INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(1, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', 'بسم الله الرحمن الرحيم', NULL, 'In the name of Allāh, the Entirely Merciful, the Especially Merciful.', 'Dengan nama Allah, Yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 4, NULL),
(1, 2, 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', 'الحمد لله رب العالمين', NULL, '[All] praise is [due] to Allāh, Lord of the worlds -', 'Segala puji tertentu bagi Allah, Tuhan yang memelihara dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 4, NULL),
(1, 3, 'ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', 'الرحمن الرحيم', NULL, 'The Entirely Merciful, the Especially Merciful,', 'Yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 2, NULL),
(1, 4, 'مَـٰلِكِ يَوْمِ ٱلدِّينِ', 'مالك يوم الدين', NULL, 'Sovereign of the Day of Recompense.', 'Yang Menguasai pemerintahan hari Pembalasan (hari Akhirat).', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 3, NULL),
(1, 5, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'اياك نعبد واياك نستعين', NULL, 'It is You we worship and You we ask for help.', 'Engkaulah sahaja (Ya Allah) Yang Kami sembah, dan kepada Engkaulah sahaja kami memohon pertolongan.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 4, NULL),
(1, 6, 'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'اهدنا الصراط المستقيم', NULL, 'Guide us to the straight path -', 'Tunjukilah kami jalan yang lurus.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 3, NULL),
(1, 7, 'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', 'صراط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين', NULL, 'The path of those upon whom You have bestowed favor, not of those who have earned [Your] anger or of those who are astray.', 'Iaitu jalan orang-orang yang Engkau telah kurniakan nikmat kepada mereka, bukan (jalan) orang-orang yang Engkau telah murkai, dan bukan pula (jalan) orang-orang yang sesat.', FALSE, NULL, NULL, 1, 1, 1, 1, FALSE, 9, NULL),
(2, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam, Miim.', FALSE, NULL, NULL, 2, 1, 1, 2, FALSE, 1, NULL),
(2, 2, 'ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ', 'ذلك الكتاب لا ريب فيه هدى للمتقين', NULL, 'This is the Book about which there is no doubt, a guidance for those conscious of Allāh -', 'Kitab Al-Quran ini, tidak ada sebarang syak padanya (tentang datangnya dari Allah dan tentang sempurnanya); ia pula menjadi petunjuk bagi orang-orang yang (hendak) bertaqwa;', FALSE, NULL, NULL, 2, 1, 1, 2, FALSE, 7, NULL),
(2, 3, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', 'الذين يؤمنون بالغيب ويقيمون الصلاة ومما رزقناهم ينفقون', NULL, 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,', 'Iaitu orang-orang yang beriman kepada perkara-perkara yang ghaib, dan mendirikan (mengerjakan) sembahyang serta membelanjakan (mendermakan) sebahagian dari rezeki yang Kami berikan kepada mereka.', FALSE, NULL, NULL, 2, 1, 1, 2, FALSE, 8, NULL),
(2, 4, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', 'والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخرة هم يوقنون', NULL, 'And who believe in what has been revealed to you, [O Muḥammad], and what was revealed before you, and of the Hereafter they are certain [in faith].', 'Dan juga orang-orang yang beriman kepada Kitab “Al-Quran” yang diturunkan kepadamu (Wahai Muhammad), dan Kitab-kitab yang diturunkan dahulu daripadamu, serta mereka yakin akan (adanya) hari akhirat (dengan sepenuhnya).', FALSE, NULL, NULL, 2, 1, 1, 2, FALSE, 12, NULL),
(2, 5, 'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'اولئك على هدى من ربهم واولئك هم المفلحون', NULL, 'Those are upon [right] guidance from their Lord, and it is those who are the successful.', 'Mereka itulah yang tetap mendapat petunjuk dari Tuhan mereka, dan merekalah orang-orang yang berjaya.', FALSE, NULL, NULL, 2, 1, 1, 2, FALSE, 8, NULL),
(2, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'ان الذين كفروا سواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون', NULL, 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.', 'Sesungguhnya orang-orang kafir (yang tidak akan beriman), sama sahaja kepada mereka: sama ada engkau beri amaran kepadanya atau engkau tidak beri amaran, mereka tidak akan beriman.', FALSE, NULL, NULL, 3, 1, 1, 2, FALSE, 11, NULL),
(2, 7, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'ختم الله على قلوبهم وعلى سمعهم وعلى ابصارهم غشاوة ولهم عذاب عظيم', NULL, 'Allāh has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.', '(Dengan sebab keingkaran mereka), Allah mematerikan atas hati mereka serta pendengaran mereka, dan pada penglihatan mereka ada penutupnya; dan bagi mereka pula disediakan azab seksa yang amat besar.', FALSE, NULL, NULL, 3, 1, 1, 2, FALSE, 12, NULL),
(2, 8, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 'ومن الناس من يقول امنا بالله وباليوم الاخر وما هم بمؤمنين', NULL, 'And of the people are some who say, "We believe in Allāh and the Last Day," but they are not believers.', 'Dan di antara manusia ada yang berkata: “Kami telah beriman kepada Allah dan kepada hari akhirat”; padahal mereka sebenarnya tidak beriman.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 11, NULL),
(2, 9, 'يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'يخادعون الله والذين امنوا وما يخدعون الا انفسهم وما يشعرون', NULL, 'They [think to] deceive Allāh and those who believe, but they deceive not except themselves and perceive [it] not.', 'Mereka hendak memperdayakan Allah dan orang-orang yang beriman, padahal mereka hanya memperdaya dirinya sendiri, sedang mereka tidak menyedarinya.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 10, NULL),
(2, 10, 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 'في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون', NULL, 'In their hearts is disease, so Allāh has increased their disease; and for them is a painful punishment because they [habitually] used to lie.', 'Dalam hati mereka (golongan yang munafik itu) terdapat penyakit (syak dan hasad dengki), maka Allah tambahkan lagi penyakit itu kepada mereka; dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya, dengan sebab mereka berdusta (dan mendustakan kebenaran).', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 12, NULL),
(2, 11, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', 'واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون', NULL, 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."', 'Dan apabila dikatakan kepada mereka: “Janganlah kamu membuat bencana dan kerosakan di muka bumi”, mereka menjawab: “Sesungguhnya kami orang-orang yang hanya membuat kebaikan”.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 11, NULL),
(2, 12, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ', 'الا انهم هم المفسدون ولكن لا يشعرون', NULL, 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.', 'Ketahuilah! Bahawa sesungguhnya mereka itulah orang-orang yang sebenar-benarnya membuat bencana dan kerosakan, tetapi mereka tidak menyedarinya.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 7, NULL),
(2, 13, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ', 'واذا قيل لهم امنوا كما امن الناس قالوا انؤمن كما امن السفهاء الا انهم هم السفهاء ولكن لا يعلمون', NULL, 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.', 'Dan apabila dikatakan kepada mereka: “Berimanlah kamu sebagaimana orang-orang itu telah beriman”. Mereka menjawab: “Patutkah kami ini beriman sebagaimana berimannya orang-orang bodoh itu?” Ketahuilah! Sesungguhnya merekalah orang-orang yang bodoh, tetapi mereka tidak mengetahui (hakikat yang sebenarnya).', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 19, NULL),
(2, 14, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَـٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', 'واذا لقوا الذين امنوا قالوا امنا واذا خلوا الى شياطينهم قالوا انا معكم انما نحن مستهزئون', NULL, 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."', 'Dan apabila mereka bertemu dengan orang-orang yang beriman, mereka berkata: “Kami telah beriman”, dan manakala mereka kembali kepada syaitan-syaitan mereka, mereka berkata pula: “Sesungguhnya kami tetap bersama kamu, sebenarnya kami hanya memperolok-olok (akan orang-orang yang beriman)”.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 16, NULL),
(2, 15, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', 'الله يستهزئ بهم ويمدهم في طغيانهم يعمهون', NULL, '[But] Allāh mocks them and prolongs them in their transgression [while] they wander blindly.', 'Allah (membalas) memperolok-olok, dan membiarkan mereka meraba-raba dalam kesesatan mereka (yang melampaui batas itu).', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 7, NULL),
(2, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', 'اولئك الذين اشتروا الضلالة بالهدى فما ربحت تجارتهم وما كانوا مهتدين', NULL, 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.', 'Mereka itulah orang-orang yang membeli kesesatan dengan meninggalkan petunjuk; maka tiadalah beruntung perniagaan mereka dan tidak pula mereka beroleh petunjuk hidayah.', FALSE, NULL, NULL, 3, 1, 1, 3, FALSE, 11, NULL),
(2, 17, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَـٰتٍ لَّا يُبْصِرُونَ', 'مثلهم كمثل الذي استوقد نارا فلما اضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون', NULL, 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allāh took away their light and left them in darkness [so] they could not see.', 'Perbandingan hal mereka (golongan yang munafik itu) samalah seperti orang yang menyalakan api; apabila api itu menerangi sekelilingnya, (tiba-tiba) Allah hilangkan cahaya (yang menerangi) mereka, dan dibiarkannya mereka dalam gelap-gelita, tidak dapat melihat (sesuatu pun).', FALSE, NULL, NULL, 4, 1, 1, 3, FALSE, 17, NULL),
(2, 18, 'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ', 'صم بكم عمي فهم لا يرجعون', NULL, 'Deaf, dumb and blind - so they will not return [to the right path].', 'Mereka (seolah-olah orang yang) pekak, bisu dan buta; dengan keadaan itu mereka tidak dapat kembali (kepada kebenaran).', FALSE, NULL, NULL, 4, 1, 1, 3, FALSE, 6, NULL),
(2, 19, 'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ', 'او كصيب من السماء فيه ظلمات ورعد وبرق يجعلون اصابعهم في اذانهم من الصواعق حذر الموت والله محيط بالكافرين', NULL, 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allāh is encompassing of the disbelievers.', 'Atau (bandingannya) seperti (orang-orang yang ditimpa) hujan lebat dari langit, bersama dengan gelap-gelita, dan guruh serta kilat; mereka menyumbat jarinya ke dalam telinga masing-masing dari mendengar suara petir, kerana mereka takut mati. (Masakan mereka boleh terlepas), sedang (pengetahuan dan kekuasaan) Allah meliputi orang-orang yang kafir itu.', FALSE, NULL, NULL, 4, 1, 1, 3, FALSE, 19, NULL),
(2, 20, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'يكاد البرق يخطف ابصارهم كلما اضاء لهم مشوا فيه واذا اظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وابصارهم ان الله على كل شيء قدير', NULL, 'The lightning almost snatches away their sight. Every time it lights [the way] for them, they walk therein; but when darkness comes over them, they stand [still]. And if Allāh had willed, He could have taken away their hearing and their sight. Indeed, Allāh is over all things competent.', 'Kilat itu pula hampir-hampir menyambar (menghilangkan) penglihatan mereka; tiap-tiap kali kilat itu menerangi mereka (dengan pancarannya), mereka berjalan dalam cahayanya. Dan apabila gelap menyelubungi mereka, berhentilah mereka (menunggu dengan bingungnya). Dan sekiranya Allah menghendaki, nescaya dihilangkanNya pendengaran dan penglihatan mereka; sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 4, 1, 1, 3, FALSE, 25, NULL),
(2, 21, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'O mankind, worship your Lord, who created you and those before you, that you may become righteous -', 'Wahai sekalian manusia! Beribadatlah kepada Tuhan kamu yang telah menciptakan kamu dan orang-orang yang terdahulu daripada kamu, supaya kamu (menjadi orang-orang yang) bertaqwa.', FALSE, NULL, NULL, 4, 1, 1, 4, FALSE, 0, NULL),
(2, 22, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', 'الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', NULL, '[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allāh equals while you know [that there is nothing similar to Him].', 'Dia lah yang menjadikan bumi ini untuk kamu sebagai hamparan, dan langit (serta segala isinya) sebagai bangunan (yang dibina dengan kukuhnya); dan diturunkanNya air hujan dari langit, lalu dikeluarkanNya dengan air itu berjenis-jenis buah-buahan yang menjadi rezeki bagi kamu; maka janganlah kamu mengadakan bagi Allah, sebarang sekutu, padahal kamu semua mengetahui (bahawa Allah ialah Tuhan Yang Maha Esa).', FALSE, NULL, NULL, 4, 1, 1, 4, FALSE, 0, NULL),
(2, 23, 'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'وَإِن كُنتُمْ فِي رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ وَادْعُوا شُهَدَاءَكُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ', NULL, 'And if you are in doubt about what We have sent down [i.e., the Qur’ān] upon Our Servant [i.e., Prophet Muḥammad (ﷺ)], then produce a sūrah the like thereof and call upon your witnesses [i.e., supporters] other than Allāh, if you should be truthful.', 'Dan kalau kamu ada menaruh syak tentang apa yang Kami turunkan (Al-Quran) kepada hamba kami (Muhammad), maka cubalah buat dan datangkanlah satu surah yang sebanding dengan Al-Quran itu, dan panggilah orang-orang yang kamu percaya boleh menolong kamu selain dari Allah, jika betul kamu orang-orang yang benar.', FALSE, NULL, NULL, 4, 1, 1, 4, FALSE, 0, NULL),
(2, 24, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ أُعِدَّتْ لِلْكَٰفِرِينَ', 'فَإِن لَّمْ تَفْعَلُوا وَلَن تَفْعَلُوا فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجَارَةُ أُعِدَّتْ لِلْكَافِرِينَ', NULL, 'But if you do not - and you will never be able to - then fear the Fire, whose fuel is people and stones, prepared for the disbelievers.', 'Maka kalau kamu tidak dapat membuatnya, dan sudah tentu kamu tidak dapat membuatnya, maka peliharalah diri kamu dari api neraka yang bahan-bahan bakarannya: manusia dan batu-batu (berhala), (iaitu neraka) yang disediakan untuk orang-orang kafir.', FALSE, NULL, NULL, 4, 1, 1, 4, FALSE, 0, NULL),
(2, 25, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَٰلِدُونَ', 'وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ كُلَّمَا رُزِقُوا مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا هَٰذَا الَّذِي رُزِقْنَا مِن قَبْلُ وَأُتُوا بِهِ مُتَشَابِهًا وَلَهُمْ فِيهَا أَزْوَاجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَالِدُونَ', NULL, 'And give good tidings to those who believe and do righteous deeds that they will have gardens [in Paradise] beneath which rivers flow. Whenever they are provided with a provision of fruit therefrom, they will say, "This is what we were provided with before." And it is given to them in likeness. And they will have therein purified spouses, and they will abide therein eternally.', 'Dan berilah khabar gembira kepada orang-orang yang beriman dan beramal soleh, sesungguhnya mereka beroleh syurga yang mengalir di bawahnya beberapa sungai; tiap-tiap kali mereka diberikan satu pemberian dari sejenis buah-buahan syurga itu, mereka berkata: “Inilah yang telah diberikan kepada kami dahulu”; dan mereka diberikan rezeki itu yang sama rupanya (tetapi berlainan hakikatnya), dan disediakan untuk mereka dalam syurga itu pasangan-pasangan, isteri-isteri yang sentiasa bersih suci, sedang mereka pula kekal di dalamnya selama-lamanya.', FALSE, NULL, NULL, 5, 1, 1, 4, FALSE, 0, NULL),
(2, 26, 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 'إِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ مَاذَا أَرَادَ اللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا وَمَا يُضِلُّ بِهِ إِلَّا الْفَاسِقِينَ', NULL, 'Indeed, Allāh is not timid to present an example - that of a mosquito or what is smaller than it. And those who have believed know that it is the truth from their Lord. But as for those who disbelieve, they say, "What did Allāh intend by this as an example?" He misleads many thereby and guides many thereby. And He misleads not except the defiantly disobedient,', 'Sesungguhnya Allah tidak malu membuat perbandingan apa sahaja, (seperti) nyamuk hingga ke suatu yang lebih daripadanya (kerana perbuatan itu ada hikmatnya), iaitu kalau orang-orang yang beriman maka mereka akan mengetahui bahawa perbandingan itu benar dari Tuhan mereka; dan kalau orang-orang kafir pula maka mereka akan berkata: “Apakah maksud Allah membuat perbandingan dengan ini?” (Jawabnya): Tuhan akan menjadikan banyak orang sesat dengan sebab perbandingan itu, dan akan menjadikan banyak orang mendapat petunjuk dengan sebabnya; dan Tuhan tidak akan menjadikan sesat dengan sebab perbandingan itu melainkan orang-orang yang fasik;', FALSE, NULL, NULL, 5, 1, 2, 4, FALSE, 0, NULL),
(2, 27, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, 'Who break the covenant of Allāh after contracting it and sever that which Allāh has ordered to be joined and cause corruption on earth. It is those who are the losers.', '(Iaitu) orang-orang yang merombak (mencabuli) perjanjian Allah sesudah diperteguhkannya, dan memutuskan perkara yang disuruh Allah supaya diperhubungkan, dan mereka pula membuat kerosakan dan bencana di muka bumi. Mereka itu ialah orang-orang yang rugi.', FALSE, NULL, NULL, 5, 1, 2, 4, FALSE, 0, NULL),
(2, 28, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمْ أَمْوَاتًا فَأَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', NULL, 'How can you disbelieve in Allāh when you were lifeless and He brought you to life; then He will cause you to die, then He will bring you [back] to life, and then to Him you will be returned.', 'Bagaimana kamu tergamak kufur (mengingkari) Allah padahal kamu dahulunya mati (belum lahir), kemudian Ia menghidupkan kamu; setelah itu Ia mematikan kamu, kemudian Ia menghidupkan kamu pula (pada hari akhirat); akhirnya kamu dikembalikan kepadaNya (untuk diberi balasan bagi segala yang kamu kerjakan).', FALSE, NULL, NULL, 5, 1, 2, 4, FALSE, 0, NULL),
(2, 29, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'هُوَ الَّذِي خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا ثُمَّ اسْتَوَىٰ إِلَى السَّمَاءِ فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'It is He who created for you all of that which is on the earth. Then He directed Himself to the heaven, [His being above all creation], and made them seven heavens, and He is Knowing of all things.', 'Dia lah (Allah) yang menjadikan untuk kamu segala yang ada di bumi, kemudian Ia menuju dengan kehendakNya ke arah (bahan-bahan) langit, lalu dijadikannya tujuh langit dengan sempurna; dan Ia Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 5, 1, 2, 4, FALSE, 0, NULL),
(2, 30, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً قَالُوا أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّي أَعْلَمُ مَا لَا تَعْلَمُونَ', NULL, 'And [mention, O Muḥammad], when your Lord said to the angels, "Indeed, I will make upon the earth a successive authority." They said, "Will You place upon it one who causes corruption therein and sheds blood, while we exalt You with praise and declare Your perfection?" He [Allāh] said, "Indeed, I know that which you do not know."', 'Dan (ingatlah) ketika Tuhanmu berfirman kepada Malaikat; “Sesungguhnya Aku hendak menjadikan seorang khalifah di bumi”. Mereka bertanya (tentang hikmat ketetapan Tuhan itu dengan berkata): “Adakah Engkau (Ya Tuhan kami) hendak menjadikan di bumi itu orang yang akan membuat bencana dan menumpahkan darah (berbunuh-bunuhan), padahal kami sentiasa bertasbih dengan memujiMu dan mensucikanMu?”. Tuhan berfirman: “Sesungguhnya Aku mengetahui akan apa yang kamu tidak mengetahuinya”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 31, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', 'وَعَلَّمَ آدَمَ الْأَسْمَاءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى الْمَلَائِكَةِ فَقَالَ أَنبِئُونِي بِأَسْمَاءِ هَٰؤُلَاءِ إِن كُنتُمْ صَادِقِينَ', NULL, 'And He taught Adam the names - all of them. Then He showed them to the angels and said, "Inform Me of the names of these, if you are truthful."', 'Dan Ia telah mengajarkan Nabi Adam, akan segala nama benda-benda dan gunanya, kemudian ditunjukkannya kepada malaikat lalu Ia berfirman: “Terangkanlah kepadaKu nama benda-benda ini semuanya jika kamu golongan yang benar”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 32, 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قَالُوا سُبْحَانَكَ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنتَ الْعَلِيمُ الْحَكِيمُ', NULL, 'They said, "Exalted are You; we have no knowledge except what You have taught us. Indeed, it is You who is the Knowing, the Wise."', 'Malaikat itu menjawab: “Maha suci Engkau (Ya Allah)! Kami tidak mempunyai pengetahuan selain dari apa yang Engkau ajarkan kepada kami; sesungguhnya Engkau jualah yang Maha Mengetahui, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 33, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 'قَالَ يَا آدَمُ أَنبِئْهُم بِأَسْمَائِهِمْ فَلَمَّا أَنبَأَهُم بِأَسْمَائِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّمَاوَاتِ وَالْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', NULL, 'He said, "O Adam, inform them of their names." And when he had informed them of their names, He said, "Did I not tell you that I know the unseen [aspects] of the heavens and the earth? And I know what you reveal and what you have concealed."', 'Allah berfirman: “Wahai Adam! Terangkanlah nama benda-benda ini semua kepada mereka”. Maka setelah Nabi Adam menerangkan nama benda-benda itu kepada mereka, Allah berfirman: “Bukankah Aku telah katakan kepada kamu, bahawasanya Aku mengetahui segala rahsia langit dan bumi, dan Aku mengetahui apa yang kamu nyatakan dan apa yang kamu sembunyikan?”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 34, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَىٰ وَاسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ', NULL, 'And [mention] when We said to the angels, "Prostrate before Adam"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers.', 'Dan (ingatlah) ketika kami berfirman kepada malaikat: “Tunduklah (beri hormat) kepada Nabi Adam”. Lalu mereka sekaliannya tunduk memberi hormat melainkan Iblis; ia enggan dan takbur, dan menjadilah ia dari golongan yang kafir.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 35, 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 'وَقُلْنَا يَا آدَمُ اسْكُنْ أَنتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ', NULL, 'And We said, "O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers."', 'Dan kami berfirman: “Wahai Adam! Tinggallah engkau dan isterimu dalam syurga, dan makanlah dari makanannya sepuas-puasnya apa sahaja kamu berdua sukai, dan janganlah kamu hampiri pokok ini; (jika kamu menghampirinya) maka akan menjadilah kamu dari golongan orang-orang yang zalim”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 36, 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'فَأَزَلَّهُمَا الشَّيْطَانُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ إِلَىٰ حِينٍ', NULL, 'But Satan caused them to slip out of it and removed them from that [condition] in which they had been. And We said, "Go down, [all of you], as enemies to one another, and you will have upon the earth a place of settlement and provision for a time."', 'Setelah itu maka Syaitan menggelincirkan mereka berdua dari syurga itu dan menyebabkan mereka dikeluarkan dari nikmat yang mereka telah berada di dalamnya dan Kami berfirman: “Turunlah kamu! Sebahagian dari kamu menjadi musuh kepada sebahagian yang lain dan bagi kamu semua disediakan tempat kediaman di bumi, serta mendapat kesenangan hingga ke suatu masa (mati)”.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'فَتَلَقَّىٰ آدَمُ مِن رَّبِّهِ كَلِمَاتٍ فَتَابَ عَلَيْهِ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ', NULL, 'Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of Repentance, the Merciful.', 'Kemudian Nabi Adam menerima dari Tuhannya beberapa kalimah (kata-kata pengakuan taubat yang diamalkannya), lalu Allah menerima taubatnya; sesungguhnya Allah, Dia lah yang Maha Pengampun (Penerima taubat), lagi Maha Mengasihani.', FALSE, NULL, NULL, 6, 1, 2, 5, FALSE, 0, NULL),
(2, 38, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'قُلْنَا اهْبِطُوا مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّي هُدًى فَمَن تَبِعَ هُدَايَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'We said, "Go down from it, all of you. And when guidance comes to you from Me, whoever follows My guidance - there will be no fear concerning them, nor will they grieve.', 'Kami berfirman lagi: “Turunlah kamu semuanya dari syurga itu! Kemudian jika datang kepada kamu petunjuk dariKu (melalui Rasul-rasul dan Kitab-kitab yang diturunkan kepada mereka), maka sesiapa yang mengikuti petunjukKu itu nescaya tidak ada kebimbangan (dari sesuatu yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita”.', FALSE, NULL, NULL, 7, 1, 2, 5, FALSE, 0, NULL),
(2, 39, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'And those who disbelieve and deny Our signs - those will be companions of the Fire; they will abide therein eternally."', 'Dan orang-orang kafir yang mendustakan ayat-ayat keterangan kami, mereka itu ialah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 7, 1, 2, 5, FALSE, 0, NULL),
(2, 40, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', 'يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا بِعَهْدِي أُوفِ بِعَهْدِكُمْ وَإِيَّايَ فَارْهَبُونِ', NULL, 'O Children of Israel, remember My favor which I have bestowed upon you and fulfill My covenant [upon you] that I will fulfill your covenant [from Me], and be afraid of [only] Me.', 'Wahai Bani Israil! Kenangkanlah kamu akan segala nikmat yang telah Kuberikan kepada kamu, dan sempurnakanlah perjanjian (kamu) denganKu, supaya Aku sempurnakan perjanjianKu dengan kamu; dan kepada Akulah sahaja hendaklah kamu merasa gerun takut, (bukan kepada sesuatu yang lain).', FALSE, NULL, NULL, 7, 1, 2, 6, FALSE, 0, NULL),
(2, 41, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', 'وَآمِنُوا بِمَا أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوا أَوَّلَ كَافِرٍ بِهِ وَلَا تَشْتَرُوا بِآيَاتِي ثَمَنًا قَلِيلًا وَإِيَّايَ فَاتَّقُونِ', NULL, 'And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me.', 'Dan berimanlah kamu dengan apa yang Aku turunkan (Al-Quran) yang mengesahkan benarnya Kitab yang ada pada kamu, dan janganlah kamu menjadi orang-orang yang mula-mula kafir (ingkar) akan dia; dan janganlah pula kamu menjadikan ayat-ayatKu (sebagai harga untuk) membeli kelebihan-kelebihan yang sedikit faedahnya; dan kepada Akulah sahaja hendaklah kamu bertaqwa.', FALSE, NULL, NULL, 7, 1, 2, 6, FALSE, 0, NULL),
(2, 42, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'وَلَا تَلْبِسُوا الْحَقَّ بِالْبَاطِلِ وَتَكْتُمُوا الْحَقَّ وَأَنتُمْ تَعْلَمُونَ', NULL, 'And do not mix the truth with falsehood or conceal the truth while you know [it].', 'Dan janganlah kamu campur adukkan yang benar itu dengan yang salah, dan kamu sembunyikan yang benar itu pula padahal kamu semua mengetahuinya.', FALSE, NULL, NULL, 7, 1, 2, 6, FALSE, 0, NULL),
(2, 43, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ', NULL, 'And establish prayer and give zakāh and bow with those who bow [in worship and obedience].', 'Dan dirikanlah kamu akan sembahyang dan keluarkanlah zakat, dan rukuklah kamu semua (berjemaah) bersama-sama orang-orang yang rukuk.', FALSE, NULL, NULL, 7, 1, 2, 6, FALSE, 0, NULL),
(2, 44, 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ أَفَلَا تَعْقِلُونَ', 'أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ الْكِتَابَ أَفَلَا تَعْقِلُونَ', NULL, 'Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason?', 'Patutkah kamu menyuruh manusia supaya berbuat kebaikan sedang kamu lupa akan diri kamu sendiri; padahal kamu semua membaca Kitab Allah, tidakkah kamu berakal?', FALSE, NULL, NULL, 7, 1, 3, 6, FALSE, 0, NULL),
(2, 45, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', 'وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ', NULL, 'And seek help through patience and prayer; and indeed, it is difficult except for the humbly submissive [to Allāh]', 'Dan mintalah pertolongan (kepada Allah) dengan jalan sabar dan mengerjakan sembahyang; dan sesungguhnya sembahyang itu amatlah berat kecuali kepada orang-orang yang khusyuk;', FALSE, NULL, NULL, 7, 1, 3, 6, FALSE, 0, NULL),
(2, 46, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', 'الَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَاقُو رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَاجِعُونَ', NULL, 'Who are certain that they will meet their Lord and that they will return to Him.', '(Iaitu) mereka yang percaya dengan yakin bahawa mereka akan menemui Tuhan mereka, dan bahawa mereka akan kembali kepadaNya.', FALSE, NULL, NULL, 7, 1, 3, 6, FALSE, 0, NULL),
(2, 47, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ', NULL, 'O Children of Israel, remember My favor that I have bestowed upon you and that I preferred you over the worlds [i.e., peoples].', 'Wahai Bani Israil! Kenangkanlah nikmat-nikmatKu yang Aku telah kurniakan kepada kamu, dan (ingatlah) bahawasanya Aku telah melebihkan (nenek-moyang) kamu (yang taat dahulu) atas orang-orang (yang ada pada zamannya).', FALSE, NULL, NULL, 7, 1, 3, 7, FALSE, 0, NULL),
(2, 48, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', 'وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا شَفَاعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', NULL, 'And fear a Day when no soul will suffice for another soul at all, nor will intercession be accepted from it, nor will compensation be taken from it, nor will they be aided.', 'Dan peliharalah diri kamu dari (azab sengsara) hari (akhirat), yang padanya seseorang tidak dapat melepaskan orang lain (yang berdosa) sedikitpun (dari balasan azab), dan tidak diterima syafaat daripadanya, dan tidak pula diambil daripadanya sebarang tebusan; dan mereka (yang bersalah itu) tidak akan diberi sebarang pertolongan.', FALSE, NULL, NULL, 7, 1, 3, 7, FALSE, 0, NULL),
(2, 49, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'وَإِذْ نَجَّيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ يُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ', NULL, 'And [recall] when We saved you [i.e., your forefathers] from the people of Pharaoh, who afflicted you with the worst torment, slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', 'Dan (kenangkanlah) ketika Kami selamatkan kamu dari Firaun dan orang-orangnya, yang sentiasa menyeksa kamu dengan seksa yang seburuk-buruknya; mereka menyembelih anak-anak lelaki kamu dan membiarkan hidup anak-anak perempuan kamu; sedang kejadian yang demikian itu mengandungi bala bencana dan cubaan yang besar dari Tuhan kamu.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 50, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', 'وَإِذْ فَرَقْنَا بِكُمُ الْبَحْرَ فَأَنجَيْنَاكُمْ وَأَغْرَقْنَا آلَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', NULL, 'And [recall] when We parted the sea for you and saved you and drowned the people of Pharaoh while you were looking on.', 'Dan (kenangkanlah) ketika kami belahkan laut (Merah) untuk kamu lalui (kerana melarikan diri dari angkara Firaun), maka Kami selamatkan kamu dan Kami tenggelamkan Firaun bersama-sama tenteranya, sedang kamu semua menyaksikannya.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 51, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'وَإِذْ وَاعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِن بَعْدِهِ وَأَنتُمْ ظَالِمُونَ', NULL, 'And [recall] when We made an appointment with Moses for forty nights. Then you took [for worship] the calf after him [i.e., his departure], while you were wrongdoers.', 'Dan (kenangkanlah) ketika kami berjanji kepada Nabi Musa (untuk memberi Taurat kepadanya sesudah ia bersiap selama) empat puluh malam. Kemudian, setelah ia pergi, kamu menyembah (patung) anak lembu, dan kamu sebenarnya orang-orang yang zalim (terhadap diri sendiri).', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 52, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'Then We forgave you after that so perhaps you would be grateful.', 'Kemudian sesudah itu kami maafkan kesalahan kamu, supaya kamu bersyukur.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 53, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', 'وَإِذْ آتَيْنَا مُوسَى الْكِتَابَ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', NULL, 'And [recall] when We gave Moses the Scripture and criterion that perhaps you would be guided.', 'Dan (kenangkanlah) ketika Kami turunkan kepada Nabi Musa kitab (Taurat) dan keterangan-keterangan (yang terkandung di dalamnya, yang membezakan antara yang benar dengan yang salah), supaya kamu mendapat petunjuk.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 54, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ يَا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِاتِّخَاذِكُمُ الْعِجْلَ فَتُوبُوا إِلَىٰ بَارِئِكُمْ فَاقْتُلُوا أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ', NULL, 'And [recall] when Moses said to his people, "O my people, indeed you have wronged yourselves by your taking of the calf [for worship]. So repent to your Creator and kill yourselves [i.e., the guilty among you]. That is best for [all of] you in the sight of your Creator." Then He accepted your repentance; indeed, He is the Accepting of Repentance, the Merciful.', 'Dan (kenangkanlah) ketika Nabi Musa berkata kepada kaumnya: “Wahai kaumku! Sesungguhnya kamu telah menganiaya diri kamu sendiri dengan sebab kamu menyembah patung anak lembu itu, maka bertaubatlah kamu kepada Allah yang menjadikan kamu; iaitu bunuhlah diri kamu. Yang demikian itu lebih baik bagi kamu di sisi Allah yang menjadikan kamu, supaya Allah menerima taubat kamu itu. Sesungguhnya Dia lah Yang Maha Pengampun (Penerima taubat), lagi Maha Mengasihani”.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 55, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', 'وَإِذْ قُلْتُمْ يَا مُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى اللَّهَ جَهْرَةً فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنتُمْ تَنظُرُونَ', NULL, 'And [recall] when you said, "O Moses, we will never believe you until we see Allāh outright"; so the thunderbolt took you while you were looking on.', 'Dan (kenangkanlah) ketika kamu berkata: “Wahai Musa! Kami tidak akan beriman kepadamu sehingga kami dapat melihat Allah dengan terang (dengan mata kepala kami)”. Maka kerana itu kamu disambar petir, sedang kamu semua melihatnya.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 56, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'ثُمَّ بَعَثْنَاكُم مِّن بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'Then We revived you after your death that perhaps you would be grateful.', 'Kemudian kami bangkitkan kamu sesudah kamu mati (atau pengsan dari sambaran petir itu), supaya kamu bersyukur.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 57, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وَظَلَّلْنَا عَلَيْكُمُ الْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'And We shaded you with clouds and sent down to you manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not - but they were [only] wronging themselves.', 'Dan Kami telah menaungi kamu dengan awan (dari panas matahari di padang pasir) dan Kami turunkan kepada kamu “Mann” dan “Salwa”, (serta Kami berfirman): “Makanlah dari makanan-makanan yang baik yang Kami telah kurniakan kepada kamu”. Dan tidaklah mereka menganiaya Kami (sebab mereka kufurkan nikmat itu), tetapi sebenarnya mereka adalah menganiaya diri sendiri.', FALSE, NULL, NULL, 8, 1, 3, 7, FALSE, 0, NULL),
(2, 58, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 'وَإِذْ قُلْنَا ادْخُلُوا هَٰذِهِ الْقَرْيَةَ فَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَادْخُلُوا الْبَابَ سُجَّدًا وَقُولُوا حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَايَاكُمْ وَسَنَزِيدُ الْمُحْسِنِينَ', NULL, 'And [recall] when We said, "Enter this city [i.e., Jerusalem] and eat from it wherever you will in [ease and] abundance, and enter the gate bowing humbly and say, ''Relieve us of our burdens [i.e., sins].'' We will [then] forgive your sins for you, and We will increase the doers of good [in goodness and reward]."', 'Dan (kenangkanlah) ketika Kami berfirman: “Masuklah kamu ke bandar ini, kemudian makanlah dari benda-benda yang ada di dalamnya dengan sepuas-puasnya, apa sahaja yang kamu sukai. Dan masuklah kamu melalui pintunya dengan tunduk (merendah diri); dan (mintalah ampun dengan) berkata: ‘Ya Allah ampunilah dosa kami’; supaya kami ampunkan kesalahan-kesalahan kamu, dan Kami akan tambah pula pahala orang-orang yang berbuat baik”.', FALSE, NULL, NULL, 9, 1, 3, 7, FALSE, 0, NULL),
(2, 59, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى الَّذِينَ ظَلَمُوا رِجْزًا مِّنَ السَّمَاءِ بِمَا كَانُوا يَفْسُقُونَ', NULL, 'But those who wronged changed [those words] to a statement other than that which had been said to them, so We sent down upon those who wronged a punishment [i.e., plague] from the sky because they were defiantly disobeying.', 'Kemudian orang-orang yang zalim (penderhaka) itu mengubah perkataan (perintah kami) yang dikatakan kepada mereka dengan melakukan sebaliknya; maka Kami turunkan ke atas orang-orang yang zalim itu bala bencana dari langit, dengan sebab mereka sentiasa berlaku fasik (menderhaka).', FALSE, NULL, NULL, 9, 1, 3, 7, FALSE, 0, NULL),
(2, 60, 'وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وَإِذِ اسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِ فَقُلْنَا اضْرِب بِّعَصَاكَ الْحَجَرَ فَانفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا وَاشْرَبُوا مِن رِّزْقِ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ', NULL, 'And [recall] when Moses prayed for water for his people, so We said, "Strike with your staff the stone." And there gushed forth from it twelve springs, and every people [i.e., tribe] knew its watering place. "Eat and drink from the provision of Allāh, and do not commit abuse on the earth, spreading corruption."', 'Dan (ingatlah) ketika Nabi Musa memohon supaya diberi air untuk kaumnya, maka Kami berfirman: “Pukullah batu itu dengan tongkatmu”, (ia pun memukulnya), lalu terpancutlah dari batu itu dua belas mata air; sesungguhnya tiap-tiap satu puak (di antara mereka) telah mengetahui tempat minumnya masing-masing. (Dan Kami berfirman): “Makanlah dan minumlah kamu dari rezeki Allah itu, dan janganlah kamu merebakkan bencana kerosakan di muka bumi”.', FALSE, NULL, NULL, 9, 1, 4, 8, FALSE, 0, NULL),
(2, 61, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'وَإِذْ قُلْتُمْ يَا مُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَاحِدٍ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنبِتُ الْأَرْضُ مِن بَقْلِهَا وَقِثَّائِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنَىٰ بِالَّذِي هُوَ خَيْرٌ اهْبِطُوا مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ', NULL, 'And [recall] when you said, "O Moses, we can never endure one [kind of] food. So call upon your Lord to bring forth for us from the earth its green herbs and its cucumbers and its garlic and its lentils and its onions." [Moses] said, "Would you exchange what is better for what is less? Go into [any] settlement and indeed, you will have what you have asked." And they were covered with humiliation and poverty and returned with anger from Allāh [upon them]. That was because they [repeatedly] disbelieved in the signs of Allāh and killed the prophets without right. That was because they disobeyed and were [habitually] transgressing.', 'Dan (kenangkanlah) ketika kamu berkata: “Wahai Musa, kami tidak sabar (sudah jemu) dengan makanan yang semacam sahaja; maka pohonkanlah kepada Tuhanmu untuk kami, supaya dikeluarkan bagi kami sebahagian dari apa yang tumbuh di bumi; dari sayur-sayurannya, dan mentimunnya, dan bawang putihnya, dan adas (kacang dalnya), serta bawang merahnya”. Nabi Musa menjawab: “Adakah kamu mahu menukar sesuatu yang kurang baik dengan meninggalkan yang lebih baik? Turunlah kamu ke bandar kerana di sana kamu boleh dapati apa yang kamu minta itu”. Dan mereka ditimpakan dengan kehinaan dan kepapaan, dan sudah sepatutnya mereka mendapat kemurkaan dari Allah. Yang demikian itu ialah disebabkan mereka kufur (mengingkari) ayat-ayat Allah (perintah-perintah dan mukjizat-mukjizat yang membuktikan kebesaranNya); dan mereka pula membunuh Nabi-nabi dengan tidak ada alasan yang benar. Yang demikian itu ialah disebabkan mereka menderhaka dan mereka pula sentiasa menceroboh.', FALSE, NULL, NULL, 9, 1, 4, 8, FALSE, 0, NULL),
(2, 62, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَىٰ وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Indeed, those who believed and those who were Jews or Christians or Sabeans [before Prophet Muḥammad (ﷺ)] - those [among them] who believed in Allāh and the Last Day and did righteousness - will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve.', 'Sesungguhnya orang-orang yang beriman, dan orang-orang Yahudi dan orang-orang Nasora (Nasrani), dan orang-orang Saabien sesiapa di antara mereka itu beriman kepada Allah dan (beriman kepada) hari akhirat serta beramal soleh, maka bagi mereka pahala balasannya di sisi Tuhan mereka, dan tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) kepada mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 63, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'And [recall] when We took your covenant, [O Children of Israel, to abide by the Torah] and We raised over you the mount, [saying], "Take what We have given you with determination and remember what is in it that perhaps you may become righteous."', 'Dan (ingatlah), ketika Kami mengambil perjanjian setia kamu semasa Kami angkatkan Gunung Tursina di atas kamu (sambil Kami berfirman): “Terimalah Taurat yang telah Kami berikan kepada kamu (serta amalkanlah) dengan bersungguh-sungguh, dan ingatlah (jangan lupakan) apa yang tersebut di dalamnya, supaya kamu bertaqwa.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 64, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 'ثُمَّ تَوَلَّيْتُم مِّن بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ لَكُنتُم مِّنَ الْخَاسِرِينَ', NULL, 'Then you turned away after that. And if not for the favor of Allāh upon you and His mercy, you would have been among the losers.', 'Kemudian sesudah itu kamu membelakangkan perjanjian setia kamu itu (tidak menyempurnakannya); maka kalau tidaklah kerana limpah kurnia Allah dan belas kasihanNya kepada kamu (dengan membuka pintu taubat), nescaya menjadilah kamu dari golongan orang-orang yang rugi.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 65, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ', NULL, 'And you had already known about those who transgressed among you concerning the sabbath, and We said to them, "Be apes, despised."', 'Dan sesungguhnya kamu telah mengetahui (bagaimana buruknya akibat) orang-orang di antara kamu yang melanggar (larangan) pada hari Sabtu, lalu Kami berfirman kepada mereka: “Jadilah kamu kera yang hina”.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 66, 'فَجَعَلْنَٰهَا نَكَٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'فَجَعَلْنَاهَا نَكَالًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', NULL, 'And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allāh.', 'Maka Kami jadikan apa yang berlaku itu sebagai suatu hukuman pencegah bagi orang-orang yang ada pada masa itu dan orang-orang yang datang kemudian, dan suatu pengajaran bagi orang-orang yang (hendak) bertaqwa.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 67, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا بَقَرَةً قَالُوا أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ', NULL, 'And [recall] when Moses said to his people, "Indeed, Allāh commands you to slaughter a cow." They said, "Do you take us in ridicule?" He said, "I seek refuge in Allāh from being among the ignorant."', 'Dan (ingatlah), ketika Nabi Musa berkata kepada kaumnya: “Sesungguhnya Allah menyuruh supaya kamu menyembelih seekor lembu betina”. Mereka berkata: “Adakah engkau hendak menjadikan kami ini permainan?” Nabi Musa menjawab: “Aku berlindung kepada Allah daripada menjadi salah seorang dari golongan yang jahil (yang melakukan sesuatu yang tidak patut)”.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 68, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌ بَيْنَ ذَٰلِكَ فَافْعَلُوا مَا تُؤْمَرُونَ', NULL, 'They said, "Call upon your Lord to make clear to us what it is." [Moses] said, "[Allāh] says, ''It is a cow which is neither old nor virgin, but median between that,'' so do what you are commanded."', 'Mereka berkata pula: “Berdoalah kepada Tuhanmu untuk kami, supaya diterangkanNya kepada kami bagaimana (sifat-sifat) lembu itu?” Nabi Musa menjawab: “Bahawasanya Allah berfirman: Bahawa (lembu betina) itu ialah seekor lembu yang tidak terlalu tua dan tidak terlalu muda, pertengahan (umurnya) di antara itu; maka kerjakanlah apa yang diperintahkan kepada kamu melakukannya”.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 69, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ النَّاظِرِينَ', NULL, 'They said, "Call upon your Lord to show us what is her color." He said, "He says, ''It is a yellow cow, bright in color - pleasing to the observers.''"', 'Mereka berkata lagi: “Pohonkanlah kepada Tuhanmu untuk kami, supaya diterangkanNya kepada kami apa warnanya?” Nabi Musa menjawab: “Bahawasanya Allah berfirman: Bahawa (lembu betina) itu ialah seekor lembu kuning, kuning tua warnanya, lagi menyukakan orang-orang yang melihatnya”.', FALSE, NULL, NULL, 10, 1, 4, 9, FALSE, 0, NULL),
(2, 70, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', 'قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ الْبَقَرَ تَشَابَهَ عَلَيْنَا وَإِنَّا إِن شَاءَ اللَّهُ لَمُهْتَدُونَ', NULL, 'They said, "Call upon your Lord to make clear to us what it is. Indeed, [all] cows look alike to us. And indeed we, if Allāh wills, will be guided."', 'Mereka berkata lagi: “Pohonkanlah kepada Tuhanmu untuk kami, supaya diterangkanNya kepada kami lembu betina yang mana satu? Kerana sesungguhnya lembu yang dikehendaki itu kesamaran kepada kami (susah kami memilihnya), dan kami insya Allah akan mendapat petunjuk (untuk mencari dan menyembelih lembu itu)”.', FALSE, NULL, NULL, 11, 1, 4, 9, FALSE, 0, NULL),
(2, 71, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 'قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلَا تَسْقِي الْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا الْآنَ جِئْتَ بِالْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا يَفْعَلُونَ', NULL, 'He said, "He says, ''It is a cow neither trained to plow the earth nor to irrigate the field, one free from fault with no spot upon her.''" They said, "Now you have come with the truth." So they slaughtered her, but they could hardly do it.', 'Nabi Musa menjawab: “Bahawasanya Allah berfirman: Sebenarnya (lembu yang dikehendaki itu) ialah lembu betina yang tidak pernah digunakan untuk membajak tanah (sawah bendang), dan tidak pula (digunakan mengangkut air) untuk menyiram tanaman; ia juga tidak cacat dan tidak ada belang pada warnanya”. Mereka berkata: “Sekarang baharulah engkau dapat menerangkan sifat-sifatnya yang sebenar”. Maka mereka pun menyembelih lembu yang tersebut, dan hampir-hampir mereka tidak dapat menunaikan (perintah Allah) itu.', FALSE, NULL, NULL, 11, 1, 4, 9, FALSE, 0, NULL),
(2, 72, 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', 'وَإِذْ قَتَلْتُمْ نَفْسًا فَادَّارَأْتُمْ فِيهَا وَاللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', NULL, 'And [recall] when you slew a man and disputed over it, but Allāh was to bring out that which you were concealing.', 'Dan (ingatlah), ketika kamu membunuh seorang manusia, kemudian kamu tuduh-menuduh sesama sendiri tentang pembunuhan itu, padahal Allah tetap melahirkan apa yang kamu sembunyikan.', FALSE, NULL, NULL, 11, 1, 4, 10, FALSE, 0, NULL),
(2, 73, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'فَقُلْنَا اضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْيِي اللَّهُ الْمَوْتَىٰ وَيُرِيكُمْ آيَاتِهِ لَعَلَّكُمْ تَعْقِلُونَ', NULL, 'So We said, "Strike him [i.e., the slain man] with part of it." Thus does Allāh bring the dead to life, and He shows you His signs that you might reason.', 'Maka Kami (Allah) berfirman: “Pukulah si mati dengan sebahagian anggota lembu yang kamu sembelih itu” (Mereka pun memukulnya dan ia kembali hidup). Demikianlah Allah menghidupkan orang-orang yang telah mati, dan memperlihatkan kepada kamu tanda-tanda kekuasaanNya, supaya kamu memahaminya.', FALSE, NULL, NULL, 11, 1, 4, 10, FALSE, 0, NULL),
(2, 74, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ثُمَّ قَسَتْ قُلُوبُكُم مِّن بَعْدِ ذَٰلِكَ فَهِيَ كَالْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ الْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ الْأَنْهَارُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْمَاءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اللَّهِ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'Then your hearts became hardened after that, being like stones or even harder. For indeed, there are stones from which rivers burst forth, and there are some of them that split open and water comes out, and there are some of them that fall down for fear of Allāh. And Allāh is not unaware of what you do.', 'Kemudian sesudah itu, hati kamu juga menjadi keras seperti batu, bahkan lebih keras lagi. Padahal di antara batu-batu itu ada yang terpancar dan mengalir air sungai daripadanya; dan ada pula di antaranya yang pecah-pecah terbelah lalu keluar mata air daripadanya; dan ada juga di antaranya yang jatuh ke bawah kerana takut kepada Allah; sedang Allah tidak sekali-kali lalai daripada apa yang kamu kerjakan.', FALSE, NULL, NULL, 11, 1, 4, 10, FALSE, 0, NULL),
(2, 75, 'أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', 'أَفَتَطْمَعُونَ أَن يُؤْمِنُوا لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَامَ اللَّهِ ثُمَّ يُحَرِّفُونَهُ مِن بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', NULL, 'Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allāh and then distort it [i.e., the Torah] after they had understood it while they were knowing?', '(Sesudah kamu - wahai Muhammad dan pengikut-pengikutmu - mengetahui tentang kerasnya hati orang-orang Yahudi itu) maka bolehkah kamu menaruh harapan bahawa mereka akan beriman kepada seruan Islam yang kamu sampaikan itu, padahal sesungguhnya telah ada satu puak dari mereka yang mendengar Kalam Allah (Taurat), kemudian mereka mengubah dan memutarkan maksudnya sesudah mereka memahaminya, sedang mereka mengetahui (bahawa perbuatan itu salah)?', FALSE, NULL, NULL, 11, 1, 5, 10, FALSE, 0, NULL),
(2, 76, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ', 'وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوا أَتُحَدِّثُونَهُم بِمَا فَتَحَ اللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم بِهِ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ', NULL, 'And when they meet those who believe, they say, "We have believed"; but when they are alone with one another, they say, "Do you talk to them about what Allāh has revealed to you so they can argue with you about it before your Lord?" Then will you not reason?', 'Dan apabila mereka (orang-orang Yahudi pada zaman Rasulullah) bertemu dengan orang-orang yang beriman, mereka berkata: “Kami telah beriman”; dan apabila mereka berjumpa sesama sendiri, mereka berkata: “Patutkah kamu ceritakan kepada mereka (orang-orang Islam) dengan apa yang telah diterangkan oleh Allah kepada kamu (di dalam Kitab Taurat mengenai kebenaran Nabi Muhammad) untuk menjadikannya hujah (bukti) yang dapat mengalahkah kamu di sisi Tuhan kamu? Tidakkah kamu berakal?”', FALSE, NULL, NULL, 11, 1, 5, 10, FALSE, 0, NULL),
(2, 77, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'أَوَلَا يَعْلَمُونَ أَنَّ اللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', NULL, 'But do they not know that Allāh knows what they conceal and what they declare?', '(Mereka berani berkata demikian) dan tidakkah mereka ketahui bahawasanya Allah mengetahui apa yang mereka rahsiakan dan apa yang mereka lahirkan?', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 78, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ الْكِتَابَ إِلَّا أَمَانِيَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', NULL, 'And among them are unlettered ones who do not know the Scripture except [indulgement in] wishful thinking, but they are only assuming.', 'Dan di antara mereka pula ada orang-orang yang buta huruf, mereka tidak mengetahui akan isi Kitab Taurat selain dari penerangan-penerangan bohong (dari ketua-ketua mereka), dan mereka hanyalah berpegang kepada sangkaan-sangkaan sahaja.', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 79, 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ اللَّهِ لِيَشْتَرُوا بِهِ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', NULL, 'So woe to those who write the "scripture" with their own hands, then say, "This is from Allāh," in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn.', 'Kecelakaan besar bagi orang-orang yang menulis Kitab Taurat dengan tangan mereka (lalu mengubah Kalam Allah dengan rekaan-rekaan mereka), kemudian mereka berkata: “Ini ialah dari sisi Allah”, supaya mereka dengan perbuatan itu dapat membeli keuntungan dunia yang sedikit. Maka kecelakaan besar bagi mereka disebabkan apa yang ditulis oleh tangan mereka, dan kecelakaan besar bagi mereka dari apa yang mereka usahakan itu.', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 80, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'وَقَالُوا لَن تَمَسَّنَا النَّارُ إِلَّا أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ اللَّهِ عَهْدًا فَلَن يُخْلِفَ اللَّهُ عَهْدَهُ أَمْ تَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'And they say, "Never will the Fire touch us, except for [a few] numbered days." Say, "Have you taken a covenant with Allāh? For Allāh will never break His covenant. Or do you say about Allāh that which you do not know?"', 'Dan mereka berkata: “Kami tidak sekali-kali akan disentuh oleh api neraka kecuali beberapa hari yang tertentu”. Katakanlah (wahai Muhammad): “Adakah kamu sudah mendapat janji dari Allah supaya (dengan itu) Allah tidak akan menyalahi janjiNya, atau hanya kamu mengatakan atas nama Allah sesuatu yang tidak kamu mengetahuinya?”', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 81, 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَاطَتْ بِهِ خَطِيئَتُهُ فَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'Yes, [on the contrary], whoever earns evil and his sin has encompassed him - those are the companions of the Fire; they will abide therein eternally.', '(Apa yang kamu katakan itu tidaklah benar), sesungguhnya sesiapa yang berbuat kejahatan dan ia diliputi (ditenggelamkan) oleh kesalahannya itu, maka merekalah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 82, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ أَصْحَابُ الْجَنَّةِ هُمْ فِيهَا خَالِدُونَ', NULL, 'But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally.', 'Dan orang-orang yang beriman serta beramal soleh, merekalah ahli syurga, mereka kekal di dalamnya.', FALSE, NULL, NULL, 12, 1, 5, 10, FALSE, 0, NULL),
(2, 83, 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 'وَإِذْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرَائِيلَ لَا تَعْبُدُونَ إِلَّا اللَّهَ وَبِالْوَالِدَيْنِ إِحْسَانًا وَذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَقُولُوا لِلنَّاسِ حُسْنًا وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', NULL, 'And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], "Do not worship except Allāh; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakāh." Then you turned away, except a few of you, and you were refusing.', 'Dan (ingatlah wahai Muhammad), ketika Kami mengikat perjanjian setia dengan Bani Israil (dengan berfirman): “Janganlah kamu menyembah melainkan Allah, dan berbuat baiklah kepada kedua ibu bapa, dan kaum kerabat, dan anak-anak yatim, serta orang-orang miskin; dan katakanlah kepada sesama manusia perkataan-perkataan yang baik; dan dirikanlah sembahyang serta berilah zakat”. Kemudian kamu berpaling membelakangkan (perjanjian setia kamu itu) kecuali sebahagian kecil dari kamu; dan sememangnya kamu orang-orang yang tidak menghiraukan perjanjian setianya.', FALSE, NULL, NULL, 12, 1, 5, 11, FALSE, 0, NULL),
(2, 84, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', 'وَإِذْ أَخَذْنَا مِيثَاقَكُمْ لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَارِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', NULL, 'And [recall] when We took your covenant, [saying], "Do not shed your [i.e., each other''s] blood or evict one another from your homes." Then you acknowledged [this] while you were witnessing.', 'Dan (ingatlah), ketika Kami mengikat perjanjian setia dengan kamu: “(Bahawa) janganlah kamu menumpahkan darah (berbunuh-bunuhan) sesama sendiri, dan janganlah kamu usir-mengusir sesama sendiri dari kampung masing-masing”. Kemudian kamu telah berikrar mematuhi perjanjian setia itu, dan kamu sendiri pula menjadi saksi (yang mengakui kebenarannya).', FALSE, NULL, NULL, 13, 1, 5, 11, FALSE, 0, NULL),
(2, 85, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'ثُمَّ أَنتُمْ هَٰؤُلَاءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَارِهِمْ تَظَاهَرُونَ عَلَيْهِم بِالْإِثْمِ وَالْعُدْوَانِ وَإِن يَأْتُوكُمْ أُسَارَىٰ تُفَادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَاءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْيٌ فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ الْقِيَامَةِ يُرَدُّونَ إِلَىٰ أَشَدِّ الْعَذَابِ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allāh is not unaware of what you do.', 'Kemudian kamu ini (wahai Bani Israil), kamu berbunuh-bunuhan sesama sendiri dan kamu usir satu puak dari kaum kamu keluar dari kampungnya; kamu pula saling bantu-membantu (dengan orang lain) untuk menentang mereka dengan melakukan dosa dan penganiayaan; padahal kalau mereka datang kepada kamu sebagai orang tawanan, kamu tebus mereka; sedang perbuatan mengusir mereka diharamkan juga atas kamu. Sesudah itu maka patutkah kamu hanya percaya kepada sebahagian (dari isi) Kitab Taurat dan mengingkari akan sebahagian yang lain? Maka tiadalah balasan bagi orang yang berbuat demikian itu dari antara kamu, selain dari kehinaan ketika hidup di dunia, dan pada hari kiamat akan ditolak mereka ke dalam azab seksa yang amat berat. Dan (ingatlah), Allah tidak sekali-kali lalai akan apa yang kamu lakukan.', FALSE, NULL, NULL, 13, 1, 5, 11, FALSE, 0, NULL),
(2, 86, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 'أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ', NULL, 'Those are the ones who have bought the life of this world [in exchange] for the Hereafter, so the punishment will not be lightened for them, nor will they be aided.', 'Mereka itulah orang-orang yang membeli (mengutamakan) kehidupan dunia (dan kesenangannya) dengan (meninggalkan perintah-perintah Allah yang membawa kebahagiaan dalam kehidupan) akhirat; maka tidak akan diringankan azab seksa mereka (pada hari kiamat), dan mereka pula tidak akan diberikan pertolongan.', FALSE, NULL, NULL, 13, 1, 5, 11, FALSE, 0, NULL),
(2, 87, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ وَقَفَّيْنَا مِن بَعْدِهِ بِالرُّسُلِ وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ أَفَكُلَّمَا جَاءَكُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُكُمُ اسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', NULL, 'And We did certainly give Moses the Scripture [i.e., the Torah] and followed up after him with messengers. And We gave Jesus, the son of Mary, clear proofs and supported him with the Pure Spirit [i.e., the angel Gabriel]. But is it [not] that every time a messenger came to you, [O Children of Israel], with what your souls did not desire, you were arrogant? And a party [of messengers] you denied and another party you killed.', 'Dan sesungguhnya Kami telah memberikan kepada Nabi Musa Kitab Taurat, dan Kami iringi kemudian daripadanya dengan beberapa orang Rasul, dan Kami berikan kepada Nabi Isa Ibni Maryam beberapa mukjizat serta Kami teguhkan kebenarannya dengan Ruhul-Qudus (Jibril). Maka patutkah, tiap-tiap kali datang kepada kamu seorang Rasul membawa sesuatu (kebenaran) yang tidak disukai oleh hawa nafsu kamu, kamu (dengan) sombong takbur (menolaknya), sehingga sebahagian dari Rasul-rasul itu kamu dustakan, dan sebahagian yang lain pula kamu membunuhnya?', FALSE, NULL, NULL, 13, 1, 5, 12, FALSE, 0, NULL),
(2, 88, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', 'وَقَالُوا قُلُوبُنَا غُلْفٌ بَل لَّعَنَهُمُ اللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', NULL, 'And they said, "Our hearts are wrapped." But, [in fact], Allāh has cursed them for their disbelief, so little is it that they believe.', 'Dan mereka (kaum Yahudi) berkata pula: “Hati kami tertutup (tidak dapat menerima Islam)”. (Sebenarnya hati mereka tidak tertutup) bahkan Allah telah melaknatkan mereka disebabkan kekufuran mereka, oleh itu maka sedikit benar mereka yang beriman.', FALSE, NULL, NULL, 13, 1, 5, 12, FALSE, 0, NULL),
(2, 89, 'وَلَمَّا جَآءَهُمْ كِتَٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 'وَلَمَّا جَاءَهُمْ كِتَابٌ مِّنْ عِندِ اللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُم مَّا عَرَفُوا كَفَرُوا بِهِ فَلَعْنَةُ اللَّهِ عَلَى الْكَافِرِينَ', NULL, 'And when there came to them a Book [i.e., the Qur’ān] from Allāh confirming that which was with them - although before they used to pray for victory against those who disbelieved - but [then] when there came to them that which they recognized, they disbelieved in it; so the curse of Allāh will be upon the disbelievers.', 'Dan ketika datang kepada mereka sebuah Kitab dari Allah (Al Quran), yang mengesahkan apa yang ada pada mereka (Kitab Taurat), sedang mereka sebelum itu sentiasa memohon (kepada Allah) kemenangan atas kaum kafir musyrik (dengan kedatangan seorang Nabi pembawa Kitab itu). Setelah datang kepada mereka apa yang mereka sedia mengetahui kebenarannya (Nabi Muhammad dan Al Quran), mereka mengingkarinya; maka (dengan yang demikian), laknat Allah menimpa orang-orang yang kafir ingkar itu.', FALSE, NULL, NULL, 14, 1, 5, 12, FALSE, 0, NULL),
(2, 90, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'بِئْسَمَا اشْتَرَوْا بِهِ أَنفُسَهُمْ أَن يَكْفُرُوا بِمَا أَنزَلَ اللَّهُ بَغْيًا أَن يُنَزِّلَ اللَّهُ مِن فَضْلِهِ عَلَىٰ مَن يَشَاءُ مِنْ عِبَادِهِ فَبَاءُوا بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَافِرِينَ عَذَابٌ مُّهِينٌ', NULL, 'How wretched is that for which they sold themselves - that they would disbelieve in what Allāh has revealed through [their] outrage that Allāh would send down His favor upon whom He wills from among His servants. So they returned having [earned] wrath upon wrath. And for the disbelievers is a humiliating punishment.', 'Sejahat-jahat perkara (yang mereka lakukan) ialah perbuatan mereka membeli kesenangan dirinya sendiri dengan mengingkari Al-Quran yang telah diturunkan oleh Allah, kerana dengki bahawa Allah menurunkan dari limpah kurniaNya (wahyu) kepada sesiapa yang dikehendakiNya di antara hamba-hambaNya (iaitu Nabi Muhammad s.a.w). Dengan sebab itu sudah sepatutnya mereka mendapat kemurkaan Allah bertalu-talu, dan orang-orang yang kafir itu akan beroleh azab sengsara yang menghinakan.', FALSE, NULL, NULL, 14, 1, 5, 12, FALSE, 0, NULL),
(2, 91, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', 'وَإِذَا قِيلَ لَهُمْ آمِنُوا بِمَا أَنزَلَ اللَّهُ قَالُوا نُؤْمِنُ بِمَا أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَاءَهُ وَهُوَ الْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنبِيَاءَ اللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'And when it is said to them, "Believe in what Allāh has revealed," they say, "We believe [only] in what was revealed to us." And they disbelieve in what came after it, while it is the truth confirming that which is with them. Say, "Then why did you kill the prophets of Allāh before, if you are [indeed] believers?"', 'Dan apabila dikatakan kepada mereka: “Berimanlah kamu kepada apa yang telah diturunkan oleh Allah (kepada Nabi Muhammad)”, mereka menjawab: “Kami hanya beriman kepada apa yang telah diturunkan kepada kami (Taurat)”. Dan mereka ingkarkan (Kitab) yang lain yang diturunkan kemudian daripadanya, padahal Al-Quran itu benar lagi mengesahkan Kitab Taurat yang ada pada mereka. Katakanlah (wahai Muhammad): “Jika demikian mengapa kamu membunuh Nabi-nabi Allah pada masa yang lalu kalaulah kamu benar-benar orang-orang yang beriman?”.', FALSE, NULL, NULL, 14, 1, 5, 12, FALSE, 0, NULL),
(2, 92, 'وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'وَلَقَدْ جَاءَكُم مُّوسَىٰ بِالْبَيِّنَاتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِن بَعْدِهِ وَأَنتُمْ ظَالِمُونَ', NULL, 'And Moses had certainly brought you clear proofs. Then you took the calf [in worship] after that, while you were wrongdoers.', 'Dan sesungguhnya telah datang kepada kamu Nabi Musa membawa keterangan-keterangan (mukjizat) kemudian kamu menyembah (patung) anak lembu sepeninggalannya, dan kamu (dengan perbuatan itu) adalah orang-orang yang zalim.', FALSE, NULL, NULL, 14, 1, 6, 12, FALSE, 0, NULL),
(2, 93, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِ إِيمَانُكُمْ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'And [recall] when We took your covenant and raised over you the mount, [saying], "Take what We have given you with determination and listen." They said [instead], "We hear and disobey." And their hearts absorbed [the worship of] the calf because of their disbelief. Say, "How wretched is that which your faith enjoins upon you, if you should be believers."', 'Dan (ingatlah) ketika Kami mengikat perjanjian setia dengan kamu semasa Kami angkatkan bukit Tursina itu ke atas kamu (sambil kami berfirman): “Ambilah (dan amalkanlah ajaran Kitab Taurat) yang Kami berikan kepada kamu itu dengan bersungguh-sungguh, dan dengarlah (apa yang diperintahkan kepada kamu dengan mematuhinya)”. Mereka menjawab: “Kami dengar, dan kami menderhaka”. Sedang kegemaran menyembah (patung) anak lembu itu telah mesra dan sebati di dalam hati mereka, dengan sebab kekufuran mereka. Katakanlah (wahai Muhammad): “Amatlah jahatnya apa yang disuruh oleh iman kamu itu kalaulah kamu orang-orang yang beriman”.', FALSE, NULL, NULL, 14, 1, 6, 12, FALSE, 0, NULL),
(2, 94, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'قُلْ إِن كَانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِندَ اللَّهِ خَالِصَةً مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ', NULL, 'Say, [O Muḥammad], "If the home of the Hereafter with Allāh is for you alone and not the [other] people, then wish for death, if you should be truthful."', 'Katakanlah (wahai Muhammad kepada kaum Yahudi): “Kalau syurga negeri akhirat itu telah menjadi hak istimewa untuk kamu pada sisi hukum Allah, tidak boleh dicampuri oleh orang-orang lain (seperti yang kamu dakwakan itu), maka cita-citakanlah mati (supaya kamu dimatikan sekarang juga), jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 15, 1, 6, 12, FALSE, 0, NULL),
(2, 95, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'وَلَن يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ', NULL, 'But never will they wish for it, ever, because of what their hands have put forth. And Allāh is Knowing of the wrongdoers.', 'Dan sudah tentu mereka tidak akan mencita-citakan mati itu selama-lamanya, dengan sebab dosa-dosa yang telah mereka lakukan; dan Allah sentiasa mengetahui akan orang-orang yang zalim itu.', FALSE, NULL, NULL, 15, 1, 6, 12, FALSE, 0, NULL),
(2, 96, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلَىٰ حَيَاةٍ وَمِنَ الَّذِينَ أَشْرَكُوا يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِ مِنَ الْعَذَابِ أَن يُعَمَّرَ وَاللَّهُ بَصِيرٌ بِمَا يَعْمَلُونَ', NULL, 'And you will surely find them the most greedy of people for life - [even] more than those who associate others with Allāh. One of them wishes that he could be granted life a thousand years, but it would not remove him in the least from the [coming] punishment that he should be granted life. And Allāh is Seeing of what they do.', 'Demi sesungguhnya engkau (wahai Muhammad) akan dapati mereka itu setamak-tamak manusia kepada hidup (yang lanjut masanya), dan (lobanya mereka kepada hidup itu) melebihi loba orang-orang kafir musyrik. Tiap-tiap seorang dari mereka suka kiranya ia boleh hidup seribu tahun, padahal umur panjang yang demikian, tidak akan dapat melepaskannya dari azab (yang disediakan oleh Allah). Dan (ingatlah), Allah sentiasa melihat akan apa yang mereka lakukan.', FALSE, NULL, NULL, 15, 1, 6, 12, FALSE, 0, NULL),
(2, 97, 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَىٰ قَلْبِكَ بِإِذْنِ اللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', NULL, 'Say, "Whoever is an enemy to Gabriel - it is [none but] he who has brought it [i.e., the Qur’ān] down upon your heart, [O Muḥammad], by permission of Allāh, confirming that which was before it and as guidance and good tidings for the believers."', 'Katakanlah (wahai Muhammad): “Sesiapa memusuhi Jibril maka sebabnya ialah kerana Jibril itu menurunkan Al-Quran ke dalam hatimu dengan izin Allah, yang mengesahkan kebenaran Kitab-kitab yang ada di hadapannya (yang diturunkan sebelumnya), serta menjadi petunjuk dan memberi khabar gembira kepada orang-orang yang beriman”.', FALSE, NULL, NULL, 15, 1, 6, 13, FALSE, 0, NULL),
(2, 98, 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَٰفِرِينَ', 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ فَإِنَّ اللَّهَ عَدُوٌّ لِّلْكَافِرِينَ', NULL, 'Whoever is an enemy to Allāh and His angels and His messengers and Gabriel and Michael - then indeed, Allāh is an enemy to the disbelievers.', 'Sesiapa memusuhi Allah (dengan mengingkari segala petunjuk dan perintahNya) dan memusuhi Malaikat-malaikatNya dan Rasul-rasulNya, khasnya malaikat Jibril dan Mikail, (maka ia akan diseksa oleh Allah) kerana sesungguhnya Allah adalah musuh bagi orang-orang kafir.', FALSE, NULL, NULL, 15, 1, 6, 13, FALSE, 0, NULL),
(2, 99, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', 'وَلَقَدْ أَنزَلْنَا إِلَيْكَ آيَاتٍ بَيِّنَاتٍ وَمَا يَكْفُرُ بِهَا إِلَّا الْفَاسِقُونَ', NULL, 'And We have certainly revealed to you verses [which are] clear proofs, and no one would deny them except the defiantly disobedient.', 'Dan sesungguhnya Kami telah menurunkan kepadamu (wahai Muhammad) ayat-ayat keterangan yang jelas nyata (Al-Quran), dan tidak ada yang akan mengingkarinya melainkan orang-orang yang fasik.', FALSE, NULL, NULL, 15, 1, 6, 13, FALSE, 0, NULL),
(2, 100, 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'أَوَكُلَّمَا عَاهَدُوا عَهْدًا نَّبَذَهُ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', NULL, 'Is it not [true] that every time they took a covenant a party of them threw it away? But, [in fact], most of them do not believe.', 'Patutkah (mereka ingkarkan ayat-ayat keterangan itu) dan patutkah tiap-tiap kali mereka mengikat perjanjian setia, dibuang dan dicabuli oleh segolongan dari mereka? Bahkan kebanyakan mereka tidak beriman.', FALSE, NULL, NULL, 15, 1, 6, 13, FALSE, 0, NULL),
(2, 101, 'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 'وَلَمَّا جَاءَهُمْ رَسُولٌ مِّنْ عِندِ اللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ كِتَابَ اللَّهِ وَرَاءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', NULL, 'And when a messenger from Allāh came to them confirming that which was with them, a party of those who had been given the Scripture threw the Scripture of Allāh [i.e., the Torah] behind their backs as if they did not know [what it contained].', 'Dan apabila datang kepada mereka seorang Rasul dari sisi Allah (Nabi Muhammad s.a.w), yang mengesahkan apa yang ada pada mereka, sebahagian dari orang-orang yang telah diberikan Kitab itu melemparkan Kitab Allah ke belakang mereka, seolah-olah mereka tidak mengetahui (kebenarannya).', FALSE, NULL, NULL, 15, 1, 6, 13, FALSE, 0, NULL),
(2, 102, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُوا۟ يَعْلَمُونَ', 'وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Hārūt and Mārūt. But they [i.e., the two angels] do not teach anyone unless they say, "We are a trial, so do not disbelieve [by practicing magic]." And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allāh. And they [i.e., people] learn what harms them and does not benefit them. But they [i.e., the Children of Israel] certainly knew that whoever purchased it [i.e., magic] would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew.', 'Mereka (membelakangkan Kitab Allah) dan mengikut ajaran-ajaran sihir yang dibacakan oleh puak-puak Syaitan dalam masa pemerintahan Nabi Sulaiman, padahal Nabi Sulaiman tidak mengamalkan sihir yang menyebabkan kekufuran itu, akan tetapi puak-puak Syaitan itulah yang kafir (dengan amalan sihirnya); kerana merekalah yang mengajarkan manusia ilmu sihir dan apa yang diturunkan kepada dua malaikat: Harut dan Marut, di negeri Babil (Babylon), sedang mereka berdua tidak mengajar seseorang pun melainkan setelah mereka menasihatinya dengan berkata: “Sesungguhnya kami ini hanyalah cubaan (untuk menguji imanmu), oleh itu janganlah engkau menjadi kafir (dengan mempelajarinya)”. Dalam pada itu ada juga orang-orang mempelajari dari mereka berdua: ilmu sihir yang boleh menceraikan antara seorang suami dengan isterinya, padahal mereka tidak akan dapat sama sekali memberi mudarat (atau membahayakan) dengan sihir itu seseorang pun melainkan dengan izin Allah. Dan sebenarnya mereka mempelajari perkara yang hanya membahayakan mereka dan tidak memberi manfaat kepada mereka. Dan demi sesungguhnya mereka (kaum Yahudi itu) telahpun mengetahui bahawa sesiapa yang memilih ilmu sihir itu tidaklah lagi mendapat bahagian yang baik di akhirat. Demi sesungguhnya amat buruknya apa yang mereka pilih untuk diri mereka, kalaulah mereka mengetahui.', FALSE, NULL, NULL, 16, 1, 6, 13, FALSE, 0, NULL),
(2, 103, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ لَّوْ كَانُوا۟ يَعْلَمُونَ', 'وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِّنْ عِندِ اللَّهِ خَيْرٌ لَّوْ كَانُوا يَعْلَمُونَ', NULL, 'And if they had believed and feared Allāh, then the reward from Allāh would have been [far] better, if they only knew.', 'Dan kalau sebenarnya mereka itu tetap beriman dan bertaqwa (nescaya mereka akan mendapat pahala); sesungguhnya pahala dari sisi Allah itu adalah lebih baik, kalau mereka mengetahui.', FALSE, NULL, NULL, 16, 1, 6, 13, FALSE, 0, NULL),
(2, 104, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقُولُوا رَاعِنَا وَقُولُوا انظُرْنَا وَاسْمَعُوا وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ', NULL, 'O you who have believed, say not [to Allāh''s Messenger], "Rāʿinā" but say, "Unẓurnā" and listen. And for the disbelievers is a painful punishment.', 'Wahai orang-orang yang beriman! Janganlah kamu mengatakan: “raaina”, (ketika kamu berkata-kata dengan Nabi Muhammad), sebaliknya katakanlah: “unzurna”, dan dengarlah kamu (segala perintah dengan sebulat hati menerimanya); dan (ingatlah, bahawa) orang-orang kafir itu akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 16, 1, 6, 14, FALSE, 0, NULL),
(2, 105, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'مَّا يَوَدُّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَلَا الْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَاللَّهُ يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ', NULL, 'Neither those who disbelieve from the People of the Scripture [i.e., the Jews and Christians] nor the polytheists wish that any good should be sent down to you from your Lord. But Allāh selects for His mercy whom He wills, and Allāh is the possessor of great bounty.', 'Orang-orang kafir dari Ahli kitab, dan juga dari orang-orang musyrik, tidak suka kiranya diturunkan kepada kamu sedikit dari kebaikan (atau wahyu) dari Tuhan kamu Padahal Allah berhak menentukan rahmatNya kepada sesiapa yang dikehendakiNya; dan Allah (jualah Yang) mempunyai limpah kurnia yang amat besar.', FALSE, NULL, NULL, 16, 1, 6, 14, FALSE, 0, NULL),
(2, 106, 'مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'مَا نَنسَخْ مِنْ آيَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَا أَوْ مِثْلِهَا أَلَمْ تَعْلَمْ أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'We do not abrogate a verse or cause it to be forgotten except that We bring forth [one] better than it or similar to it. Do you not know that Allāh is over all things competent?', 'Apa sahaja ayat keterangan yang Kami mansukhkan (batalkan), atau yang Kami tinggalkan (atau tangguhkan), Kami datangkan ganti yang lebih baik daripadanya, atau yang sebanding dengannya. Tidakkah engkau mengetahui bahawasanya Allah Maha Kuasa atas tiap-tiap sesuatu?', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 107, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'Do you not know that to Allāh belongs the dominion of the heavens and the earth and [that] you have not besides Allāh any protector or any helper?', 'Tidakkah engkau mengetahui bahawa sesungguhnya Allah Yang Menguasai segala alam langit dan bumi? Dan tiadalah bagi kamu selain Allah sesiapapun yang dapat melindungi dan yang dapat memberi pertolongan.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 108, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'أَمْ تُرِيدُونَ أَن تَسْأَلُوا رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ الْكُفْرَ بِالْإِيمَانِ فَقَدْ ضَلَّ سَوَاءَ السَّبِيلِ', NULL, 'Or do you intend to ask your Messenger as Moses was asked before? And whoever exchanges faith for disbelief has certainly strayed from the soundness of the way.', 'Adakah kamu pula hendak meminta dari Rasul kamu sebagaimana diminta dari Nabi Musa (oleh kaumnya) dahulu? Dan sesiapa yang menukar iman dengan mengambil kekufuran, maka sesungguhnya ia telah sesat dari jalan yang lurus.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 109, 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُم مِّن بَعْدِ إِيمَانِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّ فَاعْفُوا وَاصْفَحُوا حَتَّىٰ يَأْتِيَ اللَّهُ بِأَمْرِهِ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Many of the People of the Scripture wish they could turn you back to disbelief after you have believed, out of envy from themselves [even] after the truth has become clear to them. So pardon and overlook until Allāh delivers His command. Indeed, Allāh is over all things competent.', 'Banyak di antara Ahli kitab (Yahudi dan Nasrani) suka kalaulah kiranya mereka dapat mengembalikan kamu menjadi kafir setelah kamu beriman, kerana dengki yang timbul dari diri mereka sendiri, sesudah nyata kepada mereka kebenaran (Nabi Muhammad s.a.w). Oleh itu, maafkanlah dan biarkanlah oleh kamu (akan mereka), sehingga Allah datangkan perintahNya. Sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 110, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'And establish prayer and give zakāh, and whatever good you put forward for yourselves - you will find it with Allāh. Indeed Allāh, of what you do, is Seeing.', 'Dan dirikanlah oleh kamu akan sembahyang dan tunaikanlah zakat dan apa jua yang kamu dahulukan dari kebaikan untuk diri kamu, tentulah kamu akan mendapat balasan pahalanya di sisi Allah. Sesungguhnya Allah sentiasa Melihat segala yang kamu kerjakan.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 111, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'وَقَالُوا لَن يَدْخُلَ الْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَارَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا بُرْهَانَكُمْ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "None will enter Paradise except one who is a Jew or a Christian." That is [merely] their wishful thinking. Say, "Produce your proof, if you should be truthful."', 'Dan mereka (Yahudi dan Nasrani) berkata pula: “Tidak sekali-kali akan masuk Syurga melainkan orang-orang yang berugama Yahudi atau Nasrani”. Yang demikian itu hanyalah angan-angan mereka sahaja. Katakanlah (wahai Muhammad): “Bawalah kemari keterangan-keterangan yang (membuktikan kebenaran) apa yang kamu katakan itu, jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 112, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُ أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Yes, [on the contrary], whoever submits his face [i.e., self] in Islām to Allāh while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve.', '(Apa yang kamu katakan itu tidaklah benar) bahkan sesiapa yang menyerahkan dirinya kepada Allah (mematuhi perintahNya) sedang ia pula berusaha supaya baik amalannya, maka ia akan beroleh pahalanya di sisi Tuhannya dan tidaklah ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 17, 1, 7, 14, FALSE, 0, NULL),
(2, 113, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'وَقَالَتِ الْيَهُودُ لَيْسَتِ النَّصَارَىٰ عَلَىٰ شَيْءٍ وَقَالَتِ النَّصَارَىٰ لَيْسَتِ الْيَهُودُ عَلَىٰ شَيْءٍ وَهُمْ يَتْلُونَ الْكِتَابَ كَذَٰلِكَ قَالَ الَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ', NULL, 'The Jews say, "The Christians have nothing [true] to stand on," and the Christians say, "The Jews have nothing to stand on," although they [both] recite the Scripture. Thus do those who know not [i.e., the polytheists] speak the same as their words. But Allāh will judge between them on the Day of Resurrection concerning that over which they used to differ.', 'Dan orang-orang Yahudi berkata: “Orang-orang Nasrani itu tidak mempunyai sesuatu pegangan (ugama yang benar)”; dan orang-orang Nasrani pula berkata: “Orang-orang Yahudi tidak mempunyai sesuatu pegangan (ugama yang benar)”; padahal mereka membaca Kitab Suci masing-masing (Taurat dan Injil). Demikian juga orang-orang (musyrik dari kaum Jahiliyah) yang tidak berilmu pengetahuan, mengatakan seperti yang dikatakan oleh mereka itu. Maka Allah akan menghukum (mengadili) di antara mereka pada hari kiamat mengenai apa yang mereka berselisihan padanya.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 114, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَاجِدَ اللَّهِ أَن يُذْكَرَ فِيهَا اسْمُهُ وَسَعَىٰ فِي خَرَابِهَا أُولَٰئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَا إِلَّا خَائِفِينَ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ', NULL, 'And who are more unjust than those who prevent the name of Allāh from being mentioned [i.e., praised] in His mosques and strive toward their destruction. It is not for them to enter them except in fear. For them in this world is disgrace, and they will have in the Hereafter a great punishment.', 'Dan siapakah yang lebih zalim daripada orang-orang yang menyekat dan menghalangi dari menggunakan masjid-masjid Allah untuk (sembahyang dan) menyebut nama Allah di dalamnya, dan ia berusaha pula untuk meruntuhkan masjid-masjid itu? Orang-orang yang demikian, tidak sepatunya masuk ke dalam masjid-masjid itu melainkan dengan rasa penuh hormat dan takut kepada Allah (bukan secara yang mereka lakukan itu). Mereka (dengan perbuatan itu) akan beroleh kehinaan di dunia, dan di akhirat kelak mereka mendapat azab seksa yang amat besar.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 115, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ', 'وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ إِنَّ اللَّهَ وَاسِعٌ عَلِيمٌ', NULL, 'And to Allāh belongs the east and the west. So wherever you [might] turn, there is the Face of Allāh. Indeed, Allāh is all-Encompassing and Knowing.', 'Dan Allah jualah yang memiliki timur dan barat, maka ke mana sahaja kamu arahkan diri (ke kiblat untuk mengadap Allah) maka di situlah arah yang diredhai Allah; sesungguhnya Allah Maha Luas (rahmatNya dan limpah kurniaNya), lagi sentiasa Mengetahui.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 116, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا سُبْحَانَهُ بَل لَّهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ كُلٌّ لَّهُ قَانِتُونَ', NULL, 'They say, "Allāh has taken a son." Exalted is He! Rather, to Him belongs whatever is in the heavens and the earth. All are devoutly obedient to Him,', 'Dan mereka (orang-orang musyrik) berkata: “Allah mempunyai anak”. Maha Suci Allah (dari apa yang mereka katakan itu), bahkan Dia lah Yang memiliki segala yang di langit dan di bumi, semuanya itu tunduk di bawah kekuasaanNya.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 117, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ وَإِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ', NULL, 'Originator of the heavens and the earth. When He decrees a matter, He only says to it, "Be," and it is.', 'Allah jualah yang menciptakan langit dan bumi (dengan segala keindahannya); dan apabila Ia berkehendak (untuk menjadikan) suatu, maka Ia hanya berfirman kepadanya: “Jadilah engkau!” Lalu menjadilah ia.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 118, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَٰبَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا ٱلْـَٔايَٰتِ لِقَوْمٍ يُوقِنُونَ', 'وَقَالَ الَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا اللَّهُ أَوْ تَأْتِينَا آيَةٌ كَذَٰلِكَ قَالَ الَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَابَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا الْآيَاتِ لِقَوْمٍ يُوقِنُونَ', NULL, 'Those who do not know say, "Why does Allāh not speak to us or there come to us a sign?" Thus spoke those before them like their words. Their hearts resemble each other. We have shown clearly the signs to a people who are certain [in faith].', 'Dan (orang-orang musyrik) yang tidak berilmu pengetahuan, berkata: “Alangkah eloknya kalau Allah berkata-kata dengan kami (mengenai kebenaran Muhammad) atau datang kepada kami sesuatu keterangan (mukjizat)?” Demikian pula orang-orang (kafir) yang terdahulu dari mereka pernah berkata seperti yang dikatakan oleh mereka; hati mereka (sekaliannya) adalah bersamaan (degil dan kufur). Sesungguhnya Kami telah pun menerangkan ayat-ayat keterangan (yang menjadi dalil dan bukti) kepada kaum yang mahu percaya dengan yakin.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 119, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', 'إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ', NULL, 'Indeed, We have sent you, [O Muḥammad], with the truth as a bringer of good tidings and a warner, and you will not be asked about the companions of Hellfire.', 'Sesungguhnya Kami telah mengutuskan engkau (wahai Muhammad) dengan kebenaran, (serta menjadi) pembawa khabar gembira (kepada orang-orang yang beriman) dan pembawa amaran (kepada orang-orang yang ingkar). Dan (setelah engkau sampaikan semuanya itu), engkau tidak akan diminta (bertanggungjawab) tentang ahli neraka.', FALSE, NULL, NULL, 18, 1, 7, 15, FALSE, 0, NULL),
(2, 120, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'وَلَن تَرْضَىٰ عَنكَ الْيَهُودُ وَلَا النَّصَارَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَىٰ وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم بَعْدَ الَّذِي جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'And never will the Jews and the Christians approve of you until you follow their religion. Say, "Indeed, the guidance of Allāh is the [only] guidance." If you were to follow their desires after what has come to you of knowledge, you would have against Allāh no protector or helper.', 'Orang-orang Yahudi dan Nasrani tidak sekali-kali akan bersetuju atau suka kepadamu (wahai Muhammad) sehingga engkau menurut ugama mereka (yang telah terpesong itu). Katakanlah (kepada mereka): “Sesungguhnya petunjuk Allah (ugama Islam itulah petunjuk yang benar”. Dan demi sesungguhnya jika engkau menurut kehendak hawa nafsu mereka sesudah datangnya (wahyu yang memberi) pengetahuan kepadamu (tentang kebenaran), maka tiadalah engkau akan peroleh dari Allah (sesuatupun) yang dapat mengawal dan memberi pertolongan kepada mu.', FALSE, NULL, NULL, 19, 1, 7, 15, FALSE, 0, NULL),
(2, 121, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَتْلُونَهُ حَقَّ تِلَاوَتِهِ أُولَٰئِكَ يُؤْمِنُونَ بِهِ وَمَن يَكْفُرْ بِهِ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, 'Those to whom We have given the Book recite it with its true recital. They [are the ones who] believe in it. And whoever disbelieves in it - it is they who are the losers.', 'Orang-orang yang Kami berikan Kitab kepada mereka, sedang mereka membacanya dengan sebenar-benar bacaan (tidak mengubah dan memutarkan maksudnya), mereka itulah orang-orang yang beriman kepadanya; dan sesiapa yang mengingkarinya maka mereka itulah orang-orang yang rugi.', FALSE, NULL, NULL, 19, 1, 7, 15, FALSE, 0, NULL),
(2, 122, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ', NULL, 'O Children of Israel, remember My favor which I have bestowed upon you and that I preferred you over the worlds.', 'Wahai Bani Israil, kenanglah akan limpah kurnia nikmatKu yang telah Kuberikan kepada kamu, dan Aku telah melebihkan (datuk nenek) kamu (yang taat dahulu) atas umat-umat yang lain (yang ada pada zamannya).', FALSE, NULL, NULL, 19, 1, 7, 16, FALSE, 0, NULL),
(2, 123, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَٰعَةٌ وَلَا هُمْ يُنصَرُونَ', 'وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنصَرُونَ', NULL, 'And fear a Day when no soul will suffice for another soul at all, and no compensation will be accepted from it, nor will any intercession benefit it, nor will they be aided.', 'Dan peliharalah diri kamu dari (huru-hara) hari kiamat (yang padanya) seseorang tidak dapat mengganti atau melepaskan orang lain sedikitpun, dan tidak akan diterima daripadanya sebarang tebusan, dan tidak akan memberi manfaat kepadanya sebarang syafaat; dan orang-orang yang salah itu tidak akan ditolong (dari azab sengsara).', FALSE, NULL, NULL, 19, 1, 7, 16, FALSE, 0, NULL),
(2, 124, 'وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٍ فَأَتَمَّهُنَّ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِى قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', 'وَإِذِ ابْتَلَىٰ إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِي قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ', NULL, 'And [mention, O Muḥammad], when Abraham was tried by his Lord with words [i.e., commands] and he fulfilled them. [Allāh] said, "Indeed, I will make you a leader for the people." [Abraham] said, "And of my descendants?" [Allāh] said, "My covenant does not include the wrongdoers."', 'Dan (ingatlah), ketika Nabi Ibrahim diuji oleh Tuhannya dengan beberapa Kalimah (suruhan dan larangan), maka Nabi Ibrahim pun menyempurnakannya. (Setelah itu) Allah berfirman: “Sesungguhnya Aku melantikmu menjadi Imam (Pemimpin ikutan) bagi umat manusia”. Nabi Ibrahim pun memohon dengan berkata: “(Ya Tuhanku!) Jadikanlah juga (apalah jua kiranya) dari keturunanku (pemimpin-pemimpin ikutan)”. Allah berfirman: “(Permohonanmu diterima, tetapi) janjiKu ini tidak akan didapati oleh orang-orang yang zalim.”', FALSE, NULL, NULL, 19, 1, 8, 16, FALSE, 0, NULL),
(2, 125, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى وَعَهِدْنَا إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ أَن طَهِّرَا بَيْتِيَ لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ', NULL, 'And [mention] when We made the House [i.e., the Kaʿbah] a place of return for the people and [a place of] security. And take, [O believers], from the standing place of Abraham a place of prayer. And We charged Abraham and Ishmael, [saying], "Purify My House for those who perform ṭawāf and those who are staying [there] for worship and those who bow and prostrate [in prayer]."', 'Dan (ingatlah) ketika Kami jadikan Rumah Suci (Baitullah) itu tempat tumpuan bagi umat manusia (untuk Ibadat Haji) dan tempat yang aman; dan jadikanlah oleh Kamu Makam Ibrahim itu tempat sembahyang. Dan Kami perintahkan kepada Nabi Ibrahim dan Nabi Ismail (dengan berfirman): “Bersihkanlah Rumahku (Kaabah dan Masjid Al-Haraam dari segala perkara yang dilarang) untuk orang-orang yang bertawaf, dan orang-orang yang beriktikaf (yang tetap tinggal padanya), dan orang-orang yang rukuk dan sujud”.', FALSE, NULL, NULL, 19, 1, 8, 16, FALSE, 0, NULL),
(2, 126, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ وَبِئْسَ ٱلْمَصِيرُ', 'وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَٰذَا بَلَدًا آمِنًا وَارْزُقْ أَهْلَهُ مِنَ الثَّمَرَاتِ مَنْ آمَنَ مِنْهُم بِاللَّهِ وَالْيَوْمِ الْآخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُ قَلِيلًا ثُمَّ أَضْطَرُّهُ إِلَىٰ عَذَابِ النَّارِ وَبِئْسَ الْمَصِيرُ', NULL, 'And [mention] when Abraham said, "My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allāh and the Last Day." [Allāh] said, "And whoever disbelieves - I will grant him enjoyment for a little; then I will force him to the punishment of the Fire, and wretched is the destination."', 'Dan (ingatlah) ketika Nabi Ibrahim berdoa dengan berkata: “Wahai Tuhanku! Jadikanlah (negeri Makkah) ini, negeri yang aman sentosa, dan berikanlah rezeki dari berbagai jenis buah-buahan kepada penduduknya, iaitu orang-orang yang beriman kepada Allah dan hari akhirat di antara mereka”. Allah berfirman: “(Permohonanmu itu diterima) tetapi sesiapa yang kufur dan ingkar maka Aku akan beri juga ia bersenang-senang menikmati rezeki itu bagi sementara (di dunia), kemudian Aku memaksanya (dengan menyeretnya) ke azab neraka, dan (itulah) seburuk-buruk tempat kembali”.', FALSE, NULL, NULL, 19, 1, 8, 16, FALSE, 0, NULL),
(2, 127, 'وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ', NULL, 'And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], "Our Lord, accept [this] from us. Indeed, You are the Hearing, the Knowing.', 'Dan (ingatlah) ketika Nabi Ibrahim bersama-sama Nabi Ismail meninggikan binaan asas-asas (tapak) Baitullah (Kaabah) itu, sambil keduanya berdoa dengan berkata: “Wahai Tuhan kami! Terimalah daripada kami (amal kami); sesungguhnya Engkaulah yang Maha Mendengar, lagi Maha mengetahui;', FALSE, NULL, NULL, 20, 1, 8, 16, FALSE, 0, NULL),
(2, 128, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ', NULL, 'Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites [of worship] and accept our repentance. Indeed, You are the Accepting of Repentance, the Merciful.', '“Wahai Tuhan kami! Jadikanlah kami berdua: orang-orang Islam (yang berserah diri) kepadaMu, dan jadikanlah daripada keturunan kami: umat Islam (yang berserah diri) kepadamu, dan tunjukkanlah kepada kami syariat dan cara-cara ibadat kami, dan terimalah taubat kami; sesungguhnya Engkaulah Maha Penerima taubat, lagi Maha Mengasihani;', FALSE, NULL, NULL, 20, 1, 8, 16, FALSE, 0, NULL),
(2, 129, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ', NULL, 'Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise."', '“Wahai Tuhan Kami! Utuslah kepada mereka seorang Rasul dari kalangan mereka sendiri, yang akan membacakan kepada mereka ayat-ayat (firmanMu) dan mengajarkan mereka isi kandungan Kitab (Al-Quran) serta Hikmat kebijaksanaan dan membersihkan (hati dan jiwa) mereka (dari syirik dan maksiat). Sesungguhnya Engkaulah yang Maha Kuasa, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 20, 1, 8, 16, FALSE, 0, NULL),
(2, 130, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَاهِيمَ إِلَّا مَن سَفِهَ نَفْسَهُ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ', NULL, 'And who would be averse to the religion of Abraham except one who makes a fool of himself. And We had chosen him in this world, and indeed he, in the Hereafter, will be among the righteous.', 'Tidak ada orang yang membenci ugama Nabi Ibrahim selain dari orang yang membodohkan dirinya sendiri, kerana sesungguhnya Kami telah memilih Ibrahim (menjadi nabi) di dunia ini; dan sesungguhnya ia pada hari akhirat kelak tetaplah dari orang-orang yang soleh yang (tertinggi martabatnya).', FALSE, NULL, NULL, 20, 1, 8, 17, FALSE, 0, NULL),
(2, 131, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 'إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ', NULL, 'When his Lord said to him, "Submit," he said, "I have submitted [in Islām] to the Lord of the worlds."', '(Ingatlah) ketika Tuhannya berfirman kepadanya: “Serahkanlah diri (kepadaKu wahai Ibrahim)!” Nabi Ibrahim menjawab: “Aku serahkan diri (tunduk taat) kepada Tuhan Yang Memelihara dan mentadbirkan sekalian alam”.', FALSE, NULL, NULL, 20, 1, 8, 17, FALSE, 0, NULL),
(2, 132, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'وَوَصَّىٰ بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَىٰ لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', NULL, 'And Abraham instructed his sons [to do the same] and [so did] Jacob, [saying], "O my sons, indeed Allāh has chosen for you this religion, so do not die except while you are Muslims."', 'Dan Nabi Ibrahim pun berwasiat dengan ugama itu kepada anak-anaknya, dan (demikian juga) Nabi Yaakub (berwasiat kepada anak-anaknya) katanya: “Wahai anak-anakku! Sesungguhnya Allah telah memilih ugama (Islam) ini menjadi ikutan kamu, maka janganlah kamu mati melainkan kamu dalam keadaan Islam”.', FALSE, NULL, NULL, 20, 1, 8, 17, FALSE, 0, NULL),
(2, 133, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'أَمْ كُنتُمْ شُهَدَاءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِن بَعْدِي قَالُوا نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَٰهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ', NULL, 'Or were you witnesses when death approached Jacob, when he said to his sons, "What will you worship after me?" They said, "We will worship your God and the God of your fathers, Abraham and Ishmael and Isaac - one God. And we are Muslims [in submission] to Him."', '(Demikianlah wasiat Nabi Yaakub, bukan sebagaimana yang kamu katakan itu wahai orang-orang Yahudi)! Kamu tiada hadir ketika Nabi Yaakub hampir mati, ketika ia berkata kepada anak-anaknya: “Apakah yang kamu akan sembah sesudah aku mati?” Mereka menjawab: “Kami menyembah Tuhanmu dan Tuhan datuk nenekmu Ibrahim dan Ismail dan Ishak, iaitu Tuhan yang Maha Esa, dan kepadaNyalah sahaja kami berserah diri (dengan penuh iman)”.', FALSE, NULL, NULL, 20, 1, 8, 17, FALSE, 0, NULL),
(2, 134, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ', NULL, 'That was a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.', 'Mereka itu adalah satu umat yang telah lalu sejarahnya; bagi mereka (balasan) apa yang mereka telah usahakan, dan bagi kamu pula (balasan) apa yang kamu usahakan; dan kamu tidak akan ditanya (atau dipertanggungjawabkan) tentang apa yang telah mereka lakukan.', FALSE, NULL, NULL, 20, 1, 8, 17, FALSE, 0, NULL),
(2, 135, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', NULL, 'They say, "Be Jews or Christians [so] you will be guided." Say, "Rather, [we follow] the religion of Abraham, inclining toward truth, and he was not of the polytheists."', 'Dan mereka (kaum Yahudi dan Nasrani) berkata: “Jadilah kamu pemeluk ugama Yahudi atau pemeluk ugama Nasrani, nescaya kamu akan mendapat petunjuk”. Katakanlah (wahai Muhammad: “Kami orang-orang Islam tidak akan menurut apa yang kamu katakan itu) bahkan kami mengikut ugama Nabi Ibrahim yang tetap di atas dasar Tauhid, dan bukanlah ia dari orang-orang musyrik”.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 136, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَا أُوتِيَ النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ', NULL, 'Say, [O believers], "We have believed in Allāh and what has been revealed to us and what has been revealed to Abraham and Ishmael and Isaac and Jacob and the Descendants [al-Asbāṭ] and what was given to Moses and Jesus and what was given to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [in submission] to Him."', 'Katakanlah (wahai orang-orang yang beriman): “Kami beriman kepada Allah, dan kepada apa yang diturunkan kepada kami (Al-Quran), dan kepada apa yang diturunkan kepada Nabi Ibrahim dan Nabi Ismail dan Nabi Ishak dan Nabi Yaakub serta anak-anaknya, dan juga kepada apa yang diberikan kepada Nabi Musa (Taurat) dan Nabi Isa (Injil), dan kepada apa yang diberikan kepada Nabi-nabi dari Tuhan mereka; kami tidak membeza-bezakan antara seseorang dari mereka (sebagaimana yang kamu - Yahudi dan Nasrani - membeza-bezakannya); dan kami semua adalah Islam (berserah diri, tunduk taat) kepada Allah semata-mata”.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 137, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ فَسَيَكْفِيكَهُمُ ٱللَّهُ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنتُم بِهِ فَقَدِ اهْتَدَوا وَّإِن تَوَلَّوْا فَإِنَّمَا هُمْ فِي شِقَاقٍ فَسَيَكْفِيكَهُمُ اللَّهُ وَهُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'So if they believe in the same as you believe in, then they have been [rightly] guided; but if they turn away, they are only in dissension, and Allāh will be sufficient for you against them. And He is the Hearing, the Knowing.', 'Maka kalau mereka beriman sebagaimana kamu beriman (dengan Kitab-kitab Allah dan Rasul-rasulnya), maka sesungguhnya mereka telah beroleh petunjuk; dan jika mereka berpaling (serta tidak mahu beriman dengan sebenar-benar iman) maka sesungguhnya mereka akan tinggal berkekalan dalam perbalahan dan permusuhan (dengan kamu); oleh itu (janganlah engkau khuatir wahai Muhammad) kerana Allah akan memeliharamu (dan umatmu) dari kejahatan mereka; dan Dia lah jua Yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 138, 'صِبْغَةَ ٱللَّهِ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً وَنَحْنُ لَهُۥ عَٰبِدُونَ', 'صِبْغَةَ اللَّهِ وَمَنْ أَحْسَنُ مِنَ اللَّهِ صِبْغَةً وَنَحْنُ لَهُ عَابِدُونَ', NULL, '[And say, "Ours is] the religion of Allāh. And who is better than Allāh in [ordaining] religion? And we are worshippers of Him."', '(Katakanlah wahai orang-orang yang beriman: “Ugama Islam, yang kami telah sebati dengannya ialah): celupan Allah yang mencorakkan seluruh kehidupan kami dengan corak Islam); dan siapakah yang lebih baik celupannya daripada Allah? (Kami tetap percayakan Allah) dan kepadaNyalah kami beribadat”.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 139, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 'قُلْ أَتُحَاجُّونَنَا فِي اللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ وَنَحْنُ لَهُ مُخْلِصُونَ', NULL, 'Say, [O Muḥammad], "Do you argue with us about Allāh while He is our Lord and your Lord? For us are our deeds, and for you are your deeds. And we are sincere [in deed and intention] to Him."', 'Katakanlah (wahai Muhammad): “Patutkah kamu (hai kaum Yahudi dan Nasrani) membuat bantahan terhadap kami mengenai pilihan Allah dan pengurniaanNya? Padahal Dia lah Tuhan kami dan Tuhan kamu. Bagi kami (faedah) amal kami dan bagi kamu pula (faedah) amal kamu (kalau diikhlaskan), dan kami adalah (mengerjakan amal dengan) ikhlas kepadaNya;', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 140, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'أَمْ تَقُولُونَ إِنَّ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطَ كَانُوا هُودًا أَوْ نَصَارَىٰ قُلْ أَأَنتُمْ أَعْلَمُ أَمِ اللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَادَةً عِندَهُ مِنَ اللَّهِ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'Or do you say that Abraham and Ishmael and Isaac and Jacob and the Descendants were Jews or Christians? Say, "Are you more knowing or is Allāh?" And who is more unjust than one who conceals a testimony he has from Allāh? And Allāh is not unaware of what you do.', '“Atau patutkah kamu mengatakan, bahawa Nabi Ibrahim, dan Nabi Ismail, dan Nabi Ishak, dan Nabi Yaakub beserta anak-anaknya, mereka semua adalah orang-orang Yahudi atau Nasrani, (padahal ugama mereka telahpun ada sebelum adanya ugama Yahudi atau ugama Kristian itu)?” Katakanlah (wahai Muhammad): “Adakah kamu yang lebih mengetahui atau Allah? Dan siapakah yang lebih zalim daripada orang yang menyembunyikan keterangan (saksi dan bukti) yang telah diberikan Allah kepadanya?” Dan (ingatlah), Allah tidak sekali-kali lalai akan apa yang telah kamu lakukan.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 141, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ', NULL, 'That is a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.', 'Mereka itu adalah satu umat yang telah lalu sejarahnya; bagi mereka (balasan) apa yang telah mereka usahakan, dan bagi kamu pula (balasan) apa yang kamu usahakan; dan kamu tidak akan ditanya (atau dipertanggungjawabkan) tentang apa yang mereka telah lakukan.', FALSE, NULL, NULL, 21, 1, 8, 17, FALSE, 0, NULL),
(2, 142, 'سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'سَيَقُولُ السُّفَهَاءُ مِنَ النَّاسِ مَا وَلَّاهُمْ عَن قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا قُل لِّلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'The foolish among the people will say, "What has turned them away from their qiblah, which they used to face?" Say, "To Allāh belongs the east and the west. He guides whom He wills to a straight path."', 'Orang-orang bodoh (yang kurang akal pertimbangannya) akan berkata: “Apa sebabnya yang menjadikan orang-orang Islam berpaling dari kiblat yang mereka mengadapnya selama ini?” Katakanlah (wahai Muhammad): “Timur dan barat adalah kepunyaan Allah - (maka ke pihak mana sahaja kita diarahkan Allah mengadapnya, wajiblah kita mematuhiNya); Allah yang memberikan petunjuk hidayahNya kepada sesiapa yang dikehendakiNya ke jalan yang lurus”.', FALSE, NULL, NULL, 22, 2, 9, 18, FALSE, 0, NULL),
(2, 143, 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', 'وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا الْقِبْلَةَ الَّتِي كُنتَ عَلَيْهَا إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ الرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ', NULL, 'And thus We have made you a median [i.e., just] community that you will be witnesses over the people and the Messenger will be a witness over you. And We did not make the qiblah which you used to face except that We might make evident who would follow the Messenger from who would turn back on his heels. And indeed, it is difficult except for those whom Allāh has guided. And never would Allāh have caused you to lose your faith [i.e., your previous prayers]. Indeed Allāh is, to the people, Kind and Merciful.', 'Dan demikianlah (sebagaimana Kami telah memimpin kamu ke jalan yang lurus), Kami jadikan kamu (wahai umat Muhammad) satu umat yang pilihan lagi adil, supaya kamu layak menjadi orang yang memberi keterangan kepada umat manusia (tentang yang benar dan yang salah) dan Rasulullah (Muhammad) pula akan menjadi orang yang menerangkan kebenaran perbuatan kamu. (Sebenarnya kiblat kamu ialah Kaabah) dan tiadalah Kami jadikan kiblat yang engkau mengadapnya dahulu itu (wahai Muhammad), melainkan untuk menjadi ujian bagi melahirkan pengetahuan Kami tentang siapakah yang benar-benar mengikut Rasul serta membenarkannya dan siapa pula yang berpaling tadah (berbalik kepada kekufurannya) dan sesungguhnya (soal peralihan arah kiblat) itu adalah amat berat (untuk diterima) kecuali kepada orang-orang yang telah diberikan Allah petunjuk hidayah dan Allah tidak akan menghilangkan (bukti) iman kamu. Sesungguhnya Allah Amat melimpah belas kasihan dan rahmatNya kepada orang-orang (yang beriman).', FALSE, NULL, NULL, 22, 2, 9, 18, FALSE, 0, NULL),
(2, 144, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ وَإِنَّ الَّذِينَ أُوتُوا الْكِتَابَ لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ', NULL, 'We have certainly seen the turning of your face, [O Muḥammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face [i.e., yourself] toward al-Masjid al-Ḥarām. And wherever you [believers] are, turn your faces [i.e., yourselves] toward it [in prayer]. Indeed, those who have been given the Scripture [i.e., the Jews and the Christians] well know that it is the truth from their Lord. And Allāh is not unaware of what they do.', 'Kerap kali Kami melihat engkau (wahai Muhammad), berulang-ulang menengadah ke langit, maka Kami benarkan engkau berpaling mengadap kiblat yang engkau sukai. Oleh itu palingkanlah mukamu ke arah masjid Al-Haraam (tempat letaknya Kaabah); dan di mana sahaja kamu berada maka hadapkanlah muka kamu ke arahnya. Dan sesungguhnya orang-orang (Yahudi dan Nasrani) yang telah diberikan Kitab, mereka mengetahui bahawa perkara (berkiblat ke Kaabah) itu adalah perintah yang benar dari Tuhan mereka; dan Allah tidak sekali-kali lalai akan apa yang mereka lakukan.', FALSE, NULL, NULL, 22, 2, 9, 18, FALSE, 0, NULL),
(2, 145, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ إِنَّكَ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ مَّا تَبِعُوا قِبْلَتَكَ وَمَا أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم مِّن بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ إِنَّكَ إِذًا لَّمِنَ الظَّالِمِينَ', NULL, 'And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another''s qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers.', 'Dan demi sesungguhnya! Jika engkau bawakan kepada orang-orang (Yahudi dan Nasrani) yang telah diberikan Kitab, akan segala keterangan (yang menunjukkan kebenaran perintah berkiblat ke Kaabah itu), mereka tidak akan menurut kiblatmu, dan engkau pula tidak sekali-kali akan menurut kiblat mereka; dan sebahagian dari mereka juga tidak akan menurut kiblat sebahagian yang lain. Demi sesungguhnya! Kalau engkau menurut kehendak hawa nafsu mereka setelah datang kepadamu pengetahuan (yang telah diwahyukan kepadamu), sesungguhnya engkau, jika demikian, adalah dari golongan orang-orang yang zalim.', FALSE, NULL, NULL, 22, 2, 9, 18, FALSE, 0, NULL),
(2, 146, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 'الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ', NULL, 'Those to whom We gave the Scripture know him [i.e., Prophet Muḥammad (ﷺ)] as they know their own sons. But indeed, a party of them conceal the truth while they know [it].', 'Orang-orang (Yahudi dan Nasrani) yang Kami berikan Kitab itu mengetahui serta mengenalinya (Nabi Muhammad dan kebenarannya) sebagaimana mereka mengenal anak-anak mereka sendiri. Dan sesungguhnya sebahagian dari mereka berusaha menyembunyikan kebenaran itu, sedang mereka mengetahui (salahnya perbuatan yang demikian).', FALSE, NULL, NULL, 23, 2, 9, 18, FALSE, 0, NULL),
(2, 147, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'الْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ', NULL, 'The truth is from your Lord, so never be among the doubters.', 'Kebenaran (yang datangnya kepadamu dan disembunyikan oleh kaum Yahudi dan Nasrani) itu (wahai Muhammad), adalah datangnya dari Tuhanmu; oleh itu jangan sekali-kali engkau termasuk dalam golongan orang-orang yang ragu-ragu.', FALSE, NULL, NULL, 23, 2, 9, 18, FALSE, 0, NULL),
(2, 148, 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَاسْتَبِقُوا الْخَيْرَاتِ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'For each [religious following] is a [prayer] direction toward which it faces. So race to [all that is] good. Wherever you may be, Allāh will bring you forth [for judgement] all together. Indeed, Allāh is over all things competent.', 'Dan bagi tiap-tiap umat ada arah (kiblat) yang masing-masing menujunya; oleh itu berlumba-lumbalah kamu mengerjakan kebaikan; kerana di mana sahaja kamu berada maka Allah tetap akan membawa kamu semua (berhimpun pada hari kiamat untuk menerima balasan); sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 23, 2, 9, 19, FALSE, 0, NULL),
(2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَإِنَّهُ لَلْحَقُّ مِن رَّبِّكَ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'So from wherever you go out [for prayer, O Muḥammad], turn your face toward al-Masjid al-Ḥarām, and indeed, it is the truth from your Lord. And Allāh is not unaware of what you do.', 'Dan dari mana sahaja engkau keluar (untuk mengerjakan sembahyang), maka hadapkanlah mukamu ke arah masjid Al-Haraam (Kaabah); dan sesungguhnya perintah berkiblat ke Kaabah itu adalah benar dari Tuhanmu. Dan (ingatlah), Allah tidak sekali-kali lalai akan segala apa yang kamu lakukan.', FALSE, NULL, NULL, 23, 2, 9, 19, FALSE, 0, NULL),
(2, 150, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِي وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', NULL, 'And from wherever you go out [for prayer], turn your face toward al-Masjid al-Ḥarām. And wherever you [believers] may be, turn your faces toward it in order that the people will not have any argument against you, except for those of them who commit wrong; so fear them not but fear Me. And [it is] so I may complete My favor upon you and that you may be guided,', 'Dan dari mana sahaja engkau keluar (untuk mengerjakan sembahyang), maka hadapkanlah mukamu ke arah masjid Al-Haraam (Kaabah); dan di mana sahaja kamu berada maka hadapkanlah muka kamu ke arahnya, supaya tidak ada lagi (sebarang) alasan bagi orang-orang (yang menyalahi kamu), kecuali orang-orang yang zalim di antara mereka (ada sahaja yang mereka jadikan alasan). Maka janganlah kamu takut kepada (cacat cela) mereka, dan takutlah kamu kepada Ku (semata-mata); dan supaya Aku sempurnakan nikmatKu kepada kamu, dan juga supaya kamu beroleh petunjuk hidayah (mengenai perkara yang benar).', FALSE, NULL, NULL, 23, 2, 9, 19, FALSE, 0, NULL),
(2, 151, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'كَمَا أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا تَعْلَمُونَ', NULL, 'Just as We have sent among you a messenger from yourselves reciting to you Our verses and purifying you and teaching you the Book and wisdom and teaching you that which you did not know.', '(Nikmat berkiblatkan Kaabah yang Kami berikan kepada kamu itu), samalah seperti (nikmat) Kami mengutuskan kepada kamu seorang Rasul dari kalangan kamu (iaitu Muhammad), yang membacakan ayat-ayat Kami kepada kamu, dan membersihkan kamu (dari amalan syirik dan maksiat), dan yang mengajarkan kamu kandungan Kitab (Al-Quran) serta Hikmat kebijaksanaan, dan mengajarkan kamu apa yang belum kamu ketahui.', FALSE, NULL, NULL, 23, 2, 9, 19, FALSE, 0, NULL),
(2, 152, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', 'فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ', NULL, 'So remember Me; I will remember you. And be grateful to Me and do not deny Me.', 'Oleh itu ingatlah kamu kepadaKu (dengan mematuhi hukum dan undang-undangKu), supaya Aku membalas kamu dengan kebaikan; dan bersyukurlah kamu kepadaKu dan janganlah kamu kufur (akan nikmatKu).', FALSE, NULL, NULL, 23, 2, 9, 19, FALSE, 0, NULL),
(2, 153, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', NULL, 'O you who have believed, seek help through patience and prayer. Indeed, Allāh is with the patient.', 'Wahai sekalian orang-orang yang beriman! Mintalah pertolongan (untuk menghadapi susah payah dalam menyempurnakan sesuatu perintah Tuhan) dengan bersabar dan dengan (mengerjakan) sembahyang; kerana sesungguhnya Allah menyertai (menolong) orang-orang yang sabar', FALSE, NULL, NULL, 23, 2, 9, 20, FALSE, 0, NULL),
(2, 154, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ بَلْ أَحْيَآءٌ وَلَٰكِن لَّا تَشْعُرُونَ', 'وَلَا تَقُولُوا لِمَن يُقْتَلُ فِي سَبِيلِ اللَّهِ أَمْوَاتٌ بَلْ أَحْيَاءٌ وَلَٰكِن لَّا تَشْعُرُونَ', NULL, 'And do not say about those who are killed in the way of Allāh, "They are dead." Rather, they are alive, but you perceive [it] not.', 'Dan janganlah kamu mengatakan (bahawa) sesiapa yang terbunuh dalam perjuangan membela Ugama Allah itu: orang-orang mati; bahkan mereka itu orang-orang yang hidup (dengan keadaan hidup yang istimewa), tetapi kamu tidak dapat menyedarinya.', FALSE, NULL, NULL, 24, 2, 9, 20, FALSE, 0, NULL),
(2, 155, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ وَبَشِّرِ ٱلصَّٰبِرِينَ', 'وَلَنَبْلُوَنَّكُم بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِّنَ الْأَمْوَالِ وَالْأَنفُسِ وَالثَّمَرَاتِ وَبَشِّرِ الصَّابِرِينَ', NULL, 'And We will surely test you with something of fear and hunger and a loss of wealth and lives and fruits, but give good tidings to the patient,', 'Demi sesungguhnya! Kami akan menguji kamu dengan sedikit perasaan takut (kepada musuh) dan (dengan merasai) kelaparan, dan (dengan berlakunya) kekurangan dari harta benda dan jiwa serta hasil tanaman. Dan berilah khabar gembira kepada orang-orang yang sabar:', FALSE, NULL, NULL, 24, 2, 9, 20, FALSE, 0, NULL),
(2, 156, 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', 'الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ', NULL, 'Who, when disaster strikes them, say, "Indeed we belong to Allāh, and indeed to Him we will return."', '(Iaitu) orang-orang yang apabila mereka ditimpa oleh sesuatu kesusahan, mereka berkata: “Sesungguhnya kami adalah kepunyaan Allah dan kepada Allah jualah kami kembali.”', FALSE, NULL, NULL, 24, 2, 9, 20, FALSE, 0, NULL),
(2, 157, 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 'أُولَٰئِكَ عَلَيْهِمْ صَلَوَاتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُولَٰئِكَ هُمُ الْمُهْتَدُونَ', NULL, 'Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided.', 'Mereka itu ialah orang-orang yang dilimpahi dengan berbagai-bagai kebaikan dari Tuhan mereka serta rahmatNya; dan mereka itulah orang-orang yang dapat petunjuk hidayahNya.', FALSE, NULL, NULL, 24, 2, 9, 20, FALSE, 0, NULL),
(2, 158, 'إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ', NULL, 'Indeed, aṣ-Ṣafā and al-Marwah are among the symbols of Allāh. So whoever makes ḥajj [pilgrimage] to the House or performs ʿumrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allāh is Appreciative and Knowing.', 'Sesungguhnya “Safa” dan “Marwah” itu ialah sebahagian daripada Syiar (lambang) ugama Allah; maka sesiapa yang menunaikan ibadat Haji ke Baitullah atau mengerjakan Umrah, maka tiadalah menjadi salah ia bersaie (berjalan dengan berulang-alik) di antara keduanya. Dan sesiapa yang bersukarela mengerjakan perkara kebajikan, maka sesungguhnya Allah memberi balasan pahala, lagi Maha Mengetahui.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 159, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', 'إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَىٰ مِن بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ أُولَٰئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ', NULL, 'Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allāh and cursed by those who curse,', 'Sesungguhnya orang-orang yang menyembunyikan apa yang telah Kami turunkan dari keterangan-keterangan dan petunjuk hidayah, sesudah Kami menerangkannya kepada manusia di dalam Kitab Suci, mereka itu dilaknat oleh Allah dan dilaknat oleh sekalian makhluk.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 160, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', 'إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَبَيَّنُوا فَأُولَٰئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا التَّوَّابُ الرَّحِيمُ', NULL, 'Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of Repentance, the Merciful.', 'Kecuali orang-orang yang bertaubat, dan memperbaiki (amal buruk mereka) serta menerangkan (apa yang mereka sembunyikan); maka orang-orang itu, Aku terima taubat mereka, dan Akulah Yang Maha Penerima taubat, lagi Maha Mengasihani.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 161, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ', NULL, 'Indeed, those who disbelieve and die while they are disbelievers - upon them will be the curse of Allāh and of the angels and the people, all together,', 'Sesungguhnya orang-orang yang kafir, dan mereka mati sedang mereka tetap dalam keadaan kafir, mereka itulah orang-orang yang ditimpa laknat Allah dan malaikat serta manusia sekaliannya.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 162, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ', NULL, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.', 'Mereka kekal di dalam laknat itu, tidak diringankan azab sengsara dari mereka dan mereka pula tidak diberikan tempoh atau perhatian.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 163, 'وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'وَإِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ لَّا إِلَٰهَ إِلَّا هُوَ الرَّحْمَٰنُ الرَّحِيمُ', NULL, 'And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful.', 'Dan Tuhan kamu ialah Tuhan yang Maha Esa; tiada Tuhan (Yang berhak disembah) selain dari Allah, yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 24, 2, 10, 20, FALSE, 0, NULL),
(2, 164, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللَّهُ مِنَ السَّمَاءِ مِن مَّاءٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ', NULL, 'Indeed, in the creation of the heavens and the earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allāh has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and earth are signs for a people who use reason.', 'Sesungguhnya pada kejadian langit dan bumi; dan (pada) pertukaran malam dan siang; dan (pada) kapal-kapal yang belayar di laut dengan membawa benda-benda yang bermanfaat kepada manusia; demikian juga (pada) air hujan yang Allah turunkan dari langit lalu Allah hidupkan dengannya tumbuh-tumbuhan di bumi sesudah matinya, serta Ia biakkan padanya dari berbagai-bagai jenis binatang; demikian juga (pada) peredaran angin dan awan yang tunduk (kepada kuasa Allah) terapung-apung di antara langit dengan bumi; sesungguhnya (pada semuanya itu) ada tanda-tanda (yang membuktikan keesaan Allah kekuasaanNya, kebijaksanaanNya, dan keluasan rahmatNya) bagi kaum yang (mahu) menggunakan akal fikiran.', FALSE, NULL, NULL, 25, 2, 10, 21, FALSE, 0, NULL),
(2, 165, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', 'وَمِنَ النَّاسِ مَن يَتَّخِذُ مِن دُونِ اللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ اللَّهِ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ', NULL, 'And [yet], among the people are those who take other than Allāh as equals [to Him]. They love them as they [should] love Allāh. But those who believe are stronger in love for Allāh. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allāh and that Allāh is severe in punishment.', '(Walaupun demikian), ada juga di antara manusia yang mengambil selain dari Allah (untuk menjadi) sekutu-sekutu (Allah), mereka mencintainya, (memuja dan mentaatinya) sebagaimana mereka mencintai Allah; sedang orang-orang yang beriman itu lebih cinta (taat) kepada Allah. Dan kalaulah orang-orang yang melakukan kezaliman (syirik) itu mengetahui ketika mereka melihat azab pada hari akhirat kelak, bahawa sesungguhnya kekuatan dan kekuasaan itu semuanya tertentu bagi Allah, dan bahawa sesungguhnya Allah Maha berat azab seksaNya, (nescaya mereka tidak melakukan kezaliman itu).', FALSE, NULL, NULL, 25, 2, 10, 21, FALSE, 0, NULL),
(2, 166, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 'إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذَابَ وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ', NULL, '[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship],', '(Iaitu) ketika ketua-ketua yang menjadi ikutan itu berlepas diri dari orang-orang yang mengikutnya, sedang kedua-dua pihak melihat betapa ngerinya azab seksa itu, dan (ketika) terputusnya segala hubungan di antara mereka.', FALSE, NULL, NULL, 25, 2, 10, 21, FALSE, 0, NULL),
(2, 167, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', 'وَقَالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا كَذَٰلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ وَمَا هُم بِخَارِجِينَ مِنَ النَّارِ', NULL, 'Those who followed will say, "If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us." Thus will Allāh show them their deeds as regrets upon them. And they are never to emerge from the Fire.', 'Dan (pada masa yang mengecewakan itu) berkatalah orang-orang yang menjadi pengikut: Alangkah eloknya kalau kami (dengan itu dapat kami berlepas diri daripada mereka sebagaimana mereka berlepas diri daripada kami (pada saat ini)!” Demikianlah Allah perlihatkan kepada mereka amal-amal mereka (dengan rupa yang mendatangkan) penyesalan yang amat sangat kepada mereka, dan mereka pula tidak akan dapat keluar dari neraka.', FALSE, NULL, NULL, 25, 2, 10, 21, FALSE, 0, NULL),
(2, 168, 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ', NULL, 'O mankind, eat from whatever is on earth [that is] lawful and good and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', 'Wahai sekalian manusia! Makanlah dari apa yang ada di bumi yang halal lagi baik, dan janganlah kamu ikut jejak langkah Syaitan; kerana sesungguhnya Syaitan itu ialah musuh yang terang nyata bagi kamu.', FALSE, NULL, NULL, 25, 2, 10, 22, FALSE, 0, NULL),
(2, 169, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'إِنَّمَا يَأْمُرُكُم بِالسُّوءِ وَالْفَحْشَاءِ وَأَن تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'He only orders you to evil and immorality and to say about Allāh what you do not know.', 'Ia hanya menyuruh kamu melakukan kejahatan dan perkara-perkara yang keji, dan (menyuruh) supaya kamu berkata (dusta) terhadap Allah apa yang kamu tidak ketahui (salah benarnya).', FALSE, NULL, NULL, 25, 2, 10, 22, FALSE, 0, NULL),
(2, 170, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْقِلُونَ شَيْئًا وَلَا يَهْتَدُونَ', NULL, 'And when it is said to them, "Follow what Allāh has revealed," they say, "Rather, we will follow that which we found our fathers doing." Even though their fathers understood nothing, nor were they guided?', 'Dan apabila dikatakan kepada mereka” Turutlah akan apa yang telah diturunkan oleh Allah” mereka menjawab: “(Tidak), bahkan kami (hanya) menurut apa yang kami dapati datuk nenek kami melakukannya”. Patutkah (mereka menurutnya) sekalipun datuk neneknya itu tidak faham sesuatu (apa pun tentang perkara-perkara ugama), dan tidak pula mendapat petunjuk hidayah (dari Allah)?', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 171, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ', 'وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ', NULL, 'The example of those who disbelieve is like that of one who shouts at what hears nothing but calls and cries [i.e., cattle or sheep] - deaf, dumb and blind, so they do not understand.', 'Dan bandingan (orang-orang yang menyeru) orang-orang kafir (yang tidak mahu beriman itu), samalah seperti orang yang berteriak memanggil binatang yang tidak dapat memahami selain dari mendengar suara panggilan sahaja; mereka itu ialah orang-orang yang pekak, bisu dan buta; oleh sebab itu mereka tidak dapat menggunakan akalnya.', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 172, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', NULL, 'O you who have believed, eat from the good [i.e., lawful] things which We have provided for you and be grateful to Allāh if it is [indeed] Him that you worship.', 'Wahai orang-orang yang beriman! Makanlah dari benda-benda yang baik (yang halal) yang telah Kami berikan kepada kamu, dan bersyukurlah kepada Allah, jika betul kamu hanya beribadat kepadanya.', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 173, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allāh. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], there is no sin upon him. Indeed, Allāh is Forgiving and Merciful.', 'Sesungguhnya Allah hanya mengharamkan kepada kamu memakan bangkai, dan darah, dan daging babi, dan binatang-binatang yang disembelih tidak kerana Allah maka sesiapa terpaksa (memakannya kerana darurat) sedang ia tidak mengingininya dan tidak pula melampaui batas (pada kadar benda yang dimakan itu), maka tidaklah ia berdosa. Sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 174, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلَ اللَّهُ مِنَ الْكِتَابِ وَيَشْتَرُونَ بِهِ ثَمَنًا قَلِيلًا أُولَٰئِكَ مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ وَلَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Indeed, they who conceal what Allāh has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allāh will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment.', 'Sesungguhnya orang-orang yang menyembunyikan (meminda atau mengubah) apa-apa keterangan Kitab Suci yang telah diturunkan oleh Allah, dan membeli dengannya keuntungan dunia yang sedikit faedahnya, mereka itu tidak mengisi dalam perut mereka selain dari api neraka, dan Allah tidak akan berkata-kata kepada mereka pada hari kiamat, dan Ia tidak membersihkan mereka (dari dosa), dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 175, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', 'أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَىٰ وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ', NULL, 'Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are for [i.e., in pursuit of] the Fire!', 'Mereka itulah orang-orang yang membeli kesesatan dengan meninggalkan petunjuk (ugama Allah), dan (membeli) azab seksa neraka dengan meninggalkan keampunan Tuhan. Maka sungguh ajaib kesanggupan mereka menanggung seksa api neraka itu.', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 176, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ', 'ذَٰلِكَ بِأَنَّ اللَّهَ نَزَّلَ الْكِتَابَ بِالْحَقِّ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتَابِ لَفِي شِقَاقٍ بَعِيدٍ', NULL, 'That is [deserved by them] because Allāh has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension.', '(Segala balasan yang buruk) itu adalah dengan sebab Allah telah menurunkan Kitab dengan mengandungi kebenaran (tetapi mereka berselisih padanya); dan sesungguhnya orang-orang yang berselisihan mengenai (kebenaran) kitab, itu sebenarnya mereka adalah dalam keadaan berpecah-belah yang jauh (dari mendapat petunjuk hidayah Allah).', FALSE, NULL, NULL, 26, 2, 10, 22, FALSE, 0, NULL),
(2, 177, 'لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'لَّيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَٰكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ وَآتَى الْمَالَ عَلَىٰ حُبِّهِ ذَوِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقَابِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ أُولَٰئِكَ الَّذِينَ صَدَقُوا وَأُولَٰئِكَ هُمُ الْمُتَّقُونَ', NULL, 'Righteousness is not that you turn your faces toward the east or the west, but [true] righteousness is [in] one who believes in Allāh, the Last Day, the angels, the Book, and the prophets and gives wealth, in spite of love for it, to relatives, orphans, the needy, the traveler, those who ask [for help], and for freeing slaves; [and who] establishes prayer and gives zakāh; [those who] fulfill their promise when they promise; and [those who] are patient in poverty and hardship and during battle. Those are the ones who have been true, and it is those who are the righteous.', 'Bukanlah perkara kebajikan itu hanya kamu menghadapkan muka ke pihak timur dan barat, tetapi kebajikan itu ialah berimannya seseorang kepada Allah, dan hari akhirat, dan segala malaikat, dan segala Kitab, dan sekalian Nabi; dan mendermanya seseorang akan hartanya sedang ia menyayanginya, - kepada kaum kerabat, dan anak-anak yatim dan orang-orang miskin dan orang yang terlantar dalam perjalanan, dan kepada orang-orang yang meminta, dan untuk memerdekakan hamba-hamba abdi; dan mengerjanya seseorang akan sembahyang serta mengeluarkan zakat; dan perbuatan orang-orang yang menyempurnakan janjinya apabila mereka membuat perjanjian; dan ketabahan orang-orang yang sabar dalam masa kesempitan, dan dalam masa kesakitan, dan juga dalam masa bertempur dalam perjuangan perang Sabil. orang-orang yang demikian sifatnya), mereka itulah orang-orang yang benar (beriman dan mengerjakan kebajikan); dan mereka itulah juga orang-orang yang bertaqwa.', FALSE, NULL, NULL, 27, 2, 11, 23, FALSE, 0, NULL),
(2, 178, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنثَىٰ بِالْأُنثَىٰ فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ اعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ', NULL, 'O you who have believed, prescribed for you is legal retribution for those murdered - the free for the free, the slave for the slave, and the female for the female. But whoever overlooks from his brother [i.e., the killer] anything, then there should be a suitable follow-up and payment to him [i.e., the deceased''s heir or legal representative] with good conduct. This is an alleviation from your Lord and a mercy. But whoever transgresses after that will have a painful punishment.', 'Wahai orang-orang yang beriman! Diwajibkan kamu menjalankan hukuman “Qisas” (balasan yang seimbang) dalam perkara orang-orang yang mati dibunuh iaitu: orang merdeka dengan orang merdeka, dan hamba dengan hamba, dan perempuan dengan perempuan. Maka sesiapa (pembunuh) yang dapat sebahagian keampunan dari saudaranya (pihak yang terbunuh), maka hendaklah orang yang mengampunkan itu) mengikut cara yang baik (dalam menuntut ganti nyawa), dan (si pembunuh pula) hendaklah menunaikan bayaran ganti nyawa itu) dengan sebaik-baiknya. Yang demikian itu adalah suatu keringanan dari Tuhan kamu serta suatu rahmat kemudahan. Sesudah itu sesiapa yang melampaui batas (untuk membalas dendam pula) maka baginya azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 27, 2, 11, 23, FALSE, 0, NULL),
(2, 179, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', 'وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ يَا أُولِي الْأَلْبَابِ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'And there is for you in legal retribution [saving of] life, O you [people] of understanding, that you may become righteous.', 'Dan di dalam hukuman Qisas itu ada jaminan hidup bagi kamu, wahai orang-orang yang berakal fikiran, supaya kamu bertaqwa.', FALSE, NULL, NULL, 27, 2, 11, 23, FALSE, 0, NULL),
(2, 180, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِن تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ', NULL, 'Prescribed for you when death approaches [any] one of you if he leaves wealth [is that he should make] a bequest for the parents and near relatives according to what is acceptable - a duty upon the righteous.', 'Kamu diwajibkan, apabila seseorang dari kamu hampir mati, jika ia ada meninggalkan harta, (hendaklah ia) membuat wasiat untuk ibu bapa dan kaum kerabat dengan cara yang baik (menurut peraturan ugama), sebagai suatu kewajipan atas orang-orang yang bertaqwa.', FALSE, NULL, NULL, 27, 2, 11, 23, FALSE, 0, NULL),
(2, 181, 'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'فَمَن بَدَّلَهُ بَعْدَ مَا سَمِعَهُ فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ', NULL, 'Then whoever alters it [i.e., the bequest] after he has heard it - the sin is only upon those who have altered it. Indeed, Allāh is Hearing and Knowing.', 'Kemudian sesiapa yang mengubah mana-mana wasiat sesudah ia mendengarnya, maka sesungguhnya dosanya hanya ditanggung oleh orang-orang yang mengubahnya; sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 27, 2, 11, 23, FALSE, 0, NULL),
(2, 182, 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'But if one fears from the bequeather [some] error or sin and corrects that which is between them [i.e., the concerned parties], there is no sin upon him. Indeed, Allāh is Forgiving and Merciful.', 'Tetapi sesiapa yang mengetahui bahawa orang yang berwasiat itu tidak adil atau melakukan dosa (dalam wasiatnya), lalu ia mendamaikan antara mereka (waris-waris, dengan membetulkan wasiat itu menurut aturan ugama), maka tidaklah ia berdosa. Sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 28, 2, 11, 23, FALSE, 0, NULL),
(2, 183, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -', 'Wahai orang-orang yang beriman! Kamu diwajibkan berpuasa sebagaimana diwajibkan atas orang-orang yang dahulu daripada kamu, supaya kamu bertaqwa.', FALSE, NULL, NULL, 28, 2, 11, 24, FALSE, 0, NULL),
(2, 184, 'أَيَّامًا مَّعْدُودَٰتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'أَيَّامًا مَّعْدُودَاتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُ وَأَن تَصُومُوا خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', NULL, '[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of other days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers good [i.e., excess] - it is better for him. But to fast is best for you, if you only knew.', '(Puasa yang diwajibkan itu ialah beberapa hari yang tertentu; maka sesiapa di antara kamu yang sakit, atau dalam musafir, (bolehlah ia berbuka), kemudian wajiblah ia berpuasa sebanyak (hari yang dibuka) itu pada hari-hari yang lain; dan wajib atas orang-orang yang tidak terdaya berpuasa (kerana tua dan sebagainya) membayar fidyah iaitu memberi makan orang miskin. Maka sesiapa yang dengan sukarela memberikan (bayaran fidyah) lebih dari yang ditentukan itu, maka itu adalah suatu kebaikan baginya; dan (walaupun demikian) berpuasa itu lebih baik bagi kamu daripada memberi fidyah), kalau kamu mengetahui.', FALSE, NULL, NULL, 28, 2, 11, 24, FALSE, 0, NULL),
(2, 185, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ هُدًى لِّلنَّاسِ وَبَيِّنَاتٍ مِّنَ الْهُدَىٰ وَالْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ الشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللَّهَ عَلَىٰ مَا هَدَاكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', NULL, 'The month of Ramaḍān [is that] in which was revealed the Qur’ān, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the crescent of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allāh intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allāh for that [to] which He has guided you; and perhaps you will be grateful.', '(Masa yang diwajibkan kamu berpuasa itu ialah) bulan Ramadan yang padanya diturunkan Al-Quran, menjadi petunjuk bagi sekalian manusia, dan menjadi keterangan-keterangan yang menjelaskan petunjuk dan (menjelaskan) perbezaan antara yang benar dengan yang salah. Oleh itu, sesiapa dari antara kamu yang menyaksikan anak bulan Ramadan (atau mengetahuinya), maka hendaklah ia berpuasa bulan itu; dan sesiapa yang sakit atau dalam musafir maka (bolehlah ia berbuka, Kemudian wajiblah ia berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain. (Dengan ketetapan yang demikian itu) Allah menghendaki kamu beroleh kemudahan, dan Ia tidak menghendaki kamu menanggung kesukaran. Dan juga supaya kamu cukupkan bilangan puasa (sebulan Ramadan), dan supaya kamu membesarkan Allah kerana mendapat petunjukNya, dan supaya kamu bersyukur.', FALSE, NULL, NULL, 28, 2, 11, 24, FALSE, 0, NULL),
(2, 186, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ', NULL, 'And when My servants ask you, [O Muḥammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided.', 'Dan apabila hamba-hambaKu bertanya kepadamu mengenai Aku maka (beritahu kepada mereka): sesungguhnya Aku (Allah) sentiasa hampir (kepada mereka); Aku perkenankan permohonan orang yang berdoa apabila ia berdoa kepadaKu. Maka hendaklah mereka menyahut seruanku (dengan mematuhi perintahKu), dan hendaklah mereka beriman kepadaKu supaya mereka menjadi baik serta betul.', FALSE, NULL, NULL, 28, 2, 11, 24, FALSE, 0, NULL),
(2, 187, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', 'أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَىٰ نِسَائِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ اللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَالْآنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ وَكُلُوا وَاشْرَبُوا حَتَّىٰ يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ وَلَا تُبَاشِرُوهُنَّ وَأَنتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ تِلْكَ حُدُودُ اللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ اللَّهُ آيَاتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', NULL, 'It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are a clothing for you and you are a clothing for them. Allāh knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allāh has decreed for you [i.e., offspring]. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the night [i.e., sunset]. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allāh, so do not approach them. Thus does Allāh make clear His verses [i.e., ordinances] to the people that they may become righteous.', 'Dihalalkan bagi kamu, pada malam hari puasa, bercampur (bersetubuh) dengan isteri-isteri kamu. Isteri-isteri kamu itu adalah sebagai pakaian bagi kamu dan kamu pula sebagai pakaian bagi mereka. Allah mengetahui bahawasanya kamu mengkhianati diri sendiri, lalu Ia menerima taubat kamu dan memaafkan kamu. Maka sekarang setubuhilah isteri-isteri kamu dan carilah apa-apa yang telah ditetapkan oleh Allah bagi kamu; dan makanlah serta minumlah sehingga nyata kepada kamu benang putih (cahaya siang) dari benang hitam kegelapan malam), iaitu waktu fajar. Kemudian sempurnakanlah puasa itu sehingga waktu malam (maghrib); dan janganlah kamu setubuhi isteri-isteri kamu ketika kamu sedang beriktikaf di masjid. Itulah batas-batas larangan Allah, maka janganlah kamu menghampirinya. Demikian Allah menerangkan ayat-ayat hukumNya kepada sekalian manusia supaya mereka bertaqwa.', FALSE, NULL, NULL, 29, 2, 11, 24, FALSE, 0, NULL),
(2, 188, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', 'وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقًا مِّنْ أَمْوَالِ النَّاسِ بِالْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', NULL, 'And do not consume one another''s wealth unjustly or send it [in bribery] to the rulers in order that [they might aid] you [to] consume a portion of the wealth of the people in sin, while you know [it is unlawful].', 'Dan janganlah kamu makan (atau mengambil) harta (orang-orang lain) di antara kamu dengan jalan yang salah, dan jangan pula kamu menghulurkan harta kamu (memberi rasuah) kepada hakim-hakim kerana hendak memakan (atau mengambil) sebahagian dari harta manusia dengan (berbuat) dosa, padahal kamu mengetahui (salahnya).', FALSE, NULL, NULL, 29, 2, 11, 24, FALSE, 0, NULL),
(2, 189, 'يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يَسْأَلُونَكَ عَنِ الْأَهِلَّةِ قُلْ هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ وَلَيْسَ الْبِرُّ بِأَن تَأْتُوا الْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ الْبِرَّ مَنِ اتَّقَىٰ وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'They ask you, [O Muḥammad], about the crescent moons. Say, "They are measurements of time for the people and for ḥajj [pilgrimage]." And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allāh. And enter houses from their doors. And fear Allāh that you may succeed.', 'Mereka bertanya kepadamu (wahai Muhammad) mengenai (peredaran) anak-anak bulan. Katakanlah: “(peredaran) anak-anak bulan itu menandakan waktu-waktu (urusan dan amalan) manusia, khasnya ibadat Haji. Dan bukanlah perkara kebajikan: kamu memasuki rumah dari bahagian belakangnya (ketika kamu berihram) akan tetapi kebajikan itu ialah perbuatan orang yang bertaqwa; dan masuklah ke rumah (Kamu) itu melalui pintunya, serta bertaqwalah kamu kepada Allah supaya kamu berjaya.”', FALSE, NULL, NULL, 29, 2, 12, 25, FALSE, 0, NULL),
(2, 190, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُوا إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ', NULL, 'Fight in the way of Allāh those who fight against you but do not transgress. Indeed, Allāh does not like transgressors.', 'Dan perangilah kerana (menegakkan dan mempertahankan) ugama Allah akan orang-orang yang memerangi kamu, dan janganlah kamu menceroboh (dengan memulakan peperangan); kerana sesungguhnya Allah tidak suka kepada orang-orang yang menceroboh.', FALSE, NULL, NULL, 29, 2, 12, 25, FALSE, 0, NULL),
(2, 191, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ وَلَا تُقَاتِلُوهُمْ عِندَ الْمَسْجِدِ الْحَرَامِ حَتَّىٰ يُقَاتِلُوكُمْ فِيهِ فَإِن قَاتَلُوكُمْ فَاقْتُلُوهُمْ كَذَٰلِكَ جَزَاءُ الْكَافِرِينَ', NULL, 'And kill them [in battle] wherever you overtake them and expel them from wherever they have expelled you, and fitnah is worse than killing. And do not fight them at al-Masjid al-Ḥarām until they fight you there. But if they fight you, then kill them. Such is the recompense of the disbelievers.', 'Dan bunuhlah mereka (musuh yang memerangi kamu) di mana sahaja kamu dapati mereka, dan usirlah mereka dari tempat yang mereka telah mengusir kamu; dan (ingatlah bahawa angkara) fitnah itu lebih besar bahayanya daripada pembunuhan dan janganlah kamu memerangi mereka di sekitar masjid Al-Haraam sehingga mereka memerangi kamu di situ. Oleh itu kalau mereka memerangi kamu (di situ), maka bunuhlah mereka. Demikianlah balasan bagi orang-orang yang kafir.', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 192, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'فَإِنِ انتَهَوْا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'And if they cease, then indeed, Allāh is Forgiving and Merciful.', 'Kemudian jika mereka berhenti memerangi kamu (maka berhentilah kamu); kerana sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 193, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', 'وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ فَإِنِ انتَهَوْا فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ', NULL, 'Fight them until there is no [more] fitnah and [until] religion [i.e., worship] is [acknowledged to be] for Allāh. But if they cease, then there is to be no aggression [i.e., assault] except against the oppressors.', 'Dan perangilah mereka sehingga tidak ada lagi fitnah, dan (sehingga) menjadilah ugama itu semata-mata kerana Allah. Kemudian jika mereka berhenti maka tidaklah ada permusuhan lagi melainkan terhadap orang-orang yang zalim.', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 194, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'الشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ وَالْحُرُمَاتُ قِصَاصٌ فَمَنِ اعْتَدَىٰ عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَىٰ عَلَيْكُمْ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ', NULL, '[Battle in] the sacred month is for [aggression committed in] the sacred month, and for [all] violations is legal retribution. So whoever has assaulted you, then assault him in the same way that he has assaulted you. And fear Allāh and know that Allāh is with those who fear Him.', '(Mencabuli) bulan yang dihormati itu ialah dengan (sebab membalas pencabulan dalam) bulan yang dihormati; dan tiap-tiap perkara yang dihormati itu (jika dicabuli), ada balasannya yang seimbang. Oleh itu sesiapa yang melakukan pencerobohan terhadap kamu maka balaslah pencerobohannya itu seimbang dengan pencerobohan yang dilakukannya kepada kamu; dan bertaqwalah kamu kepada Allah serta ketahuilah: Sesungguhnya Allah beserta orang-orang yang bertaqwa.', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 195, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ وَأَحْسِنُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'وَأَنفِقُوا فِي سَبِيلِ اللَّهِ وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ', NULL, 'And spend in the way of Allāh and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allāh loves the doers of good.', 'Dan belanjakanlah (apa yang ada pada kamu) kerana (menegakkan) ugama Allah, dan janganlah kamu sengaja mencampakkan diri kamu ke dalam bahaya kebinasaan (dengan bersikap bakhil); dan baikilah (dengan sebaik-baiknya segala usaha dan) perbuatan kamu; kerana sesungguhnya Allah mengasihi orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 196, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ الْهَدْيُ مَحِلَّهُ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَا أَمِنتُمْ فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ', NULL, 'And complete the ḥajj and ʿumrah for Allāh. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity or sacrifice. And when you are secure, then whoever performs ʿumrah [during the ḥajj months] followed by ḥajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during ḥajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Ḥarām. And fear Allāh and know that Allāh is severe in penalty.', 'Dan sempurnakanlah ibadat Haji dan Umrah kerana Allah; maka sekiranya kamu dikepong (dan dihalang daripada menyempurnakannya ketika kamu sudah berihram, maka kamu bolehlah bertahallul serta) sembelihlah Dam yang mudah didapati; dan janganlah kamu mencukur kepala kamu (untuk bertahallul), sebelum binatang Dam itu sampai (dan disembelih) di tempatnya. Maka sesiapa di antara kamu sakit atau terdapat sesuatu yang menyakiti di kepalanya (lalu ia mencukur rambutnya), hendaklah ia membayar fidyah. Iaitu berpuasa, atau bersedekah, atau menyembelih Dam. Kemudian apabila kamu berada kembali dalam keadaan aman, maka sesiapa yang mahu menikmati kemudahan dengan mengerjakan Umrah, (dan terus menikmati kemudahan itu) hingga masa (mengerjakan) ibadat Haji, (bolehlah ia melakukannya kemudian wajiblah ia) menyembelih Dam yang mudah didapati. Kalau ia tidak dapat (mengadakan Dam), maka hendaklah ia berpuasa tiga hari dalam masa mengerjakan Haji dan tujuh hari lagi apabila kamu kembali (ke tempat masing-masing); semuanya itu sepuluh (hari) cukup sempurna. Hukum ini ialah bagi orang yang tidak tinggal menetap (di sekitar) masjid Al-Haraam (Makkah). Dan hendaklah kamu bertaqwa kepada Allah; dan ketahuilah bahawasanya Allah Maha berat balasan seksaNya (terhadap orang-orang yang melanggar perintahNya).', FALSE, NULL, NULL, 30, 2, 12, 25, FALSE, 0, NULL),
(2, 197, 'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 'الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ', NULL, 'Ḥajj is [during] well-known months, so whoever has made ḥajj obligatory upon himself therein [by entering the state of iḥrām], there is [to be for him] no sexual relations and no disobedience and no disputing during ḥajj. And whatever good you do - Allāh knows it. And take provisions, but indeed, the best provision is fear of Allāh. And fear Me, O you of understanding.', '(Masa untuk mengerjakan ibadat) Haji itu ialah beberapa bulan yang termaklum. Oleh yang demikian sesiapa yang telah mewajibkan dirinya (dengan niat mengerjakan) ibadat Haji itu, maka tidak boleh mencampuri isteri, dan tidak boleh membuat maksiat, dan tidak boleh bertengkar, dalam masa mengerjakan ibadat Haji. Dan apa jua kebaikan yang kamu kerjakan adalah diketahui oleh Allah; dan hendaklah kamu membawa bekal dengan cukupnya kerana sesungguhnya sebaik-baik bekal itu ialah memelihara diri (dari keaiban meminta sedekah); dan bertaqwalah kepadaKu wahai orang-orang yang berakal (yang dapat memikir dan memahaminya).', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 198, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا فَضْلًا مِّن رَّبِّكُمْ فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِندَ الْمَشْعَرِ الْحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِن كُنتُم مِّن قَبْلِهِ لَمِنَ الضَّالِّينَ', NULL, 'There is no blame upon you for seeking bounty from your Lord [during ḥajj]. But when you depart from ʿArafāt, remember Allāh at al-Mashʿar al-Ḥarām. And remember Him, as He has guided you, for indeed, you were before that among those astray.', 'Tidaklah menjadi salah, kamu mencari limpah kurnia dari Tuhan kamu (dengan meneruskan perniagaan ketika mengerjakan Haji). Kemudian apabila kamu bertolak turun dari padang Arafah (menuju ke Muzdalifah) maka sebutlah nama Allah (dengan doa, “talbiah” dan tasbih) di tempat Masy''ar Al-Haraam (di Muzdalifah), dan ingatlah kepada Allah dengan menyebutnya sebagaimana Ia telah memberikan petunjuk hidayah kepadamu; dan sesungguhnya kamu sebelum itu adalah dari golongan orang-orang yang salah jalan ibadatnya.', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 199, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'Then depart from the place from where [all] the people depart and ask forgiveness of Allāh. Indeed, Allāh is Forgiving and Merciful.', 'Selain dari itu hendaklah kamu bertolak turun dari (Arafah) tempat bertolaknya orang ramai, dan beristighfarlah kamu kepada Allah (dengan memohon ampun), sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 200, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ', 'فَإِذَا قَضَيْتُم مَّنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ كَذِكْرِكُمْ آبَاءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ النَّاسِ مَن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ', NULL, 'And when you have completed your rites, remember Allāh like your [previous] remembrance of your fathers or with [much] greater remembrance. And among the people is he who says, "Our Lord, give us in this world," and he will have in the Hereafter no share.', 'Kemudian apabila kamu telah selesai mengerjakan amalan ibadat Haji kamu, maka hendaklah kamu menyebut-nyebut dan mengingati Allah (dengan membesarkanNya) sebagaimana kamu dahulu menyebut-nyebut (memuji-muji) datuk nenek kamu, bahkan dengan sebutan yang lebih lagi. Dalam pada itu, ada di antara manusia yang (berdoa dengan) berkata: “Wahai Tuhan kami! Berilah kami kebaikan) di dunia”. (orang-orang ini diberikan kebaikan di dunia) dan tidak ada baginya sedikitpun kebaikan di akhirat.', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 201, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ', 'وَمِنْهُم مَّن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', NULL, 'But among them is he who says, "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire."', 'Dan di antara mereka pula ada yang (berdoa dengan) berkata: “Wahai Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari azab neraka”.', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 202, 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'أُولَٰئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا وَاللَّهُ سَرِيعُ الْحِسَابِ', NULL, 'Those will have a share of what they have earned, and Allāh is swift in account.', 'Mereka itulah yang akan mendapat bahagian yang baik dari apa yang telah mereka usahakan; dan Allah amat cepat hitunganNya.', FALSE, NULL, NULL, 31, 2, 12, 26, FALSE, 0, NULL),
(2, 203, 'وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ٱتَّقَىٰ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', 'وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَىٰ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', NULL, 'And remember Allāh during [specific] numbered days. Then whoever hastens [his departure] in two days - there is no sin upon him; and whoever delays [until the third] - there is no sin upon him - for him who fears Allāh. And fear Allāh and know that unto Him you will be gathered.', 'Dan sebutlah kamu akan Allah (dengan takbir semasa mengerjakan Haji) dalam beberapa hari yang tertentu bilangannya. Kemudian sesiapa yang segera (meninggalkan Mina) pada hari yang kedua, maka ia tidaklah berdosa dan sesiapa yang melambatkan (meninggalkan Mina) maka ia juga tidaklah berdosa; (ketiadaan dosa itu ialah) bagi orang yang bertaqwa dan hendaklah kamu bertaqwa kepada Allah dan ketahuilah sesungguhnya kamu akan dihimpunkan kepadanya.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 204, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 'وَمِنَ النَّاسِ مَن يُعْجِبُكَ قَوْلُهُ فِي الْحَيَاةِ الدُّنْيَا وَيُشْهِدُ اللَّهَ عَلَىٰ مَا فِي قَلْبِهِ وَهُوَ أَلَدُّ الْخِصَامِ', NULL, 'And of the people is he whose speech pleases you in worldly life, and he calls Allāh to witness as to what is in his heart, yet he is the fiercest of opponents.', 'Dan di antara manusia ada orang yang tutur katanya mengenai hal kehidupan dunia, menyebabkan engkau tertarik hati (mendengarnya), dan ia (bersumpah dengan mengatakan bahawa) Allah menjadi saksi atas apa yang ada dalam hatinya, padahal ia adalah orang yang amat keras permusuhannya (kepadamu).', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 205, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِي الْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ وَاللَّهُ لَا يُحِبُّ الْفَسَادَ', NULL, 'And when he goes away, he strives throughout the land to cause corruption therein and destroy crops and animals. And Allāh does not like corruption.', 'Kemudian apabila ia pergi (dengan mendapat hajatnya), berusahalah ia di bumi, untuk melakukan bencana padanya, dan membinasakan tanaman-tanaman dan keturunan (binatang ternak dan manusia; sedang Allah tidak suka kepada bencana kerosakan.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 206, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ فَحَسْبُهُۥ جَهَنَّمُ وَلَبِئْسَ ٱلْمِهَادُ', 'وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ', NULL, 'And when it is said to him, "Fear Allāh," pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place.', 'Dan apabila dikatakan kepadanya: “Bertaqwalah engkau kepada Allah” timbulah kesombongannya dengan (meneruskan) dosa (yang dilakukannya itu). Oleh itu padanlah ia (menerima balasan azab) neraka jahannam dan demi sesungguhnya, (neraka jahannam itu) adalah seburuk-buruk tempat tinggal.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 207, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'وَمِنَ النَّاسِ مَن يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَاللَّهُ رَءُوفٌ بِالْعِبَادِ', NULL, 'And of the people is he who sells himself, seeking means to the approval of Allāh. And Allāh is Kind to [His] servants.', 'Dan di antara manusia ada yang mengorbankan dirinya kerana mencari keredaan Allah semata-mata; dan Allah pula Amat belas-kasihan akan hamba-hambanya.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 208, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ', NULL, 'O you who have believed, enter into Islām completely [and perfectly] and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', 'Wahai orang-orang yang beriman! Masuklah kamu ke dalam Ugama Islam (dengan mematuhi) segala hukum-hukumnya; dan janganlah kamu menurut jejak langkah Syaitan; sesungguhnya Syaitan itu musuh bagi kamu yang terang nyata.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 209, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'فَإِن زَلَلْتُم مِّن بَعْدِ مَا جَاءَتْكُمُ الْبَيِّنَاتُ فَاعْلَمُوا أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, 'But if you slip [i.e., deviate] after clear proofs have come to you, then know that Allāh is Exalted in Might and Wise.', 'Maka kalau kamu tergelincir (dan jatuh ke dalam kesalahan disebabkan tipu daya Syaitan itu), sesudah datang keterangan-keterangan yang jelas kepada kamu, maka ketahuilah bahawasanya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 210, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'هَلْ يَنظُرُونَ إِلَّا أَن يَأْتِيَهُمُ اللَّهُ فِي ظُلَلٍ مِّنَ الْغَمَامِ وَالْمَلَائِكَةُ وَقُضِيَ الْأَمْرُ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ', NULL, 'Do they await but that Allāh should come to them in covers of clouds and the angels [as well] and the matter is [then] decided? And to Allāh [all] matters are returned.', '(Orang-orang yang ingkar itu) tidak menunggu melainkan kedatangan (azab) Allah kepada mereka dalam lindungan-lindungan awan, bersama-sama dengan malaikat (yang menjalankannya), padahal telahpun diputuskan perkara itu (balasan azab yang menimpa mereka); dan kepada Allah jua kembalinya segala urusan.', FALSE, NULL, NULL, 32, 2, 13, 26, FALSE, 0, NULL),
(2, 211, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'سَلْ بَنِي إِسْرَائِيلَ كَمْ آتَيْنَاهُم مِّنْ آيَةٍ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ اللَّهِ مِن بَعْدِ مَا جَاءَتْهُ فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ', NULL, 'Ask the Children of Israel how many a sign of evidence We have given them. And whoever exchanges the favor of Allāh [for disbelief] after it has come to him - then indeed, Allāh is severe in penalty.', 'Bertanyalah kepada Bani Israil, berapa banyak keterangan-keterangan yang telah Kami berikan kepada mereka (sedang mereka masih ingkar)? dan sesiapa menukar nikmat keterangan Allah (dengan mengambil kekufuran sebagai gantinya) sesudah nikmat itu sampai kepadaNya, maka (hendaklah ia mengetahui) sesungguhnya Allah amat berat azab seksaNya.', FALSE, NULL, NULL, 33, 2, 13, 27, FALSE, 0, NULL),
(2, 212, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا وَالَّذِينَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيَامَةِ وَاللَّهُ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ', NULL, 'Beautified for those who disbelieve is the life of this world, and they ridicule those who believe. But those who fear Allāh are above them on the Day of Resurrection. And Allāh gives provision to whom He wills without account.', 'Kehidupan dunia (dan kemewahannya) diperhiaskan (dan dijadikan amat indah) pada (pandangan) orang-orang kafir, sehingga mereka (berlagak sombong dan) memandang rendah kepada orang-orang yang beriman. Padahal orang-orang yang bertaqwa (dengan imannya) lebih tinggi (martabatnya) daripada mereka (yang kafir itu) pada hari kiamat kelak. Dan (ingatlah), Allah memberi rezeki kepada sesiapa yang dikehendakiNya dengan tidak terkira (menurut undang-undang peraturanNya).', FALSE, NULL, NULL, 33, 2, 13, 27, FALSE, 0, NULL),
(2, 213, 'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'كَانَ النَّاسُ أُمَّةً وَاحِدَةً فَبَعَثَ اللَّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ فِيمَا اخْتَلَفُوا فِيهِ وَمَا اخْتَلَفَ فِيهِ إِلَّا الَّذِينَ أُوتُوهُ مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ فَهَدَى اللَّهُ الَّذِينَ آمَنُوا لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِّ بِإِذْنِهِ وَاللَّهُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'Mankind was [of] one religion [before their deviation]; then Allāh sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over it [i.e., the Scripture] except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allāh guided those who believed to the truth concerning that over which they had differed, by His permission. And Allāh guides whom He wills to a straight path.', 'Pada mulanya manusia itu ialah umat yang satu (menurut ugama Allah yang satu, tetapi setelah mereka berselisihan), maka Allah mengutuskan Nabi-nabi sebagai pemberi khabar gembira (kepada orang-orang yang beriman dengan balasan Syurga, dan pemberi amaran (kepada orang-orang yang ingkar dengan balasan azab neraka); dan Allah menurunkan bersama Nabi-nabi itu Kitab-kitab Suci yang (mengandungi keterangan-keterangan yang) benar, untuk menjalankan hukum di antara manusia mengenai apa yang mereka perselisihkan dan (sebenarnya) tidak ada yang melakukan perselisihan melainkan orang-orang yang telah diberi kepada mereka Kitab-kitab Suci itu, iaitu sesudah datang kepada mereka keterangan-keterangan yang jelas nyata, - mereka berselisih semata-mata kerana hasad dengki sesama sendiri. Maka Allah memberikan petunjuk kepada orang-orang yang beriman ke arah kebenaran yang diperselisihkan oleh mereka (yang derhaka itu), dengan izinNya. Dan Allah sentiasa memberi petunjuk hidayahNya kepada sesiapa yang dikehendakiNya ke jalan yang lurus (menurut undang-undang peraturanNya).', FALSE, NULL, NULL, 33, 2, 13, 27, FALSE, 0, NULL),
(2, 214, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ', 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ الَّذِينَ خَلَوْا مِن قَبْلِكُم مَّسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّىٰ يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَىٰ نَصْرُ اللَّهِ أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ', NULL, 'Or do you think that you will enter Paradise while such [trial] has not yet come to you as came to those who passed on before you? They were touched by poverty and hardship and were shaken until [even their] messenger and those who believed with him said, "When is the help of Allāh?" Unquestionably, the help of Allāh is near.', 'Adakah patut kamu menyangka bahawa kamu akan masuk syurga, padahal belum sampai kepada kamu (ujian dan cubaan) seperti yang telah berlaku kepada orang-orang yang terdahulu daripada kamu? Mereka telah ditimpa kepapaan (kemusnahan hartabenda) dan serangan penyakit, serta digoncangkan (oleh ancaman bahaya musuh), sehingga berkatalah Rasul dan orang-orang yang beriman yang ada bersamanya: Bilakah (datangnya) pertolongan Allah?” Ketahuilah sesungguhnya pertolongan Allah itu dekat (asalkan kamu bersabar dan berpegang teguh kepada ugama Allah).', FALSE, NULL, NULL, 33, 2, 13, 27, FALSE, 0, NULL),
(2, 215, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'يَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَا أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالْأَقْرَبِينَ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ', NULL, 'They ask you, [O Muḥammad], what they should spend. Say, "Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allāh is Knowing of it."', 'Mereka bertanya kepadamu (wahai Muhammad): apakah yang akan mereka belanjakan (dan kepada siapakah)? Katakanlah: “Apa jua harta benda (yang halal) yang kamu belanjakan maka berikanlah kepada: Kedua ibu bapa, dan kaum kerabat, dan anak-anak yatim, dan orang-orang miskin, dan orang-orang yang terlantar dalam perjalanan. Dan (ingatlah), apa jua yang kamu buat dari jenis-jenis kebaikan, maka sesungguhnya Allah sentiasa mengetahuiNya (dan akan membalas dengan sebaik-baiknya).', FALSE, NULL, NULL, 33, 2, 13, 27, FALSE, 0, NULL),
(2, 216, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰ أَن تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَّكُمْ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', NULL, 'Battle has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allāh knows, while you know not.', 'Kamu diwajibkan berperang (untuk menentang pencerobohan) sedang peperangan itu ialah perkara yang kamu benci; dan boleh jadi kamu benci kepada sesuatu padahal ia baik bagi kamu, dan boleh jadi kamu suka kepada sesuatu padahal ia buruk bagi kamu. Dan (ingatlah), Allah jualah Yang mengetahui (semuanya itu), sedang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 34, 2, 13, 27, FALSE, 0, NULL),
(2, 217, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِندَ اللَّهِ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ اسْتَطَاعُوا وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ وَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'They ask you about the sacred month - about fighting therein. Say, "Fighting therein is great [sin], but averting [people] from the way of Allāh and disbelief in Him and [preventing access to] al-Masjid al-Ḥarām and the expulsion of its people therefrom are greater [evil] in the sight of Allāh. And fitnah is greater than killing." And they will continue to fight you until they turn you back from your religion if they are able. And whoever of you reverts from his religion [to disbelief] and dies while he is a disbeliever - for those, their deeds have become worthless in this world and the Hereafter, and those are the companions of the Fire; they will abide therein eternally.', 'Mereka bertanya kepadamu (wahai Muhammad), mengenai (hukum) berperang dalam bulan yang dihormati; katakanlah: “Peperangan dalam bulan itu adalah berdosa besar, tetapi perbuatan menghalangi (orang-orang Islam) dari jalan Allah dan perbuatan kufur kepadaNya, dan juga perbuatan menyekat (orang-orang Islam) ke Masjid Al-Haraam (di Makkah), serta mengusir penduduknya dari situ, (semuanya itu) adalah lebih besar lagi dosanya di sisi Allah. Dan (ingatlah), angkara fitnah itu lebih besar (dosanya) daripada pembunuhan (semasa perang dalam bulan yang dihormati). Dan mereka (orang-orang kafir itu) sentiasa memerangi kamu hingga mereka (mahu) memalingkan kamu dari ugama kamu kalau mereka sanggup (melakukan yang demikian); dan sesiapa di antara kamu yang murtad (berpaling tadah) dari ugamanya (ugama Islam), lalu ia mati sedang ia tetap kafir, maka orang-orang yang demikian, rosak binasalah amal usahanya (yang baik) di dunia dan di akhirat, dan mereka itulah ahli neraka, kekal mereka di dalamnya (selama-lamanya).', FALSE, NULL, NULL, 34, 2, 13, 28, FALSE, 0, NULL),
(2, 218, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ أُولَٰئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'Indeed, those who have believed and those who have emigrated and fought in the cause of Allāh - those expect the mercy of Allāh. And Allāh is Forgiving and Merciful.', 'Sesungguhnya orang-orang yang beriman, dan orang-orang yang berhijrah serta berjuang pada jalan Allah (untuk menegakkan ugama Islam), mereka itulah orang-orang yang mengharapkan rahmat Allah. Dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 34, 2, 13, 28, FALSE, 0, NULL),
(2, 219, 'يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلِ الْعَفْوَ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', NULL, 'They ask you about wine and gambling. Say, "In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit." And they ask you what they should spend. Say, "The excess [beyond needs]." Thus Allāh makes clear to you the verses [of revelation] that you might give thought', 'Mereka bertanya kepadamu (Wahai Muhammad) mengenai arak dan judi. Katakanlah: “Pada keduanya ada dosa besar dan ada pula beberapa manfaat bagi manusia tetapi dosa keduanya lebih besar daripada manfaatnya dan mereka bertanya pula kepadamu: Apakah yang mereka akan belanjakan (dermakan)? Katakanlah: “Dermakanlah - apa-apa) yang berlebih dari keperluan (kamu). Demikianlah Allah menerangkan kepada kamu ayat-ayatNya (keterangan-keterangan hukumNya) supaya kamu berfikir:', FALSE, NULL, NULL, 34, 2, 14, 28, FALSE, 0, NULL),
(2, 220, 'فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'فِي الدُّنْيَا وَالْآخِرَةِ وَيَسْأَلُونَكَ عَنِ الْيَتَامَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَانُكُمْ وَاللَّهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, 'To this world and the Hereafter. And they ask you about orphans. Say, "Improvement for them is best. And if you mix your affairs with theirs - they are your brothers. And Allāh knows the corrupter from the amender. And if Allāh had willed, He could have put you in difficulty. Indeed, Allāh is Exalted in Might and Wise."', 'Mengenai (urusan-urusan kamu) di dunia dan di akhirat dan mereka bertanya lagi kepadamu (wahai Muhammad), mengenai (masalah) anak-anak yatim. Katakanlah: “Memperbaiki keadaan anak-anak yatim itu amatlah baiknya”, dan jika kamu bercampur gaul dengan mereka (maka tidak ada salahnya) kerana mereka itu ialah saudara-saudara kamu (yang seugama); dan Allah mengetahui akan orang yang merosakkan (harta benda mereka) daripada orang yang hendak memperbaikinya. Dan jika Allah menghendaki tentulah Ia memberatkan kamu (dengan mengharamkan bercampur gaul dengan mereka). Sesungguhnya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 35, 2, 14, 28, FALSE, 0, NULL),
(2, 221, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'وَلَا تَنكِحُوا الْمُشْرِكَاتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا الْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُولَٰئِكَ يَدْعُونَ إِلَى النَّارِ وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِ وَيُبَيِّنُ آيَاتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And do not marry polytheistic women until they believe. And a believing slave woman is better than a polytheist, even though she might please you. And do not marry polytheistic men [to your women] until they believe. And a believing slave is better than a polytheist, even though he might please you. Those invite [you] to the Fire, but Allāh invites to Paradise and to forgiveness, by His permission. And He makes clear His verses [i.e., ordinances] to the people that perhaps they may remember.', 'Dan janganlah kamu berkahwin dengan perempuan-perempuan kafir musyrik sebelum mereka beriman (memeluk ugama Islam); dan sesungguhnya seorang hamba perempuan yang beriman itu lebih baik daripada perempuan kafir musyrik sekalipun keadaannya menarik hati kamu. Dan janganlah kamu (kahwinkan perempuan-perempuan Islam) dengan lelaki-lelaki kafir musyrik sebelum mereka beriman (memeluk ugama Islam) dan sesungguhnya seorang hamba lelaki yang beriman lebih baik daripada seorang lelaki musyrik, sekalipun keadaannya menarik hati kamu. (Yang demikian ialah kerana orang-orang kafir itu mengajak ke neraka sedang Allah mengajak ke Syurga dan memberi keampunan dengan izinNya. Dan Allah menjelaskan ayat-ayatNya (keterangan-keterangan hukumNya) kepada umat manusia, supaya mereka dapat mengambil pelajaran (daripadanya).', FALSE, NULL, NULL, 35, 2, 14, 28, FALSE, 0, NULL),
(2, 222, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 'وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ', NULL, 'And they ask you about menstruation. Say, "It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allāh has ordained for you. Indeed, Allāh loves those who are constantly repentant and loves those who purify themselves."', 'Dan mereka bertanya kepadamu (wahai Muhammad), mengenai (hukum) haid. Katakanlah: “Darah haid itu satu benda yang (menjijikkan dan) mendatangkan mudarat”. Oleh sebab itu hendaklah kamu menjauhkan diri dari perempuan (jangan bersetubuh dengan isteri kamu) dalam masa datang darah haid itu, dan janganlah kamu hampiri mereka (untuk bersetubuh) sebelum mereka suci. Kemudian apabila mereka sudah bersuci maka datangilah mereka menurut jalan yang diperintahkan oleh Allah kepada kamu. SesungguhNya Allah mengasihi orang-orang yang banyak bertaubat, dan mengasihi orang-orang yang sentiasa mensucikan diri.', FALSE, NULL, NULL, 35, 2, 14, 29, FALSE, 0, NULL),
(2, 223, 'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا۟ لِأَنفُسِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'نِسَاؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا لِأَنفُسِكُمْ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُم مُّلَاقُوهُ وَبَشِّرِ الْمُؤْمِنِينَ', NULL, 'Your wives are a place of cultivation [i.e., sowing of seed] for you, so come to your place of cultivation however you wish and put forth [righteousness] for yourselves. And fear Allāh and know that you will meet Him. And give good tidings to the believers.', 'Isteri-isteri kamu adalah sebagai kebun tanaman kamu, oleh itu datangilah kebun tanaman kamu menurut cara yang kamu sukai dan sediakanlah (amal-amal yang baik) untuk diri kamu; dan bertaqwalah kepada Allah serta ketahuilah sesungguhnya kamu akan menemuiNya (pada hari akhirat kelak) dan berilah khabar gembira wahai Muhammad) kepada orang-orang yang beriman.', FALSE, NULL, NULL, 35, 2, 14, 29, FALSE, 0, NULL),
(2, 224, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِّأَيْمَانِكُمْ أَن تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'And do not make [your oath by] Allāh an excuse against being righteous and fearing Allāh and making peace among people. And Allāh is Hearing and Knowing.', '(Dan janganlah kamu jadikan nama) Allah dalam sumpah kamu sebagai benteng yang menghalangi kamu daripada berbuat baik dan bertaqwa, serta mendamaikan perbalahan antara sesama manusia. Dan (ingatlah), Allah sentiasa mendengar, lagi sentiasa mengetahui.', FALSE, NULL, NULL, 35, 2, 14, 29, FALSE, 0, NULL),
(2, 225, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَٱللَّهُ غَفُورٌ حَلِيمٌ', 'لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَاللَّهُ غَفُورٌ حَلِيمٌ', NULL, 'Allāh does not impose blame upon you for what is unintentional in your oaths, but He imposes blame upon you for what your hearts have earned. And Allāh is Forgiving and Forbearing.', 'Allah tidak mengira kamu bersalah tentang sumpah kamu yang tidak dimaksudkan (untuk bersumpah), tetapi Ia mengira kamu bersalah (dan akan mengenakan hukuman) dengan sebab sumpah yang diusahakan (disengajakan) oleh hati kamu (dengan niat bersumpah). Dan (ingatlah), Allah Maha Pengampun, lagi Maha Penyabar.', FALSE, NULL, NULL, 36, 2, 14, 29, FALSE, 0, NULL),
(2, 226, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'For those who swear not to have sexual relations with their wives is a waiting time of four months, but if they return [to normal relations] - then indeed, Allāh is Forgiving and Merciful.', 'Kepada orang-orang yang bersumpah tidak akan mencampuri isteri-isteri mereka, diberikan tempoh empat bulan. Setelah itu jika mereka kembali (mencampurinya), maka sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 36, 2, 14, 29, FALSE, 0, NULL),
(2, 227, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'وَإِنْ عَزَمُوا الطَّلَاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ', NULL, 'And if they decide on divorce - then indeed, Allāh is Hearing and Knowing.', 'Dan jika mereka berazam hendak menjatuhkan talak (menceraikan isteri), maka sesungguhnya Allah Maha Mendengar, lagi Maha mengetahui.', FALSE, NULL, NULL, 36, 2, 14, 29, FALSE, 0, NULL),
(2, 228, 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًا وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنْ أَرَادُوا إِصْلَاحًا وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَاللَّهُ عَزِيزٌ حَكِيمٌ', NULL, 'Divorced women remain in waiting [i.e., do not remarry] for three periods, and it is not lawful for them to conceal what Allāh has created in their wombs if they believe in Allāh and the Last Day. And their husbands have more right to take them back in this [period] if they want reconciliation. And due to them [i.e., the wives] is similar to what is expected of them, according to what is reasonable. But the men [i.e., husbands] have a degree over them [in responsibility and authority]. And Allāh is Exalted in Might and Wise.', 'Dan isteri-isteri yang diceraikan itu hendaklah menunggu dengan menahan diri mereka (dari berkahwin) selama tiga kali suci (dari haid). Dan tidaklah halal bagi mereka menyembunyikan (tidak memberitahu tentang) anak yang dijadikan oleh Allah dalam kandungan rahim mereka, jika betul mereka beriman kepada Allah dan hari akhirat. Dan suami-suami mereka berhak mengambil kembali (rujuk akan) isteri-isteri itu dalam masa idah mereka jika suami-suami bertujuan hendak berdamai. Dan isteri-isteri itu mempunyai hak yang sama seperti kewajipan yang ditanggung oleh mereka (terhadap suami) dengan cara yang sepatutnya (dan tidak dilarang oleh syarak); dalam pada itu orang-orang lelaki (suami-suami itu) mempunyai satu darjat kelebihan atas orang-orang perempuan (isterinya). Dan (ingatlah), Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 36, 2, 14, 29, FALSE, 0, NULL),
(2, 229, 'ٱلطَّلَٰقُ مَرَّتَانِ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'الطَّلَاقُ مَرَّتَانِ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا إِلَّا أَن يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ تِلْكَ حُدُودُ اللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ اللَّهِ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ', NULL, 'Divorce is twice. Then [after that], either keep [her] in an acceptable manner or release [her] with good treatment. And it is not lawful for you to take anything of what you have given them unless both fear that they will not be able to keep [within] the limits of Allāh. But if you fear that they will not keep [within] the limits of Allāh, then there is no blame upon either of them concerning that by which she ransoms herself. These are the limits of Allāh, so do not transgress them. And whoever transgresses the limits of Allāh - it is those who are the wrongdoers [i.e., the unjust].', 'Talak (yang boleh dirujuk kembali itu hanya) dua kali. Sesudah itu bolehlah ia (rujuk dan) memegang terus (isterinya itu) dengan cara yang sepatutnya atau melepaskan (menceraikannya) dengan cara yang baik dan tidaklah halal bagi kamu mengambil balik sesuatu dari apa yang telah kamu berikan kepada mereka (isteri-isteri yang diceraikan itu) kecuali jika keduanya (suami isteri takut tidak dapat menegakkan aturan-aturan hukum Allah. Oleh itu kalau kamu khuatir bahawa kedua-duanya tidak dapat menegakkan aturan-aturan hukum Allah, maka tidaklah mereka berdosa - mengenai bayaran (tebus talak) yang diberikan oleh isteri untuk menebus dirinya (dan mengenai pengambilan suami akan bayaran itu). Itulah aturan-aturan hukum Allah maka janganlah kamu melanggarnya; dan sesiapa yang melanggar aturan-aturan hukum Allah, maka mereka itulah orang-orang yang zalim.', FALSE, NULL, NULL, 36, 2, 14, 30, FALSE, 0, NULL),
(2, 230, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِن بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَا أَن يَتَرَاجَعَا إِن ظَنَّا أَن يُقِيمَا حُدُودَ اللَّهِ وَتِلْكَ حُدُودُ اللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', NULL, 'And if he has divorced her [for the third time], then she is not lawful to him afterward until [after] she marries a husband other than him. And if he [i.e., the latter husband] divorces her [or dies], there is no blame upon them [i.e., the woman and her former husband] for returning to each other if they think that they can keep [within] the limits of Allāh. These are the limits of Allāh, which He makes clear to a people who know [i.e.,understand].', 'Sesudah (diceraikan dua kali), itu jika diceraikan pula (bagi kali yang ketiga) maka perempuan itu tidak halal lagi baginya sesudah itu, sehingga ia berkahwin dengan suami yang lain. Setelah itu kalau ia diceraikan (oleh suami baharu itu dan habis idahnya), maka mereka berdua (suami lama dan bekas isterinya) tidaklah berdosa untuk kembali (maskahwin semula), jika mereka kuat menyangka akan dapat menegakkan aturan-aturan hukum Allah dan itulah aturan-aturan hukum Allah, diterangkannya kepada kaum yang (mahu) mengetahui dan memahaminya.', FALSE, NULL, NULL, 36, 2, 14, 30, FALSE, 0, NULL),
(2, 231, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًا وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُ وَلَا تَتَّخِذُوا آيَاتِ اللَّهِ هُزُوًا وَاذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ وَمَا أَنزَلَ عَلَيْكُم مِّنَ الْكِتَابِ وَالْحِكْمَةِ يَعِظُكُم بِهِ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'And when you divorce women and they have [nearly] fulfilled their term, either retain them according to acceptable terms or release them according to acceptable terms, and do not keep them, intending harm, to transgress [against them]. And whoever does that has certainly wronged himself. And do not take the verses of Allāh in jest. And remember the favor of Allāh upon you and what has been revealed to you of the Book [i.e., the Qur’ān] and wisdom [i.e., the Prophet''s sunnah] by which He instructs you. And fear Allāh and know that Allāh is Knowing of all things.', 'Dan apabila kamu menceraikan isteri-isteri (kamu) kemudian mereka (hampir) habis tempoh idahnya maka bolehlah kamu pegang mereka (rujuk) dengan cara yang baik atau lepaskan mereka dengan cara yang baik. Dan janganlah kamu pegang mereka (rujuk semula dengan maksud memberi mudarat, kerana kamu hendak melakukan kezaliman (terhadap mereka); dan sesiapa yang melakukan demikian maka sesungguhnya dia menganiaya dirinya sendiri. dan janganlah kamu menjadikan ayat-ayat hukum Allah itu sebagai ejek-ejekan (dan permainan). Dan kenanglah nikmat Allah yang diberikan kepada kamu, (dan kenanglah) apa yang diturunkan kepada kamu iaitu Kitab (Al-Quran) dan ilmu hikmat, untuk memberi pengajaran kepada kamu dengannya. Dan bertaqwalah kepada Allah serta ketahuilah: sesungguhnya Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 37, 2, 14, 30, FALSE, 0, NULL),
(2, 232, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَاجَهُنَّ إِذَا تَرَاضَوْا بَيْنَهُم بِالْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِ مَن كَانَ مِنكُمْ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', NULL, 'And when you divorce women and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they [i.e., all parties] agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allāh and the Last Day. That is better for you and purer, and Allāh knows and you know not.', 'Dan apabila kamu menceraikan isteri-isteri (kamu), lalu habis masa idah mereka ‘ maka janganlah kamu (wahai wali-wali nikah) menahan mereka daripada berkahwin semula dengan (bekas) suami mereka, apabila mereka (lelaki dan perempuan itu) bersetuju sesama sendiri dengan cara yang baik (yang dibenarkan oleh Syarak). Demikianlah diberi ingatan dan pengajaran dengan itu kepada sesiapa di antara kamu yang beriman kepada Allah dan hari akhirat. Yang demikian adalah lebih baik bagi kamu dan lebih suci. Dan (ingatlah), Allah mengetahui (akan apa jua yang baik untuk kamu) sedang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 37, 2, 14, 31, FALSE, 0, NULL),
(2, 233, 'وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ الرَّضَاعَةَ وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَارَّ وَالِدَةٌ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُ بِوَلَدِهِ وَعَلَى الْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوا أَوْلَادَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّا آتَيْتُم بِالْمَعْرُوفِ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'Mothers may nurse [i.e., breastfeed] their children two complete years for whoever wishes to complete the nursing [period]. Upon the father is their [i.e., the mothers''] provision and their clothing according to what is acceptable. No person is charged with more than his capacity. No mother should be harmed through her child, and no father through his child. And upon the [father''s] heir is [a duty] like that [of the father]. And if they both desire weaning through mutual consent from both of them and consultation, there is no blame upon either of them. And if you wish to have your children nursed by a substitute, there is no blame upon you as long as you give payment according to what is acceptable. And fear Allāh and know that Allāh is Seeing of what you do.', 'Dan ibu-ibu hendaklah menyusukan anak-anak mereka selama dua tahun genap iaitu bagi orang yang hendak menyempurnakan penyusuan itu; dan kewajipan bapa pula ialah memberi makan dan pakaian kepada ibu itu menurut cara yang sepatutnya. Tidaklah diberatkan seseorang melainkan menurut kemampuannya. Janganlah menjadikan seseorang ibu itu menderita kerana anaknya, dan (jangan juga menjadikan) seseorang bapa itu menderita kerana anaknya; dan waris juga menanggung kewajipan yang tersebut (jika si bapa tiada). kemudian jika keduanya (suami isteri mahu menghentikan penyusuan itu dengan persetujuan (yang telah dicapai oleh) mereka sesudah berunding, maka mereka berdua tidaklah salah (melakukannya). Dan jika kamu hendak beri anak-anak kamu menyusu kepada orang lain, maka tidak ada salahnya bagi kamu apabila kamu serahkan (upah) yang kamu mahu beri itu dengan cara yang patut. Dan bertaqwalah kamu kepada Allah, serta ketahuilah, sesungguhnya Allah sentiasa melihat akan apa jua yang kamu lakukan.', FALSE, NULL, NULL, 37, 2, 15, 31, FALSE, 0, NULL),
(2, 234, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ بِالْمَعْرُوفِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', NULL, 'And those who are taken in death among you and leave wives behind - they, [the wives, shall] wait four months and ten [days]. And when they have fulfilled their term, then there is no blame upon you for what they do with themselves in an acceptable manner. And Allāh is [fully] Aware of what you do.', 'Dan orang-orang yang meninggal dunia di antara kamu, sedang mereka meninggalkan isteri-isteri hendaklah isteri-isteri itu menahan diri mereka (beridah) selama empat bulan sepuluh hari. Kemudian apabila telah habis masa idahnya itu maka tidak ada salahnya bagi kamu mengenai apa yang dilakukan mereka pada dirinya menurut cara yang baik (yang diluluskan oleh Syarak). Dan (ingatlah), Allah sentiasa mengetahui dengan mendalam akan apa jua yang kamu lakukan.', FALSE, NULL, NULL, 38, 2, 15, 31, FALSE, 0, NULL),
(2, 235, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنتُمْ فِي أَنفُسِكُمْ عَلِمَ اللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّا أَن تَقُولُوا قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّىٰ يَبْلُغَ الْكِتَابُ أَجَلَهُ وَاعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ مَا فِي أَنفُسِكُمْ فَاحْذَرُوهُ وَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ', NULL, 'There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allāh knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period reaches its end. And know that Allāh knows what is within yourselves, so beware of Him. And know that Allāh is Forgiving and Forbearing.', 'Dan tidak ada salahnya bagi kamu tentang apa yang kamu bayangkan (secara sindiran), untuk meminang perempuan (yang kematian suami dan masih dalam idah), atau tentang kamu menyimpan dalam hati (keinginan berkahwin dengan mereka). Allah mengetahui bahawa kamu akan menyebut-nyebut atau mengingati) mereka, (yang demikian itu tidaklah salah), akan tetapi janganlah kamu membuat janji dengan mereka di dalam sulit, selain dari menyebutkan kata-kata (secara sindiran) yang sopan. Dan janganlah kamu menetapkan dengan bersungguh-sungguh (hendak melakukan) akad nikah sebelum habis idah yang ditetapkan itu. Dan ketahuilah sesungguhnya Allah mengetahui apa yang ada dalam hati kamu, maka beringat-ingatlah kamu akan kemurkaanNya, dan ketahuilah, sesungguhnya Allah Maha Pengampun, lagi Maha Penyabar.', FALSE, NULL, NULL, 38, 2, 15, 31, FALSE, 0, NULL),
(2, 236, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُحْسِنِينَ', 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ', NULL, 'There is no blame upon you if you divorce women you have not touched nor specified for them an obligation. But give them [a gift of] compensation - the wealthy according to his capability and the poor according to his capability - a provision according to what is acceptable, a duty upon the doers of good.', 'Tidaklah kamu bersalah dan tidaklah kamu menanggung bayaran maskahwin) jika kamu menceraikan isteri-isteri kamu sebelum kamu sentuh (bercampur) dengan mereka atau (sebelum) kamu menetapkan maskahwin untuk mereka. Walaupun demikian, hendaklah kamu memberi “Mut''ah” (pemberian saguhati) kepada mereka (yang diceraikan itu). Iaitu: suami yang senang (hendaklah memberi saguhati itu) menurut ukuran kemampuannya; dan suami yang susah pula menurut ukuran kemampuannya, sebagai pemberian saguhati menurut yang patut, lagi menjadi satu kewajipan atas orang-orang (yang mahu) berbuat kebaikan.', FALSE, NULL, NULL, 38, 2, 15, 32, FALSE, 0, NULL),
(2, 237, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّا أَن يَعْفُونَ أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ وَأَن تَعْفُوا أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا الْفَضْلَ بَيْنَكُمْ إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allāh, of whatever you do, is Seeing.', 'Dan jika kamu ceraikan mereka sebelum kamu sentuh (bercampur) dengan mereka, padahal kamu sudah menetapkan kadar maskahwin untuk mereka, maka mereka berhak mendapat separuh dari maskahwin yang telah kamu tetapkan itu, kecuali jika mereka memaafkannya tidak menuntutnya); atau (pihak) yang memegang ikatan nikah itu memaafkannya (memberikan maskahwin itu dengan sepenuhnya). Dan perbuatan kamu bermaaf-maafan (halal menghalalkan) itu lebih hampir kepada taqwa. Dan janganlah pula kamu lupa berbuat baik dan berbudi sesama sendiri. Sesungguhnya Allah sentiasa melihat akan apa jua yang kamu kerjakan.', FALSE, NULL, NULL, 38, 2, 15, 32, FALSE, 0, NULL),
(2, 238, 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 'حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ وَقُومُوا لِلَّهِ قَانِتِينَ', NULL, 'Maintain with care the [obligatory] prayers and [in particular] the middle [i.e., ʿaṣr] prayer and stand before Allāh, devoutly obedient.', 'Peliharalah kamu (kerjakanlah dengan tetap dan sempurna pada waktunya) segala sembahyang fardu, khasnya sembahyang Wusta (sembahyang Asar), dan berdirilah kerana Allah (dalam sembahyang kamu) dengan taat dan khusyuk.', FALSE, NULL, NULL, 39, 2, 15, 32, FALSE, 0, NULL),
(2, 239, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَا أَمِنتُمْ فَاذْكُرُوا اللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا تَعْلَمُونَ', NULL, 'And if you fear [an enemy, then pray] on foot or riding. But when you are secure, then remember Allāh [in prayer], as He has taught you that which you did not [previously] know.', 'Dan jika kamu takuti (sesuatu bahaya) maka sembahyanglah sambil berjalan atau berkenderaan, kemudian apabila kamu telah aman sentosa, maka hendaklah kamu mengingati Allah (dengan mengerjakan sembahyang secara yang lebih sempurna), sebagaimana Allah telah mengajar kamu apa yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 39, 2, 15, 32, FALSE, 0, NULL),
(2, 240, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لِّأَزْوَاجِهِم مَّتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِي مَا فَعَلْنَ فِي أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَاللَّهُ عَزِيزٌ حَكِيمٌ', NULL, 'And those who are taken in death among you and leave wives behind - for their wives is a bequest: maintenance for one year without turning [them] out. But if they leave [of their own accord], then there is no blame upon you for what they do with themselves in an acceptable way. And Allāh is Exalted in Might and Wise.', 'Dan orang-orang yang (hampir) mati di antara kamu serta meninggalkan isteri, hendaklah berwasiat untuk isteri-isteri mereka, iaitu diberi nafkah saguhati (makan, pakai dan tempat tinggal) hingga setahun lamanya, dengan tidak disuruh pindah dari tempat tinggalnya. Kemudian jika mereka keluar (dari tempat tinggalnya dengan kehendaknya sendiri) maka tidaklah kamu bersalah (wahai wali waris si mati) mengenai apa yang mereka (isteri-isteri itu) lakukan pada diri mereka dari perkara yang patut yang tidak dilarang Syarak) itu dan ingatlah, Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 39, 2, 15, 32, FALSE, 0, NULL),
(2, 241, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ', NULL, 'And for divorced women is a provision according to what is acceptable - a duty upon the righteous.', 'Dan isteri-isteri yang diceraikan berhak mendapat Mut''ah pemberian saguhati) dengan cara yang patut, sebagai satu tanggungan yang wajib atas orang-orang yang taqwa.', FALSE, NULL, NULL, 39, 2, 15, 32, FALSE, 0, NULL),
(2, 242, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَعْقِلُونَ', NULL, 'Thus does Allāh make clear to you His verses [i.e., laws] that you might use reason.', 'Demikianlah Allah menerangkan kepada kamu hukum-hukumnya supaya kamu memahaminya.', FALSE, NULL, NULL, 39, 2, 15, 32, FALSE, 0, NULL),
(2, 243, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'أَلَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِن دِيَارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ فَقَالَ لَهُمُ اللَّهُ مُوتُوا ثُمَّ أَحْيَاهُمْ إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', NULL, 'Have you not considered those who left their homes in many thousands, fearing death? Allāh said to them, "Die"; then He restored them to life. And Allāh is the possessor of bounty for the people, but most of the people do not show gratitude.', 'Tidakkah engkau ketahui (wahai Muhammad) tentang orang-orang yang keluar (melarikan diri) dari kampung halamannya kerana takutkan mati, sedang mereka beribu-ribu ramainya? Maka Allah berfirman kepada mereka: “Matilah kamu” kemudian Allah menghidupkan mereka. Sesungguhnya Allah sentiasa melimpah-limpah kurniaNya kepada manusia (seluruhnya), tetapi kebanyakan manusia tidak bersyukur.', FALSE, NULL, NULL, 39, 2, 16, 33, FALSE, 0, NULL),
(2, 244, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'وَقَاتِلُوا فِي سَبِيلِ اللَّهِ وَاعْلَمُوا أَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ', NULL, 'And fight in the cause of Allāh and know that Allāh is Hearing and Knowing.', 'Dan berperanglah kamu pada jalan Allah (kerana mempertahankan kebenaran ugamaNya); dan ketahuilah, sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 39, 2, 16, 33, FALSE, 0, NULL),
(2, 245, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', 'مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ أَضْعَافًا كَثِيرَةً وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'Who is it that would loan Allāh a goodly loan so He may multiply it for him many times over? And it is Allāh who withholds and grants abundance, and to Him you will be returned.', 'Siapakah orangnya yang (mahu) memberikan pinjaman kepada Allah sebagai pinjaman yang baik (yang ikhlas) supaya Allah melipatgandakan balasannya dengan berganda-ganda banyaknya? Dan (ingatlah), Allah jualah Yang menyempit dan Yang meluaskan (pemberian rezeki) dan kepadaNyalah kamu semua dikembalikan.', FALSE, NULL, NULL, 39, 2, 16, 33, FALSE, 0, NULL),
(2, 246, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'أَلَمْ تَرَ إِلَى الْمَلَإِ مِن بَنِي إِسْرَائِيلَ مِن بَعْدِ مُوسَىٰ إِذْ قَالُوا لِنَبِيٍّ لَّهُمُ ابْعَثْ لَنَا مَلِكًا نُّقَاتِلْ فِي سَبِيلِ اللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ الْقِتَالُ أَلَّا تُقَاتِلُوا قَالُوا وَمَا لَنَا أَلَّا نُقَاتِلَ فِي سَبِيلِ اللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَارِنَا وَأَبْنَائِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ تَوَلَّوْا إِلَّا قَلِيلًا مِّنْهُمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ', NULL, 'Have you not considered the assembly of the Children of Israel after [the time of] Moses when they said to a prophet of theirs, "Send to us a king, and we will fight in the way of Allāh"? He said, "Would you perhaps refrain from fighting if battle was prescribed for you?" They said, "And why should we not fight in the cause of Allāh when we have been driven out from our homes and from our children?" But when battle was prescribed for them, they turned away, except for a few of them. And Allāh is Knowing of the wrongdoers.', 'Tidakkah engkau ketahui (wahai muhammad), tentang (kisah) ketua-ketua dari Bani lsrail sesudah (wafatnya) Nabi Musa, ketika mereka berkata kepada seorang Nabi mereka: “Lantiklah seorang raja untuk kamu, supaya boleh kami berperang (bersama-sama dengannya) pada jalan Allah” Nabi mereka menjawab: “Tidakkah harus, jika kamu kelak diwajibkan berperang, kamu tidak akan berperang?,” Mereka berkata: “Mengapa pula kami tidak akan berperang pada jalan Allah, sedang kami telah diusir dari kampung halaman kami, dan (dari) anak-anak kami?” Maka apabila perang itu diwajibkan atas mereka, mereka membelakangkan kewajipan itu, kecuali sebahagian kecil dari mereka. Dan (ingatlah), Allah Maha Mengetahui akan orang-orang yang zalim.', FALSE, NULL, NULL, 40, 2, 16, 33, FALSE, 0, NULL),
(2, 247, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوا أَنَّىٰ يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ الْمَالِ قَالَ إِنَّ اللَّهَ اصْطَفَاهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ وَاللَّهُ يُؤْتِي مُلْكَهُ مَن يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'And their prophet said to them, "Indeed, Allāh has sent to you Saul as a king." They said, "How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?" He said, "Indeed, Allāh has chosen him over you and has increased him abundantly in knowledge and stature. And Allāh gives His sovereignty to whom He wills. And Allāh is all-Encompassing [in favor] and Knowing."', 'Dan Nabi mereka pula berkata kepada mereka: “Bahawasanya Allah telah melantik Talut menjadi raja bagi kamu. Mereka menjawab: “Bagaimana dia mendapat kuasa memerintah kami sedang kami lebih berhak dengan kuasa pemerintahan itu daripadanya, dan ia pula tidak diberi keluasan harta kekayaan?” Nabi mereka berkata: “Sesungguhnya Allah telah memilihnya (Talut) menjadi raja kamu, dan telah mengurniakannya kelebihan dalam lapangan ilmu pengetahuan dan kegagahan tubuh badan”. Dan (ingatlah), Allah jualah yang memberikan kuasa pemerintahan kepada sesiapa yang dikehendakiNya; dan Allah Maha Luas (rahmatNya dan pengurniaanNya), lagi meliputi ilmuNya.', FALSE, NULL, NULL, 40, 2, 16, 33, FALSE, 0, NULL),
(2, 248, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَن يَأْتِيَكُمُ التَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ آلُ مُوسَىٰ وَآلُ هَارُونَ تَحْمِلُهُ الْمَلَائِكَةُ إِنَّ فِي ذَٰلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'And their prophet said to them, "Indeed, a sign of his kingship is that the chest will come to you in which is assurance from your Lord and a remnant of what the family of Moses and the family of Aaron had left, carried by the angels. Indeed in that is a sign for you, if you are believers."', 'Dan Nabi mereka, berkata lagi kepada mereka: “Sesungguhnya tanda kerajaan Talut itu (yang menunjukkan benarnya dari Allah) ialah datangnya kepada kamu peti Tabut yang mengandungi (sesuatu yang memberi) ketenteraman jiwa dari Tuhan kamu, dan (berisi) sebahagian dari apa yang telah ditinggalkan oleh keluarga Nabi-nabi Musa dan Harun; peti Tabut itu dibawa oleh malaikat. Sesungguhnya peristiwa kembalinya Tabut itu mengandungi satu tanda keterangan bagi kamu jika betul kamu orang-orang yang beriman”.', FALSE, NULL, NULL, 40, 2, 16, 33, FALSE, 0, NULL),
(2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِ قَالَ إِنَّ اللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّي وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي إِلَّا مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ فَشَرِبُوا مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُ هُوَ وَالَّذِينَ آمَنُوا مَعَهُ قَالُوا لَا طَاقَةَ لَنَا الْيَوْمَ بِجَالُوتَ وَجُنُودِهِ قَالَ الَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَاقُو اللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ', NULL, 'And when Saul went forth with the soldiers, he said, "Indeed, Allāh will be testing you with a river. So whoever drinks from it is not of me, and whoever does not taste it is indeed of me, excepting one who takes [from it] in the hollow of his hand." But they drank from it, except a [very] few of them. Then when he had crossed it along with those who believed with him, they said, "There is no power for us today against Goliath and his soldiers." But those who were certain that they would meet Allāh said, "How many a small company has overcome a large company by permission of Allāh. And Allāh is with the patient."', 'Kemudian apabila Talut keluar bersama-sama tenteranya, berkatalah ia: “Sesungguhnya Allah akan menguji kamu dengan sebatang sungai, oleh itu sesiapa di antara kamu yang meminum airnya maka bukanlah ia dari pengikutku, dan sesiapa yang tidak merasai airnya maka sesungguhnya ia dari pengikutku, kecuali orang yang menceduk satu cedukan dengan tangannya”. (Sesudah diingatkan demikian) mereka meminum juga dari sungai itu (dengan sepuas-puasnya), kecuali sebahagian kecil dari mereka. Setelah Talut bersama-sama orang-orang yang beriman menyeberangi sungai itu, berkatalah orang-orang yang meminum (sepuas-puasnya): “Kami pada hari ini tidak terdaya menentang Jalut dan tenteranya”. Berkata pula orang-orang yang yakin bahawa mereka akan menemui Allah: “Berapa banyak (yang pernah terjadi), golongan yang sedikit berjaya menewaskan golongan yang banyak dengan izin Allah; dan Allah (sentiasa) bersama-sama orang-orang yang sabar”.', FALSE, NULL, NULL, 41, 2, 16, 34, FALSE, 0, NULL),
(2, 250, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'وَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِهِ قَالُوا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', NULL, 'And when they went forth to [face] Goliath and his soldiers, they said, "Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people."', 'Dan apabila mereka (yang beriman itu) keluar menentang Jalut dan tenteranya, mereka berdoa dengan berkata: “Wahai Tuhan kami! Limpahkanlah sabar kepada kami, dan teguhkanlah tapak pendirian kami serta menangkanlah kami terhadap kaum yang kafir”', FALSE, NULL, NULL, 41, 2, 16, 34, FALSE, 0, NULL),
(2, 251, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', 'فَهَزَمُوهُم بِإِذْنِ اللَّهِ وَقَتَلَ دَاوُودُ جَالُوتَ وَآتَاهُ اللَّهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشَاءُ وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ الْأَرْضُ وَلَٰكِنَّ اللَّهَ ذُو فَضْلٍ عَلَى الْعَالَمِينَ', NULL, 'So they defeated them by permission of Allāh, and David killed Goliath, and Allāh gave him the kingship and wisdom [i.e., prophethood] and taught him from that which He willed. And if it were not for Allāh checking [some] people by means of others, the earth would have been corrupted, but Allāh is the possessor of bounty for the worlds.', 'Oleh sebab itu, mereka dapat mengalahkan tentera Jalut dengan izin Allah, dan Nabi Daud (yang turut serta dalam tentera Talut) membunuh Jalut. Dan (sesudah itu) Allah memberikan kepadanya (Nabi Daud) kuasa pemerintahan, dan hikmat (pangkat kenabian) serta diajarkannya apa yang dikehendakiNya. Dan kalaulah Allah tidak menolak setengah manusia (yang ingkar dan derhaka) dengan setengahnya yang lain (yang beriman dan setia) nescaya rosak binasalah bumi ini; akan tetapi Allah sentiasa melimpah kurniaNya kepada sekalian alam.', FALSE, NULL, NULL, 41, 2, 16, 34, FALSE, 0, NULL),
(2, 252, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ', NULL, 'These are the verses of Allāh which We recite to you, [O Muḥammad], in truth. And indeed, you are from among the messengers.', 'Itulah ayat-ayat keterangan Allah yang kami bacakan dia kepadamu (wahai Muhammad) dengan benar; dan sesungguhnya engkau adalah salah seorang dari Rasul-rasul (yang diutuskan oleh) Allah.', FALSE, NULL, NULL, 41, 2, 16, 34, FALSE, 0, NULL),
(2, 253, 'تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'تِلْكَ الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ اللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَاتٍ وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ وَلَوْ شَاءَ اللَّهُ مَا اقْتَتَلَ الَّذِينَ مِن بَعْدِهِم مِّن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ وَلَٰكِنِ اخْتَلَفُوا فَمِنْهُم مَّنْ آمَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَاءَ اللَّهُ مَا اقْتَتَلُوا وَلَٰكِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ', NULL, 'Those messengers - some of them We caused to exceed others. Among them were those to whom Allāh spoke, and He raised some of them in degree. And We gave Jesus, the son of Mary, clear proofs, and We supported him with the Pure Spirit [i.e., Gabriel]. If Allāh had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allāh had willed, they would not have fought each other, but Allāh does what He intends.', 'Rasul-rasul Kami lebihkan sebahagian daripada mereka atas sebahagian yang lain (dengan kelebihan-kelebihan yang tertentu). Di antara mereka ada yang Allah berkata-kata dengannya, dan ditinggikanNya (pangkat) sebahagian daripada mereka beberapa darjat kelebihan. Dan Kami berikan Nabi Isa ibni Maryam beberapa keterangan kebenaran (mukjizat), serta Kami kuatkan dia dengan Ruhul-Qudus (Jibril). Dan sekiranya Allah menghendaki nescaya orang-orang yang datang kemudian daripada Rasul-rasul itu tidak berbunuh-bunuhan sesudah datang kepada mereka keterangan-keterangan (yang dibawa oleh Rasul mereka). Tetapi mereka bertelingkah, maka timbulah di antara mereka: orang yang beriman, dan orang yang kafir. Dan kalaulah Allah menghendaki tentulah mereka tidak berbunuh-bunuhan; tetapi Allah melakukan apa yang dikehendakiNya.', FALSE, NULL, NULL, 42, 3, 17, 34, FALSE, 0, NULL),
(2, 254, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَٰعَةٌ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَاعَةٌ وَالْكَافِرُونَ هُمُ الظَّالِمُونَ', NULL, 'O you who have believed, spend from that which We have provided for you before there comes a Day in which there is no exchange [i.e., ransom] and no friendship and no intercession. And the disbelievers - they are the wrongdoers.', 'Wahai orang-orang yang beriman! Sebarkanlah sebahagian dari apa yang telah Kami berikan kepada kamu, sebelum tibanya hari (kiamat) yang tidak ada jual-beli padanya, dan tidak ada kawan teman (yang memberi manfaat), serta tidak ada pula pertolongan syafaat. Dan orang-orang kafir, mereka itulah orang-orang yang zalim.', FALSE, NULL, NULL, 42, 3, 17, 35, FALSE, 0, NULL),
(2, 255, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ', NULL, 'Allāh - there is no deity except Him, the Ever-Living, the Self-Sustaining. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursī extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 'Allah, tiada Tuhan (yang berhak disembah) melainkan Dia, Yang Tetap hidup, Yang Kekal selama-lamanya mentadbirkan (sekalian makhlukNya). Yang tidak mengantuk usahkan tidur. Yang memiliki segala yang ada di langit dan yang ada di bumi. Tiada sesiapa yang dapat memberi syafaat (pertolongan) di sisiNya melainkan dengan izinNya. yang mengetahui apa yang ada di hadapan mereka dan apa yang ada di belakang mereka, sedang mereka tidak mengetahui sesuatu pun dari (kandungan) ilmu Allah melainkan apa yang Allah kehendaki (memberitahu kepadanya). Luasnya Kursi Allah (ilmuNya dan kekuasaanNya) meliputi langit dan bumi; dan tiadalah menjadi keberatan kepada Allah menjaga serta memelihara keduanya. Dan Dia lah Yang Maha Tinggi (darjat kemuliaanNya), lagi Maha Besar (kekuasaanNya)', FALSE, NULL, NULL, 42, 3, 17, 35, FALSE, 0, NULL),
(2, 256, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'لَا إِكْرَاهَ فِي الدِّينِ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'There shall be no compulsion in [acceptance of] the religion. The right course has become distinct from the wrong. So whoever disbelieves in ṭāghūt and believes in Allāh has grasped the most trustworthy handhold with no break in it. And Allāh is Hearing and Knowing.', 'Tidak ada paksaan dalam ugama (Islam), kerana sesungguhnya telah nyata kebenaran (Islam) dari kesesatan (kufur). Oleh itu, sesiapa yang tidak percayakan Taghut, dan ia pula beriman kepada Allah, maka sesungguhnya ia telah berpegang kepada simpulan (tali ugama) yang teguh yang tidak akan putus. Dan (ingatlah), Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 42, 3, 17, 35, FALSE, 0, NULL),
(2, 257, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُم مِّنَ النُّورِ إِلَى الظُّلُمَاتِ أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'Allāh is the Ally of those who believe. He brings them out from darknesses into the light. And those who disbelieve - their allies are ṭāghūt. They take them out of the light into darknesses. Those are the companions of the Fire; they will abide eternally therein.', 'Allah Pelindung (Yang mengawal dan menolong) orang-orang yang beriman. Ia mengeluarkan mereka dari kegelapan (kufur) kepada cahaya (iman). Dan orang-orang yang kafir, penolong-penolong mereka ialah Taghut yang mengeluarkan mereka dari cahaya (iman) kepada kegelapan (kufur). Mereka itulah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 43, 3, 17, 35, FALSE, 0, NULL),
(2, 258, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'أَلَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْرَاهِيمَ فِي رَبِّهِ أَنْ آتَاهُ اللَّهُ الْمُلْكَ إِذْ قَالَ إِبْرَاهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ قَالَ أَنَا أُحْيِي وَأُمِيتُ قَالَ إِبْرَاهِيمُ فَإِنَّ اللَّهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِي كَفَرَ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'Have you not considered the one who argued with Abraham about his Lord [merely] because Allāh had given him kingship? When Abraham said, "My Lord is the one who gives life and causes death," he said, "I give life and cause death." Abraham said, "Indeed, Allāh brings up the sun from the east, so bring it up from the west." So the disbeliever was overwhelmed [by astonishment], and Allāh does not guide the wrongdoing people.', 'Tidakkah engkau (pelik) memikirkan (wahai Muhammad) tentang orang yang berhujah membantah Nabi Ibrahim (dengan sombongnya) mengenai Tuhannya, kerana Allah memberikan orang itu kuasa pemerintahan? Ketika Nabi Ibrahim berkata: “Tuhanku ialah Yang menghidupkan dan Yang mematikan”. Ia menjawab: “Aku juga boleh menghidupkan dan mematikan”. Nabi Ibrahim berkata lagi: “Sesungguhnya Allah menerbitkan matahari dari timur, oleh itu terbitkanlah dia dari barat?” Maka tercenganglah orang yang kafir itu (lalu diam membisu). Dan (ingatlah), Allah tidak akan memberikan petunjuk kepada kaum yang zalim.', FALSE, NULL, NULL, 43, 3, 17, 36, FALSE, 0, NULL),
(2, 259, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'أَوْ كَالَّذِي مَرَّ عَلَىٰ قَرْيَةٍ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْيِي هَٰذِهِ اللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ اللَّهُ مِائَةَ عَامٍ ثُمَّ بَعَثَهُ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِائَةَ عَامٍ فَانظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَانظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ آيَةً لِّلنَّاسِ وَانظُرْ إِلَى الْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُ قَالَ أَعْلَمُ أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said, "How will Allāh bring this to life after its death?" So Allāh caused him to die for a hundred years; then He revived him. He said, "How long have you remained?" He [the man] said, "I have remained a day or part of a day." He said, "Rather, you have remained one hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of this donkey] - how We raise them and then We cover them with flesh." And when it became clear to him, he said, "I know that Allāh is over all things competent."', 'Atau (tidakkah engkau pelik memikirkan wahai Muhammad) tentang orang yang melalui sebuah negeri yang telah runtuh segala bangunannya, orang itu berkata: “Bagaimana Allah akan menghidupkan (membina semula) negeri ini sesudah matinya (rosak binasanya)?” Lalu ia dimatikan oleh Allah (dan dibiarkan tidak berubah) selama seratus tahun, kemudian Allah hidupkan dia semula lalu bertanya kepadanya: “Berapa lama engkau tinggal (di sini)?” Ia menjawab: “Aku telah tinggal (di sini) sehari atau setengah hari”. Allah berfirman: “(Tidak benar), bahkan engkau telah tinggal (berkeadaan demikian) selama seratus tahun. Oleh itu, perhatikanlah kepada makanan dan minumanmu, masih tidak berubah keadaannya, dan perhatikanlah pula kepada keldaimu (hanya tinggal tulang-tulangnya bersepah), dan Kami (lakukan ini ialah untuk) menjadikan engkau sebagai tanda (kekuasaan Kami) bagi umat manusia; dan lihatlah kepada tulang-tulang (keldai) itu, bagaimana Kami menyusunnya kembali kemudian Kami menyalutnya dengan daging”. Maka apabila telah jelas kepadanya (apa yang berlaku itu), berkatalah dia: Sekarang aku mengetahuinya (dengan yakin), sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu”.', FALSE, NULL, NULL, 43, 3, 17, 36, FALSE, 0, NULL),
(2, 260, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِي قَالَ فَخُذْ أَرْبَعَةً مِّنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْيًا وَاعْلَمْ أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, 'And [mention] when Abraham said, "My Lord, show me how You give life to the dead." [Allāh] said, "Have you not believed?" He said, "Yes, but [I ask] only that my heart may be satisfied." [Allāh] said, "Take four birds and commit them to yourself. Then [after slaughtering them] put on each hill a portion of them; then call them - they will come [flying] to you in haste. And know that Allāh is Exalted in Might and Wise."', 'Dan (ingatlah) ketika Nabi Ibrahim (merayu dengan) berkata: “Wahai Tuhanku! Perlihatkanlah kepadaku bagaimana Engkau menghidupkan makhluk-makhluk yang mati?” Allah berfirman: “Adakah engkau belum percaya (kepada kekuasaanku)?” Nabi Ibrahim menjawab: “Bahkan (aku percaya dan yakin), akan tetapi (aku memohon yang demikian ialah) supaya tenteram hatiku (yang amat ingin menyaksikannya)”. Allah berfirman: “(Jika demikian), ambilah empat ekor burung, kemudian kumpulkanlah olehmu (dan cincanglah semuanya). Setelah itu letakkanlah di atas tiap-tiap sebuah bukit sebahagian daripadanya. Kemudian serulah burung-burung itu nescaya semuanya akan datang kepadamu dengan segera”. Dan ketahuilah sesungguhnya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 44, 3, 17, 36, FALSE, 0, NULL),
(2, 261, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'مَّثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنبُلَةٍ مِّائَةُ حَبَّةٍ وَاللَّهُ يُضَاعِفُ لِمَن يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'The example of those who spend their wealth in the way of Allāh is like a seed [of grain] which grows seven spikes; in each spike is a hundred grains. And Allāh multiplies [His reward] for whom He wills. And Allāh is all-Encompassing and Knowing.', 'Bandingan (derma) orang-orang yang membelanjakan hartanya pada jalan Allah, ialah sama seperti sebiji benih yang tumbuh menerbitkan tujuh tangkai; tiap-tiap tangkai itu pula mengandungi seratus biji. Dan (ingatlah), Allah akan melipatgandakan pahala bagi sesiapa yang dikehendakiNya, dan Allah Maha Luas (rahmat) kurniaNya, lagi Meliputi ilmu pengetahuanNya.', FALSE, NULL, NULL, 44, 3, 17, 37, FALSE, 0, NULL),
(2, 262, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ ثُمَّ لَا يُتْبِعُونَ مَا أَنفَقُوا مَنًّا وَلَا أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Those who spend their wealth in the way of Allāh and then do not follow up what they have spent with reminders [of it] or [other] injury will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.', 'Orang-orang yang membelanjakan hartanya pada jalan (ugama) Allah, kemudian mereka tidak mengiringi apa yang mereka belanjakan itu dengan perkataan membangkit-bangkit (pemberiannya), dan tidak pula menyinggung atau menyakiti (pihak yang diberi), mereka beroleh pahala di sisi Tuhan mereka, dan tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 44, 3, 17, 37, FALSE, 0, NULL),
(2, 263, 'قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى وَٱللَّهُ غَنِىٌّ حَلِيمٌ', 'قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَا أَذًى وَاللَّهُ غَنِيٌّ حَلِيمٌ', NULL, 'Kind speech and forgiveness are better than charity followed by injury. And Allāh is Free of need and Forbearing.', '(Menolak peminta-peminta sedekah) dengan perkataan yang baik dan memaafkan (kesilapan mereka) adalah lebih baik daripada sedekah (pemberian) yang diiringi (dengan perbuatan atau perkataan yang) menyakitkan hati. Dan (ingatlah), Allah Maha Kaya, lagi Maha Penyabar.', FALSE, NULL, NULL, 44, 3, 18, 37, FALSE, 0, NULL),
(2, 264, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُم بِالْمَنِّ وَالْأَذَىٰ كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَمَثَلُهُ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُ وَابِلٌ فَتَرَكَهُ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَيْءٍ مِّمَّا كَسَبُوا وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ', NULL, 'O you who have believed, do not invalidate your charities with reminders [of it] or injury as does one who spends his wealth [only] to be seen by the people and does not believe in Allāh and the Last Day. His example is like that of a [large] smooth stone upon which is dust and is hit by a downpour that leaves it bare. They are unable [to keep] anything of what they have earned. And Allāh does not guide the disbelieving people.', 'Wahai orang-orang yang beriman! Jangan rosakkan (pahala amal) sedekah kamu dengan perkataan membangkit-bangkit dan (kelakuan yang) menyakiti, seperti (rosaknya pahala amal sedekah) orang yang membelanjakan hartanya kerana hendak menunjuk-nunjuk kepada manusia (riak), dan ia pula tidak beriman kepada Allah dan hari akhirat. Maka bandingan orang itu ialah seperti batu licin yang ada tanah di atasnya, kemudian batu itu ditimpa hujan lebat, lalu ditinggalkannya bersih licin (tidak bertanah lagi). (Demikianlah juga halnya orang-orang yang kafir dan riak itu) mereka tidak akan mendapat sesuatu (pahala) pun dari apa yang mereka usahakan. Dan (ingatlah), Allah tidak akan memberi petunjuk kepada kaum yang kafir.', FALSE, NULL, NULL, 44, 3, 18, 37, FALSE, 0, NULL),
(2, 265, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'وَمَثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَآتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'And the example of those who spend their wealth seeking means to the approval of Allāh and assuring [reward for] themselves is like a garden on high ground which is hit by a downpour - so it yields its fruits in double. And [even] if it is not hit by a downpour, then a drizzle [is sufficient]. And Allāh, of what you do, is Seeing.', 'Dan bandingan orang-orang yang membelanjakan hartanya kerana mencari keredaan Allah dan kerana meneguhkan (iman dan perasaan ikhlas) yang timbul dari jiwa mereka, adalah seperti sebuah kebun di tempat yang tinggi, yang ditimpa hujan lebat, lalu mengeluarkan hasilnya dua kali ganda. Kalau ia tidak ditimpa hujan lebat maka hujan renyai-renyai pun (cukup untuk menyiraminya). Dan (ingatlah), Allah sentiasa Melihat akan apa yang kamu lakukan.', FALSE, NULL, NULL, 45, 3, 18, 37, FALSE, 0, NULL),
(2, 266, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ لَهُ فِيهَا مِن كُلِّ الثَّمَرَاتِ وَأَصَابَهُ الْكِبَرُ وَلَهُ ذُرِّيَّةٌ ضُعَفَاءُ فَأَصَابَهَا إِعْصَارٌ فِيهِ نَارٌ فَاحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', NULL, 'Would one of you like to have a garden of palm trees and grapevines underneath which rivers flow in which he has from every fruit? But he is afflicted with old age and has weak [i.e., immature] offspring, and it is hit by a whirlwind containing fire and is burned. Thus does Allāh make clear to you [His] verses that you might give thought.', 'Adakah seseorang di antara kamu suka mempunyai sebuah kebun dari pokok tamar (kurma) dan anggur, yang mengalir di bawahnya beberapa sungai, ia juga mempunyai dalam kebun itu segala jenis buah-buahan, sedang ia sudah tua dan mempunyai banyak anak cucu yang masih kecil, lalu kebun itu diserang oleh angin taufan yang membawa api sehingga terbakarlah ia? Demikianlah Allah menjelaskan kepada kamu keterangan-keterangan, supaya kamu berfikir (dan mengambil iktibar).', FALSE, NULL, NULL, 45, 3, 18, 37, FALSE, 0, NULL),
(2, 267, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِن طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُم مِّنَ الْأَرْضِ وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِآخِذِيهِ إِلَّا أَن تُغْمِضُوا فِيهِ وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ حَمِيدٌ', NULL, 'O you who have believed, spend from the good things which you have earned and from that which We have produced for you from the earth. And do not aim toward the defective therefrom, spending [from that] while you would not take it [yourself] except with closed eyes. And know that Allāh is Free of need and Praiseworthy.', 'Wahai orang-orang yang beriman! Belanjakanlah (pada jalan Allah) sebahagian dari hasil usaha kamu yang baik-baik, dan sebahagian dari apa yang Kami keluarkan dari bumi untuk kamu. Dan janganlah kamu sengaja memilih yang buruk daripadanya (lalu kamu dermakan atau kamu jadikan pemberian zakat), padahal kamu sendiri tidak sekali-kali akan mengambil yang buruk itu (kalau diberikan kepada kamu), kecuali dengan memejamkan mata padanya. Dan ketahuilah, sesungguhnya Allah Maha Kaya, lagi sentiasa Terpuji.', FALSE, NULL, NULL, 45, 3, 18, 38, FALSE, 0, NULL),
(2, 268, 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'الشَّيْطَانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُم بِالْفَحْشَاءِ وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'Satan threatens you with poverty and orders you to immorality, while Allāh promises you forgiveness from Him and bounty. And Allāh is all-Encompassing and Knowing.', 'Syaitan itu menjanjikan (menakut-nakutkan) kamu dengan kemiskinan dan kepapaan (jika kamu bersedekah atau menderma), dan ia menyuruh kamu melakukan perbuatan yang keji (bersifat bakhil kedekut); sedang Allah menjanjikan kamu (dengan) keampunan daripadaNya serta kelebihan kurniaNya. Dan (ingatlah), Allah Maha Luas limpah rahmatNya, lagi sentiasa Meliputi PengetahuanNya.', FALSE, NULL, NULL, 45, 3, 18, 38, FALSE, 0, NULL),
(2, 269, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'يُؤْتِي الْحِكْمَةَ مَن يَشَاءُ وَمَن يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ', NULL, 'He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good. And none will remember except those of understanding.', 'Allah memberikan Hikmat kebijaksanaan (ilmu yang berguna) kepada sesiapa yang dikehendakiNya (menurut aturan yang ditentukanNya). Dan sesiapa yang diberikan hikmat itu maka sesungguhnya ia telah diberikan kebaikan yang banyak. Dan tiadalah yang dapat mengambil pengajaran (dan peringatan) melainkan orang-orang yang menggunakan akal fikirannya.', FALSE, NULL, NULL, 45, 3, 18, 38, FALSE, 0, NULL),
(2, 270, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'وَمَا أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ', NULL, 'And whatever you spend of expenditures or make of vows - indeed, Allāh knows of it. And for the wrongdoers there are no helpers.', 'Dan (ketahuilah), apa sahaja yang kamu belanjakan (dermakan) atau apa sahaja yang kamu nazarkan maka sesungguhnya Allah mengetahuiNya dan (ingatlah), orang-orang yang zalim itu tidak ada sesiapa pun yang dapat menolongnya.', FALSE, NULL, NULL, 46, 3, 18, 38, FALSE, 0, NULL),
(2, 271, 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'إِن تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّئَاتِكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', NULL, 'If you disclose your charitable expenditures, they are good; but if you conceal them and give them to the poor, it is better for you, and He will remove from you some of your misdeeds [thereby]. And Allāh, of what you do, is [fully] Aware.', 'Kalau kamu zahirkan sedekah-sedekah itu (secara terang), maka yang demikian adalah baik (kerana menjadi contoh yang baik). Dan kalau pula kamu sembunyikan sedekah-sedekah itu serta kamu berikan kepada orang-orang fakir miskin, maka itu adalah baik bagi kamu; dan Allah akan menghapuskan dari kamu sebahagian dari kesalahan-kesalahan kamu. Dan (ingatlah), Allah Maha Mengetahui secara mendalam akan apa yang kamu lakukan.', FALSE, NULL, NULL, 46, 3, 18, 38, FALSE, 0, NULL),
(2, 272, 'لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'لَّيْسَ عَلَيْكَ هُدَاهُمْ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ وَمَا تُنفِقُوا مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ابْتِغَاءَ وَجْهِ اللَّهِ وَمَا تُنفِقُوا مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', NULL, 'Not upon you, [O Muḥammad], is [responsibility for] their guidance, but Allāh guides whom He wills. And whatever good you [believers] spend is for yourselves, and you do not spend except seeking the face [i.e., approval] of Allāh. And whatever you spend of good - it will be fully repaid to you, and you will not be wronged.', 'Tidaklah engkau diwajibkan (wahai Muhammad) menjadiKan mereka (yang kafir) mendapat petunjuk (kerana kewajipanmu hanya menyampaikan petunjuk), akan tetapi Allah jualah yang memberi petunjuk (dengan memberi taufik) kepada sesiapa yang dikehendakinya (menurut undang-undang peraturanNya). Dan apa jua harta yang halal yang kamu belanjakan (pada jalan Allah) maka (faedahnya dan pahalanya) adalah untuk diri kamu sendiri dan kamu pula tidaklah mendermakan sesuatu melainkan kerana menuntut keredaan Allah dan apa jua yang kamu dermakan dari harta yang halal, akan disempurnakan (balasan pahalanya) kepada kamu, dan (balasan baik) kamu (itu pula) tidak dikurangkan.', FALSE, NULL, NULL, 46, 3, 19, 38, FALSE, 0, NULL),
(2, 273, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'لِلْفُقَرَاءِ الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِي الْأَرْضِ يَحْسَبُهُمُ الْجَاهِلُ أَغْنِيَاءَ مِنَ التَّعَفُّفِ تَعْرِفُهُم بِسِيمَاهُمْ لَا يَسْأَلُونَ النَّاسَ إِلْحَافًا وَمَا تُنفِقُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ', NULL, '[Charity is] for the poor who have been restricted for the cause of Allāh, unable to move about in the land. An ignorant [person] would think them self-sufficient because of their restraint, but you will know them by their [characteristic] sign. They do not ask people persistently [or at all]. And whatever you spend of good - indeed, Allāh is Knowing of it.', 'Pemberian sedekah itu) ialah bagi orang-orang fakir miskin yang telah menentukan dirinya (dengan menjalankan khidmat atau berjuang) pada jalan Allah (membela Islam), yang tidak berupaya mengembara di muka bumi (untuk berniaga dan sebagainya); mereka itu disangka: orang kaya - oleh orang yang tidak mengetahui halnya, kerana mereka menahan diri daripada meminta-minta. Engkau kenal mereka dengan (melihat) sifat-sifat dan keadaan masing-masing, mereka tidak meminta kepada orang ramai dengan mendesak-desak. Dan (ketahuilah), apa jua yang kamu belanjakan dari harta yang halal maka sesungguhnya Allah sentiasa Mengetahuinya.', FALSE, NULL, NULL, 46, 3, 19, 38, FALSE, 0, NULL),
(2, 274, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'الَّذِينَ يُنفِقُونَ أَمْوَالَهُم بِاللَّيْلِ وَالنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Those who spend their wealth [in Allāh''s way] by night and by day, secretly and publicly - they will have their reward with their Lord. And no fear will there be concerning them, nor will they grieve.', 'Orang-orang yang membelanjakan (mendermakan) hartanya pada waktu malam dan siang, dengan cara sulit atau terbuka, maka mereka beroleh pahala di sisi Tuhan mereka, dan tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, serta mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 46, 3, 19, 39, FALSE, 0, NULL),
(2, 275, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'الَّذِينَ يَأْكُلُونَ الرِّبَا لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَن جَاءَهُ مَوْعِظَةٌ مِّن رَّبِّهِ فَانتَهَىٰ فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'Those who consume interest cannot stand [on the Day of Resurrection] except as one stands who is being beaten by Satan into insanity. That is because they say, "Trade is [just] like interest." But Allāh has permitted trade and has forbidden interest. So whoever has received an admonition from his Lord and desists may have what is past, and his affair rests with Allāh. But whoever returns [to dealing in interest or usury] - those are the companions of the Fire; they will abide eternally therein.', 'Orang-orang yang memakan (mengambil) riba itu tidak dapat berdiri betul melainkan seperti berdirinya orang yang dirasuk Syaitan dengan terhuyung-hayang kerana sentuhan (Syaitan) itu. Yang demikian ialah disebabkan mereka mengatakan: “Bahawa sesungguhnya berniaga itu sama sahaja seperti riba”. Padahal Allah telah menghalalkan berjual-beli (berniaga) dan mengharamkan riba. Oleh itu sesiapa yang telah sampai kepadanya peringatan (larangan) dari Tuhannya lalu ia berhenti (dari mengambil riba), maka apa yang telah diambilnya dahulu (sebelum pengharaman itu) adalah menjadi haknya, dan perkaranya terserahlah kepada Allah. Dan sesiapa yang mengulangi lagi (perbuatan mengambil riba itu) maka itulah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 276, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', 'يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ وَاللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', NULL, 'Allāh destroys interest and gives increase for charities. And Allāh does not like every sinning disbeliever.', 'Allah susutkan (kebaikan harta yang dijalankan dengan mengambil) riba dan Ia pula mengembangkan (berkat harta yang dikeluarkan) sedekah-sedekah dan zakatnya. Dan Allah tidak suka kepada tiap-tiap orang yang kekal terus dalam kekufuran, dan selalu melakukan dosa.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 277, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Indeed, those who believe and do righteous deeds and establish prayer and give zakāh will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, dan mengerjakan sembahyang serta memberikan zakat, mereka beroleh pahala di sisi Tuhan mereka, dan tidak ada kebimbangan (dari berlakunya sesuatu yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 278, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِن كُنتُم مُّؤْمِنِينَ', NULL, 'O you who have believed, fear Allāh and give up what remains [due to you] of interest, if you should be believers.', 'Wahai orang-orang yang beriman! Bertaqwalah kamu kepada Allah dan tinggalkanlah (jangan menuntut lagi) saki baki riba (yang masih ada pada orang yang berhutang) itu, jika benar kamu orang- orang yang beriman.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 279, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', 'فَإِن لَّمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِّنَ اللَّهِ وَرَسُولِهِ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', NULL, 'And if you do not, then be informed of a war [against you] from Allāh and His Messenger. But if you repent, you may have your principal - [thus] you do no wrong, nor are you wronged.', 'Oleh itu, kalau kamu tidak juga melakukan (perintah mengenai larangan riba itu), maka ketahuilah kamu: akan adanya peperangan dari Allah dan RasulNya, (akibatnya kamu tidak menemui selamat). Dan jika kamu bertaubat, maka hak kamu (yang sebenarnya) ialah pokok asal harta kamu. (Dengan yang demikian) kamu tidak berlaku zalim kepada sesiapa, dan kamu juga tidak dizalimi oleh sesiapa.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 280, 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', NULL, 'And if someone is in hardship, then [let there be] postponement until [a time of] ease. But if you give [from your right as] charity, then it is better for you, if you only knew.', 'Dan jika orang yang berhutang itu sedang mengalami kesempitan hidup, maka berilah tempoh sehingga ia lapang hidupnya dan (sebaliknya) bahawa kamu sedekahkan hutang itu (kepadanya) adalah lebih baik untuk kamu, kalau kamu mengetahui (pahalanya yang besar yang kamu akan dapati kelak).', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 281, 'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And fear a Day when you will be returned to Allāh. Then every soul will be compensated for what it earned, and they will not be wronged [i.e., treated unjustly].', 'Dan peliharalah diri kamu dari huru-hara hari (kiamat) yang padanya kamu akan dikembalikan kepada Allah. Kemudian akan disempurnakan balasan tiap-tiap seorang menurut apa yang telah diusahakannya, sedang mereka tidak dikurangkan balasannya sedikitpun.', FALSE, NULL, NULL, 47, 3, 19, 39, FALSE, 0, NULL),
(2, 282, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَيُعَلِّمُكُمُ ٱللَّهُ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌ بِالْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ اللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللَّهَ رَبَّهُ وَلَا يَبْخَسْ مِنْهُ شَيْئًا فَإِن كَانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ الشُّهَدَاءِ أَن تَضِلَّ إِحْدَاهُمَا فَتُذَكِّرَ إِحْدَاهُمَا الْأُخْرَىٰ وَلَا يَأْبَ الشُّهَدَاءُ إِذَا مَا دُعُوا وَلَا تَسْأَمُوا أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰ أَجَلِهِ ذَٰلِكُمْ أَقْسَطُ عِندَ اللَّهِ وَأَقْوَمُ لِلشَّهَادَةِ وَأَدْنَىٰ أَلَّا تَرْتَابُوا إِلَّا أَن تَكُونَ تِجَارَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ وَلَا يُضَارَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا فَإِنَّهُ فُسُوقٌ بِكُمْ وَاتَّقُوا اللَّهَ وَيُعَلِّمُكُمُ اللَّهُ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'O you who have believed, when you contract a debt for a specified term, write it down. And let a scribe write [it] between you in justice. Let no scribe refuse to write as Allāh has taught him. So let him write and let the one who has the obligation [i.e., the debtor] dictate. And let him fear Allāh, his Lord, and not leave anything out of it. But if the one who has the obligation is of limited understanding or weak or unable to dictate himself, then let his guardian dictate in justice. And bring to witness two witnesses from among your men. And if there are not two men [available], then a man and two women from those whom you accept as witnesses - so that if one of them [i.e., the women] errs, then the other can remind her. And let not the witnesses refuse when they are called upon. And do not be [too] weary to write it, whether it is small or large, for its [specified] term. That is more just in the sight of Allāh and stronger as evidence and more likely to prevent doubt between you, except when it is an immediate transaction which you conduct among yourselves. For [then] there is no blame upon you if you do not write it. And take witnesses when you conclude a contract. Let no scribe be harmed or any witness. For if you do so, indeed, it is [grave] disobedience in you. And fear Allāh. And Allāh teaches you. And Allāh is Knowing of all things.', 'Wahai orang-orang yang beriman! Apabila kamu menjalankan sesuatu urusan dengan hutang piutang yang diberi tempoh hingga ke suatu masa yang tertentu maka hendaklah kamu menulis (hutang dan masa bayarannya) itu dan hendaklah seorang penulis di antara kamu menulisnya dengan adil (benar) dan janganlah seseorang penulis enggan menulis sebagaimana Allah telah mengajarkannya. Oleh itu, hendaklah ia menulis dan hendaklah orang yang berhutang itu merencanakan (isi surat hutang itu dengan jelas). Dan hendaklah ia bertaqwa kepada Allah Tuhannya, dan janganlah ia mengurangkan sesuatu pun dari hutang itu. Kemudian jika orang yang berhutang itu bodoh atau lemah atau ia sendiri tidak dapat hendak merencanakan (isi itu), maka hendaklah direncanakan oleh walinya dengan adil benar); dan hendaklah kamu mengadakan dua orang saksi lelaki dari kalangan kamu. Kemudian kalau tidak ada saksi dua orang lelaki, maka bolehlah, seorang lelaki dan dua orang perempuan dari orang-orang yang kamu setujui menjadi saksi, supaya jika yang seorang lupa dari saksi-saksi perempuan yang berdua itu maka dapat diingatkan oleh yang seorang lagi. Dan jangan saksi-saksi itu enggan apabila mereka dipanggil menjadi saksi. Dan janganlah kamu jemu menulis perkara hutang yang bertempoh masanya itu, sama ada kecil atau besar jumlahnya. Yang demikian itu, lebih adil di sisi Allah dan lebih membetulkan (menguatkan) keterangan saksi, dan juga lebih hampir kepada tidak menimbulkan keraguan kamu. Kecuali perkara itu mengenai perniagaan tunai yang kamu edarkan sesama sendiri, maka tiadalah salah jika kamu tidak menulisnya. Dan adakanlah saksi apabila kamu berjual-beli. Dan janganlah mana-mana jurutulis dan saksi itu disusahkan. Dan kalau kamu melakukan (apa yang dilarang itu), maka sesungguhnya yang demikian adalah perbuatan fasik (derhaka) yang ada pada kamu. Oleh itu hendaklah kamu bertaqwa kepada Allah; dan (ingatlah), Allah (dengan keterangan ini) mengajar kamu; dan Allah sentiasa Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 48, 3, 19, 40, FALSE, 0, NULL),
(2, 283, 'وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَٰنٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمَانَتَهُ وَلْيَتَّقِ اللَّهَ رَبَّهُ وَلَا تَكْتُمُوا الشَّهَادَةَ وَمَن يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', NULL, 'And if you are on a journey and cannot find a scribe, then a security deposit [should be] taken. And if one of you entrusts another, then let him who is entrusted discharge his trust [faithfully] and let him fear Allāh, his Lord. And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allāh is Knowing of what you do.', 'Dan jika kamu berada dalam musafir (lalu kamu berhutang atau memberi hutang yang bertempoh), sedang kamu tidak mendapati jurutulis, maka hendaklah diadakan barang gadaian untuk dipegang (oleh orang yang memberi hutang). Kemudian kalau yang memberi hutang percaya kepada yang berhutang (dengan tidak payah bersurat, saksi dan barang gadaian), maka hendaklah orang (yang berhutang) yang dipercayai itu menyempurnakan bayaran hutang yang diamanahkan kepadanya, dan hendaklah ia bertaqwa kepada Allah Tuhannya. Dan janganlah kamu (wahai orang-orang yang menjadi saksi) menyembunyikan perkara yang dipersaksikan itu. dan sesiapa yang menyembunyikannya, maka sesungguhnya ia adalah orang yang berdosa hatinya. Dan (ingatlah), Allah sentiasa Mengetahui akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 49, 3, 20, 40, FALSE, 0, NULL),
(2, 284, 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'لِّلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللَّهُ فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'To Allāh belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allāh will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allāh is over all things competent.', 'Segala yang ada di langit dan yang ada di bumi adalah kepunyaan Allah. Dan jika kamu melahirkan apa yang ada di dalam hati kamu atau kamu memyembunyikannya, nescaya Allah akan menghitung dan menyatakannya kepada kamu. Kemudian Ia mengampunkan bagi sesiapa yang dikehendakiNya dan menyeksa sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya) Dan (ingatlah), Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 49, 3, 20, 41, FALSE, 0, NULL),
(2, 285, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ', NULL, 'The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allāh and His angels and His books and His messengers, [saying], "We make no distinction between any of His messengers." And they say, "We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination."', 'Rasulullah telah beriman kepada apa yang diturunkan kepadanya dari Tuhannya, dan juga orang-orang yang beriman; semuanya beriman kepada Allah, dan Malaikat-malaikatNya, dan Kitab-kitabNya, dan Rasul-rasulNya. (Mereka berkata): “Kami tidak membezakan antara seorang dengan yang lain Rasul-rasulnya”. Mereka berkata lagi: Kami dengar dan kami taat (kami pohonkan) keampunanMu wahai Tuhan kami, dan kepadaMu jualah tempat kembali”.', FALSE, NULL, NULL, 49, 3, 20, 41, FALSE, 0, NULL),
(2, 286, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', NULL, 'Allāh does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."', 'Allah tidak memberati seseorang melainkan apa yang terdaya olehnya. Ia mendapat pahala kebaikan yang diusahakannya, dan ia juga menanggung dosa kejahatan yang diusahakannya. (Mereka berdoa dengan berkata): “Wahai Tuhan kami! Janganlah Engkau mengirakan kami salah jika kami lupa atau kami tersalah. Wahai Tuhan kami! Janganlah Engkau bebankan kepada kami bebanan yang berat sebagaimana yang telah Engkau bebankan kepada orang-orang yang terdahulu daripada kami. Wahai Tuhan kami! Janganlah Engkau pikulkan kepada kami apa yang kami tidak terdaya memikulnya. Dan maafkanlah kesalahan kami, serta ampunkanlah dosa kami, dan berilah rahmat kepada kami. Engkaulah Penolong kami; oleh itu, tolonglah kami untuk mencapai kemenangan terhadap kaum-kaum yang kafir”.', FALSE, NULL, NULL, 49, 3, 20, 41, FALSE, 0, NULL),
(3, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam, Miim.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 1, NULL),
(3, 2, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 'الله لا اله الا هو الحي القيوم', NULL, 'Allāh - there is no deity except Him, the Ever-Living, the Self-Sustaining.', 'Allah tiada Tuhan (yang berhak disembah) melainkan Dia, Yang Tetap Hidup, Yang Kekal selama-lamanya mentadbirkan sekalian makhlukNya.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 7, NULL),
(3, 3, 'نَزَّلَ عَلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'نزل عليك الكتاب بالحق مصدقا لما بين يديه وانزل التوراة والانجيل', NULL, 'He has sent down upon you, [O Muḥammad], the Book in truth, confirming what was before it. And He revealed the Torah and the Gospel', 'Ia menurunkan kepadamu (wahai Muhammad) Kitab Suci (Al-Quran) dengan mengandungi kebenaran, yang mengesahkan isi Kitab-kitab Suci yang telah diturunkan dahulu daripadanya, dan Ia juga yang menurunkan Kitab-kitab Taurat dan Injil.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 11, NULL),
(3, 4, 'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'من قبل هدى للناس وانزل الفرقان ان الذين كفروا بايات الله لهم عذاب شديد والله عزيز ذو انتقام', NULL, 'Before, as guidance for the people. And He revealed the Criterion [i.e., the Qur’ān]. Indeed, those who disbelieve in the verses of Allāh will have a severe punishment, and Allāh is Exalted in Might, the Owner of Retribution.', 'Sebelum (Al-Quran diturunkan), menjadi petunjuk bagi umat manusia. Dan Ia juga yang menurunkan Al-Furqaan (yang membezakan antara yang benar dengan yang salah). Sesungguhnya orang-orang yang kufur ingkar akan ayat-ayat keterangan Allah itu, bagi mereka azab seksa yang amat berat. Dan (ingatlah), Allah Maha Kuasa, lagi berhak membalas dengan azab seksa (kepada golongan yang bersalah).', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 18, NULL),
(3, 5, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'ان الله لا يخفى عليه شيء في الارض ولا في السماء', NULL, 'Indeed, from Allāh nothing is hidden in the earth nor in the heaven.', 'Sesungguhnya Allah tidak tersembunyi kepadaNya sesuatu pun yang ada di bumi dan juga yang ada di langit.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 11, NULL),
(3, 6, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'هو الذي يصوركم في الارحام كيف يشاء لا اله الا هو العزيز الحكيم', NULL, 'It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise.', 'Dia lah yang membentuk rupa kamu dalam rahim (ibu kamu) sebagaimana yang dikehendakiNya. Tiada Tuhan (yang berhak disembah) melainkan Dia, Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 13, NULL),
(3, 7, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَـٰبَ مِنْهُ ءَايَـٰتٌ مُّحْكَمَـٰتٌ هُنَّ أُمُّ ٱلْكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتٌ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَـٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', 'هو الذي انزل عليك الكتاب منه ايات محكمات هن ام الكتاب واخر متشابهات فاما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تاويله وما يعلم تاويله الا الله والراسخون في العلم يقولون امنا به كل من عند ربنا وما يذكر الا اولو الالباب', NULL, 'It is He who has sent down to you, [O Muḥammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allāh. But those firm in knowledge say, "We believe in it. All [of it] is from our Lord." And no one will be reminded except those of understanding,', 'Dia lah yang menurunkan kepadamu (wahai Muhammad) Kitab Suci Al-Quran. Sebahagian besar dari Al-Quran itu ialah ayat-ayat “Muhkamaat” (yang tetap, tegas dan nyata maknanya serta jelas maksudnya); ayat-ayat Muhkamaat itu ialah ibu (atau pokok) isi Al-Quran. Dan yang lain lagi ialah ayat-ayat “Mutasyaabihaat” (yang samar-samar, tidak terang maksudnya). Oleh sebab itu (timbulah faham yang berlainan menurut kandungan hati masing-masing) - adapun orang-orang yang ada dalam hatinya kecenderungan ke arah kesesatan, maka mereka selalu menurut apa yang samar-samar dari Al-Quran untuk mencari fitnah dan mencari-cari Takwilnya (memutarkan maksudnya menurut yang disukainya). Padahal tidak ada yang mengetahui Takwilnya (tafsir maksudnya yang sebenar) melainkan Allah. Dan orang-orang yang tetap teguh serta mendalam pengetahuannya dalam ilmu-ilmu ugama, berkata: “Kami beriman kepadanya, semuanya itu datangnya dari sisi Tuhan kami” Dan tiadalah yang mengambil pelajaran dan peringatan melainkan orang-orang yang berfikiran.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 46, NULL),
(3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمة انك انت الوهاب', NULL, '[Who say], "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.', '(Mereka berdoa dengan berkata): “Wahai Tuhan kami! Janganlah Engkau memesongkan hati kami sesudah Engkau beri petunjuk kepada kami, dan kurniakanlah kepada kami limpah rahmat dari sisiMu; sesungguhnya Engkau jualah Tuhan Yang melimpah-limpah pemberianNya.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 15, NULL),
(3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد', NULL, 'Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allāh does not fail in His promise."', '“Wahai Tuhan kami! Sesungguhnya Engkaulah yang akan menghimpunkan sekalian manusia, untuk (menerima balasan pada) suatu hari (hari kiamat) yang tidak ada syak padanya”. Sesungguhnya Allah tidak memungkiri janjiNya.', FALSE, NULL, NULL, 50, 3, 20, 42, FALSE, 13, NULL),
(3, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 'ان الذين كفروا لن تغني عنهم اموالهم ولا اولادهم من الله شيئا واولئك هم وقود النار', NULL, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allāh at all. And it is they who are fuel for the Fire.', 'Sebenarnya harta benda orang-orang kafir, dan juga anak-pinak mereka tidak sekali-kali akan menyelamatkan mereka dari (azab seksa) Allah sedikit juapun; dan mereka itulah bahan bakaran api neraka.', FALSE, NULL, NULL, 51, 3, 20, 43, FALSE, 16, NULL),
(3, 11, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'كداب ال فرعون والذين من قبلهم كذبوا باياتنا فاخذهم الله بذنوبهم والله شديد العقاب', NULL, '[Theirs is] like the custom of the people of Pharaoh and those before them. They denied Our signs, so Allāh seized them for their sins. And Allāh is severe in penalty.', '(Keadaan orang-orang kafir itu) sama seperti keadaan kaum Firaun, dan orang-orang yang terdahulu dari mereka; mereka mendustakan ayat-ayat keterangan Kami, lalu Allah menyeksa mereka disebabkan dosa-dosa mereka. Dan (ingatlah), Allah Maha berat azab seksaNya.', FALSE, NULL, NULL, 51, 3, 20, 43, FALSE, 14, NULL),
(3, 12, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ', 'قل للذين كفروا ستغلبون وتحشرون الى جهنم وبئس المهاد', NULL, 'Say to those who disbelieve, "You will be overcome and gathered together to Hell, and wretched is the resting place."', 'Katakanlah (wahai Muhammad) kepada orang-orang kafir itu: “Kamu akan dikalahkan (di dunia ini) dan akan dihimpunkan (pada hari kiamat) ke dalam neraka Jahannam, dan itulah seburuk-buruk tempat yang disediakan”.', FALSE, NULL, NULL, 51, 3, 20, 43, FALSE, 9, NULL),
(3, 13, 'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌ تُقَـٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَـٰرِ', 'قد كان لكم اية في فئتين التقتا فئة تقاتل في سبيل الله واخرى كافرة يرونهم مثليهم راي العين والله يؤيد بنصره من يشاء ان في ذلك لعبرة لاولي الابصار', NULL, 'Already there has been for you a sign in the two armies which met [in combat at Badr] - one fighting in the cause of Allāh and another of disbelievers. They saw them [to be] twice their [own] number by [their] eyesight. But Allāh supports with His victory whom He wills. Indeed in that is a lesson for those of vision.', 'Sesungguhnya telah ada satu tanda (bukti) bagi kamu pada (peristiwa) dua pasukan yang telah bertemu (di medan perang); satu pasukan (orang-orang Islam) berperang pada jalan Allah (kerana mempertahankan ugama Allah), dan yang satu lagi dari golongan kafir musyrik. Mereka (yang kafir itu) melihat orang-orang Islam dengan pandangan mata biasa - dua kali ramainya berbanding dengan mereka sendiri. Dan Allah sentiasa menguatkan sesiapa yang dikehendakiNya, dengan memberikan pertolonganNya. Sesungguhnya pada peristiwa itu terdapat satu pengajaran yang memberi insaf bagi orang-orang yang berfikiran (yang celik mata hatinya).', FALSE, NULL, NULL, 51, 3, 20, 43, FALSE, 29, NULL),
(3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَـٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَـٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', 'زين للناس حب الشهوات من النساء والبنين والقناطير المقنطرة من الذهب والفضة والخيل المسومة والانعام والحرث ذلك متاع الحياة الدنيا والله عنده حسن الماب', NULL, 'Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allāh has with Him the best return [i.e., Paradise].', 'Dihiaskan (dan dijadikan indah) kepada manusia: kesukaan kepada benda-benda yang diingini nafsu, iaitu perempuan-perempuan dan anak-pinak; harta benda yang banyak bertimbun-timbun, dari emas dan perak; kuda peliharaan yang bertanda lagi terlatih; dan binatang-binatang ternak serta kebun-kebun tanaman. Semuanya itu ialah kesenangan hidup di dunia. Dan (ingatlah), pada sisi Allah ada tempat kembali yang sebaik-baiknya (iaitu Syurga).', FALSE, NULL, NULL, 51, 3, 20, 43, FALSE, 24, NULL),
(3, 15, '۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'قل اؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنات تجري من تحتها الانهار خالدين فيها وازواج مطهرة ورضوان من الله والله بصير بالعباد', NULL, 'Say, "Shall I inform you of [something] better than that? For those who fear Allāh will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allāh. And Allāh is Seeing [i.e., aware] of [His] servants -', 'Katakanlah (wahai Muhammad): “Mahukah supaya aku khabarkan kepada kamu akan yang lebih baik daripada semuanya itu? Iaitu bagi orang-orang yang bertaqwa disediakan di sisi Tuhan mereka beberapa Syurga, yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Disediakan juga pasangan-pasangan/ isteri-isteri yang suci bersih, serta (beroleh pula) keredaan dari Allah”. Dan (ingatlah), Allah sentiasa Melihat akan hamba-hambaNya;', FALSE, NULL, NULL, 51, 3, 21, 43, FALSE, 24, NULL),
(3, 16, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', 'الذين يقولون ربنا اننا امنا فاغفر لنا ذنوبنا وقنا عذاب النار', NULL, 'Those who say, ''Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,'' "', '(Iaitu) orang-orang yang berdoa dengan berkata: “Wahai Tuhan kami! Sesungguhnya kami telah beriman, oleh itu, ampunkanlah dosa-dosa kami dan peliharalah kami dari azab neraka”;', FALSE, NULL, NULL, 52, 3, 21, 43, FALSE, 11, NULL),
(3, 17, 'ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلْقَـٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 'الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالاسحار', NULL, 'The patient, the true, the obedient, those who spend [in the way of Allāh], and those who seek forgiveness before dawn.', '(Dan juga) orang-orang yang sabar (dalam menjunjung perintah Allah), dan orang-orang yang benar (perkataan dan hatinya), dan orang-orang yang sentiasa taat (akan perintah Allah), dan orang-orang yang membelanjakan hartanya (pada jalan Allah), dan orang-orang yang beristighfar (memohon ampun) pada waktu sahur.', FALSE, NULL, NULL, 52, 3, 21, 43, FALSE, 6, NULL),
(3, 18, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا هُوَ وَٱلْمَلَـٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'شهد الله انه لا اله الا هو والملائكة واولو العلم قائما بالقسط لا اله الا هو العزيز الحكيم', NULL, 'Allāh witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise.', 'Allah menerangkan (kepada sekalian makhlukNya dengan dalil-dalil dan bukti), bahawasanya tiada Tuhan (yang berhak disembah) melainkan Dia, Yang sentiasa mentadbirkan (seluruh alam) dengan keadilan, dan malaikat-malaikat serta orang-orang yang berilmu (mengakui dan menegaskan juga yang demikian); tiada Tuhan (yang berhak disembah) melainkan Dia; Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 52, 3, 21, 43, FALSE, 18, NULL),
(3, 19, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَـٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'ان الدين عند الله الاسلام وما اختلف الذين اوتوا الكتاب الا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بايات الله فان الله سريع الحساب', NULL, 'Indeed, the religion in the sight of Allāh is Islām. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allāh, then indeed, Allāh is swift in [taking] account.', 'Sesungguhnya ugama (yang benar dan diredai) di sisi Allah ialah Islam. Dan orang-orang (Yahudi dan Nasrani) yang diberikan Kitab itu tidak berselisih (mengenai ugama Islam dan enggan menerimanya) melainkan setelah sampai kepada mereka pengetahuan yang sah tentang kebenarannya; (perselisihan itu pula) semata-mata kerana hasad dengki yang ada dalam kalangan mereka. Dan (ingatlah), sesiapa yang kufur ingkar akan ayat-ayat keterangan Allah, maka sesungguhnya Allah Amat segera hitungan hisabNya.', FALSE, NULL, NULL, 52, 3, 21, 43, FALSE, 26, NULL),
(3, 20, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتاب والاميين ااسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلاغ والله بصير بالعباد', NULL, 'So if they argue with you, say, "I have submitted myself to Allāh [in Islām], and [so have] those who follow me." And say to those who were given the Scripture and [to] the unlearned, "Have you submitted yourselves?" And if they submit [in Islām], they are rightly guided; but if they turn away - then upon you is only the [duty of] notification. And Allāh is Seeing of [His] servants.', 'Oleh sebab itu jika mereka berhujah (menyangkal dan) membantahmu (Wahai Muhammad), maka katakanlah: “Aku telah berserah diriku kepada Allah dan demikian juga orang-orang yang mengikutku”. Dan bertanyalah (Wahai Muhammad) kepada orang-orang (Yahudi dan Nasrani) yang diberi Kitab, dan orang-orang yang “Ummi” (orang-orang musyrik Arab): “Sudahkah kamu mematuhi dan menurut (ugama Islam yang aku bawa itu)?” Kemudian jika mereka memeluk Islam, maka sebenarnya mereka telah memperoleh petunjuk; dan jika mereka berpaling (tidak mahu menerima Islam), maka sesungguhnya kewajipanmu hanyalah menyampaikan (dakwah Islam itu). Dan (ingatlah), Allah sentiasa Melihat (tingkah laku) sekalian hambaNya.', FALSE, NULL, NULL, 52, 3, 21, 43, FALSE, 26, NULL),
(3, 21, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'إِنَّ الَّذِينَ يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ الَّذِينَ يَأْمُرُونَ بِالْقِسْطِ مِنَ النَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', NULL, 'Those who disbelieve in the signs of Allāh and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment.', 'Sesungguhnya orang-orang yang kufur ingkar akan ayat-ayat keterangan Allah dan membunuh Nabi-nabi dengan jalan yang tidak benar, serta membunuh orang-orang yang menyeru manusia supaya berlaku adil maka sampaikanlah berita yang mengembirakan mereka, dengan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 52, 3, 21, 44, FALSE, 0, NULL),
(3, 22, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'أُولَٰئِكَ الَّذِينَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ وَمَا لَهُم مِّن نَّاصِرِينَ', NULL, 'They are the ones whose deeds have become worthless in this world and the Hereafter, and for them there will be no helpers.', 'Mereka itulah orang-orang yang telah rosak amal perbuatannya di dunia dan di akhirat, dan mereka tidak akan memperoleh sesiapa pun yang dapat memberi pertolongan.', FALSE, NULL, NULL, 52, 3, 21, 44, FALSE, 0, NULL),
(3, 23, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', 'أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُدْعَوْنَ إِلَىٰ كِتَابِ اللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', NULL, 'Do you not consider, [O Muḥammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allāh that it should arbitrate between them; then a party of them turns away, and they are refusing.', 'Tidakkah engkau pelik memikirkan (wahai Muhammad) terhadap sikap orang-orang (Yahudi) yang telah diberikan sebahagian dari Kitab Taurat, mereka diseru kepada Kitab Allah supaya Kitab itu dijadikan hakim (mengenai perkara-perkara yang timbul) di antara mereka. Ahli-ahli satu puak dari mereka berpaling ingkar sambil menolak (seruan dan hukum Kitab Allah itu).', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 24, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا لَن تَمَسَّنَا النَّارُ إِلَّا أَيَّامًا مَّعْدُودَاتٍ وَغَرَّهُمْ فِي دِينِهِم مَّا كَانُوا يَفْتَرُونَ', NULL, 'That is because they say, "Never will the Fire touch us except for [a few] numbered days," and [because] they were deluded in their religion by what they were inventing.', 'Yang demikian ialah disebabkan mereka (mendakwa dengan) berkata: “Kami tidak sekali-kali akan disentuh oleh api neraka melainkan beberapa hari sahaja yang boleh dihitung”. Mereka (sebenarnya) telah diperdayakan dalam ugama mereka, oleh dakwaan-dakwaan dusta yang mereka telah ada-adakan.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 25, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'فَكَيْفَ إِذَا جَمَعْنَاهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', NULL, 'So how will it be when We assemble them for a Day about which there is no doubt? And each soul will be compensated [in full for] what it earned, and they will not be wronged.', 'Oleh itu, bagaimana pula (hal keadaan mereka) ketika Kami himpunkan mereka pada hari (kiamat), yang tidak ada syak padanya; dan (pada hari itu juga) disempurnakan kepada tiap-tiap seorang, balasan apa yang ia telah usahakan, sedang mereka masing-masing tidak akan dianiaya.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 26, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Say, "O Allāh, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent.', 'Katakanlah (wahai Muhammad): “Wahai Tuhan yang mempunyai kuasa pemerintahan! Engkaulah yang memberi kuasa pemerintahan kepada sesiapa yang Engkau kehendaki, dan Engkaulah yang mencabut kuasa pemerintahan dari sesiapa yang Engkau kehendaki. Engkaulah juga yang memuliakan sesiapa yang Engkau kehendaki, dan Engkaulah yang menghina sesiapa yang Engkau kehendaki. Dalam kekuasaan Engkaulah sahaja adanya segala kebaikan. Sesungguhnya Engkau Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 27, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ', 'تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَتَرْزُقُ مَن تَشَاءُ بِغَيْرِ حِسَابٍ', NULL, 'You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account [i.e., limit or measure]."', '“Engkaulah (wahai Tuhan) yang memasukkan waktu malam ke dalam waktu siang, dan Engkaulah yang memasukkan waktu siang ke dalam waktu malam. Engkaulah juga yang mengeluarkan sesuatu yang hidup dari benda yang mati, dan Engkaulah yang mengeluarkan benda yang mati dari sesuatu yang hidup. Engkau jualah yang memberi rezeki kepada sesiapa yang Engkau kehendaki, dengan tiada hitungan hisabnya”.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 28, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'لَّا يَتَّخِذِ الْمُؤْمِنُونَ الْكَافِرِينَ أَوْلِيَاءَ مِن دُونِ الْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ اللَّهِ فِي شَيْءٍ إِلَّا أَن تَتَّقُوا مِنْهُمْ تُقَاةً وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ وَإِلَى اللَّهِ الْمَصِيرُ', NULL, 'Let not believers take disbelievers as allies [i.e., supporters or protectors] rather than believers. And whoever [of you] does that has nothing [i.e., no association] with Allāh, except when taking precaution against them in prudence. And Allāh warns you of Himself, and to Allāh is the [final] destination.', 'Janganlah orang-orang yang beriman mengambil orang-orang kafir menjadi teman rapat dengan meninggalkan orang-orang yang beriman. Dan sesiapa yang melakukan (larangan) yang demikian maka tiadalah ia (mendapat perlindungan) dari Allah dalam sesuatu apapun, kecuali kamu hendak menjaga diri daripada sesuatu bahaya yang ditakuti dari pihak mereka (yang kafir itu). Dan Allah perintahkan supaya kamu beringat-ingat terhadap kekuasaan diriNya (menyeksa kamu). Dan kepada Allah jualah tempat kembali.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 29, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'قُلْ إِن تُخْفُوا مَا فِي صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Say, "Whether you conceal what is in your breasts or reveal it, Allāh knows it. And He knows that which is in the heavens and that which is on the earth. And Allāh is over all things competent.', 'Katakanlah (wahai Muhammad): “Jika kamu sembunyikan apa yang ada dalam dada kamu atau kamu melahirkannya, nescaya Allah mengetahuinya; dan Ia mengetahui segala yang ada di langit dan yang ada di bumi. Dan Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 53, 3, 21, 44, FALSE, 0, NULL),
(3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُ أَمَدًا بَعِيدًا وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ وَاللَّهُ رَءُوفٌ بِالْعِبَادِ', NULL, 'The Day every soul will find what it has done of good present [before it] and what it has done of evil, it will wish that between itself and that [evil] was a great distance. And Allāh warns you of Himself, and Allāh is Kind to [His] servants."', '(Ingatlah) hari (kiamat yang padanya) tiap-tiap seorang akan mendapati apa sahaja kebaikan yang telah dikerjakannya, sedia (dibentangkan kepadanya dalam surat-surat amalnya); dan demikian juga apa sahaja kejahatan yang telah dikerjakannya. (ketika itu tiap-tiap orang yang bersalah) ingin kalau ada jarak yang jauh di antaranya dengan amalnya yang jahat itu. Dan Allah perintahkan supaya kamu beringat-ingat terhadap kekuasaan diriNya (menyeksa kamu). Dan (ingatlah juga), Allah Amat belas kasihan kepada hamba-hambaNya.', FALSE, NULL, NULL, 54, 3, 21, 44, FALSE, 0, NULL),
(3, 31, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'قُلْ إِن كُنتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'Say, [O Muḥammad], "If you should love Allāh, then follow me, [so] Allāh will love you and forgive you your sins. And Allāh is Forgiving and Merciful."', 'Katakanlah (wahai Muhammad): “Jika benar kamu mengasihi Allah maka ikutilah daku, nescaya Allah mengasihi kamu serta mengampunkan dosa-dosa kamu. Dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 54, 3, 21, 45, FALSE, 0, NULL),
(3, 32, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'قُلْ أَطِيعُوا اللَّهَ وَالرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّ اللَّهَ لَا يُحِبُّ الْكَافِرِينَ', NULL, 'Say, "Obey Allāh and the Messenger. But if you turn away - then indeed, Allāh does not like the disbelievers."', 'Katakanlah (wahai Muhammad): “Taatlah kamu kepada Allah dan RasulNya. Oleh itu, jika kamu berpaling (menderhaka), maka sesungguhnya Allah tidak suka kepada orang-orang yang kafir.', FALSE, NULL, NULL, 54, 3, 21, 45, FALSE, 0, NULL),
(3, 33, 'إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 'إِنَّ اللَّهَ اصْطَفَىٰ آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ', NULL, 'Indeed, Allāh chose Adam and Noah and the family of Abraham and the family of ʿImrān over the worlds -', 'Sesungguhnya Allah telah memilih Nabi Adam, dan Nabi Nuh, dan juga keluarga Nabi Ibrahim dan keluarga Imran, melebihi segala umat (yang ada pada zaman mereka masing-masing).', FALSE, NULL, NULL, 54, 3, 22, 45, FALSE, 0, NULL),
(3, 34, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'ذُرِّيَّةً بَعْضُهَا مِن بَعْضٍ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'Descendants, some of them from others. And Allāh is Hearing and Knowing.', '(Mereka kembang biak sebagai) satu keturunan (zuriat) yang setengahnya berasal dari setengahnya yang lain. Dan (ingatlah), Allah sentiasa Mendengar, lagi sentiasa Mengetahui.', FALSE, NULL, NULL, 54, 3, 22, 45, FALSE, 0, NULL),
(3, 35, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'إِذْ قَالَتِ امْرَأَتُ عِمْرَانَ رَبِّ إِنِّي نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا فَتَقَبَّلْ مِنِّي إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ', NULL, '[Mention, O Muḥammad], when the wife of ʿImrān said, "My Lord, indeed I have pledged to You what is in my womb, consecrated [for Your service], so accept this from me. Indeed, You are the Hearing, the Knowing."', '(Ingatlah) ketika isteri Imran berkata: “Tuhanku! Sesungguhnya aku nazarkan kepadaMu anak yang ada dalam kandunganku sebagai seorang yang bebas (dari segala urusan dunia untuk berkhidmat kepadaMu semata-mata), maka terimalah nazarku; sesungguhnya Engkaulah Yang Maha Mendengar, lagi Maha Mengetahui.”', FALSE, NULL, NULL, 54, 3, 22, 45, FALSE, 0, NULL),
(3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّي وَضَعْتُهَا أُنثَىٰ وَاللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ الذَّكَرُ كَالْأُنثَىٰ وَإِنِّي سَمَّيْتُهَا مَرْيَمَ وَإِنِّي أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ الشَّيْطَانِ الرَّجِيمِ', NULL, 'But when she delivered her, she said, "My Lord, I have delivered a female." And Allāh was most knowing of what she delivered, and the male is not like the female. "And I have named her Mary, and I seek refuge for her in You and [for] her descendants from Satan, the expelled [from the mercy of Allāh]."', 'Maka apabila ia melahirkannya, berkatalah ia: “Wahai Tuhanku! Sesungguhnya aku telah melahirkan seorang anak perempuan (sedang yang aku harap-harapkan ialah anak lelaki), - dan Allah memang mengetahui akan apa yang dilahirkannya itu - dan memanglah tidak sama anak lelaki dengan anak perempuan; dan bahawasanya aku telah menamakannya Maryam, dan aku melindungi dia dengan peliharaanMu, demikian juga zuriat keturunannya, dari godaan syaitan yang kena rejam (yang dikutuk dan disingkirkan)”.', FALSE, NULL, NULL, 54, 3, 22, 45, FALSE, 0, NULL),
(3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا الْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَا مَرْيَمُ أَنَّىٰ لَكِ هَٰذَا قَالَتْ هُوَ مِنْ عِندِ اللَّهِ إِنَّ اللَّهَ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ', NULL, 'So her Lord accepted her with good acceptance and caused her to grow in a good manner and put her in the care of Zechariah. Every time Zechariah entered upon her in the prayer chamber, he found with her provision. He said, "O Mary, from where is this [coming] to you?" She said, "It is from Allāh. Indeed, Allāh provides for whom He wills without account."', 'Maka ia (Maryam yang dinazarkan oleh ibunya) diterima oleh Tuhannya dengan penerimaan yang baik, dan dibesarkannya dengan didikan yang baik, serta diserahkannya untuk dipelihara oleh Nabi Zakaria. Tiap-tiap kali Nabi Zakaria masuk untuk menemui Maryam di Mihrab, ia dapati rezeki (buah-buahanan yang luar biasa) di sisinya. Nabi Zakaria bertanya: “Wahai Maryam dari mana engkau dapati (buah-buahan) ini?” Maryam menjawab; “Ialah dari Allah, sesungguhnya Allah memberikan rezeki kepada sesiapa yang dikehendakiNya dengan tidak dikira”.', FALSE, NULL, NULL, 54, 3, 22, 45, FALSE, 0, NULL),
(3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ قَالَ رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ', NULL, 'At that, Zechariah called upon his Lord, saying, "My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication."', 'Ketika itu Nabi Zakaria berdoa kepada Tuhannya, katanya: “Wahai Tuhanku! Kurniakanlah kepadaku dari sisiMu zuriat keturunan yang baik; sesungguhnya Engkau sentiasa Mendengar (menerima) doa permohonan”.', FALSE, NULL, NULL, 55, 3, 22, 45, FALSE, 0, NULL),
(3, 39, 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', 'فَنَادَتْهُ الْمَلَائِكَةُ وَهُوَ قَائِمٌ يُصَلِّي فِي الْمِحْرَابِ أَنَّ اللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًا بِكَلِمَةٍ مِّنَ اللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ الصَّالِحِينَ', NULL, 'So the angels called him while he was standing in prayer in the chamber, "Indeed, Allāh gives you good tidings of John, confirming a word from Allāh and [who will be] honorable, abstaining [from women], and a prophet from among the righteous."', 'Lalu ia diseru oleh malaikat sedang ia berdiri sembahyang di Mihrab, (katanya): “Bahawasanya Allah memberi khabar yang mengembirakanmu, dengan (mengurniakanmu seorang anak lelaki bernama) Yahya, yang akan beriman kepada Kalimah dari Allah, dan akan menjadi ketua, dan juga akan menahan diri dari berkahwin, dan akan menjadi seorang Nabi dari orang-orang yang soleh”.', FALSE, NULL, NULL, 55, 3, 22, 45, FALSE, 0, NULL),
(3, 40, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَامٌ وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَأَتِي عَاقِرٌ قَالَ كَذَٰلِكَ اللَّهُ يَفْعَلُ مَا يَشَاءُ', NULL, 'He said, "My Lord, how will I have a boy when I have reached old age and my wife is barren?" He [the angel] said, "Such is Allāh; He does what He wills."', 'Nabi Zakaria berkata: “Wahai Tuhanku! Bagaimanakah aku akan beroleh seorang anak, padahal sebenarnya aku telah tua dan isteriku pula mandul?”, Allah berfirman: “Demikianlah keadaannya, Allah melakukan apa yang dikehendakiNya”.', FALSE, NULL, NULL, 55, 3, 22, 45, FALSE, 0, NULL),
(3, 41, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًا وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ ثَلَاثَةَ أَيَّامٍ إِلَّا رَمْزًا وَاذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِالْعَشِيِّ وَالْإِبْكَارِ', NULL, 'He said, "My Lord, make for me a sign." He said, "Your sign is that you will not [be able to] speak to the people for three days except by gesture. And remember your Lord much and exalt [Him with praise] in the evening and the morning."', 'Nabi Zakaria berkata lagi: “Wahai Tuhanku! Jadikanlah bagiku satu tanda (yang menunjukkan isteriku mengandung)”. Allah berfirman: “Tandamu itu ialah engkau tidak akan dapat berkata-kata dengan orang ramai selama tiga hari (tiga malam) melainkan dengan isyarat sahaja; dan ingatlah kepada Tuhanmu (dengan berzikir) banyak-banyak, dan bertasbihlah memuji Allah (dengan mengerjakan sembahyang), pada waktu malam dan pada waktu pagi”.', FALSE, NULL, NULL, 55, 3, 22, 45, FALSE, 0, NULL),
(3, 42, 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', 'وَإِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَىٰ نِسَاءِ الْعَالَمِينَ', NULL, 'And [mention] when the angels said, "O Mary, indeed Allāh has chosen you and purified you and chosen you above the women of the worlds.', 'Dan (ingatlah wahai Muhammad) ketika malaikat berkata: “Wahai Maryam! Sesungguhnya Allah telah memilihmu, dan mensucikanmu, dan telah memilihmu (beroleh kemuliaan) melebihi perempuan-perempuan seluruh alam (yang sezaman denganmu).', FALSE, NULL, NULL, 55, 3, 22, 46, FALSE, 0, NULL),
(3, 43, 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 'يَا مَرْيَمُ اقْنُتِي لِرَبِّكِ وَاسْجُدِي وَارْكَعِي مَعَ الرَّاكِعِينَ', NULL, 'O Mary, be devoutly obedient to your Lord and prostrate and bow with those who bow [in prayer]."', '“Wahai Maryam! Taatlah kepada Tuhanmu, dan sujudlah serta rukuklah (mengerjakan sembahyang) bersama-sama orang-orang yang rukuk”.', FALSE, NULL, NULL, 55, 3, 22, 46, FALSE, 0, NULL),
(3, 44, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', 'ذَٰلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَامَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', NULL, 'That is from the news of the unseen which We reveal to you, [O Muḥammad]. And you were not with them when they cast their pens as to which of them should be responsible for Mary. Nor were you with them when they disputed.', 'Peristiwa yang demikian ialah sebahagian dari berita-berita ghaib yang Kami wahyukan kepadamu (wahai Muhammad), sedang engkau tidak ada bersama-sama mereka ketika mereka mencampakkan qalam masing-masing (untuk mengundi) siapakah di antara mereka yang akan memelihara Maryam. Dan engkau juga (wahai Muhammad) tidak ada bersama-sama mereka ketika mereka berkelahi (tentang perkara menjaga dan memelihara Maryam).', FALSE, NULL, NULL, 55, 3, 22, 46, FALSE, 0, NULL),
(3, 45, 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 'إِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ اسْمُهُ الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ وَمِنَ الْمُقَرَّبِينَ', NULL, '[And mention] when the angels said, "O Mary, indeed Allāh gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allāh].', '(Ingatlah) ketika malaikat berkata: “Wahai Maryam! Bahawasanya Allah memberikan khabar yang mengembirakanmu, dengan (mengurniakan seorang anak yang engkau akan kandungkan semata-mata dengan) Kalimah daripada Allah, nama anak itu: Al-Masih, Isa Ibni Maryam, seorang yang terkemuka di dunia dan di akhirat, dan ia juga dari orang-orang yang didampingkan (diberi kemuliaan di sisi Allah).', FALSE, NULL, NULL, 55, 3, 22, 46, FALSE, 0, NULL),
(3, 46, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّٰلِحِينَ', 'وَيُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلًا وَمِنَ الصَّالِحِينَ', NULL, 'He will speak to the people in the cradle and in maturity and will be of the righteous."', '“Dan ia akan berkata-kata kepada orang ramai semasa ia masih kecil dalam buaian, dan semasa ia dewasa, dan ia adalah dari orang-orang yang soleh.”', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 47, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٌ وَلَمْ يَمْسَسْنِي بَشَرٌ قَالَ كَذَٰلِكِ اللَّهُ يَخْلُقُ مَا يَشَاءُ إِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ', NULL, 'She said, "My Lord, how will I have a child when no man has touched me?" [The angel] said, "Such is Allāh; He creates what He wills. When He decrees a matter, He only says to it, ''Be,'' and it is.', 'Maryam berkata: “Wahai Tuhanku! Bagaimanakah aku akan beroleh seorang anak, padahal aku tidak pernah disentuh oleh seorang lelaki pun?” Allah berfirman; “Demikianlah keadaannya, Allah menjadikan apa yang dikehendakiNya; apabila Ia berkehendak melaksanakan sesuatu perkara, maka Ia hanyalah berfirman kepadanya: ‘Jadilah engkau’, lalu menjadilah ia.”', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 48, 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'وَيُعَلِّمُهُ الْكِتَابَ وَالْحِكْمَةَ وَالتَّوْرَاةَ وَالْإِنجِيلَ', NULL, 'And He will teach him writing and wisdom and the Torah and the Gospel', 'Dan Allah akan mengajarnya ilmu menulis, dan hukum-hukum aturan ugama, dan juga kandungan kitab-kitab Taurat dan Injil.', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 49, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وَرَسُولًا إِلَىٰ بَنِي إِسْرَائِيلَ أَنِّي قَدْ جِئْتُكُم بِآيَةٍ مِّن رَّبِّكُمْ أَنِّي أَخْلُقُ لَكُم مِّنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًا بِإِذْنِ اللَّهِ وَأُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ وَأُحْيِي الْمَوْتَىٰ بِإِذْنِ اللَّهِ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمْ إِنَّ فِي ذَٰلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'And [make him] a messenger to the Children of Israel, [who will say], ''Indeed I have come to you with a sign from your Lord in that I design for you from clay [that which is] like the form of a bird, then I breathe into it and it becomes a bird by permission of Allāh. And I cure the blind [from birth] and the leper, and I give life to the dead - by permission of Allāh. And I inform you of what you eat and what you store in your houses. Indeed in that is a sign for you, if you are believers.', 'Dan (akan melantiknya) menjadi seorang Rasul kepada Bani Israil, (dengan menegaskan kepada mereka): “Sesungguhnya aku telah datang kepada kamu, dengan membawa satu tanda (mukjizat) dari tuhan kamu, iaitu aku boleh membuat untuk kamu dari tanah liat seperti bentuk burung, kemudian aku tiup padanya lalu menjadilah ia seekor burung (yang hidup) dengan izin Allah; dan juga aku boleh menyembuhkan orang yang buta dan orang yang sopak, dan aku boleh menghidupkan kembali orang-orang yang mati dengan izin Allah; dan juga aku boleh memberitahu kepada kamu tentang apa yang kamu makan dan apa yang kamu simpan di rumah kamu. Sesungguhnya perkara-perkara yang demikian itu, mengandungi satu tanda (mukjizat) bagi kamu (yang membuktikan kebenaran bahawa aku seorang Rasul yang diutus oleh Allah kepada kamu), jika kamu orang-orang yang (mahu) beriman.', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 50, 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيَّ مِنَ التَّوْرَاةِ وَلِأُحِلَّ لَكُم بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِآيَةٍ مِّن رَّبِّكُمْ فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'And [I have come] confirming what was before me of the Torah and to make lawful for you some of what was forbidden to you. And I have come to you with a sign from your Lord, so fear Allāh and obey me.', '“Dan juga (aku datang kepada kamu ialah untuk) mengesahkan kebenaran Kitab Taurat yang diturunkan dahulu daripadaku, dan untuk menghalalkan bagi kamu sebahagian (dari perkara-perkara) yang telah diharamkan kepada kamu; dan juga aku datang kepada kamu dengan membawa satu mukjizat dari Tuhan kamu. Oleh itu bertaqwalah kamu kepada Allah dan taatlah kepadaku.', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 51, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ', NULL, 'Indeed, Allāh is my Lord and your Lord, so worship Him. That is the straight path.''"', '“Sesungguhnya Allah ialah Tuhanku dan Tuhan kamu, oleh itu, beribadatlah kamu kepadaNya. Inilah jalan yang lurus”.', FALSE, NULL, NULL, 56, 3, 22, 46, FALSE, 0, NULL),
(3, 52, 'فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 'فَلَمَّا أَحَسَّ عِيسَىٰ مِنْهُمُ الْكُفْرَ قَالَ مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ', NULL, 'But when Jesus felt [persistence in] disbelief from them, he said, "Who are my supporters for [the cause of] Allāh?" The disciples said, "We are supporters for Allāh. We have believed in Allāh and testify that we are Muslims [submitting to Him].', 'Maka ketika Nabi Isa merasa (serta mengetahui dengan yakin) akan kekufuran dari mereka (kaum Yahudi), berkatalah ia: “Siapakah penolong-penolongku (dalam perjalananku) kepada Allah (dengan menegakkan ugamaNya)?”. Orang-orang “Hawariyyuun” (Penyokong-penyokong Nabi Isa) berkata: “Kamilah penolong-penolong (utusan) Allah. Kami telah beriman kepada Allah, dan saksikanlah (wahai Nabi Allah) sesungguhnya kami ialah orang-orang Islam (yang berserah bulat-bulat kepada Allah).', FALSE, NULL, NULL, 56, 3, 23, 46, FALSE, 0, NULL),
(3, 53, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ', NULL, 'Our Lord, we have believed in what You revealed and have followed the messenger [i.e., Jesus], so register us among the witnesses [to truth]."', '“Wahai Tuhan kami! Kami telah beriman kepada apa yang telah Engkau turunkan, dan kami mengikut RasulMu; oleh itu suratkanlah kami beserta orang-orang yang menjadi saksi (yang mengakui keesaanMu dan kebenaran RasulMu)”.', FALSE, NULL, NULL, 57, 3, 23, 46, FALSE, 0, NULL),
(3, 54, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'وَمَكَرُوا وَمَكَرَ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ', NULL, 'And they [i.e., the disbelievers] planned, but Allāh planned. And Allāh is the best of planners.', 'Dan orang-orang (Yahudi yang kafir) itupun merancangkan tipu daya (hendak membunuh Nabi Isa), dan Allah pula membalas tipu daya (mereka); dan (ingatlah), Allah sebijak-bijak yang membalas (dan menggagalkan segala jenis) tipu daya.', FALSE, NULL, NULL, 57, 3, 23, 46, FALSE, 0, NULL),
(3, 55, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'إِذْ قَالَ اللَّهُ يَا عِيسَىٰ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ الَّذِينَ كَفَرُوا وَجَاعِلُ الَّذِينَ اتَّبَعُوكَ فَوْقَ الَّذِينَ كَفَرُوا إِلَىٰ يَوْمِ الْقِيَامَةِ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', NULL, '[Mention] when Allāh said, "O Jesus, indeed I will take you and raise you to Myself and purify [i.e., free] you from those who disbelieve and make those who follow you [in submission to Allāh alone] superior to those who disbelieve until the Day of Resurrection. Then to Me is your return, and I will judge between you concerning that in which you used to differ.', '(Ingatlah) ketika Allah berfirman: “Wahai Isa! Sesungguhnya Aku akan mengambilmu dengan sempurna, dan akan mengangkatmu ke sisiKu, dan akan membersihkanmu dari orang-orang kafir, dan juga akan menjadikan orang-orang yang mengikutmu mengatasi orang-orang kafir (yang tidak beriman kepadamu), hingga ke hari kiamat. Kemudian kepada Akulah tempat kembalinya kamu, lalu Aku menghukum (memberi keputusan) tentang apa yang kamu perselisihkan”.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 56, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'فَأَمَّا الَّذِينَ كَفَرُوا فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِي الدُّنْيَا وَالْآخِرَةِ وَمَا لَهُم مِّن نَّاصِرِينَ', NULL, 'And as for those who disbelieved, I will punish them with a severe punishment in this world and the Hereafter, and they will have no helpers."', 'Adapun orang-orang kafir, maka Aku (Allah) akan menyeksa mereka dengan azab yang amat berat di dunia dan di akhirat, dan mereka pula tidak akan beroleh sesiapa pun yang dapat menolong.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'وَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَاللَّهُ لَا يُحِبُّ الظَّالِمِينَ', NULL, 'But as for those who believed and did righteous deeds, He will give them in full their rewards, and Allāh does not like the wrongdoers.', 'Adapun orang-orang yang beriman dan mengerjakan amal-amal soleh, maka Allah akan menyempurnakan pahala mereka; dan (ingatlah), Allah tidak suka kepada orang-orang yang zalim.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 58, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ الْآيَاتِ وَالذِّكْرِ الْحَكِيمِ', NULL, 'This is what We recite to you, [O Muḥammad], of [Our] verses and the precise [and wise] message [i.e., the Qur’ān].', 'Demikianlah (perihal Nabi Isa), yang Kami membacakannya kepadamu (wahai Muhammad, adalah ia) sebahagian dari hujah-hujah keterangan (yang membuktikan kebenarannya), dan dari Al-Quran yang penuh dengan hikmat-hikmat - (pengetahuan yang tepat, lagi sentiasa terpelihara).', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 59, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', 'إِنَّ مَثَلَ عِيسَىٰ عِندَ اللَّهِ كَمَثَلِ آدَمَ خَلَقَهُ مِن تُرَابٍ ثُمَّ قَالَ لَهُ كُن فَيَكُونُ', NULL, 'Indeed, the example of Jesus to Allāh is like that of Adam. He created him from dust; then He said to him, "Be," and he was.', 'Sesungguhnya perbandingan (kejadian) Nabi Isa di sisi Allah adalah sama seperti (kejadian) Nabi Adam. Allah telah menciptakan Adam dari tanah lalu berfirman kepadanya: “Jadilah engkau!” maka menjadilah ia.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 60, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 'الْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ الْمُمْتَرِينَ', NULL, 'The truth is from your Lord, so do not be among the doubters.', 'Perkara yang benar ialah yang datang dari Tuhanmu. Maka jangan sekali-kali engkau menjadi dari orang-orang yang ragu-ragu.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 61, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', 'فَمَنْ حَاجَّكَ فِيهِ مِن بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ فَقُلْ تَعَالَوْا نَدْعُ أَبْنَاءَنَا وَأَبْنَاءَكُمْ وَنِسَاءَنَا وَنِسَاءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ اللَّهِ عَلَى الْكَاذِبِينَ', NULL, 'Then whoever argues with you about it after [this] knowledge has come to you - say, "Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then supplicate earnestly [together] and invoke the curse of Allāh upon the liars [among us]."', 'Kemudian sesiapa yang membantahmu (wahai Muhammad) mengenainya, sesudah engkau beroleh pengetahuan yang benar, maka katakanlah kepada mereka: “Marilah kita menyeru anak-anak kami serta anak-anak kamu, dan perempuan-perempuan kami serta perempuan-perempuan kamu, dan diri kami serta diri kamu, kemudian kita memohon kepada Allah dengan bersungguh-sungguh, serta kita meminta supaya laknat Allah ditimpakan kepada orang-orang yang berdusta”.', FALSE, NULL, NULL, 57, 3, 23, 47, FALSE, 0, NULL),
(3, 62, 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إِنَّ هَٰذَا لَهُوَ الْقَصَصُ الْحَقُّ وَمَا مِنْ إِلَٰهٍ إِلَّا اللَّهُ وَإِنَّ اللَّهَ لَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'Indeed, this is the true narration. And there is no deity except Allāh. And indeed, Allāh is the Exalted in Might, the Wise.', 'Sesungguhnya ini ialah kisah-kisah yang benar; dan tiadalah Tuhan (yang berhak disembah) melainkan Allah; dan (ingatlah), sesungguhnya Allah, Dia lah jua Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 58, 3, 23, 47, FALSE, 0, NULL),
(3, 63, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', 'فَإِن تَوَلَّوْا فَإِنَّ اللَّهَ عَلِيمٌ بِالْمُفْسِدِينَ', NULL, 'But if they turn away, then indeed - Allāh is Knowing of the corrupters.', 'Kemudian kalau mereka berpaling (enggan menurut), maka sesungguhnya Allah sentiasa Mengetahui akan orang-orang yang berbuat kerosakan.', FALSE, NULL, NULL, 58, 3, 23, 47, FALSE, 0, NULL),
(3, 64, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 'قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ اللَّهِ فَإِن تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ', NULL, 'Say, "O People of the Scripture, come to a word that is equitable between us and you - that we will not worship except Allāh and not associate anything with Him and not take one another as lords instead of Allāh." But if they turn away, then say, "Bear witness that we are Muslims [submitting to Him]."', 'Katakanlah (wahai Muhammad): “Wahai Ahli Kitab, marilah kepada satu Kalimah yang bersamaan antara kami dengan kamu, iaitu kita semua tidak menyembah melainkan Allah, dan kita tidak sekutukan denganNya sesuatu jua pun; dan jangan pula sebahagian dari kita mengambil akan sebahagian yang lain untuk dijadikan orang-orang yang dipuja dan didewa-dewakan selain dari Allah”. Kemudian jika mereka (Ahli Kitab itu) barpaling (enggan menerimanya) maka katakanlah kepada mereka: “Saksikanlah kamu bahawa sesungguhnya kami adalah orang-orang Islam”.', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 65, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ أَفَلَا تَعْقِلُونَ', 'يَا أَهْلَ الْكِتَابِ لِمَ تُحَاجُّونَ فِي إِبْرَاهِيمَ وَمَا أُنزِلَتِ التَّوْرَاةُ وَالْإِنجِيلُ إِلَّا مِن بَعْدِهِ أَفَلَا تَعْقِلُونَ', NULL, 'O People of the Scripture, why do you argue about Abraham while the Torah and the Gospel were not revealed until after him? Then will you not reason?', 'Wahai Ahli Kitab! Mengapa kamu berani memperdebatkan tentang (ugama) Nabi Ibrahim, padahal Taurat dan Injil tidak diturunkan melainkan kemudian daripada (zaman) Ibrahim; patutkah (kamu berdegil sehingga) kamu tidak mahu menggunakan akal?', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 66, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'هَا أَنتُمْ هَٰؤُلَاءِ حَاجَجْتُمْ فِيمَا لَكُم بِهِ عِلْمٌ فَلِمَ تُحَاجُّونَ فِيمَا لَيْسَ لَكُم بِهِ عِلْمٌ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', NULL, 'Here you are - those who have argued about that of which you have [some] knowledge, but why do you argue about that of which you have no knowledge? And Allāh knows, while you know not.', 'Ingatlah! Kamu ini orang-orang (bodoh), kamu telah memajukan bantahan tentang perkara yang kamu ada pengetahuan mengenainya (yang diterangkan perihalnya dalam Kitab Taurat), maka mengapa kamu membuat bantahan tentang perkara yang tidak ada pada kamu sedikit pengetahuan pun bersabit dengannya? Dan (ingatlah), Allah mengetahui (hakikat yang sebenarnya) sedang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 67, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'مَا كَانَ إِبْرَاهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', NULL, 'Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allāh]. And he was not of the polytheists.', 'Bukanlah Nabi Ibrahim itu seorang pemeluk ugama Yahudi, dan bukanlah ia seorang pemeluk ugama Kristian, tetapi ia seorang yang tetap di atas dasar Tauhid sebagai seorang Muslim (yang taat dan berserah bulat-bulat kepada Allah), dan ia pula bukanlah dari orang-orang musyrik.', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 68, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', 'إِنَّ أَوْلَى النَّاسِ بِإِبْرَاهِيمَ لَلَّذِينَ اتَّبَعُوهُ وَهَٰذَا النَّبِيُّ وَالَّذِينَ آمَنُوا وَاللَّهُ وَلِيُّ الْمُؤْمِنِينَ', NULL, 'Indeed, the most worthy of Abraham among the people are those who followed him [in submission to Allāh] and this prophet [i.e., Muḥammad (ﷺ)] and those who believe [in his message]. And Allāh is the Ally of the believers.', 'Sesungguhnya orang-orang yang hampir sekali kepada Nabi Ibrahim (dan berhak mewarisi ugamanya) ialah orang-orang yang mengikutinya dan juga Nabi (Muhammad) ini serta orang-orang yang beriman (umatnya - umat Islam). Dan (ingatlah), Allah ialah Pelindung dan Penolong sekalian orang-orang yang beriman.', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 69, 'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'وَدَّت طَّائِفَةٌ مِّنْ أَهْلِ الْكِتَابِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ', NULL, 'A faction of the People of the Scripture wish they could mislead you. But they do not mislead except themselves, and they perceive [it] not.', 'Segolongan dari Ahli Kitab suka dan berangan-angan kiranya mereka dapat menyesatkan kamu; padahal mereka tidak akan menyesatkan melainkan dirinya sendiri, dan mereka pula tidak menyedari (akibat yang buruk itu).', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 70, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 'يَا أَهْلَ الْكِتَابِ لِمَ تَكْفُرُونَ بِآيَاتِ اللَّهِ وَأَنتُمْ تَشْهَدُونَ', NULL, 'O People of the Scripture, why do you disbelieve in the verses of Allāh while you witness [to their truth]?', 'Wahai Ahli Kitab! Mengapa kamu kufurkan (ingkarkan) ayat-ayat keterangan Allah padahal kamu menyaksikan kebenaranNya?', FALSE, NULL, NULL, 58, 3, 23, 48, FALSE, 0, NULL),
(3, 71, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'يَا أَهْلَ الْكِتَابِ لِمَ تَلْبِسُونَ الْحَقَّ بِالْبَاطِلِ وَتَكْتُمُونَ الْحَقَّ وَأَنتُمْ تَعْلَمُونَ', NULL, 'O People of the Scripture, why do you mix [i.e., confuse] the truth with falsehood and conceal the truth while you know [it]?', 'Wahai Ahli Kitab! Mengapa kamu campur adukkan yang benar dengan yang salah, dan kamu pula menyembunyikan kebenaran padahal kamu mengetahuinya?', FALSE, NULL, NULL, 59, 3, 23, 48, FALSE, 0, NULL),
(3, 72, 'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', 'وَقَالَت طَّائِفَةٌ مِّنْ أَهْلِ الْكِتَابِ آمِنُوا بِالَّذِي أُنزِلَ عَلَى الَّذِينَ آمَنُوا وَجْهَ النَّهَارِ وَاكْفُرُوا آخِرَهُ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And a faction of the People of the Scripture say [to each other], "Believe in that which was revealed to the believers at the beginning of the day and reject it at its end that perhaps they will return [i.e., abandon their religion],', 'Dan berkatalah segolongan dari Ahli Kitab (sesama sendiri): “Berimanlah kamu kepada Al-Quran yang diturunkan kepada orang-orang yang beriman itu: pada sebelah pagi, dan kufurlah (ingkarlah) pada petangnya, supaya mereka (merasa ragu-ragu, lalu) kembali menjadi kafir semula”.', FALSE, NULL, NULL, 59, 3, 23, 49, FALSE, 0, NULL),
(3, 73, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'وَلَا تُؤْمِنُوا إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ الْهُدَىٰ هُدَى اللَّهِ أَن يُؤْتَىٰ أَحَدٌ مِّثْلَ مَا أُوتِيتُمْ أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ قُلْ إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'And do not trust except those who follow your religion." Say, "Indeed, the [true] guidance is the guidance of Allāh. [Do you fear] lest someone be given [knowledge] like you were given or that they would [thereby] argue with you before your Lord?" Say, "Indeed, [all] bounty is in the hand of Allāh - He grants it to whom He wills. And Allāh is all-Encompassing and Wise."', 'Dan (mereka berkata lagi): “Janganlah kamu percaya melainkan kepada orang-orang yang mengikut ugama kamu”. Katakanlah (wahai Muhammad): “Sesungguhnya petunjuk yang sebenar benarnya ialah petunjuk Allah”. (Mereka berkata pula: “Janganlah kamu percaya) bahawa akan diberi kepada sesiapa seperti apa yang telah diberikan kepada kamu, atau mereka akan dapat mengalahkan hujah kamu di sisi Tuhan kamu”. Katakanlah (wahai Muhammad): “Sesungguhnya limpah kurnia itu adalah di tangan Allah, diberikanNya kepada sesiapa yang dikehendakiNya; dan Allah Maha Luas limpah kurniaNya, lagi Meliputi pengetahuanNya.', FALSE, NULL, NULL, 59, 3, 23, 49, FALSE, 0, NULL),
(3, 74, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ', NULL, 'He selects for His mercy whom He wills. And Allāh is the possessor of great bounty.', 'Allah menentukan pemberian rahmatNya itu kepada sesiapa yang dikehendakiNya; dan (ingatlah), Allah mempunyai limpah kurnia yang besar.', FALSE, NULL, NULL, 59, 3, 23, 49, FALSE, 0, NULL),
(3, 75, 'وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'وَمِنْ أَهْلِ الْكِتَابِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَائِمًا ذَٰلِكَ بِأَنَّهُمْ قَالُوا لَيْسَ عَلَيْنَا فِي الْأُمِّيِّينَ سَبِيلٌ وَيَقُولُونَ عَلَى اللَّهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ', NULL, 'And among the People of the Scripture is he who, if you entrust him with a great amount [of wealth], he will return it to you. And among them is he who, if you entrust him with a [single] coin, he will not return it to you unless you are constantly standing over him [demanding it]. That is because they say, "There is no blame upon us concerning the unlearned." And they speak untruth about Allāh while they know [it].', 'Dan di antara Ahli Kitab, ada orang yang kalau engkau amanahkan dia menyimpan sejumlah besar harta sekalipun, ia akan mengembalikannya (dengan sempurna) kepadamu, dan ada pula di antara mereka yang kalau engkau amanahkan menyimpan sedinar pun, ia tidak akan mengembalikannya kepadamu kecuali kalau engkau selalu menuntutnya. Yang demikian itu ialah kerana mereka mengatakan: “Tidak ada jalannya kami menanggung dosa mengenai orang-orang yang Ummi dan, mereka pula selalu berkata dusta terhadap Allah sedang mereka mengetahui (bahawa mereka adalah berdusta).', FALSE, NULL, NULL, 59, 3, 24, 49, FALSE, 0, NULL),
(3, 76, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِ وَاتَّقَىٰ فَإِنَّ اللَّهَ يُحِبُّ الْمُتَّقِينَ', NULL, 'But yes, whoever fulfills his commitment and fears Allāh - then indeed, Allāh loves those who fear Him.', 'Bahkan (mereka berdosa memakan hak orang, kerana), sesiapa yang menyempurnakan janjinya (mengenai hak orang lain) dan bertaqwa, maka sesungguhnya Allah mengasihi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 59, 3, 24, 49, FALSE, 0, NULL),
(3, 77, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا أُولَٰئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَةِ وَلَا يُكَلِّمُهُمُ اللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Indeed, those who exchange the covenant of Allāh and their [own] oaths for a small price will have no share in the Hereafter, and Allāh will not speak to them or look at them on the Day of Resurrection, nor will He purify them; and they will have a painful punishment.', 'Sesungguhnya orang-orang yang mengutamakan keuntungan dunia yang sedikit dengan menolak janji Allah dan mencabuli sumpah mereka, mereka tidak akan mendapat bahagian yang baik pada hari akhirat, dan Allah tidak akan berkata-kata dengan mereka dan tidak akan memandang kepada mereka pada hari Kiamat, dan tidak akan membersihkan mereka (dari dosa), dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 59, 3, 24, 49, FALSE, 0, NULL),
(3, 78, 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُونَ أَلْسِنَتَهُم بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِندِ اللَّهِ وَمَا هُوَ مِنْ عِندِ اللَّهِ وَيَقُولُونَ عَلَى اللَّهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ', NULL, 'And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, "This is from Allāh," but it is not from Allāh. And they speak untruth about Allāh while they know.', 'Dan sesungguhnya, di antara mereka (Ahli Kitab itu) ada (Ketua-ketua ugamanya) yang memutar-mutar lidahnya semasa membaca Kitab Taurat (dengan mengubah maknanya), supaya kamu menyangkanya sebahagian dari Kitab Taurat padahal ia bukanlah dari Kitab itu. Dan mereka pula berkata: “(bahawa) ia adalah (datangnya) dari sisi Allah”, padahal ia bukanlah dari sisi Allah; dan mereka pula tergamak berkata dusta terhadap Allah sedang mereka mengetahui (bahawa mereka adalah berdusta).', FALSE, NULL, NULL, 60, 3, 24, 49, FALSE, 0, NULL),
(3, 79, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ اللَّهُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا عِبَادًا لِّي مِن دُونِ اللَّهِ وَلَٰكِن كُونُوا رَبَّانِيِّينَ بِمَا كُنتُمْ تُعَلِّمُونَ الْكِتَابَ وَبِمَا كُنتُمْ تَدْرُسُونَ', NULL, 'It is not for a human [prophet] that Allāh should give him the Scripture and authority and prophethood and then he would say to the people, "Be servants to me rather than Allāh," but [instead, he would say], "Be pious scholars of the Lord because of what you have taught of the Scripture and because of what you have studied."', 'Tidaklah patut bagi seseorang manusia yang Allah berikan kepadanya Kitab ugama dan hikmat serta pangkat Nabi, kemudian ia tergamak mengatakan kepada orang ramai: “Hendaklah kamu menjadi orang-orang yang menyembahku dengan meninggalkan perbuatan menyembah Allah”. Tetapi (sepatutnya ia berkata): “Hendaklah kamu menjadi orang-orang Rabbaniyin (yang hanya menyembah Allah Taala - dengan ilmu dan amal yang sempurna), kerana kamu sentiasa mengajarkan isi Kitab Allah itu, dan kerana kamu selalu mempelajarinya.', FALSE, NULL, NULL, 60, 3, 24, 49, FALSE, 0, NULL),
(3, 80, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا الْمَلَائِكَةَ وَالنَّبِيِّينَ أَرْبَابًا أَيَأْمُرُكُم بِالْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', NULL, 'Nor could he order you to take the angels and prophets as lords. Would he order you to disbelief after you had been Muslims?', 'Dan ia tidak pula patut menyuruh kamu menjadikan malaikat dan Nabi-nabi sebagai tuhan-tuhan. Patutkah ia menyuruh kamu dengan kekufuran sesudah kamu menjadi orang Islam?', FALSE, NULL, NULL, 60, 3, 24, 49, FALSE, 0, NULL),
(3, 81, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى قَالُوٓا۟ أَقْرَرْنَا قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 'وَإِذْ أَخَذَ اللَّهُ مِيثَاقَ النَّبِيِّينَ لَمَا آتَيْتُكُم مِّن كِتَابٍ وَحِكْمَةٍ ثُمَّ جَاءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِ وَلَتَنصُرُنَّهُ قَالَ أَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِي قَالُوا أَقْرَرْنَا قَالَ فَاشْهَدُوا وَأَنَا مَعَكُم مِّنَ الشَّاهِدِينَ', NULL, 'And [recall, O People of the Scripture], when Allāh took the covenant of the prophets, [saying], "Whatever I give you of the Scripture and wisdom and then there comes to you a messenger confirming what is with you, you [must] believe in him and support him." [Allāh] said, "Have you acknowledged and taken upon that My commitment?" They said, "We have acknowledged it." He said, "Then bear witness, and I am with you among the witnesses."', 'Dan (ingatlah) ketika Allah mengambil perjanjian setia dari Nabi-nabi (dengan firmanNya): “Sesungguhnya apa jua Kitab dan Hikmat yang Aku berikan kepada kamu, kemudian datang pula kepada Kamu seorang Rasul yang mengesahkan apa yang ada pada kamu, hendaklah kamu beriman sungguh-sungguh kepadanya, dan hendaklah kamu bersungguh-sungguh menolongnya”. Allah berfirman lagi (bertanya kepada mereka): “Sudahkah kamu mengakui dan sudahkah kamu menerima akan ikatan janjiku secara yang demikian itu?” Mereka menjawab: “Kami berikrar (mengakui dan menerimanya)”. Allah berfirman lagi: “Jika demikian, maka saksikanlah kamu, dan Aku juga menjadi saksi bersama-sama kamu.”', FALSE, NULL, NULL, 60, 3, 24, 50, FALSE, 0, NULL),
(3, 82, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ', NULL, 'And whoever turned away after that - they were the defiantly disobedient.', 'Kemudian sesiapa yang berpaling ingkar sesudah mengakui perjanjian setia itu, maka mereka itulah orang-orang yang fasik.', FALSE, NULL, NULL, 60, 3, 24, 50, FALSE, 0, NULL),
(3, 83, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', 'أَفَغَيْرَ دِينِ اللَّهِ يَبْغُونَ وَلَهُ أَسْلَمَ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', NULL, 'So is it other than the religion of Allāh they desire, while to Him have submitted [all] those within the heavens and earth, willingly or by compulsion, and to Him they will be returned?', 'Patutkah sesudah (mengakui dan menerima perjanjian) itu, mereka mencari lain dari ugama Allah? Padahal kepadaNyalah tunduk taat sekalian makhluk yang ada di langit dan di bumi, sama ada dengan sukarela ataupun terpaksa, dan kepadaNya lah mereka dikembalikan.', FALSE, NULL, NULL, 60, 3, 24, 50, FALSE, 0, NULL),
(3, 84, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'قُلْ آمَنَّا بِاللَّهِ وَمَا أُنزِلَ عَلَيْنَا وَمَا أُنزِلَ عَلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَالنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ', NULL, 'Say, "We have believed in Allāh and in what was revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and the Descendants [al-Asbāṭ], and in what was given to Moses and Jesus and to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [submitting] to Him."', 'Katakanlah (wahai Muhammad): “Kami beriman kepada Allah, dan kepada apa yang telah diturunkan kepada kami, dan kepada apa yang telah diturunkan kepada Nabi-nabi: Ibrahim, dan lsmail, dan Ishak, dan Yaakub, dan keturunannya, dan kepada apa yang telah diberikan kepada Nabi-nabi: Musa dan Isa, dan sekalian Nabi-nabi dari Tuhan mereka. Kami tidak membeza-bezakan seseorang pun di antara mereka, dan kepada Allah jualah kami berserah diri (Islam)”.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 85, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'وَمَن يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخَاسِرِينَ', NULL, 'And whoever desires other than Islām as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers.', 'Dan sesiapa yang mencari ugama selain ugama Islam, maka tidak akan diterima daripadanya, dan ia pada hari akhirat kelak dari orang-orang yang rugi.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 86, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'كَيْفَ يَهْدِي اللَّهُ قَوْمًا كَفَرُوا بَعْدَ إِيمَانِهِمْ وَشَهِدُوا أَنَّ الرَّسُولَ حَقٌّ وَجَاءَهُمُ الْبَيِّنَاتُ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'How shall Allāh guide a people who disbelieved after their belief and had witnessed that the Messenger is true and clear signs had come to them? And Allāh does not guide the wrongdoing people.', 'Bagaimana Allah akan memberi petunjuk hidayah kepada sesuatu kaum yang kufur ingkar sesudah mereka beriman, dan juga sesudah mereka menyaksikan bahawa Rasulullah (Nabi Muhammad) itu adalah benar, dan telah datang pula kepada mereka keterangan-keterangan yang jelas nyata. Dan (ingatlah), Allah tidak akan memberikan petunjuk hidayahNya kepada kaum yang zalim.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 87, 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'أُولَٰئِكَ جَزَاؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ', NULL, 'Those - their recompense will be that upon them is the curse of Allāh and the angels and the people, all together,', 'Mereka itu balasannya ialah bahawa mereka ditimpa laknat Allah dan malaikatNya sekalian orang-orang (yang beriman).', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 88, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ', NULL, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved,', 'Mereka kekal di dalamnya, tidak diringankan azab seksa daripada mereka dan mereka pula tidak diberi tempoh atau perhatian;', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 89, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَٰلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'Except for those who repent after that and correct themselves. For indeed, Allāh is Forgiving and Merciful.', 'Kecuali orang-orang yang bertaubat sesudah (ingkar) itu, serta memperbaiki keburukan mereka, maka sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 90, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', 'إِنَّ الَّذِينَ كَفَرُوا بَعْدَ إِيمَانِهِمْ ثُمَّ ازْدَادُوا كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُولَٰئِكَ هُمُ الضَّالُّونَ', NULL, 'Indeed, those who disbelieve [i.e., reject the message] after their belief and then increase in disbelief - never will their [claimed] repentance be accepted, and they are the ones astray.', 'Sesungguhnya orang-orang yang kafir sesudah mereka beriman, kemudian mereka bertambah kufur lagi, tidak sekali-kali akan diterima taubat mereka, dan mereka itulah orang-orang yang sesat.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 91, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ الْأَرْضِ ذَهَبًا وَلَوِ افْتَدَىٰ بِهِ أُولَٰئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّاصِرِينَ', NULL, 'Indeed, those who disbelieve and die while they are disbelievers - never would the [whole] capacity of the earth in gold be accepted from one of them if he would [seek to] ransom himself with it. For those there will be a painful punishment, and they will have no helpers.', 'Sesungguhnya orang-orang yang kafir, lalu mati sedang mereka tetap kafir, maka tidak sekali-kali akan diterima dari seseorang di antara mereka: emas sepenuh bumi, walaupun ia menebus dirinya dengan (emas yang sebanyak) itu. Mereka itu akan mendapat azab seksa yang tidak terperi sakitnya, dan mereka pula tidak akan beroleh seorang penolong pun.', FALSE, NULL, NULL, 61, 3, 24, 50, FALSE, 0, NULL),
(3, 92, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'لَن تَنَالُوا الْبِرَّ حَتَّىٰ تُنفِقُوا مِمَّا تُحِبُّونَ وَمَا تُنفِقُوا مِن شَيْءٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ', NULL, 'Never will you attain the good [reward] until you spend [in the way of Allāh] from that which you love. And whatever you spend - indeed, Allāh is Knowing of it.', 'Kamu tidak sekali-kali akan dapat mencapai (hakikat) kebajikan dan kebaktian (yang sempurna) sebelum kamu dermakan sebahagian dari apa yang kamu sayangi. Dan sesuatu apa jua yang kamu dermakan maka sesungguhnya Allah mengetahuinya.', FALSE, NULL, NULL, 62, 3, 24, 51, FALSE, 0, NULL),
(3, 93, 'كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', 'كُلُّ الطَّعَامِ كَانَ حِلًّا لِّبَنِي إِسْرَائِيلَ إِلَّا مَا حَرَّمَ إِسْرَائِيلُ عَلَىٰ نَفْسِهِ مِن قَبْلِ أَن تُنَزَّلَ التَّوْرَاةُ قُلْ فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا إِن كُنتُمْ صَادِقِينَ', NULL, 'All food was lawful to the Children of Israel except what Israel [i.e., Jacob] had made unlawful to himself before the Torah was revealed. Say, [O Muḥammad], "So bring the Torah and recite it, if you should be truthful."', 'Segala jenis makanan dahulu adalah halal bagi Bani Israil, kecuali makanan yang diharamkan oleh Israil (Nabi Yaakub) kepada dirinya sendiri sebelum diturunkan Kitab Taurat. Katakanlah (wahai Muhammad): “(Jika ada makanan yang diharamkan kepada kamu - wahai Bani Israil - sebelum Kitab Taurat diturunkan) maka bawalah kamu Kitab Taurat itu kemudian bacalah akan dia, kalau betul kamu orang-orang yang benar.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 94, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'فَمَنِ افْتَرَىٰ عَلَى اللَّهِ الْكَذِبَ مِن بَعْدِ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ', NULL, 'And whoever invents about Allāh untruth after that - then those are [truly] the wrongdoers.', '(Jika tidak) maka sesiapa yang mereka-reka kata-kata dusta terhadap Allah sesudah yang demikian itu, maka mereka itulah orang-orang yang zalim.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 95, 'قُلْ صَدَقَ ٱللَّهُ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'قُلْ صَدَقَ اللَّهُ فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', NULL, 'Say, "Allāh has told the truth. So follow the religion of Abraham, inclining toward truth; and he was not of the polytheists."', 'Katakanlah (wahai Muhammad): “Benarlah (apa yang difirmankan oleh) Allah, maka ikutilah kamu akan ugama Nabi Ibrahim yang ikhlas (berdasarkan Tauhid), dan bukanlah ia dari orang-orang musyrik.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 96, 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَٰلَمِينَ', 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَالَمِينَ', NULL, 'Indeed, the first House [of worship] established for mankind was that at Bakkah [i.e., Makkah] - blessed and a guidance for the worlds.', 'Sesungguhnya Rumah Ibadat yang mula-mula dibina untuk manusia (beribadat kepada Tuhannya) ialah Baitullah yang di Makkah yang berkat dan (dijadikan) petunjuk hidayah bagi umat manusia.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 97, 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌ مَّقَامُ إِبْرَٰهِيمَ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'فِيهِ آيَاتٌ بَيِّنَاتٌ مَّقَامُ إِبْرَاهِيمَ وَمَن دَخَلَهُ كَانَ آمِنًا وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ عَنِ الْعَالَمِينَ', NULL, 'In it are clear signs [such as] the standing place of Abraham. And whoever enters it [i.e., the Ḥaram] shall be safe. And [due] to Allāh from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves [i.e., refuses] - then indeed, Allāh is free from need of the worlds.', 'Di situ ada tanda-tanda keterangan yang nyata (yang menunjukkan kemuliaannya; di antaranya ialah) Makam Nabi Ibrahim. Dan sesiapa yang masuk ke dalamnya aman tenteramlah dia. Dan Allah mewajibkan manusia mengerjakan ibadat Haji dengan mengunjungi Baitullah iaitu sesiapa yang mampu sampai kepadanya. Dan sesiapa yang kufur (ingkarkan kewajipan ibadat Haji itu), maka sesungguhnya Allah Maha Kaya (tidak berhajatkan sesuatu pun) dari sekalian makhluk.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 98, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 'قُلْ يَا أَهْلَ الْكِتَابِ لِمَ تَكْفُرُونَ بِآيَاتِ اللَّهِ وَاللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', NULL, 'Say, "O People of the Scripture, why do you disbelieve in the verses of Allāh while Allāh is Witness over what you do?"', 'Katakanlah (wahai Muhammad): “Wahai Ahli Kitab! Mengapa kamu ingkarkan keterangan-keterangan Allah, padahal Allah sentiasa menyaksikan apa yang kamu lakukan?”', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 99, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'قُلْ يَا أَهْلَ الْكِتَابِ لِمَ تَصُدُّونَ عَن سَبِيلِ اللَّهِ مَنْ آمَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَاءُ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'Say, "O People of the Scripture, why do you avert from the way of Allāh those who believe, seeking to make it [seem] deviant, while you are witnesses [to the truth]? And Allāh is not unaware of what you do."', 'Katakanlah: “Wahai Ahli Kitab! Mengapa kamu menghalangi orang-orang yang beriman daripada menurut jalan jalan (ugama Islam), kamu hendak menjadikan jalan Allah itu bengkok terpesong, padahal kamu menyaksikan (kebenarannya)? “Dan (ingatlah), Allah tidak sekali-kali lalai akan apa yang kamu lakukan.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 100, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تُطِيعُوا فَرِيقًا مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ يَرُدُّوكُم بَعْدَ إِيمَانِكُمْ كَافِرِينَ', NULL, 'O you who have believed, if you obey a party of those who were given the Scripture, they would turn you back, after your belief, [to being] unbelievers.', 'Wahai orang-orang yang beriman! Jika kamu taat akan sesuatu puak dari orang-orang (Yahudi dan Nasrani) yang diberikan Kitab itu, nescaya mereka akan mengembalikan kamu menjadi orang-orang kafir sesudah kamu beriman.', FALSE, NULL, NULL, 62, 4, 25, 51, FALSE, 0, NULL),
(3, 101, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ آيَاتُ اللَّهِ وَفِيكُمْ رَسُولُهُ وَمَن يَعْتَصِم بِاللَّهِ فَقَدْ هُدِيَ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And how could you disbelieve while to you are being recited the verses of Allāh and among you is His Messenger? And whoever holds firmly to Allāh has [indeed] been guided to a straight path.', 'Dan bagaimana kamu akan menjadi kafir padahal kepada kamu dibacakan ayat-ayat Allah (Al-Quran), dan dalam kalangan kamu ada RasulNya (Muhammad, s.a.w)? Dan sesiapa berpegang teguh kepada (ugama) Allah, maka sesungguhnya ia telah beroleh petunjuk hidayah ke jalan yang betul (lurus).', FALSE, NULL, NULL, 63, 4, 25, 51, FALSE, 0, NULL),
(3, 102, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', NULL, 'O you who have believed, fear Allāh as He should be feared and do not die except as Muslims [in submission to Him].', 'Wahai orang-orang yang beriman! Bertaqwalah kamu kepada Allah dengan sebenar-benar taqwa, dan jangan sekali-kali kamu mati melainkan dalam keadaan Islam.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 103, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', 'وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا وَاذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَاءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِ إِخْوَانًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ النَّارِ فَأَنقَذَكُم مِّنْهَا كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَهْتَدُونَ', NULL, 'And hold firmly to the rope of Allāh all together and do not become divided. And remember the favor of Allāh upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allāh make clear to you His verses that you may be guided.', 'Dan berpegang teguhlah kamu sekalian kepada tali Allah (ugama Islam), dan janganlah kamu bercerai-berai; dan kenanglah nikmat Allah kepada kamu ketika kamu bermusuh-musuhan (semasa jahiliyah dahulu), lalu Allah menyatukan di antara hati kamu (sehingga kamu bersatu-padu dengan nikmat Islam), maka menjadilah kamu dengan nikmat Allah itu orang-orang Islam yang bersaudara. Dan kamu dahulu telah berada di tepi jurang neraka (disebabkan kekufuran kamu semasa jahiliyah), lalu Allah selamatkan kamu dari neraka itu (disebabkan nikmat Islam juga). Demikianlah Allah menjelaskan kepada kamu ayat-ayat keteranganNya, supaya kamu mendapat petunjuk hidayahNya.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 104, 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful.', 'Dan hendaklah ada di antara kamu satu puak yang menyeru (berdakwah) kepada kebajikan (mengembangkan Islam), dan menyuruh berbuat segala perkara yang baik, serta melarang daripada segala yang salah (buruk dan keji). Dan mereka yang bersifat demikian ialah orang-orang yang berjaya.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 105, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', 'وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِن بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ وَأُولَٰئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', NULL, 'And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment', 'Dan janganlah kamu menjadi seperti orang-orang (Yahudi dan Nasrani) yang telah berceri-berai dan berselisihan (dalam ugama mereka) sesudah datang kepada mereka keterangan-keterangan yang jelas nyata (yang dibawa oleh Nabi-nabi Allah), Dan mereka yang bersifat demikian, akan beroleh azab seksa yang besar.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا الَّذِينَ اسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَانِكُمْ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', NULL, 'On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], "Did you disbelieve [i.e., reject faith] after your belief? Then taste the punishment for what you used to reject."', '(Ingatlah akan) hari (kiamat yang padanya) ada muka (orang-orang) menjadi putih berseri, dan ada muka (orang-orang) menjadi hitam legam. Adapun orang-orang yang telah hitam legam mukanya, (mereka akan ditanya secara menempelak): “Patutkah kamu kufur ingkar sesudah kamu beriman? Oleh itu rasalah azab seksa neraka disebabkan kekufuran kamu itu”.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 107, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', 'وَأَمَّا الَّذِينَ ابْيَضَّتْ وُجُوهُهُمْ فَفِي رَحْمَةِ اللَّهِ هُمْ فِيهَا خَالِدُونَ', NULL, 'But as for those whose faces turn white, [they will be] within the mercy of Allāh. They will abide therein eternally.', 'Adapun orang-orang yang telah putih berseri mukanya, maka mereka berada dalam limpah rahmat Allah (Syurga), mereka kekal di dalamnya.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 108, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَٰلَمِينَ', 'تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِّلْعَالَمِينَ', NULL, 'These are the verses of Allāh. We recite them to you, [O Muḥammad], in truth; and Allāh wants no injustice to the worlds [i.e., His creatures].', 'Itulah ayat-ayat keterangan Allah, kami bacakan dia kepadamu (wahai Muhammad) dengan benar. Dan (ingatlah), Allah tidak berkehendak melakukan kezaliman kepada sekalian makhlukNya.', FALSE, NULL, NULL, 63, 4, 25, 52, FALSE, 0, NULL),
(3, 109, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ', NULL, 'To Allāh belongs whatever is in the heavens and whatever is on the earth. And to Allāh will [all] matters be returned.', 'Dan bagi Allah jualah hak milik segala yang ada di langit dan yang ada di bumi, dan kepada Allah jualah dikembalikan segala urusan.', FALSE, NULL, NULL, 64, 4, 25, 52, FALSE, 0, NULL),
(3, 110, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًا لَّهُم مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ وَلَوْ آمَنَ أَهْلُ الْكِتَابِ لَكَانَ خَيْرًا لَّهُم مِّنْهُمُ الْمُؤْمِنُونَ وَأَكْثَرُهُمُ الْفَاسِقُونَ', NULL, 'You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allāh. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient.', 'Kamu (wahai umat Muhammad) adalah sebaik-baik umat yang dilahirkan bagi (faedah) umat manusia, (kerana) kamu menyuruh berbuat segala perkara yang baik dan melarang daripada segala perkara yang salah (buruk dan keji), serta kamu pula beriman kepada Allah (dengan sebenar-benar iman). Dan kalaulah Ahli Kitab (Yahudi dan Nasrani) itu beriman (sebagaimana yang semestinya), tentulah (iman) itu menjadi baik bagi mereka. (Tetapi) di antara mereka ada yang beriman dan kebanyakan mereka: orang-orang yang fasik.', FALSE, NULL, NULL, 64, 4, 25, 53, FALSE, 0, NULL),
(3, 111, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًى وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 'لَن يَضُرُّوكُمْ إِلَّا أَذًى وَإِن يُقَاتِلُوكُمْ يُوَلُّوكُمُ الْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', NULL, 'They will not harm you except for [some] annoyance. And if they fight you, they will show you their backs [i.e., retreat]; then they will not be aided.', 'Mereka (kaum Yahudi dan Nasrani) tidak sekali-kali akan membahayakan kamu, kecuali menyakiti (perasaan kamu dengan ejekan dan tuduhan yang tidak berasas). Dan jika mereka memerangi kamu, mereka akan berpaling lari membelakangkan kamu (kalah dengan sehina-hinanya); sesudah itu mereka tidak akan mencapai kemenangan.', FALSE, NULL, NULL, 64, 4, 25, 53, FALSE, 0, NULL),
(3, 112, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ أَيْنَ مَا ثُقِفُوا إِلَّا بِحَبْلٍ مِّنَ اللَّهِ وَحَبْلٍ مِّنَ النَّاسِ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ', NULL, 'They have been put under humiliation [by Allāh] wherever they are overtaken, except for a rope [i.e., covenant] from Allāh and a rope [i.e., treaty] from the people [i.e., the Muslims]. And they have drawn upon themselves anger from Allāh and have been put under destitution. That is because they disbelieved in [i.e., rejected] the verses of Allāh and killed the prophets without right. That is because they disobeyed and [habitually] transgressed.', 'Mereka ditimpakan kehinaan (dari segala jurusan) di mana sahaja mereka berada, kecuali dengan adanya sebab dari Allah dan adanya sebab dari manusia. Dan sudah sepatutnya mereka beroleh kemurkaan dari Allah, dan mereka ditimpakan kemiskinan (dari segala jurusan). Yang demikian itu, disebabkan mereka sentiasa kufur ingkar akan ayat-ayat Allah (perintah-perintahNya), dan mereka membunuh Nabi-nabi dengan tiada alasan yang benar. Semuanya itu disebabkan mereka derhaka dan mereka sentiasa mencerobohi (hukum-hukum Allah).', FALSE, NULL, NULL, 64, 4, 25, 53, FALSE, 0, NULL),
(3, 113, 'لَيْسُوا۟ سَوَآءً مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', 'لَيْسُوا سَوَاءً مِّنْ أَهْلِ الْكِتَابِ أُمَّةٌ قَائِمَةٌ يَتْلُونَ آيَاتِ اللَّهِ آنَاءَ اللَّيْلِ وَهُمْ يَسْجُدُونَ', NULL, 'They are not [all] the same; among the People of the Scripture is a community standing [in obedience], reciting the verses of Allāh during periods of the night and prostrating [in prayer].', 'Ahli-ahli Kitab itu tidaklah sama. Di antaranya ada golongan yang (telah memeluk Islam dan) tetap (berpegang kepada ugama Allah yang benar) mereka membaca ayat-ayat Allah (Al-Quran) pada waktu malam, semasa mereka sujud (mengerjakan sembahyang).', FALSE, NULL, NULL, 64, 4, 26, 53, FALSE, 0, NULL),
(3, 114, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 'يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُسَارِعُونَ فِي الْخَيْرَاتِ وَأُولَٰئِكَ مِنَ الصَّالِحِينَ', NULL, 'They believe in Allāh and the Last Day, and they enjoin what is right and forbid what is wrong and hasten to good deeds. And those are among the righteous.', 'Mereka beriman kepada Allah dan hari akhirat, dan menyuruh berbuat segala perkara yang baik, dan melarang daripada segala perkara yang salah (buruk dan keji), dan mereka pula segera segera pada mengerjakan berbagai-bagai kebajikan. Mereka (yang demikian sifatnya), adalah dari orang-orang yang soleh.', FALSE, NULL, NULL, 64, 4, 26, 53, FALSE, 0, NULL),
(3, 115, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'وَمَا يَفْعَلُوا مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ', NULL, 'And whatever good they do - never will it be denied them. And Allāh is Knowing of the righteous.', 'Dan apa sahaja kebajikan yang mereka kerjakan, maka mereka tidak sekali-kali akan diingkari (atau disekat dari mendapat pahalanya). Dan (ingatlah), Allah sentiasa mengetahui akan keadaan orang-orang yang bertaqwa.', FALSE, NULL, NULL, 64, 4, 26, 53, FALSE, 0, NULL),
(3, 116, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'إِنَّ الَّذِينَ كَفَرُوا لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allāh at all, and those are the companions of the Fire; they will abide therein eternally.', 'Sesungguhnya orang-orang yang kafir, harta benda mereka dan anak-anak mereka, tidak sekali-kali akan dapat menyelamatkan mereka dari (azab) Allah sedikitpun, dan mereka itu ialah ahli neraka; mereka kekal di dalamnya.', FALSE, NULL, NULL, 65, 4, 26, 53, FALSE, 0, NULL),
(3, 117, 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 'مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ الْحَيَاةِ الدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوا أَنفُسَهُمْ فَأَهْلَكَتْهُ وَمَا ظَلَمَهُمُ اللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'The example of what they spend in this worldly life is like that of a wind containing frost which strikes the harvest of a people who have wronged themselves [i.e., sinned] and destroys it. And Allāh has not wronged them, but they wrong themselves.', 'Bandingan apa yang mereka belanjakan dalam kehidupan dunia ini (sekalipun untuk amal-amal yang baik), samalah seperti angin yang membawa udara yang amat sejuk, yang menimpa tanaman kaum yang menganiaya diri mereka sendiri, lalu membinasakannya; dan (ingatlah), Allah tidak menganiaya mereka, tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 65, 4, 26, 53, FALSE, 0, NULL),
(3, 118, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ إِن كُنتُمْ تَعْقِلُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا مَا عَنِتُّمْ قَدْ بَدَتِ الْبَغْضَاءُ مِنْ أَفْوَاهِهِمْ وَمَا تُخْفِي صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ الْآيَاتِ إِن كُنتُمْ تَعْقِلُونَ', NULL, 'O you who have believed, do not take as intimates those other than yourselves [i.e., believers], for they will not spare you [any] ruin. They wish you would have hardship. Hatred has already appeared from their mouths, and what their breasts conceal is greater. We have certainly made clear to you the signs, if you will use reason.', 'Wahai orang-orang yang beriman! Janganlah kamu mengambil orang-orang yang bukan dari kalangan kamu menjadi “orang dalam” (yang dipercayai). Mereka tidak akan berhenti-henti berusaha mendatangkan bencana kepada kamu. Mereka sukakan apa yang menyusahkan kamu. Telahpun nyata (tanda) kebencian mereka pada pertuturan mulutnya, dan apa yang disembunyikan oleh hati mereka lebih besar lagi. Sesungguhnya telah kami jelaskan kepada kamu keterangan-keterangan itu jika kamu (mahu) memahaminya.', FALSE, NULL, NULL, 65, 4, 26, 53, FALSE, 0, NULL),
(3, 119, 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ قُلْ مُوتُوا۟ بِغَيْظِكُمْ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'هَا أَنتُمْ أُولَاءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِالْكِتَابِ كُلِّهِ وَإِذَا لَقُوكُمْ قَالُوا آمَنَّا وَإِذَا خَلَوْا عَضُّوا عَلَيْكُمُ الْأَنَامِلَ مِنَ الْغَيْظِ قُلْ مُوتُوا بِغَيْظِكُمْ إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, 'Here you are loving them but they are not loving you, while you believe in the Scripture - all of it. And when they meet you, they say, "We believe." But when they are alone, they bite their fingertips at you in rage. Say, "Die in your rage. Indeed, Allāh is Knowing of that within the breasts."', 'Awaslah! Kamu ini adalah orang-orang (yang melanggar larangan), kamu sahajalah yang suka (dan percayakan mereka, sedang mereka tidak suka kepada kamu. kamu juga beriman kepada segala Kitab Allah (sedang mereka tidak beriman kepada Al-Quran). Dan apabila mereka bertemu dengan kamu mereka berkata: “Kami beriman”, tetapi apabila mereka berkumpul sesama sendiri, mereka menggigit hujung jari kerana geram marah (kepada kamu), katakanlah (wahai Muhammad): “Matilah kamu dengan kemarahan kamu itu”. Sesungguhnya Allah sentiasa mengetahui akan segala (isi hati) yang ada di dalam dada.', FALSE, NULL, NULL, 65, 4, 26, 53, FALSE, 0, NULL),
(3, 120, 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا بِهَا وَإِن تَصْبِرُوا وَتَتَّقُوا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا إِنَّ اللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', NULL, 'If good touches you, it distresses them; but if harm strikes you, they rejoice at it. And if you are patient and fear Allāh, their plot will not harm you at all. Indeed, Allāh is encompassing of what they do.', 'Kalau kamu beroleh kebaikan (kemakmuran dan kemenangan, maka yang demikian) menyakitkan hati mereka; dan jika kamu ditimpa bencana, mereka bergembira dengannya. Dan kalau kamu sabar dan bertaqwa, (maka) tipu daya mereka tidak akan membahayakan kamu sedikitpun. Sesungguhnya Allah meliputi pengetahuanNya akan apa yang mereka lakukan.', FALSE, NULL, NULL, 65, 4, 26, 53, FALSE, 0, NULL),
(3, 121, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ الْمُؤْمِنِينَ مَقَاعِدَ لِلْقِتَالِ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'And [remember] when you, [O Muḥammad], left your family in the morning to post the believers at their stations for the battle [of Uḥud] - and Allāh is Hearing and Knowing -', 'Dan (ingatlah wahai Muhammad), ketika engkau keluar pada pagi hari dari rumah ahlimu (di Madinah), dengan tujuan menempatkan orang-orang yang beriman pada tempat masing-masing untuk berperang (di medan perang Uhud). Dan (ingatlah), Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 65, 4, 26, 54, FALSE, 0, NULL),
(3, 122, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'إِذْ هَمَّت طَّائِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَاللَّهُ وَلِيُّهُمَا وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', NULL, 'When two parties among you were about to lose courage, but Allāh was their ally; and upon Allāh the believers should rely.', '(Ingatlah) ketika dua puak dari kamu (pada hari peperangan Uhud itu) terasa lemah semangat (untuk meneruskan perjuangan) kerana takut, padahal Allah Penolong dan Pelindung mereka; dan (jika sudah demikian) kepada Allah sahajalah hendaknya orang-orang yang beriman itu bertawakal.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 123, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 'وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَاتَّقُوا اللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And already had Allāh given you victory at [the battle of] Badr while you were weak [i.e., few in number]. Then fear Allāh; perhaps you will be grateful.', 'Dan sesungguhnya Allah telah menolong kamu mencapai kemenangan dalam peperangan Badar, sedang kamu berkeadaan lemah (kerana kamu sedikit bilangannya dan kekurangan alat perang). Oleh itu bertaqwalah kamu kepada Allah, supaya kamu bersyukur (akan kemenangan itu).', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 124, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَاثَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُنزَلِينَ', NULL, '[Remember] when you said to the believers, "Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down?', '(Ingatlah wahai Muhammad) ketika engkau berkata kepada orang-orang yang beriman (untuk menguatkan semangat mereka): “Tidakkah cukup bagi kamu, bahawa Allah membantu kamu dengan tiga ribu tentera dari malaikat yang diturunkan?,”', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 125, 'بَلَىٰٓ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', 'بَلَىٰ إِن تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُسَوِّمِينَ', NULL, 'Yes, if you remain patient and conscious of Allāh and they [i.e., the enemy] come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction]."', 'Bahkan (mencukupi. Dalam pada itu) jika kamu bersabar dan bertaqwa, dan mereka (musuh) datang menyerang kamu dengan serta-merta, nescaya Allah membantu kamu dengan lima ribu malaikat yang bertanda masing-masing.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 126, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'وَمَا جَعَلَهُ اللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّهِ الْعَزِيزِ الْحَكِيمِ', NULL, 'And Allāh made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allāh, the Exalted in Might, the Wise -', 'Dan Allah tidak menjadikan bantuan tentera malaikat itu melainkan kerana memberi khabar gembira kepada kamu, dan supaya kamu tenteram dengan bantuan itu. Dan (ingatlah bahawa) pertolongan yang membawa kemenangan itu hanya dari Allah Yang Maha kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 127, 'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 'لِيَقْطَعَ طَرَفًا مِّنَ الَّذِينَ كَفَرُوا أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا خَائِبِينَ', NULL, 'That He might cut down a section of the disbelievers or suppress them so that they turn back disappointed.', '(Kemenangan Badar itu) kerana Allah hendak membinasakan satu golongan dari orang-orang kafir atau menghina mereka (dengan kekalahan), supaya mereka kembali dengan hampa kecewa.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 128, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', 'لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ', NULL, 'Not for you, [O Muḥammad, but for Allāh], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers.', 'Engkau tidak berhak sedikitpun (wahai Muhammad) dalam urusan (orang-orang yang ingkar) itu, (kerana urusan mereka tertentu bagi Allah), sama ada dia menerima taubat mereka ataupun Ia menyeksa mereka; kerana sesungguhnya mereka itu orang-orang yang zalim.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 129, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ يَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'And to Allāh belongs whatever is in the heavens and whatever is on the earth. He forgives whom He wills and punishes whom He wills. And Allāh is Forgiving and Merciful.', 'Dan bagi Allah jualah segala yang ada di langit dan yang ada di bumi. Ia mengampunkan sesiapa yang dikehendakiNya, dan dia menyeksa sesiapa yang dikehendakiNya. Dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 66, 4, 26, 54, FALSE, 0, NULL),
(3, 130, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًا مُّضَٰعَفَةً وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا الرِّبَا أَضْعَافًا مُّضَاعَفَةً وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, do not consume usury, doubled and multiplied, but fear Allāh that you may be successful.', 'Wahai orang-orang yang beriman! Janganlah kamu makan atau mengambil riba dengan berlipat-lipat ganda, dan hendaklah kamu bertaqwa kepada Allah supaya kamu berjaya.', FALSE, NULL, NULL, 66, 4, 26, 55, FALSE, 0, NULL),
(3, 131, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 'وَاتَّقُوا النَّارَ الَّتِي أُعِدَّتْ لِلْكَافِرِينَ', NULL, 'And fear the Fire, which has been prepared for the disbelievers.', 'Dan peliharalah diri kamu dari api neraka, yang disediakan bagi orang-orang kafir.', FALSE, NULL, NULL, 66, 4, 26, 55, FALSE, 0, NULL),
(3, 132, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'وَأَطِيعُوا اللَّهَ وَالرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'And obey Allāh and the Messenger that you may obtain mercy.', 'Dan taatlah kamu kepada Allah dan RasulNya, supaya kamu diberi rahmat.', FALSE, NULL, NULL, 66, 4, 26, 55, FALSE, 0, NULL),
(3, 133, 'وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'وَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', NULL, 'And hasten to forgiveness from your Lord and a garden [i.e., Paradise] as wide as the heavens and earth, prepared for the righteous', 'Dan segeralah kamu kepada (mengerjakan amal-amal yang baik untuk mendapat) keampunan dari Tuhan kamu, dan (mendapat) Syurga yang bidangnya seluas segala langit dan bumi, yang disediakan bagi orang-orang yang bertaqwa;', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 134, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'الَّذِينَ يُنفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ', NULL, 'Who spend [in the cause of Allāh] during ease and hardship and who restrain anger and who pardon the people - and Allāh loves the doers of good;', 'Iaitu orang-orang yang mendermakan hartanya pada masa senang dan susah, dan orang-orang yang menahan kemarahannya, dan orang-orang yang memaafkan kesalahan orang. Dan (ingatlah), Allah mengasihi orang-orang yang berbuat perkara-perkara yang baik;', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 135, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', 'وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ', NULL, 'And those who, when they commit an immorality or wrong themselves [by transgression], remember Allāh and seek forgiveness for their sins - and who can forgive sins except Allāh? - and [who] do not persist in what they have done while they know.', 'Dan juga orang-orang yang apabila melakukan perbuatan keji, atau menganiaya diri sendiri, mereka segera ingat kepada Allah lalu memohon ampun akan dosa mereka - dan sememangnya tidak ada yang mengampunkan dosa-dosa melainkan Allah -, dan mereka juga tidak meneruskan perbuatan keji yang mereka telah lakukan itu, sedang mereka mengetahui (akan salahnya dan akibatnya).', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 136, 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'أُولَٰئِكَ جَزَاؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ', NULL, 'Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers.', 'Orang-orang yang demikian sifatnya, balasannya ialah keampunan dari Tuhan mereka, dan Syurga-syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya; dan yang demikian itulah sebaik-baik balasan (bagi) orang-orang yang beramal.', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 137, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ', NULL, 'Similar situations [as yours] have passed on before you, so proceed throughout the earth and observe how was the end of those who denied.', 'Sesungguhnya telah berlaku sebelum kamu (contoh kejadian-kejadian berdasarkan) peraturan-peraturan Allah yang tetap; oleh itu mengembaralah kamu di muka bumi, kemudian perhatikanlah bagaimana akibat orang-orang yang mendustakan (Rasul-rasul).', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 138, 'هَٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', 'هَٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', NULL, 'This [Qur’ān] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allāh.', '(Al-Quran) ini ialah penerangan kepada seluruh umat manusia, dan petunjuk serta pengajaran bagi orang-orang yang (hendak) bertaqwa.', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 139, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 'وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'So do not weaken and do not grieve, and you will be superior if you are [true] believers.', 'Dan janganlah kamu merasa lemah (dalam perjuangan mempertahan dan menegakkan Islam), dan janganlah kamu berdukacita (terhadap apa yang akan menimpa kamu), padahal kamulah orang-orang yang tertinggi (mengatasi musuh dengan mencapai kemenangan) jika kamu orang-orang yang (sungguh-sungguh) beriman.', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 140, 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِّثْلُهُ وَتِلْكَ الْأَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِ وَلِيَعْلَمَ اللَّهُ الَّذِينَ آمَنُوا وَيَتَّخِذَ مِنكُمْ شُهَدَاءَ وَاللَّهُ لَا يُحِبُّ الظَّالِمِينَ', NULL, 'If a wound should touch you - there has already touched the [opposing] people a wound similar to it. And these days [of varying conditions] We alternate among the people so that Allāh may make evident those who believe and [may] take to Himself from among you martyrs - and Allāh does not like the wrongdoers -', 'Jika kamu (dalam peperangan Uhud) mendapat luka (tercedera), maka sesungguhnya kaum (musyrik yang mencerobohi kamu) itu telah (tercedera juga dan) mendaapat luka yang sama (dalam peperangan Badar). Dan demikian itulah keadaan hari-hari (dunia ini dengan peristiwa-peristiwa kemenangan atau kekalahan), kami gilirkan dia antara sesama manusia, (supaya menjadi pengajaran) dan supaya nyata apa yang diketahui Allah tentang orang-orang yang tetap beriman (dan yang sebaliknya), dan juga supaya Allah menjadikan sebahagian di antara kamu orang-orang yang mati Syahid. Dan (ingatlah), Allah tidak suka kepada orang-orang yang zalim.', FALSE, NULL, NULL, 67, 4, 27, 55, FALSE, 0, NULL),
(3, 141, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', 'وَلِيُمَحِّصَ اللَّهُ الَّذِينَ آمَنُوا وَيَمْحَقَ الْكَافِرِينَ', NULL, 'And that Allāh may purify the believers [through trials] and destroy the disbelievers.', 'Dan juga supaya Allah membersihkan orang-orang yang beriman (dari dosa-dosa mereka) dan membinasakan orang-orang yang kafir.', FALSE, NULL, NULL, 68, 4, 27, 55, FALSE, 0, NULL),
(3, 142, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَاهَدُوا مِنكُمْ وَيَعْلَمَ الصَّابِرِينَ', NULL, 'Or do you think that you will enter Paradise while Allāh has not yet made evident those of you who fight in His cause and made evident those who are steadfast?', 'Adakah kamu menyangka bahawa kamu akan masuk Syurga padahal belum lagi nyata kepada Allah (wujudnya) orang-orang yang berjihad (yang berjuang dengan bersungguh-sungguh) di antara kamu, dan (belum lagi) nyata (wujudnya) orang-orang yang sabar (tabah dan cekal hati dalam perjuangan)?', FALSE, NULL, NULL, 68, 4, 27, 55, FALSE, 0, NULL),
(3, 143, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ الْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', NULL, 'And you had certainly wished for death [i.e., martyrdom] before you encountered it, and you have [now] seen it [before you] while you were looking on.', 'Dan sesungguhnya kamu telah mengharap-harapkan mati Syahid (dalam perang Sabil) sebelum kamu menghadapinya. Maka sesungguhnya kamu (sekarang) telahpun menyaksikannya dan kamu sedang melihatnya (dengan mata kepala sendiri).', FALSE, NULL, NULL, 68, 4, 27, 55, FALSE, 0, NULL),
(3, 144, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ اللَّهَ شَيْئًا وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ', NULL, 'Muḥammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allāh at all; but Allāh will reward the grateful.', 'Dan Muhammad itu tidak lain hanyalah seorang Rasul yang sudahpun didahului oleh beberapa orang Rasul (yang telah mati atau terbunuh). Jika demikian, kalau ia pula mati atau terbunuh, (patutkah) kamu berbalik (berpaling tadah menjadi kafir)? Dan (ingatlah), sesiapa yang berbalik (menjadi kafir) maka ia tidak akan mendatangkan mudarat kepada Allah sedikitpun; dan (sebaliknya) Allah akan memberi balasan pahala kepada orang-orang yang bersyukur (akan nikmat Islam yang tidak ada bandingannya itu).', FALSE, NULL, NULL, 68, 4, 27, 56, FALSE, 0, NULL),
(3, 145, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًا مُّؤَجَّلًا وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا وَسَنَجْزِى ٱلشَّٰكِرِينَ', 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ اللَّهِ كِتَابًا مُّؤَجَّلًا وَمَن يُرِدْ ثَوَابَ الدُّنْيَا نُؤْتِهِ مِنْهَا وَمَن يُرِدْ ثَوَابَ الْآخِرَةِ نُؤْتِهِ مِنْهَا وَسَنَجْزِي الشَّاكِرِينَ', NULL, 'And it is not [possible] for one to die except by permission of Allāh at a decree determined. And whoever desires the reward of this world - We will give him thereof; and whoever desires the reward of the Hereafter - We will give him thereof. And We will reward the grateful.', 'Dan (tiap-tiap) makhluk yang bernyawa tidak akan mati melainkan dengan izin Allah, iaitu ketetapan (ajal) yang tertentu masanya (yang telah ditetapkan oleh Allah). Dan (dengan yang demikian) sesiapa yang menghendaki balasan dunia, kami berikan bahagiannya dari balasan dunia itu, dan sesiapa yang menghendaki balasan akhirat, kami berikan behagiannya dari balasan akhirat itu; dan Kami pula akan beri balasan pahala kepada orang-orang yang bersyukur.', FALSE, NULL, NULL, 68, 4, 27, 56, FALSE, 0, NULL),
(3, 146, 'وَكَأَيِّن مِّن نَّبِىٍّ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', 'وَكَأَيِّن مِّن نَّبِيٍّ قَاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا لِمَا أَصَابَهُمْ فِي سَبِيلِ اللَّهِ وَمَا ضَعُفُوا وَمَا اسْتَكَانُوا وَاللَّهُ يُحِبُّ الصَّابِرِينَ', NULL, 'And how many a prophet [fought in battle and] with him fought many religious scholars. But they never lost assurance due to what afflicted them in the cause of Allāh, nor did they weaken or submit. And Allāh loves the steadfast.', 'Dan berapa banyak dari Nabi-nabi (dahulu) telah berperang dengan disertai oleh ramai orang-orang yang taat kepada Allah, maka mereka tidak merasa lemah semangat akan apa yang telah menimpa mereka pada jalan (ugama) Allah dan mereka juga tidak lemah tenaga dan tidak pula mahu tunduk (kepada musuh). Dan (ingatlah), Allah sentiasa mengasihi orang-orang yang sabar.', FALSE, NULL, NULL, 68, 4, 27, 56, FALSE, 0, NULL),
(3, 147, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'وَمَا كَانَ قَوْلَهُمْ إِلَّا أَن قَالُوا رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', NULL, 'And their words were not but that they said, "Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people."', 'Dan tidaklah ada yang mereka ucapkan (semasa berjuang), selain daripada berdoa dengan berkata: “Wahai Tuhan kami! Ampunkanlah dosa-dosa kami dan perbuatan kami yang melampau dalam urusan kami, dan teguhkanlah tapak pendirian kami (dalam perjuangan); dan tolonglah kami mencapai kemenangan terhadap kaum yang kafir.', FALSE, NULL, NULL, 68, 4, 27, 56, FALSE, 0, NULL),
(3, 148, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'فَآتَاهُمُ اللَّهُ ثَوَابَ الدُّنْيَا وَحُسْنَ ثَوَابِ الْآخِرَةِ وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ', NULL, 'So Allāh gave them the reward of this world and the good reward of the Hereafter. And Allāh loves the doers of good.', 'Oleh itu, Allah memberikan mereka pahala dunia (kemenangan dan nama yang harum), dan pahala akhirat yang sebaik-baiknya (nikmat Syurga yang tidak ada bandingannya). Dan (ingatlah), Allah sentiasa mengasihi orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 68, 4, 27, 56, FALSE, 0, NULL),
(3, 149, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تُطِيعُوا الَّذِينَ كَفَرُوا يَرُدُّوكُمْ عَلَىٰ أَعْقَابِكُمْ فَتَنقَلِبُوا خَاسِرِينَ', NULL, 'O you who have believed, if you obey those who disbelieve, they will turn you back on your heels, and you will [then] become losers.', 'Wahai orang-orang yang beriman! Jika kamu taatkan orang-orang yang kafir nescaya mereka akan menolak kamu kembali kepada kekufuran, lalu menjadilah kamu orang-orang yang rugi.', FALSE, NULL, NULL, 69, 4, 27, 57, FALSE, 0, NULL),
(3, 150, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', 'بَلِ اللَّهُ مَوْلَاكُمْ وَهُوَ خَيْرُ النَّاصِرِينَ', NULL, 'But Allāh is your protector, and He is the best of helpers.', '(Janganlah kamu taatkan mereka!) Bahkan (taatlah kepada) Allah Pelindung kamu, dan Dia lah sebaik-baik Penolong.', FALSE, NULL, NULL, 69, 4, 27, 57, FALSE, 0, NULL),
(3, 151, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَأْوَىٰهُمُ ٱلنَّارُ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', 'سَنُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ بِمَا أَشْرَكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَمَأْوَاهُمُ النَّارُ وَبِئْسَ مَثْوَى الظَّالِمِينَ', NULL, 'We will cast terror into the hearts of those who disbelieve for what they have associated with Allāh of which He had not sent down [any] authority. And their refuge will be the Fire, and wretched is the residence of the wrongdoers.', 'Kami akan isikan hati orang-orang kafir itu dengan perasaan gerun, disebabkan mereka mempersekutukan Allah dengan benda-benda (yang mereka sembah) yang Allah tidak menurunkan sebarang keterangan yang membenarkannya. Dan (dengan yang demikian) tempat kembali mereka ialah neraka, dan itulah seburuk-buruk tempat tinggal bagi orang-orang zalim.', FALSE, NULL, NULL, 69, 4, 27, 57, FALSE, 0, NULL),
(3, 152, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ وَلَقَدْ عَفَا عَنكُمْ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', 'وَلَقَدْ صَدَقَكُمُ اللَّهُ وَعْدَهُ إِذْ تَحُسُّونَهُم بِإِذْنِهِ حَتَّىٰ إِذَا فَشِلْتُمْ وَتَنَازَعْتُمْ فِي الْأَمْرِ وَعَصَيْتُم مِّن بَعْدِ مَا أَرَاكُم مَّا تُحِبُّونَ مِنكُم مَّن يُرِيدُ الدُّنْيَا وَمِنكُم مَّن يُرِيدُ الْآخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ وَلَقَدْ عَفَا عَنكُمْ وَاللَّهُ ذُو فَضْلٍ عَلَى الْمُؤْمِنِينَ', NULL, 'And Allāh had certainly fulfilled His promise to you when you were killing them [i.e., the enemy] by His permission until [the time] when you lost courage and fell to disputing about the order [given by the Prophet (ﷺ)] and disobeyed after He had shown you that which you love. Among you are some who desire this world, and among you are some who desire the Hereafter. Then He turned you back from them [defeated] that He might test you. And He has already forgiven you, and Allāh is the possessor of bounty for the believers.', 'Dan demi sesungguhnya, Allah telah menepati janjiNya (memberikan pertolongan) kepada kamu ketika kamu (berjaya) membunuh mereka (beramai-ramai) dengan izinNya, sehingga ke masa kamu lemah (hilang semangat untuk meneruskan perjuangan) dan kamu berbalah dalam urusan (perang) itu, serta kamu pula menderhaka (melanggar perintah Rasulullah) sesudah Allah perlihatkan kepada kamu akan apa yang kamu sukai (kemenangan dan harta rampasan perang). Di antara kamu ada yang menghendaki keuntungan dunia semata-mata, dan di antara kamu ada yang menghendaki akhirat, kemudian Allah memalingkan kamu daripada menewaskan mereka untuk menguji (iman dan kesabaran) kamu; dan sesungguhnya Allah telah memaafkan kamu, (semata-mata dengan limpah kurniaNya). Dan (ingatlah), Allah sentiasa melimpahkan kurniaNya kepada orang-orang yang beriman.', FALSE, NULL, NULL, 69, 4, 27, 57, FALSE, 0, NULL),
(3, 153, 'إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'إِذْ تُصْعِدُونَ وَلَا تَلْوُونَ عَلَىٰ أَحَدٍ وَالرَّسُولُ يَدْعُوكُمْ فِي أُخْرَاكُمْ فَأَثَابَكُمْ غَمًّا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا عَلَىٰ مَا فَاتَكُمْ وَلَا مَا أَصَابَكُمْ وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ', NULL, '[Remember] when you [fled and] climbed [the mountain] without looking aside at anyone while the Messenger was calling you from behind. So Allāh repaid you with distress upon distress so you would not grieve for that which had escaped you [of victory and spoils of war] or [for] that which had befallen you [of injury and death]. And Allāh is [fully] Aware of what you do.', '(Ingatlah) ketika kamu berundur lari dan tidak menoleh kepada sesiapa pun, sedang Rasulullah (yang masih berjuang dengan gagahnya) memanggil kamu dari kumpulan yang tinggal di belakang kamu (untuk berjuang terus tetapi kamu tidak mematuhinya). Oleh sebab itu Allah membalas kamu (dengan peristiwa) yang mendukacitakan (kekalahan), dengan sebab perbuatan (kamu menderhaka) yang mendukacitakan (Rasulullah) itu, supaya kamu tidak bersedih hati akan apa yang telah luput dari kamu, dan tidak (pula bersedih) akan apa yang menimpa kamu. Dan (ingatlah), Allah Maha Mengetahui dengan mendalam akan apa jua yang kamu lakukan.', FALSE, NULL, NULL, 69, 4, 28, 57, FALSE, 0, NULL),
(3, 154, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَٰهُنَا قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ثُمَّ أَنزَلَ عَلَيْكُم مِّن بَعْدِ الْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَائِفَةً مِّنكُمْ وَطَائِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِاللَّهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِ يَقُولُونَ هَل لَّنَا مِنَ الْأَمْرِ مِن شَيْءٍ قُلْ إِنَّ الْأَمْرَ كُلَّهُ لِلَّهِ يُخْفُونَ فِي أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ الْأَمْرِ شَيْءٌ مَّا قُتِلْنَا هَاهُنَا قُل لَّوْ كُنتُمْ فِي بُيُوتِكُمْ لَبَرَزَ الَّذِينَ كُتِبَ عَلَيْهِمُ الْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِيَ اللَّهُ مَا فِي صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمْ وَاللَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, 'Then after distress, He sent down upon you security [in the form of] drowsiness, overcoming a faction of you, while another faction worried about themselves, thinking of Allāh other than the truth - the thought of ignorance, saying, "Is there anything for us [to have done] in this matter?" Say, "Indeed, the matter belongs completely to Allāh." They conceal within themselves what they will not reveal to you. They say, "If there was anything we could have done in the matter, we [i.e., some of us] would not have been killed right here." Say, "Even if you had been inside your houses, those decreed to be killed would have come out to their death beds." [It was] so that Allāh might test what is in your breasts and purify what is in your hearts. And Allāh is Knowing of that within the breasts.', 'Kemudian sesudah (kamu mengalami kejadian) yang mendukacitakan itu, Allah menurunkan kepada kamu perasaan aman tenteram, iaitu rasa mengantuk yang meliputi segolongan dari kamu (yang teguh imannya lagi ikhlas), sedang segolongan yang lain yang hanya mementingkan diri sendiri, menyangka terhadap Allah dengan sangkaan yang tidak benar, seperti sangkaan orang-orang jahiliyah. Mereka berkata: “Adakah bagi kita sesuatu bahagian dari pertolongan kemenangan yang dijanjikan itu?” Katakanlah (wahai Muhammad): “Sesungguhnya perkara (yang telah dijanjikan) itu semuanya tertentu bagi Allah, (Dia lah sahaja yang berkuasa melakukannya menurut peraturan yang ditetapkanNya)”. Mereka sembunyikan dalam hati mereka apa yang mereka tidak nyatakan kepadamu. Mereka berkata (sesama sendiri): “Kalaulah ada sedikit bahagian kita dari pertolongan yang dijanjikan itu, tentulah (orang-orang) kita tidak terbunuh di tempat ini?” katakanlah (wahai Muhammad): “Kalau kamu berada di rumah kamu sekalipun nescaya keluarlah juga orang-orang yang telah ditakdirkan (oleh Allah) akan terbunuh itu ke tempat mati masing-masing”. Dan (apa yang berlaku di medan perang Uhud itu) dijadikan oleh Allah untuk menguji apa yang ada dalam dada kamu, dan untuk membersihkan apa yang ada dalam hati kamu. Dan (ingatlah), Allah sentiasa mengetahui akan segala (isi hati) yang ada di dalam dada.', FALSE, NULL, NULL, 70, 4, 28, 57, FALSE, 0, NULL),
(3, 155, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'إِنَّ الَّذِينَ تَوَلَّوْا مِنكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُوا وَلَقَدْ عَفَا اللَّهُ عَنْهُمْ إِنَّ اللَّهَ غَفُورٌ حَلِيمٌ', NULL, 'Indeed, those of you who turned back on the day the two armies met [at Uḥud] - it was Satan who caused them to slip because of some [blame] they had earned. But Allāh has already forgiven them. Indeed, Allāh is Forgiving and Forbearing.', 'Bahawasanya orang-orang yang telah berpaling (melarikan diri) di antara kamu pada hari bertemu dua angkatan tentera (Islam dan kafir dalam perang Uhud) itu, sesungguhnya mereka telah digelincirkan oleh Syaitan dengan sebab sebahagian dari perbuatan-perbuatan (yang salah) yang mereka telah lakukan (pada masa yang lalu); dan demi sesungguhnya Allah telah memaafkan mereka, kerana sesungguhnya Allah Maha Pengampun, lagi Maha Penyabar.', FALSE, NULL, NULL, 70, 4, 28, 57, FALSE, 0, NULL),
(3, 156, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَكُونُوا كَالَّذِينَ كَفَرُوا وَقَالُوا لِإِخْوَانِهِمْ إِذَا ضَرَبُوا فِي الْأَرْضِ أَوْ كَانُوا غُزًّى لَّوْ كَانُوا عِندَنَا مَا مَاتُوا وَمَا قُتِلُوا لِيَجْعَلَ اللَّهُ ذَٰلِكَ حَسْرَةً فِي قُلُوبِهِمْ وَاللَّهُ يُحْيِي وَيُمِيتُ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'O you who have believed, do not be like those who disbelieved and said about their brothers when they traveled through the land or went out to fight, "If they had been with us, they would not have died or have been killed," so Allāh makes that [misconception] a regret within their hearts. And it is Allāh who gives life and causes death, and Allāh is Seeing of what you do.', 'Wahai orang-orang yang beriman! Janganlah kamu menjadi seperti orang-orang (munafik) yang telah kufur dan berkata kepada saudara-saudaranya apabila mereka pergi mengembara di muka bumi untuk berniaga, atau keluar berperang (lalu mati atau terbunuh): “Kalau mereka tinggal bersama-sama kita, tentulah mereka tidak mati dan tidak terbunuh”. (Apa yang mereka katakan itu tidak ada faedahnya) bahkan akibatnya Allah menjadikan (kesan perkataan dan kepercayaan mereka) yang demikian itu: penyesalan dalam hati mereka. Dan (ingatlah), Allah yang menghidupkan dan yang mematikan, dan Allah sentiasa melihat akan segala yang kamu lakukan.', FALSE, NULL, NULL, 70, 4, 28, 58, FALSE, 0, NULL),
(3, 157, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'وَلَئِن قُتِلْتُمْ فِي سَبِيلِ اللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ اللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', NULL, 'And if you are killed in the cause of Allāh or die - then forgiveness from Allāh and mercy are better than whatever they accumulate [in this world].', 'Demi sesungguhnya! Jika kamu terbunuh pada jalan Allah (dalam perang Sabil), atau kamu mati (mati biasa - semasa mengerjakan kebajikan umum), sesungguhnya keampunan dari Allah dan rahmatNya adalah lebih baik (bagi kamu) dari apa yang mereka (orang-orang kafir dan munafik) itu himpunkan (meliputi segala jenis kesenangan hidup).', FALSE, NULL, NULL, 70, 4, 28, 58, FALSE, 0, NULL),
(3, 158, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى اللَّهِ تُحْشَرُونَ', NULL, 'And whether you die or are killed, unto Allāh you will be gathered.', 'Demi sesungguhnya! jika kamu mati atau terbunuh, sudah tentu kepada Allah jualah kamu akan dihimpunkan (untuk menerima balasan).', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 159, 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 'فَبِمَا رَحْمَةٍ مِّنَ اللَّهِ لِنتَ لَهُمْ وَلَوْ كُنتَ فَظًّا غَلِيظَ الْقَلْبِ لَانفَضُّوا مِنْ حَوْلِكَ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِي الْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ إِنَّ اللَّهَ يُحِبُّ الْمُتَوَكِّلِينَ', NULL, 'So by mercy from Allāh, [O Muḥammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allāh. Indeed, Allāh loves those who rely [upon Him].', 'Maka dengan sebab rahmat (yang melimpah-limpah) dari Allah (kepadamu wahai Muhammad), engkau telah bersikap lemah-lembut kepada mereka (sahabat-sahabat dan pengikutmu), dan kalaulah engkau bersikap kasar lagi keras hati, tentulah mereka lari dari kelilingmu. Oleh itu maafkanlah mereka (mengenai kesalahan yang mereka lakukan terhadapmu), dan pohonkanlah ampun bagi mereka, dan juga bermesyuaratlah dengan mereka dalam urusan (peperangan dan hal-hal keduniaan) itu. kemudian apabila engkau telah berazam (sesudah bermesyuarat, untuk membuat sesuatu) maka bertawakalah kepada Allah, sesungguhnya Allah Mengasihi orang-orang yang bertawakal kepadaNya.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 160, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'إِن يَنصُرْكُمُ اللَّهُ فَلَا غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا الَّذِي يَنصُرُكُم مِّن بَعْدِهِ وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', NULL, 'If Allāh should aid you, no one can overcome you; but if He should forsake you, who is there that can aid you after Him? And upon Allāh let the believers rely.', 'Jika Allah menolong kamu mencapai kemenangan maka tidak ada sesiapa pun yang akan dapat mengalahkan kamu; dan jika Ia mengalahkan kamu, maka siapakah yang akan dapat menolong kamu sesudah Allah (menetapkan yang demikian)? Dan (ingatlah), kepada Allah jualah hendaknya orang-orang yang beriman itu berserah diri.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 161, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', NULL, 'It is not [attributable] to any prophet that he would act unfaithfully [in regard to war booty]. And whoever betrays, [taking unlawfully], will come with what he took on the Day of Resurrection. Then will every soul be [fully] compensated for what it earned, and they will not be wronged.', 'Dan tiadalah patut bagi seseorang Nabi itu (disangkakan) berkhianat (menggelapkan harta rampasan perang), dan sesiapa yang berkhianat (menggelapkan sesuatu), ia akan bawa bersama pada hari kiamat kelak apa yang dikhianatinya itu; kemudian tiap-tiap seorang akan disempurnakan (balasan bagi) apa yang telah diusahakannya, sedang mereka tidak akan dikurangkan sedikitpun (balasannya).', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 162, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'أَفَمَنِ اتَّبَعَ رِضْوَانَ اللَّهِ كَمَن بَاءَ بِسَخَطٍ مِّنَ اللَّهِ وَمَأْوَاهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ', NULL, 'So is one who pursues the pleasure of Allāh like one who brings upon himself the anger of Allāh and whose refuge is Hell? And wretched is the destination.', 'Adakah orang yang menurut keredaan Allah itu sama seperti orang yang kesudahannya mendapat kemurkaan dari Allah? Sedang tempat kembalinya ialah neraka Jahannam, dan itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 163, 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'هُمْ دَرَجَاتٌ عِندَ اللَّهِ وَاللَّهُ بَصِيرٌ بِمَا يَعْمَلُونَ', NULL, 'They are [varying] degrees in the sight of Allāh, and Allāh is Seeing of whatever they do.', 'Mereka itu (yang menurut keredaan Allah, dan yang mendapat kemurkaanNya), mempunyai tingkatan-tingkatan (pahala atau dosa yang berlainan) di sisi Allah; dan Allah Maha Melihat akan segala yang mereka kerjakan.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 164, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَإِن كَانُوا مِن قَبْلُ لَفِي ضَلَالٍ مُّبِينٍ', NULL, 'Certainly did Allāh confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book [i.e., the Qur’ān] and wisdom, although they had been before in manifest error.', 'Sesungguhnya Allah telah mengurniakan (rahmatNya) kepada orang-orang yang beriman, setelah Ia mengutuskan dalam kalangan mereka seorang Rasul dari bangsa mereka sendiri, yang membacakan kepada mereka ayat-ayat Allah (kandungan Al-Quran yang membuktikan keesaan Allah dan kekuasaanNya), dan membersihkan mereka (dari iktiqad yang sesat), serta mengajar mereka Kitab Allah (Al-Quran) dan Hikmah (pengetahuan yang mendalam mengenai hukum-hukum Syariat). Dan sesungguhnya mereka sebelum (kedatangan Nabi Muhammad) itu adalah dalam kesesatan yang nyata.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 165, 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'أَوَلَمَّا أَصَابَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Why [is it that] when a [single] disaster struck you [on the day of Uḥud], although you had struck [the enemy in the battle of Badr] with one twice as great, you said, "From where is this?" Say, "It is from yourselves [i.e., due to your sin]." Indeed, Allāh is over all things competent.', '(Patutkah kamu melanggar perintah Rasulullah)? dan (kemudiannya) apabila kamu ditimpa kemalangan (dalam peperangan Uhud), yang kamu telahpun memenangi seperti itu sebanyak dua kali ganda (dengan menimpakan kemalangan kepada musuh dalam peperangan Badar), kamu berkata: “Dari mana datangnya (kemalangan) ini? “Katakanlah (wahai Muhammad): “Kemalangan) itu ialah dari kesalahan diri kamu sendiri (melanggar perintah Rasulullah)”. Sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 71, 4, 28, 58, FALSE, 0, NULL),
(3, 166, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', 'وَمَا أَصَابَكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ فَبِإِذْنِ اللَّهِ وَلِيَعْلَمَ الْمُؤْمِنِينَ', NULL, 'And what struck you on the day the two armies met [at Uḥud] was by permission of Allāh that He might make evident the [true] believers', 'Dan apa yang telah menimpa kamu pada hari bertemu dua kumpulan (angkatan tentera - di medan perang Uhud) itu, maka (adalah ia) dengan izin Allah, dan dengan tujuan Allah hendak melahirkan dengan nyata akan orang-orang yang (sebenar-benarnya) beriman.', FALSE, NULL, NULL, 72, 4, 28, 58, FALSE, 0, NULL),
(3, 167, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَٰكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', 'وَلِيَعْلَمَ الَّذِينَ نَافَقُوا وَقِيلَ لَهُمْ تَعَالَوْا قَاتِلُوا فِي سَبِيلِ اللَّهِ أَوِ ادْفَعُوا قَالُوا لَوْ نَعْلَمُ قِتَالًا لَّاتَّبَعْنَاكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَانِ يَقُولُونَ بِأَفْوَاهِهِم مَّا لَيْسَ فِي قُلُوبِهِمْ وَاللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', NULL, 'And that He might make evident those who are hypocrites. For it was said to them, "Come, fight in the way of Allāh or [at least] defend." They said, "If we had known [there would be] battle, we would have followed you." They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allāh is most knowing of what they conceal -', 'Dan juga dengan tujuan Ia hendak melahirkan dengan nyata akan dikatakan kepada mereka: “Marilah berperang pada jalan Allah (untuk membela Islam), atau pertahankanlah (diri, keluarga dan harta benda kamu)”. Mereka menjawab: “Kalaulah kami faham ada peperangan (dengan sebenar-benarnya), tentulah kami mengikut kamu (turut berperang)”. Mereka ketika (mengeluarkan perkataan) itu lebih dekat kepada kufur dari dekatnya kepada iman. Mereka selalu menyebut dengan mulutnya apa yang tidak ada dalam hatinya. Dan (ingatlah), Allah Maha Mengetahui akan apa yang mereka sembunyikan.', FALSE, NULL, NULL, 72, 4, 28, 58, FALSE, 0, NULL),
(3, 168, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'الَّذِينَ قَالُوا لِإِخْوَانِهِمْ وَقَعَدُوا لَوْ أَطَاعُونَا مَا قُتِلُوا قُلْ فَادْرَءُوا عَنْ أَنفُسِكُمُ الْمَوْتَ إِن كُنتُمْ صَادِقِينَ', NULL, 'Those who said about their brothers while sitting [at home], "If they had obeyed us, they would not have been killed." Say, "Then prevent death from yourselves, if you should be truthful."', 'Merekalah juga yang mengatakan tentang hal saudara-saudaranya (yang telah terbunuh di medan perang Uhud), sedang mereka sendiri tidak turut berperang: “Kalaulah mereka taatkan kami (turut menarik diri) tentulah mereka tidak terbunuh”. Katakanlah (wahai Muhammad): “Jika demikian, hindarkanlah maut dari diri kamu, jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 72, 4, 28, 58, FALSE, 0, NULL),
(3, 169, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', NULL, 'And never think of those who have been killed in the cause of Allāh as dead. Rather, they are alive with their Lord, receiving provision,', 'Dan jangan sekali-kali engkau menyangka orang-orang yang terbunuh (yang gugur Syahid) pada jalan Allah itu mati, (mereka tidak mati) bahkan mereka adalah hidup (secara istimewa) di sisi Tuhan mereka dengan mendapat rezeki;', FALSE, NULL, NULL, 72, 4, 28, 58, FALSE, 0, NULL),
(3, 170, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'فَرِحِينَ بِمَا آتَاهُمُ اللَّهُ مِن فَضْلِهِ وَيَسْتَبْشِرُونَ بِالَّذِينَ لَمْ يَلْحَقُوا بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Rejoicing in what Allāh has bestowed upon them of His bounty, and they receive good tidings about those [to be martyred] after them who have not yet joined them - that there will be no fear concerning them, nor will they grieve.', '(Dan juga) mereka bersukacita dengan kurniaan Allah (balasan mati Syahid) yang telah dilimpahkan kepada mereka, dan mereka bergembira dengan berita baik mengenai (saudara-saudaranya) orang-orang (Islam yang sedang berjuang), yang masih tinggal di belakang, yang belum (mati dan belum) sampai kepada mereka, (iaitu) bahawa tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 72, 4, 28, 58, FALSE, 0, NULL),
(3, 171, 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ وَأَنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُؤْمِنِينَ', NULL, 'They receive good tidings of favor from Allāh and bounty and [of the fact] that Allāh does not allow the reward of believers to be lost -', 'Mereka bergembira dengan balasan nikmat dari Allah dan limpah kurniaNya; dan (ingatlah), bahawa Allah tidak menghilangkan pahala orang-orang yang beriman.', FALSE, NULL, NULL, 72, 4, 29, 58, FALSE, 0, NULL),
(3, 172, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', 'الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِن بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ لِلَّذِينَ أَحْسَنُوا مِنْهُمْ وَاتَّقَوْا أَجْرٌ عَظِيمٌ', NULL, 'Those [believers] who responded to Allāh and the Messenger after injury had struck them. For those who did good among them and feared Allāh is a great reward -', 'Iaitu orang-orang yang menjunjung perintah Allah dan RasulNya (supaya keluar menentang musuh yang menceroboh), sesudah mereka mendapat luka (tercedera di medan perang Uhud). Untuk orang-orang yang telah berbuat baik di antara mereka dan yang bertaqwa, ada balasan yang amat besar.', FALSE, NULL, NULL, 72, 4, 29, 59, FALSE, 0, NULL),
(3, 173, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 'الَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', NULL, 'Those to whom people [i.e., hypocrites] said, "Indeed, the people have gathered against you, so fear them." But it [merely] increased them in faith, and they said, "Sufficient for us is Allāh, and [He is] the best Disposer of affairs."', 'Mereka juga ialah yang diberitahu oleh orang-orang (pembawa berita) kepada mereka: “Bahawa kaum (kafir musyrik) telah mengumpulkan tentera untuk memerangi kamu, oleh itu hendaklah kamu gerun kepadanya”. Maka berita itu makin menambahkan iman mereka lalu berkata: “Cukuplah Allah untuk (menolong) kami, dan Ia sebaik-baik pengurus (yang terserah kepadaNya segala urusan kami)”.', FALSE, NULL, NULL, 72, 4, 29, 59, FALSE, 0, NULL),
(3, 174, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 'فَانقَلَبُوا بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ وَاتَّبَعُوا رِضْوَانَ اللَّهِ وَاللَّهُ ذُو فَضْلٍ عَظِيمٍ', NULL, 'So they returned with favor from Allāh and bounty, no harm having touched them. And they pursued the pleasure of Allāh, and Allāh is the possessor of great bounty.', 'Setelah (pergi mengejar musuh), mereka kembali dengan mendapat nikmat dan limpah kurnia dari Allah, mereka tidak disentuh oleh sesuatu bencana pun, serta mereka pula menurut keredaan Allah. Dan ingatlah), Allah mempunyai limpah kurnia yang amat besar.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 175, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 'إِنَّمَا ذَٰلِكُمُ الشَّيْطَانُ يُخَوِّفُ أَوْلِيَاءَهُ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'That is only Satan who frightens [you] of his supporters. So fear them not, but fear Me, if you are [indeed] believers.', 'Sesungguhnya (pembawa berita) yang demikian itu ialah syaitan yang (bertujuan) menakut-nakutkan (kamu terhadap) pengikut-pengikutnya (kaum kafir musyrik). Oleh itu, janganlah kamu takut kepada mereka, tetapi takutlah kepadaKu (jangan cuaikan perintahKu), jika betul kamu orang-orang yang beriman.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 176, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'وَلَا يَحْزُنكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ إِنَّهُمْ لَن يَضُرُّوا اللَّهَ شَيْئًا يُرِيدُ اللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِي الْآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', NULL, 'And do not be grieved, [O Muḥammad], by those who hasten into disbelief. Indeed, they will never harm Allāh at all. Allāh intends that He should give them no share in the Hereafter, and for them is a great punishment.', 'Dan janganlah engkau berdukacita (wahai Muhammad), disebabkan orang-orang yang segera menceburkan diri dalam kekufuran; kerana sesungguhnya mereka tidak sekali-kali akan dapat mendatangkan mudarat kepada Allah sedikitpun. Allah menetapkan tidak memberi kepada mereka (balasan baik syurga) pada hari akhirat kelak, dan mereka pula beroleh azab seksa yang amat besar.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 177, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّ الَّذِينَ اشْتَرَوُا الْكُفْرَ بِالْإِيمَانِ لَن يَضُرُّوا اللَّهَ شَيْئًا وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Indeed, those who purchase disbelief [in exchange] for faith - never will they harm Allāh at all, and for them is a painful punishment.', 'Sesungguhnya orang-orang yang membeli (memilih) kufur dengan meninggalkan iman tidak sekali-kali mereka akan dapat mendatangkan mudarat kepada Allah sedikitpun, dan mereka pula beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 178, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا وَلَهُمْ عَذَابٌ مُّهِينٌ', 'وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا أَنَّمَا نُمْلِي لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ إِنَّمَا نُمْلِي لَهُمْ لِيَزْدَادُوا إِثْمًا وَلَهُمْ عَذَابٌ مُّهِينٌ', NULL, 'And let not those who disbelieve ever think that [because] We extend their time [of enjoyment] it is better for them. We only extend it for them so that they may increase in sin, and for them is a humiliating punishment.', 'Dan jangan sekali-kali orang-orang kafir menyangka bahawa Kami membiarkan (mereka hidup lama) itu baik bagi diri mereka; kerana sesungguhnya Kami biarkan mereka hanyalah supaya mereka bertambah dosa (di dunia), dan mereka pula beroleh azab seksa yang menghina (di akhirat kelak).', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 179, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ', 'مَّا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ وَمَا كَانَ اللَّهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ وَلَٰكِنَّ اللَّهَ يَجْتَبِي مِن رُّسُلِهِ مَن يَشَاءُ فَآمِنُوا بِاللَّهِ وَرُسُلِهِ وَإِن تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ أَجْرٌ عَظِيمٌ', NULL, 'Allāh would not leave the believers in that [state] you are in [presently] until He separates the evil from the good. Nor would Allāh reveal to you the unseen. But [instead], Allāh chooses of His messengers whom He wills, so believe in Allāh and His messengers. And if you believe and fear Him, then for you is a great reward.', 'Allah tidak sekali-kali akan membiarkan orang-orang yang beriman dalam keadaan yang kamu ada seorang (bercampur aduk mukmin dan munafik, bahkan Ia tetap menguji kamu) sehingga Ia memisahkan yang buruk (munafik) daripada yang baik (beriman). Dan Allah tidak sekali-kali akan memperlihatkan kepada kamu perkara-perkara yang Ghaib akan tetapi Allah memilih dari RasulNya sesiapa yang dikehendakiNya (untuk memperlihatkan kepadanya perkara-perkara yang Ghaib). Oleh itu berimanlah kamu kepada Allah dan Rasul-rasulNya; dan kamu beriman dan bertaqwa, maka kamu akan beroleh pahala yang besar.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 180, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم بَلْ هُوَ شَرٌّ لَّهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللَّهُ مِن فَضْلِهِ هُوَ خَيْرًا لَّهُم بَلْ هُوَ شَرٌّ لَّهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا بِهِ يَوْمَ الْقِيَامَةِ وَلِلَّهِ مِيرَاثُ السَّمَاوَاتِ وَالْأَرْضِ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', NULL, 'And let not those who [greedily] withhold what Allāh has given them of His bounty ever think that it is better for them. Rather, it is worse for them. Their necks will be encircled by what they withheld on the Day of Resurrection. And to Allāh belongs the heritage of the heavens and the earth. And Allāh, of what you do, is [fully] Aware.', 'Dan jangan sekali-kali orang-orang yang bakhil dengan harta benda yang telah dikurniakan Allah kepada mereka dari kemurahanNya - menyangka bahawa keadaan bakhilnya itu baik bagi mereka. Bahkan ia adalah buruk bagi mereka. Mereka akan dikalongkan (diseksa) dengan apa yang mereka bakhilkan itu pada hari kiamat kelak. Dan bagi Allah jualah hak milik segala warisan (isi) langit dan bumi. Dan (ingatlah), Allah Maha Mengetahui dengan mendalam akan segala yang kamu kerjakan.', FALSE, NULL, NULL, 73, 4, 29, 59, FALSE, 0, NULL),
(3, 181, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'لَّقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ سَنَكْتُبُ مَا قَالُوا وَقَتْلَهُمُ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا عَذَابَ الْحَرِيقِ', NULL, 'Allāh has certainly heard the statement of those [Jews] who said, "Indeed, Allāh is poor, while we are rich." We will record what they said and their killing of the prophets without right and will say, "Taste the punishment of the Burning Fire.', 'Sesungguhnya Allah telah mendengar perkataan orang-orang (Yahudi) yang mengatakan: Bahawasanya Allah miskin dan kami ialah orang-orang kaya. Kami (Allah) akan menuliskan perkataan mereka itu dan perbuatan mereka membunuh Nabi-nabi dengan tidak ada alasan yang membenarkannya, dan Kami akan katakan kepada mereka: “Rasalah kamu azab seksa yang sentiasa membakar -', FALSE, NULL, NULL, 74, 4, 29, 60, FALSE, 0, NULL),
(3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', NULL, 'That is for what your hands have put forth and because Allāh is not ever unjust to [His] servants."', '(Azab seksa) yang demikian itu ialah disebabkan perbuatan yang - telah dilakukan oleh tangan kamu sendiri. Dan (ingatlah), sesungguhnya Allah tidak sekali-kali berlaku zalim kepada hamba-hambanya.”', FALSE, NULL, NULL, 74, 4, 29, 60, FALSE, 0, NULL),
(3, 183, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', 'الَّذِينَ قَالُوا إِنَّ اللَّهَ عَهِدَ إِلَيْنَا أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ النَّارُ قُلْ قَدْ جَاءَكُمْ رُسُلٌ مِّن قَبْلِي بِالْبَيِّنَاتِ وَبِالَّذِي قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَادِقِينَ', NULL, '[They are] those who said, "Indeed, Allāh has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume." Say, "There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?"', 'Orang-orang (Yahudi itulah) yang berkata: “Sebenarnya Allah telah perintahkan kami, supaya kami jangan beriman kepada seseorang Rasul sehingga ia membawa kepada kami korban yang dimakan api. “Katakanlah (wahai Muhammad): “Sesungguhnya telah datang kepada kamu beberapa Rasul dahulu daripadaku dengan membawa keterangan-keterangan (mukjizat) yang nyata dan dengan (korban) yang kamu membunuh mereka, jika kamu orang-orang yang benar (dalam yang kamu dakwakan itu)?', FALSE, NULL, NULL, 74, 4, 29, 60, FALSE, 0, NULL),
(3, 184, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَاءُوا بِالْبَيِّنَاتِ وَالزُّبُرِ وَالْكِتَابِ الْمُنِيرِ', NULL, 'Then if they deny you, [O Muḥammad] - so were messengers denied before you, who brought clear proofs and written ordinances and the enlightening Scripture.', 'Oleh itu, jika mereka mendustakanmu (wahai Muhammad, maka janganlah engkau berdukacita), kerana sesungguhnya Rasul-rasul yang terdahulu daripadamu telah didustakan juga; mereka telah membawa keterangan-keterangan (mukjizat) yang nyata dan Kitab-kitab (nasihat pengajaran), serta Kitab (Syariat) yang terang jelas.', FALSE, NULL, NULL, 74, 4, 29, 60, FALSE, 0, NULL),
(3, 185, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيَامَةِ فَمَن زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ الْغُرُورِ', NULL, 'Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion.', 'Tiap-tiap yang bernyawa akan merasai mati, dan bahawasanya pada hari kiamat sahajalah akan disempurnakan balasan kamu. Ketika itu sesiapa yang dijauhkan dari neraka dan dimasukkan ke syurga maka sesungguhnya ia telah berjaya. Dan (ingatlah bahawa) kehidupan di dunia ini (meliputi segala kemewahannya dan pangkat kebesarannya) tidak lain hanyalah kesenangan bagi orang-orang yang terpedaya.', FALSE, NULL, NULL, 74, 4, 29, 60, FALSE, 0, NULL),
(3, 186, 'لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'لَتُبْلَوُنَّ فِي أَمْوَالِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذًى كَثِيرًا وَإِن تَصْبِرُوا وَتَتَّقُوا فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ', NULL, 'You will surely be tested in your possessions and in yourselves. And you will surely hear from those who were given the Scripture before you and from those who associate others with Allāh much abuse. But if you are patient and fear Allāh - indeed, that is of the matters [worthy] of resolve.', 'Demi sesungguhnya, kamu akan diuji pada harta benda dan diri kamu. Dan demi sesungguhnya, kamu akan mendengar dari orang-orang yang telah diberikan Kitab dahulu daripada kamu dan orang-orang yang musyrik: banyak (tuduhan-tuduhan dan cacian) yang menyakitkan hati. Dalam pada itu, jika kamu bersabar dan bertaqwa maka sesungguhnya yang demikian itu adalah dari perkara-perkara yang dikehendaki diambil berat (melakukannya).', FALSE, NULL, NULL, 74, 4, 30, 60, FALSE, 0, NULL),
(3, 187, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ', 'وَإِذْ أَخَذَ اللَّهُ مِيثَاقَ الَّذِينَ أُوتُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُ فَنَبَذُوهُ وَرَاءَ ظُهُورِهِمْ وَاشْتَرَوْا بِهِ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ', NULL, 'And [mention, O Muḥammad], when Allāh took a covenant from those who were given the Scripture, [saying], "You must make it clear [i.e., explain it] to the people and not conceal it." But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased.', 'Dan (ingatlah) ketika Allah mengambil perjanjian setia dari orang-orang yang telah diberikan Kitab (iaitu): “Demi sesungguhnya! Hendaklah kamu menerangkan isi Kitab itu kepada umat manusia, dan jangan sekali-kali kamu menyembunyikannya”. Kemudian mereka membuang (perjanjian setia) itu ke belakang mereka, serta mereka menukarnya dengan mengambil faedah dunia yang sedikit. Maka amatlah buruknya apa yang mereka dapati dari penukaran (Kalamullah dan janjiNya) itu.', FALSE, NULL, NULL, 75, 4, 30, 60, FALSE, 0, NULL),
(3, 188, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوا وَّيُحِبُّونَ أَن يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ الْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'And never think that those who rejoice in what they have perpetrated and like to be praised for what they did not do - never think them [to be] in safety from the punishment, and for them is a painful punishment.', 'Jangan sekali-kali engkau menyangka (wahai Muhammad, bahawa) orang-orang yang bergembira dengan apa yang mereka telah lakukan, dan mereka pula suka dipuji dengan apa yang mereka tidak lakukan - jangan sekali-kali engkau menyangka mereka akan terselamat dari seksa, dan mereka pula akan beroleh azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 75, 4, 30, 60, FALSE, 0, NULL),
(3, 189, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'And to Allāh belongs the dominion of the heavens and the earth, and Allāh is over all things competent.', 'Dan bagi Allah jualah kuasa pemerintah langit dan bumi, dan Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 75, 4, 30, 60, FALSE, 0, NULL),
(3, 190, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ', 'إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ', NULL, 'Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding -', 'Sesungguhnya pada kejadian langit dan bumi, dan pada pertukaran malam dan siang, ada tanda-tanda (kekuasaan, kebijaksanaan, dan keluasan rahmat Allah) bagi orang-orang yang berakal;', FALSE, NULL, NULL, 75, 4, 30, 61, FALSE, 0, NULL),
(3, 191, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ', NULL, 'Who remember Allāh while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], "Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire.', '(Iaitu) orang-orang yang menyebut dan mengingati Allah semasa mereka berdiri dan duduk dan semasa mereka berbaring mengiring, dan mereka pula memikirkan tentang kejadian langit dan bumi (sambil berkata): “Wahai Tuhan kami! Tidaklah Engkau menjadikan benda-benda ini dengan sia-sia, Maha Suci Engkau, maka peliharalah kami dari azab neraka.', FALSE, NULL, NULL, 75, 4, 30, 61, FALSE, 0, NULL),
(3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ', NULL, 'Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.', 'Wahai Tuhan kami! Sebenarnya sesiapa yang Engkau masukkan ke dalam neraka maka sesungguhnya Engkau telah menghinakannya, dan orang-orang yang zalim tidak akan beroleh seorang penolong pun;', FALSE, NULL, NULL, 75, 4, 30, 61, FALSE, 0, NULL),
(3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', 'رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ', NULL, 'Our Lord, indeed we have heard a caller [i.e., Prophet Muḥammad (ﷺ)] calling to faith, [saying], ''Believe in your Lord,'' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die among the righteous.', 'Wahai Tuhan kami! Sesungguhnya kami telah mendengar seorang Penyeru (Rasul) yang menyeru kepada iman, katanya: ‘Berimanlah kamu kepada Tuhan kamu’, maka kami pun beriman. Wahai Tuhan kami, ampunkanlah dosa-dosa kami, dan hapuskanlah daripada kami kesalahan-kesalahan kami, dan matikanlah kami bersama orang-orang yang berbakti;', FALSE, NULL, NULL, 75, 4, 30, 61, FALSE, 0, NULL),
(3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', 'رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ', NULL, 'Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise."', 'Wahai Tuhan kami! Berikanlah kepada kami pahala yang telah Engkau janjikan kepada kami melalui Rasul-rasulMu, dan janganlah Engkau hinakan kami pada hari kiamat; sesungguhnya Engkau tidak memungkiri janji”.', FALSE, NULL, NULL, 75, 4, 30, 61, FALSE, 0, NULL),
(3, 195, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 'فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّهِ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ', NULL, 'And their Lord responded to them, "Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allāh, and Allāh has with Him the best reward."', 'Maka Tuhan mereka perkenankan doa mereka (dengan firmanNya): “Sesungguhnya Aku tidak akan sia-siakan amal orang-orang yang beramal dari kalangan kamu, sama ada lelaki atau perempuan, (kerana) setengah kamu (adalah keturunan) dari setengahnya yang lain; maka orang-orang yang berhijrah (kerana menyelamatkan ugamanya), dan yang diusir ke luar dari tempat tinggalnya, dan juga yang disakiti (dengan berbagai-bagai gangguan) kerana menjalankan ugamaKu, dan yang berperang (untuk mempertahankan Islam), dan yang terbunuh (gugur Syahid dalam perang Sabil) - sesungguhnya Aku akan hapuskan kesalahan-kesalahan mereka, dan sesungguhnya Aku akan masukkan mereka ke dalam Syurga yang mengalir di bawahnya beberapa sungai, sebagai pahala dari sisi Allah. Dan di sisi Allah jualah pahala yang sebaik-baiknya (bagi mereka yang beramal soleh)”.', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 'لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ', NULL, 'Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.', 'Jangan sekali-kali engkau (wahai Muhammad) terpedaya oleh usaha gerakan orang-orang yang kafir di dalam negeri (yang membawa keuntungan-keuntungan kepada mereka).', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(3, 197, 'مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', 'مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ', NULL, '[It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place.', '(Semuanya) itu hanyalah kesenangan yang sedikit, (akhirnya akan lenyap), kemudian tempat kembali mereka neraka Jahannam: dan itulah seburuk-buruk tempat ketetapan.', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(3, 198, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ', 'لَٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ اللَّهِ وَمَا عِندَ اللَّهِ خَيْرٌ لِّلْأَبْرَارِ', NULL, 'But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allāh. And that which is with Allāh is best for the righteous.', 'Tetapi orang-orang yang bertaqwa kepada Tuhan mereka, mereka beroleh Syurga-syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya, sebagai tempat sambutan tetamu (yang meriah dengan nikmat pemberian) dari Allah. Dan (ingatlah) apa jua yang ada di sisi Allah adalah lebih bagi orang-orang yang berbakti (yang taat, yang banyak berbuat kebajikan).', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(3, 199, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَنًا قَلِيلًا أُولَٰئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ', NULL, 'And indeed, among the People of the Scripture are those who believe in Allāh and what was revealed to you and what was revealed to them, [being] humbly submissive to Allāh. They do not exchange the verses of Allāh for a small price. Those will have their reward with their Lord. Indeed, Allāh is swift in account.', 'Dan sesungguhnya di antara Ahli Kitab, ada orang yang beriman kepada Allah dan (kepada) apa yang diturunkan kepada kamu (Al-Quran) dan juga (kepada) apa yang diturunkan kepada mereka, sedang mereka khusyuk kepada Allah dengan tidak menukarkan ayat-ayat Allah untuk mengambil keuntungan dunia yang sedikit. Mereka itu beroleh pahalanya di sisi Tuhan mereka. Sesungguhnya Allah Amat segera hitungan hisabNya.', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(3, 200, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, persevere and endure and remain stationed and fear Allāh that you may be successful.', 'Wahai orang-orang yang beriman! Bersabarlah kamu (menghadapi segala kesukaran dalam mengerjakan perkara-perkara yang berkebajikan), dan kuatkanlah kesabaran kamu lebih daripada kesabaran musuh, di medan perjuangan), dan bersedialah (dengan kekuatan pertahanan di daerah-daerah sempadan) serta bertaqwalah kamu kepada Allah supaya, kamu berjaya (mencapai kemenangan).', FALSE, NULL, NULL, 76, 4, 30, 61, FALSE, 0, NULL),
(4, 1, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا', 'يا ايها الناس اتقوا ربكم الذي خلقكم من نفس واحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا', NULL, 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allāh, through whom you ask one another, and the wombs. Indeed Allāh is ever, over you, an Observer.', 'Wahai sekalian manusia! Bertaqwalah kepada Tuhan kamu yang telah menjadikan kamu (bermula) dari diri yang satu (Adam), dan yang menjadikan daripada (Adam) itu pasangannya (isterinya - Hawa), dan juga yang membiakkan dari keduanya - zuriat keturunan - lelaki dan perempuan yang ramai. Dan bertaqwalah kepada Allah yang kamu selalu meminta dengan menyebut-yebut namaNya, serta peliharalah hubungan (silaturrahim) kaum kerabat; kerana sesungguhnya Allah sentiasa memerhati (mengawas) kamu.', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 28, NULL),
(4, 2, 'وَءَاتُوا۟ ٱلْيَتَـٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا', 'واتوا اليتامى اموالهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا اموالهم الى اموالكم انه كان حوبا كبيرا', NULL, 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.', 'Dan berikanlah kepada anak-anak yatim (yang telah baligh) itu harta mereka, dan janganlah kamu tukar-gantikan yang baik dengan yang buruk; dan janganlah kamu makan harta mereka (dengan menghimpunkannya) dengan harta kamu; kerana sesungguhnya (yang demikian) itu adalah dosa yang besar.', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 16, NULL),
(4, 3, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَـٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَـٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', 'وان خفتم الا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فان خفتم الا تعدلوا فواحدة او ما ملكت ايمانكم ذلك ادنى الا تعولوا', NULL, 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hands possess [i.e., slaves]. That is more suitable that you may not incline [to injustice].', 'Dan jika kamu takut tidak berlaku adil terhadap perempuan-perempuan yatim (apabila kamu berkahwin dengan mereka), maka berkahwinlah dengan sesiapa yang kamu berkenan dari perempuan-perempuan (lain): dua, tiga atau empat. Kemudian jika kamu bimbang tidak akan berlaku adil (di antara isteri-isteri kamu) maka (berkahwinlah dengan) seorang sahaja, atau (pakailah) hamba-hamba perempuan yang kamu miliki. Yang demikian itu adalah lebih dekat (untuk mencegah) supaya kamu tidak melakukan kezaliman.', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 28, NULL),
(4, 4, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَـٰتِهِنَّ نِحْلَةً ۚ فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا', 'واتوا النساء صدقاتهن نحلة فان طبن لكم عن شيء منه نفسا فكلوه هنيئا مريئا', NULL, 'And give the women [upon marriage] their [bridal] gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.', 'Dan berikanlah kepada perempuan-perempuan itu maskahwin-maskahwin mereka sebagai pemberian yang wajib. Kemudian jika mereka dengan suka hatinya memberikan kepada kamu sebahagian dari maskahwinnya maka makanlah (gunakanlah) pemberian (yang halal) itu sebagai nikmat yang lazat, lagi baik kesudahannya.', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 14, NULL),
(4, 5, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَـٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'ولا تؤتوا السفهاء اموالكم التي جعل الله لكم قياما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا', NULL, 'And do not give the weak-minded your property, which Allāh has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.', 'Dan janganlah kamu berikan (serahkan) kepada orang-orang yang belum sempurna akalnya akan harta (mereka yang ada dalam jagaan) kamu, (harta) yang Allah telah menjadikannya untuk kamu semua sebagai asas pembangunan kehidupan kamu; dan berilah mereka belanja dan pakaian dari pendapatan hartanya (yang kamu niagakan), dan juga berkatalah kepada mereka dengan kata-kata yang baik.', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 16, NULL),
(4, 6, 'وَٱبْتَلُوا۟ ٱلْيَتَـٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ ۖ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ ۚ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ ۖ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ ۚ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'وابتلوا اليتامى حتى اذا بلغوا النكاح فان انستم منهم رشدا فادفعوا اليهم اموالهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم اموالهم فاشهدوا عليهم وكفى بالله حسيبا', NULL, 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain [from taking a fee]; and whoever is poor - let him take according to what is acceptable. Then when you release their property to them, bring witnesses upon them. And sufficient is Allāh as Accountant.', 'Dan ujilah anak-anak yatim itu (sebelum baligh) sehingga mereka cukup umur (dewasa). Kemudian jika kamu nampak dari keadaan mereka (tanda-tanda yang menunjukkan bahawa mereka) telah cerdik dan berkebolehan menjaga hartanya, maka serahkanlah kepada mereka hartanya; dan janganlah kamu makan harta anak-anak yatim itu secara yang melampaui batas dan secara terburu-buru (merebut peluang) sebelum mereka dewasa. Dan sesiapa (di antara penjaga harta anak-anak yatim itu) yang kaya maka hendaklah ia menahan diri (dari memakannya); dan sesiapa yang miskin maka bolehlah ia memakannya dengan cara yang sepatutnya. Kemudian apabila kamu menyerahkan kepada mereka hartanya, maka hendaklah kamu adakan saksi-saksi (yang menyaksikan penerimaan) mereka. Dan cukuplah Allah sebagai Pengawas (akan segala yang kamu lakukan).', FALSE, NULL, NULL, 77, 4, 31, 62, FALSE, 37, NULL),
(4, 7, 'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ ۚ نَصِيبًا مَّفْرُوضًا', 'للرجال نصيب مما ترك الوالدان والاقربون وللنساء نصيب مما ترك الوالدان والاقربون مما قل منه او كثر نصيبا مفروضا', NULL, 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.', 'Orang-orang lelaki ada bahagian pusaka dari peninggalan ibu bapa dan kerabat, dan orang-orang perempuan pula ada bahagian pusaka dari peninggalan ibu bapa dan kerabat, sama ada sedikit atau banyak dari harta yang ditinggalkan itu; iaitu bahagian yang telah diwajibkan (dan ditentukan oleh Allah).', FALSE, NULL, NULL, 78, 4, 31, 62, FALSE, 19, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(4, 8, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'واذا حضر القسمة اولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا', NULL, 'And when [other] relatives and orphans and the needy are present at the [time of] division, then provide for them [something] out of it [i.e., the estate] and speak to them words of appropriate kindness.', 'Dan apabila kerabat (yang tidak berhak mendapat pusaka), dan anak-anak yatim serta orang-orang miskin hadir ketika pembahagian (harta pusaka) itu, maka berikanlah kepada mereka sedikit daripadanya, dan berkatalah kepada mereka dengan kata-kata yang baik.', FALSE, NULL, NULL, 78, 4, 31, 62, FALSE, 13, NULL),
(4, 9, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَـٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا', 'وليخش الذين لو تركوا من خلفهم ذرية ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا', NULL, 'And let those [executors and guardians] fear [injustice] as if they [themselves] had left weak offspring behind and feared for them. So let them fear Allāh and speak words of appropriate justice.', 'Dan hendaklah takut (kepada Allah daripada melakukan aniaya kepada anak-anak yatim oleh) orang-orang (yang menjadi penjaganya), yang jika ditakdirkan mereka pula meninggalkan anak-anak yang daif (yatim) di belakang mereka, (tentulah) mereka akan merasa bimbang terhadap (masa depan dan keselamatan) anak-anak mereka; oleh itu hendaklah mereka bertaqwa kepada Allah, dan hendaklah mereka mengatakan perkataan yang betul (menepati kebenaran).', FALSE, NULL, NULL, 78, 4, 31, 62, FALSE, 15, NULL),
(4, 10, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَـٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا ۖ وَسَيَصْلَوْنَ سَعِيرًا', 'ان الذين ياكلون اموال اليتامى ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا', NULL, 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze [i.e., Hellfire].', 'Sesungguhnya orang-orang yang memakan harta anak-anak yatim secara zalim, sebenarnya mereka itu hanyalah menelan api ke dalam perut mereka; dan mereka pula akan masuk ke dalam api neraka yang menyala-nyala.', FALSE, NULL, NULL, 78, 4, 31, 62, FALSE, 13, NULL),
(4, 11, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَـٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحدة فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوة فلامه السدس من بعد وصية يوصي بها او دين اباؤكم وابناؤكم لا تدرون ايهم اقرب لكم نفعا فريضة من الله ان الله كان عليما حكيما', NULL, 'Allāh instructs you concerning your children [i.e., their portions of inheritance]: for the male, what is equal to the share of two females. But if there are [only] daughters, two or more, for them is two thirds of one''s estate. And if there is only one, for her is half. And for one''s parents, to each one of them is a sixth of his estate if he left children. But if he had no children and the parents [alone] inherit from him, then for his mother is one third. And if he had brothers [and/or sisters], for his mother is a sixth, after any bequest he [may have] made or debt. Your parents or your children - you know not which of them are nearest to you in benefit. [These shares are] an obligation [imposed] by Allāh. Indeed, Allāh is ever Knowing and Wise.', 'Allah perintahkan kamu mengenai (pembahagian harta pusaka untuk) anak-anak kamu, iaitu bahagian seorang anak lelaki menyamai bahagian dua orang anak perempuan. Tetapi jika anak-anak perempuan itu lebih dari dua, maka bahagian mereka ialah dua pertiga dari harta yang ditinggalkan oleh si mati. Dan jika anak perempuan itu seorang sahaja, maka bahagiannya ialah satu perdua (separuh) harta itu. Dan bagi ibu bapa (si mati), tiap-tiap seorang dari keduanya: satu perenam dari harta yang ditinggalkan oleh si mati, jika si mati itu mempunyai anak. Tetapi jika si mati tidak mempunyai anak, sedang yang mewarisinya hanyalah kedua ibu bapanya, maka bahagian ibunya ialah satu pertiga. Kalau pula si mati itu mempunyai beberapa orang saudara (adik-beradik), maka bahagian ibunya ialah satu perenam. (Pembahagian itu) ialah sesudah diselesaikan wasiat yang telah diwasiatkan oleh si mati, dan sesudah dibayarkan hutangnya. lbu-bapa kamu dan anak-anak kamu, kamu tidak mengetahui siapa di antaranya yang lebih dekat serta banyak manfaatnya kepada kamu (Pembahagian harta pusaka dan penentuan bahagian masing-masing seperti yang diterangkan itu ialah) ketetapan dari Allah; sesungguhnya Allah adalah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 78, 4, 31, 63, FALSE, 71, NULL),
(4, 12, '۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ ۚ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ ۗ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَـٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ ۚ وَصِيَّةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌ', 'ولكم نصف ما ترك ازواجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها او دين وان كان رجل يورث كلالة او امراة وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصية يوصى بها او دين غير مضار وصية من الله والله عليم حليم', NULL, 'And for you is half of what your wives leave if they have no child. But if they have a child, for you is one fourth of what they leave, after any bequest they [may have] made or debt. And for them [i.e., the wives] is one fourth if you leave no child. But if you leave a child, then for them is an eighth of what you leave, after any bequest you [may have] made or debt. And if a man or woman leaves neither ascendants nor descendants but has a brother or a sister, then for each one of them is a sixth. But if they are more than two, they share a third, after any bequest which was made or debt, as long as there is no detriment [caused]. [This is] an ordinance from Allāh, and Allāh is Knowing and Forbearing.', 'Dan bagi kamu satu perdua dari harta yang ditinggalkan oleh isteri-isteri kamu jika mereka tidak mempunyai anak. Tetapi jika mereka mempunyai anak maka kamu beroleh satu perempat dari harta yang mereka tinggalkan, sesudah ditunaikan wasiat yang mereka wasiatkan dan sesudah dibayarkan hutangnya. Dan bagi mereka (isteri-isteri) pula satu perempat dari harta yang kamu tinggalkan, jika kamu tidak mempunyai anak. Tetapi kalau kamu mempunyai anak maka bahagian mereka (isteri-isteri kamu) ialah satu perlapan dari harta yang kamu tinggalkan, sesudah ditunaikan wasiat yang kamu wasiatkan, dan sesudah dibayarkan hutang kamu. Dan jika si mati yang diwarisi itu, lelaki atau perempuan, yang tidak meninggalkan anak atau bapa, dan ada meninggalkan seorang saudara lelaki (seibu) atau saudara perempuan (seibu) maka bagi tiap-tiap seorang dari keduanya ialah satu perenam. Kalau pula mereka (saudara-saudara yang seibu itu) lebih dari seorang, maka mereka bersekutu pada satu pertiga (dengan mendapat sama banyak lelaki dengan perempuan), sesudah ditunaikan wasiat yang diwasiatkan oleh si mati, dan sesudah dibayarkan hutangnya; wasiat-wasiat yang tersebut hendaknya tidak mendatangkan mudarat (kepada waris-waris). (Tiap-tiap satu hukum itu) ialah ketetapan dari Allah. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Penyabar.', FALSE, NULL, NULL, 79, 4, 32, 63, FALSE, 88, NULL),
(4, 13, 'تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'تلك حدود الله ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار خالدين فيها وذلك الفوز العظيم', NULL, 'These are the limits [set by] Allāh, and whoever obeys Allāh and His Messenger will be admitted by Him to gardens [in Paradise] under which rivers flow, abiding eternally therein; and that is the great attainment.', 'Segala hukum yang tersebut adalah batas-batas (Syariat) Allah. Dan sesiapa yang taat kepada Allah dan RasulNya, akan dimasukkan oleh Allah ke dalam Syurga yang mengalir dari bawahnya beberapa sungai, mereka kekal di dalamnya; dan itulah kejayaan yang amat besar.', FALSE, NULL, NULL, 79, 4, 32, 63, FALSE, 18, NULL),
(4, 14, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَـٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ', 'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها وله عذاب مهين', NULL, 'And whoever disobeys Allāh and His Messenger and transgresses His limits - He will put him into the Fire to abide eternally therein, and he will have a humiliating punishment.', 'Dan sesiapa yang derhaka kepada Allah dan RasulNya, dan melampaui batas-batas SyariatNya, akan dimasukkan oleh Allah ke dalam api neraka, kekalah dia di dalamnya, dan baginya azab seksa yang amat menghina.', FALSE, NULL, NULL, 79, 4, 32, 63, FALSE, 13, NULL),
(4, 15, 'وَٱلَّـٰتِى يَأْتِينَ ٱلْفَـٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ ۖ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا', 'واللاتي ياتين الفاحشة من نسائكم فاستشهدوا عليهن اربعة منكم فان شهدوا فامسكوهن في البيوت حتى يتوفاهن الموت او يجعل الله لهن سبيلا', NULL, 'Those who commit immorality [i.e., unlawful sexual intercourse] of your women - bring against them four [witnesses] from among you. And if they testify, confine them [i.e., the guilty women] to houses until death takes them or Allāh ordains for them [another] way.', 'Dan sesiapa yang melakukan perbuatan keji (zina) di antara perempuan-perempuan kamu, maka carilah empat orang lelaki di antara kamu yang menjadi saksi terhadap perbuatan mereka. Kemudian kalau keterangan-keterangan saksi itu mengesahkan perbuatan tersebut, maka kurunglah mereka (perempuan yang berzina itu) dalam rumah hingga mereka sampai ajal matinya, atau hingga Allah mengadakan untuk mereka jalan keluar (dari hukuman itu).', FALSE, NULL, NULL, 80, 4, 32, 64, FALSE, 22, NULL),
(4, 16, 'وَٱلَّذَانِ يَأْتِيَـٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا ۖ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا', 'واللذان ياتيانها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما', NULL, 'And the two who commit it [i.e., unlawful sexual intercourse] among you - punish [i.e., dishonor] them both. But if they repent and correct themselves, leave them alone. Indeed, Allāh is ever Accepting of Repentance and Merciful.', 'Dan (mana-mana) dua orang di antara kamu yang melakukan perbuatan yang keji itu, (setelah sabit kesalahannya) maka hendaklah kamu menyakiti keduanya; kemudian jika mereka bertaubat dan memperbaiki keadaan diri mereka (yang buruk itu), maka biarkanlah mereka; kerana sesungguhnya Allah adalah sentiasa Menerima taubat, lagi Maha Luas rahmatNya.', FALSE, NULL, NULL, 80, 4, 32, 64, FALSE, 14, NULL),
(4, 17, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَـٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'انما التوبة على الله للذين يعملون السوء بجهالة ثم يتوبون من قريب فاولئك يتوب الله عليهم وكان الله عليما حكيما', NULL, 'The repentance accepted by Allāh is only for those who do wrong in ignorance [or carelessness] and then repent soon [after]. It is those to whom Allāh will turn in forgiveness, and Allāh is ever Knowing and Wise.', 'Sesungguhnya penerimaan taubat itu disanggup oleh Allah hanya bagi orang-orang yang melakukan kejahatan disebabkan (sifat) kejahilan kemudian mereka segera bertaubat, maka (dengan adanya dua sebab itu) mereka diterima Allah taubatnya; dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 80, 4, 32, 64, FALSE, 20, NULL),
(4, 18, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٔـٰنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَـٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', 'وليست التوبة للذين يعملون السيئات حتى اذا حضر احدهم الموت قال اني تبت الان ولا الذين يموتون وهم كفار اولئك اعتدنا لهم عذابا اليما', NULL, 'But repentance is not [accepted] of those who [continue to] do evil deeds up until, when death comes to one of them, he says, "Indeed, I have repented now," or of those who die while they are disbelievers. For them We have prepared a painful punishment.', 'Dan tidak ada gunanya taubat itu kepada orang-orang yang selalu melakukan kejahatan, hingga apabila salah seorang dari mereka hampir mati, berkatalah ia: “Sesungguhnya aku bertaubat sekarang ini,” (sedang taubatnya itu sudah terlambat), dan (demikian juga halnya) orang-orang yang mati sedang mereka tetap kafir. Orang-orang yang demikian, Kami telah sediakan bagi mereka azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 80, 4, 32, 64, FALSE, 24, NULL),
(4, 19, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا ۖ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ ۚ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا', 'يا ايها الذين امنوا لا يحل لكم ان ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما اتيتموهن الا ان ياتين بفاحشة مبينة وعاشروهن بالمعروف فان كرهتموهن فعسى ان تكرهوا شيئا ويجعل الله فيه خيرا كثيرا', NULL, 'O you who have believed, it is not lawful for you to inherit women by compulsion. And do not make difficulties for them in order to take [back] part of what you gave them unless they commit a clear immorality [i.e., adultery]. And live with them in kindness. For if you dislike them - perhaps you dislike a thing and Allāh makes therein much good.', 'Wahai orang-orang yang beriman, tidak halal bagi kamu mewarisi perempuan-perempuan dengan jalan paksaan, dan janganlah kamu menyakiti mereka (dengan menahan dan menyusahkan mereka) kerana kamu hendak mengambil balik sebahagian dari apa yang kamu telah berikan kepadanya, kecuali (apabila) mereka melakukan perbuatan keji yang nyata. Dan bergaulah kamu dengan mereka (isteri-isteri kamu itu) dengan cara yang baik. Kemudian jika kamu (merasai) benci kepada mereka (disebabkan tingkah-lakunya, janganlah kamu terburu-buru menceraikannya), kerana boleh jadi kamu bencikan sesuatu, sedang Allah hendak menjadikan pada apa yang kamu benci itu kebaikan yang banyak (untuk kamu).', FALSE, NULL, NULL, 80, 4, 32, 64, FALSE, 34, NULL),
(4, 20, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا ۚ أَتَأْخُذُونَهُۥ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا', 'وان اردتم استبدال زوج مكان زوج واتيتم احداهن قنطارا فلا تاخذوا منه شيئا اتاخذونه بهتانا واثما مبينا', NULL, 'But if you want to replace one wife with another and you have given one of them a great amount [in gifts], do not take [back] from it anything. Would you take it in injustice and manifest sin?', 'Dan jika kamu hendak mengambil isteri (baharu) menggantikan isteri (lama yang kamu ceraikan) sedang kamu telahpun memberikan kepada seseorang di antaranya (isteri yang diceraikan itu) harta yang banyak, maka janganlah kamu mengambil sedikitpun dari harta itu. Patutkah kamu mengambilnya dengan cara yang tidak benar dan (yang menyebabkan) dosa yang nyata?', FALSE, NULL, NULL, 81, 4, 32, 64, FALSE, 17, NULL),
(4, 21, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًا', 'وَكَيْفَ تَأْخُذُونَهُ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَاقًا غَلِيظًا', NULL, 'And how could you take it while you have gone in unto each other and they have taken from you a solemn covenant?', 'Dan bagaimana kamu tergamak mengambil balik pemberian itu padahal kasih mesra kamu telah terjalin antara satu dengan yang lain, dan mereka pula (isteri-isteri kamu itu) telahpun mengambil perjanjian yang kuat daripada kamu?', FALSE, NULL, NULL, 81, 4, 32, 64, FALSE, 0, NULL),
(4, 22, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ إِنَّهُۥ كَانَ فَٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا', 'وَلَا تَنكِحُوا مَا نَكَحَ آبَاؤُكُم مِّنَ النِّسَاءِ إِلَّا مَا قَدْ سَلَفَ إِنَّهُ كَانَ فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا', NULL, 'And do not marry those [women] whom your fathers married, except what has already occurred. Indeed, it was an immorality and hateful [to Allāh] and was evil as a way.', 'Dan janganlah kamu berkahwin (dengan perempuan-perempuan) yang telah diperisterikan oleh bapa kamu kecuali apa yang telah berlaku pada masa yang lalu. Sesungguhnya perbuatan itu adalah satu perkara yang keji, dan dibenci (oleh Allah), serta menjadi seburuk-buruk jalan (yang dilalui dalam perkahwinan).', FALSE, NULL, NULL, 81, 4, 32, 64, FALSE, 0, NULL),
(4, 23, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُم مِّنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُم مِّن نِّسَائِكُمُ اللَّاتِي دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَن تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا', NULL, 'Prohibited to you [for marriage] are your mothers, your daughters, your sisters, your father''s sisters, your mother''s sisters, your brother''s daughters, your sister''s daughters, your [milk] mothers who nursed you, your sisters through nursing, your wives'' mothers, and your step-daughters under your guardianship [born] of your wives unto whom you have gone in. But if you have not gone in unto them, there is no sin upon you. And [also prohibited are] the wives of your sons who are from your [own] loins, and that you take [in marriage] two sisters simultaneously, except for what has already occurred. Indeed, Allāh is ever Forgiving and Merciful.', 'Diharamkan kepada kamu berkahwin dengan (perempuan-perempuan yang berikut): ibu-ibu kamu, dan anak-anak kamu, dan saudara-saudara kamu, dan saudara-saudara bapa kamu, dan saudara-saudara ibu kamu dan anak-anak saudara kamu yang lelaki, dan anak-anak saudara kamu yang perempuan, dan ibu-ibu kamu yang telah menyusukan kamu, dan saudara-saudara susuan kamu, dan ibu-ibu isteri kamu, dan anak-anak tiri yang dalam pemuliharaan kamu dari isteri-isteri yang kamu telah campuri; tetapi kalau kamu belum campuri mereka (isteri kamu) itu (dan kamu telahpun menceraikan mereka), maka tiadalah salah kamu (berkahwin dengannya). Dan (haram juga kamu berkahwin dengan) bekas isteri anak-anak kamu sendiri yang berasal dari benih kamu. Dan diharamkan kamu menghimpunkan dua beradik sekali (untuk menjadi isteri-isteri kamu), kecuali yang telah berlaku pada masa yang lalu. Sesungguhnya Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 81, 4, 32, 65, FALSE, 0, NULL),
(4, 24, 'وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ كِتَابَ اللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُم مَّا وَرَاءَ ذَٰلِكُمْ أَن تَبْتَغُوا بِأَمْوَالِكُم مُّحْصِنِينَ غَيْرَ مُسَافِحِينَ فَمَا اسْتَمْتَعْتُم بِهِ مِنْهُنَّ فَآتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَاضَيْتُم بِهِ مِن بَعْدِ الْفَرِيضَةِ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا', NULL, 'And [also prohibited to you are all] married women except those your right hands possess. [This is] the decree of Allāh upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allāh is ever Knowing and Wise.', 'Dan (diharamkan juga kamu berkahwin dengan) perempuan-perempuan isteri orang, kecuali hamba sahaya yang kamu miliki. (Haramnya segala yang tersebut itu) ialah suatu ketetapan hukum Allah (yang diwajibkan) atas kamu. Dan (sebaliknya) dihalalkan bagi kamu perempuan-perempuan yang lain daripada yang tersebut itu, untuk kamu mencari (isteri) dengan harta kamu secara bernikah, bukan secara berzina. Kemudian mana-mana perempuan yang kamu nikmati percampuran dengannya (setelah ia menjadi isteri kamu), maka berikanlah kepada mereka maskahwinnya (dengan sempurna), sebagai suatu ketetapan (yang diwajibkan oleh Allah). Dan tiadalah kamu berdosa mengenai sesuatu persetujuan yang telah dicapai bersama oleh kamu (suami isteri), sesudah ditetapkan maskahwin itu (tentang cara dan kadar pembayarannya). Sesungguhnya Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 82, 5, 33, 65, FALSE, 0, NULL),
(4, 25, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم بَعْضُكُم مِّنۢ بَعْضٍ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ فَمِن مَّا مَلَكَتْ أَيْمَانُكُم مِّن فَتَيَاتِكُمُ الْمُؤْمِنَاتِ وَاللَّهُ أَعْلَمُ بِإِيمَانِكُم بَعْضُكُم مِّن بَعْضٍ فَانكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَآتُوهُنَّ أُجُورَهُنَّ بِالْمَعْرُوفِ مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلَا مُتَّخِذَاتِ أَخْدَانٍ فَإِذَا أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَاحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى الْمُحْصَنَاتِ مِنَ الْعَذَابِ ذَٰلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنكُمْ وَأَن تَصْبِرُوا خَيْرٌ لَّكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'And whoever among you cannot [find] the means to marry free, believing women, then [he may marry] from those whom your right hands possess of believing slave girls. And Allāh is most knowing about your faith. You [believers] are of one another. So marry them with the permission of their people and give them their due compensation [i.e., mahr] according to what is acceptable. [They should be] chaste, neither [of] those who commit unlawful intercourse randomly nor those who take [secret] lovers. But once they are sheltered in marriage, if they should commit adultery, then for them is half the punishment for free [unmarried] women. This [allowance] is for him among you who fears affliction [i.e., sin], but to be patient is better for you. And Allāh is Forgiving and Merciful.', 'Dan sesiapa di antara kamu yang tidak mempunyai kemampuan yang cukup untuk berkahwin dengan perempuan-perempuan yang baik-baik (yang merdeka, yang terpelihara kehormatannya) lagi beriman, maka bolehlah kamu berkahwin dengan hamba-hamba perempuan yang beriman yang kamu miliki. Dan Allah lebih mengetahui akan iman kamu; kamu masing-masing (suami yang merdeka dan isteri dari hamba - abdi itu) adalah berasal sama (dari Adam, dan seugama pula). Oleh itu berkahwinlah dengan mereka dengan izin walinya serta berikanlah maskahwinnya menurut yang patut. Mereka (hamba-hamba perempuan yang akan dijadikan isteri, hendaklah) yang sopan bukan perempuan-perempuan lacur, dan bukan pula yang mengambil lelaki sebagai teman simpanan. Kemudian setelah mereka (hamba-hamba perempuan itu) berkahwin, lalu mereka melakukan perbuatan keji (zina), maka mereka dikenakan separuh dari (hukuman) seksa yang ditetapkan ke atas perempuan-perempuan yang merdeka. (Hukum perkahwinan) yang demikian (yang membolehkan seseorang berkahwin dengan hamba-hamba perempuan) itu ialah bagi orang-orang yang bimbang melakukan zina di antara kamu; dan sabarnya kamu (tidak berkahwin dengan hamba-hamba perempuan) itu adalah lebih baik bagi kamu. Dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 82, 5, 33, 65, FALSE, 0, NULL),
(4, 26, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'Allāh wants to make clear to you [the lawful from the unlawful] and guide you to the [good] practices of those before you and to accept your repentance. And Allāh is Knowing and Wise.', 'Allah menghendaki (dengan apa yang telah diharamkan dan dihalalkan dari kaum perempuan itu) ialah untuk menerangkan (SyariatNya) dan untuk menunjukkan kepada kamu jalan-jalan aturan orang-orang yang dahulu daripada kamu (Nabi-nabi dan orang-orang yang soleh, supaya kamu mengikutinya), dan juga untuk menerima taubat kamu. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 82, 5, 33, 66, FALSE, 0, NULL),
(4, 27, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا', 'وَاللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ الَّذِينَ يَتَّبِعُونَ الشَّهَوَاتِ أَن تَمِيلُوا مَيْلًا عَظِيمًا', NULL, 'Allāh wants to accept your repentance, but those who follow [their] passions want you to digress [into] a great deviation.', 'Dan Allah hendak (membersihkan kamu dari dosa dengan) menerima taubat kamu, sedang orang-orang (yang fasik) yang menurut keinginan hawa nafsu (yang diharamkan oleh Allah itu) hendak mendorong kamu supaya kamu menyeleweng (dari kebenaran) dengan penyelewengan yang besar bahayanya.', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 28, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًا', 'يُرِيدُ اللَّهُ أَن يُخَفِّفَ عَنكُمْ وَخُلِقَ الْإِنسَانُ ضَعِيفًا', NULL, 'And Allāh wants to lighten for you [your difficulties]; and mankind was created weak.', 'Allah (sentiasa) hendak meringankan (beban hukumnya) daripada kamu, kerana manusia itu dijadikan berkeadaan lemah.', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍ مِّنكُمْ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَن تَكُونَ تِجَارَةً عَن تَرَاضٍ مِّنكُمْ وَلَا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا', NULL, 'O you who have believed, do not consume one another''s wealth unjustly but only [in lawful] business by mutual consent. And do not kill yourselves [or one another]. Indeed, Allāh is to you ever Merciful.', 'Wahai orang-orang yang beriman, janganlah kamu makan (gunakan) harta-harta kamu sesama kamu dengan jalan yang salah (tipu, judi dan sebagainya), kecuali dengan jalan perniagaan yang dilakukan secara suka sama suka di antara kamu, dan janganlah kamu berbunuh-bunuhan sesama sendiri. Sesungguhnya Allah sentiasa Mengasihani kamu.', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 30, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَانًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا', NULL, 'And whoever does that in aggression and injustice - then We will drive him into a Fire. And that, for Allāh, is [always] easy.', 'Dan sesiapa berbuat demikian dengan menceroboh dan aniaya, maka kami akan masukkan dia ke dalam api neraka, dan balasan yang sedemikian itu adalah mudah bagi Allah, (tidak ada sesiapapun yang dapat menghalangnya).', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 31, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', 'إِن تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', NULL, 'If you avoid the major sins which you are forbidden, We will remove from you your lesser sins and admit you to a noble entrance [into Paradise].', 'Jika kamu menjauhkan dosa-dosa besar yang dilarang kamu melakukannya, Kami akan ampunkan kesalahan-kesalahan (dosa kecil) kamu, dan kami akan masukkan kamu ke tempat yang mulia (syurga).', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 32, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَىٰ بَعْضٍ لِّلرِّجَالِ نَصِيبٌ مِّمَّا اكْتَسَبُوا وَلِلنِّسَاءِ نَصِيبٌ مِّمَّا اكْتَسَبْنَ وَاسْأَلُوا اللَّهَ مِن فَضْلِهِ إِنَّ اللَّهَ كَانَ بِكُلِّ شَيْءٍ عَلِيمًا', NULL, 'And do not wish for that by which Allāh has made some of you exceed others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask Allāh of His bounty. Indeed Allāh is ever, of all things, Knowing.', 'Dan janganlah kamu terlalu mengharapkan (ingin mendapat) limpah kurnia yang Allah telah berikan kepada sebahagian dari kamu (untuk menjadikan mereka) melebihi sebahagian yang lain (tentang harta benda, ilmu pengetahuan atau pangkat kebesaran). (Kerana telah tetap) orang-orang lelaki ada bahagian dari apa yang mereka usahakan, dan orang-orang perempuan pula ada bahagian dari apa yang mereka usahakan; (maka berusahalah kamu) dan pohonkanlah kepada Allah akan limpah kurnianya. Sesungguhnya Allah sentiasa Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 33, 'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', 'وَلِكُلٍّ جَعَلْنَا مَوَالِيَ مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ فَآتُوهُمْ نَصِيبَهُمْ إِنَّ اللَّهَ كَانَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدًا', NULL, 'And for all, We have made heirs to what is left by parents and relatives. And to those whom your oaths have bound [to you] - give them their share. Indeed Allāh is ever, over all things, a Witness.', 'Dan bagi tiap-tiap (lelaki dan perempuan yang telah mati), kami telah tetapkan orang-orang yang berhak mewarisi peninggalannya iaitu ibu bapa dan kerabat yang dekat. Dan mana-mana orang yang kamu telah membuat ikatan setia dengan mereka (untuk bantu-membantu dalam masa kecemasan dan kesusahan) maka berikanlah kepada mereka bahagiannya. Sesungguhnya Allah sentiasa Menyaksikan tiap-tiap sesuatu.', FALSE, NULL, NULL, 83, 5, 33, 66, FALSE, 0, NULL),
(4, 34, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا', 'الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِّلْغَيْبِ بِمَا حَفِظَ اللَّهُ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا', NULL, 'Men are in charge of women by [right of] what Allāh has given one over the other and what they spend [for maintenance] from their wealth. So righteous women are devoutly obedient, guarding in [the husband''s] absence what Allāh would have them guard. But those [wives] from whom you fear arrogance - [first] advise them; [then if they persist], forsake them in bed; and [finally], strike them [lightly]. But if they obey you [once more], seek no means against them. Indeed, Allāh is ever Exalted and Grand.', 'Kaum lelaki itu adalah pemimpin dan pengawal yang bertanggungjawab terhadap kaum perempuan, oleh kerana Allah telah melebihkan orang-orang lelaki (dengan beberapa keistimewaan) atas orang-orang perempuan, dan juga kerana orang-orang lelaki telah membelanjakan (memberi nafkah) sebahagian dari harta mereka. Maka perempuan-perempuan yang soleh itu ialah yang taat (kepada Allah dan suaminya), dan yang memelihara (kehormatan dirinya dan apa jua yang wajib dipelihara) ketika suami tidak hadir bersama, dengan pemuliharaan Allah dan pertolonganNya. Dan perempuan-perempuan yang kamu bimbang melakukan perbuatan derhaka (nusyuz) hendaklah kamu menasihati mereka, dan (jika mereka berdegil) pulaukanlah mereka di tempat tidur, dan (kalau juga mereka masih degil) pukullah mereka (dengan pukulan ringan yang bertujuan mengajarnya). Kemudian jika mereka taat kepada kamu, maka janganlah kamu mencari-cari jalan untuk menyusahkan mereka. Sesungguhnya Allah Maha Tinggi, lagi Maha Besar.', FALSE, NULL, NULL, 84, 5, 33, 67, FALSE, 0, NULL),
(4, 35, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا', 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِّنْ أَهْلِهِ وَحَكَمًا مِّنْ أَهْلِهَا إِن يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا', NULL, 'And if you fear dissension between the two, send an arbitrator from his people and an arbitrator from her people. If they both desire reconciliation, Allāh will cause it between them. Indeed, Allāh is ever Knowing and Aware.', 'Dan jika kamu bimbangkan perpecahan di antara mereka berdua (suami isteri) maka lantiklah “orang tengah” (untuk mendamaikan mereka, iaitu), seorang dari keluarga lelaki dan seorang dari keluarga perempuan. Jika kedua-dua “orang tengah” itu (dengan ikhlas) bertujuan hendak mendamaikan, nescaya Allah akan menjadikan kedua (suami isteri itu) berpakat baik. Sesungguhnya Allah sentiasa Mengetahui, lagi Amat mendalam pengetahuanNya.', FALSE, NULL, NULL, 84, 5, 33, 67, FALSE, 0, NULL),
(4, 36, 'وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', 'وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا وَبِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَالْجَارِ ذِي الْقُرْبَىٰ وَالْجَارِ الْجُنُبِ وَالصَّاحِبِ بِالْجَنبِ وَابْنِ السَّبِيلِ وَمَا مَلَكَتْ أَيْمَانُكُمْ إِنَّ اللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', NULL, 'Worship Allāh and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allāh does not like those who are self-deluding and boastful,', 'Dan hendaklah kamu beribadat kepada Allah dan janganlah kamu sekutukan Dia dengan sesuatu apa jua; dan hendaklah kamu berbuat baik kepada kedua ibu bapa, dan kaum kerabat, dan anak-anak yatim, dan orang-orang miskin, dan jiran tetangga yang dekat, dan jiran tetangga yang jauh, dan rakan sejawat, dan orang musafir yang terlantar, dan juga hamba yang kamu miliki. Sesungguhnya Allah tidak suka kepada orang-orang yang sombong takbur dan membangga-banggakan diri;', FALSE, NULL, NULL, 84, 5, 34, 67, FALSE, 0, NULL),
(4, 37, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ وَيَكْتُمُونَ مَا آتَاهُمُ اللَّهُ مِن فَضْلِهِ وَأَعْتَدْنَا لِلْكَافِرِينَ عَذَابًا مُّهِينًا', NULL, 'Who are stingy and enjoin upon [other] people stinginess and conceal what Allāh has given them of His bounty - and We have prepared for the disbelievers a humiliating punishment -', 'Iaitu orang-orang yang bakhil dan menyuruh manusia supaya bakhil serta menyembunyikan apa-apa jua yang Allah berikan kepada mereka dari limpah kurniannya. Dan (sebenarnya) Kami telah sediakan bagi orang-orang kafir itu azab seksa yang amat menghina;', FALSE, NULL, NULL, 84, 5, 34, 67, FALSE, 0, NULL),
(4, 38, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا', 'وَالَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَمَن يَكُنِ الشَّيْطَانُ لَهُ قَرِينًا فَسَاءَ قَرِينًا', NULL, 'And [also] those who spend of their wealth to be seen by the people and believe not in Allāh nor in the Last Day. And he to whom Satan is a companion - then evil is he as a companion.', 'Dan juga orang-orang yang membelanjakan hartanya dengan menunjuk-nunjuk kepada manusia (riak), dan mereka tidak pula beriman kepada Allah dan tidak juga beriman kepada hari akhirat. Dan sesiapa yang (mengambil) Syaitan itu menjadi kawannya, maka seburuk-buruk kawan ialah syaitan.', FALSE, NULL, NULL, 85, 5, 34, 67, FALSE, 0, NULL),
(4, 39, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 'وَمَاذَا عَلَيْهِمْ لَوْ آمَنُوا بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَأَنفَقُوا مِمَّا رَزَقَهُمُ اللَّهُ وَكَانَ اللَّهُ بِهِمْ عَلِيمًا', NULL, 'And what [harm would come] upon them if they believed in Allāh and the Last Day and spent out of what Allāh provided for them? And Allāh is ever, about them, Knowing.', 'Dan apakah (kerugian) yang akan menimpa mereka jika mereka beriman kepada Allah dan hari akhirat, serta mereka mendermakan sebahagian dari apa yang telah dikurniakan Allah kepada mereka? Dan (ingatlah) Allah sentiasa Mengetahui akan keadaan mereka.', FALSE, NULL, NULL, 85, 5, 34, 67, FALSE, 0, NULL),
(4, 40, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', 'إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', NULL, 'Indeed, Allāh does not do injustice, [even] as much as an atom''s weight; while if there is a good deed, He multiplies it and gives from Himself a great reward.', 'Sesungguhnya Allah tidak sekali-kali menganiaya (seseorang) sekalipun seberat zarah (debu). Dan kalaulah (amal yang seberat zarrah) itu amal kebajikan, nescaya akan menggandakannya dan akan memberi, dari sisiNya, pahala yang amat besar.', FALSE, NULL, NULL, 85, 5, 34, 67, FALSE, 0, NULL),
(4, 41, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًا', 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَٰؤُلَاءِ شَهِيدًا', NULL, 'So how [will it be] when We bring from every nation a witness and We bring you, [O Muḥammad], against these [people] as a witness?', 'Maka bagaimanakah (keadaan orang-orang kafir pada hari akhirat kelak), apabila Kami datangkan dari tiap-tiap umat seorang saksi (iaitu Rasul mereka sendiri menjadi saksi terhadap perbuatan mereka), dan Kami juga datangkan engkau (wahai Muhammad) sebagai saksi terhadap umatmu ini?', FALSE, NULL, NULL, 85, 5, 34, 67, FALSE, 0, NULL),
(4, 42, 'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا', 'يَوْمَئِذٍ يَوَدُّ الَّذِينَ كَفَرُوا وَعَصَوُا الرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ الْأَرْضُ وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا', NULL, 'That Day, those who disbelieved and disobeyed the Messenger will wish they could be covered by the earth. And they will not conceal from Allāh a [single] statement.', 'Pada hari itu orang-orang yang kafir dan menderhaka kepada Rasulullah, suka jika mereka disama ratakan dengan tanah (ditelan bumi), dan (ketika itu) mereka tidak dapat menyembunyikan sepatah kata pun dari pengetahuan Allah.', FALSE, NULL, NULL, 85, 5, 34, 67, FALSE, 0, NULL),
(4, 43, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنتُمْ سُكَارَىٰ حَتَّىٰ تَعْلَمُوا مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا وَإِن كُنتُم مَّرْضَىٰ أَوْ عَلَىٰ سَفَرٍ أَوْ جَاءَ أَحَدٌ مِّنكُم مِّنَ الْغَائِطِ أَوْ لَامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا', NULL, 'O you who have believed, do not approach prayer while you are intoxicated until you know what you are saying or in a state of janābah, except those passing through [a place of prayer], until you have washed [your whole body]. And if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women [i.e., had sexual intercourse] and find no water, then seek clean earth and wipe over your faces and your hands [with it]. Indeed, Allāh is ever Pardoning and Forgiving.', 'Wahai orang-orang yang beriman, janganlah kamu hampiri sembahyang (mengerjakannya) sedang kamu dalam keadaan mabuk, hingga kamu sedar dan mengetahui akan apa yang kamu katakan. Dan janganlah pula (hampiri masjid) sedang kamu dalam keadaan Junub (berhadas besar) - kecuali kamu hendak melintas sahaja - hingga kamu mandi bersuci. Dan jika kamu sakit, atau sedang dalam musafir, atau salah seorang di antara kamu datang dari tempat buang air, atau kamu bersentuh dengan perempuan, kemudian kamu tidak mendapat air (untuk mandi atau berwuduk), maka hendaklah kamu bertayamum dengan tanah - debu, yang suci, iaitu sapukanlah ke muka kamu dan kedua tangan kamu. Sesungguhnya Allah Maha Pemaaf, lagi Maha Pengampun.', FALSE, NULL, NULL, 85, 5, 34, 68, FALSE, 0, NULL),
(4, 44, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', 'أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يَشْتَرُونَ الضَّلَالَةَ وَيُرِيدُونَ أَن تَضِلُّوا السَّبِيلَ', NULL, 'Have you not seen those who were given a portion of the Scripture, purchasing error [in exchange for it] and wishing you would lose the way?', 'Tidakkah engkau memerhatikan (wahai Muhammad) orang-orang yang telah diberikan sebahagian dari Kitab, mereka memilih kesesatan (dengan meninggalkan pertunjuk Tuhan), dan mereka pula berkehendak supaya kamu juga sesat jalan.', FALSE, NULL, NULL, 85, 5, 34, 68, FALSE, 0, NULL),
(4, 45, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا', 'وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَىٰ بِاللَّهِ وَلِيًّا وَكَفَىٰ بِاللَّهِ نَصِيرًا', NULL, 'And Allāh is most knowing of your enemies; and sufficient is Allāh as an ally, and sufficient is Allāh as a helper.', 'Dan Allah lebih mengetahui berkenaan dengan musuh-musuh kamu, (oleh itu awasilah angkara musuh kamu itu). Dan cukuplah Allah sebagai Pengawal yang melindungi, dan cukuplah Allah sebagai Penolong (yang menyelamatkan kamu dari angkara mereka).', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 46, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', 'مِّنَ الَّذِينَ هَادُوا يُحَرِّفُونَ الْكَلِمَ عَن مَّوَاضِعِهِ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَاسْمَعْ غَيْرَ مُسْمَعٍ وَرَاعِنَا لَيًّا بِأَلْسِنَتِهِمْ وَطَعْنًا فِي الدِّينِ وَلَوْ أَنَّهُمْ قَالُوا سَمِعْنَا وَأَطَعْنَا وَاسْمَعْ وَانظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ اللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', NULL, 'Among the Jews are those who distort words from their [proper] places [i.e., usages] and say, "We hear and disobey" and "Hear but be not heard" and "Rāʿinā," twisting their tongues and defaming the religion. And if they had said [instead], "We hear and obey" and "Wait for us [to understand]," it would have been better for them and more suitable. But Allāh has cursed them for their disbelief, so they believe not, except for a few.', 'Di antara orang-orang Yahudi ada yang mengubah (atau menukar ganti) Kalamullah (isi Kitab Taurat), dari tempat dan maksudnya yang sebenar, dan berkata (kepada Nabi Muhammad): “Kami dengar”, (sedang mereka berkata dalam hati): “Kami tidak akan menurut”. (Mereka juga berkata): “Tolonglah dengar, tuan tidak diperdengarkan sesuatu yang buruk”, serta (mereka mengatakan): “Raaeina”; (Tujuan kata-kata mereka yang tersebut) hanya memutar belitkan perkataan mereka dan mencela ugama Islam. Dan kalaulah mereka berkata: “Kami dengar dan kami taat, dan dengarlah serta berilah perhatian kepada kami”, tentulah yang demikian itu lebih baik bagi mereka dan lebih betul. Akan tetapi Allah melaknat mereka dengan sebab kekufuran mereka. Oleh itu, mereka tidak beriman kecuali sedikit sahaja (di antara mereka).', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 47, 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 'يَا أَيُّهَا الَّذِينَ أُوتُوا الْكِتَابَ آمِنُوا بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰ أَدْبَارِهَا أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّا أَصْحَابَ السَّبْتِ وَكَانَ أَمْرُ اللَّهِ مَفْعُولًا', NULL, 'O you who were given the Scripture, believe in what We have sent down [to Prophet Muḥammad (ﷺ)], confirming that which is with you, before We obliterate faces and turn them toward their backs or curse them as We cursed the sabbath-breakers. And ever is the matter [i.e., decree] of Allāh accomplished.', 'Wahai orang-orang yang telah diberikan Kitab, berimanlah kamu dengan apa yang telah Kami turunkan (Al-Quran), yang mengesahkan Kitab-Kitab yang ada pada kamu, sebelum Kami menyeksa dengan menghapuskan bentuk muka kamu (sehingga berubah menjadi rata - tidak bermulut, berhidung dan bermata), lalu Kami menjadikannya sama seperti rupa sebelah belakangnya, atau Kami melaknatkan mereka sebagaimana Kami telah melaknatkan orang-orang (dari kaum mereka - Yahudi) yang melanggar larangan bekerja pada hari Sabtu. Dan (ingatlah) perintah Allah itu tetap berlaku.', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 48, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', 'إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ وَمَن يُشْرِكْ بِاللَّهِ فَقَدِ افْتَرَىٰ إِثْمًا عَظِيمًا', NULL, 'Indeed, Allāh does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allāh has certainly fabricated a tremendous sin.', 'Sesungguhnya Allah tidak akan mengampunkan dosa syirik mempersekutukanNya (dengan sesuatu apajua), dan akan mengampunkan dosa yang lain dari itu bagi sesiapa yang dikehendakiNya (menurut aturan SyariatNya). Dan sesiapa yang mempersekutukan Allah (dengan sesuatu yang lain), maka sesungguhnya ia telah melakukan dosa yang besar.', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 49, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', 'أَلَمْ تَرَ إِلَى الَّذِينَ يُزَكُّونَ أَنفُسَهُم بَلِ اللَّهُ يُزَكِّي مَن يَشَاءُ وَلَا يُظْلَمُونَ فَتِيلًا', NULL, 'Have you not seen those who claim themselves to be pure? Rather, Allāh purifies whom He wills, and injustice is not done to them, [even] as much as a thread [inside a date seed].', 'Tidakkah engkau perhatikan (dan merasa pelik wahai Muhammad) kepada orang-orang yang membersihkan (memuji) diri sendiri? (Padahal perkara itu bukan hak manusia) bahkan Allah jualah yang berhak membersihkan (memuji) sesiapa yang dikehendakiNya (menurut aturan SyariatNya); dan mereka pula tidak akan dianiaya (atau dikurangkan balasan mereka) sedikitpun.', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 50, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا', 'انظُرْ كَيْفَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ وَكَفَىٰ بِهِ إِثْمًا مُّبِينًا', NULL, 'Look how they invent about Allāh untruth, and sufficient is that as a manifest sin.', 'Lihatlah (wahai Muhammad) betapa beraninya mereka mengada-adakan perkara-perkara dusta terhadap Allah? Dan cukuplah perbuatan itu menjadi dosa yang terang nyata.', FALSE, NULL, NULL, 86, 5, 34, 68, FALSE, 0, NULL),
(4, 51, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', 'أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا هَٰؤُلَاءِ أَهْدَىٰ مِنَ الَّذِينَ آمَنُوا سَبِيلًا', NULL, 'Have you not seen those who were given a portion of the Scripture, who believe in jibt [superstition] and ṭāghūt [false objects of worship] and say about the disbelievers, "These are better guided than the believers as to the way"?', 'Tidakkah engkau perhatikan (dan merasa pelik wahai Muhammad) kepada orang-orang yang telah diberikan sebahagian dari Kitab (Taurat)? Mereka percaya kepada benda-benda yang disembah yang lain dari Allah, dan kepada Taghut, dan mereka pula berkata kepada orang-orang kafir (kaum musyrik di Makkah) bahawa mereka (kaum musyrik itu) lebih betul jalan ugamanya daripada orang-orang yang beriman (kepada Nabi Muhammad s.a.w).', FALSE, NULL, NULL, 86, 5, 34, 69, FALSE, 0, NULL),
(4, 52, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', 'أُولَٰئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ وَمَن يَلْعَنِ اللَّهُ فَلَن تَجِدَ لَهُ نَصِيرًا', NULL, 'Those are the ones whom Allāh has cursed; and he whom Allāh curses - never will you find for him a helper.', '(Kaum Yahudi yang demikian sikapnya) mereka itulah orang-orang yang dilaknat oleh Allah; dan sesiapa yang dilaknat oleh Allah, maka engkau tidak sekali-kali akan mendapati sesiapa pun yang boleh menolongnya.', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 53, 'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', 'أَمْ لَهُمْ نَصِيبٌ مِّنَ الْمُلْكِ فَإِذًا لَّا يُؤْتُونَ النَّاسَ نَقِيرًا', NULL, 'Or have they a share of dominion? Then [if that were so], they would not give the people [even as much as] the speck on a date seed.', 'Patutkah ada bagi mereka (kaum Yahudi itu) sesuatu bahagian dari kekuasaan memerintah? (Tidak, bahkan kalau ada) maka sudah tentu mereka tidak akan memberikan sedikitpun kebaikan kepada manusia.', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 54, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًا', 'أَمْ يَحْسُدُونَ النَّاسَ عَلَىٰ مَا آتَاهُمُ اللَّهُ مِن فَضْلِهِ فَقَدْ آتَيْنَا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ وَآتَيْنَاهُم مُّلْكًا عَظِيمًا', NULL, 'Or do they envy people for what Allāh has given them of His bounty? But We had already given the family of Abraham the Scripture and wisdom and conferred upon them a great kingdom.', 'Atau patutkah mereka dengki kepada manusia (Nabi Muhammad dan umatnya) disebabkan nikmat (pangkat Nabi dan ugama Islam) yang telah diberikan oleh Allah kepada mereka dari limpah kurniaNya? Kerana sesungguhnya Kami telahpun memberi kepada keluarga Ibrahim: Kitab (ugama) dan hikmat (pangkat Nabi), dan kami telah memberi kepada mereka kerajaan yang besar.', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 55, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', 'فَمِنْهُم مَّنْ آمَنَ بِهِ وَمِنْهُم مَّن صَدَّ عَنْهُ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', NULL, 'And some among them believed in it, and some among them were averse to it. And sufficient is Hell as a blaze.', 'Maka di antara mereka (kaum Yahudi yang dengki itu) ada yang beriman kepada (apa yang telah di kurniakan oleh Allah kepada keluarga Nabi Ibrahim) itu, dan ada pula di antara mereka yang berpaling daripadanya (tidak beriman). Dan cukuplah dengan neraka jahanam yang sentiasa menyala-nyala itu (menjadi tempat seksa mereka).', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 56, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا', 'إِنَّ الَّذِينَ كَفَرُوا بِآيَاتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ إِنَّ اللَّهَ كَانَ عَزِيزًا حَكِيمًا', NULL, 'Indeed, those who disbelieve in Our verses - We will drive them into a fire. Every time their skins are roasted through, We will replace them with other skins so they may taste the punishment. Indeed, Allāh is ever Exalted in Might and Wise.', 'Sesungguhnya orang-orang yang kufur ingkar kepada ayat-ayat keterangan Kami, Kami akan membakar mereka dalam api neraka. Tiap-tiap kali kulit mereka masak hangus, Kami gantikan untuk mereka kulit yang lain supaya mereka dapat merasa azab sengsara itu. Dan (ingatlah) sesungguhnya Allah adalah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 57, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', 'وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا لَّهُمْ فِيهَا أَزْوَاجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', NULL, 'But those who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they abide forever. For them therein are purified spouses, and We will admit them to deepening shade.', 'Dan orang-orang yang beriman serta beramal soleh, Kami akan masukkan mereka ke dalam syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya selama-lamanya. Mereka beroleh dalam syurga itu pasangan-pasangan, isteri-isteri yang suci bersih, serta Kami masukkan mereka ke tempat yang teduh yang sentiasa dinaungi.', FALSE, NULL, NULL, 87, 5, 34, 69, FALSE, 0, NULL),
(4, 58, 'إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا', 'إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ النَّاسِ أَن تَحْكُمُوا بِالْعَدْلِ إِنَّ اللَّهَ نِعِمَّا يَعِظُكُم بِهِ إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا', NULL, 'Indeed, Allāh commands you to render trusts to whom they are due and when you judge between people to judge with justice. Excellent is that which Allāh instructs you. Indeed, Allāh is ever Hearing and Seeing.', 'Sesungguhnya Allah menyuruh kamu supaya menyerahkan segala jenis amanah kepada ahlinya (yang berhak menerimanya), dan apabila kamu menjalankan hukum di antara manusia, (Allah menyuruh) kamu menghukum dengan adil. Sesungguhnya Allah dengan (suruhanNya) itu memberi pengajaran yang sebaik-baiknya kepada kamu. Sesungguhnya Allah sentiasa Mendengar, lagi sentiasa Melihat.', FALSE, NULL, NULL, 87, 5, 35, 69, FALSE, 0, NULL),
(4, 59, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', NULL, 'O you who have believed, obey Allāh and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allāh and the Messenger, if you should believe in Allāh and the Last Day. That is the best [way] and best in result.', 'Wahai orang-orang yang beriman, taatlah kamu kepada Allah dan taatlah kamu kepada Rasulullah dan kepada “Ulil-Amri” (orang-orang yang berkuasa) dari kalangan kamu. Kemudian jika kamu berbantah-bantah (berselisihan) dalam sesuatu perkara, maka hendaklah kamu mengembalikannya kepada (Kitab) Allah (Al-Quran) dan (Sunnah) RasulNya - jika kamu benar beriman kepada Allah dan hari akhirat. Yang demikian adalah lebih baik (bagi kamu), dan lebih elok pula kesudahannya.', FALSE, NULL, NULL, 87, 5, 35, 69, FALSE, 0, NULL),
(4, 60, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًا', 'أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوا إِلَى الطَّاغُوتِ وَقَدْ أُمِرُوا أَن يَكْفُرُوا بِهِ وَيُرِيدُ الشَّيْطَانُ أَن يُضِلَّهُمْ ضَلَالًا بَعِيدًا', NULL, 'Have you not seen those who claim to have believed in what was revealed to you, [O Muḥammad], and what was revealed before you? They wish to refer legislation to ṭāghūt, while they were commanded to reject it; and Satan wishes to lead them far astray.', 'Tidakkah engkau (hairan) melihat (wahai Muhammad) orang-orang (munafik) yang mendakwa bahawa mereka telah beriman kepada Al-Quran yang telah diturunkan kepadamu dan kepada (Kitab-kitab) yang telah diturunkan dahulu daripadamu? Mereka suka hendak berhakim kepada Taghut, padahal mereka telah diperintahkan supaya kufur ingkar kepada Taghut itu. Dan Syaitan pula sentiasa hendak menyesatkan mereka dengan kesesatan yang amat jauh.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 61, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَىٰ مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', NULL, 'And when it is said to them, "Come to what Allāh has revealed and to the Messenger," you see the hypocrites turning away from you in aversion.', 'Dan apabila dikatakan kepada mereka: “Marilah berhakim kepada hukum Al-Quran yang telah diturunkan oleh Allah dan kepada hukum Rasulullah,” nescaya engkau melihat orang-orang munafik itu berpaling serta menghalang (manusia) dengan bersungguh-sungguh daripada menghampirimu.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 62, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًا وَتَوْفِيقًا', 'فَكَيْفَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَاءُوكَ يَحْلِفُونَ بِاللَّهِ إِنْ أَرَدْنَا إِلَّا إِحْسَانًا وَتَوْفِيقًا', NULL, 'So how [will it be] when disaster strikes them because of what their hands have put forth and then they come to you swearing by Allāh, "We intended nothing but good conduct and accommodation."', 'Maka bagaimana halnya apabila mereka ditimpa sesuatu kemalangan disebabkan (kesalahan) yang telah dibuat oleh tangan mereka sendiri, kemudian mereka datang kepadamu sambil bersumpah: “Demi Allah, kami tidak sekali-kali menghendaki melainkan kebaikan dan perdamaian (bagi kedua pihak yang berbalah)”.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 63, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا', 'أُولَٰئِكَ الَّذِينَ يَعْلَمُ اللَّهُ مَا فِي قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِي أَنفُسِهِمْ قَوْلًا بَلِيغًا', NULL, 'Those are the ones of whom Allāh knows what is in their hearts, so turn away from them but admonish them and speak to them a far-reaching [i.e., effective] word.', 'Mereka itulah orang-orang yang diketahui oleh Allah akan apa yang ada dalam hati mereka, oleh itu berpalinglah engkau daripada mereka, dan nasihatilah mereka, serta katakanlah kepada mereka kata-kata yang boleh memberi kesan pada hati mereka.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 64, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا', 'وَمَا أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوا أَنفُسَهُمْ جَاءُوكَ فَاسْتَغْفَرُوا اللَّهَ وَاسْتَغْفَرَ لَهُمُ الرَّسُولُ لَوَجَدُوا اللَّهَ تَوَّابًا رَّحِيمًا', NULL, 'And We did not send any messenger except to be obeyed by permission of Allāh. And if, when they wronged themselves, they had come to you, [O Muḥammad], and asked forgiveness of Allāh and the Messenger had asked forgiveness for them, they would have found Allāh Accepting of Repentance and Merciful.', 'Dan Kami tidak mengutus seseorang Rasul pun melainkan supaya ia ditaati dengan izin Allah. Dan kalaulah mereka ketika menganiaya diri mereka sendiri datang kepadamu (wahai Muhammad) lalu memohon ampun kepada Allah, dan Rasulullah juga memohon ampun untuk mereka, tentulah mereka mendapati Allah Maha Penerima taubat, lagi Maha Mengasihani.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 65, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا', 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا', NULL, 'But no, by your Lord, they will not [truly] believe until they make you, [O Muḥammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission.', 'Maka demi Tuhanmu (wahai Muhammad)! Mereka tidak disifatkan beriman sehingga mereka menjadikan engkau hakim dalam mana-mana perselisihan yang timbul di antara mereka, kemudian mereka pula tidak merasa di hati mereka sesuatu keberatan dari apa yang telah engkau hukumkan, dan mereka menerima keputusan itu dengan sepenuhnya.', FALSE, NULL, NULL, 88, 5, 35, 70, FALSE, 0, NULL),
(4, 66, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ اقْتُلُوا أَنفُسَكُمْ أَوِ اخْرُجُوا مِن دِيَارِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', NULL, 'And if We had decreed upon them, "Kill yourselves" or "Leave your homes," they would not have done it, except for a few of them. But if they had done what they were instructed, it would have been better for them and a firmer position [for them in faith].', 'Dan sesungguhnya kalau Kami wajibkan kepada mereka (dengan perintah): “Bunuhlah diri kamu sendiri, atau keluarlah dari tempat kediaman kamu”, nescaya mereka tidak akan melakukannya, kecuali sedikit di antara mereka. Dan sesungguhnya kalau mereka amalkan nasihat pengajaran (meliputi suruh dan tegah) yang telah diberikan kepada mereka, tentulah yang demikian itu lebih baik bagi mereka dan lebih meneguhkan (iman mereka).', FALSE, NULL, NULL, 89, 5, 35, 70, FALSE, 0, NULL),
(4, 67, 'وَإِذًا لَّـَٔاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا', 'وَإِذًا لَّآتَيْنَاهُم مِّن لَّدُنَّا أَجْرًا عَظِيمًا', NULL, 'And then We would have given them from Us a great reward.', 'Dan (setelah mereka berkeadaan demikian), tentulah Kami akan berikan kepada mereka - dari sisi Kami - pahala balasan yang amat besar;', FALSE, NULL, NULL, 89, 5, 35, 70, FALSE, 0, NULL),
(4, 68, 'وَلَهَدَيْنَٰهُمْ صِرَٰطًا مُّسْتَقِيمًا', 'وَلَهَدَيْنَاهُمْ صِرَاطًا مُّسْتَقِيمًا', NULL, 'And We would have guided them to a straight path.', 'Dan tentulah Kami pimpin mereka ke jalan yang lurus.', FALSE, NULL, NULL, 89, 5, 35, 70, FALSE, 0, NULL),
(4, 69, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًا', 'وَمَن يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَٰئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَٰئِكَ رَفِيقًا', NULL, 'And whoever obeys Allāh and the Messenger - those will be with the ones upon whom Allāh has bestowed favor of the prophets, the steadfast affirmers of truth, the martyrs and the righteous. And excellent are those as companions.', 'Dan sesiapa yang taat kepada Allah dan RasulNya, maka mereka akan (ditempatkan di syurga) bersama-sama orang-orang yang telah dikurniakan nikmat oleh Allah kepada mereka, iaitu Nabi-nabi, dan orang-orang Siddiqiin, dan orang-orang yang Syahid, serta orang-orang yang soleh. Dan amatlah eloknya mereka itu menjadi teman rakan (kepada orang-orang yang taat).', FALSE, NULL, NULL, 89, 5, 35, 70, FALSE, 0, NULL),
(4, 70, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ وَكَفَىٰ بِٱللَّهِ عَلِيمًا', 'ذَٰلِكَ الْفَضْلُ مِنَ اللَّهِ وَكَفَىٰ بِاللَّهِ عَلِيمًا', NULL, 'That is the bounty from Allāh, and sufficient is Allāh as Knower.', 'Yang demikian itu adalah limpah kurnia dari Allah; dan cukuplah Allah Yang Maha Mengetahui (akan balasan pahalanya).', FALSE, NULL, NULL, 89, 5, 35, 70, FALSE, 0, NULL),
(4, 71, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ فَانفِرُوا ثُبَاتٍ أَوِ انفِرُوا جَمِيعًا', NULL, 'O you who have believed, take your precaution and [either] go forth in companies or go forth all together.', 'Wahai orang-orang yang beriman, bersedialah dan berjaga-jagalah (sebelum kamu menghadapi musuh), kemudian (bila dikehendaki) maralah (ke medan perang) sepuak demi sepuak, atau (jika perlu) maralah serentak beramai-ramai.', FALSE, NULL, NULL, 89, 5, 35, 71, FALSE, 0, NULL),
(4, 72, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَابَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ اللَّهُ عَلَيَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', NULL, 'And indeed, there is among you he who lingers behind; and if disaster strikes you, he says, "Allāh has favored me in that I was not present with them."', 'Dan sesungguhnya ada di antara kamu: orang-orang yang sengaja memberat-beratkan dirinya (juga orang lain, daripada turut mara ke medan perang). Kemudian kalau kamu ditimpa kemalangan (tercedera atau terbunuh) ia berkata: “Sesungguhnya Allah telah mengurniakan nikmat kepadaku, kerana aku tidak turut berperang bersama-sama mereka”.', FALSE, NULL, NULL, 89, 5, 35, 71, FALSE, 0, NULL),
(4, 73, 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', 'وَلَئِنْ أَصَابَكُمْ فَضْلٌ مِّنَ اللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُن بَيْنَكُمْ وَبَيْنَهُ مَوَدَّةٌ يَا لَيْتَنِي كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', NULL, 'But if bounty comes to you from Allāh, he will surely say, as if [i.e., showing that] there had never been between you and him any affection, "Oh, I wish I had been with them so I could have attained a great attainment."', 'Dan demi sesungguhnya kalau kamu beroleh limpah kurnia (kemenangan) dari Allah, sudah tentu ia mengatakan (dengan sesalnya), seolah-olah tidak ada hubungan kasih mesra antara kamu dengannya: “Alangkah baiknya kalau aku turut serta bersama-sama mereka, supaya aku juga beroleh kemenangan yang amat besar?”', FALSE, NULL, NULL, 89, 5, 35, 71, FALSE, 0, NULL),
(4, 74, 'فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'فَلْيُقَاتِلْ فِي سَبِيلِ اللَّهِ الَّذِينَ يَشْرُونَ الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ وَمَن يُقَاتِلْ فِي سَبِيلِ اللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', NULL, 'So let those fight in the cause of Allāh who sell the life of this world for the Hereafter. And he who fights in the cause of Allāh and is killed or achieves victory - We will bestow upon him a great reward.', 'Oleh itu, orang-orang (yang beriman) yang mengutamakan kebahagiaan akhirat daripada (kesenangan) kehidupan dunia, hendaklah mereka berperang pada jalan Allah (untuk membela Islam). Dan sesiapa yang berperang pada jalan Allah lalu ia mati (gugur Syahid) atau beroleh kemenangan, maka Kami akan memberi kepadanya pahala yang besar.', FALSE, NULL, NULL, 89, 5, 36, 71, FALSE, 0, NULL),
(4, 75, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', 'وَمَا لَكُمْ لَا تُقَاتِلُونَ فِي سَبِيلِ اللَّهِ وَالْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ الَّذِينَ يَقُولُونَ رَبَّنَا أَخْرِجْنَا مِنْ هَٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', NULL, 'And what is [the matter] with you that you fight not in the cause of Allāh and [for] the oppressed among men, women and children who say, "Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper"?', 'Dan apakah yang menghalang kamu (maka kamu) tidak mahu berperang pada jalan Allah (untuk menegakkan ugama Islam) dan (untuk menyelamatkan) orang-orang yang tertindas dari kaum lelaki, perempuan dan kanak-kanak, iaitu mereka yang selalu (berdoa dengan) berkata: “Wahai Tuhan kami! Keluarkanlah kami dari negeri (Makkah) ini, yang penduduknya (kaum kafir musyrik) yang zalim, dan jadikanlah bagi kami dari pihakMu seorang pemimpin yang mengawal (keselamatan ugama kami), dan jadikanlah bagi kami dari pihakMu seorang pemimpin yang membela kami (dari ancaman musuh)”.', FALSE, NULL, NULL, 90, 5, 36, 71, FALSE, 0, NULL),
(4, 76, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 'الَّذِينَ آمَنُوا يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ وَالَّذِينَ كَفَرُوا يُقَاتِلُونَ فِي سَبِيلِ الطَّاغُوتِ فَقَاتِلُوا أَوْلِيَاءَ الشَّيْطَانِ إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا', NULL, 'Those who believe fight in the cause of Allāh, and those who disbelieve fight in the cause of ṭāghūt. So fight against the allies of Satan. Indeed, the plot of Satan has ever been weak.', 'Orang-orang yang beriman, berperang pada jalan Allah; dan orang-orang yang kafir pula berperang pada jalan Taghut (Syaitan). Oleh sebab itu, perangilah kamu akan pengikut-pengikut Syaitan itu, kerana sesungguhnya tipu daya Syaitan itu adalah lemah.', FALSE, NULL, NULL, 90, 5, 36, 71, FALSE, 0, NULL),
(4, 77, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْـَٔاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', 'أَلَمْ تَرَ إِلَى الَّذِينَ قِيلَ لَهُمْ كُفُّوا أَيْدِيَكُمْ وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُوا رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا الْقِتَالَ لَوْلَا أَخَّرْتَنَا إِلَىٰ أَجَلٍ قَرِيبٍ قُلْ مَتَاعُ الدُّنْيَا قَلِيلٌ وَالْآخِرَةُ خَيْرٌ لِّمَنِ اتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', NULL, 'Have you not seen those who were told, "Restrain your hands [from fighting] and establish prayer and give zakāh"? But then when battle was ordained for them, at once a party of them feared men as they fear Allāh or with [even] greater fear. They said, "Our Lord, why have You decreed upon us fighting? If only You had postponed [it for] us for a short time." Say, "The enjoyment of this world is little, and the Hereafter is better for he who fears Allāh. And injustice will not be done to you, [even] as much as a thread [inside a date seed]."', 'Tidakkah engkau (hairan) melihat (wahai Muhammad), akan orang-orang yang (pernah) dikatakan kepada mereka: “Tahanlah tangan kamu (daripada bertindak melancarkan perang yang belum diizinkan), dan dirikanlah sembahyang serta berikanlah zakat”. (Mereka meminta juga hendak berperang), kemudian apabila mereka diperintahkan berperang, tiba-tiba sepuak di antara mereka merasa gerun kepada manusia sama seperti mereka merasa gerun kepada (azab) Allah atau lebih gerun lagi. Lalu mereka (merayu kepada Allah dengan) berkata: “Wahai Tuhan kami, mengapa Engkau wajibkan kami berperang (pada saat ini)? Mengapa Engkau tidak biarkan kami hingga ke tempoh yang singkat (iaitu akhir hayat kami)?” Katakanlah (wahai Muhammad): “Harba benda yang menjadi kesenangan di dunia ini adalah sedikit sahaja, (dan akhirnya akan lenyap), dan (balasan) hari akhirat itu lebih baik lagi bagi orang-orang yang bertaqwa (kerana ia lebih mewah dan kekal selama-lamanya), dan kamu pula tidak akan dianiaya sedikit pun”.', FALSE, NULL, NULL, 90, 5, 36, 72, FALSE, 0, NULL),
(4, 78, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', 'أَيْنَمَا تَكُونُوا يُدْرِككُّمُ الْمَوْتُ وَلَوْ كُنتُمْ فِي بُرُوجٍ مُّشَيَّدَةٍ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا هَٰذِهِ مِنْ عِندِ اللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا هَٰذِهِ مِنْ عِندِكَ قُلْ كُلٌّ مِّنْ عِندِ اللَّهِ فَمَالِ هَٰؤُلَاءِ الْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', NULL, 'Wherever you may be, death will overtake you, even if you should be within towers of lofty construction. But if good comes to them, they say, "This is from Allāh"; and if evil befalls them, they say, "This is from you." Say, "All [things] are from Allāh." So what is [the matter] with those people that they can hardly understand any statement?', 'Di mana jua kamu berada, maut akan mendapatkan kamu (bila sampai ajal), sekalipun kamu berada dalam benteng-benteng yang tinggi lagi kukuh. Dan kalau mereka beroleh kebaikan (kemewahan hidup), mereka berkata: “Ini adalah dari sisi Allah”, dan kalau pula mereka ditimpa bencana, mereka berkata: “Ini adalah dari (sesuatu nahas) yang ada padamu”. Katakanlah (wahai Muhammad): “Semuanya itu (kebaikan dan bencana) adalah (berpunca) dari sisi Allah”. Maka apakah yang menyebabkan kaum itu hampir-hampir tidak memahami perkataan (nasihat dan pengajaran)?', FALSE, NULL, NULL, 90, 5, 36, 72, FALSE, 0, NULL),
(4, 79, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًا وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'مَّا أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ اللَّهِ وَمَا أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ وَأَرْسَلْنَاكَ لِلنَّاسِ رَسُولًا وَكَفَىٰ بِاللَّهِ شَهِيدًا', NULL, 'What comes to you of good is from Allāh, but what comes to you of evil, [O man], is from yourself. And We have sent you, [O Muḥammad], to the people as a messenger, and sufficient is Allāh as Witness.', 'Apa jua kebaikan (nikmat kesenangan) yang engkau dapati maka ia adalah dari Allah; dan apa jua bencana yang menimpamu maka ia adalah dari (kesalahan) dirimu sendiri. Dan Kami telah mengutus engkau (wahai Muhammad) kepada seluruh umat manusia sebagai seorang Rasul (yang membawa rahmat). Dan cukuplah Allah menjadi saksi (yang membuktikan kebenaran hakikat ini).', FALSE, NULL, NULL, 90, 5, 36, 72, FALSE, 0, NULL),
(4, 80, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا', 'مَّن يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ وَمَن تَوَلَّىٰ فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا', NULL, 'He who obeys the Messenger has obeyed Allāh; but those who turn away - We have not sent you over them as a guardian.', 'Sesiapa yang taat kepada Rasulullah, maka sesungguhnya ia telah taat kepada Allah; dan sesiapa yang berpaling ingkar, maka (janganlah engkau berdukacita wahai Muhammad), kerana Kami tidak mengutusmu untuk menjadi pengawal (yang memelihara mereka dari melakukan kesalahan).', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 81, 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا مِنْ عِندِكَ بَيَّتَ طَائِفَةٌ مِّنْهُمْ غَيْرَ الَّذِي تَقُولُ وَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى اللَّهِ وَكَفَىٰ بِاللَّهِ وَكِيلًا', NULL, 'And they say, "[We pledge] obedience." But when they leave you, a group of them spend the night determining to do other than what you say. But Allāh records what they plan by night. So leave them alone and rely upon Allāh. And sufficient is Allāh as Disposer of affairs.', 'Dan mereka (golongan munafik) berkata: “(Kami) taat”, kemudian apabila mereka keluar dari majlismu, segolongan dari mereka memutuskan pada malam hari satu rancangan yang lain daripada (pengakuan taat) yang mereka katakan (kepadamu). Sedang Allah (perintahkan malaikat) menulis apa yang mereka rancangkan itu; maka berpalinglah (wahai Muhammad) daripada mereka, (janganlah dihiraukan apa yang mereka rancangkan), serta berserahlah kepada Allah; kerana cukuplah Allah menjadi Pembela (yang memeliharamu dari angkara mereka).', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 82, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًا كَثِيرًا', 'أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا', NULL, 'Then do they not reflect upon the Qur’ān? If it had been from [any] other than Allāh, they would have found within it much contradiction.', 'Patutkah mereka (bersikap demikian), tidak mahu memikirkan isi Al-Quran? Kalaulah Al-Quran itu (datangnya) bukan dari sisi Allah, nescaya mereka akan dapati perselisihan yang banyak di dalamnya.', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 83, 'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًا', 'وَإِذَا جَاءَهُمْ أَمْرٌ مِّنَ الْأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلَىٰ أُولِي الْأَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنبِطُونَهُ مِنْهُمْ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ لَاتَّبَعْتُمُ الشَّيْطَانَ إِلَّا قَلِيلًا', NULL, 'And when there comes to them something [i.e., information] about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allāh upon you and His mercy, you would have followed Satan, except for a few.', 'Dan apabila datang kepada mereka sesuatu berita mengenai keamanan atau kecemasan, mereka terus menghebahkannya; padahal kalau mereka kembalikan sahaja hal itu kepada Rasulullah dan kepada - “Ulil-Amri” (orang-orang yang berkuasa) di antara mereka, tentulah hal itu dapat diketahui oleh orang-orang yang layak mengambil keputusan mengenainya di antara mereka; dan jika tidaklah kerana limpah kurnia Allah dan belas kasihanNya kepada kamu, tentulah kamu (terbabas) menurut Syaitan kecuali sedikit sahaja (iaitu orang-orang yang teguh imannya dan luas ilmunya di antara kamu).', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 84, 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ وَحَرِّضِ ٱلْمُؤْمِنِينَ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', 'فَقَاتِلْ فِي سَبِيلِ اللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ وَحَرِّضِ الْمُؤْمِنِينَ عَسَى اللَّهُ أَن يَكُفَّ بَأْسَ الَّذِينَ كَفَرُوا وَاللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', NULL, 'So fight, [O Muḥammad], in the cause of Allāh; you are not held responsible except for yourself. And encourage the believers [to join you] that perhaps Allāh will restrain the [military] might of those who disbelieve. And Allāh is greater in might and stronger in [exemplary] punishment.', 'Oleh itu, berperanglah (wahai Muhammad) pada jalan Allah (untuk membela Islam dari pencerobohan musuh); engkau tidak diberati selain daripada kewajipanmu sendiri. Dan berilah peransang kepada orang-orang yang beriman (supaya turut berjuang dengan gagah berani). Mudah-mudahan Allah menahan bahaya serangan orang-orang yang kafir itu. Dan (ingatlah) Allah Amatlah besar kekuatanNya dan Amatlah berat azab seksaNya.', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 85, 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا', 'مَّن يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُن لَّهُ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَاعَةً سَيِّئَةً يَكُن لَّهُ كِفْلٌ مِّنْهَا وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقِيتًا', NULL, 'Whoever intercedes for a good cause will have a share [i.e., reward] therefrom; and whoever intercedes for an evil cause will have a portion [i.e., burden] therefrom. And ever is Allāh, over all things, a Keeper.', 'Sesiapa yang memberikan syafaat yang baik nescaya ia akan memperoleh bahagian (pahala) daripadanya; dan sesiapa yang memberikan syafaat yang buruk, nescaya ia akan mendapat bahagian (dosa) daripadanya. Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 86, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا إِنَّ اللَّهَ كَانَ عَلَىٰ كُلِّ شَيْءٍ حَسِيبًا', NULL, 'And when you are greeted with a greeting, greet [in return] with one better than it or [at least] return it [in a like manner]. Indeed Allāh is ever, over all things, an Accountant.', 'Dan apabila kamu diberikan penghormatan dengan sesuatu ucapan hormat (seperti memberi salam), maka balaslah penghormatan itu dengan yang lebih baik daripadanya, atau balaslah dia (dengan cara yang sama). Sesungguhnya Allah sentiasa menghitung tiap-tiap sesuatu.', FALSE, NULL, NULL, 91, 5, 36, 72, FALSE, 0, NULL),
(4, 87, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ الْقِيَامَةِ لَا رَيْبَ فِيهِ وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا', NULL, 'Allāh - there is no deity except Him. He will surely assemble you for [account on] the Day of Resurrection, about which there is no doubt. And who is more truthful than Allāh in statement.', 'Allah, tiada Tuhan (yang berhak disembah) melainkan Dia. Sesungguhnya Ia akan menghimpunkan kamu pada hari kiamat, (hari) yang tidak ada syak padanya. Dan siapakah pula yang lebih benar perkataannya daripada Allah?', FALSE, NULL, NULL, 92, 5, 36, 72, FALSE, 0, NULL),
(4, 88, 'فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ وَاللَّهُ أَرْكَسَهُم بِمَا كَسَبُوا أَتُرِيدُونَ أَن تَهْدُوا مَنْ أَضَلَّ اللَّهُ وَمَن يُضْلِلِ اللَّهُ فَلَن تَجِدَ لَهُ سَبِيلًا', NULL, 'What is [the matter] with you [that you are] two groups concerning the hypocrites, while Allāh has made them fall back [into error and disbelief] for what they earned. Do you wish to guide those whom Allāh has sent astray? And he whom Allāh sends astray - never will you find for him a way [of guidance].', 'Maka apakah yang menyebabkan kamu (berpecah) menjadi dua golongan terhadap kaum munafik itu, padahal Allah telah menjerumuskan mereka (ke dalam kekufuran) disebabkan apa yang telah mereka usahakan? Adakah kamu pula hendak memberi pertunjuk kepada orang-orang yang telah disesatkan oleh Allah? Padahal sesiapa yang telah disesatkan oleh Allah, maka engkau tidak sekali-kali akan mendapat jalan untuk menyelamatkannya.', FALSE, NULL, NULL, 92, 5, 37, 73, FALSE, 0, NULL),
(4, 89, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', 'وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا فَتَكُونُونَ سَوَاءً فَلَا تَتَّخِذُوا مِنْهُمْ أَوْلِيَاءَ حَتَّىٰ يُهَاجِرُوا فِي سَبِيلِ اللَّهِ فَإِن تَوَلَّوْا فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُوا مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', NULL, 'They wish you would disbelieve as they disbelieved so you would be alike. So do not take from among them allies until they emigrate for the cause of Allāh. But if they turn away [i.e., refuse], then seize them and kill them [for their betrayal] wherever you find them and take not from among them any ally or helper,', 'Mereka suka kalau kamu pula menjadi kafir sebagaimana mereka telah menjadi kafir, maka (dengan yang demikian) menjadilah kamu sama seperti mereka. Oleh itu janganlah kamu mengambil (seorang pun) di antara mereka menjadi teman rapat kamu, sehingga mereka berhijrah pada jalan Allah (untuk menegakkan Islam). Kemudian kalau mereka sengaja berpaling ingkar, maka tawanlah mereka dan bunuhlah mereka di mana sahaja kamu menemuinya; dan jangan sekali-kali kamu mengambil (seorang pun) di antara mereka menjadi teman rapat atau penolong;', FALSE, NULL, NULL, 92, 5, 37, 73, FALSE, 0, NULL),
(4, 90, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', 'إِلَّا الَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُم مِّيثَاقٌ أَوْ جَاءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَاتِلُوكُمْ أَوْ يُقَاتِلُوا قَوْمَهُمْ وَلَوْ شَاءَ اللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَاتَلُوكُمْ فَإِنِ اعْتَزَلُوكُمْ فَلَمْ يُقَاتِلُوكُمْ وَأَلْقَوْا إِلَيْكُمُ السَّلَمَ فَمَا جَعَلَ اللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', NULL, 'Except for those who take refuge with a people between yourselves and whom is a treaty or those who come to you, their hearts strained at [the prospect of] fighting you or fighting their own people. And if Allāh had willed, He could have given them power over you, and they would have fought you. So if they remove themselves from you and do not fight you and offer you peace, then Allāh has not made for you a cause [for fighting] against them.', 'Kecuali orang-orang yang pergi (meminta perlindungan) kepada suatu kaum yang ada ikatan perjanjian setia antara kamu dengan mereka, atau orang-orang yang datang kepada kamu sedang hati mereka merasa berat hendak memerangi kamu atau memerangi kaumnya. Dan jika Allah menghendaki, nescaya Ia menjadikan mereka berkuasa melawan kamu, kemudian tentulah mereka memerangi kamu. Dalam pada itu, jika mereka membiarkan kamu (dengan tidak mengancam atau mengganggu), serta mereka tidak memerangi kamu dan mereka menawarkan perdamaian kepada kamu, maka Allah tidak menjadikan bagi kamu sesuatu jalan (yang membolehkan kamu memerangi atau menawan) mereka.', FALSE, NULL, NULL, 92, 5, 37, 73, FALSE, 0, NULL),
(4, 91, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًا مُّبِينًا', 'سَتَجِدُونَ آخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ كُلَّ مَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوا إِلَيْكُمُ السَّلَمَ وَيَكُفُّوا أَيْدِيَهُمْ فَخُذُوهُمْ وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأُولَٰئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَانًا مُّبِينًا', NULL, 'You will find others who wish to obtain security from you and [to] obtain security from their people. Every time they are returned to [the influence of] disbelief, they fall back into it. So if they do not withdraw from you or offer you peace or restrain their hands, then seize them and kill them wherever you overtake them. And those - We have made for you against them a clear authorization.', 'Kamu juga akan dapati golongan-golongan yang lain (yang pura-pura Islam) supaya mereka beroleh aman dari pihak kamu, dan (sebaliknya mereka melahirkan kekufurannya) supaya mereka beroleh aman dari pihak kaumnya (yang masih kafir). Tiap-tiap kali mereka diajak kepada fitnah (pencerobohan), mereka segera terjerumus ke dalamnya. Oleh itu, jika mereka tidak membiarkan kamu (dan terus mengganggu atau berpihak kepada musuh), dan (tidak pula) menawarkan perdamaian kepada kamu dan juga (tidak) menahan tangan mereka (daripada memerangi kamu), maka hendaklah kamu bertindak menawan mereka dan membunuh mereka di mana sahaja kamu menemuinya; kerana merekalah orang-orang yang Kami jadikan bagi kamu alasan yang terang nyata untuk bertindak terhadapnya.', FALSE, NULL, NULL, 92, 5, 37, 73, FALSE, 0, NULL),
(4, 92, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً وَمَن قَتَلَ مُؤْمِنًا خَطَأً فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰ أَهْلِهِ إِلَّا أَن يَصَّدَّقُوا فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَإِن كَانَ مِن قَوْمٍ بَيْنَكُمْ وَبَيْنَهُم مِّيثَاقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰ أَهْلِهِ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ اللَّهِ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', NULL, 'And never is it for a believer to kill a believer except by mistake. And whoever kills a believer by mistake - then the freeing of a believing slave and a compensation payment [diyah] presented to his [i.e., the deceased''s] family [is required], unless they give [up their right as] charity. But if he [i.e., the deceased] was from a people at war with you and he was a believer - then [only] the freeing of a believing slave; and if he was from a people with whom you have a treaty - then a compensation payment presented to his family and the freeing of a believing slave. And whoever does not find [one or cannot afford to buy one] - then [instead], a fast for two months consecutively, [seeking] acceptance of repentance from Allāh. And Allāh is ever Knowing and Wise.', 'Dan tidak harus sama sekali bagi seseorang mukmin membunuh seorang mukmin yang lain, kecuali dengan tidak sengaja. Dan sesiapa yang membunuh seorang mukmin dengan tidak sengaja, maka (wajiblah ia membayar kaffarah) dengan memerdekakan seorang hamba yang beriman serta membayar “diah” (denda ganti nyawa) yang diserahkan kepada ahlinya (keluarga si mati), kecuali jika mereka sedekahkan (memaafkannya). Tetapi jika ia (yang terbunuh dengan tidak sengaja) dari kaum (kafir) yang memusuhi kamu, sedang ia sendiri beriman, maka (wajiblah si pembunuh membayar kaffarah sahaja dengan) memerdekakan seorang hamba yang beriman. Dan jika ia (orang yang terbunuh dengan tidak sengaja itu) dari kaum (kafir) yang ada ikatan perjanjian setia di antara kamu dengan mereka, maka wajiblah membayar “diah” (denda ganti nyawa) kepada keluarganya serta memerdekakan seorang hamba yang beriman. Dalam pada itu, sesiapa yang tidak dapat (mencari hamba yang akan dimerdekakannya), maka hendaklah ia berpuasa dua bulan berturut-turut; (hukum yang tersebut) datangnya dari Allah untuk menerima taubat (membersihkan diri kamu). Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 93, 5, 37, 74, FALSE, 0, NULL),
(4, 93, 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا', 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا', NULL, 'But whoever kills a believer intentionally - his recompense is Hell, wherein he will abide eternally, and Allāh has become angry with him and has cursed him and has prepared for him a great punishment.', 'Dan sesiapa yang membunuh seorang mukmin dengan sengaja, maka balasannya ialah neraka jahanam, kekal ia di dalamnya, dan Allah murka kepadanya, dan melakanatkannya serta menyediakan baginya azab seksa yang besar.', FALSE, NULL, NULL, 93, 5, 37, 74, FALSE, 0, NULL),
(4, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ فَتَبَيَّنُوا وَلَا تَقُولُوا لِمَنْ أَلْقَىٰ إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ الْحَيَاةِ الدُّنْيَا فَعِندَ اللَّهِ مَغَانِمُ كَثِيرَةٌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ اللَّهُ عَلَيْكُمْ فَتَبَيَّنُوا إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', NULL, 'O you who have believed, when you go forth [to fight] in the cause of Allāh, investigate; and do not say to one who gives you [a greeting of] peace, "You are not a believer," aspiring for the goods of worldly life; for with Allāh are many acquisitions. You [yourselves] were like that before; then Allāh conferred His favor [i.e., guidance] upon you, so investigate. Indeed Allāh is ever, of what you do, Aware.', 'Wahai orang-orang yang beriman, apabila kamu pergi (berperang) pada jalan Allah (untuk membela Islam), maka hendaklah kamu menyelidik (apa jua perkara dengan sebaik-baiknya), dan janganlah kamu (terburu-buru) mengatakan kepada orang yang menunjukkan kepada kamu sikap damai (dengan memberi salam atau mengucap dua Kalimah Syahadat): “Engkau bukan orang yang beriman” (lalu kamu membunuhnya) dengan tujuan hendak (mendapat harta bendanya yang merupakan) harta benda kehidupan dunia (yang tidak kekal). (Janganlah kamu gelap mata kepada daki dunia itu) kerana di sisi Allah ada disediakan limpah kurnia yang banyak. Demikianlah juga keadaan kamu dahulu (dapat diketahui oleh orang lain akan keIslaman kamu dengan memberi salam atau mengucap kalimah Syahadat), lalu Allah mengurniakan nikmatNya kepada kamu. Oleh itu selidikilah (apa-apa jua lebih dahulu, dan janganlah bertindak dengan terburu-buru). Sesungguhnya Allah sentiasa memerhati dengan mendalam akan segala yang kamu lakukan.', FALSE, NULL, NULL, 93, 5, 37, 74, FALSE, 0, NULL),
(4, 95, 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةً وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًا', 'لَّا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فَضَّلَ اللَّهُ الْمُجَاهِدِينَ بِأَمْوَالِهِمْ وَأَنفُسِهِمْ عَلَى الْقَاعِدِينَ دَرَجَةً وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَىٰ وَفَضَّلَ اللَّهُ الْمُجَاهِدِينَ عَلَى الْقَاعِدِينَ أَجْرًا عَظِيمًا', NULL, 'Not equal are those believers remaining [at home] - other than the disabled - and the mujāhideen, [who strive and fight] in the cause of Allāh with their wealth and their lives. Allāh has preferred the mujāhideen through their wealth and their lives over those who remain [behind], by degrees. And to all [i.e., both] Allāh has promised the best [reward]. But Allāh has preferred the mujāhideen over those who remain [behind] with a great reward -', 'Tidaklah sama keadaan orang-orang yang duduk (tidak turut berperang) dari kalangan orang-orang yang beriman - selain daripada orang-orang yang ada keuzuran - dengan orang-orang yang berjihad (berjuang) pada jalan Allah (untuk membela Islam) dengan harta dan jiwanya. Allah melebihkan orang-orang yang berjuang dengan harta benda dan jiwa mereka atas orang-orang yang tinggal duduk (tidak turut berperang kerana uzur) dengan kelebihan satu darjat. Dan tiap-tiap satu (dari dua golongan itu) Allah menjanjikan dengan balasan yang baik (Syurga), dan Allah melebihkan orang-orang yang berjuang atas orang-orang yang tinggal duduk (tidak turut berperang dan tidak ada sesuatu uzur) dengan pahala yang amat besar;', FALSE, NULL, NULL, 94, 5, 37, 74, FALSE, 0, NULL),
(4, 96, 'دَرَجَٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'دَرَجَاتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'Degrees [of high position] from Him and forgiveness and mercy. And Allāh is ever Forgiving and Merciful.', 'Iaitu beberapa darjat kelebihan daripadaNya, dan keampunan serta rahmat belas kasihan. Dan (ingatlah) adalah Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 94, 5, 37, 74, FALSE, 0, NULL),
(4, 97, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَسَآءَتْ مَصِيرًا', 'إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ قَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا فَأُولَٰئِكَ مَأْوَاهُمْ جَهَنَّمُ وَسَاءَتْ مَصِيرًا', NULL, 'Indeed, those whom the angels take [in death] while wronging themselves - [the angels] will say, "In what [condition] were you?" They will say, "We were oppressed in the land." They [the angels] will say, "Was not the earth of Allāh spacious [enough] for you to emigrate therein?" For those, their refuge is Hell - and evil it is as a destination.', 'Sesungguhnya orang-orang yang diambil nyawanya oleh malaikat semasa mereka sedang menganiaya diri sendiri (kerana enggan berhijrah untuk membela Islam dan rela ditindas oleh kaum kafir musyrik), mereka ditanya oleh malaikat dengan berkata: “Apakah yang kamu telah lakukan mengenai ugama kamu?” Mereka menjawab: “Kami dahulu adalah orang-orang yang tertindas di bumi”. Malaikat bertanya lagi: “Tidakkah bumi Allah itu luas, yang membolehkan kamu berhijrah dengan bebas padanya?” Maka orang-orang yang sedemikian itu keadaannya, tempat akhir mereka ialah neraka jahanam, dan neraka jahanam itu adalah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 94, 5, 37, 75, FALSE, 0, NULL),
(4, 98, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', 'إِلَّا الْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', NULL, 'Except for the oppressed among men, women and children who cannot devise a plan nor are they directed to a way -', 'Kecuali orang-orang yang lemah (lagi uzur) dari kaum lelaki dan perempuan serta kanak-kanak, yang tidak berdaya upaya mencari helah (untuk melepaskan diri) dan tidak pula mengetahui sesuatu jalan (untuk berhijrah).', FALSE, NULL, NULL, 94, 5, 37, 75, FALSE, 0, NULL),
(4, 99, 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا', 'فَأُولَٰئِكَ عَسَى اللَّهُ أَن يَعْفُوَ عَنْهُمْ وَكَانَ اللَّهُ عَفُوًّا غَفُورًا', NULL, 'For those it is expected that Allāh will pardon them, and Allāh is ever Pardoning and Forgiving.', 'Maka mereka (yang demikian sifatnya), mudah-mudahan Allah maafkan mereka. Dan (ingatlah), Allah Maha Pemaaf, lagi Maha Pengampun.', FALSE, NULL, NULL, 94, 5, 37, 75, FALSE, 0, NULL),
(4, 100, 'وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'وَمَن يُهَاجِرْ فِي سَبِيلِ اللَّهِ يَجِدْ فِي الْأَرْضِ مُرَاغَمًا كَثِيرًا وَسَعَةً وَمَن يَخْرُجْ مِن بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'And whoever emigrates for the cause of Allāh will find on the earth many [alternative] locations and abundance. And whoever leaves his home as an emigrant to Allāh and His Messenger and then death overtakes him - his reward has already become incumbent upon Allāh. And Allāh is ever Forgiving and Merciful.', 'Dan sesiapa yang berhijrah pada jalan Allah (untuk membela dan menegakkan Islam), nescaya ia akan dapati di muka bumi ini tempat berhijrah yang banyak dan rezeki yang makmur; dan sesiapa yang keluar dari rumahnya dengan tujuan berhijrah kepada Allah dan RasulNya, kemudian ia mati (dalam perjalanan), maka sesungguhnya telah tetap pahala hijrahnya di sisi Allah. Dan (ingatlah) Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 94, 5, 38, 75, FALSE, 0, NULL),
(4, 101, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا', 'وَإِذَا ضَرَبْتُمْ فِي الْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا مِنَ الصَّلَاةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ الَّذِينَ كَفَرُوا إِنَّ الْكَافِرِينَ كَانُوا لَكُمْ عَدُوًّا مُّبِينًا', NULL, 'And when you travel throughout the land, there is no blame upon you for shortening the prayer, [especially] if you fear that those who disbelieve may disrupt [or attack] you. Indeed, the disbelievers are ever to you a clear enemy.', 'Dan apabila kamu musafir di muka bumi, maka kamu tidaklah berdosa “mengqasarkan” (memendekkan) sembahyang jika kamu takut diserang oleh orang-orang kafir. Sesungguhnya orang-orang kafir itu adalah musuh yang amat nyata bagi kamu.', FALSE, NULL, NULL, 94, 5, 38, 76, FALSE, 0, NULL),
(4, 102, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ وَخُذُوا۟ حِذْرَكُمْ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلَاةَ فَلْتَقُمْ طَائِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا فَلْيَكُونُوا مِن وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ الَّذِينَ كَفَرُوا لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَاحِدَةً وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰ أَن تَضَعُوا أَسْلِحَتَكُمْ وَخُذُوا حِذْرَكُمْ إِنَّ اللَّهَ أَعَدَّ لِلْكَافِرِينَ عَذَابًا مُّهِينًا', NULL, 'And when you [i.e., the commander of an army] are among them and lead them in prayer, let a group of them stand [in prayer] with you and let them carry their arms. And when they have prostrated, let them be [in position] behind you and have the other group come forward which has not [yet] prayed and let them pray with you, taking precaution and carrying their arms. Those who disbelieve wish that you would neglect your weapons and your baggage so they could come down upon you in one [single] attack. But there is no blame upon you, if you are troubled by rain or are ill, for putting down your arms, but take precaution. Indeed, Allāh has prepared for the disbelievers a humiliating punishment.', 'Dan apabila engkau (wahai Muhammad) berada dalam kalangan mereka (semasa perang), lalu engkau mendirikan sembahyang dengan (menjadi imam) mereka, maka hendaklah sepuak dari mereka berdiri (mengerjakan sembahyang) bersama-samamu, dan hendaklah mereka menyandang senjata masing-masing; kemudian apabila mereka telah sujud, maka hendaklah mereka berundur ke belakang (untuk menjaga serbuan musuh); dan hendaklah datang pula puak yang lain (yang kedua) yang belum sembahyang (kerana menjaga serbuan musuh), maka hendaklah mereka bersembahyang (berjamaah) bersama-samamu, dan hendakah mereka mengambil langkah berjaga-jaga serta menyandang senjata masing-masing. Orang-orang kafir memang suka kalau kamu cuai lalai akan senjata dan harta benda kamu, supaya dengan jalan itu mereka dapat menyerbu kamu beramai-ramai dengan serentak. Dan tidaklah kamu berdosa meletakkan senjata masing-masing, jika kamu dihalangi sesuatu yang menyusahkan disebabkan hujan atau kamu sakit. Dan hendaklah kamu mengambil langkah berjaga-jaga. Sesungguhnya Allah telah menyediakan bagi orang-orang kafir itu azab seksa yang amat menghina.', FALSE, NULL, NULL, 95, 5, 38, 76, FALSE, 0, NULL),
(4, 103, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًا مَّوْقُوتًا', 'فَإِذَا قَضَيْتُمُ الصَّلَاةَ فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ فَإِذَا اطْمَأْنَنتُمْ فَأَقِيمُوا الصَّلَاةَ إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَّوْقُوتًا', NULL, 'And when you have completed the prayer, remember Allāh standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times.', 'Kemudian apabila kamu telah selesai mengerjakan sembahyang, maka hendaklah kamu menyebut dan mengingati Allah semasa kamu berdiri atau duduk, dan semasa kamu berbaring. Kemudian apabila kamu telah merasa tenteram (berada dalam keadaan aman) maka dirikanlah sembahyang itu (dengan sempurna sebagaimana biasa). Sesungguhnya sembahyang itu adalah satu ketetapan yang diwajibkan atas orang-orang yang beriman, yang tertentu waktunya.', FALSE, NULL, NULL, 95, 5, 38, 76, FALSE, 0, NULL),
(4, 104, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'وَلَا تَهِنُوا فِي ابْتِغَاءِ الْقَوْمِ إِن تَكُونُوا تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ اللَّهِ مَا لَا يَرْجُونَ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', NULL, 'And do not weaken in pursuit of the enemy. If you should be suffering - so are they suffering as you are suffering, but you expect from Allāh that which they expect not. And Allāh is ever Knowing and Wise.', 'Dan janganlah kamu lemah (hilang semangat) dalam memburu musuh (yang menceroboh) itu; kerana kalau kamu menderita sakit (luka atau mati) maka sesungguhnya mereka pun menderita sakitnya seperti penderitaan kamu; sedang kamu mengharapkan dari Allah apa yang mereka tidak harapkan (iaitu balasan yang baik pada hari akhirat kelak). Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 95, 5, 38, 76, FALSE, 0, NULL),
(4, 105, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا', 'إِنَّا أَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلَا تَكُن لِّلْخَائِنِينَ خَصِيمًا', NULL, 'Indeed, We have revealed to you, [O Muḥammad], the Book in truth so you may judge between the people by that which Allāh has shown you. And do not be for the deceitful an advocate.', 'Sesungguhnya Kami menurunkan kepadamu (wahai Muhammad) Kitab (Al-Quran) dengan membawa kebenaran, supaya engkau menghukum di antara manusia menurut apa yang Allah telah tunjukkan kepadamu (melalui wahyuNya); dan janganlah engkau menjadi pembela bagi orang-orang yang khianat.', FALSE, NULL, NULL, 95, 5, 38, 77, FALSE, 0, NULL),
(4, 106, 'وَٱسْتَغْفِرِ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'وَاسْتَغْفِرِ اللَّهَ إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا', NULL, 'And seek forgiveness of Allāh. Indeed, Allāh is ever Forgiving and Merciful.', 'Dan hendaklah engkau memohon ampun kepada Allah; kerana sesungguhnya Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 107, 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', 'وَلَا تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ إِنَّ اللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', NULL, 'And do not argue on behalf of those who deceive themselves. Indeed, Allāh loves not one who is a habitually sinful deceiver.', 'Dan janganlah engkau berbahas untuk membela orang-orang yang mengkhianati diri mereka sendiri. Sesungguhnya Allah tidak suka kepada orang-orang yang selalu melakukan khianat, lagi sentiasa berdosa.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 108, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', 'يَسْتَخْفُونَ مِنَ النَّاسِ وَلَا يَسْتَخْفُونَ مِنَ اللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ الْقَوْلِ وَكَانَ اللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', NULL, 'They conceal [their evil intentions and deeds] from the people, but they cannot conceal [them] from Allāh, and He is with them [in His knowledge] when they spend the night in such as He does not accept of speech. And ever is Allāh, of what they do, encompassing.', 'Mereka menyembunyikan (kejahatan mereka) daripada manusia, dalam pada itu mereka tidak menyembunyikan (kejahatan mereka) daripada Allah. Padahal Allah ada bersama-sama mereka, ketika mereka merancangkan pada malam hari, kata-kata yang tidak diredhai oleh Allah. Dan (ingatlah) Allah sentiasa Meliputi PengetahuanNya akan apa yang mereka lakukan.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 109, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', 'هَا أَنتُمْ هَٰؤُلَاءِ جَادَلْتُمْ عَنْهُمْ فِي الْحَيَاةِ الدُّنْيَا فَمَن يُجَادِلُ اللَّهَ عَنْهُمْ يَوْمَ الْقِيَامَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', NULL, 'Here you are - those who argue on their behalf in [this] worldly life - but who will argue with Allāh for them on the Day of Resurrection, or who will [then] be their representative?', 'Sedarlah! Kamu ini adalah orang-orang (yang telah menyimpang dari kebenaran), kamu telah berhujah membela mereka (yang bersalah) dalam kehidupan dunia ini, maka siapakah yang akan berhujah kepada Allah untuk membela mereka itu pada hari kiamat kelak? Atau siapakah yang akan menjadi pelindung mereka (dari azab seksa yang disediakan oleh Allah)?', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 110, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا', 'وَمَن يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ يَجِدِ اللَّهَ غَفُورًا رَّحِيمًا', NULL, 'And whoever does a wrong or wrongs himself but then seeks forgiveness of Allāh will find Allāh Forgiving and Merciful.', 'Dan sesiapa yang melakukan kejahatan atau menganiaya dirinya sendiri (dengan melakukan maksiat) kemudian ia memohon ampun kepada Allah, nescaya ia akan mendapati Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 111, 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَىٰ نَفْسِهِ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', NULL, 'And whoever earns [i.e., commits] a sin only earns it against himself. And Allāh is ever Knowing and Wise.', 'Dan sesiapa yang mengerjakan sesuatu dosa maka sesungguhnya ia hanya mengerjakannya untuk (menjadi bala bencana yang) menimpa dirinya sendiri. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 112, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'وَمَن يَكْسِبْ خَطِيئَةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِ بَرِيئًا فَقَدِ احْتَمَلَ بُهْتَانًا وَإِثْمًا مُّبِينًا', NULL, 'But whoever earns an offense or a sin and then blames it on an innocent [person] has taken upon himself a slander and manifest sin.', 'Dan sesiapa yang melakukan suatu kesalahan atau suatu dosa, kemudian ia menuduhnya kepada orang yang tidak bersalah, maka sesungguhnya ia telah memikul kesalahan berbuat dusta, dan melakukan dosa yang amat nyata.', FALSE, NULL, NULL, 96, 5, 38, 77, FALSE, 0, NULL),
(4, 113, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَىْءٍ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا', 'وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ لَهَمَّت طَّائِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّا أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَيْءٍ وَأَنزَلَ اللَّهُ عَلَيْكَ الْكِتَابَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ وَكَانَ فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا', NULL, 'And if it was not for the favor of Allāh upon you, [O Muḥammad], and His mercy, a group of them would have determined to mislead you. But they do not mislead except themselves, and they will not harm you at all. And Allāh has revealed to you the Book and wisdom and has taught you that which you did not know. And ever has the favor of Allāh upon you been great.', 'Dan kalaulah tidak kerana limpah kurnia Allah dan rahmatNya kepadamu (wahai Muhammad), nescaya berhasilah cita-cita segolongan dari mereka yang bertujuan hendak menyesatkanmu, padahal mereka tidak akan menyesatkan melainkan dirinya sendiri; dan juga mereka tidak akan dapat mendatangkan mudarat kepadamu sedikitpun; dan (selain itu) Allah telah menurunkan kepadamu Kitab (Al-Quran) serta Hikmah (pengetahuan yang mendalam), dan telah mengajarkanmu apa yang engkau tidak mengetahuinya. Dan adalah kurnia Allah yang dilimpahkanNya kepada mu amatlah besar.', FALSE, NULL, NULL, 96, 5, 38, 78, FALSE, 0, NULL),
(4, 114, 'لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'لَّا خَيْرَ فِي كَثِيرٍ مِّن نَّجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَاحٍ بَيْنَ النَّاسِ وَمَن يَفْعَلْ ذَٰلِكَ ابْتِغَاءَ مَرْضَاتِ اللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', NULL, 'No good is there in much of their private conversation, except for those who enjoin charity or that which is right or conciliation between people. And whoever does that seeking means to the approval of Allāh - then We are going to give him a great reward.', 'Tidak ada kebaikan pada kebanyakan bisik-bisikan mereka, kecuali (bisik-bisikan) orang yang menyuruh bersedekah, atau berbuat kebaikan, atau mendamaikan di antara manusia. Dan sesiapa yang berbuat demikian dengan maksud mencari keredaan Allah, tentulah Kami akan memberi kepadanya pahala yang amat besar.', FALSE, NULL, NULL, 97, 5, 39, 78, FALSE, 0, NULL),
(4, 115, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', 'وَمَن يُشَاقِقِ الرَّسُولَ مِن بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّىٰ وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا', NULL, 'And whoever opposes the Messenger after guidance has become clear to him and follows other than the way of the believers - We will give him what he has taken and drive him into Hell, and evil it is as a destination.', 'Dan sesiapa yang menentang (ajaran) Rasulullah sesudah terang nyata kepadanya kebenaran pertunjuk (yang dibawanya), dan ia pula mengikut jalan yang lain dari jalan orang-orang yang beriman, Kami akan memberikannya kuasa untuk melakukan (kesesatan) yang dipilihnya, dan (pada hari akhirat kelak) Kami akan memasukkannya ke dalam neraka jahanam; dan neraka jahanam itu adalah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 97, 5, 39, 78, FALSE, 0, NULL),
(4, 116, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ وَمَن يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا', NULL, 'Indeed, Allāh does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allāh has certainly gone far astray.', 'Sesungguhnya Allah tidak akan mengampunkan dosa orang yang mempersekutukanNya dengan sesuatu (apa jua), dan akan mengampunkan yang lain daripada kesalahan (syirik) itu bagi sesiapa yang dikehendakiNya (menurut peraturan hukum-hukumNya); dan sesiapa yang mempersekutukan Allah dengan sesuatu (apa jua), maka sesungguhnya ia telah sesat dengan kesesatan yang amat jauh.', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 117, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًا مَّرِيدًا', 'إِن يَدْعُونَ مِن دُونِهِ إِلَّا إِنَاثًا وَإِن يَدْعُونَ إِلَّا شَيْطَانًا مَّرِيدًا', NULL, 'They call upon instead of Him none but female [deities], and they [actually] call upon none but a rebellious Satan,', 'Apa yang mereka sembah yang lain dari Allah itu, hanyalah berhala-berhala (makhluk-makhluk yang lemah), dan mereka (dengan yang demikian) tidak menyembah melainkan Syaitan yang derhaka;', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 118, 'لَّعَنَهُ ٱللَّهُ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', 'لَّعَنَهُ اللَّهُ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', NULL, 'Whom Allāh has cursed. For he had said, "I will surely take from among Your servants a specific portion.', 'Yang telah dilaknat oleh Allah, dan yang telah mengatakan: “Demi sesungguhnya, aku akan mengambil dari kalangan hamba-hambaMu, bahagian yang tertentu (untuk menjadi pengikutku);', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 119, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَآمُرَنَّهُمْ فَلَيُبَتِّكُنَّ آذَانَ الْأَنْعَامِ وَلَآمُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ اللَّهِ وَمَن يَتَّخِذِ الشَّيْطَانَ وَلِيًّا مِّن دُونِ اللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', NULL, 'And I will mislead them, and I will arouse in them [sinful] desires, and I will command them so they will slit the ears of cattle, and I will command them so they will change the creation of Allāh." And whoever takes Satan as an ally instead of Allāh has certainly sustained a clear loss.', '“Dan demi sesungguhnya, aku akan menyesatkan mereka (dari kebenaran), dan demi sesungguhnya aku akan memperdayakan mereka dengan angan-angan kosong, dan demi sesungguhnya aku akan menyuruh mereka (mencacatkan binatang-binatang ternak), lalu mereka membelah telinga binatang-binatang itu; dan aku akan menyuruh mereka mengubah ciptaan Allah”. Dan (ingatlah) sesiapa yang mengambil Syaitan menjadi pemimpin yang ditaati selain dari Allah, maka sesungguhnya rugilah ia dengan kerugian yang terang nyata.', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 120, 'يَعِدُهُمْ وَيُمَنِّيهِمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'يَعِدُهُمْ وَيُمَنِّيهِمْ وَمَا يَعِدُهُمُ الشَّيْطَانُ إِلَّا غُرُورًا', NULL, 'He [i.e., Satan] promises them and arouses desire in them. But Satan does not promise them except delusion.', 'Syaitan sentiasa menjanjikan mereka (dengan janji-janji indah) serta memperdayakan mereka dengan angan-angan kosong; dan apa yang dijanjikan oleh Syaitan itu tidak lain hanyalah tipu daya semata-mata.', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 121, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', 'أُولَٰئِكَ مَأْوَاهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', NULL, 'The refuge of those will be Hell, and they will not find from it an escape.', 'Mereka itu, tempat akhirnya ialah neraka jahanam, dan mereka pula tidak akan dapat melarikan diri daripadanya.', FALSE, NULL, NULL, 97, 5, 39, 79, FALSE, 0, NULL),
(4, 122, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا وَعْدَ ٱللَّهِ حَقًّا وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا', 'وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا وَعْدَ اللَّهِ حَقًّا وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا', NULL, 'But the ones who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they will abide forever. [It is] the promise of Allāh, [which is] truth, and who is more truthful than Allāh in statement.', 'Dan orang-orang yang beriman serta beramal soleh, Kami akan masukkan mereka ke dalam Syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya selama-lamanya, sebagai janji Allah yang benar. Dan siapakah yang lebih benar perkataannya daripada Allah?', FALSE, NULL, NULL, 98, 5, 39, 79, FALSE, 0, NULL),
(4, 123, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَا أَمَانِيِّ أَهْلِ الْكِتَابِ مَن يَعْمَلْ سُوءًا يُجْزَ بِهِ وَلَا يَجِدْ لَهُ مِن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا', NULL, 'It [i.e., Paradise] is not [obtained] by your wishful thinking nor by that of the People of the Scripture. Whoever does a wrong will be recompensed for it, and he will not find besides Allāh a protector or a helper.', '(Balasan yang baik yang dijanjikan oleh Allah itu) tidak akan didapati hanya dengan angan-angan kamu semata-mata, dan tidak pula dengan angan-angan ahli Kitab (Yahudi dan Nasrani). Sesiapa yang melakukan kejahatan, ia akan dibalas dengan kejahatan itu, dan ia pula tidak akan mendapat - selain dari Allah - seorang pun yang akan melindunginya, dan tidak ada juga yang dapat menolongnya.', FALSE, NULL, NULL, 98, 5, 39, 79, FALSE, 0, NULL),
(4, 124, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', 'وَمَن يَعْمَلْ مِنَ الصَّالِحَاتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُولَٰئِكَ يَدْخُلُونَ الْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', NULL, 'And whoever does righteous deeds, whether male or female, while being a believer - those will enter Paradise and will not be wronged, [even as much as] the speck on a date seed.', 'Dan sesiapa yang mengerjakan amal soleh, dari lelaki atau perempuan, sedang ia beriman, maka mereka itu akan masuk Syurga, dan mereka pula tidak akan dianiaya (atau dikurangkan balasannya) sedikitpun.', FALSE, NULL, NULL, 98, 5, 39, 79, FALSE, 0, NULL),
(4, 125, 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا', 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ وَاتَّبَعَ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَاتَّخَذَ اللَّهُ إِبْرَاهِيمَ خَلِيلًا', NULL, 'And who is better in religion than one who submits himself to Allāh while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allāh took Abraham as an intimate friend.', 'Dan tidak ada yang lebih baik ugamanya daripada orang yang menyerahkan dirinya kepada Allah (dengan ikhlas), sedang ia berusaha mengerjakan kebaikan, dan ia pula mengikut ugama Nabi Ibrahim yang lurus (yang tetap di atas dasar tauhid); dan (kerana itulah) Allah menjadikan Nabi Ibrahim kesayanganNya.', FALSE, NULL, NULL, 98, 5, 39, 79, FALSE, 0, NULL),
(4, 126, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ مُّحِيطًا', NULL, 'And to Allāh belongs whatever is in the heavens and whatever is on the earth. And ever is Allāh, of all things, encompassing.', 'Dan bagi Allah jualah segala yang ada di langit dan yang ada di bumi; dan Allah sentiasa Meliputi (pengetahuanNya dan kekuasaanNya) akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 98, 5, 39, 79, FALSE, 0, NULL),
(4, 127, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا', 'وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِي الْكِتَابِ فِي يَتَامَى النِّسَاءِ اللَّاتِي لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَالْمُسْتَضْعَفِينَ مِنَ الْوِلْدَانِ وَأَن تَقُومُوا لِلْيَتَامَىٰ بِالْقِسْطِ وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ كَانَ بِهِ عَلِيمًا', NULL, 'And they request from you, [O Muḥammad], a [legal] ruling concerning women. Say, "Allāh gives you a ruling about them and [about] what has been recited to you in the Book concerning the orphan girls to whom you do not give what is decreed for them - and [yet] you desire to marry them - and concerning the oppressed among children and that you maintain for orphans [their rights] in justice." And whatever you do of good - indeed, Allāh is ever Knowing of it.', 'Dan mereka meminta fatwa kepadamu (wahai Muhammad), mengenai (hak dan kewajipan) kaum perempuan. Katakanlah olehmu: “Allah akan memberi keterangan (fatwa) kepada kamu mengenai mereka dan juga (ada difatwakan dalam) apa yang selalu dibacakan kepada kamu dalam Kitab (Al-Quran) ini mengenai perempuan-perempuan yatim yang kamu tidak memberi kepadanya apa yang telah ditetapkan menjadi hak mereka, dan yang kamu suka berkahwin dengan mereka; dan juga mengenai anak-anak yang lemah (yang masih kecil lagi). Dan (kamu juga diwajibkan) supaya menguruskan (hak dan keperluan) anak-anak yatim dengan adil. Dan (ingatlah) apa jua kebaikan yang kamu lakukan (kepada mereka), maka sesungguhnya Allah sentiasa Mengetahuinya.”', FALSE, NULL, NULL, 98, 5, 39, 80, FALSE, 0, NULL),
(4, 128, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَٱلصُّلْحُ خَيْرٌ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'وَإِنِ امْرَأَةٌ خَافَتْ مِن بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ وَأُحْضِرَتِ الْأَنفُسُ الشُّحَّ وَإِن تُحْسِنُوا وَتَتَّقُوا فَإِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', NULL, 'And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them - and settlement is best. And present in [human] souls is stinginess. But if you do good and fear Allāh - then indeed Allāh is ever, of what you do, Aware.', 'Dan jika seorang perempuan bimbang akan timbul dari suaminya “nusyuz” (kebencian), atau tidak melayaninya, maka tiadalah salah bagi mereka (suami isteri) membuat perdamaian di antara mereka berdua (secara yang sebaik-baiknya), kerana perdamaian itu lebih baik (bagi mereka daripada bercerai-berai); sedang sifat bakhil kedekut (tidak suka memberi atau bertolak ansur) itu memang tabiat semula jadi yang ada pada manusia. Dan jika kamu berlaku baik (dalam pergaulan), dan mencegah diri (daripada melakukan kezaliman), maka sesungguhnya Allah Maha Mendalam PengetahuanNya akan apa yang kamu lakukan.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 129, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'وَلَن تَسْتَطِيعُوا أَن تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ وَإِن تُصْلِحُوا وَتَتَّقُوا فَإِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا', NULL, 'And you will never be able to be equal [in feeling] between wives, even if you should strive [to do so]. So do not incline completely [toward one] and leave another hanging. And if you amend [your affairs] and fear Allāh - then indeed, Allāh is ever Forgiving and Merciful.', 'Dan kamu tidak akan dapat berlaku adil di antara isteri-isteri kamu sekalipun kamu bersungguh-sungguh (hendak melakukannya); oleh itu janganlah kamu cenderung dengan melampau (berat sebelah kepada isteri yang kamu sayangi) sehingga kamu biarkan isteri yang lain seperti benda yang tergantung (di awan-awan); dan jika kamu memperbaiki (keadaan yang pincang itu), dan memelihara diri (daripada perbuatan yang zalim), maka sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 130, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا', 'وَإِن يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِّن سَعَتِهِ وَكَانَ اللَّهُ وَاسِعًا حَكِيمًا', NULL, 'But if they separate [by divorce], Allāh will enrich each [of them] from His abundance. And ever is Allāh Encompassing and Wise.', 'Dan jika keduanya bercerai, maka Allah akan cukupkan (keperluan) masing-masing dari limpah kurniaNya. Dan (ingatlah) Allah Maha Luas limpah kurniaNya, lagi Maha Bijaksana.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 131, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَلَقَدْ وَصَّيْنَا الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ اتَّقُوا اللَّهَ وَإِن تَكْفُرُوا فَإِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ غَنِيًّا حَمِيدًا', NULL, 'And to Allāh belongs whatever is in the heavens and whatever is on the earth. And We have instructed those who were given the Scripture before you and yourselves to fear Allāh. But if you disbelieve - then to Allāh belongs whatever is in the heavens and whatever is on the earth. And ever is Allāh Free of need and Praiseworthy.', 'Dan bagi Allah jualah segala yang ada di langit dan yang ada di bumi; dan demi sesungguhnya, Kami telah perintahkan orang-orang yang diberi Kitab dahulu daripada kamu, dan juga (perintahkan) kamu, iaitu hendaklah bertaqwa kepada Allah; dan jika kamu kufur ingkar, maka (ketahuilah) sesungguhnya Allah jualah yang memiliki segala yang ada di langit dan yang ada di bumi; dan (ingatlah) adalah Allah Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 132, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَىٰ بِاللَّهِ وَكِيلًا', NULL, 'And to Allāh belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allāh as Disposer of affairs.', 'Dan bagi Allah jualah apa yang ada di langit dan yang ada di bumi; dan cukuplah Allah sebagai Pengawal (yang mentadbirkan dan menguasai segala-galanya).', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 133, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا النَّاسُ وَيَأْتِ بِآخَرِينَ وَكَانَ اللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', NULL, 'If He wills, He can do away with you, O people, and bring others [in your place]. And ever is Allāh competent to do that.', 'Jika Allah menghendaki, nescaya Ia musnahkan kamu wahai umat manusia dan Ia datangkan gantinya dengan umat-umat yang lain. Dan adalah Allah Maha Kuasa melakukan yang demikian itu.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 134, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا', 'مَّن كَانَ يُرِيدُ ثَوَابَ الدُّنْيَا فَعِندَ اللَّهِ ثَوَابُ الدُّنْيَا وَالْآخِرَةِ وَكَانَ اللَّهُ سَمِيعًا بَصِيرًا', NULL, 'Whoever desires the reward of this world - then with Allāh is the reward of this world and the Hereafter. And ever is Allāh Hearing and Seeing.', 'Sesiapa yang mahukan pahala (balasan) dunia sahaja (maka rugilah ia), kerana di sisi Allah disediakan pahala (balasan) dunia dan akhirat. Dan (ingatlah) Allah sentiasa Mendengar, lagi sentiasa Melihat.', FALSE, NULL, NULL, 99, 5, 39, 80, FALSE, 0, NULL),
(4, 135, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَىٰ أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَىٰ بِهِمَا فَلَا تَتَّبِعُوا الْهَوَىٰ أَن تَعْدِلُوا وَإِن تَلْوُوا أَوْ تُعْرِضُوا فَإِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', NULL, 'O you who have believed, be persistently standing firm in justice, witnesses for Allāh, even if it be against yourselves or parents and relatives. Whether one is rich or poor, Allāh is more worthy of both. So follow not [personal] inclination, lest you not be just. And if you distort [your testimony] or refuse [to give it], then indeed Allāh is ever, of what you do, Aware.', 'Wahai orang-orang yang beriman! Hendaklah kamu menjadi orang-orang yang sentiasa menegakkan keadilan, lagi menjadi saksi (yang menerangkan kebenaran) kerana Allah, sekalipun terhadap diri kamu sendiri, atau ibu bapa dan kaum kerabat kamu. Kalaulah orang (yang didakwa) itu kaya atau miskin (maka janganlah kamu terhalang daripada menjadi saksi yang memperkatakan kebenaran disebabkan kamu bertimbang rasa), kerana Allah lebih bertimbang rasa kepada keduanya. Oleh itu, janganlah kamu turutkan hawa nafsu supaya kamu tidak menyeleweng dari keadilan. Dan jika kamu memutar-balikkan keterangan ataupun enggan (daripada menjadi saksi), maka sesungguhnya Allah sentiasa Mengetahui dengan mendalam akan apa yang kamu lakukan.', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 136, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا آمِنُوا بِاللَّهِ وَرَسُولِهِ وَالْكِتَابِ الَّذِي نَزَّلَ عَلَىٰ رَسُولِهِ وَالْكِتَابِ الَّذِي أَنزَلَ مِن قَبْلُ وَمَن يَكْفُرْ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا', NULL, 'O you who have believed, believe in Allāh and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allāh, His angels, His books, His messengers, and the Last Day has certainly gone far astray.', 'Wahai orang-orang yang beriman! Tetapkanlah iman kamu kepada Allah dan RasulNya, dan kepada Kitab Al-Quran yang telah diturunkan kepada RasulNya (Muhammad, s.a.w), dan juga kepada Kitab-kitab Suci yang telah diturunkan dahulu daripada itu. Dan sesiapa yang kufur ingkar kepada Allah, dan Malaikat-malaikatNya, dan Kitab-kitabNya, dan Rasul-rasulNya dan juga Hari Akhirat, maka sesungguhnya ia telah sesat dengan kesesatan yang amat jauh.', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 137, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 'إِنَّ الَّذِينَ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ آمَنُوا ثُمَّ كَفَرُوا ثُمَّ ازْدَادُوا كُفْرًا لَّمْ يَكُنِ اللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًا', NULL, 'Indeed, those who have believed then disbelieved, then believed then disbelieved, and then increased in disbelief - never will Allāh forgive them, nor will He guide them to a way.', 'Sesungguhnya orang-orang yang beriman, kemudian mereka kafir, kemudian mereka beriman semula, kemudian mereka kafir sekali lagi, kemudian mereka bertambah-tambah lagi dengan kekufuran, Allah tidak sekali-kali akan memberi ampun kepada mereka, dan tidak akan memberi pertunjuk hidayah kepada mereka ke jalan yang benar.', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 138, 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 'بَشِّرِ الْمُنَافِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', NULL, 'Give tidings to the hypocrites that there is for them a painful punishment -', 'Sampaikanlah khabar berita kepada orang-orang munafik: bahawa sesungguhnya disediakan untuk mereka azab seksa yang tidak terperi sakitnya;', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 139, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا', 'الَّذِينَ يَتَّخِذُونَ الْكَافِرِينَ أَوْلِيَاءَ مِن دُونِ الْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ الْعِزَّةَ فَإِنَّ الْعِزَّةَ لِلَّهِ جَمِيعًا', NULL, 'Those who take disbelievers as allies instead of the believers. Do they seek with them honor [through power]? But indeed, honor belongs to Allāh entirely.', '(Iaitu) orang-orang yang mengambil orang-orang kafir menjadi teman rapat dengan meninggalkan orang-orang yang beriman. Tidaklah patut mereka (orang-orang munafik) mencari kekuatan dan kemuliaan di sisi orang-orang kafir itu, kerana sesungguhnya kekuatan dan kemuliaan itu semuanya ialah milik Allah, (diberikannya kepada sesiapa yang dikehendakiNya).', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 140, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ إِنَّكُمْ إِذًا مِّثْلُهُمْ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِي الْكِتَابِ أَنْ إِذَا سَمِعْتُمْ آيَاتِ اللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا مَعَهُمْ حَتَّىٰ يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ إِنَّكُمْ إِذًا مِّثْلُهُمْ إِنَّ اللَّهَ جَامِعُ الْمُنَافِقِينَ وَالْكَافِرِينَ فِي جَهَنَّمَ جَمِيعًا', NULL, 'And it has already come down to you in the Book [i.e., the Qur’ān] that when you hear the verses of Allāh [recited], they are denied [by them] and ridiculed; so do not sit with them until they enter into another conversation. Indeed, you would then be like them. Indeed, Allāh will gather the hypocrites and disbelievers in Hell all together -', 'Dan sesungguhnya Allah telahpun menurunkan kepada kamu (perintahNya) di dalam Kitab (Al-Quran), iaitu: apabila kamu mendengar ayat-ayat keterangan Allah diingkari dan diejek-ejek (oleh kaum kafir dan munafik), maka janganlah kamu duduk (bergaul) dengan mereka sehingga mereka masuk kepada memperkatakan soal yang lain; kerana sesungguhnya (jika kamu melakukan yang demikian), tentulah kamu sama seperti mereka. Sesungguhnya Allah akan menghimpunkan sekalian orang munafik dan orang kafir di dalam neraka Jahannam.', FALSE, NULL, NULL, 100, 5, 40, 81, FALSE, 0, NULL),
(4, 141, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 'الَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ اللَّهِ قَالُوا أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَافِرِينَ نَصِيبٌ قَالُوا أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ الْمُؤْمِنِينَ فَاللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيَامَةِ وَلَن يَجْعَلَ اللَّهُ لِلْكَافِرِينَ عَلَى الْمُؤْمِنِينَ سَبِيلًا', NULL, 'Those who wait [and watch] you. Then if you gain a victory from Allāh, they say, "Were we not with you?" But if the disbelievers have a success, they say [to them], "Did we not gain the advantage over you, but we protected you from the believers?" Allāh will judge between [all of] you on the Day of Resurrection, and never will Allāh give the disbelievers over the believers a way [to overcome them].', '(Mereka yang munafik itu ialah) orang-orang yang sentiasa menunggu-nunggu (berlakunya sesuatu) kepada kamu; maka kalau kamu mendapat kemenangan dari Allah (dalam sesuatu peperangan), berkatalah mereka (kepada kamu): “Bukankah kami turut berjuang bersama-sama kamu? (Oleh itu kami juga berhak menerima bahagian dari harta rampasan perang)”. Dan jika orang-orang kafir pula mendapat bahagian (yang menguntungkan dalam peperangan), berkatalah mereka (kepada orang-orang kafir itu): “Bukankah kami turut membantu kamu dan mempertahankan kamu dari (serang balas) orang-orang yang beriman (dengan mendedahkan rahsia perpaduannya)?” Maka Allah akan menghakimi di antara kamu semua pada hari kiamat; dan Allah tidak sekali-kali akan memberi jalan kepada orang-orang kafir untuk membinasakan orang-orang yang beriman.', FALSE, NULL, NULL, 101, 5, 40, 81, FALSE, 0, NULL),
(4, 142, 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا', 'إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَىٰ يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا', NULL, 'Indeed, the hypocrites [think to] deceive Allāh, but He is deceiving them. And when they stand for prayer, they stand lazily, showing [themselves to] the people and not remembering Allāh except a little,', 'Sesungguhnya orang-orang munafik itu melakukan tipu daya (terhadap ugama) Allah (dengan perbuatan pura-pura beriman sedang mereka kafir pada batinnya), dan Allah pula tetap membalas tipu daya mereka (dengan membiarkan mereka dalam keadaan munafik). Mereka pula apabila berdiri hendak sembahyang, mereka berdiri dengan malas. Mereka (hanya bertujuan) riak (memperlihatkan sembahyangnya) kepada manusia (supaya disangka bahawa mereka orang yang beriman), dan mereka pula tidak mengingati Allah (dengan mengerjakan sembahyang) melainkan sedikit sekali (jarang-jarang).', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 143, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَا إِلَىٰ هَٰؤُلَاءِ وَلَا إِلَىٰ هَٰؤُلَاءِ وَمَن يُضْلِلِ اللَّهُ فَلَن تَجِدَ لَهُ سَبِيلًا', NULL, 'Wavering between them, [belonging] neither to these [i.e., the believers] nor to those [i.e., the disbelievers]. And whoever Allāh sends astray - never will you find for him a way.', 'Mereka berkeadaan “muzabzab” (tidak mempunyai pendirian yang tetap) antara (iman dan kufur) itu; mereka tidak berpihak terus kepada golongan (kafir) dan tidak pula berpihak kepada golongan (yang beriman). Dan sesiapa yang disesatkan oleh Allah, maka engkau (wahai Muhammad) tidak sekali-kali akan mendapat jalan untuk menyelamatkannya.', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 144, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًا مُّبِينًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا الْكَافِرِينَ أَوْلِيَاءَ مِن دُونِ الْمُؤْمِنِينَ أَتُرِيدُونَ أَن تَجْعَلُوا لِلَّهِ عَلَيْكُمْ سُلْطَانًا مُّبِينًا', NULL, 'O you who have believed, do not take the disbelievers as allies instead of the believers. Do you wish to give Allāh against yourselves a clear case?', 'Wahai orang-orang yang beriman, janganlah kamu mengambil orang-orang kafir menjadi teman rapat dengan meninggalkan orang-orang yang beriman. Adakah kamu hendak mengadakan alasan yang terang nyata bagi Allah untuk (menyeksa) kamu?', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 145, 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', 'إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', NULL, 'Indeed, the hypocrites will be in the lowest depths of the Fire - and never will you find for them a helper -', 'Sesungguhnya orang-orang munafik itu ditempatkan pada tingkatan yang terkebawah sekali dari (lapisan-lapisan dalam) neraka. Dan engkau tidak sekali-kali akan mendapat sesiapa pun yang boleh menolong mereka.', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 146, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا', 'إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَاعْتَصَمُوا بِاللَّهِ وَأَخْلَصُوا دِينَهُمْ لِلَّهِ فَأُولَٰئِكَ مَعَ الْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ اللَّهُ الْمُؤْمِنِينَ أَجْرًا عَظِيمًا', NULL, 'Except for those who repent, correct themselves, hold fast to Allāh, and are sincere in their religion for Allāh, for those will be with the believers. And Allāh is going to give the believers a great reward.', 'Kecuali orang-orang yang bertaubat (dari perbuatan munafik itu) dan memperbaiki amalan mereka (yang salah), dan mereka pula berpegang teguh kepada (ugama) Allah, serta mengerjakan ugama mereka dengan ikhlas kerana Allah, maka mereka yang demikian itu ditempatkan bersama-sama orang-orang yang beriman (di dalam Syurga); dan Allah akan memberikan orang-orang yang beriman itu pahala yang amat besar.', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 147, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا', 'مَّا يَفْعَلُ اللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَآمَنتُمْ وَكَانَ اللَّهُ شَاكِرًا عَلِيمًا', NULL, 'What would Allāh do with [i.e., gain from] your punishment if you are grateful and believe? And ever is Allāh Appreciative and Knowing.', 'Apa gunanya Allah menyeksa kamu sekiranya kamu bersyukur (akan nikmatNya) serta kamu beriman (kepadaNya)? Dan (ingatlah) Allah sentiasa Membalas dengan sebaik-baiknya (akan orang-orang yang bersyukur kepadaNya), lagi Maha Mengetahui (akan hal keadaan mereka).', FALSE, NULL, NULL, 101, 5, 40, 82, FALSE, 0, NULL),
(4, 148, 'لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', 'لَّا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَن ظُلِمَ وَكَانَ اللَّهُ سَمِيعًا عَلِيمًا', NULL, 'Allāh does not like the public mention of evil except by one who has been wronged. And ever is Allāh Hearing and Knowing.', 'Allah tidak suka kepada perkataan-perkataan buruk yang dikatakan dengan berterus-terang (untuk mendedahkan kejahatan orang); kecuali oleh orang yang dianiayakan. Dan (ingatlah) Allah sentiasa Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 102, 6, 41, 82, FALSE, 0, NULL),
(4, 149, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا', 'إِن تُبْدُوا خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا عَن سُوءٍ فَإِنَّ اللَّهَ كَانَ عَفُوًّا قَدِيرًا', NULL, 'If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allāh is ever Pardoning and Competent.', 'Jika kamu melahirkan sesuatu kebaikan, atau menyembunyikannya, atau kamu memaafkan kesalahan (yang dilakukan terhadap kamu), maka sesungguhnya Allah adalah Maha Pemaaf lagi Maha Kuasa.', FALSE, NULL, NULL, 102, 6, 41, 82, FALSE, 0, NULL),
(4, 150, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', 'إِنَّ الَّذِينَ يَكْفُرُونَ بِاللَّهِ وَرُسُلِهِ وَيُرِيدُونَ أَن يُفَرِّقُوا بَيْنَ اللَّهِ وَرُسُلِهِ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا بَيْنَ ذَٰلِكَ سَبِيلًا', NULL, 'Indeed, those who disbelieve in Allāh and His messengers and wish to discriminate between Allāh and His messengers and say, "We believe in some and disbelieve in others," and wish to adopt a way in between -', 'Sesungguhnya orang-orang yang kufur ingkar kepada Allah dan Rasul-rasulNya, dan (orang-orang yang) hendak membeza-bezakan iman mereka di antara Allah dan Rasul-rasulNya, dan (orang-orang yang) berkata: “Kami beriman kepada setengah Rasul-rasul itu dan kufur ingkar kepada setengahnya yang lain”, serta bertujuan hendak mengambil jalan lain antara iman dan kufur itu:', FALSE, NULL, NULL, 102, 6, 41, 82, FALSE, 0, NULL),
(4, 151, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'أُولَٰئِكَ هُمُ الْكَافِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَافِرِينَ عَذَابًا مُّهِينًا', NULL, 'Those are the disbelievers, truly. And We have prepared for the disbelievers a humiliating punishment.', 'Mereka itulah orang-orang yang kafir dengan sebenar-benarnya. Dan Kami telah menyediakan bagi orang-orang kafir itu azab seksa yang menghina.', FALSE, NULL, NULL, 102, 6, 41, 82, FALSE, 0, NULL),
(4, 152, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'وَالَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ وَلَمْ يُفَرِّقُوا بَيْنَ أَحَدٍ مِّنْهُمْ أُولَٰئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'But they who believe in Allāh and His messengers and do not discriminate between any of them - to those He is going to give their rewards. And ever is Allāh Forgiving and Merciful.', 'Dan orang-orang yang beriman kepada Allah dan Rasul-rasulNya dan mereka pula tidak membeza-bezakan (imannya terhadap) seseorang pun di antara Rasul-rasul itu, (maka) mereka yang demikian, Allah akan memberi mereka pahala mereka. Dan (ingatlah) adalah Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 102, 6, 41, 82, FALSE, 0, NULL),
(4, 153, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًا مِّنَ ٱلسَّمَآءِ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًا مُّبِينًا', 'يَسْأَلُكَ أَهْلُ الْكِتَابِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَابًا مِّنَ السَّمَاءِ فَقَدْ سَأَلُوا مُوسَىٰ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوا أَرِنَا اللَّهَ جَهْرَةً فَأَخَذَتْهُمُ الصَّاعِقَةُ بِظُلْمِهِمْ ثُمَّ اتَّخَذُوا الْعِجْلَ مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ فَعَفَوْنَا عَن ذَٰلِكَ وَآتَيْنَا مُوسَىٰ سُلْطَانًا مُّبِينًا', NULL, 'The People of the Scripture ask you to bring down to them a book from the heaven. But they had asked of Moses [even] greater than that and said, "Show us Allāh outright," so the thunderbolt struck them for their wrongdoing. Then they took the calf [for worship] after clear evidences had come to them, and We pardoned that. And We gave Moses a clear authority.', 'Ahli Kitab (kaum Yahudi) meminta kepadamu (wahai Muhammad) supaya engkau menurunkan kepada mereka sebuah Kitab dari langit. (Janganlah engkau merasa pelik), kerana sesungguhnya mereka telah meminta kepada Nabi Musa lebih besar dari itu. Mereka berkata: “(Wahai Musa) perlihatkanlah Allah kepada kami dengan nyata (supaya kami dapat melihatNya dan percaya kepadaNya)”. Lalu mereka disambar oleh petir dengan sebab kezaliman mereka (menderhaka kepada Allah); kemudian mereka pula menyembah (patung) anak lembu sesudah datang kepada mereka keterangan-keterangan (mukjizat), lalu Kami maafkan mereka dari perbuatan yang sedemikian itu (ketika mereka bertaubat). Dan Kami telah memberi kepada Nabi Musa kekuasaan yang nyata (untuk mengalahkan kaum yang kafir itu).', FALSE, NULL, NULL, 102, 6, 41, 83, FALSE, 0, NULL),
(4, 154, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', 'وَرَفَعْنَا فَوْقَهُمُ الطُّورَ بِمِيثَاقِهِمْ وَقُلْنَا لَهُمُ ادْخُلُوا الْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا فِي السَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَاقًا غَلِيظًا', NULL, 'And We raised over them the mount for [refusal of] their covenant; and We said to them, "Enter the gate bowing humbly"; and We said to them, "Do not transgress on the sabbath"; and We took from them a solemn covenant.', 'Dan Kami telah mengangkat “Gunung Tursina” ke atas mereka disebabkan (mereka ingkar akan) perjanjian setia mereka (mematuhi hukum-hukum Taurat), dan Kami perintahkan mereka: “Masuklah kamu melalui pintu (negeri) itu dengan merendah diri” dan Kami juga perintahkan mereka: “Janganlah kamu melanggar perintah larangan yang ditentukan pada hari Sabtu”, dan Kami telah mengambil daripada mereka perjanjian setia yang teguh (yang mewajibkan mereka mengerjakan suruhan Allah dan meninggalkan laranganNya).', FALSE, NULL, NULL, 102, 6, 41, 83, FALSE, 0, NULL),
(4, 155, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', 'فَبِمَا نَقْضِهِم مِّيثَاقَهُمْ وَكُفْرِهِم بِآيَاتِ اللَّهِ وَقَتْلِهِمُ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌ بَلْ طَبَعَ اللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', NULL, 'And [We cursed them] for their breaking of the covenant and their disbelief in the signs of Allāh and their killing of the prophets without right and their saying, "Our hearts are wrapped" [i.e., sealed against reception]. Rather, Allāh has sealed them because of their disbelief, so they believe not, except for a few.', 'Maka (Kami laknatkan mereka) dengan sebab mereka mencabuli perjanjian setia mereka, dan mereka kufur ingkar akan ayat-ayat keterangan Allah, dan mereka pula membunuh Nabi-nabi dengan tiada sesuatu alasan yang benar, dan mereka juga mengatakan: “Hati kami tertutup (tidak dapat menerima ajaran Islam yang dibawa oleh Nabi Muhammad)”. (Sebenarnya hati mereka tidak tertutup), bahkan Allah telah memeteraikan hati mereka disebabkan kekufuran mereka. Oleh itu mereka tidak beriman kecuali sedikit sahaja (di antaranya).', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 156, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًا', 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَانًا عَظِيمًا', NULL, 'And [We cursed them] for their disbelief and their saying against Mary a great slander', 'Demikian juga (Kami laknatkan mereka) dangan sebab kekufuran mereka dan tuduhan mereka terhadap Maryam (dengan tuduhan yang amat dustanya.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 157, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ وَمَا قَتَلُوهُ يَقِينًۢا', 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا الْمَسِيحَ عِيسَى ابْنَ مَرْيَمَ رَسُولَ اللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِيهِ لَفِي شَكٍّ مِّنْهُ مَا لَهُم بِهِ مِنْ عِلْمٍ إِلَّا اتِّبَاعَ الظَّنِّ وَمَا قَتَلُوهُ يَقِينًا', NULL, 'And [for] their saying, "Indeed, we have killed the Messiah, Jesus the son of Mary, the messenger of Allāh." And they did not kill him, nor did they crucify him; but [another] was made to resemble him to them. And indeed, those who differ over it are in doubt about it. They have no knowledge of it except the following of assumption. And they did not kill him, for certain.', 'Dan juga (disebabkan) dakwaan mereka dengan mengatakan: “Sesungguhnya kami telah membunuh Al-Masih Isa Ibni Maryam, Rasul Allah”. Padahal mereka tidak membunuhnya dan tidak memalangnya (di kayu palang - salib), tetapi diserupakan bagi mereka (orang yang mereka bunuh itu seperti Nabi Isa). Dan Sesungguhnya orang-orang yang telah berselisih faham, mengenai Nabi Isa, sebenarnya mereka berada dalam keadaan syak (ragu-ragu) tentang menentukan (pembunuhannya). Tiada sesuatu pengetahuan pun bagi mereka mengenainya selain daripada mengikut sangkaan semata-mata; dan mereka tidak membunuhnya dengan yakin.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 158, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'بَل رَّفَعَهُ اللَّهُ إِلَيْهِ وَكَانَ اللَّهُ عَزِيزًا حَكِيمًا', NULL, 'Rather, Allāh raised him to Himself. And ever is Allāh Exalted in Might and Wise.', 'Bahkan Allah telah mengangkat Nabi Isa kepadaNya; dan adalah Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 159, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', 'وَإِن مِّنْ أَهْلِ الْكِتَابِ إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ وَيَوْمَ الْقِيَامَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', NULL, 'And there is none from the People of the Scripture but that he will surely believe in him [i.e., Jesus] before his death. And on the Day of Resurrection he will be against them a witness.', 'Dan tidak ada seorang pun dari kalangan ahli Kitab melainkan ia akan beriman kepada Nabi Isa sebelum matinya dan pada hari kiamat kelak Nabi Isa akan menjadi saksi terhadap mereka.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 160, 'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا', 'فَبِظُلْمٍ مِّنَ الَّذِينَ هَادُوا حَرَّمْنَا عَلَيْهِمْ طَيِّبَاتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ اللَّهِ كَثِيرًا', NULL, 'For wrongdoing on the part of the Jews, We made unlawful for them [certain] good foods which had been lawful to them, and for their averting from the way of Allāh many [people],', 'Maka disebabkan kezaliman yang amat besar dari perbuatan orang-orang Yahudi, Kami haramkan atas mereka makanan yang baik-baik yang pernah dihalalkan bagi mereka, dan disebabkan mereka banyak menghalang manusia dari jalan Allah.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 161, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', 'وَأَخْذِهِمُ الرِّبَا وَقَدْ نُهُوا عَنْهُ وَأَكْلِهِمْ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَأَعْتَدْنَا لِلْكَافِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', NULL, 'And [for] their taking of usury while they had been forbidden from it, and their consuming of the people''s wealth unjustly. And We have prepared for the disbelievers among them a painful punishment.', 'Dan juga (disebabkan) mereka mengambil riba padahal mereka telah dilarang melakukannya, dan (disebabkan) mereka memakan harta orang dengan jalan yang salah (tipu, judi dan sebagainya). Dan (ingatlah) Kami telah menyediakan bagi orang-orang yang kafir di antara mereka, azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 162, 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', 'لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَالْمُقِيمِينَ الصَّلَاةَ وَالْمُؤْتُونَ الزَّكَاةَ وَالْمُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أُولَٰئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', NULL, 'But those firm in knowledge among them and the believers believe in what has been revealed to you, [O Muḥammad], and what was revealed before you. And the establishers of prayer [especially] and the givers of zakāh and the believers in Allāh and the Last Day - those We will give a great reward.', 'Tetapi orang-orang yang teguh serta mendalam ilmu pengetahuannya di antara mereka dan orang-orang yang beriman, sekaliannya beriman dengan apa yang telah diturunkan kepadamu (Al-Quran), dan kepada apa yang telah diturunkan dahulu daripadamu, - khasnya orang-orang yang mendirikan sembahyang, dan orang-orang yang menunaikan zakat, serta yang beriman kepada Allah dan hari akhirat; mereka itulah yang Kami akan berikan kepadanya pahala (balasan) yang amat besar.', FALSE, NULL, NULL, 103, 6, 41, 83, FALSE, 0, NULL),
(4, 163, 'إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'إِنَّا أَوْحَيْنَا إِلَيْكَ كَمَا أَوْحَيْنَا إِلَىٰ نُوحٍ وَالنَّبِيِّينَ مِن بَعْدِهِ وَأَوْحَيْنَا إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَارُونَ وَسُلَيْمَانَ وَآتَيْنَا دَاوُودَ زَبُورًا', NULL, 'Indeed, We have revealed to you, [O Muḥammad], as We revealed to Noah and the prophets after him. And We revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon; and to David We gave the book [of Psalms].', 'Sungguhnya Kami telah memberikan wahyu kepadamu (wahai Muhammad), sebagaimana Kami telah memberikan wahyu kepada Nabi Nuh, dan Nabi-nabi yang diutus kemudian daripadanya; dan Kami juga telah memberikan wahyu kepada Nabi Ibrahim, dan Nabi Ismail, dan Nabi Ishak, dan Nabi Yaakub, serta Nabi-nabi keturunannya, dan Nabi Isa, dan Nabi Ayub, dan Nabi Yunus, dan Nabi Harun, dan Nabi Sulaiman; dan juga Kami telah memberikan kepada Nabi Daud: Kitab Zabur.', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 164, 'وَرُسُلًا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا', 'وَرُسُلًا قَدْ قَصَصْنَاهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ اللَّهُ مُوسَىٰ تَكْلِيمًا', NULL, 'And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allāh spoke to Moses with [direct] speech.', 'Dan (Kami telah mengutuskan) beberapa orang Rasul yang telah Kami ceritakan kepadamu dahulu sebelum ini, dan Rasul-rasul yang tidak Kami ceritakan hal mereka kepadamu. Dan Allah telah berkata-kata kepada Nabi Musa dengan kata-kata (secara langsung, tidak ada perantaraan).', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 165, 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللَّهِ حُجَّةٌ بَعْدَ الرُّسُلِ وَكَانَ اللَّهُ عَزِيزًا حَكِيمًا', NULL, '[We sent] messengers as bringers of good tidings and warners so that mankind will have no argument against Allāh after the messengers. And ever is Allāh Exalted in Might and Wise.', 'Rasul-rasul (yang Kami telah utuskan itu semuanya) pembawa khabar gembira (kepada orang-orang yang beriman), dan pembawa amaran (kepada orang-orang yang kafir dan yang berbuat maksiat), supaya tidak ada bagi manusia sesuatu hujah (atau sebarang alasan untuk berdalih pada hari kiamat kelak) terhadap Allah sesudah mengutuskan Rasul-rasul itu. Dan (ingatlah) Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 166, 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ أَنزَلَهُۥ بِعِلْمِهِۦ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'لَّٰكِنِ اللَّهُ يَشْهَدُ بِمَا أَنزَلَ إِلَيْكَ أَنزَلَهُ بِعِلْمِهِ وَالْمَلَائِكَةُ يَشْهَدُونَ وَكَفَىٰ بِاللَّهِ شَهِيدًا', NULL, 'But Allāh bears witness to that which He has revealed to you. He has sent it down with His knowledge, and the angels bear witness [as well]. And sufficient is Allāh as Witness.', '(Orang-orang kafir itu tidak mahu mengakui apa yang telah diturunkan Allah kepadamu wahai Muhammad), tetapi Allah sentiasa menjadi saksi akan kebenaran Al-Quran yang telah diturunkanNya kepadamu. Allah menurunkannya dengan ilmuNya, dan malaikat juga turut menjadi saksi. Dan cukuplah Allah menjadi saksi (akan kebenaran Al-Quran ini).', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 167, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', 'إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ قَدْ ضَلُّوا ضَلَالًا بَعِيدًا', NULL, 'Indeed, those who disbelieve and avert [people] from the way of Allāh have certainly gone far astray.', 'Sesungguhnya orang-orang yang kafir serta menghalang orang-orang lain dari jalan Allah (ugama Islam), sebenarnya mereka telah sesat dengan kesesatan yang amat jauh.', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 168, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', 'إِنَّ الَّذِينَ كَفَرُوا وَظَلَمُوا لَمْ يَكُنِ اللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', NULL, 'Indeed, those who disbelieve and commit wrong [or injustice] - never will Allāh forgive them, nor will He guide them to a path,', 'Sesungguhnya orang-orang yang kafir serta berlaku zalim, Allah tidak sekali-kali akan mengampunkan mereka dan tidak akan menunjukkan jalan kepada mereka:', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 169, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'إِلَّا طَرِيقَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا', NULL, 'Except the path of Hell; they will abide therein forever. And that, for Allāh, is [always] easy.', 'Selain dari jalan neraka jahanam, yang mereka akan kekal di dalamnya selama-lamanya; dan balasan yang demikian itu adalah mudah bagi Allah.', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 170, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الرَّسُولُ بِالْحَقِّ مِن رَّبِّكُمْ فَآمِنُوا خَيْرًا لَّكُمْ وَإِن تَكْفُرُوا فَإِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', NULL, 'O mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allāh belongs whatever is in the heavens and earth. And ever is Allāh Knowing and Wise.', 'Wahai sekalian umat manusia! Sesungguhnya telah datang kepada kamu Rasul Allah (Muhammad s.a.w) dengan membawa kebenaran dari Tuhan kamu, maka berimanlah kamu (kerana yang demikian itu) amatlah baiknya bagi kamu. Dan jika kamu kufur ingkar (maka kekufuran kamu itu tidak mendatangkan kerugian apa-apa kepada Allah), kerana sesungguhnya bagi Allah jualah segala yang ada di langit dan di bumi; dan Allah sentiasa Mengetahui lagi Maha Bijaksana.', FALSE, NULL, NULL, 104, 6, 42, 84, FALSE, 0, NULL),
(4, 171, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ٱنتَهُوا۟ خَيْرًا لَّكُمْ إِنَّمَا ٱللَّهُ إِلَٰهٌ وَٰحِدٌ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ فَآمِنُوا بِاللَّهِ وَرُسُلِهِ وَلَا تَقُولُوا ثَلَاثَةٌ انتَهُوا خَيْرًا لَّكُمْ إِنَّمَا اللَّهُ إِلَٰهٌ وَاحِدٌ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَىٰ بِاللَّهِ وَكِيلًا', NULL, 'O People of the Scripture, do not commit excess in your religion or say about Allāh except the truth. The Messiah, Jesus the son of Mary, was but a messenger of Allāh and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allāh and His messengers. And do not say, "Three"; desist - it is better for you. Indeed, Allāh is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allāh as Disposer of affairs.', 'Wahai Ahli kitab (Yahudi dan Nasrani)! Janganlah kamu melampaui batas dalam perkara ugama kamu, dan janganlah kamu mengatakan sesuatu terhadap Allah melainkan yang benar; sesungguhnya Al Masih Isa ibni Maryam itu hanya seorang pesuruh Allah dan Kalimah Allah yang telah disampaikanNya kepada Maryam, dan (ia juga tiupan) roh daripadaNya. Maka berimanlah kamu kepada Allah dan Rasul-rasulNya, dan janganlah kamu mengatakan: “(Tuhan itu) tiga”. Berhentilah (daripada mengatakan yang demikian), supaya menjadi kebaikan bagi kamu. Hanyasanya Allah ialah Tuhan Yang Maha Esa, Maha Suci Allah daripada mempunyai anak. Bagi Allah jualah segala yang ada di langit dan yang ada di bumi. Dan cukuplah menjadi Pengawal (Yang Mentadbirkan sekalian makhlukNya).', FALSE, NULL, NULL, 105, 6, 42, 84, FALSE, 0, NULL),
(4, 172, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', 'لَّن يَسْتَنكِفَ الْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا الْمَلَائِكَةُ الْمُقَرَّبُونَ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', NULL, 'Never would the Messiah disdain to be a servant of Allāh, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together.', '(Nabi Isa) Al-Masih tidak sekali-kali enggan dan angkuh daripada menjadi hamba bagi Allah, demikian juga (sikap) malaikat yang sentiasa berdamping (dengan Allah). Dan sesiapa yang enggan dan angkuh daripada beribadat (menyembah dan memperhambakan diri) kepada Allah, serta ia berlaku sombong takbur, maka Allah akan menghimpunkan mereka semua kepadaNya.', FALSE, NULL, NULL, 105, 6, 42, 85, FALSE, 0, NULL),
(4, 173, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِ وَأَمَّا الَّذِينَ اسْتَنكَفُوا وَاسْتَكْبَرُوا فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا', NULL, 'And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allāh any protector or helper.', 'Sesudah itu, orang-orang yang beriman beramal soleh, Allah akan menyempurnakan bagi mereka pahala (balasan) mereka, dan Ia akan menambahkan lagi limpah kurniaNya kepada mereka. Sebaliknya orang-orang yang enggan beribadat kepada Allah dan berlaku sombong takbur, maka Allah akan menyeksa mereka dengan azab seksa yang tidak terperi sakitnya, dan mereka pula tidak akan memperoleh sesiapa pun - yang lain dari Allah - yang akan menjadi pelindung atau penolong bagi mereka.', FALSE, NULL, NULL, 105, 6, 42, 85, FALSE, 0, NULL),
(4, 174, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا', 'يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُم بُرْهَانٌ مِّن رَّبِّكُمْ وَأَنزَلْنَا إِلَيْكُمْ نُورًا مُّبِينًا', NULL, 'O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light.', 'Wahai sekalian umat manusia! Sesungguhnya telah datang kepada kamu: Bukti dari Tuhan kamu, dan Kami pula telah menurunkan kepada kamu (Al-Quran sebagai) Nur (cahaya) yang menerangi (segala apa jua yang membawa kejayaan di dunia ini dan kebahagiaan yang kekal di akhirat kelak).', FALSE, NULL, NULL, 105, 6, 42, 85, FALSE, 0, NULL),
(4, 175, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا', 'فَأَمَّا الَّذِينَ آمَنُوا بِاللَّهِ وَاعْتَصَمُوا بِهِ فَسَيُدْخِلُهُمْ فِي رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَاطًا مُّسْتَقِيمًا', NULL, 'So those who believe in Allāh and hold fast to Him - He will admit them to mercy from Himself and bounty and guide them to Himself on a straight path.', 'Oleh itu, orang-orang yang beriman kepada Allah dan berpegang teguh kepada (ajaran Al-Quran) ini, maka Allah akan memasukkan mereka ke dalam rahmatNya (yang khas iaitu Syurga) dan limpah kurniaNya (yang tidak terkira), dan Allah akan menunjukkan mereka ke jalan yang lurus (jalan ugama Islam), yang membawa kepadaNya.', FALSE, NULL, NULL, 105, 6, 42, 85, FALSE, 0, NULL),
(4, 176, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَا إِن لَّمْ يَكُن لَّهَا وَلَدٌ فَإِن كَانَتَا اثْنَتَيْنِ فَلَهُمَا الثُّلُثَانِ مِمَّا تَرَكَ وَإِن كَانُوا إِخْوَةً رِّجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ يُبَيِّنُ اللَّهُ لَكُمْ أَن تَضِلُّوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'They request from you a [legal] ruling. Say, "Allāh gives you a ruling concerning one having neither descendants nor ascendants [as heirs]." If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two thirds of what he left. If there are both brothers and sisters, the male will have the share of two females. Allāh makes clear to you [His law], lest you go astray. And Allāh is Knowing of all things.', 'Mereka (orang-orang Islam umatmu) meminta fatwa kepadamu (Wahai Muhammad mengenai masalah Kalaalah). Katakanlah: “Allah memberi fatwa kepada kamu di dalam perkara Kalaalah itu, iaitu jika seseorang mati yang tidak mempunyai anak dan ia mempunyai seorang saudara perempuan, maka bagi saudara perempuan itu satu perdua dari harta yang ditinggalkan oleh si mati; dan ia pula (saudara lelaki itu) mewarisi (semua harta) saudara perempuannya, jika saudara perempuannya tidak mempunyai anak. Kalau pula saudara perempuannya itu dua orang, maka keduanya mendapat dua pertiga dari harta yang di tinggalkan oleh si mati. Dan sekiranya mereka (saudara-saudaranya itu) ramai, lelaki dan perempuan, maka bahagian seorang lelaki menyamai bahagian dua orang perempuan”. Allah menerangkan (hukum ini) kepada kamu supaya kamu tidak sesat. Dan (ingatlah) Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 106, 6, 42, 85, FALSE, 0, NULL),
(5, 1, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَـٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', 'يا ايها الذين امنوا اوفوا بالعقود احلت لكم بهيمة الانعام الا ما يتلى عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد', NULL, 'O you who have believed, fulfill [all] contracts. Lawful for you are the animals of grazing livestock except for that which is recited to you [in this Qur’ān] - hunting not being permitted while you are in the state of iḥrām. Indeed, Allāh ordains what He intends.', 'Wahai orang-orang yang beriman, penuhi serta sempurnakanlah perjanjian-perjanjian. Dihalalkan bagi kamu (memakan) binatang-binatang ternak (dan sebagainya), kecuali apa yang akan dibacakan (tentang haramnya) kepada kamu. (Halalnya binatang-binatang ternak dan sebagainya itu) tidak pula bererti kamu boleh menghalalkan perburuan ketika kamu dalam keadaan berihram. Sesungguhnya Allah menetapkan hukum apa yang Ia kehendaki.', FALSE, NULL, NULL, 106, 6, 43, 86, FALSE, 23, NULL),
(5, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'يا ايها الذين امنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا امين البيت الحرام يبتغون فضلا من ربهم ورضوانا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا على البر والتقوى ولا تعاونوا على الاثم والعدوان واتقوا الله ان الله شديد العقاب', NULL, 'O you who have believed, do not violate the rites of Allāh or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of iḥrām, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Ḥarām lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allāh; indeed, Allāh is severe in penalty.', 'Wahai orang-orang yang beriman, janganlah kamu ingat halal membuat sesuka hati mengenai syiar-syiar ugama Allah, dan mengenai bulan-bulan yang dihormati, dan mengenai binatang-binatang yang dihadiahkan (ke Makkah untuk korban), dan mengenai kalong-kalong binatang hadiah itu, dan mengenai orang-orang yang menuju ke Baitullah Al-Haraam, yang bertujuan mencari limpah kurnia dari Tuhan mereka (dengan jalan perniagaan) dan mencari keredaanNya (dengan mengerjakan ibadat Haji di Tanah Suci); dan apabila kamu telah selesai dari ihram maka bolehlah kamu berburu. Dan jangan sekali-kali kebencian kamu kepada suatu kaum kerana mereka pernah menghalangi kamu dari masjid Al-Haraam itu - mendorong kamu menceroboh. Dan hendaklah kamu bertolong-tolongan untuk membuat kebajikan dan bertaqwa, dan janganlah kamu bertolong-tolongan pada melakukan dosa (maksiat) dan pencerobohan. Dan bertaqwalah kepada Allah, kerana sesungguhnya Allah Maha Berat azab seksaNya (bagi sesiapa yang melanggar perintahNya).', FALSE, NULL, NULL, 106, 6, 43, 86, FALSE, 52, NULL),
(5, 3, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَـٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَـٰمَ دِينًا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ ۙ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'حرمت عليكم الميتة والدم ولحم الخنزير وما اهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما اكل السبع الا ما ذكيتم وما ذبح على النصب وان تستقسموا بالازلام ذلكم فسق اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلام دينا فمن اضطر في مخمصة غير متجانف لاثم فان الله غفور رحيم', NULL, 'Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allāh, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islām as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allāh is Forgiving and Merciful.', 'Diharamkan kepada kamu (memakan) bangkai (binatang yang tidak disembelih), dan darah (yang keluar mengalir), dan daging babi (termasuk semuanya), dan binatang-binatang yang disembelih kerana yang lain dari Allah, dan yang mati tercekik, dan yang mati dipukul, dan yang mati jatuh dari tempat yang tinggi, dan yang mati ditanduk, dan yang mati dimakan binatang buas, kecuali yang sempat kamu sembelih (sebelum habis nyawanya), dan yang disembelih atas nama berhala; dan (diharamkan juga) kamu merenung nasib dengan undi batang-batang anak panah. Yang demikian itu adalah perbuatan fasik. Pada hari ini, orang-orang kafir telah putus asa (daripada memesongkan kamu) dari ugama kamu (setelah mereka melihat perkembangan Islam dan umatnya). Sebab itu janganlah kamu takut dan gentar kepada mereka, sebaliknya hendaklah kamu takut dan gentar kepadaKu. Pada hari ini, Aku telah sempurnakan bagi kamu ugama kamu, dan Aku telah cukupkan nikmatKu kepada kamu, dan Aku telah redakan Islam itu menjadi ugama untuk kamu. Maka sesiapa yang terpaksa kerana kelaparan (memakan benda-benda yang diharamkan) sedang ia tidak cenderung hendak melakukan dosa (maka bolehlah ia memakannya), kerana sesungguhnya Allah maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 107, 6, 43, 86, FALSE, 61, NULL),
(5, 4, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'يسالونك ماذا احل لهم قل احل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب', NULL, 'They ask you, [O Muḥammad], what has been made lawful for them. Say, "Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals which you train as Allāh has taught you. So eat of what they catch for you, and mention the name of Allāh upon it, and fear Allāh." Indeed, Allāh is swift in account.', 'Mereka bertanya kepadamu (wahai Muhammad): “Apakah (makanan) yang dihalalkan bagi mereka?” Bagi menjawabnya katakanlah: “Dihalalkan bagi kamu (memakan) yang lazat-lazat serta baik, dan (buruan yang ditangkap oleh) binatang-binatang pemburu yang telah kamu ajar (untuk berburu) mengikut cara pelatih-pelatih binatang pemburu. Kamu mengajar serta melatihnya (adab peraturan berburu) sebagaimana yang telah diajarkan Allah kepada kamu. Oleh itu makanlah dari apa yang mereka tangkap untuk kamu dan sebutlah nama Allah atasnya (ketika kamu melepaskannya berburu); dan bertaqwalah kepada Allah (dengan memelihara diri dari memakan yang diharamkan Allah); Sesungguhnya Allah Maha Cepat hitungan hisabNya”', FALSE, NULL, NULL, 107, 6, 43, 86, FALSE, 31, NULL),
(5, 5, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ ۖ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلْمُؤْمِنَـٰتِ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَـٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ', 'اليوم احل لكم الطيبات وطعام الذين اوتوا الكتاب حل لكم وطعامكم حل لهم والمحصنات من المؤمنات والمحصنات من الذين اوتوا الكتاب من قبلكم اذا اتيتموهن اجورهن محصنين غير مسافحين ولا متخذي اخدان ومن يكفر بالايمان فقد حبط عمله وهو في الاخرة من الخاسرين', NULL, 'This day [all] good foods have been made lawful, and the food of those who were given the Scripture is lawful for you and your food is lawful for them. And [lawful in marriage are] chaste women from among the believers and chaste women from among those who were given the Scripture before you, when you have given them their due compensation, desiring chastity, not unlawful sexual intercourse or taking [secret] lovers. And whoever denies the faith - his work has become worthless, and he, in the Hereafter, will be among the losers.', 'Pada masa ini dihalalkan bagi kamu (memakan makanan) yang lazat-lazat serta baik-baik. Dan makanan (sembelihan) orang-orang yang diberikan Kitab itu adalah halal bagi kamu, dan makanan (sembelihan) kamu adalah halal bagi mereka (tidak salah kamu memberi makan kepada mereka). Dan (dihalalkan kamu berkahwin) dengan perempuan-perempuan yang menjaga kehormatannya - di antara perempuan-perempuan yang beriman, dan juga perempuan-perempuan yang menjaga kehormatannya dari kalangan orang-orang yang diberikan Kitab dahulu daripada kamu apabila kamu beri mereka maskahwinnya, sedang kamu (dengan cara yang demikian), bernikah bukan berzina, dan bukan pula kamu mengambil mereka menjadi perempuan-perempuan simpanan. Dan sesiapa yang ingkar (akan syariat Islam) sesudah ia beriman, maka sesungguhnya gugurlah amalnya (yang baik) dan adalah ia pada hari akhirat kelak dari orang-orang yang rugi.', FALSE, NULL, NULL, 107, 6, 43, 86, FALSE, 43, NULL),
(5, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَـٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'يا ايها الذين امنوا اذا قمتم الى الصلاة فاغسلوا وجوهكم وايديكم الى المرافق وامسحوا برءوسكم وارجلكم الى الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضى او على سفر او جاء احد منكم من الغائط او لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون', NULL, 'O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janābah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allāh does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful.', 'Wahai orang-orang yang beriman, apabila kamu hendak mengerjakan sembahyang (padahal kamu berhadas kecil), maka (berwuduklah) iaitu basuhlah muka kamu, dan kedua belah tangan kamu meliputi siku, dan sapulah sebahagian dari kepala kamu, dan basuhlah kedua belah kaki kamu meliputi buku lali; dan jika kamu junub (berhadas besar) maka bersucilah dengan mandi wajib; dan jika kamu sakit (tidak boleh kena air), atau dalam pelayaran, atau salah seorang dari kamu datang dari tempat buang air, atau kamu sentuh perempuan, sedang kamu tidak mendapat air (untuk berwuduk dan mandi), maka hendaklah kamu bertayamum dengan tanah - debu yang bersih, iaitu: sapulah muka kamu dan kedua belah tangan kamu dengan tanah - debu itu. Allah tidak mahu menjadikan kamu menanggung sesuatu kesusahan (kepayahan), tetapi Ia berkehendak membersihkan (mensucikan) kamu dan hendak menyempurnakan nikmatNya kepada kamu, supaya kamu bersyukur.', FALSE, NULL, NULL, 108, 6, 43, 87, FALSE, 61, NULL),
(5, 7, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَـٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'واذكروا نعمة الله عليكم وميثاقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور', NULL, 'And remember the favor of Allāh upon you and His covenant with which He bound you when you said, "We hear and we obey"; and fear Allāh. Indeed, Allāh is Knowing of that within the breasts.', 'Dan kenanglah nikmat Allah (yang telah dikurniakanNya) kepada kamu serta ingatlah perjanjianNya yang telah diikatNya dengan kamu, ketika kamu berkata: “Kami dengar dan kami taat (akan perintah-perintah Allah dan RasulNya)” Dan bertaqwalah kamu kepada Allah, kerana sesungguhnya Allah Maha Mengetahui akan segala (isi hati) yang ada di dalam dada.', FALSE, NULL, NULL, 108, 6, 43, 87, FALSE, 19, NULL),
(5, 8, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'يا ايها الذين امنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنان قوم على الا تعدلوا اعدلوا هو اقرب للتقوى واتقوا الله ان الله خبير بما تعملون', NULL, 'O you who have believed, be persistently standing firm for Allāh, witnesses in justice, and do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. And fear Allāh; indeed, Allāh is [fully] Aware of what you do.', 'Wahai orang-orang yang beriman, hendaklah kamu semua sentiasa menjadi orang-orang yang menegakkan keadilan kerana Allah, lagi menerangkan kebenaran; dan jangan sekali-kali kebencian kamu terhadap sesuatu kaum itu mendorong kamu kepada tidak melakukan keadilan. Hendaklah kamu berlaku adil (kepada sesiapa jua) kerana sikap adil itu lebih hampir kepada taqwa. Dan bertaqwalah kepada Allah, sesungguhnya Allah Maha Mengetahui dengan mendalam akan apa yang kamu lakukan.', FALSE, NULL, NULL, 108, 6, 43, 87, FALSE, 26, NULL),
(5, 9, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۙ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', 'وعد الله الذين امنوا وعملوا الصالحات لهم مغفرة واجر عظيم', NULL, 'Allāh has promised those who believe and do righteous deeds [that] for them there is forgiveness and great reward.', 'Allah menjanjikan kepada orang-orang yang beriman dan beramal soleh, mereka akan beroleh keampunan dan pahala yang besar.', FALSE, NULL, NULL, 108, 6, 43, 87, FALSE, 10, NULL),
(5, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', 'والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم', NULL, 'But those who disbelieve and deny Our signs - those are the companions of Hellfire.', 'Dan orang-orang yang kafir serta mendustakan ayat-ayat Kami (Al-Quran), merekalah ahli neraka.', FALSE, NULL, NULL, 109, 6, 43, 87, FALSE, 7, NULL),
(5, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'يا ايها الذين امنوا اذكروا نعمت الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلى الله فليتوكل المؤمنون', NULL, 'O you who have believed, remember the favor of Allāh upon you when a people determined to extend their hands [in aggression] against you, but He withheld their hands from you; and fear Allāh. And upon Allāh let the believers rely.', 'Wahai orang-orang yang beriman, kenanglah nikmat Allah (yang telah dikurniakanNya) kepada kamu ketika kaum (kafir yang memusuhi kamu) hendak menghulurkan tangannya (untuk menyerang kamu), lalu Allah menahan tangan mereka daripada (menyerang) kamu. Oleh itu, bertaqwalah kamu kepada Allah; dan kepada Allah jualah (sesudah bertaqwa itu) hendaklah orang-orang yang beriman berserah diri.', FALSE, NULL, NULL, 109, 6, 43, 87, FALSE, 23, NULL),
(5, 12, '۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'ولقد اخذ الله ميثاق بني اسرائيل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لئن اقمتم الصلاة واتيتم الزكاة وامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سيئاتكم ولادخلنكم جنات تجري من تحتها الانهار فمن كفر بعد ذلك منكم فقد ضل سواء السبيل', NULL, 'And Allāh had already taken a covenant from the Children of Israel, and We delegated from among them twelve leaders. And Allāh said, "I am with you. If you establish prayer and give zakāh and believe in My messengers and support them and loan Allāh a goodly loan, I will surely remove from you your misdeeds and admit you to gardens beneath which rivers flow. But whoever of you disbelieves after that has certainly strayed from the soundness of the way."', 'Dan demi sesungguhnya! Allah telah mengambil perjanjian setia Bani Israil (supaya mereka menjunjung perintahNya dan menjauhi laranganNya), dan Kami telah utuskan dari kalangan mereka dua belas ketua (untuk memimpin golongan masing-masing); dan Allah berfirman (kepada mereka): “Bahawa Aku adalah beserta kamu (memerhati segala-galanya). Demi sesungguhnya jika kamu dirikan sembahyang, serta kamu tunaikan zakat, dan kamu beriman dengan segala Rasul (utusanku) serta menolong bantu mereka (dalam menegakkan ugama Allah), dan kamu pinjamkan Allah (dengan sedekah dan berbuat baik pada jalanNya) secara pinjaman yang baik (bukan kerana riak dan mencari keuntungan dunia), sudah tentu Aku akan ampunkan dosa-dosa kamu, dan Aku akan masukkan kamu ke dalam Syurga yang mengalir di bawahnya beberapa sungai. Oleh itu, sesiapa yang kufur ingkar di antara kamu sesudah yang demikian, maka sesungguhnya sesatlah ia dari jalan yang betul”', FALSE, NULL, NULL, 109, 6, 44, 88, FALSE, 45, NULL),
(5, 13, 'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ لَعَنَّـٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَـٰسِيَةً ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'فبما نقضهم ميثاقهم لعناهم وجعلنا قلوبهم قاسية يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع على خائنة منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين', NULL, 'So for their breaking of the covenant We cursed them and made their hearts hardened. They distort words from their [proper] places [i.e., usages] and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allāh loves the doers of good.', 'Maka dengan sebab mereka mencabuli perjanjian setia mereka, Kami laknatkan mereka, dan Kami jadikan hati mereka keras membatu (tidak mahu menerima kebenaran). Mereka sentiasa mengubah Kalimah-kalimah (yang ada di dalam kitab Taurat dengan memutarnya) dari tempat-tempatnya (dan maksudnya) yang sebenar, dan mereka melupakan (meninggalkan) sebahagian dari apa yang diperingatkan mereka mereka dengannya. Dan engkau (wahai Muhammad) sentiasa dapat melihat perbuatan khianat yang mereka lakukan, kecuali sedikit dari mereka (yang tidak berlaku khianat). Oleh itu, maafkanlah mereka (jika mereka sedia bertaubat) dan janganlah dihiraukan, kerana sesungguhnya Allah suka kepada orang-orang yang berusaha supaya baik amalannya.', FALSE, NULL, NULL, 109, 6, 44, 88, FALSE, 32, NULL),
(5, 14, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰٓ أَخَذْنَا مِيثَـٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 'ومن الذين قالوا انا نصارى اخذنا ميثاقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوة والبغضاء الى يوم القيامة وسوف ينبئهم الله بما كانوا يصنعون', NULL, 'And from those who say, "We are Christians" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allāh is going to inform them about what they used to do.', 'Dan di antara orang-orang yang berkata: “Bahawa kami ini orang-orang Nasrani”, Kami juga telah mengambil perjanjian setia mereka, maka mereka juga melupakan (meninggalkan) sebahagian dari apa yang diperingatkan mereka dengannya, lalu Kami tanamkan perasaan permusuhan dan kebencian di antara mereka, sampai ke hari kiamat; dan Allah akan memberitahu mereka dengan apa yang telah mereka kerjakan.', FALSE, NULL, NULL, 110, 6, 44, 88, FALSE, 25, NULL),
(5, 15, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَـٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَـٰبٌ مُّبِينٌ', 'يا اهل الكتاب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتاب ويعفو عن كثير قد جاءكم من الله نور وكتاب مبين', NULL, 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allāh a light and a clear Book [i.e., the Qur’ān]', 'Wahai Ahli Kitab! Sesungguhnya telah datang kepada kamu Rasul Kami (Muhammad, s.a.w) dengan menerangkan kepada kamu banyak dari (keterangan-keterangan dan hukum-hukum) yang telah kamu sembunyikan dari Kitab Suci, dan ia memaafkan kamu (dengan tidak mendedahkan) banyak perkara (yang kamu sembunyikan). Sesungguhnya telah datang kepada kamu cahaya kebenaran (Nabi Muhammad) dari Allah, dan sebuah Kitab (Al-Quran) yang jelas nyata keterangannya.', FALSE, NULL, NULL, 110, 6, 44, 88, FALSE, 23, NULL),
(5, 16, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'يهدي به الله من اتبع رضوانه سبل السلام ويخرجهم من الظلمات الى النور باذنه ويهديهم الى صراط مستقيم', NULL, 'By which Allāh guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.', 'Dengan (Al-Quran) itu Allah menunjukkan jalan-jalan keselamatan serta kesejahteraan kepada sesiapa yang mengikut keredaanNya, dan (dengannya) Tuhan keluarkan mereka dari gelap-gelita (kufur) kepada cahaya (iman) yang terang-benderang, dengan izinNya; dan (dengannya juga) Tuhan menunjukkan mereka ke jalan yang lurus.', FALSE, NULL, NULL, 110, 6, 44, 88, FALSE, 18, NULL),
(5, 17, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيئا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السماوات والارض وما بينهما يخلق ما يشاء والله على كل شيء قدير', NULL, 'They have certainly disbelieved who say that Allāh is Christ, the son of Mary. Say, "Then who could prevent Allāh at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allāh belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allāh is over all things competent.', 'Demi sesungguhnya, kafirlah orang-orang yang berkata: “Bahawasanya Allah ialah Al-Masih Ibni Maryam) katakanlah (wahai Muhammad): “(Dakwaan itu tidak benar) kerana siapakah yang dapat menahan (seksa) dari Allah sedikit jua pun kalau Ia mahu membinasakan Al-Masih Ibni Maryam beserta ibunya dan orang-orang yang ada di muka bumi semuanya?” Dan (ingatlah) bagi Allah jualah kuasa pemerintahan langit dan bumi dan segala yang ada di antara keduanya. Ia menciptakan apa jua yang dikehendakiNya. Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 110, 6, 44, 88, FALSE, 42, NULL),
(5, 18, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَـٰرَىٰ نَحْنُ أَبْنَـٰٓؤُا۟ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'وقالت اليهود والنصارى نحن ابناء الله واحباؤه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السماوات والارض وما بينهما واليه المصير', NULL, 'But the Jews and the Christians say, "We are the children of Allāh and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allāh belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.', 'Orang-orang Yahudi dan Nasrani berkata: “Kami adalah anak-anak Allah dan yang amat disayangiNya”. Katakanlah (wahai Muhammad): “(Kalau betul demikian), maka mengapakah Ia menyeksa kamu dengan sebab dosa-dosa kamu? (Sebenarnya bukanlah sebagaimana yang kamu dakwakan) bahkan kamu semuanya adalah manusia biasa di antara manusia-manusia lain yang diciptakanNya. Ia mengampunkan bagi sesiapa yang dikehendakiNya (menurut aturan serta hukum SyariatNya), demikian juga Ia menyeksa sesiapa yang dikehendakiNya. Dan (ingatlah) bagi Allah jualah kuasa pemerintahan langit dan bumi serta segala yang ada di antara keduanya, dan kepada Allah jualah tempat kembali”', FALSE, NULL, NULL, 111, 6, 44, 88, FALSE, 30, NULL),
(5, 19, 'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ ۖ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'يا اهل الكتاب قد جاءكم رسولنا يبين لكم على فترة من الرسل ان تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله على كل شيء قدير', NULL, 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allāh is over all things competent.', 'Wahai Ahli Kitab! Sesungguhnya telah datang kepada kamu Rasul kami (Muhammad, s.a.w) yang menerangkan kepada kamu (akan syariat Islam) ketika terputusnya (kedatangan) Rasul-rasul (yang diutus), supaya kamu tidak (berdalih) dengan berkata (pada hari kiamat): “Tidak datang kepada kami seorang (Rasul) pun pembawa berita gembira dan juga pembawa amaran (yang mengingatkan kami)”. Kerana sesungguhnya telah datang kepada kamu seorang (rasul) pembawa berita gembira dan juga pembawa amaran. Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 111, 6, 44, 88, FALSE, 28, NULL),
(5, 20, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ', 'واذ قال موسى لقومه يا قوم اذكروا نعمة الله عليكم اذ جعل فيكم انبياء وجعلكم ملوكا واتاكم ما لم يؤت احدا من العالمين', NULL, 'And [mention, O Muḥammad], when Moses said to his people, "O my people, remember the favor of Allāh upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.', 'Dan (ingatkanlah mereka wahai Muhammad), ketika Nabi Musa berkata kepada kaumnya: “Wahai kaumku! Kenanglah nikmat Allah (Yang diberikan) kepada kamu ketika Ia menjadikan dalam kalangan kamu beberapa orang Nabi, dan Ia menjadikan kamu bebas merdeka (setelah kamu diperhamba oleh Firaun dan orang-orangnya), dan Ia memberikan kepada kamu barang yang tidak pernah diberikan kepada seseorang pun dari umat-umat (yang ada pada masa itu)”.', FALSE, NULL, NULL, 111, 6, 44, 89, FALSE, 22, NULL),
(5, 21, 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'يَا قَوْمِ ادْخُلُوا الْأَرْضَ الْمُقَدَّسَةَ الَّتِي كَتَبَ اللَّهُ لَكُمْ وَلَا تَرْتَدُّوا عَلَىٰ أَدْبَارِكُمْ فَتَنقَلِبُوا خَاسِرِينَ', NULL, 'O my people, enter the blessed land [i.e., Palestine] which Allāh has assigned to you and do not turn back [from fighting in Allāh''s cause] and [thus] become losers."', '(Nabi Musa berkata lagi): “Wahai kaumku, masuklah ke Tanah Suci (Palestin) yang telah diperintahkan oleh Allah untuk kamu (memasukinya); dan janganlah kamu berbalik undur ke belakang, (kalau kamu undur) maka kamu kelak menjadi orang-orang yang rugi (di dunia dan di akhirat)”.', FALSE, NULL, NULL, 111, 6, 44, 89, FALSE, 0, NULL),
(5, 22, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', 'قَالُوا يَا مُوسَىٰ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا مِنْهَا فَإِن يَخْرُجُوا مِنْهَا فَإِنَّا دَاخِلُونَ', NULL, 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."', 'Mereka menjawab: “Wahai Musa bahawasanya di negeri itu ada kaum yang gagah perkasa, dan sesungguhnya kami tidak akan memasukinya sehingga mereka keluar daripadanya; kemudian jika mereka keluar daripadanya, maka sesungguhnya kami akan masuk (ke negeri itu)”.', FALSE, NULL, NULL, 111, 6, 44, 89, FALSE, 0, NULL),
(5, 23, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'قَالَ رَجُلَانِ مِنَ الَّذِينَ يَخَافُونَ أَنْعَمَ اللَّهُ عَلَيْهِمَا ادْخُلُوا عَلَيْهِمُ الْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَالِبُونَ وَعَلَى اللَّهِ فَتَوَكَّلُوا إِن كُنتُم مُّؤْمِنِينَ', NULL, 'Said two men from those who feared [to disobey] upon whom Allāh had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allāh rely, if you should be believers."', 'Berkatalah dua lelaki di antara orang-orang yang takut (menyalahi perintah tuhan), lagi yang telah diberi nikmat (taufik) oleh Allah kepada keduanya: “Seranglah mereka melalui pintu itu, kerana apabila kamu memasukinya maka sudah tentu kamulah orang-orang yang menang; dan kepada Allah jualah hendaklah kamu berserah (setelah kamu bertindak menyerang), jika benar kamu orang-orang yang beriman”', FALSE, NULL, NULL, 111, 6, 44, 89, FALSE, 0, NULL),
(5, 24, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', 'قَالُوا يَا مُوسَىٰ إِنَّا لَن نَّدْخُلَهَا أَبَدًا مَّا دَامُوا فِيهَا فَاذْهَبْ أَنتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ', NULL, 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."', 'Mereka (menolak dengan) berkata: “Wahai Musa, sesungguhnya kami tidak akan memasuki negeri itu selama-lamanya selagi kaum itu masih berada di dalamnya; oleh itu pergilah engkau bersama Tuhanmu dan perangilah mereka. Sebenarnya kami di sinilah duduk menunggu”.', FALSE, NULL, NULL, 112, 6, 44, 89, FALSE, 0, NULL),
(5, 25, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'قَالَ رَبِّ إِنِّي لَا أَمْلِكُ إِلَّا نَفْسِي وَأَخِي فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ', NULL, '[Moses] said, "My Lord, indeed I do not possess [i.e., control] except myself and my brother, so part us from the defiantly disobedient people."', 'Nabi Musa (merayu kepada Allah), katanya: “Wahai Tuhan! Sesungguhnya aku tidak dapat menguasai selain daripada diriku sendiri dan saudaraku (Harun); oleh itu pisahkanlah antara kami dengan kaum yang fasik itu”.', FALSE, NULL, NULL, 112, 6, 44, 89, FALSE, 0, NULL),
(5, 26, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِى ٱلْأَرْضِ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِي الْأَرْضِ فَلَا تَأْسَ عَلَى الْقَوْمِ الْفَاسِقِينَ', NULL, '[Allāh] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."', 'Allah berfirman: “Sesungguhnya negeri itu diharamkan kepada mereka memasukinya - selama empat puluh tahun, mereka akan merayau-rayau dengan bingungnya (di sepanjang masa yang tersebut) di padang pasir (Sinai); maka janganlah engkau berdukacita terhadap kaum yang fasik itu”.', FALSE, NULL, NULL, 112, 6, 44, 89, FALSE, 0, NULL),
(5, 27, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', 'وَاتْلُ عَلَيْهِمْ نَبَأَ ابْنَيْ آدَمَ بِالْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ الْآخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ اللَّهُ مِنَ الْمُتَّقِينَ', NULL, 'And recite to them the story of Adam''s two sons, in truth, when they both made an offering [to Allāh], and it was accepted from one of them but was not accepted from the other. Said [the latter], "I will surely kill you." Said [the former], "Indeed, Allāh only accepts from the righteous [who fear Him].', 'Dan bacakanlah (wahai Muhammad) kepada mereka kisah (mengenai) dua orang anak Adam (Habil dan Qabil) yang berlaku dengan sebenarnya, iaitu ketika mereka berdua mempersembahkan satu persembahan korban (untuk mendampingkan diri kepada Allah). Lalu diterima korban salah seorang di antaranya (Habil), dan tidak diterima (korban) dari yang lain (Qabil). Berkata (Qabil): “Sesungguhnya aku akan membunuhmu!”. (Habil) menjawab: “Hanyasanya Allah menerima (korban) dari orang-orang yang bertaqwa;', FALSE, NULL, NULL, 112, 6, 45, 90, FALSE, 0, NULL),
(5, 28, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'لَئِن بَسَطتَ إِلَيَّ يَدَكَ لِتَقْتُلَنِي مَا أَنَا بِبَاسِطٍ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ', NULL, 'If you should raise your hand toward me to kill me - I shall not raise my hand toward you to kill you. Indeed, I fear Allāh, Lord of the worlds.', '“Demi sesungguhnya! Jika engkau hulurkan tanganmu kepadaku untuk membunuhku, aku tidak sekali-kali akan menghulurkan tanganku kepadamu untuk membunuhmu. Kerana sesungguhnya aku takut kepada Allah, Tuhan Yang mentadbirkan sekalian alam;', FALSE, NULL, NULL, 112, 6, 45, 90, FALSE, 0, NULL),
(5, 29, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 'إِنِّي أُرِيدُ أَن تَبُوءَ بِإِثْمِي وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَابِ النَّارِ وَذَٰلِكَ جَزَاءُ الظَّالِمِينَ', NULL, 'Indeed, I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of wrongdoers."', '“Sesungguhnya aku mahu supaya engkau kembali dengan (membawa) dosa (membunuhku) dan dosamu sendiri. Maka dengan itu menjadilah engkau dari ahli neraka, dan itulah dia balasan orang-orang yang zalim”.', FALSE, NULL, NULL, 112, 6, 45, 90, FALSE, 0, NULL),
(5, 30, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 'فَطَوَّعَتْ لَهُ نَفْسُهُ قَتْلَ أَخِيهِ فَقَتَلَهُ فَأَصْبَحَ مِنَ الْخَاسِرِينَ', NULL, 'And his soul permitted to him the murder of his brother, so he killed him and became among the losers.', 'Maka nafsu jahat (Qabil) mendorongnya (sehingga ia tergamak) membunuh saudaranya, lalu ia membunuhnya. Oleh itu menjadilah dia dari golongan orang-orang yang rugi.', FALSE, NULL, NULL, 112, 6, 45, 90, FALSE, 0, NULL),
(5, 31, 'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', 'فَبَعَثَ اللَّهُ غُرَابًا يَبْحَثُ فِي الْأَرْضِ لِيُرِيَهُ كَيْفَ يُوَارِي سَوْءَةَ أَخِيهِ قَالَ يَا وَيْلَتَىٰ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا الْغُرَابِ فَأُوَارِيَ سَوْءَةَ أَخِي فَأَصْبَحَ مِنَ النَّادِمِينَ', NULL, 'Then Allāh sent a crow searching [i.e., scratching] in the ground to show him how to hide the disgrace of his brother. He said, "O woe to me! Have I failed to be like this crow and hide the disgrace [i.e., body] of my brother?" And he became of the regretful.', 'Kemudian Allah hantarkan seekor burung gagak (menyuruhnya) mengorek-ngorek di bumi supaya, diperlihatkan kepada (Qabil) bagaimana cara menimbus mayat saudaranya. (Qabil) berkata: “Wahai celakanya aku! Alangkah lemah serta bodohnya aku, aku tidak tahu berbuat seperti burung gagak ini, supaya aku dapat menimbuskan mayat saudaraku?”. Kerana itu menjadilah ia dari golongan orang-orang yang menyesal.', FALSE, NULL, NULL, 112, 6, 45, 90, FALSE, 0, NULL),
(5, 32, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِي إِسْرَائِيلَ أَنَّهُ مَن قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِي الْأَرْضِ فَكَأَنَّمَا قَتَلَ النَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَا أَحْيَا النَّاسَ جَمِيعًا وَلَقَدْ جَاءَتْهُمْ رُسُلُنَا بِالْبَيِّنَاتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِي الْأَرْضِ لَمُسْرِفُونَ', NULL, 'Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land - it is as if he had slain mankind entirely. And whoever saves one - it is as if he had saved mankind entirely. And Our messengers had certainly come to them with clear proofs. Then indeed many of them, [even] after that, throughout the land, were transgressors.', 'Dengan sebab (kisah pembunuhan kejam) yang demikian itu kami tetapkan atas Bani Israil, bahawasanya sesiapa yang membunuh seorang manusia dengan tiada alasan yang membolehkan membunuh orang itu, atau (kerana) melakukan kerosakan di muka bumi, maka seolah-olah dia telah membunuh manusia semuanya; dan sesiapa yang menjaga keselamatan hidup seorang manusia, maka seolah-olah dia telah menjaga keselamatan hidup manusia semuanya. Dan demi sesungguhnya, telah datang kepada mereka Rasul-rasul kami dengan membawa keterangan yang cukup terang; kemudian, sesungguhnya kebanyakan dari mereka sesudah itu, sungguh-sungguh menjadi orang-orang yang melampaui batas (melakukan kerosakan) di muka bumi.', FALSE, NULL, NULL, 113, 6, 45, 90, FALSE, 0, NULL),
(5, 33, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', 'إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَن يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَافٍ أَوْ يُنفَوْا مِنَ الْأَرْضِ ذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ', NULL, 'Indeed, the penalty for those who wage war against Allāh and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,', 'Hanyasanya balasan orang-orang yang memerangi Allah dan RasulNya serta melakukan bencana kerosakan di muka bumi ialah dengan dibalas bunuh (kalau mereka membunuh sahaja dengan tidak merampas), atau dipalang (kalau mereka membunuh dan merampas), atau dipotong tangan dan kaki mereka bersilang (kalau mereka merampas sahaja), atau dibuang negeri (kalau mereka hanya mengganggu ketenteraman umum). Hukuman yang demikian itu adalah suatu kehinaan di dunia bagi mereka, dan di akhirat kelak mereka beroleh azab seksa yang amat besar.', FALSE, NULL, NULL, 113, 6, 45, 90, FALSE, 0, NULL),
(5, 34, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'إِلَّا الَّذِينَ تَابُوا مِن قَبْلِ أَن تَقْدِرُوا عَلَيْهِمْ فَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'Except for those who return [repenting] before you overcome [i.e., apprehend] them. And know that Allāh is Forgiving and Merciful.', 'Kecuali orang-orang yang bertaubat sebelum kamu dapat menangkapnya, (mereka terlepas dari hukuman itu). Maka ketahuilah, bahawasanya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 113, 6, 45, 90, FALSE, 0, NULL),
(5, 35, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ وَجَاهِدُوا فِي سَبِيلِهِ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, fear Allāh and seek the means [of nearness] to Him and strive in His cause that you may succeed.', 'Wahai orang-orang yang beriman! Bertaqwalah kepada Allah dan carilah yang boleh menyampaikan kepadaNya (dengan mematuhi perintahNya dan meninggalkan laranganNya); dan berjuanglah pada jalan Allah (untuk menegakkan Islam) supaya kamu beroleh kejayaan.', FALSE, NULL, NULL, 113, 6, 45, 91, FALSE, 0, NULL),
(5, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّ الَّذِينَ كَفَرُوا لَوْ أَنَّ لَهُم مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ عَذَابِ يَوْمِ الْقِيَامَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Indeed, those who disbelieve - if they should have all that is in the earth and the like of it with it by which to ransom themselves from the punishment of the Day of Resurrection, it will not be accepted from them, and for them is a painful punishment.', 'Sesungguhnya orang-orang yang kafir, kalau (tiap-tiap seorang dari) mereka mempunyai segala yang ada di muka bumi atau sebanyak itu lagi bersamanya, untuk mereka menjadikannya penebus diri mereka dari azab seksa hari kiamat, nescaya tebusan itu tidak akan diterima dari mereka; dan mereka akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 113, 6, 45, 91, FALSE, 0, NULL),
(5, 37, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'يُرِيدُونَ أَن يَخْرُجُوا مِنَ النَّارِ وَمَا هُم بِخَارِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ', NULL, 'They will wish to get out of the Fire, but never are they to emerge therefrom, and for them is an enduring punishment.', 'Mereka sentiasa berharap hendak keluar dari api neraka itu, padahal mereka tidak sekali-kali akan dapat keluar daripadanya; dan bagi mereka azab seksa yang tetap kekal.', FALSE, NULL, NULL, 114, 6, 45, 91, FALSE, 0, NULL),
(5, 38, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًا مِّنَ ٱللَّهِ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا جَزَاءً بِمَا كَسَبَا نَكَالًا مِّنَ اللَّهِ وَاللَّهُ عَزِيزٌ حَكِيمٌ', NULL, '[As for] the thief, the male and the female, amputate their hands in recompense for what they earned [i.e., committed] as a deterrent [punishment] from Allāh. And Allāh is Exalted in Might and Wise.', 'Dan orang lelaki yang mencuri dan orang perempuan yang mencuri maka (hukumnya) potonglah tangan mereka sebagai satu balasan dengan sebab apa yang mereka telah usahakan, (juga sebagai) suatu hukuman pencegah dari Allah. Dan (ingatlah) Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 114, 6, 45, 91, FALSE, 0, NULL),
(5, 39, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'فَمَن تَابَ مِن بَعْدِ ظُلْمِهِ وَأَصْلَحَ فَإِنَّ اللَّهَ يَتُوبُ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'But whoever repents after his wrongdoing and reforms, indeed, Allāh will turn to him in forgiveness. Indeed, Allāh is Forgiving and Merciful.', 'Maka sesiapa yang bertaubat sesudah ia melakukan kejahatan (curi) itu dan memperbaiki amal usahanya, sesungguhnya Allah menerima taubatnya; kerana Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 114, 6, 45, 91, FALSE, 0, NULL),
(5, 40, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يُعَذِّبُ مَن يَشَاءُ وَيَغْفِرُ لِمَن يَشَاءُ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Do you not know that to Allāh belongs the dominion of the heavens and the earth? He punishes whom He wills and forgives whom He wills, and Allāh is over all things competent.', 'Tidakkah engkau mengetahui bahawa Allah menguasai pemerintahan langit dan bumi? Ia menyeksakan sesiapa yang dikehendakiNya (menurut aturan dan hukum SyariatNya), dan mengampunkan sesiapa yang dikehendakiNya (menurut aturan dan hukum SyariatNya). Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 114, 6, 45, 91, FALSE, 0, NULL),
(5, 41, 'يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ وَمِنَ ٱلَّذِينَ هَادُوا۟ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', 'يَا أَيُّهَا الرَّسُولُ لَا يَحْزُنكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ مِنَ الَّذِينَ قَالُوا آمَنَّا بِأَفْوَاهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ وَمِنَ الَّذِينَ هَادُوا سَمَّاعُونَ لِلْكَذِبِ سَمَّاعُونَ لِقَوْمٍ آخَرِينَ لَمْ يَأْتُوكَ يُحَرِّفُونَ الْكَلِمَ مِن بَعْدِ مَوَاضِعِهِ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَاحْذَرُوا وَمَن يُرِدِ اللَّهُ فِتْنَتَهُ فَلَن تَمْلِكَ لَهُ مِنَ اللَّهِ شَيْئًا أُولَٰئِكَ الَّذِينَ لَمْ يُرِدِ اللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ', NULL, 'O Messenger, let them not grieve you who hasten into disbelief – of those who say, "We believe" with their mouths, but their hearts believe not, and from among the Jews. [They are] avid listeners to falsehood, listening to another people who have not come to you. They distort words beyond their [proper] places [i.e., usages], saying, "If you are given this, take it; but if you are not given it, then beware." But he for whom Allāh intends fitnah - never will you possess [power to do] for him a thing against Allāh. Those are the ones for whom Allāh does not intend to purify their hearts. For them in this world is disgrace, and for them in the Hereafter is a great punishment.', 'Wahai Rasul Allah! Janganlah engkau menanggung dukacita disebabkan orang-orang yang segera menceburkan diri dalam kekufuran, iaitu dari orang-orang yang berkata dengan mulutnya: “Kami tetap beriman”, padahal hatinya tidak beriman; demikian juga dari orang-orang Yahudi, mereka orang-orang yang sangat suka mendengar berita-berita dusta; mereka sangat suka mendengar perkataan golongan lain (pendita-pendita Yahudi) yang tidak pernah datang menemuimu; mereka ini mengubah serta meminda perkataan-perkataan (dalam Kitab Taurat) itu dari tempat-tempatnya yang sebenar. Mereka berkata: “Jika disampaikan kepada kamu hukum seperti ini maka terimalah dia, dan jika tidak disampaikannya kepada kamu, maka jagalah diri baik-baik”. Dan sesiapa yang dikehendaki Allah kesesatannya, maka engkau tidak berkuasa sama sekali (menolak) sesuatu apapun (yang datang) dari Allah untuknya. Mereka ialah orang-orang yang Allah tidak mahu membersihkan hati mereka; bagi mereka kehinaan di dunia, dan di akhirat kelak mereka beroleh azab seksa yang besar.', FALSE, NULL, NULL, 114, 6, 46, 91, FALSE, 0, NULL),
(5, 42, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ فَإِن جَاءُوكَ فَاحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْئًا وَإِنْ حَكَمْتَ فَاحْكُم بَيْنَهُم بِالْقِسْطِ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ', NULL, '[They are] avid listeners to falsehood, devourers of [what is] unlawful. So if they come to you, [O Muḥammad], judge between them or turn away from them. And if you turn away from them - never will they harm you at all. And if you judge, judge between them with justice. Indeed, Allāh loves those who act justly.', 'Mereka sangat suka mendengar berita-berita dusta, sangat suka memakan segala yang haram (rasuah dan sebagainya). Oleh itu kalau mereka datang kepadamu, maka hukumlah di antara mereka (dengan apa yang telah diterangkan oleh Allah), atau berpalinglah dari mereka; dan kalau engkau berpaling dari mereka maka mereka tidak akan dapat membahayakanmu sedikitpun; dan jika engkau menghukum maka hukumlah di antara mereka dengan adil; kerana sesungguhnya Allah mengasihi orang-orang yang berlaku adil.', FALSE, NULL, NULL, 115, 6, 46, 91, FALSE, 0, NULL),
(5, 43, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ التَّوْرَاةُ فِيهَا حُكْمُ اللَّهِ ثُمَّ يَتَوَلَّوْنَ مِن بَعْدِ ذَٰلِكَ وَمَا أُولَٰئِكَ بِالْمُؤْمِنِينَ', NULL, 'But how is it that they come to you for judgement while they have the Torah, in which is the judgement of Allāh? Then they turn away, [even] after that; but those are not [in fact] believers.', 'Dan (sungguh menghairankan), bagaimana mereka meminta keputusan hukum kepadamu, padahal di sisi mereka ada Kitab Taurat yang mengandungi hukum Allah, kemudian mereka berpaling pula sesudah itu (dari hukumanmu)? Dan (sebenarnya) mereka itu bukanlah orang-orang yang beriman.', FALSE, NULL, NULL, 115, 6, 46, 91, FALSE, 0, NULL),
(5, 44, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', 'إِنَّا أَنزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا لِلَّذِينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْأَحْبَارُ بِمَا اسْتُحْفِظُوا مِن كِتَابِ اللَّهِ وَكَانُوا عَلَيْهِ شُهَدَاءَ فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ وَلَا تَشْتَرُوا بِآيَاتِي ثَمَنًا قَلِيلًا وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الْكَافِرُونَ', NULL, 'Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allāh] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allāh, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price [i.e., worldly gain]. And whoever does not judge by what Allāh has revealed - then it is those who are the disbelievers.', 'Sesungguhnya Kami telah menurunkan Kitab Taurat, yang mengandungi petunjuk dan cahaya yang menerangi; dengan Kitab itu nabi-nabi yang menyerah diri (kepada Allah) menetapkan hukum bagi orang-orang Yahudi, dan (dengannya juga) ulama mereka dan pendita-penditanya (menjalankan hukum Allah), sebab mereka diamanahkan memelihara dan menjalankan hukum-hukum dari Kitab Allah (Taurat) itu, dan mereka pula adalah menjadi penjaga dan pengawasnya (dari sebarang perubahan). Oleh itu janganlah kamu takut kepada manusia tetapi hendaklah kamu takut kepadaKu (dengan menjaga diri dari melakukan maksiat dan patuh akan perintahKu); dan janganlah kamu menjual (membelakangkan) ayat-ayatKu dengan harga yang sedikit (kerana mendapat rasuah, pangkat dan lain-lain keuntungan dunia); dan sesiapa yang tidak menghukum dengan apa yang telah diturunkan oleh Allah (kerana mengingkarinya), maka mereka itulah orang-orang kafir.', FALSE, NULL, NULL, 115, 6, 46, 92, FALSE, 0, NULL),
(5, 45, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنفَ بِالْأَنفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصٌ فَمَن تَصَدَّقَ بِهِ فَهُوَ كَفَّارَةٌ لَّهُ وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ', NULL, 'And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allāh has revealed - then it is those who are the wrongdoers [i.e., the unjust].', 'Dan kami telah tetapkan atas mereka di dalam kitab Taurat itu, bahawa jiwa dibalas dengan jiwa, dan mata dibalas dengan mata, dan hidung dibalas dengan hidung, dan telinga dibalas dengan telinga, dan gigi dibalas dengan gigi, dan luka-luka hendaklah dibalas (seimbang). Tetapi sesiapa yang melepaskan hak membalasnya, maka menjadilah ia penebus dosa baginya; dan sesiapa yang tidak menghukum dengan apa yang telah diturunkan Allah, maka mereka itulah orang-orang yang zalim.', FALSE, NULL, NULL, 115, 6, 46, 92, FALSE, 0, NULL),
(5, 46, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'وَقَفَّيْنَا عَلَىٰ آثَارِهِم بِعِيسَى ابْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ وَآتَيْنَاهُ الْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', NULL, 'And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous.', 'Dan Kami utuskan Nabi Isa Ibni Maryam mengikuti jejak langkah mereka (Nabi-nabi Bani Israil), untuk membenarkan Kitab Taurat yang diturunkan sebelumnya; dan Kami telah berikan kepadanya Kitab Injil, yang mengandungi petunjuk hidayah dan cahaya yang menerangi, sambil mengesahkan benarnya apa yang telah ada di hadapannya dari Kitab Taurat, serta menjadi petunjuk dan nasihat pengajaran bagi orang-orang yang (hendak) bertaqwa.', FALSE, NULL, NULL, 116, 6, 46, 92, FALSE, 0, NULL),
(5, 47, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'وَلْيَحْكُمْ أَهْلُ الْإِنجِيلِ بِمَا أَنزَلَ اللَّهُ فِيهِ وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ', NULL, 'And let the People of the Gospel judge by what Allāh has revealed therein. And whoever does not judge by what Allāh has revealed - then it is those who are the defiantly disobedient.', 'Dan hendaklah Ahli Kitab Injil menghukum dengan apa yang telah diturunkan oleh Allah di dalamnya; dan sesiapa yang tidak menghukum dengan apa yang telah diturunkan oleh Allah, maka mereka itulah orang-orang yang fasik.', FALSE, NULL, NULL, 116, 6, 46, 92, FALSE, 0, NULL),
(5, 48, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'وَأَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ عَمَّا جَاءَكَ مِنَ الْحَقِّ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا وَلَوْ شَاءَ اللَّهُ لَجَعَلَكُمْ أُمَّةً وَاحِدَةً وَلَٰكِن لِّيَبْلُوَكُمْ فِي مَا آتَاكُمْ فَاسْتَبِقُوا الْخَيْرَاتِ إِلَى اللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', NULL, 'And We have revealed to you, [O Muḥammad], the Book [i.e., the Qur’ān] in truth, confirming that which preceded it of the Scripture and as a criterion over it. So judge between them by what Allāh has revealed and do not follow their inclinations away from what has come to you of the truth. To each of you We prescribed a law and a method. Had Allāh willed, He would have made you one nation [united in religion], but [He intended] to test you in what He has given you; so race to [all that is] good. To Allāh is your return all together, and He will [then] inform you concerning that over which you used to differ.', 'Dan Kami turunkan kepadamu (wahai Muhammad) Kitab (Al-Quran) dengan membawa kebenaran, untuk mengesahkan benarnya Kitab-kitab Suci yang telah diturunkan sebelumnya dan untuk memelihara serta mengawasinya. Maka jalankanlah hukum di antara mereka (Ahli Kitab) itu dengan apa yang telah diturunkan oleh Allah (kepadamu), dan janganlah engkau mengikut kehendak hawa nafsu mereka (dengan menyeleweng) dari apa yang telah datang kepadamu dari kebenaran. Bagi tiap-tiap umat yang ada di antara kamu, Kami jadikan (tetapkan) suatu Syariat dan jalan ugama (yang wajib diikuti oleh masing-masing). Dan kalau Allah menghendaki nescaya Ia menjadikan kamu satu umat (yang bersatu dalam ugama yang satu), tetapi Ia hendak menguji kamu (dalam menjalankan) apa yang telah disampaikan kepada kamu. Oleh itu berlumba-lumbalah kamu membuat kebaikan (beriman dan beramal soleh). Kepada Allah jualah tempat kembali kamu semuanya, maka Ia akan memberitahu kamu apa yang kamu berselisihan padanya.', FALSE, NULL, NULL, 116, 6, 46, 92, FALSE, 0, NULL),
(5, 49, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', 'وَأَنِ احْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ وَاحْذَرْهُمْ أَن يَفْتِنُوكَ عَن بَعْضِ مَا أَنزَلَ اللَّهُ إِلَيْكَ فَإِن تَوَلَّوْا فَاعْلَمْ أَنَّمَا يُرِيدُ اللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ وَإِنَّ كَثِيرًا مِّنَ النَّاسِ لَفَاسِقُونَ', NULL, 'And judge, [O Muḥammad], between them by what Allāh has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allāh has revealed to you. And if they turn away - then know that Allāh only intends to afflict them with some of their [own] sins. And indeed, many among the people are defiantly disobedient.', 'Dan hendaklah engkau menjalankan hukum di antara mereka dengan apa yang telah diturunkan oleh Allah dan janganlah engkau menurut kehendak hawa nafsu mereka, dan berjaga-jagalah supaya mereka tidak memesongkanmu dari sesuatu hukum yang telah diturunkan oleh Allah kepadamu. Kemudian jika mereka berpaling (enggan menerima hukum Allah itu), maka ketahuilah, hanyasanya Allah mahu menyeksa mereka dengan sebab setengah dari dosa-dosa mereka; dan sesungguhnya kebanyakan dari umat manusia itu adalah orang-orang yang fasik.', FALSE, NULL, NULL, 116, 6, 46, 92, FALSE, 0, NULL),
(5, 50, 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', 'أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', NULL, 'Then is it the judgement of [the time of] ignorance they desire? But who is better than Allāh in judgement for a people who are certain [in faith].', 'Sesudah itu, patutkah mereka berkehendak lagi kepada hukum-hukum jahiliyah? Padahal - kepada orang-orang yang penuh keyakinan - tidak ada sesiapa yang boleh membuat hukum yang lebih pada daripada Allah.', FALSE, NULL, NULL, 116, 6, 46, 92, FALSE, 0, NULL),
(5, 51, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا الْيَهُودَ وَالنَّصَارَىٰ أَوْلِيَاءَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُ مِنْهُمْ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'O you who have believed, do not take the Jews and the Christians as allies. They are [in fact] allies of one another. And whoever is an ally to them among you - then indeed, he is [one] of them. Indeed, Allāh guides not the wrongdoing people.', 'Wahai orang-orang yang beriman! Janganlah kamu mengambil orang-orang Yahudi dan Nasrani itu sebagai teman rapat, kerana setengah mereka menjadi teman rapat kepada setengahnya yang lain; dan sesiapa di antara kamu yang menjadikan mereka teman rapatnya, maka sesungguhnya ia adalah dari golongan mereka itu mereka itu. Sesungguhnya Allah tidak memberikan petunjuk kepada kaum yang berlaku zalim.', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 52, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', 'فَتَرَى الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ يُسَارِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰ أَن تُصِيبَنَا دَائِرَةٌ فَعَسَى اللَّهُ أَن يَأْتِيَ بِالْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِ فَيُصْبِحُوا عَلَىٰ مَا أَسَرُّوا فِي أَنفُسِهِمْ نَادِمِينَ', NULL, 'So you see those in whose hearts is disease [i.e., hypocrisy] hastening into [association with] them, saying, "We are afraid a misfortune may strike us." But perhaps Allāh will bring conquest or a decision from Him, and they will become, over what they have been concealing within themselves, regretful.', 'Dalam pada itu, engkau lihat orang-orang (munafik) yang ada penyakit dalam hatinya segera berusaha mendampingkan diri kepada mereka (Yahudi dan Nasrani), sambil berkata: “Kami takut bahawa kami akan ditimpa bencana (yang memaksa kami meminta pertolongan mereka)”. Mudah-mudahan Allah akan mendatangkan kemenangan (kepada RasulNya dan umat Islam) atau mendatangkan sesuatu hukuman dari sisiNya (terhadap golongan yang munafik itu); maka sebab itu mereka akan menyesal mengenai apa yang telah mereka sembunyikan dalam hatinya.', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 53, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ إِنَّهُمْ لَمَعَكُمْ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 'وَيَقُولُ الَّذِينَ آمَنُوا أَهَٰؤُلَاءِ الَّذِينَ أَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ إِنَّهُمْ لَمَعَكُمْ حَبِطَتْ أَعْمَالُهُمْ فَأَصْبَحُوا خَاسِرِينَ', NULL, 'And those who believe will say, "Are these the ones who swore by Allāh their strongest oaths that indeed they were with you?" Their deeds have become worthless, and they have become losers.', 'Dan (telatah kaum munafik itu menjadikan) orang-orang yang beriman berkata: “Adakah mereka ini orang-orang yang bersumpah dengan nama Allah, dengan sebenar-benar sumpahnya, bahawa mereka benar-benar menyertai dan menolong kamu?” Telah gugurlah amal-amal mereka, lalu menjadilah mereka: orang-orang yang rugi.', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 54, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِ فَسَوْفَ يَأْتِي اللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ يُجَاهِدُونَ فِي سَبِيلِ اللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَائِمٍ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'O you who have believed, whoever of you should revert from his religion - Allāh will bring forth [in place of them] a people He will love and who will love Him [who are] humble toward the believers, strong against the disbelievers; they strive in the cause of Allāh and do not fear the blame of a critic. That is the favor of Allāh; He bestows it upon whom He wills. And Allāh is all-Encompassing and Knowing.', 'Wahai orang-orang yang beriman! Sesiapa di antara kamu berpaling tadah dari ugamanya (jadi murtad), maka Allah akan mendatangkan suatu kaum yang Ia kasihkan mereka dan mereka juga kasihkan Dia; mereka pula bersifat lemah-lembut terhadap orang-orang yang beriman dan berlaku tegas gagah terhadap orang-orang kafir, mereka berjuang dengan bersungguh-sungguh pada jalan Allah, dan mereka tidak takut kepada celaan orang yang mencela. Yang demikian itu adalah limpah kurnia Allah yang diberikanNya kepada sesiapa yang dikehendakiNya; kerana Allah Maha Luas limpah kurniaNya, lagi Meliputi PengetahuanNya.', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 55, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 'إِنَّمَا وَلِيُّكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ رَاكِعُونَ', NULL, 'Your ally is none but Allāh and [therefore] His Messenger and those who have believed - those who establish prayer and give zakāh, and they bow [in worship].', 'Sesungguhnya Penolong kamu hanyalah Allah, dan RasulNya, serta orang-orang yang beriman, yang mendirikan sembahyang, dan menunaikan zakat, sedang mereka rukuk (tunduk menjunjung perintah Allah).', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 56, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 'وَمَن يَتَوَلَّ اللَّهَ وَرَسُولَهُ وَالَّذِينَ آمَنُوا فَإِنَّ حِزْبَ اللَّهِ هُمُ الْغَالِبُونَ', NULL, 'And whoever is an ally of Allāh and His Messenger and those who have believed - indeed, the party of Allāh - they will be the predominant.', 'Dan sesiapa yang menjadikan Allah dan rasulnya serta orang-orang yang beriman itu penolongnya (maka berjayalah dia), kerana sesungguhnya golongan (yang berpegang kepada ugama) Allah, itulah yang tetap menang.', FALSE, NULL, NULL, 117, 6, 47, 93, FALSE, 0, NULL),
(5, 57, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا الَّذِينَ اتَّخَذُوا دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ وَالْكُفَّارَ أَوْلِيَاءَ وَاتَّقُوا اللَّهَ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'O you who have believed, take not those who have taken your religion in ridicule and amusement among the ones who were given the Scripture before you nor the disbelievers as allies. And fear Allāh, if you should [truly] be believers.', 'Wahai orang-orang yang beriman! Janganlah kamu mengambil orang-orang yang menjadikan ugama kamu sebagai ejek-ejekan dan permainan - dari orang-orang yang telah diberikan Kitab sebelum kamu, dan orang-orang kafir musyrik itu: menjadi penolong-penolong; dan bertaqwalah kepada Allah, jika kamu benar-benar orang yang beriman.', FALSE, NULL, NULL, 117, 6, 47, 94, FALSE, 0, NULL),
(5, 58, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', 'وَإِذَا نَادَيْتُمْ إِلَى الصَّلَاةِ اتَّخَذُوهَا هُزُوًا وَلَعِبًا ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', NULL, 'And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason.', 'Dan apabila kamu menyeru (azan) untuk mengerjakan sembahyang, mereka menjadikan sembahyang itu sebagai ejek-ejekan dan permainan. Yang demikian itu ialah kerana mereka suatu kaum yang tidak berakal.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 59, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', 'قُلْ يَا أَهْلَ الْكِتَابِ هَلْ تَنقِمُونَ مِنَّا إِلَّا أَنْ آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَاسِقُونَ', NULL, 'Say, "O People of the Scripture, do you resent us except [for the fact] that we have believed in Allāh and what was revealed to us and what was revealed before and because most of you are defiantly disobedient?"', 'Katakanlah (wahai Muhammad): “Wahai Ahli Kitab! Kamu tidak mencela dan menyalahkan kami melainkan kerana kami beriman kepada Allah dan beriman kepada apa yang diturunkan kepada kami, serta beriman kepada apa yang diturunkan sebelum itu, dan kerana kebanyakan kamu sesungguhnya adalah orang orang yang fasik”.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 60, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ اللَّهِ مَن لَّعَنَهُ اللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ الْقِرَدَةَ وَالْخَنَازِيرَ وَعَبَدَ الطَّاغُوتَ أُولَٰئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَاءِ السَّبِيلِ', NULL, 'Say, "Shall I inform you of [what is] worse than that as penalty from Allāh? [It is that of] those whom Allāh has cursed and with whom He became angry and made of them apes and pigs and slaves of ṭāghūt. Those are worse in position and further astray from the sound way."', 'Katakanlah: “Mahukah, aku khabarkan kepada kamu tentang yang lebih buruk balasannya di sisi Allah daripada yang demikian itu? Ialah orang-orang yang dilaknat oleh Allah dan dimurkaiNya, dan orang-orang yang dijadikan di antara mereka sebagai kera dan babi, dan penyembah Taghut. Mereka inilah yang lebih buruk kedudukannya dan yang lebih sesat dari jalan yang betul”.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 61, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', 'وَإِذَا جَاءُوكُمْ قَالُوا آمَنَّا وَقَد دَّخَلُوا بِالْكُفْرِ وَهُمْ قَدْ خَرَجُوا بِهِ وَاللَّهُ أَعْلَمُ بِمَا كَانُوا يَكْتُمُونَ', NULL, 'And when they come to you, they say, "We believe." But they have entered with disbelief [in their hearts], and they have certainly left with it. And Allāh is most knowing of what they were concealing.', 'Dan apabila mereka (orang-orang Yahudi atau munafik itu) datang kepada kamu, mereka berkata: “Kami telah beriman”. Padahal sesungguhnya mereka itu masuk menemui kamu dengan kekufurannya, dan sesungguhnya mereka keluar (dari sisi kamu) dengan kekufurannya juga; dan (hendaklah mereka ingat), Allah lebih mengetahui akan apa yang mereka sembunyikan.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 62, 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَارِعُونَ فِي الْإِثْمِ وَالْعُدْوَانِ وَأَكْلِهِمُ السُّحْتَ لَبِئْسَ مَا كَانُوا يَعْمَلُونَ', NULL, 'And you see many of them hastening into sin and aggression and the devouring of [what is] unlawful. How wretched is what they have been doing.', 'Dan engkau lihat kebanyakan dari mereka berlumba-lumba pada melakukan dosa dan pencerobohan serta memakan yang haram. Demi sesungguhnya amatlah buruk apa yang mereka telah lakukan.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 63, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', 'لَوْلَا يَنْهَاهُمُ الرَّبَّانِيُّونَ وَالْأَحْبَارُ عَن قَوْلِهِمُ الْإِثْمَ وَأَكْلِهِمُ السُّحْتَ لَبِئْسَ مَا كَانُوا يَصْنَعُونَ', NULL, 'Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing.', 'Alangkah baiknya kalau ketua-ketua ugama dan pendita-pendita mereka melarang mereka dari mengeluarkan perkataan-perkataan yang dusta dan dari memakan yang haram? Sesungguhnya amatlah buruk apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 64, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'وَقَالَتِ الْيَهُودُ يَدُ اللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَاءُ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ إِلَىٰ يَوْمِ الْقِيَامَةِ كُلَّمَا أَوْقَدُوا نَارًا لِّلْحَرْبِ أَطْفَأَهَا اللَّهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا وَاللَّهُ لَا يُحِبُّ الْمُفْسِدِينَ', NULL, 'And the Jews say, "The hand of Allāh is chained." Chained are their hands, and cursed are they for what they say. Rather, both His hands are extended; He spends however He wills. And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. And We have cast among them animosity and hatred until the Day of Resurrection. Every time they kindled the fire of war [against you], Allāh extinguished it. And they strive throughout the land [causing] corruption, and Allāh does not like corrupters.', 'Dan orang-orang Yahudi itu berkata: “Tangan Allah terbelenggu (bakhil - kikir)”, tangan merekalah yang terbelenggu dan mereka pula dilaknat dengan sebab apa yang mereka telah katakan itu, bahkan kedua tangan Allah sentiasa terbuka (nikmat dan kurniaNya luas melimpah-limpah). Ia belanjakan (limpahkan) sebagaimana yang Ia kehendaki; dan demi sesungguhnya, apa yang telah diturunkan kepadamu dari tuhanmu itu akan menjadikan kebanyakan dari mereka bertambah derhaka dan kufur; dan Kami tanamkan perasaan permusuhan dan kebencian di antara mereka hingga hari kiamat. Tiap-tiap kali mereka menyalakan api peperangan, Allah memadamkannya; dan mereka pula terus-menerus melakukan kerosakan di muka bumi, sedang Allah tidak suka kepada orang-orang yang melakukan kerosakan.', FALSE, NULL, NULL, 118, 6, 47, 94, FALSE, 0, NULL),
(5, 65, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', 'وَلَوْ أَنَّ أَهْلَ الْكِتَابِ آمَنُوا وَاتَّقَوْا لَكَفَّرْنَا عَنْهُمْ سَيِّئَاتِهِمْ وَلَأَدْخَلْنَاهُمْ جَنَّاتِ النَّعِيمِ', NULL, 'And if only the People of the Scripture had believed and feared Allāh, We would have removed from them their misdeeds and admitted them to Gardens of Pleasure.', 'Dan sekiranya Ahli Kitab itu beriman dan bertaqwa tentulah Kami akan hapuskan dari mereka kejahatan-kejahatan mereka, dan tentulah Kami akan masukkan mereka ke dalam Syurga-syurga yang penuh nikmat.', FALSE, NULL, NULL, 119, 6, 47, 94, FALSE, 0, NULL),
(5, 66, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', 'وَلَوْ أَنَّهُمْ أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ وَكَثِيرٌ مِّنْهُمْ سَاءَ مَا يَعْمَلُونَ', NULL, 'And if only they had upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord [i.e., the Qur’ān], they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate [i.e., acceptable] community, but many of them - evil is that which they do.', 'Dan kalau mereka bersungguh-sungguh menegakkan (menjalankan perintah-perintah Allah dalam) Taurat dan Injil dan apa yang diturunkan kepada mereka dari Tuhan mereka (Al-Quran), nescaya mereka akan makan (yang mewah) dari atas mereka (langit) dan dari bawah kaki mereka (bumi). Di antara mereka ada sepuak yang adil, dan kebanyakan dari mereka, buruk keji amal perbuatannya.', FALSE, NULL, NULL, 119, 6, 47, 94, FALSE, 0, NULL),
(5, 67, 'يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ', NULL, 'O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allāh will protect you from the people. Indeed, Allāh does not guide the disbelieving people.', 'Wahai Rasul Allah! Sampaikanlah apa yang telah diturunkan kepadamu dari Tuhanmu; dan jika engkau tidak melakukannya (dengan menyampaikan semuanya), maka bermakna tiadalah engkau menyampaikan perutusanNya; dan Allah jualah akan memeliharamu dari (kejahatan) manusia. Sesungguhnya Allah tidak memberi hidayah petunjuk kepada kaum yang kafir.', FALSE, NULL, NULL, 119, 6, 48, 95, FALSE, 0, NULL),
(5, 68, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'قُلْ يَا أَهْلَ الْكِتَابِ لَسْتُمْ عَلَىٰ شَيْءٍ حَتَّىٰ تُقِيمُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا فَلَا تَأْسَ عَلَى الْقَوْمِ الْكَافِرِينَ', NULL, 'Say, "O People of the Scripture, you are [standing] on nothing until you uphold [the law of] the Torah, the Gospel, and what has been revealed to you from your Lord [i.e., the Qur’ān]." And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. So do not grieve over the disbelieving people.', 'Katakanlah: “Wahai Ahli Kitab! Kamu tidak dikira mempunyai sesuatu ugama sehingga kamu tegakkan ajaran Kitab-kitab Taurat dan Injil (yang membawa kamu percaya kepada Nabi Muhammad) dan apa yang diturunkan kepada kamu dari Tuhan kamu (iaitu Al-Quran)” Dan demi sesungguhnya, apa yang diturunkan kepadamu (wahai Muhammad) dari Tuhanmu itu, akan menambahkan kederhakaan dan kekufuran kepada kebanyakan mereka. Oleh itu janganlah engkau berdukacita terhadap kaum yang kafir itu.', FALSE, NULL, NULL, 119, 6, 48, 95, FALSE, 0, NULL),
(5, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالصَّابِئُونَ وَالنَّصَارَىٰ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Indeed, those who have believed [in Prophet Muḥammad (ﷺ)] and those [before him (ﷺ)] who were Jews or Sabeans or Christians - those [among them] who believed in Allāh and the Last Day and did righteousness - no fear will there be concerning them, nor will they grieve.', 'Sesungguhnya orang-orang yang beriman, dan orang-orang Yahudi, dan orang-orang Saabiein, dan orang-orang Nasrani - sesiapa sahaja di antara mereka yang beriman kepada Allah (dan segala RasulNya meliputi Nabi Muhammad s.a.w) dan (beriman kepada) hari akhirat serta beramal soleh, maka tidaklah ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 119, 6, 48, 95, FALSE, 0, NULL),
(5, 70, 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ', 'لَقَدْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرَائِيلَ وَأَرْسَلْنَا إِلَيْهِمْ رُسُلًا كُلَّمَا جَاءَهُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا وَفَرِيقًا يَقْتُلُونَ', NULL, 'We had already taken the covenant of the Children of Israel and had sent to them messengers. Whenever there came to them a messenger with what their souls did not desire, a party [of messengers] they denied, and another party they killed.', 'Demi sesungguhnya! Kami telah mengambil perjanjian setia dari Bani Israil dan Kami telah utuskan kepada mereka beberapa orang Rasul. (Tetapi) tiap-tiap kali datang - seorang Rasul kepada mereka dengan membawa apa yang tidak disukai oleh hawa nafsu mereka, mereka dustakan sebahagian dari Rasul-rasul itu, dan mereka bunuh yang sebahagian lagi.', FALSE, NULL, NULL, 119, 6, 48, 95, FALSE, 0, NULL),
(5, 71, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'وَحَسِبُوا أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا وَصَمُّوا ثُمَّ تَابَ اللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا وَصَمُّوا كَثِيرٌ مِّنْهُمْ وَاللَّهُ بَصِيرٌ بِمَا يَعْمَلُونَ', NULL, 'And they thought there would be no [resulting] punishment, so they became blind and deaf. Then Allāh turned to them in forgiveness; then [again] many of them became blind and deaf. And Allāh is Seeing of what they do.', 'Dan mereka juga menyangka bahawa tidak akan berlaku sebarang bencana, lalu mereka membutakan mata dan memekakkan telinga, kemudian Allah menerima taubat mereka, setelah itu kebanyakan dari mereka membutakan mata dan memekakkan telinga lagi. Padahal Allah Maha Melihat akan apa yang mereka lakukan.', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 72, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'لَقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ وَقَالَ الْمَسِيحُ يَا بَنِي إِسْرَائِيلَ اعْبُدُوا اللَّهَ رَبِّي وَرَبَّكُمْ إِنَّهُ مَن يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ', NULL, 'They have certainly disbelieved who say, "Allāh is the Messiah, the son of Mary" while the Messiah has said, "O Children of Israel, worship Allāh, my Lord and your Lord." Indeed, he who associates others with Allāh - Allāh has forbidden him Paradise, and his refuge is the Fire. And there are not for the wrongdoers any helpers.', 'Demi sesungguhnya! Telah kafirlah orang-orang yang berkata: “Bahawasanya Allah ialah Al-Masih Ibni Maryam”. Padahal Al-Masih sendiri berkata: “Wahai Bani Israil! Sembahlah Allah, Tuhanku dan Tuhan kamu, Bahawasanya sesiapa yang mempersekutukan Allah dengan sesuatu yang lain, maka sesungguhnya Allah haramkan kepadanya Syurga, dan tempat kembalinya ialah neraka; dan tiadalah seorang penolong pun bagi orang-orang yang berlaku zalim”.', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 73, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌ وَٰحِدٌ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 'لَّقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ ثَالِثُ ثَلَاثَةٍ وَمَا مِنْ إِلَٰهٍ إِلَّا إِلَٰهٌ وَاحِدٌ وَإِن لَّمْ يَنتَهُوا عَمَّا يَقُولُونَ لَيَمَسَّنَّ الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابٌ أَلِيمٌ', NULL, 'They have certainly disbelieved who say, "Allāh is the third of three." And there is no god except one God. And if they do not desist from what they are saying, there will surely afflict the disbelievers among them a painful punishment.', 'Demi sesungguhnya telah kafirlah orang-orang yang berkata: “Bahawasanya Allah ialah salah satu dari tiga tuhan”. Padahal tiada Tuhan (yang berhak disembah) melainkan Tuhan yang Maha Esa. Dan jika mereka tidak berhenti dari apa yang mereka katakan itu, sudah tentu orang-orang yang kafir dari antara mereka akan dikenakan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 74, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'أَفَلَا يَتُوبُونَ إِلَى اللَّهِ وَيَسْتَغْفِرُونَهُ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'So will they not repent to Allāh and seek His forgiveness? And Allāh is Forgiving and Merciful.', 'Oleh itu tidakkah mereka mahu bertaubat kepada Allah dan memohon keampunannya (sesudah mereka mendengar keterangan-keterangan tentang kepercayaan mereka yang salah dan balasan seksanya)? Padahal Allah Maha pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 75, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', 'مَّا الْمَسِيحُ ابْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ وَأُمُّهُ صِدِّيقَةٌ كَانَا يَأْكُلَانِ الطَّعَامَ انظُرْ كَيْفَ نُبَيِّنُ لَهُمُ الْآيَاتِ ثُمَّ انظُرْ أَنَّىٰ يُؤْفَكُونَ', NULL, 'The Messiah, son of Mary, was not but a messenger; [other] messengers have passed on before him. And his mother was a supporter of truth. They both used to eat food. Look how We make clear to them the signs; then look how they are deluded.', 'Tiadalah Al-Masih Ibni Maryam itu melainkan seorang Rasul yang telah terdahulu sebelumnya beberapa orang Rasul, dan ibunya seorang perempuan yang amat benar, mereka berdua adalah memakan makanan (seperti kamu juga). Lihatlah bagaimana kami jelaskan kepada mereka (ahli kitab itu) keterangan-keterangan (yang tegas yang menunjukkan kesesatan mereka), kemudian lihatlah bagaimana mereka dipalingkan (oleh hawa nafsu mereka dari menerima kebenaran yang jelas nyata itu).', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 76, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'قُلْ أَتَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا وَاللَّهُ هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'Say, "Do you worship besides Allāh that which holds for you no [power of] harm or benefit while it is Allāh who is the Hearing, the Knowing?"', 'Katakanlah (wahai Muhammad): “Patutkah kamu menyembah sesuatu yang lain dari Allah, yang tidak berkuasa memberi mudarat kepada kamu dan tidak juga berkuasa memberi manfaat? Padahal Allah Yang Maha Mendengar, lagi Maha Mengetahui”.', FALSE, NULL, NULL, 120, 6, 48, 95, FALSE, 0, NULL),
(5, 77, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', 'قُلْ يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ غَيْرَ الْحَقِّ وَلَا تَتَّبِعُوا أَهْوَاءَ قَوْمٍ قَدْ ضَلُّوا مِن قَبْلُ وَأَضَلُّوا كَثِيرًا وَضَلُّوا عَن سَوَاءِ السَّبِيلِ', NULL, 'Say, "O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way."', 'Katakanlah: “Wahai Ahli Kitab! Janganlah kamu melampau dalam ugama kamu secara yang tidak benar, dan janganlah kamu menurut hawa nafsu suatu kaum yang telah sesat sebelum ini dan telah menyesatkan banyak manusia, dan juga (sekarang) mereka telah tersesat (jauh) dari jalan yang betul”', FALSE, NULL, NULL, 121, 6, 48, 95, FALSE, 0, NULL),
(5, 78, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'لُعِنَ الَّذِينَ كَفَرُوا مِن بَنِي إِسْرَائِيلَ عَلَىٰ لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ', NULL, 'Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed.', 'Orang-orang kafir Yahudi dari Bani Israil telah dilaknat (di dalam Kitab-kitab Zabur dan Injil) melalui lidah Nabi Daud dan Nabi Isa ibni Maryam. Yang demikian itu disebabkan mereka menderhaka dan selalu menceroboh.', FALSE, NULL, NULL, 121, 6, 48, 96, FALSE, 0, NULL),
(5, 79, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', 'كَانُوا لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ', NULL, 'They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing.', 'Mereka sentiasa tidak berlarang-larangan (sesama sendiri) dari perbuatan mungkar (derhaka dan ceroboh), yang mereka lakukan. Demi sesungguhnya amatlah buruknya apa yang mereka telah lakukan.', FALSE, NULL, NULL, 121, 6, 48, 96, FALSE, 0, NULL),
(5, 80, 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ الَّذِينَ كَفَرُوا لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ اللَّهُ عَلَيْهِمْ وَفِي الْعَذَابِ هُمْ خَالِدُونَ', NULL, 'You see many of them becoming allies of those who disbelieved [i.e., the polytheists]. How wretched is that which they have put forth for themselves in that Allāh has become angry with them, and in the punishment they will abide eternally.', 'Engkau melihat banyak dari mereka menjadikan orang-orang kafir (musyrik) teman rapat mereka. Demi sesungguhnya amatlah buruknya apa yang mereka sediakan bagi diri mereka (pada hari akhirat kelak) iaitu kemurkaan Allah menimpa mereka, dan mereka pula tetap kekal di dalam azab (neraka).', FALSE, NULL, NULL, 121, 6, 48, 96, FALSE, 0, NULL),
(5, 81, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَٰسِقُونَ', 'وَلَوْ كَانُوا يُؤْمِنُونَ بِاللَّهِ وَالنَّبِيِّ وَمَا أُنزِلَ إِلَيْهِ مَا اتَّخَذُوهُمْ أَوْلِيَاءَ وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَاسِقُونَ', NULL, 'And if they had believed in Allāh and the Prophet and in what was revealed to him, they would not have taken them as allies; but many of them are defiantly disobedient.', 'Sekirany mereka beriman kepada Allah dan kepada Nabi serta apa yang diturunkan kepadanya, nescaya mereka tidak menjadikan orang-orang (musyrik) sebagai teman rapat, akan tetapi kebanyakan dari mereka adalah orang-orang fasik.', FALSE, NULL, NULL, 121, 6, 48, 96, FALSE, 0, NULL),
(5, 82, 'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', 'لَتَجِدَنَّ أَشَدَّ النَّاسِ عَدَاوَةً لِّلَّذِينَ آمَنُوا الْيَهُودَ وَالَّذِينَ أَشْرَكُوا وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ آمَنُوا الَّذِينَ قَالُوا إِنَّا نَصَارَىٰ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', NULL, 'You will surely find the most intense of the people in animosity toward the believers [to be] the Jews and those who associate others with Allāh; and you will find the nearest of them in affection to the believers those who say, "We are Christians." That is because among them are priests and monks and because they are not arrogant.', 'Demi sesungguhnya engkau (wahai Muhammad) akan dapati manusia yang keras sekali permusuhannya kepada orang-orang yang beriman ialah orang-orang Yahudi dan orang-orang musyrik. Dan demi sesungguhnya engkau akan dapati orang-orang yang dekat sekali kasih mesranya kepada orang-orang yang beriman ialah orang-orang yang berkata: “Bahawa kami ini ialah orang-orang Nasrani” yang demikian itu, disebabkan ada di antara mereka pendita-pendita dan ahli-ahli ibadat, dan kerana mereka pula tidak berlaku sombong.', FALSE, NULL, NULL, 121, 7, 49, 96, FALSE, 0, NULL),
(5, 83, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'وَإِذَا سَمِعُوا مَا أُنزِلَ إِلَى الرَّسُولِ تَرَىٰ أَعْيُنَهُمْ تَفِيضُ مِنَ الدَّمْعِ مِمَّا عَرَفُوا مِنَ الْحَقِّ يَقُولُونَ رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ', NULL, 'And when they hear what has been revealed to the Messenger, you see their eyes overflowing with tears because of what they have recognized of the truth. They say, "Our Lord, we have believed, so register us among the witnesses.', 'Dan apabila mereka mendengar Al-Quran yang diturunkan kepada Rasulullah (Muhammad, s.a.w), engkau melihat mata mereka mencucurkan air mata disebabkan apa yang mereka ketahui (melalui Kitab mereka) dari kebenaran (Al-Quran), sambil mereka berkata: “Wahai Tuhan kami, kami beriman (kepada Nabi Muhammad dan Kitab Suci Al-Quran), oleh itu tetapkanlah kami bersama-sama orang-orang yang menjadi saksi (yang mengakui kebenaran Nabi Muhammad s.a.w).', FALSE, NULL, NULL, 122, 7, 49, 96, FALSE, 0, NULL),
(5, 84, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 'وَمَا لَنَا لَا نُؤْمِنُ بِاللَّهِ وَمَا جَاءَنَا مِنَ الْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ الْقَوْمِ الصَّالِحِينَ', NULL, 'And why should we not believe in Allāh and what has come to us of the truth? And we aspire that our Lord will admit us [to Paradise] with the righteous people."', '“Dan tidak ada sebab bagi kami tidak beriman kepada Allah dan kepada kebenaran (Al-Quran) yang sampai kepada kami, padahal kami ingin (dengan sepenuh-penuh harapan), supaya Tuhan kami memasukkan kami (ke dalam Syurga) bersama-sama orang-orang yang soleh”', FALSE, NULL, NULL, 122, 7, 49, 96, FALSE, 0, NULL),
(5, 85, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'فَأَثَابَهُمُ اللَّهُ بِمَا قَالُوا جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَٰلِكَ جَزَاءُ الْمُحْسِنِينَ', NULL, 'So Allāh rewarded them for what they said with gardens [in Paradise] beneath which rivers flow, wherein they abide eternally. And that is the reward of doers of good.', 'Lalu Allah memberikan pahala kepada mereka disebabkan (pengakuan iman yang ikhlas) yang telah mereka ucapkan, (iaitu mereka dibalas dengan) Syurga yang mengalir di bawahnya beberapa sungai; mereka pula tetap kekal di dalamnya. Dan yang demikian itu, adalah balasan orang-orang yang berusaha berbuat kebaikan.', FALSE, NULL, NULL, 122, 7, 49, 96, FALSE, 0, NULL),
(5, 86, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ الْجَحِيمِ', NULL, 'But those who disbelieved and denied Our signs - they are the companions of Hellfire.', 'Dan (sebaliknya) orang-orang yang kafir serta mendustakan ayat-ayat keterangan Kami, mereka itulah ahli neraka.', FALSE, NULL, NULL, 122, 7, 49, 96, FALSE, 0, NULL),
(5, 87, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ', NULL, 'O you who have believed, do not prohibit the good things which Allāh has made lawful to you and do not transgress. Indeed, Allāh does not like transgressors.', 'Wahai orang-orang yang beriman! Janganlah kamu haramkan benda-benda yang baik-baik yang telah dihalalkan oleh Allah bagi kamu, dan janganlah kamu melampaui batas (pada apa yang telah ditetapkan halalnya itu); kerana sesungguhnya Allah tidak suka kepada orang-orang yang melampaui batas.', FALSE, NULL, NULL, 122, 7, 49, 97, FALSE, 0, NULL),
(5, 88, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'وَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاتَّقُوا اللَّهَ الَّذِي أَنتُم بِهِ مُؤْمِنُونَ', NULL, 'And eat of what Allāh has provided for you [which is] lawful and good. And fear Allāh, in whom you are believers.', 'Dan makanlah dari rezeki yang telah diberikan Allah kepada kamu, iaitu yang halal lagi baik, dan bertaqwalah kepada Allah yang kepadaNya sahaja kamu beriman.', FALSE, NULL, NULL, 122, 7, 49, 97, FALSE, 0, NULL),
(5, 89, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', 'لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَٰلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'Allāh will not impose blame upon you for what is meaningless in your oaths, but He will impose blame upon you for [breaking] what you intended of oaths. So its expiation is the feeding of ten needy people from the average of that which you feed your [own] families or clothing them or the freeing of a slave. But whoever cannot find [or afford it] - then a fast of three days [is required]. That is the expiation for oaths when you have sworn. But guard your oaths. Thus does Allāh make clear to you His verses [i.e., revealed law] that you may be grateful.', 'Kamu tidak dikira salah oleh Allah tentang sumpah-sumpah kamu yang tidak disengajakan (untuk bersumpah), akan tetapi kamu dikira salah olehNya dengan sebab sumpah yang sengaja kamu buat dengan bersungguh-sungguh. Maka bayaran dendanya ialah memberi makan sepuluh orang miskin dari jenis makanan yang sederhana yang kamu (biasa) berikan kepada keluarga kamu, atau memberi pakaian untuk mereka, atau memerdekakan seorang hamba. Kemudian sesiapa yang tidak dapat (menunaikan denda yang tersebut), maka hendaklah ia berpuasa tiga hari. Yang demikian itu ialah denda penebus sumpah kamu apabila kamu bersumpah. Dan jagalah - peliharalah sumpah kamu. Demikianlah Allah menerangkan kepada kamu ayat-ayatNya (hukum-hukum ugamaNya) supaya kamu bersyukur.', FALSE, NULL, NULL, 122, 7, 49, 97, FALSE, 0, NULL),
(5, 90, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنصَابُ وَالْأَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, indeed, intoxicants, gambling, [sacrificing on] stone alters [to other than Allāh], and divining arrows are but defilement from the work of Satan, so avoid it that you may be successful.', 'Wahai orang-orang yang beriman! Bahawa sesungguhnya arak, dan judi, dan pemujaan berhala, dan mengundi nasib dengan batang-batang anak panah, adalah (semuanya) kotor (keji) dari perbuatan Syaitan. Oleh itu hendaklah kamu menjauhinya supaya kamu berjaya.', FALSE, NULL, NULL, 123, 7, 49, 97, FALSE, 0, NULL),
(5, 91, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ فَهَلْ أَنتُم مُّنتَهُونَ', 'إِنَّمَا يُرِيدُ الشَّيْطَانُ أَن يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنتُم مُّنتَهُونَ', NULL, 'Satan only wants to cause between you animosity and hatred through intoxicants and gambling and to avert you from the remembrance of Allāh and from prayer. So will you not desist?', 'Sesungguhnya Syaitan itu hanyalah bermaksud mahu menimbulkan permusuhan dan kebencian di antara kamu dengan sebab arak dan judi, dan mahu memalingkan kamu daripada mengingati Allah dan daripada mengerjakan sembahyang. Oleh itu, mahukah kamu berhenti (daripada melakukan perkara-perkara yang keji dan kotor itu atau kamu masih berdegil)?', FALSE, NULL, NULL, 123, 7, 49, 97, FALSE, 0, NULL),
(5, 92, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وَأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَاحْذَرُوا فَإِن تَوَلَّيْتُمْ فَاعْلَمُوا أَنَّمَا عَلَىٰ رَسُولِنَا الْبَلَاغُ الْمُبِينُ', NULL, 'And obey Allāh and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification.', 'Dan taatlah kamu kepada Allah serta taatlah kepada Rasul Allah, dan awaslah (janganlah sampai menyalahi perintah Allah dan RasulNya). Oleh itu, jika kamu berpaling (enggan menurut apa yang diperintahkan itu), maka ketahuilah, bahawa sesungguhnya kewajipan Rasul Kami hanyalah menyampaikan (perintah-perintah) dengan jelas nyata.', FALSE, NULL, NULL, 123, 7, 49, 97, FALSE, 0, NULL),
(5, 93, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا إِذَا مَا اتَّقَوا وَّآمَنُوا وَعَمِلُوا الصَّالِحَاتِ ثُمَّ اتَّقَوا وَّآمَنُوا ثُمَّ اتَّقَوا وَّأَحْسَنُوا وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ', NULL, 'There is not upon those who believe and do righteousness [any] blame concerning what they have eaten [in the past] if they [now] fear Allāh and believe and do righteous deeds, and then fear Allāh and believe, and then fear Allāh and do good; and Allāh loves the doers of good.', 'Tidak ada dosa bagi orang-orang yang beriman serta mengerjakan amal yang soleh pada apa yang telah mereka makan dahulu, apabila mereka bertaqwa dan beriman serta mengerjakan amal yang soleh, kemudian mereka tetap bertaqwa dan beriman, kemudian mereka tetap bertaqwa dan berbuat kebajikan; kerana Allah mengasihi orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 123, 7, 49, 97, FALSE, 0, NULL),
(5, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَيَبْلُوَنَّكُمُ اللَّهُ بِشَيْءٍ مِّنَ الصَّيْدِ تَنَالُهُ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ اللَّهُ مَن يَخَافُهُ بِالْغَيْبِ فَمَنِ اعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ', NULL, 'O you who have believed, Allāh will surely test you through something of the game that your hands and spears [can] reach, that Allāh may make evident those who fear Him unseen. And whoever transgresses after that - for him is a painful punishment.', 'Wahai orang-orang yang beriman! Demi sesungguhnya Allah akan menguji kamu (semasa kamu berihram) dengan sesuatu dari binatang buruan yang mudah ditangkap oleh tangan kamu dan (mudah terkena) tikaman lembing-lembing kamu, supaya Allah ketahui wujudnya sesiapa yang takut kepadaNya semasa ia tidak melihatNya semasa ia tidak dilihat orang. Oleh itu, sesiapa yang melampaui batas sesudah yang demikian maka baginya azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 123, 7, 49, 98, FALSE, 0, NULL),
(5, 95, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ عَفَا ٱللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْتُلُوا الصَّيْدَ وَأَنتُمْ حُرُمٌ وَمَن قَتَلَهُ مِنكُم مُّتَعَمِّدًا فَجَزَاءٌ مِّثْلُ مَا قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِهِ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًا بَالِغَ الْكَعْبَةِ أَوْ كَفَّارَةٌ طَعَامُ مَسَاكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِ عَفَا اللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنتَقِمُ اللَّهُ مِنْهُ وَاللَّهُ عَزِيزٌ ذُو انتِقَامٍ', NULL, 'O you who have believed, do not kill game while you are in the state of iḥrām. And whoever of you kills it intentionally - the penalty is an equivalent from sacrificial animals to what he killed, as judged by two just men among you as an offering [to Allāh] delivered to the Kaʿbah, or an expiation: the feeding of needy people or the equivalent of that in fasting, that he may taste the consequence of his matter [i.e., deed]. Allāh has pardoned what is past; but whoever returns [to violation], then Allāh will take retribution from him. And Allāh is Exalted in Might and Owner of Retribution.', 'Wahai orang-orang yang beriman! Janganlah kamu membunuh binatang-binatang buruan ketika kamu sedang berihram. Dan sesiapa di antara kamu yang membunuhnya dengan sengaja, maka dendanya (menggantinya) dengan binatang ternak yang sama dengan binatang buruan yang dibunuh itu, yang ditetapkan hukumnya oleh dua orang yang adil di antara kamu, sebagai hadiah yang disampaikan ke Kaabah (untuk disembelih dan dibahagikan kepada fakir miskin di Tanah Suci), atau bayaran kaffarah, iaitu memberi makan orang-orang miskin, atau berpuasa sebanyak bilangan cupak yang diberikan kepada orang miskin; supaya dapat ia merasai kesan yang buruk dari perbuatannya. Allah maafkan apa yang telah lalu; dan sesiapa yang mengulangi (kesalahan itu) maka Allah akan menyeksanya; dan (ingatlah) Allah Maha Kuasa, lagi Berkuasa membalas dengan azab seksa.', FALSE, NULL, NULL, 123, 7, 49, 98, FALSE, 0, NULL),
(5, 96, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًا لَّكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَّكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا وَاتَّقُوا اللَّهَ الَّذِي إِلَيْهِ تُحْشَرُونَ', NULL, 'Lawful to you is game from the sea and its food as provision for you and the travelers, but forbidden to you is game from the land as long as you are in the state of iḥrām. And fear Allāh to whom you will be gathered.', 'Dihalalkan bagi kamu binatang buruan laut, dan makanan yang didapati dari laut, sebagai bekalan bagi kamu (untuk dinikmati kelazatannya) dan juga bagi orang-orang yang dalam pelayaran; tetapi diharamkan atas kamu memburu binatang buruan darat selama kamu sedang berihram. Oleh itu, bertaqwalah kepada Allah, yang kepadaNya kamu akan dihimpunkan.', FALSE, NULL, NULL, 124, 7, 49, 98, FALSE, 0, NULL),
(5, 97, 'جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'جَعَلَ اللَّهُ الْكَعْبَةَ الْبَيْتَ الْحَرَامَ قِيَامًا لِّلنَّاسِ وَالشَّهْرَ الْحَرَامَ وَالْهَدْيَ وَالْقَلَائِدَ ذَٰلِكَ لِتَعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'Allāh has made the Kaʿbah, the Sacred House, standing for the people and [has sanctified] the sacred months and the sacrificial animals and the garlands [by which they are identified]. That is so you may know that Allāh knows what is in the heavens and what is in the earth and that Allāh is Knowing of all things.', 'Allah menjadikan Kaabah, rumah yang mulia itu, sebagai tempat tumpuan manusia (untuk menjalankan ibadat dan hal-hal hidup), demikian juga bulan-bulan yang mulia, dan binatang-binatang korban, dan kalong-kalong binatang korban itu. Yang demikian itu, supaya kamu ketahui bahawa sesungguhnya Allah mengetahui apa yang ada di langit dan apa yang ada di bumi, dan bahawa sesungguhnya Allah Maha mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 124, 7, 50, 98, FALSE, 0, NULL),
(5, 98, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'اعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ وَأَنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'Know that Allāh is severe in penalty and that Allāh is Forgiving and Merciful.', 'Ketahuilah oleh kamu, bahawasanya Allah Maha berat azab seksaNya (kepada orang yang kufur dan derhaka), dan bahawasanya Allah Maha Pengampun lagi Maha Mengasihani (bagi orang yang mengerjakan suruhanNya dan meninggalkan laranganNya).', FALSE, NULL, NULL, 124, 7, 50, 98, FALSE, 0, NULL),
(5, 99, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'مَّا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', NULL, 'Not upon the Messenger is [responsibility] except [for] notification. And Allāh knows whatever you reveal and whatever you conceal.', 'Tidak ada kewajipan yang ditugaskan kepada Rasulullah selain daripada menyampaikan (perintah-perintah Allah) sahaja; dan Allah sentiasa mengetahui apa yang kamu lahirkan dan apa yang kamu sembunyikan.', FALSE, NULL, NULL, 124, 7, 50, 98, FALSE, 0, NULL),
(5, 100, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', 'قُل لَّا يَسْتَوِي الْخَبِيثُ وَالطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ الْخَبِيثِ فَاتَّقُوا اللَّهَ يَا أُولِي الْأَلْبَابِ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'Say, "Not equal are the evil and the good, although the abundance of evil might impress you." So fear Allāh, O you of understanding, that you may be successful.', 'Katakanlah (wahai Muhammad): “Tidak sama yang buruk dengan yang baik, walaupun banyaknya yang buruk itu menarik hatimu. Oleh itu bertaqwalah kepada Allah wahai orang-orang yang berakal fikiran, supaya kamu berjaya.', FALSE, NULL, NULL, 124, 7, 50, 98, FALSE, 0, NULL),
(5, 101, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا وَٱللَّهُ غَفُورٌ حَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ عَفَا اللَّهُ عَنْهَا وَاللَّهُ غَفُورٌ حَلِيمٌ', NULL, 'O you who have believed, do not ask about things which, if they are shown to you, will distress you. But if you ask about them while the Qur’ān is being revealed, they will be shown to you. Allāh has pardoned it [i.e., that which is past]; and Allāh is Forgiving and Forbearing.', 'Wahai orang-orang yang beriman! Janganlah kamu bertanyakan (kepada Nabi) perkara-perkara yang jika diterangkan kepada kamu akan menyusahkan kamu, dan jika kamu bertanya mengenainya ketika diturunkan Al-Quran, tentulah akan diterangkan kepada kamu. Allah maafkan (kamu) dari (kesalahan bertanyakan) perkara-perkara itu (yang tidak dinyatakan di dalam Al-Quran); kerana Allah Maha pengampun, lagi Maha penyabar.', FALSE, NULL, NULL, 124, 7, 50, 99, FALSE, 0, NULL),
(5, 102, 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا بِهَا كَافِرِينَ', NULL, 'A people asked such [questions] before you; then they became thereby disbelievers.', 'Sesungguhnya perkara-perkara yang serupa itu pernah ditanyakan (kepada Nabi mereka) oleh suatu kaum dahulu sebelum kamu, kemudian mereka menjadi kafir dengan sebab pertanyaan itu (kerana setelah diterangkan, mereka tidak menerimanya).', FALSE, NULL, NULL, 124, 7, 50, 99, FALSE, 0, NULL),
(5, 103, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', 'مَا جَعَلَ اللَّهُ مِن بَحِيرَةٍ وَلَا سَائِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', NULL, 'Allāh has not appointed [such innovations as] baḥīrah or sā’ibah or waṣīlah or ḥām. But those who disbelieve invent falsehood about Allāh, and most of them do not reason.', 'Allah tidak sekali-kali mensyariatkan Bahirah, tidak juga Saa''ibah, tidak juga Wasilah dan tidak juga Haam. Akan tetapi orang-orang kafir itu sentiasa mengada-adakan perkara dusta terhadap Allah; dan kebanyakan mereka tidak menggunakan akal fikirannya', FALSE, NULL, NULL, 124, 7, 50, 99, FALSE, 0, NULL),
(5, 104, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَىٰ مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ قَالُوا حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْلَمُونَ شَيْئًا وَلَا يَهْتَدُونَ', NULL, 'And when it is said to them, "Come to what Allāh has revealed and to the Messenger," they say, "Sufficient for us is that upon which we found our fathers." Even though their fathers knew nothing, nor were they guided?', 'Dan apabila dikatakan kepada mereka: “Marilah menurut kepada apa yang telah diturunkan oleh Allah (Al-Quran), dan kepada RasulNya (yang menyampaikannya)”, mereka menjawab: “Cukuplah bagi kami apa yang kami dapati datuk nenek kami mengerjakannya”. Adakah (mereka akan menurut juga) sekalipun datuk nenek mereka tidak mengetahui apa-apa dan tidak pula mendapat hidayah petunjuk?', FALSE, NULL, NULL, 125, 7, 50, 99, FALSE, 0, NULL),
(5, 105, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا اهْتَدَيْتُمْ إِلَى اللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'O you who have believed, upon you is [responsibility for] yourselves. Those who have gone astray will not harm you when you have been guided. To Allāh is your return all together; then He will inform you of what you used to do.', 'Wahai orang-orang yang beriman! Jagalah sahaja diri kamu (dari melakukan sesuatu yang dilarang oleh Allah). Orang-orang yang sesat tidak akan mendatangkan mudarat kepada kamu apabila kamu sendiri telah mendapat hidayah petunjuk (taat mengerjakan suruhan Allah dan meninggalkan laranganNya). Kepada Allah jualah tempat kembali kamu semuanya, kemudian Ia akan menerangkan kepada kamu (balasan) apa yang kamu telah lakukan.', FALSE, NULL, NULL, 125, 7, 50, 99, FALSE, 0, NULL),
(5, 106, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ آخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِي الْأَرْضِ فَأَصَابَتْكُم مُّصِيبَةُ الْمَوْتِ تَحْبِسُونَهُمَا مِن بَعْدِ الصَّلَاةِ فَيُقْسِمَانِ بِاللَّهِ إِنِ ارْتَبْتُمْ لَا نَشْتَرِي بِهِ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ وَلَا نَكْتُمُ شَهَادَةَ اللَّهِ إِنَّا إِذًا لَّمِنَ الْآثِمِينَ', NULL, 'O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allāh if you doubt [their testimony, saying], "We will not exchange it [i.e., our oath] for a price [i.e., worldly gain], even if he should be a near relative, and we will not withhold the testimony of [i.e., ordained by] Allāh. Indeed, we would then be of the sinful."', 'Wahai orang-orang yang beriman! Apabila salah seorang di antara kamu hampir mati, ketika (ia mahu) berwasiat, hendaklah wasiatnya itu disaksikan oleh dua orang yang adil di antara kamu, atau dua orang lain (yang bukan seugama) dengan kamu, jika kamu dalam pelayaran di muka bumi lalu kamu ditimpa bencana sakit yang membawa maut. Kalau kamu ragu-ragu tentang kejujuran kedua saksi itu, hendaklah) kamu tahan mereka sesudah selesai sembahyang, kemudian mereka (disuruh) bersumpah dengan nama Allah (dengan berkata: “Demi Allah) kami tidak akan menjual sumpah kami untuk mendapat sesuatu harta benda, walaupun orang itu dari kaum kerabat, dan kami tidak menyembunyikan (keterangan yang kami ketahui) sebagai saksi (sebagaimana yang diperintahkan oleh) Allah, (kerana jika kami menyembunyikannya) tentulah kami dengan itu termasuk dalam golongan orang-orang yang berdosa”.', FALSE, NULL, NULL, 125, 7, 50, 99, FALSE, 0, NULL),
(5, 107, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'فَإِنْ عُثِرَ عَلَىٰ أَنَّهُمَا اسْتَحَقَّا إِثْمًا فَآخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ الَّذِينَ اسْتَحَقَّ عَلَيْهِمُ الْأَوْلَيَانِ فَيُقْسِمَانِ بِاللَّهِ لَشَهَادَتُنَا أَحَقُّ مِن شَهَادَتِهِمَا وَمَا اعْتَدَيْنَا إِنَّا إِذًا لَّمِنَ الظَّالِمِينَ', NULL, 'But if it is found that those two were guilty of sin [i.e., perjury], let two others stand in their place [who are] foremost [in claim] from those who have a lawful right. And let them swear by Allāh, "Our testimony is truer than their testimony, and we have not transgressed. Indeed, we would then be of the wrongdoers."', 'Kemudian jika didapati bahawa kedua saksi itu (sesudah bersumpah) ada melakukan dosa (kerana berdusta atau mengkhianati dalam perkara yang mereka menjadi saksi itu), maka hendaklah dua orang yang lain menggantikan tempat mereka dari waris-waris si mati lebih dekat, yang lebih berhak (menuntut dan memberi keterangan yang sebenarnya), kemudian mereka bersumpah dengan nama Allah (dengan berkata): “Demi sesungguhnya, persaksian kami lebih berhak diterima daripada persaksian kedua saksi itu (yang telah nyata berdusta), dan kami tidak melampaui batas, (kerana jika kami berbuat demikian) tentulah kami dengan itu termasuk dalam golongan orang-orang yang zalim.', FALSE, NULL, NULL, 125, 7, 50, 99, FALSE, 0, NULL),
(5, 108, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'ذَٰلِكَ أَدْنَىٰ أَن يَأْتُوا بِالشَّهَادَةِ عَلَىٰ وَجْهِهَا أَوْ يَخَافُوا أَن تُرَدَّ أَيْمَانٌ بَعْدَ أَيْمَانِهِمْ وَاتَّقُوا اللَّهَ وَاسْمَعُوا وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ', NULL, 'That is more likely that they will give testimony according to its [true] objective, or [at least] they would fear that [other] oaths might be taken after their oaths. And fear Allāh and listen [i.e., obey Him]; and Allāh does not guide the defiantly disobedient people.', '(Hukum-hukum dan peraturan menjadi saksi) yang tersebut itu adalah jalan yang lebih dekat untuk mereka memberi keterangan persaksian menurut cara yang sebenarnya, atau untuk mereka merasa takut akan ditolak sumpah mereka (kepada waris-waris si mati) sesudah mereka bersumpah (yang akan mendedahkan kecurangan mereka). Oleh itu bertaqwalah kepada Allah, dan dengarlah dengan patuh (segala perintahNya), dan (ingatlah) Allah tidak memberi hidayah petunjuk kepada kaum yang fasik.', FALSE, NULL, NULL, 125, 7, 50, 99, FALSE, 0, NULL),
(5, 109, 'يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'يَوْمَ يَجْمَعُ اللَّهُ الرُّسُلَ فَيَقُولُ مَاذَا أُجِبْتُمْ قَالُوا لَا عِلْمَ لَنَا إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ', NULL, '[Be warned of] the Day when Allāh will assemble the messengers and say, "What was the response you received?" They will say, "We have no knowledge. Indeed, it is You who is Knower of the unseen" -', '(Ingatlah) hari (kiamat yang padanya) Allah menghimpunkan Rasul-rasulNya lalu bertanya: “Apakah penerimaan yang diberikan kepada kamu (oleh umat-umat kamu dahulu, ketika kamu menyampaikan seruan ugama Allah)?” Rasul-rasul itu menjawab: “Tidak ada bagi kami pengetahuan yang sah tentang itu, (pengetahuan yang tepat adalah tertentu bagiMu), kerana sesungguhnya Engkaulah sahaja yang Maha Mengetahui akan segala perkara yang ghaib”', FALSE, NULL, NULL, 126, 7, 51, 100, FALSE, 0, NULL),
(5, 110, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'إِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ اذْكُرْ نِعْمَتِي عَلَيْكَ وَعَلَىٰ وَالِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ الْقُدُسِ تُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلًا وَإِذْ عَلَّمْتُكَ الْكِتَابَ وَالْحِكْمَةَ وَالتَّوْرَاةَ وَالْإِنجِيلَ وَإِذْ تَخْلُقُ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ بِإِذْنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًا بِإِذْنِي وَتُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ بِإِذْنِي وَإِذْ تُخْرِجُ الْمَوْتَىٰ بِإِذْنِي وَإِذْ كَفَفْتُ بَنِي إِسْرَائِيلَ عَنكَ إِذْ جِئْتَهُم بِالْبَيِّنَاتِ فَقَالَ الَّذِينَ كَفَرُوا مِنْهُمْ إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ', NULL, '[The Day] when Allāh will say, "O Jesus, Son of Mary, remember My favor upon you and upon your mother when I supported you with the Pure Spirit [i.e., the angel Gabriel] and you spoke to the people in the cradle and in maturity; and [remember] when I taught you writing and wisdom and the Torah and the Gospel; and when you designed from clay [what was] like the form of a bird with My permission, then you breathed into it, and it became a bird with My permission; and you healed the blind [from birth] and the leper with My permission; and when you brought forth the dead with My permission; and when I restrained the Children of Israel from [killing] you when you came to them with clear proofs and those who disbelieved among them said, "This is not but obvious magic."', '(Ingatlah) ketika Allah berfirman: “Wahai Isa ibni Maryam! Kenanglah nikmatKu kepadamu dan kepada ibumu, ketika Aku menguatkanmu dengan Ruhul-Qudus (Jibril), iaitu engkau dapat berkata-kata dengan manusia (semasa engkau masih kecil) dalam buaian dan sesudah dewasa; dan (ingatlah) ketika Aku mengajarmu menulis membaca, dan hikmat pengetahuan, khasnya Kitab Taurat dan Kitab Injil; dan (ingatlah) ketika engkau jadikan dari tanah seperti bentuk burung dengan izinKu, kemudian engkau tiupkan padanya, lalu menjadilah ia seekor burung dengan izinku; dan (ingatlah ketika) engkau menyembuhkan orang buta dan orang sopak dengan izinku; dan (ingatlah) ketika engkau menghidupkan orang-orang yang mati dengan izinKu; dan (ingatlah) ketika Aku menghalangi Bani Israil daripada membunuhmu, ketika engkau datang kepada mereka dengan membawa keterangan-keterangan (mukjizat), lalu orang-orang yang kafir di antara mereka berkata: “Bahawa ini hanyalah sihir yang terang nyata”', FALSE, NULL, NULL, 126, 7, 51, 100, FALSE, 0, NULL),
(5, 111, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', 'وَإِذْ أَوْحَيْتُ إِلَى الْحَوَارِيِّينَ أَنْ آمِنُوا بِي وَبِرَسُولِي قَالُوا آمَنَّا وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ', NULL, 'And [remember] when I inspired to the disciples, "Believe in Me and in My messenger [i.e., Jesus]." They said, "We have believed, so bear witness that indeed we are Muslims [in submission to Allāh]."', 'Dan (ingatlah) ketika Aku ilhamkan kepada orang-orang Hawariyyiin (sahabat-sahabat karib nabi Isa): “Berimanlah kamu kepadaku dan kepada RasulKu!” Mereka menjawab: “Kami telah beriman, dan saksikanlah, bahawa sesungguhnya kami orang-orang Islam (yang menyerah diri kepada Allah)”', FALSE, NULL, NULL, 126, 7, 51, 100, FALSE, 0, NULL),
(5, 112, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'إِذْ قَالَ الْحَوَارِيُّونَ يَا عِيسَى ابْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ قَالَ اتَّقُوا اللَّهَ إِن كُنتُم مُّؤْمِنِينَ', NULL, '[And remember] when the disciples said, "O Jesus, Son of Mary, can your Lord send down to us a table [spread with food] from the heaven?" [Jesus] said, "Fear Allāh, if you should be believers."', 'Dan (ingatlah) ketika orang orang Hawariyyiin berkata: “Wahai Isa Ibni Maryam! Dapatkah kiranya Tuhanmu berkenan menurunkan kepada kami satu hidangan dari langit?” Nabi Isa menjawab: “Bertaqwalah kamu kepada Allah jika benar kamu orang-orang yang beriman”.', FALSE, NULL, NULL, 126, 7, 51, 100, FALSE, 0, NULL),
(5, 113, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 'قَالُوا نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ الشَّاهِدِينَ', NULL, 'They said, "We wish to eat from it and let our hearts be reassured and know that you have been truthful to us and be among its witnesses."', 'Mereka berkata: “Kami hanya ingin hendak makan dari hidangan itu (untuk mengambil berkat), dan supaya tenang tenteram hati kami, dan juga supaya kami ketahui dengan yakin, bahawa sesungguhnya engkau telah berkata benar kepada kami, dan supaya menjadilah kami orang-orang yang menyaksikannya sendiri”', FALSE, NULL, NULL, 126, 7, 51, 100, FALSE, 0, NULL),
(5, 114, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', 'قَالَ عِيسَى ابْنُ مَرْيَمَ اللَّهُمَّ رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنكَ وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ', NULL, 'Said Jesus, the son of Mary, "O Allāh, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers."', 'Isa ibni Maryam (pun berdoalah ke hadrat Allah dengan) berkata: Ya Allah, Tuhan kami! Turunkanlah kiranya kepada kami satu hidangan dari langit, untuk menjadi hari raya bagi kami, iaitu bagi kami yang ada hari ini dan bagi orang-orang kami yang datang kemudian, dan sebagai satu tanda (mukjizat) daripadamu (yang menunjukkan kebesaran dan kekuasaanMu); dan kurniakanlah rezeki kepada kami, kerana Engkau jualah sebaik-baik Pemberi rezeki”.', FALSE, NULL, NULL, 127, 7, 51, 100, FALSE, 0, NULL),
(5, 115, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', 'قَالَ اللَّهُ إِنِّي مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّي أُعَذِّبُهُ عَذَابًا لَّا أُعَذِّبُهُ أَحَدًا مِّنَ الْعَالَمِينَ', NULL, 'Allāh said, "Indeed, I will send it down to you, but whoever disbelieves afterwards from among you - then indeed will I punish him with a punishment by which I have not punished anyone among the worlds."', 'Allah berfirman: “Sesungguhnya Aku akan menurunkan hidangan itu berulang-ulang kepada kamu, kemudian sesiapa di antara kamu kufur ingkar sesudah (turunnya hidangan itu), maka sesungguhnya Aku akan menyeksanya dengan azab sengsara yang tidak pernah Aku seksakan seseorang pun dari sekalian makhluk”.', FALSE, NULL, NULL, 127, 7, 51, 100, FALSE, 0, NULL),
(5, 116, 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَٰهَيْنِ مِن دُونِ اللَّهِ قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ', NULL, 'And [beware the Day] when Allāh will say, "O Jesus, Son of Mary, did you say to the people, ''Take me and my mother as deities besides Allāh?''" He will say, "Exalted are You! It was not for me to say that to which I have no right. If I had said it, You would have known it. You know what is within myself, and I do not know what is within Yourself. Indeed, it is You who is Knower of the unseen.', 'Dan (ingatlah) ketika Allah berfirman: “Wahai Isa ibni Maryam! Engkaukah yang berkata kepada manusia: ‘Jadikanlah daku dan ibuku dua tuhan selain dari Allah?’” Nabi ‘Isa menjawab: “Maha Suci Engkau (wahai Tuhan)! Tidaklah layak bagiku mengatakan sesuatu yang aku tidak berhak (mengatakannya). Jika aku ada mengatakannya, maka tentulah Engkau telah mengetahuinya. Engkau mengetahui apa yang ada pada diriku, sedang aku tidak mengetahui apa yang ada pada diriMu; kerana sesungguhnya Engkau jualah Yang Maha Mengetahui perkara-perkara yang ghaib.', FALSE, NULL, NULL, 127, 7, 51, 101, FALSE, 0, NULL),
(5, 117, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'مَا قُلْتُ لَهُمْ إِلَّا مَا أَمَرْتَنِي بِهِ أَنِ اعْبُدُوا اللَّهَ رَبِّي وَرَبَّكُمْ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنتَ أَنتَ الرَّقِيبَ عَلَيْهِمْ وَأَنتَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ', NULL, 'I said not to them except what You commanded me - to worship Allāh, my Lord and your Lord. And I was a witness over them as long as I was among them; but when You took me up, You were the Observer over them, and You are, over all things, Witness.', '“Aku tidak mengatakan kepada mereka melainkan apa yang Engkau perintahkan kepadaku mengatakannya, iaitu: ‘Sembahlah kamu akan Allah, Tuhanku dan Tuhan kamu ’ dan adalah aku menjadi pengawas terhadap mereka (dengan membenarkan yang benar dan menyalahkan yang salah) selama aku berada dalam kalangan mereka; kemudian apabila Engkau sempurnakan tempohku, menjadilah Engkau sendiri yang mengawasi keadaan mereka, dan Engkau jualah yang menjadi Saksi atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 127, 7, 51, 101, FALSE, 0, NULL),
(5, 118, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ', NULL, 'If You should punish them - indeed they are Your servants; but if You forgive them - indeed it is You who is the Exalted in Might, the Wise."', '“Jika Engkau menyeksa mereka, (maka tidak ada yang menghalanginya) kerana sesungguhnya mereka adalah hamba-hambaMu; dan jika Engkau mengampunkan mereka, maka sesungguhnya Engkaulah sahaja yang Maha Kuasa, lagi Maha Bijaksana”', FALSE, NULL, NULL, 127, 7, 51, 101, FALSE, 0, NULL),
(5, 119, 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'قَالَ اللَّهُ هَٰذَا يَوْمُ يَنفَعُ الصَّادِقِينَ صِدْقُهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَٰلِكَ الْفَوْزُ الْعَظِيمُ', NULL, 'Allāh will say, "This is the Day when the truthful will benefit from their truthfulness." For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allāh being pleased with them, and they with Him. That is the great attainment.', 'Allah berfirman: “Inilah hari (kiamat) yang (padanya) orang-orang yang benar (pada tutur kata dan amal perbuatan) mendapat manfaat dari kebenaran mereka; mereka beroleh Syurga-syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya selama-lamanya. Allah reda akan mereka dan mereka pula reda akan Dia. Itulah kejayaan yang amat besar”.', FALSE, NULL, NULL, 127, 7, 51, 101, FALSE, 0, NULL),
(5, 120, 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ', 'لِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'To Allāh belongs the dominion of the heavens and the earth and whatever is within them. And He is over all things competent.', 'Allah jualah yang menguasai alam langit dan bumi serta segala yang ada padanya; dan Dia lah jua yang Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 127, 7, 51, 101, FALSE, 0, NULL),
(6, 1, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', 'الحمد لله الذي خلق السماوات والارض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون', NULL, '[All] praise is [due] to Allāh, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.', 'Segala puji tertentu bagi Allah yang menciptakan langit dan bumi, dan menjadikan gelap dan terang; dalam pada itu, orang-orang kafir menyamakan (sesuatu yang lain) dengan tuhan mereka.', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 14, NULL),
(6, 2, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا ۖ وَأَجَلٌ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ', 'هو الذي خلقكم من طين ثم قضى اجلا واجل مسمى عنده ثم انتم تمترون', NULL, 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.', 'Dia lah yang menciptakan kamu dari tanah, kemudian Ia tentukan ajal (kematian kamu) dan satu ajal lagi yang tertentu di sisiNya (iaitu masa yang telah ditetapkan untuk dibangkitkan kamu semula pada hari kiamat); dalam pada itu, kamu masih ragu-ragu (tentang hari pembalasan).', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 14, NULL),
(6, 3, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', 'وهو الله في السماوات وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون', NULL, 'And He is Allāh, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.', 'Dan Dia lah Allah (yang disembah dan diakui kekuasaanNya) di langit dan di bumi; Ia mengetahui apa yang kamu rahsiakan dan apa yang kamu lahirkan, dan Ia juga mengetahui apa yang kamu usahakan.', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 12, NULL),
(6, 4, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وما تاتيهم من اية من ايات ربهم الا كانوا عنها معرضين', NULL, 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.', 'Dan tidak ada sesuatu keterangan yang sampai kepada mereka (yang kafir) dari keterangan-keterangan Tuhan mereka, melainkan mereka selalu berpaling daripadanya (enggan menerimanya).', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 11, NULL),
(6, 5, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فقد كذبوا بالحق لما جاءهم فسوف ياتيهم انباء ما كانوا به يستهزئون', NULL, 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.', 'Sesungguhnya mereka telah mendustakan kebenaran (Al-Quran) ketika ia sampai kepada mereka. Oleh itu, akan datanglah kepada mereka berita (yang membuktikan kebenaran) apa yang mereka selalu ejek-ejek itu (iaitu mereka akan ditimpa bala bencana).', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 12, NULL),
(6, 6, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَـٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'الم يروا كم اهلكنا من قبلهم من قرن مكناهم في الارض ما لم نمكن لكم وارسلنا السماء عليهم مدرارا وجعلنا الانهار تجري من تحتهم فاهلكناهم بذنوبهم وانشانا من بعدهم قرنا اخرين', NULL, 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.', 'Tidakkah mereka memerhati dan memikirkan berapa banyak umat-umat yang telah Kami binasakan sebelum mereka, padahal (umat-umat itu) telah Kami teguhkan kedudukan mereka di muka bumi (dengan kekuasaan dan kemewahan) yang tidak Kami berikan kepada kamu, dan Kami turunkan hujan atas mereka dengan lebatnya, dan Kami jadikan sungai-sungai mengalir di bawah mereka, kemudian Kami binasakan mereka dengan sebab dosa mereka mereka, dan Kami ciptakan sesudah mereka, umat yang lain?', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 31, NULL),
(6, 7, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَـٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'ولو نزلنا عليك كتابا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين', NULL, 'And even if We had sent down to you, [O Muḥammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."', 'Dan kalau Kami turunkan kepadamu (wahai Muhammad) sebuah kitab (yang bertulis) pada kertas, lalu mereka memegangnya dengan tangan mereka, nescaya orang-orang yang kafir itu berkata: “Ini tidak lain, hanyalah sihir yang terang nyata”.', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 16, NULL),
(6, 8, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ ۖ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', 'وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون', NULL, 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.', 'Dan mereka berkata: “Mengapa tidak diturunkan malaikat kepadanya?” padahal kalau Kami turunkan malaikat nescaya selesailah perkara itu (kerana mereka tetap berdegil dan tidak akan beriman), kemudian mereka tidak diberi tempoh (lalu dibinasakan dengan bala bencana secara mengejut).', FALSE, NULL, NULL, 128, 7, 51, 102, FALSE, 13, NULL),
(6, 9, 'وَلَوْ جَعَلْنَـٰهُ مَلَكًا لَّجَعَلْنَـٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 'ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون', NULL, 'And if We had made him [i.e., the messenger] an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves [i.e., confusion and doubt].', 'Dan kalau (Rasul) itu Kami jadikan malaikat, tentulah Kami jadikan dia berupa seorang lelaki (supaya mereka dapat melihatnya), dan tentulah Kami (dengan yang demikian) menyebabkan mereka kesamaran sebagaimana mereka sengaja membuat-buat kesamaran (tentang kebenaran Nabi Muhammad s.a.w).', FALSE, NULL, NULL, 129, 7, 51, 102, FALSE, 9, NULL),
(6, 10, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون', NULL, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.', 'Dan demi sesungguhnya! Telah diperolok-olok beberapa Rasul sebelummu, lalu orang-orang yang mengejek-ejek di antara mereka ditimpakan (balasan azab) bagi apa yang mereka telah perolok-olokkan itu.', FALSE, NULL, NULL, 129, 7, 51, 102, FALSE, 13, NULL),
(6, 11, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ', 'قل سيروا في الارض ثم انظروا كيف كان عاقبة المكذبين', NULL, 'Say, "Travel through the land; then observe how was the end of the deniers."', 'Katakanlah (wahai Muhammad): “Mengembaralah kamu di muka bumi, kemudian perhatikanlah bagaimana akibat buruk (yang menimpa) orang-orang yang mendustakan (Rasul-rasul) itu.”', FALSE, NULL, NULL, 129, 7, 51, 103, FALSE, 10, NULL),
(6, 12, 'قُل لِّمَن مَّا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'قل لمن ما في السماوات والارض قل لله كتب على نفسه الرحمة ليجمعنكم الى يوم القيامة لا ريب فيه الذين خسروا انفسهم فهم لا يؤمنون', NULL, 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allāh." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.', 'Bertanyalah (wahai muhammad): “Hak milik siapakah segala yang ada di langit dan di bumi?” Katakanlah: “(Semuanya itu) adalah milik Allah. Ia telah menetapkan atas diriNya memberi rahmat. Demi sesungguhnya Ia akan menghimpunkan kamu pada hari kiamat yang tidak ada sebarang syak padanya”. Orang-orang yang merugikan diri sendiri (dangan mensia-siakan pengurniaan Allah), maka mereka (dengan sebab yang tersebut) tidak beriman.', FALSE, NULL, NULL, 129, 7, 51, 103, FALSE, 25, NULL),
(6, 13, '۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وله ما سكن في الليل والنهار وهو السميع العليم', NULL, 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.', 'Dan bagi Allah jualah apa yang ada pada waktu malam dan siang; dan Dia lah Yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 9, NULL),
(6, 14, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'قل اغير الله اتخذ وليا فاطر السماوات والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين', NULL, 'Say, "Is it other than Allāh I should take as a protector, Creator of the heavens and earth, while it is He who feeds and is not fed?" Say, [O Muḥammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allāh] and [was commanded], ''Do not ever be of the polytheists.''"', 'Katakanlah (wahai Muhammad): “Patutkah aku mengambil (memilih) pelindung yang lain dari Allah yang menciptakan langit dan bumi, dan Ia pula yang memberi makan dan bukan Ia yang diberi makan?” Katakanlah: “Sesungguhnya aku diperintahkan supaya menjadi orang yang pertama sekali menyerah diri kepada Allah (Islam), dan (aku diperintahkan dengan firmanNya): ‘Jangan sekali-kali engkau menjadi dari golongan orang-orang musyrik itu.’”', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 24, NULL),
(6, 15, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', NULL, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', 'Katakanlah: “Sesungguhnya aku takut jika aku derhaka kepada Tuhanku, (akan dikenakan) azab hari yang besar (hari kiamat)”.', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 9, NULL),
(6, 16, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 'من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين', NULL, 'He from whom it is averted that Day - [Allāh] has granted him mercy. And that is the clear attainment.', 'Sesiapa yang dijauhkan azab daripadanya pada hari itu, maka sesugguhnya Allah telah memberi rahmat kepadanya; dan itulah kejayaan yang jelas nyata.', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 9, NULL),
(6, 17, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو على كل شيء قدير', NULL, 'And if Allāh should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.', 'Dan jika Allah mengenakan (menimpakan) engkau dengan bahaya bencana, maka tidak ada sesiapa pun yang dapat menghapuskannya melainkan Dia sendiri; dan jika Ia mengenakan (melimpahkan) engkau dengan kebaikan, maka Ia adalah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 17, NULL),
(6, 18, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'وهو القاهر فوق عباده وهو الحكيم الخبير', NULL, 'And He is the subjugator over His servants. And He is the Wise, the Aware.', 'Dan Dia lah yang Berkuasa atas sekalian hambaNya (dangan tadbir dan takdir); dan Dia lah Yang Maha Bijaksana serta Amat Mendalam PengetahuanNya.', FALSE, NULL, NULL, 129, 7, 52, 103, FALSE, 7, NULL),
(6, 19, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَـٰدَةً ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَـٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'قل اي شيء اكبر شهادة قل الله شهيد بيني وبينكم واوحي الي هذا القران لانذركم به ومن بلغ ائنكم لتشهدون ان مع الله الهة اخرى قل لا اشهد قل انما هو اله واحد وانني بريء مما تشركون', NULL, 'Say, "What thing is greatest in testimony?" Say, "Allāh is witness between me and you. And this Qur’ān was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allāh there are other deities?" Say, "I will not testify [with you]." Say, "Indeed, He is but one God, and indeed, I am free of what you associate [with Him]."', 'Bertanyalah (wahai Muhammad): “Apakah sesuatu yang lebih besar persaksiannya?” (Bagi menjawabnya) katakanlah: “Allah menjadi Saksi antaraku dengan kamu, dan diwahyukan kepadaku Al-Quran ini, supaya aku memberi amaran dengannya kepada kamu dan juga (kepada) sesiapa yang telah sampai kepadanya seruan Al-Quran itu. Adakah kamu sungguh-sungguh mengakui bahawa ada beberapa tuhan yang lain bersama-sama Allah?” Katakanlah: “Aku tidak mengakuinya”. Katakanlah lagi: “Hanyasanya Dia lah sahaja Tuhan Yang Maha Esa, dan sesungguhnya aku adalah berlepas diri apa yang kamu sekutukan (dengan Allah Azza Wa Jalla)”.', FALSE, NULL, NULL, 130, 7, 52, 103, FALSE, 37, NULL),
(6, 20, 'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'الذين اتيناهم الكتاب يعرفونه كما يعرفون ابناءهم الذين خسروا انفسهم فهم لا يؤمنون', NULL, 'Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe.', 'Orang-orang (Yahudi dan Nasrani) yang telah Kami berikan kitab kepada mereka, mereka mengenalinya (Nabi Muhammad), sebagaimana mereka mengenali anak-anak mereka sendiri. Orang-orang yang merugikan diri sendiri (dengan mensia-siakan pengurniaan Allah), maka mereka (dengan sebab yang tersebut) tidak beriman.', FALSE, NULL, NULL, 130, 7, 52, 103, FALSE, 13, NULL),
(6, 21, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآيَاتِهِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', NULL, 'And who is more unjust than one who invents about Allāh a lie or denies His verses? Indeed, the wrongdoers will not succeed.', 'Dan siapakah lagi yang lebih aniaya dari orang yang mengada-adakan perkara-perkara yang dusta terhadap Allah, atau yang mendustakan ayat-ayat keteranganNya? Sesungguhnya orang-orang yang zalim itu tidak akan berjaya.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 22, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا أَيْنَ شُرَكَاؤُكُمُ الَّذِينَ كُنتُمْ تَزْعُمُونَ', NULL, 'And [mention, O Muḥammad], the Day We will gather them all together; then We will say to those who associated others with Allāh, "Where are your ''partners'' that you used to claim [with Him]?"', 'Dan (ingatlah), hari (kiamat yang padanya) Kami himpunkan mereka semua, kemudian Kami berfirman kepada orang-orang musyrik: “Manakah orang-orang dan benda-benda yang dahulu kamu sifatkan (menjadi sekutu Allah):?”', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 23, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّا أَن قَالُوا وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', NULL, 'Then there will be no [excuse upon] examination except they will say, "By Allāh, our Lord, we were not those who associated."', 'Kemudian tidaklah ada akidah kufur mereka selain dari mereka menjawab dengan dusta: “Demi Allah Tuhan kami, kami tidak pernah menjadi orang-orang yang mempersekutukan Allah (dengan sesuatu yang lain)”.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 24, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'انظُرْ كَيْفَ كَذَبُوا عَلَىٰ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'See how they will lie about themselves. And lost from them will be what they used to invent.', 'Lihatlah bagaimana mereka berdusta terhadap diri mereka sendiri, dan bagaimana hilang lenyapnya dari mereka apa yang telah mereka ada-adakan (sebagai sekutu Allah) itu.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 25, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن يَرَوْا كُلَّ آيَةٍ لَّا يُؤْمِنُوا بِهَا حَتَّىٰ إِذَا جَاءُوكَ يُجَادِلُونَكَ يَقُولُ الَّذِينَ كَفَرُوا إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ', NULL, 'And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, "This is not but legends of the former peoples."', 'Dan di antara mereka ada yang mendengarkanmu (membaca Al-Quran), pada hal Kami telah jadikan tutupan berlapis-lapis atas hati mereka, yang menghalang mereka daripada memahaminya, dan Kami jadikan pada telinga mereka penyumbat (yang menjadikan mereka pekak); dan kalaupun mereka melihat tiap-tiap keterangan (dan mukjizat yang membuktikan kebenaran Rasul), mereka tidak juga akan beriman kepada keterangan itu; sehingga apabila mereka datang kepadamu, sambil membantahmu, berkatalah orang-orang yang kafir itu: “Ini tidak lain hanyalah cerita-cerita dongeng orang-orang dahulu”.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 26, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْأَوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ', NULL, 'And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not.', 'Dan mereka pula melarang orang ramai dari mendengar Al-Quran dan mereka juga menjauhkan diri daripadanya, padahal mereka (dengan perbuatan yang demikian) hanyalah membinasakan diri sendiri (dengan bala bencana dan azab yang disediakan untuk mereka di dunia dan di akhirat kelak), sedang mereka tidak menyedarinya.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 27, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'وَلَوْ تَرَىٰ إِذْ وُقِفُوا عَلَى النَّارِ فَقَالُوا يَا لَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِآيَاتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِنِينَ', NULL, 'If you could but see when they are made to stand before the Fire and will say, "Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers."', 'Dan sungguh ngeri jika engkau melihat ketika mereka didirikan di tepi neraka (untuk menyaksikan azabnya yang tidak terperi), lalu mereka berkata: “Wahai kiranya kami dikembalikan ke dunia, dan kami tidak akan mendustakan lagi ayat-ayat keterangan Tuhan kami, dan menjadilah kami dari golongan yang beriman”.', FALSE, NULL, NULL, 130, 7, 52, 104, FALSE, 0, NULL),
(6, 28, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'بَلْ بَدَا لَهُم مَّا كَانُوا يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا لَعَادُوا لِمَا نُهُوا عَنْهُ وَإِنَّهُمْ لَكَاذِبُونَ', NULL, 'But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars.', '(Mereka mengatakan yang demikian bukanlah kerana hendak beriman) bahkan setelah nyata kepada mereka apa yang mereka selalu sembunyikan dahulu; dan kalau mereka dikembalikan ke dunia sekalipun, tentulah mereka akan mengulangi lagi apa yang mereka dilarang dari melakukannya; dan sesungguhnya mereka adalah tetap pendusta.', FALSE, NULL, NULL, 131, 7, 52, 104, FALSE, 0, NULL),
(6, 29, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'وَقَالُوا إِنْ هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', NULL, 'And they say, "There is none but our worldly life, and we will not be resurrected."', 'Dan tentulah mereka akan berkata pula: “Tiadalah hidup yang lain selain dari hidup kita di dunia ini, dan tiadalah kita akan dibangkitkan semula sesudah kita mati”.', FALSE, NULL, NULL, 131, 7, 52, 104, FALSE, 0, NULL),
(6, 30, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'وَلَوْ تَرَىٰ إِذْ وُقِفُوا عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِالْحَقِّ قَالُوا بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', NULL, 'If you could but see when they will be made to stand before their Lord. He will say, "Is this not the truth?" They will say, "Yes, by our Lord." He will [then] say, "So taste the punishment for what you used to deny."', 'Dan sungguh ngeri jika engkau melihat ketika mereka dihadapkan kepada Tuhan mereka, lalu Allah berfirman: “Bukankah hari kiamat ini suatu perkara yang benar? Mereka menjawab: “Benar, demi Tuhan kami!” Allah berfirman lagi: “Oleh itu, rasalah azab seksa neraka dengan sebab kamu telah kufur ingkar”.', FALSE, NULL, NULL, 131, 7, 52, 104, FALSE, 0, NULL),
(6, 31, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَآءَ مَا يَزِرُونَ', 'قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقَاءِ اللَّهِ حَتَّىٰ إِذَا جَاءَتْهُمُ السَّاعَةُ بَغْتَةً قَالُوا يَا حَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَاءَ مَا يَزِرُونَ', NULL, 'Those will have lost who deny the meeting with Allāh, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, "Oh, [how great is] our regret over what we neglected concerning it [i.e., the Hour]," while they bear their burdens [i.e., sins] on their backs. Unquestionably, evil is that which they bear.', 'Sesungguhnya telah rugilah orang-orang yang mendustakan pertemuan mengadap Allah; sehingga apabila hari kiamat datang secara mengejut kepada mereka, mereka berkata; “Aduhai kesalnya kami atas apa yang telah kami cuaikan dalam dunia!” Sambil mereka memikul dosa-dosa mereka di atas belakang mereka. Ingatlah, amatlah buruk apa yang mereka pikul itu.', FALSE, NULL, NULL, 131, 7, 52, 105, FALSE, 0, NULL),
(6, 32, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ الْآخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', NULL, 'And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allāh, so will you not reason?', 'Dan tidak (dinamakan) kehidupan dunia melainkan permainan yang sia-sia dan hiburan yang melalaikan: dan demi sesungguhnya negeri akhirat itu lebih baik bagi orang-orang yang bertaqwa. Oleh itu, tidakkah kamu mahu berfikir?', FALSE, NULL, NULL, 131, 7, 52, 105, FALSE, 0, NULL),
(6, 33, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'قَدْ نَعْلَمُ إِنَّهُ لَيَحْزُنُكَ الَّذِي يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ الظَّالِمِينَ بِآيَاتِ اللَّهِ يَجْحَدُونَ', NULL, 'We know that you, [O Muḥammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allāh that the wrongdoers reject.', 'Sesungguhnya Kami mengetahui bahawa apa yang mereka katakan itu akan menyebabkan engkau (wahai Muhammad) berdukacita; (maka janganlah engkau berdukacita) kerana sebenarnya mereka bukan mendustakanmu, tetapi orang-orang yang zalim itu mengingkari ayat-ayat keterangan Allah (disebabkan kedegilan mereka semata-mata).', FALSE, NULL, NULL, 131, 7, 52, 105, FALSE, 0, NULL),
(6, 34, 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا عَلَىٰ مَا كُذِّبُوا وَأُوذُوا حَتَّىٰ أَتَاهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَاتِ اللَّهِ وَلَقَدْ جَاءَكَ مِن نَّبَإِ الْمُرْسَلِينَ', NULL, 'And certainly were messengers denied before you, but they were patient over the denial, and they were harmed until Our victory came to them. And none can alter the words [i.e., decrees] of Allāh. And there has certainly come to you some information about the [previous] messengers.', 'Dan demi sesungguhnya, Rasul-rasul sebelummu pernah juga didustakan, maka mereka sabar terhadap perbuatan orang-orang yang mendustakan mereka dan menyakiti mereka, sehingga datanglah pertolongan Kami kepada mereka; dan sememangnyalah tiada sesiapa pun yang dapat mengubah Kalimah-kalimah Allah (janji-janjiNya); dan demi sesungguhnya, telah datang kepadamu sebahagian dari khabar berita Rasul-rasul itu.', FALSE, NULL, NULL, 131, 7, 52, 105, FALSE, 0, NULL),
(6, 35, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ اسْتَطَعْتَ أَن تَبْتَغِيَ نَفَقًا فِي الْأَرْضِ أَوْ سُلَّمًا فِي السَّمَاءِ فَتَأْتِيَهُم بِآيَةٍ وَلَوْ شَاءَ اللَّهُ لَجَمَعَهُمْ عَلَى الْهُدَىٰ فَلَا تَكُونَنَّ مِنَ الْجَاهِلِينَ', NULL, 'And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allāh had willed, He would have united them upon guidance. So never be of the ignorant.', 'Dan jika perbuatan mereka berpaling (daripada menerima apa yang engkau bawa wahai Muhammad) terasa amat berat kepadamu; maka sekiranya engkau sanggup mencari satu lubang di bumi (untuk menembusi ke bawahnya) atau satu tangga untuk naik ke langit, supaya engkau dapat bawakan mukjizat kepada mereka, (cubalah lakukan jika engkau sanggup). Dan sekiranya Allah menghendaki, tentulah ia himpunkan mereka atas hidayah petunjuk. (Tetapi Allah tidak menghendakinya), oleh itu janganlah engkau menjadi dari orang-orang yang jahil.', FALSE, NULL, NULL, 131, 7, 52, 105, FALSE, 0, NULL),
(6, 36, 'إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 'إِنَّمَا يَسْتَجِيبُ الَّذِينَ يَسْمَعُونَ وَالْمَوْتَىٰ يَبْعَثُهُمُ اللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', NULL, 'Only those who hear will respond. But the dead - Allāh will resurrect them; then to Him they will be returned.', 'Hanyasanya orang-orang yang menyahut seruanmu itu ialah mereka yang mendengar (yang mahu menurut kebenaran); sedang orang-orang yang mati Allah bangkitkan mereka semula (pada hari kiamat kelak), kemudian mereka dikembalikan kepadaNya untuk menerima balasan.', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 37, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وَقَالُوا لَوْلَا نُزِّلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ قُلْ إِنَّ اللَّهَ قَادِرٌ عَلَىٰ أَن يُنَزِّلَ آيَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'And they say, "Why has a sign not been sent down to him from his Lord?" Say, "Indeed, Allāh is Able to send down a sign, but most of them do not know."', 'Dan mereka (golongan kafir musyrik) berkata: “Alangkah eloknya kalau diturunkan kepada Muhammad satu mukjizat dari Tuhannya?” Katakanlah (wahai Muhammad): “Sesungguhnya Allah berkuasa menurunkan mukjizat”, akan tetapi kebanyakan mereka tidak mengetahui (balasan yang akan menimpa mereka kalau mereka enggan beriman).', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 38, 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', 'وَمَا مِن دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِي الْكِتَابِ مِن شَيْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', NULL, 'And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered.', 'Dan tidak seekor pun binatang yang melata di bumi, dan tidak seekor pun burung yang terbang dengan kedua sayapnya, melainkan mereka umat-umat seperti kamu. Tiada Kami tinggalkan sesuatu pun di dalam kitab Al-Quran ini; kemudian mereka semuanya akan dihimpunkan kepada Tuhan mereka (untuk dihisab dan menerima balasan).', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 39, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَٰتِ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا صُمٌّ وَبُكْمٌ فِي الظُّلُمَاتِ مَن يَشَإِ اللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'But those who deny Our verses are deaf and dumb within darknesses. Whomever Allāh wills - He sends astray; and whomever He wills - He puts him on a straight path.', 'Dan orang-orang yang mendustakan ayat-ayat keterangan Kami, mereka adalah bisu dan tuli, di dalam gelap-gelita. Sesiapa yang Allah kehendaki: akan disesatkannya (menurut peraturan tetapNya), dan sesiapa yang Ia kehendaki: akan dijadikannya atas jalan yang betul lurus.', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 40, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', 'قُلْ أَرَأَيْتَكُمْ إِنْ أَتَاكُمْ عَذَابُ اللَّهِ أَوْ أَتَتْكُمُ السَّاعَةُ أَغَيْرَ اللَّهِ تَدْعُونَ إِن كُنتُمْ صَادِقِينَ', NULL, 'Say, "Have you considered: if there came to you the punishment of Allāh or there came to you the Hour - is it other than Allāh you would invoke, if you should be truthful?"', 'Katakanlah (wahai Muhammad): “Khabarkanlah kepadaku, jika datang kepada kamu azab Allah, atau datang kepada kamu hari kiamat, adakah kamu akan menyeru yang lain dari Allah (untuk menolong kamu), jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 41, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَاءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', NULL, 'No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him].', 'Bahkan Dia lah (Allah) yang kamu seru lalu Ia hapuskan bahaya yang kamu pohonkan kepadaNya jika Ia kehendaki; dan kamu lupakan apa yang kamu sekutukan (dengan Allah dalam masa kamu ditimpa bahaya itu).', FALSE, NULL, NULL, 132, 7, 53, 105, FALSE, 0, NULL),
(6, 42, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', 'وَلَقَدْ أَرْسَلْنَا إِلَىٰ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَاهُم بِالْبَأْسَاءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', NULL, 'And We have already sent [messengers] to nations before you, [O Muḥammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us].', 'Dan demi sesungguhnya Kami telah utuskan Rasul-rasul kepada umat-umat yang dahulu daripadamu (lalu mereka mendustakannya), maka Kami seksakan mereka dengan kebuluran dan penyakit, supaya mereka berdoa (kepada Kami) dangan merendah diri (serta insaf dan bertaubat).', FALSE, NULL, NULL, 132, 7, 53, 106, FALSE, 0, NULL),
(6, 43, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 'فَلَوْلَا إِذْ جَاءَهُم بَأْسُنَا تَضَرَّعُوا وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ الشَّيْطَانُ مَا كَانُوا يَعْمَلُونَ', NULL, 'Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing.', 'Maka alangkah eloknya kalau mereka berdoa kepada Kami dengan merendah diri (serta insaf dan bertaubat) ketika mereka ditimpa azab Kami? Tetapi yang sebenarnya hati mereka keras (tidak mahu menerima kebenaran), dan Syaitan pula memperelokkan pada (pandangan) mereka apa yang mereka telah lakukan.', FALSE, NULL, NULL, 132, 7, 53, 106, FALSE, 0, NULL),
(6, 44, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', 'فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّىٰ إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', NULL, 'So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.', 'Kemudian apabila mereka melupakan apa yang telah diperingatkan mereka dengannya, Kami bukakan kepada mereka pintu-pintu segala kemewahan dan kesenangan, sehingga apabila mereka bergembira dan bersukaria dengan segala nikmat yang diberikan kepada mereka, Kami timpakan mereka secara mengejut (dengan bala bencana yang membinasakan), maka mereka pun berputus asa (dari mendapat sebarang pertolongan).', FALSE, NULL, NULL, 132, 7, 53, 106, FALSE, 0, NULL),
(6, 45, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُوا وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'So the people that committed wrong were eliminated. And praise to Allāh, Lord of the worlds.', 'Lalu kaum yang zalim itu dibinasakan sehingga terputus keturunannya. Dan (dengan itu bersyukurlah kerana musnahnya kezaliman, dengan menyebut): “Segala puji tertentu bagi Allah Tuhan yang memelihara dan mentadbirkan sekalian Alam”.', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 46, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 'قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَارَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ انظُرْ كَيْفَ نُصَرِّفُ الْآيَاتِ ثُمَّ هُمْ يَصْدِفُونَ', NULL, 'Say, "Have you considered: if Allāh should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allāh could bring them [back] to you?" Look how We diversify the verses; then they [still] turn away.', 'Katakanlah (wahai Muhammad): “Bagaimana fikiran kamu, jika Allah melenyapkan pendengaran serta penglihatan kamu, dan Ia pula memeteraikan atas hati kamu? Siapakah Tuhan selain Allah yang berkuasa mengembalikannya kepada kamu?” Lihatlah bagaimana Kami berulang-ulang menerangkan tanda-tanda kebesaran Kami (dengan berbagai cara), dalam pada itu, mereka tetap juga berpaling - ingkar.', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 47, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', 'قُلْ أَرَأَيْتَكُمْ إِنْ أَتَاكُمْ عَذَابُ اللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا الْقَوْمُ الظَّالِمُونَ', NULL, 'Say, "Have you considered: if the punishment of Allāh should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?"', 'Katakanlah: “Bagaimana fikiran kamu, jika datang kepada kamu azab Allah dengan tiba-tiba, atau dengan terang-terang (setelah diperlihatkan tanda-tanda yang menunjukkan kedatangannya), siapakah yang akan binasa, selain dari kaum yang zalim?”.', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 48, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'وَمَا نُرْسِلُ الْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ آمَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve.', 'Dan tiadalah Kami utuskan Rasul-rasul itu melainkan sebagai pembawa berita gembira dan pembawa amaran; kemudian sesiapa yang beramal soleh, maka tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka tidak akan berdukacita.', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 49, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 'وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا يَمَسُّهُمُ الْعَذَابُ بِمَا كَانُوا يَفْسُقُونَ', NULL, 'But those who deny Our verses - the punishment will touch them for their defiant disobedience.', 'Dan orang-orang yang mendustakan ayat-ayat keterangan Kami, mereka akan dikenakan azab seksa dengan sebab mereka berlaku fasik.', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 50, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ', 'قُل لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰ إِلَيَّ قُلْ هَلْ يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ', NULL, 'Say, [O Muḥammad], "I do not tell you that I have the depositories [containing the provision] of Allāh or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me." Say, "Is the blind equivalent to the seeing? Then will you not give thought?"', 'Katakanlah (wahai Muhammad); “Aku tidak mengatakan kepada kamu (bahawa) perbendaharaan Allah ada di sisiku, dan aku pula tidak mengetahui perkara-perkara yang ghaib; aku juga tidak mengatakan kepada kamu bahawasanya aku ini malaikat, aku tidak menurut melainkan apa yang diwahyukan kepadaku”. Bertanyalah (kepada mereka): “Adakah sama orang yang buta dengan orang yang celik? Tidakkah kamu mahu berfikir?”', FALSE, NULL, NULL, 133, 7, 53, 106, FALSE, 0, NULL),
(6, 51, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', 'وَأَنذِرْ بِهِ الَّذِينَ يَخَافُونَ أَن يُحْشَرُوا إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِ وَلِيٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', NULL, 'And warn by it [i.e., the Qur’ān] those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous.', 'Dan berilah amaran dengan Al-Quran itu kepada orang-orang yang merasa takut bahawa mereka akan dihimpunkan kepada Tuhan mereka (pada hari kiamat), (padahal) tiadalah bagi mereka pelindung dan tidak juga pemberi syafaat yang lain dari Allah, supaya mereka bertaqwa.', FALSE, NULL, NULL, 133, 7, 53, 107, FALSE, 0, NULL),
(6, 52, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 'وَلَا تَطْرُدِ الَّذِينَ يَدْعُونَ رَبَّهُم بِالْغَدَاةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَيْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَيْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ الظَّالِمِينَ', NULL, 'And do not send away those who call upon their Lord morning and afternoon, seeking His face [i.e., favor]. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers.', 'Dan janganlah engkau usir orang-orang yang beribadat dan berdoa kepada Tuhan mereka pagi dan petang, sedang mereka menghendaki keredaanNya semata-mata. Tiadalah engkau bertanggungjawab sesuatu pun mengenai hitungan amal mereka, dan mereka juga tidak bertanggungjawab sesuatu pun mengenai hitungan amalmu. Maka (sekiranya) engkau usir mereka, nescaya menjadilah engkau dari orang-orang yang zalim.', FALSE, NULL, NULL, 133, 7, 53, 107, FALSE, 0, NULL),
(6, 53, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوا أَهَٰؤُلَاءِ مَنَّ اللَّهُ عَلَيْهِم مِّن بَيْنِنَا أَلَيْسَ اللَّهُ بِأَعْلَمَ بِالشَّاكِرِينَ', NULL, 'And thus We have tried some of them through others that they [i.e., the disbelievers] might say, "Is it these whom Allāh has favored among us?" Is not Allāh most knowing of those who are grateful?', 'Dan demikianlah Kami uji sebahagian dari mereka (yang kaya raya) dengan sebahagian yang lain (yang fakir miskin); lalu orang-orang yang kaya itu berkata (kepada orang-orang fakir miskin yang beriman): “Inikah orang-orangnya yang telah dikurniakan nikmat oleh Allah kepada mereka di antara kami?” (Allah berfirman): “Bukankah Allah lebih mengetahui akan orang-orang yang bersyukur?”', FALSE, NULL, NULL, 134, 7, 53, 107, FALSE, 0, NULL),
(6, 54, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ', 'وَإِذَا جَاءَكَ الَّذِينَ يُؤْمِنُونَ بِآيَاتِنَا فَقُلْ سَلَامٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ الرَّحْمَةَ أَنَّهُ مَنْ عَمِلَ مِنكُمْ سُوءًا بِجَهَالَةٍ ثُمَّ تَابَ مِن بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'And when those come to you who believe in Our verses, say, "Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful."', 'Dan apabila orang-orang yang beriman kepada ayat-ayat keterangan Kami itu datang kepadamu (dengan tujuan hendak bertaubat dari dosa-dosa mereka), maka katakanlah: “Mudah-mudahan kamu beroleh selamat! Tuhan kamu telah menetapkan bagi diriNya untuk memberi rahmat (yang melimpah-limpah): bahawasanya sesiapa di antara kamu yang melakukan kejahatan dengan sebab kejahilannya, kemudian ia bertaubat sesudah itu, dan berusaha memperbaiki (amalannya), maka sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani”.', FALSE, NULL, NULL, 134, 7, 53, 107, FALSE, 0, NULL),
(6, 55, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', 'وَكَذَٰلِكَ نُفَصِّلُ الْآيَاتِ وَلِتَسْتَبِينَ سَبِيلُ الْمُجْرِمِينَ', NULL, 'And thus do We detail the verses, and [thus] the way of the criminals will become evident.', 'Dan demikianlah Kami terangkan ayat-ayat Al-Quran satu persatu (supaya jelas jalan yang benar), dan supaya jelas pula jalan orang-orang yang berdosa.', FALSE, NULL, NULL, 134, 7, 53, 107, FALSE, 0, NULL),
(6, 56, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 'قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ قُل لَّا أَتَّبِعُ أَهْوَاءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنَ الْمُهْتَدِينَ', NULL, 'Say, "Indeed, I have been forbidden to worship those you invoke besides Allāh." Say, "I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided."', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku dilarang menyembah mereka yang kamu sembah yang lain dari Allah”. Katakanlah lagi: “Aku tidak akan menurut hawa nafsu kamu, kerana kalau aku turut, sesungguhnya sesatlah aku, dan tiadalah aku dari orang-orang yang mendapat hidayah petunjuk”.', FALSE, NULL, NULL, 134, 7, 53, 108, FALSE, 0, NULL),
(6, 57, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ ٱلْحَقَّ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', 'قُلْ إِنِّي عَلَىٰ بَيِّنَةٍ مِّن رَّبِّي وَكَذَّبْتُم بِهِ مَا عِندِي مَا تَسْتَعْجِلُونَ بِهِ إِنِ الْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِلِينَ', NULL, 'Say, "Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allāh. He relates the truth, and He is the best of deciders."', 'Katakanlah: “Sesungguhnya aku tetap berada di atas (kebenaran yang berdasarkan) bukti-bukti yang nyata (Al-Quran) dari Tuhanku; sedang kamu mendustakannya. Tidak ada padaku apa yang kamu minta disegerakan (dari azab seksa); hanya Allah jualah yang menetapkan hukum; Ia menerangkan kebenaran, dan Dia lah sebaik-baik yang memberi keputusan”.', FALSE, NULL, NULL, 134, 7, 53, 108, FALSE, 0, NULL),
(6, 58, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', 'قُل لَّوْ أَنَّ عِندِي مَا تَسْتَعْجِلُونَ بِهِ لَقُضِيَ الْأَمْرُ بَيْنِي وَبَيْنَكُمْ وَاللَّهُ أَعْلَمُ بِالظَّالِمِينَ', NULL, 'Say, "If I had that for which you are impatient, the matter would have been decided between me and you, but Allāh is most knowing of the wrongdoers."', 'Katakanlah: “Kalau ada padaku (kuasa menurunkan) azab seksa yang kamu minta disegerakan kedatangannya itu, nescaya selesailah perkara (yang sedang berbangkit) antaraku dengan kamu. Dan (ingatlah) Allah Maha Mengetahui akan orang-orang yang zalim”.', FALSE, NULL, NULL, 134, 7, 53, 108, FALSE, 0, NULL),
(6, 59, 'وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'وَعِندَهُ مَفَاتِحُ الْغَيْبِ لَا يَعْلَمُهَا إِلَّا هُوَ وَيَعْلَمُ مَا فِي الْبَرِّ وَالْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِي ظُلُمَاتِ الْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِي كِتَابٍ مُّبِينٍ', NULL, 'And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record.', 'Dan pada sisi Allah jualah anak kunci perbendaharaan segala yang ghaib, tiada sesiapa yang mengetahuinya melainkan Dia lah sahaja; dan Ia mengetahui apa yang ada di darat dan di laut; dan tidak gugur sehelai daun pun melainkan Ia mengetahuinya, dan tidak gugur sebutir bijipun dalam kegelapan bumi dan tidak gugur yang basah dan yang kering, melainkan (semuanya) ada tertulis di dalam kitab (Lauh Mahfuz) yang terang nyata.', FALSE, NULL, NULL, 134, 7, 54, 108, FALSE, 0, NULL),
(6, 60, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وَهُوَ الَّذِي يَتَوَفَّاكُم بِاللَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِالنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein [i.e., by day] that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do.', 'Dan Dia lah yang menidurkan kamu pada waktu malam, dan mengetahui apa yang kamu kerjakan pada siang hari; kemudian Ia bangunkan kamu (dari tidur) padanya, untuk disempurnakan ajal (masa umur kamu) yang telah ditetapkan. Kemudian kepadaNyalah tempat kamu kembali, kemudian Ia menyatakan kepada kamu apa yang kamu lakukan.', FALSE, NULL, NULL, 135, 7, 54, 108, FALSE, 0, NULL),
(6, 61, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰ إِذَا جَاءَ أَحَدَكُمُ الْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', NULL, 'And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers [i.e., angels of death] take him, and they do not fail [in their duties].', 'Dan Dia lah yang berkuasa atas sekalian hambaNya; dan Ia mengutuskan kepada kamu pengawal-pengawal (malaikat yang menjaga dan menulis segala yang kamu lakukan), sehingga apabila sampai ajal maut kepada salah seorang di antara kamu, lalu diambil (nyawanya) oleh utusan-utusan Kami (malaikat); sedang mereka pula (malaikat itu) tidak cuai (dalam menjalankan tugasnya).', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 62, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', 'ثُمَّ رُدُّوا إِلَى اللَّهِ مَوْلَاهُمُ الْحَقِّ أَلَا لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحَاسِبِينَ', NULL, 'Then they [i.e., His servants] are returned to Allāh, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants.', 'Kemudian mereka (yang diambil nyawanya itu) dikembalikan kepada Allah Pengawas mereka yang sebenar (yang akan membalas dengan adil). Ketahuilah, bagi Allah jua lah kuasa menetapkan hukum (pada hari kiamat itu), dan Dia lah secepat-cepat Pengira - Penghitung.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 63, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ تَدْعُونَهُ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَانَا مِنْ هَٰذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ', NULL, 'Say, "Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, ''If He should save us from this [crisis], we will surely be among the thankful.''"', 'Katakanlah: “Siapakah yang menyelamatkan kamu dari bencana-bencana di darat dan di laut? (Ketika) kamu berdoa merayu kepadaNya dengan merendah diri (secara terbuka) dan secara bersembunyi, (dengan berkata): “Demi sesungguhnya jika Allah selamatkan kami dari bencana ini nescaya menjadilah kami dari orang-orang yang bersyukur”.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 64, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', 'قُلِ اللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', NULL, 'Say, "It is Allāh who saves you from it and from every distress; then you [still] associate others with Him."', 'Katakanlah: “Allah jualah yang menyelamatkan kamu dari bencana itu dan dari segala jenis kesusahan; dalam pada itu, kamu (masih) mempersekutukan (Allah dengan sesuatu yang lain)”.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 65, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 'قُلْ هُوَ الْقَادِرُ عَلَىٰ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ انظُرْ كَيْفَ نُصَرِّفُ الْآيَاتِ لَعَلَّهُمْ يَفْقَهُونَ', NULL, 'Say, "He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another." Look how We diversify the signs that they might understand.', 'Katakanlah: “Dia lah yang berkuasa menghantar kepada kamu azab seksa (bala bencana), dari sebelah atas kamu, atau dari bawah kaki kamu, atau Ia menjadikan kamu bertentangan dan berpecah-belah - berpuak-puak, dan Ia merasakan sebahagian daripada kamu akan perbuatan ganas dan kejam sebahagian yang lain”. Perhatikanlah bagaimana Kami menjelaskan ayat-ayat keterangan (yang menunjukkan kebesaran Kami) dengan berbagai cara, supaya mereka memahaminya.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 66, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', 'وَكَذَّبَ بِهِ قَوْمُكَ وَهُوَ الْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', NULL, 'But your people have denied it while it is the truth. Say, "I am not over you a manager [i.e., authority]."', 'Dan kaum engkau (wahai Muhammad) mendustakannya (Al-Quran), padahal ia adalah benar. Katakanlah: “Aku bukanlah orang yang ditugaskan menjaga urusan kamu, (aku hanya seorang Rasul yang menyampaikan perintah-perintah Allah kepada kamu)”.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 67, 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ', 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ', NULL, 'For every news [i.e., happening] is a finality; and you are going to know.', 'Tiap-tiap khabar berita mempunyai masa yang menentukannya (yang membuktikan benarnya atau dustanya); dan kamu akan mengetahuinya.', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 68, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وَإِذَا رَأَيْتَ الَّذِينَ يَخُوضُونَ فِي آيَاتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ وَإِمَّا يُنسِيَنَّكَ الشَّيْطَانُ فَلَا تَقْعُدْ بَعْدَ الذِّكْرَىٰ مَعَ الْقَوْمِ الظَّالِمِينَ', NULL, 'And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people.', 'Dan apabila engkau melihat orang-orang yang memperkatakan dengan cara mencaci atau mengejek-ejek ayat-ayat Kami, maka tinggalkanlah mereka sehingga mereka memperkatakan soal yang lain; dan jika engkau dilupakan oleh Syaitan (lalu engkau duduk bersama mereka), maka janganlah engkau duduk lagi bersama-sama kaum yang zalim itu, sesudah engkau mengingati (akan larangan itu).', FALSE, NULL, NULL, 135, 7, 54, 109, FALSE, 0, NULL),
(6, 69, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', 'وَمَا عَلَى الَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَيْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', NULL, 'And those who fear Allāh are not held accountable for them [i.e., the disbelievers] at all, but [only for] a reminder - that perhaps they will fear Him.', 'Dan tidaklah ada tanggungjawab sedikitpun atas orang-orang yang bertaqwa mengenai dosa orang-orang (kafir yang mengejek-ejek) itu, akan tetapi (kewajipan orang-orang Islam) ialah mengingati (larangan Allah itu) supaya mereka bertaqwa.', FALSE, NULL, NULL, 136, 7, 54, 109, FALSE, 0, NULL),
(6, 70, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'وَذَرِ الَّذِينَ اتَّخَذُوا دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَذَكِّرْ بِهِ أَن تُبْسَلَ نَفْسٌ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ اللَّهِ وَلِيٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَا أُولَٰئِكَ الَّذِينَ أُبْسِلُوا بِمَا كَسَبُوا لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ', NULL, 'And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with it [i.e., the Qur’ān], lest a soul be given up to destruction for what it earned; it will have other than Allāh no protector and no intercessor. And if it should offer every compensation, it would not be taken from it [i.e., that soul]. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve.', 'Dan jauhkanlah diri dari orang-orang yang menjadikan ugama mereka sebagai permainan dan hiburan, dan mereka pula telah diperdayakan oleh kehidupan dunia dan peringatkanlah (mereka) dengan Al-Quran itu supaya tiap-tiap diri (di akhirat kelak) tidak terjerumus (ke dalam azab neraka) dengan sebab apa yang ia telah usahakan (dari perbuatan yang buruk dan keji). Tidak ada baginya pelindung dan tidak juga pemberi syafaat yang lain dari Allah. Dan jika ia hendak menebus (dirinya) dengan segala jenis tebusan, (nescaya tebusan itu) tidak akan diterima daripadanya. Mereka itulah orang-orang yang dijerumuskan (ke dalam azab neraka) dengan sebab apa yang telah mereka usahakan. Bagi mereka disediakan minuman dari air panas yang menggelegak, dan azab seksa yang tidak terperi sakitnya, disebabkan mereka kufur ingkar (semasa hidupnya).', FALSE, NULL, NULL, 136, 7, 54, 109, FALSE, 0, NULL),
(6, 71, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'قُلْ أَنَدْعُو مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰ أَعْقَابِنَا بَعْدَ إِذْ هَدَانَا اللَّهُ كَالَّذِي اسْتَهْوَتْهُ الشَّيَاطِينُ فِي الْأَرْضِ حَيْرَانَ لَهُ أَصْحَابٌ يَدْعُونَهُ إِلَى الْهُدَى ائْتِنَا قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ الْعَالَمِينَ', NULL, 'Say, "Shall we invoke instead of Allāh that which neither benefits us nor harms us and be turned back on our heels after Allāh has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], ''Come to us.''" Say, "Indeed, the guidance of Allāh is the [only] guidance; and we have been commanded to submit to the Lord of the worlds.', 'Katakanlah: “Patutkah kita menyeru serta menyembah yang lain dari Allah, sesuatu yang tidak dapat memberi manfaat kepada kita dan tidak dapat mendatangkan mudarat kepada kita; dan (patutkah) kita dikembalikan undur ke belakang (menjadi kafir musyrik) setelah kita diberi hidayah petunjuk oleh Allah (dengan ugama Islam), seperti orang yang telah disesatkan oleh Syaitan-syaitan di bumi (di tempat yang lengang) dalam keadaan bingung, sedang ia pula mempunyai sahabat-sahabat yang mengajaknya ke jalan yang lurus (dengan berkata kepadanya): “Marilah bersama-sama kami. “Katakanlah: “Sesungguhnya petunjuk Allah itulah sebenar-benar petunjuk, dan kita diperintahkan supaya berserah diri kepada Tuhan yang memelihara dan mentadbirkan sekalian alam”.', FALSE, NULL, NULL, 136, 7, 54, 110, FALSE, 0, NULL),
(6, 72, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'وَأَنْ أَقِيمُوا الصَّلَاةَ وَاتَّقُوهُ وَهُوَ الَّذِي إِلَيْهِ تُحْشَرُونَ', NULL, 'And to establish prayer and fear Him." And it is He to whom you will be gathered.', 'Dan (diperintahkan): Hendaklah kamu mengerjakan sembahyang dan bertaqwa kepadaNya, dan Dia lah Tuhan yang kepadaNya kamu akan dihimpunkan (pada hari akhirat kelak).', FALSE, NULL, NULL, 136, 7, 54, 110, FALSE, 0, NULL),
(6, 73, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ ٱلْحَقُّ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ الْحَقُّ وَلَهُ الْمُلْكُ يَوْمَ يُنفَخُ فِي الصُّورِ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ', NULL, 'And it is He who created the heavens and earth in truth. And the day [i.e., whenever] He says, "Be," and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Aware.', 'Dan Dia lah yang menciptakan langit dan bumi dengan (tujuan) yang benar, dan (Dia lah juga) pada masa (hendak menjadikan sesuatu) berfirman: “Jadilah”, lalu terjadilah ia. FirmanNya itu adalah benar. Dan bagiNyalah kuasa pemerintahan pada hari ditiupkan sangkakala. Ia yang mengetahui segala yang ghaib dan yang nyata, dan Dia lah Yang Maha Bijaksana, lagi Maha mendalam pengetahuanNya.', FALSE, NULL, NULL, 136, 7, 54, 110, FALSE, 0, NULL),
(6, 74, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍ مُّبِينٍ', 'وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ آزَرَ أَتَتَّخِذُ أَصْنَامًا آلِهَةً إِنِّي أَرَاكَ وَقَوْمَكَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'And [mention, O Muḥammad], when Abraham said to his father Āzar, "Do you take idols as deities? Indeed, I see you and your people to be in manifest error."', 'Dan (ingatlah) ketika Nabi Ibrahim berkata kepada bapanya Aazar: “Patutkah ayah menjadikan berhala-berhala sebagai tuhan-tuhan? Sesungguhnya aku melihatmu dan kaummu dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 75, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', 'وَكَذَٰلِكَ نُرِي إِبْرَاهِيمَ مَلَكُوتَ السَّمَاوَاتِ وَالْأَرْضِ وَلِيَكُونَ مِنَ الْمُوقِنِينَ', NULL, 'And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith].', 'Dan demikianlah Kami perlihatkan kepada Nabi Ibrahim kebesaran dan kekuasaan (Kami) di langit dan di bumi, dan supaya menjadilah ia dari orang-orang yang percaya dengan sepenuh-penuh yakin.', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 76, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ', 'فَلَمَّا جَنَّ عَلَيْهِ اللَّيْلُ رَأَىٰ كَوْكَبًا قَالَ هَٰذَا رَبِّي فَلَمَّا أَفَلَ قَالَ لَا أُحِبُّ الْآفِلِينَ', NULL, 'So when the night covered him [with darkness], he saw a star. He said, "This is my lord." But when it set, he said, "I like not those that set [i.e., disappear]."', 'Maka ketika ia berada pada waktu malam yang gelap, ia melihat sebuah bintang (bersinar-sinar), lalu ia berkata: “Inikah Tuhanku?” Kemudian apabila bintang itu terbenam, ia berkata pula: “Aku tidak suka kepada yang terbenam hilang”.', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 77, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 'فَلَمَّا رَأَى الْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّي فَلَمَّا أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِي رَبِّي لَأَكُونَنَّ مِنَ الْقَوْمِ الضَّالِّينَ', NULL, 'And when he saw the moon rising, he said, "This is my lord." But when it set, he said, "Unless my Lord guides me, I will surely be among the people gone astray."', 'Kemudian apabila dilihatnya bulan terbit (menyinarkan cahayanya), dia berkata: “Inikah Tuhanku?” Maka setelah bulan itu terbenam, berkatalah dia: “Demi sesungguhnya, jika aku tidak diberikan petunjuk oleh Tuhanku, nescaya menjadilah aku dari kaum yang sesat”.', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 78, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'فَلَمَّا رَأَى الشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّي هَٰذَا أَكْبَرُ فَلَمَّا أَفَلَتْ قَالَ يَا قَوْمِ إِنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ', NULL, 'And when he saw the sun rising, he said, "This is my lord; this is greater." But when it set, he said, "O my people, indeed I am free from what you associate with Allāh.', 'Kemudian apabila dia melihat matahari sedang terbit (menyinarkan cahayanya), berkatalah dia: “Inikah Tuhanku? Ini lebih besar”. Setelah matahari terbenam, dia berkata pula: ‘Wahai kaumku, sesungguhnya aku berlepas diri (bersih) dari apa yang kamu sekutukan (Allah dengannya).', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 79, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ', NULL, 'Indeed, I have turned my face [i.e., self] toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allāh."', '“Sesungguhnya aku hadapkan muka dan diriku kepada Allah yang menciptakan langit dan bumi, sedang aku tetap di atas dasar tauhid dan bukanlah aku dari orang-orang yang menyekutukan Allah (dengan sesuatu yang lain)”.', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 80, 'وَحَآجَّهُۥ قَوْمُهُۥ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ', 'وَحَاجَّهُ قَوْمُهُ قَالَ أَتُحَاجُّونِّي فِي اللَّهِ وَقَدْ هَدَانِ وَلَا أَخَافُ مَا تُشْرِكُونَ بِهِ إِلَّا أَن يَشَاءَ رَبِّي شَيْئًا وَسِعَ رَبِّي كُلَّ شَيْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ', NULL, 'And his people argued with him. He said, "Do you argue with me concerning Allāh while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?', 'Dan ia dibantah oleh kaumnya, ia pun berkata: “Patutkah kamu membantahku mengenai Allah, padahal sesungguhnya Ia telah memberi hidayah petunjuk kepadaku? Dan aku pula tidak takut (akan sebarang bahaya dari) apa yang kamu sekutukan dengan Allah, kecuali Tuhanku menghendaki sesuatu dari bahaya itu. (Sesungguhnya) pengetahuan Tuhanku meliputi tiap-tiap sesuatu, tidakkah kamu mahu (insaf) mengambil pelajaran?', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 81, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًا فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ', 'وَكَيْفَ أَخَافُ مَا أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ عَلَيْكُمْ سُلْطَانًا فَأَيُّ الْفَرِيقَيْنِ أَحَقُّ بِالْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ', NULL, 'And how should I fear what you associate while you do not fear that you have associated with Allāh that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?"', '“Dan bagaimanakah aku hendak takutkan apa yang kamu sekutukan dengan Allah itu (yang tidak dapat mendatangkan sesuatu bahaya), padahal kamu tidak takut bahawa kamu telah sekutukan Allah dengan sesuatu yang Allah tidak menurunkan sebarang keterangan kepada kamu mengenainya? Maka yang manakah di antara dua puak itu yang lebih berhak mendapat keamanan (dari bahaya), jika betul kamu mengetahui?”', FALSE, NULL, NULL, 137, 7, 55, 110, FALSE, 0, NULL),
(6, 82, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', 'الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُم مُّهْتَدُونَ', NULL, 'They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided.', 'Orang-orang yang beriman dan tidak mencampur adukkan iman mereka dengan kezaliman (syirik), mereka itulah orang-orang yang mendapat keamanan dan merekalah orang-orang yang mendapat hidayah petunjuk.', FALSE, NULL, NULL, 138, 7, 55, 110, FALSE, 0, NULL),
(6, 83, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', 'وَتِلْكَ حُجَّتُنَا آتَيْنَاهَا إِبْرَاهِيمَ عَلَىٰ قَوْمِهِ نَرْفَعُ دَرَجَاتٍ مَّن نَّشَاءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', NULL, 'And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing.', 'Dan itulah hujah (bukti) Kami, yang Kami berikan kepada Nabi Ibrahim untuk mengalahkan kaumnya. Kami tinggikan pangkat-pangkat kedudukan sesiapa yang Kami kehendaki. Sesungguhnya Tuhanmu Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 84, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِ دَاوُودَ وَسُلَيْمَانَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَارُونَ وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'And We gave to him [i.e., Abraham] Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good.', 'Dan Kami telah kurniakan kepada Nabi Ibrahim: (anaknya) Ishak (dari isterinya Sarah), dan (cucunya) Yaakub. Tiap-tiap seorang (dari mereka) Kami telah berikan petunjuk, dan Nabi Nuh juga Kami telah berikan petunjuk dahulu sebelum itu; dan dari keturunan Nabi Ibrahim itu (ialah Nabi-nabi): Daud, dan Sulaiman, dan Ayub, dan Yusuf, dan Musa, dan Harun. Dan demikianlah Kami memberi balasan kepada orang-orang yang berusaha supaya baik amal perbuatannya.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 85, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ ٱلصَّٰلِحِينَ', 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ الصَّالِحِينَ', NULL, 'And Zechariah and John and Jesus and Elias - and all were of the righteous.', 'Dan (dari keturunannya juga ialah Nabi-nabi): Zakaria, dan Yahya, dan Isa, dan Ilyas; semuanya dari orang-orang yang soleh.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 86, 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 'وَإِسْمَاعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى الْعَالَمِينَ', NULL, 'And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds.', 'Dan (dari keturunannya juga ialah Nabi-nabi): Ismail, dan Alyasak dan Yunus, dan Lut; dan mereka itu semuanya, Kami lebihkan darjat mereka atas umat-umat (yang ada pada zamannya).', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 87, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَمِنْ آبَائِهِمْ وَذُرِّيَّاتِهِمْ وَإِخْوَانِهِمْ وَاجْتَبَيْنَاهُمْ وَهَدَيْنَاهُمْ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.', 'Dan (Kami juga lebihkan darjat) sebahagian daripada datuk nenek mereka, dan keturunan mereka, dan mereka, dan keturunan mereka, dan saudara-saudara mereka; dan Kami telah pilih mereka, serta Kami tunjukkan mereka ke jalan yang lurus.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 88, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 'ذَٰلِكَ هُدَى اللَّهِ يَهْدِي بِهِ مَن يَشَاءُ مِنْ عِبَادِهِ وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُم مَّا كَانُوا يَعْمَلُونَ', NULL, 'That is the guidance of Allāh by which He guides whomever He wills of His servants. But if they had associated others with Allāh, then worthless for them would be whatever they were doing.', 'Yang demikian itu ialah petunjuk Allah, yang dengannya Ia memimpin sesiapa yang dihendakiNya dari hamba-hambaNya; dan kalau mereka sekutukan (Allah dengan sesuatu yang lain) nescaya gugurlah dari mereka, apa yang mereka telah lakukan (dari amal-amal yang baik).', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 89, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', 'أُولَٰئِكَ الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰؤُلَاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا بِهَا بِكَافِرِينَ', NULL, 'Those are the ones to whom We gave the Scripture and authority and prophethood. But if they [i.e., the disbelievers] deny it, then We have entrusted it to a people who are not therein disbelievers.', 'Mereka itulah orang-orang yang telah Kami berikan kepadanya Kitab Suci, dan Hikmah (ilmu pengetahuan), serta pangkat kenabian. Oleh itu, jika orang-orang (kafir) itu mengingkarinya, maka sesungguhnya Kami akan menyerahkannya kepada kaum (lain) yang tidak akan mengingkarinya.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 90, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ فَبِهُدَىٰهُمُ ٱقْتَدِهْ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', 'أُولَٰئِكَ الَّذِينَ هَدَى اللَّهُ فَبِهُدَاهُمُ اقْتَدِهْ قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَالَمِينَ', NULL, 'Those are the ones whom Allāh has guided, so from their guidance take an example. Say, "I ask of you for it [i.e., this message] no payment. It is not but a reminder for the worlds."', 'Mereka (Nabi-nabi) itulah, orang-orang yang telah diberi petunjuk oleh Allah, maka turutlah olehmu (wahai Muhammad) akan petunjuk mereka; Katakanlah: “Aku tidak meminta upah kepada kamu mengenai petunjuk (Al-Quran yang aku sampaikan) itu. Al-Quran itu tidak lain hanyalah peringatan bagi penduduk alam seluruhnya.', FALSE, NULL, NULL, 138, 7, 55, 111, FALSE, 0, NULL),
(6, 91, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ٱللَّهُ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', 'وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ إِذْ قَالُوا مَا أَنزَلَ اللَّهُ عَلَىٰ بَشَرٍ مِّن شَيْءٍ قُلْ مَنْ أَنزَلَ الْكِتَابَ الَّذِي جَاءَ بِهِ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوا أَنتُمْ وَلَا آبَاؤُكُمْ قُلِ اللَّهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ', NULL, 'And they did not appraise Allāh with true appraisal when they said, "Allāh did not reveal to a human being anything." Say, "Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers." Say, "Allāh [revealed it]." Then leave them in their [empty] discourse, amusing themselves.', 'Dan tiadalah mereka (kaum Yahudi) menghormati Allah sesuai dengan penghormatan yang sebenarnya ketika mereka berkata: “Allah tidak menurunkan sesuatu pun kepada manusia”. Bertanyalah (kepada kaum Yahudi yang ingkar itu): “Siapakah yang menurunkan Kitab (Taurat) yang dibawa oleh Nabi Musa sebagai cahaya dan petunjuk bagi manusia, yang kamu jadikan dia lembaran-lembaran kertas, sambil kamu perlihatkan (kepada orang ramai sebahagian kecil daripadanya) dan kamu sembunyikan kebanyakannya; sedang kamu pula diajarkan (dengan pengajaran-pengajaran yang terkandung di dalamnya), yang tidak diketahui oleh kamu (sebelum itu) dan tidak juga oleh datuk nenek kamu?” Katakanlah (kepada mereka): “Allah jualah (yang menurunkannya)”, kemudian, biarkanlah mereka leka bermain-main dalam kesesatannya.', FALSE, NULL, NULL, 139, 7, 55, 112, FALSE, 0, NULL),
(6, 92, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'وَهَٰذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ مُّصَدِّقُ الَّذِي بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ الْقُرَىٰ وَمَنْ حَوْلَهَا وَالَّذِينَ يُؤْمِنُونَ بِالْآخِرَةِ يُؤْمِنُونَ بِهِ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', NULL, 'And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities [i.e., Makkah] and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers.', 'Dan ini ialah Kitab (Al-Quran) yang Kami turunkan, yang mengandungi berkat (banyak faedah-faedah dan manfaatnya), lagi mengesahkan kebenaran (Kitab-kitab Suci) yang diturunkan sebelumnya, dan supaya engkau memberi peringatan kepada penduduk “Ummul-Qura” (Makkah) serta orang-orang yang tinggal di kelilingnya; dan orang-orang yang beriman kepada hari akhirat, mereka beriman kepada Al-Quran, dan mereka tetap mengerjakan dan memelihara sembahyangnya.', FALSE, NULL, NULL, 139, 7, 55, 112, FALSE, 0, NULL),
(6, 93, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', 'وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ قَالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَا أَنزَلَ اللَّهُ وَلَوْ تَرَىٰ إِذِ الظَّالِمُونَ فِي غَمَرَاتِ الْمَوْتِ وَالْمَلَائِكَةُ بَاسِطُو أَيْدِيهِمْ أَخْرِجُوا أَنفُسَكُمُ الْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى اللَّهِ غَيْرَ الْحَقِّ وَكُنتُمْ عَنْ آيَاتِهِ تَسْتَكْبِرُونَ', NULL, 'And who is more unjust than one who invents a lie about Allāh or says, "It has been inspired to me," while nothing has been inspired to him, and one who says, "I will reveal [something] like what Allāh revealed." And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], "Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allāh other than the truth and [that] you were, toward His verses, being arrogant."', 'Dan siapakah yang lebih zalim daripada orang yang mereka-reka perkara yang dusta terhadap Allah, atau orang yang berkata: “Telah diberi wahyu kepadaku”, padahal tidak diberikan sesuatu wahipun kepadanya; dan orang yang berkata: “Aku akan menurunkan seperti apa yang diturunkan Allah”. Dan (sungguh ngeri) sekiranya engkau melihat ketika orang-orang yang zalim itu dalam penderitaan “sakrat''ul-maut” (ketika hendak putus nyawa), sedang malaikat-malaikat pula menghulurkan tangan mereka (memukul dan menyeksa orang-orang itu) sambil berkata (dengan menengking dan mengejek): “Keluarkanlah nyawa kamu (dari tubuh kamu sendiri); pada hari ini kamu dibalas dengan azab seksa yang menghina (kamu) sehina-hinanya, disebabkan apa yang telah kamu katakan terhadap Allah dengan tidak benar, dan kamu pula (menolak dengan) sombong takbur akan ayat-ayat keteranganNya”.', FALSE, NULL, NULL, 139, 7, 55, 112, FALSE, 0, NULL),
(6, 94, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 'وَلَقَدْ جِئْتُمُونَا فُرَادَىٰ كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَاكُمْ وَرَاءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَاءَكُمُ الَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَاءُ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', NULL, '[It will be said to them], "And you have certainly come to Us alone [i.e., individually] as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your ''intercessors'' which you claimed that they were among you associates [of Allāh]. It has [all] been severed between you, and lost from you is what you used to claim."', 'Dan demi sesungguhnya, kamu tetap datang kepada Kami (pada hari kiamat) dengan bersendirian, sebagaimana Kami jadikan kamu pada mulanya; dan kamu tinggalkan di belakang kamu apa yang telah kami kurniakan kepada kamu; dan Kami tidak melihat beserta kamu penolong-penolong yang kamu anggap dan sifatkan bahawa mereka ialah sekutu-sekutu Allah dalam kalangan kamu. Demi sesungguhnya, telah putuslah perhubungan antara kamu (dengan mereka), dan hilang lenyaplah daripada kamu apa yang dahulu kamu anggap dan sifatkan (memberi faedah dan manfaat).', FALSE, NULL, NULL, 139, 7, 55, 112, FALSE, 0, NULL),
(6, 95, 'إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ذَٰلِكُمُ ٱللَّهُ فَأَنَّىٰ تُؤْفَكُونَ', 'إِنَّ اللَّهَ فَالِقُ الْحَبِّ وَالنَّوَىٰ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَمُخْرِجُ الْمَيِّتِ مِنَ الْحَيِّ ذَٰلِكُمُ اللَّهُ فَأَنَّىٰ تُؤْفَكُونَ', NULL, 'Indeed, Allāh is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allāh; so how are you deluded?', 'Sesungguhnya Allah jualah yang membelah (menumbuhkan) butir (tumbuh-tumbuhan) dan biji (buah-buahan). Ia mengeluarkan yang hidup dari yang mati, dan mengeluarkan yang mati dari yang hidup. Yang sedemikian itu kekuasaannya ialah Allah. Maka bagaimanakah kamu dipalingkan dari menyembahNya (oleh benda-benda yang kamu jadikan sekutuNya)?', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 96, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'فَالِقُ الْإِصْبَاحِ وَجَعَلَ اللَّيْلَ سَكَنًا وَالشَّمْسَ وَالْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ', NULL, '[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing.', 'Allah jualah Yang membelah cahaya subuh (yang menyingsingkan fajar), dan yang menjadikan malam untuk tinggal berehat, dan menjadikan matahari dan bulan untuk mengira waktu (menurut peredarannya). Yang demikian itu adalah kuasa penentuan Allah Yang Maha Kuasa, lagi Maha Mengetahui.', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 97, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'وَهُوَ الَّذِي جَعَلَ لَكُمُ النُّجُومَ لِتَهْتَدُوا بِهَا فِي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ قَدْ فَصَّلْنَا الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ', NULL, 'And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.', 'Dan Dia lah yang menjadikan bintang-bintang bagi kamu supaya kamu berpedoman kepadanya dalam kegelapan (malam) di darat dan di laut. Sesungguhnya kami telah jelaskan tanda-tanda kebesaran (Kami) satu persatu bagi orang-orang yang mengetahui.', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 98, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَفْقَهُونَ', 'وَهُوَ الَّذِي أَنشَأَكُم مِّن نَّفْسٍ وَاحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا الْآيَاتِ لِقَوْمٍ يَفْقَهُونَ', NULL, 'And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand.', 'Dan Dia lah yang mencipta kamu dari diri yang satu (Adam), maka (bagi kamu) disediakan tempat tetap (dalam tulang sulbi bapa kamu atau di bumi), dan tempat simpanan (dalam rahim ibu atau dalam kubur). Sesungguhnya Kami telah jelaskan tanda-tanda kebesaran (Kami) satu persatu bagi orang-orang yang mengerti (secara mendalam).', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 99, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَٰبِهٍ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'وَهُوَ الَّذِي أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ النَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّاتٍ مِّنْ أَعْنَابٍ وَالزَّيْتُونَ وَالرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَابِهٍ انظُرُوا إِلَىٰ ثَمَرِهِ إِذَا أَثْمَرَ وَيَنْعِهِ إِنَّ فِي ذَٰلِكُمْ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe.', 'Dan Dia lah yang menurunkan hujan dari langit lalu Kami tumbuhkan dengan air hujan itu segala jenis tumbuh-tumbuhan, kemudian Kami keluarkan daripadanya tanaman yang menghijau, Kami keluarkan pula dari tanaman itu butir-butir (buah) yang bergugus-gugus; dan dari pohon-pohon tamar (kurma), dari mayang-mayangnya (Kami keluarkan) tandan-tandan buah yang mudah dicapai dan dipetik; dan (Kami jadikan) kebun-kebun dari anggur dan zaiton serta buah delima, yang bersamaan (bentuk, rupa dan rasanya) dan yang tidak bersamaan. Perhatikanlah kamu kepada buahnya apabila ia berbuah, dan ketika masaknya. Sesungguhnya yang demikian itu mengandungi tanda-tanda (yang menunjukkan kekuasaan Kami) bagi orang-orang yang beriman.', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 100, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', 'وَجَعَلُوا لِلَّهِ شُرَكَاءَ الْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا لَهُ بَنِينَ وَبَنَاتٍ بِغَيْرِ عِلْمٍ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يَصِفُونَ', NULL, 'But they have attributed to Allāh partners - the jinn, while He has created them - and have fabricated for Him sons and daughters without knowledge. Exalted is He and high above what they describe.', 'Dan mereka menjadikan jin sekutu bagi Allah, padahal Allah jualah yang mencipta jin-jin itu; dan mereka berdusta terhadap Allah dengan mengada-adakan bagiNya anak-anak lelaki dan anak-anak perempuan, dengan tidak berdasarkan sebarang pengetahuan. Maha Suci Allah dan Maha Tinggilah Ia dari apa yang mereka sifatkan!', FALSE, NULL, NULL, 140, 7, 56, 113, FALSE, 0, NULL),
(6, 101, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌ وَخَلَقَ كُلَّ شَىْءٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ أَنَّىٰ يَكُونُ لَهُ وَلَدٌ وَلَمْ تَكُن لَّهُ صَاحِبَةٌ وَخَلَقَ كُلَّ شَيْءٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, '[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion [i.e., wife] and He created all things? And He is, of all things, Knowing.', '(Dia lah) yang menciptakan langit dan bumi. Bagaimanakah Ia mempunyai anak sedang Ia tidak mempunyai isteri? Ia pula yang menciptakan tiap-tiap sesuatu, dan Dia lah Yang Maha Mengetahui akan segala-galanya.', FALSE, NULL, NULL, 140, 7, 56, 114, FALSE, 0, NULL),
(6, 102, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَآ إِلَٰهَ إِلَّا هُوَ خَٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'ذَٰلِكُمُ اللَّهُ رَبُّكُمْ لَا إِلَٰهَ إِلَّا هُوَ خَالِقُ كُلِّ شَيْءٍ فَاعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ وَكِيلٌ', NULL, 'That is Allāh, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things.', 'Yang demikian (sifat-sifatNya dan kekuasaanNya) ialah Allah Tuhan kamu, tiada Tuhan (yang berhak disembah) melainkan Dia, yang menciptakan tiap-tiap sesuatu, maka beribadatlah kamu kepadaNya. Dan (ingatlah) Dia lah yang mentadbirkan segala-galanya.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 103, 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'لَّا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ', NULL, 'Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Aware.', 'Ia tidak dapat dilihat dan diliputi oleh penglihatan mata, sedang Ia dapat melihat (dan mengetahui hakikat) segala penglihatan (mata), dan Dia lah Yang Maha Halus (melayan hamba-hambaNya dengan belas kasihan), lagi Maha Mendalam pengetahuanNya.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 104, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِىَ فَعَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', 'قَدْ جَاءَكُم بَصَائِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِ وَمَنْ عَمِيَ فَعَلَيْهَا وَمَا أَنَا عَلَيْكُم بِحَفِيظٍ', NULL, 'There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], "I am not a guardian over you."', '(Katakanlah wahai Muhammad): “Sesungguhnya telah datang kepada kamu keterangan-keterangan (dalil-dalil dan bukti) dari Tuhan kamu; oleh itu sesiapa melihat (kebenaran itu serta menerimanya) maka faedahnya terpulang kepada dirinya sendiri, dan sesiapa buta (dan enggan menerimanya) maka bahayanya tertimpalah ke atas dirinya sendiri. Dan tiadalah aku berkewajipan menjaga dan mengawasi kamu”.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 105, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ', 'وَكَذَٰلِكَ نُصَرِّفُ الْآيَاتِ وَلِيَقُولُوا دَرَسْتَ وَلِنُبَيِّنَهُ لِقَوْمٍ يَعْلَمُونَ', NULL, 'And thus do We diversify the verses so they [i.e., the disbelievers] will say, "You have studied," and so We may make it [i.e., the Qur’ān] clear for a people who know.', 'Dan demikianlah Kami menerangkan ayat-ayat keterangan Kami satu persatu (dengan berbagai cara, untuk menimbulkan keingkaran mereka) dan supaya mereka (yang ingkar itu menuduhmu dengan) berkata: “Engkau telah mempelajarinya (dari orang-orang lain)”, dan supaya kami menerangkan (Al-Quran) itu kepada orang-orang yang (mahu) mengetahui.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 106, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ لَآ إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'اتَّبِعْ مَا أُوحِيَ إِلَيْكَ مِن رَّبِّكَ لَا إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ', NULL, 'Follow, [O Muḥammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allāh.', 'Ikutlah apa yang telah diwahyukan kepadamu dari Tuhanmu, tiada Tuhan (yang berhak disembah) melainkan Dia, dan berpalinglah dari orang-orang musyrik.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 107, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'وَلَوْ شَاءَ اللَّهُ مَا أَشْرَكُوا وَمَا جَعَلْنَاكَ عَلَيْهِمْ حَفِيظًا وَمَا أَنتَ عَلَيْهِم بِوَكِيلٍ', NULL, 'But if Allāh had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them.', 'Dan kalau Allah menghendaki, nescaya mereka tidak mempersekutukanNya; dan Kami tidak menjadikan engkau (wahai Muhammad) penjaga dan pengawal mereka, dan engkau pula bukanlah wakil yang menguruskan hal-hal mereka (kerana semuanya itu terserah kepada Allah semata-mata).', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 108, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِن دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ', NULL, 'And do not insult those they invoke other than Allāh, lest they insult Allāh in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do.', 'Dan janganlah kamu cerca benda-benda yang mereka sembah yang lain dari Allah, kerana mereka kelak, akan mencerca Allah secara melampaui batas dengan ketiadaan pengetahuan. Demikianlah Kami memperelokkan pada pandangan tiap-tiap umat akan amal perbuatan mereka, kemudian kepada Tuhan merekalah tempat kembali mereka, lalu Ia menerangkan kepada mereka apa yang mereka telah lakukan.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 109, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 'وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِن جَاءَتْهُمْ آيَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا الْآيَاتُ عِندَ اللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَا إِذَا جَاءَتْ لَا يُؤْمِنُونَ', NULL, 'And they swear by Allāh their strongest oaths that if a sign came to them, they would surely believe in it. Say, "The signs are only with [i.e., from] Allāh." And what will make you perceive that even if it [i.e., a sign] came, they would not believe.', 'Dan mereka pula bersumpah dengan nama Allah, dengan menegaskan sumpah mereka bersungguh-sungguh, bahawa sesungguhnya jika datang kepada mereka sesuatu mukjizat (sebagaimana yang mereka minta itu), tentulah mereka akan beriman kepadanya. Katakanlah (wahai Muhammad): “Bahawa soal mendatangkan mukjizat-mukjizat itu hanyalah Allah yang menentukannya, dan kamu tidak menyedari (wahai orang-orang Islam), bahawa apabila mukjizat-mukjizat (yang mereka minta) itu datang, mereka juga tidak akan beriman.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 110, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ', NULL, 'And We will turn away their hearts and their eyes just as they refused to believe in it [i.e., the revelation] the first time. And We will leave them in their transgression, wandering blindly.', 'Dan kami palingkan hati mereka dan pemandangan mereka sebagaimana mereka telah tidak (mahu) beriman kepada (ayat-ayat Kami ketika datang kepada mereka) pada awal mulanya, dan Kami biarkan mereka meraba-raba di dalam kesesatannya dengan bingung.', FALSE, NULL, NULL, 141, 7, 56, 114, FALSE, 0, NULL),
(6, 111, 'وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', 'وَلَوْ أَنَّنَا نَزَّلْنَا إِلَيْهِمُ الْمَلَائِكَةَ وَكَلَّمَهُمُ الْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَيْءٍ قُبُلًا مَّا كَانُوا لِيُؤْمِنُوا إِلَّا أَن يَشَاءَ اللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', NULL, 'And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allāh should will. But most of them, [of that], are ignorant.', 'Dan jika Kami turunkan malaikat pun kepada mereka, dan orang-orang yang mati (hidup semula lalu) berkata-kata dengan mereka, dan kami himpunkan pula tiap-tiap sesuatu di hadapan mereka (untuk menjadi saksi tentang kebenaran Nabi Muhammad), nescaya mereka tidak juga akan beriman, kecuali jika dikehendaki Allah; tetapi kebanyakan mereka tidak mengetahui (hakikat yang sebenar).', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 112, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الْإِنسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', NULL, 'And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent.', 'Dan demikianlah Kami jadikan bagi tiap-tiap Nabi itu musuh dari Syaitan-syaitan manusia dan jin, setengahnya membisikkan kepada setengahnya yang lain kata-kata dusta yang indah-indah susunannya untuk memperdaya pendengarnya. Dan jika Tuhanmu menghendaki, tentulah mereka tidak melakukannya. Oleh itu, biarkanlah mereka dan apa yang mereka ada-adakan (dari perbuatan yang kufur dan dusta) itu.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 113, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 'وَلِتَصْغَىٰ إِلَيْهِ أَفْئِدَةُ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا مَا هُم مُّقْتَرِفُونَ', NULL, 'And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it [i.e., deceptive speech] and that they will be satisfied with it and that they will commit that which they are committing.', 'Dan juga supaya hati orang-orang yang tidak beriman kepada hari akhirat cenderung kepada bisikan itu, dan supaya disetujui oleh mereka, dan juga supaya mereka (terus) melakukan apa yang mereka lakukan itu.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 114, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًا وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'أَفَغَيْرَ اللَّهِ أَبْتَغِي حَكَمًا وَهُوَ الَّذِي أَنزَلَ إِلَيْكُمُ الْكِتَابَ مُفَصَّلًا وَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْلَمُونَ أَنَّهُ مُنَزَّلٌ مِّن رَّبِّكَ بِالْحَقِّ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ', NULL, '[Say], "Then is it other than Allāh I should seek as judge while it is He who has revealed to you the Book [i.e., the Qur’ān] explained in detail?" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters.', '(Katakanlah wahai Muhammad): “Patutkah aku (terpedaya dengan kata-kata dusta Syaitan-syaitan itu sehingga aku) hendak mencari hakim selain dari Allah, padahal Dia lah yang menurunkan kepada kamu kitab Al-Quran yang jelas nyata kandungannya satu persatu (tentang yang benar dan yang salah)?” Dan orang-orang yang Kami berikan kitab, mengetahui bahawa Al-Quran itu adalah diturunkan dari Tuhanmu dengan sebenar-benarnya. Oleh itu, jangan sekali-kali engkau menjadi (salah seorang) dari golongan yang ragu-ragu.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 115, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَاتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing.', 'Dan telah sempurnalah Kalimah Tuhanmu (Al-Quran, meliputi hukum-hukum dan janji-janjiNya) dengan benar dan adil; tiada sesiapa yang dapat mengubah sesuatupun dari Kalimah-kalimahNya; dan Dia lah yang sentiasa Mendengar, lagi sentiasa Mengetahui.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 116, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'وَإِن تُطِعْ أَكْثَرَ مَن فِي الْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ اللَّهِ إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', NULL, 'And if you obey most of those upon the earth, they will mislead you from the way of Allāh. They follow not except assumption, and they are not but misjudging.', 'Dan jika engkau menurut kebanyakan orang yang ada di muka bumi, nescaya mereka akan menyesatkanmu dari jalan Allah; tiadalah yang mereka turut melainkan sangkaan semata-mata, dan mereka tidak lain hanyalah berdusta.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 117, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ', NULL, 'Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided.', 'Sesungguhnya Tuhanmu, Dia lah yang lebih mengetahui akan sesiapa yang sesat dari jalannya, dan Dia lah yang lebih mengetahui akan orang-orang yang mendapat petunjuk.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 118, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', 'فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ إِن كُنتُم بِآيَاتِهِ مُؤْمِنِينَ', NULL, 'So eat of that [meat] upon which the name of Allāh has been mentioned, if you are believers in His verses [i.e., revealed law].', 'Maka makanlah dari (sembelihan binatang-binatang halal) yang disebut nama Allah ketika menyembelihnya, jika betul kamu beriman kepada ayat-ayatNya.', FALSE, NULL, NULL, 142, 8, 57, 115, FALSE, 0, NULL),
(6, 119, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَائِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِالْمُعْتَدِينَ', NULL, 'And why should you not eat of that upon which the name of Allāh has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors.', 'Dan tidak ada sebab bagi kamu, (yang menjadikan) kamu tidak mahu makan dari (sembelihan binatang-binatang halal) yang disebut nama Allah ketika menyembelihnya, padahal Allah telah menerangkan satu persatu kepada kamu apa yang diharamkanNya atas kamu, kecuali apa yang kamu terpaksa memakannya? Dan sesungguhnya kebanyakan manusia hendak menyesatkan dengan hawa nafsu mereka dengan tidak berdasarkan pengetahuan. Sesungguhnya Tuhanmu, Dia lah yang lebih mengetahui akan orang-orang yang melampaui batas.', FALSE, NULL, NULL, 143, 8, 57, 115, FALSE, 0, NULL),
(6, 120, 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 'وَذَرُوا ظَاهِرَ الْإِثْمِ وَبَاطِنَهُ إِنَّ الَّذِينَ يَكْسِبُونَ الْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا يَقْتَرِفُونَ', NULL, 'And leave [i.e., desist from] what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit.', 'Dan tinggalkanlah kamu dosa yang nyata dan yang tersembunyi. Kerana sesungguhnya orang-orang yang berusaha melakukan dosa, mereka akan dibalas dengan apa yang mereka telah lakukan.', FALSE, NULL, NULL, 143, 8, 57, 115, FALSE, 0, NULL),
(6, 121, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 'وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ وَإِنَّهُ لَفِسْقٌ وَإِنَّ الشَّيَاطِينَ لَيُوحُونَ إِلَىٰ أَوْلِيَائِهِمْ لِيُجَادِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', NULL, 'And do not eat of that upon which the name of Allāh has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him].', 'Dan janganlah kamu makan dari (sembelihan binatang-binatang halal) yang tidak disebut nama Allah ketika menyembelihnya, kerana sesungguhnya yang sedemikian itu adalah perbuatan fasik (berdosa); dan sesungguhnya Syaitan-syaitan itu membisikkan kepada pengikut-pengikutnya, supaya mereka membantah (menghasut) kamu; dan jika kamu menurut hasutan mereka (untuk menghalalkan yang haram itu), sesungguhnya kamu tetap menjadi orang-orang musyrik.', FALSE, NULL, NULL, 143, 8, 57, 115, FALSE, 0, NULL),
(6, 122, 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ كَمَن مَّثَلُهُ فِي الظُّلُمَاتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَافِرِينَ مَا كَانُوا يَعْمَلُونَ', NULL, 'And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing.', 'Dan adakah orang yang mati (hatinya dengan kufur), kemudian Kami hidupkan dia semula (dengan hidayah petunjuk), dan Kami jadikan baginya cahaya (iman) yang menerangi (sehingga dapatlah ia membezakan antara yang benar dengan yang salah, dan dapatlah) ia berjalan dengan suluhan cahaya itu dalam masyarakat manusia, (adakah orang yang demikian keadaannya) sama seperti yang tinggal tetap di dalam gelap-gelita (kufur), yang tidak dapat keluar sama sekali daripadanya? Demikianlah (sebagaimana iman itu diperlihatkan keelokannya kepada orang-orang yang beriman), diperlihatkan pula pada pandangan orang-orang yang kafir itu akan keelokan apa yang mereka telah lakukan (dari perbuatan kufur dan segala jenis maksiat).', FALSE, NULL, NULL, 143, 8, 57, 116, FALSE, 0, NULL),
(6, 123, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 'وَكَذَٰلِكَ جَعَلْنَا فِي كُلِّ قَرْيَةٍ أَكَابِرَ مُجْرِمِيهَا لِيَمْكُرُوا فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', NULL, 'And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not.', 'Dan demikianlah Kami adakan dalam tiap-tiap negeri orang-orang besar yang jahat supaya mereka melakukan tipu daya di negeri itu, padahal tiadalah mereka memperdayakan selain dari dirinya sendiri (kerana merekalah yang akan menerima akibatnya yang buruk), sedang mereka tidak menyedarinya.', FALSE, NULL, NULL, 143, 8, 57, 116, FALSE, 0, NULL),
(6, 124, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 'وَإِذَا جَاءَتْهُمْ آيَةٌ قَالُوا لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَا أُوتِيَ رُسُلُ اللَّهِ اللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُ سَيُصِيبُ الَّذِينَ أَجْرَمُوا صَغَارٌ عِندَ اللَّهِ وَعَذَابٌ شَدِيدٌ بِمَا كَانُوا يَمْكُرُونَ', NULL, 'And when a sign comes to them, they say, "Never will we believe until we are given like that which was given to the messengers of Allāh." Allāh is most knowing of where [i.e., with whom] He places His message. There will afflict those who committed crimes debasement before Allāh and severe punishment for what they used to conspire.', 'Dan apabila datang kepada mereka sesuatu keterangan, mereka berkata: “Kami tidak akan beriman sehingga kami juga diberi (wahyu) sama seperti yang telah diberikan kepada pesuruh-pesuruh Allah”. Allah lebih mengetahui di mana (dan kepada siapakah yang sepatutnya) Ia berikan jawatan Rasul (dan wahyu) yang diberikanNya itu. Orang-orang yang melakukan perbuatan yang salah itu akan ditimpa kehinaan di sisi Allah, dan azab seksa yang amat berat, disebabkan perbuatan tipu daya yang mereka lakukan.', FALSE, NULL, NULL, 143, 8, 57, 116, FALSE, 0, NULL),
(6, 125, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', 'فَمَن يُرِدِ اللَّهُ أَن يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَن يُرِدْ أَن يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ كَذَٰلِكَ يَجْعَلُ اللَّهُ الرِّجْسَ عَلَى الَّذِينَ لَا يُؤْمِنُونَ', NULL, 'So whoever Allāh wants to guide - He expands his breast to [contain] Islām; and whoever He wants to send astray - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allāh place defilement upon those who do not believe.', 'Maka sesiapa yang Allah kehendaki untuk memberi hidayah petunjuk kepadanya nescaya Ia melapangkan dadanya (membuka hatinya) untuk menerima Islam; dan sesiapa yang Allah kehendaki untuk menyesatkannya, nescaya Ia menjadikan dadanya sesak sempit sesempit-sempitnya, seolah-olah ia sedang mendaki naik ke langit (dengan susah payahnya). Demikianlah Allah menimpakan azab kepada orang-orang yang tidak beriman.', FALSE, NULL, NULL, 144, 8, 57, 116, FALSE, 0, NULL),
(6, 126, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَذَّكَّرُونَ', 'وَهَٰذَا صِرَاطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا الْآيَاتِ لِقَوْمٍ يَذَّكَّرُونَ', NULL, 'And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.', 'Dan inilah jalan Tuhanmu (ugama Islam) yang betul lurus. Sesungguhnya Kami telah menjelaskan ayat-ayat keterangan (Kami) satu persatu, bagi kaum yang mahu beringat - insaf.', FALSE, NULL, NULL, 144, 8, 57, 116, FALSE, 0, NULL),
(6, 127, 'لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'لَهُمْ دَارُ السَّلَامِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا يَعْمَلُونَ', NULL, 'For them will be the Home of Peace [i.e., Paradise] with their Lord. And He will be their protecting friend because of what they used to do.', 'Bagi merekalah Syurga Darus-Salaam (tempat tinggal yang aman sejahtera) di sisi Tuhan mereka, dan Dia lah Penolong mereka, disebabkan amal-amal (yang baik) yang mereka telah kerjakan.', FALSE, NULL, NULL, 144, 8, 58, 116, FALSE, 0, NULL),
(6, 128, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُم مِّنَ الْإِنسِ وَقَالَ أَوْلِيَاؤُهُم مِّنَ الْإِنسِ رَبَّنَا اسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَا أَجَلَنَا الَّذِي أَجَّلْتَ لَنَا قَالَ النَّارُ مَثْوَاكُمْ خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', NULL, 'And [mention, O Muḥammad], the Day when He will gather them together [and say], "O company of jinn, you have [misled] many of mankind." And their allies among mankind will say, "Our Lord, some of us made use of others, and we have [now] reached our term which You appointed for us." He will say, "The Fire is your residence, wherein you will abide eternally, except for what Allāh wills. Indeed, your Lord is Wise and Knowing."', 'Dan (ingatlah) hari (kiamat yang padanya) Allah akan himpunkan mereka semua, (lalu berfirman): “Wahai sekalian jin (Syaitan-syaitan)! Sesungguhnya kamu telah banyak pengikut-pengikut dari manusia”. Dan berkatalah pula pengikut-pengikut mereka dari golongan manusia: “Wahai Tuhan kami, sebahagian kami (manusia) telah bersenang-senang (mendapat kemudahan) dengan sebahagian yang lain (Syaitan-syaitan), dan kami telah sampailah kepada masa kami (hari kiamat) yang Engkau telah tentukan bagi kami”. (Allah berfirman): “Nerakalah tempat kediaman kamu, kekal kamu di dalamnya, kecuali apa yang dikehendaki Allah”. Sesungguhnya Tuhanmu (wahai Muhammad) Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 144, 8, 58, 116, FALSE, 0, NULL),
(6, 129, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'وَكَذَٰلِكَ نُوَلِّي بَعْضَ الظَّالِمِينَ بَعْضًا بِمَا كَانُوا يَكْسِبُونَ', NULL, 'And thus will We make some of the wrongdoers allies of others for what they used to earn.', 'Dan demikianlah Kami jadikan sebahagian dari orang-orang yang zalim itu kawan rapat dengan sebahagian yang lain, disebabkan apa yang mereka telah usahakan (dari perbuatan-perbuatan kufur dan maksiat itu).', FALSE, NULL, NULL, 144, 8, 58, 116, FALSE, 0, NULL),
(6, 130, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَٰذَا قَالُوا شَهِدْنَا عَلَىٰ أَنفُسِنَا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَشَهِدُوا عَلَىٰ أَنفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ', NULL, '"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?" They will say, "We bear witness against ourselves"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers.', 'Wahai sekalian jin dan manusia! Bukankah telah datang kepada kamu Rasul-rasul dari kalangan kamu sendiri, yang menyampaikan kepada kamu ayat-ayatKu (perintah-perintahKu), dan yang memberikan amaran kepada kamu tentang pertemuan kamu dengan hari (kiamat) ini? Mereka menjawab: “Kami menjadi saksi mengakui akan (kesalahan) diri kami sendiri (mendustakan Rasul-rasul itu)”. Dan (sebabnya ialah) mereka telah diperdayakan oleh (kemewahan) hidup di dunia dan (kerana itulah) mereka menjadi saksi (pada hari akhirat) terhadap diri mereka sendiri: (bahawa) sesungguhnya mereka adalah orang-orang yang mengingkari (apa yang telah disampaikan oleh Rasul-rasul itu).', FALSE, NULL, NULL, 144, 8, 58, 117, FALSE, 0, NULL),
(6, 131, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَٰفِلُونَ', 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ الْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَافِلُونَ', NULL, 'That is because your Lord would not destroy the cities for wrongdoing while their people were unaware.', 'Yang demikian (kedatangan Rasul-rasul itu ialah), kerana Tuhanmu tidak membinasakan negeri-negeri secara zalim sedang penduduknya leka lalai.', FALSE, NULL, NULL, 144, 8, 58, 117, FALSE, 0, NULL),
(6, 132, 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'وَلِكُلٍّ دَرَجَاتٌ مِّمَّا عَمِلُوا وَمَا رَبُّكَ بِغَافِلٍ عَمَّا يَعْمَلُونَ', NULL, 'And for all are degrees [i.e., positions resulting] from what they have done. And your Lord is not unaware of what they do.', 'Dan bagi tiap-tiap seorang (dari manusia atau jin), beberapa darjat (tingkatan balasan) disebabkan (amal baik atau jahat) yang mereka telah kerjakan; dan (ingatlah) Tuhanmu tiadalah lalai dari apa yang mereka lakukan.', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 133, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', 'وَرَبُّكَ الْغَنِيُّ ذُو الرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِن بَعْدِكُم مَّا يَشَاءُ كَمَا أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ آخَرِينَ', NULL, 'And your Lord is the Free of need, the possessor of mercy. If He wills, He can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people.', 'Dan Tuhanmu Maha Kaya, lagi Melimpah-limpah rahmatNya. Jika Ia kehendaki, nescaya Ia binasakan kamu dan menggantikan sesudah (binasanya) kamu dengan sesiapa yang dikehendakiNya, sebagaimana Ia telah menjadikan kamu dari keturunan kaum yang lain.', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 134, 'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ وَمَآ أَنتُم بِمُعْجِزِينَ', 'إِنَّ مَا تُوعَدُونَ لَآتٍ وَمَا أَنتُم بِمُعْجِزِينَ', NULL, 'Indeed, what you are promised is coming, and you will not cause failure [to Allāh].', 'Sesungguhnya apa yang dijanjikan kepada kamu (hari kiamat dan balasannya) tetap akan datang, dan kamu tidak akan dapat melepaskan diri (dari balasan itu).', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 135, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'قُلْ يَا قَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', NULL, 'Say, "O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed."', 'Katakanlah (wahai Muhammad): “Wahai kaumku (yang masih kafir), buatlah sedaya upaya kamu (untuk menentang Islam), sesungguhnya aku juga tetap beramal (berusaha dengan bersungguh-sungguh untuk mempertahankan Islam); kemudian kamu akan ketahui siapakah yang akan beroleh kebaikan dan kejayaan di dunia ini. Sesungguhnya orang-orang yang zalim itu tidak akan berjaya.', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 136, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ', 'وَجَعَلُوا لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعَامِ نَصِيبًا فَقَالُوا هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَائِنَا فَمَا كَانَ لِشُرَكَائِهِمْ فَلَا يَصِلُ إِلَى اللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَائِهِمْ سَاءَ مَا يَحْكُمُونَ', NULL, 'And they [i.e., the polytheists] assign to Allāh from that which He created of crops and livestock a share and say, "This is for Allāh," by their claim, "and this is for our ''partners'' [associated with Him]." But what is for their "partners" does not reach Allāh, while what is for Allāh - this reaches their "partners." Evil is that which they rule.', 'Dan mereka (orang-orang musyrik) memperuntukkan dari hasil tanaman dan binatang-binatang ternak yang diciptakan oleh Allah itu, sebahagian bagi Allah (dan sebahagian lagi untuk berhala-berhala mereka), lalu mereka berkata: Ini untuk Allah - menurut anggapan mereka - dan ini untuk berhala-berhala kami.” Kemudian apa yang telah ditentukan untuk berhala-berhala mereka, maka ia tidak sampai kepada Allah (kerana mereka tidak membelanjakannya pada jalan Allah), dan apa yang telah ditentukan untuk Allah, sampai pula kepada berhala-berhala mereka (kerana mereka membelanjakannya pada jalan itu). Amatlah jahatnya apa yang mereka hukumkan itu.', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 137, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ الْمُشْرِكِينَ قَتْلَ أَوْلَادِهِمْ شُرَكَاؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ وَلَوْ شَاءَ اللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', NULL, 'And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allāh had willed, they would not have done so. So leave them and that which they invent.', 'Dan demikianlah juga (jahatnya) ketua-ketua yang orang-orang musyrik itu jadikan sekutu bagi Allah, menghasut kebanyakan dari mereka dengan kata-kata indah yang memperlihatkan eloknya perbuatan membunuh anak-anak mereka, untuk membinasakan mereka, dan untuk mengelirukan mereka nengenai ugama mereka. Dan kalau Allah kehendaki, nescaya mereka tidak melakukannya. Oleh itu biarkanlah mereka dan apa yang mereka ada-adakan itu.', FALSE, NULL, NULL, 145, 8, 58, 117, FALSE, 0, NULL),
(6, 138, 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 'وَقَالُوا هَٰذِهِ أَنْعَامٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَا إِلَّا مَن نَّشَاءُ بِزَعْمِهِمْ وَأَنْعَامٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَامٌ لَّا يَذْكُرُونَ اسْمَ اللَّهِ عَلَيْهَا افْتِرَاءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا يَفْتَرُونَ', NULL, 'And they say, "These animals and crops are forbidden; no one may eat from them except whom we will," by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allāh is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing.', 'Dan mereka berkata lagi: “Ini adalah binatang-binatang ternak dan tanaman-tanaman yang dilarang, yang tidak boleh seorang pun memakannya kecuali sesiapa yang kami kehendaki”, - menurut anggapan mereka; dan (sejenis lagi) binatang-binatang ternak yang dilarang menunggangnya; dan (sejenis lagi) binatang-binatang ternak yang tidak mereka sebutkan nama Allah ketika menyembelihnya; (semuanya itu mereka lakukan dengan) berdusta terhadap Allah. Allah akan membalas mereka disebabkan apa yang mereka telah ada-adakan itu.', FALSE, NULL, NULL, 146, 8, 58, 117, FALSE, 0, NULL),
(6, 139, 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'وَقَالُوا مَا فِي بُطُونِ هَٰذِهِ الْأَنْعَامِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰ أَزْوَاجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَاءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُ حَكِيمٌ عَلِيمٌ', NULL, 'And they say, "What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein." He will punish them for their description. Indeed, He is Wise and Knowing.', 'Dan mereka berkata lagi: “Apa yang ada dalam perut binatang-binatang ternak itu (jika ia lahirkan hidup) adalah halal bagi lelaki-lelaki kami dan haram bagi perempuan-perempuan kami”. Dan jika ia (dilahirkan) mati, maka mereka (lelaki perempuan) bersekutu padanya (bersama-sama memakannya). Allah akan membalas mereka tentang apa yang mereka tetapkan (mengenai halal dan haram) itu. Sesungguhnya Allah Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 146, 8, 58, 117, FALSE, 0, NULL),
(6, 140, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 'قَدْ خَسِرَ الَّذِينَ قَتَلُوا أَوْلَادَهُمْ سَفَهًا بِغَيْرِ عِلْمٍ وَحَرَّمُوا مَا رَزَقَهُمُ اللَّهُ افْتِرَاءً عَلَى اللَّهِ قَدْ ضَلُّوا وَمَا كَانُوا مُهْتَدِينَ', NULL, 'They will have lost who killed their children in foolishness without knowledge and prohibited what Allāh had provided for them, inventing untruth about Allāh. They have gone astray and were not [rightly] guided.', 'Sesungguhnya rugilah orang-orang yang membunuh anak-anak mereka kerana kebodohan, lagi tidak berpengetahuan (sedang Allah yang memberi rezeki kepada sekalian makhluknya), dan juga (rugilah orang-orang yang) mengharamkan apa yang telah dikurniakan oleh Allah kepada mereka, dengan berdusta terhadap Allah. Sesungguhnya sesatlah mereka, dan tiadalah mereka mendapat petunjuk.', FALSE, NULL, NULL, 146, 8, 58, 117, FALSE, 0, NULL),
(6, 141, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍ مَّعْرُوشَٰتٍ وَغَيْرَ مَعْرُوشَٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًا وَغَيْرَ مُتَشَٰبِهٍ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'وَهُوَ الَّذِي أَنشَأَ جَنَّاتٍ مَّعْرُوشَاتٍ وَغَيْرَ مَعْرُوشَاتٍ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفًا أُكُلُهُ وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشَابِهًا وَغَيْرَ مُتَشَابِهٍ كُلُوا مِن ثَمَرِهِ إِذَا أَثْمَرَ وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ', NULL, 'And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakāh] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess.', 'Dan Dia lah (Allah) yang menjadikan (untuk kamu) kebun-kebun yang menjalar tanamannya dan yang tidak menjalar; dan pohon-pohon tamar (kurma) dan tanaman-tanaman yang berlainan (bentuk, rupa dan) rasanya; dan buah zaiton dan delima, yang bersamaan (warnanya atau daunnya) dan tidak bersamaan (rasanya). Makanlah dari buahnya ketika ia berbuah, dan keluarkanlah haknya (zakatnya) pada hari memetik atau menuainya; dan janganlah kamu melampau (pada apa-apa jua yang kamu makan atau belanjakan); sesungguhnya Allah tidak suka kepada orang-orang yang melampau.', FALSE, NULL, NULL, 146, 8, 59, 118, FALSE, 0, NULL),
(6, 142, 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةً وَفَرْشًا كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'وَمِنَ الْأَنْعَامِ حَمُولَةً وَفَرْشًا كُلُوا مِمَّا رَزَقَكُمُ اللَّهُ وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ', NULL, 'And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allāh has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', 'Dan di antara binatang-binatang ternak itu, ada yang dijadikan untuk pengangkutan, dan ada yang untuk disembelih. Makanlah dari apa yang telah dikurniakan oleh Allah kepada kamu, dan janganlah kamu menurut jejak langkah Syaitan; kerana sesungguhnya Syaitan itu musuh bagi kamu yang terang nyata.', FALSE, NULL, NULL, 146, 8, 59, 118, FALSE, 0, NULL),
(6, 143, 'ثَمَٰنِيَةَ أَزْوَٰجٍ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'ثَمَانِيَةَ أَزْوَاجٍ مِّنَ الضَّأْنِ اثْنَيْنِ وَمِنَ الْمَعْزِ اثْنَيْنِ قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحَامُ الْأُنثَيَيْنِ نَبِّئُونِي بِعِلْمٍ إِن كُنتُمْ صَادِقِينَ', NULL, '[They are] eight mates - of the sheep, two and of the goats, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful."', '(Binatang ternak itu) delapan ekor - (empat) pasangan; dari kambing biri-biri dua ekor (sepasang jantan betina), dan dari kambing biasa dua ekor (sepasang jantan betina). Tanyalah (wahai Muhammad kepada orang-orang musyrik itu): “Adakah yang diharamkan Allah itu, dua jantannya atau dua betinanya, atau yang dikandung oleh rahim dua betinanya? Terangkanlah kepadaku dengan berdasarkan ilmu pengetahuan (Syarak dari Allah yang menjadi dalil tentang haramnya), jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 147, 8, 59, 118, FALSE, 0, NULL),
(6, 144, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'وَمِنَ الْإِبِلِ اثْنَيْنِ وَمِنَ الْبَقَرِ اثْنَيْنِ قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحَامُ الْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَاءَ إِذْ وَصَّاكُمُ اللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا لِّيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'And of the camels, two and of the cattle, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allāh charged you with this? Then who is more unjust than one who invents a lie about Allāh to mislead the people by [something] other than knowledge? Indeed, Allāh does not guide the wrongdoing people."', 'Dan dari unta dua ekor (sepasang jantan betina), dan dari lembu dua ekor (sepasang jantan betina). Tanyalah (wahai Muhammad): “Adakah yang diharamkan Allah itu dua jantannya atau dua betinanya, atau yang dikandung oleh rahim dua betinanya? Ataupun kamu ada menyaksikan ketika Allah menyuruh serta menentukan kepada kamu (atau kepada datuk nenek kamu) dengan yang demikian ini?” Oleh itu, siapakah yang lebih zalim daripada orang yang berdusta terhadap Allah untuk menyesatkan manusia dengan tidak berdasarkan ilmu pengetahuan? Sesungguhnya Allah tidak memberi petunjuk kepada kaum yang zalim.', FALSE, NULL, NULL, 147, 8, 59, 118, FALSE, 0, NULL),
(6, 145, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', 'قُل لَّا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُ إِلَّا أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', NULL, 'Say, "I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allāh. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful."', 'Katakanlah (wahai Muhammad): “Aku tidak dapati dalam apa yang telah diwahyukan kepadaku, sesuatu yang diharamkan bagi orang yang hendak memakannya melainkan kalau benda itu bangkai, atau darah yang mengalir, atau daging babi - kerana sesungguhnya ia adalah kotor - atau sesuatu yang dilakukan secara fasik, iaitu binatang yang disembelih atas nama yang lain dari Allah”. Kemudian sesiapa yang terpaksa (memakannya kerana darurat) sedang ia tidak mengingininya dan tidak melampaui batas, maka sesungguhnya Tuhan mu Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 147, 8, 59, 119, FALSE, 0, NULL),
(6, 146, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ وَإِنَّا لَصَٰدِقُونَ', 'وَعَلَى الَّذِينَ هَادُوا حَرَّمْنَا كُلَّ ذِي ظُفُرٍ وَمِنَ الْبَقَرِ وَالْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَا إِلَّا مَا حَمَلَتْ ظُهُورُهُمَا أَوِ الْحَوَايَا أَوْ مَا اخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَاهُم بِبَغْيِهِمْ وَإِنَّا لَصَادِقُونَ', NULL, 'And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their transgression. And indeed, We are truthful.', 'Dan Kami haramkan atas orang-orang Yahudi segala binatang yang berkuku, dan dari lembu dan kambing pula Kami haramkan kepada mereka lemaknya, kecuali (lemak) yang ada pada belakangnya atau yang menyelaputi perkakas dalam perutnya, atau yang bercampur dengan tulang. Demikianlah Kami balas mereka dengan sebab kederhakaan mereka; dan sesungguhnya Kamilah yang benar.', FALSE, NULL, NULL, 147, 8, 59, 119, FALSE, 0, NULL),
(6, 147, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَاسِعَةٍ وَلَا يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ', NULL, 'So if they deny you, [O Muḥammad], say, "Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals."', 'Kemudian jika mereka mendustakanmu (wahai Muhammad) maka katakanlah: “Tuhan kamu mempunyai rahmat yang luas melimpah-ruah, dan azab seksaNya tidak dapat ditolak dari kaum yang berdosa”.', FALSE, NULL, NULL, 148, 8, 59, 119, FALSE, 0, NULL),
(6, 148, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', 'سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللَّهُ مَا أَشْرَكْنَا وَلَا آبَاؤُنَا وَلَا حَرَّمْنَا مِن شَيْءٍ كَذَٰلِكَ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَا إِن تَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', NULL, 'Those who associated [others] with Allāh will say, "If Allāh had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything." Likewise did those before deny until they tasted Our punishment. Say, "Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but misjudging."', 'Orang-orang musyrik akan mengatakan: “Kalau Allah menghendaki tentulah kami dan datuk nenek kami tidak mempersekutukanNya (dengan sesuatu yang lain), dan tidak pula kami haramkan sesuatu apa pun”. Demikianlah juga orang-orang yang dahulu sebelum mereka telah mendustakan (Rasul-rasul) sehingga mereka merasai azab seksa Kami. Katakanlah: Adakah kamu mempunyai (sesuatu keterangan yang berdasarkan) ilmu supaya dapat kamu tunjukkan kepada kami? Tiadalah kamu menurut melainkan sangkaan semata-mata, dan kamu pula tidak lain hanyalah berdusta”.', FALSE, NULL, NULL, 148, 8, 59, 119, FALSE, 0, NULL),
(6, 149, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'قُلْ فَلِلَّهِ الْحُجَّةُ الْبَالِغَةُ فَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ', NULL, 'Say, "With Allāh is the far-reaching [i.e., conclusive] argument. If He had willed, He would have guided you all."', 'Katakanlah (wahai Muhammad: “Kalau kamu sudah tidak ada sesuatu bukti) maka Allah mempunyai bukti yang tegas nyata. Oleh itu, jika Ia menghendaki tentulah Ia akan memberi hidayah petunjuk kepada kamu semuanya”.', FALSE, NULL, NULL, 148, 8, 59, 119, FALSE, 0, NULL),
(6, 150, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 'قُلْ هَلُمَّ شُهَدَاءَكُمُ الَّذِينَ يَشْهَدُونَ أَنَّ اللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَالَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', NULL, 'Say, [O Muḥammad], "Bring forward your witnesses who will testify that Allāh has prohibited this." And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord.', 'Katakanlah: “Bawalah saksi-saksi kamu memberi keterangan bahawa Allah mengharamkan (benda-benda yang kamu haramkan) ini”. Kemudian jika mereka (tergamak) menjadi saksi (secara dusta), maka janganlah engkau turut sama membenarkan mereka mereka; dan janganlah engkau turut hawa nafsu orang-orang yang mendustakan ayat-ayat keterangan Kami, dan orang-orang yang tidak beriman kepada hari akhirat, sedang mereka pula menyamakan (sesuatu yang lain) dengan Tuhan mereka.', FALSE, NULL, NULL, 148, 8, 59, 119, FALSE, 0, NULL),
(6, 151, 'قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا وَلَا تَقْتُلُوا أَوْلَادَكُم مِّنْ إِمْلَاقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَعْقِلُونَ', NULL, 'Say, "Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allāh has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason."', 'Katakanlah: “Marilah, supaya aku bacakan apa yang telah diharamkan oleh Tuhan kamu kepada kamu, iaitu janganlah kamu sekutukan dengan Allah sesuatupun; dan hendaklah (kamu) membuat baik kepada ibu bapa; dan janganlah kamu membunuh anak-anak kamu kerana kepapaan, (sebenarnya) Kamilah yang memberi rezeki kepada kamu dan kepada mereka; dan janganlah kamu hampiri kejahatan-kejahatan (zina) - yang terang daripadanya dan yang tersembunyi; dan janganlah kamu membunuh jiwa yang telah diharamkan Allah (membunuhnya) melainkan dengan jalan yang hak (yang dibenarkan oleh Syarak). Dengan yang demikian itulah Allah perintahkan kamu, supaya kamu memahaminya.', FALSE, NULL, NULL, 148, 8, 60, 120, FALSE, 0, NULL),
(6, 152, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 'وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُ وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ اللَّهِ أَوْفُوا ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَذَكَّرُونَ', NULL, 'And do not approach the orphan''s property except in a way that is best [i.e., intending improvement] until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you speak [i.e., testify], be just, even if [it concerns] a near relative. And the covenant of Allāh fulfill. This has He instructed you that you may remember.', '“Dan janganlah kamu hampiri harta anak yatim melainkan dengan cara yang baik (untuk mengawal dan mengembangkannya), sehingga ia baligh (dewasa, serta layak mengurus hartanya dengan sendiri); dan sempurnakanlah segala sukatan dan timbangan dengan adil”. - Kami tidak memberatkan seseorang dengan kewajipan melainkan sekadar kesanggupannya - “dan apabila kamu mengatakan sesuatu (semasa membuat apa-apa keterangan) maka hendaklah kamu berlaku adil, sekalipun orang itu ada hubungan kerabat (dengan kamu); dan perjanjian (perintah-perintah) Allah hendaklah kamu sempurnakan. Dengan yang demikian itulah Allah perintahkan kamu, supaya kamu beringat (mematuhiNya)”.', FALSE, NULL, NULL, 149, 8, 60, 120, FALSE, 0, NULL),
(6, 153, 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 'وَأَنَّ هَٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ ذَٰلِكُمْ وَصَّاكُم بِهِ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous.', 'Dan bahawa sesungguhnya inilah jalanKu (ugama Islam) yang betul lurus, maka hendaklah kamu menurutnya; dan janganlah kamu menurut menurut jalan-jalan (yang lain dari Islam), kerana jalan-jalan (yang lain itu) mencerai-beraikan kamu dari jalan Allah, Dengan yang demikian itulah Allah perintahkan kamu, supaya kamu bertaqwa.', FALSE, NULL, NULL, 149, 8, 60, 120, FALSE, 0, NULL),
(6, 154, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', 'ثُمَّ آتَيْنَا مُوسَى الْكِتَابَ تَمَامًا عَلَى الَّذِي أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَاءِ رَبِّهِمْ يُؤْمِنُونَ', NULL, 'Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good [i.e., Moses] and as a detailed explanation of all things and as guidance and mercy that perhaps in the meeting with their Lord they would believe.', 'Kemudian (ketahuilah pula bahawa) Kami telah memberikan kepada Nabi Musa Kitab Taurat untuk menyempurnakan (kemuliaan dan nikmat Kami) kepada orang yang telah berbuat baik (menjalankan ajaran Kitab itu iaitu Nabi Musa), dan untuk menerangkan tiap-tiap sesuatu, serta menjadi petunjuk dan rahmat, supaya mereka beriman kepada pertemuan dengan Tuhan mereka (pada hari akhirat kelak).', FALSE, NULL, NULL, 149, 8, 60, 120, FALSE, 0, NULL),
(6, 155, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'وَهَٰذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'And this [Qur’ān] is a Book We have revealed [which is] blessed, so follow it and fear Allāh that you may receive mercy.', 'Dan ini sebuah Kitab (Al-Quran) yang Kami turunkan, yang ada berkatnya (banyak manfaatnya). Oleh itu, hendaklah kamu menurutnya; dan bertaqwalah (kepada Allah), mudah-mudahan kamu beroleh rahmat.', FALSE, NULL, NULL, 149, 8, 60, 121, FALSE, 0, NULL),
(6, 156, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', 'أَن تَقُولُوا إِنَّمَا أُنزِلَ الْكِتَابُ عَلَىٰ طَائِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَافِلِينَ', NULL, '[We revealed it] lest you say, "The Scripture was only sent down to two groups before us, but we were of their study unaware,"', 'Supaya kamu tidak mengatakan: “Bahawa Kitab (ugama) itu hanya diturunkan kepada dua golongan (Yahudi dan Nasrani) dahulu sebelum kami, dan sesungguhnya kami lalai (tidak faham) akan apa yang dibaca dan dipelajari oleh mereka”.', FALSE, NULL, NULL, 149, 8, 60, 121, FALSE, 0, NULL),
(6, 157, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 'أَوْ تَقُولُوا لَوْ أَنَّا أُنزِلَ عَلَيْنَا الْكِتَابُ لَكُنَّا أَهْدَىٰ مِنْهُمْ فَقَدْ جَاءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِآيَاتِ اللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِي الَّذِينَ يَصْدِفُونَ عَنْ آيَاتِنَا سُوءَ الْعَذَابِ بِمَا كَانُوا يَصْدِفُونَ', NULL, 'Or lest you say, "If only the Scripture had been revealed to us, we would have been better guided than they." So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allāh and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away.', 'Atau supaya kamu (tidak) mengatakan: “Sesungguhnya kalau diturunkan Kitab kepada kami tentulah kami mendapat petunjuk hidayah lebih daripada mereka”. (Kamu tidak akan dapat berdalih lagi) kerana sesungguhnya telah datang kepada kamu keterangan (yang cukup) dari Tuhan kamu, dan petunjuk hidayah serta rahmatNya (yang melimpah-limpah). Oleh itu, siapakah yang lebih zalim lagi daripada orang yang mendustakan ayat-ayat keterangan Allah dan berpaling daripadanya? Kami akan membalas orang-orang yang berpaling dari ayat-ayat keterangan Kami (dengan) azab seksa yang seburuk-buruknya, disebabkan mereka sentiasa berpaling (mengingkarinya).', FALSE, NULL, NULL, 149, 8, 60, 121, FALSE, 0, NULL),
(6, 158, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًا قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ رَبُّكَ أَوْ يَأْتِيَ بَعْضُ آيَاتِ رَبِّكَ يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا قُلِ انتَظِرُوا إِنَّا مُنتَظِرُونَ', NULL, 'Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, "Wait. Indeed, we [also] are waiting."', 'Apakah (yang ditunggu-tunggu oleh mereka yang tidak beriman itu?) mereka tidak menunggu melainkan kedatangan malaikat (yang mencabut nyawa mereka), atau kedatangan (azab) Tuhanmu, atau kedatangan sebahagian dari tanda-tanda Tuhanmu (yang menjadi alamat hari kiamat). Pada hari datangnya sebahagian dari tanda-tanda Tuhanmu itu, tidak berfaedah lagi iman seseorang yang tidak beriman sebelum itu, atau yang tidak berusaha mengerjakan kebaikan mengenai imannya. Katakanlah: “Tunggulah kamu (akan apa yang kamu berhak mendapatnya), dan kami pun sebenarnya menunggu (akan apa yang telah dijanjikan oleh Tuhan kepada kami)”.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 159, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', 'إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا لَّسْتَ مِنْهُمْ فِي شَيْءٍ إِنَّمَا أَمْرُهُمْ إِلَى اللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا يَفْعَلُونَ', NULL, 'Indeed, those who have divided their religion and become sects - you, [O Muḥammad], are not [associated] with them in anything. Their affair is only [left] to Allāh; then He will inform them about what they used to do.', 'Bahawasanya orang-orang yang mencerai-beraikan ugama mereka (dengan perselisihan-perselisihan yang berdasarkan hawa nafsu), dan mereka menjadi berpuak-puak, tiadalah engkau terkait sedikitpun dalam (perbuatan) mereka. Sesungguhnya perkara mereka hanya terserah kepada Allah. Kemudian Ia akan menerangkan kepada mereka (pada hari kiamat kelak), apa yang telah mereka lakukan (dan membalasnya).', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 160, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', 'مَن جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا وَمَن جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَىٰ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', NULL, 'Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.', 'Sesiapa yang membawa amal kebaikan (pada hari kiamat), maka baginya (balasan) sepuluh kali ganda (dari kebaikan) yang sama dengannya; dan sesiapa yang membawa amal kejahatan, maka ia tidak dibalas melainkan (kejahatan) yang sama dengannya; sedang mereka tidak dianiaya (sedikitpun).', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 161, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'قُلْ إِنَّنِي هَدَانِي رَبِّي إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', NULL, 'Say, "Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allāh."', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku telah diberikan petunjuk hidayah oleh Tuhanku ke jalan yang betul lurus, (kepada) ugama yang tetap teguh, iaitu ugama Nabi Ibrahim yang ikhlas, dan tiadalah ia dari orang-orang musyrik”.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 162, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'Say, "Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allāh, Lord of the worlds.', 'Katakanlah: “Sesungguhnya sembahyangku dan ibadatku, hidupku dan matiku, hanyalah untuk Allah Tuhan yang memelihara dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 163, 'لَا شَرِيكَ لَهُۥ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', 'لَا شَرِيكَ لَهُ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ', NULL, 'No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims."', 'Tiada sekutu bagiNya, dan dengan yang demikian sahaja aku diperintahkan, dan aku (di antara seluruh umatku) adalah orang Islam yang awal pertama - (yang berserah diri kepada Allah dan mematuhi perintahNya)”.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 164, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'قُلْ أَغَيْرَ اللَّهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', NULL, 'Say, "Is it other than Allāh I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ."', 'Katakanlah: “(Sesudah aku mentauhidkan Allah dan berserah diri kepadaNya) patutkah aku mencari Tuhan selain Allah, padahal Dia lah Tuhan bagi tiap-tiap sesuatu? Dan tiadalah (kejahatan) yang diusahakan oleh tiap-tiap seorang melainkan orang itulah sahaja yang menanggung dosanya; dan seseorang yang boleh memikul tidak akan memikul dosa perbuatan orang lain (bahkan dosa usahanya sahaja); kemudian kepada Tuhan kamulah tempat kamu kembali, lalu Ia menerangkan kepada kamu akan apa yang kamu berselisihan padanya.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(6, 165, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ', 'وَهُوَ الَّذِي جَعَلَكُمْ خَلَائِفَ الْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ لِّيَبْلُوَكُمْ فِي مَا آتَاكُمْ إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ', NULL, 'And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.', 'Dan Dia lah yang menjadikan kamu khalifah di bumi dan meninggikan setengah kamu atas setengahnya yang lain beberapa darjat, kerana Ia hendak menguji kamu pada apa yang telah dikurniakanNya kepada kamu. Sesungguhnya Tuhanmu amatlah cepat azab seksaNya, dan sesungguhnya Ia Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 150, 8, 60, 121, FALSE, 0, NULL),
(7, 1, 'الٓمٓصٓ', 'المص', NULL, 'Alif, Lām, Meem, Ṣād.', 'Alif, Laam, Miim, Saad.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 1, NULL),
(7, 2, 'كِتَـٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'كتاب انزل اليك فلا يكن في صدرك حرج منه لتنذر به وذكرى للمؤمنين', NULL, '[This is] a Book revealed to you, [O Muḥammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.', '(Al-Quran ini) sebuah Kitab yang diturunkan kepadamu (wahai Muhammad dari Tuhanmu). Oleh itu, janganlah ada perasaan bimbang dalam dadamu mengenainya, supaya engkau memberi amaran dengan Al-Quran itu (kepada orang-orang yang ingkar), dan supaya menjadi peringatan bagi orang-orang yang beriman.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 13, NULL),
(7, 3, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًا مَّا تَذَكَّرُونَ', 'اتبعوا ما انزل اليكم من ربكم ولا تتبعوا من دونه اولياء قليلا ما تذكرون', NULL, 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.', '(Katakanlah kepada mereka wahai Muhammad): “Turutlah apa yang telah diturunkan kepada kamu dari Tuhan kamu dan janganlah kamu menurut pemimpin-pemimpin yang lain dari Allah; (tetapi sayang) amatlah sedikit kamu mengambil peringatan”.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 14, NULL),
(7, 4, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَا فَجَآءَهَا بَأْسُنَا بَيَـٰتًا أَوْ هُمْ قَآئِلُونَ', 'وكم من قرية اهلكناها فجاءها باسنا بياتا او هم قائلون', NULL, 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.', 'Dan berapa banyak negeri yang Kami binasakan, iaitu datang azab seksa Kami menimpa penduduknya pada malam hari, atau ketika mereka berehat pada tengah hari.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 10, NULL),
(7, 5, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَـٰلِمِينَ', 'فما كان دعواهم اذ جاءهم باسنا الا ان قالوا انا كنا ظالمين', NULL, 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"', 'Maka tidak ada yang mereka katakan ketika datangnya azab Kami kepada mereka, melainkan mereka (mengakui dengan) berkata: “Sebenarnya kami adalah orang-orang yang zalim”.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 12, NULL),
(7, 6, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', 'فلنسالن الذين ارسل اليهم ولنسالن المرسلين', NULL, 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.', 'Maka sesungguhnya Kami (Allah) akan menyoal umat-umat yang telah diutuskan (Rasul-rasul) kepada mereka, dan sesungguhnya Kami akan menyoal juga Rasul-rasul itu.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 6, NULL),
(7, 7, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ ۖ وَمَا كُنَّا غَآئِبِينَ', 'فلنقصن عليهم بعلم وما كنا غائبين', NULL, 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.', 'Kemudian sesungguhnya Kami akan ceritakan kepada mereka (Rasul-rasul dan umat-umatnya), dengan (berdasarkan) pengetahuan (yang meliputi akan apa yang mereka lakukan), dan sememangnya Kami tidak sekali-kali ghaib (bahkan sentiasa Mendengar, Melihat dan Mengetahui akan hal ehwal mereka).', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 6, NULL),
(7, 8, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'والوزن يومئذ الحق فمن ثقلت موازينه فاولئك هم المفلحون', NULL, 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.', 'Dan timbangan amal pada hari itu adalah benar; maka sesiapa yang berat timbangan amalnya (yang baik), maka mereka itulah orang-orang yang berjaya.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 9, NULL),
(7, 9, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَظْلِمُونَ', 'ومن خفت موازينه فاولئك الذين خسروا انفسهم بما كانوا باياتنا يظلمون', NULL, 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.', 'Dan sesiapa yang ringan timbangan amalnya (yang baik), maka mereka itulah orang-orang yang merugikan dirinya sendiri, dengan sebab mereka berlaku zalim terhadap ayat-ayat Kami (dengan meletakkannya pada bukan tempatnya).', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 11, NULL),
(7, 10, 'وَلَقَدْ مَكَّنَّـٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ ۗ قَلِيلًا مَّا تَشْكُرُونَ', 'ولقد مكناكم في الارض وجعلنا لكم فيها معايش قليلا ما تشكرون', NULL, 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.', 'Dan sesungguhnya Kami telah menetapkan kamu (dan memberi kuasa) di bumi, dan Kami jadikan untuk kamu padanya (berbagai jalan) penghidupan (supaya kamu bersyukur, tetapi) amatlah sedikit kamu bersyukur.', FALSE, NULL, NULL, 151, 8, 61, 122, FALSE, 11, NULL),
(7, 11, 'وَلَقَدْ خَلَقْنَـٰكُمْ ثُمَّ صَوَّرْنَـٰكُمْ ثُمَّ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّـٰجِدِينَ', 'ولقد خلقناكم ثم صورناكم ثم قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس لم يكن من الساجدين', NULL, 'And We have certainly created you, [O mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.', 'Dan sesungguhnya Kami telah menciptakan kamu, lalu Kami membentuk rupa kamu, kemudian Kami berfirman kepada malaikat-malaikat: “Sujudlah kamu kepada Adam”, lalu mereka sujud melainkan Iblis, ia tidaklah termasuk dalam golongan yang sujud.', FALSE, NULL, NULL, 151, 8, 61, 123, FALSE, 16, NULL),
(7, 12, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'قال ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين', NULL, '[Allāh] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay [i.e., earth]."', 'Allah berfirman: “Apakah penghalangnya yang menyekatmu daripada sujud ketika Aku perintahmu?” Iblis menjawab: “Aku lebih baik daripada Adam, Engkau (wahai Tuhan) jadikan daku dari api sedang dia Engkau jadikan dari tanah.”', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 17, NULL),
(7, 13, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ', 'قال فاهبط منها فما يكون لك ان تتكبر فيها فاخرج انك من الصاغرين', NULL, '[Allāh] said, "Descend from it [i.e., Paradise], for it is not for you to be arrogant therein. So get out; indeed, you are of the debased."', 'Allah berfirman: “Turunlah engkau dari Syurga ini, kerana tidak patut engkau berlaku sombong di dalamnya; oleh sebab itu keluarlah, sesungguhnya engkau dari golongan yang hina”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 13, NULL),
(7, 14, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قال انظرني الى يوم يبعثون', NULL, '[Satan] said, "Reprieve me until the Day they are resurrected."', 'Iblis berkata: Berilah tempoh kepadaku hingga hari mereka dibangkitkan (hari kiamat)”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 5, NULL),
(7, 15, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قال انك من المنظرين', NULL, '[Allāh] said, "Indeed, you are of those reprieved."', 'Allah berfirman: “Sesungguhnya engkau dari golongan yang diberi tempoh (ke suatu masa yang tertentu)”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 4, NULL),
(7, 16, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 'قال فبما اغويتني لاقعدن لهم صراطك المستقيم', NULL, '[Satan] said, "Because You have put me in error, I will surely sit in wait for them [i.e., mankind] on Your straight path.', 'Iblis berkata: “Oleh kerana Engkau (wahai Tuhan) menyebabkan daku tersesat (maka) demi sesungguhnya aku akan mengambil tempat menghalangi mereka (dari menjalani) jalanMu yang lurus;', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 7, NULL),
(7, 17, 'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَـٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَـٰكِرِينَ', 'ثم لاتينهم من بين ايديهم ومن خلفهم وعن ايمانهم وعن شمائلهم ولا تجد اكثرهم شاكرين', NULL, 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."', '“Kemudian aku datangi mereka, dari hadapan mereka serta dari belakang mereka, dan dari kanan mereka serta dari kiri mereka; dan Engkau tidak akan dapati kebanyakan mereka bersyukur”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 15, NULL),
(7, 18, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', 'قال اخرج منها مذءوما مدحورا لمن تبعك منهم لاملان جهنم منكم اجمعين', NULL, '[Allāh] said, "Depart from it [i.e., Paradise], reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."', 'Allah berfirman: “Keluarlah engkau dari Syurga sebagai makhluk yang terhina serta terusir. Sesungguhnya sesiapa di antara mereka yang menurutmu, tetaplah aku akan memenuhi neraka jahanam dengan (golongan) kamu (yang derhaka) semuanya;', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 12, NULL),
(7, 19, 'وَيَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ', 'ويا ادم اسكن انت وزوجك الجنة فكلا من حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين', NULL, 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."', '“Dan wahai Adam! Tinggallah engkau dan isterimu di dalam Syurga serta makanlah dari makanannya sepuas-puasnya apa sahaja kamu berdua sukai, dan janganlah kamu hampiri pokok ini, (jika kamu menghampirinya) maka akan menjadilah kamu dari orang-orang yang zalim”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 16, NULL),
(7, 20, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَـٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَـٰلِدِينَ', 'فوسوس لهما الشيطان ليبدي لهما ما ووري عنهما من سواتهما وقال ما نهاكما ربكما عن هذه الشجرة الا ان تكونا ملكين او تكونا من الخالدين', NULL, 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."', 'Setelah itu maka Syaitan membisikkan (hasutan) kepada mereka berdua supaya (dapatlah) ia menampakkan kepada mereka akan aurat mereka yang (sekian lama) tertutup dari (pandangan) mereka, sambil ia berkata: “Tidaklah Tuhan kamu melarang kamu daripada (menghampiri) pokok ini, melainkan (kerana Ia tidak suka) kamu berdua menjadi malaikat atau menjadi dari orang-orang yang kekal (selama-lamanya di dalam Syurga)”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 25, NULL),
(7, 21, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', 'وَقَاسَمَهُمَا إِنِّي لَكُمَا لَمِنَ النَّاصِحِينَ', NULL, 'And he swore [by Allāh] to them, "Indeed, I am to you from among the sincere advisors."', 'Dan ia bersumpah kepada keduanya (dengan berkata): “Sesungguhnya aku adalah dari mereka yang memberi nasihat kepada kamu berdua”.', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 0, NULL),
(7, 22, 'فَدَلَّىٰهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ', 'فَدَلَّاهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا الشَّجَرَةَ بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ وَنَادَاهُمَا رَبُّهُمَا أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا الشَّجَرَةِ وَأَقُل لَّكُمَا إِنَّ الشَّيْطَانَ لَكُمَا عَدُوٌّ مُّبِينٌ', NULL, 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"', 'Dengan sebab itu dapatlah ia menjatuhkan mereka berdua (ke dalam larangan) dengan tipu dayanya. Setelah mereka memakan (buah) pohon itu, terdedahlah kepada mereka berdua aurat masing-masing, dan mereka mulailah menutupnya dengan daun-daun (dari) Syurga. Serta Tuhan mereka menyeru mereka: “Bukankah Aku telah melarang kamu berdua dari pokok itu, dan Aku katakan kepada kamu, bahawa Syaitan itu adalah musuh kamu yang nyata?”', FALSE, NULL, NULL, 152, 8, 61, 123, FALSE, 0, NULL),
(7, 23, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'قَالَا رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', NULL, 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."', 'Mereka berdua merayu: “Wahai Tuhan kami, kami telah menganiaya diri kami sendiri, dan kalau Engkau tidak mengampunkan kami dan memberi rahmat kepada kami, nescaya menjadilah kami dari orang-orang yang rugi”.', FALSE, NULL, NULL, 153, 8, 61, 123, FALSE, 0, NULL),
(7, 24, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'قَالَ اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ إِلَىٰ حِينٍ', NULL, '[Allāh] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment [i.e., provision] for a time."', 'Allah berfirman: “Turunlah kamu semuanya, dengan keadaan setengah kamu menjadi musuh bagi setengahnya yang lain, dan bagi kamu disediakan tempat kediaman di bumi, dan juga diberi kesenangan hingga ke suatu ketika (mati)”.', FALSE, NULL, NULL, 153, 8, 61, 123, FALSE, 0, NULL),
(7, 25, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', NULL, 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."', 'Allah berfirman lagi: “Di bumi itu kamu hidup dan situ juga kamu mati, dan daripadanya pula kamu akan dikeluarkan (dibangkitkan hidup semula pada hari kiamat)”.', FALSE, NULL, NULL, 153, 8, 61, 123, FALSE, 0, NULL),
(7, 26, 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'يَا بَنِي آدَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَارِي سَوْآتِكُمْ وَرِيشًا وَلِبَاسُ التَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ آيَاتِ اللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', NULL, 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allāh that perhaps they will remember.', 'Wahai anak-anak Adam! Sesungguhnya Kami telah menurunkan kepada kamu (bahan-bahan untuk) pakaian menutup aurat kamu, dan pakaian perhiasan; dan pakaian yang berupa taqwa itulah yang sebaik-baiknya. Yang demikian itu adalah dari tanda-tanda (limpah kurnia) Allah (dan rahmatNya kepada hamba-hambaNya) supaya mereka mengenangnya (dan bersyukur).', FALSE, NULL, NULL, 153, 8, 61, 124, FALSE, 0, NULL),
(7, 27, 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', 'يَا بَنِي آدَمَ لَا يَفْتِنَنَّكُمُ الشَّيْطَانُ كَمَا أَخْرَجَ أَبَوَيْكُم مِّنَ الْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْآتِهِمَا إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا الشَّيَاطِينَ أَوْلِيَاءَ لِلَّذِينَ لَا يُؤْمِنُونَ', NULL, 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.', 'Wahai anak-anak Adam! Janganlah kamu diperdayakan oleh Syaitan sebagaimana ia telah mengeluarkan kedua ibu bapa kamu dari Syurga, sambil ia menyebabkan terlucutnya pakaian mereka berdua untuk memperlihatkan kepada mereka: aurat mereka (yang sebelum itu tertutup). Sesungguhnya Syaitan dan kaumnya melihat kamu dengan keadaan yang kamu tidak dapat melihat mereka. Sesungguhnya Kami telah menjadikan Syaitan-syaitan itu teman rapat bagi orang-orang yang tidak beriman.', FALSE, NULL, NULL, 153, 8, 61, 124, FALSE, 0, NULL),
(7, 28, 'وَإِذَا فَعَلُوا۟ فَٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'وَإِذَا فَعَلُوا فَاحِشَةً قَالُوا وَجَدْنَا عَلَيْهَا آبَاءَنَا وَاللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'And when they commit an immorality, they say, "We found our fathers doing it, and Allāh has ordered us to do it." Say, "Indeed, Allāh does not order immorality. Do you say about Allāh that which you do not know?"', 'Dan (orang-orang yang tidak beriman itu) apabila mereka melakukan sesuatu perbuatan yang keji, mereka berkata: “Kami dapati datuk nenek kami mengerjakannya, dan Allah perintahkan kami mengerjakannya”. Katakanlah (wahai Muhammad): “Sesungguhnya Allah tidak sekali-kali menyuruh mengerjakan perbuatan yang keji. Patutkah kamu mengatakan terhadap Allah apa yang kamu tidak mengetahuinya?”', FALSE, NULL, NULL, 153, 8, 61, 124, FALSE, 0, NULL),
(7, 29, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ', 'قُلْ أَمَرَ رَبِّي بِالْقِسْطِ وَأَقِيمُوا وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ', NULL, 'Say, [O Muḥammad], "My Lord has ordered justice and that you direct yourselves [to the Qiblah] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -', 'Katakanlah: “Tuhanku menyuruh berlaku adil (pada segala perkara), dan (menyuruh supaya kamu) hadapkan muka (dan hati) kamu (kepada Allah) dengan betul pada tiap-tiap kali mengerjakan sembahyang, dan beribadatlah dengan mengikhlaskan amal ugama kamu kepadaNya semata-mata; (kerana) sebagaimana Ia telah menjadikan kamu pada mulanya, (demikian pula) kamu akan kembali (kepadaNya).', FALSE, NULL, NULL, 153, 8, 61, 124, FALSE, 0, NULL),
(7, 30, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ الضَّلَالَةُ إِنَّهُمُ اتَّخَذُوا الشَّيَاطِينَ أَوْلِيَاءَ مِن دُونِ اللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', NULL, 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they [i.e., the latter] had taken the devils as allies instead of Allāh while they thought that they were guided.', 'Sebahagian (dari umat manusia) diberi hidayah petunjuk oleh Allah (dengan diberi taufiq untuk beriman dan beramal soleh); dan sebahagian lagi (yang ingkar) berhaklah mereka ditimpa kesesatan (dengan pilihan mereka sendiri), kerana sesungguhnya mereka telah menjadikan Syaitan-syaitan itu pemimpin-pemimpin (yang ditaati) selain Allah. Serta mereka pula menyangka, bahawa mereka berada dalam petunjuk hidayah.', FALSE, NULL, NULL, 153, 8, 61, 124, FALSE, 0, NULL),
(7, 31, 'يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ', NULL, 'O children of Adam, take your adornment [i.e., wear your clothing] at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.', 'Wahai anak-anak Adam! Pakailah pakaian kamu yang indah berhias pada tiap-tiap kali kamu ke tempat ibadat (atau mengerjakan sembahyang), dan makanlah serta minumlah, dan jangan pula kamu melampau; sesungguhnya Allah tidak suka akan orang-orang yang melampaui batas.', FALSE, NULL, NULL, 154, 8, 62, 124, FALSE, 0, NULL),
(7, 32, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَٰمَةِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'قُلْ مَنْ حَرَّمَ زِينَةَ اللَّهِ الَّتِي أَخْرَجَ لِعِبَادِهِ وَالطَّيِّبَاتِ مِنَ الرِّزْقِ قُلْ هِيَ لِلَّذِينَ آمَنُوا فِي الْحَيَاةِ الدُّنْيَا خَالِصَةً يَوْمَ الْقِيَامَةِ كَذَٰلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ', NULL, 'Say, "Who has forbidden the adornment of [i.e., from] Allāh which He has produced for His servants and the good [lawful] things of provision?" Say, "They are for those who believed during the life of this world, exclusively [for them] on the Day of Resurrection." Thus do We detail the verses for a people who know.', 'Katakanlah (wahai Muhammad): “Siapakah yang (berani) mengharamkan perhiasan Allah yang telah dikeluarkanNya untuk hamba-hambaNya, dan demikian juga benda-benda yang baik lagi halal dari rezeki yang dikurniakanNya?” Katakanlah: “Semuanya itu ialah (nikmat-nikmat) untuk orang-orang yang beriman (dan juga yang tidak beriman) dalam kehidupan dunia; (nikmat-nikmat itu pula) hanya tertentu (bagi orang-orang yang beriman sahaja) pada hari kiamat”. Demikianlah Kami jelaskan ayat-ayat keterangan Kami satu persatu bagi orang-orang yang (mahu) mengetahui.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 33, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَن تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَن تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'Say, "My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allāh that for which He has not sent down authority, and that you say about Allāh that which you do not know."', 'Katakanlah: “Sesungguhnya Tuhanku hanya mengharamkan perbuatan-perbuatan yang keji, sama ada yang nyata atau yang tersembunyi; dan perbuatan dosa; dan perbuatan menceroboh dengan tidak ada alasan yang benar; dan (diharamkanNya) kamu mempersekutukan sesuatu dengan Allah sedang Allah tidak menurunkan sebarang bukti (yang membenarkannya); dan (diharamkanNya) kamu memperkatakan terhadap Allah sesuatu yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 34, 'وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', NULL, 'And for every nation is a [specified] term. So when their time has come, they will not remain behind an hour, nor will they precede [it].', 'Dan bagi tiap-tiap umat ada tempoh (yang telah ditetapkan); maka apabila datang tempohnya, tidak dapat mereka dikemudiankan walau sesaatpun, dan tidak dapat pula mereka didahulukan.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 35, 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'يَا بَنِي آدَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي فَمَنِ اتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'O children of Adam, if there come to you messengers from among you relating to you My verses [i.e., scriptures and laws], then whoever fears Allāh and reforms - there will be no fear concerning them, nor will they grieve.', 'Wahai anak-anak Adam! Jika datang kepada kamu Rasul-rasul dari kalangan kamu yang menceritakan kepada kamu ayat-ayat (perintah) Ku, maka sesiapa yang bertaqwa dan memperbaiki amalnya, tidak ada kebimbangan (dari berlakunya kejadian yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 36, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'But the ones who deny Our verses and are arrogant toward them - those are the companions of the Fire; they will abide therein eternally.', 'Dan orang-orang yang mendustakan ayat-ayat (perintah) Kami dan yang angkuh (merasa dirinya lebih) daripada mematuhinya, merekalah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 37, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآيَاتِهِ أُولَٰئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ الْكِتَابِ حَتَّىٰ إِذَا جَاءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوا أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ اللَّهِ قَالُوا ضَلُّوا عَنَّا وَشَهِدُوا عَلَىٰ أَنفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ', NULL, 'And who is more unjust than one who invents about Allāh a lie or denies His verses? Those will attain their portion of the decree until, when Our messengers [i.e., angels] come to them to take them in death, they will say, "Where are those you used to invoke besides Allāh?" They will say, "They have departed from us," and will bear witness against themselves that they were disbelievers.', 'Maka tidak ada yang lebih zalim daripada orang yang berdusta terhadap Allah atau yang mendustakan ayat-ayatNya. Orang-orang itu akan mendapat bahagian mereka (di dunia) dari apa yang telah tersurat (bagi mereka), hingga apabila datang kepada mereka utusan-utusan Kami (malaikat) yang mengambil nyawa mereka, bertanyalah malaikat itu (kepada mereka): “Manakah (makhluk-makhluk dan benda-benda) yang kamu sembah selain Allah?” Mereka menjawab: “Semuanya itu telah hilang lenyap daripada kami”, dan mereKa pula menjadi saksi terhadap diri mereka sendiri, bahawa mereka adalah orang-orang yang ingkar.', FALSE, NULL, NULL, 154, 8, 62, 125, FALSE, 0, NULL),
(7, 38, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ', 'قَالَ ادْخُلُوا فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ فِي النَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰ إِذَا ادَّارَكُوا فِيهَا جَمِيعًا قَالَتْ أُخْرَاهُمْ لِأُولَاهُمْ رَبَّنَا هَٰؤُلَاءِ أَضَلُّونَا فَآتِهِمْ عَذَابًا ضِعْفًا مِّنَ النَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ', NULL, '[Allāh] will say, "Enter among nations which had passed on before you of jinn and mankind into the Fire." Every time a nation enters, it will curse its sister until, when they have all overtaken one another therein, the last of them will say about the first of them, "Our Lord, these had misled us, so give them a double punishment of the Fire." He will say, "For each is double, but you do not know."', 'Allah berfirman: “Masuklah kamu ke dalam neraka bersama-sama umat-umat yang terdahulu daripada kamu, dari jin dan manusia. Tiap-tiap satu umat yang masuk, mengutuk akan saudaranya (golongannya sendiri); hingga apabila mereka semua berhimpun di dalamnya, berkatalah golongan yang akhir mengenai golongan yang pertama di antara mereka: “Wahai Tuhan kami, mereka inilah yang telah menyesatkan kami; oleh itu berilah kepada mereka azab seksa yang berlipat ganda dari (azab) neraka”. Allah berfirman: “Kamu masing-masing disediakan (azab seksa) yang berlipat ganda tetapi kamu tidak mengetahui”.', FALSE, NULL, NULL, 155, 8, 62, 125, FALSE, 0, NULL),
(7, 39, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', 'وَقَالَتْ أُولَاهُمْ لِأُخْرَاهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', NULL, 'And the first of them will say to the last of them, "Then you had not any favor over us, so taste the punishment for what you used to earn."', 'Dan berkatalah golongan pertama (ketua-ketua), di antara mereka, kepada golongan yang akhir (pengikut-pengikutnya): “(Jika demikianlah hukuman Tuhan), maka tidak ada bagi kamu sebarang kelebihan atas kami”. (Allah berfirman): “Oleh itu rasalah kamu azab seksa disebabkan apa yang kamu telah usahakan”.', FALSE, NULL, NULL, 155, 8, 62, 125, FALSE, 0, NULL),
(7, 40, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', 'إِنَّ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَاسْتَكْبَرُوا عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ وَلَا يَدْخُلُونَ الْجَنَّةَ حَتَّىٰ يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ وَكَذَٰلِكَ نَجْزِي الْمُجْرِمِينَ', NULL, 'Indeed, those who deny Our verses and are arrogant toward them - the gates of Heaven will not be opened for them, nor will they enter Paradise until a camel enters into the eye of a needle [i.e., never]. And thus do We recompense the criminals.', 'Sesungguhnya orang-orang yang mendustakan ayat-ayat (perintah) Kami dan yang angkuh (merasa dirinya lebih) daripada mematuhinya, tidak sekali-kali akan dibukakan bagi mereka pintu-pintu langit dan mereka tidak akan masuk Syurga sehingga unta masuk di lubang jarum dan demikianlah Kami membalas orang-orang yang melakukan kesalahan.', FALSE, NULL, NULL, 155, 8, 62, 126, FALSE, 0, NULL),
(7, 41, 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِي الظَّالِمِينَ', NULL, 'They will have from Hell a bed and over them coverings [of fire]. And thus do We recompense the wrongdoers.', 'Disediakan untuk mereka hamparan-hamparan dari api neraka, dan di atas mereka lapisan-lapisan penutup (dari api neraka) dan demikianlah Kami membalas orang-orang yang zalim (disebabkan keingkarannya).', FALSE, NULL, NULL, 155, 8, 62, 126, FALSE, 0, NULL),
(7, 42, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا أُولَٰئِكَ أَصْحَابُ الْجَنَّةِ هُمْ فِيهَا خَالِدُونَ', NULL, 'But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally.', 'Dan orang-orang yang beriman serta beramal soleh - (dengan tidak menjadi keberatan kepada mereka, kerana) Kami tidak memberati diri seseorang (dengan kewajipan) melainkan sekadar yang terdaya olehnya, - merekalah ahli Syurga, mereka kekal di dalamnya.', FALSE, NULL, NULL, 155, 8, 62, 126, FALSE, 0, NULL),
(7, 43, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'وَنَزَعْنَا مَا فِي صُدُورِهِم مِّنْ غِلٍّ تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ لَقَدْ جَاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ وَنُودُوا أَن تِلْكُمُ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'And We will have removed whatever is within their breasts of resentment, [while] flowing beneath them are rivers. And they will say, "Praise to Allāh, who has guided us to this; and we would never have been guided if Allāh had not guided us. Certainly the messengers of our Lord had come with the truth." And they will be called, "This is Paradise, which you have been made to inherit for what you used to do."', 'Dan Kami cabutkan segala dendam dan hasad dengki dari hati mereka, (di dalam Syurga) yang mengalir beberapa sungai di bawah (tempat) masing-masing, dan mereka pula bersyukur dengan berkata: “Segala puji tertentu bagi Allah yang telah memberi hidayah petunjuk untuk (mendapat nikmat-nikmat) ini, padahal Kami tidak sekali-kali akan memperoleh petunjuk kalau Allah tidak memimpin kami (dengan taufiqNya); sesungguhnya telah datang Rasul-rasul Tuhan kami dengan membawa kebenaran”. Dan mereka diseru: “Itulah Syurga yang diberikan kamu mewarisinya dengan sebab apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 155, 8, 62, 126, FALSE, 0, NULL),
(7, 44, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا۟ نَعَمْ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 'وَنَادَىٰ أَصْحَابُ الْجَنَّةِ أَصْحَابَ النَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا نَعَمْ فَأَذَّنَ مُؤَذِّنٌ بَيْنَهُمْ أَن لَّعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ', NULL, 'And the companions of Paradise will call out to the companions of the Fire, "We have already found what our Lord promised us to be true. Have you found what your Lord promised to be true?" They will say, "Yes." Then an announcer will announce among them, "The curse of Allāh shall be upon the wrongdoers', 'Dan (apabila ahli-ahli Syurga itu berada di tempat masing-masing), berserulah mereka kepada ahli neraka dengan berkata: “Sesungguhnya kami telah dapati apa yang telah dijanjikan kepada kami oleh Tuhan kami, semuanya betul. Maka adakah kamu juga telah dapati apa yang telah dijanjikan oleh Tuhan kamu itu semuanya betul?”. Mereka menjawab: “Benar ada”. Kemudian berserulah penyeru (malaikat) di antara mereka (kedua-dua puak itu) menyatakan: “Bahawa laknat Allah tertimpa ke atas orang-orang yang zalim”.', FALSE, NULL, NULL, 156, 8, 62, 126, FALSE, 0, NULL),
(7, 45, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَٰفِرُونَ', 'الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ كَافِرُونَ', NULL, 'Who averted [people] from the way of Allāh and sought to make it [seem] deviant while they were, concerning the Hereafter, disbelievers."', 'Iaitu mereka yang menghalang (dirinya sendiri dan juga orang lain) dari menurut jalan Allah, dan mencari helah menjadikan jalan itu bengkok terpesong, sedang mereka pula tidak percayakan hari akhirat.', FALSE, NULL, NULL, 156, 8, 62, 126, FALSE, 0, NULL),
(7, 46, 'وَبَيْنَهُمَا حِجَابٌ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', 'وَبَيْنَهُمَا حِجَابٌ وَعَلَى الْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّا بِسِيمَاهُمْ وَنَادَوْا أَصْحَابَ الْجَنَّةِ أَن سَلَامٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', NULL, 'And between them will be a partition [i.e., wall], and on [its] elevations are men who recognize all by their mark. And they call out to the companions of Paradise, "Peace be upon you." They have not [yet] entered it, but they long intensely.', 'Dan di antara keduanya (Syurga dan neraka) ada tembok “Al-A''raaf “(yang menjadi) pendinding, dan di atas tembok Al-A''raaf itu ada sebilangan orang-orang lelaki yang mengenal tiap-tiap seorang (dari ahli-ahli Syurga dan neraka) itu, dengan tanda masing-masing. Dan mereka pun menyeru ahli Syurga (dengan memberi salam, katanya): “Salaamun Alaikum” (salam sejahtera kepada kamu). Sedang mereka, sendiri belum lagi masuk Syurga, padahal mereka ingin sangat memasukinya.', FALSE, NULL, NULL, 156, 8, 62, 126, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(7, 47, 'وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وَإِذَا صُرِفَتْ أَبْصَارُهُمْ تِلْقَاءَ أَصْحَابِ النَّارِ قَالُوا رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ', NULL, 'And when their eyes are turned toward the companions of the Fire, they say, "Our Lord, do not place us with the wrongdoing people."', 'Dan apabila dialihkan pandangan mereka ke arah ahli neraka, mereka (berdoa dengan) berkata: “Wahai Tuhan kami! Janganlah Engkau jadikan kami bersama orang-orang yang zalim”.', FALSE, NULL, NULL, 156, 8, 63, 126, FALSE, 0, NULL),
(7, 48, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 'وَنَادَىٰ أَصْحَابُ الْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَاهُمْ قَالُوا مَا أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', NULL, 'And the companions of the Elevations will call to men [within Hell] whom they recognize by their mark, saying, "Of no avail to you was your gathering and [the fact] that you were arrogant."', 'Dan orang-orang yang berada di atas tembok Al-A''raaf menyeru beberapa orang (Ketua kaum kafir) yang mereka kenal dengan tandanya, dengan berkata: “Nampaknya kumpulan kamu yang ramai (atau kekayaan kamu yang besar) dan juga segala apa yang kamu sombongkan dahulu - tidak dapat menolong kamu”.', FALSE, NULL, NULL, 156, 8, 63, 127, FALSE, 0, NULL),
(7, 49, 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 'أَهَٰؤُلَاءِ الَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ اللَّهُ بِرَحْمَةٍ ادْخُلُوا الْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَا أَنتُمْ تَحْزَنُونَ', NULL, '[Allāh will say], "Are these the ones whom you [inhabitants of Hell] swore that Allāh would never offer them mercy? Enter Paradise, [O people of the Elevations]. No fear will there be concerning you, nor will you grieve."', '(Mereka bertanya pula kepada Ketua-ketua kaum kafir itu dengan berkata): “Itukah orang-orang yang kamu ejek-ejek dahulu dan kamu bersumpah bahawa mereka tidak akan beroleh rahmat dari Allah? (Sekarang dikatakan kepada mereka): ‘Masuklah kamu ke dalam Syurga, tidak ada kebimbangan (dari berlakunya sesuatu yang tidak baik) terhadap kamu, dan kamu pula tidak akan berdukacita.’”', FALSE, NULL, NULL, 156, 8, 63, 127, FALSE, 0, NULL),
(7, 50, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', 'وَنَادَىٰ أَصْحَابُ النَّارِ أَصْحَابَ الْجَنَّةِ أَنْ أَفِيضُوا عَلَيْنَا مِنَ الْمَاءِ أَوْ مِمَّا رَزَقَكُمُ اللَّهُ قَالُوا إِنَّ اللَّهَ حَرَّمَهُمَا عَلَى الْكَافِرِينَ', NULL, 'And the companions of the Fire will call to the companions of Paradise, "Pour upon us some water or from whatever Allāh has provided you." They will say, "Indeed, Allāh has forbidden them both to the disbelievers', 'Dan (Tuhan menerangkan pula kehinaan ahli neraka dengan firmannya): ahli neraka menyeru ahli Syurga (dengan berkata): “Limpahkanlah kepada kami sedikit dari air atau dari rezeki (makanan) yang telah dikurniakan Allah kepada kamu”. Mereka (ahli Syurga) menjawab: “Sesungguhnya Allah telah haramkan kedua-duanya atas orang-orang kafir”.', FALSE, NULL, NULL, 156, 8, 63, 127, FALSE, 0, NULL),
(7, 51, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'الَّذِينَ اتَّخَذُوا دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا فَالْيَوْمَ نَنسَاهُمْ كَمَا نَسُوا لِقَاءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا بِآيَاتِنَا يَجْحَدُونَ', NULL, 'Who took their religion as distraction and amusement and whom the worldly life deluded." So today We will forget them just as they forgot the meeting of this Day of theirs and for having rejected Our verses.', '(Tuhan berfirman: Orang-orang kafir itu ialah) orang-orang yang menjadikan perkara-perkara ugama mereka sebagai hiburan yang melalaikan dan permainan, dan orang-orang yang telah terpedaya dengan kehidupan dunia (segala kemewahannya dan kelazatannya). Oleh itu, pada hari ini (hari kiamat), Kami lupakan (tidak hiraukan) mereka sebagaimana mereka telah lupa (tidak hiraukan persiapan-persipan untuk) menemui hari mereka ini, dan juga kerana mereka selalu mengingkari ayat-ayat keterangan Kami.', FALSE, NULL, NULL, 156, 8, 63, 127, FALSE, 0, NULL),
(7, 52, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'وَلَقَدْ جِئْنَاهُم بِكِتَابٍ فَصَّلْنَاهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe.', 'Dan sesungguhnya Kami telah datangkan kepada mereka, sebuah Kitab (Al-Quran) yang Kami telah menjelaskannya satu persatu berdasarkan pengetahuan (Kami yang meliputi segala-galanya), untuk menjadi hidayah petunjuk dan rahmat, bagi orang-orang yang (mahu) beriman.', FALSE, NULL, NULL, 157, 8, 63, 127, FALSE, 0, NULL),
(7, 53, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُ يَوْمَ يَأْتِي تَأْوِيلُهُ يَقُولُ الَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ فَهَل لَّنَا مِن شُفَعَاءَ فَيَشْفَعُوا لَنَا أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذِي كُنَّا نَعْمَلُ قَدْ خَسِرُوا أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'Do they await except its result? The Day its result comes, those who had ignored it before will say, "The messengers of our Lord had come with the truth, so are there [now] any intercessors to intercede for us or could we be sent back to do other than what we used to do?" They will have lost themselves, and lost from them is what they used to invent.', 'Tidak ada perkara yang mereka tunggu-tunggukan melainkan akibat atau kesudahan (apa yang telah dijanjikan oleh Allah di dalam Al-Quran), pada hari datangnya apa yang telah dijanjikan dalam Al-Quran itu (pada hari kiamat kelak), berkatalah orang-orang yang telah melupakannya (yang tidak menghiraukannya dalam dunia) dahulu: “Sesungguhnya telah datang Rasul-rasul Tuhan kami dengan membawa kebenaran, maka adakah untuk kami pemberi syafaat supaya mereka memberi syafaat bagi kami atau (bolehkah) kami dikembalikan (ke dunia) supaya kami dapat beramal, lain daripada apa yang kami telah kerjakan?” Sesungguhnya mereka telah merugikan diri mereka sendiri, dan telah lenyaplah dari mereka perkara-perkara yang mereka ada-adakan dahulu.', FALSE, NULL, NULL, 157, 8, 63, 127, FALSE, 0, NULL),
(7, 54, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ', NULL, 'Indeed, your Lord is Allāh, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allāh, Lord of the worlds.', 'Sesungguhnya Tuhan kamu ialah Allah yang menciptakan langit dan bumi dalam enam masa lalu Ia bersemayam di atas Arasy; Ia melindungi malam dengan siang yang mengiringinya dengan deras (silih berganti) dan (Ia pula yang menciptakan) matahari dan bulan serta bintang-bintang, (semuanya) tunduk kepada perintahNya. Ingatlah, kepada Allah jualah tertentu urusan menciptakan (sekalian makhluk) dan urusan pemerintahan. Maha Suci Allah yang mencipta dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 157, 8, 63, 128, FALSE, 0, NULL),
(7, 55, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ', NULL, 'Call upon your Lord in humility and privately; indeed, He does not like transgressors.', 'Berdoalah kepada Tuhan kamu dengan merendah diri dan (dengan suara) perlahan-lahan. Sesungguhnya Allah tidak suka kepada orang-orang yang melampaui batas.', FALSE, NULL, NULL, 157, 8, 63, 128, FALSE, 0, NULL),
(7, 56, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ', 'وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ', NULL, 'And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allāh is near to the doers of good.', 'Dan janganlah kamu berbuat kerosakan di bumi sesudah Allah menyediakan segala yang membawa kebaikan padanya, dan berdoalah kepadaNya dengan perasaan bimbang (kalau-kalau tidak diterima) dan juga dengan perasaan terlalu mengharapkan (supaya makbul). Sesungguhnya rahmat Allah itu dekat kepada orang-orang yang memperbaiki amalannya.', FALSE, NULL, NULL, 157, 8, 63, 128, FALSE, 0, NULL),
(7, 57, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', 'وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ حَتَّىٰ إِذَا أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَاهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ الْمَاءَ فَأَخْرَجْنَا بِهِ مِن كُلِّ الثَّمَرَاتِ كَذَٰلِكَ نُخْرِجُ الْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', NULL, 'And it is He who sends the winds as good tidings before His mercy [i.e., rainfall] until, when they have carried heavy rainclouds, We drive them to a dead land and We send down rain therein and bring forth thereby [some] of all the fruits. Thus will We bring forth the dead; perhaps you may be reminded.', 'Dan Dia lah (Allah) yang menghantarkan angin sebagai pembawa berita yang mengembirakan sebelum kedatangan rahmatnya (iaitu hujan), hingga apabila angin itu membawa awan mendung, Kami halakan dia ke negeri yang mati (ke daerah yang kering kontang), lalu Kami turunkan hujan dengan awan itu, kemudian Kami keluarkan dengan air hujan itu berbagai-bagai jenis buah-buahan. Demikianlah pula Kami mengeluarkan (menghidupkan semula) orang-orang yang telah mati, supaya kamu beringat (mengambil pelajaran daripadanya).', FALSE, NULL, NULL, 157, 8, 63, 128, FALSE, 0, NULL),
(7, 58, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَشْكُرُونَ', 'وَالْبَلَدُ الطَّيِّبُ يَخْرُجُ نَبَاتُهُ بِإِذْنِ رَبِّهِ وَالَّذِي خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ الْآيَاتِ لِقَوْمٍ يَشْكُرُونَ', NULL, 'And the good land - its vegetation emerges by permission of its Lord; but that which is bad - nothing emerges except sparsely, with difficulty. Thus do We diversify the signs for a people who are grateful.', 'Dan negeri yang baik (tanahnya), tanaman-tanamannya tumbuh (subur) dengan izin Allah; dan negeri yang tidak baik (tanahnya) tidak tumbuh tanamannya melainkan dengan keadaan bantut. Demikianlah Kami menerangkan tanda-tanda (kemurahan dan kekuasaan) Kami dengan berbagai cara bagi orang-orang yang (mahu) bersyukur.', FALSE, NULL, NULL, 158, 8, 63, 128, FALSE, 0, NULL),
(7, 59, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَقَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', NULL, 'We had certainly sent Noah to his people, and he said, "O my people, worship Allāh; you have no deity other than Him. Indeed, I fear for you the punishment of a tremendous Day."', 'Sesungguhnya Kami telah mengutuskan Nabi Nuh kepada kaumnya, lalu berkatalah ia: “Wahai kaumku! Sembahlah kamu akan Allah, (sebenarnya) tidak ada Tuhan bagi kamu selain daripadaNya. Sesungguhnya aku bimbang, kamu akan ditimpa azab hari yang besar (hari kiamat)”', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 60, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍ مُّبِينٍ', 'قَالَ الْمَلَأُ مِن قَوْمِهِ إِنَّا لَنَرَاكَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'Said the eminent among his people, "Indeed, we see you in clear error."', 'Ketua-ketua dari kaumnya berkata: “Sesungguhnya kami nampakmu (wahai Nuh) berada dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 61, 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'قَالَ يَا قَوْمِ لَيْسَ بِي ضَلَالَةٌ وَلَٰكِنِّي رَسُولٌ مِّن رَّبِّ الْعَالَمِينَ', NULL, '[Noah] said, "O my people, there is not error in me, but I am a messenger from the Lord of the worlds.', 'Nabi Nuh menjawab: “Wahai KaumKu! Tidak ada padaku sebarang kesesatan, tetapi aku adalah seorang Rasul dari Tuhan sekalian alam.', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 62, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'أُبَلِّغُكُمْ رِسَالَاتِ رَبِّي وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'I convey to you the messages of my Lord and advise you; and I know from Allāh what you do not know.', '“(Tugasku) menyampaikan kepada kamu perintah-perintah yang (diutuskan oleh) Tuhanku, serta aku memberi nasihat kepada kamu, sedang aku mengetahui (melalui wahyu) dari Allah akan apa yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 63, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 'أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا وَلَعَلَّكُمْ تُرْحَمُونَ', NULL, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you and that you may fear Allāh so you might receive mercy?"', '“Adakah kamu merasa ragu-ragu dan hairan tentang datangnya kepada kamu nasihat pengajaran dari Tuhan kamu melalui seorang lelaki dari golongan kamu, untuk memberi peringatan kepada kamu, dan supaya kamu bertaqwa dan juga supaya kamu beroleh rahmat?”.', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 64, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', 'فَكَذَّبُوهُ فَأَنجَيْنَاهُ وَالَّذِينَ مَعَهُ فِي الْفُلْكِ وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآيَاتِنَا إِنَّهُمْ كَانُوا قَوْمًا عَمِينَ', NULL, 'But they denied him, so We saved him and those who were with him in the ship. And We drowned those who denied Our signs. Indeed, they were a blind people.', 'Mereka terus mendustakannya, lalu Kami selamatkan dia dan orang-orang yang bersamanya di dalam bahtera, dan Kami karamkan orang-orang yang mendustakan ayat-ayat kami. Sesungguhnya mereka adalah kaum yang buta (matahatinya daripada melihat kebenaran)', FALSE, NULL, NULL, 158, 8, 63, 129, FALSE, 0, NULL),
(7, 65, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ', NULL, 'And to the ʿAad [We sent] their brother Hūd. He said, "O my people, worship Allāh; you have no deity other than Him. Then will you not fear Him?"', 'Dan kepada kaum Aad, (Kami utuskan) saudara mereka: Nabi Hud. Ia berkata: “Wahai kaumku! Sembahlah kamu akan Allah, (sebenarnya) tidak ada Tuhan bagi kamu selain daripadaNya. Oleh itu, tidakkah kamu mahu bertaqwa kepadaNya?”', FALSE, NULL, NULL, 158, 8, 64, 130, FALSE, 0, NULL),
(7, 66, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', 'قَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ إِنَّا لَنَرَاكَ فِي سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ الْكَاذِبِينَ', NULL, 'Said the eminent ones who disbelieved among his people, "Indeed, we see you in foolishness, and indeed, we think you are of the liars."', 'Ketua-ketua yang kafir dari kaumnya berkata: “Sesungguhnya kami (wahai Hud) nampakmu berada dalam kebodohan, dan sesungguhnya kami fikir engkau adalah dari orang-orang yang berdusta”.', FALSE, NULL, NULL, 158, 8, 64, 130, FALSE, 0, NULL),
(7, 67, 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'قَالَ يَا قَوْمِ لَيْسَ بِي سَفَاهَةٌ وَلَٰكِنِّي رَسُولٌ مِّن رَّبِّ الْعَالَمِينَ', NULL, '[Hūd] said, "O my people, there is not foolishness in me, but I am a messenger from the Lord of the worlds.', 'Nabi Hud menjawab: “Wahai kaumku! Tidak ada padaku sebarang kebodohan, tetapi aku adalah seorang Rasul dari Tuhan sekalian alam.', FALSE, NULL, NULL, 158, 8, 64, 130, FALSE, 0, NULL),
(7, 68, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', 'أُبَلِّغُكُمْ رِسَالَاتِ رَبِّي وَأَنَا لَكُمْ نَاصِحٌ أَمِينٌ', NULL, 'I convey to you the messages of my Lord, and I am to you a trustworthy adviser.', '“(Tugasku) menyampaikan kepada kamu akan perintah-perintah (yang diutuskan oleh) Tuhanku, dan aku adalah pemberi nasihat yang amanah, bagi kamu.', FALSE, NULL, NULL, 159, 8, 64, 130, FALSE, 0, NULL),
(7, 69, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 'أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفَاءَ مِن بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِي الْخَلْقِ بَسْطَةً فَاذْكُرُوا آلَاءَ اللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you? And remember when He made you successors after the people of Noah and increased you in stature extensively. So remember the favors of Allāh that you might succeed."', '“Adakah kamu merasa ragu-ragu dan hairan tentang datangnya kepada kamu nasihat pengajaran dari Tuhan kamu, melalui seorang lelaki dari golongan kamu, untuk memberi peringatan kepada kamu? Dan kenanglah ketika Allah menjadikan kamu khalifah-khalifah sesudah kaum Nabi Nuh, dan Allah telah menambahkan kamu kelebihan (dan kekuatan) pada bentuk kejadian tubuh kamu. Maka kenanglah akan nikmat-nikmat Allah supaya kamu berjaya”.', FALSE, NULL, NULL, 159, 8, 64, 130, FALSE, 0, NULL),
(7, 70, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قَالُوا أَجِئْتَنَا لِنَعْبُدَ اللَّهَ وَحْدَهُ وَنَذَرَ مَا كَانَ يَعْبُدُ آبَاؤُنَا فَأْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'They said, "Have you come to us that we should worship Allāh alone and leave what our fathers have worshipped? Then bring us what you promise us, if you should be of the truthful."', 'Mereka berkata: “Adakah engkau datang kepada kami supaya kami hanya menyembah Allah semata-mata, dan meninggalkan apa yang pernah disembah oleh datuk nenek kami? (Kami tidak akan menurut) maka datangkanlah azab yang engkau janjikan kepada kami, jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 159, 8, 64, 130, FALSE, 0, NULL),
(7, 71, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَادِلُونَنِي فِي أَسْمَاءٍ سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا نَزَّلَ اللَّهُ بِهَا مِن سُلْطَانٍ فَانتَظِرُوا إِنِّي مَعَكُم مِّنَ الْمُنتَظِرِينَ', NULL, '[Hūd] said, "Already have defilement and anger fallen upon you from your Lord. Do you dispute with me concerning [mere] names you have named them, you and your fathers, for which Allāh has not sent down any authority? Then wait; indeed, I am with you among those who wait."', 'Nabi Hud menjawab: “Sesungguhnya telah tetaplah kamu akan ditimpa azab dan kemurkaan dari Tuhan kamu. Adakah kamu hendak berbahas denganku mengenai nama-nama yang hanya kamu dan nenek moyang kamu menamakannya, sedang Allah tidak sekali-kali menurunkan sebarang bukti yang membenarkannya? Maka tunggulah (kedatangan azab itu), sesungguhnya aku juga dari orang-orang yang turut menunggu bersama-sama kamu”.', FALSE, NULL, NULL, 159, 8, 64, 130, FALSE, 0, NULL),
(7, 72, 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَمَا كَانُوا۟ مُؤْمِنِينَ', 'فَأَنجَيْنَاهُ وَالَّذِينَ مَعَهُ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَمَا كَانُوا مُؤْمِنِينَ', NULL, 'So We saved him and those with him by mercy from Us. And We eliminated those who denied Our signs, and they were not [at all] believers.', 'Maka Kami selamatkan dia dan orang-orang yang bersamanya, dengan rahmat dari Kami, dan Kami (binasakan serta) putuskan keturunan orang-orang yang mendustakan ayat-ayat Kami, dan mereka bukanlah orang-orang yang beriman.', FALSE, NULL, NULL, 159, 8, 64, 130, FALSE, 0, NULL),
(7, 73, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ قَدْ جَاءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِ نَاقَةُ اللَّهِ لَكُمْ آيَةً فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', NULL, 'And to the Thamūd [We sent] their brother Ṣāliḥ. He said, "O my people, worship Allāh; you have no deity other than Him. There has come to you clear evidence from your Lord. This is the she-camel of Allāh [sent] to you as a sign. So leave her to eat within Allāh''s land and do not touch her with harm, lest there seize you a painful punishment.', 'Dan kepada kaum Thamud (Kami utuskan) saudara mereka: Nabi Soleh. Ia berkata: “Wahai kaumku! Sembahlah kamu akan Allah, (sebenarnya) tiada Tuhan bagi kamu selain daripadaNya. Sesungguhnya telah datang kepada kamu keterangan yang nyata (mukjizat) dari Tuhan kamu; ini adalah seekor unta betina (dari) Allah sebagai keterangan bagi kamu (membuktikan kebenaranku). Oleh itu, biarkanlah unta itu mencari makan di bumi Allah, dan janganlah kamu menyentuhnya dengan sesuatu yang menyakitinya; (kalau kamu menyentuhnya) maka kamu akan ditimpa azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 159, 8, 64, 131, FALSE, 0, NULL),
(7, 74, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفَاءَ مِن بَعْدِ عَادٍ وَبَوَّأَكُمْ فِي الْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ الْجِبَالَ بُيُوتًا فَاذْكُرُوا آلَاءَ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ', NULL, 'And remember when He made you successors after the ʿAad and settled you in the land, [and] you take for yourselves palaces from its plains and carve from the mountains, homes. Then remember the favors of Allāh and do not commit abuse on the earth, spreading corruption."', '“Dan kenanglah ketika Allah menjadikan kamu khalifah-khalifah sesudah kaum Aad, dan di tempatkannya kamu di bumi, (dengan diberi kemudahan) untuk kamu mendirikan istana-istana di tanahnya yang rata, dan kamu memahat gunung-ganangnya untuk dijadikan rumah. Maka kenangkanlah nikmat-nikmat Allah itu dan janganlah kamu bermaharajalela melakukan kerosakan di muka bumi”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 75, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 'قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِن قَوْمِهِ لِلَّذِينَ اسْتُضْعِفُوا لِمَنْ آمَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَالِحًا مُّرْسَلٌ مِّن رَّبِّهِ قَالُوا إِنَّا بِمَا أُرْسِلَ بِهِ مُؤْمِنُونَ', NULL, 'Said the eminent ones who were arrogant among his people to those who were oppressed - to those who believed among them, "Do you [actually] know that Ṣāliḥ is sent from his Lord?" They said, "Indeed we, in that with which he was sent, are believers."', 'Ketua-ketua yang sombong takbur dari kaumnya berkata kepada orang-orang yang dipandang lemah iaitu orang-orang yang telah beriman di antara mereka: “Tahukah kamu bahawa Soleh itu diutus dari Tuhannya?” Mereka menjawab: “Sesungguhnya kami beriman kepada apa yang ia diutus untuk menyampaikannya”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 76, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'قَالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا بِالَّذِي آمَنتُم بِهِ كَافِرُونَ', NULL, 'Said those who were arrogant, "Indeed we, in that which you have believed, are disbelievers."', 'Orang-orang yang sombong takbur itu berkata: “Sesungguhnya kami tetap ingkar akan orang yang kamu beriman kepadanya”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 77, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', 'فَعَقَرُوا النَّاقَةَ وَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا يَا صَالِحُ ائْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الْمُرْسَلِينَ', NULL, 'So they hamstrung the she-camel and were insolent toward the command of their Lord and said, "O Ṣāliḥ, bring us what you promise us, if you should be of the messengers."', 'Maka mereka pun menyembelih unta itu, dan mereka menderhaka terhadap perintah Tuhan mereka, sambil berkata: “Hai Soleh! Datangkanlah azab yang engkau telah janjikan kepada kami, jika betul engkau dari Rasul-rasul yang diutus (oleh Allah)”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 78, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ', NULL, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.', 'Oleh itu, mereka pun dibinasakan oleh gempa bumi, lalu menjadilah mereka mayat-mayat yang tersungkur di tempat tinggal masing-masing.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 79, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ النَّاصِحِينَ', NULL, 'And he [i.e., Ṣāliḥ] turned away from them and said, "O my people, I had certainly conveyed to you the message of my Lord and advised you, but you do not like advisors."', 'Maka Nabi Soleh pun meninggalkan mereka sambil berkata: “Wahai kaumku! Aku telah menyampaikan kepada kamu perutusan Tuhanku, dan aku telah memberi nasihat kepada kamu, tetapi kamu tidak suka kepada orang-orang yang memberi nasihat”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 80, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِ أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ', NULL, 'And [We had sent] Lot when he said to his people, "Do you commit such immorality as no one has preceded you with from among the worlds [i.e., peoples]?', 'Dan Nabi Lut juga (Kami utuskan). Ingatlah ketika ia berkata kepada kaumnya: “Patutkah kamu melakukan perbuatan yang keji, yang tidak pernah dilakukan oleh seorang pun dari penduduk alam ini sebelum kamu?', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 81, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', 'إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', NULL, 'Indeed, you approach men with desire, instead of women. Rather, you are a transgressing people."', '“Sesungguhnya kamu mendatangi lelaki untuk memuaskan nafsu syahwat kamu dengan meninggalkan perempuan, bahkan kamu ini adalah kaum yang melampaui batas”.', FALSE, NULL, NULL, 160, 8, 64, 131, FALSE, 0, NULL),
(7, 82, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', NULL, 'But the answer of his people was only that they said, "Evict them from your city! Indeed, they are men who keep themselves pure."', 'Dan tidak ada jawab dari kaumnya selain daripada berkata: “Usirlah mereka (Nabi Lut dan pengikut-pengikutnya yang taat) dari bandar kamu ini, sesungguhnya mereka adalah orang-orang yang (mendakwa) mensucikan diri”.', FALSE, NULL, NULL, 161, 8, 64, 131, FALSE, 0, NULL),
(7, 83, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'فَأَنجَيْنَاهُ وَأَهْلَهُ إِلَّا امْرَأَتَهُ كَانَتْ مِنَ الْغَابِرِينَ', NULL, 'So We saved him and his family, except for his wife; she was of those who remained [with the evildoers].', 'Maka Kami selamatkan dia dan keluarganya (serta pengikut-pengikutnya) melainkan isterinya, adalah ia dari orang-orang yang dibinasakan.', FALSE, NULL, NULL, 161, 8, 64, 131, FALSE, 0, NULL),
(7, 84, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِمِينَ', NULL, 'And We rained upon them a rain [of stones]. Then see how was the end of the criminals.', 'Dan Kami telah menghujani mereka dengan hujan (batu yang membinasakan). Oleh itu, lihatlah, bagaimana akibat orang-orang yang melakukan kesalahan.', FALSE, NULL, NULL, 161, 8, 64, 131, FALSE, 0, NULL),
(7, 85, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ قَدْ جَاءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', NULL, 'And to [the people of] Madyan [We sent] their brother Shuʿayb. He said, "O my people, worship Allāh; you have no deity other than Him. There has come to you clear evidence from your Lord. So fulfill the measure and weight and do not deprive people of their due and cause not corruption upon the earth after its reformation. That is better for you, if you should be believers.', 'Dan kepada penduduk Madyan (Kami utuskan) saudara mereka Nabi Syuaib. Ia berkata: “Wahai kaum sembahlah kamu akan Allah, (sebenarnya) tiada Tuhan bagi kamu selain daripadaNya. Sesungguhnya telah datang kepada kamu keterangan yang nyata dari Tuhan kamu. Oleh itu, sempurnakanlah sukatan dan timbangan, dan janganlah kamu kurangkan bagi manusia akan benda-benda dan perkara-perkara yang menjadi haknya; dan janganlah kamu berbuat kerosakan di muka bumi sesudah Allah menjadikannya (makmur teratur) dengan sebaik-baiknya. Yang demikian itu lebih baik bagi kamu jika betul kamu orang-orang yang beriman.', FALSE, NULL, NULL, 161, 8, 64, 132, FALSE, 0, NULL),
(7, 86, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'وَلَا تَقْعُدُوا بِكُلِّ صِرَاطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ اللَّهِ مَنْ آمَنَ بِهِ وَتَبْغُونَهَا عِوَجًا وَاذْكُرُوا إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِدِينَ', NULL, 'And do not sit on every path, threatening and averting from the way of Allāh those who believe in Him, seeking to make it [seem] deviant. And remember when you were few and He increased you. And see how was the end of the corrupters.', '“Dan janganlah kamu duduk pada tiap-tiap jalan lalu-lalang, dengan menakut-nakutkan dan menghalangi orang-orang yang beriman dari melalui jalan Allah, dan kamu pula menghendaki supaya jalan Allah itu bengkok terpesong. Dan ingatlah semasa kamu dahulu sedikit bilangannya lalu Allah menjadikan kamu kembang ramai, serta perhatikanlah bagaimana akibat orang-orang yang berbuat kerosakan.', FALSE, NULL, NULL, 161, 8, 64, 132, FALSE, 0, NULL),
(7, 87, 'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'وَإِن كَانَ طَائِفَةٌ مِّنكُمْ آمَنُوا بِالَّذِي أُرْسِلْتُ بِهِ وَطَائِفَةٌ لَّمْ يُؤْمِنُوا فَاصْبِرُوا حَتَّىٰ يَحْكُمَ اللَّهُ بَيْنَنَا وَهُوَ خَيْرُ الْحَاكِمِينَ', NULL, 'And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allāh judges between us. And He is the best of judges."', '“Dan jika ada segolongan dari kamu beriman kepada wahyu (perintah-perintah Allah) yang aku telah diutuskan untuk menyampaikannya, dan segolongan lagi tidak beriman, maka sabarlah sehingga Allah menjalankan hukumNya di antara kita semua, dan Dia lah jua sebaik-baik hakim”.', FALSE, NULL, NULL, 161, 8, 64, 132, FALSE, 0, NULL),
(7, 88, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 'قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِن قَوْمِهِ لَنُخْرِجَنَّكَ يَا شُعَيْبُ وَالَّذِينَ آمَنُوا مَعَكَ مِن قَرْيَتِنَا أَوْ لَتَعُودُنَّ فِي مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَارِهِينَ', NULL, 'Said the eminent ones who were arrogant among his people, "We will surely evict you, O Shuʿayb, and those who have believed with you from our city, or you must return to our religion." He said, "Even if we were unwilling?', 'Ketua-ketua yang sombong takbur dari kaum Nabi Syuaib berkata: “Sesungguhnya kami akan mengusirmu wahai Syuaib dan orang-orang yang beriman yang menjadi pengikut-pengikutmu dari negeri kami ini, atau kamu berpindah kepada ugama kami”. Nabi Syuaib menjawab: “Adakah (kamu hendak melakukan yang demikian) sekalipun kami tidak menyukainya?', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 89, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', 'قَدِ افْتَرَيْنَا عَلَى اللَّهِ كَذِبًا إِنْ عُدْنَا فِي مِلَّتِكُم بَعْدَ إِذْ نَجَّانَا اللَّهُ مِنْهَا وَمَا يَكُونُ لَنَا أَن نَّعُودَ فِيهَا إِلَّا أَن يَشَاءَ اللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَيْءٍ عِلْمًا عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ', NULL, 'We would have invented against Allāh a lie if we returned to your religion after Allāh had saved us from it. And it is not for us to return to it except that Allāh, our Lord, should will. Our Lord has encompassed all things in knowledge. Upon Allāh we have relied. Our Lord, decide between us and our people in truth, and You are the best of those who give decision."', '“Sesungguhnya (bermakna) kami berdusta terhadap Allah, jika kami berpindah kepada ugama kamu sesudah Allah menyelamatkan kami daripadanya. Dan tidaklah harus kami berpindah kepadanya sama sekali, kecuali jika Allah Tuhan kami, menghendakinya. Pengetahuan Tuhan kami meliputi akan tiap-tiap sesuatu. Kepada Allah jualah kami bertawakal. Wahai Tuhan kami, hukumkanlah antara kami dan kaum kami dengan kebenaran (keadilan), kerana Engkau jualah sebaik-baik Hakim”.', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 90, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'وَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ لَئِنِ اتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَاسِرُونَ', NULL, 'Said the eminent ones who disbelieved among his people, "If you should follow Shuʿayb, indeed, you would then be losers."', 'Dan berkatalah pula Ketua-ketua yang kafir dari kaum Nabi Syuaib (kepada orang ramai): “Sesungguhnya jika kamu mengikut Syuaib nescaya kamu dengan perbuatan yang demikian menjadilah orang-orang yang rugi”.', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 91, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ', NULL, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.', 'Maka mereka dibinasakan oleh gempa, lalu menjadilah mereka mayat-mayat yang tersungkur di tempat masing-masing.', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 92, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', 'الَّذِينَ كَذَّبُوا شُعَيْبًا كَأَن لَّمْ يَغْنَوْا فِيهَا الَّذِينَ كَذَّبُوا شُعَيْبًا كَانُوا هُمُ الْخَاسِرِينَ', NULL, 'Those who denied Shuʿayb - it was as though they had never resided there. Those who denied Shuʿayb - it was they who were the losers.', 'Orang-orang yang mendustakan Nabi Syuaib (punah-ranah) seolah-olah mereka tidak pernah mendiami negeri itu. Orang-orang yang mendustakan Nabi Syuaib, merekalah orang-orang yang rugi.', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 93, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَٰفِرِينَ', 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَاتِ رَبِّي وَنَصَحْتُ لَكُمْ فَكَيْفَ آسَىٰ عَلَىٰ قَوْمٍ كَافِرِينَ', NULL, 'And he [i.e., Shuʿayb] turned away from them and said, "O my people, I had certainly conveyed to you the messages of my Lord and advised you, so how could I grieve for a disbelieving people?"', 'Kemudian Nabi Syuaib meninggalkan mereka sambil berkata: “Wahai kaumku! Sesungguhnya aku telah menyampaikan kepada kamu perintah-perintah Tuhanku, dan aku telah memberi nasihat kepada kamu. Oleh itu, tidaklah aku merasa sedih terhadap orang-orang kafir (yang telah binasa itu)”.', FALSE, NULL, NULL, 162, 9, 65, 132, FALSE, 0, NULL),
(7, 94, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 'وَمَا أَرْسَلْنَا فِي قَرْيَةٍ مِّن نَّبِيٍّ إِلَّا أَخَذْنَا أَهْلَهَا بِالْبَأْسَاءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَضَّرَّعُونَ', NULL, 'And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allāh].', 'Dan (Tuhan berfirman): Kami tidak mengutus dalam sesebuah negeri seorang Nabi (yang didustakan oleh penduduknya), melainkan Kami timpakan mereka dengan kesusahan (kesempitan hidup) dan penderitaan (penyakit), supaya mereka tunduk merendah diri (insaf dan tidak berlaku sombong takbur).', FALSE, NULL, NULL, 162, 9, 65, 133, FALSE, 0, NULL),
(7, 95, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'ثُمَّ بَدَّلْنَا مَكَانَ السَّيِّئَةِ الْحَسَنَةَ حَتَّىٰ عَفَوا وَّقَالُوا قَدْ مَسَّ آبَاءَنَا الضَّرَّاءُ وَالسَّرَّاءُ فَأَخَذْنَاهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', NULL, 'Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, "Our fathers [also] were touched with hardship and ease." So We seized them suddenly while they did not perceive.', 'Setelah (mereka tidak juga insaf) Kami gantikan kesusahan itu dengan kesenangan hingga mereka kembang biak (serta senang-lenang) dan berkata (dengan angkuhnya): “Sesungguhnya nenek moyang kita juga pernah merasai kesusahan dan kesenangan (sebagaimana yang kita rasakan)”. Lalu Kami timpakan mereka (dengan azab seksa) secara mengejut, dan mereka tidak menyedarinya.', FALSE, NULL, NULL, 162, 9, 65, 133, FALSE, 0, NULL),
(7, 96, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'وَلَوْ أَنَّ أَهْلَ الْقُرَىٰ آمَنُوا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِم بَرَكَاتٍ مِّنَ السَّمَاءِ وَالْأَرْضِ وَلَٰكِن كَذَّبُوا فَأَخَذْنَاهُم بِمَا كَانُوا يَكْسِبُونَ', NULL, 'And if only the people of the cities had believed and feared Allāh, We would have opened [i.e., bestowed] upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning.', 'Dan (Tuhan berfirman lagi): Sekiranya penduduk negeri itu, beriman serta bertaqwa, tentulah Kami akan membuka kepada mereka (pintu pengurniaan) yang melimpah-limpah berkatnya, dari langit dan bumi. Tetapi mereka mendustakan (Rasul Kami), lalu Kami timpakan mereka dengan azab seksa disebabkan apa yang mereka telah usahakan.', FALSE, NULL, NULL, 163, 9, 65, 133, FALSE, 0, NULL),
(7, 97, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًا وَهُمْ نَآئِمُونَ', 'أَفَأَمِنَ أَهْلُ الْقُرَىٰ أَن يَأْتِيَهُم بَأْسُنَا بَيَاتًا وَهُمْ نَائِمُونَ', NULL, 'Then, did the people of the cities feel secure from Our punishment coming to them at night while they were asleep?', 'Patutkah penduduk negeri negeri itu (bersedap hati) serta merasa aman daripada kedatangan azab Kami kepada mereka pada malam hari, semasa mereka sedang tidur?', FALSE, NULL, NULL, 163, 9, 65, 133, FALSE, 0, NULL),
(7, 98, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', 'أَوَأَمِنَ أَهْلُ الْقُرَىٰ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', NULL, 'Or did the people of the cities feel secure from Our punishment coming to them in the morning while they were at play?', 'Atau patutkah penduduk negeri negeri itu (bersedap hati) serta merasa aman daripada kedatangan azab Kami kepada mereka pada siang hari, semasa mereka sedang leka bermain-main?', FALSE, NULL, NULL, 163, 9, 65, 133, FALSE, 0, NULL),
(7, 99, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', 'أَفَأَمِنُوا مَكْرَ اللَّهِ فَلَا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ', NULL, 'Then, did they feel secure from the plan of Allāh? But no one feels secure from the plan of Allāh except the losing people.', 'Patutkah mereka (bersukaria) sehingga mereka merasa aman akan rancangan buruk (balasan azab) yang diatur oleh Allah? Kerana sebenarnya tidak ada yang merasa aman dari rancangan buruk (balasan azab) yang diatur oleh Allah itu melainkan orang-orang yang rugi.', FALSE, NULL, NULL, 163, 9, 65, 133, FALSE, 0, NULL),
(7, 100, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ الْأَرْضَ مِن بَعْدِ أَهْلِهَا أَن لَّوْ نَشَاءُ أَصَبْنَاهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', NULL, 'Has it not become clear to those who inherited the earth after its [previous] people that if We willed, We could afflict them for their sins? But We seal over their hearts so they do not hear.', 'Adakah (yang demikian itu tersembunyi dan) tidak jelas kepada orang-orang yang mewarisi negeri itu sesudah penduduknya (hilang lenyap kerana ditimpa bencana), bahawa kalau Kami kehendaki tentulah Kami akan menimpakan mereka pula dengan azab disebabkan dosa-dosa mereka, dan Kami meteraikan di atas hati mereka sehingga mereka tidak dapat mendengar (nasihat-nasihat pengajaran)?', FALSE, NULL, NULL, 163, 9, 65, 134, FALSE, 0, NULL),
(7, 101, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 'تِلْكَ الْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنبَائِهَا وَلَقَدْ جَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانُوا لِيُؤْمِنُوا بِمَا كَذَّبُوا مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ قُلُوبِ الْكَافِرِينَ', NULL, 'Those cities - We relate to you, [O Muḥammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before. Thus does Allāh seal over the hearts of the disbelievers.', 'Negeri-negeri (yang telah Kami binasakan) itu, Kami ceritakan sebahagian dari khabar beritanya kepadamu (wahai Muhammad); dan sesungguhnya telah datang kepada mereka Rasul-rasul mereka dengan keterangan-keterangan yang nyata (mukjizat), sesudah itu mereka tidak juga beriman kepada apa yang mereka telah mendustakannya dahulu. Demikianlah Allah meteraikan di atas hati orang-orang yang kafir.', FALSE, NULL, NULL, 163, 9, 65, 134, FALSE, 0, NULL),
(7, 102, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَا أَكْثَرَهُمْ لَفَاسِقِينَ', NULL, 'And We did not find for most of them any covenant; but indeed, We found most of them defiantly disobedient.', 'Dan Kami tidak mendapati bagi kebanyakan mereka sebarang janji (yang ditepati), dan Kami tidak mendapati kebanyakan mereka melainkan orang-orang yang fasik.', FALSE, NULL, NULL, 163, 9, 65, 134, FALSE, 0, NULL),
(7, 103, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'ثُمَّ بَعَثْنَا مِن بَعْدِهِم مُّوسَىٰ بِآيَاتِنَا إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ فَظَلَمُوا بِهَا فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُفْسِدِينَ', NULL, 'Then We sent after them Moses with Our signs to Pharaoh and his establishment, but they were unjust toward them. So see how was the end of the corrupters.', 'Kemudian Kami mengutuskan Nabi Musa selepas Rasul-rasul itu, dengan membawa ayat-ayat Kami kepada Firaun dan Ketua-ketua kaumnya, lalu mereka berlaku zalim (ingkar) akan ayat-ayat itu. Maka perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerosakan.', FALSE, NULL, NULL, 163, 9, 65, 134, FALSE, 0, NULL),
(7, 104, 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'وَقَالَ مُوسَىٰ يَا فِرْعَوْنُ إِنِّي رَسُولٌ مِّن رَّبِّ الْعَالَمِينَ', NULL, 'And Moses said, "O Pharaoh, I am a messenger from the Lord of the worlds', 'Dan berkatalah Nabi Musa: “Hai Firaun! Sesungguhnya aku ini adalah seorang Rasul dari Tuhan sekalian alam.', FALSE, NULL, NULL, 163, 9, 65, 134, FALSE, 0, NULL),
(7, 105, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', 'حَقِيقٌ عَلَىٰ أَن لَّا أَقُولَ عَلَى اللَّهِ إِلَّا الْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِيَ بَنِي إِسْرَائِيلَ', NULL, '[Who is] obligated not to say about Allāh except the truth. I have come to you with clear evidence from your Lord, so send with me the Children of Israel."', '“Sudah semestinya aku tidak mengatakan sesuatu terhadap Allah melainkan yang benar. Sesungguhnya aku datang kepada kamu dengan membawa keterangan yang nyata dari Tuhan kamu. Oleh itu, bebaskanlah Kaum Bani Israil menyertai aku (ke Palestin).', FALSE, NULL, NULL, 164, 9, 65, 134, FALSE, 0, NULL),
(7, 106, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قَالَ إِن كُنتَ جِئْتَ بِآيَةٍ فَأْتِ بِهَا إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, '[Pharaoh] said, "If you have come with a sign, then bring it forth, if you should be of the truthful."', 'Firaun menjawab: “Kalau betul engkau datang dengan membawa sesuatu mukjizat maka bawalah dia (supaya aku melihatnya), jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 164, 9, 65, 134, FALSE, 0, NULL),
(7, 107, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُّبِينٌ', NULL, 'So he [i.e., Moses] threw his staff, and suddenly it was a serpent, manifest.', 'Nabi Musa pun mencampakkan tongkatnya, maka tiba-tiba tongkatnya itu menjadi seekor ular yang jelas nyata.', FALSE, NULL, NULL, 164, 9, 65, 134, FALSE, 0, NULL),
(7, 108, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَاءُ لِلنَّاظِرِينَ', NULL, 'And he drew out his hand; thereupon it was white [with radiance] for the observers.', 'Dan Nabi Musa mengeluarkan tangannya, tiba-tiba tangannya (menjadi) putih (bersinar-sinar) bagi orang-orang yang melihatnya.', FALSE, NULL, NULL, 164, 9, 65, 134, FALSE, 0, NULL),
(7, 109, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', 'قَالَ الْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَاحِرٌ عَلِيمٌ', NULL, 'Said the eminent among the people of Pharaoh, "Indeed, this is a learned magician', 'Berkatalah Ketua-ketua dari kaum Firaun: “Sesungguhnya orang ini (Musa) ialah seorang ahli sihir yang mahir.', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 110, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ', 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ', NULL, 'Who wants to expel you from your land [through magic], so what do you instruct?"', '“Ia bertujuan hendak mengeluarkan kamu dari negeri kamu”. (Firaun bertanya): “Oleh itu, apa yang kamu syorkan?”', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 111, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'قَالُوا أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِي الْمَدَائِنِ حَاشِرِينَ', NULL, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', 'Mereka berkata: “Tangguhkanlah dia dan saudaranya (daripada dijatuhkan sebarang hukuman) serta utuslah ke bandar-bandar (di merata-rata negeri Mesir untuk) mengumpulkan (ahli-ahli sihir);', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 112, 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'يَأْتُوكَ بِكُلِّ سَاحِرٍ عَلِيمٍ', NULL, 'Who will bring you every learned magician."', '“Yang kelak akan membawa kepadamu segala ahli sihir yang mahir”.', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 113, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'وَجَاءَ السَّحَرَةُ فِرْعَوْنَ قَالُوا إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ الْغَالِبِينَ', NULL, 'And the magicians came to Pharaoh. They said, "Indeed for us is a reward if we are the predominant."', 'Dan datanglah ahli-ahli sihir itu kepada Firaun lalu berkata: “Sungguhkah kami akan beroleh upah, kalau kami dapat mengalahkannya?”', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 114, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ الْمُقَرَّبِينَ', NULL, 'He said, "Yes, and, [moreover], you will be among those made near [to me]."', 'Firaun menjawab: “Benar, (kamu akan mendapat upah) dan kamu sesungguhnya (akan menjadi) dari orang-orang yang damping (denganku)”.', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 115, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 'قَالُوا يَا مُوسَىٰ إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ نَحْنُ الْمُلْقِينَ', NULL, 'They said, "O Moses, either you throw [your staff], or we will be the ones to throw [first]."', 'Mereka berkata: “Hai Musa! Engkaukah yang akan mencampakkan (tongkatmu lebih dahulu) atau kamikah yang akan mencampakkan (lebih dahulu)?”', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 116, 'قَالَ أَلْقُوا۟ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ', 'قَالَ أَلْقُوا فَلَمَّا أَلْقَوْا سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ', NULL, 'He said, "Throw," and when they threw, they bewitched the eyes of the people and struck terror into them, and they presented a great [feat of] magic.', 'Nabi Musa menjawab: “Campakkanlah kamu (dahulu)!” Maka apabila mereka mencampakkan (tongkat-tongkat dan tali masing-masing), mereka menyilap mata orang ramai dan menjadikan orang-orang itu merasa gerun, serta mereka melakukan sihir yang besar (keadaan dan caranya).', FALSE, NULL, NULL, 164, 9, 65, 135, FALSE, 0, NULL),
(7, 117, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ', NULL, 'And We inspired to Moses, "Throw your staff," and at once it devoured what they were falsifying.', 'Dan Kami wahyukan kepada Nabi Musa: “Campakkanlah tongkatmu!” Maka tiba-tiba tongkat itu menelan apa yang mereka pura-pura adakan (dengan sihir mereka).', FALSE, NULL, NULL, 164, 9, 66, 135, FALSE, 0, NULL),
(7, 118, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', 'فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ', NULL, 'So the truth was established, and abolished was what they were doing.', 'Maka sabitlah kebenaran (mukjizat Nabi Musa), dan batallah (sihir) yang mereka telah lakukan.', FALSE, NULL, NULL, 164, 9, 66, 135, FALSE, 0, NULL),
(7, 119, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', 'فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ', NULL, 'And they [i.e., Pharaoh and his people] were overcome right there and became debased.', 'Oleh itu, kalahlah Firaun dan Ketua-ketua kaumnya di situ dan kembalilah mereka dengan keadaan yang hina.', FALSE, NULL, NULL, 164, 9, 66, 135, FALSE, 0, NULL),
(7, 120, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'وَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ', NULL, 'And the magicians fell down in prostration [to Allāh].', 'Dan (kemenangan Nabi Musa menjadikan) ahli-ahli sihir itu dengan sendirinya merebahkan diri mereka sujud,', FALSE, NULL, NULL, 164, 9, 66, 135, FALSE, 0, NULL),
(7, 121, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'قَالُوا آمَنَّا بِرَبِّ الْعَالَمِينَ', NULL, 'They said, "We have believed in the Lord of the worlds,', 'Sambil berkata: “Kami beriman kepada Tuhan sekalian alam.', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 122, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'رَبِّ مُوسَىٰ وَهَارُونَ', NULL, 'The Lord of Moses and Aaron."', '“(Iaitu) Tuhan bagi Nabi Musa dan Nabi Harun”.', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 123, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ', 'قَالَ فِرْعَوْنُ آمَنتُم بِهِ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِي الْمَدِينَةِ لِتُخْرِجُوا مِنْهَا أَهْلَهَا فَسَوْفَ تَعْلَمُونَ', NULL, 'Said Pharaoh, "You believed in him before I gave you permission. Indeed, this is a conspiracy which you conspired in the city to expel therefrom its people. But you are going to know.', 'Firaun berkata: “Patutkah kamu beriman kepadanya sebelum aku memberi izin kepada kamu? Sesungguhnya ini adalah perbuatan tipu daya yang kamu lakukan dalam bandar ini kerana kamu hendak mengeluarkan penduduknya dari padanya. Oleh itu, kamu akan mengetahui (akibatya).', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 124, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', NULL, 'I will surely cut off your hands and your feet on opposite sides; then I will surely crucify you all."', '“Demi sesungguhnya, aku akan memotong tangan dan kaki kamu dengan bersilang, kemudian aku akan memalang kamu semuanya”.', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 125, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'قَالُوا إِنَّا إِلَىٰ رَبِّنَا مُنقَلِبُونَ', NULL, 'They said, "Indeed, to our Lord we will return.', 'Mereka menjawab: “Sesungguhnya kami (tidak gentar) kerana kepada Tuhan kamilah kembalinya kami (dan kepadaNyalah kami mengharapkan keampunan dan rahmatNya).', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 126, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', 'وَمَا تَنقِمُ مِنَّا إِلَّا أَنْ آمَنَّا بِآيَاتِ رَبِّنَا لَمَّا جَاءَتْنَا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', NULL, 'And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You]."', '“Dan tidaklah engkau (hai Firaun) marah (dan bertindak menyeksa) kami melainkan kerana kami beriman kepada ayat-ayat Tuhan kami, ketika sampainya kepada kami”. (Mereka berdoa): “Wahai Tuhan kami, limpahkanlah kesabaran kepada kami, dan matikanlah kami dalam keadaan Islam (berserah bulat-bulat kepadaMu)”.', FALSE, NULL, NULL, 165, 9, 66, 135, FALSE, 0, NULL),
(7, 127, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', 'وَقَالَ الْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُ لِيُفْسِدُوا فِي الْأَرْضِ وَيَذَرَكَ وَآلِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَاءَهُمْ وَنَسْتَحْيِي نِسَاءَهُمْ وَإِنَّا فَوْقَهُمْ قَاهِرُونَ', NULL, 'And the eminent among the people of Pharaoh said, "Will you leave Moses and his people to cause corruption in the land and abandon you and your gods?" [Pharaoh] said, "We will kill their sons and keep their women alive; and indeed, we are subjugators over them."', 'Dan berkatalah pula Ketua-ketua dari kaum Firaun: “Adakah engkau (wahai Firaun) hendak membiarkan Musa dan kaumnya untuk melakukan kerosakan di bumi (Mesir) dan meninggalkanmu serta apa-apa yang dipuja olehmu?” Firaun menjawab: “Kita akan membunuh anak-anak lelaki mereka dan kita biarkan hidup anak-anak perempuan mereka, dan kita tetap menguasai (menundukkan) mereka”.', FALSE, NULL, NULL, 165, 9, 66, 136, FALSE, 0, NULL),
(7, 128, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'قَالَ مُوسَىٰ لِقَوْمِهِ اسْتَعِينُوا بِاللَّهِ وَاصْبِرُوا إِنَّ الْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَاءُ مِنْ عِبَادِهِ وَالْعَاقِبَةُ لِلْمُتَّقِينَ', NULL, 'Said Moses to his people, "Seek help through Allāh and be patient. Indeed, the earth belongs to Allāh. He causes to inherit it whom He wills of His servants. And the [best] outcome is for the righteous."', '(Pengikut-pengikut Nabi Musa merayu, lalu) Musa berkata kepada kaumnya: “Mintalah pertolongan kepada Allah dan bersabarlah, sesungguhnya bumi ini kepunyaan Allah, diwariskannya kepada sesiapa yang dikehendakiNya dari hamba-hambaNya; dan kesudahan yang baik adalah bagi orang-orang yang bertaqwa”.', FALSE, NULL, NULL, 165, 9, 66, 136, FALSE, 0, NULL),
(7, 129, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', 'قَالُوا أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِن بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِي الْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', NULL, 'They said, "We have been harmed before you came to us and after you have come to us." He said, "Perhaps your Lord will destroy your enemy and grant you succession in the land and see how you will do."', 'Mereka berkata: “Kami telah dianiaya dan diperhambakan (oleh Firaun) sebelum engkau datang kepada kami dan sesudah engkau datang kepada kami”. Nabi Musa menjawab: “Mudah-mudahan Tuhan kamu akan membinasakan musuh kamu dan menjadikan kamu khalifah di bumi, kemudian Ia akan memerhati bagaimana pula perbuatan kamu?”', FALSE, NULL, NULL, 165, 9, 66, 136, FALSE, 0, NULL),
(7, 130, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'وَلَقَدْ أَخَذْنَا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِّنَ الثَّمَرَاتِ لَعَلَّهُمْ يَذَّكَّرُونَ', NULL, 'And We certainly seized the people of Pharaoh with years of famine and a deficiency in fruits that perhaps they would be reminded.', 'Dan sesungguhnya Kami telah menimpakan Firaun dan kaumnya dengan musim kemarau dan kekurangan buah-buahan, supaya mereka insaf mengambil pelajaran.', FALSE, NULL, NULL, 165, 9, 66, 137, FALSE, 0, NULL),
(7, 131, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فَإِذَا جَاءَتْهُمُ الْحَسَنَةُ قَالُوا لَنَا هَٰذِهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا بِمُوسَىٰ وَمَن مَّعَهُ أَلَا إِنَّمَا طَائِرُهُمْ عِندَ اللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'But when good [i.e., provision] came to them, they said, "This is ours [by right]." And if a bad [condition] struck them, they saw an evil omen in Moses and those with him. Unquestionably, their fortune is with Allāh, but most of them do not know.', 'Kemudian apabila datang kepada mereka kesenangan mereka berkata: “Ini ialah hasil usaha kami”, dan jika mereka ditimpa kesusahan, mereka mengatakan nahas dan malang itu disebabkan oleh Nabi Musa dan pengikut-pengikutnya. (Tuhan berfirman): Ketahuilah, sesungguhnya nahas dan malang mereka itu hanya di tetapkan di sisi Allah, akan tetapi kebanyakan mereka tidak mengetahui.', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 132, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'وَقَالُوا مَهْمَا تَأْتِنَا بِهِ مِنْ آيَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', NULL, 'And they said, "No matter what sign you bring us with which to bewitch us, we will not be believers in you."', 'Dan mereka berkata: “Walau apa sahaja (jenis-jenis) keterangan (mukjizat) yang engkau bawa kepada kami; (wahai Musa), untuk menjalankan sihirmu kepada kami, maka kami tidak sekali-kali akan beriman kepadamu”.', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 133, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍ مُّفَصَّلَٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'فَأَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ آيَاتٍ مُّفَصَّلَاتٍ فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا مُّجْرِمِينَ', NULL, 'So We sent upon them the flood and locusts and lice and frogs and blood as distinct signs, but they were arrogant and were a criminal people.', '(Allah berfirman): Kami pun menghantarkan kepada mereka taufan, dan belalang, dan kutu, dan katak, dan darah, sebagai tanda-tanda dan bukti yang jelas nyata, maka mereka juga tetap berlaku sombong takbur dan menjadi kaum yang menderhaka.', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 134, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', 'وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرَائِيلَ', NULL, 'And when the punishment descended upon them, they said, "O Moses, invoke for us your Lord by what He has promised you. If you [can] remove the punishment from us, we will surely believe you, and we will send with you the Children of Israel."', 'Dan apabila azab yang tersebut itu menimpa mereka, mereka (merayu dengan) berkata: “Wahai Musa! Pohonkanlah kepada Tuhanmu untuk kami dengan (kehormatan) pangkat Nabi yang diberikanNya kepadamu (yang menjadikan permohonanmu sentiasa makbul). Sesungguhnya jika engkau hapuskan azab itu daripada kami, tentulah kami akan beriman kepadamu, dan sudah tentu kami akan membebaskan kaum Bani Israil (pergi) bersamamu”.', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 135, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 'فَلَمَّا كَشَفْنَا عَنْهُمُ الرِّجْزَ إِلَىٰ أَجَلٍ هُم بَالِغُوهُ إِذَا هُمْ يَنكُثُونَ', NULL, 'But when We removed the punishment from them until a term which they were to reach, then at once they broke their word.', '(Tuhan berfirman): Setelah Kami hapuskan azab itu daripada mereka, hingga ke suatu masa yang tertentu yang mereka sampai kepadanya, tiba-tiba mereka mencabuli janjinya', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 136, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'فَانتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ فِي الْيَمِّ بِأَنَّهُمْ كَذَّبُوا بِآيَاتِنَا وَكَانُوا عَنْهَا غَافِلِينَ', NULL, 'So We took retribution from them, and We drowned them in the sea because they denied Our signs and were heedless of them.', 'Maka Kami pun membalas mereka, lalu Kami menenggelamkan mereka di laut dengan sebab mereka mendustakan ayat-ayat Kami dan mereka sentiasa lalai daripadanya.', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 137, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', 'وَأَوْرَثْنَا الْقَوْمَ الَّذِينَ كَانُوا يُسْتَضْعَفُونَ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا الَّتِي بَارَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنَىٰ عَلَىٰ بَنِي إِسْرَائِيلَ بِمَا صَبَرُوا وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُ وَمَا كَانُوا يَعْرِشُونَ', NULL, 'And We caused the people who had been oppressed to inherit the eastern regions of the land and the western ones, which We had blessed. And the good word [i.e., decree] of your Lord was fulfilled for the Children of Israel because of what they had patiently endured. And We destroyed [all] that Pharaoh and his people were producing and what they had been building.', 'Dan Kami wariskan kepada kaum (Bani Israil) yang telah tertindas itu akan daerah-daerah timur bumi (Palestin) dan daerah-daerah baratnya, yang Kami telah melimpahkan berkat padanya. Dan telah sempurnalah Kalimah Allah (janjiNya) yang baik kepada kaum Bani Israil kerana kesabaran mereka (semasa mereka ditindas oleh Firaun), dan Kami telah hancurkan apa yang telah dibuat oleh Firaun dan kaumnya dan apa yang mereka telah dirikan (dari bangunan-bangunan yang tinggi)', FALSE, NULL, NULL, 166, 9, 66, 137, FALSE, 0, NULL),
(7, 138, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', 'وَجَاوَزْنَا بِبَنِي إِسْرَائِيلَ الْبَحْرَ فَأَتَوْا عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰ أَصْنَامٍ لَّهُمْ قَالُوا يَا مُوسَى اجْعَل لَّنَا إِلَٰهًا كَمَا لَهُمْ آلِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', NULL, 'And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They [the Children of Israel] said, "O Moses, make for us a god just as they have gods." He said, "Indeed, you are a people behaving ignorantly.', 'Dan Kami bawakan Bani Israil ke sebarang Laut (Merah) itu lalu mereka sampai kepada suatu kaum yang sedang menyembah berhala-berhalanya. (Melihatkan yang demikian) mereka (Bani Israil) berkata: “Wahai Musa buatlah untuk kami suatu tuhan (berhala) sebagaimana mereka mempunyai beberapa tuhan”. Nabi Musa menjawab: “Sesungguhnya kamu ini adalah kaum yang jahil.', FALSE, NULL, NULL, 167, 9, 66, 137, FALSE, 0, NULL),
(7, 139, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'إِنَّ هَٰؤُلَاءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَاطِلٌ مَّا كَانُوا يَعْمَلُونَ', NULL, 'Indeed, those [worshippers] - destroyed is that in which they are [engaged], and worthless is whatever they were doing."', '“Sesungguhnya mereka (penyembah-penyembah berhala itu), akan dihancurkan apa yang mereka berada di dalamnya (dari perbuatan syirik), dan tetaplah salahnya apa yang mereka kerjakan itu”.', FALSE, NULL, NULL, 167, 9, 66, 137, FALSE, 0, NULL),
(7, 140, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', 'قَالَ أَغَيْرَ اللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى الْعَالَمِينَ', NULL, 'He said, "Is it other than Allāh I should desire for you as a god while He has preferred you over the worlds?"', 'Nabi Musa berkata lagi: “Patutkah aku mencari tuhan untuk kamu selain dari Allah, padahal Ia telah melebihkan kamu atas sekalian manusia (yang sezaman dengan kamu, dengan berbagai nikmat yang telah dikurniakanNya kepada kamu)?”', FALSE, NULL, NULL, 167, 9, 66, 137, FALSE, 0, NULL),
(7, 141, 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ يُقَتِّلُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ', NULL, 'And [recall, O Children of Israel], when We saved you from the people of Pharaoh, [who were] afflicting you with the worst torment - killing your sons and keeping your women alive. And in that was a great trial from your Lord.', 'Dan (Tuhan berfirman): Ingatlah ketika Kami selamatkan kamu dari Firaun dan kaumnya, yang menyeksa kamu dengan azab seksa yang seberat-berat dan seburuk-buruknya; mereka membunuh anak-anak lelaki kamu dan membiarkan hidup anak-anak perempuan kamu; dan (ingatlah bahawa) yang demikian itu mengandungi cubaan yang besar dari Tuhan kamu.', FALSE, NULL, NULL, 167, 9, 66, 137, FALSE, 0, NULL),
(7, 142, 'وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةً وَأَتْمَمْنَٰهَا بِعَشْرٍ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 'وَوَاعَدْنَا مُوسَىٰ ثَلَاثِينَ لَيْلَةً وَأَتْمَمْنَاهَا بِعَشْرٍ فَتَمَّ مِيقَاتُ رَبِّهِ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَارُونَ اخْلُفْنِي فِي قَوْمِي وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ الْمُفْسِدِينَ', NULL, 'And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, "Take my place among my people, do right [by them], and do not follow the way of the corrupters."', 'Dan kami telah janjikan masa kepada Nabi Musa (untuk memberikan Taurat) selama tiga puluh malam, serta Kami genapkan jumlahnya dengan sepuluh malam lagi, lalu sempurnalah waktu yang telah ditentukan oleh Tuhannya empat puluh malam. Dan berkatalah Nabi Musa kepada saudaranya Nabi Harun (semasa keluar menerima Taurat): “Gantikanlah aku dalam (urusan memimpin) kaumku dan perbaikilah (keadaan mereka sepeninggalanku), dan janganlah engkau menurut jalan orang-orang yang melakukan kerosakan”.', FALSE, NULL, NULL, 167, 9, 67, 138, FALSE, 0, NULL),
(7, 143, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 'وَلَمَّا جَاءَ مُوسَىٰ لِمِيقَاتِنَا وَكَلَّمَهُ رَبُّهُ قَالَ رَبِّ أَرِنِي أَنظُرْ إِلَيْكَ قَالَ لَن تَرَانِي وَلَٰكِنِ انظُرْ إِلَى الْجَبَلِ فَإِنِ اسْتَقَرَّ مَكَانَهُ فَسَوْفَ تَرَانِي فَلَمَّا تَجَلَّىٰ رَبُّهُ لِلْجَبَلِ جَعَلَهُ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّا أَفَاقَ قَالَ سُبْحَانَكَ تُبْتُ إِلَيْكَ وَأَنَا أَوَّلُ الْمُؤْمِنِينَ', NULL, 'And when Moses arrived at Our appointed time and his Lord spoke to him, he said, "My Lord, show me [Yourself] that I may look at You." [Allāh] said, "You will not see Me, but look at the mountain; if it should remain in place, then you will see Me." But when his Lord appeared to the mountain, He rendered it level, and Moses fell unconscious. And when he awoke, he said, "Exalted are You! I have repented to You, and I am the first [among my people] of the believers."', 'Dan ketika Nabi Musa datang pada waktu yang Kami telah tentukan itu, dan Tuhannya berkata-kata dengannya, maka Nabi Musa (merayu dengan) berkata: “Wahai Tuhanku! Perlihatkanlah kepadaku (ZatMu Yang Maha Suci) supaya aku dapat melihatMu”. Allah berfirman: “Engkau tidak sekali-kali akan sanggup melihatKu, tetapi pandanglah ke gunung itu, maka kalau ia tetap berada di tempatnya, nescaya engkau akan dapat melihatKu”, Setelah Tuhannya “Tajalla” (menzahirkan kebesaranNya) kepada gunung itu, (maka) “TajalliNya” menjadikan gunung itu hancur lebur dan Nabi Musa pun jatuh pengsan. Setelah ia sedar semula, berkatalah ia: “Maha Suci Engkau (wahai Tuhanku), aku bertaubat kepadaMu, dan akulah orang yang awal pertama beriman (pada zamanku)', FALSE, NULL, NULL, 167, 9, 67, 138, FALSE, 0, NULL),
(7, 144, 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'قَالَ يَا مُوسَىٰ إِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسَالَاتِي وَبِكَلَامِي فَخُذْ مَا آتَيْتُكَ وَكُن مِّنَ الشَّاكِرِينَ', NULL, '[Allāh] said, "O Moses, I have chosen you over the people with My messages and My words [to you]. So take what I have given you and be among the grateful."', 'Allah berfirman: “Wahai Musa! Sesungguhnya Aku memilihmu melebihi umat manusia (yang ada pada zamanmu), dengan membawa perutusanKu (Kitab Taurat) dan dengan KalamKu; oleh itu, terimalah apa yang Aku kurniakan kepadamu, dan jadikanlah dirimu dari orang-orang yang bersyukur”.', FALSE, NULL, NULL, 168, 9, 67, 138, FALSE, 0, NULL),
(7, 145, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 'وَكَتَبْنَا لَهُ فِي الْأَلْوَاحِ مِن كُلِّ شَيْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَيْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا سَأُرِيكُمْ دَارَ الْفَاسِقِينَ', NULL, 'And We wrote for him on the tablets [something] of all things - instruction and explanation for all things, [saying], "Take them with determination and order your people to take the best of it. I will show you the home of the defiantly disobedient."', 'Dan Kami telah menuliskan bagi Nabi Musa pada Lauh-lauh (Taurat) itu, dari pelbagai jenis nasihat pengajaran dan penjelasan bagi tiap-tiap sesuatu (dasar Syariat dan hukum-hukumnya). Oleh itu, terimalah dia (dan amalkanlah wahai Musa) dengan bersungguh-sungguh, dan suruhlah kaummu berpegang (serta mengamalkan) yang sebaik-baiknya (iaitu suruhan-suruhannya). Aku akan perlihatkan kepada kamu akan negeri orang-orang yang fasik - derhaka”.', FALSE, NULL, NULL, 168, 9, 67, 138, FALSE, 0, NULL),
(7, 146, 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'سَأَصْرِفُ عَنْ آيَاتِيَ الَّذِينَ يَتَكَبَّرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَإِن يَرَوْا كُلَّ آيَةٍ لَّا يُؤْمِنُوا بِهَا وَإِن يَرَوْا سَبِيلَ الرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا سَبِيلَ الْغَيِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا بِآيَاتِنَا وَكَانُوا عَنْهَا غَافِلِينَ', NULL, 'I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them.', 'Aku akan memalingkan (hati) orang-orang yang sombong takbur di muka bumi dengan tiada alasan yang benar dari (memahami) ayat-ayatKu (yang menunjukkan kekuasaanKu); dan mereka (yang bersifat demikian) jika mereka melihat sebarang keterangan (bukti), mereka tidak beriman kepadanya, dan jika mereka melihat jalan yang (membawa kepada) hidayah petunjuk, mereka tidak mengambilnya sebagai jalan yang dilalui. Dan sebaliknya jika mereka melihat jalan kesesatan, mereka terus mengambilnya sebagai jalan yang dilalui. Yang demikian itu, kerana mereka mendustakan ayat-ayat Kami dan mereka sentiasa lalai daripadanya.', FALSE, NULL, NULL, 168, 9, 67, 138, FALSE, 0, NULL),
(7, 147, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا وَلِقَاءِ الْآخِرَةِ حَبِطَتْ أَعْمَالُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ', NULL, 'Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?', 'Dan orang-orang yang mendustakan ayat-ayat Kami dan pertemuan hari akhirat, gugurlah amal-amal mereka (yang baik). Mereka tidak diberikan balasan (pada hari akhirat) melainkan (bagi) apa yang mereka telah kerjakan (dari perbuatan kufur dan maksiat).', FALSE, NULL, NULL, 168, 9, 67, 138, FALSE, 0, NULL),
(7, 148, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', 'وَاتَّخَذَ قَوْمُ مُوسَىٰ مِن بَعْدِهِ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُ خُوَارٌ أَلَمْ يَرَوْا أَنَّهُ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا اتَّخَذُوهُ وَكَانُوا ظَالِمِينَ', NULL, 'And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers.', 'Dan kaum Nabi Musa, sesudah ia (pergi ke Gunung Tursina), mereka membuat dari barang-barang emas perhiasan mereka, (patung) anak lembu yang bertubuh dan bersuara (Allah berfirman): “Tidakkah mereka memikirkan bahawa patung itu tidak dapat berkata-kata dengan mereka dan tidak dapat juga menunjukkan jalan kepada mereka? Mereka menjadikannya (berhala yang disembah) dan sememangnya mereka adalah orang-orang yang melakukan kezaliman”.', FALSE, NULL, NULL, 168, 9, 67, 139, FALSE, 0, NULL),
(7, 149, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'وَلَمَّا سُقِطَ فِي أَيْدِيهِمْ وَرَأَوْا أَنَّهُمْ قَدْ ضَلُّوا قَالُوا لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', NULL, 'And when regret overcame them and they saw that they had gone astray, they said, "If our Lord does not have mercy upon us and forgive us, we will surely be among the losers."', 'Dan setelah mereka menyesal (akan apa yang mereka lakukan) dan mengetahui bahawa mereka telah sesat, berkatalah mereka: “Sesungguhnya jika Tuhan kami tidak memberi rahmat kepada kami dan mengampunkan kami, nescaya menjadilah kami dari orang-orang yang rugi”.', FALSE, NULL, NULL, 168, 9, 67, 139, FALSE, 0, NULL),
(7, 150, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وَلَمَّا رَجَعَ مُوسَىٰ إِلَىٰ قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِي مِن بَعْدِي أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ قَالَ ابْنَ أُمَّ إِنَّ الْقَوْمَ اسْتَضْعَفُونِي وَكَادُوا يَقْتُلُونَنِي فَلَا تُشْمِتْ بِيَ الْأَعْدَاءَ وَلَا تَجْعَلْنِي مَعَ الْقَوْمِ الظَّالِمِينَ', NULL, 'And when Moses returned to his people, angry and grieved, he said, "How wretched is that by which you have replaced me after [my departure]. Were you impatient over the matter of your Lord?" And he threw down the tablets and seized his brother by [the hair of] his head, pulling him toward him. [Aaron] said, "O son of my mother, indeed the people overpowered me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people."', 'Dan apabila Nabi Musa kembali kepada kaumnya dengan marah dan dukacita, berkatalah ia: “Amatlah buruknya apa yang telah kamu lakukan sepeninggalanku; mengapa kamu terburu-buru (tidak menunggu) perintah Tuhan kamu?” Dan ia meletakkan Lauh-lauh (yang mengandungi tulisan Taurat) itu serta ia memegang (rambut) kepala saudaranya (Nabi Harun) sambil menariknya kepadanya. Nabi Harun berkata: “Wahai anak ibuku! Sesungguhnya kaum (Bani Israil) memandangku lemah dan nyaris-nyaris mereka membunuhku (ketika aku melarang mereka); oleh itu, janganlah engkau menjadikan musuh bergembira melihat (tempelakmu) terhadapku, dan janganlah engkau jadikan daku termasuk dalam golongan orang-orang yang zalim”.', FALSE, NULL, NULL, 169, 9, 67, 139, FALSE, 0, NULL),
(7, 151, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قَالَ رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ', NULL, '[Moses] said, "My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful."', 'Nabi Musa berdoa dengan berkata: “Wahai Tuhanku, ampunkanlah bagiku dan bagi saudaraku, dan masukkanlah kami ke dalam rahmatMu, kerana Engkaulah sahaja Yang Maha Mengasihani dari segala yang lain mengasihani”.', FALSE, NULL, NULL, 169, 9, 67, 139, FALSE, 0, NULL),
(7, 152, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', 'إِنَّ الَّذِينَ اتَّخَذُوا الْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِي الْحَيَاةِ الدُّنْيَا وَكَذَٰلِكَ نَجْزِي الْمُفْتَرِينَ', NULL, 'Indeed, those who took the calf [for worship] will obtain anger from their Lord and humiliation in the life of this world, and thus do We recompense the inventors [of falsehood].', 'Sesungguhnya orang-orang yang menyembah (patung) anak lembu itu, akan ditimpa kemurkaan dari Tuhan mereka dan kehinaan dalam kehidupan dunia. Dan demikianlah kami membalas orang-orang yang mengada-adakan perkara yang tidak benar.', FALSE, NULL, NULL, 169, 9, 67, 140, FALSE, 0, NULL),
(7, 153, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'وَالَّذِينَ عَمِلُوا السَّيِّئَاتِ ثُمَّ تَابُوا مِن بَعْدِهَا وَآمَنُوا إِنَّ رَبَّكَ مِن بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', NULL, 'But those who committed misdeeds and then repented after them and believed - indeed your Lord, thereafter, is Forgiving and Merciful.', 'Dan orang-orang yang melakukan kejahatan kemudian mereka bertaubat sesudah itu dan beriman, (maka) sesungguhnya Tuhanmu sesudah itu Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 169, 9, 67, 140, FALSE, 0, NULL),
(7, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'وَلَمَّا سَكَتَ عَن مُّوسَى الْغَضَبُ أَخَذَ الْأَلْوَاحَ وَفِي نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', NULL, 'And when the anger subsided in Moses, he took up the tablets; and in their inscription was guidance and mercy for those who are fearful of their Lord.', 'Dan apabila kemarahan Nabi Musa itu reda, dia pun mengambil Lauh-lauh Taurat itu yang dalam naskhahnya terkandung petunjuk dan rahmat, bagi orang-orang yang bersungguh-sungguh takut kepada Tuhan mereka (daripada melanggar perintahNya).', FALSE, NULL, NULL, 169, 9, 67, 140, FALSE, 0, NULL),
(7, 155, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَٰتِنَا فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 'وَاخْتَارَ مُوسَىٰ قَوْمَهُ سَبْعِينَ رَجُلًا لِّمِيقَاتِنَا فَلَمَّا أَخَذَتْهُمُ الرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّايَ أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا إِنْ هِيَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَاءُ وَتَهْدِي مَن تَشَاءُ أَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الْغَافِرِينَ', NULL, 'And Moses chose from his people seventy men for Our appointment. And when the earthquake seized them, he said, "My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers.', 'Dan Nabi Musa memilih tujuh puluh orang lelaki dari kaumnya (untuk di bawa bersama ke Gunung Tursina) pada waktu yang telah kami tentukan. Maka ketika mereka digegar oleh gempa, Nabi Musa merayu dengan berkata: “Wahai Tuhanku! Jika Engkau kehendaki, Engkau boleh binasakan mereka bersama-sama denganku sebelum ini. Adakah Engkau hendak membinasakan kami disebabkan apa yang telah dilakukan oleh orang-orang yang bodoh di antara kami? (Apa yang mereka telah lakukan) itu hanyalah cubaanMu. Dengan cubaan itu Engkau sesatkan sesiapa yang Engkau kehendaki dan Engkau beri petunjuk kepada sesiapa yang Engkau kehendaki. Engkau jualah Pelindung kami; oleh itu ampunkanlah kami dan berilah rahmat kepada kami, kerana Engkau jualah sebaik-baik Pemberi ampun.', FALSE, NULL, NULL, 169, 9, 67, 140, FALSE, 0, NULL),
(7, 156, 'وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', 'وَاكْتُبْ لَنَا فِي هَٰذِهِ الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ إِنَّا هُدْنَا إِلَيْكَ قَالَ عَذَابِي أُصِيبُ بِهِ مَنْ أَشَاءُ وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكَاةَ وَالَّذِينَ هُم بِآيَاتِنَا يُؤْمِنُونَ', NULL, 'And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You." [Allāh] said, "My punishment - I afflict with it whom I will, but My mercy encompasses all things." So I will decree it [especially] for those who fear Me and give zakāh and those who believe in Our verses-', '“Dan tetapkanlah untuk Kami kebaikan dalam dunia ini dan juga di akhirat, sesungguhnya kami kembali (bertaubat) kepadaMu”. Allah berfirman: “AzabKu akan Aku timpakan kepada sesiapa yang Aku kehendaki, dan rahmatKu meliputi tiap-tiap sesuatu; maka Aku akan menentukannya bagi orang-orang yang bertaqwa, dan yang memberi zakat, serta orang-orang yang beriman kepada ayat-ayat Kami.', FALSE, NULL, NULL, 170, 9, 68, 140, FALSE, 0, NULL),
(7, 157, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْأُمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِندَهُمْ فِي التَّوْرَاةِ وَالْإِنجِيلِ يَأْمُرُهُم بِالْمَعْرُوفِ وَيَنْهَاهُمْ عَنِ الْمُنكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَالْأَغْلَالَ الَّتِي كَانَتْ عَلَيْهِمْ فَالَّذِينَ آمَنُوا بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّذِي أُنزِلَ مَعَهُ أُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'Those who follow the Messenger, the unlettered prophet, whom they find written [i.e., described] in what they have of the Torah and the Gospel, who enjoins upon them what is right and prohibits them from what is wrong and makes lawful for them what is good and forbids them from what is evil and relieves them of their burden and the shackles which were upon them. So they who have believed in him, honored him, supported him and followed the light which was sent down with him - it is those who will be the successful.', '“Iaitu orang-orang yang mengikut Rasulullah (Muhammad s.a.w) Nabi yang Ummi, yang mereka dapati tertulis (namanya dan sifat-sifatnya) di dalam Taurat dan Injil yang ada di sisi mereka. Ia menyuruh mereka dengan perkara-perkara yang baik, dan melarang mereka daripada melakukan perkara-perkara yang keji; dan ia menghalalkan bagi mereka segala benda yang baik, dan mengharamkan kepada mereka segala benda yang buruk; dan ia juga menghapuskan dari mereka beban-beban dan belenggu-belenggu yang ada pada pada mereka. Maka orang-orang yang beriman kepadanya, dan memuliakannya, juga menolongnya, serta mengikut nur (cahaya) yang diturunkan kepadanya (Al-Quran), mereka itulah orang-orang yang berjaya.', FALSE, NULL, NULL, 170, 9, 68, 140, FALSE, 0, NULL),
(7, 158, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', 'قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ لَا إِلَٰهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الْأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', NULL, 'Say, [O Muḥammad], "O mankind, indeed I am the Messenger of Allāh to you all, [from Him] to whom belongs the dominion of the heavens and the earth. There is no deity except Him; He gives life and causes death." So believe in Allāh and His Messenger, the unlettered prophet, who believes in Allāh and His words, and follow him that you may be guided.', 'Katakanlah (wahai Muhammad): “Wahai sekalian manusia! Sesungguhnya aku adalah Pesuruh Allah kepada kamu semuanya, (di utus oleh Allah) yang menguasai langit dan bumi, tiada Tuhan (yang berhak disembah) melainkan Dia; Yang menghidupkan dan mematikan. Oleh itu, berimanlah kamu kepada Allah dan RasulNya, Nabi yang Ummi yang beriman kepada Allah dan Kalimah-kalimahNya (Kitab-kitabNya); dan ikutilah dia, supaya kamu beroleh hidayah petunjuk”.', FALSE, NULL, NULL, 170, 9, 68, 141, FALSE, 0, NULL),
(7, 159, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'وَمِن قَوْمِ مُوسَىٰ أُمَّةٌ يَهْدُونَ بِالْحَقِّ وَبِهِ يَعْدِلُونَ', NULL, 'And among the people of Moses is a community which guides by truth and by it establishes justice.', 'Dan di antara kaum Nabi Musa, ada satu golongan yang memberi petunjuk (kepada orang ramai) dengan perkara-perkara yang hak, dan dengannya mereka menjalankan keadilan.', FALSE, NULL, NULL, 170, 9, 68, 141, FALSE, 0, NULL),
(7, 160, 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وَقَطَّعْنَاهُمُ اثْنَتَيْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ إِذِ اسْتَسْقَاهُ قَوْمُهُ أَنِ اضْرِب بِّعَصَاكَ الْحَجَرَ فَانبَجَسَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ الْغَمَامَ وَأَنزَلْنَا عَلَيْهِمُ الْمَنَّ وَالسَّلْوَىٰ كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'And We divided them into twelve descendant tribes [as distinct] nations. And We inspired to Moses when his people implored him for water, "Strike with your staff the stone," and there gushed forth from it twelve springs. Every people [i.e., tribe] knew its watering place. And We shaded them with clouds and sent down upon them manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not, but they were [only] wronging themselves.', 'Dan kami membahagikan mereka (Bani Israil) menjadi dua belas suku, sebagai golongan-golongan besar, dan Kami wahyukan kepada Nabi Musa, ketika kaumnya meminta air kepadanya: “Pukullah batu itu dengan tongkatmu.” Maka terpancarlah daripadanya dua belas mata air. Tiap-tiap golongan (di antara mereka) mengetahui tempat masing-masing. Dan Kami naungi mereka dengan awan, dan Kami turunkan kepada mereka “Mann” dan “Salwa”. (Lalu Kami berfirman): “Makanlah dari baik-baik yang kami telah kurniakan kepada kamu”. Dan tidaklah mereka menganiaya Kami (dengan kekufuran mereka), tetapi mereka adalah menganiaya diri mereka sendiri.', FALSE, NULL, NULL, 171, 9, 68, 141, FALSE, 0, NULL),
(7, 161, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ', 'وَإِذْ قِيلَ لَهُمُ اسْكُنُوا هَٰذِهِ الْقَرْيَةَ وَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا حِطَّةٌ وَادْخُلُوا الْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيئَاتِكُمْ سَنَزِيدُ الْمُحْسِنِينَ', NULL, 'And [mention, O Muḥammad], when it was said to them, "Dwell in this city [i.e., Jerusalem] and eat from it wherever you will and say, ''Relieve us of our burdens [i.e., sins],'' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward]."', 'Dan (ingatlah) ketika dikatakan kepada mereka: “Tinggallah dalam bandar ini dan makanlah dari makanannya apa sahaja yang kamu sukai, dan berdoalah dengan berkata: ‘(Wahai Tuhan kami), gugurkanlah (dosa kami)’, dan masuklah melalui pintu (bandar) itu dengan tunduk merendah diri, supaya Kami mengampunkan dosa-dosa kamu. Kami akan menambah (balasan) bagi orang-orang yang berbuat kebaikan”.', FALSE, NULL, NULL, 171, 9, 68, 141, FALSE, 0, NULL),
(7, 162, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 'فَبَدَّلَ الَّذِينَ ظَلَمُوا مِنْهُمْ قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ السَّمَاءِ بِمَا كَانُوا يَظْلِمُونَ', NULL, 'But those who wronged among them changed [the words] to a statement other than that which had been said to them. So We sent upon them a punishment from the sky for the wrong that they were doing.', 'Maka orang-orang yang zalim di antara mereka menukarkan perintah itu dengan perkataan yang tidak dikatakan kepada mereka. Oleh itu, Kami turunkan azab dari langit menimpa mereka, dengan sebab kezaliman yang mereka lakukan.', FALSE, NULL, NULL, 171, 9, 68, 141, FALSE, 0, NULL),
(7, 163, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 'وَاسْأَلْهُمْ عَنِ الْقَرْيَةِ الَّتِي كَانَتْ حَاضِرَةَ الْبَحْرِ إِذْ يَعْدُونَ فِي السَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا يَفْسُقُونَ', NULL, 'And ask them about the town that was by the sea - when they transgressed in [the matter of] the sabbath - when their fish came to them openly on their sabbath day, and the day they had no sabbath they did not come to them. Thus did We give them trial because they were defiantly disobedient.', 'Dan bertanyalah kepada mereka (wahai Muhammad) mengenai (penduduk) bandar yang letaknya di tepi laut, semasa mereka melanggar larangan pada hari Sabtu, ketika datang kepada mereka pada hari Sabtu itu ikan-ikan (yang menjadi cubaan kepada) mereka, yang kelihatan timbul di muka air; sedang pada hari-hari lain, ikan-ikan itu tidak pula datang kepada mereka. Demikianlah kami menguji mereka (dengan cubaan itu) kerana mereka sentiasa berlaku fasik.', FALSE, NULL, NULL, 171, 9, 68, 142, FALSE, 0, NULL),
(7, 164, 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا اللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', NULL, 'And when a community among them said, "Why do you advise [or warn] a people whom Allāh is [about] to destroy or to punish with a severe punishment?" they [the advisors] said, "To be absolved before your Lord and perhaps they may fear Him."', 'Dan (ingatlah) ketika segolongan di antara mereka berkata: “Mengapa kamu menasihati kaum yang Allah akan membinasakan mereka atau mengazabkan mereka dengan azab yang amat berat?” Orang-orang (yang memberi nasihat) itu menjawab: “(Nasihat itu ialah) untuk melepaskan diri dari bersalah kepada Tuhan kamu, dan supaya mereka bertaqwa”.', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 165, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', 'فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ أَنجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ وَأَخَذْنَا الَّذِينَ ظَلَمُوا بِعَذَابٍ بَئِيسٍ بِمَا كَانُوا يَفْسُقُونَ', NULL, 'And when they [i.e., those advised] forgot that by which they had been reminded, We saved those who had forbidden evil and seized those who wronged, with a wretched punishment, because they were defiantly disobeying.', 'Maka ketika mereka melupakan (tidak menghiraukan) apa yang telah diperingatkan kepada mereka, Kami selamatkan orang-orang yang melarang daripada perbuatan jahat itu, dan Kami timpakan orang-orang yang zalim dengan azab seksa yang amat berat, disebabkan mereka berlaku fasik (derhaka).', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 166, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ', NULL, 'So when they were insolent about that which they had been forbidden, We said to them, "Be apes, despised."', 'Maka setelah mereka berlaku sombong takbur (tidak mengambil indah) kepada apa yang telah dilarang mereka melakukannya, Kami katakan kepada mereka: “Jadilah kamu kera yang hina”.', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 167, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ', 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ الْقِيَامَةِ مَن يَسُومُهُمْ سُوءَ الْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ', NULL, 'And [mention] when your Lord declared that He would surely [continue to] send upon them until the Day of Resurrection those who would afflict them with the worst torment. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.', 'Dan (ingatlah wahai Muhammad) ketika Tuhanmu memberitahu: Bahawa sesungguhnya Ia akan menghantarkan kepada kaum Yahudi itu, (terus menerus) hingga hari kiamat, kaum-kaum yang akan menimpakan mereka dengan azab sengsara yang seburuk-buruknya (disebabkan kejahatan dan kekufuran mereka). Sesungguhnya Tuhanmu amat cepat azab seksaNya, dan sesungguhnya Dia juga Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 168, 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًا مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', 'وَقَطَّعْنَاهُمْ فِي الْأَرْضِ أُمَمًا مِّنْهُمُ الصَّالِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَاهُم بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience].', 'Dan Kami pecah-pecahkan mereka (kaum Yahudi itu) berpuak-puak (yang bertaburan di merata-rata) dunia ini. Di antara mereka ada yang soleh dan di antaranya juga yang tidak demikian. Dan kami uji mereka dengan nikmat pemberian yang baik-baik dan bala bencana yang buruk, supaya mereka kembali (bertaubat).', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 169, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'فَخَلَفَ مِن بَعْدِهِمْ خَلْفٌ وَرِثُوا الْكِتَابَ يَأْخُذُونَ عَرَضَ هَٰذَا الْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَاقُ الْكِتَابِ أَن لَّا يَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ وَدَرَسُوا مَا فِيهِ وَالدَّارُ الْآخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', NULL, 'And there followed them successors who inherited the Scripture [while] taking the commodities of this lower life and saying, "It will be forgiven for us." And if an offer like it comes to them, they will [again] take it. Was not the covenant of the Scripture [i.e., the Torah] taken from them that they would not say about Allāh except the truth, and they studied what was in it? And the home of the Hereafter is better for those who fear Allāh, so will you not use reason?', 'Maka mereka kemudiannya digantikan oleh keturunan-keturunan yang jahat yang mewarisi Kitab (Taurat). Mereka mengambil kebendaan yang hina di dunia ini sambil berkata: “Akan diampunkan kelak dosa kami” Padahal jika datang kepada mereka kebendaan yang hina seperti itu mereka akan mengambilnya lagi. Bukankah telah diambil perjanjian setia daripada mereka di dalam kitab Taurat bahawa mereka tidak memperkatakan terhadap Allah melainkan yang benar? Dan mereka pula telah mempelajari apa yang terkandung di dalamnya? Dan juga (mereka mengetahui bahawa) negeri akhirat itu lebih baik bagi orang-orang yang bertaqwa. Tidakkah kamu mahu mengerti?', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 170, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', 'وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلَاةَ إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ', NULL, 'But those who hold fast to the Book [i.e., the Qur’ān] and establish prayer - indeed, We will not allow to be lost the reward of the reformers.', 'Dan orang-orang yang berpegang teguh dengan Kitab Allah serta mendirikan sembahyang, sesungguhnya Kami tidak akan menghilangkan pahala orang-orang yang berusaha memperbaiki (keadaan hidupnya).', FALSE, NULL, NULL, 172, 9, 68, 142, FALSE, 0, NULL),
(7, 171, 'وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'وَإِذْ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَأَنَّهُ ظُلَّةٌ وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', NULL, 'And [mention] when We raised the mountain above them as if it was a dark cloud and they were certain that it would fall upon them, [and Allāh said], "Take what We have given you with determination and remember what is in it that you might fear Allāh."', 'Dan (ingatlah wahai Muhammad) ketika Kami mengangkat gunung (Tursina) ke atas mereka (Bani Israil) seolah-olah gunung itu awan (yang menaungi mereka) dan mereka yakin bahawa gunung itu akan jatuh menimpa mereka, (sambil Kami berfirman kepada mereka): “Terimalah dengan bersungguh-sungguh (Kitab Taurat) yang telah Kami berikan kepada kamu dan ingatlah (amalkanlah) apa yang terkandung di dalamnya, supaya kamu menjadi orang-orang yang bertaqwa”', FALSE, NULL, NULL, 173, 9, 69, 142, FALSE, 0, NULL),
(7, 172, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا۟ بَلَىٰ شَهِدْنَآ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', 'وَإِذْ أَخَذَ رَبُّكَ مِن بَنِي آدَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَىٰ شَهِدْنَا أَن تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَافِلِينَ', NULL, 'And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], "Am I not your Lord?" They said, "Yes, we have testified." [This] - lest you should say on the Day of Resurrection, "Indeed, we were of this unaware."', 'Dan (ingatlah wahai Muhammad) ketika Tuhanmu mengeluarkan zuriat anak-anak Adam (turun-temurun) dari (tulang) belakang mereka, dan Ia jadikan mereka saksi terhadap diri mereka sendiri, (sambil Ia bertanya dengan firmanNya): “Bukankah Aku tuhan kamu?” Mereka semua menjawab: “Benar (Engkaulah Tuhan kami), kami menjadi saksi”. Yang demikian supaya kamu tidak berkata pada hari kiamat kelak: “Sesungguhnya kami adalah lalai (tidak diberi peringatan) tentang (hakikat tauhid) ini”.', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 173, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', 'أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّن بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ', NULL, 'Or [lest] you say, "It was only that our fathers associated [others in worship] with Allāh before, and we were but descendants after them. Then would You destroy us for what the falsifiers have done?"', 'Atau supaya kamu tidak mengatakan: “Sesungguhnya ibu bapa kamilah yang melakukan syirik dahulu sedang kami ialah keturunan (mereka) yang datang kemudian daripada mereka. Oleh itu, patutkah Engkau (wahai Tuhan kami) hendak membinasakan kami disebabkan perbuatan orang-orang yang sesat itu?”', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'وَكَذَٰلِكَ نُفَصِّلُ الْآيَاتِ وَلَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And thus do We [explain in] detail the verses, and perhaps they will return.', 'Dan demikianlah Kami menjelaskan ayat-ayat keterangan Kami satu persatu (supaya nyata segala kebenaran), dan supaya mereka kembali (kepada kebenaran).', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 175, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 'وَاتْلُ عَلَيْهِمْ نَبَأَ الَّذِي آتَيْنَاهُ آيَاتِنَا فَانسَلَخَ مِنْهَا فَأَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاوِينَ', NULL, 'And recite to them, [O Muḥammad], the news of him to whom We gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators.', 'Dan bacakanlah kepada mereka (wahai Muhammad), khabar berita seorang yang kami beri kepadanya (pengetahuan mengenai) ayat-ayat (Kitab) Kami. kemudian ia menjadikan dirinya terkeluar dari mematuhinya, lalu ia diikuti oleh Syaitan (dengan godaannya), maka menjadilah dari orang-orang yang sesat.', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'وَلَوْ شِئْنَا لَرَفَعْنَاهُ بِهَا وَلَٰكِنَّهُ أَخْلَدَ إِلَى الْأَرْضِ وَاتَّبَعَ هَوَاهُ فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِنَا فَاقْصُصِ الْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', NULL, 'And if We had willed, We could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought.', 'Dan kalau Kami kehendaki nescaya Kami tinggikan pangkatnya dengan (sebab mengamalkan) ayat-ayat itu. Tetapi ia bermati-mati cenderung kepada dunia dan menurut hawa nafsunya; maka bandingannya adalah seperti anjing, jika engkau menghalaunya: ia menghulurkan lidahnya termengah-mengah, dan jika engkau membiarkannya: ia juga menghulurkan lidahnya termengah-mengah. Demikianlah bandingan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah kisah-kisah itu supaya mereka berfikir.', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 177, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', 'سَاءَ مَثَلًا الْقَوْمُ الَّذِينَ كَذَّبُوا بِآيَاتِنَا وَأَنفُسَهُمْ كَانُوا يَظْلِمُونَ', NULL, 'How evil an example [is that of] the people who denied Our signs and used to wrong themselves.', 'Amatlah buruknya bandingan orang-orang yang mendustakan ayat-ayat Kami, dan mereka pula berlaku zalim kepada diri merela sendiri.', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 178, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'مَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِي وَمَن يُضْلِلْ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, 'Whoever Allāh guides - he is the [rightly] guided; and whoever He sends astray - it is those who are the losers.', 'Sesiapa yang diberi petunjuk oleh Allah (dengan sebab persediaannya) maka dia lah yang beroleh petunjuk; dan sesiapa yang disesatkan oleh Allah (dengan sebab keingkarannya) maka merekalah orang-orang yang rugi.', FALSE, NULL, NULL, 173, 9, 69, 143, FALSE, 0, NULL),
(7, 179, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ الْجِنِّ وَالْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لَّا يَسْمَعُونَ بِهَا أُولَٰئِكَ كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ أُولَٰئِكَ هُمُ الْغَافِلُونَ', NULL, 'And We have certainly created for Hell many of the jinn and mankind. They have hearts with which they do not understand, they have eyes with which they do not see, and they have ears with which they do not hear. Those are like livestock; rather, they are more astray. It is they who are the heedless.', 'Dan sesungguhnya Kami jadikan untuk neraka jahanam banyak dari jin dan manusia yang mempunyai hati (tetapi) tidak mahu memahami dengannya (ayat-ayat Allah), dan yang mempunyai mata (tetapi) tidak mahu melihat dengannya (bukti keesaan Allah) dan yang mempunyai telinga (tetapi) tidak mahu mendengar dengannya (ajaran dan nasihat); mereka itu seperti binatang ternak, bahkan mereka lebih sesat lagi; mereka itulah orang-orang yang lalai.', FALSE, NULL, NULL, 174, 9, 69, 143, FALSE, 0, NULL),
(7, 180, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', 'وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَىٰ فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ', NULL, 'And to Allāh belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing.', 'Dan Allah mempunyai nama-nama yang baik (yang mulia), maka serulah (dan berdoalah) kepadaNya dengan menyebut nama-nama itu, dan pulaukanlah orang-orang yang berpaling dari kebenaran dalam masa menggunakan nama-namaNya. Mereka akan mendapat balasan mengenai apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 174, 9, 69, 143, FALSE, 0, NULL),
(7, 181, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'وَمِمَّنْ خَلَقْنَا أُمَّةٌ يَهْدُونَ بِالْحَقِّ وَبِهِ يَعْدِلُونَ', NULL, 'And among those We created is a community which guides by truth and thereby establishes justice.', 'Dan di antara orang-orang yang Kami ciptakan itu, ada satu umat yang memberi petunjuk dengan kebenaran, dan dengannya mereka menjalankan keadilan.', FALSE, NULL, NULL, 174, 9, 69, 143, FALSE, 0, NULL),
(7, 182, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'وَالَّذِينَ كَذَّبُوا بِآيَاتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', NULL, 'But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know.', 'Dan orang-orang yang mendustakan ayat-ayat Kami, Kami akan menarik menarik mereka sedikit demi sedikit (ke jurang kebinasaan), menurut cara yang mereka tidak mengetahuinya.', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 183, 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', 'وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ', NULL, 'And I will give them time. Indeed, My plan is firm.', 'Dan Aku memberi tempoh kepada mereka; sesungguhnya rancangan balasanKu amatlah teguh.', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 184, 'أَوَلَمْ يَتَفَكَّرُوا۟ مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', 'أَوَلَمْ يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', NULL, 'Then do they not give thought? There is in their companion [i.e., Muḥammad (ﷺ)] no madness. He is not but a clear warner.', 'Patutkah mereka (ingkar dan) tidak mahu memikirkan (dengan fikiran yang siuman bahawa) sahabat mereka (Muhammad) tidak sekali-kali mengidap penyakit gila (sebagaimana yang mereka tuduh itu), bahkan ia hanyalah seorang (Pesuruh Allah) yang memberi amaran yang jelas.', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 185, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'أَوَلَمْ يَنظُرُوا فِي مَلَكُوتِ السَّمَاوَاتِ وَالْأَرْضِ وَمَا خَلَقَ اللَّهُ مِن شَيْءٍ وَأَنْ عَسَىٰ أَن يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ', NULL, 'Do they not look into the realm of the heavens and the earth and everything that Allāh has created and [think] that perhaps their appointed time has come near? So in what statement [i.e., message] hereafter will they believe?', 'Patutkah mereka (membutakan mata) tidak mahu memperhatikan alam langit dan bumi dan segala yang diciptakan oleh Allah, dan (memikirkan) bahawa harus telah dekat ajal kebinasaan mereka? Maka kepada perkataan yang mana lagi sesudah (datangnya Kalamullah Al-Quran) itu mereka mahu beriman?', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 186, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'مَن يُضْلِلِ اللَّهُ فَلَا هَادِيَ لَهُ وَيَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ', NULL, 'Whoever Allāh sends astray - there is no guide for him. And He leaves them in their transgression, wandering blindly.', 'Sesiapa yang disesatkan oleh Allah (kerana keingkarannya), maka tidak ada sesiapa pun yang akan dapat memberi petunjuk kepadanya; dan Allah membiarkan mereka meraba-raba (dengan bingung) dalam kesesatan mereka.', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 187, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّي لَا يُجَلِّيهَا لِوَقْتِهَا إِلَّا هُوَ ثَقُلَتْ فِي السَّمَاوَاتِ وَالْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ اللَّهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'They ask you, [O Muḥammad], about the Hour: when is its arrival? Say, "Its knowledge is only with my Lord. None will reveal its time except Him. It lays heavily upon the heavens and the earth. It will not come upon you except unexpectedly." They ask you as if you are familiar with it. Say, "Its knowledge is only with Allāh, but most of the people do not know."', 'Mereka bertanya kepadamu (wahai Muhammad) tentang hari kiamat: “Bilakah masa datangnya?” Katakanlah: “Sesungguhnya pengetahuan mengenainya hanyalah ada di sisi Tuhanku, tidak ada sesiapa pun yang dapat menerangkan kedatangannya pada waktunya melainkan Dia. (Huru-hara) hari kiamat itu amatlah berat (menggerunkan makhluk-makhluk yang ada) di langit dan di bumi; ia tidak datang kepada kamu melainkan secara mengejut”. Mereka bertanya kepadamu seolah-olah engkau sedia mengetahuinya. Katakanlah: “Sesungguhnya pengetahuan mengenai hari kiamat itu adalah di sisi Allah, tetapi kebanyakan manusia tidak mengetahui”.', FALSE, NULL, NULL, 174, 9, 69, 144, FALSE, 0, NULL),
(7, 188, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', 'قُل لَّا أَمْلِكُ لِنَفْسِي نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لَاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'Say, "I hold not for myself [the power of] benefit or harm, except what Allāh has willed. And if I knew the unseen, I could have acquired much wealth, and no harm would have touched me. I am not except a warner and a bringer of good tidings to a people who believe."', 'Katakanlah: “Aku tidak berkuasa mendatangkan manfaat bagi diriku dan tidak dapat menolak mudarat kecuali apa yang dikehendaki Allah. Dan kalau aku mengetahui perkara-perkara yang ghaib, tentulah aku akan mengumpulkan dengan banyaknya benda-benda yang mendatangkan faedah dan (tentulah) aku tidak ditimpa kesusahan. Aku ini tidak lain hanyalah (Pesuruh Allah) yang memberi amaran (bagi orang-orang yang ingkar) dan membawa berita gembira bagi orang-orang yang beriman”.', FALSE, NULL, NULL, 175, 9, 69, 144, FALSE, 0, NULL),
(7, 189, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'هُوَ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّاهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِ فَلَمَّا أَثْقَلَت دَّعَوَا اللَّهَ رَبَّهُمَا لَئِنْ آتَيْتَنَا صَالِحًا لَّنَكُونَنَّ مِنَ الشَّاكِرِينَ', NULL, 'It is He who created you from one soul and created from it its mate that he might dwell in security with her. And when he [i.e., man] covers her, she carries a light burden [i.e., a pregnancy] and continues therein. And when it becomes heavy, they both invoke Allāh, their Lord, "If You should give us a good [child], we will surely be among the grateful."', 'Dia lah (Allah) yang menciptakan kamu semua dari (hakikat) diri yang satu, dan Ia mengadakan daripada hakikat itu pasangannya (diri suami isteri), untuk bersenang hati dan hidup mesra yang satu kepada yang lain. Ketika suami mencampuri isterinya, mengandunglah ia dengan kandungan yang ringan, serta teruslah ia dengan keadaan itu (ke suatu waktu). Kemudian ketika ia merasa berat (dan menaruh bimbang) berdoalah suami isteri itu kepada Tuhan mereka (dengan berkata): “Sesungguhnya jika Engkau (wahai Tuhan kami) mengurniakan kami nikmat yang baik, tentulah kami menjadi orang-orang yang bersyukur”.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 190, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا فَتَعَالَى اللَّهُ عَمَّا يُشْرِكُونَ', NULL, 'But when He gives them a good [child], they ascribe partners to Him concerning that which He has given them. Exalted is Allāh above what they associate with Him.', 'Kemudian ketika Allah mengurniakan kepada keduanya nikmat yang baik (sebagaimana yang mereka pohonkan), mereka berdua menjadikan sekutu bagi Allah dalam urusan wujudnya nikmat yang dikurniakan Allah kepada mereka. Maha Suci Allah dari apa yang mereka sekutukan itu.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 191, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ', 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْئًا وَهُمْ يُخْلَقُونَ', NULL, 'Do they associate with Him those who create nothing and they are [themselves] created?', 'Patutkah mereka sekutukan Allah dengan benda-benda yang tidak dapat menciptakan sesuatupun, sedang benda-benda itu sendiri diciptakan?', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 192, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَا أَنفُسَهُمْ يَنصُرُونَ', NULL, 'And they [i.e., the false deities] are unable to [give] them help, nor can they help themselves.', 'Dan benda-benda itu tidak dapat menolong mereka, dan tidak juga dapat menolong dirinya sendiri.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 193, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', 'وَإِن تَدْعُوهُمْ إِلَى الْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَاءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَامِتُونَ', NULL, 'And if you [believers] invite them to guidance, they will not follow you. It is all the same for you whether you invite them or you are silent.', 'Dan jika kamu (hai kaum musyrik) menyeru benda-benda itu untuk memperoleh petunjuk (daripadanya), mereka tidak dapat menurut (menyampaikan hajat) kamu; sama sahaja bagi kamu, sama ada kamu menyerunya atau mendiamkan diri.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 194, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ عِبَادٌ أَمْثَالُكُمْ فَادْعُوهُمْ فَلْيَسْتَجِيبُوا لَكُمْ إِن كُنتُمْ صَادِقِينَ', NULL, 'Indeed, those you [polytheists] call upon besides Allāh are servants [i.e., creations] like you. So call upon them and let them respond to you, if you should be truthful.', 'Sesungguhnya benda-benda yang kamu seru selain Allah adalah makhluk-makhluk seperti kamu. Oleh itu, (cubalah) menyerunya supaya benda-benda itu dapat memperkenankan permohonan kamu, kalau betul kamu orang-orang yang benar.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 195, 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَا أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَا أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَا أَمْ لَهُمْ آذَانٌ يَسْمَعُونَ بِهَا قُلِ ادْعُوا شُرَكَاءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', NULL, 'Do they have feet by which they walk? Or do they have hands by which they strike? Or do they have eyes by which they see? Or do they have ears by which they hear? Say, [O Muḥammad], "Call your ''partners'' and then conspire against me and give me no respite.', 'Adakah benda-benda (yang kamu sembah) itu mempunyai kaki yang mereka dapat berjalan dengannya, atau adakah mereka mempunyai tangan yang mereka dapat memegang (menyeksa) dengannya, atau adakah mereka mempunyai mata yang mereka dapat melihat dengannya, atau adakah mereka mempunyai telinga yang mereka dapat mendengar dengannya? Katakanlah (wahai Muhammad): “Panggilah benda-benda yang kamu jadikan sekutu Allah, kemudian kamu semua jalankan tipu daya terhadapku, serta jangan pula kamu bertangguh lagi.', FALSE, NULL, NULL, 175, 9, 70, 145, FALSE, 0, NULL),
(7, 196, 'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 'إِنَّ وَلِيِّيَ اللَّهُ الَّذِي نَزَّلَ الْكِتَابَ وَهُوَ يَتَوَلَّى الصَّالِحِينَ', NULL, 'Indeed, my protector is Allāh, who has sent down the Book; and He is an ally to the righteous.', '“Sesungguhnya pelindungku ialah Allah yang telah menurunkan kitab (Al-Quran), dan Dia lah jua yang menolong dan memelihara orang-orang yang berbuat kebaikan”', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 197, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'وَالَّذِينَ تَدْعُونَ مِن دُونِهِ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَا أَنفُسَهُمْ يَنصُرُونَ', NULL, 'And those you call upon besides Him are unable to help you, nor can they help themselves."', 'Dan benda-benda yang kamu sembah selain Allah, tidak akan dapat menolong kamu, bahkan tidak dapat menolong dirinya sendiri.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 198, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', 'وَإِن تَدْعُوهُمْ إِلَى الْهُدَىٰ لَا يَسْمَعُوا وَتَرَاهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', NULL, 'And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see.', 'Dan jika kamu menyeru benda-benda (yang kamu sembah) itu untuk mendapat petunjuk (daripadanya), mereka tidak dapat mendengarnya; dan engkau nampak benda-benda itu memandangmu padahal mereka tidak melihat.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 199, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', 'خُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَأَعْرِضْ عَنِ الْجَاهِلِينَ', NULL, 'Take what is given freely, enjoin what is good, and turn away from the ignorant.', 'Terimalah apa yang mudah engkau lakukan, dan suruhlah dengan perkara yang baik, serta berpalinglah (jangan dihiraukan) orang-orang yang jahil (yang degil dengan kejahilannya).', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 200, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', 'وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'And if an evil suggestion comes to you from Satan, then seek refuge in Allāh. Indeed, He is Hearing and Knowing.', 'Dan jika engkau dihasut oleh sesuatu hasutan dari Syaitan, maka mintalah perlindungan kepada Allah, sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 201, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', 'إِنَّ الَّذِينَ اتَّقَوْا إِذَا مَسَّهُمْ طَائِفٌ مِّنَ الشَّيْطَانِ تَذَكَّرُوا فَإِذَا هُم مُّبْصِرُونَ', NULL, 'Indeed, those who fear Allāh - when an impulse touches them from Satan, they remember [Him] and at once they have insight.', 'Sesungguhnya orang-orang yang bertaqwa, apabila mereka disentuh oleh sesuatu imbasan hasutan dari Syaitan, mereka ingat (kepada ajaran Allah) maka dengan itu mereka nampak (jalan yang benar).', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 202, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', 'وَإِخْوَانُهُمْ يَمُدُّونَهُمْ فِي الْغَيِّ ثُمَّ لَا يُقْصِرُونَ', NULL, 'But their brothers - they [i.e., the devils] increase them in error; then they do not stop short.', 'Sedang saudara (pengikut) Syaitan-syaitan, dibantu oleh Syaitan-syaitan itu dalam melakukan kesesatan, kemudian mereka tidak berhenti-henti (melakukan perbuatan yang sesat lagi menyesatkan itu).', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 203, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', 'وَإِذَا لَمْ تَأْتِهِم بِآيَةٍ قَالُوا لَوْلَا اجْتَبَيْتَهَا قُلْ إِنَّمَا أَتَّبِعُ مَا يُوحَىٰ إِلَيَّ مِن رَّبِّي هَٰذَا بَصَائِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'And when you, [O Muḥammad], do not bring them a sign [i.e., miracle], they say, "Why have you not contrived it?" Say, "I only follow what is revealed to me from my Lord. This [Qur’ān] is enlightenment from your Lord and guidance and mercy for a people who believe."', 'Dan apabila engkau (wahai Muhammad) tidak membawa kepada mereka sesuatu ayat Al-Quran (sebagaimana yang mereka kehendaki), berkatalah mereka (secara mengejek): “Mengapa engkau tidak bersusah payah membuat sendiri akan ayat itu?” Katakanlah: “Sesungguhnya aku hanya menurut apa yang diwahyukan kepadaku dari Tuhanku. Al-Quran ini ialah panduan-panduan - yang membuka hati - dari Tuhan kamu, dan petunjuk serta menjadi rahmat bagi orang-orang yang beriman”.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 204, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'So when the Qur’ān is recited, then listen to it and pay attention that you may receive mercy.', 'Dan apabila Al-Quran itu dibacakan, maka dengarlah akan dia serta diamlah (dengan sebulat-bulat ingatan untuk mendengarnya), supaya kamu beroleh rahmat.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 205, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 'وَاذْكُر رَّبَّكَ فِي نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْآصَالِ وَلَا تَكُن مِّنَ الْغَافِلِينَ', NULL, 'And remember your Lord within yourself in humility and in fear without being apparent in speech - in the mornings and the evenings. And do not be among the heedless.', 'Dan sebutlah serta ingatlah akan Tuhanmu dalam hatimu, dengan merendah diri serta dengan perasaan takut (melanggar perintahnya), dan dengan tidak pula menyaringkan suara, pada waktu pagi dan petang dan janganlah engkau menjadi dari orang-orang yang lalai.', FALSE, NULL, NULL, 176, 9, 70, 145, FALSE, 0, NULL),
(7, 206, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ', 'إِنَّ الَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ وَيُسَبِّحُونَهُ وَلَهُ يَسْجُدُونَ', NULL, 'Indeed, those who are near your Lord [i.e., the angels] are not prevented by arrogance from His worship, and they exalt Him, and to Him they prostrate.', 'Sesungguhnya mereka (malaikat) yang ada di sisi Tuhanmu tidak bersikap angkuh (ingkar) daripada beribadat kepadaNya, dan mereka pula bertasbih bagiNya, dan kepadaNyalah jua mereka sujud.', FALSE, NULL, NULL, 176, 9, 70, 145, TRUE, 0, NULL),
(8, 1, 'يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', 'يسالونك عن الانفال قل الانفال لله والرسول فاتقوا الله واصلحوا ذات بينكم واطيعوا الله ورسوله ان كنتم مؤمنين', NULL, 'They ask you, [O Muḥammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allāh and the Messenger." So fear Allāh and amend that which is between you and obey Allāh and His Messenger, if you should be believers.', 'Mereka bertanya kepadamu (wahai Muhammad) tentang harta rampasan perang. Katakanlah: “Harta rampasan perang itu (terserah) bagi Allah dan bagi RasulNya (untuk menentukan pembahagiannya). Oleh itu, bertaqwalah kamu kepada Allah dan perbaikilah keadaan perhubungan di antara kamu, serta taatlah kepada Allah dan RasulNya, jika betul kamu orang-orang yang beriman”.', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 18, NULL),
(8, 2, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَـٰتُهُۥ زَادَتْهُمْ إِيمَـٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'انما المؤمنون الذين اذا ذكر الله وجلت قلوبهم واذا تليت عليهم اياته زادتهم ايمانا وعلى ربهم يتوكلون', NULL, 'The believers are only those who, when Allāh is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -', 'Sesungguhnya orang-orang yang beriman itu (yang sempurna imannya) ialah mereka yang apabila disebut nama Allah (dan sifat-sifatNya) gementarlah hati mereka; dan apabila dibacakan kepada mereka ayat-ayatNya, menjadikan mereka bertambah iman, dan kepada Tuhan mereka jualah mereka berserah.', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 17, NULL),
(8, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', 'الذين يقيمون الصلاة ومما رزقناهم ينفقون', NULL, 'The ones who establish prayer, and from what We have provided them, they spend.', 'Iaitu orang-orang yang mendirikan sembahyang dan yang mendermakan sebahagian dari apa yang Kami kurniakan kepada mereka.', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 6, NULL),
(8, 4, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُمْ دَرَجَـٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'اولئك هم المؤمنون حقا لهم درجات عند ربهم ومغفرة ورزق كريم', NULL, 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.', 'Merekalah orang-orang yang beriman dengan sebenar-benarnya. Mereka akan mendapat pangkat-pangkat yang tinggi di sisi Tuhan mereka dan keampunan serta limpah kurnia yang mulia (di Syurga).', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 11, NULL),
(8, 5, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَـٰرِهُونَ', 'كما اخرجك ربك من بيتك بالحق وان فريقا من المؤمنين لكارهون', NULL, '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,', 'Sebagaimana (harta rampasan perang ditentukan pembahagiannya dengan kebenaran, maka) Tuhanmu (wahai Muhammad) mengeluarkanmu dari rumahmu (untuk pergi berperang) dengan kebenaran juga, sedang sebahagian dari orang-orang yang beriman itu (sebenarnya) tidak suka (turut berjuang).', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 11, NULL),
(8, 6, 'يُجَـٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 'يجادلونك في الحق بعدما تبين كانما يساقون الى الموت وهم ينظرون', NULL, 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.', 'Mereka membantahmu tentang kebenaran (berjihad) setelah nyata (kepada mereka kemenangan yang engkau janjikan), seolah-olah mereka dihalau kepada kematian, sedang mereka melihat (sebab-sebabnya).', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 12, NULL),
(8, 7, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَـٰفِرِينَ', 'واذ يعدكم الله احدى الطائفتين انها لكم وتودون ان غير ذات الشوكة تكون لكم ويريد الله ان يحق الحق بكلماته ويقطع دابر الكافرين', NULL, '[Remember, O believers], when Allāh promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allāh intended to establish the truth by His words and to eliminate the disbelievers', 'Dan (ingatlah) ketika Allah menjanjikan kepada kamu salah satu dari dua angkatan, menjadi untuk kamu (menghadapinya), sedang kamu suka kiranya (angkatan perniagaan) bukan angkatan (perang) yang mempunyai kekuatan itu yang dijadikan untuk kamu (menghadapinya). Padahal Allah menghendaki untuk menetapkan yang benar (ugama Islam) dengan Kalimah-kalimahNya, dan untuk membinasakan kaum yang kafir seluruhnya;', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 23, NULL),
(8, 8, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَـٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'ليحق الحق ويبطل الباطل ولو كره المجرمون', NULL, 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.', 'Supaya Allah menegakkan yang benar itu dan menghapuskan yang salah (kufur dan syirik), sekalipun golongan (kafir musyrik) yang berdosa itu tidak menyukainya.', FALSE, NULL, NULL, 177, 9, 71, 146, FALSE, 7, NULL),
(8, 9, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُرْدِفِينَ', 'اذ تستغيثون ربكم فاستجاب لكم اني ممدكم بالف من الملائكة مردفين', NULL, '[Remember] when you were asking help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."', '(Ingatlah) ketika kamu memohon pertolongan kepada tuhan kamu, lalu Ia perkenankan permohonan kamu (dengan firmanNya): “Sesungguhnya Aku akan membantu kamu dengan seribu (bala tentera) dari malaikat yang datang berturut-turut.', FALSE, NULL, NULL, 178, 9, 71, 146, FALSE, 11, NULL),
(8, 10, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'وما جعله الله الا بشرى ولتطمئن به قلوبكم وما النصر الا من عند الله ان الله عزيز حكيم', NULL, 'And Allāh made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allāh. Indeed, Allāh is Exalted in Might and Wise.', 'Dan Allah tidak menjadikan (bantuan malaikat) itu melainkan sebagai berita gembira dan supaya hati kamu tenang tenteram dengannya. Dan kemenangan itu pula hanyalah dari sisi Allah. Sesungguhnya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 178, 9, 71, 146, FALSE, 18, NULL),
(8, 11, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَـٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 'اذ يغشيكم النعاس امنة منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الاقدام', NULL, '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.', '(Ingatlah) ketika kamu diliputi perasaan mengantuk sebagai satu (pemberian) aman dari Allah (untuk menghapuskan kecemasan kamu). Dan (ingatlah ketika) Ia menurunkan kepada kamu hujan dari langit untuk mensucikan kamu dengannya dan menghapuskan dari kamu gangguan Syaitan, dan juga untuk menguatkan hati kamu dan menetapkan dengannya tapak pendirian (kamu di medan perjuangan).', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 22, NULL),
(8, 12, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَـٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ', 'اذ يوحي ربك الى الملائكة اني معكم فثبتوا الذين امنوا سالقي في قلوب الذين كفروا الرعب فاضربوا فوق الاعناق واضربوا منهم كل بنان', NULL, '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."', '(Ingatlah) ketika Tuhanmu wahyukan kepada malaikat: “Sesungguhnya Aku menyertai kamu (memberi pertolongan), maka tetapkanlah (hati) orang-orang yang beriman. Aku akan mengisi hati orang-orang yang kafir dengan perasaan gerun; oleh itu, pancunglah leher mereka (musuh) dan potonglah tiap-tiap anggota mereka”', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 23, NULL),
(8, 13, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ذلك بانهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فان الله شديد العقاب', NULL, 'That is because they opposed Allāh and His Messenger. And whoever opposes Allāh and His Messenger - indeed, Allāh is severe in penalty.', '(Perintah) yang demikian ialah kerana sesungguhnya mereka menentang Allah dan RasulNya; dan sesiapa yang menentang Allah dan RasulNya, maka sesungguhnya Allah Maha berat azab seksaNya.', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 13, NULL),
(8, 14, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَـٰفِرِينَ عَذَابَ ٱلنَّارِ', 'ذلكم فذوقوه وان للكافرين عذاب النار', NULL, '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.', 'Itulah (azab dunia) maka rasalah dia (hai orang-orang kafir). Sesungguhnya orang-orang yang kafir disediakan baginya azab neraka (di akhirat).', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 6, NULL),
(8, 15, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', 'يا ايها الذين امنوا اذا لقيتم الذين كفروا زحفا فلا تولوهم الادبار', NULL, 'O you who have believed, when you meet those who disbelieve advancing [in battle], do not turn to them your backs [in flight].', 'Wahai orang-orang yang beriman! Apabila kamu bertemu dengan orang-orang kafir yang sedang mara menyerang, maka janganlah kamu berpaling undur dari menentang mereka.', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 11, NULL),
(8, 16, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'ومن يولهم يومئذ دبره الا متحرفا لقتال او متحيزا الى فئة فقد باء بغضب من الله وماواه جهنم وبئس المصير', NULL, 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allāh, and his refuge is Hell - and wretched is the destination.', 'Dan sesiapa berpaling undur dari menentang mereka pada ketika itu - kecuali ia bergerak ke arah lain (untuk menjalankan tipu muslihat) peperangan, atau hendak menyatukan diri dengan pasukan yang lain - maka sesungguhnya ia tetaplah mendapat kemurkaan dari Allah, dan tempatnya ialah neraka jahanam; sedang neraka jahanam ialah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 178, 9, 71, 147, FALSE, 20, NULL),
(8, 17, 'فَلَمْ تَقْتُلُوهُمْ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'فلم تقتلوهم ولكن الله قتلهم وما رميت اذ رميت ولكن الله رمى وليبلي المؤمنين منه بلاء حسنا ان الله سميع عليم', NULL, 'And you did not kill them, but it was Allāh who killed them. And you threw not, [O Muḥammad], when you threw, but it was Allāh who threw that He might test the believers with a good test. Indeed, Allāh is Hearing and Knowing.', 'Maka bukanlah kamu yang membunuh mereka, akan tetapi Allah jualah yang menyebabkan pembunuhan mereka. Dan bukanlah engkau (wahai Muhammad) yang melempar ketika engkau melempar, akan tetapi Allah jualah yang melempar (untuk membinasakan orang-orang kafir), dan untuk mengurniakan orang-orang yang beriman dengan pengurniaan yang baik (kemenangan) daripadaNya. Sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 179, 9, 71, 147, FALSE, 21, NULL),
(8, 18, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَـٰفِرِينَ', 'ذلكم وان الله موهن كيد الكافرين', NULL, 'That [is so], and [also] that Allāh will weaken the plot of the disbelievers.', 'Demikianlah (caranya nikmat yang dikurniakanNya kepada kamu), dan sesungguhnya Allah sentiasa melumpuhkan tipu daya orang-orang yang kafir.', FALSE, NULL, NULL, 179, 9, 71, 147, FALSE, 6, NULL),
(8, 19, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 'ان تستفتحوا فقد جاءكم الفتح وان تنتهوا فهو خير لكم وان تعودوا نعد ولن تغني عنكم فئتكم شيئا ولو كثرت وان الله مع المؤمنين', NULL, 'If you [disbelievers] seek the decision [i.e., victory] - the decision [i.e., defeat] has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allāh is with the believers.', 'Jika kamu (hai orang-orang musyrik) memohon supaya diberi kemenangan (bagi pihak yang benar) maka sesungguhnya kemenangan (yang kamu pohonkan) itu telah datang (dan disaksikan oleh) kamu; dan jika kamu berhenti (daripada memusuhi Nabi Muhammad, s.a.w) maka yang demikian amat baik bagi kamu, dan jika kamu kembali (memusuhinya), Kami juga kembali (menolongnya mengalahkan kamu); dan golongan (angkatan perang) kamu tidak sekali-kali akan dapat menyelamatkan kamu sedikitpun, sekalipun ia lebih ramai; dan (yang demikian itu adalah kerana) sesungguhnya Allah beserta orang-orang yang beriman.', FALSE, NULL, NULL, 179, 9, 71, 147, FALSE, 24, NULL),
(8, 20, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', 'يا ايها الذين امنوا اطيعوا الله ورسوله ولا تولوا عنه وانتم تسمعون', NULL, 'O you who have believed, obey Allāh and His Messenger and do not turn from him while you hear [his order].', 'Wahai orang-orang yang beriman! Taatlah kepada Allah dan RasulNya dan janganlah kamu berpaling daripadanya, sedang kamu mendengar (Al-Quran yang mewajibkan taatnya).', FALSE, NULL, NULL, 179, 9, 71, 148, FALSE, 11, NULL),
(8, 21, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', 'وَلَا تَكُونُوا كَالَّذِينَ قَالُوا سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', NULL, 'And do not be like those who say, "We have heard," while they do not hear.', 'Dan janganlah kamu menjadi seperti orang-orang (kafir dan munafik) yang berkata: “Kami dengar”, padahal mereka tidak mendengar (tidak mahu menerima dan mematuhinya).', FALSE, NULL, NULL, 179, 9, 71, 148, FALSE, 0, NULL),
(8, 22, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', 'إِنَّ شَرَّ الدَّوَابِّ عِندَ اللَّهِ الصُّمُّ الْبُكْمُ الَّذِينَ لَا يَعْقِلُونَ', NULL, 'Indeed, the worst of living creatures in the sight of Allāh are the deaf and dumb who do not use reason [i.e., the disbelievers].', 'Sesungguhnya sejahat-jahat makhluk yang melata, pada sisi (hukum dan ketetapan) Allah, ialah orang-orang yang pekak lagi bisu, yang tidak mahu memahami sesuatupun (dengan akal fikirannya).', FALSE, NULL, NULL, 179, 9, 72, 148, FALSE, 0, NULL),
(8, 23, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'وَلَوْ عَلِمَ اللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا وَّهُم مُّعْرِضُونَ', NULL, 'Had Allāh known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.', 'Dan kalaulah Allah mengetahui ada kebaikan pada mereka, tentulah Ia menjadikan mereka dapat mendengar; dan kalau Allah menjadikan mereka dapat mendengar juga (dengan keadaan yang demikian), nescaya mereka tidak menerimanya sambil memalingkan diri.', FALSE, NULL, NULL, 179, 9, 72, 148, FALSE, 0, NULL),
(8, 24, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَاعْلَمُوا أَنَّ اللَّهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ وَأَنَّهُ إِلَيْهِ تُحْشَرُونَ', NULL, 'O you who have believed, respond to Allāh and to the Messenger when he calls you to that which gives you life. And know that Allāh intervenes between a man and his heart and that to Him you will be gathered.', 'Wahai orang-orang yang beriman, sahut dan sambutlah seruan Allah dan seruan RasulNya apabila Ia menyeru kamu kepada perkara-perkara yang menjadikan kamu hidup sempurna; dan ketahuilah bahawa sesungguhnya Allah berkuasa mengubah atau menyekat di antara seseorang itu dengan (pekerjaan) hatinya, dan sesungguhnya kepadaNyalah kamu akan dihimpunkan.', FALSE, NULL, NULL, 179, 9, 72, 148, FALSE, 0, NULL),
(8, 25, 'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'وَاتَّقُوا فِتْنَةً لَّا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنكُمْ خَاصَّةً وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ', NULL, 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allāh is severe in penalty.', 'Dan jagalah diri kamu daripada (berlakunya) dosa (yang membawa bala bencana) yang bukan sahaja akan menimpa orang-orang yang zalim di antara kamu secara khusus (tetapi akan menimpa kamu secara umum). Dan ketahuilah bahawa Allah Maha berat azab seksaNya.', FALSE, NULL, NULL, 179, 9, 72, 148, FALSE, 0, NULL),
(8, 26, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 'وَاذْكُرُوا إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِي الْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ النَّاسُ فَآوَاكُمْ وَأَيَّدَكُم بِنَصْرِهِ وَرَزَقَكُم مِّنَ الطَّيِّبَاتِ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.', 'Dan ingatlah ketika kamu sedikit bilangannya serta tertindas di bumi, kamu takut orang-orang menangkap dan melarikan kamu, maka Allah memberi kamu tempat bermustautin dan diperkuatkanNya kamu dengan pertolonganNya, serta dikurniakanNya kamu dari rezeki yang baik-baik, supaya kamu bersyukur.', FALSE, NULL, NULL, 180, 9, 72, 148, FALSE, 0, NULL),
(8, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنتُمْ تَعْلَمُونَ', NULL, 'O you who have believed, do not betray Allāh and the Messenger or betray your trusts while you know [the consequence].', 'Wahai orang-orang yang beriman! Janganlah kamu mengkhianati (amanah) Allah dan RasulNya, dan (janganlah) kamu mengkhianati amanah-amanah kamu, sedang kamu mengetahui (salahnya).', FALSE, NULL, NULL, 180, 9, 72, 148, FALSE, 0, NULL),
(8, 28, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'وَاعْلَمُوا أَنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ وَأَنَّ اللَّهَ عِندَهُ أَجْرٌ عَظِيمٌ', NULL, 'And know that your properties and your children are but a trial and that Allāh has with Him a great reward.', 'Dan ketahuilah bahawa harta benda kamu dan anak-anak kamu itu hanyalah menjadi ujian, dan sesungguhnya di sisi Allah jualah pahala yang besar.', FALSE, NULL, NULL, 180, 9, 72, 148, FALSE, 0, NULL),
(8, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تَتَّقُوا اللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّئَاتِكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ', NULL, 'O you who have believed, if you fear Allāh, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allāh is the possessor of great bounty.', 'Wahai orang-orang yang beriman! Jika kamu bertaqwa kepada Allah, nescaya Ia mengadakan bagi kamu (petunjuk) yang membezakan antara yang benar dengan yang salah, dan menghapuskan kesalahan-kesalahan kamu, serta mengampunkan (dosa-dosa) kamu. Dan Allah (sememangnya) mempunyai limpah kurnia yang besar.', FALSE, NULL, NULL, 180, 9, 72, 149, FALSE, 0, NULL),
(8, 30, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ', NULL, 'And [remember, O Muḥammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allāh plans. And Allāh is the best of planners.', 'Dan ingatlah (wahai Muhammad), ketika orang-orang kafir musyrik (Makkah) menjalankan tipu daya terhadapmu untuk menahanmu, atau membunuhmu, atau mengusirmu. Mereka menjalankan tipu daya dan Allah menggagalkan tipu daya (mereka), kerana Allah sebaik-baik yang menggagalkan tipu daya.', FALSE, NULL, NULL, 180, 9, 72, 149, FALSE, 0, NULL),
(8, 31, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا قَالُوا قَدْ سَمِعْنَا لَوْ نَشَاءُ لَقُلْنَا مِثْلَ هَٰذَا إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ', NULL, 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."', 'Dan apabila dibacakan kepada mereka ayat-ayat Kami, mereka berkata: “Sesungguhnya kami telah mendengarnya. Kalau kami mahu, nescaya kami dapat mengatakan (kata-kata) seperti (Al-Quran) ini. (Al-Quran) ini tidak lain hanyalah cerita cerita dongeng orang-orang dahulu kala”.', FALSE, NULL, NULL, 180, 9, 72, 149, FALSE, 0, NULL),
(8, 32, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ', 'وَإِذْ قَالُوا اللَّهُمَّ إِن كَانَ هَٰذَا هُوَ الْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ', NULL, 'And [remember] when they said, "O Allāh, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."', 'Dan (ingatlah) ketika mereka (kaum musyrik Makkah) berkata: “Wahai tuhan kami! Jika betul (Al-Quran) itu ialah yang benar dari sisimu, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab seksa yang tidak terperi sakitnya”.', FALSE, NULL, NULL, 180, 9, 72, 149, FALSE, 0, NULL),
(8, 33, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', 'وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', NULL, 'But Allāh would not punish them while you, [O Muḥammad], are among them, and Allāh would not punish them while they seek forgiveness.', 'Dan Allah tidak sekali-kali akan menyeksa mereka, sedang engkau (wahai Muhammad) ada di antara mereka; dan Allah tidak akan menyeksa mereka sedang mereka beristighfar (meminta ampun).', FALSE, NULL, NULL, 180, 9, 72, 149, FALSE, 0, NULL),
(8, 34, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'But why should Allāh not punish them while they obstruct [people] from al-Masjid al-Ḥarām and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.', 'Dan mengapa mereka tidak patut diseksa oleh Allah, sedang mereka menyekat (orang-orang Islam) dari masjid Al-Haraam, padahal mereka bukanlah orang-orang yang berhak menguasainya (kerana mereka kafir musyrik)? Sebenarnya orang-orang yang berhak menguasainya hanyalah orang-orang yang bertaqwa, tetapi kebanyakan mereka tidak mengetahui.', FALSE, NULL, NULL, 181, 9, 72, 149, FALSE, 0, NULL),
(8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'وَمَا كَانَ صَلَاتُهُمْ عِندَ الْبَيْتِ إِلَّا مُكَاءً وَتَصْدِيَةً فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', NULL, 'And their prayer at the House [i.e., the Kaʿbah] was not except whistling and handclapping. So taste the punishment for what you disbelieved [i.e., practiced of deviations].', 'Dan tiadalah sembahyang mereka di sisi Baitullah itu melainkan bersiul-siul dan bertepuk tangan. Oleh itu rasalah kamu (wahai orang kafir) akan azab seksa dengan sebab kekufuran kamu.', FALSE, NULL, NULL, 181, 9, 72, 149, FALSE, 0, NULL),
(8, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'إِنَّ الَّذِينَ كَفَرُوا يُنفِقُونَ أَمْوَالَهُمْ لِيَصُدُّوا عَن سَبِيلِ اللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَالَّذِينَ كَفَرُوا إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', NULL, 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allāh. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.', 'Sesungguhnya orang-orang kafir yang selalu membelanjakan harta mereka untuk menghalangi (manusia) dari jalan Allah, maka mereka tetap membelanjakannya kemudian (harta yang dibelanjakan) itu menyebabkan penyesalan kepada mereka, tambahan pula mereka dikalahkan. Dan (ingatlah) orang-orang kafir itu (akhirnya) dihimpunkan dalam neraka jahanam.', FALSE, NULL, NULL, 181, 9, 72, 149, FALSE, 0, NULL),
(8, 37, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'لِيَمِيزَ اللَّهُ الْخَبِيثَ مِنَ الطَّيِّبِ وَيَجْعَلَ الْخَبِيثَ بَعْضَهُ عَلَىٰ بَعْضٍ فَيَرْكُمَهُ جَمِيعًا فَيَجْعَلَهُ فِي جَهَنَّمَ أُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, '[It is] so that Allāh may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.', 'Kerana Allah hendak membezakan yang jahat (golongan yang ingkar) dari yang baik (golongan yang beriman), dan menjadikan (golongan) yang jahat itu setengahnya bersatu dengan setengahnya yang lain, lalu ditimbunkannya kesemuanya, serta dimasukkannya ke dalam neraka Jahanam. Mereka itulah orang-orang yang rugi.', FALSE, NULL, NULL, 181, 9, 72, 149, FALSE, 0, NULL),
(8, 38, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', 'قُل لِّلَّذِينَ كَفَرُوا إِن يَنتَهُوا يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا فَقَدْ مَضَتْ سُنَّتُ الْأَوَّلِينَ', NULL, 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.', 'Katakanlah (wahai Muhammad) kepada orang-orang yang kafir itu, jika mereka berhenti (dari kekufurannya), nescaya akan diampunkan dosa mereka yang telah lalu, dan jika mereka kembali lagi (ingkar maka Kami akan menyeksa mereka), kerana sesungguhnya telah berlakulah kebinasaan orang-orang (yang kufur ingkar) dahulu kala.', FALSE, NULL, NULL, 181, 9, 72, 150, FALSE, 0, NULL),
(8, 39, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', 'وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ فَإِنِ انتَهَوْا فَإِنَّ اللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', NULL, 'And fight against them until there is no fitnah and [until] the religion [i.e., worship], all of it, is for Allāh. And if they cease - then indeed, Allāh is Seeing of what they do.', 'Dan perangilah mereka sehingga tidak ada lagi fitnah, dan (sehingga) menjadilah ugama itu seluruhnya (bebas) bagi Allah semata-mata. Kemudian jika mereka berhenti (dari kekufurannya dan gangguannya, nescaya mereka diberikan balasan yang baik) kerana sesungguhnya Allah Maha Melihat akan apa yang mereka kerjakan.', FALSE, NULL, NULL, 181, 9, 72, 150, FALSE, 0, NULL),
(8, 40, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'وَإِن تَوَلَّوْا فَاعْلَمُوا أَنَّ اللَّهَ مَوْلَاكُمْ نِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ', NULL, 'But if they turn away - then know that Allāh is your protector. Excellent is the protector, and excellent is the helper.', 'Dan jika mereka berpaling (enggan beriman dan tidak berhenti daripada menceroboh) maka ketahuilah bahawasanya Allah Pelindung kamu; Dia lah sebaik-baik Pelindung dan sebaik-baik Penolong (yang menyelamatkan dan menjayakan kamu).', FALSE, NULL, NULL, 181, 9, 72, 150, FALSE, 0, NULL),
(8, 41, 'وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ إِن كُنتُمْ آمَنتُم بِاللَّهِ وَمَا أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'And know that anything you obtain of war booty - then indeed, for Allāh is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allāh and in that which We sent down to Our Servant on the day of criterion [i.e., decisive encounter] - the day when the two armies met [at Badr]. And Allāh, over all things, is competent.', 'Dan ketahuilah, bahawa apa sahaja yang kamu dapati sebagai harta rampasan perang, maka sesungguhnya satu perlimanya (dibahagikan) untuk (jalan) Allah, dan untuk RasulNya, dan untuk kerabat (Rasulullah), dan anak-anak yatim, dan orang-orang miskin, serta ibnus-sabil (orang musafir yang keputusan), jika kamu beriman kepada Allah dan kepada apa yang telah diturunkan oleh Kami (Allah) kepada hamba Kami (Muhammad) pada “Hari Al-Furqaan”, iaitu hari bertemunya dua angkatan tentera (Islam dan kafir, di medan perang Badar). Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 182, 10, 73, 150, FALSE, 0, NULL),
(8, 42, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'إِذْ أَنتُم بِالْعُدْوَةِ الدُّنْيَا وَهُم بِالْعُدْوَةِ الْقُصْوَىٰ وَالرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَاخْتَلَفْتُمْ فِي الْمِيعَادِ وَلَٰكِن لِّيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَن بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَيَّ عَن بَيِّنَةٍ وَإِنَّ اللَّهَ لَسَمِيعٌ عَلِيمٌ', NULL, '[Remember] when you were on the near side of the valley, and they were on the farther side, and the caravan was lower [in position] than you. If you had made an appointment [to meet], you would have missed the appointment. But [it was] so that Allāh might accomplish a matter already destined - that those who perished [through disbelief] would perish upon evidence and those who lived [in faith] would live upon evidence; and indeed, Allāh is Hearing and Knowing.', '(Iaitu) ketika kamu berada di tepi lembah yang dekat (ke Madinah) dan mereka (pihak musuh) berada di tepi lembah yang jauh (dari Madinah), sedang Kafilah (pembawa dagangan musuh) berada di tempat yang rendah dari tempat kamu (di tepi laut). Dan kalaulah kamu berjanji (dengan mereka mengenai peperangan itu) nescaya kamu akan berselisih pada menentukan harinya. Akan tetapi (pertemuan angkatan kamu dengan angkatan mereka yang tidak disangka-sangka itu) ialah supaya Allah melakukan suatu perkara (kemenangan Islam) yang telah ditetapkan berlakunya, iaitu supaya orang (kafir musyrik) yang binasa itu, binasa dengan keterangan (yang membuktikan kesalahannya), dan supaya orang (Islam) yang hidup itu, hidup dengan keterangan (yang membuktikan kebenarannya); kerana sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 182, 10, 73, 150, FALSE, 0, NULL),
(8, 43, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'إِذْ يُرِيكَهُمُ اللَّهُ فِي مَنَامِكَ قَلِيلًا وَلَوْ أَرَاكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَازَعْتُمْ فِي الْأَمْرِ وَلَٰكِنَّ اللَّهَ سَلَّمَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, '[Remember, O Muḥammad], when Allāh showed them to you in your dream as few; and if He had shown them to you as many, you [believers] would have lost courage and would have disputed in the matter [of whether to fight], but Allāh saved [you from that]. Indeed, He is Knowing of that within the breasts.', '(Ingatlah wahai Muhammad) ketika Allah memperlihatkan mereka kepadamu dalam mimpimu sedikit bilangannya; dan kalaulah Ia perlihatkan mereka kepadamu ramai bilangannya, tentulah kamu akan merasa gerun dan tentulah kamu akan berbantah-bantahan dalam urusan (perang) itu. Akan tetapi Allah telah menyelamatkan kamu. Sesungguhnya Allah Maha Mengetahui akan segala (isi hati) yang ada di dalam dada.', FALSE, NULL, NULL, 182, 10, 73, 150, FALSE, 0, NULL),
(8, 44, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'وَإِذْ يُرِيكُمُوهُمْ إِذِ الْتَقَيْتُمْ فِي أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِي أَعْيُنِهِمْ لِيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ', NULL, 'And [remember] when He showed them to you, when you met, as few in your eyes, and He made you [appear] as few in their eyes so that Allāh might accomplish a matter already destined. And to Allāh are [all] matters returned.', 'Dan (ingatlah) ketika Kami memperlihatkan mereka kepada kamu (wahai umat Islam) semasa kamu bertemu dengan mereka: sedikit bilangannya pada pandangan mata kamu, dan kamu pula diperlihatkanNya: sedikit bilangannya pada pandangan mata mereka; kerana Allah hendak melakukan sesuatu perkara (kemenangan Islam) yang telah ditetapkan berlakunya. Dan (ingatlah) kepada Allah jualah dikembalikan segala urusan.', FALSE, NULL, NULL, 182, 10, 73, 150, FALSE, 0, NULL),
(8, 45, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا لَقِيتُمْ فِئَةً فَاثْبُتُوا وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, when you encounter a company [from the enemy forces], stand firm and remember Allāh much that you may be successful.', 'Wahai orang-orang yang beriman! Apabila kamu bertemu dengan sesuatu pasukan (musuh) maka hendaklah kamu tetap teguh menghadapinya, dan sebutlah serta ingatilah Allah (dengan doa) banyak-banyak, supaya kamu berjaya (mencapai kemenangan).', FALSE, NULL, NULL, 182, 10, 73, 151, FALSE, 0, NULL),
(8, 46, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ وَٱصْبِرُوٓا۟ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'وَأَطِيعُوا اللَّهَ وَرَسُولَهُ وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', NULL, 'And obey Allāh and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allāh is with the patient.', 'Dan taatlah kamu kepada Allah dan RasulNya, dan janganlah kamu berbantah-bantahan; kalau tidak nescaya kamu menjadi lemah semangat dan hilang kekuatan kamu, dan sabarlah (menghadapi segala kesukaran dengan cekal hati); sesungguhnya Allah beserta orang-orang yang sabar.', FALSE, NULL, NULL, 183, 10, 73, 151, FALSE, 0, NULL),
(8, 47, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', 'وَلَا تَكُونُوا كَالَّذِينَ خَرَجُوا مِن دِيَارِهِم بَطَرًا وَرِئَاءَ النَّاسِ وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَاللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', NULL, 'And do not be like those who came forth from their homes insolently and to be seen by people and avert [them] from the way of Allāh. And Allāh is encompassing of what they do.', 'Dan janganlah kamu menjadi seperti orang-orang yang keluar dari negerinya dengan berlagak sombong dan menunjuk-nunjuk (kekuatan mereka) kepada orang ramai (kerana hendak meminta dipuji), serta mereka pula menghalang manusia dari jalan Allah dan (ingatlah) Allah Maha Meliputi pengetahuanNya akan apa yang mereka kerjakan.', FALSE, NULL, NULL, 183, 10, 73, 151, FALSE, 0, NULL),
(8, 48, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'وَإِذْ زَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَإِنِّي جَارٌ لَّكُمْ فَلَمَّا تَرَاءَتِ الْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّي بَرِيءٌ مِّنكُمْ إِنِّي أَرَىٰ مَا لَا تَرَوْنَ إِنِّي أَخَافُ اللَّهَ وَاللَّهُ شَدِيدُ الْعِقَابِ', NULL, 'And [remember] when Satan made their deeds pleasing to them and said, "No one can overcome you today from among the people, and indeed, I am your protector." But when the two armies sighted each other, he turned on his heels and said, "Indeed, I am disassociated from you. Indeed, I see what you do not see; indeed, I fear Allāh. And Allāh is severe in penalty."', 'Dan (ingatlah) ketika Syaitan memperhiaskan kepada mereka perbuatan mereka (yang salah itu, untuk dipandang elok dan diteruskan), serta menghasut mereka dengan berkata: “Pada hari ini tidak ada sesiapa pun dari umat manusia yang dapat mengalahkan kamu, dan sesungguhnya aku adalah pelindung dan penolong kamu”. Maka apabila kedua-dua puak (angkatan tentera Islam dan kafir musyrik) masing-masing kelihatan (berhadapan), Syaitan itu berundur ke belakang sambil berkata: “Aku berlepas diri dari kamu, kerana aku dapat melihat apa yang kamu tidak dapat melihatnya; sesungguhnya aku takut kepada Allah, dan Allah sangat berat azab seksaNya”.', FALSE, NULL, NULL, 183, 10, 73, 151, FALSE, 0, NULL),
(8, 49, 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'إِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَٰؤُلَاءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَإِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, '[Remember] when the hypocrites and those in whose hearts was disease [i.e., arrogance and disbelief] said, "Their religion has deluded those [Muslims]." But whoever relies upon Allāh - then indeed, Allāh is Exalted in Might and Wise.', '(Ingatlah) ketika orang-orang munafik dan orang-orang yang ada penyakit (syak) dalam hatinya berkata: “Orang-orang (Islam) itu telah diperdayakan oleh ugama mereka (sehingga mereka berani menentang kami yang lebih besar bilangannya)”. Dan (yang sebenarnya) sesiapa yang bertawakal kepada Allah (dengan sepenuh-penuh yakin, maka Allah akan menolongnya untuk mengalahkan musuh yang lebih besar bilangannya), kerana Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 183, 10, 73, 152, FALSE, 0, NULL),
(8, 50, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'وَلَوْ تَرَىٰ إِذْ يَتَوَفَّى الَّذِينَ كَفَرُوا الْمَلَائِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ وَذُوقُوا عَذَابَ الْحَرِيقِ', NULL, 'And if you could but see when the angels take the souls of those who disbelieved... They are striking their faces and their backs and [saying], "Taste the punishment of the Burning Fire.', 'Dan (amatlah ngerinya) kalau engkau melihat (wahai orang yang memandang), ketika malaikat mengambil nyawa orang-orang kafir dengan memukul muka dan belakang mereka (sambil berkata): “Rasalah kamu azab seksa neraka yang membakar”.', FALSE, NULL, NULL, 183, 10, 73, 152, FALSE, 0, NULL),
(8, 51, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', NULL, 'That is for what your hands have put forth [of evil] and because Allāh is not ever unjust to [His] servants."', '(Azab seksa) yang demikian itu ialah disebabkan apa yang telah dilakukan oleh tangan kamu sendiri, kerana sesungguhnya Allah tidak sekali-kali berlaku zalim kepada hamba-hambaNya.', FALSE, NULL, NULL, 183, 10, 73, 152, FALSE, 0, NULL),
(8, 52, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', 'كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَفَرُوا بِآيَاتِ اللَّهِ فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ إِنَّ اللَّهَ قَوِيٌّ شَدِيدُ الْعِقَابِ', NULL, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allāh, so Allāh seized them for their sins. Indeed, Allāh is Powerful and severe in penalty.', '(Keadaan orang-orang kafir itu) samalah seperti keadaan Firaun dan kaumnya serta orang-orang yang terdahulu dari mereka. Mereka kufur ingkar akan ayat-ayat Allah, lalu Allah menyeksa mereka dengan sebab dosa-dosa mereka. Sesungguhnya Allah Maha Kuat, lagi Maha berat seksaNya.', FALSE, NULL, NULL, 183, 10, 73, 152, FALSE, 0, NULL),
(8, 53, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'ذَٰلِكَ بِأَنَّ اللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ وَأَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ', NULL, 'That is because Allāh would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allāh is Hearing and Knowing.', '(Balasan) yang demikian itu, ialah kerana sesungguhnya Allah tidak akan mengubah sesuatu nikmat yang telah dikurniakanNya kepada sesuatu kaum sehingga mereka mengubah apa yang ada pada diri mereka sendiri. Dan (ingatlah) sesungguhnya Allah Maha mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 54, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَكُلٌّ كَانُوا۟ ظَٰلِمِينَ', 'كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِ رَبِّهِمْ فَأَهْلَكْنَاهُم بِذُنُوبِهِمْ وَأَغْرَقْنَا آلَ فِرْعَوْنَ وَكُلٌّ كَانُوا ظَالِمِينَ', NULL, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They denied the signs of their Lord, so We destroyed them for their sins, and We drowned the people of Pharaoh. And all [of them] were wrongdoers.', '(Keadaan mereka) samalah seperti keadaan Firaun dan kaumnya serta orang-orang yang terdahulu dari mereka. Mereka mendustakan ayat-ayat Tuhan mereka, lalu Kami binasakan mereka dengan sebab dosa-dosa mereka, dan Kami tenggelamkan Firaun serta pengikut-pengikutnya (di laut), kerana kesemuanya adalah orang-orang yang zalim.', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 55, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', 'إِنَّ شَرَّ الدَّوَابِّ عِندَ اللَّهِ الَّذِينَ كَفَرُوا فَهُمْ لَا يُؤْمِنُونَ', NULL, 'Indeed, the worst of living creatures in the sight of Allāh are those who have disbelieved, and they will not [ever] believe-', 'Sesungguhnya sejahat-jahat (makhluk) yang melata di sisi (hukum dan ketetapan) Allah ialah orang-orang yang kafir (yang degil dengan kekufurannya). Sebab itu mereka tidak (mahu) beriman.', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 56, 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', 'الَّذِينَ عَاهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِي كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', NULL, 'The ones with whom you made a treaty but then they break their pledge every time, and they do not fear Allāh.', '(Iaitu) orang-orang yang engkau telah mengikat perjanjian setia dengan mereka, kemudian mereka mencabuli perjanjian setianya pada tiap-tiap kali, sedang mereka tidak mahu memelihara dirinya (dari keaiban mencabuli perjanjian itu).', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 57, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', 'فَإِمَّا تَثْقَفَنَّهُمْ فِي الْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', NULL, 'So if you, [O Muḥammad], gain dominance over them in war, disperse by [means of] them those behind them that perhaps they will be reminded.', 'Oleh itu, jika engkau menemui mereka dalam peperangan maka hancurkanlah mereka (supaya dengan itu) orang-orang yang di belakang mereka (gerun gentar); mudah-mudahan orang-orang itu pula beringat (insaf).', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 58, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَانبِذْ إِلَيْهِمْ عَلَىٰ سَوَاءٍ إِنَّ اللَّهَ لَا يُحِبُّ الْخَائِنِينَ', NULL, 'If you [have reason to] fear from a people betrayal, throw [their treaty] back to them, [putting you] on equal terms. Indeed, Allāh does not like traitors.', 'Dan jika engkau mengetahui adanya perbuatan khianat dari sesuatu kaum (yang mengikat perjanjian setia denganmu) maka campakkanlah (perjanjian itu) kepada mereka dengan cara terus terang dan adil. Sesungguhnya Allah tidak suka kepada orang-orang yang khianat.', FALSE, NULL, NULL, 184, 10, 73, 152, FALSE, 0, NULL),
(8, 59, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ إِنَّهُمْ لَا يُعْجِزُونَ', 'وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا سَبَقُوا إِنَّهُمْ لَا يُعْجِزُونَ', NULL, 'And let not those who disbelieve think they will escape. Indeed, they will not cause failure [to Allāh].', 'Dan janganlah orang-orang yang kafir itu menyangka (bahawa) mereka telah terlepas (dari kekuasaan dan balasan Kami); sesungguhnya mereka tidak akan dapat melemahkan (kekuasaan Kami).', FALSE, NULL, NULL, 184, 10, 73, 153, FALSE, 0, NULL),
(8, 60, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ وَآخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ اللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا مِن شَيْءٍ فِي سَبِيلِ اللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', NULL, 'And prepare against them whatever you are able of power and of steeds of war by which you may terrify the enemy of Allāh and your enemy and others besides them whom you do not know [but] whom Allāh knows. And whatever you spend in the cause of Allāh will be fully repaid to you, and you will not be wronged.', 'Dan sediakanlah untuk menentang mereka (musuh yang menceroboh) segala jenis kekuatan yang dapat kamu sediakan dan dari pasukan-pasukan berkuda yang lengkap sedia, untuk menggerunkan dengan persediaan itu musuh Allah dan musuh kamu serta musuh-musuh yang lain dari mereka yang kamu tidak mengetahuinya; sedang Allah mengetahuinya. Dan apa sahaja yang kamu belanjakan pada jalan Allah akan disempurnakan balasannya kepada kamu, dan kamu tidak akan dianiaya.', FALSE, NULL, NULL, 184, 10, 73, 153, FALSE, 0, NULL),
(8, 61, 'وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَإِن جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى اللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'And if they incline to peace, then incline to it [also] and rely upon Allāh. Indeed, it is He who is the Hearing, the Knowing.', 'Dan jika mereka (pihak musuh) cenderung kepada perdamaian, maka engkau juga hendaklah cenderung kepadanya serta bertawakalah kepada Allah. Sesungguhnya Ia Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 184, 10, 74, 153, FALSE, 0, NULL),
(8, 62, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', 'وَإِن يُرِيدُوا أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ اللَّهُ هُوَ الَّذِي أَيَّدَكَ بِنَصْرِهِ وَبِالْمُؤْمِنِينَ', NULL, 'But if they intend to deceive you - then sufficient for you is Allāh. It is He who supported you with His help and with the believers', 'Dan jika mereka bertujuan hendak menipumu, maka sesungguhnya cukuplah Allah (menjaga dan memberikan perlindungan) kepadamu. Dia lah yang menguatkanmu dengan pertolonganNya dan dengan (sokongan) orang-orang yang beriman.', FALSE, NULL, NULL, 185, 10, 74, 153, FALSE, 0, NULL),
(8, 63, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُۥ عَزِيزٌ حَكِيمٌ', 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَّا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ اللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُ عَزِيزٌ حَكِيمٌ', NULL, 'And brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allāh brought them together. Indeed, He is Exalted in Might and Wise.', 'Dan (Dia lah) yang menyatu-padukan di antara hati mereka (yang beriman itu). Kalaulah engkau belanjakan segala (harta benda) yang ada di bumi, nescaya engkau tidak dapat juga menyatu-padukan di antara hati mereka, akan tetapi Allah telah menyatu-padukan di antara (hati) mereka. Sesungguhnya Ia Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 185, 10, 74, 153, FALSE, 0, NULL),
(8, 64, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'يَا أَيُّهَا النَّبِيُّ حَسْبُكَ اللَّهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ', NULL, 'O Prophet, sufficient for you is Allāh and for whoever follows you of the believers.', 'Wahai Nabi, cukuplah Allah menjadi Penolongmu, dan juga pengikut-pengikutmu dari orang-orang yang beriman.', FALSE, NULL, NULL, 185, 10, 74, 153, FALSE, 0, NULL),
(8, 65, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'يَا أَيُّهَا النَّبِيُّ حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ وَإِن يَكُن مِّنكُم مِّائَةٌ يَغْلِبُوا أَلْفًا مِّنَ الَّذِينَ كَفَرُوا بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', NULL, 'O Prophet, urge the believers to battle. If there are among you twenty [who are] steadfast, they will overcome two hundred. And if there are among you one hundred [who are steadfast], they will overcome a thousand of those who have disbelieved because they are a people who do not understand.', 'Wahai Nabi, peransangkanlah orang-orang yang beriman itu untuk berperang. Jika ada di antara kamu dua puluh yang sabar, nescaya mereka dapat menewaskan dua ratus orang (dari pihak musuh yang kafir itu); dan jika ada di antara kamu seratus orang, nescaya mereka dapat menewaskan seribu orang dari golongan yang kafir, disebabkan mereka (yang kafir itu) orang-orang yang tidak mengerti.', FALSE, NULL, NULL, 185, 10, 74, 154, FALSE, 0, NULL),
(8, 66, 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'الْآنَ خَفَّفَ اللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّائَةٌ صَابِرَةٌ يَغْلِبُوا مِائَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوا أَلْفَيْنِ بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ', NULL, 'Now, Allāh has lightened [the hardship] for you, and He knows that among you is weakness. So if there are from you one hundred [who are] steadfast, they will overcome two hundred. And if there are among you a thousand, they will overcome two thousand by permission of Allāh. And Allāh is with the steadfast.', 'Sekarang Allah telah meringankan daripada kamu (apa yang telah diwajibkan dahulu) kerana Ia mengetahui bahawa pada kamu ada kelemahan; oleh itu jika ada di antara kamu seratus orang yang sabar, nescaya mereka akan dapat menewaskan dua ratus orang; dan jika ada di antara kamu seribu orang, nescaya mereka dapat menewaskan dua ribu orang dengan izin Allah. Dan (ingatlah) Allah beserta orang-orang yang sabar.', FALSE, NULL, NULL, 185, 10, 74, 154, FALSE, 0, NULL),
(8, 67, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِي الْأَرْضِ تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ', NULL, 'It is not for a prophet to have captives [of war] until he inflicts a massacre [upon Allāh''s enemies] in the land. You [i.e., some Muslims] desire the commodities of this world, but Allāh desires [for you] the Hereafter. And Allāh is Exalted in Might and Wise.', 'Tidaklah patut bagi seseorang Nabi mempunyai orang-orang tawanan sebelum ia dapat membunuh sebanyak-banyaknya di muka bumi. Kamu menghendaki harta benda dunia (yang tidak kekal), sedang Allah menghendaki (untuk kamu pahala) akhirat. Dan (ingatlah), Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 185, 10, 74, 154, FALSE, 0, NULL),
(8, 68, 'لَّوْلَا كِتَٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ', 'لَّوْلَا كِتَابٌ مِّنَ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيمٌ', NULL, 'If not for a decree from Allāh that preceded, you would have been touched for what you took by a great punishment.', 'Kalaulah tidak (kerana) adanya ketetapan dari Allah yang telah terdahulu, tentulah kamu ditimpa azab seksa yang besar disebabkan (penebus diri) yang kamu ambil (dari orang-orang tawanan) itu.', FALSE, NULL, NULL, 185, 10, 74, 154, FALSE, 0, NULL),
(8, 69, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'فَكُلُوا مِمَّا غَنِمْتُمْ حَلَالًا طَيِّبًا وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'So consume what you have taken of war booty [as being] lawful and good, and fear Allāh. Indeed, Allāh is Forgiving and Merciful.', 'Maka makanlah dari apa yang kamu telah dapat (dalam peperangan) itu, sebagai benda yang halal lagi baik, serta bertaqwalah kepada Allah; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 185, 10, 74, 154, FALSE, 0, NULL),
(8, 70, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'يَا أَيُّهَا النَّبِيُّ قُل لِّمَن فِي أَيْدِيكُم مِّنَ الْأَسْرَىٰ إِن يَعْلَمِ اللَّهُ فِي قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّا أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'O Prophet, say to whoever is in your hands of the captives, "If Allāh knows [any] good in your hearts, He will give you [something] better than what was taken from you, and He will forgive you; and Allāh is Forgiving and Merciful."', 'Wahai Nabi, katakanlah kepada orang-orang tawanan yang ada dalam tangan kamu: “Jika Allah mengetahui ada kebaikan (iman) dalam hati kamu, nescaya Ia akan memberi kepada kamu (balasan) yang lebih baik daripada (harta benda penebus diri) yang telah diambil dari kamu, dan Ia akan mengampunkan dosa kamu; kerana Allah Maha Pengampun, lagi maha Mengasihani.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(8, 71, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'وَإِن يُرِيدُوا خِيَانَتَكَ فَقَدْ خَانُوا اللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'But if they intend to betray you - then they have already betrayed Allāh before, and He empowered [you] over them. And Allāh is Knowing and Wise.', 'Dan jika mereka (orang-orang tawanan itu) bertujuan hendak melakukan khianat kepadamu, maka sesungguhnya mereka telahpun melakukan khianat kepada Allah (dengan kekufuran mereka) sebelum itu, lalu Allah menjadikan (engkau) mengalahkan dan menundukkan mereka; kerana Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(8, 72, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'إِنَّ الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوا وَّنَصَرُوا أُولَٰئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا مَا لَكُم مِّن وَلَايَتِهِم مِّن شَيْءٍ حَتَّىٰ يُهَاجِرُوا وَإِنِ اسْتَنصَرُوكُمْ فِي الدِّينِ فَعَلَيْكُمُ النَّصْرُ إِلَّا عَلَىٰ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُم مِّيثَاقٌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'Indeed, those who have believed and emigrated and fought with their wealth and lives in the cause of Allāh and those who gave shelter and aided - they are allies of one another. But those who believed and did not emigrate - for you there is no support of them until they emigrate. And if they seek help of you for the religion, then you must help, except against a people between yourselves and whom is a treaty. And Allāh is Seeing of what you do.', 'Sesungguhnya orang-orang yang beriman dan berhijrah serta berjihad dengan harta benda dan jiwa mereka pada jalan Allah, dan orang-orang (Ansar) yang memberi tempat kediaman dan pertolongan (kepada orang-orang Islam yang berhijrah itu), mereka semuanya menjadi penyokong dan pembela antara satu dengan yang lain. Dan orang-orang yang beriman yang belum berhijrah, maka kamu tidak bertanggungjawab sedikitpun untuk membela mereka sehingga mereka berhijrah. Dan jika mereka meminta pertolongan kepada kamu dalam perkara (menentang musuh untuk membela) ugama, maka wajiblah kamu menolongnya, kecuali terhadap kaum yang ada perjanjian setia di antara kamu dengan mereka. Dan (ingatlah) Allah Maha Melihat akan apa yang kamu lakukan.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(8, 73, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ', 'وَالَّذِينَ كَفَرُوا بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِي الْأَرْضِ وَفَسَادٌ كَبِيرٌ', NULL, 'And those who disbelieved are allies of one another. If you do not do so [i.e., ally yourselves with other believers], there will be fitnah [i.e., disbelief and oppression] on earth and great corruption.', 'Dan orang-orang yang kafir, setengahnya menjadi penyokong dan pembela bagi setengahnya yang lain. Jika kamu (wahai umat Islam) tidak menjalankan (dasar bantu-membantu sesama sendiri yang diperintahkan oleh Allah) itu, nescaya akan berlakulah fitnah (kekacauan) di muka bumi dan kerosakan yang besar.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(8, 74, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'وَالَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوا وَّنَصَرُوا أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', NULL, 'But those who have believed and emigrated and fought in the cause of Allāh and those who gave shelter and aided - it is they who are the believers, truly. For them is forgiveness and noble provision.', 'Dan orang-orang yang beriman dan berhijrah serta berjihad pada jalan Allah (untuk membela Islam), dan orang-orang (Ansar) yang memberi tempat kediaman dan pertolongan (kepada orang-orang Islam yang berhijrah itu), merekalah orang-orang yang beriman dengan sebenar-benarnya. Mereka beroleh keampunan dan limpah kurnia yang mulia.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(8, 75, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'وَالَّذِينَ آمَنُوا مِن بَعْدُ وَهَاجَرُوا وَجَاهَدُوا مَعَكُمْ فَأُولَٰئِكَ مِنكُمْ وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِي كِتَابِ اللَّهِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'And those who believed after [the initial emigration] and emigrated and fought with you - they are of you. But those of [blood] relationship are more entitled [to inheritance] in the decree of Allāh. Indeed, Allāh is Knowing of all things.', 'Dan orang-orang yang beriman sesudah itu, kemudian mereka berhijrah dan berjihad bersama-sama kamu, maka adalah mereka dari golongan kamu. Dalam pada itu, orang-orang yang mempunyai pertalian kerabat, setengahnya lebih berhak atas setengahnya yang (lain) menurut (hukum) Kitab Allah; sesungguhnya Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 186, 10, 74, 155, FALSE, 0, NULL),
(9, 1, 'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', 'براءة من الله ورسوله الى الذين عاهدتم من المشركين', NULL, '[This is a declaration of] disassociation, from Allāh and His Messenger, to those with whom you had made a treaty among the polytheists.', '(Ini adalah) pemutusan tanggungjawab (pembatalan perjanjian) dari Allah dan RasulNya terhadap kaum kafir musyrik yang kamu mengikat perjanjian setia (dengan mereka).', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 9, NULL),
(9, 2, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَـٰفِرِينَ', 'فسيحوا في الارض اربعة اشهر واعلموا انكم غير معجزي الله وان الله مخزي الكافرين', NULL, 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allāh and that Allāh will disgrace the disbelievers.', 'Oleh itu hendaklah kamu (hai kaum musyrik) bergerak di muka bumi (dengan bebasnya) selama empat bulan, dan ketahuilah bahawa kamu tidak terlepas dari (azab seksa) Allah. Dan (ingatlah) sesungguhnya Allah akan menghina orang-orang yang kafir (dengan bala bencana di dunia dan azab seksa di akhirat).', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 14, NULL),
(9, 3, 'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 'واذان من الله ورسوله الى الناس يوم الحج الاكبر ان الله بريء من المشركين ورسوله فان تبتم فهو خير لكم وان توليتم فاعلموا انكم غير معجزي الله وبشر الذين كفروا بعذاب اليم', NULL, 'And [it is] an announcement from Allāh and His Messenger to the people on the day of the greater pilgrimage that Allāh is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allāh. And give tidings to those who disbelieve of a painful punishment.', 'Dan inilah perisytiharan dari Allah dan RasulNya kepada umat manusia, (diisytiharkan) pada Hari Raya Haji yang terbesar, bahawa sesungguhnya Allah dan RasulNya memutuskan tanggungjawab terhadap orang-orang musyrik; oleh itu jika kamu (wahai kaum musyrik) bertaubat (dari kufur) maka yang demikian adalah baik bagi kamu; dan jika kamu berpaling (ingkar), maka ketahuilah sesungguhnya kamu tidak akan dapat melepaskan diri dari (azab seksa) Allah. Dan khabarkanlah (wahai Muhammad) kepada orang-orang kafir (bahawa mereka akan ditimpakan) dengan azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 32, NULL),
(9, 4, 'إِلَّا ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَـٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'الا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئا ولم يظاهروا عليكم احدا فاتموا اليهم عهدهم الى مدتهم ان الله يحب المتقين', NULL, 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allāh loves the righteous [who fear Him].', 'Kecuali mereka yang kamu mengikat perjanjian setia (dengannya) dari orang-orang musyrik, kemudian mereka tidak mencabuli perjanjian kamu itu sedikitpun, dan mereka tidak menolong seorangpun yang memusuhi kamu, maka sempurnakanlah kepada mereka perjanjian mereka sehingga (habis) tempohnya. Sesungguhnya Allah mengasihi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 22, NULL),
(9, 5, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'فاذا انسلخ الاشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فان تابوا واقاموا الصلاة واتوا الزكاة فخلوا سبيلهم ان الله غفور رحيم', NULL, 'And when the inviolable months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakāh, let them [go] on their way. Indeed, Allāh is Forgiving and Merciful.', 'Kemudian apabila habislah (masa) bulan-bulan yang dihormati itu maka bunuhlah orang-orang musyrik itu di mana sahaja kamu menemuinya, dan tawanlah mereka, dan juga keponglah mereka, serta tunggulah mereka di tiap-tiap tempat mengintipnya. Kemudian jika mereka bertaubat (dari kekufurannya) dan mendirikan sembahyang serta memberi zakat, maka biarkanlah mereka (jangan diganggu). Sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 26, NULL),
(9, 6, 'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ', 'وان احد من المشركين استجارك فاجره حتى يسمع كلام الله ثم ابلغه مامنه ذلك بانهم قوم لا يعلمون', NULL, 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allāh [i.e., the Qur’ān]. Then deliver him to his place of safety. That is because they are a people who do not know.', 'Dan jika seseorang dari kaum musyrik meminta perlindungan kepadamu (untuk memahami Islam), maka berilah perlindungan kepadanya sehingga ia sempat mendengar keterangan-keterangan Allah (tentang hakikat Islam itu), kemudian hantarlah dia ke mana-mana tempat yang ia beroleh aman. Perintah yang tersebut ialah kerana mereka itu kaum yang tidak mengetahui (hakikat Islam).', FALSE, NULL, NULL, 187, 10, 75, 156, FALSE, 18, NULL),
(9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَـٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَـٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'كيف يكون للمشركين عهد عند الله وعند رسوله الا الذين عاهدتم عند المسجد الحرام فما استقاموا لكم فاستقيموا لهم ان الله يحب المتقين', NULL, 'How can there be for the polytheists a treaty in the sight of Allāh and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Ḥarām? So as long as they are upright toward you, be upright toward them. Indeed, Allāh loves the righteous [who fear Him].', 'Bagaimanakah dapat diakui adanya perjanjian (keamanan) di sisi Allah dan RasulNya bagi orang-orang musyrik (sedang mereka mencabulinya)? Kecuali orang-orang (musyrik) yang kamu telah mengikat perjanjian setia dengan mereka dekat Masjid Al-Haraam. Maka selagi mereka berlaku lurus terhadap kamu, hendaklah kamu berlaku lurus pula terhadap mereka; sesungguhnya Allah mengasihi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 23, NULL),
(9, 8, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَـٰسِقُونَ', 'كيف وان يظهروا عليكم لا يرقبوا فيكم الا ولا ذمة يرضونكم بافواههم وتابى قلوبهم واكثرهم فاسقون', NULL, 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.', 'Bagaimana (boleh dikekalkan perjanjian kaum kafir musyrik itu) padahal kalau mereka dapat mengalahkan kamu, mereka tidak akan menghormati perhubungan kerabat terhadap kamu, dan tidak akan menghormati perjanjian setianya. Mereka menjadikan kamu bersenang hati hanya dengan mulut mereka, sedang hati mereka menolaknya; dan kebanyakan mereka adalah orang-orang yang fasik.', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 16, NULL),
(9, 9, 'ٱشْتَرَوْا۟ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'اشتروا بايات الله ثمنا قليلا فصدوا عن سبيله انهم ساء ما كانوا يعملون', NULL, 'They have exchanged the signs of Allāh for a small price and averted [people] from His way. Indeed, it was evil that they were doing.', 'Mereka menukarkan ayat-ayat Allah dengan harga yang sedikit (dari faedah-faedah dunia), lalu mereka menghalangi (dirinya dan orang-orang lain) dari ugama Allah; sesungguhnya amatlah buruknya apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 13, NULL),
(9, 10, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', 'لا يرقبون في مؤمن الا ولا ذمة واولئك هم المعتدون', NULL, 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.', 'Mereka tidak menghormati pertalian kerabat dan perjanjian terhadap orang-orang yang beriman, dan merekalah orang-orang yang menceroboh.', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 10, NULL),
(9, 11, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', 'فان تابوا واقاموا الصلاة واتوا الزكاة فاخوانكم في الدين ونفصل الايات لقوم يعلمون', NULL, 'But if they repent, establish prayer, and give zakāh, then they are your brothers in religion; and We detail the verses for a people who know.', 'Oleh itu, jika mereka bertaubat (dari kekufuran), dan mendirikan sembahyang serta memberi zakat, maka mereka itu adalah saudara kamu yang seugama; dan Kami menjelaskan ayat-ayat keterangan Kami satu persatu bagi kaum yang mahu mengetahui.', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 13, NULL),
(9, 12, 'وَإِن نَّكَثُوٓا۟ أَيْمَـٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَـٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَـٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', 'وان نكثوا ايمانهم من بعد عهدهم وطعنوا في دينكم فقاتلوا ائمة الكفر انهم لا ايمان لهم لعلهم ينتهون', NULL, 'And if they break their oaths after their treaty and defame your religion, then combat the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.', 'Dan jika mereka mencabuli sumpahnya sesudah mengikat perjanjian setia, dan mereka pula mencela ugama kamu, maka perangilah ketua-ketua dan pemimpin-pemimpin kaum yang kafir itu, kerana sesungguhnya mereka tidak menghormati sumpah janjinya, supaya mereka berhenti (dari kekufuran dan bertaubat).', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 18, NULL),
(9, 13, 'أَلَا تُقَـٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَـٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', 'الا تقاتلون قوما نكثوا ايمانهم وهموا باخراج الرسول وهم بدءوكم اول مرة اتخشونهم فالله احق ان تخشوه ان كنتم مؤمنين', NULL, 'Would you not fight against a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allāh has more right that you should fear Him, if you are [truly] believers.', 'Mengapa kamu tidak memerangi suatu kaum yang telah mencabuli sumpah janjinya, dan mereka pula telah berazam hendak mengusir Rasulullah, dan merekalah juga yang mula-mula memerangi kamu? Tidak patut kamu takut kepada mereka (sehingga kamu tidak mahu memeranginya) kerana Allah jualah yang berhak kamu takuti (melanggar perintahNya), jika betul kamu orang-orang yang beriman?', FALSE, NULL, NULL, 188, 10, 75, 157, FALSE, 20, NULL),
(9, 14, 'قَـٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ', 'قاتلوهم يعذبهم الله بايديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين', NULL, 'Fight them; Allāh will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts [i.e., desires] of a believing people', 'Perangilah mereka, nescaya Allah akan menyeksa mereka dengan (perantaraan) tangan kamu, dan Allah akan menghinakan mereka serta menolong kamu menewaskan mereka, dan Ia akan memuaskan hati orang-orang yang beriman.', FALSE, NULL, NULL, 189, 10, 75, 157, FALSE, 11, NULL),
(9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'ويذهب غيظ قلوبهم ويتوب الله على من يشاء والله عليم حكيم', NULL, 'And remove the fury in their [i.e., the believers''] hearts. And Allāh turns in forgiveness to whom He wills; and Allāh is Knowing and Wise.', 'Dan Ia juga akan menghapuskan kemarahan hati orang-orang yang beriman itu, dan Allah akan menerima taubat orang-orang yang dikehendakiNya; dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 189, 10, 75, 157, FALSE, 11, NULL),
(9, 16, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ام حسبتم ان تتركوا ولما يعلم الله الذين جاهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجة والله خبير بما تعملون', NULL, 'Do you think that you will be left [as you are] while Allāh has not yet made evident those among you who strive [for His cause] and do not take other than Allāh, His Messenger and the believers as intimates? And Allāh is [fully] Aware of what you do.', 'Adakah kamu menyangka, bahawa kamu akan dibiarkan (dalam keadaan kamu yang ada itu), padahal belum lagi terbukti kepada Allah (sebagaimana yang diketahuiNya) orang-orang yang berjihad di antara kamu dan yang tidak mengambil teman-teman rapat (untuk mencurahkan rahsia kepada mereka), selain daripada Allah dan RasulNya serta orang-orang yang beriman? Dan (ingatlah) Allah Maha Mengetahui secara mendalam akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 189, 10, 75, 157, FALSE, 24, NULL),
(9, 17, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَـٰجِدَ ٱللَّهِ شَـٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ ۚ أُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَـٰلِدُونَ', 'ما كان للمشركين ان يعمروا مساجد الله شاهدين على انفسهم بالكفر اولئك حبطت اعمالهم وفي النار هم خالدون', NULL, 'It is not for the polytheists to maintain the mosques of Allāh [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.', 'Tidaklah layak orang-orang kafir musyrik itu memakmurkan (menghidupkan) masjid-masjid Allah, sedang mereka menjadi saksi (mengakui) akan kekufuran diri mereka sendiri. Mereka itu ialah orang-orang yang rosak binasa amal-amalnya dan mereka pula kekal di dalam neraka.', FALSE, NULL, NULL, 189, 10, 75, 158, FALSE, 18, NULL),
(9, 18, 'إِنَّمَا يَعْمُرُ مَسَـٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ ۖ فَعَسَىٰٓ أُو۟لَـٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 'انما يعمر مساجد الله من امن بالله واليوم الاخر واقام الصلاة واتى الزكاة ولم يخش الا الله فعسى اولئك ان يكونوا من المهتدين', NULL, 'The mosques of Allāh are only to be maintained by those who believe in Allāh and the Last Day and establish prayer and give zakāh and do not fear except Allāh, for it is expected that those will be of the [rightly] guided.', 'Hanyasanya yang layak memakmurkan (menghidupkan) masjid-masjid Allah itu ialah orang-orang yang beriman kepada Allah dan hari akhirat serta mendirikan sembahyang dan menunaikan zakat dan tidak takut melainkan kepada Allah, (dengan adanya sifat-sifat yang tersebut) maka adalah diharapkan mereka menjadi dari golongan yang mendapat petunjuk.', FALSE, NULL, NULL, 189, 10, 75, 158, FALSE, 23, NULL),
(9, 19, '۞ أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَـٰهَدَ فِى سَبِيلِ ٱللَّهِ ۚ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 'اجعلتم سقاية الحاج وعمارة المسجد الحرام كمن امن بالله واليوم الاخر وجاهد في سبيل الله لا يستوون عند الله والله لا يهدي القوم الظالمين', NULL, 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Ḥarām equal to [the deeds of] one who believes in Allāh and the Last Day and strives in the cause of Allāh? They are not equal in the sight of Allāh. And Allāh does not guide the wrongdoing people.', 'Adakah kamu sifatkan hanya perbuatan memberi minum kepada orang-orang yang mengerjakan Haji, dan (hanya perbuatan) memakmurkan Masjid Al-Haraam itu sama seperti orang yang beriman kepada Allah dan hari akhirat serta berjihad pada jalan Allah? Mereka (yang bersifat demikian) tidak sama di sisi Allah, dan Allah tidak memberikan hidayah petunjuk kepada kaum yang zalim.', FALSE, NULL, NULL, 189, 10, 76, 158, FALSE, 24, NULL),
(9, 20, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'الذين امنوا وهاجروا وجاهدوا في سبيل الله باموالهم وانفسهم اعظم درجة عند الله واولئك هم الفائزون', NULL, 'The ones who have believed, emigrated and striven in the cause of Allāh with their wealth and their lives are greater in rank in the sight of Allāh. And it is those who are the attainers [of success].', '(Sesungguhnya) orang-orang yang beriman dan berhijrah serta berjihad pada jalan Allah dengan harta benda dan jiwa mereka adalah lebih besar dan tinggi darjatnya di sisi Allah (daripada orang-orang yang hanya memberi minum orang-orang Haji dan orang yang memakmurkan masjid sahaja); dan mereka itulah orang-orang yang berjaya.', FALSE, NULL, NULL, 189, 10, 76, 158, FALSE, 16, NULL),
(9, 21, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَانٍ وَجَنَّاتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', NULL, 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.', 'Mereka digembirakan oleh Tuhan mereka dengan pemberian rahmat daripadanya dan keredaan serta Syurga; mereka beroleh di dalam Syurga itu nikmat kesenangan yang kekal.', FALSE, NULL, NULL, 190, 10, 76, 158, FALSE, 0, NULL),
(9, 22, 'خَٰلِدِينَ فِيهَآ أَبَدًا إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'خَالِدِينَ فِيهَا أَبَدًا إِنَّ اللَّهَ عِندَهُ أَجْرٌ عَظِيمٌ', NULL, '[They will be] abiding therein forever. Indeed, Allāh has with Him a great reward.', 'Mereka kekal di dalamnya selama-lamanya. Sesungguhnya Allah, menyediakan di sisiNya pahala yang besar.', FALSE, NULL, NULL, 190, 10, 76, 158, FALSE, 0, NULL),
(9, 23, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا آبَاءَكُمْ وَإِخْوَانَكُمْ أَوْلِيَاءَ إِنِ اسْتَحَبُّوا الْكُفْرَ عَلَى الْإِيمَانِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ', NULL, 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.', 'Wahai orang-orang yang beriman! Janganlah kamu menjadikan bapa-bapa kamu dan saudara-saudara kamu sebagai orang-orang yang didampingi jika mereka memilih kufur dengan meninggalkan iman; dan sesiapa di antara kamu yang menjadikan mereka orang-orang yang didampingi, maka merekalah orang-orang yang zalim.', FALSE, NULL, NULL, 190, 10, 76, 158, FALSE, 0, NULL),
(9, 24, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'قُلْ إِن كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ وَإِخْوَانُكُمْ وَأَزْوَاجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَالٌ اقْتَرَفْتُمُوهَا وَتِجَارَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَهَا أَحَبَّ إِلَيْكُم مِّنَ اللَّهِ وَرَسُولِهِ وَجِهَادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّىٰ يَأْتِيَ اللَّهُ بِأَمْرِهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ', NULL, 'Say, [O Muḥammad], "If your fathers, your sons, your brothers, your wives, your relatives, wealth which you have obtained, commerce wherein you fear decline, and dwellings with which you are pleased are more beloved to you than Allāh and His Messenger and jihād [i.e., striving] in His cause, then wait until Allāh executes His command. And Allāh does not guide the defiantly disobedient people."', 'Katakanlah (wahai Muhammad): “Jika bapa-bapa kamu, dan anak-anak kamu, dan saudara-saudara kamu, dan isteri-isteri (atau suami-suami) kamu, dan kaum keluarga kamu, dan harta benda yang kamu usahakan, dan perniagaan yang kamu bimbang akan merosot, dan rumah-rumah tempat tinggal yang kamu sukai, - (jika semuanya itu) menjadi perkara-perkara yang kamu cintai lebih daripada Allah dan RasulNya dan (daripada) berjihad untuk ugamaNya, maka tunggulah sehingga Allah mendatangkan keputusanNya (azab seksaNya); kerana Allah tidak akan memberi petunjuk kepada orang-orang yang fasik (derhaka).', FALSE, NULL, NULL, 190, 10, 76, 158, FALSE, 0, NULL),
(9, 25, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', 'لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', NULL, 'Allāh has already given you victory in many regions and [even] on the day of Ḥunayn, when your great number pleased you, but it did not avail you at all, and the earth was confining for you with [i.e., in spite of] its vastness; then you turned back, fleeing.', 'Sesungguhnya Allah telah menolong kamu mencapai kemenangan dalam banyak medan-medan perang dan di medan perang Hunain, iaitu semasa kamu merasa megah dengan sebab bilangan kamu yang ramai; maka bilangan yang ramai itu tidak mendatangkan faedah kepada kamu sedikitpun; dan (semasa kamu merasa) bumi yang luas itu menjadi sempit kepada kamu; kemudian kamu berpaling undur melarikan diri.', FALSE, NULL, NULL, 190, 10, 76, 159, FALSE, 0, NULL),
(9, 26, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'ثُمَّ أَنزَلَ اللَّهُ سَكِينَتَهُ عَلَىٰ رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَٰلِكَ جَزَاءُ الْكَافِرِينَ', NULL, 'Then Allāh sent down His tranquility upon His Messenger and upon the believers and sent down soldiers [i.e., angels] whom you did not see and punished those who disbelieved. And that is the recompense of the disbelievers.', 'Kemudian Allah menurunkan semangat tenang tenteram kepada RasulNya dan kepada orang-orang yang beriman, dan Allah menurunkan tentera yang kamu tidak melihatnya, serta Ia menyeksa orang-orang kafir itu (dengan kekalahan yang membawa kehancuran); dan yang demikian itu ialah balasan bagi orang-orang yang kafir.', FALSE, NULL, NULL, 190, 10, 76, 159, FALSE, 0, NULL),
(9, 27, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'ثُمَّ يَتُوبُ اللَّهُ مِن بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَاءُ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'Then Allāh will accept repentance after that for whom He wills; and Allāh is Forgiving and Merciful.', 'Kemudian Allah menerima taubat orang-orang yang dikehendaki (dengan memberi taufiq untuk memeluk Islam), sesudah (orang-orang kafir itu ditimpakan dengan azab); dan (ingatlah) Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 191, 10, 76, 159, FALSE, 0, NULL),
(9, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ اللَّهُ مِن فَضْلِهِ إِن شَاءَ إِنَّ اللَّهَ عَلِيمٌ حَكِيمٌ', NULL, 'O you who have believed, indeed the polytheists are unclean, so let them not approach al-Masjid al-Ḥarām after this, their [final] year. And if you fear privation, Allāh will enrich you from His bounty if He wills. Indeed, Allāh is Knowing and Wise.', 'Wahai orang-orang yang beriman! Sesungguhnya (kepercayaan) orang-orang kafir musyrik itu najis, oleh itu janganlah mereka menghampiri Masjid Al-Haraam sesudah tahun ini; dan jika kamu bimbangkan kepapaan, maka Allah akan memberi kekayaan kepada kamu dari limpah kurniaNya, jika dia kehendaki. Sesungguhnya Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 191, 10, 76, 159, FALSE, 0, NULL),
(9, 29, 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَٰغِرُونَ', 'قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّىٰ يُعْطُوا الْجِزْيَةَ عَن يَدٍ وَهُمْ صَاغِرُونَ', NULL, 'Fight against those who do not believe in Allāh or in the Last Day and who do not consider unlawful what Allāh and His Messenger have made unlawful and who do not adopt the religion of truth [i.e., Islām] from those who were given the Scripture - [fight] until they give the jizyah willingly while they are humbled.', 'Perangilah orang-orang yang tidak beriman kepada Allah dan tidak beriman kepada hari akhirat, dan mereka pula tidak mengharamkan apa yang telah diharamkan oleh Allah dan RasulNya, dan tidak berugama dengan ugama yang benar, iaitu dari orang-orang yang diberikan Kitab (kaum Yahudi dan Nasrani), sehingga mereka membayar “Jizyah” dengan keadaan taat dan merendah diri.', FALSE, NULL, NULL, 191, 10, 76, 159, FALSE, 0, NULL),
(9, 30, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', 'وَقَالَتِ الْيَهُودُ عُزَيْرٌ ابْنُ اللَّهِ وَقَالَتِ النَّصَارَى الْمَسِيحُ ابْنُ اللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَاهِهِمْ يُضَاهِئُونَ قَوْلَ الَّذِينَ كَفَرُوا مِن قَبْلُ قَاتَلَهُمُ اللَّهُ أَنَّىٰ يُؤْفَكُونَ', NULL, 'The Jews say, "Ezra is the son of Allāh"; and the Christians say, "The Messiah is the son of Allāh." That is their statement from their mouths; they imitate the saying of those who disbelieved before [them]. May Allāh destroy them; how are they deluded?', 'Dan orang-orang Yahudi berkata: “Uzair ialah anak Allah” dan orang-orang Nasrani berkata: “Al-Masih ialah anak Allah”. Demikianlah perkataan mereka dengan mulut mereka sendiri, (iaitu) mereka menyamai perkataan orang-orang kafir dahulu; semoga Allah binasakan mereka. Bagaimanakah mereka boleh berpaling dari kebenaran?', FALSE, NULL, NULL, 191, 10, 76, 160, FALSE, 0, NULL),
(9, 31, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًا وَٰحِدًا لَّآ إِلَٰهَ إِلَّا هُوَ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 'اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَابًا مِّن دُونِ اللَّهِ وَالْمَسِيحَ ابْنَ مَرْيَمَ وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا إِلَٰهًا وَاحِدًا لَّا إِلَٰهَ إِلَّا هُوَ سُبْحَانَهُ عَمَّا يُشْرِكُونَ', NULL, 'They have taken their scholars and monks as lords besides Allāh, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him.', 'Mereka menjadikan pendita-pendita dan ahli-ahli ugama mereka sebagai pendidik-pendidik selain dari Allah, dan juga (mereka mempertuhankan) Al-Masih ibni Maryam, padahal mereka tidak diperintahkan melainkan untuk menyembah Tuhan Yang Maha Esa; tiada Tuhan (yang berhak disembah) melainkan Dia. Maha Suci Allah dari apa yang mereka sekutukan.', FALSE, NULL, NULL, 191, 10, 76, 160, FALSE, 0, NULL),
(9, 32, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'يُرِيدُونَ أَن يُطْفِئُوا نُورَ اللَّهِ بِأَفْوَاهِهِمْ وَيَأْبَى اللَّهُ إِلَّا أَن يُتِمَّ نُورَهُ وَلَوْ كَرِهَ الْكَافِرُونَ', NULL, 'They want to extinguish the light of Allāh with their mouths, but Allāh refuses except to perfect His light, although the disbelievers dislike it.', 'Mereka hendak memadamkan cahaya Allah (ugama Islam) dengan mulut mereka, sedang Allah tidak menghendaki melainkan menyempurnakan cahayaNya, sekalipun orang-orang kafir tidak suka (akan yang demikian).', FALSE, NULL, NULL, 192, 10, 76, 160, FALSE, 0, NULL),
(9, 33, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ', NULL, 'It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allāh dislike it.', 'Dia lah yang telah mengutus RasulNya (Muhammad) dengan membawa petunjuk dan ugama yang benar (ugama Islam), untuk dimenangkan dan ditinggikannya atas segala ugama yang lain, walaupun orang-orang musyrik tidak menyukainya.', FALSE, NULL, NULL, 192, 10, 76, 160, FALSE, 0, NULL),
(9, 34, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ كَثِيرًا مِّنَ الْأَحْبَارِ وَالرُّهْبَانِ لَيَأْكُلُونَ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', NULL, 'O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allāh. And those who hoard gold and silver and spend it not in the way of Allāh - give them tidings of a painful punishment.', 'Wahai orang-orang yang beriman! Sesungguhnya banyak di antara pendita-pendita dan ahli-ahli ugama (Yahudi dan Nasrani) memakan harta orang ramai dengan cara yang salah, dan mereka menghalangi (manusia) dari jalan Allah (ugama Islam). Dan (ingatlah) orang-orang yang menyimpan emas dan perak serta tidak membelanjakannya pada jalan Allah, maka khabarkanlah kepada mereka dengan (balasan) azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 192, 10, 77, 160, FALSE, 0, NULL),
(9, 35, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا مَا كُنتُمْ تَكْنِزُونَ', NULL, 'The Day when it will be heated in the fire of Hell and seared therewith will be their foreheads, their flanks, and their backs, [it will be said], "This is what you hoarded for yourselves, so taste what you used to hoard."', '(Iaitu) pada hari dibakar emas perak (dan harta benda) itu dalam neraka jahanam, lalu diselar dengannya dahi mereka, dan rusuk mereka, serta belakang mereka (sambil dikatakan kepada mereka): “Inilah apa yang telah kamu simpan untuk diri kamu sendiri, oleh itu rasalah (azab dari) apa yang kamu simpan itu.', FALSE, NULL, NULL, 192, 10, 77, 160, FALSE, 0, NULL),
(9, 36, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَٰتِلُونَكُمْ كَآفَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'إِنَّ عِدَّةَ الشُّهُورِ عِندَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ الدِّينُ الْقَيِّمُ فَلَا تَظْلِمُوا فِيهِنَّ أَنفُسَكُمْ وَقَاتِلُوا الْمُشْرِكِينَ كَافَّةً كَمَا يُقَاتِلُونَكُمْ كَافَّةً وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ', NULL, 'Indeed, the number of months with Allāh is twelve [lunar] months in the register of Allāh [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion [i.e., way], so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allāh is with the righteous [who fear Him].', 'Sesungguhnya bilangan bulan-bulan di sisi (hukum) Allah ialah dua belas bulan, (yang telah ditetapkan) dalam Kitab Allah semasa Ia menciptakan langit dan bumi, di antaranya empat bulan yang dihormati. Ketetapan yang demikian itu ialah ugama yang betul lurus, maka janganlah kamu menganiaya diri kamu dalam bulan-bulan yang dihormati itu (dengan melanggar laranganNya); dan perangilah kaum kafir musyrik seluruhnya sebagaimana mereka memerangi kamu seluruhnya; dan ketahuilah sesungguhnya Allah beserta orang-orang yang bertaqwa.', FALSE, NULL, NULL, 192, 10, 77, 160, FALSE, 0, NULL),
(9, 37, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا لِّيُوَاطِئُوا عِدَّةَ مَا حَرَّمَ اللَّهُ فَيُحِلُّوا مَا حَرَّمَ اللَّهُ زُيِّنَ لَهُمْ سُوءُ أَعْمَالِهِمْ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ', NULL, 'Indeed, the postponing [of restriction within sacred months] is an increase in disbelief by which those who have disbelieved are led [further] astray. They make it lawful one year and unlawful another year to correspond to the number made unlawful by Allāh and [thus] make lawful what Allāh has made unlawful. Made pleasing to them is the evil of their deeds; and Allāh does not guide the disbelieving people.', 'Sesungguhnya perbuatan mengundurkan (kehormatan itu dari satu bulan ke satu bulan yang lain) adalah menambah kekufuran yang menjadikan orang-orang kafir itu tersesat kerananya. Mereka menghalalkannya pada satu tahun dan mengharamkannya pada tahun yang lain, supaya mereka dapat menyesuaikan bilangan (bulan-bulan yang empat) yang telah diharamkan Allah (berperang di dalamnya); dengan itu mereka menghalalkan apa yang telah diharamkan oleh Allah. Perbuatan buruk mereka itu dihias dan dijadikan indah (oleh Syaitan) untuk dipandang baik oleh mereka. Dan (ingatlah) Allah tidak memberi hidayah petunjuk kepada orang-orang yang kafir.', FALSE, NULL, NULL, 193, 10, 77, 160, FALSE, 0, NULL),
(9, 38, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا مَا لَكُمْ إِذَا قِيلَ لَكُمُ انفِرُوا فِي سَبِيلِ اللَّهِ اثَّاقَلْتُمْ إِلَى الْأَرْضِ أَرَضِيتُم بِالْحَيَاةِ الدُّنْيَا مِنَ الْآخِرَةِ فَمَا مَتَاعُ الْحَيَاةِ الدُّنْيَا فِي الْآخِرَةِ إِلَّا قَلِيلٌ', NULL, 'O you who have believed, what is [the matter] with you that, when you are told to go forth in the cause of Allāh, you adhere heavily to the earth? Are you satisfied with the life of this world rather than the Hereafter? But what is the enjoyment of worldly life compared to the Hereafter except a [very] little.', 'Wahai orang-orang yang beriman! Mengapa kamu, apabila dikatakan kepada kamu: “Pergilah beramai-ramai untuk berperang pada jalan Allah”, kamu merasa keberatan (dan suka tinggal menikmati kesenangan) di tempat (masing-masing)? Adakah kamu lebih suka dengan kehidupan dunia daripada akhirat? (Kesukaan kamu itu salah) kerana kesenangan hidup di dunia ini hanya sedikit jua berbanding dengan (kesenangan hidup) di akhirat kelak.', FALSE, NULL, NULL, 193, 10, 77, 161, FALSE, 0, NULL),
(9, 39, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'إِلَّا تَنفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْئًا وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'If you do not go forth, He will punish you with a painful punishment and will replace you with another people, and you will not harm Him at all. And Allāh is over all things competent.', 'Jika kamu tidak pergi beramai-ramai (untuk berperang pada jalan Allah - membela ugamaNya), Allah akan menyeksa kamu dengan azab seksa yang tidak terperi sakitnya dan Ia akan menggantikan kamu dengan kaum yang lain, dan kamu tidak akan dapat mendatangkan bahaya sedikitpun kepadaNya. Dan (ingatlah) Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 193, 10, 77, 161, FALSE, 0, NULL),
(9, 40, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا فَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ الَّذِينَ كَفَرُوا السُّفْلَىٰ وَكَلِمَةُ اللَّهِ هِيَ الْعُلْيَا وَاللَّهُ عَزِيزٌ حَكِيمٌ', NULL, 'If you do not aid him [i.e., the Prophet (ﷺ)] - Allāh has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he [i.e., Muḥammad (ﷺ)] said to his companion, "Do not grieve; indeed Allāh is with us." And Allāh sent down His tranquility upon him and supported him with soldiers [i.e., angels] you did not see and made the word of those who disbelieved the lowest, while the word of Allāh - that is the highest. And Allāh is Exalted in Might and Wise.', 'Kalau kamu tidak menolongnya (Nabi Muhammad) maka sesungguhnya Allah telahpun menolongnya, iaitu ketika kaum kafir (di Makkah) mengeluarkannya (dari negerinya Makkah) sedang ia salah seorang dari dua (sahabat) semasa mereka berlindung di dalam gua, ketika ia berkata kepada sahabatnya: “Janganlah engkau berdukacita, sesungguhnya Allah bersama kita”. Maka Allah menurunkan semangat tenang tenteram kepada (Nabi Muhammad) dan menguatkannya dengan bantuan tentera (malaikat) yang kamu tidak melihatnya. Dan Allah menjadikan seruan (syirik) orang-orang kafir terkebawah (kalah dengan sehina-hinanya), dan Kalimah Allah (Islam) ialah yang tertinggi (selama-lamanya), kerana Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 193, 10, 77, 161, FALSE, 0, NULL),
(9, 41, 'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'انفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', NULL, 'Go forth, whether light or heavy, and strive with your wealth and your lives in the cause of Allāh. That is better for you, if you only knew.', 'Pergilah kamu beramai-ramai (untuk berperang pada jalan Allah), sama ada dengan keadaan ringan (dan mudah bergerak) ataupun dengan keadaan berat (disebabkan berbagai-bagai tanggungjawab); dan berjihadlah dengan harta benda dan jiwa kamu pada jalan Allah (untuk membela Islam). Yang demikian amatlah baik bagi kamu, jika kamu mengetahui.', FALSE, NULL, NULL, 194, 10, 77, 161, FALSE, 0, NULL),
(9, 42, 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّاتَّبَعُوكَ وَلَٰكِن بَعُدَتْ عَلَيْهِمُ الشُّقَّةُ وَسَيَحْلِفُونَ بِاللَّهِ لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَاللَّهُ يَعْلَمُ إِنَّهُمْ لَكَاذِبُونَ', NULL, 'Had it been a near [i.e., easy] gain and a moderate trip, they [i.e., the hypocrites] would have followed you, but distant to them was the journey. And they will swear by Allāh, "If we were able, we would have gone forth with you," destroying themselves [through false oaths], and Allāh knows that indeed they are liars.', 'Kalau apa yang engkau serukan kepada mereka (wahai Muhammad) sesuatu yang berfaedah yang sudah didapati, dan satu perjalanan yang sederhana (tidak begitu jauh), nescaya mereka (yang munafik itu) akan mengikutmu; tetapi tempat yang hendak dituju itu jauh bagi mereka. Dan mereka akan bersumpah dengan nama Allah dengan berkata: “Kalau kami sanggup, tentulah kami akan pergi bersama kamu”. (Dengan sumpah dusta itu) mereka membinasakan diri mereka sendiri, sedang Allah mengetahui bahawa sesungguhnya mereka itu orang-orang yang berdusta (tentang tidak sanggupnya mengikutmu).', FALSE, NULL, NULL, 194, 10, 77, 161, FALSE, 0, NULL),
(9, 43, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 'عَفَا اللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ الَّذِينَ صَدَقُوا وَتَعْلَمَ الْكَاذِبِينَ', NULL, 'Allāh has pardoned you, [O Muḥammad, but] why did you give them permission [to remain behind]? [You should not have] until it was evident to you who were truthful and you knew [who were] the liars.', 'Allah memaafkanmu (wahai Muhammad), mengapa engkau izinkan mereka (tidak turut berperang) sebelum nyata bagimu orang-orang yang benar dan (sebelum) engkau mengetahui orang-orang yang berdusta?', FALSE, NULL, NULL, 194, 10, 77, 162, FALSE, 0, NULL),
(9, 44, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'لَا يَسْتَأْذِنُكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَن يُجَاهِدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ', NULL, 'Those who believe in Allāh and the Last Day would not ask permission of you to be excused from striving [i.e., fighting] with their wealth and their lives. And Allāh is Knowing of those who fear Him.', 'Orang-orang yang beriman kepada Allah dan hari akhirat, tidak akan meminta izin kepadamu untuk (tidak turut) berjihad dengan harta benda dan jiwa mereka. Dan (ingatlah) Allah Maha Mengetahui akan orang-orang yang bertaqwa.', FALSE, NULL, NULL, 194, 10, 77, 162, FALSE, 0, NULL),
(9, 45, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', 'إِنَّمَا يَسْتَأْذِنُكَ الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَارْتَابَتْ قُلُوبُهُمْ فَهُمْ فِي رَيْبِهِمْ يَتَرَدَّدُونَ', NULL, 'Only those would ask permission of you who do not believe in Allāh and the Last Day and whose hearts have doubted, and they, in their doubt, are hesitating.', 'Sesungguhnya yang akan meminta izin kepadamu hanyalah orang-orang yang tidak beriman kepada Allah dan hari akhirat, dan yang hati mereka (sangat) ragu-ragu. Oleh itu mereka sentiasa bingung teragak-agak dalam keraguannya.', FALSE, NULL, NULL, 194, 10, 77, 162, FALSE, 0, NULL),
(9, 46, 'وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 'وَلَوْ أَرَادُوا الْخُرُوجَ لَأَعَدُّوا لَهُ عُدَّةً وَلَٰكِن كَرِهَ اللَّهُ انبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ اقْعُدُوا مَعَ الْقَاعِدِينَ', NULL, 'And if they had intended to go forth, they would have prepared for it [some] preparation. But Allāh disliked their being sent, so He kept them back, and they were told, "Remain [behind] with those who remain."', 'Dan kalaulah mereka mahu keluar (untuk turut berperang), tentulah mereka menyediakan persiapan untuknya; tetapi Allah tidak suka pemergian mereka, lalu dilemahkanNya semangat mereka, dan dikatakan (oleh Syaitan): “Tinggallah kamu bersama-sama orang-orang yang tinggal”.', FALSE, NULL, NULL, 194, 10, 78, 162, FALSE, 0, NULL),
(9, 47, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'لَوْ خَرَجُوا فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا خِلَالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ', NULL, 'Had they gone forth with you, they would not have increased you except in confusion, and they would have been active among you, seeking [to cause] you fitnah [i.e., chaos and dissension]. And among you are avid listeners to them. And Allāh is Knowing of the wrongdoers.', 'Kalaulah mereka keluar bersama kamu, tidaklah mereka menambahkan kamu melainkan kerosakan, dan tentulah mereka segera menjalankan hasutan di antara kamu, (dengan tujuan) hendak menimbulkan fitnah (kekacauan) dalam kalangan kamu; sedang di antara kamu ada orang yang suka mendengar hasutan mereka. Dan (ingatlah) Allah Maha Mengetahui akan orang-orang yang zalim.', FALSE, NULL, NULL, 194, 10, 78, 162, FALSE, 0, NULL),
(9, 48, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', 'لَقَدِ ابْتَغَوُا الْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا لَكَ الْأُمُورَ حَتَّىٰ جَاءَ الْحَقُّ وَظَهَرَ أَمْرُ اللَّهِ وَهُمْ كَارِهُونَ', NULL, 'They had already desired dissension before and had upset matters for you until the truth came and the ordinance [i.e., victory] of Allāh appeared, while they were averse.', 'Sesungguhnya mereka telah lakukan fitnah semenjak dahulu lagi, dan mereka merancangkan terhadapmu (wahai Muhammad) berbagai tipu daya, sehingga datanglah kebenaran, dan nyatalah (kemenangan) ugama Allah (Islam), sedang mereka tidak suka kepadanya.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 49, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'وَمِنْهُم مَّن يَقُولُ ائْذَن لِّي وَلَا تَفْتِنِّي أَلَا فِي الْفِتْنَةِ سَقَطُوا وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ', NULL, 'And among them is he who says, "Permit me [to remain at home] and do not put me to trial." Unquestionably, into trial they have fallen. And indeed, Hell will encompass the disbelievers.', 'Dan di antara mereka (yang munafik itu) ada yang berkata: “Izinkanlah aku (supaya tidak pergi berperang) dan janganlah engkau menjadikan daku dipengaruhi oleh fitnah”. Ketahuilah, mereka telah pun tercebur ke dalam fitnah (dengan dalihan yang dusta itu). Dan sesungguhnya azab Jahannam meliputi orang-orang yang kafir.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 50, 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا قَدْ أَخَذْنَا أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا وَّهُمْ فَرِحُونَ', NULL, 'If good befalls you, it distresses them; but if disaster strikes you, they say, "We took our matter [in hand] before," and turn away while they are rejoicing.', 'Jika engkau (wahai Muhammad) beroleh sesuatu kebaikan, (maka) kebaikan itu menyebabkan mereka sakit hati; dan jika engkau ditimpa sesuatu bencana, mereka berkata: “Sesungguhnya kami telahpun mengambil keputusan (tidak turut berperang) sebelum itu”, dan mereka berpaling (meninggalkanmu) sambil mereka bergembira.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 51, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'قُل لَّن يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا هُوَ مَوْلَانَا وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ', NULL, 'Say, "Never will we be struck except by what Allāh has decreed for us; He is our protector." And upon Allāh let the believers rely.', 'Katakanlah (wahai Muhammad): “Tidak sekali-kali akan menimpa kami sesuatu pun melainkan apa yang telah ditetapkan Allah bagi kami. Dia lah Pelindung yang menyelamatkan kami, dan (dengan kepercayaan itu) maka kepada Allah jualah hendaknya orang-orang yang beriman bertawakal”.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', 'قُلْ هَلْ تَرَبَّصُونَ بِنَا إِلَّا إِحْدَى الْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ اللَّهُ بِعَذَابٍ مِّنْ عِندِهِ أَوْ بِأَيْدِينَا فَتَرَبَّصُوا إِنَّا مَعَكُم مُّتَرَبِّصُونَ', NULL, 'Say, "Do you await for us except one of the two best things [i.e., martyrdom or victory] while we await for you that Allāh will afflict you with punishment from Himself or at our hands? So wait; indeed we, along with you, are waiting."', 'Katakanlah: “(Sebenarnya) tidak ada yang kamu tunggu-tunggu untuk kami melainkan salah satu dari dua perkara yang sebaik-baiknya (iaitu kemenangan atau mati syahid); dan kami menunggu-nunggu pula untuk kamu bahawa Allah akan menimpakan kamu dengan azab dari sisiNya, atau dengan perantaraan tangan kami. Oleh itu tunggulah, sesungguhnya kami juga menunggu bersama-sama kamu”.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 53, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَٰسِقِينَ', 'قُلْ أَنفِقُوا طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَاسِقِينَ', NULL, 'Say, "Spend willingly or unwillingly; never will it be accepted from you. Indeed, you have been a defiantly disobedient people."', 'Katakanlah: “Dermakanlah harta kamu sama ada dengan sukarela atau kerana terpaksa, tidak sekali-kali akan diterima daripada kamu, (kerana) sesungguhnya kamu adalah orang-orang yang fasik”.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 54, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَارِهُونَ', NULL, 'And what prevents their expenditures from being accepted from them but that they have disbelieved in Allāh and in His Messenger and that they come not to prayer except while they are lazy and that they do not spend except while they are unwilling.', 'Dan tidak ada yang menghalangi mereka, untuk diterima derma-derma mereka melainkan kerana mereka kufur kepada Allah dan RasulNya, dan (kerana) mereka tidak mengerjakan sembahyang melainkan dengan keadaan malas dan mereka pula tidak mendermakan hartanya melainkan dengan perasaan benci.', FALSE, NULL, NULL, 195, 10, 78, 162, FALSE, 0, NULL),
(9, 55, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'فَلَا تُعْجِبْكَ أَمْوَالُهُمْ وَلَا أَوْلَادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُم بِهَا فِي الْحَيَاةِ الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ', NULL, 'So let not their wealth or their children impress you. Allāh only intends to punish them through them in worldly life and that their souls should depart [at death] while they are disbelievers.', 'Oleh itu, janganlah engkau tertarik hati kepada harta benda dan anak-anak mereka, (kerana) sesungguhnya Allah hanya hendak menyeksa mereka dengan harta benda dan anak-anak itu dalam kehidupan dunia, dan hendak menjadikan nyawa mereka tercabut sedang mereka berkeadaan kafir (untuk mendapat azab akhirat pula).', FALSE, NULL, NULL, 196, 10, 78, 162, FALSE, 0, NULL),
(9, 56, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', 'وَيَحْلِفُونَ بِاللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', NULL, 'And they swear by Allāh that they are from among you while they are not from among you; but they are a people who are afraid.', 'Dan mereka (yang munafik itu) bersumpah dengan nama Allah bahawa sesungguhnya mereka dari golongan kamu, padahal mereka bukanlah dari golongan kamu, tetapi mereka ialah suatu kaum yang pengecut.', FALSE, NULL, NULL, 196, 10, 78, 162, FALSE, 0, NULL),
(9, 57, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', 'لَوْ يَجِدُونَ مَلْجَأً أَوْ مَغَارَاتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا إِلَيْهِ وَهُمْ يَجْمَحُونَ', NULL, 'If they could find a refuge or some caves or any place to enter [and hide], they would turn to it while they run heedlessly.', 'Kalau mereka dapat tempat perlindungan, atau gua-gua, atau lubang-lubang dalam tanah, nescaya mereka segera menuju ke arahnya serta melompat masuk ke dalamnya.', FALSE, NULL, NULL, 196, 10, 78, 162, FALSE, 0, NULL),
(9, 58, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', 'وَمِنْهُم مَّن يَلْمِزُكَ فِي الصَّدَقَاتِ فَإِنْ أُعْطُوا مِنْهَا رَضُوا وَإِن لَّمْ يُعْطَوْا مِنْهَا إِذَا هُمْ يَسْخَطُونَ', NULL, 'And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry.', 'Dan di antara mereka ada yang mencelamu (wahai Muhammad) mengenai (pembahagian) sedekah-sedekah (zakat); oleh itu jika mereka diberikan sebahagian daripadanya (menurut kehendak mereka), mereka suka (dan memandangnya adil); dan jika mereka tidak diberikan dari zakat itu (menurut kehendaknya), (maka) dengan serta merta mereka marah.', FALSE, NULL, NULL, 196, 10, 78, 162, FALSE, 0, NULL),
(9, 59, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'وَلَوْ أَنَّهُمْ رَضُوا مَا آتَاهُمُ اللَّهُ وَرَسُولُهُ وَقَالُوا حَسْبُنَا اللَّهُ سَيُؤْتِينَا اللَّهُ مِن فَضْلِهِ وَرَسُولُهُ إِنَّا إِلَى اللَّهِ رَاغِبُونَ', NULL, 'If only they had been satisfied with what Allāh and His Messenger gave them and said, "Sufficient for us is Allāh; Allāh will give us of His bounty, and [so will] His Messenger; indeed, we are desirous toward Allāh," [it would have been better for them].', 'Dan (amatlah baiknya) kalau mereka berpuas hati dengan apa yang diberikan oleh Allah dan RasulNya kepada mereka, sambil mereka berkata: “Cukuplah Allah bagi kami; Allah akan memberi kepada kami dari limpah kurniaNya, demikian juga RasulNya; sesungguhnya kami sentiasa berharap kepada Allah”', FALSE, NULL, NULL, 196, 10, 78, 162, FALSE, 0, NULL),
(9, 60, 'إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ فَرِيضَةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ فَرِيضَةً مِّنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'Zakāh expenditures are only for the poor and for the needy and for those employed for it and for bringing hearts together [for Islām] and for freeing captives [or slaves] and for those in debt and for the cause of Allāh and for the [stranded] traveler - an obligation [imposed] by Allāh. And Allāh is Knowing and Wise.', 'Sesungguhnya sedekah-sedekah (zakat) itu hanyalah untuk orang-orang fakir, dan orang-orang miskin, dan amil-amil yang mengurusnya, dan orang-orang muallaf yang dijinakkan hatinya, dan untuk hamba-hamba yang hendak memerdekakan dirinya, dan orang-orang yang berhutang, dan untuk (dibelanjakan pada) jalan Allah, dan orang-orang musafir (yang keputusan) dalam perjalanan. (Ketetapan hukum yang demikian itu ialah) sebagai satu ketetapan (yang datangnya) dari Allah. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 196, 10, 79, 163, FALSE, 0, NULL),
(9, 61, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', 'وَمِنْهُمُ الَّذِينَ يُؤْذُونَ النَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِاللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ يُؤْذُونَ رَسُولَ اللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'And among them are those who abuse the Prophet and say, "He is an ear." Say, "[It is] an ear of goodness for you that believes in Allāh and believes the believers and [is] a mercy to those who believe among you." And those who abuse the Messenger of Allāh - for them is a painful punishment.', 'Dan di antara mereka (yang munafik itu) ada orang-orang yang menyakiti Nabi sambil mereka berkata: “Bahawa dia (Nabi Muhammad) orang yang suka mendengar (dan percaya pada apa yang didengarnya)”. Katakanlah: “Dia mendengar (dan percaya) apa yang baik bagi kamu, ia beriman kepada Allah dan percaya kepada orang mukmin, dan ia pula menjadi rahmat bagi orang-orang yang beriman di antara kamu”. Dan orang-orang yang menyakiti Rasulullah itu, bagi mereka azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 196, 10, 79, 163, FALSE, 0, NULL),
(9, 62, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 'يَحْلِفُونَ بِاللَّهِ لَكُمْ لِيُرْضُوكُمْ وَاللَّهُ وَرَسُولُهُ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا مُؤْمِنِينَ', NULL, 'They swear by Allāh to you [Muslims] to satisfy you. But Allāh and His Messenger are more worthy for them to satisfy, if they were to be believers.', 'Mereka bersumpah kepada kamu dengan nama Allah untuk mendapat keredaan kamu, padahal Allah dan RasulNya jualah yang lebih berhak mereka mendapat keredaanNya, jika betul mereka orang-orang yang beriman.', FALSE, NULL, NULL, 197, 10, 79, 163, FALSE, 0, NULL),
(9, 63, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 'أَلَمْ يَعْلَمُوا أَنَّهُ مَن يُحَادِدِ اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا ذَٰلِكَ الْخِزْيُ الْعَظِيمُ', NULL, 'Do they not know that whoever opposes Allāh and His Messenger - that for him is the fire of Hell, wherein he will abide eternally? That is the great disgrace.', 'Tidakkah mereka mengetahui bahawa sesiapa yang menentang (perintah-perintah) Allah dan RasulNya, maka sesungguhnya adalah baginya neraka Jahannam serta ia kekal di dalamnya? Balasan yang demikian adalah kehinaan yang besar', FALSE, NULL, NULL, 197, 10, 79, 163, FALSE, 0, NULL),
(9, 64, 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', 'يَحْذَرُ الْمُنَافِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمْ قُلِ اسْتَهْزِئُوا إِنَّ اللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', NULL, 'The hypocrites are apprehensive lest a sūrah be revealed about them, informing them of what is in their hearts. Say, "Mock [as you wish]; indeed, Allāh will expose that which you fear."', 'Orang-orang munafik itu takut kalau diturunkan satu surah Al-Quran yang menerangkan kepada mereka (dan kepada ramai) akan apa yang ada dalam hati mereka (dari kekufuran). Katakanlah (wahai Muhammad): “Ejek-ejeklah (seberapa yang kamu suka), sesungguhnya Allah akan mendedahkan apa yang kamu takut (terdedah untuk pengetahuan ramai)”', FALSE, NULL, NULL, 197, 10, 79, 163, FALSE, 0, NULL),
(9, 65, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ', NULL, 'And if you ask them, they will surely say, "We were only conversing and playing." Say, "Is it Allāh and His verses and His Messenger that you were mocking?"', 'Dan jika engkau bertanya kepada mereka (tentang ejek-ejekan itu) tentulah mereka akan menjawab: “Sesungguhnya kami hanyalah berbual dan bermain-main”. Katakanlah: “Patutkah nama Allah dan ayat-ayatNya serta RasulNya kamu memperolok-olok dan mengejeknya?”', FALSE, NULL, NULL, 197, 10, 79, 163, FALSE, 0, NULL),
(9, 66, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'لَا تَعْتَذِرُوا قَدْ كَفَرْتُم بَعْدَ إِيمَانِكُمْ إِن نَّعْفُ عَن طَائِفَةٍ مِّنكُمْ نُعَذِّبْ طَائِفَةً بِأَنَّهُمْ كَانُوا مُجْرِمِينَ', NULL, 'Make no excuse; you have disbelieved [i.e., rejected faith] after your belief. If We pardon one faction of you - We will punish another faction because they were criminals.', 'Janganlah kamu berdalih (dengan alasan-alasan yang dusta), kerana sesungguhnya kamu telah kufur sesudah kamu (melahirkan) iman. Jika Kami maafkan sepuak dari kamu (kerana mereka bertaubat), maka Kami akan menyeksa puak yang lain, kerana mereka adalah orang-orang yang terus bersalah.', FALSE, NULL, NULL, 197, 10, 79, 163, FALSE, 0, NULL),
(9, 67, 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 'الْمُنَافِقُونَ وَالْمُنَافِقَاتُ بَعْضُهُم مِّن بَعْضٍ يَأْمُرُونَ بِالْمُنكَرِ وَيَنْهَوْنَ عَنِ الْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا اللَّهَ فَنَسِيَهُمْ إِنَّ الْمُنَافِقِينَ هُمُ الْفَاسِقُونَ', NULL, 'The hypocrite men and hypocrite women are of one another. They enjoin what is wrong and forbid what is right and close their hands. They have forgotten Allāh, so He has forgotten them [accordingly]. Indeed, the hypocrites - it is they who are the defiantly disobedient.', 'Orang-orang munafik lelaki dan perempuan, setengahnya adalah sama dengan setengahnya yang lain; mereka masing-masing menyuruh dengan perbuatan yang jahat, dan melarang dari perbuatan yang baik, dan mereka pula menggenggam tangannya (bakhil kedekut). Mereka telah melupakan (tidak menghiraukan perintah) Allah dan Allah juga melupakan (tidak menghiraukan) mereka. Sesungguhnya orang-orang munafik itu, merekalah orang-orang yang fasik.', FALSE, NULL, NULL, 197, 10, 79, 164, FALSE, 0, NULL),
(9, 68, 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا هِىَ حَسْبُهُمْ وَلَعَنَهُمُ ٱللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'وَعَدَ اللَّهُ الْمُنَافِقِينَ وَالْمُنَافِقَاتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ خَالِدِينَ فِيهَا هِيَ حَسْبُهُمْ وَلَعَنَهُمُ اللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ', NULL, 'Allāh has promised the hypocrite men and hypocrite women and the disbelievers the fire of Hell, wherein they will abide eternally. It is sufficient for them. And Allāh has cursed them, and for them is an enduring punishment.', 'Allah menjanjikan orang-orang munafik lelaki dan perempuan serta orang-orang kafir dengan neraka Jahannam, mereka kekal di dalamnya. Cukuplah neraka itu menjadi balasan mereka; dan Allah melaknatkan mereka, dan bagi mereka azab seksa yang kekal.', FALSE, NULL, NULL, 197, 10, 79, 164, FALSE, 0, NULL),
(9, 69, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'كَالَّذِينَ مِن قَبْلِكُمْ كَانُوا أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَالًا وَأَوْلَادًا فَاسْتَمْتَعُوا بِخَلَاقِهِمْ فَاسْتَمْتَعْتُم بِخَلَاقِكُمْ كَمَا اسْتَمْتَعَ الَّذِينَ مِن قَبْلِكُم بِخَلَاقِهِمْ وَخُضْتُمْ كَالَّذِي خَاضُوا أُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ وَأُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, '[You disbelievers are] like those before you; they were stronger than you in power and more abundant in wealth and children. They enjoyed their portion [of worldly enjoyment], and you have enjoyed your portion as those before you enjoyed their portion, and you have engaged [in vanities] like that in which they engaged. [It is] those whose deeds have become worthless in this world and in the Hereafter, and it is they who are the losers.', '(Nasib kamu hai orang-orang munafik) adalah sama dengan nasib orang-orang sebelum kamu (yang telah dibinasakan), mereka lebih kuat serta lebih banyak harta benda dan anak pinak daripada kamu; seterusnya mereka telah bersenang-senang dengan bahagian mereka; maka kamu pula telah bersenang-senang dengan bahagian kamu sebagaimana orang-orang yang sebelum kamu itu bersenang-senang dengan bahagiannya; dan kamu pula telah memperkatakan (perkara yang salah dan dusta) sebagaimana mereka memperkatakannya. Mereka yang demikian, rosak binasalah amal-amalnya (yang baik) di dunia dan di akhirat, dan merekalah orang-orang yang rugi.', FALSE, NULL, NULL, 198, 10, 79, 164, FALSE, 0, NULL),
(9, 70, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَاهِيمَ وَأَصْحَابِ مَدْيَنَ وَالْمُؤْتَفِكَاتِ أَتَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'Has there not reached them the news of those before them - the people of Noah and [the tribes of] ʿAad and Thamūd and the people of Abraham and the companions [i.e., dwellers] of Madyan and the towns overturned? Their messengers came to them with clear proofs. And Allāh would never have wronged them, but they were wronging themselves.', 'Bukankah telah datang kepada mereka berita orang-orang yang terdahulu daripada mereka, iaitu kaum Nabi Nuh dan Aad dan Thamud dan kaum Nabi Ibrahim, dan penduduk negeri Madyan serta negeri-negeri yang telah dibinasakan? (Semuanya) telah datang kepada mereka Rasul-rasul mereka dengan membawa keterangan yang jelas nyata, (lalu mereka mendustakannya dan Tuhan pula membinasakan mereka); Allah tidak sekali-kali menganiaya mereka tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 198, 10, 79, 164, FALSE, 0, NULL),
(9, 71, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَٰئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, 'The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakāh and obey Allāh and His Messenger. Those - Allāh will have mercy upon them. Indeed, Allāh is Exalted in Might and Wise.', 'Dan orang-orang yang beriman, lelaki dan perempuan, setengahnya menjadi penolong bagi setengahnya yang lain; mereka menyuruh berbuat kebaikan, dan melarang daripada berbuat kejahatan; dan mereka mendirikan sembahyang dan memberi zakat, serta taat kepada Allah dan RasulNya. Mereka itu akan diberi rahmat oleh Allah; sesungguhnya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 198, 10, 79, 164, FALSE, 0, NULL),
(9, 72, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'وَعَدَ اللَّهُ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ وَرِضْوَانٌ مِّنَ اللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ', NULL, 'Allāh has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allāh is greater. It is that which is the great attainment.', 'Allah menjanjikan orang-orang yang beriman, lelaki dan perempuan, (akan beroleh) Syurga-syurga yang mengalir di bawahnya beberapa sungai; mereka kekal di dalamnya dan beroleh tempat-tempat yang baik di dalam “Syurga Adn” serta keredaan dari Allah yang lebih besar kemuliaannya; (balasan) yang demikian itulah kejayaan yang besar.', FALSE, NULL, NULL, 198, 10, 79, 164, FALSE, 0, NULL),
(9, 73, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ', NULL, 'O Prophet, fight against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.', 'Wahai Nabi, berjihadlah menentang orang-orang kafir dan orang-orang munafik, dan bertindak keras terhadap mereka. Dan (sebenarnya) tempat mereka ialah neraka Jahannam, dan itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 199, 10, 79, 165, FALSE, 0, NULL),
(9, 74, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'يَحْلِفُونَ بِاللَّهِ مَا قَالُوا وَلَقَدْ قَالُوا كَلِمَةَ الْكُفْرِ وَكَفَرُوا بَعْدَ إِسْلَامِهِمْ وَهَمُّوا بِمَا لَمْ يَنَالُوا وَمَا نَقَمُوا إِلَّا أَنْ أَغْنَاهُمُ اللَّهُ وَرَسُولُهُ مِن فَضْلِهِ فَإِن يَتُوبُوا يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا يُعَذِّبْهُمُ اللَّهُ عَذَابًا أَلِيمًا فِي الدُّنْيَا وَالْآخِرَةِ وَمَا لَهُمْ فِي الْأَرْضِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'They swear by Allāh that they did not say [anything against the Prophet (ﷺ)] while they had said the word of disbelief and disbelieved after their [pretense of] Islām and planned that which they were not to attain. And they were not resentful except [for the fact] that Allāh and His Messenger had enriched them of His bounty. So if they repent, it is better for them; but if they turn away, Allāh will punish them with a painful punishment in this world and the Hereafter. And there will not be for them on earth any protector or helper.', 'Mereka bersumpah dengan nama Allah, bahawa mereka tidak mengatakan (sesuatu yang buruk terhadapmu), padahal sesungguhnya mereka telah mengatakan perkataan kufur, dan mereka pula menjadi kafir sesudah melahirkan Islam, serta mereka berazam untuk melakukan apa yang mereka tidak akan dapat mencapainya (iaitu membunuhmu). Dan tidaklah mereka mencaci dan mencela (Islam) melainkan setelah Allah dan RasulNya memberi kesenangan kepada mereka dari limpah kurniaNya. Oleh itu, jika mereka bertaubat, mereka akan beroleh kebaikan; dan jika mereka berpaling (ingkar), Allah akan menyeksa mereka dengan azab seksa yang tidak terperi sakitnya di dunia dan di akhirat; dan mereka tidak akan mendapat sesiapa pun di bumi ini, yang akan menjadi pelindung dan juga yang menjadi penolong.', FALSE, NULL, NULL, 199, 10, 79, 165, FALSE, 0, NULL),
(9, 75, 'وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 'وَمِنْهُم مَّنْ عَاهَدَ اللَّهَ لَئِنْ آتَانَا مِن فَضْلِهِ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ الصَّالِحِينَ', NULL, 'And among them are those who made a covenant with Allāh, [saying], "If He should give us from His bounty, we will surely spend in charity, and we will surely be among the righteous."', 'Dan di antara mereka ada yang membuat janji dengan Allah dengan berkata: “Sesungguhnya jika Allah memberi kepada kami dari limpah kurniaNya, tentulah kami akan bersedekah, dan tentulah kami akan menjadi dari orang-orang yang soleh”', FALSE, NULL, NULL, 199, 10, 80, 165, FALSE, 0, NULL),
(9, 76, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'فَلَمَّا آتَاهُم مِّن فَضْلِهِ بَخِلُوا بِهِ وَتَوَلَّوا وَّهُم مُّعْرِضُونَ', NULL, 'But when He gave them from His bounty, they were stingy with it and turned away while they refused.', 'Kemudian setelah Allah memberi kepada mereka dari limpah kurniaNya, mereka bakhil dengan pemberian Allah itu, serta mereka membelakangkan janjinya; dan sememangnya mereka orang-orang yang sentiasa membelakangkan (kebajikan).', FALSE, NULL, NULL, 199, 10, 80, 165, FALSE, 0, NULL),
(9, 77, 'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', 'فَأَعْقَبَهُمْ نِفَاقًا فِي قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُ بِمَا أَخْلَفُوا اللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا يَكْذِبُونَ', NULL, 'So He penalized them with hypocrisy in their hearts until the Day they will meet Him - because they failed Allāh in what they promised Him and because they [habitually] used to lie.', 'Akibatnya Allah menimbulkan perasaan munafik dalam hati mereka (berkekalan) hingga ke masa mereka menemui Allah, kerana mereka telah memungkiri apa yang mereka janjikan kepada Allah dan juga kerana mereka sentiasa berdusta.', FALSE, NULL, NULL, 199, 10, 80, 165, FALSE, 0, NULL),
(9, 78, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', 'أَلَمْ يَعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَاهُمْ وَأَنَّ اللَّهَ عَلَّامُ الْغُيُوبِ', NULL, 'Did they not know that Allāh knows their secrets and their private conversations and that Allāh is the Knower of the unseen?', 'Tidakkah mereka mengetahui bahawa Allah sentiasa mengetahui apa yang mereka rahsiakan serta apa yang mereka bisikkan, dan bahawasanya Allah Maha Mengetahui akan perkara-perkara yang ghaib?', FALSE, NULL, NULL, 199, 10, 80, 165, FALSE, 0, NULL),
(9, 79, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ اللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Those who criticize the contributors among the believers concerning [their] charities and [criticize] the ones who find nothing [to spend] except their effort, so they ridicule them - Allāh will ridicule them, and they will have a painful punishment.', 'Orang-orang (munafik) yang mencela sebahagian dari orang-orang yang beriman mengenai sedekah-sedekah yang mereka berikan dengan sukarela, dan (mencela) orang-orang yang tidak dapat (mengadakan apa-apa untuk disedekahkan) kecuali sedikit sekadar kemampuannya, serta mereka mengejek-ejeknya, - Allah akan membalas ejek-ejekan mereka, dan bagi mereka (disediakan) azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 199, 10, 80, 165, FALSE, 0, NULL),
(9, 80, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ اللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ', NULL, 'Ask forgiveness for them, [O Muḥammad], or do not ask forgiveness for them. If you should ask forgiveness for them seventy times - never will Allāh forgive them. That is because they disbelieved in Allāh and His Messenger, and Allāh does not guide the defiantly disobedient people.', '(Orang-orang munafik itu) sama sahaja engkau meminta ampun untuk mereka atau engkau tidak meminta ampun bagi mereka. Jika engkau (wahai Muhammad) meminta ampun bagi mereka tujuh puluh kali (sekalipun) maka Allah tidak sekali-kali mengampunkan mereka; yang demikian itu, kerana mereka telah kufur kepada Allah dan RasulNya; dan Allah tidak akan memberi hidayah petunjuk kepada kaum yang fasik.', FALSE, NULL, NULL, 200, 10, 80, 165, FALSE, 0, NULL),
(9, 81, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا۟ يَفْقَهُونَ', 'فَرِحَ الْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَافَ رَسُولِ اللَّهِ وَكَرِهُوا أَن يُجَاهِدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فِي سَبِيلِ اللَّهِ وَقَالُوا لَا تَنفِرُوا فِي الْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا يَفْقَهُونَ', NULL, 'Those who remained behind rejoiced in their staying [at home] after [the departure of] the Messenger of Allāh and disliked to strive with their wealth and their lives in the cause of Allāh and said, "Do not go forth in the heat." Say, "The fire of Hell is more intense in heat" - if they would but understand.', 'Orang-orang (munafik) yang ditinggalkan (tidak turut berperang) itu, bersukacita disebabkan mereka tinggal di belakang Rasulullah (di Madinah); dan mereka (sememangnya) tidak suka berjihad dengan harta benda dan jiwa mereka pada jalan Allah (dengan sebab kufurnya), dan mereka pula (menghasut dengan) berkata: “Janganlah kamu keluar beramai-ramai (untuk berperang) pada musim panas ini”. Katakanlah (wahai Muhammad): “Api neraka Jahannam lebih panas membakar”, kalaulah mereka itu orang-orang yang memahami.', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 82, 'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا جَزَاءً بِمَا كَانُوا يَكْسِبُونَ', NULL, 'So let them laugh a little and [then] weep much as recompense for what they used to earn.', 'Oleh itu bolehlah mereka ketawa sedikit (di dunia ini) dan mereka akan menangis banyak (di akhirat kelak), sebagai balasan bagi apa yang mereka telah usahakan.', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 83, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 'فَإِن رَّجَعَكَ اللَّهُ إِلَىٰ طَائِفَةٍ مِّنْهُمْ فَاسْتَأْذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا مَعِيَ أَبَدًا وَلَن تُقَاتِلُوا مَعِيَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِالْقُعُودِ أَوَّلَ مَرَّةٍ فَاقْعُدُوا مَعَ الْخَالِفِينَ', NULL, 'If Allāh should return you to a faction of them [after the expedition] and then they ask your permission to go out [to battle], say, "You will not go out with me, ever, and you will never fight with me an enemy. Indeed, you were satisfied with sitting [at home] the first time, so sit [now] with those who stay behind."', 'Maka jika Allah mengembalikan engkau kepada segolongan dari mereka (orang-orang yang munafik itu di Madinah), kemudian mereka meminta izin kepadamu untuk keluar (turut berperang), maka katakanlah: “Kamu tidak sekali-kali akan keluar bersama-samaku selama-lamanya, dan kamu tidak sekali-kali akan memerangi musuh bersama-samaku; sesungguhnya kamu telah bersetuju tinggal pada kali yang pertama, oleh itu duduklah kamu bersama-sama orang-orang yang tinggal”.', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 84, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 'وَلَا تُصَلِّ عَلَىٰ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِ إِنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَمَاتُوا وَهُمْ فَاسِقُونَ', NULL, 'And do not pray [the funeral prayer, O Muḥammad], over any of them who has died - ever - or stand at his grave. Indeed, they disbelieved in Allāh and His Messenger and died while they were defiantly disobedient.', 'Dan janganlah engkau sembahyangkan seorang pun yang mati dari orang-orang munafik itu selama-lamanya, dan janganlah engkau berada di (tepi) kuburnya, kerana sesungguhnya mereka telah kufur kepada Allah dan RasulNya, dan mereka mati sedang mereka dalam keadaan fasik (derhaka).', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 85, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'وَلَا تُعْجِبْكَ أَمْوَالُهُمْ وَأَوْلَادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ أَن يُعَذِّبَهُم بِهَا فِي الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ', NULL, 'And let not their wealth and their children impress you. Allāh only intends to punish them through them in this world and that their souls should depart [at death] while they are disbelievers.', 'Dan janganlah engkau tertarik hati kepada harta benda dan anak-anak mereka, (kerana) sesungguhnya Allah hanya hendak menyeksa mereka dengannya di dunia, dan hendak menjadikan nyawa mereka tercabut sedang mereka dalam keadaan kafir (untuk mendapat azab akhirat pula).', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 86, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', 'وَإِذَا أُنزِلَتْ سُورَةٌ أَنْ آمِنُوا بِاللَّهِ وَجَاهِدُوا مَعَ رَسُولِهِ اسْتَأْذَنَكَ أُولُو الطَّوْلِ مِنْهُمْ وَقَالُوا ذَرْنَا نَكُن مَّعَ الْقَاعِدِينَ', NULL, 'And when a sūrah was revealed [enjoining them] to believe in Allāh and to fight with His Messenger, those of wealth among them asked your permission [to stay back] and said, "Leave us to be with them who sit [at home]."', 'Dan apabila diturunkan satu surah Al-Quran (yang menyuruh mereka): “Berimanlah kamu kepada Allah, dan berjihadlah bersama-sama dengan RasulNya”, nescaya orang-orang yang kaya di antara mereka meminta izin kepadamu dengan berkata: “Biarkanlah kami tinggal bersama-sama orang-orang yang tinggal (tidak turut berperang)”.', FALSE, NULL, NULL, 200, 10, 80, 166, FALSE, 0, NULL),
(9, 87, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'رَضُوا بِأَن يَكُونُوا مَعَ الْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', NULL, 'They were satisfied to be with those who stay behind, and their hearts were sealed over, so they do not understand.', 'Mereka suka tinggal bersama-sama orang-orang yang ditinggalkan (kerana uzur), dan (dengan sebab itu) hati mereka dimeteraikan atasnya, sehingga mereka tidak dapat memahami sesuatu.', FALSE, NULL, NULL, 201, 10, 80, 166, FALSE, 0, NULL),
(9, 88, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'لَٰكِنِ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ جَاهَدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ وَأُولَٰئِكَ لَهُمُ الْخَيْرَاتُ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'But the Messenger and those who believed with him fought with their wealth and their lives. Those will have [all that is] good and it is those who are the successful.', '(Mereka tetap tinggal) tetapi Rasulullah dan orang-orang yang beriman bersamanya, berjihad dengan harta benda dan jiwa mereka; dan mereka itulah orang-orang yang mendapat kebaikan, dan mereka itulah juga yang berjaya.', FALSE, NULL, NULL, 201, 10, 80, 166, FALSE, 0, NULL),
(9, 89, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'أَعَدَّ اللَّهُ لَهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ذَٰلِكَ الْفَوْزُ الْعَظِيمُ', NULL, 'Allāh has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment.', 'Allah telah menyediakan untuk mereka Syurga-syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya; yang demikian itulah kemenangan yang besar.', FALSE, NULL, NULL, 201, 10, 80, 166, FALSE, 0, NULL),
(9, 90, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 'وَجَاءَ الْمُعَذِّرُونَ مِنَ الْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ الَّذِينَ كَذَبُوا اللَّهَ وَرَسُولَهُ سَيُصِيبُ الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابٌ أَلِيمٌ', NULL, 'And those with excuses among the bedouins came to be permitted [to remain], and they who had lied to Allāh and His Messenger sat [at home]. There will strike those who disbelieved among them a painful punishment.', 'Dan datanglah pula orang-orang yang menyatakan uzurnya dari orang-orang “A''raab”, memohon supaya mereka diizinkan (tidak turut berperang), sedang orang-orang (munafik di antara mereka) yang mendustakan Allah dan RasulNya, duduk (mendiamkan diri). (Oleh itu) orang-orang yang kafir di antara mereka, akan dikenakan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 201, 10, 80, 167, FALSE, 0, NULL),
(9, 91, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'لَّيْسَ عَلَى الضُّعَفَاءِ وَلَا عَلَى الْمَرْضَىٰ وَلَا عَلَى الَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا لِلَّهِ وَرَسُولِهِ مَا عَلَى الْمُحْسِنِينَ مِن سَبِيلٍ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'There is not upon the weak or upon the ill or upon those who do not find anything to spend any discomfort [i.e., guilt] when they are sincere to Allāh and His Messenger. There is not upon the doers of good any cause [for blame]. And Allāh is Forgiving and Merciful.', 'Orang-orang yang lemah dan orang-orang yang sakit, dan juga orang-orang yang tidak mempunyai sesuatu yang akan dibelanjakan, tidaklah menanggung dosa (kerana tidak turut berperang) apabila mereka berlaku ikhlas kepada Allah dan RasulNya. Tidak ada jalan sedikitpun bagi menyalahkan orang-orang yang berusaha memperbaiki amalannya; dan Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 201, 10, 80, 167, FALSE, 0, NULL),
(9, 92, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 'وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا وَّأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَنًا أَلَّا يَجِدُوا مَا يُنفِقُونَ', NULL, 'Nor [is there blame] upon those who, when they came to you for you to take them along, you said, "I can find nothing upon which to carry you." They turned back while their eyes overflowed with tears out of grief that they could not find something to spend [for the cause of Allāh].', 'Dan tidak juga berdosa orang-orang yang ketika mereka datang kepadamu (memohon) supaya engkau memberi kenderaan kepada mereka, engkau berkata: “Tidak ada padaku kenderaan yang hendak kuberikan untuk membawa kamu”, mereka kembali sedang mata mereka mengalirkan airmata yang bercucuran, kerana sedih bahawa mereka tidak mempunyai sesuatupun yang hendak mereka belanjakan (untuk pergi berjihad pada jalan Allah).', FALSE, NULL, NULL, 201, 10, 80, 167, FALSE, 0, NULL),
(9, 93, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', 'إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَسْتَأْذِنُونَكَ وَهُمْ أَغْنِيَاءُ رَضُوا بِأَن يَكُونُوا مَعَ الْخَوَالِفِ وَطَبَعَ اللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', NULL, 'The cause [for blame] is only upon those who ask permission of you while they are rich. They are satisfied to be with those who stay behind, and Allāh has sealed over their hearts, so they do not know.', 'Sesungguhnya jalan (untuk menyalahkan dan mengenakan seksa) hanyalah terhadap orang-orang yang meminta izin kepadamu sedang mereka kaya dan mampu. Mereka suka tinggal bersama-sama orang yang ditinggalkan (kerana uzur) dan (dengan sebab itu) Allah meteraikan atas hati mereka, sehingga mereka tidak dapat mengetahui (perkara yang baik).', FALSE, NULL, NULL, 201, 11, 81, 167, FALSE, 0, NULL),
(9, 94, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا اللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ ثُمَّ تُرَدُّونَ إِلَىٰ عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'They will make excuses to you when you have returned to them. Say, "Make no excuse - never will we believe you. Allāh has already informed us of your news [i.e., affair]. And Allāh will observe your deeds, and [so will] His Messenger; then you will be taken back to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."', 'Mereka akan menyatakan uzur kepada kamu, apabila kamu kembali kepada mereka (dari medan perang). Katakanlah (wahai Muhammad): “Janganlah kamu menyatakan uzur lagi, kami tidak sekali-kali akan percaya kepada kamu. Kerana sesungguhnya Allah telah menerangkan kepada kami akan berita-berita perihal kamu; dan Allah serta RasulNya akan melihat amal kamu (sama ada kamu kembali beriman atau tetap kufur); kemudian kamu akan dikembalikan kepada (Allah) Yang Mengetahui perkara-perkara yang ghaib dan yang nyata (untuk menerima balasan), lalu Ia menyatakan kepada kamu apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 95, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ فَأَعْرِضُوا۟ عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ', NULL, 'They will swear by Allāh to you when you return to them that you would leave them alone. So leave them alone; indeed they are evil; and their refuge is Hell as recompense for what they had been earning.', 'Mereka akan bersumpah dengan nama Allah kepada kamu apabila kamu kembali kepada mereka (dari medan perang), supaya kamu berpaling dari mereka (tidak menempelak mereka); oleh itu berpalinglah dari mereka kerana sesungguhnya mereka itu kotor (disebabkan mereka telah sebati dengan kufur); dan tempat kembali mereka pula ialah neraka Jahannam, sebagai balasan bagi apa yang mereka telah usahakan.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 96, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِن تَرْضَوْا عَنْهُمْ فَإِنَّ اللَّهَ لَا يَرْضَىٰ عَنِ الْقَوْمِ الْفَاسِقِينَ', NULL, 'They swear to you so that you might be satisfied with them. But if you should be satisfied with them - indeed, Allāh is not satisfied with a defiantly disobedient people.', 'Mereka bersumpah kepada kamu supaya kamu reda akan mereka; oleh itu jika kamu reda akan mereka, maka sesungguhnya Allah tidak reda akan kaum yang fasik.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 97, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'الْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا حُدُودَ مَا أَنزَلَ اللَّهُ عَلَىٰ رَسُولِهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allāh has revealed to His Messenger. And Allāh is Knowing and Wise.', 'Orang-orang A''raab lebih keras kufurnya dan sikap munafiknya, dan sangatlah patut mereka tidak mengetahui batas-batas (dan hukum-hukum Syarak) yang diturunkan oleh Allah kepada RasulNya. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 98, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'وَمِنَ الْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ الدَّوَائِرَ عَلَيْهِمْ دَائِرَةُ السَّوْءِ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'And among the bedouins are some who consider what they spend as a loss and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allāh is Hearing and Knowing.', 'Dan sebahagian dari orang-orang A''raab (yang munafik) itu memandang apa yang mereka belanjakan (dermakan pada jalan Allah) sebagai satu bayaran yang memberatkan, sambil menunggu peredaran zaman (yang membawa bala bencana) menimpa kamu; atas merekalah (tertimpanya bala bencana yang dibawa oleh) peredaran zaman yang buruk itu. Dan (ingatlah), Allah Maha Mendengar lagi Maha Mengetahui.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 99, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'وَمِنَ الْأَعْرَابِ مَن يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَاتٍ عِندَ اللَّهِ وَصَلَوَاتِ الرَّسُولِ أَلَا إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ اللَّهُ فِي رَحْمَتِهِ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'But among the bedouins are some who believe in Allāh and the Last Day and consider what they spend as means of nearness to Allāh and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allāh will admit them to His mercy. Indeed, Allāh is Forgiving and Merciful.', 'Dan sebahagian dari orang-orang A''raab itu ada yang beriman kepada Allah dan hari akhirat, dan memandang apa yang mereka dermakan (pada jalan Allah itu) sebagai amal-amal bakti (yang mendampingkan) di sisi Allah dan sebagai (satu jalan untuk mendapat) doa dari Rasulullah (yang membawa rahmat kepada mereka) Ketahuilah, sesungguhnya apa yang mereka dermakan itu adalah menjadi amal bakti bagi mereka (yang mendampingkan mereka kepada Allah); Allah akan masukkan mereka ke dalam rahmatNya; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 202, 11, 81, 167, FALSE, 0, NULL),
(9, 100, 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَٰلِكَ الْفَوْزُ الْعَظِيمُ', NULL, 'And the first forerunners [in the faith] among the Muhājireen and the Anṣār and those who followed them with good conduct - Allāh is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', 'Dan orang-orang yang terdahulu - yang mula-mula (berhijrah dan memberi bantuan) dari orang-orang “Muhajirin” dan “Ansar”, dan orang-orang yang menurut (jejak langkah) mereka dengan kebaikan (iman dan taat), Allah reda akan mereka dan mereka pula reda akan Dia, serta Ia menyediakan untuk mereka Syurga-syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya selama-lamanya; itulah kemenangan yang besar.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 101, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ وَمِنْ أَهْلِ ٱلْمَدِينَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', 'وَمِمَّنْ حَوْلَكُم مِّنَ الْأَعْرَابِ مُنَافِقُونَ وَمِنْ أَهْلِ الْمَدِينَةِ مَرَدُوا عَلَى النِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', NULL, 'And among those around you of the bedouins are hypocrites, and [also] from the people of Madīnah. They have persisted in hypocrisy. You, [O Muḥammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment.', 'Dan di antara orang-orang yang di sekeliling kamu dari orang-orang “A''raab” ada yang bersifat munafik dan (demikian juga) sebahagian dari penduduk Madinah; mereka telah berkeras dengan sifat munafik; engkau tidak mengetahui mereka (bahkan) Kamilah yang mengetahui mereka. Kami akan azabkan mereka berulang-ulang, kemudian mereka dikembalikan kepada azab yang besar.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 102, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'وَآخَرُونَ اعْتَرَفُوا بِذُنُوبِهِمْ خَلَطُوا عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا عَسَى اللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'And [there are] others who have acknowledged their sins. They had mixed [i.e., polluted] a righteous deed with another that was bad. Perhaps Allāh will turn to them in forgiveness. Indeed, Allāh is Forgiving and Merciful.', 'Dan (sebahagian) yang lain mengakui dosa-dosa mereka. Mereka telah mencampur adukkan amal yang baik dengan amal yang lain, yang buruk. Mudah-mudahan Allah akan menerima taubat mereka; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 103, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَاتَكَ سَكَنٌ لَّهُمْ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'Take, [O Muḥammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allāh''s blessings] upon them. Indeed, your invocations are reassurance for them. And Allāh is Hearing and Knowing.', 'Ambilah (sebahagian) dari harta mereka menjadi sedekah (zakat), supaya dengannya engkau membersihkan mereka (dari dosa) dan mensucikan mereka (dari akhlak yang buruk); dan doakanlah untuk mereka, kerana sesungguhnya doamu itu menjadi ketenteraman bagi mereka. Dan (ingatlah) Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 104, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'أَلَمْ يَعْلَمُوا أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَأْخُذُ الصَّدَقَاتِ وَأَنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ', NULL, 'Do they not know that it is Allāh who accepts repentance from His servants and receives charities and that it is Allāh who is the Accepting of Repentance, the Merciful?', 'Tidakkah mereka mengetahui bahawa Allah Dia lah yang menerima taubat dari hamba-hambaNya, dan juga menerima sedekah-sedekah (dan zakat serta membalasnya), dan bahawa sesungguhnya Allah Dia lah Penerima taubat, lagi Maha Mengasihani?', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 105, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'And say, "Do [as you will], for Allāh will see your deeds, and [so will] His Messenger and the believers. And you will be returned to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."', 'Dan katakanlah (wahai Muhammad): Beramallah kamu (akan segala yang diperintahkan), maka Allah dan RasulNya serta orang-orang yang beriman akan melihat apa yang kamu kerjakan; dan kamu akan dikembalikan kepada (Allah) Yang Mengetahui perkara-perkara yang ghaib dan yang nyata, kemudian Ia menerangkan kepada kamu apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 106, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'وَآخَرُونَ مُرْجَوْنَ لِأَمْرِ اللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'And [there are] others deferred until the command of Allāh - whether He will punish them or whether He will forgive them. And Allāh is Knowing and Wise.', 'Dan segolongan yang lain (dari orang-orang yang tidak turut berperang); ditempohkan keputusan mengenai mereka kerana menunggu perintah Allah; sama ada dia mengazabkan mereka ataupun Ia menerima taubat mereka. Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 203, 11, 81, 168, FALSE, 0, NULL),
(9, 107, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 'وَالَّذِينَ اتَّخَذُوا مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًا بَيْنَ الْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ اللَّهَ وَرَسُولَهُ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَا إِلَّا الْحُسْنَىٰ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ', NULL, 'And [there are] those [hypocrites] who took for themselves a mosque for causing harm and disbelief and division among the believers and as a station for whoever had warred against Allāh and His Messenger before. And they will surely swear, "We intended only the best." And Allāh testifies that indeed they are liars.', 'Dan (di antara orang-orang munafik juga ialah) orang-orang yang membina masjid dengan tujuan membahayakan (keselamatan orang-orang Islam), dan (menguatkan) keingkaran (mereka sendiri) serta memecah-belahkan perpaduan orang-orang yang beriman, dan juga untuk (dijadikan tempat) intipan bagi orang yang telah memerangi Allah dan RasulNya sebelum itu. Dan (apabila tujuan mereka yang buruk itu ketara), mereka akan bersumpah dengan berkata: “Tidaklah yang kami kehendaki (dengan mendirikan masjid ini) melainkan untuk kebaikan semata-mata”. Padahal Allah menyaksikan, bahawa sesungguhnya mereka adalah berdusta.', FALSE, NULL, NULL, 204, 11, 81, 168, FALSE, 0, NULL),
(9, 108, 'لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', 'لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ', NULL, 'Do not stand [for prayer] within it - ever. A mosque founded on righteousness from the first day is more worthy for you to stand in. Within it are men who love to purify themselves; and Allāh loves those who purify themselves.', 'Jangan engkau sembahyang di masjid itu selama-lamanya, kerana sesungguhnya masjid (Qubaa'' yang engkau bina wahai Muhammad), yang telah didirikan di atas dasar taqwa dari mula (wujudnya), sudah sepatutnya engkau sembahyang padanya. Di dalam masjid itu ada orang-orang lelaki yang suka (mengambil berat) membersihkan (mensucikan) dirinya; dan Allah Mengasihi orang-orang yang membersihkan diri mereka (zahir dan batin).', FALSE, NULL, NULL, 204, 11, 81, 168, FALSE, 0, NULL),
(9, 109, 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'أَفَمَنْ أَسَّسَ بُنْيَانَهُ عَلَىٰ تَقْوَىٰ مِنَ اللَّهِ وَرِضْوَانٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَانَهُ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَانْهَارَ بِهِ فِي نَارِ جَهَنَّمَ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'Then is one who laid the foundation of his building on righteousness [with fear] from Allāh and [seeking] His approval better or one who laid the foundation of his building on the edge of a bank about to collapse, so it collapsed with him into the fire of Hell? And Allāh does not guide the wrongdoing people.', 'Maka adakah orang yang membangunkan masjid yang didirikannya di atas dasar taqwa kepada Allah dan (untuk mencari) keredaan Allah itu lebih baik, ataukah orang yang membangunkan masjid yang didirikannya di tepi jurang yang (hampir) runtuh, lalu runtuhlah ia dengan yang membangunkannya ke dalam api neraka? Dan (ingatlah) Allah tidak akan memberi hidayah petunjuk kepada orang-orang yang zalim.', FALSE, NULL, NULL, 204, 11, 81, 168, FALSE, 0, NULL),
(9, 110, 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'لَا يَزَالُ بُنْيَانُهُمُ الَّذِي بَنَوْا رِيبَةً فِي قُلُوبِهِمْ إِلَّا أَن تَقَطَّعَ قُلُوبُهُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'Their building which they built will not cease to be a [cause of] skepticism in their hearts until their hearts are cut [i.e., stopped]. And Allāh is Knowing and Wise.', '(Keruntuhan masjid) yang dibina oleh mereka yang munafik itu sentiasa menjadi penyakit syak dan keluh-kesah (lebih daripada yang sedia ada) dalam hati mereka, (dan tidak akan habis) kecuali (apabila) hati mereka hancur-luluh (dalam tanah). Dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 204, 11, 81, 168, FALSE, 0, NULL),
(9, 111, 'إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالْإِنجِيلِ وَالْقُرْآنِ وَمَنْ أَوْفَىٰ بِعَهْدِهِ مِنَ اللَّهِ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذِي بَايَعْتُم بِهِ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ', NULL, 'Indeed, Allāh has purchased from the believers their lives and their properties [in exchange] for that they will have Paradise. They fight in the cause of Allāh, so they kill and are killed. [It is] a true promise [binding] upon Him in the Torah and the Gospel and the Qur’ān. And who is truer to his covenant than Allāh? So rejoice in your transaction which you have contracted. And it is that which is the great attainment.', 'Sesungguhnya Allah telah membeli dari orang-orang yang beriman akan jiwa mereka dan harta benda mereka dengan (balasan) bahawa mereka akan beroleh Syurga, (disebabkan) mereka berjuang pada jalan Allah maka (di antara) mereka ada yang membunuh dan terbunuh. (Balasan Syurga yang demikian ialah) sebagai janji yang benar yang ditetapkan oleh Allah di dalam (Kitab-kitab) Taurat dan Injil serta Al-Quran; dan siapakah lagi yang lebih menyempurnakan janjinya daripada Allah? Oleh itu, bergembiralah dengan jualan yang kamu jalankan jual-belinya itu, dan (ketahuilah bahawa) jual-beli (yang seperti itu) ialah kemenangan yang besar.', FALSE, NULL, NULL, 204, 11, 82, 169, FALSE, 0, NULL),
(9, 112, 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'التَّائِبُونَ الْعَابِدُونَ الْحَامِدُونَ السَّائِحُونَ الرَّاكِعُونَ السَّاجِدُونَ الْآمِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ الْمُنكَرِ وَالْحَافِظُونَ لِحُدُودِ اللَّهِ وَبَشِّرِ الْمُؤْمِنِينَ', NULL, '[Such believers are] the repentant, the worshippers, the praisers [of Allāh], the travelers [for His cause], those who bow and prostrate [in prayer], those who enjoin what is right and forbid what is wrong, and those who observe the limits [set by] Allāh. And give good tidings to the believers.', '(Mereka itu ialah): orang-orang yang bertaubat, yang beribadat, yang memuji Allah, yang mengembara (untuk menuntut ilmu dan mengembangkan Islam), yang rukuk, yang sujud, yang menyuruh berbuat kebaikan dan yang melarang daripada kejahatan, serta yang menjaga batas-batas hukum Allah. Dan gembirakanlah orang-orang yang beriman (yang bersifat demikian).', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 113, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', 'مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ', NULL, 'It is not for the Prophet and those who have believed to ask forgiveness for the polytheists, even if they were relatives, after it has become clear to them that they are companions of Hellfire.', 'Tidaklah dibenarkan bagi Nabi dan orang-orang yang beriman, meminta ampun bagi orang-orang musyrik, sekalipun orang itu kaum kerabat sendiri, sesudah nyata bagi mereka bahawa orang-orang musyrik itu adalah ahli neraka.', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 114, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ', 'وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَا إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَاهِيمَ لَأَوَّاهٌ حَلِيمٌ', NULL, 'And the request of forgiveness of Abraham for his father was only because of a promise he had made to him. But when it became apparent to him [i.e., Abraham] that he [i.e., the father] was an enemy to Allāh, he disassociated himself from him. Indeed was Abraham compassionate and patient.', 'Dan bukanlah istighfar Nabi Ibrahim bagi bapanya (dibuat) melainkan kerana adanya janji yang dijanjikan kepadanya; dan apabila ternyata kepada Nabi Ibrahim bahawa bapanya musuh bagi Allah, ia pun berlepas diri daripadanya. Sesungguhnya Nabi Ibrahim itu lembut hati lagi penyabar.', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 115, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'وَمَا كَانَ اللَّهُ لِيُضِلَّ قَوْمًا بَعْدَ إِذْ هَدَاهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'And Allāh would not let a people stray after He has guided them until He makes clear to them what they should avoid. Indeed, Allāh is Knowing of all things.', 'Dan Allah tidak sekali-kali menjadikan sesuatu kaum itu sesat sesudah Ia memberi hidayah petunjuk kepada mereka, sebelum Ia menerangkan kepada mereka apa yang mereka wajib memelihara dan melindungi diri daripadanya; sesungguhnya Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 116, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'إِنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يُحْيِي وَيُمِيتُ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'Indeed, to Allāh belongs the dominion of the heavens and the earth; He gives life and causes death. And you have not besides Allāh any protector or any helper.', 'Sesungguhnya Allah jualah yang menguasai segala alam langit dan bumi; Ia menghidupkan dan mematikan; dan tidaklah ada bagi kamu selain dari Allah sesiapa pun yang menjadi pelindung dan juga yang menjadi penolong.', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ', 'لَّقَد تَّابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِن بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَّحِيمٌ', NULL, 'Allāh has already forgiven the Prophet and the Muhājireen and the Anṣār who followed him in the hour of difficulty after the hearts of a party of them had almost inclined [to doubt], and then He forgave them. Indeed, He was to them Kind and Merciful.', 'Sesungguhnya Allah telah menerima taubat Nabi dan orang-orang Muhajirin dan Ansar yang mengikutnya (berjuang) dalam masa kesukaran, sesudah hampir-hampir terpesong hati segolongan dari mereka (daripada menurut Nabi untuk berjuang); kemudian Allah menerima taubat mereka; sesungguhnya Allah Amat belas, lagi Maha Mengasihani terhadap mereka.', FALSE, NULL, NULL, 205, 11, 82, 169, FALSE, 0, NULL),
(9, 118, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوا أَن لَّا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا إِنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ', NULL, 'And [He also forgave] the three who were left alone [i.e., boycotted, regretting their error] to the point that the earth closed in on them in spite of its vastness and their souls confined [i.e., anguished] them and they were certain that there is no refuge from Allāh except in Him. Then He turned to them so they could repent. Indeed, Allāh is the Accepting of Repentance, the Merciful.', 'Dan (Allah menerima pula taubat) tiga orang yang ditangguhkan (penerimaan taubat mereka) hingga apabila bumi yang luas ini (terasa) sempit kepada mereka (kerana mereka dipulaukan), dan hati mereka pula menjadi sempit (kerana menanggung dukacita), serta mereka yakin bahawa tidak ada tempat untuk mereka lari dari (kemurkaan) Allah melainkan (kembali bertaubat) kepadaNya; kemudian Allah (memberi taufiq serta) menerima taubat mereka supaya mereka kekal bertaubat. Sesungguhnya Allah Dia lah Penerima taubat lagi Maha Mengasihani.', FALSE, NULL, NULL, 206, 11, 82, 169, FALSE, 0, NULL),
(9, 119, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ', NULL, 'O you who have believed, fear Allāh and be with those who are true.', 'Wahai orang-orang yang beriman! Bertaqwalah kamu kepada Allah, dan hendaklah kamu berada bersama-sama orang-orang yang benar.', FALSE, NULL, NULL, 206, 11, 82, 170, FALSE, 0, NULL),
(9, 120, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَٰلِحٌ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'مَا كَانَ لِأَهْلِ الْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ الْأَعْرَابِ أَن يَتَخَلَّفُوا عَن رَّسُولِ اللَّهِ وَلَا يَرْغَبُوا بِأَنفُسِهِمْ عَن نَّفْسِهِ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِي سَبِيلِ اللَّهِ وَلَا يَطَئُونَ مَوْطِئًا يَغِيظُ الْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِ عَمَلٌ صَالِحٌ إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ', NULL, 'It was not [proper] for the people of Madīnah and those surrounding them of the bedouins that they remain behind after [the departure of] the Messenger of Allāh or that they prefer themselves over his self. That is because they are not afflicted by thirst or fatigue or hunger in the cause of Allāh, nor do they tread on any ground that enrages the disbelievers, nor do they inflict upon an enemy any infliction but that it is registered for them as a righteous deed. Indeed, Allāh does not allow to be lost the reward of the doers of good.', 'Tidaklah patut bagi penduduk Madinah dan orang-orang yang di sekeliling mereka dari orang-orang “A''raab” ketinggalan daripada (turut berperang bersama) Rasulullah; dan tidaklah patut mereka mengasihi diri mereka sendiri dengan tidak menghiraukan Rasulullah. Yang demikian kerana sesungguhnya (tiap-tiap kali) mereka merasai dahaga, dan merasai penat lelah, dan juga merasai lapar (dalam perjuangan) pada jalan Allah; dan (tiap-tiap kali) mereka menjejak sesuatu tempat yang menimbulkan kemarahan orang-orang kafir; dan juga (tiap-tiap kali) mereka menderita sesuatu yang mencederakan dari pihak musuh - melainkan semuanya itu ditulis bagi mereka: (pahala) amal yang soleh. Sesungguhnya Allah tidak menghilangkan pahala orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 206, 11, 82, 170, FALSE, 0, NULL),
(9, 121, 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا كَانُوا يَعْمَلُونَ', NULL, 'Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allāh may reward them for the best of what they were doing.', 'Dan tidak pula mereka membelanjakan sesuatu perbelanjaan yang kecil, atau yang besar; dan tidak mereka melintas sesuatu lembah, melainkan ditulis pahala bagi mereka, supaya Allah membalas dengan balasan yang lebih baik dari apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 206, 11, 82, 170, FALSE, 0, NULL),
(9, 122, 'وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', 'وَمَا كَانَ الْمُؤْمِنُونَ لِيَنفِرُوا كَافَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَائِفَةٌ لِّيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', NULL, 'And it is not for the believers to go forth [to battle] all at once. For there should separate from every division of them a group [remaining] to obtain understanding in the religion and warn [i.e., advise] their people when they return to them that they might be cautious.', 'Dan tidaklah (betul dan elok) orang-orang yang beriman keluar semuanya (pergi berperang); oleh itu, hendaklah keluar sebahagian sahaja dari tiap-tiap puak di antara mereka, supaya orang-orang (yang tinggal) itu mempelajari secara mendalam ilmu yang dituntut di dalam ugama, dan supaya mereka dapat mengajar kaumnya (yang keluar berjuang) apabila orang-orang itu kembali kepada mereka; mudah-mudahan mereka dapat berjaga-jaga (dari melakukan larangan Allah).', FALSE, NULL, NULL, 206, 11, 83, 170, FALSE, 0, NULL),
(9, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا قَاتِلُوا الَّذِينَ يَلُونَكُم مِّنَ الْكُفَّارِ وَلْيَجِدُوا فِيكُمْ غِلْظَةً وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ', NULL, 'O you who have believed, fight against those adjacent to you of the disbelievers and let them find in you harshness. And know that Allāh is with the righteous.', 'Wahai orang-orang yang beriman! Perangilah orang-orang kafir musyrik yang berdekatan dengan kamu; dan biarlah mereka merasai sikap kekerasan (serta ketabahan hati) yang ada pada kamu; dan ketahuilah sesungguhnya Allah beserta orang-orang yang bertaqwa (dengan memberikan pertolonganNya).', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 124, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًا وَهُمْ يَسْتَبْشِرُونَ', 'وَإِذَا مَا أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِ إِيمَانًا فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا وَهُمْ يَسْتَبْشِرُونَ', NULL, 'And whenever a sūrah is revealed, there are among them [i.e., the hypocrites] those who say, "Which of you has this increased in faith?" As for those who believed, it has increased them in faith, while they are rejoicing.', 'Dan apabila diturunkan sesuatu surah (dari Al-Quran) maka di antara mereka (yang munafik) ada yang bertanya (secara mengejek): “Siapakah di antara kamu yang imannya bertambah disebabkan oleh surah ini?” Adapun orang-orang yang beriman, maka surah itu menambahkan iman mereka, sedang mereka bergembira (dengan turunnya).', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 125, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', 'وَأَمَّا الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا وَهُمْ كَافِرُونَ', NULL, 'But as for those in whose hearts is disease, it has [only] increased them in evil [in addition] to their evil. And they will have died while they are disbelievers.', 'Adapun orang-orang yang ada penyakit (kufur) dalam hati mereka maka surah Al-Quran itu menambahkan kekotoran (kufur) kepada kekotoran (kufur) yang ada pada mereka; dan mereka mati, sedang mereka berkeadaan kafir.', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 126, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِي كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', NULL, 'Do they not see that they are tried every year once or twice but then they do not repent nor do they remember?', 'Dan (patutkah) mereka (berdegil) tidak mahu memperhatikan, bahawa mereka dicuba (dengan berbagai-bagai bencana) pada tiap-tiap tahun, sekali atau dua kali; kemudian mereka tidak juga bertaubat, dan tidak pula mereka mahu beringat (dan insaf)?', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 127, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'وَإِذَا مَا أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَاكُم مِّنْ أَحَدٍ ثُمَّ انصَرَفُوا صَرَفَ اللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', NULL, 'And whenever a sūrah is revealed, they look at each other, [as if saying], "Does anyone see you?" and then they dismiss themselves. Allāh has dismissed their hearts because they are a people who do not understand.', 'Dan apabila diturunkan satu surah dari Al-Quran (mendedahkan keburukan orang-orang munafik itu) setengah mereka memandang kepada setengahnya yang lain sambil berkata: “Adakah sesiapa nampak kamu (kalau kita undur dari sini)?” Kemudian mereka berpaling pergi (dengan meninggalkan majlis Nabi); Allah memalingkan hati mereka (daripada iman), disebabkan mereka kaum yang tidak (mahu) mengerti.', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 128, 'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', 'لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', NULL, 'There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; [he is] concerned over you [i.e., your guidance] and to the believers is kind and merciful.', 'Sesungguhnya telah datang kepada kamu seorang Rasul dari golongan kamu sendiri (iaitu Nabi Muhammad s.a.w), yang menjadi sangat berat kepadanya sebarang kesusahan yang ditanggung oleh kamu, yang sangat tamak (inginkan) kebaikan bagi kamu, (dan) ia pula menumpahkan perasaan belas serta kasih sayangnya kepada orang-orang yang beriman.', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(9, 129, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'فَإِن تَوَلَّوْا فَقُلْ حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', NULL, 'But if they turn away, [O Muḥammad], say, "Sufficient for me is Allāh; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne."', 'Kemudian jika mereka berpaling ingkar, maka katakanlah (wahai Muhammad): “cukuplah bagiku Allah (yang menolong dan memeliharaku), tiada Tuhan (yang berhak disembah) melainkan Dia; kepadaNya aku berserah diri, dan Dia lah yang mempunyai Arasy yang besar.”', FALSE, NULL, NULL, 207, 11, 83, 171, FALSE, 0, NULL),
(10, 1, 'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ', 'الر تلك ايات الكتاب الحكيم', NULL, 'Alif, Lām, Rā. These are the verses of the wise Book.', 'Alif, Laam Raa'' ini ialah ayat-ayat Kitab (Al-Quran) yang mengandungi hikmat-hikmat dan kebenaran yang tetap teguh.', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 5, NULL),
(10, 2, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرٌ مُّبِينٌ', 'اكان للناس عجبا ان اوحينا الى رجل منهم ان انذر الناس وبشر الذين امنوا ان لهم قدم صدق عند ربهم قال الكافرون ان هذا لساحر مبين', NULL, 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."', 'Tidaklah patut adanya pada manusia yang ingkar itu perasaan hairan disebabkan Kami telah wahyukan kepada seorang lelaki dari jenis mereka (Nabi Muhammad, dengan berfirman kepadanya): “Berilah amaran kepada umat manusia (yang ingkar, dengan balasan azab) dan sampaikanlah berita yang mengembirakan kepada orang-orang yang beriman, bahawa bagi mereka ada persediaan yang sungguh mulia di sisi Tuhan mereka (disebabkan amal-amal soleh yang mereka kerjakan). (Setelah Nabi Muhammad memberi amaran dan menyampaikan berita yang mengembirakan) berkatalah orang-orang kafir (yang merasa hairan) itu: “Sebenarnya (Al-Quran) ini ialah sihir yang terang nyata.”', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 26, NULL),
(10, 3, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ', 'ان ربكم الله الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يدبر الامر ما من شفيع الا من بعد اذنه ذلكم الله ربكم فاعبدوه افلا تذكرون', NULL, 'Indeed, your Lord is Allāh, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allāh, your Lord, so worship Him. Then will you not remember?', 'Sesungguhnya Tuhan kamu ialah Allah yang menjadikan langit dan bumi dalam enam masa kemudian Ia bersemayam di atas Arasy mentadbirkan segala urusan. Tidak ada sesiapa pun yang dapat memberi syafaat melainkan sesudah diizinkanNya. (Yang bersifat demikian) itulah Allah, Tuhan (yang memelihara dan mentadbirkan keadaan) kamu; maka tunduklah dan taatlah kamu kepada perintahNya; patutkah kamu - setelah mengetahui kenyataan yang tersebut tidak mahu mengingatiNya?', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 29, NULL),
(10, 4, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'اليه مرجعكم جميعا وعد الله حقا انه يبدا الخلق ثم يعيده ليجزي الذين امنوا وعملوا الصالحات بالقسط والذين كفروا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون', NULL, 'To Him is your return all together. [It is] the promise of Allāh [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.', 'KepadaNyalah kembalinya kamu semua, sebagai janji Allah yang benar. Sesungguhnya Dia lah yang memulakan kejadian sekalian makhluk, kemudian Ia mengembalikannya (hidup semula sesudah matinya), untuk membalas orang-orang yang beriman dan beramal soleh dengan adil; dan orang-orang yang kafir pula, disediakan bagi mereka minuman dari air panas yang menggelegak, dan azab yang tidak terperi sakitnya, disebabkan mereka ingkar dan berlaku kufur.', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 28, NULL),
(10, 5, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ', 'هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك الا بالحق يفصل الايات لقوم يعلمون', NULL, 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allāh has not created this except in truth. He details the signs for a people who know.', 'Dia lah yang menjadikan matahari bersinar-sinar (terang-benderang) dan bulan bercahaya, dan Dia lah yang menentukan perjalanan tiap-tiap satu itu (berpindah-randah) pada tempat-tempat peredarannya masing-masing) supaya kamu dapat mengetahui bilangan tahun dan kiraan masa. Allah tidak menjadikan semuanya itu melainkan dengan adanya faedah dan gunanya yang sebenar. Allah menjelaskan ayat-ayatNya (tanda-tanda kebesaranNya) satu persatu bagi kaum yang mahu mengetahui (hikmat sesuatu yang dijadikanNya).', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 23, NULL),
(10, 6, 'إِنَّ فِى ٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَّقُونَ', 'ان في اختلاف الليل والنهار وما خلق الله في السماوات والارض لايات لقوم يتقون', NULL, 'Indeed, in the alternation of the night and the day and [in] what Allāh has created in the heavens and the earth are signs for a people who fear Allāh.', 'Sesungguhnya pada pertukaran malam dan siang silih berganti, dan pada segala yang dijadikan oleh Allah di langit dan di bumi, ada tanda-tanda (yang menunjukkan undang-undang dan peraturan Allah) kepada kaum yang mahu bertaqwa.', FALSE, NULL, NULL, 208, 11, 83, 172, FALSE, 14, NULL),
(10, 7, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَـٰتِنَا غَـٰفِلُونَ', 'ان الذين لا يرجون لقاءنا ورضوا بالحياة الدنيا واطمانوا بها والذين هم عن اياتنا غافلون', NULL, 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs -', 'Sesungguhnya orang-orang yang tidak menaruh ingatan akan menemui Kami (pada hari akhirat untuk menerima balasan), dan yang reda (berpuashati) dengan kehidupan dunia semata-mata serta merasa tenang tenteram dengannya, dan orang-orang yang tidak mengindahkan ayat-ayat (keterangan dan tanda-tanda kekuasasaan) Kami, -', FALSE, NULL, NULL, 209, 11, 83, 172, FALSE, 15, NULL),
(10, 8, 'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', 'اولئك ماواهم النار بما كانوا يكسبون', NULL, 'For those their refuge will be the Fire because of what they used to earn.', 'Mereka yang demikian keadaannya (di dunia), tempat kediaman mereka (di akhirat) ialah neraka; disebabkan keingkaran dan kederhakaan yang mereka telah lakukan.', FALSE, NULL, NULL, 209, 11, 83, 172, FALSE, 6, NULL),
(10, 9, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَـٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ فِى جَنَّـٰتِ ٱلنَّعِيمِ', 'ان الذين امنوا وعملوا الصالحات يهديهم ربهم بايمانهم تجري من تحتهم الانهار في جنات النعيم', NULL, 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure.', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, Tuhan mereka akan memimpin mereka dengan sebab iman mereka yang sempurna itu. (Mereka masuk ke taman yang) sungai-sungainya mengalir di bawah tempat kediaman mereka di dalam Syurga yang penuh nikmat.', FALSE, NULL, NULL, 209, 11, 83, 172, FALSE, 15, NULL),
(10, 10, 'دَعْوَىٰهُمْ فِيهَا سُبْحَـٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ', 'دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام واخر دعواهم ان الحمد لله رب العالمين', NULL, 'Their call therein will be, "Exalted are You, O Allāh," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allāh, Lord of the worlds!"', 'Doa ucapan mereka di dalam Syurga itu ialah Maha Suci Engkau dari segala kekurangan wahai Tuhan! Dan ucapan penghormatan mereka padanya ialah: Selamat sejahtera! Dan akhir doa mereka ialah segala puji dipersembahkan kepada Allah yang memelihara dan mentadbirkan sekalian alam!', FALSE, NULL, NULL, 209, 11, 83, 172, FALSE, 14, NULL),
(10, 11, '۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ', 'ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقاءنا في طغيانهم يعمهون', NULL, 'And if Allāh was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly.', 'Dan kalau Allah menyegerakan bagi manusia azab sengsara yang mereka minta disegerakan, sebagaimana mereka minta disegerakan nikmat kesenangan, nescaya binasalah mereka dan selesailah ajal mereka. Oleh itu, (Kami tidak menyegerakan azab yang dimintanya), Kami biarkan orang-orang yang tidak menaruh ingatan menemui Kami itu meraba-raba dalam kesesatannya.', FALSE, NULL, NULL, 209, 11, 84, 173, FALSE, 18, NULL),
(10, 12, 'وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'واذا مس الانسان الضر دعانا لجنبه او قاعدا او قائما فلما كشفنا عنه ضره مر كان لم يدعنا الى ضر مسه كذلك زين للمسرفين ما كانوا يعملون', NULL, 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing.', 'Dan apabila seseorang manusia ditimpa kesusahan, merayulah ia ditimpa Kami (dalam segala keadaan), sama ada ia sedang berbaring atau duduk ataupun berdiri; dan manakala Kami hapuskan kesusahan itu daripadanya, ia terus membawa cara lamanya seolah-olah dia tidak pernah merayu kepada Kami memohon hapuskan sebarang kesusahan yang menimpanya (sebagaimana ia memandang eloknya bawaan itu) demikianlah diperelokkan pada pandangan orang-orang yang melampau apa yang mereka lakukan.', FALSE, NULL, NULL, 209, 11, 84, 173, FALSE, 27, NULL),
(10, 13, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'ولقد اهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين', NULL, 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people.', 'Dan sesungguhnya Kami telah membinasakan umat-umat yang terdahulu daripada kamu semasa mereka berlaku zalim padahal telah datang kepada mereka Rasul-rasul mereka membawa keterangan-keterangan, dan mereka masih juga tidak beriman. Demikianlah Kami membalas kaum yang melakukan kesalahan.', FALSE, NULL, NULL, 209, 11, 84, 173, FALSE, 17, NULL),
(10, 14, 'ثُمَّ جَعَلْنَـٰكُمْ خَلَـٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 'ثم جعلناكم خلائف في الارض من بعدهم لننظر كيف تعملون', NULL, 'Then We made you successors in the land after them so that We may observe how you will do.', 'Kemudian Kami jadikan kamu (wahai umat Muhammad) khalifah-khalifah di bumi menggantikan mereka yang telah dibinasakan itu, supaya Kami melihat apa pula corak dan bentuk kelakuan yang kamu akan lakukan.', FALSE, NULL, NULL, 209, 11, 84, 173, FALSE, 10, NULL),
(10, 15, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَـٰتٍ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَـٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'واذا تتلى عليهم اياتنا بينات قال الذين لا يرجون لقاءنا ائت بقران غير هذا او بدله قل ما يكون لي ان ابدله من تلقاء نفسي ان اتبع الا ما يوحى الي اني اخاف ان عصيت ربي عذاب يوم عظيم', NULL, 'And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, "Bring us a Qur’ān other than this or change it." Say, [O Muḥammad], "It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas nyata, berkatalah orang-orang yang tidak menaruh ingatan menemui Kami (untuk menerima balasan): “Bawalah Quran yang lain daripada ini atau tukarkanlah dia”. Katakanlah (wahai Muhammad): “Aku tidak berhak menukarkannya dengan kemahuanku sendiri, aku hanya tetap menurut apa yang diwahyukan kepadaku sahaja. Sesungguhnya aku takut, - jika aku menderhaka kepada Tuhanku, - akan azab hari yang besar (soal jawabnya)”.', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 39, NULL),
(10, 16, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', 'قل لو شاء الله ما تلوته عليكم ولا ادراكم به فقد لبثت فيكم عمرا من قبله افلا تعقلون', NULL, 'Say, "If Allāh had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?"', 'Katakanlah (wahai Muhammad): “Jika Allah kehendaki (supaya aku tidak membacakan Al-Quran ini kepada kamu), tentulah aku tidak dapat membacakannya kepada kamu, dan tentulah Ia tidak memberitahu kamu akan Al-Quran ini (dengan perantaraanku); kerana sesungguhnya aku telah tinggal dalam kalangan kamu satu masa yang lanjut (dan kamu pula mengenal aku sebagai seorang yang amanah) sebelum turunnya Al-Quran ini; maka mengapa kamu tidak mahu memikirkannya?”', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 18, NULL),
(10, 17, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 'فمن اظلم ممن افترى على الله كذبا او كذب باياته انه لا يفلح المجرمون', NULL, 'So who is more unjust than he who invents a lie about Allāh or denies His signs? Indeed, the criminals will not succeed.', 'Dengan yang demikian, tidaklah ada yang lebih zalim daripada orang yang berdusta terhadap Allah, atau yang mendustakan ayat-ayatNya. Sesungguhnya orang-orang yang berdosa itu tidak akan berjaya.', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 14, NULL),
(10, 18, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', 'ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعاؤنا عند الله قل اتنبئون الله بما لا يعلم في السماوات ولا في الارض سبحانه وتعالى عما يشركون', NULL, 'And they worship other than Allāh that which neither harms them nor benefits them, and they say, "These are our intercessors with Allāh." Say, "Do you inform Allāh of something He does not know in the heavens or on the earth?" Exalted is He and high above what they associate with Him.', 'Dan mereka menyembah yang lain dari Allah, sesuatu yang tidak dapat mendatangkan mudarat kepada mereka dan tidak dapat mendatangkan manfaat kepada mereka dan mereka pula berkata: “Mereka (yang kami sembah itu) ialah pemberi-pemberi syafaat kepada kami di sisi Allah”. Katakanlah (wahai Muhammad): “Adakah kamu hendak memberitahu kepada Allah akan apa yang Ia tidak mengetahui adanya di langit dan di bumi (padahal Allah mengetahui segala-galanya)? Maha Suci Allah dan tertinggi keadaanNya dari apa yang mereka sekutukan.”', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 29, NULL),
(10, 19, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 'وما كان الناس الا امة واحدة فاختلفوا ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون', NULL, 'And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ.', 'Dan (ketahuilah bahawa) manusia pada mulanya tidak memeluk melainkan ugama yang satu (ugama Allah), kemudian (dengan sebab menurut hawa nafsu dan Syaitan) mereka berselisihan. Dan kalau tidaklah kerana telah terdahulu Kalimah ketetapan dari Tuhanmu (untuk menangguhkan hukuman hingga hari kiamat), tentulah telah diputuskan hukuman di antara mereka (dengan segeranya di dunia) mengenai apa yang mereka perselisihkan itu.', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 17, NULL),
(10, 20, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'ويقولون لولا انزل عليه اية من ربه فقل انما الغيب لله فانتظروا اني معكم من المنتظرين', NULL, 'And they say, "Why is a sign not sent down to him from his Lord?" So say, "The unseen is only for Allāh [to administer], so wait; indeed, I am with you among those who wait."', 'Dan mereka yang ingkar itu berkata: “Mengapa tidak diturunkan kepada (Muhammad) satu mukjizat dari Tuhannya? “Maka jawablah (wahai Muhammad): “Sesungguhnya perkara yang ghaib itu tertentu bagi Allah; oleh itu tunggulah (hukuman Allah), sesungguhnya aku juga di antara orang-orang yang menunggu.', FALSE, NULL, NULL, 210, 11, 84, 173, FALSE, 16, NULL),
(10, 21, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', 'وَإِذَا أَذَقْنَا النَّاسَ رَحْمَةً مِّن بَعْدِ ضَرَّاءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِي آيَاتِنَا قُلِ اللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', NULL, 'And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, "Allāh is swifter in strategy." Indeed, Our messengers [i.e., angels] record that which you conspire.', 'Dan apabila Kami beri manusia merasai sesuatu rahmat sesudah mereka ditimpa sesuatu kesusahan, mereka dengan serta-merta melakukan rancangan mereka menentang ayat-ayat keterangan Kami dengan mendustakannya dan mengingkarinya. Katakanlah (wahai Muhammad): “Allah lebih cepat melakukan rancangan menentangnya!” Sesungguhnya malaikat-malaikat utusan Kami sentiasa menulis akan rancangan tipu daya yang kamu jalankan itu.', FALSE, NULL, NULL, 211, 11, 84, 174, FALSE, 0, NULL),
(10, 22, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ حَتَّىٰ إِذَا كُنتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا بِهَا جَاءَتْهَا رِيحٌ عَاصِفٌ وَجَاءَهُمُ الْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوا أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ', NULL, 'It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from every place and they expect to be engulfed, they supplicate Allāh, sincere to Him in religion, "If You should save us from this, we will surely be among the thankful."', 'Dia lah yang menjalankan kamu di darat dan di laut (dengan diberi kemudahan menggunakan berbagai jenis kenderaan); sehingga apabila kamu berada di dalam bahtera, dan bahtera itu pula bergerak laju membawa penumpang-penumpangnya dengan tiupan angin yang baik, dan mereka pun bersukacita dengannya; tiba-tiba datanglah kepadanya angin ribut yang kencang, dan mereka pula didatangi ombak menimpa dari segala penjuru, serta mereka percaya bahawa mereka diliputi oleh bahaya; pada saat itu mereka semua berdoa kepada Allah dengan mengikhlaskan kepercayaan mereka kepadaNya semata-mata (sambil merayu dengan berkata): “Demi sesungguhnya! jika Engkau (Ya Allah) selamatkan kami dari bahaya ini, kami tetap menjadi orang-orang yang bersyukur”.', FALSE, NULL, NULL, 211, 11, 84, 174, FALSE, 0, NULL),
(10, 23, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'فَلَمَّا أَنجَاهُمْ إِذَا هُمْ يَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ يَا أَيُّهَا النَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰ أَنفُسِكُم مَّتَاعَ الْحَيَاةِ الدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do.', 'Kemudian bila sahaja Allah selamatkan mereka, mereka dengan serta-merta merebakkan perbuatan derhaka di bumi dengan tidak ada sebarang alasan yang benar. Wahai manusia! Sesungguhnya perbuatan kamu menderhaka itu hanyalah bala bencana terhadap diri kamu sendiri. (Dengan itu kamu hanya dapat merasai) kesenangan hidup di dunia (bagi sementara); kemudian kepada kamilah tempat kembalinya kamu, maka Kami akan memberitahu apa yang kamu telah lakukan.', FALSE, NULL, NULL, 211, 11, 84, 174, FALSE, 0, NULL),
(10, 24, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَتَفَكَّرُونَ', 'إِنَّمَا مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ مِمَّا يَأْكُلُ النَّاسُ وَالْأَنْعَامُ حَتَّىٰ إِذَا أَخَذَتِ الْأَرْضُ زُخْرُفَهَا وَازَّيَّنَتْ وَظَنَّ أَهْلُهَا أَنَّهُمْ قَادِرُونَ عَلَيْهَا أَتَاهَا أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَاهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِالْأَمْسِ كَذَٰلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَتَفَكَّرُونَ', NULL, 'The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought.', 'Sesungguhnya bandingan kehidupan dunia hanyalah seperti air hujan yang Kami turunkan dari langit, lalu (tumbuhlah dengan suburnya) tanaman-tanaman di bumi dari jenis-jenis yang dimakan oleh manusia dan binatang - bercampur-aduk dan berpaut-pautan (pokok-pokok dan pohonnya) dengan sebab air itu hingga apabila bumi itu lengkap sempurna dengan keindahannya dan berhias (dengan bunga-bungaan yang berwarna-warni), dan penduduknya pun menyangka bahawa mereka dapat berbagai-bagai tanaman serta menguasainya (mengambil hasilnya) datanglah perintah Kami menimpakannya dengan bencana pada waktu malam atau pada siang hari lalu Kami jadikan dia hancur-lebur, seolah-olah ia tidak ada sebelum itu. Demikianlah Kami menjelaskan ayat-ayat keterangan Kami satu persatu bagi kaum yang mahu berfikir (dan mengambil iktibar daripadanya).', FALSE, NULL, NULL, 211, 11, 84, 174, FALSE, 0, NULL),
(10, 25, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَاللَّهُ يَدْعُو إِلَىٰ دَارِ السَّلَامِ وَيَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And Allāh invites to the Home of Peace [i.e., Paradise] and guides whom He wills to a straight path.', '(Itulah dia kesudahan kehidupan dunia), dan sebaliknya Allah menyeru manusia ke tempat kediaman yang selamat sentosa, dan Dia sentiasa memberi petunjuk hidayahNya kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya) ke jalan yang betul lurus (yang selamat itu).', FALSE, NULL, NULL, 211, 11, 84, 174, FALSE, 0, NULL),
(10, 26, 'لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'لِّلَّذِينَ أَحْسَنُوا الْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُولَٰئِكَ أَصْحَابُ الْجَنَّةِ هُمْ فِيهَا خَالِدُونَ', NULL, 'For them who have done good is the best [reward] - and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally.', 'Untuk orang-orang yang berusaha menjadikan amalnya baik dikurniakan segala kebaikan serta satu tambahan yang mulia dan air muka mereka pula (berseri-seri) tidak diliputi oleh sebarang kesedihan dan kehinaan. Mereka itulah ahli Syurga, mereka kekal di dalamnya selama-lamanya.', FALSE, NULL, NULL, 212, 11, 85, 174, FALSE, 0, NULL),
(10, 27, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'وَالَّذِينَ كَسَبُوا السَّيِّئَاتِ جَزَاءُ سَيِّئَةٍ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ اللَّهِ مِنْ عَاصِمٍ كَأَنَّمَا أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ اللَّيْلِ مُظْلِمًا أُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ', NULL, 'But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allāh no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally.', 'Dan untuk orang-orang yang melakukan kejahatan (syirik dan maksiat), balasan tiap-tiap satu kejahatan mereka ialah kejahatan yang sebanding dengannya serta akan ditimpakan kehinaan; tiadalah bagi mereka pelindung dari (seksa) Allah; muka mereka (hitam legam) seolah-olahnya ditutup dengan beberapa bahagian (yang gelap-gelita) dari malam yang gelap-gelita. Mereka itulah ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 212, 11, 85, 174, FALSE, 0, NULL),
(10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا مَكَانَكُمْ أَنتُمْ وَشُرَكَاؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَاؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', NULL, 'And [mention, O Muḥammad], the Day We will gather them all together - then We will say to those who associated others with Allāh, "[Remain in] your place, you and your ''partners.''" Then We will separate them, and their "partners" will say, "You did not used to worship us,', 'Dan (ingatlah) masa Kami himpunkan mereka semua (pada hari kiamat), kemudian Kami berfirman kepada orang-orang musyrik: “Tunggulah di tempat kamu semua, kamu dan makhluk-makhluk yang kamu jadikan sekutu”; sesudah itu kami putuskan perhubungan baik di antara mereka. Dan berkatalah makhluk-makhluk yang mereka sembah itu (sebagai berlepas diri): “Bukanlah kami - yang kamu puja dan taat (sebenarnya kamu hanya memuja dan mentaati hawa nafsu kamu sendiri)!', FALSE, NULL, NULL, 212, 11, 85, 174, FALSE, 0, NULL),
(10, 29, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', 'فَكَفَىٰ بِاللَّهِ شَهِيدًا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَافِلِينَ', NULL, 'And sufficient is Allāh as a witness between us and you that we were of your worship unaware."', '“(Allah mengetahui apa yang sebenarnya); oleh itu, cukuplah Allah sebagai saksi antara kami dengan kamu, bahawa sesungguhnya kami tidak menyedari pujaan atau penyembahan kamu (kepada kami)”.', FALSE, NULL, NULL, 212, 11, 85, 174, FALSE, 0, NULL),
(10, 30, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'هُنَالِكَ تَبْلُو كُلُّ نَفْسٍ مَّا أَسْلَفَتْ وَرُدُّوا إِلَى اللَّهِ مَوْلَاهُمُ الْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allāh, their master, the Truth, and lost from them is whatever they used to invent.', 'Pada masa itu tiap-tiap diri dapatlah mengetahui (dan merasai) akan apa yang telah dikerjakan dan mereka dikembalikan kepada Allah Tuhan mereka yang sebenar-benarnya (yang akan membalas dengan adilnya); dan (dengan itu) hilang lenyaplah dari mereka apa yang mereka ada-adakan.', FALSE, NULL, NULL, 212, 11, 85, 174, FALSE, 0, NULL),
(10, 31, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ فَسَيَقُولُونَ ٱللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ', 'قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَمَّن يَمْلِكُ السَّمْعَ وَالْأَبْصَارَ وَمَن يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَن يُدَبِّرُ الْأَمْرَ فَسَيَقُولُونَ اللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ', NULL, 'Say, "Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?" They will say, "Allāh," so say, "Then will you not fear Him?"', 'Bertanyalah kepada mereka (yang musyrik itu): “Siapakah Yang memberi rezeki kepada kamu dari langit dan bumi? Atau siapakah yang menguasai pendengaran dan penglihatan? Dan siapakah yang mengeluarkan makhluk yang hidup dari benda yang mati, dan mengeluarkan benda yang mati dari makhluk yang hidup? Dan siapakah pula yang mentadbirkan urusan sekalian alam? “(Dengan pertanyaan-pertanyaan itu) maka mereka (yang musyrik) tetap akan menjawab (mengakui) dengan berkata: “Allah jualah yang menguasai segala-galanya! “Oleh itu, katakanlah: “(Jika kamu mengakui yang demikian), maka mengapa kamu tidak mahu bertaqwa?', FALSE, NULL, NULL, 212, 11, 85, 175, FALSE, 0, NULL),
(10, 32, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ فَأَنَّىٰ تُصْرَفُونَ', 'فَذَٰلِكُمُ اللَّهُ رَبُّكُمُ الْحَقُّ فَمَاذَا بَعْدَ الْحَقِّ إِلَّا الضَّلَالُ فَأَنَّىٰ تُصْرَفُونَ', NULL, 'For that is Allāh, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?', 'Maka yang demikian (sifatNya dan kekuasaanNya) ialah Allah, Tuhan kamu yang sebenar-benarnya; sesudah nyatanya sesuatu yang betul dan benar, maka tidakkah yang lain daripada itu salah dan karut sahaja? Oleh itu, bagaimana kamu dapat dipesongkan dari kebenaran?', FALSE, NULL, NULL, 212, 11, 85, 175, FALSE, 0, NULL),
(10, 33, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ فَسَقُوا أَنَّهُمْ لَا يُؤْمِنُونَ', NULL, 'Thus the word [i.e., decree] of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe.', '(Sebagaimana benarnya ketuhanan itu bagi Allah sahaja) demikianlah benarnya kalimah ketetapan hukum Tuhanmu, terhadap orang-orang yang fasik kerana bahawasanya mereka tidak beriman.', FALSE, NULL, NULL, 212, 11, 85, 175, FALSE, 0, NULL),
(10, 34, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ فَأَنَّىٰ تُؤْفَكُونَ', 'قُلْ هَلْ مِن شُرَكَائِكُم مَّن يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ قُلِ اللَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ فَأَنَّىٰ تُؤْفَكُونَ', NULL, 'Say, "Are there of your ''partners'' any who begins creation and then repeats it?" Say, "Allāh begins creation and then repeats it, so how are you deluded?"', 'Bertanyalah (kepada mereka wahai Muhammad): “Adakah di antara makhluk-makhluk yang kamu sekutukan dengan Tuhan itu, sesiapa yang mula menciptakan sesuatu kejadian kemudian ia mengembalikan adanya semula (pada hari kiamat)? “Katakanlah: Allah jualah yang mula menciptakan sekalian makhluk kemudian Ia mengembalikan adanya semula (untuk menerima balasan); oleh itu, mengapa kamu rela dipalingkan (kepada menyembah yang lain)?”', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 35, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'قُلْ هَلْ مِن شُرَكَائِكُم مَّن يَهْدِي إِلَى الْحَقِّ قُلِ اللَّهُ يَهْدِي لِلْحَقِّ أَفَمَن يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّي إِلَّا أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', NULL, 'Say, "Are there of your ''partners'' any who guides to the truth?" Say, "Allāh guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?"', 'Bertanyalah (wahai Muhammad): “Adakah di antara makhluk-makhluk: yang kamu sekutukan dengan Tuhan itu, sesiapa yang dengan memberi petunjuk kepada kebenaran? “Katakanlah: “Allah jualah yang memberi hidayah petunjuk kepada kebenaran; (kalau sudah demikian) maka adakah yang dapat memberi hidayah petunjuk kepada kebenaran itu, lebih berhak diturut, ataupun yang tidak dapat memberi sebarang petunjuk melainkan sesudah ia diberi hidayah petunjuk? Maka apakah alasan sikap kamu itu? Bagaimana kamu sanggup mengambil keputusan (dengan perkara yang salah, yang tidak dapat diterima oleh akal)?”', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 36, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا إِنَّ اللَّهَ عَلِيمٌ بِمَا يَفْعَلُونَ', NULL, 'And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allāh is Knowing of what they do.', 'Dan kebanyakan mereka, tidak menurut melainkan sesuatu sangkaan sahaja, (padahal) sesungguhnya sangkaan itu tidak dapat memenuhi kehendak menentukan sesuatu dari kebenaran (iktiqad). Sesungguhnya Allah Maha Mengetahui akan apa yang mereka lakukan.', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 37, 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 'وَمَا كَانَ هَٰذَا الْقُرْآنُ أَن يُفْتَرَىٰ مِن دُونِ اللَّهِ وَلَٰكِن تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ وَتَفْصِيلَ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ', NULL, 'And it was not [possible] for this Qur’ān to be produced by other than Allāh, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds.', 'Dan bukanlah Al-Quran ini sesuatu yang boleh diada-adakan oleh yang lain dari Allah; tetapi Al-Quran itu diturunkan oleh Allah untuk membenarkan Kitab-kitab yang diturunkan sebelumnya, dan untuk menjelaskan satu persatu hukum-hukum Syarak yang diwajibkan (atas kamu); tidak ada sebarang syak dan ragu-ragu pada Al-Quran itu tentang datangnya dari Allah, Tuhan yang mencipta dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 38, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِّثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ', NULL, 'Or do they say [about the Prophet (ﷺ)], "He invented it?" Say, "Then bring forth a sūrah like it and call upon [for assistance] whomever you can besides Allāh, if you should be truthful."', '(Orang-orang kafir tidak mengakui hakikat yang demikian itu) bahkan mereka mengatakan: “Dia lah (Muhammad) yang mengada-adakan Al-Quran menurut rekaannya”. Katakanlah (wahai Muhammad): “Kalau demikian, datangkanlah satu surah yang sebanding dengan Al-Quran itu, dan panggilah siapa sahaja yang kamu dapat memanggilnya, yang lain dari Allah (untuk membantu kamu), jika betul kamu orang-orang yang benar!”.', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 39, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُ كَذَٰلِكَ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الظَّالِمِينَ', NULL, 'Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers.', 'Bahkan mereka pula terburu-buru mendustakan Al-Quran yang fahaman mereka tidak dapat meliputi segala isi pengetahuannya, dan belum datang kepada mereka kenyataan yang menjelaskan kebenarannya. Demikianlah juga orang-orang sebelum mereka mendustakan (Kitab-kitab Allah yang diturunkan kepada mereka). Maka lihatlah bagaimana akibat orang-orang yang zalim itu (berakhir dengan berbagai bencana yang membinasakan mereka).', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 40, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 'وَمِنْهُم مَّن يُؤْمِنُ بِهِ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِ وَرَبُّكَ أَعْلَمُ بِالْمُفْسِدِينَ', NULL, 'And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters.', 'Dan di antara mereka ada yang beriman kepada Al-Quran, dan ada di antaranya yang tidak beriman langsung kepadanya; dan (ingatlah), Tuhanmu lebih mengetahui akan orang-orang yang melakukan kerosakan.', FALSE, NULL, NULL, 213, 11, 85, 175, FALSE, 0, NULL),
(10, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيئُونَ مِمَّا أَعْمَلُ وَأَنَا بَرِيءٌ مِّمَّا تَعْمَلُونَ', NULL, 'And if they deny you, [O Muḥammad], then say, "For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do."', 'Dan jika mereka terus-menerus mendustakanmu (wahai Muhammad), maka katakanlah: “Bagiku amalku, dan bagi kamu pula amal kamu. Kamu tidak bertanggungjawab akan apa yang aku kerjakan, dan aku juga tidak bertanggungjawab akan apa yang kamu kerjakan”.', FALSE, NULL, NULL, 213, 11, 85, 176, FALSE, 0, NULL),
(10, 42, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ الصُّمَّ وَلَوْ كَانُوا لَا يَعْقِلُونَ', NULL, 'And among them are those who listen to you. But can you cause the deaf to hear [i.e., benefit from this hearing], although they will not use reason?', 'Dan di antara mereka (yang ingkar) itu, ada yang datang mendengar ajaranmu (dengan tidak mendapat faedah sedikitpun sebagai orang pekak); maka engkau (wahai Muhammad) tidak berkuasa menjadikan orang-orang yang pekak itu mendengar, juga kalau mereka menjadi orang-orang yang tidak mahu memahami perkara yang didengarnya.', FALSE, NULL, NULL, 213, 11, 85, 176, FALSE, 0, NULL),
(10, 43, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِي الْعُمْيَ وَلَوْ كَانُوا لَا يُبْصِرُونَ', NULL, 'And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?', 'Dan di antara mereka pula ada yang memandang kepada perkara-perkara yang engkau tunjukkan (tetapi mereka tidak nampak kebenarannya sebagai orang buta); maka engkau (wahai Muhammad) tidak berfaedah menunjuk jalan kepada orang-orang yang buta, juga kalau mereka menjadi orang-orang yang tidak mahu melihat (perkara yang engkau tunjukkan itu).', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 44, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', 'إِنَّ اللَّهَ لَا يَظْلِمُ النَّاسَ شَيْئًا وَلَٰكِنَّ النَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'Indeed, Allāh does not wrong the people at all, but it is the people who are wronging themselves.', 'Sesungguhnya Allah tidak menganiaya manusia sedikitpun, akan tetapi manusia jualah yang menganiaya diri mereka sendiri.', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 45, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوا إِلَّا سَاعَةً مِّنَ النَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقَاءِ اللَّهِ وَمَا كَانُوا مُهْتَدِينَ', NULL, 'And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allāh and were not guided.', 'Dan (ingatlah) masa Tuhan himpunkan mereka (pada hari kiamat kelak), dengan keadaan mereka merasai seolah-olah mereka tidak tinggal di dunia melainkan sekadar satu saat sahaja dari siang hari. Mereka akan berkenal-kenalan sesama sendiri. Sesungguhnya rugilah orang-orang yang telah mendustakan hari menemui Allah untuk menerima balasan, dan yang tidak mendapat petunjuk (ke jalan mencari untung semasa hidup di dunia).', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 46, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', 'وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ اللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', NULL, 'And whether We show you some of what We promise them, [O Muḥammad], or We take you in death, to Us is their return; then, [either way], Allāh is a witness concerning what they are doing.', 'Dan jika Kami perlihatkan kepadamu (wahai Muhammad) akan sebahagian dari balasan azab yang Kami janjikan kepada mereka, atau jika Kami wafatkan engkau sebelum itu, maka kepada Kamilah tempat kembali mereka; kemudian Allah yang memberi keterangan mengenai apa yang mereka lakukan.', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 47, 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَاءَ رَسُولُهُمْ قُضِيَ بَيْنَهُم بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged.', 'Dan bagi tiap-tiap satu umat ada seorang Rasul (yang diutuskan kepadanya); setelah datang Rasul masing-masing (menerangkan apa yang mesti diterangkan) maka hukuman pun dijalankan di antara mereka dengan adil dan mereka tetap tidak dianiaya.', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"', 'Dan mereka (yang kafir) bertanya: “Bilakah berlakunya azab yang telah dijanjikan itu, jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 49, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'قُل لَّا أَمْلِكُ لِنَفْسِي ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَاءَ اللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَاءَ أَجَلُهُمْ فَلَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', NULL, 'Say, "I possess not for myself any harm or benefit except what Allāh should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it]."', 'Katakanlah (wahai Muhammad): “Aku tidak berkuasa menolak mudarat dan tidak juga berkuasa mendatangkan manfaat bagi diriku kecuali apa yang dikehendaki Allah. Bagi tiap-tiap umat ada tempoh yang ditetapkan; maka apabila tempohnya, tidak dapat mereka melambatkannya sesaatpun, dan tidak dapat mereka menyegerakannya”.', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 50, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 'قُلْ أَرَأَيْتُمْ إِنْ أَتَاكُمْ عَذَابُهُ بَيَاتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ الْمُجْرِمُونَ', NULL, 'Say, "Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?"', 'Katakanlah: “Sudahkah kamu nampak jalan keluar jika datang kepada kamu azab Tuhan itu, pada waktu malam atau pada waktu siang? “Azab manakah yang orang-orang berdosa itu minta disegerakan (sedang sebarang azab wajib ditakuti)?', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'أَثُمَّ إِذَا مَا وَقَعَ آمَنتُم بِهِ آلْآنَ وَقَدْ كُنتُم بِهِ تَسْتَعْجِلُونَ', NULL, 'Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient.', 'Patutkah (kamu mengingkari azab itu), kemudian apabila ia menimpa kamu, kamu mengakui benarnya? (Sedang pengakuan pada masa itu tidak diterima bahkan dikatakan kepada kamu): “Sekarangkah baharu kamu mengakui benarnya, padahal sebelum ini kamu telah menunjukkan keingkaran dengan meminta disegerakan kedatangannya?”', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 52, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا ذُوقُوا عَذَابَ الْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', NULL, 'Then it will be said to those who had wronged, "Taste the punishment of eternity; are you being recompensed except for what you used to earn?"', 'Kemudian dikatakan lagi kepada orang-orang yang berlaku zalim itu: “Rasakanlah azab yang kekal. Tidaklah kamu dibalas melainkan dengan apa yang kamu usahakan (di dunia)”.', FALSE, NULL, NULL, 214, 11, 85, 176, FALSE, 0, NULL),
(10, 53, 'وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ وَمَآ أَنتُم بِمُعْجِزِينَ', 'وَيَسْتَنبِئُونَكَ أَحَقٌّ هُوَ قُلْ إِي وَرَبِّي إِنَّهُ لَحَقٌّ وَمَا أَنتُم بِمُعْجِزِينَ', NULL, 'And they ask information of you, [O Muḥammad], "Is it true?" Say, "Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allāh]."', 'Dan mereka (yang meminta disegerakan azab) itu akan bertanya kepadamu (wahai Muhammad): “Adakah kedatangan azab yang dijanjikan itu benar? “Jawablah: “Ya, demi Tuhanku! Sesungguhnya adalah ia benar! Dan kamu tidak sekali-kali berkuasa menahan kedatangannya”.', FALSE, NULL, NULL, 214, 11, 86, 176, FALSE, 0, NULL),
(10, 54, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِي الْأَرْضِ لَافْتَدَتْ بِهِ وَأَسَرُّوا النَّدَامَةَ لَمَّا رَأَوُا الْعَذَابَ وَقُضِيَ بَيْنَهُم بِالْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged.', 'Dan pada masa itu sekiranya tiap-tiap seorang yang berlaku zalim (kepada dirinya sendiri atau kepada orang lain) itu mempunyai segala yang ada di bumi, tentulah ia rela menebus dirinya dengan semuanya itu (dari azab yang akan menimpanya); dan mereka tetap akan merasa sesal serta kecewa manakala mereka melihat azab itu; dan Allah putuskan hukum di antara mereka dengan adil serta mereka tidak akan dianiaya dengan keputusan itu.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 55, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'أَلَا إِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ أَلَا إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'Unquestionably, to Allāh belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allāh is truth, but most of them do not know.', 'Ingatlah! Sesungguhnya segala yang ada di langit dan di bumi adalah kepunyaan Allah. Awaslah! Sesungguhnya janji Allah itu adalah benar, tetapi kebanyakan manusia tidak mengetahui.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 56, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 'هُوَ يُحْيِي وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'He gives life and causes death, and to Him you will be returned.', 'Dia lah yang menghidupkan dan yang mematikan, dan kepadaNyalah kamu akan dikembalikan untuk menerima balasan.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 57, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', 'يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَاءٌ لِّمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', NULL, 'O mankind, there has come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers.', 'Wahai umat manusia! Sesungguhnya telah datang kepada kamu Al-Quran yang menjadi nasihat pengajaran dari Tuhan kamu, dan yang menjadi penawar bagi penyakit-penyakit batin yang ada di dalam dada kamu, dan juga menjadi hidayah petunjuk untuk keselamatan, serta membawa rahmat bagi orang-orang yang beriman.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 58, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَٰلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', NULL, 'Say, "In the bounty of Allāh and in His mercy - in that let them rejoice; it is better than what they accumulate."', 'Katakanlah (wahai Muhammad) “kedatangan Al-Quran itu adalah semata-mata dengan limpah kurnia Allah dan kasih sayangNya, maka dengan isi kandungan Al-Quran itulah hendaknya mereka bersukacita (bukan dengan yang lainnya), kerana ia lebih baik daripada apa yang mereka himpunkan dari segala benda dan perkara yang tidak kekal)”.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 59, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', 'قُلْ أَرَأَيْتُم مَّا أَنزَلَ اللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَالًا قُلْ آللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى اللَّهِ تَفْتَرُونَ', NULL, 'Say, "Have you seen what Allāh has sent down to you of provision of which you have made [some] lawful and [some] unlawful?" Say, "Has Allāh permitted you [to do so], or do you invent [something] about Allāh?"', 'Katakanlah (kepada kaum yang mengada-adakan sesuatu hukum): “Sudahkah kamu nampak baik-buruknya sesuatu yang diturunkan Allah untuk manfaat kamu itu sehingga dapat kamu jadikan sebahagian daripadanya haram, dan sebahagian lagi halal?” Katakanlah lagi (kepada mereka): “Adakah Allah izinkan bagi kamu berbuat demikian, atau kamu hanya mengada-adakan secara dusta terhadap Allah?”.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 60, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'وَمَا ظَنُّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ يَوْمَ الْقِيَامَةِ إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', NULL, 'And what will be the supposition of those who invent falsehood about Allāh on the Day of Resurrection? Indeed, Allāh is the possessor of bounty for the people, but most of them are not grateful.', 'Dan apakah sangkaan orang-orang yang mengada-adakan kata-kata dusta terhadap Allah, (tidakkah mereka akan diazabkan) hari kiamat kelak? Sebenarnya Allah jualah yang melimpahkan kurnia kepada manusia (meliputi rezeki pemberianNya dan hukum-hukum Syarak yang diturunkanNya), tetapi kebanyakan mereka tidak bersyukur.', FALSE, NULL, NULL, 215, 11, 86, 177, FALSE, 0, NULL),
(10, 61, 'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'وَمَا تَكُونُ فِي شَأْنٍ وَمَا تَتْلُو مِنْهُ مِن قُرْآنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَلَا أَصْغَرَ مِن ذَٰلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ مُّبِينٍ', NULL, 'And, [O Muḥammad], you are not [engaged] in any matter and do not recite any of the Qur’ān and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom''s weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register.', 'Dan tidaklah engkau (wahai Muhammad) dalam menjalankan sesuatu urusan, dan tidaklah engkau dalam membaca sesuatu surah atau sesuatu ayat dari Al-Quran dan tidaklah kamu (wahai umat manusia) dalam mengerjakan sesuatu amal usaha, melainkan adalah Kami menjadi saksi terhadap kamu, ketika kamu mengerjakannya. Dan tidak akan hilang lenyap dari pengetahuan Tuhanmu sesuatu dari sehalus-halus atau seringan-ringan yang ada di bumi atau di langit, dan tidak ada yang lebih kecil dari itu dan tidak ada yang lebih besar, melainkan semuanya tertulis di dalam Kitab yang terang nyata.', FALSE, NULL, NULL, 215, 11, 86, 178, FALSE, 0, NULL),
(10, 62, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', NULL, 'Unquestionably, [for] the allies of Allāh there will be no fear concerning them, nor will they grieve -', 'Ketahuilah! Sesungguhnya wali-wali Allah, tidak ada kebimbangan (dari sesuatu yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 63, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ', NULL, 'Those who believed and were fearing Allāh.', '(Wali-wali Allah itu ialah) orang-orang yang beriman serta mereka pula sentiasa bertaqwa.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 64, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'لَهُمُ الْبُشْرَىٰ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ لَا تَبْدِيلَ لِكَلِمَاتِ اللَّهِ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ', NULL, 'For them are good tidings in the worldly life and in the Hereafter. No change is there in the words [i.e., decrees] of Allāh. That is what is the great attainment.', 'Untuk mereka sahajalah kebahagiaan yang mengembirakan di dunia dan di akhirat; tidak ada (sebarang perubahan pada janji-janji Allah yang demikian itulah kejayaan yang besar.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 65, 'وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ الْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'And let not their speech grieve you. Indeed, honor [due to power] belongs to Allāh entirely. He is the Hearing, the Knowing.', 'Dan janganlah engkau (wahai Muhammad) merasa dukacita disebabkan kata-kata mereka yang ingkar itu; kerana sesungguhnya segala kekuasaan tertentu bagi Allah; Dia lah Yang Maha Mendengar, lagi Yang Maha Mengetahui.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 66, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'أَلَا إِنَّ لِلَّهِ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ وَمَا يَتَّبِعُ الَّذِينَ يَدْعُونَ مِن دُونِ اللَّهِ شُرَكَاءَ إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', NULL, 'Unquestionably, to Allāh belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allāh do not [actually] follow [His] "partners." They follow not except assumption, and they are not but misjudging.', 'Ingatlah! Sesungguhnya bagi Allah jualah segala yang ada di langit dan yang ada di bumi dan bahawa mereka yang menyembah sesuatu yang lain Allah sebagai sekutuNya, mereka tidak menurut (sesuatu keyakinan), mereka hanya menurut sangkaan semata-mata, dan mereka hanyalah orang-orang yang sentiasa berdusta.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 67, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'هُوَ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَسْمَعُونَ', NULL, 'It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen.', 'Dia lah yang menjadikan malam bagi kamu supaya kamu berehat padanya, dan menjadikan siang terang-benderang (supaya kamu berusaha). Sesungguhnya perubahan malam dan siang itu mengandungi tanda-tanda (yang menunjukkan kekuasaan Allah) bagi kaum yang mahu mendengar (keterangan-keterangan yang tersebut dan mengambil pelajaran daripadanya).', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 68, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ هُوَ ٱلْغَنِىُّ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قَالُوا اتَّخَذَ اللَّهُ وَلَدًا سُبْحَانَهُ هُوَ الْغَنِيُّ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَانٍ بِهَٰذَا أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'They have said, "Allāh has taken a son." Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allāh that which you do not know?', 'Mereka berkata: “Allah mempunyai anak” Maha Suci Allah (dari apa yang mereka katakan itu)! Dia lah Yang Maha Kaya; segala yang ada di langit dan yang ada di bumi adalah kepunyaanNya; tidaklah ada sebarang keterangan di sisi kamu yang membuktikan apa yang kamu dakwakan itu. Mengapa kamu berani mengatakan terhadap Allah, apa yang kamu tidak mengetahuinya?', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 69, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'قُلْ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ', NULL, 'Say, "Indeed, those who invent falsehood about Allāh will not succeed."', 'Katakanlah (wahai Muhammad): “Sesungguhnya orang-orang yang mengada-adakan sesuatu yang dusta terhadap Allah, tidak akan berjaya”.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 70, 'مَتَٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 'مَتَاعٌ فِي الدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ الْعَذَابَ الشَّدِيدَ بِمَا كَانُوا يَكْفُرُونَ', NULL, '[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve.', '(Apa yang mereka beroleh hanya) kesenangan di dunia, kemudian kepada Kamilah tempat kembalinya mereka. Kemudian Kami akan rasakan mereka azab yang berat disebabkan perbuatan kufur yang mereka lakukan.', FALSE, NULL, NULL, 216, 11, 86, 178, FALSE, 0, NULL),
(10, 71, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', 'وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِ يَا قَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِي وَتَذْكِيرِي بِآيَاتِ اللَّهِ فَعَلَى اللَّهِ تَوَكَّلْتُ فَأَجْمِعُوا أَمْرَكُمْ وَشُرَكَاءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ اقْضُوا إِلَيَّ وَلَا تُنظِرُونِ', NULL, 'And recite to them the news of Noah, when he said to his people, "O my people, if my residence and my reminding of the signs of Allāh has become burdensome upon you - then I have relied upon Allāh. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite.', 'Dan bacakanlah kepada mereka (wahai Muhammad) perihal Nabi Nuh, ketika ia berkata kepada kaumnya: “Wahai kaumku! Sekiranya kedudukan aku dalam kalangan kamu, dan peringatan yang aku berikan kepada kamu dengan ayat-ayat keterangan Allah itu, menjadi keberatan kepada kamu, maka (buatlah apa yang kamu hendak buat, kerana) kepada Allah jualah aku berserah diri. Oleh itu, tetapkanlah keazaman kamu serta sekutu-sekutu kamu untuk melakukan rancangan jahat kamu terhadapku; kemudian janganlah hendaknya rancangan jahat kamu itu, kamu jalankan secara tersembunyi (tetapi biarlah terbuka); sesudah itu bertindaklah terus terhadapku dan janganlah kamu tunggu-tunggu lagi.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 72, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ', NULL, 'And if you turn away [from my advice] - then no payment have I asked of you. My reward is only from Allāh, and I have been commanded to be of the Muslims [i.e., those who submit to Allāh]."', '“Oleh itu, jika kamu berpaling membelakangkan peringatanku, maka tidaklah menjadi hal kepadaku, kerana aku tidak meminta sebarang balasan daripada kamu (mengenai ajaran ugama Allah yang aku sampaikan itu); balasanku hanyalah dari Allah semata-mata (sama ada kamu beriman ataupun kamu ingkar); dan aku pula diperintahkan supaya menjadi dari orang-orang Islam (yang berserah diri bulat-bulat kepada Allah)”.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'فَكَذَّبُوهُ فَنَجَّيْنَاهُ وَمَن مَّعَهُ فِي الْفُلْكِ وَجَعَلْنَاهُمْ خَلَائِفَ وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآيَاتِنَا فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنذَرِينَ', NULL, 'And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned.', 'Mereka tetap juga mendustakan Nabi Nuh, lalu Kami selamatkan dia bersama-sama pengikut-pengikutnya yang beriman di dalam bahtera, dan kami jadikan mereka pengganti-pengganti (yang memakmurkan bumi) serta Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami (dengan banjir dan taufan sehingga punah-ranah semuanya). Maka lihatlah bagaimana kesudahan orang-orang (yang mendustakan ayat-ayat kami) setelah diberi amaran.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 74, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 'ثُمَّ بَعَثْنَا مِن بَعْدِهِ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَاءُوهُم بِالْبَيِّنَاتِ فَمَا كَانُوا لِيُؤْمِنُوا بِمَا كَذَّبُوا بِهِ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ الْمُعْتَدِينَ', NULL, 'Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors.', 'Kemudian Kami utuskan sesudah Nabi Nuh, beberapa orang Rasul kepada kaum masing-masing; lalu Rasul-rasul itu datang kepada kaum mereka dengan membawa keterangan-keterangan yang nyata; dalam pada itu kaum mereka tetap juga tidak mahu beriman kepada apa yang mereka telah mendustakannya sebelum itu. Demikianlah, Kami meteraikan atas hati orang-orang yang melampaui batas.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 75, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'ثُمَّ بَعَثْنَا مِن بَعْدِهِم مُّوسَىٰ وَهَارُونَ إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ بِآيَاتِنَا فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا مُّجْرِمِينَ', NULL, 'Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people.', 'Kemudian Kami utuskan sesudah Rasul-rasul itu, Nabi Musa dan Nabi Harun, kepada Firaun dan kaumnya dengan membawa ayat-ayat Kami; lalu mereka (Firaun dan kaumnya) berlaku sombong takbur (enggan menerimanya), dan mereka adalah kaum yang biasa melakukan dosa.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 76, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ', 'فَلَمَّا جَاءَهُمُ الْحَقُّ مِنْ عِندِنَا قَالُوا إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ', NULL, 'So when there came to them the truth from Us, they said, "Indeed, this is obvious magic."', 'Oleh sebab itu ketika datang kepada mereka kebenaran dari sisi Kami, berkatalah mereka: “Sesungguhnya ini ialah sihir yang nyata”.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 77, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', 'قَالَ مُوسَىٰ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَاءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ السَّاحِرُونَ', NULL, 'Moses said, "Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed."', '(Mendengarkan yang demikian), Nabi Musa bertanya: Patutkah kamu berkata demikian terhadap sesuatu kebenaran ketika datangnya kepada kamu? Adakah bawaanku ini sihir? Sedang ahli-ahli sihir itu sudah tetap tidak akan berjaya”.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 78, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', 'قَالُوا أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ آبَاءَنَا وَتَكُونَ لَكُمَا الْكِبْرِيَاءُ فِي الْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', NULL, 'They said, "Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you."', 'Mereka pula berkata: “Adakah engkau datang (wahai Musa) untuk memesongkan kami dari penyembahan berhala yang kami dapati datuk nenek kami melakukannya, dan untuk membolehkan kamu berdua membolot kekuasaan di bumi (Mesir)? Dan (ketahuilah) sebenarnya kami tidak akan beriman kepada kamu berdua”.', FALSE, NULL, NULL, 217, 11, 87, 179, FALSE, 0, NULL),
(10, 79, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ', NULL, 'And Pharaoh said, "Bring to me every learned magician."', 'Dan berkatalah Firaun (kepada orang-orangnya): “Bawalah kamu kepadaku segala ahli sihir yang mahir”.', FALSE, NULL, NULL, 218, 11, 87, 179, FALSE, 0, NULL),
(10, 80, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُم مُّوسَىٰ أَلْقُوا مَا أَنتُم مُّلْقُونَ', NULL, 'So when the magicians came, Moses said to them, "Throw down whatever you will throw."', 'Setelah datang ahli-ahli sihir itu, Nabi Musa berkata kepada mereka: “Campakkanlah kamu dahulu apa yang kamu hendak campakkan (diri benda-benda yang kamu jadikan sihir itu)!”', FALSE, NULL, NULL, 218, 11, 87, 179, FALSE, 0, NULL),
(10, 81, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', 'فَلَمَّا أَلْقَوْا قَالَ مُوسَىٰ مَا جِئْتُم بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ', NULL, 'And when they had thrown, Moses said, "What you have brought is [only] magic. Indeed, Allāh will expose its worthlessness. Indeed, Allāh does not amend the work of corrupters.', 'Setelah mereka campakkan (benda-benda itu), Nabi Musa berkata: “Apa yang kamu datangkan itu, itulah sihir; sesungguhnya Allah akan mendedahkan kepalsuannya (dengan mukjizat yang dikurniakanNya kepadaku); sesungguhnya Allah tidak akan menjayakan perbuatan orang-orang yang melakukan kerosakan.', FALSE, NULL, NULL, 218, 11, 87, 179, FALSE, 0, NULL),
(10, 82, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ', NULL, 'And Allāh will establish the truth by His words, even if the criminals dislike it."', '“Dan Allah juga sentiasa menetapkan perkara yang benar dengan kalimah-kalimah perintahNya, walaupun yang demikian dibenci oleh orang-orang yang melakukan dosa”.', FALSE, NULL, NULL, 218, 11, 87, 179, FALSE, 0, NULL),
(10, 83, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', 'فَمَا آمَنَ لِمُوسَىٰ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَئِهِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِي الْأَرْضِ وَإِنَّهُ لَمِنَ الْمُسْرِفِينَ', NULL, 'But no one believed Moses, except [some] offspring [i.e., youths] among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors.', 'Maka tidaklah ada yang beriman kepada Nabi Musa melainkan sebilangan kecil dari keturunan kaumnya, itupun dengan keadaan takut kepada Firaun dan ketua-ketua kaum mereka menyeksa mereka; kerana sesungguhnya Firaun bermaharajalela di bumi, dan sebenarnya ia dari orang-orang yang melampaui batas.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 84, 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', 'وَقَالَ مُوسَىٰ يَا قَوْمِ إِن كُنتُمْ آمَنتُم بِاللَّهِ فَعَلَيْهِ تَوَكَّلُوا إِن كُنتُم مُّسْلِمِينَ', NULL, 'And Moses said, "O my people, if you have believed in Allāh, then rely upon Him, if you should be Muslims [i.e., submitting to Him]."', 'Dan Nabi Musa pula berkata (kepada kaumnya): “Wahai kaumku! Kalau sungguh kamu beriman kepada Allah, maka hendaklah kamu berserah diri kepadaNya, jika betul kamu orang-orang Islam (yang berserah diri bulat-bulat kepada Allah)”.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 85, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'فَقَالُوا عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ', NULL, 'So they said, "Upon Allāh do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people', 'Lalu mereka berkata: “Kepada Allah jualah kami berserah. Wahai Tuhan kami! Janganlah Engkau jadikan kami landasan fitnah kesengsaraan bagi kaum yang zalim ganas.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ', NULL, 'And save us by Your mercy from the disbelieving people."', '“Dan selamatkanlah kami dengan rahmatMu dari angkara kaum yang kafir”.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 87, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّآ لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَاجْعَلُوا بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا الصَّلَاةَ وَبَشِّرِ الْمُؤْمِنِينَ', NULL, 'And We inspired to Moses and his brother, "Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers."', 'Dan (setelah itu), Kami wahyukan kepada Nabi Musa serta saudaranya (Nabi Harun): “Hendaklah kamu berdua mendirikan rumah-rumah di Mesir untuk menempatkan kaum kamu, dan jadikanlah rumah-rumah kamu tempat sembahyang, serta dirikanlah sembahyang di dalamnya; dan sampaikanlah berita gembira kepada orang-orang yang beriman (bahawa mereka akan diselamatkan dari kezaliman Firaun dan kaumnya)”.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 88, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'وَقَالَ مُوسَىٰ رَبَّنَا إِنَّكَ آتَيْتَ فِرْعَوْنَ وَمَلَأَهُ زِينَةً وَأَمْوَالًا فِي الْحَيَاةِ الدُّنْيَا رَبَّنَا لِيُضِلُّوا عَن سَبِيلِكَ رَبَّنَا اطْمِسْ عَلَىٰ أَمْوَالِهِمْ وَاشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ', NULL, 'And Moses said, "Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment."', 'Dan Nabi Musa pula (merayu dengan) berkata: “Wahai Tuhan kami! Sesungguhnya Engkau telah memberikan kepada Firaun dan ketua-ketua kaumnya barang-barang perhiasan dan harta benda yang mewah dalam kehidupan dunia ini. Wahai Tuhan kami! (Kemewahan yang Engkau berikan kepada mereka) akibatnya menyesatkan mereka dari jalanMu (dengan sebab kekufuran mereka). Wahai Tuhan kami! Binasakanlah harta benda mereka dan meteraikanlah hati mereka (sehingga menjadi keras membatu), maka dengan itu mereka tidak akan dapat beriman sehingga mereka melihat azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 218, 11, 87, 180, FALSE, 0, NULL),
(10, 89, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَاسْتَقِيمَا وَلَا تَتَّبِعَانِّ سَبِيلَ الَّذِينَ لَا يَعْلَمُونَ', NULL, '[Allāh] said, "Your supplication has been answered." So remain on a right course and follow not the way of those who do not know."', 'Allah berfirman: “Sesungguhnya telah dikabulkan doa kamu berdua; oleh itu hendaklah kamu tetap (menjalankan perintahKu seterusnya), dan janganlah kamu menurut jalan orang-orang yang tidak mengetahui (peraturan janjiKu)”.', FALSE, NULL, NULL, 219, 11, 87, 180, FALSE, 0, NULL),
(10, 90, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', 'وَجَاوَزْنَا بِبَنِي إِسْرَائِيلَ الْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ بَغْيًا وَعَدْوًا حَتَّىٰ إِذَا أَدْرَكَهُ الْغَرَقُ قَالَ آمَنتُ أَنَّهُ لَا إِلَٰهَ إِلَّا الَّذِي آمَنَتْ بِهِ بَنُو إِسْرَائِيلَ وَأَنَا مِنَ الْمُسْلِمِينَ', NULL, 'And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, "I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims."', 'Dan Kami bawakan Bani Israil ke seberang Laut Merah, lalu dikejar oleh Firaun dan tenteranya, dengan tujuan melakukan kezaliman dan pencerobohan, sehingga apabila Firaun hampir tenggelam berkatalah ia (pada saat yang genting itu): “Aku percaya, bahawa tiada Tuhan melainkan yang dipercayai oleh Bani Israil, dan aku adalah dari orang-orang yang berserah diri (menurut perintah)”.', FALSE, NULL, NULL, 219, 11, 88, 180, FALSE, 0, NULL),
(10, 91, 'ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', 'آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ الْمُفْسِدِينَ', NULL, 'Now? And you had disobeyed [Him] before and were of the corrupters?', '(Allah berfirman): “Adakah sekarang (baharu engkau beriman), padahal sesungguhnya engkau dari dahulu telah kufur derhaka, dan engkau telahpun menjadi dari orang-orang yang melakukan kerosakan?.', FALSE, NULL, NULL, 219, 11, 88, 180, FALSE, 0, NULL),
(10, 92, 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ', 'فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ آيَةً وَإِنَّ كَثِيرًا مِّنَ النَّاسِ عَنْ آيَاتِنَا لَغَافِلُونَ', NULL, 'So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless.', '“Maka pada hari ini, Kami biarkan engkau (hai Firaun) terlepas dengan badanmu (yang tidak bernyawa, daripada ditelan laut), untuk menjadi tanda bagi orang-orang yang di belakangmu (supaya mereka mengambil itibar). Dan (ingatlah) sesungguhnya kebanyakan manusia lalai daripada (memerhati dan memikirkan) tanda-tanda kekuasaan Kami!”.', FALSE, NULL, NULL, 219, 11, 88, 180, FALSE, 0, NULL),
(10, 93, 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'وَلَقَدْ بَوَّأْنَا بَنِي إِسْرَائِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَاهُم مِّنَ الطَّيِّبَاتِ فَمَا اخْتَلَفُوا حَتَّىٰ جَاءَهُمُ الْعِلْمُ إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ', NULL, 'And We had certainly settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', 'Dan sesungguhnya Kami telah menempatkan Bani Israil di negeri yang baik (sesudah Kami binasakan Firaun), dan Kami mengurniakan mereka dengan benda-benda yang baik. Maka mereka tidak berselisihan (mengenai Nabi Muhammad melainkan) setelah datang kepada mereka pengetahuan (dari bukti-bukti yang nyata). Sesungguhnya Tuhanmu akan menghukum di antara mereka pada hari kiamat tentang apa yang mereka perselisihan itu.', FALSE, NULL, NULL, 219, 11, 88, 181, FALSE, 0, NULL),
(10, 94, 'فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'فَإِن كُنتَ فِي شَكٍّ مِّمَّا أَنزَلْنَا إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَابَ مِن قَبْلِكَ لَقَدْ جَاءَكَ الْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ', NULL, 'So if you are in doubt, [O Muḥammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters.', 'Oleh sebab itu, sekiranya engkau (wahai Muhammad) merasa ragu-ragu tentang apa yang Kami turukan kepadamu, maka bertanyalah kepada orang-orang yang membaca kitab-kitab yang diturunkan dahulu daripadamu (kerana mereka mengetahui kebenarannya). Sesungguhnya telah datang kepadamu kebenaran dari Tuhanmu, maka jangan sekali-kali engkau menjadi dari golongan yang ragu-ragu.', FALSE, NULL, NULL, 219, 11, 88, 181, FALSE, 0, NULL),
(10, 95, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ', 'وَلَا تَكُونَنَّ مِنَ الَّذِينَ كَذَّبُوا بِآيَاتِ اللَّهِ فَتَكُونَ مِنَ الْخَاسِرِينَ', NULL, 'And never be of those who deny the signs of Allāh and [thus] be among the losers.', 'Dan jangan sekali-kali engkau menjadi dari golongan yang mendustakan ayat-ayat Allah, kerana dengan itu engkau akan menjadi dari orang-orang yang rugi.', FALSE, NULL, NULL, 219, 11, 88, 181, FALSE, 0, NULL),
(10, 96, 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', 'إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', NULL, 'Indeed, those upon whom the word [i.e., decree] of your Lord has come into effect will not believe,', 'Sesungguhnya orang-orang yang telah ditetapkan atas mereka hukuman Tuhanmu (dengan azab), mereka tidak akan beriman:', FALSE, NULL, NULL, 219, 11, 88, 181, FALSE, 0, NULL),
(10, 97, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'وَلَوْ جَاءَتْهُمْ كُلُّ آيَةٍ حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ', NULL, 'Even if every sign should come to them, until they see the painful punishment.', 'Walaupun datang kepada mereka segala jenis keterangan dan tanda-tanda (yang membuktikan kekuasaan Allah dan kebenaran Rasul-rasulNya), sehingga mereka melihat azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 219, 11, 88, 181, FALSE, 0, NULL),
(10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ', 'فَلَوْلَا كَانَتْ قَرْيَةٌ آمَنَتْ فَنَفَعَهَا إِيمَانُهَا إِلَّا قَوْمَ يُونُسَ لَمَّا آمَنُوا كَشَفْنَا عَنْهُمْ عَذَابَ الْخِزْيِ فِي الْحَيَاةِ الدُّنْيَا وَمَتَّعْنَاهُمْ إِلَىٰ حِينٍ', NULL, 'Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment [i.e., provision] for a time.', '(Dengan kisah Firaun itu) maka ada baiknya kalau (penduduk) sesebuah negeri beriman (sebelum mereka ditimpa azab), supaya imannya itu mendatangkan manfaat menyelamatkannya. Hanya kaum Nabi Yunus sahaja yang telah berbuat demikian - ketika mereka beriman, Kami elakkan azab sengsara yang membawa kehinaan dalam kehidupan dunia dari menimpa mereka, dan Kami berikan mereka menikmati kesenangan sehingga ke suatu masa (yang Kami tentukan).', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 99, 'وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', 'وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَن فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ النَّاسَ حَتَّىٰ يَكُونُوا مُؤْمِنِينَ', NULL, 'And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muḥammad], would you compel the people in order that they become believers?', 'Dan (bukanlah tanggungjawabmu wahai Muhammad menjadikan seluruh umat manusia beriman), jika Tuhanmu menghendaki nescaya berimanlah sekalian manusia yang ada di bumi. (Janganlah engkau bersedih hati tentang kedegilan orang-orang yang ingkar itu; kalau Tuhan tidak menghendaki) maka patutkah engkau pula hendak memaksa manusia supaya mereka menjadi orang-orang yang beriman?', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 100, 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ اللَّهِ وَيَجْعَلُ الرِّجْسَ عَلَى الَّذِينَ لَا يَعْقِلُونَ', NULL, 'And it is not for a soul [i.e., anyone] to believe except by permission of Allāh, and He will place defilement upon those who will not use reason.', 'Dan tiadalah sebarang kuasa bagi seseorang untuk beriman melainkan dengan izin Allah (melalui undang-undang dan peraturanNya); dan Allah menimpakan azab atas orang-orang yang tidak mahu memahami (perintah-perintahNya).', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 101, 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا تُغْنِى ٱلْـَٔايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ', 'قُلِ انظُرُوا مَاذَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَمَا تُغْنِي الْآيَاتُ وَالنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ', NULL, 'Say, "Observe what is in the heavens and the earth." But of no avail will be signs or warners to a people who do not believe.', 'Katakanlah (wahai Muhammad): “Perhatikan dan fikirkanlah apa yang ada di langit dan di bumi dari segala kejadian yang menakjubkan, yang membuktikan keesaan Allah dan kekuasaanNya). Dalam pada itu, segala tanda dan bukti (yang menunjukkan kekuasaan Allah), dan segala Rasul (yang menyampaikan perintah-perintah Allah dan memberi amaran), tidak akan memberi faedah kepada orang-orang yang tidak menaruh kepercayaan kepadanya.', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 102, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ الَّذِينَ خَلَوْا مِن قَبْلِهِمْ قُلْ فَانتَظِرُوا إِنِّي مَعَكُم مِّنَ الْمُنتَظِرِينَ', NULL, 'So do they wait except for like [what occurred in] the days of those who passed on before them? Say, "Then wait; indeed, I am with you among those who wait."', 'Maka orang-orang yang tersebut tidak menunggu melainkan (azab Allah) sebagaimana kejadian-kejadian yang berlaku kepada orang-orang yang ingkar yang terdahulu daripada mereka. Katakanlah (wahai Muhammad): “Tunggulah, sesungguhnya aku juga bersama-sama kamu dari orang-orang yang menunggu”.', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 103, 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', 'ثُمَّ نُنَجِّي رُسُلَنَا وَالَّذِينَ آمَنُوا كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ الْمُؤْمِنِينَ', NULL, 'Then We will save Our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers.', 'Kemudian Kami selamatkan Rasul Kami dan orang-orang yang beriman. Demikianlah juga, sebagai kewajipan Kami, Kami selamatkan orang-orang yang beriman yang menurutmu).', FALSE, NULL, NULL, 220, 11, 88, 181, FALSE, 0, NULL),
(10, 104, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'قُلْ يَا أَيُّهَا النَّاسُ إِن كُنتُمْ فِي شَكٍّ مِّن دِينِي فَلَا أَعْبُدُ الَّذِينَ تَعْبُدُونَ مِن دُونِ اللَّهِ وَلَٰكِنْ أَعْبُدُ اللَّهَ الَّذِي يَتَوَفَّاكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُؤْمِنِينَ', NULL, 'Say, [O Muḥammad], "O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allāh; but I worship Allāh, who causes your death. And I have been commanded to be of the believers', 'Katakanlah (wahai Muhammad): “Wahai sekalian manusia! Sekiranya kamu menaruh syak tentang kebenaran ugamaku, maka (ketahuilah) aku tidak menyembah makhluk-makhluk yang kamu menyembahnya yang lain dari Allah, tetapi aku hanya menyembah Allah yang akan mematikan kamu (untuk menerima balasan); dan aku diperintahkan supaya menjadi dari golongan yang beriman.', FALSE, NULL, NULL, 220, 11, 88, 182, FALSE, 0, NULL),
(10, 105, 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ الْمُشْرِكِينَ', NULL, 'And [commanded], ''Direct your face [i.e., self] toward the religion, inclining to truth, and never be of those who associate others with Allāh;', '“Serta (diwajibkan kepadaku): ‘Hadapkanlah seluruh dirimu menuju (ke arah mengerjakan perintah-perintah) ugama dengan betul dan ikhlas, dan janganlah engkau menjadi dari orang-orang musyrik’.”', FALSE, NULL, NULL, 220, 11, 88, 182, FALSE, 0, NULL),
(10, 106, 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّٰلِمِينَ', 'وَلَا تَدْعُ مِن دُونِ اللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ الظَّالِمِينَ', NULL, 'And do not invoke besides Allāh that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.''"', 'Dan janganlah engkau (wahai Muhammad) menyembah atau memuja yang lain dari Allah, yang tidak dapat mendatangkan manfaat kepadamu dan juga tidak dapat mendatangkan mudarat kepadamu. Oleh itu, sekiranya engkau mengerjakan yang demikian, maka pada saat itu menjadilah engkau dari orang-orang yang berlaku zalim (terhadap diri sendiri dengan perbuatan syirik itu).', FALSE, NULL, NULL, 220, 11, 88, 182, FALSE, 0, NULL),
(10, 107, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ يُصِيبُ بِهِ مَن يَشَاءُ مِنْ عِبَادِهِ وَهُوَ الْغَفُورُ الرَّحِيمُ', NULL, 'And if Allāh should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful.', 'Dan jika Allah mengenakan engkau dengan sesuatu yang membahayakan, maka tiada sesiapa pun yang akan dapat menghapuskannya melainkan Dia; dan jika Ia menghendaki engkau beroleh sesuatu kebaikan, maka tiada sesiapapun yang akan dapat menghalangi limpah kurniaNya. Allah melimpahkan kurniaNya itu kepada sesiapa yang dikendakiNya dari hamba-hambaNya, dan Dia lah yang Maha Pengampun lagi Maha Mengasihani.', FALSE, NULL, NULL, 221, 11, 88, 182, FALSE, 0, NULL),
(10, 108, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ', 'قُلْ يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الْحَقُّ مِن رَّبِّكُمْ فَمَنِ اهْتَدَىٰ فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا أَنَا عَلَيْكُم بِوَكِيلٍ', NULL, 'Say, "O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager."', 'Katakanlah (wahai Muhammad): “Wahai sekalian manusia! Telah datang kepada kamu kebenaran (Al-Quran) dari Tuhan kamu. Oleh itu sesiapa yang mendapat hidayah petunjuk (beriman kepadanya), maka faedah hidayah petunjuk itu terpulang kepada dirinya sendiri; dan sesiapa yang sesat (mengingkarinya) maka bahaya kesesatannya itu tertimpa ke atas dirinya sendiri dan aku pula bukanlah menjadi wakil yang menguruskan soal (iman atau keingkaran) kamu”.', FALSE, NULL, NULL, 221, 11, 88, 182, FALSE, 0, NULL),
(10, 109, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'وَاتَّبِعْ مَا يُوحَىٰ إِلَيْكَ وَاصْبِرْ حَتَّىٰ يَحْكُمَ اللَّهُ وَهُوَ خَيْرُ الْحَاكِمِينَ', NULL, 'And follow what is revealed to you, [O Muḥammad], and be patient until Allāh will judge. And He is the best of judges.', 'Dan turutlah apa yang diwahyukan kepadamu serta bersabarlah (dalam perjuangan mengembangkan Islam) sehingga Allah menghukum (di antaramu dengan golongan yang ingkar, dan memberi kepadamu kemenangan yang telah dijanjikan), kerana Dia lah sebaik-baik Hakim.', FALSE, NULL, NULL, 221, 11, 88, 182, FALSE, 0, NULL),
(11, 1, 'الٓر ۚ كِتَـٰبٌ أُحْكِمَتْ ءَايَـٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'الر كتاب احكمت اياته ثم فصلت من لدن حكيم خبير', NULL, 'Alif, Lām, Rā. [This is] a Book whose verses are perfected and then presented in detail from [one who is] Wise and Aware', 'Alif, Laam, Raa''. Al-Quran sebuah Kitab yang tersusun ayat-ayatnya dengan tetap teguh, kemudian dijelaskan pula kandungannya satu persatu. (Susunan dan penjelasan itu) adalah dari sisi Allah Yang Maha Bijaksana, lagi Maha Mendalam pengetahuanNya.', FALSE, NULL, NULL, 221, 11, 88, 183, FALSE, 10, NULL),
(11, 2, 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۚ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ', 'الا تعبدوا الا الله انني لكم منه نذير وبشير', NULL, '[Through a messenger, saying], "Do not worship except Allāh. Indeed, I am to you from Him a warner and a bringer of good tidings,"', '(Al-Quran yang demikian sifatnya diturunkan oleh Allah) supaya janganlah kamu menyembah sesuatupun melainkan Allah. (Katakanlah wahai Muhammad): “Sesungguhnya aku diutus oleh Allah kepada kamu, sebagai pemberi amaran (kepada orang-orang yang (ingkar), dan pembawa berita gembira (kepada orang-orang yang (beriman).', FALSE, NULL, NULL, 221, 11, 88, 183, FALSE, 9, NULL),
(11, 3, 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَـٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ ۖ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ', 'وان استغفروا ربكم ثم توبوا اليه يمتعكم متاعا حسنا الى اجل مسمى ويؤت كل ذي فضل فضله وان تولوا فاني اخاف عليكم عذاب يوم كبير', NULL, 'And [saying], "Seek forgiveness of your Lord and repent to Him, [and] He will let you enjoy a good provision for a specified term and give every doer of favor his favor [i.e., reward]. But if you turn away, then indeed, I fear for you the punishment of a great Day.', 'Dan hendaklah kamu meminta ampun kepada Tuhan kamu (dari perbuatan syirik), kemudian hendaklah kamu rujuk kembali taat kepadaNya; supaya Ia memberi kamu nikmat kesenangan hidup yang baik (di dunia) hingga ke suatu masa yang tertentu, dan (di akhirat pula) Ia akan memberi kepada tiap-tiap seorang yang mempunyai kelebihan (dalam sebarang amal yang soleh) akan pahala kelebihannya itu; dan jika kamu berpaling (membelakangkan tiga perkara itu), maka sesungguhnya aku bimbang kamu akan beroleh azab hari kiamat yang besar (huru-haranya).', FALSE, NULL, NULL, 221, 11, 88, 183, FALSE, 25, NULL),
(11, 4, 'إِلَى ٱللَّهِ مَرْجِعُكُمْ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'الى الله مرجعكم وهو على كل شيء قدير', NULL, 'To Allāh is your return, and He is over all things competent."', 'Kepada Allah jualah kembalinya kamu, dan Ia Maha Kuasa atas tiap-tiap sesuatu”.', FALSE, NULL, NULL, 221, 11, 88, 183, FALSE, 8, NULL),
(11, 5, 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'الا انهم يثنون صدورهم ليستخفوا منه الا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون انه عليم بذات الصدور', NULL, 'Unquestionably, they [i.e., the disbelievers] turn away their breasts to hide themselves from him. Unquestionably, [even] when they cover themselves in their clothing, He [i.e., Allāh] knows what they conceal and what they declare. Indeed, He is Knowing of that within the breasts.', 'Ketahuilah! Sesungguhnya mereka yang ingkar itu membongkokkan badan mereka untuk menyembunyikan (perasaan buruk yang ada dalam dada mereka) daripada Allah. Ketahuilah! Semasa mereka berselubung dengan pakaian mereka sekalipun, Allah mengetahui apa yang mereka sembunyikan dan apa yang mereka zahirkan; sesungguhnya Ia Maha Mengetahui akan segala (isi hati) yang ada di dalam dada.', FALSE, NULL, NULL, 221, 11, 88, 183, FALSE, 19, NULL),
(11, 6, '۞ وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّ فِى كِتَـٰبٍ مُّبِينٍ', 'وما من دابة في الارض الا على الله رزقها ويعلم مستقرها ومستودعها كل في كتاب مبين', NULL, 'And there is no creature on earth but that upon Allāh is its provision, and He knows its place of dwelling and place of storage. All is in a clear register.', 'Dan tiadalah sesuatupun dari makhluk-makhluk yang bergerak di bumi melainkan Allah jualah yang menanggung rezekinya dan mengetahui tempat kediamannya dan tempat ia disimpan. Semuanya itu tersurat di dalam Kitab (Lauh mahfuz) yang nyata (kepada malaikat-malaikat yang berkenaan).', FALSE, NULL, NULL, 222, 12, 89, 183, FALSE, 16, NULL),
(11, 7, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۗ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'وهو الذي خلق السماوات والارض في ستة ايام وكان عرشه على الماء ليبلوكم ايكم احسن عملا ولئن قلت انكم مبعوثون من بعد الموت ليقولن الذين كفروا ان هذا الا سحر مبين', NULL, 'And it is He who created the heavens and the earth in six days - and His Throne had been upon water - that He might test you as to which of you is best in deed. But if you say, "Indeed, you are resurrected after death," those who disbelieve will surely say, "This is not but obvious magic."', 'Dan Dia lah yang menjadikan langit dan bumi dalam enam masa, sedang “ArasyNya, berada di atas air (Ia menjadikan semuanya itu untuk menguji kamu: siapakah di antara kamu yang lebih baik amalnya. Dan demi sesungguhnya! Jika engkau (wahai Muhammad) berkata: “Bahawa kamu akan dibangkitkan hidup kembali sesudah mati” tentulah orang-orang yang ingkar akan berkata: “Ini tidak lain, hanyalah seperti sihir yang nyata (tipuannya)”.', FALSE, NULL, NULL, 222, 12, 89, 183, FALSE, 31, NULL),
(11, 8, 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'ولئن اخرنا عنهم العذاب الى امة معدودة ليقولن ما يحبسه الا يوم ياتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزئون', NULL, 'And if We hold back from them the punishment for a limited time, they will surely say, "What detains it?" Unquestionably, on the Day it comes to them, it will not be averted from them, and they will be enveloped by what they used to ridicule.', 'Dan demi sesungguhnya! Jika kami tangguhkan azab daripada menimpa mereka hingga ke suatu masa yang tertentu, tentulah mereka akan berkata (secara mengejek): “Apakah yang menghalangnya?” Ketahuilah! Pada hari datangnya azab itu kepada mereka, tidak akan dapat ditolak daripada menimpa mereka, dan tentulah mereka akan diliputi oleh azab yang mereka telah ejek-ejek itu.', FALSE, NULL, NULL, 222, 12, 89, 183, FALSE, 22, NULL),
(11, 9, 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَـٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَـٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ', 'ولئن اذقنا الانسان منا رحمة ثم نزعناها منه انه ليئوس كفور', NULL, 'And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful.', 'Dan demi sesungguhnya! Jika Kami rasakan manusia sesuatu pemberian rahmat dari Kami kemudian Kami tarik balik pemberian itu daripadanya, mendapati dia amat berputus asa, lagi amat tidak bersyukur.', FALSE, NULL, NULL, 222, 12, 89, 184, FALSE, 11, NULL),
(11, 10, 'وَلَئِنْ أَذَقْنَـٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌ فَخُورٌ', 'ولئن اذقناه نعماء بعد ضراء مسته ليقولن ذهب السيئات عني انه لفرح فخور', NULL, 'But if We give him a taste of favor after hardship has touched him, he will surely say, "Bad times have left me." Indeed, he is exultant and boastful -', 'Dan demi sesungguhnya! kalau Kami memberinya pula kesenangan sesudah ia menderita kesusahan, tentulah ia akan berkata: “Telah hilang lenyaplah dariku segala kesusahan yang menimpaku”. Sesungguhnya ia (dengan kesenangannya itu) riang gembira, lagi bermegah-megah (kepada orang ramai).', FALSE, NULL, NULL, 222, 12, 89, 184, FALSE, 13, NULL),
(11, 11, 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'الا الذين صبروا وعملوا الصالحات اولئك لهم مغفرة واجر كبير', NULL, 'Except for those who are patient and do righteous deeds; those will have forgiveness and great reward.', 'Kecuali orang-orang yang sabar dan mengerjakan amal soleh maka mereka itu akan beroleh keampunan dan pahala yang besar.', FALSE, NULL, NULL, 222, 12, 89, 184, FALSE, 10, NULL),
(11, 12, 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ ۚ إِنَّمَآ أَنتَ نَذِيرٌ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'فلعلك تارك بعض ما يوحى اليك وضائق به صدرك ان يقولوا لولا انزل عليه كنز او جاء معه ملك انما انت نذير والله على كل شيء وكيل', NULL, 'Then would you possibly leave [out] some of what is revealed to you, or is your breast constrained by it because they say, "Why has there not been sent down to him a treasure or come with him an angel?" But you are only a warner. And Allāh is Disposer of all things.', 'Jangan-jangan engkau (wahai Muhammad) tidak menyampaikan sebahagian dari apa yang diwahyukan kepadamu serta merasa sempit dada untuk menyampaikannya disebabkan orang-orang yang ingkar itu berkata: “Mengapa tidak diturunkan kepada (Muhammad) perbendaharaan (harta benda yang banyak), ataupun datang bersama-sama dengannya malaikat (untuk menolongnya menyiarkan Islam)?” Kerana sesungguhnya engkau hanyalah seorang Rasul pemberi amaran kepada orang-orang yang ingkar, dan Allah jualah Pentadbir yang menguruskan tiap-tiap sesuatu (maka berserahlah diri kepadaNya).', FALSE, NULL, NULL, 222, 12, 89, 184, FALSE, 27, NULL),
(11, 13, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَـٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ', 'ام يقولون افتراه قل فاتوا بعشر سور مثله مفتريات وادعوا من استطعتم من دون الله ان كنتم صادقين', NULL, 'Or do they say, "He invented it"? Say, "Then bring ten sūrahs like it that have been invented and call upon [for assistance] whomever you can besides Allāh, if you should be truthful."', 'Bukan itu sahaja kata-kata mereka bahkan mereka menuduh dengan mengatakan: “Ia (Muhammad) yang mereka-reka Al-Quran itu!” katakanlah (wahai Muhammad): “(Jika demikian tuduhan kamu), maka cubalah buat serta datangkan sepuluh surah rekaan yang sebanding dengan Al-Quran itu, dan panggilah siapa sahaja yang kamu sanggup memanggilnya, yang lain dari Allah, jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 18, NULL),
(11, 14, 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَـٰهَ إِلَّا هُوَ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', 'فالم يستجيبوا لكم فاعلموا انما انزل بعلم الله وان لا اله الا هو فهل انتم مسلمون', NULL, 'And if they do not respond to you - then know that it [i.e., the Qur’ān] was revealed with the knowledge of Allāh and that there is no deity except Him. Then, would you [not] be Muslims?', 'Oleh itu, jika mereka (penolong-penolong kamu) tidak dapat melaksanakan permintaan kamu (untuk membuat surah-surah yang sebanding dengan Al-Quran), maka ketahuilah bahawa Al-Quran itu diturunkan hanyalah menurut pengetahuan Allah, dan bahawa tidak ada tuhan yang berhak disembah melainkan Allah. Setelah (terbukti hakikat yang demikian) maka adakah kamu mengakui Islam dan menurut aturannya?', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 16, NULL),
(11, 15, 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَـٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', 'من كان يريد الحياة الدنيا وزينتها نوف اليهم اعمالهم فيها وهم فيها لا يبخسون', NULL, 'Whoever desires the life of this world and its adornments - We fully repay them for their deeds therein, and they therein will not be deprived.', 'Sesiapa yang keadaan usahanya semata-mata berkehendakkan kehidupan dunia dan perhiasannya (dengan tidak disaksikan sama oleh Al-Quran tentang sah batalnya), maka Kami akan sempurnakan hasil usaha mereka di dunia, dan mereka tidak dikurangkan sedikitpun padanya.', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 14, NULL),
(11, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'اولئك الذين ليس لهم في الاخرة الا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون', NULL, 'Those are the ones for whom there is not in the Hereafter but the Fire. And lost is what they did therein, and worthless is what they used to do.', 'Merekalah orang-orang yang tidak ada baginya pada hari akhirat kelak selain daripada azab neraka, dan pada hari itu gugurlah apa yang mereka lakukan di dunia, dan batalah apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 16, NULL),
(11, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۚ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ ۚ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ ۚ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'افمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى اماما ورحمة اولئك يؤمنون به ومن يكفر به من الاحزاب فالنار موعده فلا تك في مرية منه انه الحق من ربك ولكن اكثر الناس لا يؤمنون', NULL, 'So is one who [stands] upon a clear evidence from his Lord [like the aforementioned]? And a witness from Him follows it, and before it was the Scripture of Moses to lead and as mercy. Those [believers in the former revelations] believe in it [i.e., the Qur’ān]. But whoever disbelieves in it from the [various] factions - the Fire is his promised destination. So be not in doubt about it. Indeed, it is the truth from your Lord, but most of the people do not believe.', 'Jika demikian, adakah sama mereka itu dengan orang-orang yang keadaannya sentiasa berdasarkan bukti yang terdapat dari (benda-benda yang diciptakan oleh) Tuhannya, dan diikuti oleh Kitab Suci Al-Quran memberi kenyataan - sebagai saksi dari pihak Tuhan meneguhkan bukti yang tersebut; dan sebelum itu, kenyataan yang serupa diberi oleh Kitab Nabi Musa yang menjadi ikutan dan rahmat (kepada umatnya)? Orang-orang yang berkeadaan demikian, mengakui - menerima Al-Quran; dan sesiapa ingkar akan Al-Quran itu dari kumpulan-kumpulan kaum kafir, maka nerakalah dijanjikan menjadi tempatnya. Oleh itu, janganlah engkau (wahai Muhammad) menaruh perasaan ragu-ragu terhadap Al-Quran, kerana sesungguhnya Al-Quran itu adalah perkara yang benar dari Tuhanmu, tetapi kebanyakan manusia tidak percaya kepadanya.', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 39, NULL),
(11, 18, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَـٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَـٰدُ هَـٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ', 'ومن اظلم ممن افترى على الله كذبا اولئك يعرضون على ربهم ويقول الاشهاد هؤلاء الذين كذبوا على ربهم الا لعنة الله على الظالمين', NULL, 'And who is more unjust than he who invents a lie about Allāh? Those will be presented before their Lord, and the witnesses will say, "These are the ones who lied against their Lord." Unquestionably, the curse of Allāh is upon the wrongdoers', 'Dan tidak ada yang lebih zalim daripada orang-orang yang mereka-reka perkara-perkara dusta terhadap Allah! Orang-orang yang demikian sifatnya akan dibawa mengadap Tuhan mereka, dan pada hari itu akan berkatalah saksi-saksi (dari malaikat-malaikat, Nabi-nabi, dan anggota-anggota tubuh mereka sendiri): “Inilah orang-orang yang membuat-buat dusta terhadap Tuhan mereka”. Ketahuilah (sesungguhnya) laknat Allah tertimpa kepada orang-orang yang zalim!', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 23, NULL),
(11, 19, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ', 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخرة هم كافرون', NULL, 'Who averted [people] from the way of Allāh and sought to make it [seem] deviant while they, concerning the Hereafter, were disbelievers.', 'Orang-orang yang menghalang dirinya sendiri dan orang lain dari jalan ugama Allah dan berusaha supaya jalan itu menjadi bengkok terpesong, sedang mereka pula ingkarkan hari akhirat;', FALSE, NULL, NULL, 223, 12, 89, 184, FALSE, 11, NULL),
(11, 20, 'أُو۟لَـٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ۘ يُضَـٰعَفُ لَهُمُ ٱلْعَذَابُ ۚ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', 'اولئك لم يكونوا معجزين في الارض وما كان لهم من دون الله من اولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون', NULL, 'Those were not causing failure [to Allāh] on earth, nor did they have besides Allāh any protectors. For them the punishment will be multiplied. They were not able to hear, nor did they see.', 'Mereka itu tidak akan dapat melemahkan kekuasaan Allah daripada menimpakan mereka dengan azab di dunia, dan tidak ada pula bagi mereka, yang lain dari Allah, sesiapapun yang dapat menolong melepaskan mereka dari seksaNya. Azab untuk mereka akan digandakan (kerana mereka sangat bencikan jalan ugama Allah), sehingga mereka tidak tahan mendengarnya, dan tidak pula suka melihat tanda-tanda kebenarannya.', FALSE, NULL, NULL, 224, 12, 89, 184, FALSE, 24, NULL),
(11, 21, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'أُولَٰئِكَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'Those are the ones who will have lost themselves, and lost from them is what they used to invent.', 'Merekalah orang-orang yang merugikan diri sendiri, dan hilang lenyaplah dari mereka apa yang mereka ada-adakan.', FALSE, NULL, NULL, 224, 12, 89, 184, FALSE, 0, NULL),
(11, 22, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 'لَا جَرَمَ أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْأَخْسَرُونَ', NULL, 'Assuredly, it is they in the Hereafter who will be the greatest losers.', 'Tidak syak lagi, bahawa sesungguhnya merekalah yang paling rugi, pada hari akhirat kelak.', FALSE, NULL, NULL, 224, 12, 89, 184, FALSE, 0, NULL),
(11, 23, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَخْبَتُوا إِلَىٰ رَبِّهِمْ أُولَٰئِكَ أَصْحَابُ الْجَنَّةِ هُمْ فِيهَا خَالِدُونَ', NULL, 'Indeed, they who have believed and done righteous deeds and humbled themselves to their Lord - those are the companions of Paradise; they will abide eternally therein.', 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal yang soleh, serta tunduk taat menunaikan ibadat kepada Tuhan mereka dengan khusyuk, mereka itulah ahli Syurga, mereka kekal di dalamnya.', FALSE, NULL, NULL, 224, 12, 89, 184, FALSE, 0, NULL),
(11, 24, 'مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ', 'مَثَلُ الْفَرِيقَيْنِ كَالْأَعْمَىٰ وَالْأَصَمِّ وَالْبَصِيرِ وَالسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ', NULL, 'The example of the two parties is like the blind and deaf, and the seeing and hearing. Are they equal in comparison? Then, will you not remember?', 'Bandingan dua golongan (yang kafir dan yang beriman) itu samalah seperti orang yang buta serta pekak, dengan orang yang celik serta mendengar; kedua-dua golongan itu tidaklah sama keadaannya. (Setelah kamu mengetahui yang demikian) maka tidakkah kamu mahu mengambil peringatan dan insaf?', FALSE, NULL, NULL, 224, 12, 90, 184, FALSE, 0, NULL),
(11, 25, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ إِنِّي لَكُمْ نَذِيرٌ مُّبِينٌ', NULL, 'And We had certainly sent Noah to his people, [saying], "Indeed, I am to you a clear warner', 'Dan demi sesungguhnya! Kami telah utuskan Nabi Nuh lalu ia memberitahu kaumnya dengan berkata: “Sesungguhnya aku ini seorang Rasul pemberi amaran yang nyata kepada kamu.', FALSE, NULL, NULL, 224, 12, 90, 185, FALSE, 0, NULL),
(11, 26, 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ', 'أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ', NULL, 'That you not worship except Allāh. Indeed, I fear for you the punishment of a painful day."', '“Iaitu janganlah kamu menyembah melainkan Allah; sesungguhnya aku bimbang (jika kamu menyembah yang lainnya), kamu akan ditimpa azab yang tidak terperi sakitnya pada hari pembalasan”.', FALSE, NULL, NULL, 224, 12, 90, 185, FALSE, 0, NULL),
(11, 27, 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ', 'فَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ مَا نَرَاكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَاكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَرَاذِلُنَا بَادِيَ الرَّأْيِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍ بَلْ نَظُنُّكُمْ كَاذِبِينَ', NULL, 'So the eminent among those who disbelieved from his people said, "We do not see you but as a man like ourselves, and we do not see you followed except by those who are the lowest of us [and] at first suggestion. And we do not see in you over us any merit; rather, we think you are liars."', 'Maka berkatalah ketua-ketua yang kafir dari kaumnya: “Kami tidak memandangmu (wahai Nuh) melainkan sebagai seorang manusia seperti kami; dan kami tidak nampak golongan yang mengikutmu melainkan orang-orang kami yang miskin hina, lagi berfikiran singkat; dan kami juga tidak memandang kamu (semua) mempunyai sebarang kelebihan yang mengatasi kami, bahkan kami menganggap kamu orang-orang pendusta”.', FALSE, NULL, NULL, 224, 12, 90, 185, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(11, 28, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 'قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي رَحْمَةً مِّنْ عِندِهِ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَارِهُونَ', NULL, 'He said, "O my people, have you considered: if I should be upon clear evidence from my Lord while He has given me mercy from Himself but it has been made unapparent to you, should we force it upon you while you are averse to it?', 'Nabi Nuh berkata: “Wahai kaumku! Jika keadaanku berdasarkan bukti yang nyata dari Tuhanku, serta Ia mengurniakan pangkat Nabi kepadaku dari sisiNya, kemudian bukti yang nyata itu menjadi kabur pada pandangan kamu (disebabkan keingkaran kamu yang telah sebati), maka adakah kamu nampak ada gunanya Kami memaksa kamu menerima bukti itu sedang kamu tidak suka kepadanya?', FALSE, NULL, NULL, 224, 12, 90, 185, FALSE, 0, NULL),
(11, 29, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'وَيَا قَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَمَا أَنَا بِطَارِدِ الَّذِينَ آمَنُوا إِنَّهُم مُّلَاقُو رَبِّهِمْ وَلَٰكِنِّي أَرَاكُمْ قَوْمًا تَجْهَلُونَ', NULL, 'And O my people, I ask not of you for it any wealth. My reward is not but from Allāh. And I am not one to drive away those who have believed. Indeed, they will meet their Lord, but I see that you are a people behaving ignorantly.', 'Dan (ketahuilah) wahai kaumku! Aku tidak meminta kepada kamu sebarang harta benda sebagai upah menyampaikan ugama Allah itu, tiadalah aku harapkan upahku melainkan dari Allah semata-mata; dan aku tidak akan menghalau orang-orang yang beriman (sebagaimana yang kamu minta itu), kerana sesungguhnya mereka akan menemui Tuhan mereka (dan pada hari itu mereka akan menuntut dan menerima hak masing-masing); tetapi aku nampak kamu semua, kaum yang tidak mengetahui apa yang mesti diketahui.', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 30, 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ', 'وَيَا قَوْمِ مَن يَنصُرُنِي مِنَ اللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ', NULL, 'And O my people, who would protect me from Allāh if I drove them away? Then will you not be reminded?', 'Dan lagi wahai kaumku! Siapakah yang akan menolongku dari azab Allah jika aku menghalau mereka? Maka mengapa kamu tidak mahu ingatkan kekuasaan Allah?', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 31, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'وَلَا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ إِنِّي مَلَكٌ وَلَا أَقُولُ لِلَّذِينَ تَزْدَرِي أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ اللَّهُ خَيْرًا اللَّهُ أَعْلَمُ بِمَا فِي أَنفُسِهِمْ إِنِّي إِذًا لَّمِنَ الظَّالِمِينَ', NULL, 'And I do not tell you that I have the depositories [containing the provision] of Allāh or that I know the unseen, nor do I tell you that I am an angel, nor do I say of those upon whom your eyes look down that Allāh will never grant them any good. Allāh is most knowing of what is within their souls. Indeed, I would then be among the wrongdoers [i.e., the unjust]."', 'Dan aku tidak pernah berkata kepada kamu: di sisiku ada perbendaharaan Allah, dan tidaklah aku mendakwa mengetahui perkara-perkara yang ghaib dan aku tidak mengatakan bahawa aku ini malaikat; dan aku juga tidak berkata terhadap orang-orang yang beriman yang kamu pandang hina itu, bahawa Allah tidak akan memberi kebaikan kepada mereka. Allah lebih mengetahui akan apa yang ada di dalam hati mereka. Sesungguhnya aku jika bertindak demikian, nescaya menjadilah aku dari orang-orang yang zalim”.', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 32, 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قَالُوا يَا نُوحُ قَدْ جَادَلْتَنَا فَأَكْثَرْتَ جِدَالَنَا فَأْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'They said, "O Noah, you have disputed [i.e., opposed] us and been frequent in dispute of us. So bring us what you threaten us, if you should be of the truthful."', 'Mereka berkata: “Wahai Nuh! Sesungguhnya engkau telah bertikam lidah membantah kami lalu engkau banyakkan sangat hujjah-hujjah semasa mengemukakan bantahanmu kepada kami; oleh itu, datangkanlah azab Allah yang engkau janjikan kepada kami, jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 33, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ اللَّهُ إِن شَاءَ وَمَا أَنتُم بِمُعْجِزِينَ', NULL, 'He said, "Allāh will only bring it to you if He wills, and you will not cause [Him] failure.', 'Nabi Nuh menjawab: “Sesungguhnya Allah jualah yang akan mendatangkan azabNya itu kepada kamu jika Ia kehendaki, dan kamu tidak sekali-kali akan dapat melemahkan kuasa Allah!', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 34, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 'وَلَا يَنفَعُكُمْ نُصْحِي إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ اللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And my advice will not benefit you - although I wished to advise you - if Allāh should intend to put you in error. He is your Lord, and to Him you will be returned."', 'Dan tidak ada gunanya nasihatku kepada kamu, jika aku hendak menasihati kamu, kalau Allah hendak menyesatkan kamu (kerana kamu tetap berdegil); Dia lah Tuhan kamu dan kepadaNya kamu akan kembali”.', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 35, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ', 'أَمْ يَقُولُونَ افْتَرَاهُ قُلْ إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرَامِي وَأَنَا بَرِيءٌ مِّمَّا تُجْرِمُونَ', NULL, 'Or do they say [about Prophet Muḥammad (ﷺ)], "He invented it"? Say, "If I have invented it, then upon me is [the consequence of] my crime; but I am innocent of what [crimes] you commit."', '(Mereka terus berdegil), bahkan mereka menuduh dengan mengatakan Nabi Nuh sengaja mengada-adakan secara dusta: bahawa Tuhan mengurniakan pangkat Nabi kepadanya. Nabi Nuh diperintahkan menjawab dengan berkata: “Kalau aku yang mereka-reka wahyu itu maka akulah yang akan menanggung dosa perbuatanku itu, dan sebenarnya aku bersih dari dosa kesalahan kamu menuduhku”.', FALSE, NULL, NULL, 225, 12, 90, 185, FALSE, 0, NULL),
(11, 36, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', 'وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ آمَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَفْعَلُونَ', NULL, 'And it was revealed to Noah that, "No one will believe from your people except those who have already believed, so do not be distressed by what they have been doing.', 'Dan (setelah itu) diwahyukan kepada Nabi Nuh: “Bahawa sesungguhnya tidak akan beriman lagi dari kaummu melainkan orang-orang yang telah sedia beriman. Oleh itu, janganlah engkau berdukacita tentang apa yang mereka sentiasa lakukan.', FALSE, NULL, NULL, 225, 12, 90, 186, FALSE, 0, NULL),
(11, 37, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', 'وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُم مُّغْرَقُونَ', NULL, 'And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned."', 'Dan buatlah bahtera dengan pengawasan serta kawalan Kami, dan dengan panduan wahyu Kami (tentang cara membuatnya); dan janganlah engkau merayu kepadaKu untuk menolong kaum yang zalim itu, kerana sesungguhnya mereka akan ditenggelamkan (dengan taufan)”.', FALSE, NULL, NULL, 225, 12, 90, 186, FALSE, 0, NULL),
(11, 38, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', 'وَيَصْنَعُ الْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِ سَخِرُوا مِنْهُ قَالَ إِن تَسْخَرُوا مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', NULL, 'And he constructed the ship, and whenever an assembly of the eminent of his people passed by him, they ridiculed him. He said, "If you ridicule us, then we will ridicule you just as you ridicule.', 'Dan Nabi Nuh pun membuat bahtera itu, dan tiap-tiap kali sepuak dari kaumnya melalui tempat ia membina bahteranya, mereka mengejek-ejeknya. Nabi Nuh pun menjawab: “Jika kamu memandang kami bodoh (kerana membuat bahtera ini), maka sesungguhnya kami juga memandang kamu bodoh (kerana keingkaran kamu), sebagai (balasan) ejekan kamu.', FALSE, NULL, NULL, 226, 12, 90, 186, FALSE, 0, NULL),
(11, 39, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', NULL, 'And you are going to know who will get a punishment that will disgrace him [on earth] and upon whom will descend an enduring punishment [in the Hereafter]."', 'Maka kamu akan mengetahui siapakah yang akan didatangi azab yang menghinakannya di dunia, dan yang akan ditimpakan pula dengan azab yang kekal pada hari akhirat kelak”.', FALSE, NULL, NULL, 226, 12, 90, 186, FALSE, 0, NULL),
(11, 40, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ', 'حَتَّىٰ إِذَا جَاءَ أَمْرُنَا وَفَارَ التَّنُّورُ قُلْنَا احْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ وَمَنْ آمَنَ وَمَا آمَنَ مَعَهُ إِلَّا قَلِيلٌ', NULL, '[So it was], until when Our command came and the oven overflowed, We said, "Load upon it [i.e., the ship] of each [creature] two mates and your family, except those about whom the word [i.e., decree] has preceded, and [include] whoever has believed." But none had believed with him, except a few.', '(Nabi Nuh terus bekerja) sehingga apabila datang hukum Kami untuk membinasakan mereka dan air memancut-mancut dari muka bumi (yang menandakan kedatangan taufan), Kami berfirman kepada Nabi Nuh: “Bawalah dalam bahtera itu dua dari tiap-tiap sejenis haiwan (jantan dan betina), dan bawalah ahlimu kecuali orang yang telah ditetapkan hukuman azab atasnya (disebabkan kekufurannya), juga bawalah orang-orang beriman”. Dan tidak ada orang-orang yang beriman yang turut bersama-samanya, melainkan sedikit sahaja.', FALSE, NULL, NULL, 226, 12, 90, 186, FALSE, 0, NULL),
(11, 41, 'وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ', 'وَقَالَ ارْكَبُوا فِيهَا بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا إِنَّ رَبِّي لَغَفُورٌ رَّحِيمٌ', NULL, 'And [Noah] said, "Embark therein; in the name of Allāh [are] its course and its anchorage. Indeed, my Lord is Forgiving and Merciful."', 'Dan (ketika itu) berkatalah Nabi Nuh (kepada pengikut-pengikutnya yang beriman): “Naiklah kamu ke bahtera itu sambil berkata: ‘Dengan nama Allah bergerak lajunya dan berhentinya’. Sesungguhnya Tuhanku adalah Maha Pengampun, lagi Maha Mengasihani.”', FALSE, NULL, NULL, 226, 12, 91, 186, FALSE, 0, NULL),
(11, 42, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 'وَهِيَ تَجْرِي بِهِمْ فِي مَوْجٍ كَالْجِبَالِ وَنَادَىٰ نُوحٌ ابْنَهُ وَكَانَ فِي مَعْزِلٍ يَا بُنَيَّ ارْكَب مَّعَنَا وَلَا تَكُن مَّعَ الْكَافِرِينَ', NULL, 'And it sailed with them through waves like mountains, and Noah called to his son who was apart [from them], "O my son, come aboard with us and be not with the disbelievers."', '(Mereka semua naik) dan bahtera itupun bergerak laju membawa mereka dalam ombak yang seperti gunung-ganang, dan (sebelum itu) Nabi Nuh memanggil anaknya, yang sedang berada di tempat yang terpisah daripadanya: “Wahai anakku, naiklah bersama-sama kami, dan janganlah engkau tinggal dengan orang-orang yang kafir”.', FALSE, NULL, NULL, 226, 12, 91, 186, FALSE, 0, NULL),
(11, 43, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', 'قَالَ سَآوِي إِلَىٰ جَبَلٍ يَعْصِمُنِي مِنَ الْمَاءِ قَالَ لَا عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا الْمَوْجُ فَكَانَ مِنَ الْمُغْرَقِينَ', NULL, '[But] he said, "I will take refuge on a mountain to protect me from the water." [Noah] said, "There is no protector today from the decree of Allāh, except for whom He gives mercy." And the waves came between them, and he was among the drowned.', 'Anaknya menjawab: “Aku akan pergi berlindung ke sebuah gunung yang dapat menyelamatkan aku daripada ditenggelamkan oleh air”. Nabi Nuh berkata: “Hari ini tidak ada sesuatupun yang akan dapat melindungi dari azab Allah, kecuali orang yang dikasihani olehNya”. Dan dengan serta-merta ombak itu pun memisahkan antara keduanya, lalu menjadilah ia (anak yang derhaka itu) dari orang-orang yang ditenggelamkan oleh taufan.', FALSE, NULL, NULL, 226, 12, 91, 186, FALSE, 0, NULL),
(11, 44, 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ وَيَا سَمَاءُ أَقْلِعِي وَغِيضَ الْمَاءُ وَقُضِيَ الْأَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ الظَّالِمِينَ', NULL, 'And it was said, "O earth, swallow your water, and O sky, withhold [your rain]." And the water subsided, and the matter was accomplished, and it [i.e., the ship] came to rest on the [mountain of] Jūdiyy. And it was said, "Away with the wrongdoing people."', 'Dan (setelah binasanya kaum kafir itu) diperintahkan kepada bumi dan langit dengan berkata: “Wahai bumi telanlah airmu, dan wahai langit berhentilah dari curahan hujanmu”. Dan (ketika itu) surutlah air, serta terlaksanalah perintah (Allah) itu. Dan bahtera Nabi Nuh itupun berhenti di atas gunung “Judi” serta diingatkan (kepada kaum kafir umumnya bahawa): “Kebinasaanlah akhirnya bagi orang-orang yang zalim”.', FALSE, NULL, NULL, 226, 12, 91, 186, FALSE, 0, NULL),
(11, 45, 'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', 'وَنَادَىٰ نُوحٌ رَّبَّهُ فَقَالَ رَبِّ إِنَّ ابْنِي مِنْ أَهْلِي وَإِنَّ وَعْدَكَ الْحَقُّ وَأَنتَ أَحْكَمُ الْحَاكِمِينَ', NULL, 'And Noah called to his Lord and said, "My Lord, indeed my son is of my family; and indeed, Your promise is true; and You are the most just of judges!"', 'Dan Nabi Nuh merayu kepada Tuhannya dengan berkata: “Wahai Tuhanku! Sesungguhnya anakku itu dari keluargaku sendiri, dan bahawa janjiMu itu adalah benar, dan Engkau adalah sebijak-bijak Hakim yang menghukum dengan seadil-adilnya”.', FALSE, NULL, NULL, 226, 12, 91, 186, FALSE, 0, NULL),
(11, 46, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'قَالَ يَا نُوحُ إِنَّهُ لَيْسَ مِنْ أَهْلِكَ إِنَّهُ عَمَلٌ غَيْرُ صَالِحٍ فَلَا تَسْأَلْنِ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنِّي أَعِظُكَ أَن تَكُونَ مِنَ الْجَاهِلِينَ', NULL, 'He said, "O Noah, indeed he is not of your family; indeed, he is [one whose] work was other than righteous, so ask Me not for that about which you have no knowledge. Indeed, I advise you, lest you be among the ignorant."', 'Allah berfirman: “Wahai Nuh! Sesungguhnya anakmu itu bukanlah dari keluargamu (kerana ia telah terputus hubungan denganmu disebabkan kekufurannya); sesungguhnya bawaannya bukanlah amal yang soleh, maka janganlah engkau memohon kepadaKu sesuatu yang engkau tidak mempunyai pengetahuan mengenainya. Sebenarnya Aku melarangmu dari menjadi orang yang jahil”.', FALSE, NULL, NULL, 227, 12, 91, 186, FALSE, 0, NULL),
(11, 47, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', 'قَالَ رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِينَ', NULL, '[Noah] said, "My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers."', 'Nabi Nuh berkata: “Wahai Tuhanku! Sesungguhnya aku berlindung kepadaMu daripada memohon sesuatu yang aku tidak mempunyai pengetahuan mengenainya; dan jika Engkau tidak mengampunkan dosaku, dan memberi rahmat kepadaku, nescaya menjadilah aku dari orang-orang yang rugi”.', FALSE, NULL, NULL, 227, 12, 91, 186, FALSE, 0, NULL),
(11, 48, 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', 'قِيلَ يَا نُوحُ اهْبِطْ بِسَلَامٍ مِّنَّا وَبَرَكَاتٍ عَلَيْكَ وَعَلَىٰ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', NULL, 'It was said, "O Noah, disembark in security from Us and blessings upon you and upon nations [descending] from those with you. But other nations [of them] We will grant enjoyment; then there will touch them from Us a painful punishment."', 'Allah berfirman: Wahai Nuh! Turunlah (dari bahtera itu) dengan selamat dan berkat dari Kami kepadamu dan kepada umat-umat yang bersama-samamu. Dan (dalam pada itu) ada umat-umat dari keturunan mereka yang Kami akan beri kesenangan kepadanya (dalam kehidupan dunia), kemudian mereka akan dikenakan azab dari Kami yang tidak terperi sakitnya”.', FALSE, NULL, NULL, 227, 12, 91, 186, FALSE, 0, NULL),
(11, 49, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَٱصْبِرْ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 'تِلْكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهَا إِلَيْكَ مَا كُنتَ تَعْلَمُهَا أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَاصْبِرْ إِنَّ الْعَاقِبَةَ لِلْمُتَّقِينَ', NULL, 'That is from the news of the unseen which We reveal to you, [O Muḥammad]. You knew it not, neither you nor your people, before this. So be patient; indeed, the [best] outcome is for the righteous.', '(Kisah Nabi Nuh) itu adalah dari perkara-perkara yang ghaib yang Kami wahyukan kepadamu (wahai Muhammad), yang engkau dan kaum engkau tidak mengetahuinya sebelum ini. Oleh itu, bersabarlah. Sesungguhnya kesudahan yang baik (yang membawa kejayaan di dunia dan kebahagiaan di akhirat) adalah bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 227, 12, 91, 186, FALSE, 0, NULL),
(11, 50, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', NULL, 'And to ʿAad [We sent] their brother Hūd. He said, "O my people, worship Allāh; you have no deity other than Him. You are not but inventors [of falsehood].', 'Dan kepada kaum Aad, Kami utuskan saudara mereka: Nabi hud ia berkata: “Wahai kaumku! Sembahlah kamu akan Allah! Sebenarnya tiada Tuhan bagi kamu selain daripadaNya. kamu hanyalah orang-orang yang mengada-adakan perkara-perkara yang dusta (terhadap Allah).', FALSE, NULL, NULL, 227, 12, 91, 187, FALSE, 0, NULL),
(11, 51, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ أَفَلَا تَعْقِلُونَ', 'يَا قَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِيَ إِلَّا عَلَى الَّذِي فَطَرَنِي أَفَلَا تَعْقِلُونَ', NULL, 'O my people, I do not ask you for it [i.e., my advice] any reward. My reward is only from the one who created me. Then will you not reason?', 'Wahai kaumku! Tiadalah aku meminta sebarang upah daripada kamu tentang (ajaran yang aku sampaikan) itu. Upahku hanyalah dari Allah yang menciptakan daku; maka mengapa kamu tidak mahu menggunakan akal (untuk mengetahui kebenaran)?', FALSE, NULL, NULL, 227, 12, 91, 187, FALSE, 0, NULL),
(11, 52, 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', 'وَيَا قَوْمِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُرْسِلِ السَّمَاءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا مُجْرِمِينَ', NULL, 'And O my people, ask forgiveness of your Lord and then repent to Him. He will send [rain from] the sky upon you in showers and increase you in strength [added] to your strength. And do not turn away, [being] criminals."', 'Dan wahai kaumku! Mintalah ampun kepada Tuhan kamu, kemudian kembalilah taat kepadaNya, supaya Ia menghantarkan kepada kamu hujan lebat serta menambahkan kamu kekuatan di samping kekuatan kamu yang sedia ada; dan janganlah kamu membelakangkan seruanku dengan terus melakukan dosa!', FALSE, NULL, NULL, 227, 12, 91, 187, FALSE, 0, NULL),
(11, 53, 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'قَالُوا يَا هُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِي آلِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', NULL, 'They said, "O Hūd, you have not brought us clear evidence, and we are not ones to leave our gods on your say-so. Nor are we believers in you.', 'Mereka berkata: “Wahai Hud! Engkau tidak membawa kepada kami sebarang keterangan yang membuktikan kebenaranmu, dan kami tidak akan meninggalkan penyembahan tuhan-tuhan kami dengan sebab kata-katamu itu! Dan kami tidak sekali-kali percaya kepadamu!', FALSE, NULL, NULL, 227, 12, 91, 187, FALSE, 0, NULL),
(11, 54, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'إِن نَّقُولُ إِلَّا اعْتَرَاكَ بَعْضُ آلِهَتِنَا بِسُوءٍ قَالَ إِنِّي أُشْهِدُ اللَّهَ وَاشْهَدُوا أَنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ', NULL, 'We only say that some of our gods have possessed you with evil [i.e., insanity]." He said, "Indeed, I call Allāh to witness, and witness [yourselves] that I am free from whatever you associate with Allāh', '“Kami hanya boleh berkata bahawa setengah dari tuhan-tuhan kami telah mengenakanmu sesuatu penyakit gila (disebabkan engkau selalu mencaci penyembahan kami itu)”. Nabi Hud menjawab: “Sesungguhnya aku menyeru Allah menjadi saksi tentang kebenaranku, dan kamu juga saksikanlah bahawa aku bersih dari dosa perbuatan syirik kamu -', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 55, 'مِن دُونِهِۦ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ', 'مِن دُونِهِ فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنظِرُونِ', NULL, 'Other than Him. So plot against me all together; then do not give me respite.', '“Menyembah yang lain dari Allah. Maka rancangkanlah tipu helah kamu semua terhadapku, kemudian jalankan terus, janganlah kamu beri tempoh kepadaku mempertahankan diri.', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 56, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُم مَّا مِن دَابَّةٍ إِلَّا هُوَ آخِذٌ بِنَاصِيَتِهَا إِنَّ رَبِّي عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'Indeed, I have relied upon Allāh, my Lord and your Lord. There is no creature but that He holds it by its forelock [i.e., controls it]. Indeed, my Lord is on a path [that is] straight.', '“Kerana sesungguhnya aku telah berserah diri kepada Allah, Tuhanku dan Tuhan kamu! Tiadalah sesuatupun dari makhluk-makhluk yang bergerak di muka bumi melainkan Allah jualah yang menguasainya. Sesungguhnya Tuhanku tetap di atas jalan yang lurus.', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 57, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'فَإِن تَوَلَّوْا فَقَدْ أَبْلَغْتُكُم مَّا أُرْسِلْتُ بِهِ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّي قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُ شَيْئًا إِنَّ رَبِّي عَلَىٰ كُلِّ شَيْءٍ حَفِيظٌ', NULL, 'But if you turn away, then I have already conveyed that with which I was sent to you. My Lord will give succession to a people other than you, and you will not harm Him at all. Indeed my Lord is, over all things, Guardian."', 'Dalam pada itu, jika kamu membelakangkan juga seruanku, maka tidaklah menjadi hal kepadaku kerana aku telah sampaikan kepada kamu apa yang telah diutus oleh Allah untuk menyampaikannya, dan Tuhanku akan menggantikan kamu dengan suatu kaum yang lain (setelah kamu dibinasakan); dan kamu pula tidak akan dapat membahayakanNya sedikitpun. Sesungguhnya Tuhanku Maha Pengawal dan Pemulihara tiap-tiap sesuatu.”', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 58, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍ', 'وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا هُودًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَاهُم مِّنْ عَذَابٍ غَلِيظٍ', NULL, 'And when Our command came, We saved Hūd and those who believed with him, by mercy from Us; and We saved them from a harsh punishment.', 'Dan apabila datang azab Kami, Kami selamatkan Nabi Hud beserta dengan umatnya yang beriman, dengan rahmat dari Kami; dan Kami selamatkan mereka dari azab yang keras.', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 59, 'وَتِلْكَ عَادٌ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', 'وَتِلْكَ عَادٌ جَحَدُوا بِآيَاتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', NULL, 'And that was ʿAad, who rejected the signs of their Lord and disobeyed His messengers and followed the order of every obstinate tyrant.', 'Dan itulah peristiwa kaum Aad mereka mengingkari ayat-ayat keterangan Tuhan mereka, serta mereka menderhaka kepada Rasul-rasulnya; dan mereka menurut perintah tiap-tiap ketua yang bermaharajalela, lagi degil dalam keingkarannya.', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 60, 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', 'وَأُتْبِعُوا فِي هَٰذِهِ الدُّنْيَا لَعْنَةً وَيَوْمَ الْقِيَامَةِ أَلَا إِنَّ عَادًا كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', NULL, 'And they were [therefore] followed in this world with a curse and [as well] on the Day of Resurrection. Unquestionably, ʿAad denied their Lord; then away with ʿAad, the people of Hūd.', 'Dan mereka ditimpa laknat (yang tidak putus-putus) dalam dunia ini dan pada hari kiamat. Ketahuilah Sesungguhnya kaum Aad itu telah kufur ingkar kepada Tuhan mereka ketahuilah! Sesungguhnya kebinasaanlah akhirnya bagi Aad: kaum Nabi Hud.', FALSE, NULL, NULL, 228, 12, 91, 187, FALSE, 0, NULL),
(11, 61, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ', 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ هُوَ أَنشَأَكُم مِّنَ الْأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ', NULL, 'And to Thamūd [We sent] their brother Ṣāliḥ. He said, "O my people, worship Allāh; you have no deity other than Him. He has produced you from the earth and settled you in it, so ask forgiveness of Him and then repent to Him. Indeed, my Lord is near and responsive."', 'Dan kepada kaum Thamud, kami utuskan saudara mereka: Nabi Soleh. Ia berkata: “Wahai kaumku! Sembahlah kamu akan Allah! Sebenarnya tiada Tuhan bagi kamu selain daripadaNya. Dia lah yang menjadikan kamu dari bahan-bahan bumi, serta menghendaki kamu memakmurkannya. Oleh itu mintalah ampun kepada Allah dari perbuatan syirik, kemudian kembalilah kepadaNya dengan taat dan tauhid. Sesungguhnya Tuhanku sentiasa dekat, lagi sentiasa memperkenankan permohonan hambaNya”.', FALSE, NULL, NULL, 228, 12, 92, 188, FALSE, 0, NULL),
(11, 62, 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَآ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ', 'قَالُوا يَا صَالِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَا أَتَنْهَانَا أَن نَّعْبُدَ مَا يَعْبُدُ آبَاؤُنَا وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ', NULL, 'They said, "O Ṣāliḥ, you were among us a man of promise before this. Do you forbid us to worship what our fathers worshipped? And indeed we are, about that to which you invite us, in disquieting doubt."', 'Mereka menjawab dengan berkata: “Wahai Soleh, sesungguhnya engkau sebelum ini adalah orang yang diharap dalam kalangan kami (untuk memimpin kami); patutkah engkau melarang kami daripada menyembah apa yang disembah oleh datuk nenek kami? Dan (ketahuilah) sesungguhnya kami berada dalam keadaan ragu-ragu yang merunsingkan tentang apa yang engkau serukan kami kepadanya”.', FALSE, NULL, NULL, 228, 12, 92, 188, FALSE, 0, NULL),
(11, 63, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ', 'قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي مِنْهُ رَحْمَةً فَمَن يَنصُرُنِي مِنَ اللَّهِ إِنْ عَصَيْتُهُ فَمَا تَزِيدُونَنِي غَيْرَ تَخْسِيرٍ', NULL, 'He said, "O my people, have you considered: if I should be upon clear evidence from my Lord and He has given me mercy from Himself, who would protect me from Allāh if I disobeyed Him? So you would not increase me except in loss.', 'Nabi Soleh berkata: “Wahai kaumku! Bagaimana fikiran kamu, jika aku berada dalam kebenaran yang berdasarkan bukti yang nyata (mukjzat) dari Tuhanku, dan Ia pula mengurniakan rahmat (pangkat Nabi) kepadaku sebagai pemberian daripadaNya, maka siapakah yang akan menolongku dari azab Allah kalau aku menderhaka kepadaNya? Oleh itu, kamu tidak menambah sesuatu kebaikan pun bagiku selain daripada perkara yang merugikan.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 64, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', 'وَيَا قَوْمِ هَٰذِهِ نَاقَةُ اللَّهِ لَكُمْ آيَةً فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', NULL, 'And O my people, this is the she-camel of Allāh - [she is] to you a sign. So let her feed upon Allāh''s earth and do not touch her with harm, or you will be taken by an impending punishment."', '“Dan wahai kaumku! Ini adalah unta betina dari Allah untuk kamu sebagai tanda (mukjizat) yang membuktikan kebenaranku. Oleh itu, biarkanlah dia mencari makan di bumi Allah dan janganlah kamu menyentuhnya dengan sesuatu yang menyakitinya, (kalau kamu menyakitinya) maka kamu akan ditimpa azab seksa yang dekat masa datangnya”.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا فِي دَارِكُمْ ثَلَاثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', NULL, 'But they hamstrung her, so he said, "Enjoy yourselves in your homes for three days. That is a promise not to be denied [i.e., unfailing]."', 'Mereka kemudiannya menyembelih unta itu, lalu berkatalah Nabi Soleh kepada mereka: Bersenang-senanglah kamu di tempat masing-masing selama tiga hari; tempoh yang demikian itu, ialah suatu janji yang tidak dapat didustakan”.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 66, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'فَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا صَالِحًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْيِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ', NULL, 'So when Our command came, We saved Ṣāliḥ and those who believed with him, by mercy from Us, and [saved them] from the disgrace of that day. Indeed, it is your Lord who is the Powerful, the Exalted in Might.', 'Maka ketika datang azab kami, kami selamatkan Soleh beserta umatnya yang beriman, dengan rahmat dari Kami, dan Kami selamatkan mereka dari azab serta kehinaan hari itu. Sesungguhnya Tuhanmu, Dia lah Yang Maha Kuat, lagi Maha Kuasa.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 67, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ', NULL, 'And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone', 'Dan orang-orang yang zalim itu, dibinasakan oleh satu letusan suara yang menggempakan bumi, lalu menjadilah mereka mayat-mayat yang tersungkur di tempat tinggal masing-masing.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 68, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ', 'كَأَن لَّمْ يَغْنَوْا فِيهَا أَلَا إِنَّ ثَمُودَ كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ', NULL, 'As if they had never prospered therein. Unquestionably, Thamūd denied their Lord; then, away with Thamūd.', '(Mereka punah-ranah) seolah-olah mereka tidak pernah tinggal di situ. Ketahuilah! Sesungguhnya kaum Thamud itu kufurkan Tuhan mereka. Ketahuilah! Sesungguhnya kebinasaanlah akhirnya bagi kaum Thamud.', FALSE, NULL, NULL, 229, 12, 92, 188, FALSE, 0, NULL),
(11, 69, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ', 'وَلَقَدْ جَاءَتْ رُسُلُنَا إِبْرَاهِيمَ بِالْبُشْرَىٰ قَالُوا سَلَامًا قَالَ سَلَامٌ فَمَا لَبِثَ أَن جَاءَ بِعِجْلٍ حَنِيذٍ', NULL, 'And certainly did Our messengers [i.e., angels] come to Abraham with good tidings; they said, "Peace." He said, "Peace," and did not delay in bringing [them] a roasted calf.', 'Dan sesungguhnya telah datang malaikat utusan-utusan kami kepada Nabi Ibrahim, dengan membawa berita yang mengembirakan. Lalu mereka memberi salam dengan berkata: “Salam sejahtera kepadamu (wahai Ibrahim)”. Nabi Ibrahim menjawab: “Salam sejahtera kepada kamu”. Maka tidak berapa lama selepas itu, ia membawa jamuan untuk mereka: seekor anak lembu yang dipanggang.', FALSE, NULL, NULL, 229, 12, 92, 189, FALSE, 0, NULL),
(11, 70, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ', 'فَلَمَّا رَأَىٰ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا لَا تَخَفْ إِنَّا أُرْسِلْنَا إِلَىٰ قَوْمِ لُوطٍ', NULL, 'But when he saw their hands not reaching for it, he distrusted them and felt from them apprehension. They said, "Fear not. We have been sent to the people of Lot."', 'Maka apabila ia melihat tangan mereka tidak menyentuh hidangan itu, ia merasa pelik akan hal mereka serta merasa takut dari keadaan mereka. (Melihat kecemasannya) mereka berkata: “Janganlah engkau takut wahai Ibrahim, sebenarnya kami ini diutus kepada kaum Lut (untuk membinasakan mereka)”.', FALSE, NULL, NULL, 229, 12, 92, 189, FALSE, 0, NULL),
(11, 71, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', 'وَامْرَأَتُهُ قَائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِن وَرَاءِ إِسْحَاقَ يَعْقُوبَ', NULL, 'And his wife was standing, and she smiled. Then We gave her good tidings of Isaac and after Isaac, Jacob.', 'Dan isterinya pada ketika itu berdiri (mendengar), lalu ia ketawa (kerana hilang perasaan takutnya). Maka Kami pun memberikan berita yang mengembirakan kepadanya (melalui malaikat itu), bahawa ia akan mendapat seorang anak: Ishak, dan sesudah Ishak, (ia pula akan mendapat seorang cucu): Yaakub.', FALSE, NULL, NULL, 229, 12, 92, 189, FALSE, 0, NULL),
(11, 72, 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَٰذَا بَعْلِى شَيْخًا إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌ', 'قَالَتْ يَا وَيْلَتَىٰ أَأَلِدُ وَأَنَا عَجُوزٌ وَهَٰذَا بَعْلِي شَيْخًا إِنَّ هَٰذَا لَشَيْءٌ عَجِيبٌ', NULL, 'She said, "Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is an amazing thing!"', 'Isterinya berkata: “Sungguh ajaib keadaanku! Adakah aku akan melahirkan anak padahal aku sudah tua dan suamiku ini juga sudah tua? Sesungguhnya kejadian ini suatu perkara yang menghairankan”.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 73, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ', 'قَالُوا أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ رَحْمَتُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَّجِيدٌ', NULL, 'They said, "Are you amazed at the decree of Allāh? May the mercy of Allāh and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honorable."', 'Malaikat-malaikat itu berkata: “Patutkah engkau merasa hairan tentang perkara yang telah ditetapkan oleh Allah? Memanglah rahmat Allah dan berkatNya melimpah-limpah kepada kamu, wahai ahli rumah ini. Sesungguhnya Allah Maha terpuji, lagi Maha Melimpah kebaikan dan kemurahanNya”.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 74, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', 'فَلَمَّا ذَهَبَ عَنْ إِبْرَاهِيمَ الرَّوْعُ وَجَاءَتْهُ الْبُشْرَىٰ يُجَادِلُنَا فِي قَوْمِ لُوطٍ', NULL, 'And when the fright had left Abraham and the good tidings had reached him, he began to argue [i.e., plead] with Us concerning the people of Lot.', 'Maka apabila hilang perasaan takut dari hati Nabi Ibrahim, dan sampai kepadanya berita yang mengembirakan itu, (mulailah) ia membantah (utusan-utusan) kami tentang (azab yang akan menimpa) kaum Nabi Lut.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 75, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ', 'إِنَّ إِبْرَاهِيمَ لَحَلِيمٌ أَوَّاهٌ مُّنِيبٌ', NULL, 'Indeed, Abraham was forbearing, grieving and [frequently] returning [to Allāh].', 'Sesungguhnya Nabi Ibrahim, penyabar, lembut hati (bertimbang rasa) lagi suka kembali kepada Allah dengan mengerjakan amal bakti.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 76, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', 'يَا إِبْرَاهِيمُ أَعْرِضْ عَنْ هَٰذَا إِنَّهُ قَدْ جَاءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ آتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', NULL, '[The angels said], "O Abraham, give up this [plea]. Indeed, the command of your Lord has come, and indeed, there will reach them a punishment that cannot be repelled."', '(Malaikat-malaikat itu berkata): “Wahai Ibrahim! Janganlah dihiraukan hal ini. Sesungguhnya telah datang perintah Tuhanmu (menghukum mereka), dan sesungguhnya mereka akan didatangi azab yang tidak akan dapat ditolak (oleh bantahan atau doa permohonan)”.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 77, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ', 'وَلَمَّا جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ', NULL, 'And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort and said, "This is a trying day."', 'Dan apabila datang utusan-utusan Kami kepada Nabi Lut ia merasa dukacita dengan kedatangan mereka, dan merasa tidak terdaya untuk mengawal mereka (dari gangguan kaumnya), sambil berkata: “Ini adalah hari yang amat mencemaskan”.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 78, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', 'وَجَاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا يَعْمَلُونَ السَّيِّئَاتِ قَالَ يَا قَوْمِ هَٰؤُلَاءِ بَنَاتِي هُنَّ أَطْهَرُ لَكُمْ فَاتَّقُوا اللَّهَ وَلَا تُخْزُونِ فِي ضَيْفِي أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', NULL, 'And his people came hastening to him, and before [this] they had been doing evil deeds. He said, "O my people, these are my daughters; they are purer for you. So fear Allāh and do not disgrace me concerning my guests. Is there not among you a man of reason?"', 'Dan kaumnya pun datang meluru kepadanya (dengan tujuan hendak mengganggu tetamunya), sedang mereka sebelum itu sudah biasa melakukan kejahatan. Nabi Lut berkata: “Wahai kaumku! Di sini ada anak-anak perempuanku mereka lebih suci bagi kamu (maka berkahwinlah dengan mereka). Oleh itu takutlah kamu kepada Allah, dan janganlah kamu memberi malu kepadaku mengenai tetamu-tetamuku. Tidakkah ada di antara kamu seorang lelaki yang bijak berakal (yang dapat memberi nasihat)?”', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 79, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', 'قَالُوا لَقَدْ عَلِمْتَ مَا لَنَا فِي بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', NULL, 'They said, "You have already known that we have not concerning your daughters [i.e., women] any claim [i.e., desire], and indeed, you know what we want."', 'Mereka menjawab: “Sesungguhnya engkau telahpun mengetahui bahawa kami tidak ada sebarang hajat kepada anak-anak perempuanmu, dan sebenarnya engkau sedia mengetahui akan apa yang kami kehendaki.”', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 80, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ', 'قَالَ لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَىٰ رُكْنٍ شَدِيدٍ', NULL, 'He said, "If only I had against you some power or could take refuge in a strong support."', 'Nabi Lut berkata: “Kalaulah aku ada kekuatan untuk menentang kamu, atau aku dapat bertumpu ke sesuatu tempat bertahan yang kuat (dari penyokong-penyokong, tentulah aku akan membinasakan kamu)”.', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 81, 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ', 'قَالُوا يَا لُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوا إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ اللَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا امْرَأَتَكَ إِنَّهُ مُصِيبُهَا مَا أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ الصُّبْحُ أَلَيْسَ الصُّبْحُ بِقَرِيبٍ', NULL, 'They [the angels] said, "O Lot, indeed we are messengers of your Lord; [therefore], they will never reach you. So set out with your family during a portion of the night and let not any among you look back - except your wife; indeed, she will be struck by that which strikes them. Indeed, their appointment is [for] the morning. Is not the morning near?"', '(Mendengarkan yang demikian tetamunya berkata: “Wahai Lut! Sesungguhnya kami (adalah malaikat) utusan Tuhanmu. Kaum engkau yang jahat itu tidak sekali-kali akan dapat melakukan kepadamu (sebarang bencana). Oleh itu, pergilah berundur dari sini bersama-sama dengan keluargamu pada tengah malam, dan janganlah seorangpun di antara kamu menoleh ke belakang. Kecuali isterimu, sesungguhnya ia akan ditimpa azab yang akan menimpa mereka (kerana ia memihak kepada mereka). Sesungguhnya masa yang dijanjikan untuk menimpakan azab kepada mereka ialah waktu subuh; bukankah waktu subuh itu sudah dekat?”', FALSE, NULL, NULL, 230, 12, 92, 189, FALSE, 0, NULL),
(11, 82, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', 'فَلَمَّا جَاءَ أَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', NULL, 'So when Our command came, We made the highest part [of the city] its lowest and rained upon them stones of layered hard clay, [which were]', 'Maka apabila datang (masa perlaksanaan) perintah Kami, Kami jadikan negeri kaum Lut itu diterbalikkan (tertimbus segala yang ada di muka buminya) dan kami menghujaninya dengan batu-batu dari tanah yang dibakar, menimpanya bertalu-talu.', FALSE, NULL, NULL, 231, 12, 92, 189, FALSE, 0, NULL),
(11, 83, 'مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍ', 'مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ', NULL, 'Marked from your Lord. And it [i.e., Allāh''s punishment] is not from the wrongdoers [very] far.', 'Batu-batu itu ditandakan di sisi Tuhanmu (untuk membinasakan mereka), dan Ia pula tidaklah jauh dari orang-orang yang zalim itu.', FALSE, NULL, NULL, 231, 12, 92, 189, FALSE, 0, NULL),
(11, 84, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ وَلَا تَنقُصُوا الْمِكْيَالَ وَالْمِيزَانَ إِنِّي أَرَاكُم بِخَيْرٍ وَإِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', NULL, 'And to Madyan [We sent] their brother Shuʿayb. He said, "O my people, worship Allāh; you have no deity other than Him. And do not decrease from the measure and the scale. Indeed, I see you in prosperity, but indeed, I fear for you the punishment of an all-encompassing Day.', 'Dan kepada penduduk “Madyan” Kami utuskan saudara mereka: Nabi Syuaib. Ia berkata: “Wahai kaumku! Sembahlah kamu akan Allah! (Sebenarnya) tiada Tuhan bagi kamu selain daripadaNya. Dan janganlah kamu mengurangi sukatan dan timbangan. Sesungguhnya aku melihat kamu berada dalam kemewahan; dan sesungguhnya aku bimbang, kamu akan ditimpa azab hari yang meliputi (orang-orang yang bersalah).', FALSE, NULL, NULL, 231, 12, 93, 190, FALSE, 0, NULL),
(11, 85, 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وَيَا قَوْمِ أَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ', NULL, 'And O my people, give full measure and weight in justice and do not deprive the people of their due and do not commit abuse on the earth, spreading corruption.', 'Dan wahai kaumku! Sempurnakanlah sukatan dan timbangan dengan adil dan janganlah kamu kurangkan manusia akan benda-benda yang menjadi haknya, dan janganlah kamu merebakkan bencana kerosakan di muka bumi.', FALSE, NULL, NULL, 231, 12, 93, 190, FALSE, 0, NULL),
(11, 86, 'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', 'بَقِيَّتُ اللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَا أَنَا عَلَيْكُم بِحَفِيظٍ', NULL, 'What remains [lawful] from Allāh is best for you, if you would be believers. But I am not a guardian over you."', 'Limpah kurnia Allah kepada kamu lebih baik bagi kamu (daripada yang kamu ambil secara haram itu), jika betul kamu orang-orang yang beriman. Dan aku bukanlah orang yang menjaga dan mengawas perbuatan kamu”.', FALSE, NULL, NULL, 231, 12, 93, 190, FALSE, 0, NULL),
(11, 87, 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', 'قَالُوا يَا شُعَيْبُ أَصَلَاتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ آبَاؤُنَا أَوْ أَن نَّفْعَلَ فِي أَمْوَالِنَا مَا نَشَاءُ إِنَّكَ لَأَنتَ الْحَلِيمُ الرَّشِيدُ', NULL, 'They said, "O Shuʿayb, does your prayer [i.e., religion] command you that we should leave what our fathers worship or not do with our wealth what we please? Indeed, you are the forbearing, the discerning!"', 'Mereka berkata: “Wahai Syuaib! Adakah sembahyangmu (yang banyak itu) menyuruhmu perintahkan kami supaya meninggalkan apa yang disembah oleh datuk nenek kami, atau supaya kami lakukannya apa yang kami suka melakukannya dalam menguruskan harta kami? Sesungguhnya engkau (wahai Syuaib) adalah orang yang penyabar, lagi bijak berakal (maka bagaimana pula engkau menyuruh kami melakukan perkara yang bertentangan dengan kebiasaan kami)?”', FALSE, NULL, NULL, 231, 12, 93, 190, FALSE, 0, NULL),
(11, 88, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 'قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّي وَرَزَقَنِي مِنْهُ رِزْقًا حَسَنًا وَمَا أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَا أَنْهَاكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا الْإِصْلَاحَ مَا اسْتَطَعْتُ وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', NULL, 'He said, "O my people, have you considered: if I am upon clear evidence from my Lord and He has provided me with a good provision from Him...? And I do not intend to differ from you in that which I have forbidden you; I only intend reform as much as I am able. And my success is not but through Allāh. Upon Him I have relied, and to Him I return.', 'Nabi Syuaib berkata: “Wahai kaumku! Bagaimana fikiran kamu, jika aku berdasarkan bukti yang nyata dari Tuhanku, dan Ia pula mengurniakan daku pangkat Nabi sebagai pemberian daripadaNya, (patutkah aku berdiam diri dari melarang kamu) sedang aku tidak bertujuan hendak melakukan sesuatu yang aku melarang kamu daripada melakukannya? Aku hanya bertujuan hendak memperbaiki sedaya upayaku; dan tiadalah aku akan beroleh taufik untuk menjayakannya melainkan dengan pertolongan Allah. Kepada Allah jualah aku berserah diri dan kepadaNyalah aku kembali.', FALSE, NULL, NULL, 231, 12, 93, 190, FALSE, 0, NULL),
(11, 89, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', 'وَيَا قَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِي أَن يُصِيبَكُم مِّثْلُ مَا أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَالِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', NULL, 'And O my people, let not [your] dissension from me cause you to be struck by that similar to what struck the people of Noah or the people of Hūd or the people of Ṣāliḥ. And the people of Lot are not from you far away.', 'Dan wahai kaumku! Janganlah permusuhan kamu terhadapku menyebabkan kamu ditimpa bala bencana sebagaimana yang telah menimpa kaum Nabi Nuh, atau kaum Nabi Hud, atau kaum Nabi Soleh. Dan kaum Nabi Lut pun tidaklah jauh dari kamu (kamu sedia mengetahui apa yang telah menimpa mereka).', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 90, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ', 'وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ', NULL, 'And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate."', 'Dan mintalah ampun kepada Tuhan kamu, kemudian kembalilah taat kepadaNya. Sesungguhnya Tuhanku Maha Mengasihani, lagi Maha Pengasih”.', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 91, 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ', 'قَالُوا يَا شُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَاكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَاكَ وَمَا أَنتَ عَلَيْنَا بِعَزِيزٍ', NULL, 'They said, "O Shuʿayb, we do not understand much of what you say, and indeed, we consider you among us as weak. And if not for your family, we would have stoned you [to death]; and you are not to us one respected."', 'Mereka berkata: “Wahai Syuaib,! kami tidak mengerti kebanyakan dari apa yang engkau katakan itu, dan sesungguhnya kami melihat engkau orang yang lemah dalam kalangan kami; dan kalau tidaklah kerana kaum keluargamu, tentulah kami telah melemparmu (dengan batu hingga mati). Dan engkau pula bukanlah orang yang dipandang mulia dalam kalangan kami!”', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 92, 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ', 'قَالَ يَا قَوْمِ أَرَهْطِي أَعَزُّ عَلَيْكُم مِّنَ اللَّهِ وَاتَّخَذْتُمُوهُ وَرَاءَكُمْ ظِهْرِيًّا إِنَّ رَبِّي بِمَا تَعْمَلُونَ مُحِيطٌ', NULL, 'He said, "O my people, is my family more respected for power by you than Allāh? But you put Him behind your backs [in neglect]. Indeed, my Lord is encompassing of what you do.', 'Nabi Syuaib berkata: “Wahai kaumku! (Mengapa kamu bersikap demikian)? Patutkah kaum keluargaku kamu pandang lebih mulia dari pada Allah serta kamu pula jadikan perintahNya sebagai sesuatu yang dibuang dan dilupakan di belakang kamu? Sesungguhnya Tuhanku Amat Meliputi pengetahuanNya akan apa yang kamu lakukan.', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 93, 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ', 'وَيَا قَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّي عَامِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَاذِبٌ وَارْتَقِبُوا إِنِّي مَعَكُمْ رَقِيبٌ', NULL, 'And O my people, work according to your position; indeed, I am working. You are going to know to whom will come a punishment that will disgrace him and who is a liar. So watch; indeed, I am with you a watcher, [awaiting the outcome]."', '“Dan wahai kaumku, buatlah sedaya upaya kamu (untuk menentang ugama Allah yang aku sampaikan itu), sesungguhnya aku juga tetap berusaha dengan bersungguh-sungguh (untuk mengembangkannya). Kamu akan ketahui siapakah yang akan didatangi azab yang menghinakannya, dan siapa pula yang berdusta. Dan tunggulah, sesungguhnya aku juga turut menunggu bersama-sama kamu”.', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 94, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ', NULL, 'And when Our command came, We saved Shuʿayb and those who believed with him, by mercy from Us. And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone', 'Dan ketika datang (masa perlaksanaan) perintah Kami, Kami selamatkan Nabi Syuaib beserta dengan umatnya yang beriman, dengan rahmat dari Kami; dan orang-orang yang zalim itu dibinasakan oleh letusan suara yang menggempakan bumi, lalu menjadilah mereka mayat-mayat yang tersungkur di tempat masing-masing.', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 95, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', 'كَأَن لَّمْ يَغْنَوْا فِيهَا أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', NULL, 'As if they had never prospered therein. Then, away with Madyan as Thamūd was taken away.', '(Mereka punah-ranah) seolah-olah mereka tidak pernah tinggal di situ. Ketahuilah! kebinasaanlah akhirnya bagi penduduk Madyan, sebagaimana binasanya kaum Thamud.', FALSE, NULL, NULL, 232, 12, 93, 190, FALSE, 0, NULL),
(11, 96, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِآيَاتِنَا وَسُلْطَانٍ مُّبِينٍ', NULL, 'And We did certainly send Moses with Our signs and a clear authority', 'Dan sesungguhnya kami telah mengutuskan Nabi Musa dengan membawa ayat-ayat keterangan Kami, dan bukti (mukjizat) yang nyata:', FALSE, NULL, NULL, 232, 12, 93, 191, FALSE, 0, NULL),
(11, 97, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', 'إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ فَاتَّبَعُوا أَمْرَ فِرْعَوْنَ وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', NULL, 'To Pharaoh and his establishment, but they followed the command of Pharaoh, and the command of Pharaoh was not [at all] discerning.', 'Kepada Firaun dan kaumnya; lalu kaum Firaun menurut perintah Firaun, sedang perintahnya itu bukanlah perintah yang betul.', FALSE, NULL, NULL, 232, 12, 93, 191, FALSE, 0, NULL),
(11, 98, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 'يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَةِ فَأَوْرَدَهُمُ النَّارَ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ', NULL, 'He will precede his people on the Day of Resurrection and lead them into the Fire; and wretched is the place to which they are led.', 'Firaun akan mengetuai kaumnya pada hari kiamat kemudian tetaplah ia akan membawa mereka masuk ke neraka. Dan seburuk-buruk tempat yang dimasuki ialah neraka.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 99, 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', 'وَأُتْبِعُوا فِي هَٰذِهِ لَعْنَةً وَيَوْمَ الْقِيَامَةِ بِئْسَ الرِّفْدُ الْمَرْفُودُ', NULL, 'And they were followed in this [world] with a curse and on the Day of Resurrection. And wretched is the gift which is given.', 'Dan mereka diiringi oleh laknat yang tidak putus-putus di dunia ini, dan pada hari kiamat. (Sebenarnya) laknat itu adalah seburuk-buruk pemberian yang diberikan.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 100, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمٌ وَحَصِيدٌ', 'ذَٰلِكَ مِنْ أَنبَاءِ الْقُرَىٰ نَقُصُّهُ عَلَيْكَ مِنْهَا قَائِمٌ وَحَصِيدٌ', NULL, 'That is from the news of the cities, which We relate to you; of them, some are [still] standing and some are [as] a harvest [mowed down].', 'Yang demikian, ialah sebahagian dari khabar berita penduduk negeri-negeri (yang telah dibinasakan), kami ceritakan perihalnya kepadamu (wahai Muhammad). Di antaranya ada yang masih wujud (sisanya yang dapat disaksikan), dan ada pula yang telah hancur lebur (dan hilang lenyap).', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 101, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', 'وَمَا ظَلَمْنَاهُمْ وَلَٰكِن ظَلَمُوا أَنفُسَهُمْ فَمَا أَغْنَتْ عَنْهُمْ آلِهَتُهُمُ الَّتِي يَدْعُونَ مِن دُونِ اللَّهِ مِن شَيْءٍ لَّمَّا جَاءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', NULL, 'And We did not wrong them, but they wronged themselves. And they were not availed at all by their gods which they invoked other than Allāh when there came the command of your Lord. And they did not increase them in other than ruin.', 'Dan tiadalah Kami menganiaya mereka, tetapi merekalah yang menganiaya diri sendiri. Maka berhala-berhala yang mereka sembah selain dari Allah itu tidak dapat menolong mereka sedikitpun pada masa datangnya azab Tuhanmu; dan penyembahan yang mereka lakukan itu hanya menambahkan kerugian sahaja kepada mereka.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 102, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ', 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَىٰ وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ', NULL, 'And thus is the seizure of your Lord when He seizes the cities while they are committing wrong. Indeed, His seizure is painful and severe.', 'Dan demikianlah azab Tuhanmu, apabila ia menimpa (penduduk) negeri-negeri yang berlaku zalim. Sesungguhnya azabNya itu tidak terperi sakitnya, lagi amat keras serangannya.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 103, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً لِّمَنْ خَافَ عَذَابَ الْآخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ النَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', NULL, 'Indeed in that is a sign for those who fear the punishment of the Hereafter. That is a Day for which the people will be collected, and that is a Day [which will be] witnessed.', 'Sesungguhnya pada kejadian yang demikian, ada tanda (yang mendatangkan iktibar) bagi orang yang takut kepada azab akhirat, iaitu hari yang dihimpunkan manusia padanya. Dan hari yang demikian ialah hari yang dihadiri oleh sekalian makhluk.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 104, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ', 'وَمَا نُؤَخِّرُهُ إِلَّا لِأَجَلٍ مَّعْدُودٍ', NULL, 'And We do not delay it except for a limited term.', 'Dan tiadalah Kami lambatkan hari kiamat itu melainkan untuk suatu tempoh yang tertentu.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 105, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ', 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ', NULL, 'The Day it comes no soul will speak except by His permission. And among them will be the wretched and the prosperous.', '(Pada) masa datangnya (hari kiamat itu), tiadalah seorangpun dapat berkata-kata (untuk membela dirinya atau memohon pertolongan) melainkan dengan izin Allah. Maka di antara mereka ada yang celaka, dan ada pula yang berbahagia.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 106, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', 'فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', NULL, 'As for those who were [destined to be] wretched, they will be in the Fire. For them therein is [violent] exhaling and inhaling.', 'Adapun orang-orang yang celaka (disebabkan keingkaran dan maksiatnya), maka di dalam nerakalah tempatnya. Bagi mereka di situ, hanyalah suara memekik-mekik dan mendayu-dayu (seperti suara keldai).', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 107, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', 'خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', NULL, '[They will be] abiding therein as long as the heavens and the earth endure, except what your Lord should will. Indeed, your Lord is an effecter of what He intends.', 'Mereka kekal di dalamnya selagi ada langit dan bumi kecuali apa yang dikehendaki oleh Tuhanmu. Sesungguhnya Tuhanmu, Maha Kuasa melakukan apa yang dikehendakiNya.', FALSE, NULL, NULL, 233, 12, 93, 191, FALSE, 0, NULL),
(11, 108, 'وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ عَطَآءً غَيْرَ مَجْذُوذٍ', 'وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ عَطَاءً غَيْرَ مَجْذُوذٍ', NULL, 'And as for those who were [destined to be] prosperous, they will be in Paradise, abiding therein as long as the heavens and the earth endure, except what your Lord should will - a bestowal uninterrupted.', 'Adapun orang-orang yang berbahagia (disebabkan imannya dan taatnya), maka di dalam Syurgalah tempatnya. Mereka kekal di dalamnya selagi ada langit dan bumi kecuali apa yang dikehendaki oleh Tuhanmu sebagai pemberian nikmat yang tidak putus-putus.', FALSE, NULL, NULL, 233, 12, 94, 191, FALSE, 0, NULL),
(11, 109, 'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', 'فَلَا تَكُ فِي مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰؤُلَاءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ آبَاؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', NULL, 'So do not be in doubt, [O Muḥammad], as to what these [polytheists] are worshipping. They worship not except as their fathers worshipped before. And indeed, We will give them their share undiminished.', 'Maka janganlah engkau (wahai Muhammad) menaruh perasaan ragu-ragu tentang sia-sianya apa yang disembah oleh mereka yang musyrik itu. Mereka tidak menyembah melainkan sama seperti yang disembah oleh datuk nenek mereka yang musyrik dahulu. Dan sesungguhnya Kami akan menyempurnakan bagi mereka bahagian mereka (dari azab yang telah ditentukan) dengan tidak dikurangi.', FALSE, NULL, NULL, 234, 12, 94, 191, FALSE, 0, NULL),
(11, 110, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ وَإِنَّهُمْ لَفِي شَكٍّ مِّنْهُ مُرِيبٍ', NULL, 'And We had certainly given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been judged between them. And indeed they are, concerning it [i.e., the Qur’ān], in disquieting doubt.', '(Janganlah engkau merasa bimbang wahai Muhammad tentang keingkaran kaummu) kerana sesungguhnya Kami telah memberikan kepada Nabi Musa Kitab Taurat, lalu berlaku pertentangan mengenainya. Dan kalau tidaklah kerana telah terdahulu kalimah ketetapan dari Tuhanmu (untuk menangguhkan hukuman hingga ke suatu masa yang tertentu), tentulah dijatuhkan hukuman azab dengan serta-merta kepada mereka. Dan sesungguhnya mereka masih menaruh perasaan ragu-ragu tentang (kebenaran Al-Quran) itu.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 111, 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ', 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَالَهُمْ إِنَّهُ بِمَا يَعْمَلُونَ خَبِيرٌ', NULL, 'And indeed, each [of the believers and disbelievers] - your Lord will fully compensate them for their deeds. Indeed, He is Aware of what they do.', 'Dan sesungguhnya tiap-tiap seorang akan disempurnakan oleh Tuhanmu balasan amal mereka; sesungguhnya Allah Amat Mendalam pengetahuanNya tentang apa yang mereka kerjakan.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 112, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 'فَاسْتَقِمْ كَمَا أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'So remain on a right course as you have been commanded, [you] and those who have turned back with you [to Allāh], and do not transgress. Indeed, He is Seeing of what you do.', 'Oleh itu, hendaklah engkau (wahai Muhammad) sentiasa tetap teguh di atas jalan yang betul sebagaimana yang diperintahkan kepadamu, dan hendaklah orang-orang yang rujuk kembali kepada kebenaran mengikutmu berbuat demikian; dan janganlah kamu melampaui batas hukum-hukum Allah; sesungguhnya Allah Maha Melihat akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 113, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', 'وَلَا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ وَمَا لَكُم مِّن دُونِ اللَّهِ مِنْ أَوْلِيَاءَ ثُمَّ لَا تُنصَرُونَ', NULL, 'And do not incline toward those who do wrong, lest you be touched by the Fire, and you would not have other than Allāh any protectors; then you would not be helped.', 'Dan janganlah kamu cenderung kepada orang-orang yang berlaku zalim maka (kalau kamu berlaku demikian), api neraka akan membakar kamu, sedang kamu tidak ada sebarang penolong pun yang lain dari Allah. Kemudian (dengan sebab kecenderungan kamu itu) kamu tidak akan mendapat pertolongan.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 114, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', 'وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِّنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّاكِرِينَ', NULL, 'And establish prayer at the two ends of the day and at the approach of the night. Indeed, good deeds do away with misdeeds. That is a reminder for those who remember.', 'Dan dirikanlah sembahyang (wahai Muhammad, engkau dan umatmu), pada dua bahagian siang (pagi dan petang), dan pada waktu-waktu yang berhampiran dengannya dari waktu malam. Sesungguhnya amal-amal kebajikan (terutama sembahyang) itu menghapuskan kejahatan. Perintah-perintah Allah yang demikian adalah menjadi peringatan bagi orang-orang yang mahu beringat.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 115, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'وَاصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ', NULL, 'And be patient, for indeed, Allāh does not allow to be lost the reward of those who do good.', 'Dan sabarlah (wahai Muhammad, engkau dan umatmu, dalam mengerjakan suruhan Allah), kerana sesungguhnya Allah tidak akan menghilangkan pahala orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 116, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 'فَلَوْلَا كَانَ مِنَ الْقُرُونِ مِن قَبْلِكُمْ أُولُو بَقِيَّةٍ يَنْهَوْنَ عَنِ الْفَسَادِ فِي الْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَاتَّبَعَ الَّذِينَ ظَلَمُوا مَا أُتْرِفُوا فِيهِ وَكَانُوا مُجْرِمِينَ', NULL, 'So why were there not among the generations before you those of enduring discrimination forbidding corruption on earth - except a few of those We saved from among them? But those who wronged pursued what luxury they were given therein, and they were criminals.', 'Maka sepatutnya ada di antara umat yang telah dibinasakan dahulu daripada kamu itu, orang-orang yang berkelebihan akal fikiran yang melarang kaumnya dari perbuatan-perbuatan jahat di muka bumi tetapi sayang! Tidak ada yang melarang melainkan sedikit sahaja, iaitu orang-orang yang Kami telah selamatkan di antara mereka. Dan orang-orang yang tidak melarang itu telah menitik beratkan segala kemewahan yang diberikan kepada mereka dan menjadilah mereka orang-orang yang berdosa.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 117, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', NULL, 'And your Lord would not have destroyed the cities unjustly while their people were reformers.', 'Dan Tuhanmu tidak sekali-kali hendak membinasakan mana-mana negeri dengan sebab kezaliman penduduknya, selagi mereka sentiasa memperbaiki keadaan sesama sendiri.', FALSE, NULL, NULL, 234, 12, 94, 192, FALSE, 0, NULL),
(11, 118, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ', 'وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ', NULL, 'And if your Lord had willed, He could have made mankind one community; but they will not cease to differ,', 'Dan kalaulah Tuhanmu (wahai Muhammad) menghendaki, tentulah Ia menjadikan umat manusia semuanya menurut ugama yang satu. (Tetapi Ia tidak berbuat demikian) dan kerana itulah mereka terus-menerus berselisihan.', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(11, 119, 'إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ', NULL, 'Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, "I will surely fill Hell with jinn and men all together."', 'Tetapi orang-orang yang telah diberi rahmat oleh Tuhanmu, (mereka bersatu di dalam ugama Allah); dan untuk (perselisihan dan rahmat) itulah Allah menjadikan manusia. Dan dengan yang demikian sempurnalah janji Tuhanmu: “Sesungguhnya Aku akan memenuhi neraka jahannam dengan sekalian jin dan manusia (yang berdosa)”.', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(11, 120, 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنبَاءِ الرُّسُلِ مَا نُثَبِّتُ بِهِ فُؤَادَكَ وَجَاءَكَ فِي هَٰذِهِ الْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', NULL, 'And each [story] We relate to you from the news of the messengers is that by which We make firm your heart. And there has come to you, in this, the truth and an instruction and a reminder for the believers.', 'Dan tiap-tiap berita dari berita Rasul-rasul itu, kami ceritakan kepadamu (wahai Muhammad), untuk menguatkan hatimu dengannya. Dan telah datang kepadamu dalam berita ini kebenaran dan pengajaran serta peringatan bagi orang-orang yang beriman.', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(11, 121, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنَّا عَامِلُونَ', NULL, 'And say to those who do not believe, "Work according to your position; indeed, we are working.', 'Dan katakanlah kepada orang-orang yang tidak beriman: “Buatlah apa yang kamu sanggup melakukannya (dari perbuatan ingkar itu). Sesungguhnya kami juga tetap mengerjakan (nasihat pengajaran yang Tuhan berikan kepada kami).', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(11, 122, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'وَانتَظِرُوا إِنَّا مُنتَظِرُونَ', NULL, 'And wait; indeed, we are waiting."', 'Dan tunggulah (akibat yang buruk yang akan menimpa kamu)! Sesungguhnya kami juga menunggu (akan kemenangan dan kejayaan yang dijanjikan oleh Allah kepada kami)”.', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(11, 123, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'وَلِلَّهِ غَيْبُ السَّمَاوَاتِ وَالْأَرْضِ وَإِلَيْهِ يُرْجَعُ الْأَمْرُ كُلُّهُ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'And to Allāh belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do.', 'Dan Allah jualah yang mengetahui rahsia langit dan bumi dan kepadaNyalah dikembalikan segala urusan. Oleh itu, sembahlah akan Dia serta berserahlah kepadaNya. Dan (ingatlah), Tuhanmu tidak sekali-kali lalai akan apa yang kamu lakukan.', FALSE, NULL, NULL, 235, 12, 94, 192, FALSE, 0, NULL),
(12, 1, 'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', 'الر تلك ايات الكتاب المبين', NULL, 'Alif, Lām, Rā. These are the verses of the clear Book.', 'Alif, Laam, Raa''. Ini ialah ayat-ayat Kitab Al-Quran yang menyatakan kebenaran.', FALSE, NULL, NULL, 235, 12, 94, 193, FALSE, 5, NULL),
(12, 2, 'إِنَّآ أَنزَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'انا انزلناه قرانا عربيا لعلكم تعقلون', NULL, 'Indeed, We have sent it down as an Arabic Qur’ān that you might understand.', 'Sesungguhnya Kami menurunkan kitab itu sebagai Quran yang dibaca dengan bahasa Arab, supaya kamu (menggunakan akal untuk) memahaminya.', FALSE, NULL, NULL, 235, 12, 94, 193, FALSE, 6, NULL),
(12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَـٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَـٰفِلِينَ', 'نحن نقص عليك احسن القصص بما اوحينا اليك هذا القران وان كنت من قبله لمن الغافلين', NULL, 'We relate to you, [O Muḥammad], the best of stories in what We have revealed to you of this Qur’ān although you were, before it, among the unaware.', 'Kami ceritakan kepadamu (wahai Muhammad) seindah-indah kisah dengan jalan Kami wahyukan kepadamu Al-Quran ini, padahal sebenarnya engkau sebelum datangnya wahyu itu, adalah dari orang-orang yang tidak pernah menyedari akan halnya.', FALSE, NULL, NULL, 235, 12, 94, 193, FALSE, 16, NULL),
(12, 4, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَـٰجِدِينَ', 'اذ قال يوسف لابيه يا ابت اني رايت احد عشر كوكبا والشمس والقمر رايتهم لي ساجدين', NULL, '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."', '(Ingatlah peristiwa) ketika Nabi Yusuf berkata kepada bapanya: “Wahai ayahku! Sesungguhnya aku mimpi melihat sebelas bintang dan matahari serta bulan; aku melihat mereka tunduk memberi hormat kepadaku”.', FALSE, NULL, NULL, 235, 12, 94, 193, FALSE, 15, NULL),
(12, 5, 'قَالَ يَـٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَـٰنَ لِلْإِنسَـٰنِ عَدُوٌّ مُّبِينٌ', 'قال يا بني لا تقصص رؤياك على اخوتك فيكيدوا لك كيدا ان الشيطان للانسان عدو مبين', NULL, 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.', 'Bapanya berkata: “Wahai anakku! Janganlah engkau ceritakan mimpimu kepada saudara-saudaramu, kerana aku khuatir mereka akan menjalankan sesuatu rancangan jahat terhadapmu. Sesungguhnya syaitan adalah musuh yang nyata bagi manusia.', FALSE, NULL, NULL, 236, 12, 94, 193, FALSE, 15, NULL),
(12, 6, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَـٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ', 'وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث ويتم نعمته عليك وعلى ال يعقوب كما اتمها على ابويك من قبل ابراهيم واسحاق ان ربك عليم حكيم', NULL, 'And thus will your Lord choose you and teach you the interpretation of narratives [i.e., events or dreams] and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."', 'Dan demikianlah caranya Tuhanmu memilihmu, dan akan mengajarmu takbir mimpi, serta akan menyempurnakan nikmatNya kepadamu dan kepada keluarga Yaakub: sebagaimana Ia telah menyempurnakannya kepada datuk nenekmu dahulu: Ibrahim dan Ishak. Sesungguhnya Tuhanmu Maha Mengetahui, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 236, 12, 94, 193, FALSE, 25, NULL),
(12, 7, '۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَـٰتٌ لِّلسَّآئِلِينَ', 'لقد كان في يوسف واخوته ايات للسائلين', NULL, 'Certainly were there in Joseph and his brothers signs for those who ask, [such as]', 'Demi sesungguhnya! (Kisah) Nabi Yusuf dengan saudara-saudaranya itu mengandungi beberapa pengajaran bagi orang-orang yang bertanya (tentang hal mereka untuk mengambil iktibar).', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 7, NULL),
(12, 8, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَـٰلٍ مُّبِينٍ', 'اذ قالوا ليوسف واخوه احب الى ابينا منا ونحن عصبة ان ابانا لفي ضلال مبين', NULL, 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.', '(Kisah itu bermula) ketika saudara-saudara Yusuf berkata (sesama sendiri): “Sesungguhnya Yusuf dan adiknya, lebih disayangi oleh bapa kita daripada kita, padahal kita ini satu kumpulan (yang ramai dan berguna). Sesungguhnya bapa kita adalah dalam keadaan tidak adil yang nyata.”', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 15, NULL),
(12, 9, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَـٰلِحِينَ', 'اقتلوا يوسف او اطرحوه ارضا يخل لكم وجه ابيكم وتكونوا من بعده قوما صالحين', NULL, 'Kill Joseph or cast him out to [another] land; the countenance [i.e., attention] of your father will [then] be only for you, and you will be after that a righteous people."', '(Ramai di antara mereka berkata): “Bunuhlah Yusuf atau buanglah dia ke suatu tempat yang jauh, supaya perhatian dan kasih sayang bapa kamu tertumpu kepada kamu semata-mata, dan supaya kamu sesudah itu menjadi orang-orang yang baik dan berguna”.', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 14, NULL),
(12, 10, 'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَـٰعِلِينَ', 'قال قائل منهم لا تقتلوا يوسف والقوه في غيابت الجب يلتقطه بعض السيارة ان كنتم فاعلين', NULL, 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."', 'Salah seorang di antara mereka berkata: “Janganlah kamu membunuh Yusuf, tetapi buanglah dia ke dalam pergi, supaya ia dipungut oleh sebahagian dari orang-orang musafir (yang lalu di situ), kalaulah kamu tetap hendak menjalankan rancangan kamu itu”.', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 16, NULL),
(12, 11, 'قَالُوا۟ يَـٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ', 'قالوا يا ابانا ما لك لا تامنا على يوسف وانا له لناصحون', NULL, 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?', 'Mereka pun (pergi berjumpa dengan bapa mereka lalu) berkata: Wahai ayah kami! Mengapa ayah tidak percaya kepada kami tentang Yusuf, padahal sesungguhnya kami sentiasa tulus ikhlas mengambil berat kepadanya?', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 11, NULL),
(12, 12, 'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ', 'ارسله معنا غدا يرتع ويلعب وانا له لحافظون', NULL, 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians."', 'Biarkan dia pergi bersama-sama kami esok, supaya ia bersuka ria makan minum dan bermain-main dengan bebasnya; dan sesungguhnya kami akan menjaganya dengan sebaik-baiknya”.', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 8, NULL),
(12, 13, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَـٰفِلُونَ', 'قال اني ليحزنني ان تذهبوا به واخاف ان ياكله الذئب وانتم عنه غافلون', NULL, '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."', 'Bapa mereka menjawab: “Permergian kamu membawanya bersama sangatlah mendukacitakan daku, dan aku pula bimbang ia akan dimakan oleh serigala, ketika kamu lalai dari mengawalnya”.', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 13, NULL),
(12, 14, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَـٰسِرُونَ', 'قالوا لئن اكله الذئب ونحن عصبة انا اذا لخاسرون', NULL, 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."', 'Mereka berkata: “Kalau dia dimakan oleh serigala, sedang kami ramai bilangannya, sesungguhnya kami sudah tentu menjadilah orang-orang yang rugi”.', FALSE, NULL, NULL, 236, 12, 95, 194, FALSE, 9, NULL),
(12, 15, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَـٰذَا وَهُمْ لَا يَشْعُرُونَ', 'فلما ذهبوا به واجمعوا ان يجعلوه في غيابت الجب واوحينا اليه لتنبئنهم بامرهم هذا وهم لا يشعرون', NULL, 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."', 'Setelah mereka pergi dengan membawanya bersama dan setelah mereka sekata hendak melepaskan dia ke dalam perigi, (mereka pun melakukan yang demikian), dan kami pula ilhamkan kepadanya: “Sesungguhnya engkau (wahai Yusuf, akan terselamat, dan) akan memberi tahu mereka tentang hal perbuatan mereka ini, sedang mereka tidak sedar (dan tidak mengingatinya lagi)”.', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 17, NULL),
(12, 16, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ', 'وجاءوا اباهم عشاء يبكون', NULL, 'And they came to their father at night, weeping.', 'Dan sesudah itu datanglah mereka mendapatkan bapa mereka pada waktu senja sambil (buat-buat) menangis.', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 4, NULL),
(12, 17, 'قَالُوا۟ يَـٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَـٰدِقِينَ', 'قالوا يا ابانا انا ذهبنا نستبق وتركنا يوسف عند متاعنا فاكله الذئب وما انت بمؤمن لنا ولو كنا صادقين', NULL, 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."', 'Mereka berkata: “Wahai ayah kami! Sesungguhnya kami telah pergi berlumba-lumba berburu dan kami telah tinggalkan Yusuf menjaga barang-barang kami, lalu ia dimakan oleh serigala; dan sudah tentu ayah tidak akan percaya kepada kata-kata kami ini, sekalipun kami adalah orang-orang yang benar”.', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 18, NULL),
(12, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'وجاءوا على قميصه بدم كذب قال بل سولت لكم انفسكم امرا فصبر جميل والله المستعان على ما تصفون', NULL, 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allāh is the one sought for help against that which you describe."', 'Dan (bagi mengesahkan dakwaan itu) mereka pula melumurkan baju Yusuf dengan darah palsu. Bapa mereka berkata: “Tidak! Bahkan nafsu kamu memperelokkan kepada kamu suatu perkara (yang tidak diterima akal). Kalau demikian, bersabarlah aku dengan sebaik-baiknya, dan Allah jualah yang dipohonkan pertolonganNya, mengenai apa yang kamu katakan itu.”', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 18, NULL),
(12, 19, 'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَـٰبُشْرَىٰ هَـٰذَا غُلَـٰمٌ ۚ وَأَسَرُّوهُ بِضَـٰعَةً ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', 'وجاءت سيارة فارسلوا واردهم فادلى دلوه قال يا بشرى هذا غلام واسروه بضاعة والله عليم بما يعملون', NULL, 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allāh was Knowing of what they did.', 'Dan (semasa Yusuf dalam perigi) datanglah ke tempat itu satu rombongan (ahli perniagaan) yang sedang dalam perjalanan; lalu mereka menghantarkan seorang pencari air bagi mereka; (setelah sampainya ke perigi itu) dia pun menghulurkan timbanya (dan manakala ia melihat Yusuf bergantung pada timbanya) ia berseru dengan katanya: “Hai, (ini) sungguh mengembirakan! Ini adalah seorang budak lelaki (yang cantik parasnya)”. (Setelah mengetahui hal itu, saudara-saudara Yusuf pun datang) serta mereka sembunyikan keadaan Yusuf yang sebenarnya (untuk dijual) sebagai barang dagangan. Dan Allah Maha Mengetahui akan apa yang mereka lakukan.', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 16, NULL),
(12, 20, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', 'وشروه بثمن بخس دراهم معدودة وكانوا فيه من الزاهدين', NULL, 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.', 'Dan (setelah berlaku perundingan) mereka menjualnya dengan harga yang murah, iaitu beberapa dirham sahaja bilangannya; dan mereka adalah orang-orang yang tidak menghargainya.', FALSE, NULL, NULL, 237, 12, 95, 194, FALSE, 9, NULL),
(12, 21, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وَقَالَ الَّذِي اشْتَرَاهُ مِن مِّصْرَ لِامْرَأَتِهِ أَكْرِمِي مَثْوَاهُ عَسَىٰ أَن يَنفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِن تَأْوِيلِ الْأَحَادِيثِ وَاللَّهُ غَالِبٌ عَلَىٰ أَمْرِهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'And the one from Egypt who bought him said to his wife, "Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son." And thus, We established Joseph in the land that We might teach him the interpretation of events [i.e., dreams]. And Allāh is predominant over His affair, but most of the people do not know.', 'Dan (setelah Yusuf dijualkan di negeri Mesir), berkatalah orang yang membeli Yusuf kepada isterinya: “Berilah dia layanan yang sebaik-baiknya; semoga ia berguna kepada kita, atau kita jadikan dia anak”. Dan demikianlah caranya kami menetapkan kedudukan Yusuf di bumi (Mesir untuk dihormati dan disayangi), dan untuk kami mengajarnya sebahagian dari ilmu takbir mimpi. Dan Allah Maha Kuasa melakukan segala perkara yang telah ditetapkanNya, akan tetapi kebanyakan manusia tidak mengetahui.', FALSE, NULL, NULL, 237, 12, 95, 195, FALSE, 0, NULL),
(12, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْنَاهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'And when he [i.e., Joseph] reached maturity, We gave him judgement and knowledge. And thus We reward the doers of good.', 'Dan ketika Yusuf sampai ke peringkat umurnya yang sempurna kekuatannya, Kami beri kepadanya kebijaksanaan serta ilmu pengetahuan; dan demikianlah kami membalas orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 237, 12, 95, 195, FALSE, 0, NULL),
(12, 23, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ ٱللَّهِ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'وَرَاوَدَتْهُ الَّتِي هُوَ فِي بَيْتِهَا عَن نَّفْسِهِ وَغَلَّقَتِ الْأَبْوَابَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ اللَّهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', NULL, 'And she, in whose house he was, sought to seduce him. She closed the doors and said, "Come, you." He said, "[I seek] the refuge of Allāh. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed."', 'Dan perempuan yang Yusuf tinggal di rumahnya, bersungguh-sungguh memujuk Yusuf berkehendakkan dirinya; dan perempuan itupun menutup pintu-pintu serta berkata: “Marilah ke mari, aku bersedia untukmu”. Yusuf menjawab: “Aku berlindung kepada Allah (dari perbuatan yang keji itu); sesungguhnya Tuhanku telah memuliharaku dengan sebaik-baiknya; sesungguhnya orang-orang yang zalim tidak akan berjaya”.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 24, 'وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', 'وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا لَوْلَا أَن رَّأَىٰ بُرْهَانَ رَبِّهِ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشَاءَ إِنَّهُ مِنْ عِبَادِنَا الْمُخْلَصِينَ', NULL, 'And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof [i.e., sign] of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants.', 'Dan sebenarnya perempuan itu telah berkeinginan sangat kepadanya, dan Yusuf pula (mungkin timbul) keinginannya kepada perempuan itu kalaulah ia tidak menyedari kenyataan Tuhannya (tentang kejinya perbuatan zina itu). Demikianlah (takdir Kami) untuk menjauhkan dari Yusuf perkara-perkara yang tidak baik dan perbuatan-perbuatan yang keji, kerana sesungguhnya ia dari hamba-hamba Kami yang dibersihkan dari segala dosa.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 25, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', 'وَاسْتَبَقَا الْبَابَ وَقَدَّتْ قَمِيصَهُ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَى الْبَابِ قَالَتْ مَا جَزَاءُ مَنْ أَرَادَ بِأَهْلِكَ سُوءًا إِلَّا أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', NULL, 'And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, "What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?"', 'Dan mereka berdua pun berkejaran ke pintu, serta perempuan itu mengoyakkan baju Yusuf dari belakang; lalu terserempaklah keduanya dengan suami perempuan itu di muka pintu. Tiba-tiba perempuan itu berkata (kepada suaminya): Tidak ada balasan bagi orang yang mahu membuat jahat terhadap isterimu melainkan dipenjarakan dia atau dikenakan azab yang menyiksanya”.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 26, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 'قَالَ هِيَ رَاوَدَتْنِي عَن نَّفْسِي وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَا إِن كَانَ قَمِيصُهُ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكَاذِبِينَ', NULL, '[Joseph] said, "It was she who sought to seduce me." And a witness from her family testified, "If his shirt is torn from the front, then she has told the truth, and he is of the liars.', 'Yusuf pula berkata: “Dia lah yang memujukku berkehendakkan diriku”. (Suaminya tercengang mendengarnya) dan seorang dari keluarga perempuan itu (yang ada bersama-sama) tampil memberi pendapatnya dengan berkata: “Jika baju Yusuf koyak dari depan maka benarlah tuduhan perempuan itu, dan menjadilah Yusuf dari orang-orang yang dusta.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 'وَإِن كَانَ قَمِيصُهُ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ', NULL, 'But if his shirt is torn from the back, then she has lied, and he is of the truthful."', 'Dan jika bajunya koyak dari belakang, maka dustalah perempuan itu, dan Yusuf adalah dari orang-orang yang benar”.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 28, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ', 'فَلَمَّا رَأَىٰ قَمِيصَهُ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ', NULL, 'So when he [i.e., her husband] saw his shirt torn from the back, he said, "Indeed, it is of your [i.e., women''s] plan. Indeed, your plan is great [i.e., vehement].', 'Setelah suaminya melihat baju Yusuf koyak dari belakang, berkatalah ia: “Sesungguhnya ini adalah dari tipu daya kamu orang-orang perempuan; sesungguhnya tipu daya kamu amatlah besar pengaruhnya.', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 29, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَٱسْتَغْفِرِى لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَاسْتَغْفِرِي لِذَنبِكِ إِنَّكِ كُنتِ مِنَ الْخَاطِئِينَ', NULL, 'Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful."', 'Wahai Yusuf, lupakanlah hal ini. Dan engkau (Wahai Zulaikha), mintalah ampun bagi dosamu, sesungguhnya engkau adalah dari orang-orang yang bersalah!”', FALSE, NULL, NULL, 238, 12, 95, 195, FALSE, 0, NULL),
(12, 30, 'وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍ مُّبِينٍ', 'وَقَالَ نِسْوَةٌ فِي الْمَدِينَةِ امْرَأَتُ الْعَزِيزِ تُرَاوِدُ فَتَاهَا عَن نَّفْسِهِ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَاهَا فِي ضَلَالٍ مُّبِينٍ', NULL, 'And women in the city said, "The wife of al-ʿAzeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error."', 'Dan (sesudah itu) perempuan-perempuan di bandar Mesir (mencaci hal Zulaikha dengan) berkata: Isteri Al-Aziz itu memujuk hambanya (Yusuf) berkehendakkan dirinya, sesungguhnya cintanya (kepada Yusuf) itu sudahlah meresap ke dalam lipatan hatinya; sesungguhnya kami memandangnya berada dalam kesesatan yang nyata.”', FALSE, NULL, NULL, 238, 12, 96, 196, FALSE, 0, NULL),
(12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌ كَرِيمٌ', 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَأً وَآتَتْ كُلَّ وَاحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ اخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُ أَكْبَرْنَهُ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَاشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَا إِلَّا مَلَكٌ كَرِيمٌ', NULL, 'So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], "Come out before them." And when they saw him, they greatly admired him and cut their hands and said, "Perfect is Allāh! This is not a man; this is none but a noble angel."', 'Maka apabila ia (Zulaikha) mendengar cacian mereka, dia pun menjemput mereka dan menyediakan satu jamuan untuk mereka, serta memberi kepada - tiap seorang di antara mereka sebilah pisau. Dan pada ketika itu berkatalah ia (kepada Yusuf): “Keluarlah di hadapan mereka”. Maka ketika mereka melihatnya, mereka tercengang melihat kecantikan parasnya, dan mereka dengan tidak sedar melukakan tangan mereka sambil berkata: “Jauhnya Allah dari kekurangan! Ini bukanlah seorang manusia, ini tidak lain melainkan malaikat yang mulia!”', FALSE, NULL, NULL, 239, 12, 96, 196, FALSE, 0, NULL),
(12, 32, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّٰغِرِينَ', 'قَالَتْ فَذَٰلِكُنَّ الَّذِي لُمْتُنَّنِي فِيهِ وَلَقَدْ رَاوَدتُّهُ عَن نَّفْسِهِ فَاسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَا آمُرُهُ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ الصَّاغِرِينَ', NULL, 'She said, "That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased."', '(Zulaikha) berkata: “Inilah orangnya yang kamu tempelak aku mengenainya! Sebenarnya aku telah memujuknya berkehendakkan dirinya tetapi ia menolak dan berpegang teguh kepada kesuciannya; dan demi sesungguhnya kalau ia tidak mahu melakukan apa yang aku suruh tentulah ia akan dipenjarakan, dan akan menjadi dari orang-orang yang hina.”', FALSE, NULL, NULL, 239, 12, 96, 196, FALSE, 0, NULL),
(12, 33, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', 'قَالَ رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ الْجَاهِلِينَ', NULL, 'He said, "My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."', 'Yusuf (merayu kehadrat Allah Taala dengan) berkata: “Wahai Tuhanku! Aku lebih suka kepada penjara dari apa yang perempuan-perempuan itu ajak aku kepadanya. Dan jika Engkau tidak menjauhkan daripadaku tipu daya mereka, mungkin aku akan cenderung kepada mereka, dan aku menjadi dari orang-orang yang tidak mengamalkan ilmunya”.', FALSE, NULL, NULL, 239, 12, 96, 196, FALSE, 0, NULL),
(12, 34, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'فَاسْتَجَابَ لَهُ رَبُّهُ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing.', 'Maka Tuhannya memperkenankan doanya, lalu dijauhkan daripadanya tipu daya mereka; sesungguhnya Allah jualah yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 239, 12, 96, 196, FALSE, 0, NULL),
(12, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ', 'ثُمَّ بَدَا لَهُم مِّن بَعْدِ مَا رَأَوُا الْآيَاتِ لَيَسْجُنُنَّهُ حَتَّىٰ حِينٍ', NULL, 'Then it appeared to them after they had seen the signs that he [i.e., al-ʿAzeez] should surely imprison him for a time.', 'Kemudian timbul fikiran bagi suami perempuan itu, serta orang-orangnya hendak memenjarakan Yusuf sesudah mereka nampak tanda-tanda (yang menghendaki supaya Yusuf dijauhkan) hingga ke suatu masa.', FALSE, NULL, NULL, 239, 12, 96, 196, FALSE, 0, NULL),
(12, 36, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِۦٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'وَدَخَلَ مَعَهُ السِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَا إِنِّي أَرَانِي أَعْصِرُ خَمْرًا وَقَالَ الْآخَرُ إِنِّي أَرَانِي أَحْمِلُ فَوْقَ رَأْسِي خُبْزًا تَأْكُلُ الطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِ إِنَّا نَرَاكَ مِنَ الْمُحْسِنِينَ', NULL, 'And there entered the prison with him two young men. One of them said, "Indeed, I have seen myself [in a dream] pressing [grapes for] wine." The other said, "Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good."', 'Dan masuklah bersama-samanya ke penjara dua orang khadam raja. Salah seorang di antaranya (bertanya kepada Yusuf dengan) berkata: “Sesungguhnya aku bermimpi melihat diriku memerah anggur”. Dan berkata pula yang seorang lagi: “Sesungguhnya aku bermimpi melihat diriku menjunjung roti atas kepalaku, yang sebahagiannya dimakan oleh burung.” (kemudian keduanya berkata): “Terangkanlah kepada kami akan takbirnya. Sesungguhnya kami memandangmu: dari orang-orang yang berbuat kebaikan (untuk umum)”.', FALSE, NULL, NULL, 239, 12, 96, 197, FALSE, 0, NULL),
(12, 37, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّي إِنِّي تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِاللَّهِ وَهُم بِالْآخِرَةِ هُمْ كَافِرُونَ', NULL, 'He said, "You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allāh, and they, in the Hereafter, are disbelievers.', 'Yusuf menjawab: “(Aku bukan sahaja dapat menerangkan takbir mimpi kamu itu, bahkan) tidak datang kepada kamu sesuatu makanan yang diberikan kepada kamu (tiap-tiap hari dalam penjara), melainkan aku juga dapat memberitahu kepada kamu akan nama dan jenisnya, sebelum ia dibawa kepada kamu. Yang demikian itu ialah sebahagian dari apa yang diajarkan kepadaku oleh Tuhanku. Dengan sebab itu aku meninggalkan ugama kaum yang tidak beriman kepada Allah serta tidak pula percayakan hari akhirat.', FALSE, NULL, NULL, 239, 12, 96, 197, FALSE, 0, NULL),
(12, 38, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'وَاتَّبَعْتُ مِلَّةَ آبَائِي إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ مَا كَانَ لَنَا أَن نُّشْرِكَ بِاللَّهِ مِن شَيْءٍ ذَٰلِكَ مِن فَضْلِ اللَّهِ عَلَيْنَا وَعَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', NULL, 'And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allāh. That is from the favor of Allāh upon us and upon the people, but most of the people are not grateful.', '“Dan aku menurut ugama bapa dan datuk nenekku: Ibrahim dan Ishak serta Yaakub. Tidaklah sepatutnya kita mempersekutukan sesuatupun dengan Allah. Mentauhid - mengesakan Allah ialah hasil dari limpah kurnia Allah kepada kita dan kepada umat manusia. Tetapi kebanyakan manusia tidak bersyukur.', FALSE, NULL, NULL, 240, 12, 96, 197, FALSE, 0, NULL),
(12, 39, 'يَٰصَٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'يَا صَاحِبَيِ السِّجْنِ أَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ اللَّهُ الْوَاحِدُ الْقَهَّارُ', NULL, 'O [my] two companions of prison, are separate lords better or Allāh, the One, the Prevailing?', '“Wahai sahabatku berdua yang sepenjara, memuja dan menyembah berbilang-bilang tuhan yang bercerai-berai itukah yang lebih baik atau menyembah Allah Tuhan Yang Maha Esa, lagi Maha Kuasa?', FALSE, NULL, NULL, 240, 12, 96, 197, FALSE, 0, NULL),
(12, 40, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'مَا تَعْبُدُونَ مِن دُونِهِ إِلَّا أَسْمَاءً سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا أَنزَلَ اللَّهُ بِهَا مِن سُلْطَانٍ إِنِ الْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ ذَٰلِكَ الدِّينُ الْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allāh has sent down no evidence. Legislation is not but for Allāh. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know.', 'Apa yang kamu sembah, yang lain dari Allah, hanyalah nama-nama yang kamu menamakannya, kamu dan datuk nenek kamu, Allah tidak pernah menurunkan sebarang bukti yang membenarkannya. Sebenarnya hukum (yang menentukan amal ibadat) hanyalah bagi Allah. Ia memerintahkan supaya kamu jangan menyembah melainkan Dia. Yang demikian itulah Ugama yang betul, tetapi kebanyakan manusia tidak mengetahui.', FALSE, NULL, NULL, 240, 12, 96, 197, FALSE, 0, NULL),
(12, 41, 'يَٰصَٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', 'يَا صَاحِبَيِ السِّجْنِ أَمَّا أَحَدُكُمَا فَيَسْقِي رَبَّهُ خَمْرًا وَأَمَّا الْآخَرُ فَيُصْلَبُ فَتَأْكُلُ الطَّيْرُ مِن رَّأْسِهِ قُضِيَ الْأَمْرُ الَّذِي فِيهِ تَسْتَفْتِيَانِ', NULL, 'O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire."', '“Wahai sahabatku berdua yang sepenjara! (Takbir mimpi kamu itu ialah): adapun salah seorang dari kamu, maka ia akan memberi minum arak kepada tuannya. Ada pun yang seorang lagi, maka ia akan dipalang, serta burung pula akan makan dari kepalanya. Telah selesailah (dan tetaplah berlakunya) perkara yang kamu tanyakan itu”.', FALSE, NULL, NULL, 240, 12, 96, 197, FALSE, 0, NULL),
(12, 42, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', 'وَقَالَ لِلَّذِي ظَنَّ أَنَّهُ نَاجٍ مِّنْهُمَا اذْكُرْنِي عِندَ رَبِّكَ فَأَنسَاهُ الشَّيْطَانُ ذِكْرَ رَبِّهِ فَلَبِثَ فِي السِّجْنِ بِضْعَ سِنِينَ', NULL, 'And he said to the one whom he knew would go free, "Mention me before your master." But Satan made him forget the mention [to] his master, and he [i.e., Joseph] remained in prison several years.', 'Dan berkatalah Yusuf kepada orang yang ia percaya akan terselamat di antara mereka berdua: “Sebutkanlah perihalku kepada tuanmu”. (Setelah orang itu dibebaskan dari penjara) maka ia dilupakan oleh syaitan untuk menyebutkan (hal Yusuf) kepada tuannya. Dengan sebab itu tinggallah Yusuf dalam penjara beberapa tahun.', FALSE, NULL, NULL, 240, 12, 96, 197, FALSE, 0, NULL),
(12, 43, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', 'وَقَالَ الْمَلِكُ إِنِّي أَرَىٰ سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ يَا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي رُؤْيَايَ إِن كُنتُمْ لِلرُّؤْيَا تَعْبُرُونَ', NULL, 'And [subsequently] the king said, "Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions."', 'Dan (pada suatu hari) raja Mesir berkata: “Sesungguhnya aku mimpi melihat: tujuh ekor lembu yang gemuk dimakan oleh tujuh ekor lembu yang kurus, dan aku melihat tujuh tangkai (biji-bijian) yang hijau dan tujuh tangkai lagi yang kering. Wahai ketua-ketua kaum (yang hadir, terangkanlah kepadaku tentang mimpiku ini, kalau kamu orang yang pandai menafsirkan mimpi”.', FALSE, NULL, NULL, 240, 12, 96, 198, FALSE, 0, NULL),
(12, 44, 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', 'قَالُوا أَضْغَاثُ أَحْلَامٍ وَمَا نَحْنُ بِتَأْوِيلِ الْأَحْلَامِ بِعَالِمِينَ', NULL, 'They said, "[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams."', 'Mereka menjawab: “Yang demikian itu ialah mimpi-mimpi yang bercampur aduk, dan kami bukanlah orang-orang yang mengetahui mimpi-mimpi (yang sedemikian) itu”.', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 45, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 'وَقَالَ الَّذِي نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ أُمَّةٍ أَنَا أُنَبِّئُكُم بِتَأْوِيلِهِ فَأَرْسِلُونِ', NULL, 'But the one who was freed and remembered after a time said, "I will inform you of its interpretation, so send me forth."', 'Dan (pada saat itu) berkatalah orang yang terselamat di antara mereka yang berdua itu, dan yang baharu mengingati (akan pesanan Yusuf) sesudah berlalu suatu masa yang lanjut: “Aku akan memberi tahu kepada kamu tafsirannya. Oleh itu hantarkanlah daku pergi (kepada orang yang mengetahui tafsirannya)”.', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 46, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'يُوسُفُ أَيُّهَا الصِّدِّيقُ أَفْتِنَا فِي سَبْعِ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ لَّعَلِّي أَرْجِعُ إِلَى النَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', NULL, '[He said], "Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people [i.e., the king and his court]; perhaps they will know [about you]."', '(Setelah ia berjumpa dengan Yusuf, berkatalah ia): “Yusuf, Wahai orang yang benar (pada segala-galanya)! tafsirkanlah kepada kami (seorang bermimpi melihat): tujuh ekor lembu yang gemuk dimakan oleh tujuh ekor lembu yang kurus; dan tujuh tangkai (biji-bijian) yang hijau serta tujuh tangkai lagi yang kering; (tafsirkanlah) supaya aku kembali kepada orang-orang yang mengutusku itu, semoga mereka dapat mengetahui tafsirannya”.', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِي سُنبُلِهِ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', NULL, '[Joseph] said, "You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat.', 'Yusuf menjawab: “Hendaklah kamu menanam bersungguh-sungguh tujuh tahun berturut-turut, kemudian apa yang kamu ketam biarkanlah dia pada tangkai-tangkainya; kecuali sedikit dari bahagian yang kamu jadikan untuk makan.', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 48, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', 'ثُمَّ يَأْتِي مِن بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', NULL, 'Then will come after that seven difficult [years] which will consume what you advanced [i.e., saved] for them, except a little from which you will store.', 'Kemudian akan datang selepas tempoh itu, tujuh tahun yang bersangatan kemaraunya, yang akan menghabiskan makanan yang kamu sediakan baginya; kecuali sedikit dari apa yang kamu simpan (untuk dijadikan benih).', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 49, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', 'ثُمَّ يَأْتِي مِن بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ النَّاسُ وَفِيهِ يَعْصِرُونَ', NULL, 'Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes]."', '“Kemudian akan datang pula sesudah itu tahun yang padanya orang ramai beroleh rahmat hujan, dan padanya mereka dapat memerah (hasil anggur, zaitun dan sebagainya)”.', FALSE, NULL, NULL, 241, 12, 96, 198, FALSE, 0, NULL),
(12, 50, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ', 'وَقَالَ الْمَلِكُ ائْتُونِي بِهِ فَلَمَّا جَاءَهُ الرَّسُولُ قَالَ ارْجِعْ إِلَىٰ رَبِّكَ فَاسْأَلْهُ مَا بَالُ النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّي بِكَيْدِهِنَّ عَلِيمٌ', NULL, 'And the king said, "Bring him to me." But when the messenger came to him, [Joseph] said, "Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan."', 'Dan (apabila mendengar tafsiran itu) berkatalah raja Mesir: “Bawalah dia kepadaku! “Maka tatkata utusan raja datang kepada Yusuf (menjemputnya mengadap raja), Yusuf berkata kepadanya: Kembalilah kepada tuanmu kemudian bertanyalah kepadanya: “Apa halnya perempuan-perempuan yang melukakan tangan mereka? Sesungguhnya Tuhanku Maha Mengetahui tipu daya mereka”.', FALSE, NULL, NULL, 241, 12, 96, 199, FALSE, 0, NULL),
(12, 51, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 'قَالَ مَا خَطْبُكُنَّ إِذْ رَاوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِ قُلْنَ حَاشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوءٍ قَالَتِ امْرَأَتُ الْعَزِيزِ الْآنَ حَصْحَصَ الْحَقُّ أَنَا رَاوَدتُّهُ عَن نَّفْسِهِ وَإِنَّهُ لَمِنَ الصَّادِقِينَ', NULL, 'Said [the king to the women], "What was your condition when you sought to seduce Joseph?" They said, "Perfect is Allāh! We know about him no evil." The wife of al-ʿAzeez said, "Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.', 'Setelah perempuan-perempuan itu dipanggil), raja bertanya kepada mereka: “Apahal kamu, semasa kamu memujuk Yusuf mengenai dirinya?” Mereka menjawab: JauhNya Allah dari segala cacat cela, kami tidak mengetahui sesuatu kejahatan terhadap Yusuf”. Isteri Al-Aziz pun berkata: “Sekarang ternyatalah kebenaran (yang selama ini tersembunyi), akulah yang memujuk Yusuf berkehendakkan dirinya (tetapi ia telah menolak); dan sesungguhnya adalah ia dari orang-orang yang benar.', FALSE, NULL, NULL, 241, 12, 96, 199, FALSE, 0, NULL),
(12, 52, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 'ذَٰلِكَ لِيَعْلَمَ أَنِّي لَمْ أَخُنْهُ بِالْغَيْبِ وَأَنَّ اللَّهَ لَا يَهْدِي كَيْدَ الْخَائِنِينَ', NULL, 'That is so he [i.e., al-ʿAzeez] will know that I did not betray him in [his] absence and that Allāh does not guide the plan of betrayers.', '“(Pengakuanku) yang demikian supaya ia mengetahui, bahawa aku tidak mengkhianatinya semasa ia tidak hadir (bersama di sini); dan bahawa Allah tidak menjayakan tipu daya orang-orang yang khianat.', FALSE, NULL, NULL, 241, 12, 96, 199, FALSE, 0, NULL),
(12, 53, 'وَمَآ أُبَرِّئُ نَفْسِىٓ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ', 'وَمَا أُبَرِّئُ نَفْسِي إِنَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي إِنَّ رَبِّي غَفُورٌ رَّحِيمٌ', NULL, 'And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful."', '“Dan tiadalah aku berani membersihkan diriku; sesungguhnya nafsu manusia itu sangat menyuruh melakukan kejahatan, kecuali orang-orang yang telah diberi rahmat oleh Tuhanku (maka terselamatlah ia dari hasutan nafsu itu). Sesungguhnya Tuhanku Maha Pengampun, lagi Maha Mengasihani.”', FALSE, NULL, NULL, 242, 13, 97, 199, FALSE, 0, NULL),
(12, 54, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', 'وَقَالَ الْمَلِكُ ائْتُونِي بِهِ أَسْتَخْلِصْهُ لِنَفْسِي فَلَمَّا كَلَّمَهُ قَالَ إِنَّكَ الْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', NULL, 'And the king said, "Bring him to me; I will appoint him exclusively for myself." And when he spoke to him, he said, "Indeed, you are today established [in position] and trusted."', 'Dan (setelah mendengar pengakuan perempuan-perempuan itu), raja berkata: “Bawalah Yusuf kepadaku, aku hendak menjadikan dia orang yang khas untuk aku bermesyuarat dengannya. Setelah (Yusuf dibawa mengadap, dan raja) berkata-kata dengannya (serta mengetahui kebijaksanaannya) berkatalah raja kepadanya: “Sesungguhnya engkau pada hari ini (wahai Yusuf), seorang yang berpangkat tinggi, lagi dipercayai di kalangan kami”.', FALSE, NULL, NULL, 242, 13, 97, 199, FALSE, 0, NULL),
(12, 55, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ إِنِّى حَفِيظٌ عَلِيمٌ', 'قَالَ اجْعَلْنِي عَلَىٰ خَزَائِنِ الْأَرْضِ إِنِّي حَفِيظٌ عَلِيمٌ', NULL, '[Joseph] said, "Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian."', 'Yusuf berkata: “Jadikanlah daku pengurus perbendaharaan hasil bumi (Mesir); sesungguhnya aku sedia menjaganya dengan sebaik-baiknya, lagi mengetahui cara mentadbirkannya”.', FALSE, NULL, NULL, 242, 13, 97, 199, FALSE, 0, NULL),
(12, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَاءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَاءُ وَلَا نُضِيعُ أَجْرَ الْمُحْسِنِينَ', NULL, 'And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good.', 'Dan demikianlah caranya, Kami tetapkan kedudukan Yusuf memegang kuasa di bumi Mesir; ia bebas tinggal di negeri itu di mana sahaja yang disukainya. Kami limpahkan rahmat Kami kepada sesiapa sahaja yang Kami kehendaki, dan Kami tidak menghilangkan balasan baik orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 242, 13, 97, 199, FALSE, 0, NULL),
(12, 57, 'وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'وَلَأَجْرُ الْآخِرَةِ خَيْرٌ لِّلَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ', NULL, 'And the reward of the Hereafter is better for those who believed and were fearing Allāh.', 'Dan sesungguhnya pahala hari akhirat lebih baik bagi orang-orang yang beriman serta mereka pula sentiasa bertaqwa.', FALSE, NULL, NULL, 242, 13, 97, 199, FALSE, 0, NULL),
(12, 58, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', 'وَجَاءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُ مُنكِرُونَ', NULL, 'And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown.', 'Dan (setelah tiba musim kemarau) datanglah saudara-saudara Yusuf (ke Mesir), lalu masuklah mereka mendapatkannya; Yusuf dengan serta merta kenal mereka, sedang mereka tidak mengenalnya.', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ائْتُونِي بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّي أُوفِي الْكَيْلَ وَأَنَا خَيْرُ الْمُنزِلِينَ', NULL, 'And when he had furnished them with their supplies, he said, "Bring me a brother of yours from your father. Do you not see that I give full measure and that I am the best of accommodators?', 'Dan ketika Yusuf menyediakan untuk mereka bekalan mereka, berkatalah ia: “(Pada kali yang lain) bawalah kepadaku saudara kamu yang sebapa. Tidakkah kamu melihat, bahawa aku menyempurnakan bekalan makanan kamu, dan bahawa aku sebaik-baik penerima tetamu?', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 60, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', 'فَإِن لَّمْ تَأْتُونِي بِهِ فَلَا كَيْلَ لَكُمْ عِندِي وَلَا تَقْرَبُونِ', NULL, 'But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me."', 'Oleh itu, kalau kamu tidak membawanya kepadaku, maka tidak ada hak bagi kamu mendapat bekalan makanan di sisiku, dan janganlah kamu menghampiriku lagi”.', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 61, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', 'قَالُوا سَنُرَاوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَاعِلُونَ', NULL, 'They said, "We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it]."', 'Mereka menjawab: “Kami akan memujuk bapanya melepaskan dia bersama-sama kami, dan sesungguhnya kami akan melakukannya”.', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 62, 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', 'وَقَالَ لِفِتْيَانِهِ اجْعَلُوا بِضَاعَتَهُمْ فِي رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَا إِذَا انقَلَبُوا إِلَىٰ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And [Joseph] said to his servants, "Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return."', 'Dan (selepas itu) berkatalah Yusuf kepada orang-orang suruhannya. “Masukkanlah barang-barang dagangan mereka pada tempat simpanan barang di kenderaan mereka, supaya mereka mengetahuinya kelak ketika mereka kembali kepada keluarga mereka, dan supaya mereka datang lagi (ke negeri ini)”.', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 63, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'فَلَمَّا رَجَعُوا إِلَىٰ أَبِيهِمْ قَالُوا يَا أَبَانَا مُنِعَ مِنَّا الْكَيْلُ فَأَرْسِلْ مَعَنَا أَخَانَا نَكْتَلْ وَإِنَّا لَهُ لَحَافِظُونَ', NULL, 'So when they returned to their father, they said, "O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians."', 'Maka ketika mereka kembali kepada bapa mereka, berkatalah mereka: “Wahai ayah kami! Kami (tetap diberi amaran bahawa kami) tidak akan mendapat lagi bekalan makanan (kiranya Bunyamin tidak pergi bersama). Oleh itu, hantarkanlah dia bersama-sama kami, supaya kami dapat lagi bekalan makanan; dan sesungguhnya kami akan menjaganya dengan sebaik-baiknya”.', FALSE, NULL, NULL, 242, 13, 97, 200, FALSE, 0, NULL),
(12, 64, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ فَٱللَّهُ خَيْرٌ حَٰفِظًا وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قَالَ هَلْ آمَنُكُمْ عَلَيْهِ إِلَّا كَمَا أَمِنتُكُمْ عَلَىٰ أَخِيهِ مِن قَبْلُ فَاللَّهُ خَيْرٌ حَافِظًا وَهُوَ أَرْحَمُ الرَّاحِمِينَ', NULL, 'He said, "Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allāh is the best guardian, and He is the most merciful of the merciful."', 'Bapa mereka berkata: “(Jika aku lepaskan dia pergi bersama-sama kamu), aku tidak menaruh kepercayaan kepada kamu menjaganya melainkan seperti kepercayaanku kepada kamu menjaga saudaranya dahulu (yang telah kamu hampakan. Oleh itu aku hanya menaruh kepercayaan kepada Allah), kerana Allah jualah Penjaga yang sebaik-baiknya, dan Dia lah jua Yang Maha Mengasihani dari sesiapa sahaja yang menaruh belas kasihan”.', FALSE, NULL, NULL, 243, 13, 97, 200, FALSE, 0, NULL),
(12, 65, 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ', 'وَلَمَّا فَتَحُوا مَتَاعَهُمْ وَجَدُوا بِضَاعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا يَا أَبَانَا مَا نَبْغِي هَٰذِهِ بِضَاعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ', NULL, 'And when they opened their baggage, they found their merchandise returned to them. They said, "O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies [i.e., food] for our family and protect our brother and obtain an increase of a camel''s load; that is an easy measurement."', 'Dan semasa mereka membuka barang-barang mereka, mereka dapati barang-barang dagangan mereka telah dikembalikan kepada mereka. Mereka berkata dengan gembiranya: “Wahai ayah kami! Apa yang kita kehendaki lagi? Ini dia barang-barang dagangan yang kita jadikan tukaran (bagi mendapat gandum) itu telah dikembalikan kepada kita. Dan (dengan kemurahan hati menteri yang berbudi itu) akan dapatlah kami membawa lagi bekalan makanan kepada keluarga kami, dan kami pula akan dapat menjaga saudara kami, serta akan dapat tambahan benda-benda makanan sebanyak muatan seekor unta lagi. Pemberian tambahan yang sebanyak itu mudah sekali ditunaikannya”.', FALSE, NULL, NULL, 243, 13, 97, 200, FALSE, 0, NULL),
(12, 66, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'قَالَ لَنْ أُرْسِلَهُ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ اللَّهِ لَتَأْتُنَّنِي بِهِ إِلَّا أَن يُحَاطَ بِكُمْ فَلَمَّا آتَوْهُ مَوْثِقَهُمْ قَالَ اللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', NULL, '[Jacob] said, "Never will I send him with you until you give me a promise [i.e., oath] by Allāh that you will bring him [back] to me, unless you should be surrounded [i.e., overcome by enemies]." And when they had given their promise, he said, "Allāh, over what we say, is Entrusted."', 'Bapa mereka berkata: “Aku tidak sekali-kali akan melepaskan dia (Bunyamin) pergi bersama-sama kamu, sehingga kamu memberi kepadaku satu perjanjian yang teguh (bersumpah) dengan nama Allah, bahawa kamu akan membawanya kembali kepadaku dengan selamat, kecuali jika kamu semua dikepong dan dikalahkan oleh musuh”. Maka ketika mereka memberikan perjanjian yang teguh (bersumpah) kepadanya, berkatalah ia: “Allah jualah yang menjadi Saksi dan Pengawas atas apa yang kita semua katakan itu.”', FALSE, NULL, NULL, 243, 13, 97, 200, FALSE, 0, NULL),
(12, 67, 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'وَقَالَ يَا بَنِيَّ لَا تَدْخُلُوا مِن بَابٍ وَاحِدٍ وَادْخُلُوا مِنْ أَبْوَابٍ مُّتَفَرِّقَةٍ وَمَا أُغْنِي عَنكُم مِّنَ اللَّهِ مِن شَيْءٍ إِنِ الْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ', NULL, 'And he said, "O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allāh at all. The decision is only for Allāh; upon Him I have relied, and upon Him let those who would rely [indeed] rely."', 'Dan ia berkata lagi: “Wahai anak-anakku! Janganlah kamu masuk (ke bandar Mesir) dari sebuah pintu sahaja, tetapi masuklah dari beberapa buah pintu yang berlainan. Dan aku (dengan nasihatku ini), tidak dapat menyelamatkan kamu dari sesuatu takdir yang telah ditetapkan oleh Allah. Kuasa menetapkan sesuatu (sebab dan musabab) itu hanya tertentu bagi Allah. KepadaNyalah aku berserah diri, dan kepadaNyalah hendaknya berserah orang-orang yang mahu berserah diri”.', FALSE, NULL, NULL, 243, 13, 97, 200, FALSE, 0, NULL),
(12, 68, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وَلَمَّا دَخَلُوا مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِي عَنْهُم مِّنَ اللَّهِ مِن شَيْءٍ إِلَّا حَاجَةً فِي نَفْسِ يَعْقُوبَ قَضَاهَا وَإِنَّهُ لَذُو عِلْمٍ لِّمَا عَلَّمْنَاهُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'And when they entered from where their father had ordered them, it did not avail them against Allāh at all except [it was] a need [i.e., concern] within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know.', 'Dan ketika mereka masuk menurut arah yang diperintahkan oleh bapa mereka, tidaklah perintahnya itu dapat menyelamatkan mereka dari apa yang telah ditakdirkan oleh Allah sedikitpun, tetapi yang demikian itu hanyalah melahirkan hajat yang terpendam dalam hati Nabi Yaakub. Dan sesungguhnya ia orang yang berilmu, kerana kami telah mengajarnya (dengan perantaraan wahyu); tetapi kebanyakan manusia tidak mengetahui (akan rahsia takdir Tuhan).', FALSE, NULL, NULL, 243, 13, 97, 200, FALSE, 0, NULL),
(12, 69, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 'وَلَمَّا دَخَلُوا عَلَىٰ يُوسُفَ آوَىٰ إِلَيْهِ أَخَاهُ قَالَ إِنِّي أَنَا أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَعْمَلُونَ', NULL, 'And when they entered upon Joseph, he took his brother to himself; he said, "Indeed, I am your brother, so do not despair over what they used to do [to me]."', 'Dan semasa mereka masuk mendapatkan Yusuf, ia menempatkan saudara kandungnya (Bunyamin) bersama-samanya, sambil berkata kepadanya: “Akulah saudara engkau Yusuf), oleh itu janganlah engkau berdukacita lagi disebabkan apa yang mereka lakukan”.', FALSE, NULL, NULL, 243, 13, 97, 201, FALSE, 0, NULL),
(12, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ السِّقَايَةَ فِي رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا الْعِيرُ إِنَّكُمْ لَسَارِقُونَ', NULL, 'So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, "O caravan, indeed you are thieves."', 'Maka ketika ia membekalkan mereka dengan bekalan makan (yang mencukupi keperluan) mereka, lalu ia meletakkan bijana minuman raja di kenderaan saudaranya (Bunyamin), kemudian menyeru seorang penyeru: “Wahai orang-orang kafilah ini, sesungguhnya kamu adalah pencuri”.', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 71, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', 'قَالُوا وَأَقْبَلُوا عَلَيْهِم مَّاذَا تَفْقِدُونَ', NULL, 'They said while approaching them, "What is it you are missing?"', 'Mereka bertanya sambil mengadap ke arah orang-orang menteri yang menuduh itu: “Apa benda kamu yang kehilangan?”', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 72, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ', 'قَالُوا نَفْقِدُ صُوَاعَ الْمَلِكِ وَلِمَن جَاءَ بِهِ حِمْلُ بَعِيرٍ وَأَنَا بِهِ زَعِيمٌ', NULL, 'They said, "We are missing the measure of the king. And for he who produces it is [the reward of] a camel''s load, and I am responsible for it."', 'Orang-orang menteri menjawab: “Kami kehilangan cupak raja. Dan sesiapa yang memulangkannya akan diberi (benda-benda makanan) sebanyak muatan seekor unta, dan akulah yang menjamin pemberian itu”.', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 73, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 'قَالُوا تَاللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِي الْأَرْضِ وَمَا كُنَّا سَارِقِينَ', NULL, 'They said, "By Allāh, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves."', 'Mereka berkata: “Demi Allah! Sesungguhnya kamu sedia mengetahui bahawa kedatangan kami bukanlah untuk berbuat kerosakan di bumi (Mesir ini), dan kami pula bukanlah pencuri”.', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 74, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', 'قَالُوا فَمَا جَزَاؤُهُ إِن كُنتُمْ كَاذِبِينَ', NULL, 'They [the accusers] said, "Then what would be its recompense if you should be liars?"', '(Orang-orang menteri) bertanya: “Maka apa balasan pencuri itu, jika kamu berdusta?”', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 75, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'قَالُوا جَزَاؤُهُ مَن وُجِدَ فِي رَحْلِهِ فَهُوَ جَزَاؤُهُ كَذَٰلِكَ نَجْزِي الظَّالِمِينَ', NULL, '[The brothers] said, "Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers."', 'Mereka menjawab: “Balasannya: sesiapa yang didapati benda itu di kenderaannya, maka dia lah sendiri yang menjadi balasannya. Demikianlah kami membalas orang-orang yang zalim”.', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 76, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ', 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَاءِ أَخِيهِ ثُمَّ اسْتَخْرَجَهَا مِن وِعَاءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِي دِينِ الْمَلِكِ إِلَّا أَن يَشَاءَ اللَّهُ نَرْفَعُ دَرَجَاتٍ مَّن نَّشَاءُ وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ', NULL, 'So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion [i.e., law] of the king except that Allāh willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing.', 'Maka Yusuf pun mulailah memeriksa tempat-tempat barang mereka sebelum memeriksa tempat barang saudara kandungnya (Bunyamin) kemudian ia mengeluarkan benda yang hilang itu dari tempat simpanan barang saudara kandungnya. Demikianlah Kami jayakan rancangan untuk (menyampaikan hajat) Yusuf. Tidaklah ia akan dapat mengambil saudara kandungnya menurut undang-undang raja, kecuali jika dikehendaki oleh Allah. (Dengan ilmu pengetahuan), Kami tinggikan pangkat kedudukan sesiapa yang Kami kehendaki, dan tiap-tiap orang yang berilmu pengetahuan, ada lagi di atasnya yang lebih mengetahui,', FALSE, NULL, NULL, 244, 13, 97, 201, FALSE, 0, NULL),
(12, 77, 'قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 'قَالُوا إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِي نَفْسِهِ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَاللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', NULL, 'They said, "If he steals - a brother of his has stolen before." But Joseph kept it within himself and did not reveal it to them. He said, "You are worse in position, and Allāh is most knowing of what you describe."', 'Mereka berkata: “Kalau dia mencuri, maka (tidaklah pelik), kerana sesungguhnya saudara kandungnya pernah juga mencuri dahulu. (Mendengar kata-kata yang menyinggung itu) maka Yusuf pun menyembunyikan perasaannya, dan tidak menyatakannya kepada mereka, sambil berkata (dalam hati): “Kamulah yang lebih buruk keadaannya; dan Allah Maha Mengetahui akan apa yang kamu katakan itu”.', FALSE, NULL, NULL, 244, 13, 98, 201, FALSE, 0, NULL),
(12, 78, 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'قَالُوا يَا أَيُّهَا الْعَزِيزُ إِنَّ لَهُ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُ إِنَّا نَرَاكَ مِنَ الْمُحْسِنِينَ', NULL, 'They said, "O ʿAzeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good."', 'Merekapun merayu dengan berkata: “Wahai datuk menteri! Sesungguhnya ia (Bunyamin), mempunyai bapa yang sudah tua, lagi berpangkat. Oleh itu, ambilah salah seorang di antara kami sebagai gantinya; sesungguhnya kami memandangmu dari orang-orang yang sentiasa berbudi”.', FALSE, NULL, NULL, 244, 13, 98, 201, FALSE, 0, NULL),
(12, 79, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَٰلِمُونَ', 'قَالَ مَعَاذَ اللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَاعَنَا عِندَهُ إِنَّا إِذًا لَّظَالِمُونَ', NULL, 'He said, "[I seek] the refuge of Allāh [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust."', 'Yusuf berkata: “Kami berlindung kepada Allah daripada mengambil sesiapapun kecuali orang yang kami dapati barang kami dalam simpanannya. Sesungguhnya jika kami mengambil orang lain, nescaya menjadilah kami orang-orang yang zalim”.', FALSE, NULL, NULL, 245, 13, 98, 201, FALSE, 0, NULL),
(12, 80, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'فَلَمَّا اسْتَيْأَسُوا مِنْهُ خَلَصُوا نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوا أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ اللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِي يُوسُفَ فَلَنْ أَبْرَحَ الْأَرْضَ حَتَّىٰ يَأْذَنَ لِي أَبِي أَوْ يَحْكُمَ اللَّهُ لِي وَهُوَ خَيْرُ الْحَاكِمِينَ', NULL, 'So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, "Do you not know that your father has taken upon you an oath by Allāh and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allāh decides for me, and He is the best of judges.', 'Maka apabila mereka berputus asa daripada mendapat pertolongannya, merekapun mengasingkan diri lalu bermesyuarat tentang hal itu. Berkatalah ketua mereka (saudaranya yang sulung): “Tidakkah kamu ketahui bahawa bapa kita telah mengambil janji dari kamu yang dikuatkan dengan nama Allah, dan dahulu pun kamu telah mencuaikan janji dan sumpah kamu dalam perkara menjaga keselamatan Yusuf? Oleh itu, aku tidak sekali-kali akan meninggalkan negeri (Mesir) ini sehingga bapaku izinkan aku (kembali atau sehingga Allah menghukum bagiku (untuk meninggalkan negeri ini), dan Dia lah Hakim yang seadil-adilnya.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 81, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 'ارْجِعُوا إِلَىٰ أَبِيكُمْ فَقُولُوا يَا أَبَانَا إِنَّ ابْنَكَ سَرَقَ وَمَا شَهِدْنَا إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَافِظِينَ', NULL, 'Return to your father and say, ''O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen.', 'Kembalilah kamu kepada bapa kamu, dan katakanlah, wahai ayah kami! Sesungguhnya anakmu (Bunyamin) telah mencuri, dan kami tidak menjadi saksi (terhadapnya) melainkan dengan apa yang kami ketahui dan kami tidaklah dapat menjaga perkara yang ghaib.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 82, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ', 'وَاسْأَلِ الْقَرْيَةَ الَّتِي كُنَّا فِيهَا وَالْعِيرَ الَّتِي أَقْبَلْنَا فِيهَا وَإِنَّا لَصَادِقُونَ', NULL, 'And ask the city in which we were and the caravan in which we came - and indeed, we are truthful.''"', 'Dan bertanyalah kepada penduduk negeri (Mesir) tempat kami tinggal (berdagang) dan kepada orang-orang kafilah yang kami balik bersamanya. Sesungguhnya kami adalah orang-orang yang benar”.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى اللَّهُ أَن يَأْتِيَنِي بِهِمْ جَمِيعًا إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ', NULL, '[Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allāh will bring them to me all together. Indeed, it is He who is the Knowing, the Wise."', '(Setelah mereka kembali dan menyampaikan hal itu kepada bapa mereka) berkatalah ia: “(Tidaklah benar apa yang kamu katakan itu) bahkan nafsu kamu telah memperelokkan pada pandangan kamu suatu perkara (yang kamu rancangkan). Jika demikian, bersabarlah aku dengan sebaik-baiknya, mudah-mudahan Allah mengembalikan mereka semua kepadaku. Sesungguhnya Dia lah jua Yang Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 84, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ', 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا أَسَفَىٰ عَلَىٰ يُوسُفَ وَابْيَضَّتْ عَيْنَاهُ مِنَ الْحُزْنِ فَهُوَ كَظِيمٌ', NULL, 'And he turned away from them and said, "Oh, my sorrow over Joseph," and his eyes became white from grief, for he was [of that] a suppressor.', 'Dan (bapa mereka - Nabi Yaakub) pun berpaling dari mereka (kerana berita yang mengharukan itu) sambil berkata: Aduhai sedihnya aku kerana Yusuf, dan putihlah dua belah matanya disebabkan ratap tangis dukacitanya kerana ia orang yang memendamkan marahnya di dalam hati.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 85, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 'قَالُوا تَاللَّهِ تَفْتَأُ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ الْهَالِكِينَ', NULL, 'They said, "By Allāh, you will not cease remembering Joseph until you become fatally ill or become of those who perish."', 'Mereka berkata: “Demi Allah, ayah tak habis-habis ingat kepada Yusuf, sehingga ayah menjadi sakit merana, atau menjadi dari orang-orang yang binasa”.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 86, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'قَالَ إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ وَأَعْلَمُ مِنَ اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'He said, "I only complain of my suffering and my grief to Allāh, and I know from Allāh that which you do not know.', '(Nabi Yaakub) menjawab: “Sesungguhnya aku hanyalah mengadukan kesusahan dan dukacitaku kepada Allah dan aku mengetahui (dengan perantaraan wahyu) dari Allah, apa yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 245, 13, 98, 202, FALSE, 0, NULL),
(12, 87, 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', 'يَا بَنِيَّ اذْهَبُوا فَتَحَسَّسُوا مِن يُوسُفَ وَأَخِيهِ وَلَا تَيْأَسُوا مِن رَّوْحِ اللَّهِ إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ', NULL, 'O my sons, go and find out about Joseph and his brother and despair not of relief from Allāh. Indeed, no one despairs of relief from Allāh except the disbelieving people."', 'Wahai anak-anakku! Pergilah dan intiplah khabar berita mengenai Yusuf dan saudaranya (Bunyamin), dan janganlah kamu berputus asa dari rahmat serta pertolongan Allah. Sesungguhnya tidak berputus asa dari rahmat dan pertolongan Allah itu melainkan kaum yang kafir”.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 88, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', 'فَلَمَّا دَخَلُوا عَلَيْهِ قَالُوا يَا أَيُّهَا الْعَزِيزُ مَسَّنَا وَأَهْلَنَا الضُّرُّ وَجِئْنَا بِبِضَاعَةٍ مُّزْجَاةٍ فَأَوْفِ لَنَا الْكَيْلَ وَتَصَدَّقْ عَلَيْنَا إِنَّ اللَّهَ يَجْزِي الْمُتَصَدِّقِينَ', NULL, 'So when they entered upon him [i.e., Joseph], they said, "O ʿAzeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allāh rewards the charitable."', 'Maka (bertolaklah mereka ke Mesir, dan) setelah mereka masuk mengadap Yusuf, berkatalah mereka: “Wahai Datuk Menteri, kami dan keluarga kami telah menderita kesusahan (kemarau), dan kami datang dengan membawa barang-barang yang kurang baik dan tidak berharga (untuk menjadi tukaran bagi benda-benda makanan negeri ini). Oleh itu, sempurnakanlah sukatan bekalan makanan bagi kami dan mendermalah kepada kami, sesungguhnya Allah membalas dengan sebaik-baik balasan kepada orang-orang yang bermurah hati menderma”.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 89, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَاهِلُونَ', NULL, 'He said, "Do you know what you did with Joseph and his brother when you were ignorant?"', 'Yusuf berkata: “Tahukah kamu (betapa buruknya) apa yang kamu telah lakukan kepada Yusuf dan adiknya, semasa kamu masih jahil (tentang buruknya perbuatan yang demikian)?”', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 90, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'قَالُوا أَإِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا يُوسُفُ وَهَٰذَا أَخِي قَدْ مَنَّ اللَّهُ عَلَيْنَا إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ', NULL, 'They said, "Are you indeed Joseph?" He said, "I am Joseph, and this is my brother. Allāh has certainly favored us. Indeed, he who fears Allāh and is patient, then indeed, Allāh does not allow to be lost the reward of those who do good."', 'Mereka bertanya (dengan hairan): “Engkau ini Yusufkah?” Ia menjawab: “Akulah Yusuf dan ini adikku (Bunyamin). Sesungguhnya Allah telah mengurniakan nikmatNya kepada kami. Sebenarnya sesiapa yang bertaqwa dan bersabar, maka sesungguhnya Allah tidak menghilangkan pahala orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 91, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'قَالُوا تَاللَّهِ لَقَدْ آثَرَكَ اللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَاطِئِينَ', NULL, 'They said, "By Allāh, certainly has Allāh preferred you over us, and indeed, we have been sinners."', 'Mereka berkata: “Demi Allah! Sesungguhnya Allah telah melebihkan dan memuliakan engkau daripada kami (disebabkan taqwa dan kesabaranmu); dan sesungguhnya kami adalah orang-orang yang bersalah”.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 92, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ يَغْفِرُ ٱللَّهُ لَكُمْ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ', NULL, 'He said, "No blame will there be upon you today. May Allāh forgive you; and He is the most merciful of the merciful.', 'Yusuf berkata: “Kamu pada hari ini tidak akan ditempelak atau disalahkan (tentang perbuatan kamu yang telah terlanjur itu), semoga Allah mengampunkan dosa kamu, dan Dia lah jua Yang Maha Mengasihani daripada segala yang lain yang mengasihani.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 93, 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', 'اذْهَبُوا بِقَمِيصِي هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِي يَأْتِ بَصِيرًا وَأْتُونِي بِأَهْلِكُمْ أَجْمَعِينَ', NULL, 'Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together."', 'Pergilah dengan membawa bajuku ini, kemudian letakkan pada muka ayahku supaya ia dapat melihat, dan selepas itu bawalah kepadaku keluarga kamu semuanya”.', FALSE, NULL, NULL, 246, 13, 98, 202, FALSE, 0, NULL),
(12, 94, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ', 'وَلَمَّا فَصَلَتِ الْعِيرُ قَالَ أَبُوهُمْ إِنِّي لَأَجِدُ رِيحَ يُوسُفَ لَوْلَا أَن تُفَنِّدُونِ', NULL, 'And when the caravan departed [from Egypt], their father said, "Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind."', 'Dan semasa kafilah (mereka meninggalkan Mesir menuju ke tempat bapa mereka di Palestin), berkatalah bapa mereka (kepada kaum kerabatnya yang ada di sisinya): “Sesungguhnya aku ada terbau akan bau Yusuf. Jika kamu tidak menyangka aku sudah nyanyuk (tentulah kamu akan percaya)”.', FALSE, NULL, NULL, 246, 13, 98, 203, FALSE, 0, NULL),
(12, 95, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', 'قَالُوا تَاللَّهِ إِنَّكَ لَفِي ضَلَالِكَ الْقَدِيمِ', NULL, 'They said, "By Allāh, indeed you are in your [same] old error."', 'Mereka berkata: “Demi Allah! Sesungguhnya ayah masih berada dalam keadaan tidak siumanmu yang lama”.', FALSE, NULL, NULL, 246, 13, 98, 203, FALSE, 0, NULL),
(12, 96, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'فَلَمَّا أَن جَاءَ الْبَشِيرُ أَلْقَاهُ عَلَىٰ وَجْهِهِ فَارْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّي أَعْلَمُ مِنَ اللَّهِ مَا لَا تَعْلَمُونَ', NULL, 'And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, "Did I not tell you that I know from Allāh that which you do not know?"', 'Maka sebaik-baik sahaja datang pembawa khabar berita yang mengembirakan itu, dia pun meletakkan baju Yusuf pada muka Nabi Yaakub, lalu menjadilah ia celik kembali seperti sediakala. Nabi Yaakub berkata: “Bukankah aku telah katakan kepada kamu, sesungguhnya aku mengetahui (dengan perantaraan wahyu) dari Allah akan apa yang kamu tidak mengetahuinya?”', FALSE, NULL, NULL, 247, 13, 98, 203, FALSE, 0, NULL),
(12, 97, 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', 'قَالُوا يَا أَبَانَا اسْتَغْفِرْ لَنَا ذُنُوبَنَا إِنَّا كُنَّا خَاطِئِينَ', NULL, 'They said, "O our father, ask for us forgiveness of our sins; indeed, we have been sinners."', 'Mereka berkata: “Wahai ayah kami! Mintalah ampun bagi kami akan dosa-dosa kami; sesungguhnya kami adalah orang-orang yang bersalah”.', FALSE, NULL, NULL, 247, 13, 98, 203, FALSE, 0, NULL),
(12, 98, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّي إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ', NULL, 'He said, "I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful."', 'Nabi Yaakub berkata: “Aku akan meminta ampun bagi kamu dari Tuhanku; sesungguhnya Dia lah jua Yang Maha Pengampun, lagi Maha Mengasihani”.', FALSE, NULL, NULL, 247, 13, 98, 203, FALSE, 0, NULL),
(12, 99, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', 'فَلَمَّا دَخَلُوا عَلَىٰ يُوسُفَ آوَىٰ إِلَيْهِ أَبَوَيْهِ وَقَالَ ادْخُلُوا مِصْرَ إِن شَاءَ اللَّهُ آمِنِينَ', NULL, 'And when they entered upon Joseph, he took his parents to himself [i.e., embraced them] and said, "Enter Egypt, Allāh willing, safe [and secure]."', 'Maka ketika mereka (Nabi Yaakub dan keluarganya) masuk (ke Mesir) menemui Yusuf, Yusuf segera menyambut serta memeluk kedua ibu bapanya, sambil berkata: “Masuklah kamu ke negeri Mesir, insya Allah kamu berada di dalam aman.', FALSE, NULL, NULL, 247, 13, 98, 203, FALSE, 0, NULL),
(12, 100, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّدًا وَقَالَ يَا أَبَتِ هَٰذَا تَأْوِيلُ رُؤْيَايَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّي حَقًّا وَقَدْ أَحْسَنَ بِي إِذْ أَخْرَجَنِي مِنَ السِّجْنِ وَجَاءَ بِكُم مِّنَ الْبَدْوِ مِن بَعْدِ أَن نَّزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي إِنَّ رَبِّي لَطِيفٌ لِّمَا يَشَاءُ إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ', NULL, 'And he raised his parents upon the throne, and they bowed to him in prostration. And he said, "O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise.', 'Dan ia dudukkan kedua ibu bapanya (bersama-samanya) di atas kerusi kebesaran. Dan setelah itu mereka semuanya tunduk memberi hormat kepada Yusuf. Dan (pada saat itu) berkatalah Yusuf: “Wahai ayahku! Inilah dia tafsiran mimpiku dahulu. Sesungguhnya Allah telah menjadikan mimpiku itu benar. Dan sesungguhnya Ia telah melimpahkan kebaikan kepadaku ketika Ia mengeluarkan daku dari penjara; dan Ia membawa kamu ke mari dari dosa sesudah Syaitan (dengan hasutannya) merosakkan perhubungan antaraku dengan saudara-saudaraku. Sesungguhnya Tuhanku lemah-lembut tadbirNya bagi apa yang dikehendakiNya; sesungguhnya Dia lah yang Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 247, 13, 98, 203, FALSE, 0, NULL),
(12, 101, 'رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ وَعَلَّمْتَنِي مِن تَأْوِيلِ الْأَحَادِيثِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ', NULL, 'My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and the Hereafter. Cause me to die a Muslim and join me with the righteous."', '“Wahai Tuhanku! Sesungguhnya Engkau telah mengurniakan daku sebahagian dari kekuasaan (pemerintahan) dan mengajarku sebahagian dari ilmu tafsiran mimpi. Wahai Tuhan yang menciptakan langit dan bumi Engkau Penguasa dan Pelindungku di dunia dan di akhirat; sempurnakanlah ajalku (ketika mati) dalam keadaan Islam, dan hubungkanlah daku dengan orang-orang yang soleh”.', FALSE, NULL, NULL, 247, 13, 99, 203, FALSE, 0, NULL),
(12, 102, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'ذَٰلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوا أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', NULL, 'That is from the news of the unseen which We reveal, [O Muḥammad], to you. And you were not with them when they put together their plan while they conspired.', '(Kisah nabi Yusuf) yang demikian ialah dari berita-berita yang ghaib yang kami wahyukan kepadamu (wahai Muhammad), sedang engkau tidak ada bersama-sama mereka semasa mereka sekata mengambil keputusan (hendak membuang Yusuf ke dalam perigi) dan semasa mereka menjalankan rancangan jahat (terhadapnya untuk membinasakannya).', FALSE, NULL, NULL, 247, 13, 99, 203, FALSE, 0, NULL),
(12, 103, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', 'وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', NULL, 'And most of the people, although you strive [for it], are not believers.', 'Dan kebanyakan manusia tidak akan beriman walaupun engkau terlalu ingin (supaya mereka beriman).', FALSE, NULL, NULL, 247, 13, 99, 203, FALSE, 0, NULL),
(12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'وَمَا تَسْأَلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ', NULL, 'And you do not ask of them for it any payment. It is not except a reminder to the worlds.', 'Padahal engkau tidak meminta kepada mereka sebarang upah tentang ajaran Al-Quran, sedang Al-Quran itu tidak lain hanyalah peringatan dan pengajaran dari Allah bagi umat manusia seluruhnya.', FALSE, NULL, NULL, 248, 13, 99, 203, FALSE, 0, NULL),
(12, 105, 'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'وَكَأَيِّن مِّنْ آيَةٍ فِي السَّمَاوَاتِ وَالْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', NULL, 'And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away.', 'Dan berapa banyak tanda-tanda kekuasaan Allah di langit dan di bumi yang mereka menyaksikannya berulang-ulang semasa mereka pergi dan datang, sedang mereka tidak juga menghiraukan dan memikirkannya.', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 106, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', NULL, 'And most of them believe not in Allāh except while they associate others with Him.', 'Dan (orang-orang yang beriman kepada Allah), kebanyakan mereka tidak beriman kepada Allah melainkan mereka mempersekutukannya juga dengan yang lain.', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 107, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'أَفَأَمِنُوا أَن تَأْتِيَهُمْ غَاشِيَةٌ مِّنْ عَذَابِ اللَّهِ أَوْ تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', NULL, 'Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allāh or that the Hour will not come upon them suddenly while they do not perceive?', '(Mengapa mereka bersikap demikian?) Adakah mereka merasa aman dari didatangi azab Allah yang meliputi mereka, atau didatangi hari kiamat secara mengejut, sedang mereka tidak menyedarinya?', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 108, 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'قُلْ هَٰذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي وَسُبْحَانَ اللَّهِ وَمَا أَنَا مِنَ الْمُشْرِكِينَ', NULL, 'Say, "This is my way; I invite to Allāh with insight, I and those who follow me. And exalted is Allāh; and I am not of those who associate others with Him."', 'Katakanlah (wahai Muhammad): “Inilah jalanku, aku dan orang-orang yang menurutku, menyeru manusia umumnya kepada ugama Allah dengan berdasarkan keterangan dan bukti yang jelas nyata. Dan aku menegaskan: Maha suci Allah (dari segala iktiqad dan perbuatan syirik); dan bukanlah aku dari golongan yang mempersekutukan Allah dengan sesuatu yang lain.”', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 109, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ أَفَلَا تَعْقِلُونَ', 'وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم مِّنْ أَهْلِ الْقُرَىٰ أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ الْآخِرَةِ خَيْرٌ لِّلَّذِينَ اتَّقَوْا أَفَلَا تَعْقِلُونَ', NULL, 'And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allāh; then will you not reason?', 'Dan tiadalah Kami mengutus Rasul - sebelummu (wahai Muhammad) melainkan orang-orang lelaki dari penduduk bandar, yang kami wahyukan kepada mereka. Maka mengapa orang-orang (yang tidak mahu beriman) itu tidak mengembara di muka bumi, supaya memerhatikan bagaimana akibat orang-orang kafir yang terdahulu dari mereka? Dan (ingatlah) sesungguhnya negeri akhirat lebih baik bagi orang-orang yang bertaqwa. Oleh itu, mengapa kamu (wahai manusia) tidak mahu memikirkannya?', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 110, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'حَتَّىٰ إِذَا اسْتَيْأَسَ الرُّسُلُ وَظَنُّوا أَنَّهُمْ قَدْ كُذِبُوا جَاءَهُمْ نَصْرُنَا فَنُجِّيَ مَن نَّشَاءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ الْقَوْمِ الْمُجْرِمِينَ', NULL, '[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals.', '(Orang-orang yang mendustakan ugama Allah itu telah diberi tempoh yang lanjut sebelum ditimpakan dengan azab) hingga apabila Rasul-rasul berputus asa terhadap kaumnya yang ingkar dan menyangka bahawa mereka telah disifatkan oleh kaumnya sebagai orang-orang yang berdusta, datanglah pertolongan Kami kepada mereka, lalu diselamatkanlah sesiapa yang Kami kehendaki. Dan (ingatlah bahawa) azab Kami tidak akan dapat ditolak oleh sesiapapun daripada menimpa kaum yang berdosa.', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(12, 111, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَٰبِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَةٌ لِّأُولِي الْأَلْبَابِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'There was certainly in their stories a lesson for those of understanding. Never was it [i.e., the Qur’ān] a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.', 'Demi sesungguhnya, kisah Nabi-nabi itu mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang mempunyai akal fikiran. (Kisah Nabi-nabi yang terkandung dalam Al-Quran) bukanlah ia cerita-cerita yang diada-adakan, tetapi ia mengesahkan apa yang tersebut di dalam Kitab-kitab ugama yang terdahulu daripadanya, dan ia sebagai keterangan yang menjelaskan tiap-tiap sesuatu, serta menjadi hidayah petunjuk dan rahmat bagi kaum yang (mahu) beriman.', FALSE, NULL, NULL, 248, 13, 99, 204, FALSE, 0, NULL),
(13, 1, 'الٓمٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ۗ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'المر تلك ايات الكتاب والذي انزل اليك من ربك الحق ولكن اكثر الناس لا يؤمنون', NULL, 'Alif, Lām, Meem, Rā. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.', 'Alif, Laam, Miim, Raa''. Ini ialah ayat-ayat Kitab (Al-Quran); dan apa yang diturunkan kepadamu (wahai Muhammad) dari Tuhanmu adalah benar; tetapi kebanyakan manusia tidak (mahu) beriman.', FALSE, NULL, NULL, 249, 13, 99, 205, FALSE, 15, NULL),
(13, 2, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَـٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۚ يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْـَٔايَـٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 'الله الذي رفع السماوات بغير عمد ترونها ثم استوى على العرش وسخر الشمس والقمر كل يجري لاجل مسمى يدبر الامر يفصل الايات لعلكم بلقاء ربكم توقنون', NULL, 'It is Allāh who erected the heavens without pillars that you [can] see; then He established Himself above the Throne and made subject the sun and the moon, each running [its course] for a specified term. He arranges [each] matter; He details the signs that you may, of the meeting with your Lord, be certain.', 'Allah jualah yang menjadikan langit terangkat tinggi dengan tiada bertiang sebagaimana yang kamu melihatnya, kemudian Ia bersemayam di atas Arasy; dan Ia memudahkan matahari dan bulan (untuk faedah makhluk-makhlukNya) tiap-tiap satu dari keduanya beredar untuk suatu masa yang telah ditetapkan. Allah jualah yang mentadbirkan segala urusan; Ia menerangkan tanda-tanda kekuasaanNya satu-persatu, supaya kamu yakin kepada pertemuan Tuhan kamu (untuk menerima balasan).', FALSE, NULL, NULL, 249, 13, 99, 205, FALSE, 26, NULL),
(13, 3, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَـٰرًا ۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ ۖ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'وهو الذي مد الارض وجعل فيها رواسي وانهارا ومن كل الثمرات جعل فيها زوجين اثنين يغشي الليل النهار ان في ذلك لايات لقوم يتفكرون', NULL, 'And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought.', 'Dan Dia lah yang menjadikan bumi terbentang luas, dan menjadikan padanya gunung-ganang (terdiri kukuh) serta sungai-sungai (yang mengalir). Dan dari tiap-tiap jenis buah-buahan, Ia jadikan padanya pasangan: dua-dua. Ia juga melindungi siang dengan malam silih berganti. Sesungguhnya semuanya itu mengandungi tanda-tanda kekuasaan Allah bagi kaum yang (mahu) berfikir.', FALSE, NULL, NULL, 249, 13, 99, 205, FALSE, 24, NULL),
(13, 4, 'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَـٰوِرَٰتٌ وَجَنَّـٰتٌ مِّنْ أَعْنَـٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'وفي الارض قطع متجاورات وجنات من اعناب وزرع ونخيل صنوان وغير صنوان يسقى بماء واحد ونفضل بعضها على بعض في الاكل ان في ذلك لايات لقوم يعقلون', NULL, 'And within the land are neighboring plots and gardens of grapevines and crops and palm trees, [growing] several from a root or otherwise, watered with one water; but We make some of them exceed others in [quality of] fruit. Indeed in that are signs for a people who reason.', 'Dan di bumi ada beberapa potong tanah yang berdekatan (tetapi berlainan keadaannya); dan padanya ada kebun-kebun anggur, dan jenis-jenis tanaman serta pohon-pohon tamar (kurma) yang berumpun dan yang tidak berumpun; semuanya disiram dengan air yang sama; dan Kami lebihkan buah setengahnya dari setengahnya yang lain (pada bentuk, rasa, dan baunya) Sesungguhnya yang demikian itu mengandungi tanda-tanda kekuasaan Allah bagi orang-orang yang (mahu) berfikir serta memahaminya.', FALSE, NULL, NULL, 249, 13, 99, 205, FALSE, 27, NULL),
(13, 5, '۞ وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ ٱلْأَغْلَـٰلُ فِىٓ أَعْنَاقِهِمْ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', 'وان تعجب فعجب قولهم ااذا كنا ترابا اانا لفي خلق جديد اولئك الذين كفروا بربهم واولئك الاغلال في اعناقهم واولئك اصحاب النار هم فيها خالدون', NULL, 'And if you are astonished, [O Muḥammad] - then astonishing is their saying, "When we are dust, will we indeed be [brought] into a new creation?" Those are the ones who have disbelieved in their Lord, and those will have shackles upon their necks, and those are the companions of the Fire; they will abide therein eternally.', 'Dan jika engkau merasa hairan (wahai Muhammad), maka sungguh menghairankan perkataan mereka yang kafir itu (yang mengatakan): “Adalah apabila kami telah menjadi tanah betulkah kami pula akan hidup semula dalam bentuk kejadian yang baharu?” Mereka itulah orang-orang yang kufur ingkar kepada Tuhan mereka, dan merekalah yang dibelenggu dengan belenggu-belenggu pada leher mereka; dan merekalah juga ahli neraka, mereka kekal di dalamnya.', FALSE, NULL, NULL, 249, 13, 100, 205, FALSE, 25, NULL),
(13, 6, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَـٰتُ ۗ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ ۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', 'ويستعجلونك بالسيئة قبل الحسنة وقد خلت من قبلهم المثلات وان ربك لذو مغفرة للناس على ظلمهم وان ربك لشديد العقاب', NULL, 'They impatiently urge you to bring about evil before good, while there has already occurred before them similar punishments [to what they demand]. And indeed, your Lord is the possessor of forgiveness for the people despite their wrongdoing, and indeed, your Lord is severe in penalty.', 'Dan mereka meminta kepadamu menyegerakan kedatangan perkara buruk (azab yang dijanjikan) sebelum mereka memohon kebaikan; padahal sesungguhnya telah berlaku sebelum mereka peristiwa-peristiwa azab yang telah menimpa orang-orang yang kafir seperti mereka. dan (ingatlah) sesungguhnya Tuhanmu Amat melimpah keampunanNya bagi manusia (yang bertaubat) terhadap kezaliman mereka, dan sesungguhnya Tuhanmu juga amatlah keras balasan azabNya (terhadap golongan yang tetap ingkar).', FALSE, NULL, NULL, 250, 13, 100, 205, FALSE, 20, NULL),
(13, 7, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ ۗ إِنَّمَآ أَنتَ مُنذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ', 'ويقول الذين كفروا لولا انزل عليه اية من ربه انما انت منذر ولكل قوم هاد', NULL, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" You are only a warner, and for every people is a guide.', 'Dan berkatalah orang-orang yang kafir: “Mengapa tidak diturunkan kepada (Muhammad) sesuatu mukjizat dari Tuhannya?” Sesungguhnya engkau (wahai Muhammad) hanyalah seorang Rasul pemberi amaran (kepada orang-orang yang ingkar), dan tiap-tiap umat (yang telah lalu) ada Nabinya yang memimpin ke jalan yang benar.', FALSE, NULL, NULL, 250, 13, 100, 205, FALSE, 15, NULL),
(13, 8, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', 'الله يعلم ما تحمل كل انثى وما تغيض الارحام وما تزداد وكل شيء عنده بمقدار', NULL, 'Allāh knows what every female carries and what the wombs lose [prematurely] or exceed. And everything with Him is by due measure.', 'Allah mengetahui akan apa yang dikandung oleh tiap-tiap ibu, dan mengetahui apa yang kurang dari yang dikandung dalam rahim itu atau yang lebih. Dan tiap-tiap sesuatu adalah ditetapkan di sisiNya dengan kadar yang tertentu.', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 15, NULL),
(13, 9, 'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', 'عالم الغيب والشهادة الكبير المتعال', NULL, '[He is] Knower of the unseen and the witnessed, the Grand, the Exalted.', 'Dia lah yang mengetahui perkara-perkara yang ghaib dan yang nyata; Dia lah jua Yang Maha Besar, lagi maha Tinggi (Yang mengatasi segala-galanya).', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 5, NULL),
(13, 10, 'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', 'سواء منكم من اسر القول ومن جهر به ومن هو مستخف بالليل وسارب بالنهار', NULL, 'It is the same [to Him] concerning you whether one conceals [his] speech or publicizes it and whether one is hidden by night or conspicuous [among others] by day.', 'Sama sahaja kepadaNya: sesiapa di antara kamu yang merahsiakan kata-katanya dalam hati dan yang menyatakannya; juga yang bersembunyi pada waktu malam dan yang keluar berjalan pada waktu siang.', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 14, NULL),
(13, 11, 'لَهُۥ مُعَقِّبَـٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'له معقبات من بين يديه ومن خلفه يحفظونه من امر الله ان الله لا يغير ما بقوم حتى يغيروا ما بانفسهم واذا اراد الله بقوم سوءا فلا مرد له وما لهم من دونه من وال', NULL, 'For him [i.e., each one] are successive [angels] before and behind him who protect him by the decree of Allāh. Indeed, Allāh will not change the condition of a people until they change what is in themselves. And when Allāh intends for a people ill, there is no repelling it. And there is not for them besides Him any patron.', 'Bagi tiap-tiap seorang ada malaikat penjaganya silih berganti dari hadapannya dan dari belakangnya, yang mengawas dan menjaganya (dari sesuatu bahaya) dengan perintah Allah. Sesungguhnya Allah tidak mengubah apa yang ada pada sesuatu kaum sehingga mereka mengubah apa yang ada pada diri mereka sendiri. Dan apabila Allah menghendaki untuk menimpakan kepada sesuatu kaum bala bencana (disebabkan kesalahan mereka sendiri), maka tiada sesiapapun yang dapat menolak atau menahan apa yang ditetapkanNya itu, dan tidak ada sesiapapun yang dapat menolong dan melindungi mereka selain daripadaNya.', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 35, NULL),
(13, 12, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', 'هو الذي يريكم البرق خوفا وطمعا وينشئ السحاب الثقال', NULL, 'It is He who shows you lightning, [causing] fear and aspiration, and generates the heavy clouds.', 'Dia lah yang memperlihatkan kilat kepada kamu, untuk menakutkan (dari panahan petir), dan memberi harapan (dengan turunnya hujan); dan Ia yang menjadikan awan tebal yang berat (dengan air).', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 9, NULL),
(13, 13, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَـٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَـٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', 'ويسبح الرعد بحمده والملائكة من خيفته ويرسل الصواعق فيصيب بها من يشاء وهم يجادلون في الله وهو شديد المحال', NULL, 'And the thunder exalts [Allāh] with praise of Him - and the angels [as well] from fear of Him - and He sends thunderbolts and strikes therewith whom He wills while they dispute about Allāh; and He is severe in assault.', 'Dan Dia lah juga yang guruh dan malaikat bertasbih memujiNya, kerana takut kepadaNya. Dan Dia lah juga yang menghantarkan petir, lalu Ia mengenakan dengan panahannya kepada sesiapa yang dikehendakinya Dan mereka yang ingkar itu membantah (serta mendustakan Rasul) mengenai perkara yang berhubung dengan Allah (dan kuat kuasaNya) Padahal Ia Amat keras azab seksanya.', FALSE, NULL, NULL, 250, 13, 100, 206, FALSE, 19, NULL),
(13, 14, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَـٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَـٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَـٰفِرِينَ إِلَّا فِى ضَلَـٰلٍ', 'له دعوة الحق والذين يدعون من دونه لا يستجيبون لهم بشيء الا كباسط كفيه الى الماء ليبلغ فاه وما هو ببالغه وما دعاء الكافرين الا في ضلال', NULL, 'To Him [alone] is the supplication of truth. And those they call upon besides Him do not respond to them with a thing, except as one who stretches his hands toward water [from afar, calling it] to reach his mouth, but it will not reach it [thus]. And the supplication of the disbelievers is not but in error [i.e., futility].', 'Kuasa menerima ibadat yang benar adalah tertentu bagi Allah; dan benda-benda yang mereka sembah yang lain dari Allah, tidak akan dapat menyahut atau memberikan sesuatupun kepada mereka, hanyalah seperti orang yang membentangkan kedua tapak tangannya kepada air supaya sampai ke mulutnya, padahal air itu sudah tentu tidak akan sampai kepadanya. Dan tiadalah ibadat dan doa permohonan orang-orang kafir itu melainkan dalam kesesatan.', FALSE, NULL, NULL, 251, 13, 100, 206, FALSE, 27, NULL),
(13, 15, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَـٰلُهُم بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ ۩', 'ولله يسجد من في السماوات والارض طوعا وكرها وظلالهم بالغدو والاصال', NULL, 'And to Allāh prostrates whoever is within the heavens and the earth, willingly or by compulsion, and their shadows [as well] in the mornings and the afternoons.', 'Dan kepada Allah jualah sekalian makhluk yang ada di langit dan di bumi tunduk menurut, sama ada dengan sukarela atau dengan terpaksa; dan (demikian juga) bayang-bayang mereka; pada waktu pagi dan petang.', FALSE, NULL, NULL, 251, 13, 100, 206, TRUE, 11, NULL),
(13, 16, 'قُلْ مَن رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ ۚ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَـٰتُ وَٱلنُّورُ ۗ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَـٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ ۚ قُلِ ٱللَّهُ خَـٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّـٰرُ', 'قل من رب السماوات والارض قل الله قل افاتخذتم من دونه اولياء لا يملكون لانفسهم نفعا ولا ضرا قل هل يستوي الاعمى والبصير ام هل تستوي الظلمات والنور ام جعلوا لله شركاء خلقوا كخلقه فتشابه الخلق عليهم قل الله خالق كل شيء وهو الواحد القهار', NULL, 'Say, "Who is Lord of the heavens and earth?" Say, "Allāh." Say, "Have you then taken besides Him allies not possessing [even] for themselves any benefit or any harm?" Say, "Is the blind equivalent to the seeing? Or is darkness equivalent to light? Or have they attributed to Allāh partners who created like His creation so that the creation [of each] seemed similar to them?" Say, "Allāh is the Creator of all things, and He is the One, the Prevailing."', 'Bertanyalah (wahai Muhammad): “Siapakah Tuhan yang memelihara dan mentadbirkan langit dan bumi?” Jawablah: “Allah”. Bertanyalah lagi: “Kalau demikian, patutkah kamu menjadikan benda-benda yang lain dari Allah sebagai Pelindung dan Penolong, yang tidak dapat mendatangkan sebarang manfaat bagi dirinya sendiri, dan tidak dapat menolak sesuatu bahaya?” Bertanyalah lagi: “Adakah sama, orang yang buta dengan orang yang celik? Atau adakah sama, gelap-gelita dengan terang? Atau adakah makhluk-makhluk yang mereka jadikan sekutu bagi Allah itu telah mencipta sesuatu seperti ciptaanNya, sehingga ciptaan-ciptaan itu menjadi kesamaran kepada mereka?” Katakanlah: “Allah jualah yang menciptakan tiap-tiap sesuatu, dan Dia lah Yang Maha Esa, lagi Maha Kuasa”.', FALSE, NULL, NULL, 251, 13, 100, 206, FALSE, 45, NULL),
(13, 17, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا ۚ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَـٰعٍ زَبَدٌ مِّثْلُهُۥ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَـٰطِلَ ۚ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً ۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 'انزل من السماء ماء فسالت اودية بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار ابتغاء حلية او متاع زبد مثله كذلك يضرب الله الحق والباطل فاما الزبد فيذهب جفاء واما ما ينفع الناس فيمكث في الارض كذلك يضرب الله الامثال', NULL, 'He sends down from the sky, rain, and valleys flow according to their capacity, and the torrent carries a rising foam. And from that [ore] which they heat in the fire, desiring adornments and utensils, is a foam like it. Thus Allāh presents [the example of] truth and falsehood. As for the foam, it vanishes, [being] cast off; but as for that which benefits the people, it remains on the earth. Thus does Allāh present examples.', 'Ia menurunkan air (hujan) dari langit, lalu membanjiri tanah-tanah lembah (dengan airnya) menurut kadarnya yang ditetapkan Tuhan untuk faedah makhlukNya, kemudian banjir itu membawa buih yang terapung-apung. Dan dari benda-benda yang dibakar di dalam api untuk dijadikan barang perhiasan atau perkakas yang diperlukan, juga timbul buih seperti itu. Demikianlah Allah memberi misal perbandingan tentang perkara yang benar dan yang salah. Adapun buih itu maka akan hilang lenyaplah ia hanyut terbuang, manakala benda-benda yang berfaedah kepada manusia maka ia tetap tinggal di bumi. Demikianlah Allah menerangkan misal-misal perbandingan.', FALSE, NULL, NULL, 251, 13, 100, 206, FALSE, 42, NULL),
(13, 18, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ ۚ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ ۚ أُو۟لَـٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمِهَادُ', 'للذين استجابوا لربهم الحسنى والذين لم يستجيبوا له لو ان لهم ما في الارض جميعا ومثله معه لافتدوا به اولئك لهم سوء الحساب وماواهم جهنم وبئس المهاد', NULL, 'For those who have responded to their Lord is the best [reward], but those who did not respond to Him - if they had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby. Those will have the worst account, and their refuge is Hell, and wretched is the resting place.', 'Bagi orang-orang yang menyahut seruan Tuhan mereka sahajalah balasan yang sebaik-baiknya; dan orang-orang yang ingkar yang tidak menyahut seruanNya, kalaulah mereka mempunyai segala apa jua yang ada di bumi disertai dengan sebanyak itu lagi, tentulah mereka rela menebus diri dengannya. mereka itu disediakan baginya hitungan hisab yang seburuk-buruknya, serta tempat kembali mereka ialah neraka jahanam; dan amatlah buruknya tempat tinggal itu.', FALSE, NULL, NULL, 251, 13, 100, 206, FALSE, 27, NULL),
(13, 19, '۞ أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', 'افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمى انما يتذكر اولو الالباب', NULL, 'Then is he who knows that what has been revealed to you from your Lord is the truth like one who is blind? They will only be reminded who are people of understanding -', 'Maka adakah orang yang mengetahui bahawa Al-Quran yang diturunkan kepadamu dari Tuhanmu itu (wahai Muhammad) perkara yang benar, sama dengan orang yang buta matahatinya? Sesungguhnya orang-orang yang mahu memikirkan hal itu hanyalah orang-orang yang berakal sempurna.', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 15, NULL),
(13, 20, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَـٰقَ', 'الذين يوفون بعهد الله ولا ينقضون الميثاق', NULL, 'Those who fulfill the covenant of Allāh and do not break the contract,', 'Orang-orang yang menyempurnakan perjanjian Allah dan tidak merombak (mencabuli) perjanjian yang telah diperteguhkan itu; -', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 7, NULL),
(13, 21, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', 'وَالَّذِينَ يَصِلُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ', NULL, 'And those who join that which Allāh has ordered to be joined and fear their Lord and are afraid of the evil of [their] account,', 'Dan orang-orang yang menghubungkan perkara-perkara yang disuruh oleh Allah supaya dihubungkan, dan yang menaruh bimbang akan kemurkaan Tuhan mereka, serta takut kepada kesukaran yang akan dihadapi semasa soaljawab dan hitungan amal (pada hari kiamat); -', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 22, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 'وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ أُولَٰئِكَ لَهُمْ عُقْبَى الدَّارِ', NULL, 'And those who are patient, seeking the face [i.e., acceptance] of their Lord, and establish prayer and spend from what We have provided for them secretly and publicly and prevent evil with good - those will have the good consequence of [this] home -', 'Dan orang-orang yang sabar kerana mengharapkan keredaan Tuhan mereka semata-mata, dan mendirikan sembahyang, serta mendermakan dari apa yang Kami kurniakan kepada mereka, secara bersembunyi atau secara terbuka; dan mereka pula menolak kejahatan dengan cara yang baik; mereka itu semuanya adalah disediakan baginya balasan yang sebaik-baiknya pada hari akhirat; -', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 23, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', NULL, 'Gardens of perpetual residence; they will enter them with whoever were righteous among their forefathers, their spouses and their descendants. And the angels will enter upon them from every gate, [saying],', 'Iaitu Syurga yang kekal yang mereka akan memasukinya bersama-sama orang-orang yang mengerjakan amal soleh dari ibu bapa mereka dan isteri-isteri mereka serta anak-anak mereka; sedang malaikat-malaikat pula akan masuk kepada mereka dari tiap-tiap pintu; -', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 24, 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى ٱلدَّارِ', 'سَلَامٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ', NULL, '"Peace [i.e., security] be upon you for what you patiently endured." And excellent is the final home.', '(Memberi hormat dengan berkata): “Selamat sejahteralah kamu berpanjangan, disebabkan kesabaran kamu. Maka amatlah baiknya balasan amal kamu di dunia dahulu.', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 25, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولَٰئِكَ لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ', NULL, 'But those who break the covenant of Allāh after contracting it and sever that which Allāh has ordered to be joined and spread corruption on earth - for them is the curse, and they will have the worst home.', 'Dan (sebaliknya) orang-orang yang merombak (mencabuli) perjanjian Allah sesudah diperteguhkannya dan memutuskan perkara-perkara yang disuruh oleh Allah supaya dihubungkan, serta mereka pula membuat kerosakan dan bencana di muka bumi, - mereka itu beroleh laknat, dan mereka pula beroleh balasan hari akhirat yang seburuk-buruknya.', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 26, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا مَتَٰعٌ', 'اللَّهُ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ وَفَرِحُوا بِالْحَيَاةِ الدُّنْيَا وَمَا الْحَيَاةُ الدُّنْيَا فِي الْآخِرَةِ إِلَّا مَتَاعٌ', NULL, 'Allāh extends provision for whom He wills and restricts [it]. And they rejoice in the worldly life, while the worldly life is not, compared to the Hereafter, except [brief] enjoyment.', 'Allah memewahkan rezeki bagi sesiapa yang dikehendakiNya, dan Ia juga yang menyempitkannya. Dan mereka (yang ingkar): bergembira dengan kehidupan dunia, sedang kehidupan dunia itu tidak lain, hanyalah kesenangan yang kecil dan tidak, kekal berbanding dengan kesenangan hari akhirat.', FALSE, NULL, NULL, 252, 13, 101, 207, FALSE, 0, NULL),
(13, 27, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', 'وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ قُلْ إِنَّ اللَّهَ يُضِلُّ مَن يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ', NULL, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" Say, [O Muḥammad], "Indeed, Allāh leaves astray whom He wills and guides to Himself whoever turns back [to Him] -', 'Dan orang-orang yang kafir berkata: “Mengapa tidak diturunkan kepada (Muhammad) satu mukjizat dari Tuhannya? “Katakanlah (wahai Muhammad): “Sesungguhnya Allah menyesatkan sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya), dan memberi petunjuk ke jalan ugamanya, sesiapa yang rujuk kepadaNya, -', FALSE, NULL, NULL, 252, 13, 101, 208, FALSE, 0, NULL),
(13, 28, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 'الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ اللَّهِ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ', NULL, 'Those who have believed and whose hearts are assured by the remembrance of Allāh. Unquestionably, by the remembrance of Allāh hearts are assured."', '“(Iaitu) orang-orang yang beriman dan tenang tenteram hati mereka dengan zikrullah”. Ketahuilah dengan “zikrullah” itu, tenang tenteramlah hati manusia.', FALSE, NULL, NULL, 252, 13, 101, 208, FALSE, 0, NULL),
(13, 29, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ', 'الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَآبٍ', NULL, 'Those who have believed and done righteous deeds - a good state is theirs and a good return.', 'Orang-orang yang beriman dan beramal soleh, beroleh kebahagiaan yang amat mengembirakan dan tempat kembali yang sebaik-baiknya.', FALSE, NULL, NULL, 253, 13, 101, 208, FALSE, 0, NULL),
(13, 30, 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', 'كَذَٰلِكَ أَرْسَلْنَاكَ فِي أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَا أُمَمٌ لِّتَتْلُوَ عَلَيْهِمُ الَّذِي أَوْحَيْنَا إِلَيْكَ وَهُمْ يَكْفُرُونَ بِالرَّحْمَٰنِ قُلْ هُوَ رَبِّي لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', NULL, 'Thus have We sent you to a community before which [other] communities have passed on so you might recite to them that which We revealed to you, while they disbelieve in the Most Merciful. Say, "He is my Lord; there is no deity except Him. Upon Him I rely, and to Him is my return."', 'Demikianlah, Kami utuskan engkau (wahai Muhammad) kepada satu umat yang telah lalu sebelumnya beberapa umat yang lain, supaya engkau membacakan kepada mereka Al-Quran yang Kami wahyukan kepadamu, sedang mereka kufur kepada (Allah) Ar-Rahman Katakanlah: “Dia lah Tuhanku, tiada Tuhan (yang berhak disembah) melainkan Dia. KepadaNyalah aku berserah diri, dan kepadaNyalah tempat kembaliku (dan kamu semuanya)”.', FALSE, NULL, NULL, 253, 13, 101, 208, FALSE, 0, NULL),
(13, 31, 'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'وَلَوْ أَنَّ قُرْآنًا سُيِّرَتْ بِهِ الْجِبَالُ أَوْ قُطِّعَتْ بِهِ الْأَرْضُ أَوْ كُلِّمَ بِهِ الْمَوْتَىٰ بَل لِّلَّهِ الْأَمْرُ جَمِيعًا أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا أَن لَّوْ يَشَاءُ اللَّهُ لَهَدَى النَّاسَ جَمِيعًا وَلَا يَزَالُ الَّذِينَ كَفَرُوا تُصِيبُهُم بِمَا صَنَعُوا قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِيَ وَعْدُ اللَّهِ إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ', NULL, 'And if there was any Qur’ān [i.e., recitation] by which the mountains would be removed or the earth would be broken apart or the dead would be made to speak, [it would be this Qur’ān], but to Allāh belongs the affair entirely. Then have those who believed not accepted that had Allāh willed, He would have guided the people, all of them? And those who disbelieve do not cease to be struck, for what they have done, by calamity - or it will descend near their home - until there comes the promise of Allāh. Indeed, Allāh does not fail in [His] promise.', 'Dan kalaulah ada mana-mana Kitab Suci yang dengan sebabnya gunung-ganang terbongkar bergerak dari tempatnya, atau dengan sebabnya bumi dipecah-belah mengeluarkan isi kandungannya, atau dengan sebabnya orang-orang yang telah mati dapat menjawab kata-kata yang dihadapkan kepadanya, maka Al-Quran ialah Kitab Suci yang mengandungi mukjizat. (Tetapi lahirnya sesuatu mukjizat itu adalah menurut kehendak Allah), bahkan segala urusan tertentu bagi Allah. Maka tidakkah orang-orang yang beriman mengetahui bahawa kalaulah Allah menghendaki tentulah Ia memberi petunjuk kepada umat manusia seluruhnya, (lalu menjadikan mereka semuanya beriman). Dan orang-orang yang kafir itu (dengan sebab kekufuran mereka) sentiasa ditimpa bala bencana (ke atas diri atau harta benda mereka); atau pun bala bencana itu turun menimpa tempat-tempat yang berhampiran dengan tempat tinggal mereka (lalu menjadikan mereka gempar kecemasan), sehinggalah datang janji Allah (hari kiamat dan azabnya); Sesungguhnya Allah tidak memungkiri janjiNya.', FALSE, NULL, NULL, 253, 13, 101, 208, FALSE, 0, NULL),
(13, 32, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', NULL, 'And already were [other] messengers ridiculed before you, and I extended the time of those who disbelieved; then I seized them, and how [terrible] was My penalty.', 'Dan sesungguhnya telahpun diejek-ejekkan Rasul-rasul yang diutus sebelummu (wahai Muhammad), lalu aku biarkan orang-orang yang tidak percayakan Rasul-rasul itu ke suatu masa yang tertentu, kemudian Aku menimpakan mereka dengan azab; maka tidaklah terperi seksanya azabKu itu.', FALSE, NULL, NULL, 253, 13, 101, 209, FALSE, 0, NULL),
(13, 33, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍ مِّنَ ٱلْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'أَفَمَنْ هُوَ قَائِمٌ عَلَىٰ كُلِّ نَفْسٍ بِمَا كَسَبَتْ وَجَعَلُوا لِلَّهِ شُرَكَاءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّئُونَهُ بِمَا لَا يَعْلَمُ فِي الْأَرْضِ أَم بِظَاهِرٍ مِّنَ الْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا مَكْرُهُمْ وَصُدُّوا عَنِ السَّبِيلِ وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ', NULL, 'Then is He who is a maintainer of every soul, [knowing] what it has earned, [like any other]? But to Allāh they have attributed partners. Say, "Name them. Or do you inform Him of that which He knows not upon the earth or of what is apparent [i.e., alleged] of speech?" Rather, their [own] plan has been made attractive to those who disbelieve, and they have been averted from the way. And whomever Allāh sends astray - there will be for him no guide.', 'Setelah diketahui demikian maka tidaklah patut disamakan Allah Tuhan yang berkuasa mengawas, tiap-tiap diri dan mengetahui akan apa yang telah diusahakan oleh diri-diri itu, (dengan makhluk yang tidak bersifat demikian). Dalam pada itu, mereka yang kafir telah menjadikan beberapa makhluk sebagai sekutu bagi Allah. Katakanlah (wahai Muhammad): “Namakanlah kamu akan mereka (yang kamu sembah itu). Atau adakah kamu hendak memberi tahu kepada Allah akan apa yang tidak diketahuiNya di bumi? Atau adakah kamu menamakannya dengan kata-kata yang lahir (sedang pada hakikatnya tidak demikian)?” Bahkan sebenarnya telah diperhiaskan oleh Iblis bagi orang-orang yang kafir itu akan kekufuran dan tipu daya mereka (terhadap Islam), dan mereka pula disekat oleh hawa nafsu mereka daripada menurut jalan yang benar. Dan (ingatlah) sesiapa yang disesatkan oleh Allah (dengan pilihannya yang salah) maka tidak ada sesiapapun yang dapat memberi hidayah petunjuk kepadanya.', FALSE, NULL, NULL, 253, 13, 101, 209, FALSE, 0, NULL),
(13, 34, 'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', 'لَّهُمْ عَذَابٌ فِي الْحَيَاةِ الدُّنْيَا وَلَعَذَابُ الْآخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ اللَّهِ مِن وَاقٍ', NULL, 'For them will be punishment in the life of [this] world, and the punishment of the Hereafter is more severe. And they will not have from Allāh any protector.', 'Mereka beroleh azab dalam kehidupan dunia, dan sesungguhnya azab hari akhirat lebih menyeksakan lagi; dan tiadalah bagi mereka, sesiapapun yang dapat melindungi mereka dari azab Allah itu.', FALSE, NULL, NULL, 253, 13, 101, 209, FALSE, 0, NULL),
(13, 35, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ أُكُلُهَا دَآئِمٌ وَظِلُّهَا تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', 'مَّثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ أُكُلُهَا دَائِمٌ وَظِلُّهَا تِلْكَ عُقْبَى الَّذِينَ اتَّقَوا وَّعُقْبَى الْكَافِرِينَ النَّارُ', NULL, 'The example [i.e., description] of Paradise, which the righteous have been promised, is [that] beneath it rivers flow. Its fruit is lasting, and its shade. That is the consequence for the righteous, and the consequence for the disbelievers is the Fire.', 'Sifat Syurga yang dijanjikan kepada orang-orang yang bertaqwa itu ialah air sungai-sungainya sentiasa mengalir di sekitar tamannya; makanannya kekal tidak putus-putus dan naungannya sentiasa teduh. Itulah kesudahan usaha orang-orang yang bertaqwa, sedang kesudahan usaha orang-orang yang kafir pula ialah neraka.', FALSE, NULL, NULL, 254, 13, 102, 209, FALSE, 0, NULL),
(13, 36, 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', 'وَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَفْرَحُونَ بِمَا أُنزِلَ إِلَيْكَ وَمِنَ الْأَحْزَابِ مَن يُنكِرُ بَعْضَهُ قُلْ إِنَّمَا أُمِرْتُ أَنْ أَعْبُدَ اللَّهَ وَلَا أُشْرِكَ بِهِ إِلَيْهِ أَدْعُو وَإِلَيْهِ مَآبِ', NULL, 'And [the believers among] those to whom We have given the [previous] Scripture rejoice at what has been revealed to you, [O Muḥammad], but among the [opposing] factions are those who deny part of it [i.e., the Qur’ān]. Say, "I have only been commanded to worship Allāh and not associate [anything] with Him. To Him I invite, and to Him is my return."', 'Dan orang-orang yang Kami berikan Kitab, mereka bersukacita dengan apa yang Kami turunkan kepadamu (wahai Muhammad) dan di antara beberapa kumpulan dari orang-orang itu ada yang mengingkari sebahagiannya. Katakanlah: “Sesungguhnya aku hanya diperintahkan supaya menyembah Allah, dan supaya aku tidak mempersekutukanNya dengan sesuatu yang lain: kepadaNyalah aku menyeru (manusia semuanya untuk menyembahNya), dan kepadaNyalah tempat kembaliku (dan kamu semuanya untuk menerima balasan)”.', FALSE, NULL, NULL, 254, 13, 102, 209, FALSE, 0, NULL),
(13, 37, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّا وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ', 'وَكَذَٰلِكَ أَنزَلْنَاهُ حُكْمًا عَرَبِيًّا وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم بَعْدَ مَا جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا وَاقٍ', NULL, 'And thus We have revealed it as an Arabic legislation. And if you should follow their inclinations after what has come to you of knowledge, you would not have against Allāh any ally or any protector.', 'Dan demikianlah Kami menurunkan Al-Quran sebagai hukum dalam bahasa Arab. Dan demi sesungguhnya, jika engkau (wahai Muhammad) menurut kehendak hawa nafsu mereka sesudah datangnya kepadamu wahyu pengetahuan (tentang kebenaran), maka tiadalah engkau peroleh dari Allah sesuatupun yang dapat mengawal dan memberi perlindungan kepadamu (dari perkara-perkara yang tidak diingini).', FALSE, NULL, NULL, 254, 13, 102, 209, FALSE, 0, NULL),
(13, 38, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ', 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ', NULL, 'And We have already sent messengers before you and assigned to them wives and descendants. And it was not for a messenger to come with a sign except by permission of Allāh. For every term is a decree.', 'Dan demi sesungguhnya! Kami telah mengutus Rasul-rasul sebelummu, dan Kami jadikan untuk mereka isteri-isteri dan zuriat keturunan. Dan tiadalah sebarang kuasa bagi seseorang Rasul untuk mendatangkan sesuatu mukjizat melainkan dengan izin Allah. Tiap-tiap satu tempoh dan waktu ada baginya perkara dan hukum yang telah ditentukan oleh “Suratan Azali”.', FALSE, NULL, NULL, 254, 13, 102, 210, FALSE, 0, NULL),
(13, 39, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', 'يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِندَهُ أُمُّ الْكِتَابِ', NULL, 'Allāh eliminates what He wills or confirms, and with Him is the Mother of the Book.', 'Allah menghapuskan apa jua yang dikehendakiNya dan Ia juga menetapkan apa jua yang dikehendakinya. Dan (ingatlah) pada sisiNya ada “Ibu segala suratan”.', FALSE, NULL, NULL, 254, 13, 102, 210, FALSE, 0, NULL),
(13, 40, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ الْبَلَاغُ وَعَلَيْنَا الْحِسَابُ', NULL, 'And whether We show you part of what We promise them or take you in death, upon you is only the [duty of] notification, and upon Us is the account.', 'Sama ada Kami perlihatkan kepadamu (wahai Muhammad) sebahagian dari azab yang Kami janjikan untuk mereka (yang ingkar) atau kami wafatkanmu sebelum melihatnya maka tidaklah menjadi hal kerana tanggunganmu hanyalah menyampaikan hukum-hukum yang kami turunkan kepadamu; dan urusan Kami menghitung dan membalas amal mereka.', FALSE, NULL, NULL, 254, 13, 102, 210, FALSE, 0, NULL),
(13, 41, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ وَهُوَ سَرِيعُ ٱلْحِسَابِ', 'أَوَلَمْ يَرَوْا أَنَّا نَأْتِي الْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا وَاللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِ وَهُوَ سَرِيعُ الْحِسَابِ', NULL, 'Have they not seen that We set upon the land, reducing it from its borders? And Allāh decides; there is no adjuster of His decision. And He is swift in account.', 'Mengapa mereka yang kafir itu masih berdegil dan tidak mahu memerhatikan bahawa kekuasaan kami sentiasa menakluk bumi (yang mereka diami) dengan menjadikan dia kurang sedikit demi sedikit dari kebaikannya dan kemuliaannya? Dan (ingatlah) Allah menghukum menurut apa yang dikehendakiNya; tiada sesiapapun yang dapat menghalang hukumNya, dan dia lah juga yang amat cepat hitungan hisabNya.', FALSE, NULL, NULL, 254, 13, 102, 210, FALSE, 0, NULL),
(13, 42, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', 'وَقَدْ مَكَرَ الَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ الْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ الْكُفَّارُ لِمَنْ عُقْبَى الدَّارِ', NULL, 'And those before them had plotted, but to Allāh belongs the plan entirely. He knows what every soul earns, and the disbelievers will know for whom is the final home.', 'Dan sesungguhnya orang-orang kafir yang sebelum mereka telah melancarkan rancangan jahat (terhadap Nabi-nabi mereka): oleh itu, (janganlah engkau bimbang kerana) bagi Allah jualah kuasa menggagalkan segala jenis rancangan jahat. Ia mengetahui apa yang diusahakan oleh tiap-tiap diri; dan orang-orang yang kafir akan mengetahui bagi siapakah balasan (yang baik dan yang buruk) pada hari akhirat kelak.', FALSE, NULL, NULL, 254, 13, 102, 210, FALSE, 0, NULL),
(13, 43, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 'وَيَقُولُ الَّذِينَ كَفَرُوا لَسْتَ مُرْسَلًا قُلْ كَفَىٰ بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِندَهُ عِلْمُ الْكِتَابِ', NULL, 'And those who have disbelieved say, "You are not a messenger." Say, [O Muḥammad], "Sufficient is Allāh as Witness between me and you, and [the witness of] whoever has knowledge of the Scripture."', 'Dan orang-orang yang kafir itu berkata: “Engkau bukanlah seorang Rasul dari Allah”. Katakanlah (kepada mereka): “Cukuplah Allah menjadi saksi antaraku dengan kamu, dan juga disaksikan oleh orang-orang yang ada ilmu pengetahuan mengenai Kitab Allah”.', FALSE, NULL, NULL, 255, 13, 102, 210, FALSE, 0, NULL),
(14, 1, 'الٓر ۚ كِتَـٰبٌ أَنزَلْنَـٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'الر كتاب انزلناه اليك لتخرج الناس من الظلمات الى النور باذن ربهم الى صراط العزيز الحميد', NULL, 'Alif, Lām, Rā. [This is] a Book which We have revealed to you, [O Muḥammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -', 'Alif, Laam, Raa''. Ini ialah Kitab (Al-Quran) Kami turunkan dia kepadamu (wahai Muhammad), supaya engkau mengeluarkan umat manusia seluruhnya dari gelap-gelita kufur kepada cahaya iman - dengan izin Tuhan mereka - ke jalan Allah Yang Maha Kuasa lagi Maha Terpuji.', FALSE, NULL, NULL, 255, 13, 102, 211, FALSE, 16, NULL),
(14, 2, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَوَيْلٌ لِّلْكَـٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ', 'الله الذي له ما في السماوات وما في الارض وويل للكافرين من عذاب شديد', NULL, 'Allāh, to whom belongs whatever is in the heavens and whatever is on the earth. And woe [i.e., destruction] to the disbelievers from a severe punishment -', 'Allah jua yang memiliki segala yang ada di langit serta yang ada di bumi; dan kecelakaan besar bagi orang-orang yang kufur ingkar (terhadap Al-Quran) dari azab yang amat berat (yang akan menimpa mereka kelak).', FALSE, NULL, NULL, 255, 13, 102, 211, FALSE, 14, NULL),
(14, 3, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍۭ بَعِيدٍ', 'الذين يستحبون الحياة الدنيا على الاخرة ويصدون عن سبيل الله ويبغونها عوجا اولئك في ضلال بعيد', NULL, 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allāh, seeking to make it [seem] deviant. Those are in extreme error.', 'Orang-orang yang mengutamakan dunia lebih daripada akhirat, dan menghalangi manusia dari jalan ugama Allah, serta menghendaki jalan itu menjadi bengkok terpesong, mereka itulah orang-orang yang terjerumus ke dalam kesesatan yang jauh terpesongnya.', FALSE, NULL, NULL, 255, 13, 102, 211, FALSE, 16, NULL),
(14, 4, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وما ارسلنا من رسول الا بلسان قومه ليبين لهم فيضل الله من يشاء ويهدي من يشاء وهو العزيز الحكيم', NULL, 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allāh sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.', 'Dan Kami tidak mengutuskan seseorang Rasul melainkan dengan bahasa kaumnya supaya ia menjelaskan (hukum-hukum Allah) kepada mereka. Maka Allah menyesatkan sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya), juga memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan Dia lah jua Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 255, 13, 102, 211, FALSE, 19, NULL),
(14, 5, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'ولقد ارسلنا موسى باياتنا ان اخرج قومك من الظلمات الى النور وذكرهم بايام الله ان في ذلك لايات لكل صبار شكور', NULL, 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allāh." Indeed in that are signs for everyone patient and grateful.', 'Dan sesungguhnya Kami telah mengutuskan Nabi Musa (pada masa yang lalu) dengan membawa mukjizat-mukjizat Kami sambil Kami berfirman: “Hendaklah engkau mengeluarkan kaummu dari gelap-gelita kufur kepada cahaya iman; dan ingatkanlah mereka dengan Hari-hari Allah. “Sesungguhnya yang demikian itu, mengandungi tanda-tanda yang menunjukkan kekuasaan Allah bagi tiap-tiap seorang yang kuat bersabar, lagi kuat bersyukur.', FALSE, NULL, NULL, 255, 13, 102, 211, FALSE, 21, NULL),
(14, 6, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'واذ قال موسى لقومه اذكروا نعمة الله عليكم اذ انجاكم من ال فرعون يسومونكم سوء العذاب ويذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم', NULL, 'And [recall, O Children of Israel], when Moses said to his people, "Remember the favor of Allāh upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', 'Dan (ingatlah) ketika Nabi Musa berkata kepada kaumnya: “Kenanglah nikmat Allah kepada kamu, semasa Ia menyelamatkan kamu dari Firaun dan orang-orangnya yang sentiasa menyeksa kamu dengan berbagai seksa yang buruk dan mereka pula menyembelih anak-anak lelaki kamu dan membiarkan hidup anak-anak perempuan kamu; dan kejadian yang demikian itu mengandungi bala bencana dan cubaan yang besar dari Tuhan kamu”.', FALSE, NULL, NULL, 256, 13, 102, 211, FALSE, 26, NULL),
(14, 7, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', 'واذ تاذن ربكم لئن شكرتم لازيدنكم ولئن كفرتم ان عذابي لشديد', NULL, 'And [remember] when your Lord proclaimed, ''If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.''"', 'Dan (ingatlah) ketika Tuhan kamu memberitahu: “Demi sesungguhnya! Jika kamu bersyukur nescaya Aku akan tambahi nikmatKu kepada kamu, dan demi sesungguhnya, jika kamu kufur ingkar sesungguhnya azabKu amatlah keras”.', FALSE, NULL, NULL, 256, 13, 102, 212, FALSE, 11, NULL),
(14, 8, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', 'وقال موسى ان تكفروا انتم ومن في الارض جميعا فان الله لغني حميد', NULL, 'And Moses said, "If you should disbelieve, you and whoever is on the earth entirely - indeed, Allāh is Free of need and Praiseworthy."', 'Dan Nabi Musa berkata: “Kalau kamu dan sesiapa jua yang ada di muka bumi seluruhnya berlaku kufur ingkar, maka (hal yang demikian tidak merugikan Allah), kerana sesungguhnya Allah adalah Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 256, 13, 102, 212, FALSE, 13, NULL),
(14, 9, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ ۛ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۛ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ ۚ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ', 'الم ياتكم نبا الذين من قبلكم قوم نوح وعاد وثمود والذين من بعدهم لا يعلمهم الا الله جاءتهم رسلهم بالبينات فردوا ايديهم في افواههم وقالوا انا كفرنا بما ارسلتم به وانا لفي شك مما تدعوننا اليه مريب', NULL, 'Has there not reached you the news of those before you - the people of Noah and ʿAad and Thamūd and those after them? No one knows them [i.e., their number] but Allāh. Their messengers brought them clear proofs, but they returned their hands to their mouths and said, "Indeed, we disbelieve in that with which you have been sent, and indeed we are, about that to which you invite us, in disquieting doubt."', '(Mengapa kamu masih berdegil) bukankah telah datang kepada kamu khabar berita orang-orang yang terdahulu daripada kamu, iaitu kaum Nabi Nuh, dan Aad juga Thamud serta orang-orang yang kemudian daripada mereka? Tiada sesiapapun yang mengetahui bilangan mereka melainkan Allah. Mereka telah didatangi oleh rasul-rasul mereka dengan membawa keterangan-keterangan yang nyata, lalu mereka meletakkan tangan mereka ke mulut mereka sambil berkata: “Sesungguhnya kami kufur ingkarkan apa yang - mengikut dakwaan kamu - kamu diutus membawanya, dan sesungguhnya kami adalah dalam keadaan yang meragukan terhadap iman dan tauhid yang kamu ajak kami kepadanya”.', FALSE, NULL, NULL, 256, 13, 102, 212, FALSE, 37, NULL),
(14, 10, '۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَـٰنٍ مُّبِينٍ', 'قالت رسلهم افي الله شك فاطر السماوات والارض يدعوكم ليغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى قالوا ان انتم الا بشر مثلنا تريدون ان تصدونا عما كان يعبد اباؤنا فاتونا بسلطان مبين', NULL, 'Their messengers said, "Can there be doubt about Allāh, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays you [i.e., your death] for a specified term." They said, "You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority [i.e., evidence]."', 'Rasul-rasul mereka bertanya: “Patutkah berlakunya sebarang keraguan tentang wujudnya Allah, yang menciptakan langit dan bumi? Ia menyeru kamu beriman kerana hendak membersih dan melepaskan kamu dari dosa-dosa kamu, dan memberi tempoh kepada kamu hingga ke suatu masa yang tertentu. Mereka menjawab: “Kamu tidak lain hanyalah manusia seperti kami. Kamu bertujuan hendak menyekat kami daripada menyembah apa yang telah disembah oleh datuk nenek kami. Oleh itu, bawalah kepada kami satu bukti yang jelas nyata”.', FALSE, NULL, NULL, 256, 13, 103, 212, FALSE, 33, NULL),
(14, 11, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَـٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَـٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'قالت لهم رسلهم ان نحن الا بشر مثلكم ولكن الله يمن على من يشاء من عباده وما كان لنا ان ناتيكم بسلطان الا باذن الله وعلى الله فليتوكل المؤمنون', NULL, 'Their messengers said to them, "We are only men like you, but Allāh confers favor upon whom He wills of His servants. It has never been for us to bring you evidence except by permission of Allāh. And upon Allāh let the believers rely.', 'Rasul-rasul mereka berkata kepada mereka: “Kami ini tidak lain hanyalah manusia seperti kamu juga, tetapi Allah melimpahkan kurniaNya kepada sesiapa yang dikehendakiNya dari hamba-hambaNya; dan kami tiadalah berkuasa membawa kepada kamu sebarang bukti (mukjizat) melainkan dengan izin Allah. Dan dengan yang demikian maka kepada Allah jualah hendaknya orang-orang yang beriman berserah diri.', FALSE, NULL, NULL, 257, 13, 103, 212, FALSE, 29, NULL),
(14, 12, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا ۚ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'وما لنا الا نتوكل على الله وقد هدانا سبلنا ولنصبرن على ما اذيتمونا وعلى الله فليتوكل المتوكلون', NULL, 'And why should we not rely upon Allāh while He has guided us to our [good] ways. And we will surely be patient against whatever harm you should cause us. And upon Allāh let those who would rely [indeed] rely."', '“Dan mengapa pula kami tidak berserah diri kepada Allah padahal Ia telah menunjukkan jalan untuk tiap-tiap seorang dari kami menjalaninya? Dan demi sesungguhnya, kami akan bersabar terhadap segala perbuatan kamu menyakiti kami. Dan dengan yang demikian, maka kepada Allah jualah hendaknya berserah diri orang-orang yang mahu berserah”.', FALSE, NULL, NULL, 257, 13, 103, 212, FALSE, 17, NULL),
(14, 13, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّـٰلِمِينَ', 'وقال الذين كفروا لرسلهم لنخرجنكم من ارضنا او لتعودن في ملتنا فاوحى اليهم ربهم لنهلكن الظالمين', NULL, 'And those who disbelieved said to their messengers, "We will surely drive you out of our land, or you must return to our religion." So their Lord inspired to them, "We will surely destroy the wrongdoers.', 'Dan berkatalah pula orang-orang yang kafir itu kepada Rasul-rasul mereka: “Demi sesungguhnya, kami akan mengeluarkan kamu dari negeri kami atau kamu menjadi seugama dengan kami”. Lalu Tuhan wahyukan, kepada Rasul-rasulNya: “Demi sesungguhnya! Kami akan membinasakan orang-orang yang zalim.', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 16, NULL),
(14, 14, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ۚ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', 'ولنسكننكم الارض من بعدهم ذلك لمن خاف مقامي وخاف وعيد', NULL, 'And We will surely cause you to dwell in the land after them. That is for he who fears My position and fears My threat."', '“Dan demi sesungguhnya! kami akan tempatkan kamu di negeri itu sesudah binasanya kaum yang zalim itu; balasan baik yang demikian, adalah bagi orang-orang yang takut akan sikap keadilanKu (menghitung amalnya), dan takut akan janji-janji azabKu”.', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 10, NULL),
(14, 15, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ', 'واستفتحوا وخاب كل جبار عنيد', NULL, 'And they requested decision [i.e., victory from Allāh], and disappointed, [therefore], was every obstinate tyrant.', 'Dan (Rasul-rasul serta umatnya yang beriman) memohon pertolongan (kepada Allah, untuk mendapat kemenangan); dan terkecewalah tiap-tiap orang yang sombong takbur, lagi bersikap degil (dalam keingkarannya).', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 5, NULL),
(14, 16, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ', 'من ورائه جهنم ويسقى من ماء صديد', NULL, 'Before him is Hell, and he will be given a drink of purulent water.', 'Di belakangnya disediakan neraka Jahannam, dan ia akan diberi minum dari air danur (yang keluar dari tubuh ahli neraka).', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 7, NULL),
(14, 17, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ ۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ', 'يتجرعه ولا يكاد يسيغه وياتيه الموت من كل مكان وما هو بميت ومن ورائه عذاب غليظ', NULL, 'He will gulp it but will hardly [be able to] swallow it. And death will come to him from everywhere, but he is not to die. And before him is a massive punishment.', 'Ia meminumnya dengan terpaksa dan hampir-hampir tidak dapat diterima oleh tekaknya (kerana busuknya), dan ia didatangi (penderitaan) maut dari segala arah, sedang ia tidak pula mati (supaya terlepas dari azab seksa itu); dan selain dari itu, ada lagi azab seksa yang lebih berat.', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 16, NULL),
(14, 18, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ أَعْمَـٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ ۖ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ۚ ذَٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلْبَعِيدُ', 'مثل الذين كفروا بربهم اعمالهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا على شيء ذلك هو الضلال البعيد', NULL, 'The example of those who disbelieve in their Lord is [that] their deeds are like ashes which the wind blows forcefully on a stormy day; they are unable [to keep] from what they earned a [single] thing. That is what is extreme error.', 'Bandingan (segala kebaikan amal dan usaha) orang-orang yang kufur ingkar terhadap Tuhannya ialah seperti abu yang diterbangkan angin pada hari ribut yang kencang; mereka tidak memperoleh sesuatu faedah pun dari apa yang mereka telah usahakan itu. Sia-sianya amalan itu ialah kesan kesesatan yang jauh dari dasar kebenaran.', FALSE, NULL, NULL, 257, 13, 103, 213, FALSE, 22, NULL),
(14, 19, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'الم تر ان الله خلق السماوات والارض بالحق ان يشا يذهبكم ويات بخلق جديد', NULL, 'Have you not seen [i.e., considered] that Allāh created the heavens and the earth in truth? If He wills, He can do away with you and produce a new creation.', 'Tidakkah engkau telah nampak dan mengetahui bahawa Allah telah menciptakan langit dan bumi dengan cara yang sungguh layak dan berhikmat? Jika Ia kehendaki nescaya dibinasakanNya kamu (dengan sebab kekufuran kamu) dan didatangkan pula dengan makhluk-makhluk yang baharu.', FALSE, NULL, NULL, 258, 13, 103, 213, FALSE, 14, NULL),
(14, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'وما ذلك على الله بعزيز', NULL, 'And that is not difficult for Allāh.', 'Dan yang demikian itu tidaklah sukar bagi Allah melakukannya.', FALSE, NULL, NULL, 258, 13, 103, 213, FALSE, 5, NULL),
(14, 21, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', 'وَبَرَزُوا لِلَّهِ جَمِيعًا فَقَالَ الضُّعَفَاءُ لِلَّذِينَ اسْتَكْبَرُوا إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ اللَّهِ مِن شَيْءٍ قَالُوا لَوْ هَدَانَا اللَّهُ لَهَدَيْنَاكُمْ سَوَاءٌ عَلَيْنَا أَجَزِعْنَا أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', NULL, 'And they will come out [for judgement] before Allāh all together, and the weak will say to those who were arrogant, "Indeed, we were your followers, so can you avail us anything against the punishment of Allāh?" They will say, "If Allāh had guided us, we would have guided you. It is all the same for us whether we show intolerance or are patient: there is for us no place of escape."', 'Dan mereka sekalian tetap akan berhimpun mengadap Allah (untuk dihisab pada hari kiamat); kemudian orang-orang yang lemah (yang menjadi pengikut) kepada orang-orang yang sombong takbur itu akan berkata kepada mereka (yang menjadi pemimpinnya): “Sesungguhnya kami telah menjadi pengikut kamu; maka adakah kamu dapat menolak daripada kami sedikit dari azab Allah?” Mereka menjawab: “Kalaulah Allah menunjukkan jalan selamat kepada kami, tentulah kami tunjukkan jalan itu kepada kamu. (Sekarang) sama sahaja kepada kita, sama ada kita menggelisah dan mengeluh atau kita bersabar, tiadalah sebarang jalan bagi kita untuk melepaskan diri (dari azab itu)”.', FALSE, NULL, NULL, 258, 13, 103, 213, FALSE, 0, NULL),
(14, 22, 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', 'وَقَالَ الشَّيْطَانُ لَمَّا قُضِيَ الْأَمْرُ إِنَّ اللَّهَ وَعَدَكُمْ وَعْدَ الْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِيَ عَلَيْكُم مِّن سُلْطَانٍ إِلَّا أَن دَعَوْتُكُمْ فَاسْتَجَبْتُمْ لِي فَلَا تَلُومُونِي وَلُومُوا أَنفُسَكُم مَّا أَنَا بِمُصْرِخِكُمْ وَمَا أَنتُم بِمُصْرِخِيَّ إِنِّي كَفَرْتُ بِمَا أَشْرَكْتُمُونِ مِن قَبْلُ إِنَّ الظَّالِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'And Satan will say when the matter has been concluded, "Indeed, Allāh had promised you the promise of truth. And I promised you, but I betrayed you. But I had no authority over you except that I invited you, and you responded to me. So do not blame me; but blame yourselves. I cannot be called to your aid, nor can you be called to my aid. Indeed, I deny your association of me [with Allāh] before. Indeed, for the wrongdoers is a painful punishment."', 'Dan berkatalah pula Syaitan setelah selesai perkara itu: “Sesungguhnya Allah telah menjanjikan kamu dengan janji yang benar dan aku telah menjanjikan kamu lalu aku mungkiri janjiku itu kepada kamu; dan tiadalah bagiku sebarang alasan dan kuasa mempengaruhi kamu selain daripada aku telah mengajak kamu lalu kamu terburu-buru menurut ajakanku itu; maka janganlah kamu salahkan daku tetapi salahkan diri kamu sendiri. Aku tidak dapat menyelamatkan kamu dan kamu juga tidak dapat menyelamatkan daku. Sesungguhnya dari dahulu lagi aku telah kufur ingkarkan (perintah Tuhan) yang kamu sekutukan daku denganNya”. Sesungguhnya orang-orang yang zalim (yang meletakkan sesuatu pada bukan tempatnya) beroleh azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 258, 13, 103, 214, FALSE, 0, NULL),
(14, 23, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 'وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ تَحِيَّتُهُمْ فِيهَا سَلَامٌ', NULL, 'And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, "Peace!"', 'Dan dimasukkanlah orang-orang yang beriman dan beramal soleh, ke dalam Syurga-syurga yang mengalir di bawahnya beberapa sungai; mereka kekal di dalamnya dengan izin Tuhan mereka; ucapan selamat sentiasa mereka dapati (dari malaikat) di dalam Syurga-syurga itu.', FALSE, NULL, NULL, 258, 13, 103, 214, FALSE, 0, NULL),
(14, 24, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ', 'أَلَمْ تَرَ كَيْفَ ضَرَبَ اللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ', NULL, 'Have you not considered how Allāh presents an example, [making] a good word like a good tree, whose root is firmly fixed and its branches [high] in the sky?', 'Tidakkah engkau melihat (wahai Muhammad) bagaimana Allah mengemukakan satu perbandingan, iaitu: kalimah yang baik adalah sebagai sebatang pohon yang baik, yang pangkalnya (akar tunjangnya) tetap teguh, dan cabang pucuknya menjulang ke langit.', FALSE, NULL, NULL, 258, 13, 103, 214, FALSE, 0, NULL),
(14, 25, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'تُؤْتِي أُكُلَهَا كُلَّ حِينٍ بِإِذْنِ رَبِّهَا وَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'It produces its fruit all the time, by permission of its Lord. And Allāh presents examples for the people that perhaps they will be reminded.', 'Dia mengeluarkan buahnya pada tiap-tiap masa dengan izin Tuhannya. Dan Allah mengemukakan perbandingan-perbandingan itu untuk manusia, supaya mereka beringat (mendapat pelajaran).', FALSE, NULL, NULL, 259, 13, 103, 214, FALSE, 0, NULL),
(14, 26, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ', 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ اجْتُثَّتْ مِن فَوْقِ الْأَرْضِ مَا لَهَا مِن قَرَارٍ', NULL, 'And the example of a bad word is like a bad tree, uprooted from the surface of the earth, not having any stability.', 'Dan bandingan Kalimah yang jahat dan buruk samalah seperti sebatang pohon yang tidak berguna yang mudah tercabut akar-akarnya dari muka bumi; tidak ada tapak baginya untuk tetap hidup.', FALSE, NULL, NULL, 259, 13, 103, 214, FALSE, 0, NULL),
(14, 27, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 'يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ وَيُضِلُّ اللَّهُ الظَّالِمِينَ وَيَفْعَلُ اللَّهُ مَا يَشَاءُ', NULL, 'Allāh keeps firm those who believe, with the firm word, in worldly life and in the Hereafter. And Allāh sends astray the wrongdoers. And Allāh does what He wills.', 'Allah menetapkan (pendirian) orang-orang yang beriman dengan kalimah yang tetap teguh dalam kehidupan dunia dan akhirat; dan Allah menyesatkan orang-orang yang berlaku zalim (kepada diri mereka sendiri); dan Allah berkuasa melakukan apa yang dikehendakiNya.', FALSE, NULL, NULL, 259, 13, 103, 214, FALSE, 0, NULL),
(14, 28, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 'أَلَمْ تَرَ إِلَى الَّذِينَ بَدَّلُوا نِعْمَتَ اللَّهِ كُفْرًا وَأَحَلُّوا قَوْمَهُمْ دَارَ الْبَوَارِ', NULL, 'Have you not considered those who exchanged the favor of Allāh for disbelief and settled their people [in] the home of ruin?', 'Tidakkah engkau melihat (dan merasa ajaib) terhadap orang-orang kafir yang telah menukar kesyukuran nikmat Allah dengan kekufuran, dan yang telah menempatkan kaum mereka dalam kebinasaan?', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 29, 'جَهَنَّمَ يَصْلَوْنَهَا وَبِئْسَ ٱلْقَرَارُ', 'جَهَنَّمَ يَصْلَوْنَهَا وَبِئْسَ الْقَرَارُ', NULL, '[It is] Hell, which they will [enter to] burn, and wretched is the settlement.', '(Iaitu) neraka Jahannam yang mereka akan menderita bakarannya; dan (ingatlah), seburuk-buruk tempat tetap ialah neraka Jahannam.', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 30, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', 'وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا فَإِنَّ مَصِيرَكُمْ إِلَى النَّارِ', NULL, 'And they have attributed to Allāh equals to mislead [people] from His way. Say, "Enjoy yourselves, for indeed, your destination is the Fire."', 'Dan mereka mengadakan sekutu-sekutu bagi Allah untuk menyesatkan manusia dari jalanNya. Katakanlah (wahai Muhammad): “Bersenang-senanglah kamu (bagi sementara di dunia), kerana sesungguhnya kesudahan kamu ke neraka”.', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 31, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَٰلٌ', 'قُل لِّعِبَادِيَ الَّذِينَ آمَنُوا يُقِيمُوا الصَّلَاةَ وَيُنفِقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَالٌ', NULL, '[O Muḥammad], tell My servants who have believed to establish prayer and spend from what We have provided them, secretly and publicly, before a Day comes in which there will be no exchange [i.e., ransom], nor any friendships.', 'Katakanlah kepada hamba-hambaKu yang beriman hendaklah mereka mendirikan sembahyang dan mendermakan dari apa yang kami kurniakan kepada mereka, sama ada dengan merahsiakan pemberiannya itu atau dengan terbuka; sebelum datangnya hari yang tidak ada jual beli padanya, dan tidak ada sahabat handai (yang dapat memberikan pertolongan).', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 32, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 'اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ بِأَمْرِهِ وَسَخَّرَ لَكُمُ الْأَنْهَارَ', NULL, 'It is Allāh who created the heavens and the earth and sent down rain from the sky and produced thereby some fruits as provision for you and subjected for you the ships to sail through the sea by His command and subjected for you the rivers.', 'Allah jualah yang menciptakan langit dan bumi, dan menurunkan hujan dari langit lalu mengeluarkan dengan air hujan itu buah-buahan untuk menjadi makanan bagi kamu; dan Ia yang memberi kemudahan kepada kamu menggunakan kapal-kapal untuk belayar di laut dengan perintahNya, juga yang memudahkan sungai-sungai untuk kamu (mengambil manfaat darinya).', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 33, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'وَسَخَّرَ لَكُمُ الشَّمْسَ وَالْقَمَرَ دَائِبَيْنِ وَسَخَّرَ لَكُمُ اللَّيْلَ وَالنَّهَارَ', NULL, 'And He subjected for you the sun and the moon, continuous [in orbit], and subjected for you the night and the day.', 'Dan Ia juga yang menjadikan matahari dan bulan sentiasa beredar, untuk kepentingan kemudahan kamu, dan yang menjadikan malam dan siang bagi faedah hidup kamu.', FALSE, NULL, NULL, 259, 13, 104, 215, FALSE, 0, NULL),
(14, 34, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌ كَفَّارٌ', 'وَآتَاكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا نِعْمَتَ اللَّهِ لَا تُحْصُوهَا إِنَّ الْإِنسَانَ لَظَلُومٌ كَفَّارٌ', NULL, 'And He gave you from all you asked of Him. And if you should count the favor [i.e., blessings] of Allāh, you could not enumerate them. Indeed, mankind is [generally] most unjust and ungrateful.', 'Dan Ia telah memberi kepada kamu sebahagian dari tiap-tiap apa jua yang kamu hajati. Dan jika kamu menghitung nikmat Allah nescaya lemahlah kamu menentukan bilangannya. Sesungguhnya manusia (yang ingkar) sangat suka menempatkan sesuatu pada bukan tempatnya lagi sangat tidak menghargai nikmat Tuhannya.', FALSE, NULL, NULL, 260, 13, 104, 215, FALSE, 0, NULL),
(14, 35, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 'وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَٰذَا الْبَلَدَ آمِنًا وَاجْنُبْنِي وَبَنِيَّ أَن نَّعْبُدَ الْأَصْنَامَ', NULL, 'And [mention, O Muḥammad], when Abraham said, "My Lord, make this city [i.e., Makkah] secure and keep me and my sons away from worshipping idols.', 'Dan (ingatlah) ketika Nabi Ibrahim berdoa dengan berkata: “Wahai Tuhanku! jadikanlah negeri Makkah ini negeri yang aman, dan jauhkanlah daku dan anak-anakku dari perbuatan menyembah berhala.', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 36, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ', 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ النَّاسِ فَمَن تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَّحِيمٌ', NULL, 'My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.', 'Wahai Tuhanku, berhala-berhala itu telah menyebabkan sesat banyak di antara umat manusia. Oleh itu, sesiapa yang menurutku (dalam Islam yang menjadi peganganku) maka ia adalah dari golonganku; dan sesiapa yang menderhaka kepadaku (dengan menyalahi ugamaku), maka sesungguhnya engkau Maha Pengampun, lagi Maha Mengasihani (kiranya ia insaf dan bertaubat).', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 37, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', 'رَّبَّنَا إِنِّي أَسْكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ عِندَ بَيْتِكَ الْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا الصَّلَاةَ فَاجْعَلْ أَفْئِدَةً مِّنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُم مِّنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ', NULL, 'Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful.', '“Wahai Tuhan kami! Sesungguhnya aku telah menempatkan sebahagian dari zuriat keturunanku di sebuah lembah (Tanah Suci Makkah) yang tidak tanaman padanya, di sisi rumahMu yang diharamkan mencerobohinya. Wahai Tuhan kami, (mereka ditempatkan di situ) supaya mereka mendirikan sembahyang (dan memakmurkannya dengan ibadat). Oleh itu, jadikanlah hati sebahagian dari manusia tertarik gemar kepada mereka, (supaya datang beramai-ramai ke situ), dan kurniakanlah rezeki kepada mereka dari berbagai jenis buah-buahan dan hasil tanaman, semoga mereka bersyukur.', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 38, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'رَبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى اللَّهِ مِن شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ', NULL, 'Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allāh on the earth or in the heaven.', '“Wahai Tuhan kami! Sesungguhnya Engkau mengetahui akan apa yang kami sembunyikan dan apa yang kami zahirkan; dan tiada sesuatupun di langit dan di bumi, yang tersembunyi kepada Allah!', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 39, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', 'الْحَمْدُ لِلَّهِ الَّذِي وَهَبَ لِي عَلَى الْكِبَرِ إِسْمَاعِيلَ وَإِسْحَاقَ إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ', NULL, 'Praise to Allāh, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication.', '“Segala puji tertentu bagi Allah Yang telah mengurniakan kepadaku semasa aku tua: Ismail dan Ishak. Sesungguhnya Tuhanku Maha Mendengar dan Memperkenan doa permohonan.', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 40, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 'رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ', NULL, 'My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.', '“Wahai Tuhanku! Jadikanlah daku orang yang mendirikan sembahyang dan demikianlah juga zuriat keturunanku. Wahai Tuhan kami, perkenankanlah doa permohonanku.', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 41, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', 'رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ', NULL, 'Our Lord, forgive me and my parents and the believers the Day the account is established."', '“Wahai Tuhan kami! Berilah ampun bagiku dan bagi kedua ibu bapaku serta bagi orang-orang yang beriman, pada masa berlakunya hitungan amal dan pembalasan”', FALSE, NULL, NULL, 260, 13, 104, 216, FALSE, 0, NULL),
(14, 42, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', 'وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ', NULL, 'And never think that Allāh is unaware of what the wrongdoers do. He only delays them [i.e., their account] for a Day when eyes will stare [in horror].', 'Dan janganlah engkau (wahai Muhammad) menyangka Allah lalai akan apa yang dilakukan oleh orang-orang yang zalim; sesungguhnya Ia hanya melambatkan balasan mereka hingga ke suatu hari yang padanya terbeliak kaku pemandangan mereka, (kerana gerun gementar melihat keadaan yang berlaku).', FALSE, NULL, NULL, 260, 13, 104, 217, FALSE, 0, NULL),
(14, 43, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْـِٔدَتُهُمْ هَوَآءٌ', 'مُهْطِعِينَ مُقْنِعِي رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْئِدَتُهُمْ هَوَاءٌ', NULL, 'Racing ahead, their heads raised up, their glance does not come back to them, and their hearts are void.', '(Dalam pada itu) mereka terburu-buru (menyahut panggilan ke padang Mahsyar) sambil mendongakkan kepala mereka dengan mata tidak berkelip, dan hati mereka tidak bersemangat (kerana bingung dan cemas).', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 44, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', 'وَأَنذِرِ النَّاسَ يَوْمَ يَأْتِيهِمُ الْعَذَابُ فَيَقُولُ الَّذِينَ ظَلَمُوا رَبَّنَا أَخِّرْنَا إِلَىٰ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ الرُّسُلَ أَوَلَمْ تَكُونُوا أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', NULL, 'And, [O Muḥammad], warn the people of a Day when the punishment will come to them and those who did wrong will say, "Our Lord, delay us for a short term; we will answer Your call and follow the messengers." [But it will be said], "Had you not sworn, before, that for you there would be no cessation?', 'Dan berilah amaran (wahai Muhammad) kepada manusia yang ingkar itu jangan mereka lupakan hari kiamat yang padanya mereka akan didatangi azab, kerana pada saat itu, orang-orang yang berlaku zalim akan merayu dengan berkata: “Wahai Tuhan kami, (kembalikanlah kami ke dunia dan) berilah tempoh kepada kami hingga ke suatu masa yang dekat, supaya kami menyahut seruanMu (untuk mengesakanMu dan mentaati perintahMu), dan supaya kami menurut ugama yang disampaikan oleh Rasul-rasul itu”. Dan (rayuan mereka akan ditolak dengan dikatakan kepada mereka): “Tidakkah kamu telah diberikan tempoh untuk berbuat demikian, dan bukankah kamu telah bersumpah (semasa kamu dalam dunia) dahulu, bahawa keadaan kamu tidak akan mengalami sebarang perubahan?', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 45, 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 'وَسَكَنتُمْ فِي مَسَاكِنِ الَّذِينَ ظَلَمُوا أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ الْأَمْثَالَ', NULL, 'And you lived among the dwellings of those who wronged themselves, and it had become clear to you how We dealt with them. And We presented for you [many] examples."', '“Padahal kamu telah mendiami tempat-tempat tinggal orang-orang yang berlaku zalim kepada diri mereka sendiri, serta telah ternyata kepada kamu dengan bukti-buKti yang jelas bagaimana Kami telah mengubah keadaan mereka (dengan menimpakan mereka berbagai bencana), dan Kami pula telah nyatakan kepada kamu berbagai contoh perbandingan (di dalam Al-Quran dan melalui sabda Rasul)”.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 46, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 'وَقَدْ مَكَرُوا مَكْرَهُمْ وَعِندَ اللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ الْجِبَالُ', NULL, 'And they had planned their plan, but with Allāh is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains.', 'Dan sesungguhnya mereka telah menjalankan rancangan jahat mereka (untuk menentang Islam), sedang di sisi Allah ada balasan bagi rancangan jahat mereka, walau rancangan jahat mereka itu, dapat melenyapkan gunung-ganang sekalipun.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 47, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ', 'فَلَا تَحْسَبَنَّ اللَّهَ مُخْلِفَ وَعْدِهِ رُسُلَهُ إِنَّ اللَّهَ عَزِيزٌ ذُو انتِقَامٍ', NULL, 'So never think that Allāh will fail in His promise to His messengers. Indeed, Allāh is Exalted in Might and Owner of Retribution.', 'Oleh itu, janganlah engkau menyangka Allah memungkiri janjiNya kepada Rasul-rasulNya; sesungguhnya Allah Maha Kuasa, lagi Sedia Membalas (orang-orang yang menderhaka kepadaNya).', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 48, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ', NULL, '[It will be] on the Day the earth will be replaced by another earth, and the heavens [as well], and they [i.e., all creatures] will come out before Allāh, the One, the Prevailing,', '(Ingatlah) masa hari bumi ini diganti dengan yang lain, demikian juga langit; dan manusia semuanya keluar berhimpun mengadap Allah, Yang Maha Esa, lagi Maha Kuasa.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 49, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'وَتَرَى الْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِي الْأَصْفَادِ', NULL, 'And you will see the criminals that Day bound together in irons,', 'Dan engkau akan melihat orang-orang yang berdosa pada ketika itu diberkas dengan belenggu.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 50, 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ النَّارُ', NULL, 'Their garments of liquid pitch and their faces covered by the Fire', 'Pakaian mereka dari belangkin (minyak tar), dan muka (serta seluruh badan) mereka diliputi oleh jilatan api neraka.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 51, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ', NULL, 'So that Allāh will recompense every soul for what it earned. Indeed, Allāh is swift in account.', '(Keluarnya manusia dari kubur masing-masing itu ialah) kerana Allah akan membalas tiap-tiap seorang apa yang ia telah usahakan; sesungguhnya Allah amat cepat hitungan hisabNya.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(14, 52, 'هَٰذَا بَلَٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'هَٰذَا بَلَاغٌ لِّلنَّاسِ وَلِيُنذَرُوا بِهِ وَلِيَعْلَمُوا أَنَّمَا هُوَ إِلَٰهٌ وَاحِدٌ وَلِيَذَّكَّرَ أُولُو الْأَلْبَابِ', NULL, 'This [Qur’ān] is notification for the people that they may be warned thereby and that they may know that He is but one God and that those of understanding will be reminded.', '(Al-Quran) ini disampaikan kepada manusia supaya mereka diberi ingat dan diberi nasihat dengannya; dan supaya mereka mengetahui (dengan hujjah-hujjah yang tersebut di dalamnya) bahawa sesungguhnya Allah ialah Tuhan Yang Maha Esa; dan supaya orang-orang yang mempunyai fikiran, beringat dan insaf.', FALSE, NULL, NULL, 261, 13, 104, 217, FALSE, 0, NULL),
(15, 1, 'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ وَقُرْءَانٍ مُّبِينٍ', 'الر تلك ايات الكتاب وقران مبين', NULL, 'Alif, Lām, Rā. These are the verses of the Book and a clear Qur’ān [i.e., recitation].', 'Alif, Laam, Raa''. Ini ialah ayat-ayat Kitab (yang lengkap sempurna) dan Al-Quran yang memberi penjelasan.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 6, NULL),
(15, 2, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 'ربما يود الذين كفروا لو كانوا مسلمين', NULL, 'Perhaps those who disbelieve will wish that they had been Muslims.', 'Ada masanya orang-orang yang kafir merasa ingin kalaulah mereka telah menjadi orang-orang Islam.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 3, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ', 'ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون', NULL, 'Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know.', 'Biarkanlah mereka makan dan bersenang-lenang dengan kemewahan dunia dan dilalaikan oleh angan-angan (daripada bertaubat dan insaf); kemudian mereka akan mengetahui kelak (bencana perbuatan mereka).', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 4, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ', 'وما اهلكنا من قرية الا ولها كتاب معلوم', NULL, 'And We did not destroy any city but that for it was a known decree.', 'Dan tiadalah Kami binasakan (penduduk) sesebuah negeri melainkan ada baginya tempoh yang tertentu dan termaklum.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 8, NULL),
(15, 5, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'ما تسبق من امة اجلها وما يستاخرون', NULL, 'No nation will precede its term, nor will they remain thereafter.', 'Sesuatu umat itu tidak dapat mendahului tempohnya yang telah ditentukan, dan mereka juga tidak dapat mengundurkannya.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 6, 'وَقَالُوا۟ يَـٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ', 'وقالوا يا ايها الذي نزل عليه الذكر انك لمجنون', NULL, 'And they say, "O you upon whom the message has been sent down, indeed you are mad.', 'Dan mereka yang ingkar berkata (kepada Nabi Muhammad): “Wahai orang yang kepadanya diturunkan Al-Quran, sesungguhnya engkau adalah orang gila”.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 8, NULL),
(15, 7, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'لو ما تاتينا بالملائكة ان كنت من الصادقين', NULL, 'Why do you not bring us the angels, if you should be among the truthful?"', '“Sepatutnya engkau membawakan malaikat kepada kami (untuk menjadi saksi tentang kerasulanmu), jika betul engkau dari orang-orang yang benar!”', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 8, NULL),
(15, 8, 'مَا نُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ', 'ما ننزل الملائكة الا بالحق وما كانوا اذا منظرين', NULL, 'We do not send down the angels except with truth; and they [i.e., the disbelievers] would not then be reprieved.', 'Tiadalah Kami menurunkan Malaikat melainkan dengan cara yang sungguh layak dan berhikmat, dan pada ketika itu mereka (yang ingkar) tidak akan diberi tempoh lagi.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 9, NULL),
(15, 9, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ', 'انا نحن نزلنا الذكر وانا له لحافظون', NULL, 'Indeed, it is We who sent down the message [i.e., the Qur’ān], and indeed, We will be its guardian.', 'Sesungguhnya Kamilah yang menurunkan Al-Quran, dan Kamilah yang memelihara dan menjaganya.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 10, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 'ولقد ارسلنا من قبلك في شيع الاولين', NULL, 'And We had certainly sent [messengers] before you, [O Muḥammad], among the sects of the former peoples.', 'Dan demi sesungguhnya! Kami telah utuskan Rasul-rasul sebelummu (wahai Muhammad), dalam kalangan kaum-kaum yang telah lalu.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 11, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وما ياتيهم من رسول الا كانوا به يستهزئون', NULL, 'And no messenger would come to them except that they ridiculed him.', 'Dan tiadalah seseorang Rasul pun yang datang kepada mereka, melainkan mereka mempersenda dan mengejek-ejeknya.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 8, NULL),
(15, 12, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'كذلك نسلكه في قلوب المجرمين', NULL, 'Thus do We insert it [i.e., denial] into the hearts of the criminals.', '(Sebagaimana hati kaum-kaum yang telah lalu dimasuki perasaan mempersendakan Rasul-rasul) demikianlah pula Kami masukkan perasaan yang seperti itu ke dalam hati orang-orang yang berdosa (yang menentangmu).', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 5, NULL),
(15, 13, 'لَا يُؤْمِنُونَ بِهِۦ ۖ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 'لا يؤمنون به وقد خلت سنة الاولين', NULL, 'They will not believe in it, while there has already occurred the precedent of the former peoples.', 'Mereka tidak percaya kepada Al-Quran yang engkau bawa, padahal telahpun berlaku undang-undang membinasakan orang-orang yang telah lalu (yang mendustakan Rasul-rasulnya).', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 7, NULL),
(15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', 'ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون', NULL, 'And [even] if We opened to them a gate from the heaven and they continued therein to ascend,', 'Dan kalau Kami bukakan kepada mereka mana-mana pintu langit, kemudian mereka dapat naik melalui pintu itu (pada siang hari yang membolehkan mereka menyaksikan segala kenyataan yang ada):', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 9, NULL),
(15, 15, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَـٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ', 'لقالوا انما سكرت ابصارنا بل نحن قوم مسحورون', NULL, 'They would say, "Our eyes have only been dazzled. Rather, we are a people affected by magic."', 'Tentulah mereka akan (mengingkari kenyataan yang benar itu dengan) berkata: “Hanya mata kami telah disilapkan penglihatannya bahkan kami adalah kaum yang telah disihirkan (oleh Muhammad)”.', FALSE, NULL, NULL, 262, 14, 105, 218, FALSE, 8, NULL),
(15, 16, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ', 'ولقد جعلنا في السماء بروجا وزيناها للناظرين', NULL, 'And We have placed within the heaven great stars and have beautified it for the observers.', 'Dan demi sesungguhnya! Kami telah menjadikan di langit: bintang-bintang (yang berbagai bentuk dan keadaan) serta kami hiasi langit itu bagi orang-orang yang melihatnya.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 7, NULL),
(15, 17, 'وَحَفِظْنَـٰهَا مِن كُلِّ شَيْطَـٰنٍ رَّجِيمٍ', 'وحفظناها من كل شيطان رجيم', NULL, 'And We have protected it from every devil expelled [from the mercy of Allāh]', 'Dan Kami pelihara (urusan) langit itu dari (masuk campur) tiap-tiap Syaitan yang kena rejam.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 5, NULL),
(15, 18, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ', 'الا من استرق السمع فاتبعه شهاب مبين', NULL, 'Except one who steals a hearing and is pursued by a clear burning flame.', 'Kecuali Syaitan yang curi mendengar percakapan (malaikat di langit), maka ia diburu dan diikuti (dengan rejaman) api yang menyala, yang nyata kelihatan.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 7, NULL),
(15, 19, 'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ', 'والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل شيء موزون', NULL, 'And the earth - We have spread it and cast therein firmly set mountains and caused to grow therein [something] of every well-balanced thing.', 'Dan bumi ini Kami bentangkan, dan Kami letakkan padanya gunung-ganang yang kukuh terdiri, serta Kami tumbuhkan padanya tiap-tiap sesuatu yang tertentu timbangannya.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 11, NULL),
(15, 20, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', 'وجعلنا لكم فيها معايش ومن لستم له برازقين', NULL, 'And We have made for you therein means of living and [for] those for whom you are not providers.', 'Dan Kami jadikan untuk kamu pada bumi ini segala keperluan hidup, juga Kami jadikan makhluk-makhluk yang kamu bukanlah orang yang sebenar menyediakan rezekinya.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 8, NULL),
(15, 21, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ', 'وَإِن مِّن شَيْءٍ إِلَّا عِندَنَا خَزَائِنُهُ وَمَا نُنَزِّلُهُ إِلَّا بِقَدَرٍ مَّعْلُومٍ', NULL, 'And there is not a thing but that with Us are its depositories, and We do not send it down except according to a known [i.e., specified] measure.', 'Dan tidak ada sesuatupun melainkan pada sisi Kami sahaja perbendaharaannya dan Kami tidak menurunkannya melainkan dengan menurut kadar dan masa yang tertentu.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 0, NULL),
(15, 22, 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', 'وَأَرْسَلْنَا الرِّيَاحَ لَوَاقِحَ فَأَنزَلْنَا مِنَ السَّمَاءِ مَاءً فَأَسْقَيْنَاكُمُوهُ وَمَا أَنتُمْ لَهُ بِخَازِنِينَ', NULL, 'And We have sent the fertilizing winds and sent down water from the sky and given you drink from it. And you are not its retainers.', 'Dan Kami hantarkan angin sebagai pembawa air dan pemindah benih; maka dengan itu Kami menurunkan air (hujan) dari langit, kemudian Kami berikan kamu meminumnya; dan bukanlah kamu yang (berkuasa menurunkannya atau) menyimpannya.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 0, NULL),
(15, 23, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', 'وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ وَنَحْنُ الْوَارِثُونَ', NULL, 'And indeed, it is We who give life and cause death, and We are the Inheritor.', 'Dan sesungguhnya Kamilah yang menghidupkan dan yang mematikan, dan Kamilah yang kekal memiliki segala-galanya.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 0, NULL),
(15, 24, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', 'وَلَقَدْ عَلِمْنَا الْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا الْمُسْتَأْخِرِينَ', NULL, 'And We have already known the preceding [generations] among you, and We have already known the later [ones to come].', 'Dan sesungguhnya Kami telah mengetahui orang-orang yang segera (berbakti) di antara kamu, dan sesungguhnya Kami telah mengetahui orang-orang yang lambat.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 0, NULL),
(15, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ إِنَّهُ حَكِيمٌ عَلِيمٌ', NULL, 'And indeed, your Lord will gather them; indeed, He is Wise and Knowing.', 'Dan sesungguhnya Tuhanmu, Dia lah yang menghimpunkan mereka semuanya; sesungguhnya Ia Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 263, 14, 105, 219, FALSE, 0, NULL),
(15, 26, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'وَلَقَدْ خَلَقْنَا الْإِنسَانَ مِن صَلْصَالٍ مِّنْ حَمَإٍ مَّسْنُونٍ', NULL, 'And We did certainly create man out of clay from an altered black mud.', 'Dan sesungguhnya Kami telah menciptakan manusia (Adam) dari tanah liat yang kering, yang berasal dari tanah kental yang berubah warna dan baunya.', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 27, 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 'وَالْجَانَّ خَلَقْنَاهُ مِن قَبْلُ مِن نَّارِ السَّمُومِ', NULL, 'And the jinn We created before from scorching fire.', 'Dan jin pula, Kami jadikan dia sebelum itu, dari angin api yang panasnya menyerap ke liang bulu roma.', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 28, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن صَلْصَالٍ مِّنْ حَمَإٍ مَّسْنُونٍ', NULL, 'And [mention, O Muḥammad], when your Lord said to the angels, "I will create a human being out of clay from an altered black mud.', 'Dan (ingatkanlah peristiwa) ketika Tuhanmu berfirman kepada malaikat: “Sesungguhnya Aku hendak menciptakan manusia dari tanah liat yang kering, yang berasal dari tanah kental yang berubah warna dan baunya.', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 29, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ', NULL, 'And when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', '“Kemudian apabila Aku sempurnakan kejadiannya, serta Aku tiupkan padanya roh dari (ciptaan) ku, maka hendaklah kamu sujud kepadanya.', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 30, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ', NULL, 'So the angels prostrated - all of them entirely,', '(Setelah selesai kejadian Adam) maka sujudlah sekalian malaikat, semuanya sekali, -', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 31, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'إِلَّا إِبْلِيسَ أَبَىٰ أَن يَكُونَ مَعَ السَّاجِدِينَ', NULL, 'Except Iblees; he refused to be with those who prostrated.', 'Melainkan Iblis; ia enggan turut bersama mereka yang sujud.', FALSE, NULL, NULL, 263, 14, 105, 220, FALSE, 0, NULL),
(15, 32, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'قَالَ يَا إِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ السَّاجِدِينَ', NULL, '[Allāh] said, "O Iblees, what is [the matter] with you that you are not with those who prostrate?"', 'Allah berfirman: Hai Iblis, apa sebabnya engkau tidak turut bersama mereka yang sujud itu?”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 33, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُ مِن صَلْصَالٍ مِّنْ حَمَإٍ مَّسْنُونٍ', NULL, 'He said, "Never would I prostrate to a human whom You created out of clay from an altered black mud."', 'Iblis menjawab: “Aku tidak patut sujud kepada manusia yang Engkau jadikan dia dari tanah liat yang kering, yang berasal dari tanah kental yang berubah warna dan baunya”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 34, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', 'قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', NULL, '[Allāh] said, "Then depart from it, for indeed, you are expelled.', 'Allah berfirman: “Kalau demikian, keluarlah engkau daripadanya, kerana sesungguhnya engkau dari sekarang ke masa depan adalah (satu makhluk yang) diusir.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 35, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', 'وَإِنَّ عَلَيْكَ اللَّعْنَةَ إِلَىٰ يَوْمِ الدِّينِ', NULL, 'And indeed, upon you is the curse until the Day of Recompense."', '“Dan sesungguhnya engkau ditimpa laknat terus-menerus hingga ke hari kiamat”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 36, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قَالَ رَبِّ فَأَنظِرْنِي إِلَىٰ يَوْمِ يُبْعَثُونَ', NULL, 'He said, "My Lord, then reprieve me until the Day they are resurrected."', 'Iblis berkata: “Wahai Tuhanku! Jika demikian, berilah tempoh kepadaku hingga ke hari mereka dibangitkan (hari kiamat)”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 37, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قَالَ فَإِنَّكَ مِنَ الْمُنظَرِينَ', NULL, '[Allāh] said, "So indeed, you are of those reprieved', 'Allah berfirman: “Dengan permohonanmu itu, maka sesungguhnya engkau dari golongan yang diberi tempoh.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 38, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'إِلَىٰ يَوْمِ الْوَقْتِ الْمَعْلُومِ', NULL, 'Until the Day of the time well-known."', '“Hingga ke hari - masa yang termaklum”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 39, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'قَالَ رَبِّ بِمَا أَغْوَيْتَنِي لَأُزَيِّنَنَّ لَهُمْ فِي الْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', NULL, '[Iblees] said, "My Lord, because You have put me in error, I will surely make [disobedience] attractive to them [i.e., mankind] on earth, and I will mislead them all', 'Iblis berkata: “Wahai Tuhanku! Kerana Engkau telah menjadikan daku sesat, (maka) demi sesungguhnya aku akan memperelokkan segala jenis maksiat kepada Adam dan zuriatnya di dunia ini, dan aku akan menyesatkan mereka semuanya,', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 40, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ', NULL, 'Except, among them, Your chosen servants."', '“Kecuali di antara zuriat-zuriat Adam itu hamba-hambaMu yang dibersihkan dari sebarang syirik”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 41, 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', 'قَالَ هَٰذَا صِرَاطٌ عَلَيَّ مُسْتَقِيمٌ', NULL, '[Allāh] said, "This is a path [of return] to Me [that is] straight.', 'Allah berfirman: “Inilah satu jalan yang lurus, yang tetap Aku memeliharanya.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 42, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', 'إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ إِلَّا مَنِ اتَّبَعَكَ مِنَ الْغَاوِينَ', NULL, 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.', '“Sesungguhnya hamba-hambaKu, tidaklah ada bagimu sebarang kuasa untuk menyesatkan mereka, kecuali sesiapa yang menurutmu dari orang-orang yang sesat (dengan pilihannya sendiri).', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 43, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', NULL, 'And indeed, Hell is the promised place for them all.', '“Dan sesungguhnya neraka Jahannam itu, tempat yang dijanjikan bagi sekalian mereka (yang menurutmu).', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 44, 'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', 'لَهَا سَبْعَةُ أَبْوَابٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', NULL, 'It has seven gates; for every gate is of them [i.e., Satan''s followers] a portion designated."', '“Ia mempunyai tujuh pintu; bagi tiap-tiap sebuah pintu ada bahagian yang tertentu dari mereka (yang sesat dan menyesatkan itu)”.', FALSE, NULL, NULL, 264, 14, 105, 220, FALSE, 0, NULL),
(15, 45, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَعُيُونٍ', 'إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ', NULL, 'Indeed, the righteous will be within gardens and springs,', 'Sesungguhnya orang-orang yang bertaqwa adalah ditempatkan di dalam beberapa taman Syurga, dengan matair-matair terpancar padanya.', FALSE, NULL, NULL, 264, 14, 105, 221, FALSE, 0, NULL),
(15, 46, 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'ادْخُلُوهَا بِسَلَامٍ آمِنِينَ', NULL, '[Having been told], "Enter it in peace, safe [and secure]."', '(Mereka dipersilakan oleh malaikat dengan berkata): “Masuklah kamu ke dalamnya dengan selamat sejahtera serta beroleh aman”.', FALSE, NULL, NULL, 264, 14, 105, 221, FALSE, 0, NULL),
(15, 47, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'وَنَزَعْنَا مَا فِي صُدُورِهِم مِّنْ غِلٍّ إِخْوَانًا عَلَىٰ سُرُرٍ مُّتَقَابِلِينَ', NULL, 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.', 'Dan Kami cabut akan apa yang ada dihati mereka dari perasaan hasad dengki sehingga menjadilah mereka bersaudara (dalam suasana kasih mesra), serta mereka duduk berhadap-hadapan di atas pelamin masing-masing.', FALSE, NULL, NULL, 264, 14, 105, 221, FALSE, 0, NULL),
(15, 48, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', NULL, 'No fatigue will touch them therein, nor from it will they [ever] be removed.', 'Mereka tidak akan disentuh susah payah dalam Syurga itu, dan mereka pula tidak sekali-kali akan dikeluarkan daripadanya.', FALSE, NULL, NULL, 264, 14, 105, 221, FALSE, 0, NULL),
(15, 49, 'نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', 'نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ', NULL, '[O Muḥammad], inform My servants that it is I who am the Forgiving, the Merciful,', 'Khabarkanlah kepada hamba-hambaKu (wahai Muhammad), bahawa Akulah Yang Maha Pengampun lagi Maha Mengasihani (bagi mereka yang bertaubat dan beramal soleh).', FALSE, NULL, NULL, 264, 14, 105, 221, FALSE, 0, NULL),
(15, 50, 'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ', 'وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ', NULL, 'And that it is My punishment which is the painful punishment.', 'Dan bahawa azabKu, ialah azab yang tidak terperi sakitnya, (bagi mereka yang tetap dalam kederhakaannya).', FALSE, NULL, NULL, 264, 14, 106, 221, FALSE, 0, NULL),
(15, 51, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَاهِيمَ', NULL, 'And inform them about the guests of Abraham,', 'Dan khabarkanlah kepada mereka perihal tetamu Nabi Ibrahim.', FALSE, NULL, NULL, 264, 14, 106, 221, FALSE, 0, NULL),
(15, 52, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', 'إِذْ دَخَلُوا عَلَيْهِ فَقَالُوا سَلَامًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', NULL, 'When they entered upon him and said, "Peace." [Abraham] said, "Indeed, we are fearful [i.e., apprehensive] of you."', 'Ketika mereka masuk mendapatkannya lalu memberi salam dengan berkata: “Selamat sejahtera kepadamu!” Ia berkata: “Sesungguhnya kami berasa takut kepada kamu”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 53, 'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٍ', 'قَالُوا لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَامٍ عَلِيمٍ', NULL, '[The angels] said, "Fear not. Indeed, we give you good tidings of a learned boy."', 'Mereka menjawab: “Janganlah engkau takut, sebenarnya kami hendak mengembirakanmu dengan berita bahawa engkau akan beroleh seorang anak lelaki yang bakal menjadi seorang yang berilmu”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 54, 'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ', 'قَالَ أَبَشَّرْتُمُونِي عَلَىٰ أَن مَّسَّنِيَ الْكِبَرُ فَبِمَ تُبَشِّرُونَ', NULL, 'He said, "Have you given me good tidings although old age has come upon me? Then of what [wonder] do you inform?"', 'Nabi Ibrahim berkata: “Betulkah kamu mengembirakan daku (dengan berita yang demikian), padahal aku telah tua; maka dengan jalan apakah kamu mengembirakan daku?”', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 55, 'قَالُوا۟ بَشَّرْنَٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَٰنِطِينَ', 'قَالُوا بَشَّرْنَاكَ بِالْحَقِّ فَلَا تَكُن مِّنَ الْقَانِطِينَ', NULL, 'They said, "We have given you good tidings in truth, so do not be of the despairing."', 'Mereka menjawab: “Kami mengembirakanmu dengan jalan yang sungguh benar; oleh itu janganlah engkau menjadi dari orang-orang yang berputus asa”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 56, 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِ إِلَّا الضَّالُّونَ', NULL, 'He said, "And who despairs of the mercy of his Lord except for those astray?"', 'Nabi Ibrahim berkata: “Dan tiadalah sesiapa yang berputus asa dari rahmat Tuhannya melainkan orang-orang yang sesat”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 57, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا الْمُرْسَلُونَ', NULL, '[Abraham] said, "Then what is your business [here], O messengers?"', 'Nabi Ibrahim bertanya pula: “Apa hal kamu wahai Utusan Tuhan?”', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 58, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', 'قَالُوا إِنَّا أُرْسِلْنَا إِلَىٰ قَوْمٍ مُّجْرِمِينَ', NULL, 'They said, "Indeed, we have been sent to a people of criminals,', 'Mereka menjawab: “Kami diutus kepada suatu kaum yang berdosa (untuk membinasakan mereka)”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 59, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', 'إِلَّا آلَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', NULL, 'Except the family of Lot; indeed, we will save them all', '“Melainkan keluarga Nabi Lut; sesungguhnya kami akan menyelamatkan mereka semuanya, -', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 60, 'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ إِنَّهَا لَمِنَ ٱلْغَٰبِرِينَ', 'إِلَّا امْرَأَتَهُ قَدَّرْنَا إِنَّهَا لَمِنَ الْغَابِرِينَ', NULL, 'Except his wife." We [i.e., Allāh] decreed that she is of those who remain behind.', '“Kecuali isterinya; kami telah tentukan (menurut keputusan Tuhan) sesungguhnya ia dari orang-orang yang tinggal (menerima kebinasaan)”.', FALSE, NULL, NULL, 265, 14, 106, 221, FALSE, 0, NULL),
(15, 61, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ', 'فَلَمَّا جَاءَ آلَ لُوطٍ الْمُرْسَلُونَ', NULL, 'And when the messengers came to the family of Lot,', 'Maka apabila (malaikat-malaikat) utusan itu datang kepada kaum Nabi Lut,', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 62, 'قَالَ إِنَّكُمْ قَوْمٌ مُّنكَرُونَ', 'قَالَ إِنَّكُمْ قَوْمٌ مُّنكَرُونَ', NULL, 'He said, "Indeed, you are people unknown."', 'Nabi Lut berkata: “Sesungguhnya kamu suatu kaum yang tidak dikenali (serta tidak diketahui baiknya kedatangan kamu)”.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 63, 'قَالُوا۟ بَلْ جِئْنَٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ', 'قَالُوا بَلْ جِئْنَاكَ بِمَا كَانُوا فِيهِ يَمْتَرُونَ', NULL, 'They said, "But we have come to you with that about which they were disputing,', 'Mereka menjawab: “(Kedatangan kami bukan untuk mendukacitakanmu) bahkan kami datang kepadamu untuk membawa azab yang mereka ragu-ragukan kebenarannya.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 64, 'وَأَتَيْنَٰكَ بِٱلْحَقِّ وَإِنَّا لَصَٰدِقُونَ', 'وَأَتَيْنَاكَ بِالْحَقِّ وَإِنَّا لَصَادِقُونَ', NULL, 'And we have come to you with truth, and indeed, we are truthful.', '“Juga membawa kepadamu perkara yang benar (tentang kebinasaan mereka); dan sesungguhnya kami adalah orang-orang yang benar”.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 65, 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ', 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ اللَّيْلِ وَاتَّبِعْ أَدْبَارَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ وَامْضُوا حَيْثُ تُؤْمَرُونَ', NULL, 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."', '“Oleh itu, bawalah pergi keluargamu pada waktu malam serta ikutlah di belakang mereka; dan janganlah seseorang pun di antara kamu berpaling (ke belakang); serta pergilah terus ke arah yang diperintahkan kamu menujunya”.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 66, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقْطُوعٌ مُّصْبِحِينَ', 'وَقَضَيْنَا إِلَيْهِ ذَٰلِكَ الْأَمْرَ أَنَّ دَابِرَ هَٰؤُلَاءِ مَقْطُوعٌ مُّصْبِحِينَ', NULL, 'And We conveyed to him [the decree] of that matter: that those [sinners] would be eliminated by early morning.', 'Dan Kami wahyukan kepadanya tentang kesudahan perkara itu; iaitu mereka akan dibinasakan pada waktu pagi, sehingga mereka punah ranah dan terputus keturunannya.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 67, 'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ', 'وَجَاءَ أَهْلُ الْمَدِينَةِ يَسْتَبْشِرُونَ', NULL, 'And the people of the city came rejoicing.', 'Dan (semasa kedatangan mereka) datanglah penduduk bandar itu dengan gembira.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 68, 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ', 'قَالَ إِنَّ هَٰؤُلَاءِ ضَيْفِي فَلَا تَفْضَحُونِ', NULL, '[Lot] said, "Indeed, these are my guests, so do not shame me.', 'Nabi Lut berkata: “Sesungguhnya mereka ini tetamuku, maka janganlah kamu memberi malu kepadaku”.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 69, 'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ', 'وَاتَّقُوا اللَّهَ وَلَا تُخْزُونِ', NULL, 'And fear Allāh and do not disgrace me."', '“Dan takutlah kamu kepada Allah serta janganlah kamu menghinakan daku”.', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 70, 'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَٰلَمِينَ', 'قَالُوا أَوَلَمْ نَنْهَكَ عَنِ الْعَالَمِينَ', NULL, 'They said, "Have we not forbidden you from [protecting] people?"', 'Mereka menjawab: “Bukankah kami telah melarangmu jangan menerima sebarang tetamu dari orang ramai (atau memberi perlindungan kepada mereka)?”', FALSE, NULL, NULL, 265, 14, 106, 222, FALSE, 0, NULL),
(15, 71, 'قَالَ هَٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَٰعِلِينَ', 'قَالَ هَٰؤُلَاءِ بَنَاتِي إِن كُنتُمْ فَاعِلِينَ', NULL, '[Lot] said, "These are my daughters - if you would be doers [of lawful marriage]."', 'Nabi Lut berkata: “Di sini ada anak-anak perempuanku, kalaulah kamu mahu melakukan (secara halal).', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 72, 'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ', 'لَعَمْرُكَ إِنَّهُمْ لَفِي سَكْرَتِهِمْ يَعْمَهُونَ', NULL, 'By your life, [O Muḥammad], indeed they were, in their intoxication, wandering blindly.', 'Demi umurmu (wahai Muhammad), sesungguhnya mereka membuta tuli dalam kemabukan maksiat mereka.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 73, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ', 'فَأَخَذَتْهُمُ الصَّيْحَةُ مُشْرِقِينَ', NULL, 'So the shriek seized them at sunrise.', 'Akhirnya merekapun dibinasakan oleh letusan suara yang menggempakan bumi, ketika matahari terbit.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 74, 'فَجَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِّن سِجِّيلٍ', 'فَجَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِّن سِجِّيلٍ', NULL, 'And We made the highest part [of the city] its lowest and rained upon them stones of hard clay.', 'Maka Kami jadikan negeri kaum Lut itu tunggang-balik (tertimbus segala yang ada di muka buminya), dan kami hujani atasnya dengan batu dari tanah yang dibakar.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 75, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّلْمُتَوَسِّمِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّلْمُتَوَسِّمِينَ', NULL, 'Indeed in that are signs for those who discern.', 'Sesungguhnya balasan azab yang demikian itu, mengandungi tanda-tanda bagi orang-orang yang kenalkan sesuatu serta memerhati dan memikirkannya.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 76, 'وَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ', 'وَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ', NULL, 'And indeed, they [i.e., those cities] are [situated] on an established road.', 'Dan sesungguhnya negeri kaum Lut yang telah dibinasakan itu, terletak di jalan yang tetap (dilalui orang).', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 77, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً لِّلْمُؤْمِنِينَ', NULL, 'Indeed in that is a sign for the believers.', 'Sesungguhnya keadaan yang demikian, mengandungi satu tanda yang memberi kesedaran kepada orang-orang yang beriman.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 78, 'وَإِن كَانَ أَصْحَٰبُ ٱلْأَيْكَةِ لَظَٰلِمِينَ', 'وَإِن كَانَ أَصْحَابُ الْأَيْكَةِ لَظَالِمِينَ', NULL, 'And the companions of the thicket [i.e., the people of Madyan] were [also] wrongdoers,', 'Dan sebenarnya penduduk kampung “Aikah” adalah orang-orang yang berlaku zalim.', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 79, 'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ', 'فَانتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ', NULL, 'So We took retribution from them, and indeed, both [cities] are on a clear highway.', 'Maka Kami membalas kezaliman mereka itu dengan azab yang membinasakan; dan sesungguhnya kedua-duanya itu terletak di jalan yang terang (yang masih dilalui orang).', FALSE, NULL, NULL, 266, 14, 106, 222, FALSE, 0, NULL),
(15, 80, 'وَلَقَدْ كَذَّبَ أَصْحَٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ', 'وَلَقَدْ كَذَّبَ أَصْحَابُ الْحِجْرِ الْمُرْسَلِينَ', NULL, 'And certainly did the companions of al-Ḥijr [i.e., the Thamūd] deny the messengers.', 'Dan demi sesungguhnya penduduk “Al-Hijr” telah mendustakan Rasul-rasul.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 81, 'وَءَاتَيْنَٰهُمْ ءَايَٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وَآتَيْنَاهُمْ آيَاتِنَا فَكَانُوا عَنْهَا مُعْرِضِينَ', NULL, 'And We gave them Our signs, but from them they were turning away.', 'Dan Kami telah berikan kepada mereka tanda-tanda (yang membuktikan kebenaran ugama dan Rasul Kami); dalam pada itu, mereka terus juga berpaling (mengingkarinya).', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 82, 'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ', 'وَكَانُوا يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا آمِنِينَ', NULL, 'And they used to carve from the mountains, houses, feeling secure.', 'Dan mereka memahat sebahagian dari gunung-ganang, sebagai tempat tinggal dengan keadaan aman (dari sesuatu bahaya).', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 83, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ', 'فَأَخَذَتْهُمُ الصَّيْحَةُ مُصْبِحِينَ', NULL, 'But the shriek seized them at early morning,', 'Meskipun demikian, mereka dibinasakan juga oleh letusan suara yang menggempakan pada bumi waktu pagi.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 84, 'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'فَمَا أَغْنَىٰ عَنْهُم مَّا كَانُوا يَكْسِبُونَ', NULL, 'So nothing availed them [from] what they used to earn.', 'Maka apa yang mereka telah usahakan itu, tidak dapat menolong mereka sedikit pun.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 85, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَإِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ', 'وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَإِنَّ السَّاعَةَ لَآتِيَةٌ فَاصْفَحِ الصَّفْحَ الْجَمِيلَ', NULL, 'And We have not created the heavens and earth and that between them except in truth. And indeed, the Hour is coming; so forgive with gracious forgiveness.', 'Dan (ingatlah) tiadalah Kami mencipta langit dan bumi serta segala yang ada di antara keduanya itu, melainkan dengan cara yang sungguh layak dan berhikmat; dan sesungguhnya hari kiamat itu tetap akan datang; oleh itu biarkanlah (golongan kafir yang mendustakanmu itu wahai Muhammad) serta layanlah mereka dengan cara yang elok.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 86, 'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'إِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَلِيمُ', NULL, 'Indeed, your Lord - He is the Knowing Creator.', 'Sesungguhnya Tuhanmu, Dia lah yang menciptakan sekalian makhluk, lagi Yang Maha Mengetahui (akan hal mereka).', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 87, 'وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ', 'وَلَقَدْ آتَيْنَاكَ سَبْعًا مِّنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ', NULL, 'And We have certainly given you, [O Muḥammad], seven of the often repeated [verses] and the great Qur’ān.', 'Dan sesungguhnya Kami telah memberi kepadamu (wahai Muhammad) tujuh ayat yang diulang-ulang bacaannya dan seluruh Al-Quran yang amat besar kemuliaan dan faedahnya.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 88, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', NULL, 'Do not extend your eyes toward that by which We have given enjoyment to [certain] categories of them [i.e., the disbelievers], and do not grieve over them. And lower your wing [i.e., show kindness] to the believers.', 'Janganlah engkau menujukan pandanganmu (serta menaruh hati) kepada nikmat kesenangan yang kami berikan kepada beberapa golongan di antara mereka (yang kafir itu) dan janganlah engkau merasa dukacita terhadap mereka (kerana mereka tidak beriman dan tidak dapat menguatkan Islam sebagaimana yang engkau harapkan); dan sebaliknya hendaklah engkau merendah diri kepada orang-orang yang beriman (sekalipun mereka dari golongan fakir miskin).', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 89, 'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ', 'وَقُلْ إِنِّي أَنَا النَّذِيرُ الْمُبِينُ', NULL, 'And say, "Indeed, I am the clear warner" -', 'Dan katakanlah: “Sesungguhnya aku ini, adalah seorang Rasul pemberi amaran dengan bukti-bukti yang nyata (tentang turunnya azab ke atas orang-orang yang ingkar)”.', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 90, 'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ', 'كَمَا أَنزَلْنَا عَلَى الْمُقْتَسِمِينَ', NULL, 'Just as We had revealed [scriptures] to the separators', '(Kami berikan kepadamu Al-Faatihah dan Al-Quran) samalah seperti Kami menurunkan (Kitab-kitab) kepada orang-orang yang membahagi-bahagi. -', FALSE, NULL, NULL, 266, 14, 106, 223, FALSE, 0, NULL),
(15, 91, 'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ', 'الَّذِينَ جَعَلُوا الْقُرْآنَ عِضِينَ', NULL, 'Who have made the Qur’ān into portions.', '(Iaitu) mereka yang menjadikan Al-Quran terbahagi kepada beberapa bahagian (lalu mereka percaya kepada sebahagian dan menolak sebahagian yang lain).', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 92, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ', 'فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ', NULL, 'So by your Lord, We will surely question them all', 'Demi Tuhanmu! Kami akan menyoal mereka (yang kafir itu) semuanya (pada hari kiamat kelak), -', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 93, 'عَمَّا كَانُوا۟ يَعْمَلُونَ', 'عَمَّا كَانُوا يَعْمَلُونَ', NULL, 'About what they used to do.', 'Mengenai apa yang mereka telah lakukan.', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 94, 'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ', NULL, 'Then declare what you are commanded and turn away from the polytheists.', 'Oleh itu, sampaikanlah secara berterus-terang apa yang diperintahkan kepadamu (wahai Muhammad), dan janganlah engkau hiraukan bantahan dan tentangan kaum kafir musyrik itu.', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 95, 'إِنَّا كَفَيْنَٰكَ ٱلْمُسْتَهْزِءِينَ', 'إِنَّا كَفَيْنَاكَ الْمُسْتَهْزِئِينَ', NULL, 'Indeed, We are sufficient for you against the mockers', 'Sesungguhnya Kami tetap memelihara dan mengawalmu dari kejahatan orang-orang yang mengejek-ejek dan mempersendakanmu, -', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 96, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَسَوْفَ يَعْلَمُونَ', 'الَّذِينَ يَجْعَلُونَ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَسَوْفَ يَعْلَمُونَ', NULL, 'Who make [equal] with Allāh another deity. But they are going to know.', '(Iaitu) mereka yang mengadakan tuhan yang lain bersama-sama Allah, maka mereka akan mengetahui kelak (akibatnya).', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 97, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', NULL, 'And We already know that your breast is constrained by what they say.', 'Dan demi sesungguhnya Kami mengetahui, bahawa engkau bersusah hati dengan sebab apa yang mereka katakan.', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 98, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ السَّاجِدِينَ', NULL, 'So exalt [Allāh] with praise of your Lord and be of those who prostrate [to Him].', 'Oleh itu, bertasbihlah engkau dengan memuji Tuhanmu, serta jadilah dari orang-orang yang sujud.', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(15, 99, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 'وَاعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ الْيَقِينُ', NULL, 'And worship your Lord until there comes to you the certainty [i.e., death].', 'Dan sembahlah Tuhanmu, sehingga datang kepadamu (perkara yang tetap) yakin.', FALSE, NULL, NULL, 267, 14, 106, 223, FALSE, 0, NULL),
(16, 1, 'أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', 'اتى امر الله فلا تستعجلوه سبحانه وتعالى عما يشركون', NULL, 'The command of Allāh is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.', 'Telah hampir datangnya janji yang telah ditetapkan oleh Allah, maka janganlah kamu minta disegerakan. Maha suci Allah dan Maha tinggilah Ia dari perbuatan syirik yang mereka lakukan.', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 9, NULL),
(16, 2, 'يُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', 'ينزل الملائكة بالروح من امره على من يشاء من عباده ان انذروا انه لا اله الا انا فاتقون', NULL, 'He sends down the angels, with the inspiration [i.e., revelation] of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."', 'Ia menurunkan malaikat membawa wahyu dengan perintahNya kepada sesiapa yang dikehendakiNya dari hamba-hambaNya (yang layak menjadi Rasul); (lalu Ia berfirman kepada Rasul-rasul): “Hendaklah kamu menegaskan kepada umat manusia bahawa tiada Tuhan melainkan Aku. Oleh itu, bertaqwalah kamu kepadaku”.', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 18, NULL),
(16, 3, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَـٰلَىٰ عَمَّا يُشْرِكُونَ', 'خلق السماوات والارض بالحق تعالى عما يشركون', NULL, 'He created the heavens and earth in truth. High is He above what they associate with Him.', 'Ia menciptakan langit dan bumi dengan cara yang sungguh layak dan berhikmat; Maha Tinggilah Ia dari perbuatan syirik yang mereka lakukan.', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 7, NULL),
(16, 4, 'خَلَقَ ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'خلق الانسان من نطفة فاذا هو خصيم مبين', NULL, 'He created man from a sperm-drop; then at once he is a clear adversary.', 'Ia menciptakan manusia dari air benih, (setelah sempurna kejadiannya), tiba-tiba menjadilah ia seorang pembantah yang terang jelas bantahannya.', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 8, NULL),
(16, 5, 'وَٱلْأَنْعَـٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌ وَمَنَـٰفِعُ وَمِنْهَا تَأْكُلُونَ', 'والانعام خلقها لكم فيها دفء ومنافع ومنها تاكلون', NULL, 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.', 'Dan binatang-binatang ternak itu, Ia juga menciptakannya untuk kamu; terdapat padanya benda-benda yang memanaskan tubuh dari sejuk dan beberapa faedah yang lain; dan daripadanya juga kamu makan.', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 8, NULL),
(16, 6, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', 'ولكم فيها جمال حين تريحون وحين تسرحون', NULL, 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].', 'Dan bagi kamu pada binatang-binatang ternak itu, keindahan (yang menarik hati) ketika kamu membawanya balik untuk berihat (pada waktu petang), dan ketika kamu membawanya keluar (pada waktu pagi).', FALSE, NULL, NULL, 267, 14, 107, 224, FALSE, 7, NULL),
(16, 7, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَـٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ ۚ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'وتحمل اثقالكم الى بلد لم تكونوا بالغيه الا بشق الانفس ان ربكم لرءوف رحيم', NULL, 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.', 'Dan binatang-binatang itu pula membawa barang-barang kamu ke mana-mana negeri yang kamu tidak dapat sampai kepadanya melainkan dengan menanggung susah payah. Sesungguhnya Tuhan kamu Amat melimpah belas kasihan dan rahmatNya.', FALSE, NULL, NULL, 268, 14, 107, 224, FALSE, 14, NULL),
(16, 8, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ', 'والخيل والبغال والحمير لتركبوها وزينة ويخلق ما لا تعلمون', NULL, 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.', 'Dan (Allah menjadikan) kuda dan baghal serta keldai untuk kamu menunggangnya, dan untuk menjadi perhiasan; dan Ia menjadikan apa yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 268, 14, 107, 224, FALSE, 9, NULL),
(16, 9, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'وعلى الله قصد السبيل ومنها جائر ولو شاء لهداكم اجمعين', NULL, 'And upon Allāh is the direction of the [right] way, and among them [i.e., the various paths] are those deviating. And if He willed, He could have guided you all.', 'Dan kepada Allah jualah tertentunya urusan memberi panduan yang menerangkan jalan yang lurus; dan di antara jalan-jalan yang dituju ada yang terpesong dari kebenaran; dan jika Ia kehendaki, tentulah Ia memberi petunjuk kepada kamu semua (yang menyampaikan ke jalan yang lurus itu).', FALSE, NULL, NULL, 268, 14, 107, 224, FALSE, 10, NULL),
(16, 10, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً ۖ لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ', 'هو الذي انزل من السماء ماء لكم منه شراب ومنه شجر فيه تسيمون', NULL, 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].', 'Dia lah yang menurunkan hujan dari langit; sebahagian daripadanya untuk minuman kamu dan sebahagian lagi menyebabkan tumbuhnya pokok-pokok (tumbuh-tumbuhan) untuk kamu melepaskan binatang-binatang ternak: makan padanya.', FALSE, NULL, NULL, 268, 14, 107, 225, FALSE, 13, NULL),
(16, 11, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَـٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'ينبت لكم به الزرع والزيتون والنخيل والاعناب ومن كل الثمرات ان في ذلك لاية لقوم يتفكرون', NULL, 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and of all the fruits. Indeed in that is a sign for a people who give thought.', 'Ia juga menumbuhkan bagi kamu dengan sebab hujan itu tanaman-tanaman dan pokok-pokok zaitun dan tamar (kurma) serta anggur; dan juga dari segala jenis buah-buahan. Sesungguhnya yang demikian mengandungi satu tanda (yang membuktikan kekuasaan Allah) bagi kaum yang mahu berfikir.', FALSE, NULL, NULL, 268, 14, 107, 225, FALSE, 16, NULL),
(16, 12, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'وسخر لكم الليل والنهار والشمس والقمر والنجوم مسخرات بامره ان في ذلك لايات لقوم يعقلون', NULL, 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.', 'Dan ia memudahkan bagi kamu malam dan siang, dan matahari serta bulan; dan bintang-bintang dimudahkan dengan perintahNya untuk keperluan-keperluan kamu. Sesungguhnya yang demikian itu mengandungi tanda-tanda (yang membuktikan kebijaksanaan Allah) bagi kaum yang mahu memahaminya.', FALSE, NULL, NULL, 268, 14, 107, 225, FALSE, 15, NULL),
(16, 13, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَذَّكَّرُونَ', 'وما ذرا لكم في الارض مختلفا الوانه ان في ذلك لاية لقوم يذكرون', NULL, 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.', 'Dan apa-apa jua yang dijadikan untuk kamu di bumi yang berlainan jenisnya (dimudahkan juga untuk kegunaan kamu). Sesungguhnya yang demikian itu mengandungi satu tanda (yang membuktikan kemurahan Allah) bagi kaum yang mahu mengingati nikmat Allah itu.', FALSE, NULL, NULL, 268, 14, 107, 225, FALSE, 13, NULL),
(16, 14, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وهو الذي سخر البحر لتاكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها وترى الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون', NULL, 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.', 'Dan Dia lah yang memudahkan laut, supaya kamu dapat makan daripadanya daging yang lembut hidup-hidup, dan dapat pula mengeluarkan daripadanya benda-benda perhiasan untuk kamu memakainya dan (selain itu) engkau melihat pula kapal-kapal belayar padanya; dan lagi supaya kamu dapat mencari rezeki dari limpah kurniaNya; dan supaya kamu bersyukur.', FALSE, NULL, NULL, 268, 14, 107, 225, FALSE, 21, NULL),
(16, 15, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَـٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', 'والقى في الارض رواسي ان تميد بكم وانهارا وسبلا لعلكم تهتدون', NULL, 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,', 'Dan Ia mengadakan di bumi gunung-ganang yang menetapnya supaya ia tidak menghayun-hayunkan kamu; dan Ia mengadakan sungai-sungai serta jalan-jalan lalu lalang, supaya kamu dapat sampai ke matlamat yang kamu tuju.', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 11, NULL),
(16, 16, 'وَعَلَـٰمَـٰتٍ ۚ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', 'وعلامات وبالنجم هم يهتدون', NULL, 'And landmarks. And by the stars they are [also] guided.', 'Dan (Ia mengadakan) tanda-tanda panduan jalan, dan dengan bintang-bintang (pada waktu malam) mereka dapat mengetahui arah yang hendak dituju.', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 4, NULL),
(16, 17, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ', 'افمن يخلق كمن لا يخلق افلا تذكرون', NULL, 'Then is He who creates like one who does not create? So will you not be reminded?', 'Kalau sudah demikian, adakah Allah yang menciptakan semuanya itu sama seperti makhluk-makhluk yang tidak menciptakan sesuatu? Maka patutkah kamu lalai sehingga kamu tidak mahu beringat serta memikirkannya?', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 7, NULL),
(16, 18, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ', 'وان تعدوا نعمة الله لا تحصوها ان الله لغفور رحيم', NULL, 'And if you should count the favors of Allāh, you could not enumerate them. Indeed, Allāh is Forgiving and Merciful.', 'Dan jika kamu menghitung nikmat Allah (yang dilimpahkannya kepada kamu), tiadalah kamu akan dapat menghitungnya satu persatu; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 10, NULL),
(16, 19, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'والله يعلم ما تسرون وما تعلنون', NULL, 'And Allāh knows what you conceal and what you declare.', 'Dan Allah mengetahui apa yang kamu sembunyikan dan apa yang kamu zahirkan.', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 6, NULL),
(16, 20, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ', 'والذين يدعون من دون الله لا يخلقون شيئا وهم يخلقون', NULL, 'And those they invoke other than Allāh create nothing, and they [themselves] are created.', 'Dan makhluk-makhluk yang mereka sembah selain dari Allah itu tidak dapat menciptakan sesuatupun, bahkah merekalah yang diciptakan.', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 10, NULL),
(16, 21, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'أَمْوَاتٌ غَيْرُ أَحْيَاءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', NULL, 'They are [in fact] dead, not alive, and they do not perceive when they will be resurrected.', 'Makhluk-makhluk itu tetap akan mati, bukanlah kekal hidup; dan mereka tidak mengetahui bilakah masing-masing akan dibangkitkan (menerima balasan).', FALSE, NULL, NULL, 269, 14, 107, 225, FALSE, 0, NULL),
(16, 22, 'إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', 'إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَالَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', NULL, 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.', 'Tuhan kamu (yang berhak disembah) ialah Tuhan yang satu (Maha Esa); oleh itu, orang-orang yang tidak beriman kepada hari akhirat: hati mereka ingkar dan sikap zahir mereka sombong takbur (menentang kebenaran).', FALSE, NULL, NULL, 269, 14, 107, 226, FALSE, 0, NULL),
(16, 23, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', 'لَا جَرَمَ أَنَّ اللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ لَا يُحِبُّ الْمُسْتَكْبِرِينَ', NULL, 'Assuredly, Allāh knows what they conceal and what they declare. Indeed, He does not like the arrogant.', 'Sebenarnya, bahawa Allah mengetahui akan apa yang mereka sembunyikan dan apa yang mereka zahirkan; sesungguhnya Ia tidak suka kepada orang-orang yang sombong takbur.', FALSE, NULL, NULL, 269, 14, 107, 226, FALSE, 0, NULL),
(16, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'وَإِذَا قِيلَ لَهُم مَّاذَا أَنزَلَ رَبُّكُمْ قَالُوا أَسَاطِيرُ الْأَوَّلِينَ', NULL, 'And when it is said to them, "What has your Lord sent down?" they say, "Legends of the former peoples,"', 'Dan apabila dikatakan kepada mereka: “Apakah yang diturunkan oleh Tuhan kamu (kepada nabi Muhammad)?” Mereka menjawab: “Cerita-cerita dongeng orang-orang dahulu kala”.', FALSE, NULL, NULL, 269, 14, 107, 226, FALSE, 0, NULL),
(16, 25, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَٰمَةِ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَآءَ مَا يَزِرُونَ', 'لِيَحْمِلُوا أَوْزَارَهُمْ كَامِلَةً يَوْمَ الْقِيَامَةِ وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَاءَ مَا يَزِرُونَ', NULL, 'That they may bear their own burdens [i.e., sins] in full on the Day of Resurrection and some of the burdens of those whom they misguide without [i.e., by lack of] knowledge. Unquestionably, evil is that which they bear.', '(Mereka dibiarkan menuduh dengan yang demikian) supaya mereka memikul dosa-dosa mereka dengan sepenuhnya pada hari kiamat, dan juga memikul sebahagian dari dosa orang-orang yang mereka sesatkan dengan tidak berdasarkan pengetahuan yang benar; sesungguhnya amatlah buruknya dosa-dosa yang mereka lakukan itu.', FALSE, NULL, NULL, 269, 14, 107, 226, FALSE, 0, NULL),
(16, 26, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'قَدْ مَكَرَ الَّذِينَ مِن قَبْلِهِمْ فَأَتَى اللَّهُ بُنْيَانَهُم مِّنَ الْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ السَّقْفُ مِن فَوْقِهِمْ وَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', NULL, 'Those before them had already plotted, but Allāh came at [i.e., uprooted] their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.', 'Sebenarnya orang-orang yang terdahulu dari mereka telah menjalankan rancangan jahat (terhadap ugama Allah dan Rasul-rasulNya); maka Allah binasakan bangunan (rancangan jahat) mereka dari asas-asasnya, lalu bumbung (bangunan itu) jatuh menimpa ke atas mereka, dan mereka pula didatangi azab kebinasaan dari arah yang mereka tidak menyedarinya.', FALSE, NULL, NULL, 269, 14, 107, 227, FALSE, 0, NULL),
(16, 27, 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', 'ثُمَّ يَوْمَ الْقِيَامَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تُشَاقُّونَ فِيهِمْ قَالَ الَّذِينَ أُوتُوا الْعِلْمَ إِنَّ الْخِزْيَ الْيَوْمَ وَالسُّوءَ عَلَى الْكَافِرِينَ', NULL, 'Then on the Day of Resurrection He will disgrace them and say, "Where are My ''partners'' for whom you used to oppose [the believers]?" Those who were given knowledge will say, "Indeed disgrace, this Day, and evil are upon the disbelievers" -', 'Kemudian pada hari kiamat, Allah menghinakan mereka (dengan azab seksa) sambil bertanya: “Mana dia sekutu-sekutuKu yang kamu berperi-peri memusuhi (Nabi-nabi dan orang-orang yang beriman) untuk membela mereka?” (Pada ketika itu) berkatalah orang-orang yang beroleh ilmu pengetahuan: “Sesungguhnya kehinaan hari ini dan azab seksa, adalah tertimpa kepada orang-orang yang kafir;', FALSE, NULL, NULL, 270, 14, 107, 227, FALSE, 0, NULL),
(16, 28, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', 'الَّذِينَ تَتَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ فَأَلْقَوُا السَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوءٍ بَلَىٰ إِنَّ اللَّهَ عَلِيمٌ بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'The ones whom the angels take in death [while] wronging themselves, and [who] then offer submission, [saying], "We were not doing any evil." But, yes! Indeed, Allāh is Knowing of what you used to do.', '(Iaitu) mereka yang diambil nyawanya oleh malaikat dalam keadaan mereka menganiaya diri sendiri (dengan kekufurannya).” Lalu mereka tunduk menyerah (ketika melihat azab sambil berkata): “Kami tiada melakukan sesuatu kejahatan”. (Malaikat menjawab): “Bahkan (kamu ada melakukannya); sesungguhnya Allah Maha Mengetahui akan apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 270, 14, 107, 227, FALSE, 0, NULL),
(16, 29, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ', NULL, 'So enter the gates of Hell to abide eternally therein, and how wretched is the residence of the arrogant.', '“Oleh itu, masukilah pintu-pintu neraka, tinggal kekalah kamu di dalamnya; maka sesungguhnya (neraka itu) seburuk-buruk tempat bagi orang-orang yang sombong takbur”.', FALSE, NULL, NULL, 270, 14, 107, 227, FALSE, 0, NULL),
(16, 30, 'وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ قَالُوا۟ خَيْرًا لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 'وَقِيلَ لِلَّذِينَ اتَّقَوْا مَاذَا أَنزَلَ رَبُّكُمْ قَالُوا خَيْرًا لِّلَّذِينَ أَحْسَنُوا فِي هَٰذِهِ الدُّنْيَا حَسَنَةٌ وَلَدَارُ الْآخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ الْمُتَّقِينَ', NULL, 'And it will be said to those who feared Allāh, "What did your Lord send down?" They will say, "[That which is] good." For those who do good in this world is good; and the home of the Hereafter is better. And how excellent is the home of the righteous -', 'Dan ditanya pula kepada orang-orang yang bertaqwa: “Apakah yang telah diturunkan oleh tuhan yang telah diturunkan oleh Tuhan kamu?” Mereka menjawab: “Kebaikan” orang-orang yang berbuat kebaikan di dunia ini beroleh balasan yang baik, dan sesungguhnya balasan negeri akhirat itu lebih baik lagi; dan memanglah negeri akhirat ialah sebaik-baik negeri bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 270, 14, 108, 227, FALSE, 0, NULL),
(16, 31, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُمْ فِيهَا مَا يَشَآءُونَ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ لَهُمْ فِيهَا مَا يَشَاءُونَ كَذَٰلِكَ يَجْزِي اللَّهُ الْمُتَّقِينَ', NULL, 'Gardens of perpetual residence, which they will enter, beneath which rivers flow. They will have therein whatever they wish. Thus does Allāh reward the righteous -', '(Untuk mereka) Syurga-syurga “Adn”, yang mereka akan memasukinya, yang mengalir padanya beberapa sungai; mereka beroleh di dalam Syurga itu apa yang mereka kehendaki; demikianlah Allah membalas orang-orang yang bertaqwa,', FALSE, NULL, NULL, 270, 14, 108, 227, FALSE, 0, NULL),
(16, 32, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 'الَّذِينَ تَتَوَفَّاهُمُ الْمَلَائِكَةُ طَيِّبِينَ يَقُولُونَ سَلَامٌ عَلَيْكُمُ ادْخُلُوا الْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'The ones whom the angels take in death, [being] good and pure; [the angels] will say, "Peace be upon you. Enter Paradise for what you used to do."', '(Iaitu) mereka yang diambil nyawanya oleh malaikat dalam keadaan mereka bersih suci (dari kufur syirik dan maksiat), sambil malaikat itu berkata kepada mereka: “Selamat sejahtera kepada kamu; masuklah ke dalam Syurga disebabkan amal baik yang telah kamu kerjakan”.', FALSE, NULL, NULL, 270, 14, 108, 227, FALSE, 0, NULL),
(16, 33, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ أَمْرُ رَبِّكَ كَذَٰلِكَ فَعَلَ الَّذِينَ مِن قَبْلِهِمْ وَمَا ظَلَمَهُمُ اللَّهُ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'Do they [i.e., the disbelievers] await except that the angels should come to them or there comes the command of your Lord? Thus did those do before them. And Allāh wronged them not, but they had been wronging themselves.', '(Apakah yang ditunggu-tunggu oleh mereka yang tidak beriman itu?) Mereka tidak menunggu melainkan kedatangan malaikat (yang akan mencabut nyawa mereka), atau kedatangan azab Tuhanmu (yang akan membinasakan mereka). Demikianlah juga yang dilakukan oleh orang-orang kafir yang terdahulu daripada mereka (lalu dibinasakan); dan (sebenarnya) Allah tidak menganiaya mereka, tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 270, 14, 108, 227, FALSE, 0, NULL),
(16, 34, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'So they were struck by the evil consequences of what they did and were enveloped by what they used to ridicule.', 'Oleh itu, mereka ditimpa azab sebagai balasan perbuatan jahat yang mereka lakukan; dan azab Allah itu meliputi mereka sebagai balasan bagi apa yang mereka telah ejek-ejek dahulu.', FALSE, NULL, NULL, 270, 14, 108, 227, FALSE, 0, NULL),
(16, 35, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'وَقَالَ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا مِن دُونِهِ مِن شَيْءٍ نَّحْنُ وَلَا آبَاؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِ مِن شَيْءٍ كَذَٰلِكَ فَعَلَ الَّذِينَ مِن قَبْلِهِمْ فَهَلْ عَلَى الرُّسُلِ إِلَّا الْبَلَاغُ الْمُبِينُ', NULL, 'And those who associate others with Allāh say, "If Allāh had willed, we would not have worshipped anything other than Him, neither we nor our fathers, nor would we have forbidden anything through other than Him." Thus did those do before them. So is there upon the messengers except [the duty of] clear notification?', 'Dan berkatalah orang-orang kafir musyrik: “Kalaulah Allah menghendaki, tentulah kami tidak menyembah selain daripadanya sesuatupun, - (tidak) kami dan tidak juga datuk nenek kami; - dan tentulah kami tidak mengharamkan sesuatu pun dengan ketiadaan perintahnya”. Demikianlah juga yang telah dilakukan oleh orang-orang yang terdahulu daripada mereka. (Apa yang mereka katakan itu adalah salah semata-mata) kerana bukankah Rasul-rasul semuanya tidak bertanggungjawab selain daripada menyampaikan (kehendak dan hukum Allah) dengan cara yang jelas nyata?', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 36, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ فَمِنْهُم مَّنْ هَدَى اللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُ فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ', NULL, 'And We certainly sent into every nation a messenger, [saying], "Worship Allāh and avoid ṭāghūt." And among them were those whom Allāh guided, and among them were those upon whom error was [deservedly] decreed. So proceed [i.e., travel] through the earth and observe how was the end of the deniers.', 'Dan sesungguhnya Kami telah mengutus dalam kalangan tiap-tiap umat seorang Rasul (dengan memerintahkannya menyeru mereka): “Hendaklah kamu menyembah Allah dan jauhilah Taghut”. Maka di antara mereka (yang menerima seruan Rasul itu), ada yang diberi hidayah petunjuk oIeh Allah dan ada pula yang berhak ditimpa kesesatan. Oleh itu mengembaralah kamu di bumi, kemudian lihatlah bagaimana buruknya kesudahan umat-umat yang mendustakan Rasul-rasulnya.', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 37, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'إِن تَحْرِصْ عَلَىٰ هُدَاهُمْ فَإِنَّ اللَّهَ لَا يَهْدِي مَن يُضِلُّ وَمَا لَهُم مِّن نَّاصِرِينَ', NULL, '[Even] if you should strive for their guidance, [O Muḥammad], indeed, Allāh does not guide those He sends astray, and they will have no helpers.', 'Jika engkau (wahai Muhammad) terlalu tamak (inginkan mereka beroleh hidayah petunjuk, maka sesungguhnya Allah tidak memberi hidayah petunjuk kepada orang-orang yang berhak disesatkanNya; dan tiadalah bagi mereka sesiapapun yang dapat memberikan pertolongan.', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 38, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَا يَبْعَثُ اللَّهُ مَن يَمُوتُ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'And they swear by Allāh their strongest oaths [that] Allāh will not resurrect one who dies. But yes - [it is] a true promise [binding] upon Him, but most of the people do not know.', 'Dan mereka bersumpah dengan nama Allah dengan bersungguh-sungguh (sambil berkata): “Allah tidak akan membangkitkan semula orang-orang yang telah mati”. (Itu tidak benar), bahkan janji Allah membangkitkan orang-orang yang telah mati) tetap benar; tetapi kebanyakan manusia tidak mengetahui.', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 39, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', 'لِيُبَيِّنَ لَهُمُ الَّذِي يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ الَّذِينَ كَفَرُوا أَنَّهُمْ كَانُوا كَاذِبِينَ', NULL, '[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars.', '(Allah menghidupkan semula orang-orang yang mati) untuk menerangkan kepada mereka apa yang mereka berselisihan padanya, dan supaya orang-orang kafir mengetahui bahawa mereka adalah orang-orang yang berdusta.', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 40, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', 'إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَن نَّقُولَ لَهُ كُن فَيَكُونُ', NULL, 'Indeed, Our word to a thing when We intend it is but that We say to it, "Be," and it is.', 'Sesungguhnya perkataan Kami kepada sesuatu apabila Kami kehendaki, hanyalah Kami berkata kepadanya: “Jadilah engkau!”, maka menjadilah ia.', FALSE, NULL, NULL, 271, 14, 108, 228, FALSE, 0, NULL),
(16, 41, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً وَلَأَجْرُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'وَالَّذِينَ هَاجَرُوا فِي اللَّهِ مِن بَعْدِ مَا ظُلِمُوا لَنُبَوِّئَنَّهُمْ فِي الدُّنْيَا حَسَنَةً وَلَأَجْرُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'And those who emigrated for [the cause of] Allāh after they had been wronged - We will surely settle them in this world in a good place; but the reward of the Hereafter is greater, if only they could know.', 'Dan orang-orang yang berhijrah kerana Allah, sesudah mereka dianiaya (ditindas oleh musuh-musuh Islam), Kami akan menempatkan mereka di dunia ini pada tempatnya yang baik; dan sesungguhnya pahala (amal mereka yang baik itu) lebih besar di akhirat kelak, kalaulah mereka mengetahui.', FALSE, NULL, NULL, 271, 14, 108, 229, FALSE, 0, NULL),
(16, 42, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'الَّذِينَ صَبَرُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', NULL, '[They are] those who endured patiently and upon their Lord relied.', 'Mereka itu ialah) orang-orang yang bersabar (menanggung kezaliman) dan berserah diri kepada Tuhannya.', FALSE, NULL, NULL, 271, 14, 108, 229, FALSE, 0, NULL),
(16, 43, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِمْ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', NULL, 'And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message [i.e., former scriptures] if you do not know.', 'Dan tidaklah Kami mengutus Rasul-rasul sebelummu (wahai Muhammad), melainkan dari kalangan orang-orang lelaki, yang Kami wahyukan kepada mereka. Oleh itu bertanyalah kamu (wahai golongan musyrik) kepada orang-orang yang berpengetahuan ugama jika kamu tidak mengetahui.', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 44, 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 'بِالْبَيِّنَاتِ وَالزُّبُرِ وَأَنزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', NULL, '[We sent them] with clear proofs and written ordinances. And We revealed to you the message [i.e., the Qur’ān] that you may make clear to the people what was sent down to them and that they might give thought.', '(Kami utuskan Rasul-rasul itu) membawa keterangan-keterangan yang jelas nyata (yang membuktikan kebenaran mereka) dan Kitab-kitab Suci (yang menjadi panduan); dan kami pula turunkan kepadamu (wahai Muhammad) Al-Quran yang memberi peringatan, supaya engkau menerangkan kepada umat manusia akan apa yang telah diturunkan kepada mereka, dan supaya mereka memikirkannya.', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 45, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'أَفَأَمِنَ الَّذِينَ مَكَرُوا السَّيِّئَاتِ أَن يَخْسِفَ اللَّهُ بِهِمُ الْأَرْضَ أَوْ يَأْتِيَهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', NULL, 'Then, do those who have planned evil deeds feel secure that Allāh will not cause the earth to swallow them or that the punishment will not come upon them from where they do not perceive?', '(Setelah diterangkan yang demikian) maka adakah orang-orang yang merancang dan melakukan kejahatan-kejahatan itu merasa aman daripada ditimbuskan oleh Allah akan mereka ke dalam bumi, atau mereka didatangi azab dari arah yang mereka tidak menyedarinya?', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 46, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', 'أَوْ يَأْخُذَهُمْ فِي تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', NULL, 'Or that He would not seize them during their [usual] activity, and they could not cause failure [i.e., escape from Him]?', 'Atau Ia membinasakan mereka secara mengejut dalam masa mereka berulang alik melakukan kerja masing-masing? Kerana sebenarnya mereka tidak akan dapat melemahkan kuasa Allah.', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 47, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', NULL, 'Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful.', 'Atau Ia membinasakan mereka (dan harta benda mereka) sedikit demi sedikit? Kerana sesungguhnya Tuhan kamu Amat melimpah belas kasihan dan rahmatNya.', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 48, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 'أَوَلَمْ يَرَوْا إِلَىٰ مَا خَلَقَ اللَّهُ مِن شَيْءٍ يَتَفَيَّأُ ظِلَالُهُ عَنِ الْيَمِينِ وَالشَّمَائِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَاخِرُونَ', NULL, 'Have they not considered what things Allāh has created? Their shadows incline to the right and to the left, prostrating to Allāh, while they [i.e., those creations] are humble.', 'Tidakkah mereka melihat dan memikirkan segala yang telah dijadikan oleh Allah, yang beredar (berpindah-randah) bayang-bayangnya ke kanan dan ke kiri (pada pagi dan petang), dengan keadaan tunduk menurut peraturan dan kehendak Allah, sedang mereka merendah diri?', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 49, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 'وَلِلَّهِ يَسْجُدُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مِن دَابَّةٍ وَالْمَلَائِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', NULL, 'And to Allāh prostrates whatever is in the heavens and whatever is on the earth of creatures, and the angels [as well], and they are not arrogant.', 'Dan bagi Allah jualah tunduk sujud apa yang ada di langit dan yang ada di bumi, dari makhluk-makhluk yang bergerak serta malaikat; sedang mereka (malaikat-malaikat itu) tidak berlaku sombong takbur (daripada beribadat dan sujud kepadaNya).', FALSE, NULL, NULL, 272, 14, 108, 229, FALSE, 0, NULL),
(16, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', NULL, 'They fear their Lord above them, and they do what they are commanded.', 'Mereka takut kepada Tuhan mereka yang mengatasi mereka (dengan kekuasaanNya), serta mereka mengerjakan apa yang diperintahkan.', FALSE, NULL, NULL, 272, 14, 108, 229, TRUE, 0, NULL),
(16, 51, 'وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰىَ فَٱرْهَبُونِ', 'وَقَالَ اللَّهُ لَا تَتَّخِذُوا إِلَٰهَيْنِ اثْنَيْنِ إِنَّمَا هُوَ إِلَٰهٌ وَاحِدٌ فَإِيَّايَ فَارْهَبُونِ', NULL, 'And Allāh has said, "Do not take for yourselves two deities. He [i.e., Allāh] is but one God, so fear only Me."', 'Dan Allah berfirman: “Janganlah kamu bertuhankan dua tuhan, kerana sesungguhnya Tuhan itu hanyalah Tuhan yang satu; maka kepada Akulah sahaja hendaknya kamu gerun gementar.', FALSE, NULL, NULL, 272, 14, 109, 230, FALSE, 0, NULL),
(16, 52, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 'وَلَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَلَهُ الدِّينُ وَاصِبًا أَفَغَيْرَ اللَّهِ تَتَّقُونَ', NULL, 'And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allāh that you fear?', 'Dan bagiNyalah (hak milik) segala yang ada di langit dan di bumi; dan kepadaNya sahaja tertentu ibadat dan ketaatan selama-lamanya; (sesudah kamu mengetahui yang demikian) maka tidaklah patut kamu takut kepada yang lain dari Allah.', FALSE, NULL, NULL, 272, 14, 109, 230, FALSE, 0, NULL),
(16, 53, 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ اللَّهِ ثُمَّ إِذَا مَسَّكُمُ الضُّرُّ فَإِلَيْهِ تَجْأَرُونَ', NULL, 'And whatever you have of favor - it is from Allāh. Then when adversity touches you, to Him you cry for help.', 'Dan apa-apa nikmat yang ada pada kamu maka adalah ia dari Allah; kemudian, apabila kamu ditimpa kesusahan maka kepadaNyalah kamu meraung meminta pertolongan.', FALSE, NULL, NULL, 272, 14, 109, 230, FALSE, 0, NULL),
(16, 54, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'ثُمَّ إِذَا كَشَفَ الضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', NULL, 'Then when He removes the adversity from you, at once a party of you associates others with their Lord', 'Kemudian, apabila Ia menghapuskan kesusahan itu daripada kamu, tiba-tiba sepuak di antara kamu mempersekutukan (sesuatu yang lain) dengan Tuhan mereka.', FALSE, NULL, NULL, 272, 14, 109, 230, FALSE, 0, NULL),
(16, 55, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ فَتَمَتَّعُوا فَسَوْفَ تَعْلَمُونَ', NULL, 'So they will deny what We have given them. Then enjoy yourselves, for you are going to know.', '(Mereka melakukan yang demikian) kerana mereka kufur, tidak bersyukur akan nikmat-nikmat yang kami berikan kepada mereka. Oleh itu, bersenang-senanglah kamu (dengan nikmat-nikmat itu bagi sementara di dunia), kemudian kamu akan mengetahui (balasan buruk yang akan menimpa kamu).', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَٰهُمْ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَاهُمْ تَاللَّهِ لَتُسْأَلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', NULL, 'And they assign to what they do not know [i.e., false deities] a portion of that which We have provided them. By Allāh, you will surely be questioned about what you used to invent.', 'Dan mereka (yang musyrik itu) menentukan untuk keperluan benda-benda yang mereka tidak mengetahui hal keadaannya, sebahagian dari harta-benda yang kami kurniakan kepada mereka. Demi Allah! Sesungguhnya kamu akan ditanya kelak tentang apa yang kamu ada-adakan secara dusta itu.', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 57, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ وَلَهُم مَّا يَشْتَهُونَ', 'وَيَجْعَلُونَ لِلَّهِ الْبَنَاتِ سُبْحَانَهُ وَلَهُم مَّا يَشْتَهُونَ', NULL, 'And they attribute to Allāh daughters - exalted is He - and for them is what they desire [i.e., sons].', 'Dan mereka mengatakan Allah mempunyai anak-anak perempuan. Maha Suci Ia. Sedang bagi mereka pula mereka sediakan apa yang mereka sukai (anak-anak lelaki).', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'وَإِذَا بُشِّرَ أَحَدُهُم بِالْأُنثَىٰ ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ', NULL, 'And when one of them is informed of [the birth of] a female, his face becomes dark, and he suppresses grief.', 'Dan apabila dikhabarkan kepada seseorang dari mereka bahawa ia beroleh anak perempuan, muramlah mukanya sepanjang hari (kerana menanggung dukacita), sedang ia menahan perasaan marahnya dalam hati.', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 59, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ أَلَا سَآءَ مَا يَحْكُمُونَ', 'يَتَوَارَىٰ مِنَ الْقَوْمِ مِن سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَىٰ هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ أَلَا سَاءَ مَا يَحْكُمُونَ', NULL, 'He hides himself from the people because of the ill of which he has been informed. Should he keep it in humiliation or bury it in the ground? Unquestionably, evil is what they decide.', 'Ia bersembunyi dari orang ramai kerana (merasa malu disebabkan) berita buruk yang disampaikan kepadanya (tentang ia beroleh anak perempuan; sambil ia berfikir): adakah ia akan memelihara anak itu dalam keadaan yang hina, atau ia akan menanamnya hidup-hidup dalam tanah? Ketahuilah! Sungguh jahat apa yang mereka hukumkan itu.', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 60, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ مَثَلُ ٱلسَّوْءِ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ وَلِلَّهِ الْمَثَلُ الْأَعْلَىٰ وَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'For those who do not believe in the Hereafter is the description [i.e., an attribute] of evil; and for Allāh is the highest attribute. And He is Exalted in Might, the Wise.', 'Bagi mereka yang tidak beriman kepada hari akhirat itu, sifat yang buruk, dan bagi Allah jualah sifat yang tertinggi; dan Dia lah jua Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 273, 14, 109, 230, FALSE, 0, NULL),
(16, 61, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَابَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰ أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', NULL, 'And if Allāh were to impose blame on the people for their wrongdoing, He would not have left upon it [i.e., the earth] any creature, but He defers them for a specified term. And when their term has come, they will not remain behind an hour, nor will they precede [it].', 'Dan kalaulah Allah menyeksa manusia disebabkan kezaliman mereka, tentulah Ia tidak membiarkan tinggal di muka bumi sesuatu makhluk yang bergerak; akan tetapi Ia memberi tempoh kepada mereka hingga ke suatu masa yang tertentu; kemudian apabila sampai tempoh mereka, tiadalah mereka akan dapat meminta dikemudiankan sesaatpun dan tidak pula mereka akan dapat meminta didahulukan.', FALSE, NULL, NULL, 273, 14, 109, 231, FALSE, 0, NULL),
(16, 62, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ الْكَذِبَ أَنَّ لَهُمُ الْحُسْنَىٰ لَا جَرَمَ أَنَّ لَهُمُ النَّارَ وَأَنَّهُم مُّفْرَطُونَ', NULL, 'And they attribute to Allāh that which they dislike [i.e., daughters], and their tongues assert the lie that they will have the best [from Him]. Assuredly, they will have the Fire, and they will be [therein] neglected.', 'Dan mereka mengadakan bagi Allah apa yang mereka sendiri tidak menyukainya; dalam pada itu, lidah mereka memperkatakan perkara yang dusta, (kononnya) bahawa mereka akan beroleh kesudahan yang baik di sisi Allah. Tidak syak lagi, bahawa bagi merekalah api neraka, dan bahawa merekalah orang-orang yang disegerakan (masuknya ke dalam neraka).', FALSE, NULL, NULL, 273, 14, 109, 231, FALSE, 0, NULL),
(16, 63, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'تَاللَّهِ لَقَدْ أَرْسَلْنَا إِلَىٰ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَهُوَ وَلِيُّهُمُ الْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'By Allāh, We did certainly send [messengers] to nations before you, but Satan made their deeds attractive to them. And he is their [i.e., the disbelievers] ally today [as well], and they will have a painful punishment.', 'Demi Allah! Sesungguhnya kami juga telah mengutus Rasul-rasul kepada umat-umat yang terdahulu daripadamu (wahai Muhammad), lalu Syaitan memperelokkan pada pandangan mereka yang ingkar akan amal-amal mereka yang jahat itu; maka dia lah menjadi pemimpin mereka pada hari ini; dan mereka akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 273, 14, 109, 231, FALSE, 0, NULL),
(16, 64, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'وَمَا أَنزَلْنَا عَلَيْكَ الْكِتَابَ إِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا فِيهِ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'And We have not revealed to you the Book, [O Muḥammad], except for you to make clear to them that wherein they have differed and as guidance and mercy for a people who believe.', 'Dan tiadalah Kami menurunkan Al-Quran kepadamu (wahai Muhammad) melainkan supaya engkau menerangkan kepada mereka akan apa yang mereka berselisihan padanya; dan supaya menjadi petunjuk dan rahmat bagi orang-orang yang beriman.', FALSE, NULL, NULL, 273, 14, 109, 231, FALSE, 0, NULL),
(16, 65, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَسْمَعُونَ', 'وَاللَّهُ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ فِي ذَٰلِكَ لَآيَةً لِّقَوْمٍ يَسْمَعُونَ', NULL, 'And Allāh has sent down rain from the sky and given life thereby to the earth after its lifelessness. Indeed in that is a sign for a people who listen.', 'Dan Allah menurunkan hujan dari langit, lalu Ia menghidupkan dengan air hujan itu akan bumi sesudah matinya; sesungguhnya pada yang demikian itu terdapat satu tanda (yang membuktikan kebijaksanaan Allah) bagi kaum yang mendengar (peringatan ini dan memahaminya).', FALSE, NULL, NULL, 274, 14, 109, 231, FALSE, 0, NULL),
(16, 66, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّٰرِبِينَ', 'وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ مِن بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَائِغًا لِّلشَّارِبِينَ', NULL, 'And indeed, for you in grazing livestock is a lesson. We give you drink from what is in their bellies - between excretion and blood - pure milk, palatable to drinkers.', 'Dan sesungguhnya pada binatang-binatang ternak itu, kamu beroleh pelajaran yang mendatangkan iktibar. Kami beri minum kepada kamu daripada apa yang terbit dari dalam perutnya, yang lahir dari antara hampas makanan dengan darah; (iaitu) susu yang bersih, yang mudah diminum, lagi sedap rasanya bagi orang-orang yang meminumnya.', FALSE, NULL, NULL, 274, 14, 109, 232, FALSE, 0, NULL),
(16, 67, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْقِلُونَ', 'وَمِن ثَمَرَاتِ النَّخِيلِ وَالْأَعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِي ذَٰلِكَ لَآيَةً لِّقَوْمٍ يَعْقِلُونَ', NULL, 'And from the fruits of the palm trees and grapevines you take intoxicant and good provision. Indeed in that is a sign for a people who reason.', 'Dan dari buah tamar (kurma) dan anggur kamu jadikan daripadanya minuman haram dan makanan serta minuman yang halal; sesungguhnya pada yang demikian itu terdapat satu tanda (yang membuktikan kekuasaan Allah) bagi orang-orang yang mahu menggunakan akalnya.', FALSE, NULL, NULL, 274, 14, 109, 232, FALSE, 0, NULL),
(16, 68, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', 'وَأَوْحَىٰ رَبُّكَ إِلَى النَّحْلِ أَنِ اتَّخِذِي مِنَ الْجِبَالِ بُيُوتًا وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَ', NULL, 'And your Lord inspired to the bee, "Take for yourself among the mountains, houses [i.e., hives], and among the trees and [in] that which they construct.', 'Dan Tuhanmu memberi ilham kepada lebah: “Hendaklah engkau membuat sarangmu di gunung-ganang dan di pokok-pokok kayu, dan juga di bangunan-bangunan yang didirikan oleh manusia.', FALSE, NULL, NULL, 274, 14, 109, 232, FALSE, 0, NULL),
(16, 69, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'ثُمَّ كُلِي مِن كُلِّ الثَّمَرَاتِ فَاسْلُكِي سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِن بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَانُهُ فِيهِ شِفَاءٌ لِّلنَّاسِ إِنَّ فِي ذَٰلِكَ لَآيَةً لِّقَوْمٍ يَتَفَكَّرُونَ', NULL, 'Then eat from all the fruits and follow the ways of your Lord laid down [for you]." There emerges from their bellies a drink, varying in colors, in which there is healing for people. Indeed in that is a sign for a people who give thought.', 'Kemudian makanlah dari segala jenis bunga-bungaan dan buah-buahan (yang engkau sukai), serta turutlah jalan-jalan peraturan Tuhanmu yang diilhamkan dan dimudahkannya kepadamu”. (Dengan itu) akan keluarlah dari dalam badannya minuman (madu) yang berlainan warnanya, yang mengandungi penawar bagi manusia (dari berbagai-bagai penyakit). Sesungguhnya pada yang demikian itu, ada tanda (yang membuktikan kemurahan Allah) bagi orang-orang yang mahu berfikir.', FALSE, NULL, NULL, 274, 14, 109, 232, FALSE, 0, NULL),
(16, 70, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ', 'وَاللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَىٰ أَرْذَلِ الْعُمُرِ لِكَيْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْئًا إِنَّ اللَّهَ عَلِيمٌ قَدِيرٌ', NULL, 'And Allāh created you; then He will take you in death. And among you is he who is reversed to the most decrepit [old] age so that he will not know, after [having had] knowledge, a thing. Indeed, Allāh is Knowing and Competent.', 'Dan Allah yang menciptakan kamu (dari tiada kepada ada); kemudian Ia menyempurnakan tempoh umur kamu; (maka ada di antara kamu yang disegerakan matinya), dan ada pula di antara kamu yang dikembalikannya kepada peringkat umur yang lemah (peringkat tua kebudak-budakan), sehingga menjadilah ia tidak ingat akan sesuatu yang telah diketahuinya; sesungguhnya Allah Maha Mengetahui, lagi Maha Kuasa.', FALSE, NULL, NULL, 274, 14, 109, 232, FALSE, 0, NULL),
(16, 71, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', 'وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِي الرِّزْقِ فَمَا الَّذِينَ فُضِّلُوا بِرَادِّي رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَانُهُمْ فَهُمْ فِيهِ سَوَاءٌ أَفَبِنِعْمَةِ اللَّهِ يَجْحَدُونَ', NULL, 'And Allāh has favored some of you over others in provision. But those who were favored [i.e., given more] would not hand over their provision to those whom their right hands possess [i.e., slaves] so they would be equal to them therein. Then is it the favor of Allāh they reject?', 'Dan Allah telah melebihkan sebahagian dari kamu atas sebahagian yang lain pada rezeki yang dikurniakanNya; dalam pada itu, orang-orang yang diberi kelebihan itu tidak mahu memberikan sebahagian dari kelebihan hartanya kepada hamba-hamba mereka, supaya orang-orang itu dapat sama mempunyai harta. Maka mengapa mereka tergamak mengingkari nikmat Allah itu dengan perbuatan syirik?', FALSE, NULL, NULL, 274, 14, 109, 233, FALSE, 0, NULL),
(16, 72, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', 'وَاللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجًا وَجَعَلَ لَكُم مِّنْ أَزْوَاجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ الطَّيِّبَاتِ أَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ اللَّهِ هُمْ يَكْفُرُونَ', NULL, 'And Allāh has made for you from yourselves mates and has made for you from your mates sons and grandchildren and has provided for you from the good things. Then in falsehood do they believe and in the favor of Allāh they disbelieve?', 'Dan Allah menjadikan bagi kamu dari diri kamu sendiri pasangan-pasangan (isteri), dan dijadikan bagi kamu dari pasangan kamu: anak-anak dan cucu-cicit, serta dikurniakan kepada kamu dari benda yang baik lagi halal; maka patutkah mereka (yang ingkar itu) percaya kepada perkara yang salah (penyembahan berhala), dan mereka kufur pula akan nikmat Allah?', FALSE, NULL, NULL, 274, 14, 109, 233, FALSE, 0, NULL),
(16, 73, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ', 'وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ السَّمَاوَاتِ وَالْأَرْضِ شَيْئًا وَلَا يَسْتَطِيعُونَ', NULL, 'And they worship besides Allāh that which does not possess for them [the power of] provision from the heavens and the earth at all, and [in fact], they are unable.', 'Dan mereka menyembah benda-benda yang lain dari Allah, yang tidak berkuasa memberikan mereka sebarang rezeki pemberian dari langit dan bumi, dan mereka pula tidak berdaya sama sekali mendapat kuasa itu.', FALSE, NULL, NULL, 275, 14, 109, 233, FALSE, 0, NULL),
(16, 74, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', NULL, 'So do not assert similarities to Allāh. Indeed, Allāh knows and you do not know.', 'Oleh itu, janganlah kamu mengadakan sesuatu yang sebanding dengan Allah, kerana sesungguhnya Allah mengetahui (setakat mana buruknya perbuatan syirik kamu) sedang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 275, 14, 109, 233, FALSE, 0, NULL),
(16, 75, 'ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُۥنَ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ضَرَبَ اللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَيْءٍ وَمَن رَّزَقْنَاهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُونَ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', NULL, 'Allāh presents an example: a slave [who is] owned and unable to do a thing and he to whom We have provided from Us good provision, so he spends from it secretly and publicly. Can they be equal? Praise to Allāh! But most of them do not know.', 'Allah memberikan satu misal perbandingan: Seorang hamba abdi yang menjadi milik orang, yang tidak berkuasa melakukan dengan bebasnya sesuatupun; dan seorang lagi (yang merdeka) yang Kami kurniakan kepadanya pemberian yang baik (harta kekayaan) dari Kami, maka dia pun membelanjakan hartanya dengan bebasnya, sama ada secara bersembunyi atau terbuka, adakah kedua orang itu sama? Segala puji tertentu bagi Allah (dan Allah jualah yang berhak disembah), tetapi kebanyakan mereka (yang musyrik) tidak mengetahui (hakikat tauhid itu).', FALSE, NULL, NULL, 275, 14, 110, 233, FALSE, 0, NULL),
(16, 76, 'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَضَرَبَ اللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَا أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَيْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَاهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِي هُوَ وَمَن يَأْمُرُ بِالْعَدْلِ وَهُوَ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And Allāh presents an example of two men, one of them dumb and unable to do a thing, while he is a burden to his guardian. Wherever he directs him, he brings no good. Is he equal to one who commands justice, while he is on a straight path?', 'Dan Allah memberikan satu misal perbandingan lagi: Dua orang lelaki, salah seorangnya kelu pekak dari semulajadinya, tidak dapat menyatakan apa yang difikirkannya dan tidak dapat mendengar apa yang dikatakan kepadanya; dan ia pula menjadi beban kepada orang yang menjaganya; ke mana sahaja ia diarahkan pergi oleh penjaganya, tak dapatlah dia membawa sesuatu yang berfaedah; adakah dia (yang demikian sifatnya) sama seperti orang (yang boleh berkata-kata serta dapat) menyuruh orang ramai melakukan keadilan, dan ia sendiri pula berada di atas jalan yang lurus (jalan yang benar)?', FALSE, NULL, NULL, 275, 14, 110, 233, FALSE, 0, NULL),
(16, 77, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَلِلَّهِ غَيْبُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا أَمْرُ السَّاعَةِ إِلَّا كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'And to Allāh belongs the unseen [aspects] of the heavens and the earth. And the command for the Hour is not but as a glance of the eye or even nearer. Indeed, Allāh is over all things competent.', 'Dan (ingatlah), Allah jualah yang mengetahui segala rahsia langit dan bumi; tiadalah hal kedatangan hari kiamat itu melainkan seperti sekelip mata, atau ia lebih cepat lagi; sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 275, 14, 110, 234, FALSE, 0, NULL),
(16, 78, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ لَعَلَّكُمْ تَشْكُرُونَ', 'وَاللَّهُ أَخْرَجَكُم مِّن بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And Allāh has extracted you from the wombs of your mothers not knowing a thing, and He made for you hearing and vision and hearts [i.e., intellect] that perhaps you would be grateful.', 'Dan Allah mengeluarkan kamu dari perut ibu kamu dengan keadaan tidak mengetahui sesuatupun; dan dia mengurniakan kepada kamu pendengaran dan penglihatan serta hati akal fikiran); supaya kamu bersyukur.', FALSE, NULL, NULL, 275, 14, 110, 234, FALSE, 0, NULL),
(16, 79, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'أَلَمْ يَرَوْا إِلَى الطَّيْرِ مُسَخَّرَاتٍ فِي جَوِّ السَّمَاءِ مَا يُمْسِكُهُنَّ إِلَّا اللَّهُ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'Do they not see the birds controlled in the atmosphere of the sky? None holds them up except Allāh. Indeed in that are signs for a people who believe.', 'Tidakkah mereka memperhatikan burung-burung yang dimudahkan terbang melayang-layang di angkasa? Tiada yang menahan mereka (dari jatuh) melainkan Allah; sesungguhnya pada yang demikian itu, ada tanda-tanda (yang membuktikan kekuasaan Allah) bagi kaum yang beriman.', FALSE, NULL, NULL, 275, 14, 110, 234, FALSE, 0, NULL),
(16, 80, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًا وَمَتَٰعًا إِلَىٰ حِينٍ', 'وَاللَّهُ جَعَلَ لَكُم مِّن بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ الْأَنْعَامِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَا أَثَاثًا وَمَتَاعًا إِلَىٰ حِينٍ', NULL, 'And Allāh has made for you from your homes a place of rest and made for you from the hides of the animals tents which you find light on your day of travel and your day of encampment; and from their wool, fur and hair is furnishing and enjoyment [i.e., provision] for a time.', 'Dan Allah menjadikan bagi kamu rumah-rumah (yang kamu dirikan itu) tempat tinggal; dan Ia menjadikan bagi kamu dari kulit binatang-binatang ternak: khemah-khemah (tempat berteduh), yang kamu mendapatinya ringan (di bawa ke mana-mana) semasa kamu merantau dan semasa kamu berhenti; dan (Ia juga menjadikan bagi kamu) dari berjenis-jenis bulu binatang-binatang ternak itu, berbagai barang perkakas rumah dan perhiasan, (untuk kamu menggunakannya) hingga ke suatu masa.', FALSE, NULL, NULL, 276, 14, 110, 234, FALSE, 0, NULL),
(16, 81, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', 'وَاللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَالًا وَجَعَلَ لَكُم مِّنَ الْجِبَالِ أَكْنَانًا وَجَعَلَ لَكُمْ سَرَابِيلَ تَقِيكُمُ الْحَرَّ وَسَرَابِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', NULL, 'And Allāh has made for you, from that which He has created, shadows [i.e., shade] and has made for you from the mountains, shelters and has made for you garments which protect you from the heat and garments [i.e., coats of mail] which protect you from your [enemy in] battle. Thus does He complete His favor upon you that you might submit [to Him].', 'Dan Allah menjadikan bagi kamu sebahagian dari yang diciptakanNya: benda-benda untuk berteduh, dan Ia menjadikan bagi kamu sebahagian dari gunung-ganang tempat-tempat berlindung; dan Ia juga menjadikan bagi kamu pakaian-pakaian yang memelihara kamu dari panas dan sejuk, juga pakaian-pakaian yang memelihara kamu semasa berjuang. Demikianlah, Ia menyempurnakan nikmatNya kepada kamu, supaya kamu berserah diri kepadaNya dan mematuhi perintahNya.', FALSE, NULL, NULL, 276, 14, 110, 234, FALSE, 0, NULL),
(16, 82, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', 'فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْكَ الْبَلَاغُ الْمُبِينُ', NULL, 'But if they turn away, [O Muḥammad] - then only upon you is [responsibility for] clear notification.', 'Kemudian, jika mereka masih berpaling ingkar maka sesungguhnya engkau (wahai Muhammad) hanya bertanggungjawab menyampaikan perintah-perintah Allah dengan cara yang jelas nyata.', FALSE, NULL, NULL, 276, 14, 110, 234, FALSE, 0, NULL),
(16, 83, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 'يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ الْكَافِرُونَ', NULL, 'They recognize the favor of Allāh; then they deny it. And most of them are disbelievers.', 'Mereka mengetahui nikmat Allah (yang melimpah-limpah itu), kemudian mereka tergamak mengingkarinya; dan kebanyakan mereka pula ialah orang-orang yang kufur ingkar.', FALSE, NULL, NULL, 276, 14, 110, 234, FALSE, 0, NULL),
(16, 84, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا وَلَا هُمْ يُسْتَعْتَبُونَ', NULL, 'And [mention] the Day when We will resurrect from every nation a witness [i.e., their prophet]. Then it will not be permitted to the disbelievers [to apologize or make excuses], nor will they be asked to appease [Allāh].', 'Dan (ingatkanlah kepada mereka yang musyrik tentang) hari Kami bangkitkan dari tiap-tiap umat, seorang saksi; kemudian tidak diizinkan bagi orang-orang yang kafir (memberi sebarang alasan), dan mereka pula tidak diminta memohon keredaan Allah.', FALSE, NULL, NULL, 276, 14, 110, 235, FALSE, 0, NULL),
(16, 85, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', 'وَإِذَا رَأَى الَّذِينَ ظَلَمُوا الْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', NULL, 'And when those who wronged see the punishment, it will not be lightened for them, nor will they be reprieved.', 'Dan apabila orang-orang yang melakukan kezaliman (dengan kekufurannya) itu melihat azab, maka tidak akan diringankan azab itu daripada mereka, dan mereka pula tidak diberi tempoh.', FALSE, NULL, NULL, 276, 14, 110, 235, FALSE, 0, NULL),
(16, 86, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 'وَإِذَا رَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ قَالُوا رَبَّنَا هَٰؤُلَاءِ شُرَكَاؤُنَا الَّذِينَ كُنَّا نَدْعُو مِن دُونِكَ فَأَلْقَوْا إِلَيْهِمُ الْقَوْلَ إِنَّكُمْ لَكَاذِبُونَ', NULL, 'And when those who associated others with Allāh see their "partners," they will say, "Our Lord, these are our partners [to You] whom we used to invoke [in worship] besides You." But they will throw at them the statement, "Indeed, you are liars."', 'Dan apabila orang-orang musyrik melihat makhluk-makhluk dan benda-benda yang mereka jadikan sekutu-sekutu Allah, mereka berkata: “Wahai Tuhan kami, inilah dia yang kami jadikan sekutu-sekutu (bagiMu), yang kami sembah mereka dengan meninggalkanMu”. Maka dengan serta-merta makhluk-makhluk yang puja itu menolak dakwaan mereka dengan berkata: “Sesungguhnya kamu adalah berdusta”.', FALSE, NULL, NULL, 276, 14, 110, 235, FALSE, 0, NULL),
(16, 87, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'وَأَلْقَوْا إِلَى اللَّهِ يَوْمَئِذٍ السَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'And they will impart to Allāh that Day [their] submission, and lost from them is what they used to invent.', 'Dan pada hari itu mereka semua menyerah diri bulat-bulat kepada Allah, dan hilang lenyaplah dari mereka (yang musyrik itu) apa yang telah mereka ada-adakan (sebagai sekutu-sekutu Allah).', FALSE, NULL, NULL, 276, 14, 110, 235, FALSE, 0, NULL),
(16, 88, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', 'الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ بِمَا كَانُوا يُفْسِدُونَ', NULL, 'Those who disbelieved and averted [others] from the way of Allāh - We will increase them in punishment over [their] punishment for what corruption they were causing.', 'Orang-orang yang kafir dan menghalangi (dirinya serta orang lain) dari jalan Allah, Kami tambahi mereka azab seksa di samping azab (yang menimpa mereka), disebabkan mereka membuat kerosakan.', FALSE, NULL, NULL, 277, 14, 110, 235, FALSE, 0, NULL),
(16, 89, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'وَيَوْمَ نَبْعَثُ فِي كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰؤُلَاءِ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِّكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', NULL, 'And [mention] the Day when We will resurrect among every nation a witness over them from themselves [i.e., their prophet]. And We will bring you, [O Muḥammad], as a witness over these [i.e., your nation]. And We have sent down to you the Book as clarification for all things and as guidance and mercy and good tidings for the Muslims.', 'Dan (ingatkanlah tentang) hari Kami bangkitkan dalam kalangan tiap-tiap umat, seorang saksi terhadap mereka, dari golongan mereka sendiri; dan Kami datangkanmu (wahai Muhammad) untuk menjadi saksi terhadap mereka ini (umatmu); dan Kami turunkan kepadamu Al-Quran menjelaskan tiap-tiap sesuatu dan menjadi hidayah petunjuk, serta membawa rahmat dan berita yang mengembirakan, bagi orang-orang Islam.', FALSE, NULL, NULL, 277, 14, 110, 235, FALSE, 0, NULL),
(16, 90, 'إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَىٰ وَيَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', NULL, 'Indeed, Allāh orders justice and good conduct and giving [help] to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded.', 'Sesungguhnya Allah menyuruh berlaku adil, dan berbuat kebaikan, serta memberi bantuan kepada kaum kerabat; dan melarang daripada melakukan perbuatan-perbuatan yang keji dan mungkar serta kezaliman. Ia mengajar kamu (dengan suruhan dan laranganNya ini), supaya kamu mengambil peringatan mematuhiNya.', FALSE, NULL, NULL, 277, 14, 111, 236, FALSE, 0, NULL),
(16, 91, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', 'وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدتُّمْ وَلَا تَنقُضُوا الْأَيْمَانَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ اللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', NULL, 'And fulfill the covenant of Allāh when you have taken it, [O believers], and do not break oaths after their confirmation while you have made Allāh, over you, a security [i.e., witness]. Indeed, Allāh knows what you do.', 'Dan sempurnakanlah pesanan-pesanan dan perintah-perintah Allah apabila kamu berjanji; dan janganlah kamu merombak (mencabuli) sumpah kamu sesudah kamu menguatkannya (dengan nama Allah), sedang kamu telah menjadikan Allah sebagai Penjamin kebaikan kamu; sesungguhnya Allah sedia mengetahui akan apa yang kamu lakukan.', FALSE, NULL, NULL, 277, 14, 111, 236, FALSE, 0, NULL),
(16, 92, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'وَلَا تَكُونُوا كَالَّتِي نَقَضَتْ غَزْلَهَا مِن بَعْدِ قُوَّةٍ أَنكَاثًا تَتَّخِذُونَ أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِيَ أَرْبَىٰ مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ الْقِيَامَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', NULL, 'And do not be like she who untwisted her spun thread after it was strong [by] taking your oaths as [means of] deceit between you because one community is more plentiful [in number or wealth] than another community. Allāh only tries you thereby. And He will surely make clear to you on the Day of Resurrection that over which you used to differ.', 'Dan janganlah kamu menjadi seperti perempuan yang telah merombak satu persatu benda yang dipintalnya, sesudah ia selesai memintalnya kuat teguh; dengan kamu menjadikan sumpah kamu sebagai tipu daya (untuk mencabuli perjanjian yang telah dimeteraikan) sesama kamu, disebabkan adanya satu golongan yang lebih ramai dari golongan lain. Sesungguhnya Allah hanya mahu menguji kamu dengan yang demikian itu; dan Ia sudah tentu akan menerangkan kepada kamu, pada hari kiamat, apa yang kamu berselisihan padanya.', FALSE, NULL, NULL, 277, 14, 111, 236, FALSE, 0, NULL),
(16, 93, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', 'وَلَوْ شَاءَ اللَّهُ لَجَعَلَكُمْ أُمَّةً وَاحِدَةً وَلَٰكِن يُضِلُّ مَن يَشَاءُ وَيَهْدِي مَن يَشَاءُ وَلَتُسْأَلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', NULL, 'And if Allāh had willed, He could have made you [of] one religion, but He sends astray whom He wills and guides whom He wills. And you will surely be questioned about what you used to do.', 'Dan jika Allah menghendaki, tentulah Dia menjadikan kamu satu umat (yang bersatu dalam ugama Allah yang satu); akan tetapi Allah menyesatkan sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya) dan memberi petunjuk kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan sesungguhnya kamu akan ditanya kelak tentang apa yang kamu telah kerjakan.', FALSE, NULL, NULL, 277, 14, 111, 236, FALSE, 0, NULL),
(16, 94, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ', 'وَلَا تَتَّخِذُوا أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا السُّوءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ اللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ', NULL, 'And do not take your oaths as [means of] deceit between you, lest a foot slip after it was [once] firm, and you would taste evil [in this world] for what [people] you diverted from the way of Allāh, and you would have [in the Hereafter] a great punishment.', 'Dan janganlah kamu jadikan sumpah kamu sebagai tipu daya sesama kamu, kerana dengan yang demikian itu akan menyebabkan tergelincir kaki kamu sesudah ia tetap teguh (di atas jalan yang benar); dan kamu pula akan merasai balasan buruk (di dunia) dengan sebab kamu menghalangi manusia dari jalan Allah; dan bagi kamu juga disediakan azab yang besar (di akhirat kelak).', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 95, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'وَلَا تَشْتَرُوا بِعَهْدِ اللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ اللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', NULL, 'And do not exchange the covenant of Allāh for a small price. Indeed, what is with Allāh is best for you, if only you could know.', 'Dan janganlah kamu jadikan pesanan-pesanan dan perintah Allah sebagai modal untuk mendapat keuntungan dunia yang sedikit; sesugguhnya apa yang ada di sisi Allah (dari balasan yang baik), itulah sahaja yang lebih baik bagi kamu, kalaulah kamu mengetahui.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 96, 'مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٍ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ اللَّهِ بَاقٍ وَلَنَجْزِيَنَّ الَّذِينَ صَبَرُوا أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ', NULL, 'Whatever you have will end, but what Allāh has is lasting. And We will surely give those who were patient their reward according to the best of what they used to do.', '(Sebenarnya) apa yang ada pada kamu akan habis dan hilang lenyap, dan apa yang ada di sisi Allah tetap kekal; dan sesungguhnya Kami membalas orang-orang sabar dengan memberikan pahala yang lebih baik dari apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 97, 'مَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ', NULL, 'Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do.', 'Sesiapa yang beramal soleh, dari lelaki atau perempuan, sedang ia beriman, maka sesungguhnya Kami akan menghidupkan dia dengan kehidupan yang baik; dan sesungguhnya kami akan membalas mereka, dengan memberikan pahala yang lebih dari apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 98, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', NULL, 'So when you recite the Qur’ān, [first] seek refuge in Allāh from Satan, the expelled [from His mercy].', 'Oleh itu, apabila engkau membaca Al-Quran, maka hendaklah engkau terlebih dahulu) memohon perlindungan kepada Allah dari hasutan Syaitan yang kena rejam.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 99, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'إِنَّهُ لَيْسَ لَهُ سُلْطَانٌ عَلَى الَّذِينَ آمَنُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', NULL, 'Indeed, there is for him no authority over those who have believed and rely upon their Lord.', 'Sesungguhnya Syaitan itu tidak mempunyai sebarang pengaruh terhadap orang-orang yang beriman dan yang berserah bulat-bulat kepada Tuhan mereka.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(16, 100, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 'إِنَّمَا سُلْطَانُهُ عَلَى الَّذِينَ يَتَوَلَّوْنَهُ وَالَّذِينَ هُم بِهِ مُشْرِكُونَ', NULL, 'His authority is only over those who take him as an ally and those who through him associate others with Allāh.', 'Sesungguhnya pengaruh Syaitan itu hanyalah terhadap orang-orang yang menjadikan dia pemimpin mereka, dan orang-orang yang dengan sebab hasutannya melakukan syirik kepada Allah.', FALSE, NULL, NULL, 278, 14, 111, 236, FALSE, 0, NULL),
(16, 101, 'وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'وَإِذَا بَدَّلْنَا آيَةً مَّكَانَ آيَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوا إِنَّمَا أَنتَ مُفْتَرٍ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', NULL, 'And when We substitute a verse in place of a verse - and Allāh is most knowing of what He sends down - they say, "You, [O Muḥammad], are but an inventor [of lies]." But most of them do not know.', 'Dan apabila Kami tukarkan satu ayat (Al-Quran) untuk menggantikan ayat yang lain (yang dimansukhkan), dan Allah memang mengetahui akan apa yang Ia turunkan, - berkatalah mereka (yang kafir): “Sesungguhnya engkau (wahai Muhammad) hanyalah seorang pendusta”; (padahal Nabi Muhammad tidak berdusta) bahkan kebanyakan mereka tidak mengetahui hakikat yang sebenarnya.', FALSE, NULL, NULL, 278, 14, 111, 237, FALSE, 0, NULL),
(16, 102, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِن رَّبِّكَ بِالْحَقِّ لِيُثَبِّتَ الَّذِينَ آمَنُوا وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', NULL, 'Say, [O Muḥammad], "The Pure Spirit [i.e., Gabriel] has brought it down from your Lord in truth to make firm those who believe and as guidance and good tidings to the Muslims."', 'Katakanlah (wahai Muhammad): Al-Quran itu diturunkan oleh Ruhul Qudus (Jibril) dari Tuhanmu dengan cara yang sungguh layak dan berhikmat, untuk meneguhkan iman orang-orang yang beriman, dan untuk menjadi hidayah petunjuk serta berita yang mengembirakan bagi orang-orang Islam.', FALSE, NULL, NULL, 278, 14, 111, 237, FALSE, 0, NULL),
(16, 103, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّ وَهَٰذَا لِسَانٌ عَرَبِىٌّ مُّبِينٌ', 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُ بَشَرٌ لِّسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ وَهَٰذَا لِسَانٌ عَرَبِيٌّ مُّبِينٌ', NULL, 'And We certainly know that they say, "It is only a human being who teaches him [i.e., the Prophet (ﷺ)]." The tongue of the one they refer to is foreign, and this [recitation, i.e., Qur’ān] is [in] a clear Arabic language.', 'Dan demi sesungguhnya Kami mengetahui, bahawa mereka yang musyrik itu berkata: “Sebenarnya dia diajar oleh seorang manusia”. (Padahal) bahasa orang yang mereka sandarkan tuduhan kepadanya itu ialah bahasa asing, sedang Al-Quran ini berbahasa Arab yang fasih nyata.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 104, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِآيَاتِ اللَّهِ لَا يَهْدِيهِمُ اللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Indeed, those who do not believe in the verses of Allāh - Allāh will not guide them, and for them is a painful punishment.', 'Sesungguhnya orang-orang yang tidak beriman kepada ayat-ayat Allah, Allah tidak akan memberi hidayah petunjuk kepada mereka, dan mereka pula beroleh azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 105, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', 'إِنَّمَا يَفْتَرِي الْكَذِبَ الَّذِينَ لَا يُؤْمِنُونَ بِآيَاتِ اللَّهِ وَأُولَٰئِكَ هُمُ الْكَاذِبُونَ', NULL, 'They only invent falsehood who do not believe in the verses of Allāh, and it is those who are the liars.', 'Sebenarnya yang tergamak berdusta itu hanyalah orang-orang yang tidak beriman kepada ayat-ayat Allah, dan mereka itu ialah orang-orang yang bertabikat berdusta.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 106, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'مَن كَفَرَ بِاللَّهِ مِن بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ وَلَٰكِن مَّن شَرَحَ بِالْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ اللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', NULL, 'Whoever disbelieves in [i.e., denies] Allāh after his belief... except for one who is forced [to renounce his religion] while his heart is secure in faith. But those who [willingly] open their breasts to disbelief, upon them is wrath from Allāh, and for them is a great punishment;', 'Sesiapa yang kufur kepada Allah sesudah ia beriman (maka baginya kemurkaan dan azab dari Allah), kecuali orang yang dipaksa (melakukan kufur) sedang hatinya tenang tenteram dengan iman; akan tetapi sesiapa yang terbuka hatinya menerima kufur maka atas mereka tertimpa kemurkaan dari Allah, dan mereka pula beroleh azab yang besar.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 107, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'ذَٰلِكَ بِأَنَّهُمُ اسْتَحَبُّوا الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ وَأَنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ', NULL, 'That is because they preferred the worldly life over the Hereafter and that Allāh does not guide the disbelieving people.', '(Kekufuran mereka) yang demikian, ialah kerana mereka lebih mengutamakan kehidupan dunia daripada hari akhirat, dan kerana Allah tidak memberi hidayah petunjuk yang menyampaikan kaum yang kufur ingkar (kepada kebahagiaan di akhirat).', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 108, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'أُولَٰئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَارِهِمْ وَأُولَٰئِكَ هُمُ الْغَافِلُونَ', NULL, 'Those are the ones over whose hearts and hearing and vision Allāh has sealed, and it is those who are the heedless.', 'Mereka itulah orang-orang yang telah dimeteraikan Allah Taala hati mereka dan pendengaran mereka serta penglihatan mereka; dan merekalah orang-orang yang lalai.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 109, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 'لَا جَرَمَ أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْخَاسِرُونَ', NULL, 'Assuredly, it is they, in the Hereafter, who will be the losers.', 'Tidak syak lagi, bahawa mereka ialah orang-orang yang rugi pada hari akhirat kelak.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا مِن بَعْدِ مَا فُتِنُوا ثُمَّ جَاهَدُوا وَصَبَرُوا إِنَّ رَبَّكَ مِن بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', NULL, 'Then, indeed your Lord, to those who emigrated after they had been compelled [to say words of disbelief] and thereafter fought [for the cause of Allāh] and were patient - indeed, your Lord, after that, is Forgiving and Merciful', 'Kemudian, sesungguhnya Tuhanmu (memberikan pertolongan) kepada orang-orang yang telah berhijrah sesudah mereka difitnahkan (oleh kaum musyrik), kemudian mereka berjihad serta bersabar; sesungguhnya Tuhanmu - sesudah mereka menderita dan bersabar dalam perjuangan - adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 279, 14, 111, 237, FALSE, 0, NULL),
(16, 111, 'يَوْمَ تَأْتِى كُلُّ نَفْسٍ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'يَوْمَ تَأْتِي كُلُّ نَفْسٍ تُجَادِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', NULL, 'On the Day when every soul will come disputing [i.e., pleading] for itself, and every soul will be fully compensated for what it did, and they will not be wronged [i.e., treated unjustly].', '(Allah akan mengampunkan dosa-dosa mereka itu pada hari kiamat), hari tiap-tiap diri datang membela dirinya semata-mata, dan tiap-tiap diri disempurnakan balasan apa yang ia telah kerjakan (sama ada baik atau jahat), sedang mereka tidak akan dianiaya sedikit pun.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 112, 'وَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 'وَضَرَبَ اللَّهُ مَثَلًا قَرْيَةً كَانَتْ آمِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ اللَّهِ فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ', NULL, 'And Allāh presents an example: a city [i.e., Makkah] which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allāh. So Allāh made it taste the envelopment of hunger and fear for what they had been doing.', 'Dan (berhubung dengan hal kaum yang kufur ingkar) Allah memberikan satu contoh: Sebuah negeri yang aman damai dan tenteram, yang didatangi rezekinya yang mewah dari tiap-tiap tempat, kemudian penduduknya kufur akan nikmat-nikmat Allah itu, maka Allah merasakannya kelaparan dan ketakutan yang meliputi keseluruhannya disebabkan apa yang mereka telah lakukan.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 113, 'وَلَقَدْ جَآءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', 'وَلَقَدْ جَاءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ الْعَذَابُ وَهُمْ ظَالِمُونَ', NULL, 'And there had certainly come to them a Messenger from among themselves, but they denied him; so punishment overtook them while they were wrongdoers.', 'Dan demi sesungguhnya, mereka pula telah didatangi seorang Rasul dari kalangan mereka sendiri, lalu mereka mendustakannya; maka mereka pun ditimpa azab sedang mereka berkeadaan zalim.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 114, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'فَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاشْكُرُوا نِعْمَتَ اللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', NULL, 'Then eat of what Allāh has provided for you [which is] lawful and good. And be grateful for the favor of Allāh, if it is [indeed] Him that you worship.', 'Oleh itu, makanlah (wahai orang-orang yang beriman) dari apa yang telah dikurniakan Allah kepada kamu dari benda-benda yang halal lagi baik, dan bersyukurlah akan nikmat Allah, jika benar kamu hanya menyembahNya semata-mata.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 115, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allāh. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit] - then indeed, Allāh is Forgiving and Merciful.', 'Sesungguhnya Allah hanya mengharamkan kepada kamu memakan bangkai, dan darah, dan daging babi, dan binatang yang disembelih tidak kerana Allah maka sesiapa terpaksa (memakannya kerana darurat) sedang ia tidak mengingininya dan tidak melampaui batas (pada kadar benda yang dimakan itu, maka tidaklah ia berdosa), sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 116, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَٰذَا حَلَالٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ', NULL, 'And do not say about what your tongues assert of untruth, "This is lawful and this is unlawful," to invent falsehood about Allāh. Indeed, those who invent falsehood about Allāh will not succeed.', 'Dan janganlah kamu berdusta dengan sebab apa yang disifatkan oleh lidah kamu: “Ini halal dan ini haram”, untuk mengada-adakan sesuatu yang dusta terhadap Allah; sesungguhnya orang-orang yang berdusta terhadap Allah tidak akan berjaya.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 117, 'مَتَٰعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'مَتَاعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', NULL, '[It is but] a brief enjoyment, and they will have a painful punishment.', '(Mereka hanya mendapat) sedikit kesenangan (di dunia), dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 118, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'وَعَلَى الَّذِينَ هَادُوا حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَاهُمْ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'And to those who are Jews We have prohibited that which We related to you before. And We did not wrong them [thereby], but they were wronging themselves.', 'Dan kepada orang-orang Yahudi, Kami haramkan apa yang telah kami ceritakan kepadamu dahulu; dan tiadalah Kami menganiaya mereka (dengan pengharaman itu), tetapi merekalah yang menganiaya diri mereka sendiri.', FALSE, NULL, NULL, 280, 14, 112, 238, FALSE, 0, NULL),
(16, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا السُّوءَ بِجَهَالَةٍ ثُمَّ تَابُوا مِن بَعْدِ ذَٰلِكَ وَأَصْلَحُوا إِنَّ رَبَّكَ مِن بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', NULL, 'Then, indeed your Lord, to those who have done wrong out of ignorance and then repent after that and correct themselves - indeed, your Lord, thereafter, is Forgiving and Merciful.', 'Kemudian, sesungguhnya Tuhanmu terhadap orang-orang yang melakukan kejahatan dengan sebab kejahilan, kemudian mereka bertaubat sesudah itu serta memperbaiki amalannya, sesungguhnya Tuhanmu sesudah (mereka bertaubat) itu, adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 281, 14, 112, 238, FALSE, 0, NULL),
(16, 120, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 'إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ', NULL, 'Indeed, Abraham was a [comprehensive] leader, devoutly obedient to Allāh, inclining toward truth, and he was not of those who associate others with Allāh.', 'Sesungguhnya Nabi Ibrahim adalah merupakan “satu umat” (walaupun Ia seorang diri); ia takat bulat-bulat kepada Allah, lagi berdiri teguh di atas dasar tauhid; dan ia tidak pernah menjadi dari orang-orang yang musyrik.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 121, 'شَاكِرًا لِّأَنْعُمِهِ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'شَاكِرًا لِّأَنْعُمِهِ اجْتَبَاهُ وَهَدَاهُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, '[He was] grateful for His favors. He [i.e., Allāh] chose him and guided him to a straight path.', 'Ia sentiasa bersyukur akan nikmat-nikmat Allah; Allah telah memilihnya (menjadi Nabi) dan memberi hidayah petunjuk kepadanya ke jalan yang lurus.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 122, 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةً وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'وَآتَيْنَاهُ فِي الدُّنْيَا حَسَنَةً وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ', NULL, 'And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous.', 'Dan Kami telah memberikan kepadanya kebaikan di dunia; dan sesungguhnya ia pada hari akhirat adalah dari orang-orang yang soleh.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 123, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'ثُمَّ أَوْحَيْنَا إِلَيْكَ أَنِ اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', NULL, 'Then We revealed to you, [O Muḥammad], to follow the religion of Abraham, inclining toward truth; and he was not of those who associate with Allāh.', 'Kemudian Kami wahyukan kepadamu (wahai Muhammad): Hendaklah engkau menurut ugama Nabi Ibrahim, yang berdiri teguh di atas jalan yang benar; dan tiadalah ia dari orang-orang musyrik.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 124, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'إِنَّمَا جُعِلَ السَّبْتُ عَلَى الَّذِينَ اخْتَلَفُوا فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ', NULL, 'The sabbath was only appointed for those who differed over it. And indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', 'Sesungguhnya hari Sabtu itu dijadikan (Hari kelepasan yang wajib dihormati) atas orang-orang (Yahudi) yang telah berselisihan padanya; dan sesungguhnya Tuhanmu akan menghukum di antara mereka pada hari kiamat, tentang apa yang mereka telah berselisihan padanya.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 125, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ادْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُم بِالَّتِي هِيَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ', NULL, 'Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided.', 'Serulah ke jalan Tuhanmu (wahai Muhammad) dengan hikmat kebijaksanaan dan nasihat pengajaran yang baik, dan berbahaslah dengan mereka (yang engkau serukan itu) dengan cara yang lebih baik; sesungguhnya Tuhanmu Dia lah jua yang lebih mengetahui akan orang yang sesat dari jalanNya, dan Dia lah jua yang lebih mengetahui akan orang-orang yang mendapat hidayah petunjuk.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 126, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّٰبِرِينَ', 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُم بِهِ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّابِرِينَ', NULL, 'And if you punish [an enemy, O believers], punish with an equivalent of that with which you were harmed. But if you are patient - it is better for those who are patient.', 'Dan jika kamu membalas kejahatan (pihak lawan), maka hendaklah kamu membalas dengan kejahatan yang sama seperti yang telah ditimpakan kepada kamu, dan jika kamu bersabar, (maka) sesungguhnya yang demikian itu adalah lebih baik bagi orang-orang yang sabar.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 127, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', 'وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ', NULL, 'And be patient, [O Muḥammad], and your patience is not but through Allāh. And do not grieve over them and do not be in distress over what they conspire.', 'Dan bersabarlah (wahai Muhammad terhadap perbuatan dan telatah golongan yang ingkar itu); dan tiadalah berhasil kesabaranmu melainkan dengan (memohon pertolongan) Allah; dan janganlah engkau berdukacita terhadap kedegilan mereka, dan janganlah engkau bersempit dada disebabkan tipu daya yang mereka lakukan.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(16, 128, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', 'إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَّالَّذِينَ هُم مُّحْسِنُونَ', NULL, 'Indeed, Allāh is with those who fear Him and those who are doers of good.', 'Sesungguhnya Allah beserta orang-orang yang bertaqwa, dan orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 281, 14, 112, 239, FALSE, 0, NULL),
(17, 1, 'سُبْحَـٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَـٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَـٰتِنَآ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'سبحان الذي اسرى بعبده ليلا من المسجد الحرام الى المسجد الاقصى الذي باركنا حوله لنريه من اياتنا انه هو السميع البصير', NULL, 'Exalted is He who took His Servant [i.e., Prophet Muḥammad (ﷺ)] by night from al-Masjid al-Ḥarām to al-Masjid al-Aqṣā, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.', 'Maha Suci Allah yang telah menjalankan hambaNya (Muhammad) pada malam hari dari Masjid Al-Haraam (di Makkah) ke Masjid Al-Aqsa (di Palestin), yang Kami berkati sekelilingnya, untuk memperlihatkan kepadanya tanda-tanda (kekuasaan dan kebesaran) Kami. Sesungguhnya Allah jualah yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 21, NULL),
(17, 2, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَجَعَلْنَـٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًا', 'واتينا موسى الكتاب وجعلناه هدى لبني اسرائيل الا تتخذوا من دوني وكيلا', NULL, 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,', 'Dan Kami telah memberikan Nabi Musa Kitab Taurat, dan Kami jadikan Kitab itu petunjuk bagi Bani Israil (serta Kami perintahkan mereka): “Janganlah kamu jadikan yang lain daripadaKu sebagai Tuhan (untuk menyerahkan urusan kamu kepadanya)”.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 12, NULL),
(17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ ۚ إِنَّهُۥ كَانَ عَبْدًا شَكُورًا', 'ذرية من حملنا مع نوح انه كان عبدا شكورا', NULL, 'O descendants of those We carried [in the ship] with Noah. Indeed, he was a grateful servant.', '(Wahai) keturunan orang-orang yang telah Kami bawa bersama-sama dengan Nabi Nuh (di dalam bahtera)! Sesungguhnya ia adalah seorang hamba yang bersyukur.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 9, NULL),
(17, 4, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَـٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا', 'وقضينا الى بني اسرائيل في الكتاب لتفسدن في الارض مرتين ولتعلن علوا كبيرا', NULL, 'And We conveyed to the Children of Israel in the Scripture that, "You will surely cause corruption on the earth twice, and you will surely reach [a degree of] great haughtiness."', 'Dan Kami menyatakan kepada Bani Israil dalam Kitab itu: “Sesungguhnya kamu akan melakukan kerosakan di bumi (Palestin) dua kali, dan sesungguhnya kamu akan berlaku sombong angkuh dengan melampau.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 13, NULL),
(17, 5, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَآ أُو۟لِى بَأْسٍ شَدِيدٍ فَجَاسُوا۟ خِلَـٰلَ ٱلدِّيَارِ ۚ وَكَانَ وَعْدًا مَّفْعُولًا', 'فاذا جاء وعد اولاهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلال الديار وكان وعدا مفعولا', NULL, 'So when the [time of] promise came for the first of them, We sent against you servants of Ours - those of great military might, and they probed [even] into the homes, and it was a promise fulfilled.', 'Maka apabila sampai masa janji (membalas kederhakaan kamu) kali yang pertama dari dua (kederhakaan) itu, Kami datangkan kepada kamu hamba-hamba Kami yang kuat gagah dan amat ganas serangannya lalu mereka menjelajah di segala ceruk rantau (membunuh dan membinasakan kamu); dan (sebenarnya peristiwa itu) adalah satu janji yang tetap berlaku.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 17, NULL),
(17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَـٰكُم بِأَمْوَٰلٍ وَبَنِينَ وَجَعَلْنَـٰكُمْ أَكْثَرَ نَفِيرًا', 'ثم رددنا لكم الكرة عليهم وامددناكم باموال وبنين وجعلناكم اكثر نفيرا', NULL, 'Then We gave back to you a return victory over them. And We reinforced you with wealth and sons and made you more numerous in manpower.', 'Kemudian (setelah kamu bertaubat), Kami kembalikan kepada kamu kekuasaan untuk mengalahkan mereka, dan Kami beri kepada kamu dengan banyaknya harta kekayaan dan anak pinak, serta Kami jadikan kamu kaum yang lebih ramai pasukannya.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 11, NULL),
(17, 7, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ ۖ وَإِنْ أَسَأْتُمْ فَلَهَا ۚ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ لِيَسُـۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', 'ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جاء وعد الاخرة ليسوءوا وجوهكم وليدخلوا المسجد كما دخلوه اول مرة وليتبروا ما علوا تتبيرا', NULL, '[And said], "If you do good, you do good for yourselves; and if you do evil, [you do it] to them [i.e., yourselves]." Then when the final [i.e., second] promise came, [We sent your enemies] to sadden your faces and to enter the masjid [i.e., the temple in Jerusalem], as they entered it the first time, and to destroy what they had taken over with [total] destruction.', 'Jika kamu berbuat kebaikan, (maka faedah) kebaikan yang kamu lakukan adalah untuk diri kamu; dan jika kamu berbuat kejahatan, maka (kesannya yang buruk) berbalik kepada diri kamu juga. Oleh itu, apabila sampai masa janji (membalas perbuatan derhaka kamu) kali kedua, (Kami datangkan musuh-musuh kamu) untuk memuramkan muka kamu (dengan penghinaan dan keganasannya); dan untuk memasuki masjid (BaitulMaqdis) sebagaimana mereka telah memasukinya pada kali yang pertama; dan untuk menghancurkan apa sahaja yang mereka telah kuasai, dengan sehancur-hancurnya.', FALSE, NULL, NULL, 282, 15, 113, 240, FALSE, 23, NULL),
(17, 8, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ ۚ وَإِنْ عُدتُّمْ عُدْنَا ۘ وَجَعَلْنَا جَهَنَّمَ لِلْكَـٰفِرِينَ حَصِيرًا', 'عسى ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكافرين حصيرا', NULL, '[Then Allāh said], "It is expected, [if you repent], that your Lord will have mercy upon you. But if you return [to sin], We will return [to punishment]. And We have made Hell, for the disbelievers, a prison-bed."', 'Mudah-mudahan Tuhan kamu akan mengasihani kamu (kalau kamu bertaubat); dan jika kamu kembali (menderhaka), maka Kami pula akan kembali (menyeksa kamu di dunia); dan kami telah jadikan neraka: penjara bagi orang-orang kafir (pada hari akhirat).', FALSE, NULL, NULL, 283, 15, 113, 240, FALSE, 11, NULL),
(17, 9, 'إِنَّ هَـٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ أَجْرًا كَبِيرًا', 'ان هذا القران يهدي للتي هي اقوم ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا كبيرا', NULL, 'Indeed, this Qur’ān guides to that which is most suitable and gives good tidings to the believers who do righteous deeds that they will have a great reward', 'Sesungguhnya Al-Quran ini memberi petunjuk ke jalan yang amat betul (ugama Islam), dan memberikan berita yang mengembirakan orang-orang yang beriman yang mengerjakan amal-amal soleh, bahawa mereka beroleh pahala yang besar.', FALSE, NULL, NULL, 283, 15, 113, 240, FALSE, 16, NULL),
(17, 10, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', 'وان الذين لا يؤمنون بالاخرة اعتدنا لهم عذابا اليما', NULL, 'And that those who do not believe in the Hereafter - We have prepared for them a painful punishment.', 'Dan bahawa orang-orang yang tidak beriman kepada hari akhirat, Kami sediakan bagi mereka azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 283, 15, 113, 240, FALSE, 9, NULL),
(17, 11, 'وَيَدْعُ ٱلْإِنسَـٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ ۖ وَكَانَ ٱلْإِنسَـٰنُ عَجُولًا', 'ويدع الانسان بالشر دعاءه بالخير وكان الانسان عجولا', NULL, 'And man supplicates for evil [when angry] as he supplicates for good, and man is ever hasty.', 'Dan manusia berdoa dengan (memohon supaya ia ditimpa) kejahatan sebagaimana ia berdoa dengan memohon kebaikan, dan sememangnya manusia itu (bertabiat) terburu-buru.', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 8, NULL),
(17, 12, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ ۖ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةً لِّتَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ وَكُلَّ شَىْءٍ فَصَّلْنَـٰهُ تَفْصِيلًا', 'وجعلنا الليل والنهار ايتين فمحونا اية الليل وجعلنا اية النهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلناه تفصيلا', NULL, 'And We have made the night and day two signs, and We erased the sign of the night and made the sign of the day visible that you may seek bounty from your Lord and may know the number of years and the account [of time]. And everything We have set out in detail.', 'Dan Kami jadikan malam dan siang itu dua tanda (yang membuktikan kekuasaan kami), maka Kami hapuskan tanda malam itu (sehingga menjadi gelap-gelita), dan Kami jadikan tanda siang itu terang-benderang supaya kamu mudah mencari rezeki dari limpah kurnia Tuhan kamu, dan supaya kamu mengetahui bilangan tahun dan hitungan hisab (bulan dan hari); dan (ingatlah) tiap-tiap sesuatu (yang kamu perlukan untuk dunia dan ugama kamu), Kami telah menerangkannya satu persatu (dalam Al-Quran) dengan sejelas-jelasnya.', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 23, NULL),
(17, 13, 'وَكُلَّ إِنسَـٰنٍ أَلْزَمْنَـٰهُ طَـٰٓئِرَهُۥ فِى عُنُقِهِۦ ۖ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَـٰمَةِ كِتَـٰبًا يَلْقَىٰهُ مَنشُورًا', 'وكل انسان الزمناه طائره في عنقه ونخرج له يوم القيامة كتابا يلقاه منشورا', NULL, 'And [for] every person We have imposed his fate upon his neck, and We will produce for him on the Day of Resurrection a record which he will encounter spread open.', 'Dan tiap-tiap seorang manusia Kami kalongkan bahagian nasibnya di lehernya, dan pada hari kiamat kelak Kami akan keluarkan kepadanya kitab (suratan amalnya) yang akan didapatinya terbuka (untuk di tatapnya).', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 13, NULL),
(17, 14, 'ٱقْرَأْ كِتَـٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًا', 'اقرا كتابك كفى بنفسك اليوم عليك حسيبا', NULL, '[It will be said], "Read your record. Sufficient is yourself against you this Day as accountant."', '(Lalu Kami perintahkan kepadanya): “Bacalah Kitab (suratan amalmu), cukuplah engkau sendiri pada hari ini menjadi penghitung terhadap dirimu (tentang segala yang telah engkau lakukan)”.', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 7, NULL),
(17, 15, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا', 'من اهتدى فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازرة وزر اخرى وما كنا معذبين حتى نبعث رسولا', NULL, 'Whoever is guided is only guided for [the benefit of] his soul. And whoever errs only errs against it. And no bearer of burdens will bear the burden of another. And never would We punish until We sent a messenger.', 'Sesiapa yang beroleh hidayah petunjuk (menurut panduan Al-Quran), maka sesungguhnya faedah petunjuk yang didapatinya itu hanya terpulang kepada dirinya sendiri, dan sesiapa yang sesat maka sesungguhnya kesan buruk kesesatannya hanya ditanggung oleh dirinya juga. Dan seseorang yang boleh memikul, tidak akan memikul dosa perbuatan orang lain (bahkan dosa usahanya sahaja). Dan tiadalah Kami mengazabkan sesiapapun sebelum Kami mengutuskan seorang Rasul (untuk menerangkan yang benar dan yang salah).', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 21, NULL),
(17, 16, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَـٰهَا تَدْمِيرًا', 'واذا اردنا ان نهلك قرية امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرناها تدميرا', NULL, 'And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word [i.e., deserved decree] comes into effect upon it, and We destroy it with [complete] destruction.', 'Dan apabila sampai tempoh Kami hendak membinasakan penduduk sesebuah negeri, Kami perintahkan (lebih dahulu) orang-orang yang melampau dengan kemewahan di antara mereka (supaya taat), lalu mereka menderhaka dan melakukan maksiat padanya; maka berhaklah negeri itu dibinasakan, lalu kami menghancurkannya sehancur-hancurnya.', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 14, NULL),
(17, 17, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍ ۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'وكم اهلكنا من القرون من بعد نوح وكفى بربك بذنوب عباده خبيرا بصيرا', NULL, 'And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Aware and Seeing.', 'Dan berapa banyak umat-umat yang kami telah binasakan sesudah zaman Nabi Nuh; dan cukuplah Tuhanmu (wahai Muhammad) mengetahui lagi melihat akan dosa-dosa hambaNya.', FALSE, NULL, NULL, 283, 15, 113, 241, FALSE, 13, NULL),
(17, 18, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًا مَّدْحُورًا', 'من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا', NULL, 'Whoever should desire the immediate - We hasten for him from it what We will to whom We intend. Then We have made for him Hell, which he will [enter to] burn, censured and banished.', 'Sesiapa yang menghendaki (kesenangan hidup) dunia, Kami akan segerakan kepadanya dalam dunia apa yang Kami kehendaki, bagi sesiapa yang Kami kehendaki; kemudian Kami sediakan baginya neraka Jahannam (di akhirat kelak), untuk membakarnya dalam keadaan yang hina lagi tersingkir dari rahmat Allah.', FALSE, NULL, NULL, 284, 15, 113, 241, FALSE, 18, NULL),
(17, 19, 'وَمَنْ أَرَادَ ٱلْـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًا', 'ومن اراد الاخرة وسعى لها سعيها وهو مؤمن فاولئك كان سعيهم مشكورا', NULL, 'But whoever desires the Hereafter and exerts the effort due to it while he is a believer - it is those whose effort is ever appreciated [by Allāh].', 'Dan sesiapa yang menghendaki akhirat dan berusaha mengerjakan amal-amal yang baik untuk akhirat dengan usaha yang layak baginya, sedang ia beriman, maka mereka yang demikian keadaannya, diberi pahala akan amal usahanya.', FALSE, NULL, NULL, 284, 15, 113, 241, FALSE, 12, NULL),
(17, 20, 'كُلًّا نُّمِدُّ هَـٰٓؤُلَآءِ وَهَـٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ ۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', 'كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا', NULL, 'To each [category] We extend - to these and to those - from the gift of your Lord. And never has the gift of your Lord been restricted.', 'Tiap-tiap golongan dari keduanya, golongan dunia dan golongan akhirat Kami hulurkan kepada mereka dari pemberian Tuhanmu (wahai Muhammad); dan tiadalah pemberian Tuhanmu itu tersekat (dari sesiapapun).', FALSE, NULL, NULL, 284, 15, 113, 241, FALSE, 12, NULL),
(17, 21, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْـَٔاخِرَةُ أَكْبَرُ دَرَجَٰتٍ وَأَكْبَرُ تَفْضِيلًا', 'انظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْآخِرَةُ أَكْبَرُ دَرَجَاتٍ وَأَكْبَرُ تَفْضِيلًا', NULL, 'Look how We have favored [in provision] some of them over others. But the Hereafter is greater in degrees [of difference] and greater in distinction.', 'Lihatlah bagaimana Kami lebihkan sebahagian dari mereka atas sebahagian yang lain (dalam rezeki pemberian Kami itu) dan sesungguhnya pemberian di akhirat lebih besar tingkatan-tingkatan perbezaannya dan lebih besar tambahan-tambahan kelebihannya.', FALSE, NULL, NULL, 284, 15, 113, 241, FALSE, 0, NULL),
(17, 22, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', 'لَّا تَجْعَلْ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', NULL, 'Do not make [as equal] with Allāh another deity and [thereby] become censured and forsaken.', 'Janganlah engkau adakan tuhan yang lain bersama Allah (dalam ibadatmu), kerana akibatnya engkau akan tinggal dalam keadaan tercela dan kecewa dari mendapat pertolongan.', FALSE, NULL, NULL, 284, 15, 113, 241, FALSE, 0, NULL),
(17, 23, 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِندَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', NULL, 'And your Lord has decreed that you worship not except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], "uff," and do not repel them but speak to them a noble word.', 'Dan Tuhanmu telah perintahkan, supaya engkau tidak menyembah melainkan kepadaNya semata-mata, dan hendaklah engkau berbuat baik kepada ibu bapa. Jika salah seorang dari keduanya, atau kedua-duanya sekali, sampai kepada umur tua dalam jagaan dan peliharaanmu, maka janganlah engkau berkata kepada mereka (sebarang perkataan kasar) sekalipun perkataan “Ha”, dan janganlah engkau menengking menyergah mereka, tetapi katakanlah kepada mereka perkataan yang mulia (yang bersopan santun).', FALSE, NULL, NULL, 284, 15, 114, 242, FALSE, 0, NULL),
(17, 24, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا', 'وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُل رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', NULL, 'And lower to them the wing of humility out of mercy and say, "My Lord, have mercy upon them as they brought me up [when I was] small."', 'Dan hendaklah engkau merendah diri kepada keduanya kerana belas kasihan dan kasih sayangmu, dan doakanlah (untuk mereka, dengan berkata): “Wahai Tuhanku! Cucurilah rahmat kepada mereka berdua sebagaimana mereka telah mencurahkan kasih sayangnya memelihara dan mendidikku semasa kecil.”', FALSE, NULL, NULL, 284, 15, 114, 242, FALSE, 0, NULL),
(17, 25, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًا', 'رَّبُّكُمْ أَعْلَمُ بِمَا فِي نُفُوسِكُمْ إِن تَكُونُوا صَالِحِينَ فَإِنَّهُ كَانَ لِلْأَوَّابِينَ غَفُورًا', NULL, 'Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving.', 'Tuhan kamu lebih mengetahui akan apa yang ada pada hati kamu; kalaulah kamu orang-orang yang bertujuan baik mematuhi perintahNya, maka sesungguhnya dia adalah Maha Pengampun bagi orang-orang yang bertaubat.', FALSE, NULL, NULL, 284, 15, 114, 242, FALSE, 0, NULL),
(17, 26, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 'وَآتِ ذَا الْقُرْبَىٰ حَقَّهُ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', NULL, 'And give the relative his right, and [also] the poor and the traveler, and do not spend wastefully.', 'Dan berikanlah kepada kerabatmu, dan orang miskin serta orang musafir akan haknya masing-masing; dan janganlah engkau membelanjakan hartamu dengan boros yang melampau.', FALSE, NULL, NULL, 284, 15, 114, 242, FALSE, 0, NULL),
(17, 27, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًا', 'إِنَّ الْمُبَذِّرِينَ كَانُوا إِخْوَانَ الشَّيَاطِينِ وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا', NULL, 'Indeed, the wasteful are brothers of the devils, and ever has Satan been to his Lord ungrateful.', 'Sesungguhnya orang-orang yang boros itu adalah saudara-saudara Syaitan, sedang Syaitan itu pula adalah makhluk yang sangat kufur kepada Tuhannya.', FALSE, NULL, NULL, 284, 15, 114, 242, FALSE, 0, NULL),
(17, 28, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَاءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', NULL, 'And if you [must] turn away from them [i.e., the needy] awaiting mercy from your Lord which you expect, then speak to them a gentle word.', 'Dan jika engkau terpaksa berpaling tidak melayani mereka, kerana menunggu rezeki dari Tuhanmu yang engkau harapkan, maka katakanlah kepada mereka kata-kata yang menyenangkan hati.', FALSE, NULL, NULL, 285, 15, 114, 242, FALSE, 0, NULL),
(17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', NULL, 'And do not make your hand [as] chained to your neck or extend it completely and [thereby] become blamed and insolvent.', 'Dan janganlah engkau jadikan tanganmu terbelenggu di lehermu, dan janganlah pula engkau menghulurkannya dengan sehabis-habisnya, kerana akibatnya akan tinggallah engkau dengan keadaan yang tercela serta kering keputusan.', FALSE, NULL, NULL, 285, 15, 114, 242, FALSE, 0, NULL),
(17, 30, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا', NULL, 'Indeed, your Lord extends provision for whom He wills and restricts [it]. Indeed He is ever, concerning His servants, Aware and Seeing.', 'Sesungguhnya Tuhanmu lah yang meluaskan rezeki bagi sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya), dan Ia juga yang menyempitkannya (menurut yang demikian). Sesungguhnya Ia Maha Mendalam pengetahuanNya, lagi Maha Melihat akan hamba-hambaNya.', FALSE, NULL, NULL, 285, 15, 114, 242, FALSE, 0, NULL),
(17, 31, 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ إِنَّ قَتْلَهُمْ كَانَ خِطْـًٔا كَبِيرًا', 'وَلَا تَقْتُلُوا أَوْلَادَكُمْ خَشْيَةَ إِمْلَاقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ إِنَّ قَتْلَهُمْ كَانَ خِطْئًا كَبِيرًا', NULL, 'And do not kill your children for fear of poverty. We provide for them and for you. Indeed, their killing is ever a great sin.', 'Dan janganlah kamu membunuh anak-anak kamu kerana takutkan kepapaan; Kamilah yang memberi rezeki kepada mereka dan kepada kamu. Sesungguhnya perbuatan membunuh mereka adalah satu kesalahan yang besar.', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 32, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ إِنَّهُۥ كَانَ فَٰحِشَةً وَسَآءَ سَبِيلًا', 'وَلَا تَقْرَبُوا الزِّنَىٰ إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا', NULL, 'And do not approach unlawful sexual intercourse. Indeed, it is ever an immorality and is evil as a way.', 'Dan janganlah kamu menghampiri zina, sesungguhnya zina itu adalah satu perbuatan yang keji dan satu jalan yang jahat (yang membawa kerosakan).', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 33, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًا فَلَا يُسْرِف فِّى ٱلْقَتْلِ إِنَّهُۥ كَانَ مَنصُورًا', 'وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا فَلَا يُسْرِف فِّي الْقَتْلِ إِنَّهُ كَانَ مَنصُورًا', NULL, 'And do not kill the soul [i.e., person] which Allāh has forbidden, except by right. And whoever is killed unjustly - We have given his heir authority, but let him not exceed limits in [the matter of] taking life. Indeed, he has been supported [by the law].', 'Dan janganlah kamu membunuh diri seseorang manusia yang diharamkan oleh Allah membunuhnya kecuali dengan alasan yang benar. Dan sesiapa yang dibunuh secara zalim, maka sesungguhnya Kami telah menjadikan warisannya berkuasa menuntut balas. Dalam pada itu, janganlah ia melampau dalam menuntut balas bunuh itu, kerana sesungguhnya ia adalah mendapat sepenuh-penuh pertolongan (menurut hukum Syarak).', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 34, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ بِٱلْعَهْدِ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًا', 'وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُ وَأَوْفُوا بِالْعَهْدِ إِنَّ الْعَهْدَ كَانَ مَسْئُولًا', NULL, 'And do not approach the property of an orphan, except in the way that is best, until he reaches maturity. And fulfill [every] commitment. Indeed, the commitment is ever [that about which one will be] questioned.', 'Dan janganlah kamu menghampiri harta anak yatim melainkan dengan cara yang baik (untuk mengawal dan mengembangkannya), sehingga ia baligh (dewasa, serta layak mengurus hartanya dengan sendiri); dan sempurnakanlah perjanjian (dengan Allah dan dengan manusia), sesungguhnya perjanjian itu akan ditanya.', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 35, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', 'وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', NULL, 'And give full measure when you measure, and weigh with an even [i.e., honest] balance. That is the best [way] and best in result.', 'Dan sempurnakanlah sukatan apabila kamu menyukat, dan timbanglah dengan timbangan yang adil. Yang demikian itu baik (kesannya bagi kamu di dunia) dan sebaik baik kesudahan (yang mendatangkan pahala di akhirat kelak).', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 36, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا', 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَٰئِكَ كَانَ عَنْهُ مَسْئُولًا', NULL, 'And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned.', 'Dan janganlah engkau mengikut apa yang engkau tidak mempunyai pengetahuan mengenainya; sesungguhnya pendengaran dan penglihatan serta hati, semua anggota-anggota itu tetap akan ditanya tentang apa yang dilakukannya.', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 37, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًا', 'وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ الْأَرْضَ وَلَن تَبْلُغَ الْجِبَالَ طُولًا', NULL, 'And do not walk upon the earth exultantly. Indeed, you will never tear the earth [apart], and you will never reach the mountains in height.', 'Dan janganlah engkau berjalan di bumi dengan berlagak sombong, kerana sesungguhnya engkau tidak akan dapat menembusi bumi, dan engkau tidak akan dapat menyamai setinggi gunung-ganang.', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًا', 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُ عِندَ رَبِّكَ مَكْرُوهًا', NULL, 'All that [i.e., the aforementioned] - its evil is ever, in the sight of your Lord, detested.', 'Tiap-tiap satu perintah itu, menyalahinya adalah kejahatan yang dibenci di sisi Tuhanmu.', FALSE, NULL, NULL, 285, 15, 114, 243, FALSE, 0, NULL),
(17, 39, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًا مَّدْحُورًا', 'ذَٰلِكَ مِمَّا أَوْحَىٰ إِلَيْكَ رَبُّكَ مِنَ الْحِكْمَةِ وَلَا تَجْعَلْ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَتُلْقَىٰ فِي جَهَنَّمَ مَلُومًا مَّدْحُورًا', NULL, 'That is from what your Lord has revealed to you, [O Muḥammad], of wisdom. And, [O mankind], do not make [as equal] with Allāh another deity, lest you be thrown into Hell, blamed and banished.', 'Perintah yang demikian itu ialah sebahagian dari hikmat yang telah diwahyukan kepadamu (wahai Muhammad) oleh Tuhanmu. Dan (ingatlah) janganlah engkau jadikan bersama-sama Allah sesuatu yang lain yang disembah, kerana akibatnya engkau akan dicampakkan ke dalam neraka Jahannam dengan keadaan tercela dan tersingkir (dari rahmat Allah).', FALSE, NULL, NULL, 286, 15, 114, 243, FALSE, 0, NULL),
(17, 40, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', 'أَفَأَصْفَاكُمْ رَبُّكُم بِالْبَنِينَ وَاتَّخَذَ مِنَ الْمَلَائِكَةِ إِنَاثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', NULL, 'Then, has your Lord chosen you for [having] sons and taken [i.e., adopted] from among the angels daughters? Indeed, you say a grave saying.', '(Jika demikian wajibnya mengesakan Allah, maka patutkah kamu mendakwa bahawa Tuhan mempunyai anak, dan anak itu pula dari jenis yang kamu tidak sukai?). Adakah Tuhan kamu telah memilih anak-anak lelaki untuk kamu dan Ia mengambil untuk diriNya anak-anak perempuan dari kalangan malaikat? Sesungguhnya kamu adalah memperkatakan dusta yang amat besar.', FALSE, NULL, NULL, 286, 15, 114, 243, FALSE, 0, NULL),
(17, 41, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', 'وَلَقَدْ صَرَّفْنَا فِي هَٰذَا الْقُرْآنِ لِيَذَّكَّرُوا وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', NULL, 'And We have certainly diversified [the contents] in this Qur’ān that they [i.e., mankind] may be reminded, but it does not increase them [i.e., the disbelievers] except in aversion.', 'Dan sesungguhnya Kami telah menerangkan jalan-jalan menetapkan iktiqad dan tauhid dengan berbagai cara di dalam Al-Quran ini supaya mereka beringat (memahami dan mematuhi kebenaran); dalam pada itu, penerangan yang berbagai cara itu tidak menjadikan mereka melainkan bertambah liar.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 42, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌ كَمَا يَقُولُونَ إِذًا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًا', 'قُل لَّوْ كَانَ مَعَهُ آلِهَةٌ كَمَا يَقُولُونَ إِذًا لَّابْتَغَوْا إِلَىٰ ذِي الْعَرْشِ سَبِيلًا', NULL, 'Say, [O Muḥammad], "If there had been with Him [other] gods, as they say, then they [each] would have sought to the Owner of the Throne a way."', 'Katakanlah (wahai Muhammad): “Kalaulah ada tuhan-tuhan yang lain bersama-sama Allah, sebagaimana yang mereka katakan itu, tentulah tuhan-tuhan itu akan mencari jalan kepada Allah yang mempunyai Arasy (dan kekuasaan yang mutlak).', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 43, 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', 'سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', NULL, 'Exalted is He and high above what they say by great sublimity.', 'Maha Sucilah Allah dan tertinggilah Ia setinggi-tingginya, jauh dari apa yang mereka katakan itu.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 44, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُ كَانَ حَلِيمًا غَفُورًا', NULL, 'The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts [Allāh] by His praise, but you do not understand their [way of] exalting. Indeed, He is ever Forbearing and Forgiving.', 'Langit yang tujuh dan bumi serta sekalian makhluk yang ada padanya, sentiasa mengucap tasbih bagi Allah; dan tiada sesuatupun melainkan bertasbih dengan memujiNya; akan tetapi kamu tidak faham akan tasbih mereka. Sesungguhnya Ia adalah Maha Penyabar, lagi Maha Pengampun.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 45, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ حِجَابًا مَّسْتُورًا', 'وَإِذَا قَرَأْتَ الْقُرْآنَ جَعَلْنَا بَيْنَكَ وَبَيْنَ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ حِجَابًا مَّسْتُورًا', NULL, 'And when you recite the Qur’ān, We put between you and those who do not believe in the Hereafter a concealed partition.', 'Dan apabila engkau membaca Al-Quran (wahai Muhammad), Kami jadikan perasaan ingkar dan hasad dengki orang-orang yang tidak beriman kepada hari akhirat itu sebagai dinding yang tidak dapat dilihat, yang menyekat mereka daripada memahami bacaanmu.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 46, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًا', 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِذَا ذَكَرْتَ رَبَّكَ فِي الْقُرْآنِ وَحْدَهُ وَلَّوْا عَلَىٰ أَدْبَارِهِمْ نُفُورًا', NULL, 'And We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And when you mention your Lord alone in the Qur’ān, they turn back in aversion.', 'Dan Kami jadikan (perasaan itu sebagai) tutupan yang berlapis-lapis atas hati mereka, juga sebagai penyumbat pada telinga mereka, yang menghalang mereka dari memahami dan mendengar kebenaran Al-Quran; dan sebab itulah apabila engkau menyebut nama Tuhanmu sahaja di dalam Al-Quran, mereka berpaling undur melarikan diri.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 47, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰ إِذْ يَقُولُ الظَّالِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', NULL, 'We are most knowing of how they listen to it when they listen to you and [of] when they are in private conversation, when the wrongdoers say, "You follow not but a man affected by magic."', 'Kami lebih mengetahui akan tujuan mereka mendengar Al-Quran semasa mereka mendengar bacaanmu (wahai Muhammad), dan semasa mereka berbisik-bisik iaitu ketika orang-orang yang zalim itu berkata (sesama sendiri): “Kamu tidak menurut melainkan seorang yang kena sihir”.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 48, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا', NULL, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', 'Lihatlah (wahai Muhammad) bagaimana mereka menyifatkan engkau dengan yang bukan-bukan, maka dengan sebab itu mereka sesat, sehingga mereka tidak dapat mencari jalan kebenaran.', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 49, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', NULL, 'And they say, "When we are bones and crumbled particles, will we [truly] be resurrected as a new creation?"', 'Dan mereka berkata: “Adakah sesudah kita menjadi tulang dan benda yang reput, adakah kita akan dibangkitkan semula dengan kejadian yang baharu?”', FALSE, NULL, NULL, 286, 15, 114, 244, FALSE, 0, NULL),
(17, 50, 'قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', 'قُلْ كُونُوا حِجَارَةً أَوْ حَدِيدًا', NULL, 'Say, "Be you stones or iron', 'Katakanlah (wahai Muhammad): “Jadilah kamu batu atau besi -', FALSE, NULL, NULL, 287, 15, 115, 244, FALSE, 0, NULL),
(17, 51, 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًا', 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِي صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ الَّذِي فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰ أَن يَكُونَ قَرِيبًا', NULL, 'Or [any] creation of that which is great within your breasts." And they will say, "Who will restore us?" Say, "He who brought you forth the first time." Then they will nod their heads toward you and say, "When is that?" Say, "Perhaps it will be soon -', 'Atau lain-lain makhluk yang terlintas di hati kamu sukar hidupnya, (maka Allah berkuasa menghidupkannya)!” Mereka pula akan bertanya: “Siapakah yang akan mengembalikan kita hidup semula?” Katakanlah: “Ialah Allah yang menjadikan kamu pada mulanya!” Maka mereka akan menganggukkan kepala mereka kepadamu sambil bertanya secara mengejek: Bila berlakunya?” Katakanlah: “Dipercayai akan berlaku tidak lama lagi!”', FALSE, NULL, NULL, 287, 15, 115, 244, FALSE, 0, NULL),
(17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', NULL, 'On the Day He will call you and you will respond with praise of Him and think that you had not remained [in the world] except for a little."', '(Ingatlah akan) hari Ia menyeru kamu lalu kamu menyahut sambil memuji kekuasaanNya, dan kamu menyangka, bahawa kamu tinggal (dalam kubur) hanya sebentar.', FALSE, NULL, NULL, 287, 15, 115, 244, FALSE, 0, NULL),
(17, 53, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّا مُّبِينًا', 'وَقُل لِّعِبَادِي يَقُولُوا الَّتِي هِيَ أَحْسَنُ إِنَّ الشَّيْطَانَ يَنزَغُ بَيْنَهُمْ إِنَّ الشَّيْطَانَ كَانَ لِلْإِنسَانِ عَدُوًّا مُّبِينًا', NULL, 'And tell My servants to say that which is best. Indeed, Satan induces [dissension] among them. Indeed Satan is ever, to mankind, a clear enemy.', 'Dan katakanlah (wahai Muhammad) kepada hamba-hambaKu (yang beriman), supaya mereka berkata dengan kata-kata yang amat baik (kepada orang-orang yang menentang kebenaran); sesungguhnya Syaitan itu sentiasa menghasut di antara mereka (yang mukmin dan yang menentang); sesungguhnya Syaitan itu adalah musuh yang amat nyata bagi manusia.', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 54, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًا', 'رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَا أَرْسَلْنَاكَ عَلَيْهِمْ وَكِيلًا', NULL, 'Your Lord is most knowing of you. If He wills, He will have mercy upon you; or if He wills, He will punish you. And We have not sent you, [O Muḥammad], over them as a manager.', 'Tuhan kamu lebih mengetahui akan keadaan kamu; jika Ia kehendaki, Ia akan memberi rahmat kepada kamu; atau jika Ia kehendaki, Ia akan menyeksa kamu. Dan Kami tidak mengutusmu kepada mereka (wahai Muhammad), sebagai wakil yang menguasai urusan mereka.', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 55, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعْضٍ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'وَرَبُّكَ أَعْلَمُ بِمَن فِي السَّمَاوَاتِ وَالْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَىٰ بَعْضٍ وَآتَيْنَا دَاوُودَ زَبُورًا', NULL, 'And your Lord is most knowing of whoever is in the heavens and the earth. And We have made some of the prophets exceed others [in various ways], and to David We gave the book [of Psalms].', 'Dan Tuhanmu (wahai Muhammad) lebih mengetahui akan sekalian makhluk yang ada di langit dan di bumi; dan sesungguhnya Kami telah melebihkan setengah Nabi-nabi atas setengahnya yang lain; dan Kami telah memberikan Kitab Zabur kepada Nabi Daud.', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 56, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 'قُلِ ادْعُوا الَّذِينَ زَعَمْتُم مِّن دُونِهِ فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', NULL, 'Say, "Invoke those you have claimed [as gods] besides Him, for they do not possess the [ability for] removal of adversity from you or [for its] transfer [to someone else]."', 'Katakanlah (wahai Muhammad kepada kaum musyrik): “Serukanlah orang-orang yang kamu dakwa (boleh memberi pertolongan) selain dari Allah, maka sudah tentu mereka tidak berkuasa menghapuskan bahaya daripada kamu dan tidak dapat memindahkannya”.', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 57, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', 'أُولَٰئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', NULL, 'Those whom they invoke seek means of access to their Lord, [striving as to] which of them would be nearest, and they hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is ever feared.', 'orang-orang yang mereka seru itu, masing-masing mencari jalan mendampingkan diri kepada Tuhannya (dengan berbuat ibadat), sekali pun orang yang lebih dekat kepada Tuhannya, serta mereka pula mengharapkan rahmatNya dan gerun takut akan azabNya; sesungguhnya azab Tuhanmu itu, adalah (perkara yang semestinya) ditakuti.', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 58, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ الْقِيَامَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِي الْكِتَابِ مَسْطُورًا', NULL, 'And there is no city but that We will destroy it before the Day of Resurrection or punish it with a severe punishment. That has ever been in the Register inscribed.', 'Dan tiada sesebuah negeri pun melainkan Kami akan membinasakannya sebelum hari kiamat, atau Kami menyeksa penduduknya dengan azab seksa yang berat; yang demikian itu adalah tertulis di dalam Kitab (Lauh Mahfuz).', FALSE, NULL, NULL, 287, 15, 115, 245, FALSE, 0, NULL),
(17, 59, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْـَٔايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةً فَظَلَمُوا۟ بِهَا وَمَا نُرْسِلُ بِٱلْـَٔايَٰتِ إِلَّا تَخْوِيفًا', 'وَمَا مَنَعَنَا أَن نُّرْسِلَ بِالْآيَاتِ إِلَّا أَن كَذَّبَ بِهَا الْأَوَّلُونَ وَآتَيْنَا ثَمُودَ النَّاقَةَ مُبْصِرَةً فَظَلَمُوا بِهَا وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا', NULL, 'And nothing has prevented Us from sending signs [i.e., miracles] except that the former peoples denied them. And We gave Thamūd the she-camel as a visible sign, but they wronged her. And We send not the signs except as a warning.', 'Dan tiada yang menghalang Kami dari menghantar turun mukjizat yang mereka minta itu melainkan kerana jenis mukjizat itu telah didustakan oleh kaum-kaum yang telah lalu; dan di antaranya Kami telahpun memberikan kepada kaum Thamud unta betina sebagai mukjizat yang menjadi keterangan yang nyata, lalu mereka berlaku zalim kepadanya; dan biasanya Kami tidak menghantar turun mukjizat-mukjizat itu melainkan untuk menjadi amaran (bagi kebinasaan orang-orang yang memintanya kalau mereka tidak beriman).', FALSE, NULL, NULL, 288, 15, 115, 245, FALSE, 0, NULL),
(17, 60, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًا كَبِيرًا', 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِالنَّاسِ وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْآنِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَانًا كَبِيرًا', NULL, 'And [remember, O Muḥammad], when We told you, "Indeed, your Lord has encompassed the people." And We did not make the sight which We showed you except as a trial for the people, as was the accursed tree [mentioned] in the Qur’ān. And We threaten [i.e., warn] them, but it increases them not except in great transgression.', 'Dan (ingatlah) ketika Kami wahyukan kepadamu (wahai Muhammad), bahawa sesungguhnya Tuhanmu meliputi akan manusia (dengan ilmuNya dan kekuasaanNya; dan tiadalah Kami menjadikan pandangan (pada malam Mikraj) yang telah kami perlihatkan kepadamu melainkan sebagai satu ujian bagi manusia; dan (demikian juga Kami jadikan) pokok yang dilaknat di dalam Al-Quran; dan Kami beri mereka takut (dengan berbagai-bagai amaran) maka semuanya itu tidak menambahkan mereka melainkan dengan kekufuran yang melampau.', FALSE, NULL, NULL, 288, 15, 115, 245, FALSE, 0, NULL),
(17, 61, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', 'وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ قَالَ أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', NULL, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He said, "Should I prostrate to one You created from clay?"', 'Dan (ingatkanlah peristiwa) ketika Kami berfirman kepada malaikat: “Sujudlah kamu kepada Adam”; maka mereka sujudlah melainkan iblis; ia berkata: “Patutkah aku sujud kepada (makhluk) yang Engkau jadikan dari tanah (yang di adun)?”', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 62, 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًا', 'قَالَ أَرَأَيْتَكَ هَٰذَا الَّذِي كَرَّمْتَ عَلَيَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ الْقِيَامَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُ إِلَّا قَلِيلًا', NULL, '[Iblees] said, "Do You see this one whom You have honored above me? If You delay me [i.e., my death] until the Day of Resurrection, I will surely destroy his descendants, except for a few."', 'Ia berkata lagi: “Khabarkanlah kepadaku, inikah orangnya yang Engkau muliakan mengatasiku? Jika Engkau beri tempoh kepadaku hingga hari kiamat, tentulah aku akan memancing menyesatkan zuriat keturunannya, kecuali sedikit (di antaranya)”.', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 63, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءً مَّوْفُورًا', 'قَالَ اذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَاؤُكُمْ جَزَاءً مَّوْفُورًا', NULL, '[Allāh] said, "Go, for whoever of them follows you, indeed Hell will be the recompense of [all of] you - an ample recompense.', 'Allah berfirman (kepada iblis): “Pergilah (lakukanlah apa yang engkau rancangkan)! Kemudian siapa yang menurutmu di antara mereka, maka sesungguhnya neraka Jahannamlah balasan kamu semua, sebagai balasan yang cukup.', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 64, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِي الْأَمْوَالِ وَالْأَوْلَادِ وَعِدْهُمْ وَمَا يَعِدُهُمُ الشَّيْطَانُ إِلَّا غُرُورًا', NULL, 'And incite [to senselessness] whoever you can among them with your voice and assault them with your horses and foot soldiers and become a partner in their wealth and their children and promise them." But Satan does not promise them except delusion.', 'Dan desak serta pujuklah sesiapa yang engkau dapat memujuknya dengan suaramu; dan kerahlah penyokong-penyokongmu yang berkuda serta yang berjalan kaki untuk mengalahkan mereka; dan turut - campurlah dengan mereka dalam menguruskan harta-benda dan anak-anak (mereka); dan janjikanlah mereka (dengan janji-janjimu)”. Padahal tidak ada yang dijanjikan oleh Syaitan itu melainkan tipu daya semata-mata.', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 65, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', 'إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', NULL, 'Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs.', 'Sesungguhnya hamba-hambaKu (yang beriman dengan ikhlas), tiadalah engkau (hai iblis) mempunyai sebarang kuasa terhadap mereka (untuk menyesatkannya); cukuplah Tuhanmu (wahai Muhammad) menjadi Pelindung (bagi mereka).', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 66, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًا', 'رَّبُّكُمُ الَّذِي يُزْجِي لَكُمُ الْفُلْكَ فِي الْبَحْرِ لِتَبْتَغُوا مِن فَضْلِهِ إِنَّهُ كَانَ بِكُمْ رَحِيمًا', NULL, 'It is your Lord who drives the ship for you through the sea that you may seek of His bounty. Indeed, He is ever, to you, Merciful.', 'Tuhan kamulah yang menjalankan untuk kamu kapal-kapal di laut, supaya kamu dapat mencari rezeki dari limpah kurniaNya; sesungguhnya Ia adalah Maha Mengasihani kepada kamu.', FALSE, NULL, NULL, 288, 15, 115, 246, FALSE, 0, NULL),
(17, 67, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', 'وَإِذَا مَسَّكُمُ الضُّرُّ فِي الْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّا إِيَّاهُ فَلَمَّا نَجَّاكُمْ إِلَى الْبَرِّ أَعْرَضْتُمْ وَكَانَ الْإِنسَانُ كَفُورًا', NULL, 'And when adversity touches you at sea, lost are [all] those you invoke except for Him. But when He delivers you to the land, you turn away [from Him]. And ever is man ungrateful.', 'Dan apabila kamu terkena bahaya di laut, (pada saat itu) hilang lenyaplah (dari ingatan kamu) makhluk-makhluk yang kamu seru selain dari Allah; maka apabila Allah selamatkan kamu ke darat, kamu berpaling tadah (tidak mengingatiNya); dan memanglah manusia itu sentiasa kufur (akan nikmat-nikmat Allah).', FALSE, NULL, NULL, 289, 15, 115, 246, FALSE, 0, NULL),
(17, 68, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ الْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا لَكُمْ وَكِيلًا', NULL, 'Then do you feel secure that [instead] He will not cause a part of the land to swallow you or send against you a storm of stones? Then you would not find for yourselves an advocate.', 'Adakah kamu - (sesudah diselamatkan ke darat) - merasa aman (dan tidak memikirkan), bahawa Allah akan menggempakan sebahagian dari daratan itu menimbus kamu, atau dia akan menghantarkan kepada kamu angin ribut yang menghujani kamu dengan batu; kemudian kamu tidak beroleh sesiapapun yang menjadi pelindung kamu?', FALSE, NULL, NULL, 289, 15, 115, 246, FALSE, 0, NULL),
(17, 69, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًا', 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ الرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُوا لَكُمْ عَلَيْنَا بِهِ تَبِيعًا', NULL, 'Or do you feel secure that He will not send you back into it [i.e., the sea] another time and send upon you a hurricane of wind and drown you for what you denied? Then you would not find for yourselves against Us an avenger.', 'Atau adakah kamu merasa aman (dan tidak memikirkan) bahawa Allah akan mengembalikan kamu sekali lagi ke laut, kemudian Ia menghantarkan kepada kamu angin ribut yang memecah belahkan segala yang dirempuhnya, lalu Ia mengaramkan kamu dengan sebab kekufuran kamu; kemudian kamu tidak beroleh sesiapapun yang boleh menuntut bela tentang itu terhadap Kami?', FALSE, NULL, NULL, 289, 15, 115, 246, FALSE, 0, NULL),
(17, 70, 'وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', 'وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ وَحَمَلْنَاهُمْ فِي الْبَرِّ وَالْبَحْرِ وَرَزَقْنَاهُم مِّنَ الطَّيِّبَاتِ وَفَضَّلْنَاهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', NULL, 'And We have certainly honored the children of Adam and carried them on the land and sea and provided for them of the good things and preferred them over much of what We have created, with [definite] preference.', 'Dan sesungguhnya Kami telah memuliakan anak-anak Adam; dan Kami telah beri mereka menggunakan berbagai-bagai kenderaan di darat dan di laut; dan Kami telah memberikan rezeki kepada mereka dari benda-benda yang baik-baik serta Kami telah lebihkan mereka dengan selebih-lebihnya atas banyak makhluk-makhluk yang telah Kami ciptakan.', FALSE, NULL, NULL, 289, 15, 116, 246, FALSE, 0, NULL),
(17, 71, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', 'يَوْمَ نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ فَمَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَأُولَٰئِكَ يَقْرَءُونَ كِتَابَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', NULL, '[Mention, O Muḥammad], the Day We will call forth every people with their record [of deeds]. Then whoever is given his record in his right hand - those will read their records, and injustice will not be done to them, [even] as much as a thread [inside the date seed].', '(Ingatlah) hari Kami menyeru tiap-tiap kumpulan manusia dengan nama imamnya; kemudian sesiapa diberikan Kitabnya di tangan kanannya, maka mereka itu akan membacanya (dengan sukacita), dan mereka tidak dikurangkan (pahala amal-amalnya yang baik) sedikitpun.', FALSE, NULL, NULL, 289, 15, 116, 247, FALSE, 0, NULL),
(17, 72, 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْـَٔاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', 'وَمَن كَانَ فِي هَٰذِهِ أَعْمَىٰ فَهُوَ فِي الْآخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', NULL, 'And whoever is blind in this [life] will be blind in the Hereafter and more astray in way.', 'Dan (sebaliknya) sesiapa yang berada di dunia ini (dalam keadaan) buta (matahatinya), maka ia juga buta di akhirat dan lebih sesat lagi jalannya.', FALSE, NULL, NULL, 289, 15, 116, 247, FALSE, 0, NULL),
(17, 73, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ وَإِذًا لَّٱتَّخَذُوكَ خَلِيلًا', 'وَإِن كَادُوا لَيَفْتِنُونَكَ عَنِ الَّذِي أَوْحَيْنَا إِلَيْكَ لِتَفْتَرِيَ عَلَيْنَا غَيْرَهُ وَإِذًا لَّاتَّخَذُوكَ خَلِيلًا', NULL, 'And indeed, they were about to tempt you away from that which We revealed to you in order to [make] you invent about Us something else; and then they would have taken you as a friend.', 'Dan sesungguhnya nyaris-nyaris mereka dapat memesongkanmu (wahai Muhammad) dari apa yang Kami telah wahyukan kepadamu, supaya engkau ada-adakan atas nama Kami perkara yang lainnya; dan (kalau engkau melakukan yang demikian) baharulah mereka menjadikan engkau sahabat karibnya.', FALSE, NULL, NULL, 289, 15, 116, 247, FALSE, 0, NULL),
(17, 74, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًٔا قَلِيلًا', 'وَلَوْلَا أَن ثَبَّتْنَاكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْئًا قَلِيلًا', NULL, 'And if We had not strengthened you, you would have almost inclined to them a little.', 'Dan kalaulah tidak Kami menetapkan engkau (berpegang teguh kepada kebenaran), tentulah engkau sudah mendekati dengan menyetujui sedikit kepada kehendak mereka.', FALSE, NULL, NULL, 289, 15, 116, 247, FALSE, 0, NULL),
(17, 75, 'إِذًا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', 'إِذًا لَّأَذَقْنَاكَ ضِعْفَ الْحَيَاةِ وَضِعْفَ الْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', NULL, 'Then [if you had], We would have made you taste double [punishment in] life and double [after] death. Then you would not find for yourself against Us a helper.', 'Jika (engkau melakukan yang) demikian, tentulah Kami akan merasakanmu kesengsaraan yang berganda semasa hidup dan kesengsaraan yang berganda juga semasa mati; kemudian engkau tidak beroleh seseorang penolong pun terhadap hukuman Kami.', FALSE, NULL, NULL, 289, 15, 116, 247, FALSE, 0, NULL),
(17, 76, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًا', 'وَإِن كَادُوا لَيَسْتَفِزُّونَكَ مِنَ الْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَافَكَ إِلَّا قَلِيلًا', NULL, 'And indeed, they were about to provoke [i.e., drive] you from the land [i.e., Makkah] to evict you therefrom. And then [when they do], they will not remain [there] after you, except for a little.', 'Dan sesungguhnya mereka hampir-hampir berjaya mengganggumu daripada tinggal aman di bumi (Makkah) dengan tujuan mereka dapat mengusirmu dari negeri itu; dan jika berlaku demikian, maka mereka tidak akan tinggal di situ sesudahmu melainkan sedikit masa sahaja.', FALSE, NULL, NULL, 290, 15, 116, 247, FALSE, 0, NULL),
(17, 77, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', NULL, '[That is Our] established way for those We had sent before you of Our messengers; and you will not find in Our way any alteration.', '(Demikianlah) peraturan (Kami yang tetap mengenai) orang-orang yang telah Kami utuskan sebelummu dari Rasul-rasul Kami; dan engkau tidak akan dapati sebarang perubahan bagi peraturan Kami yang tetap itu.', FALSE, NULL, NULL, 290, 15, 116, 247, FALSE, 0, NULL),
(17, 78, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًا', 'أَقِمِ الصَّلَاةَ لِدُلُوكِ الشَّمْسِ إِلَىٰ غَسَقِ اللَّيْلِ وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا', NULL, 'Establish prayer at the decline of the sun [from its meridian] until the darkness of the night and [also] the Qur’ān [i.e., recitation] of dawn. Indeed, the recitation of dawn is ever witnessed.', 'Dirikanlah olehmu sembahyang ketika gelincir matahari hingga waktu gelap malam, dan (dirikanlah) sembahyang subuh sesungguhnya sembahyang subuh itu adalah disaksikan (keistimewaannya).', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 79, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', 'وَمِنَ اللَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَّكَ عَسَىٰ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', NULL, 'And from [part of] the night, pray with it [i.e., recitation of the Qur’ān] as additional [worship] for you; it is expected that your Lord will resurrect you to a praised station.', 'Dan bangunlah pada sebahagian dari waktu malam serta kerjakanlah “sembahyang tahajjud” padanya, sebagai sembahyang tambahan bagimu; semoga Tuhanmu membangkit dan menempatkanmu pada hari akhirat di tempat yang terpuji.', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 80, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًا نَّصِيرًا', 'وَقُل رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا', NULL, 'And say, "My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority."', 'Dan pohonkanlah (wahai Muhammad, dengan berdoa): “Wahai Tuhanku! Masukkanlah daku ke dalam urusan ugamaku dengan kemasukan yang benar lagi mulia, serta keluarkanlah daku daripadanya dengan cara keluar yang benar lagi mulia; dan berikanlah kepadaku dari sisiMu hujah keterangan serta kekuasaan yang menolongku”,', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 81, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًا', 'وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا', NULL, 'And say, "Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart."', 'Dan katakanlah: “Telah datang kebenaran (Islam), dan hilang lenyaplah perkara yang salah (kufur dan syirik); sesungguhnya yang salah itu sememangnya satu perkara yang tetap lenyap”.', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 82, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًا', 'وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلَا يَزِيدُ الظَّالِمِينَ إِلَّا خَسَارًا', NULL, 'And We send down of the Qur’ān that which is healing and mercy for the believers, but it does not increase the wrongdoers except in loss.', 'Dan Kami turunkan dengan beransur-ansur dari Al-Quran Aya-ayat Suci yang menjadi ubat penawar dan rahmat bagi orang-orang yang beriman kepadanya; dan (sebaliknya) Al-Quran tidak menambahkan orang-orang yang zalim (disebabkan keingkaran mereka) melainkan kerugian jua.', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 83, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًا', 'وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَىٰ بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ كَانَ يَئُوسًا', NULL, 'And when We bestow favor upon man [i.e., the disbeliever], he turns away and distances himself; and when evil touches him, he is ever despairing.', 'Dan apabila Kami kurniakan nikmat kepada manusia, berpalinglah ia serta menjauhkan diri (dari bersyukur); dan apabila ia merasai kesusahan, jadilah ia berputus asa.', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 84, 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', NULL, 'Say, "Each works according to his manner, but your Lord is most knowing of who is best guided in way."', 'Katakanlah (wahai Muhammad): “Tiap-tiap seorang beramal menurut pembawaan jiwanya sendiri; maka Tuhan kamu lebih mengetahui siapakah (di antara kamu) yang lebih betul jalannya”.', FALSE, NULL, NULL, 290, 15, 116, 248, FALSE, 0, NULL),
(17, 85, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًا', 'وَيَسْأَلُونَكَ عَنِ الرُّوحِ قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُم مِّنَ الْعِلْمِ إِلَّا قَلِيلًا', NULL, 'And they ask you, [O Muḥammad], about the soul. Say, "The soul is of the affair [i.e., concern] of my Lord. And you [i.e., mankind] have not been given of knowledge except a little."', 'Dan mereka bertanya kepadamu tentang roh. Katakan: “Roh itu dari perkara urusan Tuhanku; dan kamu tidak diberikan ilmu pengetahuan melainkan sedikit sahaja”.', FALSE, NULL, NULL, 290, 15, 116, 249, FALSE, 0, NULL),
(17, 86, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِالَّذِي أَوْحَيْنَا إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِ عَلَيْنَا وَكِيلًا', NULL, 'And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us.', 'Dan sesungguhnya jika Kami kehendaki, tentulah Kami akan hapuskan apa yang Kami telah wahyukan kepadamu, kemudian engkau tidak akan beroleh sebarang pembela terhadap Kami untuk mengembalikannya.', FALSE, NULL, NULL, 290, 15, 116, 249, FALSE, 0, NULL),
(17, 87, 'إِلَّا رَحْمَةً مِّن رَّبِّكَ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًا', 'إِلَّا رَحْمَةً مِّن رَّبِّكَ إِنَّ فَضْلَهُ كَانَ عَلَيْكَ كَبِيرًا', NULL, 'Except [We have left it with you] as a mercy from your Lord. Indeed, His favor upon you has ever been great.', '(Tetapi kekalnya Al-Quran itu) hanyalah sebagai rahmat dari tuhanmu; sesungguhnya limpah kurnianya kepadamu (wahai Muhammad) amatlah besar.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 88, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', 'قُل لَّئِنِ اجْتَمَعَتِ الْإِنسُ وَالْجِنُّ عَلَىٰ أَن يَأْتُوا بِمِثْلِ هَٰذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', NULL, 'Say, "If mankind and the jinn gathered in order to produce the like of this Qur’ān, they could not produce the like of it, even if they were to each other assistants."', 'Katakanlah (wahai Muhammad): “Sesungguhnya jika sekalian manusia dan jin berhimpun dengan tujuan hendak membuat dan mendatangkan sebanding dengan Al-Quran ini, mereka tidak akan dapat membuat dan mendatangkan yang sebanding dengannya, walaupun mereka bantu-membantu sesama sendiri”.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ فَأَبَىٰ أَكْثَرُ النَّاسِ إِلَّا كُفُورًا', NULL, 'And We have certainly diversified for the people in this Qur’ān from every [kind of] example, but most of the people refused except disbelief.', 'Dan sesungguhnya Kami telah menerangkan berulang-ulang kepada manusia, di dalam Al-Quran ini, dengan berbagai-bagai contoh perbandingan (yang mendatangkan iktibar); dalam pada itu, kebanyakan manusia tidak mahu menerima selain dari kekufuran.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 90, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', 'وَقَالُوا لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ الْأَرْضِ يَنبُوعًا', NULL, 'And they say, "We will not believe you until you break open for us from the ground a spring', 'Dan mereka berkata: “Kami tidak sekali-kali akan beriman kepadamu (wahai Muhammad), sehingga engkau memancarkan matair dari bumi, bagi Kami.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 91, 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ الْأَنْهَارَ خِلَالَهَا تَفْجِيرًا', NULL, 'Or [until] you have a garden of palm trees and grapes and make rivers gush forth within them in force [and abundance]', 'Atau (sehingga) engkau mempunyai kebun dari pohon-pohon tamar dan anggur, kemudian engkau mengalirkan sungai-sungai dari celah-celahnya dengan aliran yang terpancar terus-menerus.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 92, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', 'أَوْ تُسْقِطَ السَّمَاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِيَ بِاللَّهِ وَالْمَلَائِكَةِ قَبِيلًا', NULL, 'Or you make the heaven fall upon us in fragments as you have claimed or you bring Allāh and the angels before [us]', 'Atau (sehingga) engkau gugurkan langit berkeping-keping atas kami, sebagaimana yang engkau katakan (akan berlaku); atau (sehingga) engkau bawakan Allah dan malaikat untuk kami menyaksikannya.', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 93, 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًا نَّقْرَؤُهُۥ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِي السَّمَاءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَابًا نَّقْرَؤُهُ قُلْ سُبْحَانَ رَبِّي هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', NULL, 'Or you have a house of ornament [i.e., gold] or you ascend into the sky. And [even then], we will not believe in your ascension until you bring down to us a book we may read." Say, "Exalted is my Lord! Was I ever but a human messenger?"', 'Atau (sehingga) engkau mempunyai sebuah rumah terhias dari emas; atau (sehingga) engkau naik ke langit; dan kami tidak sekali-kali akan percaya tentang kenaikanmu ke langit sebelum engkau turunkan kepada kami sebuah kitab yang dapat kami membacanya”. Katakanlah (wahai Muhammad): “Maha Suci Tuhanku! Bukankah aku ini hanya seorang manusia yang menjadi Rasul?', FALSE, NULL, NULL, 291, 15, 116, 249, FALSE, 0, NULL),
(17, 94, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًا رَّسُولًا', 'وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَىٰ إِلَّا أَن قَالُوا أَبَعَثَ اللَّهُ بَشَرًا رَّسُولًا', NULL, 'And what prevented the people from believing when guidance came to them except that they said, "Has Allāh sent a human messenger?"', 'Dan tiadalah yang menghalang orang-orang musyrik itu dari beriman ketika datang kepada mereka hidayah petunjuk, melainkan (keingkaran mereka tentang manusia menjadi Rasul, sehingga) mereka berkata dengan hairan: “Patutkah Allah mengutus seorang manusia menjadi Rasul?”', FALSE, NULL, NULL, 291, 15, 116, 250, FALSE, 0, NULL),
(17, 95, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا', 'قُل لَّوْ كَانَ فِي الْأَرْضِ مَلَائِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ السَّمَاءِ مَلَكًا رَّسُولًا', NULL, 'Say, "If there were upon the earth angels walking securely, We would have sent down to them from the heaven an angel [as a] messenger."', 'Katakanlah (wahai Muhammad): “Kalau ada di bumi, malaikat yang berjalan serta tinggal mendiaminya, tentulah kami akan turunkan kepada mereka dari langit, malaikat yang menjadi rasul”.', FALSE, NULL, NULL, 291, 15, 116, 250, FALSE, 0, NULL),
(17, 96, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'قُلْ كَفَىٰ بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ إِنَّهُ كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا', NULL, 'Say, "Sufficient is Allāh as Witness between me and you. Indeed He is ever, concerning His servants, Aware and Seeing."', 'Katakanlah lagi: “Cukuplah Allah menjadi saksi antaraku dengan kamu; sesungguhnya adalah Ia Amat Mendalam pengetahuanNya, lagi Amat Melihat akan keadaan hamba-hambaNya”.', FALSE, NULL, NULL, 291, 15, 116, 250, FALSE, 0, NULL),
(17, 97, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَىٰهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًا', 'وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَاءَ مِن دُونِهِ وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَاهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا', NULL, 'And whoever Allāh guides - he is the [rightly] guided; and whoever He sends astray - you will never find for them protectors besides Him, and We will gather them on the Day of Resurrection [fallen] on their faces - blind, dumb and deaf. Their refuge is Hell; every time it subsides, We increase [for] them blazing fire.', 'Dan sesiapa yang diberi hidayah petunjuk oleh Allah maka dia lah yang sebenar-benarnya berjaya mencapai kebahagiaan; dan sesiapa yang disesatkanNya maka engkau tidak sekali-kali akan mendapati bagi mereka, penolong-penolong yang lain daripadaNya. Dan Kami akan himpunkan mereka pada hari kiamat (dengan menyeret mereka masing-masing) atas mukanya, dalam keadaan buta, bisu dan pekak; tempat kediaman mereka: neraka Jahannam; tiap-tiap kali malap julangan apinya, Kami tambahi mereka dengan api yang menjulang-julang.', FALSE, NULL, NULL, 292, 15, 116, 250, FALSE, 0, NULL),
(17, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'ذَٰلِكَ جَزَاؤُهُم بِأَنَّهُمْ كَفَرُوا بِآيَاتِنَا وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', NULL, 'That is their recompense because they disbelieved in Our verses and said, "When we are bones and crumbled particles, will we [truly] be resurrected [in] a new creation?"', 'Balasan mereka yang sedemikian, ialah kerana mereka kufur ingkarkan ayat-ayat Kami, dan mereka berkata: “Adakah sesudah Kami menjadi tulang dan benda yang reput, adakah Kami akan dibangkitkan semula dalam kejadian yang baharu?”', FALSE, NULL, NULL, 292, 15, 116, 250, FALSE, 0, NULL),
(17, 99, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًا', 'أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَىٰ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى الظَّالِمُونَ إِلَّا كُفُورًا', NULL, 'Do they not see that Allāh, who created the heavens and earth, is [the one] Able to create the likes of them? And He has appointed for them a term, about which there is no doubt. But the wrongdoers refuse except disbelief.', 'Tidakkah mereka mahu memikirkan dan meyakini bahawa Allah yang menciptakan langit dan bumi, berkuasa menciptakan orang orang yang seperti mereka (dalam bentuk yang baharu), padahal Ia telahpun menentukan bagi mereka tempoh yang tidak ada syak padanya.? Dalam pada itu, orang orang yang zalim enggan menerima melainkan kekufuran.', FALSE, NULL, NULL, 292, 15, 117, 250, FALSE, 0, NULL),
(17, 100, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ وَكَانَ ٱلْإِنسَٰنُ قَتُورًا', 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَائِنَ رَحْمَةِ رَبِّي إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ الْإِنفَاقِ وَكَانَ الْإِنسَانُ قَتُورًا', NULL, 'Say [to them], "If you possessed the depositories of the mercy of my Lord, then you would withhold out of fear of spending." And ever has man been stingy.', 'Katakanlah (wahai muhammad): “jika kamu memiliki perbendaharaan rahmat Tuhanku pada ketika itu tentulah kamu akan berlaku bakhil kedekut kerana takut kehabisan; dan sememangnya manusia itu bertabiat bakhil kedekut”.', FALSE, NULL, NULL, 292, 15, 117, 250, FALSE, 0, NULL),
(17, 101, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًا', 'وَلَقَدْ آتَيْنَا مُوسَىٰ تِسْعَ آيَاتٍ بَيِّنَاتٍ فَاسْأَلْ بَنِي إِسْرَائِيلَ إِذْ جَاءَهُمْ فَقَالَ لَهُ فِرْعَوْنُ إِنِّي لَأَظُنُّكَ يَا مُوسَىٰ مَسْحُورًا', NULL, 'And We had certainly given Moses nine evident signs, so ask the Children of Israel [about] when he came to them and Pharaoh said to him, "Indeed I think, O Moses, that you are affected by magic."', 'Dan sesungguhnya Kami telah memberi kepada Nabi Musa sembilan mukjizat yang jelas nyata (membuktikan kebenarannya); maka bertanyalah (wahai Muhammad) kepada Bani Israil (tentang itu): Ketika Nabi Musa datang kepada Firaun dan kaumnya (serta menunjukkan mukjizatnya), lalu berkatalah Firaun kepadanya: “Sesungguhnya aku fikir, engkau ini wahai Musa, seorang yang terkena sihir”', FALSE, NULL, NULL, 292, 15, 117, 251, FALSE, 0, NULL),
(17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًا', 'قَالَ لَقَدْ عَلِمْتَ مَا أَنزَلَ هَٰؤُلَاءِ إِلَّا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ بَصَائِرَ وَإِنِّي لَأَظُنُّكَ يَا فِرْعَوْنُ مَثْبُورًا', NULL, '[Moses] said, "You have already known that none has sent down these [signs] except the Lord of the heavens and the earth as evidence, and indeed I think, O Pharaoh, that you are destroyed."', 'Nabi Musa menjawab: “Sebenarnya engkau (hai Firaun) telah pun mengetahui: tiadalah yang menurunkan mukjizat-mukjizat ini melainkan Tuhan yang mencipta dan mentadbirkan langit dan bumi, sebagai bukti-bukti yang menerangkan kebenaran; dan sebenarnya aku fikir, engkau hai Firaun, akan binasa”.', FALSE, NULL, NULL, 292, 15, 117, 251, FALSE, 0, NULL),
(17, 103, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًا', 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ الْأَرْضِ فَأَغْرَقْنَاهُ وَمَن مَّعَهُ جَمِيعًا', NULL, 'So he intended to drive them from the land, but We drowned him and those with him all together.', 'Maka Firaun pun berkira hendak mengusir mereka dari bumi (Mesir) lalu Kami tenggelamkan dia bersama-sama pengikut-pengikutnya seluruhnya.', FALSE, NULL, NULL, 292, 15, 117, 251, FALSE, 0, NULL),
(17, 104, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', 'وَقُلْنَا مِن بَعْدِهِ لِبَنِي إِسْرَائِيلَ اسْكُنُوا الْأَرْضَ فَإِذَا جَاءَ وَعْدُ الْآخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', NULL, 'And We said after him [i.e., Pharaoh] to the Children of Israel, "Dwell in the land, and when there comes the promise [i.e., appointment] of the Hereafter, We will bring you forth in [one] gathering."', 'Dan Kami katakan kepada Bani Israil, sesudah Firaun (dibinasakan): “Tinggallah kamu di negeri itu kemudian apabila datang tempoh hari akhirat, Kami datangkan kamu (ke Padang Mahsyar) dengan bercampur-aduk.', FALSE, NULL, NULL, 292, 15, 117, 251, FALSE, 0, NULL),
(17, 105, 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', 'وَبِالْحَقِّ أَنزَلْنَاهُ وَبِالْحَقِّ نَزَلَ وَمَا أَرْسَلْنَاكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', NULL, 'And with the truth We have sent it [i.e., the Qur’ān] down, and with the truth it has descended. And We have not sent you, [O Muḥammad], except as a bringer of good tidings and a warner.', 'Dan dengan cara yang sungguh layak serta berhikmat Kami turunkan Al-Quran, dan dengan meliputi segala kebenaran ia diturunkan; dan tiadalah Kami mengutusmu (wahai Muhammad) melainkan sebagai pembawa berita gembira (bagi orang-orang yang beriman) dan pembawa amaran (kepada orang-orang yang ingkar).', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(17, 106, 'وَقُرْءَانًا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَٰهُ تَنزِيلًا', 'وَقُرْآنًا فَرَقْنَاهُ لِتَقْرَأَهُ عَلَى النَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَاهُ تَنزِيلًا', NULL, 'And [it is] a Qur’ān which We have separated [by intervals] that you might recite it to the people over a prolonged period. And We have sent it down progressively.', 'Dan Al-Quran itu Kami bahagi-bahagikan supaya engkau membacakannya kepada manusia dengan lambat tenang; dan Kami menurunkannya beransur-ansur.', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(17, 107, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', 'قُلْ آمِنُوا بِهِ أَوْ لَا تُؤْمِنُوا إِنَّ الَّذِينَ أُوتُوا الْعِلْمَ مِن قَبْلِهِ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', NULL, 'Say, "Believe in it or do not believe." Indeed, those who were given knowledge before it - when it is recited to them, they fall upon their faces in prostration,', 'Katakanlah (wahai Muhammad kepada orang-orang yang ingkar itu): “Sama ada kamu beriman kepada Al-Quran atau kamu tiada beriman, (tidaklah menjadi hal); kerana sesungguhnya orang-orang yang diberi ilmu sebelum itu apabila dibacakan Al-Quran kepada mereka, mereka segera tunduk sujud (dalam keadaan hiba dan khusyuk);', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(17, 108, 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', 'وَيَقُولُونَ سُبْحَانَ رَبِّنَا إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', NULL, 'And they say, "Exalted is our Lord! Indeed, the promise of our Lord has been fulfilled."', 'Serta mereka menegaskan (dalam sujudnya): “Maha Suci Tuhan kami! Sesungguhnya janji Tuhan kami tetap terlaksana.”', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(17, 109, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا', 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا', NULL, 'And they fall upon their faces weeping, and it [i.e., the Qur’ān] increases them in humble submission.', 'Dan mereka segera tunduk sujud itu sambil menangis, sedang Al-Quran menambahkan mereka khusyuk.', FALSE, NULL, NULL, 293, 15, 117, 251, TRUE, 0, NULL),
(17, 110, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', 'قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', NULL, 'Say, "Call upon Allāh or call upon the Most Merciful [ar-Raḥmān]. Whichever [name] you call - to Him belong the best names." And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way.', 'Katakanlah (wahai Muhammad): “Serulah nama “Allah” atau nama “Ar-Rahman”, yang mana sahaja kamu serukan (dari kedua-dua nama itu adalah baik belaka); kerana Allah mempunyai banyak nama-nama yang baik serta mulia”. Dan janganlah engkau nyaringkan bacaan doa atau sembahyangmu, juga janganlah engkau perlahankannya, dan gunakanlah sahaja satu cara yang sederhana antara itu.', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(17, 111, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّ مِّنَ ٱلذُّلِّ وَكَبِّرْهُ تَكْبِيرًۢا', 'وَقُلِ الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا', NULL, 'And say, "Praise to Allāh, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification."', 'Dan katakanlah: “Segala puji tertentu bagi Allah yang tiada mempunyai anak, dan tiada bagiNya sekutu dalam urusan kerajaanNya, dan tiada bagiNya penolong disebabkan sesuatu kelemahanNya; dan hendaklah engkau membesarkan serta memuliakanNya dengan bersungguh-sungguh!”', FALSE, NULL, NULL, 293, 15, 117, 251, FALSE, 0, NULL),
(18, 1, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَـٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ۜ', 'الحمد لله الذي انزل على عبده الكتاب ولم يجعل له عوجا', NULL, '[All] praise is [due] to Allāh, who has sent down upon His Servant [Muḥammad (ﷺ)] the Book and has not made therein any deviance.', 'Segala puji tertentu bagi Allah yang telah menurunkan kepada hambaNya (Muhammad), Kitab suci Al-Quran, dan tidak menjadikan padanya sesuatu yang bengkok (terpesong):', FALSE, NULL, NULL, 293, 15, 117, 252, FALSE, 11, NULL),
(18, 2, 'قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا', 'قيما لينذر باسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا حسنا', NULL, '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward [i.e., Paradise]', '(Bahkan keadaannya) tetap benar lagi menjadi pengawas turunnya Al-Quran untuk memberi amaran (kepada orang-orang yang ingkar) dengan azab yang seberat-beratnya dari sisi Allah, dan memberi berita gembira kepada orang-orang yang beriman yang mengerjakan amal-amal soleh, bahawa mereka akan beroleh balasan yang baik.', FALSE, NULL, NULL, 293, 15, 117, 252, FALSE, 15, NULL),
(18, 3, 'مَّـٰكِثِينَ فِيهِ أَبَدًا', 'ماكثين فيه ابدا', NULL, 'In which they will remain forever', 'Mereka tinggal tetap dalam (balasan yang baik) itu selama-lamanya.', FALSE, NULL, NULL, 293, 15, 117, 252, FALSE, 3, NULL),
(18, 4, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا', 'وينذر الذين قالوا اتخذ الله ولدا', NULL, 'And to warn those who say, "Allāh has taken a son."', 'Dan juga Al-Quran itu memberi amaran kepada orang-orang yang berkata: “Allah mempunyai anak”.', FALSE, NULL, NULL, 293, 15, 117, 252, FALSE, 6, NULL),
(18, 5, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍ وَلَا لِـَٔابَآئِهِمْ ۚ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَٰهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًا', 'ما لهم به من علم ولا لابائهم كبرت كلمة تخرج من افواههم ان يقولون الا كذبا', NULL, 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.', '(Sebenarnya) mereka tiada mempunyai sebarang pengetahuan mengenainya, dan tiada juga bagi datuk nenek mereka; besar sungguh perkataan syirik yang keluar dari mulut mereka; mereka hanya mengatakan perkara yang dusta.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 16, NULL),
(18, 6, 'فَلَعَلَّكَ بَـٰخِعٌ نَّفْسَكَ عَلَىٰٓ ءَاثَـٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَـٰذَا ٱلْحَدِيثِ أَسَفًا', 'فلعلك باخع نفسك على اثارهم ان لم يؤمنوا بهذا الحديث اسفا', NULL, 'Then perhaps you would kill yourself through grief over them, [O Muḥammad], if they do not believe in this message, [and] out of sorrow.', 'Maka jangan-jangan pula engkau (wahai Muhammad), membinasakan dirimu disebabkan menanggung dukacita terhadap kesan-kesan perbuatan buruk mereka, jika mereka enggan beriman kepada keterangan Al-Quran ini.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 11, NULL),
(18, 7, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا', 'انا جعلنا ما على الارض زينة لها لنبلوهم ايهم احسن عملا', NULL, 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.', 'Sesungguhnya Kami telah jadikan apa yang ada di muka bumi sebagai perhiasan baginya, kerana kami hendak menguji mereka, siapakah di antaranya yang lebih baik amalnya.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 11, NULL),
(18, 8, 'وَإِنَّا لَجَـٰعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا', 'وانا لجاعلون ما عليها صعيدا جرزا', NULL, 'And indeed, We will make that which is upon it [into] a barren ground.', 'Dan sesungguhnya Kami akan jadikan apa yang ada di bumi itu (punah-ranah) sebagai tanah yang tandus.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 6, NULL),
(18, 9, 'أَمْ حَسِبْتَ أَنَّ أَصْحَـٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَـٰتِنَا عَجَبًا', 'ام حسبت ان اصحاب الكهف والرقيم كانوا من اياتنا عجبا', NULL, 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?', 'Adakah engkau menyangka (wahai Muhammad), bahawa kisah “Ashaabul Kahfi” dan “Ar-Raqiim” itu sahaja yang menakjubkan di antara tanda-tanda yang membuktikan kekuasaan Kami?', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 10, NULL),
(18, 10, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', 'اذ اوى الفتية الى الكهف فقالوا ربنا اتنا من لدنك رحمة وهيئ لنا من امرنا رشدا', NULL, '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."', '(Ingatkanlah peristiwa) ketika serombongan orang-orang muda pergi ke gua, lalu mereka berdoa: “Wahai Tuhan kami! Kurniakanlah kami rahmat dari sisiMu, dan berilah kemudahan-kemudahan serta pimpinan kepada kami untuk keselamatan ugama kami”.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 16, NULL),
(18, 11, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًا', 'فضربنا على اذانهم في الكهف سنين عددا', NULL, 'So We cast [a cover of sleep] over their ears within the cave for a number of years.', 'Lalu Kami tidurkan mereka dengan nyenyaknya dalam gua itu, bertahun-tahun, yang banyak bilangannya.', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 7, NULL),
(18, 12, 'ثُمَّ بَعَثْنَـٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًا', 'ثم بعثناهم لنعلم اي الحزبين احصى لما لبثوا امدا', NULL, 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.', 'Kemudian Kami bangkitkan mereka (dari tidurnya), untuk Kami menguji siapakah dari dua golongan di antara mereka yang lebih tepat kiraannya, tentang lamanya mereka hidup (dalam gua itu).', FALSE, NULL, NULL, 294, 15, 117, 252, FALSE, 9, NULL),
(18, 13, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَـٰهُمْ هُدًى', 'نحن نقص عليك نباهم بالحق انهم فتية امنوا بربهم وزدناهم هدى', NULL, 'It is We who relate to you, [O Muḥammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.', 'Kami ceritakan kepadamu (wahai Muhammad) perihal mereka dengan benar; sesungguhnya mereka itu orang-orang muda yang beriman kepada Tuhan mereka, dan kami tambahi mereka dengan hidayah petunjuk.', FALSE, NULL, NULL, 294, 15, 117, 253, FALSE, 11, NULL),
(18, 14, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَـٰهًا ۖ لَّقَدْ قُلْنَآ إِذًا شَطَطًا', 'وربطنا على قلوبهم اذ قاموا فقالوا ربنا رب السماوات والارض لن ندعو من دونه الها لقد قلنا اذا شططا', NULL, 'And We bound [i.e., made firm] their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.', 'Dan Kami kuatkan hati mereka (dengan kesabaran dan keberanian), semasa mereka bangun (menegaskan tauhid) lalu berkata: “Tuhan kami ialah Tuhan yang mencipta dan mentadbirkan langit dan bumi; kami tidak sekali-kali akan menyembah Tuhan yang lain dari padanya; jika kami menyembah yang lainnya bermakna kami memperkatakan dan mengakui sesuatu yang jauh dari kebenaran.”', FALSE, NULL, NULL, 294, 15, 117, 253, FALSE, 19, NULL),
(18, 15, 'هَـٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً ۖ لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَـٰنٍۭ بَيِّنٍ ۖ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا', 'هؤلاء قومنا اتخذوا من دونه الهة لولا ياتون عليهم بسلطان بين فمن اظلم ممن افترى على الله كذبا', NULL, 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear evidence? And who is more unjust than one who invents about Allāh a lie?"', '(Mereka berkata pula sesama sendiri): “Kaum kita itu, menyembah beberapa tuhan yang lain dari Allah; sepatutnya mereka mengemukakan keterangan yang nyata yang membuktikan ketuhanan makhluk-makhluk yang mereka sembah itu? (Tetapi mereka tidak dapat berbuat demikian); Maka tidak ada yang lebih zalim dari orang-orang yang berdusta terhadap Allah.', FALSE, NULL, NULL, 294, 15, 117, 253, FALSE, 18, NULL),
(18, 16, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا', 'واذ اعتزلتموهم وما يعبدون الا الله فاووا الى الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من امركم مرفقا', NULL, '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allāh, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."', 'Dan oleh kerana kamu telah mengasingkan diri dari mereka dan dari apa yang mereka sembah yang lain dari Allah, maka pergilah kamu berlindung di gua itu, supaya Tuhan kamu melimpahkan dari rahmatnya kepada kamu, dan menyediakan kemudahan-kemudahan untuk (menjayakan) urusan kamu dengan memberikan bantuan yang berguna”.', FALSE, NULL, NULL, 295, 15, 117, 253, FALSE, 19, NULL),
(18, 17, '۞ وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ ۗ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا', 'وترى الشمس اذا طلعت تزاور عن كهفهم ذات اليمين واذا غربت تقرضهم ذات الشمال وهم في فجوة منه ذلك من ايات الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا', NULL, 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [lying] within an open space thereof. That was from the signs of Allāh. He whom Allāh guides is the [rightly] guided, but he whom He sends astray - never will you find for him a protecting guide.', 'Dan engkau akan melihat matahari ketika terbit, cenderung ke kanan dari gua mereka; dan apabila ia terbenam, meninggalkan mereka ke arah kiri, sedang mereka berada dalam satu lapangan gua itu. Yang demikian ialah dari tanda-tanda (yang membuktikan kekuasaan) Allah. Sesiapa yang diberi hidayah petunjuk oleh Allah, maka dia lah yang berjaya mencapai kebahagiaan; dan sesiapa yang disesatkanNya maka engkau tidak sekali-kali akan beroleh sebarang penolong yang dapat menunjukkan (jalan yang benar) kepadanya.', FALSE, NULL, NULL, 295, 15, 118, 253, FALSE, 34, NULL),
(18, 18, 'وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ ۚ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ ۖ وَكَلْبُهُم بَـٰسِطٌ ذِرَاعَيْهِ بِٱلْوَصِيدِ ۚ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا', 'وتحسبهم ايقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم باسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا', NULL, 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.', 'Dan engkau sangka mereka sedar, padahal mereka tidur; dan Kami balik-balikkan mereka dalam tidurnya ke sebelah kanan dan ke sebelah kiri; sedang anjing mereka menghulurkan dua kaki depannya dekat pintu gua; jika engkau melihat mereka, tentulah engkau akan berpaling melarikan diri dari mereka, dan tentulah engkau akan merasa sepenuh-penuh gerun takut kepada mereka.', FALSE, NULL, NULL, 295, 15, 118, 254, FALSE, 22, NULL),
(18, 19, 'وَكَذَٰلِكَ بَعَثْنَـٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ ۚ قَالَ قَآئِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ ۖ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ ۚ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَـٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 'وكذلك بعثناهم ليتساءلوا بينهم قال قائل منهم كم لبثتم قالوا لبثنا يوما او بعض يوم قالوا ربكم اعلم بما لبثتم فابعثوا احدكم بورقكم هذه الى المدينة فلينظر ايها ازكى طعاما فلياتكم برزق منه وليتلطف ولا يشعرن بكم احدا', NULL, 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.', 'Dan demikianlah pula Kami bangkitkan mereka (dari tidurnya), supaya mereka bertanya-tanyaan sesama sendiri. Salah seorang di antaranya bertanya: “Berapa lama kamu tidur?” (sebahagian dari) mereka menjawab: “Kita telah tidur selama sehari atau sebahagian dari sehari”. (Sebahagian lagi dari) mereka berkata: “Tuhan kamu lebih menengetahui tentang lamanya kamu tidur; sekarang utuslah salah seorang dari kamu, membawa wang perak kamu ini ke bandar; kemudian biarlah dia mencari dan memilih mana-mana jenis makanan yang lebih baik lagi halal (yang dijual di situ); kemudian hendaklah ia membawa untuk kamu sedikit habuan daripadanya; dan hendaklah ia berlemah-lembut dengan bersungguh-sungguh (semasa di bandar); dan janganlah dia melakukan sesuatu yang menyebabkan sesiapapun menyedari akan hal kamu.', FALSE, NULL, NULL, 295, 15, 118, 254, FALSE, 38, NULL),
(18, 20, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًا', 'انهم ان يظهروا عليكم يرجموكم او يعيدوكم في ملتهم ولن تفلحوا اذا ابدا', NULL, 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."', '“Sesungguhnya, kalaulah mereka mengetahui hal kamu, tentulah mereka akan merejam dengan membunuh kamu, atau mereka akan mengembalikan kamu kepada ugama mereka (secara paksa); dan jika berlaku demikian, kamu tidak sekali-kali akan berjaya selama-lamanya”.', FALSE, NULL, NULL, 295, 15, 118, 254, FALSE, 13, NULL),
(18, 21, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًا رَّبُّهُمْ أَعْلَمُ بِهِمْ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ وَأَنَّ السَّاعَةَ لَا رَيْبَ فِيهَا إِذْ يَتَنَازَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا ابْنُوا عَلَيْهِم بُنْيَانًا رَّبُّهُمْ أَعْلَمُ بِهِمْ قَالَ الَّذِينَ غَلَبُوا عَلَىٰ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', NULL, 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allāh is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."', 'Dan demikianlah Kami dedahkan hal mereka kepada orang ramai supaya orang-orang itu mengetahui bahawa janji Allah menghidupkan semula orang mati adalah benar, dan bahawa hari kiamat itu tidak ada sebarang syak padanya; pendedahan itu berlaku semasa orang-orang itu berbantahan sesama sendiri mengenai perkara hidupnya semula orang mati. Setelah itu maka (sebahagian dari) mereka berkata: “Dirikanlah sebuah bangunan di sisi gua mereka, Allah jualah yang mengetahui akan hal ehwal mereka”. orang-orang yang berkuasa atas urusan mereka (pihak raja) pula berkata: “Sebenarnya kami hendak membina sebuah masjid di sisi gua mereka”.', FALSE, NULL, NULL, 296, 15, 118, 254, FALSE, 0, NULL),
(18, 22, 'سَيَقُولُونَ ثَلَٰثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءً ظَٰهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', 'سَيَقُولُونَ ثَلَاثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًا بِالْغَيْبِ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ قُل رَّبِّي أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَاءً ظَاهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', NULL, 'They [i.e., people] will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muḥammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."', '(Sebahagian dari) mereka akan berkata: “Bilangan Ashaabul Kahfi itu tiga orang, yang keempatnya ialah anjing mereka”; dan setengahnya pula berkata: “Bilangan mereka lima orang, yang keenamnya ialah anjing mereka” - secara meraba-raba dalam gelap akan sesuatu yang tidak diketahui; dan setengahnya yang lain berkata: “Bilangan mereka tujuh orang, dan yang kedelapannya ialah anjing mereka”. Katakanlah (wahai Muhammad): “Tuhanku lebih mengetahui akan bilangan mereka, tiada yang mengetahui bilangannya melainkan sedikit”. Oleh itu, janganlah engkau berbahas dengan sesiapapun mengenai mereka melainkan dengan bahasan (secara sederhana) yang nyata (keterangannya di dalam Al-Quran), dan janganlah engkau meminta penjelasan mengenai hal mereka kepada seseorangpun dari golongan (yang membincangkannya).', FALSE, NULL, NULL, 296, 15, 118, 254, FALSE, 0, NULL),
(18, 23, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا', 'وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَٰلِكَ غَدًا', NULL, 'And never say of anything, "Indeed, I will do that tomorrow,"', 'Dan janganlah engkau berkata mengenai sesuatu (yang hendak dikerjakan): “Bahawa aku akan lakukan yang demikian itu, kemudian nanti”.', FALSE, NULL, NULL, 296, 15, 118, 255, FALSE, 0, NULL),
(18, 24, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًا', 'إِلَّا أَن يَشَاءَ اللَّهُ وَاذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰ أَن يَهْدِيَنِ رَبِّي لِأَقْرَبَ مِنْ هَٰذَا رَشَدًا', NULL, 'Except [when adding], "If Allāh wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."', 'Melainkan (hendaklah disertakan dengan berkata): “Insya Allah”. Dan ingatlah serta sebutlah akan Tuhanmu jika engkau lupa; dan katakanlah: “Mudah-mudahan Tuhanku memimpinku ke jalan petunjuk yang lebih dekat dan lebih terang dari ini”.', FALSE, NULL, NULL, 296, 15, 118, 255, FALSE, 0, NULL),
(18, 25, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍ سِنِينَ وَٱزْدَادُوا۟ تِسْعًا', 'وَلَبِثُوا فِي كَهْفِهِمْ ثَلَاثَ مِائَةٍ سِنِينَ وَازْدَادُوا تِسْعًا', NULL, 'And they remained in their cave for three hundred years and exceeded by nine.', 'Dan mereka telah tinggal tidur dalam gua mereka: Tiga ratus tahun dengan kiraan Ahli Kitab), dan sembilan lagi (dengan kiraan kamu).', FALSE, NULL, NULL, 296, 15, 118, 255, FALSE, 0, NULL),
(18, 26, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَبْصِرْ بِهِۦ وَأَسْمِعْ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًا', 'قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا لَهُ غَيْبُ السَّمَاوَاتِ وَالْأَرْضِ أَبْصِرْ بِهِ وَأَسْمِعْ مَا لَهُم مِّن دُونِهِ مِن وَلِيٍّ وَلَا يُشْرِكُ فِي حُكْمِهِ أَحَدًا', NULL, 'Say, "Allāh is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."', 'Katakanlah (wahai Muhammad): “Allah jua yang mengetahui tentang masa mereka tidur; bagiNya lah tertentu ilmu pengetahuan segala rahsia langit dan bumi; terang sungguh penglihatanNya (terhadap segala-galanya)! Tidak ada bagi penduduk langit dan bumi pengurus selain daripadaNya dan Ia tidak menjadikan sesiapapun masuk campur dalam hukumNya.', FALSE, NULL, NULL, 296, 15, 118, 255, FALSE, 0, NULL),
(18, 27, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'وَاتْلُ مَا أُوحِيَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَاتِهِ وَلَن تَجِدَ مِن دُونِهِ مُلْتَحَدًا', NULL, 'And recite, [O Muḥammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.', 'Dan baca serta turutlah apa yang diwahyukan kepadamu dari kitab Tuhanmu; tiada sesiapa yang dapat mengubah kalimah-kalimahNya; dan engkau tidak sekali-kali akan mendapat tempat perlindungan selain daripadaNya.', FALSE, NULL, NULL, 296, 15, 118, 255, FALSE, 0, NULL),
(18, 28, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًا', 'وَاصْبِرْ نَفْسَكَ مَعَ الَّذِينَ يَدْعُونَ رَبَّهُم بِالْغَدَاةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ الْحَيَاةِ الدُّنْيَا وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُ عَن ذِكْرِنَا وَاتَّبَعَ هَوَاهُ وَكَانَ أَمْرُهُ فُرُطًا', NULL, 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His face [i.e., acceptance]. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.', 'Dan jadikanlah dirimu sentiasa berdamping rapat dengan orang-orang yang beribadat kepada Tuhan mereka pada waktu pagi dan petang, yang mengharapkan keredaan Allah semata-mata; dan janganlah engkau memalingkan pandanganmu daripada mereka hanya kerana engkau mahukan kesenangan hidup di dunia; dan janganlah engkau mematuhi orang yang Kami ketahui hatinya lalai daripada mengingati dan mematuhi pengajaran Kami di dalam Al-Quran, serta ia menurut hawa nafsunya, dan tingkah-lakunya pula adalah melampaui kebenaran.', FALSE, NULL, NULL, 297, 15, 118, 255, FALSE, 0, NULL),
(18, 29, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', 'وَقُلِ الْحَقُّ مِن رَّبِّكُمْ فَمَن شَاءَ فَلْيُؤْمِن وَمَن شَاءَ فَلْيَكْفُرْ إِنَّا أَعْتَدْنَا لِلظَّالِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا وَإِن يَسْتَغِيثُوا يُغَاثُوا بِمَاءٍ كَالْمُهْلِ يَشْوِي الْوُجُوهَ بِئْسَ الشَّرَابُ وَسَاءَتْ مُرْتَفَقًا', NULL, 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.', 'Dan katakanlah (wahai Muhammad): “Kebenaran itu ialah yang datang dari Tuhan kamu, maka sesiapa yang mahu beriman, hendaklah ia beriman; dan sesiapa yang mahu kufur ingkar, biarlah dia mengingkarinya”. Kerana Kami telah menyediakan bagi orang-orang yang berlaku zalim itu api neraka, yang meliputi mereka laksana khemah; dan jika mereka meminta pertolongan kerana dahaga, mereka diberi pertolongan dengan air yang seperti tembaga cair yang membakar muka; amatlah buruknya minuman itu, dan amatlah buruknya neraka sebagai tempat bersenang-senang.', FALSE, NULL, NULL, 297, 15, 118, 255, FALSE, 0, NULL),
(18, 30, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', NULL, 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.', 'Sebenarnya orang-orang yang beriman dan beramal soleh sudah tetap Kami tidak akan menghilangkan pahala orang-orang yang berusaha memperbaiki amalnya.', FALSE, NULL, NULL, 297, 15, 118, 255, FALSE, 0, NULL),
(18, 31, 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', 'أُولَٰئِكَ لَهُمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ نِعْمَ الثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', NULL, 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.', 'Mereka itu, disediakan baginya syurga yang kekal, yang mengalir di bawahnya beberapa sungai; mereka dihiaskan di dalamnya dengan gelang-gelang tangan emas, dan memakai pakaian hijau dari sutera yang nipis dan sutera tebal yang bersulam; mereka berehat di dalamnya dengan berbaring di atas pelamin-pelamin (yang berhias). Demikian itulah balasan yang sebaik-baiknya dan demikian itulah Syurga tempat berehat yang semolek-moleknya.', FALSE, NULL, NULL, 297, 15, 118, 255, FALSE, 0, NULL),
(18, 32, 'وَٱضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍ وَحَفَفْنَٰهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', 'وَاضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', NULL, 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.', 'Dan berikanlah kepada mereka satu contoh: Dua orang lelaki, Kami adakan bagi salah seorang di antaranya, dua buah kebun anggur; dan Kami kelilingi kebun-kebun itu dengan pohon-pohon tamar, serta Kami jadikan di antara keduanya, jenis-jenis tanaman yang lain.', FALSE, NULL, NULL, 297, 15, 119, 256, FALSE, 0, NULL),
(18, 33, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًٔا وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًا', 'كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْئًا وَفَجَّرْنَا خِلَالَهُمَا نَهَرًا', NULL, 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.', 'Kedua-dua kebun itu mengeluarkan hasilnya, dan tiada mengurangi sedikitpun dari hasil itu; dan kami juga mengalirkan di antara keduanya sebatang sungai.', FALSE, NULL, NULL, 297, 15, 119, 256, FALSE, 0, NULL),
(18, 34, 'وَكَانَ لَهُۥ ثَمَرٌ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', 'وَكَانَ لَهُ ثَمَرٌ فَقَالَ لِصَاحِبِهِ وَهُوَ يُحَاوِرُهُ أَنَا أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', NULL, 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."', 'Tuan kebun itu pula ada mempunyai harta (yang lain); lalu berkatalah ia kepada rakannya, semasa ia berbincang dengannya: “Aku lebih banyak harta daripadamu, dan lebih berpengaruh dengan pengikut-pengikutku yang ramai”.', FALSE, NULL, NULL, 297, 15, 119, 256, FALSE, 0, NULL),
(18, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًا', 'وَدَخَلَ جَنَّتَهُ وَهُوَ ظَالِمٌ لِّنَفْسِهِ قَالَ مَا أَظُنُّ أَن تَبِيدَ هَٰذِهِ أَبَدًا', NULL, 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.', 'Dan ia pun masuk ke kebunnya (bersama-sama rakannya), sedang ia berlaku zalim kepada dirinya sendiri (dengan sebab kufurnya), sambil ia berkata: “Aku tidak fikir, kebun ini akan binasa selama-lamanya.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 36, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', 'وَمَا أَظُنُّ السَّاعَةَ قَائِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', NULL, 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."', 'Dan aku tidak fikir, hari kiamat kan berlaku; dan kalaulah aku dikembalikan kepada Tuhanku (sebagaimana kepercayaanmu), tentulah aku akan mendapat tempat kembali yang lebih baik daripada ini.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 37, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّىٰكَ رَجُلًا', 'قَالَ لَهُ صَاحِبُهُ وَهُوَ يُحَاوِرُهُ أَكَفَرْتَ بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّاكَ رَجُلًا', NULL, 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?', 'berkatalah rakannya kepadanya, semasa ia berbincang dengannya: “Patutkah engkau kufur ingkar kepada Allah yang menciptakan engkau dari tanah, kemudian dari air benih, kemudian Ia membentukmu dengan sempurna sebagai seorang lelaki?', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 38, 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًا', 'لَّٰكِنَّا هُوَ اللَّهُ رَبِّي وَلَا أُشْرِكُ بِرَبِّي أَحَدًا', NULL, 'But as for me, He is Allāh, my Lord, and I do not associate with my Lord anyone.', 'Tetapi aku sendiri percaya dan yakin dengan sepenuhnya bahawa Dia lah Allah, Tuhanku, dan aku tidak sekutukan sesuatu pun dengan Tuhanku.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 39, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًا وَوَلَدًا', 'وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ إِن تَرَنِ أَنَا أَقَلَّ مِنكَ مَالًا وَوَلَدًا', NULL, 'And why did you, when you entered your garden, not say, ''What Allāh willed [has occurred]; there is no power except in Allāh''? Although you see me less than you in wealth and children,', 'Dan sepatutnya semasa engkau masuk ke kebunmu, berkata: (Semuanya ialah barang yang dikehendaki Allah)! (tiada daya dan upaya melainkan dengan pertolongan Allah)? Kalau engkau memandangku sangat kurang tentang harta dan anak, berbanding denganmu,', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 40, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', 'فَعَسَىٰ رَبِّي أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ السَّمَاءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', NULL, 'It may be that my Lord will give me [something] better than your garden and will send upon it a [disastrous] penalty from the sky, and it will become a smooth, dusty ground,', 'Maka mudah-mudahan Tuhanku akan mengurniakan daku lebih baik daripada kebunmu, dan (aku bimbang) dia akan menimpakannya dengan bala, bencana dari langit, sehinggalah menjadilah kebunmu itu tanah yang licin tandus.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 41, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًا', 'أَوْ يُصْبِحَ مَاؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُ طَلَبًا', NULL, 'Or its water will become sunken [into the earth], so you would never be able to seek it."', 'Ataupun air kebun itu akan menjadi kering ditelan bumi, maka dengan yang demikian, engkau tidak akan dapat mencarinya lagi”.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 42, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًا', 'وَأُحِيطَ بِثَمَرِهِ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَا أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَا لَيْتَنِي لَمْ أُشْرِكْ بِرَبِّي أَحَدًا', NULL, 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."', 'Dan segala tanaman serta hartabendanya itupun dibinasakan, lalu jadilah ia membalik-balikkan kedua tapak tangannya (kerana menyesal) terhadap segala perbelanjaan yang telah dibelanjakannya pada kebun-kebunnya, sedang kebun-kebun itu runtuh junjung-junjung tanamannya; sambil dia berkata: “Alangkah baiknya kalau aku tidak sekutukan sesuatupun dengan Tuhanku!”', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 43, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', 'وَلَمْ تَكُن لَّهُ فِئَةٌ يَنصُرُونَهُ مِن دُونِ اللَّهِ وَمَا كَانَ مُنتَصِرًا', NULL, 'And there was for him no company to aid him other than Allāh, nor could he defend himself.', 'Dan ia tidak mendapat sebarang golongan yang boleh menolongnya, selain dari Allah; dan ia pula tidak dapat membela dirinya sendiri.', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 44, 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', 'هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', NULL, 'There the authority is [completely] for Allāh, the Truth. He is best in reward and best in outcome.', 'Pada saat yang sedemikian itu kekuasaan memberi pertolongan hanya tertentu bagi Allah, Tuhan yang sebenar-benarnya; Dia lah sebaik-baik pemberi pahala, dan sebaik-baik pemberi kesudahan yang berbahagia (kepada hamba-hambaNya yang taat).', FALSE, NULL, NULL, 298, 15, 119, 256, FALSE, 0, NULL),
(18, 45, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَٰحُ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا', 'وَاضْرِبْ لَهُم مَّثَلَ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّيَاحُ وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ مُّقْتَدِرًا', NULL, 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allāh is ever, over all things, Perfect in Ability.', 'Dan kemukakanlah kepada mereka misal perbandingan: Kehidupan dunia ini samalah seperti air yang Kami turunkan dari langit, lalu bercampur aduklah tanaman di bumi antara satu sama lain (dan kembang suburlah ia) disebabkan air itu; kemudian menjadilah ia kering hancur ditiup angin; dan (ingatlah) adalah Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 298, 15, 119, 257, FALSE, 0, NULL),
(18, 46, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', 'الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', NULL, 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one''s] hope.', 'Harta benda dan anak pinak itu, ialah perhiasan hidup di dunia; dan amal-amal soleh yang kekal faedahnya itu lebih baik pada sisi Tuhanmu sebagai pahala balasan, dan lebih baik sebagai asas yang memberi harapan.', FALSE, NULL, NULL, 299, 15, 119, 257, FALSE, 0, NULL),
(18, 47, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةً وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', 'وَيَوْمَ نُسَيِّرُ الْجِبَالَ وَتَرَى الْأَرْضَ بَارِزَةً وَحَشَرْنَاهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', NULL, 'And [warn of] the Day when We will remove the mountains and you will see the earth exposed, and We will gather them and not leave behind from them anyone.', 'Dan (ingatkanlah) hari Kami bongkar dan terbangkan gunung-ganang dan engkau akan melihat (seluruh) muka bumi terdedah nyata; dan Kami himpunkan mereka (di padang Mahsyar) sehingga Kami tidak akan tinggalkan seorangpun dari mereka.', FALSE, NULL, NULL, 299, 15, 119, 257, FALSE, 0, NULL),
(18, 48, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', 'وَعُرِضُوا عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', NULL, 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."', 'Dan mereka tetap akan dibawa mengadap Tuhanmu dengan berbaris teratur, (sambil dikatakan kepada mereka): “Kamu sekarang telah datang kepada Kami - (berseorangan) sebagaimana Kami telah jadikan kamu pada mulanya; bahkan kamu dahulu menyangka, bahawa kami tidak akan menjadikan bagi kamu masa yang tertentu (untuk melaksanakan apa yang Kami telah janjikan)”.', FALSE, NULL, NULL, 299, 15, 119, 257, FALSE, 0, NULL),
(18, 49, 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', 'وَوُضِعَ الْكِتَابُ فَتَرَى الْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَالِ هَٰذَا الْكِتَابِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّا أَحْصَاهَا وَوَجَدُوا مَا عَمِلُوا حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', NULL, 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.', 'Dan “Kitab-kitab Amal” juga tetap akan dibentangkan, maka engkau akan melihat orang-orang yang berdosa itu, merasa takut akan apa yang tersurat di dalamnya; dan mereka akan berkata: “Aduhai celakanya kami, mengapa kitab ini demikian keadaannya? Ia tidak meninggalkan yang kecil atau yang besar, melainkan semua dihitungnya!” Dan mereka dapati segala yang mereka kerjakan itu sedia (tertulis di dalamnya); dan (ingatlah) Tuhanmu tidak berlaku zalim kepada seseorangpun.', FALSE, NULL, NULL, 299, 15, 119, 257, FALSE, 0, NULL),
(18, 50, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ بِئْسَ لِلظَّٰلِمِينَ بَدَلًا', 'وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ مِن دُونِي وَهُمْ لَكُمْ عَدُوٌّ بِئْسَ لِلظَّالِمِينَ بَدَلًا', NULL, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from [i.e., disobeyed] the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.', 'Dan (ingatkanlah peristiwa) ketika Kami berfirman kepada malaikat: “Sujudlah kamu kepada Adam”; lalu mereka sujud melainkan iblis; ia adalah berasal dari golongan jin, lalu ia menderhaka terhadap perintah Tuhannya. Oleh itu, patutkah kamu hendak menjadikan iblis dan keturunannya sebagai sahabat-sahabat karib yang menjadi pemimpin selain daripadaku? Sedang mereka itu ialah musuh bagi kamu. Amatlah buruknya bagi orang-orang yang zalim: pengganti yang mereka pilih itu.', FALSE, NULL, NULL, 299, 15, 119, 258, FALSE, 0, NULL),
(18, 51, 'مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًا', 'مَّا أَشْهَدتُّهُمْ خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا', NULL, 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.', 'Aku tidak memanggil mereka menyaksi atau membantuKu menciptakan langit dan bumi, dan tidak juga meminta bantuan setengahnya untuk menciptakan setengahnya yang lain; dan tidak sepatutnya Aku mengambil makhluk-makhluk yang menyesatkan itu sebagai pembantu.', FALSE, NULL, NULL, 299, 15, 120, 258, FALSE, 0, NULL),
(18, 52, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', 'وَيَوْمَ يَقُولُ نَادُوا شُرَكَائِيَ الَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', NULL, 'And [warn of] the Day when He will say, "Call My ''partners'' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.', 'Dan (ingatkanlah) masa Allah berfirman: “Panggilah sekutu-sekutuKu yang kamu katakan itu (untuk menolong kamu); lalu mereka memanggilnya, tetapi sia-sia sahaja, kerana makhluk-makhluk itu tidak menyahut seruan mereka: dan kami jadikan untuk mereka bersama sebuah tempat azab yang membinasakan.', FALSE, NULL, NULL, 299, 15, 120, 258, FALSE, 0, NULL),
(18, 53, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًا', 'وَرَأَى الْمُجْرِمُونَ النَّارَ فَظَنُّوا أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا', NULL, 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.', 'Dan orang-orang yang berdosa itu tetap akan melihat neraka, maka yakinlah mereka, bahawa mereka akan jatuh ke dalamnya dan mereka tidak akan mendapati sebarang jalan untuk mengelakkan diri daripadanya.', FALSE, NULL, NULL, 299, 15, 120, 258, FALSE, 0, NULL),
(18, 54, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍ جَدَلًا', 'وَلَقَدْ صَرَّفْنَا فِي هَٰذَا الْقُرْآنِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ الْإِنسَانُ أَكْثَرَ شَيْءٍ جَدَلًا', NULL, 'And We have certainly diversified in this Qur’ān for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.', 'Dan demi sesungguhnya Kami telah huraikan dengan berbagai-bagai cara di dalam Al-Quran ini untuk umat manusia, dari segala jenis contoh bandingan; dan sememangnya manusia itu, sejenis makhluk yang banyak sekali bantahannya.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 55, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًا', 'وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَىٰ وَيَسْتَغْفِرُوا رَبَّهُمْ إِلَّا أَن تَأْتِيَهُمْ سُنَّةُ الْأَوَّلِينَ أَوْ يَأْتِيَهُمُ الْعَذَابُ قُبُلًا', NULL, 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.', 'Dan tiada yang menghalang manusia daripada beriman, ketika datang petunjuk Al-Quran kepada mereka, dan daripada memohon ampun kepada Tuhan mereka, melainkan (kerana kedegilan mereka dan kerana mereka) menunggu didatangi azab yang memusnahkan yang telah menimpa orang-orang dahulu, atau di datangi azab yang dilihat dan dihadapi.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 56, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًا', 'وَمَا نُرْسِلُ الْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَادِلُ الَّذِينَ كَفَرُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ وَاتَّخَذُوا آيَاتِي وَمَا أُنذِرُوا هُزُوًا', NULL, 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.', 'Dan tidak Kami mengutus Rasul-rasul, melainkan sebagai pemberi berita gembira dan pemberi amaran; dan orang-orang yang kafir membantah dengan alasan yang salah untuk menghapuskan kebenaran dengan bantahan itu; dan mereka jadikan ayat-ayatku, dan amaran yang diberikan kepada mereka sebagai ejek-ejekan.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 57, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًا', 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِآيَاتِ رَبِّهِ فَأَعْرَضَ عَنْهَا وَنَسِيَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى الْهُدَىٰ فَلَن يَهْتَدُوا إِذًا أَبَدًا', NULL, 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.', 'Dan tidaklah ada yang lebih zalim daripada orang yang diberi ingat dengan ayat-ayat Tuhannya, lalu ia berpaling daripadanya dan lupa akan apa yang telah dilakukan oleh kedua tangannya; sesungguhnya (disebabkan bawaan mereka yang buruk itu) Kami jadikan tutupan berlapis-lapis atas hati mereka, menghalang mereka daripada memahaminya, dan (Kami jadikan) pada telinga mereka penyumbat (yang menyebabkan mereka pekak). Dan jika engkau menyeru mereka kepada petunjuk, maka dengan keadaan yang demikian, mereka tidak sekali-kali akan beroleh hidayah petunjuk selama-lamanya.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 58, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًا', 'وَرَبُّكَ الْغَفُورُ ذُو الرَّحْمَةِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا لَعَجَّلَ لَهُمُ الْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا مِن دُونِهِ مَوْئِلًا', NULL, 'And your Lord is the Forgiving, the possessor of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.', 'Dan Tuhanmu Maha Pengampun, lagi melimpah-limpah rahmatnya. Jika Ia mahu menyeksa mereka (di dunia) disebabkan apa yang mereka telah usahakan, tentulah Ia akan menyegerakan azab itu menimpa mereka; (tetapi Ia tidak berbuat demikian) bahkan ditentukan bagi mereka satu masa yang mereka tidak sekali-kali akan dapat sebarang tempat perlindungan, yang ialah daripadanya.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 59, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', 'وَتِلْكَ الْقُرَىٰ أَهْلَكْنَاهُمْ لَمَّا ظَلَمُوا وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', NULL, 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.', 'Dan penduduk negeri-negeri (yang derhaka) itu Kami telah binasakan ketika mereka melakukan kezaliman, dan Kami telah tetapkan satu masa yang tertentu bagi kebinasaan mereka.', FALSE, NULL, NULL, 300, 15, 120, 259, FALSE, 0, NULL),
(18, 60, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا', 'وَإِذْ قَالَ مُوسَىٰ لِفَتَاهُ لَا أَبْرَحُ حَتَّىٰ أَبْلُغَ مَجْمَعَ الْبَحْرَيْنِ أَوْ أَمْضِيَ حُقُبًا', NULL, 'And [mention] when Moses said to his boy [i.e., servant], "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."', 'Dan (ingatkanlah peristiwa) ketika Nabi Musa berkata kepada temannya: “Aku tidak akan berhenti berjalan sehingga aku sampai di tempat pertemuan dua laut itu atau aku berjalan terus bertahun-tahun”.', FALSE, NULL, NULL, 300, 15, 120, 260, FALSE, 0, NULL),
(18, 61, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًا', 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا', NULL, 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.', 'Maka apabila mereka berdua sampai ke tempat pertemuan dua laut itu, lupalah mereka akan hal ikan mereka, lalu ikan itu menggelunsur menempuh jalannya di laut, yang merupakan lorong di bawah tanah.', FALSE, NULL, NULL, 300, 15, 120, 260, FALSE, 0, NULL),
(18, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًا', 'فَلَمَّا جَاوَزَا قَالَ لِفَتَاهُ آتِنَا غَدَاءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًا', NULL, 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."', 'Setelah mereka melampaui (tempat itu), berkatalah Nabi Musa kepada temannya: “Bawalah makan tengah hari kita sebenarnya kita telah mengalami penat lelah dalam perjalanan kita ini”.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 63, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًا', 'قَالَ أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا أَنسَانِيهُ إِلَّا الشَّيْطَانُ أَنْ أَذْكُرَهُ وَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ عَجَبًا', NULL, 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly."', 'Temannya berkata: “Tahukah apa yang telah terjadi ketika kita berehat di batu besar itu? Sebenarnya aku lupakan hal ikan itu; dan tiadalah yang menyebabkan aku lupa daripada menyebutkan halnya kepadamu melainkan Syaitan; dan ikan itu telah menggelunsur menempuh jalannya di laut, dengan cara yang menakjubkan”.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 64, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًا', 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ فَارْتَدَّا عَلَىٰ آثَارِهِمَا قَصَصًا', NULL, '[Moses] said, "That is what we were seeking." So they returned, following their footprints.', 'Nabi Musa berkata: “Itulah yang kita kehendaki”; merekapun balik semula ke situ, dengan menurut jejak mereka.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 65, 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًا', 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَا آتَيْنَاهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَاهُ مِن لَّدُنَّا عِلْمًا', NULL, 'And they found a servant from among Our servants [i.e., al-Khiḍr] to whom We had given mercy from Us and had taught him from Us a [certain] knowledge.', 'Lalu mereka dapati seorang dari hamba-hamba Kami yang telah kami kurniakan kepadanya rahmat dari Kami, dan Kami telah mengajarnya sejenis ilmu; dari sisi Kami.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 66, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', 'قَالَ لَهُ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', NULL, 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"', 'Nabi Musa berkata kepadanya: Bolehkah aku mengikutmu, dengan syarat engkau mengajarku dari apa yang telah diajarkan oleh Allah kepadamu, ilmu yang menjadi petunjuk bagiku?”', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 67, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا', NULL, 'He said, "Indeed, with me you will never be able to have patience.', 'Ia menjawab: “Sesungguhnya engkau (wahai Musa), tidak sekali-kali akan dapat bersabar bersamaku.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 68, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًا', 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِ خُبْرًا', NULL, 'And how can you have patience for what you do not encompass in knowledge?"', 'Dan bagaimana engkau akan sabar terhadap perkara yang engkau tidak mengetahuinya secara meliputi?', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 69, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًا وَلَآ أَعْصِى لَكَ أَمْرًا', 'قَالَ سَتَجِدُنِي إِن شَاءَ اللَّهُ صَابِرًا وَلَا أَعْصِي لَكَ أَمْرًا', NULL, '[Moses] said, "You will find me, if Allāh wills, patient, and I will not disobey you in [any] order."', 'Nabi Musa berkata: “Engkau akan dapati aku, Insyaa Allah: orang yang sabar; dan aku tidak akan membantah sebarang perintahmu”.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 70, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', 'قَالَ فَإِنِ اتَّبَعْتَنِي فَلَا تَسْأَلْنِي عَن شَيْءٍ حَتَّىٰ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', NULL, 'He said, "Then if you follow me, do not ask me about anything until I make to you about it mention [i.e., explanation]."', 'Ia menjawab: “Sekiranya engkau mengikutku, maka janganlah engkau bertanya kepadaku akan sesuatupun sehingga aku ceritakan halnya kepadamu”.', FALSE, NULL, NULL, 301, 15, 120, 260, FALSE, 0, NULL),
(18, 71, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًا', 'فَانطَلَقَا حَتَّىٰ إِذَا رَكِبَا فِي السَّفِينَةِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْئًا إِمْرًا', NULL, 'So they set out, until when they had embarked on the ship, he [i.e., al-Khiḍr] tore it open. [Moses] said, "Have you torn it open to drown its people? You have certainly done a grave thing."', 'Lalu berjalanlah keduanya sehingga apabila mereka naik ke sebuah perahu, ia membocorkannya. Nabi Musa berkata: “Patutkah engkau membocorkannya sedang akibat perbuatan itu menenggelamkan penumpang-penumpangnya? Sesungguhnya engkau telah melakukan satu perkara yang besar”.', FALSE, NULL, NULL, 301, 15, 120, 261, FALSE, 0, NULL),
(18, 72, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا', NULL, '[Al-Khiḍr] said, "Did I not say that with me you would never be able to have patience?"', 'Ia menjawab: “Bukankah aku telah katakan, bahawa engkau tidak sekali-kali akan dapat bersabar bersamaku?”', FALSE, NULL, NULL, 301, 15, 120, 261, FALSE, 0, NULL),
(18, 73, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًا', 'قَالَ لَا تُؤَاخِذْنِي بِمَا نَسِيتُ وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا', NULL, '[Moses] said, "Do not blame me for what I forgot and do not overwhelm me in my matter with difficulty."', 'Nabi Musa berkata: “Janganlah engkau marah akan daku disebabkan aku lupa (akan syaratmu); dan janganlah engkau memberati daku dengan sebarang kesukaran dalam urusanku (menuntut ilmu)”.', FALSE, NULL, NULL, 301, 15, 120, 261, FALSE, 0, NULL),
(18, 74, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةًۢ بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْـًٔا نُّكْرًا', 'فَانطَلَقَا حَتَّىٰ إِذَا لَقِيَا غُلَامًا فَقَتَلَهُ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْئًا نُّكْرًا', NULL, 'So they set out, until when they met a boy, he [i.e., al-Khiḍr] killed him. [Moses] said, "Have you killed a pure soul for other than [having killed] a soul? You have certainly done a deplorable thing."', 'Kemudian keduanya berjalan lagi sehingga apabila mereka bertemu dengan seorang pemuda lalu ia membunuhnya. Nabi Musa berkata “Patutkah engkau membunuh satu jiwa yang bersih, yang tidak berdosa membunuh orang? Sesungguhnya engkau telah melakukan satu perbuatan yang mungkar!”', FALSE, NULL, NULL, 301, 15, 120, 261, FALSE, 0, NULL),
(18, 75, 'قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِيَ صَبْرًا', NULL, '[Al-Khiḍr] said, "Did I not tell you that with me you would never be able to have patience?"', 'Ia menjawab: “Bukankah, aku telah katakan kepadamu, bahawa engkau tidak sekali-kali akan dapat bersabar bersamaku?”', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 76, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًا', 'قَالَ إِن سَأَلْتُكَ عَن شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِن لَّدُنِّي عُذْرًا', NULL, '[Moses] said, "If I should ask you about anything after this, then do not keep me as a companion. You have obtained from me an excuse."', 'Nabi Musa berkata: “Jika aku bertanya kepadamu tentang sebarang perkara sesudah ini, maka janganlah engkau jadikan daku sahabatmu lagi; sesungguhnya engkau telah cukup mendapat alasan-alasan berbuat demikian disebabkan pertanyaan-pertanyaan dan bantahanku”.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 77, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًا', 'فَانطَلَقَا حَتَّىٰ إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُ قَالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا', NULL, 'So they set out, until when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. And they found therein a wall about to collapse, so he [i.e., al-Khiḍr] restored it. [Moses] said, "If you wished, you could have taken for it a payment."', 'Kemudian keduanya berjalan lagi, sehingga apabila mereka sampai kepada penduduk sebuah bandar, mereka meminta makan kepada orang-orang di situ, lalu orang-orang itu enggan menjamu mereka. Kemudian mereka dapati di situ sebuah tembok yang hendak runtuh, lalu ia membinanya. Nabi Musa berkata: “Jika engkau mahu, tentulah engkau berhak mengambil upah mengenainya!”', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 78, 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 'قَالَ هَٰذَا فِرَاقُ بَيْنِي وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', NULL, '[Al-Khiḍr] said, "This is parting between me and you. I will inform you of the interpretation of that about which you could not have patience.', 'Ia menjawab: “Inilah masanya perpisahan antaraku denganmu, aku akan terangkan kepadamu maksud (kejadian-kejadian yang dimusykilkan) yang engkau tidak dapat bersabar mengenainya.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 79, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', 'أَمَّا السَّفِينَةُ فَكَانَتْ لِمَسَاكِينَ يَعْمَلُونَ فِي الْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَاءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', NULL, 'As for the ship, it belonged to poor people working at sea. So I intended to cause defect in it as there was after them a king who seized every [good] ship by force.', 'Adapun perahu itu adalah ia dipunyai oleh orang-orang miskin yang bekerja di laut; oleh itu, aku bocorkan dengan tujuan hendak mencacatkannya, kerana di belakang mereka nanti ada seorang raja yang merampas tiap-tiap sebuah perahu yang tidak cacat.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 80, 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًا وَكُفْرًا', 'وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَا أَن يُرْهِقَهُمَا طُغْيَانًا وَكُفْرًا', NULL, 'And as for the boy, his parents were believers, and we feared that he would overburden them by transgression and disbelief.', 'Adapun pemuda itu, kedua ibu bapanya adalah orang-orang yang beriman, maka kami bimbang bahawa ia akan mendesak mereka melakukan perbuatan yang zalim dan kufur.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 81, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَوٰةً وَأَقْرَبَ رُحْمًا', 'فَأَرَدْنَا أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَاةً وَأَقْرَبَ رُحْمًا', NULL, 'So we intended that their Lord should substitute for them one better than him in purity and nearer to mercy.', 'Oleh itu, kami ingin dan berharap, supaya Tuhan mereka gantikan bagi mereka anak yang lebih baik daripadanya tentang kebersihan jiwa, dan lebih mesra kasih sayangnya.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 82, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', 'وَأَمَّا الْجِدَارُ فَكَانَ لِغُلَامَيْنِ يَتِيمَيْنِ فِي الْمَدِينَةِ وَكَانَ تَحْتَهُ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَالِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَا أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ وَمَا فَعَلْتُهُ عَنْ أَمْرِي ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', NULL, 'And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure for them, and their father had been righteous. So your Lord intended that they reach maturity and extract their treasure, as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of that about which you could not have patience."', 'Adapun tembok itu pula, adalah ia dipunyai oleh dua orang anak yatim di bandar itu; dan di bawahnya ada “harta terpendam” kepunyaan mereka; dan bapa mereka pula adalah orang yang soleh. Maka Tuhanmu menghendaki supaya mereka cukup umur dan dapat mengeluarkan harta mereka yang terpendam itu, sebagai satu rahmat dari Tuhanmu (kepada mereka). Dan (ingatlah) aku tidak melakukannya menurut fikiranku sendiri. Demikianlah penjelasan tentang maksud dan tujuan perkara-perkara yang engkau tidak dapat bersabar mengenainya”.', FALSE, NULL, NULL, 302, 16, 121, 261, FALSE, 0, NULL),
(18, 83, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', 'وَيَسْأَلُونَكَ عَن ذِي الْقَرْنَيْنِ قُلْ سَأَتْلُو عَلَيْكُم مِّنْهُ ذِكْرًا', NULL, 'And they ask you, [O Muḥammad], about Dhul-Qarnayn. Say, "I will recite to you about him a report."', 'Dan mereka bertanya kepadamu (wahai Muhammad), mengenai Zulkarnain. Katakanlah: “Aku akan bacakan kepada kamu (wahyu dari Allah yang menerangkan) sedikit tentang perihalnya”:', FALSE, NULL, NULL, 302, 16, 121, 262, FALSE, 0, NULL),
(18, 84, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍ سَبَبًا', 'إِنَّا مَكَّنَّا لَهُ فِي الْأَرْضِ وَآتَيْنَاهُ مِن كُلِّ شَيْءٍ سَبَبًا', NULL, 'Indeed, We established him upon the earth, and We gave him from everything a way [i.e., means].', 'Sesungguhnya Kami telah memberikan kepadanya kekuasaan memerintah di bumi, dan Kami beri kepadanya jalan bagi menjayakan tiap-tiap sesuatu yang diperlukannya.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 85, 'فَأَتْبَعَ سَبَبًا', 'فَأَتْبَعَ سَبَبًا', NULL, 'So he followed a way', 'Lalu ia menurut jalan (yang menyampaikan maksudnya).', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 86, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًا', 'حَتَّىٰ إِذَا بَلَغَ مَغْرِبَ الشَّمْسِ وَجَدَهَا تَغْرُبُ فِي عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا قُلْنَا يَا ذَا الْقَرْنَيْنِ إِمَّا أَن تُعَذِّبَ وَإِمَّا أَن تَتَّخِذَ فِيهِمْ حُسْنًا', NULL, 'Until, when he reached the setting of the sun [i.e., the west], he found it [as if] setting in a body of dark water, and he found near it a people. We [i.e., Allāh] said, "O Dhul-Qarnayn, either you punish [them] or else adopt among them [a way of] goodness."', 'Sehingga apabila ia sampai ke daerah matahari terbenam, ia mendapatinya terbenam di sebuah matair yang hitam berlumpur, dan ia dapati di sisinya satu kaum (yang kufur ingkar). Kami berfirman (dengan mengilhamkan kepadanya): “Wahai Zulkarnain! Pilihlah sama ada engkau hendak menyeksa mereka atau engkau bertindak secara baik terhadap mereka”.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 87, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًا نُّكْرًا', 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِ فَيُعَذِّبُهُ عَذَابًا نُّكْرًا', NULL, 'He said, "As for one who wrongs, we will punish him. Then he will be returned to his Lord, and He will punish him with a terrible punishment [i.e., Hellfire].', 'Ia berkata: “Adapun orang yang melakukan kezaliman (kufur derhaka), maka kami akan menyeksanya; kemudian ia akan dikembalikan kepada Tuhannya, lalu diazabkannya dengan azab seksa yang seburuk-buruknya.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 88, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًا', 'وَأَمَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَلَهُ جَزَاءً الْحُسْنَىٰ وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا', NULL, 'But as for one who believes and does righteousness, he will have a reward of the best [i.e., Paradise], and we [i.e., Dhul-Qarnayn] will speak to him from our command with ease."', 'Adapun orang yang beriman serta beramal soleh, maka baginya balasan yang sebaik-baiknya; dan kami akan perintahkan kepadanya perintah-perintah kami yang tidak memberati”.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 89, 'ثُمَّ أَتْبَعَ سَبَبًا', 'ثُمَّ أَتْبَعَ سَبَبًا', NULL, 'Then he followed a way', 'Kemudian ia berpatah balik menurut jalan yang lain.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 90, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', 'حَتَّىٰ إِذَا بَلَغَ مَطْلِعَ الشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', NULL, 'Until, when he came to the rising of the sun [i.e., the east], he found it rising on a people for whom We had not made against it any shield.', 'Sehingga apabila ia sampai di daerah matahari terbit, ia mendapatinya terbit kepada suatu kaum yang kami tidak menjadikan bagi mereka sebarang perlindungan daripadanya.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 91, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', NULL, 'Thus. And We had encompassed [all] that he had in knowledge.', 'Demikianlah halnya; dan sesungguhnya Kami mengetahui secara meliputi akan segala yang ada padanya.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 92, 'ثُمَّ أَتْبَعَ سَبَبًا', 'ثُمَّ أَتْبَعَ سَبَبًا', NULL, 'Then he followed a way', 'kemudian ia berpatah balik menurut jalan yang lain.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 93, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', 'حَتَّىٰ إِذَا بَلَغَ بَيْنَ السَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', NULL, 'Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech.', 'Sehingga apabila ia sampai di antara dua gunung, ia dapati di sisinya satu kaum yang hampir-hampir mereka tidak dapat memahami perkataan.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 94, 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', 'قَالُوا يَا ذَا الْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', NULL, 'They said, "O Dhul-Qarnayn, indeed Gog and Magog are [great] corrupters in the land. So may we assign for you an expenditure that you might make between us and them a barrier?"', 'Mereka berkata: “wahai Zulkarnain, sesungguhnya kaum Yakjuj dan Makjuj sentiasa melakukan kerosakan di bumi; oleh itu, setujukah kiranya kami menentukan sejumlah bayaran kepadamu (dari hasil pendapatan kami) dengan syarat engkau membina sebuah tembok di antara kami dengan mereka?”', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 95, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 'قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ فَأَعِينُونِي بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', NULL, 'He said, "That in which my Lord has established me is better [than what you offer], but assist me with strength [i.e., manpower]; I will make between you and them a dam.', 'Dia menjawab: “(kekuasaan dan kekayaan) yang Tuhanku jadikan daku menguasainya, lebih baik (dari bayaran kamu); oleh itu bantulah daku dengan tenaga (kamu beramai-ramai) aku akan bina antara kamu dengan mereka sebuah tembok penutup yang kukuh.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 96, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًا', 'آتُونِي زُبَرَ الْحَدِيدِ حَتَّىٰ إِذَا سَاوَىٰ بَيْنَ الصَّدَفَيْنِ قَالَ انفُخُوا حَتَّىٰ إِذَا جَعَلَهُ نَارًا قَالَ آتُونِي أُفْرِغْ عَلَيْهِ قِطْرًا', NULL, 'Bring me bars of iron" - until, when he had leveled [them] between the two mountain walls, he said, "Blow [with bellows]," until when he had made it [like] fire, he said, "Bring me, that I may pour over it molten copper."', 'Bawalah kepadaku ketul-ketul besi”; sehingga apabila ia terkumpul separas tingginya menutup lapangan antara dua gunung itu, ddia pun perintahkan mereka membakarnya dengan berkata: “Tiuplah dengan alat-alat kamu” sehingga apabila ia menjadikannya merah menyala seperti api, berkatalah dia: “Bawalah tembaga cair supaya aku tuangkan atasnya”.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 97, 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًا', 'فَمَا اسْطَاعُوا أَن يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا', NULL, 'So they [i.e., Gog and Magog] were unable to pass over it, nor were they able [to effect] in it any penetration.', 'Maka mereka tidak dapat memanjat tembok itu, dan mereka juga tidak dapat menebuknya.', FALSE, NULL, NULL, 303, 16, 121, 262, FALSE, 0, NULL),
(18, 98, 'قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّى فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ وَكَانَ وَعْدُ رَبِّى حَقًّا', 'قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّي فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ وَكَانَ وَعْدُ رَبِّي حَقًّا', NULL, '[Dhul-Qarnayn] said, "This is a mercy from my Lord; but when the promise of my Lord comes [i.e., approaches], He will make it level, and ever is the promise of my Lord true."', '(Setelah itu) berkatalah Zulkarnain: “Ini ialah suatu rahmat dari Tuhanku; dalam pada itu, apabila sampai janji Tuhanku, Dia akan menjadikan tembok itu hancur lebur, dan adalah janji Tuhanku itu benar”.', FALSE, NULL, NULL, 304, 16, 121, 262, FALSE, 0, NULL),
(18, 99, 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِى بَعْضٍ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًا', 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِي بَعْضٍ وَنُفِخَ فِي الصُّورِ فَجَمَعْنَاهُمْ جَمْعًا', NULL, 'And We will leave them that day surging over each other, and [then] the Horn will be blown, and We will assemble them in [one] assembly.', 'Dan Kami biarkan mereka pada hari itu (keluar beramai-ramai) bercampur-baur antara satu dengan yang lain; dan (kemudiannya) akan ditiup sangkakala, lalu Kami himpunkan makhluk-makhluk seluruhnya di Padang Mahsyar.', FALSE, NULL, NULL, 304, 16, 122, 262, FALSE, 0, NULL),
(18, 100, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَٰفِرِينَ عَرْضًا', 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَافِرِينَ عَرْضًا', NULL, 'And We will present Hell that Day to the disbelievers, on display -', 'Dan Kami perlihatkan neraka Jahannam, pada hari itu kepada orang-orang kafir, dengan pendedahan yang jelas nyata;', FALSE, NULL, NULL, 304, 16, 122, 262, FALSE, 0, NULL),
(18, 101, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', 'الَّذِينَ كَانَتْ أَعْيُنُهُمْ فِي غِطَاءٍ عَن ذِكْرِي وَكَانُوا لَا يَسْتَطِيعُونَ سَمْعًا', NULL, 'Those whose eyes had been within a cover [removed] from My remembrance, and they were not able to hear.', '(Iaitu) orang-orang yang matanya telah tertutup daripada melihat tanda-tanda yang membawa kepada mengingatiKu, dan mereka pula tidak dapat mendengar sama sekali.', FALSE, NULL, NULL, 304, 16, 122, 262, FALSE, 0, NULL),
(18, 102, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًا', 'أَفَحَسِبَ الَّذِينَ كَفَرُوا أَن يَتَّخِذُوا عِبَادِي مِن دُونِي أَوْلِيَاءَ إِنَّا أَعْتَدْنَا جَهَنَّمَ لِلْكَافِرِينَ نُزُلًا', NULL, 'Then do those who disbelieve think that they can take My servants instead of Me as allies? Indeed, We have prepared Hell for the disbelievers as a lodging.', 'Maka adakah orang-orang kafir menyangka bahawa mereka mengambil hamba-hambaKu sebagai makhluk-makhluk yang disembah, selain daripadaKu, dapat menolong mereka? Sesungguhnya Kami telah sediakan neraka Jahannam bagi orang-orang kafir itu sebagai tempat tetamu.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 103, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', 'قُلْ هَلْ نُنَبِّئُكُم بِالْأَخْسَرِينَ أَعْمَالًا', NULL, 'Say, [O Muḥammad], "Shall we [believers] inform you of the greatest losers as to [their] deeds?', 'Katakanlah (wahai Muhammad): “Mahukah Kami khabarkan kepada kamu akan orang-orang yang paling rugi amal-amal perbuatannya?', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 104, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', 'الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', NULL, '[They are] those whose effort is lost in worldly life, while they think that they are doing well in work."', '(Iaitu) orang-orang yang telah sia-sia amal usahanya dalam kehidupan dunia ini, sedang mereka menyangka bahawa mereka sentiasa betul dan baik pada apa sahaja yang mereka lakukan”.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 105, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًا', 'أُولَٰئِكَ الَّذِينَ كَفَرُوا بِآيَاتِ رَبِّهِمْ وَلِقَائِهِ فَحَبِطَتْ أَعْمَالُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا', NULL, 'Those are the ones who disbelieve in the verses of their Lord and in [their] meeting Him, so their deeds have become worthless; and We will not assign to them on the Day of Resurrection any weight [i.e., importance].', 'Merekalah orang-orang yang kufur ingkar akan ayat-ayat Tuhan mereka dan akan pertemuan denganNya; oleh itu gugurlah amal-amal mereka; maka akibatya Kami tidak akan memberi sebarang timbangan untuk menilai amal mereka, pada hari kiamat kelak.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 106, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', 'ذَٰلِكَ جَزَاؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا وَاتَّخَذُوا آيَاتِي وَرُسُلِي هُزُوًا', NULL, 'That is their recompense - Hell - for what they denied and [because] they took My signs and My messengers in ridicule.', '(Mereka yang bersifat) demikian, balasannya neraka Jahannam, disebabkan mereka kufur ingkar, dan mereka pula menjadikan ayat-ayatKu dan Rasul-rasulKu sebagai ejek-ejekan.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 107, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا', NULL, 'Indeed, those who have believed and done righteous deeds - they will have the Gardens of Paradise as a lodging,', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, disediakan bagi mereka Syurga-syurga Firdaus, sebagai tempat tetamu (yang serba mewah).', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 108, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', 'خَالِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', NULL, 'Wherein they abide eternally. They will not desire from it any transfer.', 'Mereka kekal di dalamnya, (dan) tidak ingin berpindah daripadanya.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 109, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًا', 'قُل لَّوْ كَانَ الْبَحْرُ مِدَادًا لِّكَلِمَاتِ رَبِّي لَنَفِدَ الْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَاتُ رَبِّي وَلَوْ جِئْنَا بِمِثْلِهِ مَدَدًا', NULL, 'Say, "If the sea were ink for [writing] the words of my Lord, the sea would be exhausted before the words of my Lord were exhausted, even if We brought the like of it in [continual] supplement."', 'Katakanlah (wahai Muhammad): “Kalaulah semua jenis lautan menjadi tinta untuk menulis Kalimah-kalimah Tuhanku, sudah tentu akan habis kering lautan itu sebelum habis Kalimah-kalimah Tuhanku, walaupun Kami tambahi lagi dengan lautan yang sebanding dengannya, sebagai bantuan”.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(18, 110, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًا صَٰلِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', 'قُلْ إِنَّمَا أَنَا بَشَرٌ مِّثْلُكُمْ يُوحَىٰ إِلَيَّ أَنَّمَا إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَمَن كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا', NULL, 'Say, "I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone."', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku hanyalah seorang manusia seperti kamu, diwahyukan kepadaku bahawa Tuhan kamu hanyalah Tuhan Yang Satu; Oleh itu, sesiapa yang percaya dan berharap akan pertemuan dengan Tuhannya, hendaklah ia mengerjakan amal yang soleh dan janganlah ia mempersekutukan sesiapapun dalam ibadatnya kepada Tuhannya”.', FALSE, NULL, NULL, 304, 16, 122, 263, FALSE, 0, NULL),
(19, 1, 'كٓهيعٓصٓ', 'كهيعص', NULL, 'Kāf, Hā, Yā, ʿAyn, Ṣād.', 'Kaaf, Haa, Yaa, Ain, Saad', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 1, NULL),
(19, 2, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', 'ذكر رحمت ربك عبده زكريا', NULL, '[This is] a mention of the mercy of your Lord to His servant Zechariah', '(Ini ialah) perihal limpahan rahmat Tuhanmu (wahai Muhammad), kepada hambaNya Zakaria.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 5, NULL),
(19, 3, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا', 'اذ نادى ربه نداء خفيا', NULL, 'When he called to his Lord a private call [i.e., supplication].', '(Ingatkanlah peristiwa) ketika Nabi Zakaria berdoa kepada tuhannya dengan doa permohonan secara perlahan.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 5, NULL),
(19, 4, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا', 'قال رب اني وهن العظم مني واشتعل الراس شيبا ولم اكن بدعائك رب شقيا', NULL, 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy [i.e., disappointed].', 'Ia merayu dengan berkata: Wahai Tuhanku! Sesungguhnya telah lemahlah tulang -tulangku, dan telah putih melepaklah uban kepalaku; dan aku - wahai Tuhanku - tidak pernah merasa hampa dengan doa permohonanku kepadaMu.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 14, NULL),
(19, 5, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا', 'واني خفت الموالي من ورائي وكانت امراتي عاقرا فهب لي من لدنك وليا', NULL, 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir', 'Dan sesungguhnya aku merasa bimbang akan kecuaian kaum kerabatku menyempurnakan tugas-tugas ugama sepeninggalanku; dan isteriku pula adalah seorang yang mandul; oleh itu, kurniakanlah daku dari sisiMu seorang anak lelaki.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 13, NULL),
(19, 6, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ ۖ وَٱجْعَلْهُ رَبِّ رَضِيًّا', 'يرثني ويرث من ال يعقوب واجعله رب رضيا', NULL, 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."', 'Yang layak mewarisi daku, juga mewarisi keluarga Nabi Yaakub; dan jadikanlah dia - wahai Tuhanku seorang yang diredhai serta disukai”.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 8, NULL),
(19, 7, 'يَـٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا', 'يا زكريا انا نبشرك بغلام اسمه يحيى لم نجعل له من قبل سميا', NULL, '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."', '(Nabi Zakaria diseru setelah dikabulkan doanya): “Wahai Zakaria! Sesungguhnya Kami memberikan khabar yang mengembirakanmu dengan mengurniakan seorang anak lelaki bernama Yahya, yang kami tidak pernah jadikan sebelum itu, seorangpun yang senama dengannya”.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 12, NULL),
(19, 8, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا', 'قال رب انى يكون لي غلام وكانت امراتي عاقرا وقد بلغت من الكبر عتيا', NULL, 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"', 'Nabi Zakaria bertanya: “Wahai Tuhanku! Bagaimanakah caranya aku akan beroleh seorang anak, sedang isteriku adalah seorang yang mandul dan aku sendiri pula telah sampai had umur yang setua-tuanya?”', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 14, NULL),
(19, 9, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا', 'قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيئا', NULL, '[An angel] said, "Thus [it will be]; your Lord says, ''It is easy for Me, for I created you before, while you were nothing.''"', 'Penyeru itu menjawab: Demikian keadaannya - janganlah dihairankan; Tuhanmu berfirman; “Hal itu mudah bagiKu kerana sesungguhnya Aku telah menciptakanmu dahulu, sedang engkau pada masa itu belum ada sebarang apapun.”', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 14, NULL),
(19, 10, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً ۚ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَ لَيَالٍ سَوِيًّا', 'قال رب اجعل لي اية قال ايتك الا تكلم الناس ثلاث ليال سويا', NULL, '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."', 'Nabi Zakaria merayu lagi: “Wahai Tuhanku! Jadikanlah satu tanda bagiku (yang menunjukkan isteriku mengandung)”, Allah Taala berfirman: “Tandamu itu ialah engkau tidak akan dapat berkata-kata dengan orang ramai selama tiga malam, sedang engkau dalam keadaan sihat”.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 13, NULL),
(19, 11, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا', 'فخرج على قومه من المحراب فاوحى اليهم ان سبحوا بكرة وعشيا', NULL, 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allāh] in the morning and afternoon.', 'Maka dia pun keluar mendapatkan kaumnya dari Mihrab (tempat sembahyangnya), lalu ia memberi isyarat kepada mereka: “Hendaklah kamu bertasbih (mengerjakan ibadat kepada Allah) pagi dan petang”.', FALSE, NULL, NULL, 305, 16, 122, 264, FALSE, 11, NULL),
(19, 12, 'يَـٰيَحْيَىٰ خُذِ ٱلْكِتَـٰبَ بِقُوَّةٍ ۖ وَءَاتَيْنَـٰهُ ٱلْحُكْمَ صَبِيًّا', 'يا يحيى خذ الكتاب بقوة واتيناه الحكم صبيا', NULL, '[Allāh said], "O John, take the Scripture [i.e., adhere to it] with determination." And We gave him judgement [while yet] a boy', '“Wahai Yahya, terimalah Kitab itu (serta amalkanlah) dengan bersungguh-sungguh! Dan Kami berikan kepadanya Hikmat kebijaksanaan semasa ia masih kanak-kanak.', FALSE, NULL, NULL, 306, 16, 122, 264, FALSE, 7, NULL),
(19, 13, 'وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً ۖ وَكَانَ تَقِيًّا', 'وحنانا من لدنا وزكاة وكان تقيا', NULL, 'And affection from Us and purity, and he was fearing of Allāh', 'dan (Kami mengurniakannya) rahmat dari sisi Kami, serta kelebihan yang kembang manfaatnya; dan ia seorang yang bertaqwa.', FALSE, NULL, NULL, 306, 16, 122, 264, FALSE, 6, NULL),
(19, 14, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا', 'وبرا بوالديه ولم يكن جبارا عصيا', NULL, 'And dutiful to his parents, and he was not a disobedient tyrant.', 'Dan ia taat serta berbuat baik kepada ibu bapanya, dan ia pula tidak sombong angkuh atau derhaka.', FALSE, NULL, NULL, 306, 16, 122, 264, FALSE, 6, NULL),
(19, 15, 'وَسَلَـٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا', 'وسلام عليه يوم ولد ويوم يموت ويوم يبعث حيا', NULL, 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.', 'Dan (Kami limpahkan) kepadanya selamat sejahtera pada hari ia diperanakkan, dan pada hari ia mati, serta pada hari ia dibangkitkan hidup semula (pada hari kiamat).', FALSE, NULL, NULL, 306, 16, 122, 264, FALSE, 9, NULL),
(19, 16, 'وَٱذْكُرْ فِى ٱلْكِتَـٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا', 'واذكر في الكتاب مريم اذ انتبذت من اهلها مكانا شرقيا', NULL, 'And mention, [O Muḥammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.', 'Dan bacakanlah (wahai Muhammad) di dalam Kitab Al-Quran ini perihal Maryam, ketika dia memencilkan diri dari keluarganya di sebuah tempat sebelah timur.', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 10, NULL),
(19, 17, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا', 'فاتخذت من دونهم حجابا فارسلنا اليها روحنا فتمثل لها بشرا سويا', NULL, 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel [i.e., Gabriel], and he represented himself to her as a well-proportioned man.', 'Kemudian Maryam membuat dinding untuk melindungi dirinya dari mereka maka Kami hantarkan kepadanya: Roh dari kami lalu ia menyamar diri kepadanya sebagai seorang lelaki yang sempurna bentuk kejadiannya.', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 11, NULL),
(19, 18, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَـٰنِ مِنكَ إِن كُنتَ تَقِيًّا', 'قالت اني اعوذ بالرحمن منك ان كنت تقيا', NULL, 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allāh."', 'Maryam berkata: Sesungguhnya aku berlindung kepada (Allah) Ar-Rahman daripada (gangguan) mu kalaulah engkau seorang yang bertaqwa.', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 8, NULL),
(19, 19, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَـٰمًا زَكِيًّا', 'قال انما انا رسول ربك لاهب لك غلاما زكيا', NULL, 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy [i.e., son]."', 'Ia berkata: “Sesungguhnya aku pesuruh Tuhanmu, untuk menyebabkanmu dikurniakan seorang anak yang suci”.', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 9, NULL),
(19, 20, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا', 'قالت انى يكون لي غلام ولم يمسسني بشر ولم اك بغيا', NULL, 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"', 'Maryam bertanya (dengan cemas): Bagaimanakah aku akan beroleh seorang anak lelaki, padahal aku tidak pernah disentuh oleh seorang lelaki pun, dan aku pula bukan perempuan jahat?”', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 11, NULL),
(19, 21, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا', 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٌ وَلِنَجْعَلَهُ آيَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا', NULL, 'He said, "Thus [it will be]; your Lord says, ''It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.''"', 'Ia menjawab: “Demikianlah keadaannya tak usahlah dihairankan; Tuhanmu berfirman: Hal itu mudah bagiKu; dan Kami hendak menjadikan pemberian anak itu sebagai satu tanda (yang membuktikan kekuasaan Kami) untuk umat manusia dan sebagai satu rahmat dari Kami; dan hal itu adalah satu perkara yang telah ditetapkan berlakunya.', FALSE, NULL, NULL, 306, 16, 122, 265, FALSE, 0, NULL),
(19, 22, 'فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا', 'فَحَمَلَتْهُ فَانتَبَذَتْ بِهِ مَكَانًا قَصِيًّا', NULL, 'So she conceived him, and she withdrew with him to a remote place.', 'Maka Maryam hamillah mengandungnya, lalu ia memencilkan diri dengan kandungannya itu ke sebuah tempat yang jauh.', FALSE, NULL, NULL, 306, 16, 123, 265, FALSE, 0, NULL),
(19, 23, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', 'فَأَجَاءَهَا الْمَخَاضُ إِلَىٰ جِذْعِ النَّخْلَةِ قَالَتْ يَا لَيْتَنِي مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', NULL, 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."', '(Ketika ia hendak bersalin) maka sakit beranak itu memaksanya (pergi bersandar) ke pangkal sebatang pohon tamar (kurma); ia berkata alangkah baiknya kalau aku mati sebelum ini dan menjadilah aku sesuatu yang dilupakan orang dan tidak dikenang-kenang!', FALSE, NULL, NULL, 306, 16, 123, 265, FALSE, 0, NULL),
(19, 24, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', 'فَنَادَاهَا مِن تَحْتِهَا أَلَّا تَحْزَنِي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', NULL, 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.', 'Lalu ia diseru dari sebelah bawahnya: “Janganlah engkau berdukacita (wahai Maryam), sesungguhnya Tuhanmu telah menjadikan di bawahmu sebatang anak sungai.', FALSE, NULL, NULL, 306, 16, 123, 265, FALSE, 0, NULL),
(19, 25, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', 'وَهُزِّي إِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسَاقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', NULL, 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.', 'Dan gegarlah ke arahmu batang pohon tamar itu, supaya gugur kepadamu buah tamar yang masak.', FALSE, NULL, NULL, 306, 16, 123, 265, FALSE, 0, NULL),
(19, 26, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا', 'فَكُلِي وَاشْرَبِي وَقَرِّي عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ الْبَشَرِ أَحَدًا فَقُولِي إِنِّي نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ الْيَوْمَ إِنسِيًّا', NULL, 'So eat and drink and be contented. And if you see from among humanity anyone, say, ''Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.''"', '“Maka makanlah dan minumlah serta bertenanglah hati dari segala yang merunsingkan. Kemudian kalau engkau melihat seseorang manusia, maka katakanlah: Sesungguhnya aku bernazar diam membisu kerana (Allah) Ar-Rahman; (setelah aku menyatakan yang demikian) maka aku tidak akan berkata-kata kepada sesiapapun dari kalangan manusia pada hari ini”.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 27, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا', 'فَأَتَتْ بِهِ قَوْمَهَا تَحْمِلُهُ قَالُوا يَا مَرْيَمُ لَقَدْ جِئْتِ شَيْئًا فَرِيًّا', NULL, 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.', 'Kemudian baliklah ia kepada kaumnya dengan mendokong anaknya mereka pun menempelaknya dengan berkata: Wahai Maryam! Sesungguhnya engkau telah melakukan suatu perkara yang besar salahnya!', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 28, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', 'يَا أُخْتَ هَارُونَ مَا كَانَ أَبُوكِ امْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', NULL, 'O sister [i.e., descendant] of Aaron, your father was not a man of evil, nor was your mother unchaste."', '“Wahai saudara perempuan Harun, bapamu bukanlah seorang yang buruk akhlaknya, dan ibumu pula bukanlah seorang perempuan jahat!”', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 29, 'فَأَشَارَتْ إِلَيْهِ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا', 'فَأَشَارَتْ إِلَيْهِ قَالُوا كَيْفَ نُكَلِّمُ مَن كَانَ فِي الْمَهْدِ صَبِيًّا', NULL, 'So she pointed to him. They said, "How can we speak to one who is in the cradle a child?"', 'Maka Maryam segera menunjuk kepada anaknya. Mereka berkata (dengan hairannya): “Bagaimana kami boleh berkata-kata dengan seorang yang masih kanak-kanak dalam buaian?”', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 30, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّا', 'قَالَ إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا', NULL, '[Jesus] said, "Indeed, I am the servant of Allāh. He has given me the Scripture and made me a prophet.', 'Ia menjawab: “Sesungguhnya aku ini hamba Allah; Ia telah memberikan kepadaku Kitab (Injil), dan Ia telah menjadikan daku seorang Nabi.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 31, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا', 'وَجَعَلَنِي مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَانِي بِالصَّلَاةِ وَالزَّكَاةِ مَا دُمْتُ حَيًّا', NULL, 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakāh as long as I remain alive', 'Dan Ia menjadikan daku seorang yang berkat di mana sahaja aku berada, dan diperintahkan daku mengerjakan sembahyang dan memberi zakat selagi aku hidup.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 32, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا', 'وَبَرًّا بِوَالِدَتِي وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا', NULL, 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.', '“Serta (diperintahkan daku) taat dan berbuat baik kepada ibuku, dan Ia tidak menjadikan daku seorang yang sombong takbur atau derhaka.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 33, 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', 'وَالسَّلَامُ عَلَيَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', NULL, 'And peace is on me the day I was born and the day I will die and the day I am raised alive."', 'Dan segala keselamatan serta kesejahteraan dilimpahkan kepadaku pada hari aku diperanakkan dan pada hari aku mati, serta pada hari aku dibangkitkan hidup semula (pada hari kiamat)”.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 34, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', 'ذَٰلِكَ عِيسَى ابْنُ مَرْيَمَ قَوْلَ الْحَقِّ الَّذِي فِيهِ يَمْتَرُونَ', NULL, 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.', 'Yang demikian sifat-sifatnya itulah Isa Ibni Maryam. Keterangan yang tersebut ialah keterangan yang sebenar-benarnya, yang mereka ragu-ragu dan berselisihan padanya.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 35, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَٰنَهُۥٓ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَانَهُ إِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ', NULL, 'It is not [befitting] for Allāh to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.', 'Tiadalah layak bagi Allah mempunyai anak. Maha Sucilah Ia. Apabila menetapkan jadinya sesuatu perkara, maka hanyalah Ia berfirman kepadanya: “Jadilah engkau”, lalu menjadilah ia.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 36, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'وَإِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ', NULL, '[Jesus said], "And indeed, Allāh is my Lord and your Lord, so worship Him. That is a straight path."', 'Dan sesungguhnya Allah ialah Tuhanku dan Tuhan kamu maka sembahlah kamu akan Dia inilah jalan yang betul - lurus”.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 37, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', 'فَاخْتَلَفَ الْأَحْزَابُ مِن بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', NULL, 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.', 'Kemudian, golongan-golongan (dari kaumnya) itu berselisihan sesama sendiri. Maka kecelakaanlah bagi orang-orang kafir (yang berselisihan) itu, dari apa yang disaksikan pada hari yang besar huru-haranya.', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 38, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍ مُّبِينٍ', 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ الظَّالِمُونَ الْيَوْمَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.', 'Sungguh jelas pendengaran dan penglihatan mereka yang kafir itu semasa mereka datang mengadap Kami pada hari akhirat. Tetapi orang-orang yang zalim (dengan perbuatan kufur dan maksiat) pada masa di dunia ini, berada dalam kesesatan yang nyata', FALSE, NULL, NULL, 307, 16, 123, 265, FALSE, 0, NULL),
(19, 39, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', 'وَأَنذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الْأَمْرُ وَهُمْ فِي غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', NULL, 'And warn them, [O Muḥammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.', 'Dan berilah amaran (wahai Muhammad) kepada umat manusia seluruhnya tentang hari penyesalan iaitu hari diselesaikan perbicaraan perkara masing-masing pada masa mereka (yang ingkar) di dunia ini berada dalam kelalaian serta mereka pula tidak mahu beriman.', FALSE, NULL, NULL, 308, 16, 123, 265, FALSE, 0, NULL),
(19, 40, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 'إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', NULL, 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.', 'Sesungguhnya Kamilah yang mewarisi bumi dan segala makhluk yang ada di atasnya; dan kepada Kamilah mereka akan dikembalikan.', FALSE, NULL, NULL, 308, 16, 123, 265, FALSE, 0, NULL),
(19, 41, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', 'وَاذْكُرْ فِي الْكِتَابِ إِبْرَاهِيمَ إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا', NULL, 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.', 'Dan bacakanlah (wahai Muhammad) di dalam Kitab (Al-Quran) ini perihal Nabi Ibrahim; sesungguhnya adalah ia seorang yang amat benar, lagi menjadi Nabi.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 42, 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا', 'إِذْ قَالَ لِأَبِيهِ يَا أَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِي عَنكَ شَيْئًا', NULL, '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?', 'Ketika ia berkata kepada bapanya: “Wahai ayahku, mengapa ayah menyembah benda yang tidak mendengar dan tidak melihat serta tidak dapat menolongmu sedikitpun?', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 43, 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا', 'يَا أَبَتِ إِنِّي قَدْ جَاءَنِي مِنَ الْعِلْمِ مَا لَمْ يَأْتِكَ فَاتَّبِعْنِي أَهْدِكَ صِرَاطًا سَوِيًّا', NULL, 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.', '“Wahai ayahku, sesungguhnya telah datang kepadaku dari ilmu pengetahuan yang tidak pernah datang kepadamu oleh itu ikutlah daku; aku akan memimpinmu ke jalan yang betul.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 44, 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا', 'يَا أَبَتِ لَا تَعْبُدِ الشَّيْطَانَ إِنَّ الشَّيْطَانَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا', NULL, 'O my father, do not worship [i.e., obey] Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.', '“Wahai ayahku, janganlah ayah menyembah Syaitan, sesungguhnya Syaitan itu adalah menderhaka kepada Allah yang melimpah-limpah rahmatNya.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 45, 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّا', 'يَا أَبَتِ إِنِّي أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ الرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَانِ وَلِيًّا', NULL, 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."', '“Wahai ayahku, sesungguhnya aku bimbang bahawa ayah akan kena azab dari (Allah) Ar-Rahman disebabkan ayah menyembah yang lainnya; maka dengan sebab itu akan menjadilah ayah rakan bagi Syaitan di dalam neraka”.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 46, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَٱهْجُرْنِى مَلِيًّا', 'قَالَ أَرَاغِبٌ أَنتَ عَنْ آلِهَتِي يَا إِبْرَاهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَاهْجُرْنِي مَلِيًّا', NULL, '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."', '(Bapanya) menjawab: “Patutkah engkau bencikan tuhan-tuhanku, wahai Ibrahim? Demi sesungguhnya jika engkau tidak berhenti daripada menyeru dan menasihati daku sudah tentu aku akan meluntarmu dengan batu; dan (ingatlah lebih baik) engkau tinggalkan daku sepanjang masa”.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 47, 'قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ إِنَّهُۥ كَانَ بِى حَفِيًّا', 'قَالَ سَلَامٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّي إِنَّهُ كَانَ بِي حَفِيًّا', NULL, '[Abraham] said, "Peace [i.e., safety] will be upon you. I will ask forgiveness for you of my Lord. Indeed, He is ever gracious to me.', 'Nabi Ibrahim berkata: “Selamat tinggallah ayah; aku akan memohon kepada Tuhanku mengampuni dosamu; sesungguhnya Ia sentiasa melimpahkan kemurahan ihsanNya kepadaku.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 48, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا', 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ اللَّهِ وَأَدْعُو رَبِّي عَسَىٰ أَلَّا أَكُونَ بِدُعَاءِ رَبِّي شَقِيًّا', NULL, 'And I will leave you and those you invoke other than Allāh and will invoke my Lord. I expect that I will not be in invocation to my Lord unhappy [i.e., disappointed]."', 'Dan aku akan membawa diri meninggalkan kamu semua serta apa yang kamu sembah yang lain dari Allah; dan aku akan beribadat kepada Tuhanku dengan ikhlas; mudah-mudahan aku dengan ibadatku kepada Tuhanku itu tidak menjadi hampa (dan derhaka seperti kamu)”.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 49, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا', 'فَلَمَّا اعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ اللَّهِ وَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا', NULL, 'So when he had left them and those they worshipped other than Allāh, We gave him Isaac and Jacob, and each [of them] We made a prophet.', 'Maka apabila ia berhijrah meninggalkan mereka dan apa yang mereka sembah yang lain dari Allah kami kurniakan kepadanya: Ishak (anaknya), dan Yaakub (cucunya); dan kedua-duanya Kami jadikan berpangkat Nabi.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 50, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', NULL, 'And We gave them of Our mercy, and We made for them a mention [i.e., reputation] of high honor.', 'Dan Kami kurniakan kepada mereka dari rahmat Kami, dan Kami jadikan bagi mereka sebutan dan pujian yang tinggi dalam kalangan umat manusia.', FALSE, NULL, NULL, 308, 16, 123, 266, FALSE, 0, NULL),
(19, 51, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', 'وَاذْكُرْ فِي الْكِتَابِ مُوسَىٰ إِنَّهُ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', NULL, 'And mention in the Book, Moses. Indeed, he was chosen, and he was a messenger and a prophet.', 'Dan bacakanlah (wahai Muhammad) di dalam Kitab (Al-Quran) ini perihal Nabi Musa; sesungguhnya ia adalah orang pilihan, dan adalah ia seorang Rasul, lagi Nabi.', FALSE, NULL, NULL, 308, 16, 123, 267, FALSE, 0, NULL),
(19, 52, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّا', 'وَنَادَيْنَاهُ مِن جَانِبِ الطُّورِ الْأَيْمَنِ وَقَرَّبْنَاهُ نَجِيًّا', NULL, 'And We called him from the side of the mount at [his] right and brought him near, confiding [to him].', 'Dan Kami telah menyerunya dari arah sebelah kanan Gunung Tursina, dan Kami dampingkan dia dengan diberi penghormatan berkata dengan Kami.', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 53, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّا', 'وَوَهَبْنَا لَهُ مِن رَّحْمَتِنَا أَخَاهُ هَارُونَ نَبِيًّا', NULL, 'And We gave him out of Our mercy his brother Aaron as a prophet.', 'Dan Kami kurniakan kepadanya dari rahmat Kami, saudaranya: Harun, yang juga berpangkat Nabi.', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 54, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', 'وَاذْكُرْ فِي الْكِتَابِ إِسْمَاعِيلَ إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', NULL, 'And mention in the Book, Ishmael. Indeed, he was true to his promise, and he was a messenger and a prophet.', 'Dan bacakanlah (wahai Muhammad) di dalam Kitab (Al-Quran) ini perihal Nabi Ismail; sesungguhnya ia adalah benar menepati janji dan adalah ia seorang Rasul, lagi berpangkat Nabi.', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 55, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا', 'وَكَانَ يَأْمُرُ أَهْلَهُ بِالصَّلَاةِ وَالزَّكَاةِ وَكَانَ عِندَ رَبِّهِ مَرْضِيًّا', NULL, 'And he used to enjoin on his people prayer and zakāh and was to his Lord pleasing [i.e., accepted by Him].', 'Dan adalah ia menyuruh keluarganya mengerjakan sembahyang dan memberi zakat, dan ia pula adalah seorang yang diredhai di sisi Tuhannya!', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 56, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', 'وَاذْكُرْ فِي الْكِتَابِ إِدْرِيسَ إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا', NULL, 'And mention in the Book, Idrees. Indeed, he was a man of truth and a prophet.', 'Dan bacakanlah (wahai Muhammad) di dalam Kitab (Al-Quran) ini perihal Nabi Idris; sesungguhnya adalah ia amat benar (tutur katanya dan imannya), serta ia seorang Nabi.', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 57, 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', 'وَرَفَعْنَاهُ مَكَانًا عَلِيًّا', NULL, 'And We raised him to a high station.', 'Dan Kami telah mengangkatnya ke tempat yang tinggi darjatnya.', FALSE, NULL, NULL, 309, 16, 123, 267, FALSE, 0, NULL),
(19, 58, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا', 'أُولَٰئِكَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ مِن ذُرِّيَّةِ آدَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَاهِيمَ وَإِسْرَائِيلَ وَمِمَّنْ هَدَيْنَا وَاجْتَبَيْنَا إِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُ الرَّحْمَٰنِ خَرُّوا سُجَّدًا وَبُكِيًّا', NULL, 'Those were the ones upon whom Allāh bestowed favor from among the prophets of the descendants of Adam and of those We carried [in the ship] with Noah, and of the descendants of Abraham and Israel [i.e., Jacob], and of those whom We guided and chose. When the verses of the Most Merciful were recited to them, they fell in prostration and weeping.', 'Mereka itulah sebahagian dari Nabi-nabi yang telah dikurniakan Allah nikmat yang melimpah-limpah kepada mereka dari keturunan Nabi Adam, dan dari keturunan orang-orang yang Kami bawa (dalam bahtera) bersama-sama Nabi Nuh, dan dari keturunan Nabi Ibrahim, dan (dari keturunan) Israil- dan mereka itu adalah dari orang-orang yang Kami beri hidayah petunjuk dan Kami pilih. Apabila dibacakan kepada mereka ayat-ayat (Allah) Ar-Rahman, mereka segera sujud serta menangis.', FALSE, NULL, NULL, 309, 16, 123, 267, TRUE, 0, NULL),
(19, 59, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيًّا', 'فَخَلَفَ مِن بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا', NULL, 'But there came after them successors [i.e., later generations] who neglected prayer and pursued desires; so they are going to meet evil -', 'Kemudian mereka digantikan oleh keturunan-keturunan yang mencuaikan sembahyang serta menurut hawa nafsu (dengan melakukan maksiat); maka mereka akan menghadapi azab (dalam neraka),', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 60, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا', 'إِلَّا مَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا فَأُولَٰئِكَ يَدْخُلُونَ الْجَنَّةَ وَلَا يُظْلَمُونَ شَيْئًا', NULL, 'Except those who repent, believe and do righteousness; for those will enter Paradise and will not be wronged at all.', 'Kecuali orang-orang yang bertaubat dan beriman serta beramal soleh, maka mereka itu akan masuk Syurga, dan mereka pula tidak dikurangkan pahala sedikitpun, -', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 61, 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا', 'جَنَّاتِ عَدْنٍ الَّتِي وَعَدَ الرَّحْمَٰنُ عِبَادَهُ بِالْغَيْبِ إِنَّهُ كَانَ وَعْدُهُ مَأْتِيًّا', NULL, '[Therein are] gardens of perpetual residence which the Most Merciful has promised His servants in the unseen. Indeed, His promise has ever been eminent.', '(Iaitu) Syurga “Adn” yang telah dijanjikan oleh (Allah) Ar-Rahman kepada hamba-hambaNya disebabkan kepercayaan mereka akan perkara-perkara yang ghaib; sesungguhnya Tuhan itu, janjiNya tetap berlaku.', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 62, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَامًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', NULL, 'They will not hear therein any ill speech - only [greetings of] peace - and they will have their provision therein, morning and afternoon.', 'Mereka tidak akan mendengar di dalamnya perkataan yang sia-sia tetapi mereka sentiasa mendengar perkataan yang baik-baik; dan makan minum untuk mereka disediakan di dalamnya, pagi dan petang (sepanjang masa).', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 63, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', 'تِلْكَ الْجَنَّةُ الَّتِي نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', NULL, 'That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allāh.', 'Itulah taman Syurga yang Kami akan berikan sebagai warisan pusaka kepada orang-orang. yang bertaqwa dari hamba-hamba Kami.', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا', 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا', NULL, '[Gabriel said], "And we [angels] descend not except by the order of your Lord. To Him belongs that before us and that behind us and what is in between. And never is your Lord forgetful -', 'Dan (berkatalah malaikat): “Kami tidak turun dari semasa ke semasa melainkan dengan perintah Tuhanmu (wahai Muhammad); Dia lah jua yang menguasai serta mentadbirkan apa yang di hadapan kita dan apa yang di belakang kita serta apa yang di antara itu; dan tiadalah Tuhanmu itu lupa, -', FALSE, NULL, NULL, 309, 16, 124, 267, FALSE, 0, NULL),
(19, 65, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا', 'رَّبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِهِ هَلْ تَعْلَمُ لَهُ سَمِيًّا', NULL, 'Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?"', '“Tuhan yang mencipta dan mentadbirkan langit dan bumi serta segala yang ada di antara keduanya; oleh itu, sembahlah engkau akan Dia dan bersabarlah dengan tekun tetap dalam beribadat kepadaNya; adakah engkau mengetahui sesiapapun yang senama dan sebanding denganNya?”', FALSE, NULL, NULL, 310, 16, 124, 267, FALSE, 0, NULL),
(19, 66, 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', 'وَيَقُولُ الْإِنسَانُ أَإِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', NULL, 'And man [i.e., the disbeliever] says, "When I have died, am I going to be brought forth alive?"', 'Dan manusia (yang kafir) berkata: “Apa! Apabila aku mati, adakah aku akan dibangkitkan hidup semula?”', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 67, 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا', 'أَوَلَا يَذْكُرُ الْإِنسَانُ أَنَّا خَلَقْنَاهُ مِن قَبْلُ وَلَمْ يَكُ شَيْئًا', NULL, 'Does man not remember that We created him before, while he was nothing?', 'Patutkah manusia itu berkata demikian dan tidak memikirkan bahawa Kami telah menciptakan dia dahulu sedang ia pada masa itu belum ada sebarang apapun?', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَالشَّيَاطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', NULL, 'So by your Lord, We will surely gather them and the devils; then We will bring them to be present around Hell upon their knees.', 'Oleh itu, demi Tuhanmu (wahai Muhammad)! Sesungguhnya Kami akan himpunkan mereka yang kafir itu beserta syaitan-syaitan di Padang Mahsyar, kemudian Kami akan bawa mereka duduk berlutut di keliling neraka Jahannam.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّا', 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى الرَّحْمَٰنِ عِتِيًّا', NULL, 'Then We will surely extract from every sect those of them who were worst against the Most Merciful in insolence.', 'Sesudah itu, sesungguhnya kami akan cabut dari tiap-tiap golongan, mana-mana orang yang sangat derhaka kepada (Allah) Ar-Rahman, di antara mereka.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 70, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', 'ثُمَّ لَنَحْنُ أَعْلَمُ بِالَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', NULL, 'Then, surely it is We who are most knowing of those most worthy of burning therein.', 'Kemudian, sesungguhnya Kami lebih mengetahui akan orang-orang yang lebih patut diseksa dan dibakar dangan api neraka itu.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 71, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', NULL, 'And there is none of you except he will come to it. This is upon your Lord an inevitability decreed.', 'Dan tiada seorangpun di antara kamu melainkan akan sampai kepadanya; (yang demikian) adalah satu perkara yang mesti (berlaku) yang telah ditetapkan oleh Tuhanmu.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 72, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّا', 'ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوا وَّنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا', NULL, 'Then We will save those who feared Allāh and leave the wrongdoers within it, on their knees.', 'Kemudian Kami akan selamatkan orang-orang yang bertaqwa, dan kami akan biarkan orang-orang yang zalim (dengan kekufurannya dan maksiatnya) tinggal berlutut di dalam neraka itu.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 73, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَيُّ الْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', NULL, 'And when Our verses are recited to them as clear evidences, those who disbelieve say to those who believe, "Which of [our] two parties is best in position and best in association?"', 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas nyata, berkatalah orang-orang yang kafir kepada orang-orang yang beriman: “Puak yang manakah (dari kami dan kamu) yang lebih baik tempat tinggalnya dan lebih elok majlis perhimpunannya?', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 74, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًا وَرِءْيًا', 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَاثًا وَرِئْيًا', NULL, 'And how many a generation have We destroyed before them who were better in possessions and [outward] appearance?', 'Dan berapa banyak kaum-kaum (yang ingkar) sebelum mereka, kami telah binasakan, sedang mereka lebih elok alat-alat kesenangannya dan lebih elok keadaannya pada pandangan mata.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 75, 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', 'قُلْ مَن كَانَ فِي الضَّلَالَةِ فَلْيَمْدُدْ لَهُ الرَّحْمَٰنُ مَدًّا حَتَّىٰ إِذَا رَأَوْا مَا يُوعَدُونَ إِمَّا الْعَذَابَ وَإِمَّا السَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', NULL, 'Say, "Whoever is in error - let the Most Merciful extend for him an extension [in wealth and time] until, when they see that which they were promised - either punishment [in this world] or the Hour [of resurrection] - they will come to know who is worst in position and weaker in soldiers."', 'Katakanlah (wahai Muhammad): “Sesiapa yang berada di dalam kesesatan, maka biarlah (Allah) Ar-Rahman melanjutkan baginya satu tempoh yang tertentu, hingga apabila mereka melihat apa yang dijanjikan kepada mereka, - sama ada azab sengsara dunia ataupun azab kiamat, maka (pada saat itu) mereka akan mengetahui siapakah orangnya yang lebih buruk kedudukannya dan lebih lemah penyokong-penyokongnya.”', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 76, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', 'وَيَزِيدُ اللَّهُ الَّذِينَ اهْتَدَوْا هُدًى وَالْبَاقِيَاتُ الصَّالِحَاتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', NULL, 'And Allāh increases those who were guided, in guidance, and the enduring good deeds are better to your Lord for reward and better for recourse.', 'Dan Allah akan menambahi hidayah petunjuk bagi orang-orang yang menurut jalan petunjuk; dan amal-amal yang baik yang tetap kekal faedah-faedahnya itu, lebih baik balasan pahalanya di sisi Tuhanmu dan lebih baik kesudahannya.', FALSE, NULL, NULL, 310, 16, 124, 268, FALSE, 0, NULL),
(19, 77, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', 'أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', NULL, 'Then, have you seen he who disbelieved in Our verses and said, "I will surely be given wealth and children [in the next life]"?', 'Maka tidakkah engkau merasa hairan memikirkan (wahai Muhammad), akan orang yang kufur ingkar kepada ayat-ayat keterangan Kami serta ia berkata: “Demi sesungguhnya aku akan diberikan harta kekayaan dan anak-pinak pada hari akhirat?”', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 78, 'أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا', 'أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِندَ الرَّحْمَٰنِ عَهْدًا', NULL, 'Has he looked into the unseen, or has he taken from the Most Merciful a promise?', 'Adakah ia telah mengetahui akan perkara yang ghaib, atau adakah ia telah membuat perjanjian dengan (Allah) Ar-Rahman mengenainya?', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 79, 'كَلَّا سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّا', 'كَلَّا سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا', NULL, 'No! We will record what he says and extend [i.e., increase] for him from the punishment extensively.', 'Tidak sekali-kali! Kami akan menulis apa yang dikatakannya, dan Kami akan tambahi baginya dari azab seksa, berganda-ganda.', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 80, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًا', 'وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْدًا', NULL, 'And We will inherit him [in] what he mentions, and he will come to Us alone.', 'Dan Kami akan warisi (harta benda dan anak-pinak) yang dikatakannya itu, dan ia akan datang kepada kami dengan seorang diri.', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 81, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لِّيَكُونُوا۟ لَهُمْ عِزًّا', 'وَاتَّخَذُوا مِن دُونِ اللَّهِ آلِهَةً لِّيَكُونُوا لَهُمْ عِزًّا', NULL, 'And they have taken besides Allāh [false] deities that they would be for them [a source of] honor.', 'Dan mereka yang kafir menyembah benda-benda yang lain dari Allah sebagai tuhan-tuhan, supaya benda-benda yang mereka sembah itu menjadi penolong-penolong yang memberi kemuliaan dan pengaruh kepada mereka.', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 82, 'كَلَّا سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', 'كَلَّا سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', NULL, 'No! They [i.e., those "gods"] will deny their worship of them and will be against them opponents [on the Day of Judgement].', 'Tidak sekali-kali! Bahkan benda-benda yang mereka pertuhankan itu mengingkari perbuatan mereka menyembahnya, dan akan menjadi musuh yang membawa kehinaan kepada mereka.', FALSE, NULL, NULL, 311, 16, 124, 268, FALSE, 0, NULL),
(19, 83, 'أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَٰطِينَ عَلَى ٱلْكَٰفِرِينَ تَؤُزُّهُمْ أَزًّا', 'أَلَمْ تَرَ أَنَّا أَرْسَلْنَا الشَّيَاطِينَ عَلَى الْكَافِرِينَ تَؤُزُّهُمْ أَزًّا', NULL, 'Do you not see that We have sent the devils upon the disbelievers, inciting them [to evil] with [constant] incitement?', 'Tidakkah engkau mengetahui (Wahai Muhammad) bahawa Kami telah menghantarkan Syaitan-syaitan kepada orang-orang kafir, untuk menggalakkan mereka mengerjakan perbuatan kufur dan maksiat dengan bersungguh-sungguh?', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 84, 'فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', 'فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', NULL, 'So be not impatient over them. We only count out [i.e., allow] to them a [limited] number.', 'Oleh itu, janganlah engkau segera marah terhadap mereka yang ingkar itu, kerana sesungguhnya kami hanya menghitung hari yang sedikit sahaja bilangannya untuk mereka.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 85, 'يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًا', 'يَوْمَ نَحْشُرُ الْمُتَّقِينَ إِلَى الرَّحْمَٰنِ وَفْدًا', NULL, 'On the Day We will gather the righteous to the Most Merciful as a delegation', '(Ingatlah) hari Kami himpunkan orang-orang yang bertaqwa untuk mengadap (Allah) Ar-Rahman, dengan berpasuk-pasukan.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 86, 'وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًا', 'وَنَسُوقُ الْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًا', NULL, 'And will drive the criminals to Hell in thirst', 'Dan Kami akan menghalau orang-orang yang bersalah ke neraka Jahannam, dalam keadaan dahaga.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 87, 'لَّا يَمْلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا', 'لَّا يَمْلِكُونَ الشَّفَاعَةَ إِلَّا مَنِ اتَّخَذَ عِندَ الرَّحْمَٰنِ عَهْدًا', NULL, 'None will have [power of] intercession except he who had taken from the Most Merciful a covenant.', 'Mereka tidak berhak mendapat dan memberi syafaat, kecuali orang yang telah mengikat perjanjian (dengan iman dan amal yang soleh) di sisi Allah yang melimpah-limpah rahmatNya!.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 88, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا', 'وَقَالُوا اتَّخَذَ الرَّحْمَٰنُ وَلَدًا', NULL, 'And they say, "The Most Merciful has taken [for Himself] a son."', 'Dan mereka yang kafir berkata: “(Allah) Ar-Rahman, mempunyai anak.”', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 89, 'لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّا', 'لَّقَدْ جِئْتُمْ شَيْئًا إِدًّا', NULL, 'You have done an atrocious thing.', 'Demi sesungguhnya, kamu telah melakukan satu perkara yang besar salahnya!', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 90, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا', 'تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ الْأَرْضُ وَتَخِرُّ الْجِبَالُ هَدًّا', NULL, 'The heavens almost rupture therefrom and the earth splits open and the mountains collapse in devastation', 'Langit nyaris-nyaris pecah disebabkan (anggapan mereka) yang demikian, dan bumi pula nyaris-nyaris terbelah, serta gunung-ganang pun nyaris-nyaris runtuh ranap, -', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 91, 'أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًا', 'أَن دَعَوْا لِلرَّحْمَٰنِ وَلَدًا', NULL, 'That they attribute to the Most Merciful a son.', 'Kerana mereka mendakwa mengatakan: (Allah) Ar-Rahman mempunyai anak.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 92, 'وَمَا يَنۢبَغِى لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا', 'وَمَا يَنبَغِي لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا', NULL, 'And it is not appropriate for the Most Merciful that He should take a son.', 'Padahal tiadalah layak bagi (Allah) Ar-Rahman, bahawa Ia mempunyai anak.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 93, 'إِن كُلُّ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَٰنِ عَبْدًا', 'إِن كُلُّ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ إِلَّا آتِي الرَّحْمَٰنِ عَبْدًا', NULL, 'There is no one in the heavens and earth but that he comes to the Most Merciful as a servant.', 'Tidak ada sesiapapun di langit dan di bumi melainkan ia akan datang kepada (Allah) Ar-Rahman, sebagai hamba.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 94, 'لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّا', 'لَّقَدْ أَحْصَاهُمْ وَعَدَّهُمْ عَدًّا', NULL, 'He has enumerated them and counted them a [full] counting.', 'Demi sesungguhnya! Allah telah mengira mereka (dengan pengetahuanNya) serta menghitung mereka satu persatu.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 95, 'وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَٰمَةِ فَرْدًا', 'وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْدًا', NULL, 'And all of them are coming to Him on the Day of Resurrection alone.', 'Dan mereka masing-masing akan datang mengadapNya pada hari kiamat dengan seorang diri.', FALSE, NULL, NULL, 311, 16, 124, 269, FALSE, 0, NULL),
(19, 96, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَٰنُ وُدًّا', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَيَجْعَلُ لَهُمُ الرَّحْمَٰنُ وُدًّا', NULL, 'Indeed, those who have believed and done righteous deeds - the Most Merciful will appoint for them affection.', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, Allah yang melimpah-limpah rahmatnya akan menanamkan bagi mereka dalam hati orang ramai perasaan kasih sayang.', FALSE, NULL, NULL, 312, 16, 124, 269, FALSE, 0, NULL),
(19, 97, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًا لُّدًّا', 'فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ الْمُتَّقِينَ وَتُنذِرَ بِهِ قَوْمًا لُّدًّا', NULL, 'So, [O Muḥammad], We have only made it [i.e., the Qur’ān] easy in your tongue [i.e., the Arabic language] that you may give good tidings thereby to the righteous and warn thereby a hostile people.', 'Maka sesungguhnya Kami memudahkan turunnya Al-Quran ini dengan bahasamu (wahai Muhammad), ialah supaya engkau memberi khabar gembira dengannya kepada orang-orang yang bertaqwa, dan supaya engkau memberi amaran dengannya kepada kaum yang degil dalam kekufurannya.', FALSE, NULL, NULL, 312, 16, 124, 269, FALSE, 0, NULL),
(19, 98, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا', 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًا', NULL, 'And how many have We destroyed before them of generations? Do you perceive of them anyone or hear from them a sound?', 'Dan amatlah banyaknya kaum-kaum kafir yang Kami telah binasakan sebelum mereka; engkau tidak menyedari ataupun mendengar suara yang sayup bagi seseorangpun dari orang-orang yang telah dibinasakan itu.', FALSE, NULL, NULL, 312, 16, 124, 269, FALSE, 0, NULL),
(20, 1, 'طه', 'طه', NULL, 'Ṭā, Hā.', 'Taa'' Haa.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 1, NULL),
(20, 2, 'مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ', 'ما انزلنا عليك القران لتشقى', NULL, 'We have not sent down to you the Qur’ān that you be distressed', 'Kami tidak menurunkan Al-Quran kepadamu (wahai Muhammad) supaya engkau menanggung kesusahan.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 5, NULL),
(20, 3, 'إِلَّا تَذْكِرَةً لِّمَن يَخْشَىٰ', 'الا تذكرة لمن يخشى', NULL, 'But only as a reminder for those who fear [Allāh] -', 'Hanya untuk menjadi peringatan bagi orang-orang yang takut melanggar perintah. Allah', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 4, NULL),
(20, 4, 'تَنزِيلًا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَـٰوَٰتِ ٱلْعُلَى', 'تنزيلا ممن خلق الارض والسماوات العلى', NULL, 'A revelation from He who created the earth and highest heavens,', '(Al-Quran) diturunkan dari (Tuhan) yang menciptakan bumi dan langit yang tinggi.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 6, NULL),
(20, 5, 'ٱلرَّحْمَـٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ', 'الرحمن على العرش استوى', NULL, 'The Most Merciful [who is] above the Throne established.', 'Iaitu (Allah) Ar-Rahman, yang bersemayam di atas Arasy.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 4, NULL),
(20, 6, 'لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ', 'له ما في السماوات وما في الارض وما بينهما وما تحت الثرى', NULL, 'To Him belongs what is in the heavens and what is on the earth and what is between them and what is under the soil.', 'Dia lah jua yang memiliki segala yang ada di langit dan yang ada di bumi serta yang ada di antara keduanya dan juga yang ada di bawah tanah basah di perut bumi.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 12, NULL),
(20, 7, 'وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى', 'وان تجهر بالقول فانه يعلم السر واخفى', NULL, 'And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden.', 'Dan jika engkau menyaringkan suara dengan doa permohonanmu, (maka yang demikian tidaklah perlu), kerana sesungguhnya Allah mengetahui segala rahsia dan segala yang tersembunyi.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 7, NULL),
(20, 8, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ', 'الله لا اله الا هو له الاسماء الحسنى', NULL, 'Allāh - there is no deity except Him. To Him belong the best names.', 'Allah! Tiada Tuhan yang berhak disembah melainkan Dia, bagiNyalah segala nama yang baik.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 8, NULL),
(20, 9, 'وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'وهل اتاك حديث موسى', NULL, 'And has the story of Moses reached you? -', 'Dan sudahkah sampai kepadamu (wahai Muhammad) perihal Nabi Musa?', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 4, NULL),
(20, 10, 'إِذْ رَءَا نَارًا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًى', 'اذ راى نارا فقال لاهله امكثوا اني انست نارا لعلي اتيكم منها بقبس او اجد على النار هدى', NULL, 'When he saw a fire and said to his family, "Stay here; indeed, I have perceived a fire; perhaps I can bring you a torch or find at the fire some guidance."', 'Ketika ia melihat api, lalu berkatalah ia kepada isterinya: “Berhentilah! Sesungguhnya aku ada melihat api semoga aku dapat membawa kepada kamu satu cucuhan daripadanya, atau aku dapat di tempat api itu: penunjuk jalan.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 18, NULL),
(20, 11, 'فَلَمَّآ أَتَىٰهَا نُودِىَ يَـٰمُوسَىٰٓ', 'فلما اتاها نودي يا موسى', NULL, 'And when he came to it, he was called, "O Moses,', 'Maka apabila ia sampai ke tempat api itu (kedengaran) ia diseru: “Wahai Musa!” -', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 4, NULL),
(20, 12, 'إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'اني انا ربك فاخلع نعليك انك بالواد المقدس طوى', NULL, 'Indeed, I am your Lord, so remove your sandals. Indeed, you are in the blessed valley of Ṭuwā.', '“Sesungguhnya Aku Tuhanmu! Maka bukalah kasutmu, kerana engkau sekarang berada di Wadi Tuwa yang suci.', FALSE, NULL, NULL, 312, 16, 125, 270, FALSE, 9, NULL),
(20, 13, 'وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ', 'وانا اخترتك فاستمع لما يوحى', NULL, 'And I have chosen you, so listen to what is revealed [to you].', '“Dan Aku telah memilihmu menjadi Rasul maka dengarlah apa yang akan diwahyukan kepadamu.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 5, NULL),
(20, 14, 'إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ', 'انني انا الله لا اله الا انا فاعبدني واقم الصلاة لذكري', NULL, 'Indeed, I am Allāh. There is no deity except Me, so worship Me and establish prayer for My remembrance.', '“Sesungguhnya Akulah Allah; tiada tuhan melainkan Aku; oleh itu, sembahlah akan Daku, dan dirikanlah sembahyang untuk mengingati Daku.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 11, NULL),
(20, 15, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ', 'ان الساعة اتية اكاد اخفيها لتجزى كل نفس بما تسعى', NULL, 'Indeed, the Hour is coming - I almost conceal it - so that every soul may be recompensed according to that for which it strives.', '“Sesungguhnya hari kiamat itu tetap akan datang - yang Aku sengaja sembunyikan masa datangnya - supaya tiap-tiap diri dibalas akan apa yang ia usahakan.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 10, NULL),
(20, 16, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ', 'فلا يصدنك عنها من لا يؤمن بها واتبع هواه فتردى', NULL, 'So do not let one avert you from it who does not believe in it and follows his desire, for you [then] would perish.', '“Maka janganlah engkau dihalangi daripada mempercayainya oleh orang yang tidak beriman kepadanya serta ia menurut hawa nafsunya; kerana dengan itu engkau akan binasa.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 10, NULL),
(20, 17, 'وَمَا تِلْكَ بِيَمِينِكَ يَـٰمُوسَىٰ', 'وما تلك بيمينك يا موسى', NULL, 'And what is that in your right hand, O Moses?"', '“Dan apa (bendanya) yang di tangan kananmu itu wahai Musa?”', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 4, NULL),
(20, 18, 'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ', 'قال هي عصاي اتوكا عليها واهش بها على غنمي ولي فيها مارب اخرى', NULL, 'He said, "It is my staff; I lean upon it, and I bring down leaves for my sheep and I have therein other uses."', 'Nabi Musa menjawab: “Ini ialah tongkatku; aku bertekan atasnya semasa, berjalan, dan aku memukul dengannya daun-daun kayu supaya gugur kepada kambing-kambingku, dan ada lagi lain-lain keperluanku pada tongkat itu”.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 13, NULL),
(20, 19, 'قَالَ أَلْقِهَا يَـٰمُوسَىٰ', 'قال القها يا موسى', NULL, '[Allāh] said, "Throw it down, O Moses."', 'Allah Taala berfirman: “Campakkanlah tongkatmu itu wahai Musa!”', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 3, NULL),
(20, 20, 'فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌ تَسْعَىٰ', 'فالقاها فاذا هي حية تسعى', NULL, 'So he threw it down, and thereupon it was a snake, moving swiftly.', 'Lalu ia mencampakkannya, maka tiba-tiba tongkatnya itu menjadi seekor ular yang bergerak menjalar.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 5, NULL),
(20, 21, 'قَالَ خُذْهَا وَلَا تَخَفْ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ', 'قَالَ خُذْهَا وَلَا تَخَفْ سَنُعِيدُهَا سِيرَتَهَا الْأُولَىٰ', NULL, '[Allāh] said, "Seize it and fear not; We will return it to its former condition.', 'Allah berfirman: “Tangkaplah akan dia, dan janganlah engkau takut, Kami akan mengembalikannya kepada keadaannya yang asal.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 0, NULL),
(20, 22, 'وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ', 'وَاضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ آيَةً أُخْرَىٰ', NULL, 'And draw in your hand to your side; it will come out white without disease - another sign,', '“Dan kepitlah tanganmu di celah lambungmu; nescaya keluarlah ia putih bersinar-sinar dengan tidak ada cacat; sebagai satu mukjizat yang lain.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 0, NULL),
(20, 23, 'لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى', 'لِنُرِيَكَ مِنْ آيَاتِنَا الْكُبْرَى', NULL, 'That We may show you [some] of Our greater signs.', '“(Berlakunya yang demikian itu) kerana Kami hendak memperlihatkan kepadamu sebahagian dari tanda-tanda kekuasaan Kami yang besar.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 0, NULL),
(20, 24, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ', NULL, 'Go to Pharaoh. Indeed, he has transgressed [i.e., tyrannized]."', '“Pergilah kepada Firaun, sesungguhnya ia telah melampaui batas”.', FALSE, NULL, NULL, 313, 16, 125, 270, FALSE, 0, NULL),
(20, 25, 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', 'قَالَ رَبِّ اشْرَحْ لِي صَدْرِي', NULL, '[Moses] said, "My Lord, expand [i.e., relax] for me my breast [with assurance]', 'Nabi Musa berdoa dengan berkata: “Wahai Tuhanku, lapangkanlah bagiku, dadaku;', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 26, 'وَيَسِّرْ لِىٓ أَمْرِى', 'وَيَسِّرْ لِي أَمْرِي', NULL, 'And ease for me my task', '“Dan mudahkanlah bagiku, tugasku;', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 27, 'وَٱحْلُلْ عُقْدَةً مِّن لِّسَانِى', 'وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي', NULL, 'And untie the knot from my tongue', '“Dan lepaskanlah simpulan dari lidahku,', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 28, 'يَفْقَهُوا۟ قَوْلِى', 'يَفْقَهُوا قَوْلِي', NULL, 'That they may understand my speech.', '“Supaya mereka faham perkataanku;', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 29, 'وَٱجْعَل لِّى وَزِيرًا مِّنْ أَهْلِى', 'وَاجْعَل لِّي وَزِيرًا مِّنْ أَهْلِي', NULL, 'And appoint for me a minister [i.e., assistant] from my family -', '“Dan jadikanlah bagiku, seorang penyokong dari keluargaku.', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 30, 'هَٰرُونَ أَخِى', 'هَارُونَ أَخِي', NULL, 'Aaron, my brother.', '“Iaitu Harun saudaraku;', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 31, 'ٱشْدُدْ بِهِۦٓ أَزْرِى', 'اشْدُدْ بِهِ أَزْرِي', NULL, 'Increase through him my strength', '“Kuatkanlah dengan sokongannya, pendirianku,', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 32, 'وَأَشْرِكْهُ فِىٓ أَمْرِى', 'وَأَشْرِكْهُ فِي أَمْرِي', NULL, 'And let him share my task', '“Dan jadikanlah dia turut campur bertanggungjawab dalam urusanku,', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 33, 'كَىْ نُسَبِّحَكَ كَثِيرًا', 'كَيْ نُسَبِّحَكَ كَثِيرًا', NULL, 'That we may exalt You much', '“Supaya kami sentiasa beribadat dan memujiMu,', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 34, 'وَنَذْكُرَكَ كَثِيرًا', 'وَنَذْكُرَكَ كَثِيرًا', NULL, 'And remember You much.', '“Dan (supaya) kami sentiasa menyebut dan mengingatiMu;', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 35, 'إِنَّكَ كُنتَ بِنَا بَصِيرًا', 'إِنَّكَ كُنتَ بِنَا بَصِيرًا', NULL, 'Indeed, You are of us ever Seeing."', '“Sesungguhnya Engkau adalah sedia melihat dan mengetahui hal ehwal kami”.', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 36, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَىٰ', NULL, '[Allāh] said, "You have been granted your request, O Moses.', 'Allah berfirman: “Sesungguhnya telah diberikan kepadamu apa yang engkau pohonkan itu, wahai Musa!', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 37, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰ', NULL, 'And We had already conferred favor upon you another time,', '“Dan demi sesungguhnya! Kami telahpun mengurniakan kepadamu berbagai nikmat pada satu masa yang lain sebelum ini.', FALSE, NULL, NULL, 313, 16, 125, 271, FALSE, 0, NULL),
(20, 38, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'إِذْ أَوْحَيْنَا إِلَىٰ أُمِّكَ مَا يُوحَىٰ', NULL, 'When We inspired to your mother what We inspired,', '“Ketika Kami ilhamkan kepada ibumu, dengan memberitahu kepadanya:', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 39, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 'أَنِ اقْذِفِيهِ فِي التَّابُوتِ فَاقْذِفِيهِ فِي الْيَمِّ فَلْيُلْقِهِ الْيَمُّ بِالسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّي وَعَدُوٌّ لَّهُ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّي وَلِتُصْنَعَ عَلَىٰ عَيْنِي', NULL, '[Saying], ''Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.'' And I bestowed upon you love from Me that you would be brought up under My eye [i.e., observation and care].', '“Letakkanlah anakmu di dalam peti, kemudian lepaskanlah peti itu ke laut, maka biarlah laut itu membawanya terdampar ke pantai, supaya dipungut oleh musuhKu dan musuhnya; dan Aku telah tanamkan dari kemurahanKu perasaan kasih sayang orang terhadapmu; dan supaya engkau dibela dan dipelihara dengan pengawasanKu.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 40, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَٰمُوسَىٰ', 'إِذْ تَمْشِي أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُ فَرَجَعْنَاكَ إِلَىٰ أُمِّكَ كَيْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَاكَ مِنَ الْغَمِّ وَفَتَنَّاكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِي أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَا مُوسَىٰ', NULL, '[And We favored you] when your sister went and said, ''Shall I direct you to someone who will be responsible for him?'' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.', '“Ketika saudara perempuanmu pergi mencarimu lalu berkata kepada orang-orang yang memungutmu: “Mahukah, aku tunjukkan kamu kepada orang yang boleh memeliharanya?” Maka dengan jalan itu Kami mengembalikanmu kepada ibumu supaya tenang hatinya dan supaya ia tidak berdukacita kerana bercerai denganmu; dan semasa engkau membunuh seorang lelaki, lalu Kami selamatkan engkau dari kesusahan pembunuhan itu; dan Kami telah melepaskan engkau berkali-kali dari berbagai-bagai cubaan; kemudian engkau tinggal dengan selamat beberapa tahun dalam kalangan penduduk negeri Madyan; setelah itu engkau sekarang datang dari sana pada masa yang telah ditentukan, wahai Musa!', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 41, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', 'وَاصْطَنَعْتُكَ لِنَفْسِي', NULL, 'And I produced you for Myself.', '“Dan Aku telah memilihmu untuk menjadi RasulKu.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 42, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 'اذْهَبْ أَنتَ وَأَخُوكَ بِآيَاتِي وَلَا تَنِيَا فِي ذِكْرِي', NULL, 'Go, you and your brother, with My signs and do not slacken in My remembrance.', '“Pergilah, engkau dan saudaramu, membawa mukjizat-mukjizat pengurniaanKu dan janganlah kamu berdua lemah dan cuai dalam menyebut serta mengingati Daku.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 43, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذْهَبَا إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ', NULL, 'Go, both of you, to Pharaoh. Indeed, he has transgressed.', '“Pergilah kamu berdua kepada Firaun, sesungguhnya ia telah melampaui batas dalam kekufurannya.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 44, 'فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', 'فَقُولَا لَهُ قَوْلًا لَّيِّنًا لَّعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَىٰ', NULL, 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allāh]."', '“Kemudian hendaklah kamu berkata kepadanya, dengan kata-kata yang lemah-lembut, semoga ia beringat atau takut”.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 45, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 'قَالَا رَبَّنَا إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَا أَوْ أَن يَطْغَىٰ', NULL, 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."', 'Mereka berdua berkata: “Wahai Tuhan kami! Sesungguhnya kami takut bahawa ia akan segera menyeksa kami, atau ia akan melampau batas”.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 46, 'قَالَ لَا تَخَافَآ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', 'قَالَ لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَىٰ', NULL, '[Allāh] said, "Fear not. Indeed, I am with you both; I hear and I see.', 'Allah berfirman: “Janganlah kamu takut, sesungguhnya Aku ada bersama-sama kamu; Aku mendengar dan melihat segala-galanya.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 47, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', 'فَأْتِيَاهُ فَقُولَا إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِي إِسْرَائِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَاكَ بِآيَةٍ مِّن رَّبِّكَ وَالسَّلَامُ عَلَىٰ مَنِ اتَّبَعَ الْهُدَىٰ', NULL, 'So go to him and say, ''Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.', '“Oleh itu, pergilah kamu berdua kepadanya, kemudian katakanlah: “Bahawa sesungguhnya kami ini Rasul-rasul dari Tuhanmu, maka bebaskanlah kaum Bani lsrail mengikut kami, dan janganlah engkau menyeksakan mereka. Sesungguhnya kami telah datang kepadamu membawa satu tanda (mukjizat) dari Tuhanmu! Dan selamat sejahtera itu adalah untuk orang-orang yang menurut petunjuk ugama Allah.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 48, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', 'إِنَّا قَدْ أُوحِيَ إِلَيْنَا أَنَّ الْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', NULL, 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.''"', '“Sesungguhnya telah diwahyukan kepada kami bahawa azab seksa di dunia dan di akhirat ditimpakan kepada orang yang mendustakan ayat-ayat Allah dan berpaling daripadanya”.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 49, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', 'قَالَ فَمَن رَّبُّكُمَا يَا مُوسَىٰ', NULL, '[Pharaoh] said, "So who is the Lord of you two, O Moses?"', '(Setelah mereka menyampaikan perintah Allah itu), Firaun berkata: “Jika demikian, siapakah Tuhan kamu berdua, hai Musa?”', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 50, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 'قَالَ رَبُّنَا الَّذِي أَعْطَىٰ كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَىٰ', NULL, 'He said, "Our Lord is He who gave each thing its form and then guided [it]."', 'Nabi Musa menjawab: “Tuhan kami ialah yang telah memberikan kepada tiap-tiap sesuatu: kejadian semulajadinya yang sesuai dengannya, kemudian Ia memberi petunjuk kepadanya akan cara menggunakannya”.', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 51, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', 'قَالَ فَمَا بَالُ الْقُرُونِ الْأُولَىٰ', NULL, '[Pharaoh] said, "Then what is the case of the former generations?"', 'Firaun bertanya lagi: “Jika demikian, bagaimana pula keadaan kaum-kaum yang telah lalu?”', FALSE, NULL, NULL, 314, 16, 125, 271, FALSE, 0, NULL),
(20, 52, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', 'قَالَ عِلْمُهَا عِندَ رَبِّي فِي كِتَابٍ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى', NULL, '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."', 'Nabi Musa menjawab: “Pengetahuan mengenainya ada di sisi Tuhanku, tertulis di dalam sebuah Kitab; Tuhanku tidak pernah keliru dan Ia juga tidak pernah lupa”.', FALSE, NULL, NULL, 315, 16, 125, 271, FALSE, 0, NULL),
(20, 53, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ', 'الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ أَزْوَاجًا مِّن نَّبَاتٍ شَتَّىٰ', NULL, '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.', '(Dia lah Tuhan) yang telah menjadikan bumi bagi kamu sebagai hamparan, dan Ia telah mengadakan bagi kamu padanya jalan-jalan lalu-lalang; dan Ia juga telah menurunkan hujan dari langit. Maka Kami keluarkan dengannya berjenis-jenis tanaman dan buah-buahan yang berlainan keadaannya.', FALSE, NULL, NULL, 315, 16, 125, 271, FALSE, 0, NULL),
(20, 54, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', 'كُلُوا وَارْعَوْا أَنْعَامَكُمْ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّأُولِي النُّهَىٰ', NULL, 'Eat [therefrom] and pasture your livestock. Indeed in that are signs for those of intelligence.', 'Makanlah kamu daripadanya dan berilah makan binatang-binatang ternak kamu; sesungguhnya semuanya itu mengandungi tanda-tanda yang membuktikan kemurahan Allah, bagi orang-orang yang berakal fikiran.', FALSE, NULL, NULL, 315, 16, 125, 271, FALSE, 0, NULL),
(20, 55, 'مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', 'مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', NULL, 'From it [i.e., the earth] We created you, and into it We will return you, and from it We will extract you another time.', 'Dari bumilah Kami ciptakan kamu, dan ke dalamnya Kami akan mengembalikan kamu, dan daripadanya pula Kami akan mengeluarkan kamu sekali lagi.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 56, 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', 'وَلَقَدْ أَرَيْنَاهُ آيَاتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', NULL, 'And We certainly showed him [i.e., Pharaoh] Our signs - all of them - but he denied and refused.', 'Dan demi sesungguhnya! Kami telah tunjukkan kepada Firaun segala tanda-tanda yang membukti kekuasaan Kami; dalam pada itu ia mendustakannya dan enggan beriman.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 57, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَا مُوسَىٰ', NULL, 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?', 'Firaun berkata: “Patutkah engkau datang kepada kami untuk mengeluarkan kami dari negeri kami dengan sihirmu, hai Musa?', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 58, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى', 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِ فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُ نَحْنُ وَلَا أَنتَ مَكَانًا سُوًى', NULL, 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."', '“Kalau demikian, sesungguhnya kami juga akan bawakan kepadamu sihir yang seperti itu untuk melawanmu! Maka tentukanlah suatu tempoh pertemuan antara kami denganmu, yang kita bersama tidak akan memungkirinya, di suatu tempat yang sesuai bagi kedua belah pihak”.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 59, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى', 'قَالَ مَوْعِدُكُمْ يَوْمُ الزِّينَةِ وَأَن يُحْشَرَ النَّاسُ ضُحًى', NULL, '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."', 'Nabi Musa menjawab: “Tempoh yang aku tetapkan untuk kamu itu ialah hari perayaan, dan hendaklah orang ramai berhimpun pada waktu dhuha”.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 60, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُ ثُمَّ أَتَىٰ', NULL, 'So Pharaoh went away, put together his plan, and then came [to Moses].', 'Maka Firaun pun berangkat dari majlis itu. Ia mengumpulkan ahli-ahli sihir untuk menjalankan tipu-dayanya, kemudian ia datang ke tempat perlawanan.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 61, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا عَلَى اللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ افْتَرَىٰ', NULL, 'Moses said to them [i.e., the magicians summoned by Pharaoh], "Woe to you! Do not invent a lie against Allāh or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."', 'Nabi Musa berkata kepada mereka: “Celakalah kamu kelak! Janganlah kamu mendakwa secara dusta terhadap Allah, kerana dengan sebab itu Ia akan membinasakan kamu dengan azab seksa; dan sesungguhnya orang yang berdusta, tetap hampa dan kecewa”.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 62, 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 'فَتَنَازَعُوا أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا النَّجْوَىٰ', NULL, 'So they disputed over their affair among themselves and concealed their private conversation.', 'Maka merekapun berbantahan dan berunding sesama sendiri mengenai perkara sihir mereka, dan mereka rahsiakan apa yang mereka rundingkan.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 63, 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 'قَالُوا إِنْ هَٰذَانِ لَسَاحِرَانِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ الْمُثْلَىٰ', NULL, 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way [i.e., religion or tradition].', 'Mereka berkata: “Dua orang ini, sebenarnya dua ahli sihir yang bertujuan hendak mengeluarkan kamu dari negeri kamu dengan sihir mereka, dan hendak melenyapkan kepercayaan serta adat peraturan kamu yang utama.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 64, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', 'فَأَجْمِعُوا كَيْدَكُمْ ثُمَّ ائْتُوا صَفًّا وَقَدْ أَفْلَحَ الْيَوْمَ مَنِ اسْتَعْلَىٰ', NULL, 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."', '“Oleh itu, satukanlah segala cara helah kamu, kemudian datanglah beramai-ramai dalam satu barisan untuk menentangnya; dan sesungguhnya beruntunglah orang yang menang pada hari ini”.', FALSE, NULL, NULL, 315, 16, 126, 272, FALSE, 0, NULL),
(20, 65, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', 'قَالُوا يَا مُوسَىٰ إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', NULL, 'They said, "O Moses, either you throw or we will be the first to throw."', 'Mereka berkata: “Wahai Musa! Engkaukah yang akan mencampak lebih dahulu atau kamikah yang mula-mula mencampak?”', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 66, 'قَالَ بَلْ أَلْقُوا۟ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 'قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', NULL, 'He said, "Rather, you throw." And suddenly their ropes and staffs seemed to him from their magic that they were moving [like snakes].', 'Nabi Musa menjawab: “Bahkan kamulah campak dahulu”. Tiba-tiba tali-tali mereka dan tongkat-tongkat mereka terbayang-bayang kepadanya seolah-olah benda-benda berjalan, disebabkan sihir mereka.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 67, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ', 'فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُّوسَىٰ', NULL, 'And he sensed within himself apprehension, did Moses.', 'Maka yang demikian menjadikan Nabi Musa merasa takut sedikit dalam hatinya.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 68, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ الْأَعْلَىٰ', NULL, 'We [i.e., Allāh] said, "Fear not. Indeed, it is you who are superior.', 'Kami berfirman kepadanya: “Janganlah engkau takut (wahai Musa)! Sesungguhnya engkaulah yang tertinggi mengatasi mereka dengan kemenangan.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 69, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 'وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَىٰ', NULL, 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."', '“Dan campakkanlah apa yang ada di tangan kananmu, nescaya ia menelan segala (benda-benda sihir) yang mereka lakukan, kerana sesungguhnya apa yang mereka lakukan itu hanyalah tipu daya ahli sihir; sedang ahli sihir itu tidak akan beroleh kejayaan, di mana sahaja ia berada”.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 70, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', 'فَأُلْقِيَ السَّحَرَةُ سُجَّدًا قَالُوا آمَنَّا بِرَبِّ هَارُونَ وَمُوسَىٰ', NULL, 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."', '(Nabi Musa pun mencampakkan tongkatnya yang terus menelan segala benda sihir mereka), maka keadaan yang demikian menjadikan ahli-ahli sihir itu segera merebahkan diri sujud sambil berkata: “Kami beriman kepada Tuhan yang mengutus Nabi Harun dan Nabi Musa”.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 71, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ', 'قَالَ آمَنتُمْ لَهُ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ وَلَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَا أَشَدُّ عَذَابًا وَأَبْقَىٰ', NULL, '[Pharaoh] said, "You believed him [i.e., Moses] before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."', 'Firaun berkata: “Patutkah kamu beriman kepada Musa sebelum aku memberi izin kepada kamu? Sesungguhnya dia lah ketua kamu yang mengajar sihir kepada kamu. Oleh itu, demi sesungguhnya, aku akan memotong tangan dan kaki kamu dengan bersilang, dan aku akan memalang kamu pada batang-batang pohon tamar; dan demi sesungguhnya kamu akan mengetahui kelak siapakah di antara kita yang lebih keras azab seksanya dan lebih kekal”.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 72, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا فَٱقْضِ مَآ أَنتَ قَاضٍ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 'قَالُوا لَن نُّؤْثِرَكَ عَلَىٰ مَا جَاءَنَا مِنَ الْبَيِّنَاتِ وَالَّذِي فَطَرَنَا فَاقْضِ مَا أَنتَ قَاضٍ إِنَّمَا تَقْضِي هَٰذِهِ الْحَيَاةَ الدُّنْيَا', NULL, 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.', 'Mereka menjawab: “Kami tidak sekali-kali akan mengutamakanmu daripada apa yang telah datang kepada kami dari mukjizat-mukjizat yang terang nyata, dan (tidak akan mengutamakanmu daripada) Tuhan yang telah menjadikan kita semua. Oleh itu, hukumkanlah apa sahaja yang engkau hendak hukumkan, kerana sesungguhnya engkau hanyalah dapat menghukum dalam kehidupan dunia ini sahaja.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 73, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ', 'إِنَّا آمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَايَانَا وَمَا أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ وَاللَّهُ خَيْرٌ وَأَبْقَىٰ', NULL, 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allāh is better and more enduring."', '“Sesungguhnya kami telah beriman kepada Tuhan kami, supaya diampunkanNya kesalahan-kesalahan kami, dan dosa-dosa sihir yang engkau paksakan kami melakukannya. Dan Allah jualah yang lebih baik dan lebih kekal balasan pahalaNya.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 74, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'إِنَّهُ مَن يَأْتِ رَبَّهُ مُجْرِمًا فَإِنَّ لَهُ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', NULL, 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.', '“Sebenarnya sesiapa yang datang kepada Tuhannya pada hari akhirat sedang ia bersalah maka sesungguhnya adalah baginya neraka jahannam yang ia tidak mati di dalamnya dan tidak pula hidup.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 75, 'وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', 'وَمَن يَأْتِهِ مُؤْمِنًا قَدْ عَمِلَ الصَّالِحَاتِ فَأُولَٰئِكَ لَهُمُ الدَّرَجَاتُ الْعُلَىٰ', NULL, 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:', '“Dan sesiapa yang datang kepadaNya sedang ia beriman, serta ia telah mengerjakan amal-amal yang soleh, maka mereka itu akan beroleh tempat-tempat tinggal yang tinggi darjatnya:', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 76, 'جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', 'جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَٰلِكَ جَزَاءُ مَن تَزَكَّىٰ', NULL, 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.', '“(Iaitu) Syurga-syurga yang kekal, yang mengalir padanya beberapa sungai, mereka kekal di dalamnya; dan yang demikian itu ialah balasan orang-orang yang membersihkan dirinya dari perbuatan kufur dan maksiat”.', FALSE, NULL, NULL, 316, 16, 126, 272, FALSE, 0, NULL),
(20, 77, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَٰفُ دَرَكًا وَلَا تَخْشَىٰ', 'وَلَقَدْ أَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَسْرِ بِعِبَادِي فَاضْرِبْ لَهُمْ طَرِيقًا فِي الْبَحْرِ يَبَسًا لَّا تَخَافُ دَرَكًا وَلَا تَخْشَىٰ', NULL, 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."', 'Dan demi sesungguhnya! Kami telah wahyukan kepada Nabi Musa: “Hendaklah engkau membawa hamba-hambaKu (kaummu) keluar memgembara pada waktu malam, kemudian pukulah air laut dengan tongkatmu, untuk mengadakan jalan yang kering bagi mereka di laut itu; janganlah engkau menaruh bimbang daripada ditangkap oleh musuh, dan jangan pula engkau takut tenggelam”.', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 78, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ فَغَشِيَهُم مِّنَ الْيَمِّ مَا غَشِيَهُمْ', NULL, 'So Pharaoh pursued them with his soldiers, and there covered them from the sea that which covered them,', 'Maka Firaun pun mengejar mereka bersama-sama dengan tenteranya, lalu ia dan orang-orangnya diliputi oleh air laut yang menenggelamkan mereka semuanya dengan cara yang sedahsyat-dahsyatnya.', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 79, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَىٰ', NULL, 'And Pharaoh led his people astray and did not guide [them].', 'Dan dengan itu Firaun telah menjerumuskan kaumnya ke tempat kebinasaan, dan tidaklah ia membawa mereka ke jalan yang benar.', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 80, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 'يَا بَنِي إِسْرَائِيلَ قَدْ أَنجَيْنَاكُم مِّنْ عَدُوِّكُمْ وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ', NULL, 'O Children of Israel, We delivered you from your enemy, and We made an appointment with you at the right side of the mount, and We sent down to you manna and quails,', 'Wahai Bani lsrail! Sesungguhnya Kami telah selamatkan kamu dari musuh kamu, dan Kami telah janjikan kamu (dengan memberi wahyu kepada Nabi Musa) di sebelah kanan Gunung Tursina itu, dan kami turunkan kepada kamu “Mann” dan “Salwa”,', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 81, 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 'كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَلَا تَطْغَوْا فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي وَمَن يَحْلِلْ عَلَيْهِ غَضَبِي فَقَدْ هَوَىٰ', NULL, '[Saying], "Eat from the good things with which We have provided you and do not transgress [or oppress others] therein, lest My anger should descend upon you. And he upon whom My anger descends has certainly fallen [i.e., perished]."', 'Serta Kami katakan: Makanlah dari benda-benda yang baik yang Kami kurniakan kepada kamu, dan janganlah kamu melampaui batas padanya, kerana dengan yang demikian kamu akan ditimpa kemurkaanKu; dan sesiapa yang ditimpa kemurkaanKu, maka sesungguhnya binasalah ia.', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 82, 'وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا ثُمَّ ٱهْتَدَىٰ', 'وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَىٰ', NULL, 'But indeed, I am the Perpetual Forgiver of whoever repents and believes and does righteousness and then continues in guidance.', 'Dan sesungguhnya Aku yang amat memberi ampun kepada orang-orang yang bertaubat serta beriman dan beramal soleh, kemudian ia tetap teguh menurut petunjuk yang diberikan kepadanya.', FALSE, NULL, NULL, 317, 16, 126, 273, FALSE, 0, NULL),
(20, 83, 'وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', 'وَمَا أَعْجَلَكَ عَن قَوْمِكَ يَا مُوسَىٰ', NULL, '[Allāh said], "And what made you hasten from your people, O Moses?"', 'Dan apakah yang menyebabkan engkau segera datang ke mari lebih dahulu dari kaum engkau wahai Musa?.', FALSE, NULL, NULL, 317, 16, 127, 273, FALSE, 0, NULL),
(20, 84, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 'قَالَ هُمْ أُولَاءِ عَلَىٰ أَثَرِي وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', NULL, 'He said, "They are close upon my tracks, and I hastened to You, my Lord, that You be pleased."', 'Nabi Musa menjawab: “Mereka itu ada mengiringi daku tidak jauh dari sini; dan aku segera datang kepadaMu, wahai Tuhanku, supaya Engkau reda akan daku”.', FALSE, NULL, NULL, 317, 16, 127, 273, FALSE, 0, NULL),
(20, 85, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِن بَعْدِكَ وَأَضَلَّهُمُ السَّامِرِيُّ', NULL, '[Allāh] said, "But indeed, We have tried your people after you [departed], and the Sāmirī has led them astray."', '(Setelah selesainya urusan itu) maka Allah berfirman kepada Nabi Musa: “Sesungguhnya Kami telah mengenakan kaummu satu fitnah ujian sepeninggalanmu, dan mereka telah disesatkan oleh Samiri”', FALSE, NULL, NULL, 317, 16, 127, 273, FALSE, 0, NULL),
(20, 86, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', 'فَرَجَعَ مُوسَىٰ إِلَىٰ قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ يَا قَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ الْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِي', NULL, 'So Moses returned to his people, angry and grieved. He said, "O my people, did your Lord not make you a good promise? Then, was the time [of its fulfillment] too long for you, or did you wish that wrath from your Lord descend upon you, so you broke your promise [of obedience] to me?"', 'Maka kembalilah Nabi Musa kepada kaumnya dengan perasaan marah dan dukacita; ia berkata: “Wahai kaumku! Bukankah Tuhan kamu telah menjanjikan kamu dengan satu perjanjian yang baik? Patutkah kamu merasa panjang masa pemergianku menerima apa yang dijanjikan itu? Atau kamu sengaja menghendaki supaya kamu ditimpa kemurkaan dari Tuhan kamu, lalu kamu menyalahi perjanjian kamu denganku?”', FALSE, NULL, NULL, 317, 16, 127, 273, FALSE, 0, NULL),
(20, 87, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', 'قَالُوا مَا أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَا أَوْزَارًا مِّن زِينَةِ الْقَوْمِ فَقَذَفْنَاهَا فَكَذَٰلِكَ أَلْقَى السَّامِرِيُّ', NULL, 'They said, "We did not break our promise to you by our will, but we were made to carry burdens from the ornaments of the people [of Pharaoh], so we threw them [into the fire], and thus did the Sāmirī throw."', 'Mereka menjawab: “Kami tidak menyalahi janji kami kepadamu itu dengan kuasa dan ikhtiar kami, tetapi kami telah dibebankan membawa barang-barang perhiasan orang-orang (Mesir) itu, supaya kami mencampakkannya ke dalam api lalu kami melakukan yang demikian, maka demikianlah juga “Samiri” mencampakkan apa yang dibawanya.', FALSE, NULL, NULL, 317, 16, 127, 273, FALSE, 0, NULL),
(20, 88, 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُ خُوَارٌ فَقَالُوا هَٰذَا إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ', NULL, 'And he extracted for them [the statue of] a calf which had a lowing sound, and they said, "This is your god and the god of Moses, but he forgot."', '“Kemudian Samiri mengeluarkan untuk mereka dari leburan barang-barang itu (patung) seekor anak lembu yang bertubuh lagi bersuara, lalu mereka berkata: “Ini ialah tuhan kamu dan tuhan bagi Musa, tetapi Musa telah lupa!”', FALSE, NULL, NULL, 318, 16, 127, 273, FALSE, 0, NULL),
(20, 89, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', NULL, 'Did they not see that it could not return to them any speech [i.e., response] and that it did not possess for them any harm or benefit?', 'Patutkah mereka tidak mahu berfikir sehingga mereka tidak nampak bahawa patung itu tidak dapat menjawab perkataan mereka, dan tidak berkuasa mendatangkan bahaya atau memberi manfaat kepada mereka?', FALSE, NULL, NULL, 318, 16, 127, 273, FALSE, 0, NULL),
(20, 90, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', 'وَلَقَدْ قَالَ لَهُمْ هَارُونُ مِن قَبْلُ يَا قَوْمِ إِنَّمَا فُتِنتُم بِهِ وَإِنَّ رَبَّكُمُ الرَّحْمَٰنُ فَاتَّبِعُونِي وَأَطِيعُوا أَمْرِي', NULL, 'And Aaron had already told them before [the return of Moses], "O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order."', 'Dan demi sesungguhnya, Nabi Harun telahpun berkata kepada mereka sebelum itu: “Wahai kaumku, sesungguhnya kamu hanya diperdayakan dengan patung itu, dan sesungguhnya Tuhan kamu ialah Allah yang melimpah-limpah rahmatNya; oleh itu, ikutlah daku dan taatlah akan perintahku”.', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 91, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 'قَالُوا لَن نَّبْرَحَ عَلَيْهِ عَاكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', NULL, 'They said, "We will never cease being devoted to it [i.e., the calf] until Moses returns to us."', 'Mereka menjawab: “Kami tidak sekali-kali akan meninggalkan penyembahan patung ini, (bahkan) kami akan tetap menyembahnya hingga Nabi Musa kembali kepada kami”.', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 92, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', 'قَالَ يَا هَارُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا', NULL, '[Moses] said, "O Aaron, what prevented you, when you saw them going astray,', '(Sekembalinya), Nabi Musa berkata: “Wahai Harun, apakah maniknya yang menghalangmu ketika engkau melihat mereka sesat,', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 93, 'أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِى', 'أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِي', NULL, 'From following me? Then have you disobeyed my order?"', '“Daripada menurutku? Adakah engkau ingkar akan suruhanku?”', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 94, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 'قَالَ يَا ابْنَ أُمَّ لَا تَأْخُذْ بِلِحْيَتِي وَلَا بِرَأْسِي إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِي إِسْرَائِيلَ وَلَمْ تَرْقُبْ قَوْلِي', NULL, '[Aaron] said, "O son of my mother, do not seize [me] by my beard or by my head. Indeed, I feared that you would say, ''You caused division among the Children of Israel, and you did not observe [or await] my word.''"', 'Nabi Harun menjawab: “Wahai anak ibuku! Janganlah engkau meragut janggutku dan janganlah menarik (rambut) kepalaku. Sesungguhnya aku takut bahawa engkau akan berkata kepadaku: ‘Engkau telah memecah-belahkan kaum Bani lsrail sesama sendiri, dan engkau tidak berhati-hati mengambil berat pesananku!’”', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 95, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', 'قَالَ فَمَا خَطْبُكَ يَا سَامِرِيُّ', NULL, '[Moses] said, "And what is your case, O Sāmirī?"', '(Sesudah itu Nabi Musa hadapkan kemarahannya kepada Samiri lalu) bertanya: “Apa pula halmu, wahai Samiri?”', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 96, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِهِ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ الرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِي نَفْسِي', NULL, 'He said, "I saw what they did not see, so I took a handful [of dust] from the track of the messenger and threw it, and thus did my soul entice me."', 'Ia menjawab: “Aku mengetahui dan menyedari apa yang tidak diketahui oleh mereka, lalu aku mengambil segenggam dari kesan jejak Rasul itu, kemudian aku mencampakkannya; dan demikianlah aku dihasut oleh hawa nafsuku”.', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 97, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', 'قَالَ فَاذْهَبْ فَإِنَّ لَكَ فِي الْحَيَاةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُ وَانظُرْ إِلَىٰ إِلَٰهِكَ الَّذِي ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُ ثُمَّ لَنَنسِفَنَّهُ فِي الْيَمِّ نَسْفًا', NULL, '[Moses] said, "Then go. And indeed, it is [decreed] for you in [this] life to say, ''No contact.'' And indeed, you have an appointment [in the Hereafter] you will not fail to keep. And look at your ''god'' to which you remained devoted. We will surely burn it and blow it [i.e., its ashes] into the sea with a blast.', 'Nabi Musa berkata kepada Samiri: “Jika demikian, pergilah, (engkau adalah diusir dan dipulaukan), kerana sesungguhnya telah ditetapkan bagimu akan berkata dalam kehidupan dunia ini: ‘Jangan sentuh daku’, dan sesungguhnya telah dijanjikan lagi untukmu satu balasan akhirat yang engkau tidak sekali-kali akan terlepas daripadanya. Dan (sekarang) lihatlah kepada tuhanmu yang engkau sekian lama menyembahnya, sesungguhnya kami akan membakarnya kemudian kami akan menghancur dan menaburkan serbuknya di laut sehingga hilang lenyap.', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 98, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْمًا', 'إِنَّمَا إِلَٰهُكُمُ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَيْءٍ عِلْمًا', NULL, 'Your god is only Allāh, except for whom there is no deity. He has encompassed all things in knowledge."', '“Sesungguhnya Tuhan kamu hanya Allah, yang tidak ada Tuhan melainkan Dia, yang meliputi pengetahuanNya akan tiap-tiap sesuatu”.', FALSE, NULL, NULL, 318, 16, 127, 274, FALSE, 0, NULL),
(20, 99, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًا', 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنبَاءِ مَا قَدْ سَبَقَ وَقَدْ آتَيْنَاكَ مِن لَّدُنَّا ذِكْرًا', NULL, 'Thus, [O Muḥammad], We relate to you from the news of what has preceded. And We have certainly given you from Us a message [i.e., the Qur’ān].', 'Demikianlah Kami ceritakan kepadamu (wahai Muhammad), sebahagian dari kisah-kisah umat manusia yang telah lalu; dan sesungguhnya Kami telah memberikan kepadamu, dari sisi Kami (sebuah Kitab Al-Quran yang menjadi) peringatan.', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 100, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا', NULL, 'Whoever turns away from it - then indeed, he will bear on the Day of Resurrection a burden [i.e., great sin],', 'Sesiapa yang berpaling ingkar dari peringatan Al-Quran itu, maka sesungguhnya ia pada hari kiamat menanggung beban (dosa) yang berat.', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 101, 'خَٰلِدِينَ فِيهِ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًا', 'خَالِدِينَ فِيهِ وَسَاءَ لَهُمْ يَوْمَ الْقِيَامَةِ حِمْلًا', NULL, '[Abiding] eternally therein, and evil it is for them on the Day of Resurrection as a load -', 'Mereka kekal di dalam (azab) dosa itu; dan amatlah buruknya tanggungan itu bagi mereka pada hari kiamat,', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 102, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', 'يَوْمَ يُنفَخُ فِي الصُّورِ وَنَحْشُرُ الْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', NULL, 'The Day the Horn will be blown. And We will gather the criminals, that Day, blue-eyed.', '(Iaitu) hari ditiup Sangkakala, dan Kami akan himpunkan pada hari itu orang-orang yang bersalah dalam keadaan kelabu matanya.', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 103, 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', 'يَتَخَافَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', NULL, 'They will murmur among themselves, "You remained not but ten [days in the world]."', 'Mereka berbisik-bisik sesama sendiri: “Kamu telah tinggal hanya sepuluh sahaja”.', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 104, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', NULL, 'We are most knowing of what they say when the best of them in manner [i.e., wisdom or speech] will say, "You remained not but one day."', '(Allah berfirman): Kami lebih mengetahui akan kadar masa yang mereka katakan itu, manakala orang yang lebih tepat pendapatnya di antara mereka berkata pula: “Tiadalah kamu tinggal melainkan satu masa yang amat singkat”.', FALSE, NULL, NULL, 319, 16, 127, 274, FALSE, 0, NULL),
(20, 105, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا', 'وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّي نَسْفًا', NULL, 'And they ask you about the mountains, so say, "My Lord will blow them away with a blast.', 'Dan mereka (yang kafir) bertanya kepadamu (wahai Muhammad) dari hal gunung-ganang; maka jawablah: “Tuhanku akan menghancurkannya menjadi debu ditiup angin.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 106, 'فَيَذَرُهَا قَاعًا صَفْصَفًا', 'فَيَذَرُهَا قَاعًا صَفْصَفًا', NULL, 'And He will leave it [i.e., the earth] a level plain;', '“Lalu Ia membiarkan tapak gunung-gunung itu (di bumi) rata lagi licin”.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 107, 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا', 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَا أَمْتًا', NULL, 'You will not see therein a depression or an elevation."', 'Engkau tidak akan melihat pada tapaknya itu tempat yang rendah atau yang tinggi.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 108, 'يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', 'يَوْمَئِذٍ يَتَّبِعُونَ الدَّاعِيَ لَا عِوَجَ لَهُ وَخَشَعَتِ الْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', NULL, 'That Day, they [i.e., everyone] will follow [the call of] the Caller [with] no deviation therefrom, and [all] voices will be stilled before the Most Merciful, so you will not hear except a whisper [of footsteps].', 'Pada hari itu mereka menurut seruan panggilan yang menyeru mereka dengan tidak dapat melencong dari menurutnya; dan diam khusyuklah segala suara kepada Allah yang melimpah-limpah rahmatNya sehingga engkau tidak mendengar melainkan bunyi yang amat perlahan.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 109, 'يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًا', 'يَوْمَئِذٍ لَّا تَنفَعُ الشَّفَاعَةُ إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمَٰنُ وَرَضِيَ لَهُ قَوْلًا', NULL, 'That Day, no intercession will benefit except [that of] one to whom the Most Merciful has given permission and has accepted his word.', 'Pada hari itu, tidak berfaedah syafaat (dari dan kepada sesiapapun) kecuali dari orang yang diizinkan oleh Allah yang melimpah-limpah rahmatNya, dan kepada orang yang diredai perkataannya.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 110, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِ عِلْمًا', NULL, 'He [i.e., Allāh] knows what is [presently] before them and what will be after them, but they do not encompass it [i.e., what He knows] in knowledge.', 'Allah mengetahui apa yang di hadapan mereka (dari hal-hal dunia), dan apa yang di belakang mereka (dari perkara akhirat); sedang mereka tidak mengetahuinya secara meliputi.', FALSE, NULL, NULL, 319, 16, 127, 275, FALSE, 0, NULL),
(20, 111, 'وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', 'وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', NULL, 'And [all] faces will be humbled before the Ever-Living, the Self-Sustaining. And he will have failed who carries injustice.', 'Dan segala muka akan tunduk dengan berupa hina kepada Allah Yang Tetap Hidup, lagi Yang Kekal Mentadbirkan makhluk selama-lamanya; dan sesungguhnya telah rugi dan hampalah orang yang menanggung dosa kezaliman.', FALSE, NULL, NULL, 319, 16, 128, 275, FALSE, 0, NULL),
(20, 112, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', 'وَمَن يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', NULL, 'But he who does of righteous deeds while he is a believer - he will neither fear injustice nor deprivation.', 'Dan sesiapa yang mengerjakan sebarang apa dari amal-amal yang soleh, sedang ia beriman, maka tidaklah (seharusnya) ia merasa takut dianiaya atau dikurangkan sedikitpun dari pahalanya.', FALSE, NULL, NULL, 319, 16, 128, 275, FALSE, 0, NULL),
(20, 113, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', 'وَكَذَٰلِكَ أَنزَلْنَاهُ قُرْآنًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ الْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', NULL, 'And thus We have sent it down as an Arabic Qur’ān and have diversified therein the warnings that perhaps they will avoid [sin] or it would cause them remembrance.', 'Dan demikianlah Kami telah menurunkan Al-Quran sebagai bacaan dalam bahasa Arab, dan kami telah terangkan di dalamnya berbagai-bagai amaran supaya mereka (umat manusia seluruhnya) bertaqwa, atau mereka mendapat daripadanya sesuatu peringatan dari faedah mereka.', FALSE, NULL, NULL, 319, 16, 128, 275, FALSE, 0, NULL),
(20, 114, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ وَقُل رَّبِّ زِدْنِى عِلْمًا', 'فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ وَلَا تَعْجَلْ بِالْقُرْآنِ مِن قَبْلِ أَن يُقْضَىٰ إِلَيْكَ وَحْيُهُ وَقُل رَّبِّ زِدْنِي عِلْمًا', NULL, 'So high [above all] is Allāh, the Sovereign, the Truth. And, [O Muḥammad], do not hasten with [recitation of] the Qur’ān before its revelation is completed to you, and say, "My Lord, increase me in knowledge."', 'Maka Maha Tinggilah Allah, yang Menguasai seluruh alam, lagi Yang Benar (pada segala-galanya). Dan janganlah engkau (wahai Muhammad) tergesa-gesa membaca Al-Quran sebelum selesai dibacakan oleh Jibril kepadamu, dan berdoalah dengan berkata: “Wahai Tuhanku, tambahilah ilmuku”.', FALSE, NULL, NULL, 320, 16, 128, 275, FALSE, 0, NULL),
(20, 115, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا', 'وَلَقَدْ عَهِدْنَا إِلَىٰ آدَمَ مِن قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُ عَزْمًا', NULL, 'And We had already taken a promise from Adam before, but he forgot; and We found not in him determination.', 'Dan demi sesungguhnya, Kami telah berpesan kepada Adam pada masa yang lalu, tetapi ia lupa; dan kami tidak mendapatinya mempunyai keazaman yang teguh.', FALSE, NULL, NULL, 320, 16, 128, 275, FALSE, 0, NULL),
(20, 116, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', 'وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَىٰ', NULL, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except Iblees; he refused.', 'Dan (ingatkanlah peristiwa) ketika Kami berfirman kepada malaikat: “Sujudlah kamu kepada Adam”, lalu mereka sujud, melainkan Iblis, ia enggan sujud.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 117, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', 'فَقُلْنَا يَا آدَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَىٰ', NULL, 'So We said, "O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer.', 'Maka, Kami berfirman: “Wahai Adam sesungguhnya Iblis ini musuh bagimu dan bagi isterimu; oleh itu, janganlah ia menyebabkan kamu berdua keluar dari Syurga, kerana dengan yang demikian engkau (dan isterimu) akan menderita.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 118, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', NULL, 'Indeed, it is [promised] for you not to be hungry therein or be unclothed.', '“Sesungguhnya telah dikurniakan berbagai nikmat bagimu, bahawa engkau tidak akan lapar dalam Syurga itu dan tidak akan bertelanjang.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 119, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', 'وَأَنَّكَ لَا تَظْمَأُ فِيهَا وَلَا تَضْحَىٰ', NULL, 'And indeed, you will not be thirsty therein or be hot from the sun."', '“Dan sesungguhnya engkau juga tidak akan dahaga dalam Syurga itu, dan tidak akan merasa panas matahari”.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 120, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', 'فَوَسْوَسَ إِلَيْهِ الشَّيْطَانُ قَالَ يَا آدَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ الْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', NULL, 'Then Satan whispered to him; he said, "O Adam, shall I direct you to the tree of eternity and possession that will not deteriorate?"', 'Setelah itu maka Syaitan membisikkan (hasutan) kepadanya, dengan berkata: “Wahai Adam, mahukah, aku tunjukkan kepadamu pohon yang menyebabkan hidup selama-lamanya, dan kekuasaan yang tidak akan hilang lenyap?”', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 121, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ وَعَصَىٰ آدَمُ رَبَّهُ فَغَوَىٰ', NULL, 'And they [i.e., Adam and his wife] ate of it, and their private parts became apparent to them, and they began to fasten over themselves from the leaves of Paradise. And Adam disobeyed his Lord and erred.', 'Kemudian mereka berdua memakan dari pohon itu, lalu terdedahlah kepada mereka aurat masing-masing, dan mereka mulailah menutupnya dengan daun-daun dari Syurga; dan dengan itu derhakalah Adam kepada Tuhannya, lalu tersalah jalan (dari mencapai hajatnya).', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 122, 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 'ثُمَّ اجْتَبَاهُ رَبُّهُ فَتَابَ عَلَيْهِ وَهَدَىٰ', NULL, 'Then his Lord chose him and turned to him in forgiveness and guided [him].', 'Kemudian Tuhannya memilihnya (dengan diberi taufiq untuk bertaubat), lalu Allah menerima taubatnya serta diberi petunjuk.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 123, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 'قَالَ اهْبِطَا مِنْهَا جَمِيعًا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّي هُدًى فَمَنِ اتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', NULL, '[Allāh] said, "Descend from it [i.e., Paradise] - all, [your descendants] being enemies to one another. And if there should come to you guidance from Me - then whoever follows My guidance will neither go astray [in the world] nor suffer [in the Hereafter].', 'Allah berfirman: “Turunlah kamu berdua dari Syurga itu, bersama-sama, dalam keadaan setengah kamu menjadi musuh bagi setengahnya yang lain; kemudian jika datang kepada kamu petunjuk dariKu, maka sesiapa yang mengikut petunjukKu itu nescaya ia tidak akan sesat dan ia pula tidak akan menderita azab sengsara.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 124, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 'وَمَنْ أَعْرَضَ عَن ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنكًا وَنَحْشُرُهُ يَوْمَ الْقِيَامَةِ أَعْمَىٰ', NULL, 'And whoever turns away from My remembrance - indeed, he will have a depressed [i.e., difficult] life, and We will gather [i.e., raise] him on the Day of Resurrection blind."', '“Dan sesiapa yang berpaling ingkar dari ingatan dan petunjukKu, maka sesungguhnya adalah baginya kehidupan yang sempit, dan Kami akan himpunkan dia pada hari kiamat dalam keadaan buta”.', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 125, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', 'قَالَ رَبِّ لِمَ حَشَرْتَنِي أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', NULL, 'He will say, "My Lord, why have you raised me blind while I was [once] seeing?"', 'Ia berkata: “Wahai Tuhanku, mengapa Engkau himpunkan daku dalam keadaan buta, padahal aku dahulu melihat?”', FALSE, NULL, NULL, 320, 16, 128, 276, FALSE, 0, NULL),
(20, 126, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', 'قَالَ كَذَٰلِكَ أَتَتْكَ آيَاتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ الْيَوْمَ تُنسَىٰ', NULL, '[Allāh] will say, "Thus did Our signs come to you, and you forgot [i.e., disregarded] them; and thus will you this Day be forgotten."', 'Allah berfirman: “Demikianlah keadaannya! Telah datang ayat-ayat keterangan Kami kepadamu, lalu engkau melupakan serta meninggalkannya, dan demikianlah engkau pada hari ini dilupakan serta ditinggalkan”.', FALSE, NULL, NULL, 321, 16, 128, 276, FALSE, 0, NULL),
(20, 127, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 'وَكَذَٰلِكَ نَجْزِي مَنْ أَسْرَفَ وَلَمْ يُؤْمِن بِآيَاتِ رَبِّهِ وَلَعَذَابُ الْآخِرَةِ أَشَدُّ وَأَبْقَىٰ', NULL, 'And thus do We recompense he who transgressed and did not believe in the signs of his Lord. And the punishment of the Hereafter is more severe and more enduring.', 'Dan demikianlah Kami membalas orang yang melampaui batas dan tidak beriman kepada ayat-ayat keterangan Tuhannya; dan demi sesungguhnya azab akhirat itu lebih berat dan lebih kekal.', FALSE, NULL, NULL, 321, 16, 128, 276, FALSE, 0, NULL),
(20, 128, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّأُولِي النُّهَىٰ', NULL, 'Then, has it not become clear to them how many generations We destroyed before them as they walk among their dwellings? Indeed in that are signs for those of intelligence.', 'Adakah tersembunyi serta belum jelas lagi kepada mereka: berapa banyak Kami telah binasakan dari kamu-kaum yang terdahulu daripada mereka, sedang mereka sekarang berulang-alik melalui tempat-tempat tinggal kaum-kaum itu? Sesungguhnya pada yang demikian ada tanda-tanda (untuk mengambil iktibar) bagi orang-orang yang berakal fikiran.', FALSE, NULL, NULL, 321, 16, 128, 276, FALSE, 0, NULL),
(20, 129, 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', NULL, 'And if not for a word that preceded from your Lord, it [i.e., punishment] would have been an obligation [due immediately], and [if not for] a specified term [decreed].', 'Dan jika tidaklah kerana telah terdahulu Kalimah Tuhanmu (wahai Muhammad), dan satu tempoh yang ditentukan nescaya balasan jenayah mereka sudah semestinya berlaku.', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 130, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', 'فَاصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ آنَاءِ اللَّيْلِ فَسَبِّحْ وَأَطْرَافَ النَّهَارِ لَعَلَّكَ تَرْضَىٰ', NULL, 'So be patient over what they say and exalt [Allāh] with praise of your Lord before the rising of the sun and before its setting; and during periods of the night [exalt Him] and at the ends of the day, that you may be satisfied.', 'Oleh itu, bersabarlah engkau (wahai Muhammad) akan apa yang mereka katakan, dan beribadatlah dengan memuji Tuhanmu sebelum matahari terbit dan sebelum terbenamnya; dan beribadatlah pada saat-saat dari waktu malam dan pada sebelah-sebelah siang; supaya engkau reda (dengan mendapat sebaik-baik balasan).', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 131, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ زَهْرَةَ الْحَيَاةِ الدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', NULL, 'And do not extend your eyes toward that by which We have given enjoyment to [some] categories of them, [its being but] the splendor of worldly life by which We test them. And the provision of your Lord is better and more enduring.', 'Dan janganlah engkau menujukan pandangan kedua matamu dengan keinginan kepada apa yang telah Kami berikan kepada beberapa golongan dari mereka yang kafir itu menikmatinya, yang merupakan keindahan kehidupan dunia ini, untuk Kami menguji mereka padanya; sedang limpah kurnia Tuhanmu di akhirat lebih baik dan lebih kekal.', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 132, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا لَا نَسْـَٔلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 'وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَىٰ', NULL, 'And enjoin prayer upon your family [and people] and be steadfast therein. We ask you not for provision; We provide for you, and the [best] outcome is for [those of] righteousness.', 'Dan perintahkanlah keluargamu serta umatmu mengerjakan sembahyang, dan hendaklah engkau tekun bersabar menunaikannya. Kami tidak meminta rezeki kepadamu, (bahkan) Kamilah yang memberi rezeki kepadamu. Dan (ingatlah) kesudahan yang baik adalah bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 133, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'وَقَالُوا لَوْلَا يَأْتِينَا بِآيَةٍ مِّن رَّبِّهِ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِي الصُّحُفِ الْأُولَىٰ', NULL, 'And they say, "Why does he not bring us a sign from his Lord?" Has there not come to them evidence of what was in the former scriptures?', 'Dan mereka yang kafir berkata: “Mengapa ia tidak membawa kepada kami satu tanda mukjizat dari Tuhannya yang membuktikan kebenarannya?” Bukankah telah datang kepada mereka berbagai-bagai keterangan dan khasnya Al-Quran yang menjadi kenyataan yang menerangkan apa yang terkandung dalam Kitab-kitab yang dahulu?', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 134, 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 'وَلَوْ أَنَّا أَهْلَكْنَاهُم بِعَذَابٍ مِّن قَبْلِهِ لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', NULL, 'And if We had destroyed them with a punishment before him, they would have said, "Our Lord, why did You not send to us a messenger so we could have followed Your verses [i.e., teachings] before we were humiliated and disgraced?"', 'Dan sekiranya Kami binasakan mereka dengan sesuatu azab sebelum datangnya Rasul Kami membawa Al-Quran ini, tentulah mereka akan berkata pada hari kiamat: “Wahai Tuhan Kami! Mengapa Engkau tidak mengutuskan kepada kami seorang Rasul supaya kami menurut ayat-ayat keteranganMu yang dibawanya, sebelum kami menjadi hina (dengan azab di dunia), dan mendapat malu (dengan azab di akhirat)?”', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(20, 135, 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا فَسَتَعْلَمُونَ مَنْ أَصْحَابُ الصِّرَاطِ السَّوِيِّ وَمَنِ اهْتَدَىٰ', NULL, 'Say, "Each [of us] is waiting; so wait. For you will know who are the companions of the sound path and who is guided."', 'Katakanlah (wahai Muhammad): “Tiap-tiap seorang (di antara kita) sedang menunggu; maka tunggulah kamu! Kemudian kamu akan mengetahui kelak siapakah orang-orang yang berada atas jalan yang lurus, dan juga siapa yang mendapat petunjuk”.', FALSE, NULL, NULL, 321, 16, 128, 277, FALSE, 0, NULL),
(21, 1, 'ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ', 'اقترب للناس حسابهم وهم في غفلة معرضون', NULL, '[The time of] their account has approached for the people, while they are in heedlessness turning away.', 'Telah hampir datangnya kepada manusia hari perhitungan amalnya sedang mereka dalam kelalaian, tidak hiraukan persediaan baginya.', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 7, NULL),
(21, 2, 'مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون', NULL, 'No mention [i.e., revelation] comes to them anew from their Lord except that they listen to it while they are at play', 'Tidak datang kepada mereka itu sebarang peringatan yang diturunkan dari Tuhan mereka lepas satu: satu, melainkan mereka memasang telinga mendengarnya sambil mereka mempermain-mainkannya -', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 11, NULL),
(21, 3, 'لَاهِيَةً قُلُوبُهُمْ ۗ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَـٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ ۖ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', 'لاهية قلوبهم واسروا النجوى الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون', NULL, 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"', 'Dengan keadaan hati mereka leka daripada memahami dan mengamalkan maksudnya. Dan orang-orang yang zalim itu, berbisik-bisik sesama sendiri dengan berkata: “Bukankah (Muhammad) ini hanyalah seorang manusia biasa seperti kamu? Maka patutkah kamu turut hadir mendengar sihir yang dibawanya itu sedang kamu nampak dan mengetahui karutnya?”', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 15, NULL),
(21, 4, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'قال ربي يعلم القول في السماء والارض وهو السميع العليم', NULL, 'He [the Prophet (ﷺ)] said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."', '(Bagi menjawab mereka, Nabi Muhammad) berkata: “Tuhanku mengetahui tiap-tiap perkataan (yang dilahirkan atau disembunyikan oleh makhluk-makhluk) di langit dan di bumi; dan Dia lah jua yang Maha Mendengar, lagi Maha Mengetahui”.', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 10, NULL),
(21, 5, 'بَلْ قَالُوٓا۟ أَضْغَـٰثُ أَحْلَـٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', 'بل قالوا اضغاث احلام بل افتراه بل هو شاعر فلياتنا باية كما ارسل الاولون', NULL, 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."', '(Mereka bukan sahaja menyifatkan Al-Quran itu sihir) bahkan mereka menuduh dengan berkata: “Al-Quran itu perkara karut yang dimimpikan oleh Muhammad, bahkan perkara yang diada-adakan olehnya, bahkan Muhammad sendiri seorang penyair. (Kalaulah ia sebenarnya seorang Rasul) maka hendaklah ia membawa kepada kita satu mukjizat sebagaimana mukjizat-mukjizat yang dibawa oleh Rasul-rasul yang telah diutus dahulu”.', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 14, NULL),
(21, 6, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَآ ۖ أَفَهُمْ يُؤْمِنُونَ', 'ما امنت قبلهم من قرية اهلكناها افهم يؤمنون', NULL, 'Not a [single] city which We destroyed believed before them, so will they believe?', 'Tidak ada penduduk sesebuah negeri pun yang Kami binasakan sebelum mereka, yang telah beriman kepada mukjizat yang diberi kepadanya; maka benarkah mereka yang meminta mukjizat itu mahu beriman?', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 8, NULL),
(21, 7, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ ۖ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'وما ارسلنا قبلك الا رجالا نوحي اليهم فاسالوا اهل الذكر ان كنتم لا تعلمون', NULL, 'And We sent not before you, [O Muḥammad], except men to whom We revealed [the message], so ask the people of the message [i.e., former scriptures] if you do not know.', 'Dan Kami tidak mengutus Rasul-rasul sebelummu (wahai Muhammad) melainkan orang-orang lelaki yang Kami wahyukan kepada mereka (bukan malaikat); maka bertanyalah kamu kepada AhluzZikri” jika kamu tidak mengetahui.', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 14, NULL),
(21, 8, 'وَمَا جَعَلْنَـٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَـٰلِدِينَ', 'وما جعلناهم جسدا لا ياكلون الطعام وما كانوا خالدين', NULL, 'And We did not make them [i.e., the prophets] forms not eating food, nor were they immortal [on earth].', 'Dan Kami tidak menjadikan Rasul-rasul itu bertubuh badan yang tidak makan minum, dan mereka pula tidak akan kekal hidup selama-lamanya (di dunia).', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 9, NULL),
(21, 9, 'ثُمَّ صَدَقْنَـٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَـٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', 'ثم صدقناهم الوعد فانجيناهم ومن نشاء واهلكنا المسرفين', NULL, 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.', 'Kemudian Kami tepati janji Kami kepada mereka, lalu Kami selamatkan mereka dan sesiapa yang Kami kehendaki, dan (sebaliknya) Kami binasakan orang-orang yang melampaui batas.', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 8, NULL),
(21, 10, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَـٰبًا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ', 'لقد انزلنا اليكم كتابا فيه ذكركم افلا تعقلون', NULL, 'We have certainly sent down to you a Book [i.e., the Qur’ān] in which is your mention. Then will you not reason?', 'Sesungguhnya Kami telah menurunkan kepada kamu sebuah Kitab (Al-Quran) yang mengandungi perkara yang menimbulkan sebutan baik dan kelebihan untuk kamu, maka mengapa kamu tidak memahaminya (dan bersyukur akan nikmat yang besar itu)?', FALSE, NULL, NULL, 322, 17, 129, 278, FALSE, 8, NULL),
(21, 11, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 'وكم قصمنا من قرية كانت ظالمة وانشانا بعدها قوما اخرين', NULL, 'And how many a city which was unjust have We shattered and produced after it another people.', 'Dan berapa banyak Kami telah pecah-belahkan dan binasakan penduduk negeri yang melakukan kezaliman, dan Kami telah menjadikan sesudah mereka, kaum yang lain sebagai gantinya.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 10, NULL),
(21, 12, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', 'فلما احسوا باسنا اذا هم منها يركضون', NULL, 'And when they [i.e., its inhabitants] perceived Our punishment, at once they fled from it.', 'Maka ketika mereka merasai (kedatangan) azab Kami, mereka dengan serta-merta lari keluar dari negeri itu.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 7, NULL),
(21, 13, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَـٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', 'لا تركضوا وارجعوا الى ما اترفتم فيه ومساكنكم لعلكم تسالون', NULL, '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."', '(Lalu dikatakan kepada mereka): “Janganlah kamu lari, dan sebaliknya kembalilah kepada kemewahan hidup yang telah diberikan kepada kamu, dan ke tempat-tempat tinggal kamu, supaya kamu dapat ditanya mengenai apa yang berlaku”.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 10, NULL),
(21, 14, 'قَالُوا۟ يَـٰوَيْلَنَآ إِنَّا كُنَّا ظَـٰلِمِينَ', 'قالوا يا ويلنا انا كنا ظالمين', NULL, 'They said, "O woe to us! Indeed, we were wrongdoers."', '(Akhirnya) mereka berkata: “Aduhai celakanya kami! Sesungguhnya kami adalah orang-orang yang berlaku zalim!”', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 5, NULL),
(21, 15, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَـٰهُمْ حَصِيدًا خَـٰمِدِينَ', 'فما زالت تلك دعواهم حتى جعلناهم حصيدا خامدين', NULL, 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].', 'Maka demikianlah seterusnya jeritan dan keluhan mereka, sehingga Kami jadikan mereka hancur lebur dan sunyi-sepi.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 8, NULL),
(21, 16, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَـٰعِبِينَ', 'وما خلقنا السماء والارض وما بينهما لاعبين', NULL, 'And We did not create the heaven and earth and that between them in play.', 'Dan (ingatlah) tidaklah Kami menciptakan langit dan bumi serta segala yang ada di antaranya, secara main-main.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 7, NULL),
(21, 17, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَـٰهُ مِن لَّدُنَّآ إِن كُنَّا فَـٰعِلِينَ', 'لو اردنا ان نتخذ لهوا لاتخذناه من لدنا ان كنا فاعلين', NULL, 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.', 'Sekiranya Kami hendak mengambil sesuatu untuk hiburan, tentulah Kami akan mengambilnya dari sisi Kami; Kami tidak melakukannya.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 11, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(21, 18, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَـٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ ۚ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 'بل نقذف بالحق على الباطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون', NULL, 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.', 'Bahkan Kami sentiasa mengarahkan yang benar menentang yang salah, lalu ia menghancurkannya, maka dengan serta-merta hilang lenyaplah dia. Dan (tetaplah) kecelakaan akan menimpa kamu disebabkan apa yang kamu sifatkan (terhadap Kami).', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 13, NULL),
(21, 19, 'وَلَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', 'وله من في السماوات والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون', NULL, 'To Him belongs whoever is in the heavens and the earth. And those near Him [i.e., the angels] are not prevented by arrogance from His worship, nor do they tire.', 'Dan (ingatlah) segala yang ada di langit dan di bumi adalah milik kepunyaan Allah jua; dan malaikat-malaikat yang ada di sisiNya tidak membesarkan diri dan tidak enggan daripada beribadat kepadaNya, dan tidak pula mereka merasa penat dan letih.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 13, NULL),
(21, 20, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', 'يسبحون الليل والنهار لا يفترون', NULL, 'They exalt [Him] night and day [and] do not slacken.', 'Mereka beribadat malam dan siang, dengan tidak berhenti-henti.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 5, NULL),
(21, 21, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 'أَمِ اتَّخَذُوا آلِهَةً مِّنَ الْأَرْضِ هُمْ يُنشِرُونَ', NULL, 'Or have they [i.e., men] taken for themselves gods from the earth who resurrect [the dead]?', 'Adakah benda-benda dari bumi yang mereka jadikan tuhan-tuhan itu, dapat menghidupkan semula sesuatu yang mati?', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 0, NULL),
(21, 22, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا فَسُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ', NULL, 'Had there been within them [i.e., the heavens and earth] gods besides Allāh, they both would have been ruined. So exalted is Allāh, Lord of the Throne, above what they describe.', 'Kalau ada di langit dan di bumi tuhan-tuhan yang lain dari Allah, nescaya rosaklah pentadbiran kedua-duanya. Maka (bertauhidlah kamu kepada Allah dengan menegaskan): Maha Suci Allah, Tuhan yang mempunyai Arasy, dari apa yang mereka sifatkan.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 0, NULL),
(21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', 'لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ', NULL, 'He is not questioned about what He does, but they will be questioned.', 'Ia tidak boleh ditanya tentang apa yang Ia lakukan, sedang merekalah yang akan ditanya kelak.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 0, NULL),
(21, 24, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ فَهُم مُّعْرِضُونَ', 'أَمِ اتَّخَذُوا مِن دُونِهِ آلِهَةً قُلْ هَاتُوا بُرْهَانَكُمْ هَٰذَا ذِكْرُ مَن مَّعِيَ وَذِكْرُ مَن قَبْلِي بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ الْحَقَّ فَهُم مُّعْرِضُونَ', NULL, 'Or have they taken gods besides Him? Say, [O Muḥammad], "Produce your proof. This [Qur’ān] is the message for those with me and the message of those before me." But most of them do not know the truth, so they are turning away.', 'Patutkah mereka menyembah tuhan-tuhan yang lain dari Allah? Katakanlah (wahai Muhammad): “Bawalah keterangan dan bukti kamu; kandungan Al-Quran ini menjadi peringatan dan bukti tauhid umatku, juga peringatan dan bukti tauhid umat-umat yang dahulu daripadaku”. (Kaum musyrik tidak mempunyai sebarang keterangan) bahkan kebanyakan mereka tidak mengetahui mana yang benar dan mana yang salah, dengan sebab itulah maka mereka berpaling ingkar.', FALSE, NULL, NULL, 323, 17, 129, 279, FALSE, 0, NULL),
(21, 25, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', 'وَمَا أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لَا إِلَٰهَ إِلَّا أَنَا فَاعْبُدُونِ', NULL, 'And We sent not before you any messenger except We revealed to him that, "There is no deity except Me, so worship Me."', 'Dan Kami tidak mengutus sebelummu (wahai Muhammad) seseorang Rasul pun melainkan Kami wahyukan kepadanya: “Bahawa sesungguhnya tiada Tuhan (yang berhak disembah) melainkan Aku; oleh itu, beribadatlah kamu kepadaKu”.', FALSE, NULL, NULL, 324, 17, 129, 279, FALSE, 0, NULL),
(21, 26, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا سُبْحَٰنَهُۥ بَلْ عِبَادٌ مُّكْرَمُونَ', 'وَقَالُوا اتَّخَذَ الرَّحْمَٰنُ وَلَدًا سُبْحَانَهُ بَلْ عِبَادٌ مُّكْرَمُونَ', NULL, 'And they say, "The Most Merciful has taken a son." Exalted is He! Rather, they are [but] honored servants.', 'Dan mereka (yang musyrik) berkata: “(Allah) Ar-Rahman mempunyai anak”. Maha Sucilah Ia. Bahkan (mereka yang dikatakan menjadi anak Allah itu) ialah hamba-hambaNya yang dimuliakan.', FALSE, NULL, NULL, 324, 17, 129, 279, FALSE, 0, NULL),
(21, 27, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 'لَا يَسْبِقُونَهُ بِالْقَوْلِ وَهُم بِأَمْرِهِ يَعْمَلُونَ', NULL, 'They cannot precede Him in word, and they act by His command.', 'Mereka tidak mendahuluiNya dengan perkataan dan mereka pula mengerjakan apa yang diperintahkanNya.', FALSE, NULL, NULL, 324, 17, 129, 279, FALSE, 0, NULL),
(21, 28, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِ مُشْفِقُونَ', NULL, 'He knows what is [presently] before them and what will be after them, and they cannot intercede except on behalf of one whom He approves. And they, from fear of Him, are apprehensive.', 'Allah mengetahui apa yang di hadapan mereka (yang telah mereka lakukan), dan apa yang di belakang mereka (yang akan mereka lakukan); dan mereka tidak memohon syafaat melainkan bagi sesiapa yang diredhai Allah; dan mereka pula sentiasa cemas takut daripada ditimpa azabNya.', FALSE, NULL, NULL, 324, 17, 129, 279, FALSE, 0, NULL),
(21, 29, 'وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'وَمَن يَقُلْ مِنْهُمْ إِنِّي إِلَٰهٌ مِّن دُونِهِ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِي الظَّالِمِينَ', NULL, 'And whoever of them should say, "Indeed, I am a god besides Him" - that one We would recompense with Hell. Thus do We recompense the wrongdoers.', 'Dan (jika ada) sesiapa di antara mereka berkata: “Sesungguhnya aku ialah tuhan selain dari Allah”, maka yang berkata sedemikian itu, Kami akan membalasnya dengan (azab) neraka jahannam; demikianlah Kami membalas golongan yang zalim.', FALSE, NULL, NULL, 324, 17, 130, 279, FALSE, 0, NULL),
(21, 30, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَٰهُمَا وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ أَفَلَا يُؤْمِنُونَ', 'أَوَلَمْ يَرَ الَّذِينَ كَفَرُوا أَنَّ السَّمَاوَاتِ وَالْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ أَفَلَا يُؤْمِنُونَ', NULL, 'Have those who disbelieved not considered that the heavens and the earth were a joined entity, and then We separated them and made from water every living thing? Then will they not believe?', 'Dan tidakkah orang-orang kafir itu memikirkan dan mempercayai bahawa sesungguhnya langit dan bumi itu pada asal mulanya bercantum (sebagai benda yang satu), lalu Kami pisahkan antara keduanya? Dan Kami jadikan dari air, tiap-tiap benda yang hidup? Maka mengapa mereka tidak mahu beriman?', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 31, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', 'وَجَعَلْنَا فِي الْأَرْضِ رَوَاسِيَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', NULL, 'And We placed within the earth firmly set mountains, lest it should shift with them, and We made therein [mountain] passes [as] roads that they might be guided.', 'Dan Kami telah menjadikan di bumi gunung-ganang yang menetapnya, supaya bumi itu tidak menggegar mereka; dan Kami jadikan padanya celah-celah sebagai jalan-jalan lalu-lalang, supaya mereka dapat sampai kepada mencapai keperluan rohani dan jasmani.', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 32, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', 'وَجَعَلْنَا السَّمَاءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ آيَاتِهَا مُعْرِضُونَ', NULL, 'And We made the sky a protected ceiling, but they, from its signs, are turning away.', 'Dan Kami telah menjadikan langit sebagai bumbung yang terpelihara dan terkawal, sedang mereka (yang kafir itu) berpaling tidak memerhatikan tanda-tanda (kekuasaan Kami) yang ada padanya.', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 33, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'وَهُوَ الَّذِي خَلَقَ اللَّيْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَ كُلٌّ فِي فَلَكٍ يَسْبَحُونَ', NULL, 'And it is He who created the night and the day and the sun and the moon; all [heavenly bodies] in an orbit are swimming.', 'Dan Dia lah (Tuhan) yang telah menjadikan malam dan siang, serta matahari dan bulan; tiap-tiap satunya beredar terapung-apung di tempat edaran masing-masing (di angkasa lepas).', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 34, 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ الْخُلْدَ أَفَإِن مِّتَّ فَهُمُ الْخَالِدُونَ', NULL, 'And We did not grant to any man before you eternity [on earth]; so if you die - would they be eternal?', 'Dan Kami tidak menjadikan seseorang manusia sebelummu dapat hidup kekal (di dunia ini). Maka kalau engkau meninggal dunia (wahai Muhammad), adakah mereka akan hidup selama-lamanya?', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 35, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ', 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ وَنَبْلُوكُم بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ', NULL, 'Every soul will taste death. And We test you with evil and with good as trial; and to Us you will be returned.', 'Tiap-tiap diri akan merasai mati, dan Kami menguji kamu dengan kesusahan dan kesenangan sebagai cubaan; dan kepada Kamilah kamu semua akan dikembalikan.', FALSE, NULL, NULL, 324, 17, 130, 280, FALSE, 0, NULL),
(21, 36, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 'وَإِذَا رَآكَ الَّذِينَ كَفَرُوا إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا الَّذِي يَذْكُرُ آلِهَتَكُمْ وَهُم بِذِكْرِ الرَّحْمَٰنِ هُمْ كَافِرُونَ', NULL, 'And when those who disbelieve see you, [O Muḥammad], they take you not except in ridicule, [saying], "Is this the one who mentions [i.e., insults] your gods?" And they are, at the mention of the Most Merciful, disbelievers.', 'Dan apabila orang-orang kafir itu melihatmu, mereka hanyalah menjadikan perkara yang engkau sampaikan itu sebagai ejek-ejekan sahaja, sambil berkata sesama sendiri: “Inikah dia orangnya yang mencaci tuhan-tuhan kamu?” (Mereka berkata demikian) sedang mereka sendiri kufur ingkar kepada Al-Quran yang mengandungi peringatan Allah yang melimpah-limpah rahmatNya.', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 37, 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', 'خُلِقَ الْإِنسَانُ مِنْ عَجَلٍ سَأُرِيكُمْ آيَاتِي فَلَا تَسْتَعْجِلُونِ', NULL, 'Man was created of haste [i.e., impatience]. I will show you My signs [i.e., vengeance], so do not impatiently urge Me.', 'Jenis manusia dijadikan bertabiat terburu-buru dalam segala halya; Aku (Allah) akan perlihatkan kepada kamu tanda-tanda kekuasaanKu; maka janganlah kamu meminta disegerakan (kedatangannya).', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 38, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is this promise, if you should be truthful?"', 'Dan (kerana tabiat terburu-burunya) mereka berkata: “Bilakah berlakunya janji azab itu, jika betul kamu orang-orang yang berkata benar?”.', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 39, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', 'لَوْ يَعْلَمُ الَّذِينَ كَفَرُوا حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ النَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', NULL, 'If those who disbelieved but knew the time when they will not avert the Fire from their faces or from their backs and they will not be aided...', 'Kalaulah orang-orang kafir itu mengetahui apa yang akan menimpa mereka ketika mereka tidak dapat menahan atau mengelakkan api neraka dari muka dan belakang mereka, dan mereka pula tidak diberi pertolongan, (tentulah mereka segera beriman, dan tidak berkata demikian).', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 40, 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', NULL, 'Rather, it will come to them unexpectedly and bewilder them, and they will not be able to repel it, nor will they be reprieved.', '(Mereka tidak diberitahu akan masa itu) bahkan (yang dijanjikan) itu akan datang kepada mereka secara mengejut, serta terus membingungkan mereka; maka mereka tidak akan terdaya menolaknya, dan tidak akan diberi tempoh bertaubat.', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 41, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِالَّذِينَ سَخِرُوا مِنْهُم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by what they used to ridicule.', 'Dan demi sesungguhnya, telah diperolok-olokkan beberapa Rasul sebelummu, lalu orang-orang yang mengejek-ejek di antara mereka, ditimpakan balasan azab bagi apa yang mereka telah perolok-olokkan itu.', FALSE, NULL, NULL, 325, 17, 130, 280, FALSE, 0, NULL),
(21, 42, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 'قُلْ مَن يَكْلَؤُكُم بِاللَّيْلِ وَالنَّهَارِ مِنَ الرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', NULL, 'Say, "Who can protect you at night or by day from the Most Merciful?" But they are, from the remembrance of their Lord, turning away.', 'Katakanlah (wahai Muhammad): “Siapakah yang dapat menjaga keselamatan kamu pada malam dan siang daripada azab Tuhan yang bersifat Maha Pemurah?” (Mereka tidak memikirkan yang demikian) bahkan mereka tetap berpaling ingkar dari pengajaran Tuhan mereka.', FALSE, NULL, NULL, 325, 17, 130, 281, FALSE, 0, NULL),
(21, 43, 'أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', 'أَمْ لَهُمْ آلِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', NULL, 'Or do they have gods to defend them other than Us? They are unable [even] to help themselves, nor can they be protected from Us.', 'Tidak ada bagi mereka tuhan-tuhan yang dapat melindungi mereka dari azab Kami. Mereka yang dipertuhankan itu tidak dapat menolong dirinya sendiri, dan tidak pula mereka dibantu dengan pertolongan dari pihak Kami.', FALSE, NULL, NULL, 325, 17, 130, 281, FALSE, 0, NULL),
(21, 44, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ أَفَهُمُ ٱلْغَٰلِبُونَ', 'بَلْ مَتَّعْنَا هَٰؤُلَاءِ وَآبَاءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ الْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِي الْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا أَفَهُمُ الْغَالِبُونَ', NULL, 'But, [on the contrary], We have provided good things for these [disbelievers] and their fathers until life was prolonged for them. Then do they not see that We set upon the land, reducing it from its borders? Is it they who will overcome?', '(Bukan benda-benda yang dipertuhankan itu yang memberi kesenangan kepada mereka) bahkan Kami biarkan mereka dan datuk-nenek mereka menikmati (kesenangan hidup) hingga berlanjutanlah umur mereka (dalam keadaan yang menyebabkan berlaku perkara yang tidak diingini mereka). Maka tidakkah mereka melihat bahawa kami datangi daerah bumi yang mereka kuasai dengan menguranginya sedikit demi sedikit dari sempadan-sempadannya? Jika demikian halnya, maka adakah mereka yang akan menang?', FALSE, NULL, NULL, 325, 17, 130, 281, FALSE, 0, NULL),
(21, 45, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'قُلْ إِنَّمَا أُنذِرُكُم بِالْوَحْيِ وَلَا يَسْمَعُ الصُّمُّ الدُّعَاءَ إِذَا مَا يُنذَرُونَ', NULL, 'Say, "I only warn you by revelation." But the deaf do not hear the call when they are warned.', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku hanyalah memberi amaran kepada kamu dengan wahyu (Al-Quran yang diturunkan Allah kepadaku); dan sudah tentu orang-orang yang pekak tidak dapat mendengar seruan apabila mereka diberi amaran, (maka janganlah kamu menjadi pekak kerana azab Tuhan amatlah berat).', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 46, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَا وَيْلَنَا إِنَّا كُنَّا ظَالِمِينَ', NULL, 'And if [as much as] a whiff of the punishment of your Lord should touch them, they would surely say, "O woe to us! Indeed, we have been wrongdoers."', 'Dan demi sesungguhnya, jika mereka disentuh oleh sedikit sahaja dari azab Tuhanmu, sudah tentu mereka akan berkata: “Aduhai celakanya kami! Sebenarnya kami adalah orang-orang yang zalim (terhadap diri sendiri)!”', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 47, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ', 'وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ', NULL, 'And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant.', 'Dan (ingatlah) Kami akan mengadakan neraca timbangan yang adil untuk (menimbang amal makhluk-makhluk pada) hari kiamat; maka tidak ada diri sesiapa akan teraniaya sedikitpun; dan jika (amalnya) itu seberat biji sawi (sekalipun), nescaya Kami akan mendatangkannya (untuk ditimbang dan dihitung); dan cukuplah Kami sebagai Penghitung.', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 48, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ', 'وَلَقَدْ آتَيْنَا مُوسَىٰ وَهَارُونَ الْفُرْقَانَ وَضِيَاءً وَذِكْرًا لِّلْمُتَّقِينَ', NULL, 'And We had already given Moses and Aaron the criterion and a light and a reminder for the righteous', 'Dan demi sesungguhnya, Kami telah memberi kepada Nabi Musa dan Nabi Harun Kitab (Taurat) yang membezakan antara yang benar dengan yang salah, dan yang menjadi cahaya yang menerangi, serta yang mengandungi pengajaran, bagi orang-orang yang mahu bertaqwa.', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 49, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 'الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ وَهُم مِّنَ السَّاعَةِ مُشْفِقُونَ', NULL, 'Who fear their Lord unseen, while they are of the Hour apprehensive.', 'Iaitu mereka yang takut (melanggar hukum-hukum) Tuhannya semasa mereka tidak dilihat orang, dan mereka pula gerun cemas akan (peristiwa-peristiwa yang mengerikan pada) hari kiamat.', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 50, 'وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَٰهُ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', 'وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَاهُ أَفَأَنتُمْ لَهُ مُنكِرُونَ', NULL, 'And this [Qur’ān] is a blessed message which We have sent down. Then are you with it unacquainted?', 'Dan Al-Quran ini juga pengajaran yang berkat, yang Kami turunkan (kepada Nabi Muhammad); dengan keadaan yang demikian maka patutkah kamu mengingkarinya?', FALSE, NULL, NULL, 326, 17, 130, 281, FALSE, 0, NULL),
(21, 51, 'وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', 'وَلَقَدْ آتَيْنَا إِبْرَاهِيمَ رُشْدَهُ مِن قَبْلُ وَكُنَّا بِهِ عَالِمِينَ', NULL, 'And We had certainly given Abraham his sound judgement before, and We were of him well-Knowing', 'Dan demi sesungguhnya, Kami telah memberi kepada Nabi Ibrahim sebelum itu jalan yang benar dalam bertauhid, dan Kami adalah mengetahui akan halnya.', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 52, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِ مَا هَٰذِهِ التَّمَاثِيلُ الَّتِي أَنتُمْ لَهَا عَاكِفُونَ', NULL, 'When he said to his father and his people, "What are these statues to which you are devoted?"', 'Ketika ia berkata kepada bapanya dan kaumnya: “Apakah hakikatnya patung-patung ini yang kamu bersungguh-sungguh memujanya?”', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 53, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', 'قَالُوا وَجَدْنَا آبَاءَنَا لَهَا عَابِدِينَ', NULL, 'They said, "We found our fathers worshippers of them."', 'Mereka menjawab: “Kami dapati datuk nenek kami selalu menyembahnya”.', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 54, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍ مُّبِينٍ', 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَآبَاؤُكُمْ فِي ضَلَالٍ مُّبِينٍ', NULL, 'He said, "You were certainly, you and your fathers, in manifest error."', 'Ia berkata: “Sesungguhnya kamu dan datuk-nenek kamu adalah dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 55, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', 'قَالُوا أَجِئْتَنَا بِالْحَقِّ أَمْ أَنتَ مِنَ اللَّاعِبِينَ', NULL, 'They said, "Have you come to us with truth, or are you of those who jest?"', 'Mereka bertanya: “Adakah engkau membawa kepada kami sesuatu yang benar (sebagai seorang Rasul), atau engkau dari orang-orang yang bermain-main sahaja?”', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 56, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', 'قَالَ بَل رَّبُّكُمْ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ الَّذِي فَطَرَهُنَّ وَأَنَا عَلَىٰ ذَٰلِكُم مِّنَ الشَّاهِدِينَ', NULL, 'He said, "[No], rather, your Lord is the Lord of the heavens and the earth who created them, and I, to that, am of those who testify.', 'Ia menjawab: “(Bukan bermain-main) bahkan (untuk menegaskan bahawa) Tuhan kamu ialah Tuhan yang mentadbirkan langit dan bumi, Dia lah yang menciptanya; dan aku adalah dari orang-orang yang boleh memberi keterangan mengesahkan yang demikian itu.', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 57, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', 'وَتَاللَّهِ لَأَكِيدَنَّ أَصْنَامَكُم بَعْدَ أَن تُوَلُّوا مُدْبِرِينَ', NULL, 'And [I swear] by Allāh, I will surely plan against your idols after you have turned and gone away."', '“Dan demi Allah, aku akan jalankan rancangan terhadap berhala-berhala kamu, sesudah kamu pergi meninggalkan (rumah berhala ini)”.', FALSE, NULL, NULL, 326, 17, 131, 282, FALSE, 0, NULL),
(21, 58, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', 'فَجَعَلَهُمْ جُذَاذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', NULL, 'So he made them into fragments, except a large one among them, that they might return to it [and question].', 'Lalu ia memecahkan semuanya berketul-ketul, kecuali sebuah berhala mereka yang besar (dibiarkannya), supaya mereka kembali kepadanya.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 59, 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 'قَالُوا مَن فَعَلَ هَٰذَا بِآلِهَتِنَا إِنَّهُ لَمِنَ الظَّالِمِينَ', NULL, 'They said, "Who has done this to our gods? Indeed, he is of the wrongdoers."', '(Setelah melihat kejadian itu) mereka bertanya: “Siapakah yang melakukan perbuatan yang demikian terhadap tuhan-tuhan kami? Sesungguhnya adalah ia dari orang-orang yang zalim”.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 60, 'قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', 'قَالُوا سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ', NULL, 'They said, "We heard a young man mention them who is called Abraham."', '(Setengah dari) mereka berkata: “Kami ada mendengar seorang anak muda bernama Ibrahim, mencacinya”.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 61, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', 'قَالُوا فَأْتُوا بِهِ عَلَىٰ أَعْيُنِ النَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', NULL, 'They said, "Then bring him before the eyes of the people that they may testify."', '(Ketua-ketua) mereka berkata: “Jika demikian, bawalah dia di hadapan orang ramai supaya mereka menyaksikan (tindakan mengenainya).', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 62, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', 'قَالُوا أَأَنتَ فَعَلْتَ هَٰذَا بِآلِهَتِنَا يَا إِبْرَاهِيمُ', NULL, 'They said, "Have you done this to our gods, O Abraham?"', '(Setelah ia dibawa ke situ) mereka bertanya: “Engkaukah yang melakukan demikian kepada tuhan-tuhan kami, hai Ibrahim?”', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 63, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 'قَالَ بَلْ فَعَلَهُ كَبِيرُهُمْ هَٰذَا فَاسْأَلُوهُمْ إِن كَانُوا يَنطِقُونَ', NULL, 'He said, "Rather, this - the largest of them - did it, so ask them, if they should [be able to] speak."', 'Ia menjawab: “(Tidak) bahkan yang melakukannya ialah (berhala) yang besar di antara mereka ini! Maka bertanyalah kamu kepada mereka kalau-kalau mereka dapat berkata-kata”.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 64, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', 'فَرَجَعُوا إِلَىٰ أَنفُسِهِمْ فَقَالُوا إِنَّكُمْ أَنتُمُ الظَّالِمُونَ', NULL, 'So they returned to [blaming] themselves and said [to each other], "Indeed, you are the wrongdoers."', 'Maka mereka (penyembah berhala) kembali kepada diri mereka (memikirkan hal itu) lalu berkata (sesama sendiri): “Sesungguhnya kamulah sendiri orang-orang yang zalim”.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 65, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 'ثُمَّ نُكِسُوا عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰؤُلَاءِ يَنطِقُونَ', NULL, 'Then they reversed themselves, [saying], "You have already known that these do not speak!"', 'Kemudian mereka terbalik fikirannya kepada kesesatan, lalu berkata: “Sesungguhnya engkau (hai Ibrahim), telah sedia mengetahui bahawa berhala-berhala itu tidak dapat berkata-kata (maka betapa engkau menyuruh kami bertanya kepadanya)?”', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 66, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ', 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَنفَعُكُمْ شَيْئًا وَلَا يَضُرُّكُمْ', NULL, 'He said, "Then do you worship instead of Allāh that which does not benefit you at all or harm you?', 'Nabi Ibrahim berkata: “Jika demikian, patutkah kamu menyembah yang lain dari Allah sesuatu yang tidak dapat mendatangkan faedah sedikitpun kepada kamu, dan juga tidak dapat mendatangkan mudarat kepada kamu?', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 67, 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَفَلَا تَعْقِلُونَ', 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ اللَّهِ أَفَلَا تَعْقِلُونَ', NULL, 'Uff to you and to what you worship instead of Allāh. Then will you not use reason?"', '“Jijik perasaanku terhadap kamu dan apa yang kamu sembah selain Allah! Maka mengapa kamu tidak mahu menggunakan akal fikiran kamu?”', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 68, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 'قَالُوا حَرِّقُوهُ وَانصُرُوا آلِهَتَكُمْ إِن كُنتُمْ فَاعِلِينَ', NULL, 'They said, "Burn him and support your gods - if you are to act."', '(Setelah tidak dapat berhujah lagi, ketua-ketua) mereka berkata: “Bakarlah dia dan belalah tuhan-tuhan kamu, jika betul kamu mahu bertindak membelanya!”', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 69, 'قُلْنَا يَٰنَارُ كُونِى بَرْدًا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 'قُلْنَا يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ', NULL, 'We [i.e., Allāh] said, "O fire, be coolness and safety upon Abraham."', 'Kami berfirman: “Hai api, jadilah engkau sejuk serta selamat sejahtera kepada Ibrahim!”.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 70, 'وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 'وَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَخْسَرِينَ', NULL, 'And they intended for him a plan [i.e., harm], but We made them the greatest losers.', 'Dan mereka (dengan perbuatan membakarnya itu) hendak melakukan angkara yang menyakitinya, lalu Kami jadikan mereka orang-orang yang amat rugi, (kalah dengan hinanya).', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 71, 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 'وَنَجَّيْنَاهُ وَلُوطًا إِلَى الْأَرْضِ الَّتِي بَارَكْنَا فِيهَا لِلْعَالَمِينَ', NULL, 'And We delivered him and Lot to the land which We had blessed for the worlds [i.e., peoples].', 'Dan Kami selamatkan dia dan (sepupunya) Nabi Lut ke negeri yang Kami limpahkan berkat padanya untuk umat manusia.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 72, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَٰلِحِينَ', 'وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَالِحِينَ', NULL, 'And We gave him Isaac and Jacob in addition, and all [of them] We made righteous.', 'Dan Kami kurniakan kepadanya: Ishak (anaknya), dan Yaakub (cucunya) sebagai tambahan; dan tiap-tiap seorang (dari mereka) Kami jadikan orang yang soleh.', FALSE, NULL, NULL, 327, 17, 131, 282, FALSE, 0, NULL),
(21, 73, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 'وَجَعَلْنَاهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَا إِلَيْهِمْ فِعْلَ الْخَيْرَاتِ وَإِقَامَ الصَّلَاةِ وَإِيتَاءَ الزَّكَاةِ وَكَانُوا لَنَا عَابِدِينَ', NULL, 'And We made them leaders guiding by Our command. And We inspired to them the doing of good deeds, establishment of prayer, and giving of zakāh; and they were worshippers of Us.', 'Dan Kami jadikan mereka ketua-ketua ikutan, yang memimpin (manusia ke jalan yang benar) dengan perintah Kami, dan Kami wahyukan kepada mereka mengerjakan kebaikan, dan mendirikan sembahyang, serta memberi zakat; dan mereka pula sentiasa beribadat kepada Kami.', FALSE, NULL, NULL, 328, 17, 131, 282, FALSE, 0, NULL),
(21, 74, 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَٰسِقِينَ', 'وَلُوطًا آتَيْنَاهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَاهُ مِنَ الْقَرْيَةِ الَّتِي كَانَت تَّعْمَلُ الْخَبَائِثَ إِنَّهُمْ كَانُوا قَوْمَ سَوْءٍ فَاسِقِينَ', NULL, 'And to Lot We gave judgement and knowledge, and We saved him from the city that was committing wicked deeds. Indeed, they were a people of evil, defiantly disobedient.', 'Dan kepada Nabi Lut, Kami berikan hikmat kebijaksanaan dan ilmu; dan Kami selamatkan dia dari bandar yang penduduknya selalu melakukan perkara-perkara yang keji; sesungguhnya mereka itu adalah kaum jahat, yang fasik, derhaka.', FALSE, NULL, NULL, 328, 17, 131, 282, FALSE, 0, NULL),
(21, 75, 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 'وَأَدْخَلْنَاهُ فِي رَحْمَتِنَا إِنَّهُ مِنَ الصَّالِحِينَ', NULL, 'And We admitted him into Our mercy. Indeed, he was of the righteous.', 'Dan Kami masukkan Nabi Lut dalam (kumpulan mereka yang dilimpahi) rahmat Kami; sesungguhnya dia dari orang-orang yang soleh.', FALSE, NULL, NULL, 328, 17, 131, 282, FALSE, 0, NULL),
(21, 76, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَاسْتَجَبْنَا لَهُ فَنَجَّيْنَاهُ وَأَهْلَهُ مِنَ الْكَرْبِ الْعَظِيمِ', NULL, 'And [mention] Noah, when he called [to Allāh] before [that time], so We responded to him and saved him and his family from the great affliction [i.e., the flood].', 'Dan (sebutkanlah peristiwa) Nabi Nuh, ketika ia menyeru (berdoa kepada Kami) sebelum (Nabi-nabi yang tersebut) itu, lalu Kami perkenankan doanya serta Kami selamatkan dia dan pengikut-pengikutnya dari kesusahan yang besar.', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 77, 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'وَنَصَرْنَاهُ مِنَ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِنَا إِنَّهُمْ كَانُوا قَوْمَ سَوْءٍ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ', NULL, 'And We aided [i.e., saved] him from the people who denied Our signs. Indeed, they were a people of evil, so We drowned them, all together.', 'Dan Kami membelanya dari angkara kaum yang mendustakan ayat-ayat Kami; sesungguhnya adalah mereka kaum yang jahat; lalu Kami tenggelamkan mereka semuanya (sehingga mati lemas dengan taufan).', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 78, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 'وَدَاوُودَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَاهِدِينَ', NULL, 'And [mention] David and Solomon, when they judged concerning the field - when the sheep of a people overran it [at night], and We were witness to their judgement.', 'Dan (sebutkanlah peristiwa) Nabi Daud dengan Nabi Sulaiman, ketika mereka berdua menghukum mengenai tanaman-tanaman semasa ia dirosakkan oleh kambing kaumnya pada waktu malam; dan sememangnya Kamilah yang memerhati dan mengesahkan hukuman mereka.', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 79, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ وَكُنَّا فَٰعِلِينَ', 'فَفَهَّمْنَاهَا سُلَيْمَانَ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُودَ الْجِبَالَ يُسَبِّحْنَ وَالطَّيْرَ وَكُنَّا فَاعِلِينَ', NULL, 'And We gave understanding of it [i.e., the case] to Solomon, and to each [of them] We gave judgement and knowledge. And We subjected the mountains to exalt [Us], along with David and [also] the birds. And We were doing [that].', 'Maka Kami beri Nabi Sulaiman memahami hukum yang lebih tepat bagi masalah itu; dan masing-masing (dari mereka berdua) Kami berikan hikmat kebijaksanaan dan ilmu (yang banyak); dan Kami mudahkan gunung-ganang dan unggas memuji Kami bersama-sama dengan Nabi Daud; dan adalah Kami berkuasa melakukan semuanya itu.', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 80, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ فَهَلْ أَنتُمْ شَٰكِرُونَ', 'وَعَلَّمْنَاهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّن بَأْسِكُمْ فَهَلْ أَنتُمْ شَاكِرُونَ', NULL, 'And We taught him the fashioning of coats of armor to protect you from your [enemy in] battle. So will you then be grateful?', 'Dan Kami mengajar Nabi Daud membuat baju-baju besi untuk kamu, untuk menjaga keselamatan kamu dalam mana-mana peperangan kamu, maka adakah kamu sentiasa bersyukur?', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 81, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', 'وَلِسُلَيْمَانَ الرِّيحَ عَاصِفَةً تَجْرِي بِأَمْرِهِ إِلَى الْأَرْضِ الَّتِي بَارَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَيْءٍ عَالِمِينَ', NULL, 'And to Solomon [We subjected] the wind, blowing forcefully, proceeding by his command toward the land which We had blessed. And We are ever, of all things, Knowing.', 'Dan (Kami mudahkan) bagi Nabi Sulaiman angin yang kencang tiupannya, bertiup menurut kehendaknya ke negeri yang Kami limpahi berkat padanya; dan adalah Kami mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 328, 17, 131, 283, FALSE, 0, NULL),
(21, 82, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَٰفِظِينَ', 'وَمِنَ الشَّيَاطِينِ مَن يَغُوصُونَ لَهُ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَافِظِينَ', NULL, 'And of the devils [i.e., jinn] were those who dived for him and did work other than that. And We were of them a guardian.', 'Dan (Kami mudahkan) sebahagian dari Syaitan-syaitan untuk menyelam baginya, serta melakukan kerja-kerja yang lain dari itu; dan adalah Kami mengawal mereka (daripada melanggar perintahnya).', FALSE, NULL, NULL, 329, 17, 131, 283, FALSE, 0, NULL),
(21, 83, 'وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ', NULL, 'And [mention] Job, when he called to his Lord, "Indeed, adversity has touched me, and You are the most merciful of the merciful."', 'Dan (sebutkanlah peristiwa) Nabi Ayub, ketika ia berdoa merayu kepada Tuhannya dengan berkata: “Sesungguhnya aku ditimpa penyakit, sedang Engkaulah sahaja yang lebih mengasihani daripada segala (yang lain) yang mengasihani”.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 84, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', 'فَاسْتَجَبْنَا لَهُ فَكَشَفْنَا مَا بِهِ مِن ضُرٍّ وَآتَيْنَاهُ أَهْلَهُ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَابِدِينَ', NULL, 'So We responded to him and removed what afflicted him of adversity. And We gave him [back] his family and the like thereof with them as mercy from Us and a reminder for the worshippers [of Allāh].', 'Maka Kami perkenankan doa permohonannya, lalu Kami hapuskan penyakit yang menimpanya, serta Kami kurniakan kepadanya: keluarganya, dengan seganda lagi ramainya, sebagai satu rahmat dari Kami dan sebagai satu peringatan bagi orang-orang yang taat kepada Kami (supaya bersabar dan mendapat balasan baik).', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 85, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ كُلٌّ مِّنَ ٱلصَّٰبِرِينَ', 'وَإِسْمَاعِيلَ وَإِدْرِيسَ وَذَا الْكِفْلِ كُلٌّ مِّنَ الصَّابِرِينَ', NULL, 'And [mention] Ishmael and Idrees and Dhul-Kifl; all were of the patient.', 'Dan (demikianlah pula) Nabi-nabi Ismail dan Idris serta Zul-Kifli; semuanya adalah dari orang-orang yang sabar.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 86, 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', 'وَأَدْخَلْنَاهُمْ فِي رَحْمَتِنَا إِنَّهُم مِّنَ الصَّالِحِينَ', NULL, 'And We admitted them into Our mercy. Indeed, they were of the righteous.', 'Dan Kami masukkan mereka dalam (kumpulan yang dilimpahi) rahmat Kami: sesungguhnya mereka adalah dari orang-orang yang soleh.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 87, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', 'وَذَا النُّونِ إِذ ذَّهَبَ مُغَاضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِي الظُّلُمَاتِ أَن لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', NULL, 'And [mention] the man of the fish [i.e., Jonah], when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers."', 'Dan (sebutkanlah peristiwa) Zun-Nun, ketika ia pergi (meninggalkan kaumnya) dalam keadaan marah, yang menyebabkan ia menyangka bahawa Kami tidak akan mengenakannya kesusahan atau cubaan; (setelah berlaku kepadanya apa yang berlaku) maka ia pun menyeru dalam keadaan yang gelap-gelita dengan berkata: “Sesungguhnya tiada Tuhan (yang dapat menolong) melainkan Engkau (ya Allah)! Maha Suci Engkau (daripada melakukan aniaya, tolongkanlah daku)! Sesungguhnya aku adalah dari orang-orang yang menganiaya diri sendiri”.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 88, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ وَكَذَٰلِكَ نُـۨجِى ٱلْمُؤْمِنِينَ', 'فَاسْتَجَبْنَا لَهُ وَنَجَّيْنَاهُ مِنَ الْغَمِّ وَكَذَٰلِكَ نُنجِي الْمُؤْمِنِينَ', NULL, 'So We responded to him and saved him from the distress. And thus do We save the believers.', 'Maka Kami kabulkan permohonan doanya, dan Kami selamatkan dia dari kesusahan yang menyelubunginya; dan sebagaimana Kami menyelamatkannya Kami akan selamatkan orang-orang yang beriman (ketika mereka merayu kepada Kami).', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 89, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', 'وَزَكَرِيَّا إِذْ نَادَىٰ رَبَّهُ رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ', NULL, 'And [mention] Zechariah, when he called to his Lord, "My Lord, do not leave me alone [with no heir], while You are the best of inheritors."', 'Dan (sebutkanlah peristiwa) Nabi Zakaria, ketika ia merayu kepada Tuhannya dengan berkata: “Wahai Tuhanku! Janganlah Engkau biarkan daku seorang diri (dengan tidak meninggalkan zuriat); dan Engkaulah jua sebaik-baik yang mewarisi”.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 90, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا۟ لَنَا خَٰشِعِينَ', 'فَاسْتَجَبْنَا لَهُ وَوَهَبْنَا لَهُ يَحْيَىٰ وَأَصْلَحْنَا لَهُ زَوْجَهُ إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا لَنَا خَاشِعِينَ', NULL, 'So We responded to him, and We gave to him John, and amended for him his wife. Indeed, they used to hasten to good deeds and supplicate Us in hope and fear, and they were to Us humbly submissive.', 'Maka Kami perkenankan doanya, dan Kami kurniakan kepadanya (anaknya) Yahya, dan Kami perelokkan keadaan isterinya yang mandul, (untuk melahirkan anak) baginya. (Kami limpahkan berbagai ihsan kepada Rasul-rasul itu ialah kerana) sesungguhnya mereka sentiasa berlumba-lumba dalam mengerjakan kebaikan, dan sentiasa berdoa kepada kami dengan penuh harapan serta gerun takut; dan mereka pula sentiasa khusyuk (dan taat) kepada Kami.', FALSE, NULL, NULL, 329, 17, 132, 283, FALSE, 0, NULL),
(21, 91, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ', 'وَالَّتِي أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَاهَا وَابْنَهَا آيَةً لِّلْعَالَمِينَ', NULL, 'And [mention] the one who guarded her chastity [i.e., Mary], so We blew into her [garment] through Our angel [i.e., Gabriel], and We made her and her son a sign for the worlds.', 'Dan (sebutkanlah peristiwa) perempuan yang telah menjaga kehormatan dan kesuciannya; lalu Kami tiupkan padanya dari Roh (ciptaan) Kami, dan Kami jadikan dia dan anaknya sebagai satu tanda (yang menunjukkan kekuasaan Kami) bagi umat manusia.', FALSE, NULL, NULL, 330, 17, 132, 283, FALSE, 0, NULL),
(21, 92, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 'إِنَّ هَٰذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً وَأَنَا رَبُّكُمْ فَاعْبُدُونِ', NULL, 'Indeed this, your religion, is one religion, and I am your Lord, so worship Me.', 'Sesungguhnya ugama Islam inilah ugama kamu, ugama yang satu asas pokoknya, dan Akulah Tuhan kamu; maka sembahlah kamu akan Daku.', FALSE, NULL, NULL, 330, 17, 132, 283, FALSE, 0, NULL),
(21, 93, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 'وَتَقَطَّعُوا أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَاجِعُونَ', NULL, 'And [yet] they divided their affair [i.e., that of their religion] among themselves, [but] all to Us will return.', '(Kebanyakan manusia masih berselisihan) dan berpecah-belah dalam urusan ugama mereka; (ingatlah) mereka semuanya akan kembali kepada kami (untuk menerima balasan).', FALSE, NULL, NULL, 330, 17, 132, 283, FALSE, 0, NULL),
(21, 94, 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', 'فَمَن يَعْمَلْ مِنَ الصَّالِحَاتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِ وَإِنَّا لَهُ كَاتِبُونَ', NULL, 'So whoever does righteous deeds while he is a believer - no denial will there be for his effort, and indeed We [i.e., Our angels], of it, are recorders.', 'Dengan yang demikian, sesiapa yang mengerjakan sesuatu amal kebaikan, sedang ia beriman, maka tidaklah disia-siakan amal usahanya; dan sesungguhnya Kami tetap menulisnya.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 95, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', 'وَحَرَامٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَاهَا أَنَّهُمْ لَا يَرْجِعُونَ', NULL, 'And it is prohibited to [the people of] a city which We have destroyed that they will [ever] return', 'Dan mustahil kepada penduduk sesebuah negeri yang Kami binasakan, bahawa mereka tidak akan kembali (kepada Kami untuk menerima balasan di akhirat kelak).', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 96, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', 'حَتَّىٰ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', NULL, 'Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend', '(Demikianlah keadaan mereka) hingga apabila terbuka tembok yang menyekat Yakjuj dan Makjuj, serta mereka meluru turun dari tiap-tiap tempat yang tinggi.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 97, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', 'وَاقْتَرَبَ الْوَعْدُ الْحَقُّ فَإِذَا هِيَ شَاخِصَةٌ أَبْصَارُ الَّذِينَ كَفَرُوا يَا وَيْلَنَا قَدْ كُنَّا فِي غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَالِمِينَ', NULL, 'And [when] the true promise [i.e., the resurrection] has approached; then suddenly the eyes of those who disbelieved will be staring [in horror, while they say], "O woe to us; we had been unmindful of this; rather, we were wrongdoers."', 'Dan hampirlah datangnya janji hari kiamat yang benar, maka dengan serta-merta pandangan mata orang-orang yang kufur ingkar terbeliak (sambil berkata dengan cemas): “Aduhai celakanya Kami. Sesungguhnya kami telah tinggal dalam keadaan yang melalaikan kami daripada memikirkan perkara ini, bahkan kami telah menjadi orang-orang yang menganiaya diri sendiri”.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 98, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَارِدُونَ', NULL, 'Indeed, you [disbelievers] and what you worship other than Allāh are the firewood of Hell. You will be coming to [enter] it.', 'Sesungguhnya kamu dan apa yang kamu sembah, yang lain dari Allah, menjadi bahan-bahan bakaran yang dilimparkan ke dalam neraka Jahannam; kamu (sudah tetap) akan memasukinya.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 99, 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَٰلِدُونَ', 'لَوْ كَانَ هَٰؤُلَاءِ آلِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَالِدُونَ', NULL, 'Had these [false deities] been [actual] gods, they would not have come to it, but all are eternal therein.', 'Kalaulah mereka (yang kamu sembah) itu tuhan-tuhan, tentulah mereka tidak masuk ke dalam neraka; dan (ketahuilah), semuanya (yang menyembah dan yang disembah) akan kekal dalam neraka selama-lamanya.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 100, 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', NULL, 'For them therein is heavy sighing, and they therein will not hear.', 'Mereka mendayu-dayu (kesakitan) di dalam neraka, dan mereka pula di situ tidak dapat mendengar sesuatu yang menyenangkan.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 101, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', 'إِنَّ الَّذِينَ سَبَقَتْ لَهُم مِّنَّا الْحُسْنَىٰ أُولَٰئِكَ عَنْهَا مُبْعَدُونَ', NULL, 'Indeed, those for whom the best [reward] has preceded from Us - they are from it far removed.', 'Sesungguhnya orang-orang yang telah tetap dari dahulu lagi memperoleh kebaikan dari Kami, mereka dijauhkan dari neraka itu.', FALSE, NULL, NULL, 330, 17, 132, 284, FALSE, 0, NULL),
(21, 102, 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِي مَا اشْتَهَتْ أَنفُسُهُمْ خَالِدُونَ', NULL, 'They will not hear its sound, while they are, in that which their souls desire, abiding eternally.', 'Mereka tidak mendengar suara (julangan) api neraka itu, dan mereka akan kekal selama-lamanya di dalam (nikmat-nikmat Syurga) yang diingini oleh jiwa mereka.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 103, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', 'لَا يَحْزُنُهُمُ الْفَزَعُ الْأَكْبَرُ وَتَتَلَقَّاهُمُ الْمَلَائِكَةُ هَٰذَا يَوْمُكُمُ الَّذِي كُنتُمْ تُوعَدُونَ', NULL, 'They will not be grieved by the greatest terror, and the angels will meet them, [saying], "This is your Day which you have been promised" -', 'Huru-hara besar yang amat mengerikan (pada hari kiamat) itu tidak merunsingkan mereka, dan (sebaliknya) mereka disambut oleh malaikat-malaikat dengan berkata: “Inilah hari kamu (beroleh kebahagiaan), yang telah dijanjikan kepada kamu (di dunia) dahulu”.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 104, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ وَعْدًا عَلَيْنَآ إِنَّا كُنَّا فَٰعِلِينَ', 'يَوْمَ نَطْوِي السَّمَاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُّعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ', NULL, 'The Day when We will fold the heaven like the folding of a [written] sheet for the records. As We began the first creation, We will repeat it. [That is] a promise binding upon Us. Indeed, We will do it.', '(Ingatlah) hari Kami menggulung langit seperti menggulung lembaran surat catitan; sebagaimana kami mulakan wujudnya sesuatu kejadian, Kami ulangi wujudnya lagi; sebagai satu janji yang ditanggung oleh Kami; sesungguhnya Kami tetap melaksanakannya.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 105, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', 'وَلَقَدْ كَتَبْنَا فِي الزَّبُورِ مِن بَعْدِ الذِّكْرِ أَنَّ الْأَرْضَ يَرِثُهَا عِبَادِيَ الصَّالِحُونَ', NULL, 'And We have already written in the book [of Psalms] after the [previous] mention that the land [of Paradise] is inherited by My righteous servants.', 'Dan demi sesungguhnya, Kami telah tulis di dalam Kitab-kitab yang Kami turunkan sesudah ada tulisannya pada Lauh Mahfuz: “Bahawasanya bumi itu akan diwarisi oleh hamba-hambaKu yang soleh”.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 106, 'إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ', 'إِنَّ فِي هَٰذَا لَبَلَاغًا لِّقَوْمٍ عَابِدِينَ', NULL, 'Indeed, in this [Qur’ān] is notification for a worshipping people.', 'Sesungguhnya Al-Quran ini mengandungi keterangan-keterangan yang cukup bagi orang-orang yang (cita-citanya) mengerjakan ibadat (kepada Allah dengan berilmu).', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 107, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ', 'وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ', NULL, 'And We have not sent you, [O Muḥammad], except as a mercy to the worlds.', 'Dan tiadalah Kami mengutuskan engkau (wahai Muhammad), melainkan untuk menjadi rahmat bagi sekalian alam.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 108, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ', 'قُلْ إِنَّمَا يُوحَىٰ إِلَيَّ أَنَّمَا إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ', NULL, 'Say, "It is only revealed to me that your god is but one God; so will you be Muslims [in submission to Him]?"', 'Katakanlah: “Sesungguhnya yang diwahyukan kepadaku (mengenai ketuhanan ialah) bahawa Tuhan kamu hanyalah Tuhan yang bersifat Esa, maka adakah kamu mahu menurut apa yang diwahyukan kepadaku?”', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 109, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', 'فَإِن تَوَلَّوْا فَقُلْ آذَنتُكُمْ عَلَىٰ سَوَاءٍ وَإِنْ أَدْرِي أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', NULL, 'But if they turn away, then say, "I have announced to [all of] you equally. And I know not whether near or far is that which you are promised.', 'Sekiranya mereka berpaling ingkar maka katakanlah: “Aku telah memberitahu kepada kamu (apa yang diwahyukan kepadaku) dengan keterangan yang jelas untuk kita bersama; dan aku tidak mengetahui sama ada (balasan buruk) yang dijanjikan kerana keingkaran kamu itu, sudah dekat atau masih jauh.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 110, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'إِنَّهُ يَعْلَمُ الْجَهْرَ مِنَ الْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', NULL, 'Indeed, He knows what is declared of speech, and He knows what you conceal.', 'Sesungguhnya Allah mengetahui akan perkataan yang kamu sebutkan dengan terus terang, dan juga Ia mengetahui apa yang kamu sembunyikan (di dalam hati).', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 111, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'وَإِنْ أَدْرِي لَعَلَّهُ فِتْنَةٌ لَّكُمْ وَمَتَاعٌ إِلَىٰ حِينٍ', NULL, 'And I know not; perhaps it is a trial for you and enjoyment for a time."', '“Dan aku tidak mengetahui (mengapa dilambatkan balasan buruk yang dijanjikan kepada kamu itu) jangan-jangan lambatnya menjadi satu sebab yang menambahkan azab kamu, dan di samping itu memberi kamu kesenangan hidup hingga ke suatu masa yang tertentu”.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(21, 112, 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'قَالَ رَبِّ احْكُم بِالْحَقِّ وَرَبُّنَا الرَّحْمَٰنُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', NULL, '[The Prophet (ﷺ)] has said, "My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe."', '(Nabi Muhammad merayu dengan) berkata: “Wahai Tuhanku, hukumkanlah (di antara kami dengan mereka) dengan yang benar; dan Tuhan kami ialah Yang Melimpah-limpah rahmatNya yang dipohonkan pertolonganNya terhadap apa yang kamu sifatkan itu”.', FALSE, NULL, NULL, 331, 17, 132, 284, FALSE, 0, NULL),
(22, 1, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ', 'يا ايها الناس اتقوا ربكم ان زلزلة الساعة شيء عظيم', NULL, 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.', 'Wahai umat manusia, bertaqwalah kepada Tuhan kamu! Sesungguhnya gempa hari kiamat itu suatu perkara yang amat besar.', FALSE, NULL, NULL, 332, 17, 133, 285, FALSE, 9, NULL),
(22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَـٰرَىٰ وَمَا هُم بِسُكَـٰرَىٰ وَلَـٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ', 'يوم ترونها تذهل كل مرضعة عما ارضعت وتضع كل ذات حمل حملها وترى الناس سكارى وما هم بسكارى ولكن عذاب الله شديد', NULL, 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allāh is severe.', 'Pada hari kamu melihat (peristiwa-peristiwa yang mengerikan) itu, tiap-tiap ibu penyusu akan melupakan anak yang disusukannya, dan tiap-tiap perempuan yang mengandung akan gugurkan anak yang dikandungnya; dan engkau akan melihat manusia mabuk, padahal mereka sebenarnya tidak mabuk, tetapi azab Allah amatlah berat, mengerikan.', FALSE, NULL, NULL, 332, 17, 133, 285, FALSE, 22, NULL),
(22, 3, 'وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَـٰنٍ مَّرِيدٍ', 'ومن الناس من يجادل في الله بغير علم ويتبع كل شيطان مريد', NULL, 'And of the people is he who disputes about Allāh without knowledge and follows every rebellious devil.', 'Dan ada di antara manusia yang membantah perkara-perkara yang berhubung dengan Allah dengan tidak berdasarkan sebarang pengetahuan, dan ia menurut tiap-tiap syaitan yang telah sebati dengan kejahatan.', FALSE, NULL, NULL, 332, 17, 133, 285, FALSE, 12, NULL),
(22, 4, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'كتب عليه انه من تولاه فانه يضله ويهديه الى عذاب السعير', NULL, 'It has been decreed for him [i.e., every devil] that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.', 'Yang telah ditetapkan kepada (tiap-tiap) syaitan itu, bahawa sesiapa yang berketuakan dia, maka sesungguhnya ia akan menyesatkannya dan memimpinnya kepada azab neraka.', FALSE, NULL, NULL, 332, 17, 133, 285, FALSE, 11, NULL),
(22, 5, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَـٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ ۚ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا ۚ وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'يا ايها الناس ان كنتم في ريب من البعث فانا خلقناكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم ونقر في الارحام ما نشاء الى اجل مسمى ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفى ومنكم من يرد الى ارذل العمر لكيلا يعلم من بعد علم شيئا وترى الارض هامدة فاذا انزلنا عليها الماء اهتزت وربت وانبتت من كل زوج بهيج', NULL, 'O people, if you should be in doubt about the Resurrection, then [consider that] indeed, We created you from dust, then from a sperm-drop, then from a clinging clot, and then from a lump of flesh, formed and unformed - that We may show you. And We settle in the wombs whom We will for a specified term, then We bring you out as a child, and then [We develop you] that you may reach your [time of] maturity. And among you is he who is taken in [early] death, and among you is he who is returned to the most decrepit [old] age so that he knows, after [once having] knowledge, nothing. And you see the earth barren, but when We send down upon it rain, it quivers and swells and grows [something] of every beautiful kind.', 'Wahai umat manusia, sekiranya kamu menaruh syak (ragu-ragu) tentang kebangkitan makhluk (hidup semula pada hari kiamat), maka (perhatilah kepada tingkatan kejadian manusia) kerana sebenarnya Kami telah menciptakan kamu dari tanah, kemudian dari setitik air benih, kemudian dari sebuku darah beku, kemudian dari seketul daging yang disempurnakan kejadiannya dan yang tidak disempurnakan; (Kami jadikan secara yang demikian) kerana Kami hendak menerangkan kepada kamu (kekuasaan Kami); dan Kami pula menetapkan dalam kandungan rahim (ibu yang mengandung itu) apa yang Kami rancangkan hingga ke suatu masa yang ditentukan lahirnya; kemudian Kami mengeluarkan kamu berupa kanak-kanak; kemudian (kamu dipelihara) hingga sampai ke peringkat umur dewasa; dan (dalam pada itu) ada di antara kamu yang dimatikan (semasa kecil atau semasa dewasa) dan ada pula yang dilanjutkan umurnya ke peringkat tua nyanyuk sehingga ia tidak mengetahui lagi akan sesuatu yang telah diketahuinya dahulu. Dan (ingatlah satu bukti lagi); Engkau melihat bumi itu kering, kemudian apabila Kami menurunkan hujan menimpanya, bergeraklah tanahnya (dengan tumbuh-tumbuhan yang merecup tumbuh), dan gembur membusutlah ia, serta ia pula menumbuhkan berjenis-jenis tanaman yang indah permai.', FALSE, NULL, NULL, 332, 17, 133, 285, FALSE, 69, NULL),
(22, 6, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ذلك بان الله هو الحق وانه يحيي الموتى وانه على كل شيء قدير', NULL, 'That is because Allāh is the True Reality and because He gives life to the dead and because He is over all things competent', '(Kedua-dua kenyataan) yang tersebut membuktikan bahawa sesungguhnya Allah jualah Tuhan Yang Sebenar-benarnya (yang berhak disembah), dan sesungguhnya Dia lah yang menghidupkan makhluk-makhluk yang mati, dan Dia lah jua Yang Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 333, 17, 133, 285, FALSE, 13, NULL),
(22, 7, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', 'وان الساعة اتية لا ريب فيها وان الله يبعث من في القبور', NULL, 'And [that they may know] that the Hour is coming - no doubt about it - and that Allāh will resurrect those in the graves.', 'Dan bahawa sesungguhnya hari kiamat itu tetap akan datang, tidak ada sebarang syak padanya, dan bahawa sesungguhnya Allah akan membangkitkan (menghidupkan semula) orang-orang yang di dalam kubur.', FALSE, NULL, NULL, 333, 17, 133, 285, FALSE, 12, NULL),
(22, 8, 'وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَـٰبٍ مُّنِيرٍ', 'ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير', NULL, 'And of the people is he who disputes about Allāh without knowledge or guidance or an enlightening book [from Him],', 'Dan ada di antara manusia yang membantah dalam perkara-perkara yang berhubung dengan Allah dengan tidak berdasarkan sebarang pengetahuan, dan tidak berdasarkan sebarang keterangan, dan tidak juga berdasarkan mana-mana Kitab Allah yang menerangi kebenaran;', FALSE, NULL, NULL, 333, 17, 133, 285, FALSE, 13, NULL),
(22, 9, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ ۖ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَـٰمَةِ عَذَابَ ٱلْحَرِيقِ', 'ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيامة عذاب الحريق', NULL, 'Twisting his neck [in arrogance] to mislead [people] from the way of Allāh. For him in the world is disgrace, and We will make him taste on the Day of Resurrection the punishment of the Burning Fire [while it is said],', 'Ia membantah sambil memalingkan sebelah badannya dengan sombong angkuh sehingga menghalang dirinya dan orang lain dari jalan ugama Allah; ia akan beroleh kehinaan di dunia, dan Kami akan merasakannya azab yang membakar pada hari kiamat kelak;', FALSE, NULL, NULL, 333, 17, 133, 285, FALSE, 15, NULL),
(22, 10, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّـٰمٍ لِّلْعَبِيدِ', 'ذلك بما قدمت يداك وان الله ليس بظلام للعبيد', NULL, '"That is for what your hands have put forth and because Allāh is not ever unjust to [His] servants."', '(Dengan dikatakan kepadanya): “Azab yang demikian ini ialah disebabkan perbuatan tanganmu sendiri, kerana sesungguhnya Allah tidak sekali-kali berlaku zalim kepada hamba-hambaNya”.', FALSE, NULL, NULL, 333, 17, 133, 285, FALSE, 9, NULL),
(22, 11, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍ ۖ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْـَٔاخِرَةَ ۚ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'ومن الناس من يعبد الله على حرف فان اصابه خير اطمان به وان اصابته فتنة انقلب على وجهه خسر الدنيا والاخرة ذلك هو الخسران المبين', NULL, 'And of the people is he who worships Allāh on an edge. If he is touched by good, he is reassured by it; but if he is struck by trial, he turns on his face [to unbelief]. He has lost [this] world and the Hereafter. That is what is the manifest loss.', 'Dan ada di antara manusia yang menyembah Allah dengan sikap dan pendirian yang tidak tetap, iaitu kalau ia beroleh kebaikan, senanglah hatinya dengan keadaan itu; dan kalau pula ia ditimpa fitnah kesusahan, berbaliklah ia semula (kepada kekufurannya). (Dengan sikapnya itu) rugilah ia akan dunia dan akhirat, itulah kerugian yang terang nyata.', FALSE, NULL, NULL, 333, 17, 133, 286, FALSE, 25, NULL),
(22, 12, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ۚ ذَٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلْبَعِيدُ', 'يدعو من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلال البعيد', NULL, 'He invokes instead of Allāh that which neither harms him nor benefits him. That is what is the extreme error.', 'Ia menyeru dan menyembah makhluk-makhluk yang lain dari Allah, yang tidak dapat membahayakannya dan tidak dapat mendatangkan kebaikan kepadanya; itulah kesesatan yang jauh terpesong.', FALSE, NULL, NULL, 333, 17, 133, 286, FALSE, 14, NULL),
(22, 13, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ ۚ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', 'يدعو لمن ضره اقرب من نفعه لبئس المولى ولبئس العشير', NULL, 'He invokes one whose harm is closer than his benefit - how wretched the protector and how wretched the associate.', 'Ia menyeru dan menyembah makhluk yang - dengan perbuatan demikian - mudaratnya lebih dekat dari manfaat yang diharapkannya; demi sesungguhnya seburuk-buruk penolong dan seburuk-buruk sahabat karib ialah makhluk yang diseru dan disembahnya itu.', FALSE, NULL, NULL, 333, 17, 133, 286, FALSE, 10, NULL),
(22, 14, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار ان الله يفعل ما يريد', NULL, 'Indeed, Allāh will admit those who believe and do righteous deeds to gardens beneath which rivers flow. Indeed, Allāh does what He intends.', 'Sesungguhnya Allah akan memasukkan orang-orang yang beriman dan beramal soleh ke dalam Syurga yang mengalir di bawahnya beberapa sungai; sesungguhnya Allah melakukan apa yang ditentukanNya.', FALSE, NULL, NULL, 333, 17, 133, 286, FALSE, 17, NULL),
(22, 15, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 'من كان يظن ان لن ينصره الله في الدنيا والاخرة فليمدد بسبب الى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ', NULL, 'Whoever should think that Allāh will not support him [i.e., Prophet Muḥammad (ﷺ)] in this world and the Hereafter - let him extend a rope to the ceiling, then cut off [his breath], and let him see: will his effort remove that which enrages [him]?', 'Sesiapa yang menyangka bahawa Allah tidak sekali-kali akan menolong Nabi Muhammad dalam dunia ini dan di akhirat kelak, maka hendaklah ia menghulurkan tali (serta mengikatnya) di bumbong rumahnya, kemudian hendaklah ia menjerut lehernya (supaya ia mati tercekek); dalam pada itu hendaklah ia memikirkan lebih dahulu, adakah tipu dayanya itu dapat menghapuskan sebab-sebab yang menimbulkan kemarahannya?', FALSE, NULL, NULL, 333, 17, 133, 286, FALSE, 22, NULL),
(22, 16, 'وَكَذَٰلِكَ أَنزَلْنَـٰهُ ءَايَـٰتٍۭ بَيِّنَـٰتٍ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 'وكذلك انزلناه ايات بينات وان الله يهدي من يريد', NULL, 'And thus have We sent it [i.e., the Qur’ān] down as verses of clear evidence and because Allāh guides whom He intends.', 'Dan demikianlah pula Kami menurunkan Al-Quran itu sebagai ayat-ayat keterangan yang jelas nyata; dan sesungguhnya Allah memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya (menurut peraturan dan undang-undangNya).', FALSE, NULL, NULL, 334, 17, 133, 286, FALSE, 9, NULL),
(22, 17, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّـٰبِـِٔينَ وَٱلنَّصَـٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'ان الذين امنوا والذين هادوا والصابئين والنصارى والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيامة ان الله على كل شيء شهيد', NULL, 'Indeed, those who have believed and those who were Jews and the Sabeans and the Christians and the Magians and those who associated with Allāh - Allāh will judge between them on the Day of Resurrection. Indeed Allāh is, over all things, Witness.', 'Bahawasanya orang-orang yang beriman, dan orang-orang Yahudi, dan orang-orang Saabiein, dan orang-orang Nasrani, dan orang-orang Majusi, serta orang-orang Musyrik, sesungguhnya Allah akan memutuskan hukumNya di antara mereka pada hari kiamat, kerana sesungguhnya Allah sentiasa Memerhati dan Menyaksikan tiap-tiap sesuatu.', FALSE, NULL, NULL, 334, 17, 133, 286, FALSE, 22, NULL),
(22, 18, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌ مِّنَ ٱلنَّاسِ ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ ۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ ۩', 'الم تر ان الله يسجد له من في السماوات ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشاء', NULL, 'Do you not see [i.e., know] that to Allāh prostrates whoever is in the heavens and whoever is on the earth and the sun, the moon, the stars, the mountains, the trees, the moving creatures and many of the people? But upon many the punishment has been justified. And he whom Allāh humiliates - for him there is no bestower of honor. Indeed, Allāh does what He wills.', 'Tidakkah engkau mengetahui bahawa segala yang ada di langit dan di bumi tunduk sujud kepada Allah dan (di antaranya termasuklah) matahari dan bulan, dan bintang-bintang, dan gunung-ganang, dan pokok-pokok kayu, dan binatang-binatang, serta sebahagian besar dari manusia? Dan banyak pula (di antara manusia) yang berhak ditimpa azab (disebabkan kekufurannya dan maksiatnya); dan (ingatlah) sesiapa yang dihinakan oleh Allah maka ia tidak akan beroleh sesiapapun yang dapat memuliakannya. Sesungguhnya Allah tetap melakukan apa yang dirancangkanNya.', FALSE, NULL, NULL, 334, 17, 133, 286, TRUE, 37, NULL),
(22, 19, '۞ هَـٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ ۖ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', 'هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم', NULL, 'These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water', 'Inilah dua golongan (mukmin dan kafir) yang berbantah-bantahan tentang Tuhan mereka. Maka orang-orang yang kafir akan disediakan untuk mereka pakaian dari api neraka, serta dicurahkan atas kepala mereka air panas yang menggelegak,', FALSE, NULL, NULL, 334, 17, 134, 286, FALSE, 17, NULL),
(22, 20, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', 'يصهر به ما في بطونهم والجلود', NULL, 'By which is melted that within their bellies and [their] skins.', 'Yang dengannya dihancurkan apa yang ada dalam perut mereka, dan juga kulit badan mereka.', FALSE, NULL, NULL, 334, 17, 134, 286, FALSE, 6, NULL),
(22, 21, 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍ', 'وَلَهُم مَّقَامِعُ مِنْ حَدِيدٍ', NULL, 'And for [striking] them are maces of iron.', 'Dan mereka pula disediakan batang-batang besi untuk menyeksa mereka.', FALSE, NULL, NULL, 334, 17, 134, 286, FALSE, 0, NULL),
(22, 22, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'كُلَّمَا أَرَادُوا أَن يَخْرُجُوا مِنْهَا مِنْ غَمٍّ أُعِيدُوا فِيهَا وَذُوقُوا عَذَابَ الْحَرِيقِ', NULL, 'Every time they want to get out of it [i.e., Hellfire] from anguish, they will be returned to it, and [it will be said], "Taste the punishment of the Burning Fire!"', 'Tiap-tiap kali mereka hendak keluar dari neraka itu, disebabkan mereka menderita azabnya, mereka dikembalikan padanya, serta dikatakan: “Rasalah kamu azab seksa yang membakar!”', FALSE, NULL, NULL, 334, 17, 134, 286, FALSE, 0, NULL),
(22, 23, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', NULL, 'Indeed, Allāh will admit those who believe and do righteous deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearl, and their garments therein will be silk.', 'Sesungguhnya Allah akan memasukkan orang-orang yang beriman dan beramal soleh ke dalam Syurga yang mengalir padanya beberapa sungai; mereka dihiaskan di situ dengan gelang-gelang emas dan mutiara, dan pakaian mereka di situ dari sutera.', FALSE, NULL, NULL, 334, 17, 134, 287, FALSE, 0, NULL),
(22, 24, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 'وَهُدُوا إِلَى الطَّيِّبِ مِنَ الْقَوْلِ وَهُدُوا إِلَىٰ صِرَاطِ الْحَمِيدِ', NULL, 'And they had been guided [in worldly life] to good speech, and they were guided to the path of the Praiseworthy.', 'Dan mereka diberi petunjuk kepada mengucapkan kata-kata yang baik, serta diberi petunjuk ke jalan Allah Yang Amat Terpuji.', FALSE, NULL, NULL, 335, 17, 134, 287, FALSE, 0, NULL),
(22, 25, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', 'إِنَّ الَّذِينَ كَفَرُوا وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَالْمَسْجِدِ الْحَرَامِ الَّذِي جَعَلْنَاهُ لِلنَّاسِ سَوَاءً الْعَاكِفُ فِيهِ وَالْبَادِ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', NULL, 'Indeed, those who have disbelieved and avert [people] from the way of Allāh and [from] al-Masjid al-Ḥarām, which We made for the people - equal are the resident therein and one from outside - and [also] whoever intends [a deed] therein of deviation [in religion] by wrongdoing - We will make him taste of a painful punishment.', 'Sesungguhnya (amatlah zalim) orang-orang yang kafir serta menghalangi manusia dari jalan Allah (ugama Islam), dan dari memasuki Masjid Al-Haraam (Makkah) yang Kami jadikan dia tempat beribadat untuk seluruh umat manusia (yang beriman) - sama ada yang tinggal menetap di situ atau yang datang berziarah; dan sesiapa yang berazam melakukan di situ sebarang perbuatan yang di larang dengan cara yang zalim, Kami akan merasakannya azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 335, 17, 134, 287, FALSE, 0, NULL),
(22, 26, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'وَإِذْ بَوَّأْنَا لِإِبْرَاهِيمَ مَكَانَ الْبَيْتِ أَن لَّا تُشْرِكْ بِي شَيْئًا وَطَهِّرْ بَيْتِيَ لِلطَّائِفِينَ وَالْقَائِمِينَ وَالرُّكَّعِ السُّجُودِ', NULL, 'And [mention, O Muḥammad], when We designated for Abraham the site of the House, [saying], "Do not associate anything with Me and purify My House for those who perform ṭawāf and those who stand [in prayer] and those who bow and prostrate.', 'Dan (ingatkanlah peristiwa) ketika Kami tentukan bagi Nabi Ibrahim tempat Kaabah (untuk membinanya, lalu Kami berfirman kepadanya): “Janganlah engkau sekutukan sesuatu pun denganKu, dan bersihkanlah rumahKu (Kaabah ini) bagi orang-orang yang tawaf, dan orang-orang yang berdiri dan yang rukuk serta yang sujud (mengerjakan sembahyang).', FALSE, NULL, NULL, 335, 17, 134, 288, FALSE, 0, NULL),
(22, 27, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', 'وَأَذِّن فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', NULL, 'And proclaim to the people the ḥajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -', '“Dan serukanlah umat manusia untuk mengerjakan ibadat Haji, nescaya mereka akan datang ke (rumah Tuhan) mu dengan berjalan kaki, dan dengan menunggang berjenis-jenis unta yang kurus yang datangnya dari berbagai jalan (dan ceruk rantau) yang jauh.', FALSE, NULL, NULL, 335, 17, 134, 288, FALSE, 0, NULL),
(22, 28, 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', 'لِّيَشْهَدُوا مَنَافِعَ لَهُمْ وَيَذْكُرُوا اسْمَ اللَّهِ فِي أَيَّامٍ مَّعْلُومَاتٍ عَلَىٰ مَا رَزَقَهُم مِّن بَهِيمَةِ الْأَنْعَامِ فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ', NULL, 'That they may witness [i.e., attend] benefits for themselves and mention the name of Allāh on known [i.e., specific] days over what He has provided for them of [sacrificial] animals. So eat of them and feed the miserable and poor.', '“Supaya mereka menyaksikan berbagai perkara yang mendatangkan faedah kepada mereka serta memperingati dan menyebut nama Allah, pada hari-hari yang tertentu, kerana pengurniaanNya kepada mereka dengan binatang-binatang ternak (untuk dijadikan korban); dengan yang demikian makanlah kamu dari (daging) binatang-binatang korban itu dan berilah makan kepada orang yang susah, yang fakir miskin.', FALSE, NULL, NULL, 335, 17, 134, 288, FALSE, 0, NULL),
(22, 29, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', 'ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ', NULL, 'Then let them end their untidiness and fulfill their vows and perform ṭawāf around the ancient House."', '“Kemudian hendaklah mereka membersihkan dirinya dan hendaklah mereka menyempurnakan nazar-nazarnya, dan hendaklah mereka tawaf akan Baitullah (Kaabah) yang tua sejarahnya itu”.', FALSE, NULL, NULL, 335, 17, 134, 288, FALSE, 0, NULL),
(22, 30, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَاتِ اللَّهِ فَهُوَ خَيْرٌ لَّهُ عِندَ رَبِّهِ وَأُحِلَّتْ لَكُمُ الْأَنْعَامُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ', NULL, 'That [has been commanded], and whoever honors the sacred ordinances of Allāh - it is best for him in the sight of his Lord. And permitted to you are the grazing livestock, except what is recited to you. So avoid the uncleanliness of idols and avoid false statement,', 'Itulah yang wajib dipatuhi; dan sesiapa yang menghormati hukum-hukum Allah maka yang demikian menjadi kebaikan baginya di sisi Tuhannya. Dan dihalalkan bagi kamu binatang-binatang ternak, kecuali yang dibacakan kepada kamu (tentang haramnya), maka jauhilah kekotoran syirik yang disebabkan oleh penyembahan berhala, serta jauhilah perkataan yang dusta, -', FALSE, NULL, NULL, 335, 17, 134, 288, FALSE, 0, NULL),
(22, 31, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍ سَحِيقٍ', 'حُنَفَاءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِ وَمَن يُشْرِكْ بِاللَّهِ فَكَأَنَّمَا خَرَّ مِنَ السَّمَاءِ فَتَخْطَفُهُ الطَّيْرُ أَوْ تَهْوِي بِهِ الرِّيحُ فِي مَكَانٍ سَحِيقٍ', NULL, 'Inclining [only] to Allāh, not associating [anything] with Him. And he who associates with Allāh - it is as though he had fallen from the sky and was snatched by the birds or the wind carried him down into a remote place.', '(Amalkanlah perkara-perkara itu) dengan tulus ikhlas kepada Allah, serta tidak mempersekutukan sesuatu pun denganNya; dan sesiapa yang mempersekutukan sesuatu yang lain dengan Allah maka seolah-olah dia jatuh dari langit lalu disambar oleh burung, atau dihumbankan oleh angin ke tempat yang jauh (yang membinasakan).', FALSE, NULL, NULL, 336, 17, 134, 288, FALSE, 0, NULL),
(22, 32, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَائِرَ اللَّهِ فَإِنَّهَا مِن تَقْوَى الْقُلُوبِ', NULL, 'That [is so]. And whoever honors the symbols [i.e., rites] of Allāh - indeed, it is from the piety of hearts.', 'Demikianlah (ajaran Allah); dan sesiapa yang menghormati Syiar-syiar ugama Allah maka (dia lah orang yang bertaqwa) kerana sesungguhnya perbuatan itu satu kesan dari sifat-sifat taqwa hati orang mukmin.', FALSE, NULL, NULL, 336, 17, 134, 288, FALSE, 0, NULL),
(22, 33, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', 'لَكُمْ فِيهَا مَنَافِعُ إِلَىٰ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَا إِلَى الْبَيْتِ الْعَتِيقِ', NULL, 'For you therein [i.e., the animals marked for sacrifice] are benefits for a specified term; then their place of sacrifice is at the ancient House.', 'Kamu beroleh berbagai-bagai faedah dan kegunaan pada binatang ternak itu hingga ke suatu masa yang tertentu (bagi menyembelihnya); kemudian waktu menyembelihnya ketika sampai di tanah haram Baitullah yang tua sejarahnya itu.', FALSE, NULL, NULL, 336, 17, 134, 288, FALSE, 0, NULL),
(22, 34, 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا۟ وَبَشِّرِ ٱلْمُخْبِتِينَ', 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا اسْمَ اللَّهِ عَلَىٰ مَا رَزَقَهُم مِّن بَهِيمَةِ الْأَنْعَامِ فَإِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَلَهُ أَسْلِمُوا وَبَشِّرِ الْمُخْبِتِينَ', NULL, 'And for every [religious] community We have appointed a rite [of sacrifice] that they may mention the name of Allāh over what He has provided for them of [sacrificial] animals. For your god is one God, so to Him submit. And, [O Muḥammad], give good tidings to the humble [before their Lord]', 'Dan bagi tiap-tiap umat, Kami syariatkan ibadat menyembelih korban (atau lain-lainnya) supaya mereka menyebut nama Allah sebagai bersyukur akan pengurniaanNya kepada mereka; binatang-binatang ternak yang disembelih itu. Kerana Tuhan kamu semua ialah Tuhan Yang Maha Esa, maka hendaklah kamu tunduk taat kepadaNya; dan sampaikanlah berita gembira (wahai Muhammad) kepada orang-orang yang tunduk taat -', FALSE, NULL, NULL, 336, 17, 134, 289, FALSE, 0, NULL),
(22, 35, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَالصَّابِرِينَ عَلَىٰ مَا أَصَابَهُمْ وَالْمُقِيمِي الصَّلَاةِ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ', NULL, 'Who, when Allāh is mentioned, their hearts are fearful, and [to] the patient over what has afflicted them, and the establishers of prayer and those who spend from what We have provided them.', 'Iaitu orang-orang yang apabila disebut nama Allah, gerun gementarlah hati mereka, dan orang-orang yang sabar (cekal hati) terhadap kesusahan yang menimpa mereka, dan orang-orang yang mendirikan sembahyang, serta orang-orang yang mendermakan sebahagian dari rezeki yang Kami berikan kepadanya.', FALSE, NULL, NULL, 336, 17, 134, 289, FALSE, 0, NULL),
(22, 36, 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'وَالْبُدْنَ جَعَلْنَاهَا لَكُم مِّن شَعَائِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَافَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَاهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And the camels and cattle We have appointed for you as among the symbols [i.e., rites] of Allāh; for you therein is good. So mention the name of Allāh upon them when lined up [for sacrifice]; and when they are [lifeless] on their sides, then eat from them and feed the needy [who does not seek aid] and the beggar. Thus have We subjected them to you that you may be grateful.', 'Dan Kami jadikan unta (yang dihadiahkan kepada fakir miskin Makkah itu) sebahagian dari syiar ugama Allah untuk kamu; pada menyembelih unta yang tersebut ada kebaikan bagi kamu; oleh itu sebutlah nama Allah (semasa menyembelihnya) ketika ia berdiri di atas tiga kakinya maka apabila ia tumbang (serta putus nyawanya), makanlah sebahagian daripadanya, dan berilah (bahagian yang lain) kepada orang-orang yang tidak meminta dan yang meminta. Demikianlah Kami mudahkan dia untuk kamu (menguasainya dan menyembelihnya) supaya kamu bersyukur.', FALSE, NULL, NULL, 336, 17, 134, 289, FALSE, 0, NULL),
(22, 37, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَبَشِّرِ ٱلْمُحْسِنِينَ', 'لَن يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِن يَنَالُهُ التَّقْوَىٰ مِنكُمْ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا اللَّهَ عَلَىٰ مَا هَدَاكُمْ وَبَشِّرِ الْمُحْسِنِينَ', NULL, 'Their meat will not reach Allāh, nor will their blood, but what reaches Him is piety from you. Thus have We subjected them to you that you may glorify Allāh for that [to] which He has guided you; and give good tidings to the doers of good.', 'Daging dan darah binatang korban atau hadiah itu tidak sekali-kali akan sampai kepada Allah, tetapi yang sampai kepadaNya ialah amal yang ikhlas yang berdasarkan taqwa dari kamu. Demikianlah Ia memudahkan binatang-binatang itu bagi kamu supaya kamu membesarkan Allah kerana mendapat nikmat petunjukNya. Dan sampaikanlah berita gembira (dengan balasan yang sebaik-baiknya) kepada orang-orang yang berusaha supaya baik amalnya.', FALSE, NULL, NULL, 336, 17, 134, 289, FALSE, 0, NULL),
(22, 38, 'إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', 'إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', NULL, 'Indeed, Allāh defends those who have believed. Indeed, Allāh does not like everyone treacherous and ungrateful.', 'Sesungguhnya Allah membela orang-orang yang beriman; sesungguhnya Allah tidak suka kepada tiap-tiap seorang yang khianat, lagi tidak bersyukur.', FALSE, NULL, NULL, 336, 17, 135, 289, FALSE, 0, NULL),
(22, 39, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', 'أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', NULL, 'Permission [to fight] has been given to those who are being fought, because they were wronged. And indeed, Allāh is competent to give them victory.', 'Diizinkan berperang bagi orang-orang (Islam) yang diperangi (oleh golongan penceroboh), kerana sesungguhnya mereka telah dianiaya; dan sesungguhnya Allah Amat Berkuasa untuk menolong mereka (mencapai kemenangan).', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 40, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًا وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'الَّذِينَ أُخْرِجُوا مِن دِيَارِهِم بِغَيْرِ حَقٍّ إِلَّا أَن يَقُولُوا رَبُّنَا اللَّهُ وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَامِعُ وَبِيَعٌ وَصَلَوَاتٌ وَمَسَاجِدُ يُذْكَرُ فِيهَا اسْمُ اللَّهِ كَثِيرًا وَلَيَنصُرَنَّ اللَّهُ مَن يَنصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ', NULL, '[They are] those who have been evicted from their homes without right - only because they say, "Our Lord is Allāh." And were it not that Allāh checks the people, some by means of others, there would have been demolished monasteries, churches, synagogues, and mosques in which the name of Allāh is much mentioned [i.e., praised]. And Allāh will surely support those who support Him [i.e., His cause]. Indeed, Allāh is Powerful and Exalted in Might.', 'Iaitu mereka yang diusir dari kampung halamannya dengan tidak berdasarkan sebarang alasan yang benar, (mereka diusir) semata-mata kerana mereka berkata: “Tuhan kami ialah Allah”. Dan kalaulah Allah tidak mendorong setengah manusia menentang pencerobohan setengahnya yang lain, nescaya runtuhlah tempat-tempat pertapaan serta gereja-gereja (kaum Nasrani), dan tempat-tempat sembahyang (kaum Yahudi), dan juga masjid-masjid (orang Islam) yang sentiasa disebut nama Allah banyak-banyak padanya dan sesungguhnya Allah akan menolong sesiapa yang menolong ugamaNya (ugama Islam); sesungguhnya Allah Maha Kuat, lagi Maha Kuasa; -', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 41, 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'الَّذِينَ إِن مَّكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنكَرِ وَلِلَّهِ عَاقِبَةُ الْأُمُورِ', NULL, '[And they are] those who, if We give them authority in the land, establish prayer and give zakāh and enjoin what is right and forbid what is wrong. And to Allāh belongs the outcome of [all] matters.', 'Iaitu mereka (umat Islam) yang jika Kami berikan mereka kekuasaan memerintah di bumi nescaya mereka mendirikan sembahyang serta memberi zakat, dan mereka menyuruh berbuat kebaikan serta melarang dari melakukan kejahatan dan perkara yang mungkar. Dan (ingatlah) bagi Allah jualah kesudahan segala urusan.', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 42, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', NULL, 'And if they deny you, [O Muḥammad] - so, before them, did the people of Noah and ʿAad and Thamūd deny [their prophets],', 'Dan jika mereka (yang kafir itu) mendustakanmu (wahai Muhammad), maka (yang demikian tidaklah pelik) kerana sesungguhnya sebelum mereka: Kaum Nabi Nuh, dan Aad (kaum Nabi Hud), serta Thamud (kaum Nabi Soleh) telah juga mendustakan Rasul masing-masing;', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 43, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ', 'وَقَوْمُ إِبْرَاهِيمَ وَقَوْمُ لُوطٍ', NULL, 'And the people of Abraham and the people of Lot', 'Dan (demikian juga) kaum Nabi Ibrahim dan kaum Nabi Lut;', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 44, 'وَأَصْحَٰبُ مَدْيَنَ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ نَكِيرِ', 'وَأَصْحَابُ مَدْيَنَ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَافِرِينَ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ نَكِيرِ', NULL, 'And the inhabitants of Madyan. And Moses was denied, so I prolonged enjoyment for the disbelievers; then I seized them, and how [terrible] was My reproach.', 'Dan juga penduduk Madyan; dan Nabi Musa juga telah didustakan; maka Aku memberi tempoh kepada orang-orang kafir itu, kemudian Aku menimpakan mereka dengan azab seksa. Dengan yang demikian perhatikanlah bagaimana buruknya kesan kemurkaanKu.', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 45, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَاهَا وَهِيَ ظَالِمَةٌ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', NULL, 'And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace.', 'Maka bukan sedikit negeri-negeri yang Kami binasakan dengan sebab kezaliman penduduknya, lalu runtuh ranaplah bangunan-bangunannya; dan bukan sedikit pula telaga yang telah terbiar, dan istana yang tersergam (telah kosong, ditinggalkan).', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 46, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', 'أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا أَوْ آذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَٰكِن تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ', NULL, 'So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts.', 'Oleh itu, bukankah ada baiknya mereka mengembara di muka bumi supaya - dengan melihat kesan-kesan yang tersebut - mereka menjadi orang-orang yang ada hati yang dengannya mereka dapat memahami, atau ada telinga yang dengannya mereka dapat mendengar? (Tetapi kalaulah mereka mengembara pun tidak juga berguna) kerana keadaan yang sebenarnya bukanlah mata kepala yang buta, tetapi yang buta itu ialah mata hati yang ada di dalam dada.', FALSE, NULL, NULL, 337, 17, 135, 290, FALSE, 0, NULL),
(22, 47, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ وَلَن يُخْلِفَ اللَّهُ وَعْدَهُ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', NULL, 'And they urge you to hasten the punishment. But Allāh will never fail in His promise. And indeed, a day with your Lord is like a thousand years of those which you count.', 'Dan mereka meminta kepadamu (wahai Muhammad) menyegerakan kedatangan azab, padahal Allah tidak sekali-kali akan memungkiri janjiNya; dan (katakanlah kepada mereka): sesungguhnya satu hari dari hari-hari azab di sisi Tuhanmu adalah menyamai seribu tahun dari yang kamu hitung.', FALSE, NULL, NULL, 338, 17, 135, 290, FALSE, 0, NULL),
(22, 48, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِيَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَيَّ الْمَصِيرُ', NULL, 'And for how many a city did I prolong enjoyment while it was committing wrong. Then I seized it, and to Me is the [final] destination.', 'Dan bukan sedikit negeri-negeri yang Aku beri tempoh, sedang penduduknya berlaku zalim; kemudian Aku menimpakannya dengan azab seksa; dan (ingatlah) kepada Akulah tempat kembali.', FALSE, NULL, NULL, 338, 17, 135, 290, FALSE, 0, NULL),
(22, 49, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ', 'قُلْ يَا أَيُّهَا النَّاسُ إِنَّمَا أَنَا لَكُمْ نَذِيرٌ مُّبِينٌ', NULL, 'Say, "O people, I am only to you a clear warner."', 'Katakanlah (wahai Muhammad): “Wahai sekalian manusia, aku tidak lain hanyalah seorang Rasul pemberi amaran yang menjelaskan keterangan-keterangan kepada kamu”.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 50, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'فَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', NULL, 'And those who have believed and done righteous deeds - for them is forgiveness and noble provision.', 'Maka orang-orang yang beriman dan beramal soleh akan beroleh keampunan dan limpah kurnia yang mulia.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 51, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'وَالَّذِينَ سَعَوْا فِي آيَاتِنَا مُعَاجِزِينَ أُولَٰئِكَ أَصْحَابُ الْجَحِيمِ', NULL, 'But the ones who strove against Our verses, [seeking] to cause failure - those are the companions of Hellfire.', 'Dan (sebaliknya) orang-orang yang berusaha menentang dan membatalkan ayat-ayat keterangan Kami, mereka itulah ahli neraka.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 52, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'وَمَا أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِيٍّ إِلَّا إِذَا تَمَنَّىٰ أَلْقَى الشَّيْطَانُ فِي أُمْنِيَّتِهِ فَيَنسَخُ اللَّهُ مَا يُلْقِي الشَّيْطَانُ ثُمَّ يُحْكِمُ اللَّهُ آيَاتِهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'And We did not send before you any messenger or prophet except that when he spoke [or recited], Satan threw into it [some misunderstanding]. But Allāh abolishes that which Satan throws in; then Allāh makes precise His verses. And Allāh is Knowing and Wise.', 'Dan tidaklah Kami mengutuskan sebelummu seorang Rasul atau seorang Nabi melainkan apabila ia bercita-cita (supaya kaumnya beriman kepada ugama Allah yang dibawanya), maka Syaitan pun melemparkan hasutannya mengenai usaha Rasul atau Nabi itu mencapai cita-citanya; oleh itu, Allah segera menghapuskan apa yang telah diganggu oleh Syaitan, kemudian Allah menetapkan ayat-ayatNya dengan kukuhnya; dan Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 53, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْقَاسِيَةِ قُلُوبُهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍ', 'لِّيَجْعَلَ مَا يُلْقِي الشَّيْطَانُ فِتْنَةً لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ وَالْقَاسِيَةِ قُلُوبُهُمْ وَإِنَّ الظَّالِمِينَ لَفِي شِقَاقٍ بَعِيدٍ', NULL, '[That is] so He may make what Satan throws in [i.e., asserts] a trial for those within whose hearts is disease and those hard of heart. And indeed, the wrongdoers are in extreme dissension.', '(Yang demikian) kerana Allah hendak menjadikan hasutan Syaitan itu sebagai satu fitnah cubaan bagi orang-orang yang ada penyakit kufur ingkar dalam hati mereka, dan yang hatinya keras membatu; dan sesungguhnya mereka yang zalim itu sentiasa berada dalam pertentangan yang jauh dari kebenaran.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 54, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَلِيَعْلَمَ الَّذِينَ أُوتُوا الْعِلْمَ أَنَّهُ الْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا بِهِ فَتُخْبِتَ لَهُ قُلُوبُهُمْ وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And so those who were given knowledge may know that it is the truth from your Lord and [therefore] believe in it, and their hearts humbly submit to it. And indeed is Allāh the Guide of those who have believed to a straight path.', 'Dan juga supaya orang-orang yang beroleh ilmu mengetahui bahawa ayat-ayat keterangan itu benar dari Tuhanmu, lalu mereka beriman kepadanya, sehingga tunduk taatlah hati mereka mematuhinya; dan sesungguhnya Allah sentiasa memimpin orang-orang yang beriman ke jalan yang lurus.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 55, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', 'وَلَا يَزَالُ الَّذِينَ كَفَرُوا فِي مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', NULL, 'But those who disbelieve will not cease to be in doubt of it until the Hour comes upon them unexpectedly or there comes to them the punishment of a barren Day.', 'Dan orang-orang kafir tetap di dalam keraguan terhadap Al-Quran hingga datang kepada mereka saat kiamat secara mengejut, atau datang kepada mereka azab hari yang tidak ada kebaikan untuk mereka.', FALSE, NULL, NULL, 338, 17, 135, 291, FALSE, 0, NULL),
(22, 56, 'ٱلْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', 'الْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ فَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فِي جَنَّاتِ النَّعِيمِ', NULL, '[All] sovereignty that Day is for Allāh; He will judge between them. So they who believed and did righteous deeds will be in the Gardens of Pleasure.', 'Kuasa pemerintahan pada hari kiamat itu tertentu bagi Allah. Ia akan menghukum di antara mereka. Maka orang-orang yang beriman dan beramal soleh ditempatkan di dalam Syurga yang penuh dengan segala nikmat dan kesenangan;', FALSE, NULL, NULL, 339, 17, 135, 291, FALSE, 0, NULL),
(22, 57, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا فَأُولَٰئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', NULL, 'And they who disbelieved and denied Our signs - for those there will be a humiliating punishment.', 'Dan orang-orang yang kafir serta mendustakan ayat-ayat keterangan kami, maka mereka beroleh azab seksa yang menghina.', FALSE, NULL, NULL, 339, 17, 135, 291, FALSE, 0, NULL),
(22, 58, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًا وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'وَالَّذِينَ هَاجَرُوا فِي سَبِيلِ اللَّهِ ثُمَّ قُتِلُوا أَوْ مَاتُوا لَيَرْزُقَنَّهُمُ اللَّهُ رِزْقًا حَسَنًا وَإِنَّ اللَّهَ لَهُوَ خَيْرُ الرَّازِقِينَ', NULL, 'And those who emigrated for the cause of Allāh and then were killed or died - Allāh will surely provide for them a good provision. And indeed, it is Allāh who is the best of providers.', 'Dan orang-orang yang berhijrah pada jalan Allah, kemudian mereka terbunuh atau mati, sudah tentu Allah akan mengurniakan kepada mereka limpah kurnia yang baik. Dan (ingatlah) sesungguhnya Allah adalah sebaik-baik pemberi limpah kurnia.', FALSE, NULL, NULL, 339, 17, 135, 292, FALSE, 0, NULL),
(22, 59, 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌ', 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُ وَإِنَّ اللَّهَ لَعَلِيمٌ حَلِيمٌ', NULL, 'He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allāh is Knowing and Forbearing.', 'Sudah tentu Allah akan memasukkan mereka (yang tersebut itu) ke tempat yang mereka sukai (Syurga), dan sesungguhnya Allah Maha Mengetahui, lagi Maha Penyabar.', FALSE, NULL, NULL, 339, 17, 135, 292, FALSE, 0, NULL),
(22, 60, 'ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', 'ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِ ثُمَّ بُغِيَ عَلَيْهِ لَيَنصُرَنَّهُ اللَّهُ إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ', NULL, 'That [is so]. And whoever responds [to injustice] with the equivalent of that with which he was harmed and then is tyrannized - Allāh will surely aid him. Indeed, Allāh is Pardoning and Forgiving.', 'Demikianlah (janji balasan Allah yang melimpah-limpah itu). Dan sesiapa yang membalas kejahatan orang, sama seperti yang dilakukan kepadanya, kemudian ia dianiaya lagi, demi sesungguhnya Allah akan menolongnya. (Dalam pada itu ingatlah) sesungguhnya Allah Maha Pemaaf, lagi Maha Pengampun.', FALSE, NULL, NULL, 339, 17, 136, 292, FALSE, 0, NULL),
(22, 61, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'ذَٰلِكَ بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَأَنَّ اللَّهَ سَمِيعٌ بَصِيرٌ', NULL, 'That is because Allāh causes the night to enter the day and causes the day to enter the night and because Allāh is Hearing and Seeing.', '(Pertolongan yang dijanjikan Allah tetap berlaku) kerana Allah berkuasa menukar gantikan sesuatu keadaan sebagaimana kuasaNya memasukkan malam pada siang dan memasukkan siang pada malam (silih berganti); dan (ingatlah) sesungguhnya Allah Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 339, 17, 136, 292, FALSE, 0, NULL),
(22, 62, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ هُوَ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ', NULL, 'That is because Allāh is the True Reality, and that which they call upon other than Him is falsehood, and because Allāh is the Most High, the Grand.', 'Bersifatnya Allah dengan kekuasaan dan luas ilmu pengetahuan itu kerana bahawasanya Allah, Dia lah sahaja Tuhan Yang Sebenar-benarnya, dan bahawa segala yang mereka sembah selain dari Allah itulah yang nyata palsunya. Dan (ingatlah) sesungguhnya Allah jualah Yang Maha Tinggi keadaanNya, lagi Maha Besar (kekuasaanNya)', FALSE, NULL, NULL, 339, 17, 136, 292, FALSE, 0, NULL),
(22, 63, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَتُصْبِحُ الْأَرْضُ مُخْضَرَّةً إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ', NULL, 'Do you not see that Allāh has sent down rain from the sky and the earth becomes green? Indeed, Allāh is Subtle and Aware.', 'Tidakkah engkau melihat bahawa Allah telah menurunkan hujan dari langit, lalu menjadilah bumi ini hijau subur (dengan sebabnya)? Sesungguhnya Allah Maha Halus serta lemah-lembut (urusan tadbirNya), lagi Maha Mendalam pengetahuanNya (akan hal-ehwal sekalian makhlukNya).', FALSE, NULL, NULL, 339, 17, 136, 292, FALSE, 0, NULL),
(22, 64, 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَإِنَّ اللَّهَ لَهُوَ الْغَنِيُّ الْحَمِيدُ', NULL, 'To Him belongs what is in the heavens and what is on the earth. And indeed, Allāh is the Free of need, the Praiseworthy.', 'Segala yang ada di langit dan di bumi adalah kepunyaanNya. Dan sesungguhnya Allah, Dia lah jua Yang Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 339, 17, 136, 292, FALSE, 0, NULL),
(22, 65, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', 'أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي الْأَرْضِ وَالْفُلْكَ تَجْرِي فِي الْبَحْرِ بِأَمْرِهِ وَيُمْسِكُ السَّمَاءَ أَن تَقَعَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِ إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ', NULL, 'Do you not see that Allāh has subjected to you whatever is on the earth and the ships which run through the sea by His command? And He restrains the sky from falling upon the earth, unless by His permission. Indeed Allāh, to the people, is Kind and Merciful.', 'Tidakkah engkau melihat bahawa Allah telah memudahkan apa yang ada di bumi untuk kegunaan kamu, dan (demikian juga) kapal-kapal yang belayar di laut dengan perintahNya? Dan Ia pula menahan langit daripada runtuh menimpa bumi, kecuali dengan izinNya; sesungguhnya Allah Amat melimpah belas kasihanNya dan rahmatNya kepada umat manusia.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 66, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ', 'وَهُوَ الَّذِي أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ إِنَّ الْإِنسَانَ لَكَفُورٌ', NULL, 'And He is the one who gave you life; then He causes you to die and then will [again] give you life. Indeed, mankind is ungrateful.', 'Dan Dia lah yang menghidupkan kamu, kemudian Ia mematikan kamu, kemudian Ia menghidupkan kamu semula. Sesungguhnya manusia sangatlah tidak bersyukur.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 67, 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ وَٱدْعُ إِلَىٰ رَبِّكَ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ فَلَا يُنَازِعُنَّكَ فِي الْأَمْرِ وَادْعُ إِلَىٰ رَبِّكَ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', NULL, 'For every [religious] community We have appointed rites which they perform. So, [O Muḥammad], let them [i.e., the disbelievers] not contend with you over the matter but invite [them] to your Lord. Indeed, you are upon straight guidance.', 'Bagi tiap-tiap umat, Kami adakan satu syariat yang tertentu untuk mereka ikuti dan jalankan, maka janganlah ahli-ahli syariat yang lain membantahmu dalam urusan syariaatmu; dan serulah (wahai Muhammad) umat manusia kepada ugama Tuhanmu, kerana sesungguhnya engkau adalah berada di atas jalan yang lurus.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 68, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', 'وَإِن جَادَلُوكَ فَقُلِ اللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', NULL, 'And if they dispute with you, then say, "Allāh is most knowing of what you do.', 'Dan jika mereka mengemukakan bantahan kepadamu, maka katakanlah: “Allah Amat” mengetahui akan apa yang kamu lakukan.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 69, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'اللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيَامَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', NULL, 'Allāh will judge between you on the Day of Resurrection concerning that over which you used to differ."', '“Allah akan menghukum di antara kamu semua pada hari kiamat, mengenai apa yang kamu berselisihan padanya”.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 70, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'أَلَمْ تَعْلَمْ أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاءِ وَالْأَرْضِ إِنَّ ذَٰلِكَ فِي كِتَابٍ إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ', NULL, 'Do you not know that Allāh knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allāh, is easy.', 'Bukankah engkau telah mengetahui bahawasanya Allah mengetahui segala yang ada di langit dan di bumi? Sesungguhnya yang demikian itu ada tertulis di dalam Kitab (Lauh Mahfuz); sesungguhnya hal itu amatlah mudah bagi Allah.', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 71, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', 'وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَمَا لَيْسَ لَهُم بِهِ عِلْمٌ وَمَا لِلظَّالِمِينَ مِن نَّصِيرٍ', NULL, 'And they worship besides Allāh that for which He has not sent down authority and that of which they have no knowledge. And there will not be for the wrongdoers any helper.', 'Dan mereka menyembah yang lain dari Allah iaitu benda-benda yang Allah tidak menurunkan sebarang keterangan membenarkannya, dan yang mereka tidak mempunyai sebarang pengetahuan mengenainya dan (ingatlah) tiadalah bagi orang-orang yang zalim (dengan perbuatan syirik) itu sesiapapun yang dapat memberikan pertolongan (di dunia dan di akhirat).', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 72, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ وَبِئْسَ ٱلْمَصِيرُ', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ تَعْرِفُ فِي وُجُوهِ الَّذِينَ كَفَرُوا الْمُنكَرَ يَكَادُونَ يَسْطُونَ بِالَّذِينَ يَتْلُونَ عَلَيْهِمْ آيَاتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ النَّارُ وَعَدَهَا اللَّهُ الَّذِينَ كَفَرُوا وَبِئْسَ الْمَصِيرُ', NULL, 'And when Our verses are recited to them as clear evidences, you recognize in the faces of those who disbelieve disapproval. They are almost on the verge of assaulting those who recite to them Our verses. Say, "Then shall I inform you of [what is] worse than that? [It is] the Fire which Allāh has promised those who disbelieve, and wretched is the destination."', 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas nyata, engkau akan dapat melihat pada muka orang-orang yang kafir itu tanda marah dan benci, hampir-hampir mereka hendak menerkam dan menyerang orang-orang yang membacakan ayat-ayat Kami kepada mereka. Katakanlah (wahai Muhammad): “Jika demikian, mahukah, aku khabarkan kepada kamu: yang lebih buruk lagi daripada apa yang telah menyebabkan kemarahan kamu itu? Ialah neraka yang telah dijanjikan oleh Allah kepada orang-orang yang kafir, dan itulah seburuk-buruk tempat kembali!”', FALSE, NULL, NULL, 340, 17, 136, 293, FALSE, 0, NULL),
(22, 73, 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', 'يَا أَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُ إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَن يَخْلُقُوا ذُبَابًا وَلَوِ اجْتَمَعُوا لَهُ وَإِن يَسْلُبْهُمُ الذُّبَابُ شَيْئًا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ', NULL, 'O people, an example is presented, so listen to it. Indeed, those you invoke besides Allāh will never create [as much as] a fly, even if they gathered together for it [i.e., that purpose]. And if the fly should steal from them a [tiny] thing, they could not recover it from him. Weak are the pursuer and pursued.', 'Wahai umat manusia, inilah diberikan satu misal perbandingan, maka dengarlah mengenainya dengan bersungguh-sungguh. Sebenarnya mereka yang kamu seru dan sembah, yang lain dari Allah itu, tidak sekali-kali akan dapat mencipta seekor lalat walaupun mereka berhimpun beramai-ramai untuk membuatnya; dan jika lalat itu mengambil sesuatu dari mereka, mereka tidak dapat mengambilnya balik daripadanya. (Kedua-duanya lemah belaka), lemah yang meminta (dari mendapat hajatnya), dan lemah yang diminta (daripada menunaikannya).', FALSE, NULL, NULL, 341, 17, 136, 294, FALSE, 0, NULL),
(22, 74, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ', NULL, 'They have not appraised Allāh with true appraisal. Indeed, Allāh is Powerful and Exalted in Might.', 'Mereka (yang kafir musyrik) itu tidak menghormati Allah menurut penghormatan yang selayaknya (sebagaimana yang ditetapkanNya); sesungguhnya Allah adalah Maha Kuat, lagi Maha Kuasa.', FALSE, NULL, NULL, 341, 17, 136, 294, FALSE, 0, NULL),
(22, 75, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًا وَمِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ', NULL, 'Allāh chooses from the angels messengers and from the people. Indeed, Allāh is Hearing and Seeing.', 'Allah memilih utusan-utusanNya dari malaikat dan dari manusia; sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 341, 17, 136, 294, FALSE, 0, NULL),
(22, 76, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ', NULL, 'He knows what is [presently] before them and what will be after them. And to Allāh will be returned [all] matters.', 'Ia mengetahui apa yang ada di hadapan mereka dan apa yang ada di belakang mereka; dan kepada Allah jualah kembalinya segala urusan.', FALSE, NULL, NULL, 341, 17, 136, 294, FALSE, 0, NULL),
(22, 77, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'O you who have believed, bow and prostrate and worship your Lord and do good - that you may succeed.', 'Wahai orang-orang yang beriman, rukuklah serta sujudlah (mengerjakan sembahyang), dan beribadatlah kepada Tuhan kamu (dengan mentauhidkanNya), serta kerjakanlah amal-amal kebajikan; supaya kamu berjaya (di dunia dan di akhirat).', FALSE, NULL, NULL, 341, 17, 136, 294, TRUE, 0, NULL),
(22, 78, 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ مِّلَّةَ أَبِيكُمْ إِبْرَاهِيمَ هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِن قَبْلُ وَفِي هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ فَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلَاكُمْ فَنِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ', NULL, 'And strive for Allāh with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. He [i.e., Allāh] named you "Muslims" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakāh and hold fast to Allāh. He is your protector; and excellent is the protector, and excellent is the helper.', 'Dan berjihadlah kamu pada jalan Allah dengan jihad yang sebenar-benarnya Dia lah yang memilih kamu (untuk mengerjakan suruhan ugamanya); dan Ia tidak menjadikan kamu menanggung sesuatu keberatan dan susah payah dalam perkara ugama, ugama bapa kamu Ibrahim. Ia menamakan kamu: “orang-orang Islam” semenjak dahulu dan di dalam (Al-Quran) ini, supaya Rasulullah (Muhammad) menjadi saksi yang menerangkan kebenaran perbuatan kamu, dan supaya kamu pula layak menjadi orang-orang yang memberi keterangan kepada umat manusia (tentang yang benar dan yang salah). Oleh itu, dirikanlah sembahyang, dan berilah zakat, serta berpegang teguhlah kamu kepada Allah! Dia lah Pelindung kamu. Maka (Allah yang demikian sifatNya) Dia lah sahaja sebaik-baik Pelindung dan sebaik-baik Pemberi pertolongan.', FALSE, NULL, NULL, 341, 17, 136, 294, FALSE, 0, NULL),
(23, 1, 'قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', 'قد افلح المؤمنون', NULL, 'Certainly will the believers have succeeded:', 'Sesungguhnya berjayalah orang-orang yang beriman,', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 3, NULL),
(23, 2, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَـٰشِعُونَ', 'الذين هم في صلاتهم خاشعون', NULL, 'They who are during their prayer humbly intent', 'Iaitu mereka yang khusyuk dalam sembahyangnya;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 3, 'وَٱلَّذِينَ هُمْ عَنِ ٱللَّغْوِ مُعْرِضُونَ', 'والذين هم عن اللغو معرضون', NULL, 'And they who turn away from ill speech', 'Dan mereka yang menjauhkan diri dari perbuatan dan perkataan yang sia-sia;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 4, 'وَٱلَّذِينَ هُمْ لِلزَّكَوٰةِ فَـٰعِلُونَ', 'والذين هم للزكاة فاعلون', NULL, 'And they who are observant of zakāh', 'Dan mereka yang berusaha membersihkan hartanya (dengan menunaikan zakat harta itu);', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 4, NULL),
(23, 5, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَـٰفِظُونَ', 'والذين هم لفروجهم حافظون', NULL, 'And they who guard their private parts', 'Dan mereka yang menjaga kehormatannya, -', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 4, NULL),
(23, 6, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين', NULL, 'Except from their wives or those their right hands possess, for indeed, they will not be blamed -', 'Kecuali kepada isterinya atau hamba sahayanya maka sesungguhnya mereka tidak tercela: -', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 10, NULL),
(23, 7, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْعَادُونَ', 'فمن ابتغى وراء ذلك فاولئك هم العادون', NULL, 'But whoever seeks beyond that, then those are the transgressors -', 'Kemudian, sesiapa yang mengingini selain dari yang demikian, maka merekalah orang-orang yang melampaui batas;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 7, NULL),
(23, 8, 'وَٱلَّذِينَ هُمْ لِأَمَـٰنَـٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'والذين هم لاماناتهم وعهدهم راعون', NULL, 'And they who are to their trusts and their promises attentive', 'Dan mereka yang menjaga amanah dan janjinya;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 9, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', 'والذين هم على صلواتهم يحافظون', NULL, 'And they who carefully maintain their prayers -', 'Dan mereka yang tetap memelihara sembahyangnya;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 10, 'أُو۟لَـٰٓئِكَ هُمُ ٱلْوَٰرِثُونَ', 'اولئك هم الوارثون', NULL, 'Those are the inheritors', 'Mereka itulah orang-orang yang berhak mewarisi -', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 3, NULL),
(23, 11, 'ٱلَّذِينَ يَرِثُونَ ٱلْفِرْدَوْسَ هُمْ فِيهَا خَـٰلِدُونَ', 'الذين يرثون الفردوس هم فيها خالدون', NULL, 'Who will inherit al-Firdaus. They will abide therein eternally.', 'Yang akan mewarisi Syurga Firdaus; mereka kekal di dalamnya.', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 6, NULL),
(23, 12, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ مِن سُلَـٰلَةٍ مِّن طِينٍ', 'ولقد خلقنا الانسان من سلالة من طين', NULL, 'And certainly did We create man from an extract of clay.', 'Dan sesungguhnya Kami telah menciptakan manusia dari pati (yang berasal) dari tanah;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 7, NULL),
(23, 13, 'ثُمَّ جَعَلْنَـٰهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ', 'ثم جعلناه نطفة في قرار مكين', NULL, 'Then We placed him as a sperm-drop in a firm lodging [i.e., the womb].', 'Kemudian Kami jadikan “pati” itu (setitis) air benih pada penetapan yang kukuh;', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 6, NULL),
(23, 14, 'ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةً فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةً فَخَلَقْنَا ٱلْمُضْغَةَ عِظَـٰمًا فَكَسَوْنَا ٱلْعِظَـٰمَ لَحْمًا ثُمَّ أَنشَأْنَـٰهُ خَلْقًا ءَاخَرَ ۚ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَـٰلِقِينَ', 'ثم خلقنا النطفة علقة فخلقنا العلقة مضغة فخلقنا المضغة عظاما فكسونا العظام لحما ثم انشاناه خلقا اخر فتبارك الله احسن الخالقين', NULL, 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allāh, the best of creators.', 'Kemudian Kami ciptakan air benih itu menjadi sebuku darah beku. lalu Kami ciptakan darah beku itu menjadi seketul daging; kemudian Kami ciptakan daging itu menjadi beberapa tulang; kemudian Kami balut tulang-tulang itu dengan daging. Setelah sempurna kejadian itu Kami bentuk dia menjadi makhluk yang lain sifat keadaannya. Maka nyatalah kelebihan dan ketinggian Allah sebaik-baik Pencipta.', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 21, NULL),
(23, 15, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', 'ثم انكم بعد ذلك لميتون', NULL, 'Then indeed, after that you are to die.', 'Kemudian, sesungguhnya kamu sesudah itu akan mati.', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 16, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَـٰمَةِ تُبْعَثُونَ', 'ثم انكم يوم القيامة تبعثون', NULL, 'Then indeed you, on the Day of Resurrection, will be resurrected.', 'Kemudian sesungguhnya kamu akan dibangkitkan hidup semula pada hari kiamat.', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 5, NULL),
(23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَـٰفِلِينَ', 'ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غافلين', NULL, 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.', 'Dan demi sesungguhnya, Kami telah menciptakan tujuh jalan di atas kamu, dan Kami pula tidak lalai daripada (menyediakan keperluan) makhluk-makhluk Kami.', FALSE, NULL, NULL, 342, 18, 137, 295, FALSE, 10, NULL),
(23, 18, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَسْكَنَّـٰهُ فِى ٱلْأَرْضِ ۖ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَـٰدِرُونَ', 'وانزلنا من السماء ماء بقدر فاسكناه في الارض وانا على ذهاب به لقادرون', NULL, 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.', 'Dan Kami turunkan hujan dari langit dengan sukatan yang tertentu, serta Kami tempatkan dia tersimpan di bumi; dan sesungguhnya Kami sudah tentu berkuasa melenyapkannya.', FALSE, NULL, NULL, 343, 18, 137, 295, FALSE, 13, NULL),
(23, 19, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّـٰتٍ مِّن نَّخِيلٍ وَأَعْنَـٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', 'فانشانا لكم به جنات من نخيل واعناب لكم فيها فواكه كثيرة ومنها تاكلون', NULL, 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.', 'Kemudian, Kami tumbuhkan untuk kamu dengan air itu, kebun-kebun tamar (kurma) dan anggur. Kamu beroleh dalam kebun-kebun itu (berbagai jenis lagi) buah-buahan yang banyak, dan dari kebun-kebun itulah kamu beroleh rezeki penghidupan kamu.', FALSE, NULL, NULL, 343, 18, 137, 295, FALSE, 13, NULL),
(23, 20, 'وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍ لِّلْـَٔاكِلِينَ', 'وشجرة تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين', NULL, 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food [i.e., olives] for those who eat.', 'Dan (Kami juga menumbuhkan untuk kamu) pokok yang asal tumbuhnya di kawasan Gunung Tursina, yang mengeluarkan minyak dan lauk bagi orang-orang yang makan.', FALSE, NULL, NULL, 343, 18, 137, 295, FALSE, 9, NULL),
(23, 21, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', 'وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمْ فِيهَا مَنَافِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', NULL, 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.', 'Dan sesungguhnya pada binatang-binatang ternak itu kamu beroleh punca-punca yang menyedarkan (tentang kemurahan dan kebijaksanaan Allah penciptanya); Kami beri kamu minum dari susu yang ada dalam perutnya, dan kamu beroleh banyak faedah lagi padanya; dan daripadanya juga kamu beroleh rezeki penghidupan kamu.', FALSE, NULL, NULL, 343, 18, 137, 295, FALSE, 0, NULL),
(23, 22, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ', NULL, 'And upon them and on ships you are carried.', 'Dan di atas binatang-binatang ternak itu, serta di atas kapal-kapal kamu diangkut.', FALSE, NULL, NULL, 343, 18, 137, 295, FALSE, 0, NULL),
(23, 23, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَقَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ', NULL, 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allāh; you have no deity other than Him; then will you not fear Him?"', 'Dan demi sesungguhnya, Kami telah mengutuskan Nabi Nuh kepada kaumnya lalu berkatalah ia: “Wahai kaumku, sembahlah kamu akan Allah (sebenarnya) tidak ada Tuhan bagi kamu selain daripadaNya. Oleh itu, tidakkah kamu mahu bertaqwa kepadaNya?”.', FALSE, NULL, NULL, 343, 18, 137, 296, FALSE, 0, NULL),
(23, 24, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةً مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'فَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ مَا هَٰذَا إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَاءَ اللَّهُ لَأَنزَلَ مَلَائِكَةً مَّا سَمِعْنَا بِهَٰذَا فِي آبَائِنَا الْأَوَّلِينَ', NULL, 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allāh had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.', 'Maka ketua-ketua yang kafir dari kaumnya berkata (sesama sendiri): “Orang ini hanyalah seorang manusia seperti kamu, ia bertujuan hendak melebihkan dirinya daripada kamu. Dan kalaulah Allah berkehendak (mengutuskan seorang Rasul) tentulah Ia menurunkan malaikat menjadi RasulNya. Kami tidak pernah mendengar seruan seperti ini dalam kalangan datuk nenek kami yang telah lalu.', FALSE, NULL, NULL, 343, 18, 137, 296, FALSE, 0, NULL),
(23, 25, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍ', 'إِنْ هُوَ إِلَّا رَجُلٌ بِهِ جِنَّةٌ فَتَرَبَّصُوا بِهِ حَتَّىٰ حِينٍ', NULL, 'He is not but a man possessed with madness, so wait concerning him for a time."', '“Ia tidak lain hanyalah seorang lelaki yang mengidap penyakit gila. Oleh itu tunggulah akan perubahan keadaannya hingga ke suatu masa”.', FALSE, NULL, NULL, 343, 18, 137, 296, FALSE, 0, NULL),
(23, 26, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'قَالَ رَبِّ انصُرْنِي بِمَا كَذَّبُونِ', NULL, '[Noah] said, "My Lord, support me because they have denied me."', 'Nabi Nuh berdoa dengan berkata: “Wahai Tuhanku tolonglah daku, kerana mereka mendustakan seruanku”.', FALSE, NULL, NULL, 343, 18, 137, 296, FALSE, 0, NULL),
(23, 27, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', 'فَأَوْحَيْنَا إِلَيْهِ أَنِ اصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَاءَ أَمْرُنَا وَفَارَ التَّنُّورُ فَاسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْ وَلَا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُم مُّغْرَقُونَ', NULL, 'So We inspired to him, "Construct the ship under Our observation and Our inspiration, and when Our command comes and the oven overflows, put into it [i.e., the ship] from each [creature] two mates and your family, except him for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.', 'Lalu Kami wahyukan kepadanya: “Buatlah bahtera dengan pengawasan serta kawalan Kami, dan dengan panduan wahyu Kami (tentang cara membuatnya); kemudian apabila datang hukum Kami untuk membinasakan mereka, dan air memancut-mancut dari muka bumi (yang menandakan kedatangan taufan), maka masukkanlah ke dalam bahtera itu dua dari tiap-tiap jenis haiwan (jantan dan betina), dan bawalah ahlimu (dan pengikut-pengikutmu) kecuali orang yang telah ditetapkan hukuman azab atasnya di antara mereka (disebabkan kekufurannya); dan janganlah engkau merayu kepadaku untuk menolong kaum yang zalim itu, kerana sesungguhnya mereka akan ditenggelamkan dengan taufan sehingga mati lemas.', FALSE, NULL, NULL, 343, 18, 137, 296, FALSE, 0, NULL),
(23, 28, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فَإِذَا اسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ لِلَّهِ الَّذِي نَجَّانَا مِنَ الْقَوْمِ الظَّالِمِينَ', NULL, 'And when you have boarded the ship, you and those with you, then say, ''Praise to Allāh who has saved us from the wrongdoing people.''', '“Kemudian apabila engkau dan orang-orang yang bersamamu telah berada di atas bahtera itu maka hendaklah engkau (bersyukur kepada Allah dengan) berkata: ‘Segala puji tertentu bagi Allah yang telah menyelamatkan kami daripada orang-orang yang zalim’.', FALSE, NULL, NULL, 344, 18, 137, 296, FALSE, 0, NULL),
(23, 29, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 'وَقُل رَّبِّ أَنزِلْنِي مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ', NULL, 'And say, ''My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].''"', '“Dan berdoalah dengan berkata: ‘Wahai Tuhanku, turunkanlah daku di tempat turun yang berkat, dan Engkau adalah sebaik-baik Pemberi tempat’”', FALSE, NULL, NULL, 344, 18, 137, 296, FALSE, 0, NULL),
(23, 30, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَاتٍ وَإِن كُنَّا لَمُبْتَلِينَ', NULL, 'Indeed in that are signs, and indeed, We are ever testing [Our servants].', 'Sesungguhnya pada yang demikian itu terdapat tanda-tanda (yang mendatangkan iktibar); dan sesungguhnya Kami tetap menguji (hamba-hamba Kami).', FALSE, NULL, NULL, 344, 18, 137, 296, FALSE, 0, NULL),
(23, 31, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'ثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قَرْنًا آخَرِينَ', NULL, 'Then We produced after them a generation of others.', 'Kemudian Kami ciptakan sesudah mereka, umat yang lain.', FALSE, NULL, NULL, 344, 18, 137, 296, FALSE, 0, NULL),
(23, 32, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ', NULL, 'And We sent among them a messenger from themselves, [saying], "Worship Allāh; you have no deity other than Him; then will you not fear Him?"', 'Lalu Kami mengutus kepada mereka seorang Rasul dari kalangan mereka (dengan berfirman melalui Rasul itu): “Sembahlah kamu akan Allah, (sebenarnya) tidak ada Tuhan bagi kamu selain daripadaNya. Oleh itu tidakkah kamu mahu bertaqwa kepadaNya?”', FALSE, NULL, NULL, 344, 18, 137, 296, FALSE, 0, NULL),
(23, 33, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْـَٔاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 'وَقَالَ الْمَلَأُ مِن قَوْمِهِ الَّذِينَ كَفَرُوا وَكَذَّبُوا بِلِقَاءِ الْآخِرَةِ وَأَتْرَفْنَاهُمْ فِي الْحَيَاةِ الدُّنْيَا مَا هَٰذَا إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', NULL, 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.', 'Dan (bagi menolak seruan itu), ketua-ketua dari kaumnya yang kafir serta mendustakan pertemuan hari akhirat, dan yang Kami mewahkan mereka dalam kehidupan dunia, berkata (sesama sendiri) “Orang ini hanyalah seorang manusia seperti kamu, ia makan dari apa yang kamu makan, dan meminum dari apa yang kamu minum.', FALSE, NULL, NULL, 344, 18, 137, 297, FALSE, 0, NULL),
(23, 34, 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَاسِرُونَ', NULL, 'And if you should obey a man like yourselves, indeed, you would then be losers.', '“Dan demi sesungguhnya, jika kamu taati manusia yang seperti kamu, tentulah kamu dengan membuat demikian, menjadi orang-orang yang rugi.', FALSE, NULL, NULL, 344, 18, 137, 297, FALSE, 0, NULL),
(23, 35, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَامًا أَنَّكُم مُّخْرَجُونَ', NULL, 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?', '“Patutkah ia menjanjikan kamu, bahawa sesungguhnya apabila kamu mati dan menjadi tanah dan tulang, kamu akan dikeluarkan (dari kubur hidup semula)?', FALSE, NULL, NULL, 344, 18, 137, 297, FALSE, 0, NULL),
(23, 36, 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', NULL, 'How far, how far, is that which you are promised.', '“Jauh, amatlah jauh (dari kebenaran) apa yang dijanjikan kepada kamu itu!', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 37, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'إِنْ هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', NULL, 'It [i.e., life] is not but our worldly life - we die and live, but we will not be resurrected.', '“Tiadalah hidup yang lain selain dari hidup kita di dunia ini. Kita mati dan kita hidup (silih berganti) dan tiadalah kita akan dibangkitkan hidup semula.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 38, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', 'إِنْ هُوَ إِلَّا رَجُلٌ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا وَمَا نَحْنُ لَهُ بِمُؤْمِنِينَ', NULL, 'He is not but a man who has invented a lie about Allāh, and we will not believe him."', '“Tiadalah dia (Nabi Hud) itu selain dari seorang lelaki yang mengada-adakan perkara dusta terhadap Allah, dan kami tidak akan beriman kepadanya”.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 39, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'قَالَ رَبِّ انصُرْنِي بِمَا كَذَّبُونِ', NULL, 'He said, "My Lord, support me because they have denied me."', 'Nabi Hud berdoa dengan berkata: “Wahai TuhanKu, belalah daku, kerana mereka telah mendustakan seruanku”.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 40, 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَٰدِمِينَ', 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَادِمِينَ', NULL, '[Allāh] said, "After a little, they will surely become regretful."', 'Allah berfirman: “Dalam sedikit masa lagi mereka akan menjadi orang-orang yang menyesal”.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 41, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءً فَبُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'فَأَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ فَجَعَلْنَاهُمْ غُثَاءً فَبُعْدًا لِّلْقَوْمِ الظَّالِمِينَ', NULL, 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.', 'Akhirnya mereka dibinasakan oleh letusan suara yang menggempakan bumi, dengan benar lagi adil, lalu Kami jadikan mereka sebagai sampah sarap (yang dihanyutkan oleh banjir). Maka kebinasaanlah kesudahannya bagi kaum yang zalim itu.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 42, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', 'ثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قُرُونًا آخَرِينَ', NULL, 'Then We produced after them other generations.', 'Kemudian Kami ciptakan, sesudah mereka, umat-umat yang lain.', FALSE, NULL, NULL, 344, 18, 138, 297, FALSE, 0, NULL),
(23, 43, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَأْخِرُونَ', NULL, 'No nation will precede its time [of termination], nor will they remain [thereafter].', 'Sesuatu umat itu tidak dapat mendahului tempohnya yang telah ditentukan, dan mereka pula tidak dapat melambatkannya.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 44, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَٰهُمْ أَحَادِيثَ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَىٰ كُلَّ مَا جَاءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَاهُمْ أَحَادِيثَ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', NULL, 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.', 'Kemudian Kami mengutus Rasul-rasul Kami silih berganti. Tiap-tiap kali sesuatu umat didatangi Rasulnya, mereka mendustakannya; lalu Kami binasakan umat-umat yang demikian, lepas satu-satu; dan Kami jadikan perihal mereka sebagai cerita-cerita (yang mendatangkan iktibar); maka kebinasaanlah kesudahannya bagi orang-orang yang tidak beriman.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 45, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَارُونَ بِآيَاتِنَا وَسُلْطَانٍ مُّبِينٍ', NULL, 'Then We sent Moses and his brother Aaron with Our signs and a clear authority', 'Kemudian Kami mengutus Nabi Musa dan saudaranya: Nabi Harun, dengan membawa ayat-ayat keterangan Kami, dan bukti (mukjizat) yang nyata,', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 46, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', 'إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا عَالِينَ', NULL, 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.', 'Kepada Firaun dan kaumnya; lalu mereka menentang (seruan Nabi-nabi Allah itu) dengan sombong takbur, serta menjadi kaum yang membesarkan diri.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 47, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 'فَقَالُوا أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَابِدُونَ', NULL, 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"', 'Sehingga mereka berkata (dengan angkuhnya): “Patutkah kita beriman kepada dua manusia seperti kita, sedang kaum mereka menjadi orang-orang suruhan kita?”', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 48, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', 'فَكَذَّبُوهُمَا فَكَانُوا مِنَ الْمُهْلَكِينَ', NULL, 'So they denied them and were of those destroyed.', 'Oleh itu, merekapun mendustakan keduanya, lalu menjadilah mereka sebahagian dari orang-orang yang dibinasakan.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 49, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ لَعَلَّهُمْ يَهْتَدُونَ', NULL, 'And We certainly gave Moses the Scripture that perhaps they would be guided.', 'Dan sesungguhnya, Kami telah memberikan Nabi Musa Kitab Taurat, supaya mereka beroleh hidayah petunjuk.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 50, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', 'وَجَعَلْنَا ابْنَ مَرْيَمَ وَأُمَّهُ آيَةً وَآوَيْنَاهُمَا إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', NULL, 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.', 'Dan Kami jadikan (Nabi lsa) ibni Maryam serta ibunya sebagai satu tanda (mukjizat) dan Kami telah menempatkan keduanya di tanah tinggi, tempat tinggal yang ada tanaman dan mata air yang mengalir.', FALSE, NULL, NULL, 345, 18, 138, 297, FALSE, 0, NULL),
(23, 51, 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ', 'يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ', NULL, '[Allāh said], "O messengers, eat from the good foods and work righteousness. Indeed I, of what you do, am Knowing.', 'Wahai Rasul-rasul, makanlah dari benda-benda yang baik lagi halal dan kerjakanlah amal-amal soleh; sesungguhnya Aku Maha Mengetahui akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 52, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', 'وَإِنَّ هَٰذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً وَأَنَا رَبُّكُمْ فَاتَّقُونِ', NULL, 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."', 'Dan sesungguhnya ugama Islam ini ialah ugama kamu - ugama yang satu asas pokoknya, dan Akulah Tuhan kamu; maka bertaqwalah kamu kepadaKu.', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 53, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'فَتَقَطَّعُوا أَمْرَهُم بَيْنَهُمْ زُبُرًا كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ', NULL, 'But they [i.e., the people] divided their religion among them into portions [i.e., sects] - each faction, in what it has, rejoicing.', 'Kemudian umat Rasul-rasul itu berpecah-belah dalam urusan ugama mereka kepada beberapa pecahan, tiap-tiap golongan bergembira dengan apa yang ada pada mereka.', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 54, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', 'فَذَرْهُمْ فِي غَمْرَتِهِمْ حَتَّىٰ حِينٍ', NULL, 'So leave them in their confusion for a time.', 'Maka biarkanlah mereka tenggelam dalam kesesatannya itu hingga ke suatu masa.', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 55, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ', 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِ مِن مَّالٍ وَبَنِينَ', NULL, 'Do they think that what We extend to them of wealth and children', 'Adakah mereka menyangka bahawa apa yang Kami berikan kepada mereka dari harta benda dan anak-pinak itu.', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 56, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ بَل لَّا يَشْعُرُونَ', 'نُسَارِعُ لَهُمْ فِي الْخَيْرَاتِ بَل لَّا يَشْعُرُونَ', NULL, 'Is [because] We hasten for them good things? Rather, they do not perceive.', '(Bermakna bahawa dengan yang demikian) Kami menyegerakan untuk mereka pemberian kebaikan? (Tidak!) Bahkan mereka tidak menyedari (hakikatnya yang sebenar).', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 57, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'إِنَّ الَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', NULL, 'Indeed, they who are apprehensive from fear of their Lord', 'Sesungguhnya orang-orang yang sentiasa bimbang disebabkan takut kepada (kemurkaan) Tuhan mereka;', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 58, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', 'وَالَّذِينَ هُم بِآيَاتِ رَبِّهِمْ يُؤْمِنُونَ', NULL, 'And they who believe in the signs of their Lord', 'Dan orang-orang yang beriman kepada ayat-ayat Tuhan mereka;', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 59, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', 'وَالَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', NULL, 'And they who do not associate anything with their Lord', 'Dan orang-orang yang tidak mempersekutukan sesuatu yang lain dengan Tuhan mereka;', FALSE, NULL, NULL, 345, 18, 138, 298, FALSE, 0, NULL),
(23, 60, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', 'وَالَّذِينَ يُؤْتُونَ مَا آتَوا وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَاجِعُونَ', NULL, 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -', 'Dan orang-orang yang memberi apa yang mereka berikan sedang hati mereka gementar kerana mereka yakin akan kembali kepada Tuhan mereka;', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 61, 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', 'أُولَٰئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ', NULL, 'It is those who hasten to good deeds, and they outstrip [others] therein.', 'Mereka itulah orang-orang yang segera mengerjakan kebaikan, dan merekalah orang-orang yang mendahului pada mencapainya.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 62, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَلَدَيْنَا كِتَٰبٌ يَنطِقُ بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَلَدَيْنَا كِتَابٌ يَنطِقُ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.', 'Dan Kami tidak memberati seseorang melainkan apa yang terdaya olehnya; dan di sisi Kami ada sebuah Kitab (suratan amal) yang menyatakan segala-galanya dengan benar, sedang mereka tidak dianiaya.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 63, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', 'بَلْ قُلُوبُهُمْ فِي غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَالٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَامِلُونَ', NULL, 'But their hearts are covered with confusion over this, and they have [evil] deeds besides that [i.e., disbelief] which they are doing,', '(Sekalipun demikian, orang-orang yang ingkar tidak juga berfikir) bahkan hati mereka tenggelam di dalam kejahilan, lalai daripada (memahami ajaran Al-Quran) ini; dan mereka pula mempunyai lagi amal-amal (yang jahat) selain dari itu, yang mereka terus-menerus mengerjakannya;', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 64, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', 'حَتَّىٰ إِذَا أَخَذْنَا مُتْرَفِيهِم بِالْعَذَابِ إِذَا هُمْ يَجْأَرُونَ', NULL, 'Until when We seize their affluent ones with punishment, at once they are crying [to Allāh] for help.', 'Hingga apabila Kami timpakan azab kepada orang-orang yang mewah di antara mereka maka dengan serta-merta mereka menjerit-jerit meminta tolong.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 65, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'لَا تَجْأَرُوا الْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', NULL, 'Do not cry out today. Indeed, by Us you will not be helped.', '(Lalu dikatakan kepada mereka): “Janganlah kamu menjerit-jerit meminta tolong pada hari ini, sesungguhnya kamu tidak akan beroleh sebarang pertolongan dari Kami.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 66, 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', 'قَدْ كَانَتْ آيَاتِي تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰ أَعْقَابِكُمْ تَنكِصُونَ', NULL, 'My verses had already been recited to you, but you were turning back on your heels', '“(Kerana) sesungguhnya ayat-ayatKu telah berkali-kali dibacakan kepada kamu, dalam pada itu kamu berpaling undur ke belakang -', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 67, 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًا تَهْجُرُونَ', 'مُسْتَكْبِرِينَ بِهِ سَامِرًا تَهْجُرُونَ', NULL, 'In arrogance regarding it, conversing by night, speaking evil.', '“Dengan keadaan sombong angkuh mendustakannya, serta mencacinya dalam perbualan kamu pada malam hari”.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 68, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', 'أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ أَمْ جَاءَهُم مَّا لَمْ يَأْتِ آبَاءَهُمُ الْأَوَّلِينَ', NULL, 'Then have they not reflected over the word [i.e., the Qur’ān], or has there come to them that which had not come to their forefathers?', 'Maka adakah mereka melakukan yang demikian kerana mereka tidak dapat memahami kata-kata ajaran (yang disampaikan kepada mereka)? Atau kerana telah datang kepada mereka sesuatu yang tidak pernah datang kepada datuk nenek mereka yang telah lalu?', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 69, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 'أَمْ لَمْ يَعْرِفُوا رَسُولَهُمْ فَهُمْ لَهُ مُنكِرُونَ', NULL, 'Or did they not know their Messenger, so they are toward him disacknowledging?', 'Atau kerana mereka tidak kenal rasul mereka, lalu mereka mengingkarinya?', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 70, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 'أَمْ يَقُولُونَ بِهِ جِنَّةٌ بَلْ جَاءَهُم بِالْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَارِهُونَ', NULL, 'Or do they say, "In him is madness"? Rather, he brought them the truth, but most of them, to the truth, are averse.', 'Atau kerana mereka mengatakan: “Dia kena penyakit gila?” (Sebenarnya bukan kerana sesuatu pun dari yang tersebut itu) bahkan kerana Rasul mereka datang kepada mereka membawa ugama yang tetap benar, dan tabiat kebanyakan mereka tidak suka kepada sebarang kebenaran.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 71, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 'وَلَوِ اتَّبَعَ الْحَقُّ أَهْوَاءَهُمْ لَفَسَدَتِ السَّمَاوَاتُ وَالْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَاهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', NULL, 'But if the Truth [i.e., Allāh] had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.', 'Dan kalaulah kebenaran itu tunduk menurut hawa nafsu mereka, nescaya rosak binasalah langit dan bumi serta segala yang adanya. (Bukan sahaja Kami memberikan ugama yang tetap benar) bahkan Kami memberi kepada mereka Al-Quran yang menjadi sebutan baik dan mendatangkan kemuliaan kepada mereka; maka Al-Quran yang demikian keadaannya, mereka tidak juga mahu menerimanya;', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 72, 'أَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'أَمْ تَسْأَلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ وَهُوَ خَيْرُ الرَّازِقِينَ', NULL, 'Or do you, [O Muḥammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.', 'Atau adakah (mereka menolak seruanmu itu kerana) engkau meminta kepada mereka suatu pemberian (sebagai hasil pendapatan seruanmu)? (Ini pun tidak!) Kerana engkau percaya pemberian Tuhanmu lebih baik, dan Dia lah jua sebaik-baik Pemberi rezeki.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 73, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And indeed, you invite them to a straight path.', 'Dan sesungguhnya engkau (wahai Muhammad) hanya menyeru mereka ke jalan yang lurus;', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 74, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', 'وَإِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ عَنِ الصِّرَاطِ لَنَاكِبُونَ', NULL, 'But indeed, those who do not believe in the Hereafter are deviating from the path.', 'Dan sesungguhnya orang-orang yang tidak beriman kepada hari akhirat, sudah tentu tidak mengikuti jalan yang lurus itu.', FALSE, NULL, NULL, 346, 18, 138, 298, FALSE, 0, NULL),
(23, 75, 'وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'وَلَوْ رَحِمْنَاهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا فِي طُغْيَانِهِمْ يَعْمَهُونَ', NULL, 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.', 'Dan sekiranya Kami menaruh belas kasihan kepada mereka serta Kami hapuskan kesusahan yang menimpa mereka, nescaya mereka akan tetap terus meraba-raba dalam kesesatan mereka yang melampaui batas itu.', FALSE, NULL, NULL, 347, 18, 139, 298, FALSE, 0, NULL),
(23, 76, 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', 'وَلَقَدْ أَخَذْنَاهُم بِالْعَذَابِ فَمَا اسْتَكَانُوا لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', NULL, 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]', 'Dan sesungguhnya Kami telah menimpakan mereka dengan azab (di dunia), maka mereka tidak juga tunduk patuh kepada Tuhan mereka dan tidak pula berdoa kepadaNya dengan merendah diri (serta insaf dan bertaubat);', FALSE, NULL, NULL, 347, 18, 139, 298, FALSE, 0, NULL),
(23, 77, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 'حَتَّىٰ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', NULL, 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.', 'Sehingga apabila Kami bukakan kepada mereka sebuah pintu yang menyebabkan azab yang berat, maka mereka serta-merta berputus asa dengan sebabnya - dari mendapat sebarang kebaikan.', FALSE, NULL, NULL, 347, 18, 139, 298, FALSE, 0, NULL),
(23, 78, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'وَهُوَ الَّذِي أَنشَأَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ', NULL, 'And it is He who produced for you hearing and vision and hearts [i.e., intellect]; little are you grateful.', 'Dan Dia lah jua yang mengadakan bagi kamu pendengaran dan penglihatan serta hati (untuk kamu bersyukur; tetapi) amatlah sedikit kamu bersyukur.', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 79, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'وَهُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', NULL, 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.', 'Dan Dia lah yang menciptakan serta mengembangkan kamu di bumi, dan kepadaNyalah kamu akan dihimpunkan.', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 80, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ أَفَلَا تَعْقِلُونَ', 'وَهُوَ الَّذِي يُحْيِي وَيُمِيتُ وَلَهُ اخْتِلَافُ اللَّيْلِ وَالنَّهَارِ أَفَلَا تَعْقِلُونَ', NULL, 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?', 'Dan Dia lah yang menghidupkan dan mematikan; dan Dia lah yang menentukan pertukaran malam dan siang. Maka tidakkah kamu mahu berfikir?', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 81, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 'بَلْ قَالُوا مِثْلَ مَا قَالَ الْأَوَّلُونَ', NULL, 'Rather, they say like what the former peoples said.', '(Mereka tidak juga mahu berfikir) bahkan mereka berkata seperti yang dikatakan oleh orang-orang dahulu (yang ingkar);', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 82, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ', NULL, 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?', 'Mereka berkata: “Adakah apabila kami telah mati dan kami menjadi tanah dan tulang, adakah kami akan dibangkitkan (hidup semula)?', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 83, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'لَقَدْ وُعِدْنَا نَحْنُ وَآبَاؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ', NULL, 'We have been promised this, we and our forefathers, before; this is not but legends of the former peoples."', '“Demi sesungguhnya, kami telah dijanjikan perkara ini - kami dan datuk nenek kami - dari dahulu lagi; perkara ini hanyalah cerita dongeng orang-orang dahulu-kala.”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 84, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'قُل لِّمَنِ الْأَرْضُ وَمَن فِيهَا إِن كُنتُمْ تَعْلَمُونَ', NULL, 'Say, [O Muḥammad], "To whom belongs the earth and whoever is in it, if you should know?"', 'Tanyakanlah (wahai Muhammad): “Kepunyaan siapakah bumi ini dan segala yang ada padanya, kalau kamu mengetahui?”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 85, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَذَكَّرُونَ', 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَذَكَّرُونَ', NULL, 'They will say, "To Allāh." Say, "Then will you not remember?"', 'Mereka akan menjawab: “Kepunyaan Allah”. Katakanlah: “Mengapa kamu tidak mahu ingat (dan insaf)?”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 86, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'قُلْ مَن رَّبُّ السَّمَاوَاتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْعَظِيمِ', NULL, 'Say, "Who is Lord of the seven heavens and Lord of the Great Throne?"', 'Tanyakanlah lagi: “Siapakah Tuhan yang memiliki dan mentadbirkan langit yang tujuh, dan Tuhan yang mempunyai Arasy yang besar?”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 87, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَتَّقُونَ', 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَتَّقُونَ', NULL, 'They will say, "[They belong] to Allāh." Say, "Then will you not fear Him?"', 'Mereka akan menjawab: “(Semuanya) kepunyaan Allah”. Katakanlah: “Mengapa kamu tidak mahu bertaqwa?”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 88, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'قُلْ مَن بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', NULL, 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"', 'Tanyakanlah lagi: Siapakah yang memegang kuasa pemerintahan tiap-tiap sesuatu, serta ia dapat melindungi (segala-galanya) dan tidak ada sesuatupun yang dapat disembunyi daripada kekuasaannya? (Jawablah) jika kamu mengetahui!”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 89, 'سَيَقُولُونَ لِلَّهِ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 'سَيَقُولُونَ لِلَّهِ قُلْ فَأَنَّىٰ تُسْحَرُونَ', NULL, 'They will say, "[All belongs] to Allāh." Say, "Then how are you deluded?"', 'Mereka akan menjawab: “(Segala-galanya) dikuasai Allah”. Katakanlah: “Jika demikian, bagaimana kamu tertarik hati kepada perkara yang tidak benar?”', FALSE, NULL, NULL, 347, 18, 139, 299, FALSE, 0, NULL),
(23, 90, 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 'بَلْ أَتَيْنَاهُم بِالْحَقِّ وَإِنَّهُمْ لَكَاذِبُونَ', NULL, 'Rather, We have brought them the truth, and indeed they are liars.', '(Bukanlah sebagaimana tuduhan mereka) bahkan Kami telah membawa kepada mereka keterangan yang benar, dan sesungguhnya mereka adalah berdusta.', FALSE, NULL, NULL, 348, 18, 139, 299, FALSE, 0, NULL),
(23, 91, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'مَا اتَّخَذَ اللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ إِلَٰهٍ إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ', NULL, 'Allāh has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have [sought to] overcome others. Exalted is Allāh above what they describe [concerning Him].', 'Allah tidak sekali-kali mempunyai anak, dan tidak ada sama sekali sebarang tuhan bersamaNya; (kalaulah ada banyak tuhan) tentulah tiap-tiap tuhan itu akan menguasai dan menguruskan segala yang diciptakannya dengan bersendirian, dan tentulah setengahnya akan bertindak mengalahkan setengahnya yang lain. Maha Suci Allah dari apa yang dikatakan oleh mereka (yang musyrik) itu.', FALSE, NULL, NULL, 348, 18, 139, 299, FALSE, 0, NULL),
(23, 92, 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَتَعَالَىٰ عَمَّا يُشْرِكُونَ', NULL, '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].', '(Allah) Yang mengetahui segala yang tersembunyi dan yang nyata; maka (dengan yang demikian) Maha Tinggilah keadaanNya dari segala yang mereka sekutukan.', FALSE, NULL, NULL, 348, 18, 139, 299, FALSE, 0, NULL),
(23, 93, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 'قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ', NULL, 'Say, [O Muḥammad], "My Lord, if You should show me that which they are promised,', 'Katakanlah (wahai Muhammad): “Wahai Tuhanku, kiranya Engkau hendak memperlihatkan kepadaku (azab) yang dijanjikan kepada mereka (di dunia), -', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 94, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'رَبِّ فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظَّالِمِينَ', NULL, 'My Lord, then do not place me among the wrongdoing people."', '“Maka wahai Tuhanku, janganlah Engkau biarkan daku tinggal dalam kalangan kaum yang zalim itu”.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 95, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 'وَإِنَّا عَلَىٰ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَادِرُونَ', NULL, 'And indeed, We are Able to show you what We have promised them.', 'Dan sesungguhnya Kami berkuasa memperlihatkan kepadamu azab yang Kami janjikan kepada mereka.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 96, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', 'ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ السَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', NULL, 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.', 'Tolaklah kejahatan yang dilakukan kepadamu dengan cara yang sebaik-baiknya, Kami Maha Mengetahui apa yang mereka katakan itu.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 97, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ', NULL, 'And say, "My Lord, I seek refuge in You from the incitements of the devils,', 'Dan katakanlah: “Wahai Tuhanku, aku berlindung kepadaMu dari hasutan Syaitan-syaitan', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 98, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', NULL, 'And I seek refuge in You, my Lord, lest they be present with me."', '“Dan aku berlindung kepadaMu, wahai Tuhanku, supaya Syaitan-syaitan itu tidak menghampiriku”.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 99, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 'حَتَّىٰ إِذَا جَاءَ أَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُونِ', NULL, '[For such is the state of the disbelievers] until, when death comes to one of them, he says, "My Lord, send me back', 'Kesudahan golongan yang kufur ingkar itu apabila sampai ajal maut kepada salah seorang di antara mereka, berkatalah ia: “Wahai Tuhanku, kembalikanlah daku (hidup semula di dunia) -', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 100, 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًا فِيمَا تَرَكْتُ كَلَّآ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'لَعَلِّي أَعْمَلُ صَالِحًا فِيمَا تَرَكْتُ كَلَّا إِنَّهَا كَلِمَةٌ هُوَ قَائِلُهَا وَمِن وَرَائِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', NULL, 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.', '“Supaya aku mengerjakan amal-amal yang soleh dalam perkara-perkara yang telah aku tinggalkan”. Tidak! Masakan dapat? Sesungguhnya perkataannya itu hanyalah kata-kata yang ia sahaja yang mengatakannya, sedang di hadapan mereka ada alam barzakh (yang mereka tinggal tetap padanya) hingga hari mereka dibangkitkan semula (pada hari kiamat).', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 101, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ', 'فَإِذَا نُفِخَ فِي الصُّورِ فَلَا أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَاءَلُونَ', NULL, 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.', 'Kemudian, apabila ditiup sangkakala, maka pada hari itu tidak ada lagi manfaat pertalian kerabat di antara mereka, dan tidak pula sempat mereka bertanya-tanyaan.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 102, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فَمَن ثَقُلَتْ مَوَازِينُهُ فَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'And those whose scales are heavy [with good deeds] - it is they who are the successful.', 'Maka sesiapa yang berat timbangan amal baiknya, maka mereka itulah orang-orang yang berjaya.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 103, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فِى جَهَنَّمَ خَٰلِدُونَ', 'وَمَنْ خَفَّتْ مَوَازِينُهُ فَأُولَٰئِكَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ فِي جَهَنَّمَ خَالِدُونَ', NULL, 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.', 'Dan sesiapa yang ringan timbangan amal baiknya, maka merekalah orang-orang yang merugikan dirinya sendiri; mereka kekal di dalam neraka Jahannam -', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 104, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', 'تَلْفَحُ وُجُوهَهُمُ النَّارُ وَهُمْ فِيهَا كَالِحُونَ', NULL, 'The Fire will sear their faces, and they therein will have taut smiles.', 'Api neraka itu membakar muka mereka, dan tinggallah mereka di situ dengan muka yang hodoh cacat.', FALSE, NULL, NULL, 348, 18, 139, 300, FALSE, 0, NULL),
(23, 105, 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 'أَلَمْ تَكُنْ آيَاتِي تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', NULL, '[It will be said], "Were not My verses recited to you and you used to deny them?"', '(Sambil dikatakan kepada mereka): “Bukankah ayat-ayatKu selalu dibacakan kepada kamu, lalu kamu terus-menerus mendustakannya?”', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 106, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ', 'قَالُوا رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَالِّينَ', NULL, 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.', 'Mereka menjawab: “Wahai Tuhan kami, kami telah dikalahkan oleh sebab-sebab kecelakaan kami, dan dengan itu menjadilah kami kaum yang sesat.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 107, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', 'رَبَّنَا أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَالِمُونَ', NULL, 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."', '“Wahai Tuhan kami, keluarkanlah kami dari neraka ini (serta kembalikanlah kami ke dunia); setelah itu kalau kami kembali lagi (mengerjakan kufur dan maksiat), maka sesungguhnya kami orang-orang yang zalim.”', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 108, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', 'قَالَ اخْسَئُوا فِيهَا وَلَا تُكَلِّمُونِ', NULL, 'He will say, "Remain despised therein and do not speak to Me.', '(Allah) berfirman: “Diamlah kamu dengan kehinaan di dalam neraka, dan janganlah kamu berkata-kata (memohon sesuatupun) kepadaKu!', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 109, 'إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'إِنَّهُ كَانَ فَرِيقٌ مِّنْ عِبَادِي يَقُولُونَ رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ', NULL, 'Indeed, there was a party of My servants who said, ''Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.''', '“Sesungguhnya ada sepuak diri hamba-hambaKu (di dunia dahulu) memohon kepadaKu dengan berkata: ‘Wahai Tuhan kami, kami telah beriman; oleh itu ampunkanlah dosa kami serta berilah rahmat kepada kami, dan sememangnya Engkaulah jua sebaik-baik Pemberi rahmat’.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 110, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 'فَاتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰ أَنسَوْكُمْ ذِكْرِي وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', NULL, 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.', '“Maka kamu jadikan mereka ejek-ejekan sehingga ejek-ejekan kamu kepada mereka menyebabkan kamu lupa mengingati balasanKu, dan kamu pula sentiasa tertawakan mereka.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 111, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', 'إِنِّي جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُوا أَنَّهُمْ هُمُ الْفَائِزُونَ', NULL, 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."', '“Sesungguhnya Aku membalas mereka pada hari ini (dengan sebaik-baik balasan) disebabkan kesabaran mereka; sesungguhnya mereka itulah orang-orang yang berjaya”.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 112, 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', 'قَالَ كَمْ لَبِثْتُمْ فِي الْأَرْضِ عَدَدَ سِنِينَ', NULL, '[Allāh] will say, "How long did you remain on earth in number of years?"', 'Allah bertanya lagi (kepada mereka yang kafir itu): “Berapa tahun lamanya kamu tinggal di bumi?”', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 113, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ ٱلْعَآدِّينَ', 'قَالُوا لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَاسْأَلِ الْعَادِّينَ', NULL, 'They will say, "We remained a day or part of a day; ask those who enumerate."', 'Mereka menjawab: “Kami tinggal (di dunia) selama sehari atau sebahagian dari sehari; maka bertanyalah kepada golongan (malaikat) yang menjaga urusan menghitung', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 114, 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', 'قَالَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', NULL, 'He will say, "You stayed not but a little - if only you had known.', 'Allah berfirman: “Kamu tidak tinggal (di dunia) melainkan sedikit masa sahaja, kalau kamu dahulu mengetahui hal ini (tentulah kamu bersiap sedia).', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 115, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', NULL, 'Then did you think that We created you uselessly and that to Us you would not be returned?"', '“Maka adakah patut kamu menyangka bahawa Kami hanya menciptakan kamu (dari tiada kepada ada) sahaja dengan tiada sebarang hikmat pada ciptaan itu? Dan kamu (menyangka pula) tidak akan dikembalikan kepada Kami?”', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 116, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 'فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لَا إِلَٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ', NULL, 'So exalted is Allāh, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.', 'Maka (dengan yang demikian) Maha Tinggilah Allah Yang Menguasai seluruh alam, lagi Yang Tetap Benar; tiada Tuhan melainkan Dia, Tuhan yang mempunyai Arasy yang mulia.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 117, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'وَمَن يَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ', NULL, 'And whoever invokes besides Allāh another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.', 'Dan sesiapa yang menyembah tuhan yang lain bersama-sama Allah, dengan tidak berdasarkan sebarang keterangan mengenainya, maka sesungguhnya hitungannya (dan balasan amalnya yang jahat itu) disediakan di sisi Tuhannya. Sesungguhnya orang-orang yang kafir tidak akan berjaya.', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(23, 118, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ', NULL, 'And, [O Muḥammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."', 'Dan berdoalah (wahai Muhammad dengan berkata): “Wahai Tuhanku, berikanlah ampun dan kurniakan rahmat, dan sememangnya Engkaulah sahaja sebaik-baik Pemberi rahmat!”', FALSE, NULL, NULL, 349, 18, 139, 300, FALSE, 0, NULL),
(24, 1, 'سُورَةٌ أَنزَلْنَـٰهَا وَفَرَضْنَـٰهَا وَأَنزَلْنَا فِيهَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', 'سورة انزلناها وفرضناها وانزلنا فيها ايات بينات لعلكم تذكرون', NULL, '[This is] a sūrah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.', 'Ini ialah satu “surah” yang Kami turunkan, dan Kami wajibkan hukum-hukumnya, serta Kami turunkan padanya ayat-ayat keterangan yang nyata supaya kamu beringat (mengamalkannya).', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 9, NULL),
(24, 2, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍ ۖ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ ٱلْمُؤْمِنِينَ', 'الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة ولا تاخذكم بهما رافة في دين الله ان كنتم تؤمنون بالله واليوم الاخر وليشهد عذابهما طائفة من المؤمنين', NULL, 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion [i.e., law] of Allāh, if you should believe in Allāh and the Last Day. And let a group of the believers witness their punishment.', 'Perempuan yang berzina dan lelaki yang berzina, hendaklah kamu sebat tiap-tiap seorang dari keduanya seratus kali sebat; dan janganlah kamu dipengaruhi oleh perasaan belas kasihan terhadap keduanya dalam menjalankan hukum ugama Allah, jika benar kamu beriman kepada Allah dan hari akhirat; dan hendaklah disaksikan hukuman seksa yang dikenakan kepada mereka itu oleh sekumpulan dari orang-orang yang beriman.', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 26, NULL),
(24, 3, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ ۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 'الزاني لا ينكح الا زانية او مشركة والزانية لا ينكحها الا زان او مشرك وحرم ذلك على المؤمنين', NULL, 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that [i.e., marriage to such persons] has been made unlawful to the believers.', 'Lelaki yang berzina (lazimnya) tidak ingin berkahwin melainkan dengan perempuan yang berzina atau perempuan musyrik; dan perempuan yang berzina itu pula (lazimnya) tidak ingin berkahwin dengannya melainkan oleh lelaki yang berzina atau lelaki musyrik. Dan perkahwinan yang demikian itu terlarang kepada orang-orang yang beriman.', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 18, NULL),
(24, 4, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَـٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَـٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَـٰدَةً أَبَدًا ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', 'والذين يرمون المحصنات ثم لم ياتوا باربعة شهداء فاجلدوهم ثمانين جلدة ولا تقبلوا لهم شهادة ابدا واولئك هم الفاسقون', NULL, 'And those who accuse chaste women and then do not produce four witnesses - lash them with eighty lashes and do not accept from them testimony ever after. And those are the defiantly disobedient,', 'Dan orang-orang yang melemparkan tuduhan (zina) kepada perempuan yang terpelihara kehormatannya, kemudian mereka tidak membawakan empat orang saksi, maka sebatlah mereka delapan puluh kali sebat; dan janganlah kamu menerima persaksian mereka itu selama-lamanya; kerana mereka adalah orang-orang yang fasik; -', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 19, NULL),
(24, 5, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم', NULL, 'Except for those who repent thereafter and reform, for indeed, Allāh is Forgiving and Merciful.', 'Kecuali orang-orang yang bertaubat sesudah itu (dari kesalahannya yang tersebut) serta memperbaiki amalannya, maka sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 11, NULL),
(24, 6, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَـٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَـٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ', 'والذين يرمون ازواجهم ولم يكن لهم شهداء الا انفسهم فشهادة احدهم اربع شهادات بالله انه لمن الصادقين', NULL, 'And those who accuse their wives [of adultery] and have no witnesses except themselves - then the witness of one of them [shall be] four testimonies [swearing] by Allāh that indeed, he is of the truthful.', 'Dan orang-orang yang menuduh isterinya berzina, sedang mereka tidak ada saksi-saksi (yang mengesahkan tuduhannya itu) hanya dirinya sendiri, maka persaksian (sah pada syarak) bagi seseorang yang menuduh itu hendaklah ia bersumpah dengan nama Allah, empat kali, bahawa sesungguhnya ia dari orang-orang yang benar; -', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 17, NULL),
(24, 7, 'وَٱلْخَـٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَـٰذِبِينَ', 'والخامسة ان لعنت الله عليه ان كان من الكاذبين', NULL, 'And the fifth [oath will be] that the curse of Allāh be upon him if he should be of the liars.', 'Dan sumpah yang kelima (hendaklah ia berkata): Bahawa laknat Allah akan menimpa dirinya jika ia dari orang-orang yang dusta.', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 9, NULL),
(24, 8, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَـٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلْكَـٰذِبِينَ', 'ويدرا عنها العذاب ان تشهد اربع شهادات بالله انه لمن الكاذبين', NULL, 'But it will prevent punishment from her if she gives four testimonies [swearing] by Allāh that indeed, he is of the liars.', 'Dan bagi menghindarkan hukuman seksa dari isteri (yang kena tuduh) itu hendaklah ia bersumpah dengan nama Allah, empat kali, bahawa suaminya (yang menuduh) itu sesungguhnya adalah dari orang-orang yang berdusta; -', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 11, NULL),
(24, 9, 'وَٱلْخَـٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّـٰدِقِينَ', 'والخامسة ان غضب الله عليها ان كان من الصادقين', NULL, 'And the fifth [oath will be] that the wrath of Allāh be upon her if he was of the truthful.', 'Dan sumpah yang kelima (hendaklah ia berkata); Bahawa kemurkaan Allah akan menimpa dirinya jika suaminya dari orang-orang yang benar.', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 9, NULL),
(24, 10, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', 'ولولا فضل الله عليكم ورحمته وان الله تواب حكيم', NULL, 'And if not for the favor of Allāh upon you and His mercy... and because Allāh is Accepting of Repentance and Wise.', 'Dan kalaulah tidak kerana adanya limpah kurnia Allah dan rahmatNya kepada kamu, dan juga (kalaulah tidak kerana) bahawa Allah Maha Penerima taubat, lagi Maha Bijaksana, (tentulah kamu akan) akan mengalami kesusahan yang sukar diatasi).', FALSE, NULL, NULL, 350, 18, 140, 301, FALSE, 9, NULL),
(24, 11, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّا لَّكُم ۖ بَلْ هُوَ خَيْرٌ لَّكُمْ ۚ لِكُلِّ ٱمْرِئٍ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ ۚ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ', 'ان الذين جاءوا بالافك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من الاثم والذي تولى كبره منهم له عذاب عظيم', NULL, 'Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather, it is good for you. For every person among them is what [punishment] he has earned from the sin, and he who took upon himself the greater portion thereof - for him is a great punishment [i.e., Hellfire].', 'Sesungguhnya orang-orang yang membawa berita yang amat dusta itu ialah segolongan dari kalangan kamu; janganlah kamu menyangka (berita yang dusta) itu buruk bagi kamu, bahkan ia baik bagi kamu. Tiap-tiap seorang di antara mereka akan beroleh hukuman sepadan dengan kesalahan yang dilakukannya itu, dan orang yang mengambil bahagian besar dalam menyiarkannya di antara mereka, akan beroleh seksa yang besar (di dunia dan di akhirat).', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 28, NULL),
(24, 12, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَـٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا۟ هَـٰذَآ إِفْكٌ مُّبِينٌ', 'لولا اذ سمعتموه ظن المؤمنون والمؤمنات بانفسهم خيرا وقالوا هذا افك مبين', NULL, 'Why, when you heard it, did not the believing men and believing women think good of themselves [i.e., one another] and say, "This is an obvious falsehood"?', 'Sepatutnya semasa kamu mendengar tuduhan itu, orang-orang yang beriman - lelaki dan perempuan, menaruh baik sangka kepada diri (orang-orang) mereka sendiri. dan berkata: “Ini ialah tuduhan dusta yang nyata”.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 12, NULL),
(24, 13, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ ۚ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَـٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَـٰذِبُونَ', 'لولا جاءوا عليه باربعة شهداء فاذ لم ياتوا بالشهداء فاولئك عند الله هم الكاذبون', NULL, 'Why did they [who slandered] not produce for it four witnesses? And when they do not produce the witnesses, then it is they, in the sight of Allāh, who are the liars.', 'Sepatutnya mereka (yang menuduh) membawa empat orang saksi membuktikan tuduhan itu. Oleh kerana mereka tidak mendatangkan empat orang saksi, maka mereka itu pada sisi hukum Allah, adalah orang-orang yang dusta.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 14, NULL),
(24, 14, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', 'ولولا فضل الله عليكم ورحمته في الدنيا والاخرة لمسكم في ما افضتم فيه عذاب عظيم', NULL, 'And if it had not been for the favor of Allāh upon you and His mercy in this world and the Hereafter, you would have been touched for that [lie] in which you were involved by a great punishment', 'Dan kalaulah tidak kerana adanya limpah kurnia Allah dan rahmatNya kepada kamu di dunia dan di akhirat, tentulah kamu dikenakan azab seksa yang besar disebabkan kamu turut campur dalam berita palsu itu; -', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 15, NULL),
(24, 15, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌ', 'اذ تلقونه بالسنتكم وتقولون بافواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم', NULL, 'When you received it with your tongues and said with your mouths that of which you had no knowledge and thought it was insignificant while it was, in the sight of Allāh, tremendous.', 'Iaitu semasa kamu bertanya atau menceritakan berita dusta itu dengan lidah kamu, dan memperkatakan dengan mulut kamu akan sesuatu yang kamu tidak mempunyai pengetahuan yang sah mengenainya; dan kamu pula menyangkanya perkara kecil, pada hal ia pada sisi hukum Allah adalah perkara yang besar dosanya.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 16, NULL),
(24, 16, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَـٰذَا سُبْحَـٰنَكَ هَـٰذَا بُهْتَـٰنٌ عَظِيمٌ', 'ولولا اذ سمعتموه قلتم ما يكون لنا ان نتكلم بهذا سبحانك هذا بهتان عظيم', NULL, 'And why, when you heard it, did you not say, "It is not for us to speak of this. Exalted are You, [O Allāh]; this is a great slander"?', 'Dan sepatutnya semasa kamu mendengarnya, kamu segera berkata: “Tidaklah layak bagi kami memperkatakan hal ini! Maha Suci Engkau (ya Allah dari mencemarkan nama baik ahli rumah Rasulullah)! Ini adalah satu dusta besar yang mengejutkan”.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 14, NULL),
(24, 17, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', 'يعظكم الله ان تعودوا لمثله ابدا ان كنتم مؤمنين', NULL, 'Allāh warns you against returning to the likes of this [conduct], ever, if you should be believers.', 'Allah memberi pengajaran kepada kamu, supaya kamu tidak mengulangi perbuatan yang sedemikian ini selama-lamanya, jika betul kamu orang-orang yang beriman.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 9, NULL),
(24, 18, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'ويبين الله لكم الايات والله عليم حكيم', NULL, 'And Allāh makes clear to you the verses [i.e., His rulings], and Allāh is Knowing and Wise.', 'Dan Allah menjelaskan kepada kamu ayat-ayat keterangan (hukum-hukumNya); kerana Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 7, NULL),
(24, 19, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَـٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'ان الذين يحبون ان تشيع الفاحشة في الذين امنوا لهم عذاب اليم في الدنيا والاخرة والله يعلم وانتم لا تعلمون', NULL, 'Indeed, those who like that immorality should be spread [or publicized] among those who have believed will have a painful punishment in this world and the Hereafter. And Allāh knows and you do not know.', 'Sesungguhnya orang-orang yang suka terhebah tuduhan-tuduhan yang buruk dalam kalangan orang-orang yang beriman, mereka akan beroleh azab seksa yang tidak terperi sakitnya di dunia dan di akhirat; dan (ingatlah) Allah mengetahui (segala perkara) sedang kamu tidak mengetahui (yang demikian).', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 20, NULL),
(24, 20, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌ رَّحِيمٌ', 'ولولا فضل الله عليكم ورحمته وان الله رءوف رحيم', NULL, 'And if it had not been for the favor of Allāh upon you and His mercy... and because Allāh is Kind and Merciful.', 'Dan kalaulah tidak kerana adanya limpah kurnia Allah dan rahmatNya kepada kamu, dan juga (kalaulah tidak kerana) bahawa Allah Amat melimpah belas kasihanNya, (tentulah kamu akan ditimpa azab dengan serta-merta).', FALSE, NULL, NULL, 351, 18, 140, 302, FALSE, 9, NULL),
(24, 21, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ وَمَن يَتَّبِعْ خُطُوَاتِ الشَّيْطَانِ فَإِنَّهُ يَأْمُرُ بِالْفَحْشَاءِ وَالْمُنكَرِ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ اللَّهَ يُزَكِّي مَن يَشَاءُ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allāh upon you and His mercy, not one of you would have been pure, ever, but Allāh purifies whom He wills, and Allāh is Hearing and Knowing.', 'Wahai orang-orang yang beriman, janganlah kamu menurut jejak langkah Syaitan; dan sesiapa yang menurut jejak langkah Syaitan, maka sesungguhnya Syaitan itu sentiasa menyuruh (pengikut-pengikutnya) melakukan perkara yang keji dan perbuatan yang mungkar. Dan kalaulah tidak kerana limpah kurnia Allah dan rahmatNya kepada kamu, nescaya tidak ada seorang pun di antara kamu menjadi bersih dari dosanya selama-lamanya; akan tetapi Allah membersihkan sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan (ingatlah Allah Maha Mendengar) lagi Maha Mengetahui', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 22, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'وَلَا يَأْتَلِ أُولُو الْفَضْلِ مِنكُمْ وَالسَّعَةِ أَن يُؤْتُوا أُولِي الْقُرْبَىٰ وَالْمَسَاكِينَ وَالْمُهَاجِرِينَ فِي سَبِيلِ اللَّهِ وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allāh, and let them pardon and overlook. Would you not like that Allāh should forgive you? And Allāh is Forgiving and Merciful.', 'Dan janganlah orang-orang yang berharta serta lapang hidupnya dari kalangan kamu, bersumpah tidak mahu lagi memberi bantuan kepada kaum kerabat dan orang-orang miskin serta orang-orang yang berhijrah pada jalan Allah; dan (sebaliknya) hendaklah mereka memaafkan serta melupakan kesalahan orang-orang itu; tidakkah kamu suka supaya Allah mengampunkan dosa kamu? Dan (ingatlah) Allah Maha Pengampun lagi Maha Mengasihani.', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 23, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'إِنَّ الَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ لُعِنُوا فِي الدُّنْيَا وَالْآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', NULL, 'Indeed, those who [falsely] accuse chaste, unaware and believing women are cursed in this world and the Hereafter; and they will have a great punishment', 'Sesungguhnya orang-orang yang menuduh perempuan-perempuan yang terpelihara kehormatannya, yang tidak terlintas memikirkan sebarang kejahatan, lagi yang beriman, akan dilaknat (oleh Allah) di dunia dan di akhirat dan, mereka pula akan beroleh azab seksa yang besar;', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا يَعْمَلُونَ', NULL, 'On a Day when their tongues, their hands and their feet will bear witness against them as to what they used to do.', 'Pada hari lidah mereka dan tangan mereka serta kaki mereka menjadi saksi terhadap diri mereka sendiri, tentang segala yang mereka lakukan.', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 25, 'يَوْمَئِذٍ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', 'يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ وَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ', NULL, 'That Day, Allāh will pay them in full their true [i.e., deserved] recompense, and they will know that it is Allāh who is the manifest Truth [i.e., perfect in justice].', 'Pada hari itu Allah akan menyempurnakan untuk mereka balasan (azab seksa) yang berhak mereka mendapatnya, dan mereka pula akan mengetahui bahawa Allah ialah Tuhan Yang Maha Adil, lagi nyata keadilanNya.', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 26, 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'الْخَبِيثَاتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَاتِ وَالطَّيِّبَاتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِ أُولَٰئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', NULL, 'Evil words are for evil men, and evil men are [subjected] to evil words. And good words are for good men, and good men are [an object] of good words. Those [good people] are declared innocent of what they [i.e., slanderers] say. For them is forgiveness and noble provision.', '(Lazimnya) perempuan-perempuan yang jahat adalah untuk lelaki-lelaki yang jahat, dan lelaki-lelaki yang jahat untuk perempuan-perempuan yang jahat; dan (sebaliknya) perempuan-perempuan yang baik untuk lelaki-lelaki yang baik, dan lelaki-lelaki yang baik untuk perempuan-perempuan yang baik. Mereka (yang baik) itu adalah bersih dari (tuduhan buruk) yang dikatakan oleh orang-orang (yang jahat); mereka (yang baik) itu akan beroleh pengampunan (dari Allah) dan pengurniaan yang mulia.', FALSE, NULL, NULL, 352, 18, 141, 303, FALSE, 0, NULL),
(24, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَىٰ أَهْلِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', NULL, 'O you who have believed, do not enter houses other than your own houses until you ascertain welcome and greet their inhabitants. That is best for you; perhaps you will be reminded [i.e., advised].', 'Wahai orang-orang yang beriman, janganlah kamu masuk ke dalam mana-mana rumah yang bukan rumah kamu, sehingga kamu lebih dahulu meminta izin serta memberi salam kepada penduduknya; yang demikian adalah lebih baik bagi kamu, supaya kamu beringat (mematuhi cara dan peraturan yang sopan itu).', FALSE, NULL, NULL, 352, 18, 141, 304, FALSE, 0, NULL),
(24, 28, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ هُوَ أَزْكَىٰ لَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'فَإِن لَّمْ تَجِدُوا فِيهَا أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ وَإِن قِيلَ لَكُمُ ارْجِعُوا فَارْجِعُوا هُوَ أَزْكَىٰ لَكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', NULL, 'And if you do not find anyone therein, do not enter them until permission has been given you. And if it is said to you, "Go back," then go back; it is purer for you. And Allāh is Knowing of what you do.', 'Maka sekiranya kamu tidak mendapati sesiapa (yang berhak memberi izin) maka janganlah masuk ke dalam rumah itu sehingga kamu diberi izin; dan jika dikatakan kepada kamu “baliklah”, maka hendaklah kamu berundur balik; cara yang demikian adalah lebih suci bagi kamu; dan (ingatlah) Allah Maha Mengetahui akan apa yang kamu lakukan.', FALSE, NULL, NULL, 353, 18, 141, 304, FALSE, 0, NULL),
(24, 29, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَٰعٌ لَّكُمْ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَّكُمْ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', NULL, 'There is no blame upon you for entering houses not inhabited in which there is convenience for you. And Allāh knows what you reveal and what you conceal.', 'Tidaklah menjadi salah kamu memasuki (dengan tidak meminta izin) mana-mana rumah yang tidak didiami orang, yang ada keperluan kamu padanya; dan (ingatlah) Allah mengetahui akan apa yang kamu zahirkan dan apa yang kamu sembunyikan.', FALSE, NULL, NULL, 353, 18, 141, 304, FALSE, 0, NULL),
(24, 30, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ذَٰلِكَ أَزْكَىٰ لَهُمْ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَٰلِكَ أَزْكَىٰ لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ', NULL, 'Tell the believing men to reduce [some] of their vision and guard their private parts. That is purer for them. Indeed, Allāh is [fully] Aware of what they do.', 'Katakanlah (wahai Muhammad) kepada orang-orang lelaki yang beriman supaya mereka menyekat pandangan mereka (daripada memandang yang haram), dan memelihara kehormatan mereka. Yang demikian itu lebih suci bagi mereka; sesungguhnya Allah Amat Mendalam PengetahuanNya tentang apa yang mereka kerjakan.', FALSE, NULL, NULL, 353, 18, 141, 304, FALSE, 0, NULL),
(24, 31, 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', 'وَقُل لِّلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَىٰ عَوْرَاتِ النِّسَاءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', NULL, 'And tell the believing women to reduce [some] of their vision and guard their private parts and not expose their adornment except that which [necessarily] appears thereof and to wrap [a portion of] their headcovers over their chests and not expose their adornment [i.e., beauty] except to their husbands, their fathers, their husbands'' fathers, their sons, their husbands'' sons, their brothers, their brothers'' sons, their sisters'' sons, their women, that which their right hands possess [i.e., slaves], or those male attendants having no physical desire, or children who are not yet aware of the private aspects of women. And let them not stamp their feet to make known what they conceal of their adornment. And turn to Allāh in repentance, all of you, O believers, that you might succeed.', 'Dan katakanlah kepada perempuan-perempuan yang beriman supaya menyekat pandangan mereka (daripada memandang yang haram), dan memelihara kehormatan mereka; dan janganlah mereka memperlihatkan perhiasan tubuh mereka kecuali yang zahir daripadanya; dan hendaklah mereka menutup belahan leher bajunya dengan tudung kepala mereka; dan janganlah mereka memperlihatkan perhiasan tubuh mereka melainkan kepada suami mereka, atau bapa mereka atau bapa mertua mereka atau anak-anak mereka, atau anak-anak tiri mereka, atau saudara-saudara mereka, atau anak bagi saudara-saudara mereka yang lelaki, atau anak bagi saudara-saudara mereka yang perempuan, atau perempuan-perempuan Islam, atau hamba-hamba mereka, atau orang gaji dari orang-orang lelaki yang telah tua dan tidak berkeinginan kepada perempuan, atau kanak-kanak yang belum mengerti lagi tentang aurat perempuan; dan janganlah mereka menghentakkan kaki untuk diketahui orang akan apa yang tersembunyi dari perhiasan mereka; dan bertaubatlah kamu sekalian kepada Allah, wahai orang-orang yang beriman, supaya kamu berjaya.', FALSE, NULL, NULL, 353, 18, 141, 304, FALSE, 0, NULL),
(24, 32, 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'وَأَنكِحُوا الْأَيَامَىٰ مِنكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِن يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ وَاللَّهُ وَاسِعٌ عَلِيمٌ', NULL, 'And marry the unmarried among you and the righteous among your male slaves and female slaves. If they should be poor, Allāh will enrich them from His bounty, and Allāh is all-Encompassing and Knowing.', 'Dan kahwinkanlah orang-orang bujang (lelaki dan perempuan) dari kalangan kamu, dan orang-orang yang soleh dari hamba-hamba kamu, lelaki dan perempuan. Jika mereka miskin, Allah akan memberikan kekayaan kepada mereka dari limpah kurniaNya kerana Allah Maha Luas (rahmatNya dan limpah kurniaNya), lagi Maha Mengetahui.', FALSE, NULL, NULL, 354, 18, 141, 304, FALSE, 0, NULL),
(24, 33, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ', 'وَلْيَسْتَعْفِفِ الَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ اللَّهُ مِن فَضْلِهِ وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَآتُوهُم مِّن مَّالِ اللَّهِ الَّذِي آتَاكُمْ وَلَا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا عَرَضَ الْحَيَاةِ الدُّنْيَا وَمَن يُكْرِههُّنَّ فَإِنَّ اللَّهَ مِن بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَّحِيمٌ', NULL, 'But let them who find not [the means for] marriage abstain [from sexual relations] until Allāh enriches them from His bounty. And those who seek a contract [for eventual emancipation] from among whom your right hands possess - then make a contract with them if you know there is within them goodness and give them from the wealth of Allāh which He has given you. And do not compel your slave girls to prostitution, if they desire chastity, to seek [thereby] the temporary interests of worldly life. And if someone should compel them, then indeed, Allāh is [to them], after their compulsion, Forgiving and Merciful.', 'Dan orang-orang yang tidak mempunyai kemampuan berkahwin, hendaklah mereka menjaga kehormatannya sehingga Allah memberi kekayaan kepada mereka dari limpah kurniaNya; dan hamba-hamba kamu (lelaki dan perempuan) yang hendak membuat surat perjanjian untuk memerdekakan dirinya (dengan jumlah bayaran yang tertentu), hendaklah kamu melaksanakan perjanjian itu dengan mereka jika kamu mengetahui ada sifat-sifat yang baik pada diri mereka (yang melayakkannya berbuat demikian); dan berilah kepada mereka dari harta Allah yang telah dikurniakan kepada kamu. Dan janganlah kamu paksakan hamba-hamba perempuan kamu melacurkan diri manakala mereka mahu menjaga kehormatannya, kerana kamu berkehendakkan kesenangan hidup di dunia. Dan sesiapa yang memaksa mereka, maka sesungguhnya Allah - sesudah paksaan yang dilakukan kepada mereka - Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 354, 18, 141, 304, FALSE, 0, NULL),
(24, 34, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَمَثَلًا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'وَلَقَدْ أَنزَلْنَا إِلَيْكُمْ آيَاتٍ مُّبَيِّنَاتٍ وَمَثَلًا مِّنَ الَّذِينَ خَلَوْا مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', NULL, 'And We have certainly sent down to you distinct verses and examples from those who passed on before you and an admonition for those who fear Allāh.', 'Dan sesungguhnya, Kami telah menurunkan kepada kamu, ayat-ayat keterangan yang menjelaskan (hukum-hukum suruh dan tegah), dan contoh tauladan (mengenai kisah-kisah dan berita) orang-orang yang telah lalu sebelum kamu, serta nasihat pengajaran bagi orang-orang yang (mahu) bertaqwa.', FALSE, NULL, NULL, 354, 18, 141, 304, FALSE, 0, NULL),
(24, 35, 'ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَىٰ نُورٍ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَارَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَىٰ نُورٍ يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاءُ وَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'Allāh is the Light of the heavens and the earth. The example of His light is like a niche within which is a lamp; the lamp is within glass, the glass as if it were a pearly [white] star lit from [the oil of] a blessed olive tree, neither of the east nor of the west, whose oil would almost glow even if untouched by fire. Light upon light. Allāh guides to His light whom He wills. And Allāh presents examples for the people, and Allāh is Knowing of all things.', 'Allah yang menerangi langit dan bumi. Bandingan nur hidayah petunjuk Allah (Kitab Suci Al-Quran) adalah sebagai sebuah “misykaat” yang berisi sebuah lampu; lampu itu dalam geluk kaca (qandil), geluk kaca itu pula (jernih terang) laksana bintang yang bersinar cemerlang; lampu itu dinyalakan dengan minyak dari pokok yang banyak manfaatnya, (iaitu) pokok zaitun yang bukan sahaja disinari matahari semasa naiknya dan bukan sahaja semasa turunnya (tetapi ia sentiasa terdedah kepada matahari); hampir-hampir minyaknya itu - dengan sendirinya - memancarkan cahaya bersinar (kerana jernihnya) walaupun ia tidak disentuh api; (sinaran nur hidayah yang demikian bandingannya adalah sinaran yang berganda-ganda): cahaya berlapis cahaya. Allah memimpin sesiapa yang dikehendakiNya (menurut undang-undang dan peraturanNya) kepada nur hidayahNya itu; dan Allah mengemukakan berbagai-bagai misal perbandingan untuk umat manusia; dan Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 354, 18, 142, 305, FALSE, 0, NULL),
(24, 36, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', 'فِي بُيُوتٍ أَذِنَ اللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ يُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالْآصَالِ', NULL, '[Such niches are] in houses [i.e., mosques] which Allāh has ordered to be raised and that His name be mentioned [i.e., praised] therein; exalting Him within them in the morning and the evenings', '(Nur hidayah petunjuk Allah itu bersinar dengan nyatanya terutama sekali) di rumah-rumah ibadat yang diperintahkan oleh Allah supaya dimuliakan keadaannya dan disebut serta diperingat nama Allah padanya; di situ juga dikerjakan ibadat mensuci dan memuji Allah pada waktu pagi dan petang.', FALSE, NULL, NULL, 354, 18, 142, 305, FALSE, 0, NULL),
(24, 37, 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَن ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالْأَبْصَارُ', NULL, '[Are] men whom neither commerce nor sale distracts from the remembrance of Allāh and performance of prayer and giving of zakāh. They fear a Day in which the hearts and eyes will [fearfully] turn about -', '(Ibadat itu dikerjakan oleh) orang-orang yang kuat imannya yang tidak dilalaikan oleh perniagaan atau berjual-beli daripada menyebut serta mengingati Allah, dan mendirikan sembahyang serta memberi zakat; mereka takutkan hari (kiamat) yang padanya berbalik-balik hati dan pandangan.', FALSE, NULL, NULL, 355, 18, 142, 305, FALSE, 0, NULL),
(24, 38, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُم مِّن فَضْلِهِ وَاللَّهُ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ', NULL, 'That Allāh may reward them [according to] the best of what they did and increase them from His bounty. And Allāh gives provision to whom He wills without account [i.e., limit].', '(Mereka mengerjakan semuanya itu) supaya Allah membalas mereka dengan sebaik-baik balasan bagi apa yang mereka kerjakan, dan menambahi mereka lagi dari limpah kurniaNya; dan sememangnya Allah memberi rezeki kepada sesiapa yang dikehendakiNya dengan tidak terhitung.', FALSE, NULL, NULL, 355, 18, 142, 305, FALSE, 0, NULL),
(24, 39, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'وَالَّذِينَ كَفَرُوا أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَاءً حَتَّىٰ إِذَا جَاءَهُ لَمْ يَجِدْهُ شَيْئًا وَوَجَدَ اللَّهَ عِندَهُ فَوَفَّاهُ حِسَابَهُ وَاللَّهُ سَرِيعُ الْحِسَابِ', NULL, 'But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allāh before him, and He will pay him in full his due; and Allāh is swift in account.', 'Dan orang-orang yang kafir pula, amal-amal mereka adalah umpama riak sinaran panas di tanah rata yang disangkanya air oleh orang yang dahaga, (lalu ia menuju ke arahnya) sehingga apabila ia datang ke tempat itu, tidak didapati sesuatu pun yang disangkanya itu; (demikianlah keadaan orang kafir, tidak mendapat faedah dari amalnya sebagaimana yang disangkanya) dan ia tetap mendapati hukum Allah di sisi amalnya, lalu Allah meyempurnakan hitungan amalnya (serta membalasnya); dan (ingatlah) Allah Amat segera hitungan hisabNya.', FALSE, NULL, NULL, 355, 18, 142, 305, FALSE, 0, NULL),
(24, 40, 'أَوْ كَظُلُمَٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ', 'أَوْ كَظُلُمَاتٍ فِي بَحْرٍ لُّجِّيٍّ يَغْشَاهُ مَوْجٌ مِّن فَوْقِهِ مَوْجٌ مِّن فَوْقِهِ سَحَابٌ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا وَمَن لَّمْ يَجْعَلِ اللَّهُ لَهُ نُورًا فَمَا لَهُ مِن نُّورٍ', NULL, 'Or [they are] like darknesses within an unfathomable sea which is covered by waves, upon which are waves, over which are clouds - darknesses, some of them upon others. When one puts out his hand [therein], he can hardly see it. And he to whom Allāh has not granted light - for him there is no light.', 'Atau (orang-orang kafir itu keadaannya) adalah umpama keadaan (orang yang di dalam) gelap-gelita di lautan yang dalam, yang diliputi oleh ombak bertindih ombak; di sebelah atasnya pula awan tebal (demikianlah keadaannya) gelap-gelita berlapis-lapis - apabila orang itu mengeluarkan tangannya, ia tidak dapat melihatnya sama sekali. Dan (ingatlah) sesiapa yang tidak dijadikan Allah menurut undang-undang peraturanNya mendapat cahaya (hidayah petunjuk) maka ia tidak akan beroleh sebarang cahaya (yang akan memandunya ke jalan yang benar).', FALSE, NULL, NULL, 355, 18, 142, 305, FALSE, 0, NULL),
(24, 41, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'أَلَمْ تَرَ أَنَّ اللَّهَ يُسَبِّحُ لَهُ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ وَالطَّيْرُ صَافَّاتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ', NULL, 'Do you not see that Allāh is exalted by whomever is within the heavens and the earth and [by] the birds with wings spread [in flight]? Each [of them] has known his [means of] prayer and exalting [Him], and Allāh is Knowing of what they do.', 'Tidakkah engkau mengetahui bahawasanya Allah (Yang Maha Esa dan Maha Kuasa) sentiasa bertasbih kepadaNya sekalian makhluk yang ada di langit dan di bumi serta burung-burung yang terbang berbaris di angkasa? Masing-masing sedia mengetahui (menurut keadaan semulajadinya) akan cara mengerjakan ibadatnya kepada Allah dan memujiNya; dan Allah Maha Mengetahui akan apa yang mereka lakukan.', FALSE, NULL, NULL, 355, 18, 142, 306, FALSE, 0, NULL),
(24, 42, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَإِلَى اللَّهِ الْمَصِيرُ', NULL, 'And to Allāh belongs the dominion of the heavens and the earth, and to Allāh is the destination.', 'Dan bagi Allah jualah kuasa pemerintahan langit dan bumi dan kepada Allah sahaja tempat kembali (sekalian makhluk).', FALSE, NULL, NULL, 355, 18, 142, 306, FALSE, 0, NULL),
(24, 43, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍ فِيهَا مِنۢ بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', 'أَلَمْ تَرَ أَنَّ اللَّهَ يُزْجِي سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُ ثُمَّ يَجْعَلُهُ رُكَامًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِهِ وَيُنَزِّلُ مِنَ السَّمَاءِ مِن جِبَالٍ فِيهَا مِن بَرَدٍ فَيُصِيبُ بِهِ مَن يَشَاءُ وَيَصْرِفُهُ عَن مَّن يَشَاءُ يَكَادُ سَنَا بَرْقِهِ يَذْهَبُ بِالْأَبْصَارِ', NULL, 'Do you not see that Allāh drives clouds? Then He brings them together; then He makes them into a mass, and you see the rain emerge from within it. And He sends down from the sky, mountains [of clouds] within which is hail, and He strikes with it whom He wills and averts it from whom He wills. The flash of its lightning almost takes away the eyesight.', 'Tidakkah engkau melihat bahawasanya Allah mengarahkan awan bergerak perlahan-lahan, kemudian Dia mengumpulkan kelompok-kelompoknya, kemudian Dia menjadikannya tebal berlapis-lapis? Selepas itu engkau melihat hujan turun dari celah-celahnya. Dan Allah pula menurunkan hujan batu dari langit, dari gunung-ganang (awan) yang ada padanya; lalu Ia menimpakan hujan batu itu kepada sesiapa yang dikehendakiNya, dan menjauhkannya dari sesiapa yang dikehendakiNya. Sinaran kilat yang terpancar dari awan yang demikian keadaannya, hampir-hampir menyambar dan menghilangkan pandangan.', FALSE, NULL, NULL, 355, 18, 142, 306, FALSE, 0, NULL),
(24, 44, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'يُقَلِّبُ اللَّهُ اللَّيْلَ وَالنَّهَارَ إِنَّ فِي ذَٰلِكَ لَعِبْرَةً لِّأُولِي الْأَبْصَارِ', NULL, 'Allāh alternates the night and the day. Indeed in that is a lesson for those who have vision.', 'Allah menukarkan malam dan siang silih berganti; sesungguhnya yang demikian mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang celik mata hatinya berfikir.', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 45, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَاللَّهُ خَلَقَ كُلَّ دَابَّةٍ مِّن مَّاءٍ فَمِنْهُم مَّن يَمْشِي عَلَىٰ بَطْنِهِ وَمِنْهُم مَّن يَمْشِي عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِي عَلَىٰ أَرْبَعٍ يَخْلُقُ اللَّهُ مَا يَشَاءُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Allāh has created every [living] creature from water. And of them are those that move on their bellies, and of them are those that walk on two legs, and of them are those that walk on four. Allāh creates what He wills. Indeed, Allāh is over all things competent.', 'Dan Allah menciptakan tiap-tiap haiwan yang bergerak itu dari air; maka sebahagian di antara mereka menjalar atas perutnya, dan sebahagian di antaranya berjalan dengan dua kaki, dan sebahagian lagi berjalan dengan empat kaki. Allah menciptakan apa sahaja yang Ia kehendaki (selain dari yang tersebut), kerana sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 46, 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'لَّقَدْ أَنزَلْنَا آيَاتٍ مُّبَيِّنَاتٍ وَاللَّهُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'We have certainly sent down distinct verses. And Allāh guides whom He wills to a straight path.', 'Demi sesungguhnya, Kami telah menurunkan ayat-ayat yang menerangkan (hakikat kebenaran dengan berbagai dalil dan bukti); dan Allah memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya ke jalan yang lurus.', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 47, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'وَيَقُولُونَ آمَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّن بَعْدِ ذَٰلِكَ وَمَا أُولَٰئِكَ بِالْمُؤْمِنِينَ', NULL, 'But they [i.e., the hypocrites] say, "We have believed in Allāh and in the Messenger, and we obey"; then a party of them turns away after that. And those are not believers.', 'Dan (di antara orang-orang yang tidak dikehendakiNya ke jalan yang lurus ialah) mereka yang berkata: “Kami beriman kepada Allah dan kepada RasulNya serta kami taat”; kemudian sepuak dari mereka berpaling (membelakangkan perintah Allah dan Rasul) sesudah pengakuan itu, dan (kerana berpalingnya) tidaklah mereka itu menjadi orang-orang yang sebenarnya beriman.', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 48, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', 'وَإِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', NULL, 'And when they are called to [the words of] Allāh and His Messenger to judge between them, at once a party of them turns aside [in refusal].', 'Dan (bukti berpalingnya mereka ialah) apabila mereka diajak kepada Kitab Allah dan Sunnah RasulNya supaya menjadi hakim memutuskan sesuatu di antara mereka, maka dengan serta-merta sepuak dari mereka berpaling ingkar (menolak ajakan itu jika keputusan tidak menguntungkan mereka).', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 49, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 'وَإِن يَكُن لَّهُمُ الْحَقُّ يَأْتُوا إِلَيْهِ مُذْعِنِينَ', NULL, 'But if the right is theirs, they come to him in prompt obedience.', 'Dan (sebaliknya) jika keputusan itu memberi hak kepada mereka, mereka segera datang kepadanya dengan tunduk taat (menerima hukumnya).', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 50, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ارْتَابُوا أَمْ يَخَافُونَ أَن يَحِيفَ اللَّهُ عَلَيْهِمْ وَرَسُولُهُ بَلْ أُولَٰئِكَ هُمُ الظَّالِمُونَ', NULL, 'Is there disease in their hearts? Or have they doubted? Or do they fear that Allāh will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers [i.e., the unjust].', '(Mengapa mereka bersikap demikian), adakah kerana hati mereka mengandungi penyakit (kufur), atau kerana mereka ragu-ragu (terhadap kebenaran hukuman), ataupun kerana mereka takut bahawa Allah dan RasulNya akan berlaku zalim kepada mereka? (Allah dan RasulNya tidak sekali-kali akan berlaku zalim) bahkan merekalah sendiri orang-orang yang zalim (disebabkan keraguan dan kekufuran mereka).', FALSE, NULL, NULL, 356, 18, 142, 306, FALSE, 0, NULL),
(24, 51, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا سَمِعْنَا وَأَطَعْنَا وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'The only statement of the [true] believers when they are called to Allāh and His Messenger to judge between them is that they say, "We hear and we obey." And those are the successful.', 'Sesungguhnya perkataan yang diucapkan oleh orang-orang yang beriman ketika mereka diajak ke pada Kitab Allah dan Sunnah RasulNya, supaya menjadi hakim memutuskan sesuatu di antara mereka, hanyalah mereka berkata: “Kami dengar dan kami taat”: dan mereka itulah orang-orang yang beroleh kejayaan.', FALSE, NULL, NULL, 356, 18, 142, 307, FALSE, 0, NULL),
(24, 52, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ وَيَخْشَ اللَّهَ وَيَتَّقْهِ فَأُولَٰئِكَ هُمُ الْفَائِزُونَ', NULL, 'And whoever obeys Allāh and His Messenger and fears Allāh and is conscious of Him - it is those who are the attainers.', 'Dan sesiapa yang taat kepada Allah dan RasulNya dan takut melanggar perintah Allah serta, menjaga dirinya jangan terdedah kepada azab Allah, maka merekalah orang-orang yang beroleh kemenangan.', FALSE, NULL, NULL, 356, 18, 142, 307, FALSE, 0, NULL),
(24, 53, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُل لَّا تُقْسِمُوا۟ طَاعَةٌ مَّعْرُوفَةٌ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُل لَّا تُقْسِمُوا طَاعَةٌ مَّعْرُوفَةٌ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ', NULL, 'And they swear by Allāh their strongest oaths that if you ordered them, they would go forth [in Allāh''s cause]. Say, "Do not swear. [Such] obedience is known. Indeed, Allāh is [fully] Aware of that which you do."', 'Dan mereka (yang munafik) bersumpah dengan nama Allah, dengan sebebar-benar sumpahnya: bahawa jika engkau (wahai Muhammad) perintahkan mereka (keluar berjihad), tentulah mereka akan keluar. Katakanlah: “Janganlah kamu bersumpah, (taat kamu itu) taat yang terkenal (dustanya). Sesungguhnya Allah Amat Mendalam pengetahuanNya tentang apa yang kamu lakukan”.', FALSE, NULL, NULL, 356, 18, 143, 307, FALSE, 0, NULL),
(24, 54, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ وَإِن تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ الْمُبِينُ', NULL, 'Say, "Obey Allāh and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification."', 'Katakanlah lagi (kepada mereka): “Taatlah kamu kepada Allah dan taatlah kepada Rasul Allah. Kemudian jika kamu berpaling ingkar maka ketahuilah bahawa sesungguhnya Rasul Allah hanya bertanggungjawab akan apa yang ditugaskan kepadanya, dan kamu pula bertanggungjawab akan apa yang ditugaskan kepada kamu. Dan jika kamu taat kepadanya nescaya kamu beroleh hidayah petunjuk; dan (sebenarnya) Rasul Allah hanyalah bertanggungjawab menyampaikan perintah-perintah Allah dengan penjelasan yang terang nyata”.', FALSE, NULL, NULL, 357, 18, 143, 307, FALSE, 0, NULL),
(24, 55, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًٔا وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّن بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ', NULL, 'Allāh has promised those who have believed among you and done righteous deeds that He will surely grant them succession [to authority] upon the earth just as He granted it to those before them and that He will surely establish for them [therein] their religion which He has preferred for them and that He will surely substitute for them, after their fear, security, [for] they worship Me, not associating anything with Me. But whoever disbelieves after that - then those are the defiantly disobedient.', 'Allah menjanjikan orang-orang yang beriman dan beramal soleh dari kalangan kamu (wahai umat Muhammad) bahawa Ia akan menjadikan mereka khalifah-khalifah yang memegang kuasa pemerintahan di bumi, sebagaimana Ia telah menjadikan orang-orang yang sebelum mereka: khalifah-khalifah yang berkuasa; dan Ia akan menguatkan dan mengembangkan ugama mereka (ugama Islam) yang telah diredhaiNya untuk mereka; dan Ia juga akan menggantikan bagi mereka keamanan setelah mereka mengalami ketakutan (dari ancaman musuh). Mereka terus beribadat kepadaKu dengan tidak mempersekutukan sesuatu yang lain denganKu. Dan (ingatlah) sesiapa yang kufur ingkar sesudah itu, maka mereka itulah orang-orang yang derhaka.', FALSE, NULL, NULL, 357, 18, 143, 307, FALSE, 0, NULL),
(24, 56, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'And establish prayer and give zakāh and obey the Messenger - that you may receive mercy.', 'Dan dirikanlah kamu akan sembahyang serta berilah zakat; dan taatlah kamu kepada Rasul Allah; supaya kamu beroleh rahmat.', FALSE, NULL, NULL, 357, 18, 143, 307, FALSE, 0, NULL),
(24, 57, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَأْوَىٰهُمُ ٱلنَّارُ وَلَبِئْسَ ٱلْمَصِيرُ', 'لَا تَحْسَبَنَّ الَّذِينَ كَفَرُوا مُعْجِزِينَ فِي الْأَرْضِ وَمَأْوَاهُمُ النَّارُ وَلَبِئْسَ الْمَصِيرُ', NULL, 'Never think that the disbelievers are causing failure [to Allāh] upon the earth. Their refuge will be the Fire - and how wretched the destination.', 'Janganlah engkau menyangka orang-orang kafir itu akan dapat melemahkan kekuasaan Allah (daripada menimpakan azab kepada mereka) di dunia, sedang tempat kembali mereka ialah neraka; dan sesungguhnya neraka itu adalah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 357, 18, 143, 307, FALSE, 0, NULL),
(24, 58, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ثَلَٰثُ عَوْرَٰتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنكُمْ ثَلَاثَ مَرَّاتٍ مِّن قَبْلِ صَلَاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ الظَّهِيرَةِ وَمِن بَعْدِ صَلَاةِ الْعِشَاءِ ثَلَاثُ عَوْرَاتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'O you who have believed, let those whom your right hands possess and those who have not [yet] reached puberty among you ask permission of you [before entering] at three times: before the dawn prayer and when you put aside your clothing [for rest] at noon and after the night prayer. [These are] three times of privacy for you. There is no blame upon you nor upon them beyond these [periods], for they continually circulate among you - some of you, among others. Thus does Allāh make clear to you the verses [i.e., His ordinances]; and Allāh is Knowing and Wise.', 'Wahai orang-orang yang beriman, hendaklah hamba-hamba kamu dan orang-orang yang belum baligh dari kalangan kamu, meminta izin kepada kamu (sebelum masuk ke tempat kamu), dalam tiga masa; (iaitu) sebelum sembahyang subuh, dan ketika kamu membuka pakaian kerana kepanasan tengah hari, dan sesudah sembahyang Isyak; itulah tiga masa bagi kamu (yang biasanya terdedah aurat kamu padanya). Kamu dan mereka tidaklah bersalah kemudian daripada tiga masa yang tersebut, (kerana mereka) orang-orang yang selalu keluar masuk kepada kamu, dan kamu masing-masing sentiasa berhubung rapat antara satu dengan yang lain. Demikianlah Allah menerangkan kepada kamu ayat-ayatNya (yang menjelaskan hukum-hukumNya); dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 357, 18, 143, 308, FALSE, 0, NULL),
(24, 59, 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'وَإِذَا بَلَغَ الْأَطْفَالُ مِنكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِن قَبْلِهِمْ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ', NULL, 'And when the children among you reach puberty, let them ask permission [at all times] as those before them have done. Thus does Allāh make clear to you His verses; and Allāh is Knowing and Wise.', 'Dan apabila kanak-kanak dari kalangan kamu telah baligh, maka hendaklah mereka meminta izin sama seperti cara orang-orang (yang telah cukup umur) yang tersebut dahulu, meminta izin. Demikianlah Allah menerangkan kepada kamu ayat-ayatNya (yang menjelaskan hukum-hukumNya) dan (ingatlah) Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 358, 18, 143, 308, FALSE, 0, NULL),
(24, 60, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ وَاللَّهُ سَمِيعٌ عَلِيمٌ', NULL, 'And women of post-menstrual age who have no desire for marriage - there is no blame upon them for putting aside their outer garments [but] not displaying adornment. But to modestly refrain [from that] is better for them. And Allāh is Hearing and Knowing.', 'Dan mana-mana perempuan tua yang telah putus kedatangan haid, yang tidak mempunyai harapan berkahwin lagi maka tidak ada salahnya mereka menanggalkan pakaian luarnya, dengan tidak bertujuan mendedahkan perhiasan mereka; dalam pada itu perbuatan mereka menjaga kehormatannya (dengan tidak menanggalkan pakaian luarnya itu adalah) lebih baik bagi mereka; dan (ingatlah) Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 358, 18, 143, 308, FALSE, 0, NULL),
(24, 61, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةً طَيِّبَةً كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'لَّيْسَ عَلَى الْأَعْمَىٰ حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ وَلَا عَلَىٰ أَنفُسِكُمْ أَن تَأْكُلُوا مِن بُيُوتِكُمْ أَوْ بُيُوتِ آبَائِكُمْ أَوْ بُيُوتِ أُمَّهَاتِكُمْ أَوْ بُيُوتِ إِخْوَانِكُمْ أَوْ بُيُوتِ أَخَوَاتِكُمْ أَوْ بُيُوتِ أَعْمَامِكُمْ أَوْ بُيُوتِ عَمَّاتِكُمْ أَوْ بُيُوتِ أَخْوَالِكُمْ أَوْ بُيُوتِ خَالَاتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا عَلَىٰ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ اللَّهِ مُبَارَكَةً طَيِّبَةً كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَعْقِلُونَ', NULL, 'There is not upon the blind [any] constraint nor upon the lame constraint nor upon the ill constraint nor upon yourselves when you eat from your [own] houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your father''s brothers or the houses of your father''s sisters or the houses of your mother''s brothers or the houses of your mother''s sisters or [from houses] whose keys you possess or [from the house] of your friend. There is no blame upon you whether you eat together or separately. But when you enter houses, give greetings of peace upon each other - a greeting from Allāh, blessed and good. Thus does Allāh make clear to you the verses [of ordinance] that you may understand.', 'Tidak ada salahnya bagi orang buta, dan tidak ada salahnya bagi orang tempang, dan tidak ada salahnya bagi orang sakit (jika masing-masing tidak menjalankan sesuatu perintah disebabkan keuzurannya menghendaki ia berlaku demikian), dan juga tidak ada salah bagi kamu (termasuk orang-orang yang tersebut turut sama) makan di rumah kamu sendiri, atau di rumah bapa kamu, atau di rumah ibu kamu, atau di rumah saudara kamu yang lelaki, atau di rumah saudara kamu yang perempuan, atau di rumah bapa saudara kamu (sebelah bapa), atau di rumah emak saudara kamu (sebelah bapa), atau di rumah bapa saudara kamu (sebelah ibu), atau di rumah emak saudara kamu (sebelah ibu), atau di rumah yang kamu kuasai kuncinya, atau di rumah sahabat kamu; tidak juga menjadi salah bagi kamu, makan bersama-sama atau berasing-asing. Maka apabila kamu masuk ke mana-mana rumah, hendaklah kamu memberi salam kepada (sesiapa yang seperti) kamu dengan memohon kepada Allah cara hidup yang berkat lagi baik. Demikianlah Allah menerangkan ayat-ayat (yang menjelaskan hukum-hukumNya), supaya kamu memahaminya.', FALSE, NULL, NULL, 358, 18, 143, 308, FALSE, 0, NULL),
(24, 62, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ وَإِذَا كَانُوا مَعَهُ عَلَىٰ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا حَتَّىٰ يَسْتَأْذِنُوهُ إِنَّ الَّذِينَ يَسْتَأْذِنُونَكَ أُولَٰئِكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ فَإِذَا اسْتَأْذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ', NULL, 'The believers are only those who believe in Allāh and His Messenger and, when they are [meeting] with him for a matter of common interest, do not depart until they have asked his permission. Indeed, those who ask your permission, [O Muḥammad] - those are the ones who believe in Allāh and His Messenger. So when they ask your permission due to something of their affairs, then give permission to whom you will among them and ask forgiveness for them of Allāh. Indeed, Allāh is Forgiving and Merciful.', 'Sesungguhnya orang-orang yang sebenar-benarnya beriman ialah mereka yang beriman kepada Allah dan RasulNya, dan apabila mereka turut bersama-sama dengan Rasulullah dalam sesuatu perkara yang memerlukan perhimpunan ramai, tidaklah mereka meninggalkan majlis perhimpunan itu sebelum mereka meminta izin kepadanya. Sesungguhnya orang-orang yang meminta izin kepadamu (wahai Muhammad) itulah orang-orang yang beriman kepada Allah dan RasulNya. Maka apabila meminta izin kepadamu untuk pergi menjalankan sesuatu urusan mereka, maka izinkanlah bagi sesiapa yang engkau kehendaki di antara mereka, dan mintalah ampun kepada Allah untuk mereka; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 359, 18, 143, 309, FALSE, 0, NULL),
(24, 63, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 'لَّا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُم بَعْضًا قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Do not make [your] calling of the Messenger among yourselves as the call of one of you to another. Already Allāh knows those of you who slip away, concealed by others. So let those beware who dissent from his [i.e., the Prophet''s] order, lest fitnah strike them or a painful punishment.', 'Janganlah kamu jadikan seruan atau panggilan Rasulullah di antara kamu seperti seruan atau panggilan sesama kamu; sesungguhnya Allah mengetahui orang-orang di antara kamu yang menarik diri ke luar (dari majlis Nabi) secara berselindung dan bersembunyi. Oleh itu, hendaklah mereka yang mengingkari perintahnya, beringat serta berjaga-jaga jangan mereka ditimpa bala bencana, atau ditimpa azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 359, 18, 143, 309, FALSE, 0, NULL),
(24, 64, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'أَلَا إِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ قَدْ يَعْلَمُ مَا أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'Unquestionably, to Allāh belongs whatever is in the heavens and earth. Already He knows that upon which you [stand] and [knows] the Day when they will be returned to Him and He will inform them of what they have done. And Allāh is Knowing of all things.', 'Ketahuilah! Sesungguhnya Allah jualah yang menguasai segala yang ada di langit dan di bumi. Sesungguhnya Ia mengetahui keadaan yang kamu berada padanya (wahai umat manusia); dan pada hari umat manusia itu kembali kepadaNya, maka Ia akan menerangkan kepada mereka segala yang mereka kerjakan, kerana sesungguhnya Allah Maha Mengetahui akan tiap tiap sesuatu.', FALSE, NULL, NULL, 359, 18, 143, 309, FALSE, 0, NULL),
(25, 1, 'تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَـٰلَمِينَ نَذِيرًا', 'تبارك الذي نزل الفرقان على عبده ليكون للعالمين نذيرا', NULL, 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -', 'Maha berkat Tuhan yang menurunkan Al-Furqaan kepada hambaNya (Muhammad), untuk menjadi peringatan dan amaran bagi seluruh penduduk alam.', FALSE, NULL, NULL, 359, 18, 144, 310, FALSE, 9, NULL),
(25, 2, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا', 'الذي له ملك السماوات والارض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا', NULL, 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.', 'Tuhan yang menguasai pemerintahan langit dan bumi, dan yang tidak mempunyai anak, serta tidak mempunyai sebarang sekutu dalam pemerintahanNya; dan Dia lah yang menciptakan tiap-tiap sesuatu lalu menentukan keadaan makhluk-makhluk itu dengan ketentuan takdir yang sempurna.', FALSE, NULL, NULL, 359, 18, 144, 310, FALSE, 19, NULL),
(25, 3, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا', 'واتخذوا من دونه الهة لا يخلقون شيئا وهم يخلقون ولا يملكون لانفسهم ضرا ولا نفعا ولا يملكون موتا ولا حياة ولا نشورا', NULL, 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.', 'Dan mereka (yang kafir) mengambil benda-benda yang lain dari Allah sebagai tuhan-tuhan, yang tidak dapat mencipta sesuatupun, bahkan benda-benda itu diciptakan (oleh penyembah-penyembahnya dari bahan-bahan di bumi); dan benda-benda itu pula tidak berkuasa mendatangkan sesuatu bahaya atau sesuatu faedah untuk dirinya sendiri; dan tidak berkuasa mematikan atau menghidupkan, atau pun membangkitkan hidup semula makhluk-makhluk yang telah mati.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 22, NULL),
(25, 4, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ ۖ فَقَدْ جَآءُو ظُلْمًا وَزُورًا', 'وقال الذين كفروا ان هذا الا افك افتراه واعانه عليه قوم اخرون فقد جاءوا ظلما وزورا', NULL, 'And those who disbelieve say, "This [Qur’ān] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.', 'Dan orang-orang yang kafir itu berkata: “(Al-Quran) ini hanyalah satu perkara dusta yang direka-reka oleh Muhammad, dan ia dibantu membuatnya oleh kaum yang lain”. Maka (dengan kata-kata itu) sesungguhnya mereka telah mendatangkan satu tuduhan yang zalim dan dusta.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 16, NULL),
(25, 5, 'وَقَالُوٓا۟ أَسَـٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا', 'وقالوا اساطير الاولين اكتتبها فهي تملى عليه بكرة واصيلا', NULL, 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."', 'Dan mereka berkata lagi: “Al-Quran itu adalah cerita-cerita dongeng orang-orang dahulu kala, yang diminta oleh Muhammad supaya dituliskan, kemudian perkara yang ditulis itu dibacakan kepadanya pagi dan petang (untuk dihafaznya)”.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 9, NULL),
(25, 6, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا', 'قل انزله الذي يعلم السر في السماوات والارض انه كان غفورا رحيما', NULL, 'Say, [O Muḥammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."', 'Katakanlah (Wahai Muhammad): “Al-Quran itu diturunkan oleh Allah yang mengetahui segala rahsia di langit dan di bumi; sesungguhnya adalah Ia Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 12, NULL),
(25, 7, 'وَقَالُوا۟ مَالِ هَـٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ ۙ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'وقالوا مال هذا الرسول ياكل الطعام ويمشي في الاسواق لولا انزل اليه ملك فيكون معه نذيرا', NULL, 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?', 'Dan mereka pula berkata: “Mengapa Rasul ini makan minum dan berjalan di pasar-pasar (seperti manusia yang lain)? Sepatutnya diturunkan malaikat kepadanya, supaya malaikat itu turut memberi peringatan dan amaran bersama-sama dengannya (sebagai saksi yang membenarkannya).', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 16, NULL),
(25, 8, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا ۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'او يلقى اليه كنز او تكون له جنة ياكل منها وقال الظالمون ان تتبعون الا رجلا مسحورا', NULL, 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."', '“Atau diberikan perbendaharaan harta benda kepadanya, atau ia mempunyai sebuah kebun untuk ia makan hasilnya”. Dan orang-orang yang zalim itu berkata pula (kepada orang-orang yang beriman): “Sebenarnya kamu hanyalah menurut seorang yang tidak siuman”.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 17, NULL),
(25, 9, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَـٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا', NULL, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', 'Lihatlah (Wahai Muhammad) bagaimana mereka membuat untukmu berbagai misal perbandingan (yang bukan-bukan), dengan sebab itu sesatlah mereka, sehingga mereka tidak mendapat jalan petunjuk.', FALSE, NULL, NULL, 360, 18, 144, 310, FALSE, 9, NULL),
(25, 10, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 'تبارك الذي ان شاء جعل لك خيرا من ذلك جنات تجري من تحتها الانهار ويجعل لك قصورا', NULL, 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.', 'Maha Berkat Tuhan yang jika Ia kehendaki tentulah Ia akan mengadakan untukmu (di dunia ini) sesuatu yang lebih baik dari apa yang mereka katakan itu, iaitu syurga-syurga yang mengalir di bawahnya beberapa sungai, serta mengadakan untukmu istana-istana (yang tersergam indah).', FALSE, NULL, NULL, 360, 18, 144, 311, FALSE, 17, NULL),
(25, 11, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', 'بل كذبوا بالساعة واعتدنا لمن كذب بالساعة سعيرا', NULL, 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.', '(Mereka bukan sahaja mendustakanmu) bahkan mereka juga mendustakan hari kiamat; dan Kami telah sediakan bagi sesiapa yang mendustakan hari kiamat itu, api yang menjulang-julang.', FALSE, NULL, NULL, 360, 18, 144, 311, FALSE, 8, NULL),
(25, 12, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍ سَمِعُوا۟ لَهَا تَغَيُّظًا وَزَفِيرًا', 'اذا راتهم من مكان بعيد سمعوا لها تغيظا وزفيرا', NULL, 'When it [i.e., the Hellfire] sees them from a distant place, they will hear its fury and roaring.', 'Apabila neraka itu melihat mereka dari tempat yang jauh, kedengaranlah mereka suara marahnya yang menggelegak dan mengeluh.', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 9, NULL),
(25, 13, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًا', 'واذا القوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا', NULL, 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.', 'Dan apabila mereka dihumbankan ke tempat yang sempit di dalam neraka itu, dengan keadaan mereka dibelenggu, menjeritlah mereka di sana meminta sejenis kebinasaan (yang melepaskan dari azab itu).', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 9, NULL),
(25, 14, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًا وَٰحِدًا وَٱدْعُوا۟ ثُبُورًا كَثِيرًا', 'لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا', NULL, '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."', '(Lalu dikatakan kepada mereka): “Janganlah kamu menjerit-jerit meminta pada hari ini sejenis kebinasaan sahaja, tetapi mintalah kebinasaan sebanyak-banyaknya (kerana azab yang menunggu kamu di sini banyak jenisnya)”.', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 8, NULL),
(25, 15, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۚ كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا', 'قل اذلك خير ام جنة الخلد التي وعد المتقون كانت لهم جزاء ومصيرا', NULL, 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.', 'Bertanyalah (kepada mereka): “Adakah (azab seksa neraka) yang demikian itu lebih baik atau Syurga yang kekal, yang dijanjikan kepada orang-orang yang bertaqwa?” Syurga yang sedia diuntukkan bagi mereka sebagai balasan dan tempat kembali.', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 13, NULL),
(25, 16, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَـٰلِدِينَ ۚ كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسْـُٔولًا', 'لهم فيها ما يشاءون خالدين كان على ربك وعدا مسئولا', NULL, 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.', 'Mereka beroleh di dalam Syurga itu apa yang mereka kehendaki, mereka pula kekal di dalamnya. Balasan yang demikian adalah satu janji yang dijamin oleh Tuhanmu, lagi yang dipohonkan dan dituntut (dalam doa masing-masing).', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 10, NULL),
(25, 17, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَـٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', 'ويوم يحشرهم وما يعبدون من دون الله فيقول اانتم اضللتم عبادي هؤلاء ام هم ضلوا السبيل', NULL, 'And [mention] the Day He will gather them and that which they worship besides Allāh and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"', 'Dan (ingatkanlah) hari Tuhan menghimpunkan mereka (yang kafir) dan makhluk-makhluk yang mereka sembah yang lain dari Allah, lalu Ia bertanya (kepada makhluk-makhluk yang telah dipuja dan disembah itu): “Kamukah yang menyesatkan hamba-hambaKu itu atau mereka yang sesat jalan?”', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 16, NULL),
(25, 18, 'قَالُوا۟ سُبْحَـٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَـٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًا', 'قالوا سبحانك ما كان ينبغي لنا ان نتخذ من دونك من اولياء ولكن متعتهم واباءهم حتى نسوا الذكر وكانوا قوما بورا', NULL, 'They will say, "Exalted are You! It was not for us to take besides You any allies [i.e., protectors]. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."', 'Mereka menjawab: “Maha Suci Engkau (wahai Tuhan kami)! Sudah tentu tidak patut bagi kami mengambil sesiapa pun yang lain daripadaMu sebagai pelindung yang disembah (dan tidak patut juga kami menyeru orang menyembah kami); tetapi engkau (wahai Tuhan kami) telah melimpahkan kemewahan kepada mereka dan kepada datuk neneknya sehingga mereka lalai dan cuaikan ajaran ugamaMu, dan menjadilah mereka kaum yang binasa”.', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 21, NULL),
(25, 19, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا ۚ وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا', 'فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا', NULL, 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.', 'Maka (dikatakan pula kepada golongan itu): “Sesungguhnya mereka (yang kamu puja dan sembah) itu telah mendustakan dakwaan kamu (bahawa mereka yang menyesatkan kamu). Oleh itu, kamu semua tidak akan dapat menjauhkan azab seksa atau beroleh sebarang pertolongan”. Dan sesiapa yang berlaku zalim di antara kamu (wahai umat manusia, dengan kekufuran atau maksiat), Kami akan merasakannya azab seksa yang besar.', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 15, NULL),
(25, 20, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ ۗ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ ۗ وَكَانَ رَبُّكَ بَصِيرًا', 'وما ارسلنا قبلك من المرسلين الا انهم لياكلون الطعام ويمشون في الاسواق وجعلنا بعضكم لبعض فتنة اتصبرون وكان ربك بصيرا', NULL, 'And We did not send before you, [O Muḥammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.', 'Dan Kami tidak mengutus Rasul-rasul sebelummu (wahai Muhammad) melainkan orang-orang yang tentu makan minum dan berjalan di pasar-pasar, dan Kami jadikan sebahagian dari kamu sebagai ujian dan cubaan bagi sebahagian yang lain, supaya ternyata adakah kamu dapat bersabar (menghadapi ujian itu)? Dan (ingatlah) adalah Tuhanmu sentiasa Melihat (akan keadaan makhluk-makhlukNya).', FALSE, NULL, NULL, 361, 18, 144, 311, FALSE, 20, NULL),
(25, 21, 'وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا', 'وَقَالَ الَّذِينَ لَا يَرْجُونَ لِقَاءَنَا لَوْلَا أُنزِلَ عَلَيْنَا الْمَلَائِكَةُ أَوْ نَرَىٰ رَبَّنَا لَقَدِ اسْتَكْبَرُوا فِي أَنفُسِهِمْ وَعَتَوْا عُتُوًّا كَبِيرًا', NULL, 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.', 'Dan berkatalah pula orang-orang yang tidak percaya akan menemui Kami: “Mengapa tidak diturunkan malaikat kepada kita, atau kita dapat melihat Tuhan kita?” Demi sesungguhnya, mereka telah bersikap sombong angkuh dalam diri mereka sendiri, dan telah melampaui batas dengan cara yang sebesar-besarnya.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 22, 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', 'يَوْمَ يَرَوْنَ الْمَلَائِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', NULL, 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."', '(Ingatkanlah) hari mereka melihat malaikat, pada hari itu tiadalah sebarang berita gembira bagi orang-orang yang bersalah (bahkan sebaliknya), dan mereka akan berkata: “Semoga kita jauh - dijauhkan (dari sebarang keadaan yang buruk)”.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 23, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍ فَجَعَلْنَٰهُ هَبَآءً مَّنثُورًا', 'وَقَدِمْنَا إِلَىٰ مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَّنثُورًا', NULL, 'And We will approach [i.e., regard] what they have done of deeds and make them as dust dispersed.', 'Dan Kami tujukan perbicaraan kepada apa yang mereka telah kerjakan dari jenis amal (yang mereka pandang baik), lalu Kami jadikan dia terbuang sebagai debu yang berterbangan.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 24, 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', 'أَصْحَابُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', NULL, 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.', 'Ahli-ahli Syurga pada hari itu lebih baik tempat menetapnya, dan lebih elok tempat rehatnya.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 25, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', 'وَيَوْمَ تَشَقَّقُ السَّمَاءُ بِالْغَمَامِ وَنُزِّلَ الْمَلَائِكَةُ تَنزِيلًا', NULL, 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.', 'Dan (sebutkanlah perihal) hari segala langit pecah-belah (disertakan) dengan kumpulan awan (yang berisi malaikat), dan (pada hari yang tersebut) diturunkan malaikat itu dengan cara berpasuk-pasukan.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 26, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًا', 'الْمُلْكُ يَوْمَئِذٍ الْحَقُّ لِلرَّحْمَٰنِ وَكَانَ يَوْمًا عَلَى الْكَافِرِينَ عَسِيرًا', NULL, 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.', 'Kuasa pemerintahan yang sebenar-benarnya pada hari itu adalah tertentu bagi Allah Yang Maha melimpah rahmatNya, dan adalah ia satu masa yang amat sukar keadaannya kepada orang-orang kafir.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 27, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًا', 'وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا', NULL, 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.', 'Dan (ingatkanlah) perihal hari orang-orang yang zalim menggigit kedua-dua tangannya (marahkan dirinya sendiri) sambil berkata: “Alangkah baiknya kalau aku (di dunia dahulu) mengambil jalan yang benar bersama-sama Rasul?', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 28, 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', 'يَا وَيْلَتَىٰ لَيْتَنِي لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', NULL, 'Oh, woe to me! I wish I had not taken that one as a friend.', '“Wahai celakanya aku, alangkah baiknya kalau aku tidak mengambil si dia itu menjadi sahabat karib!', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 29, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًا', 'لَّقَدْ أَضَلَّنِي عَنِ الذِّكْرِ بَعْدَ إِذْ جَاءَنِي وَكَانَ الشَّيْطَانُ لِلْإِنسَانِ خَذُولًا', NULL, 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."', '“Sesungguhnya dia telah menyesatkan daku dari jalan peringatan (Al-Quran) setelah ia disampaikan kepadaku. Dan adalah Syaitan itu sentiasa mengecewakan manusia (yang menjadikan dia sahabat karibnya)”.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 30, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًا', 'وَقَالَ الرَّسُولُ يَا رَبِّ إِنَّ قَوْمِي اتَّخَذُوا هَٰذَا الْقُرْآنَ مَهْجُورًا', NULL, 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur’ān as [a thing] abandoned."', 'Dan berkatalah Rasul: “Wahai Tuhanku sesungguhnya kaumku telah menjadikan Al-Quran ini satu perlembagaan yang ditinggalkan, tidak dipakai”.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 31, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ ٱلْمُجْرِمِينَ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا مِّنَ الْمُجْرِمِينَ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', NULL, 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.', 'Dan demikianlah Kami jadikan bagi tiap-tiap Nabi, musuh dari kalangan orang-orang yang bersalah; dan cukuplah Tuhanmu (wahai Muhammad) menjadi Pemimpin (ke jalan mengalahkan mereka) serta menjadi Penolong (bagimu terhadap mereka).', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 32, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةً وَٰحِدَةً كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ وَرَتَّلْنَٰهُ تَرْتِيلًا', 'وَقَالَ الَّذِينَ كَفَرُوا لَوْلَا نُزِّلَ عَلَيْهِ الْقُرْآنُ جُمْلَةً وَاحِدَةً كَذَٰلِكَ لِنُثَبِّتَ بِهِ فُؤَادَكَ وَرَتَّلْنَاهُ تَرْتِيلًا', NULL, 'And those who disbelieve say, "Why was the Qur’ān not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.', 'Dan orang-orang yang kafir berkata: “Mengapa tidak diturunkan Al-Quran itu kepada Muhammad semuanya sekali (dengan sekaligus)?” Al-Quran diturunkan dengan cara (beransur-ansur) itu kerana Kami hendak menetapkan hatimu (wahai Muhammad) dengannya, dan Kami nyatakan bacaannya kepadamu dengan teratur satu persatu.', FALSE, NULL, NULL, 362, 19, 145, 312, FALSE, 0, NULL),
(25, 33, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيرًا', NULL, 'And they do not come to you with an example [i.e., argument] except that We bring you the truth and the best explanation.', 'Dan mereka tidak membawa kepadamu sesuatu kata-kata yang ganjil (untuk menentangmu) melainkan Kami bawakan kepadamu kebenaran dan penjelasan yang sebaik-baiknya (untuk menangkis segala yang mereka katakan itu).', FALSE, NULL, NULL, 363, 19, 145, 312, FALSE, 0, NULL),
(25, 34, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', 'الَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُولَٰئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', NULL, 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.', 'Orang-orang yang akan diseret beramai-ramai ke neraka Jahannam (dengan tertiarap) atas mukanya, merekalah orang-orang yang amat buruk keadaannya dan amat sesat jalannya.', FALSE, NULL, NULL, 363, 19, 145, 312, FALSE, 0, NULL),
(25, 35, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًا', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ وَجَعَلْنَا مَعَهُ أَخَاهُ هَارُونَ وَزِيرًا', NULL, 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.', 'Dan sesungguhnya Kami telah berikan Kitab Taurat kepada Nabi Musa, dan Kami lantik saudaranya Nabi Harun, sebagai menteri bersamanya.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 36, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًا', 'فَقُلْنَا اذْهَبَا إِلَى الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِنَا فَدَمَّرْنَاهُمْ تَدْمِيرًا', NULL, 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.', 'Lalu Kami perintahkan: “Pergilah kamu berdua kepada kaum yang mendustakan ayat-ayat keterangan Kami”; maka (kesudahannya) Kami binasakan kaum itu sehancur-hancurnya.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 37, 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةً وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًا', 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا الرُّسُلَ أَغْرَقْنَاهُمْ وَجَعَلْنَاهُمْ لِلنَّاسِ آيَةً وَأَعْتَدْنَا لِلظَّالِمِينَ عَذَابًا أَلِيمًا', NULL, 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.', 'Dan (demikian juga) kaum Nabi Nuh, ketika mereka mendustakan Rasul-rasul Kami, Kami tenggelamkan mereka, dan Kami jadikan mereka satu tanda (yang menjadi contoh) bagi umat manusia; dan Kami sediakan bagi sesiapa yang zalim; azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 38, 'وَعَادًا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًا', 'وَعَادًا وَثَمُودَ وَأَصْحَابَ الرَّسِّ وَقُرُونًا بَيْنَ ذَٰلِكَ كَثِيرًا', NULL, 'And [We destroyed] ʿAad and Thamūd and the companions of the well and many generations between them.', 'Dan (demikian juga Kami telah binasakan) Aad dan Thamud serta Ashaabur-Rassyi dan banyak lagi dalam zaman-zaman di antara masa yang tersebut itu.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 39, 'وَكُلًّا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', 'وَكُلًّا ضَرَبْنَا لَهُ الْأَمْثَالَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', NULL, 'And for each We presented examples [as warnings], and each We destroyed with [total] destruction.', 'Dan masing-masing, telah Kami berikan kepadanya contoh tauladan yang mendatangkan iktibar, dan masing-masing telah Kami hancurkan sehancur-hancurnya.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 40, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًا', 'وَلَقَدْ أَتَوْا عَلَى الْقَرْيَةِ الَّتِي أُمْطِرَتْ مَطَرَ السَّوْءِ أَفَلَمْ يَكُونُوا يَرَوْنَهَا بَلْ كَانُوا لَا يَرْجُونَ نُشُورًا', NULL, 'And they have already come upon the town which was showered with a rain of evil [i.e., stones]. So have they not seen it? But they are not expecting resurrection.', 'Dan demi sesungguhnya, mereka (yang menentangmu wahai Muhammad) telah melalui bandar yang telah dihujani (dengan) azab yang buruk, maka (mengapa mereka masih berdegil), tidakkah mereka selalu dapat menyaksikannya? (Mereka tidak fikirkan yang demikian itu satu balasan kufur) bahkan mereka adalah orang-orang yang tidak ingatkan adanya kebangkitan hidup semula (untuk menerima balasan).', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 41, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا', NULL, 'And when they see you, [O Muḥammad], they take you not except in ridicule, [saying], "Is this the one whom Allāh has sent as a messenger?', 'Dan apabila mereka melihatmu (wahai Muhammad), mereka hanyalah menjadikanmu ejek-ejekan (sambil mereka berkata): “Inikah orangnya yang diutus oleh Allah sebagai RasulNya?', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 42, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 'إِن كَادَ لَيُضِلُّنَا عَنْ آلِهَتِنَا لَوْلَا أَن صَبَرْنَا عَلَيْهَا وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ الْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', NULL, 'He almost would have misled us from our gods had we not been steadfast in [worship of] them." But they are going to know, when they see the punishment, who is farthest astray in [his] way.', '“Sebenarnya ia hampir-hampir dapat menyesatkan kami dari tuhan-tuhan kami, jika tidaklah kerana kami tetap teguh menyembahnya”. Dan mereka akan mengetahui kelak ketika mereka melihat azab seksa: siapakah yang sebenar-benarnya sesat jalannya.', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 43, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'أَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', NULL, 'Have you seen the one who takes as his god his own desire? Then would you be responsible for him?', 'Nampakkah (wahai Muhammad) keburukan keadaan orang yang menjadikan hawa nafsunya: tuhan yang dipuja lagi ditaati? Maka dapatkah engkau menjadi pengawas yang menjaganya jangan sesat?', FALSE, NULL, NULL, 363, 19, 145, 313, FALSE, 0, NULL),
(25, 44, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ سَبِيلًا', 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلًا', NULL, 'Or do you think that most of them hear or reason? They are not except like livestock. Rather, they are [even] more astray in [their] way.', 'Atau adakah engkau menyangka bahawa kebanyakan mereka mendengar atau memahami (apa yang engkau sampaikan kepada mereka)? Mereka hanyalah seperti binatang ternak, bahkan (bawaan) mereka lebih sesat lagi.', FALSE, NULL, NULL, 364, 19, 145, 313, FALSE, 0, NULL),
(25, 45, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًا', 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ الظِّلَّ وَلَوْ شَاءَ لَجَعَلَهُ سَاكِنًا ثُمَّ جَعَلْنَا الشَّمْسَ عَلَيْهِ دَلِيلًا', NULL, 'Have you not considered your Lord - how He extends the shadow, and if He willed, He could have made it stationary? Then We made the sun for it an indication.', 'Tidakkah engkau melihat kekuasaan Tuhanmu? - bagaimana Ia menjadikan bayang-bayang itu terbentang (luas kawasannya) dan jika Ia kehendaki tentulah Ia menjadikannya tetap (tidak bergerak dan tidak berubah)! Kemudian Kami jadikan matahari sebagai tanda yang menunjukkan perubahan bayang-bayang itu;', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 46, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًا يَسِيرًا', 'ثُمَّ قَبَضْنَاهُ إِلَيْنَا قَبْضًا يَسِيرًا', NULL, 'Then We [retract and] hold it with Us for a brief grasp.', 'Kemudian Kami tarik balik bayang-bayang itu kepada Kami, dengan beransur-ansur.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 47, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًا وَٱلنَّوْمَ سُبَاتًا وَجَعَلَ ٱلنَّهَارَ نُشُورًا', 'وَهُوَ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِبَاسًا وَالنَّوْمَ سُبَاتًا وَجَعَلَ النَّهَارَ نُشُورًا', NULL, 'And it is He who has made the night for you as clothing and sleep [a means for] rest and has made the day a resurrection.', 'Dan Dia lah Tuhan yang menjadikan malam untuk kamu sebagai pakaian, dan menjadikan tidur untuk berhenti rehat, serta menjadikan siang untuk keluar mencari rezeki.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 48, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا', 'وَهُوَ الَّذِي أَرْسَلَ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ وَأَنزَلْنَا مِنَ السَّمَاءِ مَاءً طَهُورًا', NULL, 'And it is He who sends the winds as good tidings before His mercy [i.e., rainfall], and We send down from the sky pure water', 'Dan Dia lah Tuhan yang menghantarkan angin sebagai berita gembira sebelum kedatangan rahmatNya, dan Kami menurunkan dari langit: air yang bersih suci,', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 49, 'لِّنُحْـِۧىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًا وَأَنَاسِىَّ كَثِيرًا', 'لِّنُحْيِيَ بِهِ بَلْدَةً مَّيْتًا وَنُسْقِيَهُ مِمَّا خَلَقْنَا أَنْعَامًا وَأَنَاسِيَّ كَثِيرًا', NULL, 'That We may bring to life thereby a dead land and give it as drink to those We created of numerous livestock and men.', 'Untuk Kami hidupkan dengan air itu bumi yang mati, serta memberi minum air itu kepada sebahagian dari makhluk-makhluk Kami, khasnya binatang ternak yang banyak dan manusia yang ramai.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 50, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'وَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ لِيَذَّكَّرُوا فَأَبَىٰ أَكْثَرُ النَّاسِ إِلَّا كُفُورًا', NULL, 'And We have certainly distributed it among them that they might be reminded, but most of the people refuse except disbelief.', 'Dan demi sesungguhnya! Kami telah berulang-ulang kali menyebarkan hujjah-hujjah di antara manusia melalui Al-Quran supaya mereka berfikir (mengenalku serta bersyukur); dalam pada itu kebanyakan manusia tidak mahu melainkan berlaku kufur.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا', 'وَلَوْ شِئْنَا لَبَعَثْنَا فِي كُلِّ قَرْيَةٍ نَّذِيرًا', NULL, 'And if We had willed, We could have sent into every city a warner.', 'Dan kalau Kami kehendaki, tentulah Kami utuskan dalam tiap-tiap negeri, seorang Rasul pemberi amaran.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 52, 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا', 'فَلَا تُطِعِ الْكَافِرِينَ وَجَاهِدْهُم بِهِ جِهَادًا كَبِيرًا', NULL, 'So do not obey the disbelievers, and strive against them with it [i.e., the Qur’ān] a great striving.', 'Oleh itu, janganlah engkau (Wahai Muhammad) menurut kehendak orang-orang kafir, dan berjuanglah dengan hujjah-hujjah Al-Quran menghadapi mereka dengan perjuangan yang besar dan bersungguh-sungguh.', FALSE, NULL, NULL, 364, 19, 145, 314, FALSE, 0, NULL),
(25, 53, 'وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', 'وَهُوَ الَّذِي مَرَجَ الْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', NULL, 'And it is He who has released [simultaneously] the two seas [i.e., bodies of water], one fresh and sweet and one salty and bitter, and He placed between them a barrier and prohibiting partition.', 'Dan Dia lah Tuhan yang telah mengalirkan dua laut berdampingan, yang satu tawar lagi memuaskan dahaga, dan yang satu lagi masin lagi pahit; serta Ia menjadikan antara kedua-dua laut itu sempadan dan sekatan yang menyekat percampuran keduanya.', FALSE, NULL, NULL, 364, 19, 146, 314, FALSE, 0, NULL),
(25, 54, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا وَكَانَ رَبُّكَ قَدِيرًا', 'وَهُوَ الَّذِي خَلَقَ مِنَ الْمَاءِ بَشَرًا فَجَعَلَهُ نَسَبًا وَصِهْرًا وَكَانَ رَبُّكَ قَدِيرًا', NULL, 'And it is He who has created from water [i.e., semen] a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation].', 'Dan Dia lah Tuhan yang menciptakan manusia dari air, lalu dijadikannya (mempunyai) titisan baka dan penalian keluarga (persemendaan); dan sememangnya tuhanmu berkuasa (menciptakan apa jua yang dikehendakiNya).', FALSE, NULL, NULL, 364, 19, 146, 314, FALSE, 0, NULL),
(25, 55, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا', 'وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ وَكَانَ الْكَافِرُ عَلَىٰ رَبِّهِ ظَهِيرًا', NULL, 'But they worship rather than Allāh that which does not benefit them or harm them, and the disbeliever is ever, against his Lord, an assistant [to Satan].', 'Dan mereka (yang musyrik) menyembah benda-benda yang lain dari Allah, yang tidak memberi manfaat kepada mereka (yang menyembahnya) dan tidak pula mendatangkan mudarat kepada mereka (yang tidak menyembahnya); dan orang yang kafir selalu menjadi pembantu (bagi golongannya yang kafir) untuk menderhaka kepada tuhannya.', FALSE, NULL, NULL, 364, 19, 146, 314, FALSE, 0, NULL),
(25, 56, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', 'وَمَا أَرْسَلْنَاكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', NULL, 'And We have not sent you, [O Muḥammad], except as a bringer of good tidings and a warner.', 'Dan tidaklah Kami mengutusmu (wahai Muhammad) melainkan sebagai pembawa berita gembira (kepada orang-orang yang beriman) dan pemberi amaran (kepada orang-orang yang ingkar).', FALSE, NULL, NULL, 365, 19, 146, 314, FALSE, 0, NULL),
(25, 57, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَاءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِ سَبِيلًا', NULL, 'Say, "I do not ask of you for it any payment - only that whoever wills might take to his Lord a way."', 'Katakanlah: “Aku tidak meminta kepada kamu sebarang balasan bagi apa yang aku sampaikan kepada kamu, selain daripada berimannya seseorang yang mahu mendapatkan jalan sampainya kepada keredaan Allah”.', FALSE, NULL, NULL, 365, 19, 146, 314, FALSE, 0, NULL),
(25, 58, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِ وَكَفَىٰ بِهِ بِذُنُوبِ عِبَادِهِ خَبِيرًا', NULL, 'And rely upon the Ever-Living who does not die, and exalt [Allāh] with His praise. And sufficient is He to be, with the sins of His servants, [fully] Aware -', 'Dan berserahlah engkau kepada Allah Tuhan Yang Hidup, yang tidak mati; serta bertasbihlah dengan memujiNya; dan cukuplah Ia mengetahui secara mendalam akan dosa-dosa hambaNya;', FALSE, NULL, NULL, 365, 19, 146, 314, FALSE, 0, NULL),
(25, 59, 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًا', 'الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ الرَّحْمَٰنُ فَاسْأَلْ بِهِ خَبِيرًا', NULL, 'He who created the heavens and the earth and what is between them in six days and then established Himself above the Throne - the Most Merciful, so ask about Him one well informed [i.e., the Prophet (ﷺ)].', 'Tuhan yang menciptakan langit dan bumi serta segala yang ada di antara keduanya, dalam enam masa, kemudian Ia bersemayam di atas Arasy, Ialah Ar-Rahman (Tuhan Yang Maha Pemurah); maka bertanyalah akan hal itu kepada Yang Mengetahuinya.', FALSE, NULL, NULL, 365, 19, 146, 314, FALSE, 0, NULL),
(25, 60, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا', 'وَإِذَا قِيلَ لَهُمُ اسْجُدُوا لِلرَّحْمَٰنِ قَالُوا وَمَا الرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا', NULL, 'And when it is said to them, "Prostrate to the Most Merciful," they say, "And what is the Most Merciful? Should we prostrate to that which you order us?" And it increases them in aversion.', 'Dan apabila dikatakan kepada mereka (yang musyrik itu): “Sujudlah kamu kepada Ar-Rahman (Tuhan Yang Maha Pemurah)!” Mereka bertanya: “Dan siapakah Ar-Rahman itu? Patutkah kami sujud kepada apa sahaja yang engkau perintahkan kami?” Dan perintah yang demikian, menjadikan mereka bertambah liar ingkar.', FALSE, NULL, NULL, 365, 19, 146, 314, TRUE, 0, NULL),
(25, 61, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا', 'تَبَارَكَ الَّذِي جَعَلَ فِي السَّمَاءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَاجًا وَقَمَرًا مُّنِيرًا', NULL, 'Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon.', 'Maha Berkat Tuhan yang telah menjadikan di langit, tempat-tempat peredaran bintang, dan menjadikan padanya matahari serta bulan yang menerangi.', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 62, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', 'وَهُوَ الَّذِي جَعَلَ اللَّيْلَ وَالنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', NULL, 'And it is He who has made the night and the day in succession for whoever desires to remember or desires gratitude.', 'Dan Dia lah yang menjadikan malam dan siang silih berganti untuk sesiapa yang mahu beringat (memikirkan kebesaranNya), atau mahu bersyukur (akan nikmat-nikmatNya itu).', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 63, 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًا', 'وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا', NULL, 'And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace,', 'Dan hamba-hamba (Allah) Ar-Rahman (yang diredhaiNya), ialah mereka yang berjalan di bumi dengan sopan santun, dan apabila orang-orang yang berkelakuan kurang adab, hadapkan kata-kata kepada mereka, mereka menjawab dengan perkataan yang selamat dari perkara yang tidak diingini;', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 64, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَٰمًا', 'وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا', NULL, 'And those who spend [part of] the night to their Lord prostrating and standing [in prayer]', 'Dan mereka (yang diredhai Allah itu ialah) yang tekun mengerjakan ibadat kepada Tuhan mereka pada malam hari dengan sujud dan berdiri,', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 65, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'وَالَّذِينَ يَقُولُونَ رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا', NULL, 'And those who say, "Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;', 'Dan juga mereka yang berdoa dengan berkata: Wahai Tuhan kami, sisihkanlah azab neraka Jahannam dari kami, sesungguhnya azab seksanya itu adalah mengerikan', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 66, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا', 'إِنَّهَا سَاءَتْ مُسْتَقَرًّا وَمُقَامًا', NULL, 'Indeed, it is evil as a settlement and residence."', '“Sesungguhnya neraka Jahannam itu tempat penetapan dan tempat tinggal yang amat buruk”;', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 67, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', 'وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', NULL, 'And [they are] those who, when they spend, do so not excessively or sparingly but are ever, between that, [justly] moderate', 'Dan juga mereka (yang diredhai Allah itu ialah) yang apabila membelanjakan hartanya, tiadalah melampaui batas dan tiada bakhil kedekut; dan (sebaliknya) perbelanjaan mereka adalah betul sederhana di antara kedua-dua cara (boros dan bakhil) itu.', FALSE, NULL, NULL, 365, 19, 146, 315, FALSE, 0, NULL),
(25, 68, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', 'وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَٰهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', NULL, 'And those who do not invoke with Allāh another deity or kill the soul which Allāh has forbidden [to be killed], except by right, and do not commit unlawful sexual intercourse. And whoever should do that will meet a penalty.', 'Dan juga mereka yang tidak menyembah sesuatu yang lain bersama-sama Allah, dan tidak membunuh jiwa yang diharamkan Allah membunuhnya, kecuali dengan jalan yang hak (yang dibenarkan oleh syarak), dan tidak pula berzina; dan sesiapa melakukan yang demikian, akan mendapat balasan dosanya;', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 69, 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 'يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا', NULL, 'Multiplied for him is the punishment on the Day of Resurrection, and he will abide therein humiliated -', 'Akan digandakan baginya azab seksa pada hari kiamat, dan ia pula akan kekal di dalam azab itu dengan menerima kehinaan, -', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَٰلِحًا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'إِلَّا مَن تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَٰئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'Except for those who repent, believe and do righteous work. For them Allāh will replace their evil deeds with good. And ever is Allāh Forgiving and Merciful.', 'Kecuali orang yang bertaubat dan beriman serta mengerjakan amal yang baik, maka orang-orang itu, Allah akan menggantikan (pada tempat) kejahatan mereka dengan kebaikan; dan adalah Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 71, 'وَمَن تَابَ وَعَمِلَ صَٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًا', 'وَمَن تَابَ وَعَمِلَ صَالِحًا فَإِنَّهُ يَتُوبُ إِلَى اللَّهِ مَتَابًا', NULL, 'And he who repents and does righteousness does indeed turn to Allāh with [accepted] repentance.', 'Dan sesiapa yang bertaubat serta beramal soleh, maka sesungguhnya (dengan itu) ia bertaubat kepada Tuhannya dengan sebenar-benar taubat;', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 72, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًا', 'وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا', NULL, 'And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity.', 'Dan mereka (yang diredhai Allah itu ialah orang-orang) yang tidak menghadiri tempat-tempat melakukan perkara-perkara yang dilarang, dan apabila mereka bertembung dengan sesuatu yang sia-sia, mereka melaluinya dengan cara membersihkan diri daripadanya.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 73, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّا وَعُمْيَانًا', 'وَالَّذِينَ إِذَا ذُكِّرُوا بِآيَاتِ رَبِّهِمْ لَمْ يَخِرُّوا عَلَيْهَا صُمًّا وَعُمْيَانًا', NULL, 'And those who, when reminded of the verses of their Lord, do not fall upon them deaf and blind.', 'Dan juga mereka (yang diredhai Allah itu ialah orang-orang) yang apabila diberi peringatan dengan ayat-ayat keterangan Tuhan mereka, tidaklah mereka tunduk mendengarnya secara orang-orang yang pekak dan buta.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 74, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', NULL, 'And those who say, "Our Lord, grant us from among our wives and offspring comfort to our eyes and make us a leader [i.e., example] for the righteous."', 'Dan juga mereka (yang diredhai Allah itu ialah orang-orang) yang berdoa dengan berkata: “Wahai Tuhan kami, berilah kami beroleh dari isteri-isteri dan zuriat keturunan kami: perkara-perkara yang menyukakan hati melihatnya, dan jadikanlah kami imam ikutan bagi orang-orang yang (mahu) bertaqwa.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 75, 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَٰمًا', 'أُولَٰئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَامًا', NULL, 'Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace,', 'Mereka itu semuanya akan dibalas dengan mendapat tempat yang tinggi di Syurga disebabkan kesabaran mereka, dan mereka pula akan menerima penghormatan dan ucapan selamat di dalamnya,', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 76, 'خَٰلِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', 'خَالِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', NULL, 'Abiding eternally therein. Good is the settlement and residence.', 'Mereka kekal di dalam Syurga itu; amatlah eloknya Syurga menjadi tempat penetapan dan tempat tinggal.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(25, 77, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', 'قُلْ مَا يَعْبَأُ بِكُمْ رَبِّي لَوْلَا دُعَاؤُكُمْ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًا', NULL, 'Say, "What would my Lord care for you if not for your supplication?" For you [disbelievers] have denied, so it [i.e., your denial] is going to be adherent.', 'Katakanlah (wahai Muhammad kepada golongan yang ingkar): “Tuhanku tidak akan menghargai kamu kalau tidak adanya doa ibadat kamu kepadaNya; (apabila kamu telah mengetahui bahawa Tuhanku telah menetapkan tidak menghargai seseorang pun melainkan kerana doa ibadatnya) maka sesungguhnya kamu telahpun menyalahi (ketetapan Tuhanku itu); dengan yang demikian, sudah tentu balasan azab (disebabkan kamu menyalahi itu) akan menimpa kamu”.', FALSE, NULL, NULL, 366, 19, 146, 315, FALSE, 0, NULL),
(26, 1, 'طسٓمٓ', 'طسم', NULL, 'Ṭā, Seen, Meem.', 'Taa, Siin, Miim.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 1, NULL),
(26, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', 'تلك ايات الكتاب المبين', NULL, 'These are the verses of the clear Book.', 'Ini ialah ayat-ayat Kitab (Al-Quran) yang jelas nyata.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 4, NULL),
(26, 3, 'لَعَلَّكَ بَـٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', 'لعلك باخع نفسك الا يكونوا مؤمنين', NULL, 'Perhaps, [O Muḥammad], you would kill yourself with grief that they will not be believers.', 'Jangan-jangan pula engkau (wahai Muhammad), membinasakan dirimu dengan menanggung dukacita, kerana mereka tidak menjadi orang-orang yang beriman.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 6, NULL),
(26, 4, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَـٰقُهُمْ لَهَا خَـٰضِعِينَ', 'ان نشا ننزل عليهم من السماء اية فظلت اعناقهم لها خاضعين', NULL, 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.', 'Kalau Kami mahu, tentulah Kami akan turunkan kepada mereka satu mukjizat dari langit, yang menjadikan mereka tunduk kepadanya.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 11, NULL),
(26, 5, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَـٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', 'وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين', NULL, 'And no mention [i.e., revelation] comes to them anew from the Most Merciful except that they turn away from it.', 'Dan tidak datang kepada mereka peringatan serta pengajaran yang baharu dari (Allah) Ar-Rahman, melainkan mereka tetap berpaling mengingkarinya.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 11, NULL),
(26, 6, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فقد كذبوا فسياتيهم انباء ما كانوا به يستهزئون', NULL, 'For they have already denied, but there will come to them the news of that which they used to ridicule.', 'Oleh kerana mereka telah mendustakan Al-Quran, maka sudah tentu akan datang kepada mereka berita-berita (azab) mengenai perkara yang mereka ejek-ejek itu.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 8, NULL),
(26, 7, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', 'اولم يروا الى الارض كم انبتنا فيها من كل زوج كريم', NULL, 'Did they not look at the earth - how much We have produced therein from every noble kind?', 'Masihkah mereka berdegil dan tidak memperhatikan bumi, berapa banyak kami tumbuhkan padanya dari berbagai jenis tanaman yang memberi banyak manfaat?', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 11, NULL),
(26, 8, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'ان في ذلك لاية وما كان اكثرهم مؤمنين', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya pada yang demikian itu terdapat satu tanda (yang membuktikan kekuasaan dan rahmat pengurniaan Allah); dan (dalam pada itu), kebanyakan mereka tidak juga beriman.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 8, NULL),
(26, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وان ربك لهو العزيز الرحيم', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad) Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 367, 19, 147, 316, FALSE, 5, NULL),
(26, 10, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 'واذ نادى ربك موسى ان ائت القوم الظالمين', NULL, 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -', 'Dan (ingatkanlah peristiwa) ketika Tuhanmu menyeru Nabi Musa: “Hendaklah engkau mendatangi kaum yang zalim, -', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 8, NULL),
(26, 11, 'قَوْمَ فِرْعَوْنَ ۚ أَلَا يَتَّقُونَ', 'قوم فرعون الا يتقون', NULL, 'The people of Pharaoh. Will they not fear Allāh?"', '“Iaitu kaum Firaun; tidakkah mereka mahu mengawal diri dari kemurkaanKu?”', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 4, NULL),
(26, 12, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'قال رب اني اخاف ان يكذبون', NULL, 'He said, "My Lord, indeed I fear that they will deny me', 'Nabi Musa merayu dengan berkata: “Wahai Tuhanku, sesungguhnya aku takut bahawa mereka akan mendustakan daku.', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 6, NULL),
(26, 13, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَـٰرُونَ', 'ويضيق صدري ولا ينطلق لساني فارسل الى هارون', NULL, 'And that my breast will tighten and my tongue will not be fluent, so send for Aaron.', '“Dan akan sempit pula dadaku serta tidak lancar lidahku; oleh itu utuskanlah perintahMu kepada Harun (supaya ia membantuku).', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 8, NULL),
(26, 14, 'وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ', 'ولهم علي ذنب فاخاف ان يقتلون', NULL, 'And they have upon me a [claim due to] sin, so I fear that they will kill me."', '“Dan lagi mereka ada mengemukakan satu tuduhan jenayah terhadapku; oleh itu aku takut mereka akan membunuhku”.', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 6, NULL),
(26, 15, 'قَالَ كَلَّا ۖ فَٱذْهَبَا بِـَٔايَـٰتِنَآ ۖ إِنَّا مَعَكُم مُّسْتَمِعُونَ', 'قال كلا فاذهبا باياتنا انا معكم مستمعون', NULL, '[Allāh] said, "No. Go both of you with Our signs; indeed, We are with you, listening.', 'Allah berfirman: “Jangan! Jangan fikir (akan berlaku apa yang engkau bimbangkan itu)! Oleh itu pergilah kamu berdua membawa mukjizat-mukjizat Kami (yang membuktikan kebenaran kamu); sesungguhnya Kami ada bersama-sama kamu: mendengar.', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 7, NULL),
(26, 16, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَـٰلَمِينَ', 'فاتيا فرعون فقولا انا رسول رب العالمين', NULL, 'Go to Pharaoh and say, ''We are the messengers of the Lord of the worlds,', '“Maka pergilah kamu kepada Firaun, kemudian katakanlah kepadanya: sesungguhnya kami adalah utusan Tuhan sekalian alam.', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 7, NULL),
(26, 17, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 'ان ارسل معنا بني اسرائيل', NULL, '[Commanded to say], "Send with us the Children of Israel."''"', '“Menyuruhmu membebaskan kaum Bani Israil mengikut kami”.', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 5, NULL),
(26, 18, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', 'قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين', NULL, '[Pharaoh] said, "Did we not raise you among us as a child, and you remained among us for years of your life?', 'Firaun menjawab: “Bukankah kami telah memeliharamu dalam kalangan kami semasa engkau kanak-kanak yang baharu lahir, serta engkau telah tinggal dalam kalangan kami beberapa tahun dari umurmu?', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 10, NULL),
(26, 19, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَـٰفِرِينَ', 'وفعلت فعلتك التي فعلت وانت من الكافرين', NULL, 'And [then] you did your deed which you did, and you were of the ungrateful."', '“Dan (bukankah) engkau telah melakukan satu perbuatan (jenayah) yang telah engkau lakukan dan (dengan itu) engkau dari orang-orang yang tidak mengenang budi?”', FALSE, NULL, NULL, 367, 19, 147, 317, FALSE, 7, NULL),
(26, 20, 'قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'قال فعلتها اذا وانا من الضالين', NULL, '[Moses] said, "I did it, then, while I was of those astray [i.e., ignorant].', 'Nabi Musa berkata: “Aku melakukan perbuatan yang demikian sedang aku ketika itu dari orang-orang yang belum mendapat petunjuk.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 6, NULL),
(26, 21, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِي رَبِّي حُكْمًا وَجَعَلَنِي مِنَ الْمُرْسَلِينَ', NULL, 'So I fled from you when I feared you. Then my Lord granted me judgement [i.e., wisdom and prophethood] and appointed me [as one] of the messengers.', '“Lalu aku melarikan diri dari kamu, ketika aku merasa takut kepada kamu; kemudian Tuhanku mengurniakan daku ilmu pengetahuan ugama, dan menjadikan daku seorang RasulNya.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 22, 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ أَنْ عَبَّدتَّ بَنِي إِسْرَائِيلَ', NULL, 'And is this a favor of which you remind me - that you have enslaved the Children of Israel?"', '“Dan budimu memeliharaku yang engkau bangkit-bangkitkan itu adalah kerana engkau telah bertindak memperhambakan kaum Bani Israil.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 23, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', 'قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَالَمِينَ', NULL, 'Said Pharaoh, "And what is the Lord of the worlds?"', 'Firaun berkata (dengan sombongnya): “Dan apa dia Tuhan sekalian alam itu?”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 24, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ', 'قَالَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ', NULL, '[Moses] said, "The Lord of the heavens and earth and that between them, if you should be convinced."', 'Nabi Musa menjawab. “Dia lah yang memiliki dan mentadbirkan langit dan bumi serta segala yang ada di antara keduanya, - kalaulah kamu mahu mendapat keyakinan dengan berdalil maka inilah jalannya”.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 25, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 'قَالَ لِمَنْ حَوْلَهُ أَلَا تَسْتَمِعُونَ', NULL, '[Pharaoh] said to those around him, "Do you not hear?"', 'Firaun berkata kepada orang-orang yang ada di sekelilingnya: “Tidakkah kamu dengar (apa yang dikatakan olehnya)?”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 26, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'قَالَ رَبُّكُمْ وَرَبُّ آبَائِكُمُ الْأَوَّلِينَ', NULL, '[Moses] said, "Your Lord and the Lord of your first forefathers."', 'Nabi Musa menegaskan lagi: “Dia lah Tuhan yang memiliki dan memelihara kamu dan Tuhan datuk nenek kamu yang telah lalu.”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 27, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ', 'قَالَ إِنَّ رَسُولَكُمُ الَّذِي أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ', NULL, '[Pharaoh] said, "Indeed, your ''messenger'' who has been sent to you is mad."', 'Firaun berkata (kepada orang-orangnya): “Sebenarnya Rasul yang diutuskan kepada kamu ini, sungguh gila?”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 28, 'قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ إِن كُنتُمْ تَعْقِلُونَ', 'قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَا إِن كُنتُمْ تَعْقِلُونَ', NULL, '[Moses] said, "Lord of the east and the west and that between them, if you were to reason."', 'Nabi Musa (menerangkan lagi tentang keesaan Allah dan kekuasaanNya dengan) berkata: “Dia lah yang memiliki dan menguasai timur dan barat serta segala yang ada di antara keduanya; kalau kamu orang-orang yang berakal tentulah memahamiNya!”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 29, 'قَالَ لَئِنِ ٱتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ', 'قَالَ لَئِنِ اتَّخَذْتَ إِلَٰهًا غَيْرِي لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ', NULL, '[Pharaoh] said, "If you take a god other than me, I will surely place you among those imprisoned."', 'Firaun berkata: “Demi sesungguhnya! Jika engkau menyembah Tuhan yang lain daripadaku, sudah tentu aku akan menjadikan engkau dari orang-orang yang dipenjarakan”.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 30, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍ مُّبِينٍ', 'قَالَ أَوَلَوْ جِئْتُكَ بِشَيْءٍ مُّبِينٍ', NULL, '[Moses] said, "Even if I brought you something [i.e., proof] manifest?"', 'Nabi Musa menjawab: “Adakah (engkau akan memenjarakan daku juga) walau pun aku membawa kepadamu sesuatu bukti yang jelas nyata?”', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 31, 'قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قَالَ فَأْتِ بِهِ إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, '[Pharaoh] said, "Then bring it, if you should be of the truthful."', 'Firaun berkata: “Kalau demikian, bawalah bukti itu jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 32, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُّبِينٌ', NULL, 'So [Moses] threw his staff, and suddenly it was a serpent manifest.', 'Nabi Musa pun mencampakkan tongkatnya, maka tiba-tiba tongkatnya itu menjadi seekor ular yang jelas nyata.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 33, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَاءُ لِلنَّاظِرِينَ', NULL, 'And he drew out his hand; thereupon it was white for the observers.', 'Dan ia mengeluarkan tangannya, maka tiba-tiba tangannya menjadi putih (bersinar-sinar) bagi orang-orang yang melihatnya.', FALSE, NULL, NULL, 368, 19, 147, 317, FALSE, 0, NULL),
(26, 34, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', 'قَالَ لِلْمَلَإِ حَوْلَهُ إِنَّ هَٰذَا لَسَاحِرٌ عَلِيمٌ', NULL, '[Pharaoh] said to the eminent ones around him, "Indeed, this is a learned magician.', 'Firaun berkata kepada ketua-ketua kaum yang ada dikelilingnya: “Sesungguhnya orang ini (Musa) ialah seorang ahli sihir yang mahir.', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 35, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ', 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِ فَمَاذَا تَأْمُرُونَ', NULL, 'He wants to drive you out of your land by his magic, so what do you advise?"', '“Ia bertujuan hendak mengeluarkan kamu dari negeri kamu dengan sihirnya, maka apa yang kamu syorkan?”', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 36, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'قَالُوا أَرْجِهْ وَأَخَاهُ وَابْعَثْ فِي الْمَدَائِنِ حَاشِرِينَ', NULL, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', 'Mereka berkata: “Tangguhkanlah dahulu (sebarang tindakan) terhadapnya dan terhadap saudaranya, serta hantarkanlah ke bandar-bandar (negeri Mesir) orang-orang yang mengumpulkan (ahli-ahli sihir),', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 37, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ', 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ', NULL, 'Who will bring you every learned, skilled magician."', '“Supaya mereka membawa kepadamu segala ahli sihir yang mahir”.', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 38, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوْمٍ مَّعْلُومٍ', 'فَجُمِعَ السَّحَرَةُ لِمِيقَاتِ يَوْمٍ مَّعْلُومٍ', NULL, 'So the magicians were assembled for the appointment of a well-known day.', 'Lalu dikumpulkanlah ahli-ahli sihir itu pada satu masa yang ditentukan, pada hari (perayaan) yang termaklum.', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 39, 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', NULL, 'And it was said to the people, "Will you congregate', 'Dan dikatakan kepada orang ramai: “Berkumpulah kamu semuanya;.', FALSE, NULL, NULL, 368, 19, 147, 318, FALSE, 0, NULL),
(26, 40, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'لَعَلَّنَا نَتَّبِعُ السَّحَرَةَ إِن كَانُوا هُمُ الْغَالِبِينَ', NULL, 'That we might follow the magicians if they are the predominant?"', '“Semoga kita (tetap) mengikut (ugama) ahli-ahli sihir itu kiranya merekalah orang-orang yang menang”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 41, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'فَلَمَّا جَاءَ السَّحَرَةُ قَالُوا لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ الْغَالِبِينَ', NULL, 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"', 'Maka ketika ahli-ahli sihir itu datang, berkatalah mereka kepada Firaun: “Benarkah kami akan beroleh upah, kiranya kamilah orang-orang yang menang?”', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 42, 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ ٱلْمُقَرَّبِينَ', 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ الْمُقَرَّبِينَ', NULL, 'He said, "Yes, and indeed, you will then be of those near [to me]."', 'Firaun menjawab: “Benar, (kamu akan mendapatnya) dan sesungguhnya kamu dengan itu akan menjadi dari orang-orang yang dekat kepadaku”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 43, 'قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'قَالَ لَهُم مُّوسَىٰ أَلْقُوا مَا أَنتُم مُّلْقُونَ', NULL, 'Moses said to them, "Throw whatever you will throw."', 'Nabi Musa berkata kepada mereka: “Campakkanlah dahulu apa yang kamu hendak campakkan”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 44, 'فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَٰلِبُونَ', 'فَأَلْقَوْا حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ الْغَالِبُونَ', NULL, 'So they threw their ropes and their staffs and said, "By the might of Pharaoh, indeed it is we who are predominant."', 'Lalu mereka mencampakkan tali-tali dan tongkat-tongkat mereka sambil berkata: “Demi kekuasaan Firaun, sesungguhnya sudah tetap kamilah orang-orang yang akan menang”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 45, 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ', NULL, 'Then Moses threw his staff, and at once it devoured what they falsified.', 'Kemudian Nabi Musa pula mencampakkan tongkatnya, tiba-tiba tongkatnya itu menelan apa yang mereka pura-pura adakan (dengan sihir mereka).', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 46, 'فَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'فَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ', NULL, 'So the magicians fell down in prostration [to Allāh].', 'Maka (kemenangan Nabi Musa menjadikan) ahli-ahli sihir itu segera merebahkan diri: sujud,', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 47, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'قَالُوا آمَنَّا بِرَبِّ الْعَالَمِينَ', NULL, 'They said, "We have believed in the Lord of the worlds,', 'Sambil berkata: “Kami beriman kepada Tuhan sekalian alam,', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 48, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'رَبِّ مُوسَىٰ وَهَارُونَ', NULL, 'The Lord of Moses and Aaron."', '“Tuhan Nabi Musa dan Nabi Harun”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 49, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'قَالَ آمَنتُمْ لَهُ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', NULL, '[Pharaoh] said, "You believed him [i.e., Moses] before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."', 'Firaun berkata: “Patutkah kamu beriman kepadanya sebelum aku izinkan kamu? Sesungguhnya dia lah (Musa) ketua kamu yang mengajar kamu ilmu sihir; oleh itu kamu akan mengetahui kelak (akibatnya). Demi sesungguhnya, aku akan memotong tangan dan kaki kamu dengan bersilang kemudian aku akan memalang kamu semuanya”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 50, 'قَالُوا۟ لَا ضَيْرَ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'قَالُوا لَا ضَيْرَ إِنَّا إِلَىٰ رَبِّنَا مُنقَلِبُونَ', NULL, 'They said, "No harm. Indeed, to our Lord we will return.', 'Mereka menjawab: “(Ugutanmu itu) tidaklah menjadi hal! Sesungguhnya kami (tidak gentar), kerana kepada Tuhan kamilah kembalinya kami.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 51, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَايَانَا أَن كُنَّا أَوَّلَ الْمُؤْمِنِينَ', NULL, 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."', '“Sesungguhnya kami amat berharap supaya Tuhan Kami mengampunkan dosa-dosa kami, kerana kamilah orang-orang yang mula-mula beriman (dalam peristiwa ini)”.', FALSE, NULL, NULL, 369, 19, 147, 318, FALSE, 0, NULL),
(26, 52, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', 'وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَسْرِ بِعِبَادِي إِنَّكُم مُّتَّبَعُونَ', NULL, 'And We inspired to Moses, "Travel by night with My servants; indeed, you will be pursued."', '(Allah berfirman): Dan Kami wahyukan kepada Nabi Musa: “Hendaklah engkau membawa hamba-hambaKu (kaummu) keluar pada waktu malam; sesungguhnya kamu akan dikejar (oleh Firaun dan tenteranya)”.', FALSE, NULL, NULL, 369, 19, 148, 318, FALSE, 0, NULL),
(26, 53, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'فَأَرْسَلَ فِرْعَوْنُ فِي الْمَدَائِنِ حَاشِرِينَ', NULL, 'Then Pharaoh sent among the cities gatherers', '(Setelah mengetahui keadaan itu) maka Firaun mengutus (orang-orangnya) ke bandar-bandar (negeri Mesir), untuk mengumpulkan (tenteranya),', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 54, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ', 'إِنَّ هَٰؤُلَاءِ لَشِرْذِمَةٌ قَلِيلُونَ', NULL, '[And said], "Indeed, those are but a small band,', '(Sambil berkata kepada mereka): “Sesungguhnya orang-orang (Musa) itu adalah segolongan kecil,', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 55, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', 'وَإِنَّهُمْ لَنَا لَغَائِظُونَ', NULL, 'And indeed, they are enraging us,', '“Dan sesungguhnya mereka melakukan perkara yang menyebabkan kita marah;.', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 56, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', 'وَإِنَّا لَجَمِيعٌ حَاذِرُونَ', NULL, 'And indeed, we are a cautious society..."', '“Dan sesungguhnya kita sekalian, sentiasa beringat dan berjaga-jaga”.', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 57, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍ وَعُيُونٍ', 'فَأَخْرَجْنَاهُم مِّن جَنَّاتٍ وَعُيُونٍ', NULL, 'So We removed them from gardens and springs', 'Dengan sebab itu maka kami jadikan mereka (Firaun dan tenteranya) keluar meninggalkan kebun-kebun dan matair,', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 58, 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', NULL, 'And treasures and honorable station -', 'Dan juga khazanah-khazanah kekayaan serta tempat tinggal yang mulia.', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 59, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', 'كَذَٰلِكَ وَأَوْرَثْنَاهَا بَنِي إِسْرَائِيلَ', NULL, 'Thus. And We caused to inherit it the Children of Israel.', 'Demikianlah keadaannya; dan Kami jadikan semua peninggalan Firaun dan tenteranya milik Bani Israil sebagai pusaka.', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 60, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', 'فَأَتْبَعُوهُم مُّشْرِقِينَ', NULL, 'So they pursued them at sunrise.', 'Maka Firaun dan tenteranya pun mengejar mereka ketika matahari terbit.', FALSE, NULL, NULL, 369, 19, 148, 319, FALSE, 0, NULL),
(26, 61, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', 'فَلَمَّا تَرَاءَى الْجَمْعَانِ قَالَ أَصْحَابُ مُوسَىٰ إِنَّا لَمُدْرَكُونَ', NULL, 'And when the two companies saw one another, the companions of Moses said, "Indeed, we are to be overtaken!"', 'Setelah kedua-dua kumpulan itu nampak satu sama lain, berkatalah orang-orang Nabi Musa: “Sesungguhnya kita akan dapat ditawan”.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 62, 'قَالَ كَلَّآ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 'قَالَ كَلَّا إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ', NULL, '[Moses] said, "No! Indeed, with me is my Lord; He will guide me."', 'Nabi Musa menjawab: “Tidak! Jangan fikir (akan berlaku yang demikian)! Sesungguhnya aku sentiasa disertai oleh Tuhanku (dengan pemuliharaan dan pertolonganNya), Ia akan menunjuk jalan kepadaku”.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 63, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ', 'فَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ فَانفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ', NULL, 'Then We inspired to Moses, "Strike with your staff the sea," and it parted, and each portion was like a great towering mountain.', 'Lalu Kami wahyukan kepada Nabi Musa: “Pukullah laut itu dengan tongkatmu”. (Setelah dipukul) maka terbelahlah laut itu (kepada beberapa bahagian), lalu menjadilah air tiap-tiap bahagian yang terbelah itu terangkat seperti gunung yang besar.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 64, 'وَأَزْلَفْنَا ثَمَّ ٱلْـَٔاخَرِينَ', 'وَأَزْلَفْنَا ثَمَّ الْآخَرِينَ', NULL, 'And We advanced thereto the others [i.e., the pursuers].', 'Dan Kami dekatkan golongan yang lain itu ke situ.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 65, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُ أَجْمَعِينَ', NULL, 'And We saved Moses and those with him, all together.', 'Dan Kami selamatkan Nabi Musa serta orang-orang yang bersama dengannya, semuanya.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 66, 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', 'ثُمَّ أَغْرَقْنَا الْآخَرِينَ', NULL, 'Then We drowned the others.', 'Kemudian Kami tenggelamkan golongan yang lain (yang mengejarnya).', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 67, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya pada peristiwa yang demikian, terdapat satu tanda (yang membuktikan kekuasaan Allah); dan (dalam pada itu), kebanyakkan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(26, 69, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ', 'وَاتْلُ عَلَيْهِمْ نَبَأَ إِبْرَاهِيمَ', NULL, 'And recite to them the news of Abraham,', 'Dan bacakanlah pula kepada mereka perihal Nabi Ibrahim.', FALSE, NULL, NULL, 370, 19, 148, 319, FALSE, 0, NULL),
(26, 70, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ', 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِ مَا تَعْبُدُونَ', NULL, 'When he said to his father and his people, "What do you worship?"', 'Ketika ia berkata kepada bapanya dan kaumnya: “Apa yang kamu sembah?”', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 71, 'قَالُوا۟ نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَٰكِفِينَ', 'قَالُوا نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَاكِفِينَ', NULL, 'They said, "We worship idols and remain to them devoted."', 'Mereka menjawab: “Kami menyembah berhala-berhala, maka (kerana memuliakannya) kami berkekalan menyembahnya”.', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 72, 'قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ', 'قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ', NULL, 'He said, "Do they hear you when you supplicate?', 'Nabi Ibrahim bertanya: “Adakah berhala-berhala itu mendengar kamu semasa kamu menyerunya?', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 73, 'أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ', 'أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ', NULL, 'Or do they benefit you, or do they harm?"', '“Atau mereka dapat memberikan sesuatu yang ada manfaatnya kepada kamu ataupun menimpakan sesuatu bahaya?”', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 74, 'قَالُوا۟ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ', 'قَالُوا بَلْ وَجَدْنَا آبَاءَنَا كَذَٰلِكَ يَفْعَلُونَ', NULL, 'They said, "But we found our fathers doing thus."', 'Mereka menjawab: “(Tidak satupun!) Bahkan kami dapati datuk nenek kami berbuat demikian”.', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 75, 'قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ', 'قَالَ أَفَرَأَيْتُم مَّا كُنتُمْ تَعْبُدُونَ', NULL, 'He said, "Then do you see what you have been worshipping,', 'Nabi Ibrahim berkata: “Sudahkah kamu berfikir sehingga nampak gunanya benda-benda yang kamu sembah itu? -', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 76, 'أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ', 'أَنتُمْ وَآبَاؤُكُمُ الْأَقْدَمُونَ', NULL, 'You and your ancient forefathers?', '“(Yang sekian lama disembah oleh) kamu dan datuk nenek kamu yang dahulu?', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 77, 'فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ ٱلْعَٰلَمِينَ', 'فَإِنَّهُمْ عَدُوٌّ لِّي إِلَّا رَبَّ الْعَالَمِينَ', NULL, 'Indeed, they are enemies to me, except the Lord of the worlds,', '“(Aku bertanya demikian) kerana sesungguhnya berhala-berhala itu ialah musuhKu, (aku tidak menyembah) melainkan Allah Tuhan sekalian alam;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 78, 'ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ', 'الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ', NULL, 'Who created me, and He [it is who] guides me.', '“Tuhan yang menciptakan daku (dari tiada kepada ada), maka Dia lah yang memimpin dan memberi petunjuk kepadaku;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 79, 'وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ', 'وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ', NULL, 'And it is He who feeds me and gives me drink.', '“Dan Tuhan yang Dia lah jua memberiku makan dan memberi minum,', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 80, 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', NULL, 'And when I am ill, it is He who cures me', '“Dan apabila aku sakit, maka Dia lah yang menyembuhkan penyakitku;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 81, 'وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ', 'وَالَّذِي يُمِيتُنِي ثُمَّ يُحْيِينِ', NULL, 'And who will cause me to die and then bring me to life', '“Dan (Dia lah) yang mematikan daku, kemudian Ia menghidupkan daku;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 82, 'وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ', 'وَالَّذِي أَطْمَعُ أَن يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ', NULL, 'And who I aspire that He will forgive me my sin on the Day of Recompense."', '“Dan (Dia lah) yang aku harap-harapkan supaya mengampunkan dosaku pada hari kiamat;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 83, 'رَبِّ هَبْ لِى حُكْمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ', NULL, '[And he said], "My Lord, grant me authority and join me with the righteous.', '“Wahai Tuhanku, berikanlah daku ilmu pengetahuan ugama, dan hubungkanlah daku dengan orang-orang yang soleh;', FALSE, NULL, NULL, 370, 19, 148, 320, FALSE, 0, NULL),
(26, 84, 'وَٱجْعَل لِّى لِسَانَ صِدْقٍ فِى ٱلْـَٔاخِرِينَ', 'وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ', NULL, 'And grant me a mention [i.e., reputation] of honor among later generations.', '“Dan jadikanlah bagiku sebutan yang baik (nama yang harum) dalam kalangan orang-orang yang datang kemudian;', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 85, 'وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', 'وَاجْعَلْنِي مِن وَرَثَةِ جَنَّةِ النَّعِيمِ', NULL, 'And place me among the inheritors of the Garden of Pleasure.', '“Dan jadikanlah daku dari orang-orang yang mewarisi Syurga Jannatun-Naiim;', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 86, 'وَٱغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', 'وَاغْفِرْ لِأَبِي إِنَّهُ كَانَ مِنَ الضَّالِّينَ', NULL, 'And forgive my father. Indeed, he has been of those astray.', '“Dan ampunkanlah bagi bapaku, kerana sesungguhnya ia adalah dari orang-orang yang sesat;', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 87, 'وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ', 'وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ', NULL, 'And do not disgrace me on the Day they are [all] resurrected -', '“Dan janganlah engkau hinakan daku pada hari makhluk-makhluk dibangkitkan hidup semula -', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 88, 'يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ', 'يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ', NULL, 'The Day when there will not benefit [anyone] wealth or children', '“Hari yang padanya harta benda dan anak-pinak tidak dapat memberikan pertolongan sesuatu apapun,', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 89, 'إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍ سَلِيمٍ', 'إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ', NULL, 'But only one who comes to Allāh with a sound heart."', '“Kecuali (harta benda dan anak-pinak) orang-orang yang datang mengadap Allah dengan hati yang selamat sejahtera (dari syirik dan penyakit munafik);', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 90, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ', 'وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ', NULL, 'And Paradise will be brought near [that Day] to the righteous.', '“Dan (pada hari itu) didekatkan Syurga bagi orang-orang yang bertaqwa,', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 91, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِلْغَاوِينَ', 'وَبُرِّزَتِ الْجَحِيمُ لِلْغَاوِينَ', NULL, 'And Hellfire will be brought forth for the deviators,', '“Dan diperlihatkan neraka jelas nyata kepada orang-orang yang sesat;', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 92, 'وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', 'وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', NULL, 'And it will be said to them, "Where are those you used to worship', '“Serta dikatakan kepada mereka: ‘Mana dia benda-benda yang kamu sembah dahulu -', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 93, 'مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ', 'مِن دُونِ اللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ', NULL, 'Other than Allāh? Can they help you or help themselves?"', '‘Selain dari Allah? Dapatkah mereka menolong kamu atau menolong dirinya sendiri?’', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 94, 'فَكُبْكِبُوا۟ فِيهَا هُمْ وَٱلْغَاوُۥنَ', 'فَكُبْكِبُوا فِيهَا هُمْ وَالْغَاوُونَ', NULL, 'So they will be overturned into it [i.e., Hellfire], they and the deviators', '“Lalu mereka dihumbankan ke dalam neraka dengan tertiarap, jatuh bangun berulang-ulang, - mereka dan orang-orang yang sesat bersama,', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 95, 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ', 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ', NULL, 'And the soldiers of Iblees, all together.', '“Termasuk juga bala tentera iblis semuanya.', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 96, 'قَالُوا۟ وَهُمْ فِيهَا يَخْتَصِمُونَ', 'قَالُوا وَهُمْ فِيهَا يَخْتَصِمُونَ', NULL, 'They will say while they dispute therein,', '“Mereka berkata, sambil bertengkar sesama sendiri dalam neraka:', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 97, 'تَٱللَّهِ إِن كُنَّا لَفِى ضَلَٰلٍ مُّبِينٍ', 'تَاللَّهِ إِن كُنَّا لَفِي ضَلَالٍ مُّبِينٍ', NULL, '"By Allāh, we were indeed in manifest error', '“Demi Allah! Sesungguhnya kami (semasa di dunia dahulu) adalah di dalam kesesatan yang jelas nyata,', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 98, 'إِذْ نُسَوِّيكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'إِذْ نُسَوِّيكُم بِرَبِّ الْعَالَمِينَ', NULL, 'When we equated you with the Lord of the worlds.', '“'' Kerana kami menyamakan kamu dengan Tuhan sekalian alam;', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 99, 'وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', 'وَمَا أَضَلَّنَا إِلَّا الْمُجْرِمُونَ', NULL, 'And no one misguided us except the criminals.', '“'' Dan tiadalah yang menyesatkan kami melainkan golongan yang berdosa.', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 100, 'فَمَا لَنَا مِن شَٰفِعِينَ', 'فَمَا لَنَا مِن شَافِعِينَ', NULL, 'So now we have no intercessors', '“Dengan sebab itu, tiadalah kami beroleh sesiapapun yang memberi pertolongan,', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 101, 'وَلَا صَدِيقٍ حَمِيمٍ', 'وَلَا صَدِيقٍ حَمِيمٍ', NULL, 'And not a devoted friend.', '“Dan tiadalah juga sahabat karib yang bertimbang rasa.', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 102, 'فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ الْمُؤْمِنِينَ', NULL, 'Then if we only had a return [to the world] and could be of the believers..."', '“‘Maka alangkah baiknya kalau kami dapat ke dunia sekali lagi, supaya kami menjadi dari orang-orang yang beriman.’”', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 103, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya pada peristiwa yang demikian itu terdapat satu tanda (yang membukitkan keesaan Allah dan kekuasaanNya); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 104, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja Yang Maha Kuasa, lagi Maha mengasihani.', FALSE, NULL, NULL, 371, 19, 148, 320, FALSE, 0, NULL),
(26, 105, 'كَذَّبَتْ قَوْمُ نُوحٍ ٱلْمُرْسَلِينَ', 'كَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ', NULL, 'The people of Noah denied the messengers', '(Demikian juga) kaum Nabi Nuh telah mendustakan Rasul-rasul (yang diutus kepada mereka.)', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 106, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ', NULL, 'When their brother Noah said to them, "Will you not fear Allāh?', 'Ketika saudara mereka - Nabi Nuh, berkata kepada mereka: “Hendaknya kamu mematuhi suruhan Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 107, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'إِنِّي لَكُمْ رَسُولٌ أَمِينٌ', NULL, 'Indeed, I am to you a trustworthy messenger.', '“Sesungguhnya aku ini ialah Rasul yang amanah, (yang diutus oleh Allah) kepada kamu.', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 108, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku.', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 109, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ', NULL, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', '“Dan aku tidak meminta kepada kamu sebarang upah mengenai apa yang aku sampaikan (dari Tuhanku); balasanku hanyalah terserah kepada Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 110, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me."', '“Maka dengan yang demikian, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku”.', FALSE, NULL, NULL, 371, 19, 148, 321, FALSE, 0, NULL),
(26, 111, 'قَالُوٓا۟ أَنُؤْمِنُ لَكَ وَٱتَّبَعَكَ ٱلْأَرْذَلُونَ', 'قَالُوا أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ', NULL, 'They said, "Should we believe you while you are followed by the lowest [class of people]?"', 'Mereka menjawab: “Patutkah kami percaya kepadamu, sedang engkau semata-mata diikut oleh orang-orang yang rendah (pangkatnya dan hina pekerjaannya)?”', FALSE, NULL, NULL, 371, 19, 149, 321, FALSE, 0, NULL),
(26, 112, 'قَالَ وَمَا عِلْمِى بِمَا كَانُوا۟ يَعْمَلُونَ', 'قَالَ وَمَا عِلْمِي بِمَا كَانُوا يَعْمَلُونَ', NULL, 'He said, "And what is my knowledge of what they used to do?', 'Nabi Nuh berkata: “Dan apalah ada kaitannya pengetahuanku dengan (pangkat dan) pekerjaan mereka?', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 113, 'إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى لَوْ تَشْعُرُونَ', 'إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّي لَوْ تَشْعُرُونَ', NULL, 'Their account is only upon my Lord, if you [could] perceive.', '“Sebenarnya hitungan amal mereka hanya terserah kepada Tuhanku; kalaulah kamu menyedari dan memahaminya (kamu tidak berkata demikian).', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 114, 'وَمَآ أَنَا۠ بِطَارِدِ ٱلْمُؤْمِنِينَ', 'وَمَا أَنَا بِطَارِدِ الْمُؤْمِنِينَ', NULL, 'And I am not one to drive away the believers.', '“Dan aku tidak akan menghalau orang-orang yang beriman (daripada bercampur-gaul denganku).', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 115, 'إِنْ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', 'إِنْ أَنَا إِلَّا نَذِيرٌ مُّبِينٌ', NULL, 'I am only a clear warner."', '“Aku ini hanyalah seorang Rasul pemberi amaran yang jelas nyata (kepada semua - tidak kira hina mulia)”.', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 116, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلْمَرْجُومِينَ', 'قَالُوا لَئِن لَّمْ تَنتَهِ يَا نُوحُ لَتَكُونَنَّ مِنَ الْمَرْجُومِينَ', NULL, 'They said, "If you do not desist, O Noah, you will surely be of those who are stoned."', 'Mereka (mengugut dengan) berkata: “Jika engkau tidak mahu berhenti (daripada menyiarkan ugamamu itu) wahai Nuh, sudah tentu engkau akan menjadi dari orang-orang yang direjam!”', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 117, 'قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ', 'قَالَ رَبِّ إِنَّ قَوْمِي كَذَّبُونِ', NULL, 'He said, "My Lord, indeed my people have denied me.', 'Nabi Nuh berdoa dengan berkata: “Wahai Tuhanku! Sesungguhnya kaumku telah mendustakan daku.', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 118, 'فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ', 'فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا وَنَجِّنِي وَمَن مَّعِيَ مِنَ الْمُؤْمِنِينَ', NULL, 'Then judge between me and them with decisive judgement and save me and those with me of the believers."', '“Oleh itu, hukumkanlah antaraku dengan mereka, dengan hukuman tegas (yang menegakkan yang benar dan melenyapkan yang salah), serta selamatkanlah daku dan orang-orang yang beriman yang bersama-sama denganku”', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 119, 'فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'فَأَنجَيْنَاهُ وَمَن مَّعَهُ فِي الْفُلْكِ الْمَشْحُونِ', NULL, 'So We saved him and those with him in the laden ship.', 'Maka Kami selamatkan dia dan orang-orang yang bersama-sama dengannya dalam bahtera yang penuh sarat (dengan berbagai makhluk).', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 120, 'ثُمَّ أَغْرَقْنَا بَعْدُ ٱلْبَاقِينَ', 'ثُمَّ أَغْرَقْنَا بَعْدُ الْبَاقِينَ', NULL, 'Then We drowned thereafter the remaining ones.', 'Kemudian daripada itu, Kami tenggelamkan golongan (kafir) yang tinggal (tidak turut bersama dalam bahtera).', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 121, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya pada peristiwa yang demikian, terdapat satu tanda (yang membuktikan kekuasaan Allah); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 122, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 372, 19, 149, 321, FALSE, 0, NULL),
(26, 123, 'كَذَّبَتْ عَادٌ ٱلْمُرْسَلِينَ', 'كَذَّبَتْ عَادٌ الْمُرْسَلِينَ', NULL, 'ʿAad denied the messengers', '(Demikian juga) kaum Aad telah mendustakan Rasul-rasul (yang diutus kepada mereka).', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 124, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ', NULL, 'When their brother Hūd said to them, "Will you not fear Allāh?', 'Ketika saudara mereka - Nabi Hud, berkata kepada mereka: “Hendaknya kamu mematuhi perintah Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 125, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'إِنِّي لَكُمْ رَسُولٌ أَمِينٌ', NULL, 'Indeed, I am to you a trustworthy messenger.', '“Sesungguhnya aku ini seorang Rasul yang amanah, (yang diutus oleh Allah) kepada kamu.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 126, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 127, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ', NULL, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', '“Dan aku tidak meminta kepada kamu sebarang upah mengenai apa yang aku sampaikan (dari Tuhanku); balasanku hanyalah terserah kepada Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 128, 'أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ', 'أَتَبْنُونَ بِكُلِّ رِيعٍ آيَةً تَعْبَثُونَ', NULL, 'Do you construct on every elevation a sign, amusing yourselves,', '“Patutkah kamu mendirikan pada tiap-tiap tempat yang tinggi bangunan-bangunan yang tersergam, padahal kamu tidak membuatnya dengan sesuatu tujuan yang baik.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 129, 'وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ', 'وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ', NULL, 'And take for yourselves constructions [i.e., palaces and fortresses] that you might abide eternally?', '“Dan kamu pula bersusah payah mendirikan istana-istana dan benteng-benteng yang kukuh dengan harapan hendak kekal hidup selama-lamanya?', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 130, 'وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ', 'وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ', NULL, 'And when you strike, you strike as tyrants.', '“Dan apabila kamu memukul atau menyeksa, kamu melakukan yang demikian dengan kejam bengis?', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 131, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah dan taatlah kepadaku.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 132, 'وَٱتَّقُوا۟ ٱلَّذِىٓ أَمَدَّكُم بِمَا تَعْلَمُونَ', 'وَاتَّقُوا الَّذِي أَمَدَّكُم بِمَا تَعْلَمُونَ', NULL, 'And fear He who provided you with that which you know,', '“Dan berbaktilah kamu kepada Allah yang telah menolong kamu dengan pemberian nikmat-nikmatNya yang kamu sedia mengetahuinya.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 133, 'أَمَدَّكُم بِأَنْعَٰمٍ وَبَنِينَ', 'أَمَدَّكُم بِأَنْعَامٍ وَبَنِينَ', NULL, 'Provided you with grazing livestock and children', '“Diberinya kamu binatang-binatang ternak (yang biak) serta anak-pinak (yang ramai),', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 134, 'وَجَنَّٰتٍ وَعُيُونٍ', 'وَجَنَّاتٍ وَعُيُونٍ', NULL, 'And gardens and springs.', '“Dan taman-taman (yang indah permai) serta mataair-mataair (yang mengalir).', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 135, 'إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', NULL, 'Indeed, I fear for you the punishment of a terrible day."', '“Sesungguhnya aku takut, (bahawa) kamu akan ditimpa azab seksa hari yang besar (huru-haranya)”.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 136, 'قَالُوا۟ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ ٱلْوَٰعِظِينَ', 'قَالُوا سَوَاءٌ عَلَيْنَا أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ الْوَاعِظِينَ', NULL, 'They said, "It is all the same to us whether you advise or are not of the advisors.', 'Mereka menjawab: “Sama sahaja bagi kami, sama ada engkau beri nasihat pengajaran, atau engkau tidak menjadi dari orang-orang yang memberi nasihat pengajaran.', FALSE, NULL, NULL, 372, 19, 149, 322, FALSE, 0, NULL),
(26, 137, 'إِنْ هَٰذَآ إِلَّا خُلُقُ ٱلْأَوَّلِينَ', 'إِنْ هَٰذَا إِلَّا خُلُقُ الْأَوَّلِينَ', NULL, 'This is not but the custom of the former peoples,', '“Segala apa (yang engkau katakan) ini, hanyalah adat kebiasaan orang-orang dahulu-kala,', FALSE, NULL, NULL, 373, 19, 149, 322, FALSE, 0, NULL),
(26, 138, 'وَمَا نَحْنُ بِمُعَذَّبِينَ', 'وَمَا نَحْنُ بِمُعَذَّبِينَ', NULL, 'And we are not to be punished."', '“Dan kami pula tidak akan diseksa”.', FALSE, NULL, NULL, 373, 19, 149, 322, FALSE, 0, NULL),
(26, 139, 'فَكَذَّبُوهُ فَأَهْلَكْنَٰهُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'فَكَذَّبُوهُ فَأَهْلَكْنَاهُمْ إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.', 'Akhirnya mereka mendustakan Rasul itu, lalu Kami binasakan mereka. Sesungguhnya pada peristiwa yang demikian, terdapat satu tanda (yang membuktikan kekuasaan Allah); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 373, 19, 149, 322, FALSE, 0, NULL),
(26, 140, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 373, 19, 149, 322, FALSE, 0, NULL),
(26, 141, 'كَذَّبَتْ ثَمُودُ ٱلْمُرْسَلِينَ', 'كَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ', NULL, 'Thamūd denied the messengers', '(Demikian juga) kaum Thamud telah mendustakan Rasul-rasul (yang diutus kepada mereka),', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 142, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ صَٰلِحٌ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لَهُمْ أَخُوهُمْ صَالِحٌ أَلَا تَتَّقُونَ', NULL, 'When their brother Ṣāliḥ said to them, "Will you not fear Allāh?', 'Ketika saudara mereka - Nabi Soleh, berkata kepada mereka: “Hendaknya kamu mematuhi perintah Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 143, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'إِنِّي لَكُمْ رَسُولٌ أَمِينٌ', NULL, 'Indeed, I am to you a trustworthy messenger.', '“Sesungguhnya aku ini Rasul yang amanah, (yang diutus oleh Allah) kepada kamu.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 144, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 145, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ', NULL, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', '“Dan aku tidak meminta kepada kamu sebarang upah mengenai apa yang aku sampaikan (dari Tuhanku), balasanku hanyalah terserah kepada Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 146, 'أَتُتْرَكُونَ فِى مَا هَٰهُنَآ ءَامِنِينَ', 'أَتُتْرَكُونَ فِي مَا هَاهُنَا آمِنِينَ', NULL, 'Will you be left in what is here, secure [from death],', '“Adakah (kamu fikir), bahawa kamu akan dibiarkan sentiasa bersenang-senang dalam nikmat-nikmat yang ada di dunia ini? -', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 147, 'فِى جَنَّٰتٍ وَعُيُونٍ', 'فِي جَنَّاتٍ وَعُيُونٍ', NULL, 'Within gardens and springs', '“Di dalam taman-taman (yang indah permai), dan mataair-mataair (yang mengalir),', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 148, 'وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ', 'وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ', NULL, 'And fields of crops and palm trees with softened fruit?', '“Dan kebun-kebun tanaman serta pohon-pohon tamar (kurma) yang buah mayangnya halus lembut?', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 149, 'وَتَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا فَٰرِهِينَ', 'وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا فَارِهِينَ', NULL, 'And you carve out of the mountains, homes, with skill.', '“Dan kamu memahat sebahagian dari gunung-ganang sebagai tempat tinggal - dengan bijak dan bersungguh-sungguh?', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 150, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku;', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 151, 'وَلَا تُطِيعُوٓا۟ أَمْرَ ٱلْمُسْرِفِينَ', 'وَلَا تُطِيعُوا أَمْرَ الْمُسْرِفِينَ', NULL, 'And do not obey the order of the transgressors,', '“Dan janganlah kamu taati perintah orang-orang yang melampaui batas, -', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 152, 'ٱلَّذِينَ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', 'الَّذِينَ يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ', NULL, 'Who cause corruption in the land and do not amend."', '“Iaitu orang-orang yang melakukan kerosakan di bumi dan tidak membuat kebaikan”.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 153, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', 'قَالُوا إِنَّمَا أَنتَ مِنَ الْمُسَحَّرِينَ', NULL, 'They said, "You are only of those affected by magic.', 'Mereka menjawab: “Sesungguhnya engkau ini hanyalah salah seorang dari golongan yang kena sihir!', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 154, 'مَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'مَا أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِآيَةٍ إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."', '“Engkau hanyalah seorang manusia seperti kami; oleh itu, bawakanlah satu tanda (mukjizat) jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 155, 'قَالَ هَٰذِهِۦ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ', 'قَالَ هَٰذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ', NULL, 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.', 'Nabi Soleh berkata: “Ini adalah seekor unta betina, (di antara cara-cara hidupnya ialah) air kamu hendaklah menjadi bahagian minumnya sehari, dan bahagian kamu sehari, menurut giliran yang tertentu.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 156, 'وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ', 'وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ', NULL, 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."', '“Dan janganlah kamu menyentuhnya dengan sesuatu yang menyakitinya; (jika kamu menyakitinya) maka akibatnya kamu akan dibinasakan oleh azab seksa hari yang besar (huru-haranya)”.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 157, 'فَعَقَرُوهَا فَأَصْبَحُوا۟ نَٰدِمِينَ', 'فَعَقَرُوهَا فَأَصْبَحُوا نَادِمِينَ', NULL, 'But they hamstrung her and so became regretful.', 'Akhirnya mereka menikam mati unta itu, kemudian mereka menyesal (setelah melihat kedatangan bala bencana).', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 158, 'فَأَخَذَهُمُ ٱلْعَذَابُ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'فَأَخَذَهُمُ الْعَذَابُ إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.', 'Lalu mereka ditimpa azab yang membinasakan. Sesungguhnya peristiwa yang demikian mengandungi satu tanda (yang membuktikan kekuasaan Allah); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 159, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 373, 19, 149, 323, FALSE, 0, NULL),
(26, 160, 'كَذَّبَتْ قَوْمُ لُوطٍ ٱلْمُرْسَلِينَ', 'كَذَّبَتْ قَوْمُ لُوطٍ الْمُرْسَلِينَ', NULL, 'The people of Lot denied the messengers', '(Demikian juga) kaum Nabi Lut telah mendustakan Rasul-rasul (yang diutus kepada mereka).', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 161, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ', NULL, 'When their brother Lot said to them, "Will you not fear Allāh?', 'Ketika saudara mereka - Nabi Lut, berkata kepada mereka: “Hendaknya kamu mematuhi perintah Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 162, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'إِنِّي لَكُمْ رَسُولٌ أَمِينٌ', NULL, 'Indeed, I am to you a trustworthy messenger.', '“Sesungguhnya aku ini Rasul yang amanah, (yang diutus oleh Allah) kepada kamu.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 163, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 164, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ', NULL, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', '“Dan aku tidak meminta kepada kamu sebarang upah mengenai apa yang aku sampaikan (dari Tuhanku); balasanku hanyalah terserah kepada Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 165, 'أَتَأْتُونَ ٱلذُّكْرَانَ مِنَ ٱلْعَٰلَمِينَ', 'أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ', NULL, 'Do you approach males among the worlds', '“Patutkah kamu melakukan hubungan jenis dengan lelaki dari kalangan manusia,', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 166, 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَٰجِكُم بَلْ أَنتُمْ قَوْمٌ عَادُونَ', 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَاجِكُم بَلْ أَنتُمْ قَوْمٌ عَادُونَ', NULL, 'And leave what your Lord has created for you as mates? But you are a people transgressing."', '“Dan kamu tinggalkan apa yang diciptakan oleh Tuhan kamu untuk kamu (melakukan hubungan yang halal) dari badan isteri-isteri kamu? (Kamu orang-orang yang bersalah) bahkan kamu adalah kaum yang melampaui batas (keinginan kebanyaKan haiwan)!”', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 167, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلْمُخْرَجِينَ', 'قَالُوا لَئِن لَّمْ تَنتَهِ يَا لُوطُ لَتَكُونَنَّ مِنَ الْمُخْرَجِينَ', NULL, 'They said, "If you do not desist, O Lot, you will surely be of those evicted."', 'Mereka menjawab: “Sesungguhnya jika engkau tidak berhenti wahai Lut (daripada mencaci dan menyalahkan kami), nescaya engkau akan diusir keluar!”', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 168, 'قَالَ إِنِّى لِعَمَلِكُم مِّنَ ٱلْقَالِينَ', 'قَالَ إِنِّي لِعَمَلِكُم مِّنَ الْقَالِينَ', NULL, 'He said, "Indeed, I am, toward your deed, of those who detest [it].', 'Nabi Lut berkata: “Sesungguhnya aku dari orang-orang yang bencikan perbuatan kamu yang keji itu”.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 169, 'رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ', 'رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ', NULL, 'My Lord, save me and my family from [the consequence of] what they do."', '(Nabi Lut berdoa): “Wahai Tuhanku, selamatkanlah daku dan keluarga serta pengikut-pengikutku dari apa yang dilakukan oleh golongan (yang jahat) itu.”', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 170, 'فَنَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'فَنَجَّيْنَاهُ وَأَهْلَهُ أَجْمَعِينَ', NULL, 'So We saved him and his family, all,', 'Maka Kami selamatkan dia dan keluarganya serta pengikut-pengikutnya - semuanya', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 171, 'إِلَّا عَجُوزًا فِى ٱلْغَٰبِرِينَ', 'إِلَّا عَجُوزًا فِي الْغَابِرِينَ', NULL, 'Except an old woman among those who remained behind.', 'Kecuali seorang perempuan tua tertinggal dalam golongan yang kena azab itu.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 172, 'ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ', 'ثُمَّ دَمَّرْنَا الْآخَرِينَ', NULL, 'Then We destroyed the others.', 'Kemudian Kami hancurkan yang lain (yang menentang Nabi Lut).', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 173, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَاءَ مَطَرُ الْمُنذَرِينَ', NULL, 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', 'Dan Kami hujani mereka dengan hujan (azab yang membinasakan); maka amatlah buruknya hujan azab yang menimpa kaum yang telah diberi amaran.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 174, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya peristiwa yang demikian, mengandungi satu tanda (yang membuktikan kekuasaan Allah); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 175, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 374, 19, 149, 324, FALSE, 0, NULL),
(26, 176, 'كَذَّبَ أَصْحَٰبُ لْـَٔيْكَةِ ٱلْمُرْسَلِينَ', 'كَذَّبَ أَصْحَابُ الْأَيْكَةِ الْمُرْسَلِينَ', NULL, 'The companions of the thicket [i.e., the people of Madyan] denied the messengers', '(Demikian juga) penduduk “Aikah” telah mendustakan Rasul-rasul (yang diutus kepada mereka).', FALSE, NULL, NULL, 374, 19, 149, 325, FALSE, 0, NULL),
(26, 177, 'إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ', NULL, 'When Shuʿayb said to them, "Will you not fear Allāh?', 'Ketika Nabi Syuaib berkata kepada mereka: “Hendaknya kamu mematuhi perintah Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 374, 19, 149, 325, FALSE, 0, NULL),
(26, 178, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'إِنِّي لَكُمْ رَسُولٌ أَمِينٌ', NULL, 'Indeed, I am to you a trustworthy messenger.', '“Sesungguhnya aku ini Rasul yang amanah, (yang diutus oleh Allah) kepada kamu.', FALSE, NULL, NULL, 374, 19, 149, 325, FALSE, 0, NULL),
(26, 179, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'So fear Allāh and obey me.', '“Oleh itu, takutilah kamu akan (kemurkaan) Allah, dan taatlah kepadaku.', FALSE, NULL, NULL, 374, 19, 149, 325, FALSE, 0, NULL),
(26, 180, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَىٰ رَبِّ الْعَالَمِينَ', NULL, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', '“Dan aku tidak meminta kepada kamu sebarang upah mengenai apa yang aku sampaikan (dari Tuhanku); balasanku hanyalah terserah kepada Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 374, 19, 149, 325, FALSE, 0, NULL),
(26, 181, 'أَوْفُوا۟ ٱلْكَيْلَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُخْسِرِينَ', 'أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ', NULL, 'Give full measure and do not be of those who cause loss.', '“Hendaklah kamu menyempurnakan sukatan cupak-gantang, dan janganlah kamu menjadi golongan yang merugikan orang lain.', FALSE, NULL, NULL, 374, 19, 150, 325, FALSE, 0, NULL),
(26, 182, 'وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ', 'وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ', NULL, 'And weigh with an even [i.e., honest] balance.', '“Dan timbanglah dengan neraca yang betul timbangannya.', FALSE, NULL, NULL, 374, 19, 150, 325, FALSE, 0, NULL),
(26, 183, 'وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ', NULL, 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.', '“Dan janganlah kamu mengurangi hak-hak orang ramai, dan janganlah kamu bermaharajalela melakukan kerosakan di bumi.', FALSE, NULL, NULL, 374, 19, 150, 325, FALSE, 0, NULL),
(26, 184, 'وَٱتَّقُوا۟ ٱلَّذِى خَلَقَكُمْ وَٱلْجِبِلَّةَ ٱلْأَوَّلِينَ', 'وَاتَّقُوا الَّذِي خَلَقَكُمْ وَالْجِبِلَّةَ الْأَوَّلِينَ', NULL, 'And fear He who created you and the former creation."', '“Dan (sebaliknya) berbaktilah kepada Allah yang telah menciptakan kamu dan umat-umat yang telah lalu”.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 185, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', 'قَالُوا إِنَّمَا أَنتَ مِنَ الْمُسَحَّرِينَ', NULL, 'They said, "You are only of those affected by magic.', 'Mereka menjawab: “Sesungguhnya engkau ini (hai Syuaib) hanyalah salah seorang dari golongan yang kena sihir.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 186, 'وَمَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلْكَٰذِبِينَ', 'وَمَا أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ الْكَاذِبِينَ', NULL, 'You are but a man like ourselves, and indeed, we think you are among the liars.', '“Dan engkau hanyalah seorang manusia seperti kami; dan sesungguhnya kami fikir engkau ini dari orang-orang yang dusta.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 187, 'فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ السَّمَاءِ إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'So cause to fall upon us fragments of the sky, if you should be of the truthful."', 'Oleh itu, gugurkanlah atas kami ketul-ketul (yang membinasakan) dari langit, jika betul engkau dari orang-orang yang benar!”', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 188, 'قَالَ رَبِّىٓ أَعْلَمُ بِمَا تَعْمَلُونَ', 'قَالَ رَبِّي أَعْلَمُ بِمَا تَعْمَلُونَ', NULL, 'He said, "My Lord is most knowing of what you do."', 'Nabi Syuaib berkata: “Tuhanku lebih mengetahui akan apa yang kamu lakukan”.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 189, 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ', 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ', NULL, 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.', 'Maka mereka tetap juga mendustakannya, lalu mereka ditimpa azab seksa hari awan mendung; sesungguhnya kejadian itu adalah merupakan azab seksa hari yang amat besar - (huru-haranya).', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 190, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'إِنَّ فِي ذَٰلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', NULL, 'Indeed in that is a sign, but most of them were not to be believers.', 'Sesungguhnya peristiwa yang demikian, mengandungi satu tanda (yang membuktikan kekuasaan Allah); dan dalam pada itu, kebanyakan mereka tidak juga mahu beriman.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 191, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', 'Dan sesungguhnya Tuhanmu (wahai Muhammad), Dia lah sahaja yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 375, 19, 150, 325, FALSE, 0, NULL),
(26, 192, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلْعَٰلَمِينَ', 'وَإِنَّهُ لَتَنزِيلُ رَبِّ الْعَالَمِينَ', NULL, 'And indeed, it [i.e., the Qur’ān] is the revelation of the Lord of the worlds.', 'Dan sesungguhnya Al-Quran (yang di antara isinya kisah-kisah yang tersebut) adalah diturunkan oleh Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 193, 'نَزَلَ بِهِ ٱلرُّوحُ ٱلْأَمِينُ', 'نَزَلَ بِهِ الرُّوحُ الْأَمِينُ', NULL, 'The Trustworthy Spirit [i.e., Gabriel] has brought it down', 'Ia dibawa turun oleh malaikat Jibril yang amanah.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 194, 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ٱلْمُنذِرِينَ', 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ الْمُنذِرِينَ', NULL, 'Upon your heart, [O Muḥammad] - that you may be of the warners', 'Ke dalam hatimu, supaya engkau (wahai Muhammad) menjadi seorang dari pemberi-pemberi ajaran dan amaran (kepada umat manusia).', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 195, 'بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ', 'بِلِسَانٍ عَرَبِيٍّ مُّبِينٍ', NULL, 'In a clear Arabic language.', '(Ia diturunkan) dengan bahasa Arab yang fasih serta terang nyata.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 196, 'وَإِنَّهُۥ لَفِى زُبُرِ ٱلْأَوَّلِينَ', 'وَإِنَّهُ لَفِي زُبُرِ الْأَوَّلِينَ', NULL, 'And indeed, it is [mentioned] in the scriptures of former peoples.', 'Dan sesungguhnya Al-Quran (tersebut juga perihalnya dan sebahagian dari pengajaran-pengajarannya) di dalam Kitab-kitab ugama orang-orang yang telah lalu.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 197, 'أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ', 'أَوَلَمْ يَكُن لَّهُمْ آيَةً أَن يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ', NULL, 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?', '(Tidakkah mereka yang musyrik sedarkan kebenaran itu) dan tidakkah menjadi satu keterangan kepada mereka bahawa pendita-pendita ugama Bani lsrail mengetahui akan kebenaran Al-Quran itu?', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 198, 'وَلَوْ نَزَّلْنَٰهُ عَلَىٰ بَعْضِ ٱلْأَعْجَمِينَ', 'وَلَوْ نَزَّلْنَاهُ عَلَىٰ بَعْضِ الْأَعْجَمِينَ', NULL, 'And even if We had revealed it to one among the foreigners', 'Dan sekiranya Kami turunkan Al-Quran kepada setengah orang yang bukan Arab, yang tidak tahu membaca Arab,', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 199, 'فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ', 'فَقَرَأَهُ عَلَيْهِم مَّا كَانُوا بِهِ مُؤْمِنِينَ', NULL, 'And he had recited it to them [perfectly], they would [still] not have been believers in it.', 'Kemudian ia (dikurniakan Tuhan dapat) membacakannya kepada mereka, mereka tetap juga tidak mahu percayakan bacaan itu daripada Tuhan.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 200, 'كَذَٰلِكَ سَلَكْنَٰهُ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'كَذَٰلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ', NULL, 'Thus have We inserted it [i.e., disbelief] into the hearts of the criminals.', 'Demikianlah Kami masukkan perasaan (kufur ingkar) itu ke dalam hati orang-orang yang melakukan dosa - tidak percayakan Al-Quran.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 201, 'لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'لَا يُؤْمِنُونَ بِهِ حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ', NULL, 'They will not believe in it until they see the painful punishment.', 'Mereka tidak beriman kepada Al-Quran sehingga mereka melihat azab yang tidak terperi sakitnya,', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 202, 'فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', NULL, 'And it will come to them suddenly while they perceive [it] not.', 'Lalu azab itu datang menimpa mereka secara mengejut, dengan tidak mereka menyedarinya.', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 203, 'فَيَقُولُوا۟ هَلْ نَحْنُ مُنظَرُونَ', 'فَيَقُولُوا هَلْ نَحْنُ مُنظَرُونَ', NULL, 'And they will say, "May we be reprieved?"', 'Maka (pada saat itu) mereka akan berkata (dengan menyesal): “Dapatkah kiranya kami diberi tempoh?”', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 204, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', NULL, 'So for Our punishment are they impatient?', '(Kalaulah demikian keadaan mereka) maka patutkah mereka meminta disegerakan azab Kami?', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 205, 'أَفَرَءَيْتَ إِن مَّتَّعْنَٰهُمْ سِنِينَ', 'أَفَرَأَيْتَ إِن مَّتَّعْنَاهُمْ سِنِينَ', NULL, 'Then have you considered if We gave them enjoyment for years', 'Bagaimana fikiranmu (wahai Muhammad)? Jika Kami berikan mereka menikmati kesenangan bertahun-tahun,', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 206, 'ثُمَّ جَآءَهُم مَّا كَانُوا۟ يُوعَدُونَ', 'ثُمَّ جَاءَهُم مَّا كَانُوا يُوعَدُونَ', NULL, 'And then there came to them that which they were promised?', 'Kemudian mereka didatangi azab seksa yang dijanjikan kepada mereka,', FALSE, NULL, NULL, 375, 19, 150, 326, FALSE, 0, NULL),
(26, 207, 'مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يُمَتَّعُونَ', 'مَا أَغْنَىٰ عَنْهُم مَّا كَانُوا يُمَتَّعُونَ', NULL, 'They would not be availed by the enjoyment with which they were provided.', '(Tentulah) kesenangan yang mereka nikmati bertahun-tahun itu tidak dapat memberikan mereka sebarang pertolongan.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 208, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ', 'وَمَا أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ', NULL, 'And We did not destroy any city except that it had warners', 'Dan tiadalah Kami membinasakan mana-mana negeri (yang telah dibinasakan itu), melainkan setelah diutus kepadanya lebih dahulu, Rasul-rasul pemberi amaran.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 209, 'ذِكْرَىٰ وَمَا كُنَّا ظَٰلِمِينَ', 'ذِكْرَىٰ وَمَا كُنَّا ظَالِمِينَ', NULL, 'As a reminder; and never have We been unjust.', 'Memperingatkan mereka; dan Kami tidak sekali-kali berlaku zalim.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 210, 'وَمَا تَنَزَّلَتْ بِهِ ٱلشَّيَٰطِينُ', 'وَمَا تَنَزَّلَتْ بِهِ الشَّيَاطِينُ', NULL, 'And the devils have not brought it [i.e., the revelation] down.', 'Dan Al-Quran itu pula tidak sekali-kali dibawa turun oleh Syaitan-syaitan.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 211, 'وَمَا يَنۢبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ', 'وَمَا يَنبَغِي لَهُمْ وَمَا يَسْتَطِيعُونَ', NULL, 'It is not allowable for them, nor would they be able.', 'Dan tidak layak bagi Syaitan-syaitan itu berbuat demikian, dan mereka juga tidak akan dapat melakukannya.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 212, 'إِنَّهُمْ عَنِ ٱلسَّمْعِ لَمَعْزُولُونَ', 'إِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ', NULL, 'Indeed they, from [its] hearing, are removed.', 'Sesungguhnya mereka dihalang sama sekali daripada mendengar wahyu yang dibawa oleh Malaikat.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 213, 'فَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلْمُعَذَّبِينَ', 'فَلَا تَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَتَكُونَ مِنَ الْمُعَذَّبِينَ', NULL, 'So do not invoke with Allāh another deity and [thus] be among the punished.', 'Maka janganlah engkau (wahai Muhammad) menyembah tuhan yang lain bersama-sama Allah, akibatnya engkau akan menjadi dari golongan yang dikenakan azab seksa.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 214, 'وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', 'وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ', NULL, 'And warn, [O Muḥammad], your closest kindred.', 'Dan berilah peringatan serta amaran kepada kaum kerabatmu yang dekat.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 215, 'وَٱخْفِضْ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ', NULL, 'And lower your wing [i.e., show kindness] to those who follow you of the believers.', 'Dan hendaklah engkau merendah diri kepada pengikut-pengikutmu dari orang-orang yang beriman.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 216, 'فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'فَإِنْ عَصَوْكَ فَقُلْ إِنِّي بَرِيءٌ مِّمَّا تَعْمَلُونَ', NULL, 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."', 'Kemudian jika mereka berlaku ingkar kepadamu, maka katakanlah: “Sesungguhnya aku berlepas diri dari apa yang kamu lakukan!”', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 217, 'وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ', 'وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ', NULL, 'And rely upon the Exalted in Might, the Merciful,', 'Dan berserahlah kepada Allah Yang Maha Kuasa, lagi Maha Mengasihani,', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 218, 'ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ', 'الَّذِي يَرَاكَ حِينَ تَقُومُ', NULL, 'Who sees you when you arise', 'Yang melihatmu semasa engkau berdiri (mengerjakan sembahyang),', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 219, 'وَتَقَلُّبَكَ فِى ٱلسَّٰجِدِينَ', 'وَتَقَلُّبَكَ فِي السَّاجِدِينَ', NULL, 'And your movement among those who prostrate.', 'Dan (melihat) gerak-gerimu di antara orang-orang yang sujud.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 220, 'إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'Indeed, He is the Hearing, the Knowing.', 'Sesungguhnya Dia lah jua yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 221, 'هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ', 'هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ الشَّيَاطِينُ', NULL, 'Shall I inform you upon whom the devils descend?', 'Mahukah, Aku khabarkan kepada kamu, kepada siapakah Syaitan-syaitan itu selalu turun?', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 222, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ', 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ', NULL, 'They descend upon every sinful liar.', 'Mereka selalu turun kepada tiap-tiap pendusta yang berdosa,', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 223, 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ', 'يُلْقُونَ السَّمْعَ وَأَكْثَرُهُمْ كَاذِبُونَ', NULL, 'They pass on what is heard, and most of them are liars.', 'Yang mendengar bersungguh-sungguh (apa yang disampaikan oleh Syaitan-syaitan itu), sedang kebanyakan beritanya adalah dusta.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 224, 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', 'وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ', NULL, 'And the poets - [only] the deviators follow them.', 'Dan Ahli-ahli syair itu, diturut oleh golongan yang sesat - tidak berketentuan hala.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 225, 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ', 'أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وَادٍ يَهِيمُونَ', NULL, 'Do you not see that in every valley they roam', 'Tidakkah engkau melihat bahawa mereka merayau-rayau dengan tidak berketentuan hala dalam tiap-tiap lembah (khayal dan angan-angan kosong)?', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 226, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', NULL, 'And that they say what they do not do? -', 'Dan bahawa mereka memperkatakan apa yang mereka tidak melakukannya?', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(26, 227, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَذَكَرُوا اللَّهَ كَثِيرًا وَانتَصَرُوا مِن بَعْدِ مَا ظُلِمُوا وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا أَيَّ مُنقَلَبٍ يَنقَلِبُونَ', NULL, 'Except those [poets] who believe and do righteous deeds and remember Allāh often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.', 'Kecuali orang-orang yang beriman dan beramal soleh (dari kalangan penyair-penyair itu), dan mereka pula mengingati Allah banyak-banyak, serta mereka membela diri sesudah mereka dianiaya. Dan (ingatlah), orang-orang yang melakukan sebarang kezaliman, akan mengetahui kelak, ke tempat mana, mereka akan kembali.', FALSE, NULL, NULL, 376, 19, 150, 326, FALSE, 0, NULL),
(27, 1, 'طسٓ ۚ تِلْكَ ءَايَـٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ', 'طس تلك ايات القران وكتاب مبين', NULL, 'Ṭā, Seen. These are the verses of the Qur’ān [i.e., recitation] and a clear Book', 'Taa, siin. Ini ialah ayat-ayat Al-Quran, juga Kitab yang jelas nyata (kandungannya dan kebenarannya),', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 6, NULL),
(27, 2, 'هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'هدى وبشرى للمؤمنين', NULL, 'As guidance and good tidings for the believers', 'Menjadi hidayah petunjuk dan berita gembira bagi orang-orang yang beriman,', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 3, NULL),
(27, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', 'الذين يقيمون الصلاة ويؤتون الزكاة وهم بالاخرة هم يوقنون', NULL, 'Who establish prayer and give zakāh, and of the Hereafter they are certain [in faith].', 'Iaitu mereka yang tetap mendirikan sembahyang dan memberi zakat, sedang mereka pula percaya dengan yakin akan hari akhirat.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 9, NULL),
(27, 4, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَـٰلَهُمْ فَهُمْ يَعْمَهُونَ', 'ان الذين لا يؤمنون بالاخرة زينا لهم اعمالهم فهم يعمهون', NULL, 'Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.', 'Sesungguhnya orang-orang yang tidak percaya kepada hari akhirat, Kami jadikan perbuatan-perbuatan buruk mereka kelihatan baik kepada mereka; oleh itu, tinggallah mereka meraba-raba dalam kesesatan.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 10, NULL),
(27, 5, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 'اولئك الذين لهم سوء العذاب وهم في الاخرة هم الاخسرون', NULL, 'Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.', 'Merekalah orang-orang yang akan beroleh azab seksa yang buruk (di dunia) dan mereka pula pada hari akhirat adalah orang-orang yang palig rugi.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 10, NULL),
(27, 6, 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', 'وانك لتلقى القران من لدن حكيم عليم', NULL, 'And indeed, [O Muḥammad], you receive the Qur’ān from one Wise and Knowing.', 'Dan sesungguhnya engkau (wahai Muhammad) diberikan menyambut dan menerima Al-Quran dari sisi Allah Yang Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 7, NULL),
(27, 7, 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ', 'اذ قال موسى لاهله اني انست نارا ساتيكم منها بخبر او اتيكم بشهاب قبس لعلكم تصطلون', NULL, '[Mention] when Moses said to his family, "Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves."', '(Ingatkanlah peristiwa) ketika Nabi Musa berkata kepada isterinya: “Sesungguhnya aku ada melihat api; aku akan bawakan berita dari situ kepada kamu, atau aku akan bawakan colok api daripadanya, supaya kamu dapat memanaskan diri.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 16, NULL),
(27, 8, 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَـٰلَمِينَ', 'فلما جاءها نودي ان بورك من في النار ومن حولها وسبحان الله رب العالمين', NULL, 'But when he came to it, he was called, "Blessed is whoever is at the fire and whoever is around it. And exalted is Allāh, Lord of the worlds.', 'Maka apabila ia sampai ke tempat api itu, (kedengaran) ia diseru: “Berkat yang melimpah-limpah kepada orang yang berada dekat api ini dan sesiapa yang ada (di daerah) sekelilingnya; dan Maha Sucilah Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 14, NULL),
(27, 9, 'يَـٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'يا موسى انه انا الله العزيز الحكيم', NULL, 'O Moses, indeed it is I - Allāh, the Exalted in Might, the Wise."', '“Wahai Musa, sesungguhnya Akulah Allah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 6, NULL),
(27, 10, 'وَأَلْقِ عَصَاكَ ۚ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ ۚ يَـٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', 'والق عصاك فلما راها تهتز كانها جان ولى مدبرا ولم يعقب يا موسى لا تخف اني لا يخاف لدي المرسلون', NULL, 'And [he was told], "Throw down your staff." But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allāh said], "O Moses, fear not. Indeed, in My presence the messengers do not fear.', 'Dan (sekarang) campakkanlah tongkatmu. Maka apabila ia melihat tongkatnya itu (menjadi seekor ular besar) bergerak cepat tangkas, seolah-olah seekor ular kecil, berpalinglah dia melarikan diri dan tidak menoleh lagi. (Lalu ia diseru): “Wahai Musa, janganlah takut, sesungguhnya Rasul-rasul itu semasa mengadapku (menerima wahyu), tidak sepatutnya merasa takut,', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 19, NULL),
(27, 11, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ', 'الا من ظلم ثم بدل حسنا بعد سوء فاني غفور رحيم', NULL, 'Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.', '“Tetapi sesiapa yang berbuat salah, kemudian ia mengubahnya dengan melakukan kebaikan sesudah berbuat salah, maka sesungguhnya Aku Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 11, NULL),
(27, 12, 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ۖ فِى تِسْعِ ءَايَـٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ', 'وادخل يدك في جيبك تخرج بيضاء من غير سوء في تسع ايات الى فرعون وقومه انهم كانوا قوما فاسقين', NULL, 'And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient."', '“Dan masukkanlah tanganmu melalui belahan dada bajumu, nescaya keluarlah ia putih bersinar-sinar dengan tidak ada cacat (ini ialah) di antara sembilan mukjizat (yang membuktikan kebenaranmu), untuk dibawa kepada Firaun dan kaumnya; sesungguhnya mereka adalah kaum yang fasik - derhaka.', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 19, NULL),
(27, 13, 'فَلَمَّا جَآءَتْهُمْ ءَايَـٰتُنَا مُبْصِرَةً قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ', 'فلما جاءتهم اياتنا مبصرة قالوا هذا سحر مبين', NULL, 'But when there came to them Our visible signs, they said, "This is obvious magic."', 'Maka ketika keterangan-keterangan mukjizat Kami sampai kepada Firan dan kaumnya dengan jelas nyata, berkatalah mereka: “ini adalah sihir yang terang nyata!”', FALSE, NULL, NULL, 377, 19, 151, 327, FALSE, 8, NULL),
(27, 14, 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا ۚ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ', 'وجحدوا بها واستيقنتها انفسهم ظلما وعلوا فانظر كيف كان عاقبة المفسدين', NULL, 'And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.', 'Dan mereka mengingkarinya secara zalim dan sombong angkuh sedang hati mereka meyakini kebenarannya. Oleh itu, lihatlah bagaimana kesudahan orang-orang yang melakukan kerosakan.', FALSE, NULL, NULL, 378, 19, 151, 327, FALSE, 11, NULL),
(27, 15, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَـٰنَ عِلْمًا ۖ وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', 'ولقد اتينا داوود وسليمان علما وقالا الحمد لله الذي فضلنا على كثير من عباده المؤمنين', NULL, 'And We had certainly given to David and Solomon knowledge, and they said, "Praise [is due] to Allāh, who has favored us over many of His believing servants."', 'Dan sesungguhnya kami telah mengurniakan ilmu pengetahuan kepada Nabi Daud dan Nabi Sulaiman; dan mereka berdua bersyukur dengan berkata: “Segala puji tertentu bagi Allah yang dengan limpah kurniaNya memberi kami kelebihan mengatasi kebanyakan hamba-hambaNya yang beriman”.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 15, NULL),
(27, 16, 'وَوَرِثَ سُلَيْمَـٰنُ دَاوُۥدَ ۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَـٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', 'وورث سليمان داوود وقال يا ايها الناس علمنا منطق الطير واوتينا من كل شيء ان هذا لهو الفضل المبين', NULL, 'And Solomon inherited David. He said, "O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty."', 'Dan Nabi Sulaiman mewarisi (pangkat kenabian dan kerajaan) Nabi Daud; dan (setelah itu) Nabi Sulaiman berkata: “Wahai umat manusia, kami telah diajar mengerti bahasa pertuturan burung, dan kami telah diberikan serba sedikit dari tiap-tiap sesuatu (yang diperlukan); sesungguhnya yang demikian ini adalah limpah kurnia (dari Allah) yang jelas nyata”.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 18, NULL),
(27, 17, 'وَحُشِرَ لِسُلَيْمَـٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', 'وحشر لسليمان جنوده من الجن والانس والطير فهم يوزعون', NULL, 'And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows', 'Dan dihimpunkan bagi Nabi Sulaiman bala tenteranya, dari jin dan manusia serta burung; lalu mereka dijaga serta diatur keadaan dan perjalanan masing-masing.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 9, NULL),
(27, 18, 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَـٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَـٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَـٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', 'حتى اذا اتوا على واد النمل قالت نملة يا ايها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون', NULL, 'Until, when they came upon the valley of the ants, an ant said, "O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not."', '(Maralah angkatan itu) hingga apabila mereka sampai ke “Waadin-Naml”, berkatalah seekor semut: “Wahai sekalian semut, masuklah ke sarang kamu masing-masing, jangan Sulaiman dan tenteranya memijak serta membinasakan kamu, sedang mereka tidak menyedari”.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 19, NULL),
(27, 19, 'فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّـٰلِحِينَ', 'فتبسم ضاحكا من قولها وقال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه وادخلني برحمتك في عبادك الصالحين', NULL, 'So [Solomon] smiled, amused at her speech, and said, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."', 'Maka tersenyumlah Nabi Sulaiman mendengar kata-kata semut itu, dan berdoa dengan berkata: “Wahai Tuhanku, ilhamkanlah daku supaya tetap bersyukur akan nikmatMu yang Engkau kurniakan kepadaku dan kepada ibu bapaku, dan supaya aku tetap mengerjakan amal soleh yang Engkau redai; dan masukkanlah daku - dengan limpah rahmatMu - dalam kumpulan hamba-hambaMu yang soleh”.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 24, NULL),
(27, 20, 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', 'وتفقد الطير فقال ما لي لا ارى الهدهد ام كان من الغائبين', NULL, 'And he took attendance of the birds and said, "Why do I not see the hoopoe - or is he among the absent?', 'Dan (setelah itu) Nabi Sulaiman memeriksa kumpulan burung (yang turut serta dalam tenteranya) lalu berkata: “Mengapa aku tidak melihat burung belatuk? Adakah ia dari mereka yang tidak hadir?', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 12, NULL),
(27, 21, 'لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍ مُّبِينٍ', 'لَأُعَذِّبَنَّهُ عَذَابًا شَدِيدًا أَوْ لَأَذْبَحَنَّهُ أَوْ لَيَأْتِيَنِّي بِسُلْطَانٍ مُّبِينٍ', NULL, 'I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization."', '“Demi sesungguhnya! Aku akan menyeksanya dengan seksa yang seberat-beratnya, atau aku akan menyembelihnya, kecuali ia membawa kepadaku alasan yang terang nyata (yang membuktikan sebab-sebab ia tidak hadir)”.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 0, NULL),
(27, 22, 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ', 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِ وَجِئْتُكَ مِن سَبَإٍ بِنَبَإٍ يَقِينٍ', NULL, 'But he [i.e., the hoopoe] stayed not long and said, "I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.', 'Burung belatuk itu tidak lama ghaibnya selepas itu, lalu datang sambil berkata (kepada Nabi Sulaiman): “Aku dapat mengetahui secara meliputi akan perkara yang engkau tidak cukup mengetahuinya, dan aku datang kepadamu dari negeri Saba'' dengan membawa khabar berita yang diyakini kebenarannya.', FALSE, NULL, NULL, 378, 19, 151, 328, FALSE, 0, NULL),
(27, 23, 'إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', 'إِنِّي وَجَدتُّ امْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَيْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', NULL, 'Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.', '“Sesungguhnya aku dapati seorang perempuan memerintah mereka dan ia telah diberikan kepadanya (serba sedikit) dari tiap-tiap sesuatu (yang diperlukan) dan ia pula mempunyai singgahsana yang besar.', FALSE, NULL, NULL, 379, 19, 151, 328, FALSE, 0, NULL),
(27, 24, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ اللَّهِ وَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', NULL, 'I found her and her people prostrating to the sun instead of Allāh, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,', '“Aku dapati raja perempuan itu dan kaumnya sujud kepada matahari dengan meninggalkan ibadat menyembah Allah, dan Syaitan pula memperelokkan pada pandangan mereka perbuatan (syirik) mereka, lalu menghalangi mereka dari jalan (yang benar); oleh itu mereka tidak beroleh petunjuk, -', FALSE, NULL, NULL, 379, 19, 151, 328, FALSE, 0, NULL),
(27, 25, 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'أَلَّا يَسْجُدُوا لِلَّهِ الَّذِي يُخْرِجُ الْخَبْءَ فِي السَّمَاوَاتِ وَالْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', NULL, '[And] so they do not prostrate to Allāh, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -', '“(Mereka dihalangi oleh Syaitan) supaya mereka tidak sujud menyembah Allah yang mengeluarkan benda yang tersembunyi di langit dan di bumi, dan yang mengetahui apa yang kamu rahsiakan serta apa yang kamu zahirkan.', FALSE, NULL, NULL, 379, 19, 151, 328, FALSE, 0, NULL),
(27, 26, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', NULL, 'Allāh - there is no deity except Him, Lord of the Great Throne."', '“Allah! - Tiada Tuhan melainkan Dia, Tuhan yang mempunyai Arasy yang besar”.', FALSE, NULL, NULL, 379, 19, 151, 328, TRUE, 0, NULL),
(27, 27, 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَٰذِبِينَ', 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ الْكَاذِبِينَ', NULL, '[Solomon] said, "We will see whether you were truthful or were of the liars.', 'Nabi Sulaiman berkata: Kami akan fikirkan dengan sehalus-halusnya, adakah benar apa yang engkau katakan itu, ataupun engkau dari golongan yang berdusta.', FALSE, NULL, NULL, 379, 19, 152, 328, FALSE, 0, NULL),
(27, 28, 'ٱذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', 'اذْهَب بِّكِتَابِي هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانظُرْ مَاذَا يَرْجِعُونَ', NULL, 'Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return."', '“Pergilah bawa suratku ini, serta campakkanlah kepada mereka, kemudian berundurlah dari mereka; dalam pada itu perhatikanlah apa tindak balas mereka”.', FALSE, NULL, NULL, 379, 19, 152, 328, FALSE, 0, NULL),
(27, 29, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌ كَرِيمٌ', 'قَالَتْ يَا أَيُّهَا الْمَلَأُ إِنِّي أُلْقِيَ إِلَيَّ كِتَابٌ كَرِيمٌ', NULL, 'She said, "O eminent ones, indeed, to me has been delivered a noble letter.', '(Setelah membaca surat itu), berkatalah raja perempuan negeri Saba'': “Wahai ketua-ketua kamu! Sesungguhnya telah disampaikan kepadaku sepucuk surat yang mulia.', FALSE, NULL, NULL, 379, 19, 152, 328, FALSE, 0, NULL),
(27, 30, 'إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'إِنَّهُ مِن سُلَيْمَانَ وَإِنَّهُ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ', NULL, 'Indeed, it is from Solomon, and indeed, it is [i.e., reads]: ''In the name of Allāh, the Entirely Merciful, the Especially Merciful,', '“Sesungguhnya surat itu dari Nabi Sulaiman, dan kandungannya (seperti berikut): ‘Dengan nama Allah, Yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 379, 19, 152, 328, FALSE, 0, NULL),
(27, 31, 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', 'أَلَّا تَعْلُوا عَلَيَّ وَأْتُونِي مُسْلِمِينَ', NULL, 'Be not haughty with me but come to me in submission [as Muslims].''"', '“‘Bahawa janganlah kamu meninggi diri terhadapku, dan datanglah kamu kepadaku dengan menyerah diri (beriman dan mematuhi ajaran ugama Allah).’”', FALSE, NULL, NULL, 379, 19, 152, 328, FALSE, 0, NULL),
(27, 32, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', 'قَالَتْ يَا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي أَمْرِي مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', NULL, 'She said, "O eminent ones, advise me in my affair. I would not decide a matter until you witness [for] me."', 'Raja perempuan itu berkata lagi: “Wahai ketua-ketua kaum, berilah penjelasan kepadaku mengenai perkara yang aku hadapi ini; aku tidak pernah memutuskan sesuatu perkara sebelum kamu hadir memberi pendapat dan mempersetujuinya”.', FALSE, NULL, NULL, 379, 19, 152, 329, FALSE, 0, NULL),
(27, 33, 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', 'قَالُوا نَحْنُ أُولُو قُوَّةٍ وَأُولُو بَأْسٍ شَدِيدٍ وَالْأَمْرُ إِلَيْكِ فَانظُرِي مَاذَا تَأْمُرِينَ', NULL, 'They said, "We are men of strength and of great military might, but the command is yours, so see what you will command."', 'Mereka menjawab: Kita adalah orang-orang yang kuat gagah dan amat berani merempuh peperangan; dan perkara itu (walau bagaimanapun) terserahlah kepadamu; oleh itu fikirkanlah apa yang engkau hendak perintahkan.', FALSE, NULL, NULL, 379, 19, 152, 329, FALSE, 0, NULL),
(27, 34, 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً وَكَذَٰلِكَ يَفْعَلُونَ', 'قَالَتْ إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا وَجَعَلُوا أَعِزَّةَ أَهْلِهَا أَذِلَّةً وَكَذَٰلِكَ يَفْعَلُونَ', NULL, 'She said, "Indeed kings - when they enter a city, they ruin it and render the honored of its people humbled. And thus do they do.', 'Raja perempuan itu berkata: “Sesungguhnya raja-raja, apabila masuk ke sebuah negeri, mereka merosakkannya, dan mereka menjadikan penduduknya yang mulia hina-dina; dan sedemikian itulah mereka akan lakukan.', FALSE, NULL, NULL, 379, 19, 152, 329, FALSE, 0, NULL),
(27, 35, 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', 'وَإِنِّي مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ', NULL, 'But indeed, I will send to them a gift and see with what [reply] the messengers will return."', '“Dan bahawa aku hendak menghantarkan hadiah kepada mereka, kemudian aku akan menunggu, apakah balasan yang akan dibawa balik oleh utusan-utusan kita”', FALSE, NULL, NULL, 379, 19, 152, 329, FALSE, 0, NULL),
(27, 36, 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', 'فَلَمَّا جَاءَ سُلَيْمَانَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِّمَّا آتَاكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', NULL, 'So when they came to Solomon, he said, "Do you provide me with wealth? But what Allāh has given me is better than what He has given you. Rather, it is you who rejoice in your gift.', 'Maka apabila (utusan pembawa hadiah itu) datang mengadap Nabi Sulaiman, berkatalah Nabi Sulaiman (kepadanya): “Tidaklah patut kamu memberikan kepadaku pemberian harta-benda, kerana apa yang telah diberikan Allah kepadaku lebih baik dari apa yang telah diberikanNya kepada kamu; (bukan aku yang memandang kepada pemberian hadiah) bahkan kamulah yang bergembira dengan hanya kekayaan yang dihadiahkan kepada kamu (atau yang kamu hadiahkan dengan perasaan megah).', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 37, 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَٰغِرُونَ', 'ارْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَا أَذِلَّةً وَهُمْ صَاغِرُونَ', NULL, 'Return to them, for we will surely come to them with soldiers that they will be powerless to encounter, and we will surely expel them therefrom in humiliation, and they will be debased."', '“Kembalilah kepada mereka, (jika mereka tidak juga mahu beriman) maka demi sesungguhnya Kami akan mendatangi mereka dengan angkatan tentera yang mereka tidak terdaya menentangnya, dan kami akan mengeluarkan mereka dari negeri Saba'' dengan keadaan hina, menjadi orang-orang tawanan.”', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 38, 'قَالَ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', 'قَالَ يَا أَيُّهَا الْمَلَأُ أَيُّكُمْ يَأْتِينِي بِعَرْشِهَا قَبْلَ أَن يَأْتُونِي مُسْلِمِينَ', NULL, '[Solomon] said, "O assembly [of jinn], which of you will bring me her throne before they come to me in submission?"', 'Nabi Sulaiman berkata pula (kepada golongan bijak pandainya): “Wahai pegawai-pegawaiku, siapakah di antara kamu yang dapat membawa kepadaku singgahsananya sebelum mereka datang mengadapku dalam keadaan berserah diri memeluk Islam?”', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 39, 'قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ', 'قَالَ عِفْرِيتٌ مِّنَ الْجِنِّ أَنَا آتِيكَ بِهِ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ', NULL, 'A powerful one from among the jinn said, "I will bring it to you before you rise from your place, and indeed, I am for this [task] strong and trustworthy."', 'Berkatalah Ifrit dari golongan jin: “Aku akan membawakannya kepadamu sebelum engkau bangun dari tempat dudukmu, dan sesungguhnya aku amatlah kuat gagah untuk membawanya, lagi amanah”.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 40, 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ', 'قَالَ الَّذِي عِندَهُ عِلْمٌ مِّنَ الْكِتَابِ أَنَا آتِيكَ بِهِ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَآهُ مُسْتَقِرًّا عِندَهُ قَالَ هَٰذَا مِن فَضْلِ رَبِّي لِيَبْلُوَنِي أَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ', NULL, 'Said one who had knowledge from the Scripture, "I will bring it to you before your glance returns to you." And when [Solomon] saw it placed before him, he said, "This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful - his gratitude is only for [the benefit of] himself. And whoever is ungrateful - then indeed, my Lord is Free of need and Generous."', 'Berkata pula seorang yang mempunyai ilmu pengetahuan dari Kitab Allah: “Aku akan membawakannya kepadamu dalam sekelip mata!” Setelah Nabi Sulaiman melihat singgahsana itu terletak di sisinya, berkatalah ia: “Ini ialah dari limpah kurnia Tuhanku, untuk mengujiku adakah aku bersyukur atau aku tidak mengenangkan nikmat pemberianNya. Dan (sebenarnya) sesiapa yang bersyukur maka faedah syukurnya itu hanyalah terpulang kepada dirinya sendiri, dan sesiapa yang tidak bersyukur (maka tidaklah menjadi hal kepada Allah), kerana sesungguhnya Tuhanku Maha Kaya, lagi Maha Pemurah”.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 41, 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', 'قَالَ نَكِّرُوا لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِي أَمْ تَكُونُ مِنَ الَّذِينَ لَا يَهْتَدُونَ', NULL, 'He said, "Disguise for her her throne; we will see whether she will be guided [to truth] or will be of those who is not guided."', 'Nabi Sulaiman berkata pula (kepada orang-orangnya): “Ubahkanlah keadaan singgahsananya itu, supaya kita melihat adakah ia dapat mencapai pengetahuan yang sebenar (untuk mengenal singgahsananya itu) atau ia termasuk dalam golongan yang tidak dapat mencapai pengetahuan yang demikian”.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 42, 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُۥ هُوَ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', 'فَلَمَّا جَاءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُ هُوَ وَأُوتِينَا الْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', NULL, 'So when she arrived, it was said [to her], "Is your throne like this?" She said, "[It is] as though it was it." [Solomon said], "And we were given knowledge before her, and we have been Muslims [in submission to Allāh].', 'Maka ketika ia datang mengadap, Nabi Sulaiman bertanya kepadanya: Serupa inikah singahsanamu?” Ia menjawab: “Boleh jadi inilah dia; dan kami telah diberikan ilmu pengetahuan sebelum berlakunya (mukjizat) ini, dan kami pula adalah tetap berserah diri (menjunjung perintah Allah)”.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 43, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ إِنَّهَا كَانَتْ مِن قَوْمٍ كَٰفِرِينَ', 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ اللَّهِ إِنَّهَا كَانَتْ مِن قَوْمٍ كَافِرِينَ', NULL, 'And that which she was worshipping other than Allāh had averted her [from submission to Him]. Indeed, she was from a disbelieving people."', 'Dan ia dihalangi (daripada memeluk Islam pada masa yang lalu): apa yang ia pernah menyembahnya (dari benda-benda) yang lain dari Allah; sesungguhnya adalah ia (pada masa itu) dari puak yang kafir.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 44, 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'قِيلَ لَهَا ادْخُلِي الصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا قَالَ إِنَّهُ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ قَالَتْ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'She was told, "Enter the palace." But when she saw it, she thought it was a body of water and uncovered her shins [to wade through]. He said, "Indeed, it is a palace [whose floor is] made smooth with glass." She said, "My Lord, indeed I have wronged myself, and I submit with Solomon to Allāh, Lord of the worlds."', '(Setelah itu) dikatakan kepadanya: “Dipersilakan masuk ke dalam istana ini.” Maka ketika ia melihatnya, disangkanya halaman istana itu sebuah kolam air, serta dia pun menyingsingkan pakaian dari dua betisnya. Nabi Sulaiman berkata: “Sebenarnya ini adalah sebuah istana yang diperbuat licin berkilat dari kaca”. (Mendengar yang demikian), Balqis berdoa: “Wahai Tuhanku, sesungguhnya aku telah menganiaya diri sendiri dan (sekarang aku menegaskan bahawa) aku berserah diri memeluk Islam bersama-sama Nabi Sulaiman, kepada Allah Tuhan sekalian alam”.', FALSE, NULL, NULL, 380, 19, 152, 329, FALSE, 0, NULL),
(27, 45, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', 'وَلَقَدْ أَرْسَلْنَا إِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا أَنِ اعْبُدُوا اللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', NULL, 'And We had certainly sent to Thamūd their brother Ṣāliḥ, [saying], "Worship Allāh," and at once they were two parties conflicting.', 'Dan demi sesungguhnya, Kami telah mengutus kepada kaum Thamud, saudara mereka Nabi Soleh (menyeru mereka dengan berkata): “Sembahlah kamu akan Allah!” Maka tiba-tiba mereka menjadi dua puak (mukmin dan kafir) yang berbalah.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 46, 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'قَالَ يَا قَوْمِ لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'He said, "O my people, why are you impatient for evil before [i.e., instead of] good? Why do you not seek forgiveness of Allāh that you may receive mercy?"', 'Nabi Soleh berkata (kepada puak kafir): “Wahai kaumku, mengapa kamu segerakan kufur ingkar yang mendatangkan keburukan kepada kamu, (tidak) mendahulukan iman yang mendatangkan kebaikan kepada kamu? Alangkah baiknya kalau kamu memohon ampun kepada Allah supaya kamu diberi rahmat.”', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 47, 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ قَالَ طَٰٓئِرُكُمْ عِندَ ٱللَّهِ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', 'قَالُوا اطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ قَالَ طَائِرُكُمْ عِندَ اللَّهِ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', NULL, 'They said, "We consider you a bad omen, you and those with you." He said, "Your omen [i.e., fate] is with Allāh. Rather, you are a people being tested."', 'Mereka menjawab: “Kami merasa nahas dan malang dengan sebabmu, dan juga dengan sebab pengikut-pengikutmu!” Nabi Soleh berkata: Perkara yang menyebabkan baik dan malang kamu adalah di sisi Allah (dan Dia lah yang menentukannya, bukannya aku), sebenarnya kamu adalah kaum yang disesatkan (oleh hawa nafsu)”.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 48, 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', 'وَكَانَ فِي الْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِي الْأَرْضِ وَلَا يُصْلِحُونَ', NULL, 'And there were in the city nine family heads causing corruption in the land and not amending [its affairs].', 'Dan di bandar (tempat tinggal kaum Thamud) itu, ada sembilan orang yang semata-mata melakukan kerosakan di bumi (dengan berbagai-bagai maksiat) dan tidak melakukan kebaikan sedikitpun.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 49, 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ', 'قَالُوا تَقَاسَمُوا بِاللَّهِ لَنُبَيِّتَنَّهُ وَأَهْلَهُ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِ وَإِنَّا لَصَادِقُونَ', NULL, 'They said, "Take a mutual oath by Allāh that we will kill him by night, he and his family. Then we will say to his executor, ''We did not witness the destruction of his family, and indeed, we are truthful.''"', 'Mereka berkata (sesama sendiri): “Hendaklah kamu masing-masing bersumpah dengan nama Allah, bahawa sesungguhnya kita akan membunuh Soleh dan pengikut-pengikutnya secara mengejut pada waktu malam, kemudian kita akan berkata kepada warisnya: ‘Kami tidak hadir (di tempat) pembunuhan (Soleh apalagi membunuhnya atau membunuh) pengikut-pengikutnya, dan sesungguhnya kami adalah berkata benar’.”', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 50, 'وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', 'وَمَكَرُوا مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', NULL, 'And they planned a plan, and We planned a plan, while they perceived not.', 'Dan (dengan demikian) mereka telah merancangkan rancangan jahat, dan Kami pula rancangkan balasannya dengan seburuk-buruk balasan, sedang mereka tidak menyedarinya.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 51, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', 'فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَاهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', NULL, 'Then look how was the outcome of their plan - that We destroyed them and their people, all.', 'Maka lihatlah bagaimana akibat rancangan jahat mereka, iaitu Kami telah hancurkan mereka dan kaum mereka semuanya.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 52, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْلَمُونَ', 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُوا إِنَّ فِي ذَٰلِكَ لَآيَةً لِّقَوْمٍ يَعْلَمُونَ', NULL, 'So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know.', 'Kesudahannya rumah-rumah mereka itu telah runtuh ranap, dengan sebab mereka berlaku zalim; sesungguhnya kejadian yang demikian mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang mahu mengetahui (akan sebab dan musababnya).', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 53, 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'وَأَنجَيْنَا الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ', NULL, 'And We saved those who believed and used to fear Allāh.', 'Dan Kami selamatkan orang-orang yang beriman, serta yang selalu bertaqwa.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 54, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِ أَتَأْتُونَ الْفَاحِشَةَ وَأَنتُمْ تُبْصِرُونَ', NULL, 'And [mention] Lot, when he said to his people, "Do you commit immorality while you are seeing?', 'Dan Nabi Lut juga (Kami utuskan); (ingatlah peristiwanya) ketika ia berkata kepada kaumnya: “Patutkah kamu melakukan perbuatan yang keji sedang kamu nampak kejinya?', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 55, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', 'أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', NULL, 'Do you indeed approach men with desire instead of women? Rather, you are a people behaving ignorantly."', '“Sesungguhnya kamu mendatangi lelaki, bukan perempuan, kerana memuaskan nafsu syahwat kamu. (Perbuatan kamu itu amatlah keji) bahkan kamu kaum yang jahil (yang tidak mengetahui akan akibatnya)”.', FALSE, NULL, NULL, 381, 19, 152, 330, FALSE, 0, NULL),
(27, 56, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'فَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوا آلَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', NULL, 'But the answer of his people was not except that they said, "Expel the family of Lot from your city. Indeed, they are people who keep themselves pure."', 'Maka kaumnya tidak menjawab selain dari berkata: usirlah Lut dan pengikut-pengikutnya dari bandar kamu ini; sesungguhnya mereka adalah orang-orang yang mendakwakan dirinya bersih suci”.', FALSE, NULL, NULL, 382, 20, 153, 330, FALSE, 0, NULL),
(27, 57, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ٱلْغَٰبِرِينَ', 'فَأَنجَيْنَاهُ وَأَهْلَهُ إِلَّا امْرَأَتَهُ قَدَّرْنَاهَا مِنَ الْغَابِرِينَ', NULL, 'So We saved him and his family, except for his wife; We destined her to be of those who remained behind.', 'Lalu Kami selamatkan Nabi Lut dan keluarganya serta pengikut-pengikutnya, kecuali isterinya, Kami takdirkan dia menjadi dari golongan yang tertinggal dalam azab.', FALSE, NULL, NULL, 382, 20, 153, 330, FALSE, 0, NULL),
(27, 58, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَاءَ مَطَرُ الْمُنذَرِينَ', NULL, 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', 'Dan Kami hujani mereka dengan hujan yang membinasakan, maka amatlah buruknya hujan azab yang menimpa orang-orang yang telah diberi amaran.', FALSE, NULL, NULL, 382, 20, 153, 330, FALSE, 0, NULL),
(27, 59, 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', 'قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَىٰ عِبَادِهِ الَّذِينَ اصْطَفَىٰ آللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', NULL, 'Say, [O Muḥammad], "Praise be to Allāh, and peace upon His servants whom He has chosen. Is Allāh better or what they associate with Him?"', 'Katakanlah (wahai Muhammad): “Segala puji tertentu bagi Allah dan selamat sejahtera kepada hamba-hambaNya (Nabi-nabi) yang dipilihNya. Manakah yang lebih baik? - Allah (yang demikian kekuasaanNya) atau benda-benda yang mereka jadikan sekutu-sekutu bagiNya?', FALSE, NULL, NULL, 382, 20, 153, 331, FALSE, 0, NULL),
(27, 60, 'أَمَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', 'أَمَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَأَنزَلَ لَكُم مِّنَ السَّمَاءِ مَاءً فَأَنبَتْنَا بِهِ حَدَائِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنبِتُوا شَجَرَهَا أَإِلَٰهٌ مَّعَ اللَّهِ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', NULL, '[More precisely], is He [not best] who created the heavens and the earth and sent down for you rain from the sky, causing to grow thereby gardens of joyful beauty which you could not [otherwise] have grown the trees thereof? Is there a deity with Allāh? [No], but they are a people who ascribe equals [to Him].', 'Bahkan siapakah yang telah mencipta langit dan bumi, dan menurunkan hujan dari langit untuk kamu? Lalu Kami tumbuhkan dengan air hujan itu tanaman kebun-kebun (yang menghijau subur) dengan indahnya, yang kamu tidak dapat dan tidak berkuasa menumbuhkan pohon-pohonnya. Adakah sebarang tuhan yang lain bersama-sama Allah? (Tidak!) bahkan mereka (yang musyrik itu) adalah kaum yang menyeleweng dari kebenaran (tauhid).', FALSE, NULL, NULL, 382, 20, 153, 331, FALSE, 0, NULL),
(27, 61, 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'أَمَّن جَعَلَ الْأَرْضَ قَرَارًا وَجَعَلَ خِلَالَهَا أَنْهَارًا وَجَعَلَ لَهَا رَوَاسِيَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزًا أَإِلَٰهٌ مَّعَ اللَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', NULL, 'Is He [not best] who made the earth a stable ground and placed within it rivers and made for it firmly set mountains and placed between the two seas a barrier? Is there a deity with Allāh? [No], but most of them do not know.', 'Atau siapakah yang telah menjadikan bumi tempat penetapan dan telah menjadikan sungai-sungai di antara bahagian-bahagiannya dan telah menjadikan untuknya gunung-ganang yang menetapnya; dan juga telah menjadikan di antara dua laut (yang masin dan yang tawar) sekatan (semula jadi) yang memisahnya? Adakah sebarang tuhan yang lain bersama-sama Allah? (Tidak!) bahkan kebanyakan mereka (yang musyrik itu) tidak mengetahui.', FALSE, NULL, NULL, 382, 20, 153, 331, FALSE, 0, NULL),
(27, 62, 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ', 'أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ أَإِلَٰهٌ مَّعَ اللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ', NULL, 'Is He [not best] who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allāh? Little do you remember.', 'Atau siapakah yang memperkenankan doa orang yang menderita apabila ia berdoa kepadaNya, dan yang menghapuskan kesusahan, serta menjadikan kamu pengganti (umat-umat yang telah lalu) mendiami dan menguasai bumi? Adakah sebarang tuhan yang lain bersama-sama Allah? Amat sedikit di antara kamu yang mengingati (nikmat Allah itu).', FALSE, NULL, NULL, 382, 20, 153, 331, FALSE, 0, NULL),
(27, 63, 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ أَءِلَٰهٌ مَّعَ ٱللَّهِ تَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'أَمَّن يَهْدِيكُمْ فِي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ وَمَن يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ أَإِلَٰهٌ مَّعَ اللَّهِ تَعَالَى اللَّهُ عَمَّا يُشْرِكُونَ', NULL, 'Is He [not best] who guides you through the darknesses of the land and sea and who sends the winds as good tidings before His mercy? Is there a deity with Allāh? High is Allāh above whatever they associate with Him.', 'Atau siapakah yang menunjukkan jalan kepada kamu dalam gelap-gelita darat dan laut, dan yang menghantarkan angin sebagai pembawa berita yang mengembirakan sebelum kedatangan rahmatNya? Adakah sebarang tuhan yang lain bersama-sama Allah? Maha Tinggilah keadaan Allah dari apa yang mereka sekutukan denganNya.', FALSE, NULL, NULL, 382, 20, 153, 331, FALSE, 0, NULL),
(27, 64, 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'أَمَّن يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَمَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَإِلَٰهٌ مَّعَ اللَّهِ قُلْ هَاتُوا بُرْهَانَكُمْ إِن كُنتُمْ صَادِقِينَ', NULL, 'Is He [not best] who begins creation and then repeats it and who provides for you from the heaven and earth? Is there a deity with Allāh? Say, "Produce your proof, if you should be truthful."', 'Atau siapakah yang memulakan kejadian sekalian makhluk, kemudian dia mengembalikannya (hidup semula sesudah matinya). dan siapakah yang memberi rezeki kepada kamu dari langit dan bumi? Adakah sebarang tuhan yang lain bersama-sama Allah? Katakanlah (wahai Muhammad): “Bawalah kemari keterangan-keterangan kamu, jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 383, 20, 153, 331, FALSE, 0, NULL),
(27, 65, 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'قُل لَّا يَعْلَمُ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', NULL, 'Say, "None in the heavens and earth knows the unseen except Allāh, and they do not perceive when they will be resurrected."', 'Katakanlah lagi: Tiada sesiapapun di langit dan di bumi yang mengetahui perkara yang ghaib melainkan Allah!” Dan tiadalah mereka menyedari bilakah masing-masing akan dibangkitkan hidup semula (sesudah mati).', FALSE, NULL, NULL, 383, 20, 153, 331, FALSE, 0, NULL),
(27, 66, 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْـَٔاخِرَةِ بَلْ هُمْ فِى شَكٍّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ', 'بَلِ ادَّارَكَ عِلْمُهُمْ فِي الْآخِرَةِ بَلْ هُمْ فِي شَكٍّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ', NULL, 'Rather, their knowledge is arrested concerning the Hereafter. Rather, they are in doubt about it. Rather, they are, concerning it, blind.', 'Bahkan mereka (yang kafir) telah berkali-kali mengetahui tentang hari akhirat (tetapi mereka tidak meyakininya), bahkan mereka berada dalam syak mengenainya; bahkan matahati mereka buta langsung daripada memikirkannya.', FALSE, NULL, NULL, 383, 20, 153, 331, FALSE, 0, NULL),
(27, 67, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', 'وَقَالَ الَّذِينَ كَفَرُوا أَإِذَا كُنَّا تُرَابًا وَآبَاؤُنَا أَئِنَّا لَمُخْرَجُونَ', NULL, 'And those who disbelieve say, "When we have become dust as well as our forefathers, will we indeed be brought out [of the graves]?', 'Dan orang-orang yang kafir berkata: “Adakah sesudah kami menjadi tanah, dan juga datuk nenek kami, adakah kami semua akan dikeluarkan dari kubur (hidup semula)?', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 68, 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَآبَاؤُنَا مِن قَبْلُ إِنْ هَٰذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ', NULL, 'We have been promised this, we and our forefathers, before. This is not but legends of the former peoples."', '“Demi sesungguhnya, kami telah dijanjikan dengan perkara ini, kami dan juga datuk nenek kami dahulu; ini hanyalah cerita-cerita dongeng orang-orang dahulu kala”.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 69, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُجْرِمِينَ', NULL, 'Say, [O Muḥammad], "Proceed [i.e., travel] through the land and observe how was the end of the criminals."', 'Katakanlah (wahai Muhammad): “Mengembaralah kamu di muka bumi, kemudian perhatikanlah bagaimana buruknya kesudahan orang-orang yang berdosa itu”.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 70, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ', NULL, 'And grieve not over them or be in distress from what they conspire.', 'Dan janganlah engkau berdukacita terhadap (keingkaran) mereka (yang kafir itu,) dan janganlah engkau resah-gelisah disebabkan tipu daya yang mereka lakukan.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 71, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"', 'Dan mereka bertanya: “Bilakah berlakunya azab yang telah dijanjikan itu, jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 72, 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', 'قُلْ عَسَىٰ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ الَّذِي تَسْتَعْجِلُونَ', NULL, 'Say, "Perhaps it is close behind you [i.e., very near] - some of that for which you are impatient.', 'Katakanlah (wahai Muhammad): “Dipercayai tidak lama lagi akan datang kepada kamu sebahagian dari azab yang kamu minta disegerakan itu”.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 73, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', NULL, 'And indeed, your Lord is the possessor of bounty for the people, but most of them are not grateful."', 'Dan sesungguhnya Tuhanmu (wahai Muhammad) sentiasa melimpah-ruah kurniaNya kepada umat manusia seluruhnya tetapi kebanyakan mereka tidak bersyukur.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 74, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', NULL, 'And indeed, your Lord knows what their breasts conceal and what they declare.', 'Dan sesungguhnya Tuhanmu sedia mengetahui apa yang terpendam dalam hati mereka dan apa yang mereka nyatakan (dengan tutur kata dan perbuatan).', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 75, 'وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'وَمَا مِنْ غَائِبَةٍ فِي السَّمَاءِ وَالْأَرْضِ إِلَّا فِي كِتَابٍ مُّبِينٍ', NULL, 'And there is nothing concealed within the heaven and the earth except that it is in a clear Register.', 'Dan tiada sesuatu perkara yang ghaib di langit dan di bumi, melainkan tertulis dalam Kitab yang terang nyata.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 76, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', 'إِنَّ هَٰذَا الْقُرْآنَ يَقُصُّ عَلَىٰ بَنِي إِسْرَائِيلَ أَكْثَرَ الَّذِي هُمْ فِيهِ يَخْتَلِفُونَ', NULL, 'Indeed, this Qur’ān relates to the Children of Israel most of that over which they disagree.', 'Sesungguhnya Al-Quran ini menceritakan kepada Bani lsrail (perkara yang sebenar-benarnya) mengenai kebanyakan (hal-hal ugama) yang mereka berselisihan padanya.', FALSE, NULL, NULL, 383, 20, 153, 332, FALSE, 0, NULL),
(27, 77, 'وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', 'وَإِنَّهُ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', NULL, 'And indeed, it is guidance and mercy for the believers.', 'Dan sesungguhnya Al-Quran itu menjadi hidayah petunjuk dan rahmat bagi orang-orang yang beriman.', FALSE, NULL, NULL, 384, 20, 153, 332, FALSE, 0, NULL),
(27, 78, 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'إِنَّ رَبَّكَ يَقْضِي بَيْنَهُم بِحُكْمِهِ وَهُوَ الْعَزِيزُ الْعَلِيمُ', NULL, 'Indeed, your Lord will judge between them by His [wise] judgement. And He is the Exalted in Might, the Knowing.', 'Sesungguhnya Tuhanmu (wahai Muhammad) akan memutuskan di antara mereka dengan hukumNya, dan Dia lah sahaja Yang Maha Kuasa, lagi Maha Mengetahui.', FALSE, NULL, NULL, 384, 20, 153, 332, FALSE, 0, NULL),
(27, 79, 'فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', 'فَتَوَكَّلْ عَلَى اللَّهِ إِنَّكَ عَلَى الْحَقِّ الْمُبِينِ', NULL, 'So rely upon Allāh; indeed, you are upon the clear truth.', 'Oleh itu, berserahlah kepada Allah, sesungguhnya engkau berada di atas kebenaran yang jelas nyata.', FALSE, NULL, NULL, 384, 20, 153, 332, FALSE, 0, NULL),
(27, 80, 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'إِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ', NULL, 'Indeed, you will not make the dead hear, nor will you make the deaf hear the call when they have turned their backs retreating.', 'Sesungguhnya engkau tidak dapat menjadikan orang-orang yang mati (hatinya) itu menerima ajaranmu, dan tidak dapat menjadikan orang-orang yang pekak itu mendengar seruanmu, apabila mereka berundur ke belakang (disebabkan keingkarannya).', FALSE, NULL, NULL, 384, 20, 153, 332, FALSE, 0, NULL),
(27, 81, 'وَمَآ أَنتَ بِهَٰدِى ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 'وَمَا أَنتَ بِهَادِي الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ', NULL, 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [i.e., submitting to Allāh].', 'Dan engkau tidak akan dapat memberi petunjuk kepada orang-orang yang buta supaya menjauhi kesesatan mereka; engkau tidak dapat memperdengarkan (seruanmu itu) melainkan kepada orang-orang yang sanggup beriman akan ayat-ayat keterangan Kami, kerana mereka orang-orang yang berserah diri dengan ikhlas.', FALSE, NULL, NULL, 384, 20, 153, 332, FALSE, 0, NULL),
(27, 82, 'وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ', 'وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِّنَ الْأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآيَاتِنَا لَا يُوقِنُونَ', NULL, 'And when the word [i.e., decree] befalls them, We will bring forth for them a creature from the earth speaking to them, [saying] that the people were, of Our verses, not certain [in faith].', 'Dan apabila sampai masa berlakunya hukuman atas manusia, Kami keluarkan untuk mereka sejenis binatang dari bumi, yang akan menyatakan kepada mereka, bahawa manusia telah tidak meyakini ayat-ayat keterangan dan pengajaran Kami.', FALSE, NULL, NULL, 384, 20, 154, 332, FALSE, 0, NULL),
(27, 83, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ', 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِآيَاتِنَا فَهُمْ يُوزَعُونَ', NULL, 'And [warn of] the Day when We will gather from every nation a company of those who deny Our signs, and they will be [driven] in rows', 'Dan (ingatlah) hari Kami himpunkan dari tiap-tiap umat sekumpulan besar orang-orang yang mendustakan ayat-ayat keterangan Kami, lalu mereka dijaga serta diatur keadaan dan perjalanan masing-masing.', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 84, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', 'حَتَّىٰ إِذَا جَاءُوا قَالَ أَكَذَّبْتُم بِآيَاتِي وَلَمْ تُحِيطُوا بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', NULL, 'Until, when they arrive [at the place of Judgement], He will say, "Did you deny My signs while you encompassed them not in knowledge, or what [was it that] you were doing?"', 'Sehingga apabila mereka datang (ke tempat pengadilan), Allah Taala berfirman: “Adakah kamu mendustakan ayat-ayat keteranganKu dengan tidak lebih dahulu kamu mengetahuinya secara meliputi? Atau apakah yang kamu telah lakukan?”', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 85, 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', 'وَوَقَعَ الْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا فَهُمْ لَا يَنطِقُونَ', NULL, 'And the decree will befall them for the wrong they did, and they will not [be able to] speak.', 'Dan jatuhlah hukuman atas mereka (dengan azab) disebabkan kezaliman mereka (berlaku kufur ingkar), lalu mereka diam membisu.', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 86, 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'أَلَمْ يَرَوْا أَنَّا جَعَلْنَا اللَّيْلَ لِيَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'Do they not see that We made the night that they may rest therein and the day giving sight? Indeed in that are signs for a people who believe.', 'Tidakkah mereka memerhatikan bahawa Kami telah menjadikan malam untuk mereka berehat padanya, dan menjadikan siang terang-benderang? Sesungguhnya yang demikian itu mengandungi tanda-tanda (kekuasaan Allah) bagi kaum yang beriman.', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 87, 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', 'وَيَوْمَ يُنفَخُ فِي الصُّورِ فَفَزِعَ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ وَكُلٌّ أَتَوْهُ دَاخِرِينَ', NULL, 'And [warn of] the Day the Horn will be blown, and whoever is in the heavens and whoever is on the earth will be terrified except whom Allāh wills. And all will come to Him humbled.', 'Dan (ingatkanlah) hari di tiup sangkakala, lalu terkejutlah - gerun gementar - makhluk-makhluk yang ada di langit dan yang ada di bumi, kecuali mereka yang dikekhendaki Allah; dan kesemuanya akan datang kepadaNya dengan keadaan tunduk patuh.', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 88, 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', 'وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِيَ تَمُرُّ مَرَّ السَّحَابِ صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ إِنَّهُ خَبِيرٌ بِمَا تَفْعَلُونَ', NULL, 'And you see the mountains, thinking them motionless, while they will pass as the passing of clouds. [It is] the work of Allāh, who perfected all things. Indeed, He is Aware of that which you do.', 'Dan engkau melihat gunung-ganang, engkau menyangkanya tetap membeku, padahal ia bergerak cepat seperti bergeraknya awan; (demikianlah) perbuatan Allah yang telah membuat tiap - tiap sesuatu dengan serapi-rapi dan sebaik-baiknya; sesungguhnya Ia Amat mendalam PengetahuanNya akan apa yang kamu lakukan.', FALSE, NULL, NULL, 384, 20, 154, 333, FALSE, 0, NULL),
(27, 89, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ', 'مَن جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ آمِنُونَ', NULL, 'Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe.', 'Sesiapa yang datang membawa amal kebajikan (yang telah dikerjakannya) maka ia akan beroleh balasan yang lebih baik daripadanya, dan mereka akan beroleh aman sentosa daripada kejadian-kejadian yang mengerikan pada hari kiamat itu.', FALSE, NULL, NULL, 385, 20, 154, 333, FALSE, 0, NULL),
(27, 90, 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'وَمَن جَاءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِي النَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', NULL, 'And whoever comes with an evil deed - their faces will be overturned into the Fire, [and it will be said], "Are you recompensed except for what you used to do?"', 'Dan sesiapa yang datang membawa amal jahat (yang telah dikerjakannya) maka sudah tentu mereka akan ditumuskan mukanya ke dalam api neraka, (sambil dikatakan kepada mereka): “Kamu tidak diberi melainkan balasan apa yang kamu telah lakukan”.', FALSE, NULL, NULL, 385, 20, 154, 333, FALSE, 0, NULL),
(27, 91, 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'إِنَّمَا أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ الْبَلْدَةِ الَّذِي حَرَّمَهَا وَلَهُ كُلُّ شَيْءٍ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ', NULL, '[Say, O Muḥammad], "I have only been commanded to worship the Lord of this city, who made it sacred and to whom [belongs] all things. And I am commanded to be of the Muslims [i.e., those who submit to Allāh]', '(Katakanlah wahai Muhammad): “Aku hanyalah diperintahkan supaya menyembah Allah Tuhan negeri (Makkah) ini yang telah menjadikannya suci lagi dihormati dan yang menguasai segala-galanya; dan aku diperintahkan supaya tetap menjadi dari orang-orang Islam (yang menyerah diri bulat-bulat kepadaNya), -', FALSE, NULL, NULL, 385, 20, 154, 333, FALSE, 0, NULL),
(27, 92, 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', 'وَأَنْ أَتْلُوَ الْقُرْآنَ فَمَنِ اهْتَدَىٰ فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَقُلْ إِنَّمَا أَنَا مِنَ الْمُنذِرِينَ', NULL, 'And to recite the Qur’ān." And whoever is guided is only guided for [the benefit of] himself; and whoever strays - say, "I am only [one] of the warners."', '“Dan supaya aku sentiasa membaca Al-Quran”. Oleh itu, sesiapa yang menurut petunjuk (Al-Quran dan beramal dengannya) maka faedah perbuatannya itu akan terpulang kepada dirinya sendiri, dan sesiapa yang sesat, maka katakanlah kepadanya: “Sesungguhnya aku hanyalah seorang pemberi amaran”.', FALSE, NULL, NULL, 385, 20, 154, 333, FALSE, 0, NULL),
(27, 93, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'وَقُلِ الْحَمْدُ لِلَّهِ سَيُرِيكُمْ آيَاتِهِ فَتَعْرِفُونَهَا وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ', NULL, 'And say, "[All] praise is [due] to Allāh. He will show you His signs, and you will recognize them. And your Lord is not unaware of what you do."', 'Dan katakanlah (wahai Muhammad): “Segala puji tertentu bagi Allah (yang melimpahkan nikmat-nikmatNya yang tidak terhitung), Ia akan memperlihatkan kepada kamu tanda-tanda kekuasaanNya supaya kamu dapat mengetahuinya (dengan jelas nyata)”; dan Tuhanmu tidaklah lalai akan segala yang kamu lakukan.', FALSE, NULL, NULL, 385, 20, 154, 333, FALSE, 0, NULL),
(28, 1, 'طسٓمٓ', 'طسم', NULL, 'Ṭā, Seen, Meem.', 'Taa, Siin, Miim.', FALSE, NULL, NULL, 385, 20, 154, 334, FALSE, 1, NULL),
(28, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ', 'تلك ايات الكتاب المبين', NULL, 'These are verses of the clear Book.', 'Inilah ayat-ayat Kitab - Al-Quran - yang memberi penjelasan.', FALSE, NULL, NULL, 385, 20, 154, 334, FALSE, 4, NULL),
(28, 3, 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', 'نتلو عليك من نبا موسى وفرعون بالحق لقوم يؤمنون', NULL, 'We recite to you from the news of Moses and Pharaoh in truth for a people who believe.', 'Kami bacakan kepadamu (wahai Muhammad) sebahagian dari kisah Nabi Musa dan Firaun dengan keterangan yang benar bagi orang-orang yang beriman.', FALSE, NULL, NULL, 385, 20, 154, 334, FALSE, 9, NULL),
(28, 4, 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ ۚ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', 'ان فرعون علا في الارض وجعل اهلها شيعا يستضعف طائفة منهم يذبح ابناءهم ويستحيي نساءهم انه كان من المفسدين', NULL, 'Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters.', 'Sesungguhnya Firaun telah berlaku zalim di bumi (Mesir) dengan melampaui batas, serta ia menjadikan penduduknya berpuak-puak. Ia menindas sepuak di antaranya dengan membunuh anak-anak lelaki mereka dan membiarkan hidup anak-anak perempuan mereka. Sesungguhnya adalah ia dari golongan yang membuat kerosakan.', FALSE, NULL, NULL, 385, 20, 154, 334, FALSE, 19, NULL),
(28, 5, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', 'ونريد ان نمن على الذين استضعفوا في الارض ونجعلهم ائمة ونجعلهم الوارثين', NULL, 'And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors', 'Dan Kami hendak berihsan dengan memberikan pertolongan kepada kaum yang tertindas di negeri itu, dan hendak menjadikan mereka pemimpin-pemimpin, serta hendak menjadikan mereka orang-orang yang mewarisi (apa yang dimiliki oleh Firaun dan kaumnya).', FALSE, NULL, NULL, 385, 20, 154, 334, FALSE, 12, NULL),
(28, 6, 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', 'ونمكن لهم في الارض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون', NULL, 'And establish them in the land and show Pharaoh and [his minister] Hāmān and their soldiers through them that which they had feared.', 'Dan Kami hendak memberi mereka kedudukan yang kukuh di negeri itu, serta hendak memperlihatkan kepada Firaun dan Haman bersama-sama tentera mereka apa yang mereka bimbangkan dari golongan yang bertindas itu.', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 12, NULL),
(28, 7, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ ۖ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', 'واوحينا الى ام موسى ان ارضعيه فاذا خفت عليه فالقيه في اليم ولا تخافي ولا تحزني انا رادوه اليك وجاعلوه من المرسلين', NULL, 'And We inspired to the mother of Moses, "Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers."', 'Dan Kami ilhamkan kepada ibu Musa: “Susukanlah dia; dalam pada itu, jika engkau takutkan sesuatu bahaya mengenainya (dari angkara Firaun), maka (letakkanlah dia di dalam peti dan) lepaskanlah dia ke laut; dan janganlah engkau merasa bimbang dan jangan pula berdukacita; sesungguhnya Kami akan mengembalikannya kepadamu, dan Kami akan melantiknya menjadi salah seorang dari Rasul-rasul Kami.', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 22, NULL),
(28, 8, 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا ۗ إِنَّ فِرْعَوْنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا كَانُوا۟ خَـٰطِـِٔينَ', 'فالتقطه ال فرعون ليكون لهم عدوا وحزنا ان فرعون وهامان وجنودهما كانوا خاطئين', NULL, 'And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Hāmān and their soldiers were deliberate sinners.', 'Setelah itu dia dipungut oleh orang-orang Firaun; kesudahannya dia akan menjadi musuh dan menyebabkan dukacita bagi mereka; sesungguhnya Firaun dan Haman serta orang-orangnya adalah golongan yang bersalah.', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 13, NULL),
(28, 9, 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ ۖ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ', 'وقالت امرات فرعون قرت عين لي ولك لا تقتلوه عسى ان ينفعنا او نتخذه ولدا وهم لا يشعرون', NULL, 'And the wife of Pharaoh said, "[He will be] a comfort of the eye [i.e., pleasure] for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son." And they perceived not.', 'Dan (ketika melihat kanak-kanak itu) berkatalah isteri Firaun: “(Semoga ia menjadi) cahaya mata bagiku dan bagimu; janganlah kamu membunuhnya; mudah-mudahan ia berguna kepada kita, atau kita jadikan dia anak”. Padahal mereka tidak menyedari (kesudahannya).', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 18, NULL),
(28, 10, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَـٰرِغًا ۖ إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'واصبح فؤاد ام موسى فارغا ان كادت لتبدي به لولا ان ربطنا على قلبها لتكون من المؤمنين', NULL, 'And the heart of Moses'' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers.', 'Dan (sepeninggalannya) menjadilah hati ibu Musa kosong; sesungguhnya ia nyaris-nyaris menyatakan perihal anaknya itu dengan berterus-terang jika tidaklah Kami kuatkan hatinya (dengan perasaan sabar dan tenang tenteram), supaya tetaplah ia dari orang-orang yang percaya (akan janji Allah).', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 17, NULL),
(28, 11, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ ۖ فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ', 'وقالت لاخته قصيه فبصرت به عن جنب وهم لا يشعرون', NULL, 'And she said to his sister, "Follow him"; so she watched him from a distance while they perceived not.', 'Dan berkatalah ia kepada kakak Musa: “Pergilah cari khabar beritanya”. (Maka pergilah ia) lalu dilihatnya dari jauh sedang orang ramai tidak menyedarinya.', FALSE, NULL, NULL, 386, 20, 154, 334, FALSE, 10, NULL),
(28, 12, '۞ وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَـٰصِحُونَ', 'وحرمنا عليه المراضع من قبل فقالت هل ادلكم على اهل بيت يكفلونه لكم وهم له ناصحون', NULL, 'And We had prevented from him [all] wet nurses before, so she said, "Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?"', 'Dan Kami jadikan dia dari mulanya enggan menyusu kepada perempuan-perempuan yang hendak menyusukannya; (melihatkan halnya itu), kakaknya berkata: “Mahukah, aku tunjukkan kamu kepada penduduk sebuah rumah yang dapat memeliharanya untuk kamu, serta mereka tulus ikhlas kepadanya?”', FALSE, NULL, NULL, 386, 20, 155, 334, FALSE, 16, NULL),
(28, 13, 'فَرَدَدْنَـٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فرددناه الى امه كي تقر عينها ولا تحزن ولتعلم ان وعد الله حق ولكن اكثرهم لا يعلمون', NULL, 'So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allāh is true. But most of them [i.e., the people] do not know.', 'Maka (dengan jalan itu) Kami kembalikan dia kepada ibunya supaya tenang tenteram hatinya dan tidak berdukacita (disebabkan bercerai dengannya); dan supaya ia mengetahui bahawa janji Allah (untuk menyelamatkannya) adalah benar; akan tetapi kebanyakan mereka tidak mengetahui (yang demikian itu).', FALSE, NULL, NULL, 386, 20, 155, 334, FALSE, 17, NULL),
(28, 14, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ولما بلغ اشده واستوى اتيناه حكما وعلما وكذلك نجزي المحسنين', NULL, 'And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good.', 'Dan ketika Musa sampai ke peringkat umurnya yang cukup kekuatannya dan sempurna, Kami beri kepadanya kebijaksanaan serta ilmu pengetahuan; dan demikian Kami membalas orang-orang yang berusaha memperbaiki amalannya.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 10, NULL),
(28, 15, 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَـٰذَا مِن شِيعَتِهِۦ وَهَـٰذَا مِنْ عَدُوِّهِۦ ۖ فَٱسْتَغَـٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ ۖ قَالَ هَـٰذَا مِنْ عَمَلِ ٱلشَّيْطَـٰنِ ۖ إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ', 'ودخل المدينة على حين غفلة من اهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغاثه الذي من شيعته على الذي من عدوه فوكزه موسى فقضى عليه قال هذا من عمل الشيطان انه عدو مضل مبين', NULL, 'And he entered the city at a time of inattention by its people and found therein two men fighting: one from his faction and one from among his enemy. And the one from his faction called for help to him against the one from his enemy, so Moses struck him and [unintentionally] killed him. [Moses] said, "This is from the work of Satan. Indeed, he is a manifest, misleading enemy."', 'Dan masuklah ia ke bandar (Mesir) dalam masa penduduknya tidak menyedarinya, lalu didapatinya di situ dua orang lelaki sedang berkelahi, - seorang dari golongannya sendiri dan yang seorang lagi dari pihak musuhnya. Maka orang yang dari golongannya meminta tolong kepadanya melawan orang yang dari pihak musuhnya; Musa pun menumbuknya lalu menyebabkan orang itu mati. (pada saat itu) Musa berkata: “Ini adalah dari kerja Syaitan, sesungguhnya Syaitan itu musuh yang menyesatkan, yang nyata (angkaranya)”.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 38, NULL),
(28, 16, 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قال رب اني ظلمت نفسي فاغفر لي فغفر له انه هو الغفور الرحيم', NULL, 'He said, "My Lord, indeed I have wronged myself, so forgive me," and He forgave him. Indeed, He is the Forgiving, the Merciful.', 'Ia merayu (dengan sesalnya): “Wahai Tuhanku, sesungguhnya aku telah menganiaya diri sendiri; oleh itu ampunkanlah - apalah jua kiranya - akan dosaku”. (Maka Allah Taala menerima taubatnya) lalu mengampunkan dosanya; sesungguhnya Allah jualah Yang Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 13, NULL),
(28, 17, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ', 'قال رب بما انعمت علي فلن اكون ظهيرا للمجرمين', NULL, 'He said, "My Lord, for the favor You bestowed upon me, I will never be an assistant to the criminals."', 'Ia merayu lagi: “Wahai Tuhanku, demi nikmat-nikmat yang Engkau kurniakan kepadaku, (peliharalah daku) supaya aku tidak akan menjadi penyokong kepada golongan yang bersalah”.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 9, NULL),
(28, 18, 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ ۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ', 'فاصبح في المدينة خائفا يترقب فاذا الذي استنصره بالامس يستصرخه قال له موسى انك لغوي مبين', NULL, 'And he became inside the city fearful and anticipating [exposure], when suddenly the one who sought his help the previous day cried out to him [once again]. Moses said to him, "Indeed, you are an evident, [persistent] deviator."', 'Semenjak itu, tinggallah ia di bandar (Mesir) dalam keadaan cemas sambil memerhatikan (berita mengenai dirinya), maka tiba-tiba orang yang meminta pertolongan kepadanya semalam, memanggil meminta pertolongannya lagi. Musa berkata kepadanya: “Sesungguhnya engkau ini orang yang nyata sesatnya!”', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 16, NULL),
(28, 19, 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَـٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ ۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', 'فلما ان اراد ان يبطش بالذي هو عدو لهما قال يا موسى اتريد ان تقتلني كما قتلت نفسا بالامس ان تريد الا ان تكون جبارا في الارض وما تريد ان تكون من المصلحين', NULL, 'And when he wanted to strike the one who was an enemy to both of them, he said, "O Moses, do you intend to kill me as you killed someone yesterday? You only want to be a tyrant in the land and do not want to be of the amenders."', 'Maka ketika ia bersedia hendak menumbuk orang yang menjadi musuh bagi mereka berdua berkatalah orang itu: “Wahai Musa, adakah engkau hendak membunuhku sebagaimana engkau membunuh satu jiwa semalam? Sebenarnya engkau hanyalah hendak menjadi seorang yang kejam di bumi, dan tidaklah engkau hendak menjadi seorang pendamai”.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 32, NULL),
(28, 20, 'وَجَآءَ رَجُلٌ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَـٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّـٰصِحِينَ', 'وجاء رجل من اقصى المدينة يسعى قال يا موسى ان الملا ياتمرون بك ليقتلوك فاخرج اني لك من الناصحين', NULL, 'And a man came from the farthest end of the city, running. He said, "O Moses, indeed the eminent ones are conferring over you [intending] to kill you, so leave [the city]; indeed, I am to you of the sincere advisors."', 'Dan datanglah seorang lelaki dari hujung bandar itu dengan berlari, (lalu menyampaikan berita) dengan berkata: “Wahai Musa, sesungguhnya pegawai-pegawai Firaun sedang mengadakan pakatan terhadapmu, mereka hendak membunuhmu; oleh itu pergilah dari sini, sesungguhnya aku adalah pemberi nasihat secara ikhlas kepadamu”.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 18, NULL),
(28, 21, 'فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فَخَرَجَ مِنْهَا خَائِفًا يَتَرَقَّبُ قَالَ رَبِّ نَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ', NULL, 'So he left it, fearful and anticipating [apprehension]. He said, "My Lord, save me from the wrongdoing people."', 'Musa pun keluarlah dari negeri itu dalam keadaan cemas sambil memerhatikan (berita mengenai dirinya) serta berdoa dengan berkata: “Wahai Tuhanku, selamatkanlah daku dari kaum yang zalim”.', FALSE, NULL, NULL, 387, 20, 155, 335, FALSE, 0, NULL),
(28, 22, 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', 'وَلَمَّا تَوَجَّهَ تِلْقَاءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّي أَن يَهْدِيَنِي سَوَاءَ السَّبِيلِ', NULL, 'And when he directed himself toward Madyan, he said, "Perhaps my Lord will guide me to the sound way."', 'Dan setelah ia (meninggalkan Mesir dalam perjalanan) menuju ke negeri Madyan, berdoalah ia dengan berkata: “Mudah-mudahan Tuhanku menunjukkan jalan yang benar kepadaku,”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 23, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ قَالَ مَا خَطْبُكُمَا قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ وَأَبُونَا شَيْخٌ كَبِيرٌ', 'وَلَمَّا وَرَدَ مَاءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ النَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ امْرَأَتَيْنِ تَذُودَانِ قَالَ مَا خَطْبُكُمَا قَالَتَا لَا نَسْقِي حَتَّىٰ يُصْدِرَ الرِّعَاءُ وَأَبُونَا شَيْخٌ كَبِيرٌ', NULL, 'And when he came to the water [i.e., well] of Madyan, he found there a crowd of people watering [their flocks], and he found aside from them two women holding back [their flocks]. He said, "What is your circumstance?" They said, "We do not water until the shepherds dispatch [their flocks]; and our father is an old man."', 'Dan ketika dia sampai di telaga air negeri Madyan, ia dapati di situ sekumpulan orang-orang lelaki sedang memberi minum (binatang ternak masing-masing), dan ia juga dapati di sebelah mereka dua perempuan yang sedang menahan kambing-kambingnya. dia bertanya: “Apa hal kamu berdua?” Mereka menjawab: “Kami tidak memberi minum (kambing-kambing kami) sehingga pengembala-pengembala itu membawa balik binatang ternak masing-masing; dan bapa kami seorang yang terlalu tua umurnya”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 24, 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ', 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰ إِلَى الظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ', NULL, 'So he watered [their flocks] for them; then he went back to the shade and said, "My Lord, indeed I am, for whatever good You would send down to me, in need."', 'Maka Musa pun memberi minum kepada binatang-binatang ternak mereka, kemudian ia pergi ke tempat teduh lalu berdoa dengan berkata: “Wahai Tuhanku, sesungguhnya aku sangat berhajat kepada sebarang rezeki pemberian yang Engkau berikan”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 25, 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'فَجَاءَتْهُ إِحْدَاهُمَا تَمْشِي عَلَى اسْتِحْيَاءٍ قَالَتْ إِنَّ أَبِي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا فَلَمَّا جَاءَهُ وَقَصَّ عَلَيْهِ الْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ الْقَوْمِ الظَّالِمِينَ', NULL, 'Then one of the two women came to him walking with shyness. She said, "Indeed, my father invites you that he may reward you for having watered for us." So when he came to him and related to him the story, he said, "Fear not. You have escaped from the wrongdoing people."', 'Kemudian salah seorang dari perempuan dua beradik itu datang mendapatkannya dengan berjalan dalam keadaan tersipu-sipu sambil berkata: “Sebenarnya bapaku menjemputmu untuk membalas budimu memberi minum binatang ternak kami”. Maka ketika Musa datang mendapatkannya dan menceritakan kepadanya kisah-kisah kejadian yang berlaku (mengenai dirinya) berkatalah orang tua itu kepadanya: “Janganlah engkau bimbang, engkau telah selamat dari kaum yang zalim itu”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 26, 'قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ ٱسْتَـْٔجِرْهُ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', 'قَالَتْ إِحْدَاهُمَا يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ', NULL, 'One of the women said, "O my father, hire him. Indeed, the best one you can hire is the strong and the trustworthy."', 'Salah seorang di antara perempuan yang berdua itu berkata: “Wahai ayah, ambilah dia menjadi orang upahan (mengembala kambing kita), sesungguhnya sebaik-baik orang yang ayah ambil bekerja ialah orang yang kuat, lagi amanah”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 27, 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ', 'قَالَ إِنِّي أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ابْنَتَيَّ هَاتَيْنِ عَلَىٰ أَن تَأْجُرَنِي ثَمَانِيَ حِجَجٍ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ وَمَا أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِي إِن شَاءَ اللَّهُ مِنَ الصَّالِحِينَ', NULL, 'He said, "Indeed, I wish to wed you one of these, my two daughters, on [the condition] that you serve me for eight years; but if you complete ten, it will be [as a favor] from you. And I do not wish to put you in difficulty. You will find me, if Allāh wills, from among the righteous."', 'Bapa perempuan itu berkata (kepada Musa): “Aku hendak mengahwinkanmu dengan salah seorang dari dua anak perempuanku ini, dengan syarat bahawa engkau bekerja denganku selama delapan tahun; dalam pada itu, jika engkau genapkan menjadi sepuluh tahun, maka yang demikian itu adalah dari kerelaanmu sendiri. Dan (ingatlah) aku tidak bertujuan hendak menyusahkanmu; engkau akan dapati aku Insya Allah, dari orang-orang yang baik layanannya”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 28, 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'قَالَ ذَٰلِكَ بَيْنِي وَبَيْنَكَ أَيَّمَا الْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَانَ عَلَيَّ وَاللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', NULL, '[Moses] said, "That is [established] between me and you. Whichever of the two terms I complete - there is no injustice to me, and Allāh, over what we say, is Witness."', 'Musa menjawab: “Perjanjian itu adalah antaraku denganmu (tetap dihormati bersama); yang mana sahaja dari dua tempoh itu yang aku tunaikan, maka janganlah hendaknya aku disalahkan. Dan Allah jualah menjadi Pengawas terhadap apa yang kita katakan itu”.', FALSE, NULL, NULL, 388, 20, 155, 336, FALSE, 0, NULL),
(28, 29, 'فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', 'فَلَمَّا قَضَىٰ مُوسَى الْأَجَلَ وَسَارَ بِأَهْلِهِ آنَسَ مِن جَانِبِ الطُّورِ نَارًا قَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ النَّارِ لَعَلَّكُمْ تَصْطَلُونَ', NULL, 'And when Moses had completed the term and was traveling with his family, he perceived from the direction of the mount a fire. He said to his family, "Stay here; indeed, I have perceived a fire. Perhaps I will bring you from there [some] information or burning wood from the fire that you may warm yourselves."', 'Setelah Musa menyempurnakan tempoh kerjanya itu dan (mendapat izin) berjalan dengan isterinya (kembali ke Mesir), ia melihat (dalam perjalanannya itu) api dari sebelah Gunung Tursina. (Ketika itu) berkatalah ia kepada isterinya: “Berhentilah; sesungguhnya aku ada melihat api, semoga aku dapat membawa kepada kamu sesuatu berita dari situ, atau sepuntung dari api itu, supaya kamu dapat memanaskan diri”.', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 30, 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'فَلَمَّا أَتَاهَا نُودِيَ مِن شَاطِئِ الْوَادِ الْأَيْمَنِ فِي الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ أَن يَا مُوسَىٰ إِنِّي أَنَا اللَّهُ رَبُّ الْعَالَمِينَ', NULL, 'But when he came to it, he was called from the right side of the valley in a blessed spot - from the tree, "O Moses, indeed I am Allāh, Lord of the worlds."', 'Maka ketika ia sampai ke tempat api itu, (kedengaran) ia diseru dari tepi lembah yang di sebelah kanan, di tempat yang dilimpahi berkat, dari arah pohon kayu (yang ada di situ): “Wahai Musa, sesungguhnya Akulah Allah Tuhan sekalian alam. (Sesungguhnya api itu adalah sebagai satu isyarat yang didatangkan oleh Allah untuk menarik perhatian Musa ke tempat itu dan bukannya zat Allah, Wallahu A''lam)', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 31, 'وَأَنْ أَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ ٱلْـَٔامِنِينَ', 'وَأَنْ أَلْقِ عَصَاكَ فَلَمَّا رَآهَا تَهْتَزُّ كَأَنَّهَا جَانٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَا مُوسَىٰ أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ الْآمِنِينَ', NULL, 'And [he was told], "Throw down your staff." But when he saw it writhing as if it was a snake, he turned in flight and did not return. [Allāh said], "O Moses, approach and fear not. Indeed, you are of the secure.', '“Dan (sekarang) campakkanlah tongkatmu”. (Ia pun mencampaknya), maka apabila ia melihat tongkatnya itu (menjadi seekor ular besar) bergerak cepat tangkas, seolah-olah seekor ular kecil, berpalinglah ia melarikan diri dan tidak menoleh lagi. (Lalu ia diseru): “Wahai Musa, datanglah kemari dan janganlah engkau takut. Sesungguhnya engkau dari orang-orang yang beroleh aman.', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 32, 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'اسْلُكْ يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ وَاضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ فَذَانِكَ بُرْهَانَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ إِنَّهُمْ كَانُوا قَوْمًا فَاسِقِينَ', NULL, 'Insert your hand into the opening of your garment; it will come out white, without disease. And draw in your arm close to you [as prevention] from fear, for those are two proofs from your Lord to Pharaoh and his establishment. Indeed, they have been a people defiantly disobedient."', '“Masukkanlah tanganmu melalui belahan dada bajumu, nescaya keluarlah ia putih bersinar-sinar dengan tiada cacat; dan kepitlah tanganmu di celah ketiakmu ketika merasa takut (nescaya hilanglah takutmu). Yang demikian adalah dua bukti dari Tuhanmu (untuk engkau menunjukkannya) kepada Firaun dan kaumnya. Sesungguhnya mereka itu adalah kaum yang fasik - derhaka”', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 33, 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', 'قَالَ رَبِّ إِنِّي قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', NULL, 'He said, "My Lord, indeed I killed from among them someone, and I fear they will kill me.', 'Nabi Musa merayu dengan berkata: “Wahai Tuhanku, bahawa aku telah membunuh seorang dari kalangan mereka; oleh itu aku takut mereka akan membunuhku”', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 34, 'وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِيَ رِدْءًا يُصَدِّقُنِي إِنِّي أَخَافُ أَن يُكَذِّبُونِ', NULL, 'And my brother Aaron is more fluent than me in tongue, so send him with me as support, verifying me. Indeed, I fear that they will deny me."', '“Dan saudaraku - Harun, ia lebih fasih lidahnya daripadaku, maka utuslah dia bersama-samaku sebagai penyokong yang mengakui kebenaranku; sesungguhnya aku bimbang bahawa mereka akan mendustakan daku”.', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا بِـَٔايَٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَٰلِبُونَ', 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَانًا فَلَا يَصِلُونَ إِلَيْكُمَا بِآيَاتِنَا أَنتُمَا وَمَنِ اتَّبَعَكُمَا الْغَالِبُونَ', NULL, '[Allāh] said, "We will strengthen your arm through your brother and grant you both supremacy so they will not reach you. [It will be] through Our signs; you and those who follow you will be the predominant."', 'Allah berfirman: “Kami akan menguatkan tenaga dan daya-usahamu dengan saudaramu (Harun), dan Kami akan memberikan kuasa kemenangan kepada kamu berdua oleh itu mereka tidak akan sampai kepada maksud membahayakan atau mengalahkan kamu. Dengan membawa ayat-ayat keterangan Kami itu, kamu berdua serta pengikut-pengikut kamu akan menang”.', FALSE, NULL, NULL, 389, 20, 156, 337, FALSE, 0, NULL),
(28, 36, 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'فَلَمَّا جَاءَهُم مُّوسَىٰ بِآيَاتِنَا بَيِّنَاتٍ قَالُوا مَا هَٰذَا إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِي آبَائِنَا الْأَوَّلِينَ', NULL, 'But when Moses came to them with Our signs as clear evidences, they said, "This is not except invented magic, and we have not heard of this [religion] among our forefathers."', 'Setelah Nabi Musa datang kepada Firaun dan kaumnya dengan membawa ayat-ayat keterangan Kami yang terang nyata, mereka berkata: “Apa yang engkau bawa ini hanyalah sihir yang dibuat-buat, dan kami tidak pernah mendengar tentang perkara ini dalam kalangan datuk nenek kami yang telah lalu”.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 37, 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'وَقَالَ مُوسَىٰ رَبِّي أَعْلَمُ بِمَن جَاءَ بِالْهُدَىٰ مِنْ عِندِهِ وَمَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ', NULL, 'And Moses said, "My Lord is more knowing [than we or you] of who has come with guidance from Him and to whom will be succession in the home. Indeed, wrongdoers do not succeed."', 'Dan (bagi menjawabnya) Nabi Musa berkata: “Tuhanku lebih mengetahui siapakah yang membawa hidayah petunjuk dari sisiNya dan siapa yang akan beroleh kesudahan yang baik di dunia ini. Sesungguhnya orang-orang yang zalim tidak akan berjaya”.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 38, 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَٰذِبِينَ', 'وَقَالَ فِرْعَوْنُ يَا أَيُّهَا الْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِي فَأَوْقِدْ لِي يَا هَامَانُ عَلَى الطِّينِ فَاجْعَل لِّي صَرْحًا لَّعَلِّي أَطَّلِعُ إِلَىٰ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُ مِنَ الْكَاذِبِينَ', NULL, 'And Pharaoh said, "O eminent ones, I have not known you to have a god other than me. Then ignite for me, O Hāmān, [a fire] upon the clay and make for me a tower that I may look at the God of Moses. And indeed, I do think he is among the liars."', 'Dan Firaun pula berkata: “Wahai orang-orangku, aku tidak mengetahui ada bagi kamu sebarang tuhan yang lain daripadaku; oleh itu, wahai Haman, bakarkanlah untukku batu-bata, serta binalah untukku bangunan yang tinggi, supaya aku naik melihat Tuhan Musa (yang dikatakannya itu); dan sesungguhnya aku percaya adalah Musa dari orang-orang yang berdusta”.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 39, 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', 'وَاسْتَكْبَرَ هُوَ وَجُنُودُهُ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَظَنُّوا أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', NULL, 'And he was arrogant, he and his soldiers, in the land, without right, and they thought that they would not be returned to Us.', 'Dan berlaku sombong takburlah Firaun dan tenteranya di negeri itu dengan tiada alasan yang benar, dan mereka menyangka bahawa mereka tidak akan dikembalikan kepada Kami.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'فَأَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّ فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الظَّالِمِينَ', NULL, 'So We took him and his soldiers and threw them into the sea. So see how was the end of the wrongdoers.', 'Dengan sebab itu Kami mengepungnya bersama-sama tenteranya serta Kami humbankan mereka ke dalam laut; maka perhatikanlah bagaimana buruknya kesudahan orang-orang yang zalim.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 41, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى ٱلنَّارِ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ', 'وَجَعَلْنَاهُمْ أَئِمَّةً يَدْعُونَ إِلَى النَّارِ وَيَوْمَ الْقِيَامَةِ لَا يُنصَرُونَ', NULL, 'And We made them leaders inviting to the Fire, and on the Day of Resurrection they will not be helped.', 'Dan Kami jadikan mereka ketua-ketua (dalam kesesatan) yang mengajak ke neraka (dengan kekufurannya), dan pada hari kiamat pula mereka tidak mendapat sebarang pertolongan.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 42, 'وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', 'وَأَتْبَعْنَاهُمْ فِي هَٰذِهِ الدُّنْيَا لَعْنَةً وَيَوْمَ الْقِيَامَةِ هُم مِّنَ الْمَقْبُوحِينَ', NULL, 'And We caused to overtake them in this world a curse, and on the Day of Resurrection they will be of the despised.', 'Dan Kami iringi mereka dengan laknat di dunia ini, dan pada hari kiamat pula adalah mereka dari orang-orang yang tersingkir (dari rahmat Kami) dengan sehina-hinanya.', FALSE, NULL, NULL, 390, 20, 156, 337, FALSE, 0, NULL),
(28, 43, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ مِن بَعْدِ مَا أَهْلَكْنَا الْقُرُونَ الْأُولَىٰ بَصَائِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And We gave Moses the Scripture, after We had destroyed the former generations, as enlightenment for the people and guidance and mercy that they might be reminded.', 'Dan demi sesungguhnya, Kami berikan kepada Nabi Musa Kitab Taurat sesudah Kami binasakan kaum-kaum yang telah lalu, untuk membuka hati dan menjadi hidayah petunjuk serta membawa rahmat, semoga mereka beringat.', FALSE, NULL, NULL, 390, 20, 156, 338, FALSE, 0, NULL),
(28, 44, 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ', 'وَمَا كُنتَ بِجَانِبِ الْغَرْبِيِّ إِذْ قَضَيْنَا إِلَىٰ مُوسَى الْأَمْرَ وَمَا كُنتَ مِنَ الشَّاهِدِينَ', NULL, 'And you, [O Muḥammad], were not on the western side [of the mount] when We revealed to Moses the command, and you were not among the witnesses [to that].', 'Dan engkau (wahai Muhammad) tidak ada di sebelah barat (tempat Nabi Musa menerima wahyu) ketika Kami sempurnakan penyerahan Kitab Taurat kepadanya, dan engkau juga tidak termasuk dalam golongan yang menyaksikan peristiwa itu.', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 45, 'وَلَٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', 'وَلَٰكِنَّا أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ الْعُمُرُ وَمَا كُنتَ ثَاوِيًا فِي أَهْلِ مَدْيَنَ تَتْلُو عَلَيْهِمْ آيَاتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', NULL, 'But We produced [many] generations [after Moses], and prolonged was their duration. And you were not a resident among the people of Madyan, reciting to them Our verses, but We were senders [of this message].', 'Akan tetapi (engkau hanya mengetahui kisah itu dengan jalan Kami memberi wahyu kenabian kepadamu disebabkan) Kami telah mengadakan beberapa umat (dari zaman Nabi Musa hingga ke zamanmu) sampai berlanjutanlah masa yang mereka lalui (serta kucar-kacirlah ugama yang mereka anuti). Dan engkau pula tidak pernah tinggal bersama-sama penduduk negeri Madyan membaca dan mempelajari dari mereka ayat-ayat keterangan Kami (tentang hal Nabi Musa di sana), tetapi Kamilah yang mengutusmu (menjadi Rasul dan memberi wahyu kepadamu mengenai hal itu).', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 46, 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'وَمَا كُنتَ بِجَانِبِ الطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And you were not at the side of the mount when We called [Moses] but [were sent] as a mercy from your Lord to warn a people to whom no warner had come before you that they might be reminded.', 'Dan engkau juga tidak berada dekat Gunung Tursina ketika Kami menyeru (Nabi Musa dan memberi wahyu kepadanya dahulu), tetapi (diturunkan) rahmat (Al-Quran) dari Tuhanmu (menerangkan Kisah itu) supaya engkau memberi amaran kepada kaum (mu) yang telah lama tidak didatangi sebarang Rasul pemberi amaran sebelummu, semoga mereka beroleh pengajaran (serta insaf mematuhinya).', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 47, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'وَلَوْلَا أَن تُصِيبَهُم مُّصِيبَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ وَنَكُونَ مِنَ الْمُؤْمِنِينَ', NULL, 'And if not that a disaster should strike them for what their hands put forth [of sins] and they would say, "Our Lord, why did You not send us a messenger so we could have followed Your verses and been among the believers?"...', 'Dan kalau tidaklah orang-orang musyrik itu akan berkata - semasa mereka ditimpa bala bencana disebabkan perbuatan kufur dan maksiat yang mereka lakukan: “Wahai Tuhan kami, mengapa Engkau tidak mengutuskan kepada Kami seorang Rasul supaya kami menurut ayat-ayat keteranganMu (yang dibawanya), dan supaya kami menjadi dari orang-orang yang beriman,” (tentulah engkau wahai Muhammad tidak diutuskan kepada mereka, bahkan Kami terus menyeksa mereka).', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 48, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ قَالُوا۟ سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّ كَٰفِرُونَ', 'فَلَمَّا جَاءَهُمُ الْحَقُّ مِنْ عِندِنَا قَالُوا لَوْلَا أُوتِيَ مِثْلَ مَا أُوتِيَ مُوسَىٰ أَوَلَمْ يَكْفُرُوا بِمَا أُوتِيَ مُوسَىٰ مِن قَبْلُ قَالُوا سِحْرَانِ تَظَاهَرَا وَقَالُوا إِنَّا بِكُلٍّ كَافِرُونَ', NULL, 'But when the truth came to them from Us, they said, "Why was he not given like that which was given to Moses?" Did they not disbelieve in that which was given to Moses before? They said, "[They are but] two works of magic supporting each other, and indeed we are, in both, disbelievers."', 'Maka ketika datang kepada mereka kebenaran (Al-Quran) dari sisi Kami, mereka berkata pula: “Hendaknya (Muhammad) diberi (Kitab ugama yang diturunkan dengan sekaligus) sebagaimana Kitab Taurat yang diberikan kepada Musa”. Bukankah mereka dahulu telah kufur ingkar akan apa yang diberikan kepada Nabi Musa? Mereka berkata lagi: “Kedua-duanya (Al-Quran dan Taurat) itu ialah sihir yang saling membantu (yang satu menyokong yang lain). “Dan mereka berkata pula: “Sesungguhnya kami kufur ingkar terhadap Kitab-kitab itu semuanya!”', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 49, 'قُلْ فَأْتُوا۟ بِكِتَٰبٍ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ', 'قُلْ فَأْتُوا بِكِتَابٍ مِّنْ عِندِ اللَّهِ هُوَ أَهْدَىٰ مِنْهُمَا أَتَّبِعْهُ إِن كُنتُمْ صَادِقِينَ', NULL, 'Say, "Then bring a scripture from Allāh which is more guiding than either of them that I may follow it, if you should be truthful."', 'Katakanlah (wahai Muhammad): “Kalau demikianlah sikap kamu maka bawalah sebuah Kitab dari sisi Allah yang dapat memberi panduan lebih daripada keduanya, supaya aku menurutnya. (Bawalah dia) jika betul kamu orang-orang yang benar”.', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 50, 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'فَإِن لَّمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِّنَ اللَّهِ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ', NULL, 'But if they do not respond to you - then know that they only follow their [own] desires. And who is more astray than one who follows his desire without guidance from Allāh? Indeed, Allāh does not guide the wrongdoing people.', 'Kemudian, kalau mereka tidak dapat menerima cabaranmu (wahai Muhammad), maka ketahuilah, sesungguhnya mereka hanyalah menurut hawa nafsu mereka; dan tidak ada yang lebih sesat daripada orang yang menurut hawa nafsunya dengan tidak berdasarkan hidayah petunjuk dari Allah. Sesungguhnya Allah tidak memberi pimpinan kepada kaum yang zalim (yang berdegil dalam keingkarannya).', FALSE, NULL, NULL, 391, 20, 156, 338, FALSE, 0, NULL),
(28, 51, 'وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And We have [repeatedly] conveyed to them the word [i.e., the Qur’ān] that they might be reminded.', 'Dan demi sesungguhnya Kami telah hubungkan turunnya firman-firman Kami (Al-Quran) dengan berturut-turut kepada mereka, supaya mereka beroleh peringatan (lalu beriman).', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 52, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', 'الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ مِن قَبْلِهِ هُم بِهِ يُؤْمِنُونَ', NULL, 'Those to whom We gave the Scripture before it - they are believers in it.', 'Orang-orang yang Kami beri Kitab sebelum turunnya Al-Quran, mereka beriman kepadanya.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 53, 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوا آمَنَّا بِهِ إِنَّهُ الْحَقُّ مِن رَّبِّنَا إِنَّا كُنَّا مِن قَبْلِهِ مُسْلِمِينَ', NULL, 'And when it is recited to them, they say, "We have believed in it; indeed, it is the truth from our Lord. Indeed we were, [even] before it, Muslims [i.e., submitting to Allāh]."', 'Dan apabila Al-Quran itu dibacakan kepada mereka; mereka, berkata: “Kami beriman kepadanya, sesungguhnya ia adalah perkara yang betul benar dari Tuhan kami; sesungguhnya kami sebelum ia diturunkan, telahpun mematuhinya”.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 54, 'أُو۟لَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'أُولَٰئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ', NULL, 'Those will be given their reward twice for what they patiently endured and [because] they avert evil through good, and from what We have provided them they spend.', 'Mereka itu akan beroleh pahala dua kali disebabkan kesabaran mereka; dan juga kerana mereka menolak kejahatan dengan kebaikan, dan mereka menderma dari apa yang Kami kurniakan kepada mereka.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 55, 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَٰهِلِينَ', 'وَإِذَا سَمِعُوا اللَّغْوَ أَعْرَضُوا عَنْهُ وَقَالُوا لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ سَلَامٌ عَلَيْكُمْ لَا نَبْتَغِي الْجَاهِلِينَ', NULL, 'And when they hear ill speech, they turn away from it and say, "For us are our deeds, and for you are your deeds. Peace will be upon you; we seek not the ignorant."', 'Dan apabila mereka mendengar perkataan yang sia-sia, mereka berpaling daripadanya sambil berkata: “Bagi kami amal kami dan bagi kamu pula amal kamu; selamat tinggallah kamu; kami tidak ingin berdamping dengan orang-orang yang jahil”.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 56, 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ', NULL, 'Indeed, [O Muḥammad], you do not guide whom you like, but Allāh guides whom He wills. And He is most knowing of the [rightly] guided.', 'Sesungguhnya engkau (wahai Muhammad) tidak berkuasa memberi hidayah petunjuk kepada sesiapa yang engkau kasihi (supaya ia menerima Islam), tetapi Allah jualah yang berkuasa memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan Dia lah jua yang lebih mengetahui akan orang-orang yang (ada persediaan untuk) mendapat hidayah petunjuk (kepada memeluk Islam).', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 57, 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وَقَالُوا إِن نَّتَّبِعِ الْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَا أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا آمِنًا يُجْبَىٰ إِلَيْهِ ثَمَرَاتُ كُلِّ شَيْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'And they [i.e., the Quraysh] say, "If we were to follow the guidance with you, we would be swept from our land." Have We not established for them a safe sanctuary to which are brought the fruits of all things as provision from Us? But most of them do not know.', 'Dan mereka (yang kafir) berkata: “Kalau kami menyertaimu menurut petunjuk yang engkau bawa itu, nescaya kami dengan serta merta ditangkap dan diusir dari negeri kami (oleh golongan yang menentang)”. Mengapa mereka (berkata demikian)? Bukankah kami telah melindungi mereka dan menjadikan (negeri Makkah) tempat tinggal mereka sebagai tanah suci yang aman, yang dibawa kepadanya hasil tanaman dari segala jenis, sebagai rezeki pemberian dari sisi Kami? (Benar, Kami telah menjadikan semuanya itu), tetapi kebanyakan mereka tidak memikirkan perkara itu untuk mengetahuinya (serta bersyukur).', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 58, 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًا وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍ بَطِرَتْ مَعِيشَتَهَا فَتِلْكَ مَسَاكِنُهُمْ لَمْ تُسْكَن مِّن بَعْدِهِمْ إِلَّا قَلِيلًا وَكُنَّا نَحْنُ الْوَارِثِينَ', NULL, 'And how many a city have We destroyed that was insolent in its [way of] living, and those are their dwellings which have not been inhabited after them except briefly. And it is We who were the inheritors.', 'Dan berapa banyak Kami binasakan negeri-negeri yang penduduknya telah berlaku sombong dan tidak bersyukur dalam kehidupannya (yang serba mewah dan senang lenang). Maka itulah dia tempat-tempat tinggal mereka terbiar tidak didiami orang sesudah mereka (dibinasakan), kecuali sedikit sahaja dan sesungguhnya Kamilah yang mewarisi mereka.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ', 'وَمَا كَانَ رَبُّكَ مُهْلِكَ الْقُرَىٰ حَتَّىٰ يَبْعَثَ فِي أُمِّهَا رَسُولًا يَتْلُو عَلَيْهِمْ آيَاتِنَا وَمَا كُنَّا مُهْلِكِي الْقُرَىٰ إِلَّا وَأَهْلُهَا ظَالِمُونَ', NULL, 'And never would your Lord have destroyed the cities until He had sent to their mother [i.e., principal city] a messenger reciting to them Our verses. And We would not destroy the cities except while their people were wrongdoers.', 'Dan tidaklah menjadi kebiasaan Tuhanmu membinasakan mana-mana negeri sebelum Ia mengutus ke ibu negeri itu seorang Rasul yang akan membacakan kepada penduduknya ayat-ayat keterangan Kami; dan tidaklah menjadi kebiasaan Kami membinasakan mana-mana negeri melainkan setelah penduduknya berlaku zalim.', FALSE, NULL, NULL, 392, 20, 157, 339, FALSE, 0, NULL),
(28, 60, 'وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰٓ أَفَلَا تَعْقِلُونَ', 'وَمَا أُوتِيتُم مِّن شَيْءٍ فَمَتَاعُ الْحَيَاةِ الدُّنْيَا وَزِينَتُهَا وَمَا عِندَ اللَّهِ خَيْرٌ وَأَبْقَىٰ أَفَلَا تَعْقِلُونَ', NULL, 'And whatever thing you [people] have been given - it is [only for] the enjoyment of worldly life and its adornment. And what is with Allāh is better and more lasting; so will you not use reason?', 'Dan apa jua (harta benda dan lain-lainnya) yang diberikan kepada kamu, maka adalah ia merupakan kesenangan hidup di dunia dan perhiasannya; dalam pada itu, apa jua yang ada di sisi Allah (yang disediakan untuk orang-orang yang beriman dan taat) adalah ia lebih baik dan lebih kekal; maka mengapa kamu tidak mahu memahaminya?', FALSE, NULL, NULL, 393, 20, 157, 339, FALSE, 0, NULL),
(28, 61, 'أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَٰمَةِ مِنَ ٱلْمُحْضَرِينَ', 'أَفَمَن وَعَدْنَاهُ وَعْدًا حَسَنًا فَهُوَ لَاقِيهِ كَمَن مَّتَّعْنَاهُ مَتَاعَ الْحَيَاةِ الدُّنْيَا ثُمَّ هُوَ يَوْمَ الْقِيَامَةِ مِنَ الْمُحْضَرِينَ', NULL, 'Then is he whom We have promised a good promise which he will meet [i.e., obtain] like he for whom We provided enjoyment of worldly life [but] then he is, on the Day of Resurrection, among those presented [for punishment in Hell]?', '(Jika sudah diketahui yang demikian) maka adakah orang yang Kami janjikan kepadanya janji yang baik (balasan Syurga) lalu ia mendapatnya, sama seperti orang yang kami kurniakan menikmati kesenangan hidup di dunia kemudian ia pada hari kiamat termasuk dalam golongan yang dibawa (untuk menerima azab neraka)?', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 62, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ', NULL, 'And [warn of] the Day He will call them and say, "Where are My ''partners'' which you used to claim?"', 'Dan pada hari (kiamat itu) Allah menyeru mereka lalu bertanya: “Mana dia sekutu-sekutuKu, yang kamu anggap mereka (menjadi tuhan dan dapat memberikan pertolongan)?”', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 63, 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا تَبَرَّأْنَآ إِلَيْكَ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', 'قَالَ الَّذِينَ حَقَّ عَلَيْهِمُ الْقَوْلُ رَبَّنَا هَٰؤُلَاءِ الَّذِينَ أَغْوَيْنَا أَغْوَيْنَاهُمْ كَمَا غَوَيْنَا تَبَرَّأْنَا إِلَيْكَ مَا كَانُوا إِيَّانَا يَعْبُدُونَ', NULL, 'Those upon whom the word will have come into effect will say, "Our Lord, these are the ones we led to error. We led them to error just as we were in error. We declare our disassociation [from them] to You. They did not used to worship [i.e., obey] us."', 'Mereka yang berhak menerima hukuman (azab neraka) berkata: “Wahai Tuhan kami, inilah mereka yang kami menyebabkan kesesatannya, kami menyebabkan mereka sesat (dengan pilihan mereka sendiri) sebagaimana kami telah sesat (dengan pilihan kami sendiri); (dengan ini) kami mengakui kepadaMu bahawa kami berlepas diri (dari kekufuran mereka). Bukanlah Kami yang mereka puja dan taati, (bahkan mereka hanya memuja dan mentaati hawa nafsu mereka sendiri)”.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 64, 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', 'وَقِيلَ ادْعُوا شُرَكَاءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا لَهُمْ وَرَأَوُا الْعَذَابَ لَوْ أَنَّهُمْ كَانُوا يَهْتَدُونَ', NULL, 'And it will be said, "Invoke your ''partners,''" and they will invoke them; but they will not respond to them, and they will see the punishment. If only they had followed guidance!', 'Dan dikatakan (kepada mereka): Panggilah makhluk-makhluk dan benda-benda yang kamu jadikan sekutu Allah (untuk menolong kamu)”. lalu mereka memanggilnya, tetapi makhluk-makhluk dan benda-benda itu tidak menyahut panggilan mereka; dan mereka tetap melihat azab (dengan merasa sesal) serta bercita-cita kalaulah mereka di dunia dahulu menurut petunjuk.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 65, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَا أَجَبْتُمُ الْمُرْسَلِينَ', NULL, 'And [mention] the Day He will call them and say, "What did you answer the messengers?"', 'Dan pada hari (kiamat itu) Allah menyeru mereka lalu bertanya: “Apa jawab kamu kepada Rasul-rasul yang diutus kepada kamu dahulu?', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 66, 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ', 'فَعَمِيَتْ عَلَيْهِمُ الْأَنبَاءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَاءَلُونَ', NULL, 'But the information will be unapparent to them that Day, so they will not [be able to] ask one another.', 'Maka gelaplah kepada mereka, pada hari itu, segala khabar berita dan peristiwa (yang telah lalu), serta menjadilah mereka tidak dapat hendak bertanya-tanyaan sesama sendiri.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 67, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', 'فَأَمَّا مَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا فَعَسَىٰ أَن يَكُونَ مِنَ الْمُفْلِحِينَ', NULL, 'But as for one who had repented, believed, and done righteousness, it is expected [i.e., promised by Allāh] that he will be among the successful.', '(Demikianlah akibat orang-orang derhaka), adapun orang yang bertaubat dan beriman serta beramal soleh, maka semoga akan menjadilah ia dari orang-orang yang berjaya.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ سُبْحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'وَرَبُّكَ يَخْلُقُ مَا يَشَاءُ وَيَخْتَارُ مَا كَانَ لَهُمُ الْخِيَرَةُ سُبْحَانَ اللَّهِ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ', NULL, 'And your Lord creates what He wills and chooses; not for them was the choice. Exalted is Allāh and high above what they associate with Him.', 'Dan Tuhanmu menciptakan apa yang dirancangkan berlakunya, dan Dia lah juga yang memilih (satu-satu dari makhlukNya untuk sesuatu tugas atau keutamaan dan kemuliaan); tidaklah layak dan tidaklah berhak bagi sesiapapun memilih (selain dari pilihan Allah). Maha Suci Allah dan Maha Tinggilah keadaanNya dari apa yang mereka sekutukan denganNya.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', NULL, 'And your Lord knows what their breasts conceal and what they declare.', 'Dan Tuhanmu mengetahui akan apa yang terpendam dalam hati mereka dan apa yang mereka zahirkan.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 70, 'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْـَٔاخِرَةِ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'وَهُوَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ لَهُ الْحَمْدُ فِي الْأُولَىٰ وَالْآخِرَةِ وَلَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And He is Allāh; there is no deity except Him. To Him is [due all] praise in the first [life] and the Hereafter. And His is the [final] decision, and to Him you will be returned.', 'Dan Dia lah Allah tiada Tuhan melainkan Dia. Segala puji tertentu bagiNya, di dunia dan di akhirat; dan hanyalah Dia yang berkuasa menghukum, serta kepadaNyalah kamu semua dikembalikan.', FALSE, NULL, NULL, 393, 20, 157, 340, FALSE, 0, NULL),
(28, 71, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ أَفَلَا تَسْمَعُونَ', 'قُلْ أَرَأَيْتُمْ إِن جَعَلَ اللَّهُ عَلَيْكُمُ اللَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ الْقِيَامَةِ مَنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِضِيَاءٍ أَفَلَا تَسْمَعُونَ', NULL, 'Say, "Have you considered: if Allāh should make for you the night continuous until the Day of Resurrection, what deity other than Allāh could bring you light? Then will you not hear?"', 'Katakanlah: “Bagaimana fikiran kamu jika Allah menjadikan malam kepada kamu tetap selama-lamanya hingga ke hari kiamat; tuhan yang manakah yang lain dari Allah, yang dapat membawakan cahaya yang menerangi kepada kamu? Maka mengapa kamu tidak mahu mendengar (secara memahami dan menerima kebenaran)?”', FALSE, NULL, NULL, 394, 20, 157, 340, FALSE, 0, NULL),
(28, 72, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ أَفَلَا تُبْصِرُونَ', 'قُلْ أَرَأَيْتُمْ إِن جَعَلَ اللَّهُ عَلَيْكُمُ النَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ الْقِيَامَةِ مَنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ أَفَلَا تُبْصِرُونَ', NULL, 'Say, "Have you considered: if Allāh should make for you the day continuous until the Day of Resurrection, what deity other than Allāh could bring you a night in which you may rest? Then will you not see?"', 'katakanlah lagi: Bagaimana fikiran kamu jika Allah menjadikan siang kepada kamu tetap selama-lamanya hingga ke hari kiamat; tuhan yang manakah yang lain dari Allah, yang dapat membawakan malam kepada kamu untuk kamu berehat padanya? Maka mengapa kamu tidak mahu melihat (dalil-dalil dan bukti keesaan dan kekuasaan Allah)?”', FALSE, NULL, NULL, 394, 20, 157, 340, FALSE, 0, NULL),
(28, 73, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وَمِن رَّحْمَتِهِ جَعَلَ لَكُمُ اللَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِن فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And out of His mercy He made for you the night and the day that you may rest therein and [by day] seek from His bounty and [that] perhaps you will be grateful.', 'Dan di antara rahmat pemberianNya, Ia menjadikan untuk kamu malam dan siang (silih berganti supaya kamu berehat padanya dan supaya kamu berusaha mencari rezeki dari limpah kurniaNya, dan juga supaya kamu bersyukur.', FALSE, NULL, NULL, 394, 20, 157, 340, FALSE, 0, NULL),
(28, 74, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ', NULL, 'And [warn of] the Day He will call them and say, "Where are My ''partners'' which you used to claim?"', 'Dan (ingatlah) pada hari (kiamat), Allah akan menyeru mereka lalu bertanya: “Mana dia sekutu-sekutuKu yang kamu sifatkan mereka (menjadi tuhan dan dapat memberikan pertolongan)?”', FALSE, NULL, NULL, 394, 20, 157, 340, FALSE, 0, NULL),
(28, 75, 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا۟ بُرْهَٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا بُرْهَانَكُمْ فَعَلِمُوا أَنَّ الْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ', NULL, 'And We will extract from every nation a witness and say, "Produce your proof," and they will know that the truth belongs to Allāh, and lost from them is that which they used to invent.', 'Dan (pada hari itu) Kami keluarkan dari tiap-tiap umat seorang saksi, lalu Kami katakan (kepada golongan yang kafir): “Bawalah keterangan dan bukti kebenaran kamu”. Maka (pada saat itu) ketahuilah mereka bahawa kebenaran (hak ketuhanan) itu tertentu bagi Allah, dan (dengan itu), hilang lenyaplah dari mereka apa yang mereka ada-adakan secara dusta dahulu.', FALSE, NULL, NULL, 394, 20, 157, 340, FALSE, 0, NULL),
(28, 76, 'إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', 'إِنَّ قَارُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ وَآتَيْنَاهُ مِنَ الْكُنُوزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ إِذْ قَالَ لَهُ قَوْمُهُ لَا تَفْرَحْ إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ', NULL, 'Indeed, Qārūn was from the people of Moses, but he tyrannized them. And We gave him of treasures whose keys would burden a band of strong men; thereupon his people said to him, "Do not exult. Indeed, Allāh does not like the exultant.', 'Sesungguhnya Qarun adalah ia dari kaum Nabi Musa, kemudian ia berlaku sombong dan zalim terhadap mereka; dan Kami telah mengurniakannya dari berbagai jenis kekayaan yang anak-anak kuncinya menjadi beban yang sungguh berat untuk dipikul oleh sebilangan orang yang kuat sasa. (Ia berlaku sombong) ketika kaumnya berkata kepadanya: “Janganlah engkau bermegah-megah (dengan kekayaanmu), sesungguhnya Allah tidak suka kepada orang-orang yang bermegah-megah. (seperti lagakmu itu).', FALSE, NULL, NULL, 394, 20, 158, 341, FALSE, 0, NULL),
(28, 77, 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْـَٔاخِرَةَ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'وَابْتَغِ فِيمَا آتَاكَ اللَّهُ الدَّارَ الْآخِرَةَ وَلَا تَنسَ نَصِيبَكَ مِنَ الدُّنْيَا وَأَحْسِن كَمَا أَحْسَنَ اللَّهُ إِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِي الْأَرْضِ إِنَّ اللَّهَ لَا يُحِبُّ الْمُفْسِدِينَ', NULL, 'But seek, through that which Allāh has given you, the home of the Hereafter; and [yet], do not forget your share of the world. And do good as Allāh has done good to you. And desire not corruption in the land. Indeed, Allāh does not like corrupters."', '“Dan tuntutlah dengan harta kekayaan yang telah dikurniakan Allah kepadamu akan pahala dan kebahagiaan hari akhirat dan janganlah engkau melupakan bahagianmu (keperluan dan bekalanmu) dari dunia; dan berbuat baiklah (kepada hamba-hamba Allah) sebagaimana Allah berbuat baik kepadamu (dengan pemberian nikmatNya yang melimpah-limpah); dan janganlah engkau melakukan kerosakan di muka bumi; sesungguhnya Allah tidak suka kepada orang-orang yang berbuat kerosakan”.', FALSE, NULL, NULL, 394, 20, 158, 341, FALSE, 0, NULL),
(28, 78, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', 'قَالَ إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلْمٍ عِندِي أَوَلَمْ يَعْلَمْ أَنَّ اللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِ مِنَ الْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا وَلَا يُسْأَلُ عَن ذُنُوبِهِمُ الْمُجْرِمُونَ', NULL, 'He said, "I was only given it because of knowledge I have." Did he not know that Allāh had destroyed before him of generations those who were greater than him in power and greater in accumulation [of wealth]? But the criminals, about their sins, will not be asked.', 'Qarun menjawab (dengan sombongnya): “Aku diberikan harta kekayaan ini hanyalah disebabkan pengetahuan dan kepandaian yang ada padaku”. (Kalaulah Qarun bijak pandai) tidakkah ia mengetahui dan pandai memahami, bahawa Allah telah membinasakan sebelumnya, dari umat-umat yang telah lalu, orang-orang yang lebih kuat daripadanya dan lebih banyak mengumpulkan harta kekayaan? Dan (ingatlah) orang-orang yang berdosa (apabila mereka diseksa) tidak lagi ditanya tentang dosa-dosa mereka, (kerana Allah sedia mengetahuinya).', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 79, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ', 'فَخَرَجَ عَلَىٰ قَوْمِهِ فِي زِينَتِهِ قَالَ الَّذِينَ يُرِيدُونَ الْحَيَاةَ الدُّنْيَا يَا لَيْتَ لَنَا مِثْلَ مَا أُوتِيَ قَارُونُ إِنَّهُ لَذُو حَظٍّ عَظِيمٍ', NULL, 'So he came out before his people in his adornment. Those who desired the worldly life said, "Oh, would that we had like what was given to Qārūn. Indeed, he is one of great fortune."', 'Kemudian Qarun keluar kepada kaumnya dengan memakai perhiasannya. (Pada saat itu) berkatalah orang-orang yang semata-mata inginkan kesenangan kehidupan dunia: “Alangkah baiknya kalau kita ada kekayaan seperti yang didapati oleh Qarun! Sesungguhnya dia adalah seorang yang bernasib baik”.', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 80, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ', 'وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَيْلَكُمْ ثَوَابُ اللَّهِ خَيْرٌ لِّمَنْ آمَنَ وَعَمِلَ صَالِحًا وَلَا يُلَقَّاهَا إِلَّا الصَّابِرُونَ', NULL, 'But those who had been given knowledge said, "Woe to you! The reward of Allāh is better for he who believes and does righteousness. And none are granted it except the patient."', 'Dan berkata pula orang-orang yang diberi ilmu (di antara mereka): “Janganlah kamu berkata demikian, pahala dari Allah lebih baik bagi orang yang beriman dan beramal soleh; dan tidak akan dapat menerima (pahala yang demikian) itu melainkan orang-orang yang sabar”.', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 81, 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', 'فَخَسَفْنَا بِهِ وَبِدَارِهِ الْأَرْضَ فَمَا كَانَ لَهُ مِن فِئَةٍ يَنصُرُونَهُ مِن دُونِ اللَّهِ وَمَا كَانَ مِنَ الْمُنتَصِرِينَ', NULL, 'And We caused the earth to swallow him and his home. And there was for him no company to aid him other than Allāh, nor was he of those who [could] defend themselves.', 'Lalu Kami timbuskan dia bersama-sama dengan rumahnya di dalam tanah, maka tidaklah ia mendapat sebarang golongan yang boleh menolongnya dari azab Allah” dan ia pula tidak dapat menolong dirinya sendiri.', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 82, 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'وَأَصْبَحَ الَّذِينَ تَمَنَّوْا مَكَانَهُ بِالْأَمْسِ يَقُولُونَ وَيْكَأَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَوْلَا أَن مَّنَّ اللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُ لَا يُفْلِحُ الْكَافِرُونَ', NULL, 'And those who had wished for his position the previous day began to say, "Oh, how Allāh extends provision to whom He wills of His servants and restricts it! If not that Allāh had conferred favor on us, He would have caused it to swallow us. Oh, how the disbelievers do not succeed!"', 'Dan orang-orang yang pada masa dahulu bercita-cita mendapat kekayaan seperti Qarun - mulai sedar sambil berkata: “Wah! Sesungguhnya Allah memewahkan rezeki bagi sesiapa yang dikehendakiNya dari hamba-hambaNya, dan Dia lah juga yang menyempitkannya kalau tidak kerana Allah memberi pertolongan kepada kita tentulah kita akan dibinasakan dengan tertimbus di dalam tanah (seperti Qarun). Aduhai! Sesungguhnya orang-orang yang kufurkan nikmat Allah itu tidak akan berjaya!”', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 83, 'تِلْكَ ٱلدَّارُ ٱلْـَٔاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى ٱلْأَرْضِ وَلَا فَسَادًا وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'تِلْكَ الدَّارُ الْآخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِي الْأَرْضِ وَلَا فَسَادًا وَالْعَاقِبَةُ لِلْمُتَّقِينَ', NULL, 'That home of the Hereafter We assign to those who do not desire exaltedness upon the earth or corruption. And the [best] outcome is for the righteous.', 'Negeri akhirat (yang telah diterangkan nikmat-nikmatnya) itu, Kami sediakan bagi orang-orang yang tidak bertujuan hendak mendapat pengaruh atau kelebihan di muka bumi dan tidak ingat hendak melakukan kerosakan; dan kesudahan yang baik adalah bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 84, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'مَن جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِّنْهَا وَمَن جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى الَّذِينَ عَمِلُوا السَّيِّئَاتِ إِلَّا مَا كَانُوا يَعْمَلُونَ', NULL, 'Whoever comes [on the Day of Judgement] with a good deed will have better than it; and whoever comes with an evil deed - then those who did evil deeds will not be recompensed except [as much as] what they used to do.', 'Sesiapa yang datang membawa amal baik (pada hari akhirat) maka baginya balasan yang lebih baik daripadanya; dan sesiapa yang datang membawa amal jahat, maka mereka yang melakukan kejahatan tidak di balas melainkan dengan apa yang mereka kerjakan.', FALSE, NULL, NULL, 395, 20, 158, 341, FALSE, 0, NULL),
(28, 85, 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'إِنَّ الَّذِي فَرَضَ عَلَيْكَ الْقُرْآنَ لَرَادُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّي أَعْلَمُ مَن جَاءَ بِالْهُدَىٰ وَمَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'Indeed, [O Muḥammad], He who imposed upon you the Qur’ān will take you back to a place of return. Say, "My Lord is most knowing of who brings guidance and who is in clear error."', 'Sesungguhnya Allah yang mewajibkan kepadamu (beramal dan menyampaikan) Al-Quran (wahai Muhammad) sudah tentu akan menyampaikan engkau lagi kepada apa yang engkau ingini dan cintai. Katakanlah (kepada kaum yang menentangmu): “Tuhanku amat mengetahui akan sesiapa yang membawa hidayah petunjuk dan sesiapa pula yang berada dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 396, 20, 158, 341, FALSE, 0, NULL),
(28, 86, 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَٰفِرِينَ', 'وَمَا كُنتَ تَرْجُو أَن يُلْقَىٰ إِلَيْكَ الْكِتَابُ إِلَّا رَحْمَةً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَافِرِينَ', NULL, 'And you were not expecting that the Book would be conveyed to you, but [it is] a mercy from your Lord. So do not be an assistant to the disbelievers.', 'Dan engkau (wahai Muhammad) tidak pernah berharap supaya Kitab Al-Quran ini diturunkan kepadamu, (tetapi ia diturunkan kepadamu) hanyalah sebagai rahmat dari Tuhanmu, oleh itu janganlah engkau menjadi orang-orang kafir.', FALSE, NULL, NULL, 396, 20, 158, 341, FALSE, 0, NULL),
(28, 87, 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَٱدْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'وَلَا يَصُدُّنَّكَ عَنْ آيَاتِ اللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَادْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ الْمُشْرِكِينَ', NULL, 'And never let them avert you from the verses of Allāh after they have been revealed to you. And invite [people] to your Lord. And never be of those who associate others with Allāh.', 'Dan janganlah mereka (yang ingkar) dapat menghalangmu (daripada menyampaikan dan beramal dengan) ayat-ayat Allah sesudah ia diturunkan kepadamu; dan serulah manusia kepada (ugama) Tuhanmu; dan janganlah engkau menjadi dari golongan yang menyertai orang-orang musyrik.', FALSE, NULL, NULL, 396, 20, 158, 341, FALSE, 0, NULL),
(28, 88, 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَآ إِلَٰهَ إِلَّا هُوَ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'وَلَا تَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ لَا إِلَٰهَ إِلَّا هُوَ كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ لَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And do not invoke with Allāh another deity. There is no deity except Him. Everything will be destroyed except His Face. His is the judgement, and to Him you will be returned.', 'Dan janganlah engkau menyembah tuhan yang lain bersama-sama Allah. Tiada Tuhan melainkan Dia. Tiap-tiap sesuatu akan binasa melainkan Zat Allah. BagiNyalah kuasa memutuskan segala hukum, dan kepadaNyalah kamu semua dikembalikan (untuk dihitung amal masing-masing dan menerima balasan).', FALSE, NULL, NULL, 396, 20, 158, 341, FALSE, 0, NULL),
(29, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam, Miim.', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 1, NULL),
(29, 2, 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', 'احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون', NULL, 'Do the people think that they will be left to say, "We believe" and they will not be tried?', 'Patutkah manusia menyangka bahawa mereka akan dibiarkan dengan hanya berkata: “Kami beriman”, sedang mereka tidak diuji (dengan sesuatu cubaan)?', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 10, NULL),
(29, 3, 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَـٰذِبِينَ', 'ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين', NULL, 'But We have certainly tried those before them, and Allāh will surely make evident those who are truthful, and He will surely make evident the liars.', 'Dan demi sesungguhnya! Kami telah menguji orang-orang yang terdahulu daripada mereka, maka (dengan ujian yang demikian), nyata apa yang diketahui Allah tentang orang-orang yang sebenar-benarnya beriman, dan nyata pula apa yang diketahuiNya tentang orang-orang yang berdusta.', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 11, NULL),
(29, 4, 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا ۚ سَآءَ مَا يَحْكُمُونَ', 'ام حسب الذين يعملون السيئات ان يسبقونا ساء ما يحكمون', NULL, 'Or do those who do evil deeds think they can outrun [i.e., escape] Us? Evil is what they judge.', 'Bahkan patutkah orang-orang yang melakukan kejahatan menyangka bahawa mereka akan terlepas dari azab Kami? Amatlah buruk apa yang mereka hukumkan itu.', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 10, NULL),
(29, 5, 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتٍ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'من كان يرجو لقاء الله فان اجل الله لات وهو السميع العليم', NULL, 'Whoever should hope for the meeting with Allāh - indeed, the term [decreed by] Allāh is coming. And He is the Hearing, the Knowing.', 'Sesiapa yang percaya akan pertemuannya dengan Allah (untuk menerima balasan), maka sesungguhnya masa yang telah ditetapkan oleh Allah itu akan tiba (dengan tidak syak lagi); dan Allah jualah Yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 12, NULL),
(29, 6, 'وَمَن جَـٰهَدَ فَإِنَّمَا يُجَـٰهِدُ لِنَفْسِهِۦٓ ۚ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَـٰلَمِينَ', 'ومن جاهد فانما يجاهد لنفسه ان الله لغني عن العالمين', NULL, 'And whoever strives only strives for [the benefit of] himself. Indeed, Allāh is Free from need of the worlds.', 'Dan sesiapa yang berjuang (menegakkan Islam) maka sesungguhnya dia hanyalah berjuang untuk kebaikan dirinya sendiri; sesungguhnya Allah Maha Kaya (tidak berhajatkan sesuatupun) daripada sekalian makhluk.', FALSE, NULL, NULL, 396, 20, 159, 342, FALSE, 10, NULL),
(29, 7, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'والذين امنوا وعملوا الصالحات لنكفرن عنهم سيئاتهم ولنجزينهم احسن الذي كانوا يعملون', NULL, 'And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do.', 'Dan orang-orang yang beriman serta beramal soleh sesungguhnya Kami akan hapuskan dari mereka kesalahan-kesalahan mereka, dan Kami akan membalas apa yang mereka telah kerjakan - dengan sebaik-baik balasan.', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 12, NULL),
(29, 8, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ حُسْنًا ۖ وَإِن جَـٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ ۚ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'ووصينا الانسان بوالديه حسنا وان جاهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبئكم بما كنتم تعملون', NULL, 'And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do.', 'Dan Kami wajibkan manusia berbuat baik kepada kedua ibu bapanya; dan jika mereka berdua mendesakmu supaya engkau mempersekutukan Daku (dalam ibadatmu) dengan sesuatu yang engkau tidak mempunyai pengetahuan mengenainya, maka janganlah engkau taat kepada mereka. Kepada Akulah tempat kembali kamu semuanya, kemudian Aku akan menerangkan kepada kamu segala yang kamu telah kerjakan.', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 21, NULL),
(29, 9, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّـٰلِحِينَ', 'والذين امنوا وعملوا الصالحات لندخلنهم في الصالحين', NULL, 'And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise].', 'Dan orang-orang yang beriman serta beramal soleh, sudah tentu Kami akan masukkan mereka dalam kumpulan orang-orang yang soleh (dengan mendapat sebaik-baik balasan).', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 7, NULL),
(29, 10, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ ۚ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَـٰلَمِينَ', 'ومن الناس من يقول امنا بالله فاذا اوذي في الله جعل فتنة الناس كعذاب الله ولئن جاء نصر من ربك ليقولن انا كنا معكم اوليس الله باعلم بما في صدور العالمين', NULL, 'And of the people are some who say, "We believe in Allāh," but when one [of them] is harmed for [the cause of] Allāh, he considers the trial [i.e., harm] of the people as [if it were] the punishment of Allāh. But if victory comes from your Lord, they say, "Indeed, We were with you." Is not Allāh most knowing of what is within the breasts of the worlds [i.e., all creatures]?', 'Dan ada sebahagian dari manusia yang berkata: “Kami beriman kepada Allah”; kemudian apabila ia diganggu dan disakiti pada jalan Allah, ia jadikan gangguan manusia itu seperti azab seksa Allah (lalu ia taatkan manusia). Dan jika datang pertolongan dari Tuhanmu memberi kemenangan kepadamu, mereka sudah tentu akan berkata: “Kami adalah sentiasa bersama-sama kamu”. (Mengapa mereka berdusta?) Bukankah Allah lebih mengetahui akan apa yang terpendam dalam hati sekalian makhluk?', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 31, NULL),
(29, 11, 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَـٰفِقِينَ', 'وليعلمن الله الذين امنوا وليعلمن المنافقين', NULL, 'And Allāh will surely make evident those who believe, and He will surely make evident the hypocrites.', 'Dan sesungguhnya Allah mengetahui akan orang-orang yang beriman, dan sesungguhnya Ia mengetahui akan orang-orang yang munafik.', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 6, NULL),
(29, 12, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَـٰيَـٰكُمْ وَمَا هُم بِحَـٰمِلِينَ مِنْ خَطَـٰيَـٰهُم مِّن شَىْءٍ ۖ إِنَّهُمْ لَكَـٰذِبُونَ', 'وقال الذين كفروا للذين امنوا اتبعوا سبيلنا ولنحمل خطاياكم وما هم بحاملين من خطاياهم من شيء انهم لكاذبون', NULL, 'And those who disbelieve say to those who believe, "Follow our way, and we will carry your sins." But they will not carry anything of their sins. Indeed, they are liars.', 'Dan berkata pula orang-orang yang kufur ingkar kepada orang-orang yang beriman: “Ikutlah jalan ugama kami, dan kami sedia menanggung kesalahan-kesalahan kamu (kalau kamu mengira perbuatan itu salah)”. Padahal mereka tidak akan dapat menanggung kesalahan orang-orang yang bersalah itu sedikitpun, dan sesungguhnya mereka adalah berdusta.', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 18, NULL),
(29, 13, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ ۖ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَـٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', 'وليحملن اثقالهم واثقالا مع اثقالهم وليسالن يوم القيامة عما كانوا يفترون', NULL, 'But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent.', 'Dan sesungguhnya mereka akan menanggung beban-beban dosa mereka dan beban-beban (dosa orang-orang yang mereka sesatkan) bersama-sama dengan beban-beban dosa mereka sendiri; dan sesungguhnya mereka akan ditanya pada hari kiamat kelak tentang apa yang mereka pernah ada-adakan secara dusta itu.', FALSE, NULL, NULL, 397, 20, 159, 342, FALSE, 11, NULL),
(29, 14, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَـٰلِمُونَ', 'ولقد ارسلنا نوحا الى قومه فلبث فيهم الف سنة الا خمسين عاما فاخذهم الطوفان وهم ظالمون', NULL, 'And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.', 'Dan sesungguhnya Kami telah mengutus Nabi Nuh kepada kaumnya, maka tinggallah ia dalam kalangan mereka selama sembilan ratus lima puluh tahun; akhirnya mereka dibinasakan oleh taufan sedang mereka berkeadaan zalim (dengan kufur derhaka).', FALSE, NULL, NULL, 397, 20, 159, 343, FALSE, 16, NULL),
(29, 15, 'فَأَنجَيْنَـٰهُ وَأَصْحَـٰبَ ٱلسَّفِينَةِ وَجَعَلْنَـٰهَآ ءَايَةً لِّلْعَـٰلَمِينَ', 'فانجيناه واصحاب السفينة وجعلناها اية للعالمين', NULL, 'But We saved him and the companions of the ship, and We made it a sign for the worlds.', 'Maka dengan itu Kami selamatkan dia dan pengikut-pengikutnya yang turut bersama dalam bahtera, dan Kami jadikan bahtera itu satu tanda (yang membuktikan kekuasaan Kami dan memberi pengajaran insaf) kepada sekalian makhluk.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 6, NULL),
(29, 16, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ۖ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'وابراهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون', NULL, 'And [We sent] Abraham, when he said to his people, "Worship Allāh and fear Him. That is best for you, if you should know.', 'Dan (sebutkanlah peristiwa) Nabi Ibrahim, ketika ia berkata kepada kaumnya: “Sembahlah kamu akan Allah dan bertaqwalah kepadaNya; yang demikian itu adalah baik bagi kamu jika kamu tahu (membezakan yang baik dari yang buruk).', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 13, NULL),
(29, 17, 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَـٰنًا وَتَخْلُقُونَ إِفْكًا ۚ إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ ۖ إِلَيْهِ تُرْجَعُونَ', 'انما تعبدون من دون الله اوثانا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون', NULL, 'You only worship, besides Allāh, idols, and you produce a falsehood. Indeed, those you worship besides Allāh do not possess for you [the power of] provision. So seek from Allāh provision and worship Him and be grateful to Him. To Him you will be returned."', '“Kamu hanyalah menyembah berhala-berhala yang diperbuat oleh orang, tidak menyembah Allah yang mencipta segala-galanya, dan kamu hanya mengadakan penyembahan yang dusta. Sesungguhnya mereka yang kamu sembah yang lain dari Allah itu, tidak berkuasa memberi rezeki kepada kamu; oleh itu carilah rezeki dari sisi Allah, dan sembahlah akan Dia, serta bersyukurlah kepadaNya; (ingatlah), kepada Allah jualah kamu akan dikembalikan.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 27, NULL),
(29, 18, 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ ۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', 'وان تكذبوا فقد كذب امم من قبلكم وما على الرسول الا البلاغ المبين', NULL, 'And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification.', '“Dan jika kamu terus-menerus mendustakan (ajaran ugama Allah yang aku sampaikan kepada kamu), maka sesungguhnya umat-umat yang sebelum kamu telah juga mendustakan (Rasul-rasulnya); dan (ingatlah) tugas Rasul hanya menyampaikan dengan penjelasan yang terang nyata”.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 13, NULL),
(29, 19, 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'اولم يروا كيف يبدئ الله الخلق ثم يعيده ان ذلك على الله يسير', NULL, 'Have they not considered how Allāh begins creation and then repeats it? Indeed that, for Allāh, is easy.', 'Tidakkah mereka melihat dan memikirkan bagaimana Allah mencipta makhluk-makhluk pada mulanya, kemudian Ia akan mengembalikannya (hidup semula sesudah matinya)? Sesungguhnya yang demikian itu amatlah mudah bagi Allah.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 13, NULL),
(29, 20, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْـَٔاخِرَةَ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشئ النشاة الاخرة ان الله على كل شيء قدير', NULL, 'Say, [O Muḥammad], "Travel through the land and observe how He began creation. Then Allāh will produce the final creation [i.e., development]. Indeed Allāh, over all things, is competent."', 'Katakanlah: “Mengembaralah kamu di muka bumi, serta lihatlah bagaimana Allah telah memulakan ciptaan makhluk-makhluk dari asal jadinya; kemudian Allah akan memulakan ciptaan itu semula (pada hari akhirat) dalam bentuk kejadian yang baharu. Sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 19, NULL),
(29, 21, 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ وَإِلَيْهِ تُقْلَبُونَ', 'يُعَذِّبُ مَن يَشَاءُ وَيَرْحَمُ مَن يَشَاءُ وَإِلَيْهِ تُقْلَبُونَ', NULL, 'He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned.', '“Ia menyeksa sesiapa yang dikehendakiNya (iaitu orang-orang yang ingkar), dan Ia juga yang memberi rahmat kepada sesiapa yang dikehendakiNya (iaitu orang-orang yang beriman); dan kepadaNyalah kamu semua akan dikembalikan (untuk menerima balasan).', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 0, NULL),
(29, 22, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'وَمَا أَنتُم بِمُعْجِزِينَ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'And you will not cause failure [to Allāh] upon the earth or in the heaven. And you have not other than Allāh any protector or any helper.', '“Dan kamu tidak akan dapat melepaskan diri (dari kekuasaan Allah) di bumi dan tidak juga di langit (sekalipun); dan kamu tidak akan mendapat sebarang pelindung dan penolong yang lain dari Allah”.', FALSE, NULL, NULL, 398, 20, 159, 343, FALSE, 0, NULL),
(29, 23, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'وَالَّذِينَ كَفَرُوا بِآيَاتِ اللَّهِ وَلِقَائِهِ أُولَٰئِكَ يَئِسُوا مِن رَّحْمَتِي وَأُولَٰئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'And the ones who disbelieve in the signs of Allāh and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment.', 'Dan orang-orang yang kufur ingkar akan ayat-ayat keterangan Allah dan pertemuan denganNya, mereka tetaplah akan menjadi orang-orang yang putus asa dari rahmatKu; dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 398, 20, 159, 344, FALSE, 0, NULL),
(29, 24, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'فَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا اقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَاهُ اللَّهُ مِنَ النَّارِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'And the answer of his [i.e., Abraham''s] people was not but that they said, "Kill him or burn him," but Allāh saved him from the fire. Indeed in that are signs for a people who believe.', 'Kemudian, seruan Nabi Ibrahim tidak dijawab oleh kaumnya melainkan dengan kata-kata (tentangan yang keras): “Bunuhlah dia atau bakarlah dia”. Maka Allah selamatkan Nabi Ibrahim dari api (yang disediakan oleh kaumnya). Sesungguhnya peristiwa yang demikian, mengandungi tanda-tanda (yang membuktikan kekuasaan Allah) bagi kaum yang (mahu) beriman.', FALSE, NULL, NULL, 399, 20, 159, 344, FALSE, 0, NULL),
(29, 25, 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'وَقَالَ إِنَّمَا اتَّخَذْتُم مِّن دُونِ اللَّهِ أَوْثَانًا مَّوَدَّةَ بَيْنِكُمْ فِي الْحَيَاةِ الدُّنْيَا ثُمَّ يَوْمَ الْقِيَامَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَاكُمُ النَّارُ وَمَا لَكُم مِّن نَّاصِرِينَ', NULL, 'And [Abraham] said, "You have only taken, other than Allāh, idols as [a bond of] affection among you in worldly life. Then on the Day of Resurrection you will deny one another and curse one another, and your refuge will be the Fire, and you will not have any helpers."', 'Dan Nabi Ibrahim berkata pula (kepada kaumnya): “Perbuatan kamu menyembah berbagai berhala, tidak menyembah Allah itu, hanyalah kerana menjaga hubungan kasih mesra di antara kamu masing-masing dalam kehidupan dunia ini; kemudian pada hari kiamat kelak setengah kamu akan membantah setengahnya yang lain, dan setengah kamu pula akan melaknatkan setengahnya yang lain; dan (kesudahannya) tempat kembali kamu ialah neraka, dan kamu tidak akan beroleh sesiapapun yang dapat memberikan pertolongan”.', FALSE, NULL, NULL, 399, 20, 159, 344, FALSE, 0, NULL),
(29, 26, 'فَـَٔامَنَ لَهُۥ لُوطٌ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'فَآمَنَ لَهُ لُوطٌ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّي إِنَّهُ هُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'And Lot believed him. [Abraham] said, "Indeed, I will emigrate to [the service of] my Lord. Indeed, He is the Exalted in Might, the Wise."', 'Setelah itu Lut beriman kepadanya dan Nabi Ibrahim pun berkata: “Aku hendak berhijrah kepada TuhanKu, sesungguhnya Dia lah jua Yang Maha Kuasa, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 399, 20, 160, 344, FALSE, 0, NULL),
(29, 27, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ وَجَعَلْنَا فِي ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَابَ وَآتَيْنَاهُ أَجْرَهُ فِي الدُّنْيَا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ', NULL, 'And We gave to him Isaac and Jacob and placed in his descendants prophethood and scripture. And We gave him his reward in this world, and indeed, he is in the Hereafter among the righteous.', 'Dan Kami kurniakan kepadanya: Ishak (anaknya) dan Yaakub (cucunya); dan Kami jadikan dalam kalangan keturunannya orang-orang yang berpangkat Nabi dan menerima Kitab-kitab ugama; dan Kami berikan balasannya yang baik di dunia; dan sesungguhnya adalah ia, pada hari akhirat, dari orang-orang yang soleh.', FALSE, NULL, NULL, 399, 20, 160, 344, FALSE, 0, NULL),
(29, 28, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِ إِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ', NULL, 'And [mention] Lot, when he said to his people, "Indeed, you commit such immorality as no one has preceded you with from among the worlds.', 'Dan (ingatkanlah peristiwa) Nabi Lut tatkala ia berkata kepada kaumnya: “Sesungguhnya kamu melakukan perbuatan yang keji, yang tidak pernah dilakukan oleh seorangpun dari penduduk alam ini sebelum kamu.', FALSE, NULL, NULL, 399, 20, 160, 344, FALSE, 0, NULL),
(29, 29, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ وَتَقْطَعُونَ السَّبِيلَ وَتَأْتُونَ فِي نَادِيكُمُ الْمُنكَرَ فَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا ائْتِنَا بِعَذَابِ اللَّهِ إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'Indeed, you approach men and obstruct the road and commit in your meetings [every] evil." And the answer of his people was not but that they said, "Bring us the punishment of Allāh, if you should be of the truthful."', '“Patutkah kamu mendatangi orang lelaki (untuk memuaskan nafsu syahwat kamu)? Dan kamu memotong jalan lalu-lalang (untuk tujuan jahat kamu)? Dan kamu pula melakukan perbuatan yang mungkar di tempat-tempat perhimpunan kamu?” Maka kaumnya tidak menjawab selain daripada berkata (secara mengejek-ejek): “Datangkanlah kepada kami azab dari Allah (yang engkau janjikan itu) jika betul engkau dari orang-orang yang benar”.', FALSE, NULL, NULL, 399, 20, 160, 344, FALSE, 0, NULL),
(29, 30, 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', 'قَالَ رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ', NULL, 'He said, "My Lord, support me against the corrupting people."', 'Nabi Lut berdoa dengan berkata: “Wahai Tuhanku, tolonglah daku terhadap kaum yang melakukan kerosakan (menderhaka)”.', FALSE, NULL, NULL, 399, 20, 160, 344, FALSE, 0, NULL),
(29, 31, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ', 'وَلَمَّا جَاءَتْ رُسُلُنَا إِبْرَاهِيمَ بِالْبُشْرَىٰ قَالُوا إِنَّا مُهْلِكُو أَهْلِ هَٰذِهِ الْقَرْيَةِ إِنَّ أَهْلَهَا كَانُوا ظَالِمِينَ', NULL, 'And when Our messengers [i.e., angels] came to Abraham with the good tidings, they said, "Indeed, we will destroy the people of that [i.e., Lot''s] city. Indeed, its people have been wrongdoers."', 'Dan ketika datang (malaikat) utusan kami kepada Nabi Ibrahim dengan membawa berita yang mengembirakan), mereka berkata: “Sebenarnya kami hendak membinasakan penduduk bandar ini), sesungguhnya penduduknya adalah orang-orang yang zalim”.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 32, 'قَالَ إِنَّ فِيهَا لُوطًا قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'قَالَ إِنَّ فِيهَا لُوطًا قَالُوا نَحْنُ أَعْلَمُ بِمَن فِيهَا لَنُنَجِّيَنَّهُ وَأَهْلَهُ إِلَّا امْرَأَتَهُ كَانَتْ مِنَ الْغَابِرِينَ', NULL, '[Abraham] said, "Indeed, within it is Lot." They said, "We are more knowing of who is within it. We will surely save him and his family, except his wife. She is to be of those who remain behind."', 'Nabi Ibrahim berkata: “Sebenarnya Lut ada di bandar itu”. Mereka menjawab: “Kami mengetahui akan orang-orang yang tinggal di situ. Sesungguhnya kami akan menyelamatkan dia dan keluarganya (serta pengikut-pengikutnya) - kecuali isterinya, ia adalah dari orang-orang yang dibinasakan”.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 33, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'وَلَمَّا أَن جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا لَا تَخَفْ وَلَا تَحْزَنْ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا امْرَأَتَكَ كَانَتْ مِنَ الْغَابِرِينَ', NULL, 'And when Our messengers [i.e., angels] came to Lot, he was distressed for them and felt for them great discomfort. They said, "Fear not, nor grieve. Indeed, we will save you and your family, except your wife; she is to be of those who remain behind.', 'Dan ketika datang utusan-utusan Kami kepada Nabi Lut, ia merasa dukacita dengan kedatangan mereka, dan merasa tidak terdaya untuk mengawal mereka (dari gangguan kaumnya); dan (setelah melihatkan halnya yang demikian), utusan-utusan itu berkata: “Janganlah engkau takut dan janganlah berdukacita, sesungguhnya kami akan menyelamatkanmu dan keluargamu (serta pengikut-pengikutmu) - kecuali isterimu, ia adalah dari orang-orang yang dibinasakan.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 34, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'إِنَّا مُنزِلُونَ عَلَىٰ أَهْلِ هَٰذِهِ الْقَرْيَةِ رِجْزًا مِّنَ السَّمَاءِ بِمَا كَانُوا يَفْسُقُونَ', NULL, 'Indeed, we will bring down on the people of this city punishment from the sky because they have been defiantly disobedient."', '“Sesungguhnya kami (diutuskan) untuk menurunkan atas penduduk bandar ini azab dari langit, disebabkan mereka melakukan kejahatan (kufur dan maksiat)”.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 35, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', 'وَلَقَد تَّرَكْنَا مِنْهَا آيَةً بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', NULL, 'And We have certainly left of it a sign as clear evidence for a people who use reason.', 'Dan demi sesungguhnya, Kami telah (binasakan bandar itu dan telah) tinggalkan bekas-bekasnya sebagai satu tanda (yang mendatangkan iktibar) bagi orang-orang yang mahu memahaminya.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 36, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْـَٔاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ وَارْجُوا الْيَوْمَ الْآخِرَ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ', NULL, 'And to Madyan [We sent] their brother Shuʿayb, and he said, "O my people, worship Allāh and expect the Last Day and do not commit abuse on the earth, spreading corruption."', 'Dan (Kami utuskan) kepada penduduk Madyan saudara mereka: Nabi Syuaib; lalu ia berkata: “Wahai kaumku, sembahlah kamu akan Allah, dan kerjakanlah amal soleh dengan mengharapkan pahala akhirat, dan janganlah kamu melakukan kerosakan di bumi”.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 37, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ', NULL, 'But they denied him, so the earthquake seized them, and they became within their home [corpses] fallen prone.', 'Maka mereka mendustakannya, lalu mereka dibinasakan oleh gempa bumi, serta menjadilah mereka mayat-mayat yang tersungkur di tempat tinggal masing-masing.', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 38, 'وَعَادًا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', 'وَعَادًا وَثَمُودَ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَاكِنِهِمْ وَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ وَكَانُوا مُسْتَبْصِرِينَ', NULL, 'And [We destroyed] ʿAad and Thamūd, and it has become clear to you from their [ruined] dwellings. And Satan had made pleasing to them their deeds and averted them from the path, and they were endowed with perception.', 'Dan (ingatkanlah peristiwa kebinasaan) Aad (kaum nabi Hud) dan Thamud (kaum Nabi Soleh); dan telahpun ternyata kepada kamu sebahagian dari bekas-bekas tempat kediaman mereka; dan (kebinasaan mereka yang demikian ialah disebabkan) Syaitan memperelokkan pada pandangan mereka: amal-amal mereka (yang jahat itu), lalu ia menghalangi mereka dari jalan Allah; padahal mereka orang-orang yang bijak pandai dan berakal (yang dapat membezakan yang benar dan yang salah).', FALSE, NULL, NULL, 400, 20, 160, 345, FALSE, 0, NULL),
(29, 39, 'وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَٰبِقِينَ', 'وَقَارُونَ وَفِرْعَوْنَ وَهَامَانَ وَلَقَدْ جَاءَهُم مُّوسَىٰ بِالْبَيِّنَاتِ فَاسْتَكْبَرُوا فِي الْأَرْضِ وَمَا كَانُوا سَابِقِينَ', NULL, 'And [We destroyed] Qārūn and Pharaoh and Hāmān. And Moses had already come to them with clear evidences, and they were arrogant in the land, but they were not outrunners [of Our punishment].', 'Dan (ingatkanlah juga peristiwa kebinasaan) Qarun dan Firaun serta Haman. Dan demi sesungguhnya Nabi Musa telah datang kepada mereka membawa keterangan-keterangan (mukjizat) yang jelas nyata, lalu mereka berlaku sombong takbur di bumi (mendustakannya), padahal mereka tidak dapat melepaskan diri (dari azab Allah).', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 40, 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'فَكُلًّا أَخَذْنَا بِذَنبِهِ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ الصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ الْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا وَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ', NULL, 'So each We seized for his sin; and among them were those upon whom We sent a storm of stones, and among them were those who were seized by the blast [from the sky], and among them were those whom We caused the earth to swallow, and among them were those whom We drowned. And Allāh would not have wronged them, but it was they who were wronging themselves.', 'Maka masing-masing Kami binasakan dengan sebab dosanya, iaitu di antaranya ada yang Kami hantarkan angin ribut menghujaninya dengan batu; dan ada yang dibinasakan dengan letusan suara yang menggempakan bumi; dan ada yang Kami timbuskan dia di bumi; dan ada pula yang Kami tenggelamkan di laut. Dan (ingatlah) Allah tidak sekali-kali menganiaya mereka, akan tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 41, 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًا وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ لَوْ كَانُوا۟ يَعْلَمُونَ', 'مَثَلُ الَّذِينَ اتَّخَذُوا مِن دُونِ اللَّهِ أَوْلِيَاءَ كَمَثَلِ الْعَنكَبُوتِ اتَّخَذَتْ بَيْتًا وَإِنَّ أَوْهَنَ الْبُيُوتِ لَبَيْتُ الْعَنكَبُوتِ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'The example of those who take allies other than Allāh is like that of the spider who takes [i.e., constructs] a home. And indeed, the weakest of homes is the home of the spider, if they only knew.', 'Misal bandingan orang-orang yang menjadikan benda-benda yang lain dari Allah sebagai pelindung-pelindung (yang diharapkan pertolongannya) adalah seperti labah-labah yang membuat sarang (untuk menjadi tempat perlindungannya); padahal sesungguhnya sarang-sarang yang paling reput ialah sarang labah-labah, kalaulah mereka orang-orang yang berpengetahuan.', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 42, 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'إِنَّ اللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِ مِن شَيْءٍ وَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'Indeed, Allāh knows whatever thing they call upon other than Him. And He is the Exalted in Might, the Wise.', 'Sesungguhnya Allah mengetahui (kepalsuan) apa jua yang mereka sembah yang lain daripadaNya, dan Allah jualah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 43, 'وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَٰلِمُونَ', 'وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ', NULL, 'And these examples We present to the people, but none will understand them except those of knowledge.', 'Dan misal-misal perbandingan yang demikian itu Kami kemukakan kepada umat manusia, dan hanya orang-orang yang berilmu yang dapat memahaminya.', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 44, 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', 'خَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ إِنَّ فِي ذَٰلِكَ لَآيَةً لِّلْمُؤْمِنِينَ', NULL, 'Allāh created the heavens and the earth in truth. Indeed in that is a sign for the believers.', 'Allah mencipta langit dan bumi dengan cara yang layak dan berhikmat; sesungguhnya yang demikian itu mengandungi satu tanda (yang membuktikan kebijaksanaan Allah) bagi orang-orang yang beriman.', FALSE, NULL, NULL, 401, 20, 160, 345, FALSE, 0, NULL),
(29, 45, 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', 'اتْلُ مَا أُوحِيَ إِلَيْكَ مِنَ الْكِتَابِ وَأَقِمِ الصَّلَاةَ إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ وَلَذِكْرُ اللَّهِ أَكْبَرُ وَاللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', NULL, 'Recite, [O Muḥammad], what has been revealed to you of the Book and establish prayer. Indeed, prayer prohibits immorality and wrongdoing, and the remembrance of Allāh is greater. And Allāh knows that which you do.', 'Bacalah serta ikutlah (wahai Muhammad) akan apa yang diwahyukan kepadamu dari Al-Quran, dan dirikanlah sembahyang (dengan tekun); sesungguhnya sembahyang itu mencegah dari perbuatan yang keji dan mungkar; dan sesungguhnya mengingati Allah adalah lebih besar (faedahnya dan kesannya); dan (ingatlah) Allah mengetahui akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 401, 20, 160, 346, FALSE, 0, NULL),
(29, 46, 'وَلَا تُجَٰدِلُوٓا۟ أَهْلَ ٱلْكِتَٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ وَقُولُوا آمَنَّا بِالَّذِي أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَاحِدٌ وَنَحْنُ لَهُ مُسْلِمُونَ', NULL, 'And do not argue with the People of the Scripture except in a way that is best, except for those who commit injustice among them, and say, "We believe in that which has been revealed to us and revealed to you. And our God and your God is one; and we are Muslims [in submission] to Him."', 'Dan janganlah kamu berbahas dengan Ahli Kitab melainkan dengan cara yang lebih baik, kecuali orang-orang yang berlaku zalim di antara mereka; dan katakanlah (kepada mereka): “Kami beriman kepada (Al-Quran) yang diturunkan kepada kami dan kepada (Taurat dan Injil) yang diturunkan kepada kamu; dan Tuhan kami, juga Tuhan kamu, adalah Satu; dan kepadaNyalah, kami patuh dengan berserah diri.”', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 47, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ فَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يُؤْمِنُونَ بِهِۦ وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلْكَٰفِرُونَ', 'وَكَذَٰلِكَ أَنزَلْنَا إِلَيْكَ الْكِتَابَ فَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يُؤْمِنُونَ بِهِ وَمِنْ هَٰؤُلَاءِ مَن يُؤْمِنُ بِهِ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا الْكَافِرُونَ', NULL, 'And thus We have sent down to you the Book [i.e., the Qur’ān]. And those to whom We [previously] gave the Scripture believe in it. And among these [people of Makkah] are those who believe in it. And none reject Our verses except the disbelievers.', 'Dan (sebagaimana Kami telah menurunkan Kitab-kitab ugama kepada Rasul-rasul yang telah lalu) demikianlah Kami turunkan pula kepadamu (wahai Muhammad) Kitab Al-Quran ini. Maka orang-orang yang Kami berikan Kitab (Taurat dan Injil) ada yang beriman kepada Al-Quran, dan juga sebahagian dari orang-orang (Makkah) beriman kepadanya; dan tiadalah yang mengingkari ayat-ayat keterangan Kami melainkan orang-orang yang berdegil dalam kekufurannya.', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 48, 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ إِذًا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', 'وَمَا كُنتَ تَتْلُو مِن قَبْلِهِ مِن كِتَابٍ وَلَا تَخُطُّهُ بِيَمِينِكَ إِذًا لَّارْتَابَ الْمُبْطِلُونَ', NULL, 'And you did not recite before it any scripture, nor did you inscribe one with your right hand. Then [i.e., otherwise] the falsifiers would have had [cause for] doubt.', 'Dan engkau (wahai Muhammad) tidak pernah tahu membaca sesebuah kitab pun sebelum turunnya Al-Quran ini, dan tidak pula tahu menulisnya dengan tangan kananmu; (kalaulah engkau dahulu pandai membaca dan menulis) tentulah ada alasan bagi orang-orang kafir yang menentangmu akan merasa ragu-ragu (tentang kebenaranmu).', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 49, 'بَلْ هُوَ ءَايَٰتٌۢ بَيِّنَٰتٌ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', 'بَلْ هُوَ آيَاتٌ بَيِّنَاتٌ فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا الظَّالِمُونَ', NULL, 'Rather, it [i.e., the Qur’ān] is distinct verses [preserved] within the breasts of those who have been given knowledge. And none reject Our verses except the wrongdoers.', '(Al-Quran tetap datangnya dari Allah dengan tidak syak lagi) bahkan ia ayat-ayat keterangan yang jelas nyata, yang terpelihara di dalam dada orang-orang yang berilmu; dan tiadalah yang mengingkari ayat-ayat keterangan Kami melainkan orang-orang yang zalim.', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 50, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌ مِّن رَّبِّهِۦ قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'وَقَالُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَاتٌ مِّن رَّبِّهِ قُلْ إِنَّمَا الْآيَاتُ عِندَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُّبِينٌ', NULL, 'But they say, "Why are not signs sent down to him from his Lord?" Say, "The signs are only with Allāh, and I am only a clear warner."', 'Dan mereka berkata: “Mengapa tidak diturunkan kepada (Muhammad) mukjizat-mukjizat dari Tuhannya?” Jawablah (wahai Muhammad): “Sesungguhnya (urusan menurunkan) mukjizat-mukjizat itu adalah tertentu bagi Allah, dan aku hanyalah seorang Rasul pemberi amaran yang jelas nyata”.', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 51, 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', 'أَوَلَمْ يَكْفِهِمْ أَنَّا أَنزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلَىٰ عَلَيْهِمْ إِنَّ فِي ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', NULL, 'And is it not sufficient for them that We revealed to you the Book [i.e., the Qur’ān] which is recited to them? Indeed in that is a mercy and reminder for a people who believe.', '(Patutkah mereka meminta mukjizat-mukjizat yang lain?) tidakkah cukup bagi mereka bahawa Kami telah menurunkan kepadamu Al-Quran yang dibacakan kepada mereka? Sesungguhnya Al-Quran yang diturunkan itu mengandungi rahmat dan peringatan bagi orang-orang yang beriman.', FALSE, NULL, NULL, 402, 21, 161, 346, FALSE, 0, NULL),
(29, 52, 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'قُلْ كَفَىٰ بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَالَّذِينَ آمَنُوا بِالْبَاطِلِ وَكَفَرُوا بِاللَّهِ أُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, 'Say, "Sufficient is Allāh between me and you as Witness. He knows what is in the heavens and earth. And they who have believed in falsehood and disbelieved in Allāh - it is those who are the losers."', 'Katakanlah (wahai Muhammad): “Cukuplah Allah menjadi saksi (yang mengetahui perkara yang berbangkit) antaraku dengan kamu; Ia mengetahui segala yang ada di langit dan di bumi. Dan mereka yang percaya kepada perkara yang salah dan tidak percaya kepada Allah, mereka itulah orang-orang yang rugi.', FALSE, NULL, NULL, 402, 21, 161, 347, FALSE, 0, NULL),
(29, 53, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ وَلَوْلَا أَجَلٌ مُّسَمًّى لَّجَاءَهُمُ الْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', NULL, 'And they urge you to hasten the punishment. And if not for [the decree of] a specified term, punishment would have reached them. But it will surely come to them suddenly while they perceive not.', 'Dan mereka meminta kepadamu menyegerakan kedatangan azab (yang dijanjikan); dan kalau tidaklah kerana adanya tempoh yang telah ditetapkan, tentulah azab itu akan datang menimpa mereka; dan azab itu tetap akan datang menimpa mereka secara mengejut, sedang mereka tidak menyedarinya.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 54, 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'يَسْتَعْجِلُونَكَ بِالْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ', NULL, 'They urge you to hasten the punishment. And indeed, Hell will be encompassing of the disbelievers', 'Mereka meminta kepadamu menyegerakan kedatangan azab itu, padahal sesungguhnya neraka Jahannam tetap akan meliputi orang-orang yang kafir -', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 55, 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', 'يَوْمَ يَغْشَاهُمُ الْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا مَا كُنتُمْ تَعْمَلُونَ', NULL, 'On the Day the punishment will cover them from above them and from below their feet and it is said, "Taste [the result of] what you used to do."', 'Pada hari azab itu menyelubungi mereka dari sebelah atas mereka dan dari bawah kaki mereka; dan (malaikat yang melakukannya) akan berkata kepada mereka: “Rasalah kamu (balasan) apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 56, 'يَٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّٰىَ فَٱعْبُدُونِ', 'يَا عِبَادِيَ الَّذِينَ آمَنُوا إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ', NULL, 'O My servants who have believed, indeed My earth is spacious, so worship only Me.', 'Wahai hamba-hambaKu yang beriman! Sesungguhnya bumiKu adalah luas (untuk kamu bebas beribadat); oleh itu, (di mana sahaja kamu dapat berbuat demikian) maka hendaklah kamu ikhlaskan ibadat kamu kepadaKu.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 57, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ', 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ', NULL, 'Every soul will taste death. Then to Us will you be returned.', 'Tiap-tiap diri (sudah tetap) akan merasai mati, kemudian kamu akan dikembalikan kepada Kami (untuk menerima balasan).', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 58, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُبَوِّئَنَّهُم مِّنَ الْجَنَّةِ غُرَفًا تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نِعْمَ أَجْرُ الْعَامِلِينَ', NULL, 'And those who have believed and done righteous deeds - We will surely assign to them of Paradise [elevated] chambers beneath which rivers flow, wherein they abide eternally. Excellent is the reward of the [righteous] workers', 'Dan orang-orang yang beriman serta beramal soleh, Kami akan tempatkan mereka dalam mahligai-mahligai di Syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya. Demikianlah balasan yang sebaik-baiknya bagi orang-orang yang beramal soleh -', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 59, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'الَّذِينَ صَبَرُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', NULL, 'Who have been patient and upon their Lord rely.', '(Iaitu) mereka yang sabar, dan mereka pula berserah diri bulat-bulat kepada Tuhannya.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 60, 'وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَكَأَيِّن مِّن دَابَّةٍ لَّا تَحْمِلُ رِزْقَهَا اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ وَهُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'And how many a creature carries not its [own] provision. Allāh provides for it and for you. And He is the Hearing, the Knowing.', 'Dan (ingatlah) berapa banyak binatang yang tidak membawa rezekinya bersama, Allah jualah yang memberi rezeki kepadanya dan kepada kamu; dan Dia lah jua Yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 61, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ لَيَقُولُنَّ اللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', NULL, 'If you asked them, "Who created the heavens and earth and subjected the sun and the moon?" they would surely say, "Allāh." Then how are they deluded?', 'Dan sesungguhnya jika engkau (wahai Muhammad) bertanya kepada mereka (yang musyrik) itu: “Siapakah yang menciptakan langit dan bumi, dan yang memudahkan matahari dan bulan (untuk faedah makhluk-makhlukNya)?” Sudah tentu mereka akan menjawab: “Allah”. Maka bagaimana mereka tergamak dipalingkan (oleh hawa nafsunya daripada mengakui keesaan Allah dan mematuhi perintahNya)?', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 62, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'اللَّهُ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ', NULL, 'Allāh extends provision for whom He wills of His servants and restricts for him. Indeed Allāh is, of all things, Knowing.', 'Allah memewahkan rezeki bagi sesiapa yang dikehendakiNya di antara hamba-hambaNya dan menyempitkan (rezeki itu) baginya; sesungguhnya Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 63, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ السَّمَاءِ مَاءً فَأَحْيَا بِهِ الْأَرْضَ مِن بَعْدِ مَوْتِهَا لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', NULL, 'And if you asked them, "Who sends down rain from the sky and gives life thereby to the earth after its lifelessness?" they would surely say, "Allāh." Say, "Praise to Allāh"; but most of them do not reason.', 'Dan sesungguhnya jika engkau (wahai Muhammad) bertanya kepada mereka (yang musyrik) itu: “Siapakah yang menurunkan hujan dari langit, lalu Ia hidupkan dengannya tumbuh-tumbuhan di bumi sesudah matinya?” Sudah tentu mereka akan menjawab: “Allah”. Ucapkanlah (wahai Muhammad): “Alhamdulillah” (sebagai bersyukur disebabkan pengakuan mereka yang demikian), bahkan kebanyakan mereka tidak memahami (hakikat tauhid dan pengertian syirik).', FALSE, NULL, NULL, 403, 21, 161, 347, FALSE, 0, NULL),
(29, 64, 'وَمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ وَإِنَّ ٱلدَّارَ ٱلْـَٔاخِرَةَ لَهِىَ ٱلْحَيَوَانُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'وَمَا هَٰذِهِ الْحَيَاةُ الدُّنْيَا إِلَّا لَهْوٌ وَلَعِبٌ وَإِنَّ الدَّارَ الْآخِرَةَ لَهِيَ الْحَيَوَانُ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'And this worldly life is not but diversion and amusement. And indeed, the home of the Hereafter - that is the [eternal] life, if only they knew.', 'Dan (ingatlah bahawa) kehidupan dunia ini (meliputi segala kesenangan dan kemewahannya, jika dinilaikan dengan kehidupan akhirat) tidak lain hanyalah ibarat hiburan dan permainan; dan sesungguhnya negeri akhirat itu ialah kehidupan yang sebenar-benarnya; kalaulah mereka mengetahui (hakikat ini tentulah mereka tidak akan melupakan hari akhirat).', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(29, 65, 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', 'فَإِذَا رَكِبُوا فِي الْفُلْكِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ إِذَا هُمْ يُشْرِكُونَ', NULL, 'And when they board a ship, they supplicate Allāh, sincere to Him in religion [i.e., faith and hope]. But when He delivers them to the land, at once they associate others with Him', 'Dalam pada itu, apabila mereka naik bahtera (lalu menemui sesuatu bahaya di laut), mereka memohon pertolongan kepada Allah dengan doa yang tulus ikhlas kepadaNya. Kemudian setelah Allah menyelamatkan mereka (naik) ke darat, mereka berlaku syirik kepadaNya.', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(29, 66, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ فَسَوْفَ يَعْلَمُونَ', 'لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ وَلِيَتَمَتَّعُوا فَسَوْفَ يَعْلَمُونَ', NULL, 'So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know.', '(Akibat syirik itu) menjadilah mereka orang-orang yang kufurkan nikmat yang Kami telah berikan kepadanya, dan (menjadi) orang-orang yang hanya dapat bersuka ria di dunia; kemudian mereka akan mengetahui kelak akibat buruk apa yang mereka lakukan.', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(29, 67, 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', 'أَوَلَمْ يَرَوْا أَنَّا جَعَلْنَا حَرَمًا آمِنًا وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ أَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ', NULL, 'Have they not seen that We made [Makkah] a safe sanctuary, while people are being taken away all around them? Then in falsehood do they believe, and in the favor of Allāh they disbelieve?', 'Dan tidakkah mereka melihat dan memerhatikan bahawa Kami telah menjadikan (Makkah, negeri mereka) tanah suci yang dihormati, lagi aman; sedang orang-orang ramai yang tinggal (dalam daerah-daerah) di sekeliling mereka sentiasa diculik (untuk ditawan atau dibunuh)? Oleh itu, patutkah mereka percaya kepada perkara yang salah, dan kufur ingkar akan nikmat-nikmat Allah?', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(29, 68, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِالْحَقِّ لَمَّا جَاءَهُ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِّلْكَافِرِينَ', NULL, 'And who is more unjust than one who invents a lie about Allāh or denies the truth when it has come to him? Is there not in Hell a [sufficient] residence for the disbelievers?', 'Dan tidaklah ada yang lebih zalim daripada orang yang mereka-reka perkara-perkara yang dusta terhadap Allah, atau mendustakan kebenaran setelah kebenaran itu disampaikan kepadanya. Bukankah (telah diketahui bahawa) dalam neraka Jahannam disediakan tempat tinggal bagi orang-orang yang kafir?', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(29, 69, 'وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', 'وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ', NULL, 'And those who strive for Us - We will surely guide them to Our ways. And indeed, Allāh is with the doers of good.', 'Dan orang-orang yang berusaha dengan bersungguh-sungguh kerana memenuhi kehendak ugama Kami, sesungguhnya Kami akan memimpin mereka ke jalan-jalan Kami (yang menjadikan mereka bergembira serta beroleh keredaan); dan sesungguhnya (pertolongan dan bantuan) Allah adalah berserta orang-orang yang berusaha membaiki amalannya.', FALSE, NULL, NULL, 404, 21, 161, 348, FALSE, 0, NULL),
(30, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam, Miim.', FALSE, NULL, NULL, 404, 21, 162, 349, FALSE, 1, NULL),
(30, 2, 'غُلِبَتِ ٱلرُّومُ', 'غلبت الروم', NULL, 'The Byzantines have been defeated', 'Orang-orang Rom telah dikalahkan -', FALSE, NULL, NULL, 404, 21, 162, 349, FALSE, 2, NULL),
(30, 3, 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'في ادنى الارض وهم من بعد غلبهم سيغلبون', NULL, 'In the nearest land. But they, after their defeat, will overcome', 'Di negeri yang dekat sekali; dan mereka sesudah kekalahannya itu akan mengalahkan lawannya -', FALSE, NULL, NULL, 404, 21, 162, 349, FALSE, 8, NULL),
(30, 4, 'فِى بِضْعِ سِنِينَ ۗ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ ۚ وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ', 'في بضع سنين لله الامر من قبل ومن بعد ويومئذ يفرح المؤمنون', NULL, 'Within three to nine years. To Allāh belongs the command [i.e., decree] before and after. And that day the believers will rejoice', 'Dalam masa tidak sampai sepuluh tahun. Kepada pentadbiran Allah jualah terpulang segala urusan, sebelum berlakunya dan sesudah berlakunya; dan pada ketika berlakunya (kemenangan Rom) itu, orang-orang yang beriman akan bergembira -', FALSE, NULL, NULL, 404, 21, 162, 349, FALSE, 12, NULL),
(30, 5, 'بِنَصْرِ ٱللَّهِ ۚ يَنصُرُ مَن يَشَآءُ ۖ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'بنصر الله ينصر من يشاء وهو العزيز الرحيم', NULL, 'In the victory of Allāh. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.', 'Dengan kemenangan yang diberi Allah. Ia memberi kemenangan kepada sesiapa yang dikehendakiNya, dan Dia lah jua yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 404, 21, 162, 349, FALSE, 8, NULL),
(30, 6, 'وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وعد الله لا يخلف الله وعده ولكن اكثر الناس لا يعلمون', NULL, '[It is] the promise of Allāh. Allāh does not fail in His promise, but most of the people do not know.', 'Demikian dijanjikan Allah. Allah tidak pernah mengubah janjiNya, akan tetapi kebanyakan manusia tidak mengetahui (hakikat yang sebenarnya).', FALSE, NULL, NULL, 405, 21, 162, 349, FALSE, 11, NULL),
(30, 7, 'يَعْلَمُونَ ظَـٰهِرًا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْـَٔاخِرَةِ هُمْ غَـٰفِلُونَ', 'يعلمون ظاهرا من الحياة الدنيا وهم عن الاخرة هم غافلون', NULL, 'They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.', 'Mereka hanya mengetahui perkara yang zahir nyata dari kehidupan dunia sahaja, dan mereka tidak pernah ingat hendak mengambil tahu tentang hari akhirat.', FALSE, NULL, NULL, 405, 21, 162, 349, FALSE, 10, NULL),
(30, 8, 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم ۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى ۗ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَـٰفِرُونَ', 'اولم يتفكروا في انفسهم ما خلق الله السماوات والارض وما بينهما الا بالحق واجل مسمى وان كثيرا من الناس بلقاء ربهم لكافرون', NULL, 'Do they not contemplate within themselves? Allāh has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in the meeting with their Lord, are disbelievers.', 'Patutkah mereka merasa cukup dengan mengetahui yang demikian sahaja, dan tidak memikirkan dalam hati mereka, (supaya mereka dapat mengetahui), bahawa Allah tidak menciptakan langit dan bumi serta segala yang ada di antara keduanya itu melainkan dengan ada gunanya yang sebenar, dan dengan ada masa penghujungnya yang tertentu, (juga untuk kembali menemui Penciptanya)? Dan sebenarnya banyak di antara manusia, orang-orang yang sungguh ingkar akan pertemuan dengan Tuhannya.', FALSE, NULL, NULL, 405, 21, 162, 349, FALSE, 22, NULL),
(30, 9, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'اولم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم كانوا اشد منهم قوة واثاروا الارض وعمروها اكثر مما عمروها وجاءتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون', NULL, 'Have they not traveled through the earth and observed how was the end of those before them? They were greater than them in power, and they plowed [or excavated] the earth and built it up more than they [i.e., the Makkans] have built it up, and their messengers came to them with clear evidences. And Allāh would not ever have wronged them, but they were wronging themselves.', 'Tidakkah mereka telah berjalan dan mengembara di muka bumi, serta memerhatikan bagaimana kesudahan orang-orang yang terdahulu dari mereka? Orang-orang itu lebih kuat daripada mereka sendiri, dan orang-orang itu telah meneroka bumi serta memakmurkannya lebih daripada kemakmuran yang dilakukan oleh mereka, dan orang-orang itu juga telah didatangi oleh Rasul-rasulnya dengan membawa keterangan-keterangan yang jelas nyata (lalu mereka mendustakannya dan kesudahannya mereka dibinasakan). Dengan yang demikian, maka Allah tidak sekali-kali menganiaya mereka, tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 405, 21, 162, 349, FALSE, 32, NULL),
(30, 10, 'ثُمَّ كَانَ عَـٰقِبَةَ ٱلَّذِينَ أَسَـٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', 'ثم كان عاقبة الذين اساءوا السواى ان كذبوا بايات الله وكانوا بها يستهزئون', NULL, 'Then the end of those who did evil was the worst [consequence] because they denied the signs of Allāh and used to ridicule them.', 'Sesudah dibinasakan di dunia maka akibat orang-orang yang melakukan kejahatan itu ialah seburuk-buruk azab (di akhirat kelak), disebabkan mereka mendustakan ayat-ayat keterangan Allah dan sentiasa mempersendakannya.', FALSE, NULL, NULL, 405, 21, 162, 349, FALSE, 13, NULL),
(30, 11, 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'الله يبدا الخلق ثم يعيده ثم اليه ترجعون', NULL, 'Allāh begins creation; then He will repeat it; then to Him you will be returned.', 'Allah memulakan kejadian sekalian makhluk, kemudian Ia mengembalikannya (hidup semula pada hari kiamat), kemudian kepadaNyalah kamu akan dikembalikan (untuk menerima balasan).', FALSE, NULL, NULL, 405, 21, 162, 350, FALSE, 8, NULL),
(30, 12, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', 'ويوم تقوم الساعة يبلس المجرمون', NULL, 'And the Day the Hour appears the criminals will be in despair.', 'Dan semasa berlakunya hari kiamat, orang-orang yang berdosa akan dia membisu serta berputus asa.', FALSE, NULL, NULL, 405, 21, 162, 350, FALSE, 5, NULL),
(30, 13, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَـٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَـٰفِرِينَ', 'ولم يكن لهم من شركائهم شفعاء وكانوا بشركائهم كافرين', NULL, 'And there will not be for them among their [alleged] partners any intercessors, and they will [then] be disbelievers in their partners.', 'Dan makhluk-makhluk yang mereka jadikan sekutu-sekutu Allah itu tidak ada satupun daripadanya pemberi syafaat melepaskan mereka (dari azab Allah), padahal mereka berlaku kufur di dunia dahulu dengan sebab makhluk-makhluk yang mereka sekutukan (dengan Allah) itu.', FALSE, NULL, NULL, 405, 21, 162, 350, FALSE, 9, NULL),
(30, 14, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', 'ويوم تقوم الساعة يومئذ يتفرقون', NULL, 'And the Day the Hour appears - that Day they will become separated.', 'Dan semasa berlakunya kiamat, mereka pada hari itu akan berpecah kepada dua kumpulan (setelah selesai perbicaraan).', FALSE, NULL, NULL, 405, 21, 162, 350, FALSE, 5, NULL),
(30, 15, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ', 'فاما الذين امنوا وعملوا الصالحات فهم في روضة يحبرون', NULL, 'And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted.', 'Adapun kumpulan orang-orang yang beriman dan beramal soleh, maka mereka akan ditempatkan di taman Syurga dalam keadaan bersuka ria.', FALSE, NULL, NULL, 405, 21, 162, 350, FALSE, 9, NULL),
(30, 16, 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا وَلِقَآئِ ٱلْـَٔاخِرَةِ فَأُو۟لَـٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'واما الذين كفروا وكذبوا باياتنا ولقاء الاخرة فاولئك في العذاب محضرون', NULL, 'But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain].', 'Dan sebaliknya kumpulan orang-orang yang kafir dan mendustakan ayat-ayat Kami (Al-Quran) serta mendustakan pertemuan hari akhirat, maka mereka akan tetap berada dalam azab seksa selama-lamanya.', FALSE, NULL, NULL, 406, 21, 162, 350, FALSE, 11, NULL),
(30, 17, 'فَسُبْحَـٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', 'فسبحان الله حين تمسون وحين تصبحون', NULL, 'So exalted is Allāh when you reach the evening and when you reach the morning.', '(Setelah kamu mengetahui yang demikian) maka bertasbihlah kepada Allah semasa kamu berada pada waktu malam dan semasa kamu berada pada waktu subuh.', FALSE, NULL, NULL, 406, 21, 162, 350, FALSE, 6, NULL),
(30, 18, 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ', 'وله الحمد في السماوات والارض وعشيا وحين تظهرون', NULL, 'And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.', 'Serta pujilah Allah yang berhak menerima segala puji (dari sekalian makhlukNya) di langit dan di bumi, dan juga (bertasbihlah kepadaNya serta pujilah Dia) pada waktu petang dan semasa kamu berada pada waktu zuhur.', FALSE, NULL, NULL, 406, 21, 162, 350, FALSE, 8, NULL),
(30, 19, 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ وَكَذَٰلِكَ تُخْرَجُونَ', 'يخرج الحي من الميت ويخرج الميت من الحي ويحيي الارض بعد موتها وكذلك تخرجون', NULL, 'He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out.', 'Ia mengeluarkan sesuatu yang hidup dari benda yang mati, dan mengeluarkan benda yang mati dari sesuatu yang hidup, serta menghidupkan bumi sesudah matinya; dan sedemikian itulah kamu akan dikeluarkan (hidup semula dari kubur).', FALSE, NULL, NULL, 406, 21, 162, 350, FALSE, 14, NULL),
(30, 20, 'وَمِنْ ءَايَـٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ', 'ومن اياته ان خلقكم من تراب ثم اذا انتم بشر تنتشرون', NULL, 'And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth].', 'Dan di antara tanda-tanda yang membuktikan kekuasaanNya (menghidupkan kamu semula), bahawa Ia menciptakan kamu dari tanah; setelah sempurna sahaja peringkat-peringkat kejadian kamu, kamu menjadi manusia yang hidup bertebaran di muka bumi.', FALSE, NULL, NULL, 406, 21, 162, 351, FALSE, 11, NULL),
(30, 21, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجًا لِّتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', NULL, 'And of His signs is that He created for you from yourselves mates that you may find tranquility in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought.', 'Dan di antara tanda-tanda yang membuktikan kekuasaannya dan rahmatNya, bahawa Ia menciptakan untuk kamu (wahai kaum lelaki), isteri-isteri dari jenis kamu sendiri, supaya kamu bersenang hati dan hidup mesra dengannya, dan dijadikanNya di antara kamu (suami isteri) perasaan kasih sayang dan belas kasihan. Sesungguhnya yang demikian itu mengandungi keterangan-keterangan (yang menimbulkan kesedaran) bagi orang-orang yang berfikir.', FALSE, NULL, NULL, 406, 21, 162, 351, FALSE, 0, NULL),
(30, 22, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّلْعَٰلِمِينَ', 'وَمِنْ آيَاتِهِ خَلْقُ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافُ أَلْسِنَتِكُمْ وَأَلْوَانِكُمْ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّلْعَالِمِينَ', NULL, 'And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge.', 'Dan di antara tanda-tanda yang membuktikan kekuasaanNya dan kebijaksanaanNya ialah kejadian langit dan bumi, dan perbezaan bahasa kamu dan warna kulit kamu. Sesungguhnya yang demikian itu mengandungi keterangan-keterangan bagi orang-orang yang berpengetahuan.', FALSE, NULL, NULL, 406, 21, 162, 351, FALSE, 0, NULL),
(30, 23, 'وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'وَمِنْ آيَاتِهِ مَنَامُكُم بِاللَّيْلِ وَالنَّهَارِ وَابْتِغَاؤُكُم مِّن فَضْلِهِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَسْمَعُونَ', NULL, 'And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen.', 'Dan di antara tanda-tanda yang membuktikan kemurahannya dan kasih sayangNya ialah tidurnya kamu pada waktu malam dan pada siang hari, dan usaha kamu mencari rezeki dari limpah kurniaNya (pada kedua-dua waktu itu). Sesungguhnya keadaan yang demikian mengandungi keterangan-keterangan bagi orang-orang yang mahu mendengar (nasihat pengajaran).', FALSE, NULL, NULL, 406, 21, 162, 351, FALSE, 0, NULL),
(30, 24, 'وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءً فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'وَمِنْ آيَاتِهِ يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ السَّمَاءِ مَاءً فَيُحْيِي بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ', NULL, 'And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason.', 'Dan di antara tanda-tanda yang membuktikan kebesaranNya dan kekuasaanNya, Ia memperlihatkan kilat kepada kamu, untuk menakutkan (dari panahan petir) dan memberi harapan (dengan turunnya hujan); dan Ia menurunkan hujan dari langit, lalu Ia hidupkan bumi sesudah matinya dengan hujan itu. Sesungguhnya yang demikian mengandungi keterangan-keterangan bagi orang-orang yang menggunakan akal untuk memahamiNya.', FALSE, NULL, NULL, 406, 21, 162, 351, FALSE, 0, NULL),
(30, 25, 'وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', 'وَمِنْ آيَاتِهِ أَن تَقُومَ السَّمَاءُ وَالْأَرْضُ بِأَمْرِهِ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ الْأَرْضِ إِذَا أَنتُمْ تَخْرُجُونَ', NULL, 'And of His signs is that the heaven and earth stand [i.e., remain] by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth.', 'Dan di antara tanda-tanda yang membuktikan keluasan ilmuNya dan kekuasaanNya, ialah terdirinya langit dan bumi (dalam keadaan yang menakjubkan itu) dengan perintah dan penentuan takdirNya; akhirnya apabila Ia menyeru kamu dengan satu seruan (supaya kamu bangkit hidup semula) dari bumi, kamu dengan serta merta keluar (dari kubur masing-masing).', FALSE, NULL, NULL, 407, 21, 162, 351, FALSE, 0, NULL),
(30, 26, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'وَلَهُ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ كُلٌّ لَّهُ قَانِتُونَ', NULL, 'And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient.', 'Dan sekalian makhluk yang ada di langit dan di bumi adalah hak kepunyaanNya, masing-masing tetap tunduk kepada hukum peraturanNya.', FALSE, NULL, NULL, 407, 21, 162, 351, FALSE, 0, NULL),
(30, 27, 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ الْمَثَلُ الْأَعْلَىٰ فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest description [i.e., attribute] in the heavens and earth. And He is the Exalted in Might, the Wise.', 'Dan Dia lah yang memulakan kejadian sekalian makhluk, kemudian Ia mengembalikannya (hidup semula sesudah mereka mati), sedang perlaksanaan yang demikian amatlah mudah bagiNya. Dan bagiNyalah jua sifat yang tertinggi di langit dan di bumi, dan Dia lah jua Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 407, 21, 162, 351, FALSE, 0, NULL),
(30, 28, 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْقِلُونَ', 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَانُكُم مِّن شُرَكَاءَ فِي مَا رَزَقْنَاكُمْ فَأَنتُمْ فِيهِ سَوَاءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ كَذَٰلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْقِلُونَ', NULL, 'He presents to you an example from yourselves. Do you have among those whom your right hands possess [i.e., slaves] any partners in what We have provided for you so that you are equal therein [and] would fear them as your fear of one another [within a partnership]? Thus do We detail the verses for a people who use reason.', 'Ia mengemukakan kepada kamu satu misal perbandingan dari keadaan diri kamu sendiri, iaitu: Relakah kamu menerima sebahagian dari hamba-hamba abdi yang kamu miliki itu menjadi rakan kongsi kamu pada harta benda yang Kami telah kurniakan kepada kamu, supaya dengan penerimaan kamu itu, mereka dengan kamu menjadi sama-sama berhak padanya, sehingga kamu pun tidak berani (menguruskan harta benda itu dengan tiada persetujuan) mereka, sebagaimana kamu tidak berani (berbuat demikian dengan orang-orang yang berkongsi dengan kamu - yang setaraf dengan) diri kamu? Demikianlah Kami menjelaskan keterangan-keterangan satu persatu bagi orang-orang yang menggunakan akal untuk memahaminya.', FALSE, NULL, NULL, 407, 21, 162, 352, FALSE, 0, NULL),
(30, 29, 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'بَلِ اتَّبَعَ الَّذِينَ ظَلَمُوا أَهْوَاءَهُم بِغَيْرِ عِلْمٍ فَمَن يَهْدِي مَنْ أَضَلَّ اللَّهُ وَمَا لَهُم مِّن نَّاصِرِينَ', NULL, 'But those who wrong follow their [own] desires without knowledge. Then who can guide one whom Allāh has sent astray? And for them there are no helpers.', 'Orang-orang yang zalim itu (tidak berfikir), bahkan menurut hawa nafsu mereka (melakukan syirik) dengan tidak berdasarkan pengetahuan. Maka tiada sesiapa yang dapat memberi petunjuk kepada orang yang telah disesatkan oleh Allah (disebabkan bawaannya sendiri), dan tiada pula bagi mereka sesiapa yang dapat menolong melepaskan mereka dari azab.', FALSE, NULL, NULL, 407, 21, 162, 352, FALSE, 0, NULL),
(30, 30, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ ذَٰلِكَ الدِّينُ الْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'So direct your face [i.e., self] toward the religion, inclining to truth. [Adhere to] the fiṭrah of Allāh upon which He has created [all] people. No change should there be in the creation of Allāh. That is the correct religion, but most of the people do not know.', '(Setelah jelas kesesatan syirik itu) maka hadapkanlah dirimu (engkau dan pengikut-pengikutmu, wahai Muhammad) ke arah ugama yang jauh dari kesesatan; (turutlah terus) ugama Allah, iaitu ugama yang Allah menciptakan manusia (dengan keadaan bersedia dari semulajadinya) untuk menerimanya; tidaklah patut ada sebarang perubahan pada ciptaan Allah itu; itulah ugama yang betul lurus, tetapi kebanyakan manusia tidak mengetahui.', FALSE, NULL, NULL, 407, 21, 162, 352, FALSE, 0, NULL),
(30, 31, 'مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', 'مُنِيبِينَ إِلَيْهِ وَاتَّقُوهُ وَأَقِيمُوا الصَّلَاةَ وَلَا تَكُونُوا مِنَ الْمُشْرِكِينَ', NULL, '[Adhere to it], turning in repentance to Him, and fear Him and establish prayer and do not be of those who associate others with Allāh', 'Hendaklah kamu (wahai Muhammad dan pengikut-pengikutmu) sentiasa rujuk kembali kepada Allah (dengan mengerjakan amal-amal bakti) serta bertaqwalah kamu kepadaNya; dan kerjakanlah sembahyang dengan betul sempurna; dan janganlah kamu menjadi dari mana-mana golongan orang musyrik -', FALSE, NULL, NULL, 407, 21, 163, 352, FALSE, 0, NULL),
(30, 32, 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ', NULL, '[Or] of those who have divided their religion and become sects, every faction rejoicing in what it has.', 'Iaitu orang-orang yang menjadikan fahaman ugama mereka berselisihan mengikut kecenderungan masing-masing serta mereka pula menjadi berpuak-puak; tiap-tiap puak bergembira dengan apa yang ada padanya (dari fahaman dan amalan yang terpesong itu).', FALSE, NULL, NULL, 407, 21, 163, 352, FALSE, 0, NULL),
(30, 33, 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', 'وَإِذَا مَسَّ النَّاسَ ضُرٌّ دَعَوْا رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَا أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', NULL, 'And when adversity touches the people, they call upon their Lord, turning in repentance to Him. Then when He lets them taste mercy from Him, at once a party of them associate others with their Lord,', 'Dan apabila manusia disentuh oleh sesuatu bahaya, mereka segera berdoa kepada Tuhan mereka dengan keadaan rujuk kembali bertaubat kepadaNya; kemudian apabila Allah memberi mereka merasai sesuatu rahmat daripadaNya, tiba-tiba sebahagian dari mereka mempersekutukan sesuatu yang lain dengan Tuhannya;', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 34, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ فَتَمَتَّعُوا فَسَوْفَ تَعْلَمُونَ', NULL, 'So that they will deny what We have granted them. Then enjoy yourselves, for you are going to know.', 'Dengan sebab itu, mereka mengingkari nikmat-nikmat yang telah Kami berikan kepadanya. Maka (dikatakan kepada mereka): “Bersenang-senanglah kamu (bagi sementara), kemudian kamu akan mengetahui (balasan kederhakaan kamu)”.', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 35, 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَانًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا بِهِ يُشْرِكُونَ', NULL, 'Or have We sent down to them an authority [i.e., a proof or scripture], and it speaks of what they have been associating with Him?', 'Pernahkah Kami menurunkan kepada mereka (yang musyrik itu) sebarang bukti keterangan, lalu ia menerangkan jalan yang membolehkan mereka lakukan perbuatan syirik itu?', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 36, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً فَرِحُوا۟ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', 'وَإِذَا أَذَقْنَا النَّاسَ رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', NULL, 'And when We let the people taste mercy, they rejoice therein, but if evil afflicts them for what their hands have put forth, immediately they despair.', 'Dan apabila Kami beri manusia merasai sesuatu rahmat, mereka bergembira dengannya (sehingga lupa daratan); dan jika mereka ditimpa sesuatu bencana disebabkan apa yang telah dilakukan oleh tangan mereka sendiri, tiba-tiba mereka berputus asa.', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 37, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'أَوَلَمْ يَرَوْا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'Do they not see that Allāh extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.', '(Mengapa mereka bersikap demikian?) dan mengapa mereka tidak melihat (dengan hati mereka) bahawa Allah memewahkan rezeki bagi sesiapa yang dikehendakiNya (sebagai cubaan adakah orang itu bersyukur atau sebaliknya), dan Ia juga yang menyempitkannya (sebagai ujian sama ada diterima dengan sabar atau tidak)? Sesungguhnya hal yang demikian itu mengandungi keterangan-keterangan (yang membuktikan kekuasaan Allah) bagi orang-orang yang beriman.', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 38, 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فَآتِ ذَا الْقُرْبَىٰ حَقَّهُ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ اللَّهِ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ', NULL, 'So give the relative his right, as well as the needy and the traveler. That is best for those who desire the face [i.e., approval] of Allāh, and it is they who will be the successful.', 'Maka (bagi menyatakan sikap syukur) berikanlah kepada kerabatmu, dan orang miskin serta orang musafir akan haknya masing-masing; pemberian yang demikian adalah baik bagi orang-orang yang bertujuan memperoleh keredaan Allah dan mereka itulah orang-orang yang berjaya.', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 39, 'وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', 'وَمَا آتَيْتُم مِّن رِّبًا لِّيَرْبُوَ فِي أَمْوَالِ النَّاسِ فَلَا يَرْبُو عِندَ اللَّهِ وَمَا آتَيْتُم مِّن زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَٰئِكَ هُمُ الْمُضْعِفُونَ', NULL, 'And whatever you give for interest [i.e., advantage] to increase within the wealth of people will not increase with Allāh. But what you give in zakāh, desiring the face [i.e., approval] of Allāh - those are the multipliers.', 'Dan (ketahuilah bahawa) sesuatu pemberian atau tambahan yang kamu berikan, supaya bertambah kembangnya dalam pusingan harta manusia maka ia tidak sekali-kali akan kembang di sisi Allah (tidak mendatangkan kebaikan). Dan sebaliknya sesuatu pemberian sedekah yang kamu berikan dengan tujuan mengharapkan keredaan Allah semata-mata, maka mereka yang melakukannya itulah orang-orang yang beroleh pahala berganda-ganda.', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 40, 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'اللَّهُ الَّذِي خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِن شُرَكَائِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَيْءٍ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ', NULL, 'Allāh is the one who created you, then provided for you, then will cause you to die, and then will give you life. Are there any of your "partners" who does anything of that? Exalted is He and high above what they associate with Him.', 'Allah jualah yang mencipta kamu; kemudian Ia memberi rezeki kepada kamu; sesudah itu Ia mematikan kamu; kemudian Ia menghidupkan kamu semula. Adakah di antara makhluk-makhluk yang kamu sekutukan dengan Allah itu sesiapa yang dapat berbuat sesuatu pun dari segala yang tersebut? Maha Suci Allah dan Tertinggi keadaanNya dari apa yang mereka sekutukan (denganNya).', FALSE, NULL, NULL, 408, 21, 163, 352, FALSE, 0, NULL),
(30, 41, 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ لِيُذِيقَهُم بَعْضَ الَّذِي عَمِلُوا لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'Corruption has appeared throughout the land and sea by [reason of] what the hands of people have earned so He [i.e., Allāh] may let them taste part of [the consequence of] what they have done that perhaps they will return [to righteousness].', 'Telah timbul berbagai kerosakan dan bala bencana di darat dan di laut dengan sebab apa yang telah dilakukan oleh tangan manusia; (timbulnya yang demikian) kerana Allah hendak merasakan mereka sebahagian dari balasan perbuatan-perbuatan buruk yang mereka telah lakukan, supaya mereka kembali (insaf dan bertaubat).', FALSE, NULL, NULL, 408, 21, 163, 353, FALSE, 0, NULL),
(30, 42, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', 'قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلُ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', NULL, 'Say, [O Muḥammad], "Travel through the land and observe how was the end of those before. Most of them were associators [of others with Allāh].', 'Katakanlah: “Mengembaralah kamu di muka bumi kemudian lihatlah bagaimana kesudahan orang-orang yang telah lalu (yang telah dibinasakan); kebanyakan mereka adalah orang-orang musyrik”.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 43, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ', 'فَأَقِمْ وَجْهَكَ لِلدِّينِ الْقَيِّمِ مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ', NULL, 'So direct your face [i.e., self] toward the correct religion before a Day comes from Allāh of which there is no repelling. That Day, they will be divided.', '(Jika demikian keadaannya) maka hadapkanlah dirimu (wahai Muhammad) ke arah ugama yang betul, sebelum datangnya dari Allah: hari yang tak dapat ditolak; pada hari itu manusia akan berpecah (kepada dua golongan).', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 44, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَمَنْ عَمِلَ صَٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', NULL, 'Whoever disbelieves - upon him is [the consequence of] his disbelief. And whoever does righteousness - they are for themselves preparing,', 'Sesiapa yang kufur ingkar maka dia lah sahaja yang menanggung bencana kekufurannya itu, dan sesiapa yang beramal soleh (yang membuktikan imannya), maka merekalah orang-orang yang membuat persiapan untuk kesenangan diri mereka masing-masing;', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 45, 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ إِنَّهُۥ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِن فَضْلِهِ إِنَّهُ لَا يُحِبُّ الْكَافِرِينَ', NULL, 'That He may reward those who have believed and done righteous deeds out of His bounty. Indeed, He does not like the disbelievers.', 'Kerana Allah akan membalas orang-orang yang beriman dan beramal soleh dari limpah kurniaNya. Sesungguhnya Ia tidak suka kepada orang-orang yang kufur ingkar.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 46, 'وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وَمِنْ آيَاتِهِ أَن يُرْسِلَ الرِّيَاحَ مُبَشِّرَاتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِ وَلِتَجْرِيَ الْفُلْكُ بِأَمْرِهِ وَلِتَبْتَغُوا مِن فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ', NULL, 'And of His signs is that He sends the winds as bringers of good tidings and to let you taste His mercy [i.e., rain] and so the ships may sail at His command and so you may seek of His bounty, and perhaps you will be grateful.', 'Dan di antara tanda-tanda yang membuktikan kekuasaanNya, bahawa Ia menghantarkan angin sebagai pembawa berita yang mengembirakan; dan untuk merasakan kamu sedikit dari rahmatNya, dan supaya kapal-kapal belayar laju dengan perintahNya, dan juga supaya kamu dapat mencari rezeki dari limpah kurniaNya; dan seterusnya supaya kamu bersyukur.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 47, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَاءُوهُم بِالْبَيِّنَاتِ فَانتَقَمْنَا مِنَ الَّذِينَ أَجْرَمُوا وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ', NULL, 'And We have already sent messengers before you to their peoples, and they came to them with clear evidences; then We took retribution from those who committed crimes, and incumbent upon Us was support of the believers.', 'Dan demi sesungguhnya, Kami telah mengutuskan sebelummu (wahai Muhammad) Rasul-rasul kepada kaum masing-masing, lalu mereka membawa kepada kaumnya keterangan-keterangan yang jelas nyata; kemudian Kami menyeksa orang-orang yang berlaku salah (mengingkarinya); dan sememangnya adalah menjadi tanggungjawab Kami menolong orang-orang yang beriman.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 48, 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'اللَّهُ الَّذِي يُرْسِلُ الرِّيَاحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُ فِي السَّمَاءِ كَيْفَ يَشَاءُ وَيَجْعَلُهُ كِسَفًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِهِ فَإِذَا أَصَابَ بِهِ مَن يَشَاءُ مِنْ عِبَادِهِ إِذَا هُمْ يَسْتَبْشِرُونَ', NULL, 'It is Allāh who sends the winds, and they stir the clouds and spread them in the sky however He wills, and He makes them fragments so you see the rain emerge from within them. And when He causes it to fall upon whom He wills of His servants, immediately they rejoice', 'Allah jualah yang menghantarkan angin, lalu angin itu menggerakkan awan; kemudian Allah menyebarkan awan itu di langit sebagaimana yang dikehendakiNya, dan menjadikannya berkelompok-kelompok; lalu engkau melihat hujan keluar dari celah-celahnya. Maka apabila Allah menurunkan hujan itu mengenai sesiapa yang dikehendakiNya dari hamba-hambanya, mereka serta merta bergembira;', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 49, 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', 'وَإِن كَانُوا مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِ لَمُبْلِسِينَ', NULL, 'Although they were, before it was sent down upon them - before that, in despair.', 'Dan sesungguhnya mereka dahulu, sebelum diturunkan hujan kepada mereka, adalah orang-orang yang telah berputus asa.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 50, 'فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'فَانظُرْ إِلَىٰ آثَارِ رَحْمَتِ اللَّهِ كَيْفَ يُحْيِي الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ ذَٰلِكَ لَمُحْيِي الْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'So observe the effects of the mercy of Allāh - how He gives life to the earth after its lifelessness. Indeed, that [same one] will give life to the dead, and He is over all things competent.', 'Maka lihatlah olehmu kepada kesan-kesan rahmat Allah, bagaimana Ia menghidupkan bumi sesudah matinya (dengan tanaman-tanaman yang menghijau subur). Sesungguhnya Allah yang demikian kekuasaanNya, sudah tentu berkuasa menghidupkan orang-orang yang telah mati. Dan (ingatlah) Ia maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 409, 21, 163, 353, FALSE, 0, NULL),
(30, 51, 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا مِن بَعْدِهِ يَكْفُرُونَ', NULL, 'But if We should send a [bad] wind and they saw [their crops] turned yellow, they would remain thereafter disbelievers.', 'Dan demi sesungguhnya, jika Kami hantarkan angin (menyerang tanaman) lalu mereka melihat tanaman itu menjadi kuning kering, nescaya mereka sesudah itu, terus kembali kufur (tidak mengenangkan nikmat-nikmat Allah serta berputus asa).', FALSE, NULL, NULL, 410, 21, 163, 353, FALSE, 0, NULL),
(30, 52, 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ', NULL, 'So indeed, you will not make the dead hear, nor will you make the deaf hear the call when they turn their backs, retreating.', '(Maka janganlah engkau berdukacita - wahai Muhammad - terhadap keadaan mereka yang demikian), kerana sesungguhnya engkau tidak dapat menjadikan orang-orang yang mati (hatinya) itu menerima ajaranmu, dan tidak dapat menjadikan orang-orang yang pekak itu mendengar seruanmu, apabila mereka berpaling undur (disebabkan keingkarannya).', FALSE, NULL, NULL, 410, 21, 163, 353, FALSE, 0, NULL),
(30, 53, 'وَمَآ أَنتَ بِهَٰدِ ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 'وَمَا أَنتَ بِهَادِ الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ', NULL, 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [in submission to Allāh].', 'Dan engkau tidak akan dapat memberi petunjuk kepada orang-orang yang buta (matahatinya) supaya menjauhi kesesatan mereka; engkau tidak dapat memperdengarkan (seruanmu itu) melainkan kepada orang-orang yang sedia beriman akan ayat-ayat keterangan Kami, kerana mereka orang-orang yang menurut perintah.', FALSE, NULL, NULL, 410, 21, 163, 353, FALSE, 0, NULL),
(30, 54, 'ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَآءُ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', 'اللَّهُ الَّذِي خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِن بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِن بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَاءُ وَهُوَ الْعَلِيمُ الْقَدِيرُ', NULL, 'Allāh is the one who created you from weakness, then made after weakness strength, then made after strength weakness and white hair. He creates what He wills, and He is the Knowing, the Competent.', 'Allah yang menciptakan kamu bermula dengan keadaan lemah, selepas berkeadaan lemah itu Ia menjadikan kamu kuat. Setelah itu Ia menjadikan kamu lemah pula serta tua beruban. Ia menciptakan apa yang dikehendakiNya, dan Dia lah jua yang Maha Mengetahui, lagi Maha Kuasa.', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 55, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', 'وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ كَذَٰلِكَ كَانُوا يُؤْفَكُونَ', NULL, 'And the Day the Hour appears the criminals will swear they had remained but an hour. Thus they were deluded.', 'Dan semasa berlakunya hari kiamat, orang-orang yang berdosa akan bersumpah mengatakan bahawa mereka tidak tinggal (di dalam kubur) melainkan sekadar satu saat sahaja; demikianlah mereka sentiasa dipalingkan (oleh fahaman sesatnya dari memperkatakan yang benar).', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 56, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ فَهَٰذَا يَوْمُ ٱلْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', 'وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالْإِيمَانَ لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَىٰ يَوْمِ الْبَعْثِ فَهَٰذَا يَوْمُ الْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', NULL, 'But those who were given knowledge and faith will say, "You remained the extent of Allāh''s decree until the Day of Resurrection, and this is the Day of Resurrection, but you did not used to know."', 'Dan (bagi menjawabnya) berkatalah orang-orang yang berilmu serta beriman: “Demi sesungguhnya, kamu telah tinggal - menurut yang terkandung dalam Kitab Allah - sampai ke hari kebangkitan (hari kiamat); maka inilah dia hari kebangkitan (yang dijanjikan) itu, akan tetapi kamu dari dahulu lagi tidak mahu mengetahui (kebenarannya)”.', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 57, 'فَيَوْمَئِذٍ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', 'فَيَوْمَئِذٍ لَّا يَنفَعُ الَّذِينَ ظَلَمُوا مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', NULL, 'So that Day, their excuse will not benefit those who wronged, nor will they be asked to appease [Allāh].', 'Maka pada hari itu tidak berguna lagi bagi orang-orang yang zalim, sebarang alasan yang mereka kemukakan untuk melepaskan diri, dan mereka pula tidak diberi peluang untuk memohon keredaan Allah.', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 58, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ وَلَئِن جِئْتَهُم بِـَٔايَةٍ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ وَلَئِن جِئْتَهُم بِآيَةٍ لَّيَقُولَنَّ الَّذِينَ كَفَرُوا إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', NULL, 'And We have certainly presented to the people in this Qur’ān from every [kind of] example. But, [O Muḥammad], if you should bring them a sign, the disbelievers will surely say, "You [believers] are but falsifiers."', 'Dan demi sesungguhnya, Kami telah mengemukakan kepada umat manusia berbagai kisah dan perbandingan di dalam Al-Quran ini; dan demi sesungguhnya jika engkau membawa kepada mereka sebarang keterangan, sudah tentu orang-orang kafir itu akan berkata: “Kamu ini tidak lain hanyalah orang-orang yang membuat dakwaan palsu”.', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 59, 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', 'كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ قُلُوبِ الَّذِينَ لَا يَعْلَمُونَ', NULL, 'Thus does Allāh seal the hearts of those who do not know.', 'Demikianlah Allah meteraikan hati orang-orang yang tidak mahu menerima jalan mengetahui (kebenaran).', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(30, 60, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', 'فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ الَّذِينَ لَا يُوقِنُونَ', NULL, 'So be patient. Indeed, the promise of Allāh is truth. And let them not disquiet you who are not certain [in faith].', 'Oleh itu, bersabarlah (wahai Muhammad), sesungguhnya janji Allah itu benar; dan janganlah orang-orang yang tidak meyakini apa yang engkau sampaikan itu menjadikan engkau resah gelisah.', FALSE, NULL, NULL, 410, 21, 164, 354, FALSE, 0, NULL),
(31, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam, Miim.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 1, NULL),
(31, 2, 'تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ', 'تلك ايات الكتاب الحكيم', NULL, 'These are verses of the wise Book,', 'Ini ialah ayat-ayat Kitab (Al-Quran) yang mengandungi hikmat-hikmat dan kebenaran yang tetap kukuh,', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 4, NULL),
(31, 3, 'هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', 'هدى ورحمة للمحسنين', NULL, 'As guidance and mercy for the doers of good', 'Menjadi hidayah petunjuk dan rahmat bagi orang-orang yang sedia mengerjakan amal-amal yang baik', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 3, NULL),
(31, 4, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', 'الذين يقيمون الصلاة ويؤتون الزكاة وهم بالاخرة هم يوقنون', NULL, 'Who establish prayer and give zakāh, and they, of the Hereafter, are certain [in faith].', 'Iaitu orang-orang yang mendirikan sembahyang, dan memberi zakat, serta mereka yakin tentang adanya hari akhirat.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 9, NULL),
(31, 5, 'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'اولئك على هدى من ربهم واولئك هم المفلحون', NULL, 'Those are on [right] guidance from their Lord, and it is those who are the successful.', 'Mereka itulah yang tetap mendapat hidayah petunjuk dari Tuhan mereka, dan merekalah orang-orang yang berjaya.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 8, NULL),
(31, 6, 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اولئك لهم عذاب مهين', NULL, 'And of the people is he who buys the amusement of speech to mislead [others] from the way of Allāh without knowledge and who takes it [i.e., His way] in ridicule. Those will have a humiliating punishment.', 'Dan ada di antara manusia: orang yang memilih serta membelanjakan hartanya kepada cerita-cerita dan perkara-perkara hiburan yang melalaikan; yang berakibat menyesatkan (dirinya dan orang ramai) dari ugama Allah dengan tidak berdasarkan sebarang pengetahuan; dan ada pula orang yang menjadikan ugama Allah itu sebagai ejek-ejekan; merekalah orang-orang yang akan beroleh azab yang menghinakan.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 18, NULL),
(31, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', 'واذا تتلى عليه اياتنا ولى مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم', NULL, 'And when Our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment.', 'Dan apabila dibacakan kepadanya ayat-ayat Kami, berpalinglah dia dengan angkuhnya, seoleh-oleh ada penyumbat pada kedua telinganya; maka gembirakanlah dia dengan balasan azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 16, NULL),
(31, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتُ ٱلنَّعِيمِ', 'ان الذين امنوا وعملوا الصالحات لهم جنات النعيم', NULL, 'Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure,', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, mereka akan beroleh Syurga yang penuh dengan berbagai nikmat,', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 8, NULL),
(31, 9, 'خَـٰلِدِينَ فِيهَا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'خالدين فيها وعد الله حقا وهو العزيز الحكيم', NULL, 'Wherein they abide eternally; [it is] the promise of Allāh [which is] truth. And He is the Exalted in Might, the Wise.', 'kekalan mereka di dalamnya. Demikian dijanjikan Allah - janji yang tetap benar; dan Dia lah jua yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 8, NULL),
(31, 10, 'خَلَقَ ٱلسَّمَـٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', 'خلق السماوات بغير عمد ترونها والقى في الارض رواسي ان تميد بكم وبث فيها من كل دابة وانزلنا من السماء ماء فانبتنا فيها من كل زوج كريم', NULL, 'He created the heavens without pillars that you see and has cast into the earth firmly set mountains, lest it should shift with you, and dispersed therein from every creature. And We sent down rain from the sky and made grow therein [plants] of every noble kind.', 'Ia menciptakan langit dengan tidak bertiang sebagaimana yang kamu melihatnya; dan Ia mengadakan di bumi gunung-ganang yang menetapnya supaya bumi itu tidak menghayun-hayunkan kamu; dan Ia biakkan padanya berbagai jenis binatang. Dan Kami menurunkan hujan dari langit, lalu Kami tumbuhkan di bumi berbagai jenis tanaman yang memberi banyak manfaat.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 27, NULL),
(31, 11, 'هَـٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ ۚ بَلِ ٱلظَّـٰلِمُونَ فِى ضَلَـٰلٍ مُّبِينٍ', 'هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظالمون في ضلال مبين', NULL, 'This is the creation of Allāh. So show Me what those other than Him have created. Rather, the wrongdoers are in clear error.', 'Ini (semuanya adalah) ciptaan Allah, maka cubalah kamu tunjukkan kepadaKu apakah yang telah diciptakan oleh makhluk-makhluk yang lain daripadaNya (yang kamu sembah itu)? (Tidak ada sesuatu pun) bahkan orang-orang yang zalim (dengan perbuatan syiriknya) itu berada dalam kesesatan yang jelas nyata.', FALSE, NULL, NULL, 411, 21, 164, 355, FALSE, 14, NULL),
(31, 12, 'وَلَقَدْ ءَاتَيْنَا لُقْمَـٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ ۚ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'ولقد اتينا لقمان الحكمة ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد', NULL, 'And We had certainly given Luqmān wisdom [and said], "Be grateful to Allāh." And whoever is grateful is grateful for [the benefit of] himself. And whoever denies [His favor] - then indeed, Allāh is Free of need and Praiseworthy.', 'Dan sesungguhnya Kami telah memberi kepada Luqman, hikmat kebijaksanaan, (serta Kami perintahkan kepadanya): Bersyukurlah kepada Allah (akan segala nikmatNya kepadamu)”. Dan sesiapa yang bersyukur maka faedahnya itu hanyalah terpulang kepada dirinya sendiri, dan sesiapa yang tidak bersyukur (maka tidaklah menjadi hal kepada Allah), kerana sesungguhnya Allah Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 18, NULL),
(31, 13, 'وَإِذْ قَالَ لُقْمَـٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَـٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ ۖ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ', 'واذ قال لقمان لابنه وهو يعظه يا بني لا تشرك بالله ان الشرك لظلم عظيم', NULL, 'And [mention, O Muḥammad], when Luqmān said to his son while he was instructing him, "O my son, do not associate [anything] with Allāh. Indeed, association [with Him] is great injustice."', 'Dan (ingatlah) ketika Luqman berkata kepada anaknya, semasa ia memberi nasihat kepadanya: “Wahai anak kesayanganku, janganlah engkau mempersekutukan Allah (dengan sesuatu yang lain), sesungguhnya perbuatan syirik itu adalah satu kezaliman yang besar”.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 14, NULL),
(31, 14, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَـٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', 'ووصينا الانسان بوالديه حملته امه وهنا على وهن وفصاله في عامين ان اشكر لي ولوالديك الي المصير', NULL, 'And We have enjoined upon man [care] for his parents. His mother carried him, [increasing her] in weakness upon weakness, and his weaning is in two years. Be grateful to Me and to your parents; to Me is the [final] destination.', 'Dan Kami wajibkan manusia berbuat baik kepada kedua ibu bapanya; ibunya telah mengandungnya dengan menanggung kelemahan demi kelemahan (dari awal mengandung hingga akhir menyusunya), dan tempoh menceraikan susunya ialah dalam masa dua tahun; (dengan yang demikian) bersyukurlah kepadaKu dan kepada kedua ibubapamu; dan (ingatlah), kepada Akulah jua tempat kembali (untuk menerima balasan).', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 17, NULL),
(31, 15, 'وَإِن جَـٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا ۖ وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ۚ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'وان جاهداك على ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبئكم بما كنتم تعملون', NULL, 'But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them but accompany them in [this] world with appropriate kindness and follow the way of those who turn back to Me [in repentance]. Then to Me will be your return, and I will inform you about what you used to do.', 'Dan jika mereka berdua mendesakmu supaya engkau mempersekutukan denganKu sesuatu yang engkau - dengan fikiran sihatmu - tidak mengetahui sungguh adanya maka janganlah engkau taat kepada mereka; dan bergaulah dengan mereka di dunia dengan cara yang baik. Dan turutlah jalan orang-orang yang rujuk kembali kepadaKu (dengan tauhid dan amal-amal yang soleh). Kemudian kepada Akulah tempat kembali kamu semuanya, maka Aku akan menerangkan kepada kamu segala yang kamu telah kerjakan.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 29, NULL),
(31, 16, 'يَـٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَـٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ ۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'يا بني انها ان تك مثقال حبة من خردل فتكن في صخرة او في السماوات او في الارض يات بها الله ان الله لطيف خبير', NULL, '[And Luqmān said], "O my son, indeed if it [i.e., a wrong] should be the weight of a mustard seed and should be within a rock or [anywhere] in the heavens or in the earth, Allāh will bring it forth. Indeed, Allāh is Subtle and Aware.', '(Luqman menasihati anaknya dengan berkata): “Wahai anak kesayanganku, sesungguhnya jika ada sesuatu perkara (yang baik atau yang buruk) sekalipun seberat bijih sawi, serta ia tersembunyi di dalam batu besar atau di langit atau pun di bumi, sudah tetap akan dibawa oleh Allah (untuk dihakimi dan dibalasNya); kerana sesungguhnya Allah Maha Halus pengetahuanNya; lagi Amat Meliputi akan segala yang tersembunyi.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 24, NULL),
(31, 17, 'يَـٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'يا بني اقم الصلاة وامر بالمعروف وانه عن المنكر واصبر على ما اصابك ان ذلك من عزم الامور', NULL, 'O my son, establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you. Indeed, [all] that is of the matters [requiring] resolve.', '“Wahai anak kesayanganku, dirikanlah sembahyang, dan suruhlah berbuat kebaikan, serta laranglah daripada melakukan perbuatan yang mungkar, dan bersabarlah atas segala bala bencana yang menimpamu. Sesungguhnya yang demikian itu adalah dari perkara-perkara yang dikehendaki diambil berat melakukannya.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 17, NULL),
(31, 18, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', 'ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور', NULL, 'And do not turn your cheek [in contempt] toward people and do not walk through the earth exultantly. Indeed, Allāh does not like everyone self-deluded and boastful.', '“Dan janganlah engkau memalingkan mukamu (kerana memandang rendah) kepada manusia, dan janganlah engkau berjalan di bumi dengan berlagak sombong; sesungguhnya Allah tidak suka kepada tiap-tiap orang yang sombong takbur, lagi membanggakan diri.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 16, NULL),
(31, 19, 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ ۚ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', 'واقصد في مشيك واغضض من صوتك ان انكر الاصوات لصوت الحمير', NULL, 'And be moderate in your pace and lower your voice; indeed, the most disagreeable of sounds is the voice of donkeys."', '“Dan sederhanakanlah langkahmu semasa berjalan, juga rendahkanlah suaramu (semasa berkata-kata), sesungguhnya seburuk-buruk suara ialah suara keldai”.', FALSE, NULL, NULL, 412, 21, 164, 356, FALSE, 11, NULL),
(31, 20, 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَـٰهِرَةً وَبَاطِنَةً ۗ وَمِنَ ٱلنَّاسِ مَن يُجَـٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَـٰبٍ مُّنِيرٍ', 'الم تروا ان الله سخر لكم ما في السماوات وما في الارض واسبغ عليكم نعمه ظاهرة وباطنة ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير', NULL, 'Do you not see that Allāh has made subject to you whatever is in the heavens and whatever is in the earth and amply bestowed upon you His favors, [both] apparent and unapparent? But of the people is he who disputes about Allāh without knowledge or guidance or an enlightening Book [from Him].', 'Tidakkah kamu memperhatikan bahawa Allah telah memudahkan untuk kegunaan kamu apa yang ada di langit dan yang ada di bumi, dan telah melimpahkan kepada kami nikmat-nimatNya yang zahir dan yang batin? Dalam pada itu, ada di antara manusia orang yang membantah mengenai (sifat-sifat) Allah dengan tidak berdasarkan sebarang pengetahuan atau sebarang petunjuk; dan tidak juga berdasarkan mana-mana Kitab Allah yang menerangi kebenaran.', FALSE, NULL, NULL, 413, 21, 164, 357, FALSE, 30, NULL),
(31, 21, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا أَوَلَوْ كَانَ الشَّيْطَانُ يَدْعُوهُمْ إِلَىٰ عَذَابِ السَّعِيرِ', NULL, 'And when it is said to them, "Follow what Allāh has revealed," they say, "Rather, we will follow that upon which we found our fathers." Even if Satan was inviting them to the punishment of the Blaze?', 'Dan apabila dikatakan kepada mereka (yang ingkar): “Turutlah akan apa yang telah diturunkan oleh Allah” mereka menjawab: “(Tidak), bahkan Kami hanya menurut apa yang Kami dapati datuk nenek kami melakukannya”. Patutkah mereka (menurut datuk neneknya) sekalipun Syaitan mengajak mereka itu (melakukan perbuatan yang menjerumuskan mereka) ke dalam azab api neraka yang marak menjulang?', FALSE, NULL, NULL, 413, 21, 164, 357, FALSE, 0, NULL),
(31, 22, 'وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'وَمَن يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ وَإِلَى اللَّهِ عَاقِبَةُ الْأُمُورِ', NULL, 'And whoever submits his face [i.e., self] to Allāh while he is a doer of good - then he has grasped the most trustworthy handhold. And to Allāh will be the outcome of [all] matters.', 'Dan sesiapa yang berserah diri bulat-bulat kepada Allah (dengan ikhlas) sedang ia berusaha mengerjakan kebaikan, maka sesungguhnya ia telah berpegang kepada simpulan (tali ugama) yang teguh dan (ingatlah) kepada Allah jualah kesudahan segala urusan.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 23, 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوا إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, 'And whoever has disbelieved - let not his disbelief grieve you. To Us is their return, and We will inform them of what they did. Indeed, Allāh is Knowing of that within the breasts.', 'Dan sesiapa yang kufur ingkar, maka janganlah engkau (wahai Muhammad) berdukacita tentang kekufurannya itu; kepada Kamilah tempat kembalinya mereka, kemudian Kami akan memberitahu kepada mereka tentang apa yang mereka telah kerjakan. Sesungguhnya Allah Maha Mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 24, 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', NULL, 'We grant them enjoyment for a little; then We will force them to a massive punishment.', 'Kami akan berikan mereka menikmati kesenangan bagi sementara (di dunia), kemudian Kami akan memaksa mereka (dengan menyeretnya) ke dalam azab yang amat berat.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 25, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', NULL, 'And if you asked them, "Who created the heavens and earth?" they would surely say, "Allāh." Say, "[All] praise is [due] to Allāh"; but most of them do not know.', 'Dan sesungguhnya jika engkau (wahai Muhammad) bertanya kepada mereka (yang musyrik) itu: “Siapakah yang menciptakan langit dan bumi?” Sudah tentu mereka akan menjawab: “Allah”. Ucapkanlah (wahai Muhammad): “Alhamdulillah” (sebagai bersyukur disebabkan pengakuan mereka yang demikian - tidak mengingkari Allah), bahkan kebanyakan mereka tidak mengetahui (hakikat tauhid dan pengertian syirik).', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 26, 'لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ', NULL, 'To Allāh belongs whatever is in the heavens and earth. Indeed, Allāh is the Free of need, the Praiseworthy.', 'Allah jua yang memiliki segala yang ada di langit dan di bumi; sesungguhnya Allah Dia lah jua yang Maha Kaya, lagi sentiasa Terpuji.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 27, 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَٰتُ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'وَلَوْ أَنَّمَا فِي الْأَرْضِ مِن شَجَرَةٍ أَقْلَامٌ وَالْبَحْرُ يَمُدُّهُ مِن بَعْدِهِ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَاتُ اللَّهِ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ', NULL, 'And if whatever trees upon the earth were pens and the sea [was ink], replenished thereafter by seven [more] seas, the words of Allāh would not be exhausted. Indeed, Allāh is Exalted in Might and Wise.', 'Dan sekiranya segala pohon yang ada di bumi menjadi pena, dan segala lautan (menjadi tinta), dengan dibantu kepadanya tujuh lautan lagi sesudah itu, nescaya tidak akan habis Kalimah-kalimah Allah itu ditulis. Sesungguhnya Allah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 28, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ', NULL, 'Your creation and your resurrection will not be but as that of a single soul. Indeed, Allāh is Hearing and Seeing.', '(Bagi Allah Yang Maha Kuasa) soal menciptakan kamu semua (dari tiada kepada ada), dan soal membangkitkan kamu hidup semula sesudah mati, tidak ada apa-apa sukarnya, hanyalah seperti (mencipta dan menghidupkan semula) seorang manusia sahaja. Sesungguhnya Allah Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 413, 21, 165, 357, FALSE, 0, NULL),
(31, 29, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', 'أَلَمْ تَرَ أَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي إِلَىٰ أَجَلٍ مُّسَمًّى وَأَنَّ اللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', NULL, 'Do you not see [i.e., know] that Allāh causes the night to enter the day and causes the day to enter the night and has subjected the sun and the moon, each running [its course] for a specified term, and that Allāh, of whatever you do, is Aware?', 'Tidakkah engkau memerhatikan bahawa Allah memasukkan malam pada siang dan memasukkan siang pada malam (silih berganti), dan Ia memudahkan matahari dan bulan (untuk faedah makhluk-makhlukNya)? Tiap-tiap satu dari keduanya beredar untuk suatu masa yang telah ditetapkan. Dan (ingatlah) sesungguhnya Allah Maha Mengetahui dengan mendalam akan apa yang kamu lakukan.', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL),
(31, 30, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ', NULL, 'That is because Allāh is the True Reality, and that what they call upon other than Him is falsehood, and because Allāh is the Most High, the Grand.', 'Bersifatnya Allah dengan penuh kekuasaan dan luas ilmu pengetahuan itu kerana bahawasanya Allah Dia lah sahaja Tuhan Yang Sebenar-benarnya, dan bahawa segala yang mereka sembah selain dari Allah adalah palsu belaka. Dan (ingatlah) sesungguhnya Allah Dia lah Yang Maha Tinggi keadaanNya, lagi Maha Besar (kekuasaanNya).', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL),
(31, 31, 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'أَلَمْ تَرَ أَنَّ الْفُلْكَ تَجْرِي فِي الْبَحْرِ بِنِعْمَتِ اللَّهِ لِيُرِيَكُم مِّنْ آيَاتِهِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', NULL, 'Do you not see that ships sail through the sea by the favor of Allāh that He may show you of His signs? Indeed in that are signs for everyone patient and grateful.', 'Tidakkah engkau memerhatikan bahawasanya kapal-kapal belayar di laut dengan nikmat Kurnia Allah, untuk diperlihatkan kepada kamu sebahagian dari tanda-tanda kemurahanNya? Sesungguhnya yang demikian itu mengandungi keterangan-keterangan dan bukti (untuk berfikir) bagi tiap-tiap (mukmin) yang tetap teguh pendiriannya, lagi sentiasa bersyukur.', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(31, 32, 'وَإِذَا غَشِيَهُم مَّوْجٌ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', 'وَإِذَا غَشِيَهُم مَّوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', NULL, 'And when waves come over them like canopies, they supplicate Allāh, sincere to Him in religion [i.e., faith]. But when He delivers them to the land, there are [some] of them who are moderate [in faith]. And none rejects Our signs except everyone treacherous and ungrateful.', 'Dan (orang-orang yang tidak bersifat demikian) apabila mereka dirempuh serta diliputi oleh ombak yang besar seperti kelompok-kelompok awan menyerkup, pada saat itu mereka semua berdoa kepada Allah dengan mengikhlaskan kepercayaan mereka kepadaNya semata-mata. Kemudian bila sahaja Allah menyelamatkan mereka ke darat maka sebahagian sahaja di antara mereka yang bersikap adil (lalu bersyukur kepada Allah serta mengesakanNya). Dan sememangnya tiada yang mengingkari bukti-bukti kemurahan Kami melainkan tiap-tiap orang yang bersifat pemungkir janji, lagi amat tidak mengenang budi.', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL),
(31, 33, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَّا يَجْزِي وَالِدٌ عَن وَلَدِهِ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُم بِاللَّهِ الْغَرُورُ', NULL, 'O mankind, fear your Lord and fear a Day when no father will avail his son, nor will a son avail his father at all. Indeed, the promise of Allāh is truth, so let not the worldly life delude you and be not deceived about Allāh by the Deceiver [i.e., Satan].', 'Wahai sekalian manusia, bertaqwalah kepada Tuhan kamu, dan takutilah akan hari (akhirat) yang padanya seseorang ibu atau bapa tidak dapat melepaskan anaknya dari azab dosanya, dan seorang anak pula tidak dapat melepaskan ibu atau bapanya dari azab dosa masing-masing sedikit pun. Sesungguhnya janji Allah itu adalah benar, maka janganlah kamu diperdayakan oleh kehidupan dunia, dan jangan pula kamu diperdayakan oleh bisikan dan ajakan Syaitan yang menyebabkan kamu berani melanggar perintah Allah.', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL),
(31, 34, 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', 'إِنَّ اللَّهَ عِندَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ', NULL, 'Indeed, Allāh [alone] has knowledge of the Hour and sends down the rain and knows what is in the wombs. And no soul perceives what it will earn tomorrow, and no soul perceives in what land it will die. Indeed, Allāh is Knowing and Aware.', 'Sesungguhnya di sisi Allah pengetahuan yang tepat tentang hari kiamat. Dan Dia lah jua yang menurunkan hujan, dan yang mengetahui dengan sebenar-benarnya tentang apa yang ada dalam rahim (ibu yang mengandung). Dan tiada seseorang pun yang betul mengetahui apa yang akan diusahakannya esok (sama ada baik atau jahat); dan tiada seorangpun yang dapat mengetahui di bumi negeri manakah ia akan mati. Sesungguhnya Allah Maha Mengetahui, lagi Amat Meliputi pengetahuanNya.', FALSE, NULL, NULL, 414, 21, 165, 357, FALSE, 0, NULL),
(32, 1, 'الٓمٓ', 'الم', NULL, 'Alif, Lām, Meem.', 'Alif, Laam Miim.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 1, NULL),
(32, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَـٰلَمِينَ', 'تنزيل الكتاب لا ريب فيه من رب العالمين', NULL, '[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds.', 'Diturunkan Al-Quran ini, dengan tidak ada sebarang syak padanya, dari Tuhan yang memelihara dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 8, NULL),
(32, 3, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۚ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'ام يقولون افتراه بل هو الحق من ربك لتنذر قوما ما اتاهم من نذير من قبلك لعلهم يهتدون', NULL, 'Or do they say, "He invented it"? Rather, it is the truth from your Lord, [O Muḥammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided.', '(Orang-orang kafir tidak mengakui hakikat yang demikian) bahkan mereka mengatakan: “Dia lah (Muhammad) yang mengada-adakan Al-Quran menurut rekaannya”. (Dakwaan mereka itu tidaklah benar) bahkan Al-Quran ialah perkara yang benar dari Tuhanmu (wahai Muhammad), supaya engkau memberi ingatan dan amaran kepada kaum (mu) yang telah lama tidak didatangi sebarang pemberi ingatan dan amaran sebelummu, semoga mereka beroleh hidayah petunjuk.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 18, NULL),
(32, 4, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ ۚ أَفَلَا تَتَذَكَّرُونَ', 'الله الذي خلق السماوات والارض وما بينهما في ستة ايام ثم استوى على العرش ما لكم من دونه من ولي ولا شفيع افلا تتذكرون', NULL, 'It is Allāh who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?', 'Allah Tuhan yang menciptakan langit dan bumi serta segala yang ada di antara keduanya dalam enam masa, kemudian Ia bersemayam di atas Arasy; kamu tidak akan beroleh sebarang penolong dan pemberi syafaat selain dari Allah; oleh itu tidakkah kamu mahu insaf dan mengambil iktibar (untuk mencapai keredaanNya)?', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 24, NULL),
(32, 5, 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ', 'يدبر الامر من السماء الى الارض ثم يعرج اليه في يوم كان مقداره الف سنة مما تعدون', NULL, 'He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count.', 'Allah mentadbirkan makhluk-makhlukNya; (bagi melaksanakan tadbirNya itu Ia menurunkan segala sebab dan peraturan) dari langit ke bumi; kemudian diangkat naik kepada pengetahuanNya (segala yang berlaku dari perlaksanaan tadbirNya itu untuk dihakimiNya) pada suatu masa yang (dirasai oleh orang-orang yang bersalah) banyak bilangan tahunnya menurut hitungan masa kamu yang biasa.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 17, NULL),
(32, 6, 'ذَٰلِكَ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'ذلك عالم الغيب والشهادة العزيز الرحيم', NULL, 'That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,', 'Yang demikian sifatnya ialah Tuhan yang mengetahui perkara-perkara yang ghaib dan yang nyata; Yang Maha Kuasa, lagi Maha Mengasihani;', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 6, NULL),
(32, 7, 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ ۖ وَبَدَأَ خَلْقَ ٱلْإِنسَـٰنِ مِن طِينٍ', 'الذي احسن كل شيء خلقه وبدا خلق الانسان من طين', NULL, 'Who perfected everything which He created and began the creation of man from clay.', 'Yang menciptakan tiap-tiap sesuatu dengan sebaik-baiknya, dan dimulakanNya kejadian manusia berasal dari tanah;', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 10, NULL),
(32, 8, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَـٰلَةٍ مِّن مَّآءٍ مَّهِينٍ', 'ثم جعل نسله من سلالة من ماء مهين', NULL, 'Then He made his posterity out of the extract of a liquid disdained.', 'Kemudian Ia menjadikan keturunan manusia itu dari sejenis pati, iaitu dari air (benih) yang sedikit dipandang orang;', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 8, NULL),
(32, 9, 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ ۖ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًا مَّا تَشْكُرُونَ', 'ثم سواه ونفخ فيه من روحه وجعل لكم السمع والابصار والافئدة قليلا ما تشكرون', NULL, 'Then He proportioned him and breathed into him from His [created] soul and made for you hearing and vision and hearts [i.e., intellect]; little are you grateful.', 'Kemudian Ia menyempurnakan kejadiannya, serta meniupkan padanya: roh ciptaanNya. Dan Ia mengurniakan kepada kamu pendengaran dan penglihatan serta hati (akal fikiran), (supaya kamu bersyukur, tetapi) amatlah sedikit kamu bersyukur.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 14, NULL),
(32, 10, 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍۭ ۚ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَـٰفِرُونَ', 'وقالوا ااذا ضللنا في الارض اانا لفي خلق جديد بل هم بلقاء ربهم كافرون', NULL, 'And they say, "When we are lost [i.e., disintegrated] within the earth, will we indeed be [recreated] in a new creation?" Rather, they are, in the meeting with their Lord, disbelievers.', 'Dan mereka (yang kafir) itu berkata: “Adakah apabila kami telah hilang lenyap dalam tanah, kami pula akan hidup semula dalam bentuk kejadian yang baharu? Betulkah demikian?” (Mereka bukan sahaja tidak percaya tentang hidup semula) bahkan mereka tidak percaya tentang pertemuan dengan Tuhannya.', FALSE, NULL, NULL, 415, 21, 165, 358, FALSE, 14, NULL),
(32, 11, '۞ قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'قل يتوفاكم ملك الموت الذي وكل بكم ثم الى ربكم ترجعون', NULL, 'Say, "The angel of death who has been entrusted with you will take you. Then to your Lord you will be returned."', 'Katakanlah (wahai Muhammad); “Nyawa kamu akan diambil oleh Malikil Maut yang ditugaskan berbuat demikian ketika habis ajal kamu, kemudian kamu akan dikembalikan kepada Tuhan kamu (untuk menerima balasan)”.', FALSE, NULL, NULL, 415, 21, 166, 358, FALSE, 11, NULL),
(32, 12, 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَـٰلِحًا إِنَّا مُوقِنُونَ', 'ولو ترى اذ المجرمون ناكسو رءوسهم عند ربهم ربنا ابصرنا وسمعنا فارجعنا نعمل صالحا انا موقنون', NULL, 'If you could but see when the criminals are hanging their heads before their Lord, [saying], "Our Lord, we have seen and heard, so return us [to the world]; we will work righteousness. Indeed, we are [now] certain."', 'Dan (sungguh ngeri) sekiranya engkau melihat ketika orang-orang yang berdosa itu menundukkan kepalanya di hadapan Tuhan mereka (dalam keadaan malu dan hina, sambil merayu): “Wahai Tuhan kami, kami telah melihat dan mendengar dengan sejelas-jelasnya (akan segala yang kami ingkari dahulu); maka kembalikanlah kami ke dunia supaya kami mengerjakan amal-amal yang baik; sesungguhnya kami sekarang telah yakin”.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 16, NULL),
(32, 13, 'وَلَوْ شِئْنَا لَـَٔاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَـٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'ولو شئنا لاتينا كل نفس هداها ولكن حق القول مني لاملان جهنم من الجنة والناس اجمعين', NULL, 'And if We had willed, We could have given every soul its guidance, but the word from Me will come into effect [that] "I will surely fill Hell with jinn and people all together.', 'Dan (bagi menolak rayuan itu Allah Taala berfirman): “Kalaulah Kami telah tetapkan persediaan (memberikan hidayah petunjuk untuk beriman dan beramal soleh kepada tiap-tiap seorang dengan ketiadaan usaha dari masing-masing), nescaya Kami berikan kepada tiap-tiap seorang akan hidayah petunjuknya (sebelum masing-masing meninggal dunia, supaya tidak terkena azab di akhirat); tetapi telah tetap hukuman seksa dariKu: ‘Demi sesungguhnya! Aku akan memenuhi neraka Jahannam dengan semua jin dan manusia (yang pada masa hidupnya tidak berusaha untuk beriman dan beramal soleh)”.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 16, NULL),
(32, 14, 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَآ إِنَّا نَسِينَـٰكُمْ ۖ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', 'فذوقوا بما نسيتم لقاء يومكم هذا انا نسيناكم وذوقوا عذاب الخلد بما كنتم تعملون', NULL, 'So taste [punishment] because you forgot the meeting of this, your Day; indeed, We have [accordingly] forgotten you. And taste the punishment of eternity for what you used to do."', '(Lalu dikatakan kepada mereka: “Oleh sebab kelalaian kamu) maka rasalah azab seksa kerana kamu melupai pertemuan hari kamu ini. Sesungguhnya Kami pun tidak hiraukan keselamatan kamu lagi; dan (dengan yang demikian) rasalah azab yang kekal dengan sebab apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 14, NULL),
(32, 15, 'إِنَّمَا يُؤْمِنُ بِـَٔايَـٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ ۩', 'انما يؤمن باياتنا الذين اذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون', NULL, 'Only those believe in Our verses who, when they are reminded by them, fall down in prostration and exalt [Allāh] with praise of their Lord, and they are not arrogant.', 'Sesungguhnya yang sebenar-benar beriman kepada ayat-ayat keterangan Kami hanyalah orang-orang yang apabila diberi peringatan dan pengajaran dengan ayat-ayat itu, mereka segera merebahkan diri sambil sujud (menandakan taat patuh), dan menggerakkan lidah dengan bertasbih serta memuji Tuhan mereka, dan mereka pula tidak bersikap sombong takbur.', FALSE, NULL, NULL, 416, 21, 166, 359, TRUE, 15, NULL),
(32, 16, 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ', 'تتجافى جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقناهم ينفقون', NULL, 'Their sides part [i.e., they arise] from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend.', 'Mereka merenggangkan diri dari tempat tidur, (sedikit sangat tidur, kerana mengerjakan sembahyang tahajjud dan amal-amal soleh); mereka sentiasa berdoa kepada Tuhan mereka dengan perasaan takut (akan kemurkaanNya) serta dengan perasaan ingin memperolehi lagi (keredaanNya); dan mereka selalu pula mendermakan sebahagian dari apa yang Kami beri kepada mereka.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 11, NULL),
(32, 17, 'فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'فلا تعلم نفس ما اخفي لهم من قرة اعين جزاء بما كانوا يعملون', NULL, 'And no soul knows what has been hidden for them of comfort for eyes [i.e., satisfaction] as reward for what they used to do.', 'Maka tidak ada seseorang pun yang mengetahui satu persatu persediaan yang telah dirahsiakan untuk mereka (dari segala jenis nikmat) yang amat indah dipandang dan mengembirakan, sebagai balasan bagi amal-amal soleh yang mereka telah kerjakan.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 13, NULL),
(32, 18, 'أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا ۚ لَّا يَسْتَوُۥنَ', 'افمن كان مؤمنا كمن كان فاسقا لا يستوون', NULL, 'Then is one who was a believer like one who was defiantly disobedient? They are not equal.', '(Jika demikian halnya) maka adakah orang yang beriman sama seperti orang yang fasik? Mereka tidaklah sama (dalam menerima balasan).', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 8, NULL),
(32, 19, 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ جَنَّـٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', 'اما الذين امنوا وعملوا الصالحات فلهم جنات الماوى نزلا بما كانوا يعملون', NULL, 'As for those who believed and did righteous deeds, for them will be the Gardens of Refuge as accommodation for what they used to do.', 'Adapun orang-orang yang beriman dan beramal soleh, maka mereka akan beroleh Syurga tempat tinggal yang tetap sebagai balasan bagi apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 12, NULL),
(32, 20, 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ ۖ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'واما الذين فسقوا فماواهم النار كلما ارادوا ان يخرجوا منها اعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون', NULL, 'But as for those who defiantly disobeyed, their refuge is the Fire. Every time they wish to emerge from it, they will be returned to it while it is said to them, "Taste the punishment of the Fire which you used to deny."', 'Dan sebaliknya orang-orang yang fasik, maka tempat kediaman mereka ialah neraka; tiap-tiap kali mereka hendak keluar dari neraka itu, mereka dikembalikan kepadanya, serta dikatakan kepada mereka: “Rasalah azab neraka yang kamu sentiasa mendustakannya di dunia dahulu”.', FALSE, NULL, NULL, 416, 21, 166, 359, FALSE, 21, NULL),
(32, 21, 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', 'وَلَنُذِيقَنَّهُم مِّنَ الْعَذَابِ الْأَدْنَىٰ دُونَ الْعَذَابِ الْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And We will surely let them taste the nearer punishment short of the greater punishment that perhaps they will return [i.e., repent].', 'Dan demi sesungguhnya, Kami akan merasakan mereka sedikit dari azab dunia sebelum azab yang besar (di akhirat kelak), supaya mereka rujuk kembali bertaubat.', FALSE, NULL, NULL, 417, 21, 166, 359, FALSE, 0, NULL),
(32, 22, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِآيَاتِ رَبِّهِ ثُمَّ أَعْرَضَ عَنْهَا إِنَّا مِنَ الْمُجْرِمِينَ مُنتَقِمُونَ', NULL, 'And who is more unjust than one who is reminded of the verses of his Lord; then he turns away from them? Indeed We, from the criminals, will take retribution.', 'Dan tidaklah ada yang lebih zalim daripada orang yang diberi ingat dengan ayat-ayat Tuhannya, kemudian ia berpaling daripadanya (dan tetap mengingkarinya); sesungguhnya Kami tetap membalas.', FALSE, NULL, NULL, 417, 21, 166, 359, FALSE, 0, NULL),
(32, 23, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَلَا تَكُن فِي مِرْيَةٍ مِّن لِّقَائِهِ وَجَعَلْنَاهُ هُدًى لِّبَنِي إِسْرَائِيلَ', NULL, 'And We certainly gave Moses the Scripture, so do not be in doubt over his meeting. And We made it [i.e., the Torah] guidance for the Children of Israel.', 'Dan demi sesungguhnya! Kami telah memberi kepada Nabi Musa Kitab Taurat (sebagaimana Kami berikan Al-Quran kepadamu wahai Muhammad), maka janganlah engkau ragu-ragu menyambut dan menerimanya; dan Kami jadikan Kitab Taurat itu hidayah penunjuk bagi kaum Bani Israil.', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 24, 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ', 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ', NULL, 'And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs.', 'Dan Kami jadikan dari kalangan mereka beberapa pemimpin, yang membimbing kaum masing-masing kepada hukum ugama Kami, selama mereka bersikap sabar (dalam menjalankan tugas itu) serta mereka tetap yakin akan ayat-ayat keterangan Kami.', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 25, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ', NULL, 'Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', '(Pertentangan di antara satu golongan dengan yang lain itu) sesungguhnya Tuhanmu sahajalah yang akan memutuskan hukumNya di antara mereka pada hari kiamat, mengenai apa yang mereka berselisihan padanya.', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 26, 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ أَفَلَا يَسْمَعُونَ', 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ أَفَلَا يَسْمَعُونَ', NULL, 'Has it not become clear to them how many generations We destroyed before them, [as] they walk among their dwellings? Indeed in that are signs; then do they not hear?', 'Dan belumkah lagi ternyata kepada mereka (yang kafir itu): bahawa Kami telah binasakan berapa banyak dari kaum-kaum yang kufur ingkar dahulu daripada mereka, padahal mereka sekarang berulang-alik melalui tempat-tempat tinggal kaum-kaum itu? Sesungguhnya kebinasaan kaum-kaum itu mengandungi keterangan-keterangan (untuk mengambil iktibar); oleh itu tidakkah mereka mahu mendengar (dan insaf)?', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 27, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ أَفَلَا يُبْصِرُونَ', 'أَوَلَمْ يَرَوْا أَنَّا نَسُوقُ الْمَاءَ إِلَى الْأَرْضِ الْجُرُزِ فَنُخْرِجُ بِهِ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَامُهُمْ وَأَنفُسُهُمْ أَفَلَا يُبْصِرُونَ', NULL, 'Have they not seen that We drive water [in clouds] to barren land and bring forth thereby crops from which their livestock eat and [they] themselves? Then do they not see?', 'Dan tidakkah mereka (yang tidak mahu taat dan bersyukur) itu melihat bahawasanya Kami mengarahkan turunnya hujan ke bumi yang kering kontang, lalu Kami tumbuhkan dengan air hujan itu tanaman-tanaman, yang daripadanya dimakan oleh binatang-binatang ternak mereka dan mereka sendiri? Maka mengapa mereka tidak mahu memerhati (semuanya itu supaya taat dan bersyukur)?', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 28, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْفَتْحُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When will be this conquest, if you should be truthful?"', 'Dan mereka bertanya: “Bilakah datangnya hari pembukaan bicara yang dikatakan itu jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 29, 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', 'قُلْ يَوْمَ الْفَتْحِ لَا يَنفَعُ الَّذِينَ كَفَرُوا إِيمَانُهُمْ وَلَا هُمْ يُنظَرُونَ', NULL, 'Say, [O Muḥammad], "On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved."', 'Katakanlah (wahai Muhammad): “(Tidak perlu diketahui masa datangnya tetapi mesti dipercayai bahawa) pada hari pembukaan bicara itu, tidak ada gunanya lagi kepada orang-orang kafir kiranya mereka hendak beriman, dan mereka pula tidak akan diberi tempoh (berbuat demikian)”.', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(32, 30, 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', 'فَأَعْرِضْ عَنْهُمْ وَانتَظِرْ إِنَّهُم مُّنتَظِرُونَ', NULL, 'So turn away from them and wait. Indeed, they are waiting.', 'Oleh itu, janganlah engkau hiraukan mereka, dan tunggulah (kesudahan mereka), sesungguhnya mereka pun menunggu (kesudahanmu).', FALSE, NULL, NULL, 417, 21, 166, 360, FALSE, 0, NULL),
(33, 1, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَـٰفِرِينَ وَٱلْمُنَـٰفِقِينَ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'يا ايها النبي اتق الله ولا تطع الكافرين والمنافقين ان الله كان عليما حكيما', NULL, 'O Prophet, fear Allāh and do not obey the disbelievers and the hypocrites. Indeed, Allāh is ever Knowing and Wise.', 'Wahai Nabi! Tetaplah bertaqwa kepada Allah, dan janganlah engkau patuhi kehendak orang-orang kafir dan orang-orang munafik. Sesungguhnya Allah adalah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 13, NULL),
(33, 2, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'واتبع ما يوحى اليك من ربك ان الله كان بما تعملون خبيرا', NULL, 'And follow that which is revealed to you from your Lord. Indeed Allāh is ever, of what you do, Aware.', 'Dan turutlah akan apa yang diwahyukan kepadamu dari Tuhanmu, (dan janganlah menurut adat resam Jahiliyah); sesungguhnya Allah sentiasa Mengetahui dengan mendalam akan apa yang kamu lakukan.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 12, NULL),
(33, 3, 'وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'وتوكل على الله وكفى بالله وكيلا', NULL, 'And rely upon Allāh; and sufficient is Allāh as Disposer of affairs.', 'Dan berserahlah kepada Allah (dan janganlah menumpukan harapanmu kepada yang lain), kerana cukuplah Allah menjadi Pentadbir urusanmu.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 6, NULL),
(33, 4, 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ ۚ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّـٰٓـِٔى تُظَـٰهِرُونَ مِنْهُنَّ أُمَّهَـٰتِكُمْ ۚ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ۚ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ ۖ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', 'ما جعل الله لرجل من قلبين في جوفه وما جعل ازواجكم اللائي تظاهرون منهن امهاتكم وما جعل ادعياءكم ابناءكم ذلكم قولكم بافواهكم والله يقول الحق وهو يهدي السبيل', NULL, 'Allāh has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And He has not made your claimed [i.e., adopted] sons your [true] sons. That is [merely] your saying by your mouths, but Allāh says the truth, and He guides to the [right] way.', '(Diperintahkan dengan yang demikian kerana) Allah tidak sekali-kali menjadikan seseorang mempunyai dua hati dalam rongga dadanya; dan Ia tidak menjadikan isteri-isteri yang kamu “zihar” kan itu sebagai ibu kamu; dan Ia juga tidak menjadikan anak-anak angkat kamu, sebagai anak kamu sendiri. Segala yang kamu dakwakan mengenai perkara-perkara) yang tersebut itu hanyalah perkataan kamu dengan mulut kamu sahaja. Dan (ingatlah) Allah menerangkan yang benar dan Dia lah jua yang memimpin ke jalan yang betul.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 28, NULL),
(33, 5, 'ٱدْعُوهُمْ لِـَٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ ۚ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ ۚ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَـٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'ادعوهم لابائهم هو اقسط عند الله فان لم تعلموا اباءهم فاخوانكم في الدين ومواليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما', NULL, 'Call them by [the names of] their fathers; it is more just in the sight of Allāh. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allāh Forgiving and Merciful.', 'Panggilah anak-anak angkat itu dengan ber”bin”kan kepada bapa-bapa mereka sendiri; cara itulah yang lebih adil di sisi Allah. Dalam pada itu, jika kamu tidak mengetahui bapa-bapa mereka, maka panggilah mereka sebagai saudara-saudara kamu yang seugama dan sebagai “maula-maula” kamu. Dan kamu pula tidak dikira berdosa dalam perkara yang kamu tersilap melakukannya, tetapi (yang dikira berdosa itu ialah perbuatan) yang disengajakan oleh hati kamu melakukannya. Dan (ingatlah Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 28, NULL),
(33, 6, 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ ۖ وَأَزْوَٰجُهُۥٓ أُمَّهَـٰتُهُمْ ۗ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَـٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَـٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَـٰبِ مَسْطُورًا', 'النبي اولى بالمؤمنين من انفسهم وازواجه امهاتهم واولو الارحام بعضهم اولى ببعض في كتاب الله من المؤمنين والمهاجرين الا ان تفعلوا الى اوليائكم معروفا كان ذلك في الكتاب مسطورا', NULL, 'The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allāh than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed.', 'Nabi itu lebih menolong dan lebih menjaga kebaikan orang-orang yang beriman daripada diri mereka sendiri; dan isteri-isterinya adalah menjadi ibu mereka. Dan orang-orang yang mempunyai pertalian kerabat, setengahnya lebih berhak (mewarisi) akan setengahnya yang lain - menurut (hukum) Kitab Allah - daripada orang-orang yang beriman dan orang-orang Muhajirin (yang bukan kerabatnya), kecuali kalau kamu hendak berbuat baik kepada sahabat-sahabat karib kamu. Hukum yang demikian itu adalah tertulis dalam Kitab Allah.', FALSE, NULL, NULL, 418, 21, 167, 361, FALSE, 29, NULL),
(33, 7, 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَـٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَـٰقًا غَلِيظًا', 'واذ اخذنا من النبيين ميثاقهم ومنك ومن نوح وابراهيم وموسى وعيسى ابن مريم واخذنا منهم ميثاقا غليظا', NULL, 'And [mention, O Muḥammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant', '(Teruslah bertaqwa kepada Kami) dan (ingatlah) ketika Kami mengambil dari Nabi-nabi (umumnya): perjanjian setia mereka, dan (khasnya) dari engkau sendiri (wahai Muhammad), dan dari Nabi Nuh, dan Nabi Ibrahim, dan Nabi Musa, serta. Nabi Isa ibni Maryam; dan Kami telah mengambil dari mereka: perjanjian setia yang teguh (bagi menyempurnakan apa yang ditugaskan kepada mereka);', FALSE, NULL, NULL, 419, 21, 167, 361, FALSE, 17, NULL),
(33, 8, 'لِّيَسْـَٔلَ ٱلصَّـٰدِقِينَ عَن صِدْقِهِمْ ۚ وَأَعَدَّ لِلْكَـٰفِرِينَ عَذَابًا أَلِيمًا', 'ليسال الصادقين عن صدقهم واعد للكافرين عذابا اليما', NULL, 'That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment.', '(Tuhan berbuat demikian) supaya Ia menyoal orang-orang yang benar beriman tentang kebenaran iman mereka (untuk menyempurnakan balasan baik mereka); dan (sebaliknya) Ia telah menyediakan bagi orang-orang yang kafir, azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 419, 21, 167, 361, FALSE, 8, NULL),
(33, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'يا ايها الذين امنوا اذكروا نعمة الله عليكم اذ جاءتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا', NULL, 'O you who have believed, remember the favor of Allāh upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allāh, of what you do, Seeing.', 'Wahai orang-orang yang beriman, kenangkanlah nikmat Allah yang dilimpahkanNya kepada kamu. Semasa kamu didatangi tentera (Al-Ahzaab), lalu Kami hantarkan kepada mereka angin ribut (yang kencang) serta angkatan tentera (dari malaikat) yang kamu tidak dapat melihatnya. Dan (ingatlah) Allah sentiasa melihat apa yang kamu lakukan.', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 21, NULL),
(33, 10, 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَـٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', 'اذ جاءوكم من فوقكم ومن اسفل منكم واذ زاغت الابصار وبلغت القلوب الحناجر وتظنون بالله الظنونا', NULL, '[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats, and you assumed about Allāh [various] assumptions.', 'Masa itu ialah masa tentera musuh datang melanggar kamu dari sebelah hulu dan dari sebelah hilir (tempat pertahanan) kamu; dan masa itu ialah masa pemandangan mata kamu tidak berketentuan arah (kerana gempar dan bingung) serta hati pun resah gelisah (kerana cemas takut), dan kamu masing-masing pula menyangka terhadap Allah dengan berbagai-bagai sangkaan.', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 16, NULL),
(33, 11, 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا', 'هنالك ابتلي المؤمنون وزلزلوا زلزالا شديدا', NULL, 'There the believers were tested and shaken with a severe shaking.', 'Pada saat itulah diuji orang-orang yang beriman, dan digoncangkan perasaan dan pendiriannya dengan goncangan yang amat dahsyat.', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 6, NULL),
(33, 12, 'وَإِذْ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا', 'واذ يقول المنافقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا', NULL, 'And [remember] when the hypocrites and those in whose hearts is disease said, "Allāh and His Messenger did not promise us except delusion,"', 'Dan lagi masa itu ialah masa orang-orang munafik dan orang-orang yang tidak sihat dan tidak kuat iman dalam hatinya berkata: “Allah dan RasulNya tidak menjanjikan kepada kita melainkan perkara yang memperdayakan sahaja”.', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 13, NULL),
(33, 13, 'وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَـٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ ۚ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ ۖ إِن يُرِيدُونَ إِلَّا فِرَارًا', 'واذ قالت طائفة منهم يا اهل يثرب لا مقام لكم فارجعوا ويستاذن فريق منهم النبي يقولون ان بيوتنا عورة وما هي بعورة ان يريدون الا فرارا', NULL, 'And when a faction of them said, "O people of Yathrib, there is no stability for you [here], so return [home]." And a party of them asked permission of the Prophet, saying, "Indeed, our houses are exposed [i.e., unprotected]," while they were not exposed. They did not intend except to flee.', 'Dan juga masa itu ialah masa segolongan di antara mereka berkata: “Wahai penduduk Yathrib, tempat ini bukan tempat bagi kamu (untuk berjuang di sini), oleh itu baliklah”. Dan sebahagian dari mereka pula meminta izin kepada Nabi (hendak balik) sambil berkata: “Sesungguhnya rumah-rumah kami memerlukan perlindungan”, pada hal ia tidak memerlukan perlindungan. Mereka hanya bertujuan hendak melarikan diri (dari berjuang menegakkan Islam).', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 25, NULL),
(33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَـَٔاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا', 'ولو دخلت عليهم من اقطارها ثم سئلوا الفتنة لاتوها وما تلبثوا بها الا يسيرا', NULL, 'And if they had been entered upon from all its [surrounding] regions and fitnah [i.e., disbelief] had been demanded of them, they would have done it and not hesitated over it except briefly.', 'Dan kalaulah tempat-tempat kediaman mereka itu diserang oleh musuh dari segala penjurunya, kemudian mereka diajak berpaling tadah menentang Islam, sudah tentu mereka akan melakukannya, dan mereka tidak bertangguh lagi tentang itu melainkan sebentar sahaja.', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 14, NULL),
(33, 15, 'وَلَقَدْ كَانُوا۟ عَـٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَـٰرَ ۚ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا', 'ولقد كانوا عاهدوا الله من قبل لا يولون الادبار وكان عهد الله مسئولا', NULL, 'And they had already promised Allāh before not to turn their backs [i.e., flee]. And ever is the promise to Allāh [that about which one will be] questioned.', 'Pada hal sesungguhnya mereka telahpun mengikat janji dengan Allah sebelum itu, iaitu mereka tidak akan berpaling undur (dari medan perang yang mereka hadiri). Dan (ingatlah) janji setia dengan Allah itu akan ditanya kelak (tentang penyempurnaannya).', FALSE, NULL, NULL, 419, 21, 167, 362, FALSE, 13, NULL),
(33, 16, 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا', 'قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا', NULL, 'Say, [O Muḥammad], "Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little."', 'Katakanlah (wahai Muhammad): “Kalaulah kamu melarikan diri dari kematian atau dari pembunuhan maka perbuatan melarikan diri itu tidak sekali-kali mendatangkan faedah kepada kamu; dan kalaulah kamu pada hari ini terlepas sekalipun, maka kamu tidak juga akan menikmati kesenangan hidup melainkan sedikit masa sahaja”.', FALSE, NULL, NULL, 420, 21, 167, 362, FALSE, 15, NULL),
(33, 17, 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً ۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'قل من ذا الذي يعصمكم من الله ان اراد بكم سوءا او اراد بكم رحمة ولا يجدون لهم من دون الله وليا ولا نصيرا', NULL, 'Say, "Who is it that can protect you from Allāh if He intends for you an ill or intends for you a mercy?" And they will not find for themselves besides Allāh any protector or any helper.', 'Katakanlah: “Siapakah yang dapat melindungi kamu dari kemurkaan Allah jika Ia mahu menimpakan bala bencana kepada kamu, atau (siapakah yang dapat menahan kemurahan Allah) jika Ia hendak memberikan rahmat kepada kamu?” Dan (ingatkanlah) mereka (yang munafik) itu: bahawa mereka tidak akan beroleh sesiapapun - yang lain dari Allah - yang akan menjadi pelindung atau penolong mereka.', FALSE, NULL, NULL, 420, 21, 167, 362, FALSE, 24, NULL),
(33, 18, '۞ قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا ۖ وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', 'قد يعلم الله المعوقين منكم والقائلين لاخوانهم هلم الينا ولا ياتون الباس الا قليلا', NULL, 'Already Allāh knows the hinderers among you and those [hypocrites] who say to their brothers, "Come to us," and do not go to battle, except for a few,', 'Sesungguhnya Allah mengetahui akan orang-orang (munafik) yang menghalangi di antara kamu, dan orang-orang yang berkata kepada saudara-saudaranya: “Marilah bersatu dengan kami”, sedang mereka tidak turut berperang melainkan sebentar sahaja.', FALSE, NULL, NULL, 420, 21, 168, 362, FALSE, 14, NULL),
(33, 19, 'أَشِحَّةً عَلَيْكُمْ ۖ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ ۚ أُو۟لَـٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَـٰلَهُمْ ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'اشحة عليكم فاذا جاء الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشى عليه من الموت فاذا ذهب الخوف سلقوكم بالسنة حداد اشحة على الخير اولئك لم يؤمنوا فاحبط الله اعمالهم وكان ذلك على الله يسيرا', NULL, 'Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allāh has rendered their deeds worthless, and ever is that, for Allāh, easy.', 'Mereka bersikap bakhil kedekut terhadap kamu (wahai orang-orang mukmin untuk memberikan sebarang pertolongan); dalam pada itu apabila datang (ancaman musuh yang menimbulkan) ketakutan, engkau melihat mereka memandang kepadamu (wahai Muhammad, meminta pertolonganmu) dengan keadaan mata mereka berputar seperti orang yang pengsan semasa hampir mati. Kemudian apabila hilang perasaan takut itu, mereka mencela kamu dengan lidah yang tajam, sambil mereka tamakan kebaikan (yang diberikan Allah kepada kamu). Mereka itu tidak beriman, lalu Allah gugurkan amal-amal mereka. Dan yang demikian itu adalah mudah bagi Allah melaksanakannya.', FALSE, NULL, NULL, 420, 21, 168, 362, FALSE, 35, NULL),
(33, 20, 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ ۖ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ ۖ وَلَوْ كَانُوا۟ فِيكُم مَّا قَـٰتَلُوٓا۟ إِلَّا قَلِيلًا', 'يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسالون عن انبائكم ولو كانوا فيكم ما قاتلوا الا قليلا', NULL, 'They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little.', 'Mereka menyangka bahawa tentera “Al-Ahzaab” itu belum pergi; dan kalaulah tentera Al-Ahzaab datang semula, tentulah mereka suka kalau mereka tinggal jauh di desa-desa bersama-sama orang-orang Arab Badwi sambil bertanyakan berita mengenai kamu; dan kalaulah mereka ada bersama-sama kamu (pada ketika itu), mereka tidak akan turut berperang melainkan sebentar sahaja.', FALSE, NULL, NULL, 420, 21, 168, 362, FALSE, 23, NULL),
(33, 21, 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا', 'لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا', NULL, 'There has certainly been for you in the Messenger of Allāh an excellent pattern for anyone whose hope is in Allāh and the Last Day and [who] remembers Allāh often.', 'Demi sesungguhnya, adalah bagi kamu pada diri Rasulullah itu contoh ikutan yang baik, iaitu bagi orang yang sentiasa mengharapkan (keredaan) Allah dan (balasan baik) hari akhirat, serta ia pula menyebut dan mengingati Allah banyak-banyak (dalam masa susah dan senang)', FALSE, NULL, NULL, 420, 21, 168, 363, FALSE, 0, NULL),
(33, 22, 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا', 'وَلَمَّا رَأَى الْمُؤْمِنُونَ الْأَحْزَابَ قَالُوا هَٰذَا مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ وَصَدَقَ اللَّهُ وَرَسُولُهُ وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا', NULL, 'And when the believers saw the companies, they said, "This is what Allāh and His Messenger had promised us, and Allāh and His Messenger spoke the truth." And it increased them only in faith and acceptance.', 'Dan pada masa orang-orang yang beriman melihat tentera Al-Ahzaab, berkatalah mereka: “Inilah yang telah dijanjikan Allah dan RasulNya kepada kami dan benarlah (apa yang telah dijanjikan) Allah dan RasulNya”. Dan (angkatan tentera musuh yang mereka lihat) itu tidak memberi sebarang kesan kepada mereka selain daripada menambahkan iman dan penyerahan diri mereka bulat-bulat kepada Allah.', FALSE, NULL, NULL, 420, 21, 168, 363, FALSE, 0, NULL),
(33, 23, 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا۟ تَبْدِيلًا', 'مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا', NULL, 'Among the believers are men true to what they promised Allāh. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -', 'Di antara orang-orang yang beriman itu, ada yang bersikap benar menunaikan apa yang telah dijanjikannya kepada Allah (untuk berjuang membela Islam); maka di antara mereka ada yang telah selesai menjalankan janjinya itu (lalu gugur syahid), dan di antaranya ada yang menunggu giliran; dan mereka pula tidak mengubah (apa yang mereka janjikan itu) sedikitpun.', FALSE, NULL, NULL, 421, 21, 168, 363, FALSE, 0, NULL),
(33, 24, 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'لِّيَجْزِيَ اللَّهُ الصَّادِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ الْمُنَافِقِينَ إِن شَاءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا', NULL, 'That Allāh may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allāh is ever Forgiving and Merciful.', '(Berlakunya yang demikian) supaya Allah membalas orang-orang yang benar disebabkan kebenaran mereka, dan menyeksa orang-orang yang munafik jika Ia kehendaki, atau Ia menerima taubat mereka. Sesungguhnya Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 421, 21, 168, 363, FALSE, 0, NULL),
(33, 25, 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا', 'وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا', NULL, 'And Allāh repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allāh for the believers in battle, and ever is Allāh Powerful and Exalted in Might.', 'Dan Allah telah menghalau kembali (angkatan tentera) orang-orang yang kafir itu (ke tempat masing-masing) dengan keadaan mereka geram marah (kerana gagal dan hampa), mereka tidak mendapat sebarang keuntungan. Dan Allah selamatkan orang-orang yang beriman dari bencana menghadapi peperangan itu. Dan (ingatlah) adalah Allah Maha Kuat, lagi Maha Kuasa.', FALSE, NULL, NULL, 421, 21, 168, 363, FALSE, 0, NULL),
(33, 26, 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', 'وَأَنزَلَ الَّذِينَ ظَاهَرُوهُم مِّنْ أَهْلِ الْكِتَابِ مِن صَيَاصِيهِمْ وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', NULL, 'And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party [i.e., their men] you killed, and you took captive a party [i.e., the women and children].', 'Dan Ia menurunkan golongan Ahli Kitab (kaum Yahudi) yang membantu tentera musuh itu, dari benteng-benteng mereka (menyerah diri), setelah diisikanNya hati mereka dengan perasaan gerun. (Lalu mereka diadili dan dijatuhkan (hukuman); sebahagian di antaranya kamu bunuh, dan sebahagian lagi kamu tawan.', FALSE, NULL, NULL, 421, 21, 168, 363, FALSE, 0, NULL),
(33, 27, 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَارَهُمْ وَأَمْوَالَهُمْ وَأَرْضًا لَّمْ تَطَئُوهَا وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرًا', NULL, 'And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allāh, over all things, competent.', 'Dan Ia menjadikan kamu mewarisi tanah-tanah dan rumah-rumah serta harta benda mereka, dan juga tanah-tanah (di negeri-negeri lain) yang belum kamu menjejaknya. Dan (ingatlah) adalah Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 421, 21, 168, 363, FALSE, 0, NULL),
(33, 28, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', 'يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', NULL, 'O Prophet, say to your wives, "If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release.', 'Wahai Nabi, katakanlah kepada isteri-isterimu: “Sekiranya kamu semua mahukan kehidupan dunia (yang mewah) dan perhiasannya (yang indah), maka marilah supaya aku berikan kepada kamu pemberian mut''ah (sagu hati), dan aku lepaskan kamu dengan cara yang sebaik-baiknya.', FALSE, NULL, NULL, 421, 21, 168, 364, FALSE, 0, NULL),
(33, 29, 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا', 'وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنكُنَّ أَجْرًا عَظِيمًا', NULL, 'But if you should desire Allāh and His Messenger and the home of the Hereafter - then indeed, Allāh has prepared for the doers of good among you a great reward."', '“Dan sekiranya kamu semua mahukan (keredaan) Allah dan RasulNya serta (nikmat kemewahan) di negeri akhirat maka sesungguhnya Allah menyediakan bagi orang-orang yang berbuat baik di antara kamu: pahala yang besar”.', FALSE, NULL, NULL, 421, 21, 168, 364, FALSE, 0, NULL),
(33, 30, 'يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'يَا نِسَاءَ النَّبِيِّ مَن يَأْتِ مِنكُنَّ بِفَاحِشَةٍ مُّبَيِّنَةٍ يُضَاعَفْ لَهَا الْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا', NULL, 'O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allāh, easy.', 'Wahai isteri-isteri Nabi, sesiapa di antara kamu yang melakukan sesuatu perbuatan keji yang nyata, nescaya akan digandakan azab seksa baginya dua kali ganda. Dan (hukuman) yang demikian itu adalah mudah bagi Allah melaksanakannya.', FALSE, NULL, NULL, 421, 21, 168, 364, FALSE, 0, NULL),
(33, 31, 'وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', 'وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِ وَتَعْمَلْ صَالِحًا نُّؤْتِهَا أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', NULL, 'And whoever of you devoutly obeys Allāh and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision.', 'Dan sesiapa di antara kamu semua tetap taat kepada Allah dan RasulNya serta mengerjakan amal yang soleh, Kami akan beri kepadanya pahala amalnya itu dua kali ganda, dan Kami sediakan baginya limpah kurnia yang mulia.', FALSE, NULL, NULL, 422, 22, 169, 364, FALSE, 0, NULL),
(33, 32, 'يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', 'يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِّنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', NULL, 'O wives of the Prophet, you are not like anyone among women. If you fear Allāh, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech.', 'Wahai isteri-isteri Nabi, kamu semua bukanlah seperti mana-mana perempuan yang lain kalau kamu tetap bertaqwa. Oleh itu janganlah kamu berkata-kata dengan lembut manja (semasa bercakap dengan lelaki asing) kerana yang demikian boleh menimbulkan keinginan orang yang ada penyakit dalam hatinya (menaruh tujuan buruk kepada kamu), dan sebaliknya berkatalah dengan kata-kata yang baik (sesuai dan sopan).', FALSE, NULL, NULL, 422, 22, 169, 364, FALSE, 0, NULL),
(33, 33, 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', 'وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَىٰ وَأَقِمْنَ الصَّلَاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُ إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', NULL, 'And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakāh and obey Allāh and His Messenger. Allāh intends only to remove from you the impurity [of sin], O people of the [Prophet''s] household, and to purify you with [extensive] purification.', 'Dan hendaklah kamu tetap diam di rumah kamu serta janganlah kamu mendedahkan diri seperti yang dilakukan oleh orang-orang Jahiliyah zaman dahulu; dan dirikanlah sembahyang serta berilah zakat; dan taatlah kamu kepada Allah dan RasulNya. Sesungguhnya Allah (perintahkan kamu dengan semuanya itu) hanyalah kerana hendak menghapuskan perkara-perkara yang mencemarkan diri kamu - wahai “AhlulBait” dan hendak membersihkan kamu sebersih-bersihnya (dari segala perkara yang keji).', FALSE, NULL, NULL, 422, 22, 169, 364, FALSE, 0, NULL),
(33, 34, 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', 'وَاذْكُرْنَ مَا يُتْلَىٰ فِي بُيُوتِكُنَّ مِنْ آيَاتِ اللَّهِ وَالْحِكْمَةِ إِنَّ اللَّهَ كَانَ لَطِيفًا خَبِيرًا', NULL, 'And remember what is recited in your houses of the verses of Allāh and wisdom. Indeed, Allāh is ever Subtle and Aware.', 'Dan ingatlah (serta amalkanlah) apa yang dibaca di rumah kamu dari ayat-ayat Allah (Al-Quran) dan hikmah pengetahuan (hadis-hadis Rasulullah). Sesungguhnya Allah Maha Halus tadbirNya, lagi Maha Mendalam pengetahuanNya.', FALSE, NULL, NULL, 422, 22, 169, 364, FALSE, 0, NULL),
(33, 35, 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', 'إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ وَالصَّادِقِينَ وَالصَّادِقَاتِ وَالصَّابِرِينَ وَالصَّابِرَاتِ وَالْخَاشِعِينَ وَالْخَاشِعَاتِ وَالْمُتَصَدِّقِينَ وَالْمُتَصَدِّقَاتِ وَالصَّائِمِينَ وَالصَّائِمَاتِ وَالْحَافِظِينَ فُرُوجَهُمْ وَالْحَافِظَاتِ وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', NULL, 'Indeed, the Muslim men and Muslim women, the believing men and believing women, the obedient men and obedient women, the truthful men and truthful women, the patient men and patient women, the humble men and humble women, the charitable men and charitable women, the fasting men and fasting women, the men who guard their private parts and the women who do so, and the men who remember Allāh often and the women who do so - for them Allāh has prepared forgiveness and a great reward.', 'Sesungguhnya orang-orang lelaki yang Islam serta orang-orang perempuan yang Islam, dan orang-orang lelaki yang beriman serta orang-orang perempuan yang beriman, dan orang-orang lelaki yang taat serta orang-orang perempuan yang taat, dan orang-orang lelaki yang benar serta orang-orang perempuan yang benar, dan orang-orang lelaki yang sabar serta orang-orang perempuan yang sabar, dan orang-orang lelaki yang merendah diri (kepada Allah) serta orang-orang perempuan yang merendah diri (kepada Allah), dan orang-orang lelaki yang bersedekah serta orang-orang perempuan yang bersedekah, dan orang-orang lelaki yang berpuasa serta orang-orang perempuan yang berpuasa, dan orang-orang lelaki yang memelihara kehormatannya serta orang-orang perempuan yang memelihara kehormatannya, dan orang-orang lelaki yang menyebut nama Allah banyak-banyak serta orang-orang perempuan yang menyebut nama Allah banyak-banyak, Allah telah menyediakan bagi mereka semuanya keampunan dan pahala yang besar.', FALSE, NULL, NULL, 422, 22, 169, 365, FALSE, 0, NULL),
(33, 36, 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا', 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَن يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ اللَّهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلَالًا مُّبِينًا', NULL, 'It is not for a believing man or a believing woman, when Allāh and His Messenger have decided a matter, that they should [thereafter] have any choice about their affair. And whoever disobeys Allāh and His Messenger has certainly strayed into clear error.', 'Dan tidaklah harus bagi orang-orang yang beriman, lelaki dan perempuan - apabila Allah dan RasulNya menetapkan keputusan mengenai sesuatu perkara - (tidaklah harus mereka) mempunyai hak memilih ketetapan sendiri mengenai urusan mereka. Dan sesiapa yang tidak taat kepada hukum Allah dan RasulNya maka sesungguhnya ia telah sesat dengan kesesatan yang jelas nyata.', FALSE, NULL, NULL, 423, 22, 169, 365, FALSE, 0, NULL),
(33, 37, 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 'وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَاهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَاكَهَا لِكَيْ لَا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ فِي أَزْوَاجِ أَدْعِيَائِهِمْ إِذَا قَضَوْا مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ اللَّهِ مَفْعُولًا', NULL, 'And [remember, O Muḥammad], when you said to the one on whom Allāh bestowed favor and you bestowed favor, "Keep your wife and fear Allāh," while you concealed within yourself that which Allāh is to disclose. And you feared the people, while Allāh has more right that you fear Him. So when Zayd had no longer any need for her, We married her to you in order that there not be upon the believers any discomfort [i.e., guilt] concerning the wives of their claimed [i.e., adopted] sons when they no longer have need of them. And ever is the command [i.e., decree] of Allāh accomplished.', 'Dan (ingatlah wahai Muhammad) ketika engkau berkata kepada orang yang telah dikurniakan oleh Allah (dengan nikmat Islam) dan yang engkau juga telah berbuat baik kepadanya: “Jangan ceraikan isterimu itu dan bertaqwalah kepada Allah”, sambil engkau menyembunyikan dalam hatimu perkara yang Allah akan menyatakannya; dan engkau pula takut kepada (cacian manusia padahal Allah jualah yang berhak engkau takuti (melanggar perintahNya). Kemudian setelah Zaid selesai habis kemahuannya terhadap isterinya (dengan menceraikannya), Kami kahwinkan engkau dengannya supaya tidak ada keberatan atas orang-orang yang beriman untuk berkahwin dengan isteri-isteri anak-anak angkat mereka, apabila anak-anak angkat itu telah selesai habis kemahuannya terhadap isterinya (lalu menceraikannya). Dan sememangnya perkara yang dikehendaki Allah itu tetap berlaku.', FALSE, NULL, NULL, 423, 22, 169, 365, FALSE, 0, NULL),
(33, 38, 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا', 'مَّا كَانَ عَلَى النَّبِيِّ مِنْ حَرَجٍ فِيمَا فَرَضَ اللَّهُ لَهُ سُنَّةَ اللَّهِ فِي الَّذِينَ خَلَوْا مِن قَبْلُ وَكَانَ أَمْرُ اللَّهِ قَدَرًا مَّقْدُورًا', NULL, 'There is not to be upon the Prophet any discomfort concerning that which Allāh has imposed upon him. [This is] the established way of Allāh with those [prophets] who have passed on before. And ever is the command of Allāh a destiny decreed.', 'Tidaklah ada sebarang keberatan yang ditanggung oleh Nabi dalam melaksanakan perkara yang telah ditetapkan Allah baginya. (Yang demikian itu) adalah menurut peraturan Allah yang tetap, yang berlaku juga kepada Nabi-nabi yang telah lalu. Dan (ingatlah) perintah Allah itu adalah satu ketetapan yang ditentukan berlakunya.', FALSE, NULL, NULL, 423, 22, 169, 365, FALSE, 0, NULL),
(33, 39, 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'الَّذِينَ يُبَلِّغُونَ رِسَالَاتِ اللَّهِ وَيَخْشَوْنَهُ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا اللَّهَ وَكَفَىٰ بِاللَّهِ حَسِيبًا', NULL, '[Allāh praises] those who convey the messages of Allāh and fear Him and do not fear anyone but Allāh. And sufficient is Allāh as Accountant.', '(Nabi-nabi yang telah lalu itu) ialah orang-orang yang menyampaikan syariat Allah serta mereka takut melanggar perintahNya, dan mereka pula tidak takut kepada sesiapa pun melainkan kepada Allah. Dan cukuplah Allah menjadi Penghitung (segala yang dilakukan oleh makhluk-makhlukNya untuk membalas mereka).', FALSE, NULL, NULL, 423, 22, 169, 365, FALSE, 0, NULL),
(33, 40, 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', 'مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ عَلِيمًا', NULL, 'Muḥammad is not the father of [any] one of your men, but [he is] the Messenger of Allāh and seal [i.e., last] of the prophets. And ever is Allāh, of all things, Knowing.', 'Bukanlah Nabi Muhammad itu (dengan sebab ada anak angkatnya) menjadi bapa yang sebenar bagi seseorang dari orang lelaki kamu, tetapi ia adalah Rasul Allah dan kesudahan segala Nabi-nabi. Dan (ingatlah) Allah adalah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 423, 22, 169, 365, FALSE, 0, NULL),
(33, 41, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا', NULL, 'O you who have believed, remember Allāh with much remembrance', 'Wahai orang-orang yang beriman, (untuk bersyukur kepada Allah) ingatlah serta sebutlah nama Allah dengan ingatan serta sebutan yang sebanyak-banyaknya;', FALSE, NULL, NULL, 423, 22, 169, 366, FALSE, 0, NULL),
(33, 42, 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', NULL, 'And exalt Him morning and afternoon.', 'Dan bertasbihlah kamu kepadaNya pada waktu pagi dan petang.', FALSE, NULL, NULL, 423, 22, 169, 366, FALSE, 0, NULL),
(33, 43, 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا', 'هُوَ الَّذِي يُصَلِّي عَلَيْكُمْ وَمَلَائِكَتُهُ لِيُخْرِجَكُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا', NULL, 'It is He who confers blessing upon you, and His angels [ask Him to do so] that He may bring you out from darknesses into the light. And ever is He, to the believers, Merciful.', 'Dia lah yang memberi rahmat kepada kamu - dan malaikatNya pula (berdoa bagi kamu) - untuk mengeluarkan kamu dari gelap-gelita (kufur dan maksiat) kepada cahaya yang terang-benderang (iman dari taat); dan adalah Ia sentiasa Melimpah-limpah rahmatNya kepada orang-orang yang beriman (di dunia dan di akhirat).', FALSE, NULL, NULL, 423, 22, 169, 366, FALSE, 0, NULL),
(33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُ سَلَامٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', NULL, 'Their greeting the Day they meet Him will be, "Peace." And He has prepared for them a noble reward.', 'Sambutan penghormatan yang akan diberi Tuhan kepada mereka semasa menemuiNya ialah ucapan “Salam” (selamat sejahtera); dan Ia telah menyediakan untuk mereka pahala balasan yang mulia.', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 45, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا', NULL, 'O Prophet, indeed We have sent you as a witness and a bringer of good tidings and a warner', 'Wahai Nabi, sesungguhnya Kami mengutusmu sebagai saksi (terhadap umatmu), dan pembawa berita gembira (kepada orang-orang yang beriman) serta pemberi amaran (kepada orang-orang yang ingkar).', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 46, 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا', 'وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِ وَسِرَاجًا مُّنِيرًا', NULL, 'And one who invites to Allāh, by His permission, and an illuminating lamp.', 'Dan juga sebagai penyeru (umat manusia seluruhnya) kepada ugama Allah dengan taufiq yang diberiNya; dan sebagai lampu yang menerangi.', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 47, 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا', 'وَبَشِّرِ الْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ اللَّهِ فَضْلًا كَبِيرًا', NULL, 'And give good tidings to the believers that they will have from Allāh great bounty.', 'Dan (dengan itu) sampaikanlah berita yang mengembirakan kepada orang-orang yang beriman, bahawa sesungguhnya mereka akan beroleh limpah kurnia yang besar dari Allah.', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 48, 'وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'وَلَا تُطِعِ الْكَافِرِينَ وَالْمُنَافِقِينَ وَدَعْ أَذَاهُمْ وَتَوَكَّلْ عَلَى اللَّهِ وَكَفَىٰ بِاللَّهِ وَكِيلًا', NULL, 'And do not obey the disbelievers and the hypocrites and disregard their annoyance, and rely upon Allāh. And sufficient is Allāh as Disposer of affairs.', 'Dan janganlah engkau menurut kehendak orang-orang kafir dan orang-orang munafik dan janganlah engkau hiraukan usikan dan celaan mereka, serta berserahlah kepada Allah (memelihara keadaanmu); dan cukuplah Allah menjadi Pelindung (yang menyelamatkanmu).', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 49, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', NULL, 'O you who have believed, when you marry believing women and then divorce them before you have touched them [i.e., consummated the marriage], then there is not for you any waiting period to count concerning them. So provide for them and give them a gracious release.', 'Wahai orang-orang yang beriman, apabila kamu berkahwin dengan perempuan-perempuan yang beriman, kemudian kamu ceraikan mereka sebelum kamu menyentuhnya, maka tiadalah kamu berhak terhadap mereka mengenai sebarang idah yang kamu boleh hitungkan masanya. Oleh itu, berilah “mut''ah” (pemberian sagu hati) kepada mereka, dan lepaskanlah mereka dengan cara yang sebaik-baiknya.', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 50, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'يَا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللَّاتِي آتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّاتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَالَاتِكَ اللَّاتِي هَاجَرْنَ مَعَكَ وَامْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ إِنْ أَرَادَ النَّبِيُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ الْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِي أَزْوَاجِهِمْ وَمَا مَلَكَتْ أَيْمَانُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'O Prophet, indeed We have made lawful to you your wives to whom you have given their due compensation and those your right hand possesses from what Allāh has returned to you [of captives] and the daughters of your paternal uncles and the daughters of your paternal aunts and the daughters of your maternal uncles and the daughters of your maternal aunts who emigrated with you and a believing woman if she gives herself to the Prophet [and] if the Prophet wishes to marry her; [this is] only for you, excluding the [other] believers. We certainly know what We have made obligatory upon them concerning their wives and those their right hands possess, [but this is for you] in order that there will be upon you no discomfort [i.e., difficulty]. And ever is Allāh Forgiving and Merciful.', 'Wahai Nabi, sesungguhnya Kami telah halalkan bagimu isteri-isterimu yang engkau berikan maskahwinnya, dan hamba-hamba perempuan yang engkau miliki dari apa yang telah dikurniakan Allah kepadamu sebagai tawanan perang; dan (Kami telah halalkan bagimu berkahwin dengan sepupu-sepupumu, iaitu): anak-anak perempuan bapa saudaramu (dari sebelah bapa) serta anak-anak perempuan emak saudaramu (dari sebelah bapa), dan anak-anak perempuan bapa saudaramu (dari sebelah ibu) serta anak-anak perempuan emak saudaramu (dari sebelah ibu) yang telah berhijrah bersama-sama denganmu; dan (Kami telah halalkan bagimu) mana-mana perempuan yang beriman yang memberikan dirinya kepada Nabi (untuk dikahwininya dengan tidak membayar maskahwin) kalaulah Nabi suka berkahwin dengannya; perkahwinan yang demikian adalah khas bagimu semata-mata, bukan bagi orang-orang yang beriman umumnya; sesungguhnya Kami telah mengetahui apa yang Kami wajibkan kepada orang-orang mukmin mengenai isteri-isteri mereka dan hamba-hamba perempuan yang mereka miliki; - supaya tidak menjadi keberatan bagimu. Dan (ingatlah) Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 424, 22, 169, 366, FALSE, 0, NULL),
(33, 51, 'تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا', 'تُرْجِي مَن تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَن تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَا آتَيْتَهُنَّ كُلُّهُنَّ وَاللَّهُ يَعْلَمُ مَا فِي قُلُوبِكُمْ وَكَانَ اللَّهُ عَلِيمًا حَلِيمًا', NULL, 'You, [O Muḥammad], may put aside whom you will of them or take to yourself whom you will. And any that you desire of those [wives] from whom you had [temporarily] separated - there is no blame upon you [in returning her]. That is more suitable that they should be content and not grieve and that they should be satisfied with what you have given them - all of them. And Allāh knows what is in your hearts. And ever is Allāh Knowing and Forbearing.', 'Engkau boleh menangguhkan sesiapa yang engkau kehendaki dari mereka dan engkau boleh mendamping: sesiapa yang engkau kehendaki; dan sesiapa yang engkau hendak mendampinginya kembali dari mereka yang telah engkau jauhi itu maka tidaklah menjadi salah bagimu melakukannya; kebebasan yang diberikan kepadamu itu (bila diketahui oleh mereka) adalah lebih dekat untuk mententeramkan hati mereka, dan menjadikan mereka tidak berdukacita, serta menjadikan mereka pula reda akan apa yang engkau lakukan kepada mereka semuanya. Dan (ingatlah) Allah sedia mengetahui apa yang ada dalam hati kamu; dan Allah adalah Maha Mengetahui, lagi Maha Penyabar.', FALSE, NULL, NULL, 425, 22, 170, 366, FALSE, 0, NULL),
(33, 52, 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا', 'لَّا يَحِلُّ لَكَ النِّسَاءُ مِن بَعْدُ وَلَا أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ رَّقِيبًا', NULL, 'Not lawful to you, [O Muḥammad], are [any additional] women after [this], nor [is it] for you to exchange them for [other] wives, even if their beauty were to please you, except what your right hand possesses. And ever is Allāh, over all things, an Observer.', 'Tidak halal bagimu berkahwin dengan perempuan-perempuan yang lain sesudah (isteri-isterimu yang ada) itu, dan engkau juga tidak boleh menggantikan mereka dengan isteri-isteri yang baharu sekalipun engkau tertarik hati kepada kecantikan mereka, kecuali hamba-hamba perempuan yang engkau miliki. Dan (ingatlah) Allah sentiasa Mengawasi tiap-tiap sesuatu.', FALSE, NULL, NULL, 425, 22, 170, 366, FALSE, 0, NULL),
(33, 53, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِي النَّبِيَّ فَيَسْتَحْيِي مِنكُمْ وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِن وَرَاءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا رَسُولَ اللَّهِ وَلَا أَن تَنكِحُوا أَزْوَاجَهُ مِن بَعْدِهِ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ اللَّهِ عَظِيمًا', NULL, 'O you who have believed, do not enter the houses of the Prophet except when you are permitted for a meal, without awaiting its readiness. But when you are invited, then enter; and when you have eaten, disperse without seeking to remain for conversation. Indeed, that [behavior] was troubling the Prophet, and he is shy of [dismissing] you. But Allāh is not shy of the truth. And when you ask [his wives] for something, ask them from behind a partition. That is purer for your hearts and their hearts. And it is not [conceivable or lawful] for you to harm the Messenger of Allāh or to marry his wives after him, ever. Indeed, that would be in the sight of Allāh an enormity.', 'Wahai orang-orang yang beriman, janganlah kamu masuk ke rumah Nabi (menunggu makanan masak kerana hendak makan bersama), kecuali kamu dijemput untuk menghadiri jamuan, bukan dengan menunggu-nunggu masa sajiannya; tetapi apabila kamu dijemput maka masuklah (pada waktu yang ditetapkan); kemudian setelah kamu makan maka hendaklah masing-masing bersurai dan janganlah duduk bersenang-senang dengan berbual-bual. Sesungguhnya yang demikian itu menyakiti dan menyusahkan Nabi sehingga ia merasa malu (hendak menyatakan hal itu) kepada kamu, sedang Allah tidak malu daripada menyatakan kebenaran. Dan apabila kamu meminta sesuatu yang harus diminta dari isteri-isteri Nabi maka mintalah kepada mereka dari sebalik tabir. Cara yang demikian lebih suci bagi hati kamu dan hati mereka. Dan kamu tidak boleh sama sekali menyakiti Rasul Allah dan tidak boleh berkahwin dengan isteri-isterinya sesudah ia wafat selama-lamanya. Sesungguhnya segala yang tersebut itu adalah amat besar dosanya di sisi Allah.', FALSE, NULL, NULL, 425, 22, 170, 367, FALSE, 0, NULL),
(33, 54, 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'إِن تُبْدُوا شَيْئًا أَوْ تُخْفُوهُ فَإِنَّ اللَّهَ كَانَ بِكُلِّ شَيْءٍ عَلِيمًا', NULL, 'Whether you reveal a thing or conceal it, indeed Allāh is ever, of all things, Knowing.', '(Awasilah keadaan-keadaan kamu, kerana) jika kamu nyatakan sesuatu atau kamu sembunyikan dia, maka sesungguhnya Allah sentiasa Mengetahui akan segala-galanya.', FALSE, NULL, NULL, 425, 22, 170, 367, FALSE, 0, NULL),
(33, 55, 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ وَٱتَّقِينَ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', 'لَّا جُنَاحَ عَلَيْهِنَّ فِي آبَائِهِنَّ وَلَا أَبْنَائِهِنَّ وَلَا إِخْوَانِهِنَّ وَلَا أَبْنَاءِ إِخْوَانِهِنَّ وَلَا أَبْنَاءِ أَخَوَاتِهِنَّ وَلَا نِسَائِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَانُهُنَّ وَاتَّقِينَ اللَّهَ إِنَّ اللَّهَ كَانَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدًا', NULL, 'There is no blame upon them [i.e., women] concerning their fathers or their sons or their brothers or their brothers'' sons or their sisters'' sons or their women or those their right hands possess [i.e., slaves]. And fear Allāh. Indeed Allāh is ever, over all things, Witness.', 'Tidak ada salahnya kepada perempuan-perempuan (yang tidak berpakaian yang melindungi anggota yang haram dipandang oleh lelaki asing itu) menemui bapa-bapa mereka, dan anak-anak lelaki mereka, dan saudara-saudara lelaki mereka, dan anak-anak lelaki saudara-saudara lelaki mereka, dan anak-anak lelaki saudara-saudara perempuan mereka, dan perempuan-perempuan Islam mereka, serta hamba-hamba yang dimiliki oleh mereka. Dan bertaqwalah kamu kepada Allah; sesungguhnya Allah sentiasa Menyaksikan tiap-tiap sesuatu.', FALSE, NULL, NULL, 426, 22, 170, 367, FALSE, 0, NULL),
(33, 56, 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا', NULL, 'Indeed, Allāh confers blessing upon the Prophet, and His angels [ask Him to do so]. O you who have believed, ask [Allāh to confer] blessing upon him and ask [Allāh to grant him] peace.', 'Sesungguhnya Allah dan malaikatNya berselawat (memberi segala penghormatan dan kebaikan) kepada Nabi (Muhammad s.a.w); wahai orang-orang yang beriman berselawatlah kamu kepadanya serta ucapkanlah salam sejahtera dengan penghormatan yang sepenuhnya.', FALSE, NULL, NULL, 426, 22, 170, 367, FALSE, 0, NULL),
(33, 57, 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', 'إِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ وَرَسُولَهُ لَعَنَهُمُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', NULL, 'Indeed, those who abuse Allāh and His Messenger - Allāh has cursed them in this world and the Hereafter and prepared for them a humiliating punishment.', 'Sesungguhnya orang-orang yang melakukan perkara yang tidak diredai Allah dan RasulNya, Allah melaknatkan mereka di dunia dan di akhirat, dan menyediakan untuk mereka azab seksa yang menghina.', FALSE, NULL, NULL, 426, 22, 170, 367, FALSE, 0, NULL),
(33, 58, 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'وَالَّذِينَ يُؤْذُونَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ بِغَيْرِ مَا اكْتَسَبُوا فَقَدِ احْتَمَلُوا بُهْتَانًا وَإِثْمًا مُّبِينًا', NULL, 'And those who harm believing men and believing women for [something] other than what they have earned [i.e., deserved] have certainly borne upon themselves a slander and manifest sin.', 'Dan orang-orang yang mengganggu serta menyakiti orang-orang lelaki yang beriman dan orang-orang perempuan yang beriman dengan perkataan atau perbuatan yang tidak tepat dengan sesuatu kesalahan yang dilakukannya, maka sesungguhnya mereka telah memikul kesalahan menuduh secara dusta, dan berbuat dosa yang amat nyata.', FALSE, NULL, NULL, 426, 22, 170, 367, FALSE, 0, NULL),
(33, 59, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَابِيبِهِنَّ ذَٰلِكَ أَدْنَىٰ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, 'O Prophet, tell your wives and your daughters and the women of the believers to bring down over themselves [part] of their outer garments. That is more suitable that they will be known and not be abused. And ever is Allāh Forgiving and Merciful.', 'Wahai Nabi, suruhlah isteri-isterimu dan anak-anak perempuanmu serta perempuan-perempuan yang beriman, supaya melabuhkan pakaiannya bagi menutup seluruh tubuhnya (semasa mereka keluar); cara yang demikian lebih sesuai untuk mereka dikenal (sebagai perempuan yang baik-baik) maka dengan itu mereka tidak diganggu. Dan (ingatlah) Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 426, 22, 170, 368, FALSE, 0, NULL),
(33, 60, 'لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا', 'لَّئِن لَّمْ يَنتَهِ الْمُنَافِقُونَ وَالَّذِينَ فِي قُلُوبِهِم مَّرَضٌ وَالْمُرْجِفُونَ فِي الْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَا إِلَّا قَلِيلًا', NULL, 'If the hypocrites and those in whose hearts is disease and those who spread rumors in al-Madīnah do not cease, We will surely incite you against them; then they will not remain your neighbors therein except for a little,', 'Demi sesungguhnya, jika orang-orang munafik, dan orang-orang yang ada penyakit (syak ragu-ragu) dalam hatinya, serta orang-orang yang menyebarkan berita-berita dusta di Madinah itu tidak berhenti (dari perbuatan jahat masing-masing), nescaya Kami akan mendesakmu memerangi mereka; sesudah itu mereka tidak akan tinggal berjiran denganmu di Madinah lagi melainkan sebentar sahaja,', FALSE, NULL, NULL, 426, 22, 171, 368, FALSE, 0, NULL),
(33, 61, 'مَّلْعُونِينَ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا', 'مَّلْعُونِينَ أَيْنَمَا ثُقِفُوا أُخِذُوا وَقُتِّلُوا تَقْتِيلًا', NULL, 'Accursed wherever they are found, [being] seized and massacred completely.', 'serta mereka tetap ditimpa laknat. Di mana sahaja mereka ditemui, mereka ditangkap dan dibunuh habis-habisan.', FALSE, NULL, NULL, 426, 22, 171, 368, FALSE, 0, NULL),
(33, 62, 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'سُنَّةَ اللَّهِ فِي الَّذِينَ خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا', NULL, '[This is] the established way of Allāh with those who passed on before; and you will not find in the way of Allāh any change.', 'Yang demikian adalah menurut “Sunnatullah” (undang-undang peraturan Allah yang telah lalu; dan engkau tidak sekali-kali akan mendapati sebarang perubahan bagi “Sunnatullah” itu.', FALSE, NULL, NULL, 426, 22, 171, 368, FALSE, 0, NULL),
(33, 63, 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', 'يَسْأَلُكَ النَّاسُ عَنِ السَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ اللَّهِ وَمَا يُدْرِيكَ لَعَلَّ السَّاعَةَ تَكُونُ قَرِيبًا', NULL, 'People ask you concerning the Hour. Say, "Knowledge of it is only with Allāh. And what may make you perceive? Perhaps the Hour is near."', 'Manusia bertanya kepadamu (wahai Muhammad) tentang kedatangan hari kiamat; katakanlah: “Sesungguhnya pengetahuan mengenainya hanyalah ada di sisi Allah.” Dan apa jalannya engkau dapat mengetahui? - boleh jadi masa datangnya tidak lama lagi.', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 64, 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', 'إِنَّ اللَّهَ لَعَنَ الْكَافِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', NULL, 'Indeed, Allāh has cursed the disbelievers and prepared for them a Blaze.', 'Sesungguhnya Allah telah melaknat orang-orang kafir dan menyediakan bagi mereka api neraka yang marak menjulang, -', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 65, 'خَٰلِدِينَ فِيهَآ أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'خَالِدِينَ فِيهَا أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', NULL, 'Abiding therein forever, they will not find a protector or a helper.', 'kekalah mereka di dalamnya selama-lamanya; mereka pula tidak akan memperoleh sesiapapun yang akan menjadi pelindung atau penolong.', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِي النَّارِ يَقُولُونَ يَا لَيْتَنَا أَطَعْنَا اللَّهَ وَأَطَعْنَا الرَّسُولَا', NULL, 'The Day their faces will be turned about in the Fire, they will say, "How we wish we had obeyed Allāh and obeyed the Messenger."', 'Pada masa muka mereka dibalik-balikkan dalam neraka, mereka berkata (dengan sesalnya): “Alangkah baiknya kalau kami dahulu (semasa di dunia) taat kepada Allah serta taat kepada Rasul Allah.', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 67, 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', 'وَقَالُوا رَبَّنَا إِنَّا أَطَعْنَا سَادَتَنَا وَكُبَرَاءَنَا فَأَضَلُّونَا السَّبِيلَا', NULL, 'And they will say, "Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way.', 'Dan mereka berkata lagi: “Wahai Tuhan kami, sesungguhnya kami telah mematuhi kehendak ketua-ketua dan orang-orang besar kami, lalu mereka menyesatkan kami dari jalan yang benar.', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 68, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا', 'رَبَّنَا آتِهِمْ ضِعْفَيْنِ مِنَ الْعَذَابِ وَالْعَنْهُمْ لَعْنًا كَبِيرًا', NULL, 'Our Lord, give them double the punishment and curse them with a great curse."', '“Wahai Tuhan kami, berilah mereka azab sengsara dua kali ganda, dan laknatkanlah mereka dengan laknat yang sebesar-besarnya!”', FALSE, NULL, NULL, 427, 22, 171, 368, FALSE, 0, NULL),
(33, 69, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَكُونُوا كَالَّذِينَ آذَوْا مُوسَىٰ فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا وَكَانَ عِندَ اللَّهِ وَجِيهًا', NULL, 'O you who have believed, be not like those who abused Moses; then Allāh cleared him of what they said. And he, in the sight of Allāh, was distinguished.', 'Wahai orang-orang yang beriman, janganlah kamu menjadi seperti orang-orang (Yahudi) yang telah mencaci Nabi Musa, lalu Allah membersihkannya dari segala cacian yang mereka katakan; dan adalah dia seorang yang mulia di sisi Allah.', FALSE, NULL, NULL, 427, 22, 171, 369, FALSE, 0, NULL),
(33, 70, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا', NULL, 'O you who have believed, fear Allāh and speak words of appropriate justice.', 'Wahai orang-orang yang beriman, bertaqwalah kepada Allah, dan katakanlah perkataan yang tepat - benar (dalam segala perkara),', FALSE, NULL, NULL, 427, 22, 171, 369, FALSE, 0, NULL),
(33, 71, 'يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', 'يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا', NULL, 'He will [then] amend for you your deeds and forgive you your sins. And whoever obeys Allāh and His Messenger has certainly attained a great attainment.', 'Supaya Ia memberi taufiq dengan menjayakan amal-amal kamu, dan mengampunkan dosa-dosa kamu. Dan (ingatlah) sesiapa yang taat kepada Allah dan RasulNya, maka sesungguhnya ia telah berjaya mencapai sebesar-besar kejayaan.', FALSE, NULL, NULL, 427, 22, 171, 369, FALSE, 0, NULL),
(33, 72, 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا', 'إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَاوَاتِ وَالْأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الْإِنسَانُ إِنَّهُ كَانَ ظَلُومًا جَهُولًا', NULL, 'Indeed, We offered the Trust to the heavens and the earth and the mountains, and they declined to bear it and feared it; but man [undertook to] bear it. Indeed, he was unjust and ignorant.', 'Sesungguhnya Kami telah kemukakan tanggungjawab amanah (Kami) kepada langit dan bumi serta gunung-ganang (untuk memikulnya), maka mereka enggan memikulnya dan bimbang tidak dapat menyempurnakannya (kerana tidak ada pada mereka persediaan untuk memikulnya); dan (pada ketika itu) manusia (dengan persediaan yang ada padanya) sanggup memikulnya. (Ingatlah) sesungguhnya tabiat kebanyakan manusia adalah suka melakukan kezaliman dan suka pula membuat perkara-perkara yang tidak patut dikerjakan.', FALSE, NULL, NULL, 427, 22, 171, 369, FALSE, 0, NULL),
(33, 73, 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا', 'لِّيُعَذِّبَ اللَّهُ الْمُنَافِقِينَ وَالْمُنَافِقَاتِ وَالْمُشْرِكِينَ وَالْمُشْرِكَاتِ وَيَتُوبَ اللَّهُ عَلَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا', NULL, '[It was] so that Allāh may punish the hypocrite men and hypocrite women and the men and women who associate others with Him and that Allāh may accept repentance from the believing men and believing women. And ever is Allāh Forgiving and Merciful.', '(Dengan kesanggupan manusia memikul amanah itu maka) akibatnya Allah akan menyeksa orang-orang lelaki yang munafik serta orang-orang perempuan yang munafik, dan orang-orang lelaki yang musyrik serta orang-orang perempuan yang musyrik; dan juga Allah akan menerima taubat orang-orang lelaki yang beriman serta orang-orang perempuan yang beriman. Dan sememangnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 427, 22, 171, 369, FALSE, 0, NULL),
(34, 1, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْـَٔاخِرَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'الحمد لله الذي له ما في السماوات وما في الارض وله الحمد في الاخرة وهو الحكيم الخبير', NULL, '[All] praise is [due] to Allāh, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Aware.', 'Segala puji tertentu bagi Allah yang memiliki dan menguasai segala yang ada di langit dan yang ada di bumi, dan bagiNyalah juga segala puji di akhirat; dan Dia lah sahaja Yang Maha Bijaksana, lagi Maha Mendalam pengetahuanNya.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 17, NULL),
(34, 2, 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۚ وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', 'يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو الرحيم الغفور', NULL, 'He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving.', 'Ia mengetahui apa yang masuk ke bumi serta apa yang keluar daripadanya, dan apa yang turun dari langit serta apa yang naik kepadanya; dan Dia lah jua yang Maha Mengasihani, lagi Maha Pengampun.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 18, NULL),
(34, 3, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ ۖ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَـٰلِمِ ٱلْغَيْبِ ۖ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ', 'وقال الذين كفروا لا تاتينا الساعة قل بلى وربي لتاتينكم عالم الغيب لا يعزب عنه مثقال ذرة في السماوات ولا في الارض ولا اصغر من ذلك ولا اكبر الا في كتاب مبين', NULL, 'But those who disbelieve say, "The Hour will not come to us." Say, "Yes, by my Lord, it will surely come to you. [Allāh is] the Knower of the unseen." Not absent from Him is an atom''s weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -', 'Dan orang-orang yang kafir berkata: “Hari kiamat itu tidak akan datang kepada kami”. Katakanlah (wahai Muhammad): “Bahkan (tetap datang). Demi Tuhanku yang mengetahui segala perkara yang ghaib, hari kiamat itu sesungguhnya akan datang kepada kamu”. Tiada tersembunyi dari pengetahuanNya barang seberat debu yang ada di langit atau di bumi, dan tidak ada yang lebih kecil dari itu atau yang lebih besar melainkan semuanya tertulis di dalam Kitab yang terang nyata.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 32, NULL),
(34, 4, 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۚ أُو۟لَـٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'ليجزي الذين امنوا وعملوا الصالحات اولئك لهم مغفرة ورزق كريم', NULL, 'That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.', '(Kedatangan hari kiamat itu) supaya Tuhan membalas orang-orang yang beriman dan beramal soleh; mereka itu akan beroleh keampunan dan limpah kurnia yang mulia.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 10, NULL),
(34, 5, 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَـٰتِنَا مُعَـٰجِزِينَ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'والذين سعوا في اياتنا معاجزين اولئك لهم عذاب من رجز اليم', NULL, 'But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature.', 'Dan (sebaliknya) orang-orang yang berusaha menentang dan membatalkan ayat-ayat keterangan Kami sambil menyangka dapat melepaskan diri (dari hukuman Kami), - mereka itu akan beroleh azab dari jenis azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 11, NULL),
(34, 6, 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'ويرى الذين اوتوا العلم الذي انزل اليك من ربك هو الحق ويهدي الى صراط العزيز الحميد', NULL, 'And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy.', 'Dan orang-orang yang diberi ilmu pengetahuan, mengetahui (dengan yakin, bahawa keterangan-keterangan) yang diturunkan kepadamu dari Tuhanmu (mengenai hari kiamat dan lain-lainnya) itulah yang benar serta yang memimpin ke jalan Allah Yang Maha Kuasa, lagi Maha Terpuji.', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 16, NULL),
(34, 7, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ', 'وقال الذين كفروا هل ندلكم على رجل ينبئكم اذا مزقتم كل ممزق انكم لفي خلق جديد', NULL, 'But those who disbelieve say, "Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?', 'Dan orang-orang yang kafir pula berkata (sesama sendiri secara mengejek-ejek): “Mahukah, kami tunjukkan kepada kamu seorang lelaki yang memberitakan kepada kamu: ‘(Bahawa apabila kamu dihancurkan sehancur-hanurnya sesudah mati), sesungguhnya kamu akan dihidupkan semula dalam bentuk kejadian yang baru?’', FALSE, NULL, NULL, 428, 22, 171, 370, FALSE, 16, NULL),
(34, 8, 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ ۗ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَـٰلِ ٱلْبَعِيدِ', 'افترى على الله كذبا ام به جنة بل الذين لا يؤمنون بالاخرة في العذاب والضلال البعيد', NULL, 'Has he invented about Allāh a lie or is there in him madness?" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error.', '“Adakah ia berdusta terhadap Allah, atau ia kena penyakit gila?” (Tidak ada satupun) bahkan orang-orang yang tidak percaya kepada hari akhirat tetap beroleh (di sana) azab seksa yang seburuk-buruknya dan (di sini) tetap berada dalam kesesatan yang jauh terpesong.', FALSE, NULL, NULL, 429, 22, 171, 370, FALSE, 16, NULL),
(34, 9, 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ', 'افلم يروا الى ما بين ايديهم وما خلفهم من السماء والارض ان نشا نخسف بهم الارض او نسقط عليهم كسفا من السماء ان في ذلك لاية لكل عبد منيب', NULL, 'Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allāh].', '(Setelah mereka mengejek-ejek dan membuat tuduhan-tuduhan itu) tidakkah mereka melihat apa yang ada di hadapan mereka dan yang ada di belakang mereka dari langit dan bumi (dapatkah mereka melarikan diri)? Jika Kami kehendaki nescaya Kami timbuskan mereka di bumi, atau Kami gugurkan atas mereka ketul-ketul dan serpihan-serpihan dari langit (yang akan membinasakan mereka). Sesungguhnya yang demikian mengandungi satu tanda (yang memberi keinsafan) bagi tiap-tiap hamba Allah yang mahu kembali kepadanya (dengan taat dan berbakti).', FALSE, NULL, NULL, 429, 22, 171, 370, FALSE, 29, NULL),
(34, 10, '۞ وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا ۖ يَـٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ ۖ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', 'ولقد اتينا داوود منا فضلا يا جبال اوبي معه والطير والنا له الحديد', NULL, 'And We certainly gave David from Us bounty. [We said], "O mountains, repeat [Our] praises with him, and the birds [as well]." And We made pliable for him iron,', 'Dan demi sesungguhnya, Kami telah memberikan kepada Nabi Daud limpah kurnia dari Kami (sambil Kami berfirman): “Hai gunung-ganang, ulang-ulangilah mengucap tasbih bersama-sama dengan Nabi Daud, dan wahai burung-burung (bertasbihlah bersama-sama dengannya)!” Dan juga telah melembutkan besi baginya;', FALSE, NULL, NULL, 429, 22, 172, 371, FALSE, 12, NULL),
(34, 11, 'أَنِ ٱعْمَلْ سَـٰبِغَـٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ ۖ وَٱعْمَلُوا۟ صَـٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ', 'ان اعمل سابغات وقدر في السرد واعملوا صالحا اني بما تعملون بصير', NULL, '[Commanding him], "Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing."', '(Serta Kami wahyukan kepadanya): “Buatlah baju-baju besi yang luas labuh, dan sempurnakanlah jalinannya sekadar yang dikehendaki; dan kerjakanlah kamu (wahai Daud dan umatmu) amal-amal yang soleh, sesungguhnya Aku Maha Melihat akan segala yang kamu kerjakan”.', FALSE, NULL, NULL, 429, 22, 172, 371, FALSE, 12, NULL),
(34, 12, 'وَلِسُلَيْمَـٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ ۖ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ ۖ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ ۖ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', 'ولسليمان الريح غدوها شهر ورواحها شهر واسلنا له عين القطر ومن الجن من يعمل بين يديه باذن ربه ومن يزغ منهم عن امرنا نذقه من عذاب السعير', NULL, 'And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze.', 'Dan Kami kurniakan kepada Nabi Sulaiman kuasa menggunakan angin untuk perjalanannya: sepagi perjalanannya adalah menyamai perjalanan biasa sebulan, dan sepetang perjalanannya adalah menyamai perjalanan biasa sebulan; dan Kami alirkan baginya matair dari tembaga; dan (Kami mudahkan) sebahagian dari jin untuk bekerja di hadapannya dengan izin Tuhannya. Dan sesiapa dari jin itu yang menyeleweng dari perintah Kami, Kami akan merasakannya (pukulan) dari azab api neraka.', FALSE, NULL, NULL, 429, 22, 172, 371, FALSE, 27, NULL),
(34, 13, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَـٰرِيبَ وَتَمَـٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَـٰتٍ ۚ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا ۚ وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ', 'يعملون له ما يشاء من محاريب وتماثيل وجفان كالجواب وقدور راسيات اعملوا ال داوود شكرا وقليل من عبادي الشكور', NULL, 'They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], "Work, O family of David, in gratitude." And few of My servants are grateful.', 'Golongan jin itu membuat untuk Nabi Sulaiman apa yang ia kehendaki dari bangunan-bangunan yang tinggi, dan patung-patung, dan pinggan-pinggan hidangan yang besar seperti kolam, serta periuk-periuk besar yang tetap di atas tukunya. (Setelah itu Kami perintahkan): “Beramalah kamu wahai keluarga Daud untuk bersyukur!” Dan sememangnya sedikit sekali di antara hamba-hambaKu yang bersyukur.', FALSE, NULL, NULL, 429, 22, 172, 371, FALSE, 19, NULL),
(34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ ۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', 'فلما قضينا عليه الموت ما دلهم على موته الا دابة الارض تاكل منساته فلما خر تبينت الجن ان لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين', NULL, 'And when We decreed for him [i.e., Solomon] death, nothing indicated to them [i.e., the jinn] his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment.', 'Setelah Kami tetapkan berlakunya kematian Nabi Sulaiman, tidak ada yang menunjukkan kepada mereka tentang kematiannya melainkan semut putih (anai-anai) yang telah memakan tongkatnya. Maka apabila ia tumbang, ternyatalah kepada golongan jin itu, bahawa kalaulah mereka sedia, mengetahui perkara yang ghaib nescaya mereka tidak tinggal sedemikian lamanya di dalam azab (kerja berat) yang menghina.', FALSE, NULL, NULL, 429, 22, 172, 371, FALSE, 27, NULL),
(34, 15, 'لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ ۖ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ ۖ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ ۚ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', 'لقد كان لسبا في مسكنهم اية جنتان عن يمين وشمال كلوا من رزق ربكم واشكروا له بلدة طيبة ورب غفور', NULL, 'There was for [the tribe of] Saba’ in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], "Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord."', 'Demi sesungguhnya, adalah bagi penduduk negeri Saba'', satu tanda (yang membuktikan kemurahan Allah) yang terdapat di tempat tinggal mereka, iaitu: dua kumpulan kebun (yang luas lagi subur), yang terletak di sebelah kanan dan di sebelah kiri (kampung mereka). (Lalu dikatakan kepada mereka): “Makanlah dari rezeki pemberian Tuhan kamu dan bersyukurlah kepadaNya; (negeri kamu ini adalah) negeri yang baik (aman dan makmur), dan (Tuhan kamu adalah) Tuhan yang Maha Pengampun!.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 20, NULL),
(34, 16, 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَـٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ', 'فاعرضوا فارسلنا عليهم سيل العرم وبدلناهم بجنتيهم جنتين ذواتي اكل خمط واثل وشيء من سدر قليل', NULL, 'But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees.', 'Maka mereka berpaling ingkar, lalu Kami hantarkan kepada mereka banjir yang membinasakan, dan Kami gantikan dua kumpulan kebun mereka (yang subur) itu dengan dua kumpulan kebun yang berisi dengan pohon-pohon yang pahit buahnya, dan pohon-pohon yang jarang berbuah, serta sedikit pohon-pohon bidara.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 16, NULL),
(34, 17, 'ذَٰلِكَ جَزَيْنَـٰهُم بِمَا كَفَرُوا۟ ۖ وَهَلْ نُجَـٰزِىٓ إِلَّا ٱلْكَفُورَ', 'ذلك جزيناهم بما كفروا وهل نجازي الا الكفور', NULL, '[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?', 'Demikianlah Kami membalas mereka disebabkan kekufuran mereka; dan sebenarnya Kami tidak menimpakan balasan yang demikian melainkan kepada orang-orang yang amat kufur.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 8, NULL),
(34, 18, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَـٰرَكْنَا فِيهَا قُرًى ظَـٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ ۖ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', 'وجعلنا بينهم وبين القرى التي باركنا فيها قرى ظاهرة وقدرنا فيها السير سيروا فيها ليالي واياما امنين', NULL, 'And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], "Travel between them by night or by day in safety."', 'Dan - di antara tempat tinggal mereka (di negeri Yaman) dengan bandar-bandar (di daerah negeri Syam) yang Kami limpahkan berkat kepadanya (dengan kemakmuran), - Kami adakan beberapa buah bandar yang jelas kelihatan (kepada orang-orang yang melalui jalan itu), dan Kami tentukan jarak perjalanan di antaranya (sekadar yang dapat dijadikan tempat-tempat persinggahan), (serta dikatakan kepada mereka): “Berjalanlah kamu di bandar-bandar itu pada bila-bila masa yang kamu suka, malam dan siang, dalam keadaan yang aman”.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 17, NULL),
(34, 19, 'فَقَالُوا۟ رَبَّنَا بَـٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَـٰهُمْ أَحَادِيثَ وَمَزَّقْنَـٰهُمْ كُلَّ مُمَزَّقٍ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'فقالوا ربنا باعد بين اسفارنا وظلموا انفسهم فجعلناهم احاديث ومزقناهم كل ممزق ان في ذلك لايات لكل صبار شكور', NULL, 'But [insolently] they said, "Our Lord, lengthen the distance between our journeys," and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful.', '(Maka kamakmuran dan kemudahan itu menjadikan mereka sombong dan kufur) lalu berkata: “Wahai Tuhan kami, jauhkanlah jarak perjalanan kami (di antara sebuah bandar dengan yang lain)”, dan mereka berlaku zalim kepada diri mereka sendiri; lalu Kami jadikan (kisah perbuatan derhaka) mereka: buah mulut orang ramai, serta kami pecah belahkan mereka berkecai-kecai. Sesungguhnya kisah mereka yang tersebut mengandungi tanda-tanda (yang besar pengajarannya bagi tiap-tiap seorang (mukmin) yang sentiasa bersikap sabar, lagi sentiasa bersyukur.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 19, NULL),
(34, 20, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ', 'ولقد صدق عليهم ابليس ظنه فاتبعوه الا فريقا من المؤمنين', NULL, 'And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers.', 'Dan sesungguhnya Iblis telah dapati sangkaannya tepat terhadap mereka, iaitu mereka menurutnya, kecuali sebahagian dari orang-orang yang beriman (yang tidak terpedaya kepada hasutannya).', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 10, NULL),
(34, 21, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْـَٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'وَمَا كَانَ لَهُ عَلَيْهِم مِّن سُلْطَانٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِالْآخِرَةِ مِمَّنْ هُوَ مِنْهَا فِي شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَيْءٍ حَفِيظٌ', NULL, 'And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian.', 'Dan sememangnya tiadalah bagi Iblis sebarang kuasa untuk menyesatkan mereka, melainkan untuk menjadi ujian bagi melahirkan pengetahuan Kami tentang siapakah yang benar-benar beriman kepada hari akhirat dan siapa pula yang ragu-ragu terhadapnya. Dan (ingatlah) Tuhanmu sentiasa mengawal serta mengawasi tiap-tiap sesuatu.', FALSE, NULL, NULL, 430, 22, 172, 371, FALSE, 0, NULL),
(34, 22, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ', 'قُلِ ادْعُوا الَّذِينَ زَعَمْتُم مِّن دُونِ اللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُ مِنْهُم مِّن ظَهِيرٍ', NULL, 'Say, [O Muḥammad], "Invoke those you claim [as deities] besides Allāh." They do not possess an atom''s weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant.', 'Katakanlah (wahai Muhammad kepada kaum musyrik): “Serukanlah makhluk-makhluk yang kamu dakwakan sebagai tuhan selain dari Allah; mereka tidak memiliki kuasa seberat debu pun di langit dan di bumi, dan mereka tiada sebarang bahagian perkongsian (dengan Allah) dalam (mencipta dan mentadbirkan) langit dan bumi, dan Allah pula tidak mendapat sebarang pertolongan dari mereka”.', FALSE, NULL, NULL, 430, 22, 172, 372, FALSE, 0, NULL),
(34, 23, 'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ قَالُوا۟ ٱلْحَقَّ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'وَلَا تَنفَعُ الشَّفَاعَةُ عِندَهُ إِلَّا لِمَنْ أَذِنَ لَهُ حَتَّىٰ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ قَالُوا الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ', NULL, 'And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], "What has your Lord said?" They will say, "The truth." And He is the Most High, the Grand.', 'Dan tidak berfaedah syafaat di sisi Allah kecuali bagi orang yang telah diizinkan Allah, (maka orang-orang yang hendak memohon syafaat terpaksa menunggu izin itu dengan penuh perasaan takut dan bimbang) sehingga apabila dihapuskan Allah perasaan takut dari hati mereka (dengan pemberian izin itu) bersukarialah mereka dengan bertanya-tanyaan sesama sendiri: “Apakah yang telah dititahkan oleh Tuhan kamu?” Sebahagian di antara mereka menjawab: “Tuhan telah menitahkan kebenaran”; dan Dia lah jua Yang Maha Tinggi keadaanNya, lagi Maha Besar kekuasaanNya.', FALSE, NULL, NULL, 431, 22, 172, 372, FALSE, 0, NULL),
(34, 24, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ', 'قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاوَاتِ وَالْأَرْضِ قُلِ اللَّهُ وَإِنَّا أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِي ضَلَالٍ مُّبِينٍ', NULL, 'Say, "Who provides for you from the heavens and the earth?" Say, "Allāh. And indeed, we or you are either upon guidance or in clear error."', 'Bertanyalah (wahai Muhammad kepada orang-orang musyrik itu): “Siapakah yang memberi rezeki kepada kamu dari langit dan bumi?” Terangkanlah jawabnya: “Ialah Allah; dan sesungguhnya (tiap-tiap satu golongan), sama ada golongan kami ahli tauhid atau golongan kamu ahli syirik - (tidak sunyi daripada salah satu dari dua keadaan): keadaan tetapnya di atas hidayah petunjuk atau tenggelamnya dalam kesesatan yang jelas nyata”.', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 25, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', 'قُل لَّا تُسْأَلُونَ عَمَّا أَجْرَمْنَا وَلَا نُسْأَلُ عَمَّا تَعْمَلُونَ', NULL, 'Say, "You will not be asked about what we committed, and we will not be asked about what you do."', '(Oleh itu) katakanlah (wahyu Muhammad): “Kamu tidak akan bertanggungjawab tentang kesalahan yang kami lakukan, dan kami pula tidak akan bertanggungjawab tentang apa yang kamu kerjakan”.', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ', NULL, 'Say, "Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge."', 'Katakanlah lagi: “Tuhan kita akan menghimpunkan Kita semua (pada hari kiamat), kemudian Ia akan menyelesaikan perselisihan yang ada di antara kita dengan penyelesaian yang benar; dan Dia lah jua Hakim yang seadil-adilnya, lagi Yang Maha Mengetahui segala-galanya”.', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 27, 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'قُلْ أَرُونِيَ الَّذِينَ أَلْحَقْتُم بِهِ شُرَكَاءَ كَلَّا بَلْ هُوَ اللَّهُ الْعَزِيزُ الْحَكِيمُ', NULL, 'Say, "Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allāh, the Exalted in Might, the Wise."', 'Katakanlah lagi: “Tunjukkanlah kepadaku sifat-sifat ketuhanan yang ada pada makhluk-makhluk yang kamu hubungkan dengan Allah sebagai sekutu-sekutuNya. Tidak ada pada sesuatu makhluk pun sifat-sifat itu, bahkan yang mempunyai sifat-sifat ketuhanan ialah Allah Yang Maha Kuasa, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 28, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know.', 'Dan tiadalah Kami mengutusmu (wahai Muhammad) melainkan untuk umat manusia seluruhnya, sebagai Rasul pembawa berita gembira (kepada orang-orang yang beriman), dan pemberi amaran (kepada orang-orang yang ingkar); akan tetapi kebanyakan manusia tidak mengetahui (hakikat itu).', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 29, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is this promise, if you should be truthful?"', 'Dan mereka (yang ingkar) bertanya: “Bilakah berlakunya azab yang telah dijanjikan itu, jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 30, 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَأْخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', NULL, 'Say, "For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it]."', 'Jawablah (wahai Muhammad): “Untuk kamu disediakan satu hari yang kamu tidak dapat melambatkannya sesaat pun, dan tidak pula kamu dapat menyegerakannya”.', FALSE, NULL, NULL, 431, 22, 173, 372, FALSE, 0, NULL),
(34, 31, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', 'وَقَالَ الَّذِينَ كَفَرُوا لَن نُّؤْمِنَ بِهَٰذَا الْقُرْآنِ وَلَا بِالَّذِي بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰ إِذِ الظَّالِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ الْقَوْلَ يَقُولُ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا لَوْلَا أَنتُمْ لَكُنَّا مُؤْمِنِينَ', NULL, 'And those who disbelieve say, "We will never believe in this Qur’ān nor in that before it." But if you could see when the wrongdoers are made to stand before their Lord, refuting each others'' words... Those who were oppressed will say to those who were arrogant, "If not for you, we would have been believers."', 'Dan orang-orang yang kafir berkata: Kami tidak akan beriman sama sekali kepada Al-Quran ini dan tidak juga kepada Kitab-kitab ugama yang terdahulu daripadanya”. Dan (sungguh ngeri) kalau engkau melihat ketika orang-orang yang zalim itu dibawa berdiri di hadapan Tuhan mereka (untuk dihisab), masing-masing tuduh menuduh antara satu dengan yang lain. Orang-orang yang tertindas berkata kepada orang-orang yang sombong takbur (yang menjadi ketuanya): “Kalaulah tidak kerana kamu (menindas dan memperdayakan kami), tentulah kami sudah menjadi orang yang beriman”.', FALSE, NULL, NULL, 431, 22, 173, 373, FALSE, 0, NULL),
(34, 32, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ', 'قَالَ الَّذِينَ اسْتَكْبَرُوا لِلَّذِينَ اسْتُضْعِفُوا أَنَحْنُ صَدَدْنَاكُمْ عَنِ الْهُدَىٰ بَعْدَ إِذْ جَاءَكُم بَلْ كُنتُم مُّجْرِمِينَ', NULL, 'Those who were arrogant will say to those who were oppressed, "Did we avert you from guidance after it had come to you? Rather, you were criminals."', 'Orang-orang yang sombong takbur itu menjawab kepada orang-orang yang tertindas: Kamikah yang telah menghalang kamu daripada menerima hidayah petunjuk sesudah ia datang kepada kamu? (Bukan kami yang menghalang) bahkan kamulah yang menyebabkan diri sendiri menjadi orang-orang yang berdosa”.', FALSE, NULL, NULL, 432, 22, 173, 373, FALSE, 0, NULL),
(34, 33, 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'وَقَالَ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا بَلْ مَكْرُ اللَّيْلِ وَالنَّهَارِ إِذْ تَأْمُرُونَنَا أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُ أَندَادًا وَأَسَرُّوا النَّدَامَةَ لَمَّا رَأَوُا الْعَذَابَ وَجَعَلْنَا الْأَغْلَالَ فِي أَعْنَاقِ الَّذِينَ كَفَرُوا هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ', NULL, 'Those who were oppressed will say to those who were arrogant, "Rather, [it was your] conspiracy of night and day when you were ordering us to disbelieve in Allāh and attribute to Him equals." But they will [all] confide regret when they see the punishment; and We will put shackles on the necks of those who disbelieved. Will they be recompensed except for what they used to do?', 'Dan berkata pula orang-orang yang tertindas kepada orang-orang yang sombong takbur itu: “Tidak! Bahkan (yang menghalang kami daripada beriman ialah) perbuatan kamu memperdaya kami malam dan siang, ketika kamu menyuruh kami berlaku kufur kepada Allah dan mengadakan sekutu-sekutu bagiNya. Akhirnya masing-masing diam sambil memendamkan perasaan sesal dan kecewa semasa mereka melihat azab; dan Kami pasangkan belenggu-belenggu pada leher orang-orang yang kafir itu. Mereka tidak dibalas melainkan dengan apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 432, 22, 173, 373, FALSE, 0, NULL),
(34, 34, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'وَمَا أَرْسَلْنَا فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا بِمَا أُرْسِلْتُم بِهِ كَافِرُونَ', NULL, 'And We did not send into a city any warner except that its affluent said, "Indeed we, in that with which you were sent, are disbelievers."', 'Dan Kami tidak mengutus kepada sesebuah negeri: seseorang Rasul pemberi amaran melainkan orang-orang yang berada dalam kemewahan di negeri itu berkata: “Sesungguhnya kami tetap mengingkari apa yang kamu diutuskan membawanya”.', FALSE, NULL, NULL, 432, 22, 173, 373, FALSE, 0, NULL),
(34, 35, 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ', 'وَقَالُوا نَحْنُ أَكْثَرُ أَمْوَالًا وَأَوْلَادًا وَمَا نَحْنُ بِمُعَذَّبِينَ', NULL, 'And they said, "We are more [than the believers] in wealth and children, and we are not to be punished."', 'Dan mereka berkata lagi: “Kami lebih banyak harta benda dan anak pinak, dan kami pula tidak akan diseksa”.', FALSE, NULL, NULL, 432, 22, 173, 373, FALSE, 0, NULL),
(34, 36, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'Say, "Indeed, my Lord extends provision for whom He wills and restricts [it], but most of the people do not know."', 'Katakanlah (wahai Muhammad): “Sesungguhnya Tuhanku memewahkan rezeki bagi sesiapa yang dikehendakiNya, dan Dia juga yang menyempitkan (bagi sesiapa yang dikehendakiNya); akan tetapi kebanyakan manusia tidak mengetahui (hakikat itu).', FALSE, NULL, NULL, 432, 22, 173, 373, FALSE, 0, NULL),
(34, 37, 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ', 'وَمَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُم بِالَّتِي تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰ إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَأُولَٰئِكَ لَهُمْ جَزَاءُ الضِّعْفِ بِمَا عَمِلُوا وَهُمْ فِي الْغُرُفَاتِ آمِنُونَ', NULL, 'And it is not your wealth or your children that bring you nearer to Us in position, but it is [by being] one who has believed and done righteousness. For them there will be the double reward for what they did, and they will be in the upper chambers [of Paradise], safe [and secure].', 'Dan bukanlah harta benda kamu dan tidak juga anak pinak kamu yang mendampingkan kamu di sisi Kami walau sedikitpun, kecuali orang-orang yang beriman dan beramal soleh, maka mereka itu akan beroleh balasan yang berlipat ganda disebabkan apa yang mereka telah kerjakan; dan mereka pula ditempatkan dalam mahligai-mahligai (di Syurga) dengan aman sentosa.', FALSE, NULL, NULL, 432, 22, 173, 374, FALSE, 0, NULL),
(34, 38, 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'وَالَّذِينَ يَسْعَوْنَ فِي آيَاتِنَا مُعَاجِزِينَ أُولَٰئِكَ فِي الْعَذَابِ مُحْضَرُونَ', NULL, 'And the ones who strive against Our verses to cause [them] failure - those will be brought into the punishment [to remain].', 'Dan orang-orang yang berusaha menentang dan membatalkan ayat-ayat keterangan Kami sambil menyangka dapat melepaskan diri (dari hukuman Kami), mereka itu akan berada di dalam azab seksa.', FALSE, NULL, NULL, 432, 22, 173, 374, FALSE, 0, NULL),
(34, 39, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ وَمَا أَنفَقْتُم مِّن شَيْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ', NULL, 'Say, "Indeed, my Lord extends provision for whom He wills of His servants and restricts [it] for him. But whatever thing you spend [in His cause] - He will compensate it; and He is the best of providers."', 'Katakanlah (wahai Muhammad): “Sesungguhnya Tuhanku memewahkan rezeki bagi sesiapa yang dikehendakiNya di antara hamba-hambaNya, dan Ia juga yang menyempitkan baginya; dan apa sahaja yang kamu dermakan maka Allah akan menggantikannya; dan Dia lah jua sebaik-baik Pemberi rezeki”.', FALSE, NULL, NULL, 432, 22, 173, 374, FALSE, 0, NULL),
(34, 40, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَائِكَةِ أَهَٰؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ', NULL, 'And [mention] the Day when He will gather them all and then say to the angels, "Did these [people] used to worship you?"', 'Dan (ingatkanlah) masa Allah menghimpunkan mereka semua (pada hari kiamat), kemudian Ia bertanya kepada malaikat: “Adakah orang-orang ini, (kamu setujui) menyembah kamu dahulu?”', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 41, 'قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', 'قَالُوا سُبْحَانَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا يَعْبُدُونَ الْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', NULL, 'They will say, "Exalted are You! You, [O Allāh], are our benefactor excluding [i.e., not] them. Rather, they used to worship the jinn; most of them were believers in them."', 'Malaikat menjawab: “Maha Suci Engkau (dari adanya sebarang sekutu denganMu). Engkaulah (yang kami hubungi sebagai Pemimpin dan) Pelindung kami bukan mereka. (Tidak ada hubungan dari pihak kami dengan mereka mengenai penyembahan mereka kepada kami), bahkan mereka adalah menyembah Jin Syaitan; kebanyakan mereka pula percaya kepada Jin Syaitan itu (sebagai sekutu Tuhan yang dipuja dan dipatuhi)”.', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 42, 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'فَالْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا ذُوقُوا عَذَابَ النَّارِ الَّتِي كُنتُم بِهَا تُكَذِّبُونَ', NULL, 'But today [i.e., the Day of Judgement] you do not hold for one another [the power of] benefit or harm, and We will say to those who wronged, "Taste the punishment of the Fire, which you used to deny."', 'Maka pada hari ini, masing-masing di antara kamu tidak berkuasa memberi sebarang manfaat kepada kawannya, dan tidak pula dapat menolak sesuatu bahaya daripadanya; dan Kami katakan kepada orang-orang yang zalim (yang berlaku syirik) itu: “Rasalah azab neraka yang kamu dahulu mendustakannya”.', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 43, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالُوا مَا هَٰذَا إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ آبَاؤُكُمْ وَقَالُوا مَا هَٰذَا إِلَّا إِفْكٌ مُّفْتَرًى وَقَالَ الَّذِينَ كَفَرُوا لِلْحَقِّ لَمَّا جَاءَهُمْ إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ', NULL, 'And when Our verses are recited to them as clear evidences, they say, "This is not but a man who wishes to avert you from that which your fathers were worshipping." And they say, "This is not except a lie invented." And those who disbelieve say of the truth when it has come to them, "This is not but obvious magic."', 'Dan apabila dibacakan kepada mereka ayat-ayat keterangan Kami yang jelas nyata, berkatalah mereka (sesama sendiri): “Orang ini (Muhammad) tidak lain hanyalah seorang lelaki yang hendak menghalang kamu daripada menyembah apa yang telah disembah oleh datuk nenek kamu”; dan mereka berkata lagi: (Al-Quran) ini tidak lain hanyalah kata-kata dusta yang direka-reka”; dan berkatalah orang-orang yang kafir terhadap kebenaran ketika datangnya kepada mereka: “ini tidak lain hanyalah sihir yang terang nyata”.', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 44, 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', 'وَمَا آتَيْنَاهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَا أَرْسَلْنَا إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', NULL, 'And We had not given them any scriptures which they could study, and We had not sent to them before you, [O Muḥammad], any warner.', 'Dan (tidak ada sebarang alasan bagi dakwaan mereka, kerana) Kami tidak pernah memberi kepada mereka Kitab-kitab untuk mereka membaca dan mengkajinya, dan Kami juga tidak pernah mengutus kepada mereka sebelummu (wahai Muhammad) seseorang Rasul pemberi amaran (melarang mereka menerima ajaranmu).', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 45, 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ', 'وَكَذَّبَ الَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا مِعْشَارَ مَا آتَيْنَاهُمْ فَكَذَّبُوا رُسُلِي فَكَيْفَ كَانَ نَكِيرِ', NULL, 'And those before them denied, and they [i.e., the people of Makkah] have not attained a tenth of what We had given them. But they [i.e., the former peoples] denied My messengers, so how [terrible] was My reproach.', 'Dan (ketahuilah bahawa) umat-umat yang terdahulu sebelum mereka telah juga mendustakan (Rasul-rasulnya), sedang mereka (yang mendustakanmu) itu tidak: mencapai satu persepuluh (dari kekayaan, kepandaian dan kekuatan) yang Kami beri kepada umat-umat yang terdahulu itu; setelah umat-umat itu mendustakan Rasul-rasulKu (mereka pun dibinasakan). Dengan yang demikian perhatikanlah bagaimana buruknya akibat kemurkaanKu (menimpa mereka).', FALSE, NULL, NULL, 433, 22, 173, 374, FALSE, 0, NULL),
(34, 46, 'قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ', 'قُلْ إِنَّمَا أَعِظُكُم بِوَاحِدَةٍ أَن تَقُومُوا لِلَّهِ مَثْنَىٰ وَفُرَادَىٰ ثُمَّ تَتَفَكَّرُوا مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ', NULL, 'Say, "I only advise you of one [thing] - that you stand for Allāh, [seeking truth] in pairs and individually, and then give thought." There is not in your companion any madness. He is only a warner to you before a severe punishment.', 'Katakanlah (wahai Muhammad): “Aku hanyalah mengajar dan menasihati kamu dengan satu perkara sahaja, iaitu: hendaklah kamu bersungguh-sungguh berusaha mencari kebenaran kerana Allah semata-mata, sama ada dengan cara berdua (dengan orang lain), atau seorang diri; kemudian hendaklah kamu berfikir sematang-matangnya (untuk mengetahui salah benarnya ajaranKu)”. Sebenarnya tidak ada pada (Muhammad) yang menjadi sahabat kamu sebarang penyakit gila (sebagaimana yang dituduh); ia hanyalah seorang Rasul pemberi amaran kepada kamu, sebelum kamu ditimpa azab yang berat (di akhirat).', FALSE, NULL, NULL, 433, 22, 174, 375, FALSE, 0, NULL),
(34, 47, 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ', NULL, 'Say, "Whatever payment I might have asked of you - it is yours. My payment is only from Allāh, and He is, over all things, Witness."', 'Katakanlah (wahai Muhammad): “Apa jua yang aku harap kamu berikan kepadaku sebagai upah maka faedahnya tetap terpulang kepada kamu; balasan yang menjadi upahku yang sebenar hanyalah dari Allah, dan Ia sentiasa Memerhati serta Menyaksikan tiap-tiap sesuatu”.', FALSE, NULL, NULL, 433, 22, 174, 375, FALSE, 0, NULL),
(34, 48, 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ', 'قُلْ إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ عَلَّامُ الْغُيُوبِ', NULL, 'Say, "Indeed, my Lord projects the truth, Knower of the unseen."', 'Katakanlah lagi: “Sesungguhnya TuhanKu, menurunkan wahyu (kepada Nabi-nabi pilihanNya) dengan perkara yang benar; Ia sentiasa Mengetahui akan segala perkara yang ghaib”.', FALSE, NULL, NULL, 433, 22, 174, 375, FALSE, 0, NULL),
(34, 49, 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ', 'قُلْ جَاءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ', NULL, 'Say, "The truth has come, and falsehood can neither begin [anything] nor repeat [it]."', 'Katakanlah lagi: “Telah datang kebenaran (Al-Quran yang memberi segala kebaikan), dan perkara yang salah tidak memberi sebarang kebaikan di dunia, usahkan hendak mengulanginya di akhirat”.', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(34, 50, 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ إِنَّهُۥ سَمِيعٌ قَرِيبٌ', 'قُلْ إِن ضَلَلْتُ فَإِنَّمَا أَضِلُّ عَلَىٰ نَفْسِي وَإِنِ اهْتَدَيْتُ فَبِمَا يُوحِي إِلَيَّ رَبِّي إِنَّهُ سَمِيعٌ قَرِيبٌ', NULL, 'Say, "If I should err, I would only err against myself. But if I am guided, it is by what my Lord reveals to me. Indeed, He is Hearing and near."', 'Katakanlah lagi: “Sekiranya aku sesat maka bahaya kesesatanku akan menimpa diriku sendiri, dan jika aku beroleh hidayah petunjuk maka yang demikian disebabkan apa yang telah diwahyukan oleh Tuhanku kepadaku; sesungguhnya Ia Maha Mendengar, lagi Maha Dekat”.', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(34, 51, 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ', 'وَلَوْ تَرَىٰ إِذْ فَزِعُوا فَلَا فَوْتَ وَأُخِذُوا مِن مَّكَانٍ قَرِيبٍ', NULL, 'And if you could see when they are terrified but there is no escape, and they will be seized from a place nearby.', 'Dan (sungguh ngeri) jika engkau melihat (keadaan orang-orang yang bersalah itu) ketika mereka gelisah takut (menyaksikan azabnya) serta mereka tidak mendapat jalan mengelaknya, dan mereka pun diambil dari tempat mereka berada (untuk dibawa ke tempat azab).', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(34, 52, 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ', 'وَقَالُوا آمَنَّا بِهِ وَأَنَّىٰ لَهُمُ التَّنَاوُشُ مِن مَّكَانٍ بَعِيدٍ', NULL, 'And they will [then] say, "We believe in it!" But how for them will be the taking [of faith] from a place far away?', 'Dan (pada ketika itu) mereka berkata: “Kami sekarang beriman kepada kebenaran yang di bawa oleh Nabi Muhammad (s.a.w)”; (apa jalannya) dan bagaimana caranya mereka dapat mencapai iman dari tempat yang jauh?', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(34, 53, 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ', 'وَقَدْ كَفَرُوا بِهِ مِن قَبْلُ وَيَقْذِفُونَ بِالْغَيْبِ مِن مَّكَانٍ بَعِيدٍ', NULL, 'And they had already disbelieved in it before and would assault the unseen from a place far away.', 'Pada hal mereka telah mengingkarinya sebelum itu, dan mereka pula selalu melemparkan tuduhan-tuduhan buta terhadap kebenaran itu dari tempat yang jauh? (sudah tentu salah).', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(34, 54, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ', 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا فِي شَكٍّ مُّرِيبٍ', NULL, 'And prevention will be placed between them and what they desire, as was done with their kind before. Indeed, they were in disquieting doubt [i.e., denial].', 'Dan disekatlah di antara mereka dengan (iman) yang mereka ingini, sebagaimana yang telah dilakukan kepada orang-orang yang sama keadaannya dengan mereka pada masa yang lalu; sesungguhnya mereka dahulu berada dalam keadaan syak yang meragukan.', FALSE, NULL, NULL, 434, 22, 174, 375, FALSE, 0, NULL),
(35, 1, 'ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَـٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'الحمد لله فاطر السماوات والارض جاعل الملائكة رسلا اولي اجنحة مثنى وثلاث ورباع يزيد في الخلق ما يشاء ان الله على كل شيء قدير', NULL, '[All] praise is [due] to Allāh, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allāh is over all things competent.', 'Segala puji tertentu bagi Allah yang menciptakan langit dan bumi, yang menjadikan malaikat utusan-utusan yang bersayap: dua, tiga dan empat; Ia menambah pada bentuk kejadian makhluk yang diciptakanNya apa jua yang dikehendakiNya. Sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 434, 22, 174, 376, FALSE, 24, NULL),
(35, 2, 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا ۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ما يفتح الله للناس من رحمة فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم', NULL, 'Whatever Allāh grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise.', 'Apa jua jenis rahmat yang dibukakan oleh Allah kepada manusia, maka tidak ada sesuatupun yang dapat menahannya; dan apa jua yang ditahan oleh Allah maka tidak ada sesuatupun yang dapat melepaskannya sesudah itu. Dan (ingatlah) Dia lah sahaja yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 434, 22, 174, 376, FALSE, 19, NULL),
(35, 3, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ ۚ هَلْ مِنْ خَـٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 'يا ايها الناس اذكروا نعمت الله عليكم هل من خالق غير الله يرزقكم من السماء والارض لا اله الا هو فانى تؤفكون', NULL, 'O mankind, remember the favor of Allāh upon you. Is there any creator other than Allāh who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?', 'Wahai umat manusia, kenangkanlah nikmat Allah yang telah dikurniakanNya kepada kamu; tidak ada sama sekali yang menciptakan sesuatu selain daripada Allah; Ia memberi rezeki kepada kamu dari langit dan bumi. Tiada Tuhan melainkan Dia, maka mengapa kamu rela dipalingkan (dari menyembahnya)?', FALSE, NULL, NULL, 434, 22, 174, 376, FALSE, 21, NULL),
(35, 4, 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'وان يكذبوك فقد كذبت رسل من قبلك والى الله ترجع الامور', NULL, 'And if they deny you, [O Muḥammad] - already were messengers denied before you. And to Allāh are returned [all] matters.', 'Dan jika mereka mendustakanmu (wahai Muhammad), maka sesungguhnya Rasul-rasul yang terdahulu sebelummu telah juga didustakan (oleh kaumnya masing-masing). Dan (Ingatlah), kepada Allah jualah dikembalikan segala urusan.', FALSE, NULL, NULL, 435, 22, 174, 376, FALSE, 11, NULL),
(35, 5, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ ۖ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۖ وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'يا ايها الناس ان وعد الله حق فلا تغرنكم الحياة الدنيا ولا يغرنكم بالله الغرور', NULL, 'O mankind, indeed the promise of Allāh is truth, so let not the worldly life delude you and be not deceived about Allāh by the Deceiver [i.e., Satan].', 'Wahai umat manusia, sesungguhnya janji Allah (membalas amal kamu) adalah benar; maka janganlah kamu diperdayakan oleh kemewahan hidup di dunia, dan janganlah Syaitan yang menjadi sebesar-besar penipu itu berpeluang menyebabkan kamu terpedaya dengan (kemurahan) Allah (lalu kamu lalai dan menderhaka).', FALSE, NULL, NULL, 435, 22, 174, 376, FALSE, 14, NULL),
(35, 6, 'إِنَّ ٱلشَّيْطَـٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا ۚ إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَـٰبِ ٱلسَّعِيرِ', 'ان الشيطان لكم عدو فاتخذوه عدوا انما يدعو حزبه ليكونوا من اصحاب السعير', NULL, 'Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze.', 'Sesungguhnya Syaitan adalah musuh bagi kamu, maka jadikanlah dia musuh (yang mesti dijauhi tipu dayanya); sebenarnya dia hanyalah mengajak golongannya supaya menjadi dari penduduk neraka.', FALSE, NULL, NULL, 435, 22, 174, 376, FALSE, 13, NULL),
(35, 7, 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ ۖ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'الذين كفروا لهم عذاب شديد والذين امنوا وعملوا الصالحات لهم مغفرة واجر كبير', NULL, 'Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward.', 'Orang-orang yang kafir, bagi mereka azab yang berat; dan orang-orang yang beriman serta beramal soleh, bagi mereka keampunan dan pahala yang besar.', FALSE, NULL, NULL, 435, 22, 174, 376, FALSE, 13, NULL),
(35, 8, 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا ۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۖ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', 'افمن زين له سوء عمله فراه حسنا فان الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرات ان الله عليم بما يصنعون', NULL, 'Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allāh sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allāh is Knowing of what they do.', 'Maka (fikirkanlah) adakah orang yang diperelokkan kepadanya amal buruknya (oleh Syaitan) lalu ia memandangnya dan mempercayainya baik, (bolehkah disifatkan sebagai orang yang menjalankan peraturan yang ditetapkan Allah untuk memberi hidayah kepadanya, atau sebaliknya)? Kerana sesungguhnya Allah menyesatkan sesiapa yang dikehendakiNya, dan Ia juga memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya. Oleh itu, janganlah engkau membinasakan dirimu (wahai Muhammad) kerana menanggung dukacita terhadap kesesatan mereka. Sesungguhnya Allah Maha Mengetahui akan apa yang mereka kerjakan.', FALSE, NULL, NULL, 435, 22, 174, 377, FALSE, 25, NULL),
(35, 9, 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَـٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَـٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ كَذَٰلِكَ ٱلنُّشُورُ', 'والله الذي ارسل الرياح فتثير سحابا فسقناه الى بلد ميت فاحيينا به الارض بعد موتها كذلك النشور', NULL, 'And it is Allāh who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection.', 'Dan Allah jualah yang menghantarkan angin, lalu angin itu menggerakkan awan, kemudian Kami halakan awan itu ke negeri yang mati (yang kering kontang); lalu Kami hidupkan bumi sesudah matinya dengan (hujan dari awan) itu. Sedemikian itu pula kebangkitan manusia (hidup semula sesudah mati).', FALSE, NULL, NULL, 435, 22, 174, 377, FALSE, 17, NULL),
(35, 10, 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا ۚ إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّـٰلِحُ يَرْفَعُهُۥ ۚ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ ۖ وَمَكْرُ أُو۟لَـٰٓئِكَ هُوَ يَبُورُ', 'من كان يريد العزة فلله العزة جميعا اليه يصعد الكلم الطيب والعمل الصالح يرفعه والذين يمكرون السيئات لهم عذاب شديد ومكر اولئك هو يبور', NULL, 'Whoever desires honor [through power] - then to Allāh belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish.', 'Sesiapa yang mahukan kemuliaan (maka hendaklah ia berusaha mencarinya dengan jalan mematuhi perintah Allah), kerana bagi Allah jualah segala kemuliaan. Kepada Allah lah naiknya segala perkataan yang baik (yang menegaskan iman dan tauhid, untuk dimasukkan ke dalam kira-kira balasan), dan amal yang soleh pula di angkatnya naik (sebagai amal yang makbul - yang memberi kemuliaan kepada yang melakukannya). Dan sebaliknya: orang-orang yang merancangkan kejahatan (untuk mendapat kemuliaan), adalah bagi mereka azab seksa yang berat; dan rancangan jahat mereka (kalau berkesan) akan rosak binasa.', FALSE, NULL, NULL, 435, 22, 174, 377, FALSE, 24, NULL),
(35, 11, 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا ۚ وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَـٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'والله خلقكم من تراب ثم من نطفة ثم جعلكم ازواجا وما تحمل من انثى ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتاب ان ذلك على الله يسير', NULL, 'And Allāh created you from dust, then from a sperm-drop; then He made you mates. And no female conceives nor does she give birth except with His knowledge. And no aged person is granted [additional] life nor is his lifespan lessened but that it is in a register. Indeed, that for Allāh is easy.', 'Dan Allah menciptakan kamu dari tanah, kemudian dari (setitis) air benih, kemudian Ia menjadikan kamu berpasangan (lelaki dan perempuan). Dan tiada mengandung seseorang perempuan (juga seekor betina), dan tidak pula satu-satunya melahirkan (anak yang dikandungnya) melainkan dengan keadaan yang diketahui Allah. Dan tidak diberikan seseorang berumur panjang, juga tidak dijadikan seseorang pendek umurnya, melainkan ada kadarnya di dalam Kitab Ilahi. Sesungguhnya yang demikian itu mudah sahaja kepada Allah.', FALSE, NULL, NULL, 435, 22, 174, 377, FALSE, 34, NULL),
(35, 12, 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَـٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَـٰذَا مِلْحٌ أُجَاجٌ ۖ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا ۖ وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'وما يستوي البحران هذا عذب فرات سائغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حلية تلبسونها وترى الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون', NULL, 'And not alike are the two seas [i.e., bodies of water]. One is fresh and sweet, palatable for drinking, and one is salty and bitter. And from each you eat tender meat and extract ornaments which you wear, and you see the ships plowing through [them] that you might seek of His bounty; and perhaps you will be grateful.', 'Dan tidaklah sama keadaan dua laut (sekalipun satu jenisnya), yang satu tawar lagi memuaskan dahaga serta sesuai diminum, sementara yang satu lagi masin lagi pahit. Dan (kedua-duanya itu berfaedah kepada kamu): dari tiap-tiap satunya kamu dapat makan daging yang lembut - hidup-hidup, dan dapat pula kamu mengeluarkan benda-benda perhiasan untuk kamu memakainya; (selain itu) engkau melihat pula kapal-kapal membelah air belayar padanya; (diadakan semuanya itu) supaya kamu dapat mencari rezeki dari limpah kurnia Allah, dan supaya kamu bersyukur.', FALSE, NULL, NULL, 436, 22, 174, 377, FALSE, 28, NULL),
(35, 13, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۚ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', 'يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري لاجل مسمى ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير', NULL, 'He causes the night to enter the day, and He causes the day to enter the night and has subjected the sun and the moon - each running [its course] for a specified term. That is Allāh, your Lord; to Him belongs sovereignty. And those whom you invoke other than Him do not possess [as much as] the membrane of a date seed.', 'Allah jua yang memasukkan malam pada siang dan memasukkan siang pada malam (silih berganti), dan Ia yang memudahkan peredaran matahari dan bulan; tiap-tiap satu dari keduanya beredar untuk suatu masa yang telah ditetapkan. Yang melakukan semuanya itu ialah Allah Tuhan kamu, bagiNyalah kuasa pemerintahan; sedang mereka yang kamu sembah - yang lain dari Allah - tidak mempunyai sesuatu pun walau senipis selaput biji kurma.', FALSE, NULL, NULL, 436, 22, 174, 377, FALSE, 28, NULL),
(35, 14, 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ ۚ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ', 'ان تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيامة يكفرون بشرككم ولا ينبئك مثل خبير', NULL, 'If you invoke them, they do not hear your supplication; and if they heard, they would not respond to you. And on the Day of Resurrection they will deny your association. And none can inform you like [one] Aware [of all matters].', 'Kalau kamu memohon kepada mereka (yang kamu sembah itu): mereka tidak mendengar permohonan kamu, dan kalaulah mereka mendengar pun, mereka tidak dapat memberikan apa yang kamu pohonkan itu; dan pada hari kiamat pula mereka mengingkari perbuatan syirik kamu. Dan (ingatlah) tidak ada yang dapat memberi tahu kepadamu (wahai Muhammad, akan hakikat yang sebenarnya) seperti yang diberikan Allah Yang Maha Mendalam PengetahuanNya.', FALSE, NULL, NULL, 436, 22, 174, 377, FALSE, 18, NULL),
(35, 15, '۞ يَـٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ ۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'يا ايها الناس انتم الفقراء الى الله والله هو الغني الحميد', NULL, 'O mankind, you are those in need of Allāh, while Allāh is the Free of need, the Praiseworthy.', '(Oleh kerana Allah menguasai segala-galanya, maka) wahai umat manusia, kamulah yang sentiasa berhajat kepada Allah (dalam segala perkara), sedang Allah Dia lah sahaja Yang Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 436, 22, 175, 378, FALSE, 10, NULL),
(35, 16, 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'ان يشا يذهبكم ويات بخلق جديد', NULL, 'If He wills, He can do away with you and bring forth a new creation.', 'Jika Ia mahu, nescaya Ia membinasakan kamu dan mendatangkan makhluk yang baharu.', FALSE, NULL, NULL, 436, 22, 175, 378, FALSE, 6, NULL),
(35, 17, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'وما ذلك على الله بعزيز', NULL, 'And that is for Allāh not difficult.', 'Dan (perlaksanaan) yang demikian itu tidaklah sukar bagi Allah.', FALSE, NULL, NULL, 436, 22, 175, 378, FALSE, 5, NULL),
(35, 18, 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ ۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ ۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ ۚ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'ولا تزر وازرة وزر اخرى وان تدع مثقلة الى حملها لا يحمل منه شيء ولو كان ذا قربى انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلاة ومن تزكى فانما يتزكى لنفسه والى الله المصير', NULL, 'And no bearer of burdens will bear the burden of another. And if a heavily laden soul calls [another] to [carry some of] its load, nothing of it will be carried, even if he should be a close relative. You can only warn those who fear their Lord unseen and have established prayer. And whoever purifies himself only purifies himself for [the benefit of] his soul. And to Allāh is the [final] destination.', 'Dan (ketahuilah), seseorang pemikul tldak akan memikul dosa perbuatan orang lain; dan jika seseorang yang berat tanggungnya (dengan dosa), memanggil (orang lain) untuk menolong memikul sama bebanan itu, tidak akan dapat dipikul sedikitpun daripadanya, walaupun orang yang diminta pertolongannya itu dari kerabatnya sendiri. Sesungguhnya engkau (wahai Muhammad) hanyalah memberi peringatan kepada orang-orang yang takut (melanggar hukum-hukum) Tuhan semasa mereka tidak dilihat orang dan semasa mereka tidak melihat azab Tuhan, serta mereka mendirikan sembahyang. Dan sesiapa yang membersihkan dirinya (dari segala yang dilarang) maka sesungguhnya ia melakukan pembersihan itu untuk kebaikan dirinya sendiri dan (ingatlah), kepada Allah jualah tempat kembali.', FALSE, NULL, NULL, 436, 22, 175, 378, FALSE, 34, NULL),
(35, 19, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', 'وما يستوي الاعمى والبصير', NULL, 'Not equal are the blind and the seeing,', 'Dan tidaklah sama orang buta dengan orang yang celek.', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 4, NULL),
(35, 20, 'وَلَا ٱلظُّلُمَـٰتُ وَلَا ٱلنُّورُ', 'ولا الظلمات ولا النور', NULL, 'Nor are the darknesses and the light,', 'Dan tidaklah sama gelap-gelita dengan cahaya yang terang-benderang,', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 4, NULL),
(35, 21, 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', 'وَلَا الظِّلُّ وَلَا الْحَرُورُ', NULL, 'Nor are the shade and the heat,', 'Dan tidaklah sama suasana yang teduh dengan yang kencang panasnya.', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 22, 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ', 'وَمَا يَسْتَوِي الْأَحْيَاءُ وَلَا الْأَمْوَاتُ إِنَّ اللَّهَ يُسْمِعُ مَن يَشَاءُ وَمَا أَنتَ بِمُسْمِعٍ مَّن فِي الْقُبُورِ', NULL, 'And not equal are the living and the dead. Indeed, Allāh causes to hear whom He wills, but you cannot make hear those in the graves.', 'Dan (Demikianlah pula) tidaklah sama orang-orang yang hidup dengan orang-orang yang mati. Sesungguhnya Allah, (menurut undang-undang peraturanNya), dapat menjadikan sesiapa yang dikehendakinya mendengar (ajaran-ajaran Kitab Allah serta menerimanya), dan (engkau wahai Muhammad) tidak dapat menjadikan orang-orang yang di dalam kubur mendengar (dan menerimanya).', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 23, 'إِنْ أَنتَ إِلَّا نَذِيرٌ', 'إِنْ أَنتَ إِلَّا نَذِيرٌ', NULL, 'You, [O Muḥammad], are not but a warner.', 'Engkau tidak lain hanyalah seorang Rasul pemberi ingatan dan amaran.', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 24, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', 'إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', NULL, 'Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner.', 'Sesungguhnya Kami mengutusmu dengan (Ugama) yang benar, sebagai pembawa berita gembira (kepada orang-orang yang beriman) dan pemberi amaran (kepada orang-orang yang ingkar); dan tidak ada, sesuatu umat pun melainkan telah ada dalam kalangannya dahulu seorang Rasul pemberi ingatan dan amaran.', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 25, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ', 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ جَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ وَبِالزُّبُرِ وَبِالْكِتَابِ الْمُنِيرِ', NULL, 'And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture.', 'Dan jika mereka (yang kafir itu) mendustakanmu, (maka yang demikian itu tidaklah menjadi hal) kerana sesungguhnya orang-orang yang terdahulu sebelum mereka telah juga mendustakan (Rasul masing-masing), mereka telah didatangi Rasul-rasulnya dengan membawa keterangan-keterangan (mukjizat) yang nyata dan Kitab-kitab (nasihat pengajaran) serta Kitab-kitab (syariat) yang terang jelas.', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 26, 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ فَكَيْفَ كَانَ نَكِيرِ', 'ثُمَّ أَخَذْتُ الَّذِينَ كَفَرُوا فَكَيْفَ كَانَ نَكِيرِ', NULL, 'Then I seized the ones who disbelieved, and how [terrible] was My reproach.', 'Kemudian Aku timpakan orang-orang kafir itu dengan azab yang membinasakan, maka perhatikanlah bagaimana buruknya akibat kemurkaanKu (menimpa mereka).', FALSE, NULL, NULL, 437, 22, 175, 378, FALSE, 0, NULL),
(35, 27, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ', 'أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِ ثَمَرَاتٍ مُّخْتَلِفًا أَلْوَانُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَانُهَا وَغَرَابِيبُ سُودٌ', NULL, 'Do you not see that Allāh sends down rain from the sky, and We produce thereby fruits of varying colors? And in the mountains are tracts, white and red of varying shades and [some] extremely black.', 'Tidakkah engkau melihat bahawa Allah menurunkan hujan dari langit, lalu Kami keluarkan dengan air hujan itu buah-buahan yang berlainan jenis dan rupanya; dan di antara gunung-ganang pula ada yang mempunyai jalur-jalur serta lorong-lorong putih dan merah, yang berlainan warnanya (tua dan muda) dan ada juga yang hitam legam;', FALSE, NULL, NULL, 437, 22, 175, 379, FALSE, 0, NULL),
(35, 28, 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', 'وَمِنَ النَّاسِ وَالدَّوَابِّ وَالْأَنْعَامِ مُخْتَلِفٌ أَلْوَانُهُ كَذَٰلِكَ إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ إِنَّ اللَّهَ عَزِيزٌ غَفُورٌ', NULL, 'And among people and moving creatures and grazing livestock are various colors similarly. Only those fear Allāh, from among His servants, who have knowledge. Indeed, Allāh is Exalted in Might and Forgiving.', 'Dan demikian pula di antara manusia dan binatang-binatang yang melata serta binatang-binatang ternak, ada yang berlainan jenis dan warnanya? Sebenarnya yang menaruh bimbang dan takut (melanggar perintah) Allah dari kalangan hamba-hambaNya hanyalah orang-orang yang berilmu. Sesungguhnya Allah Maha Kuasa, lagi Maha Pengampun.', FALSE, NULL, NULL, 437, 22, 175, 379, FALSE, 0, NULL),
(35, 29, 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ', 'إِنَّ الَّذِينَ يَتْلُونَ كِتَابَ اللَّهِ وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَارَةً لَّن تَبُورَ', NULL, 'Indeed, those who recite the Book of Allāh and establish prayer and spend [in His cause] out of what We have provided them, secretly and publicly, [can] expect a transaction [i.e., profit] that will never perish -', 'Sesungguhnya orang-orang yang selalu membaca Kitab Allah dan tetap mendirikan sembahyang serta mendermakan dari apa yang Kami kurniakan kepada mereka, secara bersembunyi atau secara terbuka, mereka (dengan amalan yang demikian) mengharapkan sejenis perniagaan yang tidak akan mengalami kerugian;', FALSE, NULL, NULL, 437, 22, 175, 379, FALSE, 0, NULL),
(35, 30, 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ إِنَّهُۥ غَفُورٌ شَكُورٌ', 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِ إِنَّهُ غَفُورٌ شَكُورٌ', NULL, 'That He may give them in full their rewards and increase for them of His bounty. Indeed, He is Forgiving and Appreciative.', 'Supaya Allah menyempurnakan pahala mereka dan menambahi mereka dari limpah kurniaNya. Sesungguhnya Allah Maha Pengampun, lagi sentiasa membalas dengan sebaik-baiknya (akan orang-orang yang bersyukur kepadaNya).', FALSE, NULL, NULL, 437, 22, 175, 379, FALSE, 0, NULL),
(35, 31, 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ', 'وَالَّذِي أَوْحَيْنَا إِلَيْكَ مِنَ الْكِتَابِ هُوَ الْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ اللَّهَ بِعِبَادِهِ لَخَبِيرٌ بَصِيرٌ', NULL, 'And that which We have revealed to you, [O Muḥammad], of the Book is the truth, confirming what was before it. Indeed Allāh, of His servants, is Aware and Seeing.', 'Dan Al-Quran yang Kami wahyukan kepadamu (wahai Muhammad) ialah yang benar (segala-galanya) yang tetap mengesahkan Kitab-kitab yang diturunkan sebelumnya. Sesungguhnya Allah Maha Mengetahui dengan sedalam-dalamnya akan keadaan sekalian hambaNya, lagi Maha Melihat dan memerhatikan.', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 32, 'ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ذَٰلِكَ هُوَ الْفَضْلُ الْكَبِيرُ', NULL, 'Then We caused to inherit the Book those We have chosen of Our servants; and among them is he who wrongs himself [i.e., sins], and among them is he who is moderate, and among them is he who is foremost in good deeds by permission of Allāh. That [inheritance] is what is the great bounty.', 'Kemudian Kami jadikan Al-Quran itu diwarisi oleh orang-orang yang Kami pilih dari kalangan hamba-hamba Kami; maka di antara mereka ada yang berlaku zalim kepada dirinya sendiri (dengan tidak mengindahkan ajaran Al-Quran), dan di antaranya ada yang bersikap sederhana, dan di antaranya pula ada yang mendahului (orang lain) dalam berbuat kebaikan dengan izin Allah. Yang demikian itu ialah limpah kurnia yang besar (dari Allah semata-mata).', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 33, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', NULL, '[For them are] gardens of perpetual residence which they will enter. They will be adorned therein with bracelets of gold and pearls, and their garments therein will be silk.', '(Balasan mereka ialah) Syurga - syurga “And”, yang mereka akan masukinya; mereka dihiaskan di dalamnya dengan gelang-gelang tangan dari emas dan mutiara; dan pakaian mereka di situ adalah dari sutera.', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 34, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', 'وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', NULL, 'And they will say, "Praise to Allāh, who has removed from us [all] sorrow. Indeed, our Lord is Forgiving and Appreciative -', 'Dan (sebagai bersyukur) berkatalah mereka: “Segala puji tertentu bagi Allah, yang telah menghapuskan perasaan dukacita dari kami; Sesungguhnya Tuhan kami Maha Pengampun, lagi sentiasa memberi balasan yang sebaik-baiknya (kepada orang-orang yang taat);', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 35, 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', 'الَّذِي أَحَلَّنَا دَارَ الْمُقَامَةِ مِن فَضْلِهِ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', NULL, 'He who has settled us in the home of duration [i.e., Paradise] out of His bounty. There touches us not in it any fatigue, and there touches us not in it weariness [of mind]."', 'Tuhan yang telah menempatkan kami di tempat tinggal yang kekal, dengan limpah kurniaNya semata-mata. Kami tidak akan merasa penat lelah di situ, dan Kami juga di situ tidak akan merasa letih lesu”.', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 36, 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ', 'وَالَّذِينَ كَفَرُوا لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِي كُلَّ كَفُورٍ', NULL, 'And for those who disbelieve will be the fire of Hell. [Death] is not decreed for them so they may die, nor will its torment be lightened for them. Thus do We recompense every ungrateful one.', 'Dan orang-orang yang kafir, bagi mereka neraka Jahannam; mereka tidak dijatuhkan hukuman bunuh supaya mereka mati (dan terlepas dari seksa), dan tidak pula diringankan azab neraka itu dari mereka; dan demikianlah Kami membalas tiap-tiap orang yang melampau kufurnya.', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 37, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَا أَخْرِجْنَا نَعْمَلْ صَالِحًا غَيْرَ الَّذِي كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَاءَكُمُ النَّذِيرُ فَذُوقُوا فَمَا لِلظَّالِمِينَ مِن نَّصِيرٍ', NULL, 'And they will cry out therein, "Our Lord, remove us; we will do righteousness - other than what we were doing!" But did We not grant you life enough for whoever would remember therein to remember, and the warner had come to you? So taste [the punishment], for there is not for the wrongdoers any helper.', 'Dan mereka menjerit-jerit di dalam neraka itu (sambil merayu): “Wahai Tuhan kami, keluarkanlah kami (dari azab ini); kami akan mengerjakan amal-amal yang soleh, yang lain dari apa yang kami pernah kerjakan. (lalu Allah menempelak mereka): “Bukankah Kami telah melanjutkan umur kamu dan memberikan masa yang cukup untuk berfikir dan beringat padanya oleh sesiapa yang suka berfikir dan beringat? Dan kamu pula telah didatangi oleh Rasul (Kami) yang memberi amaran oleh itu, rasalah (azab seksa), kerana orang-orang yang zalim tidak akan beroleh sesiapapun yang dapat memberikan pertolongan”.', FALSE, NULL, NULL, 438, 22, 175, 379, FALSE, 0, NULL),
(35, 38, 'إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'إِنَّ اللَّهَ عَالِمُ غَيْبِ السَّمَاوَاتِ وَالْأَرْضِ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, 'Indeed, Allāh is Knower of the unseen [aspects] of the heavens and earth. Indeed, He is Knowing of that within the breasts.', 'Sesungguhnya Allah mengetahui segala rahsia di langit dan di bumi; sesungguhnya Ia mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 438, 22, 175, 380, FALSE, 0, NULL),
(35, 39, 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', 'هُوَ الَّذِي جَعَلَكُمْ خَلَائِفَ فِي الْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُ وَلَا يَزِيدُ الْكَافِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ الْكَافِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', NULL, 'It is He who has made you successors upon the earth. And whoever disbelieves - upon him will be [the consequence of] his disbelief. And the disbelief of the disbelievers does not increase them in the sight of their Lord except in hatred; and the disbelief of the disbelievers does not increase them except in loss.', 'Dia lah yang menjadikan kamu orang-orang yang berkuasa di muka bumi silih berganti; oleh itu sesiapa yang kufur ingkar maka balasan kufurnya itu akan menimpa dirinya sendiri; dan orang-orang yang kafir, kufurnya tidak menambahkan mereka di sisi Tuhan mereka melainkan kemurkaan dan kehinaan; dan juga orang-orang yang kafir itu, kufurnya tidak menambahkan mereka melainkan kerugian jua.', FALSE, NULL, NULL, 439, 22, 175, 380, FALSE, 0, NULL),
(35, 40, 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', 'قُلْ أَرَأَيْتُمْ شُرَكَاءَكُمُ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ أَرُونِي مَاذَا خَلَقُوا مِنَ الْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِي السَّمَاوَاتِ أَمْ آتَيْنَاهُمْ كِتَابًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ الظَّالِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', NULL, 'Say, "Have you considered your ''partners'' whom you invoke besides Allāh? Show me what they have created from the earth, or have they partnership [with Him] in the heavens? Or have We given them a book so they are [standing] on evidence therefrom? [No], rather, the wrongdoers do not promise each other except delusion."', 'Katakanlah (wahai Muhammad): “Sudahkah kamu mengetahui kekuasaan dan kelayakan makhluk-makhluk yang kamu jadikan sekutu-sekutu, yang kamu seru dan sembah selain Allah? Tunjukkanlah kepadaku apa yang mereka telah ciptakan dari bahagian bumi ini?. Atau adakah mereka mempunyai sebarang perkongsian (dengan Allah) dalam mencipta dan menguruskan langit? Atau pernahkah Kami memberi mereka sebuah Kitab (mengakui mereka menjadi kongsi Kami), maka (dengan itu menjadilah) perkongsian mereka berdasarkan keterangan yang terdapat dari Kitab itu? “(Tidak ada sesuatu alasan pun) bahkan orang-orang yang zalim itu, terpedaya dengan kata-kata yang disebutkan oleh setengahnya kepada yang lain, kata-kata yang hanya menjanjikan perkara yang tidak benar.', FALSE, NULL, NULL, 439, 22, 175, 380, FALSE, 0, NULL),
(35, 41, 'إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَا إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّن بَعْدِهِ إِنَّهُ كَانَ حَلِيمًا غَفُورًا', NULL, 'Indeed, Allāh holds the heavens and the earth, lest they cease. And if they should cease, no one could hold them [in place] after Him. Indeed, He is Forbearing and Forgiving.', 'Sesungguhnya Allah menahan dan memelihara langit dan bumi supaya tidak berganjak dari peraturan dan keadaan yang ditetapkan baginya; dan jika keduanya (ditakdirkan) berganjak maka tidak ada sesiapapun yang dapat menahannya daripada berlaku demikian selain dari Allah. Sesungguhnya Ia Maha Penyabar, lagi Maha Pengampun.', FALSE, NULL, NULL, 439, 22, 176, 380, FALSE, 0, NULL),
(35, 42, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', 'وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِن جَاءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى الْأُمَمِ فَلَمَّا جَاءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', NULL, 'And they swore by Allāh their strongest oaths that if a warner came to them, they would be more guided than [any] one of the [previous] nations. But when a warner came to them, it did not increase them except in aversion', 'Dan mereka bersumpah dengan nama Allah dengan sebebar-benar sumpahnya: demi sesungguhnya jika datang kepada mereka seorang Rasul pemberi ingatan dan amaran, sudah tentu mereka akan menjadi orang-orang yang lebih betul jalan ugamanya dari sebarang umat yang lain. Setelah datang kepada mereka seorang Rasul pemberi ingatan dan amaran, (maka kedatangannya itu) hanya menyebabkan mereka bertambah liar dari kebenaran,', FALSE, NULL, NULL, 439, 22, 176, 380, FALSE, 0, NULL),
(35, 43, 'ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', 'اسْتِكْبَارًا فِي الْأَرْضِ وَمَكْرَ السَّيِّئِ وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ الْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا', NULL, '[Due to] arrogance in the land and plotting of evil; but the evil plot does not encompass except its own people. Then do they await except the way [i.e., fate] of the former peoples? But you will never find in the way [i.e., established method] of Allāh any change, and you will never find in the way of Allāh any alteration.', 'Sambil bersikap sombong takbur di muka bumi dan berusaha merancangkan rancangan-rancangan jahat (terhadap Rasul itu), sedang rancangan yang jahat itu tidak menimpa melainkan orang yang menjalankannya. (Dengan keadaan yang demikian, maka) tidak ada yang mereka tunggu selain daripada berlakunya kebinasaan menimpa mereka (sebagaimana yang telah menimpa) orang-orang kafir yang telah lalu. Kerana engkau tidak sekali-kali akan mendapati sebarang perubahan bagi “Sunnatullah” (undang-undang peraturan Allah), dan engkau tidak sekali-kali akan mendapati sebarang penukaran bagi perjalanan “Sunnatullah” itu.', FALSE, NULL, NULL, 439, 22, 176, 380, FALSE, 0, NULL),
(35, 44, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا', 'أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ وَكَانُوا أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِن شَيْءٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ إِنَّهُ كَانَ عَلِيمًا قَدِيرًا', NULL, 'Have they not traveled through the land and observed how was the end of those before them? And they were greater than them in power. But Allāh is not to be caused failure [i.e., prevented] by anything in the heavens or on the earth. Indeed, He is ever Knowing and Competent.', '(Dan sebagai buktinya): tidakkah orang-orang (yang tidak mahu beriman) itu telah mengembara di muka bumi, lalu mereka menyaksikan bagaimana kesudahan orang-orang kafir yang terdahulu dari mereka, sedang orang-orang itu lebih kekuatannya dari mereka? Dan (sudah tetap) bahawa kekuasaan Allah tidak dapat dilemahkan atau dihalangi oleh sesuatupun sama ada di langit atau di bumi; sesungguhnya Ia adalah Maha Mengetahui, lagi Maha Kuasa.', FALSE, NULL, NULL, 439, 22, 176, 380, FALSE, 0, NULL),
(35, 45, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', 'وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَابَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰ أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا', NULL, 'And if Allāh were to impose blame on the people for what they have earned, He would not leave upon it [i.e., the earth] any creature. But He defers them for a specified term. And when their time comes, then indeed Allāh has ever been, of His servants, Seeing.', 'Dan kalaulah Allah mengirakan kesalahan manusia serta terus menyeksa mereka disebabkan amal-amal jahat yang mereka telah kerjakan, tentulah la tidak membiarkan tinggal di muka bumi sesuatu makhluk yang bergerak; akan tetapi (dia tidak bertindak dengan serta merta, bahkan) Ia memberi tempoh kepada mereka hingga ke suatu masa yang tertentu; kemudian apabila sampai tempoh mereka (maka Allah akan membalas masing-masing dengan adilnya), kerana sesungguhnya Allah sentiasa Melihat keadaan hamba-hambaNya.', FALSE, NULL, NULL, 440, 22, 176, 380, FALSE, 0, NULL),
(36, 1, 'يسٓ', 'يس', NULL, 'Yā, Seen.', 'Yaa, Siin.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 1, NULL),
(36, 2, 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', 'والقران الحكيم', NULL, 'By the wise Qur’ān,', 'Demi Al-Quran yang mengandungi hikmat-hikmat dan kebenaran yang tetap kukuh,', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 2, NULL),
(36, 3, 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'انك لمن المرسلين', NULL, 'Indeed you, [O Muḥammad], are from among the messengers,', 'Sesungguhnya engkau (wahai Muhammad adalah seorang Rasul) dari Rasul-rasul yang telah diutus,', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 3, NULL),
(36, 4, 'عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'على صراط مستقيم', NULL, 'On a straight path.', 'Yang tetap di atas jalan yang lurus (ugama Islam).', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 3, NULL),
(36, 5, 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', 'تنزيل العزيز الرحيم', NULL, '[This is] a revelation of the Exalted in Might, the Merciful,', 'Al-Quran itu, diturunkan oleh Allah Yang Maha Kuasa, lagi Maha Mengasihani,', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 3, NULL),
(36, 6, 'لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَـٰفِلُونَ', 'لتنذر قوما ما انذر اباؤهم فهم غافلون', NULL, 'That you may warn a people whose forefathers were not warned, so they are unaware.', 'Supaya engkau memberi peringatan dan amaran kepada kaum yang datuk neneknya telah lama tidak diberikan peringatan dan amaran; sebab itulah mereka lalai.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 7, NULL),
(36, 7, 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'لقد حق القول على اكثرهم فهم لا يؤمنون', NULL, 'Already the word [i.e., decree] has come into effect upon most of them, so they do not believe.', 'Demi sesungguhnya, telah tetap hukuman seksa atas kebanyakan mereka, kerana mereka tidak mahu beriman.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 8, NULL),
(36, 8, 'إِنَّا جَعَلْنَا فِىٓ أَعْنَـٰقِهِمْ أَغْلَـٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', 'انا جعلنا في اعناقهم اغلالا فهي الى الاذقان فهم مقمحون', NULL, 'Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft.', 'Sesungguhnya Kami jadikan (kesombongan dan keengganan mereka tunduk kepada kebenaran sebagai) belenggu yang memberkas kedua tangan mereka ke batang leher mereka; (lebarnya belenggu itu) sampai (menongkatkan) dagu mereka lalu menjadilah mereka terdongak.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 10, NULL),
(36, 9, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَـٰهُمْ فَهُمْ لَا يُبْصِرُونَ', 'وجعلنا من بين ايديهم سدا ومن خلفهم سدا فاغشيناهم فهم لا يبصرون', NULL, 'And We have put before them a barrier and behind them a barrier and covered them, so they do not see.', 'Dan Kami jadikan (sifat tamak dan gila mereka kepada harta benda dan pangkat itu sebagai) sekatan (yang menghalang mereka daripada memandang kepada keburukan dan kesingkatan masa dunia yang ada) di hadapan mereka, dan sekatan (yang menghalang mereka daripada memikirkan azab yang ada) di belakang mereka (pada hari kiamat). lalu Kami tutup pandangan mereka; maka dengan itu, mereka tidak dapat melihat (jalan yang benar).', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 12, NULL),
(36, 10, 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'وسواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون', NULL, 'And it is all the same for them whether you warn them or do not warn them - they will not believe.', 'Dan (dengan sebab itu) sama sahaja kepada mereka, engkau beri amaran atau engkau tidak beri amaran kepadanya - mereka tidak akan beriman.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 8, NULL),
(36, 11, 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَـٰنَ بِٱلْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ', 'انما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفرة واجر كريم', NULL, 'You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.', 'Sesungguhnya peringatan dan amaran (yang berkesan dan mendatangkan faedah) hanyalah yang engkau berikan kepada orang yang sedia menurut ajaran Al-Quran serta ia takut (melanggar perintah Allah) Ar-Rahman semasa ia tidak dilihat orang dan semasa ia tidak melihat azab Tuhan. Oleh itu berilah kepadanya berita yang mengembirakan dengan keampunan dan pahala yang mulia.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 12, NULL),
(36, 12, 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَـٰرَهُمْ ۚ وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ فِىٓ إِمَامٍ مُّبِينٍ', 'انا نحن نحيي الموتى ونكتب ما قدموا واثارهم وكل شيء احصيناه في امام مبين', NULL, 'Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register.', 'Sesungguhnya Kami menghidupkan orang-orang yang mati, dan Kami tuliskan segala yang mereka telah kerjakan serta segala kesan perkataan dan perbuatan yang mereka tinggalkan. Dan (ingatlah) tiap-tiap sesuatu kami catitkan satu persatu dalam Kitab (ibu Suratan) yang jelas nyata.', FALSE, NULL, NULL, 440, 22, 176, 381, FALSE, 14, NULL),
(36, 13, 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَـٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', 'واضرب لهم مثلا اصحاب القرية اذ جاءها المرسلون', NULL, 'And present to them an example: the people of the city, when the messengers came to it -', 'Dan ceritakanlah kepada mereka satu keadaan yang ajaib mengenai kisah penduduk sebuah bandar (yang tertentu) iaitu ketika mereka didatangi Rasul-rasul (Kami),', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 8, NULL),
(36, 14, 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', 'اذ ارسلنا اليهم اثنين فكذبوهما فعززنا بثالث فقالوا انا اليكم مرسلون', NULL, 'When We sent to them two but they denied them, so We strengthened [them] with a third, and they said, "Indeed, we are messengers to you."', 'Ketika Kami mengutus kepada mereka dua orang Rasul lalu mereka mendustakannya; kemudian Kami kuatkan (kedua Rasul itu) dengan Rasul yang ketiga, lalu Rasul-rasul itu berkata: ‘Sesungguhnya kami ini adalah diutuskan kepada kamu’.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 11, NULL),
(36, 15, 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَـٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', 'قالوا ما انتم الا بشر مثلنا وما انزل الرحمن من شيء ان انتم الا تكذبون', NULL, 'They said, "You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies."', 'Penduduk bandar itu menjawab: “Kamu ini tidak lain hanyalah manusia seperti kami juga, dan Tuhan Yang Maha Pemurah tidak menurunkan sesuatupun (tentang ugama yang kamu dakwakan); Kamu ini tidak lain hanyalah berdusta”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 15, NULL),
(36, 16, 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', 'قالوا ربنا يعلم انا اليكم لمرسلون', NULL, 'They said, "Our Lord knows that we are messengers to you,', 'Rasul-rasul berkata: Tuhan Kami mengetahui bahawa sesungguhnya Kami adalah Rasul-rasul yang diutus kepada kamu,', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 6, NULL),
(36, 17, 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ', 'وما علينا الا البلاغ المبين', NULL, 'And we are not responsible except for clear notification."', '“Dan tugas Kami hanyalah menyampaikan perintah-perintahNya dengan cara yang jelas nyata”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 5, NULL),
(36, 18, 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ', 'قالوا انا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب اليم', NULL, 'They said, "Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment."', 'Penduduk bandar itu berkata pula: “Sesungguhnya kami merasa nahas dan malang dengan sebab kamu. Demi sesungguhnya, kalau kamu tidak berhenti (dari menjalankan tugas yang kamu katakan itu), tentulah kami akan merejam kamu dan sudah tentu kamu akan merasai dari pihak kami azab seksa yang tidak terperi sakitnya”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 12, NULL),
(36, 19, 'قَالُوا۟ طَـٰٓئِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', 'قالوا طائركم معكم ائن ذكرتم بل انتم قوم مسرفون', NULL, 'They said, "Your omen [i.e., fate] is with yourselves. Is it because you were reminded? Rather, you are a transgressing people."', 'Rasul-rasul itu menjawab: “Nahas dan malang kamu itu adalah disebabkan (kekufuran) yang ada pada kamu. Patutkah kerana kamu diberi peringatan dan nasihat pengajaran (maka kamu mengancam kami dengan apa yang kamu katakan itu)? (Kamu bukanlah orang-orang yang mahu insaf) bahkan kamu adalah kaum pelampau”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 9, NULL),
(36, 20, 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَـٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', 'وجاء من اقصى المدينة رجل يسعى قال يا قوم اتبعوا المرسلين', NULL, 'And there came from the farthest end of the city a man, running. He said, "O my people, follow the messengers.', 'Dan (semasa Rasul-rasul itu diancam), datanglah seorang lelaki dari hujung bandar itu dengan berlari, lalu memberi nasihat dengan katanya: “Wahai kaumku! Turutlah Rasul-rasul itu -', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 10, NULL),
(36, 21, 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', 'اتَّبِعُوا مَن لَّا يَسْأَلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', NULL, 'Follow those who do not ask of you [any] payment, and they are [rightly] guided.', '“Turutlah orang-orang yang tidak meminta kapada kamu sesuatu balasan, sedang mereka adalah orang-orang mandapat hidayah petunjuk”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 22, 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', 'وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And why should I not worship He who created me and to whom you will be returned?', 'Dan (apabila ditanya: Sudahkah engkau menerima ugama mereka? Maka jawabnya): “Mengapa aku tidak menyembah Tuhan yang menciptakan daku, dan yang kepadaNyalah (aku dan) kamu semua akan dikembalikan?', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 23, 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ', 'أَأَتَّخِذُ مِن دُونِهِ آلِهَةً إِن يُرِدْنِ الرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّي شَفَاعَتُهُمْ شَيْئًا وَلَا يُنقِذُونِ', NULL, 'Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?', '“Patutkah aku menyembah beberapa tuhan yang lain dari Allah? (Sudah tentu tidak patut, kerana) jika Allah yang Maha Pemurah hendak menimpakan daku dengan sesuatu bahaya, mereka tidak dapat memberikan sebarang syafaat kepadaku, dan mereka juga tidak dapat menyelamatkan daku.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 24, 'إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ', 'إِنِّي إِذًا لَّفِي ضَلَالٍ مُّبِينٍ', NULL, 'Indeed, I would then be in manifest error.', '“Sesungguhnya aku (kalau melakukan syirik) tentulah aku pada ketika itu berada dalam kesesatan yang nyata.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 25, 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', 'إِنِّي آمَنتُ بِرَبِّكُمْ فَاسْمَعُونِ', NULL, 'Indeed, I have believed in your Lord, so listen to me."', '“Sesungguhnya aku telah beriman kepada Tuhan kamu, maka dengarlah (nasihatku)”,.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 26, 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ', 'قِيلَ ادْخُلِ الْجَنَّةَ قَالَ يَا لَيْتَ قَوْمِي يَعْلَمُونَ', NULL, 'It was said, "Enter Paradise." He said, "I wish my people could know', '(Setelah ia mati) lalu dikatakan kepadanya: “Masuklah ke dalam Syurga”. Ia berkata; “Alangkah baiknya kalau kaumku mengetahui -', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 27, 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', 'بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ', NULL, 'Of how my Lord has forgiven me and placed me among the honored."', '“Tentang perkara yang menyebabkan daku diampunkan oleh Tuhanku, serta dijadikannya daku dari orang-orang yang dimuliakan”.', FALSE, NULL, NULL, 441, 22, 176, 382, FALSE, 0, NULL),
(36, 28, 'وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', 'وَمَا أَنزَلْنَا عَلَىٰ قَوْمِهِ مِن بَعْدِهِ مِن جُندٍ مِّنَ السَّمَاءِ وَمَا كُنَّا مُنزِلِينَ', NULL, 'And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so.', 'Dan Kami tidak menurunkan kepada kaumnya sesudah ia (mati) sebarang pasukan tentera dari langit (untuk membinasakan mereka), dan tidak perlu Kami menurunkannya.', FALSE, NULL, NULL, 442, 23, 177, 382, FALSE, 0, NULL),
(36, 29, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ', 'إِن كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ', NULL, 'It was not but one shout, and immediately they were extinguished.', '(Kebinasaan mereka) hanyalah dilakukan dengan satu pekikan (yang dahsyat), maka dengan serta merta mereka semua sunyi-sepi tidak hidup lagi.', FALSE, NULL, NULL, 442, 23, 177, 382, FALSE, 0, NULL),
(36, 30, 'يَٰحَسْرَةً عَلَى ٱلْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'يَا حَسْرَةً عَلَى الْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'How regretful for the servants. There did not come to them any messenger except that they used to ridicule him.', 'Sungguh besar perasaan sesal dan kecewa yang menimpa hamba-hamba (yang mengingkari kebenaran)! Tidak datang kepada mereka seorang Rasul melainkan mereka mengejek-ejek dan memperolok-olokkannya.', FALSE, NULL, NULL, 442, 23, 177, 382, FALSE, 0, NULL),
(36, 31, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', 'أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ الْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', NULL, 'Have they not considered how many generations We destroyed before them - that they to them will not return?', 'Tidakkah mereka mengetahui berapa banyak umat-umat yang telah Kami binasakan sebelum mereka? Umat-umat yang telah binasa itu tidak kembali lagi kepada mereka (bahkan kembali kepada Kami, untuk menerima balasan).', FALSE, NULL, NULL, 442, 23, 177, 382, FALSE, 0, NULL),
(36, 32, 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', NULL, 'And indeed, all of them will yet be brought present before Us.', 'Dan tidak ada satu makhluk pun melainkan dihimpunkan ke tempat perbicaraan Kami, semuanya dibawa hadir (untuk menerima balasan).', FALSE, NULL, NULL, 442, 23, 177, 382, FALSE, 0, NULL),
(36, 33, 'وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', 'وَآيَةٌ لَّهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَاهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', NULL, 'And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat.', 'Dan dalil yang terang untuk mereka (memahami kekuasaan dan kemurahan kami), ialah bumi yang mati; kami hidupkan dia serta kami keluarkan daripadanya biji-bijian, maka daripada biji-bijian itu mereka makan.', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 34, 'وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', 'وَجَعَلْنَا فِيهَا جَنَّاتٍ مِّن نَّخِيلٍ وَأَعْنَابٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ', NULL, 'And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -', 'Dan kami jadikan di bumi itu kebun-kebun kurma dan anggur, dan kami pancarkan padanya beberapa matair,', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 35, 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ', 'لِيَأْكُلُوا مِن ثَمَرِهِ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ', NULL, 'That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?', 'Supaya mereka makan dari buah-buahannya dan dari apa yang dikerjakan oleh tangan mereka; maka patutkah mereka tidak bersyukur?', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 36, 'سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', 'سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا مِمَّا تُنبِتُ الْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', NULL, 'Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.', 'Maha Suci Tuhan yang telah menciptakan makhluk-makhluk semuanya berpasangan; sama ada dari yang ditumbuhkan oleh bumi, atau dari diri mereka, ataupun dari apa yang mereka tidak mengetahuinya.', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 37, 'وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', 'وَآيَةٌ لَّهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', NULL, 'And a sign for them is the night. We remove from it the [light of] day, so they are [left] in darkness.', 'Dan lagi dalil yang terang untuk mereka (berfikir) ialah malam; Kami hilangkan siang daripadanya, maka dengan serta-merta mereka berada dalam gelap-gelita;', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 38, 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ', NULL, 'And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.', 'Dan (sebahagian dari dalil yang tersebut ialah) matahari; ia kelihatan beredar ke tempat yang ditetapkan baginya; itu adalah takdir Tuhan yang Maha Kuasa, lagi Maha Mengetahui;', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 39, 'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', 'وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ الْقَدِيمِ', NULL, 'And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.', 'Dan bulan pula Kami takdirkan dia beredar melalui beberapa peringkat, sehingga di akhir peredarannya kelihatan kembalinya pula ke peringkat awalnya - (berbentuk melengkung) seperti tandan yang kering.', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 40, 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'لَا الشَّمْسُ يَنبَغِي لَهَا أَن تُدْرِكَ الْقَمَرَ وَلَا اللَّيْلُ سَابِقُ النَّهَارِ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ', NULL, 'It is not allowable [i.e., possible] for the sun to reach the moon, nor does the night overtake the day, but each, in an orbit, is swimming.', '(Dengan ketentuan yang demikian), matahari tidak mudah baginya mengejar bulan, dan malam pula tidak dapat mendahului siang; kerana tiap-tiap satunya beredar terapung-apung di tempat edarannya masing-masing.', FALSE, NULL, NULL, 442, 23, 177, 383, FALSE, 0, NULL),
(36, 41, 'وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'وَآيَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ', NULL, 'And a sign for them is that We carried their forefathers in a laden ship.', 'Dan satu dalil lagi untuk mereka (insaf) ialah, Kami membawa belayar jenis keluarga mereka dalam bahtera yang penuh sarat;', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 42, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِ مَا يَرْكَبُونَ', NULL, 'And We created for them from the likes of it that which they ride.', 'Dan Kami ciptakan untuk mereka, jenis-jenis kenderaan yang sama dengannya, yang mereka dapat mengenderainya.', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 43, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', NULL, 'And if We should will, We could drown them; then no one responding to a cry would there be for them, nor would they be saved', 'Dan jika kami kehendaki, kami boleh tenggelamkan mereka; (kiranya Kami lakukan yang demikian) maka tidak ada yang dapat memberi pertolongan kepada mereka, dan mereka juga tidak dapat diselamatkan, -', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 44, 'إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ', 'إِلَّا رَحْمَةً مِّنَّا وَمَتَاعًا إِلَىٰ حِينٍ', NULL, 'Except as a mercy from Us and provision for a time.', 'Kecuali dengan kemurahan dari pihak Kami memberi rahmat dan kesenangan hidup kepada mereka hingga ke suatu masa.', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 45, 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', NULL, 'But when it is said to them, "Beware of what is before you and what is behind you; perhaps you will receive mercy..."', 'Dan apabila dikatakan kepada mereka: “berjaga-jagalah kamu akan apa yang ada di hadapan kamu (dari urusan-urusan hidup di dunia ini), dan apa yang ada di belakang kamu (dari huru-hara dan balasan akhirat), supaya kamu beroleh rahmat”, (mereka tidak mengindahkannya).', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 46, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ', NULL, 'And no sign comes to them from the signs of their Lord except that they are from it turning away.', 'Dan (itulah tabiat mereka) tidak ada sesuatu keterangan yang sampai kepada mereka dari keterangan-keterangan tuhan mereka melainkan mereka selalu berpaling daripadanya (enggan menerimanya).', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 47, 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ', 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا مِمَّا رَزَقَكُمُ اللَّهُ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَنُطْعِمُ مَن لَّوْ يَشَاءُ اللَّهُ أَطْعَمَهُ إِنْ أَنتُمْ إِلَّا فِي ضَلَالٍ مُّبِينٍ', NULL, 'And when it is said to them, "Spend from that which Allāh has provided for you," those who disbelieve say to those who believe, "Should we feed one whom, if Allāh had willed, He would have fed? You are not but in clear error."', 'Dan apabila dikatakan kepada mereka: “Dermakanlah sebahagian dari rezeki yang dikurniakan Allah kepada kamu”, berkatalah orang-orang yang kafir itu kepada orang-orang yang beriman (secara mengejek-ejek): “Patutkah kami memberi makan kepada orang yang jika Allah kehendaki tentulah Ia akan memberinya makan? Kamu ini hanyalah berada dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is this promise, if you should be truthful?"', 'Dan (apabila mereka diingatkan tentang huru-hara dan balasan akhirat) mereka bertanya (secara mempersenda): “Bilakah datangnya (hari akhirat) yang dijanjikan itu? Jika betul kamu orang-orang yang benar (maka kami sedia menunggu)!”,', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 49, 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', NULL, 'They do not await except one blast which will seize them while they are disputing.', 'Mereka tidak menunggu melainkan satu pekikan yang - (dengan secara mengejut) akan membinasakan mereka semasa mereka dalam keadaan leka bertengkar (merundingkan urusan dunia masing-masing).', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 50, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَا إِلَىٰ أَهْلِهِمْ يَرْجِعُونَ', NULL, 'And they will not be able [to give] any instruction, nor to their people can they return.', 'Maka dengan itu, mereka tidak berpeluang membuat sebarang pesanan (wasiat atau lainnya), dan (kalau mereka berada di luar) mereka tidak sempat kembali kepada keluarganya.', FALSE, NULL, NULL, 443, 23, 177, 383, FALSE, 0, NULL),
(36, 51, 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', 'وَنُفِخَ فِي الصُّورِ فَإِذَا هُم مِّنَ الْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', NULL, 'And the Horn will be blown; and at once from the graves to their Lord they will hasten.', 'Dan sudah tentu akan ditiupkan sangkakala (menghidupkan orang-orang yang telah mati; apabila berlaku yang demikian) maka semuanya segera bangkit keluar dari kubur masing-masing (untuk) mengadap Tuhannya.', FALSE, NULL, NULL, 443, 23, 177, 384, FALSE, 0, NULL),
(36, 52, 'قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', 'قَالُوا يَا وَيْلَنَا مَن بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ الرَّحْمَٰنُ وَصَدَقَ الْمُرْسَلُونَ', NULL, 'They will say, "O woe to us! Who has raised us up from our sleeping place?" [The reply will be], "This is what the Most Merciful had promised, and the messengers told the truth."', '(Pada ketika itu) orang-orang yang tidak percayakan hidup semula berkata: Aduhai celakanya kami! Siapakah yang membangkitkan kami dari kubur tempat tidur kami?,, (Lalu dikatakan kepada mereka): “Inilah dia yang telah dijanjikan oleh Allah Yang Maha Pemurah dan benarlah berita yang disampaikan oleh Rasul-rasul!,', FALSE, NULL, NULL, 443, 23, 177, 384, FALSE, 0, NULL),
(36, 53, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', 'إِن كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', NULL, 'It will not be but one blast, and at once they are all brought present before Us.', 'Hanyalah dengan berlakunya satu pekikan sahaja, maka dengan serta merta mereka dihimpunkan ke tempat perbicaraan Kami, semuanya dibawa hadir (untuk menerima balasan).', FALSE, NULL, NULL, 443, 23, 177, 384, FALSE, 0, NULL),
(36, 54, 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْئًا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', NULL, 'So today [i.e., the Day of Judgement] no soul will be wronged at all, and you will not be recompensed except for what you used to do.', 'Maka pada hari itu, tidak ada seseorang yang akan dianiaya sedikitpun, dan kamu pula tidak akan dibalas melainkan menurut amal yang kamu telah kerjakan.', FALSE, NULL, NULL, 443, 23, 177, 384, FALSE, 0, NULL),
(36, 55, 'إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ', 'إِنَّ أَصْحَابَ الْجَنَّةِ الْيَوْمَ فِي شُغُلٍ فَاكِهُونَ', NULL, 'Indeed the companions of Paradise, that Day, will be amused in [joyful] occupation -', 'Sesungguhnya penduduk Syurga pada hari itu, berada dalam keadaan sibuk leka menikmati kesenangan;', FALSE, NULL, NULL, 444, 23, 177, 384, FALSE, 0, NULL),
(36, 56, 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', 'هُمْ وَأَزْوَاجُهُمْ فِي ظِلَالٍ عَلَى الْأَرَائِكِ مُتَّكِئُونَ', NULL, 'They and their spouses - in shade, reclining on adorned couches.', 'Mereka dengan pasangan-pasangan mereka bersukaria di tempat yang teduh, sambil duduk berbaring di atas pelamin;', FALSE, NULL, NULL, 444, 23, 177, 384, FALSE, 0, NULL),
(36, 57, 'لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', 'لَهُمْ فِيهَا فَاكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', NULL, 'For them therein is fruit, and for them is whatever they request [or wish]', 'Mereka beroleh dalam Syurga itu pelbagai jenis buah-buahan, dan mereka beroleh apa sahaja yang mereka kehendaki;', FALSE, NULL, NULL, 444, 23, 177, 384, FALSE, 0, NULL),
(36, 58, 'سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', 'سَلَامٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', NULL, '[And] "Peace," a word from a Merciful Lord.', '(Mereka juga beroleh) ucapan salam sejahtera dari Tuhan Yang Maha Mengasihani.', FALSE, NULL, NULL, 444, 23, 177, 384, FALSE, 0, NULL),
(36, 59, 'وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', 'وَامْتَازُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ', NULL, '[Then He will say], "But stand apart today, you criminals.', 'Dan (sebaliknya dikatakan kepada orang-orang yang kafir): “Berpisahlah kamu pada hari ini, hai orang-orang yang berdosa, (dari bercampur gaul dengan orang-orang yang beriman).', FALSE, NULL, NULL, 444, 23, 177, 384, FALSE, 0, NULL),
(36, 60, 'أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'أَلَمْ أَعْهَدْ إِلَيْكُمْ يَا بَنِي آدَمَ أَن لَّا تَعْبُدُوا الشَّيْطَانَ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ', NULL, 'Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -', '“Bukankah Aku telah perintahkan kamu wahai anak-anak Adam, supaya kamu jangan menyembah Syaitan? Sesungguhnya ia musuh yang nyata terhadap kamu!', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 61, 'وَأَنِ ٱعْبُدُونِى هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'وَأَنِ اعْبُدُونِي هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ', NULL, 'And that you worship [only] Me? This is a straight path.', '“Dan (Aku perintahkan): hendaklah kamu menyembahKu; inilah jalan yang lurus.', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 62, 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا تَعْقِلُونَ', NULL, 'And he had already led astray from among you much of creation, so did you not use reason?', '“Dan sesungguhnya Syaitan itu telah menyesatkan golongan yang ramai di antara kamu; (setelah kamu mengetahui akibat mereka) maka tidakkah sepatutnya kamu berfikir dan insaf?', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 63, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'هَٰذِهِ جَهَنَّمُ الَّتِي كُنتُمْ تُوعَدُونَ', NULL, 'This is the Hellfire which you were promised.', '“Yang kamu saksikan sekarang ialah neraka Jahannam, yang kamu selalu diancam memasukinya (kalau kamu tidak taatkan perintah Allah).', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 64, 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', 'اصْلَوْهَا الْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', NULL, '[Enter to] burn therein today for what you used to deny."', '“Rasalah kamu bakarannya pada hari ini, disebabkan perbuatan kufur yang kamu telah lakukan!”', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 65, 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'الْيَوْمَ نَخْتِمُ عَلَىٰ أَفْوَاهِهِمْ وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا يَكْسِبُونَ', NULL, 'That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn.', 'Pada waktu itu Kami meteraikan mulut mereka (sejurus); dan (memberi peluang kepada) tangan-tangan mereka memberitahu Kami (kesalahan masing-masing), dan kaki mereka pula menjadi saksi tentang apa yang mereka telah usahakan.', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 66, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', 'وَلَوْ نَشَاءُ لَطَمَسْنَا عَلَىٰ أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَأَنَّىٰ يُبْصِرُونَ', NULL, 'And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?', '(Matahati orang-orang yang menderhaka itu rosak) dan kalau Kami kehendaki, Kami berkuasa menghapuskan bentuk dan biji mata kepala mereka menjadi rata, sehingga masing-masing menerpa mencari-cari jalan (yang biasa mereka lalui). (Kiranya dijadikan demikian) maka bagaimanakah mereka dapat melihatnya?', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 67, 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ', 'وَلَوْ نَشَاءُ لَمَسَخْنَاهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ', NULL, 'And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return.', '(Kekuatan akal fikiran mereka juga tidak sihat) dan kalau kami kehendaki, kami berkuasa mangubahkan keadaan jasmani mereka (menjadi kaku beku) di tempat yang mereka berada padanya; maka dengan itu, mereka tidak dapat mara ke hadapan dan juga tidak dapat undur ke belakang.', FALSE, NULL, NULL, 444, 23, 178, 384, FALSE, 0, NULL),
(36, 68, 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ أَفَلَا يَعْقِلُونَ', 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ أَفَلَا يَعْقِلُونَ', NULL, 'And he to whom We grant long life We reverse in creation; so will they not understand?', 'Dan (hendaklah diingat bahawa) sesiapa yang Kami panjangkan umurnya, Kami balikkan kembali kejadiannya (kepada keadaan serba lemah; hakikat ini memang jelas) maka mengapa mereka tidak mahu memikirkannya?', FALSE, NULL, NULL, 444, 23, 178, 385, FALSE, 0, NULL),
(36, 69, 'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ', 'وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنبَغِي لَهُ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْآنٌ مُّبِينٌ', NULL, 'And We did not give him [i.e., Prophet Muḥammad (ﷺ)] knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur’ān', '(Nabi Muhammad bukanlah penyair) dan Kami tidak mengajarkan syair kepadanya, dan kepandaian bersyair itu pula tidak sesuai baginya. Yang Kami wahyukan kepadanya itu tidak lain melainkan nasihat pengajaran dan Kitab Suci yang memberi penerangan;', FALSE, NULL, NULL, 444, 23, 178, 385, FALSE, 0, NULL),
(36, 70, 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ', 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِينَ', NULL, 'To warn whoever is alive and justify the word [i.e., decree] against the disbelievers.', 'Supaya ia memberi peringatan kepada orang yang sedia hidup (hatinya), dan supaya nyata tetapnya hukuman (azab) terhadap orang-orang yang kufur ingkar.', FALSE, NULL, NULL, 444, 23, 178, 385, FALSE, 0, NULL),
(36, 71, 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ', 'أَوَلَمْ يَرَوْا أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا فَهُمْ لَهَا مَالِكُونَ', NULL, 'Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?', 'Tidakkah mereka melihat dan memikirkan, bahawa Kami telah menciptakan untuk mereka binatang-binatang ternak, di antara jenis-jenis makhluk yang telah Kami ciptakan dengan kekuasaan Kami lalu mereka memilikinya?', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 72, 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', 'وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', NULL, 'And We have tamed them for them, so some of them they ride, and some of them they eat.', 'Dan Kami jinakkan dia untuk kegunaan mereka; maka sebahagian di antaranya menjadi kenderaan mereka, dan sebahagian lagi mereka makan.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 73, 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ', 'وَلَهُمْ فِيهَا مَنَافِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ', NULL, 'And for them therein are [other] benefits and drinks, so will they not be grateful?', 'Dan mereka beroleh berbagai faedah dan kegunaan pada binatang ternak itu dan juga beroleh minuman; maka mengapa mereka tidak mahu bersyukur?', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 74, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ', 'وَاتَّخَذُوا مِن دُونِ اللَّهِ آلِهَةً لَّعَلَّهُمْ يُنصَرُونَ', NULL, 'But they have taken besides Allāh [false] deities that perhaps they would be helped.', 'Dan tergamak mereka menyembah beberapa tuhan yang lain dari Allah, (dengan harapan semoga mereka mendapat pertolongan (dari makhluk-makhluk itu).', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 75, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', NULL, 'They are not able to help them, and they [themselves] are for them soldiers in attendance.', 'Benda-benda yang mereka sembah itu tidak dapat sama sekali menolong mereka, sedang benda-benda itu sendiri menjadi tentera yang akan dibawa hadir (pada hari kiamat, untuk memberi azab seksa) kepada mereka.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 76, 'فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', NULL, 'So let not their speech grieve you. Indeed, We know what they conceal and what they declare.', 'Maka janganlah engkau (wahai Muhammad) berdukacita disebabkan tuduhan-tuduhan mereka (terhadapmu). Sesungguhnya Kami sedia mengetahui apa yang mereka sembunyikan dan apa yang mereka nyatakan.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 77, 'أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'أَوَلَمْ يَرَ الْإِنسَانُ أَنَّا خَلَقْنَاهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', NULL, 'Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?', 'Tidakkah manusia itu melihat dan mengetahui, bahawa Kami telah menciptakan dia dari (setitis) air benih? Dalam pada itu (setelah Kami sempurnakan kejadiannya dan tenaga kekuatannya) maka dengan tidak semena-mena menjadilah ia seorang pembantah yang terang jelas bantahannya (mengenai kekuasaan Kami menghidupkan semula orang-orang yang mati),', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 78, 'وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌ', 'وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَن يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ', NULL, 'And he presents for Us an example and forgets his [own] creation. He says, "Who will give life to bones while they are disintegrated?"', 'Serta ia mengemukakan satu misal perbandingan kepada Kami (tentang kekuasaan itu), dan ia pula lupakan keadaan Kami menciptakannya sambil ia bertanya: “Siapakah yang dapat menghidupkan tulang-tulang yang telah hancur seperti debu?”', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 79, 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', 'قُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', NULL, 'Say, "He will give them life who produced them the first time; and He is, of all creation, Knowing."', 'Katakanlah: “Tulang-tulang yang hancur itu akan dihidupkan oleh Tuhan yang telah menciptakannya pada awal mula wujudnya; dan Ia Maha Mengetahui akan segala keadaan makhluk-makhluk (yang diciptakanNya);', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 80, 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', 'الَّذِي جَعَلَ لَكُم مِّنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا أَنتُم مِّنْهُ تُوقِدُونَ', NULL, '[It is] He who made for you from the green tree, fire, and then from it you ignite.', '“Tuhan yang telah menjadikan api (boleh didapati) dari pohon-pohon yang hijau basah untuk kegunaan kamu, maka kamu pun selalu menyalakan api dari pohon-pohon itu”.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 81, 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَىٰ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ الْخَلَّاقُ الْعَلِيمُ', NULL, 'Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator.', 'Tidakkah diakui dan tidakkah dipercayai bahawa Tuhan yang telah menciptakan langit dan bumi (yang demikian besarnya) - berkuasa menciptakan semula manusia sebagaimana Ia menciptakan mereka dahulu? Ya! Diakui dan dipercayai berkuasa! Dan Dia lah Pencipta yang tidak ada bandinganNya, lagi Yang Maha Mengetahui.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 82, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', 'إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ', NULL, 'His command is only when He intends a thing that He says to it, "Be," and it is.', 'Sesungguhnya keadaan kekuasaanNya apabila Ia menghendaki adanya sesuatu, hanyalah Ia berfirman kepada (hakikat) benda itu: “Jadilah engkau!”. Maka ia terus menjadi.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(36, 83, 'فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ', 'فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'So exalted is He in whose hand is the realm of all things, and to Him you will be returned.', 'Oleh itu akuilah kesucian Allah (dengan mengucap: Subhaanallah!) - Tuhan yang memiliki dan menguasai tiap-tiap sesuatu, dan kepadaNyalah kamu semua dikembalikan.', FALSE, NULL, NULL, 445, 23, 178, 385, FALSE, 0, NULL),
(37, 1, 'وَٱلصَّـٰٓفَّـٰتِ صَفًّا', 'والصافات صفا', NULL, 'By those [angels] lined up in rows', 'Demi (hamba-hambaKu) yang berbaris dengan berderet-deret -', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 2, NULL),
(37, 2, 'فَٱلزَّٰجِرَٰتِ زَجْرًا', 'فالزاجرات زجرا', NULL, 'And those who drive [the clouds]', '(Hamba-hambaKu) yang melarang (dari kejahatan) dengan sesungguh-sungguhnya -', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 2, NULL),
(37, 3, 'فَٱلتَّـٰلِيَـٰتِ ذِكْرًا', 'فالتاليات ذكرا', NULL, 'And those who recite the message,', '(Hamba-hambaKu) yang membaca kandungan Kitab Suci;', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 2, NULL),
(37, 4, 'إِنَّ إِلَـٰهَكُمْ لَوَٰحِدٌ', 'ان الهكم لواحد', NULL, 'Indeed, your God is One,', '(Sumpah demi sumpah) sesungguhnya Tuhan kamu hanyalah Satu -', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 3, NULL),
(37, 5, 'رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَـٰرِقِ', 'رب السماوات والارض وما بينهما ورب المشارق', NULL, 'Lord of the heavens and the earth and that between them and Lord of the sunrises.', 'Tuhan (yang mencipta serta mentadbirkan) langit dan bumi dan segala yang ada di antara keduanya, dan Tuhan (yang mengatur) tempat-tempat terbit matahari.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 7, NULL),
(37, 6, 'إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ', 'انا زينا السماء الدنيا بزينة الكواكب', NULL, 'Indeed, We have adorned the nearest heaven with an adornment of stars', 'Sesungguhnya Kami telah menghiasi langit yang dekat (pada penglihatan penduduk bumi) dengan hiasan bintang-bintang.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 6, NULL),
(37, 7, 'وَحِفْظًا مِّن كُلِّ شَيْطَـٰنٍ مَّارِدٍ', 'وحفظا من كل شيطان مارد', NULL, 'And as protection against every rebellious devil', 'Dan (Kami pelihara urusan langit itu) dengan serapi-rapi kawalan dari (masuk campur) tiap-tiap Syaitan yang derhaka;', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 5, NULL),
(37, 8, 'لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ', 'لا يسمعون الى الملا الاعلى ويقذفون من كل جانب', NULL, '[So] they may not listen to the exalted assembly [of angels] and are pelted from every side,', '(Dengan itu) mereka tidak dapat memasang telinga mendengar (percakapan malaikat) penduduk langit, dan mereka pula direjam (dengan api) dari segala arah dan penjuru,', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 9, NULL),
(37, 9, 'دُحُورًا ۖ وَلَهُمْ عَذَابٌ وَاصِبٌ', 'دحورا ولهم عذاب واصب', NULL, 'Repelled; and for them is a constant punishment,', 'Untuk mengusir mereka; dan mereka pula beroleh azab seksa yang tidak putus-putus.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 4, NULL),
(37, 10, 'إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ', 'الا من خطف الخطفة فاتبعه شهاب ثاقب', NULL, 'Except one who snatches [some words] by theft, but they are pursued by a burning flame, piercing [in brightness].', 'Kecuali sesiapa di antara Syaitan-syaitan itu yang curi mendengar mana-mana percakapan (malaikat), maka ia diburu dan diikuti (dengan rejaman) api yang menjulang lagi menembusi.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 7, NULL),
(37, 11, 'فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ ۚ إِنَّا خَلَقْنَـٰهُم مِّن طِينٍ لَّازِبٍۭ', 'فاستفتهم اهم اشد خلقا ام من خلقنا انا خلقناهم من طين لازب', NULL, 'Then inquire of them, [O Muḥammad], "Are they a stronger [or more difficult] creation or those [others] We have created?" Indeed, We created them [i.e., men] from sticky clay.', '(Setelah nyata kekuasaan Kami) maka bertanyalah (wahai Muhammad) kepada mereka (yang ingkarkan hidupnya semula orang-orang mati): Adakah diri mereka lebih sukar hendak diciptakan, atau makhluk-makhluk lain yang Kami telah ciptakan? Sesungguhnya Kami telah mencipta mereka dari tanah liat (yang senang diubah dan diciptakan semula).', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 12, NULL),
(37, 12, 'بَلْ عَجِبْتَ وَيَسْخَرُونَ', 'بل عجبت ويسخرون', NULL, 'But you wonder, while they mock,', '(Pertanyaan itu tidak juga berfaedah kepada mereka) bahkan engkau merasa hairan (terhadap keingkaran mereka), dan sebaliknya mereka mengejek-ejek (peneranganmu).', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 3, NULL),
(37, 13, 'وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ', 'واذا ذكروا لا يذكرون', NULL, 'And when they are reminded, they remember not.', 'Dan apabila diperingatkan, mereka tetap tidak mahu menerima peringatan itu.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 4, NULL),
(37, 14, 'وَإِذَا رَأَوْا۟ ءَايَةً يَسْتَسْخِرُونَ', 'واذا راوا اية يستسخرون', NULL, 'And when they see a sign, they ridicule.', 'Dan apabila mereka melihat sesuatu tanda (yang membuktikan kekuasaan Kami dan kebenaranmu), mereka mencari-cari jalan memperolok-olokkannya, -', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 4, NULL),
(37, 15, 'وَقَالُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'وقالوا ان هذا الا سحر مبين', NULL, 'And say, "This is not but obvious magic.', 'Serta mereka berkata: “Ini tidak lain hanyalah sihir yang nyata.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 6, NULL),
(37, 16, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'ااذا متنا وكنا ترابا وعظاما اانا لمبعوثون', NULL, 'When we have died and become dust and bones, are we indeed to be resurrected?', '“Adakah sesudah kita mati serta menjadi tanah dan tulang, adakah kita akan dibangkitkan hidup semula?', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 7, NULL),
(37, 17, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'اواباؤنا الاولون', NULL, 'And our forefathers [as well]?"', '“Dan adakah juga datuk nenek kita yang telah lalu (akan dibangkitkan hidup semula)?”', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 2, NULL),
(37, 18, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ', 'قل نعم وانتم داخرون', NULL, 'Say, "Yes, and you will be [rendered] contemptible."', 'Jawablah (wahai Muhammad): “Ya, benar! (Kamu semua akan dibangkitkan) dengan keadaan hina-dina”.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 4, NULL),
(37, 19, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ', 'فانما هي زجرة واحدة فاذا هم ينظرون', NULL, 'It will be only one shout, and at once they will be observing.', '(Kebangkitan ini mudah) kerana sesungguhnya ia boleh berlaku hanyalah dengan suara sahaja, maka dengan serta mereka semuanya (bangkit) melihat (apa yang akan jadi).', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 7, NULL),
(37, 20, 'وَقَالُوا۟ يَـٰوَيْلَنَا هَـٰذَا يَوْمُ ٱلدِّينِ', 'وقالوا يا ويلنا هذا يوم الدين', NULL, 'They will say, "O woe to us! This is the Day of Recompense."', 'Dan (pada saat itu) mereka berkata: “Wahai celakanya kami, ini ialah hari balasan!”', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 5, NULL),
(37, 21, 'هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'هَٰذَا يَوْمُ الْفَصْلِ الَّذِي كُنتُم بِهِ تُكَذِّبُونَ', NULL, '[They will be told], "This is the Day of Judgement which you used to deny."', '(Lalu malaikat berkata kepada mereka): “Ini ialah hari memutuskan hukum untuk memberi balasan yang dahulu kamu mendustakannya”.', FALSE, NULL, NULL, 446, 23, 178, 386, FALSE, 0, NULL),
(37, 22, 'ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ', 'احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَاجَهُمْ وَمَا كَانُوا يَعْبُدُونَ', NULL, '[The angels will be ordered], "Gather those who committed wrong, their kinds, and what they used to worship', '(Allah berfirman kepada malaikat): “Himpunkanlah orang-orang yang zalim itu, dan orang-orang yang berkeadaan seperti mereka, serta benda-benda yang mereka sembah -', FALSE, NULL, NULL, 446, 23, 179, 387, FALSE, 0, NULL),
(37, 23, 'مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ', 'مِن دُونِ اللَّهِ فَاهْدُوهُمْ إِلَىٰ صِرَاطِ الْجَحِيمِ', NULL, 'Other than Allāh, and guide them to the path of Hellfire', '“Yang lain dari Allah serta hadapkanlah mereka ke jalan yang membawa ke neraka.', FALSE, NULL, NULL, 446, 23, 179, 387, FALSE, 0, NULL),
(37, 24, 'وَقِفُوهُمْ إِنَّهُم مَّسْـُٔولُونَ', 'وَقِفُوهُمْ إِنَّهُم مَّسْئُولُونَ', NULL, 'And stop them; indeed, they are to be questioned."', '“Dan hentikanlah mereka (menunggu), kerana sesungguhnya mereka akan disoal:', FALSE, NULL, NULL, 446, 23, 179, 387, FALSE, 0, NULL),
(37, 25, 'مَا لَكُمْ لَا تَنَاصَرُونَ', 'مَا لَكُمْ لَا تَنَاصَرُونَ', NULL, '[They will be asked], "What is [wrong] with you? Why do you not help each other?"', '“Mengapa kamu tidak bertolong-tolongan (sebagaimana yang kamu dakwakan dahulu?”', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 26, 'بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ', 'بَلْ هُمُ الْيَوْمَ مُسْتَسْلِمُونَ', NULL, 'But they, that Day, are in surrender.', '(Mereka pada ketika itu tidak dapat berbuat apa-apa) bahkan mereka pada hari itu menyerah diri dengan hina (untuk diadili);', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 27, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَاءَلُونَ', NULL, 'And they will approach one another asking [i.e., blaming] each other.', 'Dan masing-masing pun mengadap satu sama lain, sambil kata mengata dan cela mencela.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 28, 'قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ', 'قَالُوا إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ الْيَمِينِ', NULL, 'They will say, "Indeed, you used to come at us from the right."', 'Pengikut-pengikut berkata (kepada ketuanya): “Sesungguhnya kamu dahulu selalu datang menyekat kami (daripada beriman) dengan menggunakan kuasa kamu”.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 29, 'قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ', 'قَالُوا بَل لَّمْ تَكُونُوا مُؤْمِنِينَ', NULL, 'They [i.e., the oppressors] will say, "Rather, you [yourselves] were not believers,', 'Ketua-ketuanya menjawab: “(Tidak!) Bahkan kamulah sendiri tidak mahu menjadi orang-orang yang beriman!', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 30, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ بَلْ كُنتُمْ قَوْمًا طَٰغِينَ', 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَانٍ بَلْ كُنتُمْ قَوْمًا طَاغِينَ', NULL, 'And we had over you no authority, but you were a transgressing people.', '“Dan kami (selain daripada mengajak kamu (tidak mempunyai sebarang kuasa memerintah kamu, bahkan kamu sememangnya kaum yang melampaui batas.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 31, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ إِنَّا لَذَآئِقُونَ', 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَا إِنَّا لَذَائِقُونَ', NULL, 'So the word [i.e., decree] of our Lord has come into effect upon us; indeed, we will taste [punishment].', '(Dengan keadaan diri kita yang sedemikian) maka tetaplah di atas kita janji seksa (yang dijanjikan) oleh Tuhan kita, bahawa kita semua tentu akan merasai (azab itu).', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 32, 'فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ', 'فَأَغْوَيْنَاكُمْ إِنَّا كُنَّا غَاوِينَ', NULL, 'And we led you to deviation; indeed, we were deviators."', '“(Dengan sebab ketentuan yang tersebut) maka kami pun mengajak kamu menjadi sesat, kerana sebenarnya kami adalah orang-orang sesat”', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 33, 'فَإِنَّهُمْ يَوْمَئِذٍ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'فَإِنَّهُمْ يَوْمَئِذٍ فِي الْعَذَابِ مُشْتَرِكُونَ', NULL, 'So indeed they, that Day, will be sharing in the punishment.', 'Maka sesungguhnya mereka semua pada hari itu, menderita azab bersama.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 34, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ', NULL, 'Indeed, that is how We deal with the criminals.', 'Sesungguhnya demikianlah Kami melakukan kepada orang-orang yang berdosa.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 35, 'إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ', 'إِنَّهُمْ كَانُوا إِذَا قِيلَ لَهُمْ لَا إِلَٰهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ', NULL, 'Indeed they, when it was said to them, "There is no deity but Allāh," were arrogant', 'Sebenarnya mereka dahulu apabila dikatakan kepadanya;” (ketahuilah, bahawa) tiada Tuhan yang sebenar-benarnya melainkan Allah” - mereka bersikap takbur mengingkarinya, -', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 36, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍ مَّجْنُونٍۭ', 'وَيَقُولُونَ أَئِنَّا لَتَارِكُو آلِهَتِنَا لِشَاعِرٍ مَّجْنُونٍ', NULL, 'And were saying, "Are we to leave our gods for a mad poet?"', 'Serta mereka berkata: “Patutkah kami mesti meninggalkan tuhan-tuhan yang kami sembah, kerana mendengar ajakan seorang penyair gila?”', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 37, 'بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ', 'بَلْ جَاءَ بِالْحَقِّ وَصَدَّقَ الْمُرْسَلِينَ', NULL, 'Rather, he [i.e., the Prophet (ﷺ)] has come with the truth and confirmed the [previous] messengers.', '(Tidak! Nabi Muhammad bukan penyair dan bukan pula seorang gila) bahkan ia telah membawa kebenaran (tauhid), dan mengesahkan kebenaran (tauhid) yang dibawa oleh Rasul-rasul (yang terdahulu daripadanya).', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 38, 'إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ', 'إِنَّكُمْ لَذَائِقُو الْعَذَابِ الْأَلِيمِ', NULL, 'Indeed, you [disbelievers] will be tasters of the painful punishment,', 'Sesungguhnya kamu (wahai orang-orang musyrik) akan merasai azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 39, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', NULL, 'And you will not be recompensed except for what you used to do -', 'Dan kamu tidak dibalas melainkan (dengan balasan yang sepadan) dengan apa yang kamu telah kerjakan;', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 40, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ', NULL, 'But not the chosen servants of Allāh.', 'Kecuali hamba-hamba Allah yang dibersihkan dari sebarang syirik,', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 41, 'أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ', 'أُولَٰئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ', NULL, 'Those will have a provision determined -', 'Mereka itu beroleh limpah kurnia yang termaklum,', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 42, 'فَوَٰكِهُ وَهُم مُّكْرَمُونَ', 'فَوَاكِهُ وَهُم مُّكْرَمُونَ', NULL, 'Fruits; and they will be honored', 'Iaitu buah-buahan (yang lazat), serta mereka mendapat penghormatan,', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 43, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 'فِي جَنَّاتِ النَّعِيمِ', NULL, 'In gardens of pleasure', 'Di dalam syurga-syurga yang penuh melimpah dengan berjenis-jenis nikmat.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 44, 'عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'عَلَىٰ سُرُرٍ مُّتَقَابِلِينَ', NULL, 'On thrones facing one another.', 'Mereka duduk berhadap-hadapan di atas pelamin-pelamin kebesaran;', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 45, 'يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍۭ', 'يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍ', NULL, 'There will be circulated among them a cup [of wine] from a flowing spring,', 'Diedarkan kepada mereka piala yang berisi arak (yang diambil) dari sungainya yang mengalir,', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 46, 'بَيْضَآءَ لَذَّةٍ لِّلشَّٰرِبِينَ', 'بَيْضَاءَ لَذَّةٍ لِّلشَّارِبِينَ', NULL, 'White and delicious to the drinkers;', 'Minuman itu putih bersih, lagi lazat rasanya, bagi orang-orang yang meminumnya,', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 47, 'لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ', 'لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ', NULL, 'No bad effect is there in it, nor from it will they be intoxicated.', 'Ia tidak mengandungi sesuatu yang membahayakan, dan tidak pula mereka mabuk kerana menikmatinya.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 48, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌ', 'وَعِندَهُمْ قَاصِرَاتُ الطَّرْفِ عِينٌ', NULL, 'And with them will be women limiting [their] glances, with large, [beautiful] eyes,', 'Sedang di sisi mereka ada pula bidadari-bidadari yang tidak menumpukan pandangannya melainkan kepada mereka, lagi yang amat indah luas matanya;', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 49, 'كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ', 'كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ', NULL, 'As if they were [delicate] eggs, well-protected.', '(Putih kekuning-kuningan) seolah-olah mereka telur (burung kasuari) yang tersimpan dengan sebaik-baiknya.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 50, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَاءَلُونَ', NULL, 'And they will approach one another, inquiring of each other.', '(Tinggallah penduduk Syurga itu menikmati kesenangan), lalu setengahnya mengadap yang lain, sambil berbincang dan bertanya-tanyaan.', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 51, 'قَالَ قَآئِلٌ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌ', 'قَالَ قَائِلٌ مِّنْهُمْ إِنِّي كَانَ لِي قَرِينٌ', NULL, 'A speaker among them will say, "Indeed, I had a companion [on earth].', 'Seorang di antaranya berkata: “Sesungguhnya aku (di dunia) dahulu, ada seorang rakan (yang menempelak daku).', FALSE, NULL, NULL, 447, 23, 179, 387, FALSE, 0, NULL),
(37, 52, 'يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ', 'يَقُولُ أَإِنَّكَ لَمِنَ الْمُصَدِّقِينَ', NULL, 'Who would say, ''Are you indeed of those who believe', '“katanya: ‘Adakah engkau juga salah seorang dari golongan yang mengakui benarnya (kebangkitan orang-orang mati pada hari akhirat)?', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 53, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ', 'أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَدِينُونَ', NULL, 'That when we have died and become dust and bones, we will indeed be recompensed?''"', '“Adakah sesudah kita mati dan menjadi tanah dan tulang, adakah kita akan (dihidupkan semula serta) dibalas apa yang telah kita lakukan?”’', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 54, 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', NULL, 'He will say, "Would you [care to] look?"', '(Setelah menceritakan perihal rakannya itu) ia berkata lagi: “Adakah kamu hendak melihat (keadaan rakanku yang ingkar itu)?”', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 55, 'فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ', 'فَاطَّلَعَ فَرَآهُ فِي سَوَاءِ الْجَحِيمِ', NULL, 'And he will look and see him in the midst of the Hellfire.', 'Maka ia pun memandang (ke arah neraka), lalu dilihatnya rakannya itu berada ditengah-tengah neraka yang menjulang-julang.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 56, 'قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ', 'قَالَ تَاللَّهِ إِن كِدتَّ لَتُرْدِينِ', NULL, 'He will say, "By Allāh, you almost ruined me.', 'Ia pun (menempelaknya dengan) berkata: “Demi Allah! Nyaris-nyaris engkau menceburkan daku dalam kebinasaan.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 57, 'وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ', 'وَلَوْلَا نِعْمَةُ رَبِّي لَكُنتُ مِنَ الْمُحْضَرِينَ', NULL, 'If not for the favor of my Lord, I would have been of those brought in [to Hell].', '“Dan kalaulah tidak disebabkan nikmat pemberian Tuhanku (dengan hidayah petunjuk), nescaya akan menjadilah daku dari orang-orang yang dibawa hadir (untuk menerima balasan azab)”.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 58, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', 'أَفَمَا نَحْنُ بِمَيِّتِينَ', NULL, 'Then, are we not to die', '(Kemudian ia berkata kepada rakan-rakanya yang sedang menikmati kesenangan di Syurga bersama): “Bukankah kita (setelah mendapat nikmat-nikmat ini) tidak akan mati lagi, -', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 59, 'إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', 'إِلَّا مَوْتَتَنَا الْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', NULL, 'Except for our first death, and we will not be punished?"', '“Selain dari kematian kita yang dahulu, dan kita juga tidak akan terkena seksa?”', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 60, 'إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'إِنَّ هَٰذَا لَهُوَ الْفَوْزُ الْعَظِيمُ', NULL, 'Indeed, this is the great attainment.', 'Sesungguhnya (nikmat-nikmat kesenangan Syurga) yang demikian, ialah sebenar-benar pendapatan dan kemenangan yang besar.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 61, 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ', 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ الْعَامِلُونَ', NULL, 'For the like of this let the workers [on earth] work.', 'Untuk memperoleh (kejayaan) yang seperti inilah hendaknya orang-orang yang beramal melakukan amal usahanya dengan bersungguh-sungguh (di dunia).', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 62, 'أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ', 'أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ الزَّقُّومِ', NULL, 'Is that [i.e., Paradise] a better accommodation or the tree of zaqqūm?', 'Manakah yang lebih baik, limpah kurniaan yang termaklum itu atau pokok zaqqum?', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 63, 'إِنَّا جَعَلْنَٰهَا فِتْنَةً لِّلظَّٰلِمِينَ', 'إِنَّا جَعَلْنَاهَا فِتْنَةً لِّلظَّالِمِينَ', NULL, 'Indeed, We have made it a torment for the wrongdoers.', 'Sesungguhnya Kami jadikan pokok zaqqum itu satu ujian bagi orang-orang yang zalim (di dunia dan azab seksa bagi mereka di akhirat).', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 64, 'إِنَّهَا شَجَرَةٌ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ', 'إِنَّهَا شَجَرَةٌ تَخْرُجُ فِي أَصْلِ الْجَحِيمِ', NULL, 'Indeed, it is a tree issuing from the bottom of the Hellfire,', 'Sebenarnya ia sebatang pohon yang tumbuh di dasar neraka yang marak menjulang;', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 65, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ', 'طَلْعُهَا كَأَنَّهُ رُءُوسُ الشَّيَاطِينِ', NULL, 'Its emerging fruit as if it was heads of the devils.', 'Buahnya seolah-olah kepala Syaitan-syaitan;', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 66, 'فَإِنَّهُمْ لَـَٔاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'فَإِنَّهُمْ لَآكِلُونَ مِنْهَا فَمَالِئُونَ مِنْهَا الْبُطُونَ', NULL, 'And indeed, they will eat from it and fill with it their bellies.', 'Maka sudah tentu mereka akan makan dari buahnya (sekalipun pahit dan busuk), sehingga mereka memenuhi perut darinya.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 67, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ', 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ', NULL, 'Then indeed, they will have after it a mixture of scalding water.', 'Kemudian, sesungguhnya mereka akan beroleh lagi - selain itu- satu minuman campuran dari air panas yang menggelegak.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 68, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ', 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى الْجَحِيمِ', NULL, 'Then indeed, their return will be to the Hellfire.', 'Setelah (mereka dibawa minum) maka tempat kembali mereka tetaplah ke dalam neraka yang menjulang-julang.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 69, 'إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ', 'إِنَّهُمْ أَلْفَوْا آبَاءَهُمْ ضَالِّينَ', NULL, 'Indeed they found their fathers astray.', 'Sebenarnya mereka telah mendapati datuk nenek mereka berada dalam kesesatan;', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 70, 'فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ', 'فَهُمْ عَلَىٰ آثَارِهِمْ يُهْرَعُونَ', NULL, 'So they hastened [to follow] in their footsteps.', 'Lalu mereka terburu-buru menurut jejak langkah datuk neneknya.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 71, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ', 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ الْأَوَّلِينَ', NULL, 'And there had already strayed before them most of the former peoples,', 'Dan demi sesungguhnya, telah sesat juga - sebelum kaummu (wahai Muhammad) - kebanyakan kaum-kaum yang telah lalu.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 72, 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', NULL, 'And We had already sent among them warners.', 'Pada hal, demi sesungguhnya, Kami telahpun mengutus dalam kalangan kaum-kaum itu, Rasul-rasul pemberi amaran.', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 73, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُنذَرِينَ', NULL, 'Then look how was the end of those who were warned -', 'Maka lihatlah bagaimana kesudahan orang-orang (yang mendustakan Rasul-rasul Kami) setelah diberi amaran, -', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 74, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ', NULL, 'But not the chosen servants of Allāh.', 'Kecuali hamba-hamba Allah yang dibersihkan dari sebarang syirik (maka mereka akan terselamat dan mendapat sebaik-baik balasan).', FALSE, NULL, NULL, 448, 23, 179, 387, FALSE, 0, NULL),
(37, 75, 'وَلَقَدْ نَادَىٰنَا نُوحٌ فَلَنِعْمَ ٱلْمُجِيبُونَ', 'وَلَقَدْ نَادَانَا نُوحٌ فَلَنِعْمَ الْمُجِيبُونَ', NULL, 'And Noah had certainly called Us, and [We are] the best of responders.', 'Dan demi sesungguhnya, Nabi Nuh telah berdoa merayu kepada Kami (memohon pertolongan), maka Kami adalah sebaik-baik yang kabulkan doa permohonan.', FALSE, NULL, NULL, 448, 23, 179, 388, FALSE, 0, NULL),
(37, 76, 'وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'وَنَجَّيْنَاهُ وَأَهْلَهُ مِنَ الْكَرْبِ الْعَظِيمِ', NULL, 'And We saved him and his family from the great affliction.', 'Dan Kami telah selamatkan dia bersama-sama dengan keluarga dan pengikut-pengikutnya, dari kesusahan yang besar.', FALSE, NULL, NULL, 448, 23, 179, 388, FALSE, 0, NULL),
(37, 77, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ', 'وَجَعَلْنَا ذُرِّيَّتَهُ هُمُ الْبَاقِينَ', NULL, 'And We made his descendants those remaining [on the earth]', 'Dan Kami jadikan zuriat keturunannya sahaja orang-orang yang tinggal hidup (setelah Kami binasakan kaumnya yang ingkar).', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 78, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', 'وَتَرَكْنَا عَلَيْهِ فِي الْآخِرِينَ', NULL, 'And left for him [favorable mention] among later generations:', 'Dan Kami kekalkan baginya (nama yang harum) dalam kalangan orang-orang yang datang kemudian:', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 79, 'سَلَٰمٌ عَلَىٰ نُوحٍ فِى ٱلْعَٰلَمِينَ', 'سَلَامٌ عَلَىٰ نُوحٍ فِي الْعَالَمِينَ', NULL, '"Peace upon Noah among the worlds."', '“Salam sejahtera kepada Nabi Nuh dalam kalangan penduduk seluruh alam!”', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 80, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'Indeed, We thus reward the doers of good.', 'Demikianlah sebenarnya Kami membalas orang-orang yang berusaha mengerjakan amal-amal yang baik.', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 81, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ', NULL, 'Indeed, he was of Our believing servants.', 'Sesungguhnya Nabi Nuh itu dari hamba-hamba Kami yang beriman.', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 82, 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', 'ثُمَّ أَغْرَقْنَا الْآخَرِينَ', NULL, 'Then We drowned the others [i.e., disbelievers].', 'Kemudian Kami tenggelamkan golongan yang lain (yang mendustakannya).', FALSE, NULL, NULL, 449, 23, 179, 388, FALSE, 0, NULL),
(37, 83, 'وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', 'وَإِنَّ مِن شِيعَتِهِ لَإِبْرَاهِيمَ', NULL, 'And indeed, among his kind was Abraham,', 'Dan sesungguhnya di antara orang-orang yang menegakkan (ajaran yang dibawa oleh) Nabi Nuh ialah Nabi Ibrahim.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 84, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍ سَلِيمٍ', 'إِذْ جَاءَ رَبَّهُ بِقَلْبٍ سَلِيمٍ', NULL, 'When he came to his Lord with a sound heart', 'Ketika ia mematuhi perintah tuhannya dengan hati yang suci murni.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 85, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ', 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِ مَاذَا تَعْبُدُونَ', NULL, '[And] when he said to his father and his people, "What do you worship?', 'Ketika ia berkata kepada bapanya dan kaumnya: “Apa yang kamu sembah?', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 86, 'أَئِفْكًا ءَالِهَةً دُونَ ٱللَّهِ تُرِيدُونَ', 'أَئِفْكًا آلِهَةً دُونَ اللَّهِ تُرِيدُونَ', NULL, 'Is it falsehood [as] gods other than Allāh you desire?', '“Patutkah kamu menyembah tuhan-tuhan yang lain dari Allah, kerana kamu memutar belitkan kebenaran semata-mata (bukan kerana benarnya)?', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 87, 'فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'فَمَا ظَنُّكُم بِرَبِّ الْعَالَمِينَ', NULL, 'Then what is your thought about the Lord of the worlds?"', '“Maka bagaimana fikiran kamu pula terhadap Allah Tuhan sekalian alam?”', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 88, 'فَنَظَرَ نَظْرَةً فِى ٱلنُّجُومِ', 'فَنَظَرَ نَظْرَةً فِي النُّجُومِ', NULL, 'And he cast a look at the stars', 'Kemudian ia memandang dengan satu renungan kepada bintang-bintang (yang bertaburan di langit),', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 89, 'فَقَالَ إِنِّى سَقِيمٌ', 'فَقَالَ إِنِّي سَقِيمٌ', NULL, 'And said, "Indeed, I am [about to be] ill."', 'Lalu berkata: “Sesungguhnya aku merasa sakit (tak dapat turut berhari raya sama)”.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 90, 'فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ', 'فَتَوَلَّوْا عَنْهُ مُدْبِرِينَ', NULL, 'So they turned away from him, departing.', 'Setelah (mendengar kata-katanya) itu, mereka berpaling meninggalkan dia.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 91, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', 'فَرَاغَ إِلَىٰ آلِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', NULL, 'Then he turned to their gods and said, "Do you not eat?', 'Lalu ia pergi kepada berhala-berhala mereka secara bersembunyi, serta ia bertanya (kepada berhala-berhala itu, secara mengejek-ejek): “Mengapa kamu tidak makan?', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 92, 'مَا لَكُمْ لَا تَنطِقُونَ', 'مَا لَكُمْ لَا تَنطِقُونَ', NULL, 'What is [wrong] with you that you do not speak?"', '“Mengapa kamu tidak menjawab?”', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 93, 'فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ', 'فَرَاغَ عَلَيْهِمْ ضَرْبًا بِالْيَمِينِ', NULL, 'And he turned upon them a blow with [his] right hand.', 'Lalu ia memukul berhala-berhala itu dengan tangan kanannya (sehingga pecah berketul-ketul).', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 94, 'فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ', 'فَأَقْبَلُوا إِلَيْهِ يَزِفُّونَ', NULL, 'Then they [i.e., the people] came toward him, hastening.', '(Setelah kaumnya mengetahui hal itu) maka datanglah mereka beramai-ramai kepadanya.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 95, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', NULL, 'He said, "Do you worship that which you [yourselves] carve,', '(Bagi menjawab bantahan mereka), ia berkata: “Patutkah kamu menyembah benda-benda yang kamu pahat?', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 96, 'وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', 'وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', NULL, 'While Allāh created you and that which you do?"', '“Padahal Allah yang mencipta kamu dan benda-benda yang kamu buat itu!”', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 97, 'قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًا فَأَلْقُوهُ فِى ٱلْجَحِيمِ', 'قَالُوا ابْنُوا لَهُ بُنْيَانًا فَأَلْقُوهُ فِي الْجَحِيمِ', NULL, 'They said, "Construct for him a structure [i.e., furnace] and throw him into the burning fire."', '(Setelah tak dapat berhujah lagi, ketua-ketua) mereka berkata: “Binalah untuk Ibrahim sebuah tempat (untuk membakarnya), kemudian campakkan dia ke dalam api yang menjulang-julang itu”.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 98, 'فَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ', 'فَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَسْفَلِينَ', NULL, 'And they intended for him a plan [i.e., harm], but We made them the most debased.', 'Maka mereka (dengan perbuatan membakar Nabi Ibrahim itu) hendak melakukan angkara yang menyakitinya, lalu Kami jadikan mereka orang-orang yang terkebawah (yang tidak berjaya maksudnya).', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 99, 'وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ', 'وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهْدِينِ', NULL, 'And [then] he said, "Indeed, I will go to [where I am ordered by] my Lord; He will guide me.', 'Dan Nabi Ibrahim pula berkata: “Aku hendak (meninggalkan kamu) pergi kepada Tuhanku, Ia akan memimpinku (ke jalan yang benar).', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 100, 'رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ', 'رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ', NULL, 'My Lord, grant me [a child] from among the righteous."', '“Wahai Tuhanku! Kurniakanlah kepadaku anak yang terhitung dari orang-orang yang soleh!”', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 101, 'فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍ', 'فَبَشَّرْنَاهُ بِغُلَامٍ حَلِيمٍ', NULL, 'So We gave him good tidings of a forbearing boy.', 'Lalu Kami berikan kepadanya berita yang mengembirakan, bahawa ia akan beroleh seorang anak yang penyabar.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 102, 'فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ', 'فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَا بُنَيَّ إِنِّي أَرَىٰ فِي الْمَنَامِ أَنِّي أَذْبَحُكَ فَانظُرْ مَاذَا تَرَىٰ قَالَ يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ سَتَجِدُنِي إِن شَاءَ اللَّهُ مِنَ الصَّابِرِينَ', NULL, 'And when he reached with him [the age of] exertion, he said, "O my son, indeed I have seen in a dream that I [must] sacrifice you, so see what you think." He said, "O my father, do as you are commanded. You will find me, if Allāh wills, of the steadfast."', 'Maka ketika anaknya itu sampai (ke peringkat umur yang membolehkan dia) berusaha bersama-sama dengannya, Nabi Ibrahim berkata: “Wahai anak kesayanganku! Sesungguhnya aku melihat dalam mimpi bahawa aku akan menyembelihmu; maka fikirkanlah apa pendapatmu?”. Anaknya menjawab: “Wahai ayah, jalankanlah apa yang diperintahkan kepadamu; Insya Allah, ayah akan mendapati daku dari orang-orang yang sabar”.', FALSE, NULL, NULL, 449, 23, 180, 388, FALSE, 0, NULL),
(37, 103, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', 'فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ', NULL, 'And when they had both submitted and he put him down upon his forehead,', 'Setelah keduanya berserah bulat-bulat (menjunjung perintah Allah itu), dan Nabi Ibrahim merebahkan anaknya dengan meletakkan iringan mukanya di atas tompok tanah, (Kami sifatkan Ibrahim - dengan kesungguhan azamnya itu telah menjalankan perintah Kami),', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 104, 'وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ', 'وَنَادَيْنَاهُ أَن يَا إِبْرَاهِيمُ', NULL, 'We called to him, "O Abraham,', 'Serta Kami menyerunya: “Wahai Ibrahim!', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 105, 'قَدْ صَدَّقْتَ ٱلرُّءْيَآ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'قَدْ صَدَّقْتَ الرُّؤْيَا إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'You have fulfilled the vision." Indeed, We thus reward the doers of good.', '“Engkau telah menyempurnakan maksud mimpi yang engkau lihat itu”. Demikianlah sebenarnya Kami membalas orang-orang yang berusaha mengerjakan kebaikan.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 106, 'إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ', 'إِنَّ هَٰذَا لَهُوَ الْبَلَاءُ الْمُبِينُ', NULL, 'Indeed, this was the clear trial.', 'Sesungguhnya perintah ini adalah satu ujian yang nyata;', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 107, 'وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍ', 'وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ', NULL, 'And We ransomed him with a great sacrifice,', 'Dan Kami tebus anaknya itu dengan seekor binatang sembelihan yang besar;', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 108, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', 'وَتَرَكْنَا عَلَيْهِ فِي الْآخِرِينَ', NULL, 'And We left for him [favorable mention] among later generations:', 'Dan Kami kekalkan baginya (nama yang harum) dalam kalangan orang-orang yang datang kemudian:', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 109, 'سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ', 'سَلَامٌ عَلَىٰ إِبْرَاهِيمَ', NULL, '"Peace upon Abraham."', '“Salam sejahtera kepada Nabi Ibrahim!”.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 110, 'كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'Indeed, We thus reward the doers of good.', 'Demikianlah Kami membalas orang-orang yang berusaha mengerjakan kebaikan.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 111, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ', NULL, 'Indeed, he was of Our believing servants.', 'Sesungguhnya Nabi Ibrahim itu dari hamba-hamba Kami yang beriman.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 112, 'وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', 'وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِّنَ الصَّالِحِينَ', NULL, 'And We gave him good tidings of Isaac, a prophet from among the righteous.', 'Dan Kami pula berikan kepadanya berita yang mengembirakan, bahawa ia akan beroleh (seorang anak): Ishak, yang akan menjadi Nabi, yang terhitung dari orang-orang yang soleh.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 113, 'وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِۦ مُبِينٌ', 'وَبَارَكْنَا عَلَيْهِ وَعَلَىٰ إِسْحَاقَ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِ مُبِينٌ', NULL, 'And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself [i.e., sinner].', 'Dan Kami limpahi berkat kepadanya dan kepada (anaknya): Ishak; dan di antara zuriat keturunan keduanya ada yang mengerjakan kebaikan, dan ada pula yang berlaku zalim dengan nyata, terhadap dirinya sendiri.', FALSE, NULL, NULL, 450, 23, 180, 388, FALSE, 0, NULL),
(37, 114, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَارُونَ', NULL, 'And We did certainly confer favor upon Moses and Aaron.', 'Dan demi sesungguhnya! kami telah melimpahkan nikmat pemberian kepada Nabi Musa dan Nabi Harun.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 115, 'وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'وَنَجَّيْنَاهُمَا وَقَوْمَهُمَا مِنَ الْكَرْبِ الْعَظِيمِ', NULL, 'And We saved them and their people from the great affliction,', 'Dan Kami selamatkan keduanya dan kaumnya dari kesusahan yang besar;', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 116, 'وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'وَنَصَرْنَاهُمْ فَكَانُوا هُمُ الْغَالِبِينَ', NULL, 'And We supported them so it was they who overcame.', 'Dan Kami menolong mereka sehingga menjadilah mereka orang-orang yang berjaya mengalahkan (lawannya);', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 117, 'وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ', 'وَآتَيْنَاهُمَا الْكِتَابَ الْمُسْتَبِينَ', NULL, 'And We gave them the explicit Scripture [i.e., the Torah],', 'Dan Kami berikan kepada keduanya Kitab Suci yang amat jelas keterangannya;', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 118, 'وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'وَهَدَيْنَاهُمَا الصِّرَاطَ الْمُسْتَقِيمَ', NULL, 'And We guided them on the straight path.', 'Dan Kami berikan hidayah petunjuk kepada keduanya ke jalan yang lurus.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْـَٔاخِرِينَ', 'وَتَرَكْنَا عَلَيْهِمَا فِي الْآخِرِينَ', NULL, 'And We left for them [favorable mention] among later generations:', 'Dan Kami kekalkan bagi keduanya (nama yang harum) dalam kalangan orang-orang yang datang kemudian:', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 120, 'سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'سَلَامٌ عَلَىٰ مُوسَىٰ وَهَارُونَ', NULL, '"Peace upon Moses and Aaron."', '“Salam sejahtera kepada Nabi Musa dan Nabi Harun!”', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 121, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'Indeed, We thus reward the doers of good.', 'Demikianlah sebenarnya Kami membalas orang-orang yang berusaha mengerjakan kebaikan.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 122, 'إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إِنَّهُمَا مِنْ عِبَادِنَا الْمُؤْمِنِينَ', NULL, 'Indeed, they were of Our believing servants.', 'Sesungguhnya mereka berdua adalah dari hamba-hamba Kami yang beriman.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 123, 'وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ', 'وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ', NULL, 'And indeed, Elias was from among the messengers,', 'Dan sesungguhnya Nabi Ilyas adalah dari Rasul-rasul (Kami) yang diutus.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 124, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', 'إِذْ قَالَ لِقَوْمِهِ أَلَا تَتَّقُونَ', NULL, 'When he said to his people, "Will you not fear Allāh?', '(Ingatkanlah peristiwa) ketika ia berkata kepada kaumnya: “Hendaklah kamu mematuhi suruhan Allah dan menjauhi laranganNya.', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 125, 'أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ', 'أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ', NULL, 'Do you call upon Baʿl and leave the best of creators -', '“Patutkah kamu menyembah berhala Ba''la, dan kamu meninggalkan (ibadat kepada) sebijak-bijak pencipta?', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 126, 'ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'اللَّهَ رَبَّكُمْ وَرَبَّ آبَائِكُمُ الْأَوَّلِينَ', NULL, 'Allāh, your Lord and the Lord of your first forefathers?"', '“Iaitu Allah Tuhan kamu, dan Tuhan datuk nenek kamu yang telah lalu!”', FALSE, NULL, NULL, 450, 23, 180, 389, FALSE, 0, NULL),
(37, 127, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', NULL, 'And they denied him, so indeed, they will be brought [for punishment],', 'Maka mereka mendustakannya; akibatnya mereka tetap akan dibawa hadir (untuk diseksa),', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 128, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ', NULL, 'Except the chosen servants of Allāh.', 'Kecuali hamba-hamba Allah yang dibersihkan dari sebarang syirik (maka mereka akan terselamat, dan mendapat sebaik-baik balasan).', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 129, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ', 'وَتَرَكْنَا عَلَيْهِ فِي الْآخِرِينَ', NULL, 'And We left for him [favorable mention] among later generations:', 'Dan Kami kekalkan bagi Nabi Ilyas (nama yang harum) dalam kalangan orang-orang yang datang kemudian:', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 130, 'سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ', 'سَلَامٌ عَلَىٰ إِلْ يَاسِينَ', NULL, '"Peace upon Elias."', '“Salam sejahtera kepada Nabi Ilyas!”', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 131, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'Indeed, We thus reward the doers of good.', 'Demikianlah sebenarnya Kami membalas orang-orang yang berusaha mengerjakan kebaikan.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 132, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ', NULL, 'Indeed, he was of Our believing servants.', 'Sesungguhnya Nabi Ilyas itu dari hamba-hamba Kami yang beriman.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 133, 'وَإِنَّ لُوطًا لَّمِنَ ٱلْمُرْسَلِينَ', 'وَإِنَّ لُوطًا لَّمِنَ الْمُرْسَلِينَ', NULL, 'And indeed, Lot was among the messengers.', 'Dan sesungguhnya Nabi Lut adalah dari Rasul-rasul (Kami) yang diutus.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 134, 'إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'إِذْ نَجَّيْنَاهُ وَأَهْلَهُ أَجْمَعِينَ', NULL, '[So mention] when We saved him and his family, all,', '(ingatkanlah peristiwa) ketika kami selamatkan dia dan keluarga serta pengikut-pengikutnya semuanya,', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 135, 'إِلَّا عَجُوزًا فِى ٱلْغَٰبِرِينَ', 'إِلَّا عَجُوزًا فِي الْغَابِرِينَ', NULL, 'Except an old woman [i.e., his wife] among those who remained [with the evildoers].', 'Kecuali seorang perempuan tua tertinggal dalam golongan yang dibinasakan.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 136, 'ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ', 'ثُمَّ دَمَّرْنَا الْآخَرِينَ', NULL, 'Then We destroyed the others.', 'Kemudian Kami hancurkan yang lain (dari pengikut-pengikut Nabi Lut).', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 137, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', NULL, 'And indeed, you pass by them in the morning', 'Dan sesungguhnya kamu (yang menentang Nabi Muhammad): berulang-alik (melalui bekas-bekas tempat tinggal) mereka, semasa kamu berada pada waktu pagi.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 138, 'وَبِٱلَّيْلِ أَفَلَا تَعْقِلُونَ', 'وَبِاللَّيْلِ أَفَلَا تَعْقِلُونَ', NULL, 'And at night. Then will you not use reason?', 'Dan juga pada waktu malam; maka mengapa kamu tidak mahu memikirkannya?.', FALSE, NULL, NULL, 451, 23, 180, 389, FALSE, 0, NULL),
(37, 139, 'وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ', 'وَإِنَّ يُونُسَ لَمِنَ الْمُرْسَلِينَ', NULL, 'And indeed, Jonah was among the messengers.', 'Dan sesungguhnya Nabi Yunus adalah dari Rasul-rasul (Kami) yang diutus.', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 140, 'إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'إِذْ أَبَقَ إِلَى الْفُلْكِ الْمَشْحُونِ', NULL, '[Mention] when he ran away to the laden ship.', '(Ingatkanlah peristiwa) ketika ia melarikan diri ke kapal yang penuh sarat.', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 141, 'فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ', 'فَسَاهَمَ فَكَانَ مِنَ الْمُدْحَضِينَ', NULL, 'And he drew lots and was among the losers.', '(Dengan satu keadaan yang memaksa) maka dia pun turut mengundi, lalu menjadilah ia dari orang-orang yang kalah yang digelunsurkan (ke laut).', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 142, 'فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌ', 'فَالْتَقَمَهُ الْحُوتُ وَهُوَ مُلِيمٌ', NULL, 'Then the fish swallowed him, while he was blameworthy.', 'Setelah itu ia ditelan oleh ikan besar, sedang ia berhak ditempelak.', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 143, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ', 'فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ', NULL, 'And had he not been of those who exalt Allāh,', 'Maka kalaulah ia bukan dari orang-orang yang sentiasa mengingati Allah (dengan zikir dan tasbih),', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 144, 'لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'لَلَبِثَ فِي بَطْنِهِ إِلَىٰ يَوْمِ يُبْعَثُونَ', NULL, 'He would have remained inside its belly until the Day they are resurrected.', 'Tentulah ia akan tinggal di dalam perut ikan itu hingga ke hari manusia dibangkitkan keluar dari kubur.', FALSE, NULL, NULL, 451, 23, 180, 390, FALSE, 0, NULL),
(37, 145, 'فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌ', 'فَنَبَذْنَاهُ بِالْعَرَاءِ وَهُوَ سَقِيمٌ', NULL, 'But We threw him onto the open shore while he was ill.', 'Oleh itu Kami campakkan dia keluar (dari perut ikan) ke tanah yang tandus (di tepi pantai), sedang ia berkeadaan sakit.', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 146, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ', 'وَأَنبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ', NULL, 'And We caused to grow over him a gourd vine.', 'Dan Kami tumbuhkan (untuk melindunginya) sebatang pokok yang berdaun lebar.', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 147, 'وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ', 'وَأَرْسَلْنَاهُ إِلَىٰ مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ', NULL, 'And We sent him to [his people of] a hundred thousand or more.', 'Dan (Nabi Yunus yang tersebut kisahnya itu) Kami utuskan kepada (kaumnya yang seramai) seratus ribu atau lebih.', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 148, 'فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ', 'فَآمَنُوا فَمَتَّعْنَاهُمْ إِلَىٰ حِينٍ', NULL, 'And they believed, so We gave them enjoyment [of life] for a time.', '(Setelah berlaku apa yang berlaku) maka mereka pun beriman, lalu Kami biarkan mereka menikmati kesenangan hidup hingga ke suatu masa (yang ditetapkan bagi masing-masing).', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 149, 'فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ', 'فَاسْتَفْتِهِمْ أَلِرَبِّكَ الْبَنَاتُ وَلَهُمُ الْبَنُونَ', NULL, 'So inquire of them, [O Muḥammad], "Does your Lord have daughters while they have sons?', '(Oleh sebab ada di antara kaum musyrik Arab yang mendakwa bahawa malaikat itu anak-anak perempuan Allah) maka bertanyalah (wahai Muhammad) kepada mereka itu: Adilkah mereka membahagi untuk Tuhanmu anak-anak perempuan, dan untuk mereka anak-anak lelaki?', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 150, 'أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًا وَهُمْ شَٰهِدُونَ', 'أَمْ خَلَقْنَا الْمَلَائِكَةَ إِنَاثًا وَهُمْ شَاهِدُونَ', NULL, 'Or did We create the angels as females while they were witnesses?"', 'Atau adakah mereka hadir sendiri menyaksikan Kami mencipta malaikat-malaikat itu - perempuan?', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 151, 'أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', 'أَلَا إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', NULL, 'Unquestionably, it is out of their [invented] falsehood that they say,', 'Ketahuilah! Bahawa sesungguhnya, dengan sebab terpesongnya dari kebenaran, mereka berkata:', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 152, 'وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'وَلَدَ اللَّهُ وَإِنَّهُمْ لَكَاذِبُونَ', NULL, '"Allāh has begotten," and indeed, they are liars.', '“Allah beranak”; sedang mereka, sesungguhnya adalah orang-orang yang berdusta!', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 153, 'أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ', 'أَصْطَفَى الْبَنَاتِ عَلَى الْبَنِينَ', NULL, 'Has He chosen daughters over sons?', '(Patutkah kamu mendakwa bahawa Tuhan mempunyai anak, dan anak itu pula ialah anak-anak perempuan yang kamu tidak sukai?) Adakah Tuhan memilih serta mengutamakan anak-anak perempuan dari anak-anak lelaki (sedang kedua-dua jenis itu Dia lah yang menciptakannya)?', FALSE, NULL, NULL, 451, 23, 181, 390, FALSE, 0, NULL),
(37, 154, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', NULL, 'What is [wrong] with you? How do you make judgement?', 'Apa sudah jadi kamu? Bagaimana kamu menetapkan hukum (yang terang-terang salahnya itu)?', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 155, 'أَفَلَا تَذَكَّرُونَ', 'أَفَلَا تَذَكَّرُونَ', NULL, 'Then will you not be reminded?', 'Setelah ditegur, maka tidakkah kamu mahu berusaha mengingatkan (bahawa Allah mustahil bagiNya anak-pinak)?', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 156, 'أَمْ لَكُمْ سُلْطَٰنٌ مُّبِينٌ', 'أَمْ لَكُمْ سُلْطَانٌ مُّبِينٌ', NULL, 'Or do you have a clear authority?', 'Atau adakah kamu mempunyai sebarang bukti yang nyata (menerangkan bahawa malaikat itu anak-anak perempuan Allah)?', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 157, 'فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'فَأْتُوا بِكِتَابِكُمْ إِن كُنتُمْ صَادِقِينَ', NULL, 'Then produce your scripture, if you should be truthful.', '(Kiranya ada) maka bawalah kitab kamu (yang menerangkan demikian), jika betul kamu orang-orang yang benar.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 158, 'وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًا وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', 'وَجَعَلُوا بَيْنَهُ وَبَيْنَ الْجِنَّةِ نَسَبًا وَلَقَدْ عَلِمَتِ الْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', NULL, 'And they have made [i.e., claimed] between Him and the jinn a lineage, but the jinn have already known that they [who made such claims] will be brought [to punishment].', '(Mereka telah mengatakan perkara yang mustahil) serta mengadakan pertalian kerabat di antara Allah dan malaikat, padahal demi sesungguhnya malaikat itu sedia mengetahui bahawa sebenarnya orang-orang yang melakukan demikian akan dibawa hadir (ke dalam azab pada hari akhirat).', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 159, 'سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ', NULL, 'Exalted is Allāh above what they describe,', 'Maha Suci Allah dari apa yang mereka katakan itu!', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 160, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ', NULL, 'Except the chosen servants of Allāh [who do not share in that sin].', 'Kecuali hamba-hamba Allah yang dibersihkan dari sebarang syirik, (maka mereka akan terselamat, dan akan mendapat sebaik-baik balasan).', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 161, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', NULL, 'So indeed, you [disbelievers] and whatever you worship,', 'Maka sebenarnya kamu (wahai orang-orang musyrik), dan apa yang kamu sembah itu.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 162, 'مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ', 'مَا أَنتُمْ عَلَيْهِ بِفَاتِنِينَ', NULL, 'You cannot tempt [anyone] away from Him', 'Tidak akan dapat merosakkan perhubungan seseorang dengan Tuhannya,', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 163, 'إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ', 'إِلَّا مَنْ هُوَ صَالِ الْجَحِيمِ', NULL, 'Except he who is to [enter and] burn in the Hellfire.', 'kecuali orang-orang yang telah ditetapkan bahawa dia akan dibakar di dalam neraka yang menjulang-julang.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 164, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌ مَّعْلُومٌ', 'وَمَا مِنَّا إِلَّا لَهُ مَقَامٌ مَّعْلُومٌ', NULL, '[The angels say], "There is not among us any except that he has a known position.', '(Malaikat pula menegaskan pendirian mereka dengan berkata): “Dan tiada sesiapapun dari kalangan kami melainkan ada baginya darjat kedudukan yang tertentu (dalam menyempurnakan tugasnya);', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 165, 'وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ', 'وَإِنَّا لَنَحْنُ الصَّافُّونَ', NULL, 'And indeed, we are those who line up [for prayer].', '“Dan sesungguhnya kamilah yang sentiasa berbaris (menjunjung perintah dan beribadat),', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 166, 'وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ', 'وَإِنَّا لَنَحْنُ الْمُسَبِّحُونَ', NULL, 'And indeed, we are those who exalt Allāh."', '“Dan sesungguhnya kamilah yang sentiasa bertasbih (mensucikan Allah dari sebarang sifat kekurangan)!”', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 167, 'وَإِن كَانُوا۟ لَيَقُولُونَ', 'وَإِن كَانُوا لَيَقُولُونَ', NULL, 'And indeed, they [i.e., the disbelievers] used to say,', 'Dan sebenarnya mereka (yang musyrik) itu dahulu pernah berkata:', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 168, 'لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ ٱلْأَوَّلِينَ', 'لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ الْأَوَّلِينَ', NULL, '"If we had a message from [those of] the former peoples,', '“Kalaulah ada di sisi kami Kitab Suci dari (bawaan Rasul-rasul) yang telah lalu', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 169, 'لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'لَكُنَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ', NULL, 'We would have been the chosen servants of Allāh."', '“Tentulah kami akan menjadi hamba-hamba Allah yang dibersihkan dari sebarang syirik!”', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 170, 'فَكَفَرُوا۟ بِهِۦ فَسَوْفَ يَعْلَمُونَ', 'فَكَفَرُوا بِهِ فَسَوْفَ يَعْلَمُونَ', NULL, 'But they disbelieved in it, so they are going to know.', '(Setelah Al-Quran diturunkan kepada mereka) mereka mengingkarinya; oleh itu mereka akan mengetahui kelak (akibat kekufurannya).', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 171, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ', 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا الْمُرْسَلِينَ', NULL, 'And Our word [i.e., decree] has already preceded for Our servants, the messengers,', 'Dan demi sesungguhnya! Telah ada semenjak dahulu lagi, ketetapan Kami, bagi hamba-hamba Kami yang diutus menjadi Rasul -', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 172, 'إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ', 'إِنَّهُمْ لَهُمُ الْمَنصُورُونَ', NULL, '[That] indeed, they would be those given victory', 'Bahawa sesungguhnya merekalah orang-orang yang diberikan pertolongan mencapai kemenangan', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 173, 'وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ', 'وَإِنَّ جُندَنَا لَهُمُ الْغَالِبُونَ', NULL, 'And [that] indeed, Our soldiers [i.e., the believers] will be those who overcome.', 'Dan bahawasanya tentera Kami (pengikut-pengikut Rasul), merekalah orang-orang yang mengalahkan (golongan yang menentang kebenaran).', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 174, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', NULL, 'So, [O Muḥammad], leave them for a time.', 'Oleh itu berpalinglah (wahai Muhammad) dari mereka, (jangan hiraukan celaan mereka serta bersabarlah) hingga ke suatu masa.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 175, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', NULL, 'And see [what will befall] them, for they are going to see.', 'Dan lihat (apa yang akan menimpa) mereka; tidak lama kemudian mereka akan melihat (kemenangan yang telah Kami tetapkan untukmu).', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 176, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', NULL, 'Then for Our punishment are they impatient?', 'Maka tidaklah patut mereka meminta disegerakan azab (yang telah ditetapkan oleh) Kami!', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 177, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ', 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَاءَ صَبَاحُ الْمُنذَرِينَ', NULL, 'But when it descends in their territory, then evil is the morning of those who were warned.', 'Kerana apabila azab itu turun dalam daerah dan kawasan mereka, sudah tentu buruklah hari orang-orang yang tidak mengindahkan amaran yang telah diberikan.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 178, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', NULL, 'And leave them for a time.', 'Dan berpalinglah (wahai Muhammad) dari mereka, (jangan hiraukan celaan mereka serta bersabarlah) hingga ke suatu masa.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 179, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', NULL, 'And see, for they are going to see.', 'Dan lihatlah (apa yang akan jadi); tidak lama kemudian, mereka pun akan melihat juga.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 180, 'سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', 'سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ', NULL, 'Exalted is your Lord, the Lord of might, above what they describe.', 'Akuilah kesucian Tuhanmu, - Tuhan yang mempunyai keagungan dan kekuasaan, - dari apa yang mereka katakan!', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 181, 'وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ', 'وَسَلَامٌ عَلَى الْمُرْسَلِينَ', NULL, 'And peace upon the messengers.', 'Dan (ucaplah) salam sejahtera kepada sekalian Rasul.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(37, 182, 'وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'And praise to Allāh, Lord of the worlds.', 'Serta (ingatlah bahawa) segala puji tertentu bagi Allah, Tuhan yang memelihara dan mentadbirkan seluruh alam.', FALSE, NULL, NULL, 452, 23, 181, 390, FALSE, 0, NULL),
(38, 1, 'صٓ ۚ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ', 'ص والقران ذي الذكر', NULL, 'Ṣād. By the Qur’ān containing reminder...', 'Saad; demi Al-Quran yang mempunyai kemuliaan serta mengandungi peringatan dan pengajaran.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 4, NULL),
(38, 2, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍ وَشِقَاقٍ', 'بل الذين كفروا في عزة وشقاق', NULL, 'But those who disbelieve are in pride and dissension.', '(Orang-orang yang mengingkari kerasulanmu - wahai Muhammad - tidak berdasarkan kebenaran) bahkan mereka yang kafir itu bersifat sombong angkuh dan suka menentang kebenaran.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 6, NULL),
(38, 3, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ', 'كم اهلكنا من قبلهم من قرن فنادوا ولات حين مناص', NULL, 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.', '(Tidakkah mereka menyedari) berapa banyak umat-umat (yang ingkar) yang terdahulu dari mereka, Kami binasakan? Lalu mereka meminta pertolongan, padahal saat itu bukanlah saat meminta pertolongan melepaskan diri dari azab.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 10, NULL),
(38, 4, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ ۖ وَقَالَ ٱلْكَـٰفِرُونَ هَـٰذَا سَـٰحِرٌ كَذَّابٌ', 'وعجبوا ان جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب', NULL, 'And they wonder that there has come to them a warner [i.e., Prophet Muḥammad (ﷺ)] from among themselves. And the disbelievers say, "This is a magician and a liar.', 'Dan mereka (yang mengingkari kerasulan Nabi Muhammad itu) merasa hairan, bahawa mereka didatangi oleh seorang Rasul pemberi amaran, dari kalangan mereka sendiri. Dan mereka yang kafir itu berkata: “Orang ini adalah seorang ahli sihir, lagi pendusta.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 10, NULL),
(38, 5, 'أَجَعَلَ ٱلْـَٔالِهَةَ إِلَـٰهًا وَٰحِدًا ۖ إِنَّ هَـٰذَا لَشَىْءٌ عُجَابٌ', 'اجعل الالهة الها واحدا ان هذا لشيء عجاب', NULL, 'Has he made the gods [only] one God? Indeed, this is a curious thing."', '“Patutkah ia menafikan tuhan-tuhan yang berbilang itu dengan mengatakan: Tuhan hanya Satu? Sesungguhnya ini adalah satu perkara yang menakjubkan!”', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 8, NULL),
(38, 6, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ ۖ إِنَّ هَـٰذَا لَشَىْءٌ يُرَادُ', 'وانطلق الملا منهم ان امشوا واصبروا على الهتكم ان هذا لشيء يراد', NULL, 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.', 'Dan (ketika itu) keluarlah ketua-ketua dari kalangan mereka (memberi peransang dengan berkata): “Jalan terus (menurut cara penyembahan datuk nenek kamu) dan tetap tekunlah menyembah tuhan-tuhan kamu. Sebenarnya sikap ini adalah satu perkara yang amat dikehendaki.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 12, NULL),
(38, 7, 'مَا سَمِعْنَا بِهَـٰذَا فِى ٱلْمِلَّةِ ٱلْـَٔاخِرَةِ إِنْ هَـٰذَآ إِلَّا ٱخْتِلَـٰقٌ', 'ما سمعنا بهذا في الملة الاخرة ان هذا الا اختلاق', NULL, 'We have not heard of this in the latest religion. This is not but a fabrication.', '“Kami tidak pernah mendengar tentang (soal mengesakan Tuhan) itu dalam ugama yang terakhir; perkara ini tidak lain hanyalah rekaan dan dusta semata-mata”.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 10, NULL),
(38, 8, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا ۚ بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى ۖ بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', 'اانزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب', NULL, 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.', '(Mereka berkata lagi): Patutkah wahyu peringatan itu diturunkan kepada Muhammad (padahal orang-orang yang lebih layak ada) di antara kita?” (Mereka bukan sahaja ingkarkan kelayakan Nabi Muhammad menerima wahyu) bahkan mereka berada dalam keraguan tentang peringatan yang Aku wahyukan (kepada Nabi Muhammad) itu, bahkan mereka belum lagi merasai azab.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 15, NULL),
(38, 9, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 'ام عندهم خزائن رحمة ربك العزيز الوهاب', NULL, 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?', 'Adakah di sisi mereka perbendaharaan rahmat Tuhanmu Yang Maha Kuasa, lagi Yang Maha Melimpah pemberianNya?.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 7, NULL),
(38, 10, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَـٰبِ', 'ام لهم ملك السماوات والارض وما بينهما فليرتقوا في الاسباب', NULL, 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.', 'Atau adakah mereka menguasai langit dan bumi serta segala yang ada di antara keduanya?. (Kalau ada kekuasaan yang demikian) maka biarlah mereka naik mendaki langit menurut jalan-jalan yang membawa mereka ke situ (untuk mentadbirkan seluruh alam).', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 10, NULL),
(38, 11, 'جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ', 'جند ما هنالك مهزوم من الاحزاب', NULL, '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].', '(Sebenarnya mereka hanyalah) satu pasukan tentera dari kumpulan-kumpulan (yang menentang kebenaran), yang pada suatu masa kelak tetap akan dikalahkan.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 6, NULL),
(38, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 'كذبت قبلهم قوم نوح وعاد وفرعون ذو الاوتاد', NULL, 'The people of Noah denied before them, and [the tribe of] ʿAad and Pharaoh, the owner of stakes,', 'Sebelum mereka itu, kaum Nabi Nuh, dan Aad (kaum Nabi Hud), serta Firaun yang mempunyai kerajaan yang kuat, telah juga mendustakan Rasul masing-masing.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 8, NULL),
(38, 13, 'وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَـٰبُ لْـَٔيْكَةِ ۚ أُو۟لَـٰٓئِكَ ٱلْأَحْزَابُ', 'وثمود وقوم لوط واصحاب الايكة اولئك الاحزاب', NULL, 'And [the tribe of] Thamūd and the people of Lot and the companions of the thicket [i.e., people of Madyan]. Those are the companies.', 'Dan juga Thamud (kaum Nabi Soleh), dan kaum Nabi Lut, serta penduduk Aikah; merekalah kumpulan-kumpulan (yang menentang kebenaran).', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 7, NULL),
(38, 14, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', 'ان كل الا كذب الرسل فحق عقاب', NULL, 'Each of them denied the messengers, so My penalty was justified.', 'Tidak ada satupun dari kaum-kaum yang tersebut, melainkan telah mendustakan Rasul-rasul; maka berhaklah mereka ditimpa azab.', FALSE, NULL, NULL, 453, 23, 181, 391, FALSE, 7, NULL),
(38, 15, 'وَمَا يَنظُرُ هَـٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ', 'وما ينظر هؤلاء الا صيحة واحدة ما لها من فواق', NULL, 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.', 'Dan orang-orang ini (yang menentang Nabi Muhammad), tidak menunggu melainkan satu jeritan suara yang tidak akan berulang lagi.', FALSE, NULL, NULL, 453, 23, 181, 392, FALSE, 10, NULL),
(38, 16, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', 'وقالوا ربنا عجل لنا قطنا قبل يوم الحساب', NULL, 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account."', 'Dan mereka pula berkata (secara mengejek-ejek): “Wahai Tuhan kami! Segerakanlah azab yang ditetapkan untuk kami, sebelum datangnya hari hitungan amal (yang dikatakan oleh Muhammad itu)”.', FALSE, NULL, NULL, 453, 23, 181, 392, FALSE, 8, NULL),
(38, 17, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ ۖ إِنَّهُۥٓ أَوَّابٌ', 'اصبر على ما يقولون واذكر عبدنا داوود ذا الايد انه اواب', NULL, 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allāh].', 'Bersabarlah (wahai Muhammad) terhadap apa sahaja yang mereka katakan, dan ingatlah akan hamba Kami Nabi Daud, yang mempunyai kekuatan (dalam pegangan ugamanya); sesungguhnya ia adalah sentiasa rujuk kembali (kepada Kami dengan bersabar mematuhi perintah Kami).', FALSE, NULL, NULL, 454, 23, 181, 392, FALSE, 11, NULL),
(38, 18, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', 'انا سخرنا الجبال معه يسبحن بالعشي والاشراق', NULL, 'Indeed, We subjected the mountains [to praise] with him, exalting [Allāh] in the [late] afternoon and [after] sunrise.', 'Sesungguhnya Kami telah mudahkan gunung-ganang turut bertasbih memuji Kami bersama-sama dengannya; pada waktu petang dan ketika terbit matahari.', FALSE, NULL, NULL, 454, 23, 181, 392, FALSE, 7, NULL),
(38, 19, 'وَٱلطَّيْرَ مَحْشُورَةً ۖ كُلٌّ لَّهُۥٓ أَوَّابٌ', 'والطير محشورة كل له اواب', NULL, 'And the birds were assembled, all with him repeating [praises].', 'Dan (Kami mudahkan juga) unggas turut berhimpun (untuk bertasbih memuji Kami bersama-sama dengannya); tiap-tiap satunya mengulangi tasbih masing-masing menurutnya.', FALSE, NULL, NULL, 454, 23, 181, 392, FALSE, 5, NULL),
(38, 20, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَـٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', 'وشددنا ملكه واتيناه الحكمة وفصل الخطاب', NULL, 'And We strengthened his kingdom and gave him wisdom and discernment in speech.', 'Dan Kami kuatkan kerajaannya, serta Kami kurniakan kepadanya hikmah kebijaksanaan dan kepitahan berkata-kata (dalam menjalankan hukum dan menjatuhkan hukuman).', FALSE, NULL, NULL, 454, 23, 181, 392, FALSE, 6, NULL),
(38, 21, 'وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', 'وَهَلْ أَتَاكَ نَبَأُ الْخَصْمِ إِذْ تَسَوَّرُوا الْمِحْرَابَ', NULL, 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -', 'Dan sudahkah sampai kepadamu (wahai Muhammad) berita (perbicaraan dua) orang yang berselisihan? Ketika mereka memanjat tembok tempat ibadat;', FALSE, NULL, NULL, 454, 23, 182, 392, FALSE, 0, NULL),
(38, 22, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُوا۟ لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', 'إِذْ دَخَلُوا عَلَىٰ دَاوُودَ فَفَزِعَ مِنْهُمْ قَالُوا لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَاحْكُم بَيْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ وَاهْدِنَا إِلَىٰ سَوَاءِ الصِّرَاطِ', NULL, 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.', 'Iaitu ketika mereka masuk kepada Nabi Daud, lalu ia terkejut melihat mereka; mereka berkata kepadanya: “Janganlah takut, (kami ini) adalah dua orang yang berselisihan, salah seorang dari kami telah berlaku zalim kepada yang lain; oleh itu hukumkanlah di antara kami dengan adil, dan janganlah melampaui (batas keadilan), serta pimpinlah kami ke jalan yang lurus.', FALSE, NULL, NULL, 454, 23, 182, 392, FALSE, 0, NULL),
(38, 23, 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 'إِنَّ هَٰذَا أَخِي لَهُ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِيَ نَعْجَةٌ وَاحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِي فِي الْخِطَابِ', NULL, 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, ''Entrust her to me,'' and he overpowered me in speech."', '“Sebenarnya orang ini ialah (seorang sahabat sebagai) saudaraku; ia mempunyai sembilan puluh sembilan ekor kambing betina dan aku mempunyai seekor sahaja; dalam pada itu ia (mendesakku dengan) berkata: ‘Serahkanlah yang seekor itu kepadaku’, dan dia telah mengalahkan daku dalam merundingkan perkara itu”.', FALSE, NULL, NULL, 454, 23, 182, 392, FALSE, 0, NULL),
(38, 24, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ', 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِ وَإِنَّ كَثِيرًا مِّنَ الْخُلَطَاءِ لَيَبْغِي بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ', NULL, '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allāh].', 'Nabi Daud berkata: “Sesungguhnya ia telah berlaku zalim kepadamu dengan meminta kambingmu itu (sebagai tambahan) kepada kambing-kambingnya; dan sesungguhnya kebanyakan dari orang-orang yang bergaul dan berhubungan (dalam berbagai-bagai lapangan hidup), setengahnya berlaku zalim kepada setengahnya yang lain, kecuali orang-orang yang beriman dan beramal soleh; sedang mereka amatlah sedikit!” Dan Nabi Daud (setelah berfikir sejurus), mengetahui sebenarnya Kami telah mengujinya (dengan peristiwa itu), lalu ia memohon ampun kepada Tuhannya sambil merebahkan dirinya sujud, serta ia rujuk kembali (bertaubat).', FALSE, NULL, NULL, 454, 23, 182, 392, TRUE, 0, NULL),
(38, 25, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', 'فَغَفَرْنَا لَهُ ذَٰلِكَ وَإِنَّ لَهُ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَآبٍ', NULL, 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.', 'Maka Kami ampunkan kesalahannya itu; dan sesungguhnya ia mempunyai kedudukan yang dekat di sisi Kami serta tempat kembali yang sebaik-baiknya (pada hari akhirat kelak).', FALSE, NULL, NULL, 454, 23, 182, 392, FALSE, 0, NULL),
(38, 26, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', 'يَا دَاوُودُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُم بَيْنَ النَّاسِ بِالْحَقِّ وَلَا تَتَّبِعِ الْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ اللَّهِ إِنَّ الَّذِينَ يَضِلُّونَ عَن سَبِيلِ اللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ بِمَا نَسُوا يَوْمَ الْحِسَابِ', NULL, '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allāh." Indeed, those who go astray from the way of Allāh will have a severe punishment for having forgotten the Day of Account.', 'Wahai Daud, sesungguhnya Kami telah menjadikanmu khalifah di bumi, maka jalankanlah hukum di antara manusia dengan (hukum syariat) yang benar (yang diwahyukan kepadamu); dan janganlah engkau menurut hawa nafsu, kerana yang demikian itu akan menyesatkanmu dari jalan Allah. Sesungguhnya orang-orang yang sesat dari jalan Allah, akan beroleh azab yang berat pada hari hitungan amal, disebabkan mereka melupakan (jalan Allah) itu.', FALSE, NULL, NULL, 454, 23, 182, 392, FALSE, 0, NULL),
(38, 27, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', 'وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا ذَٰلِكَ ظَنُّ الَّذِينَ كَفَرُوا فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِنَ النَّارِ', NULL, 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.', 'Dan tiadalah Kami menciptakan langit dan bumi serta segala yang ada di antara keduanya sebagai ciptaan yang tidak mengandungi hikmah dan keadilan; yang demikian adalah sangkaan orang-orang yang kafir! Maka kecelakaanlah bagi orang-orang yang kafir itu dari azab neraka.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 28, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 'أَمْ نَجْعَلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَالْمُفْسِدِينَ فِي الْأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ', NULL, 'Or should We treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allāh like the wicked?', 'Patutkah Kami jadikan orang-orang yang beriman dan beramal soleh itu sama seperti orang-orang yang melakukan kerosakan di muka bumi? Atau patutkah Kami jadikan orang-orang yang bertaqwa sama seperti orang-orang yang berdosa?', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 29, 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِّيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ', NULL, '[This is] a blessed Book which We have revealed to you, [O Muḥammad], that they might reflect upon its verses and that those of understanding would be reminded.', '(Al-Quran ini) sebuah Kitab yang Kami turunkan kepadamu (dan umatmu wahai Muhammad), -Kitab yang banyak faedah-faedah dan manfaatnya, untuk mereka memahami dengan teliti kandungan ayat-ayatnya, dan untuk orang-orang yang berakal sempurna beringat mengambil iktibar.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 30, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ نِعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'وَوَهَبْنَا لِدَاوُودَ سُلَيْمَانَ نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ', NULL, 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allāh].', 'Dan Kami telah kurniakan kepada Nabi Daud (seorang anak bernama) Sulaiman ia adalah sebaik-baik hamba (yang kuat beribadat), lagi sentiasa rujuk kembali (bertaubat).', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(38, 31, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', 'إِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ الْجِيَادُ', NULL, '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.', '(Ingatkanlah peristiwa) ketika Nabi Sulaiman ditunjukkan kepadanya pada suatu petang, satu kumpulan kuda yang terpuji keadaannya semasa berdiri, lagi yang tangkas semasa berlari.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 32, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', 'فَقَالَ إِنِّي أَحْبَبْتُ حُبَّ الْخَيْرِ عَن ذِكْرِ رَبِّي حَتَّىٰ تَوَارَتْ بِالْحِجَابِ', NULL, 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until it [i.e., the sun] disappeared into the curtain [of darkness]."', '(Kerana lekanya dengan pertunjukan itu) maka Nabi Sulaiman berkata: “Sesungguhnya aku telah mengutamakan kesukaanku kepada (kuda pembawa) kebaikan lebih daripada mengingati (ibadatku kepada) Tuhanku, sehingga (matahari) melindungi dirinya dengan tirai malam”.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 33, 'رُدُّوهَا عَلَىَّ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 'رُدُّوهَا عَلَيَّ فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ', NULL, '[He said], "Return them to me," and set about striking [their] legs and necks.', '(Kemudian Nabi Sulaiman berkata kepada orang-orangnya): “Bawa balik kuda itu kepadaku”; maka ia pun tampil menyapu betis dan leher kuda itu (seekor demi seekor).', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 34, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ', 'وَلَقَدْ فَتَنَّا سُلَيْمَانَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِ جَسَدًا ثُمَّ أَنَابَ', NULL, 'And We certainly tried Solomon and placed on his throne a body; then he returned.', 'Dan demi sesungguhnya! Kami telah menguji Nabi Sulaiman (dengan satu kejadian), dan Kami letakkan di atas takhta kebesarannya satu jasad (yang tidak cukup sifatnya) kemudian ia kembali (merayu kepada Kami): -', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 35, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'قَالَ رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَّا يَنبَغِي لِأَحَدٍ مِّن بَعْدِي إِنَّكَ أَنتَ الْوَهَّابُ', NULL, 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."', 'Katanya: “Wahai Tuhanku! Ampunkanlah kesilapanku, dan kurniakanlah kepadaku sebuah kerajaan (yang tidak ada taranya dan) yang tidak akan ada pada sesiapapun kemudian daripadaku; sesungguhnya Engkaulah yang sentiasa Melimpah kurniaNya”.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 36, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', 'فَسَخَّرْنَا لَهُ الرِّيحَ تَجْرِي بِأَمْرِهِ رُخَاءً حَيْثُ أَصَابَ', NULL, 'So We subjected to him the wind blowing by his command, gently, wherever he directed,', 'Maka (Kami kabulkan permohonannya lalu) Kami mudahkan baginya menggunakan angin yang bertiup perlahan-lahan menurut kemahuannya, ke arah mana sahaja yang hendaK ditujunya;', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 37, 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ', 'وَالشَّيَاطِينَ كُلَّ بَنَّاءٍ وَغَوَّاصٍ', NULL, 'And [also] the devils [of jinn] - every builder and diver', 'Dan (Kami mudahkan baginya memerintah) Jin Syaitan; (ia memerintah) golongan-golongan yang pandai mendirikan bangunan, dan yang menjadi penyelam (bagi menjalankan kerja masing-masing).', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 38, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'وَآخَرِينَ مُقَرَّنِينَ فِي الْأَصْفَادِ', NULL, 'And others bound together in irons.', 'Dan Jin-jin Syaitan yang lain dipasung dalam rantai-rantai belenggu.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 39, 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', 'هَٰذَا عَطَاؤُنَا فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', NULL, '[We said], "This is Our gift, so grant or withhold without account."', '(Serta Kami katakan kepadanya): “Inilah pemberian Kami (kepadamu), maka berikanlah (kepada sesiapa yang engkau suka), atau tahankanlah pemberian itu; (terserahlah kepadamu) dengan tidak ada sebarang hitungan (untuk menyalahkanmu)”.', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 40, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', 'وَإِنَّ لَهُ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَآبٍ', NULL, 'And indeed, for him is nearness to Us and a good place of return.', 'Dan sesungguhnya ia mempunyai kedudukan yang dekat lagi mulia di sisi Kami, serta tempat kembali yang sebaik-baiknya (pada hari akhirat kelak).', FALSE, NULL, NULL, 455, 23, 182, 393, FALSE, 0, NULL),
(38, 41, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ', 'وَاذْكُرْ عَبْدَنَا أَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ', NULL, 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."', 'Dan (ingatkanlah peristiwa) hamba Kami: Nabi Ayub ketika ia berdoa merayu kepada Tuhannya dengan berkata: “Sesungguhnya aku diganggu oleh Syaitan dengan (hasutannya semasa aku ditimpa) kesusahan dan azab seksa (penyakit)”.', FALSE, NULL, NULL, 455, 23, 182, 394, FALSE, 0, NULL),
(38, 42, 'ٱرْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ', 'ارْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ', NULL, '[So he was told], "Strike [the ground] with your foot; this is a [spring for a] cool bath and drink."', '(Maka Kami kabulkan permohonannya serta Kami perintahkan kepadanya): “Hentakkanlah (bumi) dengan kakimu” (setelah ia melakukannya maka terpancarlah air, lalu Kami berfirman kepadanya): “Ini ialah air sejuk untuk mandi dan untuk minum (bagi menyembuhkan penyakitmu zahir dan batin)”.', FALSE, NULL, NULL, 455, 23, 182, 394, FALSE, 0, NULL),
(38, 43, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'وَوَهَبْنَا لَهُ أَهْلَهُ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُولِي الْأَلْبَابِ', NULL, 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.', 'Dan Kami kurniakan (lagi) kepadanya - keluarganya, dengan sekali ganda ramainya, sebagai satu rahmat dari Kami dan sebagai satu peringatan bagi orang-orang yang berakal sempurna (supaya mereka juga bersikap sabar semasa ditimpa malang).', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 44, 'وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ إِنَّا وَجَدْنَٰهُ صَابِرًا نِّعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِب بِّهِ وَلَا تَحْنَثْ إِنَّا وَجَدْنَاهُ صَابِرًا نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ', NULL, '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allāh].', 'Dan (Kami perintahkan lagi kepadanya): “Ambilah dengan tanganmu seikat jerami kemudian pukulah (isterimu) dengannya; dan janganlah engkau merosakkan sumpahmu itu”. Sesungguhnya Kami mendapati Nabi Ayub itu seorang yang sabar; ia adalah sebaik-baik hamba; sesungguhnya ia sentiasa rujuk kembali (kepada Kami dengan ibadatnya).', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 45, 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 'وَاذْكُرْ عِبَادَنَا إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ أُولِي الْأَيْدِي وَالْأَبْصَارِ', NULL, 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.', 'Dan (ingatkanlah peristiwa) hamba-hamba Kami: Nabi Ibrahim dan Nabi Ishak serta Nabi Yaakub, yang mempunyai kekuatan (melaksanakan taat setianya) dan pandangan yang mendalam (memahami ugamanya).', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 46, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ', 'إِنَّا أَخْلَصْنَاهُم بِخَالِصَةٍ ذِكْرَى الدَّارِ', NULL, 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].', 'Sesungguhnya Kami telah jadikan mereka suci bersih dengan sebab satu sifat mereka yang murni, iaitu sifat sentiasa memperingati negeri akhirat.', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 47, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', 'وَإِنَّهُمْ عِندَنَا لَمِنَ الْمُصْطَفَيْنَ الْأَخْيَارِ', NULL, 'And indeed they are, to Us, among the chosen and outstanding.', 'Dan sesungguhnya mereka di sisi Kami adalah dari orang-orang pilihan yang sebaik-baiknya.', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 48, 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ', 'وَاذْكُرْ إِسْمَاعِيلَ وَالْيَسَعَ وَذَا الْكِفْلِ وَكُلٌّ مِّنَ الْأَخْيَارِ', NULL, 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.', 'Dan (ingatkanlah peristiwa) Nabi lsmail, dan Nabi Alyasak, serta Nabi Zulkifli; dan mereka masing-masing adalah dari orang-orang yang sebaik-baiknya.', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 49, 'هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ', 'هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَآبٍ', NULL, 'This is a reminder. And indeed, for the righteous is a good place of return -', '(Segala sifat-sifat yang mulia) ini, adalah menjadi sebutan penghormatan (bagi mereka). Dan sesungguhnya bagi orang-orang yang bertaqwa, disediakan tempat kembali yang sebaik-baiknya (pada hari akhirat kelak), -', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 50, 'جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ', 'جَنَّاتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ الْأَبْوَابُ', NULL, 'Gardens of perpetual residence, whose doors will be opened to them.', 'Iaitu beberapa buah Syurga tempat penginapan yang kekal, yang terbuka pintu-pintunya untuk mereka;', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 51, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', 'مُتَّكِئِينَ فِيهَا يَدْعُونَ فِيهَا بِفَاكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', NULL, 'Reclining within them, they will call therein for abundant fruit and drink.', '(Mereka akan bersukaria) dalam Syurga itu sambil berbaring (di atas pelamin); mereka meminta di situ buah-buahan dan minuman yang berbagai jenisnya dan rasa kelazatannya.', FALSE, NULL, NULL, 456, 23, 182, 394, FALSE, 0, NULL),
(38, 52, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', 'وَعِندَهُمْ قَاصِرَاتُ الطَّرْفِ أَتْرَابٌ', NULL, 'And with them will be women limiting [their] glances and of equal age.', 'Dan di sisi mereka pula bidadari-bidadari yang pandangannya tertumpu (kepada mereka semata-mata), lagi yang sebaya umurnya.', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 53, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ الْحِسَابِ', NULL, 'This is what you, [the righteous], are promised for the Day of Account.', 'Inilah dia balasan yang dijanjikan kepada kamu setelah selesai hitungan amal!', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 54, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُ مِن نَّفَادٍ', NULL, 'Indeed, this is Our provision; for it there is no depletion.', 'Sesungguhnya ini ialah pemberian Kami kepada kamu, pemberian yang tidak akan habis-habis; -', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 55, 'هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍ', 'هَٰذَا وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ', NULL, 'This [is so]. But indeed, for the transgressors is an evil place of return -', 'Nikmat-nikmat ini (adalah untuk orang-orang yang bertaqwa). Dan Bahawa sesungguhnya bagi orang-orang yang zalim (dengan kekufuran atau kederhakaannya) seburuk-buruk tempat kembali, -', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 56, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ الْمِهَادُ', NULL, 'Hell, which they will [enter to] burn, and wretched is the resting place.', 'Iaitu neraka Jahannam yang mereka akan menderita bakarannya; maka seburuk-buruk tempat menetap ialah neraka Jahannam;', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 57, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', NULL, 'This - so let them taste it - is scalding water and [foul] purulence.', 'Ini sejenis azab seksa, maka hendaklah mereka merasainya, air panas yang menggelegak dan air danur yang mengalir (untuk minuman mereka);', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 58, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', 'وَآخَرُ مِن شَكْلِهِ أَزْوَاجٌ', NULL, 'And other [punishments] of its type [in various] kinds.', 'Dan azab seksa yang lain, yang serupa buruknya dan dahsyatnya adalah berbagai jenis lagi.', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 59, 'هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًۢا بِهِمْ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', 'هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًا بِهِمْ إِنَّهُمْ صَالُو النَّارِ', NULL, '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."', '(Penjaga neraka berkata kepada ketua-ketua golongan kafir dan penderhaka itu): “Ini ialah serombongan (orang-orang kamu) yang masuk berasak-asak bersama-sama kamu”. (Ketua-ketua itu berkata): “Mereka tidak perlu dialu-alukan, kerana sesungguhnya mereka pun akan menderita bakaran neraka”.', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 60, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ ٱلْقَرَارُ', 'قَالُوا بَلْ أَنتُمْ لَا مَرْحَبًا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ الْقَرَارُ', NULL, 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."', 'pengikut-pengikut mereka menjawab: “Bahkan kamulah yang tidak perlu dialu-alukan, kerana kamulah yang membawa azab sengsara ini kepada kami, maka amatlah buruknya neraka ini sebagai tempat penetapan”.', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 61, 'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى ٱلنَّارِ', 'قَالُوا رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِي النَّارِ', NULL, 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."', 'Mereka berkata lagi: “Wahai Tuhan kami! Sesiapa yang membawa azab ini kepada kami, maka tambahilah dia azab seksa berlipat ganda di dalam neraka”.', FALSE, NULL, NULL, 456, 23, 183, 394, FALSE, 0, NULL),
(38, 62, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', 'وَقَالُوا مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ الْأَشْرَارِ', NULL, 'And they will say, "Why do we not see men whom we used to count among the worst?', 'Dan penduduk neraka itu tetap akan bertanya sesama sendiri: “Mengapa kita tidak melihat orang-orang yang dahulu kita kirakan mereka sebagai orang-orang jahat (lagi hina)?', FALSE, NULL, NULL, 457, 23, 183, 394, FALSE, 0, NULL),
(38, 63, 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', 'أَتَّخَذْنَاهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ الْأَبْصَارُ', NULL, 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"', '“Adakah kita sahaja jadikan mereka ejek-ejekan (sedang mereka orang-orang yang benar)? Atau mata kita tidak dapat melihat mereka?', FALSE, NULL, NULL, 457, 23, 183, 394, FALSE, 0, NULL),
(38, 64, 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ', 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ النَّارِ', NULL, 'Indeed, that is truth [i.e., reality] - the quarreling of the people of the Fire.', 'Sesungguhnya (segala yang diterangkan) itu adalah benar iaitu perbalahan dan cercaan penduduk neraka sesama sendiri.', FALSE, NULL, NULL, 457, 23, 183, 394, FALSE, 0, NULL),
(38, 65, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'قُلْ إِنَّمَا أَنَا مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ', NULL, 'Say, [O Muḥammad], "I am only a warner, and there is not any deity except Allāh, the One, the Prevailing,', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku hanyalah seorang Rasul pemberi amaran, dan tidak ada sama sekali tuhan yang sebenar melainkan Allah Yang Maha Esa, lagi Yang kekuasaanNya mengatasi segala-galanya, -', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 66, 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ', NULL, 'Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver."', '“Tuhan (yang mencipta serta mentadbirkan) langit dan bumi dan segala yang ada di antara keduanya; Yang Maha Kuasa, lagi Yang sentiasa Mengampuni (dosa hamba-hambaNya)”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 67, 'قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ', 'قُلْ هُوَ نَبَأٌ عَظِيمٌ', NULL, 'Say, "It is great news', 'Katakanlah lagi: “Apa yang aku terangkan itu (tentang keesaan Allah dan kebenaran kerasulanku) adalah berita penting yang amat besar (faedahnya).', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 68, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', 'أَنتُمْ عَنْهُ مُعْرِضُونَ', NULL, 'From which you turn away.', '“Yang kamu terus mengingkarinya.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 69, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 'مَا كَانَ لِيَ مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَىٰ إِذْ يَخْتَصِمُونَ', NULL, 'I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam].', '“Tiadalah bagiku sebarang pengetahuan tentang penduduk alam yang tinggi (malaikat), semasa mereka bersoal jawab (mengenai Nabi Adam-kalaulah tidak diwahyukan kepadaku).', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 70, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'إِن يُوحَىٰ إِلَيَّ إِلَّا أَنَّمَا أَنَا نَذِيرٌ مُّبِينٌ', NULL, 'It has not been revealed to me except that I am a clear warner."', '“Tiadalah diwahyukan kepadaku melainkan kerana sesungguhnya aku seorang Rasul pemberi amaran yang jelas nyata (bukan seorang pembohong, atau ahli sihir, atau gila)”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 71, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن طِينٍ', 'إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن طِينٍ', NULL, '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.', '(Ingatkanlah peristiwa) ketika Tuhanmu berfirman kepada malaikat: “Sesungguhnya Aku hendak menciptakan manusia - Adam dari tanah;', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 72, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ', NULL, 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', '“Kemudian apabila Aku sempurnakan kejadiannya, serta Aku tiupkan padanya roh dari (ciptaan) Ku, maka hendaklah kamu sujud kepadanya”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 73, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ', NULL, 'So the angels prostrated - all of them entirely,', '(Setelah selesai kejadian Adam) maka sujudlah sekalian malaikat, semuanya sekali, -', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 74, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'إِلَّا إِبْلِيسَ اسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ', NULL, 'Except Iblees; he was arrogant and became among the disbelievers.', 'Melainkan Iblis; ia berlaku sombong takbur (mengingkarinya) serta menjadilah ia dari golongan yang kafir.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 75, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', 'قَالَ يَا إِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ الْعَالِينَ', NULL, '[Allāh] said, "O Iblees, what prevented you from prostrating to that which I created with My hands? Were you arrogant [then], or were you [already] among the haughty?"', 'Allah berfirman: “Hai lblis! Apa yang menghalangmu daripada turut sujud kepada (Adam) yang Aku telah ciptakan dengan kekuasaanKu? Adakah engkau berlaku sombong takbur, ataupun engkau dari golongan yang tertinggi?”', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 76, 'قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ', NULL, 'He said, "I am better than him. You created me from fire and created him from clay."', 'Iblis menjawab: “Aku lebih baik daripadanya; Engkau (wahai Tuhanku) ciptakan daku dari api, sedang dia Engkau ciptakan dari tanah”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 77, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', 'قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', NULL, '[Allāh] said, "Then get out of it [i.e., Paradise], for indeed, you are expelled.', 'Allah berfirman: “Kalau demikian, keluarlah engkau daripadanya, kerana sesungguhnya engkau adalah makhluk yang diusir.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 78, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 'وَإِنَّ عَلَيْكَ لَعْنَتِي إِلَىٰ يَوْمِ الدِّينِ', NULL, 'And indeed, upon you is My curse until the Day of Recompense."', '“Dan sesungguhnya engkau ditimpa laknatku terus menerus hingga ke hari kiamat!”', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 79, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'قَالَ رَبِّ فَأَنظِرْنِي إِلَىٰ يَوْمِ يُبْعَثُونَ', NULL, 'He said, "My Lord, then reprieve me until the Day they are resurrected."', 'Iblis berkata: “Wahai Tuhanku! Jika demikian, berilah tempoh kepadaku hingga ke hari mereka dibangkitkan (hari kiamat)”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 80, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'قَالَ فَإِنَّكَ مِنَ الْمُنظَرِينَ', NULL, '[Allāh] said, "So indeed, you are of those reprieved', 'Allah berfirman: “Dengan permohonanmu itu, maka sesungguhnya engkau dari golongan yang diberi tempoh -', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 81, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'إِلَىٰ يَوْمِ الْوَقْتِ الْمَعْلُومِ', NULL, 'Until the Day of the time well-known."', '“Hingga ke hari masa yang termaklum”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 82, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', NULL, '[Iblees] said, "By Your might, I will surely mislead them all', 'Iblis berkata: “Demi kekuasaanmu (wahai Tuhanku), aku akan menyesatkan mereka semuanya, -', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 83, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ', NULL, 'Except, among them, Your chosen servants."', '“Kecuali hamba-hambaMu di antara zuriat-zuriat Adam itu yang dibersihkan dari sebarang kederhakaan dan penyelewengan”.', FALSE, NULL, NULL, 457, 23, 183, 395, FALSE, 0, NULL),
(38, 84, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', 'قَالَ فَالْحَقُّ وَالْحَقَّ أَقُولُ', NULL, '[Allāh] said, "The truth [is My oath], and the truth I say -', 'Allah berfirman: “Maka Akulah Tuhan Yang Sebenar-benarnya, dan hanya perkara yang benar Aku firmankan -', FALSE, NULL, NULL, 458, 23, 183, 395, FALSE, 0, NULL),
(38, 85, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', NULL, '[That] I will surely fill Hell with you and those of them that follow you all together."', '“Demi sesungguhnya! Aku akan memenuhi neraka Jahannam dengan jenismu dan dengan orang-orang yang menurutmu di antara zuriat-zuriat Adam (yang derhaka) semuanya”.', FALSE, NULL, NULL, 458, 23, 183, 395, FALSE, 0, NULL),
(38, 86, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', 'قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ', NULL, 'Say, [O Muḥammad], "I do not ask you for it [i.e., the Qur’ān] any payment, and I am not of the pretentious.', 'Katakanlah (wahai Muhammad): “Aku tidak meminta kepada kamu sebarang bayaran kerana menyampaikan ajaran Al-Quran ini, dan bukanlah aku dari orang-orang yang mengada-ngada”.', FALSE, NULL, NULL, 458, 23, 183, 395, FALSE, 0, NULL),
(38, 87, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ', NULL, 'It is but a reminder to the worlds.', 'Al-Quran tidak lain hanyalah peringatan bagi penduduk seluruh alam.', FALSE, NULL, NULL, 458, 23, 183, 395, FALSE, 0, NULL),
(38, 88, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', 'وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ', NULL, 'And you will surely know [the truth of] its information after a time."', 'Dan demi sesungguhnya, kamu akan mengetahui kabenaran perkara-perkara yang diterangkannya, tidak lama lagi.', FALSE, NULL, NULL, 458, 23, 183, 395, FALSE, 0, NULL),
(39, 1, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'تنزيل الكتاب من الله العزيز الحكيم', NULL, 'The revelation of the Book [i.e., the Qur’ān] is from Allāh, the Exalted in Might, the Wise.', 'Turunnya Kitab Al-Quran ini dari Allah, Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 458, 23, 183, 396, FALSE, 6, NULL),
(39, 2, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', 'انا انزلنا اليك الكتاب بالحق فاعبد الله مخلصا له الدين', NULL, 'Indeed, We have sent down to you the Book, [O Muḥammad], in truth. So worship Allāh, [being] sincere to Him in religion.', 'Sesungguhnya Kami menurunkan Al-Quran ini kepadamu (wahai Muhammad) dengan membawa kebenaran; oleh itu hendaklah engkau menyembah Allah dengan mengikhlaskan segala ibadat dan bawaanmu kepadaNya.', FALSE, NULL, NULL, 458, 23, 183, 396, FALSE, 10, NULL),
(39, 3, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَـٰذِبٌ كَفَّارٌ', 'الا لله الدين الخالص والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الى الله زلفى ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كاذب كفار', NULL, 'Unquestionably, for Allāh is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allāh in position." Indeed, Allāh will judge between them concerning that over which they differ. Indeed, Allāh does not guide he who is a liar and [confirmed] disbeliever.', 'Ingatlah! (Hak yang wajib dipersembahkan) kepada Allah ialah segala ibadat dan bawaan yang suci bersih (dari segala rupa syirik). Dan orang-orang musyrik yang mengambil selain dari Allah untuk menjadi pelindung dan penolong (sambil berkata): “Kami tidak menyembah atau memujanya melainkan supaya mereka mendampingkan kami kepada Allah sehampir-hampirnya”, - sesungguhnya Allah akan menghukum di antara mereka (dengan orang-orang yang tidak melakukan syirik) tentang apa yang mereka berselisihan padanya. Sesungguhnya Allah tidak memberi hidayah petunjuk kepada orang-orang yang tetap berdusta (mengatakan yang bukan-bukan), lagi sentiasa kufur (dengan melakukan syirik).', FALSE, NULL, NULL, 458, 23, 183, 396, FALSE, 33, NULL),
(39, 4, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ ۚ سُبْحَـٰنَهُۥ ۖ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'لو اراد الله ان يتخذ ولدا لاصطفى مما يخلق ما يشاء سبحانه هو الله الواحد القهار', NULL, 'If Allāh had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allāh, the One, the Prevailing.', 'Kalaulah Allah hendak mempunyai anak, tentulah Ia memilih mana-mana yang dikehendakiNya dari makhluk-makhluk yang diciptakanNya; Maha Sucilah Ia (dari menghendaki yang demikian). Dia lah Allah, Yang Maha Esa, lagi Yang Mengatasi kekuasaanNya segala-galanya.', FALSE, NULL, NULL, 458, 23, 183, 396, FALSE, 16, NULL),
(39, 5, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۗ أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّـٰرُ', 'خلق السماوات والارض بالحق يكور الليل على النهار ويكور النهار على الليل وسخر الشمس والقمر كل يجري لاجل مسمى الا هو العزيز الغفار', NULL, 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.', 'Ia menciptakan langit dan bumi dengan ada faedah dan gunanya yang sebenar; Ia pula menjadikan malam melingkari siang (dengan gelapnya), dan menjadikan siang melingkari malam (dengan cahayanya); dan Ia menjadikan matahari dan bulan beredar menurut perintahnya, - tiap-tiap satu dari keduanya, beredar untuk suatu masa yang telah ditetapkan. Ingatlah! Dia lah Yang Maha Kuasa, lagi Yang sentiasa Mengampuni.', FALSE, NULL, NULL, 458, 23, 183, 396, FALSE, 23, NULL),
(39, 6, 'خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَـٰمِ ثَمَـٰنِيَةَ أَزْوَٰجٍ ۚ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَـٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَـٰتٍ ثَلَـٰثٍ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُصْرَفُونَ', 'خلقكم من نفس واحدة ثم جعل منها زوجها وانزل لكم من الانعام ثمانية ازواج يخلقكم في بطون امهاتكم خلقا من بعد خلق في ظلمات ثلاث ذلكم الله ربكم له الملك لا اله الا هو فانى تصرفون', NULL, 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allāh, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?', 'Ia menciptakan kamu dari diri yang satu (Adam), kemudian Ia menjadikan daripadanya - isterinya (Hawa); dan Ia mengadakan untuk kamu binatang-binatang ternak delapan ekor: (empat) pasangan (jantan dan betina). Ia menciptakan kamu dalam kandungan ibu kamu (berperingkat-peringkat) dari satu kejadian ke satu kejadian. Dalam tiga suasana yang gelap-gelita. Yang demikian (kekuasaanNya) ialah Allah Tuhan kamu; bagiNyalah kekuasaan yang mutlak; tiada Tuhan melainkan Dia; oleh itu bagaimana kamu dapat dipesongkan (dari mematuhi perintahNya)?', FALSE, NULL, NULL, 459, 23, 183, 396, FALSE, 36, NULL),
(39, 7, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ ۖ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ ۖ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ ۗ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۗ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ان تكفروا فان الله غني عنكم ولا يرضى لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازرة وزر اخرى ثم الى ربكم مرجعكم فينبئكم بما كنتم تعملون انه عليم بذات الصدور', NULL, 'If you disbelieve - indeed, Allāh is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves [i.e., likes] it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.', 'Kalaulah kamu kufur ingkar (tidak bersyukur) akan nikmat-nikmatNya itu, maka ketahuilah bahawa sesungguhnya Allah tidak berhajatkan (iman dan kesyukuran) kamu (untuk kesempurnaanNya); dan Ia tidak redakan hamba-hambaNya berkeadaan kufur; dan jika kamu bersyukur, Ia meredainya menjadi sifat dan amalan kamu. Dan (ingatlah) seseorang yang memikul tidak akan memikul dosa perbuatan orang lain (bahkan dosa usahanya sahaja). Kemudian kepada Tuhan kamulah tempat kembalinya kamu, maka Ia akan memberitahu kepada kamu tentang apa yang kamu telah kerjakan. Sesungguhnya Ia Maha Mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 459, 23, 183, 396, FALSE, 31, NULL),
(39, 8, '۞ وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ ۚ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا ۖ إِنَّكَ مِنْ أَصْحَـٰبِ ٱلنَّارِ', 'واذا مس الانسان ضر دعا ربه منيبا اليه ثم اذا خوله نعمة منه نسي ما كان يدعو اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحاب النار', NULL, 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allāh equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."', 'Dan apabila manusia disentuh oleh sesuatu bahaya, ia segera berdoa kepada Tuhannya dengan keadaan rujuk kembali bertaubat kepadaNya; kemudian apabila Allah memberikannya sesuatu nikmat (sebagai kurnia) daripadaNya, lupalah ia akan segala bahaya yang menyebabkannya merayu kepada Allah sebelum itu dan ia pula menjadikan sekutu-sekutu bagi Allah, untuk menyesatkan dirinya (dan orang lain) dari jalan Allah. Katakanlah (kepadanya): “Bersenang-senanglah engkau dengan kekufuranmu itu bagi sementara, sesungguhnya engkau dari penduduk neraka.', FALSE, NULL, NULL, 459, 23, 184, 396, FALSE, 34, NULL),
(39, 9, 'أَمَّنْ هُوَ قَـٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْـَٔاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ ۗ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', 'امن هو قانت اناء الليل ساجدا وقائما يحذر الاخرة ويرجو رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولو الالباب', NULL, 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.', '“(Engkaukah yang lebih baik) atau orang yang taat mengerjakan ibadat pada waktu malam dengan sujud dan berdiri sambil takutkan (azab) hari akhirat serta mengharapkan rahmat Tuhannya? “Katakanlah lagi (kepadanya): “Adakah sama orang-orang yang mengetahui dengan orang-orang yang tidak mengetahui?” Sesungguhnya orang-orang yang dapat mengambil pelajaran dan peringatan hanyalah orang-orang yang berakal sempurna.', FALSE, NULL, NULL, 459, 23, 184, 396, FALSE, 24, NULL),
(39, 10, 'قُلْ يَـٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ ۚ لِلَّذِينَ أَحْسَنُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةٌ ۗ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ ۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ', 'قل يا عباد الذين امنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنة وارض الله واسعة انما يوفى الصابرون اجرهم بغير حساب', NULL, 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allāh is spacious. Indeed, the patient will be given their reward without account [i.e., limit]."', 'Katakanlah (wahai Muhammad, akan firmanKu ini, kepada orang-orang yang berakal sempurna itu): “Wahai hamba-hambaKu yang beriman! Bertaqwalah kepada Tuhan kamu. (Ingatlah) orang-orang yang berbuat baik di dunia ini akan beroleh kebaikan (yang sebenar di akhirat). dan (ingatlah) bumi Allah ini luas (untuk berhijrah sekiranya kamu ditindas). Sesungguhnya orang-orang yang bersabarlah sahaja yang akan disempurnakan pahala mereka dengan tidak terkira”.', FALSE, NULL, NULL, 459, 23, 184, 397, FALSE, 21, NULL),
(39, 11, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', 'قل اني امرت ان اعبد الله مخلصا له الدين', NULL, 'Say, [O Muḥammad], "Indeed, I have been commanded to worship Allāh, [being] sincere to Him in religion.', 'Katakanlah lagi (wahai Muhammad): “Sesungguhnya aku diperintahkan supaya menyembah Allah dengan mengikhlaskan segala ibadat kepadaNya;', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 9, NULL),
(39, 12, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 'وامرت لان اكون اول المسلمين', NULL, 'And I have been commanded to be the first [among you] of the Muslims."', '“Dan aku diperintahkan supaya menjadi orang yang awal pertama berserah diri bulat-bulat (kepada Allah)”.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 5, NULL),
(39, 13, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', NULL, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', 'Katakanlah lagi: “Sesungguhnya aku takut - jika aku menderhaka kepada Tuhanku - akan azab hari yang besar (soal jawabnya)”.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 9, NULL),
(39, 14, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى', 'قل الله اعبد مخلصا له ديني', NULL, 'Say, "Allāh [alone] do I worship, sincere to Him in my religion,', 'Katakanlah lagi: “Allah jualah yang aku sembah dengan mengikhlaskan amalan ugamaku kepadaNya.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 6, NULL),
(39, 15, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ ۗ قُلْ إِنَّ ٱلْخَـٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'فاعبدوا ما شئتم من دونه قل ان الخاسرين الذين خسروا انفسهم واهليهم يوم القيامة الا ذلك هو الخسران المبين', NULL, 'So worship what you will besides Him." Say, "Indeed, the losers are the ones who will lose themselves and their families on the Day of Resurrection. Unquestionably, that is the manifest loss."', '“(Setelah kamu mengetahui pendirianku ini wahai kaum musyrik, dan kamu masih juga berdegil) maka sembahlah kamu apa yang kamu kehendaki, yang lain dari Allah, (kamu akan mengetahui akibatnya)”. Katakanlah lagi: “Sesungguhnya orang-orang yang rugi (dengan sebenar-benarnya) ialah orang-orang yang merugikan dirinya sendiri dan pengikut-pengikutnya pada hari kiamat (dengan sebab perbuatan mereka memilih kekufuran atau kederhakaan). Ingatlah, yang demikian itulah kerugian yang jelas nyata.”', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 19, NULL),
(39, 16, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ ۚ يَـٰعِبَادِ فَٱتَّقُونِ', 'لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يا عباد فاتقون', NULL, 'They will have canopies [i.e., layers] of fire above them and below them, canopies. By that Allāh threatens [i.e., warns] His servants. O My servants, then fear Me.', 'Bagi mereka (yang kafir disediakan lapisan-lapisan dari api menyerkup di atas mereka, dan lapisan-lapisan (dari api) di bawah mereka; dengan (azab) yang demikian, Allah menakutkan hamba-hambaNya: “Oleh itu, bertaqwalah kepadaKu wahai hamba-hambaKu!”', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 16, NULL),
(39, 17, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّـٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ ۚ فَبَشِّرْ عِبَادِ', 'والذين اجتنبوا الطاغوت ان يعبدوها وانابوا الى الله لهم البشرى فبشر عباد', NULL, 'But those who have avoided ṭāghūt, lest they worship it, and turned back to Allāh - for them are good tidings. So give good tidings to My servants', 'Dan orang-orang yang menjauhi dirinya dari menyembah atau memuja Taghut serta mereka rujuk kembali taat bulat-bulat kepada Allah, mereka akan beroleh berita yang mengembirakan (sebaik-baik sahaja mereka mulai meninggal dunia); oleh itu gembirakanlah hamba-hambaKu -', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 12, NULL),
(39, 18, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَـٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ', 'الذين يستمعون القول فيتبعون احسنه اولئك الذين هداهم الله واولئك هم اولو الالباب', NULL, 'Who listen to speech and follow the best of it. Those are the ones Allāh has guided, and those are people of understanding.', 'Yang berusaha mendengar perkataan-perkataan yang sampai kepadanya lalu mereka memilih dan menurut akan yang sebaik-baiknya (pada segi hukum ugama); mereka itulah orang-orang yang diberi hidayah petunjuk oleh Allah dan mereka itulah orang-orang yang berakal sempurna.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 13, NULL),
(39, 19, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 'افمن حق عليه كلمة العذاب افانت تنقذ من في النار', NULL, 'Then, is one who has deserved the decree of punishment [to be guided]? Then, can you save one who is in the Fire?', 'Maka adakah orang yang telah ditetapkan atasnya hukuman azab (disebabkan kekufurannya, sama seperti orang yang dijanjikan bergembira dengan balasan imannya? Sudah tentu tidak)! Oleh itu adakah engkau berkuasa menyelamatkan orang yang (ditetapkan kekal) dalam neraka?', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 10, NULL),
(39, 20, 'لَـٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', 'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجري من تحتها الانهار وعد الله لا يخلف الله الميعاد', NULL, 'But those who have feared their Lord - for them are chambers, above them chambers built high, beneath which rivers flow. [This is] the promise of Allāh. Allāh does not fail in [His] promise.', 'Tetapi (sebaliknya) orang-orang yang bertaqwa kepada Tuhan mereka (dengan mengerjakan suruhanNya dan menjauhi laranganNya), dibina untuk mereka (di dalam Syurga) mahligai-mahligai yang tinggi bertingkat-tingkat, yang mengalir di bawahnya beberapa sungai. Demikianlah janji yang ditetapkan Allah; Allah tidak sekali-kali akan mengubah janji-janjiNya.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 20, NULL),
(39, 21, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَسَلَكَهُ يَنَابِيعَ فِي الْأَرْضِ ثُمَّ يُخْرِجُ بِهِ زَرْعًا مُّخْتَلِفًا أَلْوَانُهُ ثُمَّ يَهِيجُ فَتَرَاهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُ حُطَامًا إِنَّ فِي ذَٰلِكَ لَذِكْرَىٰ لِأُولِي الْأَلْبَابِ', NULL, 'Do you not see that Allāh sends down rain from the sky and makes it flow as springs [and rivers] in the earth; then He produces thereby crops of varying colors; then they dry and you see them turned yellow; then He makes them [scattered] debris. Indeed in that is a reminder for those of understanding.', 'Tidakkah engkau memerhatikan, bahawa Allah menurunkan hujan dari langit, lalu dialirkanNya menjadi matair-matair di bumi; kemudian Ia menumbuhkan dengan air itu tanaman-tanaman yang berbagai jenis dan warnanya; kemudian tanaman-tanaman itu bergerak segar (hingga ke suatu masa yang tertentu), selepas itu engkau melihatmu berupa kuning; kemudian Ia menjadikannya hancur bersepai? Sesungguhnya segala yang tersebut itu mengandungi peringatan yang menyedarkan orang-orang yang berakal sempurna.', FALSE, NULL, NULL, 460, 23, 184, 397, FALSE, 0, NULL),
(39, 22, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', 'أَفَمَن شَرَحَ اللَّهُ صَدْرَهُ لِلْإِسْلَامِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِ فَوَيْلٌ لِّلْقَاسِيَةِ قُلُوبُهُم مِّن ذِكْرِ اللَّهِ أُولَٰئِكَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'So is one whose breast Allāh has expanded to [accept] Islām and he is upon [i.e., guided by] a light from his Lord [like one whose heart rejects it]? Then woe to those whose hearts are hardened against the remembrance of Allāh. Those are in manifest error.', 'Jika demikian, adakah orang yang telah dilapangkan Allah dadanya untuk menerima Islam, lalu ia tetap berada dalam cahaya (hidayah petunjuk) dari Tuhannya, (sama seperti orang yang tertutup mata hatinya dengan selaput kederhakaan)? Maka kecelakaan besarlah bagi orang-orang yang keras membatu hatinya daripada menerima peringatan yang diberi oleh Allah. Mereka yang demikian keadaannya, adalah dalam kesesatan yang nyata.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 23, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'اللَّهُ نَزَّلَ أَحْسَنَ الْحَدِيثِ كِتَابًا مُّتَشَابِهًا مَّثَانِيَ تَقْشَعِرُّ مِنْهُ جُلُودُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ اللَّهِ ذَٰلِكَ هُدَى اللَّهِ يَهْدِي بِهِ مَن يَشَاءُ وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ', NULL, 'Allāh has sent down the best statement: a consistent Book wherein is reiteration. The skins shiver therefrom of those who fear their Lord; then their skins and their hearts relax at the remembrance [i.e., mention] of Allāh. That is the guidance of Allāh by which He guides whom He wills. And one whom Allāh sends astray - for him there is no guide.', 'Allah telah menurunkan sebaik-baik perkataan iaitu Kitab Suci Al-Quran yang bersamaan isi kandungannya antara satu dengan yang lain (tentang benarnya dan indahnya), yang berulang-ulang (keterangannya, dengan berbagai cara); yang (oleh kerana mendengarnya atau membacanya) kulit badan orang-orang yang takut kepada Tuhan mereka menjadi seram; kemudian kulit badan mereka menjadi lembut serta tenang tenteram hati mereka menerima ajaran dan rahmat Allah. Kitab Suci itulah hidayah petunjuk Allah; Allah memberi hidayah petunjuk dengan Al-Quran itu kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan (ingatlah) sesiapa yang disesatkan Allah (disebabkan pilihannya yang salah), maka tidak ada sesiapa pun yang dapat memberi hidayah petunjuk kepadanya.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 24, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 'أَفَمَن يَتَّقِي بِوَجْهِهِ سُوءَ الْعَذَابِ يَوْمَ الْقِيَامَةِ وَقِيلَ لِلظَّالِمِينَ ذُوقُوا مَا كُنتُمْ تَكْسِبُونَ', NULL, 'Then is he who will shield with his face the worst of the punishment on the Day of Resurrection [like one secure from it]? And it will be said to the wrongdoers, "Taste what you used to earn."', 'Maka adakah orang yang menahan dengan mukanya akan (selaran) azab yang buruk pada hari kiamat (sama seperti orang yang terselamat)? Dan (pada saat itu) dikatakan kepada orang-orang yang zalim itu: “Rasalah (balasan) apa yang kamu usahakan dahulu”.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 25, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', NULL, 'Those before them denied, and punishment came upon them from where they did not perceive.', '(Ingatlah! Bahawa) orang-orang yang terdahulu dari mereka telah mendustakan (Rasul-rasul yang diutuskan kepada mereka), lalu orang-orang itu didatangi azab dari arah yang mereka tidak menyedarinya.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 26, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'فَأَذَاقَهُمُ اللَّهُ الْخِزْيَ فِي الْحَيَاةِ الدُّنْيَا وَلَعَذَابُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'So Allāh made them taste disgrace in worldly life. But the punishment of the Hereafter is greater, if they only knew.', 'Maka Allah merasakan mereka kehinaan dalam kehidupan dunia (dengan berbagai bala bencana), dan sesungguhnya azab seksa hari akhirat (yang disediakan untuk mereka) lebih besar lagi. Kalaulah mereka mengetahui (hakikat ini, tentulah mereka tidak mendustakan Rasul).', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 27, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And We have certainly presented for the people in this Qur’ān from every [kind of] example - that they might remember.', 'Dan demi sesungguhnya! Kami telah mengemukakan kepada umat manusia berbagai misal perbandingan dalam Al-Quran ini, supaya mereka mengambil peringatan dan pelajaran.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 28, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', 'قُرْآنًا عَرَبِيًّا غَيْرَ ذِي عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', NULL, '[It is] an Arabic Qur’ān, without any deviance that they might become righteous.', 'laitu Al-Quran yang berbahasa Arab, yang tidak mengandungi sebarang keterangan yang terpesong; supaya mereka bertaqwa.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 29, 'ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ضَرَبَ اللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَاءُ مُتَشَاكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', NULL, 'Allāh presents an example: a man [i.e., slave] owned by quarreling partners and another belonging exclusively to one man - are they equal in comparison? Praise be to Allāh! But most of them do not know.', 'Allah memberikan satu misal perbandingan: Seorang hamba lelaki yang dimiliki oleh beberapa orang yang berkongsi yang bertentangan tabiat dan kemahuannya; dan seorang hamba lelaki yang lain hanya dimilik oleh seorang sahaja; adakah kedua-dua hamba itu sama keadaannya (Tentulah tidak sama). Ucaplah: “Alhamdulillah” (sebagai bersyukur terhadap penjelasan soal tauhid itu) bahkan kebanyakan mereka (yang musyrik) tidak mengetahui (hakikat tauhid).', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 30, 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', NULL, 'Indeed, you are to die, and indeed, they are to die.', 'Sesungguhnya engkau (wahai Muhammad) akan mati, dan sesungguhnya mereka juga akan mati.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 31, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', 'ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', NULL, 'Then indeed you, on the Day of Resurrection, before your Lord, will dispute.', 'Kemudian, sesungguhnya kamu semua, pada hari kiamat, akan bertengkar berhujah di hadapan Tuhan kamu.', FALSE, NULL, NULL, 461, 23, 184, 398, FALSE, 0, NULL),
(39, 32, 'فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى اللَّهِ وَكَذَّبَ بِالصِّدْقِ إِذْ جَاءَهُ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِّلْكَافِرِينَ', NULL, 'So who is more unjust than one who lies about Allāh and denies the truth when it has come to him? Is there not in Hell a residence for the disbelievers?', '(Apabila berlaku yang demikian), maka nyatalah bahawa tidak ada yang lebih zalim daripada orang yang mereka-reka perkara-perkara yang dusta terhadap Allah, dan mendustakan kebenaran sebaik-baik sahaja kebenaran itu disampaikan kepadanya. Bukankah (telah diketahui bahawa) dalam neraka Jahannam disediakan tempat tinggal bagi orang-orang yang kafir?', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 33, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'وَالَّذِي جَاءَ بِالصِّدْقِ وَصَدَّقَ بِهِ أُولَٰئِكَ هُمُ الْمُتَّقُونَ', NULL, 'And the one who has brought the truth [i.e., the Prophet (ﷺ)] and [they who] believed in it - those are the righteous.', 'Dan (nyatalah bahawa) yang membawa kebenaran (tauhid dan hukum ugama) serta ia (dan pengikut-pengikutnya) mengakui kebenarannya (dengan mematuhi hukum itu), mereka itulah orang-orang yang bertaqwa.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 34, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'لَهُم مَّا يَشَاءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَاءُ الْمُحْسِنِينَ', NULL, 'They will have whatever they desire with their Lord. That is the reward of the doers of good -', 'Disediakan untuk mereka apa yang mereka kehendaki, di sisi Tuhan mereka; demikianlah balasan orang-orang yang berusaha memperbaiki amal perbuatannya.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 35, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'لِيُكَفِّرَ اللَّهُ عَنْهُمْ أَسْوَأَ الَّذِي عَمِلُوا وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ الَّذِي كَانُوا يَعْمَلُونَ', NULL, 'That Allāh may remove from them the worst of what they did and reward them their due for the best of what they used to do.', '(Limpah kurnia yang demikian, diberikan kepada orang-orang yang bertaqwa) kerana Allah hendak menghapuskan dari mereka (kalaulah ada) seburuk-buruk amal perbuatan yang mereka telah lakukan, serta membalas mereka, akan pahala mereka, dengan balasan yang lebih baik dari apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 36, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ وَيُخَوِّفُونَكَ بِالَّذِينَ مِن دُونِهِ وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ', NULL, 'Is not Allāh sufficient for His Servant [i.e., Prophet Muḥammad (ﷺ)]? And [yet], they threaten you with those [they worship] other than Him. And whoever Allāh leaves astray - for him there is no guide.', 'Bukankah Allah cukup untuk mengawal dan melindungi hambaNya (yang bertaqwa)? Dan mereka menakutkanmu (wahai Muhammad) dengan yang mereka sembah yang lain dari Allah. Dan (ingatlah) sesiapa yang disesatkan oleh Allah (dengan pilihannya yang salah), maka tidak ada sesiapapun yang dapat memberi hidayah petunjuk kepadanya.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 37, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ', 'وَمَن يَهْدِ اللَّهُ فَمَا لَهُ مِن مُّضِلٍّ أَلَيْسَ اللَّهُ بِعَزِيزٍ ذِي انتِقَامٍ', NULL, 'And whoever Allāh guides - for him there is no misleader. Is not Allāh Exalted in Might and Owner of Retribution?', 'Dan sesiapa yang diberi hidayah petunjuk oleh Allah (dengan sebab pilihannya yang benar), maka tidak ada sesiapapun yang dapat menyesatkannya. Bukankah Allah Maha Kuasa, lagi berhak membalas dengan azab seksa (kepada golongan yang bersalah)?', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 38, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ قُلْ حَسْبِىَ ٱللَّهُ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلْ أَفَرَأَيْتُم مَّا تَدْعُونَ مِن دُونِ اللَّهِ إِنْ أَرَادَنِيَ اللَّهُ بِضُرٍّ هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ أَوْ أَرَادَنِي بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَاتُ رَحْمَتِهِ قُلْ حَسْبِيَ اللَّهُ عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ', NULL, 'And if you asked them, "Who created the heavens and the earth?" they would surely say, "Allāh." Say, "Then have you considered what you invoke besides Allāh? If Allāh intended me harm, are they removers of His harm; or if He intended me mercy, are they withholders of His mercy?" Say, "Sufficient for me is Allāh; upon Him [alone] rely the [wise] reliers."', 'Dan demi sesungguhnya! Jika engkau (wahai Muhammad) bertanya kepada mereka (yang musyrik) itu: “Siapakah yang mencipta langit dan bumi?” Sudah tentu mereka akan menjawab: “Allah”. Katakanlah (kepada mereka): “Kalau demikian, bagaimana fikiran kamu tentang yang kamu sembah yang lain dari Allah itu? Jika Allah hendak menimpakan daku dengan sesuatu bahaya, dapatkah mereka mengelakkan atau menghapuskan bahayaNya itu; atau jika Allah hendak memberi rahmat kepadaku, dapatkah mereka menahan rahmatNya itu?” Katakanlah lagi: “Cukuplah bagiku: Allah (yang menolong dan memeliharaku); kepadaNyalah hendaknya berserah orang-orang yang mahu berserah diri”.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 39, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ فَسَوْفَ تَعْلَمُونَ', 'قُلْ يَا قَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ', NULL, 'Say, "O my people, work according to your position, [for] indeed, I am working; and you are going to know', 'Katakanlah: “Wahai kaumku (yang masih berdegil dalam kekufurannya)! Buatlah sedaya upaya kamu (untuk menentang ugama Islam yang aku sampaikan itu), sesungguhnya aku juga tetap berusaha dengan bersungguh-sungguh (untuk mengembangkannya); kemudian kamu akan mengetahui kelak -', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 40, 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', NULL, 'To whom will come a torment disgracing him and on whom will descend an enduring punishment."', '“Siapakah yang akan didatangi azab yang menghinakannya, serta akan ditimpakan kepadanya azab seksa yang berkekalan”.', FALSE, NULL, NULL, 462, 24, 185, 399, FALSE, 0, NULL),
(39, 41, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'إِنَّا أَنزَلْنَا عَلَيْكَ الْكِتَابَ لِلنَّاسِ بِالْحَقِّ فَمَنِ اهْتَدَىٰ فَلِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا أَنتَ عَلَيْهِم بِوَكِيلٍ', NULL, 'Indeed, We sent down to you the Book for the people in truth. So whoever is guided - it is for [the benefit of] his soul; and whoever goes astray only goes astray to its detriment. And you are not a manager [i.e., authority] over them.', 'Sesungguhnya Kami telah menurunkan kepadamu (wahai Muhammad) Kitab Suci Al-Quran yang menyatakan segala kebenaran (untuk menjadi panduan hidup) kepada umat manusia seluruhnya. Oleh itu sesiapa yang mendapat hidayah petunjuk (beramal menurutnya), maka faedahnya terpulang kepada dirinya sendiri; dan sesiapa yang sesat (tidak berpandu kepadanya), maka bahaya kesesatannya itu tertimpa ke atas dirinya sendiri; dan engkau (wahai Muhammad - hanyalah penyampai) bukanlah menjadi wakil yang menguasai (keadaan dan bawaan) mereka.', FALSE, NULL, NULL, 463, 24, 185, 399, FALSE, 0, NULL),
(39, 42, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَىٰ عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَىٰ إِلَىٰ أَجَلٍ مُّسَمًّى إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', NULL, 'Allāh takes the souls at the time of their death, and those that do not die [He takes] during their sleep. Then He keeps those for which He has decreed death and releases the others for a specified term. Indeed in that are signs for a people who give thought.', 'Allah (Yang Menguasai Segala-galanya), Ia mengambil dan memisahkan satu-satu jiwa dari badannya, jiwa orang yang sampai ajalnya semasa matinya, dan jiwa orang yang tidak mati: dalam masa tidurnya; kemudian Ia menahan jiwa orang yang Ia tetapkan matinya dan melepaskan balik jiwa yang lain (ke badannya) sehingga sampai ajalnya yang ditentukan. Sesungguhnya yang demikian itu mengandungi tanda-tanda yang membuktikan kekuasaan Allah bagi kaum yang berfikir (untuk memahaminya).', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 43, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ', 'أَمِ اتَّخَذُوا مِن دُونِ اللَّهِ شُفَعَاءَ قُلْ أَوَلَوْ كَانُوا لَا يَمْلِكُونَ شَيْئًا وَلَا يَعْقِلُونَ', NULL, 'Or have they taken other than Allāh as intercessors? Say, "Even though they do not possess [power over] anything, nor do they reason?"', 'Patutkah mereka (yang musyrik) mengambil yang lain dari Allah menjadi pemberi syafaat? Bertanyalah (kepada mereka): “Dapatkah yang lain dari Allah memberi syafaat padahal semuanya tidak pula mengerti (sebarang apa pun)?”', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 44, 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًا لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'قُل لِّلَّهِ الشَّفَاعَةُ جَمِيعًا لَّهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ', NULL, 'Say, "To Allāh belongs [the right to allow] intercession entirely. To Him belongs the dominion of the heavens and the earth. Then to Him you will be returned."', 'Katakanlah (wahai Muhammad): “Syafaat itu semuanya hak kepunyaan Allah; Dia lah Yang Menguasai segala urusan langit dan bumi; kemudian kamu akan dikembalikan kepadaNya (untuk menerima balasan).”', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 45, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'وَإِذَا ذُكِرَ اللَّهُ وَحْدَهُ اشْمَأَزَّتْ قُلُوبُ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ وَإِذَا ذُكِرَ الَّذِينَ مِن دُونِهِ إِذَا هُمْ يَسْتَبْشِرُونَ', NULL, 'And when Allāh is mentioned alone, the hearts of those who do not believe in the Hereafter shrink with aversion, but when those [worshipped] other than Him are mentioned, immediately they rejoice.', 'Dan (di antara keburukan orang-orang yang melakukan syirik): apabila disebut nama Allah semata-mata (di dalam doa dan sebagainya), segan serta liarlah hati mereka yang tidak beriman kepada hari akhirat; dan apabila disebut nama-nama yang mereka sembah dan puja yang lain dari Allah, mereka dengan serta merta riang dan gembira.', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 46, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'قُلِ اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِي مَا كَانُوا فِيهِ يَخْتَلِفُونَ', NULL, 'Say, "O Allāh, Creator of the heavens and the earth, Knower of the unseen and the witnessed, You will judge between your servants concerning that over which they used to differ."', 'Ucapkanlah (wahai Muhammad): “Wahai Tuhan yang menciptakan langit dan bumi, yang mengetahui perkara-perkara yang ghaib dan yang nyata, Engkaulah jua yang mengadili di antara hamba-hambaMu, mengenai apa yang mereka sentiasa berselisihan padanya”.', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 47, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا مَا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لَافْتَدَوْا بِهِ مِن سُوءِ الْعَذَابِ يَوْمَ الْقِيَامَةِ وَبَدَا لَهُم مِّنَ اللَّهِ مَا لَمْ يَكُونُوا يَحْتَسِبُونَ', NULL, 'And if those who did wrong had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby from the worst of the punishment on the Day of Resurrection. And there will appear to them from Allāh that which they had not taken into account.', 'Dan sekiranya orang-orang zalim itu mempunyai segala apa jua yang ada di bumi, disertai sebanyak itu lagi, tentulah mereka rela menebus diri mereka dengannya daripada azab seksa yang buruk pada hari kiamat, setelah jelas nyata kepada mereka dari (hukum) Allah, azab yang mereka tidak pernah fikirkan.', FALSE, NULL, NULL, 463, 24, 185, 400, FALSE, 0, NULL),
(39, 48, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'And there will appear to them the evils they had earned, and they will be enveloped by what they used to ridicule.', 'Dan sudah tentu akan nyata kepada mereka keburukan perkara-perkara yang mereka telah usahakan, dan mereka akan diliputi oleh azab yang mereka telah ejek-ejek itu.', FALSE, NULL, NULL, 464, 24, 185, 400, FALSE, 0, NULL),
(39, 49, 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'فَإِذَا مَسَّ الْإِنسَانَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَاهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلْمٍ بَلْ هِيَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'And when adversity touches man, he calls upon Us; then when We bestow on him a favor from Us, he says, "I have only been given it because of [my] knowledge." Rather, it is a trial, but most of them do not know.', 'Maka apabila manusia disentuh oleh sesuatu bahaya, ia segera berdoa kepada Kami; kemudian apabila Kami memberikannya sesuatu nikmat (sebagai kurnia) dari Kami, berkatalah ia (dengan sombongnya): “Aku diberikan nikmat ini hanyalah disebabkan pengetahuan dan kepandaian yang ada padaku”. (Tidaklah benar apa yang dikatakannya itu) bahkan pemberian nikmat yang tersebut adalah ujian (adakah ia bersyukur atau sebaliknya), akan tetapi kebanyakan mereka tidak mengetahui (hakikat itu).', FALSE, NULL, NULL, 464, 24, 185, 400, FALSE, 0, NULL),
(39, 50, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'قَدْ قَالَهَا الَّذِينَ مِن قَبْلِهِمْ فَمَا أَغْنَىٰ عَنْهُم مَّا كَانُوا يَكْسِبُونَ', NULL, 'Those before them had already said it, but they were not availed by what they used to earn.', 'Sebenarnya orang-orang yang terdahulu daripada mereka telah juga mengatakan yang demikian maka segala yang mereka usahakan itu tidak dapat menyelamatkan mereka (dari azab Allah).', FALSE, NULL, NULL, 464, 24, 185, 400, FALSE, 0, NULL),
(39, 51, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', 'فَأَصَابَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَالَّذِينَ ظَلَمُوا مِنْ هَٰؤُلَاءِ سَيُصِيبُهُمْ سَيِّئَاتُ مَا كَسَبُوا وَمَا هُم بِمُعْجِزِينَ', NULL, 'And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be struck [i.e., afflicted] by the evil consequences of what they earned; and they will not cause failure.', 'Lalu mereka ditimpa keburukan padah perbuatan-perbuatan jahat yang mereka lakukan; dan orang-orang yang zalim di antara golongan (yang musyrik) ini akan ditimpa juga akibat buruk perbuatan-perbuatan buruk perbuatan jahat yang mereka lakukan, dan mereka tidak akan dapat melepaskan diri.', FALSE, NULL, NULL, 464, 24, 185, 400, FALSE, 0, NULL),
(39, 52, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'أَوَلَمْ يَعْلَمُوا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يُؤْمِنُونَ', NULL, 'Do they not know that Allāh extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.', '(Mengapa mereka mendakwa demikian), tidakkah mereka mengetahui bahawa sesungguhnya Allah memewahkan rezeki bagi sesiapa yang dikehendakiNya, dan Ia juga yang menyempitkannya? Sesungguhnya yang demikian mengandungi keterangan-keterangan yang jelas bagi orang-orang yang percayakan (ilmu dan kebijaksanaan Allah).', FALSE, NULL, NULL, 464, 24, 185, 400, FALSE, 0, NULL),
(39, 53, 'قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ', NULL, 'Say, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allāh. Indeed, Allāh forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."', 'Katakanlah (wahai Muhammad): “Wahai hamba-hambaKu yang telah melampaui batas terhadap diri mereka sendiri (dengan perbuatan-perbuatan maksiat), janganlah kamu berputus asa dari rahmat Allah, kerana sesungguhnya Allah mengampunkan segala dosa; sesungguhnya Dia lah jua Yang Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 464, 24, 186, 401, FALSE, 0, NULL),
(39, 54, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 'وَأَنِيبُوا إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا لَهُ مِن قَبْلِ أَن يَأْتِيَكُمُ الْعَذَابُ ثُمَّ لَا تُنصَرُونَ', NULL, 'And return [in repentance] to your Lord and submit to Him before the punishment comes upon you; then you will not be helped.', '“Dan kembalilah kamu kepada Tuhan kamu dengan bertaubat, serta berserah bulat-bulat kepadaNya, sebelum kamu didatangi azab; kerana sesudah itu kamu tidak akan diberikan pertolongan.', FALSE, NULL, NULL, 464, 24, 186, 401, FALSE, 0, NULL),
(39, 55, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', 'وَاتَّبِعُوا أَحْسَنَ مَا أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ الْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', NULL, 'And follow the best of what was revealed to you from your Lord [i.e., the Qur’ān] before the punishment comes upon you suddenly while you do not perceive,', '“Dan turutlah - Al-Quran - sebaik-baik. (panduan hidup) yang diturunkan kepada kamu dari Tuhan kamu, sebelum kamu didatangi azab secara mengejut, sedang kamu tidak menyedarinya.', FALSE, NULL, NULL, 464, 24, 186, 401, FALSE, 0, NULL),
(39, 56, 'أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', 'أَن تَقُولَ نَفْسٌ يَا حَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنبِ اللَّهِ وَإِن كُنتُ لَمِنَ السَّاخِرِينَ', NULL, 'Lest a soul should say, "Oh, [how great is] my regret over what I neglected in regard to Allāh and that I was among the mockers."', '“(Diperintahkan demikian) supaya jangan seseorang (menyesal dengan) berkata: ‘sungguh besar sesal dan kecewaku kerana aku telah mencuaikan kewajipan-kewajipanku terhadap Allah serta aku telah menjadi dari orang-orang yang sungguh memperolok-olokkan (ugama Allah dan penganut-penganutnya)! -', FALSE, NULL, NULL, 464, 24, 186, 401, FALSE, 0, NULL),
(39, 57, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', 'أَوْ تَقُولَ لَوْ أَنَّ اللَّهَ هَدَانِي لَكُنتُ مِنَ الْمُتَّقِينَ', NULL, 'Or [lest] it say, "If only Allāh had guided me, I would have been among the righteous."', '“Atau berkata: ‘Kalaulah Allah memberi hidayah petunjuk kepadaku, tentulah aku telah menjadi dari orang-orang yang bertaqwa!’ -', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 58, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 'أَوْ تَقُولَ حِينَ تَرَى الْعَذَابَ لَوْ أَنَّ لِي كَرَّةً فَأَكُونَ مِنَ الْمُحْسِنِينَ', NULL, 'Or [lest] it say when it sees the punishment, "If only I had another turn so I could be among the doers of good."', '“Atau berkata semasa ia melihat azab: ‘Kalaulah aku dapat kembali ke dunia, nescaya menjadilah aku dari orang-orang yang mengerjakan kebaikan!”', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 59, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', 'بَلَىٰ قَدْ جَاءَتْكَ آيَاتِي فَكَذَّبْتَ بِهَا وَاسْتَكْبَرْتَ وَكُنتَ مِنَ الْكَافِرِينَ', NULL, 'But yes, there had come to you My verses, but you denied them and were arrogant, and you were among the disbelievers.', '(Kata-kata yang tersebut ditolak oleh Allah dengan firmanNya): “Bahkan telahpun datang kepadamu ayat-ayat petunjukKu (melalui RasulKu), maka engkau telah mendustakannya serta engkau berlaku sombong angkuh mengenainya, dan engkau telah menjadikan dirimu dari orang-orang yang kufur ingkar!”', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 60, 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', 'وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', NULL, 'And on the Day of Resurrection you will see those who lied about Allāh [with] their faces blackened. Is there not in Hell a residence for the arrogant?', 'Dan pada hari kiamat, engkau akan melihat orang-orang yang berdusta terhadap Allah (dan yang menyatakan kesedihan itu) - muka mereka hitam legam; bukankah (telah diketahui bahawa) dalam neraka Jahannam disediakan tempat tinggal bagi orang-orang yang sombong takbur?', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 61, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 'وَيُنَجِّي اللَّهُ الَّذِينَ اتَّقَوْا بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ السُّوءُ وَلَا هُمْ يَحْزَنُونَ', NULL, 'And Allāh will save those who feared Him by their attainment; no evil will touch them, nor will they grieve.', 'Dan (sebaliknya) Allah akan menyelamatkan orang-orang yang bertaqwa (yang menjauhkan diri dari perbuatan syirik dan maksiat) dengan mereka mendapat kemenangan besar (keredaan Allah) mereka tidak akan disentuh sesuatu yang buruk, dan tidak akan berdukacita.', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 62, 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ وَكِيلٌ', NULL, 'Allāh is the Creator of all things, and He is, over all things, Disposer of affairs.', 'Allah Yang Menciptakan tiap-tiap sesuatu, dan Dia lah Yang Mentadbirkan serta menguasai segala-galanya.', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 63, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'لَّهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ وَالَّذِينَ كَفَرُوا بِآيَاتِ اللَّهِ أُولَٰئِكَ هُمُ الْخَاسِرُونَ', NULL, 'To Him belong the keys of the heavens and the earth. And they who disbelieve in the verses of Allāh - it is those who are the losers.', 'Dia sahajalah yang menguasai urusan dan perbendaharaan langit dan bumi; (orang-orang yang percayakan yang demikian beruntunglah) dan orang-orang yang kufur ingkar akan ayat-ayat keterangan Allah yang jelas nyata itu, mereka itulah orang-orang yang paling rugi.', FALSE, NULL, NULL, 465, 24, 186, 401, FALSE, 0, NULL),
(39, 64, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', 'قُلْ أَفَغَيْرَ اللَّهِ تَأْمُرُونِّي أَعْبُدُ أَيُّهَا الْجَاهِلُونَ', NULL, 'Say, [O Muḥammad], "Is it other than Allāh that you order me to worship, O ignorant ones?"', 'Katakanlah (wahai Muhammad, kepada orang-orang musyrik itu: “Sesudah jelas dalil-dalil keesaan Allah yang demikian), patutkah kamu menyuruhku menyembah atau memuja yang lain dari Allah, hai orang-orang yang jahil?”', FALSE, NULL, NULL, 465, 24, 186, 402, FALSE, 0, NULL),
(39, 65, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ', NULL, 'And it was already revealed to you and to those before you that if you should associate [anything] with Allāh, your work would surely become worthless, and you would surely be among the losers.', 'Dan sesungguhnya telah diwahyukan kepadamu (wahai Muhammad) dan kepada Nabi-nabi yang terdahulu daripadamu: “Demi sesungguhnya! jika engkau (dan pengikut-pengikutmu) mempersekutukan (sesuatu yang lain dengan Allah) tentulah akan gugur amalmu, dan engkau akan tetap menjadi dari orang-orang yang rugi.', FALSE, NULL, NULL, 465, 24, 186, 402, FALSE, 0, NULL),
(39, 66, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'بَلِ اللَّهَ فَاعْبُدْ وَكُن مِّنَ الشَّاكِرِينَ', NULL, 'Rather, worship [only] Allāh and be among the grateful.', '“(Janganlah menyembah yang lain dari Allah) bahkan (apabila beribadat) maka hendaklah engkau menyembah Allah semata-mata, dan hendaklah engkau menjadi dari orang-orang yang bersyukur”.', FALSE, NULL, NULL, 465, 24, 186, 402, FALSE, 0, NULL),
(39, 67, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ', NULL, 'They have not appraised Allāh with true appraisal, while the earth entirely will be [within] His grip on the Day of Resurrection, and the heavens will be folded in His right hand. Exalted is He and high above what they associate with Him.', 'Dan mereka (yang musyrik) tidak menghormati Allah dengan penghormatan yang sewajibnya diberikan kepadaNya, sedang bumi seluruhnya - pada hari kiamat - dalam genggaman kuasaNya, dan langit tergulung dengan kekuasaanNya. Maha Sucilah Ia dan Tertinggi keadaanNya dari apa yang mereka sekutukan.', FALSE, NULL, NULL, 465, 24, 186, 402, FALSE, 0, NULL),
(39, 68, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', 'وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', NULL, 'And the Horn will be blown, and whoever is in the heavens and whoever is on the earth will fall dead except whom Allāh wills. Then it will be blown again, and at once they will be standing, looking on.', 'Dan sudah tentu akan ditiup sangkakala, maka pada waktu itu matilah makhluk-makhluk yang ada di langit dan yang ada di bumi, kecuali sesiapa yang dikehendaki Allah (terkemudian matinya); kemudian ditiup sangkakala sekali lagi, maka dengan serta merta mereka bangun berdiri menunggu (kesudahan masing-masing).', FALSE, NULL, NULL, 466, 24, 186, 402, FALSE, 0, NULL),
(39, 69, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'وَأَشْرَقَتِ الْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ الْكِتَابُ وَجِيءَ بِالنَّبِيِّينَ وَالشُّهَدَاءِ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And the earth will shine with the light of its Lord, and the record [of deeds] will be placed, and the prophets and the witnesses will be brought, and it will be judged between them in truth, and they will not be wronged.', 'Dan akan bersinar terang-benderanglah bumi (hari akhirat) dengan cahaya Tuhannya; dan akan diberikan Kitab suratan amal (untuk dibicarakan); dan akan dibawa Nabi-nabi serta saksi-saksi; dan akan dihakimi di antara mereka dengan adil, sedang mereka tidak dikurangkan balasannya sedikitpun.', FALSE, NULL, NULL, 466, 24, 186, 402, FALSE, 0, NULL),
(39, 70, 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', NULL, 'And every soul will be fully compensated [for] what it did; and He is most knowing of what they do.', 'Dan akan disempurnakan bagi tiap-tiap seorang - balasan apa yang telah dikerjakannya, dan Allah lebih mengetahui akan apa yang mereka telah lakukan.', FALSE, NULL, NULL, 466, 24, 186, 402, FALSE, 0, NULL),
(39, 71, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 'وَسِيقَ الَّذِينَ كَفَرُوا إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ آيَاتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَٰذَا قَالُوا بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكَافِرِينَ', NULL, 'And those who disbelieved will be driven to Hell in groups until, when they reach it, its gates are opened and its keepers will say, "Did there not come to you messengers from yourselves, reciting to you the verses of your Lord and warning you of the meeting of this Day of yours?" They will say, "Yes, but the word [i.e., decree] of punishment has come into effect upon the disbelievers."', 'Dan orang-orang kafir akan dihalau ke neraka Jahannam dengan berpasuk-pasukan, sehingga apabila mereka sampai ke neraka itu dibukakan pintu-pintunya dan berkatalah penjaga-penjaganya kepada mereka: Bukankah telah datang kepada kamu Rasul-rasul dari kalangan kamu sendiri, yang membacakan kepada kamu ayat-ayat Tuhan kamu dan memperingatkan kamu akan pertemuan hari kamu ini?” Mereka menjawab: “Ya, telah datang! Tetapi telah ditetapkan hukuman azab atas orang-orang yang kafir.', FALSE, NULL, NULL, 466, 24, 186, 403, FALSE, 0, NULL),
(39, 72, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'قِيلَ ادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ', NULL, '[To them] it will be said, "Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."', '(Setelah itu) dikatakan kepada mereka: “Masukilah pintu-pintu neraka Jahannam itu dengan keadaan tinggal kekal kamu di dalamnya; maka seburuk-buruk tempat bagi orang-orang yang sombong takbur ialah neraka Jahannam.', FALSE, NULL, NULL, 466, 24, 186, 403, FALSE, 0, NULL),
(39, 73, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', 'وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ', NULL, 'But those who feared their Lord will be driven to Paradise in groups until, when they reach it while its gates have been opened and its keepers say, "Peace be upon you; you have become pure; so enter it to abide eternally therein," [they will enter].', 'Dan orang-orang yang bertaqwa kepada Tuhan mereka akan dibawa ke Syurga dengan berpasuk-pasukan, sehingga apabila mereka sampai ke Syurga yang pintu-pintunya sedia terbuka dan penjaga-penjaganya mengalu-alukan mereka dengan kata-kata: “Salam sejahtera kepada kamu, berbahagialah kamu, maka silalah masuk ke dalam Syurga ini dengan keadaan tinggal kekal di dalamnya” (mereka pun masuk) -', FALSE, NULL, NULL, 466, 24, 186, 403, FALSE, 0, NULL),
(39, 74, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي صَدَقَنَا وَعْدَهُ وَأَوْرَثَنَا الْأَرْضَ نَتَبَوَّأُ مِنَ الْجَنَّةِ حَيْثُ نَشَاءُ فَنِعْمَ أَجْرُ الْعَامِلِينَ', NULL, 'And they will say, "Praise to Allāh, who has fulfilled for us His promise and made us inherit the earth [so] we may settle in Paradise wherever we will. And excellent is the reward of [righteous] workers."', 'Serta mereka berkata: “Segala puji tertentu bagi Allah yang telah menepati janjiNya kepada kami, dan yang menjadikan kami mewarisi bumi Syurga ini dengan sebebas-bebasnya, kami boleh mengambil tempat dari Syurga ini di mana sahaja kami sukai; maka pemberian yang demikian ialah sebaik-baik balasan bagi orang-orang yang beramal”.', FALSE, NULL, NULL, 466, 24, 186, 403, FALSE, 0, NULL),
(39, 75, 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'وَتَرَى الْمَلَائِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'And you will see the angels surrounding the Throne, exalting [Allāh] with praise of their Lord. And it will be judged between them in truth, and it will be said, "[All] praise to Allāh, Lord of the worlds."', 'Dan (pada hari itu) engkau akan melihat malaikat beredar di sekeliling Arasy dengan bertasbih memuji Tuhan mereka, serta mereka dihakimi dengan adil; dan (masing-masing bersyukur akan keputusan itu dengan) mengucapkan: “Segala puji tertentu bagi Allah Tuhan yang memelihara dan mentadbirkan seluruh alam!”', FALSE, NULL, NULL, 467, 24, 186, 403, FALSE, 0, NULL),
(40, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 1, NULL),
(40, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'تنزيل الكتاب من الله العزيز العليم', NULL, 'The revelation of the Book [i.e., the Qur’ān] is from Allāh, the Exalted in Might, the Knowing,', 'Turunnya Al-Quran ini dari Allah Yang Maha Kuasa, lagi Maha Mengetahui;', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 6, NULL),
(40, 3, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ إِلَيْهِ ٱلْمَصِيرُ', 'غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير', NULL, 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.', 'Yang Mengampunkan dosa, dan Yang Menerima taubat; Yang Berat azabNya; Yang Melimpah-limpah kurniaNya; tiada Tuhan melainkan Dia; kepadaNyalah tempat kembali.', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 14, NULL),
(40, 4, 'مَا يُجَـٰدِلُ فِىٓ ءَايَـٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَـٰدِ', 'ما يجادل في ايات الله الا الذين كفروا فلا يغررك تقلبهم في البلاد', NULL, 'No one disputes concerning the signs of Allāh except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.', 'Tidak ada yang membantah mengenai ayat-ayat Allah melainkan orang-orang yang kafir. Oleh itu janganlah engkau (wahai Muhammad) diperdayakan oleh kebebasan mereka bergerak dengan berulang alik dari sebuah bandar ke bandar yang lain.', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 13, NULL),
(40, 5, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ ۖ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ ۖ وَجَـٰدَلُوا۟ بِٱلْبَـٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', 'كذبت قبلهم قوم نوح والاحزاب من بعدهم وهمت كل امة برسولهم لياخذوه وجادلوا بالباطل ليدحضوا به الحق فاخذتهم فكيف كان عقاب', NULL, 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.', 'Sebelum mereka, kaum Nabi Nuh dan puak-puak yang bergabung - sesudah kaum Nabi Nuh itu - telah mendustakan (Rasul-rasulnya), dan tiap-tiap umat di antaranya telah merancangkan rancangan jahat terhadap Rasul mereka untuk menawannya (dan membinasakannya); dan mereka pula telah membantah dengan perkara yang salah untuk menghapuskan kebenaran dengan perkara yang salah itu; sebab itu Aku binasakan mereka. Maka (lihatlah) bagaimana kesan azabKu!', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 21, NULL),
(40, 6, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَـٰبُ ٱلنَّارِ', 'وكذلك حقت كلمت ربك على الذين كفروا انهم اصحاب النار', NULL, 'And thus has the word [i.e., decree] of your Lord come into effect upon those who disbelieved that they are companions of the Fire.', 'Dan demikianlah juga tetapnya hukuman Tuhanmu terhadap orang-orang yang kafir, kerana sesungguhnya mereka ialah ahli neraka.', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 10, NULL),
(40, 7, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 'الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين امنوا ربنا وسعت كل شيء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم', NULL, 'Those [angels] who carry the Throne and those around it exalt [Allāh] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.', 'Malaikat yang memikul Arasy dan malaikat yang berada di sekelilingnya, bertasbih memuji TuhanNya; dan beriman kepadaNya; serta mereka memohon ampun bagi orang-orang yang beriman (dengan berdoa merayu): “Wahai Tuhan kami! RahmatMu dan IlmuMu meliputi segala-galanya; maka berilah ampun kepada orang-orang yang bertaubat serta menurut jalanMu, dan peliharalah mereka dari azab neraka.', FALSE, NULL, NULL, 467, 24, 187, 404, FALSE, 27, NULL),
(40, 8, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّـٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّـٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ربنا وادخلهم جنات عدن التي وعدتهم ومن صلح من ابائهم وازواجهم وذرياتهم انك انت العزيز الحكيم', NULL, 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their forefathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.', '“Wahai Tuhan kami! Dan masukkanlah mereka ke dalam Syurga “Adn” yang Engkau telah janjikan kepada mereka; dan (masukkanlah bersama-sama mereka): orang-orang yang layak di antara ibu bapa mereka, dan isteri-isteri mereka, serta keturunan mereka. Sesungguhnya Engkaulah jua Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 468, 24, 187, 404, FALSE, 16, NULL),
(40, 9, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ ۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'وقهم السيئات ومن تق السيئات يومئذ فقد رحمته وذلك هو الفوز العظيم', NULL, 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."', '“Dan peliharalah mereka dari (balasan) kejahatan-kejahatan (yang dilakukannya); dan (sebenarnya) sesiapa yang Engkau pelihara pada hari itu dari terkena (balasan) kejahatan-kejahatan (yang dilakukannya) maka sesungguhnya Engkau telah mengurniakan rahmat kepadanya; dan yang demikian itulah kemenangan yang besar (nilainya)”.', FALSE, NULL, NULL, 468, 24, 187, 404, FALSE, 12, NULL),
(40, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَـٰنِ فَتَكْفُرُونَ', 'ان الذين كفروا ينادون لمقت الله اكبر من مقتكم انفسكم اذ تدعون الى الايمان فتكفرون', NULL, 'Indeed, those who disbelieve will be addressed, "The hatred of Allāh for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you disbelieved [i.e., refused]."', 'Sesungguhnya orang-orang yang kafir akan dipanggil dan dikatakan kepada mereka (pada hari kiamat): “Demi sesungguhnya! Kebencian Allah (kepada kamu) lebih besar daripada kebencian kamu kepada diri sendiri, (sebabnya kerana) semasa kamu diseru dan diajak (di dunia dahulu) supaya beriman, (kamu enggan dan menolak), lalu kamu terus berkeadaan kufur”.', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 15, NULL),
(40, 11, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ', 'قالوا ربنا امتنا اثنتين واحييتنا اثنتين فاعترفنا بذنوبنا فهل الى خروج من سبيل', NULL, 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"', 'Mereka menjawab: “Wahai Tuhan kami! Engkau telah menjadikan kami berkeadaan mati dua kali, dan telah menjadikan kami bersifat hidup dua kali, maka kami (sekarang) mengakui akan dosa-dosa kami. Oleh itu adakah sebarang jalan untuk (kami) keluar (dari neraka)?”', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 13, NULL),
(40, 12, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ ۖ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ ۚ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', 'ذلكم بانه اذا دعي الله وحده كفرتم وان يشرك به تؤمنوا فالحكم لله العلي الكبير', NULL, '[They will be told], "That is because, when Allāh was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allāh, the Most High, the Grand."', '(Lalu dikatakan kepada mereka): “Azab yang kamu berada padanya itu adalah kerana keadaan kamu apabila Allah Yang Maha Esa sahaja diseru dan disembah, kamu kufur (dan menolak cara bertauhid itu); dan apabila dipersekutukan sesuatu dengan Allah, kamu percaya (dan menerima bawaan syirik itu). Maka kuasa menjalankan keadilan adalah hak Allah, Yang Maha Tinggi (dari apa yang dipersekutukan), lagi Yang Maha Besar (pemerintahanNya)”.', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 15, NULL),
(40, 13, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَـٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا ۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 'هو الذي يريكم اياته وينزل لكم من السماء رزقا وما يتذكر الا من ينيب', NULL, 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].', 'Dia lah Tuhan yang memperlihatkan kepada kamu tanda-tanda keesaanNya dan kekuasaanNya (untuk kehidupan rohani kamu), dan yang menurunkan (untuk jasmani kamu) sebab-sebab rezeki dari langit. Dan tiadalah yang ingat serta mengambil pelajaran (dari yang demikian) melainkan orang yang sentiasa bertumpu (kepada Allah).', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 14, NULL),
(40, 14, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', 'فادعوا الله مخلصين له الدين ولو كره الكافرون', NULL, 'So invoke Allāh, [being] sincere to Him in religion, although the disbelievers dislike it.', 'Oleh itu maka sembahlah kamu akan Allah dengan mengikhlaskan ibadat kepadaNya (dan menjauhi bawaan syirik), sekalipun orang-orang kafir tidak menyukai (amalan kamu yang demikian).', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 8, NULL),
(40, 15, 'رَفِيعُ ٱلدَّرَجَـٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 'رفيع الدرجات ذو العرش يلقي الروح من امره على من يشاء من عباده لينذر يوم التلاق', NULL, '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command [i.e., revelation] upon whom He wills of His servants to warn of the Day of Meeting.', 'Dia lah Yang Maha tinggi darjat kebesaranNya, yang mempunyai Arasy (yang melambangkan keagungan dan kekuasaanNya); Ia memberikan wahyu dari hal perintahNya kepada sesiapa yang dikehendakiNya di antara hamba-hambaNya (yang telah dipilih menjadi RasulNya), supaya Ia memberi amaran (kepada manusia) tentang hari pertemuan,', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 16, NULL),
(40, 16, 'يَوْمَ هُم بَـٰرِزُونَ ۖ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ ۚ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ ۖ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'يوم هم بارزون لا يخفى على الله منهم شيء لمن الملك اليوم لله الواحد القهار', NULL, 'The Day they come forth nothing concerning them will be concealed from Allāh. To whom belongs [all] sovereignty this Day? To Allāh, the One, the Prevailing.', 'Iaitu hari mereka keluar (dari kubur masing-masing) dengan jelas nyata; tidak akan tersembunyi kepada Allah sesuatupun dari hal keadaan mereka. (Pada saat itu Allah berfirman): “Siapakah yang menguasai kerajaan pada hari ini? (Allah sendiri menjawab): “Dikuasai oleh Allah Yang Maha Esa, lagi Yang Mengatasi kekuasaanNya segala-galanya!', FALSE, NULL, NULL, 468, 24, 187, 405, FALSE, 15, NULL),
(40, 17, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ ۚ لَا ظُلْمَ ٱلْيَوْمَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'اليوم تجزى كل نفس بما كسبت لا ظلم اليوم ان الله سريع الحساب', NULL, 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allāh is swift in account.', '“Pada hari ini, tiap-tiap diri dibalas dengan apa yang telah diusahakannya; tidak ada hukuman yang tidak adil pada hari ini. Sesungguhnya Allah amat cepat hitungan hisabNya.', FALSE, NULL, NULL, 469, 24, 187, 405, FALSE, 13, NULL),
(40, 18, 'وَأَنذِرْهُمْ يَوْمَ ٱلْـَٔازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَـٰظِمِينَ ۚ مَا لِلظَّـٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ', 'وانذرهم يوم الازفة اذ القلوب لدى الحناجر كاظمين ما للظالمين من حميم ولا شفيع يطاع', NULL, 'And warn them, [O Muḥammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.', 'Dan berilah amaran (wahai Muhammad) kepada mereka tentang (hari kiamat) yang dekat (masa datangnya), iaitu ketika hati seseorang merasa resah gelisah, kerana cemas takut, sambil masing-masing menahan perasaannya itu. (Pada saat itu) orang-orang yang zalim tidak akan mendapat seorang sahabatpun yang boleh membelanya, dan tidak akan mendapat pemberi syafaat yang diterima pertolongannya.', FALSE, NULL, NULL, 469, 24, 187, 405, FALSE, 15, NULL),
(40, 19, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 'يعلم خائنة الاعين وما تخفي الصدور', NULL, 'He knows that which deceives the eyes and what the breasts conceal.', 'Allah mengetahui pengkhianatan (penyelewengan dan ketiadaan jujur) pandangan mata seseorang, serta mengetahui akan apa yang tersembunyi di dalam hati.', FALSE, NULL, NULL, 469, 24, 187, 405, FALSE, 6, NULL),
(40, 20, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ ۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء ان الله هو السميع البصير', NULL, 'And Allāh judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allāh - He is the Hearing, the Seeing.', 'Dan Allah memutuskan hukum dengan adil, sedang yang mereka sembah yang lain dari Allah - tidak dapat memberikan sebarang keputusan. Sesungguhnya Allah Dia lah Yang Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 469, 24, 187, 405, FALSE, 15, NULL),
(40, 21, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', 'أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ كَانُوا مِن قَبْلِهِمْ كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَآثَارًا فِي الْأَرْضِ فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ اللَّهِ مِن وَاقٍ', NULL, 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allāh seized them for their sins. And they had not from Allāh any protector.', 'Tidakkah mereka telah berjalan dan mengembara di muka bumi, dengan itu tidakkah mereka memerhatikan bagaimana kesudahan orang-orang yang terdahulu dari mereka? Orang-orang itu adalah orang-orang yang lebih dari mereka tentang kekuatan tenaga dan tentang kesan-kesan usaha pembangunan di muka bumi. Maka sekalipun demikian, Allah binasakan mereka dengan sebab dosa-dosa mereka, dan tiadalah bagi mereka sesiapapun yang dapat menyelamatkan mereka dari azab Allah.', FALSE, NULL, NULL, 469, 24, 188, 406, FALSE, 0, NULL),
(40, 22, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِالْبَيِّنَاتِ فَكَفَرُوا فَأَخَذَهُمُ اللَّهُ إِنَّهُ قَوِيٌّ شَدِيدُ الْعِقَابِ', NULL, 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allāh seized them. Indeed, He is Powerful and severe in punishment.', '(Kebinasaan mereka) yang demikian ialah kerana mereka sentiasa didatangi Rasul-rasul yang diutuskan kepada mereka dengan membawa keterangan-keterangan (hukum-hukum dan mukjizat) yang jelas nyata, maka mereka kufur ingkar, lalu Allah menyeksa mereka, sesungguhnya Allah adalah Maha Kuat lagi Maha berat azab seksaNya.', FALSE, NULL, NULL, 469, 24, 188, 406, FALSE, 0, NULL),
(40, 23, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِآيَاتِنَا وَسُلْطَانٍ مُّبِينٍ', NULL, 'And We did certainly send Moses with Our signs and a clear authority', 'Dan demi sesungguhnya! Kami telah mengutuskan Nabi Musa membawa ayat-ayat Kami dan bukti (mukjizat) yang jelas nyata', FALSE, NULL, NULL, 469, 24, 188, 406, FALSE, 0, NULL),
(40, 24, 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌ كَذَّابٌ', 'إِلَىٰ فِرْعَوْنَ وَهَامَانَ وَقَارُونَ فَقَالُوا سَاحِرٌ كَذَّابٌ', NULL, 'To Pharaoh, Hāmān and Qārūn, but they said, "[He is] a magician and a liar."', 'Kepada Firaun dan Haman serta Qarun; maka mereka (menuduhnya dengan) berkata: “Ia seorang ahli sihir, lagi pendusta!”', FALSE, NULL, NULL, 469, 24, 188, 406, FALSE, 0, NULL),
(40, 25, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'فَلَمَّا جَاءَهُم بِالْحَقِّ مِنْ عِندِنَا قَالُوا اقْتُلُوا أَبْنَاءَ الَّذِينَ آمَنُوا مَعَهُ وَاسْتَحْيُوا نِسَاءَهُمْ وَمَا كَيْدُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ', NULL, 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.', 'Setelah Nabi Musa datang kepada mereka dengan membawa kebenaran dari sisi Kami, mereka berkata (dengan marahnya): “Bunuhlah anak-anak lelaki orang-orang yang beriman yang mengikutnya, dan biarkan hidup anak-anak perempuan mereka”. (Tetapi usaha) dan tipu daya orang-orang kafir itu hanya menyebabkan mereka tenggelam dalam kesesatan dan kebinasaan sahaja.', FALSE, NULL, NULL, 469, 24, 188, 406, FALSE, 0, NULL),
(40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', 'وَقَالَ فِرْعَوْنُ ذَرُونِي أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُ إِنِّي أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِي الْأَرْضِ الْفَسَادَ', NULL, 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."', 'Dan berkatalah Firaun (kepada orang-orangnya): “Biarkanlah aku membunuh Musa, dan biarlah dia memohon kepada Tuhannya (meminta pertolongan)! Sesungguhnya aku bimbang dia akan menukar ugama kamu, atau ia menimbulkan kerosakan di muka bumi”.', FALSE, NULL, NULL, 470, 24, 188, 406, FALSE, 0, NULL),
(40, 27, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 'وَقَالَ مُوسَىٰ إِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ الْحِسَابِ', NULL, 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."', 'Dan (setelah mendengar ancaman itu) Nabi Musa berkata: “Sesungguhnya aku berlindung kepada Allah Tuhanku dan Tuhan kamu - dari (angkara) tiap-tiap orang yang sombong takbur, yang tidak beriman kepada hari hitungan amal!”', FALSE, NULL, NULL, 470, 24, 188, 406, FALSE, 0, NULL),
(40, 28, 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ آلِ فِرْعَوْنَ يَكْتُمُ إِيمَانَهُ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ اللَّهُ وَقَدْ جَاءَكُم بِالْبَيِّنَاتِ مِن رَّبِّكُمْ وَإِن يَكُ كَاذِبًا فَعَلَيْهِ كَذِبُهُ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ الَّذِي يَعِدُكُمْ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', NULL, 'And a believing man from the family of Pharaoh who concealed his faith said, "Do you kill a man [merely] because he says, ''My Lord is Allāh'' while he has brought you clear proofs from your Lord? And if he should be lying, then upon him is [the consequence of] his lie; but if he should be truthful, there will strike you some of what he promises you. Indeed, Allāh does not guide one who is a transgressor and a liar.', 'Dan (pada saat itu) berkatalah pula seorang lelaki yang beriman dari orang-orang Firaun yang menyembunyikan imannya: “Patutkah kamu membunuh seorang lelaki kerana ia menegaskan: ‘Tuhanku ialah Allah?’ - sedang ia telah datang kepada kamu membawa keterangan-keterangan dari Tuhan kamu? Kalau ia seorang yang berdusta maka dia lah yang akan menanggung dosa dustanya itu, dan kalau ia seorang yang benar nescaya kamu akan ditimpa oleh sebahagian dari (azab) yang dijanjikannya kepada kamu. Sesungguhnya Allah tidak memberi hidayah petunjuk kepada orang yang melampaui batas, lagi pendusta.', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 29, 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 'يَا قَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظَاهِرِينَ فِي الْأَرْضِ فَمَن يَنصُرُنَا مِن بَأْسِ اللَّهِ إِن جَاءَنَا قَالَ فِرْعَوْنُ مَا أُرِيكُمْ إِلَّا مَا أَرَىٰ وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ', NULL, 'O my people, sovereignty is yours today, [your being] dominant in the land. But who would protect us from the punishment of Allāh if it came to us?" Pharaoh said, "I do not show you except what I see, and I do not guide you except to the way of right conduct."', '“Wahai kaumku! Pada hari ini kepunyaan kamulah kuasa memerintah dengan bermaharajalela di muka bumi (Mesir dan sekitarnya; tetapi kiranya keadaan bertukar) maka siapakah yang akan membela kita dari azab Allah kalau azab itu datang menimpa kita?” Firaun berkata: “Aku tidak mengesyorkan kepada kamu melainkan dengan apa yang aku pandang (elok dijalankan), dan aku tidak menunjukkan kepada kamu melainkan jalan yang benar”.', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 30, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 'وَقَالَ الَّذِي آمَنَ يَا قَوْمِ إِنِّي أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ الْأَحْزَابِ', NULL, 'And he who believed said, "O my people, indeed I fear for you [a fate] like the day of the companies -', 'Dan berkatalah pula orang yang beriman itu: “Wahai kaumku! Sesungguhnya aku bimbang kamu akan ditimpa (kebinasaan) sebagaimana yang telah menimpa kaum-kaum yang bergabung (menentang Rasul-rasulnya)!', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَالَّذِينَ مِن بَعْدِهِمْ وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', NULL, 'Like the custom of the people of Noah and of ʿAad and Thamūd and those after them. And Allāh wants no injustice for [His] servants.', '“(Iaitu) seperti keadaan kaum Nabi Nuh, dan Aad (kaum Nabi Hud), dan Thamud (kaum Nabi Soleh), serta orang-orang yang datang kemudian daripada mereka (seperti kaum Nabi Lut). Dan (ingatlah) Allah tidak menghendaki berbuat kezaliman kepada hamba-hambaNya.', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 32, 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 'وَيَا قَوْمِ إِنِّي أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ', NULL, 'And O my people, indeed I fear for you the Day of Calling -', '“Dan, wahai kaumku! Sesungguhnya aku bimbang kamu akan ditimpa azab seksa hari (kiamat) yang padanya masing-masing menjerit-jerit memanggil (memohon pertolongan),', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ اللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ', NULL, 'The Day you will turn your backs fleeing; there is not for you from Allāh any protector. And whoever Allāh sends astray - there is not for him any guide.', '“(Iaitu) hari kamu berpaling undur melarikan diri; padahal semasa itu tidak ada sesiapapun yang dapat menyelamatkan kamu dari azab Allah. Dan (ingatlah) sesiapa yang disesatkan Allah (disebabkan pilihannya yang salah), maka tiada sesiapapun yang dapat memberi hidayah petunjuk kepadanya.', FALSE, NULL, NULL, 470, 24, 188, 407, FALSE, 0, NULL),
(40, 34, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', 'وَلَقَدْ جَاءَكُمْ يُوسُفُ مِن قَبْلُ بِالْبَيِّنَاتِ فَمَا زِلْتُمْ فِي شَكٍّ مِّمَّا جَاءَكُم بِهِ حَتَّىٰ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ اللَّهُ مِن بَعْدِهِ رَسُولًا كَذَٰلِكَ يُضِلُّ اللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', NULL, 'And Joseph had already come to you before with clear proofs, but you remained in doubt of that which he brought to you, until when he died, you said, ''Never will Allāh send a messenger after him.'' Thus does Allāh leave astray he who is a transgressor and skeptic."', '“Dan demi sesungguhnya! Nabi Yusuf telah datang kepada kamu dahulu dengan membawa keterangan-keterangan (yang membuktikan kerasulannya), maka kamu tetap juga dalam keraguan mengenai apa yang disampaikannya kepada kamu sehingga apabila ia mati, kamu berkata: Allah tidak akan mengutuskan lagi Rasul sesudahnya; demikianlah Allah menyesatkan sesiapa yang melampau kederhakaannya, lagi yang ragu-ragu kepercayaannya (terhadap balasan Tuhannya), -', FALSE, NULL, NULL, 471, 24, 188, 407, FALSE, 0, NULL),
(40, 35, 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', 'الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ كَبُرَ مَقْتًا عِندَ اللَّهِ وَعِندَ الَّذِينَ آمَنُوا كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', NULL, 'Those who dispute concerning the signs of Allāh without an authority having come to them - great is hatred [of them] in the sight of Allāh and in the sight of those who have believed. Thus does Allāh seal over every heart [belonging to] an arrogant tyrant.', '“(Iaitu) orang-orang yang membantah mengenai maksud ayat-ayat Allah dengan tidak ada sebarang bukti yang sampai kepada mereka (dari pihak yang diakui benarnya). (Bantahan yang demikian) besar kebenciannya dan kemurkaannya di sisi hukum Allah dan di sisi bawaan orang-orang yang beriman. Demikianlah Allah meteraikan atas hati tiap-tiap orang yang sombong takbur, lagi bermaharajalela pencerobohannya!”', FALSE, NULL, NULL, 471, 24, 188, 407, FALSE, 0, NULL),
(40, 36, 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', 'وَقَالَ فِرْعَوْنُ يَا هَامَانُ ابْنِ لِي صَرْحًا لَّعَلِّي أَبْلُغُ الْأَسْبَابَ', NULL, 'And Pharaoh said, "O Hāmān, construct for me a tower that I might reach the ways -', 'Dan Firaun pula berkata: “Hai Haman! Binalah untukku sebuah bangunan yang tinggi, semoga aku sampai ke jalan-jalan (yang aku hendak menujunya)', FALSE, NULL, NULL, 471, 24, 188, 407, FALSE, 0, NULL),
(40, 37, 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ', 'أَسْبَابَ السَّمَاوَاتِ فَأَطَّلِعَ إِلَىٰ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُ كَاذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوءُ عَمَلِهِ وَصُدَّ عَنِ السَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِي تَبَابٍ', NULL, 'The ways into the heavens - so that I may look at the deity of Moses; but indeed, I think he is a liar." And thus was made attractive to Pharaoh the evil of his deed, and he was averted from the [right] way. And the plan of Pharaoh was not except in ruin.', '“(Iaitu) ke pintu-pintu langit, supaya aku dapat melihat Tuhan Musa; dan sesungguhnya aku percaya Musa itu seorang pendusta!” Demikianlah diperhiaskan (oleh Syaitan) kepada Firaun akan perbuatannya yang buruk itu untuk dipandang baik, serta ia dihalangi dari jalan yang benar; dan tipu daya Firaun itu tidak membawanya melainkan ke dalam kerugian dan kebinasaan.', FALSE, NULL, NULL, 471, 24, 188, 407, FALSE, 0, NULL),
(40, 38, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 'وَقَالَ الَّذِي آمَنَ يَا قَوْمِ اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ', NULL, 'And he who believed said, "O my people, follow me; I will guide you to the way of right conduct.', 'Dan berkatalah pula orang beriman itu: “Wahai kaumku! Turutlah (nasihatku), aku akan menunjukkan kepada kamu jalan yang benar.', FALSE, NULL, NULL, 471, 24, 188, 408, FALSE, 0, NULL),
(40, 39, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌ وَإِنَّ ٱلْـَٔاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 'يَا قَوْمِ إِنَّمَا هَٰذِهِ الْحَيَاةُ الدُّنْيَا مَتَاعٌ وَإِنَّ الْآخِرَةَ هِيَ دَارُ الْقَرَارِ', NULL, 'O my people, this worldly life is only [temporary] enjoyment, and indeed, the Hereafter - that is the home of [permanent] settlement.', '“Wahai kaumku! Sesungguhnya kehidupan dunia ini hanyalah kesenangan (untuk sementara waktu sahaja), dan sesungguhnya hari akhirat itulah sahaja negeri yang kekal.', FALSE, NULL, NULL, 471, 24, 188, 408, FALSE, 0, NULL),
(40, 40, 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُولَٰئِكَ يَدْخُلُونَ الْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', NULL, 'Whoever does an evil deed will not be recompensed except by the like thereof; but whoever does righteousness, whether male or female, while he is a believer - those will enter Paradise, being given provision therein without account.', '“Sesiapa yang mengerjakan sesuatu perbuatan jahat maka ia tidak dibalas melainkan dengan kejahatan yang sebanding dengannya; dan sesiapa yang mengerjakan amal soleh - dari lelaki atau perempuan - sedang ia beriman, maka mereka itu akan masuk Syurga; mereka beroleh rezeki di dalam Syurga itu dengan tidak dihitung.', FALSE, NULL, NULL, 471, 24, 188, 408, FALSE, 0, NULL),
(40, 41, 'وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', 'وَيَا قَوْمِ مَا لِي أَدْعُوكُمْ إِلَى النَّجَاةِ وَتَدْعُونَنِي إِلَى النَّارِ', NULL, 'And O my people, how is it that I invite you to salvation while you invite me to the Fire?', '“Dan wahai kaumku! Apa halnya aku dengan kamu? Aku mengajak kamu kepada keselamatan, dan kamu pula mengajakku ke neraka?', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 42, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', 'تَدْعُونَنِي لِأَكْفُرَ بِاللَّهِ وَأُشْرِكَ بِهِ مَا لَيْسَ لِي بِهِ عِلْمٌ وَأَنَا أَدْعُوكُمْ إِلَى الْعَزِيزِ الْغَفَّارِ', NULL, 'You invite me to disbelieve in Allāh and associate with Him that of which I have no knowledge, and I invite you to the Exalted in Might, the Perpetual Forgiver.', '“Kamu mengajakku supaya aku kufur (tidak percayakan keesaan) Allah dan mempersekutukanNya dengan apa yang aku tidak mempunyai pengetahuan mengenainya, padahal aku mengajak kamu beriman kepada Allah Yang Maha Kuasa, lagi Maha Pengampun?', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 43, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْـَٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِي إِلَيْهِ لَيْسَ لَهُ دَعْوَةٌ فِي الدُّنْيَا وَلَا فِي الْآخِرَةِ وَأَنَّ مَرَدَّنَا إِلَى اللَّهِ وَأَنَّ الْمُسْرِفِينَ هُمْ أَصْحَابُ النَّارِ', NULL, 'Assuredly, that to which you invite me has no [response to a] supplication in this world or in the Hereafter; and indeed, our return is to Allāh, and indeed, the transgressors will be companions of the Fire.', '“Tidak syak lagi, bahawa makhluk-makhluk yang kamu ajak aku menyembahnya itu tidak dapat menyahut sebarang seruan (atau memberikan sebarang pertolongan) sama ada di dunia atau di akhirat; dan sesungguhnya tempat kembali kita semua ialah kepada Allah, dan sebenarnya orang-orang yang melampau kejahatannya itu, merekalah ahli neraka.', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 44, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', 'فَسَتَذْكُرُونَ مَا أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ', NULL, 'And you will remember what I [now] say to you, and I entrust my affair to Allāh. Indeed, Allāh is Seeing of [His] servants."', '“(Kiranya kamu tetap berdegil sekarang) maka kamu sudah tentu akan mengetahui kebenaran apa yang aku katakan kepada kamu; dan aku sentiasa menyerahkan urusanku bulat-bulat kepada Allah (untuk memeliharaku); sesungguhnya Allah Maha Melihat akan keadaan hamba-hambaNya”.', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 45, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', 'فَوَقَاهُ اللَّهُ سَيِّئَاتِ مَا مَكَرُوا وَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ الْعَذَابِ', NULL, 'So Allāh protected him from the evils they plotted, and the people of Pharaoh were enveloped by the worst of punishment -', '(Dengan keikhlasannya dan penyerahan dirinya kepada Allah) maka ia diselamatkan oleh Allah dari angkara tipu daya mereka; dan Firaun bersama-sama kaumnya ditimpa azab seksa yang seburuk-buruknya,', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 46, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', 'النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ', NULL, 'The Fire; they are exposed to it morning and evening. And the Day the Hour appears [it will be said], "Make the people of Pharaoh enter the severest punishment."', 'Mereka didedahkan kepada bahang api neraka pada waktu pagi dan petang (semasa mereka berada dalam alam Barzakh); dan pada hari berlakunya kiamat (diperintahkan kepada malaikat): “Masukkanlah Firaun dan pengikut-pengikutnya ke dalam azab seksa api neraka yang seberat-beratnya!”', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 47, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ', 'وَإِذْ يَتَحَاجُّونَ فِي النَّارِ فَيَقُولُ الضُّعَفَاءُ لِلَّذِينَ اسْتَكْبَرُوا إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ النَّارِ', NULL, 'And [mention] when they will argue within the Fire, and the weak will say to those who had been arrogant, "Indeed, we were [only] your followers, so will you relieve us of a share of the Fire?"', 'Dan (ingatkanlah perkara yang berlaku) semasa orang-orang yang kafir dan yang menderhaka berbantah-bantahan dalam neraka, iaitu orang-orang yang lemah (yang menjadi pengikut) berkata kepada pemimpin-pemimpinnya yang sombong takbur: “Sesungguhnya kami telah menjadi pengikut-pengikut kamu, maka dapatkah kamu menolak dari kami sebahagian daripada azab neraka ini?”', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 48, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 'قَالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا كُلٌّ فِيهَا إِنَّ اللَّهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ', NULL, 'Those who had been arrogant will say, "Indeed, all [of us] are in it. Indeed, Allāh has judged between the servants."', 'Orang-orang yang sombong angkuh itu menjawab: “Sebenarnya kita semua menderita bersama-sama dalam neraka (tidak ada jalan untuk kita melepaskan diri), kerana sesungguhnya Allah telah menetapkan hukumanNya di antara sekalian hambaNya”', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 49, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ', 'وَقَالَ الَّذِينَ فِي النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُوا رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ الْعَذَابِ', NULL, 'And those in the Fire will say to the keepers of Hell, "Supplicate your Lord to lighten for us a day from the punishment."', 'Dan berkatalah pula orang-orang yang ada dalam neraka kepada malaikat-malaikat penjaga neraka Jahannam: “Pohonkanlah kepada Tuhan kamu, supaya Ia meringankan sedikit azab seksa dari kami, barang sehari”.', FALSE, NULL, NULL, 472, 24, 189, 408, FALSE, 0, NULL),
(40, 50, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ قَالُوا۟ بَلَىٰ قَالُوا۟ فَٱدْعُوا۟ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'قَالُوا أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِالْبَيِّنَاتِ قَالُوا بَلَىٰ قَالُوا فَادْعُوا وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ', NULL, 'They will say, "Did there not come to you your messengers with clear proofs?" They will say, "Yes." They will reply, "Then supplicate [yourselves], but the supplication of the disbelievers is not except in error [i.e., futility]."', 'Malaikat penjaga neraka menjawab: “Bukankah kamu telah didatangi Rasul-rasul kamu dengan membawa keterangan-keterangan (yang menyatakan akibat perbuatan derhaka kamu)?” Mereka menjawab: “Ya, telah datang”. Malaikat itu berkata: “Jika demikian, maka berdoalah kamu sendiri. Dan doa permohonan orang-orang yang kafir pada saat ini hanya menyebabkan mereka berada dalam keadaan dukacita dan kecewa sahaja”.', FALSE, NULL, NULL, 473, 24, 189, 408, FALSE, 0, NULL),
(40, 51, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', 'إِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَادُ', NULL, 'Indeed, We will support Our messengers and those who believe during the life of this world and on the Day when the witnesses will stand -', 'Sesungguhnya Kami tetap membela serta mempertahankan Rasul-rasul Kami dan orang-orang yang beriman - dalam kehidupan dunia ini dan pada saat bangkitnya saksi-saksi (pada hari kiamat)', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 52, 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'يَوْمَ لَا يَنفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ', NULL, 'The Day their excuse will not benefit the wrongdoers, and they will have the curse, and they will have the worst home [i.e., Hell].', '(Iaitu) pada hari yang tidak berguna bagi orang-orang yang zalim dalihan-dalihan mereka untuk melepaskan diri, dan mereka akan beroleh laknat, serta mereka beroleh seburuk-buruk tempat tinggal.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 53, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 'وَلَقَدْ آتَيْنَا مُوسَى الْهُدَىٰ وَأَوْرَثْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ', NULL, 'And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture', 'Dan demi sesungguhnya! Kami telah memberikan Nabi Musa hidayah petunjuk dan Kami berikan kaum Bani Israil mewarisi Kitab Taurat,', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 54, 'هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'هُدًى وَذِكْرَىٰ لِأُولِي الْأَلْبَابِ', NULL, 'As guidance and a reminder for those of understanding.', 'Sebagai hidayah petunjuk dan peringatan bagi orang-orang yang berakal sempurna.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 55, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَاسْتَغْفِرْ لِذَنبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالْإِبْكَارِ', NULL, 'So be patient, [O Muḥammad]. Indeed, the promise of Allāh is truth. And ask forgiveness for your sin and exalt [Allāh] with praise of your Lord in the evening and the morning.', '(Setelah engkau mengetahui perihal Nabi Musa dan umatnya) maka bersabarlah (wahai Muhammad, dalam perjuangan menegakkan Islam); sesungguhnya janji Allah (untuk menjayakanmu) adalah benar. Dan pohonlah ampun bagi salah silapmu, serta bertasbihlah dengan memuji Tuhanmu pada waktu pagi dan petang.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 56, 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'إِنَّ الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ إِن فِي صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَالِغِيهِ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ', NULL, 'Indeed, those who dispute concerning the signs of Allāh without [any] evidence having come to them - there is not within their breasts except pride, [the extent of] which they cannot reach. So seek refuge in Allāh. Indeed, it is He who is the Hearing, the Seeing.', 'Sesungguhnya orang-orang yang membantah mengenai maksud ayat-ayat Tuhanmu dengan tidak berdasarkan sebarang bukti yang sampai kepada mereka (dari pihak yang diakui benarnya), tidak ada dalam dada mereka melainkan perasaan mahukan kebesaran (untuk mengatasimu), kemahuan yang mereka tidak sekali-kali akan dapat mencapainya. Oleh itu mintalah perlindungan kepada Allah (dari angkara mereka); sesungguhnya Dia lah jua Yang Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 57, 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'لَخَلْقُ السَّمَاوَاتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know.', 'Demi sesungguhnya, menciptakan langit dan bumi (dari tiada kepada ada) lebih besar (dan lebih menakjubkan) daripada menciptakan manusia dan menghidupkannya semula (sesudah matinya); akan tetapi kebanyakan manusia (yang mengingkari hari kiamat) tidak mengetahui.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 58, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ قَلِيلًا مَّا تَتَذَكَّرُونَ', 'وَمَا يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَلَا الْمُسِيءُ قَلِيلًا مَّا تَتَذَكَّرُونَ', NULL, 'And not equal are the blind and the seeing, nor are those who believe and do righteous deeds and the evildoer. Little do you remember.', 'Dan sememangnya tidaklah sama orang yang buta dan orang yang melihat, dan juga tidaklah sama orang-orang yang beriman serta beramal soleh dengan orang yang melakukan kejahatan. (Meskipun hakikat ini jelas nyata, tetapi) sedikit sangat kamu beringat dan insaf.', FALSE, NULL, NULL, 473, 24, 189, 409, FALSE, 0, NULL),
(40, 59, 'إِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'إِنَّ السَّاعَةَ لَآتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ', NULL, 'Indeed, the Hour is coming - no doubt about it - but most of the people do not believe.', 'Sesungguhnya hari kiamat tetap akan datang, tidak ada sebarang syak tentang kedatangannya; akan tetapi kebanyakan manusia tidak beriman (akan hakikat itu).', FALSE, NULL, NULL, 474, 24, 189, 409, FALSE, 0, NULL),
(40, 60, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', 'وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', NULL, 'And your Lord says, "Call upon Me; I will respond to you." Indeed, those who disdain My worship will enter Hell [rendered] contemptible.', 'Dan Tuhan kamu berfirman: “Berdoalah kamu kepadaKu nescaya Aku perkenankan doa permohonan kamu. Sesungguhnya orang-orang yang sombong takbur daripada beribadat dan berdoa kepadaKu, akan masuk neraka Jahannam dalam keadaan hina.', FALSE, NULL, NULL, 474, 24, 189, 409, FALSE, 0, NULL),
(40, 61, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'اللَّهُ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ', NULL, 'It is Allāh who made for you the night that you may rest therein and the day giving sight. Indeed, Allāh is the possessor of bounty for the people, but most of them are not grateful.', 'Allah yang menjadikan malam untuk kamu supaya kamu berehat padanya, dan menjadikan siang terang-benderang (supaya kamu berusaha). Sesungguhnya Allah sentiasa melimpah-limpah kurniaNya kepada manusia seluruhnya, akan tetapi kebanyakan manusia tidak bersyukur.', FALSE, NULL, NULL, 474, 24, 189, 410, FALSE, 0, NULL),
(40, 62, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', 'ذَٰلِكُمُ اللَّهُ رَبُّكُمْ خَالِقُ كُلِّ شَيْءٍ لَّا إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', NULL, 'That is Allāh, your Lord, Creator of all things; there is no deity except Him, so how are you deluded?', 'Yang bersifat demikian ialah Allah, Tuhan kamu; yang menciptakan tiap-tiap sesuatu (dari tiada kepada ada); tiada Tuhan (yang berhak disembah) melainkan Dia; maka bagaimana kamu dapat dipalingkan (daripada menyembahNya)?', FALSE, NULL, NULL, 474, 24, 189, 410, FALSE, 0, NULL),
(40, 63, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'كَذَٰلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بِآيَاتِ اللَّهِ يَجْحَدُونَ', NULL, 'Thus were those [before you] deluded who were rejecting the signs of Allāh.', 'Sebagaimana terpalingnya mereka itu (daripada menyembah Allah), terpaling juga orang-orang yang mengingkari keterangan-keterangan Allah.', FALSE, NULL, NULL, 474, 24, 189, 410, FALSE, 0, NULL),
(40, 64, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا وَالسَّمَاءَ بِنَاءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ الطَّيِّبَاتِ ذَٰلِكُمُ اللَّهُ رَبُّكُمْ فَتَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ', NULL, 'It is Allāh who made for you the earth a place of settlement and the sky a structure [i.e., ceiling] and formed you and perfected your forms and provided you with good things. That is Allāh, your Lord; then blessed is Allāh, Lord of the worlds.', 'Allah yang menjadikan bumi sebagai tempat penetapan untuk kamu, dan langit sebagai bumbung yang kukuh binaannya; dan Ia membentuk kamu lalu memperelokkan rupa kamu, serta dikurniakan kepada kamu dari benda-benda yang baik lagi halal. Yang demikian (kekuasaanNya dan kemurahanNya) ialah Allah Tuhan kamu; maka nyatalah kelebihan dan kemurahan Allah, Tuhan sekalian alam.', FALSE, NULL, NULL, 474, 24, 189, 410, FALSE, 0, NULL),
(40, 65, 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'هُوَ الْحَيُّ لَا إِلَٰهَ إِلَّا هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', NULL, 'He is the Ever-Living; there is no deity except Him, so call upon Him, [being] sincere to Him in religion. [All] praise is [due] to Allāh, Lord of the worlds.', 'Dia lah Yang Tetap Hidup; tiada Tuhan (yang berhak disembah) melainkan Dia; maka sembahlah kamu akan Dia dengan mengikhlaskan amal ugama kamu kepadaNya semata-mata. Segala puji tertentu bagi Allah Tuhan yang memelihara dan mentadbirkan sekalian alam.', FALSE, NULL, NULL, 474, 24, 189, 410, FALSE, 0, NULL),
(40, 66, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَاتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ', NULL, 'Say, [O Muḥammad], "Indeed, I have been forbidden to worship those you call upon besides Allāh once the clear proofs have come to me from my Lord, and I have been commanded to submit to the Lord of the worlds."', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku dilarang menyembah benda-benda yang kamu sembah yang lain dari Allah - setelah datang kepadaku keterangan-keterangan yang jelas nyata dari Tuhanku; dan aku diperintahkan supaya tunduk taat bulat-bulat kepada perintah Tuhan sekalian alam”.', FALSE, NULL, NULL, 474, 24, 190, 410, FALSE, 0, NULL),
(40, 67, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', 'هُوَ الَّذِي خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوا أَشُدَّكُمْ ثُمَّ لِتَكُونُوا شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوا أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', NULL, 'It is He who created you from dust, then from a sperm-drop, then from a clinging clot; then He brings you out as a child; then [He develops you] that you reach your [time of] maturity, then [further] that you become elders. And among you is he who is taken in death before [that], so that you reach a specified term; and perhaps you will use reason.', 'Dia lah yang menciptakan kamu dari tanah, kemudian dari (setitis) air benih, kemudian dari sebuku darah beku, kemudian dari seketul daging; kemudian Ia mengeluarkan kamu berupa kanak-kanak; kemudian kamu (dipelihara) hingga sampai ke peringkat umur dewasa; kemudian kamu (dipanjangkan umur) hingga sampai menjadi tua. Dan (dalam pada itu) ada di antara kamu yang dimatikan sebelum itu. (Allah melakukan kejadian yang demikian) supaya kamu sampai ke masa yang ditentukan (untuk menerima balasan); dan supaya kamu memahami (hikmat-hikmat kejadian itu dan kekuasaan Tuhan).', FALSE, NULL, NULL, 475, 24, 190, 410, FALSE, 0, NULL),
(40, 68, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'هُوَ الَّذِي يُحْيِي وَيُمِيتُ فَإِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ', NULL, 'He it is who gives life and causes death; and when He decrees a matter, He but says to it, "Be," and it is.', 'Dia lah yang menghidupkan dan mematikan; oleh itu apabila Ia menetapkan jadinya sesuatu perkara maka Ia hanya berfirman kepadanya: “Jadilah engkau!” Lalu menjadilah ia.', FALSE, NULL, NULL, 475, 24, 190, 410, FALSE, 0, NULL),
(40, 69, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', 'أَلَمْ تَرَ إِلَى الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ أَنَّىٰ يُصْرَفُونَ', NULL, 'Do you not consider those who dispute concerning the signs of Allāh - how are they averted?', 'Tidakkah engkau melihat dan merasa hairan terhadap orang-orang yang membantah mengenai maksud ayat-ayat Allah, bagaimana mereka telah dipalingkan (dari kebenaran)?', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 70, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', 'الَّذِينَ كَذَّبُوا بِالْكِتَابِ وَبِمَا أَرْسَلْنَا بِهِ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', NULL, 'Those who deny the Book [i.e., the Qur’ān] and that with which We sent Our messengers - they are going to know,', 'Iaitu orang-orang yang mendustakan Al-Quran dan segala yang dibawa oleh Rasul-rasul Kami yang telah Kami utus; maka mereka akan mengetahui kelak.', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 71, 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', 'إِذِ الْأَغْلَالُ فِي أَعْنَاقِهِمْ وَالسَّلَاسِلُ يُسْحَبُونَ', NULL, 'When the shackles are around their necks and the chains; they will be dragged', 'Ketika belenggu dan rantai dipasung di leher mereka, sambil mereka, diseret', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 72, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', 'فِي الْحَمِيمِ ثُمَّ فِي النَّارِ يُسْجَرُونَ', NULL, 'In boiling water; then in the Fire they will be filled [with flame].', 'Ke dalam air panas yang menggelegak; kemudian mereka dibakar dalam api neraka;', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 73, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', NULL, 'Then it will be said to them, "Where is that which you used to associate [with Him in worship]', 'Akhirnya dikatakan kepada mereka: “Mana dia berhala-berhala yang kamu dahulu sekutukan -', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 74, 'مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', 'مِن دُونِ اللَّهِ قَالُوا ضَلُّوا عَنَّا بَل لَّمْ نَكُن نَّدْعُو مِن قَبْلُ شَيْئًا كَذَٰلِكَ يُضِلُّ اللَّهُ الْكَافِرِينَ', NULL, 'Other than Allāh?" They will say, "They have departed from us; rather, we did not used to invoke previously anything." Thus does Allāh put astray the disbelievers.', '“(Dengan menyembahnya atau memujanya) selain Allah?” Mereka menjawab: “Benda-benda itu telah hilang lenyap dari kami, bahkan yang sebenarnya kami dahulu tidak pernah sekutukan sesuatu pun (dengan Allah)”. (Sebagaimana Allah menjadikan mereka sesat), demikian pula Allah menyesatkan orang-orang yang kufur ingkar (menentang maksud ayat-ayatNya).', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 75, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', NULL, '[The angels will say], "That was because you used to exult upon the earth without right and you used to behave insolently.', '(Lalu dikatakan kepada mereka setelah ditimpakan dengan azab seksa): “Balasan buruk yang demikian ini disebabkan kamu dahulu bersukaria di muka bumi dengan cara yang salah (pada hukum Tuhan), dan disebabkan kamu bersenang lenang dan bermegah-megah dengan berleluasa (dalam maksiat).', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 76, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'ادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ', NULL, 'Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."', '“Masukilah pintu-pintu neraka Jahannam kekalah kamu di dalamnya; maka seburuk-buruk tempat bagi orang-orang yang sombong takbur ialah neraka Jahannam”.', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 77, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', 'فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', NULL, 'So be patient, [O Muḥammad]; indeed, the promise of Allāh is truth. And whether We show you some of what We have promised them or We take you in death, it is to Us they will be returned.', 'Maka bersabarlah (wahai Muhammad), sesungguhnya janji Allah (menyeksa musuh-musuhmu itu) adalah benar; oleh itu kiranya Kami perlihatkan kepadamu sebahagian dari azab yang Kami janjikan kepada mereka, ataupun Kami wafatkanmu sebelum itu, (maka tetaplah mereka akan menerima balasan azab) kerana kepada Kamilah mereka akan dikembalikan.', FALSE, NULL, NULL, 475, 24, 190, 411, FALSE, 0, NULL),
(40, 78, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ فَإِذَا جَاءَ أَمْرُ اللَّهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ', NULL, 'And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allāh. So when the command of Allāh comes, it will be concluded [i.e., judged] in truth, and the falsifiers will thereupon lose [all].', 'Dan demi sesungguhnya! Kami telah mengutus beberapa Rasul sebelummu; di antara mereka ada yang Kami ceritakan perihalnya kepadamu, dan ada pula di antaranya yang tidak Kami ceritakan kepada kamu. Dan tidaklah harus bagi seseorang Rasul membawa sesuatu keterangan atau menunjukkan sesuatu mukjizat melainkan dengan izin Allah; (maka janganlah diingkari apa yang dibawa oleh Rasul) kerana apabila datang perintah Allah (menimpakan azab) diputuskan hukum dengan adil; pada saat itu rugilah orang-orang yang berpegang kepada perkara yang salah.', FALSE, NULL, NULL, 476, 24, 190, 411, FALSE, 0, NULL),
(40, 79, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', 'اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَنْعَامَ لِتَرْكَبُوا مِنْهَا وَمِنْهَا تَأْكُلُونَ', NULL, 'It is Allāh who made for you the grazing animals upon which you ride, and some of them you eat.', 'Allah yang menjadikan binatang ternak bagi kamu; sebahagian di antaranya untuk kamu menunggangnya, dan sebahagian lagi untuk kamu makan.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 80, 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'وَلَكُمْ فِيهَا مَنَافِعُ وَلِتَبْلُغُوا عَلَيْهَا حَاجَةً فِي صُدُورِكُمْ وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ', NULL, 'And for you therein are [other] benefits and that you may realize upon them a need which is in your breasts; and upon them and upon ships you are carried.', 'Dan kamu pula beroleh berbagai faedah pada binatang ternak itu, dan supaya kamu dapat memenuhi sesuatu hajat yang ada dalam hati kamu dengan menggunakan binatang itu; dan di atas binatang-binatang ternak itu, serta di atas kapal-kapal, kamu diangkut.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 81, 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 'وَيُرِيكُمْ آيَاتِهِ فَأَيَّ آيَاتِ اللَّهِ تُنكِرُونَ', NULL, 'And He shows you His signs. So which of the signs of Allāh do you deny?', 'Dan Ia memperlihatkan kepada kamu tanda-tanda kebesaranNya dan kekuasaanNya (melalui Rasul-rasulNya dan pada makhluk-makhluk yang dijadikanNya); maka di antara tanda-tanda kesempurnaan Allah, yang mana satu, yang kamu ingkari?', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 82, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كَانُوا أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَآثَارًا فِي الْأَرْضِ فَمَا أَغْنَىٰ عَنْهُم مَّا كَانُوا يَكْسِبُونَ', NULL, 'Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn.', 'Selain dari itu, tidakkah mereka telah berjalan dan mengembara di muka bumi, dengan itu tidakkah mereka memerhatikan bagaimana kesudahan orang-orang yang terdahulu dari mereka (yang telah dibinasakan dengan sebab dosa-dosanya)? Orang-orang itu lebih ramai dari mereka, dan lebih dari mereka tentang kekuatan tenaga dan tentang kesan-kesan usaha pembangunan di muka bumi. Dalam pada itu, apa yang telah diusahakan oleh orang-orang itu, tidak dapat menolongnya sedikitpun.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 83, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'فَلَمَّا جَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ فَرِحُوا بِمَا عِندَهُم مِّنَ الْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'And when their messengers came to them with clear proofs, they [merely] rejoiced in what they had of knowledge, but they were enveloped by what they used to ridicule.', 'Kerana pada masa mereka didatangi oleh Rasul-rasul yang diutus kepada mereka dengan membawa keterangan-keterangan (untuk menyelamatkan mereka, mereka mengejek-ejeknya, dan) mereka bergembira dengan pengetahuan yang ada pada mereka (yang mengenai keduniaan semata-mata); dan dengan yang demikian mereka pun diliputi oleh azab yang mereka ejek-ejek dahulu.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 84, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 'فَلَمَّا رَأَوْا بَأْسَنَا قَالُوا آمَنَّا بِاللَّهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ', NULL, 'And when they saw Our punishment, they said, "We believe in Allāh alone and disbelieve in that which we used to associate with Him."', 'Maka ketika mereka melihat azab Kami, mereka berkata: “Kami beriman kepada Allah semata-mata, dan kami kufur ingkar kepada benda-benda yang dengan sebabnya kami menjadi musyrik”.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(40, 85, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَانُهُمْ لَمَّا رَأَوْا بَأْسَنَا سُنَّتَ اللَّهِ الَّتِي قَدْ خَلَتْ فِي عِبَادِهِ وَخَسِرَ هُنَالِكَ الْكَافِرُونَ', NULL, 'But never did their faith benefit them once they saw Our punishment. [It is] the established way of Allāh which has preceded among His servants. And the disbelievers thereupon lost [all].', 'Maka iman yang mereka katakan semasa melihat azab Kami, tidak berguna lagi kepada mereka; yang demikian adalah menurut “Sunnatullah” (undang-undang peraturan Allah) yang telah berlaku kepada hamba-hambaNya. Dan pada saat itu rugilah orang-orang yang kufur ingkar.', FALSE, NULL, NULL, 476, 24, 190, 412, FALSE, 0, NULL),
(41, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 1, NULL),
(41, 2, 'تَنزِيلٌ مِّنَ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ', 'تنزيل من الرحمن الرحيم', NULL, '[This is] a revelation from the Entirely Merciful, the Especially Merciful -', 'Turunnya Kitab ini dari Allah Yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 4, NULL),
(41, 3, 'كِتَـٰبٌ فُصِّلَتْ ءَايَـٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', 'كتاب فصلت اياته قرانا عربيا لقوم يعلمون', NULL, 'A Book whose verses have been detailed, an Arabic Qur’ān for a people who know,', 'Sebuah Kitab yang dijelaskan ayat-ayatnya satu persatu; iaitu Al-Quran yang diturunkan dalam bahasa Arab bagi faedah orang-orang yang mengambil tahu dan memahami kandungannya.', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 7, NULL),
(41, 4, 'بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'بشيرا ونذيرا فاعرض اكثرهم فهم لا يسمعون', NULL, 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.', 'Ia membawa berita yang mengembirakan (bagi orang-orang yang beriman) dan membawa amaran (kepada orang-orang yang ingkar); dalam pada itu kebanyakan mereka berpaling ingkar (tidak mahu mengetahui dan memahaminya), maka dengan sebab itu mereka tidak menerima dan tidak mematuhinya.', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 7, NULL),
(41, 5, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَـٰمِلُونَ', 'وقالوا قلوبنا في اكنة مما تدعونا اليه وفي اذاننا وقر ومن بيننا وبينك حجاب فاعمل اننا عاملون', NULL, 'And they say, "Our hearts are within coverings [i.e., screened] from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."', 'Dan mereka berkata: “Hati kami dalam tutupan yang berlapis-lapis (menghalang kami) daripada memahami apa yang engkau serukan kami kepadanya, dan pada telinga kami penyumbat (menjadikan kami tidak dapat mendengarnya), serta di antara kami denganmu ada sekatan (yang memisahkan fahaman kita); oleh itu, bekerjalah engkau (untuk ugamamu), sesungguhnya kami juga tetap bekerja (untuk mempertahankan kepercayaan kami)!”', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 17, NULL),
(41, 6, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ ۗ وَوَيْلٌ لِّلْمُشْرِكِينَ', 'قل انما انا بشر مثلكم يوحى الي انما الهكم اله واحد فاستقيموا اليه واستغفروه وويل للمشركين', NULL, 'Say, [O Muḥammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allāh –', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku hanyalah seorang manusia seperti kamu; diwahyukan kepadaku bahawa Tuhan kamu hanyalah Tuhan yang Satu; maka hendaklah kamu tetap teguh di atas jalan yang betul lurus (yang membawa kepada mencapai keredaanNya), serta pohonlah kepadaNya mengampuni (dosa-dosa kamu yang telah lalu). Dan (ingatlah), kecelakaan besar bagi orang-orang yang mempersekutukanNya (dengan sesuatu yang lain),', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 16, NULL),
(41, 7, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ', 'الذين لا يؤتون الزكاة وهم بالاخرة هم كافرون', NULL, 'Those who do not give zakāh, and in the Hereafter they are disbelievers.', '“Iaitu orang-orang yang tidak memberi zakat (untuk membersihkan jiwa dan hartabendanya) dan mereka pula kufur ingkar akan adanya hari akhirat”.', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 8, NULL),
(41, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'ان الذين امنوا وعملوا الصالحات لهم اجر غير ممنون', NULL, 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.', 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal yang soleh, mereka beroleh balasan pahala yang tidak putus-putus.', FALSE, NULL, NULL, 477, 24, 190, 413, FALSE, 9, NULL),
(41, 9, '۞ قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ۚ ذَٰلِكَ رَبُّ ٱلْعَـٰلَمِينَ', 'قل ائنكم لتكفرون بالذي خلق الارض في يومين وتجعلون له اندادا ذلك رب العالمين', NULL, 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."', 'Katakanlah (wahai Muhammad): “Sesungguhnya tidak patut kamu kufur kepada Tuhan yang menciptakan bumi dalam dua masa, dan kamu adakan sekutu-sekutu bagiNya! Yang demikian (sifatNya dan kekuasaanNya) ialah Allah Tuhan sekalian alam,', FALSE, NULL, NULL, 477, 24, 191, 414, FALSE, 14, NULL),
(41, 10, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَـٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ', 'وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها اقواتها في اربعة ايام سواء للسائلين', NULL, 'And He placed on it [i.e., the earth] firmly set mountains over its surface, and He blessed it and determined therein its [creatures''] sustenance in four days without distinction - for [the information of] those who ask.', 'Dan Ia menjadikan di bumi gunung-ganang yang menetapnya (tersergam tinggi) di atasnya, serta Ia melimpahkan berkat padanya, dan Ia menentukan ada padaNya bahan-bahan keperluan hidup penduduknya, sekadar yang menyamai hajat yang diminta dan dikehendaki oleh keadaan mereka; (semuanya itu berlaku) dalam empat masa.', FALSE, NULL, NULL, 477, 24, 191, 414, FALSE, 15, NULL),
(41, 11, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ', 'ثم استوى الى السماء وهي دخان فقال لها وللارض ائتيا طوعا او كرها قالتا اتينا طائعين', NULL, 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."', 'Kemudian Ia menunjukkan kehendakNya ke arah (bahan-bahan) langit sedang langit itu masih berupa asap; lalu Ia berfirman kepadanya dan kepada bumi: “Turutlah kamu berdua akan perintahKu, sama ada dengan sukarela atau dengan paksa!” Keduanya menjawab: “Kami berdua sedia menurut - patuh dengan sukarela”', FALSE, NULL, NULL, 477, 24, 191, 414, FALSE, 16, NULL),
(41, 12, 'فَقَضَىٰهُنَّ سَبْعَ سَمَـٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا ۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَحِفْظًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'فقضاهن سبع سماوات في يومين واوحى في كل سماء امرها وزينا السماء الدنيا بمصابيح وحفظا ذلك تقدير العزيز العليم', NULL, 'And He completed them as seven heavens within two days and inspired [i.e., made known] in each heaven its command. And We adorned the nearest heaven with lamps [i.e., stars, for beauty] and as protection. That is the determination of the Exalted in Might, the Knowing.', 'Lalu Ia menjadikannya tujuh langit, dalam dua masa; dan Ia memberitahu kepada tiap-tiap langit akan urusan dan keperluannya masing-masing. Dan Kami hiasi langit yang dekat (pada pandangan mata penduduk bumi) dengan bintang-bintang yang bersinar cemerlang serta memelihara langit itu dengan sebaik-baiknya. Demikianlah ketentuan Allah Yang Maha Kuasa, lagi Maha Mengetahui.', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 19, NULL),
(41, 13, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَـٰعِقَةً مِّثْلَ صَـٰعِقَةِ عَادٍ وَثَمُودَ', 'فان اعرضوا فقل انذرتكم صاعقة مثل صاعقة عاد وثمود', NULL, 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] ʿAad and Thamūd.', 'Oleh itu, kalau mereka (yang musyrik) berpaling (daripada mengesakan Allah dan menurut jalan yang lurus), maka katakanlah (wahai Muhammad): “Aku memberi amaran kepada kamu dengan (azab yang dahsyat, iaitu) petir, seperti petir yang telah menyambar kaum Aad dan kaum Thamud!”', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 9, NULL),
(41, 14, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَـٰفِرُونَ', 'اذ جاءتهم الرسل من بين ايديهم ومن خلفهم الا تعبدوا الا الله قالوا لو شاء ربنا لانزل ملائكة فانا بما ارسلتم به كافرون', NULL, '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allāh." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."', '(Mereka ditimpa azab itu) kerana semasa mereka didatangi Rasul-rasul (memberikan berbagai penjelasan) mengenai keadaan hidup mereka di dunia dan di akhirat (sambil melarang mereka): “Janganlah kamu menyembah melainkan Allah”, mereka menjawab: “Jika Tuhan kami hendak (mengutus Rasul-rasul) tentulah Ia akan menurunkan malaikat; oleh itu sesungguhnya kami kufur ingkar akan apa yang (kamu katakan): kamu diutus membawanya!”', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 23, NULL),
(41, 15, 'فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً ۖ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً ۖ وَكَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ', 'فاما عاد فاستكبروا في الارض بغير الحق وقالوا من اشد منا قوة اولم يروا ان الله الذي خلقهم هو اشد منهم قوة وكانوا باياتنا يجحدون', NULL, 'As for ʿAad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allāh who created them was greater than them in strength? But they were rejecting Our signs.', 'Adapun kaum Aad, maka mereka berlaku sombong takbur di muka bumi dengan tiada sebarang alasan yang benar, serta berkata: “Siapakah yang lebih kuat dari kami?” Dan (mengapa mereka bersikap demikian?) Tidakkah mereka memerhatikan bahawa Allah yang menciptakan mereka (dari tiada kepada ada) adalah lebih besar kekuatanNya dari mereka? Dan sememangnya mereka sengaja mengingkari tanda-tanda kekuatan Kami (sedang mereka sedia mengetahuinya).', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 25, NULL),
(41, 16, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَخْزَىٰ ۖ وَهُمْ لَا يُنصَرُونَ', 'فارسلنا عليهم ريحا صرصرا في ايام نحسات لنذيقهم عذاب الخزي في الحياة الدنيا ولعذاب الاخرة اخزى وهم لا ينصرون', NULL, 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.', 'Lalu Kami hantarkan kepada mereka angin ribut yang kencang dalam beberapa hari yang nahas malang, kerana Kami hendak merasakan mereka azab seksa yang menghina dalam kehidupan dunia; dan sesungguhnya azab seksa hari akhirat lebih besar kehinaannya; sedang mereka tidak diberikan pertolongan (menghindarkan azab itu).', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 19, NULL),
(41, 17, 'وَأَمَّا ثَمُودُ فَهَدَيْنَـٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَـٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', 'واما ثمود فهديناهم فاستحبوا العمى على الهدى فاخذتهم صاعقة العذاب الهون بما كانوا يكسبون', NULL, 'And as for Thamūd, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.', 'Adapun kaum Thamud, maka Kami beri petunjuk kepadanya, lalu mereka mengutamakan kesesatan dari hidayah petunjuk; mereka pun disambar oleh petir azab yang menghina dengan sebab apa yang mereka telah lakukan.', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 14, NULL),
(41, 18, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'ونجينا الذين امنوا وكانوا يتقون', NULL, 'And We saved those who believed and used to fear Allāh.', 'Dan Kami selamatkan orang-orang yang beriman serta mereka tetap bertaqwa.', FALSE, NULL, NULL, 478, 24, 191, 414, FALSE, 5, NULL),
(41, 19, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', 'ويوم يحشر اعداء الله الى النار فهم يوزعون', NULL, 'And [mention, O Muḥammad], the Day when the enemies of Allāh will be gathered to the Fire while they are [driven], assembled in rows,', 'Dan (ingatlah) hari dihimpun musuh-musuh Allah untuk dibawa ke neraka, lalu mereka dijaga serta diatur keadaan dan perjalanannya masing-masing.', FALSE, NULL, NULL, 478, 24, 191, 415, FALSE, 8, NULL),
(41, 20, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَـٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'حتى اذا ما جاءوها شهد عليهم سمعهم وابصارهم وجلودهم بما كانوا يعملون', NULL, 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.', 'Sehingga apabila mereka sampai ke neraka, (maka) pendengaran dan penglihatan serta kulit-kulit badan mereka menjadi saksi terhadap mereka, mengenai apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 478, 24, 191, 415, FALSE, 12, NULL),
(41, 21, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', 'وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوا أَنطَقَنَا اللَّهُ الَّذِي أَنطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allāh, who has made everything speak; and He created you the first time, and to Him you are returned.', 'Dan (setelah berlaku yang demikian), berkatalah mereka kepada kulit-kulit badan mereka: “Mengapa kamu menjadi saksi terhadap kami?” Kulit-kulit badan mereka menjawab: “Allah yang berkuasa menjadikan tiap-tiap sesuatu pandai berkata-kata - telah menjadikan kami dapat berkata-kata; dan Dia lah yang menciptakan kamu pada mulanya, dan kepadaNyalah kamu dikembalikan (untuk menerima balasan).', FALSE, NULL, NULL, 479, 24, 191, 415, FALSE, 0, NULL),
(41, 22, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ اللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', NULL, 'And you were not covering [i.e., protecting] yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allāh does not know much of what you do.', '“Dan semasa kamu berselindung (ketika melakukan dosa di dunia dahulu) bukanlah kerana kamu bimbangkan pendengaran dan penglihatan serta kulit-kulit badan kamu menjadi saksi terhadap perbuatan-perbuatan kamu yang berdosa itu, akan tetapi kerana kamu menyangka bahawa Allah tidak mengetahui kebanyakan dosa yang kamu lakukan (secara bersembunyi itu).', FALSE, NULL, NULL, 479, 24, 191, 415, FALSE, 0, NULL),
(41, 23, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', 'وَذَٰلِكُمْ ظَنُّكُمُ الَّذِي ظَنَنتُم بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُم مِّنَ الْخَاسِرِينَ', NULL, 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."', '“Dan sangkaan kamu yang demikian, yang kamu sangka terhadap Tuhan kamu, itulah yang telah membinasakan kamu; (dengan sangkaan kamu yang salah itu) maka menjadilah kamu dari orang-orang yang rugi!”', FALSE, NULL, NULL, 479, 24, 191, 415, FALSE, 0, NULL),
(41, 24, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', 'فَإِن يَصْبِرُوا فَالنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا فَمَا هُم مِّنَ الْمُعْتَبِينَ', NULL, 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allāh], they will not be of those who are allowed to appease.', 'Oleh itu, sama ada mereka bersabar menderita azab atau sebaliknya (maka sama sahaja) kerana nerakalah tempat tinggal mereka; dan jika mereka memohon peluang untuk mendapat keredaan Allah, maka mereka bukanlah lagi dari orang-orang yang diterima permohonannya.', FALSE, NULL, NULL, 479, 24, 191, 415, FALSE, 0, NULL),
(41, 25, 'وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'وَقَيَّضْنَا لَهُمْ قُرَنَاءَ فَزَيَّنُوا لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ الْقَوْلُ فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ الْجِنِّ وَالْإِنسِ إِنَّهُمْ كَانُوا خَاسِرِينَ', NULL, 'And We appointed for them companions who made attractive to them what was before them and what was behind them [of sin], and the word [i.e., decree] has come into effect upon them among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.', 'Dan Kami adakan untuk mereka teman-teman rapat (dari jin dan manusia), lalu teman-teman itu memperhiaskan kepada mereka (fahaman-fahaman sesat) mengenai perkara-perkara dunia yang ada di hadapan mereka, serta perkara-perkara akhirat yang ada di belakang mereka; dan (dengan sebab itu) tetaplah hukuman (azab) atas mereka bersama-sama dengan umat umat (yang sesat) dari jin dan manusia yang terdahulu daripada mereka. Sesungguhnya mereka semuanya adalah golongan yang rugi (bawaan hidupnya).', FALSE, NULL, NULL, 479, 24, 192, 415, FALSE, 0, NULL),
(41, 26, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', 'وَقَالَ الَّذِينَ كَفَرُوا لَا تَسْمَعُوا لِهَٰذَا الْقُرْآنِ وَالْغَوْا فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', NULL, 'And those who disbelieve say, "Do not listen to this Qur’ān and speak noisily during [the recitation of] it that perhaps you will overcome."', 'Dan orang-orang yang kafir berkata: “Janganlah kamu mendengar Al-Quran ini dan tentanglah dia (dengan nyayian-nyanyian dan jeritan-jeritan riuh rendah serta tepuk sorak), supaya kamu berjaya (mengganggu bacaan atau menenggelamkan suara pembacanya)!”', FALSE, NULL, NULL, 479, 24, 192, 416, FALSE, 0, NULL),
(41, 27, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'فَلَنُذِيقَنَّ الَّذِينَ كَفَرُوا عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ الَّذِي كَانُوا يَعْمَلُونَ', NULL, 'But We will surely cause those who disbelieve to taste a severe punishment, and We will surely recompense them for the worst of what they had been doing.', 'Maka, demi sesungguhnya! Kami akan merasakan orang-orang yang kafir itu azab seksa yang seberat-beratnya, dan Kami akan membalas mereka dengan seburuk-buruk balasan bagi apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 479, 24, 192, 416, FALSE, 0, NULL),
(41, 28, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'ذَٰلِكَ جَزَاءُ أَعْدَاءِ اللَّهِ النَّارُ لَهُمْ فِيهَا دَارُ الْخُلْدِ جَزَاءً بِمَا كَانُوا بِآيَاتِنَا يَجْحَدُونَ', NULL, 'That is the recompense of the enemies of Allāh - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting.', 'Demikianlah keadaannya balasan musuh-musuh Allah iaitu neraka; disediakan untuk mereka tempat tinggal yang kekal didalamnya, sebagai balasan bagi perbuatan mereka sentiasa mengingkari ayat-ayat Kami.', FALSE, NULL, NULL, 479, 24, 192, 416, FALSE, 0, NULL),
(41, 29, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 'وَقَالَ الَّذِينَ كَفَرُوا رَبَّنَا أَرِنَا اللَّذَيْنِ أَضَلَّانَا مِنَ الْجِنِّ وَالْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ الْأَسْفَلِينَ', NULL, 'And those who disbelieved will [then] say, "Our Lord, show us those who misled us of the jinn and men [so] we may put them under our feet that they will be among the lowest."', 'Dan orang-orang yang kafir berkata: “Wahai Tuhan kami! Perlihatkanlah kepada kami dua golongan yang telah menyesatkan kami dari jin dan manusia, untuk kami meletakkan mereka di bawah tapak kaki kami, supaya mereka menjadi golongan yang terkebawah dalam kehinaan”.', FALSE, NULL, NULL, 479, 24, 192, 416, FALSE, 0, NULL),
(41, 30, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ أَلَّا تَخَافُوا وَلَا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنتُمْ تُوعَدُونَ', NULL, 'Indeed, those who have said, "Our Lord is Allāh" and then remained on a right course - the angels will descend upon them, [saying], "Do not fear and do not grieve but receive good tidings of Paradise, which you were promised.', 'Sesungguhnya orang-orang yang menegaskan keyakinannya dengan berkata: “Tuhan kami ialah Allah”, kemudian mereka tetap teguh di atas jalan yang betul, akan turunlah malaikat kepada mereka dari semasa ke semasa (dengan memberi ilham): “Janganlah kamu bimbang (dari berlakunya kejadian yang tidak baik terhadap kamu) dan janganlah kamu berdukacita, dan terimalah berita gembira bahawa kamu akan beroleh syurga yang telah dijanjikan kepada kamu.', FALSE, NULL, NULL, 480, 24, 192, 416, FALSE, 0, NULL),
(41, 31, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'نَحْنُ أَوْلِيَاؤُكُمْ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', NULL, 'We [angels] were your allies in worldly life and [are so] in the Hereafter. And you will have therein whatever your souls desire, and you will have therein whatever you request [or wish]', '“Kamilah penolong-penolong kamu dalam kehidupan dunia dan pada hari akhirat; dan kamu akan beroleh - pada hari akhirat - apa yang diingini oleh nafsu kamu, serta kamu akan beroleh - pada hari itu - apa yang kamu cita-citakan mendapatnya.', FALSE, NULL, NULL, 480, 24, 192, 416, FALSE, 0, NULL),
(41, 32, 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', NULL, 'As accommodation from a [Lord who is] Forgiving and Merciful."', '“(Pemberian-pemberian yang serba mewah itu) sebagai sambutan penghormatan dari Allah Yang Maha Pengampun, lagi Maha Mengasihani!”', FALSE, NULL, NULL, 480, 24, 192, 416, FALSE, 0, NULL),
(41, 33, 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ', NULL, 'And who is better in speech than one who invites to Allāh and does righteousness and says, "Indeed, I am of the Muslims."', 'Dan tidak ada yang lebih baik perkataannya daripada orang yang menyeru kepada (mengesakan dan mematuhi perintah) Allah, serta ia sendiri mengerjakan amal yang soleh, sambil berkata: “Sesungguhnya aku adalah dari orang-orang Islam (yang berserah bulat-bulat kepada Allah)!”', FALSE, NULL, NULL, 480, 24, 192, 417, FALSE, 0, NULL),
(41, 34, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', 'وَلَا تَسْتَوِي الْحَسَنَةُ وَلَا السَّيِّئَةُ ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ', NULL, 'And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon, the one whom between you and him is enmity [will become] as though he was a devoted friend.', 'Dan tidaklah sama (kesannya dan hukumnya) perbuatan yang baik dan perbuatan yang jahat. Tolaklah (kejahatan yang ditujukan kepadamu) dengan cara yang lebih baik; apabila engkau berlaku demikian maka orang yang menaruh rasa permusuhan terhadapmu, dengan serta merta akan menjadi seolah-olah seorang sahabat karib.', FALSE, NULL, NULL, 480, 24, 192, 417, FALSE, 0, NULL),
(41, 35, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ', 'وَمَا يُلَقَّاهَا إِلَّا الَّذِينَ صَبَرُوا وَمَا يُلَقَّاهَا إِلَّا ذُو حَظٍّ عَظِيمٍ', NULL, 'But none is granted it except those who are patient, and none is granted it except one having a great portion [of good].', 'Dan sifat yang terpuji ini tidak dapat diterima dan diamalkan melainkan oleh orang-orang yang bersikap sabar, dan tidak juga dapat diterima dan diamalkan melainkan oleh orang yang mempunyai bahagian yang besar dari kebahagiaan dunia dan akhirat.', FALSE, NULL, NULL, 480, 24, 192, 417, FALSE, 0, NULL),
(41, 36, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ', NULL, 'And if there comes to you from Satan an evil suggestion, then seek refuge in Allāh. Indeed, He is the Hearing, the Knowing.', 'Dan jika engkau dihasut oleh sesuatu hasutan dari Syaitan, maka hendaklah engkau meminta perlindungan kepada Allah. Sesungguhnya Dia lah yang Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 480, 24, 192, 417, FALSE, 0, NULL),
(41, 37, 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ لَا تَسْجُدُوا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوا لِلَّهِ الَّذِي خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', NULL, 'And of His signs are the night and day and the sun and moon. Do not prostrate to the sun or to the moon, but prostrate to Allāh, who created them, if it should be Him that you worship.', 'Dan di antara tanda-tanda kekuasaanNya ialah malam dan siang, serta matahari dan bulan. Janganlah kamu sujud kepada matahari dan janganlah pula sujud kepada bulan, dan sebaliknya hendaklah kamu sujud kepada Allah yang menciptakannya, kalau betulah kamu hanya beribadat kepada Allah.', FALSE, NULL, NULL, 480, 24, 192, 417, FALSE, 0, NULL),
(41, 38, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ', 'فَإِنِ اسْتَكْبَرُوا فَالَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُ بِاللَّيْلِ وَالنَّهَارِ وَهُمْ لَا يَسْأَمُونَ', NULL, 'But if they are arrogant - then those who are near your Lord [i.e., the angels] exalt Him by night and by day, and they do not become weary.', 'Oleh itu, kalau mereka tetap ingkar dengan angkuhnya (daripada mematuhi perintah Allah dan mengesakanNya, maka tidaklah menjejaskan kebesaran Tuhan), kerana malaikat-malaikat yang ada di sisi Tuhanmu tetap bertasbih kepadaNya pada waktu malam dan siang, dengan tidak mereka merasa jemu.', FALSE, NULL, NULL, 480, 24, 192, 417, TRUE, 0, NULL),
(41, 39, 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وَمِنْ آيَاتِهِ أَنَّكَ تَرَى الْأَرْضَ خَاشِعَةً فَإِذَا أَنزَلْنَا عَلَيْهَا الْمَاءَ اهْتَزَّتْ وَرَبَتْ إِنَّ الَّذِي أَحْيَاهَا لَمُحْيِي الْمَوْتَىٰ إِنَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'And of His signs is that you see the earth stilled, but when We send down upon it rain, it quivers and grows. Indeed, He who has given it life is the Giver of Life to the dead. Indeed, He is over all things competent.', 'Dan di antara tanda-tanda kekuasaanNya, engkau melihat bumi kosong sepi (dalam keadaan kering dan tandus), maka apabila Kami menurunkan hujan menimpanya, bergeraklah tanahnya serta suburlah tanamannya. Sesungguhnya Allah yang menghidupkannya sudah tentu berkuasa menghidupkan makhluk-makhluk yang telah mati; sesungguhnya Ia Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 40, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَٰمَةِ ٱعْمَلُوا۟ مَا شِئْتُمْ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 'إِنَّ الَّذِينَ يُلْحِدُونَ فِي آيَاتِنَا لَا يَخْفَوْنَ عَلَيْنَا أَفَمَن يُلْقَىٰ فِي النَّارِ خَيْرٌ أَم مَّن يَأْتِي آمِنًا يَوْمَ الْقِيَامَةِ اعْمَلُوا مَا شِئْتُمْ إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', NULL, 'Indeed, those who inject deviation into Our verses are not concealed from Us. So, is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do whatever you will; indeed, He is Seeing of what you do.', 'Sebenarnya orang-orang yang menyeleweng dari jalan yang benar mengenai ayat-ayat keterangan Kami, tidak terselindung keadaan mereka dari (pengetahuan) Kami. (Kalau sudah demikian), maka adakah orang yang dihumbankan ke dalam neraka lebih baik, atau orang yang datang dalam keadaan aman dan selamat pada hari kiamat? (Katakanlah kepada orang-orang yang menyeleweng itu): “Buatlah apa yang kamu suka, sesungguhnya Allah Maha Melihat akan apa yang kamu lakukan (dan akan membalasnya)”.', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 41, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ', 'إِنَّ الَّذِينَ كَفَرُوا بِالذِّكْرِ لَمَّا جَاءَهُمْ وَإِنَّهُ لَكِتَابٌ عَزِيزٌ', NULL, 'Indeed, those who disbelieve in the message [i.e., the Qur’ān] after it has come to them... And indeed, it is a mighty Book.', 'Sesungguhnya orang-orang yang kufur ingkar terhadap Al-Quran ketika sampainya kepada mereka, (akan ditimpa azab seksa yang tidak terperi); sedang Al-Quran itu, demi sesungguhnya sebuah Kitab Suci yang tidak dapat ditandingi,', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 42, 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', 'لَّا يَأْتِيهِ الْبَاطِلُ مِن بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', NULL, 'Falsehood cannot approach it from before it or from behind it; [it is] a revelation from a [Lord who is] Wise and Praiseworthy.', 'Yang tidak dapat didatangi sebarang kepalsuan dari mana-mana arah dan seginya; ia diturunkan dari Tuhan Yang Maha Bijaksana, lagi Maha Terpuji.', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 43, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', NULL, 'Nothing is said to you, [O Muḥammad], except what was already said to the messengers before you. Indeed, your Lord is a possessor of forgiveness and a possessor of painful penalty.', 'Apa yang dikatakan kepadamu (wahai Muhammad, dari celaan-celaan golongan yang ingkar, tidak lain) hanyalah seperti yang pernah dikatakan kepada Rasul-rasul yang terdahuhu daripadamu. (Oleh itu bersabarlah dengan cekal hati menghadapinya), sesungguhnya Tuhanmu berkuasa penuh melimpahkan keampunanNya (kepada orang-orang yang taat), dan berkuasa penuh menimpakan azab seksa yang tidak terperi sakitnya (kepada orang-orang yang ingkar).', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 44, 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ', 'وَلَوْ جَعَلْنَاهُ قُرْآنًا أَعْجَمِيًّا لَّقَالُوا لَوْلَا فُصِّلَتْ آيَاتُهُ أَأَعْجَمِيٌّ وَعَرَبِيٌّ قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ وَالَّذِينَ لَا يُؤْمِنُونَ فِي آذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُولَٰئِكَ يُنَادَوْنَ مِن مَّكَانٍ بَعِيدٍ', NULL, 'And if We had made it a foreign [i.e., non-Arabic] Qur’ān, they would have said, "Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?" Say, "It is, for those who believe, a guidance and cure." And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place.', 'Dan kalaulah Al-Quran itu Kami jadikan (bacaan) dalam bahasa asing, tentulah mereka akan berkata: “Mengapa tidak dijelaskan ayat-ayatnya (dalam bahasa yang kami fahami)? Patutkah Kitab itu berbahasa asing sedang Rasul yang membawanya berbangsa Arab?” Katakanlah (wahai Muhammad): “Al-Quran itu, menjadi (cahaya) petunjuk serta penawar bagi orang-orang yang beriman; dan sebaliknya orang-orang yang tidak beriman, (AL-Quran itu) menjadi sebagai satu penyakit yang menyumbat telinga mereka (bukan penawar); dan ia juga merupakan gelap-gelita yang menimpa (pandangan) mereka (bukan cahaya yang menerangi). Mereka itu - (dengan perbuatan melarikan diri dari ajaran Al-Quran, tidak ubahnya seperti) orang-orang yang diseru dari tempat yang jauh (masakan mereka dapat mendengar dengan betul atau melihat dengan nyata)”.', FALSE, NULL, NULL, 481, 24, 192, 417, FALSE, 0, NULL),
(41, 45, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 'وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ وَإِنَّهُمْ لَفِي شَكٍّ مِّنْهُ مُرِيبٍ', NULL, 'And We had already given Moses the Scripture, but it came under disagreement. And if not for a word [i.e., decree] that preceded from your Lord, it would have been concluded between them. And indeed they are, concerning it [i.e., the Qur’ān], in disquieting doubt.', 'Dan (janganlah engkau merasa kecewa wahai Muhammad tentang keingkaran kaummu, kerana) demi sesungguhnya! Kami telah memberi kepada Nabi Musa Kitab Taurat, lalu berlaku pertentangan mengenainya. Dan kalaulah tidak kerana telah terdahulu kalimah ketetapan dari Tuhanmu (untuk menangguhkan hukuman hingga ke suatu masa yang tertentu), tentulah dijatuhkan hukuman azab dengan serta merta kepada mereka. Dan sesungguhnya mereka (kaummu) masih menaruh syak yang meragukan tentang (kebenaran Al-Quran) itu.', FALSE, NULL, NULL, 481, 24, 192, 418, FALSE, 0, NULL),
(41, 46, 'مَّنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'مَّنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّامٍ لِّلْعَبِيدِ', NULL, 'Whoever does righteousness - it is for his [own] soul; and whoever does evil [does so] against it. And your Lord is not ever unjust to [His] servants.', 'Sesiapa yang mengerjakan amal soleh maka faedahnya akan terpulang kepada dirinya sendiri, dan sesiapa yang berbuat kejahatan maka bahayanya akan menimpa dirinya sendiri; dan Tuhanmu tidak sekali-kali berlaku zalim kepada hamba-hambaNya.', FALSE, NULL, NULL, 481, 24, 192, 418, FALSE, 0, NULL),
(41, 47, 'إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍ', 'إِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَاتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَائِي قَالُوا آذَنَّاكَ مَا مِنَّا مِن شَهِيدٍ', NULL, 'To Him [alone] is attributed knowledge of the Hour. And fruits emerge not from their coverings nor does a female conceive or give birth except with His knowledge. And the Day He will call to them, "Where are My ''partners''?" they will say, "We announce to You that there is [no longer] among us any witness [to that]."', 'Kepada (ilmu pengetahuan) Allah jua lah kembalinya soal mengetahui masa datangnya hari kiamat; dan (demikianlah tiap-tiap apa yang akan berlaku, kerana) sebiji buah (umpamanya) tidak akan keluar dari kelopaknya, dan seorang ibu tidak akan mengandung dan tidak akan melahirkan anak, melainkan (pada masa dan keadaan yang betul tepat) dengan pengetahuan Allah. Dan pada hari Tuhan menyeru mereka (yang musyrik, dengan bertanya kepada mereka): “Mana dia makhluk-makhluk yang kamu sifatkan menjadi sekutu-sekutuKu?” Mereka menjawab: “Kami mengakui kepadaMu (wahai Tuhan kami), bahawa tidak ada di antara kami seorang pun yang mahu menjadi saksi (kerana anggapan kami dahulu telah nyata salahnya)!”', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 48, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ', 'وَضَلَّ عَنْهُم مَّا كَانُوا يَدْعُونَ مِن قَبْلُ وَظَنُّوا مَا لَهُم مِّن مَّحِيصٍ', NULL, 'And lost from them will be those they were invoking before, and they will be certain that they have no place of escape.', 'Dan (pada saat itu) hilang lenyaplah dari mereka apa yang mereka sembah dahulu (yang diharapkan pertolongannya), dan yakinlah mereka bahawa tidak ada sebarang jalan untuk mereka melepaskan diri (dari azab seksa).', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 49, 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ', 'لَّا يَسْأَمُ الْإِنسَانُ مِن دُعَاءِ الْخَيْرِ وَإِن مَّسَّهُ الشَّرُّ فَيَئُوسٌ قَنُوطٌ', NULL, 'Man is not weary of supplication for good [things], but if evil touches him, he is hopeless and despairing.', 'Manusia tidak jemu-jemu memohon kebaikan. Dan kalau ia ditimpa kesusahan maka menjadilah ia seorang yang sangat berputus asa, lagi sangat nyata kesan putus harapnya (dari rahmat pertolongan Allah).', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 50, 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', 'وَلَئِنْ أَذَقْنَاهُ رَحْمَةً مِّنَّا مِن بَعْدِ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِي وَمَا أَظُنُّ السَّاعَةَ قَائِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّي إِنَّ لِي عِندَهُ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ الَّذِينَ كَفَرُوا بِمَا عَمِلُوا وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', NULL, 'And if We let him taste mercy from Us after an adversity which has touched him, he will surely say, "This is [due] to me, and I do not think the Hour will occur; and [even] if I should be returned to my Lord, indeed, for me there will be with Him the best." But We will surely inform those who disbelieved about what they did, and We will surely make them taste a massive punishment.', 'Dan demi sesungguhnya! Jika Kami beri dia merasai sesuatu rahmat dari Kami sesudah ia ditimpa sesuatu kesusahan, berkatalah ia (dengan sikap tidak bersyukur): “Ini ialah hakku (hasil usahaku semata-mata), dan aku tidak fikir bahawa hari kiamat akan berlaku; dan kalaulah aku dikembalikan kepada Tuhanku (sekalipun), sudah tentu aku aKan beroleh kebaikan di sisiNya (seperti kesenanganku sekarang ini)!” Maka demi sesungguhnya! Kami akan memberi tahu kepada orang-orang yang kufur ingkar itu akan keburukan apa yang mereka telah kerjakan, dan Kami akan beri mereka merasai azab seksa yang seberat-beratnya.', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 51, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ', 'وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَىٰ بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ فَذُو دُعَاءٍ عَرِيضٍ', NULL, 'And when We bestow favor upon man, he turns away and distances himself; but when evil touches him, then he is full of extensive supplication.', 'Dan apabila Kami kurniakan nikmat kepada manusia, berpalinglah dia serta menjauhkan diri (dari bersyukur); dan apabila ia ditimpa kesusahan, maka ia berdoa merayu dengan panjang lebar.', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 52, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ', 'قُلْ أَرَأَيْتُمْ إِن كَانَ مِنْ عِندِ اللَّهِ ثُمَّ كَفَرْتُم بِهِ مَنْ أَضَلُّ مِمَّنْ هُوَ فِي شِقَاقٍ بَعِيدٍ', NULL, 'Say, "Have you considered: if it [i.e., the Qur’ān] is from Allāh and you disbelieved in it, who would be more astray than one who is in extreme dissension?"', 'Katakanlah (wahai Muhammad): “Sudahkah nampak baiknya keadaan kamu jika Al-Quran ini (yang datangnya) dari Allah kemudian kamu mengingkarinya? Siapakah yang lebih sesat daripada orang yang tetap berada dalam perbalahan dan pertentangan, yang menyimpang jauh dari kebenaran?”', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 53, 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ', NULL, 'We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth. But is it not sufficient concerning your Lord that He is, over all things, a Witness?', 'Kami akan perlihatkan kepada mereka tanda-tanda kekuasaan Kami di merata-rata tempat (dalam alam yang terbentang luas ini) dan pada diri mereka sendiri, sehingga ternyata jelas kepada mereka bahawa Al-Quran adalah benar. Belumkah ternyata kepada mereka kebenaran itu dan belumkah cukup (bagi mereka) bahawa Tuhanmu mengetahui dan menyaksikan tiap-tiap sesuatu?', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(41, 54, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ', 'أَلَا إِنَّهُمْ فِي مِرْيَةٍ مِّن لِّقَاءِ رَبِّهِمْ أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُّحِيطٌ', NULL, 'Unquestionably, they are in doubt about the meeting with their Lord. Unquestionably He is, of all things, encompassing.', 'Ingatlah! Sesungguhnya mereka (yang kufur ingkar) sentiasa berada di dalam keadaan syak - ragu-ragu tentang pertemuan dengan Tuhan mereka. Ingatlah! Sesungguhnya Allah Maha Meliputi pengetahuanNya akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 482, 25, 193, 418, FALSE, 0, NULL),
(42, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 1, NULL),
(42, 2, 'عٓسٓقٓ', 'عسق', NULL, 'ʿAyn, Seen, Qāf.', 'Ain, Siin, Qaaf.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 1, NULL),
(42, 3, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'كذلك يوحي اليك والى الذين من قبلك الله العزيز الحكيم', NULL, 'Thus has He revealed to you, [O Muḥammad], and to those before you - Allāh, the Exalted in Might, the Wise.', 'Sebagaimana yang terkandung dalam surah ini dan surah-surah yang lain - diwahyukan kepadamu (wahai Muhammad) dan kepada Rasul-rasul yang terdahulu daripadamu, oleh Allah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 10, NULL),
(42, 4, 'لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'له ما في السماوات وما في الارض وهو العلي العظيم', NULL, 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.', 'Dia lah yang mempunyai dan menguasai segala yang ada di langit dan yang ada di bumi; dan Dia lah Yang Tertinggi keadaanNya, lagi Maha Besar (kekuasaanNya).', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 10, NULL),
(42, 5, 'تَكَادُ ٱلسَّمَـٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ ۚ وَٱلْمَلَـٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ ۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'تكاد السماوات يتفطرن من فوقهن والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الارض الا ان الله هو الغفور الرحيم', NULL, 'The heavens almost break from above them, and the angels exalt [Allāh] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allāh who is the Forgiving, the Merciful.', 'Alam langit nyaris-nyaris pecah dari sebelah atasnya (kerana ngeri dan takutnya kepada kemurkaan Allah terhadap penduduk bumi yang lupakan kebesaran Allah sehingga menyeleweng dari jalan yang benar); dan malaikat bertasbih dengan memuji Tuhannya serta memohon ampun bagi makhluk-makhluk yang ada di bumi. Ingatlah! Sesungguhnya Allah, Dia lah Yang Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 19, NULL),
(42, 6, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'والذين اتخذوا من دونه اولياء الله حفيظ عليهم وما انت عليهم بوكيل', NULL, 'And those who take as allies other than Him - Allāh is [yet] Guardian over them; and you, [O Muḥammad], are not over them a manager -', 'Dan (sebaliknya) orang-orang yang menjadikan sesuatu yang lain dari Allah sebagai pelindung (yang disembah dan diharapkan pertolongannya), Allah sentiasa mengawasi tingkah laku mereka (serta akan membalasnya); dan engkau (wahai Muhammad hanyalah penyampai) bukanlah menjadi wakil yang menguasai soal (bawaan dan amalan) mereka.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 12, NULL),
(42, 7, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ ۚ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ', 'وكذلك اوحينا اليك قرانا عربيا لتنذر ام القرى ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنة وفريق في السعير', NULL, 'And thus We have revealed to you an Arabic Qur’ān that you may warn the Mother of Cities [i.e., Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.', 'Dan sebagaimana Kami tetapkan engkau hanya penyampai, Kami wahyukan kepadamu Al-Quran dalam bahasa Arab, supaya engkau memberi peringatan dan amaran kepada (penduduk) “Ummul-Qura” dan sekalian penduduk dunia di sekelilingnya, serta memberi peringatan dan amaran mengenai hari perhimpunan (hari kiamat) - yang tidak ada syak tentang masa datangnya; (pada hari itu) sepuak masuk Syurga dan sepuak lagi masuk neraka.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 22, NULL),
(42, 8, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ', 'ولو شاء الله لجعلهم امة واحدة ولكن يدخل من يشاء في رحمته والظالمون ما لهم من ولي ولا نصير', NULL, 'And if Allāh willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.', 'Dan jika Allah menghendaki, tentulah Ia menjadikan mereka satu umat (yang bersatu dalam ugama Allah yang satu); akan tetapi Allah (tidak merancang yang demikian bahkan Ia akan) memasukkan sesiapa yang dikehendakiNya ke dalam rahmatNya (menurut peraturan yang telah ditetapkan); dan orang-orang yang zalim tidak ada baginya sesiapapun yang dapat memberikan perlindungan dan pertolongan.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 19, NULL),
(42, 9, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۖ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ام اتخذوا من دونه اولياء فالله هو الولي وهو يحيي الموتى وهو على كل شيء قدير', NULL, 'Or have they taken protectors [or allies] besides Him? But Allāh - He is the Protector, and He gives life to the dead, and He is over all things competent.', 'Tidaklah patut mereka menjadikan sesuatu yang lain dari Allah sebagai pelindung-pelindung (yang disembah dan dipuja) kerana Allah jualah Pelindung yang sebenar-benarnya, dan Dia lah yang menghidupkan makhluk-makhluk yang mati. Dan (ingatlah), Ia Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 483, 25, 193, 419, FALSE, 16, NULL),
(42, 10, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 'وما اختلفتم فيه من شيء فحكمه الى الله ذلكم الله ربي عليه توكلت واليه انيب', NULL, 'And in anything over which you disagree - its ruling is [to be referred] to Allāh. [Say], "That is Allāh, my Lord; upon Him I have relied, and to Him I turn back."', 'Dan (katakanlah wahai Muhammad kepada pengikut-pengikutmu): “Apa jua perkara ugama yang kamu berselisihan padanya maka hukum pemutusnya terserah kepada Allah; Hakim yang demikian kekuasaanNya ialah Allah Tuhanku; kepadaNyalah aku berserah diri dan kepadaNyalah aku rujuk kembali (dalam segala keadaan)”.', FALSE, NULL, NULL, 483, 25, 193, 420, FALSE, 15, NULL),
(42, 11, 'فَاطِرُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَـٰمِ أَزْوَٰجًا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'فاطر السماوات والارض جعل لكم من انفسكم ازواجا ومن الانعام ازواجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير', NULL, '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.', 'Dia lah yang menciptakan langit dan bumi; Ia menjadikan bagi kamu pasangan-pasangan dari jenis kamu sendiri, dan menjadikan dari jenis binatang-binatang ternak pasangan-pasangan (bagi bintang-binatang itu); dengan jalan yang demikian dikembangkanNya (zuriat keturunan) kamu semua. Tiada sesuatupun yang sebanding dengan (ZatNya, sifat-sifatNya, dan pentadbiranNya) dan Dia lah Yang Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 484, 25, 193, 420, FALSE, 19, NULL),
(42, 12, 'لَهُۥ مَقَالِيدُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ', 'له مقاليد السماوات والارض يبسط الرزق لمن يشاء ويقدر انه بكل شيء عليم', NULL, 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.', 'Dia lah jua yang menguasai urusan dan perbendaharaan langit dan bumi; Ia memewahkan rezeki bagi sesiapa yang dikehendakiNya (menurut peraturan yang telah ditetapkan), dan Dia juga yang menyempitkannya (menurut peraturan itu); sesungguhnya Ia Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 484, 25, 193, 420, FALSE, 13, NULL),
(42, 13, '۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', 'شرع لكم من الدين ما وصى به نوحا والذي اوحينا اليك وما وصينا به ابراهيم وموسى وعيسى ان اقيموا الدين ولا تتفرقوا فيه كبر على المشركين ما تدعوهم اليه الله يجتبي اليه من يشاء ويهدي اليه من ينيب', NULL, 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muḥammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allāh is that to which you invite them. Allāh chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].', 'Allah telah menerangkan kepada kamu - di antara perkara-perkara ugama yang Ia tetapkan hukumnya - apa yang telah diperintahkanNya kepada Nabi Nuh, dan yang telah Kami (Allah) wahyukan kepadamu (wahai Muhammad), dan juga yang telah Kami perintahkan kepada Nabi Ibrahim dan Nabi Musa serta Nabi Isa, iaitu: “Tegakkanlah pendirian ugama, dan janganlah kamu berpecah belah atau berselisihan pada dasarnya”. Berat bagi orang-orang musyrik (untuk menerima ugama tauhid) yang engkau seru mereka kepadanya. Allah memilih serta melorongkan sesiapa yang dikehendakiNya untuk menerima ugama tauhid itu, dan memberi hidayah petunjuk kepada ugamaNya itu sesiapa yang rujuk kembali kepadaNya (dengan taat).', FALSE, NULL, NULL, 484, 25, 194, 420, FALSE, 38, NULL),
(42, 14, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ ۚ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَـٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 'وما تفرقوا الا من بعد ما جاءهم العلم بغيا بينهم ولولا كلمة سبقت من ربك الى اجل مسمى لقضي بينهم وان الذين اورثوا الكتاب من بعدهم لفي شك منه مريب', NULL, 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.', 'Dan umat tiap-tiap Rasul tidak berpecah belah dan berselisihan (dalam menjalankan ugama Allah) melainkan setelah sampai kepada mereka ajaran-ajaran yang memberi mereka mengetahui (apa yang disuruh dan apa yang dilarang); berlakunya (perselisihan yang demikian) semata-mata kerana hasad dengki sesama sendiri. Dan kalaulah tidak kerana telah terdahulu kalimah ketetapan dari Tuhanmu (untuk menangguhkan hukuman) hingga ke suatu masa yang tertentu, tentulah dijatuhkan hukuman azab dengan serta-merta kepada mereka. Dan sesungguhnya orang-orang yang diberikan Allah mewarisi Kitab ugama kemudian daripada mereka, berada dalam keadaan syak yang menggelisahkan terhadap Kitab itu.', FALSE, NULL, NULL, 484, 25, 194, 420, FALSE, 30, NULL),
(42, 15, 'فَلِذَٰلِكَ فَٱدْعُ ۖ وَٱسْتَقِمْ كَمَآ أُمِرْتَ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ ۖ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَـٰبٍ ۖ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ ۖ لَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ ۖ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ۖ ٱللَّهُ يَجْمَعُ بَيْنَنَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'فلذلك فادع واستقم كما امرت ولا تتبع اهواءهم وقل امنت بما انزل الله من كتاب وامرت لاعدل بينكم الله ربنا وربكم لنا اعمالنا ولكم اعمالكم لا حجة بيننا وبينكم الله يجمع بيننا واليه المصير', NULL, 'So to that [religion of Allāh] invite, [O Muḥammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allāh has revealed of scripture [i.e., the Qur’ān], and I have been commanded to do justice among you. Allāh is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allāh will bring us together, and to Him is the [final] destination."', 'Oleh kerana yang demikian itu, maka serulah (mereka - wahai Muhammad - kepada berugama dengan betul), serta tetap teguhlah engkau menjalankannya sebagaimana yang diperintahkan kepadamu, dan janganlah engkau menurut kehendak hawa nafsu mereka; sebaliknya katakanlah: “Aku beriman kepada segala Kitab yang diturunkan oleh Allah, dan aku diperintahkan supaya berlaku adil di antara kamu. Allah jualah Tuhan kami dan Tuhan kamu. Bagi kami amal kami dan bagi kamu amal kamu. Tidaklah patut ada sebarang pertengkaran antara kami dengan kamu (kerana kebenaran telah jelas nyata). Allah akan menghimpunkan kita bersama (pada hari kiamat), dan kepadaNyalah tempat kembali semuanya (untuk dihakimi dan diberi balasan)”.', FALSE, NULL, NULL, 484, 25, 194, 420, FALSE, 34, NULL),
(42, 16, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ', 'والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد', NULL, 'And those who argue concerning Allāh after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.', 'Dan orang-orang yang berhujah menyangkal dan membantah tentang kebenaran ugama Allah sesudah disambut dan diterima ugamaNya itu - bantahan (dan tuduhan palsu) mereka itu sia-sia belaka di sisi Tuhan mereka. Dan mereka pula ditimpa kemurkaan (dari Allah) serta mereka beroleh azab seksa yang seberat-beratnya.', FALSE, NULL, NULL, 485, 25, 194, 420, FALSE, 18, NULL),
(42, 17, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَـٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ ۗ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ', 'الله الذي انزل الكتاب بالحق والميزان وما يدريك لعل الساعة قريب', NULL, 'It is Allāh who has sent down the Book in truth and [also] the balance [i.e., justice]. And what will make you perceive? Perhaps the Hour is near.', 'Allah yang menurunkan Kitab Suci dengan membawa kebenaran, dan menurunkan keterangan yang menjadi neraca keadilan. Dan apa jalannya engkau dapat mengetahui? Boleh jadi hari kiamat itu sudah hampir (masa datangnya).', FALSE, NULL, NULL, 485, 25, 194, 420, FALSE, 11, NULL),
(42, 18, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا ۖ وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ ۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَـٰلٍۭ بَعِيدٍ', 'يستعجل بها الذين لا يؤمنون بها والذين امنوا مشفقون منها ويعلمون انها الحق الا ان الذين يمارون في الساعة لفي ضلال بعيد', NULL, 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.', 'Orang-orang yang tidak beriman kepada hari kiamat itu meminta (secara mengejek-ejek) supaya disegerakan kedatangannya, dan (sebaliknya) orang-orang yang beriman merasa takut ngeri kepadanya serta mereka mengetahui dengan yakin bahawa ia adalah benar. Ketahuilah! Sesungguhnya orang-orang yang membantah mengenai hari kiamat itu, tetap berada dalam kesesatan yang jauh terpesong.', FALSE, NULL, NULL, 485, 25, 194, 420, FALSE, 22, NULL),
(42, 19, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'الله لطيف بعباده يرزق من يشاء وهو القوي العزيز', NULL, 'Allāh is Subtle with His servants; He gives provision to whom He wills. And He is the Powerful, the Exalted in Might.', 'Allah Maha Lembut tadbirNya (serta melimpah-limpah kebaikan dan belas kasihanNya) kepada hamba-hambaNya; Ia memberi rezeki kepada sesiapa yang dikehendakiNya (menurut peraturan yang telah ditetapkan), dan Dia lah Yang Maha Kuat, lagi Maha Kuasa.', FALSE, NULL, NULL, 485, 25, 194, 420, FALSE, 9, NULL),
(42, 20, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْـَٔاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ ۖ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِن نَّصِيبٍ', 'من كان يريد حرث الاخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الاخرة من نصيب', NULL, 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest [i.e., reward]. And whoever desires the harvest [i.e., benefits] of this world - We give him thereof, but there is not for him in the Hereafter any share.', 'Sesiapa yang menghendaki (dengan amal usahanya) mendapat faedah di akhirat, Kami akan memberinya mendapat tambahan pada faedah yang dikehendakinya; dan sesiapa yang menghendaki (dengan amal usahanya) kebaikan di dunia semata-mata, Kami beri kepadanya dari kebaikan dunia itu (sekadar yang Kami tentukan), dan ia tidak akan beroleh sesuatu bahagian pun di akhirat kelak.', FALSE, NULL, NULL, 485, 25, 194, 421, FALSE, 22, NULL),
(42, 21, 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', 'أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُم مِّنَ الدِّينِ مَا لَمْ يَأْذَن بِهِ اللَّهُ وَلَوْلَا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْ وَإِنَّ الظَّالِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'Or have they partners [i.e., other deities] who have ordained for them a religion to which Allāh has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.', 'Patutkah mereka mempunyai sekutu-sekutu yang menentukan - mana-mana bahagian dari ugama mereka - sebarang undang-undang yang tidak diizinkan oleh Allah? Dan kalaulah tidak kerana kalimah ketetapan yang menjadi pemutus (dari Allah, untuk menangguhkan hukuman hingga ke suatu masa yang tertentu), tentulah dijatuhkan azab dengan serta-merta kepada mereka (yang berbuat demikian). Dan sesungguhnya orang-orang yang zalim itu akan beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 485, 25, 194, 421, FALSE, 0, NULL),
(42, 22, 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'تَرَى الظَّالِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا وَهُوَ وَاقِعٌ بِهِمْ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فِي رَوْضَاتِ الْجَنَّاتِ لَهُم مَّا يَشَاءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ الْفَضْلُ الْكَبِيرُ', NULL, 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.', '(Pada hari kiamat) engkau akan melihat orang-orang yang zalim takut ngeri (akan balasan buruk) bagi kejahatan-kejahatan yang mereka telah lakukan, sedang azab seksa itu tetap menimpa mereka. Dan orang-orang yang beriman serta beramal soleh (bersenang-lenang) dalam taman-taman Syurga; mereka beroleh apa sahaja yang mereka ingini di sisi Tuhan mereka; yang demikian itu ialah limpah kurnia yang besar.', FALSE, NULL, NULL, 485, 25, 194, 421, FALSE, 0, NULL),
(42, 23, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ', 'ذَٰلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُ فِيهَا حُسْنًا إِنَّ اللَّهَ غَفُورٌ شَكُورٌ', NULL, 'It is that of which Allāh gives good tidings to His servants who believe and do righteous deeds. Say, [O Muḥammad], "I do not ask you for it [i.e., this message] any payment [but] only good will through [i.e., due to] kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allāh is Forgiving and Appreciative.', '(Limpah kurnia yang besar) itulah yang Allah gembirakan (dengannya): hamba-hambaNya yang beriman dan beramal soleh. Katakanlah (wahai Muhammad): “Aku tidak meminta kepada kamu sebarang upah tentang ajaran Islam yang aku sampaikan itu, (yang aku minta) hanyalah kasih mesra (kamu terhadapku) disebabkan pertalian kerabat (yang menghubungkan daku dengan kamu supaya aku tidak disakiti)”. Dan sesiapa yang mengerjakan sesuatu perkara yang baik, Kami tambahi kebaikan baginya (dengan menggandakan pahala) kebaikannya itu. Sesungguhnya Allah Maha Pengampun, lagi sentiasa membalas dengan sebaik-baiknya (akan orang-orang yang bersyukur kepadaNya).', FALSE, NULL, NULL, 486, 25, 194, 421, FALSE, 0, NULL),
(42, 24, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'أَمْ يَقُولُونَ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا فَإِن يَشَإِ اللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ اللَّهُ الْبَاطِلَ وَيُحِقُّ الْحَقَّ بِكَلِمَاتِهِ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ', NULL, 'Or do they say, "He has invented about Allāh a lie"? But if Allāh willed, He could seal over your heart. And Allāh eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.', '(Orang-orang kafir tidak mengakui kerasulan Nabi Muhammad) bahkan mereka mengatakan: “Ia telah mereka-reka perkara dusta terhadap Allah” (Sebenarnya tidak patut mereka berkata demikian) kerana Allah berkuasa - jika Ia menghendaki - menutup hatimu (dan ingatanmu daripada menyatakan apa yang engkau telah nyatakan itu, tetapi Allah tidak menghendaki yang demikian, bahkan Ia memberi kuasa menyampaikan perintahNya, maka semua kenyataan yang engkau sampaikan adalah benar belaka). Dan sememangnya Allah tetap menghapuskan perkara yang salah serta Ia menetapkan yang benar dengan kalimah-kalimah wahyuNya dan keputusanNya. Sesungguhnya Ia Maha Mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 486, 25, 194, 421, FALSE, 0, NULL),
(42, 25, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', 'وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَعْفُو عَنِ السَّيِّئَاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', NULL, 'And it is He who accepts repentance from His servants and pardons misdeeds, and He knows what you do.', 'Dan Dia lah Tuhan yang menerima taubat dari hamba-hambaNya (yang bertaubat) serta memaafkan kejahatan-kejahatan (yang mereka lakukan); dan Ia mengetahui akan apa yang kamu semua kerjakan.', FALSE, NULL, NULL, 486, 25, 194, 421, FALSE, 0, NULL),
(42, 26, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', 'وَيَسْتَجِيبُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَيَزِيدُهُم مِّن فَضْلِهِ وَالْكَافِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', NULL, 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.', 'Dan Ia memperkenankan doa permohonan orang-orang yang beriman serta beramal soleh, dan Ia menambahi mereka dari limpah kurniaNya (selain dari yang mereka pohonkan). Dan (sebaliknya) orang-orang yang kafir, disediakan bagi mereka azab seksa yang seberat-beratnya.', FALSE, NULL, NULL, 486, 25, 194, 421, FALSE, 0, NULL),
(42, 27, 'وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ', 'وَلَوْ بَسَطَ اللَّهُ الرِّزْقَ لِعِبَادِهِ لَبَغَوْا فِي الْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَاءُ إِنَّهُ بِعِبَادِهِ خَبِيرٌ بَصِيرٌ', NULL, 'And if Allāh had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Aware and Seeing.', 'Dan kalaulah Allah memewahkan rezeki bagi setiap hambaNya, nescaya mereka akan melampaui batas di bumi (dengan perbuatan-perbuatan liar durjana); akan tetapi Allah menurunkan (rezekiNya itu) menurut kadar yang tertentu sebagaimana yang dikehendakiNya. Sesungguhnya Ia Mengetahui dengan mendalam akan segala keadaan hambaNya, lagi Melihat dengan nyata.', FALSE, NULL, NULL, 486, 25, 195, 421, FALSE, 0, NULL),
(42, 28, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 'وَهُوَ الَّذِي يُنَزِّلُ الْغَيْثَ مِن بَعْدِ مَا قَنَطُوا وَيَنشُرُ رَحْمَتَهُ وَهُوَ الْوَلِيُّ الْحَمِيدُ', NULL, 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.', 'Dan Dia lah yang menurunkan hujan setelah mereka berputus asa, dan Ia pula menyebarkan rahmatNya merata-rata. Dan (ingatlah) Dia lah pengawal (yang melimpahkan ihsanNya), lagi Yang Maha Terpuji.', FALSE, NULL, NULL, 486, 25, 195, 421, FALSE, 0, NULL),
(42, 29, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ', 'وَمِنْ آيَاتِهِ خَلْقُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَابَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَاءُ قَدِيرٌ', NULL, 'And of His signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.', 'Dan di antara tanda-tanda kekuasaanNya ialah kejadian langit dan bumi serta segala yang Ia biakkan pada keduanya dari makhluk-makhluk yang melata; dan Ia Maha Kuasa menghimpunkan mereka semuanya apabila Ia kehendaki (melakukannya).', FALSE, NULL, NULL, 486, 25, 195, 421, FALSE, 0, NULL),
(42, 30, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ', 'وَمَا أَصَابَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَن كَثِيرٍ', NULL, 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.', 'Dan apa jua yang menimpa kamu dari sesuatu kesusahan (atau bala bencana), maka ia adalah disebabkan apa yang kamu lakukan (dari perbuatan-perbuatan yang salah dan berdosa); dan (dalam pada itu) Allah memaafkan sebahagian besar dari dosa-dosa kamu.', FALSE, NULL, NULL, 486, 25, 195, 422, FALSE, 0, NULL),
(42, 31, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'وَمَا أَنتُم بِمُعْجِزِينَ فِي الْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ', NULL, 'And you will not cause failure [to Allāh] upon the earth. And you have not besides Allāh any protector or helper.', 'Dan kamu tidak akan dapat melemahkan kuasa Allah (daripada menimpakan kamu dengan bala bencana, walaupun kamu melarikan diri di mana sahaja) di muka bumi (atau di langit); dan kamu juga tidak akan beroleh sesiapapun yang lain dari Allah. - sebagai pelindung atau pemberi pertolongan.', FALSE, NULL, NULL, 486, 25, 195, 422, FALSE, 0, NULL),
(42, 32, 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'وَمِنْ آيَاتِهِ الْجَوَارِ فِي الْبَحْرِ كَالْأَعْلَامِ', NULL, 'And of His signs are the ships in the sea, like mountains.', 'Dan di antara tanda-tanda kekuasaanNya ialah kapal-kapal (yang besar tinggi) seperti gunung, belayar laju merempuh lautan.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 33, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'إِن يَشَأْ يُسْكِنِ الرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', NULL, 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.', 'Jika Ia kehendaki, Ia menghentikan tiupan angin, maka tinggallah kapal-kapal itu terapung-apung di muka lautan. Sesungguhnya yang demikian mengandungi tanda-tanda (yang besar pengajarannya) bagi tiap-tiap seorang (mukmin) yang sentiasa bersikap sabar, lagi sentiasa bersyukur.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 34, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ', 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا وَيَعْفُ عَن كَثِيرٍ', NULL, 'Or He could destroy them for what they earned; but He pardons much.', 'Atau (jika Ia kehendaki) Ia binasakan kapal-kapal itu disebabkan dosa-dosa yang dilakukan oleh orang-orangnya, (lalu setengahnya dibiarkan mati lemas) dan (setengahnya diselamatkan dengan jalan) Ia memaafkan sebahagian besar dari dosa-dosa mereka.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 35, 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍ', 'وَيَعْلَمَ الَّذِينَ يُجَادِلُونَ فِي آيَاتِنَا مَا لَهُم مِّن مَّحِيصٍ', NULL, 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.', '(Berlakunya yang demikian supaya nyata kekuasaan Kami) dan supaya orang-orang yang membantah ayat-ayat keterangan Kami mengetahui, bahawa mereka tidak akan dapat jalan melepaskan diri (dari azab seksa).', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 36, 'فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'فَمَا أُوتِيتُم مِّن شَيْءٍ فَمَتَاعُ الْحَيَاةِ الدُّنْيَا وَمَا عِندَ اللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ آمَنُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', NULL, 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allāh is better and more lasting for those who have believed and upon their Lord rely', 'Oleh itu, apa jua yang diberikan kepada kamu, maka ia hanyalah nikmat kesenangan hidup di dunia ini sahaja, dan (sebaliknya) apa yang ada di sisi Allah (dari pahala hari akhirat) adalah lebih baik dan lebih kekal bagi orang-orang yang beriman dan yang berserah bulat-bulat kepada Tuhannya;', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 37, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', 'وَالَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ', NULL, 'And those who avoid the major sins and immoralities, and when they are angry, they forgive,', 'Dan juga (lebih baik dan lebih kekal bagi) orang-orang yang menjauhi dosa-dosa besar serta perbuatan-perbuatan yang keji; dan apabila mereka marah (disebabkan perbuatan yang tidak patut terhadap mereka), mereka memaafkannya;', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 38, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'وَالَّذِينَ اسْتَجَابُوا لِرَبِّهِمْ وَأَقَامُوا الصَّلَاةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ', NULL, 'And those who have responded to their Lord and established prayer and whose affair is [determined by] consultation among themselves, and from what We have provided them, they spend,', 'Dan juga (lebih baik dan lebih kekal bagi) orang-orang yang menyahut dan menyambut perintah Tuhannya serta mendirikan sembahyang dengan sempurna; dan urusan mereka dijalankan secara bermesyuarat sesama mereka; dan mereka pula mendermakan sebahagian dari apa yang Kami beri kepadanya;', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 39, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 'وَالَّذِينَ إِذَا أَصَابَهُمُ الْبَغْيُ هُمْ يَنتَصِرُونَ', NULL, 'And those who, when tyranny strikes them, they retaliate [in a just manner].', 'Dan juga (lebih baik dan lebih kekal bagi) orang-orang yang apabila ditimpa sesuatu perbuatan secara zalim, mereka hanya bertindak membela diri (sepadan dan tidak melampaui batas).', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 40, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ إِنَّهُ لَا يُحِبُّ الظَّالِمِينَ', NULL, 'And the retribution for an evil act is an evil one like it, but whoever pardons and makes reconciliation - his reward is [due] from Allāh. Indeed, He does not like wrongdoers.', 'Dan (jika kamu hendak membalas maka) balasan sesuatu kejahatan ialah kejahatan yang bersamaan dengannya; dalam pada itu sesiapa yang memaafkan (kejahatan orang) dan berbuat baik (kepadanya), maka pahalanya tetap dijamin oleh Allah (dengan diberi balasan yang sebaik-baiknya). Sesungguhnya Allah tidak suka kepada orang-orang yang berlaku zalim.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 41, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 'وَلَمَنِ انتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَٰئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', NULL, 'And whoever retaliates after having been wronged - those have not upon them any cause [for blame].', 'Dan sesungguhnya orang yang bertindak membela diri setelah ia dizalimi, maka mereka yang demikian keadaannya, tidak ada sebarang jalan hendak menyalahkan mereka.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 42, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ وَيَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ أُولَٰئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', NULL, 'The cause is only against the ones who wrong the people and tyrannize upon the earth without right. Those will have a painful punishment.', 'Sesungguhnya jalan (untuk menyalahkan) hanyalah terhadap orang-orang yang melakukan kezaliman kepada manusia dan bermaharajalela di muka bumi dengan tiada sebarang alasan yang benar. Mereka itulah orang-orang yang beroleh azab seksa yang tidak berperi sakitnya.', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 43, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ الْأُمُورِ', NULL, 'And whoever is patient and forgives - indeed, that is of the matters [worthy] of resolve.', 'Dalam pada itu (ingatlah), orang yang bersabar dan memaafkan (kesalahan orang terhadapnya), sesungguhnya yang demikian itu adalah dari perkara-perkara yang dikehendaki diambil berat (melakukannya).', FALSE, NULL, NULL, 487, 25, 195, 422, FALSE, 0, NULL),
(42, 44, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', 'وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِن وَلِيٍّ مِّن بَعْدِهِ وَتَرَى الظَّالِمِينَ لَمَّا رَأَوُا الْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', NULL, 'And he whom Allāh sends astray - for him there is no protector beyond Him. And you will see the wrongdoers, when they see the punishment, saying, "Is there for return [to the former world] any way?"', 'Dan sesiapa yang disesatkan oleh Allah, maka tidak ada baginya sesudah itu sesiapapun yang dapat menolongnya. Dan engkau akan melihat orang-orang yang zalim semasa mereka menyaksikan azab (pada hari kiamat) berkata: “Adakah sebarang jalan untuk kami kembali ke dunia?”', FALSE, NULL, NULL, 487, 25, 195, 423, FALSE, 0, NULL),
(42, 45, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ', 'وَتَرَاهُمْ يُعْرَضُونَ عَلَيْهَا خَاشِعِينَ مِنَ الذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِيٍّ وَقَالَ الَّذِينَ آمَنُوا إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا إِنَّ الظَّالِمِينَ فِي عَذَابٍ مُّقِيمٍ', NULL, 'And you will see them being exposed to it [i.e., the Fire], humbled from humiliation, looking from [behind] a covert glance. And those who had believed will say, "Indeed, the [true] losers are the ones who lost themselves and their families on the Day of Resurrection. Unquestionably, the wrongdoers are in an enduring punishment."', 'Dan engkau juga akan melihat mereka didedahkan kepada neraka dalam keadaan tunduk membisu dengan sebab kehinaan (yang mereka rasai) sambil memandang (ke neraka itu) hanya dengan mengerling (kerana gerun takut). Dan orang-orang yang beriman pula berkata: “Sesungguhnya orang-orang yang rugi (dengan sebenar-benarnya) ialah mereka yang merugikan dirinya sendiri dan pengikut-pengikutnya pada hari kiamat (dengan sebab mereka memilih perbuatan derhaka di dunia). Ingatlah! Sesungguhnya orang-orang yang zalim itu berada dalam azab seksa yang kekal”.', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 46, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَاءَ يَنصُرُونَهُم مِّن دُونِ اللَّهِ وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُ مِن سَبِيلٍ', NULL, 'And there will not be for them any allies to aid them other than Allāh. And whoever Allāh sends astray - for him there is no way.', 'Dan tiadalah bagi mereka sebarang penolong - yang lain dari Allah - yang dapat memberikan pertolongan kepada mereka; dan sesiapa yang disesatkan oleh Allah (disebabkan pilihannya yang salah) maka tidak ada baginya sebarang jalan (untuk mendapat hidayah petunjuk).', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 47, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', 'اسْتَجِيبُوا لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', NULL, 'Respond to your Lord before a Day comes from Allāh of which there is no repelling. No refuge will you have that Day, nor for you will there be any denial.', 'Sahut dan sambutlah seruan Tuhan kamu (yang mengajak kamu beriman), sebelum datangnya dari Allah - hari yang tidak dapat ditolak; pada hari itu tidak ada bagi kamu tempat berlindung (dari azabNya), dan tidak ada pula bagi kamu sebarang alasan untuk menafikan (kesalahan yang kamu telah lakukan).', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 48, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌ', 'فَإِنْ أَعْرَضُوا فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا الْبَلَاغُ وَإِنَّا إِذَا أَذَقْنَا الْإِنسَانَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ الْإِنسَانَ كَفُورٌ', NULL, 'But if they turn away - then We have not sent you, [O Muḥammad], over them as a guardian; upon you is only [the duty of] notification. And indeed, when We let man taste mercy from Us, he rejoices in it; but if evil afflicts him for what his hands have put forth, then indeed, man is ungrateful.', 'Oleh itu, jika mereka berpaling ingkar, maka Kami tidak mengutusmu (wahai Muhammad) sebagai pengawas terhadap mereka; tugasmu tidak lain hanyalah menyampaikan (apa yang diperintahkan kepadamu). Dan (ingatlah) sesungguhnya apabila Kami memberi manusia merasai sesuatu rahmat dari Kami, ia bergembira dengannya; dan (sebaliknya) jika mereka ditimpa sesuatu kesusahan disebabkan dosa-dosa yang mereka lakukan, maka (mereka segera membantah serta melupakan rahmat yang mereka telah menikmatinya, kerana) sesungguhnya manusia itu sangat tidak mengenang nikmat-nikmat Tuhannya.', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 49, 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَخْلُقُ مَا يَشَآءُ يَهَبُ لِمَن يَشَآءُ إِنَٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 'لِّلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يَخْلُقُ مَا يَشَاءُ يَهَبُ لِمَن يَشَاءُ إِنَاثًا وَيَهَبُ لِمَن يَشَاءُ الذُّكُورَ', NULL, 'To Allāh belongs the dominion of the heavens and the earth; He creates what He wills. He gives to whom He wills female [children], and He gives to whom He wills males.', 'Bagi Allah jualah hak milik segala yang ada di langit dan di bumi; Ia menciptakan apa yang dikehendakiNya; Ia mengurniakan anak-anak perempuan kepada sesiapa yang dikehendakiNya, dan mengurniakan anak-anak lelaki kepada sesiapa yang dikehendakiNya.', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 50, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَٰثًا وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا إِنَّهُۥ عَلِيمٌ قَدِيرٌ', 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَن يَشَاءُ عَقِيمًا إِنَّهُ عَلِيمٌ قَدِيرٌ', NULL, 'Or He makes them [both] males and females, and He renders whom He wills barren. Indeed, He is Knowing and Competent.', 'Atau Ia mengurniakan mereka kedua-duanya - anak-anak lelaki dan perempuan, dan Ia juga menjadikan sesiapa yang dikehendakiNya: mandul. Sesungguhnya Ia Maha Mengetahui, lagi Maha Kuasa.', FALSE, NULL, NULL, 488, 25, 195, 423, FALSE, 0, NULL),
(42, 51, 'وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ إِنَّهُۥ عَلِىٌّ حَكِيمٌ', 'وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ اللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ', NULL, 'And it is not for any human being that Allāh should speak to him except by revelation or from behind a partition or that He sends a messenger [i.e., angel] to reveal, by His permission, what He wills. Indeed, He is Most High and Wise.', 'Dan tidaklah layak bagi seseorang manusia bahawa Allah berkata-kata dengannya kecuali dengan jalan wahyu (dengan diberi ilham atau mimpi), atau dari sebalik dinding (dengan mendengar suara sahaja), atau dengan mengutuskan utusan (malaikat) lalu utusan itu menyampaikan wahyu kepadanya dengan izin Allah akan apa yang dikehendakiNya. Sesungguhnya Allah Maha Tinggi keadaanNya, lagi Maha Bijaksana.', FALSE, NULL, NULL, 488, 25, 196, 423, FALSE, 0, NULL),
(42, 52, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'وَكَذَٰلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِي مَا الْكِتَابُ وَلَا الْإِيمَانُ وَلَٰكِن جَعَلْنَاهُ نُورًا نَّهْدِي بِهِ مَن نَّشَاءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِي إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'And thus We have revealed to you an inspiration of Our command [i.e., the Qur’ān]. You did not know what is the Book or [what is] faith, but We have made it a light by which We guide whom We will of Our servants. And indeed, [O Muḥammad], you guide to a straight path -', 'Dan demikianlah Kami wahyukan kepadamu (Muhammad) - Al-Quran sebagai roh (yang menghidupkan hati perintah Kami; engkau tidak pernah mengetahui (sebelum diwahyukan kepadamu): apakah Kitab (Al-Quran) itu dan tidak juga mengetahui apakah iman itu; akan tetapi Kami jadikan Al-Quran: cahaya yang menerangi, Kami beri petunjuk dengannya sesiapa yang Kami kehendaki di antara hamba-hamba Kami. Dan sesungguhnya engkau (wahai Muhammad) adalah memberi petunjuk dengan Al-Quran itu ke jalan yang lurus,', FALSE, NULL, NULL, 489, 25, 196, 423, FALSE, 0, NULL),
(42, 53, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 'صِرَاطِ اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ أَلَا إِلَى اللَّهِ تَصِيرُ الْأُمُورُ', NULL, 'The path of Allāh, to whom belongs whatever is in the heavens and whatever is on the earth. Unquestionably, to Allāh do [all] matters evolve [i.e., return].', 'Iaitu jalan Allah yang memiliki dan menguasai segala yang ada di langit dan yang ada di bumi. Ingatlah! Kepada Allah jualah kembali segala urusan.', FALSE, NULL, NULL, 489, 25, 196, 423, FALSE, 0, NULL),
(43, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 1, NULL),
(43, 2, 'وَٱلْكِتَـٰبِ ٱلْمُبِينِ', 'والكتاب المبين', NULL, 'By the clear Book,', 'Demi Kitab Al-Quran yang menyatakan kebenaran.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 2, NULL),
(43, 3, 'إِنَّا جَعَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'انا جعلناه قرانا عربيا لعلكم تعقلون', NULL, 'Indeed, We have made it an Arabic Qur’ān that you might understand.', 'Sesungguhnya Kami jadikan Kitab itu sebagai Quran yang diturunkan dengan bahasa Arab, supaya kamu (menggunakan akal) memahaminya.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 6, NULL),
(43, 4, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَـٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', 'وانه في ام الكتاب لدينا لعلي حكيم', NULL, 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.', 'Dan sesungguhnya Al-Quran itu dalam Ibu Suratan di sisi Kami - sangat tinggi (kemuliaannya), lagi amat banyak mengandungi hikmat-hikmat dan kebenaran yang tetap kukuh.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 7, NULL),
(43, 5, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ', 'افنضرب عنكم الذكر صفحا ان كنتم قوما مسرفين', NULL, 'Then should We turn the message away, disregarding you, because you are a transgressing people?', 'Patutkah Kami membiarkan kamu dengan mengenepikan dan menjauhkan peringatan Al-Quran daripada kamu, kerana kamu telah menjadi kaum yang melampau buruk keadaannya? (Tidak! Kami tidak akan biarkan, bahkan Kami tetap mengingatkan kamu, sama ada kamu mahu menerimanya atau sebaliknya).', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 8, NULL),
(43, 6, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ', 'وكم ارسلنا من نبي في الاولين', NULL, 'And how many a prophet We sent among the former peoples,', 'Dan (ingatlah), berapa banyak nabi-nabi yang kami telah utuskan kepada umat-umat yang terdahulu zamannya.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 6, NULL),
(43, 7, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وما ياتيهم من نبي الا كانوا به يستهزئون', NULL, 'But there would not come to them a prophet except that they used to ridicule him.', 'Dan tidak ada seseorang Nabi pun yang datang kepada mereka, melainkan mereka mempersenda dan mengejek-ejeknya.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 8, NULL),
(43, 8, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', 'فاهلكنا اشد منهم بطشا ومضى مثل الاولين', NULL, 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.', 'Lalu Kami binasakan orang-orang yang lebih kekuatannya (dan lebih kejam serangannya) daripada mereka; dan telahpun disebutkan (berulang-ulang di dalam Al-Quran) tentang kisah-kisah dan misal perbandingan mengenai umat-umat yang telah lalu.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 7, NULL),
(43, 9, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'ولئن سالتهم من خلق السماوات والارض ليقولن خلقهن العزيز العليم', NULL, 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing,"', 'Dan demi sesungguhnya! Jika engkau (wahai Muhammad) bertanya kepada mereka (yang musyrik) itu: “Siapakah yang menciptakan langit dan bumi?” Sudah tentu mereka akan menjawab: “Yang menciptakannya ialah Allah Yang Maha Kuasa, lagi Maha Mengetahui”.', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 10, NULL),
(43, 10, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', 'الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون', NULL, '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided', '(Dia lah Tuhan) yang telah menjadikan bumi bagi kamu sebagai hamparan, dan Ia telah mengadakan bagi kamu di bumi jalan-jalan lalu-lalang, supaya kamu mendapat petunjuk (ke arah yang dituju).', FALSE, NULL, NULL, 489, 25, 196, 424, FALSE, 11, NULL),
(43, 11, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا ۚ كَذَٰلِكَ تُخْرَجُونَ', 'والذي نزل من السماء ماء بقدر فانشرنا به بلدة ميتا كذلك تخرجون', NULL, 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -', 'Dan (Dia lah) yang menurunkan hujan dari menurut sukatan yang tertentu, lalu Kami hidupkan dengan hujan itu negeri yang kering tandus tanahnya. Sedemikian itulah pula kamu akan dikeluarkan (hidup semula dari kubur).', FALSE, NULL, NULL, 490, 25, 196, 424, FALSE, 12, NULL),
(43, 12, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَـٰمِ مَا تَرْكَبُونَ', 'والذي خلق الازواج كلها وجعل لكم من الفلك والانعام ما تركبون', NULL, 'And who created the species, all of them, and has made for you of ships and animals those which you mount', 'Dan (Dia lah) yang menciptakan sekalian makhluk yang berbagai jenisnya; dan Ia mengadakan bagi kamu kapal-kapal dan binatang ternak yang kamu dapat mengenderainya,', FALSE, NULL, NULL, 490, 25, 196, 424, FALSE, 11, NULL),
(43, 13, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَـٰنَ ٱلَّذِى سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', 'لتستووا على ظهوره ثم تذكروا نعمة ربكم اذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين', NULL, 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say, "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.', 'Supaya kamu duduk tetap di atasnya; kemudian kamu mengingati nikmat Tuhan kamu apabila kamu duduk tetap di atasnya, serta kamu (bersyukur dengan) mengucapkan: “Maha Suci Tuhan yang telah memudahkan kenderaan ini untuk kami, sedang kami sebelum itu tidak terdaya menguasainya -', FALSE, NULL, NULL, 490, 25, 196, 424, FALSE, 20, NULL),
(43, 14, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', 'وانا الى ربنا لمنقلبون', NULL, 'And indeed we, to our Lord, will [surely] return."', '“Dan sesungguhnya kepada Tuhan kamilah, kami akan kembali!”', FALSE, NULL, NULL, 490, 25, 196, 424, FALSE, 4, NULL),
(43, 15, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا ۚ إِنَّ ٱلْإِنسَـٰنَ لَكَفُورٌ مُّبِينٌ', 'وجعلوا له من عباده جزءا ان الانسان لكفور مبين', NULL, 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.', 'Dan mereka (yang musyrik mempersekutukan Allah dengan) menjadikan sebahagian dari hamba-hamba Allah sebagai anak bagiNya. Sesungguhnya manusia (yang demikian sesatnya) sangat tidak mengenang budi, lagi nyata kufurnya.', FALSE, NULL, NULL, 490, 25, 196, 424, FALSE, 9, NULL),
(43, 16, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ', 'ام اتخذ مما يخلق بنات واصفاكم بالبنين', NULL, 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?', 'Patutkah tuhan mengambil dari makhluk-makhluk yang diciptakanNya menjadi anak-anak perempuannya, dan Ia mengutamakan kamu dengan anak-anak lelaki?', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 7, NULL),
(43, 17, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَـٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'واذا بشر احدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم', NULL, 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison [i.e., a daughter], his face becomes dark, and he suppresses grief.', 'Padahal apabila diberitahu kepada salah seorang dari mereka dengan (berita bahawa ia beroleh anak perempuan seperti) yang dijadikannya sekutu yang sejenis dengan Allah Yang Maha Pemurah, muramlah mukanya sepanjang hari (kerana menanggung dukacita), sedang ia menahan perasaan marahnya dalam hati.', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 12, NULL),
(43, 18, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ', 'اومن ينشا في الحلية وهو في الخصام غير مبين', NULL, 'So is one brought up in ornaments while being during conflict unevident [attributed to Allāh]?', 'Patutkah (yang dikatakan anak Allah itu jenis perempuan) yang biasanya dididik dan dibesarkan dalam perhiasan, sedang ia semasa berbantah dan bertikam lidah tidak dapat memberikan alasan yang jelas?', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 9, NULL),
(43, 19, 'وَجَعَلُوا۟ ٱلْمَلَـٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَـٰدُ ٱلرَّحْمَـٰنِ إِنَـٰثًا ۚ أَشَهِدُوا۟ خَلْقَهُمْ ۚ سَتُكْتَبُ شَهَـٰدَتُهُمْ وَيُسْـَٔلُونَ', 'وجعلوا الملائكة الذين هم عباد الرحمن اناثا اشهدوا خلقهم ستكتب شهادتهم ويسالون', NULL, 'And they described the angels, who are servants of the Most Merciful, as females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.', 'Dan mereka pula menyifatkan malaikat - yang juga menjadi hamba-hamba Allah Yang Maha Pemurah itu - jenis perempuan. Adakah mereka menyaksikan kejadian malaikat itu? Akan dituliskan kata-kata mereka (yang dusta itu), dan mereka akan ditanya kelak (serta akan menerima balasannya).', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 12, NULL),
(43, 20, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَـٰنُ مَا عَبَدْنَـٰهُم ۗ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 'وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم ان هم الا يخرصون', NULL, 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but misjudging.', 'Dan mereka berkata: “Kalaulah Allah Yang Maha Pemurah menghendaki tentulah kami tidak menyembah malaikat itu”. (Sebenarnya) mereka tidak mempunyai sesuatu pengetahuan pun mengenai kata-kata mereka (yang demikian), mereka hanyalah orang-orang yang berdusta!', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 15, NULL),
(43, 21, 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 'أَمْ آتَيْنَاهُمْ كِتَابًا مِّن قَبْلِهِ فَهُم بِهِ مُسْتَمْسِكُونَ', NULL, 'Or have We given them a book before it [i.e., the Qur’ān] to which they are adhering?', 'Pernahkah Kami memberikan mereka sebelum Al-Quran ini sebuah Kitab (yang membenarkan dakwaan mereka), lalu mereka berpegang teguh kepada kitab itu?', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 0, NULL),
(43, 22, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', 'بَلْ قَالُوا إِنَّا وَجَدْنَا آبَاءَنَا عَلَىٰ أُمَّةٍ وَإِنَّا عَلَىٰ آثَارِهِم مُّهْتَدُونَ', NULL, 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."', '(Tidak ada sebarang bukti bagi mereka) bahkan mereka (hanyalah) berkata: Sesungguhnya kami telah mendapati datuk nenek kami menurut satu jalan ugama, dan sesungguhnya kami beroleh petunjuk menurut jejak mereka sahaja”.', FALSE, NULL, NULL, 490, 25, 196, 425, FALSE, 0, NULL),
(43, 23, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 'وَكَذَٰلِكَ مَا أَرْسَلْنَا مِن قَبْلِكَ فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا وَجَدْنَا آبَاءَنَا عَلَىٰ أُمَّةٍ وَإِنَّا عَلَىٰ آثَارِهِم مُّقْتَدُونَ', NULL, 'And similarly, We did not send before you any warner into a city except that its affluent said, "Indeed, we found our fathers upon a religion, and we are, in their footsteps, following."', 'Dan demikianlah halnya (orang-orang yang taqlid buta); Kami tidak mengutus sebelummu (wahai Muhammad) kepada (penduduk) sesebuah negeri, seseorang Rasul pemberi amaran, melainkan orang-orang yang berada dalam kemewahan di negeri itu berkata: “Sesungguhnya kami dapati datuk nenek kami menurut satu jalan ugama, dan sesungguhnya kami hanya mengikut jejak mereka sahaja”.', FALSE, NULL, NULL, 491, 25, 196, 425, FALSE, 0, NULL),
(43, 24, 'قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'قَالَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ آبَاءَكُمْ قَالُوا إِنَّا بِمَا أُرْسِلْتُم بِهِ كَافِرُونَ', NULL, '[Each warner] said, "Even if I brought you better guidance than that [religion] upon which you found your fathers?" They said, "Indeed we, in that with which you were sent, are disbelievers."', 'Rasul itu berkata: “Adakah (kamu akan menurut juga mereka) walaupun aku membawa kepada kamu ugama yang lebih jelas hidayah petunjuknya daripada jalan ugama yang kamu dapati datuk nenek kamu menurutnya?” Mereka menjawab: “Sesungguhnya kami tetap mengingkari apa yang kamu diutuskan membawanya”.', FALSE, NULL, NULL, 491, 25, 197, 425, FALSE, 0, NULL),
(43, 25, 'فَٱنتَقَمْنَا مِنْهُمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'فَانتَقَمْنَا مِنْهُمْ فَانظُرْ كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ', NULL, 'So We took retribution from them; then see how was the end of the deniers.', 'Lalu kami balas keingkaran mereka dengan azab yang membinasakan; maka perhatikanlah bagaimana buruknya kesudahan umat-umat yang mendustakan Rasul-rasulnya.', FALSE, NULL, NULL, 491, 25, 197, 425, FALSE, 0, NULL),
(43, 26, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ', 'وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَرَاءٌ مِّمَّا تَعْبُدُونَ', NULL, 'And [mention, O Muḥammad], when Abraham said to his father and his people, "Indeed, I am disassociated from that which you worship', 'Dan (ingatkanlah peristiwa) ketika Nabi Ibrahim berkata kepada bapanya dan kaumnya: “Sesungguhnya aku berlepas diri dari apa yang kamu sembah -', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 27, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', 'إِلَّا الَّذِي فَطَرَنِي فَإِنَّهُ سَيَهْدِينِ', NULL, 'Except for He who created me; and indeed, He will guide me."', '“Yang lain dari Tuhan yang menciptakan daku, kerana sesungguhnya Ia tetap memberi hidayah petunjuk kepadaku”.', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 28, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 'وَجَعَلَهَا كَلِمَةً بَاقِيَةً فِي عَقِبِهِ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And he made it a word remaining among his descendants that they might return [to it].', 'Dan Nabi Ibrahim menjadikan kalimah tauhid itu tetap kekal pada keturunannya, supaya mereka kembali (kepada tauhid itu, jika ada yang menyeleweng kepada syirik).', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 29, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ', 'بَلْ مَتَّعْتُ هَٰؤُلَاءِ وَآبَاءَهُمْ حَتَّىٰ جَاءَهُمُ الْحَقُّ وَرَسُولٌ مُّبِينٌ', NULL, 'However, I gave enjoyment to these [people of Makkah] and their fathers until there came to them the truth and a clear Messenger.', '(Kebanyakan mereka tidak kembali kepada tauhid, dan Aku pula tidak segerakan azab mereka) bahkan Aku memberikan mereka dan datuk nenek mereka menikmati kesenangan hidup, sehingga datanglah kepada mereka kebenaran (Al-Quran), dan seorang Rasul yang menerangkan tauhid.', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 30, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَٰفِرُونَ', 'وَلَمَّا جَاءَهُمُ الْحَقُّ قَالُوا هَٰذَا سِحْرٌ وَإِنَّا بِهِ كَافِرُونَ', NULL, 'But when the truth came to them, they said, "This is magic, and indeed we are, concerning it, disbelievers."', 'Dan ketika kebenaran (Al-Quran) itu disampaikan kepada mereka, berkatalah mereka: “Sesungguhnya ini adalah sihir, dan sesungguhnya kami tetap mengingkarinya”.', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 31, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', 'وَقَالُوا لَوْلَا نُزِّلَ هَٰذَا الْقُرْآنُ عَلَىٰ رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيمٍ', NULL, 'And they said, "Why was this Qur’ān not sent down upon a great man from [one of] the two cities?"', 'Dan (kerana mereka mencemuh Nabi Muhammad) mereka berkata: “(Kalaulah Al-Quran ini menjadi bukti kenabian seseorang, maka) sepatutnya Al-Quran ini diturunkan kepada seorang besar (yang kaya dan berpengaruh) dari salah sebuah dua bandar yang (terkenal) itu?”', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 32, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِي الْحَيَاةِ الدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', NULL, 'Do they distribute the mercy of your Lord? It is We who have apportioned among them their livelihood in the life of this world and have raised some of them above others in degrees [of rank] that they may make use of one another for service. But the mercy of your Lord is better than whatever they accumulate.', '(Mengapa pemberian Kami itu mereka ingkarkan?) Adakah mereka berkuasa membahagi-bahagikan (perkara-perkara keruhanian dan keugamaan yang menjadi sebesar-besar) rahmat Tuhanmu (wahai Muhammad, seolah-olah Kami hanya berkuasa dalam perkara kebendaan dan keduniaan sahaja? Mereka tidak ingkarkan): Kami membahagi-bahagikan antara mereka segala keperluan hidup mereka dalam kehidupan dunia ini, (setengahnya Kami jadikan kaya raya dan setengahnya miskin menderita); dan juga Kami telah menjadikan darjat setengah mereka tertinggi dari darjat setengahnya yang lain; (semuanya itu) supaya sebahagian dari mereka senang mendapat kemudahan menjalankan kehidupannya dari (bantuan) setengahnya yang lain. Dan lagi rahmat Tuhanmu (yang meliputi kebahagiaan dunia dan akhirat) adalah lebih baik dari kebendaan dan keduniaan semata-mata yang mereka kumpulkan.', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 33, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'وَلَوْلَا أَن يَكُونَ النَّاسُ أُمَّةً وَاحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِالرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', NULL, 'And if it were not that the people would become one community [of disbelievers], We would have made for those who disbelieve in the Most Merciful - for their houses - ceilings and stairways of silver upon which to mount.', 'Dan kalaulah tidak kerana manusia akan menjadi umat yang satu (dalam kekufuran), nescaya Kami jadikan bagi orang-orang yang kufur ingkar kepada Tuhan Yang Maha Pemurah, bumbung rumah-rumah mereka dari perak, dan tangga-tangga yang mereka naik turun di atasnya (dari perak juga),', FALSE, NULL, NULL, 491, 25, 197, 426, FALSE, 0, NULL),
(43, 34, 'وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', 'وَلِبُيُوتِهِمْ أَبْوَابًا وَسُرُرًا عَلَيْهَا يَتَّكِئُونَ', NULL, 'And for their houses - doors and couches [of silver] upon which to recline', 'Dan juga pintu-pintu rumah mereka (dari perak juga), dan kerusi-kerusi panjang yang mereka berbaring di atasnya (dari perak juga),', FALSE, NULL, NULL, 492, 25, 197, 426, FALSE, 0, NULL),
(43, 35, 'وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْـَٔاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', 'وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَاعُ الْحَيَاةِ الدُّنْيَا وَالْآخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', NULL, 'And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous.', 'Serta berbagai barang perhiasan (keemasan). Dan (ingatlah), segala yang tersebut itu tidak lain hanyalah merupakan kesenangan hidup di dunia; dan (sebaliknya) kesenangan hari akhirat di sisi hukum Tuhanmu adalah khas bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 492, 25, 197, 426, FALSE, 0, NULL),
(43, 36, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًا فَهُوَ لَهُۥ قَرِينٌ', 'وَمَن يَعْشُ عَن ذِكْرِ الرَّحْمَٰنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ', NULL, 'And whoever is blinded from remembrance of the Most Merciful - We appoint for him a devil, and he is to him a companion.', 'Dan sesiapa yang tidak mengindahkan pengajaran (Al-Quran yang diturunkan oleh Allah) Yang maha Pemurah, Kami akan adakan baginya Syaitan (yang menghasut dan menyesatkannya), lalu menjadilah Syaitan itu temannya yang tidak renggang daripadanya.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 37, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ السَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', NULL, 'And indeed, they [i.e., the devils] avert them from the way [of guidance] while they think that they are [rightly] guided', 'Dan sesungguhnya Syaitan-syaitan itu tetap menghalangi mereka dari jalan yang benar, sedang mereka menyangka bahawa mereka orang-orang yang mendapat hidayah petunjuk.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 38, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 'حَتَّىٰ إِذَا جَاءَنَا قَالَ يَا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ الْقَرِينُ', NULL, 'Until, when he comes to Us [at Judgement], he says [to his companion], "How I wish there was between me and you the distance between the east and west; and what a wretched companion."', 'Sehingga apabila ia (yang terjerumus dalam kesesatan itu) datang kepada Kami (pada hari kiamat), berkatalah ia (kepada Syaitannya): “Alangkah baiknya (kalau di dunia dahulu ada sekatan yang memisahkan) antaraku denganmu sejauh timur dengan barat! Kerana (engkau) adalah sejahat-jahat teman”.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 39, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'وَلَن يَنفَعَكُمُ الْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِي الْعَذَابِ مُشْتَرِكُونَ', NULL, 'And never will it benefit you that Day, when you have wronged, that you are [all] sharing in the punishment.', '(Lalu dikatakan kepada mereka): “Pada hari ini, setelah nyata bahawa kamu telah menganiaya diri sendiri, (maka apa yang kamu cita-citakan itu) tidak sekali-kali akan memberi faedah kepada kamu, kerana sesungguhnya kamu dan teman-teman kamu itu tetap menderita bersama-sama di dalam azab”.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 40, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍ مُّبِينٍ', 'أَفَأَنتَ تُسْمِعُ الصُّمَّ أَوْ تَهْدِي الْعُمْيَ وَمَن كَانَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'Then will you make the deaf hear, [O Muḥammad], or guide the blind or he who is in clear error?', 'Maka (mengapa engkau berdukacita wahai Muhammad) adakah engkau berkuasa menjadikan orang-orang yang pekak mendengar, atau menunjuk jalan kepada orang-orang yang buta (mata hatinya), dan juga orang-orang yang berada dalam kesesatan yang nyata?', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 41, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', NULL, 'And whether [or not] We take you away [in death], indeed, We will take retribution upon them.', 'Oleh itu (bertenanglah engkau, kerana) kalaulah Kami wafatkan engkau (sebelum Kami perlihatkan kepadamu azab yang akan menimpa mereka), maka sesungguhnya Kami tetap menyeksakan mereka.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 42, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', 'أَوْ نُرِيَنَّكَ الَّذِي وَعَدْنَاهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', NULL, 'Or whether [or not] We show you that which We have promised them, indeed, We are Perfect in Ability.', 'Atau sekiranya Kami (hendak) memperlihatkan kepadamu apa yang Kami janjikan kepada mereka (dari azab seksa itu), maka Kami tetap berkuasa terhadap mereka.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 43, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'فَاسْتَمْسِكْ بِالَّذِي أُوحِيَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'So adhere to that which is revealed to you. Indeed, you are on a straight path.', 'Dengan yang demikian, berpegang teguhlah engkau kepada Al-Quran yang telah diwahyukan kepadamu; kerana sesungguhnya engkau berada di atas jalan yang lurus.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 44, 'وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْـَٔلُونَ', 'وَإِنَّهُ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْأَلُونَ', NULL, 'And indeed, it is a remembrance for you and your people, and you [all] are going to be questioned.', 'Dan sesungguhnya Al-Quran itu memberikan kemuliaan dan peringatan kepadamu (wahai Muhammad) dan kepada kaummu; dan kamu akan ditanya kelak (tentang isi kandungannya yang kamu telah amalkan).', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 45, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةً يُعْبَدُونَ', 'وَاسْأَلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَا أَجَعَلْنَا مِن دُونِ الرَّحْمَٰنِ آلِهَةً يُعْبَدُونَ', NULL, 'And ask those We sent before you of Our messengers; have We made besides the Most Merciful deities to be worshipped?', 'Dan bertanyalah kepada umat mana-mana Rasul yang Kami telah utuskan sebelummu; pernahkah Kami memberi hukum menetapkan sebarang tuhan untuk disembah, selain dari Allah Yang Maha Pemurah.', FALSE, NULL, NULL, 492, 25, 197, 427, FALSE, 0, NULL),
(43, 46, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِآيَاتِنَا إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ فَقَالَ إِنِّي رَسُولُ رَبِّ الْعَالَمِينَ', NULL, 'And certainly did We send Moses with Our signs to Pharaoh and his establishment, and he said, "Indeed, I am the messenger of the Lord of the worlds."', 'Dan demi sesungguhnya! Kami telah mengutus Nabi Musa dengan membawa mukjizat-mukjizat Kami, kepada Firaun dan kaumnya, lalu ia berkata: “Sesungguhnya aku ini ialah Rasul dari Tuhan sekalian alam”.', FALSE, NULL, NULL, 492, 25, 197, 428, FALSE, 0, NULL),
(43, 47, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 'فَلَمَّا جَاءَهُم بِآيَاتِنَا إِذَا هُم مِّنْهَا يَضْحَكُونَ', NULL, 'But when he brought them Our signs, at once they laughed at them.', 'Maka apabila ia datang kepada mereka dengan membawa tanda-tanda kekuasaan Kami, mereka dengan serta-merta mencemuh dan menggelakkan (apa yang dibawanya) itu.', FALSE, NULL, NULL, 492, 25, 197, 428, FALSE, 0, NULL),
(43, 48, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', 'وَمَا نُرِيهِم مِّنْ آيَةٍ إِلَّا هِيَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَاهُم بِالْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And We showed them not a sign except that it was greater than its sister, and We seized them with affliction that perhaps they might return [to faith].', 'Dan tidaklah Kami memperlihatkan kepada mereka sesuatu tanda kebenaran Nabi Musa melainkan tanda itu adalah lebih terang dari yang terdahulu daripadanya; Dan Kami timpakan mereka dengan berbagai azab (bala bencana), supaya mereka kembali (bertaubat).', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 49, 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 'وَقَالُوا يَا أَيُّهَ السَّاحِرُ ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', NULL, 'And they said [to Moses], "O magician, invoke for us your Lord by what He has promised you. Indeed, we will be guided."', 'Dan (apabila bala bencana itu menimpa mereka), mereka merayu kepada Nabi Musa dengan berkata: “Wahai orang yang bijak pandai, pohonkanlah kepada Tuhanmu keselamatan untuk kami dengan (kemuliaan) pangkat Nabi yang diberikan kepadamu; sesungguhnya kami (sesudah itu) akan patuh beriman”.', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 50, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', 'فَلَمَّا كَشَفْنَا عَنْهُمُ الْعَذَابَ إِذَا هُمْ يَنكُثُونَ', NULL, 'But when We removed from them the affliction, at once they broke their word.', 'Setelah Kami hapuskan azab itu daripada mereka, mereka terus mencabuli janjinya.', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 51, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ أَفَلَا تُبْصِرُونَ', 'وَنَادَىٰ فِرْعَوْنُ فِي قَوْمِهِ قَالَ يَا قَوْمِ أَلَيْسَ لِي مُلْكُ مِصْرَ وَهَٰذِهِ الْأَنْهَارُ تَجْرِي مِن تَحْتِي أَفَلَا تُبْصِرُونَ', NULL, 'And Pharaoh called out among his people; he said, "O my people, does not the kingdom of Egypt belong to me, and these rivers flowing beneath me; then do you not see?', 'Dan Firaun pula menyeru (dengan mengisytiharkan) kepada kaumnya, katanya: “Wahai kaumku! Bukankah kerajaan negeri Mesir ini - akulah yang menguasainya, dan sungai-sungai ini mengalir di bawah (istana) ku? Tidakkah kamu melihatnya?', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 52, 'أَمْ أَنَا۠ خَيْرٌ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', 'أَمْ أَنَا خَيْرٌ مِّنْ هَٰذَا الَّذِي هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', NULL, 'Or am I [not] better than this one [i.e., Moses] who is insignificant and hardly makes himself clear?', '“Bahkan bukankah aku lebih baik daripada orang yang hina keadaannya ini, dan yang hampir-hampir tidak dapat menjelaskan perkataannya?', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 53, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', 'فَلَوْلَا أُلْقِيَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَاءَ مَعَهُ الْمَلَائِكَةُ مُقْتَرِنِينَ', NULL, 'Then why have there not been placed upon him bracelets of gold or come with him the angels in conjunction?"', '“(Kalau betul ia seorang Rasul) maka sepatutnya ia dipakaikan (oleh Tuhannya) gelang-gelang emas (yang menandakan ia seorang pemimpin), atau datang malaikat bersama-sama dengannya (sebagai saksi tentang kebenarannya)?”', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 54, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'فَاسْتَخَفَّ قَوْمَهُ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا قَوْمًا فَاسِقِينَ', NULL, 'So he bluffed his people, and they obeyed him. Indeed, they were [themselves] a people defiantly disobedient [of Allāh].', '(Dengan yang demikian), maka Firaun memperbodohkan kaumnya, lalu mereka mematuhinya; sesungguhnya mereka itu adalah kaum yang fasik - derhaka.', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 55, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'فَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ أَجْمَعِينَ', NULL, 'And when they angered Us, We took retribution from them and drowned them all.', 'Setelah mereka menyebabkan kemurkaan Kami (dengan perbuatan derhaka itu), Kami menyeksa mereka, iaitu menenggelamkan mereka semuanya di laut (sehingga binasa).', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 56, 'فَجَعَلْنَٰهُمْ سَلَفًا وَمَثَلًا لِّلْـَٔاخِرِينَ', 'فَجَعَلْنَاهُمْ سَلَفًا وَمَثَلًا لِّلْآخِرِينَ', NULL, 'And We made them a precedent and an example for the later peoples.', 'Maka kami jadikan mereka contoh dan pengajaran bagi orang-orang yang datang kemudian.', FALSE, NULL, NULL, 493, 25, 197, 428, FALSE, 0, NULL),
(43, 57, 'وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', 'وَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', NULL, 'And when the son of Mary was presented as an example, immediately your people laughed aloud.', 'Dan ketika (nabi Isa) anak Maryam dikemukakan sebagai satu misal perbandingan, (untuk membantahmu wahai Muhammad), tiba-tiba kaummu bersorak-sorak kesukaan terhadapnya (kerana menyangka bahawa mereka telah menang).', FALSE, NULL, NULL, 493, 25, 198, 429, FALSE, 0, NULL),
(43, 58, 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'وَقَالُوا أَآلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًا بَلْ هُمْ قَوْمٌ خَصِمُونَ', NULL, 'And they said, "Are our gods better, or is he?" They did not present it [i.e., the comparison] except for [mere] argument. But, [in fact], they are a people prone to dispute.', 'Dan mereka berkata lagi: “Manakah yang lebih baik, benda-benda yang kami sembah atau Isa?” Dan (sebenarnya) mereka tidak mengemukakan perbandingan itu kepadamu (wahai Muhammad) melainkan kerana membantah semata-mata (bukan kerana mencari kebenaran); bahkan mereka itu adalah kaum yang suka sekali mengemukakan bantahan.', FALSE, NULL, NULL, 493, 25, 198, 429, FALSE, 0, NULL),
(43, 59, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَاهُ مَثَلًا لِّبَنِي إِسْرَائِيلَ', NULL, 'He [i.e., Jesus] was not but a servant upon whom We bestowed favor, and We made him an example for the Children of Israel.', 'Nabi Isa itu tidak lain hanyalah seorang hamba yang telah Kami kurniakan nikmat kepadanya (dengan pangkat Nabi), dan Kami jadikan dia satu contoh (kekuasaan kami yang menakjubkan) bagi kaum Bani Israil.', FALSE, NULL, NULL, 493, 25, 198, 429, FALSE, 0, NULL),
(43, 60, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ', 'وَلَوْ نَشَاءُ لَجَعَلْنَا مِنكُم مَّلَائِكَةً فِي الْأَرْضِ يَخْلُفُونَ', NULL, 'And if We willed, We could have made [instead] of you angels succeeding [one another] on the earth.', 'Dan kalaulah kami kehendaki, kami berkuasa melahirkan daripada kamu (wahai kaum lelaki): malaikat mengganti kamu (menjalankan urusan) di muka bumi.', FALSE, NULL, NULL, 493, 25, 198, 429, FALSE, 0, NULL),
(43, 61, 'وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'وَإِنَّهُ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَاتَّبِعُونِ هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ', NULL, 'And indeed, he [i.e., Jesus] will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path.', 'Dan sesungguhnya Nabi Isa menjadi tanda kedatangan hari kiamat, maka janganlah kamu ragu-ragu tentang (hari kiamat) itu, dan turutlah (petunjukKu); inilah jalan yang lurus.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 62, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'وَلَا يَصُدَّنَّكُمُ الشَّيْطَانُ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ', NULL, 'And never let Satan avert you. Indeed, he is to you a clear enemy.', 'Dan janganlah Syaitan menghalang kamu (daripada menurut jalan yang benar); sesungguhnya Syaitan itu musuh yang nyata bagi kamu.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 63, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'وَلَمَّا جَاءَ عِيسَىٰ بِالْبَيِّنَاتِ قَالَ قَدْ جِئْتُكُم بِالْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ فَاتَّقُوا اللَّهَ وَأَطِيعُونِ', NULL, 'And when Jesus brought clear proofs, he said, "I have come to you with wisdom [i.e., prophethood] and to make clear to you some of that over which you differ, so fear Allāh and obey me.', 'Dan ketika Nabi Isa datang (kepada kaumnya) dengan membawa keterangan-keterangan yang nyata, berkatalah ia: “Sesungguhnya aku datang kepada kamu dengan membawa hikmat (ajaran Tuhan), dan untuk menerangkan kepada kamu: sebahagian dari (perkara-perkara ugama) yang kamu berselisihan padanya. Oleh itu, bertaqwalah kamu kepada Allah dan taatlah kepadaku.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 64, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'إِنَّ اللَّهَ هُوَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَٰذَا صِرَاطٌ مُّسْتَقِيمٌ', NULL, 'Indeed, Allāh is my Lord and your Lord, so worship Him. This is a straight path."', '“Sesungguhnya Allah ialah Tuhanku dan Tuhan kamu, maka sembahlah kamu akan Dia; inilah jalan yang lurus”.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 65, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', 'فَاخْتَلَفَ الْأَحْزَابُ مِن بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', NULL, 'But the denominations from among them differed [and separated], so woe to those who have wronged from the punishment of a painful Day.', 'Kemudian, golongan-golongan (dari kaumnya) itu berselisihan sesama sendiri. Maka kecelakaan dan kebinasaanlah bagi orang-orang yang zalim itu, dari (paluan) azab seksa yang tidak terperi sakitnya, pada hari pembalasan.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 66, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'هَلْ يَنظُرُونَ إِلَّا السَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', NULL, 'Are they waiting except for the Hour to come upon them suddenly while they perceive not?', '(Mereka yang menentang Nabi Muhammad) tidak ada lagi yang mereka tunggu melainkan saat kiamat yang akan datang kepada mereka secara mengejut, dan dalam keadaan mereka lalai leka dengan perkara-perkara keduniaan.', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 67, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', 'الْأَخِلَّاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا الْمُتَّقِينَ', NULL, 'Close friends, that Day, will be enemies to each other, except for the righteous', 'Pada hari itu sahabat-sahabat karib: setengahnya akan menjadi musuh kepada setengahnya yang lain, kecuali orang-orang yang persahabatannya berdasarkan taqwa (iman dan amal soleh).', FALSE, NULL, NULL, 494, 25, 198, 429, FALSE, 0, NULL),
(43, 68, 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', 'يَا عِبَادِ لَا خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلَا أَنتُمْ تَحْزَنُونَ', NULL, '[To whom Allāh will say], "O My servants, no fear will there be concerning you this Day, nor will you grieve,', '(Mereka - yang bertaqwa - itu, diberi penghormatan serta diseru oleh Allah Taala dengan firmanNya): “Wahai hamba-hambaku! Pada hari ini kamu tidak akan merasai sebarang kebimbangan (dari sesuatu yang tidak baik); dan kamu pula tidak akan berdukacita”.', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 69, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 'الَّذِينَ آمَنُوا بِآيَاتِنَا وَكَانُوا مُسْلِمِينَ', NULL, '[You] who believed in Our verses and were Muslims.', '(Mereka itu ialah) orang-orang yang beriman akan ayat-ayat keterangan Kami, serta mereka menjadi orang-orang Islam yang taat patuh,', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 70, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', 'ادْخُلُوا الْجَنَّةَ أَنتُمْ وَأَزْوَاجُكُمْ تُحْبَرُونَ', NULL, 'Enter Paradise, you and your kinds, delighted."', '(Mereka diberi sebaik-baik balasan dengan dikatakan kepada mereka): “Masuklah kamu ke dalam Syurga bersama-sama isteri-isteri kamu (yang beriman), dengan menikmati sepenuh-penuh kegembiraan dan kesenangan”.', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 71, 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ وَأَنتُمْ فِيهَا خَٰلِدُونَ', 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ الْأَنفُسُ وَتَلَذُّ الْأَعْيُنُ وَأَنتُمْ فِيهَا خَالِدُونَ', NULL, 'Circulated among them will be plates and vessels of gold. And therein is whatever the souls desire and [what] delights the eyes, and you will abide therein eternally.', 'Diedarkan kepada mereka pinggan-pinggan besar dan piala-piala dari emas; dan di dalam Syurga itu pula disediakan segala yang diingini oleh nafsu serta di pandang indah oleh mata; dan (dikatakan kepada mereka): “Kamu adalah tetap kekal di dalamnya”.', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 72, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', NULL, 'And that is Paradise which you are made to inherit for what you used to do.', 'Dan (dikatakan lagi kepada mereka): “Inilah Syurga yang diberikan kamu mewarisinya, disebabkan apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 73, 'لَكُمْ فِيهَا فَٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', 'لَكُمْ فِيهَا فَاكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', NULL, 'For you therein is much fruit from which you will eat.', '“Kamu beroleh di dalamnya berbagai jenis buah-buahan, untuk kamu makan daripadanya”.', FALSE, NULL, NULL, 494, 25, 198, 430, FALSE, 0, NULL),
(43, 74, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', 'إِنَّ الْمُجْرِمِينَ فِي عَذَابِ جَهَنَّمَ خَالِدُونَ', NULL, 'Indeed, the criminals will be in the punishment of Hell, abiding eternally.', '“Sesungguhnya orang-orang yang berdosa (dengan kekufurannya), kekal selama-lamanya di dalam azab seksa neraka Jahannam.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', NULL, 'It will not be allowed to subside for them, and they, therein, are in despair.', 'Tidak diringankan azab itu daripada mereka, dan mereka tinggal menderitainya dengan berputus asa (daripada mendapat sebarang pertolongan),', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 76, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', 'وَمَا ظَلَمْنَاهُمْ وَلَٰكِن كَانُوا هُمُ الظَّالِمِينَ', NULL, 'And We did not wrong them, but it was they who were the wrongdoers.', 'Dan tidaklah kami menganiaya mereka, akan tetapi merekalah yang menganiaya diri sendiri.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 77, 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّٰكِثُونَ', 'وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّاكِثُونَ', NULL, 'And they will call, "O Mālik, let your Lord put an end to us!" He will say, "Indeed, you will remain."', 'Dan mereka menyeru (ketua malaikat penjaga neraka, dengan berkata): “Wahai Malik! Biarlah hendaknya Tuhanmu mematikan kami (kerana kami tidak tahan menderita)!” Maalik menjawab: “Sesungguhnya kamu tetap kekal di dalam azab!”', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 78, 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', 'لَقَدْ جِئْنَاكُم بِالْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَارِهُونَ', NULL, 'We had certainly brought you the truth, but most of you, to the truth, were averse.', '(Bagi menyatakan sebabnya mereka dibiarkan di dalam azab, Allah Taala berfirman): “Demi sesungguhnya! Kami telah menyampaikan kebenaran kepada kamu (melalui Rasul Kami), akan tetapi kebanyakan kamu (telah menentangnya, kerana kamu) tidak suka kepada kebenaran itu”.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 79, 'أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ', 'أَمْ أَبْرَمُوا أَمْرًا فَإِنَّا مُبْرِمُونَ', NULL, 'Or have they devised [some] affair? But indeed, We are devising [a plan].', 'Bahkan mereka (yang kafir) itu telah mengambil keputusan menjalankan satu rancangan (hendak membunuh Rasul Kami), maka Kami juga mengambil keputusan (menggagalkan rancangan mereka).', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 80, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَاهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', NULL, 'Or do they think that We hear not their secrets and their private conversations? Yes, [We do], and Our messengers [i.e., angels] are with them recording.', 'Patutkah mereka menyangka bahawa Kami tidak mendengar apa yang mereka sembunyikan (di dalam hati) dan apa yang mereka perkatakan (dengan berbisik) sesama sendiri? (Bukan sebagaimana yang mereka sangka) bahkan utusan-utusan Kami (malaikat) yang menjaga mereka, ada menulis segala yang mereka lakukan.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 81, 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا أَوَّلُ الْعَابِدِينَ', NULL, 'Say, [O Muḥammad], "If the Most Merciful had a son, then I would be the first of [his] worshippers."', 'Katakanlah (Wahai Muhammad, kepada mereka yang musyrik itu): “Kalau betul Allah yang maha pemurah, mempunyai anak (sebagaimana yang kamu dakwakan) maka akulah orang yang awal pertama yang akan menyembah anak itu; (tetapi dakwaan kamu itu tidak berasas)!”', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 82, 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'سُبْحَانَ رَبِّ السَّمَاوَاتِ وَالْأَرْضِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ', NULL, 'Exalted is the Lord of the heavens and the earth, Lord of the Throne, above what they describe.', 'Maha Suci Allah Tuhan yang menciptakan langit dan bumi, - tuhan yang mempunyai Arasy (yang melambangkan kebesarannya), - (Maha Sucilah Ia) dari apa yang mereka katakan itu.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 83, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّىٰ يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ', NULL, 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised.', 'Oleh itu, biarkanlah mereka (wahai Muhammad) tenggelam dalam kesesatan mereka dan leka bermain-main (dalam dunia mereka), sehingga mereka menemui hari yang dijanjikan kepada mereka (untuk menerima balasan).', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 84, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌ وَفِى ٱلْأَرْضِ إِلَٰهٌ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'وَهُوَ الَّذِي فِي السَّمَاءِ إِلَٰهٌ وَفِي الْأَرْضِ إِلَٰهٌ وَهُوَ الْحَكِيمُ الْعَلِيمُ', NULL, 'And it is He [i.e., Allāh] who is [the only] deity in the heaven, and on the earth [the only] deity. And He is the Wise, the Knowing.', 'Dan (ingatlah), Allah jualah Tuhan yang berhak disembah di langit, dan Dia lah Tuhan yang berhak disembah di bumi; dan Dia lah jua Yang Maha Bijaksana, lagi Maha Mengetahui.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 85, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', 'وَتَبَارَكَ الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُ عِلْمُ السَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', NULL, 'And blessed is He to whom belongs the dominion of the heavens and the earth and whatever is between them and with whom is knowledge of the Hour and to whom you will be returned.', 'Dan Maha Tinggilah Kebesaran Tuhan yang menguasai langit dan bumi serta segala yang ada di antara keduanya; dan Dia lah jua yang mengetahui tentang (masa datangnya) hari kiamat; dan kepadanyalah kamu semua akan dikembalikan.', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 86, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'وَلَا يَمْلِكُ الَّذِينَ يَدْعُونَ مِن دُونِهِ الشَّفَاعَةَ إِلَّا مَن شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ', NULL, 'And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know.', 'Dan segala yang mereka sembah yang lain dari Allah, tidak mempunyai sebarang kuasa untuk memberikan syafaat pertolongan, kecuali sesiapa yang memberi penerangan mengakui kebenaran dengan mentauhidkan Allah, Tuhan Yang Sebenar-benarnya secara mereka mengetahuiNya dengan yakin (bukan dengan kata-kata orang; maka merekalah yang mungkin diizinkan memberi dan mendapat syafaat itu).', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 87, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', NULL, 'And if you asked them who created them, they would surely say, "Allāh." So how are they deluded?', 'Dan demi sesungguhnya! Jika engkau (wahai Muhammad) bertanya kepada mereka: “Siapakah yang menciptakan mereka?” Sudah tentu mereka akan menjawab: “Allah!”. (Jika demikian) maka bagaimana mereka rela dipesongkan (dari menyembah dan mengesakanNya)?', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 88, 'وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمٌ لَّا يُؤْمِنُونَ', 'وَقِيلِهِ يَا رَبِّ إِنَّ هَٰؤُلَاءِ قَوْمٌ لَّا يُؤْمِنُونَ', NULL, 'And [Allāh acknowledges] his saying, "O my Lord, indeed these are a people who do not believe."', 'Dan (Dia lah Tuhan yang Mengetahui rayuan Nabi Muhammad) yang berkata: Wahai TuhanKu! Sesungguhnya mereka ini adalah satu kaum yang tidak mahu beriman (maka terserahlah kepadaMu untuk mengadilinya)!”', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(43, 89, 'فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌ فَسَوْفَ يَعْلَمُونَ', 'فَاصْفَحْ عَنْهُمْ وَقُلْ سَلَامٌ فَسَوْفَ يَعْلَمُونَ', NULL, 'So turn aside from them and say, "Peace." But they are going to know.', '(Tuhan menjawab rayuannya dengan berfirman): “Jika demikian, maka janganlah engkau (wahai Muhammad) hiraukan mereka, dan katakanlah: ‘Selamat tinggallah!’ Kemudian mereka akan mengetahui kelak (akibat keingkarannya)!”', FALSE, NULL, NULL, 495, 25, 198, 430, FALSE, 0, NULL),
(44, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 1, NULL),
(44, 2, 'وَٱلْكِتَـٰبِ ٱلْمُبِينِ', 'والكتاب المبين', NULL, 'By the clear Book,', 'Demi Al-Quran Kitab yang menerangkan kebenaran.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 2, NULL),
(44, 3, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةٍ مُّبَـٰرَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ', 'انا انزلناه في ليلة مباركة انا كنا منذرين', NULL, 'Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind].', 'Sesungguhnya Kami telah menurunkan Al-Quran itu pada malam yang berkat; (Kami berbuat demikian) kerana sesungguhnya Kami sentiasa memberi peringatan dan amaran (jangan hamba-hamba Kami ditimpa azab).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 8, NULL),
(44, 4, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', 'فيها يفرق كل امر حكيم', NULL, 'Therein [i.e., on that night] is made distinct every precise matter -', '(Kami menurunkan Al-Quran pada malam yang tersebut, kerana) pada malam yang berkat itu, dijelaskan (kepada malaikat) tiap-tiap perkara yang mengandungi hikmat serta tetap berlaku, (tidak berubah atau bertukar).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 5, NULL),
(44, 5, 'أَمْرًا مِّنْ عِندِنَآ ۚ إِنَّا كُنَّا مُرْسِلِينَ', 'امرا من عندنا انا كنا مرسلين', NULL, '[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]', 'Iaitu perkara-perkara yang terbitnya dari hikmat kebijaksanaan Kami; sesungguhnya telah menjadi adat Kami mengutus Rasul.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 6, 'رَحْمَةً مِّن رَّبِّكَ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'رحمة من ربك انه هو السميع العليم', NULL, 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing,', '(Untuk menyampaikan) rahmat dari Tuhanmu (kepada umat manusia); sesungguhnya Allah Jualah Yang Maha Mendengar, lagi Maha Mengetahui (akan segala keadaan hamba-hambaNya).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 7, NULL),
(44, 7, 'رَبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', 'رب السماوات والارض وما بينهما ان كنتم موقنين', NULL, 'Lord of the heavens and the earth and that between them, if you would be certain.', 'Tuhan (yang mencipta dan mentadbirkan keadaan) langit dan bumi serta segala yang ada di antara keduanya; kalau betul kamu orang-orang yang yakin (akan hakikat itu, maka terimalah sahaja apa yang diutuskan kepada kamu).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 8, NULL),
(44, 8, 'لَآ إِلَـٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'لا اله الا هو يحيي ويميت ربكم ورب ابائكم الاولين', NULL, 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.', 'Tiada Tuhan yang berhak disembah melainkan Dia; Dia lah Yang menghidupkan dan Yang mematikan; (Dia lah jua) Tuhan kamu dan Tuhan datuk nenek kamu yang telah lalu.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 10, NULL),
(44, 9, 'بَلْ هُمْ فِى شَكٍّ يَلْعَبُونَ', 'بل هم في شك يلعبون', NULL, 'But they are in doubt, amusing themselves.', '(Mereka tidak meyakini kebenaran yang dijelaskan kepada mereka), bahkan mereka masih tenggelam dalam keraguan sambil bermain-main dengan perkara ugama.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 5, NULL),
(44, 10, 'فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍ مُّبِينٍ', 'فارتقب يوم تاتي السماء بدخان مبين', NULL, 'Then watch for the Day when the sky will bring a visible smoke', 'Oleh itu tunggulah (wahai Muhammad) semasa langit membawa asap kemarau yang jelas nyata (yang menyebabkan kebuluran yang dahsyat),', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 11, 'يَغْشَى ٱلنَّاسَ ۖ هَـٰذَا عَذَابٌ أَلِيمٌ', 'يغشى الناس هذا عذاب اليم', NULL, 'Covering the people; this is a painful torment.', 'Yang akan menimpa seluruh keadaan manusia (yang kafir itu, sehingga mereka akan berkata: “Ini adalah azab yang sungguh menyakitkan”.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 5, NULL),
(44, 12, 'رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ', 'ربنا اكشف عنا العذاب انا مؤمنون', NULL, '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."', '(Pada saat itu mereka akan merayu dengan berkata): “Wahai Tuhan kami! Hapuskanlah azab ini dari kami, sesungguhnya kami akan beriman!”.', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 13, 'أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌ مُّبِينٌ', 'انى لهم الذكرى وقد جاءهم رسول مبين', NULL, 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.', 'Bagaimana mereka dapat beringat (menyempurnakan janji mereka hendak beriman itu)? Pada hal mereka telah pun didatangi seorang Rasul yang memberi keterangan-keterangan (yang cukup untuk mereka beriman)!', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 7, NULL),
(44, 14, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ', 'ثم تولوا عنه وقالوا معلم مجنون', NULL, 'Then they turned away from him and said, "[He was] taught [and is] a madman."', 'Sekalipun demikian, mereka juga berpaling ingkar daripada menerima keterangannya sambil berkata (sesama sendiri): “Dia seorang yang diajar (oleh bangsa asing), dia juga seorang yang gila!”', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 15, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا ۚ إِنَّكُمْ عَآئِدُونَ', 'انا كاشفو العذاب قليلا انكم عائدون', NULL, 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].', 'Sesungguhnya (kalaulah) kami hapuskan azab itu barang sedikitpun, sudah tentu kamu akan kembali (kufur ingkar).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 16, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 'يوم نبطش البطشة الكبرى انا منتقمون', NULL, 'The Day We will strike with the greatest assault, indeed, We will take retribution.', '(Ingatlah! Kalau kamu ulangi keingkaran kamu, kamu akan dibinasakan) semasa Kami timpakan (kamu dengan) paluan yang besar (dari pihak lawan kamu); sesungguhnya Kami tetap akan menyeksa (dengan azab yang seberat-beratnya).', FALSE, NULL, NULL, 496, 25, 198, 431, FALSE, 6, NULL),
(44, 17, '۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ', 'ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم', NULL, 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger [i.e., Moses],', 'Dan demi sesungguhnya! Sebelum mereka, Kami telah menguji kaum Firaun, dan merekapun telah didatangi oleh seorang Rasul (Nabi Musa) Yang mulia, -', FALSE, NULL, NULL, 496, 25, 199, 431, FALSE, 8, NULL),
(44, 18, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ ۖ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ان ادوا الي عباد الله اني لكم رسول امين', NULL, '[Saying], "Render to me the servants of Allāh. Indeed, I am to you a trustworthy messenger,"', '(Yang memberitahu kepada mereka dengan katanya): Berikanlah kepadaku wahai hamba-hamba Allah (apa-apa yang menandakan kamu menerima kerasulanku); sesungguhnya aku ini seorang Rasul yang amanah, yang diutuskan kepada kamu.', FALSE, NULL, NULL, 496, 25, 199, 431, FALSE, 9, NULL),
(44, 19, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ ۖ إِنِّىٓ ءَاتِيكُم بِسُلْطَـٰنٍ مُّبِينٍ', 'وان لا تعلوا على الله اني اتيكم بسلطان مبين', NULL, 'And [saying], "Be not haughty with Allāh. Indeed, I have come to you with clear evidence.', '“Dan janganlah kamu berlaku sombong takbur terhadap Allah; sesungguhnya aku ada membawa kepada kamu mukjizat yang jelas nyata.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 9, NULL),
(44, 20, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', 'واني عذت بربي وربكم ان ترجمون', NULL, 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.', '“Dan sesungguhnya aku telah memohon perlindungan kepada Tuhanku dan Tuhan kamu, daripada kamu merejam (atau menyakiti) daku.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 6, NULL),
(44, 21, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', 'وَإِن لَّمْ تُؤْمِنُوا لِي فَاعْتَزِلُونِ', NULL, 'But if you do not believe me, then leave me alone."', '“Dan sekiranya kamu tidak juga mahu berimankan kerasulanku, maka putuskanlah perhubungan kamu denganku (janganlah mengganggu daku).”', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 22, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمٌ مُّجْرِمُونَ', 'فَدَعَا رَبَّهُ أَنَّ هَٰؤُلَاءِ قَوْمٌ مُّجْرِمُونَ', NULL, 'And [finally] he called to his Lord that these were a criminal people.', '(Setelah Nabi Musa berputus asa daripada iman mereka), maka ia pun merayu kepada Tuhannya lalu berkata: “Sesungguhnya orang-orang ini adalah kaum yang berdosa, (yang telah sebati dengan kekufurannya, dan berhaklah mereka menerima balasan yang seburuk-buruknya)”.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 23, 'فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ', 'فَأَسْرِ بِعِبَادِي لَيْلًا إِنَّكُم مُّتَّبَعُونَ', NULL, '[Allāh said], "Then set out with My servants by night. Indeed, you are to be pursued.', 'Lalu (diperintahkan kepadanya): “Bawalah hamba-hambaku (pengikut-pengikutmu) keluar pada waktu malam, kerana sesungguhnya kamu akan dikejar (oleh Firaun dan orang-orangnya).', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 24, 'وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا إِنَّهُمْ جُندٌ مُّغْرَقُونَ', 'وَاتْرُكِ الْبَحْرَ رَهْوًا إِنَّهُمْ جُندٌ مُّغْرَقُونَ', NULL, 'And leave the sea in stillness. Indeed, they are an army to be drowned."', '“Dan tinggalkanlah laut itu dalam keadaan tenang - terbelah, kerana sesungguhnya mereka (yang mengejarmu itu) ialah tentera yang akan ditenggelamkan (sehingga binasa)”.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 25, 'كَمْ تَرَكُوا۟ مِن جَنَّٰتٍ وَعُيُونٍ', 'كَمْ تَرَكُوا مِن جَنَّاتٍ وَعُيُونٍ', NULL, 'How much they left behind of gardens and springs', 'Banyak sungguh kebun-kebun dan matair, mereka tinggalkan,', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 26, 'وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ', 'وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ', NULL, 'And crops and noble sites', 'Dan juga berbagai jenis tanaman serta tempat-tempat kediaman yang indah - mulia,', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 27, 'وَنَعْمَةٍ كَانُوا۟ فِيهَا فَٰكِهِينَ', 'وَنَعْمَةٍ كَانُوا فِيهَا فَاكِهِينَ', NULL, 'And comfort wherein they were amused.', 'Dan juga kemewahan hidup, yang mereka sekian lama menikmatinya.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 28, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا قَوْمًا ءَاخَرِينَ', 'كَذَٰلِكَ وَأَوْرَثْنَاهَا قَوْمًا آخَرِينَ', NULL, 'Thus. And We caused to inherit it another people.', 'Demikianlah keadaannya (hukum Kami ke atas orang-orang yang derhaka); dan Kami jadikan semua peninggalan Firaun dan orang-orangnya: milik kaum yang lain (kaum Bani Israil).', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 29, 'فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ', 'فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ وَمَا كَانُوا مُنظَرِينَ', NULL, 'And the heaven and earth wept not for them, nor were they reprieved.', 'Mereka (ketika dibinasakan) itu tidak ditangisi oleh langit dan bumi (atau penduduk keduanya) dan mereka pula tidak diberi tempoh lagi.', FALSE, NULL, NULL, 497, 25, 199, 431, FALSE, 0, NULL),
(44, 30, 'وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ', 'وَلَقَدْ نَجَّيْنَا بَنِي إِسْرَائِيلَ مِنَ الْعَذَابِ الْمُهِينِ', NULL, 'And We certainly saved the Children of Israel from the humiliating torment -', 'Dan demi sesungguhnya! Kami telah selamatkan kaum Bani Israil, dari azab yang menghina, -', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 31, 'مِن فِرْعَوْنَ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ', 'مِن فِرْعَوْنَ إِنَّهُ كَانَ عَالِيًا مِّنَ الْمُسْرِفِينَ', NULL, 'From Pharaoh. Indeed, he was a haughty one among the transgressors.', 'Dari penindasan Firaun, sesungguhnya ia adalah seorang yang sombong takbur lagi terbilang dari orang-orang yang melampaui batas (dalam keganasan dan kekejamannya).', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 32, 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 'وَلَقَدِ اخْتَرْنَاهُمْ عَلَىٰ عِلْمٍ عَلَى الْعَالَمِينَ', NULL, 'And We certainly chose them by knowledge over [all] the worlds.', 'Dan demi sesungguhnya! Kami telah memilih mereka dengan berdasarkan pengetahuan (Kami) - menjadi lebih pangkatnya dari penduduk dunia (pada zaman itu),', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 33, 'وَءَاتَيْنَٰهُم مِّنَ ٱلْـَٔايَٰتِ مَا فِيهِ بَلَٰٓؤٌا۟ مُّبِينٌ', 'وَآتَيْنَاهُم مِّنَ الْآيَاتِ مَا فِيهِ بَلَاءٌ مُّبِينٌ', NULL, 'And We gave them of signs that in which there was a clear trial.', 'Dan Kami berikan kepada mereka (melalui Nabi Musa) berbagai mukjizat yang mengandungi ujian yang jelas nyata (untuk melahirkan sikap mereka).', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 34, 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', 'إِنَّ هَٰؤُلَاءِ لَيَقُولُونَ', NULL, 'Indeed, these [disbelievers] are saying,', '(Berbalik kepada kisah kaum musyrik penduduk Makkah, Allah berfirman): “Sesungguhnya mereka ini akan berkata (kepadamu - wahai Muhammad dan kepada pengikut-pengikutmu):', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 35, 'إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', 'إِنْ هِيَ إِلَّا مَوْتَتُنَا الْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', NULL, '"There is not but our first death, and we will not be resurrected.', '“Mati, hanyalah mati kita yang pertama (di dunia), dan kita tidak sekali-kali akan dibangkitkan hidup lagi (sesudah itu);', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 36, 'فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'فَأْتُوا بِآبَائِنَا إِن كُنتُمْ صَادِقِينَ', NULL, 'Then bring [back] our forefathers, if you should be truthful."', '“(Jika tidak) maka bawakanlah datuk nenek kami (yang telah mati) kalau betul kamu orang-orang yang benar!”', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 37, 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَٱلَّذِينَ مِن قَبْلِهِمْ أَهْلَكْنَٰهُمْ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَالَّذِينَ مِن قَبْلِهِمْ أَهْلَكْنَاهُمْ إِنَّهُمْ كَانُوا مُجْرِمِينَ', NULL, 'Are they better or the people of Tubbaʿ and those before them? We destroyed them, [for] indeed, they were criminals.', '(Mengapa mereka masih berdegil dalam kekufurannya?) Adakah mereka yang lebih kekuatan dan kehandalannya atau kaum “Tubba''” dan orang-orang yang terdahulu dari mereka? Orang-orang itu semuanya Kami telah binasakan, kerana sesungguhnya mereka adalah orang-orang yang berdosa.', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 38, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 'وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ', NULL, 'And We did not create the heavens and earth and that between them in play.', 'Dan tidaklah Kami menciptakan langit dan bumi serta segala yang ada di antara keduanya, secara main-main;', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 39, 'مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'مَا خَلَقْنَاهُمَا إِلَّا بِالْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'We did not create them except in truth, but most of them do not know.', 'Tidaklah Kami menciptakan keduanya (serta segala yang ada di antaranya) melainkan kerana menzahirkan perkara-perkara yang benar; akan tetapi kebanyakan mereka tidak mengetahui (hakikat itu).', FALSE, NULL, NULL, 497, 25, 199, 432, FALSE, 0, NULL),
(44, 40, 'إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَٰتُهُمْ أَجْمَعِينَ', 'إِنَّ يَوْمَ الْفَصْلِ مِيقَاتُهُمْ أَجْمَعِينَ', NULL, 'Indeed, the Day of Judgement is the appointed time for them all -', 'Sesungguhnya hari pemutusan hukum untuk memberi balasan, ialah masa untuk mereka semua berhimpun, -', FALSE, NULL, NULL, 498, 25, 199, 432, FALSE, 0, NULL),
(44, 41, 'يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًى شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', 'يَوْمَ لَا يُغْنِي مَوْلًى عَن مَّوْلًى شَيْئًا وَلَا هُمْ يُنصَرُونَ', NULL, 'The Day when no relation will avail a relation at all, nor will they be helped -', 'Iaitu hari seseorang kerabat atau sahabat karib tidak dapat memberikan sebarang perlindungan kepada seseorang kerabat atau sahabat karibnya, dan mereka pula tidak akan diberikan pertolongan (untuk menghapuskan azab itu),', FALSE, NULL, NULL, 498, 25, 199, 432, FALSE, 0, NULL),
(44, 42, 'إِلَّا مَن رَّحِمَ ٱللَّهُ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'إِلَّا مَن رَّحِمَ اللَّهُ إِنَّهُ هُوَ الْعَزِيزُ الرَّحِيمُ', NULL, 'Except those [believers] on whom Allāh has mercy. Indeed, He is the Exalted in Might, the Merciful.', 'Kecuali orang yang telah diberi rahmat oleh Allah; sesungguhnya Allah jualah yang Maha Kuasa, lagi Maha Mengasihani.', FALSE, NULL, NULL, 498, 25, 199, 432, FALSE, 0, NULL),
(44, 43, 'إِنَّ شَجَرَتَ ٱلزَّقُّومِ', 'إِنَّ شَجَرَتَ الزَّقُّومِ', NULL, 'Indeed, the tree of zaqqūm', '(Ingatlah), sesungguhnya pokok Zaqqum, -', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 44, 'طَعَامُ ٱلْأَثِيمِ', 'طَعَامُ الْأَثِيمِ', NULL, 'Is food for the sinful.', '(Buahnya) menjadi makanan bagi orang yang berdosa (dalam neraka).', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 45, 'كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ', 'كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ', NULL, 'Like murky oil, it boils within bellies', '(Makanan ini pula panas) seperti tembaga cair, mendidih dalam perut, -', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 46, 'كَغَلْىِ ٱلْحَمِيمِ', 'كَغَلْيِ الْحَمِيمِ', NULL, 'Like the boiling of scalding water.', 'Seperti mendidihnya air yang meluap-luap panasnya.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 47, 'خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ', 'خُذُوهُ فَاعْتِلُوهُ إِلَىٰ سَوَاءِ الْجَحِيمِ', NULL, '[It will be commanded], "Seize him and drag him into the midst of the Hellfire,', '(Lalu diperintahkan kepada malaikat penjaga neraka): “Renggutlah orang yang berdosa itu dan seretlah dia ke tengah-tengah neraka.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 48, 'ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ', 'ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ', NULL, 'Then pour over his head from the torment of scalding water."', '“Kemudian curahkanlah di atas kepalanya - azab seksa - dari air panas yang menggelegak”.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 49, 'ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ', 'ذُقْ إِنَّكَ أَنتَ الْعَزِيزُ الْكَرِيمُ', NULL, '[It will be said], "Taste! Indeed, you are the honored, the noble!', '(Serta dikatakan kepadanya secara mengejek): “Rasalah azab seksa, sebenarnya engkau adalah orang yang berpengaruh dan terhormat (dalam kalangan masyarakatmu)”', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 50, 'إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ', 'إِنَّ هَٰذَا مَا كُنتُم بِهِ تَمْتَرُونَ', NULL, 'Indeed, this is what you used to dispute."', '(Kemudian dikatakan kepada ahli neraka umumnya): “Sesungguhnya inilah dia (azab seksa) yang kamu dahulu ragu-ragu terhadapnya!”', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 51, 'إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍ', 'إِنَّ الْمُتَّقِينَ فِي مَقَامٍ أَمِينٍ', NULL, 'Indeed, the righteous will be in a secure place:', 'Sesungguhnya orang-orang yang bertaqwa (akan ditempatkan) di tempat tinggal yang aman sentosa. -', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 52, 'فِى جَنَّٰتٍ وَعُيُونٍ', 'فِي جَنَّاتٍ وَعُيُونٍ', NULL, 'Within gardens and springs,', 'Ia itu di dalam beberapa taman Syurga, dengan matair-matair terpancar padanya,', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 53, 'يَلْبَسُونَ مِن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَقَٰبِلِينَ', 'يَلْبَسُونَ مِن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَقَابِلِينَ', NULL, 'Wearing [garments of] fine silk and brocade, facing each other.', 'Mereka memakai pakaian dari kain sutera yang halus dan kain sutera tebal yang bersulam; (mereka duduk di tempat perhimpunan) sentiasa berhadap-hadapan (di atas pelamin masing-masing).', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 54, 'كَذَٰلِكَ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍ', 'كَذَٰلِكَ وَزَوَّجْنَاهُم بِحُورٍ عِينٍ', NULL, 'Thus. And We will marry them to fair women with large, [beautiful] eyes.', 'Demikianlah keadaannya; dan Kami jadikan kawan teman mereka bidadari-bidadari yang putih melepak, lagi luas cantik matanya.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 55, 'يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ', 'يَدْعُونَ فِيهَا بِكُلِّ فَاكِهَةٍ آمِنِينَ', NULL, 'They will call therein for every [kind of] fruit - safe and secure.', 'Mereka meminta - di dalam Syurga itu - tiap-tiap jenis buah-buahan (yang mereka ingini), dalam keadaan aman sentosa.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 56, 'لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ', 'لَا يَذُوقُونَ فِيهَا الْمَوْتَ إِلَّا الْمَوْتَةَ الْأُولَىٰ وَوَقَاهُمْ عَذَابَ الْجَحِيمِ', NULL, 'They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire', 'Mereka tidak merasai kematian dalam Syurga itu selain daripada mati yang mereka rasai (di dunia) dahulu; dan Allah selamatkan mereka dari azab neraka;', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 57, 'فَضْلًا مِّن رَّبِّكَ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'فَضْلًا مِّن رَّبِّكَ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ', NULL, 'As bounty from your Lord. That is what is the great attainment.', '(Mereka diberikan semuanya itu) sebagai limpah kurnia dari Tuhanmu (wahai Muhammad); yang demikian itulah kemenangan yang besar.', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 58, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', NULL, 'And indeed, We have eased it [i.e., the Qur’ān] in your tongue that they might be reminded.', 'Maka sesungguhnya tujuan Kami memudahkan Al-Quran dengan bahasamu (wahai Muhammad), ialah supaya mereka (yang memahaminya) beringat dan insaf (untuk beriman dan mematuhinya).', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(44, 59, 'فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', 'فَارْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', NULL, 'So watch, [O Muḥammad]; indeed, they are watching [for your end].', '(Kiranya mereka tidak berbuat demikian) maka tunggulah (wahai Muhammad akan kesudahan mereka), sesungguhnya mereka juga menunggu (akan kesudahanmu).', FALSE, NULL, NULL, 498, 25, 199, 433, FALSE, 0, NULL),
(45, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 1, NULL),
(45, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'تنزيل الكتاب من الله العزيز الحكيم', NULL, 'The revelation of the Book is from Allāh, the Exalted in Might, the Wise.', 'Turunnya Al-Quran ini, dari Allah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 6, NULL),
(45, 3, 'إِنَّ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّلْمُؤْمِنِينَ', 'ان في السماوات والارض لايات للمؤمنين', NULL, 'Indeed, within the heavens and earth are signs for the believers.', 'Sesungguhnya pada langit dan bumi terdapat tanda-tanda (yang membuktikan kekuasaan Allah) bagi orang-orang yang beriman.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 6, NULL),
(45, 4, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَـٰتٌ لِّقَوْمٍ يُوقِنُونَ', 'وفي خلقكم وما يبث من دابة ايات لقوم يوقنون', NULL, 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].', 'Dan pada kejadian diri kamu sendiri, serta (pada kejadian) segala binatang yang dibiakkanNya, terdapat juga tanda-tanda (yang membuktikan kekuasaan Allah) bagi orang-orang yang meyakininya.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 9, NULL),
(45, 5, 'وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَـٰحِ ءَايَـٰتٌ لِّقَوْمٍ يَعْقِلُونَ', 'واختلاف الليل والنهار وما انزل الله من السماء من رزق فاحيا به الارض بعد موتها وتصريف الرياح ايات لقوم يعقلون', NULL, 'And [in] the alternation of night and day and [in] what Allāh sends down from the sky of provision [i.e., rain] and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.', 'Dan (pada) pertukaran malam dan siang silih berganti, dan juga (pada) rezeki yang diturunkan oleh Allah dari langit, lalu Ia hidupkan dengannya tumbuh-tumbuhan di bumi sesudah matinya, serta (pada) peredaran angin, (semuanya itu mengandungi) tanda-tanda (yang membuktikan keesaan Allah, kekuasaanNya, kebijaksanaanNya, serta keluasan rahmatNya) bagi kaum yang mahu menggunakan akal fikiran.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 20, NULL),
(45, 6, 'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَـٰتِهِۦ يُؤْمِنُونَ', 'تلك ايات الله نتلوها عليك بالحق فباي حديث بعد الله واياته يؤمنون', NULL, 'These are the verses of Allāh which We recite to you in truth. Then in what statement after Allāh and His verses will they believe?', 'Itulah ayat-ayat penerangan Allah yang kami bacakan kepadamu (wahai Muhammad) kerana menegakkan kebenaran; maka dengan perkataan yang manakah lagi mereka hendak beriman, sesudah penerangan Allah dan tanda-tanda kekuasaanNya (mereka tidak mahu memahami dan menelitinya)?', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 12, NULL),
(45, 7, 'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ', 'ويل لكل افاك اثيم', NULL, 'Woe to every sinful liar', 'Kecelakaanlah bagi tiap-tiap pendusta yang berdosa, -', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 4, NULL),
(45, 8, 'يَسْمَعُ ءَايَـٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', 'يسمع ايات الله تتلى عليه ثم يصر مستكبرا كان لم يسمعها فبشره بعذاب اليم', NULL, 'Who hears the verses of Allāh recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.', 'Yang mendengar ayat-ayat penerangan Allah sentiasa dibacakan kepadanya, kemudian dia terus berlagak sombong (enggan menerimanya), seolah-olah ia tidak mendengarnya; oleh itu gembirakanlah dia dengan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 14, NULL),
(45, 9, 'وَإِذَا عَلِمَ مِنْ ءَايَـٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا ۚ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'واذا علم من اياتنا شيئا اتخذها هزوا اولئك لهم عذاب مهين', NULL, 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.', 'Dan apabila sampai ke pengetahuannya sesuatu dari ayat-ayat penerangan Kami, ia menjadikannya ejek-ejekan; mereka yang demikian keadaannya, akan beroleh azab yang menghina.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 11, NULL),
(45, 10, 'مِّن وَرَآئِهِمْ جَهَنَّمُ ۖ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'من ورائهم جهنم ولا يغني عنهم ما كسبوا شيئا ولا ما اتخذوا من دون الله اولياء ولهم عذاب عظيم', NULL, 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allāh as allies. And they will have a great punishment.', 'Di hadapan mereka (di akhirat kelak) ada neraka Jahannam (yang disediakan untuk mereka), dan apa jua yang mereka usahakan, tidak dapat menyelematkan mereka sedikit pun; demikian juga yang mereka sembah atau puja selain Allah, tidak dapat memberikan sebarang perlindungan; dan (kesudahannya) mereka akan beroleh azab seksa yang besar.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 19, NULL),
(45, 11, 'هَـٰذَا هُدًى ۖ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'هذا هدى والذين كفروا بايات ربهم لهم عذاب من رجز اليم', NULL, 'This [Qur’ān] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.', 'Al-Quran ini ialah hidayah petunjuk yang cukup lengkap; dan orang-orang yang kufur ingkar akan ayat-ayat penerangan Tuhannya, mereka akan beroleh azab dari jenis azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 499, 25, 199, 434, FALSE, 11, NULL),
(45, 12, '۞ ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'الله الذي سخر لكم البحر لتجري الفلك فيه بامره ولتبتغوا من فضله ولعلكم تشكرون', NULL, 'It is Allāh who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.', 'Allah yang memudahkan laut bagi kegunaan kamu, supaya kapal-kapal belayar padanya dengan perintahNya, dan supaya kamu mencari rezeki dari limpah kurniaNya, dan juga supaya kamu bersyukur.', FALSE, NULL, NULL, 499, 25, 200, 435, FALSE, 14, NULL),
(45, 13, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'وسخر لكم ما في السماوات وما في الارض جميعا منه ان في ذلك لايات لقوم يتفكرون', NULL, 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.', 'Dan Ia memudahkan untuk (faedah dan kegunaan) kamu, segala yang ada di langit dan yang ada di bumi, (sebagai rahmat pemberian) daripadaNya; sesungguhnya semuanya itu mengandungi tanda-tanda (yang membuktikan kemurahan dan kekuasaanNya) bagi kaum yang memikirkannya dengan teliti.', FALSE, NULL, NULL, 499, 25, 200, 435, FALSE, 16, NULL),
(45, 14, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'قل للذين امنوا يغفروا للذين لا يرجون ايام الله ليجزي قوما بما كانوا يكسبون', NULL, 'Say, [O Muḥammad], to those who have believed that they [should] forgive those who expect not the days of Allāh [i.e., of His retribution] so that He may recompense a people for what they used to earn.', 'Katakanlah (wahai Muhammad) kepada orang-orang yang beriman: hendaklah mereka memaafkan (kejahatan dan gangguan) orang-orang yang tidak menaruh ingatan kepada hari-hari (pembalasan yang telah ditentukan) Allah; (disuruh berbuat demikian), kerana Allah akan memberi kepada satu-satu puak: balasan yang patut dengan apa yang mereka telah usahakan.', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 14, NULL),
(45, 15, 'مَنْ عَمِلَ صَـٰلِحًا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۖ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'من عمل صالحا فلنفسه ومن اساء فعليها ثم الى ربكم ترجعون', NULL, 'Whoever does a good deed - it is for himself; and whoever does evil - it is against it [i.e., the self or soul]. Then to your Lord you will be returned.', '(Tiap-tiap balasan berdasarkan kaedah): Sesiapa yang mengerjakan amal soleh, maka faedahnya akan terpulang kepada dirinya sendiri; dan sesiapa yang berbuat kejahatan, maka bahayanya akan menimpa dirinya sendiri; kemudian kamu akan dikembalikan kepada Tuhan kamu.', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 11, NULL),
(45, 16, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ وَفَضَّلْنَـٰهُمْ عَلَى ٱلْعَـٰلَمِينَ', 'ولقد اتينا بني اسرائيل الكتاب والحكم والنبوة ورزقناهم من الطيبات وفضلناهم على العالمين', NULL, 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.', 'Dan demi sesungguhnya, Kami telah memberi kepada Bani Israil Kitab Taurat, dan pangkat kehakiman serta pangkat kenabian; dan Kami telah kurniakan mereka benda-benda yang baik-baik, serta Kami lebihkan (nenek moyang) mereka di atas orang-orang yang ada pada zamannya.', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 13, NULL),
(45, 17, 'وَءَاتَيْنَـٰهُم بَيِّنَـٰتٍ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'واتيناهم بينات من الامر فما اختلفوا الا من بعد ما جاءهم العلم بغيا بينهم ان ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون', NULL, 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', 'Dan lagi Kami telah berikan mereka keterangan-keterangan yang jelas nyata mengenai perkara ugama; maka mereka tidak berselisihan (dalam perkara ugama itu) melainkan setelah sampai kepada mereka ajaran-ajaran yang memberi mereka mengetahui (apa yang baik dan yang sebaliknya; berlakunya yang demikian) kerana hasad dengki yang ada dalam kalangan mereka. Sesungguhnya Tuhanmu akan menghukum di antara mereka pada hari kiamat tentang apa yang mereka perselisihkan itu.', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 24, NULL),
(45, 18, 'ثُمَّ جَعَلْنَـٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'ثم جعلناك على شريعة من الامر فاتبعها ولا تتبع اهواء الذين لا يعلمون', NULL, 'Then We put you, [O Muḥammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.', 'Kesudahannya Kami jadikan engkau (wahai Muhammad dan utuskan engkau) menjalankan satu Syariat (yang cukup lengkap) dari hukum-hukum ugama; maka turutlah Syariat itu, dan janganlah engkau menurut hawa nafsu orang-orang yang tidak mengetahui (perkara yang benar).', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 13, NULL),
(45, 19, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا ۚ وَإِنَّ ٱلظَّـٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۖ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', 'انهم لن يغنوا عنك من الله شيئا وان الظالمين بعضهم اولياء بعض والله ولي المتقين', NULL, 'Indeed, they will never avail you against Allāh at all. And indeed, the wrongdoers are allies of one another; but Allāh is the protector of the righteous.', 'Sesungguhnya mereka tidak sekali-kali akan dapat menyelamatkanmu sedikitpun dari (azab) Allah (kalau engkau menurut mereka); dan sesungguhnya orang-orang yang zalim itu setengahnya menjadi penolong dan penyokong bagi setengahnya yang lain (dalam perkara yang salah); dan (sebaliknya) Allah menjadi penolong dan pelindung bagi orang-orang yang bertaqwa (yang engkaulah pemimpinnya).', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 15, NULL),
(45, 20, 'هَـٰذَا بَصَـٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ', 'هذا بصائر للناس وهدى ورحمة لقوم يوقنون', NULL, 'This [Qur’ān] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].', 'Al-Quran ini menjadi panduan-panduan yang membuka matahati manusia, dan menjadi hidayah petunjuk serta membawa rahmat bagi kaum yang meyakini (kebenarannya).', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 7, NULL),
(45, 21, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَآءَ مَا يَحْكُمُونَ', 'أَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَن نَّجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَوَاءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَاءَ مَا يَحْكُمُونَ', NULL, 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge [i.e., assume].', 'Patutkah orang-orang yang melakukan kejahatan menyangka bahawa Kami akan menjadikan mereka seperti orang-orang yang beriman dan beramal soleh, dengan menyamakan keadaan (mereka semua) semasa mereka hidup dan semasa mereka mati? Buruk sungguh apa yang mereka hukumkan itu.', FALSE, NULL, NULL, 500, 25, 200, 435, FALSE, 0, NULL),
(45, 22, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'وَخَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', NULL, 'And Allāh created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.', 'Dan (ingatlah), Allah menciptakan langit dan bumi dengan cara yang sungguh layak dan berhikmat (untuk membuktikan keesaanNya dan keadilanNya), dan supaya tiap-tiap diri diberi balasan dengan apa yang mereka telah kerjakan (baik atau jahat), sedang mereka tidak dikurangkan balasannya sedikitpun.', FALSE, NULL, NULL, 500, 25, 200, 436, FALSE, 0, NULL),
(45, 23, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ أَفَلَا تَذَكَّرُونَ', 'أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ وَأَضَلَّهُ اللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِ وَقَلْبِهِ وَجَعَلَ عَلَىٰ بَصَرِهِ غِشَاوَةً فَمَن يَهْدِيهِ مِن بَعْدِ اللَّهِ أَفَلَا تَذَكَّرُونَ', NULL, 'Have you seen he who has taken as his god his [own] desire, and Allāh has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allāh? Then will you not be reminded?', 'Dengan yang demikian, bagaimana fikiranmu (wahai Muhammad) terhadap orang yang menjadikan hawa nafsunya: tuhan yang dipatuhinya, dan ia pula disesatkan oleh Allah kerana diketahuiNya (bahawa ia tetap kufur ingkar), dan dimeteraikan pula atas pendengarannya dan hatinya, serta diadakan lapisan penutup atas penglihatannya? Maka siapakah lagi yang dapat memberi hidayah petunjuk kepadanya sesudah Allah (menjadikan dia berkeadaan demikian)? Oleh itu, mengapa kamu (wahai orang-orang yang ingkar) tidak ingat dan insaf?', FALSE, NULL, NULL, 501, 25, 200, 436, FALSE, 0, NULL),
(45, 24, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ', 'وَقَالُوا مَا هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَا إِلَّا الدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ', NULL, 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.', 'Dan mereka berkata: “Tiadalah hidup yang lain selain daripada hidup kita di dunia ini. Kita mati dan kita hidup (silih berganti); dan tiadalah yang membinasakan kita melainkan edaran zaman”. Pada hal mereka tidak mempunyai sebarang pengetahuan tentang hal itu; mereka hanyalah menurut sangkaan semata-mata.', FALSE, NULL, NULL, 501, 25, 200, 436, FALSE, 0, NULL),
(45, 25, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّا أَن قَالُوا ائْتُوا بِآبَائِنَا إِن كُنتُمْ صَادِقِينَ', NULL, 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."', 'Dan apabila dibacakan kepada mereka ayat-ayat keterangan Kami yang jelas nyata (mengenai soal hidup semula sesudah mati), tidaklah ada hujah mereka (untuk menolak kebenarannya) selain daripada berkata: “Bawakanlah datuk nenek kami (hidup semula) kalau betul kami orang-orang yang benar!”', FALSE, NULL, NULL, 501, 25, 200, 436, FALSE, 0, NULL),
(45, 26, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'قُلِ اللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ الْقِيَامَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ', NULL, 'Say, "Allāh causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."', 'Katakanlah (wahai Muhammad): “Allah yang menghidupkan kamu, kemudian Ia akan mematikan kamu, setelah itu Ia akan menghimpunkan kamu (dalam keadaan hidup semula) pada hari kiamat - (hari) yang tidak ada sebarang syak tentang kedatangannya; akan tetapi kebanyakan manusia tidak mengetahui (ketetapan itu)”.', FALSE, NULL, NULL, 501, 25, 200, 436, FALSE, 0, NULL),
(45, 27, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ', 'وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَخْسَرُ الْمُبْطِلُونَ', NULL, 'And to Allāh belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.', 'Dan bagi Allah jualah kuasa pemerintahan langit dan bumi; dan ketika berlakunya hari kiamat, pada saat itulah ruginya orang-orang yang berpegang kepada perkara yang salah.', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(45, 28, 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَىٰ إِلَىٰ كِتَابِهَا الْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', NULL, 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.', 'Dan (pada hari kiamat) engkau akan melihat tiap-tiap umat berlutut (dalam keadaan cemas dan menunggu panggilan); tiap-tiap umat diseru untuk menerima kitab suratan amalnya (serta dikatakan kepada mereka): “Pada hari ini kamu akan dibalas menurut apa yang kamu telah kerjakan!', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL),
(45, 29, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', 'هَٰذَا كِتَابُنَا يَنطِقُ عَلَيْكُم بِالْحَقِّ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', NULL, 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."', '“Inilah surat (tulisan malaikat) Kami, ia memberi keterangan terhadap kamu dengan yang benar, kerana sesungguhnya Kami telah (perintahkan malaikat) menulis segala yang kamu telah lakukan (di dunia dahulu)!”', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL),
(45, 30, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', 'فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِي رَحْمَتِهِ ذَٰلِكَ هُوَ الْفَوْزُ الْمُبِينُ', NULL, 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.', 'Adapun orang-orang yang beriman dan beramal soleh, maka mereka akan dimasukkan oleh Tuhan mereka ke dalam rahmatNya; yang demikian itu ialah kemenangan yang besar.', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL),
(45, 31, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', 'وَأَمَّا الَّذِينَ كَفَرُوا أَفَلَمْ تَكُنْ آيَاتِي تُتْلَىٰ عَلَيْكُمْ فَاسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', NULL, 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a criminal people?', 'Adapun orang-orang yang kafir, (maka mereka akan ditempelak dengan dikatakan kepada mereka): “Bukankah ayat-ayatku telah disampaikan dan dibacakan kepada kamu, lalu kamu berlaku sombong takbur (mengingkarinya), serta menjadi kaum yang sentiasa melakukan kesalahan?', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL),
(45, 32, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', 'وَإِذَا قِيلَ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَالسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِي مَا السَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', NULL, 'And when it was said, ''Indeed, the promise of Allāh is truth and the Hour [is coming] - no doubt about it,'' you said, ''We know not what is the Hour. We assume only assumption, and we are not convinced.''"', '“Dan apabila dikatakan (kepada kamu): ‘Sesungguhnya janji Allah (membalas amal kamu) adalah benar, dan hari kiamat tidak ada sebarang syak tentang kedatangannya’, kamu berkata: ‘Kami tidak mengetahui apa dia hari kiamat itu; kami hanya mengira (kemungkinannya) sebagai sangkaan jua, dan kami tidak sekali-kali meyakininya’.”', FALSE, NULL, NULL, 501, 25, 200, 437, FALSE, 0, NULL),
(45, 33, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وَبَدَا لَهُمْ سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.', 'Dan (pada ketika itu) ternyatalah kepada mereka balasan kejahatan-kejahatan yang mereka telah lakukan, serta mereka diliputi oleh azab yang mereka ejek-ejek itu!', FALSE, NULL, NULL, 502, 25, 200, 437, FALSE, 0, NULL),
(45, 34, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'وَقِيلَ الْيَوْمَ نَنسَاكُمْ كَمَا نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَٰذَا وَمَأْوَاكُمُ النَّارُ وَمَا لَكُم مِّن نَّاصِرِينَ', NULL, 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.', 'Dan dikatakan (kepada mereka): “Pada hari ini Kami tidak hiraukan kamu (menderita di dalam azab seksa) sebagaimana kamu tidak hiraukan persediaan untuk menemui hari kamu ini; dan tempat kamu ialah neraka, dan kamu tidak akan beroleh sesiapapun yang dapat memberikan pertolongan.', FALSE, NULL, NULL, 502, 25, 200, 437, FALSE, 0, NULL),
(45, 35, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'ذَٰلِكُم بِأَنَّكُمُ اتَّخَذْتُمْ آيَاتِ اللَّهِ هُزُوًا وَغَرَّتْكُمُ الْحَيَاةُ الدُّنْيَا فَالْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', NULL, 'That is because you took the verses of Allāh in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allāh].', '“(Balasan buruk) yang demikian ini ialah kerana kamu telah menjadikan ayat-ayat keterangan Allah sebagai ejek-ejekan, dan kerana kamu telah membiarkan diri kamu diperdayakan oleh kehidupan dunia”. Maka pada hari itu mereka tidak akan dikeluarkan dari neraka, dan mereka tidak diberi peluang untuk bertaubat (memperbaiki kesalahannya).', FALSE, NULL, NULL, 502, 25, 200, 437, FALSE, 0, NULL),
(45, 36, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 'فَلِلَّهِ الْحَمْدُ رَبِّ السَّمَاوَاتِ وَرَبِّ الْأَرْضِ رَبِّ الْعَالَمِينَ', NULL, 'Then, to Allāh belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.', '(Demikianlah ajaran dan peringatan Allah Yang Maha Adil) maka bagi Allah jualah tertentu segala pujian, Tuhan yang mentadbirkan langit, dan Tuhan yang mentadbirkan bumi, - Tuhan sekalian alam.', FALSE, NULL, NULL, 502, 25, 200, 437, FALSE, 0, NULL),
(45, 37, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وَلَهُ الْكِبْرِيَاءُ فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.', 'Dan bagiNyalah keagungan dan kekuasaan di langit dan di bumi; dan dia lah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 502, 25, 200, 437, FALSE, 0, NULL),
(46, 1, 'حمٓ', 'حم', NULL, 'Ḥā, Meem.', 'Haa, Miim.', FALSE, NULL, NULL, 502, 26, 201, 438, FALSE, 1, NULL),
(46, 2, 'تَنزِيلُ ٱلْكِتَـٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'تنزيل الكتاب من الله العزيز الحكيم', NULL, 'The revelation of the Book is from Allāh, the Exalted in Might, the Wise.', 'Diturunkan Al-Quran ini, dari Allah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 502, 26, 201, 438, FALSE, 6, NULL),
(46, 3, 'مَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى ۚ وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 'ما خلقنا السماوات والارض وما بينهما الا بالحق واجل مسمى والذين كفروا عما انذروا معرضون', NULL, 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.', '(Ingatlah), tidaklah Kami menciptakan langit dan bumi serta segala yang ada di antara keduanya melainkan dengan ada gunanya yang benar dan dengan ada masa penghujungnya yang tertentu (yang padanya dijalankan pembalasan); dan orang-orang yang kafir berpaling dari menerima peringatan yang diberikan kepada mereka mengenainya.', FALSE, NULL, NULL, 502, 26, 201, 438, FALSE, 15, NULL),
(46, 4, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَـٰوَٰتِ ۖ ٱئْتُونِى بِكِتَـٰبٍ مِّن قَبْلِ هَـٰذَآ أَوْ أَثَـٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ', 'قل ارايتم ما تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السماوات ائتوني بكتاب من قبل هذا او اثارة من علم ان كنتم صادقين', NULL, 'Say, [O Muḥammad], "Have you considered that which you invoke besides Allāh? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."', 'Katakanlah (wahai Muhammad kepada orang-orang musyrik yang menentangmu): “Sudahkah kamu mengetahui kekuasaan dan kelayakan makhluk - makhluk yang kamu seru dan sembah yang lain dari Allah? Tunjukkanlah kepadaku apakah yang mereka ciptakan dari bahagian bumi ini? Atau adakah mereka mempunyai sebarang perkongsian (dengan Allah) dalam mencipta dan menguruskan langit? Bawalah kamu kepadaku sebuah Kitab (dari Allah) yang lain dari Al-Quran ini, atau sebarang keterangan yang berdasarkan ilmu (peninggalan orang-orang yang telah lalu) kalau betul kamu orang-orang yang benar (tentang dakwaan kamu itu)!”', FALSE, NULL, NULL, 502, 26, 201, 438, FALSE, 29, NULL),
(46, 5, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـٰفِلُونَ', 'ومن اضل ممن يدعو من دون الله من لا يستجيب له الى يوم القيامة وهم عن دعائهم غافلون', NULL, 'And who is more astray than he who invokes besides Allāh those who will not respond to him until the Day of Resurrection [i.e., never], and they, of their invocation, are unaware.', 'Dan tidak ada yang lebih sesat daripada orang yang menyembah sesuatu yang lain dari Allah, yang tidak dapat menyahut atau memberikan sebarang pertolongan kepadanya (dari dunia) hinggalah ke hari kiamat, sedang makhluk-makhluk yang mereka sembah itu tidak dapat menyedari atau memberi layanan baik kepada permohonan mereka.', FALSE, NULL, NULL, 502, 26, 201, 438, FALSE, 18, NULL),
(46, 6, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَـٰفِرِينَ', 'واذا حشر الناس كانوا لهم اعداء وكانوا بعبادتهم كافرين', NULL, 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.', 'Dan apabila manusia dihimpunkan (untuk dihitung amalnya pada hari akhirat), menjadilah segala yang disembah itu musuh kepada orang-orang yang menyembahnya, dan segala yang disembah itu juga tidak mengakui serta mendustakan penyembahan mereka kepadanya.', FALSE, NULL, NULL, 503, 26, 201, 438, FALSE, 9, NULL),
(46, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَـٰذَا سِحْرٌ مُّبِينٌ', 'واذا تتلى عليهم اياتنا بينات قال الذين كفروا للحق لما جاءهم هذا سحر مبين', NULL, 'And when Our verses are recited to them as clear evidences, those who disbelieve say of the truth when it has come to them, "This is obvious magic."', 'Dan apabila dibacakan kepada mereka (yang kafir) ayat-ayat Quran kami yang jelas nyata, berkatalah mereka terhadap kebenaran (Al-Quran) bila sahaja disampaikan kepada mereka: “Ini ialah sihir yang nyata!”.', FALSE, NULL, NULL, 503, 26, 201, 438, FALSE, 14, NULL),
(46, 8, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ ۖ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۖ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'ام يقولون افتراه قل ان افتريته فلا تملكون لي من الله شيئا هو اعلم بما تفيضون فيه كفى به شهيدا بيني وبينكم وهو الغفور الرحيم', NULL, 'Or do they say, "He has invented it"? Say, "If I have invented it, you will not possess for me [the power of protection] from Allāh at all. He is most knowing of that in which you are involved. Sufficient is He as Witness between me and you, and He is the Forgiving, the Merciful."', '(Bukan setakat itu sahaja mereka katakan) bahkan mereka menuduh dengan berkata: “Muhammad telah merekakan Al-Quran itu.” Katakanlah (Wahai Muhammad): “Kalau aku merekakan Al-Quran itu (maka tentulah aku tidak terlepas dari azab kesalahan itu) kerana kamu (dan juga yang lain dari kamu) tidak berkuasa memberikan daku sebarang perlindungan dari (azab) Allah. Allah lebih mengetahui akan (tuduhan-tuduhan yang tidak berasas) yang kamu perkatakan itu; cukuplah Allah menjadi saksi antaraku dengan kamu, dan Dia lah jua Yang Maha Pengampun, lagi Maha Mengasihani.”', FALSE, NULL, NULL, 503, 26, 201, 438, FALSE, 25, NULL),
(46, 9, 'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', 'قل ما كنت بدعا من الرسل وما ادري ما يفعل بي ولا بكم ان اتبع الا ما يوحى الي وما انا الا نذير مبين', NULL, 'Say, "I am not something new among the messengers, nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am not but a clear warner."', 'Katakanlah lagi: “Bukanlah aku seorang Rasul pembawa ugama yang berlainan dari ugama yang dibawa oleh Rasul-rasul (yang telah lalu), dan aku tidak mengetahui apa yang akan dilakukan kepadaku dan kepada kamu. Aku tidak melakukan sesuatu melainkan menurut apa yang diwahyukan kepadaku, dan aku tidak lain hanyalah seorang Rasul pemberi amaran yang jelas nyata”', FALSE, NULL, NULL, 503, 26, 201, 438, FALSE, 24, NULL),
(46, 10, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 'قل ارايتم ان كان من عند الله وكفرتم به وشهد شاهد من بني اسرائيل على مثله فامن واستكبرتم ان الله لا يهدي القوم الظالمين', NULL, 'Say, "Have you considered: if it [i.e., the Qur’ān] was from Allāh, and you disbelieved in it while a witness from the Children of Israel has testified to something similar and believed while you were arrogant...?" Indeed, Allāh does not guide the wrongdoing people.', 'Katakanlah lagi: “Bagaimana fikiran kamu jika Al-Quran ini (yang datangnya) dari Allah dan kamu mengingkarinya, pada hal ada seorang saksi dari Bani Israil memberi keterangan mengakui (sahnya Kitab) yang sama seperti Al-Quran ini, lalu ia percayakan (Al-Quran ini dari Allah), sedang kamu dengan sombong angkuh mengingkarinya? (Tidakkah dengan yang demikian kamu bersifat zalim)? Sesungguhnya Allah tidak memberi hidayah petunjuk kepada orang-orang yang zalim (yang degil dalam kekufurannya)”.', FALSE, NULL, NULL, 503, 26, 201, 438, FALSE, 24, NULL),
(46, 11, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَـٰذَآ إِفْكٌ قَدِيمٌ', 'وقال الذين كفروا للذين امنوا لو كان خيرا ما سبقونا اليه واذ لم يهتدوا به فسيقولون هذا افك قديم', NULL, 'And those who disbelieve say of those who believe, "If it had [truly] been good, they would not have preceded us to it." And when they are not guided by it, they will say, "This is an ancient falsehood."', 'Dan (kerana sombong angkuhnya orang-orang kafir itu) mereka berkata tentang kepercayaan orang-orang yang beriman: “Kalaulah (apa yang dibawa oleh Muhammad) itu perkara yang baik tentulah mereka tidak mendahului kami mempercayainya (kerana kamilah yang sepatutnya menerima segala kebaikan)!” Dan setelah mereka tidak dapat menerima petunjuk Al-Quran itu, (mereka memusuhinya) lalu mereka mencacinya dengan berkata: “Al-Quran ini ialah rekaan dusta yang sudah lama”.', FALSE, NULL, NULL, 503, 26, 201, 439, FALSE, 19, NULL),
(46, 12, 'وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ وَهَـٰذَا كِتَـٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', 'ومن قبله كتاب موسى اماما ورحمة وهذا كتاب مصدق لسانا عربيا لينذر الذين ظلموا وبشرى للمحسنين', NULL, 'And before it was the scripture of Moses to lead and as a mercy. And this is a confirming Book in an Arabic tongue to warn those who have wronged and as good tidings to the doers of good.', '(Bagaimana mereka tergamak mengatakan Al-Quran ini rekaan dusta yang telah lama?) Pada hal telah ada sebelumnya Kitab Nabi Musa yang menjadi ikutan dan rahmat (kepada umatnya); dan Al-Quran pula sebuah Kitab - yang mengesahkan kebenaran (kitab-kitab yang telah lalu), - diturunkan dalam bahasa Arab untuk memberi amaran kepada orang-orang yang zalim, dan berita gembira bagi orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 503, 26, 201, 439, FALSE, 16, NULL),
(46, 13, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَـٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ان الذين قالوا ربنا الله ثم استقاموا فلا خوف عليهم ولا هم يحزنون', NULL, 'Indeed, those who have said, "Our Lord is Allāh," and then remained on a right course - there will be no fear concerning them, nor will they grieve.', 'Sesungguhnya orang-orang yang menegaskan keyakinannya dengan berkata: “Tuhan kami ialah Allah”, kemudian mereka tetap teguh di atas jalan yang betul (dengan pengakuan iman dan tauhidnya itu), maka tidak ada kebimbangan (dari sesuatu yang tidak baik) terhadap mereka, dan mereka pula tidak akan berdukacita.', FALSE, NULL, NULL, 503, 26, 201, 439, FALSE, 13, NULL),
(46, 14, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ خَـٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'اولئك اصحاب الجنة خالدين فيها جزاء بما كانوا يعملون', NULL, 'Those are the companions of Paradise, abiding eternally therein as reward for what they used to do.', 'Merekalah ahli Syurga, tetap kekalah mereka di dalamnya, sebagai balasan bagi amal-amal soleh yang mereka telah kerjakan.', FALSE, NULL, NULL, 503, 26, 201, 439, FALSE, 9, NULL),
(46, 15, 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ إِحْسَـٰنًا ۖ حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا ۖ وَحَمْلُهُۥ وَفِصَـٰلُهُۥ ثَلَـٰثُونَ شَهْرًا ۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', 'ووصينا الانسان بوالديه احسانا حملته امه كرها ووضعته كرها وحمله وفصاله ثلاثون شهرا حتى اذا بلغ اشده وبلغ اربعين سنة قال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه واصلح لي في ذريتي اني تبت اليك واني من المسلمين', NULL, 'And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims."', 'Dan Kami wajibkan manusia berbuat baik kepada kedua ibu bapanya; ibunya telah mengandungnya dengan menanggung susah payah dan telah melahirkannya dengan menanggung susah payah. Sedang tempoh mengandungnya beserta dengan tempoh menceraikan susunya ialah dalam masa tiga puluh bulan. Setelah ia besar sampai ke peringkat dewasa yang sempurna kekuatannya dan sampai ke peringkat umur empat puluh tahun, berdoalah ia dengan berkata: “Wahai Tuhanku, ilhamkanlah daku supaya tetap bersyukur akan nikmatmu yang engkau kurniakan kepadaku dan kepada ibu bapaku, dan supaya aku tetap mengerjakan amal soleh yang Engkau redai; dan jadikanlah sifat-sifat kebaikan meresap masuk ke dalam jiwa zuriat keturunanku. Sesungguhnya aku bertaubat kepadamu, dan sesungguhnya aku dari orang-orang Islam (yang tunduk patuh kepadamu)”.', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 45, NULL),
(46, 16, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَـٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'اولئك الذين نتقبل عنهم احسن ما عملوا ونتجاوز عن سيئاتهم في اصحاب الجنة وعد الصدق الذي كانوا يوعدون', NULL, 'Those are the ones from whom We will accept the best of what they did and overlook their misdeeds, [their being] among the companions of Paradise. [That is] the promise of truth which they had been promised.', 'Mereka (yang bersifat dengan sifat-sifat yang terpuji seperti itu) ialah orang-orang yang Kami terima dari mereka amalnya yang baik yang mereka telah kerjakan, dan Kami ampunkan kesalahan-kesalahannya; (mereka akan dimasukkan) dalam kumpulan ahli Syurga, sebagai memenuhi janji yang benar, yang telah dijanjikan kepada mereka.', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 18, NULL),
(46, 17, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', 'والذي قال لوالديه اف لكما اتعدانني ان اخرج وقد خلت القرون من قبلي وهما يستغيثان الله ويلك امن ان وعد الله حق فيقول ما هذا الا اساطير الاولين', NULL, 'But one who says to his parents, "Uff to you; do you promise me that I will be brought forth [from the earth] when generations before me have already passed on [into oblivion]?" while they call to Allāh for help [and to their son], "Woe to you! Believe! Indeed, the promise of Allāh is truth." But he says, "This is not but legends of the former peoples" -', 'Dan (sebaliknya amatlah derhakanya) orang yang berkata kepada kedua ibu bapanya (ketika mereka mengajaknya beriman): “Ah! Bosan perasaanku terhadap kamu berdua! Patutkah kamu menjanjikan kepadaku bahawa aku akan dibangkitkan keluar dari kubur, padahal berbagai umat sebelumku telah berlalu (masih lagi belum kembali)?” Sambil mendengar kata-katanya itu - ibu bapanya merayu memohon pertolongan Allah (menyelamatkan anak mereka) serta berkata (kepada anaknya yang ingkar itu): “Selamatkanlah dirimu! Berimanlah (tentang hidup semula menerima balasan amal)! Sesungguhnya janji Allah tetap benar”. Lalu ia menjawab (dengan angkuhnya): “Semuanya itu hanyalah cerita-cerita dongeng orang-orang dahulu kala!”', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 28, NULL),
(46, 18, 'أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَـٰسِرِينَ', 'اولئك الذين حق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خاسرين', NULL, 'Those are the ones upon whom the word [i.e., decree] has come into effect, [who will be] among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.', 'Mereka (yang ingkar derhaka seperti itu) ialah orang-orang yang tetap menerima hukuman (azab) bersama-sama dengan umat-umat yang terdahulu daripada mereka - dari kalangan jin dan manusia; kerana sesungguhnya mereka telah menyebabkan diri mereka menjadi orang-orang yang rugi.', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 17, NULL),
(46, 19, 'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۖ وَلِيُوَفِّيَهُمْ أَعْمَـٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', 'ولكل درجات مما عملوا وليوفيهم اعمالهم وهم لا يظلمون', NULL, 'And for all there are degrees [of reward and punishment] for what they have done, and [it is] so that He may fully compensate them for their deeds, and they will not be wronged.', 'Dan bagi mereka masing-masing (dari puak jin dan manusia - yang berbuat baik dan yang berbuat jahat) disediakan berbagai peringkat (balasan) yang sesuai dengan apa yang mereka telah kerjakan, dan (ketetapan yang demikian ialah) supaya Allah menyempurnakan bagi mereka balasan amal-amal mereka, sedang mereka tidak dirugikan (sedikitpun).', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 9, NULL),
(46, 20, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَـٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', 'ويوم يعرض الذين كفروا على النار اذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون في الارض بغير الحق وبما كنتم تفسقون', NULL, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "You exhausted your pleasures during your worldly life and enjoyed them, so this Day you will be awarded the punishment of [extreme] humiliation because you were arrogant upon the earth without right and because you were defiantly disobedient."', 'Dan (ingatlah), semasa orang-orang kafir didedahkan kepada neraka (serta dikatakan kepada mereka): “Kamu telah habiskan nikmat-nikmat kesenangan kamu dalam kehidupan dunia kamu, dan kamu telah bersenang-senang menikmatinya; maka pada hari ini kamu dibalas dengan azab yang menghina kerana kamu berlaku sombong takbur di muka bumi dengan tidak berdasarkan alasan yang benar, dan kerana kamu sentiasa berlaku fasik”', FALSE, NULL, NULL, 504, 26, 201, 439, FALSE, 27, NULL),
(46, 21, 'وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'وَاذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُ بِالْأَحْقَافِ وَقَدْ خَلَتِ النُّذُرُ مِن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', NULL, 'And mention, [O Muḥammad], the brother of ʿAad, when he warned his people in [the region of] al-Aḥqāf - and warners had already passed on before him and after him - [saying], "Do not worship except Allāh. Indeed, I fear for you the punishment of a terrible day."', 'Dan ingatlah peristiwa (Nabi Hud) saudara kaum Aad, ketika ia memberi amaran kepada kaumnya yang tinggal di lembah “Al-Ahqaaf”, - sedang (amarannya itu samalah seperti) amaran-amaran yang telah diberikan oleh Rasul-rasul yang terdahulu daripadanya dan yang datang sesudahnya - (dengan berkata): “Janganlah kamu menyembah melainkan Allah, sesungguhnya aku bimbang kamu akan beroleh azab hari yang besar (huru-haranya)”.', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 22, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'قَالُوا أَجِئْتَنَا لِتَأْفِكَنَا عَنْ آلِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الصَّادِقِينَ', NULL, 'They said, "Have you come to delude us away from our gods? Then bring us what you promise us, if you should be of the truthful."', 'Mereka menjawab: “Adakah engkau datang kepada kami untuk memesongkan kami dari menyembah tuhan-tuhan kami? Maka bawalah azab seksa yang engkau janjikan kepada kami itu jika betul engkau dari orang-orang yang benar!”', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 23, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'قَالَ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَأُبَلِّغُكُم مَّا أُرْسِلْتُ بِهِ وَلَٰكِنِّي أَرَاكُمْ قَوْمًا تَجْهَلُونَ', NULL, 'He said, "Knowledge [of its time] is only with Allāh, and I convey to you that with which I was sent; but I see you [to be] a people behaving ignorantly."', 'Nabi Hud berkata: “Sesungguhnya ilmu pengetahuan (tentang kedatangan azab itu) hanya ada di sisi Allah, dan (tugasku hanya) menyampaikan kepada kamu apa yang aku diutuskan membawanya, tetapi aku lihat kamu satu kaum yang jahil (akan tugas Rasul)!”', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 24, 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌ مُّمْطِرُنَا بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَٰذَا عَارِضٌ مُّمْطِرُنَا بَلْ هُوَ مَا اسْتَعْجَلْتُم بِهِ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', NULL, 'And when they saw it as a cloud approaching their valleys, they said, "This is a cloud bringing us rain!" Rather, it is that for which you were impatient: a wind, within it a painful punishment,', 'Maka apabila mereka melihat azab itu sebagai awan yang menghala ke lembah-lembah mereka, mereka berkata: “Ini ialah awan yang akan membawa hujan kepada kita!” (Mendengarkan kata-kata yang demikian, Nabi Hud berkata): “Tidak! Bahkan itulah (azab) yang kamu minta disegerakan kedatangannya, iaitu angin yang membawa azab seksa yang tidak terperi sakitnya;', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 25, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'تُدَمِّرُ كُلَّ شَيْءٍ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا لَا يُرَىٰ إِلَّا مَسَاكِنُهُمْ كَذَٰلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ', NULL, 'Destroying everything by command of its Lord. And they became so that nothing was seen [of them] except their dwellings. Thus do We recompense the criminal people.', '“Yang menghancur leburkan segala-galanya dengan izin Tuhannya”. (Setelah azab itu menimpa mereka) maka menjadilah mereka (punah ranah) - tidak ada yang kelihatan melainkan tempat-tempat tinggal mereka. Demikianlah Kami membalas kaum yang berdosa.', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 26, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'وَلَقَدْ مَكَّنَّاهُمْ فِيمَا إِن مَّكَّنَّاكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَارًا وَأَفْئِدَةً فَمَا أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَا أَبْصَارُهُمْ وَلَا أَفْئِدَتُهُم مِّن شَيْءٍ إِذْ كَانُوا يَجْحَدُونَ بِآيَاتِ اللَّهِ وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ', NULL, 'And We had certainly established them in such as We have not established you, and We made for them hearing and vision and hearts [i.e., intellect]. But their hearing and vision and hearts availed them not from anything [of the punishment] when they were [continually] rejecting the signs of Allāh; and they were enveloped by what they used to ridicule.', 'Dan demi sesungguhnya! Kami telah meneguhkan kedudukan mereka (dengan kekuasaan dan kemewahan) yang tidak Kami berikan kamu menguasainya (wahai kaum musyrik Makkah), dan Kami telah jadikan bagi mereka pendengaran dan penglihatan serta hati; dalam pada itu, pendengaran dan penglihatan serta hati mereka tidak memberikan faedah sedikitpun kepada mereka, kerana mereka sentiasa mengingkari ayat-ayat keterangan Allah; dan (dengan yang demikian) mereka diliputi oleh azab yang mereka telah ejek-ejek itu.', FALSE, NULL, NULL, 505, 26, 202, 440, FALSE, 0, NULL),
(46, 27, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ الْقُرَىٰ وَصَرَّفْنَا الْآيَاتِ لَعَلَّهُمْ يَرْجِعُونَ', NULL, 'And We have already destroyed what surrounds you of [those] cities, and We have diversified the signs [or verses] that perhaps they might return [from disbelief].', 'Dan demi sesungguhnya! Kami telah binasakan negeri-negeri yang ada di sekeliling (negeri) kamu (wahai kaum musyrik Makkah), dan Kami telah menerangkan tanda-tanda (kekuasaan Kami) dengan berbagai cara, supaya mereka kembali (bertaubat).', FALSE, NULL, NULL, 505, 26, 202, 441, FALSE, 0, NULL),
(46, 28, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ بَلْ ضَلُّوا۟ عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', 'فَلَوْلَا نَصَرَهُمُ الَّذِينَ اتَّخَذُوا مِن دُونِ اللَّهِ قُرْبَانًا آلِهَةً بَلْ ضَلُّوا عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا يَفْتَرُونَ', NULL, 'Then why did those they took besides Allāh as deities by which to approach [Him] not aid them? But they had strayed [i.e., departed] from them. And that was their falsehood and what they were inventing.', 'Maka sepatutnya mereka dibela oleh segala yang mereka sembah yang lain dari Allah sebagai penyembahan untuk mendekatkan diri (kepada Allah)? (Tetapi tidak), bahkan segala yang mereka sembah itu telah hilang lenyap dari mereka. Dan demikianlah akibat penyelewengan mereka dan kepercayaan yang mereka telah ada-adakan.', FALSE, NULL, NULL, 505, 26, 202, 441, FALSE, 0, NULL),
(46, 29, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 'وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ', NULL, 'And [mention, O Muḥammad], when We directed to you a few of the jinn, listening to the Qur’ān. And when they attended it, they said, "Listen attentively." And when it was concluded, they went back to their people as warners.', 'Dan (ingatkanlah peristiwa) semasa Kami menghalakan satu rombongan jin datang kepadamu (wahai Muhammad) untuk mendengar Al-Quran; setelah mereka menghadiri bacaannya, berkatalah (setengahnya kepada yang lain): “Diamlah kamu dengan sebulat-bulat ingatan untuk mendengarnya!” Kemudian setelah selesai bacaan itu, kembalilah mereka kepada kaumnya (menyiarkan ajaran Al-Quran itu dengan) memberi peringatan dan amaran.', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 30, 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', 'قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', NULL, 'They said, "O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path.', 'Mereka berkata: “Wahai kaum kami! Sesungguhnya kami telah mendengar Kitab (Al-Quran) yang diturunkan (oleh Allah) sesudah Nabi Musa, yang menegaskan kebenaran Kitab-kitab Suci yang terdahulu daripadanya, lagi, memandu kepada kebenaran (tauhid) dan ke jalan yang lurus (ugama Islam)', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 31, 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', 'يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', NULL, 'O our people, respond to the Caller [i.e., Messenger] of Allāh and believe in him; He [i.e., Allāh] will forgive for you your sins and protect you from a painful punishment.', '“Wahai kaum kami! Sahutlah (seruan) Rasul (Nabi Muhammad) yang mengajak ke jalan Allah, serta berimanlah kamu kepadanya, supaya Allah mengampunkan sebahagian dari dosa-dosa kamu, dan menyelamatkan kamu dari azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 32, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', 'وَمَن لَّا يُجِبْ دَاعِيَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَاءُ أُولَٰئِكَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'But he who does not respond to the Caller of Allāh will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error."', '“Dan sesiapa tidak menyahut (seruan) Rasul yang mengajaknya ke jalan Allah, maka ia tidak akan dapat melepaskan diri (dari balasan azab walau ke mana sahaja ia melarikan diri) di bumi, dan ia tidak akan beroleh sesiapapun - yang lain dari Allah - sebagai pelindung-pelindung yang membelanya; mereka (yang demikian sifatnya) adalah dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 33, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ بَلَىٰ إِنَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ', NULL, 'Do they not see that Allāh, who created the heavens and earth and did not fail in their creation, is able to give life to the dead? Yes. Indeed, He is over all things competent.', 'Masihkah mereka ingkar dan tidak mahu memikir serta mengetahui bahawa sesungguhnya Allah yang telah menciptakan langit dan bumi dengan tidak mengalami kesukaran dalam menciptakannya - berkuasa menghidupkan makhluk-makhluk yang telah mati? Sudah tentu berkuasa! Sesungguhnya Ia Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 34, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَلَيْسَ هَٰذَا بِالْحَقِّ قَالُوا بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', NULL, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "Is this not the truth?" They will say, "Yes, by our Lord." He will say, "Then taste the punishment for what you used to deny."', 'Dan (ingatlah) hari orang-orang yang kafir didedahkan kepada neraka, (lalu dikatakan kepada mereka): “Bukankah (azab) neraka ini benar?” Mereka menjawab: “Ya, benar, demi Tuhan kami!” (Setelah itu) dikatakan lagi (kepada mereka): “Maka sekarang rasalah azab seksa dengan sebab kamu kufur ingkar di dunia dahulu.”', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(46, 35, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ بَلَٰغٌ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', 'فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوا إِلَّا سَاعَةً مِّن نَّهَارٍ بَلَاغٌ فَهَلْ يُهْلَكُ إِلَّا الْقَوْمُ الْفَاسِقُونَ', NULL, 'So be patient, [O Muḥammad], as were those of determination among the messengers and do not be impatient for them. It will be - on the Day they see that which they are promised - as though they had not remained [in the world] except an hour of a day. [This is] notification. And will [any] be destroyed except the defiantly disobedient people?', '(Jika demikian akibat orang-orang kafir yang menentangmu wahai Muhammad) maka bersabarlah engkau sebagaimana sabarnya Rasul-rasul “Ulil-Azmi” (yang mempunyai keazaman dan ketabahan hati) dari kalangan Rasul-rasul (yang terdahulu daripadamu); dan janganlah engkau meminta disegerakan azab untuk mereka (yang menentangmu itu). Sesungguhnya keadaan mereka semasa melihat azab yang dijanjikan kepada mereka, merasai seolah-olah mereka tidak tinggal (di dunia) melainkan sekadar satu saat sahaja dari siang hari. (Penerangan yang demikian) cukuplah menjadi pelajaran (bagi orang-orang yang mahu insaf). Maka (ingatlah) tidak dibinasakan melainkan kaum yang fasik - derhaka.', FALSE, NULL, NULL, 506, 26, 202, 441, FALSE, 0, NULL),
(47, 1, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَـٰلَهُمْ', 'الذين كفروا وصدوا عن سبيل الله اضل اعمالهم', NULL, 'Those who disbelieve and avert [people] from the way of Allāh - He will waste their deeds.', 'Orang-orang yang kafir serta menghalangi (dirinya dan orang lain) dari jalan Allah, Allah sia-siakan segala amal mereka.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 8, NULL),
(47, 2, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 'والذين امنوا وعملوا الصالحات وامنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيئاتهم واصلح بالهم', NULL, 'And those who believe and do righteous deeds and believe in what has been sent down upon Muḥammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.', 'Dan (sebaliknya) orang-orang yang beriman dan mengerjakan amal yang soleh serta beriman kepada Al-Quran yang diturunkan kepada Nabi Muhammad (s.a.w) - yang ialah kebenaran dari Tuhan mereka, - Allah mengampunkan dosa-dosa mereka, dan menjayakan keadaan mereka (di dunia dan di akhirat).', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 18, NULL),
(47, 3, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَـٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَـٰلَهُمْ', 'ذلك بان الذين كفروا اتبعوا الباطل وان الذين امنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثالهم', NULL, 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allāh present to the people their comparisons.', 'Berlakunya yang demikian, kerana sesungguhnya orang-orang yang kafir menurut perkara yang salah, dan sesungguhnya orang-orang yang beriman menurut perkara yang benar dari Tuhan mereka. Demikianlah Allah menerangkan kepada umat manusia akan sifat dan akibat bawaan mereka masing-masing.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 18, NULL),
(47, 4, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَـٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ ۗ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَـٰلَهُمْ', 'فاذا لقيتم الذين كفروا فضرب الرقاب حتى اذا اثخنتموهم فشدوا الوثاق فاما منا بعد واما فداء حتى تضع الحرب اوزارها ذلك ولو يشاء الله لانتصر منهم ولكن ليبلو بعضكم ببعض والذين قتلوا في سبيل الله فلن يضل اعمالهم', NULL, 'So when you meet those who disbelieve [in battle], strike [their] necks until, when you have inflicted slaughter upon them, then secure [their] bonds, and either [confer] favor afterwards or ransom [them] until the war lays down its burdens. That [is the command]. And if Allāh had willed, He could have taken vengeance upon them [Himself], but [He ordered armed struggle] to test some of you by means of others. And those who are killed in the cause of Allāh - never will He waste their deeds.', 'Dengan yang demikian, apabila kamu berjuang menentang orang-orang kafir (dalam peperangan jihad) maka pancunglah lehernya, sehingga apabila kamu dapat membunuh mereka dengan banyaknya (serta mengalahkannya) maka tawanlah (mana-mana yang hidup) dan ikatlah mereka dengan kukuhnya. Setelah selesai pertempuran itu maka (terserahlah kepada kamu) sama ada hendak memberi kebebasan (kepada orang-orang tawanan itu dengan tiada sebarang penebusnya) atau membebaskan mereka dengan mengambil penebusnya. (Bertindaklah demikian terhadap golongan kafir yang menceroboh) sehinggalah berakhir peperangan jihad itu (dan lenyaplah sebab-sebab yang memimbulkannya). Demikianlah (diperintahkan kamu melakukannya). Dan sekiranya Allah menghendaki, tentulah Ia membinasakan mereka (dengan tidak payah kamu memeranginya); tetapi Ia (perintahkan kamu berbuat demikian) kerana hendak menguji kesabaran kamu menentang golongan yang kufur ingkar (yang mencerobohi kamu). Dan orang-orang yang telah berjuang serta gugur syahid pada jalan Allah (mempertahankan ugamanya), maka Allah tidak sekali kali akan mensia-siakan amal-amal mereka.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 38, NULL),
(47, 5, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'سيهديهم ويصلح بالهم', NULL, 'He will guide them and amend their condition', 'Allah akan memimpin mereka yang berjuang (ke jalan mendapat sebaik-baik balasan) dan menjadikan keadaan mereka baik dan berguna (di dunia dan di akhirat)', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 3, NULL),
(47, 6, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 'ويدخلهم الجنة عرفها لهم', NULL, 'And admit them to Paradise, which He has made known to them.', 'Serta memasukkan mereka ke dalam Syurga yang telah dijanjikan dan diterangkan sifat-sifatnya kepada mereka.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 4, NULL),
(47, 7, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', 'يا ايها الذين امنوا ان تنصروا الله ينصركم ويثبت اقدامكم', NULL, 'O you who have believed, if you support Allāh, He will support you and plant firmly your feet.', 'Wahai orang-orang yang beriman, kalau kamu membela (ugama) Allah nescaya Allah membela kamu (untuk mencapai kemenangan) dan meneguhkan tapak pendirian kamu.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 9, NULL),
(47, 8, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَـٰلَهُمْ', 'والذين كفروا فتعسا لهم واضل اعمالهم', NULL, 'But those who disbelieve - for them is misery, and He will waste their deeds.', 'Dan (sebaliknya) orang-orang yang kafir, maka kecelakaanlah bagi mereka, dan (Allah) mensia-siakan amal-amal mereka.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 6, NULL),
(47, 9, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَـٰلَهُمْ', 'ذلك بانهم كرهوا ما انزل الله فاحبط اعمالهم', NULL, 'That is because they disliked what Allāh revealed, so He rendered worthless their deeds.', 'Berlakunya yang demikian, kerana sesungguhnya mereka tidak menyukai apa yang diturunkan oleh Allah (mengenai ajaran tauhid dan hukum-hukum syarak yang diterangkan di dalam Al-Quran), lalu Allah menggugurkan amal-amal mereka.', FALSE, NULL, NULL, 507, 26, 202, 442, FALSE, 8, NULL),
(47, 10, '۞ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ دَمَّرَ ٱللَّهُ عَلَيْهِمْ ۖ وَلِلْكَـٰفِرِينَ أَمْثَـٰلُهَا', 'افلم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم دمر الله عليهم وللكافرين امثالها', NULL, 'Have they not traveled through the land and seen how was the end of those before them? Allāh destroyed [everything] over them, and for the disbelievers is something comparable.', 'Maka tidakkah mereka telah mengembara di muka bumi, serta mereka memerhatikan bagaimana akibat orang-orang kafir yang terdahulu dari mereka? Allah telah menghancurkan orang-orang itu; dan orang-orang kafir (yang menurut jejak mereka) akan beroleh akibat-akibat buruk yang seperti itu.', FALSE, NULL, NULL, 507, 26, 203, 442, FALSE, 16, NULL),
(47, 11, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَـٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', 'ذلك بان الله مولى الذين امنوا وان الكافرين لا مولى لهم', NULL, 'That is because Allāh is the protector of those who have believed and because the disbelievers have no protector.', 'Balasan yang demikian, kerana sesungguhnya Allah menjadi Pelindung orang-orang yang beriman, dan sesungguhnya orang-orang yang kafir: tiada sesiapapun yang dapat memberikan perlindungan kepada mereka.', FALSE, NULL, NULL, 507, 26, 203, 442, FALSE, 11, NULL),
(47, 12, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَـٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ', 'ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار والذين كفروا يتمتعون وياكلون كما تاكل الانعام والنار مثوى لهم', NULL, 'Indeed, Allāh will admit those who have believed and done righteous deeds to gardens beneath which rivers flow, but those who disbelieve enjoy themselves and eat as grazing livestock eat, and the Fire will be a residence for them.', 'Sesungguhnya Allah akan memasukkan orang-orang yang beriman serta mengerjakan amal-amal yang soleh - ke dalam Syurga yang mengalir di bawahnya beberapa sungai; dan (sebaliknya) orang-orang yang kafir menikmati kesenangan di dunia serta mereka makan minum sebagaimana binatang-binatang ternak makan minum, sedang nerakalah menjadi tempat tinggal mereka.', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 22, NULL),
(47, 13, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَـٰهُمْ فَلَا نَاصِرَ لَهُمْ', 'وكاين من قرية هي اشد قوة من قريتك التي اخرجتك اهلكناهم فلا ناصر لهم', NULL, 'And how many a city was stronger than your city [i.e., Makkah] which drove you out? We destroyed them; and there was no helper for them.', 'Dan bukan sedikit (penduduk) negeri-negeri yang lebih kuat dari (penduduk) negerimu (wahai Muhammad) yang telah memaksamu keluar (berhijrah) - Kami binasakan mereka, maka tiadalah sesiapa pun yang dapat membela mereka.', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 14, NULL),
(47, 14, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', 'افمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا اهواءهم', NULL, 'So is he who is on clear evidence from his Lord like him to whom the evil of his work has been made attractive and they follow their [own] desires?', 'Dengan yang demikian, adakah orang orang (yang beriman dan taat) yang keadaannya sentiasa berdasarkan bukti yang nyata dari Tuhannya: sama seperti orang-orang (yang ingkar - derhaka) yang telah diperhiaskan kepadanya (oleh Syaitan) akan kejahatan amalnya (sehingga dipandangnya baik), dan yang telah menurut hawa nafsunya? (Sudah tentu tidak sama)!', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 13, NULL),
(47, 15, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ فِيهَآ أَنْهَـٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَـٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَـٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّـٰرِبِينَ وَأَنْهَـٰرٌ مِّنْ عَسَلٍ مُّصَفًّى ۖ وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ ۖ كَمَنْ هُوَ خَـٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ', 'مثل الجنة التي وعد المتقون فيها انهار من ماء غير اسن وانهار من لبن لم يتغير طعمه وانهار من خمر لذة للشاربين وانهار من عسل مصفى ولهم فيها من كل الثمرات ومغفرة من ربهم كمن هو خالد في النار وسقوا ماء حميما فقطع امعاءهم', NULL, 'Is the description of Paradise, which the righteous are promised, wherein are rivers of water unaltered, rivers of milk the taste of which never changes, rivers of wine delicious to those who drink, and rivers of purified honey, in which they will have from all [kinds of] fruits and forgiveness from their Lord... [Are its inhabitants] like those who abide eternally in the Fire and are given to drink scalding water that will sever their intestines?', 'Sifat Syurga yang telah dijanjikan kepada orang-orang yang bertaqwa (ialah seperti berikut): ada padanya beberapa sungai dari air yang tidak berubah (rasa dan baunya), dan beberapa sungai dari susu yang tidak berubah rasanya, serta beberapa sungai dari arak yang lazat bagi orang-orang yang meminumnya, dan juga beberapa sungai dari madu yang suci bersih. Dan ada pula untuk mereka di sana segala jenis buah-buahan, serta keredaan dari Tuhan mereka. (Adakah orang-orang yang tinggal kekal di dalam Syurga yang sedemikian itu keadaannya) sama seperti orang-orang yang tinggal kekal di dalam neraka dan diberi minum dari air yang menggelegak sehingga menjadikan isi perut mereka hancur? (Sudah tentu tidak sama)!', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 44, NULL),
(47, 16, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', 'ومنهم من يستمع اليك حتى اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال انفا اولئك الذين طبع الله على قلوبهم واتبعوا اهواءهم', NULL, 'And among them, [O Muḥammad], are those who listen to you, until when they depart from you, they say to those who were given knowledge, "What has he said just now?" Those are the ones of whom Allāh has sealed over their hearts and who have followed their [own] desires.', 'Dan di antara mereka (yang hadir di majlismu wahai Muhammad, ialah orang-orang munafik) yang mendengar ajaranmu (dengan sambil lewa), sehingga apabila mereka keluar dari sisimu berkatalah mereka (secara mengejek-ejek) kepada orang-orang yang diberi ilmu (dari kalangan sahabat-sahabatmu yang setia): “Apa yang dikatakan oleh Muhammad tadi?” Mereka (yang munafik) itu ialah orang-orang yang telah dimeteraikan Allah atas hati mereka, dan ialah orang-orang yang menurut hawa nafsunya.', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 24, NULL),
(47, 17, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', 'والذين اهتدوا زادهم هدى واتاهم تقواهم', NULL, 'And those who are guided - He increases them in guidance and gives them their righteousness.', 'Dan (sebaliknya) orang-orang yang menerima petunjuk (ke jalan yang benar), Allah menambahi mereka dengan hidayah petunjuk, serta memberi kepada mereka (dorongan) untuk mereka bertaqwa.', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 6, NULL),
(47, 18, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً ۖ فَقَدْ جَآءَ أَشْرَاطُهَا ۚ فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', 'فهل ينظرون الا الساعة ان تاتيهم بغتة فقد جاء اشراطها فانى لهم اذا جاءتهم ذكراهم', NULL, 'Then do they await except that the Hour should come upon them unexpectedly? But already there have come [some of] its indications. Then how [i.e., what good] to them, when it has come, will be their remembrance?', '(Kiranya golongan yang ingkar masih tidak mahu menerima peringatan yang diberi kepadanya) maka tidak ada lagi yang mereka tunggu melainkan saat kiamat yang akan datang kepada mereka secara mengejut, kerana sesungguhnya telah lahirlah tanda-tanda kedatangannya. Kalaulah demikian, maka bagaimanakah mereka dapat menerima peringatan yang diberi kepada mereka - apabila saat kiamat itu datang kepada mereka?', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 15, NULL),
(47, 19, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', 'فاعلم انه لا اله الا الله واستغفر لذنبك وللمؤمنين والمؤمنات والله يعلم متقلبكم ومثواكم', NULL, 'So know, [O Muḥammad], that there is no deity except Allāh and ask forgiveness for your sin and for the believing men and believing women. And Allāh knows of your movement and your resting place.', 'Oleh itu, maka tetapkanlah pengetahuanmu dan keyakinanmu (wahai Muhammad) bahawa sesungguhnya tiada Tuhan yang berhak disembah melainkan Allah, dan mintalah ampun kepadaNya bagi salah silap yang engkau lakukan, dan bagi dosa-dosa orang-orang yang beriman - lelaki dan perempuan; dan (ingatlah), Allah mengetahui akan keadaan gerak-geri kamu (di dunia) dan keadaan penetapan kamu (di akhirat).', FALSE, NULL, NULL, 508, 26, 203, 443, FALSE, 14, NULL),
(47, 20, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ ۖ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ ۙ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَأَوْلَىٰ لَهُمْ', 'ويقول الذين امنوا لولا نزلت سورة فاذا انزلت سورة محكمة وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولى لهم', NULL, 'Those who believe say, "Why has a sūrah not been sent down?" But when a precise sūrah is revealed and battle is mentioned therein, you see those in whose hearts is disease [i.e., hypocrisy] looking at you with a look of one overcome by death. And more appropriate for them [would have been]', 'Dan (kerana gemarkan pahala berjuang menegakkan Islam) orang-orang yang beriman berkata: “Alangkah baiknya sekiranya diturunkan satu surah (dari Al-Quran, yang memerintahkan kami berjuang)?” Maka apabila diturunkan satu surah (dari Al-Quran) yang tegas keterangannya dan tersebut padanya hukum-hukum yang mewajibkan perang Jihad (menentang pencerobohan musuh), sudah tentu engkau akan melihat orang-orang yang ada penyakit (kufur) dalam hatinya memandang kepadamu dengan terbeliak matanya kerana gerun takut menghadapi mati; dengan yang demikian, maka kebinasaanlah lebih hampir kepada mereka.', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 27, NULL),
(47, 21, 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ', 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ فَإِذَا عَزَمَ الْأَمْرُ فَلَوْ صَدَقُوا اللَّهَ لَكَانَ خَيْرًا لَّهُمْ', NULL, 'Obedience and good words. And when the matter [of fighting] was determined, if they had been true to Allāh, it would have been better for them.', '(Mereka selalu berkata: “Pendirian kami) mematuhi perintah dan memperkatakan perkataan yang baik (yang diredhai Allah)”. Dalam pada itu, apabila perkara (peperangan Jihad) itu ditetapkan wajibnya, (mereka tidak menyukainya); maka kalaulah mereka bersifat jujur kepada Allah (dengan mematuhi perintahNya), tentulah yang demikian itu amat baik bagi mereka.', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 22, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ', NULL, 'So would you perhaps, if you turned away, cause corruption on earth and sever your [ties of] relationship?', '(Kalau kamu tidak mematuhi perintah) maka tidakkah kamu harus dibimbang dan dikhuatirkan - jika kamu dapat memegang kuasa - kamu akan melakukan kerosakan di muka bumi, dan memutuskan hubungan silaturrahim dengan kaum kerabat?', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 23, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 'أُولَٰئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰ أَبْصَارَهُمْ', NULL, 'Those [who do so] are the ones that Allāh has cursed, so He deafened them and blinded their vision.', '(Orang-orang yang melakukan perkara yang tersebut) merekalah yang dilaknat oleh Allah serta ditulikan pendengaran mereka, dan dibutakan penglihatannya', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 24, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', 'أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَا', NULL, 'Then do they not reflect upon the Qur’ān, or are there locks upon [their] hearts?', '(Setelah diterangkan yang demikian) maka adakah mereka sengaja tidak berusaha memahami serta memikirkan isi Al-Quran? Atau telah ada di atas hati mereka kunci penutup (yang menghalangnya daripada menerima ajaran Al-Quran)?', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 25, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', 'إِنَّ الَّذِينَ ارْتَدُّوا عَلَىٰ أَدْبَارِهِم مِّن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَى الشَّيْطَانُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', NULL, 'Indeed, those who reverted back [to disbelief] after guidance had become clear to them - Satan enticed them and prolonged hope for them.', 'Sesungguhnya orang-orang yang telah berbalik kepada keingkaran mereka sesudah terang nyata kepada mereka kebenaran petunjuk (yang dikemukakan kepadanya), Syaitanlah yang memperdayakan mereka (berlaku demikian), serta memanjangkan angan-angan mereka.', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 26, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا لِلَّذِينَ كَرِهُوا مَا نَزَّلَ اللَّهُ سَنُطِيعُكُمْ فِي بَعْضِ الْأَمْرِ وَاللَّهُ يَعْلَمُ إِسْرَارَهُمْ', NULL, 'That is because they said to those who disliked what Allāh sent down, "We will obey you in part of the matter." And Allāh knows what they conceal.', 'Berlakunya yang demikian ialah: kerana mereka berkata kepada orang-orang yang tidak menyukai perkara yang diturunkan oleh Allah: “Kami akan patuh kepada kamu pada setengah perkara (yang berhubung dengan menentang Muhammad dan pengikutnya) itu”; sedang Allah mengetahui segala (perkataan dan perbuatan) yang mereka sembunyikan.', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 27, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ الْمَلَائِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ', NULL, 'Then how [will it be] when the angels take them in death, striking their faces and their backs?', '(Kalaulah mereka terlepas sekarang dari bencana kejahatan mereka) maka bagaimanakah (mereka dapat menolak azab seksa) apabila malaikat mengambil nyawa mereka sambil memukul muka dan punggung mereka?', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 28, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'ذَٰلِكَ بِأَنَّهُمُ اتَّبَعُوا مَا أَسْخَطَ اللَّهَ وَكَرِهُوا رِضْوَانَهُ فَأَحْبَطَ أَعْمَالَهُمْ', NULL, 'That is because they followed what angered Allāh and disliked [what earns] His pleasure, so He rendered worthless their deeds.', '(Kematian mereka dalam keadaan yang buruk) itu, kerana mereka menurut (serta melakukan) perkara-perkara yang menyebabkan kemurkaan Allah, dan mereka pula membenci perkara-perkara yang diredhaiNya; oleh itu, Allah gugurkan amal-amal mereka (yang baik, yang pernah mereka lakukan).', FALSE, NULL, NULL, 509, 26, 203, 444, FALSE, 0, NULL),
(47, 29, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', 'أَمْ حَسِبَ الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ اللَّهُ أَضْغَانَهُمْ', NULL, 'Or do those in whose hearts is disease think that Allāh would never expose their [feelings of] hatred?', 'Patutkah orang-orang (munafik) yang ada penyakit (syak, ragu-ragu) dalam hatinya: menyangka bahawa Allah tidak sekali-kali akan mendedahkan perasaan dendam dan hasad dengki mereka (terhadap Nabi Muhammad s.a.w dan umatnya)?', FALSE, NULL, NULL, 509, 26, 203, 445, FALSE, 0, NULL),
(47, 30, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', 'وَلَوْ نَشَاءُ لَأَرَيْنَاكَهُمْ فَلَعَرَفْتَهُم بِسِيمَاهُمْ وَلَتَعْرِفَنَّهُمْ فِي لَحْنِ الْقَوْلِ وَاللَّهُ يَعْلَمُ أَعْمَالَكُمْ', NULL, 'And if We willed, We could show them to you, and you would know them by their mark; but you will surely know them by the tone of [their] speech. And Allāh knows your deeds.', 'Dan sekiranya Kami kehendaki, tentulah Kami akan memperkenalkan mereka kepadamu (wahai Muhammad), lalu engkau tetap mengenalinya dengan tanda-tanda (yang menjadi sifat) mereka; dan demi sesungguhnya, engkau akan mengenali mereka dari gaya dan tutur katanya. Dan (ingatlah kamu masing-masing), Allah mengetahui segala yang kamu lakukan.', FALSE, NULL, NULL, 510, 26, 203, 445, FALSE, 0, NULL),
(47, 31, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ الْمُجَاهِدِينَ مِنكُمْ وَالصَّابِرِينَ وَنَبْلُوَ أَخْبَارَكُمْ', NULL, 'And We will surely test you until We make evident those who strive among you [for the cause of Allāh] and the patient, and We will test your affairs.', 'Dan demi sesungguhnya! Kami tetap menguji kamu (wahai orang-orang yang mengaku beriman) sehingga ternyata pengetahuan Kami tentang adanya orang-orang yang berjuang dari kalangan kamu dan orang-orang yang sabar (dalam menjalankan perintah Kami); dan (sehingga) Kami dapat mengesahkan (benar atau tidaknya) berita-berita tentang keadaan kamu.', FALSE, NULL, NULL, 510, 26, 203, 445, FALSE, 0, NULL),
(47, 32, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', 'إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ وَشَاقُّوا الرَّسُولَ مِن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَىٰ لَن يَضُرُّوا اللَّهَ شَيْئًا وَسَيُحْبِطُ أَعْمَالَهُمْ', NULL, 'Indeed, those who disbelieved and averted [people] from the path of Allāh and opposed the Messenger after guidance had become clear to them - never will they harm Allāh at all, and He will render worthless their deeds.', 'Sesungguhnya orang-orang yang kafir dan menghalangi (dirinya dan orang lain) dari jalan Allah, serta mereka memusuhi Rasul Allah setelah ternyata kepada mereka kebenaran petunjuk (yang dibawanya), mereka tidak sekali-kali akan dapat mendatangkan mudarat kepada Allah sedikitpun, dan (sebaliknya) Allah akan menghampakan perbuatan dan amal-amal mereka.', FALSE, NULL, NULL, 510, 26, 203, 445, FALSE, 0, NULL),
(47, 33, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَلَا تُبْطِلُوا أَعْمَالَكُمْ', NULL, 'O you who have believed, obey Allāh and obey the Messenger and do not invalidate your deeds.', 'Wahai orang-orang yang beriman! Taatlah kamu kepada Allah dan taatlah kepada Rasul Allah, dan janganlah kamu batalkan amal-amal kamu!', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(47, 34, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', 'إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ اللَّهُ لَهُمْ', NULL, 'Indeed, those who disbelieved and averted [people] from the path of Allāh and then died while they were disbelievers - never will Allāh forgive them.', 'Sesungguhnya orang-orang yang kafir dan menghalangi (dirinya dan orang lain) dari jalan Allah, kemudian mereka mati dengan keadaan kafirnya, maka Allah tidak sekali-kali akan mengampunkan mereka.', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(47, 35, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 'فَلَا تَهِنُوا وَتَدْعُوا إِلَى السَّلْمِ وَأَنتُمُ الْأَعْلَوْنَ وَاللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَالَكُمْ', NULL, 'So do not weaken and call for peace while you are superior; and Allāh is with you and will never deprive you of [the reward of] your deeds.', '(Apabila kamu telah mengetahui bahawa orang-orang kafir itu dihampakan amalnya dan diseksa oleh Allah) maka janganlah kamu (wahai orang-orang yang beriman) merasa lemah dan mengajak (musuh yang menceroboh) untuk berdamai, padahal kamulah orang-orang yang tertinggi keadaannya, lagi pula Allah bersama-sama kamu (untuk membela kamu mencapai kemenangan), dan Ia tidak sekali-kali akan mengurangi (pahala) amal-amal kamu.', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(47, 36, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', 'إِنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِن تُؤْمِنُوا وَتَتَّقُوا يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْأَلْكُمْ أَمْوَالَكُمْ', NULL, '[This] worldly life is only amusement and diversion. And if you believe and fear Allāh, He will give you your rewards and not ask you for your properties.', '(Ingatlah) bahawa kehidupan dunia (yang tidak berdasarkan iman dan taqwa) hanyalah ibarat permainan dan hiburan; dan jika kamu beriman serta bertaqwa, Allah akan memberikan kamu pahala amal kamu, dan Ia tidak meminta kepada kamu harta benda kamu (melainkan untuk memberikan kamu barang yang lebih baik daripadanya).', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(47, 37, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', 'إِن يَسْأَلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا وَيُخْرِجْ أَضْغَانَكُمْ', NULL, 'If He should ask you for them and press you, you would withhold, and He would expose your hatred [i.e., unwillingness].', '(Tabiat kamu wahai manusia) jika Tuhan meminta kepada kamu harta benda kamu serta mendesak kamu memberikanNya, nescaya kamu akan berlaku bakhil kedekut, dan kebakhilan itu akan melahirkan kemarahan dan kebencian kamu.', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(47, 38, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', 'هَا أَنتُمْ هَٰؤُلَاءِ تُدْعَوْنَ لِتُنفِقُوا فِي سَبِيلِ اللَّهِ فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِ وَاللَّهُ الْغَنِيُّ وَأَنتُمُ الْفُقَرَاءُ وَإِن تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوا أَمْثَالَكُم', NULL, 'Here you are - those invited to spend in the cause of Allāh - but among you are those who withhold [out of greed]. And whoever withholds only withholds [benefit] from himself; and Allāh is the Free of need, while you are the needy. And if you turn away [i.e., refuse], He will replace you with another people; then they will not be the likes of you.', '(Ingatlah), kamu ini adalah orang-orang yang bertabiat demikian - kamu diseru supaya menderma dan membelanjakan sedikit dari harta benda kamu pada jalan Allah, maka ada di antara kamu yang berlaku bakhil, padahal sesiapa yang berlaku bakhil maka sesungguhnya ia hanyalah berlaku bakhil kepada dirinya sendiri. Dan (ingatlah) Allah Maha kaya (tidak berhajat kepada sesuatupun), sedang kamu semua orang-orang miskin (yang sentiasa berhajat kepadaNya dalam segala hal). Dan jika kamu berpaling (daripada beriman, bertaqwa dan berderma) Ia akan menggantikan kamu dengan kaum yang lain; setelah itu mereka tidak akan berkeadaan seperti kamu.', FALSE, NULL, NULL, 510, 26, 204, 445, FALSE, 0, NULL),
(48, 1, 'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', 'انا فتحنا لك فتحا مبينا', NULL, 'Indeed, We have given you, [O Muḥammad], a clear conquest', 'Sesungguhnya Kami telah membuka bagi perjuanganmu (wahai Muhammad) satu jalan kemenangan yang jelas nyata,', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 5, NULL),
(48, 2, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا', 'ليغفر لك الله ما تقدم من ذنبك وما تاخر ويتم نعمته عليك ويهديك صراطا مستقيما', NULL, 'That Allāh may forgive for you what preceded of your sin [i.e., errors] and what will follow and complete His favor upon you and guide you to a straight path', 'Kemenangan yang dengan sebabnya Allah mengampunkan salah dan silapmu yang telah lalu dan yang terkemudian, dan menyempurnakan nikmatNya kepadamu, serta menambahkanmu hidayah ke jalan yang lurus (dalam mengembangkan Islam dan melaksanakan hukum-hukumnya).', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 15, NULL),
(48, 3, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', 'وينصرك الله نصرا عزيزا', NULL, 'And [that] Allāh may aid you with a mighty victory.', 'Dan dengan sebabnya Allah memberikanmu pertolongan (untuk mencapai kejayaan) dengan sepunuh-penuh dan sehandal-handal pertolongan (yang tidak ada bandingannya).', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 4, NULL),
(48, 4, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَـٰنًا مَّعَ إِيمَـٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'هو الذي انزل السكينة في قلوب المؤمنين ليزدادوا ايمانا مع ايمانهم ولله جنود السماوات والارض وكان الله عليما حكيما', NULL, 'It is He who sent down tranquility into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allāh belong the soldiers of the heavens and the earth, and ever is Allāh Knowing and Wise.', '(Tuhan yang membuka jalan kemenangan itu) Dia lah yang menurunkan semangat tenang tenteram ke dalam hati orang-orang yang beriman (semasa mereka meradang terhadap angkara musuh) supaya mereka bertambah iman dan yakin beserta dengan iman dan keyakinan mereka yang sedia ada; pada hal Allah menguasai tentera langit dan bumi (untuk menolong mereka); dan Allah adalah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 19, NULL),
(48, 5, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ ۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا', 'ليدخل المؤمنين والمؤمنات جنات تجري من تحتها الانهار خالدين فيها ويكفر عنهم سيئاتهم وكان ذلك عند الله فوزا عظيما', NULL, '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allāh, a great attainment –', '(Allah melakukan yang demikian) supaya ia memasukkan orang-orang yang beriman - lelaki dan perempuan - ke dalam Syurga yang mengalir di bawahnya beberapa sungai; dengan keadaan kekal mereka di dalamnya, serta menghapuskan dosa-dosa mereka; dan adalah yang demikian itu pada sisi Allah merupakan kejayaan yang besar (untuk mereka);', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 19, NULL),
(48, 6, 'وَيُعَذِّبَ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَـٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۖ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا', 'ويعذب المنافقين والمنافقات والمشركين والمشركات الظانين بالله ظن السوء عليهم دائرة السوء وغضب الله عليهم ولعنهم واعد لهم جهنم وساءت مصيرا', NULL, 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allāh an assumption of evil nature. Upon them is a misfortune of evil nature; and Allāh has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.', 'Dan supaya Ia menyeksa orang-orang munafik - lelaki dan perempuan, dan orang-orang musyrik - lelaki dan perempuan, yang menyangka terhadap Allah dengan sangkaan yang buruk (bahawa Ia akan mengecewakan RasulNya). Atas merekalah tertimpanya bala bencana yang dibawa oleh peredaran zaman; dan (selain itu) Allah murkai mereka dan melaknatkan mereka serta menyediakan untuk mereka neraka Jahannam; sedang neraka Jahannam itu adalah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 21, NULL),
(48, 7, 'وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'ولله جنود السماوات والارض وكان الله عزيزا حكيما', NULL, 'And to Allāh belong the soldiers of the heavens and the earth. And ever is Allāh Exalted in Might and Wise.', 'Dan Allah menguasai tentera langit dan bumi (untuk menyeksa orang-orang yang derhaka); dan Allah adalah Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 8, NULL),
(48, 8, 'إِنَّآ أَرْسَلْنَـٰكَ شَـٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'انا ارسلناك شاهدا ومبشرا ونذيرا', NULL, 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner', 'Sesungguhnya Kami telah mengutusmu (wahai Muhammad) sebagai Rasul yang menjadi saksi (yang diterima keterangannya), dan sebagai pembawa berita gembira (kepada orang-orang yang beriman), serta pemberi amaran (kepada orang-orang yang ingkar).', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 5, NULL),
(48, 9, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', 'لتؤمنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكرة واصيلا', NULL, 'That you [people] may believe in Allāh and His Messenger and honor him and respect him [i.e., the Prophet (ﷺ)] and exalt Him [i.e., Allāh] morning and afternoon.', '(Kami mengutusmu wahai Muhammad) supaya engkau dan umatmu beriman kepada Allah dan RasulNya, dan supaya kamu kuatkan ugamaNya serta memuliakanNya, dan supaya kamu beribadat kepadaNya pada waktu pagi dan petang.', FALSE, NULL, NULL, 511, 26, 204, 446, FALSE, 8, NULL),
(48, 10, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ ۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ ۖ وَمَنْ أَوْفَىٰ بِمَا عَـٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا', 'ان الذين يبايعونك انما يبايعون الله يد الله فوق ايديهم فمن نكث فانما ينكث على نفسه ومن اوفى بما عاهد عليه الله فسيؤتيه اجرا عظيما', NULL, 'Indeed, those who pledge allegiance to you, [O Muḥammad] - they are actually pledging allegiance to Allāh. The hand of Allāh is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allāh - He will give him a great reward.', 'Sesungguhnya orang-orang yang memberi pengakuan taat setia kepadamu (wahai Muhammad - untuk berjuang menentang musuh), mereka hanyasanya memberikan pengakuan taat setia kepada Allah; Allah mengawasi keadaan mereka memberikan taat setia itu (untuk membalasnya). Oleh itu, sesiapa yang tidak menyempurnakan janji setianya maka bahaya tidak menyempurnakan itu hanya menimpa dirinya; dan sesiapa yang menyempurnakan apa yang telah dijanjikannya kepada Allah, maka Allah akan memberi kepadanya pahala yang besar.', FALSE, NULL, NULL, 512, 26, 204, 446, FALSE, 25, NULL),
(48, 11, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا ۚ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۚ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا ۚ بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 'سيقول لك المخلفون من الاعراب شغلتنا اموالنا واهلونا فاستغفر لنا يقولون بالسنتهم ما ليس في قلوبهم قل فمن يملك لكم من الله شيئا ان اراد بكم ضرا او اراد بكم نفعا بل كان الله بما تعملون خبيرا', NULL, 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allāh at all if He intended for you harm or intended for you benefit? Rather, ever is Allāh, of what you do, Aware.', 'Orang-orang “A''raab” (kaum Arab Badwi) yang ketinggalan tidak turut (bersama-sama denganmu ke Hudaibiyah), akan berkata kepadamu (wahai Muhammad): “Kami telah dihalangi oleh urusan menjaga keselamatan harta benda dan anak isteri kami; oleh itu, pohonkanlah ampun kepada Allah untuk kami”. Mereka berkata dengan lidahnya apa yang tidak ada dalam hatinya. Katakanlah (wahai Muhammad: “Jika demikian sebab ketinggalan kamu) maka adakah sesiapa yang berkuasa mempertahankan kamu daripada terkena atau menerima sesuatu ketetapan dari Allah jika Ia tetapkan kamu ditimpa bahaya atau beroleh manfaat? (Tidak ada sesiapapun, dan apa yang kamu katakan itu bukanlah menjadi sebab) bahkan Allah adalah Maha Mendalam pengetahuanNya tentang sebab ketinggalan yang kamu lakukan itu (dan Ia akan membalasnya).', FALSE, NULL, NULL, 512, 26, 204, 447, FALSE, 37, NULL),
(48, 12, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا', 'بل ظننتم ان لن ينقلب الرسول والمؤمنون الى اهليهم ابدا وزين ذلك في قلوبكم وظننتم ظن السوء وكنتم قوما بورا', NULL, 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."', '“(Itu bukanlah sebabnya) bahkan sebabnya kamu telah menyangka bahawa Rasulullah dan orang-orang yang beriman (yang pergi berperang akan binasa semuanya dan) tidak akan kembali lagi kepada akan isteri dan keluarga masing-masing selama-lamanya; dan sangkaan yang demikian itu diperelokkan (oleh Syaitan) di dalam hati kamu (serta menerimanya); dan lagi kamu telah menyangka berbagai-bagai sangkaan yang buruk (terhadap ugama Allah yang dibawa oleh RasulNya); dan (dengan itu) menjadilah kamu kaum yang rosak binasa”.', FALSE, NULL, NULL, 512, 26, 204, 447, FALSE, 20, NULL),
(48, 13, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَعِيرًا', 'ومن لم يؤمن بالله ورسوله فانا اعتدنا للكافرين سعيرا', NULL, 'And whoever has not believed in Allāh and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.', 'Dan (ingatlah bahawa) sesiapa yang tidak beriman kepada Allah dan RasulNya, maka sesungguhnya Kami sediakan bagi orang-orang kafir itu api neraka yang menjulang-julang.', FALSE, NULL, NULL, 512, 26, 204, 447, FALSE, 9, NULL),
(48, 14, 'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'ولله ملك السماوات والارض يغفر لمن يشاء ويعذب من يشاء وكان الله غفورا رحيما', NULL, 'And to Allāh belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allāh Forgiving and Merciful.', 'Dan (ingatlah juga bahawa) kuasa pemerintahan langit dan bumi adalah hak kepunyaan Allah, Ia berkuasa mengampunkan sesiapa yang dikehendakiNya, dan Ia juga berkuasa menyeksa sesiapa yang dikehendakiNya; dan Allah adalah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 512, 26, 204, 447, FALSE, 14, NULL),
(48, 15, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ ۖ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَـٰمَ ٱللَّهِ ۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا ۚ بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا', 'سيقول المخلفون اذا انطلقتم الى مغانم لتاخذوها ذرونا نتبعكم يريدون ان يبدلوا كلام الله قل لن تتبعونا كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون الا قليلا', NULL, 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allāh. Say, "Never will you follow us. Thus did Allāh say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.', 'Orang-orang (munafik) yang tidak turut berjuang (bersama-sama kamu) akan berkata semasa kamu pergi (mengepong musuh serta) mendapat harta rampasan perang: Biarkanlah kami turut serta dengan kamu!” Mereka (dengan itu) hendak mengubah janji Allah (yang menentukan hanya orang-orang yang turut hadir di Hudaibiyah sahaja yang berhak mendapat harta rampasan perang itu). Katakanlah (wahai Muhammad): “Kamu tidak dibenarkan sama sekali turut serta dengan kami; demikianlah Allah menegaskan (larangan itu) semenjak dahulu lagi”. Mereka akan berkata pula: “(Bukan Tuhan yang melarang) bahkan kamu dengki kepada kami”, (apa yang mereka katakan itu tidaklah benar), bahkan mereka tidak faham kecuali sedikit sahaja; (mereka hanya faham tentang kehidupan dan kesenangan dunia semata-mata).', FALSE, NULL, NULL, 512, 26, 204, 447, FALSE, 31, NULL),
(48, 16, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَـٰتِلُونَهُمْ أَوْ يُسْلِمُونَ ۖ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا ۖ وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا', 'قل للمخلفين من الاعراب ستدعون الى قوم اولي باس شديد تقاتلونهم او يسلمون فان تطيعوا يؤتكم الله اجرا حسنا وان تتولوا كما توليتم من قبل يعذبكم عذابا اليما', NULL, 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allāh will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."', 'Katakanlah (wahai Muhammad) kepada orang-orang yang tidak turut berjuang (bersama-samamu) dari kalangan kaum-kaum Arab Badwi: “Kamu akan diajak menentang satu kaum (penceroboh) yang sangat kuat gagah supaya kamu memeranginya, atau mereka menurut perintah Islam (secara damai). Jika kamu taat (menjalankan perintah Allah ini), Allah akan mengurniakan kamu dengan balasan yang baik (di dunia dan akhirat), dan kalau kamu berpaling ingkar seperti keingkaran dahulu, nescaya Allah akan menyeksa kamu dengan azab yang tidak terperi sakitnya”.', FALSE, NULL, NULL, 513, 26, 204, 447, FALSE, 28, NULL),
(48, 17, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا', 'ليس على الاعمى حرج ولا على الاعرج حرج ولا على المريض حرج ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار ومن يتول يعذبه عذابا اليما', NULL, 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allāh and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.', 'Tidaklah menjadi salah kepada orang buta, dan tidaklah menjadi salah kepada orang tempang, dan tidaklah menjadi salah kepada orang sakit (tidak turut berperang, kerana masing-masing ada uzurnya). Dan (ingatlah), sesiapa yang taat kepada Allah dan RasulNya, akan dimasukkanNya ke dalam Syurga yang mengalir di bawahnya beberapa sungai; dan sesiapa yang berpaling ingkar, akan diseksaNya dengan azab yang tidak terperi sakitnya.', FALSE, NULL, NULL, 513, 26, 204, 447, FALSE, 27, NULL),
(48, 18, '۞ لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَـٰبَهُمْ فَتْحًا قَرِيبًا', 'لقد رضي الله عن المؤمنين اذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فانزل السكينة عليهم واثابهم فتحا قريبا', NULL, 'Certainly was Allāh pleased with the believers when they pledged allegiance to you, [O Muḥammad], under the tree, and He knew what was in their hearts, so He sent down tranquility upon them and rewarded them with an imminent conquest', 'Demi sesungguhnya! Allah reda akan orang-orang yang beriman, ketika mereka memberikan pengakuan taat setia kepadamu (wahai Muhammad) di bawah naungan pohon (yang termaklum di Hudaibiyah); maka (dengan itu) ternyata apa yang sedia diketahuiNya tentang (kebenaran iman dan taat setia) yang ada dalam hati mereka, lalu Ia menurunkan semangat tenang tenteram kepada mereka, dan membalas mereka dengan kemenangan yang dekat masa datangnya;', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 19, NULL),
(48, 19, 'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا ۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'ومغانم كثيرة ياخذونها وكان الله عزيزا حكيما', NULL, 'And much war booty which they will take. And ever is Allāh Exalted in Might and Wise.', 'Dan juga dengan banyak harta rampasan perang, yang mereka akan dapat mengambilnya. Dan (ingatlah), Allah adalah Maha kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 7, NULL),
(48, 20, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَـٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا', 'وعدكم الله مغانم كثيرة تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون اية للمؤمنين ويهديكم صراطا مستقيما', NULL, 'Allāh has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.', '(Sebagai memuliakan orang-orang yang memberi pengakuan taat setianya di Hudaibiyah, Tuhan menujukan firmannya kepada mereka): Allah menjanjikan kepada kamu harta rampasan yang banyak yang kamu akan mengambilnya, lalu Ia menyegerakan untuk kamu harta rampasan perang ini, serta Ia telah menahan tangan manusia (pihak musuh di situ) daripada menyerang kamu; (Allah melakukan yang demikian supaya kamu beroleh manfaat) dan supaya menjadi tanda (yang membuktikan kebenaran janjiNya) bagi orang-orang yang beriman, dan juga supaya Ia menambahkan kamu hidayah ke jalan yang lurus.', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 18, NULL),
(48, 21, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', 'وَأُخْرَىٰ لَمْ تَقْدِرُوا عَلَيْهَا قَدْ أَحَاطَ اللَّهُ بِهَا وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرًا', NULL, 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allāh has already encompassed. And ever is Allāh, over all things, competent.', 'Dan ada lagi harta rampasan lain yang kamu belum dapat menguasainya, (tetapi) Allah telah memelihara harta itu dengan kekuasaanNya (untuk kamu mendapatnya); dan (ingatlah), Allah adalah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 0, NULL),
(48, 22, 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'وَلَوْ قَاتَلَكُمُ الَّذِينَ كَفَرُوا لَوَلَّوُا الْأَدْبَارَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', NULL, 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.', 'Dan sekiranya orang-orang kafir (dari penduduk Makkah) itu memerangi kamu (di Hudaibiyah), tentulah mereka akan berpaling melarikan diri dengan kekalahan; kemudian mereka tidak akan beroleh sesiapapun yang menjadi pelindung atau memberikan pertolongan.', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 0, NULL),
(48, 23, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'سُنَّةَ اللَّهِ الَّتِي قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا', NULL, '[This is] the established way of Allāh which has occurred before. And never will you find in the way of Allāh any change.', '(Kekalahan orang-orang yang menentang Rasul Allah sudah tetap menurut) “Sunnatullah” (peraturan Allah) yang telah berlaku semenjak dahulu lagi; dan engkau tidak akan mendapati sebarang perubahan bagi cara dan peraturan Allah itu.', FALSE, NULL, NULL, 513, 26, 205, 448, FALSE, 0, NULL),
(48, 24, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِن بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', NULL, 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allāh, of what you do, Seeing.', 'Dan Dia lah yang telah menahan tangan mereka (yang musyrik) daripada melakukan perkara yang buruk terhadap kamu, dan tangan kamu daripada berbuat demikian kepada mereka di kawasan Makkah, sesudah Ia menjadikan kamu dapat menewaskan mereka. Dan (ingatlah), Allah adalah Maha Melihat akan segala yang kamu kerjakan.', FALSE, NULL, NULL, 514, 26, 205, 448, FALSE, 0, NULL),
(48, 25, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', 'هُمُ الَّذِينَ كَفَرُوا وَصَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ وَالْهَدْيَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَاءٌ مُّؤْمِنَاتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَئُوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌ بِغَيْرِ عِلْمٍ لِّيُدْخِلَ اللَّهُ فِي رَحْمَتِهِ مَن يَشَاءُ لَوْ تَزَيَّلُوا لَعَذَّبْنَا الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابًا أَلِيمًا', NULL, 'They are the ones who disbelieved and obstructed you from al-Masjid al-Ḥarām while the offering was prevented from reaching its place of sacrifice. And if not for believing men and believing women whom you did not know - that you might trample [i.e., kill] them and there would befall you because of them dishonor without [your] knowledge - [you would have been permitted to enter Makkah]. [This was so] that Allāh might admit to His mercy whom He willed. If they had been apart [from them], We would have punished those who disbelieved among them with painful punishment', 'Mereka itulah orang-orang yang kafir dan menghalang kamu daripada masuk ke masjid Al-Haraam (Makkah Al-Mukarramah) serta (menyebabkan) binatang-binatang korban (yang kamu bawa): tertahan dari sampai ke tempat sembelihannya. Dan kalaulah tidak kerana kemungkinan kamu akan melakukan pembunuhan yang tidak sengaja terhadap beberapa orang yang beriman, lelaki dan perempuan, yang ada di antara orang-orang kafir itu, pada hal kamu tidak mengetahui mereka beriman, yang akibatnya kamu akan menanggung kesusahan dan dukacita disebabkan pembunuhan mereka, - (tentulah diizinkan kamu menyerang kaum musyrik yang mengancam kamu itu). (Tetapi tidak diizinkan) kerana Allah hendak memasukkan sesiapa yang dikehendakiNya ke dalam rahmatNya. Kalaulah mereka (penduduk Makkah - yang beriman dan yang musyrik) itu berpisahan (di antara satu puak dengan yang lain), tentulah Kami menyeksa orang-orang yang kafir dari mereka dengan seksa (di dunia) yang tidak terperi sakitnya.', FALSE, NULL, NULL, 514, 26, 205, 448, FALSE, 0, NULL),
(48, 26, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', 'إِذْ جَعَلَ الَّذِينَ كَفَرُوا فِي قُلُوبِهِمُ الْحَمِيَّةَ حَمِيَّةَ الْجَاهِلِيَّةِ فَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَىٰ رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ التَّقْوَىٰ وَكَانُوا أَحَقَّ بِهَا وَأَهْلَهَا وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ عَلِيمًا', NULL, 'When those who disbelieved had put into their hearts chauvinism - the chauvinism of the time of ignorance. But Allāh sent down His tranquility upon His Messenger and upon the believers and imposed upon them the word of righteousness, and they were more deserving of it and worthy of it. And ever is Allāh, of all things, Knowing.', '(Ingatlah dan kenangkanlah ihsan Tuhan kepada kamu) ketika orang-orang yang kafir itu menimbulkan perasaan sombong angkuh yang ada dalam hati mereka (terhadap kebenaran Islam) - perasaan sombong angkuh secara Jahiliyah (yang menyebabkan kamu panas hati dan terharu), lalu Allah menurunkan semangat tenang tenteram kepada RasulNya dan kepada orang-orang yang beriman (sehingga tercapailah perdamaian), serta meminta mereka tetap berpegang kepada “Kalimah Taqwa”, sedang mereka (di sisi Allah) adalah orang-orang yang sangat berhak dengan “kalimah Taqwa” itu serta menjadi ahlinya. Dan (ingatlah), Allah adalah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 514, 26, 205, 448, FALSE, 0, NULL),
(48, 27, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', 'لَّقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالْحَقِّ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَاءَ اللَّهُ آمِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', NULL, 'Certainly has Allāh showed to His Messenger the vision [i.e., dream] in truth. You will surely enter al-Masjid al-Ḥarām, if Allāh wills, in safety, with your heads shaved and [hair] shortened, not fearing [anyone]. He knew what you did not know and has arranged before that a conquest near [at hand].', 'Demi sesungguhnya! Allah tetap menyatakan benar RasulNya dalam perkara mimpi itu dengan kenyataan yang sebenar; iaitu sesungguhnya kamu tetap akan memasuki Masjid Al-Haraam - insya Allah (pada masa yang ditentukanNya) - dalam keadaan aman (menyempurnakan ibadat umrah kamu) dengan mencukur kepala kamu, dan kalau (tidak pun) menggunting sedikit rambutnya, serta kamu tidak merasa takut (akan pengkhianatan musuh sehingga kamu keluar balik dari situ). (Allah mengangguhkan berlakunya kenyataan itu) kerana Ia mengetahui (adanya feadah dalam penangguhan itu) yang kamu tidak mengetahuinya; maka Ia menyediakan sebelum (terlaksananya mimpi) itu, satu kemenangan yang dekat (masa berlakunnya).', FALSE, NULL, NULL, 514, 26, 205, 449, FALSE, 0, NULL),
(48, 28, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَىٰ وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَىٰ بِاللَّهِ شَهِيدًا', NULL, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion. And sufficient is Allāh as Witness.', '(Allah yang menyatakan itu) Dia lah yang telah mengutus RasulNya (Muhammad, s.a.w) dengan membawa hidayah petunjuk dan ugama yang benar (ugama Islam), supaya Dia memenangkannya dan meninggikannya atas segala bawaan ugama yang lain; dan cukuplah Allah menjadi Saksi (tentang kebenaran apa yang dibawa oleh RasulNya itu).', FALSE, NULL, NULL, 514, 26, 205, 449, FALSE, 0, NULL),
(48, 29, 'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا', 'مُّحَمَّدٌ رَّسُولُ اللَّهِ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ تَرَاهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ اللَّهِ وَرِضْوَانًا سِيمَاهُمْ فِي وُجُوهِهِم مِّنْ أَثَرِ السُّجُودِ ذَٰلِكَ مَثَلُهُمْ فِي التَّوْرَاةِ وَمَثَلُهُمْ فِي الْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْأَهُ فَآزَرَهُ فَاسْتَغْلَظَ فَاسْتَوَىٰ عَلَىٰ سُوقِهِ يُعْجِبُ الزُّرَّاعَ لِيَغِيظَ بِهِمُ الْكُفَّارَ وَعَدَ اللَّهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', NULL, 'Muḥammad is the Messenger of Allāh; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allāh and [His] pleasure. Their sign is in their faces from the effect of prostration [i.e., prayer]. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that He [i.e., Allāh] may enrage by them the disbelievers. Allāh has promised those who believe and do righteous deeds among them forgiveness and a great reward.', 'Nabi Muhammad (s.a.w) ialah Rasul Allah; dan orang-orang yang bersama dengannya bersikap keras dan tegas terhadap orang-orang kafir yang (memusuhi Islam), dan sebaiknya bersikap kasih sayang serta belas kasihan kasihan sesama sendiri (umat Islam). Engkau melihat mereka tetap beribadat rukuk dan sujud, dengan mengharapkan limpah kurnia (pahala) dari Tuhan mereka serta mengharapkan keredaanNya. Tanda yang menunjukkan mereka (sebagai orang-orang yang soleh) terdapat muka mereka - dari kesan sujud (dan ibadat mereka yang ikhlas). Demikianlah sifat mereka yang tersebut di dalam Kitab Taurat; dan sifat mereka di dalam Kitab Injil pula ialah: (bahawa mereka diibaratkan) sebagai pokok tanaman yang mengeluarkan anak dan tunasnya, lalu anak dan tunasnya itu menyuburkannya, sehingga ia menjadi kuat, lalu ia tegap berdiri di atas (pangkal) batangnya dengan keadaan yang mengkagumkan orang-orang yang menanamnya. (Allah menjadikan sahabat-sahabat Nabi Muhammad, s.a.w dan pengikut-pengikutnya kembang biak serta kuat gagah sedemikian itu) kerana Ia hendak menjadikan orang-orang kafir merana dengan perasaan marah dan hasad dengki - dengan kembang biaknya umat Islam itu. (Dan selain itu) Allah telah menjanjikan orang-orang yang beriman dan beramal soleh dari mereka, keampunan dan pahala yang besar.', FALSE, NULL, NULL, 515, 26, 205, 449, FALSE, 0, NULL),
(49, 1, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'يا ايها الذين امنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم', NULL, 'O you who have believed, do not put [yourselves] before Allāh and His Messenger but fear Allāh. Indeed, Allāh is Hearing and Knowing.', 'Wahai orang-orang yang beriman! Janganlah kamu memandai-mandai (melakukan sesuatu perkara) sebelum (mendapat hukum atau kebenaran) Allah dan RasulNya; dan bertaqwalah kamu kepada Allah; sesungguhnya Allah Maha Mendengar, lagi Maha Mengetahui.', FALSE, NULL, NULL, 515, 26, 206, 450, FALSE, 15, NULL),
(49, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَـٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', 'يا ايها الذين امنوا لا ترفعوا اصواتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعمالكم وانتم لا تشعرون', NULL, 'O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not.', 'Wahai orang-orang yang beriman! Janganlah kamu mengangkat suara kamu melebihi suara Nabi, dan janganlah kamu menyaringkan suara (dengan lantang) semasa bercakap dengannya sebagaimana setengah kamu menyaringkan suaranya semasa bercakap dengan setengahnya yang lain. (Larangan yang demikian) supaya amal-amal kamu tidak hapus pahalanya, sedang kamu tidak menyedarinya.', FALSE, NULL, NULL, 515, 26, 206, 450, FALSE, 22, NULL),
(49, 3, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ ۚ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', 'ان الذين يغضون اصواتهم عند رسول الله اولئك الذين امتحن الله قلوبهم للتقوى لهم مغفرة واجر عظيم', NULL, 'Indeed, those who lower their voices before the Messenger of Allāh - they are the ones whose hearts Allāh has tested for righteousness. For them is forgiveness and great reward.', 'Sesungguhnya orang-orang yang merendahkan suaranya semasa mereka berada di sisi Rasulullah (s.a.w), - merekalah orang-orang yang telah dibersihkan Allah hati mereka untuk bertaqwa; mereka beroleh keampunan dan pahala yang besar.', FALSE, NULL, NULL, 515, 26, 206, 450, FALSE, 17, NULL),
(49, 4, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'ان الذين ينادونك من وراء الحجرات اكثرهم لا يعقلون', NULL, 'Indeed, those who call you, [O Muḥammad], from behind the chambers - most of them do not use reason.', 'Sesungguhnya orang-orang yang memanggilmu dari luar bilik-bilik (tempat ahlimu, wahai Muhammad), kebanyakan mereka tidak mengerti (adab dan tata tertib).', FALSE, NULL, NULL, 515, 26, 206, 450, FALSE, 9, NULL),
(49, 5, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'ولو انهم صبروا حتى تخرج اليهم لكان خيرا لهم والله غفور رحيم', NULL, 'And if they had been patient until you [could] come out to them, it would have been better for them. But Allāh is Forgiving and Merciful.', 'Dan kalaulah mereka bersabar menunggu sehingga engkau keluar menemui mereka, tentulah cara yang demikian lebih baik bagi mereka; dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 12, NULL),
(49, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَـٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَـٰدِمِينَ', 'يا ايها الذين امنوا ان جاءكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهالة فتصبحوا على ما فعلتم نادمين', NULL, 'O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful.', 'Wahai orang-orang yang beriman! Jika datang kepada kamu seorang fasik membawa sesuatu berita, maka selidikilah (untuk menentukan) kebenarannya, supaya kamu tidak menimpakan sesuatu kaum dengan perkara yang tidak diingini - dengan sebab kejahilan kamu (mengenainya) - sehingga menjadikan kamu menyesali apa yang kamu telah lakukan.', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 17, NULL),
(49, 7, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ ۚ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَـٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَـٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', 'واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمان وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اولئك هم الراشدون', NULL, 'And know that among you is the Messenger of Allāh. If he were to obey you in much of the matter, you would be in difficulty, but Allāh has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided.', 'Dan ketahuilah! Bahawasanya dalam kalangan kamu ada Rasulullah (maka janganlah kemahuan atau pendapat kamu mendahului pentadbirannya); kalaulah ia menurut kehendak kamu dalam kebanyakan perkara, tentulah kamu akan mengalami kesukaran; akan tetapi (Rasulullah tidak menurut melainkan perkara yang diwahyukan kepadanya, dan kamu wahai orang-orang yang beriman hendaklah bersyukur kerana) Allah menjadikan iman suatu perkara yang kamu cintai serta di perhiaskannya dalam hati kamu, dan menjadikan kekufuran dan perbuatan fasik serta perbuatan derhaka itu: perkara-perkara yang kamu benci; mereka yang bersifat demikian ialah orang-orang yang tetap menurut jalan yang lurus; -', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 28, NULL),
(49, 8, 'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'فضلا من الله ونعمة والله عليم حكيم', NULL, '[It is] as bounty from Allāh and favor. And Allāh is Knowing and Wise.', '(Mereka dijadikan berkeadaan demikian) sebagai limpah kurnia dan nikmat pemberian dari Allah; dan (ingatlah), Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 7, NULL),
(49, 9, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَـٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'وان طائفتان من المؤمنين اقتتلوا فاصلحوا بينهما فان بغت احداهما على الاخرى فقاتلوا التي تبغي حتى تفيء الى امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين', NULL, 'And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allāh. And if it returns, then make settlement between them in justice and act justly. Indeed, Allāh loves those who act justly.', 'Dan jika dua puak dari orang-orang yang beriman berperang, maka damaikanlah di antara keduanya; jika salah satunya berlaku zalim terhadap yang lain, maka lawanlah puak yang zalim itu sehingga ia kembali mematuhi perintah Allah; jika ia kembali patuh maka damaikanlah di antara keduanya dengan adil (menurut hukum Allah), serta berlaku adillah kamu (dalam segala perkara); sesungguhnya Allah mengasihi orang-orang yang berlaku adil.', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 30, NULL),
(49, 10, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'انما المؤمنون اخوة فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون', NULL, 'The believers are but brothers, so make settlement between your brothers. And fear Allāh that you may receive mercy.', 'Sebenarnya orang-orang yang beriman itu adalah bersaudara, maka damaikanlah di antara dua saudara kamu (yang bertelingkah) itu; dan bertaqwalah kepada Allah supaya kamu beroleh rahmat.', FALSE, NULL, NULL, 516, 26, 206, 450, FALSE, 10, NULL),
(49, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَـٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَـٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'يا ايها الذين امنوا لا يسخر قوم من قوم عسى ان يكونوا خيرا منهم ولا نساء من نساء عسى ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقاب بئس الاسم الفسوق بعد الايمان ومن لم يتب فاولئك هم الظالمون', NULL, 'O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name [i.e., mention] of disobedience after [one''s] faith. And whoever does not repent - then it is those who are the wrongdoers.', 'Wahai orang-orang yang beriman! Janganlah sesuatu puak (dari kaum lelaki) mencemuh dan merendah-rendahkan puak lelaki yang lain, (kerana) harus puak yang dicemuhkan itu lebih baik daripada mereka; dan janganlah pula sesuatu puak dari kaum perempuan mencemuh dan merendah-rendahkan puak perempuan yang lain, (kerana) harus puak yang dicemuhkan itu lebih baik daripada mereka; dan janganlah setengah kamu menyatakan keaiban setengahnya yang lain; dan janganlah pula kamu panggil-memanggil antara satu dengan yang lain dengan gelaran yang buruk. (Larangan-larangan yang tersebut menyebabkan orang yang melakukannya menjadi fasik, maka) amatlah buruknya sebutan nama fasik (kepada seseorang) sesudah ia beriman. Dan (ingatlah), sesiapa yang tidak bertaubat (daripada perbuatan fasiknya) maka merekalah orang-orang yang zalim.', FALSE, NULL, NULL, 516, 26, 206, 451, FALSE, 39, NULL),
(49, 12, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ', 'يا ايها الذين امنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم', NULL, 'O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allāh; indeed, Allāh is Accepting of Repentance and Merciful.', 'Wahai orang-orang yang beriman! Jauhilah kebanyakan dari sangkaan (supaya kamu tidak menyangka sangkaan yang dilarang) kerana sesungguhnya sebahagian dari sangkaan itu adalah dosa; dan janganlah kamu mengintip atau mencari-cari kesalahan dan keaiban orang; dan janganlah setengah kamu mengumpat setengahnya yang lain. Adakah seseorang dari kamu suka memakan daging saudaranya yang telah mati? (Jika demikian keadaan mengumpat) maka sudah tentu kamu jijik kepadanya. (Oleh itu, patuhilah larangan-larangan yang tersebut) dan bertaqwalah kamu kepada Allah; sesungguhnya Allah Penerima taubat, lagi Maha mengasihani.', FALSE, NULL, NULL, 517, 26, 206, 451, FALSE, 31, NULL),
(49, 13, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَـٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَـٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ', 'يا ايها الناس انا خلقناكم من ذكر وانثى وجعلناكم شعوبا وقبائل لتعارفوا ان اكرمكم عند الله اتقاكم ان الله عليم خبير', NULL, 'O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allāh is the most righteous of you. Indeed, Allāh is Knowing and Aware.', 'Wahai umat manusia! Sesungguhnya Kami telah menciptakan kamu dari lelaki dan perempuan, dan Kami telah menjadikan kamu berbagai bangsa dan bersuku puak, supaya kamu berkenal-kenalan (dan beramah mesra antara satu dengan yang lain). Sesungguhnya semulia-mulia kamu di sisi Allah ialah orang yang lebih taqwanya di antara kamu, (bukan yang lebih keturunan atau bangsanya). Sesungguhnya Allah Maha Mengetahui, lagi Maha Mendalam PengetahuanNya (akan keadaan dan amalan kamu).', FALSE, NULL, NULL, 517, 26, 206, 451, FALSE, 20, NULL),
(49, 14, '۞ قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا ۖ قُل لَّمْ تُؤْمِنُوا۟ وَلَـٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَـٰنُ فِى قُلُوبِكُمْ ۖ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَـٰلِكُمْ شَيْـًٔا ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'قالت الاعراب امنا قل لم تؤمنوا ولكن قولوا اسلمنا ولما يدخل الايمان في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعمالكم شيئا ان الله غفور رحيم', NULL, 'The bedouins say, "We have believed." Say, "You have not [yet] believed; but say [instead], ''We have submitted,'' for faith has not yet entered your hearts. And if you obey Allāh and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allāh is Forgiving and Merciful."', 'Orang-orang “A''raab” berkata: “Kami telah beriman”. Katakanlah (wahai Muhammad): “Kamu belum beriman, (janganlah berkata demikian), tetapi sementara iman belum lagi meresap masuk ke dalam hati kamu berkatalah sahaja: ‘kami telah Islam’. Dan (ingatlah), jika kamu taat kepada Allah RasulNya (zahir dan batin), Allah tidak akan mengurangkan sedikitpun dari pahala amal-amal kamu, kerana sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani”.', FALSE, NULL, NULL, 517, 26, 207, 451, FALSE, 27, NULL),
(49, 15, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ', 'انما المؤمنون الذين امنوا بالله ورسوله ثم لم يرتابوا وجاهدوا باموالهم وانفسهم في سبيل الله اولئك هم الصادقون', NULL, 'The believers are only the ones who have believed in Allāh and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allāh. It is those who are the truthful.', 'Sesungguhnya orang-orang yang sebenar-benarnya beriman hanyalah orang-orang yang percaya kepada Allah dan RasulNya, kemudian mereka (terus percaya dengan) tidak ragu-ragu lagi, serta mereka berjuang dengan harta benda dan jiwa mereka pada jalan Allah; mereka itulah orang-orang yang benar (pengakuan imannya).', FALSE, NULL, NULL, 517, 26, 207, 451, FALSE, 18, NULL),
(49, 16, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'قل اتعلمون الله بدينكم والله يعلم ما في السماوات وما في الارض والله بكل شيء عليم', NULL, 'Say, "Would you acquaint Allāh with your religion while Allāh knows whatever is in the heavens and whatever is on the earth, and Allāh is Knowing of all things?"', 'Katakanlah (kepada orang-orang “A''raab” itu wahai Muhammad): “Patutkah kamu hendak memberitahu kepada Allah tentang ugama kamu (dengan berkata: ‘kami telah beriman’)? Padahal Allah mengetahui segala yang ada di langit dan yang ada di bumi, dan Allah Maha Mengetahui akan tiap-tiap sesuatu”.', FALSE, NULL, NULL, 517, 26, 207, 451, FALSE, 16, NULL),
(49, 17, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ ۖ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَـٰمَكُم ۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَـٰنِ إِن كُنتُمْ صَـٰدِقِينَ', 'يمنون عليك ان اسلموا قل لا تمنوا علي اسلامكم بل الله يمن عليكم ان هداكم للايمان ان كنتم صادقين', NULL, 'They consider it a favor to you that they have accepted Islām. Say, "Do not consider your Islām a favor to me. Rather, Allāh has conferred favor upon you that He has guided you to the faith, if you should be truthful."', 'Mereka mengira dirinya berbudi kepadamu (wahai Muhammad) dengan sebab mereka telah Islam (tidak melawan dan tidak menentang). Katakanlah (kepada mereka): “Janganlah kamu mengira keislaman kamu itu sebagai budi kepadaku, bahkan (kalaulah sah dakwaan kamu itu sekalipun maka) Allah jualah yang berhak membangkit-bangkitkan budiNya kepada kamu, kerana Dia lah yang memimpin kamu kepada iman (yang kamu dakwakan itu), kalau betul kamu orang-orang yang benar (pengakuan imannya).', FALSE, NULL, NULL, 517, 26, 207, 451, FALSE, 19, NULL),
(49, 18, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 'ان الله يعلم غيب السماوات والارض والله بصير بما تعملون', NULL, 'Indeed, Allāh knows the unseen [aspects] of the heavens and the earth. And Allāh is Seeing of what you do.', '“Sesungguhnya Allah mengetahui segala rahsia langit dan bumi, dan Allah Maha Melihat akan segala yang kamu kerjakan”.', FALSE, NULL, NULL, 517, 26, 207, 451, FALSE, 10, NULL),
(50, 1, 'قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', 'ق والقران المجيد', NULL, 'Qāf. By the honored Qur’ān...', 'Qaaf. Demi Al-Quran yang melimpah-limpah kemuliaan dan kebaikannya (bahawa sesungguhnya Muhammad adalah Rasul yang diutus memberi peringatan dan amaran).', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 3, NULL),
(50, 2, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَـٰفِرُونَ هَـٰذَا شَىْءٌ عَجِيبٌ', 'بل عجبوا ان جاءهم منذر منهم فقال الكافرون هذا شيء عجيب', NULL, 'But they wonder that there has come to them a warner from among themselves, and the disbelievers say, "This is an amazing thing.', '(Kaum musyrik Makkah bukan sahaja mengingkari kerasulannya) bahkan mereka merasa hairan kerana datang kepada mereka, dari kalangan mereka sendiri, seorang Rasul pemberi peringatan dan amaran (mengenai perkara hidup semula sesudah mati); lalu orang-orang yang kafir itu berkata: “Ini adalah satu perkara yang menakjubkan!', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 11, NULL),
(50, 3, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ۖ ذَٰلِكَ رَجْعٌۢ بَعِيدٌ', 'ااذا متنا وكنا ترابا ذلك رجع بعيد', NULL, 'When we have died and have become dust, [we will return to life]? That is a distant [i.e., unlikely] return."', '“Adakah (kita akan kembali hidup) sesudah kita mati dan menjadi tanah? Itu adalah cara kembali yang jauh (dari kemungkinan, kerana jasad yang telah hancur tidak dapat diketahui lagi)”.', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 7, NULL),
(50, 4, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ ۖ وَعِندَنَا كِتَـٰبٌ حَفِيظٌۢ', 'قد علمنا ما تنقص الارض منهم وعندنا كتاب حفيظ', NULL, 'We know what the earth diminishes [i.e., consumes] of them, and with Us is a retaining record.', '(Apa yang mereka katakan itu tidaklah benar, kerana) Kami sedia mengetahui apa yang dimakan oleh bumi sedikit demi sedikit dari (tubuh orang mati) mereka, serta ada di sisi Kami sebuah Kitab yang menyimpan (catitan segala perkara yang berlaku).', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 9, NULL),
(50, 5, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ', 'بل كذبوا بالحق لما جاءهم فهم في امر مريج', NULL, 'But they denied the truth when it came to them, so they are in a confused condition.', '(Mereka tidak mahu berfikir betul) bahkan mereka (terburu-buru) mendustakan kebenaran apabila sahaja sampainya kepada mereka; oleh sebab itu, mereka berada dalam keadaan yang serba kacau.', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 9, NULL),
(50, 6, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَـٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٍ', 'افلم ينظروا الى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج', NULL, 'Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts?', '(Kalaulah mereka menyangka Kami tidak berkuasa mengembalikan mereka hidup semula) maka tidakkah mereka memandang ke langit yang ada di sebelah atas mereka (dengan tidak bertiang) bagaimana Kami membinanya (dengan rapi) serta Kami menghiasinya (dengan bintang-bintang), dan dengan keadaan tidak ada padanya retak-renggang? -', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 12, NULL),
(50, 7, 'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل زوج بهيج', NULL, 'And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind,', 'Dan juga (keadaan) bumi ini, (bagaimana) Kami bentangkan dia sebagai hamparan, dan Kami letakkan padanya gunung-ganang yang terdiri kukuh, serta Kami tumbuhkan padanya pelbagai jenis tanaman yang indah subur?', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 11, NULL),
(50, 8, 'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ', 'تبصرة وذكرى لكل عبد منيب', NULL, 'Giving insight and a reminder for every servant who turns [to Allāh].', '(Kami adakan semuanya itu) untuk menjadi perhatian dan peringatan, (yang menunjukkan jalan kebenaran), kepada tiap-tiap seorang hamba Allah yang mahu kembali kepadaNya (dengan taat dan berbakti).', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 5, NULL),
(50, 9, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَـٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّـٰتٍ وَحَبَّ ٱلْحَصِيدِ', 'ونزلنا من السماء ماء مباركا فانبتنا به جنات وحب الحصيد', NULL, 'And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest', 'Dan juga Kami telah menurunkan dari langit air (hujan) yang banyak faedahnya, lalu Kami tumbuhkan dengan air itu pokok-pokok tanaman (buah-buahan) dan biji-bijian yang dituai;', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 10, NULL),
(50, 10, 'وَٱلنَّخْلَ بَاسِقَـٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ', 'والنخل باسقات لها طلع نضيد', NULL, 'And lofty palm trees having fruit arranged in layers -', 'Serta pohon-pohon kurma yang tinggi menjulang, yang mengeluarkan mayang, berlapis-lapis, lagi lebat putiknya;', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 5, NULL),
(50, 11, 'رِّزْقًا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا ۚ كَذَٰلِكَ ٱلْخُرُوجُ', 'رزقا للعباد واحيينا به بلدة ميتا كذلك الخروج', NULL, 'As provision for the servants, and We have given life thereby to a dead land. Thus is the emergence [i.e., resurrection].', '(Semuanya itu) sebagai rezeki bagi hamba-hamba Kami. Dan lagi Kami telah hidupkan dengan air itu bumi yang mati; demikianlah pula keadaan keluarnya (orang-orang yang mati dari kubur setelah dibangkitkan hidup semula).', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 8, NULL),
(50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَـٰبُ ٱلرَّسِّ وَثَمُودُ', 'كذبت قبلهم قوم نوح واصحاب الرس وثمود', NULL, 'The people of Noah denied before them, and the companions of the well and Thamūd', 'Sebelum mereka (yang menentang Nabi Muhammad) itu - kaum Nabi Nuh, dan “Ashaabur-Rassi” serta Thamud (kaum Nabi Soleh), telah juga mendustakan Rasul masing-masing,', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 7, NULL),
(50, 13, 'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ', 'وعاد وفرعون واخوان لوط', NULL, 'And ʿAad and Pharaoh and the brothers [i.e., people] of Lot', 'Dan juga Aad (kaum Nabi Hud), dan Firaun, serta kaum Nabi Lut,', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 4, NULL),
(50, 14, 'وَأَصْحَـٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ ۚ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 'واصحاب الايكة وقوم تبع كل كذب الرسل فحق وعيد', NULL, 'And the companions of the thicket and the people of Tubbaʿ. All denied the messengers, so My threat was justly fulfilled.', 'Dan juga penduduk “Aikah”, serta kaum “Tubba'' ”; tiap-tiap satu kaum itu telah mendustakan Rasul-rasul (yang diutus kepadanya), lalu mereka ditimpa azab yang Aku janjikan.', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 9, NULL),
(50, 15, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ', 'افعيينا بالخلق الاول بل هم في لبس من خلق جديد', NULL, 'Did We fail in the first creation? But they are in confusion over a new creation.', '(Setelah mereka melihat dan memerhatikan makhluk-makhluk yang Kami ciptakan itu) maka adakah Kami telah lemah dengan ciptaan yang pertama itu (sehingga Kami tidak dapat mengadakannya semula? Tidak! Dan merekapun tidak mengingkari kekuasaan Kami). Bahkan mereka berada dalam keadaan keliru dan ragu-ragu tentang ciptaan makhluk-makhluk (hidup semula) dalam bentuk yang baharu.', FALSE, NULL, NULL, 518, 26, 207, 452, FALSE, 10, NULL),
(50, 16, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 'ولقد خلقنا الانسان ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد', NULL, 'And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein.', 'Dan demi sesungguhnya, Kami telah mencipta manusia dan Kami sedia mengetahui apa yang dibisikkan oleh hatinya, sedang (pengetahuan) Kami lebih dekat kepadanya daripada urat lehernya,', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 14, NULL),
(50, 17, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ', 'اذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد', NULL, 'When the two receivers [i.e., recording angels] receive, seated on the right and on the left.', 'Semasa dua malaikat (yang mengawal dan menjaganya) menerima dan menulis segala perkataan dan perbuatannya; yang satu duduk di sebelah kanannya, dan yang satu lagi di sebelah kirinya.', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 8, NULL),
(50, 18, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ', 'ما يلفظ من قول الا لديه رقيب عتيد', NULL, 'He [i.e., man] utters no word except that with him is an observer prepared [to record].', 'Tidak ada sebarang perkataan yang dilafazkannya (atau perbuatan yang dilakukannya) melainkan ada di sisinya malaikat pengawas yang sentiasa sedia (menerima dan menulisnya).', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 8, NULL),
(50, 19, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', 'وجاءت سكرة الموت بالحق ذلك ما كنت منه تحيد', NULL, 'And the intoxication of death will bring the truth; that is what you were trying to avoid.', 'Dan (apabila sampai ajal seseorang) datanglah “Sakaratulmuat” membawa kebenaran (yang telah dijanjikan, serta dikatakan kepada yang mengingkarinya sebelum itu): “Inilah perkara yang engkau selalu mengelak diri daripadanya!”', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 9, NULL),
(50, 20, 'وَنُفِخَ فِى ٱلصُّورِ ۚ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', 'ونفخ في الصور ذلك يوم الوعيد', NULL, 'And the Horn will be blown. That is the Day of [carrying out] the threat.', 'Dan lagi (apabila sampai saat yang ditentukan) ditiuplah sangkakala (untuk menghidupkan semula makhluk-makhluk yang telah mati); saat itu ialah hari berlakunya amaran yang telah diberikan.', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 6, NULL),
(50, 21, 'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ', 'وَجَاءَتْ كُلُّ نَفْسٍ مَّعَهَا سَائِقٌ وَشَهِيدٌ', NULL, 'And every soul will come, with it a driver and a witness.', 'Dan (setelah itu) datanglah tiap-tiap orang (ke Padang Mahsyar), disertai (dua malaikat: yang satu menjadi) pembawa, dan (yang satu lagi menjadi) saksi;', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 22, 'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ', 'لَّقَدْ كُنتَ فِي غَفْلَةٍ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَاءَكَ فَبَصَرُكَ الْيَوْمَ حَدِيدٌ', NULL, '[It will be said], "You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp."', '(Serta dikatakan kepadanya): “Demi sesungguhnya! Engkau di dunia dahulu berada dalam keadaan lalai tentang (perkara hari) ini, maka kami hapuskan kelalaian yang menyelubungimu itu, lalu pandanganmu pada hari ini menjadi tajam (dapat menyaksikan dengan jelasnya perkara-perkara hari akhirat)”.', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 23, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 'وَقَالَ قَرِينُهُ هَٰذَا مَا لَدَيَّ عَتِيدٌ', NULL, 'And his companion, [the angel], will say, "This [record] is what is with me, prepared."', 'Dan berkatalah malaikat yang sentiasa ada bersama-samanya: “Inilah (Kitab catitan iman dan amal) orang yang terletak dalam jagaanku, siap sedia (untuk dibicarakan)”.', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 24, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', 'أَلْقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', NULL, '[Allāh will say], "Throw into Hell every obstinate disbeliever,', '(Setelah tiap-tiap orang dibicarakan, Allah berfirman kepada kedua malaikat yang menjadi pembawa dan saksi itu): “Humbankanlah oleh kamu berdua, ke dalam neraka Jahannam tiap-tiap orang yang tetap degil dalam kekufurannya; -', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 25, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', NULL, 'Preventer of good, aggressor, and doubter,', '“Yang sering menghalangi jenis kebajikan, yang melanggar hukum ugama, lagi yang meragukan kebenaran,', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 26, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 'الَّذِي جَعَلَ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَأَلْقِيَاهُ فِي الْعَذَابِ الشَّدِيدِ', NULL, 'Who made [as equal] with Allāh another deity; then throw him into the severe punishment."', '“Yang menyembah benda yang lain bersama-sama Allah; maka humbankanlah oleh kamu berdua akan dia ke dalam azab seksa yang seberat-beratnya”.', FALSE, NULL, NULL, 519, 26, 207, 453, FALSE, 0, NULL),
(50, 27, 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍ', 'قَالَ قَرِينُهُ رَبَّنَا مَا أَطْغَيْتُهُ وَلَٰكِن كَانَ فِي ضَلَالٍ بَعِيدٍ', NULL, 'His [devil] companion will say, "Our Lord, I did not make him transgress, but he [himself] was in extreme error."', '(Semasa ia dihumbankan ke dalam neraka Jahannam, ia mendakwa bahawa Syaitanlah yang menjadikan dia sesat; pada saat itu) Syaitan yang sentiasa menyertainya (di dunia dahulu) berkata: “Wahai Tuhan kami, aku tidak menyesatkannya tetapi sememangnya dia sendiri berada di dalam kesesatan yang jauh terpesong”.', FALSE, NULL, NULL, 519, 26, 208, 453, FALSE, 0, NULL),
(50, 28, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 'قَالَ لَا تَخْتَصِمُوا لَدَيَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِالْوَعِيدِ', NULL, '[Allāh] will say, "Do not dispute before Me, while I had already presented to you the threat [i.e., warning].', 'Allah berfirman: “Janganlah kamu berbalah lagi di hadapanKu, (tidak ada gunanya berbalah pada masa Aku membuat keputusan); padahal (kamu sedia mengetahui bahawa) Aku dahulu telah memberi amaran kepada kamu (akan menyeksa orang-orang yang bersalah).', FALSE, NULL, NULL, 519, 26, 208, 453, FALSE, 0, NULL),
(50, 29, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَمَا أَنَا بِظَلَّامٍ لِّلْعَبِيدِ', NULL, 'The word [i.e., decree] will not be changed with Me, and never will I be unjust to the servants."', '“KeputusanKu itu tidak dapat diubah atau ditukar ganti, dan Aku tidak sekali-kali berlaku zalim kepada hambaKu”.', FALSE, NULL, NULL, 519, 26, 208, 453, FALSE, 0, NULL),
(50, 30, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', NULL, 'On the Day We will say to Hell, "Have you been filled?" and it will say, "Are there some more,"', '(Peringatkanlah manusia) akan hari Kami bertanya kepada neraka Jahannam: “Adakah engkau sudah penuh?” Ia menjawab: “Adakah lagi sebarang tambahan?”', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 31, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', 'وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', NULL, 'And Paradise will be brought near to the righteous, not far,', 'Dan (ingatkanlah pula hari) didekatkan Syurga bagi orang-orang yang bertaqwa, di tempat yang tidak jauh (dari mereka).', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 32, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', NULL, '[It will be said], "This is what you were promised - for every returner [to Allāh] and keeper [of His covenant].', '(Serta dikatakan kepada mereka): “Inilah yang dijanjikan kepada kamu, - kepada tiap-tiap hamba yang sentiasa kembali (kepada Allah dengan mengerjakan ibadat), lagi yang sangat memelihara dengan sebaik-baiknya (segala hukum dan peraturan Allah);', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 33, 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍ مُّنِيبٍ', 'مَّنْ خَشِيَ الرَّحْمَٰنَ بِالْغَيْبِ وَجَاءَ بِقَلْبٍ مُّنِيبٍ', NULL, 'Who feared the Most Merciful in the unseen and came with a heart returning [in repentance].', '“(Iaitu) orang yang takut (melanggar perintah Allah) Yang Maha Pemurah, semasa tidak dilihat orang dan semasa ia tidak melihat azab Allah, serta ia datang (kepada Allah) dengan hati yang tunduk taat”.', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 34, 'ٱدْخُلُوهَا بِسَلَٰمٍ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 'ادْخُلُوهَا بِسَلَامٍ ذَٰلِكَ يَوْمُ الْخُلُودِ', NULL, 'Enter it in peace. This is the Day of Eternity."', '(Mereka dipersilakan oleh malaikat dengan berkata): “Masuklah kamu ke dalam Syurga dengan selamat sejahtera; hari ini ialah hari (bermulanya) kehidupan yang kekal”.', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 35, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', 'لَهُم مَّا يَشَاءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', NULL, 'They will have whatever they wish therein, and with Us is more.', 'Mereka beroleh apa yang mereka kehendaki di situ, dan di sisi Kami ada lagi tambahan (limpah kurnia yang tidak terlintas di hati mereka).', FALSE, NULL, NULL, 519, 26, 208, 454, FALSE, 0, NULL),
(50, 36, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا فِي الْبِلَادِ هَلْ مِن مَّحِيصٍ', NULL, 'And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape?', 'Dan berapa banyak kaum-kaum (yang ingkar) yang terdahulu daripada orang-orang musyrik Makkah itu Kami telah binasakan. Kaum-kaum itu lebih kekuatannya (dan kehandalannya) daripada mereka, lalu kaum-kaum itu keluar mencari perlindungan di merata-rata negeri. (Meskipun demikian keadaannya) dapatkah (mereka) menyelamatkan diri?', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 37, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌ', 'إِنَّ فِي ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ', NULL, 'Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind].', 'Sesungguhnya (keterangan-keterangan dan peristiwa-peristiwa) yang tersebut itu, tidak syak lagi mengandungi pengajaran bagi sesiapa yang mempunyai hati (yang sedar pada masa membacanya), atau yang menggunakan pendengarannya dengan bersungguh-sungguh (kepada pengajaran itu) dengan menumpukan hati dan fikiran kepadanya.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 38, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', 'وَلَقَدْ خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', NULL, 'And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness.', 'Dan demi sesungguhnya! Kami telah menciptakan langit dan bumi serta segala yang ada di antara keduanya dalam enam masa, dan Kami tidak mengalami sebarang susah payah.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 39, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 'فَاصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ', NULL, 'So be patient, [O Muḥammad], over what they say and exalt [Allāh] with praise of your Lord before the rising of the sun and before its setting,', 'Oleh itu bersabarlah (wahai Muhammad) akan apa yang dikatakan oleh mereka (yang menentangmu itu), dan bertasbihlah sambil memuji Tuhanmu (terutama) sebelum terbit matahari dan sebelum matahari terbenam.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 40, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَأَدْبَٰرَ ٱلسُّجُودِ', 'وَمِنَ اللَّيْلِ فَسَبِّحْهُ وَأَدْبَارَ السُّجُودِ', NULL, 'And [in part] of the night exalt Him and after prostration [i.e., prayer].', 'Serta bertasbihlah kepadaNya pada malam hari dan sesudah mengerjakan sembahyang.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 41, 'وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍ قَرِيبٍ', 'وَاسْتَمِعْ يَوْمَ يُنَادِ الْمُنَادِ مِن مَّكَانٍ قَرِيبٍ', NULL, 'And listen on the Day when the Caller will call out from a place that is near -', 'Dan dengarlah (apa yang diterangkan kepadamu sekarang ini mengenai hari kiamat), hari (malaikat yang menjadi) penyeru, menyeru (makhluk-makhluk yang telah mati) dari tempat yang dekat yang dapat didengar oleh semuanya),', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 42, 'يَوْمَ يَسْمَعُونَ ٱلصَّيْحَةَ بِٱلْحَقِّ ذَٰلِكَ يَوْمُ ٱلْخُرُوجِ', 'يَوْمَ يَسْمَعُونَ الصَّيْحَةَ بِالْحَقِّ ذَٰلِكَ يَوْمُ الْخُرُوجِ', NULL, 'The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves].', 'Iaitu hari mereka mendengar pekikan seruan yang menyatakan perkara yang benar; hari seruan itu ialah hari masing-masing keluar dari kubur.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 43, 'إِنَّا نَحْنُ نُحْىِۦ وَنُمِيتُ وَإِلَيْنَا ٱلْمَصِيرُ', 'إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ وَإِلَيْنَا الْمَصِيرُ', NULL, 'Indeed, it is We who give life and cause death, and to Us is the destination', 'Sesungguhnya Kami menghidupkan dan mematikan, dan kepada Kamilah sahaja tempat kembali (sekalian makhluk).', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 44, 'يَوْمَ تَشَقَّقُ ٱلْأَرْضُ عَنْهُمْ سِرَاعًا ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ', 'يَوْمَ تَشَقَّقُ الْأَرْضُ عَنْهُمْ سِرَاعًا ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ', NULL, 'On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us.', 'Pada hari bumi terbelah-belah untuk mereka segera keluar (daripadanya). Perbuatan (menghidupkan dan) menghimpunkan mereka di Padang Mahsyar itu, mudah bagi Kami melaksanakannya.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(50, 45, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ وَمَآ أَنتَ عَلَيْهِم بِجَبَّارٍ فَذَكِّرْ بِٱلْقُرْءَانِ مَن يَخَافُ وَعِيدِ', 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ وَمَا أَنتَ عَلَيْهِم بِجَبَّارٍ فَذَكِّرْ بِالْقُرْآنِ مَن يَخَافُ وَعِيدِ', NULL, 'We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur’ān whoever fears My threat.', 'Kami lebih mengetahui apa yang mereka katakan (dari berbagai tuduhan terhadapmu wahai Muhammad), dan engkau bukanlah seorang yang berkuasa memaksa mereka (supaya masing-masing beriman). Oleh itu, berilah peringatan dengan Al-Quran ini kepada orang yang takutkan janji azabKu.', FALSE, NULL, NULL, 520, 26, 208, 454, FALSE, 0, NULL),
(51, 1, 'وَٱلذَّٰرِيَـٰتِ ذَرْوًا', 'والذاريات ذروا', NULL, 'By the [winds] scattering [dust], dispersing [it]', 'Demi angin yang menerbang dan menaburkan (debu, biji-bijian benih, dan lain-lainnya), dengan penerbangan dan penaburan yang sesungguh-sungguhnya, -', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 2, NULL),
(51, 2, 'فَٱلْحَـٰمِلَـٰتِ وِقْرًا', 'فالحاملات وقرا', NULL, 'And the [clouds] carrying a load [of water]', 'Dan awan yang membawa dan mengangkut muatannya (ke tempat yang dikehendaki), -', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 2, NULL),
(51, 3, 'فَٱلْجَـٰرِيَـٰتِ يُسْرًا', 'فالجاريات يسرا', NULL, 'And the ships sailing with ease', 'Dan kapal-kapal yang belayar laju dengan kemudahan yang diberikan kepadanya, -', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 2, NULL),
(51, 4, 'فَٱلْمُقَسِّمَـٰتِ أَمْرًا', 'فالمقسمات امرا', NULL, 'And the [angels] apportioning [each] matter,', 'Dan malaikat-malaikat yang membahagi-bahagikan segala perkara yang mereka ditugaskan membahagikannya;', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 2, NULL),
(51, 5, 'إِنَّمَا تُوعَدُونَ لَصَادِقٌ', 'انما توعدون لصادق', NULL, 'Indeed, what you are promised is true.', '(Sumpah demi sumpah) bahawa sesungguhnya segala yang dijanjikan kepada kamu (mengenai hari akhirat) tetap benar;', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 3, NULL),
(51, 6, 'وَإِنَّ ٱلدِّينَ لَوَٰقِعٌ', 'وان الدين لواقع', NULL, 'And indeed, the recompense is to occur.', 'Dan bahawa sesungguhnya balasan amal, tetap berlaku.', FALSE, NULL, NULL, 520, 26, 208, 455, FALSE, 3, NULL),
(51, 7, 'وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ', 'والسماء ذات الحبك', NULL, 'By the heaven containing pathways,', 'Demi langit yang mempunyai jalan-jalan yang berbagai bentuk keadaannya,', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 3, NULL),
(51, 8, 'إِنَّكُمْ لَفِى قَوْلٍ مُّخْتَلِفٍ', 'انكم لفي قول مختلف', NULL, 'Indeed, you are in differing speech.', 'Sesungguhnya kamu berada dalam keadaan berlainan pendapat (mengenai ugama yang dibawa oleh Nabi Muhammad, s.a.w).', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 4, NULL),
(51, 9, 'يُؤْفَكُ عَنْهُ مَنْ أُفِكَ', 'يؤفك عنه من افك', NULL, 'Deluded away from it [i.e., the Qur’ān] is he who is deluded.', 'Dipalingkan daripada (perselisihan) itu orang-orang yang telah dipalingkan Allah (dengan sebab keikhlasannya mencari kebenaran).', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 4, NULL),
(51, 10, 'قُتِلَ ٱلْخَرَّٰصُونَ', 'قتل الخراصون', NULL, 'Destroyed are the misinformers', 'Binasalah orang-orang yang sentiasa mengeluarkan pendapat dengan cara agak-agak sahaja,', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 2, NULL),
(51, 11, 'ٱلَّذِينَ هُمْ فِى غَمْرَةٍ سَاهُونَ', 'الذين هم في غمرة ساهون', NULL, 'Who are within a flood [of confusion] and heedless.', '(Iaitu) orang-orang yang tenggelam dalam kejahilan, serta lalaikan (hari pembalasan).', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 5, NULL),
(51, 12, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ', 'يسالون ايان يوم الدين', NULL, 'They ask, "When is the Day of Recompense?"', 'Mereka bertanya (secara mengejek): “Bilakah datangnya hari pembalasan itu?”', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 4, NULL),
(51, 13, 'يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ', 'يوم هم على النار يفتنون', NULL, '[It is] the Day they will be tormented over the Fire', '(Jawabnya: hari itu ialah) hari mereka diseksa (dengan dibakar) atas api neraka, -', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 5, NULL),
(51, 14, 'ذُوقُوا۟ فِتْنَتَكُمْ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'ذوقوا فتنتكم هذا الذي كنتم به تستعجلون', NULL, '[And will be told], "Taste your torment. This is that for which you were impatient."', '(Sambil dikatakan kepada mereka): “Rasalah azab seksa yang disediakan untuk kamu; inilah dia yang dahulu kamu minta disegerakan kedatangannya”.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 7, NULL),
(51, 15, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَعُيُونٍ', 'ان المتقين في جنات وعيون', NULL, 'Indeed, the righteous will be among gardens and springs,', 'Sesungguhnya orang-orang yang bertaqwa adalah ditempatkan di dalam beberapa taman Syurga, dengan mata air-mata air terpancar padanya.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 5, NULL),
(51, 16, 'ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ', 'اخذين ما اتاهم ربهم انهم كانوا قبل ذلك محسنين', NULL, 'Accepting what their Lord has given them. Indeed, they were before that doers of good.', '(Keadaan mereka di sana) sentiasa menerima nikmat dan rahmat yang diberikan kepadanya oleh Tuhan mereka. Sesungguhnya mereka di dunia dahulu adalah orang-orang yang berbuat kebaikan.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 9, NULL),
(51, 17, 'كَانُوا۟ قَلِيلًا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ', 'كانوا قليلا من الليل ما يهجعون', NULL, 'They used to sleep but little of the night,', 'Mereka sentiasa mengambil sedikit sahaja: masa dari waktu malam, untuk mereka tidur.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 6, NULL),
(51, 18, 'وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ', 'وبالاسحار هم يستغفرون', NULL, 'And in the hours before dawn they would ask forgiveness,', 'Dan pada waktu akhir malam (sebelum fajar) pula, mereka selalu beristighfar kepada Allah (memohon ampun).', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 3, NULL),
(51, 19, 'وَفِىٓ أَمْوَٰلِهِمْ حَقٌّ لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'وفي اموالهم حق للسائل والمحروم', NULL, 'And from their properties was [given] the right of the [needy] petitioner and the deprived.', 'Dan pada harta-harta mereka, (ada pula bahagian yang mereka tentukan menjadi) hak untuk orang miskin yang meminta dan orang miskin yang menahan diri (daripada meminta).', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 5, NULL),
(51, 20, 'وَفِى ٱلْأَرْضِ ءَايَـٰتٌ لِّلْمُوقِنِينَ', 'وفي الارض ايات للموقنين', NULL, 'And on the earth are signs for the certain [in faith]', 'Dan pada bumi ada tanda-tanda (yang membuktikan keesaan dan kekuasaan Allah) bagi orang-orang (yang mahu mencapai pengetahuan) yang yakin,', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 4, NULL),
(51, 21, 'وَفِىٓ أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ', 'وَفِي أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ', NULL, 'And in yourselves. Then will you not see?', 'Dan juga pada diri kamu sendiri. Maka mengapa kamu tidak mahu melihat serta memikirkan (dalil-dalil dan bukti itu)?', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 0, NULL),
(51, 22, 'وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', 'وَفِي السَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', NULL, 'And in the heaven is your provision and whatever you are promised.', 'Dan di langit pula terdapat (sebab-sebab) rezeki kamu, dan juga terdapat apa yang telah (ditakdirkan dan) dijanjikan kepada kamu.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 0, NULL),
(51, 23, 'فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ', 'فَوَرَبِّ السَّمَاءِ وَالْأَرْضِ إِنَّهُ لَحَقٌّ مِّثْلَ مَا أَنَّكُمْ تَنطِقُونَ', NULL, 'Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking.', 'Maka demi Tuhan langit dan bumi, sesungguhnya (apa yang tersebut) itu tetap benar, (tidak patut diragu-ragukan) sebagaimana (tidak sepatutnya diragukan) benarnya kamu dapat berkata-kata.', FALSE, NULL, NULL, 521, 26, 208, 455, FALSE, 0, NULL),
(51, 24, 'هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ', 'هَلْ أَتَاكَ حَدِيثُ ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ', NULL, 'Has there reached you the story of the honored guests of Abraham? -', 'Sudahkah sampai kepadamu (wahai Muhammad) perihal tetamu Nabi Ibrahim yang dimuliakan?', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 25, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ قَوْمٌ مُّنكَرُونَ', 'إِذْ دَخَلُوا عَلَيْهِ فَقَالُوا سَلَامًا قَالَ سَلَامٌ قَوْمٌ مُّنكَرُونَ', NULL, 'When they entered upon him and said, "[We greet you with] peace." He answered, "[And upon you] peace; [you are] a people unknown."', 'Ketika mereka masuk mendapatkannya lalu memberi salam dengan berkata: “Salam sejahtera kepadamu!” Ia menjawab: Salam sejahtera kepada kamu! “(Sambil berkata dalam hati): mereka ini orang-orang yang tidak dikenal.', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 26, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍ سَمِينٍ', 'فَرَاغَ إِلَىٰ أَهْلِهِ فَجَاءَ بِعِجْلٍ سَمِينٍ', NULL, 'Then he went to his family and came with a fat [roasted] calf.', 'Kemudian ia masuk mendapatkan Ahli rumahnya serta dibawanya keluar seekor anak lembu gemuk (yang dipanggang).', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 27, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', 'فَقَرَّبَهُ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', NULL, 'And placed it near them; he said, "Will you not eat?"', 'Lalu dihidangkannya kepada mereka sambil berkata: “Silalah makan”.', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 28, 'فَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍ', 'فَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا لَا تَخَفْ وَبَشَّرُوهُ بِغُلَامٍ عَلِيمٍ', NULL, 'And he felt from them apprehension. They said, "Fear not," and gave him good tidings of a learned boy.', '(Setelah dilihatnya mereka mereka tidak menjamah makanan itu), maka ia merasa takut dari keadaan mereka. (Melihat kecemasannya), mereka berkata: “Janganlah engkau takut (wahai Ibrahim)”. Lalu mereka memberikan berita gembira kepadanya, bahawa ia akan beroleh seorang anak yang berpengetahuan.', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 29, 'فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌ', 'فَأَقْبَلَتِ امْرَأَتُهُ فِي صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌ', NULL, 'And his wife approached with a cry [of alarm] and struck her face and said, "[I am] a barren old woman!"', '(Mendengarkan berita yang mengembirakan itu), maka datanglah isterinya sambil menjerit (kehairanan) lalu menepuk mukanya sambil berkata: “Aku sudah tua, lagi mandul, (bagaimana aku boleh mendapat anak)?”', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 30, 'قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'قَالُوا كَذَٰلِكِ قَالَ رَبُّكِ إِنَّهُ هُوَ الْحَكِيمُ الْعَلِيمُ', NULL, 'They said, "Thus has said your Lord; indeed, He is the Wise, the Knowing."', 'Mereka berkata: “Demikianlah Tuhanmu berfirman, (kami hanya menyampaikan sahaja); Sesungguhnya Dia lah Yang Maha Bijaksana, lagi Maha Mengetahui”.', FALSE, NULL, NULL, 521, 26, 208, 456, FALSE, 0, NULL),
(51, 31, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا الْمُرْسَلُونَ', NULL, '[Abraham] said, "Then what is your business [here], O messengers?"', 'Nabi Ibrahim bertanya: “(Selain dari itu) apa lagi tugas penting kamu wahai utusan Tuhan?”', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 32, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', 'قَالُوا إِنَّا أُرْسِلْنَا إِلَىٰ قَوْمٍ مُّجْرِمِينَ', NULL, 'They said, "Indeed, we have been sent to a people of criminals', 'Mereka menjawab: “Sesungguhnya Kami diutus kepada suatu kaum yang berdosa (untuk membinasakan mereka);', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 33, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةً مِّن طِينٍ', 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةً مِّن طِينٍ', NULL, 'To send down upon them stones of clay,', '“Supaya Kami menimpakan mereka dengan batu-batu dari tanah (yang dibakar),', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 34, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', NULL, 'Marked in the presence of your Lord for the transgressors."', '“Batu-batu itu ditandakan di sisi Tuhanmu, untuk membinasakan orang-orang yang melampaui batas (dalam keingkarannya)”.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 35, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ', 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ الْمُؤْمِنِينَ', NULL, 'So We brought out whoever was in them [i.e., the cities] of the believers.', '(Setelah sampai utusan Kami ke tempat itu), Kami (perintahkan mereka) mengeluarkan orang-orang yang beriman yang tinggal di situ.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 36, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍ مِّنَ ٱلْمُسْلِمِينَ', 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍ مِّنَ الْمُسْلِمِينَ', NULL, 'And We found not within them other than a [single] house of Muslims.', '(Sesudah dipereksa) maka (utusan) Kami tidak mendapati di situ melainkan sebuah rumah sahaja yang ada penduduknya dari orang-orang Islam (yang beriman kepada Nabi Lut).', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 37, 'وَتَرَكْنَا فِيهَآ ءَايَةً لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ', 'وَتَرَكْنَا فِيهَا آيَةً لِّلَّذِينَ يَخَافُونَ الْعَذَابَ الْأَلِيمَ', NULL, 'And We left therein a sign for those who fear the painful punishment.', 'Dan Kami tinggalkan di negeri itu (timbunan batu-batu yang telah menghujani dan membinasakan mereka), sebagai tanda (yang mendatangkan keinsafan) bagi orang-orang yang sedia takut kepada azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 38, 'وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍ مُّبِينٍ', 'وَفِي مُوسَىٰ إِذْ أَرْسَلْنَاهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَانٍ مُّبِينٍ', NULL, 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.', 'Dan juga pada (kisah) Nabi Musa (terdapat dalil-dalil yang memberi keinsafan), - ketika kami mengutusnya kepada Firaun dengan membawa mukjizat yang nyata.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 39, 'فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌ', 'فَتَوَلَّىٰ بِرُكْنِهِ وَقَالَ سَاحِرٌ أَوْ مَجْنُونٌ', NULL, 'But he turned away with his supporters and said, "A magician or a madman."', 'Maka Firaun berpaling ingkar dengan berdasarkan kekuasaannya sambil berkata: “(Musa itu) adalah seorang ahli sihir, atau seorang gila!”', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌ', 'فَأَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّ وَهُوَ مُلِيمٌ', NULL, 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.', 'Lalu Kami (adakan jalan) mengambil Firaun bersama-sama tenteranya, kemudian Kami humbankan mereka ke dalam laut, sedang ia berkeadaan tercela.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 41, 'وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ', 'وَفِي عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ الرِّيحَ الْعَقِيمَ', NULL, 'And in ʿAad [was a sign], when We sent against them the barren wind.', 'Dan juga pada (kisah) kaum Aad (terdapat perkara-perkara yang menjadi iktibar), - ketika kami hantarkan kepada mereka angin ribut yang tidak mengandungi sebarang kebaikan; -', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 42, 'مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ', 'مَا تَذَرُ مِن شَيْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَالرَّمِيمِ', NULL, 'It left nothing of what it came upon but that it made it like disintegrated ruins.', 'Angin itu tidak meninggalkan sesuatupun yang dirempuhnya, melainkan menjadikannya (hancur) seperti debu.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 43, 'وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍ', 'وَفِي ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا حَتَّىٰ حِينٍ', NULL, 'And in Thamūd, when it was said to them, "Enjoy yourselves for a time."', 'Dan juga pada (kisah) kaum Thamud (terdapat perkara-perkara yang menjadi pelajaran) - ketika dikatakan kepada mereka: “Bersenang-senanglah kamu hingga ke suatu waktu (yang termaklum)!”', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 44, 'فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ', 'فَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ الصَّاعِقَةُ وَهُمْ يَنظُرُونَ', NULL, 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.', 'Maka mereka membesarkan diri terhadap perintah Tuhannya, lalu mereka disambar petir (dengan tidak dapat melarikan diri), sedang mereka melihatnya.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 45, 'فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍ وَمَا كَانُوا۟ مُنتَصِرِينَ', 'فَمَا اسْتَطَاعُوا مِن قِيَامٍ وَمَا كَانُوا مُنتَصِرِينَ', NULL, 'And they were unable to arise, nor could they defend themselves.', 'Dengan yang demikian, mereka tidak dapat bangun lagi, dan mereka juga tidak mendapat pertolongan.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 46, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا قَوْمًا فَاسِقِينَ', NULL, 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.', 'Dan kaum Nuh (Kami juga telah binasakan) sebelum itu; sesungguhnya mereka adalah kaum yang fasik - derhaka.', FALSE, NULL, NULL, 522, 27, 209, 456, FALSE, 0, NULL),
(51, 47, 'وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍ وَإِنَّا لَمُوسِعُونَ', 'وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ', NULL, 'And the heaven We constructed with strength, and indeed, We are [its] expander.', 'Dan langit itu Kami dirikan dengan kekuasaan Kami (dalam bentuk binaan yang kukuh rapi). Dan sesungguhnya Kami adalah mempunyai kekuasaan yang luas tidak terhingga.', FALSE, NULL, NULL, 522, 27, 209, 457, FALSE, 0, NULL),
(51, 48, 'وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ', 'وَالْأَرْضَ فَرَشْنَاهَا فَنِعْمَ الْمَاهِدُونَ', NULL, 'And the earth We have spread out, and excellent is the preparer.', 'Dan bumi pula Kami hamparkan (untuk kemudahan kamu mendiaminya); maka Kamilah sebaik-baik yang menghamparkannya.', FALSE, NULL, NULL, 522, 27, 209, 457, FALSE, 0, NULL),
(51, 49, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', 'وَمِن كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', NULL, 'And of all things We created two mates [i.e., counterparts]; perhaps you will remember.', 'Dan tiap-tiap jenis Kami ciptakan berpasangan, supaya kamu mengingati (kekuasaan Kami dan mentauhidkan Kami).', FALSE, NULL, NULL, 522, 27, 209, 457, FALSE, 0, NULL),
(51, 50, 'فَفِرُّوٓا۟ إِلَى ٱللَّهِ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', 'فَفِرُّوا إِلَى اللَّهِ إِنِّي لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', NULL, 'So flee to Allāh. Indeed, I am to you from Him a clear warner.', '(Katakanlah wahai Muhammad kepada mereka): “Maka segeralah kamu kembali kepada Allah (dengan bertaubat dan taat), sesungguhnya aku diutuskan Allah kepada kamu, sebagai pemberi amaran yang nyata.', FALSE, NULL, NULL, 522, 27, 209, 457, FALSE, 0, NULL),
(51, 51, 'وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', 'وَلَا تَجْعَلُوا مَعَ اللَّهِ إِلَٰهًا آخَرَ إِنِّي لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', NULL, 'And do not make [as equal] with Allāh another deity. Indeed, I am to you from Him a clear warner.', '“Dan janganlah kamu adakan tuhan yang lain bersama Allah (dalam kepercayaan kamu), sesungguhnya aku diutus oleh Allah kepada kamu sebagai pemberi amaran yang nyata”.', FALSE, NULL, NULL, 522, 27, 209, 457, FALSE, 0, NULL),
(51, 52, 'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ', 'كَذَٰلِكَ مَا أَتَى الَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا سَاحِرٌ أَوْ مَجْنُونٌ', NULL, 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."', 'Demikianlah (keadaan tiap-tiap kaum terhadap Rasulnya samalah seperti keadaan kaummu wahai Muhammad) - tidak ada seorang Rasul pun yang datang kepada kaum-kaum yang terdahulu dari mereka, melainkan ada yang berkata: “Dia adalah seorang ahli sihir, atau seorang gila”.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 53, 'أَتَوَاصَوْا۟ بِهِۦ بَلْ هُمْ قَوْمٌ طَاغُونَ', 'أَتَوَاصَوْا بِهِ بَلْ هُمْ قَوْمٌ طَاغُونَ', NULL, 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.', 'Adakah mereka semua telah berpesan-pesan (dan mencapai kata sepakat) untuk melemparkan tuduhan itu? (Sudah tentu mereka tidak dapat berbuat demikian), bahkan mereka semuanya adalah kaum yang melampaui batas (dalam keingkarannya).', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 54, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍ', 'فَتَوَلَّ عَنْهُمْ فَمَا أَنتَ بِمَلُومٍ', NULL, 'So leave them, [O Muḥammad], for you are not to be blamed.', 'Oleh itu, berpalinglah (wahai Muhammad) daripada mereka (yang menentangmu itu dan janganlah dihiraukan), kerana engkau tidak akan disalahkan (setelah engkau memberi amaran kepada mereka).', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 55, 'وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ', 'وَذَكِّرْ فَإِنَّ الذِّكْرَىٰ تَنفَعُ الْمُؤْمِنِينَ', NULL, 'And remind, for indeed, the reminder benefits the believers.', 'Dan tetap tekunlah engkau memberi peringatan, kerana sesungguhnya peringatan itu mendatangkan faedah kepada orang-orang yang beriman.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 56, 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ', NULL, 'And I did not create the jinn and mankind except to worship Me.', 'Dan (ingatlah) Aku tidak menciptakan jin dan manusia melainkan untuk mereka menyembah dan beribadat kepadaKu.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 57, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍ وَمَآ أُرِيدُ أَن يُطْعِمُونِ', 'مَا أُرِيدُ مِنْهُم مِّن رِّزْقٍ وَمَا أُرِيدُ أَن يُطْعِمُونِ', NULL, 'I do not want from them any provision, nor do I want them to feed Me.', 'Aku tidak sekali-kali menghendaki sebarang rezeki pemberian dari mereka, dan Aku tidak menghendaki supaya mereka memberi makan kepadaKu.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 58, 'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ', 'إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ', NULL, 'Indeed, it is Allāh who is the [continual] Provider, the firm possessor of strength.', 'Sesungguhnya Allah Dia lah sahaja Yang Memberi rezeki (kepada sekalian makhlukNya, dan Dia lah sahaja) Yang Mempunyai Kekuasaan yang tidak terhingga, lagi Yang Maha Kuat Kukuh kekuasaanNya.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 59, 'فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ', 'فَإِنَّ لِلَّذِينَ ظَلَمُوا ذَنُوبًا مِّثْلَ ذَنُوبِ أَصْحَابِهِمْ فَلَا يَسْتَعْجِلُونِ', NULL, 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their companions [i.e., predecessors], so let them not impatiently urge Me.', '(Setelah ternyata hakikat yang demikian), maka sesungguhnya bagi orang-orang yang zalim (yang menentang ajaran Nabi Muhammad) itu ada bahagiannya (dari azab seksa) seperti bahagian rakan-rakan mereka (kaum kafir yang telah lalu). Oleh itu, janganlah mereka meminta kepadaKu menyegerakan kedatangannya.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(51, 60, 'فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ', 'فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِن يَوْمِهِمُ الَّذِي يُوعَدُونَ', NULL, 'And woe to those who have disbelieved from their Day which they are promised.', 'Maka kecelakaan dan kebinasaanlah bagi orang-orang yang kafir pada hari yang telah dijanjikan kepada mereka.', FALSE, NULL, NULL, 523, 27, 209, 457, FALSE, 0, NULL),
(52, 1, 'وَٱلطُّورِ', 'والطور', NULL, 'By the mount', 'Demi Gunung Tursina;', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 1, NULL),
(52, 2, 'وَكِتَـٰبٍ مَّسْطُورٍ', 'وكتاب مسطور', NULL, 'And [by] a Book inscribed', 'Dan demi Kitab yang tertulis dengan rapi -', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 2, NULL),
(52, 3, 'فِى رَقٍّ مَّنشُورٍ', 'في رق منشور', NULL, 'In parchment spread open', 'Pada lembaran surat yang terbuka;', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 3, NULL),
(52, 4, 'وَٱلْبَيْتِ ٱلْمَعْمُورِ', 'والبيت المعمور', NULL, 'And [by] the frequented House', 'Dan demi “Al-Baitul Makmur”;', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 2, NULL),
(52, 5, 'وَٱلسَّقْفِ ٱلْمَرْفُوعِ', 'والسقف المرفوع', NULL, 'And [by] the ceiling [i.e., heaven] raised high', 'Dan demi bumbung yang tinggi;', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 2, NULL),
(52, 6, 'وَٱلْبَحْرِ ٱلْمَسْجُورِ', 'والبحر المسجور', NULL, 'And [by] the sea set on fire,', 'Dan demi laut yang penuh tepu (dengan kepanasan); -', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 2, NULL),
(52, 7, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌ', 'ان عذاب ربك لواقع', NULL, 'Indeed, the punishment of your Lord will occur.', 'Sesungguhnya azab Tuhanmu tetap berlaku; -', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 4, NULL),
(52, 8, 'مَّا لَهُۥ مِن دَافِعٍ', 'ما له من دافع', NULL, 'Of it there is no preventer.', 'Tidak ada sesiapapun yang dapat menolaknya; -', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 4, NULL),
(52, 9, 'يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًا', 'يوم تمور السماء مورا', NULL, 'On the Day the heaven will sway with circular motion', 'Pada hari langit (dan segala isinya) bergegar dengan sekuat-kuatnya.', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 4, NULL),
(52, 10, 'وَتَسِيرُ ٱلْجِبَالُ سَيْرًا', 'وتسير الجبال سيرا', NULL, 'And the mountains will pass on, departing -', 'Dan gunung-ganang bergerak dari tempatnya dengan cara yang luar biasa.', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 3, NULL),
(52, 11, 'فَوَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'فويل يومئذ للمكذبين', NULL, 'Then woe, that Day, to the deniers,', '(Apabila berlaku yang demikian), maka kecelakaan dan kebinasaanlah pada hari itu bagi orang-orang yang mendustakan kebenaran;', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 3, NULL),
(52, 12, 'ٱلَّذِينَ هُمْ فِى خَوْضٍ يَلْعَبُونَ', 'الذين هم في خوض يلعبون', NULL, 'Who are in [empty] discourse amusing themselves.', 'Iaitu orang-orang yang leka bermain-main dalam kesesatan.', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 5, NULL),
(52, 13, 'يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', 'يوم يدعون الى نار جهنم دعا', NULL, 'The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say],', 'Pada hari mereka ditolak ke alam neraka Jahannam dengan penolakan yang sekasar-kasarnya,', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 6, NULL),
(52, 14, 'هَـٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'هذه النار التي كنتم بها تكذبون', NULL, '"This is the Fire which you used to deny.', '(Dan dikatakan kepada mereka): “Inilah api neraka yang dahulu kamu mendustakannya.', FALSE, NULL, NULL, 523, 27, 209, 458, FALSE, 6, NULL),
(52, 15, 'أَفَسِحْرٌ هَـٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ', 'افسحر هذا ام انتم لا تبصرون', NULL, 'Then is this magic, or do you not see?', '“Maka adakah ini sihir juga (sebagaimana yang kamu katakan terhadap keterangan Rasul Kami dahulu?), atau kamu tidak nampak (kenyataannya sebagaimana kamu tidak nampak di dunia dahulu akan kebenaran Rasul Kami)?', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 6, NULL),
(52, 16, 'ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'اصلوها فاصبروا او لا تصبروا سواء عليكم انما تجزون ما كنتم تعملون', NULL, '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."', '“Rasalah bakarannya; kemudian sama ada kamu bersabar (menderita azabnya) atau tidak bersabar, sama sahaja (tidak ada faedahnya) kepada kamu, kerana kamu tidak dibalas melainkan dengan apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 12, NULL),
(52, 17, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَنَعِيمٍ', 'ان المتقين في جنات ونعيم', NULL, 'Indeed, the righteous will be in gardens and pleasure,', 'Sesungguhnya orang-orang yang bertaqwa, di tempatkan dalam taman-taman Syurga dan nikmat kesenangan (yang tidak ada taranya).', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 5, NULL),
(52, 18, 'فَـٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ', 'فاكهين بما اتاهم ربهم ووقاهم ربهم عذاب الجحيم', NULL, 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.', 'Mereka bersenang lenang dengan apa yang dikurniakan oleh Tuhan mereka, dan mereka dipelihara Tuhan dari azab neraka.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 8, NULL),
(52, 19, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'كلوا واشربوا هنيئا بما كنتم تعملون', NULL, '[They will be told], "Eat and drink in satisfaction for what you used to do."', '(Dan dikatakan kepada mereka): “Makan dan minumlah kamu makanan dan minuman yang lazat serta baik kesudahannya, dengan sebab apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 6, NULL),
(52, 20, 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٍ مَّصْفُوفَةٍ ۖ وَزَوَّجْنَـٰهُم بِحُورٍ عِينٍ', 'متكئين على سرر مصفوفة وزوجناهم بحور عين', NULL, 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.', 'Mereka duduk berbaring di atas pelamin-pelamin yang berderet; dan Kami jadikan kawan teman mereka bidadari-bidadari yang putih melepak, lagi luas cantik matanya.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 7, NULL),
(52, 21, 'وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌ', 'وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُم مِّنْ عَمَلِهِم مِّن شَيْءٍ كُلُّ امْرِئٍ بِمَا كَسَبَ رَهِينٌ', NULL, 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.', 'Dan orang-orang yang beriman yang diturut oleh zuriat keturunannya dengan keadaan beriman, Kami hubungkan (himpunkan) zuriat keturunannya itu dengan mereka (di dalam Syurga); dan Kami (dengan itu) tidak mengurangi sedikitpun dari pahala amal-amal mereka; tiap-tiap seorang manusia terikat dengan amal yang dikerjakannya.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 0, NULL),
(52, 22, 'وَأَمْدَدْنَٰهُم بِفَٰكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ', 'وَأَمْدَدْنَاهُم بِفَاكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ', NULL, 'And We will provide them with fruit and meat from whatever they desire.', 'Dan (penduduk Syurga itu) Kami tambahi mereka (dari semasa ke semasa), dengan buah-buahan dan daging dari berbagai jenis yang mereka ingini.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 0, NULL),
(52, 23, 'يَتَنَٰزَعُونَ فِيهَا كَأْسًا لَّا لَغْوٌ فِيهَا وَلَا تَأْثِيمٌ', 'يَتَنَازَعُونَ فِيهَا كَأْسًا لَّا لَغْوٌ فِيهَا وَلَا تَأْثِيمٌ', NULL, 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.', 'Mereka di dalam Syurga itu (kerana melahirkan kemesraan antara satu dengan yang lain): berebut-rebut mengambil piala yang berisi arak yang tidak menyebabkan timbul (dari peminumnya) perkara yang sia-sia dan tidak pula menyebabkan (peminumnya menanggung) dosa.', FALSE, NULL, NULL, 524, 27, 209, 458, FALSE, 0, NULL),
(52, 24, 'وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ', 'وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ', NULL, 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.', 'Dan mereka dilayani oleh anak-anak muda lelaki yang sentiasa beredar di sekitar mereka, (yang cantik parasnya) seolah-olah anak-anak muda itu mutiara yang tersimpan dengan sebaik-baiknya.', FALSE, NULL, NULL, 524, 27, 210, 458, FALSE, 0, NULL),
(52, 25, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَاءَلُونَ', NULL, 'And they will approach one another, inquiring of each other.', 'Dan (dengan berada dalam nikmat itu) mereka berhadap-hadapan satu sama lain sambil bertanya-tanya.', FALSE, NULL, NULL, 524, 27, 210, 458, FALSE, 0, NULL),
(52, 26, 'قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ', 'قَالُوا إِنَّا كُنَّا قَبْلُ فِي أَهْلِنَا مُشْفِقِينَ', NULL, 'They will say, "Indeed, we were previously among our people fearful [of displeasing Allāh].', 'Mereka berkata: “Sesungguhnya kami dahulu, semasa berada dalam kalangan keluarga kami - selalu merasa cemas takut (daripada berlaku derhaka kepada Allah),', FALSE, NULL, NULL, 524, 27, 210, 458, FALSE, 0, NULL),
(52, 27, 'فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', 'فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ', NULL, 'So Allāh conferred favor upon us and protected us from the punishment of the Scorching Fire.', '“Maka Allah mengurniakan kami (rahmat dan taufiqNya), serta memelihara kami dari azab neraka.', FALSE, NULL, NULL, 524, 27, 210, 458, FALSE, 0, NULL),
(52, 28, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ', 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ', NULL, 'Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful."', '“Sesungguhnya kami dahulu tetap menyembahNya (dan memohon pertolonganNya). Kerana sesungguhnya Dia lah sahaja yang sentiasa melimpahkan ihsanNya, lagi Yang Maha Mengasihani”.', FALSE, NULL, NULL, 524, 27, 210, 458, FALSE, 0, NULL),
(52, 29, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ', 'فَذَكِّرْ فَمَا أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ', NULL, 'So remind, [O Muḥammad], for you are not, by the favor of your Lord, a soothsayer or a madman.', 'Maka hendaklah engkau (wahai Muhammad) tetap tekun memberi peringatan (dengan ajaran-ajaran Al-Quran yang diturunkan kepadamu, dan janganlah dihiraukan golongan yang ingkar), kerana engkau dengan nikmat Tuhanmu (yang dilimpahkanNya kepadamu itu) bukanlah seorang pawang dan bukan pula seorang gila.', FALSE, NULL, NULL, 524, 27, 210, 459, FALSE, 0, NULL),
(52, 30, 'أَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ', 'أَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِ رَيْبَ الْمَنُونِ', NULL, 'Or do they say [of you], "A poet for whom we await a misfortune of time"?', '(Mereka menuduh Nabi Muhammad dengan yang bukan-bukan), bahkan mereka mengatakan: “(Muhammad) itu seorang penyair yang kami tunggu-tunggu saat kebinasaannya”.', FALSE, NULL, NULL, 524, 27, 210, 459, FALSE, 0, NULL),
(52, 31, 'قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ', 'قُلْ تَرَبَّصُوا فَإِنِّي مَعَكُم مِّنَ الْمُتَرَبِّصِينَ', NULL, 'Say, "Wait, for indeed I am, with you, among the waiters."', 'Katakanlah (wahai Muhammad): “Tunggulah kamu (akan apa yang kamu tuduh itu), maka sesungguhnya aku juga dari orang-orang yang menunggu bersama-sama kamu (akan apa yang dijanjikan oleh Allah Taala)”.', FALSE, NULL, NULL, 524, 27, 210, 459, FALSE, 0, NULL),
(52, 32, 'أَمْ تَأْمُرُهُمْ أَحْلَٰمُهُم بِهَٰذَآ أَمْ هُمْ قَوْمٌ طَاغُونَ', 'أَمْ تَأْمُرُهُمْ أَحْلَامُهُم بِهَٰذَا أَمْ هُمْ قَوْمٌ طَاغُونَ', NULL, 'Or do their minds command them to [say] this, or are they a transgressing people?', 'Adakah mereka disuruh oleh akal fikiran mereka melemparkan tuduhan-tuduhan yang sedemikian itu, atau sememangnya mereka suatu kaum yang melampaui batas (dalam keingkaran dan kedegilannya)?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 33, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ بَل لَّا يُؤْمِنُونَ', 'أَمْ يَقُولُونَ تَقَوَّلَهُ بَل لَّا يُؤْمِنُونَ', NULL, 'Or do they say, "He has made it up"? Rather, they do not believe.', '(Bukan sahaja mereka ingkar dan degil) bahkan mereka berkata: “Dia (Muhammad) telah mereka-reka Al-Quran itu”. (Tuduhan mereka yang demikian tidak berasas) bahkan mereka sengaja tidak mahu beriman!', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 34, 'فَلْيَأْتُوا۟ بِحَدِيثٍ مِّثْلِهِۦٓ إِن كَانُوا۟ صَٰدِقِينَ', 'فَلْيَأْتُوا بِحَدِيثٍ مِّثْلِهِ إِن كَانُوا صَادِقِينَ', NULL, 'Then let them produce a statement like it, if they should be truthful.', '(Kalau tidak) maka hendaklah mereka membuat dan mendatangkan kata-kata (yang fasih dan indah) seperti Al-Quran itu, jika betul mereka orang-orang yang benar dakwaannya.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 35, 'أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ', 'أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخَالِقُونَ', NULL, 'Or were they created by nothing, or were they the creators [of themselves]?', '(Mengapa mereka tidak beriman?) Adakah mereka telah tercipta dengan tiada yang menciptanya, atau adakah mereka yang mencipta diri mereka sendiri?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 36, 'أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بَل لَّا يُوقِنُونَ', 'أَمْ خَلَقُوا السَّمَاوَاتِ وَالْأَرْضَ بَل لَّا يُوقِنُونَ', NULL, 'Or did they create the heavens and the earth? Rather, they are not certain.', 'Adakah mereka yang mencipta langit dan bumi itu? (Sudah tentu tidak!) Bahkan mereka adalah orang-orang yang tidak meyakini (kebenaran apa yang mereka pernah mengakuinya).', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 37, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ', 'أَمْ عِندَهُمْ خَزَائِنُ رَبِّكَ أَمْ هُمُ الْمُصَيْطِرُونَ', NULL, 'Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]?', 'Adakah pada tangan mereka perbendaharaan Tuhanmu (sehingga mereka boleh memberi atau menahan sesuatu nikmat atau pangkat), atau merekalah yang berkuasa mentadbirkan segala-galanya?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 38, 'أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَٰنٍ مُّبِينٍ', 'أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَانٍ مُّبِينٍ', NULL, 'Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority [i.e., proof].', 'Adakah mereka mempunyai tangga (untuk naik ke langit), yang dengannya mereka dapat mendengar (apa yang diperintahkan dan ditetapkan oleh Allah? Jika ada) maka biarlah orang mereka yang mendengar itu membawa sesuatu bukti yang menyatakan kebenarannya.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 39, 'أَمْ لَهُ ٱلْبَنَٰتُ وَلَكُمُ ٱلْبَنُونَ', 'أَمْ لَهُ الْبَنَاتُ وَلَكُمُ الْبَنُونَ', NULL, 'Or has He daughters while you have sons?', 'Adilkah (kamu sediakan) bagi Allah - anak-anak perempuan (yang kamu benci), dan untuk kamu - anak-anak lelaki (yang kamu sukai)?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 40, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', 'أَمْ تَسْأَلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', NULL, 'Or do you, [O Muḥammad], ask of them a payment, so they are by debt burdened down?', 'Pernahkah engkau (wahai Muhammad) meminta sebarang bayaran kepada mereka (mengenai ajaran Islam yang engkau sampaikan), lalu mereka merasa berat menanggung bayaran itu (sehingga menjauhkan diri daripada menyahut seruanmu)?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 41, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'أَمْ عِندَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ', NULL, 'Or have they [knowledge of] the unseen, so they write [it] down?', 'Adakah pada sisi mereka (Lauh Mahfuz yang mengandungi) perkara-perkara yang ghaib, lalu mereka menyalin (daripadanya untuk menentang ajaran dan peringatanmu)?', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 42, 'أَمْ يُرِيدُونَ كَيْدًا فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ', 'أَمْ يُرِيدُونَ كَيْدًا فَالَّذِينَ كَفَرُوا هُمُ الْمَكِيدُونَ', NULL, 'Or do they intend a plan? But those who disbelieve - they are the object of a plan.', '(Mereka tidak cukup dengan kata-kata dan tuduhan-tuduhan yang buruk sahaja) bahkan mereka hendak melakukan rancangan jahat (terhadapmu wahai Muhammad; tetapi mereka tidak akan berjaya) kerana orang-orang yang kafir itulah yang akan ditimpa balasan rancangan jahatnya.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 43, 'أَمْ لَهُمْ إِلَٰهٌ غَيْرُ ٱللَّهِ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'أَمْ لَهُمْ إِلَٰهٌ غَيْرُ اللَّهِ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ', NULL, 'Or have they a deity other than Allāh? Exalted is Allāh above whatever they associate with Him.', '(Apabila datangnya balasan rancangan jahat itu maka) adakah bagi mereka Tuhan (yang dapat menyelamatkan mereka) selain dari Allah? Maha Suci Allah dari apa yang mereka sekutukan itu.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 44, 'وَإِن يَرَوْا۟ كِسْفًا مِّنَ ٱلسَّمَآءِ سَاقِطًا يَقُولُوا۟ سَحَابٌ مَّرْكُومٌ', 'وَإِن يَرَوْا كِسْفًا مِّنَ السَّمَاءِ سَاقِطًا يَقُولُوا سَحَابٌ مَّرْكُومٌ', NULL, 'And if they were to see a fragment from the sky falling, they would say, "[It is merely] clouds heaped up."', 'Dan kiranya mereka melihat sepotong besar dari langit gugur (untuk menimpa mereka), mereka akan berkata: “(Itu adalah) awan yang bertompok - berlapis-lapis!”', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 45, 'فَذَرْهُمْ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ', 'فَذَرْهُمْ حَتَّىٰ يُلَاقُوا يَوْمَهُمُ الَّذِي فِيهِ يُصْعَقُونَ', NULL, 'So leave them until they meet their Day in which they will be struck insensible -', '(Kalau keingkaran dan kedegilan mereka sampai begitu sekali) maka biarkanlah mereka (wahai Muhammad, dan janganlah dihiraukan) sehingga mereka menemui hari yang padanya mereka akan binasa -', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 46, 'يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', 'يَوْمَ لَا يُغْنِي عَنْهُمْ كَيْدُهُمْ شَيْئًا وَلَا هُمْ يُنصَرُونَ', NULL, 'The Day their plan will not avail them at all, nor will they be helped.', '(Iaitu) hari segala rancangan jahat dan tipu daya mereka tidak dapat mendatangkan sebarang faedah kepada mereka, dan mereka pula tidak diberikan pertolongan.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 47, 'وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'وَإِنَّ لِلَّذِينَ ظَلَمُوا عَذَابًا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', NULL, 'And indeed, for those who have wronged is a punishment before that, but most of them do not know.', 'Sesungguhnya orang-orang yang zalim itu akan beroleh azab seksa selain dari azab yang tersebut, akan tetapi kebanyakan mereka tidak mengetahui (hakikat yang sebenarnya).', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 48, 'وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', 'وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', NULL, 'And be patient, [O Muḥammad], for the decision of your Lord, for indeed, you are in Our eyes [i.e., sight]. And exalt [Allāh] with praise of your Lord when you arise', 'Dan (dengan yang demikian) bersabarlah (wahai Muhammad) menerima hukum Tuhanmu (memberi tempoh kepada mereka), kerana sesungguhnya engkau tetap terselamat dalam pemuliharaan serta pengawasan Kami; dan bertasbihlah dengan memuji Tuhanmu semasa engkau bangun.', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(52, 49, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ٱلنُّجُومِ', 'وَمِنَ اللَّيْلِ فَسَبِّحْهُ وَإِدْبَارَ النُّجُومِ', NULL, 'And in a part of the night exalt Him and after [the setting of] the stars.', 'Dan juga hendaklah engkau bertasbih kepadaNya pada waktu malam, dan ketika bintang-bintang tenggelam (pada waktu subuh).', FALSE, NULL, NULL, 525, 27, 210, 459, FALSE, 0, NULL),
(53, 1, 'وَٱلنَّجْمِ إِذَا هَوَىٰ', 'والنجم اذا هوى', NULL, 'By the star when it descends,', 'Demi bintang semasa ia menjunam, -', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 2, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ', 'ما ضل صاحبكم وما غوى', NULL, 'Your companion [i.e., Muḥammad] has not strayed, nor has he erred,', 'Rakan kamu (Nabi Muhammad yang kamu tuduh dengan berbagai tuduhan itu), tidaklah ia menyeleweng (dari jalan yang benar), dan ia pula tidak sesat (dengan kepercayaan yang salah).', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 3, 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', 'وما ينطق عن الهوى', NULL, 'Nor does he speak from [his own] inclination.', 'Dan ia tidak memperkatakan (sesuatu yang berhubung dengan ugama Islam) menurut kemahuan dan pendapatnya sendiri.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 4, NULL),
(53, 4, 'إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ', 'ان هو الا وحي يوحى', NULL, 'It is not but a revelation revealed,', 'Segala yang diperkatakannya itu (sama ada Al-Quran atau hadis) tidak lain hanyalah wahyu yang diwahyukan kepadanya.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 5, 'عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ', 'علمه شديد القوى', NULL, 'Taught to him by one intense in strength [i.e., Gabriel] -', 'wahyu itu (disampaikan dan) diajarkan kepadanya oleh (malaikat jibril) yang amat kuat gagah, -', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 6, 'ذُو مِرَّةٍ فَٱسْتَوَىٰ', 'ذو مرة فاستوى', NULL, 'One of soundness. And he rose to [his] true form', 'Lagi yang mempunyai kebijaksanaan; kemudian ia memperlihatkan dirinya (kepada Nabi Muhammad) dengan rupanya asal, -', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 7, 'وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ', 'وهو بالافق الاعلى', NULL, 'While he was in the higher [part of the] horizon.', 'Sedang ia berada di arah yang tinggi (di langit);', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 8, 'ثُمَّ دَنَا فَتَدَلَّىٰ', 'ثم دنا فتدلى', NULL, 'Then he approached and descended', 'Kemudian ia mendekatkan dirinya (kepada Nabi Muhammad), lalu ia berjuntai sedikit demi sedikit,', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 9, 'فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ', 'فكان قاب قوسين او ادنى', NULL, 'And was at a distance of two bow lengths or nearer.', 'Sehingga menjadilah jarak (di antaranya dengan Nabi Muhammad) sekadar dua hujung busaran panah, atau lebih dekat lagi;', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 10, 'فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ', 'فاوحى الى عبده ما اوحى', NULL, 'And he revealed to His Servant what he revealed [i.e., conveyed].', 'Lalu Allah wahyukan kepada hambaNya (Muhammad, dengan perantaraan malaikat Jibril) apa yang telah diwahyukanNya.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 11, 'مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ', 'ما كذب الفؤاد ما راى', NULL, 'The heart did not lie [about] what it saw.', 'Hati (Nabi Muhammad) tidak mendustakan apa yang dilihatnya.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 12, 'أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ', 'افتمارونه على ما يرى', NULL, 'So will you dispute with him over what he saw?', 'Jika demikian, patutkah kamu hendak membantahnya mengenai apa yang telah dilihatnya itu?', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 4, NULL),
(53, 13, 'وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ', 'ولقد راه نزلة اخرى', NULL, 'And he certainly saw him in another descent', 'Dan demi sesungguhnya! (Nabi Muhammad) telah melihat (malaikat Jibril, dalam bentuk rupanya yang asal) sekali lagi,', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 4, NULL),
(53, 14, 'عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ', 'عند سدرة المنتهى', NULL, 'At the Lote Tree of the Utmost Boundary -', 'Di sisi “Sidratul-Muntaha”;', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 15, 'عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ', 'عندها جنة الماوى', NULL, 'Near it is the Garden of Refuge [i.e., Paradise] -', 'Yang di sisinya terletak Syurga “Jannatul-Makwa”.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 16, 'إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ', 'اذ يغشى السدرة ما يغشى', NULL, 'When there covered the Lote Tree that which covered [it].', '(Nabi Muhammad melihat jibril dalam bentuk rupanya yang asal pada kali ini ialah) semasa “Sidratul Muntaha” itu diliputi oleh makhluk-makhluk dari alam-alam ghaib, yang tidak terhingga.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 17, 'مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ', 'ما زاغ البصر وما طغى', NULL, 'The sight [of the Prophet (ﷺ)] did not swerve, nor did it transgress [its limit].', 'Penglihatan (Nabi Muhammad) tidak berkisar daripada menyaksikan dengan tepat (akan pemandangan yang indah di situ yang diizinkan melihatnya), dan tidak pula melampaui batas.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 5, NULL),
(53, 18, 'لَقَدْ رَأَىٰ مِنْ ءَايَـٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ', 'لقد راى من ايات ربه الكبرى', NULL, 'He certainly saw of the greatest signs of his Lord.', 'Demi sesungguhnya, ia telah melihat sebahagian dari sebesar-besar tanda-tanda (yang membuktikan luasnya pemerintahan dan kekuasaan) Tuhannya.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 6, NULL),
(53, 19, 'أَفَرَءَيْتُمُ ٱللَّـٰتَ وَٱلْعُزَّىٰ', 'افرايتم اللات والعزى', NULL, 'So have you considered al-Lāt and al-ʿUzzā?', '(Setelah kamu - wahai kaum musyrik Makkah - mendengar keterangan yang membuktikan kekuasaan dan keagungan Allah) maka adakah kamu nampak bahawa “Al-Laat” dan “Al-Uzza” -', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 20, 'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ', 'ومناة الثالثة الاخرى', NULL, 'And Manāt, the third - the other one?', 'Serta “Manaat” yang ketiga, yang bertaraf rendah lagi hina itu (layak disembah dan dianggap sebagai anak-anak perempuan Allah)?', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 3, NULL),
(53, 21, 'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ', 'أَلَكُمُ الذَّكَرُ وَلَهُ الْأُنثَىٰ', NULL, 'Is the male for you and for Him the female?', 'Patutkah kamu membahagi untuk diri kamu sendiri anak lelaki (yang kamu sukai), dan untuk Allah anak perempuan (yang kamu benci)?', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 0, NULL),
(53, 22, 'تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰٓ', 'تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰ', NULL, 'That, then, is an unjust division.', 'Pembahagian yang demikian, sudah tentu suatu pembahagian yang tidak adil.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 0, NULL),
(53, 23, 'إِنْ هِىَ إِلَّآ أَسْمَآءٌ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', 'إِنْ هِيَ إِلَّا أَسْمَاءٌ سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا أَنزَلَ اللَّهُ بِهَا مِن سُلْطَانٍ إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الْأَنفُسُ وَلَقَدْ جَاءَهُم مِّن رَّبِّهِمُ الْهُدَىٰ', NULL, 'They are not but [mere] names you have named them - you and your forefathers - for which Allāh has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance.', 'Benda-benda yang kamu sembah itu tidak lain hanyalah nama-nama yang kamu dan datuk nenek kamu menamakannya. Allah tidak sekali-kali menurunkan sebarang bukti yang membenarkannya. Mereka yang berbuat demikian, tidak menurut melainkan sangkaan-sangkaan dan apa yang diingini oleh hawa nafsunya. Padahal demi sesungguhnya telah datang kepada mereka petunjuk dari Tuhan mereka.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 0, NULL),
(53, 24, 'أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ', 'أَمْ لِلْإِنسَانِ مَا تَمَنَّىٰ', NULL, 'Or is there for man whatever he wishes?', 'Adakah manusia tetap akan dapat mencapai segala yang dicita-citakannya? (Tidak!).', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 0, NULL),
(53, 25, 'فَلِلَّهِ ٱلْـَٔاخِرَةُ وَٱلْأُولَىٰ', 'فَلِلَّهِ الْآخِرَةُ وَالْأُولَىٰ', NULL, 'Rather, to Allāh belongs the Hereafter and the first [life].', 'Kerana Allah jualah yang menguasai segala urusan akhirat dan urusan dunia.', FALSE, NULL, NULL, 526, 27, 210, 460, FALSE, 0, NULL),
(53, 26, 'وَكَم مِّن مَّلَكٍ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ', 'وَكَم مِّن مَّلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِن بَعْدِ أَن يَأْذَنَ اللَّهُ لِمَن يَشَاءُ وَيَرْضَىٰ', NULL, 'And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allāh has permitted [it] to whom He wills and approves.', '(Golongan yang musyrik mengharapkan pertolongan benda-benda yang mereka sembah itu) padahal berapa banyak malaikat di langit, syafaat mereka tidak dapat mendatangkan sebarang faedah, kecuali sesudah Allah mengizinkan bagi sesiapa yang dikehendakiNya dan diredhaiNya.', FALSE, NULL, NULL, 526, 27, 211, 461, FALSE, 0, NULL),
(53, 27, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', 'إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ لَيُسَمُّونَ الْمَلَائِكَةَ تَسْمِيَةَ الْأُنثَىٰ', NULL, 'Indeed, those who do not believe in the Hereafter name the angels female names,', 'Sesungguhnya orang-orang yang tidak beriman kepada hari akhirat sahajalah, yang tergamak menamakan malaikat itu dengan nama perempuan,', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 28, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا', 'وَمَا لَهُم بِهِ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا', NULL, 'And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all.', 'Sedang mereka tidak mempunyai sebarang pengetahuan mengenainya. Mereka tidak lain hanyalah mengikut sangkaan semata-mata, padahal sesungguhnya sangkaan itu tidak dapat memenuhi kehendak menentukan sesuatu dari kebenaran (iktiqad).', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 29, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا الْحَيَاةَ الدُّنْيَا', NULL, 'So turn away from whoever turns his back on Our message and desires not except the worldly life.', 'Oleh itu, janganlah engkau (wahai Muhammad) hiraukan orang yang berpaling dari pengajaran Kami, dan tidak mahu melainkan kehidupan dunia semata-mata.', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 30, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 'ذَٰلِكَ مَبْلَغُهُم مِّنَ الْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِمَنِ اهْتَدَىٰ', NULL, 'That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided.', '(Kepentingan dunia) itulah sahaja tujuan terakhir dari pengetahuan yang dicapai oleh mereka. Sesungguhnya Tuhanmu, Dia lah jua yang lebih mengetahui akan orang yang sesat dari jalanNya, dan Dia lah jua yang lebih mengetahui akan orang yang mendapat hidayah petunjuk.', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 31, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 'وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى', NULL, 'And to Allāh belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward] -', 'Dan Allah jualah yang memiliki segala yang ada di langit dan yang ada di bumi; (diciptakan semuanya itu) untuk membalas orang-orang yang berbuat jahat menurut apa yang mereka lakukan, dan membalas orang-orang yang berbuat baik dengan balasan yang sebaik-baiknya.', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 32, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَٰتِكُمْ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', 'الَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ إِلَّا اللَّمَمَ إِنَّ رَبَّكَ وَاسِعُ الْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ الْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِي بُطُونِ أُمَّهَاتِكُمْ فَلَا تُزَكُّوا أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ اتَّقَىٰ', NULL, 'Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him.', '(Iaitu) orang-orang yang menjauhi dosa-dosa besar serta perbuatan-perbuatan yang keji, kecuali salah silap yang kecil-kecil (yang mereka terlanjur melakukannya, maka itu dimaafkan). Sesungguhnya Tuhanmu Maha Luas keampunanNya. Ia lebih mengetahui akan keadaan kamu semenjak Ia mencipta kamu (berasal) dari tanah, dan semasa kamu berupa anak yang sedang melalui berbagai peringkat kejadian dalam perut ibu kamu; maka janganlah kamu memuji-muji diri kamu (bahawa kamu suci bersih dari dosa). Dia lah sahaja yang lebih mengetahui akan orang-orang yang bertaqwa.', FALSE, NULL, NULL, 527, 27, 211, 461, FALSE, 0, NULL),
(53, 33, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', 'أَفَرَأَيْتَ الَّذِي تَوَلَّىٰ', NULL, 'Have you seen the one who turned away', 'Adakah engkau mengetahui (keburukan) orang yang berpaling (dari menurut kebenaran kerana ia dihasut)?', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 34, 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ', 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰ', NULL, 'And gave a little and [then] refrained?', 'Dan setelah ia memberi sedikit pemberiannya, ia memutuskannya (kerana menurut hawa nafsunya)?', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 35, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 'أَعِندَهُ عِلْمُ الْغَيْبِ فَهُوَ يَرَىٰ', NULL, 'Does he have knowledge of the unseen, so he sees?', 'Adakah ia mempunyai pengetahuan mengenai perkara yang ghaib sehingga ia dapat mengetahui (bahawa orang lain boleh menghalang gantinya dari apa yang akan menimpanya pada hari akhirat)?', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 36, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', 'أَمْ لَمْ يُنَبَّأْ بِمَا فِي صُحُفِ مُوسَىٰ', NULL, 'Or has he not been informed of what was in the scriptures of Moses', 'Atau belumkah ia diberitahu akan apa yang terkandung dalam Kitab-kitab Nabi Musa -', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 37, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 'وَإِبْرَاهِيمَ الَّذِي وَفَّىٰ', NULL, 'And [of] Abraham, who fulfilled [his obligations] -', 'Dan juga (dalam Kitab-kitab) Nabi Ibrahim yang memenuhi dengan sempurnanya (segala yang diperintahkan kepadanya)?', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 38, 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', NULL, 'That no bearer of burdens will bear the burden of another', '(Dalam Kitab-kitab itu ditegaskan): Bahawa sesungguhnya seseorang yang boleh memikul tidak akan memikul dosa perbuatan orang lain (bahkan dosa usahanya sahaja);', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 39, 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', 'وَأَن لَّيْسَ لِلْإِنسَانِ إِلَّا مَا سَعَىٰ', NULL, 'And that there is not for man except that [good] for which he strives', 'Dan bahawa sesungguhnya tidak ada (balasan) bagi seseorang melainkan (balasan) apa yang diusahakannya;', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 40, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', 'وَأَنَّ سَعْيَهُ سَوْفَ يُرَىٰ', NULL, 'And that his effort is going to be seen -', 'Dan bahawa sesungguhnya usahanya itu akan diperlihatkan (kepadanya, pada hari kiamat kelak);', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 41, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', 'ثُمَّ يُجْزَاهُ الْجَزَاءَ الْأَوْفَىٰ', NULL, 'Then he will be recompensed for it with the fullest recompense -', 'Kemudian usahanya itu akan dibalas dengan balasan yang amat sempurna;', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 42, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', 'وَأَنَّ إِلَىٰ رَبِّكَ الْمُنتَهَىٰ', NULL, 'And that to your Lord is the finality', 'Dan bahawa sesungguhnya kepada hukum Tuhanmu lah kesudahan (segala perkara);', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 43, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', 'وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكَىٰ', NULL, 'And that it is He who makes [one] laugh and weep', 'Dan bahawa sesungguhnya, Dia lah yang menyebabkan (seseorang itu bergembira) tertawa, dan menyebabkan (seseorang itu berdukacita) menangis;', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 44, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 'وَأَنَّهُ هُوَ أَمَاتَ وَأَحْيَا', NULL, 'And that it is He who causes death and gives life', 'Dan bahawa sesungguhnya, Dia lah yang mematikan dan menghidupkan;', FALSE, NULL, NULL, 527, 27, 211, 462, FALSE, 0, NULL),
(53, 45, 'وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ', 'وَأَنَّهُ خَلَقَ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنثَىٰ', NULL, 'And that He creates the two mates - the male and female -', 'Dan bahawa sesungguhnya, Dia lah yang menciptakan pasangan - lelaki dan perempuan, -', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 46, 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', NULL, 'From a sperm-drop when it is emitted', 'Dari (setitis) air mani ketika dipancarkan (ke dalam rahim);', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 47, 'وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ', 'وَأَنَّ عَلَيْهِ النَّشْأَةَ الْأُخْرَىٰ', NULL, 'And that [incumbent] upon Him is the other [i.e., next] creation.', 'Dan bahawa sesungguhnya, Dia lah yang tetap menghidupkan semula (makhluk-makhluk yang mati);', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 48, 'وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ', 'وَأَنَّهُ هُوَ أَغْنَىٰ وَأَقْنَىٰ', NULL, 'And that it is He who enriches and suffices', 'Dan bahawa sesungguhnya, Dia lah yang memberikan (sesiapa yang dikehendakiNya) apa yang diperlukannya dan memberikannya tambahan yang boleh disimpan;', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 49, 'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ', 'وَأَنَّهُ هُوَ رَبُّ الشِّعْرَىٰ', NULL, 'And that it is He who is the Lord of Sirius', 'Dan bahawa sesungguhnya, Dia lah Tuhan (Pencipta) “Bintang Syikra;', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 50, 'وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ', 'وَأَنَّهُ أَهْلَكَ عَادًا الْأُولَىٰ', NULL, 'And that He destroyed the first [people of] ʿAad', 'Dan bahawa sesungguhnya, Dia lah yang membinasakan kaum “Aad” yang pertama (kaum Nabi Hud), -', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 51, 'وَثَمُودَا۟ فَمَآ أَبْقَىٰ', 'وَثَمُودَ فَمَا أَبْقَىٰ', NULL, 'And Thamūd - and He did not spare [them] -', 'Dan kaum “Thamud” (kaum Nabi Soleh). Maka tidak ada seorangpun (dari kedua-dua kaum itu) yang dibiarkan hidup.', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 52, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ', 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا هُمْ أَظْلَمَ وَأَطْغَىٰ', NULL, 'And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing.', 'Dan kaum Nabi Nuh sebelum itu (telah juga dibinasakan). Sesungguhnya mereka adalah orang-orang yang sangat zalim dan sangat melampaui batas.', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 53, 'وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ', 'وَالْمُؤْتَفِكَةَ أَهْوَىٰ', NULL, 'And the overturned towns He hurled down', 'Dan bandar-bandar yang ditunggang balikkan itu, Dia lah yang (mengangkatnya ke angkasa dan) menghempaskannya ke bumi;', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 54, 'فَغَشَّىٰهَا مَا غَشَّىٰ', 'فَغَشَّاهَا مَا غَشَّىٰ', NULL, 'And covered them by that which He covered.', 'Lalu (penduduk) bandar-bandar itu diliputi azab seksa yang meliputinya.', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 55, 'فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ', 'فَبِأَيِّ آلَاءِ رَبِّكَ تَتَمَارَىٰ', NULL, 'Then which of the favors of your Lord do you doubt?', 'Maka yang mana satu di antara nikmat-nikmat Tuhanmu (yang tidak terhingga itu) engkau ragu-ragukan (wahai manusia)?', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 56, 'هَٰذَا نَذِيرٌ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ', 'هَٰذَا نَذِيرٌ مِّنَ النُّذُرِ الْأُولَىٰ', NULL, 'This [Prophet (ﷺ)] is a warner from [i.e., like] the former warners.', '(Al-Quran) ini adalah pemberi amaran di antara jenis-jenis amaran yang telah lalu!', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 57, 'أَزِفَتِ ٱلْـَٔازِفَةُ', 'أَزِفَتِ الْآزِفَةُ', NULL, 'The Approaching Day has approached.', 'Telah hampir masa datangnya saat yang dekat itu (hari kiamat);', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 58, 'لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ', 'لَيْسَ لَهَا مِن دُونِ اللَّهِ كَاشِفَةٌ', NULL, 'Of it, [from those] besides Allāh, there is no remover.', 'Tidak ada sesiapapun selain Allah yang dapat menahan atau menghapuskan huru-hara “hari kiamat” itu.', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 59, 'أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ', 'أَفَمِنْ هَٰذَا الْحَدِيثِ تَعْجَبُونَ', NULL, 'Then at this statement do you wonder?', 'Maka patutkah kamu merasa hairan terhadap keterangan-keterangan Al-Quran ini (sehingga kamu mengingkarinya)?', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 60, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', NULL, 'And you laugh and do not weep', 'Serta kamu tertawa (mengejek-ejeknya), dan kamu tidak mahu menangis (menyesali kesalahan kamu serta takutkan balasan buruk yang akan menimpa kamu)?', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 61, 'وَأَنتُمْ سَٰمِدُونَ', 'وَأَنتُمْ سَامِدُونَ', NULL, 'While you are proudly sporting?', 'Sedang kamu adalah orang-orang yang sombong angkuh, lagi yang melalaikan kewajipan?', FALSE, NULL, NULL, 528, 27, 211, 462, FALSE, 0, NULL),
(53, 62, 'فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟', 'فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا', NULL, 'So prostrate to Allāh and worship [Him].', 'Oleh yang demikian, hendaklah kamu sujud kepada Allah (yang telah menurunkan Al-Quran itu), dan beribadatlah kamu kepadaNya (dengan sepenuh-penuh tauhid).', FALSE, NULL, NULL, 528, 27, 211, 462, TRUE, 0, NULL),
(54, 1, 'ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ', 'اقتربت الساعة وانشق القمر', NULL, 'The Hour has come near, and the moon has split [in two].', 'Telah hampir saat (kedatangan hari kiamat) dan terbelahlah bulan.', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 4, NULL),
(54, 2, 'وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ', 'وان يروا اية يعرضوا ويقولوا سحر مستمر', NULL, 'And if they see a sign [i.e., miracle], they turn away and say, "Passing magic."', 'Dan kalau mereka (kaum musyrik Mekah) melihat sesuatu mukjizat, mereka berpaling ingkar sambil berkata: (Ini ialah) sihir yang terus menerus berlaku.', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 7, NULL),
(54, 3, 'وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ ۚ وَكُلُّ أَمْرٍ مُّسْتَقِرٌّ', 'وكذبوا واتبعوا اهواءهم وكل امر مستقر', NULL, 'And they denied and followed their inclinations. But for every matter is a [time of] settlement.', 'Dan (telah menjadi adat) mereka mendustakan (Nabi Muhammad dan mukjizat-mukjizat yang dibawanya) serta menurut hawa nafsu mereka, sedang tiap-tiap perkara tetap (menurut keadaan yang ditentukan oleh Allah).', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 6, NULL),
(54, 4, 'وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ', 'ولقد جاءهم من الانباء ما فيه مزدجر', NULL, 'And there has already come to them of information that in which there is deterrence.', 'Dan sesungguhnya! Telah sampai kepada mereka (dengan perantaraan Al-Quran), sebahagian dari kisah-kisah dan berita (umat-umat yang telah lalu), yang mengandungi perkara-perkara yang cukup untuk mencegah mereka (dari perbuatan kufur itu).', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 7, NULL),
(54, 5, 'حِكْمَةٌۢ بَـٰلِغَةٌ ۖ فَمَا تُغْنِ ٱلنُّذُرُ', 'حكمة بالغة فما تغن النذر', NULL, 'Extensive wisdom - but warning does not avail [them].', '(Yang demikian ialah) pengajaran yang cukup sempurna; dalam pada itu, segala peringatan dan amaran tidak akan mendatangkan faedah (kepada mereka yang ingkar).', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 5, NULL),
(54, 6, 'فَتَوَلَّ عَنْهُمْ ۘ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍ نُّكُرٍ', 'فتول عنهم يوم يدع الداع الى شيء نكر', NULL, 'So leave them, [O Muḥammad]. The Day the Caller calls to something forbidding,', 'Oleh itu, berpalinglah dari mereka (wahai Muhammad dan janganlah dihiraukan). (Ingatlah) masa (malaikat) penyeru menyeru (mereka pada hari kiamat) kepada perkara yang tidak diingini (oleh orang yang bersalah);', FALSE, NULL, NULL, 528, 27, 211, 463, FALSE, 8, NULL),
(54, 7, 'خُشَّعًا أَبْصَـٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ', 'خشعا ابصارهم يخرجون من الاجداث كانهم جراد منتشر', NULL, 'Their eyes humbled, they will emerge from the graves as if they were locusts spreading,', '(Pada saat itu) masing-masing dengan keadaan menundukkan pandangannya kerana ketakutan keluar dari kubur seperti belalang yang terbang bertebaran.', FALSE, NULL, NULL, 529, 27, 211, 463, FALSE, 8, NULL),
(54, 8, 'مُّهْطِعِينَ إِلَى ٱلدَّاعِ ۖ يَقُولُ ٱلْكَـٰفِرُونَ هَـٰذَا يَوْمٌ عَسِرٌ', 'مهطعين الى الداع يقول الكافرون هذا يوم عسر', NULL, 'Racing ahead toward the Caller. The disbelievers will say, "This is a difficult Day."', 'Masing-masing dengan cepatnya menuju kepada penyeru itu. (Pada saat yang demikian), orang-orang yang kafir berkata: Hari ini ialah hari yang amat sukar!', FALSE, NULL, NULL, 529, 27, 211, 463, FALSE, 8, NULL),
(54, 9, '۞ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌ وَٱزْدُجِرَ', 'كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر', NULL, 'The people of Noah denied before them, and they denied Our servant and said, "A madman," and he was repelled.', 'Sebelum mereka, kaum Nabi Nuh juga telah mendustakan (Rasulnya); iaitu mereka mendustakan hamba Kami (Nabi Nuh) serta mereka menuduhnya dengan berkata: Dia seorang gila dan dia telah diancam (dan dihalang daripada menjalankan dakwah agama).', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 9, NULL),
(54, 10, 'فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌ فَٱنتَصِرْ', 'فدعا ربه اني مغلوب فانتصر', NULL, 'So he invoked his Lord, "Indeed, I am overpowered, so help."', 'Lalu dia berdoa merayu kepada Tuhannya dengan berkata: Sesungguhnya aku ini dikalahkan (oleh kaumku yang ingkar), oleh itu menangkanlah daku (terhadap mereka)!', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 5, NULL),
(54, 11, 'فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍ مُّنْهَمِرٍ', 'ففتحنا ابواب السماء بماء منهمر', NULL, 'Then We opened the gates of the heaven with rain pouring down', 'Maka Kami bukakan pintu-pintu langit, dengan menurunkan hujan yang mencurah-curah.', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 5, NULL),
(54, 12, 'وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍ قَدْ قُدِرَ', 'وفجرنا الارض عيونا فالتقى الماء على امر قد قدر', NULL, 'And caused the earth to burst with springs, and the waters met for a matter already predestined.', 'Dan Kami jadikan bumi memancarkan mata air-mata air (di sana sini), lalu bertemulah air (langit dan bumi) itu untuk (melakukan) satu perkara yang telah ditetapkan.', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 9, NULL),
(54, 13, 'وَحَمَلْنَـٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍ وَدُسُرٍ', 'وحملناه على ذات الواح ودسر', NULL, 'And We carried him on a [construction of] planks and nails,', 'Dan Kami bawa naik Nabi Nuh (berserta pengikut-pengikutnya) di atas (bahtera yang dibina) dari keping-keping papan dan paku;', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 5, NULL),
(54, 14, 'تَجْرِى بِأَعْيُنِنَا جَزَآءً لِّمَن كَانَ كُفِرَ', 'تجري باعيننا جزاء لمن كان كفر', NULL, 'Sailing under Our observation as reward for he who had been denied.', 'Yang belayar laju dengan pemeliharaan dan pengawasan Kami; (Kami melakukan yang demikian dan menimpakan taufan itu) sebagai balasan bagi orang-orang yang kufur ingkar!', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 6, NULL),
(54, 15, 'وَلَقَد تَّرَكْنَـٰهَآ ءَايَةً فَهَلْ مِن مُّدَّكِرٍ', 'ولقد تركناها اية فهل من مدكر', NULL, 'And We left it as a sign, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah jadikan bahtera itu sebagai satu tanda yang menjadi pengajaran, maka adakah orang yang mahu beringat dan insaf?', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 6, NULL),
(54, 16, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فكيف كان عذابي ونذر', NULL, 'And how [severe] were My punishment and warning.', 'Oleh itu, perhatikanlah bagaimana buruknya azabKu dan kesan amaran-amaranKu.', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 4, NULL),
(54, 17, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'ولقد يسرنا القران للذكر فهل من مدكر', NULL, 'And We have certainly made the Qur’ān easy for remembrance, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah mudahkan Al-Quran untuk menjadi peringatan dan pengajaran, maka adakah sesiapa yang mahu mengambil peringatan dan pelajaran (daripadanya)?', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 7, NULL),
(54, 18, 'كَذَّبَتْ عَادٌ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'كذبت عاد فكيف كان عذابي ونذر', NULL, 'ʿAad denied; and how [severe] were My punishment and warning.', '(Demikian juga) kaum Aad telah mendustakan Rasulnya (lalu mereka dibinasakan); maka perhatikanlah, bagaimana buruknya azabku dan kesan amaran-amaranKu!', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 6, NULL),
(54, 19, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ', 'انا ارسلنا عليهم ريحا صرصرا في يوم نحس مستمر', NULL, 'Indeed, We sent upon them a screaming wind on a day of continuous misfortune,', 'Sesungguhnya Kami telah menghantarkan kepada mereka angin ribut yang kencang, pada hari nahas yang berlanjutan; -', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 9, NULL),
(54, 20, 'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ', 'تنزع الناس كانهم اعجاز نخل منقعر', NULL, 'Extracting the people as if they were trunks of palm trees uprooted.', 'Yang menumbangkan manusia gugur bergelimpangan, seolah-olah mereka batang-batang pohon kurma yang terbongkar.', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 6, NULL),
(54, 21, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فَكَيْفَ كَانَ عَذَابِي وَنُذُرِ', NULL, 'And how [severe] were My punishment and warning.', 'Maka perhatikanlah, bagaimana buruknya azabKu dan kesan amaran-amaranKu!', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 0, NULL),
(54, 22, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', NULL, 'And We have certainly made the Qur’ān easy for remembrance, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah mudahkan Al-Quran untuk peringatan dan pengajaran, maka adakah sesiapa yang mahu mengambil peringatan dan pelajaran (daripadanya)?', FALSE, NULL, NULL, 529, 27, 212, 463, FALSE, 0, NULL),
(54, 23, 'كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ', 'كَذَّبَتْ ثَمُودُ بِالنُّذُرِ', NULL, 'Thamūd denied the warning.', '(Demikian juga) kaum Thamud telah mendustakan peringatan dan amaran (yang disampaikan oleh Rasul mereka, Nabi Soleh).', FALSE, NULL, NULL, 529, 27, 212, 464, FALSE, 0, NULL),
(54, 24, 'فَقَالُوٓا۟ أَبَشَرًا مِّنَّا وَٰحِدًا نَّتَّبِعُهُۥٓ إِنَّآ إِذًا لَّفِى ضَلَٰلٍ وَسُعُرٍ', 'فَقَالُوا أَبَشَرًا مِّنَّا وَاحِدًا نَّتَّبِعُهُ إِنَّا إِذًا لَّفِي ضَلَالٍ وَسُعُرٍ', NULL, 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.', 'Lalu mereka berkata: Patutkah kita menurut manusia dari jenis kita, lagi yang berseorangan? Jika demikian, sesungguhnya kita berada dalam keadaan sesat dan gila!', FALSE, NULL, NULL, 529, 27, 212, 464, FALSE, 0, NULL),
(54, 25, 'أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ', 'أَأُلْقِيَ الذِّكْرُ عَلَيْهِ مِن بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ', NULL, 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."', 'Tidaklah patut wahyu peringatan itu diturunkan kepadanya (padahal orang-orang yang lebih layak ada) di antara kita. Bahkan dialah seorang pendusta, lagi sombong angkuh.', FALSE, NULL, NULL, 529, 27, 212, 464, FALSE, 0, NULL),
(54, 26, 'سَيَعْلَمُونَ غَدًا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ', 'سَيَعْلَمُونَ غَدًا مَّنِ الْكَذَّابُ الْأَشِرُ', NULL, 'They will know tomorrow who is the insolent liar.', 'Mereka akan mengetahui kelak siapakah orangnya yang pendusta, lagi sombong angkuh itu.', FALSE, NULL, NULL, 529, 27, 212, 464, FALSE, 0, NULL),
(54, 27, 'إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةً لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ', 'إِنَّا مُرْسِلُو النَّاقَةِ فِتْنَةً لَّهُمْ فَارْتَقِبْهُمْ وَاصْطَبِرْ', NULL, 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.', 'Sesungguhnya Kami menghantarkan unta betina (yang menjadi mukjizat) sebagai satu ujian bagi mereka. Lalu (Kami perintahkan Rasul Kami): Tunggulah (apakah yang mereka akan lakukan) serta bersabarlah (terhadap tentangan mereka).', FALSE, NULL, NULL, 529, 27, 212, 464, FALSE, 0, NULL),
(54, 28, 'وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ كُلُّ شِرْبٍ مُّحْتَضَرٌ', 'وَنَبِّئْهُمْ أَنَّ الْمَاءَ قِسْمَةٌ بَيْنَهُمْ كُلُّ شِرْبٍ مُّحْتَضَرٌ', NULL, 'And inform them that the water is shared between them, each [day of] drink attended [by turn].', 'Dan khabarkanlah kepada mereka, bahawa sesungguhnya air (telaga mereka) terbahagi di antara mereka dengan unta itu, tiap-tiap bahagian air itu dihadiri oleh yang berhak mengambilnya (pada hari gilirannya).', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 29, 'فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', 'فَنَادَوْا صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', NULL, 'But they called their companion, and he dared and hamstrung [her].', '(Mereka selepas itu merasa bosan dengan keadaan unta itu dan berkira hendak membunuhnya), lalu mereka memanggil kawan mereka (yang sanggup membunuhnya), dia pun bertindak sampai dapat membunuhnya.', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 30, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'فَكَيْفَ كَانَ عَذَابِي وَنُذُرِ', NULL, 'And how [severe] were My punishment and warning.', 'Maka perhatikanlah, bagaimana buruknya azabKu dan kesan amaran-amaranKu!', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 31, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَٰحِدَةً فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ', 'إِنَّا أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَاحِدَةً فَكَانُوا كَهَشِيمِ الْمُحْتَظِرِ', NULL, 'Indeed, We sent upon them one shriek [i.e., blast from the sky], and they became like the dry twig fragments of an [animal] pen.', 'Sesungguhnya Kami hantarkan kepada mereka satu pekikan (yang dahsyat), lalu menjadilah mereka (hancur) seperti ranting-ranting dan daun-daun yang pecah hancur, yang dikumpulkan oleh pemilik kandang binatang ternak.', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 32, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', NULL, 'And We have certainly made the Qur’ān easy for remembrance, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah mudahkan Al-Quran untuk peringatan dan pengajaran, maka adakah sesiapa yang mahu mengambil peringatan dan pelajaran (daripadanya)?', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 33, 'كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ', 'كَذَّبَتْ قَوْمُ لُوطٍ بِالنُّذُرِ', NULL, 'The people of Lot denied the warning.', '(Demikian juga) kaum Nabi Lut telah mendustakan peringatan dan amaran (yang disampaikan oleh Rasulnya).', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 34, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍ نَّجَّيْنَٰهُم بِسَحَرٍ', 'إِنَّا أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّا آلَ لُوطٍ نَّجَّيْنَاهُم بِسَحَرٍ', NULL, 'Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn.', 'Sesungguhnya Kami telah menghantarkan kepada mereka angin ribut yang menghujani mereka dengan batu, kecuali keluarga Nabi Lut, Kami selamatkan mereka (dengan menyuruh mereka keluar dari situ) pada waktu jauh malam,', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 35, 'نِّعْمَةً مِّنْ عِندِنَا كَذَٰلِكَ نَجْزِى مَن شَكَرَ', 'نِّعْمَةً مِّنْ عِندِنَا كَذَٰلِكَ نَجْزِي مَن شَكَرَ', NULL, 'As favor from Us. Thus do We reward he who is grateful.', 'Sebagai limpah kurnia dari Kami. Demikianlah kami membalas orang-orang yang bersyukur.', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 36, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ', 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا بِالنُّذُرِ', NULL, 'And he had already warned them of Our assault, but they disputed the warning.', 'Dan demi sesungguhnya! Nabi Lut telah memberi amaran kepada mereka mengenai azab seksa Kami; dalam pada itu, mereka tetap mendustakan amaran-amaran itu.', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 37, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'وَلَقَدْ رَاوَدُوهُ عَن ضَيْفِهِ فَطَمَسْنَا أَعْيُنَهُمْ فَذُوقُوا عَذَابِي وَنُذُرِ', NULL, 'And they had demanded from him his guests, but We obliterated their eyes, [saying], "Taste My punishment and warning."', 'Dan demi sesungguhnya! Mereka telah memujuk Nabi Lut mengenai tetamunya, lalu Kami hapuskan biji mata mereka, serta (dikatakan kepada mereka): Rasalah azabKu dan kesan amaran-amaranKu!', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 38, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ', 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ', NULL, 'And there came upon them by morning an abiding punishment.', 'Dan demi sesungguhnya! Mereka telah ditimpa azab yang kekal pada pagi-pagi hari (esoknya).', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 39, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'فَذُوقُوا عَذَابِي وَنُذُرِ', NULL, 'So taste My punishment and warning.', 'Lalu (dikatakan kepada mereka): Rasalah azabKu dan kesan amaran-amaranKu!', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 40, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', NULL, 'And We have certainly made the Qur’ān easy for remembrance, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah mudahkan Al-Quran untuk peringatan dan pengajaran, maka adakah sesiapa yang mahu mengambil peringatan dan pelajaran (daripadanya)?', FALSE, NULL, NULL, 530, 27, 212, 464, FALSE, 0, NULL),
(54, 41, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ', 'وَلَقَدْ جَاءَ آلَ فِرْعَوْنَ النُّذُرُ', NULL, 'And there certainly came to the people of Pharaoh warning.', 'Dan demi sesungguhnya! Firaun dan kaumnya telah didatangi (Rasul-rasul) pemberi amaran.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 42, 'كَذَّبُوا۟ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ', 'كَذَّبُوا بِآيَاتِنَا كُلِّهَا فَأَخَذْنَاهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ', NULL, 'They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability.', 'Mereka telah mendustakan mukjizat-mukjizat Kami semuanya, lalu Kami timpakan azab seksa kepada mereka sebagai seksaan dari Yang Maha Perkasa, lagi Maha Kuasa.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 43, 'أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُو۟لَٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌ فِى ٱلزُّبُرِ', 'أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُولَٰئِكُمْ أَمْ لَكُم بَرَاءَةٌ فِي الزُّبُرِ', NULL, 'Are your disbelievers better than those [former ones], or have you immunity in the scriptures?', 'Adakah orang-orang kafir kamu (wahai kaum musyrik Mekah), lebih baik (kekuatan, kekayaan dan kehandalannya) daripada kaum-kaum kafir yang tersebut itu? Atau adakah kamu mempunyai sebarang bukti dalam Kitab-kitab Suci tentang kebebasan kamu (dari azab)?', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 44, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ', 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ', NULL, 'Or do they say, "We are an assembly supporting [each other]"?', '(Mereka tidak mempunyai sebarang bukti) bahkan mereka akan berkata (dengan angkuhnya): Kami satu kaum yang bersatu, yang sudah tentu dapat membela diri!', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 45, 'سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ', 'سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ', NULL, '[Their] assembly will be defeated, and they will turn their backs [in retreat].', 'Kumpulan mereka yang bersatu itu tetap akan dikalahkan dan mereka pula akan berpaling lari.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 46, 'بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', 'بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', NULL, 'But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter.', '(Bukan kekalahan itu sahaja) bahkan hari kiamat ialah hari yang dijanjikan kepada mereka (untuk menerima balasan yang sepenuh-penuhnya) dan (azab seksa) hari kiamat itu amat dahsyat dan amat pahit.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 47, 'إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَٰلٍ وَسُعُرٍ', 'إِنَّ الْمُجْرِمِينَ فِي ضَلَالٍ وَسُعُرٍ', NULL, 'Indeed, the criminals are in error and madness..', 'Sesungguhnya orang-orang yang berdosa berada dalam keadaan sesat (di dunia), dan (di akhirat pula mereka berada dalam) api Neraka.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 48, 'يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ', 'يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا مَسَّ سَقَرَ', NULL, 'The Day they are dragged into the Fire on their faces [it will be said], "Taste the touch of Saqar."', 'Semasa mereka diseret di dalam Neraka (dengan tertiarap) atas muka mereka, (serta dikatakan kepada mereka): Rasalah kamu bakaran api Neraka.', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 49, 'إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍ', 'إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ', NULL, 'Indeed, all things We created with predestination.', 'Sesungguhnya Kami menciptakan tiap-tiap sesuatu menurut takdir (yang telah ditentukan).', FALSE, NULL, NULL, 530, 27, 212, 465, FALSE, 0, NULL),
(54, 50, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌ كَلَمْحٍۭ بِٱلْبَصَرِ', 'وَمَا أَمْرُنَا إِلَّا وَاحِدَةٌ كَلَمْحٍ بِالْبَصَرِ', NULL, 'And Our command is but one, like a glance of the eye.', 'Dan hal Kami (dalam melaksanakan apa yang Kami kehendaki), hanyalah satu cara sahaja, (cepat jadinya) seperti sekelip mata.', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(54, 51, 'وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ', 'وَلَقَدْ أَهْلَكْنَا أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ', NULL, 'And We have already destroyed your kinds, so is there any who will remember?', 'Dan demi sesungguhnya! Kami telah binasakan orang-orang yang sama keadaannya seperti kamu; maka adakah sesiapa yang mahu mengambil peringatan dan pelajaran?', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(54, 52, 'وَكُلُّ شَىْءٍ فَعَلُوهُ فِى ٱلزُّبُرِ', 'وَكُلُّ شَيْءٍ فَعَلُوهُ فِي الزُّبُرِ', NULL, 'And everything they did is in written records.', 'Dan tiap-tiap perkara yang mereka lakukan, adalah tertulis di dalam Kitab suratan amal;', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(54, 53, 'وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ', 'وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ', NULL, 'And every small and great [thing] is inscribed.', 'Dan tiap-tiap perkara yang kecil dan yang besar tetap tercatit.', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(54, 54, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَنَهَرٍ', 'إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ', NULL, 'Indeed, the righteous will be among gardens and rivers,', 'Sesungguhnya orang-orang yang bertakwa, di tempatkan dalam taman-taman Syurga (yang indah) dan (dekat) beberapa sungai,', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(54, 55, 'فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍۭ', 'فِي مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍ', NULL, 'In a seat of honor near a Sovereign, Perfect in Ability.', 'Di tempat yang sungguh bahagia, di sisi Tuhan Yang Menguasai segala-galanya, lagi Yang Berkuasa melakukan sekehendakNya.', FALSE, NULL, NULL, 531, 27, 212, 465, FALSE, 0, NULL),
(55, 1, 'ٱلرَّحْمَـٰنُ', 'الرحمن', NULL, 'The Most Merciful', '(Tuhan) Yang Maha Pemurah serta melimpah-limpah rahmatNya.', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 1, NULL),
(55, 2, 'عَلَّمَ ٱلْقُرْءَانَ', 'علم القران', NULL, 'Taught the Qur’ān,', 'Dia lah yang telah mengajarkan Al-Quran.', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 2, NULL),
(55, 3, 'خَلَقَ ٱلْإِنسَـٰنَ', 'خلق الانسان', NULL, 'Created man,', 'Dia lah yang telah menciptakan manusia; -', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 2, NULL),
(55, 4, 'عَلَّمَهُ ٱلْبَيَانَ', 'علمه البيان', NULL, '[And] taught him eloquence.', 'Dia lah yang telah membolehkan manusia (bertutur) memberi dan menerima kenyataan.', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 2, NULL),
(55, 5, 'ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍ', 'الشمس والقمر بحسبان', NULL, 'The sun and the moon [move] by precise calculation,', 'Matahari dan bulan beredar dengan peraturan dan hitungan yang tertentu;', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 3, NULL),
(55, 6, 'وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ', 'والنجم والشجر يسجدان', NULL, 'And the stars and trees prostrate.', 'Dan tumbuh-tumbuhan yang melata serta pohon-pohon kayu-kayan, masing-masing tunduk menurut peraturanNya.', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 3, NULL),
(55, 7, 'وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ', 'والسماء رفعها ووضع الميزان', NULL, 'And the heaven He raised and imposed the balance', 'Dan langit dijadikannya (bumbung) tinggi, serta Ia mengadakan undang-undang dan peraturan neraca keadilan,', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 4, NULL),
(55, 8, 'أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ', 'الا تطغوا في الميزان', NULL, 'That you not transgress within the balance.', 'Supaya kamu tidak melampaui batas dalam menjalankan keadilan;', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 4, NULL),
(55, 9, 'وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ', 'واقيموا الوزن بالقسط ولا تخسروا الميزان', NULL, 'And establish weight in justice and do not make deficient the balance.', 'Dan betulkanlah cara menimbang itu dengan adil, serta janganlah kamu mengurangi barang yang ditimbang.', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 6, NULL),
(55, 10, 'وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', 'والارض وضعها للانام', NULL, 'And the earth He laid [out] for the creatures.', 'Dan bumi pula dijadikannya rata untuk kegunaan manusia dan makhluk-makhlukNya yang lain:', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 3, NULL),
(55, 11, 'فِيهَا فَـٰكِهَةٌ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ', 'فيها فاكهة والنخل ذات الاكمام', NULL, 'Therein is fruit and palm trees having sheaths [of dates]', 'Terdapat padanya berbagai jenis buah-buahan dan pohon-pohon kurma yang ada kelopak-kelopak mayang;', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 5, NULL),
(55, 12, 'وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ', 'والحب ذو العصف والريحان', NULL, 'And grain having husks and scented plants.', 'Demikian juga terdapat biji-bijian yang ada jerami serta daun, dan terdapat lagi bunga-bungaan yang harum;', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 4, NULL),
(55, 13, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فباي الاء ربكما تكذبان', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan (wahai umat manusia dan jin)?', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 4, NULL),
(55, 14, 'خَلَقَ ٱلْإِنسَـٰنَ مِن صَلْصَـٰلٍ كَٱلْفَخَّارِ', 'خلق الانسان من صلصال كالفخار', NULL, 'He created man from clay like [that of] pottery.', 'Ia menciptakan manusia (lembaga Adam) dari tanah liat kering seperti tembikar,', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 5, NULL),
(55, 15, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍ مِّن نَّارٍ', 'وخلق الجان من مارج من نار', NULL, 'And He created the jinn from a smokeless flame of fire.', 'Dan Ia telah menciptakan jin dari lidah api yang menjulang-julang;', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 6, NULL),
(55, 16, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فباي الاء ربكما تكذبان', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 531, 27, 213, 466, FALSE, 4, NULL),
(55, 17, 'رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ', 'رب المشرقين ورب المغربين', NULL, '[He is] Lord of the two sunrises and Lord of the two sunsets.', '(Dia lah) Tuhan yang mentadbirkan dua timur, dan Tuhan yang mentadbirkan dua barat.', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 4, NULL),
(55, 18, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فباي الاء ربكما تكذبان', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 4, NULL),
(55, 19, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', 'مرج البحرين يلتقيان', NULL, 'He released the two seas, meeting [one another];', 'Ia biarkan air dua laut (yang masin dan yang tawar) mengalir, sedang keduanya pula bertemu;', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 3, NULL),
(55, 20, 'بَيْنَهُمَا بَرْزَخٌ لَّا يَبْغِيَانِ', 'بينهما برزخ لا يبغيان', NULL, 'Between them is a barrier so neither of them transgresses.', 'Di antara keduanya ada penyekat yang memisahkannya, masing-masing tidak melampaui sempadannya;', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 4, NULL),
(55, 21, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 0, NULL),
(55, 22, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', 'يَخْرُجُ مِنْهُمَا اللُّؤْلُؤُ وَالْمَرْجَانُ', NULL, 'From both of them emerge pearl and coral.', 'Dari kedua laut itu, keluar mutiara dan marjan;', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 0, NULL),
(55, 23, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 0, NULL),
(55, 24, 'وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'وَلَهُ الْجَوَارِ الْمُنشَآتُ فِي الْبَحْرِ كَالْأَعْلَامِ', NULL, 'And to Him belong the ships [with sails] elevated in the sea like mountains.', 'Dan Dia lah yang menguasai kapal-kapal yang belayar di laut, yang kembang tinggi layarnya seperti gunung-ganang;', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 0, NULL),
(55, 25, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 466, FALSE, 0, NULL),
(55, 26, 'كُلُّ مَنْ عَلَيْهَا فَانٍ', 'كُلُّ مَنْ عَلَيْهَا فَانٍ', NULL, 'Everyone upon it [i.e., the earth] will perish,', 'Segala yang ada di muka bumi itu akan binasa:', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 27, 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ', NULL, 'And there will remain the Face of your Lord, Owner of Majesty and Honor.', 'Dan akan kekalah Zat Tuhanmu yang mempunyai Kebesaran dan Kemuliaan:', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 28, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 29, 'يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍ', 'يَسْأَلُهُ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ', NULL, 'Whoever is within the heavens and earth asks Him; every day He is in [i.e., bringing about] a matter.', 'Sekalian makhluk yang ada di langit dan di bumi sentiasa berhajat dan memohon kepadaNya. Tiap-tiap masa Ia di dalam urusan (mencipta dan mentadbirkan makhluk-makhlukNya)!', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 30, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan)?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 31, 'سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ', 'سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلَانِ', NULL, 'We will attend to you, O prominent beings.', 'Kami hanya akan menguruskan hitungan dan balasan amal kamu sahaja (pada hari kiamat,) wahai manusia dan jin!', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 32, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 33, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍ', 'يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ إِنِ اسْتَطَعْتُمْ أَن تَنفُذُوا مِنْ أَقْطَارِ السَّمَاوَاتِ وَالْأَرْضِ فَانفُذُوا لَا تَنفُذُونَ إِلَّا بِسُلْطَانٍ', NULL, 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allāh].', 'Wahai sekalian jin dan manusia! Kalau kamu dapat menembus keluar dari kawasan-kawasan langit dan bumi (untuk melarikan diri dari kekuasaan dan balasan Kami), maka cubalah kamu menembus keluar. Kamu tidak akan menembus keluar melainkan dengan satu kekuasaan (yang mengatasi kekuasaan Kami; masakan dapat)!', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 34, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 35, 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ', 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ', NULL, 'There will be sent upon you a flame of fire and smoke, and you will not defend yourselves.', 'Kamu (wahai golongan yang kufur ingkar dari kalangan jin dan manusia) akan ditimpakan dengan api yang menjulang-julang dan leburan tembaga cair (yang membakar); dengan yang demikian, kamu tidak akan dapat mempertahankan diri (dari azab seksa itu);', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 36, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 37, 'فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةً كَٱلدِّهَانِ', 'فَإِذَا انشَقَّتِ السَّمَاءُ فَكَانَتْ وَرْدَةً كَالدِّهَانِ', NULL, 'And when the heaven is split open and becomes rose-colored like oil -', 'Selain itu (sungguh ngeri) ketika langit pecah-belah lalu menjadilah ia merah mawar, berkilat seperti minyak;', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 38, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 39, 'فَيَوْمَئِذٍ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٌ وَلَا جَآنٌّ', 'فَيَوْمَئِذٍ لَّا يُسْأَلُ عَن ذَنبِهِ إِنسٌ وَلَا جَانٌّ', NULL, 'Then on that Day none will be asked about his sin among men or jinn.', 'Pada masa itu tiada sesiapapun, sama ada manusia atau jin, yang akan ditanya tentang dosanya (kerana masing-masing dapat dikenal menurut keadaannya);', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 40, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 532, 27, 213, 467, FALSE, 0, NULL),
(55, 41, 'يُعْرَفُ ٱلْمُجْرِمُونَ بِسِيمَٰهُمْ فَيُؤْخَذُ بِٱلنَّوَٰصِى وَٱلْأَقْدَامِ', 'يُعْرَفُ الْمُجْرِمُونَ بِسِيمَاهُمْ فَيُؤْخَذُ بِالنَّوَاصِي وَالْأَقْدَامِ', NULL, 'The criminals will be known by their marks, and they will be seized by the forelocks and the feet.', 'Orang-orang yang berdosa dapat dikenal dari tanda-tandanya, lalu dipegang dari atas kepala dan kakinya (serta diseret ke neraka);', FALSE, NULL, NULL, 533, 27, 213, 467, FALSE, 0, NULL),
(55, 42, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 467, FALSE, 0, NULL),
(55, 43, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى يُكَذِّبُ بِهَا ٱلْمُجْرِمُونَ', 'هَٰذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ بِهَا الْمُجْرِمُونَ', NULL, 'This is Hell, which the criminals deny.', '(Lalu dikatakan kepada mereka): “Inilah neraka Jahannam yang selalu orang-orang yang berdosa mendustakannya”.', FALSE, NULL, NULL, 533, 27, 213, 467, FALSE, 0, NULL),
(55, 44, 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍ', 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ آنٍ', NULL, 'They will circulate between it and scalding water, heated [to the utmost degree].', 'Mereka (terus diseksa) berulang-ulang di antara api neraka dengan air yang menggelegak yang cukup masak panasnya!', FALSE, NULL, NULL, 533, 27, 213, 467, FALSE, 0, NULL),
(55, 45, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 467, FALSE, 0, NULL),
(55, 46, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ', 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ', NULL, 'But for he who has feared the position of his Lord are two gardens -', 'Dan orang yang takut akan keadaan dirinya di mahkamah Tuhannya (untuk dihitung amalnya), disediakan baginya dua Syurga, -', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 47, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 48, 'ذَوَاتَآ أَفْنَانٍ', 'ذَوَاتَا أَفْنَانٍ', NULL, 'Having [spreading] branches.', '(Dua Syurga) yang ada berjenis-jenis pohon dan buah-buahan; -', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 49, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 50, 'فِيهِمَا عَيْنَانِ تَجْرِيَانِ', 'فِيهِمَا عَيْنَانِ تَجْرِيَانِ', NULL, 'In both of them are two springs, flowing.', 'Pada kedua-dua Syurga itu terdapat dua matair yang mengalir; -', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 51, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan.', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 52, 'فِيهِمَا مِن كُلِّ فَٰكِهَةٍ زَوْجَانِ', 'فِيهِمَا مِن كُلِّ فَاكِهَةٍ زَوْجَانِ', NULL, 'In both of them are of every fruit, two kinds.', 'Pada kedua Syurga itu terdapat dua macam dari tiap-tiap jenis buah-buahan (yang biasa dan yang luar biasa).', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 53, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 54, 'مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍ', 'مُتَّكِئِينَ عَلَىٰ فُرُشٍ بَطَائِنُهَا مِنْ إِسْتَبْرَقٍ وَجَنَى الْجَنَّتَيْنِ دَانٍ', NULL, '[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low.', 'Mereka (bersenang-senang di tempat masing-masing dalam Syurga itu dengan) berbaring di atas hamparan-hamparan, yang lapisan-lapisan sebelah dalamnya - dari sutera tebal yang bersulam; dan buah-buahan kedua-dua Syurga itu dekat (kepada mereka) untuk dipetik.', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 55, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 56, 'فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 'فِيهِنَّ قَاصِرَاتُ الطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَانٌّ', NULL, 'In them are women limiting [their] glances, untouched before them by man or jinnī -', 'Di dalam Syurga-syurga itu terdapat bidadari-bidadari yang pandangannya tertumpu (kepada mereka semata-mata), yang tidak pernah disentuh sebelum mereka oleh manusia dan jin;', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 57, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 58, 'كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ', 'كَأَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُ', NULL, 'As if they were rubies and coral.', 'Bidadari-bidadari itu (cantik berseri) seperti permata delima dan marjan.', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 59, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 60, 'هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ', 'هَلْ جَزَاءُ الْإِحْسَانِ إِلَّا الْإِحْسَانُ', NULL, 'Is the reward for good [anything] but good?', 'Bukankah tidak ada balasan bagi amal yang baik - melainkan balasan yang baik juga?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 61, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 62, 'وَمِن دُونِهِمَا جَنَّتَانِ', 'وَمِن دُونِهِمَا جَنَّتَانِ', NULL, 'And below them both [in excellence] are two [other] gardens -', 'Dan selain dari dua Syurga itu, dua Syurga lagi (untuk menjadi balasan bagi golongan peringkat yang kedua);', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 63, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 64, 'مُدْهَآمَّتَانِ', 'مُدْهَامَّتَانِ', NULL, 'Dark green [in color].', 'Kedua-duanya menghijau subur tanamannya;', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 65, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 66, 'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', 'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', NULL, 'In both of them are two springs, spouting.', 'Dalam kedua-dua Syurga itu terdapat dua matair yang terus menerus memancutkan airnya:', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 67, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 533, 27, 213, 468, FALSE, 0, NULL),
(55, 68, 'فِيهِمَا فَٰكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', 'فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', NULL, 'In both of them are fruit and palm trees and pomegranates.', 'Pada keduanya juga terdapat buah-buahan, serta pohon-pohon kurma dan delima,', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 69, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 70, 'فِيهِنَّ خَيْرَٰتٌ حِسَانٌ', 'فِيهِنَّ خَيْرَاتٌ حِسَانٌ', NULL, 'In them are good and beautiful women -', 'Dalam kedua-dua Syurga itu juga terdapat (teman-teman) yang baik akhlaknya, lagi cantik parasnya;', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 71, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 72, 'حُورٌ مَّقْصُورَٰتٌ فِى ٱلْخِيَامِ', 'حُورٌ مَّقْصُورَاتٌ فِي الْخِيَامِ', NULL, 'Fair ones reserved in pavilions -', 'Ia itu bidadari-bidadari, yang hanya tinggal tetap di tempat tinggal masing-masing;', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 73, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 74, 'لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 'لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَانٌّ', NULL, 'Untouched before them by man or jinnī -', '(Bidadari-bidadari itu) tidak pernah disentuh sebelum mereka oleh manusia dan tidak juga oleh jin;', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 75, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny? -', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 76, 'مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِىٍّ حِسَانٍ', 'مُتَّكِئِينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِيٍّ حِسَانٍ', NULL, 'Reclining on green cushions and beautiful fine carpets.', 'Penduduk Syurga itu (bersenang-senang di dalamnya dengan) berbaring di atas (bantal-bantal dan) cadar-cadar yang hijau warnanya serta permaidani-permaidani yang sangat indah.', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 77, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ', NULL, 'So which of the favors of your Lord would you deny?', 'Maka yang mana satu di antara nikmat-nikmat Tuhan kamu, yang kamu hendak dustakan?', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(55, 78, 'تَبَٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 'تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلَالِ وَالْإِكْرَامِ', NULL, 'Blessed is the name of your Lord, Owner of Majesty and Honor.', 'Maha Sucilah nama Tuhanmu yang mempunyai Kebesaran dan Kemuliaan.', FALSE, NULL, NULL, 534, 27, 213, 468, FALSE, 0, NULL),
(56, 1, 'إِذَا وَقَعَتِ ٱلْوَاقِعَةُ', 'اذا وقعت الواقعة', NULL, 'When the Occurrence occurs,', 'Apabila berlaku hari kiamat itu,', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 2, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ', 'ليس لوقعتها كاذبة', NULL, 'There is, at its occurrence, no denial.', 'Tiada sesiapapun yang dapat mendustakan kejadiannya.', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 3, 'خَافِضَةٌ رَّافِعَةٌ', 'خافضة رافعة', NULL, 'It will bring down [some] and raise up [others].', 'Kejadian hari kiamat itu merendahkan (golongan yang ingkar), dan meninggikan (golongan yang taat).', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 2, NULL),
(56, 4, 'إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّا', 'اذا رجت الارض رجا', NULL, 'When the earth is shaken with convulsion', '(Ia berlaku) semasa bumi bergoncang dengan sebebar-benar goncangan.', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 4, NULL),
(56, 5, 'وَبُسَّتِ ٱلْجِبَالُ بَسًّا', 'وبست الجبال بسا', NULL, 'And the mountains are broken down, crumbling', 'Dan gunung-ganang dihancur leburkan dengan selebur-leburnya,', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 6, 'فَكَانَتْ هَبَآءً مُّنۢبَثًّا', 'فكانت هباء منبثا', NULL, 'And become dust dispersing,', 'Lalu menjadilah ia debu yang bertebaran,', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 7, 'وَكُنتُمْ أَزْوَٰجًا ثَلَـٰثَةً', 'وكنتم ازواجا ثلاثة', NULL, 'And you become [of] three kinds:', 'Dan kamu pula menjadi tiga puak (yang berlainan keadaannya);', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 8, 'فَأَصْحَـٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 'فاصحاب الميمنة ما اصحاب الميمنة', NULL, 'Then the companions of the right - what are the companions of the right?', 'Iaitu puak pihak kanan; alangkah bahagianya keadaan puak pihak kanan itu?', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 5, NULL),
(56, 9, 'وَأَصْحَـٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 'واصحاب المشامة ما اصحاب المشامة', NULL, 'And the companions of the left - what are companions of the left?', 'Dan puak pihak kiri; - alangkah seksanya keadaan puak pihak kiri itu?', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 5, NULL),
(56, 10, 'وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ', 'والسابقون السابقون', NULL, 'And the forerunners, the forerunners -', 'Dan (puak yang ketiga pula ialah) orang-orang yang telah mendahului (dalam mengerjakan kebaikan di dunia), - yang akan mendahului (mencapai balasan yang sebaik-baiknya di akhirat kelak);', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 2, NULL),
(56, 11, 'أُو۟لَـٰٓئِكَ ٱلْمُقَرَّبُونَ', 'اولئك المقربون', NULL, 'Those are the ones brought near [to Allāh]', 'Mereka itulah orang-orang yang didampingkan (di sisi Allah),', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 2, NULL),
(56, 12, 'فِى جَنَّـٰتِ ٱلنَّعِيمِ', 'في جنات النعيم', NULL, 'In the Gardens of Pleasure,', '(Tinggal menetap) di dalam Syurga-syurga yang penuh nikmat.', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 13, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 'ثلة من الاولين', NULL, 'A [large] company of the former peoples', '(Di antaranya) sekumpulan besar dari umat-umat manusia yang terdahulu;', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 14, 'وَقَلِيلٌ مِّنَ ٱلْـَٔاخِرِينَ', 'وقليل من الاخرين', NULL, 'And a few of the later peoples,', 'Dan sebilangan kecil dari orang-orang yang datang kemudian.', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 15, 'عَلَىٰ سُرُرٍ مَّوْضُونَةٍ', 'على سرر موضونة', NULL, 'On thrones woven [with ornament],', '(Mereka duduk di dalam Syurga itu) di atas takhta-takhta kebesaran yang bertatahkan permata;', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 16, 'مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَـٰبِلِينَ', 'متكئين عليها متقابلين', NULL, 'Reclining on them, facing each other.', 'Sambil berbaring di atasnya dengan berhadap-hadapan.', FALSE, NULL, NULL, 534, 27, 214, 469, FALSE, 3, NULL),
(56, 17, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ', 'يطوف عليهم ولدان مخلدون', NULL, 'There will circulate among them young boys made eternal', 'Mereka dilayani oleh anak-anak muda lelaki yang tetap kekal (dalam keadaan mudanya), yang sentiasa beredar di sekitar mereka, -', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 4, NULL),
(56, 18, 'بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ', 'باكواب واباريق وكاس من معين', NULL, 'With vessels, pitchers and a cup [of wine] from a flowing spring -', 'Dengan membawa piala-piala minuman dan tekoh-tekoh serta piala atau gelas yang berisi arak (yang diambil) dari sungainya yang mengalir.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 5, NULL),
(56, 19, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ', 'لا يصدعون عنها ولا ينزفون', NULL, 'No headache will they have therefrom, nor will they be intoxicated -', 'Mereka tidak merasa pening kepala dan tidak pula mabuk dengan sebab menikmatinya.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 5, NULL),
(56, 20, 'وَفَـٰكِهَةٍ مِّمَّا يَتَخَيَّرُونَ', 'وفاكهة مما يتخيرون', NULL, 'And fruit of what they select', 'Dan juga (dibawakan kepada mereka) buah-buahan dari jenis-jenis yang mereka pilih,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 3, NULL),
(56, 21, 'وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ', 'وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ', NULL, 'And the meat of fowl, from whatever they desire.', 'Serta daging burung dari jenis-jenis yang mereka ingini.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(56, 22, 'وَحُورٌ عِينٌ', 'وَحُورٌ عِينٌ', NULL, 'And [for them are] fair women with large, [beautiful] eyes,', 'Dan (mereka dilayani) bidadari-bidadari yang cantik parasnya,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 23, 'كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ', 'كَأَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ', NULL, 'The likenesses of pearls well-protected,', 'Seperti mutiara yang tersimpan dengan sebaik-baiknya.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 24, 'جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'جَزَاءً بِمَا كَانُوا يَعْمَلُونَ', NULL, 'As reward for what they used to do.', '(Semuanya itu) sebagai balasan bagi (amal-amal baik) yang mereka telah kerjakan.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 25, 'لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا', 'لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا', NULL, 'They will not hear therein ill speech or commission of sin -', 'Mereka tidak akan mendengar dalam Syurga itu perkataan yang sia-sia dan tiada pula sesuatu yang menyebabkan dosa; -', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 26, 'إِلَّا قِيلًا سَلَٰمًا سَلَٰمًا', 'إِلَّا قِيلًا سَلَامًا سَلَامًا', NULL, 'Only a saying [of] peace, peace.', 'Mereka hanya mendengar ucapan: “Selamat! Selamat!” (dari satu kepada yang lain).', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 27, 'وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ', 'وَأَصْحَابُ الْيَمِينِ مَا أَصْحَابُ الْيَمِينِ', NULL, 'The companions of the right - what are the companions of the right?', 'Dan puak kanan, - alangkah bahagianya keadaan puak kanan itu?', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 28, 'فِى سِدْرٍ مَّخْضُودٍ', 'فِي سِدْرٍ مَّخْضُودٍ', NULL, '[They will be] among lote trees with thorns removed', 'Mereka bersenang-lenang di antara pohon-pohon bidara yang tidak berduri.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 29, 'وَطَلْحٍ مَّنضُودٍ', 'وَطَلْحٍ مَّنضُودٍ', NULL, 'And [banana] trees layered [with fruit]', 'Dan pokok-pokok pisang yang tersusun rapi buahnya,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 30, 'وَظِلٍّ مَّمْدُودٍ', 'وَظِلٍّ مَّمْدُودٍ', NULL, 'And shade extended', 'Dan naungan yang tetap terbentang,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 31, 'وَمَآءٍ مَّسْكُوبٍ', 'وَمَاءٍ مَّسْكُوبٍ', NULL, 'And water poured out', 'Dan air yang sentiasa mengalir,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 32, 'وَفَٰكِهَةٍ كَثِيرَةٍ', 'وَفَاكِهَةٍ كَثِيرَةٍ', NULL, 'And fruit, abundant [and varied],', 'Serta buah-buahan yang banyak,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 33, 'لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ', 'لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ', NULL, 'Neither limited [to season] nor forbidden,', 'Yang tidak putus-putus dan tidak pula terlarang mendapatnya,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 34, 'وَفُرُشٍ مَّرْفُوعَةٍ', 'وَفُرُشٍ مَّرْفُوعَةٍ', NULL, 'And [upon] beds raised high.', 'Dan tempat-tempat tidur yang tertinggi keadaannya.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 35, 'إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءً', 'إِنَّا أَنشَأْنَاهُنَّ إِنشَاءً', NULL, 'Indeed, We have produced them [i.e., the women of Paradise] in a [new] creation', 'Sesungguhnya Kami telah menciptakan isteri-isteri mereka dengan ciptaan istimewa,', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 36, 'فَجَعَلْنَٰهُنَّ أَبْكَارًا', 'فَجَعَلْنَاهُنَّ أَبْكَارًا', NULL, 'And made them virgins,', 'Serta Kami jadikan mereka sentiasa dara (yang tidak pernah disentuh),', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 37, 'عُرُبًا أَتْرَابًا', 'عُرُبًا أَتْرَابًا', NULL, 'Devoted [to their husbands] and of equal age,', 'Yang tetap mencintai jodohnya, serta yang sebaya umurnya.', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 38, 'لِّأَصْحَٰبِ ٱلْيَمِينِ', 'لِّأَصْحَابِ الْيَمِينِ', NULL, 'For the companions of the right [who are]', '(Semuanya itu disediakan) bagi puak kanan;', FALSE, NULL, NULL, 535, 27, 214, 469, FALSE, 0, NULL),
(56, 39, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 'ثُلَّةٌ مِّنَ الْأَوَّلِينَ', NULL, 'A company of the former peoples', 'Iaitu sebilangan besar dari orang-orang yang terdahulu,', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 40, 'وَثُلَّةٌ مِّنَ ٱلْـَٔاخِرِينَ', 'وَثُلَّةٌ مِّنَ الْآخِرِينَ', NULL, 'And a company of the later peoples.', 'Dan sebilangan besar dari orang-orang yang datang kemudian.', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 41, 'وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ', 'وَأَصْحَابُ الشِّمَالِ مَا أَصْحَابُ الشِّمَالِ', NULL, 'And the companions of the left - what are the companions of the left?', 'Dan puak kiri, - alangkah seksanya keadaan puak kiri itu?', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 42, 'فِى سَمُومٍ وَحَمِيمٍ', 'فِي سَمُومٍ وَحَمِيمٍ', NULL, '[They will be] in scorching fire and scalding water', 'Mereka diseksa dalam angin yang membakar dan air yang menggelegak', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 43, 'وَظِلٍّ مِّن يَحْمُومٍ', 'وَظِلٍّ مِّن يَحْمُومٍ', NULL, 'And a shade of black smoke,', 'Serta naungan dari asap hitam,', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 44, 'لَّا بَارِدٍ وَلَا كَرِيمٍ', 'لَّا بَارِدٍ وَلَا كَرِيمٍ', NULL, 'Neither cool nor beneficial.', 'Yang tidak sejuk, dan tidak pula memberi kesenangan.', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 45, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', 'إِنَّهُمْ كَانُوا قَبْلَ ذَٰلِكَ مُتْرَفِينَ', NULL, 'Indeed they were, before that, indulging in affluence,', 'Sesungguhnya mereka sebelum itu dilalaikan oleh kemewahan (dunia, dari mengingati hukum Tuhan).', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 46, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', 'وَكَانُوا يُصِرُّونَ عَلَى الْحِنثِ الْعَظِيمِ', NULL, 'And they used to persist in the great violation,', 'Dan mereka pula sentiasa melakukan dosa yang besar,', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 47, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'وَكَانُوا يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ', NULL, 'And they used to say, "When we die and become dust and bones, are we indeed to be resurrected?', 'Dan juga mereka selalu berkata: “Adakah sesudah kita mati serta menjadi tanah dan tulang, betulkah kita akan dibangkitkan hidup semula?', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 48, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'أَوَآبَاؤُنَا الْأَوَّلُونَ', NULL, 'And our forefathers [as well]?"', '“Dan adakah juga datuk nenek kita yang telah lalu, (akan dibangkitkan hidup semula)?”', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 49, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْـَٔاخِرِينَ', 'قُلْ إِنَّ الْأَوَّلِينَ وَالْآخِرِينَ', NULL, 'Say, [O Muḥammad], "Indeed, the former and later peoples', 'Katakanlah (kepada mereka): “Sesungguhnya orang-orang yang telah lalu dan orang-orang yang terkemudian,', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 50, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍ مَّعْلُومٍ', 'لَمَجْمُوعُونَ إِلَىٰ مِيقَاتِ يَوْمٍ مَّعْلُومٍ', NULL, 'Are to be gathered together for the appointment of a known Day."', '“Tetap akan dihimpunkan pada masa yang ditentukan - pada hari kiamat yang termaklum.', FALSE, NULL, NULL, 535, 27, 214, 470, FALSE, 0, NULL),
(56, 51, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', 'ثُمَّ إِنَّكُمْ أَيُّهَا الضَّالُّونَ الْمُكَذِّبُونَ', NULL, 'Then indeed you, O those astray [who are] deniers,', '“Kemudian, sesungguhnya kamu wahai orang-orang yang sesat yang mendustakan (kedatangan hari kiamat),', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 52, 'لَـَٔاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ', 'لَآكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ', NULL, 'Will be eating from trees of zaqqūm', 'Tetap akan memakan (pada hari itu) dari sebatang pokok, iaitu pokok zaqqum,', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 53, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'فَمَالِئُونَ مِنْهَا الْبُطُونَ', NULL, 'And filling with it your bellies', '“Maka kamu akan memenuhi perut kamu dari pokok (yang pahit buahnya) itu,', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 54, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', 'فَشَارِبُونَ عَلَيْهِ مِنَ الْحَمِيمِ', NULL, 'And drinking on top of it from scalding water', '“Selepas itu kamu akan meminum pula dari air panas yang menggelegak,', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 55, 'فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ', 'فَشَارِبُونَ شُرْبَ الْهِيمِ', NULL, 'And will drink as the drinking of thirsty camels.', '“Iaitu kamu akan minum seperti unta yang berpenyakit sentiasa dahaga dan tidak puas-puas”.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 56, 'هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', 'هَٰذَا نُزُلُهُمْ يَوْمَ الدِّينِ', NULL, 'That is their accommodation on the Day of Recompense.', 'Inilah (jenis-jenis azab) yang disediakan untuk menyambut mereka pada hari Pembalasan itu.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 57, 'نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ', 'نَحْنُ خَلَقْنَاكُمْ فَلَوْلَا تُصَدِّقُونَ', NULL, 'We have created you, so why do you not believe?', 'Kamilah yang telah menciptakan kamu (dari tiada kepada ada - wahai golongan yang ingkar), maka ada baiknya kalau kamu percaya (akan kebangkitan kamu hidup semula pada hari kiamat).', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 58, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', 'أَفَرَأَيْتُم مَّا تُمْنُونَ', NULL, 'Have you seen that which you emit?', '(Mengapa kamu masih berdegil?) Tidakkah kamu memikirkan keadaan air mani yang kamu pancarkan (ke dalam rahim)?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 59, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ', 'أَأَنتُمْ تَخْلُقُونَهُ أَمْ نَحْنُ الْخَالِقُونَ', NULL, 'Is it you who creates it, or are We the Creator?', 'Adakah kamu yang menciptakannya atau Kami yang menciptakannya?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 60, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ الْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', NULL, 'We have decreed death among you, and We are not to be outdone', 'Kamilah yang menentukan (dan menetapkan masa) kematian (tiap-tiap seorang) di antara kamu, dan Kami tidak sekali-kali dapat dikalahkan atau dilemahkan;', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 61, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', 'عَلَىٰ أَن نُّبَدِّلَ أَمْثَالَكُمْ وَنُنشِئَكُمْ فِي مَا لَا تَعْلَمُونَ', NULL, 'In that We will change your likenesses and produce you in that [form] which you do not know.', '(Bahkan Kami berkuasa) menggantikan (kamu dengan) orang-orang yang serupa kamu (tetapi tidak seperti bawaan kamu), dan berkuasa menciptakan kamu dalam bentuk kejadian yang kamu tidak mengetahuinya.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 62, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', 'وَلَقَدْ عَلِمْتُمُ النَّشْأَةَ الْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', NULL, 'And you have already known the first creation, so will you not remember?', 'Dan demi sesungguhnya, kamu telah sedia mengetahui tentang ciptaan diri kamu kali pertama, maka ada baiknya kalau kamu mengambil ingatan (bahawa Allah yang telah menciptakan kamu dari tiada kepada ada, berkuasa membangkitkan kamu hidup semula pada hari akhirat kelak).', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 63, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', 'أَفَرَأَيْتُم مَّا تَحْرُثُونَ', NULL, 'And have you seen that [seed] which you sow?', 'Maka (mengapa kamu masih berdegil?) Tidakkah kamu melihat apa yang kamu tanam?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 64, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', 'أَأَنتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ', NULL, 'Is it you who makes it grow, or are We the grower?', 'Kamukah yang menumbuhkannya atau Kami yang menumbuhkannya?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 65, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًا فَظَلْتُمْ تَفَكَّهُونَ', 'لَوْ نَشَاءُ لَجَعَلْنَاهُ حُطَامًا فَظَلْتُمْ تَفَكَّهُونَ', NULL, 'If We willed, We could make it [dry] debris, and you would remain in wonder,', 'Kalau Kami kehendaki, sudah tentu Kami akan jadikan tanaman itu kering hancur (sebelum ia berbuah), maka dengan itu tinggallah kamu dalam keadaan hairan dan menyesal,', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 66, 'إِنَّا لَمُغْرَمُونَ', 'إِنَّا لَمُغْرَمُونَ', NULL, '[Saying], "Indeed, we are [now] in debt;', '(Sambil berkata): “Sesungguhnya kami menanggung kerugian.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 67, 'بَلْ نَحْنُ مَحْرُومُونَ', 'بَلْ نَحْنُ مَحْرُومُونَ', NULL, 'Rather, we have been deprived."', '“Bahkan kami hampa (dari mendapat sebarang hasil)”', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 68, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', 'أَفَرَأَيْتُمُ الْمَاءَ الَّذِي تَشْرَبُونَ', NULL, 'And have you seen the water that you drink?', 'Selain dari itu, tidakkah kamu melihat air yang kamu minum?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 69, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', 'أَأَنتُمْ أَنزَلْتُمُوهُ مِنَ الْمُزْنِ أَمْ نَحْنُ الْمُنزِلُونَ', NULL, 'Is it you who brought it down from the clouds, or is it We who bring it down?', 'Kamukah yang menurunkannya dari awan (sebagai hujan), atau Kami yang menurunkannya?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 70, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ', 'لَوْ نَشَاءُ جَعَلْنَاهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ', NULL, 'If We willed, We could make it bitter, so why are you not grateful?', 'Kalau Kami kehendaki, Kami akan jadikan dia masin, maka ada baiknya kalau kamu bersyukur.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 71, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', 'أَفَرَأَيْتُمُ النَّارَ الَّتِي تُورُونَ', NULL, 'And have you seen the fire that you ignite?', 'Akhirnya, tidakkah kamu melihat api yang kamu nyalakan (dengan cara digesek)?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 72, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', 'أَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَا أَمْ نَحْنُ الْمُنشِئُونَ', NULL, 'Is it you who produced its tree, or are We the producer?', 'Kamukah yang menumbuhkan pokok kayunya, atau Kami yang menumbuhkannya?', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 73, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةً وَمَتَٰعًا لِّلْمُقْوِينَ', 'نَحْنُ جَعَلْنَاهَا تَذْكِرَةً وَمَتَاعًا لِّلْمُقْوِينَ', NULL, 'We have made it a reminder and provision for the travelers,', 'Kami jadikan api (yang tercetus dari kayu basah) itu sebagai peringatan (bagi orang-orang yang lalaikan kebenaran hari akhirat) dan sebagai benda yang memberi kesenangan kepada orang-orang musafir.', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 74, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ', NULL, 'So exalt the name of your Lord, the Most Great.', 'Oleh yang demikian - (wahai orang yang lalai) - bertasbihlah dengan memuji nama Tuhanmu Yang Maha Besar (sebagai bersyukur akan nikmat-nikmatNya itu).', FALSE, NULL, NULL, 536, 27, 214, 470, FALSE, 0, NULL),
(56, 75, 'فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', 'فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ', NULL, 'Then I swear by the setting of the stars,', 'Maka Aku bersumpah: Demi tempat-tempat dan masa-masa turunnya bahagian-bahagian Al-Quran, -', FALSE, NULL, NULL, 536, 27, 215, 471, FALSE, 0, NULL),
(56, 76, 'وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ', 'وَإِنَّهُ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ', NULL, 'And indeed, it is an oath - if you could know - [most] great.', 'Dan sebenarnya sumpah itu adalah sumpah yang besar, kalaulah kamu mengetahuinya, -', FALSE, NULL, NULL, 536, 27, 215, 471, FALSE, 0, NULL),
(56, 77, 'إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ', 'إِنَّهُ لَقُرْآنٌ كَرِيمٌ', NULL, 'Indeed, it is a noble Qur’ān.', 'Bahawa sesungguhnya (yang dibacakan kepada kamu) itu ialah Al-Quran yang mulia, (yang sentiasa memberi ajaran dan pimpinan),', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 78, 'فِى كِتَٰبٍ مَّكْنُونٍ', 'فِي كِتَابٍ مَّكْنُونٍ', NULL, 'In a Register well-protected;.', 'Yang tersimpan dalam Kitab yang cukup terpelihara,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 79, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', 'لَّا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ', NULL, 'None touch it except the purified [i.e., the angels].', 'Yang tidak disentuh melainkan oleh makhluk-makhluk yang diakui bersih suci;', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 80, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'تَنزِيلٌ مِّن رَّبِّ الْعَالَمِينَ', NULL, '[It is] a revelation from the Lord of the worlds.', 'Al-Quran itu diturunkan dari Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 81, 'أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', 'أَفَبِهَٰذَا الْحَدِيثِ أَنتُم مُّدْهِنُونَ', NULL, 'Then is it to this statement that you are indifferent', 'Patutkah kamu (wahai golongan yang kufur ingkar) bersikap sambilewa terhadap keterangan-keterangan Al-Quran ini?', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 82, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', NULL, 'And make [the thanks for] your provision that you deny [the Provider]?', 'Dan kamu jadikan sikap kamu mendustakannya (sebagai ganti) bahagian dan nasib kamu (menerima dan bersyukur akan ajarannya)?', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 83, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', 'فَلَوْلَا إِذَا بَلَغَتِ الْحُلْقُومَ', NULL, 'Then why, when it [i.e., the soul at death] reaches the throat', 'Maka alangkah eloknya kalau semasa (roh seseorang dari kamu yang hampir mati) sampai ke kerongkongnya, -', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 84, 'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ', 'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ', NULL, 'And you are at that time looking on -', 'Sedang kamu pada masa itu (berada di sekelilingnya) menyaksikan keadaannya, -', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 85, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', NULL, 'And We [i.e., Our angels] are nearer to him than you, but you do not see -', 'Dan Kami lebih dekat kepadanya daripada kamu, tetapi kamu tidak melihat,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 86, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 'فَلَوْلَا إِن كُنتُمْ غَيْرَ مَدِينِينَ', NULL, 'Then why do you not, if you are not to be recompensed,', 'Maka bukankah elok kalau kamu orang-orang yang tidak dikuasai (dan tidak tunduk kepada kekuasaan Kami), -', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 87, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ', 'تَرْجِعُونَهَا إِن كُنتُمْ صَادِقِينَ', NULL, 'Bring it back, if you should be truthful?', 'Kamu kembalikan roh itu (kepada keadaan sebelumnya) jika betul kamu orang-orang yang benar?', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 88, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', 'فَأَمَّا إِن كَانَ مِنَ الْمُقَرَّبِينَ', NULL, 'And if he [i.e., the deceased] was of those brought near [to Allāh],', 'Kesudahannya: jika ia (yang mati itu) dari orang-orang “Muqarrabiin”,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 89, 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ', 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ', NULL, 'Then [for him is] rest and bounty and a garden of pleasure.', 'Maka (ia akan beroleh) rehat kesenangan, dan rahmat kesegaran, serta Syurga kenikmatan.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 90, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'وَأَمَّا إِن كَانَ مِنْ أَصْحَابِ الْيَمِينِ', NULL, 'And if he was of the companions of the right,', 'Dan jika ia dari puak kanan,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 91, 'فَسَلَٰمٌ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'فَسَلَامٌ لَّكَ مِنْ أَصْحَابِ الْيَمِينِ', NULL, 'Then [the angels will say], "Peace for you; [you are] from the companions of the right."', 'Maka (akan dikatakan kepadanya): “Selamat sejahtera kepadamu, (kerana engkau) dari puak kanan”.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 92, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', 'وَأَمَّا إِن كَانَ مِنَ الْمُكَذِّبِينَ الضَّالِّينَ', NULL, 'But if he was of the deniers [who were] astray,', 'Dan jika ia dari (puak kiri) yang mendustakan (Rasulnya), lagi sesat,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 93, 'فَنُزُلٌ مِّنْ حَمِيمٍ', 'فَنُزُلٌ مِّنْ حَمِيمٍ', NULL, 'Then [for him is] accommodation of scalding water', 'Maka sambutan yang disediakan baginya adalah dari air panas yang menggelegak,', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 94, 'وَتَصْلِيَةُ جَحِيمٍ', 'وَتَصْلِيَةُ جَحِيمٍ', NULL, 'And burning in Hellfire.', 'Serta bakaran api neraka.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 95, 'إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', 'إِنَّ هَٰذَا لَهُوَ حَقُّ الْيَقِينِ', NULL, 'Indeed, this is the true certainty,', 'Sesungguhnya (segala yang disebutkan) itu adalah kebenaran yang diyakini.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(56, 96, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ', NULL, 'So exalt the name of your Lord, the Most Great.', 'Oleh itu, bertasbihlah dengan memuji nama Tuhanmu Yang Maha Besar.', FALSE, NULL, NULL, 537, 27, 215, 471, FALSE, 0, NULL),
(57, 1, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'سبح لله ما في السماوات والارض وهو العزيز الحكيم', NULL, 'Whatever is in the heavens and earth exalts Allāh, and He is the Exalted in Might, the Wise.', 'Segala yang ada di langit dan di bumi tetap mengucap tasbih kepada Allah; dan Dia lah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 537, 27, 215, 472, FALSE, 9, NULL),
(57, 2, 'لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'له ملك السماوات والارض يحيي ويميت وهو على كل شيء قدير', NULL, 'His is the dominion of the heavens and earth. He gives life and causes death, and He is over all things competent.', 'Dia lah sahaja yang menguasai dan memiliki langit dan bumi; Ia menghidupkan dan mematikan; dan Ia Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 537, 27, 215, 472, FALSE, 11, NULL),
(57, 3, 'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'هو الاول والاخر والظاهر والباطن وهو بكل شيء عليم', NULL, 'He is the First and the Last, the Ascendant and the Intimate, and He is, of all things, Knowing.', 'Dia lah Yang Awal dan Yang Akhir; dan Yang Zahir serta Yang Batin; dan Dia lah Yang Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 537, 27, 215, 472, FALSE, 9, NULL),
(57, 4, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'هو الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير', NULL, 'It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allāh, of what you do, is Seeing.', 'Dia lah yang telah menciptakan langit dan bumi dalam enam masa, kemudian Ia bersemayam di atas Arasy; Ia mengetahui apa yang masuk ke bumi serta apa yang keluar daripadanya; dan apa yang diturunkan dari langit serta apa yang naik padanya. Dan Ia tetap bersama-sama kamu di mana sahaja kamu berada, dan Allah Maha Melihat akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 36, NULL),
(57, 5, 'لَّهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'له ملك السماوات والارض والى الله ترجع الامور', NULL, 'His is the dominion of the heavens and earth. And to Allāh are returned [all] matters.', 'Dia lah sahaja yang menguasai dan memiliki langit dan bumi; dan kepada Allah jualah dikembalikan segala urusan.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 8, NULL),
(57, 6, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'يولج الليل في النهار ويولج النهار في الليل وهو عليم بذات الصدور', NULL, 'He causes the night to enter the day and causes the day to enter the night, and He is Knowing of that within the breasts.', 'Dia lah yang memasukkan waktu malam ke dalam waktu siang, dan memasukkan waktu siang ke dalam waktu malam (silih berganti); dan Dia lah yang Maha Mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 12, NULL),
(57, 7, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', 'امنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين امنوا منكم وانفقوا لهم اجر كبير', NULL, 'Believe in Allāh and His Messenger and spend out of that in which He has made you successive inheritors. For those who have believed among you and spent, there will be a great reward.', 'Berimanlah kamu kepada Allah dan RasulNya, dan belanjakanlah (pada jalan kebajikan) sebahagian dari harta benda (pemberian Allah) yang dijadikannya kamu menguasainya sebagai wakil. Maka orang-orang yang beriman di antara kamu serta mereka membelanjakan (sebahagian dari harta itu pada jalan Allah); mereka tetap beroleh pahala yang besar.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 15, NULL),
(57, 8, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَـٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثاقكم ان كنتم مؤمنين', NULL, 'And why do you not believe in Allāh while the Messenger invites you to believe in your Lord and He has taken your covenant, if you should [truly] be believers?', 'Dan mengapa kamu tidak beriman kepada Allah? Sedang Rasulullah mengajak kamu untuk beriman kepada Tuhan kamu, dan Allah telah mengambil janji setia dari kamu (untuk beriman); jika kamu hendak beriman (maka telah jelaslah dalil-dalilnya).', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 15, NULL),
(57, 9, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', 'هو الذي ينزل على عبده ايات بينات ليخرجكم من الظلمات الى النور وان الله بكم لرءوف رحيم', NULL, 'It is He who sends down upon His Servant [Muḥammad (ﷺ)] verses of clear evidence that He may bring you out from darknesses into the light. And indeed, Allāh is to you Kind and Merciful.', 'Dia lah yang menurunkan kepada hambaNya (Nabi Muhammad) keterangan-keterangan Al-Quran yang terang nyata, kerana Ia hendak mengeluarkan kamu dari gelap-gelita (kekufuran) kepada cahaya (iman) yang terang-benderang. Dan (ingatlah) sesungguhnya Allah Maha Belas, lagi Maha Mengasihani, terhadap kamu.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 17, NULL),
(57, 10, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَـٰتَلَ ۚ أُو۟لَـٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَـٰتَلُوا۟ ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'وما لكم الا تنفقوا في سبيل الله ولله ميراث السماوات والارض لا يستوي منكم من انفق من قبل الفتح وقاتل اولئك اعظم درجة من الذين انفقوا من بعد وقاتلوا وكلا وعد الله الحسنى والله بما تعملون خبير', NULL, 'And why do you not spend in the cause of Allāh while to Allāh belongs the heritage of the heavens and the earth? Not equal among you are those who spent before the conquest [of Makkah] and fought [and those who did so after it]. Those are greater in degree than they who spent afterwards and fought. But to all Allāh has promised the best [reward]. And Allāh, of what you do, is Aware.', 'Dan mengapa kamu tidak membelanjakan harta benda kamu pada jalan Allah? - Padahal Allah jualah yang mewarisi langit dan bumi (serta segala isinya). Tidaklah sama di antara kamu, orang-orang yang membelanjakan hartanya serta turut berperang sebelum kemenangan (Nabi menguasai Makkah). Mereka itu lebih besar darjatnya daripada orang-orang yang membelanjakan hartanya serta turut berperang sesudah itu. Dan tiap-tiap satu puak dari keduanya, Allah janjikan (balasan) yang sebaik-baiknya. Dan (ingatlah), Allah Maha Mendalam PengetahuanNya akan apa yang kamu kerjakan.', FALSE, NULL, NULL, 538, 27, 215, 472, FALSE, 37, NULL),
(57, 11, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', 'من ذا الذي يقرض الله قرضا حسنا فيضاعفه له وله اجر كريم', NULL, 'Who is it that would loan Allāh a goodly loan so He will multiply it for him and he will have a noble reward?', 'Siapakah orangnya yang mahu memberikan pinjaman kepada Allah, sebagai pinjaman yang baik (ikhlas) supaya Allah melipat-gandakan balasannya? Dan (selain itu) ia akan beroleh pahala yang besar!', FALSE, NULL, NULL, 538, 27, 215, 473, FALSE, 12, NULL),
(57, 12, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يوم ترى المؤمنين والمؤمنات يسعى نورهم بين ايديهم وبايمانهم بشراكم اليوم جنات تجري من تحتها الانهار خالدين فيها ذلك هو الفوز العظيم', NULL, 'On the Day you see the believing men and believing women, their light proceeding before them and on their right, [it will be said], "Your good tidings today are [of] gardens beneath which rivers flow, wherein you will abide eternally." That is what is the great attainment.', '(Ingatlah) ketika engkau melihat (pada hari kiamat): orang-orang yang beriman, lelaki dan perempuan, cahaya (iman dan amal soleh) mereka bergerak cepat di hadapan mereka dan di sebelah kanan mereka (semasa mereka berjalan, serta dikatakan kepada mereka): “Berita yang mengembirakan kamu pada hari ini, (kamu akan beroleh) Syurga yang mengalir di bawahnya beberapa sungai, kekal kamu di dalamnya; yang demikian itu adalah kemenangan yang besar”.', FALSE, NULL, NULL, 539, 27, 215, 473, FALSE, 22, NULL),
(57, 13, 'يَوْمَ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', 'يوم يقول المنافقون والمنافقات للذين امنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظاهره من قبله العذاب', NULL, 'On the [same] Day the hypocrite men and hypocrite women will say to those who believed, "Wait for us that we may acquire some of your light." It will be said, "Go back behind you and seek light." And a wall will be placed between them with a door, its interior containing mercy, but on the outside of it is torment.', '(Ingatlah) semasa orang-orang munafik, lelaki dan perempuan (yang sedang meraba-raba dalam gelap-gelita pada hari kiamat), berkata kepada orang-orang yang beriman: “Tunggulah kami, biarlah kami mengambil sedikit dari cahaya kamu”. (Lalu) dikatakan (kepada mereka secara mengejek-ejek): “Baliklah kamu ke belakang, kemudian carilah cahaya (di sana)”, serta diadakanlah di antara mereka (yang beriman dan yang munafik itu) sebuah tembok yang mempunyai pintu, di sebelah dalamnya mengandungi rahmat (Syurga dan nikmat), dan di sebelah luarnya, dari situ terdapat (neraka) dan azab seksa.', FALSE, NULL, NULL, 539, 27, 215, 473, FALSE, 27, NULL),
(57, 14, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'ينادونهم الم نكن معكم قالوا بلى ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتى جاء امر الله وغركم بالله الغرور', NULL, 'They [i.e., the hypocrites] will call to them [i.e., the believers], "Were we not with you?" They will say, "Yes, but you afflicted yourselves and awaited [misfortune for us] and doubted, and wishful thinking deluded you until there came the command of Allāh. And the Deceiver [i.e., Satan] deceived you concerning Allāh.', '(Pada saat itu) mereka (yang munafik) menyeru orang-orang yang beriman (sambil berkata): “Bukankah kami bercampur gaul dengan kamu (di dunia dahulu)?” Orang-orang yang beriman menjawab: “Benar! Akan tetapi kamu telah membinasakan diri kamu (dengan perbuatan munafik) dan kamu telah menunggu-nunggu (kebinasaan umat Islam), dan kamu pula ragu-ragu (terhadap perkara-perkara ugama) serta kamu diperdayakan oleh angan-angan kosong (untuk mencapai maksud kamu), sehinggalah datangnya (maut) yang ditetapkan oleh Allah (kepada kamu). Dan (selain itu), kamu pula diperdayakan oleh bisikan Syaitan dengan (pengampunan) Allah (semata-mata dan melupakan azabNya).', FALSE, NULL, NULL, 539, 27, 215, 473, FALSE, 20, NULL),
(57, 15, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'فاليوم لا يؤخذ منكم فدية ولا من الذين كفروا ماواكم النار هي مولاكم وبئس المصير', NULL, 'So today no ransom will be taken from you or from those who disbelieved. Your refuge is the Fire. It is most worthy of you, and wretched is the destination."', '“Oleh itu, pada hari ini tidak diterima penebus diri dari kamu, dan tidak juga dari orang-orang kafir. Tempat tinggal kamu ialah neraka, nerakalah sahaja penolong kamu, dan itulah seburuk-buruk tempat kesudahan kamu!”', FALSE, NULL, NULL, 539, 27, 215, 473, FALSE, 15, NULL),
(57, 16, '۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', 'الم يان للذين امنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتاب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فاسقون', NULL, 'Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allāh and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient.', 'Belum sampaikah lagi masanya bagi orang-orang yang beriman, untuk khusyuk hati mereka mematuhi peringatan dan pengajaran Allah serta mematuhi kebenaran (Al-Quran) yang diturunkan (kepada mereka)? Dan janganlah pula mereka menjadi seperti orang-orang yang telah diberikan Kitab sebelum mereka, setelah orang-orang itu melalui masa yang lanjut maka hati mereka menjadi keras, dan banyak di antaranya orang-orang yang fasik - derhaka.', FALSE, NULL, NULL, 539, 27, 216, 473, FALSE, 28, NULL),
(57, 17, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'اعلموا ان الله يحيي الارض بعد موتها قد بينا لكم الايات لعلكم تعقلون', NULL, 'Know that Allāh gives life to the earth after its lifelessness. We have made clear to you the signs; perhaps you will understand.', 'Ketahuilah kamu, bahawa Allah menghidupkan bumi sesudah matinya; sesungguhnya Kami telah menjelaskan kepada kamu keterangan-keterangan dan bukti, supaya kamu memahaminya.', FALSE, NULL, NULL, 539, 27, 216, 473, FALSE, 13, NULL),
(57, 18, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَـٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', 'ان المصدقين والمصدقات واقرضوا الله قرضا حسنا يضاعف لهم ولهم اجر كريم', NULL, 'Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allāh a goodly loan - it will be multiplied for them, and they will have a noble reward.', 'Sesungguhnya orang-orang lelaki yang bersedekah dan orang-orang perempuan yang bersedekah, serta mereka memberikan pinjaman kepada Allah, sebagai pinjaman yang baik (ikhlas), akan digandakan balasannya (dengan berganda-ganda banyaknya), dan mereka pula akan beroleh pahala yang mulia.', FALSE, NULL, NULL, 539, 27, 216, 473, FALSE, 12, NULL),
(57, 19, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', 'والذين امنوا بالله ورسله اولئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم', NULL, 'And those who have believed in Allāh and His messengers - those are [in the ranks of] the supporters of truth and the martyrs, with their Lord. For them is their reward and their light. But those who have disbelieved and denied Our verses - those are the companions of Hellfire.', 'Dan orang-orang yang beriman kepada Allah dan Rasul-rasulNya, merekalah pada sisi (hukum) Tuhan mereka, (orang-orang yang mempunyai kedudukan yang tinggi darjatnya) seperti orang-orang “Siddiqiin” dan orang-orang yang mati Syahid; mereka akan beroleh pahala dan cahaya orang-orang Siddiqiin dan orang-orang yang mati syahid itu; dan (sebaliknya) orang yang kufur ingkar serta mendustakan ayat-ayat keterangan Kami, merekalah ahli neraka.', FALSE, NULL, NULL, 540, 27, 216, 473, FALSE, 20, NULL),
(57, 20, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَـٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَـٰمًا ۖ وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ', 'اعلموا انما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الاموال والاولاد كمثل غيث اعجب الكفار نباته ثم يهيج فتراه مصفرا ثم يكون حطاما وفي الاخرة عذاب شديد ومغفرة من الله ورضوان وما الحياة الدنيا الا متاع الغرور', NULL, 'Know that the life of this world is but amusement and diversion and adornment and boasting to one another and competition in increase of wealth and children - like the example of a rain whose [resulting] plant growth pleases the tillers; then it dries and you see it turned yellow; then it becomes [scattered] debris. And in the Hereafter is severe punishment and forgiveness from Allāh and approval. And what is the worldly life except the enjoyment of delusion.', 'Ketahuilah bahawa (yang dikatakan) kehidupan dunia itu tidak lain hanyalah (bawaan hidup yang berupa semata-mata) permainan dan hiburan (yang melalaikan) serta perhiasan (yang mengurang), juga (bawaan hidup yang bertujuan) bermegah-megah di antara kamu (dengan kelebihan, kekuatan, dan bangsa keturunan) serta berlumba-lumba membanyakkan harta benda dan anak pinak; (semuanya itu terhad waktunya) samalah seperti hujan yang (menumbuhkan tanaman yang menghijau subur) menjadikan penanamnya suka dan tertarik hati kepada kesuburannya, kemudian tanaman itu bergerak segar (ke suatu masa yang tertentu), selepas itu engkau melihatnya berupa kuning; akhirnya ia menjadi hancur bersepai; dan (hendaklah diketahui lagi, bahawa) di akhirat ada azab yang berat (di sediakan bagi golongan yang hanya mengutamakan kehidupan dunia itu), dan (ada pula) keampunan besar serta keredaan dari Allah (disediakan bagi orang-orang yang mengutamakan akhirat). Dan (ingatlah, bahawa) kehidupan dunia ini tidak lain hanyalah kesenangan bagi orang-orang yang terpedaya.', FALSE, NULL, NULL, 540, 27, 216, 474, FALSE, 39, NULL),
(57, 21, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'سَابِقُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ', NULL, 'Race [i.e., compete] toward forgiveness from your Lord and a Garden whose width is like the width of the heavens and earth, prepared for those who believed in Allāh and His messengers. That is the bounty of Allāh which He gives to whom He wills, and Allāh is the possessor of great bounty.', 'Berlumba-lumbalah kamu (mengerjakan amal-amal yang baik) untuk mendapat keampunan dari Tuhan kamu, dan mendapat Syurga yang bidangnya seluas segala langit dan bumi, yang disediakan bagi orang-orang yang beriman kepada Allah dan Rasul-rasulNya; yang demikian ialah limpah kurnia Allah, diberikanNya kepada sesiapa yang dikehendakiNya; dan Allah sememangnya mempunyai limpah kurnia yang besar.', FALSE, NULL, NULL, 540, 27, 216, 474, FALSE, 0, NULL),
(57, 22, 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'مَا أَصَابَ مِن مُّصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنفُسِكُمْ إِلَّا فِي كِتَابٍ مِّن قَبْلِ أَن نَّبْرَأَهَا إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ', NULL, 'No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allāh, is easy -', 'Tidak ada sesuatu kesusahan (atau bala bencana) yang ditimpakan di bumi, dan tidak juga yang menimpa diri kamu, melainkan telah sedia ada di dalam Kitab (pengetahuan Kami) sebelum Kami menjadikannya; sesungguhnya mengadakan yang demikian itu adalah mudah bagi Allah.', FALSE, NULL, NULL, 540, 27, 216, 474, FALSE, 0, NULL),
(57, 23, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', 'لِّكَيْلَا تَأْسَوْا عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا بِمَا آتَاكُمْ وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', NULL, 'In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allāh does not like everyone self-deluded and boastful -', '(Kamu diberitahu tentang itu) supaya kamu tidak bersedih hati akan apa yang telah luput daripada kamu, dan tidak pula bergembira (secara sombong dan bangga) dengan apa yang diberikan kepada kamu. Dan (ingatlah), Allah tidak suka kepada tiap-tiap orang yang sombong takbur, lagi membanggakan diri.', FALSE, NULL, NULL, 540, 27, 216, 474, FALSE, 0, NULL),
(57, 24, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ', NULL, '[Those] who are stingy and enjoin upon people stinginess. And whoever turns away - then indeed, Allāh is the Free of need, the Praiseworthy.', 'Orang-orang yang bakhil dan menyuruh manusia supaya berlaku bakhil, (akan mendapat balasan yang menghina); dan sesiapa yang berpaling (dari mematuhi hukum Allah maka padahnya tertimpa atas dirinya sendiri), kerana sesungguhnya Allah, Dia lah Yang Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 540, 27, 216, 474, FALSE, 0, NULL),
(57, 25, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ وَأَنزَلْنَا مَعَهُمُ الْكِتَابَ وَالْمِيزَانَ لِيَقُومَ النَّاسُ بِالْقِسْطِ وَأَنزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَافِعُ لِلنَّاسِ وَلِيَعْلَمَ اللَّهُ مَن يَنصُرُهُ وَرُسُلَهُ بِالْغَيْبِ إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ', NULL, 'We have already sent Our messengers with clear evidences and sent down with them the Scripture and the balance that the people may maintain [their affairs] in justice. And We sent down iron, wherein is great military might and benefits for the people, and so that Allāh may make evident those who support Him and His messengers unseen. Indeed, Allāh is Powerful and Exalted in Might.', 'Demi sesungguhnya! Kami telah mengutus Rasul-rasul Kami dengan membawa bukti-bukti dan mukjizat yang jelas nyata, dan Kami telah menurunkan bersama-sama mereka Kitab Suci dan keterangan yang menjadi neraca keadilan, supaya manusia dapat menjalankan keadilan dan kami telah menciptakan besi dengan keadaannya mengandungi kekuatan yang handal serta berbagai faedah lagi bagi manusia. (Dijadikan besi dengan keadaan yang demikian, supaya manusia menggunakan faedah-faedah itu dalam kehidupan mereka sehari-hari) dan supaya ternyata pengetahuan Allah tentang orang yang (menggunakan kekuatan handalnya itu untuk) menegak dan mempertahankan ugama Allah serta menolong Rasul-rasulNya, padahal balasan baiknya tidak kelihatan (kepadanya); sesungguhnya Allah Maha Kuat, lagi Maha Kuasa.', FALSE, NULL, NULL, 541, 27, 216, 474, FALSE, 0, NULL),
(57, 26, 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَاهِيمَ وَجَعَلْنَا فِي ذُرِّيَّتِهِمَا النُّبُوَّةَ وَالْكِتَابَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَاسِقُونَ', NULL, 'And We have already sent Noah and Abraham and placed in their descendants prophethood and scripture; and among them is he who is guided, but many of them are defiantly disobedient.', 'Dan demi sesungguhnya! Kami telah mengutus Nabi Nuh dan Nabi Ibrahim, dan Kami jadikan pada keturunan keduanya orang-orang yang berpangkat Nabi dan menerima Kitab-kitab ugama; maka sebahagian di antara mereka: orang yang beroleh hidayah petunjuk, dan kebanyakan mereka orang-orang yang fasik - derhaka', FALSE, NULL, NULL, 541, 27, 216, 475, FALSE, 0, NULL),
(57, 27, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'ثُمَّ قَفَّيْنَا عَلَىٰ آثَارِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ابْنِ مَرْيَمَ وَآتَيْنَاهُ الْإِنجِيلَ وَجَعَلْنَا فِي قُلُوبِ الَّذِينَ اتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ إِلَّا ابْتِغَاءَ رِضْوَانِ اللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَآتَيْنَا الَّذِينَ آمَنُوا مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَاسِقُونَ', NULL, 'Then We sent following their footsteps [i.e., traditions] Our messengers and followed [them] with Jesus, the son of Mary, and gave him the Gospel. And We placed in the hearts of those who followed him compassion and mercy and monasticism, which they innovated; We did not prescribe it for them except [that they did so] seeking the approval of Allāh. But they did not observe it with due observance. So We gave the ones who believed among them their reward, but many of them are defiantly disobedient.', 'Kemudian Kami iringi sesudah - mereka: Rasul-rasul Kami silih berganti, dan Kami iringi lagi dengan Nabi Isa ibni Maryam, serta Kami berikan kepadanya: Kitab Injil; dan Kami jadikan dalam hati orang-orang yang mengikutnya perasaan belas kasihan (sesama sendiri). Dan (perbuatan mereka beribadat secara) “Rahbaniyyah” - merekalah sahaja yang mengadakan dan merekanya; Kami tidak mewajibkannya atas mereka; (mereka berbuat demikian) kerana mencari keredaan Allah; dalam pada itu mereka tidak menjaga dan memeliharanya menurut yang sewajibnya. Oleh itu, orang-orang yang beriman (kepada Nabi Muhammad) di antara mereka, kami berikan pahalanya, dan (sebaliknya) banyak di antara mereka yang fasik - derhaka.', FALSE, NULL, NULL, 541, 27, 216, 475, FALSE, 0, NULL),
(57, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِ وَيَغْفِرْ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ', NULL, 'O you who have believed, fear Allāh and believe in His Messenger; He will [then] give you a double portion of His mercy and make for you a light by which you will walk and forgive you; and Allāh is Forgiving and Merciful.', 'Wahai orang-orang yang beriman! Bertaqwalah kamu kepada Allah dan tetaplah beriman kepada RasulNya (Muhammad), supaya Allah memberi kepada kamu dua bahagian dari rahmatNya, dan menjadikan bagi kamu cahaya untuk kamu berjalan dengannya (pada hari kiamat kelak), serta diampunkannya dosa kamu; dan (ingatlah), Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 541, 27, 216, 475, FALSE, 0, NULL),
(57, 29, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'لِّئَلَّا يَعْلَمَ أَهْلُ الْكِتَابِ أَلَّا يَقْدِرُونَ عَلَىٰ شَيْءٍ مِّن فَضْلِ اللَّهِ وَأَنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ', NULL, '[This is] so that the People of the Scripture may know that they are not able [to obtain] anything from the bounty of Allāh and that [all] bounty is in the hand of Allāh; He gives it to whom He wills. And Allāh is the possessor of great bounty.', '(Ditetapkan pemberian yang demikian kepada kamu) supaya golongan ahli Kitab (Yahudi dan Nasrani - yang menentang Islam) mengetahui, bahawa sesungguhnya mereka tidak mempunyai sebarang kuasa untuk mendapat (atau menyekat) sesuatu dari limpah kurnia Allah, dan bahawa sesungguhnya limpah kurnia itu terletak dalam kekuasaan Allah, diberikanNya kepada sesiapa yang dikehendakiNya. Dan (ingatlah), Allah jualah yang mempunyai limpah kurnia yang besar.', FALSE, NULL, NULL, 541, 27, 216, 475, FALSE, 0, NULL),
(58, 1, 'قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَـٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'قد سمع الله قول التي تجادلك في زوجها وتشتكي الى الله والله يسمع تحاوركما ان الله سميع بصير', NULL, 'Certainly has Allāh heard the speech of the one who argues [i.e., pleads] with you, [O Muḥammad], concerning her husband and directs her complaint to Allāh. And Allāh hears your dialogue; indeed, Allāh is Hearing and Seeing.', 'Sesungguhnya Allah telah mendengar (dan memperkenan) aduan perempuan yang bersoal jawab denganmu (wahai Muhammad) mengenai suaminya, sambil ia berdoa merayu kepada Allah (mengenai perkara yang menyusahkannya), sedang Allah sedia mendengar perbincangan kamu berdua. Sesungguhnya Allah Maha Mendengar, lagi Maha Melihat.', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 18, NULL),
(58, 2, 'ٱلَّذِينَ يُظَـٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَـٰتِهِمْ ۖ إِنْ أُمَّهَـٰتُهُمْ إِلَّا ٱلَّـٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', 'الذين يظاهرون منكم من نسائهم ما هن امهاتهم ان امهاتهم الا اللائي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور', NULL, 'Those who pronounce ẓihār among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allāh is Pardoning and Forgiving.', 'Orang-orang yang “ziharkan” isterinya dari kalangan kamu (adalah orang-orang yang bersalah, kerana) isteri-isteri mereka bukanlah ibu-ibu mereka. Ibu-ibu mereka tidak lain hanyalah perempuan-perempuan yang melahirkan mereka. Dan sesungguhnya mereka (dengan melakukan yang demikian) memperkatakan suatu perkara yang mungkar dan dusta. Dan (ingatlah), sesungguhnya Allah Maha Pemaaf, lagi Maha Pengampun.', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 23, NULL),
(58, 3, 'وَٱلَّذِينَ يُظَـٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'والذين يظاهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير', NULL, 'And those who pronounce ẓihār from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allāh is Aware of what you do.', 'Dan orang-orang yang “ziharkan” isterinya, kemudian mereka berbalik dari apa yang mereka ucapkan (bahawa isterinya itu haram kepadanya), maka hendaklah (suami itu) memerdekakan seorang hamba sebelum mereka berdua (suami isteri) bercampur. Dengan hukum yang demikian, kamu diberi pengajaran (supaya jangan mendekati perkara yang mungkar itu). Dan (ingatlah), Allah Maha Mendalam PengetahuanNya akan apa yang kamu lakukan.', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 21, NULL),
(58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ', 'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكافرين عذاب اليم', NULL, 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allāh and His Messenger; and those are the limits [set by] Allāh. And for the disbelievers is a painful punishment.', 'Kemudian, sesiapa yang tidak dapat (memerdekakan hamba), maka hendaklah ia berpuasa dua bulan berturut-turut sebelum mereka (suami isteri) itu bercampur. Akhirnya sesiapa yang tidak sanggup berpuasa, maka hendaklah ia memberi makan enam puluh orang miskin. Ditetapkan hukum itu untuk membuktikan iman kamu kepada Allah dan RasulNya (dengan mematuhi perintahNya serta menjauhi adat Jahiliyah). Dan itulah batas-batas hukum Allah; dan bagi orang-orang yang kafir disediakan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 26, NULL),
(58, 5, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ', 'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايات بينات وللكافرين عذاب مهين', NULL, 'Indeed, those who oppose Allāh and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment', 'Sesungguhnya orang-orang yang menentang (perintah) Allah dan RasulNya, mereka tetap ditimpa kehinaan sebagaimana orang-orang yang terdahulu dari mereka ditimpa kehinaan; kerana sesungguhnya Kami telah menurunkan keterangan-keterangan yang jelas nyata. Dan bagi orang-orang yang kafir disediakan azab seksa yang menghina,', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 18, NULL),
(58, 6, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'يوم يبعثهم الله جميعا فينبئهم بما عملوا احصاه الله ونسوه والله على كل شيء شهيد', NULL, 'On the Day when Allāh will resurrect them all and inform them of what they did. Allāh had enumerated it, while they forgot it; and Allāh is, over all things, Witness.', 'Semasa mereka semuanya dibangkitkan hidup semula oleh Allah (pada hari kiamat), lalu diterangkan kepada mereka segala yang mereka telah kerjakan. Allah telah menghitung amal-amal mereka itu satu persatu, sedang mereka telah melupakannya. Dan (ingatlah), Allah menjadi Saksi akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 542, 28, 217, 476, FALSE, 15, NULL),
(58, 7, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'الم تر ان الله يعلم ما في السماوات وما في الارض ما يكون من نجوى ثلاثة الا هو رابعهم ولا خمسة الا هو سادسهم ولا ادنى من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيامة ان الله بكل شيء عليم', NULL, 'Have you not considered that Allāh knows what is in the heavens and what is on the earth? There are not three in a private conversation but that He is the fourth of them, nor are there five but that He is the sixth of them - and no less than that and no more except that He is with them [in knowledge] wherever they are. Then He will inform them of what they did on the Day of Resurrection. Indeed Allāh is, of all things, Knowing.', 'Tidakkah engkau memikirkan, bahawa sesungguhnya Allah mengetahui segala yang ada di langit dan yang ada di bumi? Tiada berlaku bisikan antara tiga orang melainkan Dia lah yang keempatnya, dan tiada (berlaku antara) lima orang melainkan Dia lah yang keenamnya, dan tiada yang kurang dari bilangan itu dan tiada yang lebih ramai, melainkan Ia ada bersama-sama mereka di mana sahaja mereka berada. Kemudian Ia akan memberi tahu kepada mereka - pada hari kiamat - apa yang mereka telah kerjakan. Sesungguhnya Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 543, 28, 217, 477, FALSE, 47, NULL),
(58, 8, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَـٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ', 'الم تر الى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتناجون بالاثم والعدوان ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير', NULL, 'Have you not considered those who were forbidden from private conversation [i.e., ridicule and conspiracy] and then return to that which they were forbidden and converse among themselves about sin and aggression and disobedience to the Messenger? And when they come to you, they greet you with that [word] by which Allāh does not greet you and say among themselves, "Why does Allāh not punish us for what we say?" Sufficient for them is Hell, which they will [enter to] burn, and wretched is the destination.', 'Tidakkah engkau memerhatikan (wahai Muhammad) akan orang-orang (Yahudi) yang telah dilarang daripada perbuatan berbisik-bisik, kemudian mereka berbalik melakukan perbuatan yang telah dilarang itu serta mereka berbisik-bisik berkenaan dengan melakukan dosa dan pencerobohan serta kederhakaan kepada Rasulullah? Dan lagi apabila mereka datang kepadamu, mereka memberi salam hormat bukan dengan lafaz salam hormat yang diberikan Allah kepadamu; dan mereka berkata sesama sendiri: “(Kalau benar Muhammad utusan Tuhan, maka) sepatutnya kami diseksa oleh Allah disebabkan (kata-kata buruk) yang kami ucapkan itu?” Cukuplah untuk mereka neraka Jahannam, yang mereka akan dibakar di dalamnya; maka itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 543, 28, 217, 477, FALSE, 38, NULL),
(58, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَـٰجَيْتُمْ فَلَا تَتَنَـٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَـٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'يا ايها الذين امنوا اذا تناجيتم فلا تتناجوا بالاثم والعدوان ومعصيت الرسول وتناجوا بالبر والتقوى واتقوا الله الذي اليه تحشرون', NULL, 'O you who have believed, when you converse privately, do not converse about sin and aggression and disobedience to the Messenger but converse about righteousness and piety. And fear Allāh, to whom you will be gathered.', 'Wahai orang-orang yang beriman! Apabila kamu berbisik-bisik sesama sendiri, maka janganlah kamu berbisik-bisik untuk melakukan dosa dan pencerobohan serta perbuatan derhaka kepada Rasulullah; dan (sebaliknya) berbisiklah untuk berbuat kebajikan dan bertaqwa. Dan hendaklah kamu tetap bertaqwa kepada Allah yang kepadaNya kamu semua akan dihimpunkan (pada hari kiamat untuk dihitung amal kamu dan menerima balasan).', FALSE, NULL, NULL, 543, 28, 217, 477, FALSE, 19, NULL),
(58, 10, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَـٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'انما النجوى من الشيطان ليحزن الذين امنوا وليس بضارهم شيئا الا باذن الله وعلى الله فليتوكل المؤمنون', NULL, 'Private conversation is only from Satan that he may grieve those who have believed, but he will not harm them at all except by permission of Allāh. And upon Allāh let the believers rely.', 'Sesungguhnya perbuatan berbisik (dengan kejahatan) itu adalah dari (hasutan) Syaitan, untuk menjadikan orang-orang yang beriman berdukacita; sedang bisikan itu tidak akan dapat membahayakan mereka sedikitpun melainkan dengan izin Allah; dan kepada Allah jualah hendaknya orang-orang yang beriman berserah diri.', FALSE, NULL, NULL, 543, 28, 217, 477, FALSE, 17, NULL),
(58, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَـٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَـٰتٍ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'يا ايها الذين امنوا اذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجات والله بما تعملون خبير', NULL, 'O you who have believed, when you are told, "Space yourselves" in assemblies, then make space; Allāh will make space for you. And when you are told, "Arise," then arise; Allāh will raise those who have believed among you and those who were given knowledge, by degrees. And Allāh is Aware of what you do.', 'Wahai orang-orang yang beriman! Apabila diminta kepada kamu memberi lapang dari tempat duduk kamu (untuk orang lain) maka lapangkanlah seboleh-bolehnya supaya Allah melapangkan (segala halnya) untuk kamu. Dan apabila diminta kamu bangun maka bangunlah, supaya Allah meninggikan darjat orang-orang yang beriman di antara kamu, dan orang-orang yang diberi ilmu pengetahuan ugama (dari kalangan kamu) - beberapa darjat. Dan (ingatlah), Allah Maha Mendalam PengetahuanNya tentang apa yang kamu lakukan.', FALSE, NULL, NULL, 543, 28, 217, 477, FALSE, 30, NULL),
(58, 12, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَـٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ۚ ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'يا ايها الذين امنوا اذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم', NULL, 'O you who have believed, when you [wish to] privately consult the Messenger, present before your consultation a charity. That is better for you and purer. But if you find not [the means] - then indeed, Allāh is Forgiving and Merciful.', 'Wahai orang-orang yang beriman! Apabila kamu hendak mengadap dan bertanyakan sesuatu kepada Rasulullah, maka hendaklah kamu bersedekah (kepada fakir miskin) sebelum kamu mengadapnya; (pemberian sedekah) itu adalah lebih baik bagi kamu dan lebih bersih. Dalam pada itu, kalau kamu tidak ada benda yang hendak disedekahkan, (kamu dibenarkan juga mengadapnya mengenai perkara yang tak dapat dielak), kerana sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 544, 28, 217, 477, FALSE, 22, NULL),
(58, 13, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَـٰتٍ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ااشفقتم ان تقدموا بين يدي نجواكم صدقات فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاة واتوا الزكاة واطيعوا الله ورسوله والله خبير بما تعملون', NULL, 'Have you feared to present before your consultation charities? Then when you do not and Allāh has forgiven you, then [at least] establish prayer and give zakāh and obey Allāh and His Messenger. And Allāh is Aware of what you do.', 'Adakah kamu takut (akan kemiskinan) kerana kerap kali kamu memberi sedekah sebelum kamu mengadap? Kalau kamu tidak melakukan (perintah) itu, dan Allah pun memaafkan kamu (kerana kamu tidak mampu), maka dirikanlah sembahyang dan berikanlah zakat (sebagaimana yang sewajibnya), serta taatlah kamu kepada Allah dan RasulNya. Dan (ingatlah), Allah Maha Mendalam PengetahuanNya akan segala amalan yang kamu lakukan.', FALSE, NULL, NULL, 544, 28, 217, 477, FALSE, 24, NULL),
(58, 14, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', 'الم تر الى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون', NULL, 'Have you not considered those who make allies of a people with whom Allāh has become angry? They are neither of you nor of them, and they swear to untruth while they know [they are lying].', 'Tidakkah engkau melihat (bagaimana jahatnya) orang-orang yang bersahabat karib dengan kaum yang telah dimurkai Allah (dengan sebab kekufuran dan khianatnya)? Mereka itu bukanlah dari golongan kamu dan bukan pula dari golongan kaum yang tersebut itu (kerana mereka ialah golongan munafik); dan lagi mereka selalu bersumpah dengan dusta, sedang mereka mengetahui (bahawa mereka adalah berdusta).', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 19, NULL),
(58, 15, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون', NULL, 'Allāh has prepared for them a severe punishment. Indeed, it was evil that they were doing.', 'Allah telah menyediakan bagi mereka azab seksa yang berat; sesungguhnya amatlah buruk apa yang mereka telah lakukan.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 10, NULL),
(58, 16, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', 'اتخذوا ايمانهم جنة فصدوا عن سبيل الله فلهم عذاب مهين', NULL, 'They took their [false] oaths as a cover, so they averted [people] from the way of Allāh, and for them is a humiliating punishment.', 'Mereka menjadikan sumpahnya sebagai perisai (untuk menyelamatkan diri dan harta bendanya daripada dirampas atau dibunuh), maka dengan yang demikian dapatlah mereka menghalang (dirinya dan orang lain) dari jalan Allah; oleh itu mereka beroleh azab seksa yang menghina.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 10, NULL),
(58, 17, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', 'لن تغني عنهم اموالهم ولا اولادهم من الله شيئا اولئك اصحاب النار هم فيها خالدون', NULL, 'Never will their wealth or their children avail them against Allāh at all. Those are the companions of the Fire; they will abide therein eternally', 'harta benda mereka dan anak pinak mereka tidak sekali-kali akan dapat memberikan sebarang pertolongan kepada mereka dari azab Allah. Merekalah ahli neraka, mereka tetap kekal di dalamnya.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 15, NULL),
(58, 18, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَـٰذِبُونَ', 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم على شيء الا انهم هم الكاذبون', NULL, 'On the Day Allāh will resurrect them all, and they will swear to Him as they swear to you and think that they are [standing] on something. Unquestionably, it is they who are the liars.', '(Setelah nyata kepada orang-orang munafik itu bahawa harta benda dan anak pinaknya tidak dapat memberikan pertolongan), ketika mereka semuanya dibangkitkan oleh Allah (pada hari kiamat), maka mereka bersumpah kepadaNya (bahawa mereka adalah orang-orang mukmin) sebagaimana biasanya mereka bersumpah kepada kamu; dan mereka menyangka bahawa (dengan berbuat demikian) mereka akan mendapat sesuatu (yang berfaedah kepada mereka). Ketahuilah! Bahawa sesungguhnya merekalah golongan pendusta.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 17, NULL),
(58, 19, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَـٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱلشَّيْطَـٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَـٰنِ هُمُ ٱلْخَـٰسِرُونَ', 'استحوذ عليهم الشيطان فانساهم ذكر الله اولئك حزب الشيطان الا ان حزب الشيطان هم الخاسرون', NULL, 'Satan has overcome them and made them forget the remembrance of Allāh. Those are the party of Satan. Unquestionably, the party of Satan - they will be the losers.', 'Syaitan telah menguasai dan mempengaruhi mereka, sehingga menyebabkan mereka lupa mengingati (ajaran dan amaran) Allah; mereka itulah puak Syaitan. Ketahuilah! Bahawa puak Syaitan itu sebenarnya orang-orang yang rugi.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 15, NULL),
(58, 20, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَـٰٓئِكَ فِى ٱلْأَذَلِّينَ', 'ان الذين يحادون الله ورسوله اولئك في الاذلين', NULL, 'Indeed, the ones who oppose Allāh and His Messenger - those will be among the most humbled.', 'Sesungguhnya orang-orang yang menentang (perintah) Allah dan RasulNya, mereka termasuk dalam golongan yang amat hina.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 8, NULL),
(58, 21, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 'كَتَبَ اللَّهُ لَأَغْلِبَنَّ أَنَا وَرُسُلِي إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ', NULL, 'Allāh has written [i.e., decreed], "I will surely overcome, I and My messengers." Indeed, Allāh is Powerful and Exalted in Might.', 'Allah telah menetapkan: “Sesungguhnya Aku dan Rasul-rasulKu tetap mengalahkan (golongan yang menentang)”. Sesungguhnya Allah Maha Kuat, lagi Maha kuasa.', FALSE, NULL, NULL, 544, 28, 218, 478, FALSE, 0, NULL),
(58, 22, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ أُولَٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ أُولَٰئِكَ حِزْبُ اللَّهِ أَلَا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ', NULL, 'You will not find a people who believe in Allāh and the Last Day having affection for those who oppose Allāh and His Messenger, even if they were their fathers or their sons or their brothers or their kindred. Those - He has decreed within their hearts faith and supported them with spirit from Him. And We will admit them to gardens beneath which rivers flow, wherein they abide eternally. Allāh is pleased with them, and they are pleased with Him - those are the party of Allāh. Unquestionably, the party of Allāh - they are the successful.', 'Engkau tidak akan dapati sesuatu kaum yang beriman kepada Allah dan hari akhirat, tergamak berkasih-mesra dengan orang-orang yang menentang (perintah) Allah dan RasulNya, sekalipun orang-orang yang menentang itu ialah bapa-bapa mereka, atau anak-anak mereka, atau saudara-saudara mereka, ataupun keluarga mereka. Mereka (yang setia) itu, Allah telah menetapkan iman dalam hati mereka, dan telah menguatkan mereka dengan semangat pertolongan daripadaNya; dan Dia akan memasukkan mereka ke dalam Syurga yang mengalir di bawahnya beberapa sungai, mereka tetap kekal di dalamnya. Allah reda akan mereka dan mereka reda (serta bersyukur) akan nikmat pemberianNya. Merekalah penyokong-penyokong (ugama) Allah. Ketahuilah! Sesungguhnya penyokong-penyokong (ugama) Allah itu ialah orang-orang yang berjaya.', FALSE, NULL, NULL, 545, 28, 218, 478, FALSE, 0, NULL),
(59, 1, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم', NULL, 'Whatever is in the heavens and whatever is on the earth exalts Allāh, and He is the Exalted in Might, the Wise.', 'Segala yang ada di langit dan di bumi tetap mengucap tasbih kepada Allah; dan Dia lah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 545, 28, 218, 479, FALSE, 11, NULL),
(59, 2, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ مِن دِيَـٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَـٰٓأُو۟لِى ٱلْأَبْصَـٰرِ', 'هو الذي اخرج الذين كفروا من اهل الكتاب من ديارهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتاهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا يا اولي الابصار', NULL, 'It is He who expelled the ones who disbelieved among the People of the Scripture from their homes at the first gathering. You did not think they would leave, and they thought that their fortresses would protect them from Allāh; but [the decree of] Allāh came upon them from where they had not expected, and He cast terror into their hearts [so] they destroyed their houses by their [own] hands and the hands of the believers. So take warning, O people of vision.', 'Dia lah yang telah mengeluarkan orang-orang kafir di antara Ahli Kitab - dari kampung halaman mereka pada julung-julung kali mereka berhimpun hendak memerangi Rasulullah. Kamu (wahai umat Islam) tidak menyangka bahawa mereka akan keluar (disebabkan bilangannya yang ramai dan pertahanannya yang kuat), dan mereka pula menyangka bahawa benteng-benteng mereka akan dapat menahan serta memberi perlindungan kepada mereka (dari azab) Allah. Maka Allah menimpakan (azabNya) kepada mereka dari arah yang tidak terlintas dalam fikiran mereka, serta dilemparkanNya perasaan cemas takut ke dalam hati mereka, (lalu) mereka membinasakan rumah-rumah mereka dengan tangan mereka sendiri (dari dalam) sambil tangan orang-orang yang beriman (yang mengepung mereka berbuat demikian dari luar). Maka insaflah dan ambilah pelajaran (dari peristiwa itu) wahai orang-orang yang berakal fikiran serta celik mata hatinya.', FALSE, NULL, NULL, 545, 28, 218, 479, FALSE, 40, NULL),
(59, 3, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ', 'ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخرة عذاب النار', NULL, 'And if not that Allāh had decreed for them evacuation, He would have punished them in [this] world, and for them in the Hereafter is the punishment of the Fire.', 'Dan kalaulah tidak kerana Allah telah menetapkan pengusiran (yang demikian buruknya) terhadap mereka, tentulah Ia akan menyeksa mereka di dunia; dan mereka pula akan beroleh azab seksa neraka pada hari akhirat kelak.', FALSE, NULL, NULL, 545, 28, 218, 479, FALSE, 14, NULL),
(59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب', NULL, 'That is because they opposed Allāh and His Messenger. And whoever opposes Allāh - then indeed, Allāh is severe in penalty.', '(Mereka ditimpakan azab) yang demikian, kerana mereka mereka menentang (perintah) Allah dan RasulNya. Dan (ingatlah), sesiapa yang menentang (perintah) Allah, maka sesungguhnya Allah amatlah berat azab seksaNya.', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 12, NULL),
(59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَـٰسِقِينَ', 'ما قطعتم من لينة او تركتموها قائمة على اصولها فباذن الله وليخزي الفاسقين', NULL, 'Whatever you have cut down of [their] palm trees or left standing on their trunks - it was by permission of Allāh and so He would disgrace the defiantly disobedient.', 'Mana-mana jua pohon kurma (kepunyaan musuh) yang kamu tebang atau kamu biarkan tegak berdiri seperti keadaannya yang asal, maka yang demikian adalah dengan izin Allah (kerana Ia hendak memberi kemenangan kepada orang-orang mukmin), dan kerana Ia hendak menimpakan kehinaan kepada orang-orang yang fasik.', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 13, NULL),
(59, 6, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَـٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'وما افاء الله على رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير', NULL, 'And what Allāh restored [of property] to His Messenger from them - you did not spur for it [in an expedition] any horses or camels, but Allāh gives His messengers power over whom He wills, and Allāh is over all things competent.', 'Dan apajua yang Allah kurniakan kepada RasulNya dari peninggalan harta benda mereka (yang telah diusir itu, maka kamu tidak berhak mendapatnya), kerana kamu tidak memecut seekor kuda pun dan tidak menunggang seekor unta pun (untuk berperang mengalahkan mereka); tetapi Allah memberikan kekuasaan kepada Rasul-rasulNya mengalahkan sesiapa yang dikehendakiNya (dengan tidak payah berperang); dan Allah Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 25, NULL),
(59, 7, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'ما افاء الله على رسوله من اهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل كي لا يكون دولة بين الاغنياء منكم وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا واتقوا الله ان الله شديد العقاب', NULL, 'And what Allāh restored to His Messenger from the people of the towns - it is for Allāh and for the Messenger and for [his] near relatives and orphans and the needy and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allāh; indeed, Allāh is severe in penalty.', 'Apa yang Allah kurniakan kepada RasulNya (Muhammad) dari harta penduduk negeri, bandar atau desa dengan tidak berperang, maka adalah ia tertentu bagi Allah, dan bagi Rasulullah, dan bagi kaum kerabat (Rasulullah), dan anak-anak yatim, dan orang-orang miskin, serta orang-orang musafir (yang keputusan). (Ketetapan yang demikian) supaya harta itu tidak hanya beredar di antara orang-orang kaya dari kalangan kamu. Dan apa jua perintah yang dibawa oleh Rasulullah (s.a.w) kepada kamu maka terimalah serta amalkan, dan apa jua yang dilarangNya kamu melakukannya maka patuhilah laranganNya. Dan bertaqwalah kamu kepada Allah; sesungguhnya Allah amatlah berat azab seksaNya (bagi orang-orang yang melanggar perintahNya).', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 37, NULL),
(59, 8, 'لِلْفُقَرَآءِ ٱلْمُهَـٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ', 'للفقراء المهاجرين الذين اخرجوا من ديارهم واموالهم يبتغون فضلا من الله ورضوانا وينصرون الله ورسوله اولئك هم الصادقون', NULL, 'For the poor emigrants who were expelled from their homes and their properties, seeking bounty from Allāh and [His] approval and supporting [the cause of] Allāh and His Messenger, [there is also a share]. Those are the truthful.', '(Pemberian itu hendaklah diuntukkan) kepada orang-orang fakir yang berhijrah, yang telah diusir keluar dari kampung halamannya dan harta bendanya (kerana berpegang teguh kepada ajaran Islam), untuk mencari limpah kurnia dari Allah dan keredaanNya, serta menolong (ugama) Allah dan RasulNya; mereka itulah orang-orang yang benar (imannya dan amalnya).', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 18, NULL),
(59, 9, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَـٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'والذين تبوءوا الدار والايمان من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجة مما اوتوا ويؤثرون على انفسهم ولو كان بهم خصاصة ومن يوق شح نفسه فاولئك هم المفلحون', NULL, 'And [also for] those who were settled in the Home [i.e.,al-Madīnah] and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what they [i.e., the emigrants] were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', 'Dan orang-orang (Ansar) yang mendiami negeri (Madinah) serta beriman sebelum mereka, mengasihi orang-orang yang berhijrah ke negeri mereka, dan tidak ada pula dalam hati mereka perasaan berhajatkan apa yang telah diberi kepada orang-orang yang berhijrah itu; dan mereka juga mengutamakan orang-orang yang berhijrah itu lebih daripada diri mereka sendiri, sekalipun mereka dalam keadaan kekurangan dan amat berhajat. Dan (ingatlah), sesiapa yang menjaga serta memelihara dirinya daripada dipengaruhi oleh tabiat bakhilnya, maka merekalah orang-orang yang berjaya.', FALSE, NULL, NULL, 546, 28, 218, 479, FALSE, 31, NULL),
(59, 10, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَـٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', 'والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولاخواننا الذين سبقونا بالايمان ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك رءوف رحيم', NULL, 'And [there is a share for] those who come after them, saying, "Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."', 'Dan orang-orang (Islam) yang datang kemudian daripada mereka (berdoa dengan) berkata: “Wahai Tuhan Kami! Ampunkanlah dosa kami dan dosa saudara-saudara kami yang mendahului kami dalam iman, dan janganlah Engkau jadikan dalam hati perasaan hasad dengki dan dendam terhadap orang-orang yang beriman. Wahai Tuhan kami! Sesungguhnya Engkau Amat Melimpah Belas kasihan dan RahmatMu”.', FALSE, NULL, NULL, 547, 28, 218, 479, FALSE, 23, NULL),
(59, 11, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ', 'الم تر الى الذين نافقوا يقولون لاخوانهم الذين كفروا من اهل الكتاب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكاذبون', NULL, 'Have you not considered those who practice hypocrisy, saying to their brothers [i.e., associates] who have disbelieved among the People of the Scripture, "If you are expelled, we will surely leave with you, and we will not obey, in regard to you, anyone - ever; and if you are fought, we will surely aid you." But Allāh testifies that they are liars.', 'Tidakkah engkau melihat dan merasa hairan (wahai Muhammad) terhadap sikap orang-orang munafik itu? Mereka tergamak berkata kepada saudara-saudara mereka yang kafir dari kalangan (kaum Yahudi) ahli Kitab: “Sesungguhnya, kalau kamu dihalau keluar sudah tentu kami akan keluar bersama-sama kamu, dan kami tidak akan tunduk taat kepada sesiapapun untuk menentang kamu selama-lamanya; dan kalau kamu diperangi, sudah tentu kami akan membela kamu!” Padahal Allah mengetahui dan menyaksikan bahawa sebenarnya mereka adalah pendusta.', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 28, NULL),
(59, 12, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَـٰرَ ثُمَّ لَا يُنصَرُونَ', 'لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبار ثم لا ينصرون', NULL, 'If they are expelled, they will not leave with them, and if they are fought, they will not aid them. And [even] if they should aid them, they will surely turn their backs; then [thereafter] they will not be aided.', 'Demi sesungguhnya! Jika orang-orang (Yahudi) itu dihalau keluar (dari Madinah), mereka (yang munafik) ini tidak akan keluar bersama-samanya; dan demi sesungguhnya, jika orang-orang (Yahudi) itu diperangi, mereka (yang munafik) ini tidak akan membelanya; dan demi sesungguhnya, jika ditakdirkan mereka membelanya sekalipun, sudah tentu mereka (semuanya - Yahudi dan munafik) akan melarikan diri; kemudian mereka tidak akan mendapat pertolongan, -', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 16, NULL),
(59, 13, 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'لانتم اشد رهبة في صدورهم من الله ذلك بانهم قوم لا يفقهون', NULL, 'You [believers] are more fearful within their breasts than Allāh. That is because they are a people who do not understand.', '(Kerana) sesungguhnya kamu - dalam hati mereka, - sangat ditakuti lebih dari Allah; yang demikian itu, kerana mereka ialah kaum yang tidak mengerti (akan kekuasaan Allah dan kebesaranNya).', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 12, NULL),
(59, 14, 'لَا يُقَـٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ ۚ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', 'لا يقاتلونكم جميعا الا في قرى محصنة او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتى ذلك بانهم قوم لا يعقلون', NULL, 'They will not fight you all except within fortified cities or from behind walls. Their violence [i.e., enmity] among themselves is severe. You think they are together, but their hearts are diverse. That is because they are a people who do not reason.', '(Orang-orang Yahudi dan orang-orang munafik) dengan keadaan bersatu padu sekalipun, tidak berani memerangi kamu melainkan di kampung-kampung yang berbenteng kukuh, atau dari sebalik tembok. (Sebabnya): permusuhan di antara mereka sesama sendiri amatlah keras; engkau menyangka mereka bersatu padu, sedang hati mereka berpecah belah (disebabkan berlainan kepercayaan mereka). Yang demikian itu, kerana mereka adalah kaum yang tidak memahami (perkara yang sebenarnya yang memberi kebaikan kepada mereka).', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 23, NULL),
(59, 15, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم', NULL, '[Theirs is] like the example of those shortly before them: they tasted the bad consequence of their affair, and they will have a painful punishment.', '(Keadaan kaum Yahudi itu) samalah seperti orang-orang (dari suku Yahudi) yang terdahulu sedikit dari mereka, yang telah merasai akibat yang buruk (di dunia) dengan sebab bawaan kufur mereka; dan mereka pula akan beroleh azab seksa yang tidak terperi sakitnya (pada hari akhirat kelak).', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 11, NULL),
(59, 16, 'كَمَثَلِ ٱلشَّيْطَـٰنِ إِذْ قَالَ لِلْإِنسَـٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ', 'كمثل الشيطان اذ قال للانسان اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العالمين', NULL, '[The hypocrites are] like the example of Satan when he says to man, "Disbelieve." But when he disbelieves, he says, "Indeed, I am disassociated from you. Indeed, I fear Allāh, Lord of the worlds."', '(Sikap kaum munafik dengan kaum Yahudi) itu samalah seperti (sikap) Syaitan ketika ia berkata kepada manusia: “Berlaku kufurlah engkau!” Setelah orang itu berlaku kufur (dan tetap terkena azab), berkatalah Syaitan kepadanya: “Sesungguhnya aku adalah berlepas diri daripadamu, kerana sebenarnya aku takut kepada Allah, Tuhan yang menguasai seluruh alam!”', FALSE, NULL, NULL, 547, 28, 219, 480, FALSE, 17, NULL),
(59, 17, 'فَكَانَ عَـٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَـٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ', 'فكان عاقبتهما انهما في النار خالدين فيها وذلك جزاء الظالمين', NULL, 'So the outcome for both of them is that they will be in the Fire, abiding eternally therein. And that is the recompense of the wrongdoers.', 'Maka kesudahan keduanya, bahawa mereka ditempatkan di dalam neraka, kekal mereka di dalamnya. Dan yang demikian itulah balasan makhluk-makhluk yang zalim.', FALSE, NULL, NULL, 548, 28, 219, 480, FALSE, 10, NULL),
(59, 18, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'يا ايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون', NULL, 'O you who have believed, fear Allāh. And let every soul look to what it has put forth for tomorrow - and fear Allāh. Indeed, Allāh is Aware of what you do.', 'Wahai orang-orang yang beriman! Bertaqwalah kepada Allah (dengan mengerjakan suruhanNya dan meninggalkan laranganNya); dan hendaklah tiap-tiap diri melihat dan memerhatikan apa yang ia telah sediakan (dari amal-amalnya) untuk hari esok (hari akhirat). Dan (sekali lagi diingatkan): Bertaqwalah kepada Allah, sesungguhnya Allah Amat Meliputi PengetahuanNya akan segala yang kamu kerjakan.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 17, NULL),
(59, 19, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', 'ولا تكونوا كالذين نسوا الله فانساهم انفسهم اولئك هم الفاسقون', NULL, 'And be not like those who forgot Allāh, so He made them forget themselves. Those are the defiantly disobedient.', 'Dan janganlah kamu menjadi seperti orang-orang yang telah melupakan (perintah-perintah) Allah, lalu Allah menjadikan mereka melupakan (amal-amal yang baik untuk menyelamatkan) diri mereka. Mereka itulah orang-orang yang fasik - derhaka.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 10, NULL),
(59, 20, 'لَا يَسْتَوِىٓ أَصْحَـٰبُ ٱلنَّارِ وَأَصْحَـٰبُ ٱلْجَنَّةِ ۚ أَصْحَـٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 'لا يستوي اصحاب النار واصحاب الجنة اصحاب الجنة هم الفائزون', NULL, 'Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success].', 'Tidaklah sama ahli neraka dan ahli Syurga; ahli Syurgalah orang-orang yang beroleh kemenangan (mendapat segala yang diingini).', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 10, NULL),
(59, 21, 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'لَوْ أَنزَلْنَا هَٰذَا الْقُرْآنَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللَّهِ وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', NULL, 'If We had sent down this Qur’ān upon a mountain, you would have seen it humbled and splitting from fear of Allāh. And these examples We present to the people that perhaps they will give thought.', 'Sekiranya Kami turunkan Al-Quran ini ke atas sebuah gunung, nescaya engkau melihat gunung itu khusyuk serta pecah belah kerana takut kepada Allah. Dan (ingatlah), misal-misal perbandingan ini Kami kemukakan kepada umat manusia, supaya mereka memikirkannya.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 0, NULL),
(59, 22, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'هُوَ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ هُوَ الرَّحْمَٰنُ الرَّحِيمُ', NULL, 'He is Allāh, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful.', 'Dia lah Allah, yang tidak ada Tuhan melainkan Dia; Yang Mengetahui perkara yang ghaib dan yang nyata; Dia lah Yang Maha Pemurah, lagi Maha Mengasihani.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 0, NULL),
(59, 23, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'هُوَ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ', NULL, 'He is Allāh, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Grantor of Security, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allāh above whatever they associate with Him.', 'Dia lah Allah, yang tidak ada Tuhan melainkan Dia; Yang Menguasai (sekalian alam); Yang Maha Suci; Yang Maha Selamat Sejahtera (dari segala kekurangan); Yang Maha Melimpahkan Keamanan; Yang Maha Pengawal serta Pengawas; Yang Maha Kuasa; Yang Maha Kuat (menundukkan segala-galanya); Yang Melengkapi segala KebesaranNya. Maha Suci Allah dari segala yang mereka sekutukan denganNya.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 0, NULL),
(59, 24, 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ لَهُ الْأَسْمَاءُ الْحُسْنَىٰ يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ', NULL, 'He is Allāh, the Creator, the Producer, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise.', 'Dia lah Allah, Yang Menciptakan sekalian makhluk; Yang Mengadakan (dari tiada kepada ada); Yang Membentuk rupa (makhluk-makhlukNya menurut yang dikehendakiNya); bagiNyalah nama-nama yang sebaik-baiknya dan semulia-mulianya; bertasbih kepadaNya segala yang ada di langit dan di bumi; dan Dia lah Yang tiada bandingNya, lagi Maha Bijaksana.', FALSE, NULL, NULL, 548, 28, 219, 481, FALSE, 0, NULL),
(60, 1, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَـٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'يا ايها الذين امنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالمودة وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهادا في سبيلي وابتغاء مرضاتي تسرون اليهم بالمودة وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل', NULL, 'O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allāh, your Lord. If you have come out for jihād [i.e., fighting or striving] in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection [i.e., instruction], but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way.', 'Wahai orang-orang yang beriman! Janganlah kamu mengambil musuhKu dan musuh kamu menjadi teman rapat, dengan cara kamu sampaikan kepada mereka (berita-berita rahsia orang-orang mukmin) dengan sebab hubungan baik dan kasih mesra yang ada di antara kamu dengan mereka, sedang mereka telah kufur ingkar terhadap kebenaran (Islam) yang sampai kepada kamu; mereka pula telah mengeluarkan Rasulullah (s.a.w) dan juga mengeluarkan kamu (dari Tanah Suci Makkah) disebabkan kamu beriman kepada Allah Tuhan kamu. (Janganlah kamu berbuat demikian) jika betul kamu keluar untuk berjihad pada jalanKu dan untuk mencari keredaanKu. (Tidak ada sebarang faedahnya) kamu mengadakan hubungan kasih mesra dengan mereka secara rahsia, sedang Aku amat mengetahui akan apa yang kamu rahsiakan dan apa yang kamu zahirkan. Dan (ingatlah), sesiapa di antara kamu yang melakukan perkara yang demikian, maka sesungguhnya telah sesatlah ia dari jalan yang betul.', FALSE, NULL, NULL, 549, 28, 219, 482, FALSE, 48, NULL),
(60, 2, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', 'ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون', NULL, 'If they gain dominance over you, they would be [i.e., behave] to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve.', 'Jika mereka dapat menguasai kamu, nescaya mereka menjadi musuh yang membahayakan kamu, dan mereka akan membebaskan tangan mereka dan lidah mereka terhadap kamu dengan kejahatan, serta mereka suka kalaulah kamu juga menjadi kafir (seperti mereka).', FALSE, NULL, NULL, 549, 28, 219, 482, FALSE, 13, NULL),
(60, 3, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَـٰدُكُمْ ۚ يَوْمَ ٱلْقِيَـٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'لن تنفعكم ارحامكم ولا اولادكم يوم القيامة يفصل بينكم والله بما تعملون بصير', NULL, 'Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allāh, of what you do, is Seeing.', 'Kaum kerabat kamu dan anak-anak kamu (yang tidak menurut kamu beriman) tidak sekali-kali akan mendatangkan sebarang faedah kepada kamu pada hari kiamat; Allah akan memisahkan di antara kamu semua (pada hari itu). Dan (ingatlah), Allah Maha Melihat segala yang kamu kerjakan.', FALSE, NULL, NULL, 549, 28, 219, 482, FALSE, 13, NULL),
(60, 4, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'قد كانت لكم اسوة حسنة في ابراهيم والذين معه اذ قالوا لقومهم انا براء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء ابدا حتى تؤمنوا بالله وحده الا قول ابراهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير', NULL, 'There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, "Indeed, we are disassociated from you and from whatever you worship other than Allāh. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allāh alone" - except for the saying of Abraham to his father, "I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allāh. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination.', 'Sesungguhnya adalah bagi kamu pada bawaan Nabi Ibrahim (a.s) dan pengikut-pengikutnya - contoh ikutan yang baik, semasa mereka berkata kepada kaumnya (yang kufur ingkar): “Sesungguhnya kami berlepas diri daripada kamu dan daripada apa yang kamu sembah yang lain dari Allah; kami kufur ingkarkan (segala penyembahan) kamu dan (dengan ini) nyatalah perasaan permusuhan dan kebencian di antara kami dengan kamu selama-lamanya, sehingga kamu menyembah Allah semata-mata”, tetapi janganlah dicontohi perkataan Nabi Ibrahim kepada bapanya (katanya): “Aku akan memohon kepada Tuhanku mengampun dosamu, dan aku tidak berkuasa menahan (azab seksa) dari Allah sedikit juapun daripada menimpamu”. (Berdoalah wahai orang-orang yang beriman sebagaimana Nabi Ibrahim dan pengikut-pengikutnya berdoa ketika mereka memusuhi kaumnya yang kafir, dengan berkata): “Wahai Tuhan kami! Kepada Engkaulah sahaja kami berserah diri, dan kepada Engkaulah kami rujuk bertaubat, serta kepada Engkaulah jua tempat kembali!', FALSE, NULL, NULL, 549, 28, 219, 482, FALSE, 52, NULL),
(60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم', NULL, 'Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."', '“Wahai Tuhan kami! Janganlah Engkau jadikan pendirian dan keyakinan kami terpesong kerana penindasan orang-orang kafir, dan ampunkanlah dosa kami wahai Tuhan kami; sesungguhnya Engkaulah sahaja Yang Maha Kuasa, lagi Maha Bijaksana”.', FALSE, NULL, NULL, 549, 28, 219, 482, FALSE, 13, NULL),
(60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'لقد كان لكم فيهم اسوة حسنة لمن كان يرجو الله واليوم الاخر ومن يتول فان الله هو الغني الحميد', NULL, 'There has certainly been for you in them an excellent pattern for anyone whose hope is in Allāh and the Last Day. And whoever turns away - then indeed, Allāh is the Free of need, the Praiseworthy.', 'Demi sesungguhnya! Adalah bagi kamu pada bawaan Nabi Ibrahim dan pengikut-pengikutnya itu contoh ikutan yang baik, iaitu bagi orang yang sentiasa mengharapkan keredaan Allah dan (balasan baik) hari akhirat. Dan sesiapa yang berpaling daripada mencontohi mereka, (maka padahnya akan menimpa dirinya sendiri), kerana sesungguhnya Allah Dia lah Yang Maha Kaya, lagi Maha Terpuji.', FALSE, NULL, NULL, 550, 28, 219, 482, FALSE, 19, NULL),
(60, 7, '۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً ۚ وَٱللَّهُ قَدِيرٌ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'عسى الله ان يجعل بينكم وبين الذين عاديتم منهم مودة والله قدير والله غفور رحيم', NULL, 'Perhaps Allāh will put, between you and those to whom you have been enemies among them, affection. And Allāh is competent, and Allāh is Forgiving and Merciful.', 'Semoga Allah akan mengadakan perasaan kasih sayang antara kamu dengan orang-orang yang kamu musuhi dari kerabat kamu itu (dengan jalan menjadikan mereka insaf dan memeluk Islam). Dan (ingatlah), Allah Maha Kuasa (atas tiap-tiap sesuatu), dan Allah Maha pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 550, 28, 220, 483, FALSE, 15, NULL),
(60, 8, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَـٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَـٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين', NULL, 'Allāh does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allāh loves those who act justly.', 'Allah tidak melarang kamu daripada berbuat baik dan berlaku adil kepada orang-orang yang tidak memerangi kamu kerana ugama (kamu), dan tidak mengeluarkan kamu dari kampung halaman kamu; sesungguhnya Allah mengasihi orang-orang yang berlaku adil.', FALSE, NULL, NULL, 550, 28, 220, 483, FALSE, 21, NULL),
(60, 9, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَـٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَـٰرِكُمْ وَظَـٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'انما ينهاكم الله عن الذين قاتلوكم في الدين واخرجوكم من دياركم وظاهروا على اخراجكم ان تولوهم ومن يتولهم فاولئك هم الظالمون', NULL, 'Allāh only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers.', 'Sesungguhnya Allah hanyalah melarang kamu daripada menjadikan teman rapat orang-orang yang memerangi kamu kerana ugama (kamu), dan mengeluarkan kamu dari kampung halaman kamu, serta membantu (orang lain) untuk mengusir kamu. Dan (ingatlah), sesiapa yang menjadikan mereka teman rapat, maka mereka itulah orang-orang yang zalim.', FALSE, NULL, NULL, 550, 28, 220, 483, FALSE, 21, NULL),
(60, 10, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَـٰتُ مُهَـٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَـٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَـٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'يا ايها الذين امنوا اذا جاءكم المؤمنات مهاجرات فامتحنوهن الله اعلم بايمانهن فان علمتموهن مؤمنات فلا ترجعوهن الى الكفار لا هن حل لهم ولا هم يحلون لهن واتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا اتيتموهن اجورهن ولا تمسكوا بعصم الكوافر واسالوا ما انفقتم وليسالوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم', NULL, 'O you who have believed, when the believing women come to you as emigrants, examine [i.e., test] them. Allāh is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give them [i.e., the disbelievers] what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation [i.e., mahr]. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them [i.e., the disbelievers] ask for what they have spent. That is the judgement of Allāh; He judges between you. And Allāh is Knowing and Wise.', 'Wahai orang-orang yang beriman! Apabila orang-orang perempuan yang mengaku beriman datang berhijrah kepada kamu, maka ujilah (iman) mereka: Allah lebih mengetahui akan iman mereka: dengan yang demikian, sekiranya kamu mengetahui bahawa mereka beriman, maka janganlah kamu mengembalikan mereka kepada orang-orang yang kafir. Mereka tidak halal bagi orang-orang kafir itu (sebagai isteri), dan orang-orang kafir itu pula tidak halal bagi mereka (sebagai suami). Dan berilah kepada suami-suami (yang kafir) itu apa yang mereka telah belanjakan. Dan tidaklah menjadi salah kamu berkahwin dengan mereka (perempuan-perempuan yang berhijrah itu) apabila kamu memberi kepada mereka maskahwinnya. Dan janganlah kamu (wahai orang-orang Islam) tetap berpegang kepada akad perkahwinan kamu dengan perempuan-perempuan yang (kekal dalam keadaan) kafir, dan mintalah balik maskahwin yang kamu telah berikan, dan biarkanlah mereka (suami-suami yang kafir itu) meminta balik apa yang mereka telah belanjakan. Demikianlah hukum Allah; Ia hukumkan di antara kamu (dengan adil). Dan (ingatlah), Allah Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 550, 28, 220, 483, FALSE, 55, NULL),
(60, 11, 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'وان فاتكم شيء من ازواجكم الى الكفار فعاقبتم فاتوا الذين ذهبت ازواجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون', NULL, 'And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allāh, in whom you are believers.', 'Dan sekiranya kamu tidak dapat menerima balik sesuatu dari maskahwin isteri-isteri kamu (yang menjadi murtad serta) melarikan diri ke pihak orang-orang kafir, kemudian kamu menyerang puak yang kafir itu serta mendapat harta rampasan maka berikanlah kepada orang-orang (Islam) yang lari isterinya itu ganti maskahwinnya sebanyak yang mereka telah bayar. Dan bertaqwalah kamu kepada Allah yang kamu beriman kepadaNya.', FALSE, NULL, NULL, 550, 28, 220, 483, FALSE, 21, NULL),
(60, 12, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَـٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَـٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَـٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'يا ايها النبي اذا جاءك المؤمنات يبايعنك على ان لا يشركن بالله شيئا ولا يسرقن ولا يزنين ولا يقتلن اولادهن ولا ياتين ببهتان يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم', NULL, 'O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allāh, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allāh. Indeed, Allāh is Forgiving and Merciful.', 'Wahai Nabi! Apabila orang-orang perempuan yang beriman datang kepadamu untuk memberi pengakuan taat setia, bahawa mereka tidak akan melakukan syirik kepada Allah dengan sesuatu pun, dan mereka tidak akan mencuri, dan mereka tidak akan berzina, dan mereka tidak akan membunuh anak-anaknya, dan mereka tidak akan melakukan sesuatu perkara dusta yang mereka ada-adakan dari kemahuan hati mereka, dan mereka tidak akan menderhaka kepadamu dalam sesuatu perkara yang baik, - maka terimalah pengakuan taat setia mereka dan pohonkanlah kepada Allah mengampuni dosa mereka; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 551, 28, 220, 483, FALSE, 38, NULL),
(60, 13, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَـٰبِ ٱلْقُبُورِ', 'يا ايها الذين امنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخرة كما يئس الكفار من اصحاب القبور', NULL, 'O you who have believed, do not make allies of a people with whom Allāh has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the companions [i.e., inhabitants] of the graves.', 'Wahai orang-orang yang beriman! Janganlah kamu jadikan teman rapat mana-mana kaum yang dimurkai Allah, mereka telah berputus asa daripada mendapat kebaikan akhirat, sebagaimana berputus asanya orang-orang kafir yang ada di dalam kubur.', FALSE, NULL, NULL, 551, 28, 220, 483, FALSE, 19, NULL),
(61, 1, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم', NULL, 'Whatever is in the heavens and whatever is on the earth exalts Allāh, and He is the Exalted in Might, the Wise.', 'Segala yang ada di langit dan yang ada di bumi, tetap mengucap tasbih kepada Allah; dan Dia lah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 551, 28, 220, 484, FALSE, 11, NULL),
(61, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'يا ايها الذين امنوا لم تقولون ما لا تفعلون', NULL, 'O you who have believed, why do you say what you do not do?', 'Wahai orang-orang yang beriman! Mengapa kamu memperkatakan apa yang kamu tidak melakukannya!', FALSE, NULL, NULL, 551, 28, 220, 484, FALSE, 8, NULL),
(61, 3, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 'كبر مقتا عند الله ان تقولوا ما لا تفعلون', NULL, 'Greatly hateful in the sight of Allāh is that you say what you do not do.', 'Amat besar kebenciannya di sisi Allah - kamu memperkatakan sesuatu yang kamu tidak melakukannya.', FALSE, NULL, NULL, 551, 28, 220, 484, FALSE, 9, NULL),
(61, 4, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَـٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَـٰنٌ مَّرْصُوصٌ', 'ان الله يحب الذين يقاتلون في سبيله صفا كانهم بنيان مرصوص', NULL, 'Indeed, Allāh loves those who fight in His cause in a row as though they are a [single] structure joined firmly.', 'Sesungguhnya Allah mengasihi orang-orang yang berperang untuk membela ugamaNya, dalam barisan yang teratur rapi, seolah-olah mereka sebuah bangunan yang tersusun kukuh.', FALSE, NULL, NULL, 551, 28, 220, 484, FALSE, 11, NULL),
(61, 5, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', 'واذ قال موسى لقومه يا قوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفاسقين', NULL, 'And [mention, O Muḥammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allāh to you?" And when they deviated, Allāh caused their hearts to deviate. And Allāh does not guide the defiantly disobedient people.', 'Dan (ingatlah peristiwa) ketika Nabi Musa berkata kepada kaumnya: “Wahai kaumku! Mengapa kamu menyakiti daku, sedang kamu mengetahui bahawa sesungguhnya aku ini Pesuruh Allah kepada kamu?” Maka ketika mereka menyeleweng (dari kebenaran yang mereka sedia mengetahuinya), Allah selewengkan hati mereka (dari mendapat hidayah petunjuk); dan sememangnya Allah tidak memberi hidayah petunjuk kepada kaum yang fasik - derhaka.', FALSE, NULL, NULL, 551, 28, 220, 484, FALSE, 23, NULL),
(61, 6, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ', 'واذ قال عيسى ابن مريم يا بني اسرائيل اني رسول الله اليكم مصدقا لما بين يدي من التوراة ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينات قالوا هذا سحر مبين', NULL, 'And [mention] when Jesus, the son of Mary, said, "O Children of Israel, indeed I am the messenger of Allāh to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Aḥmad." But when he came to them with clear evidences, they said, "This is obvious magic."', 'Dan (ingatlah juga peristiwa) ketika Nabi Isa ibni Maryam berkata: “Wahai Bani Israil, sesungguhnya aku ini Pesuruh Allah kepada kamu, mengesahkan kebenaran Kitab yang diturunkan sebelumku, iaitu Kitab Taurat, dan memberikan berita gembira dengan kedatangan seorang Rasul yang akan datang kemudian daripadaku - bernama: Ahmad”. Maka ketika ia datang kepada mereka membawa keterangan-keterangan yang jelas nyata, mereka berkata: “Ini ialah sihir yang jelas nyata!”', FALSE, NULL, NULL, 552, 28, 220, 484, FALSE, 31, NULL),
(61, 7, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَـٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 'ومن اظلم ممن افترى على الله الكذب وهو يدعى الى الاسلام والله لا يهدي القوم الظالمين', NULL, 'And who is more unjust than one who invents about Allāh untruth while he is being invited to Islām. And Allāh does not guide the wrongdoing people.', 'Dan tidak ada yang lebih zalim daripada orang yang mengada-adakan perkara dusta terhadap Allah, sedang ia diajak kepada memeluk Islam; dan (ingatlah), Allah tidak memberi hidayah petunjuk kepada orang-orang yang zalim.', FALSE, NULL, NULL, 552, 28, 220, 484, FALSE, 16, NULL),
(61, 8, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', 'يريدون ليطفئوا نور الله بافواههم والله متم نوره ولو كره الكافرون', NULL, 'They want to extinguish the light of Allāh with their mouths, but Allāh will perfect His light, although the disbelievers dislike it.', 'Mereka sentiasa berusaha hendak memadamkan cahaya Allah (ugama Islam) dengan mulut mereka, sedang Allah tetap menyempurnakan cahayaNya, sekalipun orang-orang kafir tidak suka (akan yang demikian).', FALSE, NULL, NULL, 552, 28, 220, 484, FALSE, 11, NULL),
(61, 9, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون', NULL, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allāh dislike it.', 'Dia lah yang telah mengutus RasulNya (Muhammad s.a.w) dengan membawa hidayah petunjuk dan ugama yang benar (ugama Islam), supaya Ia memenangkannya dan meninggikannya atas segala ugama yang lain, walaupun orang-orang musyrik tidak menyukainya.', FALSE, NULL, NULL, 552, 28, 220, 484, FALSE, 14, NULL),
(61, 10, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَـٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', 'يا ايها الذين امنوا هل ادلكم على تجارة تنجيكم من عذاب اليم', NULL, 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?', 'Wahai orang-orang yang beriman! Mahukah Aku tunjukkan sesuatu perniagaan yang boleh menyelamatkan kamu dari azab seksa yang tidak terperi sakitnya?', FALSE, NULL, NULL, 552, 28, 220, 485, FALSE, 11, NULL),
(61, 11, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'تؤمنون بالله ورسوله وتجاهدون في سبيل الله باموالكم وانفسكم ذلكم خير لكم ان كنتم تعلمون', NULL, '[It is that] you believe in Allāh and His Messenger and strive in the cause of Allāh with your wealth and your lives. That is best for you, if you only knew.', 'Iaitu, kamu beriman kepada Allah dan rasulNya, serta kamu berjuang membela dan menegakkan ugama Allah dengan harta benda dan diri kamu; yang demikian itulah yang lebih baik bagi kamu, jika kamu hendak mengetahui (hakikat yang sebenarnya).', FALSE, NULL, NULL, 552, 28, 220, 485, FALSE, 15, NULL),
(61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يغفر لكم ذنوبكم ويدخلكم جنات تجري من تحتها الانهار ومساكن طيبة في جنات عدن ذلك الفوز العظيم', NULL, 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.', '(Dengan itu) Allah akan mengampunkan dosa-dosa kamu, dan memasukkan kamu ke dalam taman-taman yang mengalir di bawahnya beberapa sungai, serta ditempatkan kamu di tempat-tempat tinggal yang baik dalam Syurga “Adn”. Itulah kemenangan yang besar.', FALSE, NULL, NULL, 552, 28, 220, 485, FALSE, 17, NULL),
(61, 13, 'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'واخرى تحبونها نصر من الله وفتح قريب وبشر المؤمنين', NULL, 'And [you will obtain] another [favor] that you love - victory from Allāh and an imminent conquest; and give good tidings to the believers.', 'Dan ada lagi limpah kurnia yang kamu sukai, iaitu pertolongan dari Allah dan kemenangan yang cepat (masa berlakunya). Dan sampaikanlah berita yang mengembirakan itu kepada orang-orang yang beriman.', FALSE, NULL, NULL, 552, 28, 220, 485, FALSE, 9, NULL),
(61, 14, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَـٰهِرِينَ', 'يا ايها الذين امنوا كونوا انصار الله كما قال عيسى ابن مريم للحواريين من انصاري الى الله قال الحواريون نحن انصار الله فامنت طائفة من بني اسرائيل وكفرت طائفة فايدنا الذين امنوا على عدوهم فاصبحوا ظاهرين', NULL, 'O you who have believed, be supporters of Allāh, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allāh?" The disciples said, "We are supporters of Allāh." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.', 'Wahai orang-orang yang beriman! Jadikanlah diri kamu pembela-pembela (ugama) Allah sebagaimana (keadaan penyokong-penyokong) Nabi Isa ibni Maryam (ketika ia) berkata kepada penyokong-penyokongnya itu: “Siapakah penolong-penolongku (dalam perjalananku) kepada Allah (dengan menegakkan ugamaNya)?” Mereka menjawab: “Kamilah pembela-pembela (ugama) Allah!” (Setelah Nabi Isa tidak berada di antara mereka) maka sepuak dari kaum Bani Israil beriman, dan sepuak lagi (tetap) kafir. Lalu Kami berikan pertolongan kepada orang-orang yang beriman untuk mengalahkan musuhnya, maka menjadilah mereka orang-orang yang menang.', FALSE, NULL, NULL, 552, 28, 220, 485, FALSE, 35, NULL),
(62, 1, 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'يسبح لله ما في السماوات وما في الارض الملك القدوس العزيز الحكيم', NULL, 'Whatever is in the heavens and whatever is on the earth is exalting Allāh, the Sovereign, the Pure, the Exalted in Might, the Wise.', 'Segala yang ada di langit dan yang ada di bumi sentiasa mengucap tasbih kepada Allah Yang Menguasai (sekalian alam), Yang Maha Suci, Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 12, NULL),
(62, 2, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ', 'هو الذي بعث في الاميين رسولا منهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمة وان كانوا من قبل لفي ضلال مبين', NULL, 'It is He who has sent among the unlettered [Arabs] a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book [i.e., the Qur’ān] and wisdom [i.e., the sunnah] - although they were before in clear error -', 'Dia lah yang telah mengutuskan dalam kalangan orang-orang (Arab) yang Ummiyyin, seorang Rasul (Nabi Muhammad s.a.w) dari bangsa mereka sendiri, yang membacakan kepada mereka ayat-ayat Allah (yang membuktikan keesaan Allah dan kekuasaanNya), dan membersihkan mereka (dari iktiqad yang sesat), serta mengajarkan mereka Kitab Allah (Al-Quran) dan Hikmah (pengetahuan yang mendalam mengenai hukum-hukum syarak). Dan sesungguhnya mereka sebelum (kedatangan Nabi Muhammad) itu adalah dalam kesesatan yang nyata.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 21, NULL),
(62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'واخرين منهم لما يلحقوا بهم وهو العزيز الحكيم', NULL, 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.', 'Dan juga (telah mengutuskan Nabi Muhammad kepada) orang-orang yang lain dari mereka, yang masih belum (datang lagi dan tetap akan datang) menghubungi mereka; dan (ingatlah), Allah jualah Yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 8, NULL),
(62, 4, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم', NULL, 'That is the bounty of Allāh, which He gives to whom He wills, and Allāh is the possessor of great bounty.', '(Pengutusan Nabi Muhammad s.a.w, kepada umat manusia seluruhnya) itu (yang menjadi rahmat) adalah limpah kurnia Allah, diberikanNya kepada sesiapa yang dikehendakiNya; dan sememangnya Allah mempunyai limpah kurnia yang besar.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 10, NULL),
(62, 5, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 'مثل الذين حملوا التوراة ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بايات الله والله لا يهدي القوم الظالمين', NULL, 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allāh. And Allāh does not guide the wrongdoing people.', '(Sifat-sifat Nabi Muhammad itu telahpun diterangkan dalam Kitab Taurat tetapi orang-orang Yahudi tidak juga mempercayainya, maka) bandingan orang-orang (Yahudi) yang ditanggungjawab dan ditugaskan (mengetahui dan melaksanakan hukum) Kitab Taurat, kemudian mereka tidak menyempurnakan tanggungjawab dan tugas itu, samalah seperti keldai yang memikul bendela Kitab-kitab besar (sedang ia tidak mengetahui kandungannya). Buruk sungguh bandingan kaum yang mendustakan ayat-ayat keterangan Allah; dan (ingatlah), Allah tidak memberi hidayah petunjuk kepada kaum yang zalim.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 23, NULL),
(62, 6, 'قُلْ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ', 'قل يا ايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صادقين', NULL, 'Say, "O you who are Jews, if you claim that you are allies of Allāh, excluding the [other] people, then wish for death, if you should be truthful."', 'Katakanlah (wahai Muhammad): “Wahai orang-orang yang berugama Yahudi, kalau kamu anggap bahawa kamulah sahaja orang-orang yang dikasihi Allah tidak termasuk umat-umat manusia yang lain, maka bercita-citalah hendakkan mati (dengan meminta kepada Allah supaya kamu dimatikan sekarang juga), jika betul kamu orang-orang yang benar!”', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 17, NULL),
(62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', 'ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظالمين', NULL, 'But they will not wish for it, ever, because of what their hands have put forth. And Allāh is Knowing of the wrongdoers.', 'Dan (sudah tentu) mereka tidak akan bercita-cita hendakkan mati itu selama-lamanya, dengan sebab dosa-dosa yang mereka telah lakukan; dan Allah sentiasa mengetahui akan orang-orang yang zalim itu.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 9, NULL),
(62, 8, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَـٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'قل ان الموت الذي تفرون منه فانه ملاقيكم ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون', NULL, 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."', 'Katakanlah (wahai Muhammad): “Sebenarnya maut yang kamu melarikan diri daripadanya itu, tetaplah ia akan menemui kamu; kemudian kamu akan dikembalikan kepada Allah yang mengetahui segala yang ghaib dan yang nyata, lalu Ia memberitahu kepada kamu apa yang kamu telah lakukan (serta membalasnya)”.', FALSE, NULL, NULL, 553, 28, 221, 486, FALSE, 18, NULL),
(62, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'يا ايها الذين امنوا اذا نودي للصلاة من يوم الجمعة فاسعوا الى ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون', NULL, 'O you who have believed, when [the adhān] is called for the prayer on the day of Jumuʿah [Friday], then proceed to the remembrance of Allāh and leave trade. That is better for you, if you only knew.', 'Wahai orang-orang yang beriman! Apabila diserukan azan (bang) untuk mengerjakan sembahyang pada hari Jumaat, maka segeralah kamu pergi (ke masjid) untuk mengingati Allah (dengan mengerjakan sembahyang jumaat) dan tinggalkanlah berjual-beli (pada saat itu); yang demikian adalah baik bagi kamu, jika kamu mengetahui (hakikat yang sebenarnya),', FALSE, NULL, NULL, 554, 28, 221, 487, FALSE, 21, NULL),
(62, 10, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'فاذا قضيت الصلاة فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون', NULL, 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allāh, and remember Allāh often that you may succeed.', 'Kemudian setelah selesai sembahyang, maka bertebaranlah kamu di muka bumi (untuk menjalankan urusan masing-masing), dan carilah apa yang kamu hajati dari limpah kurnia Allah, serta ingatlah akan Allah banyak-banyak (dalam segala keadaan), supaya kamu berjaya (di dunia dan di akhirat).', FALSE, NULL, NULL, 554, 28, 221, 487, FALSE, 15, NULL),
(62, 11, 'وَإِذَا رَأَوْا۟ تِجَـٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَـٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'واذا راوا تجارة او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجارة والله خير الرازقين', NULL, 'But [on one occasion] when they saw a transaction or a diversion, [O Muḥammad], they rushed to it and left you standing. Say, "What is with Allāh is better than diversion and than a transaction, and Allāh is the best of providers."', 'Dan apabila mereka mengetahui kedatangan barang-barang dagangan (yang baharu tiba) atau (mendengar) sesuatu hiburan, mereka bersurai (lalu pergi) kepadanya dengan meninggalkan engkau berdiri (di atas mimbar - berkhutbah). Katakanlah (wahai Muhammad: “Pahala - balasan) yang ada di sisi Allah, lebih baik dari hiburan dan barang-barang dagangan itu; dan Allah sebaik-baik pemberi rezeki.', FALSE, NULL, NULL, 554, 28, 221, 487, FALSE, 21, NULL),
(63, 1, 'إِذَا جَآءَكَ ٱلْمُنَـٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَـٰفِقِينَ لَكَـٰذِبُونَ', 'اذا جاءك المنافقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنافقين لكاذبون', NULL, 'When the hypocrites come to you, [O Muḥammad], they say, "We testify that you are the Messenger of Allāh." And Allāh knows that you are His Messenger, and Allāh testifies that the hypocrites are liars.', 'Apabila orang-orang munafik datang kepadamu (wahai Muhammad), mereka berkata: “Kami mengakui bahawa sesungguhnya engkau - sebenar-benarnya Rasul Allah”. Dan Allah sememangnya mengetahui bahawa engkau ialah RasulNya, serta Allah menyaksikan bahawa sesungguhnya pengakuan mereka adalah dusta.', FALSE, NULL, NULL, 554, 28, 221, 488, FALSE, 17, NULL),
(63, 2, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'اتخذوا ايمانهم جنة فصدوا عن سبيل الله انهم ساء ما كانوا يعملون', NULL, 'They have taken their oaths as a cover, so they averted [people] from the way of Allāh. Indeed, it was evil that they were doing.', 'Mereka menjadikan sumpahnya (atau akuannya) sebagai perisai (untuk menyelamatkan dirinya dan harta bendanya daripada dibunuh atau dirampas), lalu mereka menghalang (dirinya dan orang lain) dari menurut jalan Allah. Sesungguhnya amatlah buruk apa yang mereka telah kerjakan.', FALSE, NULL, NULL, 554, 28, 221, 488, FALSE, 12, NULL),
(63, 3, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'ذلك بانهم امنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون', NULL, 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.', '(Perbuatan buruk) yang demikian kerana mereka mengaku beriman (di hadapan orang-orang Islam) kemudian mereka tetap kafir sesama sendiri, maka dengan sebab itu dimeteraikan atas hati mereka; lalu mereka tidak dapat memahami (yang mana benar dan yang mana salah).', FALSE, NULL, NULL, 554, 28, 221, 488, FALSE, 11, NULL),
(63, 4, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', 'واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسندة يحسبون كل صيحة عليهم هم العدو فاحذرهم قاتلهم الله انى يؤفكون', NULL, 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allāh destroy them; how are they deluded?', 'Dan apabila engkau melihat mereka, engkau tertarik hati kepada tubuh badan mereka (dan kelalukannya); dan apabila mereka berkata-kata, engkaujuga (tertarik hati) mendengar tutur katanya (kerana manis dan fasih. Dalam pada itu) mereka adalah seperti batang-batang kayu yang tersandar (tidak terpakai kerana tidak ada padanya kekuatan yang dikehendaki). Mereka (kerana merasai bersalah, sentiasa dalam keadaan cemas sehingga) menyangka tiap-tiap jeritan (atau riuh rendah yang mereka dengar) adalah untuk membahayakan mereka. Mereka itulah musuh yang sebenar-benarnya maka berjaga-jagalah engkau terhadap mereka. Semoga Allah membinasa dan menyingkirkan mereka dari rahmatNya. (Pelik sungguh!) Bagaimana mereka dipalingkan (oleh hawa nafsunya - dari kebenaran)?', FALSE, NULL, NULL, 554, 28, 222, 488, FALSE, 22, NULL),
(63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون', NULL, 'And when it is said to them, "Come, the Messenger of Allāh will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.', 'Dan apabila dikatakan kepada mereka: “Marilah (bertaubat) supaya Rasulullah meminta ampun (kepada Allah) untuk kamu”, mereka (enggan sambil) menggeleng-gelengkan kepalanya; dan engkau melihat mereka berpaling (dari bertaubat) serta mereka berlaku sombong angkuh.', FALSE, NULL, NULL, 555, 28, 222, 488, FALSE, 14, NULL),
(63, 6, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', 'سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفاسقين', NULL, 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allāh forgive them. Indeed, Allāh does not guide the defiantly disobedient people.', '(Tidak ada faedahnya) kepada mereka, sama ada engkau meminta ampun untuk mereka atau engkau tidak meminta ampun, Allah tidak sekali-kali akan mengampunkan mereka. Sesungguhnya Allah tidak memberi hidayah petunjuk kepada kaum yang fasik.', FALSE, NULL, NULL, 555, 28, 222, 488, FALSE, 18, NULL),
(63, 7, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَفْقَهُونَ', 'هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا ولله خزائن السماوات والارض ولكن المنافقين لا يفقهون', NULL, 'They are the ones who say, "Do not spend on those who are with the Messenger of Allāh until they disband." And to Allāh belong the depositories of the heavens and the earth, but the hypocrites do not understand.', 'Merekalah yang mengatakan (kepada orang-orang Islam di Madinah yang menolong Rasulullah dan orang-orang Muhajirin): “Janganlah kamu membelanjakan harta kamu kepada orang-orang yang ada bersama-sama Rasulullah supaya mereka bersurai (meninggalkannya)”. Padahal bagi Allah jualah perbendaharaan langit dan bumi, (tiada sesiapapun yang dapat memberi atau menyekat sebarang pemberian melainkan dengan kehendakNya); akan tetapi orang-orang yang munafik itu tidak memahami (hakikat yang sebenarnya).', FALSE, NULL, NULL, 555, 28, 222, 488, FALSE, 20, NULL),
(63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَعْلَمُونَ', 'يقولون لئن رجعنا الى المدينة ليخرجن الاعز منها الاذل ولله العزة ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون', NULL, 'They say, "If we return to al-Madīnah, the more honored [for power] will surely expel therefrom the more humble." And to Allāh belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.', 'Mereka berkata lagi: “Demi sesungguhnya! Jika kita kembali ke Madinah (dari medan perang), sudah tentu orang-orang yang mulia lagi kuat (pihak kita) akan mengusir keluar dari Madinah orang-orang yang hina lagi lemah (pihak Islam)”. Padahal bagi Allah jualah kemuliaan dan kekuatan itu dan bagi RasulNya serta bagi orang-orang yang beriman; akan tetapi golongan yang munafik itu tidak mengetahui (hakikat yang sebenarnya).', FALSE, NULL, NULL, 555, 28, 222, 488, FALSE, 17, NULL),
(63, 9, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَـٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', 'يا ايها الذين امنوا لا تلهكم اموالكم ولا اولادكم عن ذكر الله ومن يفعل ذلك فاولئك هم الخاسرون', NULL, 'O you who have believed, let not your wealth and your children divert you from the remembrance of Allāh. And whoever does that - then those are the losers.', 'Wahai orang-orang yang beriman! Janganlah kamu dilalaikan oleh (urusan) harta benda kamu dan anak-pinak kamu daripada mengingati Allah (dengan menjalankan perintahNya). Dan (ingatlah), sesiapa yang melakukan demikian, maka mereka itulah orang-orang yang rugi.', FALSE, NULL, NULL, 555, 28, 222, 489, FALSE, 17, NULL),
(63, 10, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ', 'وانفقوا من ما رزقناكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الى اجل قريب فاصدق واكن من الصالحين', NULL, 'And spend [in the way of Allāh] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be of the righteous."', 'Dan belanjakanlah (dermakanlah) sebahagian dari rezeki yang Kami berikan kepada kamu sebelum seseorang dari kamu sampai ajal maut kepadanya, (kalau tidak) maka ia (pada saat itu) akan merayu dengan katanya: “Wahai Tuhanku! Alangkah baiknya kalau Engkau lambatkan kedatangan ajal matiku - ke suatu masa yang sedikit sahaja lagi, supaya aku dapat bersedekah dan dapat pula aku menjadi dari orang-orang yang soleh”.', FALSE, NULL, NULL, 555, 28, 222, 489, FALSE, 21, NULL),
(63, 11, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون', NULL, 'But never will Allāh delay a soul when its time has come. And Allāh is Aware of what you do.', 'Dan (ingatlah), Allah tidak sekali-kali akan melambatkan kematian seseorang (atau sesuatu yang bernyawa) apabila sampai ajalnya; dan Allah Amat Mendalam PengetahuanNya mengenai segala yang kamu kerjakan.', FALSE, NULL, NULL, 555, 28, 222, 489, FALSE, 11, NULL),
(64, 1, 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'يسبح لله ما في السماوات وما في الارض له الملك وله الحمد وهو على كل شيء قدير', NULL, 'Whatever is in the heavens and whatever is on the earth is exalting Allāh. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.', 'Segala yang ada di langit dan yang ada di bumi sentiasa mengucap tasbih kepada Allah; bagiNyalah kuasa pemerintahan, dan bagiNyalah segala pujian; dan Ia Maha Kuasa atas tiap-tiap sesuatu.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 17, NULL),
(64, 2, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير', NULL, 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allāh, of what you do, is Seeing.', 'Dia lah yang mengaturkan kejadian kamu; maka ada sebahagian dari kamu yang kafir dan ada sebahagian dari kamu yang beriman; dan Allah Maha Melihat akan segala yang kamu kerjakan (serta membalas masing-masing).', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 11, NULL),
(64, 3, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'خلق السماوات والارض بالحق وصوركم فاحسن صوركم واليه المصير', NULL, 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.', 'Ia menciptakan langit dan bumi dengan cara yang sungguh layak dan berhikmat, dan Ia menentukan bentuk rupa kamu serta memperelokkan rupa kamu; dan kepadaNyalah tempat kembali.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 9, NULL),
(64, 4, 'يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'يعلم ما في السماوات والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور', NULL, 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allāh is Knowing of that within the breasts.', 'Ia mengetahui segala yang ada di langit dan di bumi; dan Ia mengetahui segala yang kamu rahsiakan serta yang kamu zahirkan; dan Allah sentiasa Mengetahui segala (isi hati) yang terkandung di dalam dada;', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 14, NULL),
(64, 5, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'الم ياتكم نبا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم', NULL, 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.', 'Bukankah telah sampai kepada kamu berita orang-orang kafir yang telah lalu? Lalu mereka merasai kesan yang buruk dari perbuatan kufur mereka; dan mereka (pada hari akhirat kelak) beroleh azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 13, NULL),
(64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', 'ذلك بانه كانت تاتيهم رسلهم بالبينات فقالوا ابشر يهدوننا فكفروا وتولوا واستغنى الله والله غني حميد', NULL, 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allāh dispensed [with them]; and Allāh is Free of need and Praiseworthy.', '(Balasan) yang demikian itu, kerana sesungguhnya mereka pernah didatangi Rasul-rasul (yang diutus kepada) mereka dengan membawa keterangan-keterangan yang jelas nyata, maka mereka berkata: “Patutkah manusia (yang seperti kami - menjadi Rasul untuk) memberi petunjuk kepada kami?” Lalu mereka kufur ingkar serta berpaling (dari kebenaran); dan Allah pun menyatakan tidak berhajatNya (kepada iman dan ketaatan mereka lalu membinasakan mereka); dan Allah sememangnya Maha Kaya, lagi tetap Terpuji.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 16, NULL),
(64, 7, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'زعم الذين كفروا ان لن يبعثوا قل بلى وربي لتبعثن ثم لتنبؤن بما عملتم وذلك على الله يسير', NULL, 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allāh, is easy."', '(Di antara sebab-sebab kufur) orang-orang yang kafir (ialah kerana mereka) mengatakan bahawa mereka tidak sekali-kali akan di bangkitkan (sesudah mati). Katakanlah: “Bahkan, demi Tuhanku, kamu akan dibangkitkan, kemudian kamu akan diberitahu tentang segala yang kamu telah kerjakan. Dan yang demikian itu adalah mudah bagi Allah melaksanakannya.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 18, NULL),
(64, 8, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير', NULL, 'So believe in Allāh and His Messenger and the light [i.e., the Qur’ān] which We have sent down. And Allāh is Aware of what you do.', 'Oleh itu, berimanlah kamu kepada Allah dan kepada rasulNya serta kepada penerangan cahaya Al-Quran - yang Kami turunkan. Dan (ingatlah), Allah Amat Mendalam PengetahuanNya akan segala yang kamu kerjakan.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 10, NULL),
(64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صالحا يكفر عنه سيئاته ويدخله جنات تجري من تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم', NULL, 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allāh and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', '(Ingatkanlah) masa Allah menghimpunkan kamu pada hari perhimpunan (untuk menerima balasan), - itulah hari masing-masing nampak kerugiannya. Dan (ingatlah), sesiapa yang beriman kepada Allah serta mengerjakan amal soleh, nescaya Allah mengampunkan dosa-dosanya dan memasukkannya ke dalam Syurga yang mengalir di bawahnya beberapa sungai, mereka kekal di dalamnya selama-lamanya; yang demikian itulah kemenangan yang besar.', FALSE, NULL, NULL, 556, 28, 222, 490, FALSE, 27, NULL),
(64, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ خَـٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', 'والذين كفروا وكذبوا باياتنا اولئك اصحاب النار خالدين فيها وبئس المصير', NULL, 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.', 'Dan orang-orang yang kafir serta mendustakan ayat-ayat keterangan Kami, merekalah ahli neraka, kekalah mereka di dalamnya; dan itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 557, 28, 222, 490, FALSE, 11, NULL),
(64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'ما اصاب من مصيبة الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم', NULL, 'No disaster strikes except by permission of Allāh. And whoever believes in Allāh - He will guide his heart. And Allāh is Knowing of all things.', 'Tidak ada kesusahan (atau bala bencana) yang menimpa (seseorang) melainkan dengan izin Allah; dan sesiapa yang beriman kepada Allah, Allah akan memimpin hatinya (untuk menerima apa yang telah berlaku itu dengan tenang dan sabar); dan (ingatlah), Allah Maha Mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 16, NULL),
(64, 12, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ', 'واطيعوا الله واطيعوا الرسول فان توليتم فانما على رسولنا البلاغ المبين', NULL, 'And obey Allāh and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.', 'Dan taatlah kamu kepada Allah serta taatlah kepada Rasulullah; maka kalau kamu berpaling (enggan taat, kamulah yang akan menderita balasannya yang buruk), kerana sesungguhnya kewajipan Rasul Kami hanyalah menyampaikan (perintah-perintah) dengan jelas nyata.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 11, NULL),
(64, 13, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'الله لا اله الا هو وعلى الله فليتوكل المؤمنون', NULL, 'Allāh - there is no deity except Him. And upon Allāh let the believers rely.', 'Allah, tiada Tuhan melainkan Dia; dan dengan yang demikian, kepada Allah jualah orang-orang yang beriman wajib berserah diri.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 9, NULL),
(64, 14, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَـٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'يا ايها الذين امنوا ان من ازواجكم واولادكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم', NULL, 'O you who have believed, indeed, among your spouses and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allāh is Forgiving and Merciful.', 'Wahai orang-orang yang beriman! Sesungguhnya ada di antara isteri-isteri kamu dan anak-anak kamu yang menjadi musuh bagi kamu; oleh itu awaslah serta berjaga-jagalah kamu terhadap mereka. Dan kalau kamu memaafkan dan tidak marahkan (mereka) serta mengampunkan kesalahan mereka (maka Allah akan berbuat demikian kepada kamu), kerana sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 18, NULL),
(64, 15, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'انما اموالكم واولادكم فتنة والله عنده اجر عظيم', NULL, 'Your wealth and your children are but a trial, and Allāh has with Him a great reward.', 'Sesungguhnya harta benda kamu dan anak-anak kamu itu hanyalah menjadi ujian, dan di sisi Allah jualah pahala yang besar.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 8, NULL),
(64, 16, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولئك هم المفلحون', NULL, 'So fear Allāh as much as you are able and listen and obey and spend [in the way of Allāh]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', 'Oleh itu bertaqwalah kamu kepada Allah sedaya supaya kamu; dan dengarlah (akan pengajaran-pengajaranNya) serta taatlah (akan perintah-perintahNya); dan belanjakanlah harta kamu (serta buatlah) kebajikan untuk diri kamu. Dan (ingatlah), sesiapa yang menjaga serta memelihara dirinya daripada dipengaruhi oleh tabiat bakhilnya, maka merekalah orang-orang yang berjaya.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 16, NULL),
(64, 17, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 'ان تقرضوا الله قرضا حسنا يضاعفه لكم ويغفر لكم والله شكور حليم', NULL, 'If you loan Allāh a goodly loan, He will multiply it for you and forgive you. And Allāh is [most] Appreciative and Forbearing,', 'Dan kalau kamu memberi pinjaman kepada Allah, sebagai pinjaman yang baik (ikhlas), nescaya Allah akan melipat gandakan balasanNya kepada kamu serta mengampunkan dosa-dosa kamu; dan Allah amat memberi penghargaan dan balasan kepada golongan yang berbuat baik, lagi Maha Penyabar (untuk memberi peluang kepada golongan yang bersalah supaya bertaubat).', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 12, NULL),
(64, 18, 'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'عالم الغيب والشهادة العزيز الحكيم', NULL, 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.', 'Dia lah yang mengetahui segala yang ghaib dan yang nyata, (dan Dia lah jua) yang Maha Kuasa, lagi Maha Bijaksana.', FALSE, NULL, NULL, 557, 28, 222, 491, FALSE, 5, NULL),
(65, 1, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العدة واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفاحشة مبينة وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا', NULL, 'O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allāh, your Lord. Do not turn them out of their [husbands''] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allāh. And whoever transgresses the limits of Allāh has certainly wronged himself. You know not; perhaps Allāh will bring about after that a [different] matter.', 'Wahai Nabi! Apabila kamu - (engkau dan umatmu) - hendak menceraikan isteri-isteri (kamu), maka ceraikanlah mereka pada masa mereka dapat memulakan idahnya, dan hitunglah masa idah itu (dengan betul), serta bertaqwalah kepada Allah, Tuhan kamu. Janganlah kamu mengeluarkan mereka dari rumah-rumah kediamannya (sehingga selesai idahnya), dan janganlah pula (dibenarkan) mereka keluar (dari situ), kecuali (jika) mereka melakukan perbuatan keji yang nyata. Dan itulah aturan-aturan hukum Allah (maka janganlah kamu melanggarnya); dan sesiapa yang melanggar aturan-aturan hukum Allah maka sesungguhnya ia telah berlaku zalim kepada dirinya. (Patuhilah hukum-hukum itu, kerana) engkau tidak mengetahui boleh jadi Allah akan mengadakan, sesudah itu, sesuatu perkara (yang lain).', FALSE, NULL, NULL, 558, 28, 223, 492, FALSE, 41, NULL),
(65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', 'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهادة لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا', NULL, 'And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allāh. That is instructed to whoever should believe in Allāh and the Last Day. And whoever fears Allāh - He will make for him a way out', 'Kemudian, apabila mereka (hampir) habis tempoh idahnya, maka bolehlah kamu pegang mereka (rujuk) dengan cara yang baik, atau lepaskan mereka dengan cara yang baik; dan adakanlah dua orang saksi yang adil di antara kamu (semasa kamu merujukkan atau melepaskannya); dan hendaklah kamu (yang menjadi saksi) menyempurnakan persaksian itu kerana Allah semata-mata. Dengan hukum-hukum yang tersebut diberi peringatan dan pengajaran kepada sesiapa yang beriman kepada Allah dan hari akhirat; dan sesiapa yang bertaqwa kepada Allah (dengan mengerjakan suruhanNya dan meninggalkan laranganNya), nescaya Allah akan mengadakan baginya jalan keluar (dari segala perkara yang menyusahkannya),', FALSE, NULL, NULL, 558, 28, 223, 492, FALSE, 30, NULL),
(65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', 'ويرزقه من حيث لا يحتسب ومن يتوكل على الله فهو حسبه ان الله بالغ امره قد جعل الله لكل شيء قدرا', NULL, 'And will provide for him from where he does not expect. And whoever relies upon Allāh - then He is sufficient for him. Indeed, Allāh will accomplish His purpose. Allāh has already set for everything a [decreed] extent.', 'Serta memberinya rezeki dari jalan yang tidak terlintas di hatinya. Dan (Ingatlah), sesiapa berserah diri bulat-bulat kepada Allah, maka Allah cukuplah baginya (untuk menolong dan menyelamatkannya). Sesungguhnya Allah tetap melakukan segala perkara yang dikehendakiNya. Allah telahpun menentukan kadar dan masa bagi berlakunya tiap-tiap sesuatu.', FALSE, NULL, NULL, 558, 28, 223, 492, FALSE, 21, NULL),
(65, 4, 'وَٱلَّـٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشْهُرٍ وَٱلَّـٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَـٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', 'واللائي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلاثة اشهر واللائي لم يحضن واولات الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا', NULL, 'And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allāh - He will make for him of his matter ease.', 'Dan perempuan-perempuan dari kalangan kamu yang putus asa dari kedatangan haid, jika kamu menaruh syak (terhadap tempoh idah mereka) maka idahnya ialah tiga bulan; dan (demikian) juga idah perempuan-perempuan yang tidak berhaid. Dan perempuan-perempuan mengandung, tempoh idahnya ialah hingga mereka melahirkan anak yang dikandungnya. Dan (ingatlah), sesiapa yang bertaqwa kepada Allah, nescaya Allah memudahkan baginya segala urusannya.', FALSE, NULL, NULL, 558, 28, 223, 492, FALSE, 28, NULL),
(65, 5, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سيئاته ويعظم له اجرا', NULL, 'That is the command of Allāh, which He has sent down to you; and whoever fears Allāh - He will remove for him his misdeeds and make great for him his reward.', 'Peraturan-peraturan yang demikian adalah hukum-hukum Allah yang diturunkan dan diterangkanNya kepada kamu; dan (ingatlah), sesiapa yang bertaqwa kepada Allah, nescaya Allah menghapuskan kesalahan-kesalahannya, dan akan membesarkan pahala balasannya.', FALSE, NULL, NULL, 558, 28, 223, 492, FALSE, 14, NULL),
(65, 6, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولات حمل فانفقوا عليهن حتى يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخرى', NULL, 'Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for him [i.e., the father] another woman.', 'Tempatkanlah isteri-isteri (yang menjalani idahnya) itu di tempat kediaman kamu sesuai dengan kemampuan kamu; dan janganlah kamu adakan sesuatu yang menyakiti mereka (di tempat tinggal itu) dengan tujuan hendak menyusahkan kedudukan mereka (supaya mereka keluar meninggalkan tempat itu). Dan jika mereka berkeadaan sedang mengandung, maka berikanlah kepada mereka nafkahnya sehingga mereka melahirkan anak yang dikandungnya; kemudian jika mereka menyusukan anak untuk kamu, maka berikanlah kepada mereka upahnya; dan berundinglah di antara kamu (dalam hal menyusunya) dengan cara yang baik. Dan (sebaliknya) jika kamu (dari kedua pihak) mengalami kesulitan, maka bolehlah perempuan lain menyusukannya.', FALSE, NULL, NULL, 559, 28, 223, 492, FALSE, 32, NULL),
(65, 7, 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', 'لينفق ذو سعة من سعته ومن قدر عليه رزقه فلينفق مما اتاه الله لا يكلف الله نفسا الا ما اتاها سيجعل الله بعد عسر يسرا', NULL, 'Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allāh has given him. Allāh does not charge a soul except [according to] what He has given it. Allāh will bring about, after hardship, ease [i.e., relief].', 'Hendaklah orang yang mampu memberi nafkah menurut kemampuannya; dan sesiapa yang di sempitkan rezekinya, maka hendaklah ia memberi nafkah dari apa yang diberikan Allah kepadanya (sekadar yang mampu); Allah tidak memberati seseorang melainkan (sekadar kemampuan) yang diberikan Allah kepadanya. (Orang-orang yang dalam kesempitan hendaklah ingat bahawa) Allah akan memberikan kesenangan sesudah berlakunya kesusahan.', FALSE, NULL, NULL, 559, 28, 223, 492, FALSE, 25, NULL),
(65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَـٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَـٰهَا عَذَابًا نُّكْرًا', 'وكاين من قرية عتت عن امر ربها ورسله فحاسبناها حسابا شديدا وعذبناها عذابا نكرا', NULL, 'And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment.', 'Dan bukan sedikit negeri-negeri yang penduduknya menderhaka terhadap perintah Tuhan mereka dan Rasul-rasulNya, maka Kami hitung amal mereka satu persatu dengan hitungan yang keras rapi, serta Kami seksakan mereka dengan azab yang tidak pernah dikenal dahsyatnya.', FALSE, NULL, NULL, 559, 28, 223, 493, FALSE, 14, NULL),
(65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَـٰقِبَةُ أَمْرِهَا خُسْرًا', 'فذاقت وبال امرها وكان عاقبة امرها خسرا', NULL, 'And it tasted the bad consequence of its affair [i.e., rebellion], and the outcome of its affair was loss.', 'Lalu mereka merasai kesan yang buruk dari perbuatan derhakanya, dan menjadilah akibat perbuatan mereka satu kerugian yang besar.', FALSE, NULL, NULL, 559, 28, 223, 493, FALSE, 7, NULL),
(65, 10, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', 'اعد الله لهم عذابا شديدا فاتقوا الله يا اولي الالباب الذين امنوا قد انزل الله اليكم ذكرا', NULL, 'Allāh has prepared for them a severe punishment; so fear Allāh, O you of understanding who have believed. Allāh has sent down to you a message [i.e., the Qur’ān].', 'Allah menyediakan bagi mereka azab seksa yang seberat-beratnya. Maka bertaqwalah kepada Allah kepada wahai orang yang berakal sempurna dari kalangan orang yang beriman. Sesungguhnya Allah telah menurunkan kepada kamu peringatan -', FALSE, NULL, NULL, 559, 28, 223, 493, FALSE, 16, NULL),
(65, 11, 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِ ٱللَّهِ مُبَيِّنَـٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 'رسولا يتلو عليكم ايات الله مبينات ليخرج الذين امنوا وعملوا الصالحات من الظلمات الى النور ومن يؤمن بالله ويعمل صالحا يدخله جنات تجري من تحتها الانهار خالدين فيها ابدا قد احسن الله له رزقا', NULL, '[He sent] a Messenger [i.e., Muḥammad (ﷺ)] reciting to you the distinct verses of Allāh that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allāh and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allāh will have perfected for him a provision.', '(Dengan mengutuskan) seorang Rasul (Nabi Muhammad s.a.w) yang membacakan kepada kamu ayat-ayat Allah yang menerangkan kebenaran, supaya Allah mengeluarkan orang-orang (yang sedia diketahuiNya akan) beriman dan beramal soleh - dari gelap-gelita (kesesatan) kepada cahaya (hidayah petunjuk). Dan (ingatlah), sesiapa yang beriman kepada Allah dan beramal soleh, akan dimasukkan oleh Allah ke dalam Syurga yang mengalir di bawahnya beberapa sungai; kekalah mereka di dalamnya selama-lamanya. Sesungguhnya Allah (dengan yang demikian) telah mengurniakan kepadanya sebaik-baik pemberian.', FALSE, NULL, NULL, 559, 28, 223, 493, FALSE, 34, NULL),
(65, 12, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'الله الذي خلق سبع سماوات ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله على كل شيء قدير وان الله قد احاط بكل شيء علما', NULL, 'It is Allāh who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allāh is over all things competent and that Allāh has encompassed all things in knowledge.', 'Allah yang menciptakan tujuh petala langit dan (Ia menciptakan) bumi seperti itu; perintah Allah berlaku terus menerus di antara alam langit dan bumi. (Berlakunya yang demikian) supaya kamu mengetahui bahawa sesungguhnya Allah Maha Kuasa atas tiap-tiap sesuatu, dan bahawa sesungguhnya Allah tetap meliputi ilmuNya akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 559, 28, 223, 493, FALSE, 25, NULL),
(66, 1, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'يا ايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازواجك والله غفور رحيم', NULL, 'O Prophet, why do you prohibit [yourself from] what Allāh has made lawful for you, seeking the approval of your wives? And Allāh is Forgiving and Merciful.', 'Wahai Nabi! Mengapa engkau haramkan (dengan bersumpah menyekat dirimu daripada menikmati) apa yang dihalalkan oleh Allah bagimu, (kerana) engkau hendak mencari keredaan isteri-isterimu? (Dalam pada itu, Allah ampunkan kesilapanmu itu) dan Allah sememangnya Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 14, NULL),
(66, 2, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَـٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قد فرض الله لكم تحلة ايمانكم والله مولاكم وهو العليم الحكيم', NULL, 'Allāh has already ordained for you [Muslims] the dissolution of your oaths. And Allāh is your protector, and He is the Knowing, the Wise.', 'Sesungguhnya Allah telah menetapkan bagi kamu (wahai Nabi dan umatmu, untuk) melepaskan diri dari sumpah kamu (dengan membayar denda - kaffarah); dan Allah ialah Pelindung yang mentadbirkan keadaan kamu, dan Ia Maha Mengetahui, lagi Maha Bijaksana.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 11, NULL),
(66, 3, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَـٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 'واذ اسر النبي الى بعض ازواجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير', NULL, 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allāh showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Aware."', 'Dan (ingatlah), ketika Nabi memberitahu suatu perkara secara rahsia kepada salah seorang dari isteri-isterinya. Kemudian apabila isterinya itu menceritakan rahsia yang tersebut (kepada seorang madunya), dan Allah menyatakan pembukaan rahsia itu kepada Nabi, (maka Nabi pun menegur isterinya itu) lalu menerangkan kepadanya sebahagian (dari rahsia yang telah dibukanya) dan tidak menerangkan yang sebahagian lagi (supaya isterinya itu tidak banyak malunya). Setelah Nabi menyatakan hal itu kepada isterinya, isterinya bertanya: “Siapakah yang memberi tahu hal ini kepada tuan?” Nabi menjawab: “Aku diberitahu oleh Allah Yang Maha Mengetahui, lagi Amat Mendalam PengetahuanNya (tentang segala perkara yang nyata dan yang tersembunyi)”.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 29, NULL),
(66, 4, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَـٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَـٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَـٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 'ان تتوبا الى الله فقد صغت قلوبكما وان تظاهرا عليه فان الله هو مولاه وجبريل وصالح المؤمنين والملائكة بعد ذلك ظهير', NULL, 'If you two [wives] repent to Allāh, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allāh is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.', 'Jika kamu berdua bertaubat kepada Allah (wahai isteri-isteri Nabi, maka itulah yang sewajibnya), kerana sesungguhnya hati kamu berdua telah cenderung (kepada perkara yang menyusahkan Nabi); dan jika kamu berdua saling membantu untuk (melakukan sesuatu yang) menyusahkannya, (maka yang demikian itu tidak akan berjaya) kerana sesungguhnya Allah adalah Pembelanya; dan selain dari itu Jibril serta orang-orang yang soleh dari kalangan orang-orang yang beriman dan malaikat-malaikat - juga menjadi penolongnya.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 21, NULL),
(66, 5, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَـٰتٍ مُّؤْمِنَـٰتٍ قَـٰنِتَـٰتٍ تَـٰٓئِبَـٰتٍ عَـٰبِدَٰتٍ سَـٰٓئِحَـٰتٍ ثَيِّبَـٰتٍ وَأَبْكَارًا', 'عسى ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مؤمنات قانتات تائبات عابدات سائحات ثيبات وابكارا', NULL, 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allāh], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.', 'Boleh jadi, jika Nabi menceraikan kamu, Tuhannya akan menggantikan baginya isteri-isteri yang lebih baik daripada kamu, - yang menurut perintah, yang ikhlas imannya, yang taat, yang bertaubat, yang tetap beribadat, yang berpuasa, - (meliputi) yang janda dan yang anak dara.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 17, NULL),
(66, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَـٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'يا ايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجارة عليها ملائكة غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون', NULL, 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allāh in what He commands them but do what they are commanded.', 'Wahai orang-orang yang beriman! Peliharalah diri kamu dan keluarga kamu dari neraka yang bahan-bahan bakarannya: manusia dan batu (berhala); neraka itu dijaga dan dikawal oleh malaikat-malaikat yang keras kasar (layanannya); mereka tidak menderhaka kepada Allah dalam segala yang diperintahkanNya kepada mereka, dan mereka pula tetap melakukan segala yang diperintahkan.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 22, NULL),
(66, 7, 'يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'يا ايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون', NULL, 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.', 'Malaikat itu akan berkata kepada orang-orang yang dimasukkan ke dalam neraka): “Hai orang-orang yang kufur ingkar! Janganlah kamu menyatakan uzur (dengan meminta ampun) pada hari ini, (kerana masanya telah terlambat). Kamu hanyalah dibalas dengan balasan apa yang kamu telah kerjakan”.', FALSE, NULL, NULL, 560, 28, 224, 494, FALSE, 11, NULL),
(66, 8, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'يا ايها الذين امنوا توبوا الى الله توبة نصوحا عسى ربكم ان يكفر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الانهار يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعى بين ايديهم وبايمانهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك على كل شيء قدير', NULL, 'O you who have believed, repent to Allāh with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allāh will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, "Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent."', 'Wahai orang-orang yang beriman! Bertaubatlah kamu kepada Allah dengan “Taubat Nasuha”, mudah-mudahan Tuhan kamu akan menghapuskan kesalahan-kesalahan kamu dan memasukkan kamu ke dalam Syurga yang mengalir di bawahnya beberapa sungai, pada hari Allah tidak akan menghinakan Nabi dan orang-orang yang beriman bersama-sama dengannya; cahaya (iman dan amal soleh) mereka, bergerak cepat di hadapan mereka dan di sebelah kanan mereka (semasa mereka berjalan); mereka berkata (ketika orang-orang munafik meraba-raba dalam gelap-gelita): “Wahai Tuhan kami! Sempurnakanlah bagi kami cahaya kami, dan limpahkanlah keampunan kepada kami; sesungguhnya Engkau Maha Kuasa atas tiap-tiap sesuatu”.', FALSE, NULL, NULL, 561, 28, 224, 495, FALSE, 45, NULL),
(66, 9, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'يا ايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير', NULL, 'O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.', 'Wahai Nabi! Berjihadlah (menentang) orang-orang kafir dan orang-orang munafik, serta bertindak keras terhadap mereka. Dan (sebenarnya) tempat mereka ialah neraka Jahannam, dan itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 561, 28, 224, 495, FALSE, 11, NULL),
(66, 10, 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَـٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صالحين فخانتاهما فلم يغنيا عنهما من الله شيئا وقيل ادخلا النار مع الداخلين', NULL, 'Allāh presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so they [i.e., those prophets] did not avail them from Allāh at all, and it was said, "Enter the Fire with those who enter."', 'Allah mengemukakan satu misal perbandingan (yang menyatakan tidak ada manfaatnya) bagi orang-orang kafir (berhubung rapat dengan orang-orang mukmin selagi mereka tidak beriman dengan sebenar-benarnya), iaitu: perihal isteri Nabi Nuh dan isteri Nabi Lut; mereka berdua berada di bawah jagaan dua orang hamba yang soleh dari hamba-hamba Kami (yang sewajibnya mereka berdua taati); dalam pada itu mereka berlaku khianat kepada suami masing-masing; maka kedua-dua suami mereka (yang berpangkat Nabi itu) tidak dapat memberikan sebarang pertolongan kepada mereka dari (azab) Allah, dan (sebaliknya) dikatakan kepada mereka berdua (pada hari pembalasan): “Masuklah kamu berdua ke dalam neraka bersama-sama orang-orang yang masuk (ke situ)”.', FALSE, NULL, NULL, 561, 28, 224, 495, FALSE, 27, NULL),
(66, 11, 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', 'وضرب الله مثلا للذين امنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظالمين', NULL, 'And Allāh presents an example of those who believed: the wife of Pharaoh, when she said, "My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people."', 'Dan Allah mengemukakan satu misal perbandingan (yang menyatakan tidak ada mudaratnya) kepada orang-orang mukmin (berhubung rapat dengan orang-orang kafir kalau tidak terjejas keadaan imannya), iaitu: perihal isteri Firaun, ketika ia berkata: “Wahai Tuhanku! Binalah untukku sebuah rumah di sisiMu dalam Syurga, dan selamatkanlah daku dari Firaun dan perbuatannya (yang kufur dan buas), serta selamatkanlah daku dari kaum yang zalim”;', FALSE, NULL, NULL, 561, 28, 224, 495, FALSE, 24, NULL),
(66, 12, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَـٰنِتِينَ', 'ومريم ابنت عمران التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمات ربها وكتبه وكانت من القانتين', NULL, 'And [the example of] Mary, the daughter of ʿImrān, who guarded her chastity, so We blew into [her garment] through Our angel [i.e., Gabriel], and she believed in the words of her Lord and His scriptures and was of the devoutly obedient.', 'Dan juga (satu misal perbandingan lagi, iaitu): Maryam binti Imran (ibu Nabi Isa seorang perempuan) yang telah memelihara kehormatan dan kesuciannya (dari disentuh oleh lelaki; tetapi oleh sebab Kami telah takdirkan dia mendapat anak) maka Kami perintahkan Jibril meniup masuk ke dalam kandungan tubuhnya dari roh (ciptaan) Kami; dan (sekalipun Maryam itu hidup di antara kaum kafir) ia mengakui kebenaran Kalimah-kalimah Tuhannya serta Kitab-kitabNya; dan ia menjadi dari orang-orang yang tetap taat.', FALSE, NULL, NULL, 561, 28, 224, 495, FALSE, 17, NULL),
(67, 1, 'تَبَـٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'تبارك الذي بيده الملك وهو على كل شيء قدير', NULL, 'Blessed is He in whose hand is dominion, and He is over all things competent -', 'Maha Berkat (serta Maha Tinggilah kelebihan) Tuhan yang menguasai pemerintahan (dunia dan akhirat); dan memanglah Ia Maha Kuasa atas tiap-tiap sesuatu;', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 9, NULL),
(67, 2, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'الذي خلق الموت والحياة ليبلوكم ايكم احسن عملا وهو العزيز الغفور', NULL, '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -', 'Dia lah yang telah mentakdirkan adanya mati dan hidup (kamu) - untuk menguji dan menzahirkan keadaan kamu: siapakah di antara kamu yang lebih baik amalnya; dan Ia Maha Kuasa (membalas amal kamu), lagi Maha Pengampun, (bagi orang-orang yang bertaubat);', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 11, NULL),
(67, 3, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَـٰنِ مِن تَفَـٰوُتٍ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', 'الذي خلق سبع سماوات طباقا ما ترى في خلق الرحمن من تفاوت فارجع البصر هل ترى من فطور', NULL, '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?', 'Dia lah yang telah mengaturkan kejadian tujuh petala langit yang berlapis-lapis; engkau tidak dapat melihat pada ciptaan Allah Yang Maha Pemurah itu sebarang keadaan yang tidak seimbang dan tidak munasabah; (jika engkau ragu-ragu) maka ulangilah pandangan - (mu) - dapatkah engkau melihat sebarang kecacatan?', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 18, NULL),
(67, 4, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', 'ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير', NULL, 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.', 'Kemudian ulangilah pandangan (mu) berkali-kali, nescaya pandanganmu itu akan berbalik kepadamu dengan hampa (daripada melihat sebarang kecacatan), sedang ia pula berkeadaan lemah lesu (kerana habis tenaga dengan sia-sia).', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 10, NULL),
(67, 5, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَجَعَلْنَـٰهَا رُجُومًا لِّلشَّيَـٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 'ولقد زينا السماء الدنيا بمصابيح وجعلناها رجوما للشياطين واعتدنا لهم عذاب السعير', NULL, 'And We have certainly beautified the nearest heaven with lamps [i.e., stars] and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.', 'Dan demi sesungguhnya! Kami telah menghiasi langit yang dekat (pada penglihatan penduduk bumi) dengan bintang-bintang, dan Kami jadikan bintang-bintang itu punca rejaman terhadap Syaitan-syaitan; dan Kami sediakan bagi mereka azab neraka yang menjulang-julang.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 12, NULL),
(67, 6, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وللذين كفروا بربهم عذاب جهنم وبئس المصير', NULL, 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.', 'Dan bagi orang-orang yang kufur ingkar terhadap Tuhan mereka, disediakan azab neraka Jahannam, dan itulah seburuk-buruk tempat kembali.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 7, NULL),
(67, 7, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', 'اذا القوا فيها سمعوا لها شهيقا وهي تفور', NULL, 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.', 'Apabila mereka dicampakkan ke dalamnya, mereka mendengar suara jeritannya meraung-raung, sedang ia menggelegak.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 8, NULL),
(67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', 'تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير', NULL, 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"', 'Hampir-hampir ia pecah berkecai-kecai kerana kuat marahnya. Tiap-tiap kali dicampakkan ke dalamnya sekumpulan besar (dari orang kafir), bertanyalah penjaga-penjaga neraka itu kepada mereka: “Tidakkah kamu pernah didatangi seorang Rasul pemberi ingatan dan amaran (di dunia dahulu)?”', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 13, NULL),
(67, 9, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ كَبِيرٍ', 'قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلال كبير', NULL, 'They will say, "Yes, a warner had come to us, but we denied and said, ''Allāh has not sent down anything. You are not but in great error.''"', 'Mereka menjawab: “Ada! Sebenarnya telah datang kepada kami seorang Rasul pemberi ingatan dan amaran, lalu kami dustakan serta kami katakan (kepadanya): Allah tidak menurunkan sesuatupun, kamu (wahai orang yang mendakwa menjadi Rasul) hanyalah berada dalam kesesatan yang besar!”', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 18, NULL),
(67, 10, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَـٰبِ ٱلسَّعِيرِ', 'وقالوا لو كنا نسمع او نعقل ما كنا في اصحاب السعير', NULL, 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."', 'Dan mereka berkata: “Kalaulah kami dahulu mendengar dan memahami (sebagai orang yang mencari kebenaran), tentulah kami tidak termasuk dalam kalangan ahli neraka”.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 11, NULL),
(67, 11, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَـٰبِ ٱلسَّعِيرِ', 'فاعترفوا بذنبهم فسحقا لاصحاب السعير', NULL, 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.', 'Akhirnya mereka mengakui dosa-dosa mereka (sebagai orang-orang yang kufur ingkar), maka tetaplah jauhnya rahmat Allah dari ahli neraka.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 5, NULL),
(67, 12, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'ان الذين يخشون ربهم بالغيب لهم مغفرة واجر كبير', NULL, 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.', 'Sesungguhnya orang-orang yang takut (melanggar hukum) Tuhannya semasa mereka tidak dilihat orang dan semasa mereka tidak melihat azab Tuhan, mereka beroleh keampunan dan pahala yang besar.', FALSE, NULL, NULL, 562, 29, 225, 496, FALSE, 9, NULL),
(67, 13, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'واسروا قولكم او اجهروا به انه عليم بذات الصدور', NULL, 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.', 'Dan tuturkanlah perkataan kamu dengan perlahan atau dengan nyaring, (sama sahaja keadaannya kepada Allah), kerana sesungguhnya Allah Maha Mengetahui akan segala (isi hati) yang terkandung di dalam dada.', FALSE, NULL, NULL, 563, 29, 225, 496, FALSE, 9, NULL),
(67, 14, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'الا يعلم من خلق وهو اللطيف الخبير', NULL, 'Does He who created not know, while He is the Subtle, the Aware?', 'Tidakkah Allah yang menciptakan sekalian makhluk itu mengetahui (segala-galanya)? Sedang Ia Maha Halus urusan PentadbiranNya, lagi Maha Mendalam PengetahuanNya!', FALSE, NULL, NULL, 563, 29, 225, 496, FALSE, 7, NULL),
(67, 15, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', 'هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور', NULL, 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.', 'Dia lah yang menjadikan bumi bagi kamu: mudah digunakan, maka berjalanlah di merata-rata ceruk rantaunya, serta makanlah dari rezeki yang dikurniakan Allah; dan (ingatlah), kepada Allah jualah (tempat kembali kamu sesudah) dibangkitkan hidup semula; (maka hargailah nikmatNya dan takutilah kemurkaanNya).', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 14, NULL),
(67, 16, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'اامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور', NULL, 'Do you feel secure that He who is above would not cause the earth to swallow you and suddenly it would sway?', 'Patutkah kamu merasa aman (tidak takut) kepada Tuhan yang pusat pemerintahanNya di langit itu: menunggang-balikkan bumi menimbus kamu, lalu bergegarlah bumi itu dengan serta-merta (melenyapkan kamu di bawahnya)?', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 11, NULL),
(67, 17, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير', NULL, 'Or do you feel secure that He who is above would not send against you a storm of stones? Then you would know how [severe] was My warning.', 'Atau patutkah kamu merasa aman (tidak takut) kepada Allah yang pusat pemerintahanNya di langit itu: menghantarkan kepada kamu angin ribut yang menghujani kamu dengan batu; maka dengan itu, kamu akan mengetahui kelak bagaimana buruknya kesan amaranKu?', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 12, NULL),
(67, 18, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'ولقد كذب الذين من قبلهم فكيف كان نكير', NULL, 'And already had those before them denied, and how [terrible] was My reproach.', 'Dan demi sesungguhnya! orang-orang (kafir) yang terdahulu daripada mereka telah mendustakan (rasul-rasulnya lalu mereka dibinasakan); dengan yang demikian, (perhatikanlah) bagaimana buruknya kesan kemurkaanKu.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 8, NULL),
(67, 19, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَـٰٓفَّـٰتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَـٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 'اولم يروا الى الطير فوقهم صافات ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير', NULL, 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.', 'Patutkah mereka menutup mata dan tidak memerhatikan (kekuasaan Allah pada) burung-burung yang terbang di atas mereka, (siapakah yang menjaganya ketika) burung-burung itu mengembang dan menutupkan sayapnya? Tidak ada yang menahannya (daripada jatuh) melainkan (kekuasaan) Allah Yang Maha Pemurah. Sesungguhnya Ia Maha Melihat serta mengetahui akan tiap-tiap sesuatu.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 15, NULL),
(67, 20, 'أَمَّنْ هَـٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَـٰنِ ۚ إِنِ ٱلْكَـٰفِرُونَ إِلَّا فِى غُرُورٍ', 'امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكافرون الا في غرور', NULL, 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.', 'Bahkan siapa dia yang menjadi tentera bagi kamu, yang akan menolong kamu selain dari Allah Yang Maha Pemurah? (Sebenarnya) orang-orang yang kafir tidak lain hanyalah berada dalam keadaan terpedaya.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 15, NULL),
(67, 21, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', 'أَمَّنْ هَٰذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ بَل لَّجُّوا فِي عُتُوٍّ وَنُفُورٍ', NULL, 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.', 'Atau siapa dia yang dapat memberi rezeki kepada kamu jika Allah menahan rezekiNya? (Tidak ada sesiapapun), bahkan mereka (yang musyrik itu) kekal terus dalam keadaan sombong angkuh serta melarikan diri (dari kebenaran).', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 22, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'أَفَمَن يَمْشِي مُكِبًّا عَلَىٰ وَجْهِهِ أَهْدَىٰ أَمَّن يَمْشِي سَوِيًّا عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', NULL, 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?', 'Maka adakah orang yang berjalan (melalui jalan yang tidak betul, yang menyebabkan dia selalu jatuh) tersungkur di atas mukanya: boleh mendapat hidayah - atau orang yang berjalan tegak betul, melalui jalan yang lurus rata?', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 23, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'قُلْ هُوَ الَّذِي أَنشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ', NULL, 'Say, "It is He who has produced you and made for you hearing and vision and hearts [i.e., intellect]; little are you grateful."', 'Katakanlah (wahai Muhammad): “Allah yang menciptakan kamu (dari tiada kepada ada), dan mengadakan bagi kamu pendengaran dan penglihatan serta hati (untuk kamu bersyukur, tetapi) amatlah sedikit kamu bersyukur”.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 24, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', NULL, 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."', 'Katakanlah lagi: “Dia lah yang mengembangkan kamu di bumi, dan kepadaNyalah kamu akan dihimpunkan”.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 25, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ', NULL, 'And they say, "When is this promise, if you should be truthful?"', 'Dan mereka (yang ingkar) berkata: “Bilakah datangnya (hari kiamat) yang dijanjikan itu, jika betul kamu orang-orang yang benar?”', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 26, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'قُلْ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُّبِينٌ', NULL, 'Say, "The knowledge is only with Allāh, and I am only a clear warner."', 'Katakanlah (wahai Muhammad): “Sesungguhnya ilmu pengetahuan (tentang masa kedatangannya) hanya ada pada sisi Allah, dan sesungguhnya aku hanyalah seorang Rasul pemberi ingatan dan amaran yang terang nyata”.', FALSE, NULL, NULL, 563, 29, 225, 497, FALSE, 0, NULL),
(67, 27, 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هَٰذَا الَّذِي كُنتُم بِهِ تَدَّعُونَ', NULL, 'But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, "This is that for which you used to call."', 'Kemudian apabila (datang kiamat dan) mereka melihat (azab) yang dijanjikan itu secara dekat, muramlah muka orang-orang yang kafir itu, serta dikatakan (kepada mereka): “Inilah dia yang dahulu kamu kerap kali minta disegerakan kedatangannya!”.', FALSE, NULL, NULL, 564, 29, 225, 497, FALSE, 0, NULL),
(67, 28, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', 'قُلْ أَرَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَن يُجِيرُ الْكَافِرِينَ مِنْ عَذَابٍ أَلِيمٍ', NULL, 'Say, [O Muḥammad], "Have you considered: whether Allāh should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?"', 'Tanyalah (wahai Muhammad, kepada mereka): “Bagaimana fikiran kamu, jika Allah binasakan daku dan orang-orang yang bersama-sama denganku (sebagaimana yang kamu harap-harapkan), atau Ia memberi rahmat kepada kami (sehingga kami dapat mengalahkan kamu), - maka siapakah yang dapat melindungi orang-orang yang kafir dari azab seksa yang tidak terperi sakitnya?”.', FALSE, NULL, NULL, 564, 29, 225, 497, FALSE, 0, NULL),
(67, 29, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'قُلْ هُوَ الرَّحْمَٰنُ آمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ', NULL, 'Say, "He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error."', 'Tegaskan (wahai Muhammad, kepada mereka): “Allah Dia lah Yang Maha Pemurah, yang kami beriman kepadaNya, dan yang kepadaNya kami berserah diri; oleh itu kamu akan mengetahui kelak siapakah yang berada dalam kesesatan yang nyata”.', FALSE, NULL, NULL, 564, 29, 225, 497, FALSE, 0, NULL),
(67, 30, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ', 'قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَاءٍ مَّعِينٍ', NULL, 'Say, "Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?"', 'Katakanlah lagi: “Bagaimana fikiran kamu, sekiranya air kamu hilang lenyap (di telan bumi), maka siapakah (selain Allah) yang dapat mendatangkan kepada kamu air yang sentiasa terpancar mengalir?”.', FALSE, NULL, NULL, 564, 29, 225, 497, FALSE, 0, NULL),
(68, 1, 'نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 'ن والقلم وما يسطرون', NULL, 'Nūn. By the pen and what they inscribe,', 'Nuun. Demi Pena dan apa yang mereka tulis, -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 4, NULL),
(68, 2, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ', 'ما انت بنعمة ربك بمجنون', NULL, 'You are not, [O Muḥammad], by the favor of your Lord, a madman.', 'Engkau (wahai Muhammad) - dengan sebab nikmat pemberian Tuhanmu - bukanlah seorang gila (sebagaimana yang dituduh oleh kaum musyrik, bahkan engkau adalah seorang yang bijaksana).', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 5, NULL),
(68, 3, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ', 'وان لك لاجرا غير ممنون', NULL, 'And indeed, for you is a reward uninterrupted.', 'Dan sesungguhnya engkau tetap beroleh pahala yang amat besar, yang tidak putus-putus, (sebagai balasan bagi menjalankan ajaran Islam);', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 5, NULL),
(68, 4, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', 'وانك لعلى خلق عظيم', NULL, 'And indeed, you are of a great moral character.', 'Dan bahawa sesungguhnya engkau mempunyai akhlak yang amat mulia.', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 4, NULL),
(68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'فستبصر ويبصرون', NULL, 'So you will see and they will see', 'Maka (tidak lama lagi) engkau akan melihat, dan mereka juga akan melihat, -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 2, NULL),
(68, 6, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 'باييكم المفتون', NULL, 'Which of you is the afflicted [by a devil].', 'Siapakah orangnya yang gila di antara kamu semua.', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 2, NULL),
(68, 7, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين', NULL, 'Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided.', 'Sesungguhnya Tuhanmu, Dia lah jua yang lebih mengetahui akan orang yang sesat dari jalanNya, dan Dia lah jua yang lebih mengetahui akan orang-orang yang mendapat petunjuk.', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 11, NULL),
(68, 8, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 'فلا تطع المكذبين', NULL, 'Then do not obey the deniers.', 'Oleh itu (berpegang teguhlah pada ajaran Islam yang sedang engkau amalkan, dan) janganlah engkau menurut kemahuan orang-orang yang mendustakan (ugama Allah).', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 3, NULL),
(68, 9, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 'ودوا لو تدهن فيدهنون', NULL, 'They wish that you would soften [in your position], so they would soften [toward you].', 'Mereka suka kalaulah engkau bertolak ansur (menurut kemahuan mereka), supaya mereka juga bertolak ansur berlemah-lembut (pada zahirnya terhadapmu).', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 4, NULL),
(68, 10, 'وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ', 'ولا تطع كل حلاف مهين', NULL, 'And do not obey every worthless habitual swearer', 'Dan janganlah engkau (berkisar dari pendirianmu yang benar, dan jangan) menurut kemahuan orang yang selalu bersumpah, lagi yang hina (pendapatnya dan amalannya), -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 5, NULL),
(68, 11, 'هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ', 'هماز مشاء بنميم', NULL, '[And] scorner, going about with malicious gossip -', 'Yang suka mencaci, lagi yang suka menyebarkan fitnah hasutan (untuk memecah belahkan orang ramai), -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 3, NULL),
(68, 12, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 'مناع للخير معتد اثيم', NULL, 'A preventer of good, transgressing and sinful,', 'Yang sering menghalangi amalan-amalan kebajikan, yang melanggar hukum-hukum ugama, lagi yang amat berdosa, -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 4, NULL),
(68, 13, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'عتل بعد ذلك زنيم', NULL, 'Cruel, moreover, and an illegitimate pretender.', 'Yang jahat kejam, yang selain itu tidak tentu pula bapanya.', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 4, NULL),
(68, 14, 'أَن كَانَ ذَا مَالٍ وَبَنِينَ', 'ان كان ذا مال وبنين', NULL, 'Because he is a possessor of wealth and children,', 'Adakah kerana ia seorang hartawan dan ramai anak-pinaknya (maka ia mendustakan ugama Kami)? -', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 5, NULL),
(68, 15, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', 'اذا تتلى عليه اياتنا قال اساطير الاولين', NULL, 'When Our verses are recited to him, he says, "Legends of the former peoples."', 'Apabila dibacakan kepadanya ayat-ayat keterangan Kami, ia berkata: “(Ini ialah) cerita-cerita dongeng orang-orang dahulu kala”.', FALSE, NULL, NULL, 564, 29, 226, 498, FALSE, 7, NULL),
(68, 16, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 'سنسمه على الخرطوم', NULL, 'We will brand him upon the snout.', '(Orang yang bersifat demikian, akan didedahkan kehinaannya) - Kami akan adakan tanda di atas hidungnya (yang berupa belalai itu).', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 3, NULL),
(68, 17, 'إِنَّا بَلَوْنَـٰهُمْ كَمَا بَلَوْنَآ أَصْحَـٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'انا بلوناهم كما بلونا اصحاب الجنة اذ اقسموا ليصرمنها مصبحين', NULL, 'Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning', 'Sesungguhnya Kami telah timpakan mereka dengan bala bencana, sebagaimana Kami timpakan tuan-tuan punya kebun (dari kaum yang telah lalu), ketika orang-orang itu bersumpah (bahawa) mereka akan memetik buah-buah kebun itu pada esok pagi; -', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 10, NULL),
(68, 18, 'وَلَا يَسْتَثْنُونَ', 'ولا يستثنون', NULL, 'Without making exception.', 'Serta mereka tidak menyebut pengecualian.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 2, NULL),
(68, 19, 'فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'فطاف عليها طائف من ربك وهم نائمون', NULL, 'So there came upon it [i.e., the garden] an affliction from your Lord while they were asleep.', 'Maka kebun itu didatangi serta diliputi oleh bala bencana dari Tuhanmu (pada malam hari), sedang mereka semua tidur.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 7, NULL),
(68, 20, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 'فاصبحت كالصريم', NULL, 'And it became as though reaped.', 'Lalu menjadilah ia sebagai kebun yang telah binasa semua buahnya.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 2, NULL),
(68, 21, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 'فَتَنَادَوْا مُصْبِحِينَ', NULL, 'And they called one another at morning,', 'Kemudian pada pagi-pagi, mereka panggil memanggil antara satu dengan yang lain -', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 22, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ', 'أَنِ اغْدُوا عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَارِمِينَ', NULL, '[Saying], "Go early to your crop if you would cut the fruit."', '(Setengahnya berkata): “Pergilah pada pagi-pagi ke kebun kamu, kalau betul kamu mahu memetik buahnya”.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 23, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ', 'فَانطَلَقُوا وَهُمْ يَتَخَافَتُونَ', NULL, 'So they set out, while lowering their voices,', 'Lalu berjalanlah mereka sambil berbisik (katanya):', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 24, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ', 'أَن لَّا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُم مِّسْكِينٌ', NULL, '[Saying], "There will surely not enter it today upon you [any] poor person."', '“Pada hari ini, janganlah hendaknya seorang miskin pun masuk ke kebun itu mendapatkan kamu”.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 25, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَٰدِرِينَ', 'وَغَدَوْا عَلَىٰ حَرْدٍ قَادِرِينَ', NULL, 'And they went early in determination, [assuming themselves] able.', 'Dan pergilah mereka pada pagi-pagi itu, dengan kepercayaan, (bahawa) mereka berkuasa menghampakan fakir miskin dari hasil kebun itu.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 26, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 'فَلَمَّا رَأَوْهَا قَالُوا إِنَّا لَضَالُّونَ', NULL, 'But when they saw it, they said, "Indeed, we are lost;', 'Sebaik-baik sahaja mereka melihat kebunnya, mereka berkata: “Sebenarnya kita sesat jalan, (ini bukanlah kebun kita)”.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ', 'بَلْ نَحْنُ مَحْرُومُونَ', NULL, 'Rather, we have been deprived."', '(Setelah mereka perhati dengan teliti, mereka berkata: “Tidak! Kita tidak sesat), bahkan kita orang-orang yang dihampakan (dari hasil kebun kita, dengan sebab ingatan buruk kita sendiri)”.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 28, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', NULL, 'The most moderate of them said, "Did I not say to you, ''Why do you not exalt [Allāh]?''"', 'Berkatalah orang yang bersikap adil di antara mereka: “Bukankah aku telah katakan kepada kamu (semasa kamu hendak menghampakan orang-orang fakir miskin dari habuannya): amatlah elok kiranya kamu mengingati Allah (serta membatalkan rancangan kamu yang jahat itu)?”', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 29, 'قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'قَالُوا سُبْحَانَ رَبِّنَا إِنَّا كُنَّا ظَالِمِينَ', NULL, 'They said, "Exalted is our Lord! Indeed, we were wrongdoers."', 'Mereka berkata (dengan sesalnya): “Maha Suci Tuhan Kami! Sesungguhnya kami adalah orang-orang yang berlaku zalim!”', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 30, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَٰوَمُونَ', 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَاوَمُونَ', NULL, 'Then they approached one another, blaming each other.', 'Kemudian setengahnya mengadap yang lain, sambil cela-mencela.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 31, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'قَالُوا يَا وَيْلَنَا إِنَّا كُنَّا طَاغِينَ', NULL, 'They said, "O woe to us; indeed we were transgressors.', 'Mereka berkata: “Aduhai celakanya kita! Sesungguhnya kita adalah orang-orang yang melampaui batas.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 32, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 'عَسَىٰ رَبُّنَا أَن يُبْدِلَنَا خَيْرًا مِّنْهَا إِنَّا إِلَىٰ رَبِّنَا رَاغِبُونَ', NULL, 'Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous."', '“Semoga Tuhan kita, (dengan sebab kita bertaubat) menggantikan bagi kita yang lebih baik daripada (kebun yang telah binasa) itu; sesungguhnya, kepada Tuhan kita sahajalah kita berharap”.', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 33, 'كَذَٰلِكَ ٱلْعَذَابُ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'كَذَٰلِكَ الْعَذَابُ وَلَعَذَابُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ', NULL, 'Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew.', 'Demikianlah azab seksa (yang telah ditimpakan kepada golongan yang ingkar di dunia), dan sesungguhnya azab hari akhirat lebih besar lagi; kalaulah mereka orang-orang yang berpengetahuan (tentulah mereka beringat-ingat).', FALSE, NULL, NULL, 565, 29, 226, 498, FALSE, 0, NULL),
(68, 34, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ', 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّاتِ النَّعِيمِ', NULL, 'Indeed, for the righteous with their Lord are the Gardens of Pleasure.', 'Sesungguhnya orang-orang yang bertaqwa, disediakan bagi mereka taman-taman Syurga yang penuh nikmat, di sisi Tuhan mereka.', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 35, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 'أَفَنَجْعَلُ الْمُسْلِمِينَ كَالْمُجْرِمِينَ', NULL, 'Then will We treat the Muslims like the criminals?', 'Patutkah Kami (berlaku tidak adil, dengan) menjadikan orang-orang Islam (yang taat), sama seperti orang-orang yang berdosa (yang kufur ingkar)?', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 36, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', NULL, 'What is [the matter] with you? How do you judge?', 'Apa sudah jadi kepada akal kamu? Bagaimana kamu menetapkan hukum (yang terang-terang salahnya itu)?', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 37, 'أَمْ لَكُمْ كِتَٰبٌ فِيهِ تَدْرُسُونَ', 'أَمْ لَكُمْ كِتَابٌ فِيهِ تَدْرُسُونَ', NULL, 'Or do you have a scripture in which you learn', 'Adakah kamu mempunyai sesebuah Kitab (dari Allah) yang kamu baca dan pelajari?', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 38, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', NULL, 'That indeed for you is whatever you choose?', 'Bahawa di dalam Kitab itu membolehkan kamu mendapat apa sahaja yang kamu pilih?', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 39, 'أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 'أَمْ لَكُمْ أَيْمَانٌ عَلَيْنَا بَالِغَةٌ إِلَىٰ يَوْمِ الْقِيَامَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', NULL, 'Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge?', 'Atau adakah kamu mendapat akuan-akuan yang ditegaskan dengan sumpah dari Kami, yang tetap hingga hari kiamat, menentukan bahawa kamu dapat mencapai apa yang kamu putuskan?', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 40, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', NULL, 'Ask them which of them, for that [claim], is responsible.', 'Bertanyalah kepada mereka: “Siapakah orangnya di antara mereka yang menjamin benarnya hukum: bahawa mereka akan mendapat di akhirat apa yang didapati oleh orang Islam?”', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 41, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ', 'أَمْ لَهُمْ شُرَكَاءُ فَلْيَأْتُوا بِشُرَكَائِهِمْ إِن كَانُوا صَادِقِينَ', NULL, 'Or do they have partners? Then let them bring their partners, if they should be truthful.', 'Atau adakah mereka mempunyai sekutu-sekutu (yang sefaham dengan mereka? Kalau ada) maka hendaklah mereka membawanya, jika betul mereka orang-orang yang benar.', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 42, 'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ', NULL, 'The Day the shin will be uncovered and they are invited to prostration but they [i.e., the disbelievers] will not be able,', '(Ingatkanlah orang-orang yang tidak beriman) akan masa didedahkan kedahsyatan huru-hara (hari kiamat), dan mereka diseru supaya sujud maka mereka tidak dapat melakukannya, -', FALSE, NULL, NULL, 565, 29, 226, 499, FALSE, 0, NULL),
(68, 43, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ', 'خَاشِعَةً أَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا يُدْعَوْنَ إِلَى السُّجُودِ وَهُمْ سَالِمُونَ', NULL, 'Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound.', 'Sambil pandangan mereka tunduk malu, serta mereka diliputi kehinaan; dan sesungguhnya mereka (di dunia) dahulu telahpun diseru supaya sujud (tetapi mereka enggan) sedang mereka dalam keadaan sihat.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 44, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'فَذَرْنِي وَمَن يُكَذِّبُ بِهَٰذَا الْحَدِيثِ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', NULL, 'So leave Me, [O Muḥammad], with [the matter of] whoever denies this statement [i.e., the Qur’ān]. We will progressively lead them [to punishment] from where they do not know.', 'Biarkanlah Aku sahaja (wahai Muhammad) dengan orang yang mendustakan keterangan Al-Quran ini, Kami akan menarik mereka sedikit demi sedikit (ke jurang kebinasaan), dari arah yang mereka tidak mengetahuinya.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 45, 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', 'وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ', NULL, 'And I will give them time. Indeed, My plan is firm.', 'Dan Aku akan melanjutkan tempoh untuk mereka; sesungguhnya rancangan sulitKu (terhadap golongan yang kufur ingkar itu), amatlah kuat kukuh.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 46, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', 'أَمْ تَسْأَلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', NULL, 'Or do you ask of them a payment, so they are by debt burdened down?', 'Pernahkah engkau (wahai Muhammad) meminta sebarang bayaran kepada mereka (mengenai ajaran Islam yang engkau sampaikan), lalu mereka merasa berat menanggung bayaran itu (sehingga menjauhkan diri daripada menyahut seruanmu)?', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 47, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'أَمْ عِندَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ', NULL, 'Or have they [knowledge of] the unseen, so they write [it] down?', 'Atau adakah di sisi mereka (Lauh Mahfuz yang mengandungi) perkara-perkara yang ghaib lalu mereka menyalin (daripadanya untuk menentang ajaran dan peringatanmu)?', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 48, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ', 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ الْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ', NULL, 'Then be patient for the decision of your Lord, [O Muḥammad], and be not like the companion of the fish [i.e., Jonah] when he called out while he was distressed.', 'Maka bersabarlah (wahai Muhammad) menerima hukum Tuhanmu (memberi tempoh kepada mereka), dan janganlah engkau bersikap seperti orang yang telah ditelan oleh ikan. (Ingatlah kisahnya) ketika ia berdoa merayu dengan keadaan sesak sebak terkurung dalam perut ikan.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 49, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ', 'لَّوْلَا أَن تَدَارَكَهُ نِعْمَةٌ مِّن رَّبِّهِ لَنُبِذَ بِالْعَرَاءِ وَهُوَ مَذْمُومٌ', NULL, 'If not that a favor [i.e., mercy] from his Lord overtook him, he would have been thrown onto the naked shore while he was censured.', 'Kalaulah ia tidak didatangi nikmat pertolongan dari Tuhannya, nescaya tercampaklah ia ke tanah yang tandus (di tepi pantai) dalam keadaan ia ditempelak (kerana salah silapnya).', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 50, 'فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', 'فَاجْتَبَاهُ رَبُّهُ فَجَعَلَهُ مِنَ الصَّالِحِينَ', NULL, 'And his Lord chose him and made him of the righteous.', 'Selepas itu Tuhannya memilihnya, serta menjadikan dia dari orang-orang yang soleh.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 51, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ', 'وَإِن يَكَادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ بِأَبْصَارِهِمْ لَمَّا سَمِعُوا الذِّكْرَ وَيَقُولُونَ إِنَّهُ لَمَجْنُونٌ', NULL, 'And indeed, those who disbelieve would almost make you slip with their eyes [i.e., looks] when they hear the message, and they say, "Indeed, he is mad."', 'Dan sesungguhnya orang-orang yang kafir itu, hampir-hampir menggelincir dan menjatuhkanmu dengan pandangan mereka (yang penuh dengan permusuhan dan kebencian), semasa mereka mendengar Al-Quran sambil berkata: “Sebenarnya (Muhammad) itu, sungguh-sungguh orang gila”.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(68, 52, 'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ', NULL, 'But it is not except a reminder to the worlds.', 'Padahal Al-Quran itu tidak lain hanyalah peringatan bagi umat manusia seluruhnya.', FALSE, NULL, NULL, 566, 29, 226, 499, FALSE, 0, NULL),
(69, 1, 'ٱلْحَآقَّةُ', 'الحاقة', NULL, 'The Inevitable Reality -', 'Saat yang tetap berlaku itu -', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 1, NULL),
(69, 2, 'مَا ٱلْحَآقَّةُ', 'ما الحاقة', NULL, 'What is the Inevitable Reality?', 'Apakah dia sifat dan keadaan saat yang tetap berlaku itu?', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 2, NULL),
(69, 3, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 'وما ادراك ما الحاقة', NULL, 'And what can make you know what is the Inevitable Reality?', 'Dan apa jalannya engkau dapat mengetahui tentang sifat dan keadaan saat yang tetap berlaku itu? (Saat itu ialah hari kiamat).', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 4, NULL),
(69, 4, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 'كذبت ثمود وعاد بالقارعة', NULL, 'Thamūd and ʿAad denied the Striking Calamity [i.e., the Resurrection].', 'Kaum Thamud dan Aad telah mendustakan hari (kiamat) yang menggempar dan mengharukan itu.', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 4, NULL),
(69, 5, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 'فاما ثمود فاهلكوا بالطاغية', NULL, 'So as for Thamūd, they were destroyed by the overpowering [blast].', 'Maka (masing-masing menerima azab dunianya) - adapun Thamud (kaum Nabi Soleh), maka mereka telah dibinasakan dengan (petir) yang melampau dahsyatnya.', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 4, NULL),
(69, 6, 'وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ', 'واما عاد فاهلكوا بريح صرصر عاتية', NULL, 'And as for ʿAad, they were destroyed by a screaming, violent wind', 'Adapun Aad (kaum Nabi Hud), maka mereka telah dibinasakan dengan angin ribut yang kencang, yang melampau kencangnya, -', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 6, NULL),
(69, 7, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَـٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ', 'سخرها عليهم سبع ليال وثمانية ايام حسوما فترى القوم فيها صرعى كانهم اعجاز نخل خاوية', NULL, 'Which He [i.e., Allāh] imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.', 'Yang diarahkannya menyerang mereka tujuh malam lapan hari terus-menerus; (kalaulah engkau menyaksikannya) maka engkau akan melihat kaum itu bergelimpangan mati, seolah-olah mereka: batang-batang pohon kurma yang (tumbang dan) lompang.', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 15, NULL),
(69, 8, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ', 'فهل ترى لهم من باقية', NULL, 'Then do you see of them any remains?', 'Dengan yang demikian, dapatkah engkau melihat lagi sisa-sisa mereka (yang masih hidup)?', FALSE, NULL, NULL, 566, 29, 227, 500, FALSE, 5, NULL),
(69, 9, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَـٰتُ بِٱلْخَاطِئَةِ', 'وجاء فرعون ومن قبله والمؤتفكات بالخاطئة', NULL, 'And there came Pharaoh and those before him and the overturned cities with sin.', 'Dan (selain dari mereka) datanglah Firaun, dan orang-orang yang terdahulu daripadanya, serta penduduk negeri-negeri yang telah ditunggang balikkan - dengan melakukan perkara-perkara yang salah.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 10, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً', 'فعصوا رسول ربهم فاخذهم اخذة رابية', NULL, 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].', 'Iaitu masing-masing menderhaka kepada Rasul (yang diutuskan oleh) Tuhan mereka, lalu Allah menyeksa mereka dengan azab yang sentiasa bertambah.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 11, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَـٰكُمْ فِى ٱلْجَارِيَةِ', 'انا لما طغى الماء حملناكم في الجارية', NULL, 'Indeed, when the water overflowed, We carried you [i.e., your ancestors] in the sailing ship', 'Sesungguhnya Kami, - ketika air (banjir) melampaui hadnya (serta menenggelamkan gunung-ganang), - telah mengangkut (serta menyelamatkan nenek moyang) kamu ke dalam bahtera Nabi Nuh (yang bergerak laju pelayarannya).', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 7, NULL),
(69, 12, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ', 'لنجعلها لكم تذكرة وتعيها اذن واعية', NULL, 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.', '(Kami lakukan yang demikian) untuk Kami jadikan peristiwa itu satu pelajaran bagi kamu, dan untuk didengar serta diambil ingat oleh telinga (orang-orang) yang mahu menerima pengajaran.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 13, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ', 'فاذا نفخ في الصور نفخة واحدة', NULL, 'Then when the Horn is blown with one blast', 'Kemudian (ketahuilah bahawa) apabila ditiup Sangkakala dengan sekali tiup, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 14, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً', 'وحملت الارض والجبال فدكتا دكة واحدة', NULL, 'And the earth and the mountains are lifted and leveled with one blow [i.e., stroke] -', 'Dan bumi serta gunung-ganang diangkat (dari tempatnya) lalu dihancurkan keduanya dengan sekali hancur, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 15, 'فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ', 'فيومئذ وقعت الواقعة', NULL, 'Then on that Day, the Occurrence [i.e., Resurrection] will occur,', 'Maka pada saat itu berlakulah hari kiamat, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 3, NULL),
(69, 16, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ', 'وانشقت السماء فهي يومئذ واهية', NULL, 'And the heaven will split [open], for that Day it is infirm.', 'Dan terbelahlah langit, lalu menjadilah ia pada saat itu reput (dan runtuh),', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 5, NULL),
(69, 17, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَـٰنِيَةٌ', 'والملك على ارجائها ويحمل عرش ربك فوقهم يومئذ ثمانية', NULL, 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].', 'Sedang malaikat-malaikat (ditempatkan) mengawal segala penjurunya, dan Arasy Tuhanmu pada saat itu dipikul oleh lapan malaikat di atas malaikat-malaikat yang mengawal itu.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 9, NULL),
(69, 18, 'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ', 'يومئذ تعرضون لا تخفى منكم خافية', NULL, 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.', 'Pada hari itu, kamu semua dihadapkan (untuk hitungan amal); tidak ada sesuatu pun yang tersembunyi (kepada Allah) dari perkara-perkara kamu yang tersembunyi.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 6, NULL),
(69, 19, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَـٰبِيَهْ', 'فاما من اوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه', NULL, 'So as for he who is given his record in his right hand, he will say, "Here, read my record!', 'Maka sesiapa yang diberikan menerima Kitab amalnya dengan tangan kanannya, maka ia akan berkata (dengan sukacitanya kepada sesiapa yang ada di sisinya): ‘Nah! Bacalah kamu Kitab amalku ini!', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 9, NULL),
(69, 20, 'إِنِّى ظَنَنتُ أَنِّى مُلَـٰقٍ حِسَابِيَهْ', 'اني ظننت اني ملاق حسابيه', NULL, 'Indeed, I was certain that I would be meeting my account."', '“Sesungguhnya aku telah mengetahui dengan yakin, bahawa aku akan menghadapi hitungan amalku (pada hari yang ditentukan)!”', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 5, NULL),
(69, 21, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 'فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ', NULL, 'So he will be in a pleasant life -', 'Maka (dengan itu) tinggallah dia dalam kehidupan yang senang lenang lagi memuaskan, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 22, 'فِى جَنَّةٍ عَالِيَةٍ', 'فِي جَنَّةٍ عَالِيَةٍ', NULL, 'In an elevated garden,', 'Di dalam Syurga yang tinggi (darjatnya), -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 23, 'قُطُوفُهَا دَانِيَةٌ', 'قُطُوفُهَا دَانِيَةٌ', NULL, 'Its [fruit] to be picked hanging near.', 'Buah-buahannya dekat untuk dipetik.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 24, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', 'كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا أَسْلَفْتُمْ فِي الْأَيَّامِ الْخَالِيَةِ', NULL, '[They will be told], "Eat and drink in satisfaction for what you put forth in the days past."', '(Masing-masing dipersilakan menikmatinya dengan dikatakan): “Makan dan minumlah kamu makanan dan minuman sebagai nikmat yang lazat dan baik kesudahannya, dengan sebab (amal-amal soleh) yang telah kamu kerjakan pada masa yang lalu (di dunia)!”', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 25, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيْتَنِى لَمْ أُوتَ كِتَٰبِيَهْ', 'وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِشِمَالِهِ فَيَقُولُ يَا لَيْتَنِي لَمْ أُوتَ كِتَابِيَهْ', NULL, 'But as for he who is given his record in his left hand, he will say, "Oh, I wish I had not been given my record', 'Adapun orang yang diberikan menerima Kitab amalnya dengan tangan kirinya, maka ia akan berkata (dengan sesalnya): “Alangkah baiknya kalau aku tidak diberikan Kitab amalku, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 26, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', NULL, 'And had not known what is my account.', '“Dan aku tidak dapat mengetahui hitungan amalku.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 27, 'يَٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', 'يَا لَيْتَهَا كَانَتِ الْقَاضِيَةَ', NULL, 'I wish it [i.e., my death] had been the decisive one.', '“Alangkah baiknya kalau kematianku di dunia dahulu, menjadi kematian pemutus (yang menamatkan kesudahanku, tidak dibangkitkan lagi); -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 28, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ', 'مَا أَغْنَىٰ عَنِّي مَالِيَهْ', NULL, 'My wealth has not availed me.', '“Harta kekayaanku tidak dapat menolongku sedikitpun; -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 29, 'هَلَكَ عَنِّى سُلْطَٰنِيَهْ', 'هَلَكَ عَنِّي سُلْطَانِيَهْ', NULL, 'Gone from me is my authority."', 'Kuat kuasaku (dan hujjah-hujjahku membela diri), telah binasa dan hilang lenyap dariku”.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 30, 'خُذُوهُ فَغُلُّوهُ', 'خُذُوهُ فَغُلُّوهُ', NULL, '[Allāh will say], "Seize him and shackle him.', '(Lalu diperintahkan malaikat penjaga neraka): “Tangkaplah orang yang berdosa itu serta belenggulah dia, -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 31, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', 'ثُمَّ الْجَحِيمَ صَلُّوهُ', NULL, 'Then into Hellfire drive him.', '“Kemudian bakarlah dia di dalam neraka Jahiim; -', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 32, 'ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ', 'ثُمَّ فِي سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَاسْلُكُوهُ', NULL, 'Then into a chain whose length is seventy cubits insert him."', '“Selain dari itu, masukkanlah dia dalam (lingkaran) rantai besi yang ukuran panjangnya tujuh puluh hasta, (dengan membelitkannya ke badannya)!', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 33, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', 'إِنَّهُ كَانَ لَا يُؤْمِنُ بِاللَّهِ الْعَظِيمِ', NULL, 'Indeed, he did not used to believe in Allāh, the Most Great,', '“Sesungguhnya dia dahulu tidak beriman kepada Allah Yang Maha Besar,', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 34, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ', NULL, 'Nor did he encourage the feeding of the poor.', '“Dan dia juga tidak menggalakkan (dirinya dan orang lain) memberi makanan (yang berhak diterima oleh) orang miskin.', FALSE, NULL, NULL, 567, 29, 227, 500, FALSE, 0, NULL),
(69, 35, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَٰهُنَا حَمِيمٌ', 'فَلَيْسَ لَهُ الْيَوْمَ هَاهُنَا حَمِيمٌ', NULL, 'So there is not for him here this Day any devoted friend', '“Maka pada hari ini, tidak ada baginya di sini (seorangpun dari) kaum kerabat serta sahabat handai (yang dapat menolongnya), -', FALSE, NULL, NULL, 568, 29, 227, 500, FALSE, 0, NULL),
(69, 36, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ', 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ', NULL, 'Nor any food except from the discharge of wounds;', '“Dan tidak ada makanan (baginya) melainkan dari air danur,', FALSE, NULL, NULL, 568, 29, 227, 500, FALSE, 0, NULL),
(69, 37, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ', 'لَّا يَأْكُلُهُ إِلَّا الْخَاطِئُونَ', NULL, 'None will eat it except the sinners.', '“Yang tidak memakannya melainkan orang-orang yang melakukan perkara yang salah”.', FALSE, NULL, NULL, 568, 29, 227, 500, FALSE, 0, NULL),
(69, 38, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'فَلَا أُقْسِمُ بِمَا تُبْصِرُونَ', NULL, 'So I swear by what you see', 'Maka Aku bersumpah: Demi segala (yang nyata) yang kamu melihatnya, -', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 39, 'وَمَا لَا تُبْصِرُونَ', 'وَمَا لَا تُبْصِرُونَ', NULL, 'And what you do not see', 'Dan segala (yang ghaib) yang kamu tidak melihatnya, -', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 40, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 'إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ', NULL, '[That] indeed, it [i.e., the Qur’ān] is the word of a noble Messenger.', 'Bahawa sesungguhnya Al-Quran itu ialah (wahyu dari Kami) yang disampaikan oleh Rasul yang mulia.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلًا مَّا تُؤْمِنُونَ', 'وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلًا مَّا تُؤْمِنُونَ', NULL, 'And it is not the word of a poet; little do you believe.', 'Dan bukanlah Al-Quran itu perkataan seorang penyair (sebagaimana yang kamu dakwakan. Tetapi sayang!) amatlah sedikit kamu beriman.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 42, 'وَلَا بِقَوْلِ كَاهِنٍ قَلِيلًا مَّا تَذَكَّرُونَ', 'وَلَا بِقَوْلِ كَاهِنٍ قَلِيلًا مَّا تَذَكَّرُونَ', NULL, 'Nor the word of a soothsayer; little do you remember.', 'Dan juga bukanlah Al-Quran itu perkataan seorang pawang (sebagaimana yang kamu katakan. Tetapi sayang!) amatlah sedikit kamu mengambil peringatan.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 43, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'تَنزِيلٌ مِّن رَّبِّ الْعَالَمِينَ', NULL, '[It is] a revelation from the Lord of the worlds.', '(Al-Quran itu) diturunkan dari Allah Tuhan sekalian alam.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ الْأَقَاوِيلِ', NULL, 'And if he [i.e., Muḥammad] had made up about Us some [false] sayings,', 'Dan kalaulah (Nabi Muhammad yang menyampaikan Al-Quran itu) mengatakan atas nama Kami secara dusta - sebarang kata-kata rekaan, -', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 45, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 'لَأَخَذْنَا مِنْهُ بِالْيَمِينِ', NULL, 'We would have seized him by the right hand;', 'Sudah tentu Kami akan menyentapnya, dengan kekuasaan Kami, -', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 'ثُمَّ لَقَطَعْنَا مِنْهُ الْوَتِينَ', NULL, 'Then We would have cut from him the aorta.', 'Kemudian sudah tentu Kami akan memutuskan tali jantungnya (supaya ia mati dengan serta-merta);', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 47, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ', 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَاجِزِينَ', NULL, 'And there is no one of you who could prevent [Us] from him.', 'Maka tidak ada seorangpun di antara kamu yang dapat menghalang (tindakan Kami itu) daripada menimpanya.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 48, 'وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ', 'وَإِنَّهُ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ', NULL, 'And indeed, it [i.e., the Qur’ān] is a reminder for the righteous.', 'Dan sesungguhnya (Al-Quran) itu tetap menjadi peringatan bagi orang-orang yang bertaqwa.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 49, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', NULL, 'And indeed, We know that among you are deniers.', 'Dan sesungguhnya Kami sedia mengetahui bahawa ada di antara kamu yang mendustakan (Al-Quran, maka Kami akan membalasnya).', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 50, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ', 'وَإِنَّهُ لَحَسْرَةٌ عَلَى الْكَافِرِينَ', NULL, 'And indeed, it will be [a cause of] regret upon the disbelievers.', 'Dan sesungguhnya Al-Quran itu sudah tentu akan menyebabkan penyesalan bagi orang-orang yang kafir (semasa mereka menerima balasan).', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 51, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 'وَإِنَّهُ لَحَقُّ الْيَقِينِ', NULL, 'And indeed, it is the truth of certainty.', 'Dan sesungguhnya Al-Quran itu adalah kebenaran yang diyakini (dengan seyakin-yakinnya).', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(69, 52, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ', NULL, 'So exalt the name of your Lord, the Most Great.', 'Oleh itu bertasbihlah dengan memuji nama Tuhanmu Yang Maha Besar.', FALSE, NULL, NULL, 568, 29, 227, 501, FALSE, 0, NULL),
(70, 1, 'سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ', 'سال سائل بعذاب واقع', NULL, 'A supplicant asked for a punishment bound to happen', 'Salah seorang (dari kalangan orang-orang kafir Makkah, secara mengejek-ejek) meminta kedatangan azab yang (dijanjikan) akan berlaku,', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 4, NULL),
(70, 2, 'لِّلْكَـٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ', 'للكافرين ليس له دافع', NULL, 'To the disbelievers; of it there is no preventer.', 'Azab yang disediakan untuk orang-orang yang kafir, yang tidak ada sesiapapun dapat menolak kedatangannya -', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 4, NULL),
(70, 3, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', 'من الله ذي المعارج', NULL, '[It is] from Allāh, owner of the ways of ascent.', 'Dari Allah yang menguasai tempat-tempat turun naik -', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 4, NULL),
(70, 4, 'تَعْرُجُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ', 'تعرج الملائكة والروح اليه في يوم كان مقداره خمسين الف سنة', NULL, 'The angels and the Spirit [i.e., Gabriel] will ascend to Him during a Day the extent of which is fifty thousand years.', 'Yang dilalui oleh malaikat-malaikat dan Jibril ke pusat pemerintahanNya (untuk menerima dan menyempurnakan tugas masing-masing, terutama) pada satu masa yang adalah tempohnya (dirasai oleh orang-orang yang bersalah) sungguh panjang, (kerana banyak hitungan hisab dan berat soal jawabnya).', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 11, NULL),
(70, 5, 'فَٱصْبِرْ صَبْرًا جَمِيلًا', 'فاصبر صبرا جميلا', NULL, 'So be patient with gracious patience.', 'Maka bersabarlah (wahai Muhammad terhadap ejekan golongan yang kafir itu), dengan cara kesabaran yang sebaik-baiknya.', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 3, NULL),
(70, 6, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا', 'انهم يرونه بعيدا', NULL, 'Indeed, they see it [as] distant,', 'Sebenarnya mereka memandang azab itu jauh (daripada berlaku),', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 3, NULL),
(70, 7, 'وَنَرَىٰهُ قَرِيبًا', 'ونراه قريبا', NULL, 'But We see it [as] near.', 'Sedang Kami memandangnya dekat, (tetap akan berlaku),', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 2, NULL),
(70, 8, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', 'يوم تكون السماء كالمهل', NULL, 'On the Day the sky will be like murky oil,', '(Iaitu) pada hari langit menjadi seperti tembaga cair,', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 4, NULL),
(70, 9, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', 'وتكون الجبال كالعهن', NULL, 'And the mountains will be like wool,', 'Dan gunung-ganang pula menjadi seperti bulu (yang berterbangan)', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 3, NULL),
(70, 10, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا', 'ولا يسال حميم حميما', NULL, 'And no friend will ask [anything of] a friend,', 'Dan sahabat karib tidak bertanyakan hal sahabat karibnya, (kerana tiap-tiap seorang sibuk memikirkan hal keadaannya sendiri),', FALSE, NULL, NULL, 568, 29, 227, 502, FALSE, 4, NULL),
(70, 11, 'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', 'يبصرونهم يود المجرم لو يفتدي من عذاب يومئذ ببنيه', NULL, 'They will be shown each other. The criminal will wish that he could be ransomed from the punishment of that Day by his children', 'Padahal masing-masing diberi melihat setengahnya yang lain; (pada saat yang demikian) orang yang kafir suka kiranya dapat menebus dirinya dari azab itu dengan anak-anaknya sendiri,', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 9, NULL),
(70, 12, 'وَصَـٰحِبَتِهِۦ وَأَخِيهِ', 'وصاحبته واخيه', NULL, 'And his wife and his brother', 'Dan isteri serta saudaranya,', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 2, NULL),
(70, 13, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', 'وفصيلته التي تؤويه', NULL, 'And his nearest kindred who shelter him', 'Dan kaum kerabatnya yang melindunginya,', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 3, NULL),
(70, 14, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ', 'ومن في الارض جميعا ثم ينجيه', NULL, 'And whoever is on earth entirely [so] then it could save him.', 'Dan juga sekalian makhluk yang ada di bumi - kemudian (diharapkannya) tebusan itu dapat menyelamatkannya.', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 6, NULL),
(70, 15, 'كَلَّآ ۖ إِنَّهَا لَظَىٰ', 'كلا انها لظى', NULL, 'No! Indeed, it is the Flame [of Hell],', 'Tidak sekali-kali (sebagaimana yang diharapkannya)! Sesungguhnya neraka (yang disediakan baginya) tetap menjulang-julang apinya,', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 3, NULL),
(70, 16, 'نَزَّاعَةً لِّلشَّوَىٰ', 'نزاعة للشوى', NULL, 'A remover of exteriors.', '(Membakar serta) menggugurkan kulit ubun-ubun dan anggota anggota tubuh badan,', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 2, NULL),
(70, 17, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', 'تدعو من ادبر وتولى', NULL, 'It invites he who turned his back [on truth] and went away [from obedience]', 'Neraka itu juga memanggil dan menarik orang yang membelakangi serta berpaling (dari kebenaran),', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 4, NULL),
(70, 18, 'وَجَمَعَ فَأَوْعَىٰٓ', 'وجمع فاوعى', NULL, 'And collected [wealth] and hoarded.', 'Dan yang mengumpulkan harta kekayaan lalu menyimpannya (dengan tidak membayar zakatnya).', FALSE, NULL, NULL, 569, 29, 227, 502, FALSE, 2, NULL),
(70, 19, '۞ إِنَّ ٱلْإِنسَـٰنَ خُلِقَ هَلُوعًا', 'ان الانسان خلق هلوعا', NULL, 'Indeed, mankind was created anxious:', 'Sesungguhnya manusia itu dijadikan bertabiat resah gelisah (lagi bakhil kedekut); -', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 4, NULL),
(70, 20, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا', 'اذا مسه الشر جزوعا', NULL, 'When evil touches him, impatient,', 'Apabila ia ditimpa kesusahan, dia sangat resah gelisah;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 4, NULL),
(70, 21, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', 'وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا', NULL, 'And when good touches him, withholding [of it],', 'Dan apabila ia beroleh kesenangan, ia sangat bakhil kedekut;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 22, 'إِلَّا ٱلْمُصَلِّينَ', 'إِلَّا الْمُصَلِّينَ', NULL, 'Except the observers of prayer -', 'Kecuali orang-orang yang mengerjakan sembahyang -', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 23, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', 'الَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَائِمُونَ', NULL, 'Those who are constant in their prayer', 'Iaitu mereka yang tetap mengerjakan sembahyangnya;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 24, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ', 'وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَّعْلُومٌ', NULL, 'And those within whose wealth is a known right', 'Dan mereka (yang menentukan bahagian) pada harta-hartanya, menjadi hak yang termaklum -', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 25, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'لِّلسَّائِلِ وَالْمَحْرُومِ', NULL, 'For the petitioner and the deprived -', 'Bagi orang miskin yang meminta dan orang miskin yang menahan diri (daripada meminta);', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 26, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', 'وَالَّذِينَ يُصَدِّقُونَ بِيَوْمِ الدِّينِ', NULL, 'And those who believe in the Day of Recompense', 'Dan mereka yang percayakan hari pembalasan (dengan mengerjakan amal-amal yang soleh sebagai buktinya);', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 27, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'وَالَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', NULL, 'And those who are fearful of the punishment of their Lord -', 'Dan mereka yang cemas takut daripada ditimpa azab Tuhannya, -', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 28, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ', 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ', NULL, 'Indeed, the punishment of their Lord is not that from which one is safe -', 'Kerana sesungguhnya azab Tuhan mereka, tidak patut (bagi seseorangpun) merasa aman terhadapnya;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 29, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ', NULL, 'And those who guard their private parts', 'Dan mereka yang menjaga kehormatannya, -', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 30, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'إِلَّا عَلَىٰ أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', NULL, 'Except from their wives or those their right hands possess, for indeed, they are not to be blamed -', 'Kecuali kepada isterinya atau kepada hambanya, maka sesungguhnya mereka tidak tercela;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 31, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'فَمَنِ ابْتَغَىٰ وَرَاءَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْعَادُونَ', NULL, 'But whoever seeks beyond that, then they are the transgressors -', 'Kemudian sesiapa yang mengingini selain dari yang demikian, maka merekalah orang-orang yang melampaui batas;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 32, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ', NULL, 'And those who are to their trusts and promises attentive', 'Dan mereka yang menjaga amanah dan janjinya;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 33, 'وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ', 'وَالَّذِينَ هُم بِشَهَادَاتِهِمْ قَائِمُونَ', NULL, 'And those who are in their testimonies upright', 'Dan mereka yang memberikan keterangan dengan benar lagi adil (semasa mereka menjadi saksi);', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 34, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'وَالَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', NULL, 'And those who [carefully] maintain their prayer:', 'Dan mereka yang tetap memelihara sembahyangnya;', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 35, 'أُو۟لَٰٓئِكَ فِى جَنَّٰتٍ مُّكْرَمُونَ', 'أُولَٰئِكَ فِي جَنَّاتٍ مُّكْرَمُونَ', NULL, 'They will be in gardens, honored.', 'Mereka (yang demikian sifatnya) ditempatkan di dalam Syurga dengan diberikan penghormatan.', FALSE, NULL, NULL, 569, 29, 228, 502, FALSE, 0, NULL),
(70, 36, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', 'فَمَالِ الَّذِينَ كَفَرُوا قِبَلَكَ مُهْطِعِينَ', NULL, 'So what is [the matter] with those who disbelieve, hastening [from] before you, [O Muḥammad],', 'Maka apakah yang menyebabkan orang-orang kafir, yang menentangmu (wahai Muhammad) datang berkejaran ke sisimu -', FALSE, NULL, NULL, 569, 29, 228, 503, FALSE, 0, NULL),
(70, 37, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', 'عَنِ الْيَمِينِ وَعَنِ الشِّمَالِ عِزِينَ', NULL, '[To sit] on [your] right and [your] left in separate groups?', '(Sambil mereka) berkumpul berpuak-puak di sebelah kanan dan di sebelah kirimu.', FALSE, NULL, NULL, 569, 29, 228, 503, FALSE, 0, NULL),
(70, 38, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ', 'أَيَطْمَعُ كُلُّ امْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ', NULL, 'Does every person among them aspire to enter a garden of pleasure?', 'Patutkah tiap-tiap seorang dari mereka berharap supaya dimasukkan ke dalam Syurga yang penuh nikmat (sedang ia tidak beriman)?', FALSE, NULL, NULL, 569, 29, 228, 503, FALSE, 0, NULL),
(70, 39, 'كَلَّآ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ', 'كَلَّا إِنَّا خَلَقْنَاهُم مِّمَّا يَعْلَمُونَ', NULL, 'No! Indeed, We have created them from that which they know.', 'Tidak sekali-kali! (Mereka yang kufur ingkar tidak akan dapat memasukinya). Sesungguhnya Kami telah menciptakan mereka dari apa yang mereka sedia mengetahuinya.', FALSE, NULL, NULL, 569, 29, 228, 503, FALSE, 0, NULL),
(70, 40, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'فَلَا أُقْسِمُ بِرَبِّ الْمَشَارِقِ وَالْمَغَارِبِ إِنَّا لَقَادِرُونَ', NULL, 'So I swear by the Lord of [all] risings and settings that indeed We are able', 'Maka Aku bersumpah dengan (kebesaranKu) Tuhan yang menguasai (seluruh alam, meliputi) tempat-tempat terbit (matahari dan bulan bintang) dan tempat-tempat tenggelamnya, - sesungguhnya Kami berkuasa -', FALSE, NULL, NULL, 570, 29, 228, 503, FALSE, 0, NULL),
(70, 41, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'عَلَىٰ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', NULL, 'To replace them with better than them; and We are not to be outdone.', '(Membinasakan mereka, serta) menggantikan mereka dengan makhluk-makluk yang lebih baik dari mereka; dan Kami tidak sekali-kali dapat dikalahkan atau dilemahkan.', FALSE, NULL, NULL, 570, 29, 228, 503, FALSE, 0, NULL),
(70, 42, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّىٰ يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ', NULL, 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -', 'Oleh itu, biarkanlah mereka (wahai Muhammad) tenggelam dalam kesesatannya dan leka bermain-main (dalam dunianya), sehingga mereka menemui hari yang dijanjikan kepada mereka (untuk menerima balasan)! -', FALSE, NULL, NULL, 570, 29, 228, 503, FALSE, 0, NULL),
(70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ', 'يَوْمَ يَخْرُجُونَ مِنَ الْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ', NULL, 'The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening.', 'Iaitu hari mereka segera keluar dari kubur masing-masing menuju (ke Padang Mahsyar) dengan keadaan seolah-olah mereka berkejaran ke (tempat) berhala-berhala (yang mereka sembah dahulu),', FALSE, NULL, NULL, 570, 29, 228, 503, FALSE, 0, NULL),
(70, 44, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'خَاشِعَةً أَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ الْيَوْمُ الَّذِي كَانُوا يُوعَدُونَ', NULL, 'Their eyes humbled, humiliation will cover them. That is the Day which they had been promised.', 'Sambil pandangan mereka tunduk, serta mereka diliputi kehinaan; itulah hari yang telah dijanjikan kepada mereka.', FALSE, NULL, NULL, 570, 29, 228, 503, FALSE, 0, NULL),
(71, 1, 'إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 'انا ارسلنا نوحا الى قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم', NULL, 'Indeed, We sent Noah to his people, [saying], "Warn your people before there comes to them a painful punishment."', 'Sesungguhnya Kami telah mengutus Nabi Nuh kepada kaumnya, (dengan berfirman kepadanya): “Berikanlah peringatan dan amaran kepada kaummu sebelum mereka didatangi azab yang tidak terperi sakitnya”.', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 14, NULL),
(71, 2, 'قَالَ يَـٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'قال يا قوم اني لكم نذير مبين', NULL, 'He said, "O my people, indeed I am to you a clear warner -', 'dia pun (menyeru mereka dengan) berkata: “Wahai kaumku! Sesungguhnya aku ini diutus kepada kamu, sebagai pemberi ingatan dan amaran yang nyata;', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 6, NULL),
(71, 3, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', 'ان اعبدوا الله واتقوه واطيعون', NULL, 'To worship Allāh, fear Him and obey me.', '“Iaitu sembahlah kamu akan Allah dan bertaqwalah kepadaNya, serta taatlah kamu kepadaku;', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 5, NULL),
(71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ', 'يغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون', NULL, 'He [i.e., Allāh] will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allāh, when it comes, will not be delayed, if you only knew."', '“Supaya Allah mengampunkan bagi kamu sebahagian dari dosa-dosa kamu, dan memberi kamu hidup (dengan tidak terkena azab) hingga ke suatu masa yang tertentu; (maka segeralah beribadat dan bertaqwa) kerana sesungguhnya ajal (yang telah ditetapkan) Allah, apabila sampai masanya, tidak dapat ditangguhkan; kalaulah kamu mengetahui (hakikat ini tentulah kamu segera beriman)”.', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 18, NULL),
(71, 5, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 'قال رب اني دعوت قومي ليلا ونهارا', NULL, 'He said, "My Lord, indeed I invited my people [to truth] night and day.', '(Setelah puas menyeru mereka), Nabi Nuh berdoa dengan berkata: “Wahai Tuhanku, sesungguhnya aku telah menyeru kaumku siang dan malam (supaya mereka beriman);', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 7, NULL),
(71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 'فلم يزدهم دعائي الا فرارا', NULL, 'But my invitation increased them not except in flight [i.e., aversion].', '“Maka seruanku itu tidak memberikan mereka (sesuatu faedah pun) selain daripada menambahi mereka melarikan diri (dari kebenaran).', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 5, NULL),
(71, 7, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', 'واني كلما دعوتهم لتغفر لهم جعلوا اصابعهم في اذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا', NULL, 'And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance.', '“Dan sesungguhnya aku, tiap-tiap kali menyeru mereka (beriman) supaya Engkau mengampunkan dosa-dosa mereka, - mereka menyumbatkan telinganya dengan jari masing-masing, dan berselubung dengan pakaiannya, serta berdegil dengan keingkarannya, dan berlaku sombong takbur dengan melampau.', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 14, NULL),
(71, 8, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', 'ثم اني دعوتهم جهارا', NULL, 'Then I invited them publicly.', '“Kemudian aku telah menyeru mereka dengan terang-terang;', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 4, NULL),
(71, 9, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', 'ثم اني اعلنت لهم واسررت لهم اسرارا', NULL, 'Then I announced to them and [also] confided to them secretly', '“Selain dari itu, aku (berulang-ulang) menyeru mereka secara beramai-ramai dengan berterus-terang, dan menyeru mereka lagi secara berseorangan dengan perlahan-lahan.', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 7, NULL),
(71, 10, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا', 'فقلت استغفروا ربكم انه كان غفارا', NULL, 'And said, ''Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.', '“Sehingga aku berkata (kepada mereka): ‘Pohonkanlah ampun kepada Tuhan kamu, sesungguhnya adalah Ia Maha Pengampun.', FALSE, NULL, NULL, 570, 29, 228, 504, FALSE, 6, NULL),
(71, 11, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا', 'يرسل السماء عليكم مدرارا', NULL, 'He will send [rain from] the sky upon you in [continuing] showers', '“(Sekiranya kamu berbuat demikian), Ia akan menghantarkan hujan lebat mencurah-curah, kepada kamu;', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 4, NULL),
(71, 12, 'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا', 'ويمددكم باموال وبنين ويجعل لكم جنات ويجعل لكم انهارا', NULL, 'And give you increase in wealth and children and provide for you gardens and provide for you rivers.', '“Dan Ia akan memberi kepada kamu dengan banyaknya harta kekayaan serta anak-pinak; dan Ia akan mengadakan bagi kamu kebun-kebun tanaman, serta mengadakan bagi kamu sungai-sungai (yang mengalir di dalamnya).', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 9, NULL),
(71, 13, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا', 'ما لكم لا ترجون لله وقارا', NULL, 'What is [the matter] with you that you do not attribute to Allāh [due] grandeur', '“Mengapa kamu berkeadaan tidak menghargai kebesaran Allah (dan kekuasaanNya), -', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 6, NULL),
(71, 14, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', 'وقد خلقكم اطوارا', NULL, 'While He has created you in stages?', '“Padahal sesungguhnya Ia telah menciptakan kamu dengan kejadian yang berperingkat-peringkat?', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 3, NULL),
(71, 15, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا', 'الم تروا كيف خلق الله سبع سماوات طباقا', NULL, 'Do you not consider how Allāh has created seven heavens in layers', '“Tidakkah kamu mengetahui dan memikirkan bagaimana Allah telah menciptakan tujuh petala langit bertingkat-tingkat,', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 8, NULL),
(71, 16, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا', 'وجعل القمر فيهن نورا وجعل الشمس سراجا', NULL, 'And made the moon therein a [reflected] light and made the sun a burning lamp?', '“Dan Ia menjadikan padanya bulan sebagai cahaya serta menjadikan matahari sebagai lampu (yang terang-benderang),', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 7, NULL),
(71, 17, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا', 'والله انبتكم من الارض نباتا', NULL, 'And Allāh has caused you to grow from the earth a [progressive] growth.', '“Dan Allah telah menumbuhkan kamu (hidup dari benda-benda yang berasal) dari bumi, dengan pertumbuhan yang sungguh-sungguh sempurna,', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 5, NULL),
(71, 18, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا', 'ثم يعيدكم فيها ويخرجكم اخراجا', NULL, 'Then He will return you into it and extract you [another] extraction.', '“Kemudian Ia mengembalikan kamu ke dalam bumi (sesudah mati), dan mengeluarkan kamu daripadanya (sesudah dihidupkan semula untuk dihitung amal kamu dan diberi balasan), dengan pengeluaran yang sesungguh-sungguhnya?', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 5, NULL),
(71, 19, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', 'والله جعل لكم الارض بساطا', NULL, 'And Allāh has made for you the earth an expanse', '“Dan Allah telah menjadikan bumi bagi kamu sebagai hamparan,', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 5, NULL),
(71, 20, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', 'لتسلكوا منها سبلا فجاجا', NULL, 'That you may follow therein roads of passage.''"', '“Supaya kamu melalui jalan-jalan yang luas padanya”.', FALSE, NULL, NULL, 571, 29, 228, 504, FALSE, 4, NULL),
(71, 21, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِي وَاتَّبَعُوا مَن لَّمْ يَزِدْهُ مَالُهُ وَوَلَدُهُ إِلَّا خَسَارًا', NULL, 'Noah said, "My Lord, indeed they have disobeyed me and followed him whose wealth and children will not increase him except in loss.', 'Nabi Nuh (merayu lagi dengan) berkata: “Wahai Tuhanku! Sesungguhnya, mereka telah menderhaka kepadaku, dan mereka telah menurut orang yang harta bendanya dan anak-pinaknya tidak menambahinya melainkan kerugian (di akhirat kelak).', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 22, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', 'وَمَكَرُوا مَكْرًا كُبَّارًا', NULL, 'And they conspired an immense conspiracy', '“Dan mereka telah menjalankan tipu daya dengan merancangkan rancangan yang amat besar jahatnya (untuk menentang seruanku).', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 23, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', 'وَقَالُوا لَا تَذَرُنَّ آلِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', NULL, 'And said, ''Never leave your gods and never leave Wadd or Suwāʿ or Yaghūth and Yaʿūq and Nasr.''', '“Dan (ketua-ketua) mereka (menghasut dengan) berkata: ‘Jangan kamu meninggalkan (penyembahan) tuhan-tuhan kamu, terutama (penyembahan) Wadd, dan Suwaa’, dan Yaghuth, dan Ya''uuq, serta Nasr.', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 24, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًا', 'وَقَدْ أَضَلُّوا كَثِيرًا وَلَا تَزِدِ الظَّالِمِينَ إِلَّا ضَلَالًا', NULL, 'And already they have misled many. And, [my Lord], do not increase the wrongdoers except in error."', '“Dan sesungguhnya ketua-ketua itu telah menyesatkan kebanyakan (dari umat manusia); dan (dengan yang demikian) janganlah Engkau (wahai Tuhanku) menambahi orang-orang yang zalim itu melainkan kesesatan jua”.', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 25, 'مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', 'مِّمَّا خَطِيئَاتِهِمْ أُغْرِقُوا فَأُدْخِلُوا نَارًا فَلَمْ يَجِدُوا لَهُم مِّن دُونِ اللَّهِ أَنصَارًا', NULL, 'Because of their sins they were drowned and put into the Fire, and they found not for themselves besides Allāh [any] helpers.', 'Disebabkan dosa-dosa dan kesalahan mereka, mereka ditenggelamkan (dengan banjir dan taufan), kemudian (pada hari akhirat) dimasukkan ke dalam neraka; maka mereka tidak akan beroleh sebarang penolong yang lain dari Allah (yang dapat memberikan pertolongan).', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 26, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا', 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا', NULL, 'And Noah said, "My Lord, do not leave upon the earth from among the disbelievers an inhabitant.', 'Dan Nabi Nuh (merayu lagi dengan) berkata: “Wahai Tuhanku! Janganlah Engkau biarkan seorangpun dari orang-orang kafir itu hidup di atas muka bumi!', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 27, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا عِبَادَكَ وَلَا يَلِدُوا إِلَّا فَاجِرًا كَفَّارًا', NULL, 'Indeed, if You leave them, they will mislead Your servants and not beget except [every] wicked one and [confirmed] disbeliever.', '“Kerana sesungguhnya jika Engkau biarkan mereka (hidup), nescaya mereka akan menyesatkan hamba-hambaMu, dan mereka tidak akan melahirkan anak melainkan yang berbuat dosa lagi kufur ingkar.', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(71, 28, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا', 'رَّبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَلَا تَزِدِ الظَّالِمِينَ إِلَّا تَبَارًا', NULL, 'My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction."', '“Wahai Tuhanku! Ampunkanlah bagiku, dan bagi kedua ibu bapaku, serta bagi sesiapa yang masuk ke rumahku dengan keadaan beriman; dan (ampunkanlah) bagi sekalian orang-orang yang beriman, lelaki dan perempuan (dalam segala zaman); dan janganlah Engkau tambahi orang-orang yang zalim melainkan kebinasaan!”', FALSE, NULL, NULL, 571, 29, 228, 505, FALSE, 0, NULL),
(72, 1, 'قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', 'قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرانا عجبا', NULL, 'Say, [O Muḥammad], "It has been revealed to me that a group of the jinn listened and said, ''Indeed, we have heard an amazing Qur’ān [i.e., recitation].', 'Katakanlah (wahai Muhammad): “Telah diwahyukan kepadaku, bahawa sesungguhnya: satu rombongan jin telah mendengar (Al-Quran yang aku bacakan), lalu mereka (menyampaikan hal itu kepada kaumnya dengan) berkata: ‘Sesungguhnya kami telah mendengar Al-Quran (sebuah Kitab Suci) yang susunannya dan kandungannya sungguh menakjubkan!', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 13, NULL),
(72, 2, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', 'يهدي الى الرشد فامنا به ولن نشرك بربنا احدا', NULL, 'It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone.', '‘Kitab yang memberi panduan ke jalan yang betul, lalu kami beriman kepadanya, dan kami tidak sekali-kali akan mempersekutukan sesuatu makhluk dengan Tuhan kami.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 9, NULL),
(72, 3, 'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةً وَلَا وَلَدًا', 'وانه تعالى جد ربنا ما اتخذ صاحبة ولا ولدا', NULL, 'And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son', '‘Dan (ketahuilah wahai kaum kami!) Bahawa sesungguhnya: tertinggilah kebesaran dan keagungan Tuhan kita daripada beristeri atau beranak.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 9, NULL),
(72, 4, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 'وانه كان يقول سفيهنا على الله شططا', NULL, 'And that our foolish one [i.e., Iblees] has been saying about Allāh an excessive transgression.', '‘Dan (dengan ajaran Al-Quran nyatalah) bahawa sesungguhnya: (ketua) yang kurang akal pertimbangannya dari kalangan kita telah mengatakan terhadap Allah kata-kata yang melampaui kebenaran;', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 7, NULL),
(72, 5, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 'وانا ظننا ان لن تقول الانس والجن على الله كذبا', NULL, 'And we had thought that mankind and the jinn would never speak about Allāh a lie.', '‘Dan bahawa sesungguhnya (nyatalah kesalahan) kita menyangka bahawa manusia dan jin tidak sekali-kali akan berani mengatakan sesuatu yang dusta terhadap Allah.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 10, NULL),
(72, 6, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', 'وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا', NULL, 'And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden [i.e., sin].', '‘Dan bahawa sesungguhnya adalah (amat salah perbuatan) beberapa orang dari manusia, menjaga dan melindungi dirinya dengan meminta pertolongan kepada ketua-ketua golongan jin, kerana dengan permintaan itu mereka menjadikan golongan jin bertambah sombong dan jahat.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 11, NULL),
(72, 7, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', 'وانهم ظنوا كما ظننتم ان لن يبعث الله احدا', NULL, 'And they had thought, as you thought, that Allāh would never send anyone [as a messenger].', '‘Dan bahawa sesungguhnya (tidaklah benar) manusia menyangka sebagaimana yang kamu sangka, bahawa Allah tidak sekali-kali mengutuskan sebarang Rasul (atau tidak akan membangkitkan manusia pada hari kiamat).', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 9, NULL),
(72, 8, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَـٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', 'وانا لمسنا السماء فوجدناها ملئت حرسا شديدا وشهبا', NULL, 'And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames.', '‘Dan bahawa sesungguhnya kami telah berusaha mencari berita langit, lalu kami dapati langit itu penuh dengan pengawal-pengawal yang sangat kuat kawalannya, dan (dengan rejaman-rejaman) api yang menyala.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 8, NULL),
(72, 9, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَـٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 'وانا كنا نقعد منها مقاعد للسمع فمن يستمع الان يجد له شهابا رصدا', NULL, 'And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him.', '‘Padahal sesungguhnya kami dahulu biasa menduduki tempat-tempat (perhentian) di langit untuk mendengar (percakapan penduduknya); maka sekarang sesiapa yang cuba mendengar, akan mendapati api yang menyala yang menunggu merejamnya.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 13, NULL),
(72, 10, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', 'وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا', NULL, 'And we do not know [therefore] whether evil is intended for those on earth or whether their Lord intends for them a right course.', '‘Dan bahawa sesungguhnya kami tidak mengetahui adakah (dengan adanya kawalan langit yang demikian) hendak menimpakan bala bencana kepada penduduk bumi, atau pun Tuhan mereka hendak melimpahkan kebaikan kepada mereka?', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 13, NULL),
(72, 11, 'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًا', 'وانا منا الصالحون ومنا دون ذلك كنا طرائق قددا', NULL, 'And among us are the righteous, and among us are [others] not so; we were [of] divided ways.', '‘Dan bahawa sesungguhnya (memang maklum) ada di antara kita golongan yang baik keadaannya, dan ada di antara kita yang lain dari itu; kita masing-masing adalah menurut jalan dan cara yang berlainan.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 9, NULL),
(72, 12, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 'وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا', NULL, 'And we have become certain that we will never cause failure to Allāh upon earth, nor can we escape Him by flight.', '‘Dan bahawa sesungguhnya kita (sekarang) mengetahui, bahawa kita tidak sekali-kali akan dapat melepaskan diri dari balasan Allah (walau di mana sahaja kita berada) di bumi, dan kita juga tidak sekali-kali akan dapat melarikan diri dari balasanNya (walau ke langit sekalipun).', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 11, NULL),
(72, 13, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 'وانا لما سمعنا الهدى امنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا', NULL, 'And when we heard the guidance [i.e., the Qur’ān], we believed in it. And whoever believes in his Lord will not fear deprivation or burden.', '‘Dan bahawa sesungguhnya kami, ketika mendengar petunjuk (Al-Quran), kami beriman kepadanya (dengan tidak bertangguh lagi); kerana sesiapa yang beriman kepada Tuhannya, maka tidaklah ia akan merasa bimbang menanggung kerugian (mengenai amalnya yang baik), dan juga tidak akan ditimpakan sebarang kesusahan.', FALSE, NULL, NULL, 572, 29, 229, 506, FALSE, 14, NULL),
(72, 14, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَـٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَـٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', 'وانا منا المسلمون ومنا القاسطون فمن اسلم فاولئك تحروا رشدا', NULL, 'And among us are Muslims [in submission to Allāh], and among us are the unjust. And whoever has become Muslim - those have sought out the right course.', '‘Dan bahawa sesungguhnya (dengan datangnya Al-Quran, nyatalah) ada di antara kita golongan yang berugama Islam, dan ada pula golongan yang (kufur derhaka dengan) menyeleweng dari jalan yang benar; maka sesiapa yang menurut Islam (dengan beriman dan taat), maka merekalah golongan yang bersungguh-sungguh mencari dan menurut jalan yang benar,', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 10, NULL),
(72, 15, 'وَأَمَّا ٱلْقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 'واما القاسطون فكانوا لجهنم حطبا', NULL, 'But as for the unjust, they will be, for Hell, firewood.''', '‘Adapun orang-orang yang menyeleweng dari jalan yang benar, maka mereka menjadi bahan bakaran bagi neraka Jahannam.’', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 5, NULL),
(72, 16, 'وَأَلَّوِ ٱسْتَقَـٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَـٰهُم مَّآءً غَدَقًا', 'وان لو استقاموا على الطريقة لاسقيناهم ماء غدقا', NULL, 'And [Allāh revealed] that if they had remained straight on the way, We would have given them abundant rain [i.e., provision]', '(Nabi Muhammad diwahyukan menerangkan lagi): “Dan bahawa sesungguhnya! Kalaulah mereka (manusia dan jin) itu berjalan betul di atas jalan (Islam), sudah tentu Kami (akan memberikan mereka sebab-sebab kemewahan, terutama) menurunkan hujan lebat kepada mereka.', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 7, NULL),
(72, 17, 'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 'لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا', NULL, 'So We might test them therein. And whoever turns away from the remembrance of his Lord He will put into arduous punishment.', '“(Pemberian yang demikian) untuk Kami menguji (dan menzahirkan bawaan dan keadaan) mereka dalam menikmati apa yang Kami berikan itu (adakah mereka bersyukur dan tetap betul menurut Islam); dan (ingatlah), sesiapa yang berpaling dari mengingati Tuhannya, (dengan berlaku ingkar - derhaka, maka) Tuhan akan memasukkannya ke dalam azab yang memuncak beratnya.', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 10, NULL),
(72, 18, 'وَأَنَّ ٱلْمَسَـٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', 'وان المساجد لله فلا تدعوا مع الله احدا', NULL, 'And [He revealed] that the masjids are for Allāh, so do not invoke with Allāh anyone.', '“Dan bahawa sesungguhnya masjid-masjid itu untuk (ibadat kepada) Allah semata-mata; maka janganlah kamu seru dan sembah sesiapapun bersama-sama Allah.', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 8, NULL),
(72, 19, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 'وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا', NULL, 'And that when the Servant [i.e., Prophet] of Allāh stood up supplicating Him, they almost became about him a compacted mass."', '“Dan bahawa sesungguhnya, ketika hamba Allah (Nabi Muhammad) berdiri mengerjakan ibadat kepadaNya, mereka hampir-hampir menindih satu sama lain mengerumuninya”.', FALSE, NULL, NULL, 573, 29, 229, 506, FALSE, 10, NULL),
(72, 20, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', 'قل انما ادعو ربي ولا اشرك به احدا', NULL, 'Say, [O Muḥammad], "I only invoke my Lord and do not associate with Him anyone."', 'Katakanlah (wahai Muhammad): “Sesungguhnya aku hanyalah beribadat kepada Tuhanku semata-mata, dan aku tidak mempersekutukanNya dengan sesiapapun”.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 8, NULL),
(72, 21, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 'قُلْ إِنِّي لَا أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', NULL, 'Say, "Indeed, I do not possess for you [the power of] harm or right direction."', 'Katakanlah lagi; “Sesungguhnya aku tidak berkuasa mendatangkan sebarang mudarat dan tidak juga berkuasa mendatangkan sebarang kebaikan bagi kamu.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 22, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'قُلْ إِنِّي لَن يُجِيرَنِي مِنَ اللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِ مُلْتَحَدًا', NULL, 'Say, "Indeed, there will never protect me from Allāh anyone [if I should disobey], nor will I find in other than Him a refuge.', 'Katakanlah lagi; “Sesungguhnya aku, tidak sekali-kali akan dapat diberi perlindungan oleh sesiapapun dari (azab) Allah (jika aku menderhaka kepadaNya), dan aku tidak sekali-kali akan mendapat tempat perlindungan selain daripadaNya,', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 23, 'إِلَّا بَلَٰغًا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا', 'إِلَّا بَلَاغًا مِّنَ اللَّهِ وَرِسَالَاتِهِ وَمَن يَعْصِ اللَّهَ وَرَسُولَهُ فَإِنَّ لَهُ نَارَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا', NULL, 'But [I have for you] only notification from Allāh, and His messages." And whoever disobeys Allāh and His Messenger - then indeed, for him is the fire of Hell; they will abide therein forever.', '“(Aku diberi kuasa) hanya menyampaikan (wahyu) dari Allah dan perintah-perintahNya (yang ditugaskan kepadaku menyampaikannya); dan sesiapa yang menderhaka kepada Allah dan ingkarkan bawaan RasulNya, maka sesungguhnya disediakan baginya neraka Jahannam; kekalah mereka di dalamnya selama-lamanya.”.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 24, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', 'حَتَّىٰ إِذَا رَأَوْا مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', NULL, '[The disbelievers continue] until, when they see that which they are promised, then they will know who is weaker in helpers and less in number.', '(Golongan yang kufur ingkar itu tetap memandang engkau lemah dan kurang penyokong wahai Muhammad), sehingga apabila mereka melihat (azab) yang dijanjikan kepada mereka, maka (pada saat itu) mereka akan mengetahui siapakah orangnya yang lemah penolong-penolongnya, dan sedikit jumlah bilangannya.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 25, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'قُلْ إِنْ أَدْرِي أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُ رَبِّي أَمَدًا', NULL, 'Say, "I do not know if what you are promised is near or if my Lord will grant for it a [long] period."', '(Kalau ditanya bilakah azab itu? Maka) katakanlah: “Aku tidak mengetahui sama ada (azab) yang dijanjikan kepada kamu itu sudah dekat, atau Tuhanku menentukan bagi kedatangannya satu tempoh yang lanjut.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 26, 'عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', 'عَالِمُ الْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِ أَحَدًا', NULL, '[He is] Knower of the unseen, and He does not disclose His [knowledge of the] unseen to anyone', '“Tuhanlah sahaja yang mengetahui segala yang ghaib, maka Ia tidak memberitahu perkara ghaib yang diketahuiNya itu kepada sesiapapun, -', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 27, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 'إِلَّا مَنِ ارْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُ يَسْلُكُ مِن بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ رَصَدًا', NULL, 'Except whom He has approved of messengers, and indeed, He sends before him [i.e., each messenger] and behind him observers', '“Melainkan kepada mana-mana Rasul yang di redaiNya (untuk mengetahui sebahagian dari perkara ghaib yang berkaitan dengan tugasnya; apabila Tuhan hendak melakukan yang demikian) maka Ia mengadakan di hadapan dan di belakang Rasul itu malaikat-malaikat yang menjaga dan mengawasnya (sehingga perkara ghaib itu selamat sampai kepada yang berkenaan).', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(72, 28, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا رِسَالَاتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَيْءٍ عَدَدًا', NULL, 'That he [i.e., Muḥammad (ﷺ)] may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number.', '“(Tuhan mengadakan malaikat-malaikat itu) supaya Ia mengetahui bahawa sesungguhnya - (dengan jagaan mereka) - Rasul-rasul itu telah menyampaikan perutusan-perutusan Tuhan mereka, (dengan sempurna); pada hal Ia memang mengetahui dengan meliputi segala keadaan yang ada pada mereka, serta Ia menghitung tiap-tiap sesuatu: satu persatu”.', FALSE, NULL, NULL, 573, 29, 229, 507, FALSE, 0, NULL),
(73, 1, 'يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ', 'يا ايها المزمل', NULL, 'O you who wraps himself [in clothing],', 'Wahai orang yang berselimut!.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 2, NULL),
(73, 2, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا', 'قم الليل الا قليلا', NULL, 'Arise [to pray] the night, except for a little -', 'Bangunlah sembahyang Tahajjud pada waktu malam, selain dari sedikit masa (yang tak dapat tidak untuk berehat),', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 4, NULL),
(73, 3, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'نصفه او انقص منه قليلا', NULL, 'Half of it - or subtract from it a little', 'Iaitu separuh dari waktu malam, atau kurangkan sedikit dari separuh itu,', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 5, NULL),
(73, 4, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', 'او زد عليه ورتل القران ترتيلا', NULL, 'Or add to it, and recite the Qur’ān with measured recitation.', 'Ataupun lebihkan (sedikit) daripadanya; dan bacalah Al-Quran dengan “Tartil”.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 5, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 'انا سنلقي عليك قولا ثقيلا', NULL, 'Indeed, We will cast upon you a heavy word.', '(Sayugialah engkau dan pengikut-pengikutmu membiasakan diri masing-masing dengan ibadat yang berat kepada hawa nafsu, kerana) sesungguhnya Kami akan menurunkan kepadamu wahyu (Al-Quran yang mengandungi perintah-perintah) yang berat (kepada orang-orang yang tidak bersedia menyempurnakannya).', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 5, NULL),
(73, 6, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', 'ان ناشئة الليل هي اشد وطئا واقوم قيلا', NULL, 'Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words.', 'Sebenarnya sembahyang dan ibadat malam lebih kuat kesannya (kepada jiwa), dan lebih tetap betul bacaannya.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 8, NULL),
(73, 7, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', 'ان لك في النهار سبحا طويلا', NULL, 'Indeed, for you by day is prolonged occupation.', '(Kami galakkan engkau dan umatmu beribadat pada waktu malam), kerana sesungguhnya engkau pada siang hari mempunyai urusan-urusan yang panjang kira bicaranya;', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 8, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 'واذكر اسم ربك وتبتل اليه تبتيلا', NULL, 'And remember the name of your Lord and devote yourself to Him with [complete] devotion.', 'Dan sebutlah (dengan lidah dan hati) akan nama Tuhanmu (terus menerus siang dan malam), serta tumpukanlah (amal ibadatmu) kepadaNya dengan sebulat-bulat tumpuan.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 9, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا', 'رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا', NULL, '[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.', 'Dia lah Tuhan yang menguasai timur dan barat; tiada Tuhan melainkan Dia; maka jadikanlah Dia Penjaga yang menyempurnakan urusanmu.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 9, NULL),
(73, 10, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا', 'واصبر على ما يقولون واهجرهم هجرا جميلا', NULL, 'And be patient over what they say and avoid them with gracious avoidance.', 'Dan bersabarlah terhadap apa yang dikatakan oleh mereka (yang menentangmu), dan jauhkanlah dirimu dari mereka dengan cara yang baik.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 7, NULL),
(73, 11, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', 'وذرني والمكذبين اولي النعمة ومهلهم قليلا', NULL, 'And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.', 'Dan biarkanlah Aku sahaja membalas orang-orang yang mendustakan (bawaanmu) itu, orang-orang yang berada dalam kemewahan, dan berilah tempoh kepada mereka sedikit masa;', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 12, 'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا', 'ان لدينا انكالا وجحيما', NULL, 'Indeed, with Us [for them] are shackles and burning fire', 'Kerana sesungguhnya di sisi Kami disediakan (untuk mereka) belenggu-belenggu dan neraka yang menjulang-julang,', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 4, NULL),
(73, 13, 'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا', 'وطعاما ذا غصة وعذابا اليما', NULL, 'And food that chokes and a painful punishment -', 'Serta makanan yang menjadikan pemakannya tercekik, dan azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 5, NULL),
(73, 14, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا', 'يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا', NULL, 'On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down.', '(Azab itu tetap berlaku) pada hari bumi dan gunung-ganang bergoncang (serta hancur lebur), dan menjadilah gunung-ganang itu timbunan pasir yang mudah bersepah.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 8, NULL),
(73, 15, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا', 'انا ارسلنا اليكم رسولا شاهدا عليكم كما ارسلنا الى فرعون رسولا', NULL, 'Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger.', 'Sesungguhnya Kami telah mengutus kepada kamu (wahai umat Muhammad), seorang Rasul yang menjadi saksi terhadap kamu (tentang orang yang mematuhi atau menolak seruannya), sebagaimana Kami telah mengutus kepada Firaun seorang Rasul.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 11, NULL),
(73, 16, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَـٰهُ أَخْذًا وَبِيلًا', 'فعصى فرعون الرسول فاخذناه اخذا وبيلا', NULL, 'But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure.', 'Maka Firaun menderhaka kepada Rasul itu, lalu Kami menyeksakannya dengan azab seksa yang seberat-beratnya.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 17, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', 'فكيف تتقون ان كفرتم يوما يجعل الولدان شيبا', NULL, 'Then how can you fear, if you disbelieve, a Day that will make the children white-haired?', '(Sekiranya kamu tidak ditimpa azab di dunia), maka bagaimana kamu dapat menjaga dan menyelamatkan diri kamu - kalau kamu kufur ingkar - (dari azab) hari yang huru-haranya menyebabkan kanak-kanak menjadi tua beruban?', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 8, NULL),
(73, 18, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا', 'السماء منفطر به كان وعده مفعولا', NULL, 'The heaven will break apart therefrom; ever is His promise fulfilled.', 'Langit (yang demikian besarnya) akan pecah belah dengan sebab kedahsyatan hari itu. (Ingatlah), janji Allah adalah perkara yang tetap dilakukanNya.', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 6, NULL),
(73, 19, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا', NULL, 'Indeed, this is a reminder, so whoever wills may take to his Lord a way.', 'Sesungguhnya (keterangan-keterangan yang mengandungi amaran) ini menjadi peringatan oleh itu sesiapa yang mahukan kebaikan dirinya dapatlah ia mengambil jalan yang membawa kepada Tuhannya (dengan iman dan taat).', FALSE, NULL, NULL, 574, 29, 229, 508, FALSE, 9, NULL),
(73, 20, '۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ', 'ان ربك يعلم انك تقوم ادنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك والله يقدر الليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضى واخرون يضربون في الارض يبتغون من فضل الله واخرون يقاتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلاة واتوا الزكاة واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم', NULL, 'Indeed, your Lord knows, [O Muḥammad], that you stand [in prayer] almost two thirds of the night or half of it or a third of it, and [so do] a group of those with you. And Allāh determines [the extent of] the night and the day. He has known that you [Muslims] will not be able to do it and has turned to you in forgiveness, so recite what is easy [for you] of the Qur’ān. He has known that there will be among you those who are ill and others traveling throughout the land seeking [something] of the bounty of Allāh and others fighting for the cause of Allāh. So recite what is easy from it and establish prayer and give zakāh and loan Allāh a goodly loan. And whatever good you put forward for yourselves - you will find it with Allāh. It is better and greater in reward. And seek forgiveness of Allāh. Indeed, Allāh is Forgiving and Merciful.', 'Sesungguhnya Tuhanmu (wahai Muhammad) mengetahui bahawasanya engkau bangun (sembahyang Tahajjud) selama kurang dari dua pertiga malam, dan selama satu perduanya, dan selama satu pertiganya; dan (demikian juga dilakukan oleh) segolongan dari orang-orang yang bersama-samamu (kerana hendak menepati perintah yang terdahulu); padahal Allah jualah yang menentukan dengan tepat kadar masa malam dan siang. Ia mengetahui bahawa kamu tidak sekali-kali akan dapat mengira dengan tepat kadar masa itu, lalu Ia menarik balik perintahNya yang terdahulu (dengan memberi kemudahan) kepada kamu; oleh itu bacalah mana-mana yang mudah kamu dapat membacanya dari Al-Quran (dalam sembahyang). Ia juga mengetahui bahawa akan ada di antara kamu orang-orang yang sakit; dan yang lainnya orang-orang yang musafir di muka bumi untuk mencari rezeki dari limpah kurnia Allah; dan yang lainnya lagi orang-orang yang berjuang pada jalan Allah (membela ugamaNya). Maka bacalah mana-mana yang sudah kamu dapat membacanya dari Al-Quran; dan dirikanlah sembahyang serta berikanlah zakat; dan berilah pinjaman kepada Allah sebagai pinjaman yang baik (ikhlas). Dan (ingatlah), apa jua kebaikan yang kamu kerjakan sebagai bekalan untuk diri kamu, tentulah kamu akan mendapat balasannya pada sisi Allah, -sebagai balasan yang sebaik-baiknya dan yang amat besar pahalanya. Dan mintalah ampun kepada Allah; sesungguhnya Allah Maha Pengampun, lagi Maha Mengasihani.', FALSE, NULL, NULL, 575, 29, 230, 509, FALSE, 78, NULL),
(74, 1, 'يَـٰٓأَيُّهَا ٱلْمُدَّثِّرُ', 'يا ايها المدثر', NULL, 'O you who covers himself [with a garment],', 'Wahai orang yang berselimut!', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 2, 'قُمْ فَأَنذِرْ', 'قم فانذر', NULL, 'Arise and warn', 'Bangunlah serta berilah peringatan dan amaran (kepada umat manusia).', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 3, 'وَرَبَّكَ فَكَبِّرْ', 'وربك فكبر', NULL, 'And your Lord glorify', 'Dan Tuhanmu, maka ucaplah dan ingatlah kebesaranNya!', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 4, 'وَثِيَابَكَ فَطَهِّرْ', 'وثيابك فطهر', NULL, 'And your clothing purify', 'Dan pakaianmu, maka hendaklah engkau bersihkan.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 5, 'وَٱلرُّجْزَ فَٱهْجُرْ', 'والرجز فاهجر', NULL, 'And uncleanliness avoid', 'Dan segala kejahatan, maka hendaklah engkau jauhi.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(74, 6, 'وَلَا تَمْنُن تَسْتَكْثِرُ', 'ولا تمنن تستكثر', NULL, 'And do not confer favor to acquire more', 'Dan janganlah engkau memberi (sesuatu, dengan tujuan hendak) mendapat lebih banyak daripadanya.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 3, NULL),
(74, 7, 'وَلِرَبِّكَ فَٱصْبِرْ', 'ولربك فاصبر', NULL, 'But for your Lord be patient.', 'Dan bagi (menjalankan perintah) Tuhanmu, maka hendaklah engkau bersabar (terhadap tentangan musuh)!', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 8, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', 'فاذا نقر في الناقور', NULL, 'And when the trumpet is blown,', 'Kerana apabila telah ditiup sangkakala,', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 9, 'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ', 'فذلك يومئذ يوم عسير', NULL, 'That Day will be a difficult day', 'Maka saat yang demikian adalah saat (berlakunya) hari yang sukar -', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 10, 'عَلَى ٱلْكَـٰفِرِينَ غَيْرُ يَسِيرٍ', 'على الكافرين غير يسير', NULL, 'For the disbelievers - not easy.', 'Kepada orang-orang kafir, lagi tidak mudah (mengelak azabnya).', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 11, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا', 'ذرني ومن خلقت وحيدا', NULL, 'Leave Me with the one I created alone', '(Jangan engkau bimbang wahai Muhammad) biarkanlah Aku sahaja membalas orang (yang menentangmu) yang Aku ciptakan dia (dalam keadaan) seorang diri (tidak berharta dan anak pinak),', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 12, 'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا', 'وجعلت له مالا ممدودا', NULL, 'And to whom I granted extensive wealth', 'Dan Aku jadikan baginya harta kekayaan yang banyak,', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 13, 'وَبَنِينَ شُهُودًا', 'وبنين شهودا', NULL, 'And children present [with him]', 'Serta anak pinak (yang ramai), yang sentiasa ada di sisinya.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 14, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا', 'ومهدت له تمهيدا', NULL, 'And spread [everything] before him, easing [his life].', 'Dan Aku mudahkan baginya (mendapat kekayaan dan kekuasaan) dengan semudah-mudahnya.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 3, NULL),
(74, 15, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', 'ثم يطمع ان ازيد', NULL, 'Then he desires that I should add more.', 'Kemudian ia ingin sangat, supaya Aku tambahi lagi;', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 4, NULL),
(74, 16, 'كَلَّآ ۖ إِنَّهُۥ كَانَ لِـَٔايَـٰتِنَا عَنِيدًا', 'كلا انه كان لاياتنا عنيدا', NULL, 'No! Indeed, he has been toward Our verses obstinate.', 'Tidak sekali-kali (akan ditambahi)! Kerana sesungguhnya dia menentang dengan degilnya akan ayat-ayat Kami (Al-Quran, yang disampaikan oleh Rasul Kami).', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 5, NULL),
(74, 17, 'سَأُرْهِقُهُۥ صَعُودًا', 'سارهقه صعودا', NULL, 'I will cover him with arduous torment.', 'Aku akan menyeksanya (dengan azab) yang memuncak beratnya.', FALSE, NULL, NULL, 575, 29, 230, 510, FALSE, 2, NULL),
(74, 18, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', 'انه فكر وقدر', NULL, 'Indeed, he thought and deliberated.', 'Kerana sesungguhnya ia telah memikirkan dan mereka-reka berbagai tuduhan terhadap Al-Quran) -', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 3, NULL),
(74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'فقتل كيف قدر', NULL, 'So may he be destroyed [for] how he deliberated.', 'Maka binasalah dia hendaknya! Bagaimanakah dia berani mereka-reka (yang demikian)?', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 3, NULL),
(74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'ثم قتل كيف قدر', NULL, 'Then may he be destroyed [for] how he deliberated.', 'Sekali lagi: binasalah dia hendaknya! Bagaimana ia berani mereka-reka (tuduhan-tuduhan itu)?', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 4, NULL),
(74, 21, 'ثُمَّ نَظَرَ', 'ثُمَّ نَظَرَ', NULL, 'Then he considered [again];', 'Kemudian ia merenung dan memikirkan (berkali-kali: jalan-jalan mencaci Al-Quran, tetapi ia gagal);', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 22, 'ثُمَّ عَبَسَ وَبَسَرَ', 'ثُمَّ عَبَسَ وَبَسَرَ', NULL, 'Then he frowned and scowled;', 'Setelah itu ia memasamkan mukanya serta ia bertambah masam berkerut;', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 23, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', 'ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ', NULL, 'Then he turned back and was arrogant', 'Kemudian ia berpaling (dari kebenaran) dan berlaku sombong angkuh,', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 24, 'فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ', 'فَقَالَ إِنْ هَٰذَا إِلَّا سِحْرٌ يُؤْثَرُ', NULL, 'And said, "This is not but magic imitated [from others].', 'Serta ia berkata: “(Al-Quran) ini tidak lain hanyalah sihir yang dituntut serta dipelajari (dari ahli-ahlinya);', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 25, 'إِنْ هَٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', 'إِنْ هَٰذَا إِلَّا قَوْلُ الْبَشَرِ', NULL, 'This is not but the word of a human being."', '“Ini tidak lain hanyalah kata-kata (rekaan) manusia!”', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 26, 'سَأُصْلِيهِ سَقَرَ', 'سَأُصْلِيهِ سَقَرَ', NULL, 'I will drive him into Saqar.', '(Disebabkan kekufurannya itu) Aku akan masukkan dia ke dalam neraka Saqar.', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 27, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', 'وَمَا أَدْرَاكَ مَا سَقَرُ', NULL, 'And what can make you know what is Saqar?', 'Dan apa jalannya engkau dapat mengetahui kedahsyatan neraka Saqar itu?', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 28, 'لَا تُبْقِى وَلَا تَذَرُ', 'لَا تُبْقِي وَلَا تَذَرُ', NULL, 'It lets nothing remain and leaves nothing [unburned],', 'Ia membakar mangsanya dengan tidak meninggalkan sisa, dan tidak membiarkannya (binasa terus)', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 29, 'لَوَّاحَةٌ لِّلْبَشَرِ', 'لَوَّاحَةٌ لِّلْبَشَرِ', NULL, 'Altering [i.e., blackening] the skins.', 'Ia terus-menerus membakar kulit manusia!', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَ', 'عَلَيْهَا تِسْعَةَ عَشَرَ', NULL, 'Over it are nineteen [angels].', 'Pengawal dan penjaganya adalah sembilan belas (malaikat).', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 31, 'وَمَا جَعَلْنَآ أَصْحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَٰنًا وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْمُؤْمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', 'وَمَا جَعَلْنَا أَصْحَابَ النَّارِ إِلَّا مَلَائِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتَابَ وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا وَلَا يَرْتَابَ الَّذِينَ أُوتُوا الْكِتَابَ وَالْمُؤْمِنُونَ وَلِيَقُولَ الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ وَالْكَافِرُونَ مَاذَا أَرَادَ اللَّهُ بِهَٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَاءُ وَيَهْدِي مَن يَشَاءُ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِيَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', NULL, 'And We have not made the keepers of the Fire except angels. And We have not made their number except as a trial for those who disbelieve - that those who were given the Scripture will be convinced and those who have believed will increase in faith and those who were given the Scripture and the believers will not doubt and that those in whose hearts is disease [i.e., hypocrisy] and the disbelievers will say, "What does Allāh intend by this as an example?" Thus does Allāh send astray whom He wills and guide whom He wills. And none knows the soldiers of your Lord except Him. And it [i.e., mention of the Fire] is not but a reminder to humanity.', 'Dan (ketahuilah bahawa hikmat) Kami tidak menjadikan pengawal-pengawal neraka itu melainkan (dari kalangan) malaikat, (kerana merekalah sekuat-kuat dan sebenar-benar makhluk yang menjalankan perintah Kami); dan (hikmat) Kami tidak menerangkan bilangan mereka melainkan dengan satu bilangan yang menyebabkan kesesatan dan kesengsaraan orang-orang kafir itu, supaya orang-orang yang diberi Kitab (Yahudi dan Nasrani) boleh percaya dengan yakin (akan kebenaran Al-Quran), dan supaya orang-orang yang beriman bertambah imannya; dan juga supaya orang-orang yang diberi Kitab dan orang-orang yang beriman itu tidak ragu-ragu (tentang kebenaran keterangan itu); dan (sebaliknya) supaya orang-orang (munafik) yang ada penyakit (ragu-ragu) dalam hatinya dan orang-orang kafir berkata: “Apakah yang di maksudkan oleh Allah dengan menyebutkan bilangan ganjil ini?” Demikianlah Allah menyesatkan sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya), dan memberi hidayah petunjuk kepada sesiapa yang dikehendakiNya (menurut undang-undang peraturanNya); dan tiada yang mengetahui tentera Tuhanmu melainkan Dia lah sahaja. Dan (ingatlah, segala yang diterangkan berkenaan dengan) neraka itu tidak lain hanyalah menjadi peringatan bagi manusia.', FALSE, NULL, NULL, 576, 29, 230, 510, FALSE, 0, NULL),
(74, 32, 'كَلَّا وَٱلْقَمَرِ', 'كَلَّا وَالْقَمَرِ', NULL, 'No! By the moon', 'Sebenarnya! Demi bulan,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 33, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', 'وَاللَّيْلِ إِذْ أَدْبَرَ', NULL, 'And [by] the night when it departs', 'Dan malam apabila ia balik melenyapkan diri,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 34, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', 'وَالصُّبْحِ إِذَا أَسْفَرَ', NULL, 'And [by] the morning when it brightens,', 'Dan waktu subuh apabila ia terang-benderang,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 35, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', 'إِنَّهَا لَإِحْدَى الْكُبَرِ', NULL, 'Indeed, it [i.e., the Fire] is of the greatest [afflictions]', 'Sesungguhnya neraka Saqar itu adalah salah satu (malapetaka) yang amat besar,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 36, 'نَذِيرًا لِّلْبَشَرِ', 'نَذِيرًا لِّلْبَشَرِ', NULL, 'As a warning to humanity -', 'Yang menjadi amaran bagi umat manusia,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 37, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', 'لِمَن شَاءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', NULL, 'To whoever wills among you to proceed or stay behind.', '(Iaitu) bagi sesiapa di antara kamu yang mahu maju (dalam mengerjakan kebaikan) atau yang mahu mundur (daripada mengerjakannya).', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 38, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', 'كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ', NULL, 'Every soul, for what it has earned, will be retained', 'Tiap-tiap diri terikat, tidak terlepas daripada (balasan buruk bagi amal jahat) yang dikerjakannya,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 39, 'إِلَّآ أَصْحَٰبَ ٱلْيَمِينِ', 'إِلَّا أَصْحَابَ الْيَمِينِ', NULL, 'Except the companions of the right,.', 'Kecuali puak Kanan,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 40, 'فِى جَنَّٰتٍ يَتَسَآءَلُونَ', 'فِي جَنَّاتٍ يَتَسَاءَلُونَ', NULL, '[Who will be] in gardens, questioning each other', '(Mereka ditempatkan) di dalam Syurga (yang penuh nikmat), mereka bertanya-tanya,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 41, 'عَنِ ٱلْمُجْرِمِينَ', 'عَنِ الْمُجْرِمِينَ', NULL, 'About the criminals,', 'Tentang (tempat tinggal) orang-orang yang bersalah,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 42, 'مَا سَلَكَكُمْ فِى سَقَرَ', 'مَا سَلَكَكُمْ فِي سَقَرَ', NULL, '[And asking them], "What put you into Saqar?"', '(Setelah melihat orang-orang yang bersalah itu, mereka berkata): “Apakah yang menyebabkan kamu masuk ke dalam (neraka) Saqar?”', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 43, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', 'قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ', NULL, 'They will say, "We were not of those who prayed,', 'Orang-orang yang bersalah itu menjawab: “Kami tidak termasuk dalam kumpulan orang-orang yang mengerjakan sembahyang;', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 44, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', 'وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ', NULL, 'Nor did we used to feed the poor.', '“Dan kami tidak pernah memberi makan orang-orang miskin;', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 45, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', 'وَكُنَّا نَخُوضُ مَعَ الْخَائِضِينَ', NULL, 'And we used to enter into vain discourse with those who engaged [in it],', '“Dan kami dahulu selalu mengambil bahagian memperkatakan perkara yang salah, bersama-sama orang-orang yang memperkatakannya;', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 46, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', 'وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّينِ', NULL, 'And we used to deny the Day of Recompense', '“Dan kami sentiasa mendustakan hari pembalasan,', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 47, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', 'حَتَّىٰ أَتَانَا الْيَقِينُ', NULL, 'Until there came to us the certainty [i.e., death]."', '“Sehinggalah kami didatangi oleh perkara yang tetap diyakini”.', FALSE, NULL, NULL, 576, 29, 230, 511, FALSE, 0, NULL),
(74, 48, 'فَمَا تَنفَعُهُمْ شَفَٰعَةُ ٱلشَّٰفِعِينَ', 'فَمَا تَنفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ', NULL, 'So there will not benefit them the intercession of [any] intercessors.', 'Maka tidak akan berguna kepada mereka sebarang syafaat pertolongan (kalaulah ditakdirkan ada) sesiapa yang boleh memberikan syafaat itu.', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 49, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', 'فَمَا لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِينَ', NULL, 'Then what is [the matter] with them that they are, from the reminder, turning away', '(Kalau demikianlah halnya orang-orang yang bersalah), maka mengapa mereka berpaling lari dari peringatan (Al-Quran)?', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 50, 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', NULL, 'As if they were alarmed donkeys', 'Seolah-olah mereka sekawan keldai liar yang lari,', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 51, 'فَرَّتْ مِن قَسْوَرَةٍۭ', 'فَرَّتْ مِن قَسْوَرَةٍ', NULL, 'Fleeing from a lion?', 'Melarikan diri (ketakutan) dari singa!', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 52, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', 'بَلْ يُرِيدُ كُلُّ امْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', NULL, 'Rather, every person among them desires that he would be given scriptures spread about.', '(Mereka tidak merasa cukup dengan peringatan itu) bahkan tiap-tiap seorang di antaranya mahu supaya diberi kepadanya lembaran surat yang terbuka (yang diturunkan dari langit untuk dibaca oleh mereka sendiri).', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 53, 'كَلَّا بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ', 'كَلَّا بَل لَّا يَخَافُونَ الْآخِرَةَ', NULL, 'No! But they do not fear the Hereafter.', 'Sebenarnya! (Bukan kerana kemahuan mereka tidak berhasil), bahkan mereka (tidak percaya dan) tidak takut akan hari akhirat.', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 54, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ', 'كَلَّا إِنَّهُ تَذْكِرَةٌ', NULL, 'No! Indeed, it [i.e., the Qur’ān] is a reminder', 'Ketahuilah! Sesungguhnya Al-Quran itu adalah satu peringatan (yang sangat besar pengajarannya);', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 55, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فَمَن شَاءَ ذَكَرَهُ', NULL, 'Then whoever wills will remember it.', 'Oleh itu sesiapa yang mahu (beringat) dapatlah ia mengambil peringatan daripadanya.', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(74, 56, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', 'وَمَا يَذْكُرُونَ إِلَّا أَن يَشَاءَ اللَّهُ هُوَ أَهْلُ التَّقْوَىٰ وَأَهْلُ الْمَغْفِرَةِ', NULL, 'And they will not remember except that Allāh wills. He is worthy of fear and adequate for [granting] forgiveness.', 'Dan (dalam pada itu) tiadalah mereka dapat beringat melainkan jika dikehendaki Allah; Dia lah Tuhan yang berhak dipatuhi perintahNya, dan Dia lah jua yang berhak memberi keampunan (kepada orang-orang yang beriman dan taat).', FALSE, NULL, NULL, 577, 29, 230, 511, FALSE, 0, NULL),
(75, 1, 'لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَـٰمَةِ', 'لا اقسم بيوم القيامة', NULL, 'I swear by the Day of Resurrection', 'Aku bersumpah dengan Hari Kiamat;', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 2, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', 'ولا اقسم بالنفس اللوامة', NULL, 'And I swear by the reproaching soul [to the certainty of resurrection].', 'Dan Aku bersumpah dengan “Nafsul Lawwaamah” (Bahawa kamu akan dibangkitkan sesudah mati)!', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 3, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'ايحسب الانسان الن نجمع عظامه', NULL, 'Does man think that We will not assemble his bones?', 'Patutkah manusia (yang kafir) menyangka bahawa Kami tidak akan dapat mengumpulkan tulang-tulangnya (dan menghidupkannya semula)?', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 5, NULL),
(75, 4, 'بَلَىٰ قَـٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', 'بلى قادرين على ان نسوي بنانه', NULL, 'Yes. [We are] Able [even] to proportion his fingertips.', 'Bukan sebagaimana yang disangka itu, bahkan Kami berkuasa menyusun (dengan sempurnanya segala tulang) jarinya, (tulang yang lebih halus dari yang lain).', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 6, NULL),
(75, 5, 'بَلْ يُرِيدُ ٱلْإِنسَـٰنُ لِيَفْجُرَ أَمَامَهُۥ', 'بل يريد الانسان ليفجر امامه', NULL, 'But man desires to continue in sin.', '(Kebenaran itu bukan tidak ada buktinya), bahkan manusia (yang ingkar) sentiasa suka hendak meneruskan perbuatan kufur dan maksiat (di sepanjang hayatnya, sehingga ia tidak mengakui adanya hari kiamat).', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 5, NULL),
(75, 6, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَـٰمَةِ', 'يسال ايان يوم القيامة', NULL, 'He asks, "When is the Day of Resurrection?"', 'Dia bertanya (secara mengejek): “Bilakah datangnya hari kiamat itu?”', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 7, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', 'فاذا برق البصر', NULL, 'So when vision is dazzled', 'Maka (jawabnya: hari kiamat akan datang) apabila pemandangan menjadi terpendar-pendar (kerana gerun takut),', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 3, NULL),
(75, 8, 'وَخَسَفَ ٱلْقَمَرُ', 'وخسف القمر', NULL, 'And the moon darkens', 'Dan bulan hilang cahayanya,', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 2, NULL),
(75, 9, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', 'وجمع الشمس والقمر', NULL, 'And the sun and the moon are joined,', 'Dan matahari serta bulan dihimpunkan bersama,', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 3, NULL),
(75, 10, 'يَقُولُ ٱلْإِنسَـٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', 'يقول الانسان يومئذ اين المفر', NULL, 'Man will say on that Day, "Where is the [place of] escape?"', '(Maka) pada hari itu, berkatalah manusia (yang ingkarkan hari kiamat): “Ke manakah hendak melarikan diri?”', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 5, NULL),
(75, 11, 'كَلَّا لَا وَزَرَ', 'كلا لا وزر', NULL, 'No! There is no refuge.', 'Tak usahlah bertanya demikian! Tidak ada lagi tempat perlindungan!', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 3, NULL),
(75, 12, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', 'الى ربك يومئذ المستقر', NULL, 'To your Lord, that Day, is the [place of] permanence.', 'Pada hari itu, kepada Tuhanmu lah sahaja terserahnya ketetapan segala perkara.', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 13, 'يُنَبَّؤُا۟ ٱلْإِنسَـٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', 'ينبا الانسان يومئذ بما قدم واخر', NULL, 'Man will be informed that Day of what he sent ahead and kept back.', 'Pada hari itu, manusia diberitahu akan apa yang ia telah lakukan, dan apa yang ia telah tinggalkan.', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 6, NULL),
(75, 14, 'بَلِ ٱلْإِنسَـٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ', 'بل الانسان على نفسه بصيرة', NULL, 'Rather, man, against himself, will be a witness,', 'Bahkan manusia itu, (anggotanya) menjadi saksi terhadap dirinya sendiri,', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 5, NULL),
(75, 15, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', 'ولو القى معاذيره', NULL, 'Even if he presents his excuses.', 'Walaupun ia memberikan alasan-alasannya (untuk membela diri).', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 3, NULL),
(75, 16, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', 'لا تحرك به لسانك لتعجل به', NULL, 'Move not your tongue with it, [O Muḥammad], to hasten with it [i.e., recitation of the Qur’ān].', 'Janganlah engkau (wahai Muhammad) - Kerana hendakkan cepat menghafaz Quran yang diturunkan kepadamu - menggerakkan lidahmu membacanya (sebelum selesai dibacakan kepadamu).', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 6, NULL),
(75, 17, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', 'ان علينا جمعه وقرانه', NULL, 'Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.', 'Sesungguhnya Kamilah yang berkuasa mengumpulkan Al-Quran itu (dalam dadamu), dan menetapkan bacaannya (pada lidahmu);', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 18, 'فَإِذَا قَرَأْنَـٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', 'فاذا قراناه فاتبع قرانه', NULL, 'So when We have recited it [through Gabriel], then follow its recitation.', 'Oleh itu, apabila Kami telah menyempurnakan bacaannya (kepadamu, dengan perantaraan Jibril), maka bacalah menurut bacaannya itu;', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 19, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', 'ثم ان علينا بيانه', NULL, 'Then upon Us is its clarification [to you].', 'Kemudian, sesungguhnya kepada Kamilah terserah urusan menjelaskan kandungannya (yang memerlukan penjelasan).', FALSE, NULL, NULL, 577, 29, 231, 512, FALSE, 4, NULL),
(75, 20, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', 'كلا بل تحبون العاجلة', NULL, 'No! But you [i.e., mankind] love the immediate', 'Sedarlah wahai orang-orang yang lalai. (Sebenarnya kamu tidak ingatkan kesudahan kamu) bahkan kamu sentiasa mencintai (Kesenangan dan kemewahan dunia) yang cepat habisnya.', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 4, NULL),
(75, 21, 'وَتَذَرُونَ ٱلْـَٔاخِرَةَ', 'وَتَذَرُونَ الْآخِرَةَ', NULL, 'And leave [i.e., neglect] the Hereafter.', 'Dan kamu tidak menghiraukan (bekalan untuk) hari akhirat (yang kekal abadi kehidupannya).', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 22, 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', NULL, '[Some] faces, that Day, will be radiant,', 'Pada hari akhirat itu, muka (orang-orang yang beriman) berseri-seri;', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 23, 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', NULL, 'Looking at their Lord.', 'Melihat kepada Tuhannya.', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 24, 'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ', 'وَوُجُوهٌ يَوْمَئِذٍ بَاسِرَةٌ', NULL, 'And [some] faces, that Day, will be contorted,', 'Dan pada hari itu, muka (orang-orang kafir) muram hodoh,', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 25, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', NULL, 'Expecting that there will be done to them [something] backbreaking.', 'Sambil percaya dengan yakin bahawa mereka akan ditimpa malapetaka (azab seksa) yang membinasakan.', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 26, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', 'كَلَّا إِذَا بَلَغَتِ التَّرَاقِيَ', NULL, 'No! When it [i.e., the soul] has reached the collar bones', 'Sedarlah (janganlah mengutamakan dunia dan melupakan akhirat. Ingatlah akan hal orang yang hendak mati) apabila rohnya sampai ke pangkal kerongkong,', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 27, 'وَقِيلَ مَنْ رَاقٍ', 'وَقِيلَ مَنْ رَاقٍ', NULL, 'And it is said, "Who will cure [him]?"', 'Dan (orang-orang yang hadir di sisinya heboh) berkata: “Siapakah yang dapat menawar jampi (dan mengubatnya)?”', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 28, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', 'وَظَنَّ أَنَّهُ الْفِرَاقُ', NULL, 'And he [i.e., the dying one] is certain that it is the [time of] separation', 'Dan ia sendiri yakin, bahawa sesungguhnya saat itu saat perpisahan;', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 29, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', 'وَالْتَفَّتِ السَّاقُ بِالسَّاقِ', NULL, 'And the leg is wound about the leg,', 'Serta kedahsyatan bertindih-tindih;', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 30, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ الْمَسَاقُ', NULL, 'To your Lord, that Day, will be the procession.', '(Maka) kepada Tuhanmulah - pada waktu itu - engkau dibawa (untuk menerima balasan).', FALSE, NULL, NULL, 578, 29, 231, 512, FALSE, 0, NULL),
(75, 31, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', NULL, 'And he [i.e., the disbeliever] had not believed, nor had he prayed.', '(Oleh sebab orang yang kufur ingkar tidak percayakan hari akhirat) maka ia tidak mengakui kebenaran (yang diwajibkan meyakininya) dan ia tidak mengerjakan sembahyang (yang difardhukan mengerjakannya)!', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 32, 'وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ', 'وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ', NULL, 'But [instead], he denied and turned away.', 'Akan tetapi ia mendustakan, dan berpaling ingkar!', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 33, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', 'ثُمَّ ذَهَبَ إِلَىٰ أَهْلِهِ يَتَمَطَّىٰ', NULL, 'And then he went to his people, swaggering [in pride].', 'Kemudian ia pergi kepada keluarganya dengan berlagak sombong megah.', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 34, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', NULL, 'Woe to you, and woe!', '(Wahai orang yang kufur ingkar!) sudahlah dekat kepadamu kebinasaanmu, sudahlah dekat!', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 35, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰ', NULL, 'Then woe to you, and woe!', 'Kemudian api nerakalah lebih layak bagimu, lebih layak.', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 36, 'أَيَحْسَبُ ٱلْإِنسَٰنُ أَن يُتْرَكَ سُدًى', 'أَيَحْسَبُ الْإِنسَانُ أَن يُتْرَكَ سُدًى', NULL, 'Does man think that he will be left neglected?', 'Patutkah manusia menyangka, bahawa ia akan ditinggalkan terbiar (dengan tidak diberikan tanggungjawab dan tidak dihidupkan menerima balasan)?', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 37, 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ', 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِيٍّ يُمْنَىٰ', NULL, 'Had he not been a sperm from semen emitted?', 'Bukankah ia berasal dari air mani yang dipancarkan (ke dalam rahim)?', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 38, 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', NULL, 'Then he was a clinging clot, and [Allāh] created [his form] and proportioned [him]', 'Kemudian air mani itu menjadi sebuku darah beku, sesudah itu Tuhan menciptakannya, dan menyempurnakan kejadiannya (sebagai manusia)?', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 39, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'فَجَعَلَ مِنْهُ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنثَىٰ', NULL, 'And made of him two mates, the male and the female.', 'Lalu Tuhan menjadikan daripadanya dua jenis - lelaki dan perempuan.', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(75, 40, 'أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ', 'أَلَيْسَ ذَٰلِكَ بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ', NULL, 'Is not that [Creator] Able to give life to the dead?', 'Adakah (Tuhan yang menjadikan semuanya) itu - tidak berkuasa menghidupkan orang-orang yang mati? (Tentulah berkuasa)!', FALSE, NULL, NULL, 578, 29, 231, 513, FALSE, 0, NULL),
(76, 1, 'هَلْ أَتَىٰ عَلَى ٱلْإِنسَـٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا', 'هل اتى على الانسان حين من الدهر لم يكن شيئا مذكورا', NULL, 'Has there [not] come upon man a period of time when he was not a thing [even] mentioned?', 'Bukankah telah berlalu kepada manusia satu ketika dari masa (yang beredar), sedang ia (masih belum wujud lagi, dan) tidak menjadi sesuatu benda yang disebut-sebut, (maka mengapa kaum musyrik itu mengingkari hari akhirat)?', FALSE, NULL, NULL, 578, 29, 231, 514, FALSE, 11, NULL),
(76, 2, 'إِنَّا خَلَقْنَا ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـٰهُ سَمِيعًۢا بَصِيرًا', 'انا خلقنا الانسان من نطفة امشاج نبتليه فجعلناه سميعا بصيرا', NULL, 'Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing.', 'Sesungguhnya Kami telah aturkan cara mencipta manusia bermulanya dari air mani yang bercampur (dari pati benih lelaki dan perempuan), serta Kami tetap mengujinya (dengan kewajipan-kewajipan); oleh itu maka Kami jadikan dia berkeadaan mendengar dan melihat.', FALSE, NULL, NULL, 578, 29, 231, 514, FALSE, 10, NULL),
(76, 3, 'إِنَّا هَدَيْنَـٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', 'انا هديناه السبيل اما شاكرا واما كفورا', NULL, 'Indeed, We guided him to the way, be he grateful or be he ungrateful.', 'Kerana keadaan itu tidak mencukupi, maka) sesungguhnya Kami telah menunjukkan kepadanya (melalui akal dan Rasul) akan jalan-jalan (yang benar dan yang salah; maka terserahlah kepadanya) sama ada ia bersyukur (dengan beriman dan taat), ataupun ia berlaku kufur (dengan mengingkari kebenaran atau menderhaka).', FALSE, NULL, NULL, 578, 29, 231, 514, FALSE, 7, NULL),
(76, 4, 'إِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَلَـٰسِلَا۟ وَأَغْلَـٰلًا وَسَعِيرًا', 'انا اعتدنا للكافرين سلاسل واغلالا وسعيرا', NULL, 'Indeed, We have prepared for the disbelievers chains and shackles and a blaze.', '(Dalam pada itu), sesungguhnya Kami telah menyediakan bagi sesiapa yang berlaku kufur (atau menderhaka): beberapa rantai dan belenggu serta neraka yang menjulang-julang.', FALSE, NULL, NULL, 578, 29, 231, 514, FALSE, 6, NULL),
(76, 5, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'ان الابرار يشربون من كاس كان مزاجها كافورا', NULL, 'Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kāfūr,', 'Sesungguhnya orang-orang yang berbakti (dengan taat dan kebajikan), akan meminum dari piala: sejenis minuman yang bercampur dengan “Kafur”, -', FALSE, NULL, NULL, 578, 29, 231, 514, FALSE, 8, NULL),
(76, 6, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'عينا يشرب بها عباد الله يفجرونها تفجيرا', NULL, 'A spring of which the [righteous] servants of Allāh will drink; they will make it gush forth in force [and abundance].', 'Iaitu sebuah mata air (di Syurga), yang diminum daripadanya oleh hamba-hamba Allah (yang taat); mereka boleh mengalirkannya (di tempat-tempat tinggal mereka) dengan aliran yang semudah-mudahnya dan menurut kemahuannya.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 7, NULL),
(76, 7, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 'يوفون بالنذر ويخافون يوما كان شره مستطيرا', NULL, 'They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread.', '(Mereka dikurniakan kesenangan itu kerana) mereka menyempurnakan nazarnya (apatah lagi yang diwajibkan Tuhan kepadanya), serta mereka takutkan hari (akhirat) yang azab seksanya merebak di sana sini.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 7, NULL),
(76, 8, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', 'ويطعمون الطعام على حبه مسكينا ويتيما واسيرا', NULL, 'And they give food in spite of love for it to the needy, the orphan, and the captive,', 'Mereka juga memberi makan benda-benda makanan yang dihajati dan disukainya, kepada orang miskin dan anak yatim serta orang tawanan,', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 7, NULL),
(76, 9, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', 'انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا', NULL, '[Saying], "We feed you only for the face [i.e., approval] of Allāh. We wish not from you reward or gratitude.', '(Sambil berkata dengan lidah atau dengan hati): “Sesungguhnya kami memberi makan kepada kamu kerana Allah semata-mata; kami tidak berkehendakkan sebarang balasan dari kamu atau ucapan terima kasih,', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 10, NULL),
(76, 10, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'انا نخاف من ربنا يوما عبوسا قمطريرا', NULL, 'Indeed, We fear from our Lord a Day austere and distressful."', '“Kami sebenarnya takutkan Tuhan kami, takut Ia kenakan kami azab hari yang padanya muka orang-orang yang bersalah: masam berkerut-kerut”.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 7, NULL),
(76, 11, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', 'فوقاهم الله شر ذلك اليوم ولقاهم نضرة وسرورا', NULL, 'So Allāh will protect them from the evil of that Day and give them radiance and happiness', 'Dengan sebab (mereka menjaga diri dari kesalahan), maka Allah selamatkan mereka dari kesengsaraan hari yang demikian keadaannya, serta memberikan kepada mereka keindahan yang berseri-seri (di muka), dan perasaan ria gembira (di hati).', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 8, NULL),
(76, 12, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', 'وجزاهم بما صبروا جنة وحريرا', NULL, 'And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].', 'Dan kerana kesabaran mereka (mengerjakan suruhan Allah dan meninggalkan laranganNya), mereka dibalas oleh Allah dengan Syurga dan (persalinan dari) sutera.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 5, NULL),
(76, 13, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', 'متكئين فيها على الارائك لا يرون فيها شمسا ولا زمهريرا', NULL, '[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold.', 'Mereka berehat di dalam Syurga dengan berbaring di atas pelamin-pelamin (yang berhias), mereka tidak nampak di situ adanya matahari (usahkan hawa panasnya), dan tidak juga merasai suasana yang terlampau sejuk;', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 10, NULL),
(76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَـٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', 'ودانية عليهم ظلالها وذللت قطوفها تذليلا', NULL, 'And near above them are its shades, and its [fruit] to be picked will be lowered in compliance.', 'Sedang naungan pohon-pohon Syurga itu dekat kepada mereka, dan buah-buahannya pula dimudahkan (untuk mereka memetiknya) dengan semudah-mudahnya.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 6, NULL),
(76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 'ويطاف عليهم بانية من فضة واكواب كانت قواريرا', NULL, 'And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],', 'Dan (selain itu) diedarkan kepada mereka (oleh pelayan-pelayannya): bijana dari perak dan piala-piala minuman yang keadaannya laksana kaca (nampak jelas isinya) -', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 8, NULL),
(76, 16, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'قوارير من فضة قدروها تقديرا', NULL, 'Clear glasses [made] from silver of which they have determined the measure.', '(Keadaannya laksana) kaca, (sedang ia) dari perak; pelayan-pelayan itu menentukan kadar isinya sekadar yang cukup betul dengan kehendak penggunanya.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 5, NULL),
(76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', 'ويسقون فيها كاسا كان مزاجها زنجبيلا', NULL, 'And they will be given to drink a cup [of wine] whose mixture is of ginger', 'Dan mereka dalam Syurga itu, diberi minum sejenis minuman yang campurannya dari “Zanjabil”,', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 6, NULL),
(76, 18, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', 'عينا فيها تسمى سلسبيلا', NULL, '[From] a fountain within it [i.e., Paradise] named Salsabeel.', 'Iaitu sebuah matair dalam Syurga, yang disebutkan sifatnya sebagai “Salsabil”.', FALSE, NULL, NULL, 579, 29, 231, 514, FALSE, 4, NULL),
(76, 19, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', 'ويطوف عليهم ولدان مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا', NULL, 'There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls.', 'Dan mereka dilayani oleh anak-anak muda lelaki yang tetap kekal (dalam keadaan mudanya), yang sentiasa beredar di sekitar mereka; apabila engkau melihat anak-anak muda itu, nescaya engkau menyangkanya mutiara yang bertaburan.', FALSE, NULL, NULL, 579, 29, 232, 514, FALSE, 9, NULL),
(76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', 'واذا رايت ثم رايت نعيما وملكا كبيرا', NULL, 'And when you look there [in Paradise], you will see pleasure and great dominion.', 'Dan apabila engkau melihat di sana (dalam Syurga itu), engkau melihat nikmat yang melimpah-limpah dan kerajaan yang besar (yang tidak ada bandingannya).', FALSE, NULL, NULL, 579, 29, 232, 514, FALSE, 7, NULL),
(76, 21, 'عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', 'عَالِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوا أَسَاوِرَ مِن فِضَّةٍ وَسَقَاهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', NULL, 'Upon them [i.e., the inhabitants] will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink.', 'Mereka di dalam Syurga memakai pakaian hijau yang diperbuat dari sutera halus dan sutera tebal (yang bertekat), serta mereka dihiasi dengan gelang-gelang tangan dari perak; dan mereka diberi minum oleh Tuhan mereka dengan sejenis minuman (yang lain) yang bersih suci.', FALSE, NULL, NULL, 579, 29, 232, 514, FALSE, 0, NULL),
(76, 22, 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَاءً وَكَانَ سَعْيُكُم مَّشْكُورًا', NULL, '[And it will be said], "Indeed, this is for you a reward, and your effort has been appreciated."', '(Serta dikatakan kepada mereka): “Sesungguhnya (segala pemberian) ini adalah untuk kamu sebagai balasan, dan adalah usaha amal kamu (di dunia dahulu) diterima dan dihargai (oleh Allah)”.', FALSE, NULL, NULL, 579, 29, 232, 514, FALSE, 0, NULL),
(76, 23, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا', 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ الْقُرْآنَ تَنزِيلًا', NULL, 'Indeed, it is We who have sent down to you, [O Muḥammad], the Qur’ān progressively.', 'Sesungguhnya Kami telah menurunkan Al-Quran kepadamu (wahai Muhammad), dengan beransur-ansur.', FALSE, NULL, NULL, 579, 29, 232, 515, FALSE, 0, NULL),
(76, 24, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا', 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ آثِمًا أَوْ كَفُورًا', NULL, 'So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever].', 'Oleh itu hendaklah engkau bersabar menerima hukum Tuhanmu (memberi tempoh kepada golongan yang menentangmu), dan janganlah engkau menurut kehendak orang yang berdosa di antara mereka, atau orang yang kufur ingkar.', FALSE, NULL, NULL, 579, 29, 232, 515, FALSE, 0, NULL),
(76, 25, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', 'وَاذْكُرِ اسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', NULL, 'And mention the name of your Lord [in prayer] morning and evening', 'Dan sebutlah dengan lidah atau dengan hati akan nama Tuhanmu (di dalam dan di luar sembahyang), pada waktu pagi dan petang;', FALSE, NULL, NULL, 579, 29, 232, 515, FALSE, 0, NULL),
(76, 26, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا', 'وَمِنَ اللَّيْلِ فَاسْجُدْ لَهُ وَسَبِّحْهُ لَيْلًا طَوِيلًا', NULL, 'And during the night prostrate to Him and exalt [i.e., praise] Him a long [part of the] night.', 'Dan (dengan apa keadaan pun maka) pada sebahagian dari waktu malam sujudlah kepada Tuhan (dengan mengerjakan sembahyang), dan (seboleh-bolehnya) bertasbihlah memujiNya (dengan mengerjakan sembahyang Tahajjud), pada sebahagian yang panjang dari waktu malam.', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(76, 27, 'إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا', 'إِنَّ هَٰؤُلَاءِ يُحِبُّونَ الْعَاجِلَةَ وَيَذَرُونَ وَرَاءَهُمْ يَوْمًا ثَقِيلًا', NULL, 'Indeed, these [disbelievers] love the immediate and leave behind them a grave Day.', 'Sesungguhnya orang-orang (yang menentangmu) itu sentiasa mencintai (kesenangan dan kemewahan dunia) yang cepat habisnya, serta mereka membelakangkan (tidak menghiraukan bekalan) untuk hari akhirat yang amat berat (penderitaannya kepada orang-orang yang tidak bertaqwa).', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(76, 28, 'نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلًا', 'نَّحْنُ خَلَقْنَاهُمْ وَشَدَدْنَا أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَا أَمْثَالَهُمْ تَبْدِيلًا', NULL, 'We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration.', 'Kamilah yang menciptakan mereka serta menguatkan tulang sendi dan urat saraf mereka; (Kami berkuasa membinasakan mereka) dan apabila Kami kehendaki, Kami gantikan (mereka dengan) orang-orang yang serupa dengan mereka, dengan penggantian yang sebaik-baiknya.', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(76, 29, 'إِنَّ هَٰذِهِۦ تَذْكِرَةٌ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'إِنَّ هَٰذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَىٰ رَبِّهِ سَبِيلًا', NULL, 'Indeed, this is a reminder, so he who wills may take to his Lord a way.', 'Sesungguhnya (segala keterangan yang disebutkan) ini, menjadi peringatan; maka sesiapa yang mahukan (kebaikan dirinya) bolehlah ia mengambil jalan yang menyampaikan kepada keredaan Allah (dengan iman dan taat).', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(76, 30, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'وَمَا تَشَاءُونَ إِلَّا أَن يَشَاءَ اللَّهُ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا', NULL, 'And you do not will except that Allāh wills. Indeed, Allāh is ever Knowing and Wise.', 'Dan tiadalah kamu berkemahuan (melakukan sesuatu perkara) melainkan dengan cara yang dikehendaki Allah; sesungguhnya Allah adalah Maha Mengetahui, lagi Maha Bijaksana (mengaturkan sebarang perkara yang dikehendakiNya).', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(76, 31, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', 'يُدْخِلُ مَن يَشَاءُ فِي رَحْمَتِهِ وَالظَّالِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًا', NULL, 'He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment.', 'Ia memasukkan sesiapa yang dikehendakiNya (menurut aturan yang ditetapkan) ke dalam rahmatNya (dengan ditempatkannya di dalam Syurga); dan orang-orang yang zalim, Ia menyediakan untuk mereka azab seksa yang tidak terperi sakitnya.', FALSE, NULL, NULL, 580, 29, 232, 515, FALSE, 0, NULL),
(77, 1, 'وَٱلْمُرْسَلَـٰتِ عُرْفًا', 'والمرسلات عرفا', NULL, 'By those [winds] sent forth in gusts', 'Demi (makhluk-makhluk) yang dihantarkan berturut-turut (menjalankan tugasnya),', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 2, 'فَٱلْعَـٰصِفَـٰتِ عَصْفًا', 'فالعاصفات عصفا', NULL, 'And the winds that blow violently', 'Juga yang merempuh mara dengan sekencang-kencangnya,', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 3, 'وَٱلنَّـٰشِرَٰتِ نَشْرًا', 'والناشرات نشرا', NULL, 'And [by] the winds that spread [clouds]', 'Dan demi (makhluk-makhluk) yang menyebarkan (pengajaran dan peringatan) dengan sebaran yang sesungguh-sungguhnya,', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 4, 'فَٱلْفَـٰرِقَـٰتِ فَرْقًا', 'فالفارقات فرقا', NULL, 'And those [angels] who bring criterion', 'Serta yang memisahkan (antara yang benar dengan yang salah) dengan pemisahan yang sejelas-jelasnya,', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 5, 'فَٱلْمُلْقِيَـٰتِ ذِكْرًا', 'فالملقيات ذكرا', NULL, 'And those [angels] who deliver a message', 'Lalu menyampaikan pengajaran dan peringatan (kepada manusia),', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 6, 'عُذْرًا أَوْ نُذْرًا', 'عذرا او نذرا', NULL, 'As justification or warning,', 'Untuk menghapuskan kesalahan orang-orang yang bertaubat serta memperbaiki keadaan dirinya, dan untuk menakutkan orang-orang yang ingkar - derhaka; -', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 7, 'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ', 'انما توعدون لواقع', NULL, 'Indeed, what you are promised is to occur.', '(Sumpah demi sumpah) sesungguhnya segala yang dijanjikan kepada kamu tetap berlaku.', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 8, 'فَإِذَا ٱلنُّجُومُ طُمِسَتْ', 'فاذا النجوم طمست', NULL, 'So when the stars are obliterated', 'Oleh itu, apabila bintang-bintang (binasa dan) hilang lenyap;', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 9, 'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ', 'واذا السماء فرجت', NULL, 'And when the heaven is opened', 'Dan apabila langit terbelah;', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 10, 'وَإِذَا ٱلْجِبَالُ نُسِفَتْ', 'واذا الجبال نسفت', NULL, 'And when the mountains are blown away', 'Dan apabila gunung-ganang hancur lebur berterbangan;', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 11, 'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ', 'واذا الرسل اقتت', NULL, 'And when the messengers'' time has come...', 'Dan apabila Rasul-rasul ditentukan waktunya untuk dipanggil menjadi saksi terhadap umatnya, (maka sudah tentu manusia akan menerima balasan masing-masing).', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 12, 'لِأَىِّ يَوْمٍ أُجِّلَتْ', 'لاي يوم اجلت', NULL, 'For what Day was it postponed?', '(Jika ditanya): ke hari yang manakah (perkara-perkara yang besar) itu ditangguhkan?', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 13, 'لِيَوْمِ ٱلْفَصْلِ', 'ليوم الفصل', NULL, 'For the Day of Judgement.', '(Jawabnya): Ke hari pemutusan hukum.', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 2, NULL),
(77, 14, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ', 'وما ادراك ما يوم الفصل', NULL, 'And what can make you know what is the Day of Judgement?', 'Dan apa jalannya engkau dapat mengetahui kedahsyatan hari pemutusan hukum itu?', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 5, NULL),
(77, 15, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (apa yang dijanjikan oleh Rasulnya)!', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 16, 'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ', 'الم نهلك الاولين', NULL, 'Did We not destroy the former peoples?', 'Bukankah Kami telah binasakan orang-orang dahulu (yang ingkar derhaka, seperti kaum Nabi Nuh, Aad dan Thamud)?', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 17, 'ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ', 'ثم نتبعهم الاخرين', NULL, 'Then We will follow them with the later ones.', 'Kemudian kami akan iringi mereka dengan (membinasakan orang-orang yang ingkar derhaka, dari) kaum-kaum yang datang kemudian.', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 18, 'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'كذلك نفعل بالمجرمين', NULL, 'Thus do We deal with the criminals.', 'Demikian cara kami lakukan terhadap sesiapa yang berdosa.', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 19, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (apa yang Kami janjikan)!', FALSE, NULL, NULL, 580, 29, 232, 516, FALSE, 3, NULL),
(77, 20, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ', 'الم نخلقكم من ماء مهين', NULL, 'Did We not create you from a liquid disdained?', 'Bukankah Kami telah menciptakan kamu dari air (benih) yang sedikit dipandang orang?', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 5, NULL),
(77, 21, 'فَجَعَلْنَٰهُ فِى قَرَارٍ مَّكِينٍ', 'فَجَعَلْنَاهُ فِي قَرَارٍ مَّكِينٍ', NULL, 'And We placed it in a firm lodging [i.e., the womb]', 'Lalu Kami jadikan air (benih) itu pada tempat penetapan yang kukuh,', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 22, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', NULL, 'For a known extent.', 'Hingga ke suatu masa yang termaklum?', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 23, 'فَقَدَرْنَا فَنِعْمَ ٱلْقَٰدِرُونَ', 'فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ', NULL, 'And We determined [it], and excellent [are We] to determine.', 'Serta Kami tentukan (keadaannya), maka Kamilah sebaik-baik yang berkuasa menentukan dan melakukan (tiap-tiap sesuatu)!', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 24, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (kekuasaan Kami)!', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 25, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا', 'أَلَمْ نَجْعَلِ الْأَرْضَ كِفَاتًا', NULL, 'Have We not made the earth a container', 'Bukankah Kami telah menjadikan bumi (sebagai tempat) penampung dan penghimpun (penduduknya)? -', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 26, 'أَحْيَآءً وَأَمْوَٰتًا', 'أَحْيَاءً وَأَمْوَاتًا', NULL, 'Of the living and the dead?', 'Yang hidup dan yang mati?', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 27, 'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَٰمِخَٰتٍ وَأَسْقَيْنَٰكُم مَّآءً فُرَاتًا', 'وَجَعَلْنَا فِيهَا رَوَاسِيَ شَامِخَاتٍ وَأَسْقَيْنَاكُم مَّاءً فُرَاتًا', NULL, 'And We placed therein lofty, firmly set mountains and have given you to drink sweet water.', 'Dan Kami telah jadikan di bumi: gunung-ganang yang menetapnya, yang tinggi menjulang; dan Kami telah memberi minum kepada kamu air yang tawar lagi memuaskan dahaga?', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 28, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (nikmat-nikmat pemberian Kami)!', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 29, 'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 'انطَلِقُوا إِلَىٰ مَا كُنتُم بِهِ تُكَذِّبُونَ', NULL, '[They will be told], "Proceed to that which you used to deny.', '(Dikatakan kepada mereka semasa ditimpakan dengan azab): “Pergilah kepada azab yang dahulu kamu mendustakannya.', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 30, 'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَٰثِ شُعَبٍ', 'انطَلِقُوا إِلَىٰ ظِلٍّ ذِي ثَلَاثِ شُعَبٍ', NULL, 'Proceed to a shadow [of smoke] having three columns', '“Pergilah kamu kepada naungan (asap neraka) yang bercabang tiga, -', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 31, 'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ', 'لَّا ظَلِيلٍ وَلَا يُغْنِي مِنَ اللَّهَبِ', NULL, '[But having] no cool shade and availing not against the flame."', '“Yang tidak dapat dijadikan naungan, dan tidak dapat memberikan sebarang lindungan dari julangan api neraka.', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 32, 'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ', 'إِنَّهَا تَرْمِي بِشَرَرٍ كَالْقَصْرِ', NULL, 'Indeed, it throws sparks [as huge] as a fortress,', '“Sesungguhnya neraka itu melemparkan bunga api, (yang besarnya) seperti bangunan besar,', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 33, 'كَأَنَّهُۥ جِمَٰلَتٌ صُفْرٌ', 'كَأَنَّهُ جِمَالَتٌ صُفْرٌ', NULL, 'As if they were yellowish [black] camels.', '“(Banyaknya dan warnanya) bunga api itu seolah-olah rombongan unta kuning”.', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 34, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (keadaan yang demikian).', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 35, 'هَٰذَا يَوْمُ لَا يَنطِقُونَ', 'هَٰذَا يَوْمُ لَا يَنطِقُونَ', NULL, 'This is a Day they will not speak,', 'Inilah hari mereka tidak dapat berkata-kata, (kerana masing-masing terpinga-pinga ketakutan),', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 36, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', NULL, 'Nor will it be permitted for them to make an excuse.', 'Dan tidak pula diizinkan mereka bercakap, maka mereka tidak dapat meminta maaf.', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 37, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (hari akhirat)!', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 38, 'هَٰذَا يَوْمُ ٱلْفَصْلِ جَمَعْنَٰكُمْ وَٱلْأَوَّلِينَ', 'هَٰذَا يَوْمُ الْفَصْلِ جَمَعْنَاكُمْ وَالْأَوَّلِينَ', NULL, 'This is the Day of Judgement; We will have assembled you and the former peoples.', 'Inilah hari pemutusan hukum (yang menentukan siapa yang benar dan siapa yang salah). Kami himpunkan kamu bersama orang-orang yang terdahulu (dari kamu).', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 39, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', NULL, 'So if you have a plan, then plan against Me.', 'Oleh itu, kalau kamu ada sebarang tipu-helah melepaskan diri, maka cubalah kamu lakukan terhadap azabKu.', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 40, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (apa yang telah dijanjikan oleh Allah)!', FALSE, NULL, NULL, 581, 29, 232, 516, FALSE, 0, NULL),
(77, 41, 'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَٰلٍ وَعُيُونٍ', 'إِنَّ الْمُتَّقِينَ فِي ظِلَالٍ وَعُيُونٍ', NULL, 'Indeed, the righteous will be among shades and springs', 'Sesungguhnya orang-orang yang bertaqwa berada di tempat teduh (yang dipenuhi pelbagai nikmat), dan yang berdekatan dengan matair-matair (yang mengalir), -', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 42, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ', 'وَفَوَاكِهَ مِمَّا يَشْتَهُونَ', NULL, 'And fruits from whatever they desire,', 'Serta menikmati buah-buahan dari segala jenis yang mereka ingini.', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 43, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا كُنتُمْ تَعْمَلُونَ', NULL, '[Being told], "Eat and drink in satisfaction for what you used to do."', '(Pada ketika itu dikatakan kepada mereka): “Makanlah dan minumlah kamu dengan lazatnya, disebabkan apa yang kamu telah kerjakan.”', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 44, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', NULL, 'Indeed, We thus reward the doers of good.', 'Sesungguhnya, demikianlah Kami membalas orang-orang yang berusaha mengerjakan amal-amal yang baik.', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 45, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (nikmat-nikmat Syurga)!', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 46, 'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ', 'كُلُوا وَتَمَتَّعُوا قَلِيلًا إِنَّكُم مُّجْرِمُونَ', NULL, '[O disbelievers], eat and enjoy yourselves a little; indeed, you are criminals.', 'Makanlah dan bersenang-senanglah kamu (wahai orang-orang yang ingkar derhaka) sementara waktu hidup, (kemudian kamu akan menghadapi bahaya), kerana sesungguhnya kamu adalah orang-orang yang berdosa.', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 47, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (amaran Allah), -', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 48, 'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ', 'وَإِذَا قِيلَ لَهُمُ ارْكَعُوا لَا يَرْكَعُونَ', NULL, 'And when it is said to them, "Bow [in prayer]," they do not bow.', 'Dan apabila dikatakan kepada mereka (yang ingkar): “Taatlah dan kerjakanlah sembahyang”, mereka enggan mengerjakannya.', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 49, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', NULL, 'Woe, that Day, to the deniers.', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan (perintah-perintah Allah dan laranganNya)!', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(77, 50, 'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ', NULL, 'Then in what statement after it [i.e., the Qur’ān] will they believe?', '(Kalau mereka tidak juga mahu beriman kepada keterangan-keterangan yang tersebut) maka kepada perkataan yang mana lagi, sesudah itu, mereka mahu beriman?', FALSE, NULL, NULL, 581, 29, 232, 517, FALSE, 0, NULL),
(78, 1, 'عَمَّ يَتَسَآءَلُونَ', 'عم يتساءلون', NULL, 'About what are they asking one another?', 'Tentang apakah mereka bertanya-tanya?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 2, NULL),
(78, 2, 'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ', 'عن النبا العظيم', NULL, 'About the great news -', 'Tentang berita yang besar, (berita kebangkitan manusia hidup semula menerima balasannya).', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 3, 'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ', 'الذي هم فيه مختلفون', NULL, 'That over which they are in disagreement.', 'Yang mereka (ragu-ragu dan) berselisihan mengenainya.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 4, 'كَلَّا سَيَعْلَمُونَ', 'كلا سيعلمون', NULL, 'No! They are going to know.', 'Jangan! (Janganlah mereka bersikap demikian!) Mereka akan mengetahui (dengan yakin tentang kebenaran hari balasan itu).', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 2, NULL),
(78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 'ثم كلا سيعلمون', NULL, 'Then, no! They are going to know.', 'Sekali lagi jangan! (Janganlah mereka berselisihan!) Mereka akan mengetahui kelak (tentang apa yang akan menimpa mereka).', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 6, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًا', 'الم نجعل الارض مهادا', NULL, 'Have We not made the earth a resting place?', '(Mengapa kamu ragu-ragukan kekuasaan Kami menghidupkan semula orang-orang yang telah mati?) Bukankah Kami telah menjadikan bumi (terbentang luas) sebagai hamparan?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 7, 'وَٱلْجِبَالَ أَوْتَادًا', 'والجبال اوتادا', NULL, 'And the mountains as stakes?', 'Dan gunung-ganang sebagai pancang pasaknya?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 2, NULL),
(78, 8, 'وَخَلَقْنَـٰكُمْ أَزْوَٰجًا', 'وخلقناكم ازواجا', NULL, 'And We created you in pairs', 'Dan Kami telah menciptakan kamu berpasang-pasang?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 2, NULL),
(78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', 'وجعلنا نومكم سباتا', NULL, 'And made your sleep [a means for] rest', 'Dan Kami telah menjadikan tidur kamu untuk berehat?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 10, 'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا', 'وجعلنا الليل لباسا', NULL, 'And made the night as clothing', 'Dan Kami telah menjadikan malam (dengan gelapnya) sebagai pakaian (yang melindungi)?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 11, 'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا', 'وجعلنا النهار معاشا', NULL, 'And made the day for livelihood', 'Dan Kami telah menjadikan siang (dengan cahaya terangnya) - masa untuk mencari rezeki?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 12, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', 'وبنينا فوقكم سبعا شدادا', NULL, 'And constructed above you seven strong [heavens]', 'Dan Kami telah membina di atas kamu tujuh petala (langit) yang kuat kukuh?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 13, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', 'وجعلنا سراجا وهاجا', NULL, 'And made [therein] a burning lamp', 'Dan Kami telah mengadakan matahari menjadi lampu yang terang-benderang cahayanya?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 3, NULL),
(78, 14, 'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا', 'وانزلنا من المعصرات ماء ثجاجا', NULL, 'And sent down from the rain clouds pouring water', 'Dan Kami telah menurunkan dari awan, air (hujan) yang mencurah-curah, -', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 5, NULL),
(78, 15, 'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا', 'لنخرج به حبا ونباتا', NULL, 'That We may bring forth thereby grain and vegetation', 'Untuk Kami mengeluarkan dengan air itu, biji-bijian dan tumbuh-tumbuhan, -', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 16, 'وَجَنَّـٰتٍ أَلْفَافًا', 'وجنات الفافا', NULL, 'And gardens of entwined growth.', 'Serta kebun-kebun yang subur bertaut-taut pokoknya?', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 2, NULL),
(78, 17, 'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًا', 'ان يوم الفصل كان ميقاتا', NULL, 'Indeed, the Day of Judgement is an appointed time -', 'Sesungguhnya hari pemutusan hukum itu, adalah satu masa yang ditentukan,', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 5, NULL),
(78, 18, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا', 'يوم ينفخ في الصور فتاتون افواجا', NULL, 'The Day the Horn is blown and you will come forth in multitudes', 'Iaitu masa ditiup sangkakala, lalu kamu (bangkit hidup) serta datang berpuak-puak (ke Padang Mahsyar);', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 6, NULL),
(78, 19, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا', 'وفتحت السماء فكانت ابوابا', NULL, 'And the heaven is opened and will become gateways', 'Dan (pada masa itu) langit dipecah belahkan sehingga tiap-tiap belahannya menjadi ibarat pintu yang terbuka luas,', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 20, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', 'وسيرت الجبال فكانت سرابا', NULL, 'And the mountains are removed and will be [but] a mirage.', 'Dan gunung-ganang - setelah dihancurkan - diterbangkan ke angkasa, lalu menjadilah ia bayangan semata-mata seperti riak sinaran panas di padang pasir.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 4, NULL),
(78, 21, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', NULL, 'Indeed, Hell has been lying in wait', 'Sesungguhnya neraka Jahannam adalah disediakan -', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 22, 'لِّلطَّٰغِينَ مَـَٔابًا', 'لِّلطَّاغِينَ مَآبًا', NULL, 'For the transgressors, a place of return,', 'Untuk orang-orang yang melampaui batas hukum Tuhan, sebagai tempat kembalinya.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 23, 'لَّٰبِثِينَ فِيهَآ أَحْقَابًا', 'لَّابِثِينَ فِيهَا أَحْقَابًا', NULL, 'In which they will remain for ages [unending].', 'Mereka tinggal di dalamnya berkurun-kurun lamanya.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', NULL, 'They will not taste therein [any] coolness or drink.', 'Mereka tidak dapat merasai udara yang sejuk di dalamnya, dan tidak pula sebarang minuman -', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 25, 'إِلَّا حَمِيمًا وَغَسَّاقًا', 'إِلَّا حَمِيمًا وَغَسَّاقًا', NULL, 'Except scalding water and [foul] purulence -', 'Kecuali air panas yang menggelegak, dan air danur yang mengalir, -', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 26, 'جَزَآءً وِفَاقًا', 'جَزَاءً وِفَاقًا', NULL, 'An appropriate recompense.', 'Sebagai balasan yang sesuai (dengan amal mereka yang buruk).', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 27, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا', 'إِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَابًا', NULL, 'Indeed, they were not expecting an account', 'Kerana sesungguhnya mereka dahulu tidak menaruh ingatan terhadap hari hitungan amal,', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 28, 'وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًا', 'وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا', NULL, 'And denied Our verses with [emphatic] denial.', 'Dan mereka telah mendustakan dengan sesungguh-sungguhnya akan ayat-ayat keterangan Kami;', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 29, 'وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًا', 'وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا', NULL, 'But all things We have enumerated in writing.', 'Dan tiap-tiap sesuatu dari bawaan hidupnya, telah Kami hitung secara bertulis.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 30, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 'فَذُوقُوا فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', NULL, '"So taste [the penalty], and never will We increase you except in torment."', '(Setelah mereka masuk ke dalam neraka, dikatakan kepada mereka: “Oleh sebab kamu telah mendustakan ayat-ayat Kami) maka rasalah kamu (azab yang disediakan), kerana Kami tidak akan melakukan selain dari menambah berbagai azab kepada kamu”.', FALSE, NULL, NULL, 582, 30, 233, 518, FALSE, 0, NULL),
(78, 31, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', NULL, 'Indeed, for the righteous is attainment -', 'Sesungguhnya orang-orang yang bertaqwa, disediakan Syurga tempat mereka beroleh apa yang mereka ingini.', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 32, 'حَدَآئِقَ وَأَعْنَٰبًا', 'حَدَائِقَ وَأَعْنَابًا', NULL, 'Gardens and grapevines', '(Mereka akan beroleh) taman-taman bunga dan kebun-kebun buah-buahan, terutama anggur;', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 33, 'وَكَوَاعِبَ أَتْرَابًا', 'وَكَوَاعِبَ أَتْرَابًا', NULL, 'And young women [companions] of equal age.', 'Dan perawan-perawan yang sebaya umurnya;', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 34, 'وَكَأْسًا دِهَاقًا', 'وَكَأْسًا دِهَاقًا', NULL, 'And a full cup.', 'Serta piala atau gelas yang penuh dengan minuman;', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 35, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا', 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّابًا', NULL, 'No ill speech will they hear therein or any falsehood -', 'Mereka tidak mendengar di dalam Syurga itu perkataan yang sia-sia, dan tiada pula perkataan yang dusta;', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 36, 'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا', 'جَزَاءً مِّن رَّبِّكَ عَطَاءً حِسَابًا', NULL, '[As] reward from your Lord, [a generous] gift [made due by] account,', 'Sebagai balasan dari Tuhanmu, iaitu satu limpah kurnia yang dikira cukup (menurut yang dijanjikanNya),', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 37, 'رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', 'رَّبِّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الرَّحْمَٰنِ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', NULL, '[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.', 'Tuhan yang mentadbirkan tujuh petala langit dan bumi serta apa yang ada di antara keduanya, Tuhan Yang Maha Pemurah, tidak ada sesiapapun diberi kuasa berkata-kata denganNya (untuk memohon pertimbangan tentang balasan atau pengurniaan itu);', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 38, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّا لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًا', 'يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفًّا لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ الرَّحْمَٰنُ وَقَالَ صَوَابًا', NULL, 'The Day that the Spirit [i.e., Gabriel] and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.', '(Tambahan pula) pada masa Jibril dan malaikat-malaikat yang lain berdiri bersaf-saf (menunggu perintah Tuhan), tidak ada yang berani berkata-kata (memohon pertimbangan) melainkan yang telah diizinkan baginya oleh Tuhan Yang Maha Pemurah, serta ia berkata benar.', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 39, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', 'ذَٰلِكَ الْيَوْمُ الْحَقُّ فَمَن شَاءَ اتَّخَذَ إِلَىٰ رَبِّهِ مَآبًا', NULL, 'That is the True [i.e., certain] Day; so he who wills may take to his Lord a [way of] return.', 'Itulah keterangan-keterangan mengenai hari (kiamat) yang sungguh tetap berlakunya; maka sesiapa yang mahukan kebaikan dirinya, dapatlah ia mengambil jalan dan cara kembali kepada Tuhannya (dengan iman dan amal yang soleh)!', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(78, 40, 'إِنَّآ أَنذَرْنَٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا', 'إِنَّا أَنذَرْنَاكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنتُ تُرَابًا', NULL, 'Indeed, We have warned you of an impending punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, "Oh, I wish that I were dust!"', 'Sesungguhnya (dengan keterangan-keterangan yang tersebut), Kami memberi amaran kepada kamu mengenai azab yang dekat (masa datangnya), - iaitu hari seseorang melihat apa yang telah diusahakannya; dan orang yang kafir akan berkata (pada hari itu): “Alangkah baiknya kalau aku menjadi tanah (supaya aku tidak dibangkitkan untuk dihitung amalku dan menerima balasan)”.', FALSE, NULL, NULL, 583, 30, 233, 519, FALSE, 0, NULL),
(79, 1, 'وَٱلنَّـٰزِعَـٰتِ غَرْقًا', 'والنازعات غرقا', NULL, 'By those [angels] who extract with violence', 'Demi (makhluk-makhluk) yang mencabut (apa yang ditugaskan mencabutnya) dengan cara yang sekasar-kasarnya;', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 2, 'وَٱلنَّـٰشِطَـٰتِ نَشْطًا', 'والناشطات نشطا', NULL, 'And [by] those who remove with ease', 'Dan yang menarik (apa yang ditugaskan menariknya) dengan cara yang selembut-lembutnya;', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 3, 'وَٱلسَّـٰبِحَـٰتِ سَبْحًا', 'والسابحات سبحا', NULL, 'And [by] those who glide [as if] swimming', 'Dan demi (makhluk-makhluk) yang cergas bergerak (menerima perintah) dengan gerak yang secergas-cergasnya;', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 4, 'فَٱلسَّـٰبِقَـٰتِ سَبْقًا', 'فالسابقات سبقا', NULL, 'And those who race each other in a race', 'Lalu masing-masing berlumba-lumba dahulu-mendahului (menjalankan tugasnya) dengan cara yang sesungguh-sungguhnya;', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 5, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا', 'فالمدبرات امرا', NULL, 'And those who arrange [each] matter,', 'Serta menyempurnakan tadbir urusan alam yang diperintahkan kepadanya; (sumpah demi sumpah, sesungguhnya kamu akan dibangkitkan hidup semula pada hari kiamat)! -', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 6, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', 'يوم ترجف الراجفة', NULL, 'On the Day the blast [of the Horn] will convulse [creation],', 'Pada masa berlakunya “tiupan sangkakala yang pertama” yang menggoncangkan alam, (sehingga mati segala yang bernyawa dan punah-ranah sekalian makhluk selain dari yang dikecualikan),', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 3, NULL),
(79, 7, 'تَتْبَعُهَا ٱلرَّادِفَةُ', 'تتبعها الرادفة', NULL, 'There will follow it the subsequent [one].', 'Tiupan yang pertama itu diikuti oleh tiupan yang kedua, (yang menyebabkan orang-orang yang mati semuanya hidup semula serta keluar dari kubur masing-masing);', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 8, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ', 'قلوب يومئذ واجفة', NULL, 'Hearts, that Day, will tremble,', 'Hati (manusia) pada hari itu berdebar-debar takut,', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 3, NULL),
(79, 9, 'أَبْصَـٰرُهَا خَـٰشِعَةٌ', 'ابصارها خاشعة', NULL, 'Their eyes humbled.', 'Pemandangannya tunduk gerun.', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 2, NULL),
(79, 10, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', 'يقولون اانا لمردودون في الحافرة', NULL, 'They are [presently] saying, "Will we indeed be returned to [our] former state [of life]?', 'Mereka (yang ingkar) berkata: “Sungguhkah kita akan dikembalikan hidup seperti keadaan di dunia dahulu?', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 5, NULL),
(79, 11, 'أَءِذَا كُنَّا عِظَـٰمًا نَّخِرَةً', 'ااذا كنا عظاما نخرة', NULL, 'Even if we should be decayed bones?"', '“Bolehkah (dihidupkan semula) sesudah kita menjadi tulang yang reput?”', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 4, NULL),
(79, 12, 'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ', 'قالوا تلك اذا كرة خاسرة', NULL, 'They say, "That, then, would be a losing return."', 'Mereka berkata lagi (secara mengejek: “Kalaulah berlaku) yang demikian, sudah tentu kembalinya kita (hidup semula) itu satu perkara yang merugikan!”', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 5, NULL),
(79, 13, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ', 'فانما هي زجرة واحدة', NULL, 'Indeed, it will be but one shout,', '(Menghidupkan semula tidaklah sukar), kerana berlakunya perkara itu hanyalah dengan satu jeritan (yang terbit dari tiupan sangkakala yang kedua), -', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 4, NULL),
(79, 14, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', 'فاذا هم بالساهرة', NULL, 'And suddenly they will be [alert] upon the earth''s surface.', 'Yang menyebabkan mereka dengan serta-merta berada di muka bumi yang putih rata.', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 3, NULL),
(79, 15, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'هل اتاك حديث موسى', NULL, 'Has there reached you the story of Moses? -', 'Sudahkah sampai kepadamu (wahai Muhammad) perihal Nabi Musa?', FALSE, NULL, NULL, 583, 30, 233, 520, FALSE, 4, NULL),
(79, 16, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'اذ ناداه ربه بالواد المقدس طوى', NULL, 'When his Lord called to him in the sacred valley of Ṭuwā,', 'Ketika ia diseru oleh Tuhannya di “Wadi Tuwa” yang suci; -', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 6, NULL),
(79, 17, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'اذهب الى فرعون انه طغى', NULL, '"Go to Pharaoh. Indeed, he has transgressed.', '(Lalu diperintahkan kepadanya): “Pergilah kepada Firaun, sesungguhnya ia telah melampaui batas (dalam kekufuran dan kezalimannya);', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 5, NULL),
(79, 18, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', 'فقل هل لك الى ان تزكى', NULL, 'And say to him, ''Would you [be willing to] purify yourself', '“Serta katakanlah kepadanya: ‘Adakah engkau suka hendak mensucikan dirimu (dari kekufuran)?', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 6, NULL),
(79, 19, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', 'واهديك الى ربك فتخشى', NULL, 'And let me guide you to your Lord so you would fear [Him]?''"', '‘Dan mahukah, aku tunjuk kepadamu jalan mengenal Tuhanmu, supaya engkau merasa takut (melanggar perintahNya)?’”', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 4, NULL),
(79, 20, 'فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ', 'فاراه الاية الكبرى', NULL, 'And he showed him the greatest sign,', '(Setelah Nabi Musa menyempurnakan perintah Tuhannya, dan Firaun pun meminta bukti kebenarannya); maka Nabi Musa memperlihatkan kepada Firaun: mukjizat yang besar.', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 3, NULL),
(79, 21, 'فَكَذَّبَ وَعَصَىٰ', 'فَكَذَّبَ وَعَصَىٰ', NULL, 'But he [i.e., Pharaoh] denied and disobeyed.', 'Lalu Firaun mendustakan (Nabi Musa) dan menderhaka (kepada Allah);', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 22, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', 'ثُمَّ أَدْبَرَ يَسْعَىٰ', NULL, 'Then he turned his back, striving [i.e., plotting].', 'Kemudian ia berpaling ingkar sambil menjalankan usahanya (menentang Nabi Musa).', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 23, 'فَحَشَرَ فَنَادَىٰ', 'فَحَشَرَ فَنَادَىٰ', NULL, 'And he gathered [his people] and called out', 'Lalu ia menghimpunkan orang-orangnya dan menyeru, -', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 24, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', 'فَقَالَ أَنَا رَبُّكُمُ الْأَعْلَىٰ', NULL, 'And said, "I am your most exalted lord."', 'Dengan berkata: “Akulah tuhan kamu, yang tertinggi”.', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 25, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ', 'فَأَخَذَهُ اللَّهُ نَكَالَ الْآخِرَةِ وَالْأُولَىٰ', NULL, 'So Allāh seized him in exemplary punishment for the last and the first [transgression]..', 'Maka Allah menyeksa Firaun di akhirat dan di dunia ini, dengan azab yang menakutkan sesiapa yang mengetahuinya.', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 26, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ', 'إِنَّ فِي ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰ', NULL, 'Indeed in that is a lesson [i.e., warning] for whoever would fear [Allāh].', 'Sesungguhnya yang demikian itu mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang takut (melanggar perintah Tuhannya).', FALSE, NULL, NULL, 584, 30, 233, 520, FALSE, 0, NULL),
(79, 27, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ بَنَىٰهَا', 'أَأَنتُمْ أَشَدُّ خَلْقًا أَمِ السَّمَاءُ بَنَاهَا', NULL, 'Are you a more difficult creation or is the heaven? He [i.e., Allāh] constructed it.', '(Wahai golongan yang ingkarkan kebangkitan hidup semula!) Kamukah yang sukar diciptakan atau langit? Tuhan telah membinanya (dengan Kukuh)!', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 28, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 'رَفَعَ سَمْكَهَا فَسَوَّاهَا', NULL, 'He raised its ceiling and proportioned it.', 'Ia telah meninggikan bangunan langit itu lalu menyempurnaKannya,', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 29, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَاهَا', NULL, 'And He darkened its night and extracted its brightness.', 'Dan Ia menjadikan malamnya gelap-gelita, serta menjadikan siangnya terang-benderang.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 30, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 'وَالْأَرْضَ بَعْدَ ذَٰلِكَ دَحَاهَا', NULL, 'And after that He spread the earth.', 'Dan bumi sesudah itu dihamparkannya (untuk kemudahan penduduknya), -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 31, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 'أَخْرَجَ مِنْهَا مَاءَهَا وَمَرْعَاهَا', NULL, 'He extracted from it its water and its pasture,', 'Ia mengeluarkan dari bumi itu: airnya dan tumbuh-tumbuhannya;', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 32, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 'وَالْجِبَالَ أَرْسَاهَا', NULL, 'And the mountains He set firmly', 'Dan gunung-ganang pula dikukuhkan letaknya (di bumi, sebagai pancang pasak yang menetapnya);', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 33, 'مَتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 'مَتَاعًا لَّكُمْ وَلِأَنْعَامِكُمْ', NULL, 'As enjoyment [i.e., provision] for you and your grazing livestock.', '(Semuanya itu) untuk kegunaan kamu dan binatang-binatang ternak kamu.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 34, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 'فَإِذَا جَاءَتِ الطَّامَّةُ الْكُبْرَىٰ', NULL, 'But when there comes the greatest Overwhelming Calamity -', 'Maka apabila datang hari yang bencananya amat besar, -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 35, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ', 'يَوْمَ يَتَذَكَّرُ الْإِنسَانُ مَا سَعَىٰ', NULL, 'The Day when man will remember that for which he strove,', 'Iaitu hari manusia akan mengingati apa yang telah diusahakannya, -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 36, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 'وَبُرِّزَتِ الْجَحِيمُ لِمَن يَرَىٰ', NULL, 'And Hellfire will be exposed for [all] those who see -', 'Dan neraka diperlihatkan kepada sesiapa sahaja yang dapat melihatnya, -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 37, 'فَأَمَّا مَن طَغَىٰ', 'فَأَمَّا مَن طَغَىٰ', NULL, 'So as for he who transgressed', 'Maka (dapatlah masing-masing mengetahui kesudahannya); adapun orang yang melampau (perbuatan derhakanya), -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 38, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'وَآثَرَ الْحَيَاةَ الدُّنْيَا', NULL, 'And preferred the life of the world,', 'Serta ia mengutamakan kehidupan dunia semata-mata, -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 39, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 'فَإِنَّ الْجَحِيمَ هِيَ الْمَأْوَىٰ', NULL, 'Then indeed, Hellfire will be [his] refuge.', 'Maka sesungguhnya neraka Jahanamlah tempat kediamannya.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 40, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ', NULL, 'But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,', 'Adapun orang yang takutkan keadaan semasa ia berdiri di mahkamah Tuhannya, (untuk dihitung amalnya), serta ia menahan dirinya dari menurut hawa nafsu, -', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 41, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 'فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَىٰ', NULL, 'Then indeed, Paradise will be [his] refuge.', 'Maka sesungguhnya Syurgalah tempat kediamannya.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 42, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 'يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا', NULL, 'They ask you, [O Muḥammad], about the Hour: when is its arrival?', 'Mereka (yang ingkar) selalu bertanya kepadamu (wahai Muhammad) tentang hari kiamat: “Bilakah masa datangnya?”', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 43, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 'فِيمَ أَنتَ مِن ذِكْرَاهَا', NULL, 'In what [position] are you that you should mention it?', 'Apa hubungannya tugasmu dengan (soal) menerangkan masa kedatangan hari kiamat itu?', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 44, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 'إِلَىٰ رَبِّكَ مُنتَهَاهَا', NULL, 'To your Lord is its finality.', 'Kepada Tuhanmu lah terserah kesudahan ilmu mengenainya.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 45, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 'إِنَّمَا أَنتَ مُنذِرُ مَن يَخْشَاهَا', NULL, 'You are only a warner for those who fear it.', 'Tugasmu hanyalah memberi amaran kepada orang yang takut akan huru-hara hari kiamat itu.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(79, 46, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوا إِلَّا عَشِيَّةً أَوْ ضُحَاهَا', NULL, 'It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof.', '(Sangatlah dahsyatnya huru-hara hari itu, sehingga orang-orang yang bersalah merasa) pada masa melihatnya: seolah-olah mereka tidak tinggal di dunia melainkan sekadar satu petang atau paginya sahaja.', FALSE, NULL, NULL, 584, 30, 233, 521, FALSE, 0, NULL),
(80, 1, 'عَبَسَ وَتَوَلَّىٰٓ', 'عبس وتولى', NULL, 'He [i.e., the Prophet (ﷺ) ] frowned and turned away', 'Ia memasamkan muka dan berpaling,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 2, NULL),
(80, 2, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 'ان جاءه الاعمى', NULL, 'Because there came to him the blind man, [interrupting].', 'Kerana ia didatangi orang buta.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 3, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 'وما يدريك لعله يزكى', NULL, 'But what would make you perceive, [O Muḥammad], that perhaps he might be purified', 'Dan apa jalannya engkau dapat mengetahui (tujuannya, wahai Muhammad)? Barangkali ia mahu membersihkan hatinya (dengan pelajaran ugama yang didapatinya daripadamu)! -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 4, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 'او يذكر فتنفعه الذكرى', NULL, 'Or be reminded and the remembrance would benefit him?', 'Ataupun ia mahu mendapat peringatan, supaya peringatan itu memberi manfaat kepadanya.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 5, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 'اما من استغنى', NULL, 'As for he who thinks himself without need,', 'Adapun orang yang merasa keadaannya telah cukup, tidak berhajat lagi (kepada ajaran Al-Quran),', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 6, 'فَأَنتَ لَهُۥ تَصَدَّىٰ', 'فانت له تصدى', NULL, 'To him you give attention.', 'Maka engkau bersungguh-sungguh melayaninya.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 7, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', 'وما عليك الا يزكى', NULL, 'And not upon you [is any blame] if he will not be purified.', 'Padahal engkau tidak bersalah kalau ia tidak mahu membersihkan dirinya (dari keingkarannya).', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 8, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', 'واما من جاءك يسعى', NULL, 'But as for he who came to you striving [for knowledge]', 'Adapun orang yang segera datang kepadamu,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 9, 'وَهُوَ يَخْشَىٰ', 'وهو يخشى', NULL, 'While he fears [Allāh],', 'Dengan perasaan takutnya (melanggar perintah-perintah Allah), -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 2, NULL),
(80, 10, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', 'فانت عنه تلهى', NULL, 'From him you are distracted.', 'Maka engkau berlengah-lengah melayaninya.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 11, 'كَلَّآ إِنَّهَا تَذْكِرَةٌ', 'كلا انها تذكرة', NULL, 'No! Indeed, they [i.e., these verses] are a reminder;', 'Janganlah melakukan lagi yang sedemikian itu! Sebenarnya ayat-ayat Al-Quran adalah pengajaran dan peringatan (yang mencukupi).', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 12, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فمن شاء ذكره', NULL, 'So whoever wills may remember it.', 'Maka sesiapa yang mahukan kebaikan dirinya, dapatlah ia mengambil peringatan daripadanya.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 13, 'فِى صُحُفٍ مُّكَرَّمَةٍ', 'في صحف مكرمة', NULL, '[It is recorded] in honored sheets,', '(Ayat-ayat Suci itu tersimpan) dalam naskhah-naskhah yang dimuliakan, -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 14, 'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ', 'مرفوعة مطهرة', NULL, 'Exalted and purified,', 'Yang tinggi darjatnya, lagi suci (dari segala gangguan), -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 2, NULL),
(80, 15, 'بِأَيْدِى سَفَرَةٍ', 'بايدي سفرة', NULL, '[Carried] by the hands of messenger-angels,', '(Terpelihara) di tangan malaikat-malaikat yang menyalinnya dari Lauh Mahfuz;', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 2, NULL),
(80, 16, 'كِرَامٍۭ بَرَرَةٍ', 'كرام بررة', NULL, 'Noble and dutiful.', '(Malaikat-malaikat) yang mulia, lagi yang berbakti.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 2, NULL),
(80, 17, 'قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ', 'قتل الانسان ما اكفره', NULL, 'Destroyed [i.e., cursed] is man; how disbelieving is he.', 'Binasalah hendaknya manusia (yang ingkar) itu, betapa besar kekufurannya?', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 18, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', 'من اي شيء خلقه', NULL, 'From what thing [i.e., substance] did He create him?', '(Tidakkah ia memikirkan) dari apakah ia diciptakan oleh Allah? -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 19, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 'من نطفة خلقه فقدره', NULL, 'From a sperm-drop He created him and destined for him;', 'Dari air mani diciptakanNya, serta dilengkapkan keadaannya dengan persediaan untuk bertanggungjawab;', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 4, NULL),
(80, 20, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', 'ثم السبيل يسره', NULL, 'Then He eased the way for him;', 'Kemudian jalan (baik dan jahat), dimudahkan Tuhan kepadanya (untuk menimbang dan mengambil mana satu yang ia pilih);', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 3, NULL),
(80, 21, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', 'ثُمَّ أَمَاتَهُ فَأَقْبَرَهُ', NULL, 'Then He causes his death and provides a grave for him.', 'Kemudian dimatikannya, lalu diperintahkan supaya ia dikuburkan;', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 22, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', 'ثُمَّ إِذَا شَاءَ أَنشَرَهُ', NULL, 'Then when He wills, He will resurrect him.', 'Kemudian apabila Allah kehendaki dibangkitkannya (hidup semula).', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 23, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', 'كَلَّا لَمَّا يَقْضِ مَا أَمَرَهُ', NULL, 'No! He [i.e., man] has not yet accomplished what He commanded him.', 'Janganlah hendaknya ia kufur ingkar lagi! Sebenarnya ia belum menunaikan apa yang diperintahkan kepadanya.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 24, 'فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ', 'فَلْيَنظُرِ الْإِنسَانُ إِلَىٰ طَعَامِهِ', NULL, 'Then let mankind look at his food -', '(Kalaulah ia tidak memikirkan asal dan kesudahan dirinya), maka hendaklah manusia melihat kepada makanannya (bagaimana kami mentadbirkannya):', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 25, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا', 'أَنَّا صَبَبْنَا الْمَاءَ صَبًّا', NULL, 'How We poured down water in torrents,', 'Sesungguhnya kami telah mencurahkan hujan dengan curahan yang menakjubkan.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 26, 'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا', 'ثُمَّ شَقَقْنَا الْأَرْضَ شَقًّا', NULL, 'Then We broke open the earth, splitting [it with sprouts],', 'Kemudian kami belah-belahkan bumi dengan belahan yang sesuai dengan tumbuh-tumbuhan, -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 27, 'فَأَنۢبَتْنَا فِيهَا حَبًّا', 'فَأَنبَتْنَا فِيهَا حَبًّا', NULL, 'And caused to grow within it grain', 'Lalu Kami tumbuhkan pada bumi biji-bijian,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 28, 'وَعِنَبًا وَقَضْبًا', 'وَعِنَبًا وَقَضْبًا', NULL, 'And grapes and herbage', 'Dan buah anggur serta sayur-sayuran,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 29, 'وَزَيْتُونًا وَنَخْلًا', 'وَزَيْتُونًا وَنَخْلًا', NULL, 'And olive and palm trees', 'Dan Zaitun serta pohon-pohon kurma,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 30, 'وَحَدَآئِقَ غُلْبًا', 'وَحَدَائِقَ غُلْبًا', NULL, 'And gardens of dense shrubbery', 'Dan taman-taman yang menghijau subur,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 31, 'وَفَٰكِهَةً وَأَبًّا', 'وَفَاكِهَةً وَأَبًّا', NULL, 'And fruit and grass -', 'Dan berbagai buah-buahan serta bermacam-macam rumput, -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 32, 'مَّتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 'مَّتَاعًا لَّكُمْ وَلِأَنْعَامِكُمْ', NULL, '[As] enjoyment [i.e., provision] for you and your grazing livestock.', 'Untuk kegunaan kamu dan binatang-binatang ternak kamu.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 33, 'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ', 'فَإِذَا جَاءَتِ الصَّاخَّةُ', NULL, 'But when there comes the Deafening Blast', 'Kemudian (ingatlah keadaan yang berlaku) apabila datang suara jeritan yang dahsyat, -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 34, 'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ', 'يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ', NULL, 'On the Day a man will flee from his brother', 'Pada hari seseorang itu lari dari saudaranya,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 35, 'وَأُمِّهِۦ وَأَبِيهِ', 'وَأُمِّهِ وَأَبِيهِ', NULL, 'And his mother and his father', 'Dan ibunya serta bapanya,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 36, 'وَصَٰحِبَتِهِۦ وَبَنِيهِ', 'وَصَاحِبَتِهِ وَبَنِيهِ', NULL, 'And his wife and his children,', 'Dan isterinya serta anak-anaknya; -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 37, 'لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ', 'لِكُلِّ امْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ', NULL, 'For every man, that Day, will be a matter adequate for him.', 'Kerana tiap-tiap seorang dari mereka pada hari itu, ada perkara-perkara yang cukup untuk menjadikannya sibuk dengan hal dirinya sahaja.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 38, 'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ', 'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ', NULL, '[Some] faces, that Day, will be bright -', 'Muka (orang-orang yang beriman) pada hari itu berseri-seri,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 39, 'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ', 'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ', NULL, 'Laughing, rejoicing at good news.', 'Tertawa, lagi bersuka ria;', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 40, 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ', 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ', NULL, 'And [other] faces, that Day, will have upon them dust.', 'Dan muka (orang-orang yang ingkar) pada hari itu penuh berdebu,', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 41, 'تَرْهَقُهَا قَتَرَةٌ', 'تَرْهَقُهَا قَتَرَةٌ', NULL, 'Blackness will cover them.', 'Diliputi oleh warna hitam legam dan gelap-gelita. -', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(80, 42, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ', 'أُولَٰئِكَ هُمُ الْكَفَرَةُ الْفَجَرَةُ', NULL, 'Those are the disbelievers, the wicked ones.', 'Mereka itu ialah orang-orang yang kafir, yang derhaka.', FALSE, NULL, NULL, 585, 30, 234, 522, FALSE, 0, NULL),
(81, 1, 'إِذَا ٱلشَّمْسُ كُوِّرَتْ', 'اذا الشمس كورت', NULL, 'When the sun is wrapped up [in darkness]', 'Apabila matahari dilingkari cahayanya (dan hilang lenyap);', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 2, 'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ', 'واذا النجوم انكدرت', NULL, 'And when the stars fall, dispersing,', 'Dan apabila bintang-bintang gugur berselerak;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 3, 'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ', 'واذا الجبال سيرت', NULL, 'And when the mountains are removed', 'Dan apabila gunung-ganang di terbangkan ke angkasa (setelah dihancurkan menjadi debu);', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 4, 'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ', 'واذا العشار عطلت', NULL, 'And when full-term she-camels are neglected', 'Dan apabila unta-unta yang bunting terbiar;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 5, 'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ', 'واذا الوحوش حشرت', NULL, 'And when the wild beasts are gathered', 'Dan apabila binatang-binatang liar dihimpunkan;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 6, 'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ', 'واذا البحار سجرت', NULL, 'And when the seas are filled with flame', 'Dan apabila lautan meluap-luap bercampur-baur;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 7, 'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ', 'واذا النفوس زوجت', NULL, 'And when the souls are paired', 'Dan apabila tiap-tiap diri disatukan dengan pasangannya;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 8, 'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ', 'واذا الموءودة سئلت', NULL, 'And when the girl [who was] buried alive is asked', 'Dan apabila anak perempuan yang ditanam hidup-hidup: ditanya, -', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 9, 'بِأَىِّ ذَنۢبٍ قُتِلَتْ', 'باي ذنب قتلت', NULL, 'For what sin she was killed', 'Dengan dosa apakah ia dibunuh?', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 10, 'وَإِذَا ٱلصُّحُفُ نُشِرَتْ', 'واذا الصحف نشرت', NULL, 'And when the pages are spread [i.e., made public]', 'Dan apabila surat-surat amal dibentangkan;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 11, 'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ', 'واذا السماء كشطت', NULL, 'And when the sky is stripped away', 'Dan apabila langit ditanggalkan dari tempatnya;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 12, 'وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ', 'واذا الجحيم سعرت', NULL, 'And when Hellfire is set ablaze', 'Dan apabila neraka dinyalakan menjulang;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 13, 'وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ', 'واذا الجنة ازلفت', NULL, 'And when Paradise is brought near,', 'Dan apabila Syurga didekatkan;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 14, 'عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ', 'علمت نفس ما احضرت', NULL, 'A soul will [then] know what it has brought [with it].', '(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui tentang amal yang telah dibawanya.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 4, NULL),
(81, 15, 'فَلَآ أُقْسِمُ بِٱلْخُنَّسِ', 'فلا اقسم بالخنس', NULL, 'So I swear by the retreating stars -', 'Oleh itu, Aku bersumpah dengan bintang-bintang yang tenggelam timbul;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 16, 'ٱلْجَوَارِ ٱلْكُنَّسِ', 'الجوار الكنس', NULL, 'Those that run [their courses] and disappear [i.e., set]', 'Yang beredar, juga yang tetap pada tempatnya;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 2, NULL),
(81, 17, 'وَٱلَّيْلِ إِذَا عَسْعَسَ', 'والليل اذا عسعس', NULL, 'And by the night as it closes in', 'Dan malam, apabila ia hampir habis,', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 18, 'وَٱلصُّبْحِ إِذَا تَنَفَّسَ', 'والصبح اذا تنفس', NULL, 'And by the dawn when it breathes [i.e., stirs]', 'Dan siang, apabila ia mulai terang;', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 3, NULL),
(81, 19, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 'انه لقول رسول كريم', NULL, '[That] indeed, it [i.e., the Qur’ān] is a word [conveyed by] a noble messenger [i.e., Gabriel]', 'Sebenarnya Al-Quran itu, sungguh-sungguh Kalamullah (yang disampaikan oleh Jibril) Utusan yang mulia,', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 4, NULL),
(81, 20, 'ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍ', 'ذي قوة عند ذي العرش مكين', NULL, '[Who is] possessed of power and with the Owner of the Throne, secure [in position],', 'Yang kuat gagah, lagi berkedudukan tinggi di sisi Allah yang mempunyai Arasy,', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 6, NULL),
(81, 21, 'مُّطَاعٍ ثَمَّ أَمِينٍ', 'مُّطَاعٍ ثَمَّ أَمِينٍ', NULL, 'Obeyed there [in the heavens] and trustworthy.', 'Yang ditaati di sana (dalam kalangan malaikat), lagi dipercayai.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 22, 'وَمَا صَاحِبُكُم بِمَجْنُونٍ', 'وَمَا صَاحِبُكُم بِمَجْنُونٍ', NULL, 'And your companion [i.e., Prophet Muḥammad (ﷺ) ] is not [at all] mad.', 'Dan sebenarnya sahabat kamu (Nabi Muhammad) itu (wahai golongan yang menentang Islam), bukanlah ia seorang gila (seperti yang kamu tuduh);', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 23, 'وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ', 'وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ', NULL, 'And he has already seen him [i.e., Gabriel] in the clear horizon.', 'Dan (Nabi Muhammad yakin bahawa yang disampaikan kepadanya ialah wahyu dari Tuhan, kerana) demi sesungguhnya! Nabi Muhammad telah mengenal dan melihat Jibril di kaki langit yang nyata.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 24, 'وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ', 'وَمَا هُوَ عَلَى الْغَيْبِ بِضَنِينٍ', NULL, 'And he [i.e., Muḥammad (ﷺ)] is not a withholder of [knowledge of] the unseen.', 'Dan bukanlah Nabi Muhammad seorang yang boleh dituduh dan disangka buruk, terhadap penyampaiannya mengenai perkara-perkara yang ghaib.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 25, 'وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍ رَّجِيمٍ', 'وَمَا هُوَ بِقَوْلِ شَيْطَانٍ رَّجِيمٍ', NULL, 'And it [i.e., the Qur’ān] is not the word of a devil, expelled [from the heavens].', 'Dan sebenarnya Al-Quran itu bukanlah perkataan Syaitan yang kena rejam.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 26, 'فَأَيْنَ تَذْهَبُونَ', 'فَأَيْنَ تَذْهَبُونَ', NULL, 'So where are you going?', '(Dengan yang demikian) maka ke manakah kamu hendak pergi (kiranya kamu masih menyeleweng dari jalan Al-Quran)?', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 27, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَالَمِينَ', NULL, 'It is not except a reminder to the worlds', 'Al-Quran itu tidak lain hanyalah peringatan bagi seluruh penduduk alam:', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 28, 'لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ', 'لِمَن شَاءَ مِنكُمْ أَن يَسْتَقِيمَ', NULL, 'For whoever wills among you to take a right course.', 'Iaitu bagi sesiapa dari kamu yang mahu tetap teguh di atas jalan (Islam) yang betul.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(81, 29, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'وَمَا تَشَاءُونَ إِلَّا أَن يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ', NULL, 'And you do not will except that Allāh wills - Lord of the worlds.', 'Dan kamu tidak dapat menentukan kemahuan kamu (mengenai sesuatupun), kecuali dengan cara yang diatur oleh Allah, Tuhan yang memelihara dan mentadbirkan seluruh alam.', FALSE, NULL, NULL, 586, 30, 234, 523, FALSE, 0, NULL),
(82, 1, 'إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', 'اذا السماء انفطرت', NULL, 'When the sky breaks apart', 'Apabila langit terbelah;', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 2, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', 'واذا الكواكب انتثرت', NULL, 'And when the stars fall, scattering,', 'Dan apabila bintang-bintang gugur bertaburan;', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 3, 'وَإِذَا ٱلْبِحَارُ فُجِّرَتْ', 'واذا البحار فجرت', NULL, 'And when the seas are erupted', 'Dan apabila lautan pecah bercampur-baur;', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 4, 'وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ', 'واذا القبور بعثرت', NULL, 'And when the [contents of] graves are scattered [i.e., exposed],', 'Dan apabila kubur-kubur dibongkarkan, -', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 5, 'عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ', 'علمت نفس ما قدمت واخرت', NULL, 'A soul will [then] know what it has put forth and kept back.', '(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui apa yang telah dikerjakan dan ditinggalkannya.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 5, NULL),
(82, 6, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ', 'يا ايها الانسان ما غرك بربك الكريم', NULL, 'O mankind, what has deceived you concerning your Lord, the Generous,', 'Wahai manusia! Apakah yang memperdayakanmu - (berlaku derhaka) kepada Tuhanmu yang Maha Pemurah? -', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 6, NULL),
(82, 7, 'ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ', 'الذي خلقك فسواك فعدلك', NULL, 'Who created you, proportioned you, and balanced you?', 'Tuhan yang telah mencipta dan mengatur kejadianmu, lalu menjadikan anggotamu sesuai (dengan tujuan yang kerananya anggota itu diadakan), serta menjadikan (binaan tubuh badanmu) sama padan dengan kekuatannya;', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 4, NULL),
(82, 8, 'فِىٓ أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ', 'في اي صورة ما شاء ركبك', NULL, 'In whatever form He willed has He assembled you.', 'Dalam bentuk dan rupa apa sahaja yang dikehendakiNya, Ia menyusun kejadianmu.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 6, NULL),
(82, 9, 'كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ', 'كلا بل تكذبون بالدين', NULL, 'No! But you deny the Recompense.', 'Sebenarnya tidak ada yang memperdayakan kamu (hai golongan yang ingkar)! Bahkan kamu sendiri tidak percayakan adanya hari pembalasan.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 4, NULL),
(82, 10, 'وَإِنَّ عَلَيْكُمْ لَحَـٰفِظِينَ', 'وان عليكم لحافظين', NULL, 'And indeed, [appointed] over you are keepers,', 'Padahal sesungguhnya, ada malaikat-malaikat yang menjaga dan mengawas segala bawaan kamu,', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 11, 'كِرَامًا كَـٰتِبِينَ', 'كراما كاتبين', NULL, 'Noble and recording;', '(Mereka adalah makhluk) yang mulia (di sisi Allah), lagi ditugaskan menulis (amal-amal kamu);', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 2, NULL),
(82, 12, 'يَعْلَمُونَ مَا تَفْعَلُونَ', 'يعلمون ما تفعلون', NULL, 'They know whatever you do.', 'Mereka mengetahui apa yang kamu lakukan.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 13, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'ان الابرار لفي نعيم', NULL, 'Indeed, the righteous will be in pleasure,', '(Gunanya catitan malaikat-malaikat itu ialah: untuk menyatakan siapa yang berbakti dan siapa yang bersalah) - kerana sesungguhnya: orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada dalam Syurga yang penuh nikmat;', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 4, NULL),
(82, 14, 'وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍ', 'وان الفجار لفي جحيم', NULL, 'And indeed, the wicked will be in Hellfire.', 'Dan sesungguhnya orang-orang yang bersalah, bertempat dalam neraka yang menjulang-julang.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 4, NULL),
(82, 15, 'يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ', 'يصلونها يوم الدين', NULL, 'They will [enter to] burn therein on the Day of Recompense,', 'Mereka menderita bakaran neraka itu pada hari pembalasan,', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 3, NULL),
(82, 16, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ', 'وما هم عنها بغائبين', NULL, 'And never therefrom will they be absent.', 'Dan mereka (sentiasa berada dalam azab seksanya), tidak ghaib daripadanya.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 4, NULL),
(82, 17, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'وما ادراك ما يوم الدين', NULL, 'And what can make you know what is the Day of Recompense?', 'Dan apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 5, NULL),
(82, 18, 'ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'ثم ما ادراك ما يوم الدين', NULL, 'Then, what can make you know what is the Day of Recompense?', 'Sekali lagi, apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 6, NULL),
(82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍ لِّلَّهِ', 'يوم لا تملك نفس لنفس شيئا والامر يومئذ لله', NULL, 'It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allāh.', '(Hari itu ialah) hari seseorang tidak dapat memberikan pertolongan sedikitpun kepada orang lain, dan segala urusan pada hari itu tertentu bagi Allah.', FALSE, NULL, NULL, 587, 30, 235, 524, FALSE, 9, NULL),
(83, 1, 'وَيْلٌ لِّلْمُطَفِّفِينَ', 'ويل للمطففين', NULL, 'Woe to those who give less [than due],', 'Kecelakaan besar bagi orang-orang yang curang (dalam timbangan dan sukatan),', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 2, NULL),
(83, 2, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 'الذين اذا اكتالوا على الناس يستوفون', NULL, 'Who, when they take a measure from people, take in full.', 'Iaitu mereka yang apabila menerima sukatan (gantang cupak) dari orang lain mereka mengambilnya dengan cukup,', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 6, NULL),
(83, 3, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 'واذا كالوهم او وزنوهم يخسرون', NULL, 'But if they give by measure or by weight to them, they cause loss.', 'Dan (sebaliknya) apabila mereka menyukat atau menimbang untuk orang lain, mereka kurangi.', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 5, NULL),
(83, 4, 'أَلَا يَظُنُّ أُو۟لَـٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'الا يظن اولئك انهم مبعوثون', NULL, 'Do they not think that they will be resurrected', 'Tidakkah mereka menyangka bahawa mereka akan dibangkitkan (hidup semula sesudah mati)?', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 5, NULL),
(83, 5, 'لِيَوْمٍ عَظِيمٍ', 'ليوم عظيم', NULL, 'For a tremendous Day -', 'Pada hari (kiamat) yang amat besar (huru-haranya),', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 2, NULL),
(83, 6, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَـٰلَمِينَ', 'يوم يقوم الناس لرب العالمين', NULL, 'The Day when mankind will stand before the Lord of the worlds?', 'Hari berdiri manusia untuk mengadap Tuhan sekalian alam?', FALSE, NULL, NULL, 587, 30, 235, 525, FALSE, 5, NULL),
(83, 7, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍ', 'كلا ان كتاب الفجار لفي سجين', NULL, 'No! Indeed, the record of the wicked is in sijjeen.', 'Tidak sepatutnya (mereka melakukan perbuatan yang salah itu dan melalaikan hari akhirat)! Sesungguhnya “kitab suratan amal” orang-orang yang berdosa itu (didaftarkan) dalam “Sijjiin”.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 6, NULL),
(83, 8, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌ', 'وما ادراك ما سجين', NULL, 'And what can make you know what is sijjeen?', 'Dan apa jalannya engkau dapat mengetahui: apa dia “Sijjiin” itu,', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 4, NULL),
(83, 9, 'كِتَـٰبٌ مَّرْقُومٌ', 'كتاب مرقوم', NULL, 'It is [their destination recorded in] a register inscribed.', 'Ialah (tempat simpanan) kitab catitan yang jelas nyata, (yang menghimpunkan amalan orang-orang yang berdosa).', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 2, NULL),
(83, 10, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 'Woe, that Day, to the deniers,', 'Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan -', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 3, NULL),
(83, 11, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', 'الذين يكذبون بيوم الدين', NULL, 'Who deny the Day of Recompense.', 'Iaitu mereka yang mendustakan hari pembalasan.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 4, NULL),
(83, 12, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', 'وما يكذب به الا كل معتد اثيم', NULL, 'And none deny it except every sinful transgressor.', 'Dan tiada yang mendustakannya melainkan tiap-tiap orang yang melampaui batas (kebenaran), lagi amat derhaka!', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 7, NULL),
(83, 13, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', 'اذا تتلى عليه اياتنا قال اساطير الاولين', NULL, 'When Our verses are recited to him, he says, "Legends of the former peoples."', '(Sehingga) apabila ia dibacakan kepadanya ayat-ayat Kami, ia berkata: “Ini ialah dongeng orang-orang dahulu kala!”', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 7, NULL),
(83, 14, 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', 'كلا بل ران على قلوبهم ما كانوا يكسبون', NULL, 'No! Rather, the stain has covered their hearts of that which they were earning.', 'Sebenarnya! (Ayat-ayat Kami itu tidak ada cacatnya) bahkan mata hati mereka telah diselaputi kekotoran (dosa), dengan sebab (perbuatan kufur dan maksiat) yang mereka kerjakan.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 8, NULL),
(83, 15, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ', 'كلا انهم عن ربهم يومئذ لمحجوبون', NULL, 'No! Indeed, from their Lord, that Day, they will be partitioned.', 'Jangan lagi mereka berlaku demikian! (kalau tidak), mereka pada hari itu, tetap terdinding dari (rahmat) Tuhannya.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 6, NULL),
(83, 16, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 'ثم انهم لصالو الجحيم', NULL, 'Then indeed, they will [enter and] burn in Hellfire.', 'Kemudian, sesungguhnya mereka akan menderita bakaran neraka.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 4, NULL),
(83, 17, 'ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'ثم يقال هذا الذي كنتم به تكذبون', NULL, 'Then it will be said [to them], "This is what you used to deny."', 'Akhirnya dikatakan (kepada mereka): “Inilah dia (azab seksa) yang kamu dustakan dahulu.”', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 7, NULL),
(83, 18, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 'كلا ان كتاب الابرار لفي عليين', NULL, 'No! Indeed, the record of the righteous is in ʿilliyyūn.', 'Ingatlah wahai manusia! Sesungguhnya “kitab suratan amal” orang-orang yang berbakti (dengan taat dan amal kebajikan), adalah (didaftarkan) dalam” Illiyiin”.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 6, NULL),
(83, 19, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 'وما ادراك ما عليون', NULL, 'And what can make you know what is ʿilliyyūn?', 'Dan apa jalannya engkau dapat mengetahui, apa dia “Illiyiin” itu?', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 4, NULL),
(83, 20, 'كِتَـٰبٌ مَّرْقُومٌ', 'كتاب مرقوم', NULL, 'It is [their destination recorded in] a register inscribed', 'Ialah (tempat simpanan) kitab catitan yang jelas nyata,', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 2, NULL),
(83, 21, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 'يَشْهَدُهُ الْمُقَرَّبُونَ', NULL, 'Which is witnessed by those brought near [to Allāh].', 'Yang disaksikan oleh sekumpulan malaikat, yang didampingkan Tuhan di sisinya.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 22, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ', NULL, 'Indeed, the righteous will be in pleasure', 'Sesungguhnya orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada di dalam Syurga yang penuh nikmat:', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 23, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', NULL, 'On adorned couches, observing.', 'Mereka berehat di atas pelamin-pelamin (yang berhias), sambil melihat (segala keindahan dan kemuliaan yang disediakan untuk mereka di situ).', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 24, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 'تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ', NULL, 'You will recognize in their faces the radiance of pleasure.', 'Engkau dapat melihat pada muka mereka: cahaya nikmat yang mereka perolehi.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 25, 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', NULL, 'They will be given to drink [pure] wine [which was] sealed.', 'Mereka diberi minum dari satu minuman yang termeterai bekasnya,', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 26, 'خِتَٰمُهُۥ مِسْكٌ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ', 'خِتَامُهُ مِسْكٌ وَفِي ذَٰلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ', NULL, 'The last of it is musk. So for this let the competitors compete.', 'Meterainya kasturi; - dan untuk (memperolehi nikmat kesenangan) itu hendaknya berlumba-lumba mereka yang ingin merebut kelebihan dan kesenangan;', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 27, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'وَمِزَاجُهُ مِن تَسْنِيمٍ', NULL, 'And its mixture is of Tasneem,', 'Dan campuran minuman itu adalah dari “Tasnim”:', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 28, 'عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 'عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ', NULL, 'A spring from which those near [to Allāh] drink.', 'laitu matair yang diminum daripadanya oleh orang-orang yang di dampingkan (Tuhan di sisiNya).', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 29, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 'إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ', NULL, 'Indeed, those who committed crimes used to laugh at those who believed.', 'Sesungguhnya orang-orang yang derhaka, mereka selalu tertawakan orang-orang yang beriman.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 30, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 'وَإِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَ', NULL, 'And when they passed by them, they would exchange derisive glances.', 'Dan apabila orang-orang yang beriman lalu dekat mereka, mereka mengerling dan memejam celikkan mata sesama sendiri (mencemuhnya).', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 31, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 'وَإِذَا انقَلَبُوا إِلَىٰ أَهْلِهِمُ انقَلَبُوا فَكِهِينَ', NULL, 'And when they returned to their people, they would return jesting.', 'Dan apabila mereka kembali kepada kaum keluarganya, mereka kembali dengan riang gembira;', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 32, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 'وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَٰؤُلَاءِ لَضَالُّونَ', NULL, 'And when they saw them, they would say, "Indeed, those are truly lost."', 'Dan apabila mereka melihat orang-orang yang beriman, mereka berkata: “Sesungguhnya orang-orang itu adalah golongan yang sesat!”', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 33, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ', 'وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ', NULL, 'But they had not been sent as guardians over them.', 'Pada hal mereka tidak diutus untuk menjaga sesat atau tidaknya orang-orang yang beriman itu!', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 34, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 'فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ', NULL, 'So Today those who believed are laughing at the disbelievers,', 'Maka pada hari ini, orang-orang yang beriman pula tertawakan orang yang kafir itu.', FALSE, NULL, NULL, 588, 30, 235, 525, FALSE, 0, NULL),
(83, 35, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', NULL, 'On adorned couches, observing.', 'Sambil mereka berehat di atas pelamin-pelamin (yang berhias), serta melihat (hal yang berlaku kepada musuhnya).', FALSE, NULL, NULL, 589, 30, 235, 525, FALSE, 0, NULL),
(83, 36, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 'هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ', NULL, 'Have the disbelievers [not] been rewarded [this Day] for what they used to do?', '(Untuk menambahkan kegembiraan mereka, mereka ditanya): “Bukankah orang-orang yang kafir itu telah dibalas akan apa yang mereka telah kerjakan dahulu?”', FALSE, NULL, NULL, 589, 30, 235, 525, FALSE, 0, NULL),
(84, 1, 'إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 'اذا السماء انشقت', NULL, 'When the sky has split [open]', 'Apabila langit terbelah,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 2, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'واذنت لربها وحقت', NULL, 'And has listened [i.e., responded] to its Lord and was obligated [to do so]', 'Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh;', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 3, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 'واذا الارض مدت', NULL, 'And when the earth has been extended', 'Dan apabila bumi diratakan,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 4, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'والقت ما فيها وتخلت', NULL, 'And has cast out that within it and relinquished [it]', 'Serta mengeluarkan apa yang di dalamnya, dan menjadi kosong,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 4, NULL),
(84, 5, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'واذنت لربها وحقت', NULL, 'And has listened [i.e., responded] to its Lord and was obligated [to do so] –', 'Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh; - (Maka pada saat itu tiap-tiap seorang akan mengetahui apa yang telah dilakukannya).', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 6, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَـٰقِيهِ', 'يا ايها الانسان انك كادح الى ربك كدحا فملاقيه', NULL, 'O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.', 'Wahai manusia! Sesungguhnya engkau sentiasa berpenat-lelah (menjalankan keadaan hidupmu) dengan sedaya upayamu hinggalah (semasa engkau) kembali kepada Tuhanmu, kemudian engkau tetap menemui balasan apa yang engkau telah usahakan itu (tercatit semuanya).', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 8, NULL),
(84, 7, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ', 'فاما من اوتي كتابه بيمينه', NULL, 'Then as for he who is given his record in his right hand,', 'Kemudian sesiapa yang diberi menerima surat amalnya dengan tangan kanannya, -', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 5, NULL),
(84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', 'فسوف يحاسب حسابا يسيرا', NULL, 'He will be judged with an easy account', 'Maka ia akan dihisab dengan cara yang mudah dan ringan,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 4, NULL),
(84, 9, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا', 'وينقلب الى اهله مسرورا', NULL, 'And return to his people in happiness.', 'Dan ia akan pergi kepada keluarganya (yang beriman) dengan sukacita.', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 4, NULL),
(84, 10, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'واما من اوتي كتابه وراء ظهره', NULL, 'But as for he who is given his record behind his back,', 'Dan sesiapa yang diberi menerima surat amalnya (dengan tangan kiri), dari sebelah belakangnya,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 6, NULL),
(84, 11, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًا', 'فسوف يدعو ثبورا', NULL, 'He will cry out for destruction', 'Maka ia akan meraung menyebut-nyebut kebinasaannya,', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 12, 'وَيَصْلَىٰ سَعِيرًا', 'ويصلى سعيرا', NULL, 'And [enter to] burn in a Blaze.', 'Dan ia akan menderita bakaran neraka yang marak menjulang.', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 2, NULL),
(84, 13, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 'انه كان في اهله مسرورا', NULL, 'Indeed, he had [once] been among his people in happiness;', 'Sebenarnya ia semasa di dunia dahulu bersukaria dalam kalangan keluarganya (yang juga kufur ingkar)!', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 5, NULL),
(84, 14, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 'انه ظن ان لن يحور', NULL, 'Indeed, he had thought he would never return [to Allāh].', 'Sesungguhnya ia menyangka bahawa ia tidak sekali-kali akan kembali (kepada Kami untuk menerima balasan)!', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 5, NULL),
(84, 15, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا', 'بلى ان ربه كان به بصيرا', NULL, 'But yes! Indeed, his Lord was ever, of him, Seeing.', '(Sangkaannya itu tidak betul) bahkan ia tetap kembali! Sesungguhnya Tuhannya sentiasa Melihat dan Mengetahui keadaannya!', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 6, NULL),
(84, 16, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 'فلا اقسم بالشفق', NULL, 'So I swear by the twilight glow', 'Maka Aku bersumpah, demi mega;', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 17, 'وَٱلَّيْلِ وَمَا وَسَقَ', 'والليل وما وسق', NULL, 'And [by] the night and what it envelops', 'Dan malam serta segala yang dihimpunkannya;', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 18, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 'والقمر اذا اتسق', NULL, 'And [by] the moon when it becomes full', 'Dan bulan apabila (penuh cahayanya) menjadi purnama:', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 3, NULL),
(84, 19, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', 'لتركبن طبقا عن طبق', NULL, '[That] you will surely embark upon [i.e., experience] state after state.', 'Sesungguhnya kamu tetap melalui beberapa keadaan yang bertingkat-tingkat baik buruknya, (sebelum kamu menemui Tuhan - menerima kesenangan dan kebahagiaan atau sebaliknya)', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 4, NULL),
(84, 20, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'فما لهم لا يؤمنون', NULL, 'So what is [the matter] with them [that] they do not believe,', 'Maka apakah alasan bagi mereka bersikap tidak mahu beriman?', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 4, NULL),
(84, 21, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ', 'وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ', NULL, 'And when the Qur’ān is recited to them, they do not prostrate [to Allāh]?', 'Dan (apakah pula alasannya) apabila dibacakan Al-Quran kepada mereka, mereka tidak mahu taat dan sujud?', FALSE, NULL, NULL, 589, 30, 236, 526, TRUE, 0, NULL),
(84, 22, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 'بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ', NULL, 'But those who have disbelieved deny,', '(Tidak ada satu alasan pun) bahkan orang-orang yang kafir, semata-mata mendustakannya;', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 0, NULL),
(84, 23, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 'وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ', NULL, 'And Allāh is most knowing of what they keep within themselves.', 'Sedang Allah mengetahui apa yang mereka rahsiakan dalam hati.', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 0, NULL),
(84, 24, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', NULL, 'So give them tidings of a painful punishment,', 'Maka khabarkanlah kepada mereka dengan azab yang tidak terperi sakitnya;', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 0, NULL),
(84, 25, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', NULL, 'Except for those who believe and do righteous deeds. For them is a reward uninterrupted.', 'Tetapi orang-orang yang beriman dan beramal soleh mereka beroleh pahala balasan yang tidak putus-putus.', FALSE, NULL, NULL, 589, 30, 236, 526, FALSE, 0, NULL),
(85, 1, 'وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 'والسماء ذات البروج', NULL, 'By the sky containing great stars', 'Demi langit yang mempunyai tempat-tempat peredaran bintang-bintang;', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 2, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 'واليوم الموعود', NULL, 'And [by] the promised Day', 'Dan hari (pembalasan) yang dijanjikan;', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 2, NULL),
(85, 3, 'وَشَاهِدٍ وَمَشْهُودٍ', 'وشاهد ومشهود', NULL, 'And [by] the witness and what is witnessed,', 'Dan makhluk-makhluk yang hadir menyaksikan hari itu, serta segala keadaan yang disaksikan; -', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 2, NULL),
(85, 4, 'قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ', 'قتل اصحاب الاخدود', NULL, 'Destroyed [i.e., cursed] were the companions of the trench', 'Celakalah kaum yang menggali parit,', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 5, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 'النار ذات الوقود', NULL, '[Containing] the fire full of fuel,', '(Parit) api yang penuh dengan bahan bakaran,', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 6, 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', 'اذ هم عليها قعود', NULL, 'When they were sitting near it.', '(Mereka dilaknat) ketika mereka duduk di kelilingnya,', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 4, NULL),
(85, 7, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ', 'وهم على ما يفعلون بالمؤمنين شهود', NULL, 'And they, to what they were doing against the believers, were witnesses.', 'Sambil mereka melihat apa yang mereka lakukan kepada orang-orang yang beriman.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 6, NULL),
(85, 8, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'وما نقموا منهم الا ان يؤمنوا بالله العزيز الحميد', NULL, 'And they resented them not except because they believed in Allāh, the Exalted in Might, the Praiseworthy,', 'Dan mereka tidak marah dan menyeksakan orang-orang yang beriman itu melainkan kerana orang-orang itu beriman kepada Allah Yang Maha Kuasa, lagi Maha Terpuji!', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 9, NULL),
(85, 9, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'الذي له ملك السماوات والارض والله على كل شيء شهيد', NULL, 'To whom belongs the dominion of the heavens and the earth. And Allāh, over all things, is Witness.', 'Tuhan yang menguasai segala alam langit dan bumi. Dan (ingatlah), Allah sentiasa menyaksikan tiap-tiap sesuatu.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 10, NULL),
(85, 10, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 'ان الذين فتنوا المؤمنين والمؤمنات ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق', NULL, 'Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.', 'Sesungguhnya orang-orang yang menimpakan bencana untuk memesongkan orang-orang lelaki yang beriman dan orang-orang perempuan yang beriman, kemudian mereka tidak bertaubat, maka mereka akan beroleh azab neraka Jahannam (kerana perbuatan buruk itu), dan mereka akan beroleh lagi azab api yang kuat membakar (kerana mereka tidak bertaubat).', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 14, NULL),
(85, 11, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', 'ان الذين امنوا وعملوا الصالحات لهم جنات تجري من تحتها الانهار ذلك الفوز الكبير', NULL, 'Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.', 'Sesungguhnya orang-orang yang beriman dan beramal soleh, mereka akan beroleh Syurga yang mengalir di bawahnya beberapa sungai; yang demikian itu ialah kemenangan yang besar.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 14, NULL),
(85, 12, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 'ان بطش ربك لشديد', NULL, 'Indeed, the assault [i.e., vengeance] of your Lord is severe.', 'Sesungguhnya azab Tuhanmu (terhadap orang-orang yang kufur ingkar) amatlah berat.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 4, NULL),
(85, 13, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', 'انه هو يبدئ ويعيد', NULL, 'Indeed, it is He who originates [creation] and repeats.', 'Sesungguhnya Dia lah yang menciptakan (sekalian makhluk) pada mulanya, dan yang mengembalikannya (hidup semula sesudah mati).', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 4, NULL),
(85, 14, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', 'وهو الغفور الودود', NULL, 'And He is the Forgiving, the Affectionate,', 'Dan Dia lah yang Maha Pengampun, lagi Maha Pengasih.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 15, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', 'ذو العرش المجيد', NULL, 'Honorable Owner of the Throne,', 'Tuhan yang mempunyai Arasy yang tinggi kemuliaannya,', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 16, 'فَعَّالٌ لِّمَا يُرِيدُ', 'فعال لما يريد', NULL, 'Effecter of what He intends.', 'Yang berkuasa melakukan segala yang dikehendakinya.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 3, NULL),
(85, 17, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', 'هل اتاك حديث الجنود', NULL, 'Has there reached you the story of the soldiers -', 'Sudahkah sampai kepadamu (wahai Muhammad) perihal (kebinasaan yang telah menimpa) kaum-kaum yang menentang (Rasul-rasul yang diutuskan kepada mereka)?', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 4, NULL),
(85, 18, 'فِرْعَوْنَ وَثَمُودَ', 'فرعون وثمود', NULL, '[Those of] Pharaoh and Thamūd?', '(Mereka itu ialah kaum) Firaun, dan Thamud (kaum Nabi Soleh).', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 2, NULL),
(85, 19, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ', 'بل الذين كفروا في تكذيب', NULL, 'But they who disbelieve are in [persistent] denial,', '(Kaummu wahai Muhammad, bukan sahaja menolak ajaranmu), bahkan orang-orang yang kafir itu terus tenggelam dalam keadaan mendustakan kebenaran;', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 5, NULL),
(85, 20, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', 'والله من ورائهم محيط', NULL, 'While Allāh encompasses them from behind.', 'Sedang Allah, dari belakang mereka, melingkungi mereka (dengan kekuasaanNya)!', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 4, NULL),
(85, 21, 'بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ', 'بَلْ هُوَ قُرْآنٌ مَّجِيدٌ', NULL, 'But this is an honored Qur’ān', '(Sebenarnya apa yang engkau sampaikan kepada mereka bukanlah syair atau sihir), bahkan ialah Al-Quran yang tertinggi kemuliaannya;', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 0, NULL),
(85, 22, 'فِى لَوْحٍ مَّحْفُوظٍۭ', 'فِي لَوْحٍ مَّحْفُوظٍ', NULL, '[Inscribed] in a Preserved Slate.', '(Lagi yang terpelihara dengan sebaik-baiknya) pada Lauh Mahfuz.', FALSE, NULL, NULL, 590, 30, 236, 527, FALSE, 0, NULL),
(86, 1, 'وَٱلسَّمَآءِ وَٱلطَّارِقِ', 'والسماء والطارق', NULL, 'By the sky and the knocker', 'Demi langit dan “At-Taariq”; -', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 2, NULL),
(86, 2, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', 'وما ادراك ما الطارق', NULL, 'And what can make you know what is the knocker?', 'Dan apa jalannya engkau dapat mengetahui apa dia “At-Taariq” itu? -', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 4, NULL),
(86, 3, 'ٱلنَّجْمُ ٱلثَّاقِبُ', 'النجم الثاقب', NULL, 'It is the piercing star.', '(At-Taariq) ialah bintang yang menembusi (sinaran cahayanya);', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 2, NULL),
(86, 4, 'إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ', 'ان كل نفس لما عليها حافظ', NULL, 'There is no soul but that it has over it a protector.', 'Tiada sesuatu diri juapun melainkan ada malaikat yang menjaga (keadaannya serta menyimpan catitan mengenai segala bawaannya).', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 6, NULL),
(86, 5, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ', 'فلينظر الانسان مم خلق', NULL, 'So let man observe from what he was created.', '(Setelah mengetahui yang demikian), maka hendaklah manusia memikirkan: dari apa ia diciptakan.', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 4, NULL),
(86, 6, 'خُلِقَ مِن مَّآءٍ دَافِقٍ', 'خلق من ماء دافق', NULL, 'He was created from a fluid, ejected,', 'Ia diciptakan dari air (mani) yang memancut (ke dalam rahim) -', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 4, NULL),
(86, 7, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', 'يخرج من بين الصلب والترائب', NULL, 'Emerging from between the backbone and the ribs.', 'Yang keluar dari “tulang sulbi” lelaki dan “tulang dada” perempuan.', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 5, NULL),
(86, 8, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ', 'انه على رجعه لقادر', NULL, 'Indeed, He [i.e., Allāh], to return him [to life], is Able.', 'Sesungguhnya Allah Maha Kuasa untuk mengembalikannya (hidup semula sesudah mati),', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 4, NULL),
(86, 9, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', 'يوم تبلى السرائر', NULL, 'The Day when secrets will be put on trial,', 'Pada hari didedahkan segala yang terpendam di hati (dari iktiqad, niat, dan lain-lainnya),', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 10, 'فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ', 'فما له من قوة ولا ناصر', NULL, 'Then he [i.e., man] will have no power or any helper.', 'Maka (pada saat itu) tidak ada bagi manusia sebarang kekuatan (untuk membela diri), dan tidak ada penolong (yang dapat memberikan pertolongan).', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 6, NULL),
(86, 11, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', 'والسماء ذات الرجع', NULL, 'By the sky which sends back', 'Demi langit yang berulang-ulang mencurahkan hujan,', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 12, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', 'والارض ذات الصدع', NULL, 'And [by] the earth which splits,', 'Dan bumi yang merekah mengeluarkan tumbuh-tumbuhan,', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 13, 'إِنَّهُۥ لَقَوْلٌ فَصْلٌ', 'انه لقول فصل', NULL, 'Indeed, it [i.e., the Qur’ān] is a decisive statement,', 'Sesungguhnya keterangan Al-Quran adalah kata-kata pemutus (yang sebenar),', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 14, 'وَمَا هُوَ بِٱلْهَزْلِ', 'وما هو بالهزل', NULL, 'And it is not amusement.', 'Dan bukanlah ia kata-kata yang olok-olok.', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 15, 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', 'انهم يكيدون كيدا', NULL, 'Indeed, they are planning a plan,', 'Sesungguhnya mereka (yang menentangmu, wahai Muhammad) bermati-mati menjalankan rancangan jahat,', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 3, NULL),
(86, 16, 'وَأَكِيدُ كَيْدًا', 'واكيد كيدا', NULL, 'But I am planning a plan.', 'Dan Aku pula tetap bertindak membalas rancangan jahat (mereka, dan menggagalkannya).', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 2, NULL),
(86, 17, 'فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', 'فمهل الكافرين امهلهم رويدا', NULL, 'So allow time for the disbelievers. Leave them awhile.', 'Oleh itu janganlah engkau hendakkan segera kebinasaan orang-orang kafir itu, berilah tempoh kepada mereka sedikit masa.', FALSE, NULL, NULL, 591, 30, 236, 528, FALSE, 4, NULL),
(87, 1, 'سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', 'سبح اسم ربك الاعلى', NULL, 'Exalt the name of your Lord, the Most High,', 'Bertasbihlah mensucikan nama Tuhanmu Yang Maha Tinggi (dari segala sifat-sifat kekurangan), -', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 4, NULL),
(87, 2, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', 'الذي خلق فسوى', NULL, 'Who created and proportioned', 'Yang telah menciptakan (sekalian makhlukNya) serta menyempurnakan kejadiannya dengan kelengkapan yang sesuai dengan keadaannya;', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 3, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', 'والذي قدر فهدى', NULL, 'And who destined and [then] guided', 'Dan Yang telah mengatur (keadaan makhluk-makhlukNya) serta memberikan hidayah petunjuk (ke jalan keselamatannya dan kesempurnaannya);', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 4, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', 'والذي اخرج المرعى', NULL, 'And who brings out the pasture', 'Dan Yang telah mengeluarkan tumbuh-tumbuhan untuk binatang-binatang ternak,', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 5, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', 'فجعله غثاء احوى', NULL, 'And [then] makes it black stubble.', 'Kemudian Ia menjadikan (tumbuh-tumbuhan yang menghijau) itu kering - (berubah warnanya) kehitam-hitaman.', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 6, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', 'سنقرئك فلا تنسى', NULL, 'We will make you recite, [O Muḥammad], and you will not forget,', 'Kami sentiasa menjadikan engkau (wahai Muhammad) dapat membaca (Al-Quran yang diturunkan kepadamu - dengan perantaraan jibril), sehingga engkau (menghafaznya dan) tidak lupa,', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 7, 'إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', 'الا ما شاء الله انه يعلم الجهر وما يخفى', NULL, 'Except what Allāh should will. Indeed, He knows what is declared and what is hidden.', 'Kecuali apa yang dikehendaki Allah engkau lupakan; sesungguhnya Ia mengetahui (segala keadaan yang patut berlaku), dan yang tersembunyi.', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 9, NULL),
(87, 8, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 'ونيسرك لليسرى', NULL, 'And We will ease you toward ease.', 'Dan Kami tetap memberi kemudahan kepadamu untuk (melaksanakan segala perkara) Ugama yang mudah diterima oleh akal yang sihat.', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 2, NULL),
(87, 9, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', 'فذكر ان نفعت الذكرى', NULL, 'So remind, if the reminder should benefit;', 'Oleh itu berilah peringatan (kepada umat manusia dengan ajaran Al-Quran), kalau-kalau peringatan itu berguna (dan sudah tentu berguna);', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 4, NULL),
(87, 10, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', 'سيذكر من يخشى', NULL, 'He who fears [Allāh] will be reminded.', 'Kerana orang yang takut (melanggar perintah Allah) akan menerima peringatan itu;', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 3, NULL),
(87, 11, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', 'ويتجنبها الاشقى', NULL, 'But the wretched one will avoid it –', 'Dan (sebaliknya) orang yang sangat celaka akan menjauhinya,', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 2, NULL),
(87, 12, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', 'الذي يصلى النار الكبرى', NULL, '[He] who will [enter and] burn in the greatest Fire,', 'Dia lah orang yang akan menderita bakaran neraka yang amat besar (azab seksanya),', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 4, NULL),
(87, 13, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'ثم لا يموت فيها ولا يحيى', NULL, 'Neither dying therein nor living.', 'Selain dari itu, ia tidak mati di dalamnya dan tidak pula hidup senang.', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 6, NULL),
(87, 14, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', 'قد افلح من تزكى', NULL, 'He has certainly succeeded who purifies himself', 'Sesungguhnya berjayalah orang yang - setelah menerima peringatan itu - berusaha membersihkan dirinya (dengan taat dan amal yang soleh),', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 4, NULL),
(87, 15, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', 'وذكر اسم ربه فصلى', NULL, 'And mentions the name of his Lord and prays.', 'Dan menyebut-nyebut dengan lidah dan hatinya akan nama Tuhannya serta mangerjakan sembahyang (dengan khusyuk).', FALSE, NULL, NULL, 591, 30, 237, 529, FALSE, 4, NULL),
(87, 16, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'بل تؤثرون الحياة الدنيا', NULL, 'But you prefer the worldly life,', '(Tetapi kebanyakkan kamu tidak melakukan yang demikian), bahkan kamu utamakan kehidupan dunia;', FALSE, NULL, NULL, 592, 30, 237, 529, FALSE, 4, NULL),
(87, 17, 'وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ', 'والاخرة خير وابقى', NULL, 'While the Hereafter is better and more enduring.', 'Padahal kehidupan akhirat lebih baik dan lebih kekal.', FALSE, NULL, NULL, 592, 30, 237, 529, FALSE, 3, NULL),
(87, 18, 'إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'ان هذا لفي الصحف الاولى', NULL, 'Indeed, this is in the former scriptures,', 'Sesungguhnya (keterangan-keterangan yang dinyatakan) ini ada (disebutkan) di dalam Kitab-kitab yang terdahulu, -', FALSE, NULL, NULL, 592, 30, 237, 529, FALSE, 5, NULL),
(87, 19, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', 'صحف ابراهيم وموسى', NULL, 'The scriptures of Abraham and Moses.', 'Iaitu Kitab-kitab Nabi Ibrahim dan Nabi Musa.', FALSE, NULL, NULL, 592, 30, 237, 529, FALSE, 3, NULL),
(88, 1, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ', 'هل اتاك حديث الغاشية', NULL, 'Has there reached you the report of the Overwhelming [event]?', 'Sudahkah sampai kepadamu (wahai Muhammad) perihal hari kiamat yang huru-haranya meliputi?', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 2, 'وُجُوهٌ يَوْمَئِذٍ خَـٰشِعَةٌ', 'وجوه يومئذ خاشعة', NULL, '[Some] faces, that Day, will be humbled,', 'Muka (orang-orang yang kafir) pada hari itu tunduk kerana merasa hina,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 3, 'عَامِلَةٌ نَّاصِبَةٌ', 'عاملة ناصبة', NULL, 'Working [hard] and exhausted.', 'Mereka menjalankan kerja yang berat lagi berpenat lelah,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 2, NULL),
(88, 4, 'تَصْلَىٰ نَارًا حَامِيَةً', 'تصلى نارا حامية', NULL, 'They will [enter to] burn in an intensely hot Fire.', 'Mereka tetap menderita bakaran neraka yang amat panas (membakar), -', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 5, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ', 'تسقى من عين انية', NULL, 'They will be given drink from a boiling spring.', 'Mereka diberi minum dari matair yang menggelegak panasnya.', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 6, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ', 'ليس لهم طعام الا من ضريع', NULL, 'For them there will be no food except from a poisonous, thorny plant', 'Tiada makanan bagi mereka (di situ) selain dari pokok-pokok yang berduri,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 6, NULL),
(88, 7, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ', 'لا يسمن ولا يغني من جوع', NULL, 'Which neither nourishes nor avails against hunger.', 'Yang tidak menggemokkan, dan tidak pula dapat menghilangkan sedikit kelaparan pun.', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 6, NULL),
(88, 8, 'وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ', 'وجوه يومئذ ناعمة', NULL, '[Other] faces, that Day, will show pleasure.', '(Sebaliknya) muka (orang-orang yang beriman) pada hari itu berseri-seri,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 9, 'لِّسَعْيِهَا رَاضِيَةٌ', 'لسعيها راضية', NULL, 'With their effort [they are] satisfied', 'Berpuas hati dengan balasan amal usahanya (yang baik yang telah dikerjakannya di dunia), -', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 2, NULL),
(88, 10, 'فِى جَنَّةٍ عَالِيَةٍ', 'في جنة عالية', NULL, 'In an elevated garden,', '(Mereka tinggal menetap) di dalam Syurga tinggi (tempat kedudukannya darjatnya),', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 11, 'لَّا تَسْمَعُ فِيهَا لَـٰغِيَةً', 'لا تسمع فيها لاغية', NULL, 'Wherein they will hear no unsuitable speech.', 'Mereka tidak mendengar di situ sebarang perkataan yang sia-sia,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 12, 'فِيهَا عَيْنٌ جَارِيَةٌ', 'فيها عين جارية', NULL, 'Within it is a flowing spring.', 'Di dalam Syurga itu ada matair yang mengalir,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 13, 'فِيهَا سُرُرٌ مَّرْفُوعَةٌ', 'فيها سرر مرفوعة', NULL, 'Within it are couches raised high', 'Di situ juga ada pelamin-pelamin (berhias) yang tinggi (tempatnya),', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 3, NULL),
(88, 14, 'وَأَكْوَابٌ مَّوْضُوعَةٌ', 'واكواب موضوعة', NULL, 'And cups put in place', 'Dan piala-piala minuman yang disediakan (untuk mereka),', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 2, NULL),
(88, 15, 'وَنَمَارِقُ مَصْفُوفَةٌ', 'ونمارق مصفوفة', NULL, 'And cushions lined up', 'Dan bantal-bantal yang teratur (untuk mereka berbaring atau bersandar),', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 2, NULL),
(88, 16, 'وَزَرَابِىُّ مَبْثُوثَةٌ', 'وزرابي مبثوثة', NULL, 'And carpets spread around.', 'Serta hamparan-hamparan yang terbentang.', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 2, NULL),
(88, 17, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', 'افلا ينظرون الى الابل كيف خلقت', NULL, 'Then do they not look at the camels - how they are created?', '(Mengapa mereka yang kafir masih mengingkari akhirat) tidakkah mereka memperhatikan keadaan unta bagaimana ia diciptakan?', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 6, NULL),
(88, 18, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', 'والى السماء كيف رفعت', NULL, 'And at the sky - how it is raised?', 'Dan keadaan langit bagaimana ia ditinggikan binaannya.?', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 19, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', 'والى الجبال كيف نصبت', NULL, 'And at the mountains - how they are erected?', 'Dan keadaan gunung-ganang bagaimana ia ditegakkan?', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 20, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', 'والى الارض كيف سطحت', NULL, 'And at the earth - how it is spread out?', 'Dan keadaan bumi bagaimana ia dihamparkan?', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 4, NULL),
(88, 21, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ', 'فَذَكِّرْ إِنَّمَا أَنتَ مُذَكِّرٌ', NULL, 'So remind, [O Muḥammad]; you are only a reminder.', 'Oleh itu berikanlah sahaja peringatan (wahai Muhammad, kepada manusia, dan janganlah berdukacita kiranya ada yang menolaknya), kerana sesungguhnya engkau hanyalah seorang Rasul pemberi ingatan;', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(88, 22, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', NULL, 'You are not over them a controller.', 'Bukanlah engkau seorang yang berkuasa memaksa mereka (menerima ajaran Islam yang engkau sampaikan itu).', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(88, 23, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', NULL, 'However, he who turns away and disbelieves –', 'Akan tetapi sesiapa yang berpaling (dari kebenaran) serta ia kufur ingkar, -', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(88, 24, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', 'فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ', NULL, 'Then Allāh will punish him with the greatest punishment.', 'Maka Allah akan menyeksanya dengan azab seksa yang sebesar-besarnya.', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(88, 25, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 'إِنَّ إِلَيْنَا إِيَابَهُمْ', NULL, 'Indeed, to Us is their return.', 'Sesungguhnya kepada Kamilah kembalinya mereka,', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(88, 26, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', NULL, 'Then indeed, upon Us is their account.', 'Selain dari itu, sesungguhnya tanggungan Kamilah soal menghitung amal mereka.', FALSE, NULL, NULL, 592, 30, 237, 530, FALSE, 0, NULL),
(89, 1, 'وَٱلْفَجْرِ', 'والفجر', NULL, 'By the dawn', 'Demi waktu fajar;', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 1, NULL),
(89, 2, 'وَلَيَالٍ عَشْرٍ', 'وليال عشر', NULL, 'And [by] ten nights', 'Dan malam yang sepuluh (yang mempunyai kelebihan di sisi Allah);', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 2, NULL),
(89, 3, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', 'والشفع والوتر', NULL, 'And [by] the even [number] and the odd', 'Dan bilangan yang genap serta yang ganjil;', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 2, NULL),
(89, 4, 'وَٱلَّيْلِ إِذَا يَسْرِ', 'والليل اذا يسر', NULL, 'And [by] the night when it passes,', 'Dan malam, apabila ia berlalu; -', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 3, NULL),
(89, 5, 'هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ', 'هل في ذلك قسم لذي حجر', NULL, 'Is there [not] in [all] that an oath [sufficient] for one of perception?', 'Bukankah yang demikian itu mengandungi sumpah (yang diakui kebenarannya) oleh orang yang berakal sempurna?', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 6, NULL),
(89, 6, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'الم تر كيف فعل ربك بعاد', NULL, 'Have you not considered how your Lord dealt with ʿAad -', '(Kami tetap akan membinasakan orang-orang yang menentangmu wahai Muhammad), tidakkah engkau perhatikan, bagaimana Tuhanmu telah melakukan terhadap kaum Aad (yang kufur derhaka)', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 6, NULL),
(89, 7, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 'ارم ذات العماد', NULL, '[With] Iram - who had lofty pillars,', 'Iaitu penduduk “Iram” yang mempunyai bangunan-bangunan yang tinggi tiangnya, (sesuai dengan penduduknya)', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 3, NULL);
INSERT INTO ayat (surah_id, ayah_number, text_uthmani, text_simple, translation_id, translation_en, display_bm, bm_flagged, bm_resolution_notes, bm_correction_note, page_number, juz_number, hizb_number, ruku_number, sajdah, word_count, audio_url) VALUES
(89, 8, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ', 'التي لم يخلق مثلها في البلاد', NULL, 'The likes of whom had never been created in the land?', 'Yang belum pernah diciptakan sepertinya (tentang besar dan kukuhnya) di segala negeri (pada zamannya)?', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 6, NULL),
(89, 9, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 'وثمود الذين جابوا الصخر بالواد', NULL, 'And [with] Thamūd, who carved out the rocks in the valley?', 'Dan (terhadap) kaum Thamud yang memahat batu-batu besar di lembah (Wadil-Qura iaitu tempat tinggalnya)?', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 5, NULL),
(89, 10, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 'وفرعون ذي الاوتاد', NULL, 'And [with] Pharaoh, owner of the stakes?', 'Dan (terhadap) Firaun yang menguasai bangunan-bangunan yang handal kukuh?', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 3, NULL),
(89, 11, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ', 'الذين طغوا في البلاد', NULL, '[All of] whom oppressed within the lands', '(Semuanya itu ialah) orang-orang yang telah bermaharajalela di negeri (masing-masing).', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 4, NULL),
(89, 12, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 'فاكثروا فيها الفساد', NULL, 'And increased therein the corruption.', 'Lalu mereka melakukan dengan banyaknya kerosakan dan bencana di negeri-negeri itu.', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 3, NULL),
(89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 'فصب عليهم ربك سوط عذاب', NULL, 'So your Lord poured upon them a scourge of punishment.', 'Dengan yang demikian, Tuhanmu mencurahkan ke atas mereka berbagai paluan azab;', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 5, NULL),
(89, 14, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 'ان ربك لبالمرصاد', NULL, 'Indeed, your Lord is in observation.', 'Sesungguhnya Tuhanmu tetap mengawas dan membalas, (terutama balasan akhirat)', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 3, NULL),
(89, 15, 'فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 'فاما الانسان اذا ما ابتلاه ربه فاكرمه ونعمه فيقول ربي اكرمن', NULL, 'And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, "My Lord has honored me."', '(Dalam pada itu manusia tidak menghiraukan balasan akhirat), oleh yang demikian, maka kebanyakan manusia apabila diuji oleh Tuhannya dengan dimuliakan dan dimewahkan hidupnya, (ia tidak mahu bersyukur tetapi terus bersikap takbur) serta berkata dengan sombongnya: “Tuhanku telah memuliakan daku!”', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 11, NULL),
(89, 16, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ', 'واما اذا ما ابتلاه فقدر عليه رزقه فيقول ربي اهانن', NULL, 'But when He tries him and restricts his provision, he says, "My Lord has humiliated me."', 'Dan sebaliknya apabila ia diuji oleh Tuhannya, dengan disempitkan rezekinya, (ia tidak bersabar bahkan ia resah gelisah) serta merepek dengan katanya: “Tuhanku telah menghinakan daku!”', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 10, NULL),
(89, 17, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 'كلا بل لا تكرمون اليتيم', NULL, 'No! But you do not honor the orphan', 'Jangan demikian, (sebenarnya kata-kata kamu itu salah). Bahkan (perbuatan kamu wahai orang-orang yang hidup mewah, lebih salah lagi kerana) kamu tidak memuliakan anak yatim, (malah kamu menahan apa yang Ia berhak menerimanya);', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 5, NULL),
(89, 18, 'وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'ولا تحاضون على طعام المسكين', NULL, 'And you do not encourage one another to feed the poor.', 'Dan kamu tidak menggalakkan untuk memberi makanan (yang berhak diterima oleh) orang miskin;', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 5, NULL),
(89, 19, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا', 'وتاكلون التراث اكلا لما', NULL, 'And you consume inheritance, devouring [it] altogether,', 'Dan kamu sentiasa makan harta pusaka secara rakus (dengan tidak membezakan halal haramnya),', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 4, NULL),
(89, 20, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا', 'وتحبون المال حبا جما', NULL, 'And you love wealth with immense love.', 'Serta kamu pula sayangkan harta secara tamak haloba!', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 4, NULL),
(89, 21, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', 'كَلَّا إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا', NULL, 'No! When the earth has been leveled - pounded and crushed', 'Jangan sekali-kali bersikap demikian! (Sebenarnya) apabila bumi (dihancurkan segala yang ada di atasnya dan) diratakan serata-ratanya,', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 0, NULL),
(89, 22, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا', 'وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا', NULL, 'And your Lord has come and the angels, rank upon rank,', 'Dan (perintah) Tuhanmu pun datang, sedang malaikat berbaris-baris (siap sedia menjalankan perintah),', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 0, NULL),
(89, 23, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 'وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنسَانُ وَأَنَّىٰ لَهُ الذِّكْرَىٰ', NULL, 'And brought [within view], that Day, is Hell - that Day, man will remember, but how [i.e., what good] to him will be the remembrance?', 'Serta diperlihatkan neraka Jahannam pada hari itu, (maka) pada saat itu manusia akan ingat (hendak berlaku baik), dan bagaimana ingatan itu akan berguna lagi kepadanya?', FALSE, NULL, NULL, 593, 30, 237, 531, FALSE, 0, NULL),
(89, 24, 'يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 'يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي', NULL, 'He will say, "Oh, I wish I had sent ahead [some good] for my life."', 'Ia akan berkata: “Alangkah baiknya kalau aku dahulu sediakan amal-amal baik untuk hidupku (di sini)!”', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 25, 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ', 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُ أَحَدٌ', NULL, 'So on that Day, none will punish [as severely] as His punishment,', 'Maka pada hari itu tiada sesiapapun yang dapat menyeksa seperti azab (yang ditimpakan oleh) Allah.', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 26, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ', 'وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ', NULL, 'And none will bind [as severely] as His binding [of the evildoers].', 'Dan tiada sesiapapun yang dapat mengikat serta membelenggu seperti ikatan dan belengguNya.', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 27, 'يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 'يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ', NULL, '[To the righteous it will be said], "O reassured soul,', '(Setelah menerangkan akibat orang-orang yang tidak menghiraukan akhirat, Tuhan menyatakan bahawa orang-orang yang beriman dan beramal soleh akan disambut dengan kata-kata): “Wahai orang yang mempunyai jiwa yang sentiasa tenang tetap dengan kepercayaan dan bawaan baiknya! -', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 28, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', 'ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', NULL, 'Return to your Lord, well-pleased and pleasing [to Him],', '“Kembalilah kepada Tuhanmu dengan keadaan engkau berpuas hati (dengan segala nikmat yang diberikan) lagi diredhai (di sisi Tuhanmu)! -', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 29, 'فَٱدْخُلِى فِى عِبَٰدِى', 'فَادْخُلِي فِي عِبَادِي', NULL, 'And enter among My [righteous] servants', '“Serta masuklah engkau dalam kumpulan hamba-hambaku yang berbahagia -', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(89, 30, 'وَٱدْخُلِى جَنَّتِى', 'وَادْخُلِي جَنَّتِي', NULL, 'And enter My Paradise."', '“Dan masuklah ke dalam SyurgaKu!”', FALSE, NULL, NULL, 594, 30, 237, 531, FALSE, 0, NULL),
(90, 1, 'لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ', 'لا اقسم بهذا البلد', NULL, 'I swear by this city [i.e., Makkah] –', 'Aku bersumpah dengan negeri (Makkah) ini;', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 2, 'وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ', 'وانت حل بهذا البلد', NULL, 'And you, [O Muḥammad], are free of restriction in this city –', 'Sedang engkau (wahai Muhammad) tinggal di negeri ini (sentiasa ditindas),', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 3, 'وَوَالِدٍ وَمَا وَلَدَ', 'ووالد وما ولد', NULL, 'And [by] the father and that which was born [of him],', 'Demi manusia yang melahirkan zuriat, dan zuriat yang dilahirkannya;', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 3, NULL),
(90, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ', 'لقد خلقنا الانسان في كبد', NULL, 'We have certainly created man into hardship.', 'Sesungguhnya Kami telah jadikan manusia sentiasa dalam keadaan menghadapi kesulitan dan kesukaran (jasmani dan rohaninya);', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 5, NULL),
(90, 5, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 'ايحسب ان لن يقدر عليه احد', NULL, 'Does he think that never will anyone overcome him?', 'Patutkah manusia yang demikian keadaannya (terpedaya dengan kekuasaan yang ada padanya dan) menyangka bahawa tidak ada sesiapapun yang dapat mengatasi kekuasaannya (dan menyeksakannya)?', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 6, NULL),
(90, 6, 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', 'يقول اهلكت مالا لبدا', NULL, 'He says, "I have spent wealth in abundance."', 'Manusia yang demikian keadaannya (tidaklah patut ia bermegah-megah dengan kekayaannya dan) berkata: “Aku telah habiskan harta benda yang banyak (dalam usaha menegakkan nama dan bangsa).', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 7, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 'ايحسب ان لم يره احد', NULL, 'Does he think that no one has seen him?', 'Adakah ia menyangka bahawa tidak ada sesiapapun yang melihatnya (dan mengetahui tujuannya menghabiskan harta bendanya itu?', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 5, NULL),
(90, 8, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'الم نجعل له عينين', NULL, 'Have We not made for him two eyes?', '(Mengapa manusia terpedaya dan bermegah-megah?) Tidakkah Kami telah menjadikan baginya: dua mata (untuk ia memerhatikan kekuasaan dan kekayaan Kami?) -', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 9, 'وَلِسَانًا وَشَفَتَيْنِ', 'ولسانا وشفتين', NULL, 'And a tongue and two lips?', 'Dan lidah serta dua bibir (untuk ia menyempurnakan sebahagian besar dari hajat-hajatnya)?', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 2, NULL),
(90, 10, 'وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ', 'وهديناه النجدين', NULL, 'And have shown him the two ways?', 'Dan Kami telah menunjukkan kepadanya dua jalan, (jalan kebaikan untuk dijalaninya, dan jalan kejahatan untuk dijauhi)?', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 2, NULL),
(90, 11, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 'فلا اقتحم العقبة', NULL, 'But he has not broken through the difficult pass.', 'Dalam pada itu manusia tidak (memilih jalan kebaikan) merempuh masuk mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan;', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 3, NULL),
(90, 12, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 'وما ادراك ما العقبة', NULL, 'And what can make you know what is [breaking through] the difficult pass?', 'Dan apa jalannya engkau dapat mengetahui: apa dia amal-amal yang tinggi darjatnya di sisi Tuhan itu?', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 13, 'فَكُّ رَقَبَةٍ', 'فك رقبة', NULL, 'It is the freeing of a slave', '(Di antara amal-amal itu - bagi orang yang mampu) ialah: memerdekakan hamba abdi;', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 2, NULL),
(90, 14, 'أَوْ إِطْعَـٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ', 'او اطعام في يوم ذي مسغبة', NULL, 'Or feeding on a day of severe hunger', 'Atau memberi makan pada hari kelaparan -', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 6, NULL),
(90, 15, 'يَتِيمًا ذَا مَقْرَبَةٍ', 'يتيما ذا مقربة', NULL, 'An orphan of near relationship', 'Kepada anak yatim dari kaum kerabat,', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 3, NULL),
(90, 16, 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', 'او مسكينا ذا متربة', NULL, 'Or a needy person in misery', 'Atau kepada orang miskin yang terlantar di atas tanah.', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 4, NULL),
(90, 17, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 'ثم كان من الذين امنوا وتواصوا بالصبر وتواصوا بالمرحمة', NULL, 'And then being among those who believed and advised one another to patience and advised one another to compassion.', 'Selain dari (tidak mengerjakan amal-amal) itu, ia (tidak pula) menjadi dari orang-orang yang beriman dan berpesan-pesan dengan sabar serta berpesan-pesan dengan kasih sayang.', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 9, NULL),
(90, 18, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 'اولئك اصحاب الميمنة', NULL, 'Those are the companions of the right.', '(Ketahuilah! Bahawa orang-orang yang beriman serta berusaha mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan), merekalah golongan pihak kanan (yang akan beroleh Syurga).', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 3, NULL),
(90, 19, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 'والذين كفروا باياتنا هم اصحاب المشامة', NULL, 'But they who disbelieved in Our signs - those are the companions of the left.', 'Dan (sebaliknya) orang-orang yang kufur ingkar akan ayat-ayat keterangan Kami, merekalah golongan pihak kiri. -', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 6, NULL),
(90, 20, 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ', 'عليهم نار مؤصدة', NULL, 'Over them will be fire closed in.', 'Mereka ditimpakan (azab seksa) neraka yang ditutup rapat (supaya kuat bakarannya).', FALSE, NULL, NULL, 594, 30, 238, 532, FALSE, 3, NULL),
(91, 1, 'وَٱلشَّمْسِ وَضُحَىٰهَا', 'والشمس وضحاها', NULL, 'By the sun and its brightness', 'Demi matahari dan cahayanya yang terang-benderang;', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 2, NULL),
(91, 2, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 'والقمر اذا تلاها', NULL, 'And [by] the moon when it follows it', 'Dan bulan apabila ia mengiringinya;', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 3, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 'والنهار اذا جلاها', NULL, 'And [by] the day when it displays it', 'Dan siang apabila ia memperlihatkannya dengan jelas nyata;', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 4, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 'والليل اذا يغشاها', NULL, 'And [by] the night when it covers [i.e., conceals] it', 'Dan malam apabila ia menyelubunginya (dengan gelap- gelita),', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 5, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 'والسماء وما بناها', NULL, 'And [by] the sky and He who constructed it', 'Demi langit dan Yang membinanya (dalam bentuk yang kuat kukuh - yang melambangkan kekuasaanNya);', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 6, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 'والارض وما طحاها', NULL, 'And [by] the earth and He who spread it', 'Serta bumi dan Yang menghamparkannya (untuk kemudahan makhluk-makhlukNya);', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 7, 'وَنَفْسٍ وَمَا سَوَّىٰهَا', 'ونفس وما سواها', NULL, 'And [by] the soul and He who proportioned it', 'Demi diri manusia dan Yang menyempurnakan kejadiannya (dengan kelengkapan yang sesuai dengan keadaannya);', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 8, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 'فالهمها فجورها وتقواها', NULL, 'And inspired it [with discernment of] its wickedness and its righteousness,', 'Serta mengilhamkannya (untuk mengenal) jalan yang membawanya kepada kejahatan, dan yang membawanya kepada bertaqwa; -', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 9, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 'قد افلح من زكاها', NULL, 'He has succeeded who purifies it,', 'Sesungguhnya berjayalah orang yang menjadikan dirinya - yang sedia bersih - bertambah-tambah bersih (dengan iman dan amal kebajikan),', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 4, NULL),
(91, 10, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 'وقد خاب من دساها', NULL, 'And he has failed who instills it [with corruption].', 'Dan sesungguhnya hampalah orang yang menjadikan dirinya - yang sedia bersih - itu susut dan terbenam kebersihannya (dengan sebab kekotoran maksiat).', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 4, NULL),
(91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 'كذبت ثمود بطغواها', NULL, 'Thamūd denied [their prophet] by reason of their transgression,', '(Ingatlah), kaum Thamud telah mendustakan (Rasulnya) dengan sebab perbuatan derhaka mereka yang melampaui batas;', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 12, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 'اذ انبعث اشقاها', NULL, 'When the most wretched of them was sent forth.', 'Ketika orang yang paling jahat di antara mereka menerima perintah dari mereka (supaya membunuh unta yang menjadi mukjizat),', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(91, 13, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا', 'فقال لهم رسول الله ناقة الله وسقياها', NULL, 'And the messenger of Allāh [i.e., Ṣāliḥ] said to them, "[Do not harm] the she-camel of Allāh or [prevent her from] her drink."', 'Maka berkatalah Rasul Allah (Nabi Soleh) kepada mereka: “(Janganlah kamu ganggu) unta betina dari Allah itu, dan (janganlah kamu menyekatnya daripada mendapat) air minumnya (supaya kamu tidak ditimpa azab)!”', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 7, NULL),
(91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسواها', NULL, 'But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].', '(Setelah Nabi Soleh memberi amaran) lalu mereka mendustakannya serta menyembelih unta itu. Dengan sebab dosa mereka, maka Tuhan menimpakan mereka dengan azab yang membinasakan serta Ia meratakan azab itu meliputi mereka (sehingga punah-ranah semuanya).', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 7, NULL),
(91, 15, 'وَلَا يَخَافُ عُقْبَـٰهَا', 'ولا يخاف عقباها', NULL, 'And He does not fear the consequence thereof.', 'Dan Allah tidak hiraukan kesudahan (mereka) yang demikian, (kerana itu adalah balasan yang adil).', FALSE, NULL, NULL, 595, 30, 238, 533, FALSE, 3, NULL),
(92, 1, 'وَٱلَّيْلِ إِذَا يَغْشَىٰ', 'والليل اذا يغشى', NULL, 'By the night when it covers', 'Demi malam apabila ia menyelubungi segala-galanya (dengan gelap-gelitanya),', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 3, NULL),
(92, 2, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 'والنهار اذا تجلى', NULL, 'And [by] the day when it appears', 'Dan siang apabila ia lahir terang-benderang;', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 3, NULL),
(92, 3, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'وما خلق الذكر والانثى', NULL, 'And [by] He who created the male and female,', 'Demi Yang menciptakan (makhluk-makhlukNya) lelaki dan perempuan, (jantan dan betina); -', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 4, NULL),
(92, 4, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'ان سعيكم لشتى', NULL, 'Indeed, your efforts are diverse.', 'Sesungguhnya amal usaha kamu adalah berbagai-bagai keadaannya.', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 3, NULL),
(92, 5, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 'فاما من اعطى واتقى', NULL, 'As for he who gives and fears Allāh', 'Jelasnya: adapun orang yang memberikan apa yang ada padanya ke jalan kebaikan dan bertaqwa (mengerjakan suruhan Allah dan meninggalkan segala laranganNya), -', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 4, NULL),
(92, 6, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 'وصدق بالحسنى', NULL, 'And believes in the best [reward].', 'Serta ia mengakui dengan yakin akan perkara yang baik,', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 2, NULL),
(92, 7, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 'فسنيسره لليسرى', NULL, 'We will ease him toward ease.', 'Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesenangan (Syurga).', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 2, NULL),
(92, 8, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 'واما من بخل واستغنى', NULL, 'But as for he who withholds and considers himself free of need', 'Sebaliknya: orang yang bakhil (daripada berbuat kebajikan) dan merasa cukup dengan kekayaan dan kemewahannya, -', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 4, NULL),
(92, 9, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', 'وكذب بالحسنى', NULL, 'And denies the best [reward],', 'Serta ia mendustakan perkara yang baik,', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 2, NULL),
(92, 10, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', 'فسنيسره للعسرى', NULL, 'We will ease him toward difficulty.', 'Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesusahan dan kesengsaraan;', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 2, NULL),
(92, 11, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', 'وما يغني عنه ماله اذا تردى', NULL, 'And what will his wealth avail him when he falls?', 'Dan apakah pertolongan yang dapat diberi kepadanya oleh hartanya apabiha ia telah terjerumus (ke dalam azab seksa hari akhirat)?', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 6, NULL),
(92, 12, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 'ان علينا للهدى', NULL, 'Indeed, [incumbent] upon Us is guidance.', 'Sesungguhnya tanggungan Kamilah memberi hidayah petunjuk (tentang yang benar dan yang salah).', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 3, NULL),
(92, 13, 'وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ', 'وان لنا للاخرة والاولى', NULL, 'And indeed, to us belongs the Hereafter and the first [life].', 'Dan sesungguhnya Kamilah yang menguasai hari akhirat dan alam dunia.', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 4, NULL),
(92, 14, 'فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', 'فانذرتكم نارا تلظى', NULL, 'So I have warned you of a Fire which is blazing.', 'Maka (serentak dengan memberi hidayah petunjuk) Aku juga telah memberi amaran mengingatkan kamu akan api neraka yang marak menjulang,', FALSE, NULL, NULL, 595, 30, 238, 534, FALSE, 3, NULL),
(92, 15, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', 'لا يصلاها الا الاشقى', NULL, 'None will [enter to] burn therein except the most wretched one', 'Yang tidak akan menderita bakarannya melainkan orang yang sungguh celaka, -', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 4, NULL),
(92, 16, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', 'الذي كذب وتولى', NULL, 'Who had denied and turned away.', 'Yang telah mendustakan (kebenaran) dan berpaling ingkar.', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 3, NULL),
(92, 17, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', 'وسيجنبها الاتقى', NULL, 'But the righteous one will avoid it –', 'Dan (sebaliknya) akan dijauhkan (azab neraka) itu daripada orang yang sungguh bertaqwa, -', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 2, NULL),
(92, 18, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', 'الذي يؤتي ماله يتزكى', NULL, '[He] who gives [from] his wealth to purify himself', 'Yang mendermakan hartanya dengan tujuan membersihkan dirinya dan hartabendanya,', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 4, NULL),
(92, 19, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ', 'وما لاحد عنده من نعمة تجزى', NULL, 'And not [giving] for anyone who has [done him] a favor to be rewarded –', 'Sedang ia tidak menanggung budi sesiapapun, yang patut di balas,', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 6, NULL),
(92, 20, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', 'الا ابتغاء وجه ربه الاعلى', NULL, 'But only seeking the face [i.e., acceptance] of his Lord, Most High.', 'Hanyalah mengharapkan keredaan Tuhannya Yang Maha Tinggi;', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 5, NULL),
(92, 21, 'وَلَسَوْفَ يَرْضَىٰ', 'وَلَسَوْفَ يَرْضَىٰ', NULL, 'And he is going to be satisfied.', 'Dan demi sesungguhnya, ia tetap akan berpuas hati (pada hari akhirat, dengan mendapat segala yang diharapkannya).', FALSE, NULL, NULL, 596, 30, 238, 534, FALSE, 0, NULL),
(93, 1, 'وَٱلضُّحَىٰ', 'والضحى', NULL, 'By the morning brightness', 'Demi waktu dhuha,', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 1, NULL),
(93, 2, 'وَٱلَّيْلِ إِذَا سَجَىٰ', 'والليل اذا سجى', NULL, 'And [by] the night when it covers with darkness,', 'Dan malam apabila ia sunyi-sepi -', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 3, NULL),
(93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'ما ودعك ربك وما قلى', NULL, 'Your Lord has not taken leave of you, [O Muḥammad], nor has He detested [you].', '(Bahawa) Tuhanmu (wahai Muhammad) tidak meninggalkanmu, dan Ia tidak benci (kepadamu, sebagaimana yang dituduh oleh kaum musyrik).', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 5, NULL),
(93, 4, 'وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ', 'وللاخرة خير لك من الاولى', NULL, 'And the Hereafter is better for you than the first [life].', 'Dan sesungguhnya kesudahan keaadaanmu adalah lebih baik bagimu daripada permulaannya.', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 5, NULL),
(93, 5, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 'ولسوف يعطيك ربك فترضى', NULL, 'And your Lord is going to give you, and you will be satisfied.', 'Dan sesungguhnya Tuhanmu akan memberikanmu (kejayaan dan kebahagiaan di dunia dan di akhirat) sehingga engkau reda - berpuas hati.', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 4, NULL),
(93, 6, 'أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ', 'الم يجدك يتيما فاوى', NULL, 'Did He not find you an orphan and give [you] refuge?', 'Bukankah dia mendapati engkau yatim piatu, lalu la memberikan perlindungan?', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 4, NULL),
(93, 7, 'وَوَجَدَكَ ضَآلًّا فَهَدَىٰ', 'ووجدك ضالا فهدى', NULL, 'And He found you lost and guided [you],', 'Dan didapatiNya engkau mencari-cari (jalan yang benar), lalu Ia memberikan hidayah petunjuk (dengan wahyu - Al-Quran)?', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 3, NULL),
(93, 8, 'وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ', 'ووجدك عائلا فاغنى', NULL, 'And He found you poor and made [you] self-sufficient.', 'Dan didapatiNya engkau miskin, lalu Ia memberikan kekayaan?', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 3, NULL),
(93, 9, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', 'فاما اليتيم فلا تقهر', NULL, 'So as for the orphan, do not oppress [him].', 'Oleh itu, adapun anak yatim maka janganlah engkau berlaku kasar terhadapnya,', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 4, NULL),
(93, 10, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', 'واما السائل فلا تنهر', NULL, 'And as for the petitioner, do not repel [him].', 'Adapun orang yang meminta (bantuan pimpinan) maka janganlah engkau tengking herdik;', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 4, NULL),
(93, 11, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 'واما بنعمة ربك فحدث', NULL, 'But as for the favor of your Lord, report [it].', 'Adapun nikmat Tuhanmu, maka hendaklah engkau sebut-sebutkan (dan zahirkan) sebagai bersyukur kepadaNya.', FALSE, NULL, NULL, 596, 30, 238, 535, FALSE, 4, NULL),
(94, 1, 'أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'الم نشرح لك صدرك', NULL, 'Did We not expand for you, [O Muḥammad], your breast?', 'Bukankah Kami telah melapangkan bagimu: dadamu (wahai Muhammad serta mengisinya dengan iman dan hidayah petunjuk)?', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 4, NULL),
(94, 2, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'ووضعنا عنك وزرك', NULL, 'And We removed from you your burden', 'Dan Kami telah meringankan daripadamu: bebanmu (menyiarkan Islam) -', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 3, NULL),
(94, 3, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', 'الذي انقض ظهرك', NULL, 'Which had weighed upon your back', 'Yang memberati tanggunganmu, (dengan memberikan berbagai kemudahan dalam melaksanakannya)?', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 3, NULL),
(94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', 'ورفعنا لك ذكرك', NULL, 'And raised high for you your repute.', 'Dan Kami telah meninggikan bagimu: sebutan namamu (dengan mengurniakan pangkat Nabi dan berbagai kemuliaan)?', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 3, NULL),
(94, 5, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'فان مع العسر يسرا', NULL, 'For indeed, with hardship [will be] ease [i.e., relief].', 'Oleh itu, maka (tetapkanlah kepercayaanmu) bahawa sesungguhnya tiap-tiap kesukaran disertai kemudahan,', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 4, NULL),
(94, 6, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'ان مع العسر يسرا', NULL, 'Indeed, with hardship [will be] ease.', '(Sekali lagi ditegaskan): bahawa sesungguhnya tiap-tiap kesukaran disertai kemudahan.', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 4, NULL),
(94, 7, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', 'فاذا فرغت فانصب', NULL, 'So when you have finished [your duties], then stand up [for worship].', 'Kemudian apabila engkau telah selesai (daripada sesuatu amal soleh), maka bersungguh-sungguhlah engkau berusaha (mengerjakan amal soleh yang lain),', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 3, NULL),
(94, 8, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 'والى ربك فارغب', NULL, 'And to your Lord direct [your] longing.', 'Dan kepada Tuhanmu sahaja hendaklah engkau memohon (apa yang engkau gemar dan ingini).', FALSE, NULL, NULL, 596, 30, 239, 536, FALSE, 3, NULL),
(95, 1, 'وَٱلتِّينِ وَٱلزَّيْتُونِ', 'والتين والزيتون', NULL, 'By the fig and the olive', 'Demi buah Tiin dan Zaitun,', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 2, NULL),
(95, 2, 'وَطُورِ سِينِينَ', 'وطور سينين', NULL, 'And [by] Mount Sinai', 'Dan Gunung Tursina,', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 2, NULL),
(95, 3, 'وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', 'وهذا البلد الامين', NULL, 'And [by] this secure city [i.e., Makkah],', 'Serta negeri (Makkah) yang aman ini, -', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 3, NULL),
(95, 4, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ', 'لقد خلقنا الانسان في احسن تقويم', NULL, 'We have certainly created man in the best of stature;', 'Sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya (dan berkelengkapan sesuai dengan keadaannya).', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 6, NULL),
(95, 5, 'ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ', 'ثم رددناه اسفل سافلين', NULL, 'Then We return him to the lowest of the low,', 'Kemudian (jika ia panjang umur sehingga tua atau menyalahgunakan kelengkapan itu), Kami kembalikan dia ke serendah-rendah peringkat orang-orang yang rendah,', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 4, NULL),
(95, 6, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'الا الذين امنوا وعملوا الصالحات فلهم اجر غير ممنون', NULL, 'Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.', 'Kecuali orang-orang yang beriman dan beramal soleh, maka mereka beroleh pahala yang tidak putus-putus.', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 9, NULL),
(95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', 'فما يكذبك بعد بالدين', NULL, 'So what yet causes you to deny the Recompense?', '(Jika demikian kekuasaanKu), maka apa pula yang menjadikan engkau seorang pendusta, (berkata tidak benar) mengenai hari pembalasan, sesudah (ternyata dalil-dalil yang membuktikan kekuasaanKu mengadakan hari pembalasan) itu?', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 4, NULL),
(95, 8, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ', 'اليس الله باحكم الحاكمين', NULL, 'Is not Allāh the most just of judges?', 'Bukankah Allah (yang demikian kekuasaanNya) seadil-adil Hakim?', FALSE, NULL, NULL, 597, 30, 239, 537, FALSE, 4, NULL),
(96, 1, 'ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'اقرا باسم ربك الذي خلق', NULL, 'Recite in the name of your Lord who created –', 'Bacalah (wahai Muhammad) dengan nama Tuhanmu yang menciptakan (sekalian makhluk),', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 5, NULL),
(96, 2, 'خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ', 'خلق الانسان من علق', NULL, 'Created man from a clinging substance.', 'Ia menciptakan manusia dari sebuku darah beku;', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 4, NULL),
(96, 3, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', 'اقرا وربك الاكرم', NULL, 'Recite, and your Lord is the most Generous -', 'Bacalah, dan Tuhanmu Yang Maha Pemurah, -', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 4, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', 'الذي علم بالقلم', NULL, 'Who taught by the pen –', 'Yang mengajar manusia melalui pena dan tulisan, -', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 5, 'عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ', 'علم الانسان ما لم يعلم', NULL, 'Taught man that which he knew not.', 'Ia mengajarkan manusia apa yang tidak diketahuinya.', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 5, NULL),
(96, 6, 'كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ', 'كلا ان الانسان ليطغى', NULL, 'No! [But] indeed, man transgresses', 'Ingatlah! Sesungguhnya jenis manusia tetap melampaui batas (yang sepatutnya atau yang sewajibnya),', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 4, NULL),
(96, 7, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', 'ان راه استغنى', NULL, 'Because he sees himself self-sufficient.', 'Dengan sebab ia melihat dirinya sudah cukup apa yang dihajatinya.', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 8, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', 'ان الى ربك الرجعى', NULL, 'Indeed, to your Lord is the return.', '(Ingatlah) sesungguhnya kepada Tuhanmu lah tempat kembali (untuk menerima balasan).', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 4, NULL),
(96, 9, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', 'ارايت الذي ينهى', NULL, 'Have you seen the one who forbids', 'Adakah engkau nampak (baiknya) orang yang melarang (dan menghalang) -', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 10, 'عَبْدًا إِذَا صَلَّىٰٓ', 'عبدا اذا صلى', NULL, 'A servant when he prays?', 'Seorang hamba Allah apabila ia mengerjakan sembahyang?', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 11, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', 'ارايت ان كان على الهدى', NULL, 'Have you seen if he is upon guidance', 'Adakah engkau nampak (buruknya) jika ia berada di atas jalan yang betul? -', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 5, NULL),
(96, 12, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', 'او امر بالتقوى', NULL, 'Or enjoins righteousness?', 'Atau ia menyuruh orang bertaqwa (jangan melakukan syirik)?', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 13, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', 'ارايت ان كذب وتولى', NULL, 'Have you seen if he denies and turns away -', 'Adakah engkau nampak (terlepasnya dari azab) jika ia mendustakan (apa yang disampaikan oleh Nabi Muhammad kepadanya) serta ia berpaling ingkar?', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 4, NULL),
(96, 14, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 'الم يعلم بان الله يرى', NULL, 'Does he not know that Allāh sees?', 'Tidakkah ia mengetahui bahawa sesungguhnya Allah melihat (segala amal perbuatannya dan membalasnya)?', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 5, NULL),
(96, 15, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', 'كلا لئن لم ينته لنسفعا بالناصية', NULL, 'No! If he does not desist, We will surely drag him by the forelock –', 'Jangan sekali-kali berlaku derhaka! Demi sesungguhnya jika ia tidak berhenti (dari perbuatannya yang buruk itu), nescaya Kami akan menyentap ubun-ubunnya (dan menyeretnya ke dalam neraka), -', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 6, NULL),
(96, 16, 'نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ', 'ناصية كاذبة خاطئة', NULL, 'A lying, sinning forelock.', 'Ubun-ubun (orang) yang berdusta, yang bersalah.', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 3, NULL),
(96, 17, 'فَلْيَدْعُ نَادِيَهُۥ', 'فليدع ناديه', NULL, 'Then let him call his associates;', 'Kemudian biarlah ia memanggil kumpulannya (untuk menyelamatkannya),', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 2, NULL),
(96, 18, 'سَنَدْعُ ٱلزَّبَانِيَةَ', 'سندع الزبانية', NULL, 'We will call the angels of Hell.', 'Kami pula akan memanggil malaikat Zabaniyah (untuk menyeksanya)!', FALSE, NULL, NULL, 597, 30, 239, 538, FALSE, 2, NULL),
(96, 19, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', 'كلا لا تطعه واسجد واقترب', NULL, 'No! Do not obey him. But prostrate and draw near [to Allāh].', 'Ingatlah! Janganlah engkau (wahai Muhammad) menurut kehendaknya, dan (sebaliknya) sujudlah dan dampingkanlah dirimu kepada Allah (dengan taat dan beramal soleh)!', FALSE, NULL, NULL, 597, 30, 239, 538, TRUE, 5, NULL),
(97, 1, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 'انا انزلناه في ليلة القدر', NULL, 'Indeed, We sent it [i.e., the Qur’ān] down during the Night of Decree.', 'Sesungguhnya Kami telah menurunkan (Al-Quran) ini pada Malam Lailatul-Qadar,', FALSE, NULL, NULL, 598, 30, 239, 539, FALSE, 5, NULL),
(97, 2, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 'وما ادراك ما ليلة القدر', NULL, 'And what can make you know what is the Night of Decree?', 'Dan apa jalannya engkau dapat mengetahui apa dia kebesaran Malam Lailatul-Qadar itu?', FALSE, NULL, NULL, 598, 30, 239, 539, FALSE, 5, NULL),
(97, 3, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', 'ليلة القدر خير من الف شهر', NULL, 'The Night of Decree is better than a thousand months.', 'Malam Lailatul-Qadar lebih baik daripada seribu bulan.', FALSE, NULL, NULL, 598, 30, 239, 539, FALSE, 6, NULL),
(97, 4, 'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', 'تنزل الملائكة والروح فيها باذن ربهم من كل امر', NULL, 'The angels and the Spirit [i.e., Gabriel] descend therein by permission of their Lord for every matter.', 'Pada Malam itu, turun malaikat dan Jibril dengan izin Tuhan mereka, kerana membawa segala perkara (yang ditakdirkan berlakunya pada tahun yang berikut);', FALSE, NULL, NULL, 598, 30, 239, 539, FALSE, 9, NULL),
(97, 5, 'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 'سلام هي حتى مطلع الفجر', NULL, 'Peace it is until the emergence of dawn.', 'Sejahteralah Malam (yang berkat) itu hingga terbit fajar!', FALSE, NULL, NULL, 598, 30, 239, 539, FALSE, 5, NULL),
(98, 1, 'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 'لم يكن الذين كفروا من اهل الكتاب والمشركين منفكين حتى تاتيهم البينة', NULL, 'Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence –', 'Orang-orang yang kafir dari Ahli Kitab (Yahudi dan Nasrani) serta orang-orang musyrik, tidak akan terlepas (dari kepercayaan dan amalan masing-masing) sehingga datang kepada mereka bukti yang jelas nyata, -', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 12, NULL),
(98, 2, 'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً', 'رسول من الله يتلو صحفا مطهرة', NULL, 'A Messenger from Allāh, reciting purified scriptures', 'Iaitu seorang Rasul dari Allah yang membacakan (kepada mereka) Lembaran-lembaran Suci,', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 6, NULL),
(98, 3, 'فِيهَا كُتُبٌ قَيِّمَةٌ', 'فيها كتب قيمة', NULL, 'Within which are correct writings [i.e., rulings and laws].', 'Terkandung di dalamnya pelajaran-pelajaran dan hukum-hukum yang benar.', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 3, NULL),
(98, 4, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 'وما تفرق الذين اوتوا الكتاب الا من بعد ما جاءتهم البينة', NULL, 'Nor did those who were given the Scripture become divided until after there had come to them clear evidence.', 'Dan orang-orang (Yahudi dan Nasrani) yang diberi Kitab (Taurat dan Injil) itu, tidak berpecah-belah melainkan setelah datang kepada mereka bukti yang jelas nyata.', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 11, NULL),
(98, 5, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 'وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة وذلك دين القيمة', NULL, 'And they were not commanded except to worship Allāh, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakāh. And that is the correct religion.', 'Pada hal mereka tidak diperintahkan melainkan supaya menyembah Allah dengan mengikhlaskan ibadat kepadaNya, lagi tetap teguh di atas tauhid; dan supaya mereka mendirikan sembahyang serta memberi zakat. Dan yang demikian itulah Ugama yang benar.', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 16, NULL),
(98, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 'ان الذين كفروا من اهل الكتاب والمشركين في نار جهنم خالدين فيها اولئك هم شر البرية', NULL, 'Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.', 'Sesungguhnya orang-orang yang kafir dari Ahli Kitab dan orang-orang musyrik itu akan ditempatkan di dalam neraka Jahannam, kekalah mereka di dalamnya. Mereka itulah sejahat-jahat makhluk.', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 16, NULL),
(98, 7, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 'ان الذين امنوا وعملوا الصالحات اولئك هم خير البرية', NULL, 'Indeed, they who have believed and done righteous deeds - those are the best of creatures.', 'Seungguhnya orang-orang yang beriman dan beramal soleh, mereka itulah sebaik-baik makhluk.', FALSE, NULL, NULL, 598, 30, 239, 540, FALSE, 9, NULL),
(98, 8, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 'جزاؤهم عند ربهم جنات عدن تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه', NULL, 'Their reward with their Lord will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allāh being pleased with them and they with Him. That is for whoever has feared his Lord.', 'Balasan mereka di sisi Tuhannya ialah syurga Adn (tempat tinggal yang tetap), yang mengalir di bawahnya beberapa sungai; kekalah mereka di dalamnya selama-lamanya; Allah reda akan mereka dan merekapun reda (serta bersyukur) akan nikmat pemberianNya. Balasan yang demikian itu untuk orang-orang yang takut (melanggar perintah) Tuhannya.', FALSE, NULL, NULL, 599, 30, 239, 540, FALSE, 21, NULL),
(99, 1, 'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 'اذا زلزلت الارض زلزالها', NULL, 'When the earth is shaken with its [final] earthquake', 'Apabila bumi digegarkan dengan gegaran yang sedahsyat-dahsyatnya,', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 4, NULL),
(99, 2, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 'واخرجت الارض اثقالها', NULL, 'And the earth discharges its burdens', 'Serta bumi itu mengeluarkan segala isinya,', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 3, NULL),
(99, 3, 'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا', 'وقال الانسان ما لها', NULL, 'And man says, "What is [wrong] with it?" -', 'Dan berkatalah manusia (dengan perasaan gerun); “Apa yang sudah terjadi kepada bumi?”', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 4, NULL),
(99, 4, 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 'يومئذ تحدث اخبارها', NULL, 'That Day, it will report its news', 'Pada hari itu bumipun menceritakan khabar beritanya:', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 3, NULL),
(99, 5, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'بان ربك اوحى لها', NULL, 'Because your Lord has inspired [i.e., commanded] it.', 'Bahawa Tuhanmu telah memerintahnya (berlaku demikian).', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 4, NULL),
(99, 6, 'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ', 'يومئذ يصدر الناس اشتاتا ليروا اعمالهم', NULL, 'That Day, the people will depart separated [into categories] to be shown [the result of] their deeds.', 'Pada hari itu manusia akan keluar berselerak (dari kubur masing-masing) - untuk diperlihatkan kepada mereka (balasan) amal-amal mereka.', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 6, NULL),
(99, 7, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ', 'فمن يعمل مثقال ذرة خيرا يره', NULL, 'So whoever does an atom''s weight of good will see it,', 'Maka sesiapa berbuat kebajikan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 6, NULL),
(99, 8, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ', 'ومن يعمل مثقال ذرة شرا يره', NULL, 'And whoever does an atom''s weight of evil will see it.', 'Dan sesiapa berbuat kejahatan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!', FALSE, NULL, NULL, 599, 30, 239, 541, FALSE, 6, NULL),
(100, 1, 'وَٱلْعَـٰدِيَـٰتِ ضَبْحًا', 'والعاديات ضبحا', NULL, 'By the racers, panting,', 'Demi Kuda Perang yang tangkas berlari dengan kedengaran kencang nafasnya,', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 2, NULL),
(100, 2, 'فَٱلْمُورِيَـٰتِ قَدْحًا', 'فالموريات قدحا', NULL, 'And the producers of sparks [when] striking', 'Serta mencetuskan api dari telapak kakinya,', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 2, NULL),
(100, 3, 'فَٱلْمُغِيرَٰتِ صُبْحًا', 'فالمغيرات صبحا', NULL, 'And the chargers at dawn,', 'Dan meluru menyerbu musuh pada waktu subuh,', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 2, NULL),
(100, 4, 'فَأَثَرْنَ بِهِۦ نَقْعًا', 'فاثرن به نقعا', NULL, 'Stirring up thereby [clouds of] dust,', 'Sehingga menghamburkan debu pada waktu itu,', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 3, NULL),
(100, 5, 'فَوَسَطْنَ بِهِۦ جَمْعًا', 'فوسطن به جمعا', NULL, 'Arriving thereby in the center collectively,', 'Lalu menggempur ketika itu di tengah-tengah kumpulan musuh;', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 3, NULL),
(100, 6, 'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌ', 'ان الانسان لربه لكنود', NULL, 'Indeed mankind, to his Lord, is ungrateful.', 'Sesungguhnya manusia sangat tidak bersyukur akan nikmat Tuhannya.', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 4, NULL),
(100, 7, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', 'وانه على ذلك لشهيد', NULL, 'And indeed, he is to that a witness.', 'Dan sesungguhnya ia (dengan bawaannya) menerangkan dengan jelas keadaan yang demikian;', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 4, NULL),
(100, 8, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 'وانه لحب الخير لشديد', NULL, 'And indeed he is, in love of wealth, intense.', 'Dan sesungguhnya ia melampau sangat sayangkan harta (secara tamak haloba).', FALSE, NULL, NULL, 599, 30, 239, 542, FALSE, 4, NULL),
(100, 9, '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', 'افلا يعلم اذا بعثر ما في القبور', NULL, 'But does he not know that when the contents of the graves are scattered', '(Patutkah ia bersikap demikian?) Tidakkah ia mengetahui (bagaimana keadaan) ketika dibongkarkan segala yang ada dalam kubur?', FALSE, NULL, NULL, 599, 30, 240, 542, FALSE, 7, NULL),
(100, 10, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 'وحصل ما في الصدور', NULL, 'And that within the breasts is obtained,', 'Dan dikumpul serta didedahkan segala yang terpendam dalam dada?', FALSE, NULL, NULL, 600, 30, 240, 542, FALSE, 4, NULL),
(100, 11, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ', 'ان ربهم بهم يومئذ لخبير', NULL, 'Indeed, their Lord with them, that Day, is [fully] Aware.', 'Sesungguhnya Tuhan mereka Maha Mengetahui dengan mendalam tentang (balasan yang diberikanNya kepada) mereka - pada hari itu.', FALSE, NULL, NULL, 600, 30, 240, 542, FALSE, 5, NULL),
(101, 1, 'ٱلْقَارِعَةُ', 'القارعة', NULL, 'The Striking Calamity -', 'Hari yang menggemparkan,', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 1, NULL),
(101, 2, 'مَا ٱلْقَارِعَةُ', 'ما القارعة', NULL, 'What is the Striking Calamity?', 'Apa dia hari yang menggemparkan itu?', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 2, NULL),
(101, 3, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 'وما ادراك ما القارعة', NULL, 'And what can make you know what is the Striking Calamity?', 'Dan apa jalannya engkau dapat mengetahui kedahsyatan hari yang menggemparkan itu? -', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 4, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 'يوم يكون الناس كالفراش المبثوث', NULL, 'It is the Day when people will be like moths, dispersed,', '(Hari itu ialah: hari kiamat), hari manusia menjadi seperti kelkatu yang terbang berkeliaran,', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 5, NULL),
(101, 5, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 'وتكون الجبال كالعهن المنفوش', NULL, 'And the mountains will be like wool, fluffed up.', 'Dan gunung-ganang menjadi seperti bulu yang dibusar berterbangan.', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 6, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'فاما من ثقلت موازينه', NULL, 'Then as for one whose scales are heavy [with good deeds],', 'Setelah berlaku demikian, maka (manusia akan diberikan tempatnya menurut amal masing-masing); adapun orang yang berat timbangan amal baiknya, -', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 7, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 'فهو في عيشة راضية', NULL, 'He will be in a pleasant life.', 'Maka ia berada dalam kehidupan yang senang lenang.', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 8, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'واما من خفت موازينه', NULL, 'But as for one whose scales are light,', 'Sebaliknya orang yang ringan timbangan amal baiknya, -', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 9, 'فَأُمُّهُۥ هَاوِيَةٌ', 'فامه هاوية', NULL, 'His refuge will be an abyss.', 'Maka tempat kembalinya ialah “Haawiyah”', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 2, NULL),
(101, 10, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', 'وما ادراك ما هيه', NULL, 'And what can make you know what that is?', 'Dan apa jalannya engkau dapat mengetahui, apa dia “Haawiyah” itu?', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 4, NULL),
(101, 11, 'نَارٌ حَامِيَةٌۢ', 'نار حامية', NULL, 'It is a Fire, intensely hot.', '(Haawiyah itu ialah): api yang panas membakar.', FALSE, NULL, NULL, 600, 30, 240, 543, FALSE, 2, NULL),
(102, 1, 'أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 'الهاكم التكاثر', NULL, 'Competition in [worldly] increase diverts you', 'Kamu telah dilalaikan (daripada mengerjakan amal bakti) oleh perbuatan berlumba-lumba untuk mendapat dengan sebanyak-banyaknya (harta benda, anak-pinak pangkat dan pengaruh), -', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 2, NULL),
(102, 2, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', 'حتى زرتم المقابر', NULL, 'Until you visit the graveyards.', 'Sehingga kamu masuk kubur.', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 3, NULL),
(102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'كلا سوف تعلمون', NULL, 'No! You are going to know.', 'Jangan sekali-kali (bersikap demikian)! Kamu akan mengetahui kelak (akibatnya yang buruk semasa hendak mati)!', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 3, NULL),
(102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 'ثم كلا سوف تعلمون', NULL, 'Then, no! You are going to know.', 'Sekali lagi (diingatkan): jangan sekali-kali (kamu bersikap demikian)! Kamu akan mengetahui kelak akibatnya yang buruk pada hari kiamat)!', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 4, NULL),
(102, 5, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', 'كلا لو تعلمون علم اليقين', NULL, 'No! If you only knew with knowledge of certainty...', 'Demi sesungguhnya! Kalaulah kamu mengetahui - (apa yang kamu akan hadapi) - dengan pengetahuan yang yakin, (tentulah kamu akan mengerjakan perkara-perkara yang menjadi bekalan kamu untuk hari akhirat).', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 5, NULL),
(102, 6, 'لَتَرَوُنَّ ٱلْجَحِيمَ', 'لترون الجحيم', NULL, 'You will surely see the Hellfire.', '(Ingatlah) demi sesungguhnya! - Kamu akan melihat neraka yang marak menjulang.', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 2, NULL),
(102, 7, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', 'ثم لترونها عين اليقين', NULL, 'Then you will surely see it with the eye of certainty.', 'Selepas itu - demi sesungguhnya! - kamu (wahai orang-orang yang derhaka) akan melihatnya dengan penglihatan yang yakin (semasa kamu dilemparkan ke dalamnya)!', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 4, NULL),
(102, 8, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 'ثم لتسالن يومئذ عن النعيم', NULL, 'Then you will surely be asked that Day about pleasure.', 'Selain dari itu, sesungguhnya kamu akan ditanya pada hari itu, tentang segala nikmat (yang kamu telah menikmatinya)!', FALSE, NULL, NULL, 600, 30, 240, 544, FALSE, 5, NULL),
(103, 1, 'وَٱلْعَصْرِ', 'والعصر', NULL, 'By time,', 'Demi Masa!', FALSE, NULL, NULL, 601, 30, 240, 545, FALSE, 1, NULL),
(103, 2, 'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ', 'ان الانسان لفي خسر', NULL, 'Indeed, mankind is in loss,', 'Sesungguhnya manusia itu dalam kerugian -', FALSE, NULL, NULL, 601, 30, 240, 545, FALSE, 4, NULL),
(103, 3, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', 'الا الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر', NULL, 'Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.', 'Kecuali orang-orang yang beriman dan beramal soleh, dan mereka pula berpesan-pesan dengan kebenaran serta berpesan-pesan dengan sabar.', FALSE, NULL, NULL, 601, 30, 240, 545, FALSE, 9, NULL),
(104, 1, 'وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ', 'ويل لكل همزة لمزة', NULL, 'Woe to every scorner and mocker', 'Kecelakaan besar bagi tiap-tiap pencaci, pengeji,', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 2, 'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ', 'الذي جمع مالا وعدده', NULL, 'Who collects wealth and [continuously] counts it.', 'Yang mengumpulkan harta dan berulang-ulang menghitung kekayaannya;', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 3, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 'يحسب ان ماله اخلده', NULL, 'He thinks that his wealth will make him immortal.', 'Ia menyangka bahawa hartanya itu dapat mengekalkannya (dalam dunia ini)!', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 4, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', 'كلا لينبذن في الحطمة', NULL, 'No! He will surely be thrown into the Crusher.', 'Tidak! Sesungguhnya dia akan dicampakkan ke dalam “Al-Hutamah”.', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 5, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', 'وما ادراك ما الحطمة', NULL, 'And what can make you know what is the Crusher?', 'Dan apa jalannya engkau dapat mengetahui, apa dia “Al-Hutamah” itu?', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 6, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', 'نار الله الموقدة', NULL, 'It is the fire of Allāh, [eternally] fueled,', '(Al-Hutamah) ialah api Allah yang dinyalakan (dengan perintahNya), -', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 3, NULL),
(104, 7, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', 'التي تطلع على الافئدة', NULL, 'Which mounts directed at the hearts.', 'Yang naik menjulang ke hati;', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 4, NULL),
(104, 8, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ', 'انها عليهم مؤصدة', NULL, 'Indeed, it [i.e., Hellfire] will be closed down upon them', 'Sesungguhnnya api neraka itu ditutup rapat atas mereka.', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 3, NULL),
(104, 9, 'فِى عَمَدٍ مُّمَدَّدَةٍۭ', 'في عمد ممددة', NULL, 'In extended columns.', '(Mereka terikat di situ) pada batang-batang palang yang melintang panjang.', FALSE, NULL, NULL, 601, 30, 240, 546, FALSE, 3, NULL),
(105, 1, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ', 'الم تر كيف فعل ربك باصحاب الفيل', NULL, 'Have you not considered, [O Muḥammad], how your Lord dealt with the companions of the elephant?', 'Tidakkah engkau mengetahui bagaimana Tuhanmu telah melakukan kepada angkatan tentera (yang dipimpin oleh pembawa) Gajah, (yang hendak meruntuhkan Kaabah)?', FALSE, NULL, NULL, 601, 30, 240, 547, FALSE, 7, NULL),
(105, 2, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ', 'الم يجعل كيدهم في تضليل', NULL, 'Did He not make their plan into misguidance?', 'Bukankah Tuhanmu telah menjadikan rancangan jahat mereka dalam keadaan yang rugi dan memusnahkan mereka?', FALSE, NULL, NULL, 601, 30, 240, 547, FALSE, 5, NULL),
(105, 3, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', 'وارسل عليهم طيرا ابابيل', NULL, 'And He sent against them birds in flocks,', 'Dan Ia telah menghantarkan kepada mereka (rombongan) burung berpasuk-pasukan, -', FALSE, NULL, NULL, 601, 30, 240, 547, FALSE, 4, NULL),
(105, 4, 'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ', 'ترميهم بحجارة من سجيل', NULL, 'Striking them with stones of hard clay,', 'Yang melontar mereka dengan batu-batu dari sejenis tanah yang dibakar keras, -', FALSE, NULL, NULL, 601, 30, 240, 547, FALSE, 4, NULL),
(105, 5, 'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ', 'فجعلهم كعصف ماكول', NULL, 'And He made them like eaten straw.', 'Lalu Ia menjadikan mereka hancur berkecai seperti daun-daun kayu yang dimakan ulat.', FALSE, NULL, NULL, 601, 30, 240, 547, FALSE, 3, NULL),
(106, 1, 'لِإِيلَـٰفِ قُرَيْشٍ', 'لايلاف قريش', NULL, 'For the accustomed security of the Quraysh -', 'Kerana kebiasaan aman tenteram kaum Quraisy (penduduk Makkah)', FALSE, NULL, NULL, 602, 30, 240, 548, FALSE, 2, NULL),
(106, 2, 'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', 'ايلافهم رحلة الشتاء والصيف', NULL, 'Their accustomed security [in] the caravan of winter and summer -', '(laitu) kebiasaan aman tenteram perjalanan mereka (menjalankan perniagaan) pada musim sejuk (ke negeri Yaman), dan pada musim panas (ke negeri Syam),', FALSE, NULL, NULL, 602, 30, 240, 548, FALSE, 4, NULL),
(106, 3, 'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ', 'فليعبدوا رب هذا البيت', NULL, 'Let them worship the Lord of this House,', 'Maka hendaklah mereka menyembah Tuhan yang menguasai rumah (Kaabah) ini,', FALSE, NULL, NULL, 602, 30, 240, 548, FALSE, 4, NULL),
(106, 4, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ', 'الذي اطعمهم من جوع وامنهم من خوف', NULL, 'Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.', 'Tuhan yang memberi mereka penghidupan: menyelamatkan mereka dari kelaparan, dan mengamankan mereka dari ketakutan.', FALSE, NULL, NULL, 602, 30, 240, 548, FALSE, 7, NULL),
(107, 1, 'أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', 'ارايت الذي يكذب بالدين', NULL, 'Have you seen the one who denies the Recompense?', 'Tahukah engkau akan orang yang mendustakan ugama (meliputi hari pembalasan)?', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 4, NULL),
(107, 2, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', 'فذلك الذي يدع اليتيم', NULL, 'For that is the one who drives away the orphan', 'Orang itu ialah yang menindas serta berlaku zalim kepada anak yatim,', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 4, NULL),
(107, 3, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'ولا يحض على طعام المسكين', NULL, 'And does not encourage the feeding of the poor.', 'Dan ia tidak menggalakkan untuk memberi makanan yang berhak diterima oleh orang miskin.', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 5, NULL),
(107, 4, 'فَوَيْلٌ لِّلْمُصَلِّينَ', 'فويل للمصلين', NULL, 'So woe to those who pray', '(Kalau orang yang demikian dikira dari bilangan orang-orang yang mendustakan ugama), maka kecelakaan besar bagi orang-orang Ahli Sembahyang -', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 2, NULL),
(107, 5, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'الذين هم عن صلاتهم ساهون', NULL, '[But] who are heedless of their prayer -', '(laitu) mereka yang berkeadaan lalai daripada menyempurnakan sembahyangnya;', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 5, NULL),
(107, 6, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', 'الذين هم يراءون', NULL, 'Those who make show [of their deeds]', '(Juga bagi) orang-orang yang berkeadaan riak (bangga diri dalam ibadat dan bawaannya),', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 3, NULL),
(107, 7, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', 'ويمنعون الماعون', NULL, 'And withhold [simple] assistance.', 'Dan orang-orang yang tidak memberi sedikit pertolongan (kepada orang yang berhak mendapatnya).', FALSE, NULL, NULL, 602, 30, 240, 549, FALSE, 2, NULL),
(108, 1, 'إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ', 'انا اعطيناك الكوثر', NULL, 'Indeed, We have granted you, [O Muḥammad], al-Kawthar.', 'Sesungguhnya Kami telah mengurniakan kepadamu (wahai Muhammad) kebaikan yang banyak (di dunia dan di akhirat).', FALSE, NULL, NULL, 602, 30, 240, 550, FALSE, 3, NULL),
(108, 2, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 'فصل لربك وانحر', NULL, 'So pray to your Lord and offer sacrifice [to Him alone].', 'Oleh itu, kerjakanlah sembahyang kerana Tuhanmu semata-mata, dan sembelihlah korban (sebagai bersyukur).', FALSE, NULL, NULL, 602, 30, 240, 550, FALSE, 3, NULL),
(108, 3, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 'ان شانئك هو الابتر', NULL, 'Indeed, your enemy is the one cut off.', 'Sesungguhnya orang yang bencikan engkau, Dia lah yang terputus (dari mendapat sebarang perkara yang diingininya).', FALSE, NULL, NULL, 602, 30, 240, 550, FALSE, 4, NULL),
(109, 1, 'قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ', 'قل يا ايها الكافرون', NULL, 'Say, "O disbelievers,', 'Katakanlah (wahai Muhammad): “Hai orang-orang kafir!', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 3, NULL),
(109, 2, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'لا اعبد ما تعبدون', NULL, 'I do not worship what you worship.', '“Aku tidak akan menyembah apa yang kamu sembah.', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 4, NULL),
(109, 3, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 'ولا انتم عابدون ما اعبد', NULL, 'Nor are you worshippers of what I worship.', '“Dan kamu tidak mahu menyembah (Allah) yang aku sembah.', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 5, NULL),
(109, 4, 'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ', 'ولا انا عابد ما عبدتم', NULL, 'Nor will I be a worshipper of what you worship.', '“Dan aku tidak akan beribadat secara kamu beribadat.', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 5, NULL),
(109, 5, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 'ولا انتم عابدون ما اعبد', NULL, 'Nor will you be worshippers of what I worship.', '“Dan kamu pula tidak mahu beribadat secara aku beribadat.', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 5, NULL),
(109, 6, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 'لكم دينكم ولي دين', NULL, 'For you is your religion, and for me is my religion."', '“Bagi kamu ugama kamu, dan bagiku ugamaku”.', FALSE, NULL, NULL, 603, 30, 240, 551, FALSE, 4, NULL),
(110, 1, 'إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 'اذا جاء نصر الله والفتح', NULL, 'When the victory of Allāh has come and the conquest,', 'Apabila datang pertolongan Allah dan kemenangan (semasa engkau wahai Muhammad berjaya menguasai negeri Makkah), -', FALSE, NULL, NULL, 603, 30, 240, 552, FALSE, 5, NULL),
(110, 2, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا', 'ورايت الناس يدخلون في دين الله افواجا', NULL, 'And you see the people entering into the religion of Allāh in multitudes,', 'Dan engkau melihat manusia masuk dalam ugama Allah beramai-ramai, -', FALSE, NULL, NULL, 603, 30, 240, 552, FALSE, 7, NULL),
(110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', 'فسبح بحمد ربك واستغفره انه كان توابا', NULL, 'Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of Repentance.', 'Maka ucapkanlah tasbih dengan memuji Tuhanmu dan mintalah ampun kepadaNya, sesungguhnya Dia amat menerima taubat.', FALSE, NULL, NULL, 603, 30, 240, 552, FALSE, 7, NULL),
(111, 1, 'تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ', 'تبت يدا ابي لهب وتب', NULL, 'May the hands of Abū Lahab be ruined, and ruined is he.', 'Binasalah kedua-dua tangan Abu lahab, dan binasalah ia bersama!', FALSE, NULL, NULL, 603, 30, 240, 553, FALSE, 5, NULL),
(111, 2, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 'ما اغنى عنه ماله وما كسب', NULL, 'His wealth will not avail him or that which he gained.', 'Hartanya dan segala yang diusahakannya, tidak dapat menolongnya.', FALSE, NULL, NULL, 603, 30, 240, 553, FALSE, 6, NULL),
(111, 3, 'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', 'سيصلى نارا ذات لهب', NULL, 'He will [enter to] burn in a Fire of [blazing] flame', 'Ia akan menderita bakaran api neraka yang marak menjulang.', FALSE, NULL, NULL, 603, 30, 240, 553, FALSE, 4, NULL),
(111, 4, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 'وامراته حمالة الحطب', NULL, 'And his wife [as well] - the carrier of firewood.', 'Dan juga isterinya, seorang perempuan pemunggah kayu api. -', FALSE, NULL, NULL, 603, 30, 240, 553, FALSE, 3, NULL),
(111, 5, 'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ', 'في جيدها حبل من مسد', NULL, 'Around her neck is a rope of [twisted] fiber.', 'Di lehernya sejenis tali, dari tali-tali yang dipintal.', FALSE, NULL, NULL, 603, 30, 240, 553, FALSE, 5, NULL),
(112, 1, 'قُلْ هُوَ ٱللَّهُ أَحَدٌ', 'قل هو الله احد', NULL, 'Say, "He is Allāh, [who is] One,', 'Katakanlah (wahai Muhammad): “(Tuhanku) ialah Allah Yang Maha Esa;', FALSE, NULL, NULL, 604, 30, 240, 554, FALSE, 4, NULL),
(112, 2, 'ٱللَّهُ ٱلصَّمَدُ', 'الله الصمد', NULL, 'Allāh, the Eternal Refuge.', '“Allah Yang menjadi tumpuan sekalian makhluk untuk memohon sebarang hajat;', FALSE, NULL, NULL, 604, 30, 240, 554, FALSE, 2, NULL),
(112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'لم يلد ولم يولد', NULL, 'He neither begets nor is born,', '“Ia tiada beranak, dan Ia pula tidak diperanakkan;', FALSE, NULL, NULL, 604, 30, 240, 554, FALSE, 4, NULL),
(112, 4, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 'ولم يكن له كفوا احد', NULL, 'Nor is there to Him any equivalent."', '“Dan tidak ada sesiapapun yang serupa denganNya”.', FALSE, NULL, NULL, 604, 30, 240, 554, FALSE, 5, NULL),
(113, 1, 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'قل اعوذ برب الفلق', NULL, 'Say, "I seek refuge in the Lord of daybreak', 'Katakanlah (wahai Muhammad); “Aku berlindung kepada (Allah) Tuhan yang menciptakan sekalian makhluk,', FALSE, NULL, NULL, 604, 30, 240, 555, FALSE, 4, NULL),
(113, 2, 'مِن شَرِّ مَا خَلَقَ', 'من شر ما خلق', NULL, 'From the evil of that which He created', '“Dari bencana makhluk-makhluk yang Ia ciptakan;', FALSE, NULL, NULL, 604, 30, 240, 555, FALSE, 4, NULL),
(113, 3, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 'ومن شر غاسق اذا وقب', NULL, 'And from the evil of darkness when it settles', '“Dan dari bahaya gelap apabila ia masuk;', FALSE, NULL, NULL, 604, 30, 240, 555, FALSE, 5, NULL),
(113, 4, 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ', 'ومن شر النفاثات في العقد', NULL, 'And from the evil of the blowers in knots', '“Dan dari kejahatan makhluk-makhluk yang menghembus-hembus pada simpulan-simpulan (dan ikatan-ikatan);', FALSE, NULL, NULL, 604, 30, 240, 555, FALSE, 5, NULL),
(113, 5, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'ومن شر حاسد اذا حسد', NULL, 'And from the evil of an envier when he envies."', '“Dan dari kejahatan orang yang dengki apabila ia melakukan dengkinya”.', FALSE, NULL, NULL, 604, 30, 240, 555, FALSE, 5, NULL),
(114, 1, 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'قل اعوذ برب الناس', NULL, 'Say, "I seek refuge in the Lord of mankind,', 'Katakanlah (wahai Muhammad): “Aku berlindung kepada (Allah) Pemulihara sekalian manusia.', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 4, NULL),
(114, 2, 'مَلِكِ ٱلنَّاسِ', 'ملك الناس', NULL, 'The Sovereign of mankind,', '“Yang Menguasai sekalian manusia,', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 2, NULL),
(114, 3, 'إِلَـٰهِ ٱلنَّاسِ', 'اله الناس', NULL, 'The God of mankind,', '“Tuhan yang berhak disembah oleh sekalian manusia,', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 2, NULL),
(114, 4, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 'من شر الوسواس الخناس', NULL, 'From the evil of the retreating whisperer -', '“Dari kejahatan pembisik penghasut yang timbul tenggelam, -', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 4, NULL),
(114, 5, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 'الذي يوسوس في صدور الناس', NULL, 'Who whispers [evil] into the breasts of mankind -', '“Yang melemparkan bisikan dan hasutannya ke dalam hati manusia, -', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 5, NULL),
(114, 6, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 'من الجنة والناس', NULL, 'From among the jinn and mankind."', '“(Iaitu pembisik dan penghasut) dari kalangan jin dan manusia”.', FALSE, NULL, NULL, 604, 30, 240, 556, FALSE, 3, NULL);
