-- Miftah Supabase Seed Data
-- Generated from QUL data + tanzil.net metadata + BM translations
-- Run AFTER 001_initial_schema.sql migration
BEGIN;

-- Surahs (114)

-- Ayat
-- Total: 6236 ayat (6236 with Arabic, 6236 with page mapping)

-- Update juz_start, page_start, page_end for each surah
UPDATE surahs SET
  juz_start = sub.juz_start,
  page_start = sub.page_start,
  page_end = sub.page_end
FROM (
  SELECT surah_id,
    MIN(juz_number) FILTER (WHERE juz_number > 0) AS juz_start,
    MIN(page_number) FILTER (WHERE page_number > 0) AS page_start,
    MAX(page_number) FILTER (WHERE page_number > 0) AS page_end
  FROM ayat GROUP BY surah_id
) sub
WHERE surahs.id = sub.surah_id;

-- Words
-- Total: 8354 unique words

-- Word Occurrences
-- Total: 20298

-- Reset sequences
SELECT setval('ayat_id_seq', (SELECT MAX(id) FROM ayat));
SELECT setval('words_id_seq', (SELECT MAX(id) FROM words));
SELECT setval('word_occurrences_id_seq', (SELECT MAX(id) FROM word_occurrences));

COMMIT;